INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Im Anfang schuf Gott die Himmel und die Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Und die Erde war wüst und leer, und Finsternis war über der Tiefe; und der Geist Gottes schwebte über den Wassern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Und Gott sprach: Es werde Licht! und es ward Licht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Und Gott sah das Licht, daß es gut war; und Gott schied das Licht von der Finsternis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Und Gott nannte das Licht Tag, und die Finsternis nannte er Nacht. Und es ward Abend und es ward Morgen: erster Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Und Gott sprach: Es werde eine Ausdehnung inmitten der Wasser, und sie scheide die Wasser von den Wassern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Und Gott machte die Ausdehnung und schied die Wasser, welche unterhalb der Ausdehnung, von den Wassern, die oberhalb der Ausdehnung sind. Und es ward also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Und Gott nannte die Ausdehnung Himmel. Und es ward Abend und es ward Morgen: zweiter Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Und Gott sprach: Es sammeln sich die Wasser unterhalb des Himmels an einen Ort, und es werde sichtbar das Trockene! Und es ward also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Und Gott nannte das Trockene Erde, und die Sammlung der Wasser nannte er Meere. Und Gott sah, daß es gut war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Und Gott sprach: Die Erde lasse Gras hervorsprossen, Kraut, das Samen hervorbringe, Fruchtbäume, die Frucht tragen nach ihrer Art, in welcher ihr Same sei auf der Erde! Und es ward also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Und die Erde brachte Gras hervor, Kraut, das Samen hervorbringt nach seiner Art, und Bäume, die Frucht tragen, in welcher ihr Same ist nach ihrer Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Und es ward Abend und es ward Morgen: dritter Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Und Gott sprach: Es werden Lichter an der Ausdehnung des Himmels, um den Tag von der Nacht zu scheiden, und sie seien zu Zeichen und zur Bestimmung von Zeiten und Tagen und Jahren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'und sie seien zu Lichtern an der Ausdehnung des Himmels, um auf die Erde zu leuchten! Und es ward also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Und Gott machte die zwei großen Lichter: das große Licht zur Beherrschung des Tages, und das kleine Licht zur Beherrschung der Nacht, und die Sterne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Und Gott setzte sie an die Ausdehnung des Himmels, um auf die Erde zu leuchten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'und um zu herrschen am Tage und in der Nacht und das Licht von der Finsternis zu scheiden. Und Gott sah, daß es gut war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Und es ward Abend und es ward Morgen: vierter Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Und Gott sprach: Es wimmeln die Wasser vom Gewimmel lebendiger Wesen, und Gevögel fliege über der Erde angesichts der Ausdehnung des Himmels!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Und Gott schuf die großen Seeungeheuer und jedes sich regende, lebendige Wesen, wovon die Wasser wimmeln, nach ihrer Art, und alles geflügelte Gevögel nach seiner Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Und Gott segnete sie und sprach: Seid fruchtbar und mehret euch und füllet die Wasser in den Meeren, und das Gevögel mehre sich auf der Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Und es ward Abend und es ward Morgen: fünfter Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Und Gott sprach: Die Erde bringe hervor lebendige Wesen nach ihrer Art: Vieh und Gewürm und Getier der Erde nach seiner Art! Und es ward also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Und Gott machte das Getier der Erde nach seiner Art, und das Vieh nach seiner Art, und alles, was sich auf dem Erdboden regt, nach seiner Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Und Gott sprach: Lasset uns Menschen machen in unserem Bilde, nach unserem Gleichnis; und sie sollen herrschen über die Fische des Meeres und über das Gevögel des Himmels und über das Vieh und über die ganze Erde und über alles Gewürm, das sich auf der Erde regt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Und Gott schuf den Menschen in seinem Bilde, im Bilde Gottes schuf er ihn; Mann und Weib schuf er sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Und Gott segnete sie, und Gott sprach zu ihnen: Seid fruchtbar und mehret euch und füllet die Erde und machet sie euch untertan; und herrschet über die Fische des Meeres und über das Gevögel des Himmels und über alles Getier, das sich auf der Erde regt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Und Gott sprach: Siehe, ich habe euch gegeben alles samenbringende Kraut, das auf der Fläche der ganzen Erde ist, und jeden Baum, an welchem samenbringende Baumfrucht ist: es soll euch zur Speise sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'und allem Getier der Erde und allem Gevögel des Himmels und allem, was sich auf der Erde regt, in welchem eine lebendige Seele ist, habe ich alles grüne Kraut zur Speise gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Und es ward also. Und Gott sah alles, was er gemacht hatte, und siehe, es war sehr gut. Und es ward Abend und es ward Morgen: der sechste Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'So wurden vollendet der Himmel und die Erde und all ihr Heer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Und Gott hatte am siebten Tage sein Werk vollendet, das er gemacht hatte; und er ruhte am siebten Tage von all seinem Werk, das er gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Und Gott segnete den siebten Tag und heiligte ihn; denn an demselben ruhte er von all seinem Werk, das Gott geschaffen hatte, indem er es machte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Dies ist die Geschichte des Himmels und der Erde, als sie geschaffen wurden, an dem Tage, da Jehova Gott Erde und Himmel machte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'und ehe alles Gesträuch des Feldes auf der Erde war, und ehe alles Kraut des Feldes sproßte; denn Jehova Gott hatte nicht regnen lassen auf die Erde, und kein Mensch war da, um den Erdboden zu bebauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Ein Dunst aber stieg auf von der Erde und befeuchtete die ganze Oberfläche des Erdbodens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Und Jehova Gott bildete den Menschen, Staub von dem Erdboden, und hauchte in seine Nase den Odem des Lebens; und der Mensch wurde eine lebendige Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Und Jehova Gott pflanzte einen Garten in Eden gegen Osten, und er setzte dorthin den Menschen, den er gebildet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Und Jehova Gott ließ aus dem Erdboden allerlei Bäume wachsen, lieblich anzusehen und gut zur Speise; und den Baum des Lebens in der Mitte des Gartens, und den Baum der Erkenntnis des Guten und Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Und ein Strom ging aus von Eden, den Garten zu bewässern; und von dort aus teilte er sich und wurde zu vier Flüssen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Der Name des ersten ist Pison; dieser ist es, der das ganze Land Hawila umfließt, wo das Gold ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'und das Gold dieses Landes ist gut; daselbst ist das Bdellion und der Stein Onyx.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Und der Name des zweiten Flusses: Gihon; dieser ist es, der das ganze Land Kusch umfließt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Und der Name des dritten Flusses: Hiddekel; dieser ist es, der vor Assyrien fließt. Und der vierte Fluß, das ist der Phrath.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Und Jehova Gott nahm den Menschen und setzte ihn in den Garten Eden, ihn zu bebauen und ihn zu bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Und Jehova Gott gebot dem Menschen und sprach: Von jedem Baume des Gartens darfst du nach Belieben essen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'aber von dem Baume der Erkenntnis des Guten und Bösen, davon sollst du nicht essen; denn welches Tages du davon issest, wirst du gewißlich sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Und Jehova Gott sprach: Es ist nicht gut, daß der Mensch allein sei; ich will ihm eine Hilfe machen, seines Gleichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Und Jehova Gott bildete aus dem Erdboden alles Getier des Feldes und alles Gevögel des Himmels, und er brachte sie zu dem Menschen, um zu sehen, wie er sie nennen würde; und wie irgend der Mensch ein lebendiges Wesen nennen würde, so sollte sein Name sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Und der Mensch gab Namen allem Vieh und dem Gevögel des Himmels und allem Getier des Feldes. Aber für Adam fand er keine Hilfe seines Gleichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Und Jehova Gott ließ einen tiefen Schlaf auf den Menschen fallen, und er entschlief. Und er nahm eine von seinen Rippen und verschloß ihre Stelle mit Fleisch;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'und Jehova Gott baute aus der Rippe, die er von dem Menschen genommen hatte, ein Weib, und er brachte sie zu dem Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Und der Mensch sprach: Diese ist einmal Gebein von meinen Gebeinen und Fleisch von meinem Fleische; diese soll Männin heißen, denn vom Manne ist diese genommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Darum wird ein Mann seinen Vater und seine Mutter verlassen und seinem Weibe anhangen, und sie werden ein Fleisch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Und sie waren beide nackt, der Mensch und sein Weib, und sie schämten sich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Und die Schlange war listiger als alles Getier des Feldes, das Jehova Gott gemacht hatte; und sie sprach zu dem Weibe: Hat Gott wirklich gesagt: Ihr sollt nicht essen von jedem Baume des Gartens?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Und das Weib sprach zu der Schlange: Von der Frucht der Bäume des Gartens essen wir;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'aber von der Frucht des Baumes, der in der Mitte des Gartens ist, hat Gott gesagt, davon sollt ihr nicht essen und sie nicht anrühren, auf daß ihr nicht sterbet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Und die Schlange sprach zu dem Weibe: Mit nichten werdet ihr sterben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Sondern Gott weiß, daß, welches Tages ihr davon esset, eure Augen aufgetan werden und ihr sein werdet wie Gott, erkennend Gutes und Böses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Und das Weib sah, daß der Baum gut zur Speise und daß er eine Lust für die Augen und daß der Baum begehrenswert wäre, um Einsicht zu geben; und sie nahm von seiner Frucht und aß, und sie gab auch ihrem Manne mit ihr, und er aß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Da wurden ihrer beider Augen aufgetan, und sie erkannten, daß sie nackt waren; und sie hefteten Feigenblätter zusammen und machten sich Schürzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Und sie hörten die Stimme Jehovas Gottes, der im Garten wandelte bei der Kühle des Tages. Und der Mensch und sein Weib versteckten sich vor dem Angesicht Jehovas Gottes mitten unter die Bäume des Gartens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Und Jehova Gott rief den Menschen und sprach zu ihm: Wo bist du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Und er sprach: Ich hörte deine Stimme im Garten, und ich fürchtete mich, denn ich bin nackt, und ich versteckte mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Und er sprach: Wer hat dir kundgetan, daß du nackt bist? Hast du gegessen von dem Baume, von dem ich dir geboten habe, nicht davon zu essen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Und der Mensch sprach: Das Weib, das du mir beigegeben hast, sie gab mir von dem Baume, und ich aß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Und Jehova Gott sprach zu dem Weibe: Was hast du da getan! Und das Weib sprach: Die Schlange betrog mich, und ich aß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Und Jehova Gott sprach zu der Schlange: Weil du dieses getan hast, sollst du verflucht sein vor allem Vieh und vor allem Getier des Feldes! Auf deinem Bauche sollst du kriechen und Staub fressen alle Tage deines Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Und ich werde Feindschaft setzen zwischen dir und dem Weibe und zwischen deinem Samen und ihrem Samen; er wird dir den Kopf zermalmen, und du, du wirst ihm die Ferse zermalmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Zu dem Weibe sprach er: Ich werde sehr mehren die Mühsal deiner Schwangerschaft, mit Schmerzen sollst du Kinder gebären; und nach deinem Manne wird dein Verlangen sein, er aber wird über dich herrschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Und zu Adam sprach er: Weil du auf die Stimme deines Weibes gehört und gegessen hast von dem Baume, von dem ich dir geboten und gesprochen habe: Du sollst nicht davon essen, so sei der Erdboden verflucht um deinetwillen: mit Mühsal sollst du davon essen alle Tage deines Lebens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'und Dornen und Disteln wird er dir sprossen lassen, und du wirst das Kraut des Feldes essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Im Schweiße deines Angesichts wirst du dein Brot essen, bis du zurückkehrst zur Erde, denn von ihr bist du genommen. Denn Staub bist du, und zum Staube wirst du zurückkehren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Und der Mensch gab seinem Weibe den Namen Eva, denn sie war die Mutter aller Lebendigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Und Jehova Gott machte Adam und seinem Weibe Röcke von Fell und bekleidete sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Und Jehova Gott sprach: Siehe, der Mensch ist geworden wie unser einer, zu erkennen Gutes und Böses; und nun, daß er seine Hand nicht ausstrecke und nehme auch von dem Baume des Lebens und esse und lebe ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Und Jehova Gott schickte ihn aus dem Garten Eden hinaus, um den Erdboden zu bebauen, davon er genommen war;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'und er trieb den Menschen aus und ließ lagern gegen Osten vom Garten Eden die Cherubim und die Flamme des kreisenden Schwertes, um den Weg zum Baume des Lebens zu bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Und der Mensch erkannte Eva,sein Weib, und sie ward schwanger und gebar Kain; und sie sprach: Ich habe einen Mann erworben mit Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Und sie gebar ferner seinen Bruder, den Abel. Und Abel wurde ein Schafhirt, und Kain wurde ein Ackerbauer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Und es geschah nach Verlauf einer Zeit, da brachte Kain dem Jehova eine Opfergabe von der Frucht des Erdbodens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'und Abel, auch er brachte von den Erstlingen seiner Herde und von ihrem Fett. Und Jehova blickte auf Abel und auf seine Opfergabe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'aber auf Kain und auf seine Opfergabe blickte er nicht. Und Kain ergrimmte sehr, und sein Antlitz senkte sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Und Jehova sprach zu Kain: Warum bist du ergrimmt, und warum hat sich dein Antlitz gesenkt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Ist es nicht so, daß es sich erhebt, wenn du wohl tust? Und wenn du nicht wohl tust, so lagert die Sünde vor der Tür. Und nach dir wird sein Verlangen sein, du aber wirst über ihn herrschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Und Kain sprach zu seinem Bruder Abel; und es geschah, als sie auf dem Felde waren, da erhob sich Kain wider seinen Bruder Abel und erschlug ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Und Jehova sprach zu Kain: Wo ist dein Bruder Abel? Und er sprach: Ich weiß nicht; bin ich meines Bruders Hüter?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Und er sprach: Was hast du getan! Horch! Das Blut deines Bruders schreit zu mir vom Erdboden her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Und nun, verflucht seiest du von dem Erdboden hinweg, der seinen Mund aufgetan hat, das Blut deines Bruders von deiner Hand zu empfangen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Wenn du den Erdboden bebaust, soll er dir hinfort seine Kraft nicht geben; unstet und flüchtig sollst du sein auf der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Und Kain sprach zu Jehova: Zu groß ist meine Strafe, um sie zu tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Siehe, du hast mich heute von der Fläche des Erdbodens vertrieben, und ich werde verborgen sein vor deinem Angesicht und werde unstet und flüchtig sein auf der Erde; und es wird geschehen: wer irgend mich findet, wird mich erschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Und Jehova sprach zu ihm: Darum, jeder, der Kain erschlägt siebenfältig soll es gerächt werden. Und Jehova machte an Kain ein Zeichen, auf daß ihn nicht erschlüge, wer irgend ihn fände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Und Kain ging weg von dem Angesicht Jehovas und wohnte im Lande Nod, östlich von Eden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Und Kain erkannte sein Weib, und sie ward schwanger und gebar Hanoch. Und er baute eine Stadt und benannte die Stadt nach dem Namen seines Sohnes Hanoch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Und dem Hanoch wurde Irad geboren; und Irad zeugte Mehujael, und Mehujael zeugte Methusael, und Methusael zeugte Lamech.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Und Lamech nahm sich zwei Weiber; der Name der einen war Ada, und der Name der anderen Zilla.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Und Ada gebar Jabal; dieser war der Vater der Zeltbewohner und Herdenbesitzer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Und der Name seines Bruders war Jubal; dieser war der Vater aller derer, welche mit der Laute und der Flöte umgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Und Zilla, auch sie gebar Tubalkain, einen Hämmerer von allerlei Schneidewerkzeug aus Erz und Eisen. Und die Schwester Tubalkains war Naama.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Und Lamech sprach zu seinen Weibern: Ada und Zilla, höret meine Stimme; Weiber Lamechs, horchet auf meine Rede! Einen Mann erschlug ich für meine Wunde und einen Jüngling für meine Strieme!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Wenn Kain siebenfältig gerächt wird, so Lamech siebenundsiebzigfältig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Und Adam erkannte abermals sein Weib, und sie gebar einen Sohn und gab ihm den Namen Seth; denn Gott hat mir einen anderen Samen gesetzt an Stelle Abels, weil Kain ihn erschlagen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Und dem Seth, auch ihm wurde ein Sohn geboren, und er gab ihm den Namen Enos. Damals fing man an, den Namen Jehovas anzurufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Dies ist das Buch von Adams Geschlechtern. An dem Tage, da Gott Adam schuf, machte er ihn im Gleichnis Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Mann und Weib schuf er sie, und er segnete sie und gab ihnen den Namen Mensch, an dem Tage, da sie geschaffen wurden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Und Adam lebte hundertdreißig Jahre und zeugte einen Sohn in seinem Gleichnis, nach seinem Bilde, und gab ihm den Namen Seth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Und die Tage Adams, nachdem er Seth gezeugt hatte, waren achthundert Jahre, und er zeugte Söhne und Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Und alle Tage Adams, die er lebte, waren neunhundertdreißig Jahre, und er starb. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Und Seth lebte hundertfünf Jahre und zeugte Enos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Und Seth lebte, nachdem er Enos gezeugt hatte, achthundertsieben Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Und alle Tage Seths waren neunhundertzwölf Jahre, und er starb. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Und Enos lebte neunzig Jahre und zeugte Kenan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Und Enos lebte, nachdem er Kenan gezeugt hatte, achthundertfünfzehn Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Und alle Tage Enos\' waren neunhundertfünf Jahre, und er starb. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Und Kenan lebte siebzig Jahre und zeugte Mahalalel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Und Kenan lebte, nachdem er Mahalalel gezeugt hatte, achthundertvierzig Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Und alle Tage Kenans waren neunhundertzehn Jahre, und er starb. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Und Mahalalel lebte fünfundsechzig Jahre und zeugte Jered.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Und Mahalalel lebte, nachdem er Jered gezeugt hatte, achthundertdreißig Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Und alle Tage Mahalalels waren achthundertfünfundneunzig Jahre, und er starb. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Und Jered lebte hundertzweiundsechzig Jahre und zeugte Henoch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Und Jered lebte, nachdem er Henoch gezeugt hatte, achthundert Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Und alle Tage Jereds waren neunhundertzweiundsechzig Jahre, und er starb. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Und Henoch lebte fünfundsechzig Jahre und zeugte Methusalah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Und Henoch wandelte mit Gott, nachdem er Methusalah gezeugt hatte, dreihundert Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Und alle Tage Henochs waren dreihundertfünfundsechzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Und Henoch wandelte mit Gott; und er war nicht mehr, denn Gott nahm ihn hinweg. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Und Methusalah lebte hundertsiebenachtzig Jahre und zeugte Lamech.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Und Methusalah lebte, nachdem er Lamech gezeugt hatte, siebenhundertzweiundachtzig Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Und alle Tage Methusalahs waren neunhundertneunundsechzig Jahre, und er starb. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Und Lamech lebte hundertzweiundachtzig Jahre und zeugte einen Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Und er gab ihm den Namen Noah, indem er sprach: Dieser wird uns trösten über unsere Arbeit und über die Mühe unserer Hände wegen des Erdbodens, den Jehova verflucht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Und Lamech lebte, nachdem er Noah gezeugt hatte, fünfhundertfünfundneunzig Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Und alle Tage Lamechs waren siebenhundertsiebenundsiebzig Jahre, und er starb. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Und Noah war fünfhundert Jahre alt; und Noah zeugte Sem, Ham und Japhet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Und es geschah, als die Menschen begannen sich zu mehren auf der Fläche des Erdbodens, und ihnen Töchter geboren wurden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'da sahen die Söhne Gottes, daß die Töchter der Menschen schön waren, und sie nahmen sich zu Weibern, welche sie irgend erwählten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Und Jehova sprach: Mein Geist soll nicht ewiglich mit dem Menschen rechten, da er ja Fleisch ist; und seine Tage seien hundertzwanzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'In jenen Tagen waren die Riesen auf der Erde, und auch nachher, als die Söhne Gottes zu den Töchtern der Menschen eingingen und diese ihnen gebaren. Das sind die Helden, welche von alters her waren, die Männer von Ruhm gewesen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Und Jehova sah, daß des Menschen Bosheit groß war auf Erden und alles Gebilde der Gedanken seines Herzens nur böse den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Und es reute Jehova, daß er den Menschen gemacht hatte auf der Erde, und es schmerzte ihn in sein Herz hinein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Und Jehova sprach: Ich will den Menschen, den ich geschaffen habe, von der Fläche des Erdbodens vertilgen, vom Menschen bis zum Vieh, bis zum Gewürm und bis zum Gevögel des Himmels; denn es reut mich, daß ich sie gemacht habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Noah aber fand Gnade in den Augen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Dies ist die Geschichte Noahs: Noah war ein gerechter, vollkommener Mann unter seinen Zeitgenossen; Noah wandelte mit Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Und Noah zeugte drei Söhne: Sem, Ham und Japhet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Und die Erde war verderbt vor Gott, und die Erde war voll Gewalttat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Und Gott sah die Erde, und siehe, sie war verderbt; denn alles Fleisch hatte seinen Weg verderbt auf Erden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Und Gott sprach zu Noah: Das Ende alles Fleisches ist vor mich gekommen; denn die Erde ist voll Gewalttat durch sie; und siehe, ich will sie verderben mit der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Mache dir eine Arche von Gopherholz; mit Kammern sollst du die Arche machen und sie von innen und von außen mit Harz verpichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Und also sollst du sie machen: Dreihundert Ellen sei die Länge der Arche, fünfzig Ellen ihre Breite und dreißig Ellen ihre Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Eine Lichtöffnung sollst du der Arche machen, und bis zu einer Elle sollst du sie fertigen von oben her; und die Tür der Arche sollst du in ihre Seite setzen; mit einem unteren, zweiten und dritten Stockwerk sollst du sie machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Denn ich, siehe, ich bringe die Wasserflut über die Erde, um alles Fleisch unter dem Himmel zu verderben, in welchem ein Hauch des Lebens ist; alles, was auf der Erde ist, soll verscheiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Aber mit dir will ich meinen Bund errichten, und du sollst in die Arche gehen, du und deine Söhne und dein Weib und die Weiber deiner Söhne mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Und von allem Lebendigen, von allem Fleische, zwei von jeglichem sollst du in die Arche bringen, um sie mit dir am Leben zu erhalten; ein Männliches und ein Weibliches sollen sie sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Von dem Gevögel nach seiner Art und von dem Vieh nach seiner Art, von allem Gewürm des Erdbodens nach seiner Art: zwei von jeglichem sollen zu dir hineingehen, um sie am Leben zu erhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Und du, nimm dir von aller Speise, die gegessen wird und sammle sie bei dir auf, daß sie dir und ihnen zur Nahrung sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Und Noah tat es; nach allem, was Gott ihm geboten hatte, also tat er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Und Jehova sprach zu Noah: Gehe in die Arche, du und dein ganzes Haus; denn dich habe ich gerecht vor mir erfunden in diesem Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Von allem reinen Vieh sollst du sieben und sieben zu dir nehmen, ein Männchen und sein Weibchen; und von dem Vieh, das nicht rein ist, zwei, ein Männchen und sein Weibchen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'auch von dem Gevögel des Himmels sieben und sieben, ein Männliches und ein Weibliches: um Samen am Leben zu erhalten auf der Fläche der ganzen Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Denn in noch sieben Tagen, so lasse ich auf die Erde regnen vierzig Tage und vierzig Nächte und werde vertilgen von der Fläche des Erdbodens alles Bestehende, das ich gemacht habe. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Und Noah tat nach allem, was Jehova ihm geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Und Noah war sechshundert Jahre alt, als die Flut kam, Wasser über die Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Und Noah und seine Söhne und sein Weib und die Weiber seiner Söhne mit ihm gingen in die Arche vor den Wassern der Flut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Von dem reinen Vieh und von dem Vieh, das nicht rein ist, und von dem Gevögel und von allem, was sich auf dem Erdboden regt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'kamen zwei und zwei zu Noah in die Arche, ein Männliches und ein Weibliches, wie Gott dem Noah geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Und es geschah nach sieben Tagen, da kamen die Wasser der Flut über die Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Im sechshundertsten Jahre des Lebens Noahs, im zweiten Monat, am siebzehnten Tage des Monats, an diesem Tage brachen auf alle Quellen der großen Tiefe, und die Fenster des Himmels taten sich auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Und der Regen fiel auf die Erde vierzig Tage und vierzig Nächte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'An ebendemselben Tage gingen Noah und Sem und Ham und Japhet, die Söhne Noahs, und das Weib Noahs und die drei Weiber seiner Söhne mit ihnen in die Arche:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'sie und alles Getier nach seiner Art und alles Vieh nach seiner Art und alles Gewürm, das sich auf der Erde regt, nach seiner Art und alles Gevögel nach seiner Art, jeder Vogel von allerlei Gefieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Und sie gingen zu Noah in die Arche, je zwei und zwei von allem Fleische, in welchem ein Hauch des Lebens war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Und die hineingingen, waren ein Männliches und ein Weibliches von allem Fleische, wie Gott ihm geboten hatte. Und Jehova schloß hinter ihm zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Und die Flut kam vierzig Tage lang über die Erde. Und die Wasser mehrten sich und hoben die Arche empor; und sie erhob sich über die Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Und die Wasser nahmen überhand und mehrten sich sehr auf der Erde; und die Arche fuhr auf der Fläche der Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Und die Wasser nahmen gar sehr überhand auf der Erde, und es wurden bedeckt alle hohen Berge, die unter dem ganzen Himmel sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Fünfzehn Ellen darüber nahmen die Wasser überhand, und die Berge wurden bedeckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Da verschied alles Fleisch, das sich auf der Erde regte, an Gevögel und an Vieh und an Getier und an allem Gewimmel, das auf der Erde wimmelte, und alle Menschen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'alles starb, in dessen Nase ein Odem des Lebenshauches war, von allem, was auf dem Trockenen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Und vertilgt wurde alles Bestehende, das auf der Fläche des Erdbodens war, vom Menschen bis zum Vieh, bis zum Gewürm und bis zum Gevögel des Himmels; und sie wurden vertilgt von der Erde. Und nur Noah blieb übrig und was mit ihm in der Arche war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Und die Wasser hatten überhand auf der Erde hundertfünfzig Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Und Gott gedachte des Noah und alles Getieres und alles Viehes, das mit ihm in der Arche war; und Gott ließ einen Wind über die Erde fahren, und die Wasser sanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Und es wurden verschlossen die Quellen der Tiefe und die Fenster des Himmels, und dem Regen vom Himmel ward gewehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Und die Wasser wichen von der Erde, fort und fort weichend; und die Wasser nahmen ab nach Verlauf von hundertfünfzig Tagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Und im siebten Monat, am siebzehnten Tage des Monats, ruhte die Arche auf dem Gebirge Ararat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Und die Wasser nahmen fort und fort ab bis zum zehnten Monat; im zehnten Monat, am Ersten des Monats, wurden die Spitzen der Berge sichtbar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Und es geschah nach Verlauf von vierzig Tagen, da öffnete Noah das Fenster der Arche, das er gemacht hatte, und ließ den Raben aus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'und der flog hin und wieder, bis die Wasser von der Erde vertrocknet waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Und er ließ die Taube von sich aus, um zu sehen, ob die Wasser sich verlaufen hätten von der Fläche des Erdbodens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'aber die Taube fand keinen Ruheplatz für ihren Fuß und kehrte zu ihm in die Arche zurück; denn die Wasser waren noch auf der Fläche der ganzen Erde; und er streckte seine Hand aus und nahm sie und brachte sie zu sich in die Arche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Und er wartete noch sieben andere Tage und ließ die Taube abermals aus der Arche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'und die Taube kam zu ihm um die Abendzeit, und siehe, ein abgerissenes Olivenblatt war in ihrem Schnabel. Und Noah erkannte, daß die Wasser sich verlaufen hatten von der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Und er wartete noch sieben andere Tage und ließ die Taube aus; und sie kehrte hinfort nicht wieder zu ihm zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Und es geschah im sechshundertundersten Jahre, im ersten Monat, am Ersten des Monats, da waren die Wasser von der Erde vertrocknet. Und Noah tat die Decke von der Arche und sah: und siehe, die Fläche des Erdbodens war getrocknet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Und im zweiten Monat, am siebenundzwanzigsten Tage des Monats, war die Erde trocken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Und Gott redete zu Noah und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Gehe aus der Arche, du und dein Weib und deine Söhne und die Weiber deiner Söhne mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Alles Getier, das bei dir ist, von allem Fleische, an Gevögel und an Vieh und an allem Gewürm, das sich auf der Erde regt, laß mit dir hinausgehen, daß sie wimmeln auf Erden und fruchtbar seien und sich mehren auf Erden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Und Noah ging hinaus und seine Söhne und sein Weib und die Weiber seiner Söhne mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Alles Getier, alles Gewürm und alles Gevögel, alles was sich auf der Erde regt, nach ihren Arten, gingen aus der Arche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Und Noah baute Jehova einen Altar; und er nahm von allem reinen Vieh und von allem reinen Gevögel und opferte Brandopfer auf dem Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Und Jehova roch den lieblichen Geruch, und Jehova sprach in seinem Herzen: Nicht mehr will ich hinfort den Erdboden verfluchen um des Menschen willen; denn das Dichten des menschlichen Herzens ist böse von seiner Jugend an; und nicht mehr will ich hinfort alles Lebendige schlagen, wie ich getan habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Forthin, alle Tage der Erde, sollen nicht aufhören Saat und Ernte, und Frost und Hitze, und Sommer und Winter, und Tag und Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Und Gott segnete Noah und seine Söhne und sprach zu ihnen: Seid fruchtbar und mehret euch und füllet die Erde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'und die Furcht und der Schrecken vor euch sei auf allem Getier der Erde und auf allem Gevögel des Himmels! Alles, was sich auf dem Erdboden regt, und alle Fische des Meeres, in eure Hände sind sie gegeben:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'alles, was sich regt, was da lebt, soll euch zur Speise sein; wie das grüne Kraut gebe ich es euch alles.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Nur das Fleisch mit seiner Seele, seinem Blute, sollt ihr nicht essen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'und wahrlich, euer Blut, nach euren Seelen, werde ich fordern; von jedem Tiere werde ich es fordern, und von der Hand des Menschen, von der Hand eines jeden, seines Bruders, werde ich die Seele des Menschen fordern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Wer Menschenblut vergießt, durch den Menschen soll sein Blut vergossen werden; denn im Bilde Gottes hat er den Menschen gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Ihr nun, seid fruchtbar und mehret euch, wimmelt auf der Erde und mehret euch auf ihr!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Und Gott sprach zu Noah und zu seinen Söhnen mit ihm und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Und ich, siehe, ich errichte meinen Bund mit euch und mit eurem Samen nach euch;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'und mit jedem lebendigen Wesen, das bei euch ist, an Gevögel, an Vieh und an allem Getier der Erde bei euch, was irgend von allem Getier der Erde aus der Arche gegangen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Und ich errichte meinen Bund mit euch; und nicht mehr soll alles Fleisch ausgerottet werden durch die Wasser der Flut, und keine Flut soll mehr sein, die Erde zu verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Und Gott sprach: Dies ist das Zeichen des Bundes, den ich stifte zwischen mir und euch und jeder lebendigen Seele, die bei euch ist, auf ewige Geschlechter hin:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Meinen Bogen setze ich in die Wolken, und er soll das Zeichen des Bundes sein zwischen mir und der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Und es wird geschehen, wenn ich Wolken über die Erde führe, so soll der Bogen in den Wolken erscheinen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'und ich werde meines Bundes gedenken, der zwischen mir und euch ist und jedem lebendigen Wesen, von allem Fleische; und nicht mehr sollen die Wasser zu einer Flut werden, alles Fleisch zu verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Und der Bogen wird in den Wolken sein; und ich werde ihn ansehen, um zu gedenken des ewigen Bundes zwischen Gott und jedem lebendigen Wesen von allem Fleische, das auf Erden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Und Gott sprach zu Noah: Das ist das Zeichen des Bundes, den ich errichtet habe zwischen mir und allem Fleische, das auf Erden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Und die Söhne Noahs, die aus der Arche gingen, waren Sem und Ham und Japhet; und Ham ist der Vater Kanaans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Diese drei sind die Söhne Noahs und von diesen aus ist die ganze Erde bevölkert worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Und Noah fing an ein Ackersmann zu werden und pflanzte einen Weinberg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Und er trank von dem Weine und ward trunken, und er entblößte sich in seinem Zelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Und Ham, der Vater Kanaans, sah die Blöße seines Vaters und berichtete es seinen beiden Brüdern draußen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Da nahmen Sem und Japhet das Obergewand und legten es beide auf ihre Schultern und gingen rücklings und bedeckten die Blöße ihres Vaters; und ihre Angesichter waren abgewandt, und sie sahen die Blöße ihres Vaters nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Und Noah erwachte von seinem Weine und erfuhr, was sein jüngster Sohn ihm getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Und er sprach: Verflucht sei Kanaan! Ein Knecht der Knechte sei er seinen Brüdern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Und er sprach: Gepriesen sei Jehova, der Gott Sems; und Kanaan sei sein Knecht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Weit mache es Gott dem Japhet, und er wohne in den Zelten Sems; und Kanaan sei sein Knecht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Und Noah lebte nach der Flut dreihundertfünfzig Jahre;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'und alle Tage Noahs waren neunhundertfünfzig Jahre, und er starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Und dies sind die Geschlechter der Söhne Noahs, Sem, Ham und Japhet: es wurden ihnen Söhne geboren nach der Flut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Die Söhne Japhets: Gomer und Magog und Madai und Jawan und Tubal und Mesech und Tiras.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Und die Söhne Gomers: Askenas und Riphat und Togarma.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Und die Söhne Jawans: Elisa und Tarsis, die Kittim und die Dodanim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Von diesen aus verteilten sich die Bewohner der Inseln der Nationen in ihren Ländern, eine jede nach ihrer Sprache, nach ihren Familien, in ihren Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Und die Söhne Hams: Kusch und Mizraim und Put und Kanaan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Und die Söhne Kuschs: Seba und Hawila und Sabta und Raghma und Sabteka. Und die Söhne Raghmas: Scheba und Dedan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Und Kusch zeugte Nimrod; der fing an, ein Gewaltiger zu sein auf der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Er war ein gewaltiger Jäger vor Jehova; darum sagt man: Wie Nimrod, ein gewaltiger Jäger vor Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Und der Anfang seines Reiches war Babel und Erek und Akkad und Kalne im Lande Sinear.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Von diesem Lande zog er aus nach Assur und baute Ninive und Rechobot-Ir und Kalach,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'und Resen zwischen Ninive und Kalach: das ist die große Stadt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Und Mizraim zeugte die Ludim und die Anamim und die Lehabim und die Naphtuchim');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'und die Pathrusim und die Kasluchim (von welchen die Philister ausgegangen sind,) und die Kaphtorim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Und Kanaan zeugte Zidon, seinen Erstgeborenen, und Heth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'und den Jebusiter und den Amoriter und den Girgasiter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'und den Hewiter und den Arkiter und den Siniter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'und den Arwaditer und den Zemariter und den Hamathiter. Und nachher haben sich die Familien der Kanaaniter zerstreut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Und das Gebiet der Kanaaniter erstreckte sich von Zidon nach Gerar hin, bis Gasa; nach Sodom und Gomorra und Adama und Zeboim hin, bis Lescha. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Das sind die Söhne Hams nach ihren Familien, nach ihren Sprachen, in ihren Ländern, in ihren Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Und dem Sem, dem Vater aller Söhne Hebers, dem Bruder Japhets, des ältesten, auch ihm wurden Söhne geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Die Söhne Sems: Elam und Assur und Arpaksad und Lud und Aram.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Und die Söhne Arams: Uz und Hul und Gether und Masch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Und Arpaksad zeugte Schelach, und Schelach zeugte Heber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Und dem Heber wurden zwei Söhne geboren: der Name des einen war Peleg, denn in seinen Tagen wurde die Erde verteilt; und der Name seines Bruders war Joktan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Und Joktan zeugte Almodad und Scheleph und Hazarmaweth und Jerach');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'und Hadoram und Usal und Dikla');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'und Obal und Abimael und Scheba');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'und Ophir und Hawila und Jobab; diese alle waren Söhne Joktans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Und ihr Wohnsitz war von Meschar nach Sephar hin, dem Gebirge des Ostens. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Das sind die Söhne Sems nach ihren Familien, nach ihren Sprachen, in ihren Ländern, nach ihren Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Das sind die Familien der Söhne Noahs nach ihren Geschlechtern, in ihren Nationen; und von diesen aus haben sich nach der Flut die Nationen auf der Erde verteilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Und die ganze Erde hatte eine Sprache und einerlei Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Und es geschah, als sie nach Osten zogen, da fanden sie eine Ebene im Lande Sinear und wohnten daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Und sie sprachen einer zum anderen: Wohlan, laßt uns Ziegel streichen und hart brennen! Und der Ziegel diente ihnen als Stein, und das Erdharz diente ihnen als Mörtel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Und sie sprachen: Wohlan, bauen wir uns eine Stadt und einen Turm, dessen Spitze an den Himmel reiche, und machen wir uns einen Namen, daß wir nicht zerstreut werden über die ganze Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Und Jehova fuhr hernieder, die Stadt und den Turm zu sehen, welche die Menschenkinder bauten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Und Jehova sprach: Siehe, sie sind ein Volk und haben alle eine Sprache, und dies haben sie angefangen zu tun; und nun wird ihnen nichts verwehrt werden, was sie zu tun ersinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Wohlan, laßt uns herniederfahren und ihre Sprache daselbst verwirren, daß sie einer des anderen Sprache nicht verstehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Und Jehova zerstreute sie von dannen über die ganze Erde; und sie hörten auf, die Stadt zu bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Darum gab man ihr den Namen Babel; denn daselbst verwirrte Jehova die Sprache der ganzen Erde, und von dannen zerstreute sie Jehova über die ganze Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Dies sind die Geschlechter Sems: Sem war hundert Jahre alt und zeugte Arpaksad, zwei Jahre nach der Flut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Und Sem lebte, nachdem er Arpaksad gezeugt hatte, fünfhundert Jahre und zeugte Söhne und Töchter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Und Arpaksad lebte fünfunddreißig Jahre und zeugte Schelach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Und Arpaksad lebte, nachdem er Schelach gezeugt hatte, vierhundertdrei Jahre und zeugte Söhne und Töchter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Und Schelach lebte dreißig Jahre und zeugte Heber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Und Schelach lebte, nachdem er Heber gezeugt hatte, vierhundertdrei Jahre und zeugte Söhne und Töchter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Und Heber lebte vierunddreißig Jahre und zeugte Peleg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Und Heber lebte, nachdem er Peleg gezeugt hatte, vierhundertdreißig Jahre und zeugte Söhne und Töchter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Und Peleg lebte dreißig Jahre und zeugte Reghu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Und Peleg lebte, nachdem er Reghu gezeugt hatte, zweihundertneun Jahre und zeugte Söhne und Töchter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Und Reghu lebte zweiunddreißig Jahre und zeugte Serug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Und Reghu lebte, nachdem er Serug gezeugt hatte, zweihundertsieben Jahre und zeugte Söhne und Töchter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Und Serug lebte dreißig Jahre und zeugte Nahor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Und Serug lebte, nachdem er Nahor gezeugt hatte, zweihundert Jahre und zeugte Söhne und Töchter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Und Nahor lebte neunundzwanzig Jahre und zeugte Tarah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Und Nahor lebte, nachdem er Tarah gezeugt hatte, hundertneunzehn Jahre und zeugte Söhne und Töchter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Und Tarah lebte siebzig Jahre und zeugte Abram, Nahor und Haran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Und dies sind die Geschlechter Tarahs: Tarah zeugte Abram, Nahor und Haran; und Haran zeugte Lot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Und Haran starb vor dem Angesicht seines Vaters Tarah, in dem Lande seiner Geburt, zu Ur in Chaldäa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Und Abram und Nahor nahmen sich Weiber; der Name des Weibes Abrams war Sarai, und der Name des Weibes Nahors Milka, die Tochter Harans, des Vaters der Milka und des Vaters der Jiska.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Und Sarai war unfruchtbar, sie hatte kein Kind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Und Tarah nahm seinen Sohn Abram und Lot, den Sohn Harans, seines Sohnes Sohn, und Sarai, seine Schwiegertochter, das Weib seines Sohnes Abram; und sie zogen miteinander aus Ur in Chaldäa, um in das Land Kanaan zu gehen; und sie kamen bis Haran und wohnten daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Und die Tage Tarahs waren zweihundertfünf Jahre, und Tarah starb in Haran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Und Jehova sprach zu Abram: Gehe aus deinem Lande und aus deiner Verwandtschaft und aus deines Vaters Hause, in das Land, das ich dir zeigen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Und ich will dich zu einer großen Nation machen und dich segnen, und ich will deinen Namen groß machen; und du sollst ein Segen sein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Und ich will segnen, die dich segnen, und wer dir flucht, den werde ich verfluchen; und in dir sollen gesegnet werden alle Geschlechter der Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Und Abram ging hin, wie Jehova zu ihm geredet hatte, und Lot ging mit ihm; und Abram war fünfundsiebzig Jahre alt, als er aus Haran zog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Und Abram nahm Sarai, sein Weib, und Lot, seines Bruders Sohn, und alle ihre Habe, die sie erworben, und die Seelen, die sie in Haran gewonnen hatten, und sie zogen aus, um in das Land Kanaan zu gehen; und sie kamen in das Land Kanaan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Und Abram durchzog das Land bis zu dem Orte Sichem, bis zur Terebinthe Mores. Und die Kanaaniter waren damals im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Und Jehova erschien dem Abram und sprach: Deinem Samen will ich dieses Land geben. Und er baute daselbst Jehova, der ihm erschienen war, einen Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Und er brach auf von dannen nach dem Gebirge ostwärts von Bethel und schlug sein Zelt auf, Bethel gegen Westen und Ai gegen Osten; und er baute daselbst Jehova einen Altar und rief den Namen Jehovas an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Und Abram zog fort, immer weiter ziehend, nach dem Süden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Es entstand aber eine Hungersnot im Lande; und Abram zog nach Ägypten hinab, um sich daselbst aufzuhalten, denn die Hungersnot war schwer im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Und es geschah, als er nahe daran war, nach Ägypten zu kommen, da sprach er zu Sarai, seinem Weibe: Siehe doch, ich weiß, daß du ein Weib, schön von Ansehen, bist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'und es wird geschehen, wenn die Ägypter dich sehen, so werden sie sagen: Sie ist sein Weib; und sie werden mich erschlagen und dich leben lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Sage doch, du seiest meine Schwester, auf daß es mir wohlgehe um deinetwillen und meine Seele am Leben bleibe deinethalben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Und es geschah, als Abram in Ägypten ankam, da sahen die Ägypter, daß das Weib sehr schön war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Und die Fürsten des Pharao sahen sie und priesen sie dem Pharao; und das Weib wurde in das Haus des Pharao geholt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Und er tat Abram Gutes um ihretwillen; und er bekam Kleinvieh und Rinder und Esel und Knechte und Mägde und Eselinnen und Kamele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Und Jehova schlug den Pharao und sein Haus mit großen Plagen um Sarais willen, des Weibes Abrams.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Und der Pharao ließ Abram rufen und sprach: Was hast du mir da getan? Warum hast du mir nicht kundgetan, daß sie dein Weib ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Warum hast du gesagt: Sie ist meine Schwester, so daß ich sie mir zum Weibe nahm? Und nun siehe, da ist dein Weib, nimm sie und gehe hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Und der Pharao entbot seinetwegen Männer, und sie geleiteten ihn und sein Weib und alles, was er hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Und Abram zog herauf aus Ägypten, er und sein Weib und alles, was er hatte, und Lot mit ihm, nach dem Süden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Und Abram war sehr reich an Vieh, an Silber und an Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Und er ging auf seinen Zügen vom Süden bis Bethel, bis zu dem Orte, wo im Anfang sein Zelt gewesen war, zwischen Bethel und Ai,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'zu der Stätte des Altars, den er zuvor daselbst gemacht hatte. Und Abram rief daselbst den Namen Jehovas an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Und auch Lot, der mit Abram zog, hatte Kleinvieh und Rinder und Zelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Und das Land ertrug es nicht, daß sie beisammen wohnten; denn ihre Habe war groß, und sie konnten nicht beisammen wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Und es gab Zank zwischen den Hirten von Abrams Vieh und den Hirten von Lots Vieh. Und die Kanaaniter und die Perisiter wohnten damals im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Da sprach Abram zu Lot: Laß doch kein Gezänk sein zwischen mir und dir und zwischen meinen Hirten und deinen Hirten; denn wir sind Brüder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Ist nicht das ganze Land vor dir? Trenne dich doch von mir! Willst du zur Linken, so will ich mich zur Rechten wenden, und willst du zur Rechten, so will ich mich zur Linken wenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Und Lot hob seine Augen auf und sah die ganze Ebene des Jordan, daß sie ganz bewässert war (bevor Jehova Sodom und Gomorra zerstört hatte) gleich dem Garten Jehovas, wie das Land Ägypten, bis nach Zoar hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Und Lot erwählte sich die ganze Ebene des Jordan, und Lot zog ostwärts; und sie trennten sich voneinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram wohnte im Lande Kanaan, und Lot wohnte in den Städten der Ebene und schlug Zelte auf bis nach Sodom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Und die Leute von Sodom waren böse und große Sünder vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Und Jehova sprach zu Abram, nachdem Lot sich von ihm getrennt hatte: Hebe doch deine Augen auf und schaue von dem Orte, wo du bist, gegen Norden und gegen Süden und gegen Osten und gegen Westen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Denn das ganze Land, das du siehst, dir will ich es geben und deinem Samen auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Und ich will deinen Samen machen wie den Staub der Erde, so daß, wenn jemand den Staub der Erde zu zählen vermag, auch dein Same gezählt werden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Mache dich auf und durchwandle das Land nach seiner Länge und nach seiner Breite; denn dir will ich es geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Und Abram schlug Zelte auf, und kam und wohnte unter den Terebinthen Mamres, die bei Hebron sind; und er baute daselbst Jehova einen Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Und es geschah in den Tagen Amraphels, des Königs von Sinear, Ariochs, des Königs von Ellasar, Kedorlaomers, des Königs von Elam, und Thidhals, des Königs von Gojim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'daß sie Krieg führten mit Bera, dem Könige von Sodom, und mit Birscha, dem Könige von Gomorra, Schineab, dem Könige von Adama, und Schemeber, dem Könige von Zeboim, und mit dem Könige von Bela, das ist Zoar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Alle diese verbündeten sich und kamen in das Tal Siddim, das ist das Salzmeer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Zwölf Jahre hatten sie Kedorlaomer gedient, und im dreizehnten Jahre empörten sie sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Und im vierzehnten Jahre kamen Kedorlaomer und die Könige, die mit ihm waren, und schlugen die Rephaim zu Asteroth-Karnaim und die Susim zu Ham und die Emim in der Ebene von Kirjathaim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'und die Horiter auf ihrem Gebirge Seir bis El-Paran, das an der Wüste liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Und sie wandten sich und kamen nach En-Mischpat, das ist Kades; und sie schlugen das ganze Gefilde der Amalekiter und auch die Amoriter, die zu Hazazon-Tamar wohnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Und es zogen aus der König von Sodom und der König von Gomorra und der König von Adama und der König von Zeboim und der König von Bela, das ist Zoar; und sie stellten sich gegen sie in Schlachtordnung auf im Tale Siddim:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'gegen Kedorlaomer, den König von Elam, und Thidhal, den König von Gojim, und Amraphel, den König von Sinear, und Arioch, den König von Ellasar, vier Könige gegen die fünf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Das Tal Siddim war aber voll von Erdharzquellen; und die Könige von Sodom und Gomorra flohen und fielen daselbst, und die übrigen flohen ins Gebirge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Und sie nahmen alle Habe von Sodom und Gomorra und alle ihre Speise und zogen davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Und sie nahmen Lot, Abrams Bruders Sohn, und seine Habe und zogen davon; denn er wohnte in Sodom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Und es kam ein Entronnener und berichtete es Abram, dem Hebräer; er wohnte aber unter den Terebinthen Mamres, des Amoriters, des Bruders von Eskol und des Bruders von Aner, und diese waren Abrams Bundesgenossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Und als Abram hörte, daß sein Bruder gefangen weggeführt war, ließ er seine Geübten, seine Hausgeborenen, ausrücken, dreihundertachtzehn Mann, und jagte ihnen nach bis Dan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Und er teilte sich wider sie des Nachts, er und seine Knechte, und schlug sie und jagte ihnen nach bis Hoba, das zur Linken von Damaskus liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Und er brachte alle Habe zurück; und auch Lot, seinen Bruder, und dessen Habe brachte er zurück, und auch die Weiber und das Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Und als er zurückgekehrt war, nachdem er Kedorlaomer und die Könige, die mit ihm gewesen, geschlagen hatte, zog der König von Sodom aus, ihm entgegen, in das Tal Schawe, das ist das Königstal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Und Melchisedek, König von Salem, brachte Brot und Wein heraus; und er war Priester Gottes, des Höchsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Und er segnete ihn und sprach: Gesegnet sei Abram von Gott, dem Höchsten, der Himmel und Erde besitzt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Und gepriesen sei Gott, der Höchste, der deine Feinde in deine Hand geliefert hat! Und Abram gab ihm den Zehnten von allem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Und der König von Sodom sprach zu Abram: Gib mir die Seelen, und die Habe nimm für dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Und Abram sprach zu dem König von Sodom: Ich hebe meine Hand auf zu Jehova, zu Gott, dem Höchsten, der Himmel und Erde besitzt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Wenn vom Faden bis zum Schuhriemen, ja, wenn ich irgend etwas nehme von dem, was dein ist...!Auf daß du nicht sagest: Ich habe Abram reich gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Nichts für mich! Nur was die Knaben verzehrt haben, und das Teil der Männer, die mit mir gezogen sind: Aner, Eskol und Mamre, die mögen ihr Teil nehmen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Nach diesen Dingen geschah das Wort Jehovas zu Abram in einem Gesicht also: Fürchte dich nicht, Abram; ich bin dir ein Schild, dein sehr großer Lohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Und Abram sprach: Herr, Jehova, was willst du mir geben? Ich gehe ja kinderlos dahin, und der Erbe meines Hauses, das ist Elieser von Damaskus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Und Abram sprach: Siehe, mir hast du keinen Samen gegeben, und siehe, der Sohn meines Hauses wird mich beerben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Und siehe, das Wort Jehovas geschah zu ihm also: Nicht dieser wird dich beerben, sondern der aus deinem Leibe hervorgehen wird, der wird dich beerben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Und er führte ihn hinaus und sprach: Blicke doch gen Himmel und zähle die Sterne, wenn du sie zählen kannst! Und er sprach zu ihm: Also wird dein Same sein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Und er glaubte Jehova; und er rechnete es ihm zur Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Und er sprach zu ihm: Ich bin Jehova, der dich herausgeführt hat aus Ur in Chaldäa, um dir dieses Land zu geben, es zu besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Und er sprach: Herr, Jehova, woran soll ich erkennen, daß ich es besitzen werde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Da sprach er zu ihm: Hole mir eine dreijährige Färse und eine dreijährige Ziege und einen dreijährigen Widder und eine Turteltaube und eine junge Taube.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Und er holte ihm diese alle und zerteilte sie in der Mitte und legte die Hälfte eines jeden der anderen gegenüber; aber das Geflügel zerteilte er nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Und die Raubvögel stürzten auf die Äser herab; und Abram scheuchte sie hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Und es geschah, als die Sonne untergehen wollte, da fiel ein tiefer Schlaf auf Abram; und siehe, Schrecken, dichte Finsternis überfiel ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Und er sprach zu Abram: Gewißlich sollst du wissen, daß dein Same ein Fremdling sein wird in einem Lande, das nicht das ihre ist; und sie werden ihnen dienen, und sie werden sie bedrücken vierhundert Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Aber ich werde die Nation auch richten, welcher sie dienen werden; und danach werden sie ausziehen mit großer Habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Und du, du wirst zu deinen Vätern eingehen in Frieden, wirst begraben werden in gutem Alter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Und im vierten Geschlecht werden sie hierher zurückkehren; denn die Ungerechtigkeit der Amoriter ist bis hierher noch nicht voll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Und es geschah, als die Sonne untergegangen und dichte Finsternis geworden war, siehe da, ein rauchender Ofen und eine Feuerflamme, die zwischen jenen Stücken hindurchfuhr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'An selbigem Tage machte Jehova einen Bund mit Abram und sprach: Deinem Samen gebe ich dieses Land vom Strome Ägyptens bis an den großen Strom, den Strom Phrath:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'die Keniter und die Kenisiter und die Kadmoniter');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'und die Hethiter und die Perisiter und die Rephaim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'und die Amoriter und die Kanaaniter und die Girgasiter und die Jebusiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Und Sarai, Abrams Weib, gebar ihm nicht. Und sie hatte eine ägyptische Magd, und ihr Name war Hagar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Und Sarai sprach zu Abram: Siehe doch, Jehova hat mich verschlossen, daß ich nicht gebäre; gehe doch ein zu meiner Magd, vielleicht werde ich aus ihr erbaut werden. Und Abram hörte auf die Stimme Sarais.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Und Sarai, Abrams Weib, nahm Hagar, die Ägypterin, ihre Magd, nach Verlauf von zehn Jahren, die Abram im Lande Kanaan gewohnt hatte, und gab sie Abram, ihrem Manne, ihm zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Und er ging zu Hagar ein, und sie ward schwanger; und als sie sah, daß sie schwanger war, da wurde ihre Herrin gering in ihren Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Und Sarai sprach zu Abram: Das Unrecht, das mir widerfährt, fällt auf dich! Ich habe meine Magd in deinen Schoß gegeben; und da sie sieht, daß sie schwanger geworden ist, bin ich gering in ihren Augen. Jehova richte zwischen mir und dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Und Abram sprach zu Sarai: Siehe, deine Magd ist in deiner Hand; tue ihr, was gut ist in deinen Augen. Und Sarai behandelte sie hart, und sie floh von ihr hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Und der Engel Jehovas fand sie an einer Wasserquelle in der Wüste, an der Quelle auf dem Wege nach Sur.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Und er sprach: Hagar, Magd Sarais, woher kommst du, und wohin gehst du? Und sie sprach: Ich fliehe hinweg von meiner Herrin Sarai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Und der Engel Jehovas sprach zu ihr: Kehre zu deiner Herrin zurück und demütige dich unter ihre Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Und der Engel Jehovas sprach zu ihr: Ich will sehr mehren deinen Samen, daß er nicht gezählt werden soll vor Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Und der Engel Jehovas sprach zu ihr: Siehe, du bist schwanger und wirst einen Sohn gebären; und du sollst ihm den Namen Ismael geben, denn Jehova hat auf dein Elend gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Und er, er wird ein Wildesel von Mensch sein; seine Hand wider alle und die Hand aller wider ihn, und angesichts aller seiner Brüder wird er wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Da nannte sie Jehova, der zu ihr redete: Du bist ein Gott, der sich schauen läßt! Denn sie sprach: Habe ich nicht auch hier geschaut, nachdem er sich hat schauen lassen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Darum nannte man den Brunnen: Beer-Lachai-Roi; siehe, er ist zwischen Kades und Bered.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Und Hagar gebar dem Abram einen Sohn; und Abram gab seinem Sohne, den Hagar geboren hatte, den Namen Ismael.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Und Abram war sechsundachtzig Jahre alt, als Hagar dem Abram Ismael gebar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Und Abram war neunundneunzig Jahre alt, da erschien Jehova dem Abram und sprach zu ihm: Ich bin Gott, der Allmächtige; wandle vor meinem Angesicht und sei vollkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Und ich will meinen Bund setzen zwischen mir und dir und will dich sehr, sehr mehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Da fiel Abram auf sein Angesicht, und Gott redete mit ihm und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Ich, siehe, mein Bund ist mit dir, und du wirst zum Vater einer Menge Nationen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Und nicht soll hinfort dein Name Abram heißen, sondern Abraham soll dein Name sein; denn zum Vater einer Menge Nationen habe ich dich gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Und ich werde dich sehr, sehr fruchtbar machen, und ich werde dich zu Nationen machen, und Könige sollen aus dir hervorkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Und ich werde meinen Bund errichten zwischen mir und dir und deinen Samen nach dir, nach ihren Geschlechtern, zu einem ewigen Bunde, um dir zum Gott zu sein und deinem Samen nach dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Und ich werde dir und deinem Samen nach dir das Land deiner Fremdlingschaft geben, das ganze Land Kanaan, zum ewigen Besitztum, und ich werde ihr Gott sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Und Gott sprach zu Abraham: Und du, du sollst meinen Bund halten, du und dein Same nach dir, nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Dies ist mein Bund, den ihr halten sollt zwischen mir und euch und deinem Samen nach dir: alles Männliche werde bei euch beschnitten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'und ihr sollt das Fleisch eurer Vorhaut beschneiden. Und das soll das Zeichen des Bundes sein zwischen mir und euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Und acht Tage alt soll alles Männliche bei euch beschnitten werden nach euren Geschlechtern, der Hausgeborene und der für Geld Erkaufte, von allen Fremden, die nicht von deinem Samen sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'es soll gewißlich beschnitten werden dein Hausgeborener und der für dein Geld Erkaufte. Und mein Bund soll an eurem Fleische sein als ein ewiger Bund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Und der unbeschnittene Männliche, der am Fleische seiner Vorhaut nicht beschnitten wird, selbige Seele soll ausgerottet werden aus ihrem Volke; meinen Bund hat er gebrochen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Und Gott sprach zu Abraham: Sarai, dein Weib, sollst du nicht Sarai nennen, sondern Sara soll ihr Name sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Und ich werde sie segnen, und auch von ihr gebe ich dir einen Sohn; und ich werde sie segnen, und sie wird zu Nationen werden; Könige von Völkern sollen aus ihr kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Und Abraham fiel auf sein Angesicht und lachte und sprach in seinem Herzen: Sollte einem Hundertjährigen geboren werden, und sollte Sara, sollte eine Neunzigjährige gebären?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Und Abraham sprach zu Gott: Möchte doch Ismael vor dir leben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Und Gott sprach: Fürwahr, Sara, dein Weib, wird dir einen Sohn gebären, und du sollst ihm den Namen Isaak geben; und ich werde meinen Bund mit ihm errichten zu einem ewigen Bunde für seinen Samen nach ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Und um Ismael habe ich dich erhört: Siehe, ich habe ihn gesegnet und werde ihn fruchtbar machen und ihn sehr, sehr mehren; zwölf Fürsten wird er zeugen, und ich werde ihn zu einer großen Nation machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Aber meinen Bund werde ich mit Isaak errichten, den Sara dir gebären wird um diese bestimmte Zeit im folgenden Jahre. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Und er hörte auf mit ihm zu reden; und Gott fuhr auf von Abraham.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Und Abraham nahm Ismael, seinen Sohn, und alle seine Hausgeborenen und alle mit seinem Geld Erkauften, alles Männliche unter den Hausleuten Abrahams, und beschnitt das Fleisch ihrer Vorhaut an diesem selbigen Tage, wie Gott zu ihm geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Und Abraham war neunundneunzig Jahre alt, als er am Fleische seiner Vorhaut beschnitten wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Und Ismael, sein Sohn, war dreizehn Jahre alt, als er am Fleische seiner Vorhaut beschnitten wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'An diesem selbigen Tage wurde Abraham beschnitten und Ismael, sein Sohn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Und alle Männer seines Hauses, der Hausgeborene und der für Geld Erkaufte, von den Fremden, wurden mit ihm beschnitten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Und Jehova erschien ihm bei den Terebinthen Mamres; und er saß an dem Eingang des Zeltes bei der Hitze des Tages.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Und er hob seine Augen auf und sah: und siehe, drei Männer standen vor ihm; und als er sie sah, lief er ihnen entgegen von dem Eingang des Zeltes und beugte sich nieder zur Erde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'und er sprach: Herr, wenn ich anders Gnade gefunden habe in deinen Augen, so gehe doch nicht an deinem Knechte vorüber!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Es werde doch ein wenig Wasser geholt, und waschet eure Füße; und lagert euch unter dem Baume,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'und ich will einen Bissen Brot holen, und stärket euer Herz; danach möget ihr weitergehen; da ihr nun einmal vorbeigekommen seid bei eurem Knechte. Und sie sprachen: Tue also, wie du geredet hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Da eilte Abraham ins Zelt zu Sara und sprach: Nimm schnell drei Maß Feinmehl, knete und mache Kuchen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Und Abraham lief zu den Rindern und nahm ein Kalb, zart und gut, und gab es dem Knaben; und der beeilte sich, es zuzubereiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Und er holte dicke und süße Milch und das Kalb, das er zubereitet hatte, und setzte es ihnen vor; und er stand vor ihnen unter dem Baume, und sie aßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Und sie sprachen zu ihm: Wo ist Sara, dein Weib? Und er sprach: Siehe, im Zelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Und er sprach: Gewißlich werde ich übers Jahr wieder zu dir kommen, und siehe, Sara, dein Weib, wird einen Sohn haben. Und Sara horchte am Eingang des Zeltes, der hinter ihm war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Und Abraham und Sara waren alt, wohlbetagt; es hatte aufgehört, Sara zu ergehen nach der Weiber Weise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Und Sara lachte in ihrem Innern und sprach: Nachdem ich alt geworden bin, sollte ich Wollust haben? Und mein Herr ist ja alt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Und Jehova sprach zu Abraham: Warum hat Sara denn gelacht und gesagt: Sollte ich auch wirklich gebären, da ich doch alt bin?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Ist für Jehova eine Sache zu wunderbar? Zur bestimmten Zeit übers Jahr werde ich wieder zu dir kommen, und Sara wird einen Sohn haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Und Sara leugnete und sprach: Ich habe nicht gelacht! denn sie fürchtete sich. Er aber sprach: Nein, sondern du hast gelacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Und die Männer erhoben sich von dannen und blickten hin nach Sodom; und Abraham ging mit ihnen, sie zu geleiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Und Jehova sprach: Sollte ich vor Abraham verbergen, was ich tun will?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Wird doch Abraham gewißlich zu einer großen und mächtigen Nation werden, und sollen doch in ihm gesegnet werden alle Nationen der Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Denn ich habe ihn erkannt, auf daß er seinen Kindern und seinem Hause nach ihm befehle, daß sie den Weg Jehovas bewahren, Gerechtigkeit und Recht zu üben, damit Jehova auf Abraham kommen lasse, was er über ihn geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Und Jehova sprach: Weil das Geschrei von Sodom und Gomorra groß, und weil ihre Sünde sehr schwer ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'so will ich doch hinabgehen und sehen, ob sie nach ihrem Geschrei, das vor mich gekommen ist, völlig getan haben; und wenn nicht, so will ich\'s wissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Und die Männer wandten sich von dannen und gingen nach Sodom; Abraham aber blieb noch vor Jehova stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Und Abraham trat hinzu und sprach: Willst du denn den Gerechten mit dem Gesetzlosen wegraffen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Vielleicht sind fünfzig Gerechte innerhalb der Stadt; willst du sie denn wegraffen und dem Orte nicht vergeben um der fünfzig Gerechten willen, die darin sind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Fern sei es von dir, so etwas zu tun, den Gerechten mit dem Gesetzlosen zu töten, so daß der Gerechte sei wie der Gesetzlose; fern sei es von dir! Sollte der Richter der ganzen Erde nicht Recht üben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Und Jehova sprach: Wenn ich in Sodom, innerhalb der Stadt, fünfzig Gerechte finde, so will ich um ihretwillen dem ganzen Orte vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Und Abraham antwortete und sprach: Siehe doch, ich habe mich unterwunden zu dem Herrn zu reden, und ich bin Staub und Asche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Vielleicht mögen an den fünfzig Gerechten fünf fehlen; willst du wegen der fünf die ganze Stadt verderben? Und er sprach: Ich will sie nicht verderben, wenn ich fünfundvierzig daselbst finde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Und er fuhr fort, weiter zu ihm zu reden, und sprach: Vielleicht mögen vierzig daselbst gefunden werden. Und er sprach: Ich will es nicht tun um der vierzig willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Und er sprach: Möge doch der Herr nicht zürnen, und ich will reden. Vielleicht mögen dreißig daselbst gefunden werden. Und er sprach: Ich will es nicht tun, wenn ich dreißig daselbst finde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Und er sprach: Siehe doch, ich habe mich unterwunden, zu dem Herrn zu reden; vielleicht mögen zwanzig daselbst gefunden werden. Und er sprach: Ich will nicht verderben um der zwanzig willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Und er sprach: Möge doch der Herr nicht zürnen, und ich will nur noch diesmal reden. Vielleicht mögen zehn daselbst gefunden werden. Und er sprach: Ich will nicht verderben um der zehn willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Und Jehova ging weg, als er mit Abraham ausgeredet hatte; und Abraham kehrte zurück an seinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Und die beiden Engel kamen am Abend nach Sodom; und Lot saß im Tore Sodoms. Und als Lot sie sah, stand er auf, ihnen entgegen, und beugte sich nieder, mit dem Angesicht zur Erde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'und er sprach: Ach siehe, meine Herren! Kehret doch ein in das Haus eures Knechtes und übernachtet und waschet eure Füße; und ihr machet euch früh auf und gehet eures Weges. Aber sie sprachen: Nein, sondern wir wollen auf dem Platze übernachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Und er drang sehr in sie; und sie kehrten bei ihm ein und kamen in sein Haus. Und er machte ihnen ein Mahl, und er backte ungesäuerte Kuchen, und sie aßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Noch hatten sie sich nicht niedergelegt, da umringten die Männer der Stadt, die Männer von Sodom, das Haus, vom Jüngling bis zum Greise, das ganze Volk insgesamt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Und sie riefen Lot und sprachen zu ihm: Wo sind die Männer, die diese Nacht zu dir gekommen sind? Führe sie zu uns heraus, daß wir sie erkennen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Und Lot trat zu ihnen hinaus an den Eingang und schloß die Tür hinter sich zu;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'und er sprach: Tut doch nicht übel, meine Brüder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Siehe doch, ich habe zwei Töchter, die keinen Mann erkannt haben; laßt mich sie doch zu euch herausbringen, und tut ihnen, wie es gut ist in euren Augen; allein diesen Männern tut nichts, da sie nun einmal unter den Schatten meines Daches gekommen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Aber sie sprachen: Zurück da! Und sie sprachen: Der eine da ist gekommen, als Fremdling hier zu weilen, und will den Richter machen? Nun, wir wollen dir ärger tun als jenen. Und sie drangen hart ein auf den Mann, auf Lot, und traten herzu, die Tür zu erbrechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Und die Männer streckten ihre Hand aus und brachten Lot zu sich herein ins Haus und verschlossen die Tür.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Und die Männer, die am Eingang des Hauses waren, schlugen sie mit Blindheit, vom kleinsten bis zum größten; und sie wurden müde, den Eingang zu finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Und die Männer sprachen zu Lot: Wen du noch hier hast, einen Schwiegersohn und deine Söhne und deine Töchter und wen irgend du in der Stadt hast, führe hinaus aus diesem Orte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Denn wir wollen diesen Ort verderben, weil ihr Geschrei groß geworden ist vor Jehova; und Jehova hat uns gesandt, die Stadt zu verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Und Lot ging hinaus und redete zu seinen Schwiegersöhnen, die seine Töchter genommen hatten, und sprach: Machet euch auf, gehet aus diesem Orte; denn Jehova will die Stadt verderben. Aber er war in den Augen seiner Schwiegersöhne wie einer, der Scherz treibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Und sowie die Morgenröte aufging, da drangen die Engel in Lot und sprachen: Mache dich auf, nimm dein Weib und deine zwei Töchter, die vorhanden sind, damit du nicht weggerafft werdest in der Ungerechtigkeit der Stadt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Und als er zögerte, ergriffen die Männer seine Hand und die Hand seines Weibes und die Hand seiner zwei Töchter, weil Jehova sich seiner erbarmte, und führten ihn hinaus und ließen ihn außerhalb der Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Und es geschah, als sie sie hinausgeführt hatten ins Freie, da sprach er: Rette dich um deines Lebens willen; sieh nicht hinter dich, und bleibe nicht stehen in der ganzen Ebene; rette dich auf das Gebirge, damit du nicht weggerafft werdest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Und Lot sprach zu ihnen: Nicht doch, Herr!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Siehe doch, dein Knecht hat Gnade gefunden in deinen Augen, und du hast deine Güte groß gemacht, die du an mir erwiesen hast, meine Seele am Leben zu erhalten; aber ich kann mich nicht auf das Gebirge retten, es möchte mich das Unglück erhaschen, daß ich stürbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Siehe doch, diese Stadt ist nahe, um dahin zu fliehen, und sie ist klein; laß mich doch dahin mich retten (ist sie nicht klein?), damit meine Seele am Leben bleibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Und er sprach zu ihm: Siehe, auch in diesem Stücke habe ich dich angesehen, daß ich die Stadt nicht umkehre, von der du geredet hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Eile, rette dich dorthin; denn ich kann nichts tun, bis du dorthin gekommen bist. Daher hat man der Stadt den Namen Zoar gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Die Sonne ging auf über der Erde, als Lot in Zoar ankam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Und Jehova ließ auf Sodom und auf Gomorra Schwefel und Feuer regnen von Jehova aus dem Himmel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'und er kehrte diese Städte um und die ganze Ebene und alle Bewohner der Städte und das Gewächs des Erdbodens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Und sein Weib sah sich hinter ihm um und ward zu einer Salzsäule.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Und Abraham machte sich des Morgens früh auf an den Ort, wo er vor Jehova gestanden hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Und er blickte hin nach Sodom und Gomorra und nach dem ganzen Lande der Ebene; und er sah: und siehe, ein Rauch stieg auf von der Erde, wie der Rauch eines Schmelzofens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Und es geschah, als Gott die Städte der Ebene verderbte, da gedachte Gott des Abraham und entsandte Lot mitten aus der Umkehrung, als er die Städte umkehrte, in welchen Lot gewohnt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Und Lot zog hinauf von Zoar und wohnte im Gebirge, und seine beiden Töchter mit ihm; denn er fürchtete sich, in Zoar zu wohnen. Und er wohnte in einer Höhle, er und seine beiden Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Und die Erstgeborene sprach zu der Jüngeren: Unser Vater ist alt, und kein Mann ist im Lande, um zu uns einzugehen nach der Weise aller Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Komm, laß uns unserem Vater Wein zu trinken geben und bei ihm liegen, damit wir von unserem Vater Samen am Leben erhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Und sie gaben ihrem Vater Wein zu trinken in selbiger Nacht, und die Erstgeborene ging hinein und lag bei ihrem Vater; und er wußte weder um ihr Niederlegen noch um ihr Aufstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Und es geschah am Morgen, da sprach die Erstgeborene zu der Jüngeren: Siehe, ich habe gestern Nacht bei meinem Vater gelegen; laß uns ihm auch diese Nacht Wein zu trinken geben, und gehe hinein, liege bei ihm, damit wir von unserem Vater Samen am Leben erhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Und sie gaben auch in selbiger Nacht ihrem Vater Wein zu trinken, und die Jüngere stand auf und lag bei ihm; und er wußte weder um ihr Niederlegen noch um ihr Aufstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Und die beiden Töchter Lots wurden schwanger von ihrem Vater.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Und die Erstgeborene gebar einen Sohn, und sie gab ihm den Namen Moab; dieser ist der Vater der Moabiter bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Und die Jüngere, auch sie gebar einen Sohn, und sie gab ihm den Namen Ben Ammi; dieser ist der Vater der Kinder Ammon bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Und Abraham brach auf von dannen nach dem Lande des Südens und wohnte zwischen Kades und Sur; und er hielt sich auf zu Gerar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Und Abraham sagte von Sara, seinem Weibe: Sie ist meine Schwester. Da sandte Abimelech, der König von Gerar, und ließ Sara holen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Und Gott kam zu Abimelech in einem Traume der Nacht und sprach zu ihm: Siehe, du bist des Todes wegen des Weibes, das du genommen hast; denn sie ist eines Mannes Eheweib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimelech aber hatte sich ihr nicht genaht; und er sprach: Herr, willst du auch eine gerechte Nation töten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Hat er nicht zu mir gesagt: Sie ist meine Schwester? Und auch sie selbst hat gesagt: Er ist mein Bruder. In Lauterkeit meines Herzens und in Unschuld meiner Hände habe ich dies getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Und Gott sprach zu ihm im Traume: Auch ich weiß, daß du in Lauterkeit deines Herzens dies getan hast, und so habe ich dich auch davon abgehalten, gegen mich zu sündigen; darum habe ich dir nicht gestattet, sie zu berühren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Und nun gib das Weib des Mannes zurück; denn er ist ein Prophet und wird für dich bitten, und du wirst am Leben bleiben. Wenn du sie aber nicht zurückgibst, so wisse, daß du gewißlich sterben wirst, du und alles, was dein ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Und Abimelech stand des Morgens früh auf und rief alle seine Knechte und redete alle diese Worte vor ihren Ohren; und die Männer fürchteten sich sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Und Abimelech rief Abraham und sprach zu ihm: Was hast du uns angetan! Und was habe ich wider dich gesündigt, daß du über mich und über mein Reich eine große Sünde gebracht hast? Dinge, die nicht getan werden sollten, hast du mir angetan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Und Abimelech sprach zu Abraham: Was hast du beabsichtigt, daß du dies getan hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Und Abraham sprach: Weil ich mir sagte: Gewiß ist keine Gottesfurcht an diesem Orte, und sie werden mich töten um meines Weibes willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Auch ist sie wahrhaftig meine Schwester, die Tochter meines Vaters, nur nicht die Tochter meiner Mutter; und sie ist mein Weib geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Und es geschah, als Gott mich wandern ließ aus meines Vaters Hause, da sprach ich zu ihr: Dies sei deine Güte, die du mir erweisen mögest; an jedem Orte, wohin wir kommen werden, sage von mir: Er ist mein Bruder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Da nahm Abimelech Kleinvieh und Rinder und Knechte und Mägde und gab sie dem Abraham; und er gab ihm Sara, sein Weib, zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Und Abimelech sprach: Siehe, mein Land ist vor dir; wohne, wo es gut ist in deinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Und zu Sara sprach er: Siehe, ich habe deinem Bruder tausend Silbersekel gegeben; siehe, das sei dir eine Augendecke vor allen, die bei dir sind, und in Bezug auf alles ist die Sache rechtlich geschlichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Und Abraham betete zu Gott; und Gott heilte Abimelech und sein Weib und seine Mägde, so daß sie gebaren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Denn Jehova hatte um Saras, des Weibes Abrahams, willen jeden Mutterleib im Hause Abimelechs gänzlich verschlossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Und Jehova suchte Sara heim, wie er gesagt hatte, und Jehova tat der Sara, wie er geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Und Sara wurde schwanger und gebar dem Abraham einen Sohn in seinem Alter, zu der bestimmten Zeit, von welcher Gott ihm gesagt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Und Abraham gab seinem Sohne, der ihm geboren worden, welchen Sara ihm gebar, den Namen Isaak.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Und Abraham beschnitt Isaak, seinen Sohn, als er acht Tage alt war, wie Gott ihm geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Und Abraham war hundert Jahre alt, als ihm sein Sohn Isaak geboren wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Und Sara sprach: Gott hat mir ein Lachen bereitet; jeder, der es hört, wird mit mir lachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Und sie sprach: Wer hätte Abraham gesagt: Sara säugt Söhne! Denn ich habe ihm einen Sohn geboren in seinem Alter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Und das Kind wuchs und ward entwöhnt; und Abraham machte ein großes Mahl an dem Tage, da Isaak entwöhnt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Und Sara sah den Sohn Hagars, der Ägypterin, den sie dem Abraham geboren hatte, spotten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Und sie sprach zu Abraham: Treibe diese Magd und ihren Sohn hinaus; denn der Sohn dieser Magd soll nicht erben mit meinem Sohne, mit Isaak!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Und die Sache war sehr übel in den Augen Abrahams um seines Sohnes willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Aber Gott sprach zu Abraham: Laß es nicht übel sein in deinen Augen wegen des Knaben und wegen deiner Magd; was immer Sara zu dir sagt, höre auf ihre Stimme; denn in Isaak soll dir ein Same genannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Doch auch den Sohn der Magd werde ich zu einer Nation machen, weil er dein Same ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Und Abraham stand des Morgens früh auf, und er nahm Brot und einen Schlauch Wasser und gab es der Hagar, indem er es auf ihre Schulter legte; und er gab ihr den Knaben und entließ sie. Und sie ging hin und irrte umher in der Wüste von Beerseba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Und als das Wasser im Schlauche ausging, da warf sie das Kind unter einen der Sträucher;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'und sie ging hin und setzte sich gegenüber, einen Bogenschuß weit, denn sie sprach: Daß ich das Sterben des Kindes nicht ansehe! Und sie setzte sich gegenüber und erhob ihre Stimme und weinte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Und Gott hörte die Stimme des Knaben. Und der Engel Gottes rief der Hagar vom Himmel zu und sprach zu ihr: Was ist dir, Hagar? Fürchte dich nicht! Denn Gott hat auf die Stimme des Knaben gehört, da, wo er ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'stehe auf, nimm den Knaben und fasse ihn mit deiner Hand, denn ich will ihn zu einer großen Nation machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Und Gott öffnete ihre Augen, und sie sah einen Wasserbrunnen; und sie ging hin und füllte den Schlauch mit Wasser und tränkte den Knaben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Und Gott war mit dem Knaben, und er wuchs heran; und er wohnte in der Wüste und wurde ein Bogenschütze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Und er wohnte in der Wüste Paran, und seine Mutter nahm ihm ein Weib aus dem Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Und es geschah zu selbiger Zeit, da sprach Abimelech und Pikol, sein Heeroberster, zu Abraham und sagte: Gott ist mit dir in allem, was du tust.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'So schwöre mir nun hier bei Gott, daß du weder an mir noch an meinem Sohne noch an meinem Enkel trüglich handeln wirst! Nach der Güte, die ich dir erwiesen habe, sollst du an mir tun und an dem Lande, in welchem du dich aufhältst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Und Abraham sprach: Ich will schwören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Und Abraham stellte Abimelech zur Rede wegen eines Wasserbrunnens, den Abimelechs Knechte mit Gewalt genommen hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Und Abimelech sprach: Ich weiß nicht, wer das getan hat; weder hast du es mir berichtet, noch habe ich davon gehört außer heute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Da nahm Abraham Kleinvieh und Rinder und gab sie Abimelech, und sie schlossen beide einen Bund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Und Abraham stellte sieben junge Schafe der Herde besonders.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Und Abimelech sprach zu Abraham: Was sollen diese sieben jungen Schafe, die du besonders gestellt hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Und er sprach: Die sieben jungen Schafe sollst du von meiner Hand annehmen, damit es mir zum Zeugnis sei, daß ich diesen Brunnen gegraben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Daher nannte man diesen Ort Beerseba, weil sie beide daselbst geschworen hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'So schlossen sie einen Bund zu Beerseba. Und Abimelech machte sich auf und Pikol, sein Heeroberster, und sie kehrten in das Land der Philister zurück. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Und Abraham pflanzte eine Tamariske zu Beerseba und rief daselbst den Namen Jehovas, des ewigen Gottes, an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Und Abraham hielt sich eine lange Zeit auf im Lande der Philister.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Und es geschah nach diesen Dingen, daß Gott den Abraham versuchte; und er sprach zu ihm: Abraham! Und er sprach: Hier bin ich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Und er sprach: Nimm deinen Sohn, deinen einzigen, den du lieb hast, den Isaak, und ziehe hin in das Land Morija, und opfere ihn daselbst als Brandopfer auf einem der Berge, den ich dir sagen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Und Abraham stand des Morgens früh auf und sattelte seinen Esel und nahm mit sich zwei von seinen Knaben und Isaak, seinen Sohn; und er spaltete Holz zum Brandopfer und machte sich auf und zog hin an den Ort, den Gott ihm gesagt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Am dritten Tage, da erhob Abraham seine Augen und sah den Ort von ferne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Und Abraham sprach zu seinen Knaben: Bleibet ihr hier mit dem Esel; ich aber und der Knabe wollen bis dorthin gehen und anbeten und dann zu euch zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Und Abraham nahm das Holz des Brandopfers und legte es auf Isaak, seinen Sohn; und in seine Hand nahm er das Feuer und das Messer; und sie gingen beide miteinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Und Isaak sprach zu seinem Vater Abraham und sagte: Mein Vater! Und er sprach: Hier bin ich, mein Sohn. Und er sprach: Siehe, das Feuer und das Holz; wo aber ist das Schaf zum Brandopfer?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Und Abraham sprach: Gott wird sich ersehen das Schaf zum Brandopfer, mein Sohn. Und sie gingen beide miteinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Und sie kamen an den Ort, von dem Gott ihm gesagt hatte; und Abraham baute daselbst den Altar und schichtete das Holz; und er band seinen Sohn Isaak und legte ihn auf den Altar oben auf das Holz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Und Abraham streckte seine Hand aus und nahm das Messer, um seinen Sohn zu schlachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Da rief ihm der Engel Jehovas vom Himmel zu und sprach: Abraham, Abraham! Und er sprach: Hier bin ich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Und er sprach: Strecke deine Hand nicht aus nach dem Knaben, und tue ihm gar nichts! Denn nun weiß ich, daß du Gott fürchtest und deinen Sohn, deinen einzigen, mir nicht vorenthalten hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Und Abraham erhob seine Augen und sah, und siehe, da war ein Widder dahinten im Dickicht festgehalten durch seine Hörner; und Abraham ging hin und nahm den Widder und opferte ihn als Brandopfer an seines Sohnes Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Und Abraham gab diesem Orte den Namen: Jehova wird ersehen; daher heutigen Tages gesagt wird: Auf dem Berge Jehovas wird ersehen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Und der Engel Jehovas rief Abraham ein zweites Mal vom Himmel zu');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'und sprach: Ich schwöre bei mir selbst, spricht Jehova, daß, weil du dieses getan und deinen Sohn, deinen einzigen, mir nicht vorenthalten hast,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'ich dich reichlich segnen und deinen Samen sehr mehren werde, wie die Sterne des Himmels und wie der Sand, der am Ufer des Meeres ist; und dein Same wird besitzen das Tor seiner Feinde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'und in deinem Samen werden sich segnen alle Nationen der Erde: darum, daß du meiner Stimme gehorcht hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Und Abraham kehrte zu seinen Knaben zurück, und sie machten sich auf und zogen miteinander nach Beerseba; und Abraham wohnte zu Beerseba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Und es geschah nach diesen Dingen, da wurde dem Abraham berichtet: Siehe, Milka, auch sie hat deinem Bruder Nahor Söhne geboren:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Uz, seinen Erstgeborenen, und Bus, seinen Bruder, und Kemuel, den Vater Arams,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'und Kesed und Haso und Pildasch und Jidlaph und Bethuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, '(Und Bethuel zeugte Rebekka.) Diese acht gebar Milka dem Nahor, dem Bruder Abrahams.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Und sein Kebsweib, namens Reuma, auch sie gebar Tebach und Gacham und Tachasch und Maaka.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Und das Leben Saras war hundertsiebenundzwanzig Jahre; das waren die Lebensjahre Saras.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Und Sara starb zu Kirjath-Arba, das ist Hebron, im Lande Kanaan. Und Abraham kam, um über Sara zu klagen und sie zu beweinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Und Abraham erhob sich weg von seiner Toten und redete zu den Kindern Heth und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Ich bin ein Fremdling und Beisasse bei euch; gebet mir ein Erbbegräbnis bei euch, daß ich meine Tote begrabe vor meinem Angesicht hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Und die Kinder Heth antworteten dem Abraham und sprachen zu ihm:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Höre uns, mein Herr! Du bist ein Fürst Gottes unter uns, begrabe deine Tote in dem auserlesensten unserer Gräber; keiner von uns wird dir sein Grab verwehren, um deine Tote zu begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Da stand Abraham auf und verneigte sich vor dem Volke des Landes, vor den Kindern Heth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'und redete mit ihnen und sprach: Wenn es euer Wille ist, daß ich meine Tote begrabe vor meinem Angesicht hinweg, so höret mich und leget Fürsprache für mich ein bei Ephron, dem Sohne Zohars,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'daß er mir die Höhle von Machpela gebe, die ihm gehört, die am Ende seines Feldes ist; um das volle Geld gebe er sie mir zu einem Erbbegräbnis in eurer Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Ephron aber saß inmitten der Kinder Heth; und Ephron, der Hethiter, antwortete dem Abraham vor den Ohren der Kinder Heth, vor allen, die zum Tore seiner Stadt eingingen, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nein, mein Herr, höre mich! Das Feld gebe ich dir; und die Höhle, die darin ist, dir gebe ich sie; vor den Augen der Kinder meines Volkes gebe ich sie dir; begrabe deine Tote.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Da verneigte sich Abraham vor dem Volke des Landes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'und er redete zu Ephron vor den Ohren des Volkes des Landes und sprach: Doch, wenn du nur auf mich hören wolltest! Ich gebe den Preis des Feldes, nimm ihn von mir; und ich will meine Tote daselbst begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Und Ephron antwortete dem Abraham und sprach zu ihm:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Mein Herr, höre mich! Ein Land von vierhundert Sekel Silber, was ist das zwischen mir und dir? So begrabe deine Tote.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Und Abraham hörte auf Ephron; und Abraham wog dem Ephron das Geld dar, wovon er vor den Ohren der Kinder Heth geredet hatte, vierhundert Sekel Silber, gangbar beim Kaufmann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'So wurde das Feld Ephrons, welches bei Machpela, vor Mamre, lag, das Feld und die Höhle, die darin war, und alle Bäume, die auf dem Felde innerhalb seiner ganzen Grenze ringsum standen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'dem Abraham zum Besitztum bestätigt vor den Augen der Kinder Heth, vor allen, die zum Tore seiner Stadt eingingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Und danach begrub Abraham Sara, sein Weib, in der Höhle des Feldes von Machpela, vor Mamre, das ist Hebron, im Lande Kanaan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'So wurde das Feld und die Höhle, welche darin war, dem Abraham zum Erbbegräbnis bestätigt von seiten der Kinder Heth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Und Abraham war alt, wohlbetagt, und Jehova hatte Abraham gesegnet in allem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Und Abraham sprach zu seinem Knechte, dem ältesten seines Hauses, der alles verwaltete, was er hatte: Lege doch deine Hand unter meine Hüfte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'und ich werde dich schwören lassen bei Jehova, dem Gott des Himmels und dem Gott der Erde, daß du meinem Sohne nicht ein Weib nehmen wirst von den Töchtern der Kanaaniter, in deren Mitte ich wohne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'sondern in mein Land und zu meiner Verwandtschaft sollst du gehen und ein Weib nehmen meinem Sohne, dem Isaak.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Und der Knecht sprach zu ihm: Vielleicht wird das Weib mir nicht in dieses Land folgen wollen; soll ich dann deinen Sohn in das Land zurückbringen, aus welchem du weggezogen bist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Da sprach Abraham zu ihm: Hüte dich, daß du meinen Sohn nicht dorthin zurückbringest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Jehova, der Gott des Himmels, der mich aus dem Hause meines Vaters und aus dem Lande meiner Verwandtschaft genommen und der zu mir geredet und der mir also geschworen hat: Deinem Samen will ich dieses Land geben! der wird seinen Engel vor dir hersenden, daß du meinem Sohne von dannen ein Weib nehmest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Wenn aber das Weib dir nicht folgen will, so bist du dieses meines Eides ledig; nur sollst du meinen Sohn nicht dorthin zurückbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Und der Knecht legte seine Hand unter die Hüfte Abrahams, seines Herrn, und schwur ihm über dieser Sache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Und der Knecht nahm zehn Kamele von den Kamelen seines Herrn, und zog hin; und allerlei Gut seines Herrn hatte er bei sich. Und er machte sich auf und zog nach Mesopotamien, nach der Stadt Nahors.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Und er ließ die Kamele draußen vor der Stadt niederknien beim Wasserbrunnen, zur Abendzeit, zur Zeit, da die Schöpferinnen herauskommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Und er sprach: Jehova, Gott meines Herrn Abraham, laß es mir doch heute begegnen, und erweise Güte an meinem Herrn Abraham!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Siehe, ich stehe bei der Wasserquelle, und die Töchter der Leute der Stadt kommen heraus, um Wasser zu schöpfen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'möge es nun geschehen, daß das Mädchen, zu dem ich sagen werde: Neige doch deinen Krug, daß ich trinke und welches sagen wird: Trinke, und auch deine Kamele will ich tränken, diejenige sei, welche du für deinen Knecht, für Isaak, bestimmt hast; und daran werde ich erkennen, daß du Güte an meinem Herrn erwiesen hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Und es geschah, er hatte noch nicht ausgeredet, siehe, da kam Rebekka heraus, die dem Bethuel geboren worden, dem Sohne der Milka, des Weibes Nahors, des Bruders Abrahams, mit ihrem Kruge auf ihrer Schulter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Und das Mädchen war sehr schön von Ansehen, eine Jungfrau, und kein Mann hatte sie erkannt; und sie stieg zur Quelle hinab und füllte ihren Krug und stieg wieder herauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Und der Knecht lief ihr entgegen und sprach: Laß mich doch ein wenig Wasser aus deinem Kruge schlürfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Und sie sprach: Trinke, mein Herr. Und eilends ließ sie ihren Krug auf ihre Hand hernieder und gab ihm zu trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Und als sie ihm genug zu trinken gegeben hatte, sprach sie: Ich will auch für deine Kamele schöpfen, bis sie genug getrunken haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Und sie eilte und goß ihren Krug aus in die Tränke und lief abermals zum Brunnen, um zu schöpfen; und sie schöpfte für alle seine Kamele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Und der Mann sah ihr staunend zu und schwieg, um zu erkennen, ob Jehova zu seiner Reise Glück gegeben habe oder nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Und es geschah, als die Kamele genug getrunken hatten, da nahm der Mann einen goldenen Ring, ein halber Sekel sein Gewicht, und zwei Spangen für ihre Arme, zehn Sekel Gold ihr Gewicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'und er sprach: Wessen Tochter bist du? Sage mir\'s doch an. Ist im Hause deines Vaters Raum für uns zu herbergen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Und sie sprach zu ihm: Ich bin die Tochter Bethuels, des Sohnes der Milka, den sie dem Nahor geboren hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Und sie sprach zu ihm: Sowohl Stroh als auch Futter ist bei uns in Menge, auch Raum zu herbergen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Da verneigte sich der Mann und warf sich nieder vor Jehova und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Gepriesen sei Jehova, der Gott meines Herrn Abraham, der von seiner Güte und seiner Wahrheit nicht abgelassen hat gegen meinen Herrn! Mich hat Jehova geleitet auf den Weg zum Hause der Brüder meines Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Und das Mädchen lief und berichtete diese Dinge dem Hause ihrer Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Und Rebekka hatte einen Bruder, sein Name war Laban; und Laban lief zu dem Manne hinaus zur Quelle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Und es geschah, als er den Ring sah und die Spangen an den Armen seiner Schwester, und als er die Worte seiner Schwester Rebekka hörte, welche sagte: Also hat der Mann zu mir geredet, da kam er zu dem Manne; und siehe, er stand bei den Kamelen, an der Quelle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Und er sprach: Komm herein, Gesegneter Jehovas! Warum stehst du draußen? Denn ich habe das Haus aufgeräumt, und Raum ist für die Kamele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Und der Mann kam in das Haus; und man sattelte die Kamele ab und gab den Kamelen Stroh und Futter, und Wasser, um seine Füße zu waschen und die Füße der Männer, die bei ihm waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Und es wurde ihm zu essen vorgesetzt; aber er sprach: Ich will nicht essen, bis ich meine Worte geredet habe. Und er sprach: Rede!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Da sprach er: Ich bin Abrahams Knecht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'und Jehova hat meinen Herrn sehr gesegnet, so daß er groß geworden ist; und er hat ihm Kleinvieh gegeben und Rinder, und Silber und Gold, und Knechte und Mägde, und Kamele und Esel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Und Sara, das Weib meines Herrn, hat meinem Herrn einen Sohn geboren, nachdem sie alt geworden war; und er hat ihm alles gegeben, was er hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Und mein Herr hat mich schwören lassen und gesagt: Du sollst meinem Sohne nicht ein Weib nehmen von den Töchtern der Kanaaniter, in deren Lande ich wohne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'sondern zu dem Hause meines Vaters und zu meinem Geschlecht sollst du gehen und meinem Sohne ein Weib nehmen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Und ich sprach zu meinem Herrn: Vielleicht wird das Weib mir nicht folgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Da sprach er zu mir: Jehova, vor dessen Angesicht ich gewandelt habe, wird seinen Engel mit dir senden und Glück zu deiner Reise geben, daß du meinem Sohne ein Weib nehmest aus meinem Geschlecht und aus dem Hause meines Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Wenn du zu meinem Geschlecht kommst, dann sollst du meines Eides ledig sein; und wenn sie sie dir nicht geben, so bist du meines Eides ledig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'So kam ich heute zu der Quelle und sprach: Jehova, Gott meines Herrn Abraham, wenn du doch Glück geben wolltest zu meinem Wege, auf dem ich gehe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Siehe, ich stehe bei der Wasserquelle; möge es nun geschehen, daß die Jungfrau, die herauskommt, um zu schöpfen, und zu der ich sagen werde: Gib mir doch ein wenig Wasser aus deinem Kruge zu trinken! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'und welche zu mir sagen wird: Trinke du, und auch für deine Kamele will ich schöpfen, daß sie das Weib sei, welches Jehova für den Sohn meines Herrn bestimmt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Ich hatte in meinem Herzen noch nicht ausgeredet, siehe, da kam Rebekka heraus mit ihrem Kruge auf ihrer Schulter; und sie stieg zur Quelle hinab und schöpfte. Da sprach ich zu ihr: Gib mir doch zu trinken!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Und eilends ließ sie ihren Krug von ihrer Schulter hernieder und sprach: Trinke, und auch deine Kamele will ich tränken. Und ich trank, und sie tränkte auch die Kamele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Und ich fragte sie und sprach: Wessen Tochter bist du? Und sie sprach: Die Tochter Bethuels, des Sohnes Nahors, den Milka ihm geboren hat. Und ich legte den Ring an ihre Nase und die Spangen an ihre Arme;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'und ich verneigte mich und warf mich nieder vor Jehova; und ich pries Jehova, den Gott meines Herrn Abraham, der mich den rechten Weg geleitet hat, um die Tochter des Bruders meines Herrn für seinen Sohn zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Und nun, wenn ihr Güte und Treue an meinem Herrn erweisen wollt, so tut es mir kund; und wenn nicht, so tut es mir kund, und ich werde mich zur Rechten oder zur Linken wenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Da antworteten Laban und Bethuel und sprachen: Von Jehova ist die Sache ausgegangen; wir können dir nichts sagen, weder Böses noch Gutes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Siehe, Rebekka ist vor dir: nimm sie und ziehe hin; und sie sei das Weib des Sohnes deines Herrn, wie Jehova geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Und es geschah, als Abrahams Knecht ihre Worte hörte, da beugte er sich zur Erde nieder vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Und der Knecht zog hervor silbernes Geschmeide und goldenes Geschmeide und Kleider und gab sie der Rebekka; und Kostbarkeiten gab er ihrem Bruder und ihrer Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Und sie aßen und tranken, er und die Männer, die bei ihm waren, und übernachteten. Und des Morgens standen sie auf, und er sprach: Entlasset mich zu meinem Herrn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Da sprachen ihr Bruder und ihre Mutter: Laß das Mädchen einige Tage oder zehn bei uns bleiben, danach magst du ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Er aber sprach zu ihnen: Haltet mich nicht auf, da Jehova Glück gegeben hat zu meiner Reise; entlasset mich, daß ich zu meinem Herrn ziehe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Und sie sprachen: Laßt uns das Mädchen rufen und ihren Mund befragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Und sie riefen Rebekka und sprachen zu ihr: Willst du mit diesem Manne gehen? Und sie antwortete: Ich will gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Und sie entließen ihre Schwester Rebekka mit ihrer Amme und den Knecht Abrahams und seine Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Und sie segneten Rebekka und sprachen zu ihr: Du, unsere Schwester, werde zu tausendmal Zehntausenden, und dein Same besitze das Tor seiner Feinde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Und Rebekka machte sich auf mit ihren Mägden, und sie bestiegen die Kamele und folgten dem Manne; und der Knecht nahm Rebekka und zog hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Isaak aber war von einem Gange nach dem Brunnen Lachai-Roi gekommen; er wohnte nämlich im Lande des Südens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Und Isaak ging aus, um auf dem Felde zu sinnen beim Anbruch des Abends; und er hob seine Augen auf und sah, und siehe, Kamele kamen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Und Rebekka hob ihre Augen auf und sah Isaak; und sie warf sich vom Kamele herab und sprach zu dem Knechte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Wer ist der Mann, der uns da auf dem Felde entgegenwandelt? Und der Knecht sprach: Das ist mein Herr. Da nahm sie den Schleier und verhüllte sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Und der Knecht erzählte Isaak all die Dinge, die er ausgerichtet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Und Isaak führte sie in das Zelt seiner Mutter Sara, und er nahm Rebekka, und sie wurde sein Weib, und er hatte sie lieb. Und Isaak tröstete sich nach dem Tode seiner Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Und Abraham nahm wieder ein Weib, mit Namen Ketura.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Und sie gebar ihm Simran und Jokschan und Medan und Midian und Jischbak und Schuach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Und Jokschan zeugte Scheba und Dedan; und die Söhne Dedans waren die Assurim und Letuschim und Leummim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Und die Söhne Midians: Epha und Epher und Hanok und Abida und Eldaba. Diese alle waren Söhne der Ketura. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Und Abraham gab dem Isaak alles, was er hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Und den Söhnen der Kebsweiber, die Abraham hatte, gab Abraham Geschenke; und er ließ sie, während er noch lebte, von seinem Sohne Isaak wegziehen nach Osten, in das Land des Ostens. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Und dies sind die Tage der Lebensjahre Abrahams, die er gelebt hat: hundertfünfundsiebzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Und Abraham verschied und starb in gutem Alter, alt und der Tage satt, und wurde versammelt zu seinen Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Und seine Söhne Isaak und Ismael begruben ihn in der Höhle von Machpela, auf dem Felde Ephrons, des Sohnes Zohars, des Hethiters, das vor Mamre liegt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'dem Felde, welches Abraham von den Kindern Heth gekauft hatte; dort wurden Abraham und sein Weib Sara begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Und es geschah nach dem Tode Abrahams, da segnete Gott Isaak, seinen Sohn; und Isaak wohnte bei dem Brunnen Lachai-Roi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Und dies sind die Geschlechter Ismaels, des Sohnes Abrahams, den Hagar, die Ägypterin, die Magd Saras, dem Abraham geboren hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'und dies sind die Namen der Söhne Ismaels mit ihren Namen, nach ihren Geschlechtern: Der Erstgeborene Ismaels: Nebajoth, und Kedar und Adbeel und Mibsam');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'und Mischma und Duma und Massa,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadad und Tema, Jetur, Naphisch und Kedma.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Das sind die Söhne Ismaels, und das ihre Namen in ihren Gehöften und in ihren Zeltlagern; zwölf Fürsten nach ihren Stämmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Und dies sind die Lebensjahre Ismaels: hundertsiebenunddreißig Jahre; und er verschied und starb und wurde versammelt zu seinen Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Und sie wohnten von Hawila bis Sur, das vor Ägypten liegt, nach Assyrien hin. Er ließ sich nieder angesichts aller seiner Brüder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Und dies sind die Geschlechter Isaaks, des Sohnes Abrahams: Abraham zeugte Isaak.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Und Isaak war vierzig Jahre alt, als er sich Rebekka zum Weibe nahm, die Tochter Bethuels, des Aramäers aus Paddan-Aram, die Schwester Labans, des Aramäers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Und Isaak bat Jehova für sein Weib, denn sie war unfruchtbar; und Jehova ließ sich von ihm erbitten, und Rebekka, sein Weib, wurde schwanger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Und die Kinder stießen sich in ihr; und sie sprach: Wenn es so steht, warum bin ich dies? Und sie ging hin, Jehova zu befragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Und Jehova sprach zu ihr: Zwei Nationen sind in deinem Leibe, und zwei Völkerschaften werden sich scheiden aus deinem Innern; und eine Völkerschaft wird stärker sein als die andere, und der Ältere wird dem Jüngeren dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Und als ihre Tage erfüllt waren, daß sie gebären sollte, siehe, da waren Zwillinge in ihrem Leibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Und der erste kam heraus, rötlich, am ganzen Leibe wie ein härener Mantel; und man gab ihm den Namen Esau.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Und danach kam sein Bruder heraus, und seine Hand hielt die Ferse Esaus; und man gab ihm den Namen Jakob. Und Isaak war sechzig Jahre alt, als sie geboren wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Und die Knaben wuchsen heran. Und Esau wurde ein jagdkundiger Mann, ein Mann des Feldes; Jakob aber war ein sanfter Mann, der in den Zelten blieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Und Isaak hatte Esau lieb, denn Wildbret war nach seinem Munde; Rebekka aber hatte Jakob lieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Und Jakob kochte ein Gericht; und Esau kam vom Felde und war matt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Da sprach Esau zu Jakob: Laß mich doch essen von dem Roten, dem Roten da, denn ich bin matt! Darum gab man ihm den Namen Edom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Und Jakob sprach: Verkaufe mir heute dein Erstgeburtsrecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Und Esau sprach: Siehe, ich gehe hin zu sterben, und wozu mir da das Erstgeburtsrecht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Und Jakob sprach: Schwöre mir heute! Und er schwur ihm und verkaufte sein Erstgeburtsrecht dem Jakob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Und Jakob gab Esau Brot und ein Gericht Linsen; und er aß und trank und stand auf und ging davon. So verachtete Esau das Erstgeburtsrecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Und es entstand eine Hungersnot im Lande, außer der vorigen Hungersnot, die in den Tagen Abrahams gewesen war. Und Isaak zog zu Abimelech, dem Könige der Philister, nach Gerar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Und Jehova erschien ihm und sprach: Ziehe nicht hinab nach Ägypten; bleibe in dem Lande, von dem ich dir sage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Halte dich auf in diesem Lande, und ich werde mit dir sein und dich segnen; denn dir und deinem Samen werde ich alle diese Länder geben, und ich werde den Eid aufrecht halten, den ich deinem Vater Abraham geschworen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Und ich werde deinen Samen mehren wie die Sterne des Himmels und deinem Samen alle diese Länder geben; und in deinem Samen werden sich segnen alle Nationen der Erde:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'darum daß Abraham meiner Stimme gehorcht und beobachtet hat meine Vorschriften, meine Gebote, meine Satzungen und meine Gesetze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'So blieb Isaak in Gerar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Und die Männer des Ortes erkundigten sich nach seinem Weibe, und er sprach: Sie ist meine Schwester. Denn er fürchtete sich zu sagen: Mein Weib, indem er dachte: Die Männer des Ortes möchten mich sonst töten wegen Rebekka; denn sie ist schön von Ansehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Und es geschah, als er längere Zeit daselbst gewesen war, da blickte Abimelech, der König der Philister, durchs Fenster, und er sah, und siehe, Isaak scherzte mit Rebekka, seinem Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Da rief Abimelech den Isaak und sprach: Siehe, fürwahr, sie ist dein Weib; und wie hast du gesagt: Sie ist meine Schwester? Und Isaak sprach zu ihm: Weil ich mir sagte: Daß ich nicht sterbe ihretwegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Und Abimelech sprach: Was hast du uns da getan! Wenig fehlte, so hätte einer aus dem Volke bei deinem Weibe gelegen, und du hättest eine Schuld über uns gebracht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Und Abimelech gebot allem Volke und sprach: Wer diesen Mann und sein Weib antastet, soll gewißlich getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Und Isaak säte in selbigem Lande und gewann in selbigem Jahre das Hundertfältige; und Jehova segnete ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Und der Mann ward groß und wurde fort und fort größer, bis er sehr groß war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Und er hatte Herden von Kleinvieh und Herden von Rindern und ein großes Gesinde; und die Philister beneideten ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Und alle Brunnen, welche die Knechte seines Vaters in den Tagen seines Vaters Abraham gegraben hatten, verstopften die Philister und füllten sie mit Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Und Abimelech sprach zu Isaak: Ziehe weg von uns, denn du bist viel mächtiger geworden als wir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Da zog Isaak von dannen und schlug sein Lager auf im Tale Gerar und wohnte daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Und Isaak grub die Wasserbrunnen wieder auf, welche sie in den Tagen seines Vaters Abraham gegraben und welche die Philister nach dem Tode Abrahams verstopft hatten; und er benannte sie mit denselben Namen, womit sein Vater sie benannt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Und die Knechte Isaaks gruben im Tale und fanden daselbst einen Brunnen lebendigen Wassers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Da haderten die Hirten von Gerar mit den Hirten Isaaks und sprachen: Das Wasser ist unser! Und er gab dem Brunnen den Namen Esek, weil sie mit ihm gezankt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Und sie gruben einen anderen Brunnen, und sie haderten auch über diesen, und er gab ihm den Namen Sitna.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Und er brach auf von dannen und grub einen anderen Brunnen, und über diesen haderten sie nicht; und er gab ihm den Namen Rechoboth und sprach: Denn nun hat Jehova uns Raum gemacht, und wir werden fruchtbar sein im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Und er zog von dannen hinauf nach Beerseba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Und Jehova erschien ihm in selbiger Nacht und sprach: Ich bin der Gott Abrahams, deines Vaters; fürchte dich nicht, denn ich bin mit dir, und ich werde dich segnen und deinen Samen mehren um Abrahams, meines Knechtes, willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Und er baute daselbst einen Altar und rief den Namen Jehovas an; und er schlug daselbst sein Zelt auf; und die Knechte Isaaks gruben daselbst einen Brunnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Und Abimelech zog zu ihm von Gerar mit Achusat, seinem Freunde, und Pikol, seinem Heerobersten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Und Isaak sprach zu ihnen: Warum kommet ihr zu mir, da ihr mich doch hasset und mich von euch weggetrieben habt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Und sie sprachen: Wir haben deutlich gesehen, daß Jehova mit dir ist; und wir haben uns gesagt: Möge doch ein Eid sein zwischen uns, zwischen uns und dir, und wir wollen einen Bund mit dir machen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'daß du uns nichts Übles tuest, so wie wir dich nicht angetastet haben und wie wir dir nur Gutes erwiesen und dich haben ziehen lassen in Frieden. Du bist nun einmal ein Gesegneter Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Und er machte ihnen ein Mahl, und sie aßen und tranken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Und sie standen des Morgens früh auf und schwuren einer dem anderen; und Isaak entließ sie, und sie zogen von ihm in Frieden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Und es geschah an selbigem Tage, da kamen Isaaks Knechte und berichteten ihm wegen des Brunnens, den sie gegraben hatten, und sprachen zu ihm: Wir haben Wasser gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Und er nannte ihn Sibea; daher der Name der Stadt Beerseba bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Und Esau war vierzig Jahre alt, da nahm er zum Weibe Judith, die Tochter Beeris, des Hethiters, und Basmath, die Tochter Elons, des Hethiters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Und sie waren ein Herzeleid für Isaak und Rebekka.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Und es geschah, als Isaak alt geworden und seine Augen zu schwach waren, um zu sehen, da rief er Esau, seinen älteren Sohn, und sprach zu ihm: Mein Sohn! Und er sprach zu ihm: Hier bin ich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Und er sprach: Siehe doch, ich bin alt geworden, ich weiß nicht den Tag meines Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Und nun nimm doch dein Jagdgerät, deinen Köcher und deinen Bogen, und gehe hinaus aufs Feld und erjage mir ein Wildbret;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'und bereite mir ein schmackhaftes Gericht, wie ich es gern habe, und bringe es mir her, daß ich esse, damit meine Seele dich segne, ehe ich sterbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Und Rebekka hörte zu, als Isaak zu seinem Sohne Esau redete. Und Esau ging aufs Feld, ein Wildbret zu erjagen, um es heimzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Und Rebekka sprach zu ihrem Sohne Jakob und sagte: Siehe, ich habe deinen Vater zu deinem Bruder Esau also reden hören:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Bringe mir ein Wildbret und bereite mir ein schmackhaftes Gericht, daß ich esse, und daß ich dich vor Jehova segne vor meinem Tode.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Und nun, mein Sohn, höre auf meine Stimme in dem, was ich dich heiße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Gehe doch zur Herde und hole mir von dannen zwei gute Ziegenböcklein, und ich will sie zu einem schmackhaften Gericht bereiten für deinen Vater, wie er es gern hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'und du sollst es deinem Vater bringen, daß er esse, damit er dich segne vor seinem Tode.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Da sprach Jakob zu Rebekka, seiner Mutter: Siehe, mein Bruder Esau ist ein haariger Mann, und ich bin ein glatter Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Vielleicht wird mein Vater mich betasten, und ich werde in seinen Augen sein wie einer, der Spott mit ihm treibt, und ich werde Fluch auf mich bringen und nicht Segen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Seine Mutter aber sprach zu ihm: Dein Fluch komme auf mich, mein Sohn! Höre nur auf meine Stimme und gehe, hole mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Und er ging und holte und brachte sie seiner Mutter. Und seine Mutter bereitete ein schmackhaftes Gericht, wie sein Vater es gern hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Und Rebekka nahm die Kleider Esaus, ihres älteren Sohnes, die kostbaren, die bei ihr im Hause waren, und zog sie Jakob, ihrem jüngeren Sohne, an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'und die Felle der Ziegenböcklein zog sie über seine Hände und über die Glätte seines Halses,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'und sie gab das schmackhafte Gericht und das Brot, das sie bereitet hatte, in die Hand ihres Sohnes Jakob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Und er ging zu seinem Vater hinein und sprach: Mein Vater! Und er sprach: Hier bin ich; wer bist du, mein Sohn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Und Jakob sprach zu seinem Vater: Ich bin Esau, dein Erstgeborener; ich habe getan, wie du zu mir geredet hast. Stehe doch auf, setze dich und iß von meinem Wildbret, damit deine Seele mich segne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Und Isaak sprach zu seinem Sohne: Wie hast du es denn so bald gefunden, mein Sohn? Und er sprach: Weil Jehova, dein Gott, es mir begegnen ließ.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Da sprach Isaak zu Jakob: Tritt doch herzu, daß ich dich betaste, mein Sohn, ob du wirklich mein Sohn Esau bist oder nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Und Jakob trat hin zu seinem Vater Isaak; und er betastete ihn und sprach: Die Stimme ist Jakobs Stimme, aber die Hände sind Esaus Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Und er erkannte ihn nicht, denn seine Hände waren haarig wie die Hände seines Bruders Esau; und er segnete ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Und er sprach: Bist du wirklich mein Sohn Esau? Und er sprach: Ich bin\'s.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Da sprach er: Reiche es mir her, daß ich esse von dem Wildbret meines Sohnes, damit meine Seele dich segne. Und er reichte es ihm hin, und er aß; und er brachte ihm Wein, und er trank.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Und sein Vater Isaak sprach zu ihm: Tritt doch herzu und küsse mich, mein Sohn. Und er trat hinzu und küßte ihn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'und er roch den Geruch seiner Kleider, und er segnete ihn und sprach: Siehe, der Geruch meines Sohnes ist wie der Geruch eines Feldes, das Jehova gesegnet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Und Gott gebe dir vom Tau des Himmels und von der Fettigkeit der Erde, und Fülle von Korn und Most!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Völker sollen dir dienen und Völkerschaften sich vor dir niederbeugen! Sei Herr über deine Brüder, und vor dir sollen sich niederbeugen die Söhne deiner Mutter! Wer dir flucht, sei verflucht, und wer dich segnet, sei gesegnet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Und es geschah, sowie Isaak geendet hatte, Jakob zu segnen, ja, es geschah, als Jakob nur eben von seinem Vater Isaak hinausgegangen war, da kam sein Bruder Esau von seiner Jagd.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Und auch er bereitete ein schmackhaftes Gericht und brachte es zu seinem Vater und sprach zu seinem Vater: Mein Vater stehe auf und esse von dem Wildbret seines Sohnes, damit deine Seele mich segne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Und sein Vater Isaak sprach zu ihm: Wer bist du? Und er sprach: Ich bin dein Sohn, dein Erstgeborener, Esau.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Da erschrak Isaak mit großem Schrecken über die Maßen und sprach: Wer war denn der, welcher ein Wildbret erjagt und mir gebracht hat? Und ich habe von allem gegessen, ehe du kamst, und habe ihn gesegnet; er wird auch gesegnet sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Als Esau die Worte seines Vaters hörte, da schrie er mit einem großen und bitterlichen Geschrei über die Maßen und sprach zu seinem Vater: Segne mich, auch mich, mein Vater!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Und er sprach: Dein Bruder ist mit Betrug gekommen und hat deinen Segen weggenommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Da sprach er: Ist es nicht, weil man ihm den Namen Jakob gegeben, daß er mich nun zweimal überlistet hat? Mein Erstgeburtsrecht hat er weggenommen, und siehe, nun hat er meinen Segen weggenommen! Und er sprach: Hast du mir keinen Segen aufbehalten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Da antwortete Isaak und sprach zu Esau: Siehe, ich habe ihn zum Herrn über dich gesetzt und alle seine Brüder ihm zu Knechten gegeben, und mit Korn und Most habe ich ihn versehen, und nun, was könnte ich für dich tun, mein Sohn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Und Esau sprach zu seinem Vater: Hast du nur diesen einen Segen, mein Vater? Segne mich, auch mich, mein Vater! Und Esau erhob seine Stimme und weinte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Da antwortete sein Vater Isaak und sprach zu ihm: Siehe, fern von der Fettigkeit der Erde wird dein Wohnsitz sein und ohne den Tau des Himmels von oben her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Und von deinem Schwerte wirst du leben, und deinem Bruder wirst du dienen; und es wird geschehen, wenn du umherschweifst, wirst du sein Joch zerbrechen von deinem Halse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Und Esau feindete Jakob an wegen des Segens, womit sein Vater ihn gesegnet hatte; und Esau sprach in seinem Herzen: Es nahen die Tage der Trauer um meinen Vater, dann werde ich meinen Bruder Jakob erschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Und es wurden der Rebekka die Worte Esaus, ihres älteren Sohnes, berichtet; und sie sandte hin und ließ Jakob, ihren jüngeren Sohn, rufen und sprach zu ihm: Siehe, dein Bruder Esau will sich an dir rächen, indem er dich erschlägt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Und nun, mein Sohn, höre auf meine Stimme und mache dich auf, fliehe zu meinem Bruder Laban nach Haran;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'und bleibe einige Zeit bei ihm, bis der Grimm deines Bruders sich wendet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'bis der Zorn deines Bruders sich von dir abwendet, und er vergißt, was du ihm getan hast; dann will ich hinsenden und dich von dort holen lassen. Warum sollte ich euer beider zugleich beraubt werden an einem Tage?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Und Rebekka sprach zu Isaak: Ich bin des Lebens überdrüssig wegen der Töchter Heths; wenn Jakob ein Weib nähme von den Töchtern Heths, wie diese, von den Töchtern des Landes, wozu sollte mir das Leben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Und Isaak rief Jakob und segnete ihn; und er gebot ihm und sprach zu ihm: Du sollst nicht ein Weib nehmen von den Töchtern Kanaans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Mache dich auf, gehe nach Paddan-Aram, zum Hause Bethuels, des Vaters deiner Mutter; und nimm dir von dort ein Weib von den Töchtern Labans, des Bruders deiner Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Und Gott, der Allmächtige, segne dich und mache dich fruchtbar und mehre dich, daß du zu einer Schar von Völkern werdest;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'und er gebe dir den Segen Abrahams, dir und deinem Samen mit dir, auf daß du besitzest das Land deiner Fremdlingschaft, das Gott dem Abraham gegeben hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Und Isaak entließ Jakob; und er ging nach Paddan-Aram zu Laban, dem Sohne Bethuels, des Aramäers, dem Bruder Rebekkas, der Mutter Jakobs und Esaus. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Und als Esau sah, daß Isaak den Jakob gesegnet und ihn nach Paddan-Aram entlassen hatte, um sich von dort ein Weib zu nehmen, indem er ihn segnete und ihm gebot und sprach: Du sollst nicht ein Weib nehmen von den Töchtern Kanaans,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'und daß Jakob seinem Vater und seiner Mutter gehorcht hatte und nach Paddan-Aram gegangen war:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'als Esau sah, daß die Töchter Kanaans übel waren in den Augen seines Vaters Isaak,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'da ging Esau hin zu Ismael und nahm sich zum Weibe Machalath, die Tochter Ismaels, des Sohnes Abrahams, die Schwester Nebajoths, zu seinen anderen Weibern hinzu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Und Jakob zog aus von Beerseba und ging nach Haran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Und er gelangte an einen Ort und übernachtete daselbst; denn die Sonne war untergegangen. Und er nahm einen von den Steinen des Ortes und legte ihn zu seinen Häupten und legte sich nieder an selbigem Orte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Und er träumte: und siehe, eine Leiter war auf die Erde gestellt, und ihre Spitze rührte an den Himmel; und siehe, Engel Gottes stiegen auf und nieder an ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Und siehe, Jehova stand über ihr und sprach: Ich bin Jehova, der Gott Abrahams, deines Vaters, und der Gott Isaaks; das Land, auf welchem du liegst, dir will ich es geben und deinem Samen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Und dein Same soll werden wie der Staub der Erde, und du wirst dich ausbreiten nach Westen und nach Osten und nach Norden und nach Süden hin; und in dir und in deinem Samen sollen gesegnet werden alle Geschlechter der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Und siehe, ich bin mit dir, und ich will dich behüten überall, wohin du gehst, und dich zurückbringen in dieses Land; denn ich werde dich nicht verlassen, bis ich getan, was ich zu dir geredet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Und Jakob erwachte von seinem Schlafe und sprach: Fürwahr, Jehova ist an diesem Orte, und ich wußte es nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Und er fürchtete sich und sprach: Wie furchtbar ist dieser Ort! Dies ist nichts anderes als Gottes Haus, und dies die Pforte des Himmels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Und Jakob stand des Morgens früh auf und nahm den Stein, den er zu seinen Häupten gelegt hatte, und stellte ihn auf als Denkmal und goß Öl auf seine Spitze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Und er gab selbigem Orte den Namen Bethel; aber im Anfang war Lus der Name der Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Und Jakob tat ein Gelübde und sprach: Wenn Gott mit mir ist und mich behütet auf diesem Wege, den ich gehe, und mir Brot zu essen gibt und Kleider anzuziehen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'und ich in Frieden zurückkehre zum Hause meines Vaters, so soll Jehova mein Gott sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Und dieser Stein, den ich als Denkmal aufgestellt habe, soll ein Haus Gottes sein; und von allem, was du mir geben wirst, werde ich dir gewißlich den Zehnten geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Und Jakob erhob seine Füße und ging nach dem Lande der Kinder des Ostens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Und er sah: und siehe, ein Brunnen auf dem Felde; und siehe, daselbst waren drei Herden Schafe an demselben gelagert, denn aus diesem Brunnen tränkte man die Herden; und der Stein auf der Öffnung des Brunnens war groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Und waren alle Herden dort zusammengetrieben, so wälzte man den Stein von der Öffnung des Brunnens und tränkte die Schafe; und man brachte den Stein wieder auf die Öffnung des Brunnens an seinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Und Jakob sprach zu ihnen: Meine Brüder, woher seid ihr? Und sie sprachen: Wir sind von Haran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Da sprach er zu ihnen: Kennet ihr Laban, den Sohn Nahors? Und sie sprachen: Wir kennen ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Und er sprach zu ihnen: Geht es ihm wohl? Und sie sprachen: Es geht ihm wohl; und siehe, da kommt seine Tochter Rahel mit den Schafen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Da sprach er: Siehe, es ist noch hoch am Tage, es ist nicht Zeit, das Vieh zusammenzutreiben; tränket die Schafe und gehet hin, weidet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Und sie sprachen: Wir können nicht, bis alle Herden zusammengetrieben werden; dann wälzt man den Stein von der Öffnung des Brunnens, und wir tränken die Schafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Noch redete er mit ihnen, da kam Rahel mit den Schafen, die ihrem Vater gehörten; denn sie war eine Hirtin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Und es geschah, als Jakob die Rahel sah, die Tochter Labans, des Bruders seiner Mutter, und die Schafe Labans, des Bruders seiner Mutter, da trat Jakob hinzu und wälzte den Stein von der Öffnung des Brunnens und tränkte die Schafe Labans, des Bruders seiner Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Und Jakob küßte Rahel und erhob seine Stimme und weinte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Und Jakob tat Rahel kund, daß er ein Bruder ihres Vaters und daß er der Sohn Rebekkas wäre; und sie lief und berichtete es ihrem Vater.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Und es geschah, als Laban die Kunde von Jakob, dem Sohne seiner Schwester, hörte, da lief er ihm entgegen und umarmte ihn und küßte ihn und führte ihn in sein Haus; und er erzählte dem Laban alle diese Dinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Und Laban sprach zu ihm: Fürwahr, du bist mein Bein und mein Fleisch. Und er blieb bei ihm einen Monat lang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Und Laban sprach zu Jakob: Solltest du mir darum, weil du mein Bruder bist, umsonst dienen? Tue mir kund, was soll dein Lohn sein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Und Laban hatte zwei Töchter; der Name der älteren war Lea und der Name der jüngeren Rahel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Und die Augen der Lea waren blöde; Rahel aber war schön von Gestalt und schön von Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Und Jakob liebte Rahel und sprach: Ich will dir sieben Jahre dienen um Rahel, deine jüngere Tochter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Und Laban sprach: Es ist besser, ich gebe sie dir, als daß ich sie einem anderen Manne gebe; bleibe bei mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Und Jakob diente um Rahel sieben Jahre; und sie waren in seinen Augen wie einzelne Tage, weil er sie liebte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Und Jakob sprach zu Laban: Gib mir mein Weib; denn meine Tage sind erfüllt, daß ich zu ihr eingehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Und Laban versammelte alle Männer des Ortes und machte ein Mahl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Und es geschah am Abend, da nahm er seine Tochter Lea und brachte sie zu ihm; und er ging zu ihr ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Und Laban gab seine Magd Silpa seiner Tochter Lea zur Magd.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Und es geschah am Morgen, siehe, da war es Lea. Da sprach er zu Laban: Was hast du mir da angetan! Habe ich nicht um Rahel bei dir gedient? Und warum hast du mich betrogen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Und Laban sprach: Es geschieht nicht also an unserem Orte, die Jüngere vor der Erstgeborenen zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Vollende die Woche mit dieser, so wollen wir dir auch jene geben, um den Dienst, den du bei mir dienen sollst noch andere sieben Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Und Jakob tat also und vollendete die Woche mit dieser; und er gab ihm seine Tochter Rahel zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Und Laban gab seiner Tochter Rahel seine Magd Bilha zur Magd.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Und er ging auch zu Rahel ein; und er liebte auch Rahel mehr als Lea. Und er diente bei ihm noch andere sieben Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Und als Jehova sah, daß Lea gehaßt war, da öffnete er ihren Mutterleib; Rahel aber war unfruchtbar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Und Lea ward schwanger und gebar einen Sohn, und sie gab ihm den Namen Ruben, denn sie sprach: Weil Jehova mein Elend angesehen hat; denn nun wird mein Mann mich lieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Und sie ward wiederum schwanger und gebar einen Sohn; und sie sprach: Weil Jehova gehört hat, daß ich gehaßt bin, so hat er mir auch diesen gegeben. Und sie gab ihm den Namen Simeon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Und sie ward wiederum schwanger und gebar einen Sohn; und sie sprach: Nun, diesmal wird sich mein Mann an mich anschließen, denn ich habe ihm drei Söhne geboren! Darum gab man ihm den Namen Levi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Und sie ward wiederum schwanger und gebar einen Sohn; und sie sprach: Diesmal will ich Jehova preisen! Darum gab sie ihm den Namen Juda. Und sie hörte auf zu gebären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Und als Rahel sah, daß sie dem Jakob nicht gebar, da beneidete Rahel ihre Schwester und sprach zu Jakob: Gib mir Kinder! Und wenn nicht, so sterbe ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Da entbrannte der Zorn Jakobs wider Rahel, und er sprach: Bin ich an Gottes Statt, der dir die Leibesfrucht versagt hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Und sie sprach: Siehe, da ist meine Magd Bilha; gehe zu ihr ein, daß sie auf meine Kniee gebäre und auch ich aus ihr erbaut werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Und sie gab ihm ihre Magd Bilha zum Weibe; und Jakob ging zu ihr ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Und Bilha ward schwanger und gebar Jakob einen Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Da sprach Rahel: Gott hat mir Recht verschafft und auch auf meine Stimme gehört und mir einen Sohn gegeben! Darum gab sie ihm den Namen Dan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Und Bilha, die Magd Rahels, ward wiederum schwanger und gebar dem Jakob einen zweiten Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Da sprach Rahel: Kämpfe Gottes habe ich mit meiner Schwester gekämpft, habe auch obsiegt! Und sie gab ihm den Namen Naphtali.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Und als Lea sah, daß sie aufhörte zu gebären, da nahm sie ihre Magd Silpa und gab sie Jakob zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Und Silpa, die Magd Leas, gebar dem Jakob einen Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Da sprach Lea: Zum Glück! Und sie gab ihm den Namen Gad.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Und Silpa, die Magd Leas, gebar dem Jakob einen zweiten Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Da sprach Lea: Zu meiner Glückseligkeit! Denn glückselig preisen mich die Töchter. Und sie gab ihm den Namen Aser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Und Ruben ging aus in den Tagen der Weizenernte und fand Dudaim auf dem Felde; und er brachte sie seiner Mutter Lea. Und Rahel sprach zu Lea: Gib mir doch von den Dudaim deines Sohnes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Und sie sprach zu ihr: Ist es zu wenig, daß du meinen Mann genommen hast, daß du auch die Dudaim meines Sohnes nehmen willst? Da sprach Rahel: So mag er denn diese Nacht bei dir liegen für die Dudaim deines Sohnes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Und als Jakob am Abend vom Felde kam, da ging Lea hinaus, ihm entgegen, und sprach: Zu mir sollst du eingehen, denn ich habe dich gewißlich gedungen um die Dudaim meines Sohnes. Und er lag bei ihr in selbiger Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Und Gott hörte auf Lea, und sie ward schwanger und gebar dem Jakob einen fünften Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Da sprach Lea: Gott hat mir meinen Lohn gegeben, daß ich meine Magd meinem Manne gegeben habe! Und sie gab ihm den Namen Issaschar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Und Lea ward wiederum schwanger und gebar dem Jakob einen sechsten Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Da sprach Lea: Mir hat Gott ein schönes Geschenk gegeben; diesmal wird mein Mann bei mir wohnen, denn ich habe ihm sechs Söhne geboren! Und sie gab ihm den Namen Sebulon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Und danach gebar sie eine Tochter und gab ihr den Namen Dina.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Und Gott gedachte an Rahel, und Gott hörte auf sie und öffnete ihren Mutterleib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Und sie ward schwanger und gebar einen Sohn; und sie sprach: Gott hat meine Schmach weggenommen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Und sie gab ihm den Namen Joseph und sprach: Jehova füge mir einen anderen Sohn hinzu!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Und es geschah, als Rahel den Joseph geboren hatte, da sprach Jakob zu Laban: Entlaß mich, daß ich an meinen Ort und in mein Land ziehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Gib mir meine Weiber und meine Kinder, um welche ich dir gedient habe, daß ich hinziehe; denn du kennst ja meinen Dienst, womit ich dir gedient habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Und Laban sprach zu ihm: Wenn ich doch Gnade gefunden habe in deinen Augen...!Ich habe gespürt, daß Jehova mich um deinetwillen gesegnet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Und er sprach: Bestimme mir deinen Lohn, und ich will ihn geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Da sprach er zu ihm: Du weißt ja, wie ich dir gedient habe und was dein Vieh bei mir geworden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Denn wenig war, was du vor mir hattest, und es hat sich ausgebreitet zu einer Menge, und Jehova hat dich gesegnet auf jedem meiner Tritte; und nun, wann soll ich auch für mein Haus schaffen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Und er sprach: Was soll ich dir geben? Und Jakob sprach: Du sollst mir gar nichts geben; wenn du mir dieses tust, so will ich wiederum deine Herde weiden und hüten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Ich will heute durch deine ganze Herde gehen und daraus absondern jedes gesprenkelte und gefleckte Tier und jedes dunkelfarbige Tier unter den Schafen, und das Gefleckte und Gesprenkelte unter den Ziegen; und das sei mein Lohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Und meine Gerechtigkeit wird für mich zeugen am morgenden Tage, wenn sie wegen meines Lohnes vor dich kommt; alles, was nicht gesprenkelt und gefleckt ist unter den Ziegen und dunkelfarbig unter den Schafen, das sei gestohlen bei mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Und Laban sprach: Siehe, es geschehe nach deinem Worte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Und er sonderte an selbigem Tage die gestreiften und gefleckten Böcke ab und alle gesprenkelten und gefleckten Ziegen, alles, woran Weißes war, und alles Dunkelfarbige unter den Schafen, und gab sie in die Hand seiner Söhne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Und er setzte einen Weg von drei Tagereisen zwischen sich und Jakob; und Jakob weidete die übrige Herde Labans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Und Jakob nahm sich frische Stäbe von Weißpappel, Mandelbaum und Platane und schälte weiße Streifen daran, indem er das Weiße entblößte, das an den Stäben war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Und er legte die Stäbe, die er geschält hatte, in die Tränkrinnen, in die Wassertränken, wohin die Herde zum Trinken kam, vor die Herde hin; und sie wurde brünstig, wenn sie zum Trinken kam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Und die Herde wurde brünstig vor den Stäben, und die Herde gebar gestreifte, gesprenkelte und gefleckte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Und Jakob schied die Lämmer aus, und er richtete das Gesicht der Herde auf das Gestreifte und alles Dunkelfarbige in der Herde Labans; und so machte er sich Herden besonders und tat sie nicht zu der Herde Labans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Und es geschah, so oft das kräftige Vieh brünstig wurde, dann legte Jakob die Stäbe vor die Augen der Herde in die Tränkrinnen, damit sie bei den Stäben brünstig würden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'wenn aber das Vieh schwächlich war, legte er sie nicht hin. Also wurden die schwächlichen dem Laban und die kräftigen dem Jakob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Und der Mann breitete sich sehr, sehr aus, und er bekam viele Herden, und Mägde und Knechte, und Kamele und Esel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Und er hörte die Worte der Söhne Labans, welche sprachen: Jakob hat alles genommen, was unserem Vater gehörte; und von dem, was unserem Vater gehörte, hat er sich all diesen Reichtum verschafft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Und Jakob sah das Angesicht Labans, und siehe, es war nicht gegen ihn wie früher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Und Jehova sprach zu Jakob: Kehre zurück in das Land deiner Väter und zu deiner Verwandtschaft, und ich will mit dir sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Da sandte Jakob hin und ließ Rahel und Lea aufs Feld rufen zu seiner Herde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Und er sprach zu ihnen: Ich sehe das Angesicht eures Vaters, daß es nicht gegen mich ist wie früher; aber der Gott meines Vaters ist mit mir gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Ihr selbst wisset ja, daß ich mit all meiner Kraft eurem Vater gedient habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Und euer Vater hat mich betrogen und hat meinen Lohn zehnmal verändert; aber Gott hat ihm nicht gestattet, mir Übles zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Wenn er so sprach: Die gesprenkelten sollen dein Lohn sein, dann gebaren alle Herden gesprenkelte; und wenn er so sprach: Die gestreiften sollen dein Lohn sein, dann gebaren alle Herden gestreifte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Und Gott hat das Vieh eures Vaters genommen und mir gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Und es geschah zur Brunstzeit der Herde, da hob ich meine Augen auf und sah im Traume: und siehe, die Böcke, welche die Herde besprangen, waren gestreift, gesprenkelt und getüpfelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Und der Engel Gottes sprach im Traume zu mir: Jakob! Und ich sprach: Hier bin ich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Und er sprach: Hebe doch deine Augen auf und sieh: alle Böcke, welche die Herde bespringen, sind gestreift, gesprenkelt und getüpfelt; denn ich habe alles gesehen, was Laban dir tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ich bin der Gott von Bethel, wo du ein Denkmal gesalbt, wo du mir ein Gelübde getan hast. Nun mache dich auf, ziehe aus diesem Lande und kehre zurück in das Land deiner Verwandtschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Und Rahel und Lea antworteten und sprachen zu ihm: Haben wir noch ein Teil und ein Erbe im Hause unseres Vaters?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Sind wir nicht als Fremde von ihm geachtet worden? Denn er hat uns verkauft und hat auch unser Geld völlig verzehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Denn aller Reichtum, den Gott unserem Vater entrissen hat, uns gehört er und unseren Kindern. So tue nun alles, was Gott zu dir geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Da machte Jakob sich auf und hob seine Kinder und seine Weiber auf die Kamele,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'und führte weg all sein Vieh und all seine Habe, die er erworben, das Vieh seines Eigentums, das er erworben hatte in Paddan-Aram, um zu seinem Vater Isaak zu kommen in das Land Kanaan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Und Laban war gegangen, um seine Schafe zu scheren; und Rahel stahl die Teraphim, die ihr Vater hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Und Jakob hinterging Laban, den Aramäer, indem er ihm nicht kundtat, daß er fliehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Und er floh, er und alles, was er hatte; und er machte sich auf und setzte über den Strom und richtete sein Angesicht nach dem Gebirge Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Und am dritten Tage wurde dem Laban berichtet, daß Jakob geflohen wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Und er nahm seine Brüder mit sich und jagte ihm sieben Tagereisen nach und ereilte ihn auf dem Gebirge Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Und Gott kam zu Laban, dem Aramäer, in einem Traume der Nacht und sprach zu ihm: Hüte dich, daß du mit Jakob weder Gutes noch Böses redest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Und Laban erreichte Jakob, und Jakob hatte sein Zelt auf dem Gebirge aufgeschlagen; und Laban schlug es auf mit seinen Brüdern auf dem Gebirge Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Und Laban sprach zu Jakob: Was hast du getan, daß du mich hintergangen und meine Töchter wie Kriegsgefangene weggeführt hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Warum bist du heimlich geflohen und hast mich hintergangen und hast es mir nicht kundgetan ich hätte dich ja begleitet mit Freude und mit Gesängen, mit Tamburin und mit Laute-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'und hast mir nicht zugelassen, meine Söhne und meine Töchter zu küssen? Nun, du hast töricht gehandelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Es wäre in der Macht meiner Hand, euch Übles zu tun; aber der Gott eures Vaters hat gestern Nacht zu mir geredet und gesagt: Hüte dich, mit Jakob weder Gutes noch Böses zu reden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Und nun, da du einmal weggegangen bist, weil du dich so sehr nach dem Hause deines Vaters sehntest, warum hast du meine Götter gestohlen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Da antwortete Jakob und sprach zu Laban: Weil ich mich fürchtete; denn ich sagte mir, du möchtest mir etwa deine Töchter entreißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Bei wem du deine Götter findest, der soll nicht leben. Erforsche vor unseren Brüdern, was bei mir ist, und nimm es dir. Jakob aber wußte nicht, daß Rahel sie gestohlen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Und Laban ging in das Zelt Jakobs und in das Zelt Leas und in das Zelt der beiden Mägde und fand nichts; und er ging aus dem Zelte Leas und kam in das Zelt Rahels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Rahel aber hatte die Teraphim genommen und sie in den Kamelsattel gelegt und sich darauf gesetzt. Und Laban durchtastete das ganze Zelt und fand nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Und sie sprach zu ihrem Vater: Mein Herr möge nicht zürnen, daß ich nicht vor dir aufstehen kann; denn es ergeht mir nach der Weiber Weise. Und er durchsuchte alles und fand die Teraphim nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Da entbrannte Jakob und haderte mit Laban. Und Jakob antwortete und sprach zu Laban: Was ist mein Vergehen, was meine Sünde, daß du mir hitzig nachgesetzt bist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Da du all mein Gerät durchtastet hast, was hast du gefunden von allem Gerät deines Hauses? Lege es hierher vor meine Brüder und deine Brüder, und sie mögen zwischen uns beiden entscheiden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Zwanzig Jahre bin ich nun bei dir gewesen; deine Mutterschafe und deine Ziegen haben nicht fehlgeboren, und die Widder deiner Herde habe ich nicht gegessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Das Zerrissene habe ich nicht zu dir gebracht, ich habe es büßen müssen; von meiner Hand hast du es gefordert, mochte es gestohlen sein bei Tage oder gestohlen bei Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Es war mit mir also: des Tages verzehrte mich die Hitze und der Frost des Nachts, und mein Schlaf floh von meinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Zwanzig Jahre bin ich nun in deinem Hause gewesen; ich habe dir vierzehn Jahre gedient um deine beiden Töchter und sechs Jahre um deine Herde, und du hast meinen Lohn zehnmal verändert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Wenn nicht der Gott meines Vaters, der Gott Abrahams, und die Furcht Isaaks, für mich gewesen wäre, gewiß, du würdest mich jetzt leer entlassen haben. Gott hat mein Elend und die Arbeit meiner Hände angesehen und hat gestern Nacht entschieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Und Laban antwortete und sprach zu Jakob: Die Töchter sind meine Töchter, und die Söhne sind meine Söhne, und die Herde ist meine Herde, und alles, was du siehest, ist mein; aber meinen Töchtern, was könnte ich ihnen heute tun, oder ihren Söhnen, die sie geboren haben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Und nun komm, laß uns einen Bund machen, ich und du, und er sei zum Zeugnis zwischen mir und dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Und Jakob nahm einen Stein und richtete ihn auf als Denkmal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Und Jakob sprach zu seinen Brüdern: Sammelt Steine! Und sie nahmen Steine und errichteten einen Haufen und aßen daselbst auf dem Haufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Und Laban nannte ihn Jegar Sahadutha, und Jakob nannte ihn Galed.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Und Laban sprach: Dieser Haufe sei heute ein Zeuge zwischen mir und dir! Darum gab man ihm den Namen Galed,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'und Mizpa, weil er sprach: Jehova sei Wächter zwischen mir und dir, wenn wir einer vor dem anderen verborgen sein werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Wenn du meine Töchter bedrücken, und wenn du noch Weibern nehmen solltest zu meinen Töchtern... kein Mensch ist bei uns; siehe, Gott ist Zeuge zwischen mir und dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Und Laban sprach zu Jakob: Siehe, dieser Haufe, und siehe, das Denkmal, das ich errichtet habe zwischen mir und dir:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'dieser Haufe sei Zeuge und das Denkmal ein Zeugnis, daß weder ich über diesen Haufen zu dir hinausgehe, noch daß du über diesen Haufen und dieses Denkmal zu mir hinausgehest zum Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Der Gott Abrahams und der Gott Nahors richte zwischen uns, der Gott ihres Vaters! Da schwur Jakob bei der Furcht seines Vaters Isaak.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Und Jakob opferte ein Schlachtopfer auf dem Gebirge und lud seine Brüder ein, zu essen; und sie aßen und übernachteten auf dem Gebirge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Und Laban stand des Morgens früh auf und küßte seine Söhne und seine Töchter und segnete sie; und Laban zog hin und kehrte zurück an seinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Und Jakob zog seines Weges, und es begegneten ihm Engel Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Und Jakob sprach, als er sie sah: Dies ist das Heerlager Gottes. Und er gab jenem Orte den Namen Machanaim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Und Jakob sandte Boten vor sich her zu seinem Bruder Esau, in das Land Seir, das Gefilde Edom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Und er gebot ihnen und sprach: So sollt ihr zu meinem Herrn, zu Esau, sprechen: So spricht dein Knecht Jakob: Bei Laban habe ich mich aufgehalten und bin geblieben bis jetzt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'und ich habe Rinder und Esel, Kleinvieh und Knechte und Mägde erworben; und ich habe gesandt, es meinem Herrn kundzutun, um Gnade zu finden in deinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Und die Boten kehrten zu Jakob zurück und sprachen: Wir sind zu deinem Bruder, zu Esau, gekommen, und er zieht dir auch entgegen und vierhundert Mann mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Da fürchtete sich Jakob sehr, und ihm ward angst; und er teilte das Volk, das bei ihm war, und das Kleinvieh und die Rinder und die Kamele in zwei Züge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Und er sprach: Wenn Esau wider den einen Zug kommt und ihn schlägt, so wird der übriggebliebene Zug entrinnen können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Und Jakob sprach: Gott meines Vaters Abraham und Gott meines Vaters Isaak, Jehova, der du zu mir geredet hast: Kehre zurück in dein Land und zu deiner Verwandtschaft, und ich will dir wohltun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Ich bin zu gering all der Gütigkeiten und all der Treue, die du deinem Knechte erwiesen hast; denn mit meinem Stabe bin ich über diesen Jordan gegangen, und nun bin ich zu zwei Zügen geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Rette mich doch von der Hand meines Bruders, von der Hand Esaus! Denn ich fürchte ihn, daß er etwa komme und mich schlage, die Mutter samt den Kindern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Du hast ja gesagt: Gewißlich werde ich dir wohltun und werde deinen Samen machen wie den Sand des Meeres, der nicht gezählt wird vor Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Und er übernachtete daselbst in jener Nacht; und er nahm von dem, was in seine Hand gekommen war, ein Geschenk für seinen Bruder Esau:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Zweihundert Ziegen und zwanzig Böcke, zweihundert Mutterschafe und zwanzig Widder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'dreißig säugende Kamele mit ihren Füllen, vierzig Kühe und zehn Stiere, zwanzig Eselinnen und zehn junge Esel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Und er gab sie in die Hand seiner Knechte, je eine Herde besonders, und er sprach zu seinen Knechten: Ziehet vor mir her und lasset Raum zwischen Herde und Herde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Und er gebot dem ersten und sprach: Wenn mein Bruder Esau dir begegnet und dich fragt und spricht: Wem gehörst du an, und wohin gehst du, und wem gehören diese da vor dir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'so sollst du sagen: Deinem Knechte Jakob; es ist ein Geschenk, gesandt meinem Herrn, dem Esau; und siehe, er selbst ist hinter uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Und er gebot auch dem zweiten, auch dem dritten, auch allen, die hinter den Herden hergingen, und sprach: Nach diesem Worte sollt ihr zu Esau reden, wenn ihr ihn findet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'und sollt sagen: Siehe, dein Knecht Jakob ist selbst hinter uns. Denn er sagte: Ich will ihn versöhnen durch das Geschenk, das vor mir hergeht, und danach will ich sein Angesicht sehen; vielleicht wird er mich annehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Und das Geschenk zog vor ihm her, und er übernachtete in jener Nacht im Lager.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Und er stand in jener Nacht auf und nahm seine zwei Weiber und seine zwei Mägde und seine elf Söhne und zog über die Furt des Jabbok;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'und er nahm sie und führte sie über den Fluß und führte hinüber, was er hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Und Jakob blieb allein übrig; und es rang ein Mann mit ihm, bis die Morgenröte aufging.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Und als er sah, daß er ihn nicht übermochte, da rührte er sein Hüftgelenk an; und das Hüftgelenk Jakobs ward verrenkt, indem er mit ihm rang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Da sprach er: Laß mich los, denn die Morgenröte ist aufgegangen; und er sprach: Ich lasse dich nicht los, du habest mich denn gesegnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Da sprach er zu ihm: Was ist dein Name? Und er sprach: Jakob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Da sprach er: Nicht Jakob soll hinfort dein Name heißen, sondern Israel; denn du hast mit Gott und mit Menschen gerungen und hast obsiegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Und Jakob fragte und sprach: Tue mir doch deinen Namen kund! Da sprach er: Warum doch fragst du nach meinem Namen? Und er segnete ihn daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Und Jakob gab dem Orte den Namen Pniel: denn ich habe Gott von Angesicht zu Angesicht gesehen, und meine Seele ist gerettet worden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Und die Sonne ging ihm auf, als er über Pniel hinaus war; und er hinkte an seiner Hüfte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Darum essen die Kinder Israel nicht die Spannader, die über dem Hüftgelenk ist, bis auf den heutigen Tag, weil er das Hüftgelenk Jakobs, die Spannader, angerührt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Und Jakob hob seine Augen auf und sah: und siehe, Esau kam und mit ihm vierhundert Mann. Und er verteilte die Kinder auf Lea und auf Rahel und auf die beiden Mägde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'und er stellte die Mägde und ihre Kinder vornan und Lea und ihre Kinder dahinter und Rahel und Joseph zuletzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Er aber ging vor ihnen her und beugte sich siebenmal zur Erde nieder, bis er nahe zu seinem Bruder kam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Und Esau lief ihm entgegen und umarmte ihn und fiel ihm um den Hals und küßte ihn; und sie weinten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Und er hob seine Augen auf und sah die Weiber und die Kinder und sprach: Wer sind diese bei dir? Und er sprach: Die Kinder, die Gott deinem Knechte beschert hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Und die Mägde traten herzu, sie und ihre Kinder, und verneigten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Und auch Lea trat herzu und ihre Kinder, und sie verneigten sich. Und danach traten Joseph und Rahel herzu und verneigten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Und er sprach: Was willst du mit diesem ganzen Zug, dem ich begegnet bin? Und er sprach: Daß ich Gnade fände in den Augen meines Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Da sprach Esau: Ich habe genug, mein Bruder; es sei dein, was du hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Und Jakob sprach: Nicht doch; wenn ich anders Gnade gefunden habe in deinen Augen, so nimm mein Geschenk von meiner Hand, da ich nun einmal dein Angesicht gesehen habe, als hätte ich Gottes Angesicht gesehen, und du Wohlgefallen an mir gehabt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Nimm doch mein Geschenk, das dir überbracht worden ist; denn Gott hat es mir beschert, und ich habe alles. Und er drang in ihn, und er nahm es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Und Esau sprach: Laß uns aufbrechen und weiterziehen, und ich will vor dir herziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Und er sprach zu ihm: Mein Herr weiß, daß die Kinder zart sind und daß ich säugende Schafe und Kühe bei mir habe; wenn man sie nur einen Tag übertriebe, so würde die ganze Herde sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Mein Herr ziehe doch vor seinem Knechte hin, und ich will einherziehen nach meiner Gemächlichkeit, nach dem Gange des Viehes, das vor mir ist, und nach dem Gange der Kinder, bis ich zu meinem Herrn komme nach Seir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Und Esau sprach: Ich will doch von dem Volke bei dir zurücklassen, das bei mir ist. Und er sprach: Wozu das? Möchte ich Gnade finden in den Augen meines Herrn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Und Esau kehrte an selbigem Tage seines Weges zurück nach Seir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Und Jakob brach auf nach Sukkoth und baute sich ein Haus, und seinem Vieh machte er Hütten; darum gab er dem Orte den Namen Sukkoth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Und Jakob kam wohlbehalten nach der Stadt Sichem, die im Lande Kanaan ist, als er aus Paddan-Aram kam, und lagerte vor der Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Und er kaufte das Stück Feld, wo er sein Zelt aufgeschlagen hatte, von der Hand der Söhne Hemors, des Vaters Sichems, um hundert Kesita.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Und er richtete daselbst einen Altar auf und nannte ihn: Gott, der Gott Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Und Dina, die Tochter Leas, die sie dem Jakob geboren hatte, ging aus, die Töchter des Landes zu sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Und es sah sie Sichem, der Sohn Hemors, des Hewiters, des Fürsten des Landes, und er nahm sie und lag bei ihr und schwächte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Und seine Seele hing an Dina, der Tochter Jakobs, und er liebte das Mädchen und redete zum Herzen des Mädchens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Und Sichem sprach zu Hemor, seinem Vater, und sagte: Nimm mir dieses Mädchen zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Und Jakob hörte, daß er seine Tochter Dina entehrt hatte; seine Söhne aber waren mit seinem Vieh auf dem Felde, und Jakob schwieg, bis sie kamen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Und Hemor, der Vater Sichems, kam heraus zu Jakob, um mit ihm zu reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Und die Söhne Jakobs kamen vom Felde, sobald sie es hörten; und die Männer kränkten sich und ergrimmten sehr, weil er eine Schandtat in Israel verübt hatte, bei der Tochter Jakobs zu liegen; und also sollte nicht geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Und Hemor redete mit ihnen und sprach: Sichem, mein Sohn, seine Seele hängt an eurer Tochter: Gebet sie ihm doch zum Weibe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'und verschwägert euch mit uns: gebet uns eure Töchter und nehmet euch unsere Töchter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'und wohnet bei uns, und das Land soll vor euch sein: wohnet und verkehret darin, und machet euch darin ansässig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Und Sichem sprach zu ihrem Vater und zu ihren Brüdern: Möge ich Gnade finden in euren Augen! Und was ihr mir sagen werdet, will ich geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Leget mir sehr viel auf als Heiratsgabe und Geschenk, und ich will es geben, so wie ihr mir sagen werdet; und gebet mir das Mädchen zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Und die Söhne Jakobs antworteten Sichem und seinem Vater Hemor betrüglich und redeten, weil er ihre Schwester Dina entehrt hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Und sie sprachen zu ihm: Wir können dies nicht tun, unsere Schwester einem unbeschnittenen Manne zu geben, denn das wäre eine Schande für uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Nur unter der Bedingung wollen wir euch zu Willen sein, wenn ihr werdet wie wir, indem alles Männliche bei euch beschnitten wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'dann wollen wir euch unsere Töchter geben und eure Töchter uns nehmen, und wir wollen bei euch wohnen und ein Volk sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Wenn ihr aber nicht auf uns höret, euch beschneiden zu lassen, so nehmen wir unsere Tochter und ziehen weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Und ihre Worte waren gut in den Augen Hemors und Sichems, des Sohnes Hemors.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Und der Jüngling zögerte nicht, dies zu tun, denn er hatte Gefallen an der Tochter Jakobs. Und er war geehrt vor allen im Hause seines Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Und Hemor und Sichem, sein Sohn, kamen in das Tor ihrer Stadt, und sie redeten zu den Männern ihrer Stadt und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Diese Männer sind friedlich gegen uns, so mögen sie im Lande wohnen und darin verkehren; und das Land, siehe, weit nach beiden Seiten ist es vor ihnen. Wir wollen uns ihre Töchter zu Weibern nehmen und unsere Töchter ihnen geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Nur unter der Bedingung wollen die Männer uns zu Willen sein, bei uns zu wohnen, ein Volk zu sein, wenn bei uns alles Männliche beschnitten werde, so wie sie beschnitten sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Ihre Herden und ihr Besitz und all ihr Vieh, werden die nicht unser sein? Nur laßt uns ihnen zu Willen sein, und sie werden bei uns wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Und sie hörten auf Hemor und auf Sichem, seinen Sohn, alle, die zum Tore seiner Stadt ausgingen; und alles Männliche wurde beschnitten, alle, die zum Tore seiner Stadt ausgingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Und es geschah am dritten Tage, als sie in Schmerzen waren, da nahmen die zwei Söhne Jakobs, Simeon und Levi, die Brüder Dinas, ein jeder sein Schwert und kamen kühn wider die Stadt und ermordeten alles Männliche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'auch Hemor und seinen Sohn Sichem ermordeten sie mit der Schärfe des Schwertes und nahmen Dina aus dem Hause Sichems und gingen davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Die Söhne Jakobs kamen über die Erschlagenen und plünderten die Stadt, weil sie ihre Schwester entehrt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Ihr Kleinvieh und ihre Rinder und ihre Esel und was in der Stadt und was auf dem Felde war, nahmen sie;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'und all ihr Vermögen und alle ihre Kinder und ihre Weiber führten sie gefangen hinweg und raubten sie und alles, was in den Häusern war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Da sprach Jakob zu Simeon und zu Levi: Ihr habt mich in Trübsal gebracht, indem ihr mich stinkend machet unter den Bewohnern des Landes, unter den Kanaanitern und unter den Perisitern. Ich aber bin ein zählbares Häuflein, und sie werden sich wider mich versammeln und mich schlagen, und ich werde vertilgt werden, ich und mein Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Und sie sprachen: Sollte man unsere Schwester wie eine Hure behandeln?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Und Gott sprach zu Jakob: Mache dich auf, ziehe hinauf nach Bethel und wohne daselbst, und mache daselbst einen Altar dem Gott, der dir erschienen ist, als du vor deinem Bruder Esau flohest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Da sprach Jakob zu seinem Hause und zu allen, die bei ihm waren: Tut die fremden Götter hinweg, die in eurer Mitte sind, und reiniget euch und wechselt eure Kleider;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'und wir wollen uns aufmachen und nach Bethel hinaufziehen, und ich werde daselbst einen Altar machen dem Gott, der mir geantwortet hat am Tage meiner Drangsal und mit mir gewesen ist auf dem Wege, den ich gewandelt bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Und sie gaben Jakob alle fremden Götter, die in ihrer Hand, und die Ringe, die in ihren Ohren waren, und Jakob vergrub sie unter der Terebinthe, die bei Sichem ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Und sie brachen auf. Und der Schrecken Gottes kam über die Städte, die rings um sie her waren, so daß sie den Söhnen Jakobs nicht nachjagten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Und Jakob kam nach Lus, welches im Lande Kanaan liegt, das ist Bethel, er und alles Volk, das bei ihm war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Und er baute daselbst einen Altar und nannte den Ort El-Bethel: denn Gott hatte sich ihm daselbst geoffenbart, als er vor seinem Bruder floh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Und Debora, die Amme Rebekkas, starb, und sie wurde begraben unterhalb Bethel unter der Eiche; und man gab ihr den Namen Allon Bakuth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Und Gott erschien dem Jakob wiederum, als er aus Paddan-Aram kam, und segnete ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Und Gott sprach zu ihm: Dein Name ist Jakob; dein Name soll hinfort nicht Jakob heißen, sondern Israel soll dein Name sein. Und er gab ihm den Namen Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Und Gott sprach zu ihm: Ich bin Gott, der Allmächtige, sei fruchtbar und mehre dich; eine Nation und ein Haufe von Nationen soll aus dir werden, und Könige sollen aus deinen Lenden hervorkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Und das Land, das ich Abraham und Isaak gegeben habe, dir will ich es geben, und deinem Samen nach dir will ich das Land geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Und Gott fuhr von ihm auf an dem Orte, wo er mit ihm geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Und Jakob richtete ein Denkmal auf an dem Orte, wo er mit ihm geredet hatte, ein Denkmal von Stein, und spendete darauf ein Trankopfer und goß Öl darauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Und Jakob gab dem Orte, woselbst Gott mit ihm geredet hatte, den Namen Bethel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Und sie brachen auf von Bethel. Und es war noch eine Strecke Landes, um nach Ephrath zu kommen, da gebar Rahel, und es wurde ihr schwer bei ihrem Gebären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Und es geschah, als es ihr schwer wurde bei ihrem Gebären, da sprach die Hebamme zu ihr: Fürchte dich nicht, denn auch dieser ist dir ein Sohn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Und es geschah, als ihre Seele ausging (denn sie starb), da gab sie ihm den Namen Benoni; sein Vater aber nannte ihn Benjamin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Und Rahel starb und wurde begraben an dem Wege nach Ephrath, das ist Bethlehem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Und Jakob richtete über ihrem Grabe ein Denkmal auf, das ist das Grabmal Rahels bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Und Israel brach auf und schlug sein Zelt auf jenseit von Migdal-Heder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Und es geschah, als Israel in jenem Lande wohnte, da ging Ruben hin und lag bei Bilha, dem Kebsweibe seines Vaters. Und Israel hörte es. Und der Söhne Jakobs waren zwölf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Die Söhne Leas: Ruben, der Erstgeborene Jakobs, und Simeon und Levi und Juda und Issaschar und Sebulon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Die Söhne Rahels: Joseph und Benjamin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Die Söhne Bilhas, der Magd Rahels: Dan und Naphtali.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Und die Söhne Silpas, der Magd Leas: Gad und Aser. Das sind die Söhne Jakobs, welche ihm in Paddan-Aram geboren wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Und Jakob kam zu seinem Vater Isaak nach Mamre, nach Kirjath-Arba, das ist Hebron, woselbst Abraham und Isaak als Fremdlinge geweilt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Und die Tage Isaaks waren hundertachtzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Und Isaak verschied und starb und wurde versammelt zu seinen Völkern, alt und der Tage satt. Und Esau und Jakob, seine Söhne, begruben ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Und dies sind die Geschlechter Esaus, das ist Edom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau nahm seine Weiber von den Töchtern Kanaans: Ada, die Tochter Elons, des Hethiters, und Oholibama, die Tochter Anas, der Tochter Zibeons, des Hewiters,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'und Basmath, die Tochter Ismaels, die Schwester Nebajoths.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Und Ada gebar dem Esau Eliphas, und Basmath gebar Reghuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Und Oholibama gebar Jeghusch und Jaghlam und Korach. Das sind die Söhne Esaus, welche ihm im Lande Kanaan geboren wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Und Esau nahm seine Weiber und seine Söhne und seine Töchter und alle Seelen seines Hauses, und seine Herden und all sein Vieh und all sein Besitztum, das er im Lande Kanaan erworben hatte, und zog in ein Land, von seinem Bruder Jakob hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Denn ihre Habe war zu groß, daß sie hätten beieinander wohnen können, und das Land ihres Aufenthaltes vermochte sie nicht zu tragen wegen ihrer Herden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Und Esau wohnte auf dem Gebirge Seir. Esau, das ist Edom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Und dies sind die Geschlechter Esaus, des Vaters von Edom, auf dem Gebirge Seir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Dies sind die Namen der Söhne Esaus: Eliphas, der Sohn Adas, des Weibes Esaus; Reghuel, der Sohn Basmaths, des Weibes Esaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Und die Söhne des Eliphas waren: Teman, Omar, Zepho und Gaetam und Kenas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Und Timna war das Kebsweib des Eliphas, des Sohnes Esaus, und sie gebar dem Eliphas Amalek. Das sind die Söhne Adas, des Weibes Esaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Und dies sind die Söhne Reghuels: Nachath und Serach, Schamma und Missa. Das waren die Söhne Basmaths, des Weibes Esaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Und dies waren die Söhne Oholibamas, der Tochter Anas, der Tochter Zibeons, des Weibes Esaus: sie gebar dem Esau Jeghusch, Jaghlam und Korach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Dies sind die Fürsten der Söhne Esaus: Die Söhne Eliphas\', des Erstgeborenen Esaus: der Fürst Teman, der Fürst Omar, der Fürst Zepho, der Fürst Kenas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'der Fürst Korach, der Fürst Gaetam, der Fürst Amalek. Das sind die Fürsten des Eliphas im Lande Edom; das sind die Söhne Adas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Und dies sind die Söhne Reghuels, des Sohnes Esaus: der Fürst Nachath, der Fürst Serach, der Fürst Schamma, der Fürst Missa. Das sind die Fürsten des Reghuel im Lande Edom; das sind die Söhne Basmaths, des Weibes Esaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Und dies sind die Söhne Oholibamas, des Weibes Esaus: der Fürst Jeghusch, der Fürst Jaghlam, der Fürst Korach. Das sind die Fürsten Oholibamas, der Tochter Anas, des Weibes Esaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Das sind die Söhne Esaus und das ihre Fürsten; das ist Edom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Das sind die Söhne Seirs, des Horiters, die Bewohner des Landes: Lotan und Schobal und Zibeon und Ana und Dischon und Ezer und Dischan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Das sind die Fürsten der Horiter, der Söhne Seirs, im Lande Edom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Und die Söhne Lotans waren: Hori und Hemam, und die Schwester Lotans: Timna.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Und dies sind die Söhne Schobals: Alwan und Manachath und Ebal, Schepho und Onam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Und dies sind die Söhne Zibeons: Aja und Ana. Das ist der Ana, welcher die warmen Quellen in der Wüste fand, als er die Esel Zibeons, seines Vaters, weidete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Und dies sind die Söhne Anas: Dischon, und Oholibama, die Tochter Anas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Und dies sind die Söhne Dischons: Hemdan und Eschban und Jithran und Keran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Dies sind die Söhne Ezers: Bilhan und Saawan und Akan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Dies sind die Söhne Dischans: Uz und Aran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Dies sind die Fürsten der Horiter: der Fürst Lotan, der Fürst Schobal, der Fürst Zibeon, der Fürst Ana,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'der Fürst Dischon, der Fürst Ezer, der Fürst Dischan. Das sind die Fürsten der Horiter, nach ihren Fürsten im Lande Seir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Und dies sind die Könige, die im Lande Edom regiert haben, ehe ein König über die Kinder Israel regierte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela, der Sohn Beors, wurde König in Edom, und der Name seiner Stadt war Dinhaba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Und Bela starb; und es ward König an seiner Statt Jobab, der Sohn Serachs, aus Bozra.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Und Jobab starb; und es ward König an seiner Statt Huscham, aus dem Lande der Temaniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Und Huscham starb; und es ward König an seiner Statt Hadad, der Sohn Bedads, welcher Midian schlug im Gefilde Moabs; und der Name seiner Stadt war Awith.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Und Hadad starb; und es ward König an seiner Statt Samla aus Masreka.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Und Samla starb; und es ward König an seiner Statt Saul aus Rechoboth am Strome.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Und Saul starb, und es ward König an seiner Statt Baal-Hanan, der Sohn Akbors.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Und Baal-Hanan, der Sohn Akbors, starb; und es ward König an seiner Statt Hadar; und der Name seiner Stadt war Paghu, und der Name seines Weibes Mehetabeel, die Tochter Matreds, der Tochter Mesahabs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Und dies sind die Namen der Fürsten Esaus, nach ihren Familien, nach ihren Ortschaften, mit ihren Namen: der Fürst Timna, der Fürst Alwa, der Fürst Jetheth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'der Fürst Oholibama, der Fürst Ela, der Fürst Pinon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'der Fürst Kenas, der Fürst Teman, der Fürst Mibzar,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'der Fürst Magdiel, der Fürst Iram. Das sind die Fürsten von Edom nach ihren Wohnsitzen, im Lande ihres Eigentums. Das ist Esau, der Vater Edoms.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Und Jakob wohnte in dem Lande, in welchem sein Vater als Fremdling geweilt hatte, im Lande Kanaan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Dies ist die Geschichte Jakobs: Joseph, siebzehn Jahre alt, weidete die Herde mit seinen Brüdern; und er war als Knabe bei den Söhnen Bilhas und bei den Söhnen Silpas, der Weiber seines Vaters. Und Joseph hinterbrachte ihrem Vater die üble Nachrede von ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Und Israel hatte Joseph lieber als alle seine Söhne, weil er der Sohn seines Alters war; und er machte ihm einen langen Leibrock.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Und als seine Brüder sahen, daß ihr Vater ihn lieber hatte als alle seine Brüder, da haßten sie ihn und vermochten nicht, ihn zu grüßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Und Joseph hatte einen Traum und teilte ihn seinen Brüdern mit; und sie haßten ihn noch mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Und er sprach zu ihnen: Höret doch diesen Traum, den ich gehabt habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Siehe, wir banden Garben auf dem Felde, und siehe, meine Garbe richtete sich auf und blieb auch aufrecht stehen; und siehe, eure Garben kamen ringsum und verneigten sich vor meiner Garbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Da sprachen seine Brüder zu ihm: Solltest du gar König über uns sein, solltest du gar über uns herrschen? Und sie haßten ihn noch mehr um seiner Träume und um seiner Worte willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Und er hatte noch einen anderen Traum und erzählte ihn seinen Brüdern und sprach: Siehe, noch einen Traum habe ich gehabt, und siehe, die Sonne und der Mond und elf Sterne beugten sich vor mir nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Und er erzählte es seinem Vater und seinen Brüdern. Da schalt ihn sein Vater und sprach zu ihm: Was ist das für ein Traum, den du gehabt hast? Sollen wir gar kommen, ich und deine Mutter und deine Brüder, um uns vor dir zur Erde niederzubeugen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Und seine Brüder waren eifersüchtig auf ihn; aber sein Vater bewahrte das Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Und seine Brüder gingen hin, um die Herde ihres Vaters zu weiden zu Sichem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Und Israel sprach zu Joseph: Weiden nicht deine Brüder zu Sichem? Komm, daß ich dich zu ihnen sende! Und er sprach zu ihm: Hier bin ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Und er sprach zu ihm: Gehe doch hin, sieh nach dem Wohlergehen deiner Brüder und nach dem Wohlergehen der Herde und bringe mir Antwort. Und er sandte ihn aus dem Tale von Hebron, und er kam nach Sichem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Und ein Mann fand ihn, und siehe, er irrte auf dem Felde umher; und der Mann fragte ihn und sprach: Was suchst du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Und er sprach: Ich suche meine Brüder; tue mir doch kund, wo sie weiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Und der Mann sprach: Sie sind von hier aufgebrochen, denn ich hörte sie sagen: Laßt uns nach Dothan ziehen! Da ging Joseph seinen Brüdern nach und fand sie zu Dothan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Und sie sahen ihn von ferne; und ehe er ihnen nahte, da ersannen sie gegen ihn den Anschlag, ihn zu töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Und sie sprachen einer zum anderen: Siehe, da kommt jener Träumer!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'So kommt nun und laßt uns ihn erschlagen und ihn in eine der Gruben werfen, und wir wollen sagen: Ein böses Tier hat ihn gefressen; und wir werden sehen, was aus seinen Träumen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Und Ruben hörte es und errettete ihn aus ihrer Hand und sprach: Laßt uns ihn nicht totschlagen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Und Ruben sprach zu ihnen: Vergießet nicht Blut; werfet ihn in diese Grube, die in der Wüste ist, und leget nicht Hand an ihn auf daß er ihn aus ihrer Hand errettete, um ihn wieder zu seinem Vater zu bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Und es geschah, als Joseph zu seinen Brüdern kam, da zogen sie Joseph seinen Leibrock aus, den langen Leibrock, den er anhatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'und sie nahmen ihn und warfen ihn in die Grube; die Grube aber war leer, es war kein Wasser darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Und sie setzten sich, um zu essen. Und sie hoben ihre Augen auf und sahen: und siehe, ein Zug Ismaeliter kam von Gilead her; und ihre Kamele trugen Tragant und Balsamharz und Ladanum; sie zogen hin, um es nach Ägypten hinabzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Da sprach Juda zu seinen Brüdern: Was für ein Gewinn ist es, daß wir unseren Bruder erschlagen und sein Blut verhehlen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Kommt, laßt uns ihn an die Ismaeliter verkaufen; aber unsere Hand sei nicht an ihm, denn unser Bruder, unser Fleisch ist er! Und seine Brüder hörten darauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Als nun die midianitischen Männer, die Kaufleute, vorüberkamen, da zogen und holten sie Joseph aus der Grube herauf und verkauften Joseph an die Ismaeliter um zwanzig Silbersekel; und sie brachten Joseph nach Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Und als Ruben zur Grube zurückkam, und siehe, Joseph war nicht in der Grube, da zerriß er seine Kleider.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Und er kehrte zu seinen Brüdern zurück und sprach: Der Knabe ist nicht da, und ich, wohin soll ich gehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Und sie nahmen den Leibrock Josephs und schlachteten einen Ziegenbock und tauchten den Leibrock in das Blut;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'und sie schickten den langen Leibrock hin und ließen ihn ihrem Vater bringen und sagen: Dieses haben wir gefunden; erkenne doch, ob es der Leibrock deines Sohnes ist oder nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Und er erkannte ihn und sprach: Der Leibrock meines Sohnes! Ein böses Tier hat ihn gefressen, Joseph ist gewißlich zerrissen worden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Und Jakob zerriß seine Kleider und legte Sacktuch um seine Lenden, und er trug Leid um seinen Sohn viele Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Und alle seine Söhne und alle seine Töchter machten sich auf, um ihn zu trösten; aber er verweigerte es, sich trösten zu lassen, und sprach: Denn leidtragend werde ich zu meinem Sohne hinabfahren in den Scheol! Und sein Vater beweinte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Und die Midianiter verkauften ihn nach Ägypten, an Potiphar, einen Kämmerer des Pharao, den Obersten der Leibwache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Und es geschah zu selbiger Zeit, daß Juda von seinen Brüdern hinabzog und zu einem Manne von Adullam einkehrte mit Namen Hira.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Und Juda sah daselbst die Tochter eines kanaanitischen Mannes mit Namen Schua; und er nahm sie und ging zu ihr ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Und sie wurde schwanger und gebar einen Sohn, und er gab ihm den Namen Gher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Und sie wurde abermals schwanger und gebar einen Sohn, und sie gab ihm den Namen Onan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Und wiederum gebar sie einen Sohn, und sie gab ihm den Namen Schela; Juda war aber zu Kesib, als sie ihn gebar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Und Juda nahm ein Weib für Gher, seinen Erstgeborenen, und ihr Name war Tamar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Und Gher, der Erstgeborene Judas, war böse in den Augen Jehovas, und Jehova tötete ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Da sprach Juda zu Onan: Gehe ein zu dem Weibe deines Bruders, und leiste ihr die Schwagerpflicht und erwecke deinem Bruder Samen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Da aber Onan wußte, daß der Same nicht sein eigen sein sollte, so geschah es, wenn er zu dem Weibe seines Bruders einging, daß er ihn verderbte zur Erde, um seinem Bruder keinen Samen zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Und es war übel in den Augen Jehovas, was er tat; und er tötete auch ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Da sprach Juda zu Tamar, seiner Schwiegertochter: Bleibe Witwe im Hause deines Vaters, bis mein Sohn Schela groß sein wird. Denn er sagte: Daß nicht auch er sterbe wie seine Brüder! Und Tamar ging hin und blieb im Hause ihres Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Als der Tage viele geworden, da starb die Tochter Schuas, das Weib Judas. Und als Juda getröstet war, ging er zu seinen Schafscherern hinauf, er und Hira, sein Freund, der Adullamiter, nach Timna.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Und es wurde der Tamar berichtet und gesagt: Siehe, dein Schwiegervater geht nach Timna hinauf, um seine Schafe zu scheren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Da legte sie die Kleider ihrer Witwenschaft von sich und bedeckte sich mit einem Schleier und verhüllte sich; und sie setzte sich an den Eingang von Enaim, das am Wege nach Timna liegt; denn sie sah, daß Schela groß geworden war und sie ihm nicht zum Weibe gegeben wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Und Juda sah sie und hielt sie für eine Hure, denn sie hatte ihr Angesicht bedeckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Und er bog zu ihr ab in den Weg und sprach: Wohlan, laß mich zu dir eingehen! Denn er wußte nicht, daß sie seine Schwiegertochter war. Und sie sprach: Was willst du mir geben, daß du zu mir eingehst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Da sprach er: Ich will dir ein Ziegenböcklein von der Herde senden. Und sie sprach: Wenn du ein Pfand gibst, bis du es sendest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Und er sprach: Was für ein Pfand soll ich dir geben? Und sie sprach: Deinen Siegelring und deine Schnur und deinen Stab, der in deiner Hand ist. Da gab er es ihr und ging zu ihr ein, und sie ward schwanger von ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Und sie stand auf und ging hin, und sie legte ihren Schleier von sich und zog die Kleider ihrer Witwenschaft an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Und Juda sandte das Ziegenböcklein durch die Hand seines Freundes, des Adullamiters, um das Pfand aus der Hand des Weibes zu nehmen; aber er fand sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Und er fragte die Leute ihres Ortes und sprach: Wo ist jene Buhlerin, die zu Enaim am Wege war? Und sie sprachen: Hier ist keine Buhlerin gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Und er kehrte zu Juda zurück und sprach: Ich habe sie nicht gefunden, und auch sagten die Leute des Ortes: Hier ist keine Buhlerin gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Da sprach Juda: Sie behalte es für sich, daß wir nicht zum Gespött werden; siehe, ich habe dieses Böcklein gesandt, und du hast sie ja nicht gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Und es geschah nach etwa drei Monaten, da wurde dem Juda berichtet und gesagt: Tamar, deine Schwiegertochter, hat gehurt, und siehe, sie ist auch schwanger von Hurerei. Da sprach Juda: Führet sie hinaus, daß sie verbrannt werde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Als sie hinausgeführt wurde, da sandte sie zu ihrem Schwiegervater und ließ ihm sagen: Von dem Manne, dem dieses gehört, bin ich schwanger; und sie sprach: Erkenne doch, wem dieser Siegelring und diese Schnur und dieser Stab gehören!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Und Juda erkannte es und sprach: Sie ist gerechter als ich, darum daß ich sie nicht meinem Sohne Schela gegeben habe; und er erkannte sie hinfort nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Und es geschah zur Zeit, als sie gebären sollte, siehe, da waren Zwillinge in ihrem Leibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Und es geschah, während sie gebar, da streckte einer die Hand heraus, und die Hebamme nahm sie und band einen Karmesinfaden um seine Hand und sprach: Dieser ist zuerst herausgekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Und es geschah, als er seine Hand zurückzog, siehe, da kam sein Bruder heraus; und sie sprach: Wie bist du durchgebrochen! Auf dir sei der Bruch! Und man gab ihm den Namen Perez.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Und danach kam sein Bruder heraus, um dessen Hand der Karmesinfaden war, und man gab ihm den Namen Serach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Und Joseph wurde nach Ägypten hinabgeführt; und Potiphar, ein Kämmerer des Pharao, der Oberste der Leibwache, ein ägyptischer Mann, kaufte ihn aus der Hand der Ismaeliter, die ihn dorthin hinabgeführt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Und Jehova war mit Joseph, und er war ein Mann, dem alles gelang; und er war im Hause seines Herrn, des Ägypters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Und sein Herr sah, daß Jehova mit ihm war und daß Jehova alles, was er tat, in seiner Hand gelingen ließ.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Und Joseph fand Gnade in seinen Augen und diente ihm; und er bestellte ihn über sein Haus, und alles, was er hatte, gab er in seine Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Und es geschah, seitdem er ihn über sein Haus bestellt und über alles, was er hatte, daß Jehova das Haus des Ägypters segnete um Josephs willen; und der Segen Jehovas war auf allem, was er hatte, im Hause und auf dem Felde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Und er überließ alles, was er hatte, der Hand Josephs und kümmerte sich um gar nichts bei ihm, außer um das Brot, das er aß. Und Joseph war schön von Gestalt und schön von Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Und es geschah nach diesen Dingen, da warf das Weib seines Herrn ihre Augen auf Joseph und sprach: Liege bei mir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Er aber weigerte sich und sprach zu dem Weibe seines Herrn: Siehe, mein Herr kümmert sich um nichts bei mir im Hause; und alles, was er hat, hat er in meine Hand gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Niemand ist größer in diesem Hause als ich, und er hat mir gar nichts vorenthalten als nur dich, indem du sein Weib bist; und wie sollte ich dieses große Übel tun und wider Gott sündigen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Und es geschah, als sie Joseph Tag für Tag ansprach und er nicht auf sie hörte, bei ihr zu liegen, bei ihr zu sein,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'da geschah es an einem solchen Tage, daß er ins Haus ging, um sein Geschäft zu besorgen, und kein Mensch von den Leuten des Hauses war daselbst im Hause;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'und sie ergriff ihn bei seinem Kleide und sprach: Liege bei mir! Er aber ließ sein Kleid in ihrer Hand und floh und lief hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Und es geschah, als sie sah, daß er sein Kleid in ihrer Hand gelassen hatte und hinausgeflohen war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'da rief sie den Leuten ihres Hauses und sprach zu ihnen und sagte: Sehet, er hat uns einen hebräischen Mann hergebracht, um Spott mit uns zu treiben. Er ist zu mir gekommen, um bei mir zu liegen, und ich habe mit lauter Stimme gerufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Und es geschah, als er hörte, daß ich meine Stimme erhob und rief, da ließ er sein Kleid neben mir und floh und ging hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Und sie legte sein Kleid neben sich, bis sein Herr nach Hause kam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Und sie redete zu ihm nach diesen Worten und sprach: Der hebräische Knecht, den du uns hergebracht hast, ist zu mir gekommen, um Spott mit mir zu treiben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'und es geschah, als ich meine Stimme erhob und rief, da ließ er sein Kleid neben mir und floh hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Und es geschah, als sein Herr die Worte seines Weibes hörte, die sie zu ihm redete, indem sie sprach: Nach diesen Worten hat mir dein Knecht getan, da entbrannte sein Zorn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Und Josephs Herr nahm ihn und legte ihn in die Feste, an den Ort, wo die Gefangenen des Königs gefangen lagen; und er war daselbst in der Feste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Und Jehova war mit Joseph und wandte ihm Güte zu und gab ihm Gnade in den Augen des Obersten der Feste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Und der Oberste der Feste übergab alle Gefangenen, die in der Feste waren, der Hand Josephs; und alles, was daselbst zu tun war, das tat er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Der Oberste der Feste sah nicht nach dem Geringsten, das unter seiner Hand war, weil Jehova mit ihm war; und was er tat, ließ Jehova gelingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Und es geschah nach diesen Dingen, da versündigten sich der Schenke des Königs von Ägypten und der Bäcker gegen ihren Herrn, den König von Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Und der Pharao ward sehr zornig über seine beiden Kämmerer, über den Obersten der Schenken und über den Obersten der Bäcker;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'und er setzte sie in Gewahrsam in das Haus des Obersten der Leibwache, in die Feste, an den Ort, wo Joseph gefangen lag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Und der Oberste der Leibwache bestellte Joseph zu ihnen, und er bediente sie; und sie waren eine Zeitlang in Gewahrsam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Und sie hatten beide einen Traum, ein jeder seinen Traum in einer Nacht, ein jeder nach der Deutung seines Traumes, der Schenke und der Bäcker des Königs von Ägypten, die in der Feste gefangen lagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Und Joseph kam am Morgen zu ihnen und sah sie, und siehe, sie waren mißmutig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Und er fragte die Kämmerer des Pharao, die mit ihm im Hause seines Herrn in Gewahrsam waren, und sprach: Warum sind eure Angesichter heute so trübe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Und sie sprachen zu ihm: Wir haben einen Traum gehabt, und da ist niemand, der ihn deute. Und Joseph sprach zu ihnen: Sind die Deutungen nicht Gottes? Erzählet mir doch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Da erzählte der Oberste der Schenken dem Joseph seinen Traum und sprach zu ihm: In meinem Traume, siehe, da war ein Weinstock vor mir,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'und an dem Weinstock drei Reben; und sowie er knospte, schoß seine Blüte auf, seine Traubenkämme reiften zu Trauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Und der Becher des Pharao war in meiner Hand, und ich nahm die Trauben und preßte sie aus in den Becher des Pharao und gab den Becher in des Pharao Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Und Joseph sprach zu ihm: Dies ist seine Deutung: Die drei Reben sind drei Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'In noch drei Tagen wird der Pharao dein Haupt erheben und dich wieder in deine Stelle einsetzen, und du wirst den Becher des Pharao in seine Hand geben, nach der früheren Weise, da du sein Schenke warst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Aber gedenke meiner bei dir, wenn es dir wohlgeht, und erweise doch Güte an mir und erwähne meiner bei dem Pharao und bringe mich aus diesem Hause heraus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'denn gestohlen bin ich aus dem Lande der Hebräer, und auch hier habe ich gar nichts getan, daß sie mich in den Kerker gesetzt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Und der Oberste der Bäcker sah, daß er gut gedeutet hatte, und er sprach zu Joseph: Auch ich sah in meinem Traume, und siehe, drei Körbe mit Weißbrot waren auf meinem Kopfe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'und im obersten Korbe allerlei Eßwaren des Pharao, Backwerk; und das Gevögel fraß sie aus dem Korbe auf meinem Kopfe weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Und Joseph antwortete und sprach: Dies ist seine Deutung:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Die drei Körbe sind drei Tage. In noch drei Tagen wird der Pharao dein Haupt erheben und dich an ein Holz hängen, und das Gevögel wird dein Fleisch von dir wegfressen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Und es geschah am dritten Tage, dem Geburtstage des Pharao, da machte er allen seinen Knechten ein Mahl; und er erhob das Haupt des Obersten der Schenken und das Haupt des Obersten der Bäcker unter seinen Knechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Und er setzte den Obersten der Schenken wieder in sein Schenkamt, daß er den Becher in des Pharao Hand gab;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'und den Obersten der Bäcker ließ er hängen, so wie Joseph ihnen gedeutet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Aber der Oberste der Schenken gedachte nicht an Joseph und vergaß ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Und es geschah nach Verlauf von zwei vollen Jahren, daß der Pharao träumte: und siehe, er stand am Strome.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Und siehe, aus dem Strome stiegen sieben Kühe herauf, schön von Ansehen und fett an Fleisch, und sie weideten im Riedgrase.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Und siehe, sieben andere Kühe stiegen nach ihnen aus dem Strome herauf, häßlich von Ansehen und mager an Fleisch, und sie standen neben den Kühen am Ufer des Stromes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Und die Kühe, die häßlich von Ansehen und mager an Fleisch waren, fraßen die sieben Kühe, die schön von Ansehen und fett waren. Und der Pharao erwachte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Und er schlief ein und träumte zum zweiten Male: und siehe, sieben Ähren wuchsen auf an einem Halme, fett und schön.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Und siehe, sieben Ähren, mager und vom Ostwinde versengt, sproßten nach ihnen auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Und die mageren Ähren verschlangen die sieben fetten und vollen Ähren. Und der Pharao erwachte, und siehe, es war ein Traum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Und es geschah am Morgen, da war sein Geist voll Unruhe, und er sandte hin und ließ alle Schriftgelehrten Ägyptens und alle seine Weisen rufen; und der Pharao erzählte ihnen seine Träume, aber da war keiner, der sie dem Pharao deutete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Da redete der Oberste der Schenken zum Pharao und sprach: Ich gedenke heute meiner Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Der Pharao war sehr zornig über seine Knechte und setzte mich in Gewahrsam in das Haus des Obersten der Leibwache, mich und den Obersten der Bäcker.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Und wir hatten einen Traum in einer Nacht, ich und er; wir träumten ein jeder nach der Deutung seines Traumes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Und daselbst war bei uns ein hebräischer Jüngling, ein Knecht des Obersten der Leibwache, und wir erzählten sie ihm; und er deutete uns unsere Träume, einem jeden deutete er nach seinem Traume.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Und es geschah, wie er uns deutete, also ist es geschehen: mich hat der Pharao wieder in meine Stelle eingesetzt, und ihn hat er gehängt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Da sandte der Pharao hin und ließ Joseph rufen; und sie ließen ihn eilends aus dem Kerker gehen. Und er schor sich und wechselte seine Kleider und kam zu dem Pharao.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Und der Pharao sprach zu Joseph: Ich habe einen Traum gehabt, und da ist keiner, der ihn deute; ich habe aber von dir sagen hören, du verstehest einen Traum, ihn zu deuten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Und Joseph antwortete dem Pharao und sprach: Das steht nicht bei mir; Gott wird antworten, was dem Pharao zum Heil ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Da sprach der Pharao zu Joseph: In meinem Traume, siehe, da stand ich am Ufer des Stromes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Und siehe, aus dem Strome stiegen sieben Kühe herauf, fett an Fleisch und schön von Gestalt, und sie weideten im Riedgrase.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Und siehe, sieben andere Kühe stiegen nach ihnen herauf, dürr und sehr häßlich von Gestalt und mager an Fleisch; ich habe wie diese an Häßlichkeit keine gesehen im ganzen Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Und die mageren und häßlichen Kühe fraßen die sieben ersten fetten Kühe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'und sie kamen in ihren Bauch, und man merkte nicht, daß sie in ihren Bauch gekommen waren, und ihr Ansehen war häßlich, wie im Anfang. Und ich erwachte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Und ich sah in meinem Traume, und siehe, sieben Ähren wuchsen auf an einem Halme, voll und schön.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Und siehe, sieben Ähren, dürftig, mager, vom Ostwinde versengt, sproßten nach ihnen auf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'und die mageren Ähren verschlangen die sieben schönen Ähren. Und ich habe es den Schriftgelehrten gesagt; aber da war keiner, der es mir kundtat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Und Joseph sprach zum Pharao: Der Traum des Pharao ist einer; was Gott tun will, hat er dem Pharao kundgetan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Die sieben schönen Kühe sind sieben Jahre, und die sieben schönen Ähren sind sieben Jahre; ein Traum ist es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Und die sieben mageren und häßlichen Kühe, die nach ihnen heraufstiegen, sind sieben Jahre, so auch die sieben leeren, vom Ostwinde versengten Ähren: es werden sieben Jahre der Hungersnot sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Das ist das Wort, das ich zu dem Pharao geredet habe: Was Gott tun will, hat er den Pharao sehen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Siehe, sieben Jahre kommen, großer Überfluß wird sein im ganzen Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Und nach ihnen werden sieben Jahre der Hungersnot entstehen, und aller Überfluß wird im Lande Ägypten vergessen sein, und die Hungersnot wird das Land verzehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Und man wird nichts mehr von dem Überfluß im Lande wissen vor selbiger Hungersnot danach, denn sie wird sehr schwer sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Und was die zweimalige Wiederholung des Traumes an den Pharao anlangt, es bedeutet, daß die Sache von seiten Gottes fest beschlossen ist und daß Gott eilt, sie zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Und nun ersehe sich der Pharao einen verständigen und weisen Mann und setze ihn über das Land Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Dies tue der Pharao, daß er Aufseher über das Land bestelle und den Fünften vom Lande Ägypten nehme in den sieben Jahren des Überflusses;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'und man sammle alle Speise dieser kommenden guten Jahre und schütte Getreide auf unter des Pharao Hand zur Speise in den Städten und bewahre es auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Und die Speise sei zum Vorrat für das Land für die sieben Jahre der Hungersnot, welche im Lande Ägypten sein werden, daß das Land nicht vertilgt werde durch die Hungersnot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Und das Wort war gut in den Augen des Pharao und in den Augen aller seiner Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Und der Pharao sprach zu seinen Knechten: Werden wir einen finden wie diesen, einen Mann, in welchem der Geist Gottes ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Und der Pharao sprach zu Joseph: Nachdem Gott dir dies alles kundgetan hat, ist keiner so verständig und weise wie du.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Du sollst über mein Haus sein, und deinem Befehle soll mein ganzes Volk sich fügen; nur um den Thron will ich größer sein als du.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Und der Pharao sprach zu Joseph: Siehe, ich habe dich über das ganze Land Ägypten gesetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Und der Pharao nahm seinen Siegelring von seiner Hand und tat ihn an die Hand Josephs, und er kleidete ihn in Kleider von Byssus und legte die goldene Kette um seinen Hals.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Und er ließ ihn auf dem zweiten Wagen fahren, den er hatte, und man rief vor ihm her: Werfet euch nieder! Und er setzte ihn über das ganze Land Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Und der Pharao sprach zu Joseph: Ich bin der Pharao, und ohne dich soll kein Mensch seine Hand oder seinen Fuß aufheben im ganzen Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Und der Pharao gab Joseph den Namen: Zaphnath-Pahneach, und gab ihm Asnath, die Tochter Potipheras, des Priesters von On, zum Weibe. Und Joseph zog aus in das Land Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Und Joseph war dreißig Jahre alt, als er vor dem Pharao, dem Könige von Ägypten, stand. Und Joseph ging weg von dem Pharao und zog durch das ganze Land Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Und das Land trug in den sieben Jahren des Überflusses händevoll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Und er sammelte alle Speise der sieben Jahre, die im Lande Ägypten waren, und legte die Speise in die Städte; die Speise des Gefildes der Stadt, das um sie her war, legte er darein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Und Joseph schüttete Getreide auf wie Sand des Meeres, über die Maßen viel, bis man aufhörte zu zählen, denn es war ohne Zahl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Und dem Joseph wurden zwei Söhne geboren, ehe das Jahr der Hungersnot kam, welche Asnath ihm gebar, die Tochter Potipheras, des Priesters von On.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Und Joseph gab dem Erstgeborenen den Namen Manasse: denn Gott hat mich vergessen lassen all meine Mühsal und das ganze Haus meines Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Und dem Zweiten gab er den Namen Ephraim: denn Gott hat mich fruchtbar gemacht im Lande meines Elends.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Und es endigten die sieben Jahre des Überflusses, der im Lande Ägypten gewesen war;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'und die sieben Jahre der Hungersnot begannen zu kommen, so wie Joseph gesagt hatte. Und es war Hungersnot in allen Ländern, aber im ganzen Lande Ägypten war Brot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Und das ganze Land Ägypten hungerte; und das Volk schrie zum Pharao um Brot. Da sprach der Pharao zu allen Ägyptern: Gehet zu Joseph; tut, was er euch sagt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Und die Hungersnot war auf der ganzen Erde; und Joseph tat alles auf, worin Getreide war, und verkaufte es den Ägyptern; und die Hungersnot war stark im Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Und alle Welt kam nach Ägypten zu Joseph, um Getreide zu kaufen; denn die Hungersnot war stark auf der ganzen Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Und Jakob sah, daß Getreide in Ägypten war, und Jakob sprach zu seinen Söhnen: Was sehet ihr einander an?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Und er sprach: Siehe, ich habe gehört, daß Getreide in Ägypten ist; ziehet hinab und kaufet uns von dort Getreide, daß wir leben und nicht sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Und die zehn Brüder Josephs zogen hinab, um Getreide aus Ägypten zu kaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Aber Benjamin, Josephs Bruder, sandte Jakob nicht mit seinen Brüdern; denn er sprach: Daß ihm nicht etwa ein Unfall begegne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Und so kamen die Söhne Israels unter den Ankommenden, um Getreide zu kaufen; denn die Hungersnot war im Lande Kanaan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Und Joseph, er war der Gebieter über das Land, er verkaufte das Getreide allem Volke des Landes. Und die Brüder Josephs kamen und beugten sich vor ihm nieder, mit dem Antlitz zur Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Und Joseph sah seine Brüder und erkannte sie; aber er stellte sich fremd gegen sie und redete hart mit ihnen und sprach zu ihnen: Woher kommet ihr? Und sie sprachen: Aus dem Lande Kanaan, um Speise zu kaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Und Joseph erkannte seine Brüder; sie aber erkannten ihn nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Und Joseph gedachte der Träume, die er von ihnen gehabt hatte, und er sprach zu ihnen: Ihr seid Kundschafter; um zu sehen, wo das Land offen ist, seid ihr gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Da sprachen sie zu ihm: Nein, mein Herr; sondern deine Knechte sind gekommen, um Speise zu kaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Wir alle sind eines Mannes Söhne; wir sind redlich, deine Knechte sind nicht Kundschafter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Und er sprach zu ihnen: Nein, sondern ihr seid gekommen, um zu sehen, wo das Land offen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Und sie sprachen: Zwölf Brüder sind wir, deine Knechte, Söhne eines Mannes im Lande Kanaan; und siehe, der jüngste ist heute bei unserem Vater, und der eine ist nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Da sprach Joseph zu ihnen: Das ist es, was ich zu euch gesagt habe: Kundschafter seid ihr!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Daran sollt ihr geprüft werden: Beim Leben des Pharao! Wenn ihr von hier weggehet, es sei denn, daß euer jüngster Bruder hierher komme!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Sendet einen von euch hin, daß er euren Bruder hole; ihr aber bleibet gefangen, und eure Worte sollen geprüft werden, ob Wahrheit bei euch ist; und wenn nicht beim Leben des Pharao! so seid ihr Kundschafter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Und er setzte sie drei Tage zusammen in Gewahrsam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Und am dritten Tage sprach Joseph zu ihnen: Tut dieses, und ihr sollt leben; ich fürchte Gott:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Wenn ihr redlich seid, so bleibe einer eurer Brüder gefangen im Hause eures Gewahrsams; ihr aber, ziehet hin, bringet Getreide für den Bedarf eurer Häuser;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'und euren jüngsten Bruder sollt ihr zu mir bringen, daß eure Worte sich bewähren, und ihr nicht sterbet. Und sie taten also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Da sprachen sie einer zum anderen: Fürwahr, wir sind schuldig wegen unseres Bruders, dessen Seelenangst wir sahen, als er zu uns flehte, und wir hörten nicht; darum ist diese Drangsal über uns gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Und Ruben antwortete ihnen und sprach: Habe ich nicht zu euch gesprochen und gesagt: Versündiget euch nicht an dem Knaben? Aber ihr hörtet nicht; und siehe, sein Blut wird auch gefordert!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Sie aber wußten nicht, daß Joseph es verstand, denn ein Dolmetscher war zwischen ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Und er wandte sich von ihnen ab und weinte. Und er kehrte zu ihnen zurück und redete zu ihnen; und er nahm Simeon aus ihrer Mitte und band ihn vor ihren Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Und Joseph gebot, daß man ihre Gefäße mit Getreide fülle und ihr Geld zurückgebe, einem jeden in seinen Sack, und ihnen Zehrung gebe auf den Weg. Und man tat ihnen also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Und sie luden ihr Getreide auf ihre Esel und zogen von dannen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Und einer öffnete seinen Sack, um seinem Esel in der Herberge Futter zu geben; und er sah sein Geld, und siehe, es war oben in seinem Sacke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Und er sprach zu seinen Brüdern: Mein Geld ist mir wieder geworden, und siehe, es ist sogar in meinem Sacke. Da entfiel ihnen das Herz, und sie sahen einander erschrocken an und sprachen: Was hat Gott uns da getan!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Und sie kamen in das Land Kanaan zu ihrem Vater Jakob und berichteten ihm alles, was ihnen widerfahren war, und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Der Mann, der Herr des Landes, redete hart mit uns und behandelte uns wie Kundschafter des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Und wir sprachen zu ihm: Wir sind redlich, wir sind nicht Kundschafter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'zwölf Brüder sind wir, Söhne unseres Vaters; der eine ist nicht mehr, und der jüngste ist heute bei unserem Vater im Lande Kanaan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Und der Mann, der Herr des Landes, sprach zu uns: Daran werde ich erkennen, daß ihr redlich seid: Einen eurer Brüder lasset bei mir, und nehmet den Bedarf eurer Häuser und ziehet hin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'und bringet ihr euren jüngsten Bruder zu mir, so werde ich erkennen, daß ihr nicht Kundschafter, sondern redlich seid; euren Bruder werde ich euch zurückgeben, und ihr möget im Lande verkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Und es geschah, als sie ihre Säcke leerten, siehe, da hatte ein jeder sein Geldbündel in seinem Sacke; und sie sahen ihre Geldbündel, sie und ihr Vater, und sie fürchteten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Und ihr Vater Jakob sprach zu ihnen: Ihr habt mich der Kinder beraubt: Joseph ist nicht mehr, und Simeon ist nicht mehr; und Benjamin wollt ihr nehmen! Dies alles kommt über mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Und Ruben sprach zu seinem Vater und sagte: Meine beiden Söhne darfst du töten, wenn ich ihn nicht zu dir zurückbringe. Gib ihn in meine Hand, und ich werde ihn zu dir zurückbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Er aber sprach: Mein Sohn soll nicht mit euch hinabziehen; denn sein Bruder ist tot, und er allein ist übriggeblieben, und begegnete ihm ein Unfall auf dem Wege, auf welchem ihr ziehet, so würdet ihr mein graues Haar mit Kummer hinabbringen in den Scheol.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Und die Hungersnot war schwer im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Und es geschah, als sie das Getreide aufgezehrt hatten, das sie aus Ägypten gebracht, da sprach ihr Vater zu ihnen: Ziehet wiederum hin, kaufet uns ein wenig Speise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Und Juda sprach zu ihm und sagte: Der Mann hat uns ernstlich bezeugt und gesagt: Ihr sollt mein Angesicht nicht sehen, es sei denn euer Bruder bei euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Wenn du unseren Bruder mit uns senden willst, so wollen wir hinabziehen und dir Speise kaufen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'wenn du ihn aber nicht sendest, so werden wir nicht hinabziehen; denn der Mann hat zu uns gesagt: Ihr sollt mein Angesicht nicht sehen, es sei denn euer Bruder bei euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Da sprach Israel: Warum habt ihr mir das Leid angetan, dem Manne kundzutun, daß ihr noch einen Bruder habt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Und sie sprachen: Der Mann erkundigte sich genau nach uns und unserer Verwandtschaft und sprach: Lebt euer Vater noch? Habt ihr noch einen Bruder? und wir taten es ihm kund nach diesen Worten. Konnten wir denn wissen, daß er sagen würde: Bringet euren Bruder herab?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Und Juda sprach zu Israel, seinem Vater: Sende den Knaben mit mir, und wir wollen uns aufmachen und ziehen, daß wir leben und nicht sterben, sowohl wir als du als auch unsere Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ich will Bürge für ihn sein, von meiner Hand sollst du ihn fordern; wenn ich ihn nicht zu dir bringe und ihn vor dein Angesicht stelle, so will ich alle Tage gegen dich gesündigt haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'denn hätten wir nicht gezögert, gewiß, wir wären jetzt schon zweimal zurückgekehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Und Israel, ihr Vater, sprach zu ihnen: Wenn es denn also ist, so tut dieses: Nehmet von dem Besten des Landes in eure Gefäße und bringet dem Manne ein Geschenk hinab: ein wenig Balsam und ein wenig Traubenhonig, Tragant und Ladanum, Pistazien und Mandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Und nehmet doppeltes Geld in eure Hand, und bringet das Geld, das euch oben in euren Säcken wieder geworden ist, in eurer Hand zurück; vielleicht ist es ein Irrtum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Und nehmet euren Bruder und machet euch auf, kehret zu dem Manne zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Und Gott, der Allmächtige, gebe euch Barmherzigkeit vor dem Manne, daß er euch euren anderen Bruder und Benjamin loslasse. Und ich, wenn ich der Kinder beraubt bin, so bin ich der Kinder beraubt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Da nahmen die Männer dieses Geschenk und nahmen doppeltes Geld in ihre Hand und Benjamin, und machten sich auf und zogen nach Ägypten hinab. Und sie traten vor Joseph.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Und als Joseph den Benjamin bei ihnen sah, sprach er zu dem, der über sein Haus war: Führe die Männer ins Haus und schlachte Schlachtvieh und richte zu; denn die Männer sollen mit mir zu Mittag essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Und der Mann tat, wie Joseph gesagt hatte; und der Mann führte die Männer in das Haus Josephs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Da fürchteten sich die Männer, daß sie in das Haus Josephs geführt wurden, und sprachen: Um des Geldes willen, das im Anfang wieder in unsere Säcke gekommen ist, werden wir hineingeführt, daß man über uns herstürze und über uns herfalle und uns zu Knechten nehme, samt unseren Eseln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Und sie traten zu dem Manne, der über das Haus Josephs war, und redeten zu ihm am Eingang des Hauses');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'und sprachen: Bitte, mein Herr! Wir sind im Anfang herabgezogen, um Speise zu kaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Und es geschah, als wir in die Herberge kamen und unsere Säcke öffneten, siehe, da war eines jeden Geld oben in seinem Sacke, unser Geld nach seinem Gewicht; und wir haben es in unserer Hand zurückgebracht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Und anderes Geld haben wir in unserer Hand herabgebracht, um Speise zu kaufen. Wir wissen nicht, wer unser Geld in unsere Säcke gelegt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Und er sprach: Friede euch! Fürchtet euch nicht! Euer Gott und der Gott eures Vaters hat euch einen Schatz in eure Säcke gegeben; euer Geld ist mir zugekommen. Und er führte Simeon zu ihnen heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Und der Mann führte die Männer in das Haus Josephs und gab ihnen Wasser, und sie wuschen ihre Füße; und er gab ihren Eseln Futter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Und sie bereiteten das Geschenk zu, bis Joseph am Mittag kam; denn sie hatten gehört, daß sie daselbst essen sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Als Joseph nach Hause kam, da brachten sie ihm das Geschenk, das in ihrer Hand war, ins Haus und beugten sich vor ihm nieder zur Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Und er fragte nach ihrem Wohlergehen und sprach: Geht es eurem Vater wohl, dem Greise, von dem ihr sprachet? Lebt er noch?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Da sprachen sie: Es geht deinem Knechte, unserem Vater, wohl; er lebt noch. Und sie verneigten sich und beugten sich nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Und er erhob seine Augen und sah seinen Bruder Benjamin, den Sohn seiner Mutter, und sprach: Ist das euer jüngster Bruder, von dem ihr zu mir sprachet? Und er sprach: Gott sei dir gnädig, mein Sohn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Und Joseph eilte (denn sein Innerstes wurde erregt über seinen Bruder) und suchte einen Ort, um zu weinen, und er ging in das innere Gemach und weinte daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Und er wusch sein Angesicht und kam heraus und bezwang sich und sprach: Traget Speise auf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Und man trug für ihn besonders auf und für sie besonders und für die Ägypter, die mit ihm aßen, besonders; denn die Ägypter dürfen nicht mit den Hebräern essen, denn das ist den Ägyptern ein Greuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Und sie aßen vor ihm, der Erstgeborene nach seiner Erstgeburt und der Jüngste nach seiner Jugend; und die Männer sahen einander staunend an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Und man trug Ehrengerichte von ihm zu ihnen; und das Ehrengericht Benjamins war fünfmal größer als die Ehrengerichte von ihnen allen. Und sie tranken und tranken sich fröhlich mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Und er gebot dem, der über sein Haus war, und sprach: Fülle die Säcke der Männer mit Speise, so viel sie tragen können, und lege das Geld eines jeden oben in seinen Sack.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Und meinen Kelch, den silbernen Kelch, sollst du oben in den Sack des Jüngsten legen mit dem Gelde für sein Getreide. Und er tat nach den Worte Josephs, das er geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Als der Morgen anbrach, da wurden die Männer entlassen, sie und ihre Esel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Sie waren eben zur Stadt hinausgegangen, sie waren noch nicht weit, da sprach Joseph zu dem, der über sein Haus war: Mache dich auf, jage den Männern nach, und hast du sie erreicht, so sage zu ihnen: Warum habt ihr Böses für Gutes vergolten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Ist es nicht der, aus welchem mein Herr trinkt und aus dem er zu wahrsagen pflegt? Ihr habt übel getan, was ihr getan habt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Und er erreichte sie und redete diese Worte zu ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Und sie sprachen zu ihm: Warum redet mein Herr solche Worte? Fern sei es von deinen Knechten, eine solche Sache zu tun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Siehe, das Geld, das wir oben in unseren Säcken fanden, haben wir dir aus dem Lande Kanaan zurückgebracht, und wie sollten wir aus dem Hause deines Herrn Silber oder Gold stehlen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Bei welchem von deinen Knechten er gefunden wird, der sterbe; und dazu wollen wir meines Herrn Knechte sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Da sprach er: Nun, nach euren Worten, so sei es auch: bei wem er gefunden wird, der sei mein Knecht, ihr aber sollt schuldlos sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Und sie eilten und hoben ein jeder seinen Sack auf die Erde herab und öffneten ein jeder seinen Sack.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Und er durchsuchte: beim Ältesten fing er an, und beim Jüngsten hörte er auf; und der Kelch fand sich im Sacke Benjamins.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Da zerrissen sie ihre Kleider, und ein jeder belud seinen Esel, und sie kehrten in die Stadt zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Und Juda und seine Brüder kamen in das Haus Josephs; und er war noch daselbst, und sie fielen vor ihm nieder zur Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Und Joseph sprach zu ihnen: Was ist das für eine Tat, die ihr getan habt! Wußtet ihr nicht, daß solch ein Mann wie ich wahrsagen kann?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Und Juda sprach: Was sollen wir meinem Herrn sagen? Was sollen wir reden und wie uns rechtfertigen? Gott hat die Missetat deiner Knechte gefunden; siehe, wir sind die Knechte meines Herrn, sowohl wir als auch der, in dessen Hand der Kelch gefunden worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Und er sprach: Fern sei es von mir, solches zu tun! Der Mann, in dessen Hand der Kelch gefunden worden ist, der soll mein Knecht sein; und ihr, ziehet in Frieden hinauf zu eurem Vater.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Da trat Juda zu ihm und sprach: Bitte, mein Herr, laß doch deinen Knecht ein Wort reden zu den Ohren meines Herrn, und es entbrenne nicht dein Zorn gegen deinen Knecht, denn du bist gleich dem Pharao.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mein Herr fragte seine Knechte und sprach: Habt ihr noch einen Vater oder einen Bruder?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Und wir sprachen zu meinem Herrn: Wir haben einen alten Vater und einen jungen Knaben, der ihm im Alter geboren wurde; und dessen Bruder ist tot, und er allein ist von seiner Mutter übriggeblieben, und sein Vater hat ihn lieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Und du sprachst zu deinen Knechten: Bringet ihn zu mir herab, daß ich mein Auge auf ihn richte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Und wir sprachen zu meinem Herrn: Der Knabe kann seinen Vater nicht verlassen; verließe er seinen Vater, so stürbe er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Da sprachst du zu deinen Knechten: Wenn euer jüngster Bruder nicht mit euch herabkommt, so sollt ihr mein Angesicht nicht mehr sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Und es geschah, als wir hinaufgezogen waren zu deinem Knechte, meinem Vater, da berichteten wir ihm die Worte meines Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Und unser Vater sprach: Ziehet wieder hin, kaufet uns ein wenig Speise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Wir aber sprachen: Wir können nicht hinabziehen. Wenn unser jüngster Bruder bei uns ist, so wollen wir hinabziehen; denn wir dürfen das Angesicht des Mannes nicht sehen, wenn unser jüngster Bruder nicht bei uns ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Und dein Knecht, mein Vater, sprach zu uns: Ihr wisset, daß mein Weib mir zwei geboren hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'und der eine ist von mir weggegangen, und ich sprach: Fürwahr, er ist gewißlich zerrissen worden; und ich habe ihn nicht mehr gesehen bis jetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Und nehmet ihr auch diesen von mir hinweg, und es begegnet ihm ein Unfall, so werdet ihr mein graues Haar mit Unglück hinabbringen in den Scheol.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Und nun, wenn ich zu deinem Knechte, meinem Vater, komme, und der Knabe ist nicht bei uns und seine Seele hängt an dessen Seele, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'so wird es geschehen, daß er stirbt, wenn er sieht, daß der Knabe nicht da ist; und deine Knechte werden das graue Haar deines Knechtes, unseres Vaters, mit Kummer hinabbringen in den Scheol.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Denn dein Knecht ist für den Knaben Bürge geworden bei meinem Vater, indem ich sprach: Wenn ich ihn nicht zu dir bringe, so will ich alle Tage gegen meinen Vater gesündigt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Und nun, laß doch deinen Knecht anstatt des Knaben bleiben, als Knecht meines Herrn, und der Knabe ziehe hinauf mit seinen Brüdern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'denn wie sollte ich zu meinem Vater hinaufziehen, wenn der Knabe nicht bei mir wäre? daß ich nicht das Unglück ansehen müsse, welches meinen Vater treffen würde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Da konnte Joseph sich nicht mehr bezwingen vor allen, die um ihn standen, und er rief: Laßt jedermann von mir hinausgehen! Und es stand niemand bei ihm, als Joseph sich seinen Brüdern zu erkennen gab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Und er erhob seine Stimme mit Weinen; und die Ägypter hörten es, und das Haus des Pharao hörte es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Und Joseph sprach zu seinen Brüdern: Ich bin Joseph. Lebt mein Vater noch? Und seine Brüder konnten ihm nicht antworten, denn sie waren bestürzt vor ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Da sprach Joseph zu seinen Brüdern: Tretet doch zu mir her! Und sie traten herzu. Und er sprach: Ich bin Joseph, euer Bruder, den ihr nach Ägypten verkauft habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Und nun betrübet euch nicht, und es entbrenne nicht in euren Augen, daß ihr mich hierher verkauft habt; denn zur Erhaltung des Lebens hat Gott mich vor euch hergesandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Denn schon zwei Jahre ist die Hungersnot im Lande, und noch sind fünf Jahre, daß kein Pflügen noch Ernten sein wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Und Gott hat mich vor euch hergesandt, um euch einen Überrest zu setzen auf Erden und euch am Leben zu erhalten für eine große Errettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Und nun, nicht ihr habt mich hierher gesandt, sondern Gott; und er hat mich zum Vater des Pharao gemacht und zum Herrn seines ganzen Hauses und zum Herrscher über das ganze Land Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Eilet und ziehet hinauf zu meinem Vater und sprechet zu ihm: So spricht dein Sohn Joseph: Gott hat mich zum Herrn von ganz Ägypten gemacht; komm zu mir herab, säume nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Und du sollst im Lande Gosen wohnen und nahe bei mir sein, du und deine Söhne und die Söhne deiner Söhne und dein Kleinvieh und deine Rinder und alles, was du hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Und ich will dich daselbst versorgen, denn noch fünf Jahre ist Hungersnot; daß du nicht verarmest, du und dein Haus und alles, was du hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Und siehe, eure Augen sehen es und die Augen meines Bruders Benjamin, daß mein Mund es ist, der zu euch redet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Und berichtet meinem Vater alle meine Herrlichkeit in Ägypten und alles, was ihr gesehen habt; und eilet und bringet meinen Vater hierher herab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Und er fiel seinem Bruder Benjamin um den Hals und weinte; und Benjamin weinte an seinem Halse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Und er küßte alle seine Brüder und weinte an ihnen; und danach redeten seine Brüder mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Und das Gerücht wurde im Hause des Pharao gehört, indem man sprach: Josephs Brüder sind gekommen! Und es war gut in den Augen des Pharao und in den Augen seiner Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Und der Pharao sprach zu Joseph: Sage deinen Brüdern: Tut dieses: Beladet eure Tiere und ziehet hin, gehet nach dem Lande Kanaan,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'und nehmet euren Vater und eure Haushaltungen und kommet zu mir; und ich will euch das Beste des Landes Ägypten geben, und ihr sollt das Fett des Landes essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Und du bist beauftragt: Tut dieses: Nehmet euch aus dem Lande Ägypten Wagen für eure Kinder und für eure Weiber, und holet euren Vater und kommet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Und laßt es euch nicht leid sein um euren Hausrat, denn das Beste des ganzen Landes Ägypten soll euer sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Und die Söhne Israels taten also, und Joseph gab ihnen Wagen nach dem Befehl des Pharao und gab ihnen Zehrung auf den Weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Er gab ihnen allen, einem jeden, Wechselkleider, und Benjamin gab er dreihundert Silbersekel und fünf Wechselkleider.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Und seinem Vater sandte er dieses: zehn Esel, beladen mit dem Besten Ägyptens, und zehn Eselinnen, beladen mit Getreide und Brot und Nahrung für seinen Vater auf den Weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Und er entließ seine Brüder, und sie zogen hin; und er sprach zu ihnen: Erzürnet euch nicht auf dem Wege!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Und sie zogen aus Ägypten hinauf und kamen in das Land Kanaan zu ihrem Vater Jakob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Und sie berichteten ihm und sprachen: Joseph lebt noch, und er ist Herrscher über das ganze Land Ägypten. Da erstarrte sein Herz, denn er glaubte ihnen nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Und sie redeten zu ihm alle Worte Josephs, die er zu ihnen geredet hatte; und er sah die Wagen, die Joseph gesandt hatte, ihn zu holen. Und der Geist ihres Vaters Jakob lebte auf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'und Israel sprach: Genug! Joseph, mein Sohn, lebt noch! Ich will hinziehen und ihn sehen, ehe ich sterbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Und Israel brach auf und alles, was er hatte, und kam nach Beerseba; und er opferte Schlachtopfer dem Gott seines Vaters Isaak.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Und Gott sprach zu Israel in den Gesichten der Nacht und sagte: Jakob! Jakob! Und er sprach: Hier bin ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Und er sprach: Ich bin Gott, der Gott deines Vaters; fürchte dich nicht, nach Ägypten hinabzuziehen; denn zu einer großen Nation will ich dich daselbst machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ich will mit dir nach Ägypten hinabziehen, und ich will dich auch gewißlich heraufführen; und Joseph soll seine Hand auf deine Augen legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Da machte sich Jakob von Beerseba auf, und die Söhne Israels führten Jakob, ihren Vater, und ihre Kinder und ihre Weiber auf den Wagen, die der Pharao gesandt hatte, ihn zu holen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Und sie nahmen ihr Vieh und ihre Habe, die sie im Lande Kanaan erworben hatten, und kamen nach Ägypten, Jakob und all sein Same mit ihm:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'seine Söhne und die Söhne seiner Söhne mit ihm, seine Töchter und die Töchter seiner Söhne, und all seinen Samen brachte er mit sich nach Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Und dies sind die Namen der Söhne Israels, die nach Ägypten kamen: Jakob und seine Söhne; der Erstgeborene Jakobs: Ruben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Und die Söhne Rubens: Hanok und Pallu und Hezron und Karmi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Und die Söhne Simeons: Jemuel und Jamin und Ohad und Jakin und Zochar und Saul, der Sohn der Kanaaniterin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Und die Söhne Levis: Gerson, Kehath und Merari.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Und die Söhne Judas: Gher und Onan und Schela und Perez und Serach; Gher und Onan aber starben im Lande Kanaan. Und die Söhne des Perez waren Hezron und Hamul.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Und die Söhne Issaschars: Tola und Puwa und Job und Schimron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Und die Söhne Sebulons: Sered und Elon und Jachleel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Das sind die Söhne Leas, welche sie dem Jakob in Paddan-Aram gebar, und Dina, seine Tochter. Aller Seelen seiner Söhne und seiner Töchter waren dreiunddreißig. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Und die Söhne Gads: Ziphjon und Haggi, Schuni und Ezbon, Eri und Arodi und Areli.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Und die Söhne Asers: Jimna und Jischwa und Jischwi und Beria, und Serach, ihre Schwester. Und die Söhne Berias: Heber und Malkiel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Das sind die Söhne Silpas, die Laban seiner Tochter Lea gab; und sie gebar diese dem Jakob, sechzehn Seelen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Die Söhne Rahels, des Weibes Jakobs: Joseph und Benjamin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Und dem Joseph wurden im Lande Ägypten Manasse und Ephraim geboren, welche Asnath ihm gebar, die Tochter Potipheras, des Priesters von On.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Und die Söhne Benjamins: Bela und Beker und Aschbel, Gera und Naaman, Echi und Rosch, Muppim und Huppim und Ard.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Das sind die Söhne Rahels, die dem Jakob geboren wurden; aller Seelen waren vierzehn. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Und die Söhne Dans: Huschim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Und die Söhne Naphtalis: Jachzeel und Guni und Jezer und Schillem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Das sind die Söhne Bilhas, die Laban seiner Tochter Rahel gab; und sie gebar diese dem Jakob; aller Seelen waren sieben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Aller dem Jakob angehörenden Seelen, die nach Ägypten kamen, die aus seinen Lenden hervorgegangen waren, ausgenommen die Weiber der Söhne Jakobs, aller Seelen waren sechsundsechzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Und die Söhne Josephs, die ihm in Ägypten geboren wurden, waren zwei Seelen. Aller Seelen des Hauses Jakob, die nach Ägypten kamen, waren siebzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Und er sandte Juda vor sich hin zu Joseph, um vor ihm her zu weisen nach Gosen; und sie kamen in das Land Gosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Da spannte Joseph seinen Wagen an und zog hinauf, seinem Vater Israel entgegen nach Gosen; und als er seiner ansichtig wurde, fiel er ihm um den Hals und weinte lange an seinem Halse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Und Israel sprach zu Joseph: Nunmehr mag ich sterben, nachdem ich dein Angesicht gesehen habe, daß du noch lebst!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Und Joseph sprach zu seinen Brüdern und zum Hause seines Vaters: Ich will hinaufziehen und dem Pharao berichten und zu ihm sagen: Meine Brüder und das Haus meines Vaters, die im Lande Kanaan waren, sind zu mir gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Und die Männer sind Schafhirten, denn sie haben Viehzucht getrieben; und sie haben ihr Kleinvieh und ihre Rinder und alles, was sie haben, mitgebracht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Und geschieht es, daß der Pharao euch ruft und spricht: Was ist eure Hantierung?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'so saget: Deine Knechte haben Viehzucht getrieben, von Jugend auf bis jetzt, sowohl wir als auch unsere Väter, auf daß ihr wohnen möget im Lande Gosen; denn alle Schafhirten sind den Ägyptern ein Greuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Und Joseph kam und berichtete dem Pharao und sprach: Mein Vater und meine Brüder und ihr Kleinvieh und ihre Rinder und alles, was sie haben, sind aus dem Lande Kanaan gekommen; und siehe, sie sind im Lande Gosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Und er nahm aus der Gesamtheit seiner Brüder fünf Männer und stellte sie vor den Pharao.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Und der Pharao sprach zu seinen Brüdern: Was ist eure Hantierung? Und sie sprachen zum Pharao: Deine Knechte sind Schafhirten, sowohl wir als auch unsere Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Und sie sprachen zum Pharao: Wir sind gekommen, um uns im Lande aufzuhalten; denn es gibt keine Weide für das Kleinvieh, das deine Knechte haben, denn die Hungersnot ist schwer im Lande Kanaan; und nun laß doch deine Knechte im Lande Gosen wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Da sprach der Pharao zu Joseph und sagte: Dein Vater und deine Brüder sind zu dir gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Das Land Ägypten ist vor dir: laß deinen Vater und deine Brüder in dem besten Teile des Landes wohnen; sie mögen wohnen im Lande Gosen. Und wenn du weißt, daß tüchtige Männer unter ihnen sind, so setze sie als Aufseher über das Vieh, das ich habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Und Joseph brachte seinen Vater Jakob und stellte ihn vor den Pharao. Und Jakob segnete den Pharao.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Und der Pharao sprach zu Jakob: Wie viel sind der Tage deiner Lebensjahre?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Und Jakob sprach zum Pharao: Die Tage der Jahre meiner Fremdlingschaft sind hundertdreißig Jahre; wenig und böse waren die Tage meiner Lebensjahre, und sie haben nicht erreicht die Tage der Lebensjahre meiner Väter in den Tagen ihrer Fremdlingschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Und Jakob segnete den Pharao und ging von dem Pharao hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Und Joseph schaffte seinem Vater und seinen Brüdern Wohnung und gab ihnen ein Besitztum in dem Lande Ägypten, im besten Teile des Landes, im Lande Raemses, so wie der Pharao geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Und Joseph versorgte seinen Vater und seine Brüder und das ganze Haus seines Vaters mit Brot, nach der Zahl der Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Und es war kein Brot im ganzen Lande, denn die Hungersnot war sehr schwer; und das Land Ägypten und das Land Kanaan verschmachteten vor Hunger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Und Joseph brachte alles Geld zusammen, das sich im Lande Ägypten und im Lande Kanaan vorfand, für das Getreide, das man kaufte; und Joseph brachte das Geld in das Haus des Pharao.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Und als das Geld im Lande Ägypten und im Lande Kanaan ausging, da kamen alle Ägypter zu Joseph und sprachen: Gib uns Brot! Warum sollen wir denn vor dir sterben? Denn das Geld ist zu Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Und Joseph sprach: Gebet euer Vieh her, und ich will euch Brot geben um euer Vieh, wenn das Geld zu Ende ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Da brachten sie ihr Vieh zu Joseph, und Joseph gab ihnen Brot um die Pferde und um das Kleinvieh und um das Rindvieh und um die Esel; und so ernährte er sie mit Brot um all ihr Vieh in selbigem Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Als selbiges Jahr zu Ende war, da kamen sie im zweiten Jahre zu ihm und sprachen zu ihm: Wir wollen es meinem Herrn nicht verhehlen, daß, da das Geld ausgegangen ist und der Besitz des Viehes an meinen Herrn gekommen, nichts mehr übrigbleibt vor meinem Herrn als nur unser Leib und unser Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Warum sollen wir vor deinen Augen sterben, sowohl wir als auch unser Land? Kaufe uns und unser Land um Brot, so wollen wir und unser Land des Pharao Knechte sein; und gib Samen, daß wir leben und nicht sterben und das Land nicht wüst werde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Und Joseph kaufte das ganze Land Ägypten für den Pharao; denn die Ägypter verkauften ein jeder sein Feld, weil der Hunger sie drängte. Und so ward das Land dem Pharao.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Und das Volk, das versetzte er in die verschiedenen Städte, von einem Ende der Grenze Ägyptens bis zu ihrem anderen Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Nur das Land der Priester kaufte er nicht; denn die Priester hatten ein Bestimmtes von dem Pharao, und sie aßen ihr Bestimmtes, das der Pharao ihnen gab; deshalb verkauften sie ihr Land nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Und Joseph sprach zu dem Volke: Siehe, ich habe euch und euer Land heute für den Pharao gekauft; siehe, da ist Samen für euch, und besäet das Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Und es soll geschehen mit dem Ertrage, daß ihr den Fünften dem Pharao gebet, und die vier Teile sollen für euch sein zur Saat des Feldes und zur Speise für euch und für die, welche in euren Häusern sind, und zur Speise für eure Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Und sie sprachen: Du hast uns am Leben erhalten; möchten wir Gnade finden in den Augen meines Herrn, so wollen wir des Pharao Knechte sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Und Joseph legte es dem Lande Ägypten bis auf diesen Tag als Satzung auf, daß dem Pharao der Fünfte gehöre. Nur das Land der Priester allein ward nicht dem Pharao.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Und Israel wohnte im Lande Ägypten, im Lande Gosen; und sie machten sich darin ansässig und waren fruchtbar und mehrten sich sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Und Jakob lebte im Lande Ägypten siebzehn Jahre; und der Tage Jakobs, der Jahre seines Lebens, waren hundertsiebenundvierzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Und als die Tage Israels herannahten, daß er sterben sollte, da rief er seinen Sohn Joseph und sprach zu ihm: Wenn ich doch Gnade gefunden habe in deinen Augen, so lege doch deine Hand unter meine Hüfte und erweise Güte und Treue an mir: begrabe mich doch nicht in Ägypten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Wenn ich mit meinen Vätern liegen werde, so führe mich aus Ägypten und begrabe mich in ihrem Begräbnis. Und er sprach: Ich werde tun nach deinem Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Da sprach er: Schwöre mir! Und er schwur ihm. Und Israel betete an zu den Häupten des Bettes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Und es geschah nach diesen Dingen, daß man dem Joseph sagte: Siehe, dein Vater ist krank. Und er nahm seine beiden Söhne, Manasse und Ephraim, mit sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Und man berichtete dem Jakob und sprach: Siehe, dein Sohn Joseph kommt zu dir. Und Israel machte sich stark und setzte sich aufs Bett.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Und Jakob sprach zu Joseph: Gott, der Allmächtige, erschien mir zu Lus im Lande Kanaan, und er segnete mich');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'und sprach zu mir: Siehe, ich will dich fruchtbar machen und dich mehren und dich zu einem Haufen Völker machen, und ich will dieses Land deinem Samen nach dir zum ewigen Besitztum geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Und nun, deine beiden Söhne, welche dir im Lande Ägypten geboren sind, ehe ich zu dir nach Ägypten kam, sollen mein sein; Ephraim und Manasse sollen mein sein wie Ruben und Simeon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Aber dein Geschlecht, das du nach ihnen gezeugt hast, soll dein sein; nach dem Namen ihrer Brüder sollen sie genannt werden in ihrem Erbteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Denn ich, als ich aus Paddan kam, starb Rahel bei mir im Lande Kanaan auf dem Wege, als noch eine Strecke Landes war, um nach Ephrath zu kommen; und ich begrub sie daselbst auf dem Wege nach Ephrath, das ist Bethlehem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Und Israel sah die Söhne Josephs und sprach: Wer sind diese?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Und Joseph sprach zu seinem Vater: Das sind meine Söhne, die Gott mir hier gegeben hat. Da sprach er: Bringe sie doch zu mir her, daß ich sie segne!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Die Augen Israels aber waren schwer vor Alter, er konnte nicht sehen. Und er führte sie näher zu ihm, und er küßte sie und umarmte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Und Israel sprach zu Joseph: Ich hatte nicht gedacht, dein Angesicht wiederzusehen, und siehe, Gott hat mich sogar deinen Samen sehen lassen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Und Joseph führte sie von seinen Knien heraus und beugte sich auf sein Angesicht zur Erde nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Und Joseph nahm sie beide, Ephraim mit seiner Rechten, zur Linken Israels, und Manasse mit seiner Linken, zur Rechten Israels, und führte sie näher zu ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Und Israel streckte seine Rechte aus und legte sie auf das Haupt Ephraims er war aber der Jüngere und seine Linke auf das Haupt Manasses; er legte seine Hände absichtlich also, denn Manasse war der Erstgeborene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Und er segnete Joseph und sprach: Der Gott, vor dessen Angesicht meine Väter, Abraham und Isaak, gewandelt haben, der Gott, der mich geweidet hat, seitdem ich bin bis auf diesen Tag,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'der Engel, der mich erlöst hat von allem Übel, segne die Knaben; und in ihnen werde mein Name genannt und der Name meiner Väter, Abraham und Isaak, und sie sollen sich mehren zu einer Menge inmitten des Landes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Und als Joseph sah, daß sein Vater seine rechte Hand auf das Haupt Ephraims legte, war es übel in seinen Augen; und er faßte seines Vaters Hand, um sie von dem Haupte Ephraims hinwegzutun auf das Haupt Manasses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Und Joseph sprach zu seinem Vater: Nicht also, mein Vater! Denn dieser ist der Erstgeborene; lege deine Rechte auf sein Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Aber sein Vater weigerte sich und sprach: Ich weiß es mein Sohn, ich weiß es. Auch er wird zu einem Volke werden, und auch er wird groß sein; aber doch wird sein jüngerer Bruder größer sein als er, und sein Same wird eine Fülle von Nationen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Und er segnete sie an selbigem Tage und sprach: In dir wird Israel segnen und sprechen: Gott mache dich wie Ephraim und wie Manasse! Und er setzte Ephraim vor Manasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Und Israel sprach zu Joseph: Siehe, ich sterbe; und Gott wird mit euch sein und euch in das Land eurer Väter zurückbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Und ich gebe dir einen Landstrich über deine Brüder hinaus, den ich von der Hand der Amoriter genommen habe mit meinem Schwerte und mit meinem Bogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Und Jakob rief seine Söhne und sprach: Versammelt euch, und ich will euch verkünden, was euch begegnen wird in künftigen Tagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Kommet zusammen und höret, ihr Söhne Jakobs, und höret auf Israel, euren Vater!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, mein Erstgeborener bist du, meine Kraft und der Erstling meiner Stärke! Vorzug an Hoheit und Vorzug an Macht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Überwallend wie die Wasser, sollst du keinen Vorzug haben, denn du hast das Lager deines Vaters bestiegen; da hast du es entweiht. Mein Bett hat er bestiegen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon und Levi sind Brüder, Werkzeuge der Gewalttat ihre Waffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Meine Seele komme nicht in ihren geheimen Rat, meine Ehre vereinige sich nicht mit ihrer Versammlung! Denn in ihrem Zorn haben sie den Mann erschlagen und in ihrem Mutwillen den Stier gelähmt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Verflucht sei ihr Zorn, denn er war gewalttätig, und ihr Grimm, denn er war grausam! Ich werde sie verteilen in Jakob und sie zerstreuen in Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Dich Juda, dich werden deine Brüder preisen; deine Hand wird sein auf dem Nacken deiner Feinde, vor dir werden sich niederbeugen die Söhne deines Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juda ist ein junger Löwe; vom Raube, mein Sohn, bist du emporgestiegen. Er duckt sich, er legt sich nieder wie ein Löwe und wie eine Löwin; wer will ihn aufreizen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Nicht weichen wird das Zepter von Juda, noch der Herrscherstab zwischen seinen Füßen hinweg, bis Schilo kommt, und ihm werden die Völker gehorchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Er bindet an den Weinstock sein Eselsfüllen und an die Edelrebe das Junge seiner Eselin; er wäscht im Weine sein Kleid und im Blute der Trauben sein Gewand;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'die Augen sind trübe von Wein und weiß die Zähne von Milch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon, am Gestade der Meere wird er wohnen, und am Gestade der Schiffe wird er sein und seine Seite gegen Sidon hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issaschar ist ein knochiger Esel, der sich lagert zwischen den Hürden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Und er sieht, daß die Ruhe gut und daß das Land lieblich ist; und er beugt seine Schulter zum Lasttragen und wird zum fronpflichtigen Knecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan wird sein Volk richten, wie einer der Stämme Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan wird eine Schlange sein am Wege, eine Hornotter am Pfade, die da beißt in die Fersen des Rosses, und rücklings fällt sein Reiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Auf deine Rettung harre ich, Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad, Scharen werden ihn drängen, und er, er wird ihnen nachdrängen auf der Ferse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Von Aser kommt Fettes, sein Brot; und er, königliche Leckerbissen wird er geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naphtali ist eine losgelassene Hindin; er, der schöne Worte gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Sohn eines Fruchtbaumes ist Joseph, Sohn eines Fruchtbaumes am Quell; die Schößlinge treiben über die Mauer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Und es reizen ihn und schießen, und es befehden ihn die Bogenschützen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'aber sein Bogen bleibt fest, und gelenkig sind die Arme seiner Hände durch die Hände des Mächtigen Jakobs. Von dannen ist der Hirte, der Stein Israels:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'von dem Gott deines Vaters, und er wird dir helfen, und dem Allmächtigen, und er wird dich segnen mit Segnungen des Himmels droben, mit Segnungen der Tiefe, die unten liegt, mit Segnungen der Brüste und des Mutterleibes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Die Segnungen deines Vaters überragen die Segnungen meiner Voreltern bis zur Grenze der ewigen Hügel. Sie werden sein auf dem Haupte Josephs und auf dem Scheitel des Abgesonderten unter seinen Brüdern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin ist ein Wolf, der zerreißt; am Morgen verzehrt er Raub, und am Abend verteilt er Beute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Alle diese sind die zwölf Stämme Israels, und das ist es, was ihr Vater zu ihnen redete und womit er sie segnete; einen jeden nach seinem Segen segnete er sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Und er gebot ihnen und sprach zu ihnen: Bin ich versammelt zu meinem Volke, so begrabet mich zu meinen Vätern in der Höhle, die in dem Felde Ephrons, des Hethiters, ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'in der Höhle, die in dem Felde Machpela vor Mamre ist, im Lande Kanaan, welche Abraham samt dem Felde von Ephron, dem Hethiter, zum Erbbegräbnis gekauft hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Dort haben sie Abraham begraben und sein Weib Sara; dort haben sie Isaak begraben und sein Weib Rebekka; und dort habe ich Lea begraben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'das Feld und die Höhle, die darin ist, sind erkauft von den Kindern Heth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Und als Jakob geendet hatte, seinen Söhnen Befehle zu geben, zog er seine Füße aufs Bett herauf und verschied und wurde versammelt zu seinen Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Und Joseph fiel auf das Angesicht seines Vaters und weinte über ihm und küßte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Und Joseph gebot seinen Knechten, den Ärzten, seinen Vater einzubalsamieren. Und die Ärzte balsamierten Israel ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Und es wurden vierzig Tage für ihn erfüllt, denn also werden erfüllt die Tage des Einbalsamierens. Und die Ägypter beweinten ihn siebzig Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Und als die Tage seines Beweinens vorüber waren, da redete Joseph zum Hause des Pharao und sprach: Wenn ich doch Gnade gefunden habe in euren Augen, so redet doch vor den Ohren des Pharao und saget:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mein Vater hat mich schwören lassen und gesagt: Siehe, ich sterbe; in meinem Grabe, das ich mir im Lande Kanaan gegraben habe, daselbst sollst du mich begraben. Und nun laß mich doch hinaufziehen, daß ich meinen Vater begrabe und zurückkomme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Und der Pharao sprach: Ziehe hinauf und begrabe deinen Vater, so wie er dich hat schwören lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Und Joseph zog hinauf, um seinen Vater zu begraben; und mit ihm zogen hinauf alle Knechte des Pharao, die Ältesten seines Hauses, und alle Ältesten des Landes Ägypten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'und das ganze Haus Josephs und seine Brüder und das Haus seines Vaters; nur ihre Kinder und ihr Kleinvieh und ihre Rinder ließen sie im Land Gosen zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Auch zogen sowohl Wagen als Reiter mit ihm hinauf, und der Zug war sehr groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Und sie kamen bis zur Tenne Atad, die jenseit des Jordan liegt, und sie hielten daselbst eine sehr große und schwere Klage; und er stellte um seinen Vater eine Trauer von sieben Tagen an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Und die Bewohner des Landes, die Kanaaniter, sahen die Trauer bei der Tenne Atad, und sie sprachen: Das ist eine schwere Trauer der Ägypter; daher gab man ihr den Namen Avel-Mizraim, die jenseit des Jordan liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Und seine Söhne taten ihm, so wie er ihnen geboten hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'und seine Söhne führten ihn in das Land Kanaan und begruben ihn in der Höhle des Feldes Machpela, die Abraham samt dem Felde zum Erbbegräbnis gekauft hatte von Ephron, dem Hethiter, vor Mamre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Und Joseph kehrte wieder nach Ägypten zurück, er und seine Brüder und alle, die mit ihm hinaufgezogen waren, um seinen Vater zu begraben, nachdem er seinen Vater begraben hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Und als die Brüder Josephs sahen, daß ihr Vater gestorben war, da sprachen sie: Wenn nun Joseph uns anfeindete und uns gar all das Böse vergelten würde, das wir ihm angetan haben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Und sie entboten dem Joseph und sprachen: Dein Vater hat vor seinem Tode befohlen und gesagt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'So sollt ihr zu Joseph sprechen: Ach, vergib doch die Übertretung deiner Brüder und ihre Sünde! Denn sie haben dir Böses angetan. Und nun vergib doch die Übertretung der Knechte des Gottes deines Vaters! Und Joseph weinte, als sie zu ihm redeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Und auch seine Brüder gingen und fielen vor ihm nieder und sprachen: Siehe, wir sind deine Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Da sprach Joseph zu ihnen: Fürchtet euch nicht; denn bin ich an Gottes Statt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Ihr zwar, ihr hattet Böses wider mich im Sinne; Gott aber hatte im Sinne, es gut zu machen, auf daß er täte, wie es an diesem Tage ist, um ein großes Volk am Leben zu erhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Und nun, fürchtet euch nicht; ich werde euch und eure Kinder versorgen. Und er tröstete sie und redete zu ihrem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Und Joseph wohnte in Ägypten, er und das Haus seines Vaters; und Joseph lebte hundertzehn Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Und Joseph sah von Ephraim Kinder des dritten Gliedes; auch die Söhne Makirs, des Sohnes Manasses, wurden auf die Knie Josephs geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Und Joseph sprach zu seinen Brüdern: Ich sterbe; und Gott wird euch gewißlich heimsuchen und euch aus diesem Lande hinaufführen in das Land, das er Abraham, Isaak und Jakob zugeschworen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Und Joseph ließ die Söhne Israels schwören und sprach: Gott wird euch gewißlich heimsuchen; so führet meine Gebeine von hier hinauf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Und Joseph starb, hundertzehn Jahre alt; und sie balsamierten ihn ein, und man legte ihn in eine Lade in Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Und dies sind die Namen der Söhne Israels, die nach Ägypten kamen; mit Jakob kamen sie, ein jeder mit seinem Hause:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi und Juda;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issaschar, Sebulon und Benjamin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan und Naphtali, Gad und Aser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Und es waren aller Seelen, die aus den Lenden Jakobs hervorgegangen waren, siebzig Seelen. Und Joseph war in Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Und Joseph starb und alle seine Brüder und dasselbige ganze Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Und die Kinder Israel waren fruchtbar und wimmelten und mehrten sich und wurden sehr, sehr stark, und das Land wurde voll von ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Da stand ein neuer König über Ägypten auf, der Joseph nicht kannte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Und er sprach zu seinem Volke: Siehe, das Volk der Kinder Israel ist zahlreicher und stärker als wir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Wohlan, laßt uns klug gegen dasselbe handeln, daß es sich nicht mehre und es nicht geschehe, wenn Krieg eintritt, daß es sich auch zu unseren Feinden schlage und wider uns streite und aus dem Lande hinaufziehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Und sie setzten Fronvögte über dasselbe, um es mit ihren Lastarbeiten zu drücken; und es baute dem Pharao Vorratsstädte: Pithom und Raemses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Aber so wie sie es drückten, also mehrte es sich, und also breitete es sich aus; und es graute ihnen vor den Kindern Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Und die Ägypter hielten die Kinder Israel mit Härte zum Dienst an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Und sie machten ihnen das Leben bitter durch harten Dienst in Lehm und in Ziegeln, und durch allerlei Dienst auf dem Felde, neben all ihrem Dienst, zu welchem sie sie anhielten mit Härte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Und der König von Ägypten sprach zu den hebräischen Hebammen, von denen der Name der einen Schiphra und der Name der anderen Pua war, und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Wenn ihr den Hebräerinnen bei der Geburt helfet und ihr sie auf dem Geburtsstuhl sehet: wenn es ein Sohn ist, so tötet ihn, und wenn eine Tochter, so mag sie leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Aber die Hebammen fürchteten Gott und taten nicht, wie der König von Ägypten zu ihnen gesagt hatte, und erhielten die Knäblein am Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Und der König von Ägypten rief die Hebammen und sprach zu ihnen: Warum habt ihr dieses getan und die Knäblein am Leben erhalten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Und die Hebammen sprachen zum Pharao: Weil die hebräischen Weiber nicht sind wie die ägyptischen, denn sie sind kräftig; ehe die Hebamme zu ihnen kommt, haben sie geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Und Gott tat den Hebammen Gutes; und das Volk mehrte sich und wurde sehr stark.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Und es geschah, weil die Hebammen Gott fürchteten, so machte er ihnen Häuser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Da gebot der Pharao all seinem Volke und sprach: Jeden Sohn, der geboren wird, sollt ihr in den Strom werfen, jede Tochter aber sollt ihr leben lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Und ein Mann vom Hause Levi ging hin und nahm eine Tochter Levis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Und das Weib ward schwanger und gebar einen Sohn. Und sie sah, daß er schön war, und verbarg ihn drei Monate.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Und als sie ihn nicht länger verbergen konnte, nahm sie für ihn ein Kästlein von Schilfrohr und verpichte es mit Erdharz und mit Pech und legte das Kind darein, und legte es in das Schilf am Ufer des Stromes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Und seine Schwester stellte sich von ferne, um zu erfahren, was ihm geschehen würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Und die Tochter des Pharao ging hinab, um an dem Strome zu baden, und ihre Mägde gingen an der Seite des Stromes. Und sie sah das Kästlein mitten im Schilf und sandte ihre Magd hin und ließ es holen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Und sie öffnete es und sah das Kind, und siehe, der Knabe weinte. Und es erbarmte sie seiner, und sie sprach: Von den Kindern der Hebräer ist dieses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Und seine Schwester sprach zu der Tochter des Pharao: Soll ich hingehen und dir ein säugendes Weib von den Hebräerinnen rufen, daß sie dir das Kind säuge?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Und die Tochter des Pharao sprach zu ihr: Gehe hin. Da ging die Jungfrau hin und rief des Kindes Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Und die Tochter des Pharao sprach zu ihr: Nimm dieses Kind mit und säuge es mir, und ich werde dir deinen Lohn geben. Und das Weib nahm das Kind und säugte es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Und als das Kind groß wurde, brachte sie es der Tochter des Pharao, und es wurde ihr zum Sohne; und sie gab ihm den Namen Mose und sprach: denn aus dem Wasser habe ich ihn gezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Und es geschah in selbigen Tagen, als Mose groß geworden war, da ging er aus zu seinen Brüdern und sah ihren Lastarbeiten zu; und er sah einen ägyptischen Mann, der einen hebräischen Mann von seinen Brüdern schlug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Und er wandte sich dahin und dorthin, und als er sah, daß kein Mensch da war, erschlug er den Ägypter und verscharrte ihn im Sande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Und er ging am zweiten Tage aus, und siehe, zwei hebräische Männer zankten sich. Da sprach er zu dem Schuldigen: Warum schlägst du deinen Nächsten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Und er sprach: Wer hat dich zum Obersten und Richter über uns gesetzt? Gedenkst du mich zu töten, wie du den Ägypter getötet hast? Da fürchtete sich Mose und sprach: Fürwahr, die Sache ist kund geworden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Und der Pharao hörte diese Sache und suchte Mose zu töten. Und Mose floh vor dem Pharao und weilte im Lande Midian. Und er saß an einem Brunnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Und der Priester von Midian hatte sieben Töchter; und sie kamen und schöpften und füllten die Tränkrinnen, um die Herde ihres Vaters zu tränken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Und die Hirten kamen und trieben sie hinweg. Da stand Mose auf und half ihnen und tränkte ihre Herde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Und sie kamen zu Reghuel, ihrem Vater, und er sprach: Warum seid ihr heute so bald gekommen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Und sie sprachen: Ein ägyptischer Mann hat uns aus der Hand der Hirten errettet und hat auch sogar für uns geschöpft und die Herde getränkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Da sprach er zu seinen Töchtern: Und wo ist er? Warum habt ihr denn den Mann zurückgelassen? Rufet ihn, daß er mit uns esse. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Und Mose willigte ein, bei dem Manne zu bleiben; und er gab Mose Zippora, seine Tochter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Und sie gebar einen Sohn, und er gab ihm den Namen Gersom, denn er sprach: Ein Fremdling bin ich geworden in fremdem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Und es geschah während jener vielen Tage, da starb der König von Ägypten; und die Kinder Israel seufzten wegen des Dienstes und schrieen; und ihr Geschrei wegen des Dienstes stieg hinauf zu Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Und Gott hörte ihr Wehklagen, und Gott gedachte seines Bundes mit Abraham, mit Isaak und mit Jakob;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Und Gott sah die Kinder Israel, und Gott nahm Kenntnis von ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Und Mose weidete die Herde Jethros, seines Schwiegervaters, des Priesters von Midian. Und er trieb die Herde hinter die Wüste und kam an den Berg Gottes, an den Horeb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Da erschien ihm der Engel Jehovas in einer Feuerflamme mitten aus einem Dornbusche; und er sah: und siehe, der Dornbusch brannte im Feuer, und der Dornbusch wurde nicht verzehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Und Mose sprach: Ich will doch hinzutreten und dieses große Gesicht sehen, warum der Dornbusch nicht verbrennt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Und als Jehova sah, daß er herzutrat, um zu sehen, da rief Gott ihm mitten aus dem Dornbusche zu und sprach: Mose! Mose! Und er sprach: Hier bin ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Und er sprach: Nahe nicht hierher! Ziehe deine Schuhe aus von deinen Füßen, denn der Ort, auf dem du stehst, ist heiliges Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Und er sprach: Ich bin der Gott deines Vaters, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs. Da verbarg Mose sein Angesicht, denn er fürchtete sich, Gott anzuschauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Und Jehova sprach: Gesehen habe ich das Elend meines Volkes, das in Ägypten ist, und sein Geschrei wegen seiner Treiber habe ich gehört; denn ich kenne seine Schmerzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Und ich bin herabgekommen, um es aus der Hand der Ägypter zu erretten und es aus diesem Lande hinaufzuführen in ein gutes und geräumiges Land, in ein Land, das von Milch und Honig fließt, an den Ort der Kanaaniter und der Hethiter und der Amoriter und der Perisiter und der Hewiter und der Jebusiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Und nun siehe, das Geschrei der Kinder Israel ist vor mich gekommen; und ich habe auch den Druck gesehen, womit die Ägypter sie drücken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Und nun gehe hin, denn ich will dich zu dem Pharao senden, daß du mein Volk, die Kinder Israel, aus Ägypten herausführest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Und Mose sprach zu Gott: Wer bin ich, daß ich zu dem Pharao gehen und daß ich die Kinder Israel aus Ägypten herausführen sollte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Und er sprach: Weil ich mit dir sein werde; und dies sei dir das Zeichen, daß ich dich gesandt habe: wenn du das Volk aus Ägypten herausgeführt hast, werdet ihr auf diesem Berge Gott dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Und Mose sprach zu Gott: Siehe, wenn ich zu den Kindern Israel komme und zu ihnen spreche: Der Gott eurer Väter hat mich zu euch gesandt, und sie zu mir sagen werden: Welches ist sein Name? was soll ich zu Ihnen sagen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Da sprach Gott zu Mose: Ich bin, der ich bin. Und er sprach: Also sollst du zu den Kindern Israel sagen: \"Ich bin\" hat mich zu euch gesandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Und Gott sprach weiter zu Mose: Also sollst du zu den Kindern Israel sagen: Jehova, der Gott eurer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs, hat mich zu euch gesandt. Das ist mein Name in Ewigkeit, und das ist mein Gedächtnis von Geschlecht zu Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Gehe hin und versammle die Ältesten Israels und sprich zu ihnen: Jehova, der Gott eurer Väter, ist mir erschienen, der Gott Abrahams, Isaaks und Jakobs, und hat gesagt: Angesehen habe ich euch und was euch in Ägypten geschehen ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'und ich habe gesagt: Ich will euch aus dem Elend Ägyptens heraufführen in das Land der Kanaaniter und der Hethiter und der Amoriter und der Perisiter und der Hewiter und der Jebusiter, in ein Land, das von Milch und Honig fließt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Und sie werden auf deine Stimme hören; und du sollst hineingehen, du und die Ältesten Israels, zu dem Könige von Ägypten, und ihr sollt zu ihm sagen: Jehova, der Gott der Hebräer, ist uns begegnet; und nun laß uns doch drei Tagereisen weit in die Wüste ziehen, daß wir Jehova, unserem Gott, opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Aber ich weiß wohl, daß der König von Ägypten euch nicht ziehen lassen wird, auch nicht durch eine starke Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Und ich werde meine Hand ausstrecken und Ägypten schlagen mit allen meinen Wundern, die ich in seiner Mitte tun werde; und danach wird er euch ziehen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Und ich werde diesem Volke Gnade geben in den Augen der Ägypter, und es wird geschehen, wenn ihr ausziehet, sollt ihr nicht leer ausziehen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'und es soll jedes Weib von ihrer Nachbarin und von ihrer Hausgenossin silberne Geräte und goldene Geräte und Kleider fordern; und ihr sollt sie auf eure Söhne und auf eure Töchter legen und die Ägypter berauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Und Mose antwortete und sprach: Aber siehe, sie werden mir nicht glauben und nicht auf meine Stimme hören; denn sie werden sagen: Jehova ist dir nicht erschienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Da sprach Jehova zu ihm: Was ist das in deiner Hand? Und er sprach: Ein Stab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Und er sprach: Wirf ihn auf die Erde. Da warf er ihn auf die Erde, und er wurde zur Schlange; und Mose floh vor ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Und Jehova sprach zu Mose: Strecke deine Hand aus und fasse sie beim Schwanze. Und er streckte seine Hand aus und ergriff sie, und sie wurde zum Stabe in seiner Hand: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'auf daß sie glauben, daß Jehova dir erschienen ist, der Gott ihrer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Und Jehova sprach weiter zu ihm: Stecke doch deine Hand in deinen Busen. Und er steckte seine Hand in seinen Busen; und er zog sie heraus, und siehe, seine Hand war aussätzig wie Schnee.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Und er sprach: Tue deine Hand wieder in deinen Busen. Und er tat seine Hand wieder in seinen Busen; und er zog sie aus seinem Busen heraus, und siehe, sie war wieder wie sein Fleisch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Und es wird geschehen, wenn sie dir nicht glauben und nicht auf die Stimme des ersten Zeichens hören, so werden sie der Stimme des anderen Zeichens glauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Und es wird geschehen, wenn sie selbst diesen zwei Zeichen nicht glauben und nicht auf deine Stimme hören, so sollst du von dem Wasser des Stromes nehmen und es auf das Trockene gießen; und das Wasser, das du aus dem Strome nehmen wirst, es wird zu Blut werden auf dem Trockenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Und Mose sprach zu Jehova: Ach, Herr! Ich bin kein Mann der Rede, weder seit gestern noch seit vorgestern, noch seitdem du zu deinem Knechte redest; denn ich bin schwer von Mund und schwer von Zunge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Da sprach Jehova zu ihm: Wer hat dem Menschen den Mund gemacht? Oder wer macht stumm oder taub oder sehend oder blind? Nicht ich, Jehova?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Und nun gehe hin, und ich will mit deinem Munde sein und dich lehren, was du reden sollst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Und er sprach: Ach, Herr! Sende doch, durch wen du senden willst!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Da entbrannte der Zorn Jehovas wider Mose, und er sprach: Ist nicht Aaron, der Levit, dein Bruder? Ich weiß, daß er reden kann. Und siehe, er geht auch aus, dir entgegen; und sieht er dich, so wird er sich freuen in seinem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Und du sollst zu ihm reden und die Worte in seinen Mund legen, und ich will mit deinem Munde und mit seinem Munde sein und will euch lehren, was ihr tun sollt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Und er soll für dich zum Volke reden; und es wird geschehen, er wird dir zum Munde sein, und du wirst ihm zum Gott sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Und diesen Stab sollst du in deine Hand nehmen, mit welchem du die Zeichen tun sollst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Und Mose ging hin und kehrte zu Jethro, seinem Schwiegervater, zurück und sprach zu ihm: Laß mich doch gehen und zu meinen Brüdern zurückkehren, die in Ägypten sind, daß ich sehe, ob sie noch leben. Und Jethro sprach zu Mose: Gehe hin in Frieden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Und Jehova sprach zu Mose in Midian: Gehe hin, kehre nach Ägypten zurück; denn alle die Männer sind gestorben, die nach deinem Leben trachteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Und Mose nahm sein Weib und seine Söhne und ließ sie auf Eseln reiten und kehrte in das Land Ägypten zurück; und Mose nahm den Stab Gottes in seine Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Und Jehova sprach zu Mose: Wenn du hinziehst, um nach Ägypten zurückzukehren, so sieh zu, daß du alle die Wunder, die ich in deine Hand gelegt habe, vor dem Pharao tuest. Und ich, ich will sein Herz verhärten, so daß er das Volk nicht ziehen lassen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Und du sollst zu dem Pharao sagen: So spricht Jehova: Mein Sohn, mein erstgeborener, ist Israel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'und ich sage zu dir: Laß meinen Sohn ziehen, daß er mir diene! Und weigerst du dich, ihn ziehen zu lassen, siehe, so werde ich deinen Sohn, deinen erstgeborenen, töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Und es geschah auf dem Wege, in der Herberge, da fiel Jehova ihn an und suchte ihn zu töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Da nahm Zippora einen scharfen Stein und schnitt die Vorhaut ihres Sohnes ab und warf sie an seine Füße und sprach: Fürwahr, du bist mir ein Blutbräutigam!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Da ließ er von ihm ab. Damals sprach sie \"Blutbräutigam\" der Beschneidung wegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Und Jehova sprach zu Aaron: Gehe hin, Mose entgegen in die Wüste. Und er ging hin und traf ihn am Berge Gottes und küßte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Und Mose berichtete dem Aaron alle Worte Jehovas, der ihn gesandt, und alle die Zeichen, die er ihm geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Und Mose und Aaron gingen hin, und sie versammelten alle Ältesten der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Und Aaron redete alle die Worte, welche Jehova zu Mose geredet hatte, und er tat die Zeichen vor den Augen des Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Und das Volk glaubte; und als sie hörten, daß Jehova die Kinder Israel heimgesucht und daß er ihr Elend gesehen habe, da neigten sie sich und beteten an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Und danach gingen Mose und Aaron hinein und sprachen zu dem Pharao: So spricht Jehova, der Gott Israels: Laß mein Volk ziehen, daß sie mir ein Fest halten in der Wüste!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Da sprach der Pharao: Wer ist Jehova, auf dessen Stimme ich hören soll, Israel ziehen zu lassen? Ich kenne Jehova nicht, und auch werde ich Israel nicht ziehen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Und sie sprachen: Der Gott der Hebräer ist uns begegnet. Laß uns doch drei Tagereisen weit in die Wüste ziehen und Jehova, unserem Gott, opfern, daß er uns nicht schlage mit der Pest oder mit dem Schwerte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Und der König von Ägypten sprach zu ihnen: Warum, Mose und Aaron, wollt ihr das Volk von seinen Arbeiten losmachen? Gehet an eure Lastarbeiten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Und der Pharao sprach: Siehe, das Volk des Landes ist nun zahlreich, und ihr wollt sie von ihren Lastarbeiten feiern lassen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Und der Pharao befahl selbigen Tages den Treibern des Volkes und seinen Vorstehern und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Ihr sollt nicht mehr, wie früher, dem Volke Stroh geben, um Ziegel zu streichen; sie sollen selbst hingehen und sich Stroh sammeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Und die Anzahl Ziegel, die sie früher gemacht haben, sollt ihr ihnen auflegen; ihr sollt nichts daran mindern, denn sie sind träge; darum schreien sie und sprechen: Wir wollen hinziehen, wir wollen unserem Gott opfern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Schwer laste der Dienst auf den Männern, daß sie damit zu schaffen haben und nicht achten auf Worte des Trugs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Und die Treiber des Volkes und seine Vorsteher gingen hinaus und redeten zu dem Volke und sprachen: So spricht der Pharao: Ich werde euch kein Stroh geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'gehet ihr selbst hin, holet euch Stroh, wo ihr es findet; doch an eurem Dienste wird nichts gemindert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Und das Volk zerstreute sich im ganzen Lande Ägypten, um Stoppeln zu sammeln zu Stroh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Und die Treiber drängten sie und sprachen: Vollendet eure Arbeiten, das Tagewerk an seinem Tage, wie früher, als Stroh da war!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Und die Vorsteher der Kinder Israel, welche die Treiber des Pharao über sie gesetzt hatten, wurden geschlagen, indem man sagte: Warum habt ihr euren Satz Ziegel, sowohl gestern als heute, nicht vollendet wie früher?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Da gingen die Vorsteher der Kinder Israel hinein und schrieen zu dem Pharao und sprachen: Warum tust du deinen Knechten also?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Stroh wird deinen Knechten nicht gegeben, und man sagt zu uns: Machet Ziegel! Und siehe, deine Knechte werden geschlagen, und es ist die Schuld deines Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Und er sprach: Ihr seid träge, träge seid ihr! Darum sprechet ihr: Wir wollen hinziehen, wir wollen Jehova opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Und nun gehet hin, arbeitet! Und Stroh wird euch nicht gegeben werden, und das Maß Ziegel sollt ihr liefern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Da sahen die Vorsteher der Kinder Israel, daß es übel mit ihnen stand, weil man sagte: Ihr sollt nichts mindern an euren Ziegeln: das Tagewerk an seinem Tage!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Und sie begegneten Mose und Aaron, die ihnen entgegentraten, als sie von dem Pharao herauskamen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Und sie sprachen zu ihnen: Jehova sehe auf euch und richte, daß ihr unseren Geruch stinkend gemacht habt vor dem Pharao und vor seinen Knechten, so daß ihr ihnen das Schwert in die Hand gegeben habt, uns zu töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Da wandte sich Mose zu Jehova und sprach: Herr, warum hast du so übel an diesem Volke getan? Warum doch hast du mich gesandt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Denn seitdem ich zu dem Pharao hineingegangen bin, um in deinem Namen zu reden, hat er diesem Volke übel getan, und du hast dein Volk durchaus nicht errettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Und Jehova sprach zu Mose: Nun sollst du sehen, was ich dem Pharao tun werde; denn durch eine starke Hand gezwungen soll er sie ziehen lassen, und durch eine starke Hand gezwungen soll er sie aus seinem Lande wegtreiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Und Gott redete zu Mose und sprach zu ihm: Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Und ich bin Abraham, Isaak und Jakob erschienen als Gott, der Allmächtige; aber mit meinem Namen Jehova habe ich mich ihnen nicht kundgegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Und auch habe ich meinen Bund mit ihnen aufgerichtet, ihnen das Land Kanaan zu geben, das Land ihrer Fremdlingschaft, in welchem sie als Fremdlinge geweilt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Und auch habe ich das Wehklagen der Kinder Israel gehört, welche die Ägypter zum Dienst anhalten, und habe meines Bundes gedacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Darum sprich zu den Kindern Israel: Ich bin Jehova, und ich werde euch herausführen unter den Lastarbeiten der Ägypter hinweg und werde euch erretten aus ihrem Dienste und euch erlösen mit ausgestrecktem Arm und durch große Gerichte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Und ich will euch annehmen mir zum Volke und will euer Gott sein; und ihr sollt erkennen, daß ich Jehova, euer Gott, bin, der euch herausführt unter den Lastarbeiten der Ägypter hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Und ich werde euch in das Land bringen, welches dem Abraham, Isaak und Jakob zu geben ich meine Hand erhoben habe, und werde es euch zum Besitztum geben, ich, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Und Mose redete also zu den Kindern Israel; aber sie hörten nicht auf Mose vor Ungeduld und vor hartem Dienste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Gehe hinein, rede zu dem Pharao, dem Könige von Ägypten, daß er die Kinder Israel aus seinem Lande ziehen lasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Und Mose redete vor Jehova und sprach: Siehe, die Kinder Israel haben nicht auf mich gehört, und wie sollte der Pharao mich hören, zumal ich unbeschnitten an Lippen bin?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Und Jehova redete zu Mose und zu Aaron und gab ihnen Befehl an die Kinder Israel und an den Pharao, den König von Ägypten, um die Kinder Israel aus dem Lande Ägypten hinauszuführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Dies sind die Häupter ihrer Vaterhäuser: Die Söhne Rubens, des Erstgeborenen Israels: Hanok und Pallu, Hezron und Karmi; das sind die Geschlechter Rubens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Und die Söhne Simeons: Jemuel und Jamin und Ohad und Jakin und Zochar und Saul, der Sohn der Kanaaniterin; das sind die Geschlechter Simeons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Und dies sind die Namen der Söhne Levis nach ihren Geschlechtern: Gerson und Kehath und Merari; und die Lebensjahre Levis waren hundertsiebenunddreißig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Die Söhne Gersons: Libni und Simei, nach ihren Familien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Und die Söhne Kehaths: Amram und Jizhar und Hebron und Ussiel; und die Lebensjahre Kehaths waren hundertdreiunddreißig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Und die Söhne Meraris: Machli und Musi; das sind die Familien Levis nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Und Amram nahm Jokebed, seine Muhme, sich zum Weibe, und sie gebar ihm Aaron und Mose; und die Lebensjahre Amrams waren hundertsiebenunddreißig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Und die Söhne Jizhars: Korah und Nepheg und Sikri.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Und die Söhne Ussiels: Mischael und Elzaphan und Sithri.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Und Aaron nahm Elischeba, die Tochter Amminadabs, die Schwester Nachschons, sich zum Weibe; und sie gabar ihm Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Und die Söhne Korahs: Assir und Elkana und Abiasaph; das sind die Familien der Korhiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Und Eleasar, der Sohn Aarons, nahm eine von den Töchtern Putiels sich zum Weibe, und sie gebar ihm Pinehas; das sind die Häupter der Väter der Leviten nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Dieser Aaron und dieser Mose sind es, zu denen Jehova gesprochen hat: Führet die Kinder Israel aus dem Lande Ägypten hinaus, nach ihren Heeren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Diese sind es, die zu dem Pharao, dem Könige von Ägypten, redeten, um die Kinder Israel aus Ägypten hinauszuführen: dieser Mose und dieser Aaron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Und es geschah an dem Tage, da Jehova zu Mose redete im Lande Ägypten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'da redete Jehova zu Mose und sprach: Ich bin Jehova; rede zu dem Pharao, dem Könige von Ägypten alles, was ich zu dir rede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Und Mose sprach vor Jehova: Siehe, ich bin unbeschnitten an Lippen, und wie sollte der Pharao auf mich hören?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Und Jehova sprach zu Mose: Siehe, ich habe dich dem Pharao zum Gott gesetzt, und dein Bruder Aaron soll dein Prophet sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Du sollst alles reden, was ich dir gebieten werde, und dein Bruder Aaron soll zu dem Pharao reden, daß er die Kinder Israel aus seinem Lande ziehen lasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Und ich will das Herz des Pharao verhärten und meine Zeichen und meine Wunder mehren im Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Und der Pharao wird nicht auf euch hören; und ich werde meine Hand an Ägypten legen und meine Heere, mein Volk, die Kinder Israel, aus dem Lande Ägypten herausführen durch große Gerichte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Und die Ägypter sollen erkennen, daß ich Jehova bin, wenn ich meine Hand über Ägypten ausstrecke und die Kinder Israel aus ihrer Mitte herausführe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Und Mose und Aaron taten es; so wie Jehova ihnen geboten hatte, also taten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Und Mose war achtzig Jahre alt, und Aaron dreiundachtzig Jahre alt, als sie zu dem Pharao redeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Und Jehova redete zu Mose und zu Aaron und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Wenn der Pharao zu euch reden und sagen wird: Tut ein Wunder für euch! so sollst du zu Aaron sagen: Nimm deinen Stab und wirf ihn hin vor dem Pharao; er soll zur Schlange werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Und Mose und Aaron gingen zu dem Pharao hinein und taten also, wie Jehova geboten hatte; und Aaron warf seinen Stab hin vor dem Pharao und vor seinen Knechten, und er wurde zur Schlange.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Da berief auch der Pharao die Weisen und die Zauberer; und auch sie, die Schriftgelehrten Ägyptens, taten also mit ihren Zauberkünsten');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'und warfen ein jeder seinen Stab hin, und sie wurden zu Schlangen; aber Aarons Stab verschlang ihre Stäbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Und das Herz des Pharao verhärtete sich, und er hörte nicht auf sie, so wie Jehova geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Und Jehova sprach zu Mose: Das Herz des Pharao ist verstockt; er weigert sich, das Volk ziehen zu lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Gehe am Morgen zum Pharao siehe, er wird ans Wasser hinausgehen und tritt ihm entgegen an dem Ufer des Stromes, und nimm den Stab, der in eine Schlange verwandelt worden, in deine Hand');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'und sprich zu ihm: Jehova, der Gott der Hebräer, hat mich zu dir gesandt und gesagt: Laß mein Volk ziehen, daß sie mir dienen in der Wüste! Aber siehe, du hast bisher nicht gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'So spricht Jehova: Daran sollst du erkennen, daß ich Jehova bin: Siehe, ich will mit dem Stabe, der in meiner Hand ist, auf das Wasser schlagen, das in dem Strome ist, und es wird in Blut verwandelt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Und die Fische, die im Strome sind, werden sterben, und der Strom wird stinken, und die Ägypter wird\'s ekeln, Wasser aus dem Strome zu trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Und Jehova sprach zu Mose: Sprich zu Aaron: Nimm deinen Stab und strecke deine Hand aus über die Wasser Ägyptens, über seine Flüsse, über seine Kanäle und über seine Teiche und über alle seine Wassersammlungen, daß sie zu Blut werden; und es wird Blut sein im ganzen Lande Ägypten, sowohl in hölzernen als auch in steinernen Gefäßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Und Mose und Aaron taten also, wie Jehova geboten hatte; und er erhob den Stab und schlug das Wasser, das im Strome war, vor den Augen des Pharao und vor den Augen seiner Knechte. Da wurde alles Wasser, das im Strome war, in Blut verwandelt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'und die Fische, die im Strome waren, starben, und der Strom wurde stinkend, und die Ägypter konnten das Wasser aus dem Strome nicht trinken; und das Blut war im ganzen Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Und die Schriftgelehrten Ägyptens taten ebenso mit ihren Zauberkünsten; und das Herz des Pharao verhärtete sich, und er hörte nicht auf sie, so wie Jehova geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Und der Pharao wandte sich und ging in sein Haus und nahm auch dies nicht zu Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Und alle Ägypter gruben rings um den Strom nach Wasser zum Trinken, denn von dem Wasser des Stromes konnten sie nicht trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Und es wurden sieben Tage erfüllt, nachdem Jehova den Strom geschlagen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Und Jehova sprach zu Mose: Gehe zu dem Pharao hinein und sprich zu ihm: So spricht Jehova: Laß mein Volk ziehen, daß sie mir dienen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Und wenn du dich weigerst, es ziehen zu lassen, siehe, so will ich dein ganzes Gebiet mit Fröschen schlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Und der Strom wird von Fröschen wimmeln, und sie werden heraufsteigen und in dein Haus kommen und in dein Schlafgemach und auf dein Bett und in die Häuser deiner Knechte und unter dein Volk und in deine Öfen und in deine Backtröge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Und die Frösche werden heraufkommen über dich und über dein Volk und über alle deine Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Und Jehova sprach zu Mose: Sprich zu Aaron: Strecke deine Hand mit deinem Stabe aus über die Flüsse, über die Kanäle und über die Teiche, und laß die Frösche über das Land Ägypten heraufkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Da streckte Aaron seine Hand aus über die Wasser in Ägypten, und die Frösche kamen herauf und bedeckten das Land Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Und die Schriftgelehrten taten ebenso mit ihren Zauberkünsten und ließen die Frösche über das Land Ägypten heraufkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Und der Pharao rief Mose und Aaron und sprach: Flehet zu Jehova, daß er die Frösche von mir und von meinem Volke wegnehme, so will ich das Volk ziehen lassen, daß sie Jehova opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Und Mose sprach zum Pharao: Bestimme über mich, auf wann ich für dich und für deine Knechte und für dein Volk flehen soll, die Frösche von dir und aus deinen Häusern auszurotten; nur im Strome sollen sie übrigbleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Und er sprach: Auf morgen. Da sprach er: Es sei nach deinem Worte, auf daß du wissest, daß niemand ist wie Jehova, unser Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Und die Frösche werden von dir weichen und von deinen Häusern und von deinen Knechten und von deinem Volke; nur im Strome sollen sie übrigbleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Und Mose und Aaron gingen von dem Pharao hinaus; und Mose schrie zu Jehova wegen der Frösche, die er über den Pharao gebracht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Und Jehova tat nach dem Worte Moses, und die Frösche starben weg aus den Häusern, aus den Gehöften und von den Feldern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Und sie sammelten sie haufenweise, und das Land stank.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Und als der Pharao sah, daß Erleichterung geworden war, da verstockte er sein Herz, und er hörte nicht auf sie, so wie Jehova geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Und Jehova sprach zu Mose: Sprich zu Aaron: Strecke deinen Stab aus und schlage den Staub der Erde, und er wird zu Stechmücken werden im ganzen Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Und sie taten also; und Aaron streckte seine Hand mit seinem Stabe aus und schlug den Staub der Erde, und die Stechmücken kamen über die Menschen und über das Vieh; aller Staub der Erde wurde zu Stechmücken im ganzen Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Und die Schriftgelehrten taten ebenso mit ihren Zauberkünsten, um die Stechmücken hervorzubringen; aber sie konnten es nicht. Und die Stechmücken kamen über die Menschen und über das Vieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Da sprachen die Schriftgelehrten zum Pharao: Das ist Gottes Finger! Aber das Herz des Pharao verhärtete sich, und er hörte nicht auf sie, so wie Jehova geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Und Jehova sprach zu Mose: Mache dich des Morgens früh auf und tritt vor den Pharao siehe, er wird ans Wasser hinausgehen und sprich zu ihm: Also spricht Jehova: Laß mein Volk ziehen, daß sie mir dienen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Denn wenn du mein Volk nicht ziehen lässest, siehe, so werde ich die Hundsfliegen senden über dich und über deine Knechte und über dein Volk und in deine Häuser; und die Häuser der Ägypter werden voll Hundsfliegen sein und auch der Erdboden, auf dem sie sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Und ich werde an selbigem Tage das Land Gosen aussondern, in welchem mein Volk weilt, daß daselbst keine Hundsfliegen seien, auf daß du wissest, daß ich, Jehova, in der Mitte des Landes bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Und ich werde eine Scheidung setzen zwischen meinem Volke und deinem Volke; morgen wird dieses Zeichen geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Und Jehova tat also; und es kamen Hundsfliegen in Menge in das Haus des Pharao und in die Häuser seiner Knechte; und im ganzen Lande Ägypten wurde das Land von den Hundsfliegen verderbt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Und der Pharao rief Mose und Aaron und sprach: Gehet hin und opfert eurem Gott in dem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Und Mose sprach: Es geziemt sich nicht, also zu tun; denn wir würden Jehova, unserem Gott, der Ägypter Greuel opfern; siehe, opferten wir der Ägypter Greuel vor ihren Augen, würden sie uns nicht steinigen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Drei Tagereisen weit wollen wir in die Wüste ziehen und Jehova, unserem Gott, opfern, so wie er zu uns geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Und der Pharao sprach: Ich will euch ziehen lassen, daß ihr Jehova, eurem Gott, in der Wüste opfert; nur entfernet euch nicht so weit! Flehet für mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Da sprach Mose: Siehe, ich gehe von dir hinaus und will zu Jehova flehen; und morgen werden die Hundsfliegen von dem Pharao weichen, von seinen Knechten und von seinem Volke; nur handle der Pharao ferner nicht betrüglich, daß er das Volk nicht ziehen lasse, um Jehova zu opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Und Mose ging von dem Pharao hinaus und flehte zu Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Und Jehova tat nach dem Worte Moses, und die Hundsfliegen wichen von dem Pharao, von seinen Knechten und von seinem Volke; nicht eine blieb übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Aber der Pharao verstockte sein Herz auch dieses Mal und ließ das Volk nicht ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Und Jehova sprach zu Mose: Gehe zu dem Pharao hinein und sprich zu ihm: So spricht Jehova, der Gott der Hebräer: Laß mein Volk ziehen, daß sie mir dienen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Denn wenn du dich weigerst, sie ziehen zu lassen, und du sie noch festhältst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'siehe, so wird die Hand Jehovas über dein Vieh kommen, das auf dem Felde ist: über die Pferde, über die Esel, über die Kamele, über die Rinder und über das Kleinvieh, eine sehr schwere Pest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Und Jehova wird einen Unterschied machen zwischen dem Vieh Israels und dem Vieh der Ägypter, und von allem, was den Kindern Israel gehört, wird nichts sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Und Jehova bestimmte eine Zeit und sprach: Morgen wird Jehova dieses tun im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Und Jehova tat dieses am anderen Tage, und alles Vieh der Ägypter starb, aber von dem Vieh der Kinder Israel starb nicht eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Und der Pharao sandte hin, und siehe, von dem Vieh Israels war auch nicht eines gestorben. Aber das Herz des Pharao verstockte sich, und er ließ das Volk nicht ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Und Jehova sprach zu Mose und zu Aaron: Nehmet eure Fäuste voll Ofenruß, und Mose streue ihn gen Himmel vor den Augen des Pharao;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'und er wird zu Staub werden über dem ganzen Lande Ägypten und wird an Menschen und Vieh zu Geschwüren werden, die in Blattern ausbrechen, im ganzen Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Und sie nahmen den Ofenruß und stellten sich vor den Pharao, und Mose streute ihn gen Himmel; und er wurde zu Blattergeschwüren, die an Menschen und Vieh ausbrachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Und die Schriftgelehrten vermochten nicht vor Mose zu stehen wegen der Geschwüre; denn die Geschwüre waren an den Schriftgelehrten und an allen Ägyptern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Und Jehova verhärtete das Herz des Pharao, und er hörte nicht auf sie, so wie Jehova zu Mose geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Und Jehova sprach zu Mose: Mache dich des Morgens früh auf und tritt vor dem Pharao und sprich zu ihm: So spricht Jehova, der Gott der Hebräer: Laß mein Volk ziehen, daß sie mir dienen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Denn dieses Mal will ich alle meine Plagen in dein Herz senden und über deine Knechte und über dein Volk, auf daß du wissest, daß niemand ist wie ich auf der ganzen Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Denn jetzt hätte ich meine Hand ausgestreckt und hätte dich und dein Volk mit der Pest geschlagen, und du wärest vertilgt worden von der Erde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'aber eben deswegen habe ich dich bestehen lassen, um dir meine Kraft zu zeigen und damit man meinen Namen verkündige auf der ganzen Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Erhebst du dich noch wider mein Volk, daß du sie nicht ziehen lässest,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'siehe, so will ich morgen um diese Zeit einen sehr schweren Hagel regnen lassen, desgleichen nicht in Ägypten gewesen ist, von dem Tage seiner Gründung an bis jetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Und nun sende hin, und bringe dein Vieh in Sicherheit und alles, was du auf dem Felde hast. Alle Menschen und alles Vieh, die auf dem Felde gefunden und nicht ins Haus aufgenommen werden, auf die fällt der Hagel herab, und sie werden sterben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Wer unter den Knechten des Pharao das Wort Jehovas fürchtete, der flüchtete seine Knechte und sein Vieh in die Häuser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Wer aber das Wort Jehovas nicht zu Herzen nahm, der ließ seine Knechte und sein Vieh auf dem Felde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Und Jehova sprach zu Mose: Strecke deine Hand aus gen Himmel, daß im ganzen Lande Ägypten Hagel komme auf die Menschen und auf das Vieh und auf alles Kraut des Feldes im Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Und Mose streckte seinen Stab aus gen Himmel, und Jehova sandte Donner und Hagel, und Feuer fuhr zur Erde. Und Jehova ließ Hagel auf das Land Ägypten regnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Und es kam Hagel, und Feuer, mitten im Hagel sich ineinander schlingend, sehr schwer, desgleichen im ganzen Lande Ägypten nicht gewesen war, seitdem es eine Nation geworden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Und der Hagel schlug im ganzen Lande Ägypten alles, was auf dem Felde war, vom Menschen bis zum Vieh; und alles Kraut des Feldes schlug der Hagel, und alle Bäume des Feldes zerbrach er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Nur im Lande Gosen, wo die Kinder Israel waren, war kein Hagel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Und der Pharao sandte hin und ließ Mose und Aaron rufen und sprach zu ihnen: Ich habe dieses Mal gesündigt. Jehova ist der Gerechte, ich aber und mein Volk sind die Schuldigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Flehet zu Jehova, und es sei genug des Donners Gottes und des Hagels; so will ich euch ziehen lassen, und ihr sollt nicht länger bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Da sprach Mose zu ihm: Sowie ich zur Stadt hinausgehe, will ich meine Hände zu Jehova ausbreiten; der Donner wird aufhören, und der Hagel wird nicht mehr sein, auf daß du wissest, daß die Erde Jehova gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Du aber und deine Knechte, ich weiß, daß ihr euch noch nicht vor Jehova Gott fürchten werdet. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Und der Flachs und die Gerste wurden geschlagen; denn die Gerste war in der Ähre, und der Flachs hatte Knospen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Aber der Weizen und der Spelt wurden nicht geschlagen, weil sie spätzeitig sind. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Und Mose ging von dem Pharao zur Stadt hinaus und breitete seine Hände aus zu Jehova; und der Donner und der Hagel hörten auf, und der Regen ergoß sich nicht mehr auf die Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Und als der Pharao sah, daß der Regen und der Hagel und der Donner aufgehört hatten, da fuhr er fort zu sündigen und verstockte sein Herz, er und seine Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Und das Herz des Pharao verhärtete sich, und er ließ die Kinder Israel nicht ziehen, so wie Jehova durch Mose geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Und Jehova sprach zu Mose: Gehe zu dem Pharao hinein, denn ich habe sein Herz verstockt und das Herz seiner Knechte, um diese meine Zeichen in seiner Mitte zu tun');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'und damit du vor den Ohren deiner Kinder und deiner Kindeskinder erzählest, was ich in Ägypten ausgerichtet, und meine Zeichen, die ich unter ihnen getan habe; und ihr werdet wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Da gingen Mose und Aaron zu dem Pharao hinein und sprachen zu ihm: So spricht Jehova, der Gott der Hebräer: Bis wann weigerst du dich, dich vor mir zu demütigen? Laß mein Volk ziehen, daß sie mir dienen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Denn wenn du dich weigerst, mein Volk ziehen zu lassen, siehe, so will ich morgen Heuschrecken in dein Gebiet bringen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'und sie werden das Angesicht des Landes bedecken, daß man das Land nicht wird sehen können; und sie werden das Übrige fressen, das entronnen, das euch übriggeblieben ist von dem Hagel, und werden alle Bäume fressen, die euch auf dem Felde wachsen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'und sie werden deine Häuser erfüllen und die Häuser aller deiner Knechte und die Häuser aller Ägypter, wie es deine Väter und die Väter deiner Väter nicht gesehen haben, seit dem Tage, da sie auf Erden gewesen sind, bis auf diesen Tag. Und er wandte sich und ging von dem Pharao hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Und die Knechte des Pharao sprachen zu ihm: Bis wann soll uns dieser zum Fallstrick sein? Laß die Leute ziehen, daß sie Jehova, ihrem Gott, dienen! Erkennst du noch nicht, daß Ägypten zu Grunde geht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Und Mose und Aaron wurden wieder zu dem Pharao gebracht, und er sprach zu ihnen: Ziehet hin, dienet Jehova, eurem Gott! Welche alle sind es, die ziehen sollen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Da sprach Mose: Mit unseren Jungen und mit unseren Alten wollen wir ziehen, mit unseren Söhnen und mit unseren Töchtern, mit unserem Kleinvieh und mit unseren Rindern wollen wir ziehen; denn wir haben ein Fest Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Und er sprach zu ihnen: Jehova sei so mit euch, wie ich euch und eure Kinder ziehen lasse! Sehet zu, denn ihr habt Böses vor!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Nicht also! Ziehet doch hin, ihr Männer, und dienet Jehova; denn das ist es, was ihr begehrt habt. Und man trieb sie von dem Pharao hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Und Jehova sprach zu Mose: Strecke deine Hand aus über das Land Ägypten wegen der Heuschrecken, daß sie über das Land Ägypten heraufkommen und alles Kraut des Landes fressen, alles was der Hagel übriggelassen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Und Mose streckte seinen Stab aus über das Land Ägypten, und Jehova führte einen Ostwind ins Land selbigen ganzen Tag und die ganze Nacht. Als es Morgen wurde, da trieb der Ostwind die Heuschrecken herbei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Und die Heuschrecken kamen herauf über das ganze Land Ägypten und ließen sich in dem ganzen Gebiet Ägyptens nieder, in gewaltiger Menge; vor ihnen sind nicht derart Heuschrecken gewesen wie diese, und nach ihnen werden nicht derart sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Und sie bedeckten das Angesicht des ganzen Landes, so daß das Land verfinstert wurde; und sie fraßen alles Kraut des Landes und alle Früchte der Bäume, die der Hagel übriggelassen hatte; und es blieb nichts Grünes übrig an den Bäumen und am Kraut des Feldes im ganzen Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Und der Pharao rief Mose und Aaron eilends und sprach: Ich habe gesündigt gegen Jehova, euren Gott, und gegen euch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Und nun vergib doch meine Sünde nur dieses Mal, und flehet zu Jehova, eurem Gott, daß er nur diesen Tod von mir wegnehme!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Da ging er von dem Pharao hinaus und flehte zu Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Und Jehova wandte den Wind in einen sehr starken Westwind, der hob die Heuschrecken auf und warf sie ins Schilfmeer. Es blieb nicht eine Heuschrecke übrig in dem ganzen Gebiet Ägyptens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Und Jehova verhärtete das Herz des Pharao, und er ließ die Kinder Israel nicht ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Und Jehova sprach zu Mose: Strecke deine Hand aus gen Himmel, daß eine Finsternis über das Land Ägypten komme, so daß man die Finsternis greifen möge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Und Mose streckte seine Hand aus gen Himmel; da entstand im ganzen Lande Ägypten eine dichte Finsternis drei Tage lang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Sie sahen einer den anderen nicht, und keiner stand von seinem Platze auf drei Tage lang; aber alle Kinder Israel hatten Licht in ihren Wohnungen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Und der Pharao rief Mose und sprach: Ziehet hin, dienet Jehova; nur euer Kleinvieh und eure Rinder sollen zurückbleiben; auch eure Kinder mögen mit euch ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Und Mose sprach: Auch Schlachtopfer und Brandopfer mußt du in unsere Hände geben, daß wir Jehova, unserem Gott opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'So muß auch unser Vieh mit uns ziehen, nicht eine Klaue darf zurückbleiben; denn davon werden wir nehmen, um Jehova, unserem Gott, zu dienen; wir wissen ja nicht, womit wir Jehova dienen sollen, bis wir dorthin kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Aber Jehova verhärtete das Herz des Pharao, und er wollte sie nicht ziehen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Und der Pharao sprach zu ihm: Gehe hinweg von mir; hüte dich, sieh mein Angesicht nicht wieder! Denn an dem Tage, da du mein Angesicht siehst, wirst du sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Und Mose sprach: Du hast recht geredet, ich werde dein Angesicht nicht mehr wiedersehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Und Jehova sprach zu Mose: Noch eine Plage will ich über den Pharao und über Ägypten bringen; danach wird er euch von hinnen ziehen lassen. Wenn er euch vollends ziehen lassen wird, so wird er euch sogar von hier wegtreiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Rede doch zu den Ohren des Volkes, daß sie ein jeder von seinem Nachbarn und eine jede von ihrer Nachbarin silberne Geräte und goldene Geräte fordern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Und Jehova gab dem Volke Gnade in den Augen der Ägypter. Auch war der Mann Mose sehr groß im Lande Ägypten, in den Augen der Knechte des Pharao und in den Augen des Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Und Mose sprach: So spricht Jehova: Um Mitternacht will ich ausgehen mitten durch Ägypten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'und alle Erstgeburt im Lande Ägypten soll sterben, von dem Erstgeborenen des Pharao, der auf seinem Throne sitzt, bis zum Erstgeborenen der Magd, die hinter der Mühle ist, und alle Erstgeburt des Viehes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Und es wird ein großes Geschrei sein im ganzen Lande Ägypten, desgleichen nie gewesen ist und desgleichen nicht mehr sein wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Aber gegen alle Kinder Israel wird nicht ein Hund seine Zunge spitzen, vom Menschen bis zum Vieh; auf daß ihr wisset, daß Jehova einen Unterschied macht zwischen den Ägyptern und den Israeliten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Und alle diese deine Knechte werden zu mir herabkommen und sich vor mir niederbeugen und sagen: Ziehe aus, du und alles Volk, das dir folgt! Und danach werde ich ausziehen. Und er ging von dem Pharao hinaus in glühendem Zorn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Und Jehova hatte zu Mose gesagt: Der Pharao wird nicht auf euch hören, auf daß meine Wunder sich mehren im Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Und Mose und Aaron haben alle diese Wunder getan vor dem Pharao; aber Jehova verhärtete das Herz des Pharao, und er ließ die Kinder Israel nicht aus seinem Lande ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Und Jehova redete zu Mose und Aaron im Lande Ägypten und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Dieser Monat soll euch der Anfang der Monate sein, er soll euch der erste sein von den Monaten des Jahres.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Redet zu der ganzen Gemeinde Israel und sprechet: Am Zehnten dieses Monats, da nehme sich ein jeder ein Lamm für ein Vaterhaus, ein Lamm für ein Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Und wenn das Haus nicht zahlreich genug ist für ein Lamm, so nehme er es und sein Nachbar, der nächste an seinem Hause, nach der Zahl der Seelen; einen jeden sollt ihr nach dem Maße seines Essens rechnen auf das Lamm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Ein Lamm ohne Fehl sollt ihr haben, ein männliches, einjährig; von den Schafen oder von den Ziegen sollt ihr es nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Und ihr sollt es in Verwahrung haben bis auf den vierzehnten Tag dieses Monats; und die ganze Versammlung der Gemeinde Israel soll es schlachten zwischen den zwei Abenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Und sie sollen von dem Blute nehmen und es an die beiden Pfosten und an die Oberschwelle tun, an den Häusern, in welchen sie es essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Und sie sollen in selbiger Nacht das Fleisch essen, gebraten am Feuer, und ungesäuertes Brot; mit bitteren Kräutern sollen sie es essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ihr sollt nichts roh davon essen und keineswegs im Wasser gesotten, sondern am Feuer gebraten: seinen Kopf samt seinen Schenkeln und samt seinem Eingeweide.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Und ihr sollt nichts davon übriglassen bis an den Morgen; und was davon bis an den Morgen übrigbleibt, sollt ihr mit Feuer verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Und also sollt ihr es essen: Eure Lenden gegürtet, eure Schuhe an euren Füßen und euren Stab in eurer Hand; und ihr sollt es essen in Eile. Es ist das Passah Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Und ich werde in dieser Nacht durch das Land Ägypten gehen und alle Erstgeburt im Lande Ägypten schlagen vom Menschen bis zum Vieh, und ich werde Gericht üben an allen Göttern Ägyptens, ich, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Und das Blut soll euch zum Zeichen sein an den Häusern, worin ihr seid; und sehe ich das Blut, so werde ich an euch vorübergehen; und es wird keine Plage zum Verderben unter euch sein, wenn ich das Land Ägypten schlage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Und dieser Tag soll euch zum Gedächtnis sein, und ihr sollt ihn feiern als Fest dem Jehova; als ewige Satzung bei euren Geschlechtern sollt ihr ihn feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sieben Tage sollt ihr Ungesäuertes essen; ja, am ersten Tage sollt ihr den Sauerteig aus euren Häusern wegtun; denn jeder, der Gesäuertes isset, von dem ersten Tage bis zu dem siebten Tage, selbige Seele soll ausgerottet werden aus Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Und am ersten Tage soll euch eine heilige Versammlung und am siebten Tage eine heilige Versammlung sein; keinerlei Arbeit soll an ihnen getan werden; nur was von jeder Seele gegessen wird, das allein soll von euch bereitet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Und so beobachtet das Fest der ungesäuerten Brote; denn an diesem selbigen Tage habe ich eure Heere aus dem Lande Ägypten herausgeführt. Und ihr sollt diesen Tag beobachten bei euren Geschlechtern als ewige Satzung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Im ersten Monat, am vierzehnten Tage des Monats, am Abend, sollt ihr Ungesäuertes essen bis zu dem einundzwanzigsten Tage des Monats, am Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Sieben Tage soll kein Sauerteig in euren Häusern gefunden werden; denn jeder, der Gesäuertes isset, selbige Seele soll aus der Gemeinde Israel ausgerottet werden, er sei Fremdling oder Eingeborener des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nichts Gesäuertes sollt ihr essen; in allen euren Wohnungen sollt ihr Ungesäuertes essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Und Mose rief alle Ältesten Israels und sprach zu ihnen: Greifet und nehmet euch Kleinvieh nach euren Familien und schlachtet das Passah;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'und nehmet einen Büschel Ysop und tauchet ihn in das Blut, das in dem Becken ist, und streichet von dem Blute, das in dem Becken ist, an die Oberschwelle und an die beiden Pfosten; ihr aber, keiner von euch soll zur Türe seines Hauses hinausgehen bis an den Morgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Und Jehova wird hindurchgehen, die Ägypter zu schlagen; und sieht er das Blut an der Oberschwelle und an den beiden Pfosten, so wird Jehova an der Tür vorübergehen und wird dem Verderber nicht erlauben, in eure Häuser zu kommen, um zu schlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Und ihr sollt dieses beobachten als eine Satzung für dich und deine Kinder ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Und es soll geschehen, wenn ihr in das Land kommet, das Jehova euch geben wird, so wie er geredet hat, so sollt ihr diesen Dienst beobachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Und es soll geschehen, wenn eure Kinder zu euch sagen werden: Was soll euch dieser Dienst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'so sollt ihr sagen: Es ist ein Passahopfer dem Jehova, der an den Häusern der Kinder Israel in Ägypten vorüberging, als er die Ägypter schlug und unsere Häuser rettete. Und das Volk neigte sich und betete an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Und die Kinder Israel gingen hin und taten es; so wie Jehova Mose und Aaron geboten hatte, also taten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Und es geschah um Mitternacht, da schlug Jehova alle Erstgeburt im Lande Ägypten, von dem Erstgeborenen des Pharao, der auf seinem Throne saß, bis zum Erstgeborenen des Gefangenen, der im Kerker war, und alle Erstgeburt des Viehs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Und der Pharao stand in der Nacht auf, er und alle seine Knechte und alle Ägypter, und es entstand ein großes Geschrei in Ägypten; denn es war kein Haus, worin nicht ein Toter war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Und er rief Mose und Aaron in der Nacht und sprach: Machet euch auf, ziehet weg aus der Mitte meines Volkes, sowohl ihr als auch die Kinder Israel, und gehet hin, dienet Jehova, wie ihr geredet habt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'auch euer Kleinvieh und eure Rinder nehmet mit, so wie ihr geredet habt, und gehet hin und segnet mich auch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Und die Ägypter drängten das Volk, sie eilends aus dem Lande ziehen zu lassen; denn sie sagten: Wir alle sind des Todes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Und das Volk trug seinen Teig, ehe er gesäuert war, ihre Backschüsseln in ihre Kleider gebunden, auf ihren Schultern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Und die Kinder Israel taten nach dem Worte Moses und forderten von den Ägyptern silberne Geräte und goldene Geräte und Kleider.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Und Jehova gab dem Volke Gnade in den Augen der Ägypter, und sie gaben ihnen das Geforderte; und sie beraubten die Ägypter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Und die Kinder Israel brachen auf von Raemses nach Sukkoth, bei sechshunderttausend Mann zu Fuß, die Männer ohne die Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Und auch viel Mischvolk zog mit ihnen herauf, und Kleinvieh und Rinder, sehr viel Vieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Und sie backten den Teig, den sie aus Ägypten gebracht hatten, zu ungesäuerten Kuchen; denn er war nicht gesäuert, weil sie aus Ägypten getrieben worden waren und nicht hatten verziehen können; und sie hatten auch keine Zehrung für sich bereitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Und die Wohnzeit der Kinder Israel, die sie in Ägypten zugebracht haben, ist vierhundertdreißig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Und es geschah am Ende der vierhundertdreißig Jahre, und es geschah an diesem selbigen Tage, daß alle Heere Jehovas aus dem Lande Ägypten auszogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Dies ist eine Nacht, die dem Jehova zu beobachten ist, weil er sie aus dem Lande Ägypten herausführte; diese selbige Nacht gehört dem Jehova, sie ist zu beobachten von allen Kindern Israel bei ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Und Jehova redete zu Mose und Aaron: Dies ist die Satzung des Passah: Kein Fremdling soll davon essen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'jedes Mannes Knecht aber, ein für Geld Erkaufter, wenn du ihn beschneidest, dann darf er davon essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Ein Beisaß und ein Mietling soll nicht davon essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'In einem Hause soll es gegessen werden; du sollst nichts von dem Fleische aus dem Hause hinausbringen, und ihr sollt kein Bein an ihm zerbrechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Die ganze Gemeinde Israel soll es feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Und wenn ein Fremdling bei dir weilt und das Passah dem Jehova feiern will, so werde alles Männliche bei ihm beschnitten, und dann komme er herzu, es zu feiern; und er soll sein wie ein Eingeborener des Landes. Aber kein Unbeschnittener soll davon essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Ein Gesetz soll sein für den Eingeborenen und für den Fremdling, der in eurer Mitte weilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Und alle Kinder Israel taten, wie Jehova Mose und Aaron geboten hatte; also taten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Und es geschah an diesem selbigen Tage, da führte Jehova die Kinder Israel aus dem Lande Ägypten heraus nach ihren Heeren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Heilige mir alles Erstgeborene, was irgend die Mutter bricht unter den Kindern Israel, an Menschen und an Vieh; es ist mein. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Und Mose sprach zu dem Volke: Gedenket dieses Tages, an welchem ihr aus Ägypten gezogen seid, aus dem Hause der Knechtschaft; denn mit starker Hand hat Jehova euch von hier herausgeführt; und es soll nichts Gesäuertes gegessen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Heute ziehet ihr aus, im Monat Abib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Und es soll geschehen, wenn Jehova dich bringt in das Land der Kanaaniter und der Hethiter und der Amoriter und der Hewiter und der Jebusiter, das er deinen Vätern geschworen hat, dir zu geben, ein Land, das von Milch und Honig fließt, so sollst du diesen Dienst in diesem Monat halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Sieben Tage sollst du Ungesäuertes essen, und am siebten Tage ist ein Fest dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Die sieben Tage soll Ungesäuertes gegessen werden; und nicht soll Gesäuertes bei dir gesehen werden, noch soll Sauerteig bei dir gesehen werden in allen deinen Grenzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Und du sollst deinem Sohne an selbigem Tage kundtun und sprechen: Es ist um deswillen, was Jehova mir getan hat, als ich aus Ägypten zog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Und es sei dir zu einem Zeichen an deiner Hand und zu einem Denkzeichen zwischen deinen Augen, damit das Gesetz Jehovas in deinem Munde sei; denn mit starker Hand hat Jehova dich aus Ägypten herausgeführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Und du sollst diese Satzung beobachten zu ihrer bestimmten Zeit, von Jahr zu Jahr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Und es soll geschehen, wenn Jehova dich in das Land der Kanaaniter bringt, wie er dir und deinen Vätern geschworen hat, und es dir gibt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'so sollst du Jehova alles darbringen, was die Mutter bricht; und alles zuerst Geworfene vom Vieh, das dir zuteil wird, die Männlichen gehören Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Und jedes Erstgeborene des Esels sollst du mit einem Lamme lösen, und wenn du es nicht lösest, so brich ihm das Genick; und jedes Erstgeborene des Menschen unter deinen Söhnen sollst du lösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Und es soll geschehen, wenn dein Sohn dich künftig fragt und spricht: Was ist das? so sollst du zu ihm sagen: Mit starker Hand hat Jehova uns aus Ägypten herausgeführt, aus dem Hause der Knechtschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Und es geschah, da der Pharao sich hartnäckig weigerte, uns ziehen zu lassen, tötete Jehova alle Erstgeburt im Lande Ägypten, vom Erstgeborenen des Menschen bis zum Erstgeborenen des Viehes; darum opfere ich dem Jehova alles, was die Mutter bricht, die Männlichen, und jeden Erstgeborenen meiner Söhne löse ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Und es sei zu einem Zeichen an deiner Hand und zu Stirnbändern zwischen deinen Augen; denn mit starker Hand hat Jehova uns aus Ägypten herausgeführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Und es geschah, als der Pharao das Volk ziehen ließ, da führte Gott sie nicht den Weg durch das Land der Philister, wiewohl er nahe war; denn Gott sprach: Damit es das Volk nicht gereue, wenn sie den Streit sehen, und sie nicht nach Ägypten zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Und Gott führte das Volk herum, den Weg der Wüste des Schilfmeeres; und die Kinder Israel zogen gerüstet aus dem Lande Ägypten herauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Und Mose nahm die Gebeine Josephs mit sich; denn er hatte die Kinder Israel ausdrücklich schwören lassen und gesagt: Gott wird euch gewißlich heimsuchen; so führet denn meine Gebeine mit euch von hier hinauf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Und sie brachen auf von Sukkoth und lagerten sich in Etham, am Rande der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Und Jehova zog vor ihnen her, des Tages in einer Wolkensäule, um sie auf dem Wege zu leiten, und des Nachts in einer Feuersäule, um ihnen zu leuchten, damit sie Tag und Nacht ziehen könnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Des Tages wich nicht die Wolkensäule noch des Nachts die Feuersäule vor dem Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Sprich zu den Kindern Israel, daß sie umkehren und sich lagern vor Pi-Hachiroth, zwischen Migdol und dem Meere; vor Baal-Zephon, ihm gegenüber, sollt ihr euch am Meere lagern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Und der Pharao wird von den Kindern Israel sagen: Verwirrt irren sie im Lande umher, die Wüste hat sie umschlossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Und ich will das Herz des Pharao verhärten, daß er ihnen nachjage; und ich will mich verherrlichen an dem Pharao und an seiner ganzen Heeresmacht, und die Ägypter sollen erkennen, daß ich Jehova bin. Und sie taten also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Und es wurde dem König von Ägypten berichtet, daß das Volk entflohen wäre; da verwandelte sich das Herz des Pharao und seiner Knechte gegen das Volk, und sie sprachen: Was haben wir da getan, daß wir Israel aus unserem Dienste haben ziehen lassen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Und er spannte seinen Wagen an und nahm sein Volk mit sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Und er nahm sechshundert auserlesene Wagen und alle Wagen Ägyptens, und Wagenkämpfer auf jedem derselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Und Jehova verhärtete das Herz des Pharao, des Königs von Ägypten, und er jagte den Kindern Israel nach; und die Kinder Israel zogen aus mit erhobener Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Und die Ägypter jagten ihnen nach, alle Rosse, Wagen des Pharao und seine Reiter und seine Heeresmacht, und erreichten sie, als sie sich am Meere gelagert hatten, bei Pi-Hachiroth, vor Baal-Zephon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Und als der Pharao nahte, da hoben die Kinder Israel ihre Augen auf, und siehe, die Ägypter zogen hinter ihnen her; und die Kinder Israel fürchteten sich sehr und schrieen zu Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Und sie sprachen zu Mose: Hast du uns darum, weil in Ägypten keine Gräber waren, weggeholt, um in der Wüste zu sterben? Warum hast du uns das getan, daß du uns aus Ägypten herausgeführt hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Ist dies nicht das Wort, das wir in Ägypten zu dir geredet haben, indem wir sprachen: Laß ab von uns, daß wir den Ägyptern dienen? Denn besser wäre es uns, den Ägyptern zu dienen, als in der Wüste zu sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Und Mose sprach zu dem Volke: Fürchtet euch nicht! Stehet und sehet die Rettung Jehovas, die er euch heute schaffen wird; denn die Ägypter, die ihr heute sehet, die werdet ihr hinfort nicht mehr sehen ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Jehova wird für euch streiten, und ihr werdet stille sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Und Jehova sprach zu Mose: Was schreiest du zu mir? Rede zu den Kindern Israel, daß sie aufbrechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Und du, erhebe deinen Stab und strecke deine Hand aus über das Meer und spalte es, daß die Kinder Israel mitten in das Meer hineingehen auf dem Trockenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Und ich, siehe, ich will das Herz der Ägypter verhärten, und sie werden hinter ihnen herkommen; und ich will mich verherrlichen an dem Pharao und an seiner ganzen Heeresmacht, an seinen Wagen und an seinen Reitern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Und die Ägypter sollen erkennen, daß ich Jehova bin, wenn ich mich verherrlicht habe an dem Pharao, an seinen Wagen und an seinen Reitern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Und der Engel Gottes, der vor dem Heere Israels herzog, brach auf und trat hinter sie; und die Wolkensäule brach auf von vorn und stellte sich hinter sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Und sie kam zwischen das Heer der Ägypter und das Heer Israels, und sie wurde dort Wolke und Finsternis, und erleuchtete hier die Nacht; und so nahte jenes diesem nicht die ganze Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Und Mose streckte seine Hand aus über das Meer, und Jehova trieb das Meer durch einen starken Ostwind hinweg, die ganze Nacht, und machte das Meer trocken, und die Wasser wurden gespalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Und die Kinder Israel gingen mitten in das Meer hinein auf dem Trockenen, und die Wasser waren ihnen eine Mauer zur Rechten und zur Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Und die Ägypter jagten ihnen nach und kamen hinter ihnen her, alle Rosse des Pharao, seine Wagen und seine Reiter, mitten ins Meer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Und es geschah in der Morgenwache, da schaute Jehova in der Feuer-und Wolkensäule auf das Heer der Ägypter und verwirrte das Heer der Ägypter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Und er stieß die Räder von seinen Wagen und ließ es fahren mit Beschwerde. Und die Ägypter sprachen: Laßt uns vor Israel fliehen, denn Jehova streitet für sie wider die Ägypter!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Und Jehova sprach zu Mose: Strecke deine Hand aus über das Meer, daß die Wasser über die Ägypter zurückkehren, über ihre Wagen und über ihre Reiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Da streckte Mose seine Hand aus über das Meer, und das Meer kehrte beim Anbruch des Morgens zu seiner Strömung zurück; und die Ägypter flohen ihm entgegen; und Jehova stürzte die Ägypter mitten ins Meer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Und die Wasser kehrten zurück und bedeckten die Wagen und die Reiter der ganzen Heeresmacht des Pharao, die hinter ihnen her ins Meer gekommen waren; es blieb auch nicht einer von ihnen übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Und die Kinder Israel gingen auf dem Trockenen mitten durch das Meer, und die Wasser waren ihnen eine Mauer zur Rechten und zur Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'So rettete Jehova Israel an selbigem Tage aus der Hand der Ägypter, und Israel sah die Ägypter tot am Ufer des Meeres.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Und Israel sah die große Macht, die Jehova an den Ägyptern betätigt hatte; und das Volk fürchtete Jehova, und sie glaubten an Jehova und an Mose, seinen Knecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Damals sangen Mose und die Kinder Israel dieses Lied dem Jehova und sprachen also: Singen will ich Jehova, denn hoch erhaben ist er; das Roß und seinen Reiter hat er ins Meer gestürzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Meine Stärke und mein Gesang ist Jah, denn er ist mir zur Rettung geworden; dieser ist mein Gott, und ich will ihn verherrlichen, meines Vaters Gott, und ich will ihn erheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Jehova ist ein Kriegsmann, Jehova sein Name.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Die Wagen des Pharao und seine Heeresmacht hat er ins Meer gestürzt, und die Auserlesenen seiner Wagenkämpfer sind versunken im Schilfmeer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Die Fluten bedeckten sie, sie sind hinuntergefahren in die Tiefen wie ein Stein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Deine Rechte, Jehova, ist herrlich in Macht; deine Rechte, Jehova, hat zerschmettert den Feind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Und in der Größe deiner Hoheit hast du niedergerissen, die sich wider dich erhoben; du ließest deine Zornglut los: sie hat sie verzehrt wie Stoppeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Und durch den Hauch deiner Nase türmten sich die Wasser, es standen die Strömungen wie ein Damm, es gerannen die Fluten im Herzen des Meeres.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Der Feind sprach: Ich will nachjagen, einholen, Beute teilen; meine Gier soll sich sättigen an ihnen; ich will mein Schwert ziehen, meine Hand soll sie vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Du hauchtest mit deinem Odem, das Meer bedeckte sie; sie sanken unter wie Blei in die gewaltigen Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Wer ist dir gleich unter den Göttern, Jehova! Wer ist dir gleich, herrlich in Heiligkeit, furchtbar an Ruhm, Wunder tuend!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Du strecktest deine Rechte aus, die Erde verschlang sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Du hast durch deine Güte geleitet das Volk, das du erlöst, hast es durch deine Stärke geführt zu deiner heiligen Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Es hörten\'s die Völker, sie bebten; Angst ergriff die Bewohner Philistäas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Da wurden bestürzt die Fürsten Edoms; die Starken Moabs, sie ergriff Beben; es verzagten alle Bewohner Kanaans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Es überfiel sie Schrecken und Furcht; ob der Größe deines Armes verstummten sie gleich einem Stein, bis hindurchzog dein Volk, Jehova, bis hindurchzog das Volk, das du erworben hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Du wirst sie bringen und pflanzen auf den Berg deines Erbteils, die Stätte, die du, Jehova, zu deiner Wohnung gemacht, das Heiligtum, Herr, das deine Hände bereitet haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Jehova wird König sein immer und ewiglich! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Denn die Rosse des Pharao mit seinen Wagen und mit seinen Reitern sind ins Meer gekommen, und Jehova hat die Wasser des Meeres über sie zurückgeführt; und die Kinder Israel gingen auf dem Trockenen mitten durchs Meer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Und Mirjam, die Prophetin, Aarons Schwester, nahm das Tamburin in ihre Hand; und alle Weiber zogen aus, hinter ihr her, mit Tamburinen und in Reigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Und Mirjam antwortete ihnen: Singet Jehova, denn hoch erhaben ist er; das Roß und seinen Reiter hat er ins Meer gestürzt! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Und Mose ließ Israel vom Schilfmeer aufbrechen, und sie zogen aus in die Wüste Sur; und sie wanderten drei Tage in der Wüste und fanden kein Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Und sie kamen nach Mara; aber sie konnten das Wasser von Mara nicht trinken, denn es war bitter: darum gab man ihm den Namen Mara.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Und das Volk murrte wider Mose und sprach: Was sollen wir trinken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Und er schrie zu Jehova, und Jehova wies ihm ein Holz; und er warf es in das Wasser, und das Wasser wurde süß. Dort stellte er ihm Satzung und Recht, und dort versuchte er es;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'und er sprach: Wenn du fleißig auf die Stimme Jehovas, deines Gottes, hören wirst, und tun, was recht ist in seinen Augen, und horchen wirst auf seine Gebote und beobachten alle seine Satzungen, so werde ich keine der Krankheiten auf dich legen, die ich auf Ägypten gelegt habe; denn ich bin Jehova, der dich heilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Und sie kamen nach Elim, und daselbst waren zwölf Wasserquellen und siebzig Palmbäume; und sie lagerten sich daselbst an den Wassern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Und sie brachen auf von Elim, und die ganze Gemeinde der Kinder Israel kam in die Wüste Sin, die zwischen Elim und Sinai ist, am fünfzehnten Tage des zweiten Monats nach ihrem Auszuge aus dem Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Und die ganze Gemeinde der Kinder Israel murrte wieder Mose und wider Aaron in der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Und die Kinder Israel sprachen zu ihnen: Wären wir doch im Lande Ägypten durch die Hand Jehovas gestorben, als wir bei den Fleischtöpfen saßen, als wir Brot aßen bis zur Sättigung! Denn ihr habt uns in diese Wüste herausgeführt, um diese ganze Versammlung Hungers sterben zu lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Da sprach Jehova zu Mose: Siehe, ich werde euch Brot vom Himmel regnen lassen; und das Volk soll hinausgehen und den täglichen Bedarf an seinem Tage sammeln, damit ich es versuche, ob es wandeln wird in meinem Gesetz oder nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Und es soll geschehen, am sechsten Tage, da sollen sie zubereiten, was sie einbringen, und es wird das Doppelte von dem sein, was sie tagtäglich sammeln werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Und Mose und Aaron sprachen zu allen Kindern Israel: Am Abend, da werdet ihr erkennen, daß Jehova euch aus dem Lande Ägypten herausgeführt hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'und am Morgen, da werdet ihr die Herrlichkeit Jehovas sehen, indem er euer Murren wider Jehova gehört hat; denn was sind wir, daß ihr wider uns murret!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Und Mose sprach: Dadurch werdet ihr\'s erkennen, daß Jehova euch am Abend Fleisch zu essen geben wird und am Morgen Brot bis zur Sättigung, indem Jehova euer Murren gehört hat, womit ihr wider ihn murret. Denn was sind wir? Nicht wider uns ist euer Murren, sondern wider Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Und Mose sprach zu Aaron: Sprich zu der ganzen Gemeinde der Kinder Israel: Nahet herzu vor Jehova, denn er hat euer Murren gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Und es geschah, als Aaron zu der ganzen Gemeinde der Kinder Israel redete, da wandten sie sich gegen die Wüste; und siehe, die Herrlichkeit Jehovas erschien in der Wolke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Ich habe das Murren der Kinder Israel gehört; rede zu ihnen und sprich: Zwischen den zwei Abenden werdet ihr Fleisch essen, und am Morgen werdet ihr von Brot satt werden; und ihr werdet erkennen, daß ich Jehova bin, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Und es geschah am Abend, da kamen Wachteln herauf und bedeckten das Lager; und am Morgen war eine Tauschicht rings um das Lager.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Und die Tauschicht stieg auf, und siehe, da lag\'s auf der Fläche der Wüste fein, körnig, fein, wie der Reif auf der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Und die Kinder Israel sahen es und sprachen einer zum anderen: Was ist das? Denn sie wußten nicht, was es war. Und Mose sprach zu ihnen: Dies ist das Brot, das Jehova euch zur Nahrung gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Dies ist das Wort, das Jehova geboten hat: Sammelt davon, ein jeder nach dem Maße seines Essens; einen Ghomer für den Kopf, nach der Zahl eurer Seelen, sollt ihr nehmen, ein jeder für die, welche in seinem Zelte sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Und die Kinder Israel taten also und sammelten, der viel und der wenig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Und sie maßen mit dem Ghomer: da hatte, wer viel gesammelt hatte, nicht übrig, und wer wenig gesammelt hatte, dem mangelte nicht; sie hatten gesammelt, ein jeder nach dem Maße seines Essens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Und Mose sprach zu ihnen: Niemand lasse davon übrig bis an den Morgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Aber sie hörten nicht auf Mose, und etliche ließen davon übrig bis an den Morgen; da wuchsen Würmer darin, und es ward stinkend. Und Mose wurde zornig über sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Und sie sammelten es Morgen für Morgen, ein jeder nach dem Maße seines Essens; und wenn die Sonne heiß wurde, so zerschmolz es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Und es geschah am sechsten Tage, da sammelten sie das Doppelte an Brot, zwei Ghomer für einen; und alle Fürsten der Gemeinde kamen und berichteten es Mose.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Und er sprach zu ihnen: Dies ist es, was Jehova geredet hat: Morgen ist Ruhe, ein heiliger Sabbath dem Jehova; was ihr backen wollt, backet, und was ihr kochen wollt, kochet. Alles aber, was übrigbleibt, leget euch hin zur Aufbewahrung bis an den Morgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Und sie legten es hin bis an den Morgen, so wie Mose geboten hatte; und es stank nicht, und es war kein Wurm darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Da sprach Mose: Esset es heute, denn heute ist Sabbath dem Jehova; ihr werdet es heute auf dem Felde nicht finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Sechs Tage sollt ihr es sammeln; aber am siebten Tage ist Sabbath, an dem wird es nicht sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Und es geschah am siebten Tage, daß etliche von dem Volke hinausgingen, um zu sammeln, und sie fanden nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Und Jehova sprach zu Mose: Bis wann weigert ihr euch, meine Gebote und meine Gesetze zu beobachten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Sehet, weil Jehova euch den Sabbath gegeben hat, darum gibt er euch am sechsten Tage Brot für zwei Tage; bleibet ein jeder an seiner Stelle, niemand gehe am siebten Tage von seinem Orte heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Und das Volk ruhte am siebten Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Und das Haus Israel gab ihm den Namen Man; und es war wie Koriandersamen, weiß, und sein Geschmack wie Kuchen mit Honig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Und Mose sprach: Dies ist das Wort, das Jehova geboten hat: Ein Ghomer voll davon sei zur Aufbewahrung für eure Geschlechter, damit sie das Brot sehen, womit ich euch in der Wüste gespeist habe, als ich euch aus dem Lande Ägypten herausführte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Und Mose sprach zu Aaron: Nimm einen Krug und tue Man darein, einen Ghomer voll, und lege es vor Jehova nieder zur Aufbewahrung für eure Geschlechter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'So wie Jehova Mose geboten hatte, legte Aaron es vor das Zeugnis nieder, zur Aufbewahrung. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Und die Kinder Israel aßen das Man vierzig Jahre, bis sie in ein bewohntes Land kamen; sie aßen das Man, bis sie an die Grenze des Landes Kanaan kamen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Der Ghomer aber ist ein Zehntel vom Epha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Und die ganze Gemeinde der Kinder Israel brach auf aus der Wüste Sin, nach ihren Zügen, nach dem Befehl Jehovas; und sie lagerten sich zu Rephidim; und da war kein Wasser zum Trinken für das Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Und das Volk haderte mit Mose, und sie sprachen: Gebet uns Wasser, daß wir trinken! Und Mose sprach zu ihnen: Was hadert ihr mit mir? Was versuchet ihr Jehova?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Und das Volk dürstete daselbst nach Wasser, und das Volk murrte wider Mose und sprach: Warum doch hast du uns aus Ägypten heraufgeführt, um mich und meine Kinder und mein Vieh vor Durst sterben zu lassen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Da schrie Mose zu Jehova und sprach: Was soll ich mit diesem Volke tun? Noch ein wenig, und sie steinigen mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Und Jehova sprach zu Mose: Gehe hin vor dem Volke, und nimm mit dir von den Ältesten Israels; und deinen Stab, womit du den Strom geschlagen hast, nimm in deine Hand und gehe hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Siehe, ich will daselbst vor dir stehen auf dem Felsen am Horeb; und du sollst auf den Felsen schlagen, und es wird Wasser aus demselben herauskommen, daß das Volk trinke. Und Mose tat also vor den Augen der Ältesten Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Und er gab dem Orte den Namen Massa und Meriba, wegen des Haderns der Kinder Israel und weil sie Jehova versucht hatten, indem sie sagten: Ist Jehova in unserer Mitte oder nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Und es kam Amalek und stritt wider Israel in Rephidim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Und Mose sprach zu Josua: Erwähle uns Männer und ziehe aus, streite wider Amalek; morgen will ich auf dem Gipfel des Hügels stehen, mit dem Stabe Gottes in meiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Und Josua tat, wie Mose ihm gesagt hatte, um wider Amalek zu streiten; und Mose, Aaron und Hur stiegen auf den Gipfel des Hügels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Und es geschah, wenn Mose seine Hand erhob, so hatte Israel die Oberhand, und wenn er seine Hand ruhen ließ, so hatte Amalek die Oberhand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Und die Hände Moses wurden schwer. Da nahmen sie einen Stein und legten denselben unter ihn, und er setzte sich darauf; und Aaron und Hur unterstützten seine Hände, hier einer und dort einer; und so waren seine Hände fest, bis die Sonne unterging.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Und Josua streckte Amalek und sein Volk nieder mit der Schärfe des Schwertes. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Und Jehova sprach zu Mose: Schreibe dieses zum Gedächtnis in ein Buch, und lege in die Ohren Josuas, daß ich das Gedächtnis Amaleks gänzlich unter dem Himmel austilgen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Und Mose baute einen Altar und gab ihm den Namen: Jehova, mein Panier!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Und er sprach: Denn die Hand ist am Throne Jahs: Krieg hat Jehova wider Amalek von Geschlecht zu Geschlecht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Und Jethro, der Priester von Midian, der Schwiegervater Moses, hörte alles, was Gott an Mose und an Israel, seinem Volke, getan, daß Jehova Israel aus Ägypten herausgeführt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Und Jethro, der Schwiegervater Moses, nahm Zippora, das Weib Moses, nach ihrer Heimsendung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'und ihre zwei Söhne, von denen der Name des einen Gersom war, denn er sprach: Ein Fremdling bin ich geworden in fremdem Lande,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'und der Name des anderen Elieser: denn der Gott meines Vaters ist meine Hilfe gewesen und hat mich errettet vom Schwerte des Pharao;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'und Jethro, der Schwiegervater Moses, und seine Söhne und sein Weib kamen zu Mose in die Wüste, wo er gelagert war am Berge Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Und er ließ Mose sagen: Ich, dein Schwiegervater Jethro, bin zu dir gekommen, und dein Weib und ihre beiden Söhne mit ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Da ging Mose hinaus, seinem Schwiegervater entgegen, und beugte sich nieder und küßte ihn; und sie fragten einer den anderen nach ihrem Wohlergehen und gingen ins Zelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Und Mose erzählte seinem Schwiegervater alles, was Jehova an dem Pharao und an den Ägyptern getan hatte um Israels willen, all die Mühsal, die sie auf dem Wege getroffen, und daß Jehova sie errettet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Und Jethro freute sich über all das Gute, das Jehova an Israel getan, daß er es errettet hatte aus der Hand der Ägypter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Und Jethro sprach: Gepriesen sei Jehova, der euch errettet hat aus der Hand der Ägypter und aus der Hand des Pharao, der das Volk errettet hat unter der Hand der Ägypter hinweg!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nun weiß ich, daß Jehova größer ist als alle Götter; denn in der Sache, worin sie in Übermut handelten, war er über ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Und Jethro, der Schwiegervater Moses, nahm ein Brandopfer und Schlachtopfer für Gott; und Aaron und alle Ältesten Israels kamen, um mit dem Schwiegervater Moses zu essen vor dem Angesicht Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Und es geschah am anderen Tage, da setzte sich Mose, um das Volk zu richten; und das Volk stand bei Mose vom Morgen bis zum Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Und der Schwiegervater Moses sah alles, was er mit dem Volke tat, und er sprach: Was ist das, das du mit dem Volke tust? Warum sitzest du allein, und alles Volk steht bei dir vom Morgen bis zum Abend?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Und Mose sprach zu seinem Schwiegervater: Weil das Volk zu mir kommt, um Gott zu befragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Wenn sie eine Sache haben, so kommt es zu mir, und ich richte zwischen dem einen und dem anderen und tue ihnen die Satzungen Gottes und seine Gesetze kund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Da sprach der Schwiegervater Moses zu ihm: Die Sache ist nicht gut, die du tust;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'du wirst ganz erschlaffen, sowohl du, als auch dieses Volk, das bei dir ist; denn die Sache ist zu schwer für dich, du kannst sie nicht allein ausrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Höre nun auf meine Stimme, ich will dir raten, und Gott wird mit dir sein: Sei du für das Volk vor Gott, und bringe du die Sachen zu Gott;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'und erläutere ihnen die Satzungen und die Gesetze, und tue ihnen kund den Weg, auf dem sie wandeln, und das Werk, das sie tun sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Du aber ersieh dir aus dem ganzen Volke tüchtige, gottesfürchtige Männer, Männer der Wahrheit, die den ungerechten Gewinn hassen, und setze sie über sie: Oberste über tausend, Oberste über hundert, Oberste über fünfzig und Oberste über zehn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'daß sie das Volk richten zu aller Zeit; und es geschehe, daß sie jede große Sache vor dich bringen und daß sie jede kleine Sache selbst richten; so erleichtere es dir, und sie mögen mit dir tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Wenn du dieses tust und Gott es dir gebietet, so wirst du bestehen können, und auch dieses ganze Volk wird in Frieden an seinen Ort kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Und Mose hörte auf die Stimme seines Schwiegervaters und tat alles, was er gesagt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Und Mose wählte tüchtige Männer aus ganz Israel und setzte sie zu Häuptern über das Volk: Oberste über tausend, Oberste über hundert, Oberste über fünfzig und Oberste über zehn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Und sie richteten das Volk zu aller Zeit: die schwierige Sache brachten sie vor Mose, und jede kleine Sache richteten sie selbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Und Mose ließ seinen Schwiegervater ziehen, und er zog hin in sein Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Im dritten Monat nach dem Auszuge der Kinder Israel aus dem Lande Ägypten, an diesem selbigen Tage kamen sie in die Wüste Sinai:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Sie brachen auf von Rephidim und kamen in die Wüste Sinai und lagerten sich in der Wüste; und Israel lagerte sich daselbst dem Berge gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Und Mose stieg hinauf zu Gott; und Jehova rief ihm vom Berge zu und sprach: So sollst du zum Hause Jakob sprechen und den Kindern Israel kundtun:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Ihr habt gesehen, was ich an den Ägyptern getan habe, wie ich euch getragen auf Adlers Flügeln und euch zu mir gebracht habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Und nun, wenn ihr fleißig auf meine Stimme hören und meinen Bund halten werdet, so sollt ihr mein Eigentum sein aus allen Völkern; denn die ganze Erde ist mein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'und ihr sollt mir ein Königreich von Priestern und eine heilige Nation sein. Das sind die Worte, die du zu den Kindern Israel reden sollst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Und Mose kam und rief die Ältesten des Volkes und legte ihnen alle diese Worte vor, die Jehova ihm geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Da antwortete das ganze Volk insgesamt und sprach: Alles, was Jehova geredet hat, wollen wir tun! Und Mose brachte die Worte des Volkes zu Jehova zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Und Jehova sprach zu Mose: Siehe, ich werde zu dir kommen im Dunkel des Gewölks, damit das Volk höre, wenn ich mit dir rede, und dir auch glaube ewiglich. Und Mose tat Jehova die Worte des Volkes kund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Und Jehova sprach zu Mose: Gehe zum Volke und heilige sie heute und morgen, und daß sie ihre Kleider waschen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Und sie seien bereit auf den dritten Tag; denn am dritten Tage wird Jehova vor den Augen des ganzen Volkes auf den Berg Sinai herabsteigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Und mache eine Grenze um das Volk ringsum und sprich: Hütet euch, auf den Berg zu steigen und sein Äußerstes anzurühren; alles, was den Berg anrührt, soll gewißlich getötet werden-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'keine Hand soll ihn anrühren, denn es soll gewißlich gesteinigt oder erschossen werden; ob Vieh oder Mensch, es darf nicht leben. Wenn das Lärmhorn anhaltend ertönt, sollen sie gegen den Berg hinansteigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Und Mose stieg vom Berge zu dem Volke hinab; und er heiligte das Volk, und sie wuschen ihre Kleider.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Und er sprach zu dem Volke: Seid bereit auf den dritten Tag; nahet nicht zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Und es geschah am dritten Tage, als es Morgen war, da waren Donner und Blitze und eine schwere Wolke auf dem Berge und ein sehr starker Posaunenschall; und das ganze Volk zitterte, das im Lager war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Und Mose führte das Volk aus dem Lager hinaus, Gott entgegen; und sie stellten sich auf am Fuße des Berges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Und der ganze Berg Sinai rauchte, darum, daß Jehova auf ihn herabstieg im Feuer; und sein Rauch stieg auf, wie der Rauch eines Schmelzofens, und der ganze Berg bebte sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Und der Posaunenschall wurde fort und fort stärker; Mose redete, und Gott antwortete ihm mit einer Stimme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Und Jehova stieg auf den Berg Sinai herab, auf den Gipfel des Berges; und Jehova rief Mose auf den Gipfel des Berges, und Mose stieg hinauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Und Jehova sprach zu Mose: Steige hinab, warne das Volk, daß sie nicht zu Jehova durchbrechen, um zu schauen, und viele von ihnen fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Und auch die Priester, die zu Jehova nahen, sollen sich heiligen, daß Jehova nicht in sie einbreche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Und Mose sprach zu Jehova: Das Volk wird den Berg Sinai nicht ersteigen können; denn du hast uns ja gewarnt und gesagt: Mache eine Grenze um den Berg und heilige ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Und Jehova sprach zu ihm: Gehe, steige hinab, und du sollst heraufkommen, du und Aaron mit dir; aber die Priester und das Volk sollen nicht durchbrechen, um zu Jehova hinaufzusteigen, daß er nicht in sie einbreche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Da stieg Mose zu dem Volke hinab und sagte es ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Und Gott redete alle diese Worte und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Ich bin Jehova, dein Gott, der ich dich herausgeführt habe aus dem Lande Ägypten, aus dem Hause der Knechtschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Du sollst keine anderen Götter haben neben mir. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Du sollst dir kein geschnitztes Bild machen, noch irgend ein Gleichnis dessen, was oben im Himmel und was unten auf der Erde und was in den Wassern unter der Erde ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Du sollst dich nicht vor ihnen niederbeugen und ihnen nicht dienen; denn ich, Jehova, dein Gott, bin ein eifernder Gott, der die Ungerechtigkeit der Väter heimsucht an den Kindern, am dritten und am vierten Gliede derer, die mich hassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'und der Güte erweist, auf Tausende hin, an denen, die mich lieben und meine Gebote beobachten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Du sollst den Namen Jehovas, deines Gottes, nicht zu Eitlem aussprechen; denn Jehova wird den nicht für schuldlos halten, der seinen Namen zu Eitlem ausspricht. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Gedenke des Sabbathtages, ihn zu heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sechs Tage sollst du arbeiten und all dein Werk tun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'aber der siebte Tag ist Sabbath dem Jehova, deinem Gott: du sollst keinerlei Werk tun, du und dein Sohn und deine Tochter, dein Knecht und deine Magd, und dein Vieh, und dein Fremdling, der in deinen Toren ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Denn in sechs Tagen hat Jehova den Himmel und die Erde gemacht, das Meer und alles, was in ihnen ist, und er ruhte am siebten Tage; darum segnete Jehova den Sabbathtag und heiligte ihn. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Ehre deinen Vater und deine Mutter, auf daß deine Tage verlängert werden in dem Lande, das Jehova, dein Gott, dir gibt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Du sollst nicht töten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Du sollst nicht ehebrechen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Du sollst nicht stehlen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Du sollst kein falsches Zeugnis ablegen wider deinen Nächsten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Du sollst nicht begehren deines Nächsten Haus; du sollst nicht begehren deines Nächsten Weib, noch seinen Knecht, noch seine Magd, noch sein Rind, noch seinen Esel, noch alles, was dein Nächster hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Und das ganze Volk gewahrte die Donner und die Flammen und den Posaunenschall und den rauchenden Berg. Und als das Volk es gewahrte, zitterten sie und standen von ferne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'und sie sprachen zu Mose: Rede du mit uns, und wir wollen hören; aber Gott möge nicht mit uns reden, daß wir nicht sterben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Da sprach Mose zu dem Volke: Fürchtet euch nicht; denn um euch zu versuchen, ist Gott gekommen, und damit seine Furcht vor eurem Angesicht sei, daß ihr nicht sündiget.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Und das Volk stand von ferne; und Mose nahte sich zum Dunkel, wo Gott war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Und Jehova sprach zu Mose: Also sollst du zu den Kindern Israel sprechen: Ihr habt gesehen, daß ich vom Himmel her mit euch geredet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Ihr sollt nichts neben mir machen, Götter von Silber und Götter von Gold sollt ihr euch nicht machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Einen Altar von Erde sollst du mir machen und darauf opfern deine Brandopfer und deine Friedensopfer, dein Kleinvieh und deine Rinder; an jedem Orte, wo ich meines Namens werde gedenken lassen, werde ich zu dir kommen und dich segnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Und wenn du mir einen Altar von Steinen machst, so sollst du ihn nicht von behauenen Steinen bauen; denn hast du deinen Meißel darüber geschwungen, so hast du ihn entweiht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Und du sollst nicht auf Stufen zu meinem Altar hinaufsteigen, damit nicht deine Blöße an ihm aufgedeckt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Und dies sind die Rechte, die du ihnen vorlegen sollst:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'So du einen hebräischen Knecht kaufst, soll er sechs Jahre dienen, und im siebten soll er frei ausgehen, umsonst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Wenn er allein gekommen ist, soll er allein ausgehen; wenn er eines Weibes Mann war, soll sein Weib mit ihm ausgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Wenn sein Herr ihm ein Weib gegeben und sie ihm Söhne oder Töchter geboren hat, so sollen das Weib und ihre Kinder ihrem Herrn gehören, und er soll allein ausgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Wenn aber der Knecht etwa sagt: Ich liebe meinen Herrn, mein Weib und meine Kinder, ich will nicht frei ausgehen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'so soll sein Herr ihn vor die Richter bringen und ihn an die Tür oder an den Pfosten stellen, und sein Herr soll ihm das Ohr mit einer Pfrieme durchbohren; und er soll ihm dienen auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Und so jemand seine Tochter zur Magd verkauft, soll sie nicht ausgehen, wie die Knechte ausgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Wenn sie in den Augen ihres Herrn mißfällig ist, die er für sich bestimmt hatte, so lasse er sie loskaufen: er soll nicht Macht haben, sie an ein fremdes Volk zu verkaufen, weil er treulos an ihr gehandelt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Und wenn er sie seinem Sohne bestimmt, so soll er ihr tun nach dem Rechte der Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Wenn er sich eine andere nimmt, so soll er ihre Nahrung, ihre Kleidung und ihre Beiwohnung nicht vermindern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Und wenn er ihr diese drei Dinge nicht tut, so soll sie umsonst ausgehen, ohne Geld.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Wer einen Menschen schlägt, daß er stirbt, soll gewißlich getötet werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'hat er ihm aber nicht nachgestellt, und Gott hat es seiner Hand begegnen lassen, so werde ich dir einen Ort bestimmen, wohin er fliehen soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Und so jemand wider seinen Nächsten vermessen handelt, daß er ihn umbringt mit Hinterlist, von meinem Altar sollst du ihn wegnehmen, daß er sterbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Und wer seinen Vater oder seine Mutter schlägt, soll gewißlich getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Und wer einen Menschen stiehlt und ihn verkauft, oder er wird in seiner Hand gefunden, der soll gewißlich getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Und wer seinem Vater oder seiner Mutter flucht, soll gewißlich getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Und wenn Männer hadern, und einer schlägt den anderen mit einem Steine oder mit der Faust, und er stirbt nicht, sondern wird bettlägerig:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'wenn er aufsteht und draußen an seinem Stabe wandelt, so soll der Schläger schuldlos sein; nur soll er sein Versäumnis erstatten und ihn völlig heilen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Und so jemand seinen Knecht oder seine Magd mit dem Stocke schlägt, daß er unter seiner Hand stirbt, so soll er gewißlich gerächt werden:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'nur wenn er einen Tag oder zwei Tage leben bleibt, soll er nicht gerächt werden, denn er ist sein Geld.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Und wenn Männer sich streiten und stoßen ein schwangeres Weib, daß ihr die Frucht abgeht, und es geschieht kein Schaden, so soll er gewißlich an Geld gestraft werden, jenachdem der Mann des Weibes ihm auferlegen wird, und er soll es geben durch die Richter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Wenn aber Schaden geschieht, so sollst du geben Leben um Leben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Brandmal um Brandmal, Wunde um Wunde, Strieme um Strieme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Und so jemand in das Auge seines Knechtes oder in das Auge seiner Magd schlägt und verdirbt es, so soll er ihn frei entlassen um sein Auge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Und wenn er den Zahn seines Knechtes oder den Zahn seiner Magd ausschlägt, so soll er ihn frei entlassen um seinen Zahn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Und wenn ein Ochse einen Mann oder ein Weib stößt, daß sie sterben, so soll der Ochse gewißlich gesteinigt, und sein Fleisch soll nicht gegessen werden; aber der Besitzer des Ochsen soll schuldlos sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Wenn aber der Ochse vordem stößig war, und sein Besitzer ist gewarnt worden, und er hat ihn nicht verwahrt, und er tötet einen Mann oder ein Weib, so soll der Ochse gesteinigt, und auch sein Besitzer soll getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Wenn ihm eine Sühne auferlegt wird, so soll er das Lösegeld seines Lebens geben nach allem, was ihm auferlegt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Mag er einen Sohn stoßen oder eine Tochter stoßen, so soll ihm nach diesem Rechte getan werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Wenn der Ochse einen Knecht stößt oder eine Magd, so soll sein Besitzer ihrem Herrn dreißig Silbersekel geben, und der Ochse soll gesteinigt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Und wenn jemand eine Grube öffnet, oder wenn jemand eine Grube gräbt und sie nicht zudeckt, und es fällt ein Ochse oder ein Esel hinein,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'so soll es der Besitzer der Grube erstatten: Geld soll er dem Besitzer desselben zahlen, und das tote Tier soll ihm gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Und wenn jemandes Ochse den Ochsen seines Nächsten stößt, daß er stirbt, so sollen sie den lebenden Ochsen verkaufen und den Erlös teilen, und auch den toten sollen sie teilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Ist es aber bekannt gewesen, daß der Ochse vordem stößig war, und sein Besitzer hat ihn nicht verwahrt, so soll er gewißlich Ochsen für Ochsen erstatten, und der tote soll ihm gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Wenn jemand einen Ochsen stiehlt oder ein Stück Kleinvieh, und schlachtet es oder verkauft es, so soll er fünf Ochsen erstatten für den Ochsen und vier Stück Kleinvieh für das Stück. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Wenn der Dieb beim Einbruch betroffen wird, und er wird geschlagen, daß er stirbt, so ist es ihm keine Blutschuld;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'wenn die Sonne über ihm aufgegangen ist, so ist es ihm eine Blutschuld. Er soll gewißlich erstatten; wenn er nichts hat, soll er für seinen Diebstahl verkauft werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Wenn das Gestohlene lebend in seiner Hand gefunden wird, es sei ein Ochse oder ein Esel oder ein Stück Kleinvieh, soll er das Doppelte erstatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'So jemand ein Feld oder einen Weingarten abweiden läßt und er sein Vieh hintreibt, und es weidet auf dem Felde eines anderen, so soll er es vom Besten seines Feldes und vom Besten seines Weingartens erstatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Wenn ein Feuer ausbricht und Dornen erreicht, und es wird ein Garbenhaufen verzehrt, oder das stehende Getreide oder das Feld, so soll der gewißlich erstatten, der den Brand angezündet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'So jemand seinem Nächsten Geld oder Geräte in Verwahrung gibt, und es wird aus dem Hause dieses Mannes gestohlen, wenn der Dieb gefunden wird, so soll er das Doppelte erstatten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'wenn der Dieb nicht gefunden wird, so soll der Besitzer des Hauses vor die Richter treten, ob er nicht seine Hand nach der Habe seines Nächsten ausgestreckt hat. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Bei jedem Falle von Veruntreuung betreffs eines Ochsen, eines Esels, eines Stückes Kleinvieh, eines Kleides, betreffs alles Verlorenen, wovon man sagt: \"das ist es\", soll beider Sache vor die Richter kommen; wen die Richter schuldig sprechen, der soll seinem Nächsten das Doppelte erstatten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'So jemand seinem Nächsten einen Esel oder einen Ochsen oder ein Stück Kleinvieh oder irgend ein Vieh in Verwahrung gibt, und es stirbt oder wird beschädigt oder weggeführt, und niemand sieht es,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'so soll der Eid Jehovas zwischen ihnen beiden sein, ob er nicht seine Hand nach der Habe seines Nächsten ausgestreckt hat; und sein Besitzer soll es annehmen, und jener soll nichts erstatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Und wenn es ihm wirklich gestohlen worden ist, so soll er es seinem Besitzer erstatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Wenn es aber zerrissen worden ist, so soll er es als Zeugnis bringen; er soll das Zerrissene nicht erstatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Und wenn jemand von seinem Nächsten ein Stück Vieh entlehnt, und es wird beschädigt oder stirbt, war sein Besitzer nicht dabei, so soll er es gewißlich erstatten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'wenn sein Besitzer dabei war, soll er es nicht erstatten. Wenn es gemietet war, so ist es für seine Miete gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Und so jemand eine Jungfrau betört, die nicht verlobt ist, und liegt bei ihr, so soll er sie gewißlich durch eine Heiratsgabe sich zum Weibe erkaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Wenn ihr Vater sich durchaus weigert, sie ihm zu geben, so soll er Geld darwägen nach der Heiratsgabe der Jungfrauen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Eine Zauberin sollst du nicht leben lassen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Jeder, der bei einem Vieh liegt, soll gewißlich getötet werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Wer den Göttern opfert außer Jehova allein, soll verbannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Und den Fremdling sollst du nicht bedrängen und ihn nicht bedrücken, denn Fremdlinge seid ihr im Lande Ägypten gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Keine Witwe und Waise sollt ihr bedrücken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Wenn du sie irgend bedrückst, so werde ich, wenn sie irgendwie zu mir schreit, ihr Geschrei gewißlich erhören;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'und mein Zorn wird entbrennen, und ich werde euch mit dem Schwerte töten, und eure Weiber sollen Witwen und eure Kinder Waisen werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Wenn du meinem Volke, dem Armen bei dir, Geld leihst, so sollst du ihm nicht sein wie ein Gläubiger; ihr sollt ihm keinen Zins auferlegen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Wenn du irgend deines Nächsten Mantel zum Pfande nimmst, so sollst du ihm denselben zurückgeben, ehe die Sonne untergeht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'denn es ist seine einzige Decke, sein Kleid für seine Haut; worin soll er liegen? Und es wird geschehen, wenn er zu mir schreit, so werde ich ihn erhören, denn ich bin gnädig. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Die Richter sollst du nicht lästern, und einem Fürsten deines Volkes sollst du nicht fluchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Mit der Fülle deines Getreides und dem Ausfluß deiner Kelter sollst du nicht zögern. Den erstgeborenen deiner Söhne sollst du mir geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Desgleichen sollst du mit deinem Ochsen tun und mit deinem Kleinvieh; sieben Tage soll es bei seiner Mutter sein, am achten Tage sollst du es mir geben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Und heilige Männer sollt ihr mir sein, und Fleisch, das auf dem Felde zerrissen worden ist, sollt ihr nicht essen; ihr sollt es den Hunden vorwerfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Du sollst kein falsches Gerücht aufnehmen; du sollst deine Hand nicht dem Gesetzlosen reichen, um ein ungerechter Zeuge zu sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Du sollst der Menge nicht folgen zum Übeltun; und du sollst bei einem Rechtsstreit nicht antworten, indem du dich der Menge nach neigest, das Recht zu beugen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Und den Armen sollst du in seinem Rechtsstreit nicht begünstigen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Wenn du den Ochsen deines Feindes oder seinen Esel umherirrend antriffst, sollst du ihn demselben jedenfalls zurückbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Wenn du den Esel deines Hassers unter seiner Last liegen siehst, so hüte dich, ihn demselben zu überlassen; du sollst ihn jedenfalls mit ihm losmachen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Du sollst das Recht deines Armen nicht beugen in seinem Rechtsstreit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Von der Sache der Lüge sollst du dich fernhalten; und den Unschuldigen und Gerechten sollst du nicht töten, denn ich werde den Gesetzlosen nicht rechtfertigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Und kein Geschenk sollst du nehmen; denn das Geschenk blendet die Sehenden und verkehrt die Worte der Gerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Und den Fremdling sollst du nicht bedrücken; ihr selbst wisset ja, wie es dem Fremdling zu Mute ist, denn Fremdlinge seid ihr im Lande Ägypten gewesen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Und sechs Jahre sollst du dein Land besäen und seinen Ertrag einsammeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'aber im siebten sollst du es ruhen und liegen lassen, daß die Armen deines Volkes davon essen; und was sie übriglassen, soll das Getier des Feldes fressen. Desgleichen sollst du mit deinem Weinberge tun und mit deinem Olivenbaum. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Sechs Tage sollst du deine Arbeiten tun; aber am siebten Tage sollst du ruhen, damit dein Ochse und dein Esel raste und der Sohn deiner Magd und der Fremdling sich erhole.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Und auf alles, was ich euch gesagt habe, sollt ihr acht haben; und den Namen anderer Götter sollt ihr nicht erwähnen, er soll in deinem Munde nicht gehört werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Dreimal im Jahre sollst du mir ein Fest feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Das Fest der ungesäuerten Brote sollst du beobachten: sieben Tage sollst du Ungesäuertes essen, so wie ich dir geboten habe, zur bestimmten Zeit im Monat Abib, denn in demselben bist du aus Ägypten gezogen; und man soll nicht leer vor meinem Angesicht erscheinen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'und das Fest der Ernte, der Erstlinge deiner Arbeit, dessen, was du auf dem Felde säen wirst; und das Fest der Einsammlung im Ausgang des Jahres, wenn du deine Arbeit vom Felde einsammelst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Dreimal im Jahre sollen alle deine Männlichen vor dem Angesicht des Herrn Jehova erscheinen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Du sollst nicht das Blut meines Schlachtopfers zu Gesäuertem opfern; und nicht soll das Fett meines Festes über Nacht bleiben bis an den Morgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Das erste der Erstlinge deines Landes sollst du in das Haus Jehovas, deines Gottes, bringen. Du sollst ein Böcklein nicht kochen in der Milch seiner Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Siehe, ich sende einen Engel vor dir her, um dich auf dem Wege zu bewahren und dich an den Ort zu bringen, den ich bereitet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Hüte dich vor ihm und höre auf seine Stimme und reize ihn nicht; denn er wird eure Übertretung nicht vergeben, denn mein Name ist in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Doch wenn du fleißig auf seine Stimme hörst und alles tust, was ich sagen werde, so werde ich deine Feinde befeinden und deine Dränger bedrängen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Denn mein Engel wird vor dir hergehen und wird dich bringen zu den Amoritern und den Hethitern und den Perisitern und den Kanaanitern, den Hewitern und den Jebusitern; und ich werde sie vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Du sollst dich vor ihren Göttern nicht niederbeugen und ihnen nicht dienen, und du sollst nicht tun nach ihren Taten; sondern du sollst sie ganz und gar niederreißen und ihre Bildsäulen gänzlich zerbrechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Und ihr sollt Jehova, eurem Gott, dienen: so wird er dein Brot und dein Wasser segnen, und ich werde Krankheit aus deiner Mitte entfernen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Keine Fehlgebärende und Unfruchtbare wird in deinem Lande sein; die Zahl deiner Tage werde ich voll machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Meinen Schrecken werde ich vor dir hersenden und alle Völker verwirren, zu denen du kommst, und dir zukehren den Rücken aller deiner Feinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Und ich werde die Hornisse vor dir hersenden, daß sie vor dir vertreibe die Hewiter, die Kanaaniter und die Hethiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Nicht in einem Jahre werde ich sie vor dir vertreiben, damit nicht das Land eine Wüste werde und das Getier des Feldes sich wider dich mehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Nach und nach werde ich sie vor dir vertreiben, bis du fruchtbar bist und das Land besitzest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Und ich werde deine Grenze setzen vom Schilfmeer bis an das Meer der Philister, und von der Wüste bis an den Strom; denn ich werde die Bewohner des Landes in deine Hand geben, daß du sie vor dir vertreibest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Du sollst mit ihnen und mit ihren Göttern keinen Bund machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Sie sollen nicht in deinem Lande wohnen, damit sie dich nicht wider mich sündigen machen; denn du würdest ihren Göttern dienen, denn es würde dir zum Fallstrick sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Und er sprach zu Mose: Steige zu Jehova herauf, du und Aaron, Nadab und Abihu und siebzig von den Ältesten Israels, und betet an von ferne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Und Mose allein nahe sich zu Jehova; sie aber sollen sich nicht nahen, und das Volk soll nicht mit ihm heraufsteigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Und Mose kam und erzählte dem Volke alle Worte Jehovas und alle Rechte; und das ganze Volk antwortete mit einer Stimme und sprach: Alle Worte, die Jehova geredet hat, wollen wir tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Und Mose schrieb alle Worte Jehovas nieder. Und er machte sich des Morgens früh auf und baute einen Altar unten am Berge und zwölf Denksteine nach den zwölf Stämmen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Und er sandte Jünglinge der Kinder Israel hin, und sie opferten Brandopfer und schlachteten Friedensopfer von Farren dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Und Mose nahm die Hälfte des Blutes und tat es in Schalen, und die Hälfte des Blutes sprengte er an den Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Und er nahm das Buch des Bundes und las es vor den Ohren des Volkes; und sie sprachen: Alles, was Jehova geredet hat, wollen wir tun und gehorchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Und Mose nahm das Blut und sprengte es auf das Volk und sprach: Siehe, das Blut des Bundes, den Jehova mit euch gemacht hat über alle diese Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Und es stiegen hinauf Mose und Aaron, Nadab und Abihu, und siebzig von den Ältesten Israels;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'und sie sahen den Gott Israels; und unter seinen Füßen war es wie ein Werk von Saphirplatten und wie der Himmel selbst an Klarheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Und er streckte seine Hand nicht aus gegen die Edlen der Kinder Israel; und sie schauten Gott und aßen und tranken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Und Jehova sprach zu Mose: Steige zu mir herauf auf den Berg und sei daselbst; und ich werde dir die steinernen Tafeln geben und das Gesetz und das Gebot, das ich geschrieben habe, um sie zu belehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Und Mose machte sich auf mit Josua, seinem Diener, und Mose stieg auf den Berg Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Und er sprach zu den Ältesten: Wartet hier auf uns, bis wir zu euch zurückkehren; und siehe, Aaron und Hur sind bei euch: wer irgend eine Sache hat, trete vor sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Und Mose stieg auf den Berg, und die Wolke bedeckte den Berg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Und die Herrlichkeit Jehovas ruhte auf dem Berge Sinai, und die Wolke bedeckte ihn sechs Tage; und am siebten Tage rief er Mose aus der Mitte der Wolke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Und das Ansehen der Herrlichkeit Jehovas war wie ein verzehrendes Feuer auf dem Gipfel des Berges vor den Augen der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Und Mose ging mitten in die Wolke hinein und stieg auf den Berg; und Mose war auf dem Berge vierzig Tage und vierzig Nächte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Rede zu den Kindern Israel, daß sie mir ein Hebopfer bringen; von einem jeden, der willigen Herzens ist, sollt ihr mein Hebopfer nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Und dies ist das Hebopfer, das ihr von ihnen nehmen sollt: Gold und Silber und Erz,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'und blauer und roter Purpur und Karmesin und Byssus und Ziegenhaar,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'und rotgefärbte Widderfelle und Dachsfelle und Akazienholz;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Öl zum Licht, Gewürze zum Salböl und zum wohlriechenden Räucherwerk;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Onyxsteine und Steine zum Einsetzen für das Ephod und für das Brustschild.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Und sie sollen mir ein Heiligtum machen, daß ich in ihrer Mitte wohne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Nach allem, was ich dir zeige, das Muster der Wohnung und das Muster aller ihrer Geräte, also sollt ihr es machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Und sie sollen eine Lade von Akazienholz machen: zwei und eine halbe Elle ihre Länge, und eine und eine halbe Elle ihre Breite, und eine und eine halbe Elle ihre Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Und du sollst sie überziehen mit reinem Golde: inwendig und auswendig sollst du sie überziehen; und mache einen goldenen Kranz daran ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Und gieße für dieselbe vier Ringe von Gold und setze sie an ihre vier Ecken, und zwar zwei Ringe an ihrer einen Seite und zwei Ringe an ihrer anderen Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Und mache Stangen von Akazienholz und überziehe sie mit Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Und bringe die Stangen in die Ringe an den Seiten der Lade, um die Lade mit denselben zu tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Die Stangen sollen in den Ringen der Lade sein, sie sollen nicht daraus entfernt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Und lege in die Lade das Zeugnis, das ich dir geben werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Und mache einen Deckel von reinem Golde: zwei und eine halbe Elle seine Länge, und eine und eine halbe Elle seine Breite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Und mache zwei Cherubim von Gold; in getriebener Arbeit sollst du sie machen an beiden Enden des Deckels;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'und mache einen Cherub an dem Ende der einen Seite und einen Cherub an dem Ende der anderen Seite; aus dem Deckel sollt ihr die Cherubim machen an seinen beiden Enden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Und die Cherubim sollen die Flügel nach oben ausbreiten, den Deckel mit ihren Flügeln überdeckend, und ihre Angesichter einander gegenüber; die Angesichter der Cherubim sollen gegen den Deckel gerichtet sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Und lege den Deckel oben über die Lade; und in die Lade sollst du das Zeugnis legen, das ich dir geben werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Und daselbst werde ich mit dir zusammenkommen und von dem Deckel herab, zwischen den zwei Cherubim hervor, die auf der Lade des Zeugnisses sind, alles zu dir reden, was ich dir an die Kinder Israel gebieten werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Und du sollst einen Tisch von Akazienholz machen: zwei Ellen seine Länge, und eine Elle seine Breite, und eine und eine halbe Elle seine Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Und überziehe ihn mit reinem Golde und mache ihm einen Kranz von Gold ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Und mache ihm eine Leiste, eine Hand breit, ringsum, und mache einen Kranz von Gold an seine Leiste ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Und mache ihm vier Ringe von Gold und setze die Ringe an die vier Ecken, die an seinen vier Füßen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Dicht bei der Leiste sollen die Ringe sein, zu Behältern für die Stangen, um den Tisch zu tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Und mache die Stangen von Akazienholz und überziehe sie mit Gold, und der Tisch soll daran getragen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Und mache seine Schüsseln und seine Schalen und seine Kannen und seine Spendschalen, mit welchen das Trankopfer ausgegossen wird; von reinem Golde sollst du sie machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Und auf den Tisch sollst du Schaubrote legen vor meinem Angesicht beständig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Und du sollst einen Leuchter von reinem Golde machen; in getriebener Arbeit soll der Leuchter gemacht werden, sein Fuß und sein Schaft; seine Kelche, seine Knäufe und seine Blumen sollen aus ihm sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Und sechs Arme sollen von seinen Seiten ausgehen: Drei Arme des Leuchters aus seiner einen Seite und drei Arme des Leuchters aus seiner anderen Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Drei Kelche, mandelblütenförmig, an dem einen Arme: Knauf und Blume; und drei Kelche, mandelblütenförmig, an dem anderen Arme: Knauf und Blume; also für die sechs Arme, die von dem Leuchter ausgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Und an dem Leuchter vier Kelche, mandelblütenförmig: seine Knäufe und seine Blumen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'und zwar ein Knauf unter zwei Armen aus ihm, und wieder ein Knauf unter zwei Armen aus ihm, und wieder ein Knauf unter zwei Armen aus ihm, für die sechs Arme, die von dem Leuchter ausgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Ihre Knäufe und ihre Arme sollen aus ihm sein; der ganze Leuchter eine getriebene Arbeit, von reinem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Und du sollst seine sieben Lampen machen; und man soll seine Lampen anzünden, so daß sie gerade vor ihm hin scheinen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'und seine Lichtschneuzen und seine Löschnäpfe von reinem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Aus einem Talent reinen Goldes soll man ihn machen mit allen diesen Geräten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Und sieh zu, daß du sie nach ihrem Muster machest, welches dir auf dem Berge gezeigt worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Und die Wohnung sollst du aus zehn Teppichen machen; von gezwirntem Byssus und blauem und rotem Purpur und Karmesin, mit Cherubim in Kunstweberarbeit sollst du sie machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Die Länge eines Teppichs achtundzwanzig Ellen, und vier Ellen die Breite eines Teppichs: ein Maß für alle Teppiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Fünf Teppiche sollen zusammengefügt werden, einer an den anderen, und wieder fünf Teppiche zusammengefügt, einer an den anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Und mache Schleifen von blauem Purpur an den Saum des einen Teppichs am Ende, bei der Zusammenfügung; und also sollst du es machen an dem Saume des äußersten Teppichs bei der anderen Zusammenfügung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Fünfzig Schleifen sollst du an den einen Teppich machen, und fünfzig Schleifen sollst du an das Ende des Teppichs machen, der bei der anderen Zusammenfügung ist, die Schleifen eine der anderen gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Und mache fünfzig Klammern von Gold, und füge die Teppiche mit den Klammern zusammen, einen an den anderen, so daß die Wohnung ein Ganzes sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Und du sollst Teppiche von Ziegenhaar machen zum Zelte über die Wohnung; elf solcher Teppiche sollst du machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Die Länge eines Teppichs dreißig Ellen, und vier Ellen die Breite eines Teppichs: ein Maß für die elf Teppiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Und füge fünf Teppiche besonders zusammen und sechs Teppiche besonders, und den sechsten Teppich an der Vorderseite des Zeltes lege doppelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Und mache fünfzig Schleifen an den Saum des einen Teppichs, des äußersten, bei der Zusammenfügung, und fünfzig Schleifen an den Saum des Teppichs der anderen Zusammenfügung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Und mache fünfzig Klammern von Erz, und bringe die Klammern in die Schleifen und füge das Zelt zusammen, so daß es ein Ganzes sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Und das Überhangende, das übrig ist an den Teppichen des Zeltes, der halbe Teppich, der übrig ist, soll über die Hinterseite der Wohnung hangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Und die Elle diesseits und die Elle jenseits, von dem, was übrig ist an der Länge der Teppiche des Zeltes, soll über die Seiten der Wohnung hangen, diesseits und jenseits, sie zu bedecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Und mache für das Zelt eine Decke von rotgefärbten Widderfellen und eine Decke von Dachsfellen oben darüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Und die Bretter zu der Wohnung sollst du von Akazienholz machen, aufrechtstehend;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'zehn Ellen die Länge eines Brettes, und eine und eine halbe Elle die Breite eines Brettes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'zwei Zapfen an einem Brette, einer dem anderen gegenüber eingefügt: also sollst du es machen an allen Brettern der Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Und mache die Bretter zu der Wohnung: zwanzig Bretter an der Seite gegen Mittag, südwärts;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'und vierzig Füße von Silber sollst du unter die zwanzig Bretter machen: zwei Füße unter ein Brett für seine zwei Zapfen, und wieder zwei Füße unter ein Brett für seine zwei Zapfen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'und an der anderen Seite der Wohnung, an der Nordseite, zwanzig Bretter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'und ihre vierzig Füße von Silber: zwei Füße unter ein Brett, und wieder zwei Füße unter ein Brett;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'und an der Hinterseite der Wohnung gegen Westen sollst du sechs Bretter machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'und zwei Bretter sollst du für die Winkel der Wohnung an der Hinterseite machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'und sie sollen zweifach sein von unten auf, und sollen an ihrem Oberteil völlig aneinander sein in einem Ringe; also soll es mit ihnen beiden sein, an den beiden Winkeln sollen sie sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Und so sollen es acht Bretter sein, und ihre Füße von Silber, sechzehn Füße: zwei Füße unter einem Brette, und wieder zwei Füße unter einem Brette.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Und du sollst Riegel von Akazienholz machen: fünf zu den Brettern der einen Seite der Wohnung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'und fünf Riegel zu den Brettern der anderen Seite der Wohnung, und fünf Riegel zu den Brettern der Seite der Wohnung an der Hinterseite gegen Westen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'und den mittleren Riegel in der Mitte der Bretter durchlaufend von einem Ende zum anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Und die Bretter sollst du mit Gold überziehen; und ihre Ringe, die Behälter für die Riegel, sollst du von Gold machen und die Riegel mit Gold überziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Und so richte die Wohnung auf, nach ihrer Vorschrift, wie sie dir auf dem Berge gezeigt worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Und du sollst einen Vorhang machen von blauem und rotem Purpur und Karmesin und gezwirntem Byssus; in Kunstweberarbeit soll man ihn machen, mit Cherubim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Und hänge ihn auf an vier Säulen von Akazienholz, überzogen mit Gold, ihre Haken von Gold, auf vier Füßen von Silber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'und hänge den Vorhang auf unter die Klammern; und bringe dorthin, innerhalb des Vorhanges, die Lade des Zeugnisses. Und der Vorhang soll euch eine Scheidung machen zwischen dem Heiligen und dem Allerheiligsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Und lege den Deckel auf die Lade des Zeugnisses im Allerheiligsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Und stelle den Tisch außerhalb des Vorhangs und den Leuchter dem Tische gegenüber an die Seite der Wohnung gegen Süden; und den Tisch sollst du an die Nordseite setzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Und mache für den Eingang des Zeltes einen Vorhang von blauem und rotem Purpur und Karmesin und gezwirntem Byssus, in Buntwirkerarbeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Und mache zu dem Vorhang fünf Säulen von Akazienholz und überziehe sie mit Gold, ihre Haken von Gold, und gieße für sie fünf Füße von Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Und du sollst den Altar von Akazienholz machen: fünf Ellen die Länge, und fünf Ellen die Breite, quadratförmig soll der Altar sein und drei Ellen seine Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Und mache seine Hörner an seine vier Ecken; aus ihm sollen seine Hörner sein; und überziehe ihn mit Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Und mache seine Töpfe, um ihn von der Fettasche zu reinigen, und seine Schaufeln und seine Sprengschalen und seine Gabeln und seine Kohlenpfannen; für alle seine Geräte sollst du Erz verwenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Und mache ihm ein Gitter von Netzwerk aus Erz, und mache an das Netz vier eherne Ringe an seine vier Ecken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'und setze es unter die Einfassung des Altars, unterwärts, daß das Netz bis zur Hälfte des Altars reiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Und mache Stangen für den Altar, Stangen von Akazienholz, und überziehe sie mit Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Und seine Stangen sollen in die Ringe gebracht werden, daß die Stangen an beiden Seiten des Altars seien, wenn man ihn trägt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Hohl, von Brettern sollst du ihn machen; so wie dir auf dem Berge gezeigt worden ist, also soll man ihn machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Und du sollst den Vorhof der Wohnung machen: an der Mittagseite, südwärts, Umhänge für den Vorhof von gezwirntem Byssus, hundert Ellen die Länge auf der einen Seite;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'und seine zwanzig Säulen und ihre zwanzig Füße von Erz, die Haken der Säulen und ihre Bindestäbe von Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Und ebenso an der Nordseite in die Länge: Umhänge, hundert Ellen lang; und seine zwanzig Säulen und ihre zwanzig Füße von Erz, die Haken der Säulen und ihre Bindestäbe von Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Und die Breite des Vorhofs an der Westseite: fünfzig Ellen Umhänge, ihre zehn Säulen und ihre zehn Füße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Und die Breite des Vorhofs an der Ostseite, gegen Aufgang, fünfzig Ellen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'fünfzehn Ellen Umhänge auf der einen Seite, ihre drei Säulen und ihre drei Füße;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'und auf der anderen Seite fünfzehn Ellen Umhänge, ihre drei Säulen und ihre drei Füße;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'und für das Tor des Vorhofs einen Vorhang von zwanzig Ellen von blauem und rotem Purpur und Karmesin und gezwirntem Byssus, in Buntwirkerarbeit, ihre vier Säulen und ihre vier Füße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Alle Säulen des Vorhofs ringsum sollen mit Bindestäben von Silber versehen sein, ihre Haken von Silber und ihre Füße von Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Die Länge des Vorhofs hundert Ellen, und die Breite fünfzig gegen fünfzig, und die Höhe fünf Ellen, von gezwirntem Byssus; und ihre Füße von Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Alle Geräte der Wohnung zu ihrem ganzen Dienst und alle ihre Pflöcke und alle Pflöcke des Vorhofs sollen von Erz sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Und du, du sollst den Kindern Israel gebieten, daß sie dir reines, zerstoßenes Olivenöl bringen zum Licht, um die Lampen anzuzünden beständig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Im Zelte der Zusammenkunft, außerhalb des Vorhangs, der vor dem Zeugnis ist, sollen Aaron und seine Söhne sie zurichten vom Abend bis zum Morgen, vor Jehova. Eine ewige Satzung bei ihren Geschlechtern von seiten der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Und du, du sollst zu dir nahen lassen deinen Bruder Aaron und seine Söhne mit ihm, aus der Mitte der Kinder Israel, um mir den Priesterdienst auszuüben: Aaron, Nadab und Abihu, Eleasar und Ithamar, die Söhne Aarons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Und du sollst heilige Kleider für deinen Bruder Aaron machen zur Herrlichkeit und zum Schmuck.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Und du sollst zu allen reden, die weisen Herzens sind, die ich mit dem Geiste der Weisheit erfüllt habe, daß sie die Kleider Aarons machen, ihn zu heiligen, um mir den Priesterdienst auszuüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Und dies sind die Kleider, die sie machen sollen: ein Brustschild und ein Ephod und ein Oberkleid, und einen Leibrock von zellenförmigem Gewebe, einen Kopfbund und einen Gürtel; und sie sollen heilige Kleider machen für deinen Bruder Aaron und für seine Söhne, um mir den Priesterdienst auszuüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Und sie sollen das Gold und den blauen und den roten Purpur und den Karmesin und den Byssus nehmen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'und sollen das Ephod machen von Gold, blauem und rotem Purpur, Karmesin und gezwirntem Byssus, in Kunstweberarbeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Es soll zwei zusammenfügende Schulterstücke haben an seinen beiden Enden, und so werde es zusammengefügt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Und der gewirkte Gürtel, mit dem es angebunden wird, der darüber ist, soll von gleicher Arbeit mit ihm sein, von gleichem Stoffe: von Gold, blauem und rotem Purpur und Karmesin und gezwirntem Byssus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Und du sollst zwei Onyxsteine nehmen und die Namen der Söhne Israels darauf stechen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'sechs ihrer Namen auf den einen Stein und die sechs übrigen Namen auf den anderen Stein, nach ihrer Geburtsfolge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'In Steinschneiderarbeit, in Siegelstecherei sollst du die beiden Steine stechen nach den Namen der Söhne Israels; mit Einfassungen von Gold umgeben sollst du sie machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Und setze die beiden Steine auf die Schulterstücke des Ephods, als Steine des Gedächtnisses für die Kinder Israel; und Aaron soll ihre Namen auf seinen beiden Schultern tragen vor Jehova zum Gedächtnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Und mache Einfassungen von Gold;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'und zwei Ketten von reinem Golde: schnurähnlich sollst du sie machen, in Flechtwerk, und die geflochtenen Ketten an die Einfassungen befestigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Und mache das Brustschild des Gerichts in Kunstweberarbeit; gleich der Arbeit des Ephods sollst du es machen: von Gold, blauem und rotem Purpur und Karmesin und gezwirntem Byssus sollst du es machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Quadratförmig soll es sein, gedoppelt, eine Spanne seine Länge und eine Spanne seine Breite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Und besetze es mit eingesetzten Steinen, vier Reihen von Steinen; eine Reihe: Sardis, Topas und Smaragd, die erste Reihe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'und die zweite Reihe: Karfunkel, Saphir und Diamant;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'und die dritte Reihe: Opal, Achat und Amethyst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'und die vierte Reihe: Chrysolith und Onyx und Jaspis; mit Gold sollen sie eingefaßt sein in ihren Einsetzungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Und der Steine sollen nach den Namen der Söhne Israels zwölf sein, nach ihren Namen; in Siegelstecherei sollen sie sein, ein jeder nach seinem Namen, für die zwölf Stämme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Und mache an das Brustschild schnurähnliche Ketten in Flechtwerk, von reinem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Und mache an das Brustschild zwei Ringe von Gold, und befestige die zwei Ringe an die beiden Enden des Brustschildes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Und befestige die zwei geflochtenen Schnüre von Gold an die beiden Ringe an den Enden des Brustschildes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'und die beiden anderen Enden der zwei geflochtenen Schnüre sollst du an die beiden Einfassungen befestigen und sie an die Schulterstücke des Ephods befestigen, an seine Vorderseite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Und mache zwei Ringe von Gold und befestige sie an die beiden Enden des Brustschildes, an seinen Saum, der gegen das Ephod hin ist, einwärts;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'und mache zwei Ringe von Gold und befestige sie an die beiden Schulterstücke des Ephods, unten an seine Vorderseite, gerade bei seiner Zusammenfügung, oberhalb des gewirkten Gürtels des Ephods.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Und man soll das Brustschild mit seinen Ringen an die Ringe des Ephods binden mit einer Schnur von blauem Purpur, daß es über dem gewirkten Gürtel des Ephods sei und das Brustschild sich nicht von dem Ephod verrücke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Und Aaron soll die Namen der Söhne Israels an dem Brustschilde des Gerichts auf seinem Herzen tragen, wenn er ins Heiligtum hineingeht, zum Gedächtnis vor Jehova beständig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Und lege in das Brustschild des Gerichts die Urim und die Thummim, daß sie auf dem Herzen Aarons seien, wenn er vor Jehova hineingeht; und Aaron soll das Gericht der Kinder Israel auf seinem Herzen tragen vor Jehova beständig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Und mache das Oberkleid des Ephods ganz von blauem Purpur.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Und seine Kopföffnung soll in seiner Mitte sein; eine Borte soll es an seiner Öffnung haben ringsum, in Weberarbeit; wie die Öffnung eines Panzers soll daran sein, daß es nicht einreiße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Und an seinen Saum mache Granatäpfel von blauem und rotem Purpur und Karmesin, an seinen Saum ringsum, und Schellen von Gold zwischen ihnen ringsum:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'eine Schelle von Gold und einen Granatapfel, eine Schelle von Gold und einen Granatapfel an den Saum des Oberkleides ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Und Aaron soll es anhaben, um den Dienst zu verrichten, daß sein Klang gehört werde, wenn er ins Heiligtum hineingeht vor Jehova und wenn er hinausgeht, daß er nicht sterbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Und mache ein Blech von reinem Golde und stich darauf mit Siegelstecherei: Heiligkeit dem Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Und tue es an eine Schnur von blauem Purpur; und es soll an dem Kopfbunde sein, an der Vorderseite des Kopfbundes soll es sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Und es soll auf der Stirn Aarons sein, und Aaron soll die Ungerechtigkeit der heiligen Dinge tragen, welche die Kinder Israel heiligen werden, bei allen Gaben ihrer heiligen Dinge; und es soll beständig an seiner Stirn sein, zum Wohlgefallen für sie vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Und mache den Leibrock von zellenförmigen Gewebe von Byssus, und mache einen Kopfbund von Byssus; und einen Gürtel sollst du machen in Buntwirkerarbeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Und den Söhnen Aarons sollst du Leibröcke machen und sollst ihnen Gürtel machen, und hohe Mützen sollst du ihnen machen zur Herrlichkeit und zum Schmuck.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Und du sollst deinen Bruder Aaron damit bekleiden und seine Söhne mit ihm; und du sollst sie salben und sie weihen und sie heiligen, daß sie mir den Priesterdienst ausüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Und mache ihnen Beinkleider von Linnen, um das Fleisch der Blöße zu bedecken; von den Hüften bis an die Schenkel sollen sie reichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Und Aaron und seine Söhne sollen sie anhaben, wenn sie in das Zelt der Zusammenkunft hineingehen, oder wenn sie dem Altar nahen, um den Dienst im Heiligtum zu verrichten, daß sie nicht eine Ungerechtigkeit tragen und sterben: eine ewige Satzung für ihn und für seinen Samen nach ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Und dies ist es, was du ihnen tun sollst, sie zu heiligen, um mir den Priesterdienst auszuüben: Nimm einen jungen Farren und zwei Widder, ohne Fehl,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'und ungesäuertes Brot, und ungesäuerte Kuchen, gemengt mit Öl, und ungesäuerte Fladen, gesalbt mit Öl: von Feinmehl des Weizens sollst du sie machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Und lege sie in einen Korb und bringe sie in dem Korbe dar, und den Farren und die zwei Widder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Und Aaron und seine Söhne sollst du herzunahen lassen an den Eingang des Zeltes der Zusammenkunft und sie mit Wasser waschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Und du sollst die Kleider nehmen und Aaron bekleiden mit dem Leibrock und dem Oberkleide des Ephods und dem Ephod und dem Brustschilde und es ihm anbinden mit dem gewirkten Gürtel des Ephods.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Und setze den Kopfbund auf sein Haupt und lege das heilige Diadem an den Kopfbund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Und nimm das Salböl und gieße es auf sein Haupt und salbe ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Und seine Söhne sollst du herzunahen lassen und sie mit den Leibröcken bekleiden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'und umgürte sie mit dem Gürtel, Aaron und seine Söhne, und binde ihnen die hohen Mützen um; und das Priestertum sei ihnen zu einer ewigen Satzung. Und du sollst Aaron und seine Söhne weihen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Und du sollst den Farren herzubringen vor das Zelt der Zusammenkunft, und Aaron und seine Söhne sollen ihre Hände auf den Kopf des Farren legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Und schlachte den Farren vor Jehova, an dem Eingang des Zeltes der Zusammenkunft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'und nimm von dem Blute des Farren und tue es mit deinem Finger an die Hörner des Altars, und alles Blut sollst du an den Fuß des Altars gießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Und nimm alles Fett, welches das Eingeweide bedeckt, und das Netz über der Leber und die beiden Nieren und das Fett, das an ihnen ist, und räuchere es auf dem Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Und das Fleisch des Farren und seine Haut und seinen Mist sollst du mit Feuer verbrennen außerhalb des Lagers: es ist ein Sündopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Und du sollst den einen Widder nehmen, und Aaron und seine Söhne sollen ihre Hände auf den Kopf des Widders legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Und du sollst den Widder schlachten und sein Blut nehmen und an den Altar sprengen ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Und den Widder sollst du in seine Stücke zerlegen und sein Eingeweide und seine Schenkel waschen und sie auf seine Stücke und auf seinen Kopf legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Und den ganzen Widder sollst du auf dem Altar räuchern: es ist ein Brandopfer dem Jehova, ein lieblicher Geruch; es ist ein Feueropfer dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Und du sollst den zweiten Widder nehmen, und Aaron und seine Söhne sollen ihre Hände auf den Kopf des Widders legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Und du sollst den Widder schlachten und von seinem Blute nehmen und es auf das rechte Ohrläppchen Aarons tun und auf das rechte Ohrläppchen seiner Söhne und auf den Daumen ihrer rechten Hand und auf die große Zehe ihres rechten Fußes; und du sollst das Blut an den Altar sprengen ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Und nimm von dem Blute, das auf dem Altar ist, und von dem Salböl, und sprenge es auf Aaron und auf seine Kleider und auf seine Söhne und auf die Kleider seiner Söhne mit ihm; und er wird heilig sein und seine Kleider, und seine Söhne und die Kleider seiner Söhne mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Und nimm von dem Widder das Fett und den Fettschwanz und das Fett, welches das Eingeweide bedeckt, und das Netz der Leber und die beiden Nieren und das Fett, das an ihnen ist, und den rechten Schenkel, denn es ist ein Widder der Einweihung-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'und einen Laib Brot und einen Kuchen geölten Brotes und einen Fladen aus dem Korbe des Ungesäuerten, der vor Jehova ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'und lege das alles auf die Hände Aarons und auf die Hände seiner Söhne, und webe es als Webopfer vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Und nimm es von ihren Händen und räuchere es auf dem Altar, auf dem Brandopfer, zum lieblichen Geruch vor Jehova: es ist ein Feueropfer dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Und nimm die Brust von dem Einweihungswidder, der für Aaron ist, und webe sie als Webopfer vor Jehova; und sie soll dein Anteil sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Und heilige die Brust des Webopfers und den Schenkel des Hebopfers, die gewoben und der gehoben worden ist von dem Einweihungswidder, von dem, der für Aaron, und von dem, der für seine Söhne ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'und es soll Aaron und seinen Söhnen gehören als eine ewige Gebühr von seiten der Kinder Israel, denn es ist ein Hebopfer; und es soll ein Hebopfer sein von seiten der Kinder Israel, von ihren Friedensopfern: ihr Hebopfer dem Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Und die heiligen Kleider Aarons sollen für seine Söhne sein nach ihm, um sie darin zu salben und sie darin zu weihen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Sieben Tage soll sie anziehen, wer von seinen Söhnen Priester wird an seiner Statt, welcher in das Zelt der Zusammenkunft hineingehen wird, um im Heiligtum zu dienen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Und den Einweihungswidder sollst du nehmen und sein Fleisch an heiligem Orte kochen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Und Aaron und seine Söhne sollen das Fleisch des Widders und das Brot, das in dem Korbe ist, essen an dem Eingang des Zeltes der Zusammenkunft:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'sie sollen die Dinge essen, durch welche Sühnung geschehen ist, um sie zu weihen, um sie zu heiligen; ein Fremder aber soll nicht davon essen, denn sie sind heilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Und wenn von dem Fleische der Einweihung und von dem Brote etwas übrigbleibt bis an den Morgen, so sollst du das Übriggebliebene mit Feuer verbrennen; es soll nicht gegessen werden, denn es ist heilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Und du sollst Aaron und seinen Söhnen also tun, nach allem, was ich dir geboten habe; sieben Tage sollst du sie einweihen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Und einen Farren als Sündopfer sollst du täglich zur Sühnung opfern und den Altar entsündigen, indem du Sühnung für ihn tust; und du sollst ihn salben, um ihn zu heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sieben Tage sollst du Sühnung tun für den Altar und ihn heiligen; und der Altar soll hochheilig sein: alles, was den Altar anrührt, wird heilig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Und dies ist es, was du auf dem Altar opfern sollst: zwei einjährige Lämmer des Tages beständig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Das eine Lamm sollst du am Morgen opfern, und das zweite Lamm sollst du opfern zwischen den zwei Abenden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'und ein Zehntel Feinmehl, gemengt mit einem viertel Hin zerstoßenen Öles, und ein Trankopfer, ein viertel Hin Wein, zu dem einen Lamme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Und das zweite Lamm sollst du opfern zwischen den zwei Abenden; wie das Morgenspeisopfer und wie dessen Trankopfer, so sollst du zu diesem opfern, zum lieblichen Geruch, ein Feueropfer dem Jehova:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'ein beständiges Brandopfer bei euren Geschlechtern an dem Eingang des Zeltes der Zusammenkunft vor Jehova, wo ich mit euch zusammenkommen werde, um daselbst mit dir zu reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Und ich werde daselbst mit den Kindern Israel zusammenkommen, und es wird geheiligt werden durch meine Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Und ich werde das Zelt der Zusammenkunft und den Altar heiligen; und Aaron und seine Söhne werde ich heiligen, daß sie mir den Priesterdienst ausüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Und ich werde in der Mitte der Kinder Israel wohnen und werde ihr Gott sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Und sie werden wissen, daß ich Jehova bin, ihr Gott, der ich sie aus dem Lande Ägypten herausgeführt habe, um in ihrer Mitte zu wohnen; ich bin Jehova, ihr Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Und du sollst einen Altar machen zum Räuchern des Räucherwerks, von Akazienholz sollst du ihn machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'eine Elle seine Länge, und eine Elle seine Breite, quadratförmig soll er sein und zwei Ellen seine Höhe; aus ihm sollen seine Hörner sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Und überziehe ihn mit reinem Golde, seine Platte und seine Wände ringsum und seine Hörner; und mache ihm einen Kranz von Gold ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Und mache ihm zwei Ringe von Gold unter seinen Kranz: an seine beiden Seiten sollst du sie machen, an seine beiden Wände; und sie sollen zu Behältern sein für die Stangen, um ihn mit denselben zu tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Und mache die Stangen von Akazienholz und überziehe sie mit Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Und stelle ihn dem Vorhang gegenüber, der vor der Lade des Zeugnisses ist, dem Deckel gegenüber, der über dem Zeugnis ist, woselbst ich mit dir zusammenkommen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Und Aaron soll wohlriechendes Räucherwerk auf ihm räuchern; Morgen für Morgen, wenn er die Lampen zurichtet, soll er es räuchern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'und wenn Aaron die Lampen anzündet zwischen den zwei Abenden, soll er es räuchern: ein beständiges Räucherwerk vor Jehova bei euren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Ihr sollt kein fremdes Räucherwerk auf ihm opfern, noch Brandopfer, noch Speisopfer; und kein Trankopfer sollt ihr auf ihn gießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Und Aaron soll einmal im Jahre für dessen Hörner Sühnung tun mit dem Blute des Sündopfers der Versöhnung; einmal im Jahre soll er Sühnung für ihn tun bei euren Geschlechtern: hochheilig ist er dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Wenn du die Summe der Kinder Israel aufnehmen wirst nach ihren Gemusterten, so sollen sie bei ihrer Musterung ein jeder eine Sühne seiner Seele dem Jehova geben, daß keine Plage unter ihnen entstehe bei ihrer Musterung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Dies sollen sie geben: jeder zu den Gemusterten Übergehende die Hälfte eines Sekels, nach dem Sekel des Heiligtums (zwanzig Gera der Sekel), die Hälfte eines Sekels als Hebopfer dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Jeder zu den Gemusterten Übergehende, von zwanzig Jahren und darüber, soll das Hebopfer Jehovas geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Der Reiche soll nicht mehr geben und der Arme nicht weniger als die Hälfte eines Sekels, wenn ihr das Hebopfer Jehovas gebet, um Sühnung zu tun für eure Seelen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Und du sollst das Sühngeld von seiten der Kinder Israel nehmen und es für die Arbeit des Zeltes der Zusammenkunft geben; und es soll den Kindern Israel zum Gedächtnis sein vor Jehova, um Sühnung zu tun für eure Seelen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Mache auch ein Becken von Erz und sein Gestell von Erz zum Waschen; und setze es zwischen das Zelt der Zusammenkunft und den Altar und tue Wasser darein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Und Aaron und seine Söhne sollen ihre Hände und ihre Füße daraus waschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Wenn sie in das Zelt der Zusammenkunft hineingehen, sollen sie sich mit Wasser waschen, daß sie nicht sterben, oder wenn sie dem Altar nahen zum Dienst, um Jehova ein Feueropfer zu räuchern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Und sie sollen ihre Hände und ihre Füße waschen, daß sie nicht sterben; und das soll ihnen eine ewige Satzung sein, ihm und seinem Samen bei ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Und du, nimm dir die besten Gewürze: von selbst ausgeflossene Myrrhe fünfhundert Sekel, und würzigen Zimmet die Hälfte davon, zweihundertfünfzig, und Würzrohr zweihundertfünfzig,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'und Kassia fünfhundert, nach dem Sekel des Heiligtums, und ein Hin Olivenöl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'und mache daraus ein Öl der heiligen Salbung, eine Mischung von Gewürzsalbe, ein Werk des Salbenmischers; es soll ein Öl der heiligen Salbung sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Und du sollst damit salben das Zelt der Zusammenkunft und die Lade des Zeugnisses');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'und den Tisch und alle seine Geräte und den Leuchter und seine Geräte und den Räucheraltar');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'und den Brandopferaltar und alle seine Geräte und das Becken und sein Gestell,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'und du sollst sie heiligen; und sie sollen hochheilig sein: alles, was sie anrührt, wird heilig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Und Aaron und seine Söhne sollst du salben und sollst sie heiligen, um mir den Priesterdienst auszuüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Und zu den Kindern Israel sollst du also reden: Ein Öl der heiligen Salbung soll mir dieses sein bei euren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Auf keines Menschen Fleisch soll man es gießen, und nach dem Verhältnis seiner Bestandteile sollt ihr keines desgleichen machen; es ist heilig, heilig soll es euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Wer desgleichen mischt, und wer davon auf einen Fremden tut, der soll ausgerottet werden aus seinen Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Und Jehova sprach zu Mose: Nimm dir wohlriechende Gewürze, Stakte und Räuchermuschel und Galban, wohlriechende Gewürze und reinen Weihrauch; zu gleichen Teilen sollen sie sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Und mache Räucherwerk daraus, Würzwerk, ein Werk des Salbenmischers, gesalzen, rein, heilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Und zerstoße davon zu Pulver, und lege davon vor das Zeugnis in das Zelt der Zusammenkunft, woselbst ich mit dir zusammenkommen werde; hochheilig soll es euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Und das Räucherwerk, das du machen sollst, nach dem Verhältnis seiner Bestandteile sollt ihr es euch nicht machen; heilig dem Jehova soll es dir sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Wer desgleichen macht, um daran zu riechen, der soll ausgerottet werden aus seinen Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Siehe, ich habe Bezaleel, den Sohn Uris, des Sohnes Hurs, vom Stamme Juda, mit Namen berufen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'und habe ihn mit dem Geiste Gottes erfüllt, in Weisheit und in Verstand und in Kenntnis und in jeglichem Werk;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'um Künstliches zu ersinnen, zu arbeiten in Gold und in Silber und in Erz,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'und im Schneiden von Steinen zum Einsetzen und im Holzschneiden, um zu arbeiten in jeglichem Werk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Und ich, siehe, ich habe ihm Oholiab, den Sohn Achisamaks, vom Stamme Dan, beigegeben; und in das Herz eines jeden, der weisen Herzens ist, habe ich Weisheit gelegt, daß sie alles machen, was ich dir geboten habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'das Zelt der Zusammenkunft und die Lade des Zeugnisses und den Deckel, der darauf ist, und alle Geräte des Zeltes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'und den Tisch und alle seine Geräte und den reinen Leuchter und alle seine Geräte und den Räucheraltar');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'und den Brandopferaltar und alle seine Geräte, und das Becken und sein Gestell;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'und die Dienstkleider und die heiligen Kleider für Aaron, den Priester, und die Kleider seiner Söhne, um den Priesterdienst auszuüben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'und das Salböl und das wohlriechende Räucherwerk für das Heiligtum: nach allem, was ich dir geboten habe, sollen sie es machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Und du, rede zu den Kindern Israel und sprich: Fürwahr, meine Sabbathe sollt ihr beobachten; denn sie sind ein Zeichen zwischen mir und euch bei euren Geschlechtern, damit ihr wisset, daß ich, Jehova, es bin, der euch heiligt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'und beobachtet den Sabbath, denn heilig ist er euch; wer ihn entweiht, soll gewißlich getötet werden; denn wer irgend an ihm eine Arbeit tut, selbige Seele soll ausgerottet werden aus der Mitte ihrer Völker.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Sechs Tage soll man Arbeit tun, aber am siebten Tage ist der Sabbath der Ruhe, heilig dem Jehova; wer irgend am Tage des Sabbaths eine Arbeit tut, soll gewißlich getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Und die Kinder Israel sollen den Sabbath beobachten, um den Sabbath zu feiern bei ihren Geschlechtern: ein ewiger Bund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Er ist ein Zeichen zwischen mir und den Kindern Israel ewiglich; denn in sechs Tagen hat Jehova den Himmel und die Erde gemacht, und am siebten Tage hat er geruht und sich erquickt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Und er gab dem Mose, als er auf dem Berge Sinai mit ihm ausgeredet hatte, die zwei Tafeln des Zeugnisses, Tafeln von Stein, beschrieben mit dem Finger Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Und als das Volk sah, daß Mose verzog, von dem Berge herabzukommen, da versammelte sich das Volk zu Aaron, und sie sprachen zu ihm: Auf! Mache uns einen Gott, der vor uns hergehe! Denn dieser Mose, der Mann, der uns aus dem Lande Ägypten heraufgeführt hat, wir wissen nicht, was ihm geschehen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Und Aaron sprach zu ihnen: Reißet die goldenen Ringe ab, die in den Ohren eurer Weiber, eurer Söhne und eurer Töchter sind, und bringet sie zu mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Und das ganze Volk riß sich die goldenen Ringe ab, die in ihren Ohren waren, und sie brachten sie zu Aaron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Und er nahm es aus ihrer Hand und bildete es mit einem Meißel und machte ein gegossenes Kalb daraus. Und sie sprachen: Das ist dein Gott, Israel, der dich aus dem Lande Ägypten heraufgeführt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Und als Aaron es sah, baute er einen Altar vor ihm; und Aaron rief aus und sprach: Ein Fest dem Jehova ist morgen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Und sie standen des folgenden Tages früh auf und opferten Brandopfer und brachten Friedensopfer; und das Volk setzte sich nieder, um zu essen und zu trinken, und sie standen auf, um sich zu belustigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Da sprach Jehova zu Mose: Gehe, steige hinab! Denn dein Volk, das du aus dem Lande Ägypten heraufgeführt hast, hat sich verderbt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Sie sind schnell von dem Wege abgewichen, den ich ihnen geboten habe; sie haben sich ein gegossenes Kalb gemacht und sich vor ihm niedergebeugt und haben ihm geopfert und gesagt: Das ist dein Gott, Israel, der dich aus dem Lande Ägypten heraufgeführt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Und Jehova sprach zu Mose: Ich habe dieses Volk gesehen, und siehe, es ist ein hartnäckiges Volk;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'und nun laß mich, daß mein Zorn wider sie entbrenne und ich sie vernichte; dich aber will ich zu einer großen Nation machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Und Mose flehte zu Jehova, seinem Gott, und sprach: Warum, Jehova, sollte dein Zorn entbrennen wider dein Volk, das du aus dem Lande Ägypten herausgeführt hast mit großer Kraft und mit starker Hand?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Warum sollten die Ägypter also sprechen: Zum Unglück hat er sie herausgeführt, um sie im Gebirge zu töten und sie von der Fläche des Erdbodens zu vernichten? Kehre um von der Glut deines Zornes und laß dich des Übels wider dein Volk gereuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Gedenke Abrahams, Isaaks und Israels, deiner Knechte, denen du bei dir selbst geschworen hast, und hast zu ihnen gesagt: Mehren will ich euren Samen wie die Sterne des Himmels; und dieses ganze Land, von dem ich geredet habe, werde ich eurem Samen geben, daß sie es als Erbteil besitzen ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Und es gereute Jehova des Übels, wovon er geredet hatte, daß er es seinem Volke tun werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Und Mose wandte sich und stieg von dem Berge hinab, die zwei Tafeln des Zeugnisses in seiner Hand, Tafeln, beschrieben auf ihren beiden Seiten: auf dieser und auf jener Seite waren sie beschrieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Und die Tafeln waren das Werk Gottes, und die Schrift war die Schrift Gottes, eingegraben in die Tafeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Und Josua hörte die Stimme des Volkes, als es jauchzte, und sprach zu Mose: Kriegsgeschrei ist im Lager!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Und er sprach: Es ist nicht der Schall von Siegesgeschrei und nicht der Schall von Geschrei der Niederlage; den Schall von Wechselgesang höre ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Und es geschah, als er dem Lager nahte und das Kalb und die Reigentänze sah, da entbrannte der Zorn Moses, und er warf die Tafeln aus seinen Händen und zerbrach sie unten am Berge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Und er nahm das Kalb, das sie gemacht hatten, und verbrannte es im Feuer und zermalmte es, bis es zu Staub wurde; und er streute es auf das Wasser und ließ es die Kinder Israel trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Und Mose sprach zu Aaron: Was hat dir dieses Volk getan, daß du eine große Sünde über dasselbe gebracht hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Und Aaron sprach: Es entbrenne nicht der Zorn meines Herrn! Du kennst das Volk, daß es im Bösen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Und sie sprachen zu mir: Mache uns einen Gott, der vor uns hergehe; denn dieser Mose, der Mann, der uns aus dem Lande Ägypten heraufgeführt hat wir wissen nicht, was ihm geschehen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Und ich sprach zu ihnen: Wer hat Gold? Sie rissen es sich ab und gaben es mir, und ich warf es ins Feuer, und dieses Kalb ging hervor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Und Mose sah das Volk, daß es zügellos war; denn Aaron hatte es zügellos gemacht, zum Gespött unter ihren Widersachern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Und Mose stellte sich auf im Tore des Lagers und sprach: Her zu mir, wer für Jehova ist! Und es versammelten sich zu ihm alle Söhne Levis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Und er sprach zu ihnen: Also spricht Jehova, der Gott Israels: Leget ein jeder sein Schwert an seine Hüfte, gehet hin und wieder, von Tor zu Tor im Lager, und erschlaget ein jeder seinen Bruder und ein jeder seinen Freund und ein jeder seinen Nachbar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Und die Söhne Levis taten nach dem Worte Moses; und es fielen von dem Volke an selbigem Tage bei dreitausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Und Mose sprach: Weihet euch heute dem Jehova, ja, ein jeder in seinem Sohne und in seinem Bruder, um heute Segen auf euch zu bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Und es geschah am anderen Tage, da sprach Mose zu dem Volke: Ihr habt eine große Sünde begangen; und nun will ich zu Jehova hinaufsteigen, vielleicht möchte ich Sühnung tun für eure Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Und Mose kehrte zu Jehova zurück und sprach: Ach, dieses Volk hat eine große Sünde begangen, und sie haben sich einen Gott von Gold gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Und nun, wenn du ihre Sünde vergeben wolltest!...Wenn aber nicht, so lösche mich doch aus deinem Buche, das du geschrieben hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Und Jehova sprach zu Mose: Wer gegen mich gesündigt hat, den werde ich aus meinem Buche auslöschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Und nun gehe hin, führe das Volk, wohin ich dir gesagt habe. Siehe, mein Engel wird vor dir herziehen; und am Tage meiner Heimsuchung, da werde ich ihre Sünde an ihnen heimsuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Und Jehova schlug das Volk, darum daß sie das Kalb gemacht, welches Aaron gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Und Jehova redete zu Mose: Gehe ziehe hinauf von hinnen, du und das Volk, das du aus dem Lande Ägypten heraufgeführt hast, in das Land, das ich Abraham, Isaak und Jakob zugeschworen habe, indem ich sprach: Deinem Samen werde ich es geben! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Und ich werde einen Engel vor dir hersenden und vertreiben die Kanaaniter, die Amoriter und die Hethiter und die Perisiter, die Hewiter und die Jebusiter, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'in ein Land, das von Milch und Honig fließt; denn ich werde nicht in deiner Mitte hinaufziehen, denn du bist ein hartnäckiges Volk, daß ich dich nicht vernichte auf dem Wege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Und als das Volk dieses böse Wort hörte, da trauerten sie, und keiner legte seinen Schmuck an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Denn Jehova hatte zu Mose gesagt: Sprich zu den Kindern Israel: Ihr seid ein hartnäckiges Volk; zöge ich nur einen Augenblick in deiner Mitte hinauf, so würde ich dich vernichten. Und nun, lege deinen Schmuck von dir, und ich werde wissen, was ich dir tun will.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Und die Kinder Israel rissen sich ihren Schmuck ab an dem Berge Horeb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Und Mose nahm das Zelt und schlug es sich auf außerhalb des Lagers, fern vom Lager, und nannte es: Zelt der Zusammenkunft. Und es geschah, ein jeder, der Jehova suchte, ging hinaus zu dem Zelte der Zusammenkunft, das außerhalb des Lagers war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Und es geschah, wenn Mose zu dem Zelte hinausging, so erhob sich das ganze Volk, und sie standen, ein jeder am Eingang seines Zeltes; und sie schauten Mose nach, bis er in das Zelt trat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Und es geschah, wenn Mose in das Zelt trat, so stieg die Wolkensäule hernieder und stand am Eingang des Zeltes; und Jehova redete mit Mose.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Und das ganze Volk sah die Wolkensäule am Eingang des Zeltes stehen; und das ganze Volk erhob sich, und sie warfen sich nieder, ein jeder am Eingang seines Zeltes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Und Jehova redete mit Mose von Angesicht zu Angesicht, wie ein Mann mit seinem Freunde redet; und er kehrte zum Lager zurück. Sein Diener aber, Josua, der Sohn Nuns, ein Jüngling, wich nicht aus dem Innern des Zeltes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Und Mose sprach zu Jehova: Siehe, du sprichst zu mir: Führe dieses Volk hinauf, aber du hast mich nicht wissen lassen, wen du mit mir senden willst. Und du hast doch gesagt: Ich kenne dich mit Namen, und du hast auch Gnade gefunden in meinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Und nun, wenn ich denn Gnade gefunden habe in deinen Augen, so laß mich doch deinen Weg wissen, daß ich dich erkenne, damit ich Gnade finde in deinen Augen; und sieh, daß diese Nation dein Volk ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Und er sprach: Mein Angesicht wird mitgehen, und ich werde dir Ruhe geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Und er sprach zu ihm: Wenn dein Angesicht nicht mitgeht, so führe uns nicht hinauf von hinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Und woran soll es denn erkannt werden, daß ich Gnade gefunden habe in deinen Augen, ich und dein Volk? Nicht daran, daß du mit uns gehst und wir ausgesondert werden, ich und dein Volk, aus jedem Volke, das auf dem Erdboden ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Und Jehova sprach zu Mose: Auch dieses, was du gesagt hast, werde ich tun; denn du hast Gnade gefunden in meinen Augen, und ich kenne dich mit Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Und er sprach: Laß mich doch deine Herrlichkeit sehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Und Jehova sprach: Ich werde alle meine Güte vor deinem Angesicht vorübergehen lassen und werde den Namen Jehovas vor dir ausrufen; und ich werde begnadigen, wen ich begnadigen werde, und werde mich erbarmen, wessen ich mich erbarmen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Und er sprach: Du vermagst nicht mein Angesicht zu sehen, denn nicht kann ein Mensch mich sehen und leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Und Jehova sprach: Siehe, es ist ein Ort bei mir, da sollst du auf dem Felsen stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Und es wird geschehen, wenn meine Herrlichkeit vorübergeht, so werde ich dich in die Felsenkluft stellen und meine Hand über dich decken, bis ich vorübergegangen bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Und ich werde meine Hand hinwegtun, und du wirst mich von hinten sehen; aber mein Angesicht soll nicht gesehen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Und Jehova sprach zu Mose: Haue dir zwei steinerne Tafeln aus wie die ersten, und ich werde auf die Tafeln die Worte schreiben, welche auf den ersten Tafeln waren, die du zerbrochen hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Und sei bereit auf den Morgen, und steige am Morgen auf den Berg Sinai und stehe daselbst vor mir auf dem Gipfel des Berges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Und niemand soll mit dir heraufsteigen, und es soll selbst niemand auf dem ganzen Berge gesehen werden; sogar Kleinvieh und Rinder sollen nicht gegen diesen Berg hin weiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Und er hieb zwei steinerne Tafeln aus wie die ersten; und Mose stand des Morgens früh auf und stieg auf den Berg Sinai, so wie Jehova ihm geboten hatte, und nahm, die zwei steinernen Tafeln in seine Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Und Jehova stieg in der Wolke hernieder, und er stand daselbst bei ihm und rief den Namen Jehovas aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Und Jehova ging vor seinem Angesicht vorüber und rief: Jehova, Jehova, Gott, barmherzig und gnädig, langsam zum Zorn und groß an Güte und Wahrheit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'der Güte bewahrt auf Tausende hin, der Ungerechtigkeit, Übertretung und Sünde vergibt, aber keineswegs hält er für schuldlos den Schuldigen, der die Ungerechtigkeit der Väter heimsucht an den Kindern und Kindeskindern, am dritten und am vierten Gliede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Und Mose neigte sich eilends zur Erde und betete an und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Wenn ich doch Gnade gefunden habe in deinen Augen, Herr, so ziehe doch der Herr in unserer Mitte denn es ist ein hartnäckiges Volk und vergib unsere Ungerechtigkeit und unsere Sünde, und nimm uns an zum Eigentum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Und er sprach: Siehe, ich mache einen Bund: Vor deinem ganzen Volke will ich Wunder tun, die nicht gewirkt worden sind auf der ganzen Erde und unter allen Nationen; und das ganze Volk, in dessen Mitte du bist, soll das Werk Jehovas sehen; denn furchtbar ist, was ich mit dir tun werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Beobachte, was ich dir heute gebiete. Siehe, ich will vor dir vertreiben die Amoriter und die Kanaaniter und die Hethiter und die Perisiter und die Hewiter und die Jebusiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Hüte dich, daß du nicht einen Bund machest mit den Bewohnern des Landes, wohin du kommen wirst, daß sie nicht zum Fallstrick werden in deiner Mitte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'sondern ihre Altäre sollt ihr niederreißen und ihre Bildsäulen zerbrechen und ihre Ascherim ausrotten, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'denn du sollst nicht einen anderen Gott anbeten; denn Jehova, dessen Name Eiferer ist, ist ein eifernder Gott; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'daß du nicht einen Bund machest mit den Bewohnern des Landes und, wenn sie ihren Göttern nachhuren und ihren Göttern opfern, man dich einlade, und du von ihrem Schlachtopfer essest');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'und du von ihren Töchtern für deine Söhne nehmest, und ihre Töchter ihren Göttern nachhuren und machen, daß deine Söhne ihren Göttern nachhuren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Gegossene Götter sollst du dir nicht machen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Das Fest der ungesäuerten Brote sollst du beobachten; sieben Tage sollst du Ungesäuertes essen, wie ich dir geboten habe, zur bestimmten Zeit des Monats Abib; denn im Monat Abib bist du aus Ägypten ausgezogen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Alles, was die Mutter bricht, ist mein; und all dein Vieh, das männlich geboren wird, das Erstgeborene vom Rind-und Kleinvieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Und das Erstgeborene vom Esel sollst du lösen mit einem Lamme; und wenn du es nicht lösest, so brich ihm das Genick. Jeden Erstgeborenen deiner Söhne sollst du lösen. Und man soll nicht leer erscheinen vor meinem Angesicht. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sechs Tage sollst du arbeiten, aber am siebten Tage sollst du ruhen; in der Pflügezeit und in der Ernte sollst du ruhen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Und das Fest der Wochen, der Erstlinge der Weizenernte, sollst du feiern; und das Fest der Einsammlung beim Umlauf des Jahres. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Dreimal im Jahre sollen alle deine Männlichen erscheinen vor dem Angesicht des Herrn Jehova, des Gottes Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Denn ich werde die Nationen vor dir austreiben und deine Grenze erweitern; und niemand wird deines Landes begehren, wenn du hinaufziehst, um vor dem Angesicht Jehovas, deines Gottes, zu erscheinen dreimal im Jahre. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Du sollst nicht das Blut meines Schlachtopfers zu Gesäuertem opfern; und das Schlachtopfer des Passahfestes soll nicht über Nacht bleiben bis an den Morgen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Das Erste der Erstlinge deines Landes sollst du in das Haus Jehovas, deines Gottes, bringen. Du sollst ein Böcklein nicht kochen in der Milch seiner Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Und Jehova sprach zu Mose: Schreibe dir diese Worte auf; denn nach dem Inhalt dieser Worte habe ich mit dir und mit Israel einen Bund gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Und er war daselbst bei Jehova vierzig Tage und vierzig Nächte; er aß kein Brot und trank kein Wasser. Und er schrieb auf die Tafeln die Worte des Bundes, die zehn Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Und es Geschah, als Mose von dem Berge Sinai herabstieg, -und die zwei Tafeln des Zeugnisses waren in der Hand Moses, als er von dem Berge herabstieg, da wußte Mose nicht, daß die Haut seines Angesichts strahlte, weil er mit ihm geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Und Aaron und alle Kinder Israel sahen Mose an, und siehe, die Haut seines Angesichts strahlte; und sie fürchteten sich, ihm zu nahen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Und Mose rief ihnen zu, und sie wandten sich zu ihm, Aaron und alle Fürsten in der Gemeinde; und Mose redete zu ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Und danach nahten sich alle Kinder Israel; und er gebot ihnen alles, was Jehova auf dem Berge Sinai zu ihm geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Und Mose hörte auf, mit ihnen zu reden. Und er hatte eine Decke auf sein Angesicht gelegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Und wenn Mose vor Jehova hineinging, um mit ihm zu reden, tat er die Decke ab, bis er hinausging; und er ging hinaus und redete zu den Kindern Israel, was ihm geboten war;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'und die Kinder Israel sahen das Angesicht Moses, daß die Haut des Angesichts Moses strahlte; und Mose tat die Decke wieder auf sein Angesicht, bis er hineinging, um mit ihm zu reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Und Mose versammelte die ganze Gemeinde der Kinder Israel und sprach zu ihnen: Dies sind die Worte, die Jehova geboten hat, sie zu tun:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Sechs Tage soll man Arbeit tun, aber am siebten Tage soll euch ein heiliger Tag sein, ein Sabbath der Ruhe dem Jehova; wer irgend an ihm eine Arbeit tut, soll getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Ihr sollt am Tage des Sabbaths kein Feuer anzünden in allen euren Wohnungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Und Mose sprach zu der ganzen Gemeinde der Kinder Israel und sagte: Dies ist das Wort, das Jehova geboten hat, indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Nehmet von euch ein Hebopfer für Jehova; jeder, der willigen Herzens ist, soll es bringen, das Hebopfer Jehovas: Gold und Silber und Erz');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'und blauen und roten Purpur und Karmesin und Byssus und Ziegenhaar');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'und rotgefärbte Widderfelle und Dachsfelle und Akazienholz');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'und Öl zum Licht und Gewürze zum Salböl und zum wohlriechenden Räucherwerk');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'und Onyxsteine und Steine zum Einsetzen für das Ephod und für das Brustschild.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Und alle, die weisen Herzens sind unter euch, sollen kommen und alles machen, was Jehova geboten hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'die Wohnung, ihr Zelt und ihre Decke, ihre Klammern und ihre Bretter, ihre Riegel, ihre Säulen und ihre Füße;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'die Lade und ihre Stangen, den Deckel und den Scheidevorhang;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'den Tisch und seine Stangen und alle seine Geräte und die Schaubrote;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'und den Leuchter zum Licht und seine Geräte und seine Lampen und das Öl zum Licht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'und den Räucheraltar und seine Stangen und das Salböl und das wohlriechende Räucherwerk; und den Eingangsvorhang für den Eingang der Wohnung;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'den Brandopferaltar und das eherne Gitter an demselben, seine Stangen und alle seine Geräte; das Becken und sein Gestell;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'die Umhänge des Vorhofs, seine Säulen und seine Füße, und den Vorhang vom Tore des Vorhofs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'die Pflöcke der Wohnung und die Pflöcke des Vorhofs und ihre Seile;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'die Dienstkleider zum Dienst im Heiligtum, die heiligen Kleider für Aaron, den Priester, und die Kleider seiner Söhne, um den Priesterdienst auszuüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Und die ganze Gemeinde der Kinder Israel ging von Mose hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Und sie kamen, ein jeder, den sein Herz trieb; und ein jeder, der willigen Geistes war, brachte das Hebopfer Jehovas für das Werk des Zeltes der Zusammenkunft und für all seine Arbeit und für die heiligen Kleider.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Und die Männer kamen mit den Weibern; ein jeder, der willigen Herzens war, brachte Nasenringe und Ohrringe und Fingerringe und Spangen, allerlei goldene Geräte; und jeder, der dem Jehova ein Webopfer an Gold webte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Und ein jeder, bei dem sich blauer und roter Purpur fand, und Karmesin und Byssus und Ziegenhaar und rotgefärbte Widderfelle und Dachsfelle, brachte es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Jeder, der ein Hebopfer an Silber und Erz hob, brachte das Hebopfer Jehovas; und jeder, bei dem sich Akazienholz fand zu allerlei Werk der Arbeit, brachte es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Und alle Weiber, die weisen Herzens waren, spannen mit ihren Händen und brachten das Gespinst: den blauen und den roten Purpur, den Karmesin und den Byssus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Und alle verständigen Weiber, die ihr Herz trieb, spannen das Ziegenhaar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Und die Fürsten brachten Onyxsteine und Steine zum Einsetzen für das Ephod und für das Brustschild,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'und das Gewürz und das Öl zum Licht und zum Salböl und zum wohlriechenden Räucherwerk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Die Kinder Israel, alle Männer und Weiber, die willigen Herzens waren, um zu all dem Werke zu bringen, das Jehova durch Mose zu machen geboten hatte, brachten eine freiwillige Gabe dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Und Mose sprach zu den Kindern Israel: Sehet, Jehova hat Bezaleel, den Sohn Uris, des Sohnes Hurs, vom Stamme Juda, mit Namen berufen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'und hat ihn mit dem Geiste Gottes erfüllt, in Weisheit, in Verstand und in Kenntnis und in jeglichem Werke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'und zwar um Künstliches zu ersinnen, zu arbeiten in Gold und in Silber und in Erz,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'und im Schneiden von Steinen zum Einsetzen und im Holzschneiden, um zu arbeiten in jeglichem Kunstwerk;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'und zu unterweisen hat er ihm ins Herz gelegt, ihm und Oholiab, dem Sohne Achisamaks, vom Stamme Dan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Er hat sie mit Weisheit des Herzens erfüllt, um jegliches Werk des Künstlers und des Kunstwebers und des Buntwirkers zu machen, in blauem und rotem Purpur und Karmesin und Byssus, und des Webers; derer, die allerlei Werk machen und Künstliches ersinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Und Bezaleel und Oholiab und alle Männer, die weisen Herzens waren, in welche Jehova Weisheit und Verstand gelegt hatte, damit sie alles Werk der Arbeit des Heiligtums zu machen wüßten, taten nach allem, was Jehova geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Und Mose rief Bezaleel und Oholiab und jeden Mann, der weisen Herzens war, in dessen Herz Gott Weisheit gelegt hatte, jeden, den sein Herz trieb, ans Werk zu gehen, um es zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Und sie nahmen von Mose das ganze Hebopfer, das die Kinder Israel gebracht hatten zum Werke der Arbeit des Heiligtums, um es zu machen; und diese brachten ihm noch freiwillige Gaben, Morgen für Morgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Und es kamen alle weisen Männer, die alles Werk des Heiligtums machten, ein jeder von seinem Werke, das sie machten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'und sprachen zu Mose und sagten: Das Volk bringt viel, mehr als genug für die Arbeit des Werkes, das Jehova zu machen geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Da gebot Mose, und man ließ einen Ruf durchs Lager ergehen also: Weder Mann noch Weib soll ferner ein Werk machen für das Hebopfer des Heiligtums! Und so wurde dem Volke das Bringen gewehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Und des Verfertigten war genug für das ganze Werk, um es zu machen; und es war übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Und alle, die weisen Herzens waren unter den Arbeitern des Werkes, machten die Wohnung aus zehn Teppichen; von gezwirntem Byssus und blauem und rotem Purpur und Karmesin, mit Cherubim in Kunstweberarbeit machte er sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Die Länge eines Teppichs war achtundzwanzig Ellen, und vier Ellen die Breite eines Teppichs: ein Maß für alle Teppiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Und er fügte fünf Teppiche zusammen, einen an den anderen, und er fügte wieder fünf Teppiche zusammen, einen an den anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Und er machte Schleifen von blauem Purpur an den Saum des einen Teppichs am Ende, bei der Zusammenfügung; also machte er es an dem Saume des äußersten Teppichs bei der anderen Zusammenfügung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Fünfzig Schleifen machte er an den einen Teppich, und fünfzig Schleifen machte er an das Ende des Teppichs, der bei der anderen Zusammenfügung war, die Schleifen eine der anderen gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Und er machte fünfzig Klammern von Gold und fügte die Teppiche zusammen, einen an den anderen, mit den Klammern, so daß die Wohnung ein Ganzes wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Und er machte Teppiche von Ziegenhaar zum Zelte über die Wohnung; elf solcher Teppiche machte er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Die Länge eines Teppichs war dreißig Ellen, und vier Ellen die Breite eines Teppichs: ein Maß für die elf Teppiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Und er fügte zusammen fünf Teppiche besonders und sechs Teppiche besonders.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Und er machte fünfzig Schleifen an den Saum des äußersten Teppichs bei der Zusammenfügung, und fünfzig Schleifen machte er an den Saum des Teppichs der anderen Zusammenfügung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Und er machte fünfzig Klammern von Erz, um das Zelt zusammenzufügen, so daß es ein Ganzes wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Und er machte für das Zelt eine Decke von rotgefärbten Widderfellen und eine Decke von Dachsfellen oben darüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Und er machte die Bretter zu der Wohnung von Akazienholz, aufrechtstehend:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'zehn Ellen die Länge eines Brettes, und eine und eine halbe Elle die Breite eines Brettes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'zwei Zapfen an einem Brette, einer dem anderen gegenüber eingefügt: also machte er es an allen Brettern der Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Und er machte die Bretter zu der Wohnung: zwanzig Bretter an der Seite gegen Mittag, südwärts;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'und er machte vierzig Füße von Silber unter die zwanzig Bretter: zwei Füße unter ein Brett für seine zwei Zapfen, und wieder zwei Füße unter ein Brett für seine zwei Zapfen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'und an der anderen Seite der Wohnung, an der Nordseite, machte er zwanzig Bretter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'und ihre vierzig Füße von Silber: zwei Füße unter ein Brett, und wieder zwei Füße unter ein Brett;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'und an der Hinterseite der Wohnung gegen Westen machte er sechs Bretter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'und zwei Bretter machte er für die Winkel der Wohnung an der Hinterseite;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'und sie waren zweifach von unten auf und waren an ihrem Oberteil völlig aneinander in einem Ringe; also machte er es mit ihnen beiden an den beiden Winkeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Und es waren acht Bretter, und ihre Füße von Silber: sechzehn Füße, je zwei Füße unter einem Brette.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Und er machte Riegel von Akazienholz: fünf zu den Brettern der einen Seite der Wohnung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'und fünf Riegel zu den Brettern der anderen Seite der Wohnung, und fünf Riegel zu den Brettern der Wohnung an der Hinterseite gegen Westen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'und er machte den mittleren Riegel in der Mitte der Bretter durchlaufend von einem Ende zum anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Und er überzog die Bretter mit Gold; und ihre Ringe, die Behälter für die Riegel, machte er von Gold, und überzog die Riegel mit Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Und er machte den Vorhang von blauem und rotem Purpur und Karmesin und gezwirntem Byssus; in Kunstweberarbeit machte er ihn, mit Cherubim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Und er machte zu demselben vier Säulen von Akazienholz und überzog sie mit Gold, ihre Haken von Gold, und er goß zu denselben vier Füße von Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Und er machte für den Eingang des Zeltes einen Vorhang von blauem und rotem Purpur und Karmesin und gezwirntem Byssus, in Buntwirkerarbeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'und seine fünf Säulen und ihre Haken; und er überzog ihre Köpfe und ihre Bindestäbe mit Gold; und ihre fünf Füße waren von Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Und Bezaleel machte die Lade von Akazienholz: zwei und eine halbe Elle ihre Länge, und eine und eine halbe Elle ihre Breite, und eine und eine halbe Elle ihre Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Und er überzog sie mit reinem Golde inwendig und auswendig, und machte einen goldenen Kranz daran ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Und er goß für dieselbe vier Ringe von Gold an ihre vier Ecken, zwei Ringe an ihrer einen Seite und zwei Ringe an ihrer anderen Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Und er machte Stangen von Akazienholz und überzog sie mit Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Und er brachte die Stangen in die Ringe an den Seiten der Lade, um die Lade zu tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Und er machte einen Deckel von reinem Golde: zwei und eine halbe Elle seine Länge, und eine und eine halbe Elle seine Breite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Und er machte zwei Cherubim von Gold; in getriebener Arbeit machte er sie, an beiden Enden des Deckels:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'einen Cherub an dem Ende der einen Seite und einen Cherub an dem Ende der anderen Seite; aus dem Deckel machte er die Cherubim, aus seinen beiden Enden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Und die Cherubim breiteten die Flügel aus nach oben, den Deckel mit ihren Flügeln überdeckend, und ihre Angesichter waren einander gegenüber; die Angesichter der Cherubim waren gegen den Deckel gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Und er machte den Tisch von Akazienholz: zwei Ellen seine Länge und eine Elle seine Breite, und eine und eine halbe Elle seine Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Und er überzog ihn mit reinem Golde und machte ihm einen Kranz von Gold ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Und er machte ihm eine Leiste, eine Hand breit, ringsum und machte einen Kranz von Gold an seiner Leiste ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Und er goß für denselben vier Ringe von Gold und setzte die Ringe an die vier Ecken, die an seinen vier Füßen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Dicht bei der Leiste waren die Ringe, als Behälter für die Stangen, um den Tisch zu tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Und er machte die Stangen von Akazienholz und überzog sie mit Gold, um den Tisch zu tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Und er machte die Geräte, die auf dem Tische waren: seine Schüsseln und seine Schalen und seine Spendschalen und die Kannen, mit welchen das Trankopfer ausgegossen wird, von reinem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Und er machte den Leuchter von reinem Golde; in getriebener Arbeit machte er den Leuchter, seinen Fuß und seinen Schaft; seine Kelche, seine Knäufe und seine Blumen waren aus ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Und sechs Arme gingen von seinen Seiten aus: drei Arme des Leuchters aus seiner einen Seite und drei Arme des Leuchters aus seiner anderen Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Drei Kelche, mandelblütenförmig, an dem einen Arme: Knauf und Blume; und drei Kelche, mandelblütenförmig, an dem anderen Arme: Knauf und Blume; also für die sechs Arme, die von dem Leuchter ausgingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Und an dem Leuchter vier Kelche, mandelblütenförmig: seine Knäufe und seine Blumen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'und zwar ein Knauf unter zwei Armen aus ihm, und wieder ein Knauf unter zwei Armen aus ihm, und wieder ein Knauf unter zwei Armen aus ihm, für die sechs Arme, die von ihm ausgingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Ihre Knäufe und ihre Arme waren aus ihm; der ganze Leuchter eine getriebene Arbeit von reinem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Und er machte seine sieben Lampen und seine Lichtschneuzen und seine Löschnäpfe von reinem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Aus einem Talent reinen Goldes machte er ihn und alle seine Geräte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Und er machte den Räucheraltar von Akazienholz: eine Elle seine Länge, und eine Elle seine Breite, quadratförmig, und zwei Ellen seine Höhe; aus ihm waren seine Hörner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Und er überzog ihn mit reinem Golde, seine Platte und seine Wände ringsum und seine Hörner; und er machte ihm einen Kranz von Gold ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Und er machte ihm zwei Ringe von Gold, unter seinen Kranz, an seine beiden Seiten, an seine beiden Wände, zu Behältern für die Stangen, um ihn mit denselben zu tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Und er machte die Stangen von Akazienholz und überzog sie mit Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Und er machte das heilige Salböl und das reine wohlriechende Räucherwerk, ein Werk des Salbenmischers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Und er machte den Brandopferaltar von Akazienholz: fünf Ellen seine Länge, und fünf Ellen seine Breite, quadratförmig, und drei Ellen seine Höhe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'und er machte seine Hörner an seine vier Ecken; aus ihm waren seine Hörner; und er überzog ihn mit Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Und er machte alle die Geräte des Altars: die Töpfe und die Schaufeln und die Sprengschalen, die Gabeln und die Kohlenpfannen; alle seine Geräte machte er von Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Und er machte dem Altar ein Gitter von Netzwerk aus Erz, unter seiner Einfassung, unterwärts, bis zu seiner Hälfte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Und er goß vier Ringe an die vier Ecken des ehernen Gitters als Behälter für die Stangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Und er machte die Stangen von Akazienholz und überzog sie mit Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Und er brachte die Stangen in die Ringe, an die Seiten des Altars, um ihn mit denselben zu tragen; hohl, von Brettern machte er ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Und er machte das Becken von Erz und sein Gestell von Erz, von den Spiegeln der sich scharenden Weiber, die sich scharten am Eingang des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Und er machte den Vorhof: an der Mittagseite, südwärts, die Umhänge des Vorhofs von gezwirntem Byssus, hundert Ellen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'ihre zwanzig Säulen und ihre zwanzig Füße von Erz, die Haken der Säulen und ihre Bindestäbe von Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Und an der Nordseite hundert Ellen; ihre zwanzig Säulen und ihre zwanzig Füße von Erz, die Haken der Säulen und ihre Bindestäbe von Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Und an der Westseite fünfzig Ellen Umhänge; ihre zehn Säulen und ihre zehn Füße, die Haken der Säulen und ihre Bindestäbe von Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Und an der Ostseite gegen Aufgang, fünfzig Ellen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'fünfzehn Ellen Umhänge auf der einen Seite, ihre drei Säulen und ihre drei Füße;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'und auf der anderen Seite, diesseit und jenseit vom Tore des Vorhofs fünfzehn Ellen Umhänge, ihre drei Säulen und ihre drei Füße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Alle Umhänge des Vorhofs ringsum waren von gezwirntem Byssus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'und die Füße der Säulen von Erz, die Haken der Säulen und ihre Bindestäbe von Silber und der Überzug ihrer Köpfe von Silber; und die Säulen des Vorhofs waren alle mit Bindestäben von Silber versehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Und den Vorhang vom Tore des Vorhofs machte er in Buntwirkerarbeit, von blauem und rotem Purpur und Karmesin und gezwirntem Byssus; und zwar zwanzig Ellen die Länge; und die Höhe, in der Breite, fünf Ellen, gerade wie die Umhänge des Vorhofs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'und ihre vier Säulen und ihre vier Füße waren von Erz, ihre Haken von Silber und der Überzug ihrer Köpfe und ihre Bindestäbe von Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Und alle Pflöcke zur Wohnung und zum Vorhof ringsum waren von Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Dies ist die Berechnung der Wohnung, der Wohnung des Zeugnisses, die berechnet wurde auf Befehl Moses, durch den Dienst der Leviten unter der Hand Ithamars, des Sohnes Aarons, des Priesters; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'und Bezaleel, der Sohn Uris, des Sohnes Hurs, vom Stamme Juda, machte alles, was Jehova dem Mose geboten hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'und mit ihm Oholiab, der Sohn Achisamaks, vom Stamme Dan, ein Künstler und Kunstweber und Buntwirker in blauem und rotem Purpur und Karmesin und Byssus: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Alles Gold, das zum Werke verwendet wurde an dem ganzen Werke des Heiligtums, das Gold des Webopfers, betrug neunundzwanzig Talente und siebenhundertdreißig Sekel, nach dem Sekel des Heiligtums.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Und das Silber von den Gemusterten der Gemeinde betrug hundert Talente und tausend siebenhundertfünfundsiebzig Sekel, nach dem Sekel des Heiligtums:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'ein Beka auf den Kopf, die Hälfte eines Sekels, nach dem Sekel des Heiligtums, von einem jeden, der zu den Gemusterten überging, von zwanzig Jahren und darüber, von sechshundert dreitausend fünfhundertfünfzig Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Und die hundert Talente Silber waren zum Gießen der Füße des Heiligtums und der Füße des Vorhanges, hundert Füße auf hundert Talente, ein Talent auf einen Fuß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Und von den tausend siebenhundertfünfundsiebzig Sekeln machte er die Haken für die Säulen und überzog ihre Köpfe und verband sie mit Stäben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Und das Erz des Webopfers betrug siebzig Talente und zweitausendvierhundert Sekel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Und er machte daraus die Füße vom Eingang des Zeltes der Zusammenkunft und den ehernen Altar und sein ehernes Gitter und alle Geräte des Altars;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'und die Füße des Vorhofs ringsum und die Füße vom Tore des Vorhofs und alle Pflöcke der Wohnung und alle Pflöcke des Vorhofs ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Und aus dem blauen und dem roten Purpur und dem Karmesin machten sie die Dienstkleider zum Dienst im Heiligtum, und sie machten die heiligen Kleider für Aaron, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Und man machte das Ephod von Gold, blauem und rotem Purpur und Karmesin und gezwirntem Byssus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Und sie plätteten Goldbleche, und man zerschnitt sie zu Fäden, zum Verarbeiten unter den blauen und unter den roten Purpur und unter den Karmesin und unter den Byssus, in Kunstweberarbeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Sie machten zusammenfügende Schulterstücke daran: an seinen beiden Enden wurde es zusammengefügt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Und der gewirkte Gürtel, mit dem es angebunden wurde, der darüber war, war von gleichem Stoffe, von gleicher Arbeit mit ihm: von Gold, blauem und rotem Purpur und Karmesin und gezwirntem Byssus: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Und sie machten die Onyxsteine, umgeben mit Einfassungen von Gold, gestochen in Siegelstecherei, nach den Namen der Söhne Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Und man setzte sie auf die Schulterstücke des Ephods, als Steine des Gedächtnisses für die Kinder Israel: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Und er machte das Brustschild in Kunstweberarbeit, gleich der Arbeit des Ephods: von Gold, blauem und rotem Purpur und Karmesin und gezwirntem Byssus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Es war quadratförmig; das Brustschild machten sie gedoppelt, eine Spanne seine Länge und eine Spanne seine Breite, gedoppelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Und sie besetzten es mit vier Reihen von Steinen; eine Reihe: Sardis, Topas und Smaragd, die erste Reihe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'und die zweite Reihe: Karfunkel, Saphir und Diamant;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'und die dritte Reihe: Opal, Achat und Amethyst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'und die vierte Reihe: Chrysolith, Onyx und Jaspis; umgeben mit Einfassungen von Gold in ihren Einsetzungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Und der Steine waren nach den Namen der Söhne Israels zwölf, nach ihren Namen; in Siegelstecherei, ein jeder nach seinem Namen, für die zwölf Stämme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Und sie machten an das Brustschild schnurähnliche Ketten, in Flechtwerk, von reinem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Und sie machten zwei Einfassungen von Gold und zwei Ringe von Gold und befestigten die zwei Ringe an die beiden Enden des Brustschildes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Und die zwei geflochtenen Schnüre von Gold befestigten sie an die beiden Ringe an den Enden des Brustschildes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'und die beiden anderen Enden der zwei geflochtenen Schnüre befestigten sie an die beiden Einfassungen und befestigten sie an die Schulterstücke des Ephods, an seine Vorderseite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Und sie machten zwei Ringe von Gold und befestigten sie an die beiden Enden des Brustschildes, an seinen Saum, der gegen das Ephod hin war, einwärts;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'und sie machten zwei Ringe von Gold und befestigten sie an die beiden Schulterstücke des Ephods, unten an seine Vorderseite, gerade bei seiner Zusammenfügung, oberhalb des gewirkten Gürtels des Ephods.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Und sie banden das Brustschild mit seinen Ringen an die Ringe des Ephods mit einer purpurblauen Schnur, daß es über dem gewirkten Gürtel des Ephods wäre und das Brustschild sich nicht von dem Ephod verrückte: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Und er machte das Oberkleid des Ephods in Weberarbeit, ganz von blauem Purpur.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Und die Öffnung des Oberkleides war in seiner Mitte, wie die Öffnung eines Panzers; eine Borte hatte es an seiner Öffnung ringsum, damit es nicht einrisse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Und sie machten an den Saum des Oberkleides Granatäpfel von blauem und rotem Purpur und Karmesin, gezwirnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Und sie machten Schellen von reinem Golde und setzten die Schellen zwischen die Granatäpfel an den Saum des Oberkleides ringsum, zwischen die Granatäpfel:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'eine Schelle und einen Granatapfel, eine Schelle und einen Granatapfel an den Saum des Oberkleides ringsum, um den Dienst zu verrichten: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Und sie machten die Leibröcke von Byssus, in Weberarbeit, für Aaron und für seine Söhne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'und den Kopfbund von Byssus, und den Kopfschmuck der hohen Mützen von Byssus, und die leinenen Beinkleider von gezwirntem Byssus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'und den Gürtel von gezwirntem Byssus und von blauem und rotem Purpur und Karmesin, in Buntwirkerarbeit: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Und sie machten das Blech, das heilige Diadem, von reinem Golde, und schrieben darauf mit Siegelstecherschrift: Heiligkeit dem Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Und sie taten daran eine Schnur von blauem Purpur, um es oben an den Kopfbund zu befestigen: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Und es wurde vollendet die ganze Arbeit der Wohnung des Zeltes der Zusammenkunft; und die Kinder Israel taten nach allem, was Jehova dem Mose geboten hatte, also taten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Und sie brachten die Wohnung zu Mose: Das Zelt und alle seine Geräte, seine Klammern, seine Bretter, seine Riegel und seine Säulen und seine Füße;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'und die Decke von rotgefärbten Widderfellen und die Decke von Dachsfellen und den Scheidevorhang;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'die Lade des Zeugnisses und ihre Stangen und den Deckel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'den Tisch, alle seine Geräte und die Schaubrote;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'den reinen Leuchter, seine Lampen, die zuzurichtenden Lampen, und alle seine Geräte und das Öl zum Licht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'und den goldenen Altar und das Salböl und das wohlriechende Räucherwerk; und den Vorhang vom Eingange des Zeltes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'den ehernen Altar und sein ehernes Gitter, seine Stangen und alle seine Geräte; das Becken und sein Gestell;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'die Umhänge des Vorhofs, seine Säulen und seine Füße; und den Vorhang für das Tor des Vorhofs, seine Seile und seine Pflöcke; und alle Geräte zum Dienst der Wohnung des Zeltes der Zusammenkunft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'die Dienstkleider zum Dienst im Heiligtum, die heiligen Kleider für Aaron, den Priester, und die Kleider seiner Söhne, um den Priesterdienst auszuüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Nach allem, was Jehova dem Mose geboten hatte, also hatten die Kinder Israel die ganze Arbeit gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Und Mose sah das ganze Werk, und siehe, sie hatten es gemacht; so wie Jehova geboten hatte, also hatten sie es gemacht; und Mose segnete sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Am Tage des ersten Monats, am Ersten des Monats, sollst du die Wohnung des Zeltes der Zusammenkunft aufrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Und du sollst die Lade des Zeugnisses darein stellen und die Lade mit dem Vorhang verdecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Und bringe den Tisch hinein und richte zu, was auf ihm zuzurichten ist; und bringe den Leuchter hinein und zünde seine Lampen an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Und stelle den goldenen Altar zum Räucherwerk vor die Lade des Zeugnisses, und hänge den Vorhang des Eingangs zur Wohnung auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Und stelle den Brandopferaltar vor den Eingang der Wohnung des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Und stelle das Becken zwischen das Zelt der Zusammenkunft und den Altar, und tue Wasser darein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Und richte den Vorhof auf ringsum und hänge den Vorhang vom Tore des Vorhofs auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Und nimm das Salböl und salbe die Wohnung und alles, was darin ist, und heilige sie und alle ihre Geräte; und sie soll heilig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Und salbe den Brandopferaltar und alle seine Geräte, und heilige den Altar; und der Altar soll hochheilig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Und salbe das Becken und sein Gestell, und heilige es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Und laß Aaron und seine Söhne herzunahen an den Eingang des Zeltes der Zusammenkunft und wasche sie mit Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Und bekleide Aaron mit den heiligen Kleidern und salbe ihn und heilige ihn, daß er mir den Priesterdienst ausübe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Und seine Söhne sollst du herzunahen lassen und sie mit den Leibröcken bekleiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Und du sollst sie salben, so wie du ihren Vater gesalbt hast, daß sie mir den Priesterdienst ausüben. Und ihre Salbung soll geschehen, um ihnen zu einem ewigen Priestertum zu sein bei ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Und Mose tat es; nach allem, was Jehova ihm geboten hatte, also tat er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Und es geschah im ersten Monat, im zweiten Jahre, am Ersten des Monats, da wurde die Wohnung aufgerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Und Mose richtete die Wohnung auf und setzte ihre Füße und stellte ihre Bretter auf und setzte ihre Riegel ein und richtete ihre Säulen auf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'und er breitete das Zelt über die Wohnung und legte die Decke des Zeltes oben darüber: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Und er nahm das Zeugnis und legte es in die Lade und tat die Stangen an die Lade und legte den Deckel auf die Lade, oben darauf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'und er brachte die Lade in die Wohnung und hing den Scheidevorhang auf und verdeckte die Lade des Zeugnisses: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Und er setzte den Tisch in das Zelt der Zusammenkunft an die Seite der Wohnung gegen Norden, außerhalb des Vorhangs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'und er richtete darauf eine Brotschicht zu vor Jehova: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Und er stellte den Leuchter in das Zelt der Zusammenkunft, dem Tische gegenüber, an die Seite der Wohnung gegen Mittag,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'und er zündete die Lampen an vor Jehova: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Und er stellte den goldenen Altar in das Zelt der Zusammenkunft vor den Vorhang');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'und räucherte darauf wohlriechendes Räucherwerk: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Und er hing den Vorhang des Eingangs zur Wohnung auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Und den Brandopferaltar stellte er an den Eingang der Wohnung des Zeltes der Zusammenkunft, und er opferte darauf das Brandopfer und das Speisopfer: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Und er stellte das Becken zwischen das Zelt der Zusammenkunft und den Altar und tat Wasser darein zum Waschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Und Mose und Aaron und seine Söhne wuschen daraus ihre Hände und ihre Füße;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'wenn sie in das Zelt der Zusammenkunft hineingingen und wenn sie dem Altar nahten, wuschen sie sich, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Und er richtete den Vorhof auf, rings um die Wohnung und um den Altar und hing den Vorhang vom Tore des Vorhofs auf. Und so vollendete Mose das Werk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Und die Wolke bedeckte das Zelt der Zusammenkunft, und die Herrlichkeit Jehovas erfüllte die Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Und Mose konnte nicht in das Zelt der Zusammenkunft hineingehen; denn die Wolke ruhte darauf, und die Herrlichkeit Jehovas erfüllte die Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Und wenn die Wolke sich von der Wohnung erhob, so brachen die Kinder Israel auf, auf allen ihren Zügen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Und wenn die Wolke sich nicht erhob, so brachen sie nicht auf, bis zu dem Tage, da sie sich erhob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Denn die Wolke Jehovas war des Tages auf der Wohnung, und des Nachts war ein Feuer darin vor den Augen des ganzen Hauses Israel, auf allen ihren Zügen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Und Jehova rief Mose, und er redete zu ihm aus dem Zelte der Zusammenkunft und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Rede zu den Kindern Israel und sprich zu ihnen: Wenn ein Mensch von euch dem Jehova eine Opfergabe darbringen will, so sollt ihr vom Vieh, vom Rind-und Kleinvieh, eure Opfergabe darbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Wenn seine Opfergabe ein Brandopfer ist vom Rindvieh, so soll er sie darbringen, ein Männliches ohne Fehl; an dem Eingang des Zeltes der Zusammenkunft soll er sie darbringen, zum Wohlgefallen für ihn vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Und er soll seine Hand auf den Kopf des Brandopfers legen, und es wird wohlgefällig für ihn sein, um Sühnung für ihn zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Und er soll das junge Rind schlachten vor Jehova; und die Söhne Aarons, die Priester, sollen das Blut herzubringen und das Blut ringsum an den Altar sprengen, der an dem Eingang des Zeltes der Zusammenkunft ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Und er soll dem Brandopfer die Haut abziehen und es in seine Stücke zerlegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Und die Söhne Aarons, des Priesters, sollen Feuer auf den Altar legen und Holz auf dem Feuer zurichten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'und die Söhne Aarons, die Priester, sollen die Stücke, den Kopf und das Fett auf dem Holze zurichten über dem Feuer, das auf dem Altar ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Und sein Eingeweide und seine Schenkel soll er mit Wasser waschen; und der Priester soll das Ganze auf dem Altar räuchern: es ist ein Brandopfer, ein Feueropfer lieblichen Geruchs dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Und wenn seine Opfergabe vom Kleinvieh ist, von den Schafen oder von den Ziegen, zum Brandopfer, so soll er sie darbringen, ein Männliches ohne Fehl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Und er soll es schlachten an der Seite des Altars gegen Norden, vor Jehova; und die Söhne Aarons, die Priester, sollen sein Blut an den Altar sprengen ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Und er soll es in seine Stücke zerlegen mit seinem Kopf und seinem Fett; und der Priester soll sie auf dem Holze zurichten, über dem Feuer, das auf dem Altar ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Und das Eingeweide und die Schenkel soll er mit Wasser waschen; und der Priester soll das Ganze darbringen und auf dem Altar räuchern: es ist ein Brandopfer, ein Feueropfer lieblichen Geruchs dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Und wenn ein Brandopfer vom Geflügel seine Opfergabe ist dem Jehova, so soll er von den Turteltauben oder von den jungen Tauben seine Opfergabe darbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Und der Priester bringe sie zum Altar und kneipe ihr den Kopf ein und räuchere sie auf dem Altar, und ihr Blut soll ausgedrückt werden an die Wand des Altars.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Und er trenne ihren Kropf mit seinem Unrat ab und werfe ihn neben den Altar gegen Osten, an den Ort der Fettasche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Und er soll sie an den Flügeln einreißen, es soll sie nicht zertrennen; und der Priester soll sie auf dem Altar räuchern, auf dem Holze, das über dem Feuer ist: es ist ein Brandopfer, ein Feueropfer lieblichen Geruchs dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Und wenn jemand die Opfergabe eines Speisopfers dem Jehova darbringen will, so soll seine Opfergabe Feinmehl sein; und er soll Öl darauf gießen und Weihrauch darauf legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Und er soll es zu den Söhnen Aarons, den Priestern, bringen; und er nehme davon seine Hand voll, von seinem Feinmehl und von seinem Öl samt all seinem Weihrauch, und der Priester räuchere das Gedächtnisteil desselben auf dem Altar: es ist ein Feueropfer lieblichen Geruchs dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Und das Übrige von dem Speisopfer soll für Aaron und für seine Söhne sein: ein Hochheiliges von den Feueropfern Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Und wenn du als Opfergabe eines Speisopfers ein Ofengebäck darbringen willst, so soll es Feinmehl sein, ungesäuerte Kuchen, gemengt mit Öl, und ungesäuerte Fladen, gesalbt mit Öl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Und wenn deine Opfergabe ein Speisopfer in der Pfanne ist, so soll es Feinmehl sein, gemengt mit Öl, ungesäuert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'du sollst es in Stücke zerbrechen und Öl darauf gießen: es ist ein Speisopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Und wenn deine Opfergabe ein Speisopfer im Napfe ist, so soll es von Feinmehl mit Öl gemacht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Und du sollst das Speisopfer, das von diesen Dingen gemacht wird, dem Jehova bringen; und man soll es dem Priester überreichen, und er soll es an den Altar tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Und der Priester hebe von dem Speisopfer dessen Gedächtnisteil ab und räuchere es auf dem Altar: es ist ein Feueropfer lieblichen Geruchs dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Und das Übrige von dem Speisopfer soll für Aaron und für seine Söhne sein: ein Hochheiliges von den Feueropfern Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Alles Speisopfer, das ihr dem Jehova darbringet, soll nicht aus Gesäuertem gemacht werden; denn aller Sauerteig und aller Honig, davon sollt ihr kein Feueropfer dem Jehova räuchern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Was die Opfergabe der Erstlinge betrifft, so sollt ihr sie Jehova darbringen; aber auf den Altar sollen sie nicht kommen zum lieblichen Geruch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Und alle Opfergaben deines Speisopfers sollst du mit Salz salzen und sollst das Salz des Bundes deines Gottes nicht fehlen lassen bei deinem Speisopfer; bei allen deinen Opfergaben sollst du Salz darbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Und wenn du ein Speisopfer von den ersten Früchten dem Jehova darbringen willst, so sollst du Ähren, am Feuer geröstet, Schrot von Gartenkorn, darbringen als Speisopfer von deinen ersten Früchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Und du sollst Öl darauf tun und Weihrauch darauf legen: es ist ein Speisopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Und der Priester soll das Gedächtnisteil desselben räuchern, von seinem Schrote und von seinem Öle, samt allem seinem Weihrauch: es ist ein Feueropfer dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Und wenn seine Opfergabe ein Friedensopfer ist: wenn er sie von den Rindern darbringt, es sei ein Männliches oder ein Weibliches, so soll er sie ohne Fehl vor Jehova darbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Und er soll seine Hand auf den Kopf seines Opfers legen und es schlachten an dem Eingang des Zeltes der Zusammenkunft; und die Söhne Aarons, die Priester, sollen das Blut an den Altar sprengen ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Und er soll von dem Friedensopfer ein Feueropfer dem Jehova darbringen: das Fett, welches das Eingeweide bedeckt, und alles Fett, das am Eingeweide ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'und die beiden Nieren und das Fett, das an ihnen, das an den Lenden ist, und das Netz über der Leber: samt den Nieren soll er es abtrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Und die Söhne Aarons sollen es auf dem Altar räuchern, auf dem Brandopfer, welches auf dem Holze über dem Feuer ist: es ist ein Feueropfer lieblichen Geruchs dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Und wenn seine Opfergabe vom Kleinvieh ist zum Friedensopfer dem Jehova, ein Männliches oder ein Weibliches, so soll er sie ohne Fehl darbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Wenn er ein Schaf darbringt als seine Opfergabe, so soll er es vor Jehova herzubringen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'und er soll seine Hand auf den Kopf seines Opfers legen und es schlachten vor dem Zelte der Zusammenkunft; und die Söhne Aarons sollen sein Blut an den Altar sprengen ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Und er soll von dem Friedensopfer als Feueropfer dem Jehova darbringen: sein Fett, den ganzen Fettschwanz; dicht beim Rückgrat soll er ihn abtrennen; und das Fett, welches das Eingeweide bedeckt, und alles Fett, das am Eingeweide ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'und die beiden Nieren und das Fett, das an ihnen, das an den Lenden ist, und das Netz über der Leber: samt den Nieren soll er es abtrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Und der Priester soll es auf dem Altar räuchern: es ist eine Speise des Feueropfers dem Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Und wenn seine Opfergabe eine Ziege ist, so soll er sie vor Jehova herzubringen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'und er soll seine Hand auf ihren Kopf legen und sie schlachten vor dem Zelte der Zusammenkunft; und die Söhne Aarons sollen ihr Blut an den Altar sprengen ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Und er soll davon seine Opfergabe als Feueropfer dem Jehova darbringen: das Fett, welches das Eingeweide bedeckt, und alles Fett, das am Eingeweide ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'und die beiden Nieren und das Fett, das an ihnen, das an den Lenden ist, und das Netz über der Leber: samt den Nieren soll er es abtrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Und der Priester soll es auf dem Altar räuchern: es ist eine Speise des Feueropfers zum lieblichen Geruch; alles Fett gehört Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Eine ewige Satzung bei euren Geschlechtern in allen euren Wohnsitzen: alles Fett und alles Blut sollt ihr nicht essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Und Jehova redete zu Mose und sprach: Rede zu den Kindern Israel und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Wenn jemand aus Versehen sündigt gegen irgend eines der Verbote Jehovas, die nicht getan werden sollen, und irgend eines derselben tut, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'wenn der gesalbte Priester sündigt nach einem Vergehen des Volkes, so soll er für seine Sünde, die er begangen hat, einen jungen Farren ohne Fehl dem Jehova darbringen zum Sündopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Und er soll den Farren an den Eingang des Zeltes der Zusammenkunft vor Jehova bringen und seine Hand auf den Kopf des Farren legen und den Farren schlachten vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Und der gesalbte Priester nehme von dem Blute des Farren und bringe es in das Zelt der Zusammenkunft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'und der Priester tauche seinen Finger in das Blut und sprenge von dem Blute siebenmal vor Jehova gegen den Vorhang des Heiligtums hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Und der Priester tue von dem Blute an die Hörner des Altars des wohlriechenden Räucherwerks, der im Zelte der Zusammenkunft ist, vor Jehova; und alles Blut des Farren soll er an den Fuß des Brandopferaltars gießen, der an dem Eingang des Zeltes der Zusammenkunft ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Und alles Fett von dem Farren des Sündopfers soll er von ihm abheben: das Fett, welches das Eingeweide bedeckt, und alles Fett, das am Eingeweide ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'und die beiden Nieren und das Fett, das an ihnen, das an den Lenden ist, und das Netz über der Leber: samt den Nieren soll er es abtrennen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'so wie es abgehoben wird von dem Rinde des Friedensopfers; und der Priester soll es auf dem Brandopferaltar räuchern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Und die Haut des Farren und all sein Fleisch samt seinem Kopfe und seinen Schenkeln und seinem Eingeweide und seinem Mist:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'den ganzen Farren soll er hinausbringen außerhalb des Lagers an einen reinen Ort, nach dem Schutthaufen der Fettasche, und soll ihn auf Holzscheiten mit Feuer verbrennen; auf dem Schutthaufen der Fettasche soll er verbrannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Und wenn die ganze Gemeinde Israel aus Versehen sündigt und die Sache ist verborgen vor den Augen der Versammlung, und sie tun eines von allen Verboten Jehovas, die nicht getan werden sollen, und verschulden sich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'und die Sünde wird bekannt, die sie wider dasselbe begangen haben, so soll die Versammlung einen jungen Farren darbringen zum Sündopfer und ihn vor das Zelt der Zusammenkunft bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Und die Ältesten der Gemeinde sollen ihre Hände auf den Kopf des Farren legen vor Jehova, und man soll den Farren vor Jehova schlachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Und der gesalbte Priester bringe von dem Blute des Farren in das Zelt der Zusammenkunft,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'und der Priester tauche seinen Finger in das Blut und sprenge siebenmal vor Jehova gegen den Vorhang hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Und er tue von dem Blute an die Hörner des Altars, der vor Jehova, der im Zelte der Zusammenkunft ist; und alles Blut soll er an den Fuß des Brandopferaltars gießen, der an dem Eingang des Zeltes der Zusammenkunft ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Und all sein Fett soll er von ihm abheben und auf dem Altar räuchern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Und er soll mit dem Farren tun, wie er mit dem Farren des Sündopfers getan hat; also soll er damit tun. Und so tue der Priester Sühnung für sie, und es wird ihnen vergeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Und er soll den Farren hinausbringen außerhalb des Lagers und ihn verbrennen, so wie er den ersten Farren verbrannt hat: es ist ein Sündopfer der Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Wenn ein Fürst sündigt und tut aus Versehen eines von allen den Verboten Jehovas, seines Gottes, die nicht getan werden sollen, und verschuldet sich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'und seine Sünde wird ihm kundgetan, worin er gesündigt hat, so soll er seine Opfergabe bringen, einen Ziegenbock, ein Männlein ohne Fehl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Und er soll seine Hand auf den Kopf des Bockes legen und ihn schlachten an dem Orte, wo man das Brandopfer vor Jehova schlachtet: es ist ein Sündopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Und der Priester nehme von dem Blute des Sündopfers mit seinem Finger und tue es an die Hörner des Brandopferaltars; und sein Blut soll er an den Fuß des Brandopferaltars gießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Und all sein Fett soll er auf dem Altar räuchern, wie das Fett des Friedensopfers. Und so tue der Priester Sühnung für ihn wegen seiner Sünde, und es wird ihm vergeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Und wenn jemand vom Volke des Landes aus Versehen sündigt, indem er eines von den Verboten Jehovas tut, die nicht getan werden sollen, und sich verschuldet');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'und seine Sünde wird ihm kundgetan, die er begangen hat, so soll er seine Opfergabe bringen, eine Ziege ohne Fehl, ein Weiblein, für seine Sünde, die er begangen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Und er soll seine Hand auf den Kopf des Sündopfers legen und das Sündopfer schlachten an dem Orte des Brandopfers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Und der Priester nehme von seinem Blute mit seinem Finger und tue es an die Hörner des Brandopferaltars; und all sein Blut soll er an den Fuß des Altars gießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Und all sein Fett soll er abtrennen, so wie das Fett von dem Friedensopfer abgetrennt wird; und der Priester soll es auf dem Altar räuchern zum lieblichen Geruch dem Jehova. Und so tue der Priester Sühnung für ihn, und es wird ihm vergeben werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Und wenn er ein Schaf bringt als seine Opfergabe zum Sündopfer, so soll es ein Weiblein ohne Fehl sein, das er bringt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Und er soll seine Hand auf den Kopf des Sündopfers legen und es zum Sündopfer schlachten an dem Orte, wo man das Brandopfer schlachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Und der Priester nehme von dem Blute des Sündopfers mit seinem Finger und tue es an die Hörner des Brandopferaltars; und all sein Blut soll er an den Fuß des Altars gießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Und all sein Fett soll er abtrennen, so wie das Fett des Schafes von dem Friedensopfer abgetrennt wird; und der Priester soll es auf dem Altar räuchern, auf den Feueropfern Jehovas. Und so tue der Priester Sühnung für ihn wegen seiner Sünde, die er begangen hat, und es wird ihm vergeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Und wenn jemand sündigt, daß er die Stimme des Fluches hört, und er war Zeuge, sei es daß er es gesehen oder gewußt hat, wenn er es nicht anzeigt, so soll er seine Ungerechtigkeit tragen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'oder wenn jemand irgend etwas Unreines anrührt, sei es das Aas eines unreinen wilden Tieres, oder das Aas eines unreinen Viehes, oder das Aas eines unreinen kriechenden Tieres, ist es ihm auch verborgen, so ist er unrein und schuldig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'oder wenn er die Unreinigkeit eines Menschen anrührt, was für eine Unreinigkeit von ihm es auch sei, durch welche er unrein wird, und es ist ihm verborgen, erkennt er es, so ist er schuldig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'oder wenn jemand schwört, indem er unbesonnen mit den Lippen redet, Böses oder Gutes zu tun, nach allem was ein Mensch mit einem Schwur unbesonnen reden mag, und es ist ihm verborgen, erkennt er es, so ist er schuldig in einem von diesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Und es soll geschehen, wenn er sich in einem von diesen verschuldet, so bekenne er, worin er gesündigt hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'und er bringe sein Schuldopfer dem Jehova für seine Sünde, die er begangen hat: ein Weiblein vom Kleinvieh, ein Schaf oder eine Ziege zum Sündopfer; und der Priester soll Sühnung für ihn tun wegen seiner Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Und wenn seine Hand das zu einem Stück Kleinvieh Hinreichende nicht aufbringen kann, so soll er für seine Schuld, die er auf sich geladen hat, zwei Turteltauben oder zwei junge Tauben dem Jehova bringen: eine zum Sündopfer und eine zum Brandopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Und er soll sie zu dem Priester bringen; und dieser bringe die zum Sündopfer bestimmte zuerst dar und kneipe ihr den Kopf ein dicht beim Genick; er soll ihn aber nicht abtrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Und er sprenge von dem Blute des Sündopfers an die Wand des Altars, und das Übrige von dem Blute soll ausgedrückt werden an den Fuß des Altars: es ist ein Sündopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Und die andere soll er als Brandopfer opfern nach der Vorschrift. Und so tue der Priester Sühnung für ihn wegen seiner Sünde, die er begangen hat, und es wird ihm vergeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Und wenn seine Hand zwei Turteltauben oder zwei junge Tauben nicht aufbringen kann, so bringe der, welcher gesündigt hat, als seine Opfergabe ein Zehntel Epha Feinmehl zum Sündopfer; er soll kein Öl darauf tun und keinen Weihrauch darauf legen, denn es ist ein Sündopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Und er soll es zu dem Priester bringen; und der Priester nehme davon seine Hand voll, das Gedächtnisteil desselben, und räuchere es auf dem Altar, auf den Feueropfern Jehovas: es ist ein Sündopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Und so tue der Priester Sühnung für ihn wegen seiner Sünde, die er begangen hat in einem von diesen, und es wird ihm vergeben werden; und es soll dem Priester gehören wie das Speisopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Wenn jemand Untreue begeht und aus Versehen an den heiligen Dingen Jehovas sündigt, so soll er sein Schuldopfer dem Jehova bringen, einen Widder ohne Fehl vom Kleinvieh, nach deiner Schätzung an Sekeln Silber, nach den Sekel des Heiligtums, zum Schuldopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Und was er an dem Heiligen gesündigt hat, soll er erstatten und dessen Fünftel darüber hinzufügen und es dem Priester geben; und der Priester soll Sühnung für ihn tun mit dem Widder des Schuldopfers, und es wird ihm vergeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Und wenn jemand sündigt und eines von allen den Verboten Jehovas tut, die nicht getan werden sollen, hat er es auch nicht gewußt, so ist er schuldig und soll seine Ungerechtigkeit tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Und er soll einen Widder ohne Fehl vom Kleinvieh nach deiner Schätzung zu dem Priester bringen, zum Schuldopfer; und der Priester soll Sühnung für ihn tun wegen seines Versehens, das er begangen hat, ohne es zu wissen; und es wird ihm vergeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Es ist ein Schuldopfer; er hat sich gewißlich an Jehova verschuldet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, '(H5:20) Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '(H5:21) Wenn jemand sündigt und Untreue wider Jehova begeht, daß er seinem Nächsten ein anvertrautes Gut ableugnet oder ein Darlehn oder etwas Geraubtes; oder er hat von seinem Nächsten etwas erpreßt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, '(H5:22) oder er hat Verlorenes gefunden, und leugnet es ab; und er schwört falsch über irgend etwas von allem, was ein Mensch tun mag, sich darin zu versündigen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, '(H5:23) so soll es geschehen, wenn er gesündigt und sich verschuldet hat, daß er zurückerstatte das Geraubte, das er geraubt, oder das Erpreßte, das er erpreßt hat, oder das Anvertraute, das ihm anvertraut worden ist, oder das Verlorene, das er gefunden hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, '(H5:24) oder alles, worüber er falsch geschworen hat; und er soll es erstatten nach seiner vollen Summe und dessen Fünftel darüber hinzufügen; wem es gehört, dem soll er es geben am Tage seines Schuldopfers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, '(H5:25) Und sein Schuldopfer soll er Jehova bringen, einen Widder ohne Fehl vom Kleinvieh, nach deiner Schätzung, zum Schuldopfer, zu dem Priester;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, '(H5:26) und der Priester soll Sühnung für ihn tun vor Jehova, und es wird ihm vergeben werden wegen irgend etwas von allem, was er getan hat, sich darin zu verschulden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, '(H6:1) Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, '(H6:2) Gebiete Aaron und seinen Söhnen und sprich: Dies ist das Gesetz des Brandopfers. Dieses, das Brandopfer, soll auf seiner Feuerstelle sein, auf dem Altar, die ganze Nacht bis an den Morgen; und das Feuer des Altars soll auf demselben in Brand erhalten werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, '(H6:3) Und der Priester soll sein leinenes Kleid anziehen, und soll seine leinenen Beinkleider anziehen über sein Fleisch; und er soll die Fettasche abheben, zu welcher das Feuer das Brandopfer auf dem Altar verzehrt hat, und soll sie neben den Altar schütten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, '(H6:4) Und er soll seine Kleider ausziehen und andere Kleider anlegen und die Fettasche hinaustragen außerhalb des Lagers an einen reinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, '(H6:5) Und das Feuer auf dem Altar soll auf demselben in Brand erhalten werden, es soll nicht erlöschen; und der Priester soll Holz auf ihm anzünden, Morgen für Morgen, und das Brandopfer auf ihm zurichten, und die Fettstücke der Friedensopfer auf ihm räuchern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, '(H6:6) Ein beständiges Feuer soll auf dem Altar in Brand erhalten werden, es soll nicht erlöschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, '(H6:7) Und dies ist das Gesetz des Speisopfers: Einer der Söhne Aarons soll es vor Jehova darbringen vor dem Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, '(H6:8) Und er soll davon seine Hand voll nehmen, vom Feinmehl des Speisopfers und von dessen Öl, und allen Weihrauch, der auf dem Speisopfer ist, und es auf dem Altar räuchern: es ist ein lieblicher Geruch, sein Gedächtnisteil für Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, '(H6:9) Und das Übrige davon sollen Aaron und seine Söhne essen; ungesäuert soll es gegessen werden an heiligem Orte; im Vorhofe des Zeltes der Zusammenkunft sollen sie es essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, '(H6:10) Es soll nicht gesäuert gebacken werden; als ihren Anteil habe ich es ihnen gegeben von meinen Feueropfern: hochheilig ist es, wie das Sündopfer und wie das Schuldopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, '(H6:11) Alles Männliche unter den Kindern Aarons soll es essen: Ein für ewig Bestimmtes bei euren Geschlechtern von den Feueropfern Jehovas. Alles, was sie anrührt, wird heilig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, '(H6:12) Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, '(H6:13) Dies ist die Opfergabe Aarons und seiner Söhne, welche sie Jehova darbringen sollen an dem Tage, da er gesalbt wird: Ein Zehntel Epha Feinmehl als beständiges Speisopfer, die Hälfte davon am Morgen und die Hälfte davon am Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, '(H6:14) Es soll in der Pfanne mit Öl bereitet werden, eingerührt mit Öl sollst du es bringen; gebackene Speisopferstücke sollst du darbringen als einen lieblichen Geruch dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, '(H6:15) Und der Priester, der unter seinen Söhnen an seiner Statt gesalbt wird, soll es opfern; eine ewige Satzung: es soll dem Jehova ganz geräuchert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, '(H6:16) Und jedes Speisopfer des Priesters soll ein Ganzopfer sein; es soll nicht gegessen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, '(H6:17) Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, '(H6:18) Rede zu Aaron und zu seinen Söhnen und sprich: Dies ist das Gesetz des Sündopfers. An dem Orte, wo das Brandopfer geschlachtet wird, soll das Sündopfer geschlachtet werden vor Jehova: hochheilig ist es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, '(H6:19) Der Priester, der es als Sündopfer opfert, soll es essen; an heiligem Orte soll es gegessen werden, im Vorhofe des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, '(H6:20) Alles, was sein Fleisch anrührt, wird heilig sein; und wenn von seinem Blute auf ein Kleid spritzt das, worauf es spritzt, sollst du waschen an heiligem Orte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, '(H6:21) Und das irdene Gefäß, in welchem es gekocht wird, soll zerbrochen werden, und wenn es in einem ehernen Gefäß gekocht wird, so soll dieses gescheuert und mit Wasser gespült werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, '(H6:22) Alles Männliche unter den Priestern soll es essen: hochheilig ist es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, '(H6:23) Aber alles Sündopfer, von dessen Blut in das Zelt der Zusammenkunft gebracht wird, um im Heiligtum Sühnung zu tun, soll nicht gegessen werden; es soll mit Feuer verbrannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Und dies ist das Gesetz des Schuldopfers; es ist hochheilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'An dem Orte, wo man das Brandopfer schlachtet, soll man das Schuldopfer schlachten; und sein Blut soll er an den Altar sprengen ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Und alles Fett soll er davon darbringen, den Fettschwanz und das Fett, welches das Eingeweide bedeckt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'und die beiden Nieren und das Fett, das an ihnen, das an den Lenden ist, und das Netz über der Leber: samt den Nieren soll er es abtrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Und der Priester soll es auf dem Altar räuchern als ein Feueropfer dem Jehova: es ist ein Schuldopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Alles Männliche unter den Priestern soll es essen; an heiligem Orte soll es gegessen werden: hochheilig ist es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Wie das Sündopfer, so das Schuldopfer: ein Gesetz soll für sie sein. Der Priester, der damit Sühnung tut, ihm soll es gehören. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Und der Priester, der jemandes Brandopfer darbringt: ihm, dem Priester, soll die Haut des Brandopfers gehören, das er dargebracht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Und alles Speisopfer, das im Ofen gebacken, und alles, was im Napfe oder in der Pfanne bereitet wird: dem Priester, der es darbringt, ihm soll es gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Und alles Speisopfer, das mit Öl gemengt oder trocken ist, soll allen Söhnen Aarons gehören, dem einen wie dem anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Und dies ist das Gesetz des Friedensopfers, das man Jehova darbringt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Wenn man es zum Danke darbringt, so bringe man nebst dem Dankopfer ungesäuerte Kuchen dar, gemengt mit Öl, und ungesäuerte Fladen, gesalbt mit Öl, und Feinmehl, eingerührt mit Öl: Kuchen, gemengt mit Öl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Nebst den Kuchen soll man gesäuertes Brot als Opfergabe darbringen, nebst seinem Dankfriedensopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Und man soll je eines davon, von der ganzen Opfergabe, dem Jehova als Hebopfer darbringen; dem Priester, der das Blut des Friedensopfers sprengt, ihm soll es gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Und das Fleisch seines Dankfriedensopfers soll am Tage seiner Darbringung gegessen werden; er soll nichts davon liegen lassen bis an den Morgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Und wenn das Schlachtopfer seiner Opfergabe ein Gelübde oder eine freiwillige Gabe ist, so soll es an dem Tage, da er sein Schlachtopfer darbringt, gegessen werden; und am anderen Tage soll dann, was davon übrigbleibt, gegessen werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'und was vom Fleische des Schlachtopfers am dritten Tage übrigbleibt, soll mit Feuer verbrannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Und wenn irgendwie vom Fleische seines Friedensopfers am dritten Tage gegessen wird, so wird es nicht wohlgefällig sein; wer es dargebracht hat, dem wird es nicht zugerechnet werden: ein Greuel wird es sein; und die Seele, die davon isset, wird ihre Ungerechtigkeit tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Und das Fleisch, das irgend etwas Unreines berührt, soll nicht gegessen werden, mit Feuer soll es verbrannt werden. Und was das Fleisch betrifft, jeder Reine darf das Fleisch essen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'aber die Seele, welche Fleisch von dem Friedensopfer isset, das Jehova gehört, und ihre Unreinigkeit ist an ihr, selbige Seele soll ausgerottet werden aus ihren Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Und wenn eine Seele irgend etwas Unreines anrührt, die Unreinigkeit eines Menschen oder ein unreines Vieh oder irgend ein unreines Scheusal, und sie isset von dem Fleische des Friedensopfers, das Jehova gehört: selbige Seele soll ausgerottet werden aus ihren Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Rede zu den Kindern Israel und sprich: Kein Fett vom Rindvieh und von Schaf und Ziege sollt ihr essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Und das Fett vom Aas und das Fett vom Zerrissenen kann verwendet werden zu allerlei Werk; aber ihr sollt es durchaus nicht essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Denn jeder, der Fett isset vom Vieh, wovon man ein Feueropfer dem Jehova darbringt die Seele, die es isset, soll ausgerottet werden aus ihren Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Und kein Blut sollt ihr essen in allen euren Wohnsitzen, es sei vom Gevögel oder vom Vieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Jede Seele, die irgend Blut isset, selbige Seele soll ausgerottet werden aus ihren Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Rede zu den Kindern Israel und sprich: Wer sein Friedensopfer dem Jehova darbringt, soll von seinem Friedensopfer seine Opfergabe dem Jehova bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Seine Hände sollen die Feueropfer Jehovas bringen; das Fett, samt der Brust soll er es bringen: die Brust, um sie als Webopfer vor Jehova zu weben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Und der Priester soll das Fett auf dem Altar räuchern, und die Brust soll Aaron und seinen Söhnen gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Und den rechten Schenkel sollt ihr als Hebopfer von euren Friedensopfern dem Priester geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Wer von den Söhnen Aarons das Blut des Friedensopfers und das Fett darbringt, dem soll der rechte Schenkel zuteil werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Und die Brust des Webopfers und den Schenkel des Hebopfers habe ich von den Kindern Israel genommen, von ihren Friedensopfern, und habe sie Aaron, dem Priester, und seinen Söhnen gegeben als eine ewige Gebühr von seiten der Kinder Israel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Das ist das Salbungsteil Aarons und das Salbungsteil seiner Söhne von den Feueropfern Jehovas, an dem Tage, da man sie herzunahen ließ, um Jehova den Priesterdienst auszuüben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'das Jehova geboten hat, ihnen zu geben von seiten der Kinder Israel, an dem Tage, da man sie salbte: eine ewige Satzung bei ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Das ist das Gesetz des Brandopfers, des Speisopfers und des Sündopfers und des Schuldopfers und des Einweihungsopfers und des Friedensopfers,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'welches Jehova dem Mose geboten hat auf dem Berge Sinai, an dem Tage, da er den Kindern Israel gebot, ihre Opfergaben dem Jehova darzubringen, in der Wüste Sinai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Nimm Aaron und seine Söhne mit ihm, und die Kleider und das Salböl und den Farren des Sündopfers und die zwei Widder und den Korb des Ungesäuerten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'und versammle die ganze Gemeinde am Eingang des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Und Mose tat, so wie Jehova ihm geboten hatte; und die Gemeinde versammelte sich am Eingang des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Und Mose sprach zu der Gemeinde: Dies ist es, was Jehova zu tun geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Und Mose ließ Aaron und seine Söhne herzunahen und wusch sie mit Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Und er legte ihm den Leibrock an und umgürtete ihn mit dem Gürtel; und er bekleidete ihn mit dem Oberkleide und legte ihm das Ephod an und umgürtete ihn mit dem gewirkten Gürtel des Ephods und band es ihm damit an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'und er setzte das Brustschild darauf und legte in das Brustschild die Urim und die Thummim;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'und er setzte den Kopfbund auf sein Haupt und setzte an den Kopfbund, an seine Vorderseite, das Goldblech, das heilige Diadem: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Und Mose nahm das Salböl und salbte die Wohnung und alles, was darin war, und heiligte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Und er sprengte davon siebenmal auf den Altar, und er salbte den Altar und alle seine Geräte und das Becken und sein Gestell, um sie zu heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Und er goß von dem Salböl auf das Haupt Aarons und salbte ihn, um ihn zu heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Und Mose ließ die Söhne Aarons herzunahen und bekleidete sie mit den Leibröcken und umgürtete sie mit den Gürteln und band ihnen die hohen Mützen um: so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Und er brachte den Farren des Sündopfers herzu; und Aaron und seine Söhne legten ihre Hände auf den Kopf des Farren des Sündopfers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Und er schlachtete ihn, und Mose nahm das Blut und tat davon mit seinem Finger an die Hörner des Altars ringsum und entsündigte den Altar; und das Blut goß er an den Fuß des Altars und heiligte ihn, indem er Sühnung für ihn tat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Und er nahm das ganze Fett, das am Eingeweide ist, und das Netz der Leber und die beiden Nieren und ihr Fett, und Mose räucherte es auf dem Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Und den Farren und seine Haut und sein Fleisch und seinen Mist verbrannte er mit Feuer außerhalb des Lagers: so wie Jehova dem Mose geboten hatte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Und er brachte den Widder des Brandopfers herzu; und Aaron und seine Söhne legten ihre Hände auf den Kopf des Widders.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Und er schlachtete ihn, und Mose sprengte das Blut an den Altar ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Und den Widder zerlegte er in seine Stücke, und Mose räucherte den Kopf und die Stücke und das Fett;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'und das Eingeweide und die Schenkel wusch er mit Wasser. Und Mose räucherte den ganzen Widder auf dem Altar: es war ein Brandopfer zum lieblichen Geruch, es war ein Feueropfer dem Jehova, so wie Jehova dem Mose geboten hatte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Und er brachte den zweiten Widder, den Widder der Einweihung, herzu; und Aaron und seine Söhne legten ihre Hände auf den Kopf des Widders.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Und er schlachtete ihn, und Mose nahm von seinem Blute und tat es auf das rechte Ohrläppchen Aarons und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Und er ließ die Söhne Aarons herzunahen, und Mose tat von dem Blute auf ihr rechtes Ohrläppchen und auf den Daumen ihrer rechten Hand und auf die große Zehe ihres rechten Fußes; und Mose sprengte das Blut an den Altar ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Und er nahm das Fett und den Fettschwanz und alles Fett, das am Eingeweide ist, und das Netz der Leber und die beiden Nieren und ihr Fett und den rechten Schenkel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'und er nahm aus dem Korbe des Ungesäuerten, der vor Jehova war, einen ungesäuerten Kuchen und einen Kuchen geölten Brotes und einen Fladen, und legte es auf die Fettstücke und auf den rechten Schenkel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'und er legte das alles auf die Hände Aarons und auf die Hände seiner Söhne, und webte es als Webopfer vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Und Mose nahm es von ihren Händen weg und räucherte es auf dem Altar, auf dem Brandopfer: es war ein Einweihungsopfer zum lieblichen Geruch, es war ein Feueropfer dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Und Mose nahm die Brust und webte sie als Webopfer vor Jehova; von dem Einweihungswidder ward sie dem Mose zuteil, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Und Mose nahm von dem Salböl und von dem Blute, das auf dem Altar war, und sprengte es auf Aaron, auf seine Kleider, und auf seine Söhne und auf die Kleider seiner Söhne mit ihm; und er heiligte Aaron, seine Kleider, und seine Söhne und die Kleider seiner Söhne mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Und Mose sprach zu Aaron und zu seinen Söhnen: Kochet das Fleisch an dem Eingang des Zeltes der Zusammenkunft; und ihr sollt es daselbst essen und das Brot, das im Korbe des Einweihungsopfers ist, so wie ich geboten habe und gesagt: Aaron und seine Söhne sollen es essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Und das Übrige von dem Fleische und von dem Brote sollt ihr mit Feuer verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Und von dem Eingang des Zeltes der Zusammenkunft sollt ihr nicht weggehen sieben Tage lang, bis zu dem Tage, da die Tage eures Einweihungsopfers erfüllt sind; denn sieben Tage sollt ihr eingeweiht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'So wie man an diesem Tage getan, hat Jehova zu tun geboten, um Sühnung für euch zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Und ihr sollt an dem Eingang des Zeltes der Zusammenkunft Tag und Nacht bleiben, sieben Tage lang, und sollt die Vorschriften Jehovas beobachten, daß ihr nicht sterbet; denn also ist mir geboten worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Und Aaron und seine Söhne taten alles, was Jehova durch Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Und es geschah am achten Tage, da rief Mose Aaron und seine Söhne und die Ältesten Israels;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'und er sprach zu Aaron: Nimm dir ein junges Kalb zum Sündopfer und einen Widder zum Brandopfer, ohne Fehl, und bringe sie dar vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Und zu den Kindern Israel sollst du reden und sprechen: Nehmet einen Ziegenbock zum Sündopfer und ein Kalb und ein Lamm, einjährige, ohne Fehl, zum Brandopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'und einen Stier und einen Widder zum Friedensopfer, um sie vor Jehova zu opfern; und ein Speisopfer, gemengt mit Öl; denn heute wird Jehova euch erscheinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Und sie brachten was Mose geboten hatte, vor das Zelt der Zusammenkunft, und die ganze Gemeinde nahte herzu und stand vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Und Mose sprach: Dies ist es, was Jehova geboten hat, daß ihr es tun sollt; und die Herrlichkeit Jehovas wird euch erscheinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Und Mose sprach zu Aaron: Nahe zum Altar, und opfere dein Sündopfer und dein Brandopfer, und tue Sühnung für dich und für das Volk; und opfere die Opfergabe des Volkes und tue Sühnung für sie, so wie Jehova geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Und Aaron nahte zum Altar und schlachtete das Kalb des Sündopfers, das für ihn war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Und die Söhne Aarons reichten ihm das Blut dar; und er tauchte seinen Finger in das Blut und tat davon an die Hörner des Altars, und er goß das Blut an den Fuß des Altars.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Und das Fett und die Nieren und das Netz der Leber vom Sündopfer räucherte er auf dem Altar, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Und das Fleisch und die Haut verbrannte er mit Feuer außerhalb des Lagers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Und er schlachtete das Brandopfer; und die Söhne Aarons reichten ihm das Blut, und er sprengte es an den Altar ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Und das Brandopfer reichten sie ihm in seinen Stücken und den Kopf, und er räucherte es auf dem Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Und er wusch das Eingeweide und die Schenkel und räucherte sie auf dem Brandopfer, auf dem Altar. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Und er brachte herzu die Opfergabe des Volkes und nahm den Bock des Sündopfers, der für das Volk war, und schlachtete ihn und opferte ihn als Sündopfer, wie das vorige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Und er brachte das Brandopfer herzu und opferte es nach der Vorschrift.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Und er brachte das Speisopfer herzu und füllte seine Hand davon und räucherte es auf dem Altar, außer dem Morgenbrandopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Und er schlachtete den Stier und den Widder, das Friedensopfer, welches für das Volk war. Und die Söhne Aarons reichten ihm das Blut, und er sprengte es an den Altar ringsum;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'und die Fettstücke von dem Stier; und von dem Widder den Fettschwanz, und das Eingeweide bedeckt und die Nieren und das Netz der Leber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'und sie legten die Fettstücke auf die Bruststücke, und er räucherte die Fettstücke auf dem Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Und die Bruststücke und den rechten Schenkel webte Aaron als Webopfer vor Jehova, so wie Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Und Aaron erhob seine Hände gegen das Volk und segnete sie; und er stieg herab nach der Opferung des Sündopfers und des Brandopfers und des Friedensopfers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Und Mose und Aaron gingen hinein in das Zelt der Zusammenkunft; und sie kamen heraus und segneten das Volk. Und die Herrlichkeit Jehovas erschien dem ganzen Volke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'und es ging Feuer aus von Jehova und verzehrte auf dem Altar das Brandopfer und die Fettstücke; und das ganze Volk sah es, und sie jauchzten und fielen auf ihr Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Und die Söhne Aarons, Nadab und Abihu, nahmen ein jeder seine Räucherpfanne und taten Feuer hinein und legten Räucherwerk darauf und brachten fremdes Feuer vor Jehova dar, das er ihnen nicht geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Da ging Feuer von Jehova aus und verzehrte sie, und sie starben vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Und Mose sprach zu Aaron: Dies ist es, was Jehova geredet hat, indem er sprach: In denen, die mir nahen, will ich geheiligt, und vor dem ganzen Volke will ich verherrlicht werden. Und Aaron schwieg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Und Mose rief Misael und Elzaphan, die Söhne Ussiels, des Oheims Aarons, und sprach zu ihnen: Tretet herzu, traget eure Brüder von dem Heiligtum hinweg außerhalb des Lagers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Und sie traten herzu und trugen sie in ihren Leibröcken hinweg außerhalb des Lagers, so wie Mose geredet hatte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Und Mose sprach zu Aaron und zu Eleasar und zu Ithamar, seinen Söhnen: Eure Häupter sollt ihr nicht entblößen und eure Kleider nicht zerreißen, damit ihr nicht sterbet, und er nicht erzürne über die ganze Gemeinde; aber eure Brüder, das ganze Haus Israel, sollen diesen Brand beweinen, den Jehova angerichtet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Und von dem Eingang des Zeltes der Zusammenkunft sollt ihr nicht weggehen, daß ihr nicht sterbet; denn das Öl der Salbung Jehovas ist auf euch. Und sie taten nach dem Worte Moses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Und Jehova redete zu Aaron und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Wein und starkes Getränk sollst du nicht trinken, du und deine Söhne mit dir, wenn ihr in das Zelt der Zusammenkunft hineingehet, daß ihr nicht sterbet, eine ewige Satzung bei euren Geschlechtern-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'und damit ihr unterscheidet zwischen dem Heiligen und dem Unheiligen und zwischen dem Reinen und dem Unreinen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'und damit ihr die Kinder Israel lehret alle die Satzungen, die Jehova durch Mose zu euch geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Und Mose redete zu Aaron und zu Eleasar und zu Ithamar, seinen Söhnen, den übriggebliebenen: Nehmet das Speisopfer, das von den Feueropfern Jehovas übrigbleibt, und esset es ungesäuert neben dem Altar; denn hochheilig ist es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Und ihr sollt es essen an heiligem Orte, denn es ist dein Bestimmtes und das Bestimmte deiner Söhne von den Feueropfern Jehovas; denn also ist mir geboten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Und die Brust des Webopfers und den Schenkel des Hebopfers sollt ihr essen an reinem Orte, du und deine Söhne und deine Töchter mit dir; denn als dein Bestimmtes und das Bestimmte deiner Söhne sind sie gegeben von den Friedensopfern der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Den Schenkel des Hebopfers und die Brust des Webopfers sollen sie nebst den Feueropfern der Fettstücke bringen, um sie als Webopfer vor Jehova zu weben; und sie sollen dir gehören und deinen Söhnen mit dir, als eine ewige Gebühr, so wie Jehova geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Und Mose suchte eifrig den Bock des Sündopfers, und siehe, er war verbrannt. Und er erzürnte über Eleasar und über Ithamar, die Söhne Aarons, die übriggeblieben, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Warum habt ihr nicht das Sündopfer an heiligem Orte gegessen? Denn es ist hochheilig; und er hat es euch gegeben, um die Ungerechtigkeit der Gemeinde zu tragen, um Sühnung für sie zu tun vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Siehe, das Blut desselben ist nicht in das Innere des Heiligtums gebracht worden; ihr sollt es jedenfalls im Heiligtum essen, so wie ich geboten habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Und Aaron redete zu Mose: Siehe, heute haben sie ihr Sündopfer und ihr Brandopfer vor Jehova dargebracht; und solches ist mir begegnet; und hätte ich heute das Sündopfer gegessen, würde es gut gewesen sein in den Augen Jehovas?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Und Mose hörte es, und es war gut in seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Und Jehova redete zu Mose und zu Aaron und sprach zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Redet zu den Kindern Israel und sprechet: Dies sind die Tiere, die ihr essen sollt von allen Tieren, die auf der Erde sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Alles, was gespaltene Hufe, und zwar ganz gespaltene Hufe hat, und wiederkäut unter den Tieren, das sollt ihr essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Nur diese sollt ihr nicht essen von den wiederkäuenden und von denen, die gespaltene Hufe haben: das Kamel, denn es wiederkäut, aber es hat keine gespaltenen Hufe: unrein soll es euch sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'und den Klippendachs, denn er wiederkäut, aber er hat keine gespaltenen Hufe: unrein soll er euch sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'und den Hasen, denn er wiederkäut, aber er hat keine gespaltenen Hufe: unrein soll er euch sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'und das Schwein, denn es hat gespaltene Hufe, und zwar ganz gespaltene Hufe, aber es wiederkäut nicht: unrein soll es euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Von ihrem Fleische sollt ihr nicht essen und ihr Aas nicht anrühren: unrein sollen sie euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Dieses sollt ihr essen von allem, was in den Wassern ist: alles, was Floßfedern und Schuppen hat in den Wassern, in den Meeren und in den Flüssen, das sollt ihr essen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'aber alles, was keine Floßfedern und Schuppen hat in den Meeren und in den Flüssen, von allem Gewimmel der Wasser und von jedem lebendigen Wesen, das in den Wassern ist, sie sollen euch ein Greuel sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'ja, ein Greuel sollen sie euch sein: von ihrem Fleische sollt ihr nicht essen, und ihr Aas sollt ihr verabscheuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Alles, was nicht Floßfedern und Schuppen hat in den Wassern, soll euch ein Greuel sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Und diese sollt ihr verabscheuen von den Vögeln; sie sollen nicht gegessen werden, ein Greuel sind sie: den Adler und den Beinbrecher und den Meeradler,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'und den Falken und die Weihe nach ihrer Art,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'alle Raben nach ihrer Art,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'und die Straußhenne und den Straußhahn und die Seemöve und den Habicht nach seiner Art,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'und die Eule und den Sturzpelikan und die Rohrdommel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'und das Purpurhuhn und den Pelikan und den Aasgeier,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'und den Storch und den Fischreiher nach seiner Art, und den Wiedehopf und die Fledermaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Alles geflügelte Gewürm, das auf Vieren geht, soll euch ein Greuel sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Nur dieses sollt ihr essen von allem geflügelten Gewürm, das auf Vieren geht: was Schenkel hat oberhalb seiner Füße, um damit auf der Erde zu hüpfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Diese sollt ihr von ihnen essen: den Arbeh nach seiner Art und den Solham nach seiner Art und den Chargol nach seiner Art und den Chagab nach seiner Art.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Aber alles geflügelte Gewürm, das vier Füße hat, soll euch ein Greuel sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Und durch diese werdet ihr euch verunreinigen; jeder, der ihr Aas anrührt, wird unrein sein bis an den Abend;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'und jeder, der von ihrem Aase trägt, soll seine Kleider waschen und wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Jedes Tier, das gespaltene Hufe, aber nicht ganz gespaltene Hufe hat und nicht wiederkäut: Unrein sollen sie euch sein; jeder, der sie anrührt, wird unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Und alles, was auf seinen Tatzen geht, unter allem Getier, das auf Vieren geht, sie sollen euch unrein sein; jeder, der ihr Aas anrührt, wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Und wer ihr Aas trägt, soll seine Kleider waschen und wird unrein sein bis an den Abend; sie sollen euch unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Und diese sollen euch unrein sein unter dem Gewimmel, das auf der Erde wimmelt: der Maulwurf und die Maus und die Eidechse nach ihrer Art,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'und die Anaka und der Koach und der Letaah und der Chomet und das Chamäleon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Diese sollen euch unrein sein unter allem Gewimmel; jeder, der sie anrührt, wenn sie tot sind, wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Und alles, worauf eines von ihnen fällt, wenn sie tot sind, wird unrein sein: jedes Holzgerät oder Kleid oder Fell oder Sack, jedes Gerät, womit eine Arbeit verrichtet wird, es soll ins Wasser getan werden und wird unrein sein bis an den Abend; dann wird es rein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Und jedes irdene Gefäß, in welches eines von ihnen hineinfällt: alles, was darin ist, wird unrein sein, und es selbst sollt ihr zerbrechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Alle Speise, die gegessen wird, auf welche solches Wasser kommt, wird unrein sein; und alles Getränk, das getrunken wird, wird unrein sein in jedem solchen Gefäße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Und alles, worauf von ihrem Aase fällt, wird unrein sein; Ofen und Herd sollen niedergerissen werden, sie sind unrein, und unrein sollen sie euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Doch Quelle und Zisterne, Wasserbehälter, werden rein sein; wer aber das Aas darin anrührt, wird unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Und wenn von ihrem Aase auf irgend welchen Saatsamen fällt, der gesät wird, so ist er rein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'wenn aber Wasser auf den Samen getan wurde, und es fällt von ihrem Aase auf denselben, so soll er euch unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Und wenn eines von dem Vieh stirbt, das euch zur Nahrung dient: wer dessen Aas anrührt, wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Und wer von dessen Aas isset, soll seine Kleider waschen und wird unrein sein bis an den Abend; und wer dessen Aas trägt, soll seine Kleider waschen und wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Und alles Gewimmel, das auf der Erde wimmelt, ist ein Greuel; es soll nicht gegessen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Alles was auf dem Bauche kriecht, und alles, was auf Vieren geht, bis zu allem Vielfüßigen von allem Gewimmel, das auf der Erde wimmelt: ihr sollt sie nicht essen; denn sie sind ein Greuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Machet euch selbst nicht zum Greuel durch irgend ein kriechendes Gewürm, und verunreiniget euch nicht durch sie, so daß ihr dadurch unrein werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Denn ich bin Jehova, euer Gott; so heiliget euch und seid heilig, denn ich bin heilig. Und ihr sollt euch selbst nicht verunreinigen durch irgend ein Gewürm, das sich auf der Erde regt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Denn ich bin Jehova, der euch aus dem Lande Ägypten heraufgeführt hat, um euer Gott zu sein: so seid heilig, denn ich bin heilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Das ist das Gesetz von dem Vieh und dem Gevögel und von jedem lebendigen Wesen, das sich in den Wassern regt, und von jedem Wesen, das auf der Erde kriecht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'um zu unterscheiden zwischen dem Unreinen und dem Reinen, und zwischen dem Getier, das gegessen wird, und dem Getier, das nicht gegessen werden soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Rede zu den Kindern Israel und sprich: Wenn ein Weib empfängt und ein männliches Kind gebiert, so wird sie unrein sein sieben Tage; wie in den Tagen der Unreinheit ihrer Krankheit wird sie unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Und am achten Tage soll das Fleisch seiner Vorhaut beschnitten werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Und sie soll dreiunddreißig Tage im Blute der Reinigung bleiben; nichts Heiliges soll sie anrühren, und zum Heiligtum soll sie nicht kommen, bis die Tage ihrer Reinigung erfüllt sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Und wenn sie ein weibliches Kind gebiert, so wird sie zwei Wochen unrein sein, wie bei ihrer Unreinheit; und sechsundsechzig Tage soll sie im Blute der Reinigung daheim bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Und wenn die Tage ihrer Reinigung erfüllt sind für einen Sohn oder für eine Tochter, so soll sie ein einjähriges Lamm bringen zum Brandopfer, und eine junge Taube oder eine Turteltaube zum Sündopfer an den Eingang des Zeltes der Zusammenkunft zu dem Priester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Und er soll es vor Jehova darbringen und Sühnung für sie tun, und sie wird rein sein von dem Flusse ihres Blutes. Das ist das Gesetz der Gebärenden bei einem männlichen oder bei einem weiblichen Kinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Und wenn ihre Hand das zu einem Schafe Hinreichende nicht aufbringen kann, so soll sie zwei Turteltauben oder zwei junge Tauben nehmen, eine zum Brandopfer und eine zum Sündopfer; und der Priester soll Sühnung für sie tun, und sie wird rein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Und Jehova redete zu Mose und zu Aaron und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Wenn ein Mensch in der Haut seines Fleisches eine Erhöhung oder einen Grind oder einen Flecken bekommt, und es wird in der Haut seines Fleisches zu einem Aussatzübel, so soll er zu Aaron, dem Priester, gebracht werden, oder zu einem von seinen Söhnen, den Priestern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Und besieht der Priester das Übel in der Haut des Fleisches, und das Haar in dem Übel hat sich in weiß verwandelt, und das Übel erscheint tiefer als die Haut seines Fleisches, so ist es das Übel des Aussatzes; und sieht es der Priester, so soll er ihn für unrein erklären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Und wenn der Flecken in der Haut seines Fleisches weiß ist, und er nicht tiefer erscheint als die Haut, und sein Haar hat sich nicht in weiß verwandelt, so soll der Priester den, der das Übel hat, sieben Tage einschließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Und besieht es der Priester am siebten Tage, und siehe, das Übel ist in seinen Augen stehen geblieben, das Übel hat nicht um sich gegriffen in der Haut, so soll der Priester ihn zum zweiten Male sieben Tage einschließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Und besieht es der Priester am siebten Tage zum zweiten Male, und siehe, das Übel ist blaß geworden, und das Übel hat nicht um sich gegriffen in der Haut, so soll der Priester ihn für rein erklären: es ist ein Grind; und er soll seine Kleider waschen, und er ist rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Wenn aber der Grind in der Haut um sich greift, nachdem er sich dem Priester gezeigt hat zu seiner Reinigung, so soll er sich dem Priester zum zweiten Male zeigen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'und besieht ihn der Priester, und siehe, der Grind hat in der Haut um sich gegriffen, so soll der Priester ihn für unrein erklären: es ist der Aussatz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Wenn ein Aussatzübel an einem Menschen entsteht, so soll er zu dem Priester gebracht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Und besieht ihn der Priester, und siehe, es ist eine weiße Erhöhung in der Haut, und sie hat das Haar in weiß verwandelt, und ein Mal rohen Fleisches ist in der Erhöhung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'so ist es ein alter Aussatz in der Haut seines Fleisches, und der Priester soll ihn für unrein erklären; er soll ihn nicht einschließen, denn er ist unrein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Wenn aber der Aussatz in der Haut ausbricht, und der Aussatz die ganze Haut dessen, der das Übel hat, bedeckt, von seinem Kopfe bis zu seinen Füßen, wohin auch die Augen des Priesters blicken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'und der Priester besieht ihn, und siehe, der Aussatz hat sein ganzes Fleisch bedeckt, so soll er den, der das Übel hat, für rein erklären; hat es sich ganz in weiß verwandelt, so ist er rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'An dem Tage aber, da rohes Fleisch an ihm gesehen wird, wird er unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Und sieht der Priester das rohe Fleisch, so soll er ihn für unrein erklären; das rohe Fleisch ist unrein: es ist der Aussatz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Wenn aber das rohe Fleisch sich ändert und in weiß verwandelt wird, so soll er zu dem Priester kommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'und besieht ihn der Priester, und siehe, das Übel ist in weiß verwandelt, so soll der Priester den, der das Übel hat, für rein erklären: er ist rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Und wenn im Fleische, in dessen Haut, eine Beule entsteht und wieder heilt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'und es entsteht an der Stelle der Beule eine weiße Erhöhung oder ein weiß-rötlicher Flecken, so soll er sich dem Priester zeigen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'und besieht ihn der Priester, und siehe, der Flecken erscheint niedriger als die Haut, und sein Haar hat sich in weiß verwandelt, so soll der Priester ihn für unrein erklären; es ist das Übel des Aussatzes, er ist in der Beule ausgebrochen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Und wenn der Priester ihn besieht, und siehe, es ist kein weißes Haar darin, und der Flecken ist nicht niedriger als die Haut und ist blaß, so soll der Priester ihn sieben Tage einschließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Wenn er aber in der Haut um sich greift, so soll der Priester ihn für unrein erklären: es ist das Übel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Und wenn der Flecken an seiner Stelle stehen bleibt, wenn er nicht um sich gegriffen hat, so ist es die Narbe der Beule; und der Priester soll ihn für rein erklären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Oder wenn in der Haut des Fleisches eine feurige Entzündung entsteht, und das Mal der Entzündung wird ein weiß-rötlicher oder weißer Flecken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'und der Priester besieht ihn, und siehe, das Haar ist in weiß verwandelt in dem Flecken, und er erscheint tiefer als die Haut, so ist es der Aussatz; er ist in der Entzündung ausgebrochen, und der Priester soll ihn für unrein erklären: es ist das Übel des Aussatzes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Und wenn der Priester ihn besieht, und siehe, es ist kein weißes Haar in dem Flecken, und er ist nicht niedriger als die Haut und ist blaß, so soll der Priester ihn sieben Tage einschließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Und der Priester soll ihn am siebten Tage besehen; wenn er in der Haut um sich greift, so soll der Priester ihn für unrein erklären: es ist das Übel des Aussatzes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Und wenn der Flecken an seiner Stelle stehen bleibt, wenn er nicht um sich gegriffen hat in der Haut und ist blaß, so ist es die Erhöhung der Entzündung; und der Priester soll ihn für rein erklären, denn es ist die Narbe der Entzündung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Und wenn ein Mann oder ein Weib ein Übel am Haupte oder am Barte bekommt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'und der Priester besieht das Übel, und siehe, es erscheint tiefer als die Haut, und goldgelbes, dünnes Haar ist darin, so soll der Priester ihn für unrein erklären: es ist Schorf, es ist der Aussatz des Hauptes oder des Bartes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Und wenn der Priester das Übel des Schorfes besieht, und siehe, es erscheint nicht tiefer als die Haut, und es ist kein schwarzes Haar darin, so soll der Priester den, der das Übel des Schorfes hat, sieben Tage einschließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Und besieht der Priester das Übel am siebten Tage, und siehe, der Schorf hat nicht um sich gegriffen, und es ist kein goldgelbes Haar darin, und der Schorf erscheint nicht tiefer als die Haut,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'so soll er sich scheren; aber den Schorf soll er nicht scheren; und der Priester schließe den, der den Schorf hat, zum zweiten Male sieben Tage ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Und besieht der Priester den Schorf am siebten Tage, und siehe, der Schorf hat nicht um sich gegriffen in der Haut, und er erscheint nicht tiefer als die Haut, so soll der Priester ihn für rein erklären; und er soll seine Kleider waschen, und er ist rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Wenn aber, nach seiner Reinigung, der Schorf in der Haut um sich greift,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'und der Priester besieht ihn, und siehe, der Schorf hat in der Haut um sich gegriffen, so soll der Priester nicht nach dem goldgelben Haare forschen; er ist unrein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Und wenn in seinen Augen der Schorf stehen geblieben ist, und es ist schwarzes Haar darin gewachsen, so ist der Schorf geheilt; er ist rein, und der Priester soll ihn für rein erklären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Und wenn ein Mann oder ein Weib in der Haut ihres Fleisches Flecken bekommen, weiße Flecken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'und der Priester besieht sie, und siehe, in der Haut ihres Fleisches sind blasse, weiße Flecken, so ist es ein Ausschlag, der in der Haut ausgebrochen ist: er ist rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Und wenn einem Manne das Haupthaar ausfällt, so ist er ein Glatzkopf: er ist rein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'und wenn ihm das Haupthaar gegen das Gesicht zu ausfällt, so ist er ein Kahlkopf: er ist rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Und wenn an der Hinter-oder an der Vorderglatze ein weiß-rötliches Übel ist, so ist es der Aussatz, der an seiner Hinter-oder an seiner Vorderglatze ausgebrochen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Und besieht ihn der Priester, und siehe, die Erhöhung des Übels ist weiß-rötlich an seiner Hinter-oder an seiner Vorderglatze, gleich dem Aussehen des Aussatzes in der Haut des Fleisches,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'so ist er ein aussätziger Mann: Er ist unrein; der Priester soll ihn für gänzlich unrein erklären; sein Übel ist an seinem Haupte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Und der Aussätzige, an dem das Übel ist, seine Kleider sollen zerrissen, und sein Haupt soll entblößt sein, und er soll seinen Bart verhüllen und ausrufen: Unrein, unrein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Alle die Tage, da das Übel an ihm ist, soll er unrein sein; er ist unrein: allein soll er wohnen, außerhalb des Lagers soll seine Wohnung sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Und wenn an einem Kleide ein Aussatzübel entsteht, an einem Kleide von Wolle oder an einem Kleide von Linnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'oder an einer Kette oder an einem Einschlag von Linnen oder von Wolle; oder an einem Felle oder an irgend einem Fellwerk;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'und das Übel ist grünlich oder rötlich am Kleide, oder am Felle, oder an der Kette oder am Einschlag, oder an irgend einem Gerät von Fell, so ist es das Übel des Aussatzes, und man soll es den Priester besehen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Und der Priester besehe das Übel und schließe das, woran das Übel ist, sieben Tage ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Und sieht er das Übel am siebten Tage, daß das Übel um sich gegriffen hat am Kleide, oder an der Kette oder am Einschlag, oder am Felle nach allem, wozu das Fell verarbeitet wird, so ist das Übel ein fressender Aussatz: es ist unrein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Und man soll das Kleid, oder die Kette oder den Einschlag von Wolle oder von Linnen, oder jedes Gerät von Fell, woran das Übel ist, verbrennen; denn es ist ein fressender Aussatz: es soll mit Feuer verbrannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Und wenn der Priester es besieht, und siehe, das Übel hat nicht um sich gegriffen am Kleide, oder an der Kette oder am Einschlag, oder an irgend einem Gerät von Fell,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'so soll der Priester gebieten, daß man das wasche, woran das Übel ist; und er soll es zum zweiten Male sieben Tage einschließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Und besieht der Priester das Übel nach dem Waschen, und siehe, das Übel hat sein Aussehen nicht geändert, und das Übel hat nicht um sich gegriffen, so ist es unrein; du sollst es mit Feuer verbrennen: es ist eine Vertiefung auf seiner kahlen Hinter-oder Vorderseite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Und wenn der Priester es besieht, und siehe, das Übel ist blaß geworden nach dem Waschen, so soll er es abreißen vom Kleide, oder vom Felle, oder von der Kette oder vom Einschlag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Und wenn es noch gesehen wird am Kleide, oder an der Kette oder am Einschlag, oder an irgend einem Gerät von Fell, so ist es ein ausbrechender Aussatz: du sollst mit Feuer verbrennen, woran das Übel ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Und das Kleid, oder die Kette oder der Einschlag, oder irgend ein Gerät von Fell, das du wäschest, und das Übel weicht daraus: es soll zum zweiten Male gewaschen werden, und es ist rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Das ist das Gesetz des Aussatzübels an einem Kleide von Wolle oder von Linnen, oder an einer Kette oder an einem Einschlag, oder an irgend einem Gerät von Fell, um es für rein oder für unrein zu erklären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Dies soll das Gesetz des Aussätzigen sein am Tage seiner Reinigung: Er soll zu dem Priester gebracht werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'und der Priester soll außerhalb des Lagers gehen; und besieht ihn der Priester, und siehe, das Übel des Aussatzes ist heil geworden an dem Aussätzigen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'so soll der Priester gebieten, daß man für den, der zu reinigen ist, zwei lebendige, reine Vögel nehme und Cedernholz und Karmesin und Ysop.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Und der Priester soll gebieten, daß man den einen Vogel schlachte in ein irdenes Gefäß über lebendigem Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Den lebendigen Vogel soll er nehmen, ihn und das Cedernholz und das Karmesin und den Ysop, und dieses und den lebendigen Vogel in das Blut des Vogels tauchen, der geschlachtet worden ist über dem lebendigen Wasser;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'und er soll auf den, der vom Aussatze zu reinigen ist, siebenmal sprengen und ihn für rein erklären; und den lebendigen Vogel soll er ins freie Feld fliegen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Und der zu reinigen ist, soll seine Kleider waschen und all sein Haar scheren und sich im Wasser baden; und er ist rein. Und danach darf er ins Lager kommen, aber er soll sieben Tage außerhalb seines Zeltes bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Und es soll geschehen, am siebten Tage soll er all sein Haar scheren, sein Haupt und seinen Bart und seine Augenbrauen; ja, all sein Haar soll er scheren und seine Kleider waschen und sein Fleisch im Wasser baden; und er ist rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Und am achten Tage soll er zwei Lämmer nehmen, ohne Fehl, und ein weibliches Lamm, einjährig, ohne Fehl, und drei Zehntel Feinmehl, gemengt mit Öl, zum Speisopfer, und ein Log Öl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Und der reinigende Priester soll den Mann, der zu reinigen ist, und diese Dinge vor Jehova stellen an den Eingang des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Und der Priester nehme das eine Lamm und bringe es zum Schuldopfer dar mit dem Log Öl und webe sie als Webopfer vor Jehova;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Und er schlachte das Lamm an dem Orte, wo man das Sündopfer und das Brandopfer schlachtet, an heiligem Orte; denn wie das Sündopfer, so gehört das Schuldopfer dem Priester: es ist hochheilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Und der Priester nehme von dem Blute des Schuldopfers, und der Priester tue es auf das rechte Ohrläppchen dessen, der zu reinigen ist, und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Und der Priester nehme von dem Log Öl und gieße es in seine linke Hand;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'und der Priester tauche seinen rechten Finger in das Öl, das in seiner linken Hand ist, und sprenge von dem Öle mit seinem Finger siebenmal vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Und von dem Übrigen des Öles, das in seiner Hand ist, soll der Priester auf das rechte Ohrläppchen dessen tun, der zu reinigen ist, und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes, auf das Blut des Schuldopfers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Und das Übrige des Öles, das in der Hand des Priesters ist, soll er auf das Haupt dessen tun, der zu reinigen ist; und der Priester soll Sühnung für ihn tun vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Und der Priester soll das Sündopfer opfern und Sühnung tun für den, der von seiner Unreinheit zu reinigen ist; und danach soll er das Brandopfer schlachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Und der Priester soll das Brandopfer und das Speisopfer auf dem Altar opfern. Und so tue der Priester Sühnung für ihn; und er ist rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Und wenn er arm ist und seine Hand es nicht aufbringen kann, so soll er ein Lamm als Schuldopfer nehmen zum Webopfer, um Sühnung für ihn zu tun; und ein Zehntel Feinmehl, gemengt mit Öl, zum Speisopfer, und ein Log Öl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'und zwei Turteltauben oder zwei junge Tauben, die seine Hand aufbringen kann; und die eine soll ein Sündopfer und die andere ein Brandopfer sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Und er soll sie am achten Tage seiner Reinigung zu dem Priester bringen an den Eingang des Zeltes der Zusammenkunft vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Und der Priester nehme das Lamm des Schuldopfers und das Log Öl, und der Priester webe sie als Webopfer vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Und er schlachte das Lamm des Schuldopfers; und der Priester nehme von dem Blute des Schuldopfers und tue es auf das rechte Ohrläppchen dessen, der zu reinigen ist, und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Und der Priester gieße von dem Öle in seine linke Hand;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'und der Priester sprenge mit seinem rechten Finger von dem Öle, das in seiner linken Hand ist, siebenmal vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Und der Priester tue von dem Öle, das in seiner Hand ist, auf das rechte Ohrläppchen dessen, der zu reinigen ist, und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes, auf die Stelle des Blutes des Schuldopfers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Und das Übrige des Öles, das in der Hand des Priesters ist, soll er auf das Haupt dessen tun, der zu reinigen ist, um Sühnung für ihn zu tun vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Und er soll die eine von den Turteltauben oder von den jungen Tauben opfern, von dem, was seine Hand aufbringen kann, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'das, was seine Hand aufbringen kann: Die eine als Sündopfer und die andere als Brandopfer, nebst dem Speisopfer. Und so tue der Priester Sühnung vor Jehova für den, der zu reinigen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Das ist das Gesetz für den, an welchem das Übel des Aussatzes ist, dessen Hand bei seiner Reinigung nicht aufbringen kann, was vorgeschrieben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Und Jehova redete zu Mose und zu Aaron und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Wenn ihr in das Land Kanaan kommet, das ich euch zum Eigentum gebe, und ich ein Aussatzübel an ein Haus setze im Lande eures Eigentums,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'so soll der, dem das Haus gehört, kommen und es dem Priester anzeigen und sprechen: Es sieht mir aus wie ein Übel am Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Und der Priester soll gebieten, daß man das Haus ausräume, ehe der Priester hineingeht, das Übel zu besehen, damit nicht unrein werde alles, was im Hause ist; und danach soll der Priester hineingehen, das Haus zu besehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Und besieht er das Übel, und siehe, das Übel ist an den Wänden des Hauses, grünliche oder rötliche Vertiefungen, und sie erscheinen tiefer als die Wand,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'so soll der Priester aus dem Hause hinaus an den Eingang des Hauses gehen und das Haus sieben Tage verschließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Und der Priester soll am siebten Tage wiederkommen; und besieht er es, und siehe, das Übel hat um sich gegriffen an den Wänden des Hauses,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'so soll der Priester gebieten, daß man die Steine, an denen das Übel ist, herausreiße, und sie hinauswerfe außerhalb der Stadt an einen unreinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Und das Haus soll man inwendig ringsum abkratzen, und den Lehm, den man abgekratzt hat, hinausschütten außerhalb der Stadt an einen unreinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Und man soll andere Steine nehmen und sie an die Stelle der Steine bringen, und man soll anderen Lehm nehmen und das Haus bewerfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Und wenn das Übel wiederkehrt und am Hause ausbricht nach dem Ausreißen der Steine und nach dem Abkratzen des Hauses und nach dem Bewerfen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'so soll der Priester kommen; und besieht er es, und siehe, das Übel hat um sich gegriffen am Hause, so ist es ein fressender Aussatz am Hause: es ist unrein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Und man soll das Haus niederreißen, seine Steine und sein Holz und allen Lehm des Hauses, und es hinausschaffen außerhalb der Stadt an einen unreinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Und wer in das Haus hineingeht, so lange es verschlossen ist, wird unrein bis an den Abend;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'und wer in dem Hause schläft, soll seine Kleider waschen; und wer in dem Hause isset, soll seine Kleider waschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Wenn aber der Priester hineingeht und es besieht, und siehe, das Übel hat nicht um sich gegriffen am Hause nach dem Bewerfen des Hauses, so soll der Priester das Haus für rein erklären; denn das Übel ist heil geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Und er soll, um das Haus zu entsündigen, zwei Vögel nehmen und Cedernholz und Karmesin und Ysop;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'und er schlachte den einen Vogel in ein irdenes Gefäß über lebendigem Wasser;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'und er nehme das Cedernholz und den Ysop und das Karmesin und den lebendigen Vogel und tauche sie in das Blut des geschlachteten Vogels und in das lebendige Wasser und besprenge das Haus siebenmal;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'und er entsündige das Haus mit dem Blute des Vogels und mit dem lebendigen Wasser und mit dem lebendigen Vogel und mit dem Cedernholz und mit dem Ysop und mit dem Karmesin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'und den lebendigen Vogel soll er ins freie Feld fliegen lassen außerhalb der Stadt. Und so tue er Sühnung für das Haus; und er wird rein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Das ist das Gesetz für alles Übel des Aussatzes und für den Schorf,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'und für den Aussatz der Kleider und der Häuser,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'und für die Erhöhung und für den Grind und für den Flecken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'um zu belehren, wann für unrein und wann für rein zu erklären ist: das ist das Gesetz des Aussatzes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Und Jehova redete zu Mose und zu Aaron und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Redet zu den Kindern Israel und sprechet zu ihnen: Wenn irgend ein Mann an seinem Fleische flüssig ist, so ist er unrein durch seinen Fluß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Und dies wird seine Unreinheit sein bei seinem Flusse: Läßt sein Fleisch seinen Fluß triefen, oder hält sein Fleisch seinen Fluß zurück, so ist das seine Unreinheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Jedes Lager, worauf der Flüssige liegt, wird unrein sein, und jedes Gerät, worauf er sitzt, wird unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Und wer sein Lager anrührt, soll seine Kleider waschen und sich im Wasser baden, und er wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Und wer sich auf das Gerät setzt, worauf der Flüssige gesessen hat, soll seine Kleider waschen und sich im Wasser baden, und er wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Und wer das Fleisch des Flüssigen anrührt, soll seine Kleider waschen und sich im Wasser baden, und er wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Und wenn der Flüssige auf einen Reinen speit, so soll dieser seine Kleider waschen und sich im Wasser baden, und er wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Und jeder Wagen, auf welchem der Flüssige fährt, wird unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Und jeder, der irgend etwas anrührt, was er unter sich hat, wird unrein sein bis an den Abend; und wer es trägt, soll seine Kleider waschen und sich im Wasser baden, und er wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Und jeder, den der Flüssige anrührt, und er hat seine Hände nicht im Wasser abgespült, der soll seine Kleider waschen und sich im Wasser baden, und er wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Und das irdene Gefäß, das der Flüssige anrührt, soll zerbrochen werden, und jedes hölzerne Gefäß soll im Wasser gespült werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Und wenn der Flüssige rein wird von seinem Flusse, so soll er sich sieben Tage zählen zu seiner Reinigung; und er soll seine Kleider waschen und sein Fleisch in lebendigem Wasser baden, und er wird rein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Und am achten Tage soll er sich zwei Turteltauben oder zwei junge Tauben nehmen und vor Jehova kommen an den Eingang des Zeltes der Zusammenkunft und sie dem Priester geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'und der Priester soll sie opfern, die eine als Sündopfer und die andere als Brandopfer. Und so tue der Priester Sühnung für ihn vor Jehova wegen seines Flusses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Und wenn einem Manne der Samenerguß entgeht, so soll er sein ganzes Fleisch im Wasser baden, und er wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Und jedes Kleid und jedes Fell, worauf der Samenerguß kommt, soll im Wasser gewaschen werden, und es wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Und ein Weib, bei welchem ein Mann liegt mit Samenerguß, sie sollen sich im Wasser baden, und werden unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Und wenn ein Weib flüssig ist, und ihr Fluß an ihrem Fleische Blut ist, so soll sie sieben Tage in ihrer Unreinheit sein; und jeder, der sie anrührt, wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Und alles, worauf sie in ihrer Unreinheit liegt, wird unrein sein, und alles, worauf sie sitzt, wird unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Und jeder, der ihr Lager anrührt, soll seine Kleider waschen und sich im Wasser baden, und er wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Und jeder, der irgend ein Gerät anrührt, worauf sie gesessen hat, soll seine Kleider waschen und sich im Wasser baden, und er wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Und wenn etwas auf dem Lager oder auf dem Gerät ist, worauf sie gesessen hat, wenn er es anrührt, wird er unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Und wenn etwa ein Mann neben ihr liegt, und ihre Unreinigkeit kommt an ihn, so wird er sieben Tage unrein sein; und jedes Lager, worauf er liegt, wird unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Und wenn ein Weib ihren Blutfluß viele Tage hat außer der Zeit ihrer Unreinheit, oder wenn sie den Fluß hat über ihre Unreinheit hinaus, so soll sie alle die Tage des Flusses ihrer Unreinigkeit sein wie in den Tagen ihrer Unreinheit: sie ist unrein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Jedes Lager, worauf sie alle Tage ihres Flusses liegt, soll ihr sein wie das Lager ihrer Unreinheit, und jedes Gerät, worauf sie sitzt, wird unrein sein nach der Unreinigkeit ihrer Unreinheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Und jeder, der es anrührt, wird unrein sein; und er soll seine Kleider waschen und sich im Wasser baden, und er wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Und wenn sie rein geworden ist von ihrem Flusse, so soll sie sich sieben Tage zählen, und danach wird sie rein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Und am achten Tage soll sie sich zwei Turteltauben oder zwei junge Tauben nehmen und sie zu dem Priester bringen an den Eingang des Zeltes der Zusammenkunft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'und der Priester soll die eine als Sündopfer und die andere als Brandopfer opfern. Und so tue der Priester Sühnung für sie vor Jehova wegen des Flusses ihrer Unreinigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Und ihr sollt die Kinder Israel absondern von ihrer Unreinigkeit, daß sie nicht in ihrer Unreinigkeit sterben, indem sie meine Wohnung verunreinigen, die in ihrer Mitte ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Das ist das Gesetz für den Flüssigen und für den, dem der Samenerguß entgeht, so daß er durch ihn unrein wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'und für die, welche krank ist in ihrer Unreinheit, und für den, der seinen Fluß hat, es sei Mann oder Weib, und für den Mann, der neben einer Unreinen liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Und Jehova redete zu Mose nach dem Tode der beiden Söhne Aarons, als sie vor Jehova nahten und starben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'und Jehova sprach zu Mose: Rede zu deinem Bruder Aaron, daß er nicht zu aller Zeit in das Heiligtum hineingehe innerhalb des Vorhangs, vor den Deckel, der auf der Lade ist, damit er nicht sterbe; denn ich erscheine in der Wolke über dem Deckel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Auf diese Weise soll Aaron in das Heiligtum hineingehen: mit einem jungen Farren zum Sündopfer und einem Widder zum Brandopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Er soll einen heiligen Leibrock von Linnen anziehen, und Beinkleider von Linnen sollen auf seinem Fleische sein, und mit einem Gürtel von Linnen soll er sich umgürten, und einen Kopfbund von Linnen sich umbinden: das sind heilige Kleider; und er soll sein Fleisch im Wasser baden und sie anziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Und von der Gemeinde der Kinder Israel soll er zwei Ziegenböcke nehmen zum Sündopfer und einen Widder zum Brandopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Und Aaron soll den Farren des Sündopfers, der für ihn ist, herzubringen und Sühnung tun für sich und für sein Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Und er soll die zwei Böcke nehmen und sie vor Jehova stellen an den Eingang des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Und Aaron soll Lose werfen über die zwei Böcke, ein Los für Jehova und ein Los für Asasel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Und Aaron soll den Bock herzubringen, auf welchen das Los für Jehova gefallen ist, und ihn opfern als Sündopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Und der Bock, auf welchen das Los für Asasel gefallen ist, soll lebendig vor Jehova gestellt werden, um auf ihm Sühnung zu tun, um ihn als Asasel fortzuschicken in die Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Und Aaron bringe den Farren des Sündopfers, der für ihn ist, herzu und tue Sühnung für sich und für sein Haus, und schlachte den Farren des Sündopfers, der für ihn ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Und er nehme eine Pfanne voll Feuerkohlen von dem Altar, vor Jehova, und seine beiden Hände voll wohlriechenden, kleingestoßenen Räucherwerks, und bringe es innerhalb des Vorhangs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Und er lege das Räucherwerk auf das Feuer vor Jehova, damit die Wolke des Räucherwerks den Deckel bedecke, der auf dem Zeugnis ist, und er nicht sterbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Und er nehme von dem Blute des Farren und sprenge mit seinem Finger auf die Vorderseite des Deckels gegen Osten; und vor den Deckel soll er von dem Blute siebenmal sprengen mit seinem Finger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Und er schlachte den Bock des Sündopfers, der für das Volk ist, und bringe sein Blut innerhalb des Vorhangs, und tue mit seinem Blute, so wie er mit dem Blute des Farren getan hat, und sprenge es auf den Deckel und vor den Deckel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Und er tue Sühnung für das Heiligtum wegen der Unreinigkeiten der Kinder Israel und wegen ihrer Übertretungen, nach allen ihren Sünden; und ebenso soll er für das Zelt der Zusammenkunft tun, das bei ihnen weilt, inmitten ihrer Unreinigkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Und kein Mensch soll in dem Zelte der Zusammenkunft sein, wenn er hineingeht, um Sühnung zu tun im Heiligtum, bis er hinausgeht. Und so tue er Sühnung für sich und für sein Haus und für die ganze Versammlung Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Und er soll hinausgehen zu dem Altar, der vor Jehova ist, und Sühnung für ihn tun; und er nehme von dem Blute des Farren und von dem Blute des Bockes und tue es an die Hörner des Altars ringsum,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'und sprenge von dem Blute mit seinem Finger siebenmal an denselben und reinige ihn und heilige ihn von den Unreinigkeiten der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Und hat er die Sühnung des Heiligtums und des Zeltes der Zusammenkunft und des Altars vollendet, so soll er den lebendigen Bock herzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Und Aaron lege seine beiden Hände auf den Kopf des lebendigen Bockes und bekenne auf ihn alle Ungerechtigkeiten der Kinder Israel und alle ihre Übertretungen nach allen ihren Sünden; und er lege sie auf den Kopf des Bockes und schicke ihn durch einen bereitstehenden Mann fort in die Wüste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'damit der Bock alle ihre Ungerechtigkeiten auf sich trage in ein ödes Land; und er schicke den Bock fort in die Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Und Aaron soll in das Zelt der Zusammenkunft hineingehen und die Kleider von Linnen ausziehen, die er anzog, als er in das Heiligtum hineinging, und sie dort niederlegen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'und er soll sein Fleisch im Wasser baden an heiligem Orte und seine Kleider anziehen; und er soll hinausgehen und sein Brandopfer und das Brandopfer des Volkes opfern und Sühnung tun für sich und für das Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Und das Fett des Sündopfers soll er auf dem Altar räuchern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Und wer den Bock als Asasel fortführt, soll seine Kleider waschen und sein Fleisch im Wasser baden; und danach darf er ins Lager kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Und den Farren des Sündopfers und den Bock des Sündopfers, deren Blut hineingebracht worden ist, um Sühnung zu tun im Heiligtum, soll man hinausschaffen außerhalb des Lagers, und ihre Häute und ihr Fleisch und ihren Mist mit Feuer verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Und der sie verbrennt, soll seine Kleider waschen und sein Fleisch im Wasser baden; und danach darf er ins Lager kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Und dies soll euch zur ewigen Satzung sein: Im siebten Monat, am Zehnten des Monats, sollt ihr eure Seelen kasteien und keinerlei Arbeit tun, der Eingeborene und der Fremdling, der in eurer Mitte weilt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'denn an diesem Tage wird man Sühnung für euch tun, um euch zu reinigen: von allen euren Sünden werdet ihr rein sein vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ein Sabbath der Ruhe soll er euch sein, und ihr sollt eure Seelen kasteien, eine ewige Satzung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Und es soll Sühnung tun der Priester, den man salben und den man weihen wird, um den Priesterdienst auszuüben an seines Vaters Statt; und er soll die Kleider von Linnen anziehen, die heiligen Kleider;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'und er soll Sühnung tun für das heilige Heiligtum und für das Zelt der Zusammenkunft, und für den Altar soll er Sühnung tun, und für die Priester und für das ganze Volk der Gemeinde soll er Sühnung tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Und das soll euch zur ewigen Satzung sein, um für die Kinder Israel Sühnung zu tun wegen aller ihrer Sünden einmal im Jahre. Und er tat, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Rede zu Aaron und zu seinen Söhnen und zu allen Kindern Israel und sprich zu ihnen: Dies ist es, was Jehova geboten und gesagt hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Jedermann aus dem Hause Israel, der ein Rind oder ein Schaf oder eine Ziege im Lager schlachtet, oder der außerhalb des Lagers schlachtet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'und es nicht an den Eingang des Zeltes der Zusammenkunft gebracht hat, um es Jehova als Opfergabe darzubringen vor der Wohnung Jehovas, selbigem Manne soll Blut zugerechnet werden: Blut hat er vergossen, und selbiger Mann soll ausgerottet werden aus der Mitte seines Volkes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'auf daß die Kinder Israel ihre Schlachtopfer bringen, die sie auf freiem Felde schlachten, daß sie sie Jehova bringen an den Eingang des Zeltes der Zusammenkunft zu dem Priester und sie als Friedensopfer dem Jehova schlachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Und der Priester soll das Blut an den Altar Jehovas sprengen vor dem Eingang des Zeltes der Zusammenkunft und das Fett räuchern zum lieblichen Geruch dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Und sie sollen nicht mehr ihre Schlachtopfer den Dämonen schlachten, denen sie nachhuren. Das soll ihnen eine ewige Satzung sein bei ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Und du sollst zu ihnen sagen: Jedermann aus dem Hause Israel und von den Fremdlingen, die in ihrer Mitte weilen, der ein Brandopfer oder Schlachtopfer opfert');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'und es nicht an den Eingang des Zeltes der Zusammenkunft bringt, um es Jehova zu opfern, selbiger Mann soll ausgerottet werden aus seinen Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Und jedermann aus dem Hause Israel und von den Fremdlingen, die in ihrer Mitte weilen, der irgend Blut essen wird, wider die Seele, die das Blut isset, werde ich mein Angesicht richten und sie ausrotten aus der Mitte ihres Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Denn die Seele des Fleisches ist im Blute, und ich habe es euch auf den Altar gegeben, um Sühnung zu tun für eure Seelen; denn das Blut ist es, welches Sühnung tut durch die Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Darum habe ich zu den Kindern Israel gesagt: Niemand von euch soll Blut essen; auch der Fremdling, der in eurer Mitte weilt, soll nicht Blut essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Und jedermann von den Kindern Israel und von den Fremdlingen, die in eurer Mitte weilen, der ein Wildbret oder einen Vogel erjagt, die gegessen werden, soll ihr Blut ausfließen lassen und es mit Erde bedecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Denn die Seele alles Fleisches: sein Blut, das ist seine Seele; und ich habe zu den Kindern Israel gesagt: Das Blut irgend welches Fleisches sollt ihr nicht essen, denn die Seele alles Fleisches ist sein Blut; jeder, der es isset, soll ausgerottet werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Und jeder, der ein Aas oder Zerrissenes isset, er sei Eingeborener oder Fremdling, der soll seine Kleider waschen und sich im Wasser baden, und er wird unrein sein bis an den Abend; dann wird er rein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Und wenn er sie nicht wäscht und sein Fleisch nicht badet, so wird er seine Ungerechtigkeit tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Rede zu den Kindern Israel und sprich zu ihnen: Ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Nach dem Tun des Landes Ägypten, in welchem ihr gewohnt habt, sollt ihr nicht tun; und nach dem Tun des Landes Kanaan, wohin ich euch bringe, sollt ihr nicht tun; und in ihren Satzungen sollt ihr nicht wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Meine Rechte sollt ihr tun und meine Satzungen sollt ihr beobachten, darin zu wandeln. Ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Und meine Satzungen und meine Rechte sollt ihr beobachten, durch welche der Mensch, wenn er sie tut, leben wird. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Kein Mensch soll sich irgend einer seiner Blutsverwandten nahen, um ihre Blöße aufzudecken. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Die Blöße deines Vaters und die Blöße deiner Mutter sollst du nicht aufdecken; sie ist deine Mutter, du sollst ihre Blöße nicht aufdecken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Die Blöße des Weibes deines Vaters sollst du nicht aufdecken; es ist die Blöße deines Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Die Blöße deiner Schwester, der Tochter deines Vaters, oder der Tochter deiner Mutter, daheim geboren oder draußen geboren, ihre Blöße sollst du nicht aufdecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Die Blöße der Tochter deines Sohnes oder der Tochter deiner Tochter ihre Blöße sollst du nicht aufdecken, denn es ist deine Blöße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Die Blöße der Tochter des Weibes deines Vaters, von deinem Vater gezeugt, sie ist deine Schwester, ihre Blöße sollst du nicht aufdecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Die Blöße der Schwester deines Vaters sollst du nicht aufdecken: sie ist die Blutsverwandte deines Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Die Blöße der Schwester deiner Mutter sollst du nicht aufdecken, denn sie ist die Blutsverwandte deiner Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Die Blöße des Bruders deines Vaters sollst du nicht aufdecken: zu seinem Weibe sollst du nicht nahen, sie ist deine Muhme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Die Blöße deiner Schwiegertochter sollst du nicht aufdecken; sie ist das Weib deines Sohnes, ihre Blöße sollst du nicht aufdecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Die Blöße des Weibes deines Bruders sollst du nicht aufdecken; es ist die Blöße deines Bruders.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Die Blöße eines Weibes und ihrer Tochter sollst du nicht aufdecken; die Tochter ihres Sohnes und die Tochter ihrer Tochter sollst du nicht nehmen, um ihre Blöße aufzudecken; sie sind Blutsverwandte: es ist eine Schandtat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Und du sollst nicht ein Weib zu ihrer Schwester nehmen, sie eifersüchtig zu machen, indem du ihre Blöße neben derselben aufdeckst bei ihrem Leben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Und einem Weibe in der Unreinheit ihrer Unreinigkeit sollst du nicht nahen, um ihre Blöße aufzudecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Und bei dem Weibe deines Nächsten sollst du nicht liegen zur Begattung, daß du durch sie unrein werdest. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Und von deinen Kindern sollst du nicht hingeben, um sie dem Molech durch das Feuer gehen zu lassen, und du sollst den Namen Jehovas, deines Gottes, nicht entweihen. Ich bin Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Und bei einem Manne sollst du nicht liegen, wie man bei einem Weibe liegt: es ist ein Greuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Und bei keinem Vieh sollst du liegen, so daß du dich an ihm verunreinigst; und ein Weib soll sich nicht vor ein Vieh hinstellen, um mit ihm zu schaffen zu haben: es ist eine schändliche Befleckung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Verunreiniget euch nicht durch alles dieses; denn durch alles dieses haben die Nationen sich verunreinigt, die ich vor euch vertreibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Und das Land wurde verunreinigt, und ich suchte seine Ungerechtigkeit an ihm heim, und das Land spie seine Bewohner aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Ihr aber, ihr sollt meine Satzungen und meine Rechte beobachten, und ihr sollt nichts tun von allen diesen Greueln, der Eingeborene und der Fremdling, der in eurer Mitte weilt, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'denn alle diese Greuel haben die Leute dieses Landes getan, die vor euch waren, und das Land ist verunreinigt worden, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'damit das Land euch nicht ausspeie, wenn ihr es verunreiniget, so wie es die Nation ausgespieen hat, die vor euch war:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'denn jeder, der einen von allen diesen Greueln tut, die Seelen, die ihn tun, sollen ausgerottet werden aus der Mitte ihres Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Und ihr sollt meine Vorschriften beobachten, daß ihr keine der greulichen Bräuche übet, die vor euch geübt worden sind, und euch nicht durch dieselben verunreiniget. Ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Rede zu der ganzen Gemeinde der Kinder Israel und sprich zu ihnen: Ihr sollt heilig sein; denn ich, Jehova, euer Gott, bin heilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Ihr sollt ein jeder seine Mutter und seinen Vater fürchten; und meine Sabbathe sollt ihr beobachten. Ich bin Jehova, euer Gott. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ihr sollt euch nicht zu den Götzen wenden, und gegossene Götter sollt ihr euch nicht machen. Ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Und wenn ihr ein Friedensopfer dem Jehova opfert, so sollt ihr es zum Wohlgefallen für euch opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'An dem Tage, da ihr es opfert, und am anderen Tage soll es gegessen werden; und was bis zum dritten Tage übrigbleibt, soll mit Feuer verbrannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Und wenn es irgend am dritten Tage gegessen wird, so ist es ein Greuel, es wird nicht wohlgefällig sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'und wer es isset, wird seine Ungerechtigkeit tragen, denn das Heilige Jehovas hat er entweiht; und selbige Seele soll ausgerottet werden aus ihren Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Und wenn ihr die Ernte eures Landes erntet, so sollst du den Rand deines Feldes nicht gänzlich abernten und sollst keine Nachlese deiner Ernte halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Und in deinem Weinberge sollst du nicht nachlesen, und die abgefallenen Beeren deines Weinberges sollst du nicht auflesen: für den Armen und für den Fremdling sollst du sie lassen. Ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ihr sollt nicht stehlen; und ihr sollt nicht lügen und nicht trüglich handeln einer gegen den anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Und ihr sollt nicht falsch schwören bei meinem Namen, daß du den Namen deines Gottes entweihest. Ich bin Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Du sollst deinen Nächsten nicht bedrücken und sollst ihn nicht berauben; der Lohn des Tagelöhners soll nicht bei dir über Nacht bleiben bis an den Morgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Du sollst einem Tauben nicht fluchen und vor einen Blinden keinen Anstoß legen, und du sollst dich fürchten vor deinem Gott. Ich bin Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Ihr sollt nicht unrecht tun im Gericht; du sollst nicht die Person des Geringen ansehen und nicht die Person des Großen ehren; in Gerechtigkeit sollst du deinen Nächsten richten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Du sollst nicht als ein Verleumder unter deinen Völkern umhergehen. Du sollst nicht wider das Blut deines Nächsten auftreten. Ich bin Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Du sollst deinen Bruder nicht hassen in deinem Herzen. Du sollst deinen Nächsten ernstlich zurechtweisen, damit du nicht seinetwegen Schuld tragest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Du sollst dich nicht rächen und den Kindern deines Volkes nichts nachtragen, und sollst deinen Nächsten lieben wie dich selbst. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Meine Satzungen sollt ihr beobachten. Dein Vieh von zweierlei Art sollst du sich nicht begatten lassen; dein Feld sollst du nicht mit zweierlei Samen besäen, und ein Kleid, aus zweierlei Stoff gewebt, soll nicht auf dich kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Und wenn ein Mann bei einem Weibe liegt zur Begattung, und sie ist eine Magd, einem Manne verlobt, und sie ist keineswegs losgekauft, noch ist ihr die Freiheit geschenkt, so soll Züchtigung stattfinden; sie sollen nicht getötet werden, denn sie ist nicht frei gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Und er soll sein Schuldopfer dem Jehova bringen an den Eingang des Zeltes der Zusammenkunft, einen Widder als Schuldopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'und der Priester soll vor Jehova Sühnung für ihn tun mit dem Widder des Schuldopfers für seine Sünde, die er begangen hat; und seine Sünde, die er begangen hat, wird ihm vergeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Und wenn ihr in das Land kommet und allerlei Bäume zur Speise pflanzet, so sollt ihr ihre erste Frucht als ihre Vorhaut achten; drei Jahre sollen sie euch als unbeschnitten gelten, es soll nichts von ihnen gegessen werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'und im vierten Jahre soll all ihre Frucht heilig sein, Jehova zum Preise;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'und im fünften Jahre sollt ihr ihre Frucht essen, um euch ihren Ertrag zu mehren. Ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ihr sollt nichts mit Blut essen. Ihr sollt nicht Wahrsagerei noch Zauberei treiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ihr sollt nicht den Rand eures Haupthaares rund scheren, und den Rand deines Bartes sollst du nicht zerstören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Und Einschnitte wegen eines Toten sollt ihr an eurem Fleische nicht machen; und Ätzschrift sollt ihr an euch nicht machen. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Du sollst deine Tochter nicht entweihen, sie der Hurerei hinzugeben, daß das Land nicht Hurerei treibe und das Land voll Schandtaten werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Meine Sabbathe sollt ihr beobachten, und mein Heiligtum sollt ihr fürchten. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ihr sollt euch nicht zu den Totenbeschwörern und zu den Wahrsagern wenden; ihr sollt sie nicht aufsuchen, euch an ihnen zu verunreinigen. Ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Vor grauem Haare sollst du aufstehen und die Person eines Greises ehren, und du sollst dich fürchten vor deinem Gott. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Und wenn ein Fremdling bei dir weilt in eurem Lande, so sollt ihr ihn nicht bedrücken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Wie ein Eingeborener unter euch soll euch der Fremdling sein, der bei euch weilt, und du sollst ihn lieben wie dich selbst; denn Fremdlinge seid ihr gewesen im Lande Ägypten. Ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ihr sollt nicht unrecht tun im Gericht, im Längenmaß, im Gewicht und im Hohlmaß;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'gerechte Waage, gerechte Gewichtsteine, gerechtes Epha und gerechtes Hin sollt ihr haben. Ich bin Jehova, euer Gott, der ich euch aus dem Lande Ägypten herausgeführt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Und so sollt ihr alle meine Satzungen und alle meine Rechte beobachten und sie tun. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Und zu den Kindern Israel sollst du sprechen: Jedermann von den Kindern Israel und von den Fremdlingen, die in Israel weilen, der von seinen Kindern dem Molech gibt, soll gewißlich getötet werden; das Volk des Landes soll ihn steinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Und ich werde mein Angesicht wider selbigen Mann richten und ihn ausrotten aus der Mitte seines Volkes, weil er von seinen Kindern dem Molech gegeben hat, mein Heiligtum zu verunreinigen und meinen heiligen Namen zu entweihen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Und wenn das Volk des Landes seine Augen irgend verhüllt vor selbigem Manne, wenn er von seinen Kindern dem Molech gibt, so daß es ihn nicht tötet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'so werde ich mein Angesicht wider selbigen Mann richten und wider sein Geschlecht, und werde ihn und alle, die ihm nachhuren, um dem Molech nachzuhuren, ausrotten aus der Mitte ihres Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Und die Seele, die sich zu den Totenbeschwörern und zu den Wahrsagern wendet, um ihnen nachzuhuren, wider selbige Seele werde ich mein Angesicht richten und sie ausrotten aus der Mitte ihres Volkes. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'So heiliget euch und seid heilig, denn ich bin Jehova, euer Gott;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'und beobachtet meine Satzungen und tut sie. Ich bin Jehova, der euch heiligt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Jedermann, der seinem Vater oder seiner Mutter flucht, soll gewißlich getötet werden; er hat seinem Vater oder seiner Mutter geflucht, sein Blut ist auf ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Und wenn ein Mann Ehebruch treibt mit dem Weibe eines Mannes, wenn er Ehebruch treibt mit dem Weibe seines Nächsten, so sollen der Ehebrecher und die Ehebrecherin gewißlich getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Und wenn ein Mann bei dem Weibe seines Vaters liegt: er hat die Blöße seines Vaters aufgedeckt; beide sollen gewißlich getötet werden, ihr Blut ist auf ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Und wenn ein Mann bei seiner Schwiegertochter liegt, so sollen beide gewißlich getötet werden; sie haben eine schändliche Befleckung verübt, ihr Blut ist auf ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Und wenn ein Mann bei einem Manne liegt, wie man bei einem Weibe liegt, so haben beide einen Greuel verübt; sie sollen gewißlich getötet werden, ihr Blut ist auf ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Und wenn ein Mann ein Weib nimmt und ihre Mutter, das ist eine Schandtat; man soll ihn und sie mit Feuer verbrennen, daß keine Schandtat in eurer Mitte sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Und wenn ein Mann bei einem Vieh liegt, so soll er gewißlich getötet werden, und das Vieh sollt ihr umbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Und wenn ein Weib sich irgend einem Vieh naht, um mit ihm zu schaffen zu haben, so sollst du das Weib und das Vieh umbringen; sie sollen gewißlich getötet werden, ihr Blut ist auf ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Und wenn ein Mann seine Schwester nimmt, die Tochter seines Vaters oder die Tochter seiner Mutter, und er sieht ihre Blöße, und sie sieht seine Blöße: das ist eine Schande, und sie sollen ausgerottet werden vor den Augen der Kinder ihres Volkes; er hat die Blöße seiner Schwester aufgedeckt, er soll seine Ungerechtigkeit tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Und wenn ein Mann bei einem Weibe liegt in ihrer Krankheit und ihre Blöße aufdeckt, so hat er ihre Quelle enthüllt, und sie hat die Quelle ihres Blutes aufgedeckt; sie sollen beide ausgerottet werden aus der Mitte ihres Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Und die Blöße der Schwester deiner Mutter und der Schwester deines Vaters sollst du nicht aufdecken; denn wer das tut, hat seine Blutsverwandte entblößt: sie sollen ihre Ungerechtigkeit tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Und wenn ein Mann bei dem Weibe seines Oheims liegt, so hat er die Blöße seines Oheims aufgedeckt; sie sollen ihre Sünde tragen, kinderlos sollen sie sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Und wenn ein Mann das Weib seines Bruders nimmt: das ist eine Unreinigkeit; Er hat die Blöße seines Bruders aufgedeckt, sie sollen kinderlos sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Und ihr sollt alle meine Satzungen und alle meine Rechte beobachten und sie tun, damit euch das Land nicht ausspeie, wohin ich euch bringe, um darin zu wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'und ihr sollt nicht wandeln in den Satzungen der Nationen, die ich vor euch vertreibe; denn alle jene Dinge haben sie getan, und sie sind mir zum Ekel geworden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Und ich habe zu euch gesagt: Ihr sollt ihr Land besitzen, und ich werde es euch zum Besitz geben, ein Land, das von Milch und Honig fließt. Ich bin Jehova euer Gott, der ich euch von den Völkern abgesondert habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Und ihr sollt unterscheiden zwischen dem reinen Vieh und dem unreinen, und zwischen dem unreinen Gevögel und dem reinen, und sollt euch selbst nicht zu einem Greuel machen durch das Vieh und durch das Gevögel und durch alles, was sich auf dem Erdboden regt, welches ich euch als unrein ausgesondert habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Und ihr sollt mir heilig sein, denn ich bin heilig, ich, Jehova; und ich habe euch von den Völkern abgesondert, um mein zu sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Und wenn in einem Manne oder einem Weibe ein Totenbeschwörer-oder Wahrsagergeist ist, so sollen sie gewißlich getötet werden; man soll sie steinigen, ihr Blut ist auf ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Und Jehova sprach zu Mose: Rede zu den Priestern, den Söhnen Aarons, und spricht zu ihnen: Keiner von ihnen soll sich wegen einer Leiche verunreinigen unter seinen Völkern:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'außer wegen seines Blutsverwandten, der ihm nahe steht: wegen seiner Mutter und wegen seines Vaters und wegen seines Sohnes und wegen seiner Tochter und wegen seines Bruders;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'und wegen seiner Schwester, der Jungfrau, sie ihm nahe steht, die noch keines Mannes geworden ist: wegen dieser darf er sich verunreinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Er soll sich nicht verunreinigen als Herr unter seinen Völkern, sich zu entweihen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Sie sollen keine Glatze auf ihrem Haupte machen, und den Rand ihres Bartes sollen sie nicht abscheren, und an ihrem Fleische sollen sie keine Einschnitte machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Sie sollen ihrem Gott heilig sein, und den Namen ihres Gottes, sollen sie nicht entweihen, denn die Feueropfer Jehovas, das Brot ihres Gottes bringen sie dar; und sie sollen heilig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Eine Hure und eine Entehrte sollen sie nicht zum Weibe nehmen, und ein von ihrem Manne verstoßenes Weib sollen sie nicht nehmen; denn heilig ist er seinem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Und du sollst ihn für heilig achten, denn das Brot deines Gottes bringt er dar; er soll dir heilig sein; denn heilig bin ich Jehova, der euch heiligt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Und wenn die Tochter eines Priesters sich durch Hurerei entweiht, so entweiht sie ihren Vater: sie soll mit Feuer verbrannt werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Und der Hohepriester unter seinen Brüdern, auf dessen Haupt das Salböl gegossen worden, und der geweiht ist, um die heiligen Kleider anzulegen, soll sein Haupt nicht entblößen und soll seine Kleider nicht zerreißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Und er soll zu keiner Leiche kommen; wegen seines Vaters und wegen seiner Mutter soll er sich nicht verunreinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Und aus dem Heiligtum soll er nicht hinausgehen und nicht entweihen das Heiligtum seines Gottes; denn die Weihe des Salböls seines Gottes ist auf ihm. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Und derselbe soll ein Weib in ihrer Jungfrauschaft nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Eine Witwe und eine Verstoßene und eine Entehrte, eine Hure, diese soll er nicht nehmen; sondern eine Jungfrau aus seinen Völkern soll er zum Weibe nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Und er soll seinen Samen nicht entweihen unter seinen Völkern; denn ich bin Jehova, der ihn heiligt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Rede zu Aaron und sprich: Jemand von deinem Samen bei ihren Geschlechtern, an dem ein Gebrechen ist, soll nicht herzunahen, um das Brot seines Gottes darzubringen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'denn jedermann, an dem ein Gebrechen ist, soll nicht herzunahen, es sei ein blinder Mann oder ein lahmer oder ein stumpfnasiger, oder der ein Glied zu lang hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'oder ein Mann, der einen Bruch am Fuße oder einen Bruch an der Hand hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'oder ein Höckeriger oder ein Zwerg, oder der einen Flecken an seinem Auge hat, oder der die Krätze oder Flechte, oder der zerdrückte Hoden hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Jedermann vom Samen Aarons, des Priesters, der ein Gebrechen hat, soll nicht herzutreten, die Feueropfer Jehovas darzubringen; ein Gebrechen ist an ihm, er soll nicht herzutreten, das Brot seines Gottes darzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Das Brot seines Gottes von dem Hochheiligen und von dem Heiligen mag er essen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'allein zum Vorhang soll er nicht kommen, und zum Altar soll er nicht nahen, denn ein Gebrechen ist an ihm, daß er nicht meine Heiligtümer entweihe; denn ich bin Jehova, der sie heiligt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Und so redete Mose zu Aaron und zu seinen Söhnen und zu allen Kindern Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Rede zu Aaron und zu seinen Söhnen, daß sie sich enthalten von den heiligen Dingen der Kinder Israel, die sie mir heiligen, und meinen heiligen Namen nicht entweihen. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Sprich zu ihnen: Wer irgend von all eurem Samen, bei euren Geschlechtern, sich den heiligen Dingen naht, welche die Kinder Israel Jehova heiligen, und seine Unreinigkeit ist an ihm, selbige Seele soll ausgerottet werden vor meinem Angesicht hinweg. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Jedermann vom Samen Aarons, der aussätzig oder flüssig ist, soll nicht von den heiligen Dingen essen, bis er rein ist. Und wer irgend einen anrührt, der durch eine Leiche verunreinigt ist, oder jemanden, dem der Samenerguß entgeht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'oder wer irgend ein kriechendes Tier anrührt, durch welches er unrein wird, oder einen Menschen, durch den er unrein wird nach irgend welcher Unreinigkeit, die er hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Einer, der solches anrührt, der wird unrein sein bis an den Abend; und er soll nicht von den heiligen Dingen essen, sondern soll sein Fleisch im Wasser baden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'und ist die Sonne untergegangen, so ist er rein; und danach darf er von den heiligen Dingen essen, denn es ist sein Brot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Aas und Zerrissenes soll er nicht essen, daß er sich dadurch verunreinige. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Und sie sollen meine Vorschriften beobachten, damit sie nicht deswegen Sünde auf sich laden und dadurch sterben, weil sie es entweihen. Ich bin Jehova, der sie heiligt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Und kein Fremder soll Heiliges essen; der Beisasse und der Tagelöhner eines Priesters sollen Heiliges nicht essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Wenn aber ein Priester eine Seele für Geld kauft, so darf diese davon essen; und seine Hausgeborenen, sie dürfen von seinem Brote essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Und wenn die Tochter eines Priesters das Weib eines fremden Mannes wird, so soll sie nicht von dem Hebopfer der heiligen Dinge essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Und wenn die Tochter eines Priesters Witwe oder verstoßen wird, und keine Kinder hat und in das Haus ihres Vaters zurückkehrt, wie in ihrer Jugend, so darf sie von dem Brote ihres Vaters essen. Aber kein Fremder soll davon essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Und wenn jemand aus Versehen Heiliges isset, so soll er das Fünftel davon hinzufügen und dem Priester das Heilige erstatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Und man soll die heiligen Dinge der Kinder Israel nicht entweihen, die sie dem Jehova heben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'und ihnen so die Ungerechtigkeit einer Schuld aufladen, wenn sie ihre heiligen Dinge essen; denn ich bin Jehova, der sie heiligt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Rede zu Aaron und zu seinen Söhnen und zu allen Kindern Israel und sprich zu ihnen: Jedermann vom Hause Israel und von den Fremdlingen in Israel, der seine Opfergabe darbringt, nach allen ihren Gelübden und nach allen ihren freiwilligen Gaben, welche sie Jehova als Brandopfer darbringen, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'zum Wohlgefallen für euch soll es sein, ohne Fehl, männlich, von den Rindern, von den Schafen oder von den Ziegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Alles, woran ein Gebrechen ist, sollt ihr nicht darbringen, denn es wird nicht zum Wohlgefallen für euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Und wenn jemand dem Jehova ein Friedensopfer darbringt, um ein Gelübde zu erfüllen, oder als freiwillige Gabe vom Rind-oder Kleinvieh: ohne Fehl soll es sein, zum Wohlgefallen; keinerlei Gebrechen soll an ihm sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Ein blindes oder verletztes oder verstümmeltes Tier, oder eines, das Geschwüre oder die Krätze oder die Flechte hat, diese sollt ihr Jehova nicht darbringen, und sollt Jehova keine Feueropfer davon auf den Altar geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Und ein Stück Rind-oder Kleinvieh, an welchem ein Glied zu lang oder zu kurz ist, das magst du als freiwillige Gabe opfern; aber zu einem Gelübde wird es nicht wohlgefällig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Und dem die Hoden zerquetscht oder zerstoßen oder ausgerissen oder ausgeschnitten sind, sollt ihr Jehova nicht darbringen; und in eurem Lande sollt ihr dergleichen nicht tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Und aus der Hand eines Fremden sollt ihr das Brot eures Gottes aus allen diesen nicht darbringen; denn ihr Verderben ist an ihnen, ein Gebrechen ist an ihnen; sie werden nicht wohlgefällig für euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Wenn ein Rind oder ein Schaf oder eine Ziege geboren wird, so soll es sieben Tage unter seiner Mutter sein; und vom achten Tage an und weiterhin wird es wohlgefällig sein zur Opfergabe eines Feueropfers dem Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Und ein Stück Rind-oder Kleinvieh, es selbst und sein Junges, sollt ihr nicht schlachten an einem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Und wenn ihr dem Jehova ein Dankopfer opfert, so sollt ihr es zum Wohlgefallen für euch opfern:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'An demselben Tage soll es gegessen werden; ihr sollt nichts davon übriglassen bis an den Morgen. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Und ihr sollt meine Gebote beobachten und sie tun. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Und ihr sollt meinen heiligen Namen nicht entweihen, damit ich geheiligt werde in der Mitte der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Ich bin Jehova, der euch heiligt, der euch aus dem Lande Ägypten herausgeführt hat, um euer Gott zu sein. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Rede zu den Kindern Israel und sprich zu ihnen: Die Feste Jehovas, die ihr als heilige Versammlungen ausrufen sollt, meine Feste sind diese:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Sechs Tage soll man Arbeit tun; aber am siebten Tage ist ein Sabbath der Ruhe, eine heilige Versammlung; keinerlei Arbeit sollt ihr tun; es ist ein Sabbath dem Jehova in allen euren Wohnsitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Dies sind die Feste Jehovas, heilige Versammlungen, die ihr ausrufen sollt zu ihrer bestimmten Zeit:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Im ersten Monat, am Vierzehnten des Monats, zwischen den zwei Abenden, ist Passah dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Und am fünfzehnten Tage dieses Monats ist das Fest der ungesäuerten Brote dem Jehova; sieben Tage sollt ihr Ungesäuertes essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Am ersten Tage soll euch eine heilige Versammlung sein, keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Und ihr sollt Jehova ein Feueropfer darbringen sieben Tage; am siebten Tage ist eine heilige Versammlung, keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Rede zu den Kindern Israel und sprich zu ihnen: Wenn ihr in das Land kommet, das ich euch gebe, und ihr seine Ernte erntet, so sollt ihr eine Garbe der Erstlinge eurer Ernte zu dem Priester bringen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'und er soll die Garbe vor Jehova weben zum Wohlgefallen für euch; am anderen Tage nach dem Sabbath soll sie der Priester weben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Und ihr sollt an dem Tage, da ihr die Garbe webet, ein Lamm opfern, ohne Fehl, einjährig, zum Brandopfer dem Jehova;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'und sein Speisopfer: zwei Zehntel Feinmehl, gemengt mit Öl, ein Feueropfer dem Jehova, ein lieblicher Geruch; und sein Trankopfer: ein viertel Hin Wein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Und Brot und geröstete Körner und Gartenkorn sollt ihr nicht essen bis zu diesem selbigen Tage, bis ihr die Opfergabe eures Gottes gebracht habt: eine ewige Satzung bei euren Geschlechtern in allen euren Wohnsitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Und ihr sollt euch zählen vom anderen Tage nach dem Sabbath, von dem Tage, da ihr die Webegarbe gebracht habt: es sollen sieben volle Wochen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Bis zum anderen Tage nach dem siebten Sabbath sollt ihr fünfzig Tage zählen; und ihr sollt Jehova ein neues Speisopfer darbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Aus euren Wohnungen sollt ihr Webebrote bringen, zwei von zwei Zehnteln Feinmehl sollen es sein, gesäuert sollen sie gebacken werden, als Erstlinge dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Und ihr sollt zu dem Brote darbringen sieben einjährige Lämmer ohne Fehl, und einen jungen Farren und zwei Widder (sie sollen ein Brandopfer dem Jehova sein) und ihr Speisopfer und ihre Trankopfer: ein Feueropfer lieblichen Geruchs dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Und ihr sollt einen Ziegenbock zum Sündopfer opfern und zwei einjährige Lämmer zum Friedensopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Und der Priester soll sie weben samt dem Brote der Erstlinge als Webopfer vor Jehova, samt den zwei Lämmern: sie sollen Jehova heilig sein für den Priester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Und ihr sollt an diesem selbigen Tage einen Ruf ergehen lassen, eine heilige Versammlung soll euch sein; keinerlei Dienstarbeit sollt ihr tun: eine ewige Satzung in allen euren Wohnsitzen bei euren Geschlechtern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Und wenn ihr die Ernte eures Landes erntet, sollst du den Rand deines Feldes nicht gänzlich abernten, und sollst keine Nachlese deiner Ernte halten; für den Armen und für den Fremdling sollst du sie lassen. Ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Rede zu den Kindern Israel und sprich: Im siebten Monat, am Ersten des Monats, soll euch Ruhe sein, ein Gedächtnis des Posaunenhalls, eine heilige Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Keinerlei Dienstarbeit sollt ihr tun, und ihr sollt Jehova ein Feueropfer darbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Doch am Zehnten dieses siebten Monats ist der Versöhnungstag; eine heilige Versammlung soll euch sein, und ihr sollt eure Seelen kasteien, und sollt Jehova ein Feueropfer darbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Und keinerlei Arbeit sollt ihr tun an diesem selbigen Tage; denn es ist der Versöhnungstag, um Sühnung für euch zu tun vor Jehova, eurem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Denn jede Seele, die sich nicht kasteit an diesem selbigen Tage, die soll ausgerottet werden aus ihren Völkern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'und jede Seele, die irgend eine Arbeit tut an diesem selbigen Tage, selbige Seele werde ich vertilgen aus der Mitte ihres Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Keinerlei Arbeit sollt ihr tun: eine ewige Satzung bei euren Geschlechtern in allen euren Wohnsitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Ein Sabbath der Ruhe soll er für euch sein, und ihr sollt eure Seelen kasteien; am Neunten des Monats, am Abend, vom Abend bis zum Abend sollt ihr euren Sabbath feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Rede zu den Kindern Israel und sprich: Am fünfzehnten Tage dieses siebten Monats ist das Fest der Laubhütten sieben Tage dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Am ersten Tage soll eine heilige Versammlung sein, keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Sieben Tage sollt ihr Jehova ein Feueropfer darbringen; am achten Tage soll euch eine heilige Versammlung sein, und ihr sollt Jehova ein Feueropfer darbringen: es ist eine Festversammlung, keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Das sind die Feste Jehovas, die ihr ausrufen sollt als heilige Versammlungen, um Jehova darzubringen Feueropfer, Brandopfer und Speisopfer, Schlachtopfer und Trankopfer, die Gebühr des Tages an seinem Tage:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'außer den Sabbathen Jehovas und außer euren Gaben und außer allen euren Gelübden und außer allen euren freiwilligen Gaben, die ihr Jehova gebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Doch am fünfzehnten Tage des siebten Monats, wenn ihr den Ertrag des Landes eingesammelt habt, sollt ihr das Fest Jehovas feiern sieben Tage; am ersten Tage soll Ruhe sein, und am achten Tage soll Ruhe sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Und ihr sollt euch am ersten Tage Frucht von schönen Bäumen nehmen, Palmzweige und Zweige von dichtbelaubten Bäumen und von Bachweiden, und sollt euch vor Jehova, eurem Gott, freuen sieben Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Und ihr sollt dasselbe sieben Tage im Jahre als Fest dem Jehova feiern: eine ewige Satzung bei euren Geschlechtern; im siebten Monat sollt ihr dasselbe feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'In Laubhütten sollt ihr wohnen sieben Tage; alle Eingeborenen in Israel sollen in Laubhütten wohnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'auf daß eure Geschlechter wissen, daß ich die Kinder Israel in Laubhütten habe wohnen lassen, als ich sie aus dem Lande Ägypten herausführte. Ich bin Jehova, euer Gott. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Und Mose sagte den Kindern Israel die Feste Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Gebiete den Kindern Israel, daß sie dir reines, zerstoßenes Olivenöl bringen zum Licht, um die Lampen anzuzünden beständig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Außerhalb des Vorhangs des Zeugnisses, im Zelte der Zusammenkunft, soll Aaron sie zurichten, vom Abend bis zum Morgen, vor Jehova beständig: eine ewige Satzung bei euren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Auf dem reinen Leuchter soll er die Lampen beständig vor Jehova zurichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Und du sollst Feinmehl nehmen und daraus zwölf Kuchen backen: von zwei Zehnteln soll ein Kuchen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Und du sollst sie in zwei Schichten legen, sechs in eine Schicht, auf den reinen Tisch vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Und du sollst auf jede Schicht reinen Weihrauch legen, und er soll dem Brote zum Gedächtnis sein, ein Feueropfer dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Sabbathtag für Sabbathtag soll es beständig vor Jehova zurichten: ein ewiger Bund von seiten der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Und es soll Aaron und seinen Söhnen gehören, und sie sollen es essen an heiligem Orte; denn als ein Hochheiliges von den Feueropfern Jehovas soll es ihm gehören: eine ewige Satzung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Und der Sohn eines israelitischen Weibes, er war aber der Sohn eines ägyptischen Mannes, ging aus unter die Kinder Israel; und der Sohn der Israelitin und ein israelitischer Mann zankten sich im Lager.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Und der Sohn des israelitischen Weibes lästerte den Namen Jehovas und fluchte ihm; und sie brachten ihn zu Mose. Der Name seiner Mutter aber war Schelomith, die Tochter Dibris, vom Stamme Dan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Und sie legten ihn in Gewahrsam, damit ihnen nach dem Munde Jehovas beschieden werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Führe den Flucher außerhalb des Lagers; und alle, die es gehört haben, sollen ihre Hände auf seinen Kopf legen, und die ganze Gemeinde soll ihn steinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Und zu den Kindern Israel sollst du reden und sprechen: Wenn irgend jemand seinem Gott flucht, so soll er seine Sünde tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Und wer den Namen Jehovas lästert, soll gewißlich getötet werden, steinigen soll ihn die ganze Gemeinde; wie der Fremdling, so der Eingeborene: wenn er den Namen lästert, soll er getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Und wenn jemand irgend einen Menschen totschlägt, so soll er gewißlich getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Und wer ein Vieh totschlägt, soll es erstatten: Leben um Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Und wenn jemand seinem Nächsten eine Verletzung zufügt: wie er getan hat, also soll ihm getan werden:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Bruch um Bruch, Auge um Auge, Zahn um Zahn; wie er einem Menschen eine Verletzung zufügt, also soll ihm zugefügt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Und wer ein Vieh totschlägt, soll es erstatten; wer aber einen Menschen totschlägt, soll getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Einerlei Recht sollt ihr haben: wie der Fremdling, so soll der Eingeborene sein; denn ich bin Jehova, euer Gott. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Und Mose redete zu den Kindern Israel, und sie führten den Flucher vor das Lager hinaus und steinigten ihn; und die Kinder Israel taten, wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Und Jehova redete zu Mose auf dem Berge Sinai und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Rede zu den Kindern Israel und sprich zu ihnen: Wenn ihr in das Land kommet, das ich euch geben werde, so soll das Land dem Jehova einen Sabbath feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Sechs Jahre sollst du dein Feld besäen und sechs Jahre deinen Weinberg beschneiden und den Ertrag des Landes einsammeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Aber im siebten Jahre soll ein Sabbath der Ruhe für das Land sein, ein Sabbath dem Jehova; dein Feld sollst du nicht besäen und deinen Weinberg nicht beschneiden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'den Nachwuchs deiner Ernte sollst du nicht einernten, und die Trauben deines unbeschnittenen Weinstocks sollst du nicht abschneiden: Es soll ein Jahr der Ruhe für das Land sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Und der Sabbath des Landes soll euch zur Speise dienen, dir und deinem Knechte und deiner Magd und deinem Tagelöhner und deinem Beisassen, die sich bei dir aufhalten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'und deinem Vieh und dem wilden Getier, das in deinem Lande ist, soll all sein Ertrag zur Speise dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Und du sollst dir sieben Jahrsabbathe zählen, siebenmal sieben Jahre, so daß die Tage von sieben Jahrsabbathen dir neunundvierzig Jahre ausmachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Und du sollst im siebten Monat, am Zehnten des Monats, den Posaunenschall ergehen lassen; an dem Versöhnungstage sollt ihr die Posaune ergehen lassen durch euer ganzes Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Und ihr sollt das Jahr des fünfzigsten Jahres heiligen und sollt im Lande Freiheit ausrufen für alle seine Bewohner. Ein Jubeljahr soll es euch sein, und ihr werdet ein jeder wieder zu seinem Eigentum kommen, und ein jeder zurückkehren zu seinem Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Ein Jubeljahr soll dasselbe, das Jahr des fünfzigsten Jahres, euch sein; ihr sollt nicht säen und seinen Nachwuchs nicht ernten und seine unbeschnittenen Weinstöcke nicht lesen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'denn ein Jubeljahr ist es: es soll euch heilig sein; vom Felde weg sollt ihr seinen Ertrag essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'In diesem Jahre des Jubels sollt ihr ein jeder wieder zu seinem Eigentum kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Und wenn ihr eurem Nächsten etwas verkaufet oder von der Hand eures Nächsten etwas kaufet, so soll keiner seinen Bruder bedrücken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Nach der Zahl der Jahre seit dem Jubeljahre sollst du von deinem Nächsten kaufen, nach der Zahl der Erntejahre soll er dir verkaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Nach Verhältnis der größeren Zahl von Jahren sollst du ihm den Kaufpreis mehren, und nach Verhältnis der geringeren Zahl von Jahren sollst du ihm den Kaufpreis mindern; denn eine Zahl von Ernten verkauft er dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Und so soll keiner von euch seinen Nächsten bedrücken, und du sollst dich fürchten vor deinem Gott; denn ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Und so tut meine Satzungen, und beobachtet meine Rechte und tut sie, so werdet ihr sicher wohnen in eurem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Und das Land wird seine Frucht geben, und ihr werdet essen bis zur Sättigung und sicher in demselben wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Und wenn ihr sprechet: Was sollen wir im siebten Jahre essen? Siehe, wir säen nicht, und unseren Ertrag sammeln wir nicht ein: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Ich werde euch ja im sechsten Jahre meinen Segen entbieten, daß es den Ertrag für drei Jahre bringe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'und wenn ihr im achten Jahre säet, werdet ihr noch vom alten Ertrage essen; bis ins neunte Jahr, bis sein Ertrag einkommt, werdet ihr Altes essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Und das Land soll nicht für immer verkauft werden, denn mein ist das Land; denn Fremdlinge und Beisassen seid ihr bei mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Und im ganzen Lande eures Eigentums sollt ihr dem Lande Lösung gestatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Wenn dein Bruder verarmt und von seinem Eigentum verkauft, so mag sein Löser, sein nächster Verwandter, kommen und das Verkaufte seines Bruders lösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Und wenn jemand keinen Löser hat, und seine Hand erwirbt und findet, was zu seiner Lösung hinreicht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'so soll er die Jahre seines Verkaufs berechnen und das Übrige dem Manne zurückzahlen, an den er verkauft hat, und so wieder zu seinem Eigentum kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Und wenn seine Hand nicht gefunden hat, was hinreicht, um ihm zurückzuzahlen, so soll das von ihm Verkaufte in der Hand des Käufers desselben bleiben bis zum Jubeljahre; und im Jubeljahre soll es frei ausgehen, und er soll wieder zu seinem Eigentum kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Und wenn jemand ein Wohnhaus in einer ummauerten Stadt verkauft, so soll sein Lösungsrecht bestehen bis zum Ende des Jahres seines Verkaufs; ein volles Jahr soll sein Lösungsrecht bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Wenn es aber nicht gelöst wird, bis ihm ein ganzes Jahr voll ist, so soll das Haus, das in der ummauerten Stadt ist, für immer dem Käufer desselben verbleiben, bei seinen Geschlechtern; es soll im Jubeljahre nicht frei ausgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Aber die Häuser der Dörfer, welche keine Mauer ringsum haben, sollen dem Felde des Landes gleichgeachtet werden; es soll Lösungsrecht für sie sein, und im Jubeljahre sollen sie frei ausgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Und was die Städte der Leviten, die Häuser der Städte ihres Eigentums betrifft, so soll ein ewiges Lösungsrecht für die Leviten sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Und wenn jemand von einem der Leviten löst, so soll das verkaufte Haus in der Stadt seines Eigentums im Jubeljahre frei ausgehen; denn die Häuser der Städte der Leviten sind ihr Eigentum unter den Kindern Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Aber das Feld des Bezirks ihrer Städte soll nicht verkauft werden, denn es gehört ihnen als ewiges Eigentum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Und wenn dein Bruder verarmt und seine Hand bei dir wankend wird, so sollst du ihn unterstützen; wie der Fremdling und der Beisasse soll er bei dir leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Du sollst nicht Zins und Wucher von ihm nehmen, und sollst dich fürchten vor deinem Gott, damit dein Bruder bei dir lebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Dein Geld sollst du ihm nicht um Zins geben und deine Nahrungsmittel nicht um Wucher geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Ich bin Jehova, euer Gott, der ich euch aus dem Lande Ägypten herausgeführt habe, um euch das Land Kanaan zu geben, um euer Gott zu sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Und wenn dein Bruder bei dir verarmt und sich dir verkauft, so sollst du ihn nicht Sklavendienst tun lassen; wie ein Tagelöhner,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'wie ein Beisasse soll er bei dir sein; bis zum Jubeljahre soll er bei dir dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Dann soll er frei von dir ausgehen, er und seine Kinder mit ihm, und zu seinem Geschlecht zurückkehren und wieder zu dem Eigentum seiner Väter kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Denn sie sind meine Knechte, die ich aus dem Lande Ägypten herausgeführt habe; sie sollen nicht verkauft werden, wie man Sklaven verkauft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Du sollst nicht mit Härte über ihn herrschen, und sollst dich fürchten vor deinem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Was aber deinen Knecht und deine Magd betrifft, die du haben wirst: von den Nationen, die rings um euch her sind, von ihnen möget ihr Knecht und Magd kaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Und auch von den Kindern der Beisassen, die sich bei euch aufhalten, von ihnen möget ihr kaufen und von ihrem Geschlecht, das bei euch ist, das sie in eurem Lande gezeugt haben; und sie mögen euch zum Eigentum sein,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'und ihr möget sie euren Söhnen nach euch vererben, um sie als Eigentum zu besitzen. Diese möget ihr auf ewig dienen lassen; aber über eure Brüder, die Kinder Israel, sollt ihr nicht einer über den anderen herrschen mit Härte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Und wenn die Hand eines Fremdlings oder eines Beisassen bei dir etwas erwirbt, und dein Bruder bei ihm verarmt und sich dem Fremdling, dem Beisassen bei dir, oder einem Sprößling aus dem Geschlecht des Fremdlings verkauft,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'so soll, nachdem er sich verkauft hat, Lösungsrecht für ihn sein; einer von seinen Brüdern mag ihn lösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Entweder sein Oheim oder der Sohn seines Oheims mag ihn lösen, oder einer von seinen nächsten Blutsverwandten aus seinem Geschlecht mag ihn lösen; oder hat seine Hand etwas erworben, so mag er sich selbst lösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Und er soll mit seinem Käufer rechnen von dem Jahre an, da er sich ihm verkauft hat, bis zum Jubeljahre; und der Preis, um den er sich verkauft hat, soll der Zahl der Jahre gemäß sein; nach den Tagen eines Tagelöhners soll er bei ihm sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Wenn der Jahre noch viele sind, so soll er nach ihrem Verhältnis seine Lösung von seinem Kaufgelde zurückzahlen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'und wenn wenig übrig ist an den Jahren bis zum Jubeljahre, so soll er es ihm berechnen: nach Verhältnis seiner Jahre soll er seine Lösung zurückzahlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Wie ein Tagelöhner soll er Jahr für Jahr bei ihm sein; er soll nicht vor deinen Augen mit Härte über ihn herrschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Und wenn er nicht in dieser Weise gelöst wird, so soll er im Jubeljahre frei ausgehen, er und seine Kinder mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Denn mir sind die Kinder Israel Knechte; meine Knechte sind sie, die ich aus dem Lande Ägypten herausgeführt habe. Ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Ihr sollt euch keine Götzen machen und sollt euch kein geschnitztes Bild und keine Bildsäule aufrichten, und keinen Stein mit Bildwerk sollt ihr in eurem Lande setzen, um euch davor niederzubeugen; denn ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Meine Sabbathe sollt ihr beobachten, und mein Heiligtum sollt ihr fürchten. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Wenn ihr in meinen Satzungen wandelt und meine Gebote beobachtet und sie tut,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'so werde ich eure Regen geben zu ihrer Zeit, und das Land wird seinen Ertrag geben, und die Bäume des Feldes werden ihre Frucht geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'und die Dreschzeit wird bei euch reichen bis an die Weinlese, und die Weinlese wird reichen bis an die Saatzeit; und ihr werdet euer Brot essen bis zur Sättigung und werdet sicher in eurem Lande wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Und ich werde Frieden im Lande geben, daß ihr euch niederleget und niemand sei, der euch aufschreckt; und ich werde die bösen Tiere aus dem Lande vertilgen, und das Schwert wird nicht durch euer Land gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Und ihr werdet eure Feinde jagen, und sie werden vor euch fallen durchs Schwert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'und fünf von euch werden hundert jagen, und hundert von euch werden zehntausend jagen, und eure Feinde werden vor euch fallen durchs Schwert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Und ich werde mich zu euch wenden und euch fruchtbar machen und euch mehren und meinen Bund mit euch aufrechthalten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'und ihr werdet das altgewordene Alte essen, und das Alte wegräumen vor dem Neuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Und ich werde meine Wohnung in eure Mitte setzen, und meine Seele wird euch nicht verabscheuen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'und ich werde in eurer Mitte wandeln und werde euer Gott sein und ihr werdet mein Volk sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ich bin Jehova, euer Gott, der ich euch aus dem Lande Ägypten herausgeführt habe, daß ihr nicht ihre Knechte sein solltet; und ich habe die Stäbe eures Joches zerbrochen und euch aufrecht wandeln lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Wenn ihr mir aber nicht gehorchet und nicht alle diese Gebote tut,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'und wenn ihr meine Satzungen verachtet, und eure Seele meine Rechte verabscheut, so daß ihr nicht alle meine Gebote tut, und daß ihr meinen Bund brechet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'so werde auch ich euch dieses tun: Ich werde Schrecken über euch bestellen, Schwindsucht und Fieberglut, welche machen werden, daß die Augen erlöschen und die Seele verschmachtet; und ihr werdet vergeblich euren Samen säen, denn eure Feinde werden ihn verzehren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'und ich werde mein Angesicht wider euch richten, daß ihr vor euren Feinden geschlagen werdet; und eure Hasser werden über euch herrschen, und ihr werdet fliehen, obwohl niemand euch jagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Und wenn ihr auf dieses hin mir nicht gehorchet, so werde ich euch siebenmal mehr züchtigen wegen eurer Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Und ich werde euren starren Hochmut brechen, und werde euren Himmel wie Eisen machen und eure Erde wie Erz;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'und eure Kraft wird sich umsonst verbrauchen, und euer Land wird seinen Ertrag nicht geben, und die Bäume des Feldes werden ihre Frucht nicht geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Und wenn ihr mir entgegen wandelt und mir nicht gehorchen wollt, so werde ich euch noch siebenmal mehr schlagen, nach euren Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Und ich werde das Getier des Feldes unter euch senden, daß es euch eurer Kinder beraube und euer Vieh ausrotte und euer weniger mache; und eure Straßen sollen öde werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Und wenn ihr euch durch dieses nicht von mir zurechtweisen laßt und mir entgegen wandelt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'so werde auch ich euch entgegen wandeln, und auch ich werde euch siebenfach schlagen wegen eurer Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Und ich werde das Schwert über euch bringen, das die Rache des Bundes vollzieht; und ziehet ihr euch in eure Städte zurück, so werde ich die Pest in eure Mitte senden, und ihr werdet in die Hand des Feindes gegeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Indem ich euch die Stütze des Brotes zerbreche, werden zehn Weiber euer Brot backen in einem Ofen, und sie werden euch das Brot zurückgeben nach dem Gewicht; und ihr werdet essen und nicht satt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Und wenn ihr bei alledem mir nicht gehorchet und mir entgegen wandelt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'so werde auch ich euch entgegen wandeln im Grimm, und werde euch siebenfach züchtigen wegen eurer Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Und ihr werdet das Fleisch eurer Söhne essen, und das Fleisch eurer Töchter werdet ihr essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Und ich werde eure Höhen vertilgen und eure Sonnensäulen ausrotten und werde eure Leichname auf die Leichname eurer Götzen werfen, und meine Seele wird euch verabscheuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Und ich werde eure Städte zur Öde machen und eure Heiligtümer verwüsten, und werde euren lieblichen Geruch nicht riechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Und ich werde das Land verwüsten, daß eure Feinde, die darin wohnen, sich darüber entsetzen sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Euch aber werde ich unter die Nationen zerstreuen, und ich werde das Schwert ziehen hinter euch her; und euer Land wird eine Wüste sein und eure Städte eine Öde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Dann wird das Land seine Sabbathe genießen alle die Tage seiner Verwüstung, während ihr im Lande eurer Feinde seid; dann wird das Land ruhen und seine Sabbathe genießen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'alle die Tage seiner Verwüstung wird es ruhen, was es nicht geruht hat in euren Sabbathen, als ihr darin wohntet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Und die Übriggebliebenen von euch, in ihr Herz werde ich Feigheit bringen in den Ländern ihrer Feinde: Und es wird sie jagen das Rauschen eines verwehten Blattes, und sie werden fliehen, wie man vor dem Schwerte flieht, und fallen, obwohl niemand sie jagt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'und sie werden einer über den anderen hinstürzen, wie vor dem Schwerte, obwohl niemand sie jagt; und ihr werdet nicht standhalten können vor euren Feinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Und ihr werdet umkommen unter den Nationen, und das Land eurer Feinde wird euch fressen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Und die Übriggebliebenen von euch werden in den Ländern eurer Feinde hinschwinden in ihrer Ungerechtigkeit, und auch in den Ungerechtigkeiten ihrer Väter mit ihnen hinschwinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Und sie werden ihre Ungerechtigkeit bekennen und die Ungerechtigkeit ihrer Väter infolge ihrer Treulosigkeit, die sie gegen mich begangen haben, und auch daß, weil sie mir entgegen gewandelt sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'auch ich ihnen entgegen wandelte und sie in das Land ihrer Feinde brachte. Wenn alsdann ihr unbeschnittenes Herz sich demütigt und sie dann die Strafe ihrer Ungerechtigkeit annehmen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'so werde ich meines Bundes mit Jakob gedenken; und auch meines Bundes mit Isaak und auch meines Bundes mit Abraham werde ich gedenken, und des Landes werde ich gedenken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Denn das Land wird von ihnen verlassen sein, und es wird seine Sabbathe genießen, in seiner Verwüstung ohne sie; und sie selbst werden die Strafe ihrer Ungerechtigkeit annehmen, darum, ja darum, daß sie meine Rechte verachtet und ihre Seele meine Satzungen verabscheut hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Aber selbst auch dann, wenn sie in dem Lande ihrer Feinde sind, werde ich sie nicht verachten und sie nicht verabscheuen, ihnen den Garaus zu machen, meinen Bund mit ihnen zu brechen; denn ich bin Jehova, ihr Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Und ich werde ihnen meines Bundes mit den Vorfahren gedenken, die ich aus dem Lande Ägypten vor den Augen der Nationen herausgeführt habe, um ihr Gott zu sein. Ich bin Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Das sind die Satzungen und die Rechte und die Gesetze, welche Jehova zwischen ihm und den Kindern Israel auf dem Berge Sinai durch Mose gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Rede zu den Kindern Israel und sprich zu ihnen: Wenn jemand ein Gelübde erfüllt, so sollen die Seelen nach deiner Schätzung für Jehova sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Und es sei deine Schätzung eines Mannes von zwanzig Jahren alt bis zu sechzig Jahren alt, und zwar sei deine Schätzung fünfzig Sekel Silber, nach dem Sekel des Heiligtums;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Und wenn es ein Weib ist, so sei deine Schätzung dreißig Sekel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Und wenn es von fünf Jahren alt bis zu zwanzig Jahren alt ist, so sei deine Schätzung einer männlichen Person zwanzig Sekel, und einer weiblichen zehn Sekel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Und wenn es von einem Monat alt bis zu fünf Jahren alt ist, so sei deine Schätzung eines Knaben fünf Sekel Silber, und deine Schätzung eines Mädchens drei Sekel Silber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'und wenn es von sechzig Jahren alt und darüber ist, so sei deine Schätzung, wenn es ein Mann ist, fünfzehn Sekel, und eines Weibes zehn Sekel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Und wenn der Gelobende zu arm ist für deine Schätzung, so soll man ihn vor den Priester stellen, und der Priester soll ihn schätzen; nach Verhältnis dessen, was die Hand des Gelobenden aufbringen kann, soll der Priester ihn schätzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Und wenn es ein Vieh ist, wovon man Jehova eine Opfergabe darbringt, so soll alles, was man Jehova davon gibt, heilig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Man soll es nicht auswechseln noch vertauschen, ein gutes um ein schlechtes, oder ein schlechtes um ein gutes; und wenn man dennoch Vieh um Vieh vertauscht, so wird dasselbe heilig und das eingetauschte heilig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Und wenn es irgend ein unreines Vieh ist, wovon man Jehova keine Opfergabe darbringt, so soll man das Vieh vor den Priester stellen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'und der Priester soll es schätzen, ob es gut oder schlecht sei; nach deiner, des Priesters, Schätzung, also soll es sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Wenn man es aber lösen will, so soll man zu deiner Schätzung ein Fünftel hinzufügen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Und wenn jemand sein Haus heiligt, daß es Jehova heilig sei, so soll es der Priester schätzen, ob es gut oder schlecht sei; so wie der Priester es schätzt, also soll es festgestellt sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Und wenn der Heiligende sein Haus lösen will, so soll er das Fünftel des Geldes deiner Schätzung darüber hinzufügen, und es soll ihm gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Und wenn jemand von dem Felde seines Eigentums Jehova heiligt, so soll deine Schätzung nach Verhältnis seiner Aussaat sein: ein Homer Gerste Aussaat zu fünfzig Sekel Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Wenn er vom Jubeljahre an sein Feld heiligt, so soll es nach deiner Schätzung festgestellt sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'und wenn er nach dem Jubeljahre sein Feld heiligt, so soll der Priester ihm das Geld berechnen nach dem Verhältnis der Jahre, die bis zum Jubeljahre übrig sind, und es soll von deiner Schätzung abgezogen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Wenn aber der Heiligende das Feld lösen will, so soll er das Fünftel des Geldes deiner Schätzung darüber hinzufügen, und es soll ihm verbleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Und wenn er das Feld nicht löst, oder wenn er das Feld einem anderen Manne verkauft, so kann es nicht wieder gelöst werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'und das Feld soll, wenn es im Jubeljahre frei ausgeht, Jehova heilig sein, wie ein verbanntes Feld; es soll dem Priester als Eigentum gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Und wenn er ein von ihm erkauftes Feld, das nicht zum Felde seines Eigentums gehört, Jehova heiligt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'so soll ihm der Priester den Betrag deiner Schätzung berechnen bis zum Jubeljahre; und er soll deine Schätzung am gleichen Tage, als ein dem Jehova Heiliges, entrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Im Jubeljahre soll das Feld wieder an den kommen, von welchem er es gekauft hatte, an den, welchem das Land eigentümlich gehörte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Und all deine Schätzung soll nach dem Sekel des Heiligtums geschehen; zwanzig Gera soll der Sekel sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Nur das Erstgeborene unter dem Vieh, das als Erstgeburt Jehova gehört, das soll kein Mensch heiligen; sei es ein Stück Rind-oder Kleinvieh, es gehört Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Wenn es aber vom unreinen Vieh ist, so soll man es lösen nach deiner Schätzung und dessen Fünftel darüber hinzufügen; und wenn es nicht gelöst wird, so soll es verkauft werden nach deiner Schätzung. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Jedoch alles Verbannte, das jemand dem Jehova verbannt, von allem, was sein ist, es seien Menschen oder Vieh oder Feld seines Eigentums, soll nicht verkauft und nicht gelöst werden; alles Verbannte ist dem Jehova hochheilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Alles, was an Menschen verbannt wird, soll nicht gelöst werden: es soll gewißlich getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Und aller Zehnte des Landes, vom Samen des Landes, von der Frucht der Bäume, gehört Jehova; er ist Jehova heilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Wenn aber jemand von seinem Zehnten lösen will, so soll er dessen Fünftel hinzufügen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Und aller Zehnte vom Rind-und Kleinvieh, von allem, was unter dem Stabe vorüberzieht, das Zehnte soll Jehova heilig sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'man soll nicht untersuchen, ob es gut oder schlecht sei, und soll es nicht vertauschen; und wenn man es dennoch vertauscht, so wird dasselbe heilig und das eingetauschte heilig sein; es soll nicht gelöst werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Das sind die Gebote, welche Jehova dem Mose auf dem Berge Sinai an die Kinder Israel aufgetragen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Und Jehova redete zu Mose in der Wüste Sinai im Zelte der Zusammenkunft, am Ersten des zweiten Monats, im zweiten Jahre nach ihrem Auszuge aus dem Lande Ägypten und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Nehmet auf die Summe der ganzen Gemeinde der Kinder Israel nach ihren Geschlechtern, nach ihren Vaterhäusern, nach der Zahl der Namen, alle Männlichen nach ihren Köpfen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'von zwanzig Jahren und darüber, jeden, der zum Heere auszieht in Israel, die sollt ihr mustern nach ihren Heeren, du und Aaron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Und je ein Mann für den Stamm soll bei euch sein, ein Mann, der das Haupt von seinem Vaterhause ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Und dies sind die Namen der Männer, die euch beistehen sollen: für Ruben: Elizur, der Sohn Schedeurs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'für Simeon: Schelumiel, der Sohn Zurischaddais;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'für Juda: Nachschon, der Sohn Amminadabs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'für Issaschar: Nethaneel, der Sohn Zuars;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'für Sebulon: Eliab, der Sohn Helons;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'für die Söhne Josephs: für Ephraim: Elischama, der Sohn Ammihuds; für Manasse: Gamliel, der Sohn Pedazurs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'für Benjamin: Abidan, der Sohn Gideonis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'für Dan: Achieser, der Sohn Ammischaddais;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'für Aser: Pagiel, der Sohn Okrans;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'für Gad: Eljasaph, der Sohn Deghuels;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'für Naphtali: Achira, der Sohn Enans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Das waren die Berufenen der Gemeinde, die Fürsten der Stämme ihrer Väter; sie waren die Häupter der Tausende Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Und Mose und Aaron nahmen diese mit Namen bezeichneten Männer,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'und sie versammelten die ganze Gemeinde am ersten des zweiten Monats. Und sie ließen sich in die Geburtsverzeichnisse eintragen nach ihren Geschlechtern, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren und darüber, nach ihren Köpfen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'wie Jehova dem Mose geboten hatte. Und so musterte er sie in der Wüste Sinai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Und es waren die Söhne Rubens, des Erstgeborenen Israels: ihre Geschlechter nach ihren Familien, nach ihren Vaterhäusern, nach der Zahl der Namen, nach ihren Köpfen, alle Männlichen von zwanzig Jahren und darüber, jeder, der zum Heere auszog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'ihre Gemusterten vom Stamme Ruben, sechsundvierzigtausend fünfhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Von den Söhnen Simeons: ihre Geschlechter nach ihren Familien, nach ihren Vaterhäusern, seine Gemusterten nach der Zahl der Namen, nach ihren Köpfen, alle Männlichen von zwanzig Jahren und darüber, jeder, der zum Heere auszog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'ihre Gemusterten vom Stamme Simeon, neunundfünfzigtausend dreihundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Von den Söhnen Gads: ihre Geschlechter nach ihren Familien, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren und darüber, jeder, der zum Heere auszog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'ihre Gemusterten vom Stamme Gad, fünfundvierzigtausend sechshundertfünfzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Von den Söhnen Judas: ihre Geschlechter nach ihren Familien, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren und darüber, jeder, der zum Heere auszog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'ihre Gemusterten vom Stamme Juda, vierundsiebzigtausend sechshundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Von den Söhnen Issaschars: ihre Geschlechter nach ihren Familien, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren und darüber, jeder, der zum Heere auszog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'ihre Gemusterten vom Stamme Issaschar, vierundfünfzigtausend vierhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Von den Söhnen Sebulons: ihre Geschlechter nach ihren Familien, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren und darüber, jeder, der zum Heere auszog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'die Gemusterten vom Stamme Sebulon, siebenundfünfzigtausend vierhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Von den Söhnen Josephs: von den Söhnen Ephraims: ihre Geschlechter nach ihren Familien nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren und darüber, jeder, der zum Heere auszog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'ihre Gemusterten vom Stamme Ephraim, vierzigtausend fünfhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Von den Söhnen Manasses: ihre Geschlechter nach ihren Familien, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren und darüber, jeder, der zum Heere auszog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'ihre Gemusterten vom Stamme Manasse, zweiunddreißigtausend zweihundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Von den Söhnen Benjamins: ihre Geschlechter nach ihren Familien, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren und darüber, jeder, der zum Heere auszog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'ihre Gemusterten vom Stamme Benjamin, fünfunddreißigtausend vierhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Von den Söhnen Dans: ihre Geschlechter nach ihren Familien, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren und darüber, jeder, der zum Heere auszog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'ihre Gemusterten vom Stamme Dan, zweiundsechzigtausend siebenhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Von den Söhnen Asers: ihre Geschlechter nach ihren Familien, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren und darüber, jeder, der zum Heere auszog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'ihre Gemusterten vom Stamme Aser, einundvierzigtausend fünfhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Die Söhne Naphtalis: ihre Geschlechter nach ihren Familien, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren und darüber, jeder, der zum Heere auszog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'ihre Gemusterten vom Stamme Naphtali, dreiundfünfzigtausend vierhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Das sind die Gemusterten, welche Mose und Aaron und die Fürsten Israels musterten, die zwölf Männer: es waren je ein Mann für sein Vaterhaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Und es waren alle Gemusterten der Kinder Israel, nach ihren Vaterhäusern, von zwanzig Jahren und darüber, jeder, der zum Heere auszog in Israel:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'es waren alle die Gemusterten sechshundertunddreitausend fünfhundertfünfzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Aber die Leviten nach dem Stamme ihrer Väter wurden nicht unter ihnen gemustert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Denn Jehova hatte zu Mose geredet und gesagt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Nur den Stamm Levi sollst du nicht mustern und ihre Summe nicht aufnehmen unter den Kindern Israel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'sondern bestelle du die Leviten über die Wohnung des Zeugnisses und über all ihr Gerät und über alles, was zu ihr gehört: Sie sollen die Wohnung und all ihr Gerät tragen, und sie sollen sie bedienen und sich rings um die Wohnung lagern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Und wenn die Wohnung aufbricht, sollen die Leviten sie abnehmen; und wenn die Wohnung sich lagert, sollen die Leviten sie aufrichten. Der Fremde aber, der herzunaht, soll getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Und die Kinder Israel sollen sich lagern, ein jeder in seinem Lager und ein jeder bei seinem Panier, nach ihren Heeren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Die Leviten aber sollen sich rings um die Wohnung des Zeugnisses lagern, daß nicht ein Zorn über die Gemeinde der Kinder Israel komme; und die Leviten sollen der Hut der Wohnung des Zeugnisses warten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Und die Kinder Israel taten nach allem was Jehova dem Mose geboten hatte; also taten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Und Jehova redete zu Mose und zu Aaron und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Die Kinder Israel sollen sich lagern, ein jeder bei seinem Panier, bei den Zeichen ihrer Vaterhäuser; dem Zelte der Zusammenkunft gegenüber sollen sie sich ringsum lagern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Und zwar die gegen Osten, gegen Sonnenaufgang Lagernden: das Panier des Lagers Judas, nach ihren Heeren; und der Fürst der Söhne Judas, Nachschon, der Sohn Amminadabs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'und sein Heer und ihre Gemusterten, vierundsiebzigtausend sechshundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Und die neben ihm Lagernden: der Stamm Issaschar; und der Fürst der Söhne Issaschars, Nethaneel, der Sohn Zuars;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'und sein Heer und dessen Gemusterte, vierundfünfzigtausend vierhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Der Stamm Sebulon; und der Fürst der Söhne Sebulons, Eliab, der Sohn Helons;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'und sein Heer und dessen Gemusterte, siebenundfünfzigtausend vierhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Alle Gemusterten vom Lager Judas: hundertsechsundachtzigtausend vierhundert, nach ihren Heeren; sie sollen zuerst aufbrechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Das Panier des Lagers Rubens gegen Süden, nach ihren Heeren; und der Fürst der Söhne Rubens, Elizur, der Sohn Schedeurs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'und sein Heer und dessen Gemusterte, sechsundvierzigtausend fünfhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Und die neben ihm Lagernden: der Stamm Simeon; und der Fürst der Söhne Simeons, Schelumiel, der Sohn Zurischaddais;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'und sein Heer und ihre Gemusterten, neunundfünfzigtausend dreihundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Und der Stamm Gad; und der Fürst der Söhne Gads, Eljasaph, der Sohn Reghuels;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'und sein Heer und ihre Gemusterten, fünfundvierzigtausend sechshundertfünfzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Alle Gemusterten vom Lager Rubens: hunderteinundfünfzigtausend vierhundertfünfzig nach ihren Heeren; und als die zweiten sollen sie aufbrechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Und dann soll das Zelt der Zusammenkunft aufbrechen, das Lager der Leviten in der Mitte der Lager; so wie sie lagern, also sollen sie aufbrechen, ein jeder an seiner Stelle, nach ihren Panieren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Das Panier des Lagers Ephraims, nach ihren Heeren, gegen Westen; und der Fürst der Söhne Ephraims, Elischama, der Sohn Ammihuds;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'und sein Heer und ihre Gemusterten, vierzigtausend fünfhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Und neben ihm der Stamm Manasse; und der Fürst der Söhne Manasses, Gamliel, der Sohn Pedazurs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'und sein Heer und ihre Gemusterten, zweiunddreißigtausend zweihundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Und der Stamm Benjamin; und der Fürst der Söhne Benjamins, Abidan, der Sohn Gideonis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'und sein Heer und ihre Gemusterten, fünfunddreißigtausend vierhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Alle Gemusterten vom Lager Ephraims: hundertachttausend einhundert, nach ihren Heeren; und als die dritten sollen sie aufbrechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Das Panier des Lagers Dans gegen Norden, nach ihren Heeren; und der Fürst der Söhne Dans, Achieser, der Sohn Ammischaddais;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'und sein Heer und ihre Gemusterten, zweiundsechzigtausend siebenhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Und die neben ihm Lagernden: der Stamm Aser; und der Fürst der Söhne Asers, Pagiel, der Sohn Okrans;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'und sein Heer und ihre Gemusterten, einundvierzigtausend fünfhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Und der Stamm Naphtali; und der Fürst der Söhne Naphtalis, Achira, der Sohn Enans;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'und sein Heer und ihre Gemusterten, dreiundfünfzigtausend vierhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Alle Gemusterten vom Lager Dans: hundertsiebenundfünfzigtausend sechshundert; sie sollen zuletzt aufbrechen nach ihren Panieren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Das sind die Gemusterten der Kinder Israel nach ihren Vaterhäusern. Alle Gemusterten der Lager, nach ihren Heeren, waren sechshundertdreitausend fünfhundertfünfzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Aber die Leviten wurden nicht unter den Kindern Israel gemustert, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Und die Kinder Israel taten nach allem, was Jehova dem Mose geboten hatte: also lagerten sie sich nach ihren Panieren, und also brachen sie auf, ein jeder nach seinen Geschlechtern, nach seinem Vaterhause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Und dies sind die Geschlechter Aarons und Moses, an dem Tage, da Jehova auf dem Berge Sinai mit Mose redete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Und dies sind die Namen der Söhne Aarons: der Erstgeborene Nadab, und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Das sind die Namen der Söhne Aarons, der gesalbten Priester, die geweiht worden waren, um den Priesterdienst auszuüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Und Nadab und Abihu starben vor Jehova, als sie in der Wüste Sinai fremdes Feuer vor Jehova darbrachten; und sie hatten keine Söhne. Und Eleasar und Ithamar übten den Priesterdienst vor ihrem Vater Aaron aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Laß den Stamm Levi herzunahen und stelle ihn vor Aaron, den Priester, daß sie ihm dienen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'und sie sollen seiner Hut warten und der Hut der ganzen Gemeinde vor dem Zelte der Zusammenkunft, um den Dienst der Wohnung zu verrichten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'und sie sollen warten aller Geräte des Zeltes der Zusammenkunft und der Hut der Kinder Israel, um den Dienst der Wohnung zu verrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Und du sollst die Leviten dem Aaron und seinen Söhnen geben; ganz zu eigen sind sie ihm gegeben von seiten der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Und Aaron und seine Söhne sollst du bestellen, daß sie ihres Priestertums warten. Der Fremde aber, der herzunaht, soll getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Und ich, siehe, ich habe die Leviten aus der Mitte der Kinder Israel genommen, anstatt aller Erstgeburt, welche die Mutter bricht unter den Kindern Israel; und die Leviten sollen mir gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Denn mein ist alle Erstgeburt: an dem Tage, da ich alle Erstgeburt im Lande Ägypten schlug, habe ich mir alle Erstgeburt in Israel geheiligt vom Menschen bis zum Vieh; mir sollen sie gehören, mir, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Und Jehova redete zu Mose in der Wüste Sinai und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Mustere die Söhne Levis nach ihren Vaterhäusern, nach ihren Familien; alle Männlichen von einem Monat und darüber sollst du sie mustern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Und Mose musterte sie nach dem Befehl Jehovas, so wie ihm geboten war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Und dies waren die Söhne Levis nach ihren Namen: Gerson und Kehath und Merari.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Und dies sind die Namen der Söhne Gersons nach ihren Familien: Libni und Simei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Und die Söhne Kehaths nach ihren Familien: Amram und Jizhar, Hebron und Ussiel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Und die Söhne Meraris nach ihren Familien: Machli und Muschi. Das sind die Familien Levis nach ihren Vaterhäusern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Von Gerson die Familie der Libniter und die Familie der Simeiter; das sind die Familien der Gersoniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Ihre Gemusterten nach der Zahl aller Männlichen von einem Monat und darüber, ihre Gemusterten: siebentausend fünfhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Die Familien der Gersoniter lagerten hinter der Wohnung gegen Westen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Und der Fürst des Vaterhauses der Gersoniter war Eljasaph, der Sohn Laels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Und die Hut der Söhne Gersons am Zelte der Zusammenkunft war: die Wohnung und das Zelt, seine Decke, und der Vorhang vom Eingang des Zeltes der Zusammenkunft,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'und die Umhänge des Vorhofs und der Vorhang vom Eingang des Vorhofs, der rings um die Wohnung und um den Altar ist, und seine Seile zu all seinem Dienst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Und von Kehath die Familie der Amramiter und die Familie der Jizhariter und die Familie der Hebroniter und die Familie der Ussieliter; das sind die Familien der Kehathiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Nach der Zahl aller Männlichen von einem Monat und darüber, achttausend sechshundert, welche der Hut des Heiligtums warteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Die Familien der Söhne Kehaths lagerten an der Seite der Wohnung gegen Süden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Und der Fürst des Vaterhauses der Familien der Kehathiter war Elizaphan, der Sohn Ussiels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Und ihre Hut war: die Lade und der Tisch und der Leuchter und die Altäre, und die Geräte des Heiligtums, mit welchen man den Dienst verrichtet, und der Vorhang, und dessen ganzer Dienst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Und der Fürst der Fürsten Levis war Eleasar, der Sohn Aarons, des Priesters; er war Aufseher über die, welche der Hut des Heiligtums warteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Von Merari die Familie der Machliter und die Familie der Muschiter: das sind die Familien Meraris.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Und ihre Gemusterten nach der Zahl aller Männlichen von einem Monat und darüber: sechstausend zweihundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Und der Fürst des Vaterhauses der Familien Meraris war Zuriel, der Sohn Abichails. Sie lagerten an der Seite der Wohnung gegen Norden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Und die Hut der Söhne Meraris war: die Bretter der Wohnung, und ihre Riegel und ihre Säulen und ihre Füße und alle ihre Geräte und ihr ganzer Dienst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'und die Säulen des Vorhofs ringsum und ihre Füße und ihre Pflöcke und ihre Seile.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Und die vor der Wohnung gegen Osten, vor dem Zelte der Zusammenkunft gegen Sonnenaufgang Lagernden waren Mose und Aaron und seine Söhne, welche der Hut des Heiligtums warteten, betreffs desjenigen, was den Kindern Israel oblag. Der Fremde aber, der herzunaht, soll getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Aller gemusterten Leviten, welche Mose und Aaron nach dem Befehl Jehovas nach ihren Familien musterten, aller Männlichen von einem Monat und darüber, waren zweiundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Und Jehova sprach zu Mose: Mustere alle männlichen Erstgeborenen der Kinder Israel, von einem Monat und darüber, und nimm die Zahl ihrer Namen auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Und du sollst die Leviten für mich, Jehova nehmen, anstatt aller Erstgeborenen unter den Kindern Israel, und das Vieh der Leviten anstatt alles Erstgeborenen unter dem Vieh der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Und Mose musterte, so wie Jehova ihm geboten hatte, alle Erstgeborenen unter den Kindern Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Und es waren aller männlichen Erstgeborenen, nach der Zahl der Namen, von einem Monat und darüber, nach ihren Gemusterten, zweiundzwanzigtausend zweihundertdreiundsiebzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Nimm die Leviten anstatt aller Erstgeborenen unter den Kindern Israel und das Vieh der Leviten anstatt ihres Viehes; und mir, sollen die Leviten gehören, mir, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Und was die Lösung der zweihundertdreiundsiebzig betrifft, welche von den Erstgeborenen der Kinder Israel überzählig sind über die Leviten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'so sollst du je fünf Sekel auf den Kopf nehmen; nach dem Sekel des Heiligtums sollst du sie nehmen, zwanzig Gera der Sekel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Und das Geld sollst du als Lösung der Überzähligen unter ihnen Aaron und seinen Söhnen geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Und Mose nahm das Lösegeld von denen, welche überzählig waren über die durch die Leviten Gelösten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'von den Erstgeborenen der Kinder Israel nahm er das Geld, tausend dreihundertfünfundsechzig Sekel, nach dem Sekel des Heiligtums.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Und Mose gab das Geld der Lösung Aaron und seinen Söhnen, nach dem Befehl Jehovas, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Und Jehova redete zu Mose und zu Aaron und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Nehmet auf die Summe der Söhne Kehaths aus der Mitte der Söhne Levis, nach ihren Familien, nach ihren Vaterhäusern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'von dreißig Jahren und darüber bis zu fünfzig Jahren, alle, welche in die Arbeit treten, um das Werk am Zelte der Zusammenkunft zu verrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Dies ist der Dienst der Söhne Kehaths am Zelte der Zusammenkunft: das Hochheilige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Und Aaron und seine Söhne sollen beim Aufbruch des Lagers hineingehen und den Scheidevorhang abnehmen und die Lade des Zeugnisses damit bedecken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'und sie sollen eine Decke von Dachsfell darüber legen und ein Tuch, ganz von blauem Purpur, oben darüber breiten und ihre Stangen daran tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Und über den Tisch der Schaubrote sollen sie ein Tuch von blauem Purpur breiten und darauf stellen die Schüsseln und Schalen und Spendschalen und die Kannen zum Trankopfer; und das beständige Brot soll auf demselben sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Und hierüber sollen sie ein Tuch von Karmesin breiten und es mit einer Decke von Dachsfell bedecken; und sie sollen seine Stangen daran tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Und sie sollen ein Tuch von blauem Purpur nehmen und den Leuchter des Lichts bedecken und seine Lampen und seine Lichtschneuzen und seine Löschnäpfe und alle seine Ölgefäße, womit man den Dienst an ihm verrichtet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Und sie sollen ihn und alle seine Geräte in eine Decke von Dachsfell tun und auf die Trage legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Und über den goldenen Altar sollen sie ein Tuch von blauem Purpur breiten und ihn mit einer Decke von Dachsfell bedecken und seine Stangen daran tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Und sie sollen alle Geräte des Dienstes nehmen, womit man den Dienst im Heiligtum verrichtet, und sie in ein Tuch von blauem Purpur legen und sie mit einer Decke von Dachsfell bedecken und auf die Trage legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Und sie sollen den Altar von der Fettasche reinigen und ein Tuch von rotem Purpur über ihn breiten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'und darauf legen alle seine Geräte, womit man den Dienst auf ihm verrichtet: die Kohlenpfannen und die Gabeln und die Schaufeln und die Sprengschalen, alle Geräte des Altars; und sie sollen eine Decke von Dachsfell darüber breiten und seine Stangen daran tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Und wenn Aaron und seine Söhne beim Aufbruch des Lagers das Bedecken des Heiligtums und aller Geräte des Heiligtums vollendet haben, so sollen danach die Söhne Kehaths kommen, um es zu tragen, damit sie das Heilige nicht anrühren und sterben. Das ist es, was die Söhne Kehaths vom Zelte der Zusammenkunft zu tragen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Und Eleasar, der Sohn Aarons, des Priesters, hat die Aufsicht über das Öl zum Licht und das wohlriechende Räucherwerk und das beständige Speisopfer und das Salböl, die Aufsicht über die ganze Wohnung und alles, was darin ist, über das Heiligtum wie über seine Geräte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Und Jehova redete zu Mose und zu Aaron und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Ihr sollt den Stamm der Familien der Kehathiter nicht ausgerottet werden lassen aus der Mitte der Leviten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'sondern dies sollt ihr ihnen tun, damit sie leben und nicht sterben, wenn sie dem Allerheiligsten nahen: Aaron und seine Söhne sollen hineingehen und jeden einzelnen von ihnen an seinen Dienst und an seine Traglast stellen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'aber sie sollen nicht hineingehen, daß sie auch nur einen Augenblick das Heilige sehen und sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Nimm auch die Summe der Söhne Gersons auf, nach ihren Vaterhäusern, nach ihren Familien;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'von dreißig Jahren und darüber bis zu fünfzig Jahren sollst du sie mustern, alle, welche in die Arbeit treten, um den Dienst am Zelte der Zusammenkunft zu verrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Dies ist der Dienst der Familien der Gersoniter im Dienen und im Tragen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Sie sollen die Teppiche der Wohnung tragen und das Zelt der Zusammenkunft, seine Decke und die Decke von Dachsfell, die oben darüber ist, und den Vorhang vom Eingang des Zeltes der Zusammenkunft,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'und die Umhänge des Vorhofs und den Vorhang vom Eingang des Tores des Vorhofs, welcher rings um die Wohnung und um den Altar ist, und ihre Seile, und alle Geräte ihres Dienstes; und alles, was an ihnen zu tun ist, sollen sie verrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Nach dem Befehl Aarons und seiner Söhne soll aller Dienst der Söhne der Gersoniter sein hinsichtlich all ihrer Traglast und all ihres Dienstes; und ihr sollt ihnen die Hut alles dessen auftragen, was sie zu tragen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Das ist der Dienst der Familien der Söhne der Gersoniter am Zelte der Zusammenkunft; und ihre Hut sei unter der Hand Ithamars, des Sohnes Aarons, des Priesters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Die Söhne Meraris, nach ihren Familien, nach ihren Vaterhäusern sollst du sie mustern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'von dreißig Jahren und darüber bis zu fünfzig Jahren sollst du sie mustern, alle, welche in die Arbeit treten, um den Dienst am Zelte der Zusammenkunft zu verrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Und dies ist es, was ihnen zu tragen obliegt, nach ihrem ganzen Dienst am Zelte der Zusammenkunft: die Bretter der Wohnung und ihre Riegel und ihre Säulen und ihre Füße,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'und die Säulen des Vorhofs ringsum und ihre Füße und ihre Pflöcke und ihre Seile, nach allen ihren Geräten und nach all ihrem Dienst; und mit Namen sollt ihr ihnen die Geräte zuzählen, die ihnen zu tragen obliegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Das ist der Dienst der Familien der Söhne Meraris, nach all ihrem Dienst am Zelte der Zusammenkunft, unter der Hand Ithamars, des Sohnes Aarons, des Priesters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Und Mose und Aaron und die Fürsten der Gemeinde musterten die Söhne der Kehathiter nach ihren Familien und nach ihren Vaterhäusern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'von dreißig Jahren und darüber bis zu fünfzig Jahren, alle, welche in die Arbeit traten zum Dienst am Zelte der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Und es waren ihrer Gemusterten, nach ihren Familien, zweitausend siebenhundertfünfzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Das sind die Gemusterten der Familien der Kehathiter, alle, welche am Zelte der Zusammenkunft dienten, die Mose und Aaron musterten nach dem Befehl Jehovas durch Mose.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Und die Gemusterten der Söhne Gersons, nach ihren Familien und nach ihren Vaterhäusern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'von dreißig Jahren und darüber bis zu fünfzig Jahren, alle, welche in die Arbeit traten zum Dienst am Zelte der Zusammenkunft:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'es waren ihrer Gemusterten, nach ihren Familien, nach ihren Vaterhäusern, zweitausend sechshundertdreißig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Das sind die Gemusterten der Familien der Söhne Gersons, alle, welche am Zelte der Zusammenkunft dienten, die Mose und Aaron musterten nach dem Befehl Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Und die Gemusterten der Familien der Söhne Meraris, nach ihren Familien, nach ihren Vaterhäusern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'von dreißig Jahren und darüber bis zu fünfzig Jahren, alle, welche in die Arbeit traten zum Dienst am Zelte der Zusammenkunft:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'es waren ihrer Gemusterten, nach ihren Familien, dreitausend zweihundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Das sind die Gemusterten der Familien der Söhne Meraris, die Mose und Aaron musterten nach dem Befehl Jehovas durch Mose.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Aller Gemusterten, welche Mose und Aaron und die Fürsten Israels musterten, der Leviten nach ihren Familien und nach ihren Vaterhäusern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'von dreißig Jahren und darüber bis zu fünfzig Jahren, aller, welche antraten, um den Dienst der Bedienung und den Dienst des Tragens am Zelte der Zusammenkunft zu verrichten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'ihrer Gemusterten waren achttausend fünfhundertachtzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Nach dem Befehl Jehovas musterte man sie durch Mose, jeden einzelnen zu seinem Dienst und zu seiner Traglast; und sie wurden von ihm gemustert, wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Gebiete den Kindern Israel, daß sie alle Aussätzigen und alle Flüssigen und alle wegen einer Leiche Verunreinigten aus dem Lager hinauszutun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'sowohl Mann als Weib sollt ihr hinaustun, vor das Lager sollt ihr sie hinaustun, damit sie nicht ihre Lager verunreinigen, in deren Mitte ich wohne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Und die Kinder Israel taten also und taten sie vor das Lager hinaus; so wie Jehova zu Mose geredet hatte, also taten die Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Rede zu den Kindern Israel: Wenn ein Mann oder ein Weib irgend eine von allen Sünden der Menschen tun, so daß sie eine Untreue gegen Jehova begehen, und selbige Seele sich verschuldet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'so sollen sie ihre Sünde bekennen, die sie getan haben; und der Täter soll seine Schuld erstatten nach ihrer vollen Summe und soll das Fünftel davon hinzufügen und es dem geben, an welchem er sich verschuldet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Und wenn der Mann keinen Blutsverwandten hat, um diesem die Schuld zu erstatten, so soll die Schuld, welche Jehova erstattet wird, dem Priester gehören außer dem Widder der Versöhnung, womit man Sühnung für ihn tut. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Und jedes Hebopfer von allen heiligen Dingen der Kinder Israel, welche sie dem Priester darbringen, soll ihm gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Ja, ihm sollen eines jeden heilige Dinge gehören; was jemand dem Priester gibt, soll ihm gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Rede zu den Kindern Israel und sprich zu ihnen: Wenn irgend eines Mannes Weib ausschweift und Untreue gegen ihn begeht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'und ein Mann liegt bei ihr zur Begattung, und es ist verborgen vor den Augen ihres Mannes, und sie hat sich im geheimen verunreinigt, und es ist kein Zeuge gegen sie, und sie ist nicht ertappt worden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'und der Geist der Eifersucht kommt über ihn, und er wird eifersüchtig auf sein Weib, und sie hat sich verunreinigt; oder der Geist der Eifersucht kommt über ihn, und er wird eifersüchtig auf sein Weib, und sie hat sich nicht verunreinigt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'so soll der Mann sein Weib zu dem Priester bringen und ihre Opfergabe ihrethalben bringen, ein Zehntel Epha Gerstenmehl; er soll kein Öl darauf gießen und keinen Weihrauch darauf legen; denn es ist ein Speisopfer der Eifersucht, ein Speisopfer des Gedächtnisses, welches Ungerechtigkeit ins Gedächtnis bringt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Und der Priester soll sie herzunahen lassen und sie vor Jehova stellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Und der Priester nehme heiliges Wasser in einem irdenen Gefäße; und der Priester nehme von dem Staube, der auf dem Fußboden der Wohnung ist, und tue ihn in das Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Und der Priester stelle das Weib vor Jehova und entblöße das Haupt des Weibes, und lege auf ihre Hände das Speisopfer des Gedächtnisses; es ist ein Speisopfer der Eifersucht; und das fluchbringende Wasser der Bitterkeit soll in der Hand des Priesters sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Und der Priester soll sie beschwören und zu dem Weibe sagen: Wenn kein Mann bei dir gelegen hat, und wenn du, unter deinem Manne seiend, nicht ausgeschweift bist in Unreinigkeit, so bleibe unversehrt von diesem fluchbringenden Wasser der Bitterkeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'wenn du aber, unter deinem Manne seiend, ausgeschweift bist und dich verunreinigt hast, und ein Mann bei dir gelegen hat außer deinem Manne, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'und zwar soll der Priester das Weib beschwören mit dem Schwure des Fluches, und der Priester soll zu dem Weibe sagen: So mache dich Jehova zum Fluche und zum Schwure in der Mitte deines Volkes, indem Jehova deine Hüfte schwinden und deinen Bauch schwellen mache,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'und es komme dieses fluchbringende Wasser in deine Eingeweide, um den Bauch schwellen und die Hüfte schwinden zu machen! Und das Weib soll sagen: Amen, Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Und der Priester soll diese Flüche in ein Buch schreiben und sie in das Wasser der Bitterkeit auslöschen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'und er soll das Weib das fluchbringende Wasser der Bitterkeit trinken lassen, damit das fluchbringende Wasser in sie komme zur Bitterkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Und der Priester nehme aus der Hand des Weibes das Speisopfer der Eifersucht und webe das Speisopfer vor Jehova und bringe es zum Altar;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'und der Priester nehme eine Handvoll von dem Speisopfer als dessen Gedächtnisteil und räuchere es auf dem Altar; und danach soll er das Weib das Wasser trinken lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Und hat er sie das Wasser trinken lassen, so wird es geschehen, wenn sie sich verunreinigt und Untreue begangen hat gegen ihren Mann, daß das fluchbringende Wasser in sie kommen wird zur Bitterkeit, und ihr Bauch wird schwellen und ihre Hüfte schwinden; und das Weib wird zum Fluche werden in der Mitte ihres Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Wenn aber das Weib sich nicht verunreinigt hat und rein ist, so wird sie unversehrt bleiben und Samen empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Das ist das Gesetz der Eifersucht: Wenn ein Weib, unter ihrem Manne seiend, ausschweift und sich verunreinigt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'oder wenn über einen Mann der Geist der Eifersucht kommt, und er wird eifersüchtig auf sein Weib, so soll er das Weib vor Jehova stellen, und der Priester soll ihr tun nach diesem, ganzen Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Und der Mann wird frei sein von Schuld; selbiges Weib aber soll ihre Missetat tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Rede zu den Kindern Israel und sprich zu ihnen: Wenn ein Mann oder ein Weib sich weiht, indem er das Gelübde eines Nasirs gelobt, um sich für Jehova abzusondern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'so soll er sich des Weines und des starken Getränks enthalten: Essig von Wein und Essig von starkem Getränk soll er nicht trinken; und keinerlei Traubensaft soll er trinken, und Trauben, frische oder getrocknete, soll er nicht essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Alle die Tage seiner Absonderung soll er von allem, was vom Weinstock bereitet wird, von den Kernen bis zur Hülse, nicht essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Alle die Tage des Gelübdes seiner Absonderung soll kein Schermesser über sein Haupt gehen; bis die Tage erfüllt sind, die er sich für Jehova absondert, soll er heilig sein; er soll das Haar seines Hauptes frei wachsen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Alle die Tage, die er sich für Jehova absondert, soll er zu keiner Leiche kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Wegen seines Vaters und wegen seiner Mutter, wegen seines Bruders und wegen seiner Schwester, ihretwegen soll er sich nicht verunreinigen, wenn sie sterben; denn die Weihe seines Gottes ist auf seinem Haupte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Alle die Tage seiner Absonderung ist er dem Jehova heilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Und wenn jemand unversehens, plötzlich, bei ihm stirbt, und er das Haupt seiner Weihe verunreinigt, so soll er sein Haupt an dem Tage seiner Reinigung scheren; am siebten Tage soll er es scheren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Und am achten Tage soll er zwei Turteltauben oder zwei junge Tauben zu dem Priester bringen an den Eingang des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Und der Priester soll eine zum Sündopfer und eine zum Brandopfer opfern, und Sühnung für ihn tun deswegen, daß er sich an der Leiche versündigt hat; und er soll sein Haupt an selbigem Tage heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Und er soll die Tage seiner Absonderung nochmals für Jehova absondern und ein einjähriges Lamm zum Schuldopfer bringen; die vorigen Tage aber sind verfallen, denn seine Weihe ist verunreinigt worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Und dies ist das Gesetz des Nasirs: An dem Tage, an welchem die Tage seiner Absonderung erfüllt sind, soll man ihn an den Eingang des Zeltes der Zusammenkunft bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Und er soll Jehova seine Opfergabe darbringen: ein einjähriges Lamm ohne Fehl zum Brandopfer, und ein einjähriges weibliches Lamm ohne Fehl zum Sündopfer; und einen Widder ohne Fehl zum Friedensopfer,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'und einen Korb mit Ungesäuertem: Feinmehlkuchen, gemengt mit Öl, und ungesäuerte Fladen, gesalbt mit Öl; nebst ihrem Speisopfer und ihren Trankopfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Und der Priester soll sie vor Jehova darbringen und sein Sündopfer und sein Brandopfer opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Und den Widder soll er als Friedensopfer dem Jehova opfern samt dem Korbe des Ungesäuerten; und der Priester soll dessen Speisopfer und dessen Trankopfer opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Und der Nasir soll an dem Eingang des Zeltes der Zusammenkunft das Haupt seiner Weihe scheren und das Haar des Hauptes seiner Weihe nehmen und es auf das Feuer legen, das unter dem Friedensopfer ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Und der Priester nehme den gekochten Bug von dem Widder und einen ungesäuerten Kuchen und einen ungesäuerten Fladen aus dem Korbe und lege sie auf die Hände des Nasirs, nachdem er das Zeichen seiner Weihe geschoren hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Und der Priester webe sie als Webopfer vor Jehova; es ist dem Priester heilig nebst der Brust des Webopfers und nebst dem Schenkel des Hebopfers. Und danach mag der Nasir Wein trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Das ist das Gesetz des Nasirs, der ein Gelübde tut, und das seine Opfergabe dem Jehova wegen seiner Weihe, außer dem, was seine Hand aufbringen kann. Gemäß seinem Gelübde, das er getan hat, also soll er tun nach dem Gesetz seiner Weihe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Rede zu Aaron und zu seinen Söhnen und sprich: So sollt ihr die Kinder Israel segnen; sprechet zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Jehova segne dich und behüte dich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Jehova lasse sein Angesicht über dir leuchten und sei dir gnädig!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Jehova erhebe sein Angesicht auf dich und gebe dir Frieden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Und so sollen sie meinen Namen auf die Kinder Israel legen, und ich werde sie segnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Und es geschah an dem Tage, da Mose das Aufrichten der Wohnung vollendet und sie gesalbt und sie geheiligt hatte mit allen ihren Geräten, sowie den Altar und alle seine Geräte, und er sie gesalbt und sie geheiligt hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'da brachten die Fürsten Israels, die Häupter ihrer Vaterhäuser, sie, die Fürsten der Stämme, die Vorsteher der Gemusterten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'sie brachten ihre Opfergabe dar vor Jehova: sechs bedeckte Wagen und zwölf Rinder, einen Wagen für zwei Fürsten und ein Rind für einen; und sie brachten sie dar vor der Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Nimm sie von Ihnen, und sie seien zum Verrichten des Dienstes des Zeltes der Zusammenkunft, und gib sie den Leviten, einem jeden nach Verhältnis seines Dienstes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Und Mose nahm die Wagen und die Rinder und gab sie den Leviten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Zwei Wagen und vier Rinder gab er den Söhnen Gersons nach Verhältnis ihres Dienstes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'und vier Wagen und acht Rinder gab er den Söhnen Meraris nach Verhältnis ihres Dienstes: unter der Hand Ithamars, des Sohnes Aarons, des Priesters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Aber den Söhnen Kehaths gab er nichts; denn ihnen lag der Dienst des Heiligtums ob: auf der Schulter trugen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Und die Fürsten brachten die Einweihungsgabe des Altars dar an dem Tage, da er gesalbt wurde; und die Fürsten brachten ihre Opfergabe dar vor dem Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Und Jehova sprach zu Mose: Je ein Fürst auf einen Tag sollen sie ihre Opfergabe zur Einweihung des Altars darbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Und es geschah, der am ersten Tage seine Opfergabe darbrachte, war Nachschon, der Sohn Amminadabs, vom Stamme Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Und seine Opfergabe war: eine silberne Schüssel, hundertdreißig Sekel ihr Gewicht, eine silberne Sprengschale, siebzig Sekel, nach dem Sekel des Heiligtums, beide voll Feinmehl, gemengt mit Öl, zum Speisopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'eine Schale, zehn Sekel Gold, voll Räucherwerk;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'ein junger Farre, ein Widder, ein einjähriges Lamm, zum Brandopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'und zum Friedensopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Opfergabe Nachschons, des Sohnes Amminadabs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Am zweiten Tage brachte Nethaneel dar, der Sohn Zuars, der Fürst von Issaschar;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'er brachte seine Opfergabe dar: eine silberne Schüssel, hundertdreißig Sekel ihr Gewicht, eine silberne Sprengschale, siebzig Sekel, nach dem Sekel des Heiligtums, beide voll Feinmehl, gemengt mit Öl, zum Speisopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'eine Schale, zehn Sekel Gold, voll Räucherwerk;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'einen jungen Farren, einen Widder, ein einjähriges Lamm, zum Brandopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'einen Ziegenbock zum Sündopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'und zum Friedensopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Opfergabe Nethaneels, des Sohnes Zuars.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Am dritten Tage der Fürst der Söhne Sebulons, Eliab, der Sohn Helons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Seine Opfergabe war: eine silberne Schüssel, hundertdreißig Sekel ihr Gewicht, eine silberne Sprengschale, siebzig Sekel, nach dem Sekel des Heiligtums, beide voll Feinmehl, gemengt mit Öl, zum Speisopfer;');
