INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Am vierten Tage der Fürst der Söhne Rubens, Elizur, der Sohn Schedeurs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Seine Opfergabe war: eine silberne Schüssel, hundertdreißig Sekel ihr Gewicht, eine silberne Sprengschale, siebzig Sekel, nach dem Sekel des Heiligtums, beide voll Feinmehl, gemengt mit Öl, zum Speisopfer;');
