INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Am fünften Tage der Fürst der Söhne Simeons, Schelumiel, der Sohn Zurischaddais.');
