INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'und zum Friedensopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Opfergabe Gamliels, des Sohnes Pedazurs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Am neunten Tage der Fürst der Söhne Benjamins, Abidan, der Sohn Gideonis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Seine Opfergabe war: eine silberne Schüssel, hundertdreißig Sekel ihr Gewicht, eine silberne Sprengschale, siebzig Sekel, nach dem Sekel des Heiligtums, beide voll Feinmehl, gemengt mit Öl, zum Speisopfer;');
