INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Am elften Tage der Fürst der Söhne Asers, Pagiel, der Sohn Okrans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Seine Opfergabe war: eine silberne Schüssel, hundertdreißig Sekel ihr Gewicht, eine silberne Sprengschale, siebzig Sekel, nach dem Sekel des Heiligtums, beide voll Feinmehl, gemengt mit Öl, zum Speisopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'eine Schale, zehn Sekel Gold, voll Räucherwerk;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'ein junger Farre, ein Widder, ein einjähriges Lamm, zum Brandopfer;');
