INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'und zum Friedensopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Opfergabe Pagiels, des Sohnes Okrans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Am zwölften Tage der Fürst der Söhne Naphtalis, Achira, der Sohn Enans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Seine Opfergabe war: eine silberne Schüssel, hundertdreißig Sekel ihr Gewicht, eine silberne Sprengschale, siebzig Sekel, nach dem Sekel des Heiligtums, beide voll Feinmehl, gemengt mit Öl, zum Speisopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'eine Schale, zehn Sekel Gold, voll Räucherwerk;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'ein junger Farre, ein Widder, ein einjähriges Lamm, zum Brandopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'und zum Friedensopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Opfergabe Achiras, des Sohnes Enans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Dies war die Einweihungsgabe des Altars, seitens der Fürsten Israels, an dem Tage, da er gesalbt wurde: zwölf silberne Schüsseln, zwölf silberne Sprengschalen, zwölf goldene Schalen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'hundertdreißig Sekel eine silberne Schüssel, und siebzig eine Sprengschale: alles Silber der Gefäße zweitausend vierhundert Sekel, nach dem Sekel des Heiligtums;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'zwölf goldene Schalen voll Räucherwerk, je zehn Sekel eine Schale, nach dem Sekel des Heiligtums: alles Gold der Schalen hundertzwanzig Sekel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Aller Rinder zum Brandopfer waren zwölf Farren; dazu zwölf Widder, zwölf einjährige Lämmer, nebst ihrem Speisopfer; und zwölf Ziegenböcke zum Sündopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Und aller Rinder zum Friedensopfer waren vierundzwanzig Farren; dazu sechzig Widder, sechzig Böcke, sechzig einjährige Lämmer. Das war die Einweihungsgabe des Altars, nachdem er gesalbt worden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Und wenn Mose in das Zelt der Zusammenkunft hineinging, um mit ihm zu reden, so hörte er die Stimme zu ihm reden von dem Deckel herab, der auf der Lade des Zeugnisses war, zwischen den beiden Cherubim hervor; und er redete zu ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Rede zu Aaron und sprich zu ihm: Wenn du die Lampen anzündest, so sollen die sieben Lampen gerade vor dem Leuchter hinscheinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Und Aaron tat also: er zündete seine Lampen an, so daß sie gerade vor dem Leuchter hinschienen, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Und dies war die Arbeit des Leuchters: getriebene Arbeit von Gold; von seinem Fuße bis zu seinen Blumen, alles war getriebene Arbeit; nach dem Bilde, das Jehova dem Mose gezeigt, also hatte man den Leuchter gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Nimm die Leviten aus der Mitte der Kinder Israel und reinige sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Und also sollst du mit ihnen tun, um sie zu reinigen: Sprenge Entsündigungswasser auf sie, und sie sollen das Schermesser über ihr ganzes Fleisch gehen lassen und ihre Kleider waschen und sich reinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Und sie sollen einen jungen Farren nehmen, und sein Speisopfer: Feinmehl, gemengt mit Öl; und einen anderen jungen Farren sollst du nehmen zum Sündopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Und du sollst die Leviten vor das Zelt der Zusammenkunft herzutreten lassen und die ganze Gemeinde der Kinder Israel versammeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Und du sollst die Leviten vor Jehova herzutreten lassen, und die Kinder Israel sollen ihre Hände auf die Leviten legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Und Aaron soll die Leviten als Webopfer von seiten der Kinder Israel vor Jehova weben, damit sie zum Verrichten des Dienstes Jehovas seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Und die Leviten sollen ihre Hände auf den Kopf der Farren legen; und den einen sollst du als Sündopfer und den anderen als Brandopfer dem Jehova opfern, um für die Leviten Sühnung zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Und so sollst du die Leviten vor Aaron und vor seine Söhne stellen und sie dem Jehova als Webopfer weben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'und du sollst die Leviten aus der Mitte der Kinder Israel aussondern, daß die Leviten mir gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Und danach sollen die Leviten kommen, um das Zelt der Zusammenkunft zu bedienen. So sollst du sie reinigen und sie als Webopfer weben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Denn sie sind mir ganz zu eigen gegeben aus der Mitte der Kinder Israel; anstatt alles dessen, was die Mutter bricht, anstatt jedes Erstgeborenen aus den Kindern Israel habe ich sie mir genommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Denn mein ist alles Erstgeborene unter den Kindern Israel an Menschen und an Vieh. An dem Tage, da ich alle Erstgeburt im Lande Ägypten schlug, habe ich sie mir geheiligt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Und ich habe die Leviten genommen anstatt aller Erstgeborenen unter den Kindern Israel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'und ich habe die Leviten dem Aaron und seinen Söhnen als Gabe aus der Mitte der Kinder Israel gegeben, um den Dienst der Kinder Israel am Zelte der Zusammenkunft zu verrichten und um für die Kinder Israel Sühnung zu tun, damit unter den Kindern Israel keine Plage dadurch entstehe, daß die Kinder Israel dem Heiligtum nahen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Und Mose und Aaron und die ganze Gemeinde der Kinder Israel taten so mit den Leviten; nach allem, was Jehova dem Mose geboten hatte wegen der Leviten, also taten die Kinder Israel mit ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Und die Leviten entsündigten sich und wuschen ihre Kleider; und Aaron webte sie als Webopfer vor Jehova; und Aaron tat Sühnung für sie zu ihrer Reinigung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Und danach kamen die Leviten, um ihren Dienst am Zelte der Zusammenkunft zu verrichten vor Aaron und vor seinen Söhnen. So wie Jehova dem Mose betreffs der Leviten geboten hatte, also taten sie mit ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Dies ist es, was die Leviten betrifft: Von fünfundzwanzig Jahren an und darüber soll er eintreten, um die Arbeit zu tun im Dienste des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Aber von fünfzig Jahren an soll er aus der Arbeit des Dienstes austreten und nicht mehr dienen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'er mag seinen Brüdern helfen am Zelte der Zusammenkunft, um der Hut zu warten; aber Dienst soll er nicht tun. So sollst du mit den Leviten tun in ihren Obliegenheiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Und Jehova redete zu Mose in der Wüste Sinai, im zweiten Jahre nach ihrem Auszug aus dem Lande Ägypten, im ersten Monat, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Die Kinder Israel sollen das Passah feiern zu seiner bestimmten Zeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'am vierzehnten Tage in diesem Monat, zwischen den zwei Abenden, sollt ihr es feiern zu seiner bestimmten Zeit; nach allen seinen Satzungen und nach allen seinen Vorschriften sollt ihr es feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Und Mose redete zu den Kindern Israel, daß sie das Passah feiern sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Und sie feierten das Passah im ersten Monat, am vierzehnten Tage des Monats, zwischen den zwei Abenden, in der Wüste Sinai; nach allem, was Jehova dem Mose geboten hatte, also taten die Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Und es waren Männer da, die unrein waren wegen der Leiche eines Menschen und an jenem Tage das Passah nicht feiern konnten; und sie traten an jenem Tage vor Mose und vor Aaron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Und diese Männer sprachen zu ihm: Wir sind unrein wegen der Leiche eines Menschen; warum sollen wir verkürzt werden, daß wir die Opfergabe Jehovas nicht zur bestimmten Zeit in der Mitte der Kinder Israel darbringen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Und Mose sprach zu ihnen: Bleibet stehen, und ich will hören, was Jehova eurethalben gebieten wird. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Rede zu den Kindern Israel und sprich: Wenn irgend jemand von euch oder von euren Geschlechtern unrein ist wegen einer Leiche oder ist auf einem fernen Wege, so soll er dem Jehova Passah feiern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'im zweiten Monat, am vierzehnten Tage, zwischen den zwei Abenden, sollen sie es feiern; mit Ungesäuertem und bitteren Kräutern sollen sie es essen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'sie sollen nichts davon übrig lassen bis an den Morgen, und sollen kein Bein an ihm zerbrechen; nach allen Satzungen des Passah sollen sie es feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Der Mann aber, der rein und nicht auf dem Wege ist, und es unterläßt, das Passah zu feiern, selbige Seele soll ausgerottet werden aus ihren Völkern; denn er hat die Opfergabe Jehovas nicht zur bestimmten Zeit dargebracht; selbiger Mann soll seine Sünde tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Und wenn ein Fremdling bei euch weilt und dem Jehova Passah feiern will, so soll er es feiern nach der Satzung des Passah und nach seiner Vorschrift. Eine Satzung soll für euch sein, sowohl für den Fremdling als auch für den Eingeborenen des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Und an dem Tage, da die Wohnung aufgerichtet wurde, bedeckte die Wolke die Wohnung des Zeltes des Zeugnisses; und am Abend war es über der Wohnung wie das Ansehen eines Feuers bis an den Morgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'So war es beständig: die Wolke bedeckte sie, und des Nachts war es wie das Ansehen eines Feuers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Und so wie die Wolke sich von dem Zelte erhob, brachen danach die Kinder Israel auf; und an dem Orte, wo die Wolke sich niederließ, daselbst lagerten sich die Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Nach dem Befehl Jehovas brachen die Kinder Israel auf, und nach dem Befehl Jehovas lagerten sie sich; alle die Tage, da die Wolke auf der Wohnung ruhte, lagerten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Und wenn die Wolke viele Tage auf der Wohnung verweilte, so warteten die Kinder Israel der Hut Jehovas und brachen nicht auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Und geschah es, daß die Wolke wenige Tage auf der Wohnung war, nach dem Befehl Jehovas lagerten sie sich, und nach dem Befehl Jehovas brachen sie auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Und geschah es, daß die Wolke da war vom Abend bis an den Morgen, und die Wolke erhob sich am Morgen, so brachen sie auf; oder einen Tag und eine Nacht, und die Wolke erhob sich, so brachen sie auf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'oder zwei Tage oder einen Monat oder eine geraume Zeit, wenn die Wolke auf der Wohnung verweilte, indem sie darauf ruhte, so lagerten die Kinder Israel und brachen nicht auf; und wenn sie sich erhob, so brachen sie auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Nach dem Befehl Jehovas lagerten sie sich, und nach dem Befehl Jehovas brachen sie auf; sie warteten der Hut Jehovas nach dem Befehl Jehovas durch Mose.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Und Jehova redete zu Mose sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Mache dir zwei Trompeten von Silber; in getriebener Arbeit sollst du sie machen; und sie sollen dir dienen zur Berufung der Gemeinde und zum Aufbruch der Lager.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Und stößt man in dieselben, so soll die ganze Gemeinde sich zu dir versammeln an den Eingang des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Und wenn man in eine stößt, so sollen die Fürsten sich zu dir versammeln, die Häupter der Tausende Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Und blaset ihr Lärm, so sollen die Lager aufbrechen, die gegen Osten lagern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'und blaset ihr Lärm zum zweiten Male, so sollen die Lager aufbrechen, die gegen Süden lagern: zu ihrem Aufbruch sollen sie Lärm blasen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Aber um die Versammlung zu versammeln, sollt ihr hineinstoßen und nicht Lärm blasen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Und die Söhne Aarons, die Priester, sollen in die Trompeten stoßen. Und sie sollen euch zu einer ewigen Satzung sein bei euren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Und wenn ihr in eurem Lande in den Streit ziehet wider den Bedränger, der euch bedrängt, so sollt ihr mit den Trompeten Lärm blasen; und es wird eurer gedacht werden vor Jehova, eurem Gott, und ihr werdet gerettet werden vor euren Feinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Und an euren Freudentagen und an euren Festen und an euren Neumonden, da sollt ihr in die Trompeten stoßen bei euren Brandopfern und bei euren Friedensopfern; und sie sollen euch zum Gedächtnis sein vor eurem Gott. Ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Und es geschah im zweiten Jahre, im zweiten Monat, am Zwanzigsten des Monats, da erhob sich die Wolke von der Wohnung des Zeugnisses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Und die Kinder Israel brachen auf aus der Wüste Sinai nach ihren Zügen; und die Wolke ließ sich nieder in der Wüste Paran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Und sie brachen zum ersten Male auf nach dem Befehl Jehovas durch Mose.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Und das Panier des Lagers der Kinder Juda brach zuerst auf nach ihren Heeren; und über sein Heer war Nachschon, der Sohn Amminadabs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Und über das Heer des Stammes der Kinder Issaschar war Nethaneel, der Sohn Zuars;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'und über das Heer des Stammes der Kinder Sebulon war Eliab, der Sohn Helons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Und die Wohnung wurde abgenommen, und es brachen auf die Söhne Gersons und die Söhne Meraris, welche die Wohnung trugen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Und das Panier des Lagers Rubens brach auf nach seinen Heeren; und über sein Heer war Elizur, der Sohn Schedeurs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Und über das Heer des Stammes der Kinder Simeon war Schelumiel, der Sohn Zurischaddais;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'und über das Heer des Stammes der Kinder Gad war Eljasaph, der Sohn Deghuels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Und die Kehathiter brachen auf, welche das Heiligtum trugen; und jene richteten die Wohnung auf, bis diese kamen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Und das Panier des Lagers der Kinder Ephraim brach auf nach ihren Heeren; und über sein Heer war Elischama, der Sohn Ammihuds.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Und über das Heer des Stammes der Kinder Manasse war Gamliel, der Sohn Pedazurs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'und über das Heer des Stammes der Kinder Benjamin war Abidan, der Sohn Gideonis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Und das Panier des Lagers der Kinder Dan, welches die Nachhut aller Lager bildete, brach auf nach ihren Heeren; und über sein Heer war Achieser, der Sohn Ammischaddais.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Und über das Heer des Stammes der Kinder Aser war Pagiel, der Sohn Okrans;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'und über das Heer des Stammes der Kinder Naphtali war Achira, der Sohn Enans. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Das war die Marschordnung der Kinder Israel nach ihren Heeren; und so brachen sie auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Und Mose sprach zu Hobab, dem Sohne Reghuels, des Midianiters, des Schwiegervaters Moses: Wir brechen auf nach dem Orte, von welchem Jehova gesagt hat: Ich will ihn euch geben. Ziehe mit uns, so werden wir dir Gutes tun; denn Jehova hat Gutes über Israel geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Und er sprach zu ihm: Ich will nicht mitziehen, sondern in mein Land und zu meiner Verwandtschaft will ich gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Und er sprach: Verlaß uns doch nicht! Denn du weißt ja, wo wir in der Wüste lagern sollen; und du wirst unser Auge sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Und es soll geschehen, wenn du mit uns ziehst, und uns jenes Gute geschieht, das Jehova an uns tun will, so werden wir dir auch Gutes tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Und sie brachen auf von dem Berge Jehovas, drei Tagereisen weit, und die Lade des Bundes Jehovas zog drei Tagereisen vor ihnen her, um ihnen einen Ruheort zu erkunden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'und die Wolke Jehovas war über ihnen des Tages, wenn sie aus dem Lager zogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Und es geschah, wenn die Lade aufbrach, so sprach Mose: Stehe auf, Jehova, daß deine Feinde sich zerstreuen, und deine Hasser vor dir fliehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Und wenn sie ruhte, so sprach er: Kehre wieder, Jehova, zu den Myriaden der Tausende Israels!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Und es geschah, als das Volk sich beklagte, daß es übel war in den Ohren Jehovas; und als Jehova es hörte, da erglühte sein Zorn, und ein Feuer Jehovas brannte unter ihnen und fraß am Ende des Lagers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Und das Volk schrie zu Mose; und Mose betete zu Jehova, da legte sich das Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Und man gab selbigem Orte den Namen Tabhera, weil ein Feuer Jehovas unter ihnen gebrannt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Und das Mischvolk, das in ihrer Mitte war, wurde lüstern, und auch die Kinder Israel weinten wiederum und sprachen: Wer wird uns Fleisch zu essen geben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Wir gedenken der Fische, die wir in Ägypten umsonst aßen, der Gurken und der Melonen und des Lauchs und der Zwiebeln und des Knoblauchs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'und nun ist unsere Seele dürre; gar nichts ist da, nur auf das Man sehen unsere Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Das Man aber war wie Koriandersamen, und sein Ansehen wie das Ansehen des Bdellion.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Das Volk lief umher, und sie sammelten und mahlten es mit Handmühlen oder zerstießen es in Mörsern; und sie kochten es in Töpfen, auch machten sie Kuchen daraus; und sein Geschmack war wie der Geschmack von Ölkuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Und wenn des Nachts der Tau auf das Lager herabfiel, so fiel das Man auf dasselbe herab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Und als Mose das Volk nach seinen Geschlechtern, einen jeden am Eingang seines Zeltes, weinen hörte, und der Zorn Jehovas heftig entbrannte, da war es übel in den Augen Moses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Und Mose sprach zu Jehova: Warum hast du an deinem Knechte übel getan, und warum habe ich nicht Gnade gefunden in deinen Augen, daß du die Last dieses ganzen Volkes auf mich legst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Bin ich mit diesem ganzen Volke schwanger gegangen, oder habe ich es geboren, daß du zu mir sprichst: Trage es in deinem Busen, gleichwie der Wärter den Säugling trägt, in das Land, das du ihren Vätern zugeschworen hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Woher soll ich Fleisch haben, um es diesem ganzen Volke zu geben? Denn sie weinen gegen mich und sagen: Gib uns Fleisch, daß wir essen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Ich allein vermag nicht dieses ganze Volk zu tragen, denn es ist mir zu schwer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Und wenn du also mit mir tust, so bringe mich doch um, wenn ich Gnade gefunden habe in deinen Augen, damit ich mein Unglück nicht ansehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Und Jehova sprach zu Mose: Versammle mir siebzig Männer aus den Ältesten Israels, von denen du weißt, daß sie die Ältesten des Volkes und seine Vorsteher sind, und führe sie zu dem Zelte der Zusammenkunft, daß sie sich daselbst mit dir hinstellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Und ich werde herniederkommen und daselbst mit dir reden, und ich werde von dem Geiste nehmen, der auf dir ist, und auf sie legen, daß sie mit dir an der Last des Volkes tragen, und du sie nicht allein tragest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Und zu dem Volke sollst du sagen: Heiliget euch auf morgen, und ihr werdet Fleisch essen; denn ihr habt vor den Ohren Jehovas geweint und gesprochen: Wer wird uns Fleisch zu essen geben? Denn in Ägypten ging es uns wohl; und Jehova wird euch Fleisch geben, und ihr werdet essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Nicht einen Tag sollt ihr essen, und nicht zwei Tage und nicht fünf Tage und nicht zehn Tage und nicht zwanzig Tage:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'bis zu einem ganzen Monat, bis es euch zur Nase herauskommt, und es euch zum Ekel wird; weil ihr Jehova, der in eurer Mitte ist, verachtet und vor ihm geweint und gesprochen habt: Warum doch sind wir aus Ägypten herausgezogen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Und Mose sprach: Sechshunderttausend Mann zu Fuß ist das Volk, in dessen Mitte ich bin, und du sprichst: Fleisch will ich ihnen geben, daß sie einen ganzen Monat essen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Soll Klein-und Rindvieh für sie geschlachtet werden, daß es für sie ausreiche? Oder sollen alle Fische des Meeres für sie gesammelt werden, daß es für sie ausreiche?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Und Jehova sprach zu Mose: Ist die Hand Jehovas zu kurz? Jetzt sollst du sehen, ob mein Wort dir eintrifft oder nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Da ging Mose hinaus und redete zu dem Volke die Worte Jehovas; und er versammelte siebzig Männer aus den Ältesten des Volkes und stellte sie rings um das Zelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Und Jehova kam in der Wolke hernieder und redete zu ihm und nahm von dem Geiste, der auf ihm war, und legte ihn auf die siebzig Männer, die Ältesten. Und es geschah, sobald der Geist auf sie kam, weissagten sie; aber sie fuhren nicht fort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Und zwei Männer blieben im Lager zurück, der Name des einen war Eldad, und der Name des anderen Medad; und auch auf sie kam der Geist (sie waren nämlich unter den Aufgeschriebenen, waren aber nicht zum Zelte hinausgegangen), und sie weissagten im Lager.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Da lief ein Jüngling hin und berichtete es Mose und sprach: Eldad und Medad weissagen im Lager.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Und Josua, der Sohn Nuns, der Diener Moses, einer von seinen Jünglingen, antwortete und sprach: Mein Herr Mose, wehre ihnen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Aber Mose sprach zu ihm: Eiferst du für mich? Möchte doch das ganze Volk Jehovas Propheten sein, daß Jehova seinen Geist auf sie legte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Und Mose zog sich in das Lager zurück, er und die Ältesten Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Und ein Wind fuhr von Jehova aus und trieb Wachteln vom Meere herbei und warf sie auf das Lager, bei einer Tagereise hier und bei einer Tagereise dort, rings um das Lager, und bei zwei Ellen hoch über der Oberfläche der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Und das Volk machte sich auf, denselben ganzen Tag und die ganze Nacht und den ganzen folgenden Tag, und sie sammelten die Wachteln; wer wenig gesammelt, hatte zehn Homer gesammelt; und sie breiteten sich dieselben aus rings um das Lager her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Das Fleisch war noch zwischen ihren Zähnen, es war noch nicht zerkaut, da entbrannte der Zorn Jehovas wider das Volk, und Jehova richtete unter dem Volke eine sehr große Niederlage an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Und man gab selbigem Orte den Namen Kibroth-Hattaawa, weil man daselbst das Volk begrub, das lüstern gewesen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Von Kibroth-Hattaawa brach das Volk auf nach Hazeroth; und sie waren zu Hazeroth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Und Mirjam und Aaron redeten wider Mose wegen des kuschitischen Weibes, das er genommen hatte; denn er hatte eine kuschitisches Weib genommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Und sie sprachen: Hat Jehova nur mit Mose allein geredet? Hat er nicht auch mit uns geredet? Und Jehova hörte es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Der Mann Mose aber war sehr sanftmütig, mehr als alle Menschen, die auf dem Erdboden waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Da sprach Jehova plötzlich zu Mose und zu Aaron und zu Mirjam: Gehet hinaus, ihr drei, zum Zelte der Zusammenkunft! Und sie gingen hinaus, sie drei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Und Jehova kam in der Wolkensäule hernieder und stand an dem Eingang des Zeltes; und er rief Aaron und Mirjam, und die beiden traten hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Und er sprach: Höret denn meine Worte! Wenn ein Prophet unter euch ist, dem will ich, Jehova, in einem Gesicht mich kundtun, in einem Traume will ich mit ihm reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Nicht also mein Knecht Mose. Er ist treu in meinem ganzen Hause;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'mit ihm rede ich von Mund zu Mund, und deutlich und nicht in Rätseln, und das Bild Jehovas schaut er. Und warum habt ihr euch nicht gefürchtet, wider meinen Knecht, wider Mose, zu reden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Und der Zorn Jehovas entbrannte wider sie, und er ging weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Und die Wolke wich von dem Zelte, und siehe, Mirjam war aussätzig wie Schnee; und Aaron wandte sich zu Mirjam, und siehe, sie war aussätzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Da sprach Aaron zu Mose: Ach, mein Herr! Lege doch nicht die Sünde auf uns, durch welche wir töricht gehandelt und uns versündigt haben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Möge sie doch nicht sein wie ein totes Kind, dessen Fleisch, wenn es aus seiner Mutter Leibe hervorkommt, zur Hälfte verwest ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Und Mose schrie zu Jehova und sprach: O Gott, bitte, heile sie doch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Und Jehova sprach zu Mose: Hätte ihr Vater ihr etwa ins Angesicht gespieen, sollte sie sich nicht sieben Tage lang schämen? Sie soll sieben Tage außerhalb des Lagers eingeschlossen werden, und danach mag sie wieder aufgenommen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Und Mirjam wurde sieben Tage außerhalb des Lagers eingeschlossen; und das Volk brach nicht auf, bis Mirjam wieder aufgenommen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Danach aber brach das Volk von Hazeroth auf; und sie lagerten sich in der Wüste Paran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Sende dir Männer aus, daß sie das Land Kanaan auskundschaften, welches ich den Kindern Israel gebe; je einen Mann für den Stamm seiner Väter sollt ihr aussenden, jeder ein Fürst unter ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Und Mose sandte sie aus der Wüste Paran nach dem Befehl Jehovas, allesamt Männer, welche Häupter der Kinder Israel waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Und dies sind ihre Namen: für den Stamm Ruben, Schammua, der Sohn Sakkurs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'für den Stamm Simeon, Schaphat, der Sohn Choris;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'für den Stamm Juda, Kaleb, der Sohn Jephunnes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'für den Stamm Issaschar, Jigal, der Sohn Josephs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'für den Stamm Ephraim, Hosea, der Sohn Nuns;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'für den Stamm Benjamin, Palti, der Sohn Raphus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'für den Stamm Sebulon, Gaddiel, der Sohn Sodis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'für den Stamm Joseph, für den Stamm Manasse, Gaddi, der Sohn Susis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'für den Stamm Dan, Ammiel, der Sohn Gemallis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'für den Stamm Aser, Sethur, der Sohn Michaels;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'für den Stamm Naphtali, Nachbi, der Sohn Waphsis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'für den Stamm Gad, Geuel, der Sohn Makis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Das sind die Namen der Männer, welche Mose aussandte, um das Land auszukundschaften. Und Mose nannte Hosea, den Sohn Nuns, Josua.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Und Mose sandte sie, um das Land Kanaan auszukundschaften, und sprach zu ihnen: Ziehet hier hinauf an der Südseite, und steiget auf das Gebirge,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'und besehet das Land, wie es ist; und das Volk, das darin wohnt, ob es stark oder schwach, ob es gering oder zahlreich ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'und wie das Land ist, in welchem es wohnt, ob es gut oder schlecht ist; und wie die Städte sind, in denen es wohnt, ob es in Lagern oder in Festungen wohnt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'und wie das Land ist, ob es fett oder mager ist, ob Bäume darin sind oder nicht. Und fasset Mut und nehmet von der Frucht des Landes. Die Tage aber waren die Tage der ersten Trauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Und sie zogen hinauf und kundschafteten das Land aus, von der Wüste Zin bis Rechob, wenn man nach Hamath geht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Und sie zogen an der Südseite hinauf und kamen bis Hebron, und daselbst waren Achiman, Scheschai und Talmai, die Kinder Enaks. Hebron aber war sieben Jahre vor Zoan in Ägypten erbaut worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Und sie kamen bis in das Tal Eskol und schnitten daselbst eine Rebe mit einer Weintraube ab und trugen sie zu zweien an einer Stange, auch Granatäpfel und Feigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Jenen Ort nannte man Tal Eskol wegen der Traube, welche die Kinder Israel daselbst abgeschnitten hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Und sie kehrten nach Verlauf von vierzig Tagen vom Auskundschaften des Landes zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Und sie gingen und kamen zu Mose und zu Aaron und zu der ganzen Gemeinde der Kinder Israel in die Wüste Paran nach Kades; und sie brachten ihnen und der ganzen Gemeinde Bescheid und zeigten ihnen die Frucht des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Und sie erzählten ihm und sprachen: Wir sind in das Land gekommen, wohin du uns gesandt hast; und wirklich, es fließt von Milch und Honig, und dies ist seine Frucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Nur daß das Volk stark ist, welches in dem Lande wohnt, und die Städte befestigt, sehr groß; und auch die Kinder Enaks haben wir dort gesehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalek wohnt im Lande des Südens, und die Hethiter und die Jebusiter und die Amoriter wohnen auf dem Gebirge, und die Kanaaniter wohnen am Meere und an der Seite des Jordan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Und Kaleb beschwichtigte das Volk gegen Mose und sprach: Laßt uns nur hinaufziehen und es in Besitz nehmen, denn wir werden es gewißlich überwältigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Aber die Männer, die mit ihm hinaufgezogen waren, sprachen: Wir vermögen nicht gegen das Volk hinaufzuziehen, denn es ist stärker als wir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Und sie brachten unter die Kinder Israel ein böses Gerücht über das Land aus, das sie ausgekundschaftet hatten, und sprachen: Das Land, welches wir durchzogen haben, um es auszukundschaften, ist ein Land, das seine Bewohner frißt; und alles Volk, das wir darin gesehen haben, sind Leute von hohem Wuchse;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'auch haben wir dort die Riesen gesehen, die Kinder Enaks, von den Riesen; und wir waren in unseren Augen wie Heuschrecken, und also waren wir auch in ihren Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Da erhob die ganze Gemeinde ihre Stimme und schrie, und das Volk weinte in selbiger Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Und alle Kinder Israel murrten wider Mose und wider Aaron, und die ganze Gemeinde sprach zu ihnen: O wären wir doch im Lande Ägypten gestorben, oder wären wir doch in dieser Wüste gestorben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Und warum bringt uns Jehova in dieses Land, daß wir durchs Schwert fallen und unsere Weiber und unsere Kindlein zur Beute werden? Wäre es nicht besser für uns, nach Ägypten zurückzukehren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Und sie sprachen einer zum anderen: Laßt uns ein Haupt über uns setzen und nach Ägypten zurückkehren! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Da fielen Mose und Aaron auf ihr Angesicht vor der ganzen Versammlung der Gemeinde der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Und Josua, der Sohn Nuns, und Kaleb, der Sohn Jephunnes, von denen, die das Land ausgekundschaftet hatten, zerrissen ihre Kleider,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'und sie sprachen zu der ganzen Gemeinde der Kinder Israel und sagten: Das Land, das wir durchzogen haben, um es auszukundschaften, das Land ist sehr, sehr gut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Wenn Jehova Gefallen an uns hat, so wird er uns in dieses Land bringen und es uns geben, ein Land, das von Milch und Honig fließt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Nur empöret euch nicht wider Jehova; und fürchtet ja nicht das Volk des Landes, denn unser Brot werden sie sein. Ihr Schirm ist von ihnen gewichen, und Jehova ist mit uns; fürchtet sie nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Und die ganze Gemeinde sagte, daß man sie steinigen solle. Da erschien die Herrlichkeit Jehovas an dem Zelte der Zusammenkunft allen Kindern Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Und Jehova sprach zu Mose: Wie lange will mich dieses Volk verachten, und wie lange wollen sie mir nicht glauben bei all den Zeichen, die ich in ihrer Mitte getan habe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Ich will es mit der Pest schlagen und es vertilgen; und ich will dich zu einer Nation machen, größer und stärker als sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Und Mose sprach zu Jehova: So werden die Ägypter es hören; denn durch deine Macht hast du dieses Volk aus ihrer Mitte heraufgeführt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'und man wird es den Bewohnern dieses Landes sagen, welche gehört haben, daß du, Jehova, in der Mitte dieses Volkes bist, daß du, Jehova, Auge in Auge dich sehen läßt, und daß deine Wolke über ihnen steht, und du in einer Wolkensäule vor ihnen hergehst bei Tage und in einer Feuersäule bei Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Und tötest du dieses Volk wie einen Mann, so werden die Nationen, die deinen Ruf gehört haben, sprechen und sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Weil Jehova nicht vermochte, dieses Volk in das Land zu bringen, das er ihnen zugeschworen hatte, so hat er sie in der Wüste hingeschlachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Und nun möge doch die Macht des Herrn sich groß erweisen, so wie du geredet hast, indem du sprachst:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Jehova ist langsam zum Zorn und groß an Güte, der Ungerechtigkeit und Übertretung vergibt, aber keineswegs hält er für schuldlos den Schuldigen, der die Ungerechtigkeit der Väter heimsucht an den Kindern am dritten und am vierten Gliede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Vergib doch die Ungerechtigkeit dieses Volkes nach der Größe deiner Güte, und so wie du diesem Volke verziehen hast von Ägypten an bis hierher!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Und Jehova sprach: Ich habe vergeben nach deinem Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Doch aber, so wahr ich lebe, soll von der Herrlichkeit Jehovas erfüllt werden die ganze Erde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'denn alle die Männer, die meine Herrlichkeit und meine Zeichen gesehen haben, welche ich in Ägypten und in der Wüste getan, und mich nun zehnmal versucht und nicht gehört haben auf meine Stimme-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'wenn sie das Land sehen werden, das ich ihren Vätern zugeschworen habe! Ja, alle, die mich verachtet haben, sollen es nicht sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Aber meinen Knecht Kaleb, weil ein anderer Geist in ihm gewesen und er mir völlig nachgefolgt ist, ihn werde ich in das Land bringen, in welches er gekommen ist; und sein Same soll es besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Die Amalekiter aber und die Kanaaniter wohnen in der Niederung; morgen wendet euch und brechet auf nach der Wüste, des Weges zum Schilfmeer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Und Jehova redete zu Mose und zu Aaron und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Wie lange soll es mit dieser bösen Gemeinde währen, daß sie wider mich murrt? Das Murren der Kinder Israel, das sie wider mich murren, habe ich gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Sprich zu ihnen: So wahr ich lebe, spricht Jehova, wenn ich euch nicht also tun werde, wie ihr vor meinen Ohren geredet habt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'In dieser Wüste sollen eure Leichname fallen, ja, alle eure Gemusterten nach eurer ganzen Zahl, von zwanzig Jahren und darüber, die ihr wider mich gemurrt habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Wenn ihr in das Land kommen werdet, darinnen euch wohnen zu lassen ich meine Hand erhoben habe, außer Kaleb, dem Sohne Jephunnes, und Josua, dem Sohne Nuns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Und eure Kindlein, von denen ihr gesagt habt: Sie werden zur Beute werden! die will ich hineinbringen, und sie sollen das Land kennen lernen, das ihr verschmäht habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Ihr aber, eure Leichname sollen in dieser Wüste fallen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'und eure Kinder sollen vierzig Jahre lang in der Wüste weiden und eure Hurereien tragen, bis eure Leichname in der Wüste aufgerieben sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Nach der Zahl der Tage, die ihr das Land ausgekundschaftet habt, vierzig Tage, je einen Tag für ein Jahr, sollt ihr vierzig Jahre lang eure Ungerechtigkeiten tragen, und ihr sollt erfahren, was es ist, wenn ich mich abwende!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Ich, Jehova, habe es geredet; wenn ich dies nicht tun werde an dieser ganzen bösen Gemeinde, die sich wider mich zusammengerottet hat! In dieser Wüste sollen sie aufgerieben werden, und daselbst sollen sie sterben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Und die Männer, welche Mose ausgesandt hatte, um das Land auszukundschaften, und die zurückkehrten und die ganze Gemeinde wider ihn murren machten, indem sie ein böses Gerücht über das Land ausbrachten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'jene Männer, die ein böses Gerücht über das Land ausgebracht hatten, starben durch eine Plage vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Aber Josua, der Sohn Nuns, und Kaleb, der Sohn Jephunnes, blieben am Leben von jenen Männern, welche gegangen waren, das Land auszukundschaften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Und als Mose jene Worte zu allen Kindern Israel redete, da trauerte das Volk sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Und sie machten sich des Morgens früh auf, um auf den Gipfel des Gebirges hinaufzuziehen, und sprachen: Hier sind wir und wollen an den Ort hinaufziehen, von welchem Jehova geredet hat; denn wir haben gesündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Aber Mose sprach: Warum übertretet ihr doch den Befehl Jehovas? Es wird ja nicht gelingen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Ziehet nicht hinauf, denn Jehova ist nicht in eurer Mitte, daß ihr nicht vor euren Feinden geschlagen werdet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'denn die Amalekiter und die Kanaaniter sind dort vor euch, und ihr werdet durchs Schwert fallen. Weil ihr euch von der Nachfolge Jehovas abgewandt habt, wird Jehova nicht mit euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Doch sie vermaßen sich, auf den Gipfel des Gebirges hinaufzuziehen; aber die Lade des Bundes Jehovas und Mose wichen nicht aus der Mitte des Lagers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Da kamen die Amalekiter und die Kanaaniter, die auf jenem Gebirge wohnten, herab und schlugen und zersprengten sie bis Horma.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Rede zu den Kindern Israel und sprich zu ihnen: Wenn ihr in das Land eurer Wohnsitze kommet, das ich euch geben werde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'und ihr dem Jehova ein Feueropfer opfert, ein Brandopfer oder ein Schlachtopfer, um ein Gelübde zu erfüllen, oder eine freiwillige Gabe, oder an euren Festen, um Jehova einen lieblichen Geruch zu bereiten, vom Rind-oder vom Kleinvieh:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'so soll der, welcher Jehova seine Opfergabe darbringt, als Speisopfer darbringen ein Zehntel Feinmehl, gemengt mit einem viertel Hin Öl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Und als Trankopfer sollst du ein viertel Hin Wein opfern zu dem Brandopfer oder zu dem Schlachtopfer, bei jedem Schafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Oder bei einem Widder sollst du als Speisopfer zwei Zehntel Feinmehl opfern, gemengt mit einem drittel Hin Öl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'und als Trankopfer sollst du ein drittel Hin Wein darbringen: ein lieblicher Geruch dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Und wenn du ein junges Rind als Brandopfer oder als Schlachtopfer opferst, um ein Gelübde zu erfüllen, oder als Friedensopfer für Jehova,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'so soll man zu dem jungen Rinde als Speisopfer darbringen drei Zehntel Feinmehl, gemengt mit einem halben Hin Öl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'und als Trankopfer sollst du ein halbes Hin Wein darbringen: ein Feueropfer lieblichen Geruchs dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Also soll getan werden bei jedem Rinde oder bei jedem Widder oder bei jedem Schafe oder bei jeder Ziege;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'nach der Zahl, die ihr opfert, sollt ihr also tun bei einem jeden nach ihrer Zahl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Jeder Eingeborene soll dieses also tun, wenn er ein Feueropfer lieblichen Geruchs dem Jehova darbringt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Und wenn ein Fremdling bei euch weilt, oder wer in eurer Mitte ist bei euren Geschlechtern, und er opfert dem Jehova ein Feueropfer lieblichen Geruchs, so soll er ebenso tun, wie ihr tut. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Was die Versammlung betrifft, so soll einerlei Satzung für euch sein und für den Fremdling, der bei euch weilt; eine ewige Satzung bei euren Geschlechtern: wie ihr, so soll der Fremdling sein vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Einerlei Gesetz und einerlei Recht soll für euch sein und für den Fremdling, der bei euch weilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Rede zu den Kindern Israel und sprich zu ihnen: Wenn ihr in das Land kommet, wohin ich euch bringen werde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'so soll es geschehen, wenn ihr von dem Brote des Landes esset, so sollt ihr Jehova ein Hebopfer heben:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'als Erstling eures Schrotmehls sollt ihr einen Kuchen als Hebopfer heben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Wie das Hebopfer der Tenne, also sollt ihr dieses heben. Von dem Erstling eures Schrotmehls sollt ihr Jehova ein Hebopfer geben, bei euren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Und wenn ihr aus Versehen sündiget und nicht tut alle diese Gebote, die Jehova zu Mose geredet hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'alles, was Jehova euch durch Mose geboten hat, von dem Tage an, da Jehova Gebote gab, und fernerhin bei euren Geschlechtern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'so soll es geschehen, wenn es vor den Augen der Gemeinde verborgen, aus Versehen geschehen ist, so soll die ganze Gemeinde einen jungen Farren als Brandopfer opfern zum lieblichen Geruch dem Jehova, nebst seinem Speisopfer und seinem Trankopfer, nach der Vorschrift, und einen Ziegenbock zum Sündopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Und der Priester soll Sühnung tun für die ganze Gemeinde der Kinder Israel, und es wird ihnen vergeben werden; denn es war eine Sünde aus Versehen, und sie haben ihre Opfergabe, ein Feueropfer dem Jehova, und ihr Sündopfer vor Jehova gebracht wegen ihrer Sünde aus Versehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Und es wird der ganzen Gemeinde der Kinder Israel vergeben werden und dem Fremdling, der in ihrer Mitte weilt; denn von dem ganzen Volke ist es geschehen aus Versehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Und wenn eine einzelne Seele aus Versehen sündigt, so soll sie eine einjährige Ziege zum Sündopfer darbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Und der Priester soll Sühnung tun für die Seele, die ein Versehen begangen hat durch eine Sünde aus Versehen vor Jehova, um Sühnung für sie zu tun; und es wird ihr vergeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Für den Eingeborenen unter den Kindern Israel und für den Fremdling, der in ihrer Mitte weilt, sollt ihr ein Gesetz haben, für den, der aus Versehen etwas tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Aber die Seele, welche mit erhobener Hand etwas tut, von den Eingeborenen und von den Fremdlingen, die schmäht Jehova; und selbige Seele soll ausgerottet werden aus der Mitte ihres Volkes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'denn das Wort Jehovas hat sie verachtet und sein Gebot gebrochen; selbige Seele soll gewißlich ausgerottet werden: ihre Ungerechtigkeit ist auf ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Und als die Kinder Israel in der Wüste waren, da fanden sie einen Mann, der am Sabbathtage Holz auflas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Und die ihn, Holz auflesend, gefunden hatten, brachten ihn zu Mose und zu Aaron und zu der ganzen Gemeinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Und sie legten ihn in Gewahrsam, denn es war nicht genau bestimmt, was ihm getan werden sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Da sprach Jehova zu Mose: Der Mann soll gewißlich getötet werden; die ganze Gemeinde soll ihn außerhalb des Lagers steinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Da führte ihn die ganze Gemeinde vor das Lager hinaus, und sie steinigten ihn, daß er starb, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Und Jehova sprach zu Mose und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Rede zu den Kindern Israel und sprich zu ihnen, daß sie sich eine Quaste an den Zipfeln ihrer Oberkleider machen, bei ihren Geschlechtern, und daß sie an die Quaste des Zipfels eine Schnur von blauem Purpur setzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'und es soll euch zu einer Quaste sein, daß ihr, wenn ihr sie ansehet, aller Gebote Jehovas gedenket und sie tuet, und daß ihr nicht umherspähet eurem Herzen und euren Augen nach, denen ihr nachhuret;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'damit ihr aller meiner Gebote gedenket und sie tuet, und heilig seiet eurem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Ich bin Jehova, euer Gott, der ich euch aus dem Lande Ägypten herausgeführt habe, um euer Gott zu sein; ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Und Korah, der Sohn Jizhars, des Sohnes Kehaths, des Sohnes Levis, unternahm es, und mit ihm Dathan und Abiram, die Söhne Eliabs, und On, der Sohn Pelets, die Söhne Rubens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'und sie standen auf gegen Mose, mit zweihundertfünfzig Männern von den Kindern Israel, Fürsten der Gemeinde, Berufene der Versammlung, Männer von Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Und sie versammelten sich wider Mose und wider Aaron und sprachen zu ihnen: Laßt es genug sein! Denn die ganze Gemeinde, sie allesamt, sind heilig, und Jehova ist in ihrer Mitte! Und warum erhebet ihr euch über die Versammlung Jehovas?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Als Mose es hörte, fiel er auf sein Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Und er redete zu Korah und zu seiner ganzen Rotte und sprach: Morgen, da wird Jehova kundtun, wer sein ist und wer heilig ist, daß er ihn zu sich nahen lasse; und wen er erwählt, den wird er zu sich nahen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Dieses tut: Nehmet euch Räucherpfannen, Korah und seine ganze Rotte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'und morgen tut Feuer darein und leget Räucherwerk darauf vor Jehova; und es soll geschehen, der Mann, den Jehova erwählen wird, der sei der Heilige. Laßt es genug sein, ihr Söhne Levis!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Und Mose sprach zu Korah: Höret doch, ihr Söhne Levis!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Ist es euch zu wenig, daß der Gott Israels euch aus der Gemeinde Israel ausgesondert hat, um euch zu sich nahen zu lassen, damit ihr den Dienst der Wohnung Jehovas verrichtet, und vor der Gemeinde stehet, um sie zu bedienen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'daß er dich und alle deine Brüder, die Söhne Levis, mit dir hat herzunahen lassen? Und ihr trachtet auch nach dem Priestertum!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Darum rottet ihr euch zusammen, du und deine ganze Rotte, wider Jehova; denn Aaron, was ist er, daß ihr wider ihn murret?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Und Mose sandte hin, um Dathan und Abiram, die Söhne Eliabs, zu rufen. Aber sie sprachen: Wir kommen nicht hinauf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Ist es zu wenig, daß du uns aus einem Lande, das von Milch und Honig fließt, heraufgeführt hast, um uns in der Wüste sterben zu lassen, daß du dich auch gar zum Herrscher über uns aufwirfst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Du hast uns keineswegs in ein Land gebracht, das von Milch und Honig fließt, noch uns Äcker und Weinberge als Erbteil gegeben! Willst du diesen Leuten die Augen ausstechen? Wir kommen nicht hinauf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Da ergrimmte Mose sehr und sprach zu Jehova: Wende dich nicht zu ihrer Opfergabe! Nicht einen Esel habe ich von ihnen genommen, und keinem einzigen unter ihnen ein Leid getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Und Mose sprach zu Korah: Du und deine ganze Rotte, ihr sollt morgen vor Jehova erscheinen, du und sie und Aaron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Und nehmet ein jeder seine Räucherpfanne und leget Räucherwerk darauf, und bringet ein jeder seine Räucherpfanne dar vor Jehova, zweihundertfünfzig Räucherpfannen; und du und Aaron, ein jeder seine Räucherpfanne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Und sie nahmen ein jeder seine Räucherpfanne und taten Feuer darauf und legten Räucherwerk darauf; und sie traten hin an den Eingang des Zeltes der Zusammenkunft, auch Mose und Aaron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Und Korah versammelte wider sie die ganze Gemeinde an den Eingang des Zeltes der Zusammenkunft. Da erschien die Herrlichkeit Jehovas vor der ganzen Gemeinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Und Jehova redete zu Mose und zu Aaron und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Sondert euch ab aus der Mitte dieser Gemeinde, und ich will sie vernichten in einem Augenblick!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Und sie fielen auf ihr Angesicht und sprachen: Gott, du Gott der Geister alles Fleisches! Der eine Mann sündigt, und du solltest über die ganze Gemeinde zürnen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Rede zu der Gemeinde und sprich: Hebet euch ringsum weg von der Wohnung Korahs, Dathans und Abirams.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Da stand Mose auf und ging zu Dathan und Abiram, und ihm nach gingen die Ältesten Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Und er redete zu der Gemeinde und sprach: Weichet doch von den Zelten dieser gesetzlosen Männer und rühret nichts an, was ihnen gehört, daß ihr nicht weggerafft werdet in allen ihren Sünden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Und sie hoben sich ringsum weg von der Wohnung Korahs, Dathans und Abirams. Und Dathan und Abiram traten heraus und standen am Eingang ihrer Zelte mit ihren Weibern und ihren Söhnen und ihren Kindlein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Und Mose sprach: Daran sollt ihr erkennen, daß Jehova mich gesandt hat, alle diese Taten zu tun, daß ich nicht aus meinem Herzen gehandelt habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Wenn diese sterben, wie alle Menschen sterben, und mit der Heimsuchung aller Menschen heimgesucht werden, so hat Jehova mich nicht gesandt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'wenn aber Jehova ein Neues schafft und der Erdboden seinen Mund auftut und sie verschlingt mit allem was ihnen angehört, und sie lebendig in den Scheol hinabfahren, so werdet ihr erkennen, daß diese Männer Jehova verachtet haben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Und es geschah, als er alle diese Worte ausgeredet hatte, da spaltete sich der Erdboden, der unter ihnen war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'und die Erde tat ihren Mund auf und verschlang sie und ihre Familien und alle Menschen, die Korah angehörten, und die ganze Habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Und sie fuhren, sie und alles, was ihnen angehörte, lebendig in den Scheol hinab; und die Erde bedeckte sie, und sie wurden mitten aus der Versammlung vertilgt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Und ganz Israel, das rings um sie her war, floh bei ihrem Geschrei; denn sie sprachen: Daß die Erde uns nicht verschlinge!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Und Feuer ging aus von Jehova und fraß die zweihundertfünfzig Männer, die das Räucherwerk dargebracht hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Sprich zu Eleasar, dem Sohne Aarons, dem Priester, daß er die Räucherpfannen aus dem Brande herausnehme; und streue das Feuer hinweg, denn sie sind heilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Die Räucherpfannen dieser Männer, welche wider ihre Seele gesündigt haben, man mache daraus breitgeschlagene Bleche zum Überzug für den Altar; denn sie haben sie vor Jehova dargebracht, und so sind sie heilig; und sie sollen den Kindern Israel zum Zeichen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Und Eleasar, der Priester, nahm die ehernen Räucherpfannen, welche die Verbrannten dargebracht hatten, und man schlug sie breit zum Überzug für den Altar,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'als ein Gedächtnis für die Kinder Israel, auf daß kein Fremder, der nicht vom Samen Aarons ist, herzunahe, um Räucherwerk vor Jehova zu räuchern, und es ihm nicht ergehe wie Korah und seiner Rotte, so wie Jehova durch Mose zu ihm geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Und die ganze Gemeinde der Kinder Israel murrte am anderen Morgen wider Mose und wider Aaron und sprach: Ihr habt das Volk Jehovas getötet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Und es geschah, als die Gemeinde sich wider Mose und wider Aaron versammelte, da wandten sie sich zu dem Zelte der Zusammenkunft, und siehe, die Wolke bedeckte es, und die Herrlichkeit Jehovas erschien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Da gingen Mose und Aaron vor das Zelt der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Hebet euch weg aus der Mitte dieser Gemeinde, und ich will sie vernichten in einem Augenblick! Da fielen sie auf ihr Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Und Mose sprach zu Aaron: Nimm die Räucherpfanne und tue Feuer vom Altar darauf und lege Räucherwerk auf, und bringe es eilends zu der Gemeinde und tue Sühnung für sie; denn der Zorn ist ausgegangen von Jehova, die Plage hat begonnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Und Aaron nahm die Räucherpfanne, so wie Mose geredet hatte, und lief mitten unter die Versammlung, und siehe, die Plage hatte unter dem Volke begonnen; und er legte das Räucherwerk auf und tat Sühnung für das Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'Und er stand zwischen den Toten und den Lebendigen, und der Plage ward gewehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Und es waren derer, die an der Plage starben, vierzehntausend siebenhundert, außer denen, die Korahs wegen gestorben waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Und Aaron kam wieder zu Mose an den Eingang des Zeltes der Zusammenkunft, als der Plage gewehrt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Rede zu den Kindern Israel und nimm von ihnen je einen Stab für ein Vaterhaus, von allen ihren Fürsten, nach ihren Vaterhäusern, zwölf Stäbe; du sollst den Namen eines jeden auf seinen Stab schreiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Und den Namen Aarons sollst du auf den Stab Levis schreiben; denn ein Stab soll für jedes Haupt ihrer Vaterhäuser sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Und du sollst sie in das Zelt der Zusammenkunft vor das Zeugnis niederlegen, woselbst ich mit euch zusammenkomme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Und es wird geschehen: der Mann, den ich erwählen werde, dessen Stab wird sprossen; und so werde ich vor mir stillen das Murren der Kinder Israel, das sie wider euch murren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Und Mose redete zu den Kindern Israel, und alle ihre Fürsten gaben ihm je einen Stab für einen Fürsten, nach ihren Vaterhäusern, zwölf Stäbe; und der Stab Aarons war unter ihren Stäben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Und Mose legte die Stäbe vor Jehova nieder in das Zelt des Zeugnisses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Und es geschah des anderen Tages, als Mose in das Zelt des Zeugnisses hineinging, siehe, da hatte der Stab Aarons, vom Hause Levi, gesproßt: er hatte Sprossen getrieben und Blüten gebracht und Mandeln gereift.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Und Mose brachte alle die Stäbe heraus vor Jehova weg zu allen Kindern Israel, und sie sahen sie und nahmen ein jeder seinen Stab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Und Jehova sprach zu Mose: Bringe den Stab Aarons vor das Zeugnis zurück, um ihn als ein Zeichen für die Widerspenstigen aufzubewahren, so daß du ihrem Murren vor mir ein Ende machest, und sie nicht sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Und Mose tat es; so wie Jehova ihm geboten hatte, also tat er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Und die Kinder Israel sprachen zu Mose und sagten: Siehe, wir vergehen, wir kommen um, wir alle kommen um!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Jeder, der irgend zur Wohnung Jehovas naht, der stirbt: sollen wir denn allzumal vergehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Und Jehova sprach zu Aaron: Du und deine Söhne und das Haus deines Vaters mit dir, ihr sollt die Ungerechtigkeit des Heiligtums tragen; und du und deine Söhne mit dir, ihr sollt die Ungerechtigkeit eures Priestertums tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Und auch deine Brüder, den Stamm Levi, den Stamm deines Vaters, laß mit dir herzunahen, daß sie sich dir anschließen und dir dienen; du aber und deine Söhne mit dir, ihr sollt vor dem Zelte des Zeugnisses dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Und sie sollen deiner Hut warten und der Hut des ganzen Zeltes; nur den Geräten des Heiligtums und dem Altar sollen sie nicht nahen, daß sie nicht sterben, sowohl sie als auch ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Und sie sollen sich dir anschließen und der Hut des Zeltes der Zusammenkunft warten nach allem Dienste des Zeltes; aber kein Fremder soll euch nahen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Und ihr sollt der Hut des Heiligtums und der Hut des Altars warten, daß kein Zorn mehr über die Kinder Israel komme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Und ich, siehe, ich habe eure Brüder, die Leviten, aus der Mitte der Kinder Israel genommen; euch als Geschenk sind sie dem Jehova gegeben, um den Dienst des Zeltes der Zusammenkunft zu verrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Du aber und deine Söhne mit dir, ihr sollt eures Priestertums warten, in allem was den Altar betrifft und innerhalb des Vorhangs, und so den Dienst tun; als einen geschenkten Dienst gebe ich euch das Priestertum. Der Fremde aber, der herzunaht, soll getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Und Jehova redete zu Aaron: Und ich, siehe, ich habe dir die Hut meiner Hebopfer gegeben; von allen heiligen Dingen der Kinder Israel habe ich sie dir und deinen Söhnen gegeben, als Salbungsteil, als eine ewige Gebühr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Dies soll dir gehören von dem Hochheiligen, das nicht verbrannt wird: alle ihre Opfergaben nach allen ihren Speisopfern und nach allen ihren Sündopfern und nach allen ihren Schuldopfern, die sie mir darbringen, als ein Hochheiliges soll es dir und deinen Söhnen gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'An hochheiligem Orte sollst du es essen, alles Männliche soll es essen; es soll dir heilig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Und dies soll dir gehören: die Hebopfer ihrer Gaben, nach allen Webopfern der Kinder Israel; dir und deinen Söhnen und deinen Töchtern mit dir habe ich sie gegeben als eine ewige Gebühr; jeder Reine in deinem Hause soll es essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Alles Beste vom Öl und alles Beste vom Most und Getreide, ihre Erstlinge, die sie Jehova geben, dir habe ich sie gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Die ersten Früchte von allem, was in ihrem Lande wächst, die sie Jehova bringen, sollen dir gehören; jeder Reine in deinem Hause soll davon essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Alles Verbannte in Israel soll dir gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Alles, was die Mutter bricht, von allem Fleische, das sie Jehova darbringen, an Menschen und an Vieh, soll dir gehören; nur sollst du den Erstgeborenen vom Menschen jedenfalls lösen, und das Erstgeborene vom unreinen Vieh sollst du lösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Und die zu Lösenden unter ihnen sollst du von einem Monat an lösen, nach deiner Schätzung, um fünf Sekel Silber, nach dem Sekel des Heiligtums, der zwanzig Gera ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Aber das Erstgeborene vom Rinde oder das Erstgeborene von den Schafen oder das Erstgeborene von den Ziegen sollst du nicht lösen; sie sind heilig. Ihr Blut sollst du an den Altar sprengen, und ihr Fett sollst du als Feueropfer räuchern zum lieblichen Geruch für Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Und ihr Fleisch soll dir gehören; wie die Brust des Webopfers und wie der rechte Schenkel soll es dir gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Alle Hebopfer der heiligen Dinge, welche die Kinder Israel dem Jehova heben, habe ich dir gegeben, und deinen Söhnen und deinen Töchtern mit dir, als eine ewige Gebühr; es ist ein ewiger Salzbund vor Jehova für dich und für deinen Samen mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Und Jehova sprach zu Aaron: In ihrem Lande sollst du nichts erben und sollst kein Teil in ihrer Mitte haben; ich bin dein Teil und dein Erbe inmitten der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Und siehe, den Kindern Levi habe ich allen Zehnten in Israel zum Erbteil gegeben für ihren Dienst, den sie verrichten, den Dienst des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Und die Kinder Israel sollen nicht mehr dem Zelte der Zusammenkunft nahen, um Sünde auf sich zu laden, daß sie sterben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'die Leviten vielmehr sollen den Dienst des Zeltes der Zusammenkunft verrichten, und sie sollen ihre Ungerechtigkeit tragen: eine ewige Satzung bei euren Geschlechtern. Aber inmitten der Kinder Israel sollen sie kein Erbteil besitzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'denn den Zehnten der Kinder Israel, welchen sie Jehova als Hebopfer heben, habe ich den Leviten zum Erbteil gegeben; darum habe ich von ihnen gesagt, daß sie inmitten der Kinder Israel kein Erbteil besitzen sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Und zu den Leviten sollst du reden und zu ihnen sprechen: Wenn ihr von den Kindern Israel den Zehnten nehmet, den ich euch von ihnen als euer Erbteil gegeben habe, so sollt ihr davon ein Hebopfer für Jehova heben, den Zehnten von dem Zehnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Und euer Hebopfer wird euch gerechnet werden wie das Getreide von der Tenne und wie die Fülle von der Kelter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Also sollt auch ihr ein Hebopfer für Jehova heben von allen euren Zehnten, die ihr von den Kindern Israel nehmet, und davon das Hebopfer für Jehova Aaron, dem Priester, geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Von allem euch Gegebenen sollt ihr alles Hebopfer Jehovas heben, von allem Besten desselben das Geheiligte davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Und du sollst zu ihnen sagen: Wenn ihr das Beste davon hebet, so soll es den Leviten gerechnet werden wie der Ertrag der Tenne und wie der Ertrag der Kelter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Und ihr möget ihn essen an jedem Orte, ihr und euer Haus; denn das ist euer Lohn für euren Dienst am Zelte der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Und ihr werdet seinethalben keine Sünde auf euch laden, wenn ihr das Beste davon hebet, und werdet die heiligen Dinge der Kinder Israel nicht entweihen und nicht sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Und Jehova redete zu Mose und zu Aaron und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Dies ist die Satzung des Gesetzes, das Jehova geboten hat, indem er sprach: Rede zu den Kindern Israel, daß sie dir eine rote junge Kuh bringen, ohne Fehl, an der kein Gebrechen, auf welche kein Joch gekommen ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'und ihr sollt sie Eleasar, dem Priester, geben, und er soll sie vor das Lager hinausführen, und man soll sie vor ihm schlachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Und Eleasar, der Priester, nehme von ihrem Blute mit seinem Finger und sprenge von ihrem Blute siebenmal gegen die Vorderseite des Zeltes der Zusammenkunft hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Und man soll die junge Kuh vor seinen Augen verbrennen: ihre Haut und ihr Fleisch und ihr Blut samt ihrem Mist soll man verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Und der Priester soll Cedernholz und Ysop und Karmesin nehmen und es mitten in den Brand der jungen Kuh werfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Und der Priester soll seine Kleider waschen und sein Fleisch im Wasser baden, und danach soll er in das Lager gehen; und der Priester wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Und der sie verbrennt, soll seine Kleider mit Wasser waschen und sein Fleisch im Wasser baden, und er wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Und ein reiner Mann soll die Asche der jungen Kuh sammeln und sie außerhalb des Lagers an einen reinen Ort schütten, und sie soll für die Gemeinde der Kinder Israel aufbewahrt werden zum Wasser der Reinigung; es ist eine Entsündigung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Und der die Asche der jungen Kuh gesammelt hat, soll seine Kleider waschen, und er wird unrein sein bis an den Abend. Und es soll den Kindern Israel und dem Fremdling, der in ihrer Mitte weilt, zur ewigen Satzung sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Wer einen Toten anrührt, irgend eine Leiche eines Menschen, der wird sieben Tage unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Selbiger soll sich am dritten Tage damit entsündigen, und am siebten Tage wird er rein sein; und wenn er sich nicht entsündigt am dritten Tage, so wird er am siebten Tage nicht rein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Jeder, der einen Toten anrührt, die Leiche irgend eines Menschen, der gestorben ist, und sich nicht entsündigt, hat die Wohnung Jehovas verunreinigt; und selbige Seele soll ausgerottet werden aus Israel. Weil das Wasser der Reinigung nicht auf ihn gesprengt wurde, ist er unrein; seine Unreinigkeit ist noch an ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Dies ist das Gesetz, wenn ein Mensch im Zelte stirbt: Jeder, der ins Zelt geht, und jeder, der im Zelte ist, wird sieben Tage unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Und jedes offene Gefäß, auf dem kein festgebundener Deckel ist, wird unrein sein. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Und jeder, der auf freiem Felde einen mit dem Schwerte Erschlagenen oder einen Gestorbenen oder das Gebein eines Menschen oder ein Grab anrührt, wird sieben Tage unrein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Und man soll für den Unreinen von dem Staube des zur Entsündigung Verbrannten nehmen und lebendiges Wasser darauf tun in ein Gefäß;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'und ein reiner Mann soll Ysop nehmen und ihn in das Wasser tauchen, und soll auf das Zelt sprengen und auf alle Geräte und auf die Personen, die daselbst sind, und auf den, der das Gebein oder den Erschlagenen oder den Gestorbenen oder das Grab angerührt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Und zwar soll der Reine auf den Unreinen sprengen am dritten Tage und am siebten Tage, und ihn am siebten Tage entsündigen; und er soll seine Kleider waschen und sich im Wasser baden, und am Abend wird er rein sein. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Und wenn jemand unrein wird, und sich nicht entsündigt, selbige Seele soll ausgerottet werden aus der Mitte der Versammlung; denn er hat das Heiligtum Jehovas verunreinigt: das Wasser der Reinigung ist nicht auf ihn gesprengt worden, er ist unrein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Und es soll ihnen zur ewigen Satzung sein. Und wer das Wasser der Reinigung sprengt, soll seine Kleider waschen; und wer das Wasser der Reinigung anrührt, wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Und alles, was der Unreine anrührt, wird unrein sein; und wer ihn anrührt, wird unrein sein bis an den Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Und die Kinder Israel, die ganze Gemeinde, kamen in die Wüste Zin, im ersten Monat; und das Volk blieb zu Kades; und Mirjam starb daselbst und wurde daselbst begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Und es war kein Wasser da für die Gemeinde, und sie versammelten sich wider Mose und wider Aaron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Und das Volk haderte mit Mose, und sie sprachen und sagten: Wären wir doch umgekommen, als unsere Brüder vor Jehova umkamen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Und warum habt ihr die Versammlung Jehovas in diese Wüste gebracht, daß wir daselbst sterben, wir und unser Vieh?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Und warum habt ihr uns aus Ägypten heraufgeführt, um uns an diesen bösen Ort zu bringen? Es ist kein Ort der Aussaat und der Feigenbäume und der Weinstöcke und der Granatbäume, und kein Wasser ist da zu trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Und Mose und Aaron gingen von der Versammlung hinweg zum Eingang des Zeltes der Zusammenkunft und fielen auf ihr Angesicht; und die Herrlichkeit Jehovas erschien ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Nimm den Stab und versammle die Gemeinde, du und dein Bruder Aaron, und redet vor ihren Augen zu dem Felsen, so wird er sein Wasser geben; und du wirst ihnen Wasser aus dem Felsen hervorbringen und die Gemeinde tränken und ihr Vieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Und Mose nahm den Stab vor Jehova weg, so wie er ihm geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Und Mose und Aaron versammelten die Versammlung vor dem Felsen; und er sprach zu ihnen: Höret doch, ihr Widerspenstigen! Werden wir euch Wasser aus diesem Felsen hervorbringen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Und Mose erhob seine Hand und schlug den Felsen mit seinem Stabe zweimal; da kam viel Wasser heraus, und die Gemeinde trank und ihr Vieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Da sprach Jehova zu Mose und zu Aaron: Weil ihr mir nicht geglaubt habt, mich vor den Augen der Kinder Israel zu heiligen, deswegen sollt ihr diese Versammlung nicht in das Land bringen, das ich ihnen gegeben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Das ist das Wasser von Meriba, wo die Kinder Israel mit Jehova haderten, und er sich an ihnen heiligte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Und Mose sandte Boten aus Kades an den König von Edom: So spricht dein Bruder Israel: Du kennst all das Ungemach, das uns betroffen hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Unsere Väter zogen nach Ägypten hinab, und wir haben eine lange Zeit in Ägypten gewohnt; und die Ägypter behandelten uns und unsere Väter übel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Da schrieen wir zu Jehova, und er hat unsere Stimme gehört und einen Engel gesandt und uns aus Ägypten herausgeführt; und siehe, wir sind zu Kades, einer Stadt am Äußersten deines Gebiets.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Laß uns doch durch dein Land ziehen! Wir wollen nicht durch die Äcker und durch die Weinberge ziehen und wollen kein Wasser aus den Brunnen trinken; auf der Straße des Königs wollen wir ziehen und nicht ausbiegen zur Rechten noch zur Linken, bis wir durch dein Gebiet gezogen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Aber Edom sprach zu ihm: Du sollst nicht bei mir durchziehen, daß ich dir nicht mit dem Schwerte entgegenrücke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Und die Kinder Israel sprachen zu ihm: Auf der Landstraße wollen wir hinaufziehen; und wenn wir von deinem Wasser trinken, ich und mein Vieh, so will ich den Preis dafür geben; mit meinen Füßen will ich durchziehen, weiter nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Und er sprach: Du sollst nicht durchziehen! Und Edom zog aus, ihm entgegen, mit zahlreichem Volk und mit starker Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Und so weigerte sich Edom, Israel zu gestatten, durch sein Gebiet zu ziehen; und Israel bog von ihm ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Und sie brachen auf von Kades; und die Kinder Israel, die ganze Gemeinde, kamen an den Berg Hor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Und Jehova redete zu Mose und zu Aaron am Berge Hor, an der Grenze des Landes Edom, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Aaron soll zu seinen Völkern versammelt werden; denn er soll nicht in das Land kommen, das ich den Kindern Israel gegeben habe, weil ihr meinem Befehle widerspenstig gewesen seid bei dem Wasser von Meriba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Nimm Aaron und Eleasar, seinen Sohn, und laß sie hinaufsteigen auf den Berg Hor;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'und ziehe Aaron seine Kleider aus und lege sie seinem Sohne Eleasar an; und Aaron soll versammelt werden und daselbst sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Und Mose tat, so wie Jehova geboten hatte, und sie stiegen auf den Berg Hor, vor den Augen der ganzen Gemeinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Und Mose zog Aaron seine Kleider aus und legte sie seinem Sohne Eleasar an; und Aaron starb daselbst auf dem Gipfel des Berges; und Mose und Eleasar stiegen von dem Berge herab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Und als die ganze Gemeinde sah, daß Aaron verschieden war, da beweinte das ganze Haus Israel Aaron dreißig Tage lang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Und der Kanaaniter, der König von Arad, der im Süden wohnte, hörte, daß Israel des Weges nach Atharim kam, und er stritt wider Israel und führte Gefangene von ihm hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Da tat Israel Jehova ein Gelübde und sprach: Wenn du dieses Volk gewißlich in meine Hand gibst, so werde ich seine Städte verbannen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Und Jehova hörte auf die Stimme Israels und gab die Kanaaniter in seine Hand; und es verbannte sie und ihre Städte. Und man gab dem Orte den Namen Horma.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Und sie brachen auf vom Berge Hor, des Weges zum Schilfmeer, um das Land Edom zu umgehen. Und die Seele des Volkes wurde ungeduldig auf dem Wege;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'und das Volk redete wider Gott und wider Mose: Warum habt ihr uns aus Ägyten heraufgeführt, daß wir in der Wüste sterben? Denn da ist kein Brot und kein Wasser, und unsere Seele ekelt vor dieser elenden Speise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Da sandte Jehova feurige Schlangen unter das Volk, und sie bissen das Volk; und es starb viel Volks aus Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Da kam das Volk zu Mose, und sie sprachen: Wir haben gesündigt, daß wir wider Jehova und wider dich geredet haben; flehe zu Jehova, daß er die Schlangen von uns wegnehme. Und Mose flehte für das Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Und Jehova sprach zu Mose: Mache dir eine feurige Schlange und tue sie auf eine Stange; und es wird geschehen, jeder, der gebissen ist und sie ansieht, der wird am Leben bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Und Mose machte eine Schlange von Erz und tat sie auf die Stange; und es geschah, wenn eine Schlange jemand gebissen hatte, und er schaute auf zu der ehernen Schlange, so blieb er am Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Und die Kinder Israel brachen auf und lagerten sich zu Oboth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Und sie brachen auf von Oboth und lagerten sich zu Ijje-Abarim, in der Wüste, die vor Moab gegen Sonnenaufgang ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Von dort brachen sie auf und lagerten sich am Bache Sered.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Von dort brachen sie auf und lagerten sich jenseit des Arnon, der in der Wüste ist, der aus dem Gebiete der Amoriter hervorgeht. Denn der Arnon ist die Grenze von Moab, zwischen Moab und den Amoritern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Darum heißt es in dem Buche der Kämpfe Jehovas: Waheb in Sufa und die Bäche des Arnon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'und die Ergießung der Bäche, die sich erstreckt nach dem Wohnsitze Ars, und sich lehnt an die Grenze von Moab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Und von dort zogen sie nach Beer; das ist der Brunnen, von welchem Jehova zu Mose sprach: Versammle das Volk, und ich will ihnen Wasser geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Damals sang Israel dieses Lied:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Herauf, Brunnen! Singet ihm zu! Brunnen, den Fürsten gegraben, den die Edlen des Volkes, mit dem Gesetzgeber, gehöhlt haben mit ihren Stäben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'Und aus der Wüste zogen sie nach Mattana; und von Mattana nach Nachaliel, und von Nachaliel nach Bamoth;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'und von Bamoth nach dem Tale, das im Gefilde Moabs ist, nach dem Gipfel des Pisga, der emporragt über die Fläche der Wildnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Und Israel sandte Boten zu Sihon, dem Könige der Amoriter, und ließ ihm sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Laß mich durch dein Land ziehen! Wir wollen nicht in die Äcker und in die Weinberge ausbiegen, wir wollen kein Wasser aus den Brunnen trinken; auf der Straße des Königs wollen wir ziehen, bis wir durch dein Gebiet gezogen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Aber Sihon gestattete Israel nicht, durch sein Gebiet zu ziehen; und Sihon versammelte all sein Volk und zog aus, Israel entgegen in die Wüste, und kam nach Jahaz und stritt wider Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Und Israel schlug ihn mit der Schärfe des Schwertes und nahm sein Land in Besitz, vom Arnon bis an den Jabbok, bis zu den Kindern Ammon; denn die Grenze der Kinder Ammon war fest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Und Israel nahm alle diese Städte, und Israel wohnte in allen Städten der Amoriter, in Hesbon und in allen seinen Tochterstädten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Denn Hesbon war die Stadt Sihons, des Königs der Amoriter; und dieser hatte wider den früheren König von Moab gestritten und hatte sein ganzes Land bis an den Arnon aus seiner Hand genommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Daher sagen die Dichter: Kommet nach Hesbon; aufgebaut und befestigt werde die Stadt Sihons!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Denn Feuer ging aus von Hesbon, eine Flamme von der Stadt Sihons; es fraß Ar-Moab, die Herren der Höhen des Arnon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Wehe dir, Moab; du bist verloren, Volk des Kamos! Er hat seine Söhne zu Flüchtlingen gemacht und seine Töchter in die Gefangenschaft Sihons geführt, des Königs der Amoriter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Da haben wir auf sie geschossen; Hesbon ist verloren bis Dibon; da haben wir verwüstet bis Nophach, Feuer bis Medeba!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Und Israel wohnte im Lande der Amoriter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Und Mose sandte Männer aus, um Jaser auszukundschaften; und sie nahmen seine Tochterstädte ein, und er trieb die Amoriter aus, die daselbst waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Und sie wandten sich und zogen hinauf des Weges nach Basan; und Og, der König von Basan, zog aus, ihnen entgegen, er und all sein Volk, zum Streite nach Edrei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Und Jehova sprach zu Mose: Fürchte ihn nicht! Denn in deine Hand habe ich ihn gegeben und all sein Volk und sein Land; und tue ihm, so wie du Sihon, dem Könige der Amoriter, getan hast, der zu Hesbon wohnte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Und sie schlugen ihn und seine Söhne und all sein Volk, bis ihm kein Entronnener übrigblieb; und sie nahmen sein Land in Besitz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Und die Kinder Israel brachen auf und lagerten sich in den Ebenen Moabs, jenseit des Jordan von Jericho.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Und Balak, der Sohn Zippors, sah alles, was Israel den Amoritern getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Und Moab fürchtete sich sehr vor dem Volke, weil es groß war, und es graute Moab vor den Kindern Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Und Moab sprach zu den Ältesten von Midian: Nun wird dieser Haufe alle unsere Umgebungen abfressen, wie das Rind das Grüne des Feldes abfrißt. Und Balak, der Sohn Zippors, war zu jener Zeit König von Moab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Und er sandte Boten zu Bileam, dem Sohne Beors, nach Pethor, das am Strome ist, in das Land der Kinder seines Volkes, um ihn zu rufen, und er ließ ihm sagen: Siehe, ein Volk ist aus Ägypten gezogen; siehe, es bedeckt die Fläche des Landes, und es liegt mir gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Und nun, komm doch, verfluche mir dieses Volk, denn es ist stärker als ich. Vielleicht gelingt es mir, daß wir es schlagen und ich es aus dem Lande vertreibe; denn ich weiß, wen du segnest, der ist gesegnet, und wen du verfluchst, der ist verflucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Und die Ältesten von Moab und die Ältesten von Midian zogen hin mit dem Wahrsagerlohn in der Hand. Und sie kamen zu Bileam und redeten zu ihm die Worte Balaks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Und er sprach zu ihnen: Übernachtet hier diese Nacht, und ich werde euch Antwort bringen, so wie Jehova zu mir reden wird. Und die Fürsten von Moab blieben bei Bileam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Und Gott kam zu Bileam und sprach: Wer sind diese Männer bei dir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Und Bileam sprach zu Gott: Balak, der Sohn Zippors, der König von Moab, hat zu mir gesandt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Siehe, das Volk, das aus Ägypten gezogen ist, es bedeckt die Fläche des Landes; komm nun, verwünsche es mir, vielleicht vermag ich wider dasselbe zu streiten und es zu vertreiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Und Gott sprach zu Bileam: Du sollst nicht mit ihnen gehen; du sollst das Volk nicht verfluchen, denn es ist gesegnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Und Bileam stand des Morgens auf und sprach zu den Fürsten Balaks: Ziehet in euer Land; denn Jehova hat sich geweigert, mir zu gestatten, mit euch zu gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Und die Fürsten von Moab machten sich auf und kamen zu Balak und sprachen: Bileam hat sich geweigert, mit uns zu gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Da sandte Balak noch einmal Fürsten, mehr und geehrtere als jene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Und sie kamen zu Bileam und sprachen zu ihm: So spricht Balak, der Sohn Zippors: Laß dich doch nicht abhalten, zu mir zu kommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'denn sehr hoch will ich dich ehren, und alles, was du mir sagen wirst, will ich tun; so komm doch, verwünsche mir dieses Volk!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Und Bileam antwortete und sprach zu den Knechten Balaks: Wenn Balak mir sein Haus voll Silber und Gold gäbe, so vermöchte ich nicht den Befehl Jehovas, meines Gottes, zu übertreten, um Kleines oder Großes zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Und nun bleibet doch hier, auch ihr, diese Nacht, und ich werde erfahren, was Jehova ferner mit mir reden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Da kam Gott des Nachts zu Bileam und sprach zu ihm: Wenn die Männer gekommen sind, um dich zu rufen, so mache dich auf, gehe mit ihnen; aber nur dasjenige, was ich dir sagen werde, sollst du tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Und Bileam machte sich am Morgen auf und sattelte seine Eselin und zog mit den Fürsten von Moab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Da entbrannte der Zorn Gottes, daß er hinzog; und der Engel Jehovas stellte sich in den Weg, ihm zu widerstehen. Er aber ritt auf seiner Eselin, und seine beiden Jünglinge waren mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Und die Eselin sah den Engel Jehovas auf dem Wege stehen mit seinem gezückten Schwert in seiner Hand, und die Eselin bog vom Wege ab und ging ins Feld; und Bileam schlug die Eselin, um sie wieder auf den Weg zu lenken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Da trat der Engel Jehovas in einen Hohlweg zwischen den Weinbergen: eine Mauer war auf dieser, und eine Mauer auf jener Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Und die Eselin sah den Engel Jehovas und drängte sich an die Wand und drückte den Fuß Bileams an die Wand; und er schlug sie noch einmal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Da ging der Engel Jehovas nochmals weiter und trat an einen engen Ort, wo kein Weg war auszubiegen, weder zur Rechten noch zur Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Und als die Eselin den Engel Jehovas sah, legte sie sich nieder unter Bileam; und es entbrannte der Zorn Bileams, und er schlug die Eselin mit dem Stabe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Da tat Jehova den Mund der Eselin auf, und sie sprach zu Bileam: Was habe ich dir getan, daß du mich nun dreimal geschlagen hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Und Bileam sprach zu der Eselin: Weil du Spott mit mir getrieben hast; wäre doch ein Schwert in meiner Hand, so hätte ich dich jetzt totgeschlagen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Und die Eselin sprach zu Bileam: Bin ich nicht deine Eselin, auf der du geritten bist von jeher bis auf diesen Tag? War ich je gewohnt, dir also zu tun? Und er sprach: Nein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Da enthüllte Jehova die Augen Bileams, und er sah den Engel Jehovas auf dem Wege stehen, mit seinem gezückten Schwert in seiner Hand; und er neigte sich und warf sich nieder auf sein Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Und der Engel Jehovas sprach zu ihm: Warum hast du deine Eselin nun dreimal geschlagen? Siehe, ich bin ausgegangen, dir zu widerstehen, denn der Weg ist verderblich vor mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Und die Eselin sah mich und bog vor mir aus nun dreimal; wenn sie nicht vor mir ausgebogen wäre, so hätte ich dich jetzt auch erschlagen, sie aber am Leben gelassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Und Bileam sprach zu dem Engel Jehovas: Ich habe gesündigt, denn ich wußte nicht, daß du mir auf dem Wege entgegenstandest; und nun, wenn es übel ist in deinen Augen, so will ich umkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Und der Engel Jehovas sprach zu Bileam: Gehe mit den Männern; aber nur dasjenige, was ich dir sagen werde, sollst du reden. Und Bileam zog mit den Fürsten Balaks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Und als Balak hörte, daß Bileam käme, da ging er aus, ihm entgegen, nach der Stadt Moabs, an der Grenze des Arnon, der an der äußersten Grenze fließt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Und Balak sprach zu Bileam: Habe ich nicht ausdrücklich zu dir gesandt, um dich zu rufen? Warum bist du nicht zu mir gekommen? Fürwahr, vermag ich nicht dich zu ehren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Und Bileam sprach zu Balak: Siehe, ich bin zu dir gekommen; vermag ich nun wohl irgend etwas zu reden? Das Wort, das Gott mir in den Mund legt, das werde ich reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Und Bileam ging mit Balak; und sie kamen nach Kirjath-Chuzoth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Und Balak opferte Rind-und Kleinvieh und schickte davon dem Bileam und den Fürsten, die bei ihm waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Und es geschah am Morgen, da nahm Balak den Bileam und führte ihn hinauf nach den Höhen des Baal, und er sah von dort aus das Äußerste des Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Und Bileam sprach zu Balak: Baue mir hier sieben Altäre, und stelle mir hier bereit sieben Farren und sieben Widder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Und Balak tat, so wie Bileam gesagt hatte; und Balak und Bileam opferten einen Farren und einen Widder auf jedem Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Und Bileam sprach zu Balak: Stelle dich neben dein Brandopfer, und ich will gehen; vielleicht wird Jehova mir entgegenkommen, und was er mich sehen lassen wird, das werde ich dir kundtun. Und er ging auf eine kahle Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Und Gott kam dem Bileam entgegen; und dieser sprach zu ihm: Die sieben Altäre habe ich zugerichtet und auf jedem Altar einen Farren und einen Widder geopfert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Und Jehova legte ein Wort in den Mund Bileams und sprach: Kehre zu Balak zurück, und so sollst du reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Und er kehrte zu ihm zurück; und siehe, er stand neben seinem Brandopfer, er und alle Fürsten von Moab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Da hob er seinen Spruch an und sprach: Aus Aram hat Balak mich hergeführt, der König von Moab von den Bergen des Ostens: Komm, verfluche mir Jakob; ja, komm, verwünsche Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Wie soll ich verfluchen, den Gott nicht verflucht, und wie verwünschen, den Jehova nicht verwünscht hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Denn vom Gipfel der Felsen sehe ich es, und von den Höhen herab schaue ich es: siehe, ein Volk, das abgesondert wohnt und unter die Nationen nicht gerechnet wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Wer könnte zählen den Staub Jakobs und, der Zahl nach, den vierten Teil Israels? Meine Seele sterbe den Tod der Rechtschaffenen, und mein Ende sei gleich dem ihrigen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Da sprach Balak zu Bileam: Was hast du mir getan! Meine Feinde zu verwünschen habe ich dich holen lassen, und siehe, du hast sie sogar gesegnet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Und er antwortete und sprach: Muß ich nicht darauf achten, das zu reden, was Jehova in meinen Mund legt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Und Balak sprach zu ihm: Komm doch mit mir an einen anderen Ort, von wo aus du es sehen wirst; nur sein Äußerstes wirst du sehen, und ganz wirst du es nicht sehen; und verwünsche es mir von dort aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Und er nahm ihn mit nach dem Felde der Wächter, auf den Gipfel des Pisga; und er baute sieben Altäre und opferte einen Farren und einen Widder auf jedem Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Und er sprach zu Balak: Stelle dich hier neben dein Brandopfer, und ich, ich will dort entgegengehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Und Jehova kam dem Bileam entgegen und legte ein Wort in seinen Mund und sprach: Kehre zu Balak zurück, und so sollst du reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Und er kam zu ihm, und siehe, er stand neben seinem Brandopfer, und die Fürsten von Moab mit ihm. Und Balak sprach zu ihm: Was hat Jehova geredet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Da hob er seinen Spruch an und sprach: Stehe auf, Balak, und höre! Horche auf mich, Sohn Zippors!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Nicht ein Mensch ist Gott, daß er lüge, noch ein Menschensohn, daß er bereue. Sollte er gesprochen haben und es nicht tun, und geredet haben und es nicht aufrecht halten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Siehe, zu segnen habe ich empfangen; und er hat gesegnet, und ich kann es nicht wenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Er erblickt keine Ungerechtigkeit in Jakob und sieht kein Unrecht in Israel; Jehova, sein Gott, ist mit ihm, und Jubelgeschrei wie um einen König ist in seiner Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Gott hat ihn aus Ägypten herausgeführt; sein ist die Stärke des Wildochsen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Denn da ist keine Zauberei wider Jakob, und keine Wahrsagerei wider Israel. Um diese Zeit wird von Jakob und von Israel gesagt werden, was Gott gewirkt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Siehe, ein Volk: gleich einer Löwin steht es auf, und gleich einem Löwen erhebt es sich! Es legt sich nicht nieder, bis es den Raub verzehrt und das Blut der Erschlagenen getrunken hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Da sprach Balak zu Bileam: Du sollst es gar nicht verwünschen, und du sollst es gar nicht segnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Und Bileam antwortete und sprach zu Balak: Habe ich nicht zu dir geredet und gesagt: Alles, was Jehova reden wird, das werde ich tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Und Balak sprach zu Bileam: Komm doch, ich will dich an einen anderen Ort mitnehmen; vielleicht wird es in den Augen Gottes recht sein, daß du es mir von dort aus verwünschest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Und Balak nahm den Bileam mit auf den Gipfel des Peor, der emporragt über die Fläche der Wildnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Und Bileam sprach zu Balak: Baue mir hier sieben Altäre, und stelle mir hier bereit sieben Farren und sieben Widder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Und Balak tat, so wie Bileam gesagt hatte; und er opferte einen Farren und einen Widder auf jedem Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Und als Bileam sah, daß es gut war in den Augen Jehovas, Israel zu segnen, so ging er nicht, wie die anderen Male, auf Wahrsagerei aus, sondern richtete sein Angesicht nach der Wüste hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Und Bileam erhob seine Augen und sah Israel, gelagert nach seinen Stämmen; und der Geist Gottes kam über ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Und er hob seinen Spruch an und sprach: Es spricht Bileam, der Sohn Beors, und es spricht der Mann geöffneten Auges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Es spricht, der da hört die Worte Gottes, der ein Gesicht des Allmächtigen sieht, der hinfällt und enthüllter Augen ist:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Wie schön sind deine Zelte, Jakob, deine Wohnungen, Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Gleich Tälern breiten sie sich aus, gleich Gärten am Strome, gleich Aloebäumen, die Jehova gepflanzt hat, gleich Zedern am Gewässer!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Wasser wird fließen aus seinen Eimern, und sein Same wird in großen Wassern sein; und sein König wird höher sein als Agag, und sein Königreich wird erhaben sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Gott hat ihn aus Ägypten herausgeführt; sein ist die Stärke des Wildochsen. Er wird die Nationen, seine Feinde, fressen und ihre Gebeine zermalmen und mit seinen Pfeilen sie zerschmettern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Er duckt sich, er legt sich nieder wie ein Löwe und wie eine Löwin; wer will ihn aufreizen? Die dich segnen, sind gesegnet, und die dich verfluchen, sind verflucht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Da entbrannte der Zorn Balaks wider Bileam, und er schlug seine Hände zusammen; und Balak sprach zu Bileam: Meine Feinde zu verwünschen, habe ich dich gerufen, und siehe, du hast sie sogar gesegnet, nun dreimal!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Und nun fliehe an deinen Ort. Ich hatte gesagt, ich wolle dich hoch ehren; und siehe, Jehova hat dir die Ehre verwehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Und Bileam sprach zu Balak: Habe ich nicht auch zu deinen Boten, die du zu mir gesandt hast, geredet und gesagt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Wenn Balak mir sein Haus voll Silber und Gold gäbe, so vermöchte ich nicht den Befehl Jehovas zu übertreten, um aus meinem eigenen Herzen Gutes oder Böses zu tun; was Jehova reden wird, das werde ich reden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Und nun siehe, ich gehe zu meinem Volke. Komm, ich will dir anzeigen, was dieses Volk deinem Volke tun wird am Ende der Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Und er hob seinen Spruch an und sprach: Es spricht Bileam, der Sohn Beors, und es spricht der Mann geöffneten Auges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Es spricht, der da hört die Worte Gottes, und der die Erkenntnis des Höchsten besitzt, der ein Gesicht des Allmächtigen sieht, der hinfällt und enthüllter Augen ist:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Ich sehe ihn, aber nicht jetzt, ich schaue ihn, aber nicht nahe; es tritt hervor ein Stern aus Jakob, und ein Zepter erhebt sich aus Israel und zerschlägt die Seiten Moabs und zerschmettert alle Söhne des Getümmels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Und Edom wird ein Besitz sein und Seir ein Besitz, sie, seine Feinde; und Israel wird Mächtiges tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Und einer aus Jakob wird herrschen, und er wird aus der Stadt den Überrest vertilgen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Und er sah Amalek und hob seinen Spruch an und sprach: Die erste der Nationen war Amalek, aber sein Letztes wird dem Untergang verfallen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Und er sah die Keniter und hob seinen Spruch an und sprach: Fest ist dein Wohnsitz, und auf den Felsen gesetzt dein Nest;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'doch der Keniter soll vertilgt werden, bis Assur dich gefangen wegführt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Und er hob seinen Spruch an und sprach: Wehe! Wer wird am Leben bleiben, sobald Gott dieses herbeiführt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Und Schiffe werden kommen von der Küste von Kittim und werden Assur demütigen, und Heber demütigen, und auch er wird dem Untergang verfallen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Und Bileam machte sich auf und ging und kehrte zurück an seinen Ort; und auch Balak zog seines Weges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Und Israel blieb in Sittim. Und das Volk fing an zu huren mit den Töchtern Moabs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'und diese luden das Volk zu den Opfern ihrer Götter, und das Volk aß und beugte sich nieder vor ihren Göttern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Und Israel hängte sich an den Baal-Peor; und der Zorn Jehovas entbrannte wider Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Da sprach Jehova zu Mose: Nimm alle Häupter des Volkes und hänge sie dem Jehova auf vor der Sonne, damit die Glut des Zornes Jehovas sich von Israel abwende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Und Mose sprach zu den Richtern Israels: Erschlaget ein jeder seine Leute, die sich an den Baal-Peor gehängt haben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Und siehe, ein Mann von den Kindern Israel kam und brachte eine Midianitin zu seinen Brüdern, vor den Augen Moses und vor den Augen der ganzen Gemeinde der Kinder Israel, als diese an dem Eingang des Zeltes der Zusammenkunft weinten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Und als Pinehas, der Sohn Eleasars, des Sohnes Aarons, des Priesters, es sah, da stand er auf aus der Mitte der Gemeinde und nahm eine Lanze in seine Hand;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'und er ging dem israelitischen Manne nach in das Innere des Zeltes und durchstach sie beide, den israelitischen Mann und das Weib, durch ihren Bauch. Da ward die Plage von den Kindern Israel abgewehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Und es waren der an der Plage Gestorbenen vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Pinehas, der Sohn Eleasars, des Sohnes Aarons, des Priesters, hat meinen Grimm von den Kindern Israel abgewendet, indem er in meinem Eifer in ihrer Mitte geeifert hat, so daß ich die Kinder Israel nicht in meinem Eifer vertilgt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Darum sprich: Siehe, ich gebe ihm meinen Bund des Friedens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'und er wird ihm und seinem Samen nach ihm ein Bund ewigen Priestertums sein, darum daß er für seinen Gott geeifert und für die Kinder Israel Sühnung getan hat. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Und der Name des erschlagenen israelitischen Mannes, der mit der Midianitin erschlagen wurde, war Simri, der Sohn Salus, der Fürst eines Vaterhauses der Simeoniter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'und der Name des erschlagenen midianitischen Weibes war Kosbi, die Tochter Zurs; er war Stammhaupt eines Vaterhauses unter den Midianitern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Befeindet die Midianiter und schlaget sie;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'denn sie haben euch befeindet durch ihre List, womit sie euch überlistet haben in der Sache des Peor und in der Sache der Kosbi, der Tochter eines Fürsten von Midian, ihrer Schwester, welche am Tage der Plage wegen des Peor erschlagen wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Und es geschah nach der Plage, da sprach Jehova zu Mose und zu Eleasar, dem Sohne Aarons, dem Priester, und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Nehmet auf die Summe der ganzen Gemeinde der Kinder Israel, von zwanzig Jahren und darüber, nach ihren Vaterhäusern, einen jeden, der zum Heere auszieht in Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Und Mose und Eleasar, der Priester, redeten zu ihnen in den Ebenen Moabs, am Jordan von Jericho, und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Von zwanzig Jahren und darüber...,so wie Jehova dem Mose geboten hatte. Und es waren die Kinder Israel, die aus dem Lande Ägypten ausgezogen waren:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben, der Erstgeborene Israels; die Söhne Rubens: von Hanok das Geschlecht der Hanokiter; von Pallu das Geschlecht der Palluiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'von Hezron das Geschlecht der Hezroniter; von Karmi das Geschlecht der Karmiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Das sind die Geschlechter der Rubeniter; und ihre Gemusterten waren dreiundvierzigtausend siebenhundertdreißig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Und die Söhne Pallus: Eliab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Und die Söhne Eliabs: Nemuel und Dathan und Abiram; das ist der Dathan und der Abiram, Berufene der Gemeinde, welche wider Mose und wider Aaron haderten in der Rotte Korahs, als sie wider Jehova haderten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'Und die Erde tat ihren Mund auf und verschlang sie und Korah, als die Rotte starb, indem das Feuer die zweihundertfünfzig Männer verzehrte, und sie zu einem Zeichen wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Aber die Söhne Korahs starben nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Die Söhne Simeons nach ihren Geschlechtern: von Nemuel das Geschlecht der Nemueliter; von Jamin das Geschlecht der Jaminiter; von Jakin das Geschlecht der Jakiniter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'von Serach das Geschlecht der Sarchiter; von Saul das Geschlecht der Sauliter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Das sind die Geschlechter der Simeoniter: zweiundzwanzigtausend zweihundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Die Söhne Gads nach ihren Geschlechtern: von Zephon das Geschlecht der Zephoniter; von Haggi das Geschlecht der Haggiter; von Schuni das Geschlecht der Schuniter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'von Osni das Geschlecht der Osniter; von Eri das Geschlecht der Eriter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Von Arod das Geschlecht der Aroditer; von Areli das Geschlecht der Areliter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Das sind die Geschlechter der Söhne Gads, nach ihren Gemusterten, vierzigtausend fünfhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Die Söhne Judas: Gher und Onan; Gher und Onan aber starben im Lande Kanaan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Und es waren die Söhne Judas nach ihren Geschlechtern: von Schela das Geschlecht der Schelaniter; von Perez das Geschlecht der Parziter; von Serach das Geschlecht der Sarchiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Und die Söhne Perez\' waren: Von Hezron das Geschlecht der Hezroniter; von Hamul das Geschlecht der Hamuliter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Das sind die Geschlechter Judas nach ihren Gemusterten: sechsundsiebzigtausend fünfhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Die Söhne Issaschars nach ihren Geschlechtern: von Tola das Geschlecht der Tolaiter; von Puwa das Geschlecht der Puniter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'von Jaschub das Geschlecht der Jaschubiter; von Schimron das Geschlecht der Schimroniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Das sind die Geschlechter Issaschars, nach ihren Gemusterten: vierundsechzigtausend dreihundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Die Söhne Sebulons nach ihren Geschlechtern: von Sered das Geschlecht der Sarditer; von Elon das Geschlecht der Eloniter; von Jachleel das Geschlecht der Jachleeliter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Das sind die Geschlechter der Sebuloniter, nach ihren Gemusterten: sechzigtausend fünfhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Die Söhne Josephs nach ihren Geschlechtern: Manasse und Ephraim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Die Söhne Manasses: von Makir das Geschlecht der Makiriter (und Makir zeugte Gilead); von Gilead das Geschlecht der Gileaditer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Dies sind die Söhne Gileads: von Jieser das Geschlecht der Jieseriter; von Helek das Geschlecht der Helkiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'und von Asriel das Geschlecht der Asrieliter; und von Sichem das Geschlecht der Sikmiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'und von Schemida das Geschlecht der Schemidaiter; und von Hepher das Geschlecht der Hephriter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Und Zelophchad, der Sohn Hephers, hatte keine Söhne, sondern nur Töchter; und die Namen der Töchter Zelophchads waren: Machla und Noa, Chogla, Milka und Tirza. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Das sind die Geschlechter Manasses; und ihrer Gemusterten waren zweiundfünfzigtausend siebenhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Dies sind die Söhne Ephraims nach ihren Geschlechtern: von Schuthelach das Geschlecht der Schuthalchiter; von Beker das Geschlecht der Bakriter; von Tachan das Geschlecht der Tachaniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Und dies sind die Söhne Schuthelachs: von Eran das Geschlecht der Eraniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Das sind die Geschlechter der Söhne Ephraims, nach ihren Gemusterten: zweiunddreißigtausend fünfhundert. Das sind die Söhne Josephs nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Die Söhne Benjamins nach ihren Geschlechtern: von Bela das Geschlecht der Baliter; von Aschbel das Geschlecht der Aschbeliter; von Achiram das Geschlecht der Achiramiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'von Schephupham das Geschlecht der Schuphamiter; von Hupham das Geschlecht der Huphamiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Und die Söhne Belas waren: Ard und Naaman; von Ard das Geschlecht der Arditer, von Naaman das Geschlecht der Naamaniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Das sind die Söhne Benjamins nach ihren Geschlechtern; und ihrer Gemusterten waren fünfundvierzigtausend sechshundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Dies sind die Söhne Dans nach ihren Geschlechtern: von Schucham das Geschlecht der Schuchamiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Das sind die Geschlechter Dans nach ihren Geschlechtern. Alle Geschlechter der Schuchamiter, nach ihren Gemusterten: Vierundsechzigtausend vierhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Die Söhne Asers nach ihren Geschlechtern: von Jimna das Geschlecht der Jimna; von Jischwi das Geschlecht der Jischwiter; von Beria das Geschlecht der Beriiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Von den Söhnen Berias: von Heber das Geschlecht der Hebriter; von Malkiel das Geschlecht der Malkieliter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Und der Name der Tochter Asers war Serach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Das sind die Geschlechter der Söhne Asers, nach ihren Gemusterten: dreiundfünfzigtausend vierhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Die Söhne Naphtalis nach ihren Geschlechtern: von Jachzeel das Geschlecht der Jachzeeliter; von Guni das Geschlecht der Guniter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'von Jezer das Geschlecht der Jizriter; von Schillem das Geschlecht der Schillemiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Das sind die Geschlechter Naphtalis nach ihren Geschlechtern; und ihrer Gemusterten waren fünfundvierzigtausend vierhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Das sind die Gemusterten der Kinder Israel: sechshunderteintausend siebenhundertdreißig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Diesen soll das Land nach der Zahl der Namen als Erbteil verteilt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Den Vielen sollst du ihr Erbteil mehren und den Wenigen ihr Erbteil mindern; einem jeden soll nach Verhältnis seiner Gemusterten sein Erbteil gegeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Doch soll das Land durchs Los verteilt werden; nach den Namen der Stämme ihrer Väter sollen sie erben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'nach der Entscheidung des Loses soll jedem Stamme sein Erbteil zugeteilt werden, sowohl den Vielen, als auch den Wenigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Und dies sind die Gemusterten Levis nach ihren Geschlechtern: von Gerson das Geschlecht der Gersoniter; von Kehath das Geschlecht der Kehathiter; von Merari das Geschlecht der Merariter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Dies sind die Geschlechter Levis: das Geschlecht der Libniter, das Geschlecht der Hebroniter, das Geschlecht der Machliter, das Geschlecht der Muschiter, das Geschlecht der Korhiter. Und Kehath zeugte Amram.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Und der Name des Weibes Amrams war Jokebed, eine Tochter Levis, die dem Levi in Ägypten geboren wurde; und sie gebar dem Amram Aaron und Mose und Mirjam, ihre Schwester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Und dem Aaron wurden geboren Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Und Nadab und Abihu starben, als sie fremdes Feuer vor Jehova darbrachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Und ihrer Gemusterten, aller Männlichen von einem Monat und darüber, waren dreiundzwanzigtausend; denn sie wurden nicht unter den Kindern Israel gemustert, weil ihnen kein Erbteil unter den Kindern Israel gegeben wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Das sind die durch Mose und Eleasar, den Priester, Gemusterten, welche die Kinder Israel in den Ebenen Moabs, am Jordan von Jericho, musterten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Und unter diesen war kein Mann von denen, welche durch Mose und Aaron, den Priester, gemustert worden waren, welche die Kinder Israel in der Wüste Sinai musterten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Denn Jehova hatte von ihnen gesagt: Sie sollen gewißlich in der Wüste sterben! Und kein Mann von ihnen war übriggeblieben außer Kaleb, dem Sohne Jephunnes, und Josua, dem Sohne Nuns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Und es nahten herzu die Töchter Zelophchads, des Sohnes Hephers, des Sohnes Gileads, des Sohnes Makirs, des Sohnes Manasses, von den Geschlechtern Manasses, des Sohnes Josephs; und dies waren die Namen seiner Töchter: Machla, Noa und Chogla und Milka und Tirza.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Und sie traten vor Mose und vor Eleasar, den Priester, und vor die Fürsten und die ganze Gemeinde an den Eingang des Zeltes der Zusammenkunft und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Unser Vater ist in der Wüste gestorben; er war aber nicht unter der Rotte derer, die sich in der Rotte Korahs wider Jehova zusammenrotteten, sondern er ist in seiner Sünde gestorben; und er hatte keine Söhne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Warum soll der Name unseres Vaters abgeschnitten werden aus der Mitte seines Geschlechts, weil er keinen Sohn hat? Gib uns ein Eigentum unter den Brüdern unseres Vaters!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Und Mose brachte ihre Rechtssache vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Die Töchter Zelophchads reden recht; du sollst ihnen sicherlich ein Erbbesitztum unter den Brüdern ihres Vaters geben, und sollst das Erbteil ihres Vaters auf sie übergehen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Und zu den Kindern Israel sollst du reden und sprechen: Wenn ein Mann stirbt und keinen Sohn hat, so sollt ihr sein Erbteil auf seine Tochter übergehen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Und wenn er keine Tochter hat, so sollt ihr sein Erbteil seinen Brüdern geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Und wenn er keine Brüder hat, so sollt ihr sein Erbteil den Brüdern seines Vaters geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Und wenn sein Vater keine Brüder hat, so sollt ihr sein Erbteil seinem Blutsverwandten geben, dem ihm am nächsten stehenden aus seinem Geschlecht, daß er es erbe. Und das soll den Kindern Israel zu einer Rechtssatzung sein, so wie Jehova dem Mose geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Und Jehova sprach zu Mose: Steige auf dieses Gebirge Abarim und sieh das Land, das ich den Kindern Israel gegeben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Und hast du es gesehen, so wirst auch du zu deinen Völkern versammelt werden, so wie dein Bruder Aaron versammelt worden ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Weil ihr in der Wüste Zin, beim Hadern der Gemeinde, widerspenstig gewesen seid gegen meinen Befehl, mich durch das Wasser vor ihren Augen zu heiligen. (Das ist das Haderwasser von Kades in der Wüste Zin.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Und Mose redete zu Jehova und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Es bestelle Jehova, der Gott der Geister alles Fleisches, einen Mann über die Gemeinde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'der vor ihnen her aus-und einziehe, und der sie aus-und einführe; damit die Gemeinde Jehovas nicht sei wie Schafe, die keinen Hirten haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Und Jehova sprach zu Mose: Nimm dir Josua, den Sohn Nuns, einen Mann, in dem der Geist ist, und lege deine Hand auf ihn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'und stelle ihn vor Eleasar, den Priester, und vor die ganze Gemeinde, und gib ihm Befehl vor ihren Augen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'und lege von deiner Würde auf ihn, damit die ganze Gemeinde der Kinder Israel ihm gehorche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Und er soll vor Eleasar, den Priester, treten, und der soll für ihn das Urteil der Urim vor Jehova befragen: Nach seinem Befehle sollen sie ausziehen, und nach seinem Befehle sollen sie einziehen, er und alle Kinder Israel mit ihm, ja, die ganze Gemeinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Und Mose tat, so wie Jehova ihm geboten hatte, und nahm Josua und stellte ihn vor Eleasar, den Priester, und vor die ganze Gemeinde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'und er legte seine Hände auf ihn und gab ihm Befehl, so wie Jehova durch Mose geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Gebiete den Kindern Israel und sprich zu ihnen: Meine Opfergabe, meine Speise zu meinen Feueropfern, mir zum lieblichen Geruch, sollt ihr acht haben mir darzubringen zu ihrer bestimmten Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Und sprich zu ihnen: Dies ist das Feueropfer, das ihr Jehova darbringen sollt: zwei einjährige Lämmer ohne Fehl, täglich, als beständiges Brandopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Das eine Lamm sollst du am Morgen opfern, und das zweite Lamm sollst du opfern zwischen den zwei Abenden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'und zum Speisopfer ein zehntel Epha Feinmehl, gemengt mit einem viertel Hin zerstoßenen Öles,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, '(ein beständiges Brandopfer, das am Berge Sinai eingesetzt wurde, zum lieblichen Geruch, ein Feueropfer dem Jehova);');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'und sein Trankopfer, ein viertel Hin zu dem einen Lamme; im Heiligtum sollst du das Trankopfer von starkem Getränk dem Jehova spenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Und das zweite Lamm sollst du opfern zwischen den zwei Abenden; wie das Morgenspeisopfer und sein Trankopfer, so sollst du zu diesem opfern, ein Feueropfer lieblichen Geruchs dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Und am Sabbathtage zwei einjährige Lämmer ohne Fehl, und als Speisopfer zwei Zehntel Feinmehl, gemengt mit Öl, und sein Trankopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Es ist das Brandopfer des Sabbaths an jedem Sabbath nebst dem beständigen Brandopfer und seinem Trankopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Und im Anfang eurer Monate sollt ihr Jehova ein Brandopfer darbringen: zwei junge Farren und einen Widder, sieben einjährige Lämmer ohne Fehl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'und zu jedem Farren drei Zehntel Feinmehl, gemengt mit Öl, als Speisopfer; und zu dem einen Widder zwei Zehntel Feinmehl, gemengt mit Öl, als Speisopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'und zu jedem Lamme je ein Zehntel Feinmehl, gemengt mit Öl, als Speisopfer. Es ist ein Brandopfer, ein lieblicher Geruch, ein Feueropfer dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Und ihre Trankopfer: ein halbes Hin Wein soll zu einem Farren sein, und ein drittel Hin zu dem Widder, und ein viertel Hin zu einem Lamme. Das ist das monatliche Brandopfer in jedem Monat, nach den Monaten des Jahres.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Und ein Ziegenbock zum Sündopfer dem Jehova soll nebst dem beständigen Brandopfer und seinem Trankopfer geopfert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Und im ersten Monat, am vierzehnten Tage des Monats, ist Passah dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Und am fünfzehnten Tage dieses Monats ist das Fest; sieben Tage soll Ungesäuertes gegessen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Am ersten Tage soll eine heilige Versammlung sein; keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Und ihr sollt dem Jehova ein Feueropfer, ein Brandopfer darbringen: zwei junge Farren und einen Widder und sieben einjährige Lämmer; ohne Fehl sollen sie euch sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'und ihr Speisopfer, Feinmehl, gemengt mit Öl: drei Zehntel sollt ihr opfern zu einem Farren, und zwei Zehntel zu dem Widder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'je ein Zehntel sollst du opfern zu jedem Lamme, zu den sieben Lämmern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'und einen Bock als Sündopfer, um Sühnung für euch zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Außer dem Morgenbrandopfer, das zum beständigen Brandopfer ist, sollt ihr das opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Solches sollt ihr täglich opfern, sieben Tage lang, als Speise eines Feueropfers lieblichen Geruchs dem Jehova; nebst dem beständigen Brandopfer und seinem Trankopfer soll es geopfert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Und am siebten Tage soll euch eine heilige Versammlung sein; keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Und am Tage der Erstlinge, wenn ihr dem Jehova ein neues Speisopfer darbringet, an eurem Wochenfeste, soll euch eine heilige Versammlung sein; keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Und ihr sollt ein Brandopfer darbringen zum lieblichen Geruch dem Jehova: zwei junge Farren, einen Widder, sieben einjährige Lämmer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'und ihr Speisopfer, Feinmehl, gemengt mit Öl: drei Zehntel zu jedem Farren, zwei Zehntel zu dem einen Widder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'je ein Zehntel zu jedem Lamme, zu den sieben Lämmern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'und einen Ziegenbock, um Sühnung für euch zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Außer dem beständigen Brandopfer und seinem Speisopfer sollt ihr sie opfern (ohne Fehl sollen sie euch sein) nebst ihren Trankopfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Und im siebten Monat, am Ersten des Monats, soll euch eine heilige Versammlung sein; keinerlei Dienstarbeit sollt ihr tun; ein Tag des Posaunenhalls soll es euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Und ihr sollt ein Brandopfer opfern zum lieblichen Geruch dem Jehova: einen jungen Farren, einen Widder, sieben einjährige Lämmer, ohne Fehl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'und ihr Speisopfer, Feinmehl, gemengt mit Öl: drei Zehntel zu dem Farren, zwei Zehntel zu dem Widder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'und ein Zehntel zu jedem Lamme, zu den sieben Lämmern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'und einen Ziegenbock als Sündopfer, um Sühnung für euch zu tun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'außer dem monatlichen Brandopfer und seinem Speisopfer und dem beständigen Brandopfer und seinem Speisopfer und ihren Trankopfern, nach ihrer Vorschrift, zum lieblichen Geruch, ein Feueropfer dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Und am Zehnten dieses siebten Monats soll euch eine heilige Versammlung sein, und ihr sollt eure Seelen kasteien; keinerlei Arbeit sollt ihr tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Und ihr sollt dem Jehova ein Brandopfer darbringen als lieblichen Geruch: einen jungen Farren, einen Widder, sieben einjährige Lämmer; ohne Fehl sollen sie euch sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'und ihr Speisopfer, Feinmehl, gemengt mit Öl: drei Zehntel zu dem Farren, zwei Zehntel zu dem einen Widder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'je ein Zehntel zu jedem Lamme, zu den sieben Lämmern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'und einen Ziegenbock als Sündopfer; außer dem Sündopfer der Versöhnung und dem beständigen Brandopfer und seinem Speisopfer und ihren Trankopfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Und am fünfzehnten Tage des siebten Monats soll euch eine heilige Versammlung sein; keinerlei Dienstarbeit sollt ihr tun, und ihr sollt dem Jehova ein Fest feiern sieben Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Und ihr sollt ein Brandopfer darbringen, ein Feueropfer lieblichen Geruchs dem Jehova: dreizehn junge Farren, zwei Widder, vierzehn einjährige Lämmer; ohne Fehl sollen sie sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'und ihr Speisopfer, Feinmehl, gemengt mit Öl: drei Zehntel zu jedem Farren, zu den dreizehn Farren, zwei Zehntel zu jedem Widder, zu den zwei Widdern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'und je ein Zehntel zu jedem Lamme, zu den vierzehn Lämmern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'und einen Ziegenbock als Sündopfer; außer dem beständigen Brandopfer, seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Und am zweiten Tage zwölf junge Farren, zwei Widder, vierzehn einjährige Lämmer ohne Fehl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'und ihr Speisopfer und ihre Trankopfer, zu den Farren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, nach der Vorschrift;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'und einen Ziegenbock als Sündopfer; außer dem beständigen Brandopfer und seinem Speisopfer und ihren Trankopfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Und am dritten Tage elf Farren, zwei Widder, vierzehn einjährige Lämmer, ohne Fehl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'und ihr Speisopfer und ihre Trankopfer, zu den Farren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, nach der Vorschrift;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'und einen Bock als Sündopfer; außer dem beständigen Brandopfer und seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Und am vierten Tage zehn Farren, zwei Widder, vierzehn einjährige Lämmer, ohne Fehl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'ihr Speisopfer und ihre Trankopfer, zu den Farren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, nach der Vorschrift;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'und einen Ziegenbock als Sündopfer; außer dem beständigen Brandopfer, seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Und am fünften Tage neun Farren, zwei Widder, vierzehn einjährige Lämmer, ohne Fehl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'und ihr Speisopfer und ihre Trankopfer, zu den Farren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, nach der Vorschrift;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'und einen Bock als Sündopfer; außer dem beständigen Brandopfer und seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Und am sechsten Tage acht Farren, zwei Widder, vierzehn einjährige Lämmer, ohne Fehl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'und ihr Speisopfer und ihre Trankopfer, zu den Farren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, nach der Vorschrift;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'und einen Bock als Sündopfer; außer dem beständigen Brandopfer, seinem Speisopfer und seinen Trankopfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Und am siebten Tage sieben Farren, zwei Widder, vierzehn einjährige Lämmer, ohne Fehl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'und ihr Speisopfer und ihre Trankopfer, zu den Farren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, nach ihrer Vorschrift;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'und einen Bock als Sündopfer; außer dem beständigen Brandopfer, seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Am achten Tage soll euch eine Festversammlung sein; keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Und ihr sollt ein Brandopfer darbringen, ein Feueropfer lieblichen Geruchs dem Jehova: einen Farren, einen Widder, sieben einjährige Lämmer, ohne Fehl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'ihr Speisopfer und ihre Trankopfer, zu dem Farren, zu dem Widder und zu den Lämmern, nach ihrer Zahl, nach der Vorschrift;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'und einen Bock als Sündopfer; außer dem beständigen Brandopfer und seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Das sollt ihr bei euren Festen dem Jehova opfern, außer euren Gelübden und euren freiwilligen Gaben an Brandopfern und an Speisopfern und an Trankopfern und an Friedensopfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'Und Mose redete zu den Kindern Israel nach allem, was Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Und Mose redete zu den Häuptern der Stämme der Kinder Israel und sprach: (H30:2) Dies ist es, was Jehova geboten hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, '(H30:3) Wenn ein Mann dem Jehova ein Gelübde tut, oder einen Eid schwört, ein Verbindnis auf seine Seele zu nehmen, so soll er sein Wort nicht brechen: nach allem, was aus seinem Munde hervorgegangen ist, soll er tun. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, '(H30:4) Und wenn ein Weib dem Jehova ein Gelübde tut oder ein Verbindnis auf sich nimmt im Hause ihres Vaters, in ihrer Jugend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, '(H30:5) und ihr Vater hört ihr Gelübde oder ihr Verbindnis, das sie auf ihre Seele genommen hat, und ihr Vater schweigt gegen sie: so sollen alle ihre Gelübde bestehen, und jedes Verbindnis, das sie auf ihre Seele genommen hat, soll bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, '(H30:6) Wenn aber ihr Vater ihr gewehrt hat an dem Tage, da er es hörte, so sollen alle ihre Gelübde und alle ihre Verbindnisse, die sie auf ihre Seele genommen hat, nicht bestehen; und Jehova wird ihr vergeben, weil ihr Vater ihr gewehrt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, '(H30:7) Und wenn sie etwa eines Mannes wird, und ihre Gelübde sind auf ihr, oder ein unbesonnener Ausspruch ihrer Lippen, wozu sie ihre Seele verbunden hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, '(H30:8) und ihr Mann hört es und schweigt gegen sie an dem Tage, da er es hört: so sollen ihre Gelübde bestehen, und ihre Verbindnisse, die sie auf ihre Seele genommen hat, sollen bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, '(H30:9) Wenn aber ihr Mann an dem Tage, da er es hört, ihr wehrt, so hebt er ihr Gelübde auf, das auf ihr ist, und den unbesonnenen Ausspruch ihrer Lippen, wozu sie ihre Seele verbunden hat; und Jehova wird ihr vergeben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, '(H30:10) Aber das Gelübde einer Witwe und einer Verstoßenen: alles, wozu sie ihre Seele verbunden hat, soll für sie bestehen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, '(H30:11) Und wenn ein Weib im Hause ihres Mannes ein Gelübde getan oder durch einen Eid ein Verbindnis auf ihre Seele genommen hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, '(H30:12) und ihr Mann hat es gehört und gegen sie geschwiegen, er hat ihr nicht gewehrt: so sollen alle ihre Gelübde bestehen, und jedes Verbindnis, das sie auf ihre Seele genommen hat, soll bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, '(H30:13) Wenn aber ihr Mann dieselben irgend aufgehoben hat an dem Tage, da er sie hörte, so soll alles, was über ihre Lippen gegangen ist an Gelübden und an Verbindnissen ihrer Seele, nicht bestehen; ihr Mann hat dieselben aufgehoben, und Jehova wird ihr vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, '(H30:14) Jedes Gelübde und jeder Eid des Verbindnisses, um die Seele zu kasteien ihr Mann kann es bestätigen, und ihr Mann kann es aufheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, '(H30:15) Und wenn ihr Mann von Tag zu Tage gänzlich gegen sie schweigt, so bestätigt er alle ihre Gelübde oder alle ihre Verbindnisse, die auf ihr sind; er hat sie bestätigt, denn er hat gegen sie geschwiegen an dem Tage, da er sie hörte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, '(H30:16) Wenn er sie aber irgend aufhebt, nachdem er sie gehört hat, so wird er ihre Ungerechtigkeit tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, '(H30:17) Das sind die Satzungen, welche Jehova dem Mose geboten hat, zwischen einem Manne und seinem Weibe, zwischen einem Vater und seiner Tochter in ihrer Jugend, im Hause ihres Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Übe Rache für die Kinder Israel an den Midianitern; danach sollst du zu deinen Völkern versammelt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Und Mose redete zu dem Volke und sprach: Rüstet von euch Männer zum Heere aus, daß sie wider Midian ziehen, um die Rache Jehovas an Midian auszuführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Je tausend vom Stamme, von allen Stämmen Israels, sollt ihr zum Heere absenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Und es wurden aus den Tausenden Israels tausend von jedem Stamme ausgehoben: zwölftausend zum Heere Gerüstete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Und Mose sandte sie, tausend von jedem Stamme, zum Heere ab, sie und Pinehas, den Sohn Eleasars, des Priesters, zum Heere; und die heiligen Geräte, die Trompeten zum Lärmblasen, waren in seiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Und sie stritten wider Midian, so wie Jehova dem Mose geboten hatte, und töteten alles Männliche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Und sie töteten die Könige von Midian, samt ihren Erschlagenen: Ewi und Rekem und Zur und Hur und Reba, fünf Könige von Midian; und auch Bileam, den Sohn Beors, töteten sie mit dem Schwerte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Und die Kinder Israel führten die Weiber der Midianiter und ihre Kinder gefangen hinweg, und erbeuteten all ihr Vieh und alle ihre Herden und alle ihre Habe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'und alle ihre Städte in ihren Wohnsitzen und alle ihre Gehöfte verbrannten sie mit Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Und sie nahmen alle Beute und allen Raub an Menschen und an Vieh,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'und brachten die Gefangenen und den Raub und die Beute zu Mose und zu Eleasar, dem Priester, und zu der Gemeinde der Kinder Israel ins Lager, in die Ebenen Moabs, die am Jordan von Jericho sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Und Mose und Eleasar, der Priester, und alle Fürsten der Gemeinde gingen ihnen entgegen außerhalb des Lagers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Und Mose ward zornig über die Vorgesetzten des Heeres, die Obersten über tausend und die Obersten über hundert, die von dem Kriegszuge kamen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'und Mose sprach zu ihnen: Habt ihr alle Weiber am Leben gelassen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Siehe, sie sind ja auf den Rat Bileams den Kindern Israel ein Anlaß geworden in der Sache des Peor eine Untreue gegen Jehova zu begehen, so daß die Plage über die Gemeinde Jehovas kam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'So tötet nun alles Männliche unter den Kindern, und tötet alle Weiber, die einen Mann im Beischlaf erkannt haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'aber alle Kinder, alle Mädchen, welche den Beischlaf eines Mannes nicht gekannt haben, laßt euch am Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Ihr aber lagert euch außerhalb des Lagers sieben Tage; ein jeder, der einen Menschen getötet, und ein jeder, der einen Erschlagenen angerührt hat, ihr sollt euch entsündigen am dritten Tage und am siebten Tage, ihr und eure Gefangenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Und alle Kleider und alles Gerät von Fell und alle Arbeit von Ziegenhaar und alles Gerät von Holz sollt ihr entsündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Und Eleasar, der Priester, sprach zu den Kriegsleuten, die in den Streit gezogen waren: Dies ist die Satzung des Gesetzes, das Jehova dem Mose geboten hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Nur das Gold und das Silber, das Erz, das Eisen, das Zinn und das Blei,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'alles, was das Feuer verträgt, sollt ihr durchs Feuer gehen lassen, und es wird rein sein; nur soll es mit dem Wasser der Reinigung entsündigt werden; und alles, was das Feuer nicht verträgt, sollt ihr durchs Wasser gehen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Und am siebten Tage sollt ihr eure Kleider waschen, und ihr werdet rein sein; und danach möget ihr ins Lager kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Nimm auf die Summe der weggeführten Beute, an Menschen und an Vieh, du und Eleasar, der Priester, und die Häupter der Väter der Gemeinde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'und teile die Beute zur Hälfte zwischen denen, welche den Krieg geführt haben, die ins Feld gezogen sind, und der ganzen Gemeinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Und erhebe von den Kriegsleuten, die ins Feld gezogen sind, eine Abgabe für Jehova: eine Seele von fünfhundert, von den Menschen und von den Rindern und von den Eseln und vom Kleinvieh;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'von ihrer Hälfte sollt ihr sie nehmen, und du sollst sie Eleasar, dem Priester, geben als ein Hebopfer Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Und von der Hälfte der Kinder Israel sollst du eines nehmen, von fünfzig herausgegriffen, von den Menschen, von den Rindern, von den Eseln und vom Kleinvieh, von allem Vieh; und du sollst es den Leviten geben, welche der Hut der Wohnung Jehovas warten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Und Mose und Eleasar, der Priester, taten, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Und das Erbeutete, was von der Beute übrigblieb, welche das Kriegsvolk gemacht hatte, war: sechshundertfünfundsiebzig tausend Stück Kleinvieh,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'und zweiundsiebzigtausend Rinder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'und einundsechzigtausend Esel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'und was die Menschenseelen betrifft, so waren der Mädchen, welche den Beischlaf eines Mannes nicht gekannt hatten, insgesamt zweiunddreißigtausend Seelen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Und die Hälfte, der Anteil derer, welche zum Heere ausgezogen waren, die Zahl des Kleinviehes, war: dreihundertsiebenunddreißig tausend und fünfhundert Stück,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'und die Abgabe vom Kleinvieh für Jehova war sechshundertfünfundsiebzig Stück;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'und die Zahl der Rinder sechsunddreißigtausend, und die Abgabe davon für Jehova zweiundsiebzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'und der Esel dreißigtausend und fünfhundert, und die Abgabe davon für Jehova einundsechzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'und der Menschenseelen sechzehntausend, und die Abgabe davon für Jehova zweiunddreißig Seelen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Und Mose gab die Abgabe des Hebopfers Jehovas Eleasar, dem Priester, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Und von der Hälfte der Kinder Israel, welche Mose von den zum Heere ausgezogenen Männern abgeteilt hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(die Hälfte der Gemeinde war nämlich: dreihundertsiebenunddreißig tausend und fünfhundert Stück Kleinvieh,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'und sechsunddreißigtausend Rinder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'und dreißigtausend und fünfhundert Esel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'und sechzehntausend Menschenseelen)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'und von der Hälfte der Kinder Israel nahm Mose das Herausgegriffene, eines von fünfzig, von den Menschen und von dem Vieh, und gab sie den Leviten, welche der Hut der Wohnung Jehovas warteten; so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Und es traten zu Mose die Vorgesetzten über die Tausende des Heeres, die Obersten über tausend und die Obersten über hundert,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'und sprachen zu Mose: Deine Knechte haben die Summe der Kriegsleute aufgenommen, die unter unserer Hand waren, und es fehlt von uns nicht ein Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Und so bringen wir eine Opfergabe für Jehova dar, ein jeder, was er an goldenem Geschmeide gefunden hat: Armspangen und Handspangen, Fingerringe, Ohrringe und Spangen, um für unsere Seelen Sühnung zu tun vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Und Mose und Eleasar, der Priester, nahmen das Gold von ihnen, allerlei verarbeitetes Geschmeide.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Und alles Gold des Hebopfers, das sie für Jehova hoben, war sechzehntausend siebenhundertfünfzig Sekel, von den Obersten über tausend und von den Obersten über hundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, '(Die Kriegsleute aber hatten ein jeder für sich geplündert.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Und Mose und Eleasar, der Priester, nahmen das Gold von den Obersten über tausend und über hundert und brachten es in das Zelt der Zusammenkunft, als ein Gedächtnis der Kinder Israel vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Und die Kinder Ruben und die Kinder Gad hatten viel Vieh, in gewaltiger Menge; und sie sahen das Land Jaser und das Land Gilead, und siehe, der Ort war ein Ort für Vieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Und die Kinder Gad und die Kinder Ruben kamen und sprachen zu Mose und zu Eleasar, dem Priester, und zu den Fürsten der Gemeinde und sagten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Ataroth und Dibon und Jaser und Nimra und Hesbon und Elale und Sebam und Nebo und Beon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'das Land, welches Jehova vor der Gemeinde Israel geschlagen hat, ist ein Land für Vieh, und deine Knechte haben Vieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Und sie sprachen: Wenn wir Gnade in deinen Augen gefunden haben, so möge dieses Land deinen Knechten zum Eigentum gegeben werden; laß uns nicht über den Jordan ziehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Und Mose sprach zu den Kindern Gad und zu den Kindern Ruben: Sollen eure Brüder in den Streit ziehen, und ihr wollt hier bleiben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Und warum wollt ihr das Herz der Kinder Israel davon abwendig machen, in das Land hinüber zu ziehen, welches Jehova ihnen gegeben hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'So haben eure Väter getan, als ich sie von Kades-Barnea aussandte, das Land zu besehen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'sie zogen hinauf bis zum Tale Eskol und besahen das Land; und sie machten das Herz der Kinder Israel abwendig, daß sie nicht in das Land gingen, welches Jehova ihnen gegeben hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Und der Zorn Jehovas entbrannte an jenem Tage, und er schwur und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Wenn die Männer, die aus Ägypten hinaufgezogen sind, von zwanzig Jahren und darüber, das Land sehen werden, das ich Abraham und Isaak und Jakob zugeschworen habe! Denn sie sind mir nicht völlig nachgefolgt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'ausgenommen Kaleb, der Sohn Jephunnes, der Kenisiter, und Josua, der Sohn Nuns; denn sie sind Jehova völlig nachgefolgt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Und der Zorn Jehovas entbrannte wider Israel, und er ließ sie vierzig Jahre lang in der Wüste umherirren, bis das ganze Geschlecht aufgerieben war, welches getan hatte, was böse war in den Augen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Und siehe, ihr seid aufgestanden an eurer Väter Statt, eine Brut von sündigen Männern, um die Glut des Zornes Jehovas gegen Israel noch zu mehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Wenn ihr euch hinter ihm abwendet, so wird er es noch länger in der Wüste lassen, und ihr werdet dieses ganze Volk verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Und sie traten zu ihm und sprachen: Kleinviehhürden wollen wir hier bauen für unsere Herden, und Städte für unsere Kinder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'wir selbst aber wollen uns eilends rüsten vor den Kindern Israel her, bis wir sie an ihren Ort gebracht haben; und unsere Kinder sollen in den festen Städten bleiben vor den Bewohnern des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Wir wollen nicht zu unseren Häusern zurückkehren, bis die Kinder Israel ein jeder sein Erbteil empfangen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Denn wir wollen nicht mit ihnen erben jenseit des Jordan und weiterhin, denn unser Erbteil ist uns diesseit des Jordan gegen Sonnenaufgang zugekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Da sprach Mose zu ihnen: Wenn ihr dieses tut, wenn ihr euch vor Jehova zum Streite rüstet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'und alle unter euch, die gerüstet sind, vor Jehova über den Jordan ziehen, bis er seine Feinde vor sich ausgetrieben hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'und das Land vor Jehova unterjocht ist, und ihr danach zurückkehret, so sollt ihr schuldlos sein gegen Jehova und gegen Israel; und dieses Land soll euch zum Eigentum sein vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Wenn ihr aber nicht also tut, siehe, so habt ihr wider Jehova gesündigt; und wisset, daß eure Sünde euch finden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Bauet euch Städte für eure Kinder und Hürden für euer Kleinvieh, und tut, was aus eurem Munde hervorgegangen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Und die Kinder Gad und die Kinder Ruben sprachen zu Mose und sagten: Deine Knechte werden tun, so wie mein Herr gebietet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Unsere Kinder, unsere Weiber, unsere Herden und all unser Vieh sollen daselbst in den Städten Gileads sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'deine Knechte aber, alle zum Heere Gerüsteten, werden vor Jehova hinüberziehen in den Streit, so wie mein Herr redet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Und Mose gebot ihrethalben Eleasar, dem Priester, und Josua, dem Sohne Nuns, und den Häuptern der Väter der Stämme der Kinder Israel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'und Mose sprach zu ihnen: Wenn die Kinder Gad und die Kinder Ruben, alle zum Streit Gerüsteten, mit euch vor Jehova über den Jordan ziehen, und das Land vor euch unterjocht sein wird, so sollt ihr ihnen das Land Gilead zum Eigentum geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'wenn sie aber nicht gerüstet mit euch hinüberziehen, so sollen sie sich unter euch ansässig machen im Lande Kanaan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Und die Kinder Gad und die Kinder Ruben antworteten und sprachen: Wie Jehova zu deinen Knechten geredet hat, so wollen wir tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Wir wollen gerüstet vor Jehova in das Land Kanaan hinüberziehen, und unser Erbbesitztum verbleibe uns diesseit des Jordan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Und Mose gab ihnen, den Kindern Gad und den Kindern Ruben und der Hälfte des Stammes Manasse, des Sohnes Josephs, das Königreich Sihons, des Königs der Amoriter, und das Königreich Ogs, des Königs von Basan, das Land nach seinen Städten in ihren Grenzen, die Städte des Landes ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Und die Kinder Gad bauten Dibon und Ataroth und Aroer,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'und Ateroth-Schofan und Jaser und Jogbeha,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'und Beth-Nimra und Beth-Haran, feste Städte und Kleinviehhürden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Und die Kinder Ruben bauten Hesbon und Elale und Kirjathaim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'und Nebo und Baal-Meon, deren Namen geändert wurden, und Sibma; und sie benannten die Städte, die sie bauten, mit anderen Namen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Und die Söhne Makirs, des Sohnes Manasses, zogen nach Gilead und nahmen es ein; und sie trieben die Amoriter, die darin wohnten, aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Und Mose gab Gilead dem Makir, dem Sohne Manasses; und er wohnte darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Und Jair, der Sohn Manasses, zog hin und nahm ihre Dörfer ein und nannte sie Dörfer Jairs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Und Nobach zog hin und nahm Kenath und seine Tochterstädte ein und nannte es Nobach nach seinem Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Dies sind die Züge der Kinder Israel, welche aus dem Lande Ägypten ausgezogen sind nach ihren Heeren, unter der Hand Moses und Aarons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Und Mose schrieb ihre Auszüge auf, nach ihren Zügen, nach dem Befehle Jehovas; und dies sind ihre Züge, nach ihren Auszügen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Sie brachen auf von Raemses im ersten Monat, am fünfzehnten Tage des ersten Monats. Am anderen Tage nach dem Passah zogen die Kinder Israel aus mit erhobener Hand, vor den Augen aller Ägypter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'als die Ägypter diejenigen begruben, welche Jehova unter ihnen geschlagen hatte, alle Erstgeborenen; und Jehova hatte an ihren Göttern Gericht geübt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Und die Kinder Israel brachen auf von Raemses und lagerten sich in Sukkoth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Und sie brachen auf von Sukkoth und lagerten sich in Etham, das am Rande der Wüste liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Und sie brachen auf von Etham und wandten sich nach Pi-Hachiroth, das Baal-Zephon gegenüber liegt, und lagerten sich vor Migdol.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Und sie brachen auf von Hachiroth und zogen mitten durchs Meer nach der Wüste hin, und sie zogen drei Tagereisen in der Wüste Etham und lagerten sich in Mara.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Und sie brachen auf von Mara und kamen nach Elim; und in Elim waren zwölf Wasserquellen und siebzig Palmbäume; und sie lagerten sich daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Und sie brachen auf von Elim und lagerten sich am Schilfmeer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Und sie brachen auf vom Schilfmeer und lagerten sich in der Wüste Sin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Und sie brachen auf aus der Wüste Sin und lagerten sich in Dophka.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Und sie brachen auf von Dophka und lagerten sich in Alusch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Und sie brachen auf von Alusch und lagerten sich in Rephidim; und das Volk hatte daselbst kein Wasser zu trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Und sie brachen auf von Rephidim und lagerten sich in der Wüste Sinai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Und sie brachen auf aus der Wüste Sinai und lagerten sich in Kibroth-Hattaawa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Und sie brachen auf von Kibroth-Hattaawa und lagerten sich in Hazeroth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Und sie brachen auf von Hazeroth und lagerten sich in Rithma.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Und sie brachen auf von Rithma und lagerten sich in Rimmon-Perez.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Und sie brachen auf von Rimmon-Perez und lagerten sich in Libna.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Und sie brachen auf von Libna und lagerten sich in Rissa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Und sie brachen auf von Rissa und lagerten sich in Kehelatha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Und sie brachen auf von Kehelatha und lagerten sich am Berge Schepher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Und sie brachen auf vom Berge Schepher und lagerten sich in Harada.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Und sie brachen auf von Harada und lagerten sich in Makheloth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Und sie brachen auf von Makheloth und lagerten sich in Tachath.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Und sie brachen auf von Tachath und lagerten sich in Terach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Und sie brachen auf von Terach und lagerten sich in Mithka.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Und sie brachen auf von Mithka und lagerten sich in Haschmona.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Und sie brachen auf von Haschmona und lagerten sich in Moseroth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Und sie brachen auf von Moseroth und lagerten sich in Bne-Jaakan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Und sie brachen auf von Bne-Jaakan und lagerten sich in Hor-Gidgad.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Und sie brachen auf von Hor-Gidgad und lagerten sich in Jotbatha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Und sie brachen auf von Jotbatha und lagerten sich in Abrona.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Und sie brachen auf von Abrona und lagerten sich in Ezjon-Geber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Und sie brachen auf von Ezjon-Geber und lagerten sich in der Wüste Zin, das ist Kades.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Und sie brachen auf von Kades und lagerten sich am Berge Hor, am Rande des Landes Edom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Und Aaron, der Priester, stieg auf den Berg Hor nach dem Befehle Jehovas; und er starb daselbst im vierzigsten Jahre nach dem Auszuge der Kinder Israel aus dem Lande Ägypten, im fünften Monat, am Ersten des Monats.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Und Aaron war hundertdreiundzwanzig Jahre alt, als er auf dem Berge Hor starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Und der Kanaaniter, der König von Arad, der im Süden wohnte im Lande Kanaan, hörte von dem Kommen der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Und sie brachen auf vom Berge Hor und lagerten sich in Zalmona.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Und sie brachen auf von Zalmona und lagerten sich in Punon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Und sie brachen auf von Punon und lagerten sich in Oboth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Und sie brachen auf von Oboth und lagerten sich in Ijje-Abarim, an der Grenze von Moab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Und sie brachen auf von Ijjim und lagerten sich in Dibon-Gad.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Und sie brachen auf von Dibon-Gad und lagerten sich in Almon-Diblathaim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Und sie brachen auf von Almon-Diblathaim und lagerten sich am Gebirge Abarim vor Nebo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Und sie brachen auf vom Gebirge Abarim und lagerten sich in den Ebenen Moabs, am Jordan von Jericho.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Und sie lagerten sich am Jordan, von Beth-Jesimoth bis Abel-Sittim in den Ebenen Moabs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Und Jehova redete zu Mose in den Ebenen Moabs, am Jordan von Jericho, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Rede zu den Kindern Israel und sprich zu ihnen: Wenn ihr über den Jordan in das Land Kanaan ziehet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'so sollt ihr alle Bewohner des Landes vor euch austreiben und alle ihre Bildwerke zerstören; und alle ihre gegossenen Bilder sollt ihr zerstören, und alle ihre Höhen sollt ihr vertilgen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'und ihr sollt das Land in Besitz nehmen und darin wohnen, denn euch habe ich das Land gegeben, es zu besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Und ihr sollt das Land durchs Los als Erbteil empfangen, nach euren Geschlechtern: Den Vielen sollt ihr ihr Erbteil mehren, und den Wenigen sollt ihr ihr Erbteil mindern; wohin das Los einem fällt, das soll ihm gehören; nach den Stämmen eurer Väter sollt ihr erben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Wenn ihr aber die Bewohner des Landes nicht vor euch austreibet, so werden diejenigen, welche ihr von ihnen übriglasset, zu Dornen in euren Augen und zu Stacheln in euren Seiten werden, und sie werden euch bedrängen in dem Lande, in welchem ihr wohnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Und es wird geschehen: so wie ich gedachte, ihnen zu tun, werde ich euch tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Gebiete den Kindern Israel und sprich zu ihnen: Wenn ihr in das Land Kanaan kommet, so ist dies das Land, welches euch als Erbteil zufallen soll: das Land Kanaan nach seinen Grenzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Und die Südseite soll euch sein von der Wüste Zin an, Edom entlang, und die Südgrenze soll euch sein vom Ende des Salzmeeres gegen Osten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Und die Grenze soll sich euch südlich von der Anhöhe Akrabbim wenden und nach Zin hinübergehen, und ihr Ausgang sei südlich von Kades-Barnea; und sie laufe nach Hazar-Addar hin, und gehe hinüber nach Azmon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'und die Grenze wende sich von Azmon nach dem Bache Ägyptens, und ihr Ausgang sei nach dem Meere hin. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Und die Westgrenze: sie sei euch das große Meer und das Angrenzende; das soll euch die Westgrenze sein. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Und dies soll euch die Nordgrenze sein: vom großen Meere aus sollt ihr euch den Berg Hor abmarken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'vom Berge Hor sollt ihr abmarken bis man nach Hamath kommt, und der Ausgang der Grenze sei nach Zedad hin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'und die Grenze laufe nach Siphron hin, und ihr Ausgang sei bei Hazar-Enan. Das soll euch die Nordgrenze sein. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Und zur Ostgrenze sollt ihr euch abmarken von Hazar-Enan nach Schepham.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Und die Grenze gehe hinab von Schepham nach Ribla, östlich von Ajin; und die Grenze gehe hinab und stoße an die Seite des Sees Kinnereth gegen Osten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'und die Grenze gehe an den Jordan hinab, und ihr Ausgang sei am Salzmeere. Das soll euer Land sein nach seinen Grenzen ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Und Mose gebot den Kindern Israel und sprach: Das ist das Land, welches ihr durchs Los als Erbteil empfangen sollt, das Jehova den neun Stämmen und dem halben Stamme zu geben geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Denn der Stamm der Kinder der Rubeniter nach ihren Vaterhäusern, und der Stamm der Kinder der Gaditer nach ihren Vaterhäusern, und die Hälfte des Stammes Manasse, die haben ihr Erbteil empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Die zwei Stämme und der halbe Stamm haben ihr Erbteil empfangen diesseit des Jordan von Jericho, gegen Osten, gegen Sonnenaufgang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Dies sind die Namen der Männer, welche euch das Land als Erbe austeilen sollen: Eleasar, der Priester, und Josua, der Sohn Nuns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Und je einen Fürsten vom Stamme sollt ihr nehmen, um das Land als Erbe auszuteilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Und dies sind die Namen der Männer: für den Stamm Juda: Kaleb, der Sohn Jephunnes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'und für den Stamm der Kinder Simeon: Samuel, der Sohn Ammihuds;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'für den Stamm Benjamin: Elidad, der Sohn Kislons;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'und für den Stamm der Kinder Dan ein Fürst: Bukki, der Sohn Joglis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'für die Söhne Josephs: für den Stamm der Kinder Manasse ein Fürst: Hanniel, der Sohn Ephods,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'und für den Stamm der Kinder Ephraim ein Fürst: Kemuel, der Sohn Schiphtans;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'und für den Stamm der Kinder Sebulon ein Fürst: Elizaphan, der Sohn Parnaks;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'und für den Stamm der Kinder Issaschar ein Fürst: Paltiel, der Sohn Assans;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'und für den Stamm der Kinder Aser ein Fürst: Achihud, der Sohn Schelomis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'und für den Stamm der Kinder Naphtali ein Fürst: Pedahel, der Sohn Ammihuds.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Diese sind es, welchen Jehova gebot, den Kindern Israel ihr Erbe im Lande Kanaan auszuteilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Und Jehova redete zu Mose in den Ebenen Moabs, am Jordan von Jericho, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Gebiete den Kindern Israel, daß sie von ihrem Erbbesitztum den Leviten Städte zum Wohnen geben; und zu den Städten sollt ihr einen Bezirk rings um dieselben her den Leviten geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Und die Städte seien ihnen zum Wohnen, und deren Bezirke seien für ihr Vieh und für ihre Habe und für alle ihre Tiere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Und die Bezirke der Städte, welche ihr den Leviten geben sollt, sollen von der Stadtmauer nach außen hin tausend Ellen betragen ringsum;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'und ihr sollt außerhalb der Stadt auf der Ostseite zweitausend Ellen abmessen, und auf der Südseite zweitausend Ellen, und auf der Westseite zweitausend Ellen und auf der Nordseite zweitausend Ellen, daß die Stadt in der Mitte sei; das sollen die Bezirke ihrer Städte sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Und die Städte, die ihr den Leviten geben sollt: sechs Zufluchtstädte sind es, die ihr ihnen geben sollt, damit dahin fliehe, wer einen Totschlag begangen hat; und zu diesen hinzu sollt ihr zweiundvierzig Städte geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Alle die Städte, die ihr den Leviten geben sollt, sie und ihre Bezirke, sollen achtundvierzig Städte sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Und was die Städte betrifft, die ihr von dem Eigentum der Kinder Israel geben sollt, von dem Stamme, der viel hat, sollt ihr viel nehmen, und von dem, der wenig hat, sollt ihr wenig nehmen; jeder Stamm soll nach Verhältnis seines Erbteils, das er erben wird, von seinen Städten den Leviten geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Und Jehova redete zu Mose und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Rede zu den Kindern Israel und sprich zu ihnen: Wenn ihr über den Jordan in das Land Kanaan ziehet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'so sollt ihr euch Städte bestimmen: Zufluchtstädte sollen sie für euch sein, daß dahin fliehe ein Totschläger, der einen Menschen aus Versehen erschlagen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Und die Städte sollen euch zur Zuflucht sein vor dem Rächer, daß der Totschläger nicht sterbe, bis er vor der Gemeinde gestanden hat zum Gericht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Und die Städte, die ihr geben sollt, sollen sechs Zufluchtstädte für euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Drei Städte sollt ihr geben diesseit des Jordan, und drei Städte sollt ihr geben im Lande Kanaan; Zufluchtstädte sollen sie sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Den Kindern Israel und dem Fremdling und dem Beisassen in ihrer Mitte sollen diese sechs Städte zur Zuflucht sein, daß dahin fliehe ein jeder, der einen Menschen aus Versehen erschlagen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Wenn er ihn aber mit einem eisernen Werkzeug geschlagen hat, daß er gestorben ist, so ist er ein Mörder; der Mörder soll gewißlich getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Und wenn er ihn mit einem Stein, den er in der Hand führte, wodurch man sterben kann, geschlagen hat, daß er gestorben ist, so ist er ein Mörder; der Mörder soll gewißlich getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Oder wenn er ihn mit einem hölzernen Werkzeug, das er in der Hand führte, wodurch man sterben kann, geschlagen hat, daß er gestorben ist, so ist er ein Mörder; der Mörder soll gewißlich getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Der Bluträcher, der soll den Mörder töten; wenn er ihn antrifft, soll er ihn töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Und wenn er ihn aus Haß gestoßen oder mit Absicht auf ihn geworfen hat, daß er gestorben ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'oder ihn aus Feindschaft mit seiner Hand geschlagen hat, daß er gestorben ist, so soll der Schläger gewißlich getötet werden; er ist ein Mörder; der Bluträcher soll den Mörder töten, wenn er ihn antrifft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Wenn er aber von ungefähr, nicht aus Feindschaft, ihn gestoßen, oder unabsichtlich irgend ein Werkzeug auf ihn geworfen hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'oder, ohne es zu sehen, irgend einen Stein, wodurch man sterben kann, auf ihn hat fallen lassen, daß er gestorben ist, er war ihm aber nicht feind und suchte seinen Schaden nicht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'so soll die Gemeinde zwischen dem Schläger und dem Bluträcher nach diesen Rechten richten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'und die Gemeinde soll den Totschläger aus der Hand des Bluträchers erretten, und die Gemeinde soll ihn in seine Zufluchtstadt zurückbringen, wohin er geflohen ist; und er soll darin bleiben bis zum Tode des Hohenpriesters, den man mit dem heiligen Öle gesalbt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Wenn aber der Totschläger über die Grenze seiner Zufluchtstadt, wohin er geflohen ist, irgend hinausgeht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'und der Bluträcher findet ihn außerhalb der Grenze seiner Zufluchtstadt, und der Bluträcher tötet den Totschläger, so hat er keine Blutschuld.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Denn er soll in seiner Zufluchtstadt bleiben bis zum Tode des Hohenpriesters; und nach dem Tode des Hohenpriesters darf der Totschläger in das Land seines Eigentums zurückkehren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Und dies soll euch zu einer Rechtssatzung sein bei euren Geschlechtern in allen euren Wohnsitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Jeder, der einen Menschen erschlägt: auf die Aussage von Zeugen soll man den Mörder töten; aber ein einzelner Zeuge kann nicht wider einen Menschen aussagen, daß er sterbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Und ihr sollt keine Sühne annehmen für die Seele eines Mörders, der schuldig ist zu sterben, sondern er soll gewißlich getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Auch sollt ihr keine Sühne annehmen für den in seine Zufluchtstadt Geflüchteten, daß er vor dem Tode des Priesters zurückkehre, um im Lande zu wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Und ihr sollt das Land nicht entweihen, in welchem ihr seid; denn das Blut, das entweiht das Land; und für das Land kann keine Sühnung getan werden wegen des Blutes, das darin vergossen worden, außer durch das Blut dessen, der es vergossen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Und du sollst nicht das Land verunreinigen, in welchem ihr wohnet, in dessen Mitte ich wohne; denn ich, Jehova, wohne inmitten der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Und es traten herzu die Häupter der Väter vom Geschlecht der Söhne Gileads, des Sohnes Makirs, des Sohnes Manasses, aus den Geschlechtern der Söhne Josephs; und sie redeten vor Mose und vor den Fürsten, den Häuptern der Väter der Kinder Israel, und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Jehova hat meinem Herrn geboten, den Kindern Israel das Land durchs Los als Erbteil zu geben; und meinem Herrn ist von Jehova geboten worden, das Erbteil Zelophchads, unseres Bruders, seinen Töchtern zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Werden sie nun einem von den Söhnen der anderen Stämme der Kinder Israel zu Weibern, so wird ihr Erbteil dem Erbteil unserer Väter entzogen und zu dem Erbteil des Stammes hinzugefügt werden, welchem sie angehören werden; und dem Lose unseres Erbteils wird es entzogen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Und auch wenn das Jubeljahr der Kinder Israel kommt, wird ihr Erbteil zu dem Erbteil des Stammes hinzugefügt werden, welchem sie angehören werden; und ihr Erbteil wird dem Erbteil des Stammes unserer Väter entzogen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Da gebot Mose den Kindern Israel, nach dem Befehle Jehovas, und sprach: Der Stamm der Kinder Joseph redet recht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Dies ist das Wort, welches Jehova betreffs der Töchter Zelophchads geboten hat, indem er sprach: Sie mögen dem, der in ihren Augen gut ist, zu Weibern werden; nur sollen sie einem aus dem Geschlecht des Stammes ihres Vaters zu Weibern werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'damit nicht ein Erbteil der Kinder Israel von Stamm zu Stamm übergehe; denn die Kinder Israel sollen ein jeder dem Erbteil des Stammes seiner Väter anhangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Und jede Tochter, die ein Erbteil aus den Stämmen der Kinder Israel besitzt, soll einem aus dem Geschlecht des Stammes ihres Vaters zum Weibe werden, damit die Kinder Israel ein jeder das Erbteil seiner Väter besitzen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'und nicht ein Erbteil von einem Stamme auf einen anderen Stamm übergehe. Denn die Stämme der Kinder Israel sollen ein jeder seinem Erbteil anhangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'So wie Jehova dem Mose geboten hatte, also taten die Töchter Zelophchads.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Und Machla, Tirza und Chogla und Milka und Noa, die Töchter Zelophchads, wurden den Söhnen ihrer Oheime zu Weibern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Männern aus den Geschlechtern der Kinder Manasse, des Sohnes Josephs, wurden sie zu Weibern. Und so verblieb ihr Erbteil bei dem Stamme des Geschlechts ihres Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Das sind die Gebote und die Rechte, welche Jehova in den Ebenen Moabs, am Jordan von Jericho, den Kindern Israel durch Mose geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Dies sind die Worte, welche Mose zu ganz Israel geredet hat diesseit des Jordan, in der Wüste, in der Ebene, Suph gegenüber, zwischen Paran und Tophel und Laban und Hazeroth und Di-Sahab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Elf Tagereisen sind vom Horeb, auf dem Wege des Gebirges Seir, bis Kades-Barnea.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Und es geschah im vierzigsten Jahre, im elften Monat, am Ersten des Monats, da redete Mose zu den Kindern Israel nach allem, was Jehova ihm an sie geboten hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'nachdem er Sihon geschlagen, den König der Amoriter, der zu Hesbon wohnte, und Og, den König von Basan, der zu Astaroth und zu Edrei wohnte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Diesseit des Jordan, im Lande Moab, fing Mose an, dieses Gesetz auszulegen, indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Jehova, unser Gott, redete zu uns am Horeb und sprach: Lange genug seid ihr an diesem Berge geblieben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'wendet euch und brechet auf und ziehet nach dem Gebirge der Amoriter und zu allen ihren Anwohnern in der Ebene, auf dem Gebirge und in der Niederung und im Süden und am Ufer des Meeres, in das Land der Kanaaniter und zum Libanon, bis zu dem großen Strome, dem Strome Phrat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Siehe, ich habe das Land vor euch gestellt; gehet hinein und nehmet das Land in Besitz, welches Jehova euren Vätern, Abraham, Isaak und Jakob, geschworen hat, ihnen zu geben und ihrem Samen nach ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Und ich sprach zu euch in selbiger Zeit und sagte: Ich allein kann euch nicht tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Jehova, euer Gott, hat euch gemehrt, und siehe, ihr seid heute wie die Sterne des Himmels an Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Jehova, der Gott eurer Väter, füge zu euch, so viele ihr seid, tausendmal hinzu und segne euch, wie er zu euch geredet hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Wie könnte ich allein eure Bürde und eure Last und euren Hader tragen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Nehmet euch weise und verständige und bekannte Männer, nach euren Stämmen, daß ich sie zu Häuptern über euch setze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Und ihr antwortetet mir und sprachet: Gut ist die Sache, die du zu tun gesagt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Und ich nahm die Häupter eurer Stämme, weise und bekannte Männer, und setzte sie als Häupter über euch, als Oberste über tausend und Oberste über hundert und Oberste über fünfzig und Oberste über zehn, und als Vorsteher eurer Stämme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Und ich gebot euren Richtern in selbiger Zeit und sprach: Höret die Streitsachen zwischen euren Brüdern und richtet in Gerechtigkeit zwischen einem Manne und seinem Bruder und dem Fremdling bei ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Ihr sollt nicht die Person ansehen im Gericht; den Kleinen wie den Großen sollt ihr hören; ihr sollt euch vor niemand fürchten, denn das Gericht ist Gottes. Die Sache aber, die zu schwierig für euch ist, sollt ihr vor mich bringen, daß ich sie höre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Und ich gebot euch in selbiger Zeit alle die Sachen, die ihr tun solltet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Und wir brachen auf vom Horeb und zogen durch diese ganze große und schreckliche Wüste, die ihr gesehen habt, des Weges nach dem Gebirge der Amoriter, so wie Jehova, unser Gott, uns geboten hatte; und wir kamen bis Kades-Barnea.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Und ich sprach zu euch: Ihr seid gekommen bis zu dem Gebirge der Amoriter, das Jehova, unser Gott, uns gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Siehe, Jehova, dein Gott, hat das Land vor dich gestellt; ziehe hinauf, nimm in Besitz, so wie Jehova, der Gott deiner Väter, zu dir geredet hat; fürchte dich nicht und verzage nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Und ihr tratet alle zu mir und sprachet: Laßt uns Männer vor uns hersenden, daß sie uns das Land erforschen und uns Bescheid bringen über den Weg, auf dem wir hinaufziehen, und über die Städte, zu denen wir kommen sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Und die Sache war gut in meinen Augen; und ich nahm aus euch zwölf Männer, je einen Mann für den Stamm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Und sie wandten sich und zogen ins Gebirge hinauf, und sie kamen bis zum Tale Eskol und kundschafteten es aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Und sie nahmen von der Frucht des Landes in ihre Hand und brachten sie zu uns herab. Und sie brachten uns Bescheid und sprachen: Das Land ist gut, das Jehova, unser Gott, uns gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Aber ihr wolltet nicht hinaufziehen und waret widerspenstig gegen den Befehl Jehovas, eures Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Und ihr murrtet in euren Zelten und sprachet: Weil Jehova uns haßte, hat er uns aus dem Lande Ägypten herausgeführt, um uns in die Hand der Amoriter zu geben, daß sie uns vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Wohin sollen wir hinaufziehen? Unsere Brüder haben unser Herz verzagt gemacht, indem sie sagten: Ein Volk, größer und höher als wir, Städte, groß und befestigt bis an den Himmel, und auch die Kinder der Enakim haben wir dort gesehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Da sprach ich zu euch: Erschrecket nicht und fürchtet euch nicht vor ihnen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Jehova, euer Gott, der vor euch herzieht, er wird für euch streiten, nach allem, was er in Ägypten vor euren Augen für euch getan hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'und in der Wüste, wo du gesehen hast, daß Jehova, dein Gott, dich getragen hat, wie ein Mann seinen Sohn trägt, auf dem ganzen Wege, den ihr gezogen seid, bis ihr an diesen Ort kamet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Aber in dieser Sache glaubtet ihr nicht Jehova, eurem Gott,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'der auf dem Wege vor euch herzog, um euch einen Ort zu erkunden, daß ihr euch lagern konntet: des Nachts im Feuer, daß ihr auf dem Wege sehen konntet, auf welchem ihr zoget, und des Tages in der Wolke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Und Jehova hörte die Stimme eurer Reden und ward zornig und schwur und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Wenn ein Mann unter diesen Männern, diesem bösen Geschlecht, das gute Land sehen wird, das ich geschworen habe, euren Vätern zu geben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'außer Kaleb, dem Sohne Jephunnes! Er soll es sehen, und ihm und seinen Söhnen werde ich das Land geben, auf welches er getreten, darum daß er Jehova völlig nachgefolgt ist. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Auch wider mich erzürnte Jehova eurethalben und sprach: Auch du sollst nicht hineinkommen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Josua, der Sohn Nuns, der vor dir steht, er soll hineinkommen; ihn stärke, denn er soll es Israel als Erbe austeilen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Und eure Kindlein, von denen ihr sagtet: Sie werden zur Beute werden! und eure Söhne, die heute weder Gutes noch Böses kennen, sie sollen hineinkommen, und ihnen werde ich es geben, und sie sollen es in Besitz nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Ihr aber, wendet euch und brechet auf nach der Wüste, des Weges zum Schilfmeere!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Da antwortetet ihr und sprachet zu mir: Wir haben wider Jehova gesündigt; wir wollen hinaufziehen und streiten, nach allem, was Jehova, unser Gott, uns geboten hat. Und ihr gürtetet ein jeder sein Kriegsgerät um und zoget leichtfertig in das Gebirge hinauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Und Jehova sprach zu mir: Sprich zu ihnen: Ziehet nicht hinauf und streitet nicht, denn ich bin nicht in eurer Mitte; daß ihr nicht vor euren Feinden geschlagen werdet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Und ich redete zu euch, aber ihr hörtet nicht; und ihr waret widerspenstig gegen den Befehl Jehovas, und handeltet vermessen und zoget in das Gebirge hinauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Und die Amoriter, die auf selbigem Gebirge wohnten, zogen aus, euch entgegen, und verfolgten euch, wie die Bienen tun, und zersprengten euch in Seir bis Horma.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Und ihr kehrtet zurück und weintet vor Jehova; aber Jehova hörte nicht auf eure Stimme und neigte sein Ohr nicht zu euch. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Und ihr bliebet in Kades viele Tage, nach den Tagen, die ihr bliebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Und wir wandten uns und brachen auf nach der Wüste, des Weges zum Schilfmeere, wie Jehova zu mir geredet hatte; und wir umzogen das Gebirge Seir viele Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Und Jehova redete zu mir und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Lange genug habt ihr dieses Gebirge umzogen; wendet euch gegen Norden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Und gebiete dem Volke und sprich: Ihr werdet nun durch das Gebiet eurer Brüder, der Kinder Esau, ziehen, die in Seir wohnen, und sie werden sich vor euch fürchten; so habet wohl acht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Laßt euch nicht in Streit mit ihnen ein, denn ich werde euch von ihrem Lande auch nicht den Tritt einer Fußsohle geben; denn das Gebirge Seir habe ich dem Esau als Besitztum gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Speise sollt ihr um Geld von ihnen kaufen, daß ihr esset, und auch Wasser sollt ihr um Geld von ihnen kaufen, daß ihr trinket.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Denn Jehova, dein Gott, hat dich gesegnet in allem Werke deiner Hand. Er kannte dein Ziehen durch diese große Wüste: Diese vierzig Jahre ist Jehova, dein Gott, mit dir gewesen; es hat dir an nichts gemangelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Und wir zogen weiter, an unseren Brüdern, den Kindern Esau, vorüber, die in Seir wohnen, von dem Wege der Ebene, von Elath und von Ezjon-Geber her; und wir wandten uns und zogen des Weges nach der Wüste von Moab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Und Jehova sprach zu mir: Befeinde Moab nicht und laß dich nicht in Streit mit ihnen ein, denn ich werde dir von seinem Lande kein Besitztum geben; denn Ar habe ich den Kindern Lot als Besitztum gegeben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Die Emim wohnten vordem darin, ein großes und zahlreiches und hohes Volk, wie die Enakim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Auch sie werden für Riesen gehalten, wie die Enakim; und die Moabiter nennen sie Emim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Und in Seir wohnten vordem die Horiter; aber die Kinder Esau trieben sie aus und vertilgten sie vor sich und wohnten an ihrer Statt, so wie Israel dem Lande seines Besitztums getan, das Jehova ihnen gegeben hat. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Nun machet euch auf und ziehet über den Bach Sered. Und wir zogen über den Bach Sered.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Die Tage aber, die wir von Kades-Barnea gegangen sind, bis wir über den Bach Sered zogen, waren achtunddreißig Jahre, bis das ganze Geschlecht der Kriegsleute aus dem Lager aufgerieben war, so wie Jehova ihnen geschworen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Und auch war die Hand Jehovas wider sie, um sie aus dem Lager zu vertilgen, bis sie aufgerieben waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Und es geschah, als die Kriegsleute insgesamt aus der Mitte des Volkes weggestorben waren,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'da redete Jehova zu mir und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Du wirst heute die Grenze von Moab, von Ar, überschreiten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'und dich nähern gegenüber den Kindern Ammon; du sollst sie nicht befeinden und dich nicht in Streit mit ihnen einlassen, denn ich werde dir von dem Lande der Kinder Ammon kein Besitztum geben; denn ich habe es den Kindern Lot als Besitztum gegeben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Für ein Land der Riesen wird auch dieses gehalten; Riesen wohnten vordem darin, und die Ammoniter nennen sie Samsummim:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Ein großes und zahlreiches und hohes Volk, wie die Enakim; und Jehova vertilgte sie vor ihnen, und sie trieben sie aus und wohnten an ihrer Statt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'so wie er für die Kinder Esau getan hat, die in Seir wohnen, vor welchen er die Horiter vertilgte; und sie trieben sie aus und wohnten an ihrer Statt bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Und die Awim, welche in Dörfern wohnten bis Gasa, die Kaphtorim, die aus Kaphtor kamen, vertilgten dieselben und wohnten an ihrer Statt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Machet euch auf, brechet auf und ziehet über den Fluß Arnon. Siehe, ich habe Sihon, den König von Hesbon, den Amoriter, und sein Land in deine Hand gegeben; beginne, nimm in Besitz und bekriege ihn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'An diesem Tage will ich beginnen, deinen Schrecken und deine Furcht auf die Völker unter dem ganzen Himmel zu legen, welche das Gerücht von dir hören und vor dir zittern und beben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Und ich sandte Boten aus der Wüste Kedemoth an Sihon, den König von Hesbon, mit Worten des Friedens, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Laß mich durch dein Land ziehen! Nur auf der Straße will ich gehen, ich will weder zur Rechten noch zur Linken weichen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Speise sollst du mir um Geld verkaufen, daß ich esse, und Wasser sollst du mir um Geld geben, daß ich trinke. Nur mit meinen Füßen will ich durchziehen-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'wie mir die Kinder Esau getan haben, die in Seir wohnen, und die Moabiter, die in Ar wohnen, bis ich über den Jordan in das Land ziehe, das Jehova, unser Gott, uns gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Aber Sihon, der König von Hesbon, wollte uns nicht bei sich durchziehen lassen; denn Jehova, dein Gott, hatte seinen Geist verhärtet und sein Herz verstockt, auf daß er ihn in deine Hand gäbe, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Und Jehova sprach zu mir: Siehe, ich habe begonnen, Sihon und sein Land vor dir dahinzugeben; beginne, nimm in Besitz, damit du sein Land besitzest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Und Sihon zog aus, uns entgegen, er und all sein Volk, zum Streite nach Jahaz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Aber Jehova, unser Gott, gab ihn vor uns dahin; und wir schlugen ihn und seine Söhne und all sein Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Und in selbiger Zeit nahmen wir alle seine Städte ein, und wir verbannten ihre ganze Bevölkerung: Männer und Weiber und Kinder; wir ließen keinen Entronnenen übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Nur das Vieh erbeuteten wir für uns und den Raub der Städte, die wir einnahmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Von Aroer, das am Ufer des Flusses Arnon ist, und zwar von der Stadt, die im Flußtale liegt, bis Gilead war keine Stadt, die uns zu stark gewesen wäre: Alles gab Jehova, unser Gott, vor uns dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Nur dem Lande der Kinder Ammon, der ganzen Seite des Flusses Jabbok, bist du nicht genaht, noch den Städten des Gebirges, noch allem, was Jehova, unser Gott, verboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Und wir wandten uns und zogen des Weges nach Basan hinauf; und Og, der König von Basan, zog aus, uns entgegen, er und all sein Volk, zum Streite nach Edrei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Und Jehova sprach zu mir: Fürchte ihn nicht! Denn in deine Hand habe ich ihn und all sein Volk und sein Land gegeben; und tue ihm, wie du Sihon, dem Könige der Amoriter, getan hast, der zu Hesbon wohnte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Und Jehova, unser Gott, gab auch Og, den König von Basan, und all sein Volk in unsere Hand; und wir schlugen ihn, bis ihm kein Entronnener übrigblieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Und in selbiger Zeit nahmen wir alle seine Städte ein; es war keine Stadt, die wir ihnen nicht nahmen: sechzig Städte, den ganzen Landstrich Argob, das Königreich Ogs in Basan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'alle diese Städte waren befestigt mit hohen Mauern, Toren und Riegeln; außer den sehr vielen offenen Städten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Und wir verbannten sie, wie wir Sihon, dem Könige von Hesbon, getan hatten; wir verbannten ihre ganze Bevölkerung: Männer, Weiber und Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Aber alles Vieh und den Raub der Städte erbeuteten wir für uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Und wir nahmen in selbiger Zeit aus der Hand der zwei Könige der Amoriter das Land, welches diesseit des Jordan ist, vom Flusse Arnon bis an den Berg Hermon');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(die Zidonier nennen den Hermon Sirjon, und die Amoriter nennen ihn Senir):');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'alle Städte der Ebene und das ganze Gilead, und das ganze Basan bis Salka und Edrei, die Städte des Königreichs Ogs in Basan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Denn nur Og, der König von Basan, war von dem Überrest der Riesen übriggeblieben. Siehe, sein Bett, ein Bett von Eisen, ist es nicht in Rabba der Kinder Ammon? Seine Länge mißt neun Ellen und seine Breite vier Ellen, nach dem Ellenbogen eines Mannes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Und dieses Land nahmen wir in selbiger Zeit in Besitz. Von Aroer an, das am Flusse Arnon ist, und die Hälfte des Gebirges Gilead und seine Städte gab ich den Rubenitern und den Gaditern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'und das Übrige von Gilead und das ganze Basan, das Königreich Ogs, gab ich dem halben Stamme Manasse. (Der ganze Landstrich Argob, das ganze Basan, dieses wird das Land der Riesen genannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, der Sohn Manasses, nahm den ganzen Landstrich Argob bis an die Grenze der Gesuriter und der Maakathiter und nannte sie, das Basan, nach seinem Namen: Dörfer Jairs, bis auf diesen Tag.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Und dem Makir gab ich Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Und den Rubenitern und den Gaditern gab ich von Gilead bis zum Flusse Arnon, bis zur Mitte des Flusses und das Angrenzende, und bis zum Flusse Jabbok, der Grenze der Kinder Ammon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'und die Ebene und den Jordan und das Angrenzende, von Kinnereth bis zum Meere der Ebene, dem Salzmeere, unter den Abhängen des Pisga gegen Sonnenaufgang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Und ich gebot euch in selbiger Zeit und sprach: Jehova, euer Gott, hat euch dieses Land gegeben, es zu besitzen. Gerüstet sollt ihr, alle streitbaren Männer, vor euren Brüdern, den Kindern Israel, hinüberziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Nur eure Weiber und eure Kinder und euer Vieh, ich weiß, daß ihr viel Vieh habt, sollen in euren Städten bleiben, die ich euch gegeben habe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'bis Jehova euren Brüdern Ruhe schafft wie euch, und auch sie das Land besitzen, welches Jehova, euer Gott, ihnen jenseit des Jordan gibt; dann sollt ihr zurückkehren, ein jeder zu seinem Besitztum, das ich euch gegeben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Und dem Josua gebot ich in selbiger Zeit und sprach: Deine Augen haben alles gesehen, was Jehova, euer Gott, diesen zwei Königen getan hat; also wird Jehova allen Königreichen tun, wohin du hinüberziehen wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Fürchtet sie nicht! Denn Jehova, euer Gott, er ist es, der für euch streitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Und ich flehte zu Jehova in selbiger Zeit und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Herr, Jehova! Du hast begonnen, deinem Knechte deine Größe und deine starke Hand zu zeigen; denn welcher Gott ist im Himmel und auf Erden, der tun könnte gleich deinen Werken und gleich deinen Machttaten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Laß mich doch hinüberziehen und das gute Land sehen, welches jenseit des Jordan ist, dieses gute Gebirge und den Libanon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Aber Jehova war über mich erzürnt um euretwillen und hörte nicht auf mich; und Jehova sprach zu mir: Laß es genug sein; rede mir fortan nicht mehr von dieser Sache!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Steige auf den Gipfel des Pisga, und hebe deine Augen auf gegen Westen und gegen Norden und gegen Süden und gegen Osten, und sieh mit deinen Augen; denn du wirst nicht über diesen Jordan gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Und gebiete dem Josua und stärke ihn und befestige ihn; denn er soll vor diesem Volke her hinüberziehen, und er soll ihnen das Land, das du sehen wirst, als Erbe austeilen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Und wir blieben im Tale, Beth-Peor gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Und nun, Israel, höre auf die Satzungen und auf die Rechte, die ich euch lehre zu tun, auf daß ihr lebet und hineinkommet und das Land in Besitz nehmet, welches Jehova, der Gott eurer Väter, euch gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Ihr sollt nichts hinzutun zu dem Worte, das ich euch gebiete, und sollt nichts davon tun, damit ihr beobachtet die Gebote Jehovas, eures Gottes, die ich euch gebiete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Eure Augen haben gesehen, was Jehova wegen des Baal Peor getan hat; denn alle Männer, welche dem Baal Peor nachgegangen sind, hat Jehova, dein Gott, aus deiner Mitte vertilgt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'ihr aber, die ihr Jehova, eurem Gott, anhinget, seid heute alle am Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Siehe, ich habe euch Satzungen und Rechte gelehrt, so wie Jehova, mein Gott, mir geboten hat, damit ihr also tuet inmitten des Landes, wohin ihr kommet, um es in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Und so beobachtet und tut sie! Denn das wird eure Weisheit und euer Verstand sein vor den Augen der Völker, welche alle diese Satzungen hören und sagen werden: Diese große Nation ist ein wahrhaft weises und verständiges Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Denn welche große Nation gibt es, die Götter hätte, welche ihr so nahe wären, wie Jehova, unser Gott, in allem, worin wir zu ihm rufen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Und welche große Nation gibt es, die so gerechte Satzungen und Rechte hätte, wie dieses ganze Gesetz, das ich euch heute vorlege?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Nur hüte dich und hüte deine Seele sehr, daß du die Dinge nicht vergessest, die deine Augen gesehen haben, und daß sie nicht aus deinem Herzen weichen alle Tage deines Lebens! Und tue sie kund deinen Kindern und deinen Kindeskindern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'An dem Tage, da du vor Jehova, deinem Gott, am Horeb standest, als Jehova zu mir sprach: Versammle mir das Volk, daß ich sie meine Worte hören lasse, welche sie lernen sollen, um mich zu fürchten alle die Tage, die sie auf dem Erdboden leben, und welche sie ihre Kinder lehren sollen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'da nahtet ihr hinzu und standet unten an dem Berge; und der Berg brannte im Feuer bis ins Herz des Himmels: Finsternis, Gewölk und Dunkel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Und Jehova redete zu euch mitten aus dem Feuer; die Stimme der Worte hörtet ihr, aber ihr sahet keine Gestalt außer der Stimme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Und er verkündigte euch seinen Bund, den er euch zu tun gebot, die zehn Worte; und er schrieb sie auf zwei steinerne Tafeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Und mir gebot Jehova in selbiger Zeit, euch Satzungen und Rechte zu lehren, damit ihr sie tätet in dem Lande, wohin ihr hinüberziehet, um es in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'So hütet eure Seelen sehr, denn ihr habt keinerlei Gestalt gesehen an dem Tage, da Jehova am Horeb, mitten aus dem Feuer, zu euch redete-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'daß ihr euch nicht verderbet und euch ein geschnitztes Bild machet, das Gleichnis irgend eines Bildes, das Abbild eines männlichen oder eines weiblichen Wesens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'das Abbild irgend eines Tieres, das auf Erden ist, das Abbild irgend eines geflügelten Vogels, der am Himmel fliegt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'das Abbild von irgend etwas, das sich auf dem Erdboden regt, das Abbild irgend eines Fisches, der im Wasser unter der Erde ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'und daß du deine Augen nicht zum Himmel erhebest und die Sonne und den Mond und die Sterne, das ganze Heer des Himmels, sehest und verleitet werdest und dich vor ihnen bückest und ihnen dienest, welche Jehova, dein Gott, allen Völkern unter dem ganzen Himmel zugeteilt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Euch aber hat Jehova genommen und euch herausgeführt aus dem eisernen Schmelzofen, aus Ägypten, damit ihr das Volk seines Erbteils wäret, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Und Jehova war eurethalben über mich erzürnt, und er schwur, daß ich nicht über den Jordan gehen und nicht in das gute Land kommen sollte, welches Jehova, dein Gott, dir als Erbteil gibt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'denn ich werde in diesem Lande sterben, ich werde nicht über den Jordan gehen; ihr aber werdet hinüberziehen und werdet dieses gute Land besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Hütet euch, daß ihr nicht des Bundes Jehovas, eures Gottes, vergesset, den er mit euch gemacht hat, und euch ein geschnitztes Bild machet, ein Gleichnis von irgend etwas, das Jehova, dein Gott, dir verboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Denn Jehova, dein Gott, ist ein verzehrendes Feuer, ein eifernder Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Wenn du Kinder und Kindeskinder zeugen wirst, und ihr eingelebt seid im Lande, und ihr euch verderbet und euch ein geschnitztes Bild machet, ein Gleichnis von irgend etwas, und tut, was böse ist in den Augen Jehovas, deines Gottes, ihn zu reizen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'so nehme ich heute den Himmel und die Erde zu Zeugen gegen euch, daß ihr gewißlich schnell aus dem Lande umkommen werdet, wohin ihr über den Jordan ziehet um es in Besitz zu nehmen; ihr werdet eure Tage darin nicht verlängern, sondern gänzlich vertilgt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Und Jehova wird euch unter die Völker zerstreuen, und ihr werdet übrigbleiben, ein zählbares Häuflein unter den Nationen, wohin Jehova euch führen wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'und ihr werdet daselbst Göttern dienen, dem Werke von Menschenhänden, Holz und Stein, die nicht sehen und nicht hören und nicht essen und nicht riechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Aber ihr werdet von dort Jehova, deinen Gott, suchen; und du wirst ihn finden, wenn du mit deinem ganzen Herzen und mit deiner ganzen Seele nach ihm fragen wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'In deiner Bedrängnis, und wenn alle diese Dinge dich treffen werden am Ende der Tage, wirst du umkehren zu Jehova, deinem Gott, und seiner Stimme gehorchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Denn ein barmherziger Gott ist Jehova, dein Gott; er wird dich nicht lassen und dich nicht verderben und wird des Bundes deiner Väter nicht vergessen, den er ihnen geschworen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Denn frage doch nach den vorigen Tagen, die vor dir gewesen sind, von dem Tage an, da Gott den Menschen auf der Erde geschaffen hat, und von einem Ende des Himmels bis zum anderen Ende des Himmels, ob je eine solch große Sache geschehen, oder ob desgleichen gehört worden sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Hat je ein Volk die Stimme Gottes mitten aus dem Feuer reden gehört, wie du sie gehört hast, und ist am Leben geblieben? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Oder hat Gott je versucht zu kommen, um sich eine Nation aus der Mitte einer Nation zu nehmen durch Versuchungen, durch Zeichen und durch Wunder, und durch Krieg und mit starker Hand und mit ausgestrecktem Arme, und durch große Schrecknisse, nach allem, was Jehova, euer Gott, in Ägypten, vor deinen Augen, für euch getan hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Dir ist es gezeigt worden, damit du wissest, daß Jehova Gott ist, keiner sonst außer ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Vom Himmel her hat er dich seine Stimme hören lassen, um dich zu unterweisen; und auf der Erde hat er dich sein großes Feuer sehen lassen, und mitten aus dem Feuer hast du seine Worte gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Und darum, daß er deine Väter geliebt und ihren Samen nach ihnen erwählt hat, hat er dich mit seinem Angesicht, mit seiner großen Kraft aus Ägypten herausgeführt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'um Nationen vor dir auszutreiben, größer und stärker als du, um dich hinzubringen, damit er dir ihr Land als Erbteil gäbe, wie es an diesem Tage geschieht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'So erkenne denn heute und nimm zu Herzen, daß Jehova Gott ist im Himmel oben und auf der Erde unten, keiner sonst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Und beobachte seine Satzungen und seine Gebote, die ich dir heute gebiete, damit es dir und deinen Kindern nach dir wohlgehe, und damit du deine Tage verlängerst in dem Lande, welches Jehova, dein Gott, dir für immer gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Damals sonderte Mose drei Städte ab diesseit des Jordan, gegen Sonnenaufgang,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'damit ein Totschläger dahin fliehe, der seinen Nächsten unabsichtlich erschlagen hat, und er haßte ihn vordem nicht, daß er in eine von diesen Städten fliehe und am Leben bleibe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Bezer in der Wüste, im Lande der Ebene, für die Rubeniter, und Ramoth in Gilead für die Gaditer, und Golan in Basan für die Manassiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Und dies ist das Gesetz, welches Mose den Kindern Israel vorlegte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'dies sind die Zeugnisse und die Satzungen und die Rechte, welche Mose zu den Kindern Israel redete, als sie aus Ägypten zogen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'diesseit des Jordan, im Tale, Beth-Peor gegenüber, im Lande Sihons, des Königs der Amoriter, der zu Hesbon wohnte, den Mose und die Kinder Israel geschlagen haben, als sie aus Ägypten zogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Und sie nahmen sein Land in Besitz, und das Land Ogs, des Königs von Basan, das Land der zwei Könige der Amoriter, welche diesseit des Jordan waren, gegen Sonnenaufgang;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'von Aroer, das am Ufer des Flusses Arnon ist, bis an den Berg Sion, das ist der Hermon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'und die ganze Ebene diesseit des Jordan, gegen Sonnenaufgang, und bis an das Meer der Ebene unter den Abhängen des Pisga.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Und Mose berief das ganze Israel und sprach zu ihnen: Höre, Israel, die Satzungen und die Rechte, die ich heute vor euren Ohren rede; und lernet sie, und achtet darauf, sie zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Jehova, unser Gott, hat am Horeb einen Bund mit uns gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Nicht mit unseren Vätern hat Jehova diesen Bund gemacht, sondern mit uns, die wir heute hier alle am Leben sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Von Angesicht zu Angesicht hat Jehova auf dem Berge, mitten aus dem Feuer, mit euch geredet-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'ich stand zwischen Jehova und euch in selbiger Zeit, um euch das Wort Jehovas zu verkünden; denn ihr fürchtetet euch vor dem Feuer und stieget nicht auf den Berg indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Ich bin Jehova, dein Gott, der ich dich herausgeführt habe aus dem Lande Ägypten, aus dem Hause der Knechtschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Du sollst keine anderen Götter haben neben mir. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Du sollst dir kein geschnitztes Bild machen, irgend ein Gleichnis dessen, was oben im Himmel, und was unten auf der Erde, und was in den Wassern unter der Erde ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Du sollst dich nicht vor ihnen niederbeugen und ihnen nicht dienen; denn ich, Jehova, dein Gott, bin ein eifernder Gott, der die Ungerechtigkeit der Väter heimsucht an den Kindern, ja, am dritten und am vierten Gliede derer, die mich hassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'und der Güte erweist, auf Tausende hin, an denen, die mich lieben und meine Gebote beobachten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Du sollst den Namen Jehovas, deines Gottes, nicht zu Eitlem aussprechen; denn Jehova wird den nicht für schuldlos halten, der seinen Namen zu Eitlem ausspricht. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Beobachte den Sabbathtag, ihn zu heiligen, so wie Jehova, dein Gott, dir geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Sechs Tage sollst du arbeiten und all dein Werk tun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'aber der siebte Tag ist Sabbath dem Jehova, deinem Gott: Du sollst keinerlei Werk tun, du und dein Sohn und deine Tochter und dein Knecht und deine Magd, und dein Rind und dein Esel und all dein Vieh, und dein Fremdling, der in deinen Toren ist; auf daß dein Knecht und deine Magd ruhen gleichwie du.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Und gedenke, daß du ein Knecht gewesen bist im Lande Ägypten, und daß Jehova, dein Gott, dich mit starker Hand und mit ausgestrecktem Arme von dannen herausgeführt hat; darum hat Jehova, dein Gott, dir geboten, den Sabbathtag zu feiern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Ehre deinen Vater und deine Mutter, so wie Jehova, dein Gott, dir geboten hat, auf daß deine Tage verlängert werden, und auf daß es dir wohlgehe in dem Lande, welches Jehova, dein Gott, dir gibt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Du sollst nicht töten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Und du sollst nicht ehebrechen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Und du sollst nicht stehlen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Und du sollst kein falsches Zeugnis ablegen wider deinen Nächsten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Und du sollst nicht begehren deines Nächsten Weib; und du sollst dich nicht gelüsten lassen deines Nächsten Hauses, noch seines Feldes, noch seines Knechtes, noch seiner Magd, noch seines Rindes, noch seines Esels, noch alles dessen, was dein Nächster hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Diese Worte hat Jehova auf dem Berge zu eurer ganzen Versammlung geredet, mitten aus dem Feuer, dem Gewölk und dem Dunkel, mit starker Stimme, und er fügte nichts hinzu. Und er schrieb sie auf zwei steinerne Tafeln und gab sie mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Und es geschah, als ihr die Stimme mitten aus der Finsternis hörtet, während der Berg im Feuer brannte, da nahtet ihr zu mir, alle Häupter eurer Stämme und eure Ältesten, und sprachet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Siehe, Jehova, unser Gott, hat uns seine Herrlichkeit und seine Größe sehen lassen, und wir haben seine Stimme mitten aus dem Feuer gehört; an diesem Tage haben wir gesehen, daß Jehova mit dem Menschen redet und er am Leben bleibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Und nun, warum sollten wir sterben? Denn dieses große Feuer wird uns verzehren. Wenn wir die Stimme Jehovas, unseres Gottes, noch weiter hören, so werden wir sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Denn wer ist von allem Fleische, der die Stimme des lebendigen Gottes mitten aus dem Feuer hätte reden hören, wie wir, und wäre am Leben geblieben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Nahe du hinzu und höre alles, was Jehova, unser Gott, sagen wird; und du, du sollst alles zu uns reden, was Jehova, unser Gott, zu dir reden wird, und wir wollen hören und es tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Und Jehova hörte die Stimme eurer Worte, als ihr zu mir redetet; und Jehova sprach zu mir: Ich habe die Stimme der Worte dieses Volkes gehört, welche sie zu dir geredet haben; es ist alles gut, was sie geredet haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Möchte doch dieses ihr Herz ihnen bleiben, mich allezeit zu fürchten und alle meine Gebote zu beobachten, auf daß es ihnen und ihren Kindern wohlgehe ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Gehe hin, sprich zu ihnen: Kehret in eure Zelte zurück!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Du aber bleibe hier bei mir, und ich will zu dir reden alle die Gebote und die Satzungen und die Rechte, welche du sie lehren sollst, damit sie sie tun in dem Lande, das ich ihnen gebe, es zu besitzen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'So achtet denn darauf, zu tun, wie Jehova, euer Gott, euch geboten hat; weichet nicht ab zur Rechten noch zur Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Auf dem ganzen Wege, den Jehova, euer Gott, euch geboten hat, sollt ihr wandeln, auf daß ihr lebet und es euch wohlgehe, und ihr eure Tage verlängert in dem Lande, das ihr besitzen werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Und dies sind die Gebote, die Satzungen und die Rechte, welche Jehova, euer Gott, geboten hat, euch zu lehren, damit ihr sie tuet in dem Lande, wohin ihr hinüberziehet, um es in Besitz zu nehmen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'auf daß du Jehova, deinen Gott, fürchtest alle Tage deines Lebens, um zu beobachten alle seine Satzungen und seine Gebote, die ich dir gebiete, du und dein Sohn und deines Sohnes Sohn, und auf daß deine Tage sich verlängern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'So höre denn, Israel, und achte darauf, sie zu tun, damit es dir wohlgehe, und ihr euch sehr mehret, so wie Jehova, der Gott deiner Väter, zu dir geredet hat, in einem Lande, das von Milch und Honig fließt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Höre Israel: Jehova, unser Gott, ist ein einziger Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Und du sollst Jehova, deinen Gott, lieben mit deinem ganzen Herzen und mit deiner ganzen Seele und mit deiner ganzen Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Und diese Worte, die ich dir heute gebiete, sollen auf deinem Herzen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Und du sollst sie deinen Kindern einschärfen und davon reden, wenn du in deinem Hause sitzest, und wenn du auf dem Wege gehst, und wenn du dich niederlegst, und wenn du aufstehst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Und du sollst sie zum Zeichen auf deine Hand binden, und sie sollen zu Stirnbändern sein zwischen deinen Augen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'und du sollst sie auf die Pfosten deines Hauses und an deine Tore schreiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Und es soll geschehen, wenn Jehova, dein Gott, dich in das Land bringt, das er deinen Vätern, Abraham, Isaak und Jakob, geschworen hat, dir zu geben: große und gute Städte, die du nicht gebaut hast,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'und Häuser, voll von allem Gut, die du nicht gefüllt, und gehauene Zisternen, die du nicht gehauen, Weinberge und Olivengärten, die du nicht gepflanzt hast, und du essen und satt werden wirst:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'so hüte dich, daß du Jehovas nicht vergessest, der dich herausgeführt hat aus dem Lande Ägypten, aus dem Hause der Knechtschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Jehova, deinen Gott, sollst du fürchten und ihm dienen, und bei seinem Namen sollst du schwören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Ihr sollt nicht anderen Göttern nachgehen, von den Göttern der Völker, die rings um euch her sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'denn ein eifernder Gott ist Jehova, dein Gott, in deiner Mitte: Damit nicht der Zorn Jehovas, deines Gottes, wider dich entbrenne, und er dich vertilge vom Erdboden hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Ihr sollt Jehova, euren Gott, nicht versuchen, wie ihr ihn zu Massa versucht habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Ihr sollt fleißig beobachten die Gebote Jehovas, eures Gottes, und seine Zeugnisse und seine Satzungen, die er dir geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Und du sollst tun, was recht und gut ist in den Augen Jehovas, auf daß es dir wohlgehe und du hineinkommest und das gute Land in Besitz nehmest, welches Jehova deinen Vätern zugeschworen hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'indem er alle deine Feinde vor dir ausstößt, so wie Jehova geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Wenn dein Sohn dich künftig fragt und spricht: Was bedeuten die Zeugnisse und die Satzungen und die Rechte, welche Jehova, unser Gott, euch geboten hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'so sollst du deinem Sohne sagen: Wir waren Knechte des Pharao in Ägypten, und Jehova hat uns mit starker Hand aus Ägypten herausgeführt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'und Jehova tat vor unseren Augen große und verderbenbringende Zeichen und Wunder an Ägypten, an dem Pharao und an seinem ganzen Hause;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'und uns führte er von dannen heraus, um uns herzubringen, uns das Land zu geben, welches er unseren Vätern zugeschworen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Und Jehova hat uns geboten, alle diese Satzungen zu tun, Jehova, unseren Gott, zu fürchten, uns zum Guten alle Tage, daß er uns am Leben erhalte, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Und es wird unsere Gerechtigkeit sein, wenn wir darauf achten, dieses ganze Gebot vor Jehova, unserem Gott, zu tun, so wie er uns geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Wenn Jehova, dein Gott, dich in das Land bringt, wohin du kommst, um es in Besitz zu nehmen, und viele Nationen vor dir hinaustreibt: die Hethiter und die Girgasiter und die Amoriter und die Kanaaniter und die Perisiter und die Hewiter und die Jebusiter, sieben Nationen, größer und stärker als du,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'und Jehova, dein Gott, sie vor dir dahingibt, und du sie schlägst, so sollst du sie ganz und gar verbannen; du sollst keinen Bund mit ihnen machen, noch Gnade gegen sie üben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Und du sollst dich nicht mit ihnen verschwägern: Deine Tochter sollst du nicht seinem Sohne geben, und seine Tochter sollst du nicht für deinen Sohn nehmen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'denn sie würden deine Söhne von mir abwendig machen, daß sie anderen Göttern dienten; und der Zorn Jehovas würde wider euch entbrennen, und er würde dich schnell vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Sondern also sollt ihr ihnen tun: Ihre Altäre sollt ihr niederreißen und ihre Bildsäulen zerbrechen und ihre Ascherim umhauen und ihre geschnitzten Bilder mit Feuer verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Denn ein heiliges Volk bist du Jehova, deinem Gott: Dich hat Jehova, dein Gott, erwählt, ihm zum Eigentumsvolke zu sein aus allen Völkern, die auf dem Erdboden sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Nicht weil euer mehr wären als aller Völker, hat Jehova sich euch zugeneigt und euch erwählt; denn ihr seid das geringste unter allen Völkern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'sondern wegen Jehovas Liebe zu euch, und weil er den Eid hielt, den er euren Vätern geschworen, hat Jehova euch mit starker Hand herausgeführt und dich erlöst aus dem Hause der Knechtschaft, aus der Hand des Pharao, des Königs von Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'So wisse denn, daß Jehova, dein Gott, Gott ist, der treue Gott, der den Bund und die Güte auf tausend Geschlechter hin denen bewahrt, die ihn lieben und seine Gebote beobachten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'und denen, die ihn hassen, ins Angesicht vergilt, sie zu vertilgen: Nicht zögert er mit seinem Hasser, ins Angesicht vergilt er ihm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'So sollst du das Gebot und die Satzungen und die Rechte beobachten, die ich dir heute zu tun gebiete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Und es wird geschehen: Dafür daß ihr diesen Rechten gehorchet und sie beobachtet und sie tut, wird Jehova, dein Gott, dir den Bund und die Güte bewahren, die er deinen Vätern geschworen hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'und er wird dich lieben und dich segnen und dich mehren: Er wird segnen die Frucht deines Leibes und die Frucht deines Landes, dein Getreide und deinen Most und dein Öl, das Geworfene deiner Rinder und die Zucht deines Kleinviehes, in dem Lande, das er deinen Vätern geschworen hat, dir zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Gesegnet wirst du sein vor allen Völkern; kein Unfruchtbarer und keine Unfruchtbare wird unter dir sein, noch unter deinem Vieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Und Jehova wird jede Krankheit von dir abwenden; und keine der bösen Seuchen Ägyptens, die du kennst, wird er auf dich legen, sondern er wird sie auf alle deine Hasser bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Und du wirst alle Völker verzehren, die Jehova, dein Gott, dir geben wird. Dein Auge soll ihrer nicht schonen, und du sollst ihren Göttern nicht dienen; denn das würde dir ein Fallstrick sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Wenn du in deinem Herzen sprichst: Diese Nationen sind größer als ich; wie vermöchte ich sie auszutreiben? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'fürchte dich nicht vor ihnen; gedenke doch dessen, was Jehova, dein Gott, dem Pharao und allen Ägyptern getan hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'der großen Versuchungen, die deine Augen gesehen, und der Zeichen und der Wunder, und der starken Hand und des ausgestreckten Armes, womit Jehova, dein Gott, dich herausgeführt hat. Also wird Jehova, dein Gott, all den Völkern tun, vor denen du dich fürchtest;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'und auch die Hornissen wird Jehova, dein Gott, gegen sie entsenden, bis die Übriggebliebenen und die sich vor dir Verbergenden umgekommen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Erschrick nicht vor ihnen! Denn Jehova, dein Gott, ist in deiner Mitte, ein großer und furchtbarer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Und Jehova, dein Gott, wird diese Nationen nach und nach vor dir austreiben; du wirst sie nicht eilends vernichten können, damit nicht das Wild des Feldes sich wider dich mehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Und Jehova, dein Gott, wird sie vor dir dahingeben und sie in große Verwirrung versetzen, bis sie vertilgt sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Und er wird ihre Könige in deine Hand geben, und du wirst ihre Namen vernichten unter dem Himmel hinweg; kein Mensch wird vor dir bestehen, bis du sie vertilgt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Die geschnitzten Bilder ihrer Götter sollt ihr mit Feuer verbrennen; du sollst nicht das Silber und das Gold an ihnen begehren und es dir nehmen, daß du nicht dadurch verstrickt werdest; denn es ist ein Greuel für Jehova, deinen Gott;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'und du sollst keinen Greuel in dein Haus bringen, so daß du ein Bann werdest gleich ihm; du sollst es ganz und gar verabscheuen und es gänzlich für einen Greuel halten, denn es ist ein Bann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Das ganze Gebot, das ich dir heute gebiete, sollt ihr beobachten, es zu tun; auf daß ihr lebet und euch mehret und hineinkommet und das Land in Besitz nehmet, welches Jehova euren Vätern zugeschworen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Und du sollst gedenken des ganzen Weges, den Jehova, dein Gott, dich hat wandern lassen diese vierzig Jahre in der Wüste, um dich zu demütigen, um dich zu versuchen, um zu erkennen, was in deinem Herzen ist, ob du seine Gebote beobachten würdest oder nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Und er demütigte dich und ließ dich hungern; und er speiste dich mit dem Man, das du nicht kanntest und das deine Väter nicht kannten, um dir kundzutun, daß der Mensch nicht von Brot allein lebt, sondern daß der Mensch von allem lebt, was aus dem Munde Jehovas hervorgeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Dein Kleid ist nicht an dir zerfallen, und dein Fuß ist nicht geschwollen diese vierzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'So erkenne in deinem Herzen, daß, wie ein Mann seinen Sohn züchtigt, Jehova, dein Gott, dich züchtigt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Und beobachte die Gebote Jehovas, deines Gottes, um auf seinen Wegen zu wandeln und ihn zu fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Denn Jehova, dein Gott, bringt dich in ein gutes Land, ein Land von Wasserbächen, Quellen und Gewässern, die in der Niederung und im Gebirge entspringen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'ein Land von Weizen und Gerste und Weinstöcken und Feigenbäumen und Granatbäumen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'ein Land von ölreichen Olivenbäumen und Honig; ein Land in welchem du nicht in Dürftigkeit Brot essen wirst, in welchem es dir an nichts mangeln wird; ein Land, dessen Steine Eisen sind, und aus dessen Bergen du Erz hauen wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Und hast du gegessen und bist satt geworden, so sollst du Jehova, deinen Gott, für das gute Land preisen, das er dir gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Hüte dich, daß du Jehovas, deines Gottes, nicht vergessest, so daß du nicht beobachtest seine Gebote und seine Rechte und seine Satzungen, die ich dir heute gebiete!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Damit nicht, wenn du issest und satt wirst, und schöne Häuser baust und bewohnst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'und dein Rind-und dein Kleinvieh sich mehrt, und Silber und Gold sich dir mehren, und alles, was du hast, sich mehrt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'dein Herz sich erhebe, und du Jehovas, deines Gottes, vergessest, der dich aus dem Lande Ägypten, aus dem Hause der Knechtschaft, herausführte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'der dich wandern ließ in der großen und schrecklichen Wüste, wo feurige Schlangen und Skorpione sind, und Dürre, wo kein Wasser ist; der dir Wasser aus dem Kieselfelsen hervorbrachte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'der dich in der Wüste mit Man speiste, welches deine Väter nicht kannten, um dich zu demütigen und um dich zu versuchen, damit er dir wohltue an deinem Ende,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'und du in deinem Herzen sprechest: Meine Kraft und die Stärke meiner Hand hat mir dieses Vermögen geschafft!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Sondern du sollst Jehovas, deines Gottes, gedenken, daß er es ist, der dir Kraft gibt, Vermögen zu schaffen; auf daß er seinen Bund aufrecht halte, den er deinen Vätern geschworen hat, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Und es wird geschehen, wenn du irgend Jehovas, deines Gottes, vergissest und anderen Göttern nachgehst und ihnen dienst und dich vor ihnen niederbeugst, ich zeuge heute gegen euch, daß ihr gewißlich umkommen werdet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'wie die Nationen, welche Jehova vor euch vernichtet hat, also werdet ihr umkommen, dafür daß ihr auf die Stimme Jehovas, eures Gottes, nicht höret.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Höre, Israel! Du gehst heute über den Jordan, um hineinzukommen, Nationen in Besitz zu nehmen, größer und stärker als du, Städte, groß und befestigt bis an den Himmel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'ein großes und hohes Volk, die Söhne der Enakim, die du ja kennst, und von denen du ja gehört hast: Wer kann vor den Kindern Enaks bestehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'So wisse heute, daß Jehova, dein Gott, es ist, der vor dir her hinübergeht, ein verzehrendes Feuer; er wird sie vertilgen, und er wird sie vor dir beugen; und du wirst sie austreiben und sie schnell vernichten, so wie Jehova zu dir geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Sprich nicht in deinem Herzen, wenn Jehova, dein Gott, sie vor dir ausstößt: Um meiner Gerechtigkeit willen hat Jehova mich hierher gebracht, um dieses Land in Besitz zu nehmen denn um der Gesetzlosigkeit dieser Nationen willen treibt Jehova sie vor dir aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Nicht um deiner Gerechtigkeit und der Geradheit deines Herzens willen kommst du hinein, um ihr Land in Besitz zu nehmen; sondern um der Gesetzlosigkeit dieser Nationen willen treibt Jehova, dein Gott, sie vor dir aus, und damit er das Wort aufrecht halte, welches Jehova deinen Vätern, Abraham, Isaak und Jakob, geschworen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'So wisse denn, daß nicht um deiner Gerechtigkeit willen Jehova, dein Gott, dir dieses gute Land gibt, es zu besitzen; denn ein hartnäckiges Volk bist du.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Gedenke, vergiß nicht, wie du Jehova, deinen Gott, in der Wüste erzürnt hast! Von dem Tage an, da du aus dem Lande Ägypten herausgezogen bist, bis ihr an diesen Ort kamet, seid ihr widerspenstig gegen Jehova gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Und am Horeb erzürntet ihr Jehova; und Jehova ergrimmte über euch, so daß er euch vertilgen wollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Als ich auf den Berg stieg, um die steinernen Tafeln zu empfangen, die Tafeln des Bundes, den Jehova mit euch gemacht hatte, da blieb ich auf dem Berge vierzig Tage und vierzig Nächte Brot aß ich nicht, und Wasser trank ich nicht-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'und Jehova gab mir die zwei steinernen Tafeln, beschrieben mit dem Finger Gottes; und auf ihnen standen alle die Worte, welche Jehova auf dem Berge mit euch geredet hatte, mitten aus dem Feuer, am Tage der Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Und es geschah am Ende von vierzig Tagen und vierzig Nächten, da gab mir Jehova die zwei steinernen Tafeln, die Tafeln des Bundes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Und Jehova sprach zu mir: Mache dich auf, steige eilends von hier hinab! Denn dein Volk, das du aus Ägypten herausgeführt hast, hat sich verderbt. Sie sind schnell von dem Wege abgewichen, den ich ihnen geboten habe; sie haben sich ein gegossenes Bild gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Und Jehova sprach zu mir und sagte: Ich habe dieses Volk gesehen, und siehe, es ist ein hartnäckiges Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Laß ab von mir, daß ich sie vertilge und ihren Namen unter dem Himmel auslösche; und ich will dich zu einer Nation machen, stärker und größer als sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Und ich wandte mich und stieg von dem Berge herab (und der Berg brannte mit Feuer), und die zwei Tafeln des Bundes waren auf meinen beiden Händen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Und ich sah, und siehe, ihr hattet gegen Jehova, euren Gott, gesündigt; ihr hattet euch ein gegossenes Kalb gemacht; ihr waret schnell von dem Wege abgewichen, den Jehova euch geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Und ich faßte die beiden Tafeln und warf sie aus meinen beiden Händen und zerbrach sie vor euren Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Und ich warf mich vor Jehova nieder, wie zuerst, vierzig Tage und vierzig Nächte Brot aß ich nicht, und Wasser trank ich nicht, um all eurer Sünden willen, die ihr begangen hattet, indem ihr tatet, was übel war in den Augen Jehovas, ihn zu reizen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Denn mir war bange vor dem Zorn und dem Grimm, womit Jehova über euch ergrimmt war, so daß er euch vertilgen wollte. Und Jehova erhörte mich auch dieses Mal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Auch über Aaron zürnte Jehova sehr, so daß er ihn vertilgen wollte; und ich bat auch für Aaron in selbiger Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Und ich nahm eure Sünde, das Kalb, das ihr gemacht hattet, und verbrannte es mit Feuer, und ich zerstieß es, indem ich es wohl zermalmte, bis es zu feinem Staube ward; und ich warf seinen Staub in den Bach, der von dem Berge herabfließt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Und zu Tabhera und zu Massa und zu Kibroth-Hattaawa erzürntet ihr Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Und als Jehova euch aus Kades-Barnea sandte und sprach: Ziehet hinauf und nehmet das Land in Besitz, das ich euch gegeben habe, da waret ihr widerspenstig gegen den Befehl Jehovas, eures Gottes, und ihr glaubtet ihm nicht und gehorchtet seiner Stimme nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Widerspenstige seid ihr gegen Jehova gewesen von dem Tage an, da ich euch gekannt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Und ich warf mich vor Jehova nieder, die vierzig Tage und die vierzig Nächte, die ich mich niederwarf; denn Jehova hatte gesagt, daß er euch vertilgen wolle;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'und ich betete zu Jehova und sprach: Herr, Jehova! Verdirb nicht dein Volk und dein Erbteil, das du durch deine Größe erlöst, das du mit starker Hand aus Ägypten herausgeführt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Gedenke deiner Knechte, Abrahams, Isaaks und Jakobs; kehre dich nicht an die Härtigkeit dieses Volkes und an seine Gesetzlosigkeit und an seine Sünde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'damit das Land, aus welchem du uns herausgeführt hast, nicht sage: Weil Jehova nicht imstande war, sie in das Land zu bringen, wovon er zu ihnen geredet hatte, und weil er sie haßte, hat er sie herausgeführt, um sie in der Wüste sterben zu lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Sie sind ja dein Volk und dein Erbteil, das du herausgeführt hast mit deiner großen Kraft und mit deinem ausgestreckten Arme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'In selbiger Zeit sprach Jehova zu mir: Haue dir zwei steinerne Tafeln aus, wie die ersten, und steige zu mir herauf auf den Berg; und mache dir eine Lade von Holz;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'und ich werde auf die Tafeln die Worte schreiben, welche auf den ersten Tafeln waren, die du zerbrochen hast; und du sollst sie in die Lade legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Und ich machte eine Lade von Akazienholz und hieb zwei steinerne Tafeln aus, wie die ersten; und ich stieg auf den Berg, und die zwei Tafeln waren in meiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Und er schrieb auf die Tafeln wie die erste Schrift, die zehn Worte, welche Jehova auf dem Berge zu euch geredet hatte, mitten aus dem Feuer am Tage der Versammlung; und Jehova gab sie mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Und ich wandte mich und stieg von dem Berge herab. Und ich legte die Tafeln in die Lade, die ich gemacht hatte; und sie sind daselbst, wie Jehova mir geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Und die Kinder Israel brachen auf von Beeroth-Bne-Jaakan nach Mosera. Daselbst starb Aaron, und er wurde daselbst begraben; und Eleasar, sein Sohn, übte den Priesterdienst aus an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Von dannen brachen sie auf nach Gudgoda, und von Gudgoda nach Jotbatha, einem Lande von Wasserbächen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'In selbiger Zeit sonderte Jehova den Stamm Levi aus, um die Lade des Bundes Jehovas zu tragen, vor Jehova zu stehen, um ihm zu dienen und in seinem Namen zu segnen, bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Darum ward dem Levi kein Teil noch Erbe mit seinen Brüdern; Jehova ist sein Erbteil, so wie Jehova, dein Gott, zu ihm geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Ich aber blieb auf dem Berge, wie die vorigen Tage, vierzig Tage und vierzig Nächte, und Jehova erhörte mich auch dieses Mal; Jehova wollte dich nicht verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Und Jehova sprach zu mir: Mache dich auf, gehe hin, um vor dem Volke herzuziehen, damit sie hineinkommen und das Land in Besitz nehmen, das ich ihren Vätern geschworen habe, ihnen zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Und nun, Israel, was fordert Jehova, dein Gott, von dir, als nur, Jehova, deinen Gott, zu fürchten, auf allen seinen Wegen zu wandeln und ihn zu lieben, und Jehova, deinem Gott, zu dienen mit deinem ganzen Herzen und mit deiner ganzen Seele,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'indem du die Gebote Jehovas und seine Satzungen, die ich dir heute gebiete, beobachtest, dir zum Guten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Siehe, Jehovas, deines Gottes, sind die Himmel und die Himmel der Himmel, die Erde und alles, was in ihr ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Jedoch deinen Vätern hat Jehova sich zugeneigt, sie zu lieben; und er hat euch, ihren Samen nach ihnen, aus allen Völkern erwählt, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'So beschneidet denn die Vorhaut eures Herzens und verhärtet euren Nacken nicht mehr!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Denn Jehova, euer Gott, er ist der Gott der Götter und der Herr der Herren, der große, mächtige und furchtbare Gott, der keine Person ansieht und kein Geschenk annimmt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'der Recht schafft der Waise und der Witwe, und den Fremdling liebt, so daß er ihm Brot und Kleider gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Und ihr sollt den Fremdling lieben; denn ihr seid Fremdlinge gewesen im Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Jehova, deinen Gott, sollst du fürchten, ihm sollst du dienen und ihm anhangen, und bei seinem Namen sollst du schwören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Er ist dein Ruhm, und er dein Gott, der jene großen und furchtbaren Dinge an dir getan hat, die deine Augen gesehen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Zu siebzig Seelen zogen deine Väter nach Ägypten hinab; und nun hat Jehova, dein Gott, dich gemacht wie die Sterne des Himmels an Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'So sollst du denn Jehova, deinen Gott, lieben und seine Vorschriften beobachten und seine Satzungen und seine Rechte und seine Gebote alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Und erkennet heute, denn nicht mit euren Kindern rede ich, die es nicht wissen und die es nicht gesehen haben, die Zucht Jehovas, eures Gottes, seine Größe, seine starke Hand und seinen ausgestreckten Arm,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'und seine Zeichen und seine Taten, die er in Ägypten getan hat, an dem Pharao, dem Könige von Ägypten, und an seinem ganzen Lande;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'und was er getan hat an der Heeresmacht Ägyptens, an seinen Rossen und seinen Wagen, über welche er die Wasser des Schilfmeeres hinströmen ließ, als sie euch nachjagten; und Jehova hat sie vernichtet bis auf diesen Tag;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'und was er euch in der Wüste getan hat, bis ihr an diesen Ort kamet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'und was er an Dathan und Abiram getan hat, den Söhnen Eliabs, des Sohnes Rubens: Wie die Erde ihren Mund auftat und sie inmitten von ganz Israel verschlang samt ihren Familien und ihren Zelten und allem Bestehenden, das in ihrem Gefolge war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Denn eure Augen haben all das große Werk Jehovas gesehen, das er getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Und so beobachtet das ganze Gebot, das ich dir heute gebiete, damit ihr stark seiet und hineinkommet und das Land besitzet, wohin ihr hinüberziehet, um es in Besitz zu nehmen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'und damit ihr eure Tage verlängert in dem Lande, das Jehova euren Vätern geschworen hat, ihnen und ihrem Samen zu geben, ein Land, das von Milch und Honig fließt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Denn das Land, wohin du kommst, um es in Besitz zu nehmen, ist nicht wie das Land Ägypten, von wo ihr ausgezogen seid, wo du deine Saat sätest und mit deinem Fuße wässertest, wie einen Krautgarten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'sondern das Land, wohin ihr hinüberziehet, um es in Besitz zu nehmen, ist ein Land mit Bergen und Tälern; vom Regen des Himmels trinkt es Wasser;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'ein Land, auf welches Jehova, dein Gott, acht hat: Beständig sind die Augen Jehovas, deines Gottes, darauf gerichtet, vom Anfang des Jahres bis zum Ende des Jahres.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Und es wird geschehen wenn ihr fleißig auf meine Gebote höret, die ich euch heute gebiete, Jehova, euren Gott, zu lieben und ihm zu dienen mit eurem ganzen Herzen und mit eurer ganzen Seele,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'so werde ich den Regen eures Landes geben zu seiner Zeit, den Frühregen und den Spätregen, damit du dein Getreide und deinen Most und dein Öl einsammelst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'und ich werde deinem Vieh Kraut geben auf deinem Felde, und du wirst essen und satt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Hütet euch, daß euer Herz nicht verführt werde, und ihr abweichet und anderen Göttern dienet und euch vor ihnen niederbeuget,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'und der Zorn Jehovas wider euch entbrenne, und er den Himmel verschließe, daß kein Regen sei und der Erdboden seinen Ertrag nicht gebe und ihr bald aus dem guten Lande vertilgt werdet, das Jehova euch gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Und ihr sollt diese meine Worte auf euer Herz und auf eure Seele legen, und sie zum Zeichen auf eure Hand binden, und sie sollen zu Stirnbändern zwischen euren Augen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Und lehret sie eure Kinder, indem ihr davon redet, wenn du in deinem Hause sitzest, und wenn du auf dem Wege gehst, und wenn du dich niederlegst, und wenn du aufstehst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'und schreibe sie auf die Pfosten deines Hauses und an deine Tore,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'auf daß eure Tage und die Tage eurer Kinder sich mehren in dem Lande, welches Jehova euren Vätern geschworen hat, ihnen zu geben, wie die Tage des Himmels über der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Denn wenn ihr dieses ganze Gebot, das ich euch zu tun gebiete, fleißig beobachtet, Jehova, euren Gott, zu lieben, auf allen seinen Wegen zu wandeln und ihm anzuhangen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'so wird Jehova alle diese Nationen vor euch austreiben; und ihr werdet Nationen in Besitz nehmen, größer und stärker als ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Jeder Ort, auf welchen eure Fußsohle treten wird, wird euer sein: Von der Wüste und dem Libanon und vom Strome, dem Strome Phrat, bis an das hintere Meer wird eure Grenze sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Niemand wird vor euch bestehen; euren Schrecken und eure Furcht wird Jehova, euer Gott, auf das ganze Land legen, auf welches ihr treten werdet, so wie er zu euch geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Siehe, ich lege euch heute Segen und Fluch vor:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Den Segen, wenn ihr den Geboten Jehovas, eures Gottes, gehorchet, die ich euch heute gebiete;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'und den Fluch, wenn ihr den Geboten Jehovas, eures Gottes, nicht gehorchet und von dem Wege abweichet, den ich euch heute gebiete, um anderen Göttern nachzugehen, die ihr nicht kennet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Und es soll geschehen, wenn Jehova, dein Gott, dich in das Land bringt, wohin du kommst, um es in Besitz zu nehmen, so sollst du den Segen erteilen auf dem Berge Gerisim und den Fluch auf dem Berge Ebal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Sind sie nicht jenseit des Jordan, hinter dem Wege gegen Sonnenuntergang im Lande der Kanaaniter, die in der Ebene wohnen, Gilgal gegenüber, bei den Terebinthen Mores?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Denn ihr gehet über den Jordan, um hineinzukommen, das Land in Besitz zu nehmen, das Jehova, euer Gott, euch gibt; und ihr werdet es in Besitz nehmen und darin wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Und so achtet darauf, alle die Satzungen und die Rechte zu tun, die ich euch heute vorlege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Dies sind die Satzungen und die Rechte, welche ihr beobachten sollt, sie zu tun in dem Lande, das Jehova, der Gott deiner Väter, dir gegeben hat, es zu besitzen alle die Tage, die ihr auf dem Erdboden lebet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Ihr sollt alle die Orte gänzlich zerstören, wo die Nationen, die ihr austreiben werdet, ihren Göttern gedient haben: auf den hohen Bergen und auf den Hügeln und unter jedem grünen Baume;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'und ihr sollt ihre Altäre niederreißen und ihre Bildsäulen zerbrechen und ihre Ascherim mit Feuer verbrennen und die geschnitzten Bilder ihrer Götter umhauen; und ihr sollt ihre Namen aus selbigem Orte vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Jehova, eurem Gott, sollt ihr nicht also tun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'sondern den Ort sollt ihr aufsuchen, welchen Jehova, euer Gott, aus allen euren Stämmen erwählen wird, um seinen Namen dahin zu setzen, daß er dort wohne, und dahin sollst du kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Und ihr sollt dahin bringen eure Brandopfer und eure Schlachtopfer, und eure Zehnten, und das Hebopfer eurer Hand, und eure Gelübde und eure freiwilligen Gaben, und die Erstgeborenen eures Rind-und eures Kleinviehes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'und daselbst sollt ihr vor Jehova, eurem Gott, essen und euch erfreuen, ihr und eure Häuser, an allem Geschäft eurer Hand, worin Jehova, dein Gott, dich gesegnet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Ihr sollt nicht tun nach allem, was wir heute hier tun, ein jeder, was irgend recht ist in seinen Augen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'denn ihr seid bis jetzt noch nicht zu der Ruhe und zu dem Erbteil gekommen, das Jehova, dein Gott, dir gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Seid ihr aber über den Jordan gezogen und wohnet ihr in dem Lande, das Jehova, euer Gott, euch erben läßt, und er schafft euch Ruhe vor allen euren Feinden ringsum, und ihr wohnet sicher,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'so soll es geschehen: Der Ort, welchen Jehova, euer Gott, erwählen wird, seinen Namen daselbst wohnen zu lassen, dahin sollt ihr alles bringen, was ich euch gebiete: eure Brandopfer und eure Schlachtopfer, eure Zehnten und das Hebopfer eurer Hand, und alle Auswahl eurer Gelübde, die ihr Jehova geloben werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Und ihr sollt euch freuen vor Jehova, eurem Gott, ihr und eure Söhne und eure Töchter und eure Knechte und eure Mägde, und der Levit, der in euren Toren ist, denn er hat kein Teil noch Erbe mit euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Hüte dich, daß du nicht deine Brandopfer an jedem Orte opferst, den du siehst!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Sondern an dem Orte, welchen Jehova in einem deiner Stämme erwählen wird, daselbst sollst du deine Brandopfer opfern und daselbst alles tun, was ich dir gebiete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Doch magst du nach allem Begehr deiner Seele schlachten und Fleisch essen in allen deinen Toren, nach dem Segen Jehovas, deines Gottes, den er dir gegeben hat: Der Unreine und der Reine mögen es essen, wie die Gazelle und wie den Hirsch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Nur das Blut sollt ihr nicht essen, ihr sollt es auf die Erde gießen wie Wasser. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Du darfst in deinen Toren nicht essen den Zehnten deines Getreides und deines Mostes und deines Öles, noch die Erstgeborenen deines Rind-und deines Kleinviehes, noch alle deine Gelübde, die du tust, noch deine freiwilligen Gaben, noch das Hebopfer deiner Hand;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'sondern vor Jehova, deinem Gott, an dem Orte, welchen Jehova, dein Gott, erwählen wird, sollst du es essen, du und dein Sohn und deine Tochter, und dein Knecht und deine Magd, und der Levit, der in deinen Toren ist; und du sollst dich vor Jehova, deinem Gott, erfreuen an allem Geschäft deiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Hüte dich, daß du den Leviten nicht verlässest, alle deine Tage in deinem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Wenn Jehova, dein Gott, dein Gebiet erweitern wird, so wie er zu dir geredet hat, und du sprichst: Ich will Fleisch essen, weil deine Seele Fleisch zu essen begehrt, so magst du Fleisch essen nach allem Begehr deiner Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Wenn der Ort, den Jehova, dein Gott, erwählen wird, um seinen Namen dahin zu setzen, fern von dir ist, so magst du schlachten von deinem Rind-und von deinem Kleinvieh, das Jehova dir gegeben hat, so wie ich dir geboten habe, und in deinen Toren essen nach allem Begehr deiner Seele;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'gerade so wie die Gazelle und der Hirsch gegessen werden, also magst du es essen: Der Unreine und der Reine mögen es gleicherweise essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Nur halte daran fest, kein Blut zu essen, denn das Blut ist die Seele; und du sollst nicht die Seele mit dem Fleische essen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'du sollst es nicht essen, du sollst es auf die Erde gießen wie Wasser;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'du sollst es nicht essen, auf daß es dir und deinen Kindern nach dir wohlgehe, weil du tust, was recht ist in den Augen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Jedoch deine heiligen Dinge, die du haben wirst, und deine Gelübde sollst du nehmen und an den Ort kommen, den Jehova erwählen wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'und deine Brandopfer, das Fleisch und das Blut, sollst du auf dem Altar Jehovas, deines Gottes, opfern; und das Blut deiner Schlachtopfer soll an den Altar Jehovas, deines Gottes, gegossen werden, und das Fleisch magst du essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Habe acht und höre auf alle diese Worte, die ich dir gebiete, auf daß es dir und deinen Kindern nach dir wohlgehe ewiglich, weil du tust, was gut und recht ist in den Augen Jehovas, deines Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Wenn Jehova, dein Gott, die Nationen vor dir ausrottet, zu welchen du kommst, um sie auszutreiben, und du treibst sie aus und wohnst in ihrem Lande,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'so hüte dich, daß du nicht verstrickt werdest ihnen nach, nachdem sie vor dir vertilgt sind, und daß du nicht fragest nach ihren Göttern und sprechest: Wie dienten diese Nationen ihren Göttern? So will auch ich ebenso tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Jehova, deinem Gott, sollst du nicht also tun; denn alles, was für Jehova ein Greuel ist, den er haßt, haben sie ihren Göttern getan; denn sogar ihre Söhne und ihre Töchter haben sie ihren Göttern mit Feuer verbrannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Das ganze Wort, das ich euch gebiete, das sollt ihr beobachten, es zu tun; du sollst nichts hinzufügen und nichts davontun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Wenn in deiner Mitte ein Prophet aufsteht, oder einer, der Träume hat, und er gibt dir ein Zeichen oder ein Wunder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'und das Zeichen oder das Wunder trifft ein, von welchem er zu dir geredet hat, indem er sprach: Laß uns anderen Göttern nachgehen (die du nicht gekannt hast) und ihnen dienen! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'so sollst du nicht hören auf die Worte dieses Propheten oder auf den, der die Träume hat; denn Jehova, euer Gott, versucht euch, um zu erkennen, ob ihr Jehova, euren Gott, liebet mit eurem ganzen Herzen und mit eurer ganzen Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Jehova, eurem Gott, sollt ihr nachfolgen und ihn fürchten; und ihr sollt seine Gebote beobachten und seiner Stimme gehorchen und ihm dienen und ihm anhangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Und jener Prophet oder jener, der die Träume hat, soll getötet werden; denn er hat Abfall geredet wider Jehova, euren Gott, der euch aus dem Lande Ägypten herausgeführt und dich erlöst hat aus dem Hause der Knechtschaft, um dich abzuleiten von dem Wege, auf welchem zu wandeln Jehova, dein Gott, dir geboten hat. Und du sollst das Böse aus deiner Mitte hinwegschaffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Wenn dein Bruder, der Sohn deiner Mutter, oder dein Sohn, oder deine Tochter, oder das Weib deines Busens, oder dein Freund, der dir wie deine Seele ist, dich heimlich anreizt und spricht: Laß uns gehen und anderen Göttern dienen (die du nicht gekannt hast, du noch deine Väter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'von den Göttern der Völker, die rings um euch her sind, nahe bei dir oder fern von dir, von einem Ende der Erde bis zum anderen Ende der Erde),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'so sollst du ihm nicht zu Willen sein und nicht auf ihn hören; und dein Auge soll seiner nicht schonen, und du sollst dich seiner nicht erbarmen noch ihn verbergen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'sondern du sollst ihn gewißlich töten. Deine Hand soll zuerst an ihm sein, ihn zu töten, und danach die Hand des ganzen Volkes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'und du sollst ihn steinigen, daß er sterbe. Denn er hat gesucht, dich abzuleiten von Jehova, deinem Gott, der dich herausgeführt hat aus dem Lande Ägypten, aus dem Hause der Knechtschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Und ganz Israel soll es hören und sich fürchten, damit man nicht mehr eine solche Übeltat in deiner Mitte begehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Wenn du von einer deiner Städte, die Jehova, dein Gott, dir gibt, um daselbst zu wohnen, sagen hörst:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Es sind Männer, Söhne Belials, aus deiner Mitte ausgegangen und haben die Bewohner ihrer Stadt verleitet und gesprochen: Laßt uns gehen und anderen Göttern dienen (die ihr nicht gekannt habt),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'so sollst du genau untersuchen und nachforschen und fragen; und siehe, ist es Wahrheit, steht die Sache fest, ist dieser Greuel in deiner Mitte verübt worden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'so sollst du die Bewohner jener Stadt gewißlich schlagen mit der Schärfe des Schwertes; du sollst sie verbannen und alles, was in ihr ist, und ihr Vieh, mit der Schärfe des Schwertes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Und alle ihre Beute sollst du mitten auf ihren Platz zusammentragen und die Stadt und alle ihre Beute Jehova, deinem Gott, gänzlich mit Feuer verbrennen; und sie soll ein Schutthaufen sein ewiglich, sie soll nicht wieder aufgebaut werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Und nicht soll irgend etwas von dem Verbannten an deiner Hand haften, auf daß Jehova sich von der Glut seines Zornes wende und dir Erbarmung gebe und sich deiner erbarme und dich mehre, so wie er deinen Vätern geschworen hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'wenn du der Stimme Jehovas, deines Gottes, gehorchst, alle seine Gebote zu beobachten, die ich dir heute gebiete, daß du tust, was recht ist in den Augen Jehovas, deines Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Ihr seid Kinder Jehovas, eures Gottes; ihr sollt euch nicht wegen eines Toten Einschnitte machen und euch nicht kahl scheren zwischen euren Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Denn ein heiliges Volk bist du Jehova, deinem Gott; und dich hat Jehova erwählt, ihm ein Eigentumsvolk zu sein, aus allen Völkern, die auf dem Erdboden sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Du sollst keinen Greuel essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Dies sind die Tiere, die ihr essen sollt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Rind, Schaf und Ziege, Hirsch und Gazelle und Damhirsch und Steinbock und Antilope und Bergziege und Wildschaf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Und jedes Tier, das gespaltene Hufe hat, und zwar ganz durchgespaltene Hufe, und das wiederkäut unter den Tieren, das sollt ihr essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Nur diese sollt ihr nicht essen von den wiederkäuenden und von denen, die mit gespaltenen Hufen versehen sind: Das Kamel und den Hasen und den Klippendachs; denn sie wiederkäuen, aber sie haben keine gespaltene Hufe: Unrein sollen sie euch sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'und das Schwein, denn es hat gespaltene Hufe, aber es wiederkäut nicht: Unrein soll es euch sein. Von ihrem Fleische sollt ihr nicht essen, und ihr Aas sollt ihr nicht anrühren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Dieses sollt ihr essen von allem, was in den Wassern ist: Alles, was Floßfedern und Schuppen hat, sollt ihr essen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'aber alles, was keine Floßfedern und Schuppen hat, sollt ihr nicht essen: Unrein soll es euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Alle reinen Vögel sollt ihr essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Aber diese sind es, die ihr von ihnen nicht essen sollt: Der Adler und der Beinbrecher und der Seeadler,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'und der Falke und die Weihe, und der Geier nach seiner Art,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'und alle Raben nach ihrer Art,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'und die Straußhenne und der Straußhahn und die Seemöve, und der Habicht nach seiner Art,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'die Eule und die Rohrdommel und das Purpurhuhn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'und der Pelikan und der Aasgeier und der Sturzpelikan,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'und der Storch, und der Fischreiher nach seiner Art, und der Wiedehopf und die Fledermaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Und alles geflügelte Gewürm soll euch unrein sein; es soll nicht gegessen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Alles reine Gevögel sollt ihr essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Ihr sollt kein Aas essen; dem Fremdling, der in deinen Toren ist, magst du es geben, daß er es esse, oder verkaufe es einem Fremden; denn ein heiliges Volk bist du Jehova, deinem Gott. Du sollst ein Böcklein nicht kochen in der Milch seiner Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Du sollst treulich verzehnten allen Ertrag deiner Saat, die aus dem Felde erwächst, Jahr für Jahr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Und du sollst essen vor Jehova, deinem Gott, an dem Orte, den er erwählen wird, um seinen Namen daselbst wohnen zu lassen, den Zehnten deines Getreides, deines Mostes und deines Öles, und die Erstgeborenen deines Rind-und deines Kleinviehes, auf daß du Jehova, deinen Gott, fürchten lernest alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Und wenn der Weg zu weit für dich ist, daß du es nicht hinbringen kannst, weil der Ort fern von dir ist, den Jehova, dein Gott, erwählen wird, um seinen Namen dahin zu setzen, wenn Jehova, dein Gott, dich segnet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'so sollst du es um Geld geben; und binde das Geld in deine Hand zusammen, und gehe an den Ort, den Jehova, dein Gott, erwählen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Und gib das Geld für alles, was deine Seele begehrt, für Rinder und für Kleinvieh und für Wein und für starkes Getränk, und für alles, was deine Seele wünscht; und iß daselbst vor Jehova, deinem Gott, und freue dich, du und dein Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Und den Leviten, der in deinen Toren ist, den sollst du nicht verlassen; denn er hat kein Teil noch Erbe mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Am Ende von drei Jahren sollst du allen Zehnten deines Ertrages in jenem Jahre aussondern und ihn in deinen Toren niederlegen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'und der Levit, denn er hat kein Teil noch Erbe mit dir und der Fremdling und die Waise und die Witwe, die in deinen Toren sind, sollen kommen und essen und sich sättigen; auf daß Jehova, dein Gott, dich segne in allem Werke deiner Hand, das du tust.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Am Ende von sieben Jahren sollst du einen Erlaß halten. Und dies ist die Sache mit dem Erlasse:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Jeder Schuldherr soll erlassen das Darlehn seiner Hand, das er seinem Nächsten geliehen hat; er soll seinen Nächsten und seinen Bruder nicht drängen; denn man hat einen Erlaß dem Jehova ausgerufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Den Fremden magst du drängen; was du aber bei deinem Bruder hast, soll deine Hand erlassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'es sei denn, daß kein Armer unter dir ist. Denn Jehova wird dich reichlich segnen in dem Lande, welches Jehova, dein Gott, dir als Erbteil gibt, es zu besitzen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'wenn du nur der Stimme Jehovas, deines Gottes, fleißig gehorchst, darauf zu achten, dieses ganze Gebot zu tun, das ich dir heute gebiete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Denn Jehova, dein Gott, wird dich segnen, wie er zu dir geredet hat; und du wirst vielen Nationen auf Pfand leihen, du aber wirst nichts auf Pfand entlehnen; und du wirst über viele Nationen herrschen, über dich aber werden sie nicht herrschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Wenn ein Armer unter dir sein wird, irgend einer deiner Brüder, in einem deiner Tore in deinem Lande, das Jehova, dein Gott, dir gibt, so sollst du dein Herz nicht verhärten und deine Hand vor deinem Bruder, dem Armen, nicht verschließen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'sondern du sollst ihm deine Hand weit auftun und ihm willig auf Pfand leihen, was hinreicht für den Mangel, den er hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Hüte dich, daß nicht in deinem Herzen ein Belialswort sei, daß du sprechest: Es naht das siebte Jahr, das Erlaßjahr! und daß dein Auge böse sei gegen deinen Bruder, den Armen, und du ihm nichts gebest, und er über dich zu Jehova schreie, und Sünde an dir sei!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Willig sollst du ihm geben, und dein Herz soll nicht ärgerlich sein, wenn du ihm gibst; denn um dieser Sache willen wird Jehova, dein Gott, dich segnen in all deinem Werke und in allem Geschäft deiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Denn der Arme wird nicht aufhören inmitten des Landes; darum gebiete ich dir und spreche: Du sollst deinem Bruder, deinem Dürftigen und deinem Armen in deinem Lande, deine Hand weit auftun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Wenn dein Bruder, ein Hebräer oder eine Hebräerin, sich dir verkauft, so soll er dir sechs Jahre dienen; und im siebten Jahre sollst du ihn frei von dir entlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Und wenn du ihn frei von dir entlässest, so sollst du ihn nicht leer entlassen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Du sollst ihm reichlich aufladen von deinem Kleinvieh und von deiner Tenne und von deiner Kelter; von dem, womit Jehova, dein Gott, dich gesegnet hat, sollst du ihm geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Und du sollst gedenken, daß du ein Knecht gewesen bist im Lande Ägypten, und daß Jehova, dein Gott, dich erlöst hat; darum gebiete ich dir heute diese Sache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Und es soll geschehen, wenn er zu dir spricht: Ich will nicht von dir weggehen, weil er dich und dein Haus liebt, weil ihm wohl bei dir ist-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'so sollst du eine Pfrieme nehmen und sie durch sein Ohr in die Tür stechen, und er wird dein Knecht sein für immer; und auch deiner Magd sollst du also tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Es soll nicht schwer sein in deinen Augen, wenn du ihn frei von dir entlässest; denn was an Wert das Doppelte des Lohnes eines Tagelöhners ausmacht, hat er dir sechs Jahre lang gedient; und Jehova, dein Gott, wird dich segnen in allem, was du tust.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Alles männliche Erstgeborene, das unter deinen Rindern unter deinem Kleinvieh geboren wird, sollst du Jehova, deinem Gott, heiligen. Du sollst mit dem Erstgeborenen deines Rindes nicht arbeiten, und du sollst das Erstgeborene deines Kleinviehes nicht scheren:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Vor Jehova, deinem Gott, sollst du es essen, Jahr für Jahr, du und dein Haus, an dem Orte, den Jehova erwählen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Wenn aber ein Gebrechen an ihm ist, daß es lahm oder blind ist, irgend ein schlimmes Gebrechen, so sollst du es Jehova, deinem Gott, nicht opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'In deinen Toren magst du es essen, der Unreine und der Reine gleicherweise, wie die Gazelle und wie den Hirsch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Nur sein Blut sollst du nicht essen; du sollst es auf die Erde gießen wie Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Beobachte den Monat Abib und feiere das Passah Jehova, deinem Gott; denn im Monat Abib hat Jehova, dein Gott, dich des Nachts aus Ägypten herausgeführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Und du sollst Jehova, deinem Gott, das Passah schlachten, Klein-und Rindvieh, an dem Orte, den Jehova erwählen wird, um seinen Namen daselbst wohnen zu lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Du sollst kein Gesäuertes dazu essen; sieben Tage sollst du Ungesäuertes dazu essen, Brot des Elendes, denn in Eile bist du aus dem Lande Ägypten herausgezogen, auf daß du gedenkest des Tages deines Auszugs aus dem Lande Ägypten alle Tage deines Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Und sieben Tage soll kein Sauerteig bei dir gesehen werden in deinem ganzen Gebiet; und von dem Fleische, das du am Abend schlachtest, am ersten Tage, soll nichts über Nacht bleiben bis an den Morgen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Du kannst das Passah nicht in einem deiner Tore schlachten, die Jehova, dein Gott, dir gibt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'sondern an dem Orte, den Jehova, dein Gott, erwählen wird, um seinen Namen daselbst wohnen zu lassen, dort sollst du das Passah schlachten, am Abend, beim Untergang der Sonne, zur Zeit deines Auszuges aus Ägypten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'und du sollst es braten und essen an dem Orte, den Jehova, dein Gott, erwählen wird. Und am Morgen sollst du dich wenden und nach deinen Zelten gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Sechs Tage sollst du Ungesäuertes essen; und am siebten Tage ist eine Festversammlung Jehova, deinem Gott; du sollst kein Werk tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Sieben Wochen sollst du dir zählen; von da an, wo man beginnt, die Sichel an die Saat zu legen, sollst du anfangen, sieben Wochen zu zählen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Und du sollst das Fest der Wochen Jehova, deinem Gott, feiern, je nach der freiwilligen Gabe deiner Hand, die du geben magst, so wie Jehova, dein Gott, dich segnen wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'und du sollst dich vor Jehova, deinem Gott, freuen, du und dein Sohn und deine Tochter, und dein Knecht und deine Magd, und der Levit, der in deinen Toren ist, und der Fremdling und die Waise und die Witwe, die in deiner Mitte sind, an dem Orte, den Jehova, dein Gott, erwählen wird, um seinen Namen daselbst wohnen zu lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Und du sollst gedenken, daß du ein Knecht in Ägypten gewesen bist, und sollst diese Satzungen beobachten und tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Das Fest der Laubhütten sollst du dir sieben Tage feiern, wenn du den Ertrag von deiner Tenne und von deiner Kelter einsammelst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'und du sollst dich an deinem Feste freuen, du und dein Sohn und deine Tochter, und dein Knecht und deine Magd, und der Levit und der Fremdling und die Waise und die Witwe, die in deinen Toren sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Sieben Tage sollst du Jehova, deinem Gott, das Fest feiern an dem Orte, den Jehova erwählen wird; denn Jehova, dein Gott, wird dich segnen in all deinem Ertrag und in allem Werke deiner Hände, und du sollst nur fröhlich sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Dreimal im Jahre sollen alle deine Männlichen vor Jehova, deinem Gott, erscheinen an dem Orte, den er erwählen wird: Am Feste der ungesäuerten Brote und am Feste der Wochen und am Feste der Laubhütten; und man soll nicht leer vor Jehova erscheinen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Ein jeder nach dem, was seine Hand geben kann, nach dem Segen Jehovas, deines Gottes, den er dir gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Richter und Vorsteher sollst du dir einsetzen, nach deinen Stämmen, in allen deinen Toren, die Jehova, dein Gott, dir gibt, damit sie das Volk richten mit gerechtem Gericht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Du sollst das Recht nicht beugen, du sollst die Person nicht ansehen und kein Geschenk nehmen, denn das Geschenk blendet die Augen der Weisen und verkehrt die Worte der Gerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Der Gerechtigkeit, der Gerechtigkeit sollst du nachjagen, auf daß du lebest und das Land besitzest, welches Jehova, dein Gott, dir gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Du sollst dir keine Aschera pflanzen, irgend ein Holz neben dem Altar Jehovas, deines Gottes, den du dir machen wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Und du sollst dir keine Bildsäule aufrichten, die Jehova, dein Gott, haßt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Du sollst Jehova, deinem Gott, kein Rind-oder Kleinvieh opfern, an welchem ein Gebrechen ist, irgend etwas Schlimmes; denn es ist ein Greuel für Jehova, deinen Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Wenn in deiner Mitte, in einem deiner Tore, die Jehova, dein Gott, dir gibt, ein Mann oder ein Weib gefunden wird, welche das tun, was böse ist in den Augen Jehovas, deines Gottes, indem sie seinen Bund übertreten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'so daß sie hingehen und anderen Göttern dienen und sich vor ihnen oder vor der Sonne oder vor dem Monde oder vor dem ganzen Heere des Himmels niederbeugen, was ich nicht geboten habe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'und es wird dir berichtet, und du hörst es, so sollst du genau nachforschen; und siehe, ist es Wahrheit, steht die Sache fest, ist dieser Greuel in Israel verübt worden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'so sollst du jenen Mann oder jenes Weib, die diese böse Sache getan haben, zu deinen Toren hinausführen, den Mann oder das Weib, und sollst sie steinigen, daß sie sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Auf die Aussage zweier Zeugen oder dreier Zeugen soll getötet werden, wer sterben soll; er soll nicht auf die Aussage eines einzelnen Zeugen getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Die Hand der Zeugen soll zuerst an ihm sein, ihn zu töten, und danach die Hand des ganzen Volkes. Und du sollst das Böse aus deiner Mitte hinwegschaffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Wenn dir eine Sache zwischen Blut und Blut, zwischen Rechtssache und Rechtssache, und zwischen Verletzung und Verletzung, zu schwierig ist zum Urteil, irgendwelche Streitsachen in deinen Toren, so sollst du dich aufmachen und an den Ort hinaufziehen, den Jehova, dein Gott, erwählen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Und du sollst zu den Priestern, den Leviten, kommen und zu dem Richter, der in jenen Tagen sein wird, und dich erkundigen; und sie werden dir den Rechtsspruch verkünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Und du sollst dem Spruche gemäß tun, welchen sie dir verkünden werden von jenem Orte aus, den Jehova erwählen wird, und sollst darauf achten, zu tun nach allem, was sie dich lehren werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Dem Gesetze gemäß, das sie dich lehren, und nach dem Rechte, das sie dir sagen werden, sollst du tun; von dem Spruche, den sie dir verkünden werden, sollst du weder zur Rechten noch zur Linken abweichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Der Mann aber, der mit Vermessenheit handeln würde, daß er auf den Priester, der dasteht, um den Dienst Jehovas, deines Gottes, daselbst zu verrichten, oder auf den Richter nicht hörte: Selbiger Mann soll sterben. Und du sollst das Böse aus Israel hinwegschaffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Und das ganze Volk soll es hören und sich fürchten, und nicht mehr vermessen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Wenn du in das Land kommst, das Jehova, dein Gott, dir gibt, und es besitzest und darin wohnst und sagst: Ich will einen König über mich setzen, gleich allen Nationen, die rings um mich her sind:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'so sollst du nur den König über dich setzen, den Jehova, dein Gott, erwählen wird; aus der Mitte deiner Brüder sollst du einen König über dich setzen; du sollst nicht einen fremden Mann über dich setzen, der nicht dein Bruder ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Nur soll er sich die Rosse nicht mehren und soll das Volk nicht nach Ägypten zurückführen, um sich die Rosse zu mehren; denn Jehova hat euch gesagt: Ihr sollt fortan nicht wieder dieses Weges zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Und er soll sich die Weiber nicht mehren, daß sein Herz nicht abwendig werde; und Silber und Gold soll er sich nicht sehr mehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Und es soll geschehen, wenn er auf dem Throne seines Königtums sitzt, so soll er sich eine Abschrift dieses Gesetzes in ein Buch schreiben, aus dem, was vor den Priestern, den Leviten, liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Und es soll bei ihm sein, und er soll alle Tage seines Lebens darin lesen, auf daß er Jehova, seinen Gott, fürchten lerne, um zu beobachten alle Worte dieses Gesetzes und diese Satzungen, sie zu tun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'damit sein Herz sich nicht über seine Brüder erhebe und damit er von dem Gebote weder zur Rechten noch zur Linken abweiche, auf daß er die Tage in seinem Königtum verlängere, er und seine Söhne, in der Mitte Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Die Priester, die Leviten, der ganze Stamm Levi, sollen kein Teil noch Erbe mit Israel haben; die Feueropfer Jehovas und sein Erbteil sollen sie essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Aber er soll kein Erbteil haben inmitten seiner Brüder; Jehova ist sein Erbteil, so wie er zu ihm geredet hat. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Und dies soll das Recht der Priester sein von seiten des Volkes, von seiten derer, die ein Schlachtopfer opfern, es sei Rind-oder Kleinvieh: Man soll dem Priester die Schulter geben und die Kinnbacken und den rauhen Magen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Die Erstlinge deines Getreides, deines Mostes und deines Öles, und die Erstlinge von der Schur deiner Schafe sollst du ihm geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'denn ihn hat Jehova, dein Gott, erwählt aus allen deinen Stämmen, damit er dastehe, um den Dienst im Namen Jehovas zu verrichten, er und seine Söhne, alle Tage. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Und wenn der Levit kommen wird aus einem deiner Tore, aus ganz Israel, wo er sich aufhält, und er kommt nach aller Lust seiner Seele an den Ort, den Jehova erwählen wird,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'und verrichtet den Dienst im Namen Jehovas, seines Gottes, wie alle seine Brüder, die Leviten, die daselbst vor Jehova stehen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'so sollen sie zu gleichen Teilen essen, außer dem was er von seinem väterlichen Eigentum verkauft hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Wenn du in das Land kommst, das Jehova, dein Gott, dir gibt, so sollst du nicht lernen, nach den Greueln dieser Nationen zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Es soll keiner unter dir gefunden werden, der seinen Sohn oder seine Tochter durchs Feuer gehen läßt, keiner, der Wahrsagerei treibt, kein Zauberer oder Beschwörer oder Magier,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'oder Bannsprecher oder Totenbeschwörer oder Wahrsager oder der die Toten befragt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Denn ein Greuel für Jehova ist ein jeder, der diese Dinge tut; und um dieser Greuel willen treibt Jehova, dein Gott, sie vor dir aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Du sollst vollkommen sein gegen Jehova, deinen Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Denn diese Nationen, die du austreiben wirst, hören auf Zauberer und auf Wahrsager; du aber, nicht also hat Jehova, dein Gott, dir gestattet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Einen Propheten aus deiner Mitte, aus deinen Brüdern, gleich mir, wird Jehova, dein Gott, dir erwecken; auf ihn sollt ihr hören;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'nach allem, was du von Jehova, deinem Gott, am Horeb begehrt hast am Tage der Versammlung, indem du sprachest: ich möchte nicht weiter die Stimme Jehovas, meines Gottes, hören, und dieses große Feuer möchte ich nicht mehr sehen, daß ich nicht sterbe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Und Jehova sprach zu mir: Gut ist, was sie geredet haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Einen Propheten, gleich dir, will ich ihnen aus der Mitte ihrer Brüder erwecken; und ich will meine Worte in seinen Mund legen, und er wird zu ihnen reden alles, was ich ihm gebieten werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Und es wird geschehen, der Mann, der nicht hört auf meine Worte, die er in meinem Namen reden wird, von dem werde ich es fordern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Doch der Prophet, der sich vermessen wird, in meinem Namen ein Wort zu reden, das ich ihm nicht geboten habe zu reden, oder der im Namen anderer Götter reden wird: Selbiger Prophet soll sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Und wenn du in deinem Herzen sprichst: Wie sollen wir das Wort erkennen, das Jehova nicht geredet hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Wenn der Prophet im Namen Jehovas redet, und das Wort geschieht nicht und trifft nicht ein, so ist das das Wort, welches Jehova nicht geredet hat; mit Vermessenheit hat der Prophet es geredet; du sollst dich nicht vor ihm fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Wenn Jehova, dein Gott, die Nationen ausrotten wird, deren Land Jehova, dein Gott, dir gibt, und du sie austreibst und in ihren Städten und in ihren Häusern wohnst:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'so sollst du dir drei Städte aussondern inmitten deines Landes, das Jehova, dein Gott, dir gibt, es zu besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Du sollst dir den Weg dahin zurichten, und das Gebiet deines Landes, das Jehova, dein Gott, dir als Erbteil geben wird, in drei Teile teilen; und das soll geschehen, damit jeder Totschläger dahin fliehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Und dies ist die Sache mit dem Totschläger, der dahin fliehen soll, damit er am Leben bleibe: Wer seinen Nächsten unabsichtlich erschlägt, und er haßte ihn vordem nicht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'wie etwa wenn jemand mit seinem Nächsten in den Wald geht, um Holz zu hauen, und seine Hand holt aus mit der Axt, um das Holz abzuhauen, und das Eisen fährt vom Stiele und trifft seinen Nächsten, daß er stirbt: Der soll in eine dieser Städte fliehen, damit er am Leben bleibe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'auf daß nicht der Bluträcher, weil sein Herz entbrannt ist, dem Totschläger nachsetze und ihn erreiche, weil der Weg lang ist, und ihn totschlage, obwohl ihm kein Todesurteil gebührt, da er ihn vordem nicht haßte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Darum gebiete ich dir und sage: Drei Städte sollst du dir aussondern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Und wenn Jehova, dein Gott, deine Grenzen erweitert, so wie er deinen Vätern geschworen hat, und dir das ganze Land gibt, welches er deinen Vätern zu geben verheißen hat');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, '(wenn du darauf achtest, dieses ganze Gebot zu tun, das ich dir heute gebiete, indem du Jehova, deinen Gott, liebst und auf seinen Wegen wandelst alle Tage), so sollst du dir zu diesen dreien noch drei Städte hinzufügen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'damit nicht unschuldiges Blut vergossen werde inmitten deines Landes, das Jehova, dein Gott, dir als Erbteil gibt, und Blutschuld auf dir sei. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Wenn aber ein Mann seinen Nächsten haßt, und ihm auflauert und sich wider ihn erhebt und ihn totschlägt, so daß er stirbt, und er flieht in eine dieser Städte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'so sollen die Ältesten seiner Stadt hinsenden und ihn von dannen holen lassen und ihn in die Hand des Bluträchers liefern, daß er sterbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Dein Auge soll seiner nicht schonen; und du sollst das unschuldige Blut aus Israel hinwegschaffen, und es wird dir wohlgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Du sollst nicht die Grenze deines Nächsten verrücken, welche die Vorfahren in deinem Erbteil gesetzt haben, das du erben wirst in dem Lande, welches Jehova, dein Gott, dir gibt, es zu besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Ein einzelner Zeuge soll nicht wider jemand auftreten wegen irgend einer Ungerechtigkeit und wegen irgend einer Sünde, bei irgend einer Sünde, die er begeht; auf zweier Zeugen Aussage oder auf dreier Zeugen Aussage soll eine Sache bestätigt werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Wenn ein ungerechter Zeuge wider jemand auftritt, um ein Vergehen wider ihn zu bezeugen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'so sollen die beiden Männer, die den Hader haben, vor Jehova treten, vor die Priester und die Richter, die in jenen Tagen sein werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Und die Richter sollen wohl nachforschen; und siehe, ist der Zeuge ein falscher Zeuge, hat er Falsches wider seinen Bruder bezeugt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'so sollt ihr ihm tun, wie er seinem Bruder zu tun gedachte; und du sollst das Böse aus deiner Mitte hinwegschaffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Und die Übrigen sollen es hören und sich fürchten und fortan nicht mehr eine solche Übeltat in deiner Mitte begehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Und dein Auge soll nicht schonen: Leben um Leben, Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Wenn du wider deine Feinde zum Kriege ausziehst und siehst Roß und Wagen, ein Volk, zahlreicher als du, so sollst du dich nicht vor ihnen fürchten; denn Jehova, dein Gott, ist mit dir, der dich aus dem Lande Ägypten heraufgeführt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Und es soll geschehen, wenn ihr zum Streite heranrücket, so soll der Priester herzutreten und zu dem Volke reden');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'und zu ihnen sprechen: Höre, Israel! Ihr rücket heute zum Streite heran wider eure Feinde; euer Herz verzage nicht, fürchtet euch nicht und ängstiget euch nicht und erschrecket nicht vor ihnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'denn Jehova, euer Gott, ist es, der mit euch zieht, um für euch zu streiten mit euren Feinden, um euch zu retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Und die Vorsteher sollen zu dem Volke reden und sprechen: Wer ist der Mann, der ein neues Haus gebaut und es noch nicht eingeweiht hat? Er gehe und kehre nach seinem Hause zurück, damit er nicht in der Schlacht sterbe, und ein anderer Mann es einweihe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Und wer ist der Mann, der einen Weinberg gepflanzt und ihn noch nicht benutzt hat? Er gehe und kehre nach seinem Hause zurück, damit er nicht in der Schlacht sterbe, und ein anderer Mann ihn benutze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Und wer ist der Mann, der sich ein Weib verlobt und es noch nicht genommen hat? Er gehe und kehre nach seinem Hause zurück, damit er nicht in der Schlacht sterbe, und ein anderer Mann sie nehme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Und die Vorsteher sollen weiter zu dem Volke reden und sprechen: Wer ist der Mann, der sich fürchtet und verzagten Herzens ist? Er gehe und kehre nach seinem Hause zurück, damit nicht das Herz seiner Brüder verzagt werde wie sein Herz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Und es soll geschehen, wenn die Vorsteher aufgehört haben, zu dem Volke zu reden, so sollen sie Heeroberste an die Spitze des Volkes stellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Wenn du dich einer Stadt näherst, wider sie zu streiten, so sollst du ihr Frieden anbieten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Und es soll geschehen, wenn sie dir Frieden erwidert und dir auftut, so soll alles Volk, das sich darin befindet, dir fronpflichtig sein und dir dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Und wenn sie nicht Frieden mit dir macht, sondern Krieg mit dir führt, so sollst du sie belagern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'und gibt Jehova, dein Gott, sie in deine Hand, so schlage alle ihre Männlichen mit der Schärfe des Schwertes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Doch die Weiber und die Kinder, und das Vieh und alles, was in der Stadt sein wird, alle ihre Beute, sollst du für dich rauben; und du sollst die Beute deiner Feinde essen, die Jehova, dein Gott, dir gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Also sollst du allen Städten tun, die sehr fern von dir sind, die nicht sind von den Städten dieser Nationen hier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Jedoch von den Städten dieser Völker, die Jehova, dein Gott, dir als Erbteil gibt, sollst du nichts leben lassen, was Odem hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'sondern du sollst sie gänzlich verbannen: Die Hethiter und die Amoriter, die Kanaaniter und die Perisiter, die Hewiter und die Jebusiter, wie Jehova, dein Gott, dir geboten hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'auf daß sie euch nicht lehren, zu tun nach allen ihren Greueln, die sie ihren Göttern getan haben, und ihr nicht sündiget wider Jehova, euren Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Wenn du eine Stadt viele Tage belagern wirst, indem du Krieg wider sie führst, um sie einzunehmen, so sollst du ihre Bäume nicht verderben, indem du die Axt gegen sie schwingst (denn du kannst davon essen), und sollst sie nicht abhauen; denn ist der Baum des Feldes ein Mensch, daß er vor dir in Belagerung kommen sollte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Nur die Bäume, von denen du weißt, daß sie keine Bäume sind, von denen man ißt, die darfst du verderben und abhauen; und du magst Belagerungswerke davon bauen wider die Stadt, die Krieg mit dir führt, bis sie gefallen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Wenn in dem Lande, das Jehova, dein Gott, dir gibt, es zu besitzen, ein Erschlagener auf dem Felde liegend gefunden wird, ohne daß es bekannt ist, wer ihn erschlagen hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'so sollen deine Ältesten und deine Richter hinausgehen und nach den Städten hin messen, die rings um den Erschlagenen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Und es geschehe: Die Stadt, welche dem Erschlagenen am nächsten ist, die Ältesten jener Stadt sollen eine Färse nehmen, mit der noch nicht gearbeitet worden ist, die noch nicht am Joche gezogen hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'und die Ältesten jener Stadt sollen die Färse zu einem immer fließenden Bache hinabführen, in welchem nicht gearbeitet und nicht gesät wird, und sollen der Färse daselbst im Bache das Genick brechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Und die Priester, die Söhne Levis, sollen herzutreten; denn sie hat Jehova, dein Gott, erwählt, ihm zu dienen und im Namen Jehovas zu segnen; und nach ihrem Ausspruch soll bei jedem Rechtsstreit und bei jeder Verletzung geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Und alle Ältesten jener Stadt, die dem Erschlagenen am nächsten sind, sollen ihre Hände über der Färse waschen, welcher das Genick im Bache gebrochen worden ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'und sollen anheben und sprechen: Unsere Hände haben dieses Blut nicht vergossen, und unsere Augen haben es nicht gesehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'vergib, Jehova, deinem Volke Israel, das du erlöst hast, und lege nicht unschuldiges Blut in deines Volkes Israel Mitte. Und die Blutschuld wird ihnen vergeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Und du, du sollst das unschuldige Blut aus deiner Mitte hinwegschaffen; denn du sollst tun, was recht ist in den Augen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Wenn du wider deine Feinde zum Kriege ausziehst, und Jehova, dein Gott, sie in deine Hand gibt, und du ihre Gefangenen wegführst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'und du siehst unter den Gefangenen ein Weib, schön von Gestalt, und hast Lust zu ihr und nimmst sie dir zum Weibe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'so sollst du sie in das Innere deines Hauses führen; und sie soll ihr Haupt scheren und ihre Nägel beschneiden');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'und die Kleider ihrer Gefangenschaft von sich ablegen; und sie soll in deinem Hause bleiben und ihren Vater und ihre Mutter einen Monat lang beweinen; und danach magst du zu ihr eingehen und sie ehelichen, daß sie dein Weib sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Und es soll geschehen, wenn du kein Gefallen mehr an ihr hast, so sollst du sie nach ihrem Wunsche entlassen; aber du darfst sie keineswegs um Geld verkaufen; du sollst sie nicht als Sklavin behandeln, darum daß du sie geschwächt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Wenn ein Mann zwei Weiber hat, eine geliebte und eine gehaßte, und sie gebären ihm Söhne, die geliebte und die gehaßte, und der erstgeborene Sohn ist von der gehaßten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'so soll es geschehen, an dem Tage, da er seine Söhne erben läßt was sein ist: Er kann nicht den Sohn der geliebten zum Erstgeborenen machen vor dem Sohne der gehaßten, dem Erstgeborenen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'sondern den Erstgeborenen, den Sohn der gehaßten, soll er anerkennen, daß er ihm zwei Teile gebe von allem, was in seinem Besitz gefunden wird; denn er ist der Erstling seiner Kraft, ihm gehört das Recht der Erstgeburt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Wenn ein Mann einen unbändigen und widerspenstigen Sohn hat, welcher der Stimme seines Vaters und der Stimme seiner Mutter nicht gehorcht, und sie züchtigen ihn, aber er gehorcht ihnen nicht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'so sollen sein Vater und seine Mutter ihn ergreifen und ihn zu den Ältesten seiner Stadt und zum Tore seines Ortes hinausführen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'und sollen zu den Ältesten seiner Stadt sprechen: Dieser unser Sohn ist unbändig und widerspenstig, er gehorcht unserer Stimme nicht, er ist ein Schlemmer und Säufer!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Und alle Leute seiner Stadt sollen ihn steinigen, daß er sterbe; und du sollst das Böse aus deiner Mitte hinwegschaffen. Und ganz Israel soll es hören und sich fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Und wenn an einem Manne eine todeswürdige Sünde ist, und er wird getötet, und du hängst ihn an ein Holz,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'so soll sein Leichnam nicht über Nacht an dem Holze bleiben, sondern du sollst ihn jedenfalls an demselben Tage begraben; denn ein Fluch Gottes ist ein Gehängter; und du sollst dein Land nicht verunreinigen, das Jehova, dein Gott, dir als Erbteil gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Du sollst nicht das Rind deines Bruders oder sein Kleinvieh irregehen sehen und dich ihnen entziehen; du sollst sie deinem Bruder jedenfalls zurückbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Wenn aber dein Bruder nicht nahe bei dir ist, und du kennst ihn nicht, so sollst du sie in dein Haus aufnehmen, daß sie bei dir seien, bis dein Bruder sie sucht; dann gib sie ihm zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Und ebenso sollst du mit seinem Esel tun, und ebenso sollst du mit seinem Gewande tun, und ebenso sollst du mit allem Verlorenen deines Bruders tun, das ihm verloren geht und das du findest; du kannst dich nicht entziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Du sollst nicht den Esel deines Bruders oder sein Rind auf dem Wege fallen sehen und dich ihnen entziehen; du sollst sie jedenfalls mit ihm aufrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Es soll nicht Mannszeug auf einem Weibe sein, und ein Mann soll nicht das Gewand eines Weibes anziehen; denn wer irgend solches tut, ist ein Greuel für Jehova, deinen Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Wenn sich zufällig ein Vogelnest vor dir auf dem Wege findet, auf irgend einem Baume oder auf der Erde, mit Jungen oder mit Eiern, und die Mutter sitzt auf den Jungen oder auf den Eiern, so sollst du nicht die Mutter samt den Jungen nehmen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'du sollst die Mutter jedenfalls fliegen lassen, und die Jungen magst du dir nehmen: auf daß es dir wohlgehe und du deine Tage verlängerst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Wenn du ein neues Haus baust, so sollst du ein Geländer um dein Dach machen, damit du nicht eine Blutschuld auf dein Haus bringest, wenn irgend jemand von demselben herabfiele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Du sollst deinen Weinberg nicht mit zweierlei Samen besäen, damit nicht die Fülle des Samens, den du gesät hast, und der Ertrag des Weinberges geheiligt werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Du sollst nicht pflügen mit einem Rinde und einem Esel zusammen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Du sollst nicht Zeug von verschiedenartigem Stoffe anziehen, Wolle und Leinen zusammen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Quasten sollst du dir machen an den vier Zipfeln deiner Hülle, womit du dich umhüllst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Wenn ein Mann ein Weib nimmt und zu ihr eingeht, und er haßt sie');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'und bürdet ihr Dinge zum Gerede auf und bringt einen bösen Namen über sie aus und spricht: Dieses Weib habe ich genommen und mich ihr genaht und habe die Zeichen der Jungfrauenschaft nicht an ihr gefunden! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'so sollen der Vater des jungen Weibes und ihre Mutter die Zeichen der Jungfrauenschaft des jungen Weibes nehmen und zu den Ältesten der Stadt in das Tor hinausbringen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'und der Vater des jungen Weibes soll zu den Ältesten sprechen: Ich habe meine Tochter diesem Manne zum Weibe gegeben, und er haßt sie;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'und siehe, er bürdet ihr Dinge zum Gerede auf und spricht: Ich habe an deiner Tochter die Zeichen der Jungfrauschaft nicht gefunden. Und hier sind die Zeichen der Jungfrauschaft meiner Tochter. Und sie sollen das Tuch vor den Ältesten der Stadt ausbreiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Und die Ältesten selbiger Stadt sollen den Mann nehmen und ihn züchtigen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'und sie sollen ihn strafen um hundert Sekel Silber und sie dem Vater des jungen Weibes geben, weil er einen bösen Namen über eine Jungfrau in Israel ausgebracht hat. Und sie soll sein Weib sein; er kann sie nicht entlassen alle seine Tage. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Wenn aber jene Sache Wahrheit gewesen ist, die Zeichen der Jungfrauschaft sind an dem jungen Weibe nicht gefunden worden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'so sollen sie das junge Weib hinausführen an den Eingang des Hauses ihres Vaters, und die Männer ihrer Stadt sollen sie steinigen, daß sie sterbe, weil sie eine Schandtat in Israel verübt hat, zu huren im Hause ihres Vaters. Und du sollst das Böse aus deiner Mitte hinwegschaffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Wenn ein Mann bei einem Weibe liegend gefunden wird, das eines Mannes Eheweib ist, so sollen sie alle beide sterben, der Mann, der bei dem Weibe gelegen hat, und das Weib. Und du sollst das Böse aus Israel hinwegschaffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Wenn ein Mädchen, eine Jungfrau, einem Manne verlobt ist, und es findet sie ein Mann in der Stadt und liegt bei ihr,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'so sollt ihr sie beide zum Tore selbiger Stadt hinausführen und sie steinigen, daß sie sterben: Das Mädchen deshalb, weil sie nicht in der Stadt geschrieen hat, und den Mann deshalb, weil er das Weib seines Nächsten geschwächt hat. Und du sollst das Böse aus deiner Mitte hinwegschaffen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Wenn aber der Mann das verlobte Mädchen auf dem Felde findet, und der Mann ergreift sie und liegt bei ihr, so soll der Mann, der bei ihr gelegen hat, allein sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Aber dem Mädchen sollst du nichts tun, an dem Mädchen ist keine Sünde zum Tode; denn gleichwie ein Mann sich erhebt wider seinen Nächsten und ihn totschlägt, also ist diese Sache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Denn er hat sie auf dem Felde gefunden; das verlobte Mädchen schrie, aber niemand rettete sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Wenn ein Mann ein Mädchen findet, eine Jungfrau, die nicht verlobt ist, und ergreift sie und liegt bei ihr, und sie werden gefunden:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'so soll der Mann, der bei ihr gelegen hat, dem Vater des Mädchens fünfzig Sekel Silber geben; und sie soll sein Weib sein, darum daß er sie geschwächt hat, er kann sie nicht entlassen alle seine Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Ein Mann soll nicht das Weib seines Vaters nehmen und soll die Decke seines Vaters nicht aufdecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Es soll keiner, dem die Hoden zerstoßen sind oder der Harnstrang abgeschnitten ist, in die Versammlung Jehovas kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Es soll kein Bastard in die Versammlung Jehovas kommen; auch das zehnte Geschlecht von ihm soll nicht in die Versammlung Jehovas kommen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Es soll kein Ammoniter noch Moabiter in die Versammlung Jehovas kommen; auch das zehnte Geschlecht von ihnen soll nicht in die Versammlung Jehovas kommen ewiglich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'deshalb weil sie euch nicht mit Brot und mit Wasser entgegengekommen sind auf dem Wege, als ihr aus Ägypten zoget; und weil sie Bileam, den Sohn Beors, aus Pethor in Mesopotamien, wider dich gedungen haben, um dich zu verfluchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Aber Jehova, dein Gott, wollte nicht auf Bileam hören, und Jehova, dein Gott, wandelte dir den Fluch in Segen; denn Jehova, dein Gott, hatte dich lieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Du sollst ihren Frieden und ihr Wohl nicht suchen alle deine Tage, ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Den Edomiter sollst du nicht verabscheuen, denn er ist dein Bruder. Den Ägypter sollst du nicht verabscheuen, denn du bist ein Fremdling in seinem Lande gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Kinder, die ihnen im dritten Geschlecht geboren werden, mögen von ihnen in die Versammlung Jehovas kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Wenn du wider deine Feinde ins Lager ausziehst, so sollst du dich vor allem Bösen hüten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Wenn ein Mann unter dir ist, der nicht rein ist durch ein Begegnis der Nacht, so soll er aus dem Lager hinausgehen; er soll nicht in das Lager hineinkommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'und es soll geschehen, wenn der Abend sich neigt, soll er sich im Wasser baden; und beim Untergang der Sonne darf er in das Lager zurückkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Und du sollst einen Platz außerhalb des Lagers haben, daß du dahin hinausgehest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Und du sollst eine Schaufel unter deinem Geräte haben; und es soll geschehen, wenn du dich draußen hinsetzest, so sollst du damit graben, und sollst dich umwenden und deine Ausleerung bedecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Denn Jehova, dein Gott, wandelt inmitten deines Lagers, um dich zu erretten und deine Feinde vor dir dahinzugeben; und dein Lager soll heilig sein, daß er nichts Schamwürdiges unter dir sehe und sich von dir abwende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Einen Knecht, der sich vor seinem Herrn zu dir rettet, sollst du seinem Herrn nicht ausliefern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Er soll bei dir wohnen, in deiner Mitte, an dem Orte, den er in einem deiner Tore erwählen wird, wo es ihm gut dünkt: du sollst ihn nicht bedrücken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Es soll keine Buhlerin sein unter den Töchtern Israels, und es soll kein Buhler sein unter den Söhnen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Du sollst nicht den Lohn einer Hure, noch den Preis eines Hundes in das Haus Jehovas, deines Gottes, bringen zu irgend einem Gelübde; denn auch diese beiden sind ein Greuel für Jehova, deinen Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Du sollst deinem Bruder keinen Zins auflegen, Zins von Geld, Zins von Speise, Zins von irgend einer Sache, die verzinst wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Dem Fremden magst du Zins auflegen, aber deinem Bruder sollst du keinen Zins auflegen; damit Jehova, dein Gott, dich segne in allem Geschäft deiner Hand in dem Lande, wohin du kommst, um es in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Wenn du Jehova, deinem Gott, ein Gelübde tust, so sollst du nicht zögern, es zu bezahlen; denn Jehova, dein Gott, wird es gewißlich von dir fordern, und es wird Sünde an dir sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Wenn du aber unterlässest zu geloben, so wird keine Sünde an dir sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Was über deine Lippen gegangen ist, sollst du halten und tun, so wie du Jehova, deinem Gott, freiwillig gelobt, was du mit deinem Munde geredet hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Wenn du in den Weinberg deines Nächsten kommst, so magst du Trauben essen nach deiner Lust, bis du satt bist; aber in dein Gefäß sollst du nichts tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Wenn du in das Getreidefeld deines Nächsten kommst, so magst du Ähren mit deiner Hand abpflücken; aber die Sichel sollst du nicht über das Getreide deines Nächsten schwingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Wenn ein Mann ein Weib nimmt und sie ehelicht, und es geschieht, wenn sie keine Gnade in seinen Augen findet, weil er etwas Schamwürdiges an ihr gefunden hat, daß er ihr einen Scheidebrief schreibt und ihn in ihre Hand gibt und sie aus seinem Hause entläßt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'und sie geht aus seinem Hause und geht hin und wird das Weib eines anderen Mannes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'und der andere Mann haßt sie, und schreibt ihr einen Scheidebrief und gibt ihn in ihre Hand und entläßt sie aus seinem Hause; oder wenn der andere Mann stirbt, der sie sich zum Weibe genommen hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'so kann ihr erster Mann, der sie entlassen hat, sie nicht wiederum nehmen, daß sie sein Weib sei, nachdem sie verunreinigt worden ist. Denn das ist ein Greuel vor Jehova; und du sollst nicht das Land sündigen machen, welches Jehova, dein Gott, dir als Erbteil gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Wenn ein Mann kürzlich ein Weib genommen hat, so soll er nicht in den Krieg ziehen, und es soll ihm keinerlei Sache auferlegt werden; er soll ein Jahr lang frei sein für sein Haus und sein Weib erfreuen, das er genommen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Man soll nicht Mühle noch Mühlstein pfänden; denn wer das tut, pfändet das Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Wenn ein Mann gefunden wird, der einen von seinen Brüdern, von den Kindern Israel, stiehlt, und ihn als Sklaven behandelt oder ihn verkauft, so soll selbiger Dieb sterben. Und du sollst das Böse aus deiner Mitte hinwegschaffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Habe acht bei dem Übel des Aussatzes, daß du sehr behutsam seiest und nach allem tuest, was euch die Priester, die Leviten, lehren werden; so wie ich ihnen geboten habe, sollt ihr achthaben zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Gedenke dessen, was Jehova, dein Gott, an Mirjam getan hat auf dem Wege, als ihr aus Ägypten zoget.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Wenn du deinem Nächsten irgend ein Darlehn leihst, so sollst du nicht in sein Haus hineingehen, um ihm ein Pfand abzupfänden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'draußen sollst du stehen bleiben, und der Mann, dem du geliehen hast, soll das Pfand zu dir hinausbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Und wenn er ein dürftiger Mann ist, so sollst du dich nicht mit seinem Pfande schlafen legen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'du sollst ihm das Pfand jedenfalls beim Untergang der Sonne zurückgeben, daß er sich in seinem Mantel schlafen lege und dich segne; und es wird dir Gerechtigkeit sein vor Jehova, deinem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Du sollst nicht bedrücken den dürftigen und armen Mietling von deinen Brüdern oder von deinen Fremdlingen, die in deinem Lande, in deinen Toren sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'An seinem Tage sollst du ihm seinen Lohn geben, und die Sonne soll nicht darüber untergehen; denn er ist dürftig, und er sehnt sich danach: Damit er nicht über dich zu Jehova schreie, und Sünde an dir sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Nicht sollen Väter getötet werden um der Kinder willen, und Kinder sollen nicht getötet werden um der Väter willen; sie sollen ein jeder für seine Sünde getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Du sollst das Recht eines Fremdlings und einer Waise nicht beugen; und das Kleid einer Witwe sollst du nicht pfänden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Und du sollst gedenken, daß du ein Knecht in Ägypten gewesen bist, und daß Jehova, dein Gott, dich von dannen erlöst hat; darum gebiete ich dir, solches zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Wenn du deine Ernte auf deinem Felde hältst und eine Garbe auf dem Felde vergissest, so sollst du nicht umkehren, um sie zu holen: Für den Fremdling, für die Waise und für die Witwe soll sie sein, auf daß Jehova, dein Gott, dich segne in allem Werke deiner Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Wenn du deine Oliven abschlägst, so sollst du nicht hinterdrein die Zweige absuchen: Für den Fremdling, für die Waise und für die Witwe soll es sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Wenn du deinen Weinberg liesest, so sollst du nicht hinterdrein Nachlese halten: Für den Fremdling, für die Waise und für die Witwe soll es sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Und du sollst gedenken, daß du ein Knecht im Lande Ägypten gewesen bist; darum gebiete ich dir, solches zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Wenn ein Hader zwischen Männern entsteht, und sie vor Gericht treten, und man richtet sie, so soll man den Gerechten gerecht sprechen und den Schuldigen schuldig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Und es soll geschehen, wenn der Schuldige Schläge verdient hat, so soll der Richter ihn niederlegen und ihm eine Anzahl Schläge geben lassen vor seinem Angesicht, nach Maßgabe seiner Schuld.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Mit vierzig Schlägen mag er ihn schlagen lassen, nicht mehr; damit nicht, wenn er fortführe, ihn über diese hinaus mit vielen Schlägen zu schlagen, dein Bruder verächtlich werde in deinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Du sollst dem Ochsen das Maul nicht verbinden, wenn er drischt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Wenn Brüder beisammen wohnen, und einer von ihnen stirbt und hat keinen Sohn, so soll das Weib des Verstorbenen nicht auswärts eines fremden Mannes werden; ihr Schwager soll zu ihr eingehen und sie sich zum Weibe nehmen und ihr die Schwagerpflicht leisten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Und es soll geschehen: Der Erstgeborene, den sie gebiert, soll nach dem Namen seines verstorbenen Bruders aufstehen, damit dessen Name nicht ausgelöscht werde aus Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Wenn aber der Mann keine Lust hat, seine Schwägerin zu nehmen, so soll seine Schwägerin ins Tor hinaufgehen zu den Ältesten und sprechen: Mein Schwager weigert sich, seinem Bruder einen Namen in Israel zu erwecken; er will mir die Schwagerpflicht nicht leisten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Und die Ältesten seiner Stadt sollen ihn rufen und mit ihm reden; und besteht er darauf und spricht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'Ich habe keine Lust, sie zu nehmen, so soll seine Schwägerin vor den Augen der Ältesten zu ihm hintreten, und ihm den Schuh von seinem Fuße ausziehen und ihm ins Angesicht speien; und sie soll antworten und sprechen: Also soll dem Manne getan werden, der das Haus seines Bruders nicht bauen will!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Und sein Name soll in Israel \"Das Haus des Barfüßigen\" heißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Wenn Männer miteinander streiten, ein Mann und sein Bruder, und das Weib des einen eilt herbei, um ihren Mann aus der Hand seines Schlägers zu retten, und streckt ihre Hand aus und ergreift ihn bei seiner Scham:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'so sollst du ihr die Hand abhauen; dein Auge soll nicht schonen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Du sollst nicht zweierlei Gewichtsteine in deinem Beutel haben, einen großen und einen kleinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Du sollst nicht zweierlei Epha in deinem Hause haben, ein großes und ein kleines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Vollen und gerechten Gewichtstein sollst du haben, und volles und gerechtes Epha sollst du haben, auf daß deine Tage verlängert werden in dem Lande, welches Jehova, dein Gott, dir gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Denn ein Greuel für Jehova, deinen Gott, ist jeder, der solches tut, jeder, der unrecht tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Gedenke dessen, was Amalek dir getan hat auf dem Wege, als ihr aus Ägypten zoget,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'wie er dir auf dem Wege entgegentrat und deinen Nachtrab schlug, alle Schwachen hinter dir her, als du matt und müde warst; und er fürchtete Gott nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Und wenn Jehova, dein Gott, dir Ruhe geschafft hat vor allen deinen Feinden ringsum, in dem Lande, welches Jehova, dein Gott, dir als Erbteil gibt, es zu besitzen, so soll es geschehen, daß du das Gedächtnis Amaleks unter dem Himmel austilgest. Vergiß es nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Und es soll geschehen, wenn du in das Land kommst, welches Jehova, dein Gott, dir als Erbteil gibt, und du besitzest es und wohnst darin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'so sollst du von den Erstlingen aller Frucht des Erdbodens nehmen, die du von deinem Lande einbringen wirst, das Jehova, dein Gott, dir gibt, und sollst sie in einen Korb legen und an den Ort gehen, welchen Jehova, dein Gott, erwählen wird, um seinen Namen daselbst wohnen zu lassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'und du sollst zu dem Priester kommen, der in jenen Tagen sein wird, und zu ihm sagen: Ich tue heute Jehova, deinem Gott, kund, daß ich in das Land gekommen bin, welches Jehova unseren Vätern geschworen hat, uns zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Und der Priester soll den Korb von deiner Hand nehmen und ihn vor den Altar Jehovas, deines Gottes, niedersetzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Und du sollst vor Jehova, deinem Gott, anheben und sprechen: Ein umherirrender Aramäer war mein Vater; und er zog nach Ägypten hinab und hielt sich daselbst auf als ein geringes Häuflein; und er wurde daselbst zu einer großen, starken und zahlreichen Nation.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Und die Ägypter mißhandelten uns und bedrückten uns und legten uns einen harten Dienst auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Da schrieen wir zu Jehova, dem Gott unserer Väter; und Jehova hörte unsere Stimme und sah unser Elend und unsere Mühsal und unseren Druck.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Und Jehova führte uns aus Ägypten heraus mit starker Hand und mit ausgestrecktem Arm und mit großem Schrecken, und mit Zeichen und mit Wundern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'und er brachte uns an diesen Ort und gab uns dieses Land, ein Land, das von Milch und Honig fließt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Und nun siehe, ich habe die Erstlinge der Frucht des Landes gebracht, das du, Jehova, mir gegeben hast. Und du sollst sie vor Jehova, deinem Gott, niederlegen und anbeten vor Jehova, deinem Gott;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'und du sollst dich freuen all des Guten, das Jehova, dein Gott, dir und deinem Hause gegeben hat, du und der Levit und der Fremdling, der in deiner Mitte ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Wenn du fertig bist mit dem Abtragen alles Zehnten deines Ertrages im dritten Jahre, dem Jahre des Zehnten, und du ihn dem Leviten, dem Fremdling, der Waise und der Witwe gegeben hast, damit sie in deinen Toren essen und sich sättigen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'so sollst du vor Jehova, deinem Gott, sprechen: Ich habe das Heilige aus dem Hause weggeschafft und habe es auch dem Leviten und dem Fremdling, der Waise und der Witwe gegeben, nach all deinem Gebot, das du mir geboten hast; ich habe deine Gebote nicht übertreten noch vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Ich habe nicht davon gegessen in meiner Trauer, und habe nicht davon weggeschafft als ein Unreiner, und habe nicht davon für einen Toten gegeben; ich habe der Stimme Jehovas, meines Gottes, gehorcht, ich habe getan nach allem, was du mir geboten hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Blicke hernieder von deiner heiligen Wohnung, vom Himmel, und segne dein Volk Israel, und das Land, das du uns gegeben, wie du unseren Vätern geschworen hast, ein Land, das von Milch und Honig fließt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'An diesem Tage gebietet dir Jehova, dein Gott, diese Satzungen und Rechte zu tun: So beobachte und tue sie mit deinem ganzen Herzen und mit deiner ganzen Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Du hast heute dem Jehova sagen lassen, daß er dein Gott sein soll, und daß du auf seinen Wegen wandeln und seine Satzungen und seine Gebote und seine Rechte beobachten und seiner Stimme gehorchen willst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Und Jehova hat dir heute sagen lassen, daß du ihm ein Eigentumsvolk sein sollst, so wie er zu dir geredet hat, und daß du alle seine Gebote beobachten sollst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'und daß er dich zur höchsten über alle Nationen machen will, die er gemacht hat, zum Ruhm und zum Namen und zum Schmuck; und daß du Jehova, deinem Gott, ein heiliges Volk sein sollst, so wie er geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Und Mose und die Ältesten von Israel geboten dem Volke und sprachen: Beobachtet das ganze Gebot, das ich euch heute gebiete!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Und es soll geschehen, an dem Tage, da ihr über den Jordan in das Land hinüberziehet, das Jehova, dein Gott, dir gibt, sollst du dir große Steine aufrichten und sie mit Kalk bestreichen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'und wenn du hinübergezogen bist, sollst du alle Worte dieses Gesetzes auf dieselben schreiben, damit du in das Land kommest, welches Jehova, dein Gott, dir gibt, ein Land, das von Milch und Honig fließt, so wie Jehova, der Gott deiner Väter, zu dir geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Und es soll geschehen, wenn ihr über den Jordan gezogen seid, so sollt ihr diese Steine, betreffs welcher ich euch heute gebiete, auf dem Berge Ebal aufrichten; und du sollst sie mit Kalk bestreichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Und du sollst daselbst Jehova, deinem Gott, einen Altar bauen, einen Altar von Steinen; du sollst kein Eisen über dieselben schwingen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Von ganzen Steinen sollst du den Altar Jehovas, deines Gottes, bauen. Und du sollst Jehova, deinem Gott, Brandopfer darauf opfern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'und du sollst Friedensopfer opfern, und daselbst essen und dich freuen vor Jehova, deinem Gott. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Und auf die Steine sollst du alle Worte dieses Gesetzes schreiben, indem du sie deutlich eingräbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Und Mose und die Priester, die Leviten, redeten zu dem ganzen Israel und sprachen: Schweige und höre, Israel! An diesem Tage bist du Jehova, deinem Gott, zum Volke geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'So gehorche der Stimme Jehovas, deines Gottes, und tue seine Gebote und seine Satzungen, die ich dir heute gebiete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Und Mose gebot dem Volke an selbigem Tage und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Wenn ihr über den Jordan gezogen seid, sollen diese auf dem Berge Gerisim stehen, um das Volk zu segnen: Simeon und Levi und Juda und Issaschar und Joseph und Benjamin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'und diese sollen auf dem Berge Ebal stehen zum Fluchen: Ruben, Gad und Aser und Sebulon, Dan und Naphtali.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Und die Leviten sollen anheben und zu allen Männern von Israel mit lauter Stimme sprechen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Verflucht sei der Mann, der ein geschnitztes oder gegossenes Bild macht, einen Greuel vor Jehova, ein Machwerk von Künstlerhand und es im Geheimen aufstellt! Und das ganze Volk antworte und sage: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Verflucht sei, wer seinen Vater oder seine Mutter verachtet! Und das ganze Volk sage: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Verflucht sei, wer die Grenze seines Nächsten verrückt! Und das ganze Volk sage: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Verflucht sei, wer einen Blinden auf dem Wege irreführt! Und das ganze Volk sage: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Verflucht sei, wer das Recht des Fremdlings, der Waise und der Witwe beugt! Und das ganze Volk sage: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Verflucht sei, wer bei dem Weibe seines Vaters liegt, denn er hat die Decke seines Vaters aufgedeckt! Und das ganze Volk sage: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Verflucht sei, wer bei irgend einem Vieh liegt! Und das ganze Volk sage: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Verflucht sei, wer bei seiner Schwester liegt, der Tochter seines Vaters oder der Tochter seiner Mutter! Und das ganze Volk sage: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Verflucht sei, wer bei seiner Schwiegermutter liegt! Und das ganze Volk sage: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Verflucht sei, wer seinen Nächsten im Geheimen erschlägt! Und das ganze Volk sage: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Verflucht sei, wer ein Geschenk nimmt, um jemand zu erschlagen, unschuldiges Blut zu vergießen! Und das ganze Volk sage: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Verflucht sei, wer nicht aufrecht hält die Worte dieses Gesetzes, sie zu tun! Und das ganze Volk sage: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Und es wird geschehen, wenn du der Stimme Jehovas, deines Gottes, fleißig gehorchst, daß du darauf achtest, zu tun alle seine Gebote, die ich dir heute gebiete, so wird Jehova, dein Gott, dich zur höchsten über alle Nationen der Erde machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'und alle diese Segnungen werden über dich kommen und werden dich erreichen, wenn du der Stimme Jehovas, deines Gottes, gehorchst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Gesegnet wirst du sein in der Stadt, und gesegnet wirst du sein auf dem Felde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Gesegnet wird sein die Frucht deines Leibes und die Frucht deines Landes und die Frucht deines Viehes, das Geworfene deiner Rinder und die Zucht deines Kleinviehes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Gesegnet wird sein dein Korb und dein Backtrog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Gesegnet wirst du sein bei deinem Eingang, und gesegnet wirst du sein bei deinem Ausgang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Jehova wird deine Feinde, die wider dich aufstehen, geschlagen vor dir dahingeben; auf einem Wege werden sie wider dich ausziehen, und auf sieben Wegen werden sie vor dir fliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Jehova wird dir den Segen entbieten in deine Speicher und zu allem Geschäft deiner Hand, und er wird dich segnen in dem Lande, welches Jehova, dein Gott, dir gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Jehova wird dich als ein heiliges Volk für sich bestätigen, wie er dir geschworen hat, wenn du die Gebote Jehovas, deines Gottes, beobachtest und auf seinen Wegen wandelst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'und alle Völker der Erde werden sehen, daß du nach dem Namen Jehovas genannt bist, und werden sich vor dir fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Und Jehova wird dir Überfluß geben an der Frucht deines Leibes und an der Frucht deines Viehes und an der Frucht deines Landes, zur Wohlfahrt in dem Lande, das Jehova deinen Vätern geschworen hat, dir zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Jehova wird dir seinen guten Schatz, den Himmel, auftun, um den Regen deines Landes zu geben zu seiner Zeit, und um alles Werk deiner Hand zu segnen; und du wirst vielen Nationen leihen, du aber wirst nicht entlehnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Und Jehova wird dich zum Haupte machen und nicht zum Schwanze, und du wirst nur immer höher kommen und nicht abwärts gehen, wenn du den Geboten Jehovas, deines Gottes, gehorchst, die ich dir heute zu beobachten und zu tun gebiete,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'und nicht abweichst von all den Worten, die ich heute gebiete, weder zur Rechten noch zur Linken, um anderen Göttern nachzugehen, ihnen zu dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Es wird aber geschehen, wenn du der Stimme Jehovas, deines Gottes, nicht gehorchst, daß du darauf achtest, zu tun alle seine Gebote und seine Satzungen, die ich dir heute gebiete, so werden alle diese Flüche über dich kommen und dich treffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Verflucht wirst du sein in der Stadt, und verflucht wirst du sein auf dem Felde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Verflucht wird sein dein Korb und dein Backtrog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Verflucht wird sein die Frucht deines Leibes und die Frucht deines Landes, das Geworfene deiner Rinder und die Zucht deines Kleinviehes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Verflucht wirst du sein bei deinem Eingang, und verflucht wirst du sein bei deinem Ausgang. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Jehova wird den Fluch, die Bestürzung und die Verwünschung wider dich senden in allem Geschäft deiner Hand, das du tust, bis du vertilgt bist, und bis du schnell umkommst wegen der Bosheit deiner Handlungen, daß du mich verlassen hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Jehova wird die Pest an dir haften lassen, bis er dich aufreibt aus dem Lande, wohin du kommst, um es in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Jehova wird dich schlagen mit Schwindsucht und mit Fieberglut und mit Hitze und mit Entzündung, und mit Dürre und mit Kornbrand und mit Vergilben des Getreides, und sie werden dich verfolgen, bis du umkommst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Und dein Himmel, der über deinem Haupte ist, wird Erz sein, und die Erde, die unter dir ist, Eisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Jehova wird als Regen deines Landes Staub und Sand geben: Vom Himmel wird er auf dich herabkommen, bis du vertilgt bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Jehova wird dich geschlagen vor deinen Feinden dahingeben; auf einem Wege wirst du wider sie ausziehen, und auf sieben Wegen wirst du vor ihnen fliehen, und du wirst umhergetrieben werden in allen Königreichen der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Und dein Leichnam wird allem Gevögel des Himmels und den Tieren der Erde zum Fraße werden, und niemand wird sie wegscheuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Jehova wird dich schlagen mit den Geschwüren Ägyptens, und mit Beulen und mit Krätze und mit Grind, daß du nicht wirst geheilt werden können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Jehova wird dich schlagen mit Wahnsinn und mit Blindheit und mit Erstarrung des Herzens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'und du wirst am Mittag umhertappen, wie der Blinde im Finstern tappt, und du wirst kein Gelingen haben auf deinen Wegen; und du wirst nur bedrückt und beraubt sein alle Tage, und niemand wird retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Ein Weib wirst du dir verloben, und ein anderer Mann wird sie beschlafen; ein Haus wirst du bauen und nicht darin wohnen; einen Weinberg wirst du pflanzen und ihn nicht benutzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Dein Rind wird geschlachtet werden vor deinen Augen, und du wirst nicht davon essen; dein Esel wird geraubt werden vor deinem Angesicht und nicht zu dir zurückkehren; dein Kleinvieh wird deinen Feinden gegeben werden, und du wirst niemand haben, der rettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Deine Söhne und deine Töchter werden einem anderen Volke gegeben werden, und deine Augen werden es sehen und werden nach ihnen schmachten den ganzen Tag; aber es wird nicht in der Macht deiner Hand stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Die Frucht deines Landes und alle deine Arbeit wird ein Volk verzehren, das du nicht kennst; und du wirst nur bedrückt und geplagt sein alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Und du wirst wahnsinnig werden vor dem Anblick deiner Augen, den du erblickst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Jehova wird dich schlagen mit bösen Geschwüren an den Knien und an den Schenkeln, von deiner Fußsohle bis zu deinem Scheitel, daß du nicht wirst geheilt werden können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Jehova wird dich und deinen König, den du über dich setzen wirst, zu einer Nation führen, die du nicht gekannt hast, du noch deine Väter; und du wirst daselbst anderen Göttern dienen, Holz und Stein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Und du wirst zum Entsetzen werden, zum Sprichwort und zur Spottrede unter allen Völkern, wohin Jehova dich wegtreiben wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Viel Samen wirst du aufs Feld hinausführen; aber du wirst wenig einsammeln, denn die Heuschrecke wird ihn abfressen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Weinberge wirst du pflanzen und bauen; aber Wein wirst du weder trinken noch einsammeln, denn der Wurm wird sie fressen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Olivenbäume wirst du haben in allen deinen Grenzen; aber mit Öl wirst du dich nicht salben, denn dein Olivenbaum wird die Frucht abwerfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Söhne und Töchter wirst du zeugen; aber sie werden dir nicht gehören, denn sie werden in die Gefangenschaft gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Alle deine Bäume und die Frucht deines Landes wird die Grille in Besitz nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Der Fremdling, der in deiner Mitte ist, wird höher und höher über dich emporkommen, und du, du wirst tiefer und tiefer hinabsinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Er wird dir leihen, du aber wirst ihm nicht leihen; er wird zum Haupte, du aber wirst zum Schwanze werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Und alle diese Flüche werden über dich kommen und dich verfolgen und dich treffen, bis du vertilgt bist; weil du der Stimme Jehovas, deines Gottes, nicht gehorcht hast, seine Gebote und seine Satzungen zu beobachten, die er dir geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Und sie werden zum Zeichen und zum Wunder sein an dir und an deinem Samen bis in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Dafür daß du Jehova, deinem Gott, nicht mit Freude und mit fröhlichem Herzen gedient hast wegen des Überflusses an allem,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'wirst du deinen Feinden dienen, die Jehova wider dich senden wird, in Hunger und in Durst und in Blöße und in Mangel an allem; und er wird ein eisernes Joch auf deinen Hals legen, bis er dich vertilgt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Jehova wird von ferne, vom Ende der Erde her, eine Nation gegen dich herbeiführen, gleichwie der Adler fliegt, eine Nation, deren Sprache du nicht verstehst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'eine Nation harten Angesichts, welche die Person des Greises nicht ansieht und des Knaben sich nicht erbarmt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'und welche die Frucht deines Viehes und die Frucht deines Landes verzehren wird, bis du vertilgt bist; welche dir weder Getreide, noch Most, noch Öl, noch das Geworfene deiner Rinder, noch die Zucht deines Kleinviehes übriglassen wird, bis sie dich zu Grunde gerichtet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Und sie wird dich belagern in allen deinen Toren, bis deine Mauern, die hohen und festen, auf welche du vertraust, in deinem ganzen Lande gefallen sind; und sie wird dich belagern in allen deinen Toren, in deinem ganzen Lande, das Jehova, dein Gott, dir gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Und in der Belagerung und in der Bedrängnis, womit dein Feind dich bedrängen wird, wirst du essen die Frucht deines Leibes, das Fleisch deiner Söhne und deiner Töchter, welche Jehova, dein Gott, dir gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Der weichlichste und am meisten verzärtelte Mann unter dir, dessen Auge wird scheel sehen auf seinen Bruder und auf das Weib seines Busens und auf die übrigen seiner Kinder, die er übrigbehalten hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'daß er keinem von ihnen von dem Fleische seiner Kinder geben wird, das er isset; weil ihm nichts übriggeblieben ist in der Belagerung und in der Bedrängnis, womit dein Feind dich bedrängen wird in allen deinen Toren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Die Weichlichste unter dir und die Verzärteltste, welche vor Verzärtelung und vor Verweichlichung nie versucht hat, ihre Fußsohle auf die Erde zu setzen, deren Auge wird scheel sehen auf den Mann ihres Busens und auf ihren Sohn und auf ihre Tochter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'wegen ihrer Nachgeburt, die zwischen ihren Beinen hervorgeht, und wegen ihrer Kinder, die sie gebiert; denn sie wird sie im Geheimen aufessen aus Mangel an allem, in der Belagerung und in der Bedrängnis, womit dein Feind dich bedrängen wird in deinen Toren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Wenn du nicht darauf achtest, alle Worte dieses Gesetzes zu tun, die in diesem Buche geschrieben sind, daß du diesen herrlichen und furchtbaren Namen, Jehova, deinen Gott, fürchtest,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'so wird Jehova deine Plagen und die Plagen deines Samens außergewöhnlich machen: große und andauernde Plagen, und böse und andauernde Krankheiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Und er wird alle Seuchen Ägyptens über dich bringen, vor denen du dich fürchtest; und sie werden an dir haften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Auch alle Krankheiten und alle Plagen, die nicht in dem Buche dieses Gesetzes geschrieben sind, Jehova wird sie über dich kommen lassen, bis du vertilgt bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Und ihr werdet übrigbleiben als ein geringes Häuflein, anstatt daß ihr waret wie die Sterne des Himmels an Menge; weil du der Stimme Jehovas, deines Gottes, nicht gehorcht hast. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Und es wird geschehen: So wie Jehova sich über euch freute, euch wohlzutun und euch zu mehren, also wird Jehova sich über euch freuen, euch zu Grunde zu richten und euch zu vertilgen; und ihr werdet herausgerissen werden aus dem Lande, wohin du kommst, um es in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Und Jehova wird dich unter alle Völker zerstreuen, von einem Ende der Erde bis zum anderen Ende der Erde; und du wirst daselbst anderen Göttern dienen, die du nicht gekannt hast, du noch deine Väter, Holz und Stein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Und unter jenen Nationen wirst du nicht rasten, und deine Fußsohle wird keine Ruhestätte finden; und Jehova wird dir daselbst ein zitterndes Herz geben, Erlöschen der Augen und Verschmachten der Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Und dein Leben wird schwebend vor dir hangen, und du wirst dich fürchten Nacht und Tag und deinem Leben nicht trauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Am Morgen wirst du sagen: Wäre es doch Abend! Und am Abend wirst du sagen: Wäre es doch Morgen! Wegen der Furcht deines Herzens, womit du dich fürchten, und wegen des Anblicks deiner Augen, den du erblicken wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Und Jehova wird dich auf Schiffen nach Ägypten zurückführen, auf dem Wege, von dem ich dir gesagt habe: Du sollst ihn nie mehr wiedersehen! Und ihr werdet daselbst euren Feinden zu Knechten und zu Mägden verkauft werden, aber niemand wird kaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, '(H28:69) Das sind die Worte des Bundes, welchen Jehova im Lande Moab dem Mose geboten hat, mit den Kindern Israel zu machen, außer dem Bunde, den er am Horeb mit ihnen gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, '(H29:1) Und Mose berief ganz Israel und sprach zu ihnen: Ihr habt alles gesehen, (H29:2) was Jehova vor euren Augen im Lande Ägypten getan hat, an dem Pharao und an allen seinen Knechten und an seinem ganzen Lande:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Die großen Versuchungen, welche deine Augen gesehen haben, jene großen Zeichen und Wunder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Aber Jehova hat euch nicht ein Herz gegeben, zu erkennen, und Augen, zu sehen, und Ohren, zu hören, bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Und ich habe euch vierzig Jahre in der Wüste geführt: Eure Kleider sind nicht an euch zerfallen, und dein Schuh ist nicht abgenutzt an deinem Fuße;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Brot habt ihr nicht gegessen, und Wein und starkes Getränk habt ihr nicht getrunken; auf daß ihr erkenntet, daß ich Jehova, euer Gott, bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Und als ihr an diesen Ort kamet, da zogen Sihon, der König von Hesbon, und Og, der König von Basan, aus, uns entgegen zum Streit, und wir schlugen sie;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'und wir nahmen ihr Land ein und gaben es den Rubenitern und den Gaditern und dem halben Stamme der Manassiter zum Erbteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'So beobachtet denn die Worte dieses Bundes und tut sie, auf daß ihr Gelingen habet in allem, was ihr tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Ihr stehet heute allesamt vor Jehova, eurem Gott: eure Häupter, eure Stämme, eure Ältesten und eure Vorsteher,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'alle Männer von Israel, eure Kinder, eure Weiber und dein Fremdling, der inmitten deiner Lager ist, von deinem Holzhauer bis zu deinem Wasserschöpfer,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'damit du in den Bund Jehovas, deines Gottes, eintretest und in seinen Eidschwur, den Jehova, dein Gott, heute mit dir macht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'auf daß er dich heute als sein Volk bestätige, und er dein Gott sei, wie er zu dir geredet, und wie er deinen Vätern, Abraham, Isaak und Jakob, geschworen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Und nicht mit euch allein mache ich diesen Bund und diesen Eidschwur,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'sondern mit dem, der heute hier ist, der mit uns vor Jehova, unserem Gott, steht, und mit dem, der heute nicht mit uns hier ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Denn ihr wisset ja, wie wir im Lande Ägypten gewohnt haben, und wie wir mitten durch die Nationen gezogen sind, durch die ihr gezogen seid;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'und ihr habt ihre Scheusale gesehen, und ihre Götzen von Holz und Stein, Silber und Gold, die bei ihnen sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'daß kein Mann oder Weib, oder Geschlecht oder Stamm unter euch sei, dessen Herz sich heute von Jehova, unserem Gott, abwende, um hinzugehen, den Göttern jener Nationen zu dienen; daß nicht eine Wurzel unter euch sei, die Gift und Wermut trage,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'und es geschehe, wenn er die Worte dieses Eidschwures hört, daß er sich in seinem Herzen segne und spreche: Ich werde Frieden haben, wenn ich auch in der Verstocktheit meines Herzens wandle! Damit zu Grunde gehe das Getränkte mit dem Durstigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Nicht wird Jehova ihm vergeben wollen, sondern alsdann wird der Zorn Jehovas und sein Eifer rauchen wider selbigen Mann; und der ganze Fluch, der in diesem Buche geschrieben ist, wird auf ihm ruhen, und Jehova wird seinen Namen unter dem Himmel austilgen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'und Jehova wird ihn aus allen Stämmen Israels zum Unglück aussondern, nach all den Flüchen des Bundes, der in diesem Buche des Gesetzes geschrieben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Und das künftige Geschlecht, eure Kinder, die nach euch aufkommen werden, und der Ausländer, der aus fernem Lande kommen wird, werden sagen, wenn sie die Plagen dieses Landes sehen und seine Krankheiten, womit Jehova es geschlagen hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'daß sein ganzes Land Schwefel und Salz, ein Brand, ist, daß es nicht besät wird und nichts sprossen läßt, und keinerlei Kraut darin aufkommt, gleich der Umkehrung von Sodom und Gomorra, Adama und Zeboim, welche Jehova umkehrte in seinem Zorn und in seinem Grimm, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'und alle Nationen werden sagen: Warum hat Jehova diesem Lande also getan? Weshalb diese große Zornglut?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Und man wird sagen: Darum daß sie den Bund Jehovas, des Gottes ihrer Väter, verlassen haben, den er mit ihnen gemacht hatte, als er sie aus dem Lande Ägypten herausführte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'und hingingen und anderen Göttern dienten und sich vor ihnen niederbeugten, Göttern, die sie nicht kannten, und die er ihnen nicht zugeteilt hatte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'da entbrannte der Zorn Jehovas über dieses Land, so daß er den ganzen Fluch über dasselbe gebracht hat, der in diesem Buche geschrieben ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Und Jehova hat sie herausgerissen aus ihrem Lande im Zorn und im Grimm und in großem Unwillen, und hat sie in ein anderes Land geworfen, wie es an diesem Tage ist. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Das Verborgene ist Jehovas, unseres Gottes; aber das Geoffenbarte ist unser und unserer Kinder ewiglich, damit wir alle Worte dieses Gesetzes tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Und es wird geschehen, wenn alle diese Worte über dich kommen, der Segen und der Fluch, die ich dir vorgelegt habe, und du es zu Herzen nimmst unter all den Nationen, wohin Jehova, dein Gott, dich vertrieben hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'und umkehrst zu Jehova, deinem Gott, und seiner Stimme gehorchst nach allem, was ich dir heute gebiete, du und deine Kinder, mit deinem ganzen Herzen und mit deiner ganzen Seele:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'so wird Jehova, dein Gott, deine Gefangenschaft wenden und sich deiner erbarmen; und er wird dich wiederum sammeln aus all den Völkern, wohin Jehova, dein Gott, dich zerstreut hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Wenn deine Vertriebenen am Ende des Himmels wären, so wird Jehova, dein Gott, von dannen dich sammeln und von dannen dich holen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'und Jehova, dein Gott, wird dich in das Land bringen, welches deine Väter besessen haben, und du wirst es besitzen; und er wird dir wohltun und dich mehren über deine Väter hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Und Jehova, dein Gott, wird dein Herz und das Herz deiner Kinder beschneiden, damit du Jehova, deinen Gott, liebest mit deinem ganzen Herzen und mit deiner ganzen Seele, auf daß du am Leben bleibest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Und Jehova, dein Gott, wird alle diese Flüche auf deine Feinde und auf deine Hasser legen, die dich verfolgt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Und du, du wirst umkehren und der Stimme Jehovas gehorchen, und wirst alle seine Gebote tun, die ich dir heute gebiete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Und Jehova, dein Gott, wird dir Überfluß geben bei allem Werke deiner Hand, an der Frucht deines Leibes und an der Frucht deines Viehes und an der Frucht deines Landes, zur Wohlfahrt; denn Jehova wird sich wieder über dich freuen zum Guten, so wie er sich über deine Väter gefreut hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Wenn du der Stimme Jehovas, deines Gottes, gehorchst, um seine Gebote und seine Satzungen zu beobachten, die in diesem Buche des Gesetzes geschrieben sind, wenn du umkehrst zu Jehova, deinem Gott, mit deinem ganzen Herzen und mit deiner ganzen Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Denn dieses Gebot, das ich dir heute gebiete, ist nicht zu wunderbar für dich und ist nicht fern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Es ist nicht im Himmel, daß du sagen könntest: Wer wird für uns in den Himmel steigen und es uns holen und es uns hören lassen, daß wir es tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Und es ist nicht jenseit des Meeres, daß du sagen könntest: Wer wird für uns jenseit des Meeres hinüberfahren und es uns holen und es uns hören lassen, daß wir es tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Sondern sehr nahe ist dir das Wort, in deinem Munde und in deinem Herzen, um es zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Siehe, ich habe dir heute das Leben und das Glück, und den Tod und das Unglück vorgelegt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'da ich dir heute gebiete, Jehova, deinen Gott, zu lieben, auf seinen Wegen zu wandeln und seine Gebote und seine Satzungen und seine Rechte zu beobachten, damit du lebest und dich mehrest, und Jehova, dein Gott, dich segne in dem Lande, wohin du kommst, um es in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Wenn aber dein Herz sich abwendet, und du nicht gehorchst, und du dich verleiten lässest und vor anderen Göttern dich niederbeugst und ihnen dienst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'so künde ich euch heute an, daß ihr gewißlich umkommen werdet; ihr werdet eure Tage nicht verlängern in dem Lande, wohin zu kommen du über den Jordan gehst, um es in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Ich nehme heute den Himmel und die Erde zu Zeugen gegen euch: Das Leben und den Tod habe ich euch vorgelegt, den Segen und den Fluch! So wähle das Leben, auf daß du lebest, du und dein Same,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'indem du Jehova, deinen Gott, liebst und seiner Stimme gehorchst und ihm anhängst; denn das ist dein Leben und die Länge deiner Tage, daß du in dem Lande wohnest, welches Jehova deinen Vätern, Abraham, Isaak und Jakob, geschworen hat, ihnen zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Und Mose ging hin und redete diese Worte zu dem ganzen Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Und er sprach zu ihnen: Hundertzwanzig Jahre bin ich heute alt, ich vermag nicht mehr aus-und einzugehen; und Jehova hat zu mir gesagt: Du sollst nicht über diesen Jordan gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Jehova, dein Gott, er zieht hinüber vor dir her; er selbst wird diese Nationen vor dir vertilgen, daß du sie austreibest. Josua, er zieht hinüber vor dir her, wie Jehova geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Und Jehova wird an ihnen tun, wie er an Sihon und an Og, den Königen der Amoriter, und an ihrem Lande getan, die er vertilgt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Und wenn Jehova sie vor euch dahingibt, so sollt ihr ihnen tun nach dem ganzen Gebot, das ich euch geboten habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Seid stark und mutig, fürchtet euch nicht und erschrecket nicht vor ihnen! Denn Jehova, dein Gott, er ist es, der mit dir geht; er wird dich nicht versäumen und dich nicht verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Und Mose rief Josua und sprach zu ihm vor den Augen des ganzen Israel: Sei stark und mutig! Denn du, du wirst mit diesem Volke in das Land kommen, welches Jehova ihren Vätern geschworen hat, ihnen zu geben; und du du wirst es ihnen als Erbe austeilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Und Jehova, er ist es, der vor dir herzieht; er selbst wird mit dir sein, er wird dich nicht versäumen und dich nicht verlassen; fürchte dich nicht und erschrick nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Und Mose schrieb dieses Gesetz nieder; und er gab es den Priestern, den Söhnen Levis, welche die Lade des Bundes Jehovas trugen, und allen Ältesten von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Und Mose gebot ihnen und sprach: Am Ende von sieben Jahren, zur Zeit des Erlaßjahres,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'am Feste der Laubhütten, wenn ganz Israel kommt, um vor Jehova, deinem Gott, zu erscheinen an dem Orte, den er erwählen wird, sollst du dieses Gesetz vor dem ganzen Israel lesen, vor ihren Ohren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Versammle das Volk, die Männer und die Weiber und die Kindlein, und deinen Fremdling, der in deinen Toren ist; auf daß sie hören, und auf daß sie lernen, und Jehova, euren Gott, fürchten und darauf achten, alle Worte dieses Gesetzes zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Und ihre Kinder, die es nicht wissen, sollen es hören, damit sie Jehova, euren Gott, fürchten lernen alle Tage, die ihr in dem Lande lebet, wohin ihr über den Jordan ziehet, um es in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Und Jehova sprach zu Mose: Siehe, deine Tage sind herangenaht, daß du sterben sollst; rufe Josua, und stellet euch in das Zelt der Zusammenkunft, daß ich ihm Befehl erteile. Und Mose und Josua gingen hin, und sie stellten sich in das Zelt der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Und Jehova erschien in dem Zelte, in der Wolkensäule; und die Wolkensäule stand über dem Eingang des Zeltes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Und Jehova sprach zu Mose: Siehe, du wirst dich zu deinen Vätern legen; und dieses Volk wird sich aufmachen und den fremden Göttern des Landes nachhuren, in dessen Mitte es kommt; und es wird mich verlassen und meinen Bund brechen, den ich mit ihnen gemacht habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Und mein Zorn wird an jenem Tage wider dasselbe entbrennen, und ich werde sie verlassen und mein Angesicht vor ihnen verbergen; und es wird verzehrt werden, und viele Übel und Drangsale werden es treffen. Und es wird an jenem Tage sagen: Haben nicht darum diese Übel mich getroffen, weil mein Gott nicht in meiner Mitte ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Ich aber, ich werde an jenem Tage mein Angesicht gänzlich verbergen um all des Bösen willen, das es getan, weil es sich zu anderen Göttern hingewandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Und nun, schreibet euch dieses Lied auf, und lehre es die Kinder Israel, lege es in ihren Mund, auf daß dieses Lied mir zum Zeugen sei gegen die Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Denn ich werde sie in das Land bringen, welches ich ihren Vätern zugeschworen habe, das von Milch und Honig fließt; und sie werden essen und satt und fett werden; und sie werden sich zu anderen Göttern wenden und ihnen dienen, und mich verachten und meinen Bund brechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Und es wird geschehen, wenn viele Übel und Drangsale sie treffen, so wird dieses Lied Zeugnis gegen sie ablegen; denn es wird nicht vergessen werden aus dem Munde ihrer Nachkommen. Denn ich kenne ihr Sinnen, womit sie schon heute umgehen, ehe ich sie in das Land bringe, von dem ich geschworen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Und Mose schrieb dieses Lied an selbigem Tage auf, und er lehrte es die Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Und er gebot Josua, dem Sohne Nuns, und sprach: Sei stark und mutig! Denn du, du sollst die Kinder Israel in das Land bringen, das ich ihnen zugeschworen habe; und ich will mit dir sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Und es geschah, als Mose geendigt hatte, die Worte dieses Gesetzes in ein Buch zu schreiben bis zu ihrem Schlusse,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'da gebot Mose den Leviten, welche die Lade des Bundes Jehovas trugen, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Nehmet dieses Buch des Gesetzes und leget es zur Seite der Lade des Bundes Jehovas, eures Gottes, daß es daselbst zum Zeugen gegen dich sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Denn ich kenne deine Widerspenstigkeit und deinen harten Nacken wohl. Siehe, während ich heute noch bei euch lebe, seid ihr widerspenstig gegen Jehova gewesen; und wieviel mehr nach meinem Tode!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Versammelt zu mir alle Ältesten eurer Stämme und eure Vorsteher, daß ich diese Worte vor ihren Ohren rede und den Himmel und die Erde gegen sie zu Zeugen nehme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Denn ich weiß, daß ihr euch nach meinem Tode ganz und gar verderben und von dem Wege abweichen werdet, den ich euch geboten habe; und es wird euch das Unglück begegnen am Ende der Tage, weil ihr tun werdet, was böse ist in den Augen Jehovas, ihn zu reizen durch das Werk eurer Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Und Mose redete vor den Ohren der ganzen Versammlung Israels die Worte dieses Liedes bis zu ihrem Schlusse:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Horchet, ihr Himmel, und ich will reden; und die Erde höre die Worte meines Mundes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Es träufle wie Regen meine Lehre, es fließe wie Tau meine Rede, wie Regenschauer auf das Gras und wie Regengüsse auf das Kraut!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Denn den Namen Jehovas will ich ausrufen: Gebet Majestät unserem Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Der Fels: Vollkommen ist sein Tun; denn alle seine Wege sind recht. Ein Gott der Treue und ohne Trug, gerecht und gerade ist er!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Es hat sich gegen ihn verderbt, nicht seiner Kinder ist ihr Schandfleck ein verkehrtes und verdrehtes Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Vergeltet ihr also Jehova, du törichtes und unweises Volk? Ist er nicht dein Vater, der dich erkauft hat? Er hat dich gemacht und dich bereitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Gedenke der Tage der Vorzeit, merket auf die Jahre von Geschlecht zu Geschlecht; frage deinen Vater, und er wird es dir kundtun, deine Ältesten, und sie werden es dir sagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Als der Höchste den Nationen das Erbe austeilte, als er voneinander schied die Menschenkinder, da stellte er fest die Grenzen der Völker nach der Zahl der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Denn Jehovas Teil ist sein Volk, Jakob die Schnur seines Erbteils.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Er fand ihn im Lande der Wüste und in der Öde, dem Geheul der Wildnis; er umgab ihn, gab acht auf ihn, er behütete ihn wie seinen Augapfel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Wie der Adler sein Nest aufstört, über seinen Jungen schwebt, seine Flügel ausbreitet, sie aufnimmt, sie trägt auf seinen Schwingen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'so leitete ihn Jehova allein, und kein fremder Gott war mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Er ließ ihn einherfahren auf den Höhen der Erde, und er aß den Ertrag des Feldes; und er ließ ihn Honig saugen aus dem Felsen und Öl aus dem Kieselfelsen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'geronnene Milch der Kühe und Milch der Schafe, samt dem Fette der Mastschafe und Widder, der Söhne Basans, und der Böcke, samt dem Nierenfett des Weizens; und der Traube Blut trankest du, feurigen Wein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Da ward Jeschurun fett und schlug aus; du wurdest fett, dick, feist! Und er verließ Gott, der ihn gemacht hatte, und verachtete den Fels seiner Rettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Sie reizten ihn zur Eifersucht durch fremde Götter, durch Greuel erbitterten sie ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Sie opferten den Dämonen, die Nicht-Gott sind, Göttern, die sie nicht kannten, neuen, die vor kurzem aufgekommen waren, die eure Väter nicht verehrten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Den Felsen, der dich gezeugt, vernachlässigtest du, und vergaßest den Gott, der dich geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Und Jehova sah es und verwarf sie, vor Unwillen über seine Söhne und seine Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Und er sprach: Ich will mein Angesicht vor ihnen verbergen, will sehen, was ihr Ende sein wird; denn ein Geschlecht voll Verkehrtheit sind sie, Kinder, in denen keine Treue ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Sie haben mich zur Eifersucht gereizt durch Nicht-Götter, haben mich erbittert durch ihre Nichtigkeiten; so will auch ich sie zur Eifersucht reizen durch ein Nicht-Volk, durch eine törichte Nation will ich sie erbittern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Denn ein Feuer ist entbrannt in meinem Zorn und wird brennen bis in den untersten Scheol, und es wird verzehren die Erde und ihren Ertrag und entzünden die Grundfesten der Berge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Ich werde Unglück über sie häufen, meine Pfeile wider sie verbrauchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Vergehen sie vor Hunger, und sind sie aufgezehrt von Fieberglut und giftiger Pest, so werde ich den Zahn wilder Tiere gegen sie senden, samt dem Gifte der im Staube Schleichenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Draußen wird das Schwert rauben, und in den Gemächern der Schrecken: den Jüngling wie die Jungfrau, den Säugling mit dem greisen Manne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Ich hätte gesagt: Ich will sie zerstreuen, ihrem Gedächtnis unter den Menschen ein Ende machen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Wenn ich die Kränkung von seiten des Feindes nicht fürchtete, daß ihre Widersacher es verkännten, daß sie sprächen: Unsere Hand war erhaben, und nicht Jehova hat dies alles getan!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Denn sie sind eine Nation, die allen Rat verloren hat; und kein Verständnis ist in ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Wenn sie weise wären, so würden sie dieses verstehen, ihr Ende bedenken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Wie könnte einer Tausend jagen, und zwei Zehntausend in die Flucht treiben, wäre es nicht, daß ihr Fels sie verkauft und Jehova sie preisgegeben hätte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Denn nicht wie unser Fels ist ihr Fels: Dessen sind unsere Feinde selbst Richter!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Denn von dem Weinstock Sodoms ist ihr Weinstock und von den Fluren Gomorras; ihre Beeren sind Giftbeeren, bitter sind ihre Trauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Gift der Drachen ist ihr Wein und grausames Gift der Nattern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Ist dieses nicht bei mir verborgen, versiegelt in meinen Schatzkammern?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Mein ist die Rache und die Vergeltung für die Zeit, da ihr Fuß wanken wird; denn nahe ist der Tag ihres Verderbens, und was ihnen bevorsteht, eilt herbei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Denn Jehova wird sein Volk richten, und er wird sich\'s gereuen lassen über seine Knechte, wenn er sehen wird, daß geschwunden die Kraft, und der Gebundene und der Freie dahin ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Und er wird sagen: Wo sind ihre Götter, der Fels, auf den sie vertrauten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'welche das Fett ihrer Schlachtopfer aßen, den Wein ihrer Trankopfer tranken? Sie mögen aufstehen und euch helfen, mögen ein Schirm über euch sein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Sehet nun, daß ich, ich bin, der da ist, und kein Gott neben mir! Ich töte, und ich mache lebendig, ich zerschlage, und ich heile; und niemand ist, der aus meiner Hand errettet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Denn ich erhebe zum Himmel meine Hand und spreche: Ich lebe ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Wenn ich mein blitzendes Schwert geschärft habe und meine Hand zum Gericht greift, so werde ich Rache erstatten meinen Feinden und Vergeltung geben meinen Hassern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Meine Pfeile werde ich berauschen mit Blut, und mein Schwert wird Fleisch fressen mit dem Blute der Erschlagenen und Gefangenen, von dem Haupte der Fürsten des Feindes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Jubelt, ihr Nationen, mit seinem Volke! Denn er wird rächen das Blut seiner Knechte und wird Rache erstatten seinen Feinden, und seinem Lande, seinem Volke, vergeben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Und Mose kam und redete alle Worte dieses Liedes vor den Ohren des Volkes, er und Hosea, der Sohn Nuns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Und als Mose alle diese Worte zu dem ganzen Israel ausgeredet hatte, da sprach er zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Richtet euer Herz auf alle die Worte, die ich euch heute bezeuge, damit ihr sie euren Kindern befehlet, daß sie darauf achten, alle Worte dieses Gesetzes zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Denn es ist nicht ein leeres Wort für euch, sondern es ist euer Leben; und durch dieses Wort werdet ihr eure Tage verlängern in dem Lande, wohin ihr über den Jordan ziehet, um es in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Und Jehova redete zu Mose an diesem selbigen Tage und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Steige auf dieses Gebirge Abarim, den Berg Nebo, der im Lande Moab liegt, der Jericho gegenüber ist, und sieh das Land Kanaan, das ich den Kindern Israel zum Eigentum gebe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'und du wirst sterben auf dem Berge, auf welchen du steigen wirst, und zu deinen Völkern versammelt werden; gleichwie dein Bruder Aaron auf dem Berge Hor gestorben ist und zu seinen Völkern versammelt wurde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'darum daß ihr treulos gegen mich gehandelt habt inmitten der Kinder Israel an dem Wasser von Meriba-Kades in der Wüste Zin, darum daß ihr mich nicht geheiligt habt inmitten der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Denn vor dir sollst du das Land sehen, aber du sollst nicht in das Land hineinkommen, das ich den Kindern Israel gebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Und dies ist der Segen, womit Mose, der Mann Gottes, die Kinder Israel vor seinem Tode gesegnet hat. Und er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Jehova ist vom Sinai hergekommen und ist ihnen aufgegangen von Seir; er ist hervorgestrahlt von dem Berge Paran und ist gekommen von heiligen Myriaden. Aus seiner Rechten ging Gesetzesfeuer für sie hervor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Ja, er liebt die Völker; alle seine Heiligen sind in deiner Hand; und sie lagern zu deinen Füßen, ein jeder empfängt von deinen Worten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Ein Gesetz hat uns Mose geboten, ein Erbe der Versammlung Jakobs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Und er ward König in Jeschurun, als sich versammelten die Häupter des Volkes, die Stämme Israels allzumal. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Ruben lebe und sterbe nicht, und seiner Männer sei eine Zahl!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Und dieses von Juda; und er sprach: Höre, Jehova, die Stimme Judas und bringe ihn zu seinem Volke; seine Hände seien mächtig für ihn, und hilf ihm von seinen Bedrängern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Und von Levi sprach er: Deine Thummim und deine Urim sind für deinen Frommen, den du versucht hast zu Massa, mit dem du hadertest bei dem Wasser von Meriba;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'der von seinem Vater und von seiner Mutter sprach: Ich sehe ihn nicht; und der seine Brüder nicht kannte und von seinen Söhnen nichts wußte. Denn sie haben dein Wort beobachtet, und deinen Bund bewahrten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Sie werden Jakob lehren deine Rechte, und Israel dein Gesetz; sie werden Weihrauch legen vor deine Nase und Ganzopfer auf deinen Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Segne, Jehova, sein Vermögen, und das Werk seiner Hände laß dir wohlgefallen; zerschmettere die Lenden derer, die sich wider ihn erheben, und seiner Hasser, daß sie nicht mehr aufstehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Von Benjamin sprach er: Der Liebling Jehovas! In Sicherheit wird er bei ihm wohnen; er beschirmt ihn den ganzen Tag, und zwischen seinen Schultern wohnt er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Und von Joseph sprach er: Gesegnet von Jehova sei sein Land, vom Köstlichsten des Himmels, vom Tau, und von der Tiefe, die unten lagert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'und vom Köstlichsten der Erträge der Sonne und vom Köstlichsten der Triebe der Monde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'und vom Vorzüglichsten der Berge der Urzeit und vom Köstlichsten der ewigen Hügel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'und vom Köstlichsten der Erde und ihrer Fülle; und das Wohlgefallen dessen, der im Dornbusch wohnte: Es komme auf das Haupt Josephs und auf den Scheitel des Abgesonderten unter seinen Brüdern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Sein ist die Majestät des Erstgeborenen seines Stieres; und Hörner des Wildochsen sind seine Hörner. Mit ihnen wird er die Völker niederstoßen allzumal bis an die Enden der Erde. Und das sind die Zehntausende Ephraims, und das die Tausende Manasses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Und von Sebulon sprach er: Freue dich, Sebulon, deines Auszugs, und du, Issaschar, deiner Zelte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Sie werden Völker zum Berge laden; daselbst werden sie Opfer der Gerechtigkeit opfern; denn sie werden saugen die Fülle der Meere und die verborgenen Schätze des Sandes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Und von Gad sprach er: Gesegnet sei, der Gad Raum schafft! Wie eine Löwin lagert er und zerreißt Arm und Scheitel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Und er hat das Erste des Landes sich ersehen, denn dort war der Anteil des Gesetzgebers aufbewahrt; und er ist an der Spitze des Volkes gezogen, hat ausgeführt die Gerechtigkeit Jehovas und seine Gerichte mit Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Und von Dan sprach er: Dan ist ein junger Löwe, der hervorspringt aus Basan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Und von Naphtali sprach er: Naphtali, gesättigt mit Huld und voll des Segens Jehovas! Westen und Süden nimm in Besitz!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Und von Aser sprach er: Gesegnet an Söhnen sei Aser; er sei wohlgefällig seinen Brüdern, und er tauche in Öl seinen Fuß!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Eisen und Erz seien deine Riegel, und wie deine Tage, so deine Kraft!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Keiner ist wie der Gott Jeschuruns, der auf den Himmeln einherfährt zu deiner Hilfe, und in seiner Hoheit auf den Wolken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Deine Wohnung ist der Gott der Urzeit, und unter dir sind ewige Arme; und er vertreibt vor dir den Feind und spricht: Vertilge!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Und Israel wohnt sicher, abgesondert der Quell Jakobs, in einem Lande von Korn und Most; und sein Himmel träufelt Tau.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Glückselig bist du, Israel! Wer ist wie du, ein Volk, gerettet durch Jehova, den Schild deiner Hilfe, und der das Schwert deiner Hoheit ist? Und es werden dir schmeicheln deine Feinde, und du, du wirst einherschreiten auf ihren Höhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Und Mose stieg von den Ebenen Moabs auf den Berg Nebo, den Gipfel des Pisga, der Jericho gegenüber ist. Und Jehova ließ ihn das ganze Land sehen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'Das Gilead bis Dan, und das ganze Naphtali und das Land Ephraim und Manasse, und das ganze Land Juda bis zum hinteren Meere;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'und den Süden und den Jordankreis, die Niederung von Jericho, der Palmenstadt, bis Zoar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Und Jehova sprach zu ihm: Das ist das Land, welches ich Abraham, Isaak und Jakob zugeschworen habe, indem ich sprach: Deinem Samen will ich es geben. Ich habe es dich mit deinen Augen sehen lassen, aber du sollst nicht hinübergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Und Mose, der Knecht Jehovas, starb daselbst im Lande Moab, nach dem Worte Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Und er begrub ihn im Tale, im Lande Moab, Beth-Peor gegenüber; und niemand weiß sein Grab bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Und Mose war hundertzwanzig Jahre alt, als er starb; sein Auge war nicht schwach geworden, und seine Kraft nicht geschwunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Und die Kinder Israel beweinten Mose in den Ebenen Moabs dreißig Tage lang; und es wurden die Tage des Weinens der Trauer um Mose vollendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Und Josua, der Sohn Nuns, war erfüllt mit dem Geiste der Weisheit; denn Mose hatte seine Hände auf ihn gelegt; und die Kinder Israel gehorchten ihm und taten, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Und es stand in Israel kein Prophet mehr auf wie Mose, welchen Jehova gekannt hätte von Angesicht zu Angesicht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'nach all den Zeichen und Wundern, die Jehova ihn gesandt hatte zu tun im Lande Ägypten, an dem Pharao und an allen seinen Knechten und an seinem ganzen Lande;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'und nach all der starken Hand und nach all dem Großen und Furchtbaren, das Mose vor den Augen des ganzen Israel getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Und es geschah nach dem Tode Moses, des Knechtes Jehovas, da sprach Jehova zu Josua, dem Sohne Nuns, dem Diener Moses, und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Mein Knecht Mose ist gestorben; und nun, mache dich auf, gehe über diesen Jordan, du und dieses ganze Volk, in das Land, das ich ihnen, den Kindern Israel, gebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Jeden Ort, auf den eure Fußsohle treten wird, euch habe ich ihn gegeben, so wie ich zu Mose geredet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Von der Wüste und diesem Libanon bis zum großen Strome, dem Strome Phrat, das ganze Land der Hethiter, und bis zum großen Meere gegen Sonnenuntergang, soll eure Grenze sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Es soll niemand vor dir bestehen alle Tage deines Lebens: so, wie ich mit Mose gewesen bin, werde ich mit dir sein; ich werde dich nicht versäumen und dich nicht verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Sei stark und mutig! Denn du, du sollst diesem Volke das Land als Erbe austeilen, das ich ihren Vätern geschworen habe, ihnen zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Nur sei sehr stark und mutig, daß du darauf achtest, zu tun nach dem ganzen Gesetz, welches mein Knecht Mose dir geboten hat. Weiche nicht davon ab zur Rechten noch zur Linken, auf daß es dir gelinge überall, wohin du gehst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Dieses Buch des Gesetzes soll nicht von deinem Munde weichen, und du sollst darüber sinnen Tag und Nacht, auf daß du darauf achtest, zu tun nach allem, was darin geschrieben ist; denn alsdann wirst du auf deinem Wege Erfolg haben, und alsdann wird es dir gelingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Habe ich dir nicht geboten: Sei stark und mutig? Erschrick nicht und fürchte dich nicht! Denn Jehova, dein Gott, ist mit dir überall, wohin du gehst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Und Josua gebot den Vorstehern des Volkes und sprach: Gehet mitten durch das Lager und gebietet dem Volke und sprechet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Bereitet euch Zehrung; denn in noch drei Tagen werdet ihr über diesen Jordan ziehen, um hinzukommen, das Land in Besitz zu nehmen, welches Jehova, euer Gott, euch gibt, es zu besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Und zu den Rubenitern und zu den Gaditern und zu dem halben Stamme Manasse sprach Josua und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Gedenket des Wortes, das Mose, der Knecht Jehovas, euch geboten hat, indem er sprach: Jehova, euer Gott, schafft euch Ruhe und gibt euch dieses Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Eure Weiber, eure Kinder und euer Vieh sollen in dem Lande bleiben, das Mose euch diesseit des Jordan gegeben hat; ihr aber, alle streitbaren Männer, sollt gerüstet vor euren Brüdern hinüberziehen und ihnen helfen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'bis Jehova euren Brüdern Ruhe schaft wie euch, und auch sie das Land besitzen, welches Jehova, euer Gott, ihnen gibt. Dann sollt ihr in das Land eures Besitztums zurückkehren und es besitzen, welches Mose, der Knecht Jehovas, euch gegeben hat, diesseit des Jordan, gegen Sonnenaufgang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Und sie antworteten Josua und sprachen: Alles, was du uns geboten hast, wollen wir tun, und wohin irgend du uns senden wirst, wollen wir gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Nach allem wie wir Mose gehorcht haben, also wollen wir dir gehorchen. Nur möge Jehova, dein Gott, mit dir sein, wie er mit Mose gewesen ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Jedermann, der deinem Befehle widerspenstig ist und nicht auf deine Worte hört in allem, was du uns gebietest, soll getötet werden. Nur sei stark und mutig!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Und Josua, der Sohn Nuns, sandte von Sittim heimlich zwei Männer als Kundschafter aus und sprach: Gehet, besehet das Land und Jericho. Und sie gingen hin und kamen in das Haus einer Hure, namens Rahab; und sie legten sich daselbst nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Und es wurde dem König von Jericho berichtet und gesagt: Siehe, es sind in dieser Nacht Männer von den Kindern Israel hierhergekommen, um das Land zu erforschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Da sandte der König von Jericho zu Rahab und ließ ihr sagen: Führe die Männer heraus, die zu dir gekommen, die in dein Haus eingekehrt sind; denn sie sind gekommen, um das ganze Land zu erforschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Das Weib aber nahm die zwei Männer und verbarg sie. Und sie sprach: Allerdings sind die Männer zu mir gekommen, aber ich wußte nicht, woher sie waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'und als das Tor beim Dunkelwerden geschlossen werden sollte, da gingen die Männer hinaus; ich weiß nicht, wohin die Männer gegangen sind. Jaget ihnen eilends nach, denn ihr werdet sie erreichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Sie hatte sie aber auf das Dach hinaufgeführt und unter Flachsstengel versteckt, die sie sich auf dem Dache aufgeschichtet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Und die Männer jagten ihnen nach, des Weges zum Jordan, nach den Furten hin; und man schloß das Tor, sobald die, welche ihnen nachjagten, hinaus waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Und ehe sie sich niederlegten, stieg sie zu ihnen auf das Dach hinauf');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'und sprach zu den Männern: Ich weiß, daß Jehova euch das Land gegeben hat, und daß euer Schrecken auf uns gefallen ist, und daß alle Bewohner des Landes vor euch verzagt sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Denn wir haben gehört, daß Jehova die Wasser des Schilfmeeres vor euch ausgetrocknet hat, als ihr aus Ägypten zoget, und was ihr den beiden Königen der Amoriter getan, die jenseit des Jordan waren, dem Sihon und dem Og, die ihr verbannt habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Und wir hörten es, und unser Herz zerschmolz, und es blieb kein Mut mehr vor euch in irgend einem Menschen; denn Jehova, euer Gott, ist Gott im Himmel oben und auf der Erde unten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Und nun schwöret mir doch bei Jehova, weil ich Güte an euch erwiesen habe, daß auch ihr an meines Vaters Hause Güte erweisen werdet; und gebet mir ein zuverlässiges Zeichen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'und lasset meinen Vater und meine Mutter und meine Brüder und meine Schwestern und alle ihre Angehörigen am Leben und errettet unsere Seelen vom Tode!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Und die Männer sprachen zu ihr: Unsere Seele soll an eurer Statt sterben, wenn ihr diese unsere Sache nicht verratet; und es soll geschehen, wenn Jehova uns das Land gibt, so werden wir Güte und Treue an dir erweisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Da ließ sie sie an einem Seile durch das Fenster hinunter; denn ihr Haus war in der Stadtmauer, und sie wohnte in der Stadtmauer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Und sie sprach zu ihnen: Gehet in das Gebirge, damit die Nachjagenden euch nicht treffen; und verberget euch daselbst drei Tage, bis die Nachjagenden zurückgekehrt sind, und danach gehet eures Weges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Und die Männer sprachen zu ihr: Wir werden dieses deines Eides ledig sein, den du uns hast schwören lassen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Siehe, wenn wir in das Land kommen, so sollst du diese Schnur von Karmesinfaden in das Fenster binden, durch welches du uns heruntergelassen hast, und sollst deinen Vater und deine Mutter und deine Brüder und das ganze Haus deines Vaters zu dir ins Haus versammeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'und es soll geschehen, wer irgend aus der Tür deines Hauses auf die Straße gehen wird, dessen Blut sei auf seinem Haupte, und wir werden unseres Eides ledig sein. Jeder aber, der bei dir im Hause sein wird, dessen Blut sei auf unserem Haupte, wenn Hand an ihn gelegt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Und wenn du diese unsere Sache verrätst, so werden wir deines Eides ledig sein, den du uns hast schwören lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Und sie sprach: Nach euren Worten, also sei es! Und sie entließ sie, und sie gingen weg. Und sie band die Karmesinschnur ins Fenster.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Und sie gingen weg und kamen in das Gebirge und blieben daselbst drei Tage, bis die Nachjagenden zurückgekehrt waren. Und die Nachjagenden suchten sie auf dem ganzen Wege und fanden sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Und die beiden Männer kehrten zurück und stiegen von dem Gebirge herab, und sie gingen hinüber und kamen zu Josua, dem Sohne Nuns; und sie erzählten ihm alles, was ihnen begegnet war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Und sie sprachen zu Josua: Jehova hat das ganze Land in unsere Hand gegeben, und auch sind alle Bewohner des Landes vor uns verzagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Da machte sich Josua des Morgens früh auf, und sie brachen auf von Sittim und kamen an den Jordan, er und alle Kinder Israel; und sie rasteten daselbst, ehe sie hinüberzogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Und es geschah am Ende von drei Tagen, da gingen die Vorsteher mitten durch das Lager,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'und sie geboten dem Volke und sprachen: Sobald ihr die Lade des Bundes Jehovas, eures Gottes, sehet, und die Priester, die Leviten, sie tragen, dann sollt ihr von eurem Orte aufbrechen und ihr nachfolgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Doch soll zwischen euch und ihr eine Entfernung sein bei zweitausend Ellen an Maß. Ihr sollt ihr nicht nahen, auf daß ihr den Weg wisset, auf dem ihr gehen sollt; denn ihr seid des Weges früher nicht gezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Und Josua sprach zu dem Volke: Heiliget euch; denn morgen wird Jehova in eurer Mitte Wunder tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Und Josua sprach zu den Priestern und sagte: Nehmet die Lade des Bundes auf und ziehet vor dem Volke hinüber. Und sie nahmen die Lade des Bundes auf und zogen vor dem Volke her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Und Jehova sprach zu Josua: An diesem Tage will ich beginnen, dich in den Augen von ganz Israel groß zu machen, damit sie wissen, daß, so wie ich mit Mose gewesen bin, ich mit dir sein werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Und du sollst den Priestern, welche die Lade des Bundes tragen, gebieten und sprechen: Wenn ihr an den Rand des Wassers des Jordan kommet, so bleibet im Jordan stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Und Josua sprach zu den Kindern Israel: Tretet herzu und höret die Worte Jehovas, eures Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Und Josua sprach: Hieran sollt ihr wissen, daß der lebendige Gott in eurer Mitte ist, und daß er die Kanaaniter und die Hethiter und die Hewiter und die Perisiter und die Girgasiter und die Amoriter und die Jebusiter gewißlich vor euch austreiben wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Siehe, die Lade des Bundes des Herrn der ganzen Erde zieht vor euch her in den Jordan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Und nun nehmet euch zwölf Männer aus den Stämmen Israels, je einen Mann für den Stamm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Und es wird geschehen, wenn die Fußsohlen der Priester, welche die Lade Jehovas, des Herrn der ganzen Erde, tragen, in den Wassern des Jordan ruhen, so werden die Wasser des Jordan, die von oben herabfließenden Wasser, abgeschnitten werden, und sie werden stehen bleiben wie ein Damm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Und es geschah, als das Volk aus seinen Zelten aufbrach, um über den Jordan zu ziehen, indem die Priester die Lade des Bundes vor dem Volke hertrugen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'und sobald die Träger der Lade an den Jordan kamen, und die Füße der Priester, welche die Lade trugen, in den Rand des Wassers tauchten, der Jordan aber ist voll über alle seine Ufer die ganze Zeit der Ernte hindurch, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'da blieben die von oben herabfließenden Wasser stehen; sie richteten sich auf wie ein Damm, sehr fern, bei Adam, der Stadt, die seitwärts von Zarethan liegt; und die nach dem Meere der Ebene, dem Salzmeere, hinabfließenden wurden völlig abgeschnitten. Und das Volk zog hindurch, Jericho gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Und die Priester, welche die Lade des Bundes Jehovas trugen, standen festen Fußes auf dem Trockenen in der Mitte des Jordan; und ganz Israel zog auf dem Trockenen hinüber, bis die ganze Nation vollends über den Jordan gegangen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Und es geschah, als die ganze Nation vollends über den Jordan gezogen war, da sprach Jehova zu Josua und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Nehmet euch aus dem Volke zwölf Männer, je einen Mann aus einem Stamme,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'und gebietet ihnen und sprechet: Hebet euch auf von hier, aus der Mitte des Jordan, von dem Standorte, wo die Füße der Priester festgestanden haben, zwölf Steine; und bringet sie mit euch hinüber und leget sie nieder in dem Nachtlager, wo ihr diese Nacht übernachten werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Und Josua rief die zwölf Männer, die er aus den Kindern Israel bestellt hatte, je einen Mann aus einem Stamme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'Und Josua sprach zu ihnen: Gehet hinüber, vor die Lade Jehovas, eures Gottes, in die Mitte des Jordan, und hebet euch ein jeder einen Stein auf seine Schulter, nach der Zahl der Stämme der Kinder Israel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'damit dies ein Zeichen unter euch sei. Wenn eure Kinder künftig fragen und sprechen: Was bedeuten euch diese Steine? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'so sollt ihr zu ihnen sagen: Daß die Wasser des Jordan vor der Lade des Bundes Jehovas abgeschnitten wurden; als sie durch den Jordan ging, wurden die Wasser des Jordan abgeschnitten. Und diese Steine sollen für die Kinder Israel zum Gedächtnis sein ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Und die Kinder Israel taten also, wie Josua geboten hatte, und hoben zwölf Steine auf aus der Mitte des Jordan, so wie Jehova zu Josua geredet hatte, nach der Zahl der Stämme der Kinder Israel; und sie brachten sie mit sich in das Nachtlager hinüber und legten sie daselbst nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Und zwölf Steine richtete Josua auf in der Mitte des Jordan, an der Stelle, wo die Füße der Priester gestanden hatten, welche die Lade des Bundes trugen; und sie sind daselbst bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Und die Priester, welche die Lade trugen, blieben in der Mitte des Jordan stehen, bis alles vollendet war, was Jehova dem Josua geboten hatte, zu dem Volke zu reden, nach allem was Mose dem Josua geboten hatte. Und das Volk eilte und zog hinüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Und es geschah, als das ganze Volk vollends hinübergezogen war, da zogen die Lade Jehovas und die Priester angesichts des Volkes hinüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Und die Kinder Ruben und die Kinder Gad und der halbe Stamm Manasse zogen gerüstet vor den Kindern Israel her, wie Mose zu ihnen geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Bei vierzigtausend zum Heere Gerüstete zogen sie vor Jehova her zum Streit in die Ebenen von Jericho.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'An selbigem Tage machte Jehova den Josua groß in den Augen von ganz Israel; und sie fürchteten ihn, wie sie Mose gefürchtet hatten, alle Tage seines Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Und Jehova sprach zu Josua und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Gebiete den Priestern, welche die Lade des Zeugnisses tragen, daß sie aus dem Jordan heraufsteigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Und Josua gebot den Priestern und sprach: Steiget aus dem Jordan herauf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Und es geschah, als die Priester, welche die Lade des Bundes Jehovas trugen, aus der Mitte des Jordan heraufstiegen, als die Fußsohlen der Priester sich abgerissen hatten auf das Trockene, da kehrten die Wasser des Jordan an ihren Ort zurück, und sie flossen wie früher über alle seine Ufer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Und das Volk stieg aus dem Jordan herauf am Zehnten des ersten Monats; und sie lagerten sich in Gilgal an der Ostgrenze von Jericho.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Und jene zwölf Steine, die sie aus dem Jordan genommen hatten, richtete Josua zu Gilgal auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Und er sprach zu den Kindern Israel und sagte: Wenn eure Kinder künftig ihre Väter fragen und sprechen: Was bedeuten diese Steine? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'so sollt ihr es euren Kindern kundtun und sprechen: Auf trockenem Boden ist Israel durch diesen Jordan gezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Denn Jehova, euer Gott, hat die Wasser des Jordan vor euch ausgetrocknet, bis ihr hinübergezogen waret, so wie Jehova, euer Gott, mit dem Schilfmeere tat, das er vor uns austrocknete, bis wir hinübergezogen waren:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'damit alle Völker der Erde die Hand Jehovas erkennten, daß sie stark ist; damit ihr Jehova, euren Gott, fürchtet alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Und es geschah, als alle Könige der Amoriter, die diesseit des Jordan westwärts, und alle Könige der Kanaaniter, die am Meere waren, hörten, daß Jehova die Wasser des Jordan vor den Kindern Israel ausgetrocknet hatte, bis wir hinübergezogen waren, da zerschmolz ihr Herz, und es war kein Mut mehr in ihnen vor den Kindern Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'In selbiger Zeit sprach Jehova zu Josua: Mache dir Steinmesser und beschneide wiederum die Kinder Israel zum zweiten Male.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Und Josua machte sich Steinmesser und beschnitt die Kinder Israel am Hügel Araloth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Und dies ist die Sache, warum Josua sie beschnitt: Das ganze Volk, das aus Ägypten gezogen war, die Männlichen, alle Kriegsleute, waren in der Wüste gestorben, auf dem Wege, als sie aus Ägypten zogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Denn das ganze Volk, welches auszog, war beschnitten; aber das ganze Volk, das in der Wüste geboren war, auf dem Wege, als sie aus Ägypten zogen, hatte man nicht beschnitten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Denn die Kinder Israel wanderten vierzig Jahre in der Wüste, bis die ganze Nation der Kriegsleute, die aus Ägypten gezogen, aufgerieben war, welche nicht gehört hatten auf die Stimme Jehovas, denen Jehova geschworen hatte, sie das Land nicht sehen zu lassen, welches Jehova ihren Vätern geschworen hatte, uns zu geben, ein Land, das von Milch und Honig fließt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Und ihre Söhne, die er an ihrer Statt aufkommen ließ, diese beschnitt Josua; denn sie hatten Vorhaut, weil man sie auf dem Wege nicht beschnitten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Und es geschah, als die ganze Nation vollends beschnitten war, da blieben sie an ihrem Orte im Lager, bis sie heil waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Und Jehova sprach zu Josua: Heute habe ich die Schande Ägyptens von euch abgewälzt. Und man gab selbigem Orte den Namen Gilgal bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Und die Kinder Israel lagerten in Gilgal; und sie feierten das Passah am vierzehnten Tage des Monats, am Abend, in den Ebenen von Jericho.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Und sie aßen am anderen Tage nach dem Passah von dem Erzeugnis des Landes, ungesäuertes Brot und geröstete Körner, an diesem selbigen Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Und das Man hörte auf am anderen Tage, als sie von dem Erzeugnis des Landes aßen, und es gab für die Kinder Israel kein Man mehr; und sie aßen von dem Ertrage des Landes Kanaan in jenem Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Und es geschah, als Josua bei Jericho war, da erhob er seine Augen auf und sah: und siehe, ein Mann stand vor ihm, und sein Schwert gezückt in seiner Hand. Und Josua ging auf ihn zu und sprach zu ihm: Bist du für uns oder für unsere Feinde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Und er sprach: Nein, sondern als der Oberste des Heeres Jehovas bin ich jetzt gekommen. Da fiel Josua auf sein Angesicht zur Erde und huldigte ihm und sprach zu ihm: Was redet mein Herr zu seinem Knechte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Und der Oberste des Heeres Jehovas sprach zu Josua: Ziehe deinen Schuh aus von deinem Fuße; denn der Ort, auf dem du stehst, ist heilig! Und Josua tat also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Und Jericho hatte seine Tore geschlossen und war verriegelt vor den Kindern Israel; niemand ging aus, und niemand ging ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Und Jehova sprach zu Josua: Siehe, ich habe Jericho und seinen König und die streitbaren Männer in deine Hand gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Und ihr sollt die Stadt umziehen, alle Kriegsleute, einmal rings um die Stadt her; also sollst du sechs Tage tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Und sieben Priester sollen sieben Hallposaunen vor der Lade hertragen. Und am siebten Tage sollt ihr die Stadt siebenmal umziehen, und die Priester sollen in die Posaunen stoßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Und es soll geschehen, wenn man das Lärmhorn anhaltend bläst, wenn ihr den Schall der Posaune höret, so soll das ganze Volk ein großes Geschrei erheben; und die Mauer der Stadt wird an ihrer Stelle einstürzen, und das Volk soll hinaufsteigen, ein jeder gerade vor sich hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Und Josua, der Sohn Nuns, rief die Priester und sprach zu ihnen: Nehmet die Lade des Bundes auf, und sieben Priester sollen sieben Hallposaunen vor der Lade Jehovas hertragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Und er sprach zu dem Volke: Gehet hin und umziehet die Stadt; und die Gerüsteten sollen vor der Lade Jehovas hergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Und es geschah, als Josua zu dem Volke geredet hatte, da zogen die sieben Priester hin, welche die sieben Hallposaunen vor Jehova hertrugen, und stießen in die Posaunen; und die Lade des Bundes Jehovas folgte hinter ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Und die Gerüsteten zogen vor den Priestern her, welche in die Posaunen stießen, und der Nachzug ging hinter der Lade her, indem sie fort und fort in die Posaunen stießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Und Josua hatte dem Volke geboten und gesagt: Ihr sollt kein Geschrei erheben und eure Stimme nicht hören lassen, und kein Wort soll aus eurem Munde gehen; bis zu dem Tage, da ich zu euch sage: Erhebet ein Geschrei! Dann sollt ihr ein Geschrei erheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Und die Lade Jehovas umzog die Stadt, einmal rings um sie her; und sie kamen in das Lager und übernachteten im Lager.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Und Josua machte sich des Morgens früh auf, und die Priester trugen die Lade Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Und die sieben Priester, welche die sieben Hallposaunen vor der Lade Jehovas hertrugen, gingen fort und fort und stießen in die Posaunen; und die Gerüsteten zogen vor ihnen her, und der Nachzug ging hinter der Lade Jehovas her, indem sie fort und fort in die Posaunen stießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Und sie umzogen die Stadt am zweiten Tage einmal und kehrten in das Lager zurück. Also taten sie sechs Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Und es geschah am siebten Tage, da machten sie sich früh auf, beim Aufgang der Morgenröte, und umzogen die Stadt nach dieser Weise siebenmal; nur an selbigem Tage umzogen sie die Stadt siebenmal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Und es geschah beim siebten Male, als die Priester in die Posaunen stießen, da sprach Josua zu dem Volke: Erhebet ein Geschrei! Denn Jehova hat euch die Stadt gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Und sie Stadt, sie und alles, was darin ist, soll dem Jehova ein Bann sein; nur Rahab, die Hure, soll am Leben bleiben, sie und alle, die bei ihr im Hause sind, weil sie die Boten versteckt hat, die wir ausgesandt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Ihr aber, hütet euch nur vor dem Verbannten, damit ihr nicht verbannet und doch von dem Verbannten nehmet und das Lager Israels zum Banne machet und es in Trübsal bringet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Und alles Silber und Gold, samt den ehernen und eisernen Geräten, soll Jehova heilig sein: in den Schatz Jehovas soll es kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Und das Volk erhob ein Geschrei, und sie stießen in die Posaunen. Und es geschah, als das Volk den Schall der Posaunen hörte, und als das Volk ein großes Geschrei erhob, da stürzte die Mauer an ihrer Stelle ein, und das Volk stieg in die Stadt hinein, ein jeder gerade vor sich hin, und sie nahmen die Stadt ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Und sie verbannten alles, was in der Stadt war, vom Manne bis zum Weibe, vom Knaben bis zum Greise, und bis zu den Rindern und Schafen und Eseln, mit der Schärfe des Schwertes. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Und Josua sprach zu den beiden Männern, die das Land ausgekundschaftet hatten: Gehet in das Haus der Hure, und führet das Weib und alle ihre Angehörigen von dannen heraus, wie ihr es ihr geschworen habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Da gingen die Jünglinge, die Kundschafter, hinein und führten Rahab und ihren Vater und ihre Mutter und ihre Brüder und alle ihre Angehörigen hinaus: alle ihre Geschlechter führten sie hinaus; und sie ließen sie außerhalb des Lagers Israels. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Und die Stadt und alles, was darin war, verbrannten sie mit Feuer; nur das Silber und das Gold und die ehernen und die eisernen Geräte legten sie in den Schatz des Hauses Jehovas. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'So ließ Josua Rahab, die Hure, und das Haus ihres Vaters und alle ihre Angehörigen am Leben; und sie hat in der Mitte Israels gewohnt bis auf diesen Tag, weil sie die Boten versteckte, welche Josua abgesandt hatte, um Jericho auszukundschaften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Und Josua schwur in selbiger Zeit und sprach: Verflucht vor Jehova sei der Mann, der sich aufmachen und diese Stadt Jericho bauen wird! Mit seinem Erstgeborenen wird er ihren Grund legen und mit seinem Jüngsten ihre Tore aufstellen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Und Jehova war mit Josua, und sein Ruf verbreitete sich durch das ganze Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Und die Kinder Israel begingen Untreue an dem Verbannten; und Achan, der Sohn Karmis, des Sohnes Sabdis, des Sohnes Serachs, vom Stamme Juda, nahm von dem Verbannten; und der Zorn Jehovas entbrannte wider die Kinder Israel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Und Josua sandte Männer von Jericho nach Ai, das bei Beth-Awen, östlich von Bethel, liegt, und sprach zu ihnen und sagte: Gehet hinauf und kundschaftet das Land aus. Und die Männer gingen hinauf und kundschafteten Ai aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Und sie kehrten zu Josua zurück und sprachen zu ihm: Es ziehe nicht das ganze Volk hinauf; bei zweitausend Mann oder bei dreitausend Mann mögen hinaufziehen und Ai schlagen; bemühe nicht das ganze Volk dahin, denn ihrer sind wenige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Da zogen von dem Volke bei dreitausend Mann dort hinauf; aber sie flohen vor den Männern von Ai;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'und die Männer von Ai erschlugen von ihnen bei sechsunddreißig Mann, und sie jagten ihnen nach vor dem Tore bis Schebarim und schlugen sie am Abhange. Da zerschmolz das Herz des Volkes und wurde wie Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Und Josua zerriß seine Kleider und fiel vor der Lade Jehovas auf sein Angesicht zur Erde bis an den Abend, er und die Ältesten von Israel, und sie warfen Staub auf ihre Häupter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Und Josua sprach: Ach, Herr, Jehova! Warum hast du denn dieses Volk über den Jordan ziehen lassen, um uns in die Hand der Amoriter zu geben, uns zu Grunde zu richten? O hätten wir es uns doch gefallen lassen und wären jenseit des Jordan geblieben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Bitte, Herr, was soll ich sagen, nachdem Israel vor seinen Feinden den Rücken gekehrt hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Und hören es die Kanaaniter und alle Bewohner des Landes, so werden sie uns umzingeln und unseren Namen von der Erde ausrotten; und was wirst du für deinen großen Namen tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Da sprach Jehova zu Josua: Stehe auf! Warum liegst du denn auf deinem Angesicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israel hat gesündigt, und auch haben sie meinen Bund übertreten, den ich ihnen geboten habe; und auch haben sie von dem Verbannten genommen und auch gestohlen und es auch verheimlicht und es auch unter ihre Geräte gelegt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Und die Kinder Israel werden vor ihren Feinden nicht zu bestehen vermögen; sie werden vor ihren Feinden den Rücken kehren, denn sie sind zum Banne geworden. Ich werde nicht mehr mit euch sein, wenn ihr nicht den Bann aus eurer Mitte vertilget.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Stehe auf, heilige das Volk und sprich: Heiliget euch auf morgen; denn so spricht Jehova, der Gott Israels: Ein Bann ist in deiner Mitte, Israel; du wirst vor deinen Feinden nicht zu bestehen vermögen, bis ihr den Bann aus eurer Mitte hinwegtut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Und ihr sollt am Morgen herzutreten nach euren Stämmen; und es soll geschehen: der Stamm, welchen Jehova treffen wird, soll herzutreten nach den Geschlechtern; und das Geschlecht, welches Jehova treffen wird, soll herzutreten nach den Häusern; und das Haus, welches Jehova treffen wird, soll herzutreten nach den Männern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Und es soll geschehen: wer mit dem Banne getroffen wird, der soll mit Feuer verbrannt werden, er und alles, was er hat; denn er hat den Bund Jehovas übertreten und eine Schandtat in Israel begangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Und Josua machte sich des Morgens früh auf und ließ Israel herzutreten nach seinen Stämmen; und es ward getroffen der Stamm Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Und er ließ die Geschlechter Judas herzutreten; und er traf das Geschlecht der Sarchiter. Und er ließ das Geschlecht der Sarchiter herzutreten nach den Männern; und es ward getroffen Sabdi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Und er ließ sein Haus herzutreten nach den Männern; und es ward getroffen Achan, der Sohn Karmis, des Sohnes Sabdis, des Sohnes Serachs, vom Stamme Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Und Josua sprach zu Achan: Mein Sohn, gib doch Jehova, dem Gott Israels, Ehre und lege ihm ein Bekenntnis ab; und tue mir doch kund, was du getan hast; verhehle es mir nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Und Achan antwortete Josua und sprach: Fürwahr, ich habe gegen Jehova, den Gott Israels, gesündigt, und so, und so habe ich getan:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Ich sah unter der Beute einen schönen Mantel aus Sinear und zweihundert Sekel Silber und eine goldene Stange, fünfzig Sekel ihr Gewicht, und mich gelüstete danach, und ich nahm sie; und siehe, sie sind im Innern meines Zeltes in der Erde vergraben und das Silber darunter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Und Josua sandte Boten hin, und sie liefen zum Zelte; und siehe, er war in seinem Zelte vergraben und das Silber darunter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Und sie nahmen es aus dem Innern des Zeltes und brachten es zu Josua und zu allen Kindern Israel, und sie legten es vor Jehova hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Da nahm Josua, und ganz Israel mit ihm, Achan, den Sohn Serachs, und das Silber und den Mantel und die goldene Stange, und seine Söhne und seine Töchter, und seine Rinder und seine Esel und sein Kleinvieh, und sein Zelt und alles, was er hatte, und sie brachten sie hinauf in das Tal Achor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Und Josua sprach: Wie hast du uns in Trübsal gebracht! Jehova wird dich in Trübsal bringen an diesem Tage! Und ganz Israel steinigte ihn, und sie verbrannten sie mit Feuer und bewarfen sie mit Steinen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'und sie errichteten einen großen Steinhaufen über ihm, der bis auf diesen Tag da ist. Und Jehova wandte sich von der Glut seines Zornes. Darum gab man jenem Orte den Namen Tal Achor bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Und Jehova sprach zu Josua: Fürchte dich nicht und erschrick nicht! Nimm alles Kriegsvolk mit dir und mache dich auf, ziehe hinauf nach Ai. Siehe, ich habe den König von Ai und sein Volk und seine Stadt und sein Land in deine Hand gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Und du sollst an Ai und an seinem König tun, so wie du an Jericho und an seinem König getan hast; jedoch seine Beute und sein Vieh dürft ihr für euch plündern. Lege dir einen Hinterhalt gegen die Stadt, in ihren Rücken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Da machte sich Josua mit allem Kriegsvolk auf, um nach Ai hinaufzuziehen. Und Josua wählte dreißigtausend Mann aus, streitbare Männer, und sandte sie ab bei der Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Und er gebot ihnen und sprach: Sehet, ihr sollt den Hinterhalt bilden gegen die Stadt, im Rücken der Stadt; entfernet euch nicht allzuweit von der Stadt, sondern seid alle bereit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Und ich und alles Volk, das bei mir ist, wir wollen uns der Stadt nähern; und es soll geschehen, wenn sie herauskommen, uns entgegen, wie das erste Mal, so wollen wir vor ihnen fliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Und sie werden herausziehen hinter uns her, bis wir sie von der Stadt abgerissen haben; denn sie werden sagen: Sie fliehen vor uns wie das erste Mal! Und wir wollen vor ihnen fliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Dann sollt ihr euch aus dem Hinterhalt aufmachen und die Stadt in Besitz nehmen; und Jehova, euer Gott, wird sie in eure Hand geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Und es soll geschehen, wenn ihr die Stadt eingenommen habt, so sollt ihr die Stadt mit Feuer anzünden; nach dem Worte Jehovas sollt ihr tun. Sehet, ich habe es euch geboten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Und Josua sandte sie ab, und sie zogen in den Hinterhalt und hielten zwischen Bethel und Ai, westlich von Ai. Und Josua brachte jene Nacht in der Mitte des Volkes zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Und Josua machte sich des Morgens früh auf und musterte das Volk; und er zog hinauf, er und die Ältesten von Israel, vor dem Volke her nach Ai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Und alles Kriegsvolk, das bei ihm war, zog hinauf und rückte heran, und sie kamen der Stadt gegenüber; und sie lagerten sich nördlich von Ai, und das Tal war zwischen ihm und Ai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Er hatte aber bei fünftausend Mann genommen und sie als Hinterhalt zwischen Bethel und Ai gelegt, westlich von der Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Und so stellten sie das Volk auf, das ganze Lager, das nördlich von der Stadt war, und dessen Hinterhalt westlich von der Stadt; und Josua zog in selbiger Nacht mitten in das Tal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Und es geschah, als der König von Ai es sah, da eilten die Männer der Stadt und machten sich früh auf und zogen hinaus, Israel entgegen zum Streit, er und all sein Volk, an den bestimmten Ort, vor der Ebene. Er wußte aber nicht, daß ihm im Rücken der Stadt ein Hinterhalt gelegt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Und Josua und ganz Israel ließen sich vor ihnen schlagen und flohen des Weges zur Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Da wurde das ganze Volk, das in der Stadt war, zusammengerufen, um ihnen nachzujagen; und sie jagten Josua nach und wurden von der Stadt abgerissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Und es blieb kein Mann in Ai und Bethel übrig, der nicht hinter Israel her ausgezogen wäre; und sie ließen die Stadt offen und jagten Israel nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Da sprach Jehova zu Josua: Strecke den Spieß, der in deiner Hand ist, gegen Ai aus; denn ich will es in deine Hand geben. Und Josua streckte den Spieß, der in seiner Hand war, gegen die Stadt aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Und der Hinterhalt machte sich eilends von seinem Orte auf und lief, als er seine Hand ausstreckte, und sie kamen in die Stadt und nahmen sie ein; und sie eilten und zündeten die Stadt mit Feuer an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Und die Männer von Ai wandten sich um und sahen, und siehe, der Rauch der Stadt stieg gen Himmel empor; und sie hatten keine Kraft, dahin noch dorthin zu fliehen. Denn das Volk, das nach der Wüste hin geflohen war, wandte sich um gegen die Nachjagenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Denn als Josua und ganz Israel sahen, daß der Hinterhalt die Stadt eingenommen hatte und daß der Rauch der Stadt emporstieg, da kehrten sie um und schlugen die Männer von Ai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Jene aber zogen aus der Stadt ihnen entgegen, so daß sie mitten zwischen Israel waren, die einen von hierher und die anderen von dorther. Und sie schlugen sie, bis ihnen kein Entronnener oder Entkommener übrigblieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Und den König von Ai griffen sie lebendig und brachten ihn zu Josua.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Und es geschah, als Israel das Würgen aller Bewohner von Ai auf dem Felde, in der Wüste, wo sie ihnen nachgejagt waren, beendigt hatte, und sie alle durch die Schärfe des Schwertes gefallen, bis sie aufgerieben waren, da kehrte ganz Israel um nach Ai, und sie schlugen es mit der Schärfe des Schwertes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Und alle an selbigem Tage Gefallenen, sowohl Männer als Weiber, waren zwölftausend, alle Leute von Ai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Und Josua zog seine Hand, die er mit dem Spieße ausgestreckt hatte, nicht zurück, bis man alle Bewohner von Ai vertilgt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Nur das Vieh und die Beute jener Stadt plünderte Israel für sich, nach dem Worte Jehovas, das er dem Josua geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Und Josua verbrannte Ai und machte es zu einem ewigen Trümmerhaufen, bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Und den König von Ai ließ er an einen Baum hängen bis zur Abendzeit; und beim Untergang der Sonne gebot Josua, und sie nahmen seinen Leichnam von dem Baume herab und warfen ihn an den Eingang des Stadttores und errichteten einen großen Steinhaufen über ihm, der bis auf diesen Tag da ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Damals baute Josua dem Jehova, dem Gott Israels, einen Altar auf dem Berge Ebal,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'so wie Mose, der Knecht Jehovas, den Kindern Israel geboten hatte, wie im Buche des Gesetzes Moses geschrieben ist, einen Altar von ganzen Steinen, über die man kein Eisen geschwungen hatte. Und sie opferten darauf dem Jehova Brandopfer und schlachteten Friedensopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Und er schrieb daselbst auf die Steine eine Abschrift des Gesetzes Moses, welches er vor den Kindern Israel geschrieben hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Und ganz Israel und seine Ältesten und Vorsteher und seine Richter standen an dieser und an jener Seite der Lade, den Priestern, den Leviten, gegenüber, welche die Lade des Bundes Jehovas trugen, der Fremdling wie der Eingeborene, die eine Hälfte gegen den Berg Gerisim hin und die andere Hälfte gegen den Berg Ebal hin, wie Mose, der Knecht Jehovas, im Anfang geboten hatte, das Volk Israel zu segnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Und danach las er alle Worte des Gesetzes, den Segen und den Fluch, nach allem, was im Buche des Gesetzes geschrieben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Es war kein Wort von allem, was Mose geboten hatte, das Josua nicht der ganzen Versammlung Israels vorlas, samt den Weibern und den Kindern und dem Fremdling, der in ihrer Mitte wandelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Und es geschah, als alle die Könige es hörten, die diesseit des Jordan waren, auf dem Gebirge und in der Niederung und an der ganzen Küste des großen Meeres gegen den Libanon hin, die Hethiter und die Amoriter, die Kanaaniter, die Perisiter, die Hewiter und die Jebusiter:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'da versammelten sie sich allzumal, um einmütig wider Josua und wider Israel zu streiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Als aber die Bewohner von Gibeon hörten, was Josua an Jericho und an Ai getan hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'handelten sie auch ihrerseits mit List und gingen und stellten sich als Boten: sie nahmen abgenutzte Säcke für ihre Esel, und abgenutzte und geborstene und zusammengebundene Weinschläuche,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'und abgenutzte und geflickte Schuhe an ihre Füße, und abgenutzte Kleider auf sich; und alles Brot ihrer Zehrung war vertrocknet und war schimmlig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Und sie gingen zu Josua in das Lager nach Gilgal und sprachen zu ihm und zu den Männern von Israel: Aus fernem Lande sind wir gekommen, und nun machet einen Bund mit uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Aber die Männer von Israel sprachen zu dem Hewiter: Vielleicht wohnst du in meiner Mitte, und wie sollte ich einen Bund mit dir machen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Und sie sprachen zu Josua: Wir sind deine Knechte. Und Josua sprach zu ihnen: Wer seid ihr, und woher kommet ihr?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Und sie sprachen zu ihm: Aus sehr fernem Lande sind deine Knechte gekommen, um des Namens Jehovas, deines Gottes, willen; denn wir haben seinen Ruf gehört und alles, was er in Ägypten getan,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'und alles, was er den beiden Königen der Amoriter getan hat, die jenseit des Jordan waren, Sihon, dem König von Hesbon, und Og, dem König von Basan, der zu Astaroth wohnte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Da sprachen unsere Ältesten und alle Bewohner unseres Landes zu uns und sagten: Nehmet Zehrung mit euch auf den Weg und gehet ihnen entgegen, und sprechet zu ihnen: Wir sind eure Knechte; und nun machet einen Bund mit uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Dieses unser Brot, warm haben wir es aus unseren Häusern als Zehrung mitgenommen an dem Tage, da wir auszogen, um zu euch zu gehen; und nun siehe, es ist vertrocknet und schimmlig geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Und diese Weinschläuche, die wir neu gefüllt hatten, siehe da, sie sind geborsten; und diese unsere Kleider und unsere Schuhe sind abgenutzt infolge des sehr langen Weges. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Und die Männer nahmen von ihrer Zehrung; aber den Mund Jehovas befragten sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Und Josua machte Frieden mit ihnen und machte mit ihnen einen Bund, sie am Leben zu lassen; und die Fürsten der Gemeinde schwuren ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Und es geschah am Ende von drei Tagen, nachdem sie einen Bund mit ihnen gemacht hatten, da hörten sie, daß sie nahe bei ihnen waren und mitten unter ihnen wohnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Da brachen die Kinder Israel auf und kamen zu ihren Städten am dritten Tage; und ihre Städte waren Gibeon und Kephira und Beeroth und Kirjath-Jearim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Und die Kinder Israel schlugen sie nicht, weil die Fürsten der Gemeinde ihnen bei Jehova, dem Gott Israels, geschworen hatten. Da murrte die ganze Gemeinde wider die Fürsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Und alle Fürsten sprachen zu der ganzen Gemeinde: Wir haben ihnen bei Jehova, dem Gott Israels, geschworen, und nun können wir sie nicht antasten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Das wollen wir ihnen tun und sie am Leben lassen, damit nicht ein Zorn über uns komme wegen des Eides, den wir ihnen geschworen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Und die Fürsten sprachen zu ihnen: Sie sollen am Leben bleiben. Und sie wurden Holzhauer und Wasserschöpfer für die ganze Gemeinde, so wie die Fürsten betreffs ihrer geredet hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Und Josua rief sie und redete zu ihnen und sprach: Warum habt ihr uns betrogen und gesagt: Wir sind sehr weit von euch, da ihr doch mitten unter uns wohnet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Und nun, verflucht seid ihr; und nicht sollt ihr aufhören, Knechte zu sein, sowohl Holzhauer als Wasserschöpfer für das Haus meines Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Und sie antworteten Josua und sprachen: Weil deinen Knechten für gewiß berichtet wurde, daß Jehova, dein Gott, Mose, seinem Knechte, geboten hat, euch das ganze Land zu geben und alle Bewohner des Landes vor euch zu vertilgen, so fürchteten wir sehr für unser Leben euretwegen und taten diese Sache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Und nun siehe, wir sind in deiner Hand; tue, wie es gut und wie es recht ist in deinen Augen, uns zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Und er tat ihnen also und errettete sie von der Hand der Kinder Israel; und sie töteten sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Und Josua machte sie an jenem Tage zu Holzhauern und Wasserschöpfern für die Gemeinde und für den Altar Jehovas, bis auf diesen Tag, an dem Orte, den er erwählen würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Und es geschah, als Adoni-Zedek, der König von Jerusalem, hörte, daß Josua Ai eingenommen und vertilgt habe, daß er Ai und seinem König ebenso getan, wie er Jericho und seinem König getan hatte, und daß die Bewohner von Gibeon Frieden mit Israel gemacht hätten und in ihrer Mitte wären:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'da fürchteten sie sich sehr; denn Gibeon war eine große Stadt, wie eine der Königsstädte, und es war größer als Ai, und alle seine Männer waren Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Und Adoni-Zedek, der König von Jerusalem, sandte zu Hoham, dem König von Hebron, und zu Piream, dem König von Jarmuth, und zu Japhija, dem König von Lachis, und zu Debir, dem König von Eglon, und ließ ihnen sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Kommt zu mir herauf und helft mir, daß wir Gibeon schlagen; denn es hat mit Josua und mit den Kindern Israel Frieden gemacht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Da versammelten sich und zogen herauf die fünf Könige der Amoriter, der König von Jerusalem, der König von Hebron, der König von Jarmuth, der König von Lachis, der König von Eglon, sie und alle ihre Heerlager; und sie lagerten sich wider Gibeon und stritten wider dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Und die Männer von Gibeon sandten zu Josua in das Lager nach Gilgal und ließen ihm sagen: Ziehe deine Hände nicht ab von deinen Knechten; komm eilends zu uns herauf und rette uns und hilf uns; denn alle Könige der Amoriter, die das Gebirge bewohnen, haben sich wider uns versammelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Und Josua zog von Gilgal hinauf, er und alles Kriegsvolk mit ihm und alle streitbaren Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Und Jehova sprach zu Josua: Fürchte dich nicht vor ihnen, denn ich habe sie in deine Hand gegeben; kein Mann von ihnen wird vor dir standhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Und Josua kam plötzlich über sie; die ganze Nacht zog er von Gilgal hinauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Und Jehova verwirrte sie vor Israel; und er richtete eine große Niederlage unter ihnen an zu Gibeon und jagte ihnen nach auf dem Wege der Anhöhe von Beth-Horon und schlug sie bis Aseka und bis Makkeda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Und es geschah, als sie vor Israel flohen, sie stiegen hinunter von Beth-Horon da warf Jehova große Steine vom Himmel auf sie herab, bis Aseka, daß sie starben. Es waren derer, welche durch die Hagelsteine starben, mehr als derer, welche die Kinder Israel mit dem Schwerte töteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Damals redete Josua zu Jehova, an dem Tage, da Jehova die Amoriter vor den Kindern Israel dahingab, und sprach vor den Augen Israels: Sonne, stehe still zu Gibeon; und du, Mond, im Tale Ajjalon!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Und die Sonne stand still, und der Mond blieb stehen, bis die Nation sich an ihren Feinden gerächt hatte. (Ist das nicht geschrieben im Buche Jaschar?) Und die Sonne blieb mitten am Himmel stehen und eilte nicht zum Untergang, ungefähr einen ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Und es war kein Tag wie dieser, vor ihm und nach ihm, daß Jehova auf die Stimme eines Menschen gehört hätte; denn Jehova stritt für Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Und Josua, und ganz Israel mit ihm, kehrte in das Lager nach Gilgal zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Jene fünf Könige aber flohen und versteckten sich in der Höhle zu Makkeda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Und es wurde Josua berichtet und gesagt: Die fünf Könige sind gefunden worden, versteckt in der Höhle zu Makkeda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Und Josua sprach: Wälzet große Steine an die Mündung der Höhle, und bestellet Männer über dieselbe, um sie zu bewachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Ihr aber, stehet nicht still, jaget euren Feinden nach und schlaget ihren Nachtrab; laßt sie nicht in ihre Städte kommen, denn Jehova, euer Gott, hat sie in eure Hand gegeben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Und es geschah, als Josua und die Kinder Israel geendigt hatten, eine sehr große Niederlage unter ihnen anzurichten, bis sie aufgerieben waren, (die Entronnenen von ihnen entrannen aber und kamen in die festen Städte)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'da kehrte das ganze Volk in Frieden zu Josua zurück, in das Lager nach Makkeda; niemand spitzte seine Zunge gegen die Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Und Josua sprach: Öffnet die Mündung der Höhle und bringet diese fünf Könige aus der Höhle zu mir heraus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Und sie taten also und brachten diese fünf Könige aus der Höhle zu ihm heraus: den König von Jerusalem, den König von Hebron, den König von Jarmuth, den König von Lachis, den König von Eglon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Und es geschah, als sie diese Könige zu Josua herausgebracht hatten, da rief Josua alle Männer von Israel und sprach zu den Anführern der Kriegsleute, die mit ihm gezogen waren: Tretet herzu, setzet eure Füße auf die Hälse dieser Könige! Und sie traten herzu und setzten ihre Füße auf ihre Hälse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Und Josua sprach zu ihnen: Fürchtet euch nicht und erschrecket nicht, seid stark und mutig! Denn so wird Jehova allen euren Feinden tun, wider die ihr streitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Und danach erschlug Josua sie und tötete sie und hängte sie an fünf Bäume; und sie hingen an den Bäumen bis zum Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Und es geschah zur Zeit des Sonnenuntergangs, da gebot Josua, und man nahm sie von den Bäumen herab und warf sie in die Höhle, wo sie sich versteckt hatten; und man legte große Steine an die Mündung der Höhle, die bis auf diesen selbigen Tag da sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Und Josua nahm an jenem Tage Makkeda ein und schlug es mit der Schärfe des Schwertes; und seinen König, die Stadt und alle Seelen, die darin waren, verbannte er: er ließ keinen Entronnenen übrig; und er tat dem König von Makkeda, so wie er dem König von Jericho getan hatte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Und Josua, und ganz Israel mit ihm, zog von Makkeda nach Libna und stritt wider Libna.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Und Jehova gab es auch in die Hand Israels, samt seinem König; und er schlug es mit der Schärfe des Schwertes und alle Seelen, die darin waren: er ließ keinen Entronnenen darin übrig; und er tat seinem König, so wie er dem König von Jericho getan hatte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Und Josua, und ganz Israel mit ihm, zog von Libna nach Lachis; und er belagerte es und stritt wider dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Und Jehova gab Lachis in die Hand Israels; und er nahm es am zweiten Tage ein und schlug es mit der Schärfe des Schwertes und alle Seelen, die darin waren, nach allem, was er Libna getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Damals zog Horam, der König von Geser, herauf, um Lachis zu helfen; aber Josua schlug ihn und sein Volk, bis ihm kein Entronnener übrigblieb. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Und Josua, und ganz Israel mit ihm, zog von Lachis nach Eglon; und sie belagerten es und stritten wider dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Und sie nahmen es an selbigem Tage ein und schlugen es mit der Schärfe des Schwertes; und alle Seelen, die darin waren, verbannte er an selbigem Tage, nach allem was er Lachis getan hatte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Und Josua, und ganz Israel mit ihm, zog von Eglon nach Hebron hinauf, und sie stritten wider dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Und sie nahmen es ein und schlugen es mit der Schärfe des Schwertes, samt seinem König und allen seinen Städten und allen Seelen, die darin waren: er ließ keinen Entronnenen übrig, nach allem, was er Eglon getan hatte; und er verbannte es und alle Seelen, die darin waren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Und Josua, und ganz Israel mit ihm, wandte sich nach Debir und stritt wider dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Und er nahm es ein, samt seinem König und allen seinen Städten, und sie schlugen sie mit der Schärfe des Schwertes und verbannten alle Seelen, die darin waren: er ließ keinen Entronnenen übrig; wie er Hebron getan, und wie er Libna und seinem König getan hatte, also tat er Debir und seinem König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Und Josua schlug das ganze Land, das Gebirge und den Süden und die Niederung und die Abhänge und alle ihre Könige: er ließ keinen Entronnenen übrig; und alles, was Odem hatte, verbannte er, so wie Jehova, der Gott Israels, geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Und Josua schlug sie von Kades-Barnea bis Gasa, und das ganze Land Gosen bis Gibeon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Und alle diese Könige und ihr Land nahm Josua auf einmal; denn Jehova, der Gott Israels, stritt für Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Und Josua, und ganz Israel mit ihm, kehrte in das Lager nach Gilgal zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Und es geschah, als Jabin, der König von Hazor, es hörte, sandte er zu Jobab, dem König von Madon, und zu dem König von Schimron und zu dem König von Akschaph');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'und zu den Königen, die gegen Norden waren im Gebirge und in der Ebene südlich von Kinneroth und in der Niederung und im Hügelgebiet von Dor gegen Westen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'zu den Kanaanitern gegen Osten und gegen Westen, und zu den Amoritern und den Hethitern und den Perisitern und den Jebusitern im Gebirge, und zu den Hewitern am Fuße des Hermon im Lande Mizpa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Und sie zogen aus, sie und alle ihre Heerlager mit ihnen, ein großes Volk, wie der Sand, der am Ufer des Meeres ist, an Menge, und sehr viele Rosse und Wagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Und alle diese Könige trafen zusammen und kamen und lagerten sich miteinander am Wasser Merom, um mit Israel zu streiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Da sprach Jehova zu Josua: Fürchte dich nicht vor ihnen; denn morgen um diese Zeit will ich sie allesamt erschlagen vor Israel dahingeben: ihre Rosse sollst du lähmen und ihre Wagen mit Feuer verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Und Josua, und alles Kriegsvolk mit ihm, kam plötzlich über sie am Wasser Merom, und sie überfielen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Und Jehova gab sie in die Hand Israels, und sie schlugen sie und jagten ihnen nach bis Zidon, der großen Stadt, und bis Misrephot-Majim und bis in die Talebene von Mizpe gegen Osten; und sie schlugen sie, bis ihnen kein Entronnener übrigblieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Und Josua tat ihnen, so wie Jehova ihm gesagt hatte: ihre Rosse lähmte er, und ihre Wagen verbrannte er mit Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Und Josua kehrte in selbiger Zeit zurück und nahm Hazor ein, und seinen König erschlug er mit dem Schwerte; denn Hazor war vordem die Hauptstadt aller dieser Königreiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Und sie schlugen alle Seelen, die darin waren, mit der Schärfe des Schwertes, indem sie sie verbannten: nichts blieb übrig, was Odem hatte; und Hazor verbrannte er mit Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Und alle Städte dieser Könige, samt allen ihren Königen, nahm Josua ein und schlug sie mit der Schärfe des Schwertes und verbannte sie, so wie Mose, der Knecht Jehovas, geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Nur alle die Städte, die auf ihren Hügeln standen, verbrannte Israel nicht; ausgenommen Hazor allein, das verbrannte Josua.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Und alle Beute dieser Städte und das Vieh plünderten die Kinder Israel für sich; doch alle Menschen schlugen sie mit der Schärfe des Schwertes, bis sie sie vertilgt hatten: sie ließen nichts übrig, was Odem hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Wie Jehova Mose, seinem Knechte, geboten hatte, also gebot Mose Josua, und also tat Josua; er ließ nichts fehlen von allem, was Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Und Josua nahm dieses ganze Land, das Gebirge und den ganzen Süden und das ganze Land Gosen und die Niederung und die Ebene, und das Gebirge Israel und seine Niederung, von dem kahlen Gebirge,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'das gegen Seir aufsteigt, bis Baal-Gad in der Talebene des Libanon, am Fuße des Berges Hermon; und alle ihre Könige ergriff er und erschlug sie und tötete sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Lange Zeit führte Josua Krieg mit allen diesen Königen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Es war keine Stadt, die sich den Kindern Israel friedlich ergab, außer den Hewitern, die zu Gibeon wohnten; alles nahmen sie mit Krieg ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Denn von Jehova war es, daß sie ihr Herz verhärteten zum Kriege mit Israel, damit sie vertilgt würden, ohne daß ihnen Gnade widerführe, sondern damit sie vertilgt würden, so wie Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Und Josua kam in selbiger Zeit und rottete die Enakim aus von dem Gebirge, von Hebron, von Debir, von Anab und von dem ganzen Gebirge Juda und von dem ganzen Gebirge Israel: mit ihren Städten verbannte sie Josua.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Es blieben keine Enakim in dem Lande der Kinder Israel übrig; nur zu Gasa, zu Gath und zu Asdod blieben sie übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Und so nahm Josua das ganze Land, nach allem, was Jehova zu Mose geredet hatte; und Josua gab es Israel zum Erbteil, nach ihren Abteilungen, nach ihren Stämmen. Und das Land hatte Ruhe vom Kriege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Und dies sind die Könige des Landes, welche die Kinder Israel schlugen, und deren Land sie in Besitz nahmen jenseit des Jordan, gegen Sonnenaufgang, vom Flusse Arnon bis zum Berge Hermon, und die ganze Ebene gegen Osten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sihon, der König der Amoriter, der zu Hesbon wohnte; er herrschte von Aroer an, das am Ufer des Flusses Arnon liegt, und zwar von der Mitte des Flußtales an, und über das halbe Gilead bis an den Fluß Jabbok, die Grenze der Kinder Ammon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'und über die Ebene bis an den See Kinneroth, gegen Osten, und bis an das Meer der Ebene, das Salzmeer, gegen Osten, nach Beth-Jesimoth hin, und gegen Süden unter den Abhängen des Pisga;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'und das Gebiet Ogs, des Königs von Basan, von dem Überrest der Rephaim, der zu Astaroth und zu Edrei wohnte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'und er herrschte über den Berg Hermon und über Salka und über das ganze Basan, bis an die Grenze der Gesuriter und der Maakathiter, und über das halbe Gilead, die Grenze Sihons, des Königs von Hesbon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mose, der Knecht Jehovas, und die Kinder Israel schlugen sie; und Mose, der Knecht Jehovas, gab es als Besitztum den Rubenitern und den Gaditern und dem halben Stamme Manasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Und dies sind die Könige des Landes, welche Josua und die Kinder Israel schlugen diesseit des Jordan, nach Westen hin, von Baal-Gad in der Talebene des Libanon, bis an das kahle Gebirge, das gegen Seir aufsteigt. Und Josua gab es den Stämmen Israels als Besitztum, nach ihren Abteilungen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'im Gebirge und in der Niederung und in der Ebene und an den Abhängen und in der Wüste und im Süden: die Hethiter und die Amoriter und die Kanaaniter, die Perisiter, die Hewiter und die Jebusiter:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'der König von Jericho: einer; der König von Ai, das zur Seite von Bethel liegt, einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'der König von Jerusalem: einer; der König von Hebron: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'der König von Jarmuth: einer; der König von Lachis: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'der König von Eglon: einer; der König von Geser: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'der König von Debir: einer; der König von Geder: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'der König von Horma: einer; der König von Arad: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'der König von Libna: einer; der König von Adullam: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'der König von Makkeda: einer; der König von Bethel: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'der König von Tappuach: einer; der König von Hepher: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'der König von Aphek: einer; der König von Lascharon: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'der König von Madon: einer; der König von Hazor: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'der König von Schimron-Meron: einer; der König von Akschaph: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'der König von Taanak: einer; der König von Megiddo: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'der König von Kedesch: einer; der König von Jokneam, am Karmel: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'der König von Dor, in dem Hügelgebiet von Dor: einer; der König von Gojim zu Gilgal: einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'der König von Tirza: einer. Aller Könige waren einunddreißig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Und Josua war alt, wohlbetagt, und Jehova sprach zu ihm: Du bist alt, wohlbetagt, und vom Lande ist sehr viel übrig in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Dies ist das Land, das noch übrig ist: alle Bezirke der Philister und das ganze Gesuri;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'von dem Sihor, der vor Ägypten fließt, bis an die Grenze von Ekron gegen Norden, wird es zu den Kanaanitern gerechnet; die fünf Fürsten der Philister: der Gasiter, der Asdoditer, der Askaloniter, der Gathiter und der Ekroniter, und die Awim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Im Süden das ganze Land der Kanaaniter und Meara, das den Zidoniern gehört, bis Aphek, bis an die Grenze der Amoriter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'und das Land der Gibliter und der ganze Libanon gegen Sonnenaufgang, von Baal-Gad, am Fuße des Berges Hermon, bis man nach Hamath kommt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'alle Bewohner des Gebirges, vom Libanon bis Misrephot-Majim, alle Zidonier. Ich selbst werde sie vor den Kindern Israel austreiben; nur verlose es Israel als Erbteil, so wie ich dir geboten habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Und nun verteile dieses Land als Erbteil den neun Stämmen und dem halben Stamme Manasse. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Mit ihm haben die Rubeniter und die Gaditer ihr Erbteil empfangen, welches Mose ihnen gegeben hat jenseit des Jordan gegen Osten, so wie Mose, der Knecht Jehovas, es ihnen gegeben hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'von Aroer an, das am Ufer des Flusses Arnon ist, und zwar von der Stadt, die mitten im Flußtale liegt, und die ganze Ebene Medeba bis Dibon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'und alle Städte Sihons, des Königs der Amoriter, der zu Hesbon regierte, bis zur Grenze der Kinder Ammon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'und Gilead und das Gebiet der Gesuriter und der Maakathiter und den ganzen Berg Hermon und das ganze Basan bis Salka,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'das ganze Reich Ogs in Basan, der zu Astaroth und zu Edrei regierte; (er war von dem Überrest der Rephaim übriggeblieben;) und Mose schlug sie und trieb sie aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Aber die Kinder Israel trieben die Gesuriter und die Maakathiter nicht aus; und Gesur und Maakath haben in der Mitte Israels gewohnt bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Nur dem Stamme Levi gab er kein Erbteil; die Feueropfer Jehovas, des Gottes Israels, sind sein Erbteil, so wie er zu ihm geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Und Mose gab dem Stamme der Kinder Ruben nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Und es wurde ihnen als Gebiet zuteil: von Aroer an, das am Ufer des Flusses Arnon ist, und zwar von der Stadt, die mitten im Flußtale liegt, und die ganze Ebene bei Medeba;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon und alle seine Städte, die in der Ebene sind: Dibon und Bamoth-Baal und Beth-Baal-Meon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'und Jahza und Kedemoth und Mephaath,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'und Kirjathaim und Sibma und Zereth-Schachar auf dem Berge der Talebene,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'und Beth-Peor und die Abhänge des Pisga und Beth-Jesimoth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'und alle Städte der Ebene, und das ganze Reich Sihons, des Königs der Amoriter, der zu Hesbon regierte, welchen Mose schlug, ihn und die Fürsten von Midian: Ewi und Rekem und Zur und Hur und Reba, die Herrscher Sihons, Bewohner des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Und Bileam, den Sohn Beors, den Wahrsager, töteten die Kinder Israel mit dem Schwerte, nebst ihren Erschlagenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Und die Grenze der Kinder Ruben war der Jordan und das Angrenzende. Das war das Erbteil der Kinder Ruben, nach ihren Geschlechtern, die Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Und Mose gab dem Stamme Gad, den Kindern Gad, nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Und es wurde ihnen als Gebiet zuteil: Jaser und alle Städte Gileads, und die Hälfte des Landes der Kinder Ammon bis Aroer, das vor Rabba liegt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'und von Hesbon bis Ramath-Mizpe und Betonim, und von Machanaim bis an die Grenze von Lidebir;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'und in der Talebene: Beth-Haram und Beth-Nimra und Sukkoth und Zaphon, der Rest von dem Reiche Sihons, des Königs von Hesbon, der Jordan und das Angrenzende bis an das Ende des Sees Kinnereth, jenseit des Jordan gegen Osten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Das war das Erbteil der Kinder Gad nach ihren Geschlechtern, die Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Und Mose gab dem halben Stamme Manasse. Und dem halben Stamme der Kinder Manasse wurde nach ihren Geschlechtern zuteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Und ihr Gebiet war von Machanaim an, das ganze Basan, das ganze Reich Ogs, des Königs von Basan, und alle Dörfer Jairs, die in Basan sind, sechzig Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Und das halbe Gilead, und Astaroth und Edrei, die Städte des Reiches Ogs, in Basan, wurden den Söhnen Makirs, des Sohnes Manasses, zuteil, der Hälfte der Söhne Makirs, nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Das ist es, was Mose in den Ebenen Moabs als Erbe ausgeteilt hat, jenseit des Jordan von Jericho, gegen Osten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Aber dem Stamme Levi gab Mose kein Erbteil; Jehova, der Gott Israels, ist ihr Erbteil, so wie er zu ihnen geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Und dies ist es, was die Kinder Israel als Erbe im Lande Kanaan erhielten, was Eleasar, der Priester, und Josua, der Sohn Nuns, und die Häupter der Väter der Stämme der Kinder Israel ihnen als Erbe austeilten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'durch das Los ihres Erbteils; so wie Jehova durch Mose geboten hatte betreffs der neun Stämme und des halben Stammes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Denn das Erbteil der zwei Stämme und des halben Stammes hatte Mose jenseit des Jordan gegeben; den Leviten aber hatte er kein Erbteil in ihrer Mitte gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Denn die Söhne Josephs bildeten zwei Stämme, Manasse und Ephraim; und man gab den Leviten kein Teil im Lande, außer Städten zum Wohnen und deren Bezirken für ihr Vieh und für ihre Habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'So wie Jehova dem Mose geboten hatte, also taten die Kinder Israel, und sie teilten das Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Und die Kinder Juda traten in Gilgal zu Josua; und Kaleb, der Sohn Jephunnes, der Kenisiter, sprach zu ihm: Du kennst das Wort, welches Jehova zu Mose, dem Manne Gottes, meinet-und deinetwegen in Kades-Barnea geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Vierzig Jahre war ich alt, als Mose, der Knecht Jehovas, mich von Kades-Barnea aussandte, um das Land auszukundschaften; und ich brachte ihm Antwort, wie es mir ums Herz war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Und meine Brüder, die mit mir hinaufgezogen waren, machten das Herz des Volkes verzagt; ich aber bin Jehova, meinem Gott, völlig nachgefolgt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Da schwur Mose an selbigem Tage und sprach: Wenn nicht das Land, auf welches dein Fuß getreten ist, dir und deinen Söhnen zum Erbteil wird ewiglich! Denn du bist Jehova, meinem Gott, völlig nachgefolgt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Und nun siehe, Jehova hat mich am Leben erhalten, so wie er geredet hat, diese fünfundvierzig Jahre, seitdem Jehova dieses Wort zu Mose geredet hat, als Israel in der Wüste umherwanderte; und nun siehe, ich bin heute fünfundachtzig Jahre alt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Ich bin heute noch so stark wie an dem Tage, da Mose mich aussandte; wie meine Kraft damals, so ist meine Kraft jetzt zum Streite und um aus-und einzuziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Und nun gib mir dieses Gebirge, von welchem Jehova an jenem Tage geredet hat; denn du hast an jenem Tage gehört, daß die Enakim daselbst sind und große, feste Städte. Vielleicht ist Jehova mit mir, daß ich sie austreibe, so wie Jehova geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Und Josua segnete ihn und gab dem Kaleb, dem Sohne Jephunnes, Hebron zum Erbteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Daher ward Hebron dem Kaleb, dem Sohne Jephunnes, dem Kenisiter, zum Erbteil bis auf diesen Tag, weil er Jehova, dem Gott Israels, völlig nachgefolgt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Der Name Hebrons war aber vordem: Stadt Arbas; er war der größte Mann unter den Enakim. Und das Land hatte Ruhe vom Kriege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Und das Los fiel für den Stamm der Kinder Juda, nach ihren Geschlechtern, nach der Grenze Edoms hin, der Wüste Zin, gegen Mittag, im äußersten Süden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Und ihre Südgrenze war vom Ende des Salzmeeres, von der Zunge, die sich gegen Süden wendet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'und sie lief aus südwärts von der Anhöhe Akrabbim und ging hinüber nach Zin, und sie stieg hinauf südlich von Kades-Barnea und ging hinüber nach Hezron, und sie stieg hinauf nach Addar und wandte sich nach Karka,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'und sie ging hinüber nach Azmon und lief aus an dem Bache Ägyptens; und der Ausgang der Grenze war nach dem Meere hin. Das soll eure Südgrenze sein. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Und die Grenze gegen Osten war das Salzmeer bis an das Ende des Jordan. Und die Grenze an der Nordseite war von der Meereszunge an, vom Ende des Jordan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'und die Grenze stieg hinauf nach Beth-Hogla und ging hinüber nördlich von Beth-Araba; und die Grenze stieg hinauf zum Steine Bohans, des Sohnes Rubens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'und die Grenze stieg von dem Tale Achor hinauf nach Debir, und sie wandte sich nördlich nach Gilgal, welches der Anhöhe Adummim gegenüber liegt, die südlich von dem Bache ist; und die Grenze ging hinüber zum Wasser En-Semes, und ihr Ausgang war nach En-Rogel hin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'und die Grenze stieg das Tal des Sohnes Hinnoms hinauf, nach der Südseite der Jebusiter, das ist Jerusalem; und die Grenze stieg zu dem Gipfel des Berges hinauf, welcher vor dem Tale Hinnom, gegen Westen, am Ende der Talebene der Rephaim, gegen Norden liegt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'und die Grenze zog sich herum von dem Gipfel des Berges nach der Quelle des Wassers Nephtoach, und lief nach den Städten des Gebirges Ephron hin; und die Grenze zog sich herum nach Baala, das ist Kirjath-Jearim;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'und von Baala wandte sich die Grenze gegen Westen nach dem Gebirge Seir und ging hinüber nach der Nordseite des Berges Jearim, das ist Kesalon, und sie stieg hinab nach Beth-Semes und ging hinüber nach Timna;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'und die Grenze lief nach der Nordseite von Ekron hin; und die Grenze zog sich herum nach Schikkeron und ging hinüber nach dem Berge von Baala, und sie lief aus bei Jabneel; und der Ausgang der Grenze war nach dem Meere hin. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Und die Westgrenze war das große Meer und das Angrenzende. Das war die Grenze der Kinder Juda ringsum nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Und Kaleb, dem Sohne Jephunnes, gab er ein Teil inmitten der Kinder Juda, nach dem Befehle Jehovas an Josua: Die Stadt Arbas, des Vaters Enaks, das ist Hebron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Und Kaleb trieb von dannen aus die drei Söhne Enaks, Scheschai und Achiman und Talmai, Kinder Enaks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Und von dannen zog er hinauf gegen die Bewohner von Debir; der Name von Debir war aber vordem Kirjath-Sepher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Und Kaleb sprach: Wer Kirjath-Sepher schlägt und es einnimmt, dem gebe ich meine Tochter Aksa zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Da nahm es Othniel ein, der Sohn Kenas\', ein Bruder Kalebs; und er gab ihm seine Tochter Aksa zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Und es geschah, als sie einzog, da trieb sie ihn an, ein Feld von ihrem Vater zu fordern. Und sie sprang von dem Esel herab. Und Kaleb sprach zu ihr: Was ist dir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Und sie sprach: Gib mir einen Segen; denn ein Mittagsland hast du mir gegeben, so gib mir auch Wasserquellen! Da gab er ihr die oberen Quellen und die unteren Quellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Das war das Erbteil des Stammes der Kinder Juda, nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Und die Städte am Ende des Stammes der Kinder Juda, gegen die Grenze Edoms hin im Süden, waren: Kabzeel und Eder und Jagur,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'und Kina und Dimona und Adada,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'und Kedesch und Hazor und Jithnan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Siph und Telem und Bealoth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'und Neu-Hazor und Kerijoth-Hezron, das ist Hazor;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam und Schema und Molada,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'und Hazor-Gadda und Heschmon und Beth-Pelet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'und Hazar-Schual und Beerseba und Bisjothja;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala und Ijim und Ezem,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'und El-Tolad und Kesil und Horma,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'und Ziklag und Madmanna und Sansanna,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'und Lebaoth und Schilchim und Ajin und Rimmon: aller Städte waren neunundzwanzig und ihre Dörfer. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'In der Niederung: Eschtaol und Zorha und Aschna,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'und Sanoach und En-Gannim, Tappuach und Enam,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmuth und Adullam, Soko und Aseka,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'und Schaaraim und Adithaim und Gedera und Gederothaim: vierzehn Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Zenan und Hadascha und Migdal-Gad,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'und Dilhan und Mizpe und Joktheel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lachis und Bozkath und Eglon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'und Kabbon und Lachmas und Kithlisch,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'und Gederoth, Beth-Dagon und Naama und Makkeda: sechzehn Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna und Ether und Aschan,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'und Jiphtach und Aschna und Nezib,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'und Kehila und Aksib und Marescha: neun Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron und seine Tochterstädte und seine Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Von Ekron an und westwärts, alle, die zur Seite von Asdod lagen, und ihre Dörfer:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod, seine Tochterstädte und seine Dörfer; Gasa, seine Tochterstädte und seine Dörfer, bis an den Bach Ägyptens, und das große Meer und das Angrenzende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Und im Gebirge: Schamir und Jattir und Soko,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'und Danna und Kirjath-Sanna, das ist Debir,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'und Anab und Eschtemo und Anim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'und Gosen und Holon und Gilo: elf Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab und Duma und Eschhan,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'und Janum und Beth-Tappuach und Apheka,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'und Humta und Kirjath-Arba, das ist Hebron, und Zior: neun Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel und Siph und Juta,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'und Jisreel und Jokdeam und Sanoach,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kajin, Gibea und Timna: zehn Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halchul, Beth-Zur und Gedor,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'und Maarath und Beth-Anoth und Eltekon: sechs Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjath-Baal, das ist Kirjath-Jearim, und Rabba: zwei Städte und ihre Dörfer. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'In der Wüste: Beth-Araba, Middin und Sekaka,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'und Nibschan und Ir-Hammelach und Engedi: sechs Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Aber die Jebusiter, die Bewohner von Jerusalem, die Kinder Juda vermochten sie nicht auszutreiben; und die Jebusiter haben mit den Kindern Juda in Jerusalem gewohnt bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Und das Los kam heraus für die Söhne Josephs vom Jordan von Jericho an, bei dem Wasser von Jericho gegen Osten: die Wüste, die von Jericho auf das Gebirge von Bethel hinaufsteigt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'und die Grenze lief von Bethel nach Lus und ging hinüber nach der Grenze der Arkiter, nach Ataroth;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'und sie stieg westwärts hinab nach der Grenze der Japhletiter, bis an die Grenze von Unter-Beth-Horon und bis Geser; und ihr Ausgang war nach dem Meere hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'So erhielten die Söhne Josephs, Manasse und Ephraim, ihr Erbteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Und es war die Grenze der Kinder Ephraim, nach ihren Geschlechtern: Die Grenze ihres Erbteils gegen Osten war Ateroth-Addar bis Ober-Beth-Horon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'und die Grenze lief gegen Westen nach Mikmethath hin, nördlich; und die Grenze wandte sich gegen Osten nach Taanath-Silo und ging daran vorbei gegen Osten nach Janocha;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'und sie stieg von Janocha hinab nach Ataroth und Naarath, und stieß an Jericho und lief aus am Jordan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'von Tappuach ging die Grenze gegen Westen nach dem Bache Kana, und ihr Ausgang war nach dem Meere hin. Das war das Erbteil des Stammes der Kinder Ephraim nach ihren Geschlechtern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'nebst den Städten, welche für die Kinder Ephraim abgesondert wurden inmitten des Erbteils der Kinder Manasse: alle Städte und ihre Dörfer. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Aber sie trieben die Kanaaniter nicht aus, die zu Geser wohnten; und die Kanaaniter haben inmitten von Ephraim gewohnt bis auf diesen Tag, und sie wurden fronpflichtig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Und das Los kam heraus für den Stamm Manasse, denn er war der Erstgeborene Josephs für Makir, den Erstgeborenen Manasses, den Vater Gileads; da er ein Kriegsmann war, so wurden ihm Gilead und Basan zuteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Und es kam heraus für die übrigen Söhne Manasses, nach ihren Geschlechtern: für die Söhne Abiesers und für die Söhne Heleks und für die Söhne Asriels und für die Söhne Sichems und für die Söhne Hephers und für die Söhne Schemidas; das waren die Kinder Manasses, des Sohnes Josephs, die Männlichen, nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Und Zelophchad, der Sohn Hephers, des Sohnes Gileads, des Sohnes Makirs, des Sohnes Manasses, hatte keine Söhne, sondern nur Töchter; und dies sind die Namen seiner Töchter: Machla und Noa, Chogla, Milka und Tirza.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Und sie traten herzu vor Eleasar, den Priester, und vor Josua, den Sohn Nuns, und vor die Fürsten, und sprachen: Jehova hat Mose geboten, uns ein Erbteil unter unseren Brüdern zu geben. Und er gab ihnen, nach dem Befehle Jehovas, ein Erbteil unter den Brüdern ihres Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Und so fielen dem Manasse zehn Anteile zu, außer dem Lande Gilead und Basan, das jenseit des Jordan liegt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'denn die Töchter Manasses erhielten ein Erbteil unter seinen Söhnen. Das Land Gilead aber wurde den übrigen Söhnen Manasses zuteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Und die Grenze Manasses war von Aser nach Mikmethath, das vor Sichem liegt; und die Grenze ging nach rechts zu den Bewohnern von En-Tappuach hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Dem Manasse gehörte das Land Tappuach; aber Tappuach, an der Grenze Manasses, gehörte den Kindern Ephraim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Und die Grenze stieg hinab nach dem Bache Kana, südlich vom Bache. Diese Städte gehörten Ephraim inmitten der Städte Manasses. Und das Gebiet Manasses war nördlich vom Bache, und sein Ausgang war nach dem Meere hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Gegen Süden gehörte es dem Ephraim, und gegen Norden dem Manasse; und das Meer war seine Grenze. Und gegen Norden stießen sie an Aser, und gegen Osten an Issaschar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Und Manasse erhielt in Issaschar und in Aser: Beth-Schean und seine Tochterstädte, und Jibleam und seine Tochterstädte, und die Bewohner von Dor und seine Tochterstädte, und die Bewohner von En-Dor und seine Tochterstädte, und die Bewohner von Taanak und seine Tochterstädte, und die Bewohner von Megiddo und seine Tochterstädte: das Dreihügelgebiet. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Aber die Kinder Manasse vermochten diese Städte nicht in Besitz zu nehmen, und die Kanaaniter wollten in diesem Lande bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Und es geschah, als die Kinder Israel erstarkten, da machten sie die Kanaaniter fronpflichtig; aber sie trieben sie keineswegs aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Und die Kinder Joseph redeten zu Josua und sprachen: Warum hast du mir nur ein Los und eine Meßschnur als Erbteil gegeben, da ich doch ein zahlreiches Volk bin, soweit Jehova mich bis jetzt gesegnet hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Und Josua sprach zu ihnen: Wenn du ein zahlreiches Volk bist, so ziehe in den Wald hinauf und haue dir daselbst aus in dem Lande der Perisiter und der Rephaim, wenn dir das Gebirge Ephraim zu enge ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Und die Kinder Joseph sprachen: Das Gebirge reicht für uns nicht aus, und bei allen Kanaanitern, die im Tallande wohnen, sind eiserne Wagen: bei denen, die in Beth-Schean und seinen Tochterstädten, und bei denen, die im Tale Jisreel wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Da sprach Josua zum Hause Joseph, zu Ephraim und zu Manasse, und sagte: Du bist ein zahlreiches Volk und hast eine große Kraft; nicht ein Los sollst du haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'sondern das Gebirge soll dir zuteil werden. Da es ein Wald ist, so haue ihn aus, und seine Ausläufer sollen dir gehören; denn du wirst die Kanaaniter austreiben, wenn sie auch eiserne Wagen haben, und wenn sie auch stark sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Und die ganze Gemeinde der Kinder Israel versammelte sich nach Silo, und sie schlugen daselbst das Zelt der Zusammenkunft auf; und das Land war vor ihnen unterjocht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Und es blieben unter den Kindern Israel sieben Stämme übrig, deren Erbteil man noch nicht ausgeteilt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Da sprach Josua zu den Kindern Israel: Wie lange werdet ihr euch lässig zeigen hinzugehen, um das Land in Besitz zu nehmen, welches Jehova, der Gott eurer Väter, euch gegeben hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Nehmet euch drei Männer für den Stamm, und ich will sie aussenden; und sie sollen sich aufmachen und das Land durchwandern und es aufschreiben nach Verhältnis ihres Erbteils, und dann zu mir kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Und sie sollen es unter sich in sieben Teile verteilen. Juda soll auf seinem Gebiet bleiben gegen Süden, und das Haus Joseph soll auf seinem Gebiet bleiben gegen Norden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Ihr aber sollt das Land aufschreiben zu sieben Teilen und mir das Verzeichnis hierherbringen; und ich werde euch das Los werfen, hier vor Jehova, unserem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Denn die Leviten haben kein Teil in eurer Mitte, denn das Priestertum Jehovas ist ihr Erbteil. Und Gad und Ruben und der halbe Stamm Manasse haben jenseit des Jordan, gegen Osten, ihr Erbteil empfangen, welches Mose, der Knecht Jehovas, ihnen gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Und die Männer machten sich auf und gingen hin. Und Josua gebot denen, die hingingen, um das Land aufzuschreiben, und sprach: Gehet hin und durchwandert das Land und schreibet es auf und kommet wieder zu mir; und hier werde ich euch das Los werfen vor Jehova, zu Silo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Und die Männer gingen hin und durchzogen das Land und schrieben es, nach den Städten, zu sieben Teilen auf in ein Buch; und sie kamen zu Josua in das Lager nach Silo zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Da warf ihnen Josua das Los zu Silo vor Jehova. Und Josua teilte daselbst das Land den Kindern Israel aus nach ihren Abteilungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Und es kam herauf das Los des Stammes der Kinder Benjamin nach ihren Geschlechtern. Und das Gebiet ihres Loses kam heraus zwischen den Kindern Juda und den Kindern Joseph.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Und ihre Grenze auf der Nordseite fing am Jordan an; und die Grenze stieg hinauf nach der Nordseite von Jericho und stieg auf das Gebirge gegen Westen, und ihr Ausgang war nach der Wüste von Beth-Awen hin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'und von dort ging die Grenze hinüber nach Lus, nach der Südseite von Lus, das ist Bethel; und die Grenze stieg hinab nach Ateroth-Addar, bei dem Berge, der südlich von Unter-Beth-Horon ist. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Und die Grenze zog sich herum und wandte sich nach der Westseite, südwärts von dem Berge, der vor Beth-Horon nach Süden liegt, und ihr Ausgang war nach Kirjath-Baal hin, das ist Kirjath-Jearim, einer Stadt der Kinder Juda; das war die Westseite. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Und die Südseite fing an am Ende von Kirjath-Jearim; und die Grenze lief aus nach Westen hin, und sie lief nach der Quelle des Wassers Nephtoach hin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'und die Grenze stieg hinab zu dem Ende des Berges, welcher vor dem Tale des Sohnes Hinnoms in der Talebene der Rephaim gegen Norden liegt; und sie stieg das Tal Hinnom hinab nach der Südseite der Jebusiter, und sie stieg hinab nach En-Rogel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'und sie zog sich nordwärts herum und lief nach En-Semes, und sie lief nach Geliloth hin, das der Anhöhe Adummim gegenüber liegt; und sie stieg hinab zum Steine Bohans, des Sohnes Rubens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'und ging hinüber nach der Seite, die der Araba nordwärts gegenüber liegt, und stieg hinab nach der Araba;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'und die Grenze ging hinüber nach der Nordseite von Beth-Hogla, und der Ausgang der Grenze war nach der nördlichen Zunge des Salzmeeres, nach dem südlichen Ende des Jordan hin. Das war die Südgrenze. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Und der Jordan begrenzte es an der Ostseite. Das war das Erbteil der Kinder Benjamin, nach seinen Grenzen ringsum, nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Und die Städte des Stammes der Kinder Benjamin, nach ihren Geschlechtern, waren: Jericho und Beth-Hogla und Emek-Keziz,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'und Beth-Araba und Zemaraim und Bethel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'und Awim und Para und Ophra,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'und Kephar-Ammoni und Ophni und Geba: Zwölf Städte und ihre Dörfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon und Rama und Beeroth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'und Mizpe und Kephira und Moza,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'und Rekem und Jirpeel und Tarala,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'und Zela, Eleph, und die Jebusiter, das ist Jerusalem, Gibeath, Kirjath: vierzehn Städte und ihre Dörfer. Das war das Erbteil der Kinder Benjamin nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Und das zweite Los kam herauf für Simeon, für den Stamm der Kinder Simeon, nach ihren Geschlechtern; und ihr Erbteil war mitten in dem Erbteil der Kinder Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Und es ward ihnen zum Erbteil: Beerseba und Scheba und Molada,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'und Hazar-Schual und Bala und Ezem,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'und Eltolad und Bethul und Horma,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'und Ziklag und Beth-Markaboth und Hazar-Susa,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'und Beth-Lebaoth und Scharuchen: dreizehn Städte und ihre Dörfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Rimmon und Ether und Aschan: vier Städte und ihre Dörfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'und alle Dörfer, die rings um diese Städte liegen, bis Baalath-Beer, das ist Süd-Ramath. Das war das Erbteil des Stammes der Kinder Simeon, nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Von der Meßschnur der Kinder Juda war das Erbteil der Kinder Simeon; denn das Teil der Kinder Juda war zu groß für sie, und so erhielten die Kinder Simeon ihr Erbteil mitten in ihrem Erbteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Und das dritte Los kam herauf für die Kinder Sebulon, nach ihren Geschlechtern. Und die Grenze ihres Erbteils war bis Sarid;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'und ihre Grenze stieg hinauf westwärts, und zwar nach Marhala, und stieß an Dabbescheth und stieß an den Bach, der vor Jokneam fließt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'und sie kehrte um von Sarid, ostwärts, gegen Sonnenaufgang, nach der Grenze von Kisloth-Tabor, und lief nach Daberath hin und stieg hinauf nach Japhija;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'und von dort ging sie hinüber ostwärts gegen Sonnenaufgang, nach Gath-Hepher, nach Eth-Kazin, und lief aus bei Rimmon, das sich nach Nea hin erstreckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Und die Grenze wandte sich um dasselbe nördlich nach Hannathon, und ihr Ausgang war das Tal Jiphtach-El;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, '...und Kattath und Nahalal und Schimron und Jidala und Bethlehem: zwölf Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Das war das Erbteil der Kinder Sebulon, nach ihren Geschlechtern, diese Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Für Issaschar kam das vierte Los heraus, für die Kinder Issaschar, nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Und ihr Gebiet war nach Jisreel hin, und Kesulloth und Schunem,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'und Hapharaim und Schion und Anacharath,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'und Rabbith und Kischjon und Ebez,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'und Remeth und En-Gannim und En-Hadda und Beth-Pazez;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'und die Grenze stieß an Tabor und Schachazuma und Beth-Semes, und der Ausgang ihrer Grenze war am Jordan: sechzehn Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Das war das Erbteil des Stammes der Kinder Issaschar, nach ihren Geschlechtern, die Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Und das fünfte Los kam heraus für den Stamm der Kinder Aser, nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Und ihre Grenze war: Helkath und Hali und Beten und Akschaph,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'und Allammelek und Amhad und Mischeal; und sie stieß an den Karmel, gegen Westen, und an den Sihor-Libnath;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'und sie kehrte um gegen Sonnenaufgang nach Beth-Dagon und stieß an Sebulon und an das Tal Jiphtach-El, nördlich von Beth-Emek und Nehiel, und sie lief nach Kabul hin zur Linken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'und Ebron und Rechob und Hammon und Kana, bis Zidon, der großen Stadt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'und die Grenze kehrte um nach Rama und bis zur festen Stadt Tyrus; und die Grenze kehrte um nach Hosa, und ihr Ausgang war nach dem Meere hin von dem Striche Aksib an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, '...und Umma und Aphek und Rechob: zweiundzwanzig Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Das war das Erbteil des Stammes der Kinder Aser, nach ihren Geschlechtern, diese Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Für die Kinder Naphtali kam das sechste Los heraus, für die Kinder Naphtali, nach ihren Geschlechtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Und ihre Grenze war von Heleph, von der Terebinthe zu Zaanannim, und Adami-Nekeb und Jabneel bis Lakum, und ihr Ausgang war am Jordan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'und die Grenze kehrte um westwärts nach Asnoth-Tabor und lief von dort nach Hukkok hin. Und so stieß sie an Sebulon gegen Süden, und an Aser stieß sie gegen Westen, und an Juda am Jordan gegen Sonnenaufgang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Und die festen Städte waren: Ziddim, Zer und Hammath, Rakkath und Kinnereth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'und Adama und Rama und Hazor,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'und Kedes und Edrei und En-Hazor,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'und Jiron und Migdal-El, Horem und Beth-Anath und Beth-Semes: neunzehn Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Das war das Erbteil des Stammes der Kinder Naphtali, nach ihren Geschlechtern, die Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Für den Stamm der Kinder Dan, nach ihren Geschlechtern, kam das siebte Los heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Und das Gebiet ihres Erbteils war: Zorha und Eschtaol und Ir-Semes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'und Schaalabbin und Ajjalon und Jithla,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'und Elon und Timnatha und Ekron,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'und Elteke und Gibbethon und Baalath,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'und Jehud und Bne-Berak und Gath-Rimmon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'und Me-Jarkon und Rakkon, mit dem Gebiete gegenüber Japho.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Und die Grenze der Kinder Dan ging später weiter als diese; denn die Kinder Dan zogen hinauf und stritten wider Leschem, und nahmen es ein und schlugen es mit der Schärfe des Schwertes, und sie nahmen es in Besitz und wohnten darin; und sie nannten Leschem Dan, nach dem Namen ihres Vaters Dan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Das war das Erbteil des Stammes der Kinder Dan nach ihren Geschlechtern, diese Städte und ihre Dörfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Und als sie die Verteilung des Landes nach seinen Grenzen vollendet hatten, gaben die Kinder Israel Josua, dem Sohne Nuns, ein Erbteil in ihrer Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Nach dem Befehle Jehovas gaben sie ihm die Stadt, die er verlangte, Timnath-Serach im Gebirge Ephraim; und er baute die Stadt und wohnte darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Das sind die Erbteile, welche Eleasar, der Priester, und Josua, der Sohn Nuns, und die Häupter der Väter der Stämme der Kinder Israel durch das Los austeilten zu Silo, vor Jehova, an dem Eingang des Zeltes der Zusammenkunft. Und so vollendeten sie die Verteilung des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Und Jehova redete zu Josua und sprach: Rede zu den Kindern Israel und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Bestimmet euch die Zufluchtstädte, von welchen ich durch Mose zu euch geredet habe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'daß dahin fliehe ein Totschläger, der jemand aus Versehen, unabsichtlich, erschlagen hat; und sie seien euch zur Zuflucht vor dem Bluträcher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Und er soll in eine von diesen Städten fliehen, und an dem Eingang des Stadttores stehen und vor den Ohren der Ältesten jener Stadt seine Sache vorbringen; und sie sollen ihn zu sich in die Stadt aufnehmen und ihm einen Ort geben, daß er bei ihnen wohne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Und wenn der Bluträcher ihm nachjagt, so sollen sie den Totschläger nicht in seine Hand ausliefern; denn er hat seinen Nächsten unabsichtlich erschlagen, und er haßte ihn vordem nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Und er soll in jener Stadt wohnen, bis er vor der Gemeinde zu Gericht gestanden hat, bis zum Tode des Hohenpriesters, der in jenen Tagen sein wird; alsdann mag der Totschläger zurückkehren und in seine Stadt und in sein Haus kommen, in die Stadt, aus welcher er geflohen ist. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Und sie heiligten Kedes in Galiläa, im Gebirge Naphtali, und Sichem im Gebirge Ephraim, und Kirjath-Arba, das ist Hebron, im Gebirge Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Und jenseit des Jordan von Jericho, gegen Osten, bestimmten sie Bezer in der Wüste, in der Ebene, vom Stamme Ruben; und Ramoth in Gilead, vom Stamme Gad; und Golan in Basan, vom Stamme Manasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Das waren die bestimmten Städte für alle Kinder Israel und für den Fremdling, der in ihrer Mitte weilte, auf daß dahin fliehe ein jeder, der jemand aus Versehen erschlagen würde, damit er nicht durch die Hand des Bluträchers sterbe, bis er vor der Gemeinde gestanden habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Und die Häupter der Väter der Leviten traten zu Eleasar, dem Priester, und zu Josua, dem Sohne Nuns, und zu den Häuptern der Väter der Stämme der Kinder Israel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'und redeten zu ihnen zu Silo, im Lande Kanaan, und sprachen: Jehova hat durch Mose geboten, uns Städte zum Wohnen zu geben, und deren Bezirke für unser Vieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Und die Kinder Israel gaben den Leviten von ihrem Erbteil diese Städte und ihre Bezirke, nach dem Befehle Jehovas:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Und das Los kam heraus für die Familien der Kehathiter. Und die Söhne Aarons, des Priesters, aus den Leviten, erhielten vom Stamme Juda und vom Stamme der Simeoniter und vom Stamme Benjamin, durchs Los, dreizehn Städte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'und die übrigen Söhne Kehaths, von den Geschlechtern des Stammes Ephraim und vom Stamme Dan und vom halben Stamme Manasse, durchs Los, zehn Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Und die Söhne Gersons erhielten von den Geschlechtern des Stammes Issaschar und vom Stamme Aser und vom Stamme Naphtali und vom halben Stamme Manasse in Basan, durchs Los, dreizehn Städte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'die Söhne Meraris, nach ihren Familien, vom Stamme Ruben und vom Stamme Gad und vom Stamme Sebulon zwölf Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Und so gaben die Kinder Israel den Leviten diese Städte und ihre Bezirke durchs Los, so wie Jehova durch Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Und sie gaben vom Stamme der Kinder Juda und vom Stamme der Kinder Simeon folgende Städte, die man mit Namen nannte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'und sie wurden den Söhnen Aarons, von den Familien der Kehathiter, aus den Kindern Levi, zuteil (denn für sie war das erste Los).');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Und sie gaben ihnen die Stadt Arbas, des Vaters Enaks, das ist Hebron, im Gebirge Juda, und ihre Bezirke rings um sie her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Aber das Feld der Stadt und ihre Dörfer gaben sie Kaleb, dem Sohne Jephunnes, als sein Eigentum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Und sie gaben den Söhnen Aarons, des Priesters, die Zufluchtstadt für den Totschläger, Hebron und seine Bezirke; und Libna und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'und Jattir und seine Bezirke, und Eschtemoa und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'und Holon und seine Bezirke, und Debir und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'und Ain und seine Bezirke, und Jutta und seine Bezirke, und Beth-Semes und seine Bezirke: neun Städte von diesen beiden Stämmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Und vom Stamme Benjamin: Gibeon und seine Bezirke, Geba und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anathoth und seine Bezirke, und Almon und seine Bezirke: vier Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Alle Städte der Söhne Aarons, der Priester: dreizehn Städte und ihre Bezirke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Und was die Familien der Söhne Kehaths, der Leviten, die übrigen von den Söhnen Kehaths, betrifft, so waren die Städte ihres Loses vom Stamme Ephraim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Und sie gaben ihnen die Zufluchtstadt für den Totschläger, Sichem und seine Bezirke im Gebirge Ephraim; und Geser und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'und Kibzaim und seine Bezirke, und Beth-Horon und seine Bezirke: vier Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Und vom Stamme Dan: Elteke und seine Bezirke, Gibbethon und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajjalon und seine Bezirke, Gath-Rimmon und seine Bezirke: vier Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Und von der Hälfte des Stammes Manasse: Taanak und seine Bezirke, und Gath-Rimmon und seine Bezirke: zwei Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Aller Städte waren zehn und ihre Bezirke, für die Familien der übrigen Söhne Kehaths.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Und den Söhnen Gersons, aus den Geschlechtern der Leviten, gaben sie vom halben Stamme Manasse: Die Zufluchtstadt für den Totschläger, Golan in Basan und seine Bezirke; und Beeschtera und seine Bezirke: zwei Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Und vom Stamme Issaschar: Kischjon und seine Bezirke, Daberath und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmuth und seine Bezirke, En-Gannim und seine Bezirke: Vier Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Und vom Stamme Aser: Mischeal und seine Bezirke, Abdon und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkath und seine Bezirke, und Rechob und seine Bezirke: vier Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Und vom Stamme Naphtali: Die Zufluchtstadt für den Totschläger, Kedes in Galiläa und seine Bezirke; und Hammoth-Dor und seine Bezirke, und Kartan und seine Bezirke: drei Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Alle Städte der Gersoniter, nach ihren Familien: dreizehn Städte und ihre Bezirke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Und den Familien der Söhne Meraris, den übrigen Leviten, gaben sie vom Stamme Sebulon: Jokneam und seine Bezirke, Karta und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna und seine Bezirke, Nahalal und seine Bezirke: vier Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Und vom Stamme Ruben: Bezer und seine Bezirke, und Jahza und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemoth und seine Bezirke, und Mephaath und seine Bezirke: vier Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Und vom Stamme Gad: Die Zufluchtstadt für den Totschläger, Ramoth in Gilead und seine Bezirke; und Machanaim und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesbon und seine Bezirke, Jaser und seine Bezirke; aller Städte waren vier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Alle Städte der Söhne Meraris, nach ihren Familien, der übrigen von den Geschlechtern der Leviten: ihr Los war zwölf Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Alle Städte der Leviten inmitten des Eigentums der Kinder Israel: achtundvierzig Städte und ihre Bezirke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Diese Städte hatten, Stadt für Stadt, ihre Bezirke rings um sich her: also war es bei allen diesen Städten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Und so gab Jehova Israel das ganze Land, welches er ihren Vätern zu geben geschworen hatte; und sie nahmen es in Besitz und wohnten darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Und Jehova schaffte ihnen Ruhe ringsumher nach allem, was er ihren Vätern geschworen hatte; und keiner von allen ihren Feinden hielt vor ihnen stand: alle ihre Feinde gab Jehova in ihre Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Es fiel kein Wort dahin von all den guten Worten, welche Jehova zu dem Hause Israel geredet hatte; alles traf ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Damals berief Josua die Rubeniter und die Gaditer und den halben Stamm Manasse,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'und er sprach zu ihnen: Ihr habt alles beobachtet, was Mose, der Knecht Jehovas, euch geboten hat, und habt meiner Stimme gehorcht in allem, was ich euch geboten habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Ihr habt eure Brüder nicht verlassen diese lange Zeit bis auf diesen Tag, und habt das Gebot Jehovas, eures Gottes, beobachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Und nun hat Jehova, euer Gott, euren Brüdern Ruhe geschafft, wie er zu ihnen geredet hat; und nun wendet euch und ziehet nach euren Zelten, in das Land eures Eigentums, welches Mose, der Knecht Jehovas, euch jenseit des Jordan gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Nur achtet wohl darauf, das Gebot und das Gesetz zu tun, welches Mose, der Knecht Jehovas, euch geboten hat: Jehova, euren Gott, zu lieben und auf allen seinen Wegen zu wandeln und seine Gebote zu beobachten, und ihm anzuhangen und ihm zu dienen mit eurem ganzen Herzen und mit eurer ganzen Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Und Josua segnete sie und entließ sie; und sie zogen nach ihren Zelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Und der einen Hälfte des Stammes Manasse hatte Mose in Basan ein Erbteil gegeben; aber seiner anderen Hälfte hatte Josua mit ihren Brüdern diesseit des Jordan, gegen Westen, ihr Erbteil gegeben. Und als Josua sie nach ihren Zelten entließ, da segnete er auch sie,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'und er sprach zu ihnen und sagte: Kehret nach euren Zelten zurück mit vielen Reichtümern und mit sehr vielem Vieh, mit Silber und mit Gold und mit Erz und mit Eisen und mit Kleidern in großer Menge; teilet die Beute eurer Feinde mit euren Brüdern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'So kehrten die Kinder Ruben und die Kinder Gad und der halbe Stamm Manasse zurück und zogen weg von den Kindern Israel, von Silo, das im Lande Kanaan ist, um in das Land Gilead zu ziehen, in das Land ihres Eigentums, in welchem sie sich ansässig gemacht hatten nach dem Befehle Jehovas durch Mose.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Und als sie in die Bezirke des Jordan kamen, die im Lande Kanaan sind, da bauten die Kinder Ruben und die Kinder Gad und der halbe Stamm Manasse daselbst einen Altar am Jordan, einen Altar, groß von Ansehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Und die Kinder Israel hörten sagen: Siehe, die Kinder Ruben und die Kinder Gad und der halbe Stamm Manasse haben einen Altar gebaut, angesichts des Landes Kanaan, in den Bezirken des Jordan, den Kindern Israel gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Und als die Kinder Israel es hörten, da versammelte sich die ganze Gemeinde der Kinder Israel nach Silo, um wider sie hinaufzuziehen zum Kriege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Und die Kinder Israel sandten zu den Kindern Ruben und zu den Kindern Gad und zu dem halben Stamme Manasse, in das Land Gilead, Pinehas, den Sohn Eleasars, des Priesters,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'und zehn Fürsten mit ihm, je einen Fürsten für ein Vaterhaus, von allen Stämmen Israels; und sie waren ein jeder das Haupt ihres Vaterhauses unter den Tausenden Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Und sie kamen zu den Kindern Ruben und zu den Kindern Gad und zu dem halben Stamme Manasse, in das Land Gilead, und redeten mit ihnen und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'So spricht die ganze Gemeinde Jehovas: Was ist das für eine Treulosigkeit, die ihr gegen den Gott Israels begangen habt, daß ihr euch heute abwendet von der Nachfolge Jehovas, indem ihr euch einen Altar bauet, um euch heute wider Jehova zu empören?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Ist es uns zu wenig an der Ungerechtigkeit Peors, von welcher wir uns noch nicht gereinigt haben bis auf diesen Tag, und doch kam die Plage über die Gemeinde Jehovas?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Und ihr, ihr wendet euch heute ab von der Nachfolge Jehovas! Und es wird geschehen, empöret ihr euch heute wider Jehova, so wird er morgen über die ganze Gemeinde Israels erzürnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Jedoch wenn das Land eures Eigentums unrein ist, so kommet herüber in das Land des Eigentums Jehovas, wo die Wohnung Jehovas weilt, und machet euch ansässig in unserer Mitte, aber empöret euch nicht wider Jehova, und empöret euch nicht wider uns, indem ihr euch einen Altar bauet außer dem Altar Jehovas, unseres Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Hat nicht Achan, der Sohn Serachs, Untreue an dem Verbannten begangen? Und ein Zorn kam über die ganze Gemeinde Israels; und er kam nicht als ein einzelner um in seiner Ungerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Und die Kinder Ruben und die Kinder Gad und der halbe Stamm Manasse antworteten und sprachen zu den Häuptern der Tausende Israels:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Der Gott der Götter, Jehova, der Gott der Götter, Jehova, er weiß es, und Israel soll es wissen: wenn es aus Empörung, und wenn es aus Treulosigkeit gegen Jehova geschehen ist, so mögest du uns nicht retten an diesem Tage!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'daß wir uns einen Altar gebaut haben, um uns von der Nachfolge Jehovas abzuwenden, und wenn es geschehen ist, um Brandopfer und Speisopfer darauf zu opfern, und wenn, um Friedensopfer darauf zu opfern, so möge Jehova es fordern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Und wenn wir nicht aus Besorgnis vor einer Sache dies getan haben, indem wir sprachen: Künftig werden eure Kinder zu unseren Kindern sprechen und sagen: Was habt ihr mit Jehova, dem Gott Israels, gemein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Jehova hat ja eine Grenze, den Jordan, zwischen uns und euch gesetzt, ihr Kinder Ruben und ihr Kinder Gad; ihr habt kein Teil an Jehova! Und so würden eure Kinder machen, daß unsere Kinder aufhörten, Jehova zu fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Und so sprachen wir: Wir wollen uns doch daran machen, den Altar zu bauen, nicht für Brandopfer und nicht für Schlachtopfer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'sondern ein Zeuge soll er sein zwischen uns und euch und zwischen unseren Geschlechtern nach uns, damit wir den Dienst Jehovas vor ihm verrichten mit unseren Brandopfern und mit unseren Schlachtopfern und mit unseren Friedensopfern, und damit nicht eure Kinder künftig zu unseren Kindern sagen: Ihr habt kein Teil an Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Und wir sprachen: Geschieht es, daß sie künftig zu uns oder zu unseren Geschlechtern also sprechen, so werden wir sagen: Sehet das Abbild des Altars Jehovas, welches unsere Väter gemacht haben, nicht für Brandopfer und nicht für Schlachtopfer; sondern ein Zeuge sollte er sein zwischen uns und euch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Fern sei es von uns, daß wir uns wider Jehova empören und uns heute von der Nachfolge Jehovas abwenden, indem wir einen Altar bauen für Brandopfer, für Speisopfer und für Schlachtopfer, außer dem Altar Jehovas, unseres Gottes, der vor seiner Wohnung ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Und als Pinehas, der Priester, und die Fürsten der Gemeinde und die Häupter der Tausende Israels, die mit ihm waren, die Worte hörten, welche die Kinder Ruben und die Kinder Gad und die Kinder Manasse redeten, war es gut in ihren Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Und Pinehas, der Sohn Eleasars, des Priesters, sprach zu den Kindern Ruben und zu den Kindern Gad und zu den Kindern Manasse: Heute erkennen wir, daß Jehova in unserer Mitte ist, weil ihr diese Treulosigkeit nicht gegen Jehova begangen habt. Nunmehr habt ihr die Kinder Israel von der Hand Jehovas errettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Und Pinehas, der Sohn Eleasars, des Priesters, und die Fürsten kehrten zurück von den Kindern Ruben und von den Kindern Gad, aus dem Lande Gilead in das Land Kanaan, zu den Kindern Israel und brachten ihnen Antwort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Und die Sache war gut in den Augen der Kinder Israel; und die Kinder Israel priesen Gott und sprachen nicht mehr davon, wider sie hinaufzuziehen zum Kriege, um das Land zu verderben, in welchem die Kinder Ruben und die Kinder Gad wohnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Und die Kinder Ruben und die Kinder Gad nannten den Altar Zeuge: denn er ist ein Zeuge zwischen uns, daß Jehova Gott ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Und es geschah nach vielen Tagen, nachdem Jehova Israel Ruhe geschafft hatte vor allen seinen Feinden ringsum, als Josua alt geworden war, wohlbetagt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'da berief Josua ganz Israel: seine Ältesten und seine Häupter und seine Richter und seine Vorsteher, und sprach zu ihnen: Ich bin alt geworden, wohlbetagt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'und ihr, ihr habt alles gesehen, was Jehova, euer Gott, allen diesen Nationen euretwegen getan hat. Denn Jehova, euer Gott, er ist es, der für euch gestritten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Sehet, ich habe euch diese übrigen Nationen durchs Los als Erbteil zufallen lassen, nach euren Stämmen, vom Jordan an (sowie alle Nationen, die ich ausgerottet habe) bis an das große Meer gegen Sonnenuntergang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Und Jehova, euer Gott, er selbst wird sie vor euch ausstoßen und sie vor euch austreiben; und ihr werdet ihr Land in Besitz nehmen, so wie Jehova, euer Gott, zu euch geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'So haltet denn sehr fest daran, alles zu beobachten und zu tun, was in dem Buche des Gesetzes Moses geschrieben ist, daß ihr nicht davon abweichet zur Rechten noch zur Linken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'daß ihr nicht unter diese Nationen kommet, diese, die bei euch übriggeblieben sind, und den Namen ihrer Götter nicht erwähnet und nicht jemand bei ihm beschwöret, und ihnen nicht dienet und euch nicht vor ihnen niederwerfet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Sondern Jehova, eurem Gott, sollt ihr anhangen, so wie ihr getan habt bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Und Jehova hat große und starke Nationen vor euch ausgetrieben; und ihr niemand hat vor euch standgehalten bis auf diesen Tag:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Ein Mann von euch jagt tausend; denn Jehova, euer Gott, er ist es, der für euch streitet, so wie er zu euch geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'So habet wohl acht auf eure Seelen, daß ihr Jehova, euren Gott, liebet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Denn wenn ihr euch irgend abwendet und euch an den Rest dieser Nationen hänget, dieser, die bei euch übriggeblieben sind, und ihr euch mit ihnen verschwägert und unter sie kommet, und sie unter euch:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'so wisset bestimmt, daß Jehova, euer Gott, nicht fortfahren wird, diese Nationen vor euch auszutreiben; und sie werden euch zur Schlinge werden und zum Fallstrick, und zur Geißel in euren Seiten und zu Dornen in euren Augen, bis ihr umkommet aus diesem guten Lande, das Jehova, euer Gott, euch gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Und siehe, ich gehe heute den Weg der ganzen Erde; und ihr wisset mit eurem ganzen Herzen und mit eurer ganzen Seele, daß nicht ein Wort dahingefallen ist von all den guten Worten, die Jehova, euer Gott, über euch geredet hat: sie sind euch alle eingetroffen, nicht ein Wort davon ist dahingefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Aber es wird geschehen, so wie jedes gute Wort über euch gekommen ist, das Jehova, euer Gott, zu euch geredet hat, also wird Jehova jedes böse Wort über euch kommen lassen, bis er euch aus diesem guten Lande vertilgt hat, das Jehova, euer Gott, euch gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Wenn ihr den Bund Jehovas, eures Gottes, den er euch geboten hat, übertretet, und hingehet und anderen Göttern dienet und euch vor ihnen niederwerfet, so wird der Zorn Jehovas gegen euch entbrennen, und ihr werdet schnell umkommen aus dem guten Lande, das er euch gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Und Josua versammelte alle Stämme Israels nach Sichem, und er berief die Ältesten von Israel und seine Häupter und seine Richter und seine Vorsteher; und sie stellten sich vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Und Josua sprach zu dem ganzen Volke: So spricht Jehova, der Gott Israels: Eure Väter wohnten vor alters jenseit des Stromes, Tarah, der Vater Abrahams und der Vater Nahors, und sie dienten anderen Göttern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Und ich nahm Abraham, euren Vater, von jenseit des Stromes und ließ ihn durch das ganze Land Kanaan wandern, und ich mehrte seinen Samen und gab ihm Isaak.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Und dem Isaak gab ich Jakob und Esau; und dem Esau gab ich das Gebirge Seir, es zu besitzen; und Jakob und seine Söhne zogen nach Ägypten hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Und ich sandte Mose und Aaron und schlug Ägypten, so wie ich in seiner Mitte getan habe; und danach führte ich euch heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Und ich führte eure Väter aus Ägypten hinweg, und ihr kamet an das Meer; und die Ägypter jagten euren Vätern nach mit Wagen und mit Reitern bis an das Schilfmeer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Da schrieen sie zu Jehova, und er setzte Finsternis zwischen euch und die Ägypter und führte das Meer über sie und bedeckte sie; und eure Augen haben gesehen, was ich an den Ägyptern getan habe. Und ihr wohntet in der Wüste eine lange Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Und ich brachte euch in das Land der Amoriter, die jenseit des Jordan wohnten, und sie stritten wider euch; und ich gab sie in eure Hand, und ihr nahmet ihr Land in Besitz, und ich vertilgte sie vor euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Da stand Balak auf, der Sohn Zippors, der König von Moab, und stritt wider Israel; und er sandte hin und ließ Bileam, den Sohn Beors, rufen, um euch zu verfluchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Aber ich wollte nicht auf Bileam hören, und er segnete euch vielmehr; und ich errettete euch aus seiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Und ihr zoget über den Jordan und kamet nach Jericho; und die Bürger von Jericho und die Amoriter und die Perisiter und die Kanaaniter und die Hethiter und die Girgasiter und die Hewiter und die Jebusiter stritten wider euch, und ich gab sie in eure Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Und ich sandte die Hornissen vor euch her, und sie vertrieben sie vor euch, die beiden Könige der Amoriter; nicht mit deinem Schwert und nicht mit deinem Bogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Und ich habe euch ein Land gegeben, um das du dich nicht gemüht, und Städte, die ihr nicht gebaut habt, und ihr wohnet darin; von Weinbergen und Olivenbäumen, die ihr nicht gepflanzt habt, esset ihr. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Und nun fürchet Jehova und dienet ihm in Vollkommenheit und in Wahrheit; und tut die Götter hinweg, welchen eure Väter jenseit des Stromes und in Ägypten gedient haben, und dienet Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Und wenn es übel ist in euren Augen, Jehova zu dienen, so erwählet euch heute, wem ihr dienen wollt, ob den Göttern, welchen eure Väter gedient haben, die jenseit des Stromes wohnten, oder den Göttern der Amoriter, in deren Land ihr wohnet. Ich aber und mein Haus, wir wollen Jehova dienen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Und das Volk antwortete und sprach: Fern sei es von uns, Jehova zu verlassen, um anderen Göttern zu dienen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Denn Jehova, unser Gott, ist es, der uns und unsere Väter aus dem Lande Ägypten, aus dem Hause der Knechtschaft, heraufgeführt hat, und der vor unseren Augen diese großen Zeichen getan und uns behütet hat auf dem ganzen Wege, auf dem wir gegangen, und unter all den Völkern, durch deren Mitte wir gezogen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Und Jehova hat alle Völker und die Amoriter, die Bewohner des Landes, vor uns vertrieben. Auch wir wollen Jehova dienen, denn er ist unser Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Und Josua sprach zu dem Volke: Ihr könnet Jehova nicht dienen; denn er ist ein heiliger Gott, er ist ein eifernder Gott; er wird eure Übertretung und eure Sünden nicht vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Wenn ihr Jehova verlasset und fremden Göttern dienet, so wird er sich wenden und euch Übles tun und euch vernichten, nachdem er euch Gutes getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Und das Volk sprach zu Josua: Nein, sondern Jehova wollen wir dienen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Da sprach Josua zu dem Volke: Ihr seid Zeugen gegen euch, daß ihr selbst euch Jehova erwählt habt, um ihm zu dienen. Und sie sprachen: Wir sind Zeugen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'So tut nun die fremden Götter hinweg, die in eurer Mitte sind, und neiget euer Herz zu Jehova, dem Gott Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Und das Volk sprach zu Josua: Jehova, unserem Gott, wollen wir dienen und auf seine Stimme hören!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Und Josua machte einen Bund mit dem Volke an selbigem Tage und stellte ihm Satzung und Recht zu Sichem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Und Josua schrieb diese Worte in das Buch des Gesetzes Gottes; und er nahm einen großen Stein und richtete ihn daselbst auf unter der Terebinthe, die bei dem Heiligtum Jehovas steht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Und Josua sprach zu dem ganzen Volke: Siehe, dieser Stein soll Zeuge gegen uns sein; denn er hat alle Worte Jehovas gehört, die er mit uns geredet hat; und er soll Zeuge gegen euch sein, damit ihr euren Gott nicht verleugnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Und Josua entließ das Volk, einen jeden in sein Erbteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Und es geschah nach diesen Dingen, da starb Josua, der Sohn Nuns, der Knecht Jehovas, hundertzehn Jahre alt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Und man begrub ihn im Gebiete seines Erbteils zu Timnath-Serach auf dem Gebirge Ephraim, nördlich vom Berge Gaasch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Und Israel diente Jehova alle Tage Josuas und alle Tage der Ältesten, welche ihre Tage nach Josua verlängerten, und die das ganze Werk Jehovas kannten, das er für Israel getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Und die Gebeine Josephs, welche die Kinder Israel aus Ägypten heraufgebracht hatten, begruben sie zu Sichem auf dem Stück Feld, welches Jakob von den Söhnen Hemors, des Vaters Sichems, gekauft hatte um hundert Kesita; und sie wurden den Kindern Joseph zum Erbteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Und Eleasar, der Sohn Aarons, starb; und sie begruben ihn auf dem Hügel seines Sohnes Pinehas, der ihm gegeben worden war auf dem Gebirge Ephraim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Und es geschah nach dem Tode Josuas, da befragten die Kinder Israel Jehova und sprachen: Wer von uns soll zuerst wider die Kanaaniter hinaufziehen, um wider sie zu streiten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Und Jehova sprach: Juda soll hinaufziehen; siehe, ich habe das Land in seine Hand gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Und Juda sprach zu Simeon, seinem Bruder: Ziehe mit mir hinauf in mein Los, und laß uns wider die Kanaaniter streiten, so will auch ich mit dir in dein Los ziehen. Und Simeon zog mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Und Juda zog hinauf, und Jehova gab die Kanaaniter und die Perisiter in ihre Hand; und sie schlugen sie zu Besek, zehntausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Und sie fanden den Adoni-Besek und stritten wider ihn; und sie schlugen die Kanaaniter und die Perisiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Und Adoni-Besek floh; und sie jagten ihm nach und ergriffen ihn und hieben ihm die Daumen seiner Hände und seiner Füße ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Da sprach Adoni-Besek: Siebzig Könige, denen die Daumen ihrer Hände und ihrer Füße abgehauen waren, lasen auf unter meinem Tische; so wie ich getan habe, also hat Gott mir vergolten. Und sie brachten ihn nach Jerusalem, und er starb daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Und die Kinder Juda stritten wider Jerusalem und nahmen es ein und schlugen es mit der Schärfe des Schwertes, und die Stadt steckten sie in Brand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Und danach zogen die Kinder Juda hinab, um wider die Kanaaniter zu streiten, die das Gebirge und den Süden und die Niederung bewohnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Und Juda zog wider die Kanaaniter, die in Hebron wohnten; der Name Hebrons war aber vordem Kirjath-Arba; und sie schlugen Scheschai und Achiman und Talmai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Und er zog von dannen wider die Bewohner von Debir; der Name von Debir war aber vordem Kirjath-Sepher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Und Kaleb sprach: Wer Kirjath-Sepher schlägt und es einnimmt, dem gebe ich meine Tochter Aksa zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Da nahm es Othniel ein, der Sohn Kenas\', der jüngere Bruder Kalebs; und er gab ihm seine Tochter Aksa zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Und es geschah, als sie einzog, da trieb sie ihn an, ein Feld von ihrem Vater zu fordern. Und sie sprang von dem Esel herab. Und Kaleb sprach zu ihr: Was ist dir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Und sie sprach zu ihm: Gib mir einen Segen; denn ein Mittagsland hast du mir gegeben, so gib mir auch Wasserquellen! Da gab ihr Kaleb die oberen Quellen und die unteren Quellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Und die Kinder des Keniters, des Schwagers Moses, waren mit den Kindern Juda aus der Palmenstadt heraufgezogen in die Wüste Juda, die im Süden von Arad liegt; und sie gingen hin und wohnten bei dem Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Und Juda zog mit seinem Bruder Simeon hin, und sie schlugen die Kanaaniter, welche Zephat bewohnten; und sie verbannten es und gaben der Stadt den Namen Horma.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Und Juda nahm Gasa ein und sein Gebiet, und Askalon und sein Gebiet, und Ekron und sein Gebiet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Und Jehova war mit Juda, und er nahm das Gebirge in Besitz; denn die Bewohner der Niederung trieb er nicht aus, weil sie eiserne Wagen hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Und sie gaben dem Kaleb Hebron, so wie Mose geredet hatte; und er vertrieb daraus die drei Söhne Enaks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Aber die Kinder Benjamin trieben die Jebusiter, die Bewohner von Jerusalem, nicht aus; und die Jebusiter haben bei den Kindern Benjamin in Jerusalem gewohnt bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Und das Haus Joseph, auch sie zogen nach Bethel hinauf, und Jehova war mit ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Und das Haus Joseph ließ Bethel auskundschaften; vordem war aber Lus der Name der Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Und die Wachen sahen einen Mann aus der Stadt herauskommen, und sie sprachen zu ihm: Zeige uns doch den Zugang zu der Stadt, so werden wir dir Güte erweisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Und er zeigte ihnen den Zugang zu der Stadt. Und sie schlugen die Stadt mit der Schärfe des Schwertes, aber den Mann und sein ganzes Geschlecht ließen sie gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Und der Mann zog in das Land der Hethiter; und er baute eine Stadt und gab ihr den Namen Lus. Das ist ihr Name bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Aber Manasse trieb nicht aus Beth-Schean und seine Tochterstädte, und Taanak und seine Tochterstädte, und die Bewohner von Dor und seine Tochterstädte, und die Bewohner von Jibleam und seine Tochterstädte, und die Bewohner von Megiddo und seine Tochterstädte; und die Kanaaniter wollten in diesem Lande bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Und es geschah als Israel erstarkte, da machte es die Kanaaniter fronpflichtig; aber es trieb sie keineswegs aus. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Und Ephraim trieb die Kanaaniter nicht aus, die zu Geser wohnten; und die Kanaaniter wohnten in ihrer Mitte zu Geser. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Sebulon trieb nicht aus die Bewohner von Kitron und die Bewohner von Nahalol; und die Kanaaniter wohnten in ihrer Mitte und wurden fronpflichtig. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Aser trieb nicht aus die Bewohner von Akko und die Bewohner von Zidon und Achlab und Aksib und Helba und Aphik und Rechob;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'und die Aseriter wohnten inmitten der Kanaaniter, der Bewohner des Landes, denn sie trieben sie nicht aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Naphtali trieb nicht aus die Bewohner von Beth-Semes und die Bewohner von Beth-Anath; und er wohnte inmitten der Kanaaniter, der Bewohner des Landes; aber die Bewohner von Beth-Semes und von Beth-Anath wurden ihm fronpflichtig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Und die Amoriter drängten die Kinder Dan ins Gebirge, denn sie gestatteten ihnen nicht, in die Niederung herabzukommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Und die Amoriter wollten im Gebirge Heres bleiben, in Ajjalon und in Schaalbim; aber die Hand des Hauses Joseph war schwer, und sie wurden fronpflichtig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Und die Grenze der Amoriter war von der Anhöhe Akrabbim, von dem Felsen an und aufwärts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Und der Engel Jehovas kam von Gilgal herauf nach Bochim; und er sprach: Ich habe euch aus Ägypten heraufgeführt und euch in das Land gebracht, das ich euren Vätern zugeschworen habe; und ich sagte: Ich werde meinen Bund mit euch nicht brechen ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Ihr aber, ihr sollt keinen Bund mit den Bewohnern dieses Landes machen, ihre Altäre sollt ihr niederreißen. Aber ihr habt meiner Stimme nicht gehorcht. Was habt ihr da getan!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'So habe ich auch gesagt: Ich werde sie nicht vor euch vertreiben; und sie werden zu euren Seiten sein, und ihre Götter werden euch zum Fallstrick werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Und es geschah, als der Engel Jehovas diese Worte zu allen Kindern Israel redete, da erhob das Volk seine Stimme und weinte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Und sie gaben selbigem Orte den Namen Bochim. Und sie opferten daselbst dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Und Josua entließ das Volk, und die Kinder Israel gingen hin, ein jeder in sein Erbteil, um das Land in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Und das Volk diente Jehova alle Tage Josuas und alle Tage der Ältesten, welche ihre Tage nach Josua verlängerten, die das ganze große Werk Jehovas gesehen, das er für Israel getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Und Josua, der Sohn Nuns, der Knecht Jehovas, starb, hundertzehn Jahre alt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Und man begrub ihn im Gebiete seines Erbteils, zu Timnath-Heres auf dem Gebirge Ephraim, nördlich vom Berge Gaasch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Und auch das ganze selbige Geschlecht wurde zu seinen Vätern versammelt. Und ein anderes Geschlecht kam nach ihnen auf, das Jehova nicht kannte und auch nicht das Werk, welches er für Israel getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Und die Kinder Israel taten, was böse war in den Augen Jehovas und dienten den Baalim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Und sie verließen Jehova, den Gott ihrer Väter, der sie aus dem Lande Ägypten herausgeführt hatte; und sie gingen anderen Göttern nach, von den Göttern der Völker, die rings um sie her waren, und sie warfen sich vor ihnen nieder und reizten Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Und sie verließen Jehova und dienten dem Baal und den Astaroth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Da entbrannte der Zorn Jehovas wider Israel, und er gab sie in die Hand von Plünderern, welche sie plünderten; und er verkaufte sie in die Hand ihrer Feinde ringsum; und sie vermochten nicht mehr vor ihren Feinden zu bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Überall, wohin sie auszogen, war die Hand Jehovas wider sie zum Bösen, so wie Jehova geredet und wie Jehova ihnen geschworen hatte; und sie wurden sehr bedrängt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Und Jehova erweckte Richter; und sie retteten sie aus der Hand ihrer Plünderer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Aber auch ihren Richtern gehorchten sie nicht, denn sie hurten anderen Göttern nach und warfen sich vor ihnen nieder; sie wichen schnell ab von dem Wege, den ihre Väter gewandelt waren, indem sie den Geboten Jehovas gehorchten; sie taten nicht also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Und wenn Jehova ihnen Richter erweckte, so war Jehova mit dem Richter, und er rettete sie aus der Hand ihrer Feinde alle Tage des Richters; denn Jehova ließ sich\'s gereuen wegen ihrer Wehklage vor ihren Bedrückern und ihren Drängern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Und es geschah, wenn der Richter starb, so verderbten sie sich wiederum, mehr als ihre Väter, indem sie anderen Göttern nachgingen, um ihnen zu dienen und sich vor ihnen niederzuwerfen. Sie ließen nichts fallen von ihren Taten und von ihrem hartnäckigen Wandel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Da entbrannte der Zorn Jehovas wider Israel, und er sprach: Darum daß diese Nation meinen Bund übertreten hat, den ich ihren Vätern geboten, und sie meiner Stimme nicht gehorcht haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'so werde auch ich hinfort niemand vor ihnen austreiben von den Nationen, die Josua übriggelassen hat, als er starb:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'um Israel durch sie zu versuchen, ob sie auf den Weg Jehovas achten werden, darauf zu wandeln, wie ihre Väter auf ihn geachtet haben, oder nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Und so ließ Jehova diese Nationen bleiben, so daß er sie nicht schnell austrieb; und er gab sie nicht in die Hand Josuas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Und dies sind die Nationen, welche Jehova bleiben ließ, um Israel durch sie zu versuchen, alle, die nichts wußten von allen Kriegen Kanaans-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'nur damit die Geschlechter der Kinder Israel Kenntnis von denselben bekämen, um sie den Krieg zu lehren: nur die, welche vordem nichts von denselben gewußt hatten: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'die fünf Fürsten der Philister und alle Kanaaniter und Zidonier und Hewiter, welche das Gebirge Libanon bewohnten, von dem Berge Baal-Hermon an, bis man nach Hamath kommt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Und sie dienten dazu, Israel durch sie zu versuchen, um zu wissen, ob sie den Geboten Jehovas gehorchen würden, welche er ihren Vätern durch Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Und die Kinder Israel wohnten inmitten der Kanaaniter, der Hethiter und der Amoriter und der Perisiter und der Hewiter und der Jebusiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'und sie nahmen sich deren Töchter zu Weibern und gaben ihre Töchter deren Söhnen und dienten ihren Göttern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Und die Kinder Israel taten, was böse war in den Augen Jehovas und vergaßen Jehovas, ihres Gottes, und sie dienten den Baalim und den Ascheroth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Da entbrannte der Zorn Jehovas wider Israel, und er verkaufte sie in die Hand Kuschan-Rischathaims, des Königs von Mesopotamien; und die Kinder Israel dienten dem Kuschan-Rischathaim acht Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Und die Kinder Israel schrieen zu Jehova; und Jehova erweckte den Kindern Israel einen Retter, der sie rettete: Othniel, den Sohn Kenas\', den jüngeren Bruder Kalebs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Und der Geist Jehovas kam über ihn, und er richtete Israel; und er zog aus zum Streite, und Jehova gab Kuschan-Rischathaim, den König von Aram, in seine Hand, und seine Hand wurde stark wider Kuschan-Rischathaim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Und das Land hatte Ruhe vierzig Jahre. Und Othniel, der Sohn Kenas\', starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Und die Kinder Israel taten wiederum, was böse war in den Augen Jehovas; und Jehova stärkte Eglon, den König von Moab, wider Israel, weil sie taten, was böse war in den Augen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Und er versammelte zu sich die Kinder Ammon und Amalek; und er zog hin und schlug Israel, und sie nahmen die Palmenstadt in Besitz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Und die Kinder Israel dienten Eglon, dem König von Moab, achtzehn Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Und die Kinder Israel schrien zu Jehova; und Jehova erweckte ihnen einen Retter, Ehud, den Sohn Geras, einen Benjaminiter, einen Mann, der links war. Und die Kinder Israel sandten durch ihn ein Geschenk an Eglon, den König von Moab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Und Ehud machte sich ein Schwert, das zwei Schneiden hatte, eine Elle seine Länge; und er gürtete es unter seinen Rock an seine rechte Hüfte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Und er überreichte das Geschenk Eglon, dem König von Moab. Eglon war aber ein sehr fetter Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Und es geschah, als er mit der Überreichung des Geschenkes fertig war, da geleitete er das Volk, welches das Geschenk getragen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Er selbst aber kehrte um von den geschnitzten Bildern, die bei Gilgal waren, und sprach: Ein geheimes Wort habe ich an dich, o König! Und er sprach: Stille! Und alle, die bei ihm standen, gingen von ihm hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Und als Ehud zu ihm hereinkam, saß er in dem Obergemach der Kühlung, das für ihn allein war. Und Ehud sprach: Ein Wort Gottes habe ich an dich. Und er stand auf vom Stuhle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Da streckte Ehud seine linke Hand aus und nahm das Schwert von seiner rechten Hüfte und stieß es ihm in den Bauch;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'und es drang sogar der Griff hinein nach der Klinge, und das Fett schloß sich um die Klinge; denn er zog das Schwert nicht aus seinem Bauche, und es fuhr hinaus zwischen den Beinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Und Ehud ging in die Säulenhalle hinaus und schloß die Tür des Obergemachs hinter ihm zu und verriegelte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Und als er hinausgegangen war, da kamen seine Knechte und sahen, und siehe, die Tür des Obergemachs war verriegelt. Und sie sprachen: Gewiß bedeckt er seine Füße in dem Gemach der Kühlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Und sie warteten, bis sie sich schämten; aber siehe, er öffnete die Tür des Obergemachs nicht; da nahmen sie den Schlüssel und schlossen auf, und siehe, ihr Herr lag tot am Boden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Ehud aber war entronnen, während sie zögerten: er war über die geschnitzten Bilder hinausgelangt und entrann nach Seira.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Und es geschah, als er ankam, da stieß er in die Posaune auf dem Gebirge Ephraim; und die Kinder Israel zogen mit ihm von dem Gebirge hinab, und er vor ihnen her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Und er sprach zu ihnen: Jaget mir nach, denn Jehova hat eure Feinde, die Moabiter, in eure Hand gegeben! Und sie zogen hinab, ihm nach, und nahmen den Moabitern die Furten des Jordan, und ließen niemand hinübergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Und sie schlugen die Moabiter zu selbiger Zeit, bei zehntausend Mann, lauter kräftige und streitbare Männer, und keiner entrann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Und Moab wurde an selbigem Tage unter die Hand Israels gebeugt. Und das Land hatte Ruhe achtzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Und nach ihm war Schamgar, der Sohn Anaths; und er schlug die Philister, sechshundert Mann, mit einem Rinderstachel. Und auch er rettete Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Und die Kinder Israel taten wiederum, was böse war in den Augen Jehovas; und Ehud war gestorben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Da verkaufte sie Jehova in die Hand Jabins, des Königs der Kanaaniter, der zu Hazor regierte; und sein Heeroberster war Sisera, und er wohnte zu Haroscheth-Gojim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Und die Kinder Israel schrieen zu Jehova; denn er hatte neunhundert eiserne Wagen, und er bedrückte die Kinder Israel mit Gewalt zwanzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Und Debora, eine Prophetin, das Weib Lappidoths, richtete Israel in selbiger Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Und sie wohnte unter der Debora-Palme zwischen Rama und Bethel, auf dem Gebirge Ephraim; und die Kinder Israel gingen zu ihr hinauf zu Gericht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Und sie sandte hin und ließ Barak, den Sohn Abinoams, von Kedes-Naphtali, rufen; und sie sprach zu ihm: Hat nicht Jehova, der Gott Israels, geboten: Gehe hin und ziehe auf den Berg Tabor, und nimm mit dir zehntausend Mann von den Kindern Naphtali und von den Kindern Sebulon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'und ich werde Sisera, den Heerobersten Jabins, zu dir ziehen an den Bach Kison samt seinen Wagen und seiner Menge, und ich werde ihn in deine Hand geben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Und Barak sprach zu ihr: Wenn du mit mir gehst, so gehe ich; wenn du aber nicht mit mir gehst, so gehe ich nicht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Da sprachen sie: Ich will wohl mit dir gehen; nur daß die Ehre nicht dein sein wird auf dem Wege, den du gehst, denn in die Hand eines Weibes wird Jehova den Sisera verkaufen. Und Debora machte sich auf und ging mit Barak nach Kedes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Und Barak berief Sebulon und Naphtali nach Kedes; und zehntausend Mann zogen in seinem Gefolge hinauf; auch Debora zog mit ihm hinauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, '(Heber aber, der Keniter, hatte sich von den Kenitern, den Kindern Hobabs, des Schwagers Moses, getrennt; und er hatte seine Zelte aufgeschlagen bis an die Terebinthe zu Zaanannim, das neben Kedes liegt.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Und man berichtete dem Sisera, daß Barak, der Sohn Abinoams, auf den Berg Tabor hinaufgezogen wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Da berief Sisera alle seine Wagen, neunhundert eiserne Wagen, und alles Volk, das mit ihm war, von Haroscheth-Gojim an den Bach Kison.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Und Debora sprach zu Barak: Mache dich auf! Denn dies ist der Tag, da Jehova den Sisera in deine Hand gegeben hat. Ist nicht Jehova ausgezogen vor dir her? Und Barak stieg von dem Berge Tabor hinab, und zehntausend Mann ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Und Jehova verwirrte Sisera und alle seine Wagen und das ganze Heerlager durch die Schärfe des Schwertes vor Barak her; und Sisera stieg von dem Wagen herab und floh zu Fuß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Barak aber jagte den Wagen und dem Heere nach bis Haroscheth-Gojim; und das ganze Heer Siseras fiel durch die Schärfe des Schwertes: Es blieb auch nicht einer übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Und Sisera floh zu Fuß in das Zelt Jaels, des Weibes Hebers, des Keniters; denn es war Friede zwischen Jabin, dem König von Hazor, und dem Hause Hebers, des Keniters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Da ging Jael hinaus, dem Sisera entgegen; und sie sprach zu ihm: Kehre ein, mein Herr, kehre ein zu mir, fürchte dich nicht! Und er kehrte ein zu ihr in das Zelt, und sie bedeckte ihn mit einer Decke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Und er sprach zu ihr: Laß mich doch ein wenig Wasser trinken, denn mich dürstet. Und sie öffnete den Milchschlauch und ließ ihn trinken, und sie deckte ihn zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Und er sprach zu ihr: Stelle dich an den Eingang des Zeltes; und es geschehe, wenn jemand kommt und dich fragt und spricht: Ist jemand hier? So sage: Niemand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Und Jael, das Weib Hebers, nahm einen Zeltpflock und faßte den Hammer in ihre Hand, und sie kam leise zu ihm und schlug den Pflock durch seine Schläfe, daß er in die Erde drang. Er war nämlich in einen tiefen Schlaf gefallen und war ermattet, und er starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Und siehe, da kam Barak, der Sisera verfolgte; und Jael ging hinaus, ihm entgegen, und sprach zu ihm: Komm, ich will dir den Mann zeigen, den du suchst! Und er ging zu ihr hinein, und siehe, Sisera lag tot, und der Pflock war in seiner Schläfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'So beugte Gott an selbigem Tage Jabin, den König von Kanaan, vor den Kindern Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Und die Hand der Kinder Israel wurde fort und fort härter über Jabin, den König von Kanaan, bis sie Jabin, den König von Kanaan, vernichtet hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Und Debora und Barak, der Sohn Abinoams, sangen an selbigem Tage und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Weil Führer führten in Israel, weil freiwillig sich stellte das Volk, preiset Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Höret, ihr Könige; horchet auf, ihr Fürsten! Ich will, ja, ich will Jehova singen und spielen Jehova, dem Gott Israels!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Jehova! Als du auszogest von Seir, als du einherschrittest vom Gefilde Edoms, da erzitterte die Erde; auch troffen die Himmel, auch troffen die Wolken von Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Die Berge erbebten vor Jehova, jener Sinai vor Jehova, dem Gott Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'In den Tagen Schamgars, des Sohnes Anaths, in den Tagen Jaels feierten die Pfade, und die Wanderer betretener Wege gingen krumme Pfade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Es feierten die Landstädte in Israel, sie feierten, bis ich, Debora, aufstand, bis ich aufstand, eine Mutter in Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Es erwählte neue Götter; da war Streit an den Toren! Ward wohl Schild und Lanze gesehen unter vierzigtausend in Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Mein Herz gehört den Führern Israels, denen, die sich freiwillig stellten im Volke. Preiset Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Die ihr reitet auf weißroten Eselinnen, die ihr sitzet auf Teppichen, und die ihr wandelt auf dem Wege, singet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Fern von der Stimme der Bogenschützen, zwischen den Schöpfrinnen, dort sollen sie preisen die gerechten Taten Jehovas, die gerechten Taten an seinen Landstädten in Israel. Da zog das Volk Jehovas hinab zu den Toren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Wache auf, wache auf, Debora! Wache auf, wache auf, sprich ein Lied! Mache dich auf, Barak, und führe gefangen deine Gefangenen, Sohn Abinoams!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Da zog hinab ein Überrest der Edlen und des Volkes; Jehova zog zu mir herab unter den Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Von Ephraim zogen hinab, deren Stammsitz unter Amalek ist; hinter dir her Benjamin, unter deinen Völkern; von Makir zogen hinab die Führer, und von Sebulon, die den Feldherrnstab halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Und die Fürsten in Issaschar waren mit Debora; und Issaschar gleich Barak; er wurde seinen Füßen nach ins Tal gesandt. An den Bächen Rubens waren große Beschlüsse des Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Warum bliebest du zwischen den Hürden, das Flöten bei den Herden zu hören? An den Bächen Rubens waren große Beratungen des Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead ruhte jenseit des Jordan; und Dan, warum weilte er auf Schiffen? Aser blieb am Gestade des Meeres, und an seinen Buchten ruhte er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Sebulon ist ein Volk, das seine Seele dem Tode preisgab, auch Naphtali auf den Höhen des Gefildes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Könige kamen, sie stritten; da stritten die Könige Kanaans zu Taanak an den Wassern Megiddos: Beute an Silber trugen sie nicht davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Vom Himmel her stritten, von ihren Bahnen aus stritten die Sterne mit Sisera.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Der Bach Kison riß sie hinweg, der Bach der Urzeit, der Bach Kison. Du, meine Seele, tratest die Starken nieder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Da stampften die Hufe der Rosse vom Rennen, dem Rennen ihrer Gewaltigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Fluchet Meros! spricht der Engel Jehovas, verfluchet seine Bewohner! Denn sie sind nicht Jehova zu Hilfe gekommen, Jehova zu Hilfe unter den Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Gesegnet vor Weibern sei Jael, das Weib Hebers, des Keniters, vor Weibern in Zelten gesegnet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Wasser verlangte er, Milch gab sie; in einer Schale der Edlen reichte sie geronnene Milch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Ihre Hand streckte sie aus nach dem Pflocke und ihre Rechte nach dem Hammer der Arbeiter; und sie hämmerte auf Sisera, zerschmetterte sein Haupt und zerschlug und durchbohrte seine Schläfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Zwischen ihren Füßen krümmte er sich, fiel, lag da; zwischen ihren Füßen krümmte er sich, fiel; da, wo er sich krümmte, fiel er überwältigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Durchs Fenster schaute aus Siseras Mutter und rief ängstlich durch das Gitter: Warum zaudert sein Wagen zu kommen? Warum zögern die Tritte seiner Gespanne?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Die Klugen unter ihren Edelfrauen antworten ihr, und sie selbst erwidert sich ihre Reden:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Finden sie nicht, teilen sie nicht Beute? Ein Mädchen, zwei Mädchen auf den Kopf eines Mannes? Beute an bunten Gewändern für Sisera, Beute an buntgewirkten Gewändern; zwei buntgewirkte Gewänder für den Hals der Gefangenen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Also mögen umkommen alle deine Feinde, Jehova! Aber die ihn lieben, seien wie die Sonne aufgeht in ihrer Kraft! Und das Land hatte Ruhe vierzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Und die Kinder Israel taten, was böse war in den Augen Jehovas; und Jehova gab sie in die Hand Midians sieben Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Und die Hand Midians wurde stark über Israel. Vor Midian richteten sich die Kinder Israel die Klüfte zu, die in den Bergen sind, und die Höhlen und die Bergfesten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Und es geschah, wenn Israel gesät hatte, so zogen Midian und Amalek und die Söhne des Ostens herauf, sie zogen herauf wider sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Und sie lagerten sich wider sie und verdarben den Ertrag des Landes bis nach Gasa hin; und sie ließen keine Lebensmittel in Israel übrig, weder Kleinvieh, noch Rind, noch Esel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Denn sie zogen herauf mit ihren Herden und mit ihren Zelten, sie kamen wie die Heuschrecken an Menge; und ihrer und ihrer Kamele war keine Zahl; und sie kamen in das Land, um es zu verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Und Israel verarmte sehr wegen Midians; und die Kinder Israel schrieen zu Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Und es geschah, als die Kinder Israel wegen Midians zu Jehova schrieen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'da sandte Jehova einen Propheten zu den Kindern Israel; und er sprach zu ihnen: So spricht Jehova, der Gott Israels: Ich habe euch aus Ägypten heraufgeführt und euch herausgeführt aus dem Hause der Knechtschaft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'und ich habe euch errettet aus der Hand der Ägypter und aus der Hand all eurer Bedrücker, und ich habe sie vor euch vertrieben und euch ihr Land gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Und ich sprach zu euch: Ich bin Jehova, euer Gott; ihr sollt nicht die Götter der Amoriter fürchten, in deren Land ihr wohnet. Aber ihr habt meiner Stimme nicht gehorcht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Und der Engel Jehovas kam und setzte sich unter die Terebinthe, die zu Ophra war, welches Joas, dem Abieseriter, gehörte. Und Gideon, sein Sohn, schlug eben Weizen aus in der Kelter, um ihn vor Midian zu flüchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Und der Engel Jehovas erschien ihm und sprach zu ihm: Jehova ist mit dir, du tapferer Held!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Und Gideon sprach zu ihm: Bitte, mein Herr! Wenn Jehova mit uns ist, warum hat denn dieses alles uns betroffen? Und wo sind alle seine Wunder, die unsere Väter uns erzählt haben, indem sie sprachen: Hat Jehova uns nicht aus Ägypten heraufgeführt? Und nun hat Jehova uns verlassen und uns in die Hand Midians gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Und Jehova wandte sich zu ihm und sprach: Gehe hin in dieser deiner Kraft und rette Israel aus der Hand Midians! Habe ich dich nicht gesandt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Und er sprach zu ihm: Bitte, mein Herr! Womit soll ich Israel retten? Siehe, mein Tausend ist das ärmste in Manasse, und ich bin der Jüngste im Hause meines Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Und Jehova sprach zu ihm: Ich werde mit dir sein, und du wirst Midian schlagen wie einen Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Und er sprach zu ihm: Wenn ich denn Gnade gefunden habe in deinen Augen, so gib mir ein Zeichen, daß du es bist, der mit mir redet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Weiche doch nicht von hinnen, bis ich zu dir komme und meine Gabe herausbringe und dir vorsetze. Und er sprach: Ich will bleiben, bis du wiederkommst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Da ging Gideon hinein und bereitete ein Ziegenböcklein zu, und ungesäuerte Kuchen aus einem Epha Mehl; das Fleisch tat er in einen Korb, und die Brühe tat er in einen Topf; und er brachte es zu ihm heraus unter die Terebinthe und setzte es vor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Und der Engel Gottes sprach zu ihm: Nimm das Fleisch und die ungesäuerten Kuchen und lege es hin auf diesen Felsen da, und die Brühe gieße aus. Und er tat also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Und der Engel Jehovas streckte das Ende des Stabes aus, der in seiner Hand war, und berührte das Fleisch und die ungesäuerten Kuchen; da stieg Feuer auf aus dem Felsen und verzehrte das Fleisch und die ungesäuerten Kuchen. Und der Engel Jehovas verschwand aus seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Da sah Gideon, daß es der Engel Jehovas war, und Gideon sprach: Ach Herr, Jehova! Dieweil ich den Engel Jehovas gesehen habe von Angesicht zu Angesicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Und Jehova sprach zu ihm: Friede dir! Fürchte dich nicht, du wirst nicht sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Und Gideon baute daselbst Jehova einen Altar und nannte ihn: Jehova-Schalom. Bis auf diesen Tag ist er noch zu Ophra der Abieseriter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Und es geschah in selbiger Nacht, da sprach Jehova zu ihm: Nimm den Farren deines Vaters, und zwar den zweiten Farren von sieben Jahren; und reiße nieder den Altar des Baal, der deinem Vater gehört, und die Aschera, die bei demselben ist, haue um;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'und baue Jehova, deinem Gott, einen Altar auf dem Gipfel dieser Feste mit der Zurüstung; und nimm den zweiten Farren und opfere ein Brandopfer mit dem Holze der Aschera, die du umhauen wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Und Gideon nahm zehn Männer von seinen Knechten und tat, so wie Jehova zu ihm geredet hatte. Und es geschah, da er sich vor dem Hause seines Vaters und vor den Leuten der Stadt fürchtete, es bei Tage zu tun, so tat er es bei Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Und als die Leute der Stadt des Morgens früh aufstanden, siehe, da war der Altar des Baal umgerissen, und die Aschera, die bei demselben war, umgehauen, und der zweite Farre war als Brandopfer auf dem erbauten Altar geopfert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Und sie sprachen einer zum anderen: Wer hat das getan? Und sie forschten und fragten nach, und man sagte: Gideon, der Sohn des Joas, hat das getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Da sprachen die Leute der Stadt zu Joas: Gib deinen Sohn heraus, daß er sterbe, weil er den Altar des Baal umgerissen, und weil er die Aschera, die bei demselben war, umgehauen hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Und Joas sprach zu allen, die bei ihm standen: Wollt ihr für den Baal rechten, oder wollt ihr ihn retten? Wer für ihn rechtet, soll getötet werden bis zum Morgen. Wenn er ein Gott ist, so rechte er für sich selbst, weil man seinen Altar umgerissen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Und man nannte ihn an selbigem Tage Jerub-Baal, indem man sprach: Der Baal rechte mit ihm, weil er seinen Altar umgerissen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Und ganz Midian und Amalek und die Söhne des Ostens versammelten sich allzumal, und sie setzten über den Jordan und lagerten sich im Tale Jisreel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Und der Geist Jehovas kam über Gideon; und er stieß in die Posaune, und die Abieseriter wurden zusammengerufen ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Und er sandte Boten durch ganz Manasse, und auch sie wurden zusammengerufen, ihm nach. Und er sandte Boten durch Aser und durch Sebulon und durch Naphtali. Und sie zogen herauf, ihnen entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Und Gideon sprach zu Gott: Wenn du Israel durch meine Hand retten willst, so wie du geredet hast-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'siehe, ich lege ein Wollvließ auf die Tenne; wenn Tau auf dem Vließe allein sein wird und auf dem ganzen Boden Trockenheit, so werde ich erkennen, daß du Israel durch meine Hand retten wirst, so wie du geredet hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Und es geschah also. Und er stand am anderen Morgen früh auf, und er drückte das Vließ aus und preßte Tau aus dem Vließe, eine Schale voll Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Und Gideon sprach zu Gott: Dein Zorn entbrenne nicht wider mich! Und ich will nur noch diesmal reden. Laß mich es doch nur noch diesmal mit dem Vließe versuchen: Möge doch Trockenheit sein auf dem Vließe allein, und auf dem ganzen Boden sei Tau.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Und Gott tat also in selbiger Nacht; und es war Trockenheit auf dem Vließe allein, und auf dem ganzen Boden war Tau.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Und Jerub-Baal, das ist Gideon, und alles Volk, das mit ihm war, machten sich früh auf, und sie lagerten sich an der Quelle Harod; das Lager Midians aber war nordwärts von ihm, nach dem Hügel More hin, im Tale.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Und Jehova sprach zu Gideon: Des Volkes, das bei dir ist, ist zu viel, als daß ich Midian in ihre Hand geben sollte; damit Israel sich nicht wider mich rühme und spreche: Meine Hand hat mich gerettet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Und nun rufe doch vor den Ohren des Volkes aus und sprich: Wer furchtsam und verzagt ist, kehre um und wende sich zurück vom Gebirge Gilead! Da kehrten von dem Volke zweiundzwanzigtausend um, und zehntausend blieben übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Und Jehova sprach zu Gideon: Noch ist des Volkes zu viel; führe sie ans Wasser hinab, daß ich sie dir daselbst läutere; und es soll geschehen, von wem ich dir sagen werde: dieser soll mit dir ziehen, der soll mit dir ziehen; und jeder, von dem ich dir sagen werde: dieser soll nicht mit dir ziehen, der soll nicht ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Und er führte das Volk ans Wasser hinab. Und Jehova sprach zu Gideon: Jeder, der mit seiner Zunge von dem Wasser leckt, wie ein Hund leckt, den stelle besonders; und auch jeden, der sich auf seine Knie niederläßt, um zu trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Und die Zahl derer, welche mit ihrer Hand zu ihrem Munde leckten, war dreihundert Mann; und das ganze übrige Volk hatte sich auf seine Knie niedergelassen, um Wasser zu trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Und Jehova sprach zu Gideon: Durch die dreihundert Mann, die geleckt haben, will ich euch retten und Midian in deine Hand geben; das ganze übrige Volk aber soll gehen, ein jeder an seinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Und sie nahmen die Zehrung des Volkes mit sich und seine Posaunen. Und er entließ alle Männer von Israel, einen jeden nach seinen Zelten; aber die dreihundert Mann behielt er. Das Lager Midians war aber unter ihm im Tale.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Und es geschah in selbiger Nacht, da sprach Jehova zu ihm: Mache dich auf, gehe in das Lager hinab; denn ich habe es in deine Hand gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Und wenn du dich fürchtest, hinabzugehen, so gehe mit Pura, deinem Knaben, zum Lager hinab;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'und du wirst hören, was sie reden; und danach werden deine Hände erstarken, und du wirst in das Lager hinabgehen. Da ging er mit Pura, seinem Knaben, hinab bis an das Ende der Gerüsteten, die im Lager waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Und Midian und Amalek und alle Söhne des Ostens lagen im Tale, wie die Heuschrecken an Menge; und ihrer Kamele war keine Zahl, wie der Sand, der am Ufer des Meeres ist, an Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Und Gideon kam, und siehe, ein Mann erzählte seinem Genossen einen Traum und sprach: Siehe, ich habe einen Traum gehabt; und siehe, ein Laib Gerstenbrot rollte in das Lager Midians; und es kam bis zum Zelte und schlug es, daß es umfiel, und kehrte es um, das Unterste zu oberst, und das Zelt lag da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Und sein Genosse antwortete und sprach: Das ist nichts anderes als das Schwert Gideons, des Sohnes Joas\', eines Mannes von Israel; Gott hat Midian und das ganze Lager in seine Hand gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Und es geschah, als Gideon die Erzählung des Traumes und seine Deutung hörte, da betete er an. Und er kehrte in das Lager Israels zurück und sprach: Machet euch auf! Denn Jehova hat das Lager Midians in eure Hand gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Und er teilte die dreihundert Mann in drei Haufen und gab ihnen allen Posaunen in die Hand und leere Krüge, und Fackeln in die Krüge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Und er sprach zu ihnen: Sehet es mir ab und tut ebenso; siehe, wenn ich an das Ende des Lagers komme, so soll es geschehen, daß ihr ebenso tut, wie ich tue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Und stoße ich in die Posaune, ich und alle, die bei mir sind, so sollt auch ihr in die Posaunen stoßen rings um das ganze Lager, und sollt rufen: Für Jehova und für Gideon!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Und Gideon und die hundert Mann, die bei ihm waren, kamen an das Ende des Lagers, beim Beginn der mittleren Nachtwache; man hatte eben die Wachen aufgestellt. Und sie stießen in die Posaunen und zerschmetterten die Krüge, die in ihrer Hand waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Und die drei Haufen stießen in die Posaunen und zerbrachen die Krüge; und sie hielten in ihrer linken Hand die Fackeln und in ihrer rechten Hand die Posaunen zum Blasen und riefen: Schwert Jehovas und Gideons!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Und sie standen ein jeder an seiner Stelle, rings um das Lager. Da lief das ganze Lager und schrie und floh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Und sie stießen in die dreihundert Posaunen; und Jehova richtete das Schwert des einen wider den anderen, und zwar im ganzen Lager. Und das Lager floh bis Beth-Schitta, nach Zerera hin, bis an das Ufer von Abel-Mehola bei Tabbath.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Und es versammelten sich die Männer von Israel, von Naphtali und von Aser und von ganz Manasse, und sie jagten Midian nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Und Gideon sandte Boten in das ganze Gebirge Ephraim und ließ sagen: Kommet herab, Midian entgegen, und nehmet ihnen die Gewässer bis Beth-Bara, und den Jordan! Da versammelten sich alle Männer von Ephraim und nahmen ihnen die Gewässer bis Beth-Bara und den Jordan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Und sie fingen die zwei Fürsten von Midian, Oreb und Seeb; und sie erschlugen Oreb an dem Felsen Oreb, und Seeb erschlugen sie bei der Kelter Seeb; und sie jagten Midian nach. Und die Köpfe Orebs und Seebs brachten sie zu Gideon auf die andere Seite des Jordan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Und die Männer von Ephraim sprachen zu ihm: Was ist das für eine Sache, die du uns getan, daß du uns nicht gerufen hast, als du hinzogest, um wider Midian zu streiten! Und sie zankten heftig mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Und er sprach zu ihnen: Was habe ich nun getan im Vergleich mit euch? Ist nicht die Nachlese Ephraims besser als die Weinlese Abiesers?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'In eure Hand hat Gott die Fürsten von Midian, Oreb und Seeb gegeben; und was habe ich tun können im Vergleich mit euch? Da ließ ihr Zorn von ihm ab, als er dieses Wort redete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Und Gideon kam an den Jordan; er ging hinüber, er und die dreihundert Mann, die bei ihm waren, ermattet und nachjagend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Und er sprach zu den Männern von Sukkoth: Gebet doch dem Volke, das mir nachfolgt, einige Laibe Brot; denn sie sind ermattet, und ich jage den Königen von Midian, Sebach und Zalmunna, nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Und die Obersten von Sukkoth sprachen: Ist die Faust Sebachs und Zalmunnas schon in deiner Hand, daß wir deinem Heere Brot geben sollen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Da sprach Gideon: Darum, wenn Jehova Sebach und Zalmunna in meine Hand gegeben hat, werde ich euer Fleisch zerdreschen mit Dornen der Wüste und mit Stechdisteln!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Und er zog von dannen nach Pnuel hinauf und redete zu ihnen auf dieselbe Weise. Und die Männer von Pnuel antworteten ihm, wie die Männer von Sukkoth geantwortet hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Da sprach er auch zu den Männern von Pnuel und sagte: Wenn ich in Frieden zurückkomme, so werde ich diesen Turm niederreißen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Sebach und Zalmunna waren aber zu Karkor, und ihre Heere mit ihnen, bei fünfzehntausend Mann, alle, die übriggeblieben waren von dem ganzen Lager der Söhne des Ostens; und der Gefallenen waren hundertundzwanzigtausend Mann, die das Schwert zogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Und Gideon zog hinauf des Weges zu den Zeltbewohnern, östlich von Nobach und Jogbeha; und er schlug das Lager, und das Lager war sorglos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Und Sebach und Zalmunna flohen, und er jagte ihnen nach; und er fing die beiden Könige von Midian, Sebach und Zalmunna; und das ganze Lager setzte er in Schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Und Gideon, der Sohn Joas\', kehrte aus dem Streite zurück, von der Anhöhe Heres herab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Und er fing einen Jüngling von den Männern von Sukkoth und befragte ihn; und dieser schrieb ihm die Obersten von Sukkoth und seine Ältesten auf, siebenundsiebzig Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Und er kam zu den Männern von Sukkoth und sprach: Sehet hier Sebach und Zalmunna, über welche ihr mich verhöhnt habt, indem ihr sprachet: Ist die Faust Sebachs und Zalmunnas schon in deiner Hand, daß wir deinen Männern, die ermattet sind, Brot geben sollen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Und er nahm die Ältesten der Stadt und Dornen der Wüste und Stechdisteln, und er züchtigte die Männer von Sukkoth mit denselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Und den Turm zu Pnuel riß er nieder und erschlug die Männer der Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Und er sprach zu Sebach und zu Zalmunna: Wie waren die Männer, die ihr zu Tabor erschlagen habt? Und sie sprachen: Wie du, so waren sie, ein jeder an Gestalt gleich einem Königssohne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Und er sprach: Das waren meine Brüder, die Söhne meiner Mutter. So wahr Jehova lebt, wenn ihr sie am Leben gelassen hättet, so erschlüge ich euch nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Und er sprach zu Jether, seinem Erstgeborenen: Stehe auf, erschlage sie! Aber der Knabe zog sein Schwert nicht; denn er fürchtete sich, weil er noch ein Knabe war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Da sprachen Sebach und Zalmunna: Stehe du auf und stoße uns nieder; denn wie der Mann, so seine Kraft. Und Gideon stand auf und erschlug Sebach und Zalmunna; und er nahm die Halbmonde, welche an den Hälsen ihrer Kamele waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Und die Männer von Israel sprachen zu Gideon: Herrsche über uns, sowohl du, als auch dein Sohn und deines Sohnes Sohn; denn du hast uns aus der Hand Midians gerettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Und Gideon sprach zu ihnen: Nicht ich will über euch herrschen, und nicht mein Sohn soll über euch herrschen; Jehova soll über euch herrschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Und Gideon sprach zu ihnen: Eine Bitte will ich von euch erbitten: Gebet mir ein jeder sie Ohrringe seiner Beute! (denn sie hatten goldene Ohrringe, weil sie Ismaeliter waren).');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Und sie sprachen: Gern wollen wir sie geben. Und sie breiteten ein Oberkleid aus und warfen darauf ein jeder die Ohrringe seiner Beute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Und das Gewicht der goldenen Ohrringe, die er erbeten hatte, war tausendsiebenhundert Sekel Gold, außer den Halbmonden und den Ohrgehängen und den Purpurkleidern, welche die Könige von Midian trugen, und außer den Halsketten, die an den Hälsen ihrer Kamele waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Und Gideon machte daraus ein Ephod und stellte es in seiner Stadt auf, in Ophra. Und ganz Israel hurte demselben dort nach; und es wurde Gideon und seinem Hause zum Fallstrick.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'So wurde Midian vor den Kindern Israels gebeugt, und es hob sein Haupt nicht mehr empor. Und das Land hatte in den Tagen Gideons Ruhe vierzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Und Jerub-Baal, der Sohn Joas\', ging hin und wohnte in seinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Und Gideon hatte siebzig Söhne, die aus seiner Lende hervorgegangen waren; denn er hatte viele Weiber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Und sein Kebsweib, das zu Sichem war, auch sie gebar ihm einen Sohn; und er gab ihm den Namen Abimelech.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Und Gideon, der Sohn Joas\', starb in gutem Alter; und er wurde begraben im Grabe seines Vaters Joas, zu Ophra der Abieseriter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Und es geschah, als Gideon tot war, da hurten die Kinder Israel wiederum den Baalim nach und machten sich den Baal-Berith zum Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Und die Kinder Israel gedachten nicht Jehovas, ihres Gottes, der sie errettet hatte aus der Hand aller ihrer Feinde ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Und sie erwiesen keine Güte an dem Hause Jerub-Baal-Gideons, nach all dem Guten, das er an Israel getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Und Abimelech, der Sohn Jerub-Baals, ging nach Sichem zu den Brüdern seiner Mutter; und er redete zu ihnen und zu dem ganzen Geschlecht des Hauses des Vaters seiner Mutter und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Redet doch vor den Ohren aller Bürger von Sichem: Was ist besser für euch, daß siebzig Männer über euch herrschen, alle Söhne Jerub-Baals, oder daß ein Mann über euch herrsche? Und bedenket, daß ich euer Gebein und euer Fleisch bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Und die Brüder seiner Mutter redeten von ihm vor den Ohren aller Bürger von Sichem alle diese Worte. Und ihr Herz neigte sich Abimelech nach; denn sie sprachen: Er ist unser Bruder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Und sie gaben ihm siebzig Sekel Silber aus dem Hause Baal-Berith; und Abimelech dingte damit lose und übermütige Männer, und sie folgten ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Und er kam in das Haus seines Vaters, nach Ophra, und ermordete seine Brüder, die Söhne Jerub-Baals, siebzig Mann auf einem Steine; aber Jotham, der jüngste Sohn Jerub-Baals, blieb übrig, denn er hatte sich versteckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Und alle Bürger von Sichem und das ganze Haus Millo versammelten sich und gingen hin und machten Abimelech zum König bei der Terebinthe des Denkmals, die zu Sichem ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Und man berichtete es Jotham. Da ging er hin und stellte sich auf den Gipfel des Berges Gerisim, und er erhob seine Stimme und rief und sprach zu ihnen: Höret auf mich, Bürger von Sichem, so wird Gott auf euch hören!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Einst gingen die Bäume hin, einen König über sich zu salben; und sie sprachen zum Olivenbaum: Sei König über uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Und der Olivenbaum sprach zu ihnen: Sollte ich meine Fettigkeit aufgeben, welche Götter und Menschen an mir preisen, und sollte hingehen, zu schweben über den Bäumen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Da sprachen die Bäume zum Feigenbaum: Komm du, sei König über uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Und der Feigenbaum sprach zu ihnen: Sollte ich meine Süßigkeit aufgeben und meine gute Frucht, und sollte hingehen, zu schweben über den Bäumen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Da sprachen die Bäume zum Weinstock: Komm du, sei König über uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Und der Weinstock sprach zu ihnen: Sollte ich meinen Most aufgeben, der Götter und Menschen erfreut, und sollte hingehen, zu schweben über den Bäumen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Da sprachen alle Bäume zum Dornstrauch: Komm du, sei König über uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Und der Dornstrauch sprach zu den Bäumen: Wenn ihr mich in Wahrheit zum König über euch salben wollt, so kommet, vertrauet euch meinem Schatten an; wenn aber nicht, so soll Feuer von dem Dornstrauch ausgehen und die Zedern des Libanon verzehren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Und nun, wenn ihr in Wahrheit und in Redlichkeit gehandelt habt, daß ihr Abimelech zum König gemacht, und wenn ihr Gutes getan habt an Jerub-Baal und an seinem Hause, und wenn ihr ihm getan habt nach dem Tun seiner Hände, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'denn mein Vater hat für euch gestritten und sein Leben dahingeworfen und euch aus der Hand Midians errettet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Ihr aber habt euch heute wider das Haus meines Vaters erhoben und seine Söhne ermordet, siebzig Mann auf einem Steine, und habt Abimelech, den Sohn seiner Magd, zum König gemacht über die Bürger von Sichem, weil er euer Bruder ist-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'wenn ihr also an diesem Tage in Wahrheit und in Redlichkeit an Jerub-Baal und an seinem Hause gehandelt habt, so freuet euch Abimelechs, und auch er möge sich euer freuen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Wenn aber nicht, so gehe Feuer von Abimelech aus und verzehre die Bürger von Sichem und das Haus Millo; und es gehe ein Feuer aus von den Bürgern von Sichem und von dem Hause Millo und verzehre Abimelech!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Und Jotham floh und entwich und ging nach Beer; und er blieb daselbst wegen seines Bruders Abimelech.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Und Abimelech herrschte über Israel drei Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Und Gott sandte einen bösen Geist zwischen Abimelech und die Bürger von Sichem; und die Bürger von Sichem handelten treulos gegen Abimelech,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'damit die Gewalttat an den siebzig Söhnen Jerub-Baals über ihn käme, und ihr Blut gelegt würde auf ihren Bruder Abimelech, der sie ermordet, und auf die Bürger von Sichem, die seine Hände gestärkt hatten, seine Brüder zu ermorden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Und die Bürger von Sichem legten einen Hinterhalt wider ihn auf die Gipfel der Berge, und sie beraubten jeden, der des Weges bei ihnen vorüberzog. Und es wurde dem Abimelech berichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Und Gaal, der Sohn Ebeds, kam mit seinen Brüdern, und sie zogen durch Sichem; und die Bürger von Sichem vertrauten ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Und sie gingen aufs Feld hinaus und lasen ihre Weinberge und kelterten; und sie hielten ein Dankfest und gingen in das Haus ihres Gottes und aßen und tranken und fluchten dem Abimelech.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Und Gaal, der Sohn Ebeds, sprach: Wer ist Abimelech und wer Sichem, daß wir ihm dienen sollten? Ist er nicht der Sohn Jerub-Baals, und Sebul sein Statthalter? Dienet den Männern Hemors, des Vaters von Sichem! Denn warum sollten wir ihm dienen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Hätte ich nur dieses Volk unter meiner Hand, so wollte ich Abimelech wegschaffen! Und er sprach von Abimelech: Mehre nur dein Heer und ziehe aus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Und Sebul, der Oberste der Stadt, hörte die Worte Gaals, des Sohnes Ebeds, und sein Zorn entbrannte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'und er sandte Boten an Abimelech mit List und sprach: Siehe, Gaal, der Sohn Ebeds, und seine Brüder sind nach Sichem gekommen, und siehe, sie wiegeln die Stadt wider dich auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Und nun, mache dich in der Nacht auf, du und das Volk, das bei dir ist, und lege dich in Hinterhalt auf dem Felde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Und es geschehe am Morgen, wenn die Sonne aufgeht, so mache dich früh auf und überfalle die Stadt; und siehe, wenn er und das Volk, das bei ihm ist, gegen dich hinausziehen, so tue ihm, wie deine Hand es finden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Und Abimelech und alles Volk, das mit ihm war, machten sich in der Nacht auf, und sie legten sich in vier Haufen gegen Sichem in Hinterhalt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Und Gaal, der Sohn Ebeds, ging hinaus und trat an den Eingang des Stadttores. Da machten sich Abimelech und das Volk, das bei ihm war, aus dem Hinterhalt auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Und Gaal sah das Volk und sprach zu Sebul: Siehe, Volk kommt von den Gipfeln der Berge herab. Und Sebul sprach zu ihm: Den Schatten der Berge siehst du für Männer an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Und Gaal redete wiederum und sprach: Siehe, Volk kommt von der Höhe des Landes herab, und ein Haufe kommt des Weges nach Elon-Meonenim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Da sprach Sebul zu ihm: Wo ist nun dein Maul, da du sprachest: Wer ist Abimelech, daß wir ihm dienen sollten? Ist das nicht das Volk, welches du verachtet hast? Ziehe doch jetzt aus und streite wider ihn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Und Gaal zog aus vor den Bürgern von Sichem und stritt wider Abimelech.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Und Abimelech jagte ihm nach, und er floh vor ihm; und es fielen viele Erschlagene bis an den Eingang des Tores.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Und Abimelech blieb zu Aruma; und Sebul vertrieb Gaal und seine Brüder, so daß sie nicht mehr in Sichem blieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Und es geschah am anderen Tage, da ging das Volk aufs Feld hinaus; und man berichtete es dem Abimelech.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Und er nahm das Volk und teilte es in drei Haufen und legte sich in Hinterhalt auf dem Felde. Und er sah, und siehe, das Volk kam aus der Stadt heraus; und er erhob sich wider sie und schlug sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Und Abimelech und die Haufen, die mit ihm waren, brachen hervor und stellten sich an den Eingang des Stadttores; und zwei der Haufen fielen über alle her, die auf dem Felde waren, und erschlugen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Und Abimelech stritt wider die Stadt jenen ganzen Tag; und er nahm die Stadt ein, und das Volk, das darin war, tötete er; und er riß die Stadt nieder und bestreute sie mit Salz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Und alle Bewohner des Turmes von Sichem hörten es, und sie gingen in die Burg des Hauses des Gottes Berith.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Und es wurde dem Abimelech berichtet, daß alle Bewohner des Turmes von Sichem sich versammelt hätten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Da stieg Abimelech auf den Berg Zalmon, er und alles Volk, das bei ihm war; und Abimelech nahm eine Axt in seine Hand und hieb einen Baumast ab und hob ihn auf und legte ihn auf seine Schulter, und er sprach zu dem Volke, das mit ihm war: Was ihr gesehen habt, das ich getan habe, das tut eilends wie ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Da hieb auch das ganze Volk ein jeder seinen Ast ab, und sie folgten Abimelech nach und legten sie an die Burg und zündeten die Burg über ihnen mit Feuer an. Und so starben auch alle Leute des Turmes von Sichem, bei tausend Männer und Weiber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Und Abimelech zog nach Tebez, und er belagerte Tebez und nahm es ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Es war aber ein starker Turm mitten in der Stadt, und dahin flohen alle Männer und Weiber, alle Bürger der Stadt; und sie schlossen hinter sich zu und stiegen auf das Dach des Turmes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Und Abimelech kam an den Turm und stritt wider ihn; und er nahte zum Eingang des Turmes, um ihn mit Feuer zu verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Da warf ein Weib den oberen Stein einer Handmühle auf den Kopf Abimelechs und zerschmetterte ihm den Schädel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Und er rief eilends den Knaben, der seine Waffen trug, und sprach zu ihm: Ziehe dein Schwert und töte mich, daß man nicht von mir sage: Ein Weib hat ihn umgebracht! Und sein Knabe durchstach ihn, und er starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Und als die Männer von Israel sahen, daß Abimelech tot war, da gingen sie ein jeder an seinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Und so brachte Gott die Bosheit Abimelechs, die er an seinem Vater verübt hatte, indem er seine siebzig Brüder ermordete, auf ihn zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Und die ganze Bosheit der Männer von Sichem brachte Gott auf ihren Kopf zurück, und es kam über sie der Fluch Jothams, des Sohnes Jerub-Baals.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Und nach Abimelech stand Tola auf, um Israel zu retten, der Sohn Puas, des Sohnes Dodos, ein Mann von Issaschar; und er wohnte zu Schamir im Gebirge Ephraim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Und er richtete Israel dreiundzwanzig Jahre; und er starb und wurde zu Schamir begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Und nach ihm stand Jair, der Gileaditer, auf; und er richtete Israel zweiundzwanzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Und er hatte dreißig Söhne, die auf dreißig Eseln ritten, und sie hatten dreißig Städte; diese nennt man bis auf diesen Tag die Dörfer Jairs, welche im Lande Gilead sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Und Jair starb und wurde zu Kamon begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Und die Kinder Israel taten wiederum, was böse war in den Augen Jehovas, und sie dienten den Baalim und den Astaroth, und den Göttern Syriens und den Göttern Zidons und den Göttern Moabs und den Göttern der Kinder Ammon und den Göttern der Philister; und sie verließen Jehova und dienten ihm nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Da entbrannte der Zorn Jehovas wider Israel, und er verkaufte sie in die Hand der Philister und in die Hand der Kinder Ammon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Und sie bedrückten und plagten die Kinder Israel in selbigem Jahre; achtzehn Jahre bedrückten sie alle Kinder Israel, welche jenseit des Jordan waren im Lande der Amoriter, das in Gilead ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Und die Kinder Ammon zogen über den Jordan, um auch wider Juda und wider Benjamin und wider das Haus Ephraim zu streiten; und Israel wurde sehr bedrängt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Da schrieen die Kinder Israel zu Jehova und sprachen: Wir haben gegen dich gesündigt, und zwar weil wir unseren Gott verlassen und den Baalim gedient haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Und Jehova sprach zu den Kindern Israel: Habe ich euch nicht von den Ägyptern und von den Amoritern, von den Kindern Ammon und von den Philistern gerettet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Und als die Zidonier und Amalekiter und Maoniter euch bedrückten, und ihr zu mir schrieet, euch aus ihrer Hand gerettet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Ihr aber habt mich verlassen und habt anderen Göttern gedient; darum werde ich euch nicht mehr retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Gehet hin und schreiet zu den Göttern, die ihr erwählt habt: sie mögen euch retten zur Zeit eurer Bedrängnis!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Und die Kinder Israel sprachen zu Jehova: Wir haben gesündigt. Tue du uns nach allem, was gut ist in deinen Augen; nur errette uns doch an diesem Tage!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Und sie taten die fremden Götter aus ihrer Mitte hinweg und dienten Jehova; und seine Seele wurde ungeduldig über die Mühsal Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Und die Kinder Ammon versammelten sich und lagerten sich in Gilead; und die Kinder Israel kamen zusammen und lagerten sich zu Mizpa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Da sprach das Volk, die Obersten von Gilead, einer zum anderen: Wer ist der Mann, der anfängt, wider die Kinder Ammon zu streiten? Er soll allen Bewohnern Gileads zum Haupte sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Und Jephtha, der Gileaditer, war ein tapferer Held; er war aber der Sohn einer Hure, und Gilead hatte Jephtha gezeugt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Und auch das Weib Gileads gebar ihm Söhne; und als die Söhne des Weibes groß wurden, da vertrieben sie Jephtha und sprachen zu ihm: Du sollst nicht erben im Hause unseres Vaters, denn du bist der Sohn eines anderen Weibes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Und Jephtha floh vor seinen Brüdern und wohnte im Lande Tob. Und es sammelten sich zu Jephtha lose Leute und zogen mit ihm aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Und es geschah nach einiger Zeit, da stritten die Kinder Ammon mit Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Und es geschah, als die Kinder Ammon mit Israel stritten, da gingen die Ältesten von Gilead hin, um Jephtha aus dem Lande Tob zu holen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Und sie sprachen zu Jephtha: Komm und sei unser Anführer, daß wir wider die Kinder Ammon streiten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Und Jephtha sprach zu den Ältesten von Gilead: Seid ihr es nicht, die mich gehaßt und mich aus dem Hause meines Vaters vertrieben haben? Und warum kommet ihr jetzt zu mir, da ihr in Bedrängnis seid?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Und die Ältesten von Gilead sprachen zu Jephtha: Darum sind wir jetzt zu dir zurückgekehrt, daß du mit uns ziehest und wider die Kinder Ammon streitest; und du sollst uns zum Haupte sein, allen Bewohnern Gileads.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Und Jephta sprach zu den Ältesten von Gilead: Wenn ihr mich zurückholet, um wider die Kinder Ammon zu streiten, und Jehova sie vor mir dahingibt, werde ich euch dann wirklich zum Haupte sein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Und die Ältesten von Gilead sprachen zu Jephtha: Jehova sei Zeuge zwischen uns, wenn wir nicht also tun, wie du geredet hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Da ging Jephtha mit den Ältesten von Gilead, und das Volk setzte ihn zum Haupte und zum Anführer über sich. Und Jephtha redete alle seine Worte vor Jehova zu Mizpa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Und Jephtha sandte Boten an den König der Kinder Ammon und ließ ihm sagen: Was haben wir miteinander zu schaffen, daß du gegen mich gekommen bist, mein Land zu bekriegen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Und der König der Kinder Ammon sprach zu den Boten Jephthas: Weil Israel mein Land genommen hat, als es aus Ägypten heraufzog, vom Arnon bis an den Jabbok und bis an den Jordan; und nun gib die Länder in Frieden zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Da sandte Jephtha abermals Boten an den König der Kinder Ammon');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'und ließ ihm sagen: So spricht Jephta: Israel hat nicht das Land Moabs und das Land der Kinder Ammon genommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'sondern als sie aus Ägypten heraufzogen, da wanderte Israel durch die Wüste bis zum Schilfmeere, und es kam nach Kades;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'und Israel sandte Boten an den König von Edom und ließ ihm sagen: Laß mich doch durch dein Land ziehen! Aber der König von Edom gab kein Gehör. Und auch an den König von Moab sandte es; aber er wollte nicht. So blieb Israel in Kades.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Und es wanderte durch die Wüste und umging das Land Edom und das Land Moab und kam von Sonnenaufgang her zum Lande Moab; und sie lagerten sich jenseit des Arnon und kamen nicht in das Gebiet Moabs, denn der Arnon ist die Grenze Moabs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Und Israel sandte Boten an Sihon, den König der Amoriter, den König von Hesbon, und Israel ließ ihm sagen: Laß uns doch durch dein Land ziehen bis an meinen Ort!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Aber Sihon traute Israel nicht, es durch sein Gebiet ziehen zu lassen; und Sihon versammelte all sein Volk, und sie lagerten sich zu Jahza; und er stritt wider Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Und Jehova, der Gott Israels, gab Sihon und all sein Volk in die Hand Israels, und sie schlugen sie. So nahm Israel das ganze Land der Amoriter, die jenes Land bewohnten, in Besitz:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Sie nahmen das ganze Gebiet der Amoriter in Besitz, vom Arnon bis an den Jabbok, und von der Wüste bis an den Jordan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Und so hat nun Jehova, der Gott Israels, die Amoriter vor seinem Volke Israel ausgetrieben, und du willst uns austreiben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Nimmst du nicht das in Besitz, was Kamos, dein Gott, dir zum Besitz gibt? So auch alles, was Jehova, unser Gott, vor uns ausgetrieben hat, das wollen wir besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Und nun, bist du etwa besser als Balak, der Sohn Zippors, der König von Moab? Hat er je mit Israel gerechtet, oder je wider sie gestritten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Während Israel in Hesbon wohnte und in seinen Tochterstädten, und in Aroer und in seinen Tochterstädten, und in all den Städten, die längs des Arnon liegen, dreihundert Jahre lang: warum habt ihr sie denn nicht in jener Zeit entrissen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Und nicht ich habe gegen dich gesündigt, sondern du tust übel an mir, wider mich zu streiten. Jehova, der Richter, richte heute zwischen den Kindern Israel und den Kindern Ammon!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Aber der König der Kinder Ammon hörte nicht auf die Worte Jephthas, die er ihm entboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Da kam der Geist Jehovas über Jephtha; und er zog durch Gilead und Manasse, und zog nach Mizpe in Gilead, und von Mizpe in Gilead zog er gegen die Kinder Ammon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Und Jephtha gelobte Jehova ein Gelübde und sprach: Wenn du die Kinder Ammon wirklich in meine Hand gibst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'so soll das, was zur Tür meines Hauses herausgeht, mir entgegen, wenn ich in Frieden von den Kindern Ammon zurückkehre, es soll Jehova gehören, und ich werde es als Brandopfer opfern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Und so zog Jephtha gegen die Kinder Ammon, um wider sie zu streiten; und Jehova gab sie in seine Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Und er schlug sie von Aroer an, bis man nach Minnith kommt, zwanzig Städte, und bis nach Abel-Keramim, und er richtete eine sehr große Niederlage unter ihnen an; und die Kinder Ammon wurden gebeugt vor den Kindern Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Und als Jephtha nach Mizpa, nach seinem Hause kam, siehe, da trat seine Tochter heraus, ihm entgegen, mit Tamburinen und mit Reigen; und sie war nur die einzige; außer ihr hatte er weder Sohn noch Tochter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Und es geschah, als er sie sah, da zerriß er seine Kleider und sprach: Ach, meine Tochter! Tief beugst du mich nieder; und du, du bist unter denen, die mich in Trübsal bringen! Denn ich habe meinen Mund gegen Jehova aufgetan und kann nicht zurücktreten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Und sie sprach zu ihm: Mein Vater, hast du deinen Mund gegen Jehova aufgetan, so tue mir, wie es aus deinem Munde hervorgegangen ist, nachdem Jehova dir Rache verschafft hat an deinen Feinden, den Kindern Ammon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Und sie sprach zu ihrem Vater: Es geschehe mir diese Sache: Laß zwei Monate von mir ab, daß ich hingehe und auf die Berge hinabsteige und meine Jungfrauschaft beweine, ich und meine Freundinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Und er sprach: Gehe hin. Und er entließ sie auf zwei Monate. Und sie ging hin, sie und ihre Freundinnen, und beweinte ihre Jungfrauschaft auf den Bergen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Und es geschah am Ende von zwei Monaten, da kehrte sie zu ihrem Vater zurück. Und er vollzog an ihr das Gelübde, das er gelobt hatte. Sie hatte aber keinen Mann erkannt. Und es wurde zum Gebrauch in Israel:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Von Jahr zu Jahr gehen die Töchter Israels hin, um die Tochter Jephthas, des Gileaditers, zu preisen vier Tage im Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Und die Männer von Ephraim versammelten sich und zogen hinüber nach Norden, und sie sprachen zu Jephtha: Warum bist du durchgezogen, um wider die Kinder Ammon zu streiten, und hast uns nicht gerufen, daß wir mit dir gingen? Wir werden dein Haus über dir mit Feuer verbrennen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Und Jephtha sprach zu ihnen: Einen heftigen Streit haben wir gehabt, ich und mein Volk, mit den Kindern Ammon; und ich rief euch, aber ihr habt mich nicht aus ihrer Hand gerettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Und als ich sah, daß du nicht helfen wolltest, da setzte ich mein Leben aufs Spiel und zog hin wider die Kinder Ammon; und Jehova gab sie in meine Hand. Warum seid ihr denn an diesem Tage gegen mich heraufgezogen, um wider mich zu streiten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Und Jephtha versammelte alle Männer von Gilead und stritt mit Ephraim; und die Männer von Gilead schlugen Ephraim, weil sie gesagt hatten: Flüchtlinge Ephraims seid ihr, ihr Gileaditer, inmitten Ephraims und inmitten Manasses!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Und Gilead nahm Ephraim die Furten des Jordan. Und es geschah, wenn ein Flüchtling von Ephraim sprach: Laß mich hinübergehen! So sprachen die Männer von Gilead zu ihm: Bist du ein Ephraimiter?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Und sagte er: Nein! so sprachen sie zu ihm: Sage doch: Schibboleth! Und sagte er: Sibboleth, und brachte es nicht fertig, richtig zu sprechen, dann ergriffen sie ihn und schlachteten ihn an den Furten des Jordan. Und es fielen in jener Zeit von Ephraim zweiundvierzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Und Jephtha richtete Israel sechs Jahre; und Jephtha, der Gileaditer, starb und wurde in einer der Städte Gileads begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Und nach ihm richtete Israel Ibzan von Bethlehem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Und er hatte dreißig Söhne; und dreißig Töchter entließ er aus dem Hause, und dreißig Töchter brachte er von außen für seine Söhne herein. Und er richtete Israel sieben Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Und Ibzan starb und wurde zu Bethlehem begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Und nach ihm richtete Israel Elon, der Sebuloniter; und er richtete Israel zehn Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Und Elon, der Sebuloniter, starb und wurde zu Ajjalon im Lande Sebulon begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Und nach ihm richtete Israel Abdon, der Sohn Hillels, der Pirhathoniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Und er hatte vierzig Söhne und dreißig Enkel, die auf siebzig Eseln ritten. Und er richtete Israel acht Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Und Abdon, der Sohn Hillels, der Pirhathoniter, starb und wurde zu Pirhathon begraben im Lande Ephraim, im Gebirge der Amalekiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Und die Kinder Israel taten wiederum was böse war in den Augen Jehovas; und Jehova gab sie in die Hand der Philister vierzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Und es war ein Mann aus Zorha, vom Geschlecht der Daniter, sein Name war Manoah. Und sein Weib war unfruchtbar und gebar nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Und der Engel Jehovas erschien dem Weibe und sprach zu ihr: Siehe doch, du bist unfruchtbar und gebierst nicht; aber du wirst schwanger werden und einen Sohn gebären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Und nun hüte dich doch und trinke weder Wein noch starkes Getränk, und iß nichts Unreines!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Denn siehe, du wirst schwanger werden und einen Sohn gebären; und kein Schermesser soll auf sein Haupt kommen, denn ein Nasir Gottes soll der Knabe sein von Mutterleibe an; und er wird anfangen, Israel aus der Hand der Philister zu retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Und das Weib kam und sprach zu ihrem Manne und sagte: Ein Mann Gottes ist zu mir gekommen, und sein Ansehen war wie das Ansehen eines Engels Gottes, sehr furchtbar; und ich habe ihn nicht gefragt, woher er sei, und seinen Namen hat er mir nicht kundgetan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Und er sprach zu mir: Siehe, du wirst schwanger werden und einen Sohn gebären; und nun, trinke weder Wein noch starkes Getränk, und iß nichts Unreines; denn ein Nasir Gottes soll der Knabe sein von Mutterleibe an bis zum Tage seines Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Da flehte Manoah zu Jehova und sprach: Bitte, Herr! Der Mann Gottes, den du gesandt hast, möge doch nochmals zu uns kommen und uns lehren, was wir tun sollen mit dem Knaben, der geboren werden soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Und Gott erhörte die Stimme Manoahs; und der Engel Gottes kam nochmals zu dem Weibe, als sie auf dem Felde saß, und Manoah, ihr Mann, nicht bei ihr war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Da eilte das Weib und lief und berichtete es ihrem Manne, und sie sprach zu ihm: Siehe, der Mann ist mir erschienen, der an jenem Tage zu mir gekommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Und Manoah machte sich auf und ging seinem Weibe nach; und er kam zu dem Manne und sprach zu ihm: Bist du der Mann, der zu dem Weibe geredet hat? Und er sprach: Ich bin\'s.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Und Manoah sprach: Wenn nun dein Wort eintrifft, was soll die Weise des Knaben sein und sein Tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Und der Engel Jehovas sprach zu Manoah: Vor allem, was ich dem Weibe gesagt habe, soll sie sich hüten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Von allem, was vom Weinstock kommt, soll sie nicht essen, und Wein und starkes Getränk soll sie nicht trinken, und soll nichts Unreines essen; alles, was ich ihr geboten habe, soll sie beobachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Und Manoah sprach zu dem Engel Jehovas: Laß dich doch von uns aufhalten, so wollen wir dir ein Ziegenböcklein zubereiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Und der Engel Jehovas sprach zu Manoah: Wenn du mich auch aufhieltest, ich würde nicht von deinem Brote essen; willst du aber ein Brandopfer opfern, so opfere es Jehova. Denn Manoah wußte nicht, daß es der Engel Jehovas war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Und Manoah sprach zu dem Engel Jehovas: Wie ist dein Name, daß wir dich ehren, wenn dein Wort eintrifft?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Und der Engel Jehovas sprach zu ihm: Warum fragst du denn nach meinem Namen? Er ist ja wunderbar!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Da nahm Manoah das Ziegenböcklein und das Speisopfer und opferte es Jehova auf dem Felsen. Er aber handelte wunderbar, und Manoah und sein Weib sahen zu;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'und es geschah, als die Flamme von dem Altar gen Himmel emporstieg, da fuhr der Engel Jehovas in der Flamme des Altars hinauf. Und Manoah und sein Weib sahen zu und fielen auf ihr Angesicht zur Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Und der Engel Jehovas erschien Manoah und seinem Weibe fortan nicht mehr. Da erkannte Manoah, daß es der Engel Jehovas war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Und Manoah sprach zu seinem Weibe: Wir werden gewißlich sterben, denn wir haben Gott gesehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Aber sein Weib sprach zu ihm: Wenn es Jehova gefallen hätte, uns zu töten, so hätte er nicht ein Brandopfer und Speisopfer aus unserer Hand angenommen, und er hätte uns dies alles nicht gezeigt, noch uns zu dieser Zeit dergleichen vernehmen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Und das Weib gebar einen Sohn; und sie gab ihm den Namen Simson. Und der Knabe wuchs, und Jehova segnete ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Und der Geist Jehovas fing an, ihn zu treiben zu Machaneh-Dan zwischen Zorha und Eschtaol.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Und Simson ging nach Timna hinab; und er sah in Timna ein Weib von den Töchtern der Philister.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Und er ging hinauf und berichtete es seinem Vater und seiner Mutter und sprach: Ich habe in Timna ein Weib gesehen von den Töchtern der Philister; und nun nehmet sie mir zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Und sein Vater und seine Mutter sprachen zu ihm: Ist unter den Töchtern deiner Brüder und unter meinem ganzen Volke kein Weib, daß du hingehest, ein Weib zu nehmen von den Philistern, den Unbeschnittenen? Und Simson sprach zu seinem Vater: Diese nimm mir, denn sie ist recht in meinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Sein Vater und seine Mutter wußten aber nicht, daß es von Jehova war; denn er suchte eine Gelegenheit an den Philistern. Und in jener Zeit herrschten die Philister über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Und Simson ging mit seinem Vater und seiner Mutter nach Timna hinab; und als sie an die Weinberge von Timna kamen, siehe, da brüllte ein junger Löwe ihm entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Und der Geist Jehovas geriet über ihn, und er zerriß ihn, wie man ein Böcklein zerreißt; und er hatte gar nichts in seiner Hand. Und er tat seinem Vater und seiner Mutter nicht kund, was er getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Und er ging hinab und redete zu dem Weibe, und sie war recht in den Augen Simsons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Und er kehrte nach einiger Zeit zurück, um sie zu nehmen, und er bog ab, um das Aas des Löwen zu besehen, und siehe, ein Bienenschwarm war in dem Körper des Löwen, und Honig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Da nahm er ihn heraus in seine Hände, und ging und aß im Gehen; und er ging zu seinem Vater und zu seiner Mutter und gab ihnen, und sie aßen; aber er tat ihnen nicht kund, daß er den Honig aus dem Körper des Löwen herausgenommen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Und sein Vater ging zu dem Weibe hinab, und Simson machte daselbst ein Mahl; denn also pflegten die Jünglinge zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Und es geschah, als sie ihn sahen, da nahmen die dreißig Gesellen; und sie waren bei ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Und Simson sprach zu ihnen: Ich will euch einmal ein Rätsel aufgeben; wenn ihr es mir in den sieben Tagen des Mahles kundtut und es erratet, so werde ich euch dreißig Hemden und dreißig Wechselkleider geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Wenn ihr es mir aber nicht kundtun könnet, so sollt ihr mir dreißig Hemden und dreißig Wechselkleider geben. Und sie sprachen zu ihm: Gib dein Rätsel auf, daß wir es hören!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Und er sprach zu ihnen: Aus dem Fresser kam Fraß, und aus dem Starken kam Süßigkeit. Und sie vermochten das Rätsel nicht kundzutun drei Tage lang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Und es geschah am siebten Tage, da sprachen sie zu dem Weibe Simsons: Berede deinen Mann, daß er uns das Rätsel kundtue, damit wir nicht dich und deines Vaters Haus mit Feuer verbrennen! Um uns zu berauben, habt ihr uns geladen, nicht wahr?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Und Simsons Weib weinte an ihm und sprach: Du hassest mich nur und liebst mich nicht. Das Rätsel hast du den Kindern meines Volkes aufgegeben, und mir hast du es nicht kundgetan. Und er sprach zu ihr: Siehe, meinem Vater und meiner Mutter habe ich es nicht kundgetan, und dir sollte ich es kundtun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Und sie weinte an ihm die sieben Tage, da sie das Mahl hatten. Und es geschah am siebten Tage, da tat er es ihr kund, denn sie drängte ihn. Und sie tat das Rätsel den Kindern ihres Volkes kund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Da sprachen die Männer der Stadt zu ihm am siebten Tage, ehe die Sonne unterging: Was ist süßer als Honig? Und was ist stärker als der Löwe? Und er sprach zu ihnen: Wenn ihr nicht mit meinem Kalbe gepflügt hättet, so hättet ihr mein Rätsel nicht erraten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Und der Geist Jehovas geriet über ihn; und er ging hinab nach Askalon und erschlug von ihnen dreißig Mann und nahm ihre ausgezogenen Gewänder und gab die Wechselkleider denen, welche das Rätsel kundgetan hatten. Und sein Zorn entbrannte, und er ging hinauf in das Haus seines Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Und das Weib Simsons wurde einem seiner Gesellen gegeben, den er sich zugesellt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Und es geschah nach einiger Zeit, in den Tagen der Weizenernte, da besuchte Simson sein Weib mit einem Ziegenböcklein. Und er sprach: Ich will zu meinem Weibe ins Gemach gehen; aber ihr Vater gestattete ihm nicht hineinzugehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Und ihr Vater sprach: Ich habe gewißlich gedacht, daß du sie haßtest, und so habe ich sie deinem Gesellen gegeben. Ist nicht ihre jüngere Schwester schöner als sie? Möge sie doch dein werden an ihrer Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Da sprach Simson zu ihnen: Diesmal bin ich schuldlos an den Philistern, wenn ich ihnen Übles tue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Und Simson ging hin und fing dreihundert Schakale; und er nahm Fackeln und kehrte Schwanz an Schwanz und tat eine Fackel zwischen je zwei Schwänze in die Mitte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'und er zündete die Fackeln mit Feuer an. Und er ließ sie los in das stehende Getreide der Philister und zündete sowohl Garbenhaufen als stehendes Getreide und Olivengärten an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Und die Philister sprachen: Wer hat das getan? und man sagte: Simson, der Schwiegersohn des Timniters, weil er ihm sein Weib genommen und sie seinem Gesellen gegeben hat. Da zogen die Philister hinauf und verbrannten sie und ihren Vater mit Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Und Simson sprach zu ihnen: Wenn ihr also tut es sei denn, daß ich mich an euch gerächt habe, danach will ich aufhören!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Und er schlug sie, Schenkel samt Hüfte, und richtete eine große Niederlage unter ihnen an. Und er ging hinab und wohnte in der Kluft des Felsens Etam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Und die Philister zogen herauf und lagerten sich in Juda und breiteten sich aus in Lechi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Und die Männer von Juda sprachen: Warum seid ihr wider uns heraufgezogen? Und sie sprachen: Um Simson zu binden, sind wir heraufgezogen, daß wir ihm tun, wie er uns getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Da zogen dreitausend Mann von Juda zur Kluft des Felsens Etam hinab und sprachen zu Simson: Weißt du nicht, daß die Philister über uns herrschen? Und warum hast du uns das getan? Und er sprach zu ihnen: Wie sie mir getan, also habe ich ihnen getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Da sprachen sie zu ihm: Um dich zu binden, sind wir herabgekommen, daß wir dich in die Hand der Philister liefern. Und Simson sprach zu ihnen: Schwöret mir, daß ihr nicht über mich herfallen werdet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Und sie sprachen zu ihm und sagten: Nein, sondern binden wollen wir dich und dich in ihre Hand liefern; aber töten wollen wir dich nicht. Und sie banden ihn mit zwei neuen Stricken und führten ihn aus dem Felsen herauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Als er nach Lechi kam, da jauchzten ihm die Philister entgegen; aber der Geist Jehovas geriet über ihn, und die Stricke, welche an seinen Armen waren, wurden wie Flachsfäden, die vom Feuer versengt sind, und seine Bande schmolzen weg von seinen Händen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Und er fand einen frischen Eselskinnbacken, und er streckte seine Hand aus und nahm ihn und erschlug damit tausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Und Simson sprach: Mit dem Eselskinnbacken einen Haufen, zwei Haufen! Mit dem Eselskinnbacken habe ich tausend Mann erschlagen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Und es geschah, als er ausgeredet hatte, da warf er den Kinnbacken aus seiner Hand; und er nannte selbigen Ort Ramath-Lechi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Und es dürstete ihn sehr, und er rief zu Jehova und sprach: Du hast durch die Hand deines Knechtes diese große Rettung gegeben, und nun soll ich vor Durst sterben und in die Hand der Unbeschnittenen fallen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Da spaltete Gott die Höhlung, die zu Lechi ist, und es kam Wasser aus ihr hervor; und er trank, und sein Geist kehrte zurück, und er lebte wieder auf. Daher gab man ihr den Namen: Quelle des Rufenden, die zu Lechi ist, bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Und er richtete Israel in den Tagen der Philister zwanzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Und Simson ging nach Gasa, und er sah daselbst eine Hure und ging zu ihr ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Und es wurde den Gasitern berichtet und gesagt: Simson ist hierher gekommen. Und sie umstellten ihn und lauerten die ganze Nacht auf ihn im Stadttore; und sie verhielten sich still die ganze Nacht und sprachen: Bis der Morgen hell wird, dann wollen wir ihn erschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Und Simson lag bis Mitternacht. Um Mitternacht aber stand er auf und ergriff die Flügel des Stadttores und die beiden Pfosten, und riß sie samt dem Riegel heraus und legte sie auf seine Schultern; und er trug sie auf den Gipfel des Berges, der gegen Hebron hin liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Und es geschah hernach, da liebte er ein Weib im Tale Sorek, ihr Name war Delila.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Und die Fürsten der Philister gingen zu ihr hinauf und sprachen zu ihr: Berede ihn und sieh, worin seine große Stärke besteht, und wodurch wir ihn überwältigen können, daß wir ihn binden, um ihn zu bezwingen; und wir wollen dir ein jeder tausend einhundert Sekel Silber geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Da sprach Delila zu Simson: Tue mir doch kund, worin deine große Stärke besteht, und womit du gebunden werden kannst, daß man dich bezwinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Und Simson sprach zu ihr: Wenn man mich bände mit sieben frischen Stricken, die nicht ausgetrocknet sind, so würde ich schwach werden und würde sein wie ein anderer Mensch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Und die Fürsten der Philister brachten sieben frische Stricke, die nicht ausgetrocknet waren, zu ihr hinauf; und sie band ihn damit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Es saßen aber Auflaurer bei ihr im Gemach; und sie sprach zu ihm: Philister über dir, Simson! Da zerriß er die Stricke, wie eine Schnur von Werg zerreißt, wenn sie Feuer riecht; und seine Stärke ward nicht kund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Da sprach Delila zu Simson: Siehe, du hast mich getäuscht und Lügen zu mir geredet. Nun tue mir doch kund, womit du gebunden werden kannst!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Und er sprach zu ihr: Wenn man mich fest bände mit neuen Seilen, mit denen keine Arbeit geschehen ist, so würde ich schwach werden und würde sein wie ein anderer Mensch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Da nahm Delila neue Seile und band ihn damit, und sie sprach zu ihm: Philister über dir, Simson! Es saßen aber Auflaurer im Gemach. Und er riß sie von seinen Armen wie einen Faden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Da sprach Delila zu Simson: Bisher hast du mich getäuscht und Lügen zu mir geredet. Tue mir kund, womit du gebunden werden kannst! Und er sprach zu ihr: Wenn du die sieben Flechten meines Hauptes mit dem Gewebe verwebtest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Und sie heftete sie mit dem Pflocke und sprach zu ihm: Philister über dir, Simson! Da wachte er auf von seinem Schlafe und riß den Webepflock und das Gewebe heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Da sprach sie zu ihm: Wie kannst du sagen: Ich habe dich lieb, so doch dein Herz nicht mit mir ist? Nun dreimal hast du mich getäuscht und mir nicht kundgetan, worin deine große Stärke besteht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Und es geschah, als sie ihn alle Tage mit ihren Worten drängte und ihn plagte, da wurde seine Seele ungeduldig zum Sterben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Und er tat ihr sein ganzes Herz kund und sprach zu ihr: Kein Schermesser ist auf mein Haupt gekommen, denn ein Nasir Gottes bin ich von Mutterleibe an; wenn ich geschoren würde, so würde meine Stärke von mir weichen, und ich würde schwach werden und würde sein wie alle Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'und als Delila sah, daß er ihr sein ganzes Herz kundgetan hatte, da sandte sie hin und rief die Fürsten der Philister und sprach: Kommet diesmal herauf, denn er hat mir sein ganzes Herz kundgetan. Und die Fürsten der Philister kamen zu ihr hinauf und brachten das Geld mit sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Und sie ließ ihn auf ihren Knien einschlafen, und rief einen Mann und ließ die sieben Flechten seines Hauptes abscheren; und sie fing an, ihn zu bezwingen, und seine Stärke wich von ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Und sie sprach: Philister über dir, Simson! Da wachte er auf von seinem Schlafe und dachte: Ich werde davonkommen wie die anderen Male und mich herausschütteln. Er wußte aber nicht, daß Jehova von ihm gewichen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Und sie Philister griffen ihn und stachen ihm die Augen aus; und sie führten ihn nach Gasa hinab und banden ihn mit ehernen Fesseln, und er mußte mahlen im Gefängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Aber das Haar seines Hauptes begann wieder zu wachsen, sobald es geschoren war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Und die Fürsten der Philister versammelten sich, um ihrem Gott Dagon ein großes Schlachtopfer zu opfern und um ein Freudenfest zu feiern; denn sie sprachen: Unser Gott hat Simson, unseren Feind, in unsere Hand gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Und als das Volk ihn sah, priesen sie ihren Gott; denn sie sprachen: Unser Gott hat unseren Feind in unsere Hand gegeben, und den Verheerer unseres Landes und den, der unserer Erschlagenen viel machte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Und es geschah, als ihr Herz fröhlich war, da sprachen sie: Rufet Simson, daß er vor uns spiele. Und sie riefen Simson aus dem Gefängnis, und er spielte vor ihnen; und sie stellten ihn zwischen die Säulen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Und Simson sprach zu dem Knaben, der ihn bei der Hand hielt: Laß mich, daß ich die Säulen betaste, auf welchen das Haus ruht, und mich an sie lehne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Das Haus war aber voll Männern und Weibern, und alle Fürsten der Philister waren daselbst; und auf dem Dache waren bei dreitausend Männer und Weiber, welche zusahen, wie Simson spielte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Und Simson rief zu Jehova und sprach: Herr, Jehova! Gedenke doch meiner, und stärke mich doch nur diesmal, o Gott, daß ich an den Philistern eine einmalige Rache nehme für meine beiden Augen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Und Simson umfaßte die beiden Mittelsäulen, auf welchen das Haus ruhte, (und er stützte sich darauf) die eine mit seiner Rechten und die andere mit seiner Linken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'und Simson sprach: Meine Seele sterbe mit den Philistern! Und er beugte sich mit Kraft; da fiel das Haus auf die Fürsten und auf alles Volk, das darin war; und es waren der Toten, die er in seinem Tode tötete, mehr als derer, die er in seinem Leben getötet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Und seine Brüder und das ganze Haus seines Vaters kamen herab und hoben ihn auf; und sie gingen hinauf und begruben ihn zwischen Zorha und Eschtaol, im Grabe Manoahs, seines Vaters. Er hatte aber Israel zwanzig Jahre gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Und es war ein Mann vom Gebirge Ephraim, sein Name war Micha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Und er sprach zu seiner Mutter: Die tausend einhundert Sekel Silber, die dir genommen worden sind, und worüber du einen Fluch getan und auch vor meinen Ohren geredet hast, siehe, das Silber ist bei mir; ich habe es genommen. Da sprach seine Mutter: Gesegnet sei mein Sohn von Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Und er gab die tausend einhundert Sekel Silber seiner Mutter zurück. Und seine Mutter sprach: Das Silber hatte ich von meiner Hand Jehova geheiligt für meinen Sohn, um ein geschnitztes Bild und ein gegossenes Bild zu machen; und nun gebe ich es dir zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Und er gab das Silber seiner Mutter zurück. Und seine Mutter nahm zweihundert Sekel Silber und gab sie dem Goldschmied, und der machte daraus ein geschnitztes Bild und ein gegossenes Bild; und es war im Hause Michas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Und der Mann Micha hatte ein Gotteshaus; und er machte ein Ephod und Teraphim und weihte einen von seinen Söhnen, und er wurde sein Priester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'In jenen Tagen war kein König in Israel; ein jeder tat, was recht war in seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Und es war ein Jüngling aus Bethlehem-Juda vom Geschlecht Juda; der war ein Levit und hielt sich daselbst auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Und der Mann zog aus der Stadt, aus Bethlehem-Juda, um sich aufzuhalten, wo er es treffen würde. Und indem er seines Weges zog, kam er in das Gebirge Ephraim bis zum Hause Michas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Und Micha sprach zu ihm: Woher kommst du? Und er sprach zu ihm: Ich bin ein Levit aus Bethlehem-Juda; und ich gehe hin, mich aufzuhalten, wo ich es treffen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Da sprach Micha zu ihm: Bleibe bei mir, und sei mir ein Vater und ein Priester, so werde ich dir jährlich zehn Sekel Silber geben und Ausrüstung an Kleidern und deinen Lebensunterhalt. Und der Levit ging hinein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Und der Levit willigte ein, bei dem Manne zu bleiben; und der Jüngling ward ihm wie einer seiner Söhne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Und Micha weihte den Leviten; und der Jüngling wurde sein Priester und war im Hause Michas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Und Micha sprach: Nun weiß ich, daß Jehova mir wohltun wird, denn ich habe einen Leviten zum Priester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'In jenen Tagen war kein König in Israel. Und in jenen Tagen suchte sich der Stamm der Daniter ein Erbteil zum Wohnen, denn bis auf jenen Tag war ihm inmitten der Stämme Israels nichts als Erbteil zugefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Und die Kinder Dan sandten fünf Männer aus ihrem Geschlecht, aus ihrer Gesamtheit, tapfere Männer, aus Zorha und aus Eschtaol, um das Land auszukundschaften und es zu erforschen; und sie sprachen zu ihnen: Gehet hin, erforschet das Land. Und sie kamen in das Gebirge Ephraim bis zum Hause Michas, und sie übernachteten daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Als sie beim Hause Michas waren, erkannten sie die Stimme des Jünglings, des Leviten, und sie wandten sich dahin und sprachen zu ihm: Wer hat dich hierhergebracht, und was tust du hier, und was hast du hier?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Und er sprach zu ihnen: So und so hat Micha mir getan; und er hat mich gedungen, und ich bin sein Priester geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Und sie sprachen zu ihm: Befrage doch Gott, daß wir wissen, ob unser Weg, auf dem wir ziehen, gelingen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Und der Priester sprach zu ihnen: Ziehet hin in Frieden! Vor Jehova ist euer Weg, auf dem ihr ziehet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Und die fünf Männer gingen hin und kamen nach Lais; und sie sahen das Volk, das darin war, in Sicherheit wohnen, nach Art der Zidonier, ruhig und sicher; und niemand, der die Herrschaft besessen hätte im Lande, tat ihnen irgend etwas zuleide; und sie waren fern von den Zidoniern und hatten mit Menschen nichts zu schaffen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Und sie kamen zu ihren Brüdern nach Zorha und Eschtaol. Und ihre Brüder sprachen zu ihnen: Was bringet ihr?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Und sie sprachen: Machet euch auf, und laßt uns wider sie hinaufziehen; denn wir haben das Land besehen, und siehe, es ist sehr gut. Und ihr bleibet stille? Seid nicht träge, hinzugehen, um hineinzukommen, das Land in Besitz zu nehmen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, '(wenn ihr kommmet, werdet ihr zu einem sicheren Volke kommen, und das Land ist geräumig nach allen Seiten hin) denn Gott hat es in eure Hand gegeben: es ist ein Ort, wo es an nichts mangelt von allem, was auf Erden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Und es brachen von dannen auf, vom Geschlecht der Daniter, aus Zorha und aus Eschtaol, sechshundert Mann, umgürtet mit Kriegsgerät.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Und sie zogen hinauf und lagerten sich zu Kirjath-Jearim in Juda; daher hat man selbigen Ort Machaneh-Dan genannt bis auf diesen Tag; siehe, er ist hinter Kirjath-Jearim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Und von dannen zogen sie weiter in das Gebirge Ephraim und kamen bis zum Hause Michas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Da hoben die fünf Männer an, welche gegangen waren, das Land Lais auszukundschaften, und sprachen zu ihren Brüdern: Wisset ihr, daß in diesen Häusern Ephod und Teraphim und ein geschnitztes Bild und ein gegossenes Bild sind? Und nun wisset, was ihr tun sollt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Und sie wandten sich dahin und traten in das Haus des Jünglings, des Leviten, das Haus Michas, und fragten ihn nach seinem Wohlergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Die sechshundert mit ihrem Kriegsgerät umgürteten Männer aber, die von den Kindern Dan waren, blieben am Eingang des Tores stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Und die fünf Männer, die gegangen waren, das Land auszukundschaften, stiegen hinauf, gingen hinein und nahmen das geschnitzte Bild und das Ephod und die Teraphim und das gegossene Bild. Und der Priester und die sechshundert Mann, die mit Kriegsgerät umgürtet waren, standen am Eingang des Tores.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Als jene nämlich in das Haus Michas gingen und das geschnitzte Bild, das Ephod und die Teraphim und das gegossene Bild wegnahmen, da sprach der Priester zu ihnen: Was tut ihr?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Und sie sprachen zu ihm: Schweige! Lege deine Hand auf deinen Mund und gehe mit uns, und sei uns ein Vater und ein Priester. Ist es besser für dich, Priester zu sein für das Haus eines einzelnen Mannes, oder Priester zu sein für einen Stamm und für ein Geschlecht in Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Da wurde das Herz des Priesters froh, und er nahm das Ephod und die Teraphim und das geschnitzte Bild und ging mitten unter das Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Und sie wandten sich und zogen weg und stellten die Kinder und das Vieh und die wertvollen Dinge voran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Sie waren schon fern vom Hause Michas, da versammelten sich die Männer, die in den Häusern waren, die beim Hause Michas standen, und ereilten die Kinder Dan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Und sie riefen den Kindern Dan zu; und diese wandten ihr Angesicht um und sprachen zu Micha: Was ist dir, daß du dich versammelt hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Und er sprach: Meine Götter, die ich gemacht hatte, habt ihr genommen und den Priester, und seid weggezogen; und was habe ich noch? Und wie sprechet ihr denn zu mir: Was ist dir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Aber die Kinder Dan sprachen zu ihm: Laß deine Stimme nicht bei uns hören, damit nicht Männer heftigen Gemütes über euch herfallen, und du dich und dein Haus ums Leben bringest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Und die Kinder Dan zogen ihres Weges. Und als Micha sah, daß sie ihm zu stark waren, wandte er sich und kehrte in sein Haus zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'So nahmen sie, was Micha gemacht hatte, und den Priester, den er besaß. Und sie überfielen Lais, ein ruhiges und sicheres Volk, und schlugen es mit der Schärfe des Schwertes; und die Stadt verbrannten sie mit Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Und kein Erretter war da; denn die Stadt war fern von Zidon, und sie hatten nichts mit Menschen zu schaffen; und sie lag in dem Tale, das sich nach Beth-Rechob hin erstreckt. Und sie bauten die Stadt wieder auf und wohnten darin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'und sie gaben der Stadt den Namen Dan, nach dem Namen Dans, ihres Vaters, welcher dem Israel geboren wurde; dagegen war im Anfang Lais der Name der Stadt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Und die Kinder Dan richteten sich das geschnitzte Bild auf; und Jonathan, der Sohn Gersoms, des Sohnes Moses, er und seine Söhne waren Priester für den Stamm der Daniter bis auf den Tag, da das Land in Gefangenschaft geführt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Und sie stellten sich das geschnitzte Bild Michas auf, das er gemacht hatte, alle die Tage, da das Haus Gottes in Silo war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Und es geschah in jenen Tagen, als kein König in Israel war, daß sich ein levitischer Mann an der äußersten Seite des Gebirges Ephraim aufhielt; und er nahm sich ein Kebsweib aus Bethlehem-Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Und sein Kebsweib hurte neben ihm; und sie ging von ihm weg in das Haus ihres Vaters, nach Bethlehem-Juda, und war daselbst eine Zeitlang, vier Monate.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Und ihr Mann machte sich auf und ging ihr nach, um zu ihrem Herzen zu reden, sie zurückzubringen; und sein Knabe war mit ihm und ein Paar Esel. Und sie führte ihn in das Haus ihres Vaters; und als der Vater des jungen Weibes ihn sah, kam er ihm freudig entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Und sein Schwiegervater, der Vater des jungen Weibes, hielt ihn zurück, und er blieb drei Tage bei ihm; und sie aßen und tranken und übernachteten daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Und es geschah am vierten Tage, da machten sie sich des Morgens früh auf, und er erhob sich, um fortzugehen. Da sprach der Vater des jungen Weibes zu seinem Schwiegersohn: Stärke dein Herz mit einem Bissen Brot, und danach möget ihr ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Und sie setzten sich und aßen und tranken beide miteinander. Und der Vater des jungen Weibes sprach zu dem Manne: Laß es dir doch gefallen und bleibe über Nacht und laß dein Herz fröhlich sein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Und als der Mann sich erhob, um fortzugehen, da drang sein Schwiegervater in ihn, und er übernachtete wiederum daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Und am fünften Tage machte er sich des Morgens früh auf, um fortzugehen; da sprach der Vater des jungen Weibes: Stärke doch dein Herz und verziehet, bis der Tag sich neigt! Und so aßen sie beide miteinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Und der Mann erhob sich, um fortzugehen, er und sein Kebsweib und sein Knabe. Aber sein Schwiegervater, der Vater des jungen Weibes, sprach zu ihm: Siehe doch, der Tag nimmt ab, es will Abend werden; übernachtet doch! Siehe, der Tag sinkt, übernachte hier und laß dein Herz fröhlich sein; und ihr machet euch morgen früh auf euren Weg, und du ziehst nach deinem Zelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Aber der Mann wollte nicht übernachten, und er erhob sich und zog fort; und er kam bis vor Jebus, das ist Jerusalem, und mit ihm das Paar gesattelter Esel, und sein Kebsweib mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Sie waren bei Jebus, und der Tag war sehr herabgesunken, da sprach der Knabe zu seinem Herrn: Komm doch und laß uns in diese Stadt der Jebusiter einkehren und darin übernachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Aber sein Herr sprach zu ihm: Wir wollen nicht in eine Stadt der Fremden einkehren, die nicht von den Kindern Israel sind, sondern wollen nach Gibea hinübergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Und er sprach zu seinem Knaben: Komm, daß wir uns einem der Orte nähern und in Gibea oder in Rama übernachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'So zogen sie vorüber und gingen weiter, und die Sonne ging ihnen unter nahe bei Gibea, das Benjamin gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Und sie wandten sich dahin, daß sie hineinkämen, um in Gibea zu übernachten. Und er kam hinein und setzte sich hin auf den Platz der Stadt; und niemand war, der sie ins Haus aufgenommen hätte, um zu übernachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Und siehe, ein alter Mann kam von seiner Arbeit, vom Felde, am Abend; und der Mann war vom Gebirge Ephraim, und er hielt sich in Gibea auf; die Leute des Ortes aber waren Benjaminiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Und er erhob seine Augen und sah den Wandersmann auf dem Platze der Stadt, und der alte Mann sprach: Wohin gehst du? Und woher kommst du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Und er sprach zu ihm: Wir reisen von Bethlehem-Juda nach der äußersten Seite des Gebirges Ephraim; von dort bin ich her, und ich bin nach Bethlehem-Juda gegangen, und ich wandle mit dem Hause Jehovas; und niemand ist, der mich in sein Haus aufnimmt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Und wir haben sowohl Stroh als auch Futter für unsere Esel, und auch Brot und Wein habe ich für mich und für deine Magd und für den Knaben, der mit deinen Knechten ist; es mangelt an nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Da sprach der alte Mann: Friede dir! Nur liege all dein Bedarf mir ob; doch auf dem Platze übernachte nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Und er führte ihn in sein Haus und gab den Eseln Futter. Und sie wuschen ihre Füße und aßen und tranken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Sie ließen ihr Herz guter Dinge sein, siehe, da umringten die Männer der Stadt, Männer, welche Söhne Belials waren, das Haus, schlugen an die Tür und sprachen zu dem alten Manne, dem Herrn des Hauses, und sagten: Führe den Mann, der in dein Haus gekommen ist, heraus, daß wir ihn erkennen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Und der Mann, der Herr des Hauses, ging zu ihnen hinaus und sprach zu ihnen: Nicht doch, meine Brüder, tut doch nicht übel; nachdem dieser Mann in mein Haus gekommen ist, begehet nicht diese Schandtat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Siehe, meine Tochter, die Jungfrau, und sein Kebsweib, lasset mich doch sie herausführen; und schwächet sie und tut mit ihnen, was gut ist in euren Augen; aber an diesem Manne begehet nicht diese Schandtat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Aber die Männer wollten nicht auf ihn hören. Da ergriff der Mann sein Kebsweib und führte sie zu ihnen hinaus auf die Straße; und sie erkannten sie und mißhandelten sie die ganze Nacht bis an den Morgen; und sie ließen sie gehen, als die Morgenröte aufging.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Und das Weib kam beim Anbruch des Morgens und fiel nieder am Eingang des Hauses des Mannes, woselbst ihr Herr war, und lag dort, bis es hell wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Und als ihr Herr am Morgen aufstand und die Tür des Hauses öffnete und hinaustrat, um seines Weges zu ziehen: Siehe, da lag das Weib, sein Kebsweib, an dem Eingang des Hauses, und ihre Hände auf der Schwelle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Und er sprach zu ihr: Stehe auf und laß uns gehen! Aber niemand antwortete. Da nahm er sie auf den Esel, und der Mann machte sich auf und zog an seinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Und als er in sein Haus gekommen war, nahm er sein Messer und ergriff sein Kebsweib und zerstückte sie, nach ihren Gebeinen, in zwölf Stücke; und er sandte sie in alle Grenzen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Und es geschah, ein jeder, der es sah, sprach: Solches ist nicht geschehen noch gesehen worden von dem Tage an, da die Kinder Israel aus dem Lande Ägypten heraufgezogen sind, bis auf diesen Tag. Bedenket euch darüber, beratet und redet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Und alle Kinder Israel zogen aus, und die Gemeinde, von Dan bis Beerseba, und das Land Gilead versammelte sich wie ein Mann vor Jehova nach Mizpa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Und die Häupter des ganzen Volkes, aller Stämme Israels, stellten sich in der Versammlung des Volkes Gottes: vierhunderttausend Mann Fußvolk, die das Schwert zogen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Und die Kinder Benjamin hörten, daß die Kinder Israel nach Mizpa hinaufgezogen waren. Und die Kinder Israel sprachen: Redet, wie ist diese Übeltat geschehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Da antwortete der levitische Mann, der Mann des ermordeten Weibes, und sprach: Ich war nach Gibea gekommen, das Benjamin gehört, ich und mein Kebsweib, um dort zu übernachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Da machten sich die Bürger von Gibea wider mich auf und umringten meinetwegen des Nachts das Haus. Mich gedachten sie umzubringen, und mein Kebsweib haben sie geschwächt, daß sie starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Da ergriff ich mein Kebsweib und zerstückte sie und sandte sie in das ganze Gefilde des Erbteils Israels; denn sie haben ein Verbrechen und eine Schandtat begangen in Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Siehe, hier seid ihr allesamt, Kinder Israel: Gebet eure Meinung und euren Rat allhier!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Und das ganze Volk stand auf wie ein Mann und sprach: Wir wollen nicht gehen, ein jeder nach seinem Zelte, und nicht einkehren, ein jeder in sein Haus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'sondern dies ist die Sache, die wir jetzt an Gibea tun wollen: Ziehen wir wider dasselbe nach dem Lose;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'und nehmen wir zehn Männer von hundert, von allen Stämmen Israels, und hundert von tausend und tausend von zehntausend, um Zehrung für das Volk zu holen, damit, wenn sie nach Gibea-Benjamin kommen, man an ihm tue nach all der Schandtat, die es in Israel begangen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Und alle Männer von Israel versammelten sich gegen die Stadt, wie ein Mann verbündet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Und die Stämme Israels sandten Männer in alle Geschlechter Benjamins und sprachen: Was ist das für eine Übeltat, die unter euch geschehen ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'So gebet nun die Männer, die Söhne Belials, heraus, die in Gibea sind, daß wir sie töten und das Böse aus Israel hinwegschaffen! Aber die Kinder Benjamin wollten nicht auf die Stimme ihrer Brüder, der Kinder Israel, hören;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Und die Kinder Benjamin versammelten sich aus den Städten nach Gibea, um auszuziehen zum Streit mit den Kindern Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Und die Kinder Benjamin wurden an selbigem Tage aus den Städten gemustert: sechsundzwanzigtausend Mann, die das Schwert zogen; außer den Bewohnern von Gibea, die gemustert wurden: siebenhundert auserlesene Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Unter all diesem Volke waren siebenhundert auserlesene Männer, die links waren; diese alle schleuderten mit dem Steine aufs Haar und fehlten nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Und die Männer von Israel wurden gemustert, außer Benjamin: vierhunderttausend Mann, die das Schwert zogen; diese alle waren Kriegsmänner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Und die Kinder Israel machten sich auf und zogen hinauf nach Bethel und befragten Gott, und sie sprachen: Wer von uns soll zuerst hinaufziehen zum Streit mit den Kindern Benjamin? Und Jehova sprach: Juda zuerst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Und die Kinder Israel machten sich am Morgen auf und lagerten sich wider Gibea.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Und die Männer von Israel zogen aus zum Streit mit Benjamin, und die Männer von Israel stellten sich wider sie in Schlachtordnung auf bei Gibea.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Und die Kinder Benjamin zogen aus Gibea heraus, und sie streckten unter Israel an selbigem Tage zweiundzwanzigtausend Mann zu Boden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Und es ermannte sich das Volk, die Männer von Israel, und sie stellten sich wieder in Schlachtordnung auf an dem Orte, wo sie sich am ersten Tage aufgestellt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Und die Kinder Israel zogen hinauf und weinten vor Jehova bis an den Abend; und sie befragten Jehova und sprachen: Soll ich wiederum ausrücken zum Streit mit den Kindern meines Bruders Benjamin? Und Jehova sprach: Ziehet wider ihn hinauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Und die Kinder Israel nahten sich den Kindern Benjamin am zweiten Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Und Benjamin zog am zweiten Tage aus Gibea heraus, ihnen entgegen, und sie streckten nochmals unter den Kindern Israel achtzehntausend Mann zu Boden; diese alle zogen das Schwert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Da zogen alle Kinder Israel und das ganze Volk hinauf und kamen nach Bethel, und sie weinten und blieben daselbst vor Jehova und fasteten an selbigem Tage bis zum Abend; und sie opferten Brandopfer und Friedensopfer vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Und die Kinder Israel befragten Jehova, denn die Lade des Bundes Gottes war daselbst in jenen Tagen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'und Pinehas, der Sohn Eleasars, des Sohnes Aarons, stand vor ihr in jenen Tagen und sprachen: Soll ich wiederum ausziehen zum Streit mit den Kindern meines Bruders Benjamin, oder soll ich aufhören? Und Jehova sprach: Ziehet hinauf, denn morgen werde ich ihn in deine Hand geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Und Israel legte einen Hinterhalt gegen Gibea ringsumher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Und die Kinder Israel zogen am dritten Tage hinauf wider die Kinder Benjamin und stellten sich wider Gibea auf, wie die anderen Male.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Und die Kinder Benjamin zogen heraus, dem Volke entgegen, wurden von der Stadt abgerissen und fingen an, etliche von dem Volke zu erschlagen, wie die anderen Male, bei dreißig Mann unter Israel, auf den Landstraßen, deren eine nach Bethel hinaufsteigt und die andere durch das Gefilde nach Gibea führt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Und die Kinder Benjamin sprachen: Sie sind vor uns geschlagen wie im Anfang. Die Kinder Israel aber sprachen: Laßt uns fliehen, daß wir sie von der Stadt abreißen auf die Landstraßen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Und alle Männer von Israel machten sich auf von ihrem Orte und stellten sich zu Baal-Tamar auf, während der Hinterhalt Israels von seinem Orte hervorbrach aus dem Blachfelde von Gibea.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Und es kamen gegen Gibea zehntausend auserlesene Männer aus ganz Israel, und der Streit wurde heftig; jene aber wußten nicht, daß das Unglück sie erreichte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Und Jehova schlug Benjamin vor Israel, und die Kinder Israel streckten unter Benjamin an selbigem Tage fünfundzwanzigtausend einhundert Mann nieder; diese alle zogen das Schwert. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Und die Kinder Benjamin sahen, daß sie geschlagen waren. Und die Männer von Israel gaben Benjamin Raum, weil sie sich auf den Hinterhalt verließen, den sie wider Gibea gelegt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Und der Hinterhalt eilte und überfiel Gibea; und der Hinterhalt zog hin und schlug die ganze Stadt mit der Schärfe des Schwertes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Die Männer von Israel hatten sich aber mit dem Hinterhalt verabredet, eine große Rauchsäule aus der Stadt emporsteigen zu lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Und die Männer von Israel wandten sich um im Streit, und Benjamin hatte angefangen, unter den Männern von Israel etliche zu erschlagen, bei dreißig Mann; denn die sprachen: Sie sind ja gänzlich vor uns geschlagen, wie im vorigen Streit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Und der Brand fing an, aus der Stadt emporzusteigen wie eine Rauchsäule; und Benjamin wandte sich zurück, und siehe, die ganze Stadt ging in Feuer auf gen Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Da wandten sich die Männer von Israel um, und die Männer von Benjamin wurden bestürzt; denn sie sahen, daß das Unglück sie erreicht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Und sie wandten sich vor den Männern von Israel nach dem Wege zur Wüste; aber der Streit ereilte sie; und die aus den Städten kamen, streckten sie in ihrer Mitte nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Sie umzingelten Benjamin, jagten ihm nach, traten ihn nieder, wo er ausruhen wollte, bis vor Gibea, gegen Sonnenaufgang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Und es fielen von Benjamin achtzehntausend Mann; diese alle waren tapfere Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Da wandten sie sich und flohen der Wüste zu, nach dem Felsen Rimmon; aber die Israeliten hielten unter ihnen auf den Landstraßen eine Nachlese von fünftausend Mann, und setzten ihnen nach bis Gideom und erschlugen von ihnen zweitausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'So waren all der von Benjamin an selbigem Tage Gefallenen fünfundzwanzigtausend Mann, die das Schwert zogen; diese alle waren tapfere Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Sechshundert Mann aber wandten sich und flohen der Wüste zu, nach dem Felsen Rimmon; und sie blieben am Felsen Rimmon vier Monate. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Und die Männer von Israel kehrten zu den Kindern Benjamin zurück und schlugen sie mit der Schärfe des Schwertes, von den Männern in den Städten bis zum Vieh, bis zu allem, was sich vorfand; auch alle die Städte, die sich vorfanden, steckten sie in Brand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Die Männer von Israel hatten aber zu Mizpa geschworen und gesagt: Niemand von uns soll seine Tochter den Benjaminitern zum Weibe geben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Und das Volk kam nach Bethel, und sie blieben daselbst bis an den Abend vor Gott; und sie erhoben ihre Stimme und weinten sehr und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Warum, Jehova, Gott Israels, ist dieses in Israel geschehen, daß heute ein Stamm aus Israel vermißt wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Und es geschah am anderen Tage, da machte sich das Volk früh auf, und sie bauten daselbst einen Altar und opferten Brandopfer und Friedensopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Und die Kinder Israel sprachen: Wer von allen Stämmen Israels ist nicht in die Versammlung zu Jehova heraufgekommen? Denn ein großer Schwur war geschehen betreffs dessen, der nicht zu Jehova nach Mizpa heraufkäme, indem man sprach: Er soll gewißlich getötet werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Und die Kinder Israel ließen sich\'s gereuen über Benjamin, ihren Bruder, und sie sprachen: Heute ist ein Stamm von Israel abgehauen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Was sollen wir ihnen, den Übriggebliebenen, tun betreffs der Weiber? Wir haben ja bei Jehova geschworen, ihnen keine von unseren Töchtern zu Weibern zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Und sie sprachen: Gibt es irgend einen von den Stämmen Israels, der nicht zu Jehova nach Mizpa heraufgekommen ist? Und siehe, kein Mann von Jabes-Gilead war ins Lager, in die Versammlung, gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Und das Volk wurde gemustert, und siehe, kein Mann war da von den Bewohnern von Jabes-Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Da sandte die Gemeinde zwölftausend Mann von den tapferen Männern dorthin, und sie geboten ihnen und sprachen: Gehet hin und schlaget die Bewohner von Jabes-Gilead mit der Schärfe des Schwertes, auch die Weiber und die Kinder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Und dies ist es, was ihr tun sollt: Alle Männlichen und alle Weiber, die den Beischlaf eines Mannes gekannt haben, sollt ihr verbannen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Und sie fanden unter den Bewohnern von Jabes-Gilead vierhundert Mädchen, Jungfrauen, die keinen Mann im Beischlaf erkannt hatten; und sie brachten sie ins Lager nach Silo, das im Lande Kanaan ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Und die ganze Gemeinde sandte hin und redete zu den Kindern Benjamin, die am Felsen Rimmon waren, und entbot ihnen Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Und Benjamin kehrte in selbiger Zeit zurück; und sie gaben ihnen die Weiber, welche sie hatten leben lassen von den Weibern von Jabes-Gilead; aber sie fanden so nicht genug für sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Und das Volk ließ sich\'s gereuen wegen Benjamins, weil Jehova einen Riß gemacht hatte in den Stämmen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Und die Ältesten der Gemeinde sprachen: Was sollen wir den Übriggebliebenen tun betreffs der Weiber? Denn die Weiber sind aus Benjamin vertilgt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Und sie sprachen: Ein Besitztum soll sein für die Entronnenen von Benjamin, damit nicht ein Stamm aus Israel ausgetilgt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Wir aber, wir können ihnen keine Weiber von unseren Töchtern geben; denn die Kinder Israel haben geschworen und gesagt: Verflucht sei, wer den Benjaminitern ein Weib gibt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Und sie sprachen: Siehe, ein Fest Jehovas ist von Jahr zu Jahr zu Silo, das nördlich von Bethel, gegen Sonnenaufgang von der Landstraße, die von Bethel nach Sichem hinaufgeht, und südlich von Lebona liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Und sie geboten den Kindern Benjamin und sprachen: Gehet hin und lauert in den Weinbergen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'und sehet zu, und siehe, wenn die Töchter von Silo herausziehen zum Reigentanze, so kommet hervor aus den Weinbergen und erhaschet euch unter den Töchtern von Silo ein jeder sein Weib, und ziehet hin in das Land Benjamin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Und es soll geschehen, wenn ihre Väter oder ihre Brüder kommen, um mit uns zu rechten, so wollen wir zu ihnen sagen: Gewähret sie uns! Denn wir haben nicht ein jeder sein Weib im Kriege empfangen; denn nicht ihr habt sie ihnen gegeben, daß ihr jetzt schuldig wäret.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Und die Kinder Benjamin taten also und nahmen sich Weiber, nach ihrer Zahl, von den Tänzerinnen, die sie raubten. Und sie zogen fort und kehrten in ihr Erbteil zurück; und sie bauten die Städte wieder auf und wohnten darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Und die Kinder Israel zogen in selbiger Zeit von dannen, ein jeder zu seinem Stamme und zu seinem Geschlecht; und sie zogen von dannen hinweg, ein jeder in sein Erbteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'In jenen Tagen war kein König in Israel; ein jeder tat, was recht war in seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Und es geschah in den Tagen, als die Richter richteten, da entstand eine Hungersnot im Lande. Und ein Mann von Bethlehem-Juda zog hin, um sich in den Gefilden Moabs aufzuhalten, er und sein Weib und seine beiden Söhne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Und der Name des Mannes war Elimelech, und der Name seines Weibes Noomi, und die Namen seiner beiden Söhne Machlon und Kiljon, Ephratiter von Bethlehem-Juda. Und sie kamen in die Gefilde Moabs und blieben daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Und Elimelech, der Mann Noomis, starb: und sie blieb mit ihren beiden Söhnen übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Und sie nahmen sich moabitische Weiber: der Name der einen war Orpa, und der Name der anderen Ruth; und sie wohnten daselbst bei zehn Jahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Da starben auch die beiden, Machlon und Kiljon; und das Weib blieb allein übrig von ihren beiden Söhnen und von ihrem Manne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Und sie machte sich auf, sie und ihre Schwiegertöchter, und kehrte aus den Gefilden Moabs zurück; denn sie hatte im Gefilde Moabs gehört, daß Jehova sein Volk heimgesucht habe, um ihnen Brot zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Und sie zog aus von dem Orte, wo sie gewesen war, und ihre beiden Schwiegertöchter mit ihr; und sie zogen des Weges, um in das Land Juda zurückzukehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Da sprach Noomi zu ihren beiden Schwiegertöchtern: Gehet, kehret um, eine jede zum Hause ihrer Mutter. Jehova erweise Güte an euch, so wie ihr sie an den Verstorbenen und an mir erwiesen habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Jehova gebe euch, daß ihr Ruhe findet, eine jede in dem Hause ihres Mannes! Und sie küßte sie. Und sie erhoben ihre Stimme und weinten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'und sie sprachen zu ihr: Doch, wir wollen mit dir zu deinem Volke zurückkehren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Und Noomi sprach: Kehret um, meine Töchter! Warum wolltet ihr mit mir gehen? Habe ich noch Söhne in meinem Leibe, daß sie euch zu Männern werden könnten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Kehret um, meine Töchter, gehet; denn ich bin zu alt, um eines Mannes zu werden. Wenn ich spräche: Ich habe Hoffnung; wenn ich selbst diese Nacht eines Mannes würde und sogar Söhne gebären sollte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'wolltet ihr deshalb warten, bis sie groß würden? Wolltet ihr deshalb euch abschließen, daß ihr keines Mannes würdet? Nicht doch, meine Töchter! Denn mir ergeht es viel bitterer als euch; denn die Hand Jehovas ist wider mich ausgegangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Da erhoben sie ihre Stimme und weinten wiederum. Und Orpa küßte ihre Schwiegermutter; Ruth aber hing ihr an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Und sie sprach: Siehe, deine Schwägerin ist zu ihrem Volke und zu ihren Göttern zurückgekehrt; kehre um, deiner Schwägerin nach!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Aber Ruth sprach: Dringe nicht in mich, dich zu verlassen, hinter dir weg umzukehren; denn wohin du gehst, will ich gehen, und wo du weilst, will ich weilen; dein Volk ist mein Volk, und dein Gott ist mein Gott;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'wo du stirbst, will ich sterben, und daselbst will ich begraben werden. So soll mir Jehova tun und so hinzufügen, nur der Tod soll scheiden zwischen mir und dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Und als sie sah, daß sie fest darauf bestand, mit ihr zu gehen, da ließ sie ab, ihr zuzureden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Und so gingen beide, bis sie nach Bethlehem kamen. Und es geschah, als sie nach Bethlehem kamen, da geriet die ganze Stadt ihretwegen in Bewegung, und sie sprachen: Ist das Noomi?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Und sie sprach zu ihnen: Nennet mich nicht Noomi, nennet mich Mara; denn der Allmächtige hat es mir sehr bitter gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Voll bin ich gegangen, und leer hat mich Jehova zurückkehren lassen. Warum nennet ihr mich Noomi, da Jehova gegen mich gezeugt, und der Allmächtige mir Übles getan hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Und so kehrte Noomi zurück, und Ruth, die Moabitin, ihre Schwiegertochter, mit ihr, welche aus den Gefilden Moabs zurückkehrte; und sie kamen nach Bethlehem beim Beginn der Gerstenernte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Und Noomi hatte einen Verwandten ihres Mannes, einen vermögenden Mann, aus dem Geschlecht Elimelechs, und sein Name war Boas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Und Ruth, die Moabitin, sprach zu Noomi: Laß mich doch aufs Feld gehen und unter den Ähren lesen hinter dem her, in dessen Augen ich Gnade finden werde. Und sie sprach zu ihr: Gehe hin, meine Tochter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Und sie ging hin und kam und las auf dem Felde hinter den Schnittern her; und sie traf zufällig das Feldstück des Boas, der aus dem Geschlecht Elimelechs war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Und siehe, Boas kam von Bethlehem und sprach zu den Schnittern: Jehova sei mit euch! Und sie sprachen zu ihm: Jehova segne dich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Und Boas sprach zu seinem Knechte, der über die Schnitter bestellt war: Wem gehört dieses Mädchen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Und der Knecht, der über die Schnitter bestellt war, antwortete und sprach: Es ist ein moabitisches Mädchen, das mit Noomi aus den Gefilden Moabs zurückgekehrt ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'und sie sprach: Laß mich doch auflesen und unter den Garben sammeln hinter den Schnittern her! Und so ist die gekommen und dageblieben vom Morgen an bis jetzt; was sie im Hause gesessen hat, ist wenig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Und Boas sprach zu Ruth: Hörst du, meine Tochter? Gehe nicht, um auf einem anderen Felde aufzulesen, und gehe auch nicht von hinnen, sondern halte dich hier zu meinen Mägden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Deine Augen seien auf das Feld gerichtet, welches man schneidet, und gehe hinter ihnen her; habe ich nicht den Knaben geboten, dich nicht anzutasten? Und wenn dich dürstet, so gehe zu den Gefäßen und trinke von dem, was die Knaben schöpfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Da fiel sie auf ihr Angesicht und beugte sich zur Erde nieder und sprach zu ihm: Warum habe ich Gnade gefunden in deinen Augen, daß du mich beachtest, da ich doch eine Fremde bin?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Und Boas antwortete und sprach zu ihr: Es ist mir alles wohl berichtet worden, was du an deiner Schwiegermutter getan hast nach dem Tode deines Mannes, indem du deinen Vater und deine Mutter und das Land deiner Geburt verlassen hast und zu einem Volke gezogen bist, das du früher nicht kanntest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Jehova vergelte dir dein Tun, und voll sei dein Lohn von Jehova, dem Gott Israels, unter dessen Flügeln Zuflucht zu suchen du gekommen bist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Und sie sprach: Möge ich Gnade finden in deinen Augen, mein Herr! Denn du hast mich getröstet und hast zum Herzen deiner Magd geredet, und doch bin ich nicht wie eine deiner Mägde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Und Boas sprach zu ihr zur Zeit des Essens: Tritt hierher, und iß von dem Brote und tunke deinen Bissen in den Essig. Da setzte sie sich zur Seite der Schnitter; und er reichte ihr geröstete Körner, und sie aß und wurde satt und ließ übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Und sie stand auf, um aufzulesen; und Boas gebot seinen Knaben und sprach: Auch zwischen den Garben mag sie auflesen, und ihr sollt sie nicht beschämen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'und auch sollt ihr selbst aus den Bündeln Ähren für sie herausziehen und sie liegen lassen, damit sie sie auflese, und sollt sie nicht schelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Und sie las auf dem Felde auf bis zum Abend, und sie schlug aus, was sie aufgelesen hatte, und es war bei einem Epha Gerste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Und sie nahm es auf und kam in die Stadt, und ihre Schwiegermutter sah, was sie aufgelesen hatte; und sie zog hervor und gab ihr, was sie übriggelassen, nachdem sie sich gesättigt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Da sprach ihre Schwiegermutter zu ihr: Wo hast du heute aufgelesen, und wo hast du gearbeitet? Gesegnet sei, der dich beachtet hat! Und sie tat ihrer Schwiegermutter kund, bei wem sie gearbeitet hatte, und sprach: Der Name des Mannes, bei dem ich heute gearbeitet habe, ist Boas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Da sprach Noomi zu ihrer Schwiegertochter: Gesegnet sei er von Jehova, dessen Güte nicht abgelassen hat von den Lebenden und von den Toten! Und Noomi sprach zu ihr: Der Mann ist uns nahe verwandt, er ist einer von unseren Blutsverwandten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Und Ruth, die Moabitin, sprach: Er hat auch zu mir gesagt: Du sollst dich zu meinen Leuten halten, bis sie meine ganze Ernte beendigt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Und Noomi sprach zu Ruth, ihrer Schwiegertochter: Es ist gut, meine Tochter, daß du mit seinen Mägden ausgehst, daß man dich nicht anfalle auf einem anderen Felde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Und so hielt sie sich zu den Mägden des Boas, um aufzulesen, bis die Gerstenernte und die Weizenernte beendigt waren. Und sie wohnte bei ihrer Schwiegermutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Und Noomi, ihre Schwiegermutter, sprach zu ihr: Meine Tochter, sollte ich dir nicht Ruhe suchen, daß es dir wohl gehe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Und nun, ist nicht Boas, bei dessen Mägden du gewesen bist, unser Verwandter? Siehe, er worfelt diese Nacht auf der Gerstentenne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'So bade dich und salbe dich und lege deine Kleider an, und gehe zur Tenne hinab; laß dich nicht von dem Manne bemerken, bis er fertig ist mit Essen und Trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Und es geschehe, wenn er sich niederlegt, so merke den Ort, wo er sich hinlegt, und gehe und decke auf zu seinen Füßen und lege dich hin; er aber wird dir kundtun, was du tun sollst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Und sie sprach zu ihr: Alles, was du sagst, will ich tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Und sie ging zur Tenne hinab und tat nach allem, was ihre Schwiegermutter ihr geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Und Boas aß und trank, und sein Herz wurde fröhlich; und er kam, um sich an dem Ende des Getreidehaufens niederzulegen. Da kam sie leise und deckte zu seinen Füßen auf und legte sich hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Und es geschah um Mitternacht, da schrak der Mann auf und beugte sich hin: und siehe, ein Weib lag zu seinen Füßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Und er sprach: Wer bist du? Und sie sprach: Ich bin Ruth, deine Magd; so breite deine Flügel aus über deine Magd, denn du bist ein Blutsverwandter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Und er sprach: Gesegnet seiest du von Jehova, meine Tochter! Du hast deine letzte Güte noch besser erwiesen als die erste, indem du nicht den Jünglingen nachgegangen bist, sei es armen oder reichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Und nun, meine Tochter, fürchte dich nicht! Alles, was du sagst, werde ich dir tun; denn das ganze Tor meines Volkes weiß, daß du ein wackeres Weib bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Und nun, wahrlich, ich bin ein Blutsverwandter; doch ist auch ein näherer Blutsverwandter da als ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Bleibe diese Nacht; und es soll am Morgen geschehen, wenn er dich lösen will, gut, so mag er lösen; wenn er aber keine Lust hat, dich zu lösen, so werde ich dich lösen, so wahr Jehova lebt! Liege bis zum Morgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Und sie lag zu seinen Füßen bis zum Morgen; und sie stand auf, ehe einer den anderen erkennen konnte; denn er sprach: Es werde nicht kund, daß ein Weib auf die Tenne gekommen ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Und er sprach: Gib den Mantel her, den du anhast, und halte ihn. Und sie hielt ihn, und er maß sechs Maß Gerste und legte sie ihr auf; und er ging in die Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Und sie kam zu ihrer Schwiegermutter; und sie sprach: Wie steht es mit dir, meine Tochter? Und sie berichtete ihr alles, was der Mann ihr getan hatte, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Diese sechs Maß Gerste gab er mir, denn er sagte: Du sollst nicht leer zu deiner Schwiegermutter kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Und sie sprach: Bleibe, meine Tochter, bis du weißt, wie die Sache ausfällt; denn der Mann wird nicht ruhen, er habe denn die Sache heute zu Ende geführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Und Boas ging zum Tore hinauf und setzte sich daselbst. Und siehe, der Blutsverwandte ging vorüber, von dem Boas geredet hatte. Da sprach er: Komm her, setze dich hierher, du, der und der. Und er kam herzu und setzte sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Und Boas nahm zehn Männer von den Ältesten der Stadt und sprach: Setzet euch hierher; und sie setzten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Und er sprach zu dem Blutsverwandten: Noomi, die aus dem Gefilde Moabs zurückgekehrt ist, verkauft das Feldstück, welches unserem Bruder Elimelech gehörte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'so habe ich nun gedacht, ich wolle es deinem Ohr eröffnen und dir sagen: Kaufe es vor den Einwohnern und vor den Ältesten meines Volkes. Wenn du lösen willst, löse, und wenn du nicht lösen willst, so tue mir\'s kund, daß ich es wisse; denn da ist niemand außer dir zum Lösen, und ich komme nach dir. Und er sprach: Ich will lösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Da sprach Boas: An dem Tage, da du das Feld aus der Hand Noomis kaufst, hast du es auch von Ruth, der Moabitin, dem Weibe des Verstorbenen, gekauft, um den Namen des Verstorbenen auf seinem Erbteil zu erwecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Da sprach der Blutsverwandte: Ich kann nicht für mich lösen, daß ich mein Erbteil nicht verderbe. Löse du für dich, was ich lösen sollte, denn ich kann nicht lösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Dies aber geschah vordem in Israel bei einer Lösung und bei einem Tausche, um jede Sache zu bestätigen: Der eine zog seinen Schuh aus und gab ihn dem anderen; und das war die Art der Bezeugung in Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Und der Blutsverwandte sprach zu Boas: Kaufe für dich! Und er zog seinen Schuh aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Da sprach Boas zu den Ältesten und zu allem Volke: Ihr seid heute Zeugen, daß ich aus der Hand Noomis alles gekauft habe, was Elimelech, und alles, was Kiljon und Machlon gehörte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'und auch Ruth, die Moabitin, das Weib Machlons, habe ich mir zum Weibe gekauft, um den Namen des Verstorbenen auf seinem Erbteil zu erwecken, daß nicht der Name des Verstorbenen ausgerottet werde unter seinen Brüdern und aus dem Tore seines Ortes. Ihr seid heute Zeugen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Und alles Volk, das im Tore war, und die Ältesten sprachen: Wir sind Zeugen! Jehova mache das Weib, das in dein Haus kommt, wie Rahel und wie Lea, welche beide das Haus Israel erbaut haben; und werde mächtig in Ephrata und stifte einen Namen in Bethlehem!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Und von dem Samen, den Jehova dir von diesem jungen Weibe geben wird, werde dein Haus wie das Haus des Perez, welchen Tamar dem Juda geboren hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Und Boas nahm Ruth, und sie wurde sein Weib, und er ging zu ihr ein; und Jehova verlieh ihr Schwangerschaft und sie gebar einen Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Und sie Weiber sprachen zu Noomi: Gepriesen sei Jehova, der es dir heute nicht hat fehlen lassen an einem Löser! Und sein Name werde gerühmt in Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Und er wird dir ein Erquicker der Seele sein und ein Versorger deines Alters! Denn deine Schwiegertochter, die dich liebt, hat ihn geboren, sie, die dir besser ist als sieben Söhne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Und Noomi nahm das Kind und legte es auf ihren Schoß und wurde seine Wärterin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Und die Nachbarinnen gaben ihm einen Namen, indem sie sprachen: Ein Sohn ist der Noomi geboren! Und sie gaben ihm den Namen Obed. Er ist der Vater Isais, des Vaters Davids.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Und dies sind die Geschlechter des Perez: Perez zeugte Hezron,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'und Hezron zeugte Ram, und Ram zeugte Amminadab,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'und Amminadab zeugte Nachschon, und Nachschon zeugte Salma,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'und Salmon zeugte Boas, und Boas zeugte Obed,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'und Obed zeugte Isai, und Isai zeugte David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Und es war ein Mann von Ramathajim-Zophim, vom Gebirge Ephraim, und sein Name war Elkana, der Sohn Jerochams, des Sohnes Elihus, des Sohnes Tochus, des Sohnes Zuphs, ein Ephratiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Und er hatte zwei Weiber: der Name der einen war Hanna, und der Name der anderen Peninna; und Peninna hatte Kinder, aber Hanna hatte keine Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Und dieser Mann ging von Jahr zu Jahr aus seiner Stadt hinauf, um Jehova der Heerscharen anzubeten und ihm zu opfern zu Silo; und daselbst waren die beiden Söhne Elis, Hophni und Pinehas, Priester Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Und es geschah an dem Tage, da Elkana opferte, da gab er seinem Weibe Peninna und allen ihren Söhnen und ihren Töchtern Stücke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'aber Hanna gab er ein doppeltes Stück, denn er liebte Hanna; aber Jehova hatte ihren Mutterleib verschlossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Und ihre Widersacherin kränkte sie mit vieler Kränkung, um sie aufzubringen, weil Jehova ihren Mutterleib verschlossen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Und so wie er das Jahr für Jahr tat, also kränkte sie sie, so oft sie zum Hause Jehovas hinaufzog; und sie weinte und aß nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Und Elkana, ihr Mann, sprach zu ihr: Hanna, warum weinst du? Und warum issest du nicht? Und warum ist dein Herz betrübt? Bin ich dir nicht besser als zehn Söhne?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Und Hanna stand auf nach dem Essen und nach dem Trinken zu Silo. Eli, der Priester, saß aber auf dem Stuhle an einem der Türpfosten des Tempels Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Und sie war bitteren Gemütes, und sie flehte zu Jehova und weinte sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Und sie tat ein Gelübde und sprach: Jehova der Heerscharen! Wenn du das Elend deiner Magd ansehen und meiner gedenken und deine Magd nicht vergessen wirst und wirst deiner Magd männlichen Samen geben, so will ich ihn Jehova geben alle Tage seines Lebens; und kein Schermesser soll auf sein Haupt kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Und es geschah, als sie lange vor Jehova betete, daß Eli ihren Mund beobachtete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Hanna aber redete in ihrem Herzen; nur ihre Lippen bewegten sich, aber ihre Stimme wurde nicht gehört; und Eli hielt sie für eine Trunkene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Und Eli sprach zu ihr: Bis wann willst du dich wie eine Trunkene gebärden? Tue deinen Wein von dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Aber Hanna antwortete und sprach: Nein, mein Herr! Ein Weib beschwerten Geistes bin ich; weder Wein noch starkes Getränk habe ich getrunken, sondern ich schüttete meine Seele vor Jehova aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Setze nicht deine Magd einer Tochter Belials gleich; denn aus der Fülle meines Kummers und meiner Kränkung habe ich bisher geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Und Eli antwortete und sprach: Gehe hin in Frieden; und der Gott Israels gewähre deine Bitte, die du von ihm erbeten hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Und sie sprach: Möge deine Magd Gnade finden in deinen Augen! Und das Weib ging ihres Weges und aß, und ihr Angesicht war nicht mehr dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Und sie machten sich des Morgens früh auf und beteten an vor Jehova; und sie kehrten zurück und kamen in ihr Haus nach Rama. Und Elkana erkannte Hanna, sein Weib, und Jehova gedachte ihrer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Und es geschah nach Umlauf der Zeit, da ward Hanna schwanger und gebar einen Sohn; und sie gab ihm den Namen Samuel: Denn von Jehova habe ich ihn erbeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Und der Mann Elkana ging hinauf mit seinem ganzen Hause, um Jehova das jährliche Schlachtopfer zu opfern und sein Gelübde zu erfüllen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Aber Hanna ging nicht hinauf; denn sie sprach zu ihrem Manne: Bis der Knabe entwöhnt ist, dann will ich ihn bringen, daß er vor Jehova erscheine und dort bleibe auf immer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Und Elkana, ihr Mann, sprach zu ihr: Tue, was gut ist in deinen Augen; bleibe, bis du ihn entwöhnt hast; nur möge Jehova sein Wort aufrecht halten! So blieb das Weib und säugte ihren Sohn, bis sie ihn entwöhnt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Und sobald sie ihn entwöhnt hatte, brachte sie ihn mit sich hinauf nebst drei Farren und einem Epha Mehl und einem Schlauch Wein, und brachte ihn in das Haus Jehovas nach Silo; und der Knabe war noch jung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Und sie schlachteten den Farren und brachten den Knaben zu Eli.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Und sie sprach: Bitte, mein Herr! So wahr deine Seele lebt, mein Herr, ich bin das Weib, das hier bei dir stand, um zu Jehova zu flehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Um diesen Knaben habe ich gefleht, und Jehova hat mir meine Bitte gewährt, die ich von ihm erbeten habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'So habe auch ich ihn Jehova geliehen; alle die Tage, die er lebt, ist er Jehova geliehen. Und er betete daselbst Jehova an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Und Hanna betete und sprach: Es frohlockt mein Herz in Jehova, erhöht ist mein Horn in Jehova; mein Mund ist weit aufgetan über meine Feinde, denn ich freue mich in deiner Rettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Keiner ist heilig wie Jehova, denn keiner ist außer dir, und kein Fels ist wie unser Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Häufet nicht Worte des Stolzes, noch gehe Freches aus eurem Munde hervor; denn ein Gott des Wissens ist Jehova, und von ihm werden die Handlungen gewogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Die Bogen der Helden sind zerbrochen, und die Strauchelnden haben sich mit Kraft umgürtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Die satt waren, haben sich um Brot verdungen, und die hungrig waren, sind es nicht mehr; sogar die Unfruchtbare hat sieben geboren, und die Kinderreiche ist dahingewelkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Jehova tötet und macht lebendig; er führt in den Scheol hinab und führt herauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Jehova macht arm und macht reich; er erniedrigt und erhöht auch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Er hebt aus dem Staube empor den Geringen, aus dem Kote erhöht er den Armen, um sie sitzen zu lassen bei den Edlen; und den Thron der Ehre gibt er ihnen als Erbteil. Denn Jehovas sind die Säulen der Erde, und auf sie hat er den Erdkreis gestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Die Füße seiner Frommen bewahrt er, aber die Gesetzlosen verstummen in Finsternis; denn nicht durch Stärke hat der Mensch die Oberhand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Jehova es werden zerschmettert werden, die mit ihm hadern; über ihnen im Himmel wird er donnern. Jehova wird richten die Enden der Erde, und Macht verleihen seinem König und erhöhen das Horn seines Gesalbten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Und Elkana ging nach Rama, nach seinem Hause. Der Knabe aber diente Jehova vor Eli, dem Priester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Und die Söhne Elis waren Söhne Belials, sie kannten Jehova nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Und die Weise der Priester gegen das Volk war also: So oft jemand ein Schlachtopfer opferte, kam der Knabe des Priesters, wenn man das Fleisch kochte, und hatte eine Gabel mit drei Zinken in seiner Hand;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'und er stieß in das Becken oder in die Mulde oder in den Kessel oder in den Topf: Alles, was die Gabel heraufbrachte, nahm der Priester damit weg. Also taten sie zu Silo allen Israeliten, die dahin kamen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Sogar ehe man das Fett räucherte, kam der Knabe des Priesters und sprach zu dem Manne, der opferte: Gib Fleisch zum Braten für den Priester! Denn er will kein gekochtes Fleisch von dir annehmen, sondern rohes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Und sprach der Mann zu ihm: Sogleich werden sie das Fett räuchern, dann nimm dir, wie deine Seele begehrt; so sprach er: Nein, sondern jetzt sollst du es geben, und wenn nicht, so nehme ich es mit Gewalt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Und die Sünde der Jünglinge war sehr groß vor Jehova; denn die Leute verachteten die Opfergabe Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Und Samuel diente vor Jehova, ein Knabe, umgürtet mit einem leinenen Ephod.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Und seine Mutter machte ihm ein kleines Oberkleid und brachte es ihm von Jahr zu Jahr hinauf, wenn sie mit ihrem Manne hinaufging, um das jährliche Schlachtopfer zu opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Und Eli segnete Elkana und sein Weib und sprach: Jehova gebe dir Samen von diesem Weibe an Stelle des Geliehenen, das man Jehova geliehen hat. Und sie gingen nach Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Und Jehova suchte Hanna heim, und sie wurde schwanger; und sie gebar drei Söhne und zwei Töchter. Und der Knabe Samuel wurde groß bei Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Und Eli war sehr alt; und er hörte alles, was seine Söhne dem ganzen Israel taten, und daß sie bei den Weibern lagen, die sich scharten am Eingang des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Und er sprach zu ihnen: Warum tut ihr dergleichen Dinge? Denn ich höre diese eure bösen Handlungen von dem ganzen Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Nicht so, meine Söhne! Denn nicht gut ist das Gerücht, das ich höre; ihr machet das Volk Jehovas übertreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Wenn ein Mensch gegen einen Menschen sündigt, so entscheidet Gott über ihn; wenn aber ein Mensch gegen Jehova sündigt, wer wird für ihn bitten? Aber sie hörten nicht auf die Stimme ihres Vaters, denn Jehova war willens, sie zu töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Und der Knabe Samuel wurde fort und fort größer und angenehmer, sowohl bei Jehova als auch bei den Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Und es kam ein Mann Gottes zu Eli und sprach zu ihm: So spricht Jehova: Habe ich mich dem Hause deines Vaters nicht deutlich geoffenbart, als sie in Ägypten waren im Hause des Pharao?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Und ich habe ihn aus allen Stämmen Israels mir zum Priester erwählt, um auf meinem Altar zu opfern, um Räucherwerk zu räuchern, um das Ephod vor mir zu tragen; und ich gab dem Hause deines Vaters alle Feueropfer der Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Warum tretet ihr mit Füßen mein Schlachtopfer und mein Speisopfer, die ich in der Wohnung geboten habe? Und du ehrest deine Söhne mehr als mich, daß ihr euch mästet von den Erstlingen aller Opfergaben Israels, meines Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Darum spricht Jehova, der Gott Israels: Ich habe allerdings gesagt: Dein Haus und das Haus deines Vaters sollen vor mir wandeln ewiglich; aber nun spricht Jehova: Fern sei es von mir! Denn die mich ehren, werde ich ehren, und die mich verachten, werden gering geachtet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Siehe, Tage kommen, da werde ich deinen Arm und den Arm des Hauses deines Vaters abhauen, daß es keinen Greis mehr in deinem Hause geben wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Und du wirst einen Bedränger in der Wohnung sehen, in allem, was Jehova Gutes tun wird an Israel; und es wird keinen Greis mehr in deinem Hause geben alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Und der Mann, den ich dir nicht ausrotten werde von meinem Altar, wird zum Erlöschen deiner Augen und zum Verschmachten deiner Seele sein; und aller Anwuchs deines Hauses, sie sollen als Männer sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Und dies soll dir das Zeichen sein: Das, was über deine beiden Söhne kommen wird, über Hophni und Pinehas: An einem Tage sollen sie beide sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Und ich werde mir einen treuen Priester erwecken: Der wird tun, wie es in meinem Herzen und in meiner Seele ist; und ich werde ihm ein beständiges Haus bauen, und er wird vor meinem Gesalbten wandeln alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Und es soll geschehen, ein jeder, der in deinem Hause übrigbleibt, wird kommen, um sich vor ihm niederzuwerfen für eine kleine Silbermünze und einen Laib Brot, und wird sagen: Geselle mich doch einem der Priesterämter bei, daß ich einen Bissen Brot esse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Und der Knabe Samuel diente Jehova vor Eli. Und das Wort Jehovas war selten in jenen Tagen, Gesichte waren nicht häufig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Und es geschah in selbiger Zeit, als Eli an seinem Orte lag seine Augen aber hatten begonnen, blöde zu werden, er konnte nicht sehen-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'und die Lampe Gottes war noch nicht erloschen, und Samuel lag im Tempel Jehovas, woselbst die Lade Gottes war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'da rief Jehova den Samuel. Und er sprach: Hier bin ich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Und er lief zu Eli und sprach: Hier bin ich, denn du hast mich gerufen. Aber er sprach: Ich habe nicht gerufen, lege dich wieder. Und er ging hin und legte sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Und Jehova rief wiederum: Samuel! Und Samuel stand auf und ging zu Eli und sprach: Hier bin ich, denn du hast mich gerufen. Und er sprach: Ich habe nicht gerufen, mein Sohn, lege dich wieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Samuel aber kannte Jehova noch nicht, und das Wort Jehovas war ihm noch nicht geoffenbart.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Und Jehova rief wiederum zum dritten Male: Samuel! Und er stand auf und ging zu Eli und sprach: Hier bin ich, denn du hast mich gerufen. Da erkannte Eli, daß Jehova den Knaben rief.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Und Eli sprach zu Samuel: Gehe hin, lege dich; und es geschehe, wenn man dich ruft, so sprich: Rede, Jehova, denn dein Knecht hört. Und Samuel ging hin und legte sich an seinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Und Jehova kam und trat hin und rief wie die anderen Male: Samuel, Samuel! Und Samuel sprach: Rede, denn dein Knecht hört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Da sprach Jehova zu Samuel: Siehe, ich will eine Sache tun in Israel, daß jedem, der sie hört, seine beiden Ohren gellen sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'An selbigem Tage werde ich wider Eli alles ausführen, was ich über sein Haus geredet habe: ich werde beginnen und vollenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Denn ich habe ihm kundgetan, daß ich sein Haus richten will ewiglich, um der Ungerechtigkeit willen, die er gewußt hat, daß seine Söhne sich den Fluch zuzogen, und er ihnen nicht gewehrt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Und darum habe ich dem Hause Elis geschworen: Wenn Ungerechtigkeit des Hauses Elis gesühnt werden soll durch Schlachtopfer und durch Speisopfer ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Und Samuel lag bis zum Morgen; da tat er die Tür des Hauses Jehovas auf. Und Samuel fürchtete sich, Eli das Gesicht kundzutun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Da rief Eli den Samuel und sprach: Samuel, mein Sohn! Und er sprach: Hier bin ich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Und er sprach: Was ist das Wort, das er zu dir geredet hat? Verhehle es mir doch nicht. So tue dir Gott und so füge er hinzu, wenn du mir etwas verhehlst von allem, was er zu dir geredet hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Da tat ihm Samuel alle die Worte kund und verhehlte ihm nichts. Und er sprach: Er ist Jehova; er tue, was gut ist in seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Und Samuel wurde groß; und Jehova war mit ihm und ließ keines von allen seinen Worten auf die Erde fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Und ganz Israel, von Dan bis Beerseba, erkannte, daß Samuel als Prophet Jehovas bestätigt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Und Jehova fuhr fort in Silo zu erscheinen; denn Jehova offenbarte sich dem Samuel in Silo durch das Wort Jehovas. Und das Wort Samuels erging an ganz Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Und Israel zog aus, den Philistern entgegen zum Streit; und sie lagerten sich bei Eben-Eser, und die Philister lagerten zu Aphek.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Und die Philister stellten sich auf, Israel gegenüber; und der Streit breitete sich aus, und Israel wurde vor den Philistern geschlagen; und sie erschlugen in der Schlachtordnung auf dem Felde bei viertausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Und als das Volk ins Lager zurückkam, da sprachen die Ältesten von Israel: Warum hat Jehova uns heute vor den Philistern geschlagen? Laßt uns von Silo die Lade des Bundes Jehovas zu uns holen, daß sie in unsere Mitte komme und uns rette aus der Hand unserer Feinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Und das Volk sandte nach Silo, und man brachte von dannen die Lade des Bundes Jehovas der Heerscharen, der zwischen den Cherubim thront; und die beiden Söhne Elis, Hophni und Pinehas, waren daselbst bei der Lade des Bundes Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Und es geschah, als die Lade des Bundes Jehovas ins Lager kam, da jauchzte ganz Israel mit großem Jauchzen, daß die Erde erdröhnte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Und die Philister hörten den Schall des Jauchzens und sprachen: Was bedeutet der Schall dieses großen Jauchzens im Lager der Hebräer? Und sie merkten, daß die Lade Jehovas ins Lager gekommen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Da fürchteten sich die Philister, denn die sprachen: Gott ist ins Lager gekommen! Und sie sprachen: Wehe uns! Denn solches ist vordem nie geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Wehe uns! Wer wird uns aus der Hand dieser mächtigen Götter erretten? Das sind die Götter, welche die Ägypter schlugen mit allerlei Plagen in der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Fasset Mut und seid Männer, ihr Philister, daß ihr nicht den Hebräern dienen müsset, wie sie euch gedient haben; so seid denn Männer und streitet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Und die Philister stritten, und Israel wurde geschlagen, und sie flohen ein jeder nach seinem Zelte; und die Niederlage war sehr groß, und es fielen von Israel dreißigtausend Mann zu Fuß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Und die Lade Gottes wurde genommen, und die beiden Söhne Elis, Hophni und Pinehas, starben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Und es lief ein Mann von Benjamin aus der Schlachtordnung und kam nach Silo an selbigem Tage, seine Kleider waren zerrissen, und Erde war auf seinem Haupte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Und als er kam, siehe, da saß Eli auf einem Stuhle, spähend an der Seite des Weges; denn sein Herz war bange wegen der Lade Gottes. Und als der Mann kam, um es in der Stadt zu berichten, da schrie die ganze Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Und Eli hörte den Schall des Geschreis und sprach: Was bedeutet dieser Schall des Getümmels? Und der Mann eilte und kam und berichtete es Eli.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Eli aber war achtundneunzig Jahre alt, und seine Augen waren starr, und er konnte nicht sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Und der Mann sprach zu Eli: Ich bin der, welcher aus der Schlachtordnung gekommen ist, und ich bin heute aus der Schlachtordnung geflohen. Und er sprach: Wie stand die Sache, mein Sohn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Und der Bote antwortete und sprach: Israel ist vor den Philistern geflohen, und auch hat eine große Niederlage unter dem Volke stattgefunden, und auch deine beiden Söhne, Hophni und Pinehas, sind tot, und die Lade Gottes ist genommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Und es geschah, als er die Lade Gottes erwähnte, da fiel Eli rücklings vom Stuhle, an der Seite des Tores, und brach das Genick und starb; denn der Mann war alt und schwer. Und er hatte Israel vierzig Jahre gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Und seine Schwiegertochter, das Weib des Pinehas, war schwanger zum Gebären; und als sie die Nachricht hörte, daß die Lade Gottes genommen, und daß ihr Schwiegervater und ihr Mann tot wären, da sank sie nieder und gebar, denn es überfielen sie ihre Wehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Und um die Zeit ihres Sterbens, da sprachen die Weiber, die um sie her standen: Fürchte dich nicht, denn einen Sohn hast du geboren! Aber sie antwortete nicht und nahm es nicht zu Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Und sie nannte den Knaben Ikabod, indem sie sprach: Die Herrlichkeit ist von Israel gewichen! weil die Lade Gottes genommen war, und wegen ihres Schwiegervaters und ihres Mannes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Und sie sprach: Die Herrlichkeit ist von Israel gewichen, denn die Lade Gottes ist genommen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Und die Philister hatten die Lade Gottes genommen und brachten sie von Eben-Eser nach Asdod.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Und die Philister nahmen die Lade Gottes und brachten sie in das Haus Dagons und stellten sie neben Dagon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Und als die Asdoditer am anderen Tage früh aufstanden, siehe, da lag Dagon auf seinem Angesicht auf der Erde vor der Lade Jehovas; und sie nahmen Dagon und stellten ihn wieder an seinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Und als die am anderen Tage des Morgens früh aufstanden, siehe, da lag Dagon auf seinem Angesicht auf der Erde vor der Lade Jehovas; und zwar lagen das Haupt Dagons und seine beiden Hände abgehauen auf der Schwelle, nur der Fischrumpf war an ihm übriggeblieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Darum treten die Priester Dagons und alle, die in das Haus Dagons gehen, nicht auf die Schwelle Dagons in Asdod bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Und die Hand Jehovas lag schwer auf den Asdoditern, und er verwüstete sie; und er schlug sie mit Beulen, Asdod und sein Gebiet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Und als die Leute von Asdod sahen, daß dem also war, sprachen sie: Die Lade des Gottes Israels soll nicht bei uns bleiben; denn seine Hand ist hart über uns und über Dagon, unserem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Und sie sandten hin und versammelten alle Fürsten der Philister zu sich und sprachen: Was sollen wir mit der Lade des Gottes Israels tun? Und sie sprachen: Man schaffe die Lade des Gottes Israels nach Gath. Und sie schafften die Lade des Gottes Israels hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Und es geschah, nachdem sie sie hingeschafft hatten, da kam die Hand Jehovas über die Stadt, und es entstand eine sehr große Bestürzung; und er schlug die Leute der Stadt, vom Kleinen bis zum Großen, daß Beulen an ihnen ausbrachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Da sandten sie die Lade Gottes nach Ekron. Und es geschah, als die Lade Gottes nach Ekron kam, da schrieen die Ekroniter und sprachen: Sie haben die Lade des Gottes Israels zu mir hergeschafft, um mich und mein Volk zu töten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Und sie sandten hin und versammelten alle Fürsten der Philister und sprachen: Sendet die Lade des Gottes Israels fort, daß sie an ihren Ort zurückkehre und mich und mein Volk nicht töte. Denn es war eine tödliche Bestürzung in der ganzen Stadt; die Hand Gottes war sehr schwer daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Und die Leute, die nicht starben, wurden mit Beulen geschlagen; und das Geschrei; der Stadt stieg zum Himmel empor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Und die Lade Jehovas war im Gefilde der Philister sieben Monate.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Und die Philister riefen die Priester und Wahrsager und sprachen: Was sollen wir mit der Lade Jehovas tun? Tut uns kund, auf welche Weise wir sie an ihren Ort senden sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Und sie sprachen: Wenn ihr die Lade des Gottes Israels fortsendet, so sollt ihr sie nicht leer fortsenden, denn ihr müßt ihm jedenfalls ein Schuldopfer erstatten; alsdann werdet ihr genesen, und es wird euch kundwerden, warum seine Hand nicht von euch weicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Und sie sprachen: Welches ist das Schuldopfer, das wir ihm erstatten sollen? Und sie sprachen: Nach der Zahl der Fürsten der Philister, fünf goldene Beulen und fünf goldene Mäuse; denn einerlei Plage habt ihr alle und eure Fürsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Und machet Bilder von euren Beulen und Bilder von euren Mäusen, die das Land verderben, und gebet dem Gott Israels Ehre; vielleicht läßt er seine Hand leichter werden über euch und über eurem Gott und über eurem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Und warum wolltet ihr euer Herz verstocken, wie die Ägypter und der Pharao ihr Herz verstockt haben? Ließen sie sie nicht ziehen, als er seine Macht an ihnen geübt hatte, und sie zogen weg?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Und nun machet einen neuen Wagen und nehmet zwei säugende Kühe, auf die kein Joch gekommen ist; und spannet die Kühe an den Wagen und bringet ihre Kälber hinter ihnen weg nach Hause zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Und nehmet die Lade Jehovas und stellet sie auf den Wagen; und die goldenen Geräte, die ihr ihm als Schuldopfer erstattet habt, tut in ein Kästlein an ihre Seite, und sendet sie, daß sie wegziehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Und sehet zu: Wenn sie den Weg nach ihrer Grenze hinaufgeht, nach Beth-Semes hin, so hat er uns dieses große Übel getan; wenn aber nicht, so wissen wir, daß nicht seine Hand uns geschlagen hat: ein Zufall ist es uns gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Und die Männer taten also und nahmen zwei säugende Kühe und spannten sie an den Wagen, und ihre Kälber sperrten sie zu Hause ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Und sie stellten die Lade Jehovas auf den Wagen, und das Kästlein mit den goldenen Mäusen und den Bildern ihrer Beulen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Und die Kühe gingen geradeaus auf dem Wege nach Beth-Semes; auf einer Straße gingen sie, im Gehen brüllend, und wichen nicht zur Rechten noch zur Linken; und die Fürsten der Philister gingen hinter ihnen her, bis an die Grenze von Beth-Semes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Und die von Beth-Semes ernteten die Weizenernte in der Niederung; und als sie ihre Augen erhoben und die Lade sahen, da freuten sie sich, sie zu sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Und der Wagen kam auf das Feld Josuas, des Beth-Semiters, und stand daselbst still; und es war ein großer Stein daselbst. Und sie spalteten das Holz des Wagens und opferten die Kühe als Brandopfer dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Und die Leviten nahmen die Lade Jehovas herab und das Kästlein, das bei ihr war, in welchem die goldenen Geräte waren, und setzten sie auf den großen Stein. Und die Männer von Beth-Semes opferten Brandopfer und schlachteten Schlachtopfer an jenem Tage dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Und die fünf Fürsten der Philister sahen zu und kehrten an jenem Tage nach Ekron zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Und dies sind die goldenen Beulen, welche die Philister Jehova als Schuldopfer erstatteten: Für Asdod eine, für Gasa eine, für Askalon eine, für Gath eine, für Ekron eine;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'und die goldenen Mäuse nach der Zahl aller Städte der Philister, nach den fünf Fürsten, von den festen Städten bis zu den offenen Dörfern; und sie brachten sie bis zu dem großen Stein Abel, auf welchen sie die Lade Jehovas niedersetzten, der bis auf diesen Tag im Felde Josuas, des Beth-Semiters, ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Und er schlug unter den Leuten von Beth-Semes, weil sie in die Lade Jehovas geschaut hatten, und schlug unter dem Volke siebzig Mann; da trauerte das Volk, weil Jehova eine so große Niederlage unter dem Volke angerichtet hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'und die Leute von Beth-Semes sprachen: Wer vermag vor Jehova, diesem heiligen Gott, zu bestehen? Und zu wem soll er von uns hinaufziehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Und sie sandten Boten zu den Bewohnern von Kirjath-Jearim und sprachen: Die Philister haben die Lade Jehovas zurückgebracht; kommet herab, führet sie zu euch hinauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Und die Männer von Kirjath-Jearim kamen und führten die Lade Jehovas hinauf, und sie brachten sie in das Haus Abinadabs auf dem Hügel; und sie heiligten Eleasar, seinen Sohn, die Lade Jehovas zu hüten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Und es geschah von dem Tage an, da die Lade zu Kirjath-Jearim blieb, daß der Tage viele wurden, und es wurden zwanzig Jahre. Und das ganze Haus Israel wehklagte Jehova nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Da sprach Samuel zu dem ganzen Hause Israel und sagte: Wenn ihr mit eurem ganzen Herzen zu Jehova umkehret, so tut die fremden Götter und die Astaroth aus eurer Mitte hinweg, und richtet euer Herz auf Jehova und dienet ihm allein; und er wird euch aus der Hand der Philister erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Und die Kinder Israel taten die Baalim und die Astaroth hinweg und dienten Jehova allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Und Samuel sprach: Versammelt ganz Israel nach Mizpa, und ich will Jehova für euch bitten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Und sie versammelten sich nach Mizpa und schöpften Wasser und gossen es aus vor Jehova; und sie fasteten an selbigem Tage und sprachen daselbst: Wir haben gegen Jehova gesündigt! Und Samuel richtete die Kinder Israel zu Mizpa. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Und die Philister hörten, daß die Kinder Israel sich nach Mizpa versammelt hatten, und die Fürsten der Philister zogen wider Israel herauf. Und die Kinder Israel hörten es und fürchteten sich vor den Philistern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'und die Kinder Israel sprachen zu Samuel: Laß nicht ab, für uns zu Jehova, unserem Gott, zu schreien, daß er uns von der Hand der Philister rette!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Und Samuel nahm ein Milchlamm und opferte es ganz als Brandopfer dem Jehova; und Samuel schrie zu Jehova für Israel, und Jehova erhörte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Es geschah nämlich, während Samuel das Brandopfer opferte, da rückten die Philister heran zum Streit wider Israel. Und Jehova donnerte mit starkem Donner an selbigem Tage über den Philistern und verwirrte sie, und sie wurden vor Israel geschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Und die Männer von Israel zogen von Mizpa aus und verfolgten die Philister und schlugen sie bis unterhalb Beth-Kar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Und Samuel nahm einen Stein und stellte ihn auf zwischen Mizpa und Schen, und er gab ihm den Namen Eben-Eser und sprach: Bis hierher hat uns Jehova geholfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'So wurden die Philister gedemütigt, und sie kamen fortan nicht mehr in die Grenzen Israels; und die Hand Jehovas war wider die Philister alle Tage Samuels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Und die Städte, welche die Philister von Israel genommen hatten, kamen wieder an Israel, von Ekron bis Gath; auch ihr Gebiet errettete Israel aus der Hand der Philister. Und es ward Friede zwischen Israel und den Amoritern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Und Samuel richtete Israel alle Tage seines Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Und er ging Jahr für Jahr und zog umher nach Bethel und Gilgal und Mizpa und richtete Israel an allen diesen Orten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'und er kehrte nach Rama zurück, denn dort war sein Haus, und dort richtete er Israel. Und er baute daselbst Jehova einen Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Und es geschah, als Samuel alt geworden war, da setzte er seine Söhne als Richter ein über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Und der Name seines erstgeborenen Sohnes war Joel, und der Name seines zweiten Abija; sie richteten zu Beerseba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Aber seine Söhne wandelten nicht in seinen Wegen; und sie neigten sich dem Gewinne nach und nahmen Geschenke und beugten das Recht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Da versammelten sich alle Ältesten von Israel und kamen zu Samuel nach Rama;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'und sie sprachen zu ihm: Siehe, du bist alt geworden, und deine Söhne wandeln nicht in deinen Wegen. Nun setze einen König über uns ein, daß er uns richte, gleich allen Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Und das Wort war übel in den Augen Samuels, als sie sprachen: Gib uns einen König, daß er uns richte! Und Samuel betete zu Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Und Jehova sprach zu Samuel: Höre auf die Stimme des Volkes in allem, was sie dir sagen; denn nicht dich haben sie verworfen, sondern mich haben sie verworfen, daß ich nicht König über sie sein soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Nach allen den Taten, die sie getan von dem Tage an, da ich sie aus Ägypten heraufgeführt habe, bis auf diesen Tag, indem sie mich verlassen und anderen Göttern gedient haben, also tun sie auch dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Und nun höre auf ihre Stimme; nur zeuge ernstlich wider sie und tue ihnen die Weise des Königs kund, der über sie herrschen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Und Samuel sprach alle Worte Jehovas zu dem Volke, das einen König von ihm begehrte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Und er sprach: Dies wird die Weise des Königs sein, der über euch regieren wird: Eure Söhne wird er nehmen und für sich bestellen auf seinen Wagen und unter seine Reiter, und daß sie vor seinem Wagen herlaufen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'und er wird sie nehmen, um sich Oberste über tausend und Oberste über fünfzig zu machen, und daß sie seine Äcker pflügen und seine Ernte einbringen, und daß sie sein Kriegsgerät und sein Wagengerät machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Und eure Töchter wird er nehmen zu Salbenmischerinnen und zu Köchinnen und zu Bäckerinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Und eure Felder und eure Weinberge und eure Olivengärten, die besten, wird er nehmen und sie seinen Knechten geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Und von euren Saaten und euren Weinbergen wird er den Zehnten nehmen und ihn seinen Kämmerern und seinen Knechten geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Und eure Knechte und eure Mägde und eure schönsten Jünglinge und eure Esel wird er nehmen und sie zu seinen Geschäften verwenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Euer Kleinvieh wird er zehnten, und ihr, ihr werdet ihm zu Knechten sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Und ihr werdet an jenem Tage schreien wegen eures Königs, den ihr euch erwählt habt; aber Jehova wird euch an jenem Tage nicht erhören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Aber das Volk weigerte sich, auf die Stimme Samuels zu hören; und sie sprachen: Nein, sondern ein König soll über uns sein,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'damit auch wir seien wie alle Nationen, und daß unser König uns richte und vor uns her ausziehe und unsere Kriege führe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Und Samuel hörte alle die Reden des Volkes und redete sie vor den Ohren Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Und Jehova sprach zu Samuel: Höre auf ihre Stimme und setze einen König über sie ein. Da sprach Samuel zu den Männern von Israel: Gehet hin, ein jeder in seine Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Und es war ein Mann von Benjamin, sein Name war Kis, der Sohn Abiels, des Sohnes Zerors, des Sohnes Bekoraths, des Sohnes Aphiachs, des Sohnes eines Benjaminiters, ein vermögender Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Und er hatte einen Sohn, sein Name war Saul, jung und schön, und kein Mann von den Kindern Israel war schöner als er; von seiner Schulter an aufwärts war er höher als alles Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Und die Eselinnen Kis\', des Vaters Sauls, hatten sich verirrt; und Kis sprach zu seinem Sohne Saul: Nimm doch einen von den Knaben mit dir und mache dich auf, gehe hin, suche die Eselinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Und er durchzog das Gebirge Ephraim und durchzog das Land Schalischa, und sie fanden sie nicht; und sie durchzogen das Land Schaalim, aber sie waren nicht da; und er durchzog das Land Benjamin, und sie fanden sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Sie waren in das Land Zuph gekommen, da sprach Saul zu seinem Knaben, der bei ihm war: Komm und laß uns umkehren, daß nicht etwa mein Vater von den Eselinnen abstehe und um uns bekümmert sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Und er sprach zu ihm: Siehe doch, ein Mann Gottes ist in dieser Stadt, und der Mann ist geehrt; alles was er redet, trifft sicher ein; laß uns nun dahin gehen, vielleicht gibt er uns Auskunft über unseren Weg, auf dem wir gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Und Saul sprach zu seinem Knaben: Siehe aber, wenn wir hingehen, was wollen wir dem Manne bringen? Denn das Brot ist ausgegangen in unseren Gefäßen, und wir haben kein Geschenk dem Manne Gottes zu bringen; was haben wir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Und der Knabe antwortete Saul wiederum und sprach: Siehe, es findet sich in meiner Hand ein viertel Sekel Silber; das will ich dem Manne Gottes geben, damit er uns über unseren Weg Auskunft gebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(Vordem sprach man in Israel also, wenn man ging, Gott zu befragen: Kommt und laßt uns zum Seher gehen; denn den, der heutzutage der Prophet heißt, nannte man vordem den Seher.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Da sprach Saul zu seinem Knaben: Dein Wort ist gut; komm, laß uns gehen! Und sie gingen nach der Stadt, wo der Mann Gottes war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Sie gingen eben die Anhöhe zu der Stadt hinauf, da trafen sie Mädchen, die herauskamen, um Wasser zu schöpfen; und sie sprachen zu ihnen: Ist der Seher hier?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Und sie antworteten ihnen und sprachen: Ja, siehe, er ist vor dir; eile jetzt, denn er ist heute in die Stadt gekommen, weil das Volk heute ein Schlachtopfer auf der Höhe hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Sowie ihr in die Stadt kommet, werdet ihr ihn finden, bevor er zur Höhe hinaufgeht zum Essen; denn das Volk ißt nicht, bis er gekommen ist; denn er segnet das Schlachtopfer, danach essen die Geladenen. So geht nun hinauf, denn gerade heute werdet ihr ihn finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Da gingen sie zur Stadt hinauf. Als sie in die Stadt eintraten, siehe, da kam Samuel heraus, ihnen entgegen, um zur Höhe hinaufzugehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Jehova hatte aber einen Tag, bevor Saul kam, dem Ohre Samuels eröffnet und gesagt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Morgen um diese Zeit werde ich einen Mann aus dem Lande Benjamin zu dir senden, und du sollst ihn zum Fürsten salben über mein Volk Israel; und er wird mein Volk aus der Hand der Philister retten; denn ich habe mein Volk angesehen, denn sein Geschrei ist zu mir gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Sobald nun Samuel Saul sah, antwortete ihm Jehova: Siehe da den Mann, von dem ich zu dir geredet habe; dieser soll über mein Volk herrschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Und Saul trat im Tore zu Samuel heran und sprach: Zeige mir doch an, wo das Haus des Sehers ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Und Samuel antwortete Saul und sprach: Ich bin der Seher; gehe vor mir zur Höhe hinauf, denn ihr sollt heute mit mir essen, und am Morgen werde ich dich entlassen; und alles, was in deinem Herzen ist, werde ich dir kundtun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Und was die Eselinnen betrifft, die dir heute vor drei Tagen irregegangen sind, richte nicht dein Herz auf sie, denn sie sind gefunden. Und nach wem steht alles Begehren Israels? Nicht nach dir und nach dem ganzen Hause deines Vaters?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Da antwortete Saul und sprach: Bin ich nicht ein Benjaminiter, von einem der kleinsten Stämme Israels, und ist nicht meine Familie die geringste unter allen Familien des Stammes Benjamin? Und warum redest du dergleichen Worte zu mir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Und Samuel nahm Saul und seinen Knaben und führte sie in den Saal, und er gab ihnen einen Platz obenan unter den Geladenen; und es waren ihrer bei dreißig Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Und Samuel sprach zu dem Koch: Gib das Stück her, das ich dir gegeben, von dem ich dir gesagt habe: Lege es bei dir zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Da trug der Koch die Keule auf und was daran war und legte es Saul vor. Und er sprach: Siehe, das Zurückbehaltene; lege dir vor, iß! Denn auf die bestimmte Zeit ist es für dich aufbewahrt worden, als ich sagte: Ich habe das Volk geladen. So aß Saul mit Samuel an selbigem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Und sie gingen von der Höhe in die Stadt hinab; und er redete mit Saul auf dem Dache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Und sie standen früh auf; und es geschah, als die Morgenröte aufging, da rief Samuel dem Saul auf dem Dache zu und sprach: Stehe auf, daß ich dich geleite! Und Saul stand auf, und sie gingen beide, er und Samuel, auf die Straße hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Während sie an das Ende der Stadt hinuntergingen, sprach Samuel zu Saul: Sage dem Knaben, daß er uns vorausgehe (und er ging voraus); du aber stehe jetzt still, daß ich dich das Wort Gottes hören lasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Und Samuel nahm die Ölflasche und goß sie aus auf sein Haupt, und er küßte ihn und sprach: Ist es nicht also, daß Jehova dich zum Fürsten über sein Erbteil gesalbt hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Wenn du heute von mir weggehst, so wirst du zwei Männer treffen beim Grabe Rahels, an der Grenze von Benjamin, zu Zelzach; und sie werden zu dir sagen: Die Eselinnen sind gefunden, die du zu suchen gegangen bist; und siehe, dein Vater hat die Sache der Eselinnen aufgegeben, und er ist um euch bekümmert und spricht: Was soll ich wegen meines Sohnes tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Und gehst du von dannen weiter und kommst zur Terebinthe Tabor, so werden dich daselbst drei Männer treffen, die zu Gott nach Bethel hinaufgehen; einer trägt drei Böcklein, und einer trägt drei Laibe Brot, und einer trägt einen Schlauch Wein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Und sie werden dich nach deinem Wohlergehen fragen und dir zwei Brote geben, und du sollst sie von ihrer Hand nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Danach wirst du zu dem Hügel Gottes kommen, wo Aufstellungen der Philister sind; und es wird geschehen, sowie du daselbst in die Stadt kommst, wirst du einer Schar Propheten begegnen, die von der Höhe herabkommen, und vor ihnen her Harfe und Tamburin und Flöte und Laute, und sie werden weissagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Und der Geist Gottes wird über dich geraten, und du wirst mit ihnen weissagen und wirst in einen anderen Mann verwandelt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Und es soll geschehen, wenn dir diese Zeichen eintreffen, so tue, was deine Hand finden wird; denn Gott ist mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Und gehe vor mir nach Gilgal hinab; und siehe, ich werde zu dir hinabkommen, um Brandopfer zu opfern, um Friedensopfer zu schlachten; sieben Tage sollst du warten, bis ich zu dir komme, und ich werde dir kundtun, was du tun sollst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Und es geschah, als er seinen Rücken wandte, um von Samuel wegzugehen, da verwandelte Gott sein Herz; und alle diese Zeichen trafen ein an jenem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Und als sie dorthin an den Hügel kamen, siehe, da kam ihm eine Schar Propheten entgegen; und der Geist Gottes geriet über ihn, und er weissagte in ihrer Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Und es geschah, als alle, die ihn von früher her kannten, sahen, und siehe, er weissagte mit den Propheten, da sprach das Volk einer zum anderen: Was ist denn dem Sohne Kis\' geschehen? Ist auch Saul unter den Propheten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Und ein Mann von dort antwortete und sprach: Und wer ist ihr Vater? Daher ist es zum Sprichwort geworden: Ist auch Saul unter den Propheten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Und als er aufgehört hatte zu weissagen, kam er auf die Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Und der Oheim Sauls sprach zu ihm und zu seinem Knaben: Wohin seid ihr gegangen? Und er sprach: Die Eselinnen zu suchen; und als wir sahen, daß die nirgend waren, gingen wir zu Samuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Und der Oheim Sauls sprach: Teile mir doch mit, was Samuel zu euch gesagt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Und Saul sprach zu seinem Oheim: Er tat uns für gewiß kund, daß die Eselinnen gefunden seien. Aber die Sache von dem Königtum, wovon Samuel geredet hatte, teilte er ihm nicht mit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Und Samuel berief das Volk zu Jehova nach Mizpa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Und er sprach zu den Kindern Israel: So spricht Jehova, der Gott Israels: Ich habe Israel aus Ägypten heraufgeführt und euch errettet aus der Hand der Ägypter und aus der Hand all der Königreiche, die euch bedrückten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'ihr aber habt heute euren Gott verworfen, der euch aus allen euren Übeln und euren Drangsalen gerettet hat, und habt zu ihm gesagt: Einen König sollst du über uns setzen! Nun denn, stellet euch auf vor Jehova nach euren Stämmen und nach euren Tausenden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Und Samuel ließ alle Stämme Israels herzutreten; und es wurde getroffen der Stamm Benjamin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Und er ließ den Stamm Benjamin nach seinen Geschlechtern herzutreten; und es wurde getroffen das Geschlecht Matri; und es wurde getroffen Saul, der Sohn Kis\'. Und sie suchten ihn, aber er wurde nicht gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Und sie befragten wiederum Jehova: Wird der Mann noch hierher kommen? Und Jehova sprach: Siehe, er hat sich bei dem Geräte versteckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Da liefen sie hin und holten ihn von dannen; und er stellte sich mitten unter das Volk, und er war höher als alles Volk, von seiner Schulter an aufwärts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Und Samuel sprach zu dem ganzen Volke: Habt ihr gesehen, den Jehova erwählt hat? Denn keiner ist wie er im ganzen Volke. Da jauchzte das ganze Volk, und sie sprachen: Es lebe der König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Und Samuel sagte dem Volke das Recht des Königtums, und er schrieb es in ein Buch und legte es vor Jehova nieder. Und Samuel entließ das ganze Volk, einen jeden nach seinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Und auch Saul ging nach seinem Hause, nach Gibea; und mit ihm zog die Schar, deren Herz Gott gerührt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Aber etliche Söhne Belials sprachen: Wie sollte der uns retten? Und sie verachteten ihn und brachten ihm kein Geschenk; aber er war wie taub.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Und Nahas, der Ammoniter, zog herauf und belagerte Jabes-Gilead. Und alle Männer von Jabes sprachen zu Nahas: Mache einen Bund mit uns, so wollen wir dir dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Aber Nahas, der Ammoniter, sprach zu ihnen: Unter dieser Bedingung will ich einen Bund mit euch machen, daß ich euch allen das rechte Auge aussteche und damit eine Schmach auf ganz Israel lege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Und die Ältesten von Jabes sprachen zu ihm: Laß uns sieben Tage, und wir wollen Boten in alle Grenzen Israels senden; und wenn niemand ist, der uns rettet, so wollen wir zu dir hinausgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Und die Boten kamen nach Gibea-Saul und redeten diese Worte zu den Ohren des Volkes. Und das ganze Volk erhob seine Stimme und weinte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Und siehe, Saul kam hinter den Rindern her vom Felde, und Saul sprach: Was ist dem Volke, daß sie weinen? Und sie erzählten ihm die Worte der Männer von Jabes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Da geriet der Geist Gottes über Saul, als er diese Worte hörte, und sein Zorn entbrannte sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Und er nahm ein Joch Rinder und zerstückte sie, und er sandte die Stücke durch Boten in alle Grenzen Israels und ließ sagen: Wer nicht auszieht hinter Saul und hinter Samuel her, dessen Rindern wird also getan werden! Da fiel der Schrecken Jehovas auf das Volk, und sie zogen aus wie ein Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Und er musterte sie zu Besek; und es waren der Kinder Israel dreihunderttausend, und der Männer von Juda dreißigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Und sie sprachen zu den Boten, die gekommen waren: So sollt ihr zu den Männern von Jabes-Gilead sagen: Morgen, wenn die Sonne heiß wird, wird euch Rettung werden. Und die Boten kamen und berichteten es den Männern von Jabes, und sie freuten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Und die Männer von Jabes sprachen: Morgen werden wir zu euch hinausgehen, und ihr möget uns tun nach allem, was gut ist in euren Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Und es geschah am anderen Tage, da stellte Saul das Volk in drei Haufen; und sie kamen mitten in das Lager bei der Morgenwache und schlugen Ammon bis zum Heißwerden des Tages; und die Übriggebliebenen wurden zerstreut, und es blieben unter ihnen nicht zwei beisammen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Da sprach das Volk zu Samuel: Wer ist es, der gesagt hat: Sollte Saul über uns regieren? Gebet die Männer her, daß wir sie töten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Aber Saul sprach: Niemand soll an diesem Tage getötet werden, denn heute hat Jehova Rettung geschafft in Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Und Samuel sprach zu dem Volke: Kommt laßt uns nach Gilgal gehen und daselbst das Königtum erneuern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Und das ganze Volk zog nach Gilgal, und sie machten daselbst Saul zum König vor Jehova, zu Gilgal; und sie schlachteten daselbst Friedensopfer vor Jehova. Und Saul und alle Männer von Israel freuten sich daselbst gar sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Und Samuel sprach zu dem ganzen Israel: Siehe, ich habe auf eure Stimme gehört in allem, was ihr zu mir gesagt habt, und habe einen König über euch gesetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Und nun siehe, der König zieht vor euch her; ich aber bin alt und grau geworden, und meine Söhne, siehe, sie sind bei euch; und ich habe vor euch gewandelt von meiner Jugend an bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Hier bin ich, zeuget wider mich vor Jehova und vor seinem Gesalbten! Wessen Rind habe ich genommen? Oder wessen Esel habe ich genommen? Oder wen habe ich übervorteilt? Wem habe ich Gewalt angetan? Oder aus wessen Hand habe ich Lösegeld genommen, daß ich dadurch meine Augen verhüllt hätte? So will ich es euch wiedergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Und sie sprachen: Du hast uns nicht übervorteilt und uns keine Gewalt angetan, und hast aus niemandes Hand irgend etwas genommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Und er sprach zu ihnen: Jehova ist Zeuge wider euch, und Zeuge sein Gesalbter an diesem Tage, daß ihr gar nichts in meiner Hand gefunden habt! Und sie sprachen: Er ist Zeuge!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Und Samuel sprach zu dem Volke: Jehova ist es, der Mose und Aaron bestellt, und der eure Väter heraufgeführt hat aus dem Lande Ägypten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Und nun tretet her, daß ich vor Jehova mit euch rechte über alle gerechten Taten Jehovas, die er an euch und an euren Vätern getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Als Jakob nach Ägypten gekommen war, da schrieen eure Väter zu Jehova; und Jehova sandte Mose und Aaron, und sie führten eure Väter aus Ägypten hinweg und ließen sie wohnen an diesem Orte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Aber sie vergaßen Jehova, ihren Gott; und er verkaufte sie in die Hand Siseras, des Heerobersten von Hazor, und in die Hand der Philister und in die Hand des Königs von Moab, und sie stritten wider sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Da schrieen sie zu Jehova und sprachen: Wir haben gesündigt, daß wir Jehova verlassen und den Baalim und den Astaroth gedient haben; und nun errette uns aus der Hand unserer Feinde, so wollen wir dir dienen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Und Jehova sandte Jerub-Baal und Bedan und Jephtha und Samuel, und er errettete euch aus der Hand eurer Feinde ringsum; und ihr wohntet in Sicherheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Als ihr aber sahet, daß Nahas, der König der Kinder Ammon, wider euch kam, sprachet ihr zu mir: Nein, sondern ein König soll über uns regieren! da doch Jehova, euer Gott, euer König war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Und nun siehe, da ist der König, den ihr erwählt, den ihr begehrt habt; und siehe, Jehova hat einen König über euch gesetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Wenn ihr nur Jehova fürchtet und ihm dienet und auf seine Stimme höret und gegen den Befehl Jehovas nicht widerspenstig seid, und sowohl ihr als auch der König, der über euch regiert, Jehova, eurem Gott, nachfolget!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Wenn ihr aber nicht auf die Stimme Jehovas höret und gegen den Befehl Jehovas widerspenstig seid, so wird die Hand Jehovas wider euch sein, wie wider eure Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Auch jetzt tretet her und sehet diese große Sache, die Jehova vor euren Augen tun wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Ist nicht jetzt die Weizenernte? Ich will zu Jehova rufen, und er wird Donner und Regen geben; und ihr sollt erkennen und sehen, daß das Böse, das ihr getan habt, groß ist in den Augen Jehovas, einen König für euch zu begehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Und Samuel rief zu Jehova, und Jehova gab Donner und Regen an jenem Tage. Da fürchtete sich das ganze Volk sehr vor Jehova und vor Samuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Und das ganze Volk sprach zu Samuel: Bitte Jehova, deinen Gott, für deine Knechte, daß wir nicht sterben! Denn zu allen unseren Sünden haben wir das Böse hinzugefügt, einen König für uns zu begehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Und Samuel sprach zu dem Volke: Fürchtet euch nicht! Ihr habt zwar all dieses Böse getan; nur weichet nicht ab von der Nachfolge Jehovas und dienet Jehova mit eurem ganzen Herzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'und weichet nicht ab, denn ihr würdet den Nichtigen nachgehen, die nichts nützen und nicht erretten, denn sie sind nichtig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Denn Jehova wird um seines großen Namens willen sein Volk nicht verlassen; denn es hat Jehova gefallen, euch sich zum Volke zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Auch ich fern sei es von mir, daß ich gegen Jehova sündigen, daß ich ablassen sollte, für euch zu bitten; sondern ich werde euch den guten und richtigen Weg lehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Nur fürchtet Jehova, und dienet ihm in Wahrheit mit eurem ganzen Herzen; denn sehet, welch große Dinge er an euch getan hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Wenn ihr aber dennoch übeltut, so werdet sowohl ihr als auch euer König weggerafft werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul war... Jahre alt, als er König wurde; und er regierte zwei Jahre über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Und Saul wählte sich dreitausend aus Israel; zweitausend waren bei Saul zu Mikmas und auf dem Gebirge von Bethel, und tausend waren bei Jonathan zu Gibea-Benjamin. Das übrige Volk aber entließ er, einen jeden nach seinen Zelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Und Jonathan schlug die Aufstellung der Philister, die zu Geba war, und die Philister hörten es. Und Saul ließ im ganzen Lande in die Posaune stoßen und sprach: Die Hebräer sollen es hören!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Und als ganz Israel sagen hörte: Saul hat die Aufstellung der Philister geschlagen, und auch hat sich Israel bei den Philistern stinkend gemacht, da versammelte sich das Volk hinter Saul her nach Gilgal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Und die Philister sammelten sich zum Streit mit Israel: dreißigtausend Wagen und sechstausend Reiter, und Fußvolk, wie der Sand, der am Ufer des Meeres ist, an Menge; und sie zogen herauf und lagerten sich zu Mikmas, östlich von Beth-Awen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Und die Männer von Israel sahen, daß sie in Drangsal waren, denn das Volk war bedrängt; und das Volk versteckte sich in den Höhlen und in den Dorngebüschen und in den Felsen und in den Burgen und in den Gruben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Und Hebräer gingen über den Jordan in das Land Gad und Gilead. Saul aber war noch zu Gilgal, und das ganze Volk zitterte hinter ihm her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Und er wartete sieben Tage, bis zu der von Samuel bestimmten Zeit; aber Samuel kam nicht nach Gilgal. Und das Volk zerstreute sich von ihm weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Da sprach Saul: Bringet mir das Brandopfer und die Friedensopfer her! Und er opferte das Brandopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Und es geschah, als er das Opfern des Brandopfers vollendet hatte, siehe, da kam Samuel; und Saul ging hinaus, ihm entgegen, ihn zu begrüßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Und Samuel sprach: Was hast du getan! Und Saul sprach: Weil ich sah, daß das Volk sich von mir weg zerstreute, und du nicht kamst zur bestimmten Zeit, und die Philister zu Mikmas versammelt waren, so sprach ich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Jetzt werden die Philister zu mir nach Gilgal herabkommen, und ich habe Jehova nicht angefleht! Und ich überwand mich und opferte das Brandopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Und Samuel sprach zu Saul: Du hast töricht gehandelt, du hast nicht beobachtet das Gebot Jehovas, deines Gottes, das er dir geboten hat; denn jetzt hätte Jehova dein Königtum über Israel bestätigt auf ewig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'nun aber wird dein Königtum nicht bestehen. Jehova hat sich einen Mann gesucht nach seinem Herzen, und Jehova hat ihn zum Fürsten über sein Volk bestellt; denn du hast nicht beobachtet, was Jehova dir geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Und Samuel machte sich auf und ging von Gilgal hinauf nach Gibea-Benjamin. Und Saul musterte das Volk, das sich bei ihm befand, bei sechshundert Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Und Saul und Jonathan, sein Sohn, und das Volk, das sich bei ihm befand, lagen zu Geba-Benjamin; die Philister aber hatten sich zu Mikmas gelagert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Und der Verheerungszug ging aus von dem Lager der Philister in drei Haufen: Ein Haufe wandte sich des Weges nach Ophra, nach dem Lande Schual hin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'und ein Haufe wandte sich auf den Weg nach Beth-Horon, und ein Haufe wandte sich des Weges nach der Grenze, die emporragt über das Tal Zeboim nach der Wüste hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Und es war kein Schmied zu finden im ganzen Lande Israel; denn die Philister hatten gesagt: Daß die Hebräer sich nicht Schwert oder Speer machen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Und ganz Israel ging zu den Philistern hinab, ein jeder, um seine Pflugschar und seinen Spaten und sein Beil und seine Sichel zu schärfen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'wenn die Schneiden an den Sicheln und an den Spaten und an den Gabeln und an den Beilen abgestumpft waren, und um den Rinderstachel zu richten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Und es geschah am Tage des Streites, da wurde kein Schwert noch Speer gefunden in der Hand des ganzen Volkes, das mit Saul und mit Jonathan war; doch bei Saul und seinem Sohne Jonathan fanden sie sich vor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Und eine Aufstellung der Philister zog aus nach dem Passe von Mikmas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Und es geschah eines Tages, da sprach Jonathan, der Sohn Sauls, zu dem Knaben, der seine Waffen trug: Komm und laß uns hinübergehen zu der Aufstellung der Philister, die dort drüben ist. Seinem Vater aber tat er es nicht kund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Und Saul saß am Ende von Gibea, unter dem Granatbaum, der zu Migron ist; und des Volkes, das bei ihm war, war bei sechshundert Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, '(Und Ahija, der Sohn Ahitubs, des Bruders Jkabods, des Sohnes Pinehas\', des Sohnes Elis, des Priesters Jehovas zu Silo, trug das Ephod.) Und das Volk wußte nicht, daß Jonathan weggegangen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Es war aber zwischen den Pässen, durch welche Jonathan zu der Aufstellung der Philister hinüberzugehen suchte, eine Felszacke auf dieser Seite und eine Felszacke auf jener Seite: der Name der einen war Bozez, und der Name der anderen Sene;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'die eine Zacke bildet eine Säule nordwärts, Mikmas gegenüber, und die andere südwärts, Geba gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Und Jonathan sprach zu dem Knaben, der seine Waffen trug: Komm und laß uns hinübergehen zu der Aufstellung dieser Unbeschnittenen; vielleicht wird Jehova für uns wirken, denn für Jehova gibt es kein Hindernis, durch viele zu retten oder durch wenige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Und sein Waffenträger sprach zu ihm: Tue alles, was in deinem Herzen ist; wende dich, wohin du willst, siehe, ich bin mit dir nach deinem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Und Jonathan sprach: Siehe, wir gehen zu den Männern hinüber und wollen uns ihnen zeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Wenn sie so zu uns sprechen: Stehet still, bis wir zu euch gelangen! so wollen wir auf unserer Stelle stehen bleiben und nicht zu ihnen hinaufgehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'wenn sie aber so sprechen: Kommet zu uns herauf! so wollen wir hinaufgehen, denn Jehova hat sie in unsere Hand gegeben; und das soll uns das Zeichen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Und beide zeigten sich der Aufstellung der Philister. Da sprachen die Philister: Siehe, Hebräer kommen aus den Löchern hervor, worin sie sich versteckt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Und die Männer der Aufstellung antworteten Jonathan und seinem Waffenträger und sprachen: Kommet zu uns herauf, so wollen wir euch etwas zu wissen tun! Da sprach Jonathan zu seinem Waffenträger: Steige hinauf, mir nach; denn Jehova hat sie in die Hand Israels gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Und Jonathan stieg auf seinen Händen und auf seinen Füßen hinauf, und sein Waffenträger ihm nach. Und sie fielen vor Jonathan, und sein Waffenträger tötete hinter ihm her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Und die erste Niederlage, welche Jonathan und sein Waffenträger anrichteten, war bei zwanzig Mann, etwa auf der halben Furchenlänge eines Jucharts Ackers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Und ein Schrecken entstand im Lager, auf dem Felde und unter dem ganzen Volke; die Aufstellung und der Verheerungszug, auch sie erschraken; und das Land erbebte, und es wurde zu einem Schrecken Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Und die Wächter Sauls zu Gibea-Benjamin sahen, und siehe, die Menge zerrann und lief dahin und dorthin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Und Saul sprach zu dem Volke, das bei ihm war: Haltet doch Musterung und sehet, wer von uns weggegangen ist. Und sie hielten Musterung, und siehe, Jonathan und sein Waffenträger waren nicht da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Da sprach Saul zu Ahija: Bringe die Lade Gottes herbei; denn die Lade Gottes war an jenem Tage unter den Kindern Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Und es geschah, während Saul zu dem Priester redete, da nahm das Getümmel im Lager der Philister fort und fort zu; und Saul sprach zu dem Priester: Ziehe deine Hand zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Und Saul und alles Volk, das bei ihm war, versammelten sich, und sie kamen zum Streit; und siehe, da war das Schwert des einen wider den anderen, eine sehr große Verwirrung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Und es waren Hebräer bei den Philistern, wie früher, welche mit ihnen in das Lager ringsum hinaufgezogen waren; auch sie wandten sich, um mit Israel zu sein, das mit Saul und Jonathan war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Und alle Männer von Israel, die sich im Gebirge Ephraim versteckt hatten, hörten, daß die Philister geflohen waren; und auch sie setzten ihnen nach im Streit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'So rettete Jehova Israel an selbigem Tage. Und der Streit ging über Beth-Awen hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Die Männer von Israel waren aber sehr angestrengt an jenem Tage; und Saul beschwor das Volk und sprach: Verflucht sei der Mann, der Speise essen wird bis zum Abend, und bis ich mich an meinen Feinden gerächt habe! Und das ganze Volk kostete keine Speise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Und das ganze Volk kam in den Wald, und Honig war auf der Fläche des Feldes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Und als das Volk in den Wald kam: siehe da, ein Strom von Honig; aber niemand brachte seine Hand zu seinem Munde, denn das Volk fürchtete den Schwur.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Jonathan aber hatte es nicht gehört, als sein Vater das Volk beschwor; und er streckte das Ende seines Stabes aus, der in seiner Hand war, und tauchte ihn in den Honigseim und brachte seine Hand wieder zu seinem Munde, und seine Augen wurden hell.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Und einer von dem Volke hob an und sprach: Dein Vater hat das Volk feierlich beschworen und gesagt: Verflucht sei der Mann, der heute Speise essen wird! Und so ist das Volk ermattet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Und Jonathan sprach: Mein Vater hat das Land in Trübsal gebracht; sehet doch, daß meine Augen hell geworden sind, weil ich ein wenig von diesem Honig gekostet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Was wäre es gewesen, wenn das Volk heute ungehindert von der Beute seiner Feinde gegessen hätte, die es gefunden hat! Denn wäre dann nicht die Niederlage der Philister groß gewesen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Und sie schlugen die Philister an jenem Tage von Mikmas bis nach Ajjalon; und das Volk war sehr ermattet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Und das Volk fiel über die Beute her, und sie nahmen Kleinvieh und Rinder und Kälber und schlachteten sie auf die Erde hin; und das Volk aß mit dem Blute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Und man berichtete es Saul und sprach: Siehe, das Volk sündigt gegen Jehova, indem es mit dem Blute ißt. Und er sprach: Ihr habt treulos gehandelt! Wälzet sofort einen großen Stein zu mir her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Und Saul sprach: Zerstreuet euch unter das Volk und sprechet zu ihnen: Bringet her zu mir, ein jeder sein Rind und ein jeder sein Kleinvieh, und schlachtet sie hier und esset; und sündiget nicht gegen Jehova, indem ihr mit dem Blute esset. Und in jener Nacht brachte das ganze Volk ein jeder sein Rind an seiner Hand; und sie schlachteten sie daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Und Saul baute Jehova einen Altar; mit diesem fing er an, Jehova einen Altar zu bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Und Saul sprach: Laßt uns bei der Nacht hinabziehen, den Philistern nach, und unter ihnen plündern, bis der Morgen hell wird, und keinen Mann unter ihnen übriglassen! Und sie sprachen: Tue alles, was gut ist in deinen Augen. Und der Priester sprach: Laßt uns hier zu Gott nahen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Und Saul fragte Gott: Soll ich hinabziehen, den Philistern nach? Wirst du sie in die Hand Israels geben? Aber er antwortete ihm nicht an jenem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Da sprach Saul: Tretet hierher, alle Häupter des Volkes, und erkennet und sehet, wodurch diese Sünde heute geschehen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Denn so wahr Jehova lebt, der Israel gerettet hat, wenn sie an meinem Sohne Jonathan wäre, so sollte er gewißlich sterben! Und niemand antwortete ihm aus dem ganzen Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Und er sprach zu dem ganzen Israel: Seid ihr auf der einen Seite, und ich und mein Sohn Jonathan wollen auf der anderen Seite sein. Und das Volk sprach zu Saul: Tue, was gut ist in deinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Und Saul sprach zu Jehova, dem Gott Israels: Gib ein vollkommenes Los! Und Jonathan und Saul wurden getroffen, und das Volk ging frei aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Und Saul sprach: Werfet das Los zwischen mir und meinem Sohne Jonathan! Und Jonathan wurde getroffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Da sprach Saul zu Jonathan: Tue mir kund, was du getan hast. Und Jonathan tat es ihm kund und sprach: Mit dem Ende des Stabes, der in meiner Hand war, habe ich ein wenig Honig nur gekostet: Siehe, ich muß sterben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Und Saul sprach: So tue mir Gott, und so füge er hinzu, du mußt gewißlich sterben, Jonathan!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Aber das Volk sprach zu Saul: Sollte Jonathan sterben, der diese große Rettung in Israel geschafft hat? Das sei ferne! So wahr Jehova lebt, wenn von den Haaren seines Hauptes eines auf die Erde fällt! Denn er hat mit Gott gehandelt an diesem Tage. So erlöste das Volk Jonathan, daß er nicht starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Und Saul zog von der Verfolgung der Philister herauf, und die Philister zogen an ihren Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Und Saul nahm das Königtum ein über Israel; und er stritt ringsum wider alle seine Feinde, wider Moab und wider die Kinder Ammon und wider Edom und wider die Könige von Zoba und wider die Philister; und überall, wohin er sich wandte, übte er Strafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Und er tat Mächtiges und schlug Amalek, und errettete Israel aus der Hand seines Plünderers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Und die Söhne Sauls waren: Jonathan und Jischwi und Malkischua. Und die Namen seiner zwei Töchter: der Name der erstgeborenen war Merab, und der Name der jüngeren Michal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Und der Name des Weibes Sauls war Achinoam, die Tochter Achimaaz\'. Und der Name seines Heerobersten war Abner, der Sohn Ners, des Oheims Sauls;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'denn Kis, der Vater Sauls, und Ner, der Vater Abners, waren Söhne Abiels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Und der Streit war heftig wider die Philister alle Tage Sauls; und wenn Saul irgend einen streitbaren Mann und irgend einen Tapferen sah, so gesellte er ihn sich zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Und Samuel sprach zu Saul: Jehova hat mich gesandt, um dich zum König zu salben über sein Volk, über Israel. So höre nun auf die Stimme der Worte Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'So spricht Jehova der Heerscharen: Ich habe angesehen, was Amalek Israel getan, wie er sich ihm in den Weg gestellt hat, als es aus Ägypten heraufzog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Nun ziehe hin und schlage Amalek, und verbannet alles, was er hat, und schone seiner nicht; und töte vom Manne bis zum Weibe, vom Kinde bis zum Säugling, vom Rinde bis zum Kleinvieh, vom Kamel bis zum Esel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Da rief Saul das Volk auf und musterte sie zu Telaim, zweihunderttausend Mann zu Fuß und zehntausend Männer von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Und Saul kam bis zu der Stadt der Amalekiter, und er legte einen Hinterhalt in das Tal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Und Saul sprach zu den Kenitern: Gehet, weichet, ziehet hinab aus der Mitte der Amalekiter, daß ich dich nicht mit ihnen wegraffe! Denn du, du hast Güte erwiesen an allen Kindern Israel, als sie aus Ägypten heraufzogen. Und die Keniter wichen aus der Mitte der Amalekiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Und Saul schlug die Amalekiter von Hawila an bis nach Sur hin, das vor Ägypten liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Und er ergriff Agag, den König der Amalekiter, lebendig; und das ganze Volk verbannte er mit der Schärfe des Schwertes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Und Saul und das Volk verschonten Agag und das Beste vom Klein-und Rindvieh und die Tiere vom zweiten Wurf und die Mastschafe und alles, was gut war, und sie wollten sie nicht verbannen; alles Vieh aber, das gering und schwächlich war, das verbannten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Da geschah das Wort Jehovas zu Samuel also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Es reut mich, daß ich Saul zum König gemacht habe; denn er hat sich hinter mir abgewandt und hat meine Worte nicht erfüllt. Und Samuel entbrannte und schrie zu Jehova die ganze Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Und am Morgen machte Samuel sich früh auf, Saul entgegen. Und es wurde Samuel berichtet und gesagt: Saul ist nach Karmel gekommen; und siehe, er hat sich ein Denkmal errichtet, und er hat sich gewandt und ist weiter gegangen und nach Gilgal hinabgezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Und Samuel kam zu Saul; und Saul sprach zu ihm: Gesegnet seiest du von Jehova! Ich habe das Wort Jehovas erfüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Und Samuel sprach: Was ist denn das für ein Blöken von Kleinvieh in meinen Ohren, und ein Brüllen von Rindern, das ich höre?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Und Saul sprach: Sie haben sie von den Amalekitern gebracht, weil das Volk das Beste vom Klein-und Rindvieh verschont hat, um Jehova, deinem Gott, zu opfern; aber das Übrige haben wir verbannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Da sprach Samuel zu Saul: Halt, daß ich dir kundtue, was Jehova diese Nacht zu mir geredet hat. Und er sprach zu ihm: Rede!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Und Samuel sprach: Wurdest du nicht, als du klein in deinen Augen warst, das Haupt der Stämme Israels? Und Jehova salbte dich zum König über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Und Jehova hat dich auf den Weg gesandt und gesagt: Ziehe hin und verbanne die Sünder, die Amalekiter, und streite wider sie, bis du sie vernichtest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Warum hast du denn der Stimme Jehovas nicht gehorcht, und bist über die Beute hergefallen und hast getan, was böse ist in den Augen Jehovas?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Und Saul sprach zu Samuel: Ich habe der Stimme Jehovas gehorcht und bin auf dem Wege gezogen, den Jehova mich gesandt hat; und ich habe Agag, den König der Amalekiter, hergebracht, und die Amalekiter habe ich verbannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Aber das Volk hat von der Beute genommen: Klein-und Rindvieh, das Vorzüglichste des Verbannten, um Jehova, deinem Gott, zu opfern in Gilgal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Und Samuel sprach zu Saul: Hat Jehova Lust an Brandopfern und Schlachtopfern, wie daran, daß man der Stimme Jehovas gehorcht? Siehe, Gehorchen ist besser als Schlachtopfer, Aufmerken besser als das Fett der Widder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Denn wie Sünde der Wahrsagerei ist Widerspenstigkeit, und der Eigenwille wie Abgötterei und Götzendienst. Weil du das Wort Jehovas verworfen hast, so hat er dich verworfen, daß du nicht mehr König seiest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Und Saul sprach zu Samuel: Ich habe gesündigt, daß ich den Befehl Jehovas und deine Worte übertreten habe; denn ich habe das Volk gefürchtet und auf seine Stimme gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Und nun, vergib doch meine Sünde, und kehre mit mir um, daß ich vor Jehova anbete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Aber Samuel sprach zu Saul: Ich kehre nicht mit dir um; denn du hast das Wort Jehovas verworfen, und Jehova hat dich verworfen, daß du nicht mehr König über Israel seiest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Und als Samuel sich wandte zu gehen, da ergriff er den Zipfel seines Oberkleides, und derselbe riß ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Da sprach Samuel zu ihm: Jehova hat heute das Königtum Israels von dir abgerissen und es deinem Nächsten gegeben, der besser ist als du.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Und auch lügt nicht das Vertrauen Israels, und er bereut nicht; denn nicht ein Mensch ist er, um zu bereuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Und er sprach: Ich habe gesündigt! Nun ehre mich doch vor den Ältesten meines Volkes und vor Israel, und kehre mit mir um, daß ich vor Jehova, deinem Gott, anbete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Und Samuel kehrte um, Saul nach, und Saul betete an vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Und Samuel sprach: Bringet Agag, den König der Amalekiter, zu mir her. Und Agag kam lustig zu ihm; und Agag sprach: Fürwahr, die Bitterkeit des Todes ist gewichen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Aber Samuel sprach: Wie dein Schwert Weiber kinderlos gemacht hat, so sei kinderlos unter Weibern deine Mutter! Und Samuel hieb Agag in Stücke vor Jehova zu Gilgal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Und Samuel ging nach Rama; und Saul zog in sein Haus hinauf nach Gibea-Saul.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Und Samuel sah Saul nicht mehr bis zum Tage seines Todes; denn Samuel trauerte um Saul, da es Jehova reute, daß er Saul zum König über Israel gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Und Jehova sprach zu Samuel: Bis wann willst du um Saul trauern, da ich ihn doch verworfen habe, daß er nicht mehr König über Israel sei? Fülle dein Horn mit Öl und gehe hin, ich will dich zu Isai, dem Bethlehemiter, senden; denn ich habe mir unter seinen Söhnen einen König ersehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Und Samuel sprach: Wie mag ich hingehen? Wenn Saul es hört, so tötet er mich. Und Jehova sprach: Nimm eine Färse mit dir und sprich: Ich bin gekommen, um Jehova zu opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Und lade Isai zum Schlachtopfer, und ich werde dir kundtun, was du tun sollst; und du sollst mir salben, den ich dir sagen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Und Samuel tat, was Jehova geredet hatte, und kam nach Bethlehem. Da kamen die Ältesten der Stadt ihm ängstlich entgegen und sprachen: Bedeutet dein Kommen Friede?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Und er sprach: Friede! Ich bin gekommen, um Jehova zu opfern. Heiliget euch und kommet mit mir zum Schlachtopfer. Und er heiligte Isai und seine Söhne und lud sie zum Schlachtopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Und es geschah, als sie kamen, da sah er Eliab und sprach: Gewiß, vor Jehova ist sein Gesalbter!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Aber Jehova sprach zu Samuel: Blicke nicht auf sein Aussehen und auf die Höhe seines Wuchses, denn ich habe ihn verworfen; denn Jehova sieht nicht auf das, worauf der Mensch sieht; denn der Mensch sieht auf das Äußere, aber Jehova sieht auf das Herz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Da rief Isai Abinadab und ließ ihn vor Samuel vorübergehen. Und er sprach: Auch diesen hat Jehova nicht erwählt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Da ließ Isai Schamma vorübergehen. Und er sprach: Auch diesen hat Jehova nicht erwählt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Und Isai ließ sieben seiner Söhne vor Samuel vorübergehen; aber Samuel sprach zu Isai: Jehova hat diese nicht erwählt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Und Samuel sprach zu Isai: Sind das die Jünglinge alle? Und er sprach: Noch ist der Jüngste übrig, und siehe, er weidet das Kleinvieh. Und Samuel sprach zu Isai: Sende hin und laß ihn holen; denn wir werden uns nicht zu Tische setzen, bis er hierhergekommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Und er sandte hin und ließ ihn kommen; und er war rötlich, dazu schön von Augen und von gutem Ansehen. Und Jehova sprach: Auf, salbe ihn! Denn dieser ist es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Da nahm Samuel das Ölhorn und salbte ihn inmitten seiner Brüder. Und der Geist Jehovas geriet über David von selbigem Tage an und hinfort. Und Samuel machte sich auf und ging nach Rama.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Aber der Geist Jehovas wich von Saul, und ein böser Geist von Jehova ängstigte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Und die Knechte Sauls sprachen zu ihm: Siehe doch, ein böser Geist von Gott ängstigt dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Es befehle doch unser Herr deinen Knechten, die vor dir sind, daß sie einen Mann suchen, der des Lautenspieles kundig ist; und es wird geschehen, wenn der böse Geist von Gott über dich kommt, so wird er mit seiner Hand spielen, und es wird dir wohl werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Und Saul sprach zu seinen Knechten: Ersehet mir doch einen Mann, der gut spielen kann, und bringet ihn zu mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Und einer von den Knaben antwortete und sprach: Siehe, ich habe einen Sohn Isais, des Bethlehemiters, gesehen, der des Spielens kundig ist, und er ist ein tapferer Held und ein Kriegsmann und der Rede verständig und ein schöner Mann, und Jehova ist mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Da sandte Saul Boten zu Isai und ließ ihm sagen: Sende deinen Sohn David zu mir, der bei dem Kleinvieh ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Und Isai nahm einen Esel mit Brot und einen Schlauch Wein und ein Ziegenböcklein, und er sandte es durch seinen Sohn David an Saul.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Und David kam zu Saul und stand vor ihm; und er liebte ihn sehr, und er wurde sein Waffenträger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Und Saul sandte zu Isai und ließ ihm sagen: Laß doch David vor mir stehen, denn er hat Gnade gefunden in meinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Und es geschah, wenn der Geist von Gott über Saul kam, so nahm David die Laute und spielte mit seiner Hand; und Saul fand Erleichterung, und es wurde ihm wohl, und der böse Geist wich von ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Und die Philister sammelten ihre Heere zum Streit und versammelten sich zu Soko, das Juda gehört, und lagerten sich bei Ephes-Dammim, zwischen Soko und Aseka.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Und Saul und die Männer von Israel versammelten und lagerten sich im Terebinthentale, und sie stellten sich in Schlachtordnung auf, den Philistern gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Und die Philister standen am Berge jenseits, und Israel stand am Berge diesseits, und das Tal war zwischen ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Und der Zwischenkämpfer trat aus den Lagern der Philister hervor, sein Name war Goliath, aus Gath; seine Höhe war sechs Ellen und eine Spanne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Und er hatte einen ehernen Helm auf seinem Haupte, und er war mit einem Schuppenpanzer bekleidet, und das Gewicht des Panzers war fünftausend Sekel Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Und er hatte eherne Schienen an seinen Beinen und einen ehernen Wurfspieß zwischen seinen Schultern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Und der Schaft seines Speeres war wie ein Weberbaum, und die Spitze seines Speeres war sechshundert Sekel Eisen. Und der Schildträger ging vor ihm her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Und er trat hin und rief den Schlachtreihen Israels zu und sprach zu ihnen: Warum ziehet ihr aus, euch in Schlachtordnung aufzustellen? Bin ich nicht der Philister, und ihr die Knechte Sauls? Wählet euch einen Mann, daß er zu mir herabkomme!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Wenn er mit mir zu kämpfen vermag und mich erschlägt, so wollen wir eure Knechte sein; wenn ich ihn aber überwinde und ihn erschlage, so sollt ihr unsere Knechte sein und uns dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Und der Philister sprach: Ich habe die Schlachtreihen Israels verhöhnt an diesem Tage! Gebet mir einen Mann, daß wir miteinander kämpfen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Und Saul und ganz Israel hörten diese Worte des Philisters, und sie erschraken und fürchteten sich sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'David nun war der Sohn jenes Ephratiters von Bethlehem-Juda, dessen Name Isai war und der acht Söhne hatte; und der Mann war in den Tagen Sauls alt, im Alter vorgerückt unter den Männern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Und die drei ältesten Söhne Isais waren hingegangen, sie waren Saul nachgefolgt zum Streit; und die Namen seiner drei Söhne, die in den Streit gezogen, waren: Eliab, der Erstgeborene, und sein Zweiter, Abinadab, und der Dritte, Schamma.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'Und David war der Jüngste, und die drei Ältesten waren Saul nachgefolgt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'David aber ging hin und kam wieder zurück von Saul, um das Kleinvieh seines Vaters zu weiden zu Bethlehem. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Und der Philister trat morgens und abends herzu und stellte sich hin, vierzig Tage lang. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Und Isai sprach zu seinem Sohne David: Nimm doch für deine Brüder dieses Epha geröstete Körner und diese zehn Brote, und bringe sie schnell in das Lager zu deinen Brüdern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'und diese zehn Schnitten Milchkäse bringe dem Obersten über tausend und besuche deine Brüder, um nach ihrem Wohlergehen zu fragen, und nimm ein Pfand von ihnen mit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Saul und sie und alle Männer von Israel sind nämlich im Terebinthentale, streitend mit den Philistern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Da machte sich David des Morgens früh auf und überließ das Kleinvieh einem Hüter; und er nahm und ging hin, wie Isai ihm geboten hatte; und er kam an die Wagenburg, als das Heer, das in die Schlachtreihe ausrückte, das Kampfgeschrei erhob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Und Israel und die Philister stellten sich auf, Schlachtreihe gegen Schlachtreihe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Und David überließ das Gerät, das er trug, der Hand des Hüters der Geräte und lief in die Schlachtreihe; und er kam und fragte seine Brüder nach ihrem Wohlergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Und während er mit ihnen redete, siehe, da kam der Zwischenkämpfer herauf, Goliath, der Philister, sein Name, von Gath, aus den Schlachtreihen der Philister und sprach nach jenen Worten; und David hörte es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Und alle Männer von Israel, als sie den Mann sahen, flohen vor ihm und fürchteten sich sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Und die Männer von Israel sprachen: Habt ihr diesen Mann gesehen, der heraufkommt? Denn um Israel zu verhöhnen, kommt er herauf. Und es soll geschehen, den Mann, der ihn erschlägt, den will der König bereichern mit großem Reichtum, und er will ihm seine Tochter geben, und das Haus seines Vaters will er frei machen in Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Da sprach David zu den Männern, die bei ihm standen, und sagte: Was soll dem Manne geschehen, der diesen Philister da erschlägt und den Hohn von Israel abwendet? Denn wer ist dieser Philister, dieser Unbeschnittene, daß er die Schlachtreihen des lebendigen Gottes verhöhnt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Und das Volk sprach zu ihm nach jenem Worte und sagte: So soll dem Manne geschehen, der ihn erschlägt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Und Eliab, sein ältester Bruder, hörte zu, als er zu den Männern redete; und der Zorn Eliabs entbrannte wider David, und er sprach: Warum doch bist du herabgekommen, und wem hast du jene wenigen Schafe in der Wüste überlassen? Ich kenne deine Vermessenheit wohl und die Bosheit deines Herzens; denn um den Streit zu sehen, bist du herabgekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Und David sprach: Was habe ich nun getan? Ist es nicht der Mühe wert?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Und er wandte sich von ihm ab, einem anderen zu, und sprach nach jenem Worte; und das Volk gab ihm Antwort nach der vorigen Antwort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Und die Worte, welche David geredet hatte, wurden gehört und man erzählte sie vor Saul; und er ließ ihn holen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Und David sprach zu Saul: Es entfalle keinem Menschen das Herz seinetwegen! Dein Knecht will gehen und mit diesem Philister kämpfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Aber Saul sprach zu David: Du vermagst nicht wider diesen Philister zu gehen, um mit ihm zu kämpfen; denn du bist ein Jüngling, er aber ist ein Kriegsmann von seiner Jugend an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Da sprach David zu Saul: Dein Knecht weidete das Kleinvieh für seinen Vater; kam nun ein Löwe oder ein Bär und trug ein Stück von der Herde fort,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'so lief ich ihm nach und schlug ihn und entriß es seinem Rachen; und erhob er sich wider mich, so ergriff ich ihn bei dem Barte und schlug ihn und tötete ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Sowohl den Löwen als auch den Bären hat dein Knecht erschlagen; und dieser Philister, dieser Unbeschnittene, soll sein wie einer von ihnen, weil er die Schlachtreihen des lebendigen Gottes verhöhnt hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Und David sprach: Jehova, der mich aus den Klauen des Löwen und aus den Klauen des Bären errettet hat, er wird mich aus der Hand dieses Philisters erretten. Und Saul sprach zu David: Gehe hin, und Jehova sei mit dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Und Saul zog David seinen Rock an und setzte einen ehernen Helm auf sein Haupt und zog ihm einen Panzer an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Und David gürtete sein Schwert über seinen Rock und wollte gehen, denn er hatte es nie versucht. Da sprach David zu Saul: Ich kann nicht darin gehen, denn ich habe es nie versucht. Und David legte sie von sich ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Und er nahm seinen Stab in seine Hand und wählte sich fünf glatte Steine aus dem Bache und tat sie in das Hirtengerät, das er hatte, in die Tasche, und seine Schleuder hatte er in seiner Hand; und er trat an den Philister heran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Und der Philister ging und kam dem David immer näher, und der Mann, der den Schild trug, vor ihm her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Und als der Philister hinschaute und David sah, verachtete er ihn; denn er war ein Jüngling und rötlich, dazu schön von Ansehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Und der Philister sprach zu David: Bin ich ein Hund, daß du mit Stöcken zu mir kommst? Und der Philister fluchte David bei seinen Göttern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Und der Philister sprach zu David: Komm her zu mir, daß ich dein Fleisch den Vögeln des Himmels und den Tieren des Feldes gebe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Und David sprach zu dem Philister: Du kommst zu mir mit Schwert und mit Speer und mit Wurfspieß; ich aber komme zu dir im Namen Jehovas der Heerscharen, des Gottes der Schlachtreihen Israels, den du verhöhnt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'An diesem Tage wird Jehova dich in meine Hand überliefern, und ich werde dich erschlagen und dein Haupt von dir wegnehmen; und die Leichname des Heeres der Philister werde ich an diesem Tage den Vögeln des Himmels und dem Wilde der Erde geben; und die ganze Erde soll erkennen, daß Israel einen Gott hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'Und diese ganze Versammlung soll erkennen, daß Jehova nicht durch Schwert und durch Speer rettet; denn Jehovas ist der Streit, und er wird euch in unsere Hand geben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Und es geschah, als der Philister sich aufmachte und ging und nahte, David entgegen, da eilte David und lief der Schlachtreihe zu, dem Philister entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Und David fuhr mit seiner Hand in das Gerät und nahm einen Stein heraus, und er schleuderte und traf den Philister an seine Stirn; und der Stein drang in seine Stirn, und er fiel auf sein Angesicht zur Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'So war David, mit der Schleuder und mit dem Steine, stärker als der Philister, und er schlug den Philister und tötete ihn; und David hatte kein Schwert in der Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Und David lief und trat zu dem Philister hin, und er nahm sein Schwert und zog es aus seiner Scheide und tötete ihn, und hieb ihm den Kopf damit ab. Als aber die Philister sahen, daß ihr Held tot war, da flohen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Und die Männer von Israel und Juda machten sich auf und erhoben ein Geschrei und verfolgten die Philister bis zum Eingang des Tales und bis zu den Toren von Ekron; und die Erschlagenen der Philister fielen auf dem Wege nach Schaaraim und bis Gath und bis Ekron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Und die Kinder Israel kehrten um von der Verfolgung der Philister und plünderten ihre Lager.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Und David nahm das Haupt des Philisters und brachte es nach Jerusalem; seine Waffen aber legte er in sein Zelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Und als Saul David ausziehen sah, dem Philister entgegen, sprach er zu Abner, dem Heerobersten: Wessen Sohn ist doch der Jüngling, Abner? Und Abner sprach: So wahr deine Seele lebt, o König, ich weiß es nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Und der König sprach: Frage du, wessen Sohn der junge Mann ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Und als David vom Erschlagen des Philisters zurückkehrte, da nahm ihn Abner und brachte ihn vor Saul; und das Haupt des Philisters war in seiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Und Saul sprach zu ihm: Wessen Sohn bist du, Jüngling? Und David sprach: Der Sohn deines Knechtes Isai, des Bethlehemiters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Und es geschah, als er aufgehört hatte, mit Saul zu reden, da verband sich die Seele Jonathans mit der Seele Davids; und Jonathan liebte ihn wie seine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Und Saul nahm ihn an jenem Tage zu sich und ließ ihn nicht in das Haus seines Vaters zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Und Jonathan und David schlossen einen Bund, weil er ihn liebte wie seine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Und Jonathan zog das Oberkleid aus, das er anhatte, und gab es David, und seinen Rock und bis auf sein Schwert und seinen Bogen und seinen Gürtel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Und David zog aus, wohin immer Saul ihn sandte, und er hatte Gelingen; und Saul setzte ihn über die Kriegsleute; und er war in den Augen des ganzen Volkes und auch in den Augen der Knechte Sauls wohlgefällig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Und es geschah, als sie einzogen, als David vom Erschlagen des Philisters zurückkehrte, da zogen die Weiber aus allen Städten Israels zu Gesang und Reigen dem König Saul entgegen, mit Tamburinen, mit Jubel und mit Triangeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Und die Weiber, die da spielten, sangen und sprachen: Saul hat seine Tausende erschlagen, und David seine Zehntausende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Da ergrimmte Saul sehr, und dieses Wort war übel in seinen Augen, und er sprach: Sie haben David Zehntausende gegeben, und mir haben sie die Tausende gegeben; es fehlt ihm nur noch das Königtum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Und Saul sah scheel auf David von jenem Tage an und hinfort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Und es geschah am anderen Tage, da geriet ein böser Geist von Gott über Saul, und er weissagte im Innern des Hauses; David aber spielte mit seiner Hand, wie Tag für Tag, und der Speer war in der Hand Sauls.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Und Saul warf den Speer und dachte: Ich will David an die Wand spießen! Aber David wandte sich zweimal von ihm ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Und Saul fürchtete sich vor David; denn Jehova war mit ihm, und von Saul war er gewichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Und Saul tat ihn von sich weg und setzte ihn zum Obersten über tausend; und er zog aus und ein vor dem Volke her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Und es gelang David auf allen seinen Wegen, und Jehova war mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Und als Saul sah, daß es ihm wohl gelang, scheute er sich vor ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Aber ganz Israel und Juda hatten David lieb, denn er zog aus und ein vor ihnen her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Und Saul sprach zu David: Siehe, meine älteste Tochter Merab, die will ich dir zum Weibe geben; nur sei mir ein tapferer Mann und streite die Streite Jehovas! Saul aber dachte: Meine Hand soll nicht wider ihn sein, sondern die Hand der Philister soll wider ihn sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Und David sprach zu Saul: Wer bin ich, und was ist mein Leben und das Geschlecht meines Vaters in Israel, daß ich des Königs Schwiegersohn werden sollte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Und es geschah zu der Zeit, als Merab, die Tochter Sauls, dem David gegeben werden sollte, da wurde sie Adriel, dem Meholathiter, zum Weibe gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Und Michal, die Tochter Sauls, liebte David; und man berichtete es Saul, und die Sache war recht in seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Und Saul sprach: Ich will sie ihm geben, daß sie ihm zum Fallstrick werde und die Hand der Philister wider ihn sei. Und Saul sprach zu David: Zum zweiten Male sollst du heute mein Schwiegersohn werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Und Saul gebot seinen Knechten: Redet im geheimen zu David und sprechet: Siehe, der König hat Gefallen an dir, und alle seine Knechte haben dich lieb; so werde nun des Königs Schwiegersohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Und die Knechte Sauls redeten diese Worte vor den Ohren Davids. Und David sprach: Ist es ein Geringes in euren Augen, des Königs Schwiegersohn zu werden? Bin ich doch ein armer und geringer Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Und die Knechte Sauls berichteten es ihm und sprachen: Nach diesen Worten hat David geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Da sprach Saul: So sollt ihr zu David sagen: Der König hat kein Begehr nach einer Heiratsgabe, sondern nach hundert Vorhäuten der Philister, um sich an den Feinden des Königs zu rächen. Saul aber gedachte David durch die Hand der Philister zu fällen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Und seine Knechte berichteten David diese Worte, und die Sache war recht in den Augen Davids, des Königs Schwiegersohn zu werden. Und noch waren die Tage nicht voll,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'da machte David sich auf und zog hin, er und seine Männer, und erschlug unter den Philistern zweihundert Mann; und David brachte ihre Vorhäute, und man lieferte sie dem König vollzählig, damit er des Königs Schwiegersohn würde. Und Saul gab ihm seine Tochter Michal zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Und Saul sah und erkannte, daß Jehova mit David war; und Michal, die Tochter Sauls, hatte ihn lieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Und Saul fürchtete sich noch mehr vor David; und Saul wurde David feind alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Und die Fürsten der Philister zogen aus; und es geschah, so oft sie auszogen, hatte David mehr Gelingen als alle Knechte Sauls, und sein Name wurde sehr geachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Und Saul redete zu seinem Sohne Jonathan und zu allen seinen Knechten, daß er David töten wolle. Jonathan aber, der Sohn Sauls, hatte großes Wohlgefallen an David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Und Jonathan berichtete es David und sprach: Mein Vater Saul sucht dich zu töten; und nun hüte dich doch morgen und halte dich verborgen und verstecke dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Ich aber will hinausgehen und an der Seite meines Vaters stehen auf dem Felde, wo du bist, und ich will zu meinem Vater von dir reden und sehen, wie es steht, und es dir berichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Und Jonathan redete zu seinem Vater Saul Gutes von David und sprach zu ihm: Der König versündige sich nicht an seinem Knechte, an David; denn er hat nicht gegen dich gesündigt, und seine Taten sind dir sehr nützlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Und er hat sein Leben aufs Spiel gesetzt und den Philister erschlagen, und Jehova hat dem ganzen Israel eine große Rettung geschafft. Du hast es gesehen und dich gefreut; und warum willst du dich an unschuldigem Blute versündigen, indem du David tötest ohne Ursache?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Und Saul hörte auf die Stimme Jonathans, und Saul schwur: So wahr Jehova lebt, wenn er getötet wird!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Da rief Jonathan dem David, und Jonathan berichtete ihm alle diese Worte. Und Jonathan brachte David zu Saul, und er war vor ihm wie früher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Und es ward wiederum Krieg; und David zog aus und stritt wider die Philister und richtete eine große Niederlage unter ihnen an, und sie flohen vor ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Und ein böser Geist von Jehova kam über Saul; und er saß in seinem Hause, mit seinem Speer in der Hand, und David spielte mit der Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Und Saul suchte David mit dem Speere an die Wand zu spießen; aber er wich aus vor Saul, und er stieß den Speer in die Wand. Und David floh und entrann in selbiger Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Da sandte Saul Boten in das Haus Davids, um ihn zu bewachen und ihn am Morgen zu töten. Aber Michal, sein Weib, tat es David kund und sprach: Wenn du nicht diese Nacht deine Seele rettest, so wirst du morgen getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Und Michal ließ David durchs Fenster hinab; und er ging weg und floh und entrann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Und Michal nahm den Teraphim und legte ihn ins Bett und legte das Geflecht von Ziegenhaar zu seinen Häupten und deckte ihn mit dem Tuche zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Und Saul sandte Boten, um David zu holen; und sie sprach: Er ist krank.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Da sandte Saul die Boten, um David zu sehen, und sprach: Bringet ihn im Bett zu mir herauf, daß ich ihn töte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Und die Boten kamen, und siehe, der Teraphim war im Bett, und das Geflecht von Ziegenhaar zu seinen Häupten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Da sprach Saul zu Michal: Warum hast du mich also betrogen und hast meinen Feind gehen lassen, daß er entronnen ist? Und Michal sprach zu Saul: Er sagte zu mir: Laß mich gehen! Warum sollte ich dich töten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'David aber war geflohen und entronnen; und er kam zu Samuel nach Rama und berichtete ihm alles, was Saul ihm getan hatte. Und er und Samuel gingen hin und wohnten zu Najoth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Und es wurde Saul berichtet und gesagt: Siehe, David ist in Najoth zu Rama.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Da sandte Saul Boten, um David zu holen. Als sie aber die Versammlung der Propheten sahen, welche weissagten, und Samuel als Vorsteher über sie dabeistehen, da kam der Geist Gottes über die Boten Sauls, und auch sie weissagten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Und man berichtete es Saul, und er sandte andere Boten, und auch sie weissagten; und Saul sandte wiederum dritte Boten, und auch sie weissagten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Da ging auch er nach Rama und kam an die große Zisterne, die zu Seku ist; und er fragte und sprach: Wo sind Samuel und David? Und man sprach: Siehe, in Najoth zu Rama.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Und er ging dorthin, nach Najoth zu Rama; und auch über ihn kam der Geist Gottes, und er ging, immerfort weissagend, bis er in Najoth zu Rama ankam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Und auch er zog seine Oberkleider aus, und auch er weissagte vor Samuel, und er lag nackt da jenen ganzen Tag und die ganze Nacht. Daher sagt man: Ist auch Saul unter den Propheten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Und David floh von Najoth zu Rama; und er kam und sprach vor Jonathan: Was habe ich getan? Was ist meine Ungerechtigkeit, und was meine Sünde vor deinem Vater, daß er nach meinem Leben trachtet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Und er sprach zu ihm: Das sei ferne! Du wirst nicht sterben. Siehe, mein Vater tut weder eine große noch eine kleine Sache, ohne daß er sie meinem Ohr eröffnete; und warum sollte mein Vater diese Sache vor mir verbergen? Es ist nicht so.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Und David fuhr fort und schwur und sprach: Dein Vater weiß wohl, daß ich Gnade gefunden habe in deinen Augen, und er hat gedacht: Jonathan soll dieses nicht wissen, damit er sich nicht betrübe. Aber doch, so wahr Jehova lebt und deine Seele lebt, nur ein Schritt ist zwischen mir und dem Tode!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Und Jonathan sprach zu David: Was deine Seele spricht, das will ich für dich tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Und David sprach zu Jonathan: Siehe, morgen ist Neumond, da ich eigentlich mit dem König beim Essen sitzen sollte; so laß mich gehen, und ich will mich auf dem Felde verbergen bis zum dritten Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Wenn dein Vater mich etwa vermissen sollte, so sage: David hat sich\'s dringend von mir erbeten, nach Bethlehem, seiner Stadt, zu laufen; denn daselbst ist das Jahresopfer für die ganze Familie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Wenn er so spricht: Es ist gut, so steht es wohl um deinen Knecht; ergrimmt er aber, so wisse, daß das Böse seinerseits beschlossen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Erweise denn Güte an deinem Knechte, denn du hast deinen Knecht in einen Bund Jehovas mit dir treten lassen! Wenn aber eine Ungerechtigkeit an mir ist, so töte du mich; denn warum wolltest du mich doch zu deinem Vater bringen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Und Jonathan sprach: Das sei ferne von dir! Denn wenn ich sicher weiß, daß es von seiten meines Vaters beschlossen ist, daß das Böse über dich komme, sollte ich es dir dann nicht berichten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Und David sprach zu Jonathan: Wer soll es mir berichten, wenn etwa dein Vater dir Hartes antwortet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Und Jonathan sprach zu David: Komm und laß uns aufs Feld hinausgehen. Und sie gingen beide hinaus aufs Feld.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Und Jonathan sprach zu David: Jehova, Gott Israels! Wenn ich meinen Vater um diese Zeit morgen oder übermorgen ausforsche, und siehe, es steht gut für David, und ich nicht alsdann zu dir sende und es deinem Ohr eröffne,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'so tue Jehova dem Jonathan, und so füge er hinzu! Wenn meinem Vater Böses wider dich gefällt, so werde ich es deinem Ohr eröffnen und dich ziehen lassen, daß du in Frieden weggehest; und Jehova sei mit dir, so wie er mit meinem Vater gewesen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Und nicht nur während ich noch lebe, und nicht nur an mir sollst du Güte Jehovas erweisen, daß ich nicht sterbe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'auch meinem Hause sollst du deine Güte nicht entziehen ewiglich, auch nicht, wenn Jehova die Feinde Davids ausrotten wird, einen jeden vom Erdboden hinweg!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Und Jonathan machte einen Bund mit dem Hause Davids und sprach: So fordere es Jehova von der Hand der Feinde Davids!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Und Jonathan ließ David nochmals bei seiner Liebe zu ihm schwören; denn er liebte ihn, wie er seine Seele liebte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Und Jonathan sprach zu ihm: Morgen ist Neumond; und man wird dich vermissen, denn dein Sitz wird leer bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Am dritten Tage aber steige eilends herab und komm an den Ort, wo du dich verborgen hattest am Tage der Tat, und bleibe neben dem Steine Asel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Ich nun, ich werde drei Pfeile zu seiner Seite abschießen, als schösse ich für mich nach einem Ziele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Und siehe, ich werde den Knaben senden: Gehe hin, suche die Pfeile! Wenn ich ausdrücklich zu dem Knaben spreche: Siehe, die Pfeile sind von dir ab herwärts, nimm sie! so komm! Denn es steht wohl um dich, und es ist nichts, so wahr Jehova lebt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Wenn ich aber also zu dem Jüngling spreche: Siehe, die Pfeile sind von dir ab hinwärts! so gehe, denn Jehova sendet dich weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Was aber die Sache betrifft, die wir besprochen haben, ich und du, siehe, Jehova ist zwischen mir und dir auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Und David verbarg sich auf dem Felde. Und es wurde Neumond, und der König setzte sich zum Mahle, um zu essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Und der König setzte sich auf seinen Sitz, wie die anderen Male, auf den Sitz an der Wand; und Jonathan stand auf, und Abner setzte sich zur Seite Sauls; und der Platz Davids blieb leer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Saul aber sagte nichts an selbigem Tage, denn er dachte: Es ist ihm etwas widerfahren; er ist nicht rein, gewiß, er ist nicht rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Und es geschah am anderen Tage des Neumondes, dem zweiten, als der Platz Davids leer blieb, da sprach Saul zu seinem Sohne Jonathan: Warum ist der Sohn Isais weder gestern noch heute zum Mahle gekommen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Und Jonathan antwortete Saul: David hat sich\'s dringend von mir erbeten, nach Bethlehem zu gehen, und er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Laß mich doch gehen, denn wir haben ein Familienopfer in der Stadt; und mein Bruder selbst hat mich entboten; und nun, wenn ich Gnade gefunden habe in deinen Augen, so laß mich doch gehen, daß ich meine Brüder sehe! Darum ist er nicht an den Tisch des Königs gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Da entbrannte der Zorn Sauls wider Jonathan, und er sprach zu ihm: Sohn einer widerspenstigen Verkehrten! Weiß ich nicht, daß du den Sohn Isais auserkoren hast zu deiner Schande und zur Schande der Blöße deiner Mutter?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Denn alle die Tage, die der Sohn Isais auf Erden lebt, wirst du nicht feststehen, weder du noch dein Königtum; und nun sende hin und laß ihn zu mir holen, denn er ist ein Kind des Todes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Und Jonathan antwortete seinem Vater Saul und sprach zu ihm: Warum soll er getötet werden? Was hat er getan?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Da warf Saul den Speer nach ihm, um ihn zu treffen; und Jonathan erkannte, daß es von seiten seines Vaters beschlossen sei, David zu töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Und Jonathan stand vom Tische auf in glühendem Zorn, und er aß am zweiten Tage des Neumondes keine Speise; denn er war betrübt um David, weil sein Vater ihn geschmäht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Und es geschah am Morgen, da ging Jonathan aufs Feld hinaus, an den Ort, den er mit David verabredet hatte, und ein kleiner Knabe war mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Und er sprach zu seinem Knaben: Laufe, suche doch die Pfeile, die ich abschieße! Der Knabe lief, und er schoß den Pfeil über ihn hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Und als der Knabe an den Ort des Pfeiles kam, welchen Jonathan abgeschossen hatte, da rief Jonathan dem Knaben nach und sprach: Der Pfeil ist ja von dir ab hinwärts!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Und Jonathan rief dem Knaben nach: Schnell, eile, stehe nicht still! Und der Knabe Jonathans las den Pfeil auf und kam zu seinem Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Der Knabe aber wußte um nichts; nur Jonathan und David wußten um die Sache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Und Jonathan gab seine Waffen seinem Knaben und sprach zu ihm: Gehe, bringe sie in die Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Der Knabe ging, und David machte sich auf von der Südseite her und fiel auf sein Antlitz zur Erde und beugte sich dreimal nieder; und sie küßten einander und weinten miteinander, bis David über die Maßen weinte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Und Jonathan sprach zu David: Gehe hin in Frieden! Es sei, wie wir beide im Namen Jehovas geschworen haben, als wir sagten: Jehova sei zwischen mir und dir und zwischen meinem Samen und deinem Samen auf ewig! (H20:43) Und David machte sich auf und ging hinweg; Jonathan aber kam in die Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Und David kam nach Nob, zu Ahimelech, dem Priester. Und Ahimelech kam David ängstlich entgegen und sprach zu ihm: Warum bist du allein, und niemand ist bei dir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'Und David sprach zu dem Priester Ahimelech: Der König hat mir eine Sache geboten; und er sprach zu mir: Niemand soll irgendwie um die Sache wissen, in der ich dich sende und die ich dir geboten habe! Und die Knaben habe ich an den und den Ort beschieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Und nun, was ist unter deiner Hand? Gib fünf Brote in meine Hand, oder was sich vorfindet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Und der Priester antwortete David und sprach: Es ist kein gemeines Brot unter meiner Hand, sondern nur heiliges Brot ist da; wenn sich nur die Knaben der Weiber enthalten haben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Und David antwortete dem Priester und sprach zu ihm: Ja, denn Weiber sind uns versagt seit gestern und vorgestern, als ich auszog, und die Gefäße der Knaben sind heilig. Und es ist einigermaßen gemeines Brot, und das um so mehr, als heute neues in den Gefäßen geheiligt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Da gab ihm der Priester heiliges Brot; denn es war daselbst kein anderes Brot, als nur das Schaubrot, das vor Jehova weggenommen worden war, um warmes Brot aufzulegen am Tage seiner Wegnahme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, '(Es war aber daselbst an jenem Tage ein Mann von den Knechten Sauls, der sich zurückgezogen vor Jehova aufhielt, sein Name war Doeg, der Edomiter; er war der Aufseher der Hirten Sauls.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Und David sprach zu Ahimelech: Und ist hier nicht unter deiner Hand ein Speer oder ein Schwert? Denn weder mein Schwert noch meine Waffen habe ich zur Hand genommen, weil die Sache des Königs dringend war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Und der Priester sprach: Das Schwert Goliaths, des Philisters, den du im Terebinthental erschlagen hast, siehe, es ist in ein Oberkleid gewickelt hinter dem Ephod; wenn du es dir nehmen willst, so nimm es, denn es ist kein anderes hier außer diesem. Und David sprach: Seinesgleichen gibt es nicht; gib es mir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Und David machte sich auf und floh an selbigem Tage vor Saul, und er kam zu Achis, dem König von Gath.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Und die Knechte Achis\' sprachen zu ihm: Ist das nicht David, der König des Landes? Haben sie nicht von diesem in den Reigen gesungen und gesprochen: \"Saul hat seine Tausende erschlagen, und David seine Zehntausende\"?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Und David nahm sich diese Worte zu Herzen und fürchtete sich sehr vor Achis, dem König von Gath.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Und er verstellte seinen Verstand vor ihren Augen und tat unsinnig unter ihren Händen, und er kritzelte an die Flügel des Tores und ließ seinen Speichel auf seinen Bart herabfließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Da kam Achis zu seinen Knechten: Siehe, ihr sehet einen wahnsinnigen Mann; warum bringet ihr ihn zu mir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Fehlt es mir an Wahnsinnigen, daß ihr diesen hergebracht habt, um sich bei mir wahnsinnig zu gebärden? Sollte der in mein Haus kommen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Und David ging von dannen und entrann in die Höhle Adullam. Und als seine Brüder und das ganze Haus seines Vaters es hörten, kamen sie dorthin zu ihm hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Und es versammelten sich zu ihm jeder Bedrängte, und jeder, der einen Gläubiger hatte, und jeder, der erbitterten Gemütes war, und er wurde ihr Oberster, und es waren bei ihm an vierhundert Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Und David ging von dannen nach Mizpe-Moab; und er sprach zu dem König von Moab: Laß doch meinen Vater und meine Mutter ausziehen und bei euch sein, bis ich weiß, was Gott mir tun wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Und er führte sie vor den König von Moab, und sie wohnten bei ihm alle Tage, die David auf der Bergfeste war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Und Gad, der Prophet, sprach zu David: Bleibe nicht auf der Bergfeste; gehe hin und begib dich in das Land Juda. Und David ging hin und kam in den Wald Hereth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Und als Saul hörte, daß David und die Männer, die bei ihm waren, entdeckt worden seien, Saul aber saß zu Gibea, unter der Tamariske auf der Anhöhe, mit seinem Speer in der Hand, und alle seine Knechte standen bei ihm,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'da sprach Saul zu seinen Knechten, die bei ihm standen: Höret doch, ihr Benjaminiter! Wird auch der Sohn Isais euch allen Felder und Weinberge geben, euch alle zu Obersten über tausend und zu Obersten über hundert machen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'daß ihr euch alle wider mich verschworen habt, und keiner es meinem Ohr eröffnet, wenn mein Sohn einen Bund mit dem Sohne Isais gemacht hat, und keiner von euch sich kränkt meinethalben und es meinem Ohr eröffnet, daß mein Sohn meinen Knecht als Laurer wider mich aufgewiegelt hat, wie es an diesem Tage ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Da antwortete Doeg, der Edomiter, der bei den Knechten Sauls stand, und sprach: Ich sah den Sohn Isais nach Nob kommen zu Ahimelech, dem Sohne Ahitubs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Und er befragte Jehova für ihn und gab ihm Zehrung, und das Schwert Goliaths, des Philisters, gab er ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Da sandte der König hin, Ahimelech, den Sohn Ahitubs, den Priester, zu rufen, sowie das ganze Haus seines Vaters, die Priester, die zu Nob waren; und sie kamen alle zum König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Und Saul sprach: Höre doch, Sohn Ahitubs! Und er sprach: Hier bin ich, mein Herr!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Und Saul sprach zu ihm: Warum habt ihr euch wider mich verschworen, du und der Sohn Isais, indem du ihm Brot und ein Schwert gegeben und Gott für ihn befragt hast, damit er als Laurer wider mich aufstehe, wie es an diesem Tage ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Und Ahimelech antwortete dem König und sprach: Und wer unter all deinen Knechten ist wie David, treu, und des Königs Schwiegersohn, und der Zutritt hat zu deinem geheimen Rat und geehrt ist in deinem Hause?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Habe ich heute angefangen, Gott für ihn zu befragen? Das sei ferne von mir! Nicht lege der König seinem Knechte etwas zur Last, noch dem ganzen Hause meines Vaters; denn dein Knecht hat von allem diesem nichts gewußt, weder Kleines noch Großes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Aber der König sprach: Du mußt gewißlich sterben Ahimelech, du und das ganze Haus deines Vaters!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Und der König sprach zu den Läufern, die bei ihm standen: Wendet euch und tötet die Priester Jehovas, weil auch ihre Hand mit David ist und, weil sie wußten, daß er floh und es meinem Ohre nicht eröffnet haben. Aber die Knechte des Königs wollten ihre Hand nicht ausstrecken, um über die Priester Jehovas herzufallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Da sprach der König zu Doeg: Wende du dich und falle über die Priester her! Und Doeg, der Edomiter, wandte sich und fiel über die Priester her, und er tötete an selbigem Tage fünfundachtzig Mann, die das leinene Ephod trugen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Und Nob, die Stadt der Priester, schlug er mit der Schärfe des Schwertes, vom Manne bis zum Weibe, vom Kinde bis zum Säugling, und Rind und Esel und Kleinvieh, mit der Schärfe des Schwertes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Und es entrann ein Sohn Ahimelechs, des Sohnes Ahitubs, sein Name war Abjathar; und er entfloh, David nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Und Abjathar berichtete David, daß Saul die Priester Jehovas ermordet hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Da sprach David zu Abjathar: Ich wußte an jenem Tage, weil Doeg, der Edomiter, daselbst war, daß er es Saul sicher berichten würde. Ich bin schuldig an allen Seelen des Hauses deines Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Bleibe bei mir, fürchte dich nicht; denn wer nach meiner Seele trachtet, trachtet nach deiner Seele; denn bei mir bist du wohlbewahrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Und man berichtete David und sprach: Siehe, die Philister streiten wider Kehila, und sie plündern die Tennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Und David befragte Jehova und sprach: Soll ich hinziehen und diese Philister schlagen? Und Jehova sprach zu David: Ziehe hin, und schlage die Philister und rette Kehila.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Aber die Männer Davids sprachen zu ihm: Siehe, wir fürchten uns hier in Juda, und wie sollten wir gar nach Kehila wider die Schlachtreihen der Philister ziehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Da befragte David wiederum Jehova, und Jehova antwortete ihm und sprach: Mache dich auf, ziehe nach Kehila hinab; denn ich werde die Philister in deine Hand geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Und David zog mit seinen Männern nach Kehila und stritt wider die Philister, und er trieb ihr Vieh weg und richtete eine große Niederlage unter ihnen an. Und so rettete David die Bewohner von Kehila. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Es geschah aber, als Abjathar, der Sohn Ahimelechs, zu David nach Kehila floh, da kam er hinab mit einem Ephod in seiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Und es wurde Saul berichtet, daß David nach Kehila gekommen wäre. Da sprach Saul: Gott hat ihn verworfen und in meine Hand überliefert; denn er hat sich eingeschlossen, indem er in eine Stadt mit Toren und Riegeln gekommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Und Saul rief alles Volk, zum Streit auf, um nach Kehila hinabzuziehen, David und seine Männer zu belagern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Und als David erfuhr, daß Saul Böses wider ihn schmiedete, da sprach er zu Abjathar, dem Priester: Bringe das Ephod her!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Und David sprach: Jehova, Gott Israels! Dein Knecht hat für gewiß gehört, daß Saul danach trachtet, nach Kehila zu kommen, um die Stadt zu verderben um meinetwillen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Werden die Bürger von Kehila mich seiner Hand ausliefern? Wird Saul herabziehen, wie dein Knecht gehört hat? Jehova, Gott Israels, tue es doch deinem Knechte kund! Und Jehova sprach: Er wird herabziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Und David sprach: Werden die Bürger von Kehila mich und meine Männer der Hand Sauls ausliefern? Und Jehova sprach: Sie werden dich ausliefern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Da machten David und seine Männer sich auf, bei sechshundert Mann, und sie zogen von Kehila aus und gingen, wohin sie gehen konnten. Und es wurde Saul berichtet, daß David aus Kehila entronnen wäre; da stand er davon ab auszuziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Und David blieb in der Wüste auf den Bergfesten, und er blieb auf dem Gebirge in der Wüste Siph. Und Saul suchte ihn alle Tage, aber Gott gab ihn nicht in seine Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Und David sah, daß Saul ausgezogen war, um nach seinem Leben zu trachten; und David war in der Wüste Siph, im Walde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Da machte sich Jonathan, der Sohn Sauls, auf und ging zu David in den Wald und stärkte seine Hand in Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Und er sprach zu ihm: Fürchte dich nicht! Denn die Hand meines Vaters Saul wird dich nicht finden; und du wirst König werden über Israel, und ich werde der zweite nach dir sein; und auch mein Vater Saul weiß es so.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Und sie schlossen beide einen Bund vor Jehova. Und David blieb im Walde, und Jonathan ging nach seinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Da zogen die Siphiter zu Saul hinauf, nach Gibea, und sprachen: Hält sich David nicht bei uns verborgen auf den Bergfesten im Walde, auf dem Hügel Hakila, der zur Rechten der Wildnis ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Und nun, o König, wenn irgend deine Seele es begehrt, herabzukommen, so komm herab; und an uns ist es, ihn der Hand des Königs auszuliefern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Und Saul sprach: Gesegnet seiet ihr von Jehova, daß ihr euch meiner erbarmt habt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Gehet doch hin, vergewissert euch noch mehr, und erkundet und sehet seinen Ort, wo sein Fuß weilt, und wer ihn daselbst gesehen hat; denn man hat mir gesagt, er sei sehr listig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Und besehet und kundet alle Schlupfwinkel aus, wo er sich versteckt hält, und kommet wieder zu mir mit sicherer Kunde; und ich werde mit euch gehen. Und es soll geschehen, wenn er im Lande ist, so will ich ihn aufspüren unter allen Tausenden Judas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Und sie machten sich auf und gingen nach Siph, vor Saul her. David und seine Männer waren aber in der Wüste Maon, in der Ebene, zur Rechten der Wildnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Und Saul und seine Männer zogen hin, um ihn zu suchen; und man berichtete es David, und er ging den Felsen hinab und blieb in der Wüste Maon. Und als Saul es hörte, jagte er David nach in die Wüste Maon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Und Saul ging auf dieser Seite des Berges, David aber und seine Männer auf jener Seite des Berges. Und es geschah, als David eilte, Saul zu entgehen, und Saul und seine Männer David und seine Männer umringten, um sie zu fangen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'da kam ein Bote zu Saul und sprach: Eile und komm, denn die Philister sind ins Land eingefallen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Da kehrte Saul um von der Verfolgung Davids und zog den Philistern entgegen. Daher nannte man jenen Ort: Selach-Hammachlekoth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, '(H24:1) Und David zog von dannen hinauf und blieb auf den Bergfesten von Engedi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, '(H24:2) Und es geschah, als Saul von der Verfolgung der Philister zurückgekehrt war, da berichtete man ihm und sprach: Siehe, David ist in der Wüste Engedi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, '(H24:3) Und Saul nahm dreitausend auserlesene Männer aus ganz Israel und zog hin, um David und seine Männer auf den Steinbockfelsen zu suchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, '(H24:4) Und er kam zu den Kleinviehhürden am Wege, wo eine Höhle war, und Saul ging hinein, um seine Füße zu bedecken; David aber und seine Männer saßen am hinteren Ende der Höhle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, '(H24:5) Da sprachen die Männer Davids zu ihm: Siehe, das ist der Tag, von welchem Jehova zu dir gesagt hat: Siehe, ich werde deinen Feind in deine Hand geben, und tue ihm, wie es gut ist in deinen Augen. Und David stand auf und schnitt heimlich einen Zipfel von dem Oberkleide Sauls ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, '(H24:6) Aber es geschah hernach, da schlug dem David sein Herz, darum daß er den Zipfel von dem Oberkleide Sauls abgeschnitten hatte; und er sprach zu seinen Männern:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, '(H24:7) Jehova lasse es fern von mir sein, daß ich so etwas an meinem Herrn, dem Gesalbten Jehovas, tun sollte, meine Hand gegen ihn auszustrecken! Denn er ist der Gesalbte Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, '(H24:8) Und David wehrte seinen Männern mit diesen Worten und ließ ihnen nicht zu, sich wider Saul zu erheben. Und Saul stand auf aus der Höhle und zog seines Weges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, '(H24:9) Und nachher machte David sich auf, und er ging aus der Höhle hinaus und rief hinter Saul her und sprach: Mein Herr König! Und Saul blickte hinter sich, und David neigte sein Antlitz zur Erde und beugte sich nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, '(H24:10) Und David sprach zu Saul: Warum hörst du auf die Worte der Menschen, welche sagen: Siehe, David sucht dein Unglück?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, '(H24:11) Siehe, an diesem Tage haben deine Augen gesehen, daß Jehova dich heute in meine Hand gegeben hat in der Höhle. Und man sagte mir, ich solle dich töten; aber mein Auge schonte deiner, und ich sprach: Ich will meine Hand nicht wider meinen Herrn ausstrecken, denn er ist der Gesalbte Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, '(H24:12) Und sieh, mein Vater, ja, sieh den Zipfel deines Oberkleides in meiner Hand! Denn daß ich einen Zipfel deines Oberkleides abgeschnitten und dich nicht getötet habe, daran erkenne und sieh, daß nichts Böses in meiner Hand ist, noch ein Vergehen, und daß ich nicht an dir gesündigt habe; du aber stellst meinem Leben nach, um es zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, '(H24:13) Jehova richte zwischen mir und dir, und Jehova räche mich an dir; aber meine Hand soll nicht wider dich sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, '(H24:14) Wie der Spruch der Vorväter sagt: Von den Gesetzlosen kommt Gesetzlosigkeit; aber meine Hand soll nicht wider dich sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, '(H24:15) Hinter wem zieht der König von Israel her? Wem jagst du nach? Einem toten Hunde, einem Floh!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, '(H24:16) So sei denn Jehova Richter, und richte zwischen mir und dir; und er sehe darein und führe meine Streitsache und verschaffe mir Recht aus deiner Hand!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, '(H24:17) Und es geschah, als David diese Worte zu Saul ausgeredet hatte, da sprach Saul: Ist das deine Stimme, mein Sohn David? Und Saul erhob seine Stimme und weinte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, '(H24:18) Und er sprach zu David: Du bist gerechter als ich. Denn du hast mir Gutes erzeigt, ich aber habe dir Böses erzeigt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, '(H24:19) und du hast heute bewiesen, daß du Gutes an mir getan hast, da Jehova mich in deine Hand geliefert, und du mich nicht getötet hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, '(H24:20) Denn wenn jemand seinen Feind findet, wird er ihn auf gutem Wege ziehen lassen? So möge Jehova dir Gutes vergelten für das, was du an diesem Tage an mir getan hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, '(H24:21) Und nun siehe, ich weiß, daß du gewißlich König werden wirst, und daß in deiner Hand das Königtum Israels bestehen wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, '(H24:22) so schwöre mir nun bei Jehova, daß du meinen Samen nach mir nicht ausrotten und meinen Namen nicht vertilgen willst aus dem Hause meines Vaters!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, '(H24:23) Und David schwur Saul. Und Saul ging nach seinem Hause; David und seine Männer aber stiegen auf die Bergfeste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Und Samuel starb; und ganz Israel versammelte sich und klagte um ihn und begrub ihn in seinem Hause zu Rama. Und David machte sich auf und zog hinab in die Wüste Paran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Und es war ein Mann in Maon, der seine Geschäfte zu Karmel hatte; und der Mann war sehr vermögend und hatte dreitausend Schafe und tausend Ziegen; und er war während der Schur seiner Schafe in Karmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Und der Name des Mannes war Nabal, und der Name seines Weibes Abigail. Und das Weib war von guter Einsicht und schön von Gestalt; der Mann aber war hart und boshaft in seinen Handlungen, und er war ein Kalebiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Und David hörte in der Wüste, daß Nabal seine Schafe schor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Da sandte David zehn Knaben, und David sprach zu den Knaben: Ziehet nach Karmel hinauf, und gehet zu Nabal und fraget ihn in meinem Namen nach seinem Wohlergehen, und sprechet also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'Lebe lange! Und Friede dir, und Friede deinem Hause, und Friede allem, was dein ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Und jetzt habe ich gehört, daß du die Schafscherer hast; nun, deine Hirten sind bei uns gewesen, wir haben ihnen nichts zuleide getan, und nicht das Geringste ist von ihnen vermißt worden alle die Tage, die sie zu Karmel gewesen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Frage deine Knaben, und sie werden es dir kundtun. Mögen denn die Knaben Gnade finden in deinen Augen, denn an einem guten Tage sind wir gekommen; gib doch deinen Knechten und deinem Sohne David, was deine Hand findet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Und die Knaben Davids kamen hin und redeten zu Nabal nach allen diesen Worten, im Namen Davids; und sie hielten inne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Aber Nabal antwortete den Knechten Davids und sprach: Wer ist David, und wer der Sohn Isais? Heutzutage sind der Knechte viele, die davonlaufen, ein jeder seinem Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Und ich sollte mein Brot und mein Wasser nehmen und mein Geschlachtetes, das ich für meine Scherer geschlachtet habe, und es Männern geben, von denen ich nicht weiß, woher sie sind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Und die Knaben Davids wandten sich auf ihren Weg; und sie kehrten zurück und kamen und berichteten ihm nach allen diesen Worten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Da sprach David zu seinen Männern: Gürtet ein jeder sein Schwert um! Und sie gürteten ein jeder sein Schwert um, und auch David gürtete sein Schwert um; und sie zogen hinauf, hinter David her, bei vierhundert Mann, und zweihundert blieben bei dem Geräte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Und ein Knabe von den Knaben berichtete der Abigail, dem Weibe Nabals, und sprach: Siehe, David hat Boten aus der Wüste gesandt, um unseren Herrn zu segnen; aber er hat sie angefahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Und doch sind die Männer sehr gut gegen uns gewesen; und es ist uns nichts zuleide geschehen, und wir haben nicht das Geringste vermißt alle die Tage, die wir mit ihnen umhergezogen sind, als wir auf dem Felde waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Sie sind eine Mauer um uns gewesen bei Nacht wie bei Tage, alle die Tage, die wir bei ihnen waren und das Kleinvieh weideten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Und nun wisse und sieh zu, was du tun willst; denn das Unglück ist beschlossen gegen unseren Herrn und über sein ganzes Haus; und er ist ein solcher Sohn Belials, daß man nicht zu ihm reden kann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Da eilte Abigail und nahm zweihundert Brote und zwei Schläuche Wein und fünf zubereitete Schafe und fünf Maß geröstete Körner und hundert Rosinenkuchen und zweihundert Feigenkuchen, und lud sie auf Esel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'und sie sprach zu ihren Knaben: Ziehet vor mir hin; siehe, ich komme hinter euch her. Aber ihrem Manne Nabal sagte sie nichts davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Und es geschah, als sie auf dem Esel ritt und an einer durch den Berg verdeckten Stelle herabkam, siehe, da kamen David und seine Männer herab, ihr entgegen; und sie stieß auf sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'David aber hatte gesagt: Fürwahr, umsonst habe ich alles behütet, was diesem Menschen in der Wüste gehörte, so daß nicht das Geringste vermißt wurde von allem, was sein ist; und er hat mir Böses für Gutes vergolten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'So tue Gott den Feinden Davids, und so füge er hinzu, wenn ich von allem, was sein ist, bis zum Morgenlicht übriglasse, was männlich ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Und als Abigail David sah, da stieg sie eilends von dem Esel herab; und sie fiel vor David auf ihr Angesicht und beugte sich zur Erde nieder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'und sie fiel ihm zu Füßen und sprach: Auf mir, mir, mein Herr, sei die Schuld! Und laß doch deine Magd zu deinen Ohren reden, und höre die Worte deiner Magd!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Mein Herr kümmere sich doch nicht um diesen Mann Belials, um Nabal; denn wie sein Name, so ist er: Nabal ist sein Name, und Torheit ist bei ihm. Und ich, deine Magd, habe die Knaben meines Herrn nicht gesehen, die du gesandt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Und nun, mein Herr, so wahr Jehova lebt und deine Seele lebt, Jehova hat dich verhindert in Blutschuld zu kommen, und daß deine Hand dir Hilfe schaffe! Und nun, mögen wie Nabal sein deine Feinde und die Böses suchen wider meinen Herrn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Und nun, dieses Geschenk, das deine Magd meinem Herrn gebracht hat, es werde den Knaben gegeben, die im Gefolge meines Herrn ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Vergib doch das Vergehen deiner Magd! Denn gewißlich wird Jehova meinem Herrn ein beständiges Haus machen, weil mein Herr die Streite Jehovas streitet, und kein Böses an dir gefunden ward, seitdem du lebst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Und ein Mensch ist aufgestanden, dich zu verfolgen und nach deiner Seele zu trachten; aber die Seele meines Herrn wird eingebunden sein in das Bündel der Lebendigen bei Jehova, deinem Gott; und die Seele deiner Feinde, die wird er wegschleudern in der Pfanne der Schleuder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Und es wird geschehen, wenn Jehova meinem Herrn tun wird nach all dem Guten, das er über dich geredet hat, und dich bestellen wird zum Fürsten über Israel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'so wird dir dieses nicht zum Anstoß sein, noch zum Herzensvorwurf für meinen Herrn, daß du Blut vergossen habest ohne Ursache, und daß mein Herr sich selbst Hilfe geschafft habe. Und wenn Jehova meinem Herrn wohltun wird, so gedenke deiner Magd.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Und David sprach zu Abigail: Gepriesen sei Jehova, der Gott Israels, der dich an diesem Tage mir entgegengesandt hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Und gesegnet sei dein Verstand, und gesegnet seiest du, daß du mich heute davon zurückgehalten hast, in Blutschuld zu kommen und mir mit meiner Hand Hilfe zu schaffen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Doch aber, so wahr Jehova lebt, der Gott Israels, der mich verhindert hat, dir Übles zu tun, wenn du nicht geeilt hättest und mir nicht entgegengekommen wärest, so wäre dem Nabal bis zum Morgenlicht nicht übriggeblieben, was männlich ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Und David nahm von ihrer Hand, was sie ihm gebracht hatte, und sprach zu ihr: Ziehe in Frieden hinauf nach deinem Hause. Siehe, ich habe auf deine Stimme gehört und deine Person angesehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Und als Abigail zu Nabal kam, siehe, da hatte er ein Mahl in seinem Hause wie ein Königsmahl; und das Herz Nabals war fröhlich in ihm, und er war trunken über die Maßen. Und sie berichtete ihm weder Kleines noch Großes, bis der Morgen hell wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Und es geschah am Morgen, als der Weinrausch von Nabal gegangen war, da berichtete ihm sein Weib diese Dinge; und sein Herz erstarb in seinem Innern, und er wurde wie ein Stein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Und es geschah ungefähr zehn Tage nachher, da schlug Jehova Nabal, und er starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Und als David hörte, daß Nabal gestorben war, sprach er: Gepriesen sei Jehova, der den Rechtsstreit meiner Schmach von seiten Nabals geführt und seinen Knecht vom Bösen abgehalten hat! Und die Bosheit Nabals hat Jehova auf seinen Kopf zurückkehren lassen. Und David sandte hin und warb um Abigail, um sie sich zum Weibe zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Und die Knechte Davids kamen zu Abigail nach Karmel; und sie redeten zu ihr und sprachen: David hat uns zu dir gesandt, um dich zu seinem Weibe zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Da stand sie auf und beugte sich nieder, das Antlitz zur Erde, und sprach: Siehe, deine Magd als Dienerin, um die Füße der Knechte meines Herrn zu waschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Und Abigail machte sich eilends auf und bestieg einen Esel, sie und ihre fünf Mägde, die ihrem Fuße folgten; und sie zog den Boten Davids nach, und sie wurde sein Weib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Und David hatte auch Achinoam von Jisreel genommen; und so wurden sie alle beide seine Weiber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Saul aber hatte seine Tochter Michal, das Weib Davids, Palti, dem Sohne des Lais, aus Gallim, gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Und die Siphiter kamen zu Saul nach Gibea und sprachen: Hält sich David nicht verborgen auf dem Hügel Hakila vor der Wildnis?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Da machte Saul sich auf und zog in die Wüste Siph hinab, und mit ihm dreitausend auserlesene Männer von Israel, um David in der Wüste Siph zu suchen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'und Saul lagerte sich auf dem Hügel Hakila, der vor der Wildnis am Wege liegt. David aber wohnte in der Wüste. Und als er sah, daß Saul ihm in die Wüste nachgekommen war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'da sandte David Kundschafter aus, und er erfuhr mit Gewißheit, daß Saul gekommen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Und David machte sich auf und kam an den Ort, wo Saul lagerte; und David sah den Ort, wo Saul lag und Abner, der Sohn Ners, sein Heeroberster; Saul lag aber in der Wagenburg, und das Volk lagerte um ihn her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Und David hob an und sprach zu Ahimelech, dem Hethiter, und zu Abisai, dem Sohne der Zeruja, dem Bruder Joabs, und sprach: Wer will mit mir zu Saul in das Lager hinabgehen? Und Abisai sprach: Ich will mit dir hinabgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Und David und Abisai kamen zu dem Volke bei der Nacht; und siehe, Saul lag schlafend in der Wagenburg, und sein Speer war in die Erde gesteckt zu seinen Häupten; und Abner und das Volk lagen rings um ihn her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Und Abisai sprach zu David: Heute hat Gott deinen Feind in deine Hand geliefert; und nun laß mich ihn doch mit dem Speere an die Erde spießen, ein einziges Mal, und ich werde es nicht zweimal tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Aber David sprach zu Abisai: Verderbe ihn nicht! Denn wer streckte seine Hand gegen den Gesalbten Jehovas aus und bliebe schuldlos?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Und David sprach: So wahr Jehova lebt, wenn nicht Jehova ihn schlagen wird, sei es daß sein Tag kommt, daß er stirbt, oder daß er in den Streit hinabzieht und weggerafft wird!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Jehova lasse es fern von mir sein, daß ich meine Hand gegen den Gesalbten Jehovas ausstrecke! Und nun nimm doch den Speer, der zu seinen Häupten ist, und den Wasserkrug, und laß uns gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Und David nahm den Speer und den Wasserkrug von den Häupten Sauls weg, und sie gingen davon; und niemand sah es, und niemand merkte es, und niemand erwachte, denn sie schliefen allesamt; denn ein tiefer Schlaf von Jehova war auf sie gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Und David ging hinüber nach der anderen Seite und stellte sich auf den Gipfel des Berges von ferne; der Raum zwischen ihnen war groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Und David rief dem Volke und Abner, dem Sohne Ners, zu und sprach: Antwortest du nicht, Abner? Und Abner antwortete und sprach: Wer bist du, der du dem Könige zurufst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Und David sprach zu Abner: Bist du nicht ein Mann? Und wer ist wie du in Israel? Und warum hast du nicht über deinen Herrn, den König, gewacht? Denn es ist einer vom Volke gekommen, um den König, deinen Herrn, zu verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Nicht gut ist diese Sache, die du getan hast. So wahr Jehova lebt, ihr seid Kinder des Todes, weil ihr nicht gewacht habt über euren Herrn, über den Gesalbten Jehovas! Und nun sieh nach, wo der Speer des Königs ist und der Wasserkrug, die zu seinen Häupten waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Und Saul erkannte die Stimme Davids und sprach: Ist das deine Stimme, mein Sohn David? Und David sprach: Es ist meine Stimme, mein Herr König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Und er sprach: Warum doch verfolgt mein Herr seinen Knecht? Denn was habe ich getan, und was für Böses ist in meiner Hand?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Und nun höre doch mein Herr, der König, auf die Worte seines Knechtes: Wenn Jehova dich wider mich aufgereizt hat, so möge er ein Speisopfer riechen; wenn aber Menschenkinder, so seien sie verflucht vor Jehova, weil sie mich heute vertrieben haben, daß ich mich dem Erbteil Jehovas nicht anschließen darf, indem sie sprechen: Gehe hin, diene anderen Göttern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'So möge nun mein Blut nicht zur Erde fallen fern von dem Angesicht Jehovas! Denn der König von Israel ist ausgezogen, einen Floh zu suchen, wie man einem Rebhuhn nachjagt auf den Bergen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Und Saul sprach: Ich habe gesündigt; kehre zurück, mein Sohn David! Denn ich will dir nichts Übles mehr tun, darum daß mein Leben an diesem Tage teuer gewesen ist in deinen Augen. Siehe, ich habe töricht gehandelt und gar sehr gefehlt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Und David antwortete und sprach: Siehe hier, der Speer des Königs; so komme einer von den Knaben herüber und hole ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Und Jehova wird einem jeden seine Gerechtigkeit und seine Treue vergelten; denn Jehova hatte dich heute in meine Hand gegeben, und ich wollte meine Hand nicht ausstrecken gegen den Gesalbten Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Und siehe, wie deine Seele an diesem Tage hochgeachtet gewesen ist in meinen Augen, also möge meine Seele hochgeachtet sein in den Augen Jehovas, und er möge mich erretten aus aller Bedrängnis!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Und Saul sprach zu David: Gesegnet seiest du, mein Sohn David! Du wirst es sicher ausrichten und wirst sicher obsiegen. Und David ging seines Weges, Saul aber kehrte zurück an seinen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Und David sprach in seinem Herzen: Nun werde ich eines Tages durch die Hand Sauls umkommen; mir ist nichts besser, als daß ich eilends in das Land der Philister entrinne, und Saul wird von mir ablassen, mich ferner in allen Grenzen Israels zu suchen; und ich werde aus seiner Hand entrinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Und David machte sich auf und ging hinüber, er und sechshundert Mann, die bei ihm waren, zu Achis, dem Sohne Maoks, dem König von Gath.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Und David blieb bei Achis, zu Gath, er und seine Männer, ein jeder mit seinem Hause: David und seine beiden Weiber, Achinoam, die Jisreelitin, und Abigail, das Weib Nabals, die Karmelitin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Und es wurde Saul berichtet, daß David nach Gath geflohen wäre; und er suchte ihn fortan nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Und David sprach zu Achis: Wenn ich anders Gnade in deinen Augen gefunden habe, so gebe man mir einen Platz in einer der Städte des Gefildes, daß ich daselbst wohne; denn warum soll dein Knecht bei dir in der Königsstadt wohnen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Und Achis gab ihm an selbigem Tage Ziklag; darum hat Ziklag den Königen von Juda gehört bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Und die Zahl der Tage, welche David im Gefilde der Philister wohnte, war ein Jahr und vier Monate.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Und David zog mit seinen Männern hinauf, und sie fielen ein bei den Gesuritern und den Girsitern und den Amalekitern; denn diese waren die Bewohner des Landes von alters her, bis nach Sur hin und bis zum Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Und David schlug das Land und ließ weder Mann noch Weib am Leben; und er nahm Kleinvieh und Rinder und Esel und Kamele und Kleider, und kehrte zurück und kam zu Achis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Und sprach Achis: Habt ihr heute keinen Einfall gemacht? so sprach David: In den Süden von Juda, oder: In den Süden der Jerachmeeliter! oder: In den Süden der Keniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Und David ließ weder Mann noch Weib am Leben, um sie nach Gath zu bringen, indem er sagte: Daß sie nicht über uns berichten und sprechen: So hat David getan. Und so war seine Weise alle die Tage, die er im Gefilde der Philister wohnte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Und Achis glaubte David und sprach: Er hat sich bei seinem Volke, bei Israel, ganz stinkend gemacht, und er wird mir zum Knechte sein ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Und es geschah in jenen Tagen, da versammelten die Philister ihre Heere zum Kriege, um wider Israel zu streiten. Und Achis sprach zu David: Wisse bestimmt, daß du mit mir ins Lager ausziehen sollst, du und deine Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Und David sprach zu Achis: So sollst du denn auch erfahren, was dein Knecht tun wird. Und Achis sprach zu David: So will ich dich denn zum Hüter meines Hauptes setzen alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, '(Samuel aber war gestorben, und ganz Israel hatte um ihn geklagt und ihn zu Rama, in seiner Stadt, begraben. Und Saul hatte die Totenbeschwörer und die Wahrsager aus dem Lande weggeschafft.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Und die Philister versammelten sich, und sie kamen und lagerten sich zu Sunem. Und Saul versammelte ganz Israel, und sie lagerten sich auf dem Gilboa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Und als Saul das Heer der Philister sah, fürchtete er sich, und sein Herz zitterte sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Und Saul befragte Jehova; aber Jehova antwortete ihm nicht, weder durch Träume, noch durch die Urim, noch durch die Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Da sprach Saul zu seinen Knechten: Suchet mir ein Weib, das einen Totenbeschwörergeist hat, damit ich zu ihr gehe und sie befrage. Und seine Knechte sprachen zu ihm: Siehe, zu Endor ist ein Weib, das einen Totenbeschwörergeist hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Und Saul verstellte sich und zog andere Kleider an, und ging hin, er und zwei Männer mit ihm, und sie kamen zu dem Weibe bei der Nacht; und er sprach: Wahrsage mir doch durch den Totenbeschwörergeist und bringe mir herauf, wen ich dir sagen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Aber das Weib sprach zu ihm: Siehe, du weißt ja, was Saul getan hat, daß er die Totenbeschwörer und die Wahrsager aus dem Lande ausgerottet hat; und warum legst du meiner Seele eine Schlinge, um mich zu töten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Und Saul schwur ihr bei Jehova und sprach: So wahr Jehova lebt, wenn dich eine Schuld treffen soll wegen dieser Sache!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Da sprach das Weib: Wen soll ich dir heraufbringen? Und er sprach: Bringe mir Samuel herauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Und als das Weib Samuel sah, da schrie sie mit lauter Stimme; und das Weib sprach zu Saul und sagte: Warum hast du mich betrogen? Du bist ja Saul!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Und der König sprach zu ihr: Fürchte dich nicht! Doch was siehst du? Und das Weib sprach zu Saul: Ich sehe einen Gott aus der Erde heraufsteigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Und er sprach zu ihr: Wie ist seine Gestalt? Und sie sprach: Ein alter Mann steigt herauf, und er ist in ein Oberkleid gehüllt. Da erkannte Saul, daß es Samuel war, und er neigte sich, das Antlitz zur Erde, und beugte sich nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Und Samuel sprach zu Saul: Warum hast du mich beunruhigt, mich heraufkommen zu lassen? Und Saul sprach: Ich bin in großer Not; denn die Philister streiten wider mich, und Gott ist von mir gewichen und antwortet mir nicht mehr, weder durch die Propheten, noch durch Träume; da ließ ich dich rufen, damit du mir kundtuest, was ich tun soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Und Samuel sprach: Warum doch fragst du mich, da Jehova von dir gewichen und dein Feind geworden ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Und Jehova hat für sich getan, so wie er durch mich geredet hat; und Jehova hat das Königtum aus deiner Hand gerissen und es deinem Nächsten, dem David, gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Weil du der Stimme Jehovas nicht gehorcht und seine Zornglut nicht ausgeführt hast an Amalek, darum hat Jehova dir dieses heute getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Und Jehova wird auch Israel mit dir in die Hand der Philister geben; und morgen wirst du mit deinen Söhnen bei mir sein; auch das Heerlager Israels wird Jehova in die Hand der Philister geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Da fiel Saul plötzlich seiner Länge nach zur Erde, und er fürchtete sich sehr vor den Worten Samuels; auch war keine Kraft in ihm, denn er hatte nichts gegessen den ganzen Tag und die ganze Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Und das Weib trat zu Saul und sah, daß er sehr bestürzt war; und sie sprach zu ihm: Siehe, deine Magd hat auf deine Stimme gehört, und ich habe mein Leben aufs Spiel gesetzt und deinen Worten gehorcht, die du zu mir geredet hast;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'und nun höre doch auch du auf die Stimme deiner Magd, und laß mich dir einen Bissen Brot vorsetzen, und iß, daß Kraft in dir sei, wenn du deines Weges gehst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Aber er weigerte sich und sprach: Ich will nicht essen. Da drangen seine Knechte und auch das Weib in ihn; und er hörte auf ihre Stimme und stand von der Erde auf und setzte sich auf das Bett.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Und das Weib hatte ein gemästetes Kalb im Hause; und sie eilte und schlachtete es; und sie nahm Mehl und knetete es und backte daraus ungesäuerte Kuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Und sie brachte es herzu vor Saul und vor seine Knechte, und sie aßen. Und sie machten sich auf und gingen fort in selbiger Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Und die Philister versammelten alle ihre Heere nach Aphek; und Israel war an der Quelle gelagert, die bei Jisreel ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Und die Fürsten der Philister zogen vorüber nach Hunderten und nach Tausenden, und David und seine Männer zogen zuletzt mit Achis vorüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Da sprachen die Fürsten der Philister: Was sollen diese Hebräer? Und Achis sprach zu den Fürsten der Philister: Ist das nicht David, der Knecht Sauls, des Königs von Israel, der schon seit Jahr und Tag bei mir gewesen ist? Und ich habe gar nichts an ihm gefunden von dem Tage an, da er abgefallen ist, bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Aber die Fürsten der Philister wurden zornig über ihn, und die Fürsten der Philister sprachen zu ihm: Schicke den Mann zurück, daß er an seinen Ort zurückkehre, wohin du ihn bestellt hast, und daß er nicht mit uns in den Streit hinabziehe und uns nicht zum Widersacher werde im Streite; denn womit könnte der sich angenehm machen bei seinem Herrn? Nicht mit den Köpfen dieser Männer?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Ist das nicht David, von dem sie in den Reigen sangen und sprachen: \"Saul hat seine Tausende erschlagen, und David seine Zehntausende\"?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Und Achis rief David und sprach zu ihm: So wahr Jehova lebt, du bist redlich; und wohlgefällig in meinen Augen ist dein Ausgang und dein Eingang bei mir im Heerlager; denn ich habe nichts Böses an dir gefunden von dem Tage an, da du zu mir gekommen bist, bis auf diesen Tag; aber in den Augen der Fürsten bist du nicht wohlgefällig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Und nun kehre zurück und gehe hin in Frieden, damit du nichts Übles tuest in den Augen der Fürsten der Philister.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Und David sprach zu Achis: Aber was habe ich getan, und was hast du an diesem Knechte gefunden von dem Tage an, da ich vor dir gewesen bin bis auf diesen Tag, daß ich nicht kommen und wider die Feinde meines Herrn, des Königs, streiten soll?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Und Achis antwortete und sprach zu David: Ich weiß es, denn du bist wohlgefällig in meinen Augen wie ein Engel Gottes; doch die Fürsten der Philister haben gesagt: Er soll nicht mit uns in den Streit hinaufziehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'So mache dich nun des Morgens früh auf, du und die Knechte deines Herrn, die mit dir gekommen sind; und machet euch des Morgens früh auf! Sobald es euch hell wird, ziehet fort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Und David machte sich früh auf, er und seine Männer, daß sie am Morgen fortzögen, um in das Land der Philister zurückzukehren. Die Philister aber zogen nach Jisreel hinauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Und es geschah, als David und seine Männer am dritten Tage nach Ziklag kamen, da waren die Amalekiter in den Süden und in Ziklag eingefallen; und sie hatten Ziklag geschlagen und es mit Feuer verbrannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Und sie hatten die Weiber und alle, die darin waren, gefangen weggeführt, vom Kleinsten bis zum Größten; sie hatten niemand getötet, sondern sie hatten sie weggetrieben und waren ihres Weges gezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Und David und seine Männer kamen zu der Stadt; und siehe, sie war mit Feuer verbrannt, und ihre Weiber und ihre Söhne und ihre Töchter waren gefangen weggeführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Da erhoben David und das Volk, das bei ihm war, ihre Stimme, und sie weinten, bis keine Kraft mehr in ihnen war zu weinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Und auch die beiden Weiber Davids waren gefangen weggeführt, Achinoam, die Jisreelitin, und Abigail, das Weib Nabals, des Karmeliters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Und David war in großer Bedrängnis, denn das Volk sprach davon, ihn zu steinigen; denn die Seele des ganzen Volkes war erbittert, ein jeder um seine Söhne und um seine Töchter. Aber David stärkte sich in Jehova, seinem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Und David sprach zu Abjathar, dem Priester, dem Sohne Ahimelechs: Bringe mir doch das Ephod her! Und Abjathar brachte das Ephod zu David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Und David befragte Jehova und sprach: Soll ich dieser Schar nachjagen? Werde ich sie erreichen? Und er sprach zu ihm: Jage nach, denn du wirst sie gewißlich erreichen und wirst gewißlich erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Da zog David hin, er und die sechshundert Mann, die bei ihm waren; und sie kamen an den Bach Besor, wo die Zurückbleibenden stehen blieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Und David jagte nach, er und vierhundert Mann; denn zweihundert Mann blieben stehen, welche zu ermattet waren, um über den Bach Besor zu gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Und sie fanden einen ägyptischen Mann auf dem Felde und brachten ihn zu David; und sie gaben ihm Brot, und er aß, und sie tränkten ihn mit Wasser;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'und sie gaben ihm eine Schnitte Feigenkuchen und zwei Rosinenkuchen, und er aß; und sein Geist kam ihm wieder, denn er hatte drei Tage und drei Nächte kein Brot gegessen und kein Wasser getrunken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Und David sprach zu ihm: Wem gehörst du? Und woher bist du? Und er sprach: Ich bin ein ägyptischer Jüngling, der Knecht eines amalekitischen Mannes; und mein Herr hat mich verlassen, denn ich wurde heute vor drei Tagen krank.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Wir sind eingefallen in den Süden der Kerethiter und in das, was Juda gehört und in den Süden von Kaleb, und wir haben Ziklag mit Feuer verbrannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Und David sprach zu ihm: Willst du mich zu dieser Schar hinabführen? Und er sprach: Schwöre mir bei Gott, daß du mich nicht töten noch mich der Hand meines Herrn ausliefern willst, so will ich dich zu dieser Schar hinabführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Und er führte ihn hinab; und siehe, sie waren über die Fläche des ganzen Landes zerstreut, essend und trinkend und tanzend wegen all der großen Beute, die sie aus dem Lande der Philister und aus dem Lande Juda genommen hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Und David schlug sie von der Dämmerung an bis zum Abend des folgenden Tages; und keiner von ihnen entrann, außer vierhundert jungen Männern, welche auf Kamele stiegen und entflohen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Und David rettete alles, was die Amalekiter genommen hatten, und David rettete auch seine beiden Weiber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Und es fehlte ihnen nichts, vom Kleinsten bis zum Größten, und bis zu den Söhnen und den Töchtern, und von der Beute bis zu allem, was sie ihnen genommen hatten; alles brachte David zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Und David nahm alles Klein-und Rindvieh; sie trieben es vor dem anderen Vieh her und sprachen: Dies ist die Beute Davids!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Und David kam zu den zweihundert Männern, die zu ermattet gewesen waren, um David nachzufolgen, und die sie am Bache Besor zurückgelassen hatten; und sie zogen aus, David und dem Volke entgegen, das bei ihm war; und David trat zu dem Volke und fragte sie nach ihrem Wohlergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Und jeder böse und nichtswürdige Mann von den Männern, die mit David gezogen waren, hob an und sprach: Darum daß sie nicht mit uns gezogen sind, wollen wir ihnen von der Beute, die wir entrissen haben, nichts geben, als nur einem jeden sein Weib und seine Kinder, daß sie sie wegführen und hingehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Aber David sprach: Tut nicht also, meine Brüder, mit dem, was Jehova uns gegeben hat; und er hat uns behütet und die Schar, die über uns gekommen war, in unsere Hand gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Und wer wird in dieser Sache auf euch hören? Denn wie das Teil dessen, der in den Streit hinabzieht, so soll auch das Teil dessen sein, der bei dem Geräte bleibt: gemeinsam sollen sie teilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Und so geschah es von jenem Tage an und hinfort; und er machte es zur Satzung und zum Recht für Israel bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Und David kam nach Ziklag; und er sandte von der Beute den Ältesten Judas, seinen Freunden, und sprach: Siehe, da habt ihr ein Geschenk von der Beute der Feinde Jehovas:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'denen zu Bethel und denen zu Ramoth im Süden und denen zu Jattir,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'und denen zu Aroer und denen zu Siphmoth und denen zu Estemoa,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'und denen zu Rakal und denen in den Städten der Jerachmeeliter und denen in den Städten der Keniter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'und denen zu Horma und denen zu Bor-Aschan und denen zu Athak,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'und denen zu Hebron, und nach allen Orten, wo David umhergezogen war, er und seine Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Die Philister aber stritten wider Israel; und die Männer von Israel flohen vor den Philistern, und Erschlagene fielen auf dem Gebirge Gilboa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Und die Philister setzten Saul und seinen Söhnen hart nach; und die Philister erschlugen Jonathan und Abinadab und Malkischua, die Söhne Sauls.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Und der Streit wurde heftig wider Saul, und es erreichten ihn die Schützen, Männer mit dem Bogen; und es wurde ihm sehr angst vor den Schützen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Da sprach Saul zu seinem Waffenträger: Ziehe dein Schwert und durchbohre mich damit, daß nicht diese Unbeschnittenen kommen und mich durchbohren und mich mißhandeln! Sein Waffenträger aber wollte nicht, denn er fürchtete sich sehr. Da nahm Saul das Schwert und stürzte sich darein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Und als sein Waffenträger sah, daß Saul tot war, da stürzte auch er sich in sein Schwert und starb mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'So starben Saul und seine drei Söhne und sein Waffenträger, auch alle seine Männer an selbigem Tage zugleich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Und als die Männer von Israel, die diesseit des Tales und diesseit des Jordan waren, sahen, daß die Männer von Israel geflohen, und daß Saul und seine Söhne tot waren, da verließen sie die Städte und flohen; und die Philister kamen und wohnten darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Und es geschah am folgenden Tage, da kamen die Philister, um die Erschlagenen auszuziehen; und sie fanden Saul und seine drei Söhne auf dem Gebirge Gilboa liegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Und sie hieben ihm den Kopf ab und zogen ihm seine Waffen aus; und sie sandten in das Land der Philister ringsumher, um die frohe Botschaft in den Häusern ihrer Götzen und unter dem Volke zu verkünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Und sie legten seine Waffen in das Haus der Astaroth, und seinen Leichnam hefteten sie an die Mauer von Beth-Schan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Als aber die Bewohner von Jabes-Gilead über ihn hörten, was die Philister mit Saul getan hatten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'da machten sich alle tapferen Männer auf und gingen die ganze Nacht; und sie nahmen den Leichnam Sauls und die Leichname seiner Söhne von der Mauer von Beth-Schan weg; und sie kamen nach Jabes zurück und verbrannten sie daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Und sie nahmen ihre Gebeine und begruben sie unter der Tamariske zu Jabes, und fasteten sieben Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Und es geschah nach dem Tode Sauls, als David von der Schlacht der Amalekiter zurückgekommen war, da blieb David zwei Tage zu Ziklag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Und es geschah am dritten Tage, siehe, da kam ein Mann aus dem Heerlager Sauls, seine Kleider waren zerrissen, und Erde war auf seinem Haupte; und als er zu David kam, fiel er zur Erde und warf sich nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Und David sprach zu ihm: Woher kommst du? Und er sprach zu ihm: Ich bin aus dem Heerlager Israels entronnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Und David sprach zu ihm: Wie steht die Sache? Berichte mir doch. Und er sagte: Das Volk ist aus dem Streit geflohen, und auch viele von dem Volke sind gefallen und gestorben, und auch Saul und sein Sohn Jonathan sind tot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Und David sprach zu dem Jüngling, der ihm berichtete: Wie weißt du, daß Saul und sein Sohn Jonathan tot sind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Und der Jüngling, der ihm berichtete, sprach: Ich geriet zufällig auf das Gebirge Gilboa, und siehe, Saul lehnte sich auf seinen Speer; und siehe, die Wagen und die Reiter setzten ihm hart nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Und er wandte sich um und sah mich und rief mir zu, und ich sprach: Hier bin ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Und er sprach zu mir: Wer bist du? Und ich sprach zu ihm: Ich bin ein Amalekiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Und er sprach zu mir: Tritt doch her zu mir und töte mich, denn die Verwirrung hat mich ergriffen; denn mein Leben ist noch ganz in mir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Da trat ich zu ihm hin und tötete ihn, denn ich wußte, daß er seinen Fall nicht überleben würde. Und ich nahm das Diadem, das auf seinem Haupte, und die Armspange, die an seinem Arme war, und habe sie zu meinem Herrn hierher gebracht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Da faßte David seine Kleider und zerriß sie; und alle Männer, die bei ihm waren, taten ebenso.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Und sie klagten und weinten und fasteten bis an den Abend um Saul und um seinen Sohn Jonathan und um das Volk Jehovas und um das Haus Israel, weil sie durchs Schwert gefallen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Und David sprach zu dem Jüngling, der ihm berichtete: Woher bist du? Und er sprach: Ich bin der Sohn eines amalekitischen Fremdlings.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Und David sprach zu ihm: Wie hast du dich nicht gefürchtet, deine Hand auszustrecken, um den Gesalbten Jehovas zu verderben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Und David rief einen von den Knaben und sprach: Tritt herzu, falle über ihn her! Und er erschlug ihn, und er starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Und David sprach zu ihm: Dein Blut komme auf dein Haupt! Denn dein Mund hat wider dich gezeugt und gesprochen: Ich habe den Gesalbten Jehovas getötet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Und David stimmte dieses Klagelied an über Saul und über Jonathan, seinen Sohn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'und er befahl, daß man die Kinder Juda das Lied von dem Bogen lehre; siehe, es ist geschrieben im Buche Jaschar:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Deine Zierde, Israel, ist erschlagen auf deinen Höhen! Wie sind die Helden gefallen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Berichtet es nicht zu Gath, verkündet die Botschaft nicht in den Straßen Askalons, daß sich nicht freuen die Töchter der Philister, daß nicht frohlocken die Töchter der Unbeschnittenen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Berge von Gilboa, nicht Tau noch Regen sei auf euch, noch Gefilde der Hebopfer! Denn dort ward weggeworfen der Schild der Helden, der Schild Sauls, nicht gesalbt mit Öl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Von dem Blute der Erschlagenen, von dem Fette der Helden wich Jonathans Bogen nicht zurück, und Sauls Schwert kehrte nicht leer wieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul und Jonathan, die Geliebten und Holdseligen in ihrem Leben, sind auch in ihrem Tode nicht getrennt; sie waren schneller als Adler, stärker als Löwen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Töchter Israels, weinet um Saul, der euch köstlich kleidete in Karmesin, der goldenen Schmuck zog über eure Kleider!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Wie sind die Helden gefallen mitten im Streit! Wie ist Jonathan erschlagen auf deinen Höhen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Mir ist wehe um dich, mein Bruder Jonathan! Holdselig warst du mir sehr; wunderbar war mir deine Liebe, mehr als Frauenliebe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Wie sind die Helden gefallen, und umgekommen die Rüstzeuge des Streites!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Und es geschah hernach, da befragte David Jehova und sprach: Soll ich in eine der Städte Judas hinaufziehen? Und Jehova sprach zu ihm: Ziehe hinauf. Und David sprach: Wohin soll ich hinaufziehen? Und er sprach: Nach Hebron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Und David zog dort hinauf, und auch seine zwei Weiber, Achinoam, die Jisreelitin, und Abigail, das Weib Nabals, des Karmeliters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Auch seine Männer, die bei ihm waren, ließ David hinaufziehen, einen jeden mit seinem Hause; und sie wohnten in den Städten Hebrons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Und die Männer von Juda kamen und salbten daselbst David zum König über das Haus Juda. Und man berichtete David und sprach: Die Männer von Jabes-Gilead sind es, die Saul begraben haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Da sandte David Boten zu den Männern von Jabes-Gilead und ließ ihnen sagen: Gesegnet seiet ihr von Jehova, daß ihr diese Güte an eurem Herrn, an Saul, erwiesen und ihn begraben habt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Und so erweise nun Jehova Güte und Treue an euch; und auch ich will euch dieses Gute vergelten, weil ihr diese Sache getan habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Und nun lasset eure Hände erstarken und seid wackere Männer; denn Saul, euer Herr, ist tot, und auch hat das Haus Juda mich zum König über sich gesalbt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Abner aber, der Sohn Ners, der Heeroberste Sauls, nahm Isboseth, den Sohn Sauls, und führte ihn hinüber nach Machanaim;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'und er machte ihn zum König über Gilead und über die Asuriter und über Jisreel, und über Ephraim und über Benjamin und über das ganze Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Vierzig Jahre war Isboseth, der Sohn Sauls, alt, als er König wurde über Israel, und er regierte zwei Jahre; nur das Haus Juda folgte David nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Und die Zahl der Tage, welche David in Hebron über das Haus Juda König war, betrug sieben Jahre und sechs Monate.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Und Abner, der Sohn Ners, und die Knechte Isboseths, des Sohnes Sauls, zogen aus von Machanaim nach Gibeon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'und auch Joab, der Sohn der Zeruja, und die Knechte Davids zogen aus; und sie stießen bei dem Teiche von Gibeon aufeinander. Und diese ließen sich nieder auf dieser Seite des Teiches, und jene auf jener Seite des Teiches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Da sprach Abner zu Joab: Laß doch die Jünglinge sich aufmachen und vor uns spielen! Und Joab sprach: Sie mögen sich aufmachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Und sie machten sich auf und gingen hinüber, nach der Zahl: zwölf für Benjamin und für Isboseth, den Sohn Sauls, und zwölf von den Knechten Davids.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Und sie ergriffen einer den anderen beim Kopfe, und jeder stieß sein Schwert dem anderen in die Seite, und sie fielen zusammen. Und man nannte selbigen Ort Helkath-Hazzurim, der bei Gibeon ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Und der Streit wurde überaus heftig an jenem Tage; und Abner und die Männer von Israel wurden vor den Knechten Davids geschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Und es waren daselbst drei Söhne der Zeruja: Joab und Abisai und Asael. Asael aber war schnell auf seinen Füßen, wie eine der Gazellen, die auf dem Felde sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Und Asael jagte Abner nach und bog nicht aus, weder zur Rechten noch zur Linken hinter Abner weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Da wandte sich Abner um und sprach: Bist du es, Asael? Und er sprach: Ich bin\'s.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Da sprach Abner zu ihm: Biege aus zu deiner Rechten oder zu deiner Linken, und greife dir einen von den Jünglingen und nimm dir seine Rüstung! Aber Asael wollte nicht hinter ihm weg weichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Da sprach Abner nochmals zu Asael: Weiche hinter mir weg! Warum soll ich dich zu Boden schlagen? Und wie könnte ich mein Angesicht erheben zu deinem Bruder Joab?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Aber er weigerte sich zu weichen. Da schlug ihn Abner mit dem hinteren Ende des Speeres in den Bauch, daß der Speer hinten herausfuhr; und er fiel daselbst und starb an seiner Stelle. Und es geschah, jeder, der an den Ort kam, wo Asael gefallen und gestorben war, der blieb stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Und Joab und Abisai jagten Abner nach; und die Sonne ging unter, als sie zum Hügel Amma kamen, der vor Giach liegt, auf dem Wege zur Wüste Gibeon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Und die Kinder Benjamin sammelten sich hinter Abner her und wurden zu einem Haufen, und sie stellten sich auf den Gipfel eines Hügels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Und Abner rief Joab zu und sprach: Soll das Schwert immerfort fressen? Weißt du nicht, daß zuletzt Erbitterung sein wird? Und wie lange willst du nicht dem Volke sagen, von der Verfolgung ihrer Brüder umzukehren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Da sprach Joab: So wahr Gott lebt, wenn du nicht geredet hättest, dann wäre schon seit dem Morgen das Volk weggezogen, ein jeder von der Verfolgung seines Bruders!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Und Joab stieß in die Posaune; da blieb alles Volk stehen, und sie jagten Israel nicht mehr nach und fuhren nicht mehr fort zu streiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Und Abner und seine Männer zogen durch die Ebene jene ganze Nacht, und sie setzten über den Jordan und durchzogen das ganze Bitron und kamen nach Machanaim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Joab aber kehrte um von der Verfolgung Abners und versammelte das ganze Volk; da wurden von den Knechten Davids neunzehn Mann vermißt und Asael.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Die Knechte Davids aber hatten von Benjamin und unter den Männern Abners viele erschlagen; dreihundertsechzig Mann waren tot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Und sie hoben Asael auf und begruben ihn in dem Begräbnis seines Vaters, das zu Bethlehem war. Und Joab und seine Männer gingen die ganze Nacht, und das Licht brach ihnen an zu Hebron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Und der Streit war lang zwischen dem Hause Sauls und dem Hause Davids; David aber wurde immerfort stärker, während das Haus Sauls immerfort schwächer wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Und es wurden dem David Söhne in Hebron geboren: Sein Erstgeborener war Amnon, von Achinoam, der Jisreelitin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'und sein zweiter Kileab, von Abigail, dem Weibe Nabals, des Karmeliters; und der dritte Absalom, der Sohn Maakas, der Tochter Talmais, des Königs von Gesur;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'und der vierte Adonija, der Sohn Haggiths; und der fünfte Schephatja, der Sohn Abitals;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'und der sechste Jithream, von Egla, dem Weibe Davids. Diese wurden dem David in Hebron geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Und es geschah, während der Streit war zwischen dem Hause Sauls und dem Hause Davids, da stand Abner dem Hause Sauls mutig bei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Und Saul hatte ein Kebsweib, ihr Name war Rizpa, die Tochter Ajas. Und Isboseth sprach zu Abner: Warum bist du zu dem Kebsweibe meines Vaters eingegangen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Da ergrimmte Abner sehr über die Worte Isboseths und sprach: Bin ich ein Hundskopf, der es mit Juda hält? Heute erweise ich Güte an dem Hause deines Vaters Saul, an seinen Brüdern und an seinen Freunden, und ich habe dich nicht in die Hand Davids überliefert; und du wirfst mir heute das Vergehen mit diesem Weibe vor?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'So möge Gott Abner tun und so ihm hinzufügen, wenn ich nicht, wie Jehova dem David geschworen hat, ihm also tun werde:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'das Königtum von dem Hause Sauls abzuwenden und den Thron Davids aufzurichten über Israel und über Juda, von Dan bis Beerseba!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Und er konnte Abner kein Wort mehr erwidern, weil er ihn fürchtete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Und Abner sandte Boten für sich zu David und sprach: Wessen ist das Land? Und er sprach: Mache einen Bund mit mir; und siehe, meine Hand wird mit dir sein, um ganz Israel dir zuzuwenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Und David sprach: Gut, ich will einen Bund mit dir machen; nur eine Sache fordere ich von dir, nämlich: Du sollst mein Angesicht nicht sehen, du bringest denn zuvor Michal, die Tochter Sauls, wenn du kommst, um mein Angesicht zu sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Und David sandte Boten zu Isboseth, dem Sohne Sauls, und ließ ihm sagen: Gib mir Michal, mein Weib, die ich mir verlobt habe um hundert Vorhäute der Philister.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Da sandte Isboseth hin und ließ sie holen von ihrem Manne, von Paltiel, dem Sohne des Lais.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Und ihr Mann ging mit ihr und folgte ihr weinend nach bis Bachurim. Da sprach Abner zu ihm: Geh, kehre um! Und er kehrte um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Und Abner hatte sich mit den Ältesten Israels unterredet und gesagt: Früher schon habt ihr David zum König über euch begehrt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'so handelt nun; denn Jehova hat von David geredet und gesagt: Durch die Hand Davids, meines Knechtes, will ich mein Volk Israel erretten aus der Hand der Philister und aus der Hand aller seiner Feinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Und Abner redete auch zu den Ohren Benjamins. Und Abner ging auch hin, um zu den Ohren Davids in Hebron alles zu reden, was gut war in den Augen Israels und in den Augen des ganzen Hauses Benjamin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Als nun Abner, und zwanzig Männer mit ihm, zu David nach Hebron kamen, machte David Abner und den Männern, die mit ihm waren, ein Mahl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Und Abner sprach zu David: Ich will mich aufmachen und hingehen, und ganz Israel zu meinem Herrn, dem König, versammeln, daß sie einen Bund mit dir machen, und du über alles regierst, was deine Seele begehrt. Und David entließ Abner, und er ging hin in Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Und siehe, die Knechte Davids und Joab kamen von einem Streifzuge und brachten große Beute mit sich. Abner war aber nicht mehr bei David zu Hebron; denn er hatte ihn entlassen, und er war hingegangen in Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Als nun Joab und das ganze Heer, das mit ihm war, ankamen, da berichtete man Joab und sprach: Abner, der Sohn Ners, ist zum König gekommen; und er hat ihn entlassen, und er ist hingegangen in Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Da kam Joab zum König und sprach: Was hast du getan! Siehe, Abner ist zu dir gekommen; warum doch hast du ihn entlassen, daß er ungehindert weggegangen ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Du kennst Abner, den Sohn Ners, daß er gekommen ist, um dich zu bereden, und um deinen Ausgang und deinen Eingang zu wissen, und alles zu wissen, was du tust.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Und Joab ging von David hinaus und sandte Boten hinter Abner her; und sie holten ihn zurück von der Zisterne Sira; David aber wußte es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Als nun Abner nach Hebron zurückkam, führte ihn Joab beiseite in das Tor, um in der Stille mit ihm zu reden; und er schlug ihn daselbst in den Bauch, daß er starb, wegen des Blutes seines Bruders Asael.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Und David hörte es hernach und sprach: Schuldlos bin ich und mein Königreich vor Jehova ewiglich an dem Blute Abners, des Sohnes Ners!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Es komme über das Haupt Joabs und über das ganze Haus seines Vaters; und nie soll im Hause Joabs fehlen der Flüssige und der Aussätzige und der sich am Stabe stützt und der durchs Schwert fällt und dem es an Brot mangelt! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'So haben Joab und Abisai, sein Bruder, Abner ermordet, weil er ihren Bruder Asael zu Gibeon im Streit getötet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Und David sprach zu Joab und zu allem Volke, das mit ihm war: Zerreißet eure Kleider und umgürtet euch mit Sacktuch, und klaget vor Abner her! Und der König David ging hinter der Bahre her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Und sie begruben Abner zu Hebron; und der König erhob seine Stimme und weinte am Grabe Abners, und das ganze Volk weinte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Und der König stimmte ein Klagelied an über Abner und sprach: Mußte, wie ein Tor stirbt, Abner sterben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Deine Hände waren nicht gebunden, und nicht in eherne Fesseln gelegt deine Füße. Wie man fällt vor Söhnen der Ungerechtigkeit, so bist du gefallen! Da weinte alles Volk noch mehr über ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Und alles Volk kam, um David zu bewegen, daß er Brot esse, während es noch Tag war. Aber David schwur und sprach: So soll mir Gott tun und so hinzufügen, wenn ich vor Untergang der Sonne Brot oder irgend etwas koste!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Und alles Volk nahm es wahr; und es war gut in ihren Augen, wie alles, was der König tat, gut war in den Augen des ganzen Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Und das ganze Volk und ganz Israel erkannten an jenem Tage, daß es nicht von dem König ausgegangen war, Abner, den Sohn Ners, zu töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Und der König sprach zu seinen Knechten: Wisset ihr nicht, daß an diesem Tage ein Oberster und Großer in Israel gefallen ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Ich aber bin heute schwach, obschon zum König gesalbt; und diese Männer, die Söhne der Zeruja, sind zu hart für mich. Jehova vergelte dem, der das Böse tut, nach seiner Bosheit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Und als der Sohn Sauls hörte, daß Abner zu Hebron gestorben war, da wurden seine Hände schlaff, und ganz Israel war bestürzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Und zwei Männer waren Oberste der Scharen des Sohnes Sauls, der Name des einen war Baana, und der Name des anderen Rekab, Söhne Rimmons, des Beerothiters, von den Kindern Benjamin. Denn auch Beeroth wird zu Benjamin gerechnet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'aber die Beerothiter entflohen nach Gittaim und haben sich dort als Fremdlinge aufgehalten bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Und Jonathan, der Sohn Sauls, hatte einen Sohn, der an den Füßen lahm war. Er war fünf Jahre alt, als die Nachricht von Saul und Jonathan aus Jisreel kam; da nahm seine Amme ihn auf und floh. Und es geschah, als sie ängstlich floh, daß er fiel und lahm wurde; und sein Name war Mephiboseth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Und die Söhne Rimmons, des Beerothiters, Rekab und Baana, gingen hin und kamen um die Hitze des Tages in das Haus Isboseths, während er seine Mittagsruhe hielt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Und sie kamen dahin, bis in das Innere des Hauses, als wollten sie Weizen holen, und sie schlugen ihn in den Bauch. Und Rekab und sein Bruder Baana entrannen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Sie kamen in das Haus, während er in seinem Schlafgemach auf seinem Bette lag, und sie schlugen ihn und töteten ihn und hieben ihm den Kopf ab; und sie nahmen seinen Kopf und gingen den Weg der Ebene die ganze Nacht hindurch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Und sie brachten den Kopf Isboseths zu David nach Hebron und sprachen zu dem König: Siehe da, der Kopf Isboseths, des Sohnes Sauls, deines Feindes, der nach deinem Leben trachtete; und so hat Jehova meinem Herrn, dem König, an diesem Tage Rache verliehen an Saul und an seinem Samen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Da antwortete David Rekab und Baana, seinem Bruder, den Söhnen Rimmons, des Beerothiters, und sprach zu ihnen: So wahr Jehova lebt, der meine Seele erlöst hat aus aller Bedrängnis, den, der mir berichtete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Siehe, Saul ist tot! und der in seinen Augen ein guter Bote war, den ergriff ich und tötete ihn zu Ziklag, um ihm so Botenlohn zu geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'wieviel mehr, da gottlose Männer einen gerechten Mann in seinem Hause auf seiner Lagerstätte ermordet haben, sollte ich jetzt nicht sein Blut von eurer Hand fordern und euch wegschaffen von der Erde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Und David gebot seinen Knechten, und sie erschlugen sie und hieben ihnen die Hände und die Füße ab, und hängten sie auf am Teiche zu Hebron; das Haupt Isboseths aber nahmen sie und begruben es in dem Begräbnis Abners zu Hebron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Und alle Stämme Israels kamen zu David nach Hebron, und sie sprachen und sagten: Siehe, wir sind dein Gebein und dein Fleisch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Schon früher, als Saul König über uns war, bist du es gewesen, der Israel aus-und einführte; und Jehova hat zu dir gesagt: Du sollst mein Volk Israel weiden, und du sollst Fürst sein über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Und alle Ältesten Israels kamen zu dem König nach Hebron, und der König David machte einen Bund mit ihnen zu Hebron, vor Jehova; und sie salbten David zum König über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Dreißig Jahre war David alt, als er König wurde; er regierte vierzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Zu Hebron regierte er sieben Jahre und sechs Monate über Juda, und zu Jerusalem regierte er dreiunddreißig Jahre über ganz Israel und Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Und der König zog mit seinen Männern nach Jerusalem wider die Jebusiter, die Bewohner des Landes. Und sie sprachen zu David und sagten: Du wirst nicht hier hereinkommen, sondern die Blinden und die Lahmen werden dich wegtreiben; sie wollten damit sagen: David wird nicht hier hereinkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Aber David nahm die Burg Zion ein, das ist die Stadt Davids.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Und David sprach an selbigem Tage: Wer die Jebusiter schlägt und an die Wasserleitung gelangt, und die Lahmen und die Blinden schlägt, welche der Seele Davids verhaßt sind...!Daher spricht man: Ein Blinder und ein Lahmer darf nicht ins Haus kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Und David wohnte in der Burg, und er nannte sie Stadt Davids. Und David baute ringsum, von dem Millo an einwärts. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Und David wurde immerfort größer, und Jehova, der Gott der Heerscharen, war mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Und Hiram, der König von Tyrus, sandte Boten zu David, und Zedernholz und Zimmerleute und Mauerleute; und sie bauten David ein Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Und David erkannte, daß Jehova ihn zum König über Israel bestätigt, und daß er sein Königreich erhoben hatte um seines Volkes Israel willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Und David nahm noch Kebsweiber und Weiber aus Jerusalem, nachdem er von Hebron gekommen war; und es wurden David noch Söhne und Töchter geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Und dies sind die Namen der ihm in Jerusalem Geborenen: Schammua und Schobab und Nathan und Salomo,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'und Jibschar und Elischua und Nepheg und Japhija,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'und Elischama und Eljada und Eliphelet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Und als die Philister hörten, daß man David zum König über Israel gesalbt hatte, da zogen alle Philister herauf, um David zu suchen. Und David hörte es und zog in die Burg hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Und die Philister kamen und breiteten sich aus im Tale Rephaim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Und David befragte Jehova und sprach: Soll ich wider die Philister hinaufziehen? Wirst du sie in meine Hand geben? Und Jehova sprach zu David: Ziehe hinauf, denn ich werde die Philister gewißlich in deine Hand geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Da kam David nach Baal-Perazim. Und David schlug sie daselbst, und er sprach: Jehova hat meine Feinde vor mir durchbrochen, gleich einem Wasserdurchbruch. Daher gab er jenem Orte den Namen Baal-Perazim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Und sie ließen daselbst ihre Götzen, und David und seine Männer nahmen sie weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Und die Philister zogen wiederum herauf und breiteten sich aus im Tale Rephaim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Und David befragte Jehova; und er sprach: Du sollst nicht hinaufziehen; wende dich ihnen in den Rücken, daß du an sie kommst den Bakabäumen gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Und sobald du das Geräusch eines Daherschreitens in den Wipfeln der Bakabäume hörst, alsdann beeile dich; denn alsdann ist Jehova vor dir ausgezogen, um das Heer der Philister zu schlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'Und David tat also, wie Jehova ihm geboten hatte; und er schlug die Philister von Geba, bis man nach Geser kommt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Und David versammelte wiederum alle Auserlesenen in Israel, dreißigtausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Und David machte sich auf und zog hin, und alles Volk, das bei ihm war, nach Baale-Juda, um von dannen die Lade Gottes heraufzubringen, welche nach dem Namen, dem Namen Jehovas der Heerscharen, der zwischen den Cherubim thront, genannt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Und sie stellten die Lade Gottes auf einen neuen Wagen, und brachten sie aus dem Hause Abinadabs weg, das auf dem Hügel war; und Ussa und Achjo, die Söhne Abinadabs, führten den neuen Wagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Und sie brachten sie aus dem Hause Abinadabs weg, das auf dem Hügel war, indem sie die Lade Gottes begleiteten; und Achjo ging vor der Lade her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Und David und das ganze Haus Israel spielten vor Jehova mit allerlei Instrumenten von Zypressenholz, und mit Lauten und mit Harfen und mit Tamburinen und mit Sistren und mit Zimbeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Und als sie zur Tenne Nakons kamen, da langte Ussa nach der Lade Gottes und faßte sie an, denn die Rinder hatten sich losgerissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Da entbrannte der Zorn Jehovas wider Ussa, und Gott schlug ihn daselbst wegen des Vergehens; und er starb daselbst bei der Lade Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Und David entbrannte darüber, daß Jehova einen Bruch an Ussa gemacht hatte; und er nannte jenen Ort Perez-Ussa, bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Und David fürchtete sich vor Jehova an selbigem Tage und sprach: Wie soll die Lade Jehovas zu mir kommen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Und David wollte die Lade Jehovas nicht zu sich einkehren lassen in die Stadt Davids; und David ließ sie beiseite bringen in das Haus Obed Edoms, des Gathiters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Und die Lade Jehovas blieb in dem Hause Obed-Edoms, des Gathiters, drei Monate. Und Jehova segnete Obed-Edom und sein ganzes Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Und es wurde dem König David berichtet und gesagt: Jehova hat das Haus Obed-Edoms und alles, was sein ist, gesegnet um der Lade Gottes willen. Da ging David hin und holte die Lade Gottes aus dem Hause Obed-Edoms herauf in die Stadt Davids mit Freuden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Und es geschah, wenn die Träger der Lade Jehovas sechs Schritte gegangen waren, so opferte er ein Rind und ein Mastvieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Und David tanzte mit aller Kraft vor Jehova, und David war mit einem leinenen Ephod umgürtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Und David und das ganze Haus Israel brachten die Lade Jehovas hinauf mit Jauchzen und mit Posaunenschall.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Und es geschah, als die Lade Jehovas in die Stadt Davids kam, da schaute Michal, die Tochter Sauls, durchs Fenster; und sie sah den König David vor Jehova hüpfen und tanzen, und sie verachtete ihn in ihrem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Und sie brachten die Lade Jehovas hinein und stellten sie an ihren Ort innerhalb des Zeltes, das David für sie aufgeschlagen hatte. Und David opferte Brandopfer und Friedensopfer vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Und als David das Opfern der Brandopfer und der Friedensopfer beendigt hatte, segnete er das Volk im Namen Jehovas der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Und er verteilte an das ganze Volk, an die ganze Menge Israels, vom Manne bis zum Weibe, an einen jeden einen Brotkuchen und einen Trunk Wein und einen Rosinenkuchen. Und das ganze Volk ging hin, ein jeder nach seinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Und als David zurückkehrte, um sein Haus zu segnen, ging Michal, die Tochter Sauls, hinaus, David entgegen, und sprach: Wie hat der König von Israel sich heute verherrlicht, da er sich heute vor den Augen der Mägde seiner Knechte entblößt hat, wie sich nur einer der losen Leute entblößt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Da sprach David zu Michal: Vor Jehova, der mich vor deinem Vater und vor seinem ganzen Hause erwählt hat, um mich als Fürst zu bestellen über das Volk Jehovas, über Israel, ja, vor Jehova will ich spielen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'und ich will noch geringer werden denn also, und will niedrig sein in meinen Augen; aber bei den Mägden, von denen du sprichst, bei ihnen werde ich geehrt sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Michal aber die Tochter Sauls, hatte kein Kind bis zum Tage ihres Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Und es geschah, als der König in seinem Hause wohnte, und Jehova ihm ringsumher Ruhe geschafft hatte vor allen seinen Feinden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'da sprach der König zu Nathan, dem Propheten: Siehe doch, ich wohne in einem Hause von Zedern, und die Lade Gottes wohnt unter Teppichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Und Nathan sprach zu dem König: Gehe hin, tue alles, was du im Herzen hast, denn Jehova ist mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Und es geschah in selbiger Nacht, da geschah das Wort Jehovas zu Nathan also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Gehe hin und sprich zu meinem Knechte, zu David: So spricht Jehova: Solltest du mir ein Haus bauen zu meiner Wohnung?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Denn ich habe nicht in einem Hause gewohnt von dem Tage an, da ich die Kinder Israel aus Ägypten heraufgeführt habe, bis auf diesen Tag; sondern ich wanderte umher in einem Zelte und in einer Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Wo immer ich wanderte unter allen Kindern Israel, habe ich wohl zu einem der Stämme Israels, dem ich gebot, mein Volk Israel zu weiden, ein Wort geredet und gesagt: Warum habt ihr mir nicht ein Haus von Zedern gebaut?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Und nun sollst du also zu meinem Knechte David sagen: So spricht Jehova der Heerscharen: Ich habe dich von der Trift genommen, hinter dem Kleinvieh weg, daß du Fürst sein solltest über mein Volk, über Israel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'und ich bin mit dir gewesen überall, wohin du gezogen bist, und habe alle deine Feinde vor dir ausgerottet; und ich habe dir einen großen Namen gemacht, gleich dem Namen der Großen, die auf Erden sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Und ich werde einen Ort setzen für mein Volk, für Israel, und werde es pflanzen, daß es an seiner Stätte wohne und nicht mehr beunruhigt werde, und die Söhne der Ungerechtigkeit sollen es nicht mehr bedrücken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'wie früher und seit dem Tage, da ich Richter über mein Volk Israel bestellt habe. Und ich habe dir Ruhe geschafft vor allen deinen Feinden; und Jehova tut dir kund, daß Jehova dir ein Haus machen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Wenn deine Tage voll sein werden, und du bei deinen Vätern liegen wirst, so werde ich deinen Samen nach dir erwecken, der aus deinem Leibe kommen soll, und werde sein Königtum befestigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Der wird meinem Namen ein Haus bauen; und ich werde den Thron seines Königtums befestigen auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Ich will ihm Vater sein, und er soll mir Sohn sein, so daß, wenn er verkehrt handelt, ich ihn züchtigen werde mit einer Menschenrute und mit Schlägen der Menschenkinder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'aber meine Güte soll nicht von ihm weichen, wie ich sie von Saul weichen ließ, den ich vor dir weggetan habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Und dein Haus und dein Königtum sollen vor dir beständig sein auf ewig, dein Thron soll fest sein auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Nach allen diesen Worten und nach diesem ganzen Gesicht, also redete Nathan zu David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Da ging der König David hinein und setzte sich vor Jehova nieder und sprach: Wer bin ich, Herr, Jehova, und was ist mein Haus, daß du mich bis hierher gebracht hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Und dies ist noch ein Geringes gewesen in deinen Augen, Herr, Jehova! Und du hast auch von dem Hause deines Knechtes geredet in die Ferne hin; und ist dies die Weise des Menschen, Herr, Jehova?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Doch was soll David noch weiter zu dir reden? Du kennst ja deinen Knecht, Herr, Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Um deines Wortes willen und nach deinem Herzen hast du all dieses Große getan, um es deinem Knechte kundzutun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Darum bist du groß, Jehova Gott! Denn niemand ist dir gleich, und kein Gott außer dir, nach allem, was wir mit unseren Ohren gehört haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Und wer ist wie dein Volk, wie Israel, die einzige Nation auf Erden, welche Gott hingegangen ist, sich zum Volke zu erlösen, und um sich einen Namen zu machen, und für sie solch Großes zu tun und furchtbare Dinge für dein Land, indem du vor deinem Volke, das du dir aus Ägypten erlöst hast, Nationen und ihre Götter vertriebst!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Und du hast dir dein Volk Israel befestigt, dir zum Volke auf ewig; und du, Jehova, bist ihr Gott geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Und nun, Jehova Gott, das Wort, das du über deinen Knecht und über sein Haus geredet hast, halte aufrecht ewiglich, und tue, wie du geredet hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Und dein Name sei groß auf ewig, daß man spreche: Jehova der Heerscharen ist Gott über Israel. Und das Haus deines Knechtes David sei fest vor dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Denn du, Jehova der Heerscharen, Gott Israels, hast dem Ohre deines Knechtes eröffnet und gesagt: Ich werde dir ein Haus bauen; darum hat dein Knecht sich ein Herz gefaßt, dieses Gebet zu dir zu beten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Und nun, Herr, Jehova, du bist es, der da Gott ist, und deine Worte sind Wahrheit, und du hast dieses Gute zu deinem Knechte geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'So laß es dir nun gefallen und segne das Haus deines Knechtes, daß es ewiglich vor dir sei; denn du, Herr, Jehova, hast geredet, und so werde mit deinem Segen das Haus deines Knechtes gesegnet ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Und es geschah hernach, da schlug David die Philister und demütigte sie; und David nahm den Zaum der Hauptstadt aus der Hand der Philister.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Und er schlug die Moabiter und maß sie mit der Meßschnur, indem er sie auf die Erde legen ließ; und er maß zwei Meßschnüre ab, um zu töten, und eine volle Meßschnur, um am Leben zu lassen. Und die Moabiter wurden David zu Knechten, welche Geschenke brachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Und David schlug Hadadeser, den Sohn Rechobs, den König von Zoba, als er hinzog, um seine Macht am Strome wiederherzustellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Und David nahm von ihm tausendsiebenhundert Reiter und zwanzigtausend Mann Fußvolk gefangen; und David lähmte alle Gespanne und ließ hundert Gespanne von ihm übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Und die Syrer von Damaskus kamen, um Hadadeser, dem König von Zoba, zu helfen; und David erschlug unter den Syrern zweiundzwanzigtausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Und David legte Besatzungen in das damascenische Syrien; und die Syrer wurden David zu Knechten, welche Geschenke brachten. Und Jehova half David überall, wohin er zog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Und David nahm die goldenen Schilde, welche den Knechten Hadadesers gehörten, und brachte sie nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Und aus Betach und aus Berothai, den Städten Hadadesers, nahm der König David Erz in großer Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Und als Toi, der König von Hamath, hörte, daß David die ganze Heeresmacht Hadadesers geschlagen hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'da sandte Toi seinen Sohn Joram zu dem König David, um ihn nach seinem Wohlergehen zu fragen und ihn zu beglückwünschen, darum daß er wider Hadadeser gestritten und ihn geschlagen hatte; denn Hadadeser war stets im Kriege mit Toi; und in seiner Hand waren Geräte von Silber und Geräte von Gold und Geräte von Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Auch diese heiligte der König David dem Jehova, samt dem Silber und dem Golde, das er von all den Nationen geheiligt, die er unterjocht hatte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'von den Syrern und von den Moabitern und von den Kindern Ammon und von den Philistern und von den Amalekitern, und von der Beute Hadadesers, des Sohnes Rechobs, des Königs von Zoba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Und David machte sich einen Namen, als er zurückkam, nachdem er die Syrer im Salztal geschlagen hatte, achtzehntausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Und er legte Besatzungen in Edom, in ganz Edom legte er Besatzungen; und alle Edomiter wurden David zu Knechten. Und Jehova half David überall, wohin er zog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Und David regierte über ganz Israel; und David übte Recht und Gerechtigkeit an seinem ganzen Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Und Joab, der Sohn der Zeruja, war über das Heer; und Josaphat, der Sohn Ahiluds, war Geschichtsschreiber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'und Zadok, der Sohn Ahitubs, und Ahimelech, der Sohn Abjathars, waren Priester; und Seraja war Schreiber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'und Benaja, der Sohn Jojadas, war über die Kerethiter und die Pelethiter; und die Söhne Davids waren Krondiener.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Und David sprach: Ist noch jemand da, der vom Hause Sauls übriggeblieben ist, daß ich Güte an ihm erweise um Jonathans willen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Es war aber ein Knecht vom Hause Sauls, sein Name war Ziba; und sie riefen ihn zu David. Und der König sprach zu ihm: Bist du Ziba? Und er sprach: Dein Knecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Und der König sprach: Ist niemand mehr da vom Hause Sauls, daß ich Güte Gottes an ihm erweise? Und Ziba sprach zu dem König: Es ist noch ein Sohn da von Jonathan, der an den Füßen lahm ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Und der König sprach zu ihm: Wo ist er? Und Ziba sprach zu dem König: Siehe, er ist im Hause Makirs, des Sohnes Ammiels, zu Lodebar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Da sandte der König David hin und ließ ihn aus dem Hause Makirs, des Sohnes Ammiels, holen, von Lodebar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Und Mephiboseth, der Sohn Jonathans, des Sohnes Sauls, kam zu David; und er fiel auf sein Angesicht und beugte sich nieder. Und David sprach: Mephiboseth! Und er sprach: Siehe, dein Knecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Und David sprach zu ihm: Fürchte dich nicht; denn ich will gewißlich Güte an dir erweisen um deines Vaters Jonathan willen, und will dir alle Felder deines Vaters Saul zurückgeben; du aber sollst beständig an meinem Tische essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Und er beugte sich nieder und sprach: Was ist dein Knecht, daß du dich zu einem toten Hunde gewandt hast, wie ich einer bin?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Da rief der König Ziba, den Diener Sauls, und sprach zu ihm: Alles, was Saul und seinem ganzen Hause gehört hat, habe ich dem Sohne deines Herrn gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Und du sollst ihm das Land bauen, du und deine Söhne und deine Knechte, und den Ertrag einbringen, damit der Sohn deines Herrn Brot zu essen habe. Und Mephiboseth, der Sohn deines Herrn, soll beständig an meinem Tische essen. Und Ziba hatte fünfzehn Söhne und zwanzig Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Und Ziba sprach zu dem König: Nach allem, was mein Herr, der König, seinem Knechte gebietet, also wird dein Knecht tun. Und Mephiboseth, sprach der König, wird an meinem Tische essen, wie einer von den Königssöhnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Und Mephiboseth hatte einen kleinen Sohn, sein Name war Micha. Und alle, die im Hause Zibas wohnten, waren Mephiboseths Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Und Mephiboseth wohnte in Jerusalem, denn er aß beständig am Tische des Königs. Er war aber lahm an beiden Füßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Und es geschah hernach, da starb der König der Kinder Ammon; und Hanun, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Und David sprach: Ich will Güte erweisen an Hanun, dem Sohne Nahas\', so wie sein Vater Güte an mir erwiesen hat. Und David sandte hin, um ihn durch seine Knechte wegen seines Vaters zu trösten. Und die Knechte Davids kamen in das Land der Kinder Ammon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Da sprachen die Fürsten der Kinder Ammon zu Hanun, ihrem Herrn: Ehrt wohl David deinen Vater in deinen Augen, daß er Tröster zu dir gesandt hat? Hat nicht David seine Knechte zu dir gesandt, um die Stadt zu erforschen und sie auszukundschafte und sie umzukehren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Da nahm Hanun die Knechte Davids und ließ ihnen die Hälfte des Bartes abscheren und ihre Oberkleider zur Hälfte abschneiden, bis an ihre Gesäße; und er entließ sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Und man berichtete es dem David. Da sandte er ihnen entgegen, denn die Männer schämten sich sehr; und der König ließ ihnen sagen: Bleibet in Jericho, bis euer Bart gewachsen ist, dann kommet zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Als nun die Kinder Ammon sahen, daß sie sich bei David stinkend gemacht hatten, da sandten die Kinder Ammon hin und dingten die Syrer von Beth-Rechob und die Syrer von Zoba, zwanzigtausend Mann zu Fuß, und den König von Maaka, tausend Mann, und die Männer von Tob, zwölftausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Und als David es hörte, sandte er Joab hin und das ganze Heer, die Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Und die Kinder Ammon zogen aus und stellten sich am Eingang des Tores in Schlachtordnung auf; und die Syrer von Zoba und Rechob und die Männer von Tob und Maaka waren für sich auf dem Felde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Und als Joab sah, daß der Streit von vorn und von hinten gegen ihn gerichtet war, da erwählte er von allen Auserlesenen Israels und stellte sich auf, den Syrern gegenüber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'und das übrige Volk übergab er der Hand seines Bruders Abisai, und dieser stellte sich auf, den Kindern Ammon gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Und er sprach: Wenn die Syrer mir zu stark sind, so sollst du mir Hilfe leisten; und wenn die Kinder Ammon dir zu stark sind, so will ich kommen, dir zu helfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Sei stark und laß uns stark sein für unser Volk und für die Städte unseres Gottes! Und Jehova wird tun, was gut ist in seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Da rückte Joab und das Volk, das bei ihm war, vor zum Streit wider die Syrer; und sie flohen vor ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Und als die Kinder Ammon sahen, daß die Syrer geflohen waren, da flohen auch sie vor Abisai und zogen sich in die Stadt zurück. Und Joab kehrte von den Kindern Ammon zurück und kam nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Und als die Syrer sahen, daß sie vor Israel geschlagen waren, da versammelten sie sich allesamt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Und Hadareser sandte hin und ließ die Syrer ausziehen, die jenseit des Stromes waren; und sie kamen nach Helam, und Schobak, der Heeroberste Hadaresers, vor ihnen her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Und es wurde David berichtet; da versammelte er ganz Israel und ging über den Jordan und kam nach Helam; und die Syrer stellten sich David gegenüber auf und stritten mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Und die Syrer flohen vor Israel, und David tötete von den Syrern siebenhundert Wagenkämpfer und vierzigtausend Reiter; und er erschlug Schobak, ihren Heerobersten, und er starb daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Und als alle die Könige, welche Knechte Hadaresers waren, sahen, daß sie vor Israel geschlagen waren, da machten sie Frieden mit Israel und dienten ihnen. Und die Syrer fürchteten sich, den Kindern Ammon fernerhin zu helfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Und es geschah bei der Rückkehr des Jahres, zur Zeit, wann die Könige ausziehen, da sandte David Joab und seine Knechte mit ihm und ganz Israel; und sie richteten die Kinder Ammon zu Grunde und belagerten Rabba. David aber blieb in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Und es geschah zur Abendzeit, als David von seinem Lager aufstand und auf dem Dache des Hauses des Königs wandelte, daß er von dem Dache herab ein Weib sich baden sah; und das Weib war sehr schön von Ansehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Und David sandte hin und erkundigte sich nach dem Weibe; und man sprach: Ist das nicht Bathseba, die Tochter Eliams, das Weib Urijas, des Hethiters?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Und David sandte Boten hin und ließ sie holen; und sie kam zu ihm, und er lag bei ihr (sie hatte sich aber gereinigt von ihrer Unreinigkeit); und sie kehrte in ihr Haus zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Und das Weib wurde schwanger; und sie sandte hin und berichtete es David und sprach: Ich bin schwanger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Da entbot David dem Joab: Sende mir Urija, den Hethiter. Und Joab sandte Urija zu David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Und Urija kam zu ihm; und David fragte nach dem Wohlergehen Joabs und nach dem Wohlergehen des Volkes und nach dem Stande des Streites.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Und David sprach zu Urija: Gehe in dein Haus hinab und wasche deine Füße. Und als Urija aus dem Hause des Königs ging, kam ein Geschenk des Königs hinter ihm her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Und Urija legte sich am Eingang des Hauses des Königs nieder bei allen Knechten seines Herrn, und ging nicht in sein Haus hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Und man berichtete es David und sprach: Urija ist nicht in sein Haus hinabgegangen. Da sprach David zu Urija: Bist du nicht von der Reise gekommen? Warum bist du nicht in dein Haus hinabgegangen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Und Urija sprach zu David: Die Lade und Israel und Juda weilen in Hütten, und mein Herr Joab und die Knechte meines Herrn lagern auf freiem Felde, und ich sollte in mein Haus gehen, um zu essen und zu trinken und bei meinem Weibe zu liegen? So wahr du lebst und deine Seele lebt, wenn ich dieses tue!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Da sprach David zu Urija: Bleibe auch heute noch hier, und morgen werde ich dich entlassen. So blieb Urija an jenem Tage und am folgenden in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Und David lud ihn, und er aß und trank vor ihm, und er machte ihn trunken. Und am Abend ging er hinaus, um sich auf sein Lager niederzulegen bei den Knechten seines Herrn; aber in sein Haus ging er nicht hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Und es geschah am Morgen, da schrieb David einen Brief an Joab und sandte ihn durch Urija.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Und er schrieb in dem Briefe also: Stellet Urija voran, wo der Streit am stärksten ist, und ziehet euch hinter ihm zurück, daß er erschlagen werde und sterbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Und es geschah, als Joab die Stadt einschloß, da stellte er Urija an den Ort, von dem er wußte, daß tapfere Männer daselbst waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Und die Männer der Stadt zogen heraus und stritten wider Joab, und es fielen etliche von dem Volke, von den Knechten Davids; und auch Urija, der Hethiter, starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Da sandte Joab hin und berichtete David alle Begebenheiten des Streites.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Und er befahl dem Boten und sprach: Wenn du geendigt hast, alle Begebenheiten des Streites dem König zu melden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'so geschehe es, wenn der Grimm des Königs aufsteigt, und er zu dir spricht: Warum habt ihr euch der Stadt genähert, um zu streiten? Wußtet ihr nicht, daß sie von der Mauer herab schießen würden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Wer hat Abimelech, den Sohn Jerubbeseths, erschlagen? Warf nicht ein Weib den oberen Stein einer Handmühle von der Mauer auf ihn herab, daß er starb zu Tebez? Warum habt ihr euch der Mauer genähert? so sollst du sagen: Auch dein Knecht Urija, der Hethiter, ist tot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Und der Bote ging hin; und er kam und berichtete David alles, wozu Joab ihn gesandt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Und der Bote sprach zu David: Da die Männer die Oberhand über uns hatten und gegen uns aufs Feld herauszogen, so drangen wir auf sie ein bis zum Eingang des Tores.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Da schossen die Schützen von der Mauer herab auf deine Knechte, und es starben etliche von den Knechten des Königs; und auch dein Knecht Urija, der Hethiter, ist tot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Da sprach David zu dem Boten: So sollst du zu Joab sagen: Laß diese Sache nicht übel sein in deinen Augen, denn das Schwert frißt bald so, bald so; verstärke deinen Streit gegen die Stadt und zerstöre sie! So ermutige ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Und als das Weib Urijas hörte, daß Urija, ihr Mann, tot war, klagte sie um ihren Gatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Als aber die Trauer vorüber war, sandte David hin und nahm sie in sein Haus; und sie wurde sein Weib und gebar ihm einen Sohn. Aber die Sache, die David getan hatte, war übel in den Augen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Und Jehova sandte Nathan zu David; und er kam zu ihm und sprach zu ihm: Zwei Männer waren in einer Stadt, der eine reich, und der andere arm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Der Reiche hatte Kleinvieh und Rinder in großer Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Der Arme hatte aber gar nichts, als nur ein einziges kleines Lamm, das er gekauft hatte; und er nährte es, und es wurde groß bei ihm, und mit seinen Kindern zugleich; es aß von seinem Bissen und trank aus seinem Becher und schlief an seinem Busen, und es war ihm wie eine Tochter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Da kam ein Reisender zu dem reichen Manne; und es dauerte ihn, von seinem Kleinvieh und von seinen Rindern zu nehmen, um es für den Wanderer zuzurichten, der zu ihm gekommen war, und er nahm das Lamm des armen Mannes und richtete es zu für den Mann, der zu ihm gekommen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Da entbrannte der Zorn Davids sehr wider den Mann, und er sprach zu Nathan: So wahr Jehova lebt, der Mann, der dieses getan hat, ist ein Kind des Todes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'und das Lamm soll er vierfältig erstatten, darum daß er diese Sache getan, und weil er kein Mitleid gehabt hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Da sprach Nathan zu David: Du bist der Mann! So spricht Jehova, der Gott Israels: Ich habe dich zum König über Israel gesalbt, und ich habe dich aus der Hand Sauls errettet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'und ich habe dir das Haus deines Herrn gegeben und die Weiber deines Herrn in deinen Schoß, und habe dir das Haus Israel und Juda gegeben; und wenn es zu wenig war, so hätte ich dir noch dies und das hinzugefügt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Warum hast du das Wort Jehovas verachtet, indem du tatest, was übel ist in seinen Augen? Urija, den Hethiter, hast du mit dem Schwerte erschlagen, und sein Weib hast du dir zum Weibe genommen; ihn selbst hast du ja umgebracht durch das Schwert der Kinder Ammon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Nun denn, so soll von deinem Hause das Schwert nicht weichen ewiglich, darum daß du mich verachtet und das Weib Urijas, des Hethiters, genommen hast, daß sie dir zum Weibe sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'So spricht Jehova: Siehe, ich will aus deinem Hause Unglück über dich erwecken, und ich will deine Weiber vor deinen Augen nehmen und sie deinem Nächsten geben, daß er bei deinen Weibern liege vor den Augen dieser Sonne!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Denn du, du hast es im Verborgenen getan; ich aber, ich werde dieses tun vor ganz Israel und vor der Sonne!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Da sprach David zu Nathan: Ich habe gegen Jehova gesündigt. Und Nathan sprach zu David: So hat auch Jehova deine Sünde hinweggetan, du wirst nicht sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Nur weil du den Feinden Jehovas durch diese Sache Anlaß zur Lästerung gegeben hast, so soll auch der Sohn, der dir geboren ist, gewißlich sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Und Nathan ging nach seinem Hause. Und Jehova schlug das Kind, welches das Weib Urijas dem David geboren hatte, und es wurde todkrank.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Und David suchte Gott um des Knaben willen; und David fastete und ging hinein und lag über Nacht auf der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Und die Ältesten seines Hauses machten sich zu ihm auf, um ihn von der Erde aufzurichten; aber er wollte nicht und aß kein Brot mit ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Und es geschah am siebten Tage, da starb das Kind. Und die Knechte Davids fürchteten sich, ihm zu berichten, daß das Kind tot sei; denn sie sprachen: Siehe, als das Kind noch am Leben war, haben wir zu ihm geredet, und er hat nicht auf unsere Stimme gehört; und wie sollen wir nun zu ihm sagen: Das Kind ist tot? Er würde etwas Übles tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Und David sah, daß seine Knechte sich zuflüsterten; da merkte David, daß das Kind tot war; und David sprach zu seinen Knechten: Ist das Kind tot? Und sie sprachen: Es ist tot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Da stand David von der Erde auf und wusch und salbte sich und wechselte seine Kleider, und ging in das Haus Jehovas und betete an; und er kam in sein Haus und forderte, daß man ihm Speise vorsetze, und er aß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Da sprachen seine Knechte zu ihm: Was ist das für ein Ding, das du tust? Als das Kind lebte, hast du um seinetwillen gefastet und geweint, und wie das Kind tot ist, stehst du auf und issest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Und er sprach: Als das Kind noch lebte, habe ich gefastet und geweint, weil ich dachte: Wer weiß, ob Jehova mir nicht gnädig sein wird, daß das Kind am Leben bleibt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Nun es aber tot ist, warum sollte ich denn fasten? Vermag ich es wieder zurückzubringen? Ich gehe zu ihm, aber es wird nicht zu mir zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Und David tröstete Bathseba, sein Weib, und ging zu ihr ein und lag bei ihr. Und sie gebar einen Sohn, und er gab ihm den Namen Salomo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Und Jehova liebte ihn. Und er sandte durch Nathan, den Propheten, und gab ihm den Namen Jedidjah, um Jehovas willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Und Joab stritt wider Rabba der Kinder Ammon, und er nahm die Königsstadt ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Und Joab sandte Boten zu David und ließ ihm sagen: Ich habe wider Rabba gestritten, habe auch die Wasserstadt eingenommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'und nun versammle das übrige Volk und belagere die Stadt und nimm sie ein, daß nicht ich die Stadt einnehme, und sie nach meinem Namen genannt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Da versammelte David alles Volk und zog nach Rabba, und er stritt wider dasselbe und nahm es ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Und er nahm die Krone ihres Königs von seinem Haupte; ihr Gewicht war ein Talent Gold, und Edelsteine waren daran; und sie kam auf das Haupt Davids. Und die Beute der Stadt brachte er hinaus in großer Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Und das Volk, das darin war, führte er hinaus und legte es unter die Säge und unter eiserne Dreschwagen und unter eiserne Beile, und ließ sie durch einen Ziegelofen gehen. Und also tat er allen Städten der Kinder Ammon. Und David und das ganze Volk kehrten nach Jerusalem zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Und es geschah danach: Absalom, der Sohn Davids, hatte eine schöne Schwester, ihr Name war Tamar; und Amnon, der Sohn Davids, liebte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Und es war dem Amnon wehe zum Krankwerden um seiner Schwester Tamar willen; denn sie war eine Jungfrau, und es war in den Augen Amnons unmöglich, ihr das Geringste zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Und Amnon hatte einen Freund, sein Name war Jonadab, der Sohn Schimeas, des Bruders Davids; und Jonadab war ein sehr kluger Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Und er sprach zu ihm: Warum bist du so abgezehrt, Königssohn, Morgen für Morgen? Willst du es mir nicht kundtun? Und Amnon sprach zu ihm: Ich liebe Tamar, die Schwester meines Bruders Absalom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Und Jonadab sprach zu ihm: Lege dich auf dein Lager und stelle dich krank; und kommt dein Vater, um dich zu sehen, so sprich zu ihm: Laß doch meine Schwester Tamar kommen und mir Speise zu essen geben, und vor meinen Augen das Essen zubereiten, damit ich zusehe und aus ihrer Hand esse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Und Amnon legte sich und stellte sich krank. Und als der König kam, um ihn zu sehen, da sprach Amnon zu dem König: Laß doch meine Schwester Tamar kommen und vor meinen Augen zwei Kuchen bereiten, daß ich aus ihrer Hand esse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Da sandte David zu Tamar ins Haus und ließ ihr sagen: Gehe doch in das Haus deines Bruders Amnon und bereite ihm das Essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Und Tamar ging in das Haus ihres Bruders Amnon; er lag aber zu Bette. Und sie nahm den Teig und knetete ihn, und bereitete Kuchen vor seinen Augen und backte die Kuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Und sie nahm die Pfanne und schüttete sie vor ihm aus. Aber er weigerte sich zu essen. Und Amnon sprach: Laßt jedermann von mir hinausgehen! Und jedermann ging von ihm hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Da sprach Amnon zu Tamar: Bringe das Essen in das innere Gemach, daß ich von deiner Hand esse. Und Tamar nahm die Kuchen, die sie zubereitet hatte, und brachte sie ihrem Bruder Amnon in das innere Gemach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Und als sie ihm zu essen hinreichte, da ergriff er sie und sprach zu ihr: Komm, liege bei mir, meine Schwester!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Und sie sprach zu ihm: Nicht doch, mein Bruder! Schwäche mich nicht, denn also tut man nicht in Israel; begehe nicht diese Schandtat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Und ich, wohin sollte ich meinen Schimpf tragen? Und du, du würdest sein wie einer der Schändlichen in Israel. Und nun rede doch zum König, denn er wird mich dir nicht verweigern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Er wollte aber nicht auf ihre Stimme hören; und er überwältigte sie und schwächte sie und beschlief sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Und Amnon haßte sie mit einem sehr großen Hasse; denn der Haß, womit er sie haßte, war größer als die Liebe, womit er sie geliebt hatte. Und Amnon sprach zu ihr: Stehe auf, gehe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Und sie sprach zu ihm: Es gibt keine Ursache zu diesem Übel, mich wegzutreiben, welches größer ist als das andere, das du mir angetan hast. Aber er wollte nicht auf sie hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Und er rief seinem Knaben, seinem Diener, und sprach: Treibet doch diese hinaus, von mir weg, und verriegele die Tür hinter ihr!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Sie trug aber ein langes Gewand; denn also waren die Töchter des Königs, die Jungfrauen, mit Gewändern bekleidet. Und sein Diener führte sie hinaus und verriegelte die Tür hinter ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Da nahm Tamar Asche auf ihr Haupt und zerriß das lange Gewand, das sie anhatte, und sie legte ihre Hand auf ihr Haupt und ging und schrie im Gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Und ihr Bruder Absalom sprach zu ihr: Ist dein Bruder Amnon bei dir gewesen? Nun denn, meine Schwester, schweige still; er ist dein Bruder, nimm dir diese Sache nicht zu Herzen! Da blieb Tamar, und zwar einsam, im Hause ihres Bruders Absalom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Und der König David hörte alle diese Dinge, und er wurde sehr zornig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Und Absalom redete mit Amnon weder Böses noch Gutes; denn Absalom haßte Amnon, darum daß er seine Schwester Tamar geschwächt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Und es geschah nach zwei vollen Jahren, da hatte Absalom Schafscherer zu Baal-Hazor, das bei Ephraim liegt; und Absalom lud alle Söhne des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Und Absalom kam zu dem König und sprach: Siehe doch, dein Knecht hat die Schafscherer; es gehe doch der König und seine Knechte mit deinem Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Aber der König sprach zu Absalom: Nicht doch, mein Sohn! Laß uns doch nicht allesamt gehen, daß wir dir nicht beschwerlich fallen. Und er drang in ihn; aber er wollte nicht gehen, und er segnete ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Da sprach Absalom: Wenn nicht, so laß doch meinen Bruder Amnon mit uns gehen! Und der König sprach zu ihm: Warum soll er mit dir gehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Absalom aber drang in ihn; da ließ er Amnon und alle Söhne des Königs mit ihm gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Und Absalom gebot seinen Knaben und sprach: Sehet doch zu, wenn Amnon fröhlichen Herzens wird vom Wein, und ich zu euch spreche: Erschlaget Amnon! so tötet ihn, fürchtet euch nicht! Bin ich es nicht, der es euch geboten hat? Seid stark und seid tapfer!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Und die Knaben Absaloms taten dem Amnon, so wie Absalom geboten hatte. Da standen alle Söhne des Königs auf und bestiegen ein jeder sein Maultier und flohen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Und es geschah, während sie auf dem Wege waren, da kam das Gerücht zu David, indem man sagte: Absalom hat alle Söhne des Königs erschlagen, und nicht einer von ihnen ist übriggeblieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Da stand der König auf und zerriß seine Kleider und legte sich auf die Erde; und alle seine Knechte standen da mit zerrissenen Kleidern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Da hob Jonadab, der Sohn Schimeas, des Bruders Davids, an und sprach: Mein Herr sage nicht: Sie haben alle die Jünglinge, die Söhne des Königs, getötet; denn Amnon allein ist tot; denn nach dem Beschluß Absaloms war es festgestellt von dem Tage an, da er seine Schwester Tamar geschwächt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Und nun nehme mein Herr, der König, die Sache nicht zu Herzen, daß er spreche: Alle Söhne des Königs sind tot; sondern Amnon allein ist tot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Und Absalom entfloh. Und der Knabe, der Wächter, erhob seine Augen und sah: Und siehe, viel Volks kam von dem Wege hinter ihm, von der Seite des Berges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Da sprach Jonadab zu dem König: Siehe, die Söhne des Königs kommen; wie dein Knecht gesagt hat, also ist es geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Und es geschah, sowie er ausgeredet hatte, siehe, da kamen die Söhne des Königs und erhoben ihre Stimme und weinten; und auch der König und alle seine Knechte brachen in ein sehr großes Weinen aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Absalom aber entfloh und ging zu Talmai, dem Sohne Ammihurs, dem König von Gesur. Und David trauerte um seinen Sohn alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Absalom aber entfloh und ging nach Gesur; und er war daselbst drei Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Und der König David sehnte sich, zu Absalom hinauszuziehen; denn er hatte sich über Amnon getröstet, daß er tot war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Und Joab, der Sohn der Zeruja, merkte, daß das Herz des Königs nach Absalom stand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Da sandte Joab nach Tekoa und ließ von dannen ein kluges Weib holen; und er sprach zu ihr: Stelle dich doch trauernd und ziehe Trauerkleider an und salbe dich nicht mit Öl, und sei wie ein Weib, das schon viele Tage über einen Toten trauert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'und gehe zum König hinein und rede zu ihm nach diesem Worte. Und Joab legte ihr die Worte in den Mund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Und das tekoitische Weib sprach zu dem König; und sie fiel auf ihr Antlitz zur Erde und beugte sich nieder und sprach: Hilf, o König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Und der König sprach zu ihr: Was ist dir? Und sie sprach: Fürwahr, ich bin eine Witwe, und mein Mann ist gestorben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Und deine Magd hatte zwei Söhne, und sie zankten sich beide auf dem Felde, und niemand war da, der rettend dazwischentrat; und der eine schlug den anderen und tötete ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Und siehe, das ganze Geschlecht ist wider deine Magd aufgestanden, und sie sprechen: Gib den heraus, der seinen Bruder erschlagen hat, daß wir ihn töten für die Seele seines Bruders, den er ermordet hat, und auch den Erben vertilgen! Und so wollen sie meine Kohle auslöschen, die mir übriggeblieben ist, um meinem Manne weder Namen noch Überrest auf dem Erdboden zu lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Da sprach der König zu dem Weibe: Gehe nach deinem Hause, und ich werde deinethalben gebieten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Und das tekoitische Weib sprach zu dem König: Auf mir, mein Herr König, und auf dem Hause meines Vaters sei die Ungerechtigkeit; der König aber und sein Thron seien schuldlos!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Und der König sprach: Wer wider dich redet, den bringe zu mir, und er soll dich fortan nicht mehr antasten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Und sie sprach: Der König gedenke doch Jehovas, deines Gottes, damit der Bluträcher nicht noch mehr Verderben anrichte, und sie meinen Sohn nicht vertilgen! Und er sprach: So wahr Jehova lebt, wenn von den Haaren deines Sohnes eines auf die Erde fällt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Und das Weib sprach: Laß doch deine Magd ein Wort zu meinem Herrn, dem König, reden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Und er sprach: Rede! Da sprach das Weib: Und warum hast du dergleichen wider Gottes Volk im Sinne? Denn da der König dieses Wort geredet hat, ist er wie schuldig, indem der König seinen Verstoßenen nicht zurückholen läßt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Denn wir müssen gewißlich sterben und sind wie Wasser, das auf die Erde geschüttet ist, welches man nicht wieder sammeln kann; und Gott nimmt nicht das Leben weg, sondern er sinnt darauf, daß der Verstoßene nicht von ihm weg verstoßen bleibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Und nun, daß ich gekommen bin, um dieses Wort zu dem König, meinem Herrn, zu reden, ist, weil das Volk mich in Furcht gesetzt hat. Da dachte deine Magd: Ich will doch zu dem König reden, vielleicht wird der König das Wort seiner Magd tun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'denn der König wird erhören, um seine Magd aus der Hand des Mannes zu erretten, der mich und meinen Sohn zusammen aus dem Erbteil Gottes vertilgen will.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Und deine Magd dachte: Das Wort meines Herrn, des Königs, möge doch zur Beruhigung sein; denn wie ein Engel Gottes, also ist mein Herr, der König, um das Gute und das Böse anzuhören; und Jehova, dein Gott, sei mit dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Da antwortete der König und sprach zu dem Weibe: Verhehle mir doch ja nichts, wonach ich dich fragen will! Und das Weib sprach: Es wolle doch mein Herr, der König, reden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Und der König sprach: Ist die Hand Joabs mit dir in diesem allem? Und das Weib antwortete und sprach: So wahr deine Seele lebt, mein Herr König, wenn zur Rechten oder zur Linken zu weichen ist von allem, was mein Herr, der König, redet! Denn dein Knecht Joab, er hat es mir geboten, und er hat deiner Magd alle diese Worte in den Mund gelegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Um das Ansehen der Sache zu wenden, hat dein Knecht Joab dieses getan; aber mein Herr ist weise, gleich der Weisheit eines Engels Gottes, daß er alles weiß, was auf Erden vorgeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Und der König sprach zu Joab: Siehe doch, ich habe dieses getan; so gehe hin, hole den Jüngling, den Absalom, zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Da fiel Joab auf sein Angesicht zur Erde und beugte sich nieder und segnete den König; und Joab sprach: Heute weiß dein Knecht, daß ich Gnade gefunden habe in deinen Augen, mein Herr König, da der König das Wort seines Knechtes getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Und Joab machte sich auf und ging nach Gesur, und er brachte Absalom nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Aber der König sprach: Er soll sich nach seinem Hause wenden und mein Angesicht nicht sehen. Und Absalom wandte sich nach seinem Hause und sah das Angesicht des Königs nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Und in ganz Israel war kein Mann wegen seiner Schönheit so sehr zu preisen wie Absalom; von seiner Fußsohle bis zu seinem Scheitel war kein Fehl an ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Und wenn er sein Haupt scheren ließ es geschah nämlich von Jahr zu Jahr, daß er es scheren ließ, denn es war ihm zu schwer, und so ließ er es scheren so wog sein Haupthaar zweihundert Sekel, nach dem Gewicht des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Und dem Absalom wurden drei Söhne geboren und eine Tochter, ihr Name war Tamar; sie war ein Weib, schön von Ansehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Und Absalom wohnte zu Jerusalem zwei volle Jahre; und er sah das Angesicht des Königs nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Da sandte Absalom zu Joab, um ihn zu dem König zu senden; aber er wollte nicht zu ihm kommen. Und er sandte wiederum zum zweiten Mal, aber er wollte nicht kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Da sprach er zu seinen Knechten: Sehet, das Ackerstück Joabs ist an meiner Seite, und er hat daselbst Gerste; gehet hin und zündet es mit Feuer an! Und die Knechte Absaloms zündeten das Ackerstück mit Feuer an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Da machte Joab sich auf und kam zu Absalom ins Haus, und sprach zu ihm: Warum haben deine Knechte mein Ackerstück mit Feuer angezündet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Und Absalom sprach zu Joab: Siehe, ich habe zu dir gesandt und dir sagen lassen: Komm her, daß ich dich zu dem König sende, um ihm zu sagen: Warum bin ich von Gesur gekommen? Besser wäre mir, ich wäre noch dort. Und nun möchte ich das Angesicht des Königs sehen; und wenn eine Ungerechtigkeit an mir ist, so töte er mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Da begab sich Joab zu dem König und berichtete es ihm. Und er rief Absalom; und er kam zu dem König und warf sich auf sein Antlitz zur Erde nieder vor dem König, und der König küßte Absalom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Und es geschah hernach, da schaffte sich Absalom Wagen und Rosse an, und fünfzig Mann, die vor ihm herliefen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Und Absalom machte sich früh auf und stellte sich an die Seite des Torweges; und es geschah: Jedermann, der einen Rechtsstreit hatte, um zu dem König zu Gericht zu kommen, dem rief Absalom zu und sprach: Aus welcher Stadt bist du? Und sprach er: Dein Knecht ist aus einem der Stämme Israels,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'so sprach Absalom zu ihm: Siehe, deine Sachen sind gut und recht; aber du hast von seiten des Königs niemand, der sie anhörte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Und Absalom sprach: Wer mich doch zum Richter setzte im Lande, daß jedermann zu mir käme, der einen Rechtsstreit und Rechtshandel hat, und ich würde ihm zu seinem Recht verhelfen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Und es geschah, wenn jemand ihm nahte, um sich vor ihm niederzubeugen, so streckte er seine Hand aus und ergriff ihn und küßte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Und Absalom tat auf solche Weise allen Israeliten, die zu dem König zu Gericht kamen; und so stahl Absalom das Herz der Männer von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Und es geschah am Ende von vierzig Jahren, da sprach Absalom zu dem König: Laß mich doch hingehen und zu Hebron mein Gelübde erfüllen, das ich Jehova gelobt habe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'denn als ich zu Gesur in Syrien wohnte, tat dein Knecht ein Gelübde und sprach: Wenn Jehova mich wirklich nach Jerusalem zurückbringt, so will ich Jehova dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Und der König sprach zu ihm: Gehe hin in Frieden! Und er machte sich auf und ging nach Hebron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Und Absalom sandte Kundschafter in alle Stämme Israels und ließ sagen: Sobald ihr den Schall der Posaune höret, so sprechet: Absalom ist König geworden zu Hebron!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Und mit Absalom gingen zweihundert Mann aus Jerusalem; sie waren geladen worden und gingen in ihrer Einfalt; und sie wußten um nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Und Absalom entbot Ahitophel, den Giloniter, den Rat Davids, aus seiner Stadt, aus Gilo, während er die Opfer schlachtete. Und die Verschwörung wurde stark, und das Volk mehrte sich fort und fort bei Absalom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Und es kam einer zu David, der ihm berichtete und sprach: Das Herz der Männer von Israel hat sich Absalom zugewandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Da sprach David zu allen seinen Knechten, die in Jerusalem bei ihm waren: Machet euch auf und laßt uns fliehen; denn sonst wird es kein Entrinnen für uns geben vor Absalom. Eilet, hinwegzugehen, daß er nicht eilends uns erreiche und das Unglück über uns treibe und die Stadt schlage mit der Schärfe des Schwertes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Und die Knechte des Königs sprachen zu dem König: Nach allem, was mein Herr, der König, zu tun erwählen wird, siehe hier, deine Knechte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Und der König zog hinaus, und sein ganzes Haus in seinem Gefolge; und der König ließ zehn Kebsweiber zurück, um das Haus zu bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'So zog der König hinaus, und alles Volk in seinem Gefolge, und sie machten Halt bei dem entfernten Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Und alle seine Knechte zogen an seiner Seite hinüber; und alle Kerethiter und alle Pelethiter, und alle Gathiter, sechshundert Mann, die in seinem Gefolge von Gath gekommen waren, zogen vor dem König hinüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Da sprach der König zu Ittai, dem Gathiter: Warum willst auch du mit uns gehen? Kehre um und bleibe bei dem König; denn du bist ein Fremder, und sogar in deinen Ort eingewandert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Gestern bist du gekommen, und heute sollte ich dich mit uns umherirren lassen? Ich aber gehe, wohin ich gehe. Kehre um und führe deine Brüder zurück; Güte und Wahrheit seien mit dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Aber Ittai antwortete dem König und sprach: So wahr Jehova lebt und mein Herr König lebt, an dem Orte, wo mein Herr, der König, sein wird, sei es zum Tode, sei es zum Leben, daselbst wird auch dein Knecht sein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Da sprach David zu Ittai: Komm und ziehe hinüber! Und Ittai, der Gathiter, zog hinüber mit allen seinen Männern und allen Kindern, die bei ihm waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Und das ganze Land weinte mit lauter Stimme, und alles Volk ging hinüber. Und der König ging über den Bach Kidron; und alles Volk zog hinüber nach dem Wege zur Wüste hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Und siehe, auch Zadok war da und alle Leviten mit ihm, die Lade des Bundes Gottes tragend; und sie stellten die Lade Gottes hin, und Abjathar ging hinauf, bis alles Volk aus der Stadt vollends hinübergegangen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Und der König sprach zu Zadok: Bringe die Lade Gottes in die Stadt zurück. Wenn ich Gnade finde in den Augen Jehovas, so wird er mich zurückbringen, und mich sie und seine Wohnung sehen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Wenn er aber also spricht: Ich habe kein Gefallen an dir hier bin ich, mag er mit mir tun, wie es gut ist in seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Und der König sprach zu Zadok, dem Priester: Bist du nicht der Seher? Kehre in die Stadt zurück in Frieden, und Achimaaz, dein Sohn, und Jonathan, der Sohn Abjathars, eure beiden Söhne, mit euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Sehet, ich will in den Ebenen der Wüste verziehen, bis ein Wort von euch kommt, mir Kunde zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Und Zadok und Abjathar brachten die Lade Gottes nach Jerusalem zurück, und sie blieben daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'David aber ging die Anhöhe der Olivenbäume hinauf und weinte, während er hinaufging; und sein Haupt war verhüllt, und er ging barfuß; und alles Volk, das bei ihm war, hatte ein jeder sein Haupt verhüllt und ging unter Weinen hinauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Und man berichtete David und sprach: Ahitophel ist unter den Verschworenen mit Absalom. Da sprach David: Betöre doch den Rat Antiophels, Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Und es geschah, als David auf den Gipfel gekommen war, wo er Gott anzubeten pflegte, siehe, da kam ihm Husai, der Arkiter, entgegen mit zerrissenem Leibrock und Erde auf seinem Haupte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Und David sprach zu ihm: Wenn du mit mir weiter gehst, so wirst du mir zur Last sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Wenn du aber in die Stadt zurückkehrst und zu Absalom sagst: Dein Knecht, o König, will ich sein; wie ich von jeher der Knecht deines Vaters gewesen bin, so will ich jetzt dein Knecht sein: so wirst du mir den Rat Ahitophels zunichte machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Und sind nicht Zadok und Abjathar, die Priester, dort bei dir? Und es soll geschehen, jede Sache, die du aus dem Hause des Königs hören wirst, sollst du Zadok und Abjathar, den Priestern, kundtun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Siehe, ihre beiden Söhne sind daselbst bei ihnen, Achimaaz, des Zadok, und Jonathan, des Abjathar Sohn; so entbietet mir durch sie jede Sache, die ihr hören werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Da begab sich Husai, der Freund Davids, in die Stadt; Absalom aber zog in Jerusalem ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Und als David von dem Gipfel ein wenig weiter gegangen war, siehe, da kam Ziba, der Knabe Mephiboseths, ihm entgegen mit einem Paar gesattelter Esel, und auf ihnen zweihundert Brote und hundert Rosinenkuchen und hundert Kuchen von getrocknetem Obst und ein Schlauch Wein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Und der König sprach zu Ziba: Was willst du damit? Und Ziba sprach: Die Esel sind für das Haus des Königs, um darauf zu reiten, und das Brot und das getrocknete Obst zum Essen für die Knaben, und der Wein zum Trinken für den, der in der Wüste ermattet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Und der König sprach: Und wo ist der Sohn deines Herrn? Und Ziba sprach zu dem König: Siehe, er bleibt in Jerusalem; denn er sprach: Heute wird mir das Haus Israel das Königtum meines Vaters wiedergeben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Da sprach der König zu Ziba: Siehe, dein ist alles, was Mephiboseth gehört. Und Ziba sprach: Ich beuge mich nieder; möge ich Gnade finden in deinen Augen, mein Herr König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Und als der König David nach Bachurim kam, siehe, da kam von dannen heraus ein Mann vom Geschlecht des Hauses Sauls, sein Name war Simei, der Sohn Geras. Er kam unter Fluchen heraus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'und warf mit Steinen nach David und nach allen Knechten des Königs David; und alles Volk und alle Helden waren zu seiner Rechten und zu seiner Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Und Simei sprach also, indem er fluchte: Hinweg, hinweg, du Mann des Blutes und Mann Belials!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Jehova hat alles Blut des Hauses Sauls, an dessen Statt du König geworden bist, auf dich zurückgebracht, und Jehova hat das Königtum in die Hand deines Sohnes Absalom gegeben; und siehe, nun bist du in deinem Unglück, denn ein Mann des Blutes bist du!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Und Abisai, der Sohn der Zeruja, sprach zu dem König: Warum soll dieser tote Hund meinem Herrn, dem König, fluchen? Laß mich doch hinübergehen und ihm den Kopf wegnehmen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Aber der König sprach: Was haben wir miteinander zu schaffen, ihr Söhne der Zeruja? Ja, mag er fluchen! Denn wenn Jehova ihm gesagt hat: Fluche David! Wer darf dann sagen: Warum tust du also?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Und David sprach zu Abisai und zu allen seinen Knechten: Siehe, mein Sohn, der aus meinem Leibe hervorgegangen ist, trachtet mir nach dem Leben; wieviel mehr nun dieser Benjaminiter! Laßt ihn, daß er fluche; denn Jehova hat es ihn geheißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Vielleicht wird Jehova mein Elend ansehen, und Jehova mir Gutes erstatten dafür, daß mir geflucht wird an diesem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Und David und seine Männer zogen auf dem Wege; Simei aber ging an der Seite des Berges, ihm gegenüber, immerfort fluchend, und warf mit Steinen gegen ihn und warf Staub empor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Und der König und alles Volk, das bei ihm war, kamen ermattet an; und er erholte sich daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Absalom aber und alles Volk, die Männer von Israel, kamen nach Jerusalem, und Ahitophel mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Und es geschah, als Husai, der Arkiter, der Freund Davids, zu Absalom kam, da sprach Husai zu Absalom: Es lebe der König! es lebe der König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Und Absalom sprach zu Husai: Ist das deine Güte an deinem Freunde? Warum bist du nicht mit deinem Freunde gegangen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Und Husai sprach zu Absalom: Nein, sondern wen Jehova erwählt hat und dieses Volk und alle Männer von Israel, dessen will ich sein, und bei ihm will ich bleiben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'und zum anderen, wem sollte ich dienen? Nicht vor seinem Sohne? Wie ich vor deinem Vater gedient habe, also will ich vor dir sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Und Absalom sprach zu Ahitophel: Schaffet Rat, was wir tun sollen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Und Ahitophel sprach zu Absalom: Gehe ein zu den Kebsweibern deines Vaters, die er zurückgelassen hat, um das Haus zu bewahren; so wird ganz Israel hören, daß du dich bei deinem Vater stinkend gemacht hast, und die Hände aller derer, die mit dir sind, werden erstarken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Da schlug man für Absalom ein Zelt auf dem Dache auf; und Absalom ging ein zu den Kebsweibern seines Vaters vor den Augen von ganz Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Der Rat Ahitophels aber, den er in jenen Tagen riet, war, wie wenn man das Wort Gottes befragte; also war jeder Rat Ahitophels, sowohl für David als auch für Absalom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Und Ahitophel sprach zu Absalom: Laß mich doch zwölftausend Mann auslesen, und mich aufmachen und diese Nacht David nachjagen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'und ich werde über ihn kommen, während er müde und an Händen schlaff ist, und ihn in Schrecken setzen; und alles Volk, das bei ihm ist, wird fliehen, und ich werde den König allein schlagen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'und so werde ich alles Volk zu dir zurückbringen. Gleich der Rückkehr aller ist der Mann, den du suchst: das ganze Volk wird in Frieden sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Und das Wort war recht in den Augen Absaloms und in den Augen aller Ältesten von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Und Absalom sprach: Rufe doch auch Husai, den Arkiter, daß wir hören, was auch er sagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Und Husai kam zu Absalom; und Absalom sprach zu ihm und sagte: Nach diesem Worte hat Ahitophel geredet; sollen wir sein Wort ausführen? Wenn nicht, so rede du!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Da sprach Husai zu Absalom: Nicht gut ist der Rat, den Ahitophel diesmal gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Und Husai sprach: Du kennst ja deinen Vater und seine Männer, daß die Helden, und daß sie erbitterten Gemütes sind, wie eine der Jungen beraubte Bärin auf dem Felde; und dein Vater ist ein Kriegsmann: er wird nicht bei dem Volke übernachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Siehe, er hat sich jetzt in irgend einer Schlucht oder sonst an einem Orte versteckt. Und es wird geschehen, wenn zu Anfang etliche unter ihnen fallen, so wird jeder, der es hört, sagen: Es hat eine Niederlage unter dem Volke stattgefunden, das Absalom nachfolgt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Und ist er auch ein tapferer Mann, dessen Herz wie ein Löwenherz ist, so wird er sicher verzagen; denn ganz Israel weiß, daß dein Vater ein Held ist, und die bei ihm sind tapfere Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Sondern ich rate: Es werde ganz Israel insgesamt zu dir versammelt, von Dan bis Beerseba, wie der Sand, der am Meere ist, an Menge; und deine Person ziehe mit ins Treffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Und wir werden über ihn kommen an einem der Orte, wo er sich befindet, und uns auf ihn niederlassen, wie der Tau auf den Erdboden fällt; und es wird von ihm und von all den Männern, die bei ihm sind, auch nicht einer übrigbleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Und wenn er sich in eine Stadt zurückzieht, so soll ganz Israel Seile an jene Stadt legen, und wir schleppen sie an den Fluß, bis dort auch nicht ein Steinchen mehr gefunden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Und Absalom und alle Männer von Israel sprachen: Der Rat Husais, des Arkiters, ist besser als der Rat Ahitophels. Aber Jehova hatte es so angeordnet, um den guten Rat Ahitophels zunichte zu machen, damit Jehova das Unglück über Absalom brächte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Und Husai sprach zu Zadok und zu Abjathar, den Priestern: So und so hat Ahitophel dem Absalom und den Ältesten von Israel geraten, und so und so habe ich geraten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'So sendet nun eilends hin und berichtet David und sprechet: Übernachte nicht diese Nacht in den Ebenen der Wüste, sondern gehe jedenfalls hinüber, damit nicht der König und alles Volk, das bei ihm ist, verschlungen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jonathan aber, und Achimaaz standen bei En-Rogel (eine Magd ging nämlich hin und berichtete ihnen, und sie gingen hin und berichteten dem König David; denn sie durften sich nicht sehen lassen, indem sie in die Stadt kamen).');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Und ein Knabe sah sie und berichtete es Absalom. Da gingen sie beide eilends und kamen in das Haus eines Mannes zu Bachurim; der hatte einen Brunnen in seinem Hofe, und sie stiegen dort hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Und das Weib nahm eine Decke und breitete sie über den Brunnen, und streute Grütze darüber aus, so daß nichts bemerkt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Und die Knechte Absaloms kamen zu dem Weibe ins Haus und sprachen: Wo sind Achimaaz und Jonathan? Und das Weib sprach zu ihnen: Sie sind über das Wasserbächlein gegangen. Und sie suchten, aber sie fanden sie nicht, und kehrten nach Jerusalem zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Und es geschah, nachdem sie weggegangen waren, da stiegen sie aus dem Brunnen herauf und gingen hin und berichteten dem König David; und sie sprachen zu David: Machet euch auf und gehet eilends über das Wasser, denn so hat Ahitophel wider euch geraten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Da machte David sich auf, und alles Volk, das bei ihm war, und sie gingen über den Jordan; bis der Morgen hell wurde, ward auch nicht einer vermißt, der nicht über den Jordan gegangen wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Als aber Ahitophel sah, daß sein Rat nicht ausgeführt worden war, sattelte er den Esel und machte sich auf und zog nach seinem Hause, nach seiner Stadt; und er bestellte sein Haus und erdrosselte sich; und er starb und wurde begraben im Begräbnis seines Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Und David kam nach Machanaim; und Absalom ging über den Jordan, er und alle Männer von Israel mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Und Absalom setzte Amasa an Joabs Statt über das Heer. Amasa war aber der Sohn eines Mannes, dessen Name Jithra war, der Israelit, der zu Abigail eingegangen war, der Tochter des Nahas, der Schwester der Zeruja, der Mutter Joabs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Und Israel und Absalom lagerten sich im Lande Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Und es geschah, als David nach Machanaim kam, da brachten Schobi, der Sohn des Nahas, aus Rabba der Kinder Ammon, und Makir, der Sohn Ammiels, aus Lodebar, und Barsillai, der Gileaditer, aus Rogelim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Betten und Becken und Töpfergefäße, und Weizen und Gerste und Mehl, und geröstete Körner und Bohnen und Linsen und Geröstetes davon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'und Honig und geronnene Milch, und Kleinvieh und Kuhkäse zu David und zu dem Volke, das bei ihm war, daß sie äßen; denn sie sprachen: Das Volk ist hungrig und matt und durstig in der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Und David musterte das Volk, das bei ihm war, und setzte über sie Oberste über tausend und Oberste über hundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Und David entsandte das Volk: ein Drittel unter der Hand Joabs und ein Drittel unter der Hand Abisais, des Sohnes der Zeruja, des Bruder Joabs, und ein Drittel unter der Hand Ittais, des Gathiters. Und der König sprach zu dem Volke: Auch ich werde gewißlich mit euch ausziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Aber das Volk sprach: Du sollst nicht ausziehen; denn wenn wir fliehen müßten, so würden sie nicht auf uns den Sinn richten; und wenn die Hälfte von uns stürbe, so würden sie nicht auf uns den Sinn richten; denn du bist wie unser zehntausend. So ist es nun besser, daß du uns von der Stadt aus zum Beistande bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Und der König sprach zu ihnen: Was gut ist in euren Augen, will ich tun. Und der König stellte sich an die Seite des Tores, und alles Volk zog aus zu Hunderten und zu Tausenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Und der König gebot Joab und Abisai und Ittai und sprach: Verfahret mir gelinde mit dem Jüngling, mit Absalom! Und alles Volk hörte es, als der König allen Obersten wegen Absaloms gebot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Und das Volk zog aus ins Feld, Israel entgegen; und die Schlacht fand statt im Walde Ephraim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Und das Volk von Israel wurde daselbst vor den Knechten Davids geschlagen, und die Niederlage wurde daselbst groß an jenem Tage: zwanzigtausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Und die Schlacht breitete sich daselbst aus über das ganze Land; und der Wald fraß mehr unter dem Volke, als das Schwert an jenem Tage fraß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Und Absalom stieß auf die Knechte Davids; und Absalom ritt auf einem Maultier, und das Maultier kam unter die verschlungenen Zweige einer großen Terebinthe; und er blieb mit dem Haupte an der Terebinthe hangen, und schwebte zwischen Himmel und Erde; das Maultier aber, das unter ihm war, lief davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Und ein Mann sah es und berichtete es Joab und sprach: Siehe, ich habe Absalom an einer Terebinthe hangen sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Da sprach Joab zu dem Manne, der es ihm berichtete: Siehe, wenn du ihn gesehen hast, warum hast du ihn nicht daselbst zu Boden geschlagen? Und an mir war es, dir zehn Sekel Silber und einen Gürtel zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Aber der Mann sprach zu Joab: Und wenn ich tausend Sekel Silber auf meinen Händen wöge, würde ich meine Hand nicht nach des Königs Sohn ausstrecken; denn vor unseren Ohren hat der König dir und Abisai und Ittai geboten und gesagt: Seid vorsichtig, wer es auch sei, mit dem Jüngling mit Absalom!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Hätte ich aber trüglich gegen sein Leben gehandelt und es bleibt ja keine Sache vor dem König verborgen, so würdest du selbst wider mich auftreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Da sprach Joab: Ich mag nicht also vor dir warten. Und er nahm drei Spieße in seine Hand und stieß sie in das Herz Absaloms, während er noch inmitten der Terebinthe lebte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Und zehn Knaben, Waffenträger Joabs, umgaben und erschlugen Absalom und töteten ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Und Joab stieß in die Posaune, und das Volk kehrte um von der Verfolgung Israels; denn Joab hielt das Volk ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Und sie nahmen Absalom und warfen ihn in eine große Grube im Walde, und errichteten über ihm einen sehr großen Haufen Steine. Und ganz Israel floh, ein jeder nach seinem Zelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Absalom aber hatte bei seinen Lebzeiten eine Denksäule genommen und sich aufgerichtet, die im Königstale steht; denn er sprach: Ich habe keinen Sohn, um meinen Namen in Erinnerung zu halten. Und er hatte die Denksäule nach seinem Namen genannt; und man nennt sie das Denkmal Absaloms, bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Und Achimaaz, der Sohn Zadoks, sprach: Ich will doch hinlaufen und dem König Botschaft bringen, daß Jehova ihm Recht verschafft hat von der Hand seiner Feinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Aber Joab sprach zu ihm: Du sollst nicht Bote sein an diesem Tage, sondern du magst an einem anderen Tage Botschaft bringen; doch an diesem Tage sollst du nicht Botschaft bringen, da ja der Sohn des Königs tot ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Und Joab sprach zu dem Kuschiten: Gehe hin, berichte dem König, was du gesehen hast. Und der Kuschit beugte sich nieder vor Joab und lief hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Da sprach Achimaaz, der Sohn Zadoks, wiederum zu Joab: Was auch geschehen möge, laß doch auch mich hinter dem Kuschiten herlaufen! Und Joab sprach: Warum willst du denn laufen, mein Sohn, da für dich keine einträgliche Botschaft da ist? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Was auch geschehen möge, ich will laufen. Und er sprach zu ihm: Laufe! Und Achimaaz lief den Weg des Jordankreises und kam dem Kuschiten zuvor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Und David saß zwischen den beiden Toren; und der Wächter ging auf das Dach des Tores, auf die Mauer, und er erhob seine Augen und sah, und siehe, ein Mann, der allein lief.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Und der Wächter rief und berichtete es dem König. Und der König sprach: Wenn er allein ist, so ist eine Botschaft in seinem Munde. Und er kam stets näher und näher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Da sah der Wächter einen anderen Mann laufen; und der Wächter rief dem Torhüter zu und sprach: Siehe, ein Mann, der allein läuft! Und der König sprach: Auch dieser ist ein Bote.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Und der Wächter sprach: Ich sehe den Lauf des ersten an für den Lauf des Achimaaz, des Sohnes Zadoks. Und der König sprach: Das ist ein guter Mann, und er kommt zu guter Botschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Und Achimaaz rief und sprach zu dem König: Friede! Und er beugte sich vor dem König auf sein Antlitz zur Erde nieder und sprach: Gepriesen sei Jehova, dein Gott, der die Männer überliefert hat, die ihre Hand erhoben haben wider meinen Herrn, den König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Und der König sprach: Geht es dem Jüngling, dem Absalom, wohl? Und Achimaaz sprach: Ich sah ein großes Getümmel, als Joab den Knecht des Königs und deinen Knecht absandte; aber ich weiß nicht, was es war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Und der König sprach: Wende dich, stelle dich hierher. Und er wandte sich und blieb stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Und siehe, der Kuschit kam, und der Kuschit sprach: Mein Herr, der König, lasse sich die Botschaft bringen, daß Jehova dir heute Recht verschafft hat von der Hand aller, die wider dich aufgestanden sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Und der König sprach zu dem Kuschiten: Geht es dem Jüngling, dem Absalom, wohl? Und der Kuschit sprach: Wie dem Jüngling, so möge es den Feinden des Königs, meines Herrn, ergehen und allen, die wider dich aufgestanden sind zum Bösen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Da wurde der König sehr bewegt, und er stieg hinauf in das Obergemach des Tores und weinte; und während er ging, sprach er also: Mein Sohn Absalom! Mein Sohn, mein Sohn Absalom! Wäre ich doch an deiner Statt gestorben! Absalom, mein Sohn, mein Sohn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Und es wurde Joab berichtet: Siehe, der König weint und trauert um Absalom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Und der Sieg wurde an jenem Tage zur Trauer für das ganze Volk; denn das Volk hörte an jenem Tage sagen: Der König ist betrübt um seinen Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Und das Volk stahl sich in die Stadt hinein an jenem Tage, wie ein Volk sich wegstiehlt, das zu Schanden geworden, wenn es im Streit geflohen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Und der König hatte sein Angesicht verhüllt, und der König schrie mit lauter Stimme: Mein Sohn Absalom! Absalom, mein Sohn, mein Sohn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Da begab sich Joab zum König ins Haus und sprach: Du hast heute das Angesicht aller deiner Knechte beschämt, die heute dein Leben errettet haben und das Leben deiner Söhne und deiner Töchter, und das Leben deiner Weiber und das Leben deiner Kebsweiber,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'indem du liebst, die dich hassen, und hassest, die dich lieben; denn du hast heute kundgetan, daß dir Oberste und Knechte nichts sind; denn heute erkenne ich, daß, wenn Absalom lebendig und wir alle heute tot wären, daß es dann recht wäre in deinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Und nun mache dich auf, gehe hinaus und rede zum Herzen deiner Knechte; denn ich schwöre bei Jehova, wenn du nicht hinausgehst, so wird diese Nacht nicht ein Mann bei dir bleiben; und das wäre schlimmer für dich als alles Übel, das über dich gekommen ist von deiner Jugend an bis jetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Da machte der König sich auf und setzte sich in das Tor. Und man berichtete allem Volke und sprach: Siehe, der König sitzt im Tore! Da kam alles Volk vor den König. Israel aber war geflohen, ein jeder nach seinen Zelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Und das ganze Volk haderte miteinander unter allen Stämmen Israels und sprach: Der König hat uns aus der Hand unserer Feinde errettet, und er hat uns befreit aus der Hand der Philister; und jetzt ist er vor Absalom aus dem Lande geflohen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Absalom aber, den wir über uns gesalbt hatten, ist im Streit gestorben; und nun, warum schweiget ihr davon, den König zurückzuführen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Und der König David sandte zu Zadok und zu Abjathar, den Priestern, und sprach: Redet zu den Ältesten von Juda und sprechet: Warum wollt ihr die letzten sein, den König in sein Haus zurückzuführen? Denn die Rede des ganzen Israel ist zum König in sein Haus gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Meine Brüder seid ihr, ihr seid mein Gebein und mein Fleisch; und warum wollt ihr die letzten sein, den König zurückzuführen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Und zu Amasa sollt ihr sagen: Bist du nicht mein Gebein und mein Fleisch? So soll mir Gott tun und so hinzufügen, wenn du nicht alle Tage Heeroberster vor mir sein sollst an Joabs Statt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Und er neigte das Herz aller Männer von Juda wie eines Mannes Herz; und sie entboten dem Könige: Kehre zurück, du und alle deine Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Und der König kehrte zurück und kam bis an den Jordan; und Juda kam nach Gilgal, dem König entgegen, um den König über den Jordan zu führen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Da eilte Simei, der Sohn Geras, der Benjaminiter, der von Bachurim war, und kam mit den Männern von Juda herab, dem König David entgegen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'und mit ihm waren tausend Mann von Benjamin, und Ziba, der Diener des Hauses Sauls, und seine fünfzehn Söhne und seine zwanzig Knechte mit ihm; und sie zogen über den Jordan, dem König entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, '(Eine Fähre aber fuhr über, um das Haus des Königs hinüberzuführen und zu tun, was gut war in seinen Augen.) Und Simei, der Sohn Geras, fiel vor dem König nieder, als er im Begriff stand, über den Jordan zu fahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Und er sprach zu dem König: Mein Herr wolle mir keine Verschuldung zurechnen; und gedenke nicht, wie dein Knecht sich vergangen hat an dem Tage, da mein Herr, der König, aus Jerusalem zog, daß der König es zu Herzen nehme!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Denn dein Knecht weiß wohl, daß ich gesündigt habe. Und siehe, ich bin heute gekommen, der erste vom ganzen Hause Joseph, um hinabzugehen, meinem Herrn, dem König, entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Und Abisai, der Sohn der Zeruja, antwortete und sprach: Sollte nicht Simei dafür getötet werden, daß er dem Gesalbten Jehovas geflucht hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Aber David sprach: Was haben wir miteinander zu schaffen, ihr Söhne der Zeruja, daß ihr mir heute zu Widersachern werdet? Sollte heute ein Mann in Israel getötet werden? Denn weiß ich nicht, daß ich heute König bin über Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Und der König sprach zu Simei: Du sollst nicht sterben! Und der König schwur ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Und Mephiboseth, der Sohn Sauls, kam herab, dem König entgegen. Und er hatte seine Füße nicht gereinigt und seinen Bart nicht gemacht und seine Kleider nicht gewaschen von dem Tage an, da der König weggegangen war, bis zu dem Tage, da er in Frieden einzog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Und es geschah, als Jerusalem dem König entgegenkam, da sprach der König zu ihm: Warum bist du nicht mit mir gezogen, Mephiboseth? Und er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Mein Herr König! Mein Knecht hat mich betrogen; denn dein Knecht sprach: Ich will mir den Esel satteln und darauf reiten und mit dem König ziehen, denn dein Knecht ist lahm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'und er hat deinen Knecht bei meinem Herrn, dem König verleumdet. Aber mein Herr, der König, ist wie ein Engel Gottes: So tue, was gut ist in deinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Denn das ganze Haus meines Vaters war nichts anderes als Männer des Todes vor meinem Herrn, dem König; und doch hast du deinen Knecht unter die gesetzt, welche an deinem Tische essen. Und was für ein Recht habe ich noch? Und um was hätte ich noch zum König zu schreien?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Und der König sprach zu ihm: Warum redest du noch von deinen Sachen? Ich sage: Du und Ziba, ihr sollt die Felder teilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Da sprach Mephiboseth zu dem König: Er mag auch das Ganze nehmen, nachdem mein Herr, der König, in Frieden in sein Haus gekommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Und Barsillai, der Gileaditer, kam von Rogelim herab und ging mit dem König über den Jordan, um ihn über den Jordan zu geleiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Barsillai war aber sehr alt, ein Mann von achtzig Jahren; und er hatte den König versorgt, als er zu Machanaim weilte, denn er war ein sehr reicher Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Und der König sprach zu Barsillai: Gehe du mit mir hinüber, und ich will dich bei mir versorgen zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Und Barsillai sprach zu dem König: Wie viel sind noch der Tage meiner Lebensjahre, daß ich mit dem König nach Jerusalem hinaufziehen sollte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Ich bin heute achtzig Jahre alt; kann ich Gutes und Schlechtes unterscheiden? Oder kann dein Knecht schmecken, was ich esse und was ich trinke? Oder kann ich noch auf die Stimme der Sänger und der Sängerinnen horchen? Und warum sollte dein Knecht meinem Herrn, dem König, noch zur Last sein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Dein Knecht würde nur auf kurze Zeit mit dem König über den Jordan gehen; und warum sollte der König mir diese Vergeltung erweisen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Laß doch deinen Knecht zurückkehren, daß ich in meiner Stadt sterbe, bei dem Grabe meines Vaters und meiner Mutter. Aber siehe, hier ist dein Knecht Kimham: Er möge mit meinem Herrn, dem König, hinübergehen; und tue ihm, was gut ist in deinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Und der König sprach: Kimham soll mit mir hinübergehen, und ich will ihm tun, was gut ist in deinen Augen; und alles, was du von mir begehren wirst, will ich für dich tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Und alles Volk ging über den Jordan, und auch der König ging hinüber. Und der König küßte Barsillai und segnete ihn; und er kehrte an seinen Ort zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Und der König ging hinüber nach Gilgal, und Kimham ging mit ihm hinüber. Und alles Volk von Juda, und auch die Hälfte des Volkes von Israel, führte den König hinüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Und siehe, alle Männer von Israel kamen zu dem König und sprachen zu dem König: Warum haben unsere Brüder, die Männer von Juda, dich weggestohlen und den König und sein Haus und alle Männer Davids mit ihm über den Jordan geführt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Und alle Männer von Juda antworteten den Männern von Israel: Weil der König mir nahe steht; und warum bist du denn über diese Sache erzürnt? Haben wir etwa von dem König Nahrung empfangen, oder hat er uns irgend ein Geschenk gemacht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Aber die Männer von Israel antworteten den Männern von Juda und sprachen: Ich habe zehn Teile an dem König, und habe auch an David mehr Anrecht als du; und warum hast du mich gering geachtet? Und ist nicht mein Wort das erste gewesen, meinen König zurückzuführen? Und das Wort der Männer von Juda war härter als das Wort der Männer von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Und daselbst war zufällig ein Mann Belials, sein Name war Scheba, der Sohn Bikris, ein Benjaminiter; und er stieß in die Posaune und sprach: Wir haben kein Teil an David und kein Erbteil an dem Sohne Isais! Ein jeder zu seinen Zelten, Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Da zogen alle Männer von Israel von David hinweg, Scheba, dem Sohne Bikris, nach. Die Männer von Juda aber hingen ihrem König an, vom Jordan bis Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Und David kam nach seinem Hause, nach Jerusalem. Und der König nahm die zehn Kebsweiber, die er zurückgelassen hatte, um das Haus zu bewahren, und tat sie in Gewahrsam und versorgte sie; er ging aber nicht zu ihnen ein; und sie waren eingeschlossen bis zum Tage ihres Todes, als Witwen lebend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Und der König sprach zu Amasa: Berufe mir die Männer von Juda binnen drei Tagen, und stelle dich selbst hier ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Und Amasa ging hin, Juda zu berufen; aber er verzog über die bestimmte Zeit, die er ihm bestimmt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Da sprach David zu Abisai: Nun wird uns Scheba, der Sohn Bikris, mehr Übles tun als Absalom. Nimm du die Knechte deines Herrn und jage ihm nach, ob er nicht feste Städte für sich gefunden und sich unseren Augen entzogen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Da zogen die Männer Joabs aus, ihm nach, und die Kerethiter und die Pelethiter und alle die Helden; und sie zogen aus von Jerusalem, um Scheba, dem Sohne Bikris, nachzujagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Sie waren bei dem großen Steine, der zu Gibeon ist, da kam Amasa ihnen entgegen. Und Joab war mit seinem Waffenrock als seinem Gewande umgürtet, und darüber war der Gürtel des Schwertes, das in seiner Scheide an seinen Lenden befestigt war; und als er hervortrat, fiel es heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Und Joab sprach zu Amasa: Geht es dir wohl, mein Bruder? Und Joab faßte mit der rechten Hand Amasas Bart, um ihn zu küssen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Amasa hatte aber nicht achtgegeben auf das Schwert, das in Joabs Hand war; und Joab schlug ihn damit in den Bauch und schüttete seine Eingeweide aus zur Erde, und gab ihm keinen zweiten Schlag; und er starb. Joab aber und Abisai, sein Bruder, jagten Scheba, dem Sohne Bikris, nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Und ein Mann von den Knaben Joabs blieb bei Amasa stehen und sprach: Wer Joab lieb hat und wer für David ist, folge Joab nach!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amasa aber wälzte sich im Blute mitten auf der Straße; und als der Mann sah, daß alles Volk stehen blieb, schaffte er Amasa von der Straße auf das Feld und warf ein Oberkleid über ihn, da er sah, daß jeder, der an ihn herankam, stehen blieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Als er von der Straße weggeschafft war, zog jedermann vorüber, Joab nach, um Scheba, dem Sohne Bikris, nachzujagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Und er durchzog alle Stämme Israels nach Abel und Beth-Maaka und ganz Berim; und sie versammelten sich und kamen ihm ebenfalls nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Und sie kamen und belagerten ihn in Abel-Beth-Maaka, und sie schütteten einen Wall gegen die Stadt auf, so daß derselbe an der Vormauer stand; und alles Volk, das mit Joab war, unterwühlte die Mauer, um sie zu stürzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Da rief ein kluges Weib aus der Stadt: Höret höret! Sprechet doch zu Joab: Nahe hierher, daß ich zu dir rede!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Und er näherte sich ihr. Und das Weib sprach: Bist du Joab? Und er sprach: Ich bin\'s. Und sie sprach zu ihm: Höre die Worte deiner Magd! Und er sprach: Ich höre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Und sie sprach und sagte: Früher pflegte man zu sprechen und zu sagen: Man frage nur in Abel; und so war man fertig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Ich bin von den Friedsamen, den Getreuen Israels; du suchst eine Stadt und Mutter in Israel zu töten. Warum willst du das Erbteil Jehovas verschlingen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Und Joab antwortete und sprach: Fern, fern sei es von mir, daß ich verschlingen und daß ich verderben sollte! Die Sache ist nicht also;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'sondern ein Mann vom Gebirge Ephraim, sein Name ist Scheba, der Sohn Bikris, hat seine Hand wider den König, wider David, erhoben; ihn allein gebet heraus, so will ich von der Stadt abziehen. Und das Weib sprach zu Joab: Siehe, sein Kopf soll dir über die Mauer zugeworfen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Und das Weib kam zu dem ganzen Volke mit ihrer Klugheit; und sie hieben Scheba, dem Sohne Bikris, den Kopf ab und warfen ihn Joab zu. Und er stieß in die Posaune, und sie zerstreuten sich von der Stadt hinweg, ein jeder nach seinen Zelten; und Joab kehrte zu dem König nach Jerusalem zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Und Joab war über das ganze Heer Israels; und Benaja, der Sohn Jojadas, war über die Kerethiter und über die Pelethiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'und Adoram war über die Fron; und Josaphat, der Sohn Ahiluds, war Geschichtsschreiber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'und Scheja war Schreiber; und Zadok und Abjathar waren Priester;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'und auch Ira, der Jairiter, war Krondiener Davids.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Und es war Hungersnot in den Tagen Davids drei Jahre, Jahr auf Jahr. Und David suchte das Angesicht Jehovas; und Jehova sprach: Es ist wegen Sauls und wegen des Bluthauses, weil er die Gibeoniter getötet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Da berief der König die Gibeoniter und redete zu ihnen. (Die Gibeoniter waren aber nicht von den Kindern Israel, sondern von dem Reste der Amoriter; und die Kinder Israel hatten ihnen geschworen; Saul aber suchte sie zu erschlagen, da er für die Kinder Israel und Juda eiferte.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Und David sprach zu den Gibeonitern: Was soll ich für euch tun, und womit soll ich Sühnung tun, daß ihr das Erbteil Jehovas segnet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Und die Gibeoniter sprachen zu ihm: Es ist uns nicht um Silber und Gold zu tun betreffs Sauls und betreffs seines Hauses, und es ist uns nicht darum zu tun, jemand in Israel zu töten. Und er sprach: Was ihr saget, will ich für euch tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Da sprachen sie zu dem König: Der Mann, der uns vernichtet hat, und der wider uns sann, daß wir vertilgt würden, um nicht mehr zu bestehen in allen Grenzen Israels: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Man gebe uns sieben Männer von seinen Söhnen, daß wir sie dem Jehova aufhängen zu Gibea Sauls, des Erwählten Jehovas. Und der König sprach: Ich will sie geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Aber der König verschonte Mephiboseth, den Sohn Jonathans, des Sohnes Sauls, um des Schwures Jehovas willen, der zwischen ihnen war, zwischen David und Jonathan, dem Sohne Sauls.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Und der König nahm die beiden Söhne Rizpas, der Tochter Ajas, die sie dem Saul geboren hatte, Armoni und Mephiboseth, und die fünf Söhne Michals, der Tochter Sauls, die sie dem Adriel geboren hatte, dem Sohne Barsillais, des Meholathiters,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'und er gab sie in die Hand der Gibeoniter; und sie hängten sie auf dem Berge vor Jehova auf. Und es fielen die sieben zugleich, und sie wurden getötet in den ersten Tagen der Ernte, im Anfang der Gerstenernte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Da nahm Rizpa, die Tochter Ajas, Sacktuch, und breitete es sich aus auf dem Felsen, vom Anfang der Ernte an, bis das Wasser vom Himmel über sie troff; und sie ließ das Gevögel des Himmels nicht auf ihnen ruhen bei Tage, noch das Getier des Feldes bei Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Und es wurde David berichtet, was Rizpa, die Tochter Ajas, das Kebsweib Sauls, getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Da ging David hin und nahm von den Bürgern von Jabes-Gilead die Gebeine Sauls und die Gebeine seines Sohnes Jonathan, welche sie von dem Marktplatze zu Beth-Schan heimlich weggenommen, wo die Philister sie aufgehängt hatten an dem Tage, da die Philister Saul schlugen auf dem Gilboa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Und er brachte die Gebeine Sauls und die Gebeine seines Sohnes Jonathan von dannen herauf; und man sammelte die Gebeine der Gehängten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'und begrub sie bei den Gebeinen Sauls und Jonathans, seines Sohnes, im Lande Benjamin, zu Zela, im Begräbnis seines Vaters Kis; und man tat alles, was der König geboten hatte. Und danach ließ Gott sich für das Land erbitten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Und wiederum entstand ein Streit der Philister mit Israel. Und David zog hinab, und seine Knechte mit ihm, und sie stritten mit den Philistern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Und David war ermattet; und Jischbi-Benob, der von den Söhnen des Rapha war (das Gewicht seiner Lanzenspitze war dreihundert Sekel Erz an Gewicht, und er war neu gerüstet), gedachte David zu erschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Aber Abisai, der Sohn der Zeruja, kam ihm zu Hilfe und schlug den Philister und tötete ihn. Damals schwuren die Männer Davids ihm zu und sprachen: Du sollst nicht mehr mit uns ausziehen zum Streit, daß du die Leuchte Israels nicht auslöschest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Und es geschah hernach, da begann wiederum der Streit mit den Philistern, zu Gob. Damals erschlug Sibbekai, der Huschathiter, den Saph, der von den Söhnen des Rapha war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Und wiederum begann der Streit mit den Philistern, zu Gob. Und Elchanan, der Sohn Jaare-Orgims, der Bethlehemiter, erschlug Goliath, den Gathiter; und der Schaft seines Speeres war wie ein Weberbaum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Und wiederum entstand ein Streit zu Gath. Da war ein Mann von großer Länge, und er hatte je sechs Finger an seinen Händen und je sechs Zehen an seinen Füßen, vierundzwanzig an der Zahl; und auch er war dem Rapha geboren worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Und er höhnte Israel; und Jonathan, der Sohn Schimeas, des Bruders Davids, erschlug ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Diese vier wurden dem Rapha zu Gath geboren; und sie fielen durch die Hand Davids und durch die Hand seiner Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Und David redete zu Jehova die Worte dieses Liedes an dem Tage, da Jehova ihn aus der Hand aller seiner Feinde und aus der Hand Sauls errettet hatte; und er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Jehova ist mein Fels und meine Burg und mein Erretter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Gott ist mein Fels, auf ihn werde ich trauen, mein Schild und das Horn meines Heils, meine hohe Feste und meine Zuflucht. Mein Retter, von Gewalttat wirst du mich retten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Ich werde Jehova anrufen, der zu loben ist, und ich werde gerettet werden von meinen Feinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Denn mich umfingen die Wogen des Todes, die Ströme Belials erschreckten mich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'die Bande des Scheols umringten mich, es ereilten mich die Fallstricke des Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'In meiner Bedrängnis rief ich zu Jehova, und ich rief zu meinem Gott; und er hörte aus seinem Tempel meine Stimme, und mein Schrei kam in seine Ohren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Da wankte und bebte die Erde; die Grundfesten des Himmels zitterten und wankten, weil er entbrannt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Rauch stieg auf von seiner Nase, und Feuer fraß aus seinem Munde; glühende Kohlen brannten aus ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Und er neigte die Himmel und fuhr hernieder, und Dunkel war unter seinen Füßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Und er fuhr auf einem Cherub und flog daher, und er erschien auf den Fittichen des Windes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Und Finsternis machte er rings um sich her zum Gezelt, Sammlung der Wasser, dichtes Himmelsgewölk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Aus dem Glanze vor ihm brannten feurige Kohlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Es donnerte Jehova vom Himmel her, und der Höchste ließ seine Stimme erschallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Und er schoß Pfeile und zerstreute sie, seinen Blitz, und verwirrte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Da wurden gesehen die Betten des Meeres, aufgedeckt die Grundfesten des Erdkreises durch das Schelten Jehovas, vor dem Schnauben des Hauches seiner Nase.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Er streckte seine Hand aus von der Höhe, er nahm mich, er zog mich aus großen Wassern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Er errettete mich von meinem starken Feinde, von meinen Hassern; denn sie waren mächtiger als ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Sie ereilten mich am Tage meines Unglücks, aber Jehova ward mir zur Stütze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Und er führte mich heraus ins Weite, er befreite mich, weil er Lust an mir hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Jehova vergalt mir nach meiner Gerechtigkeit, nach der Reinheit meiner Hände erstattete er mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Denn ich habe bewahrt die Wege Jehovas, und bin von meinem Gott nicht frevelhaft abgewichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Denn alle seine Rechte waren vor mir, und seine Satzungen, ich bin nicht davon gewichen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Und ich war vollkommen gegen ihn und hütete mich vor meiner Ungerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Und Jehova erstattete mir nach meiner Gerechtigkeit, nach meiner Reinheit vor seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Gegen den Gütigen erzeigst du dich gütig, gegen den vollkommenen Mann erzeigst du dich vollkommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'gegen den Reinen erzeigst du dich rein, und gegen den Verkehrten erzeigst du dich entgegenstreitend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Und du wirst retten das elende Volk; aber deine Augen sind wider die Hoffärtigen, die du erniedrigen wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Denn du bist meine Leuchte, Jehova; und Jehova erhellt meine Finsternis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Denn mit dir werde ich gegen eine Schar anrennen, mit meinem Gott werde ich eine Mauer überspringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Gott, sein Weg ist vollkommen; Jehovas Wort ist geläutert; ein Schild ist er allen, die auf ihn trauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Denn wer ist Gott, außer Jehova, und wer ein Fels, außer unserem Gott?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Gott ist meine starke Feste, und er lenkt vollkommen meinen Weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Er macht meine Füße denen der Hindinnen gleich, und stellt mich hin auf meine Höhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Er lehrt meine Hände den Streit, und meine Arme spannen den ehernen Bogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Und du gabst mir den Schild deines Heils, und deine Herablassung machte mich groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Du machtest Raum meinen Schritten unter mir, und meine Knöchel haben nicht gewankt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Meinen Feinden jagte ich nach und vertilgte sie; und ich kehrte nicht um, bis sie aufgerieben waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Und ich rieb sie auf und zerschmetterte sie; und sie standen nicht wieder auf, und sie fielen unter meine Füße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Und du umgürtetest mich mit Kraft zum Streit, beugtest unter mich, die wider mich aufstanden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Und du gabst mir den Rücken meiner Feinde; meine Hasser, ich vernichtete sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Sie blickten umher, und kein Retter war da zu Jehova, und er antwortete ihnen nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Und ich zermalmte sie wie Staub der Erde; wie Straßenkot zertrat, zerstampfte ich sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Und du errettetest mich aus den Streitigkeiten meines Volkes; du bewahrtest mich auf zum Haupte der Nationen; ein Volk, das ich nicht kannte, dient mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Die Söhne der Fremde unterwarfen sich mir mit Schmeichelei; beim Hören des Ohres gehorchten sie mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Die Söhne der Fremde sanken hin und zitterten hervor aus ihren Schlössern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Jehova lebt, und gepriesen sei mein Fels! Und erhoben werde der Gott, der Fels meines Heils!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Der Gott, der mir Rache gab und die Völker unter mich niederwarf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'und der mich herausführte aus der Mitte meiner Feinde. Ja, du erhöhtest mich über die, welche wider mich aufstanden, von dem Manne der Gewalttat befreitest du mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Darum, Jehova, will ich dich preisen unter den Nationen und Psalmen singen deinem Namen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Dich, der groß macht die Rettungen seines Königs, und Güte erweist seinem Gesalbten, David und seinem Samen ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Und dies sind die letzten Worte Davids: Es spricht David, der Sohn Isais, und es spricht der hochgestellte Mann, der Gesalbte des Gottes Jakobs und der Liebliche in Gesängen Israels:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Der Geist Jehovas hat durch mich geredet, und sein Wort war auf meiner Zunge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Es hat gesprochen der Gott Israels, der Fels Israels zu mir geredet: Ein Herrscher unter den Menschen, gerecht, ein Herrscher in Gottesfurcht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'und er wird sein wie das Licht des Morgens, wenn die Sonne aufgeht, ein Morgen ohne Wolken: Von ihrem Glanze nach dem Regen sproßt das Grün aus der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Obwohl mein Haus nicht also ist bei Gott, so hat er mir doch einen ewigen Bund gesetzt, geordnet in allem und verwahrt; denn dies ist all meine Rettung und all mein Begehr, obwohl er es nicht sprossen läßt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Aber die Söhne Belials sind allesamt wie Dornen, die man wegwirft; denn mit der Hand faßt man sie nicht an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'und der Mann, der sie anrührt, versieht sich mit Eisen und Speeresschaft; und mit Feuer werden sie gänzlich verbrannt an ihrer Stätte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Dies sind die Namen der Helden, welche David hatte: Joscheb-Baschebeth, der Tachkemoniter, das Haupt der Anführer; er... Adino, der Ezniter, war wider achthundert, die er auf einmal erschlug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Und nach ihm Eleasar, der Sohn Dodos, der Sohn eines Achochiters; er war unter den drei Helden mit David, als sie die Philister verhöhnten, die daselbst zum Streit versammelt waren, und als die Männer von Israel wegzogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Selbiger machte sich auf und schlug unter den Philistern, bis seine Hand ermüdete und seine Hand am Schwerte klebte; und Jehova schaffte an jenem Tage eine große Rettung. Das Volk aber kehrte um, ihm nach, nur um zu plündern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Und nach ihm Schamma, der Sohn Ages, des Harariters. Und die Philister versammelten sich zu einer Schar; und es war daselbst ein Ackerstück voll Linsen; das Volk aber floh vor den Philistern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Da stellte er sich mitten auf das Stück und rettete es und schlug die Philister; und Jehova schaffte eine große Rettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Und drei von den dreißig Häuptern gingen hinab und kamen zur Erntezeit zu David, in die Höhle Adullam; und eine Schar der Philister lagerte im Tale Rephaim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'David war aber damals auf der Bergfeste, und eine Aufstellung der Philister war damals zu Bethlehem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Und David hatte ein Gelüste und sprach: Wer wird mich mit Wasser tränken aus der Zisterne von Bethlehem, die am Tore ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Da brachen die drei Helden durch das Lager der Philister und schöpften Wasser aus der Zisterne von Bethlehem, die am Tore ist, und trugen und brachten es zu David. Aber er wollte es nicht trinken und goß es aus als Trankopfer dem Jehova;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'und er sprach: Fern sei es von mir, Jehova, daß ich solches tue! Sollte ich das Blut der Männer trinken, die mit Gefahr ihres Lebens hingegangen sind? Und er wollte es nicht trinken. Das taten die drei Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Und Abisai, der Bruder Joabs, der Sohn der Zeruja, war ein Haupt der Drei. Und er schwang seinen Speer über dreihundert, die er erschlug; und er hatte einen Namen unter den Dreien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'War er vor den Dreien nicht geehrt, so daß er ihr Oberster wurde? Aber an die ersten Drei reichte er nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Und Benaja, der Sohn Jojadas, der Sohn eines tapferen Mannes, groß an Taten, von Kabzeel; selbiger erschlug zwei Löwen von Moab. Und er stieg hinab und erschlug den Löwen in der Grube an einem Schneetage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Und er war es, der einen ägyptischen Mann erschlug, einen stattlichen Mann. Und der Ägypter hatte einen Speer in der Hand; er aber ging zu ihm hinab mit einem Stabe, und riß dem Ägypter den Speer aus der Hand und tötete ihn mit seinem eigenen Speere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Das tat Benaja, der Sohn Jojadas; und er hatte einen Namen unter den drei Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Vor den Dreißigen war er geehrt, aber an die ersten Drei reichte er nicht. Und David setzte ihn in seinen geheimen Rat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asael, der Bruder Joabs, war unter den Dreißig; Elchanan, der Sohn Dodos, von Bethlehem;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Schamma, der Haroditer; Elika, der Haroditer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Helez, der Paltiter; Ira, der Sohn Ikkesch\', der Tekoiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abieser, der Anathothiter; Mebunnai, der Huschathiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Zalmon, der Achochiter; Maharai, der Netophatiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Heleb, der Sohn Baanas, der Netophatiter; Ittai, der Sohn Ribais, von Gibea der Kinder Benjamin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaja, der Pirhathoniter; Hiddai, von den Bächen Gaasch;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abi-Albon, der Arbathiter; Asmaweth, der Barchumiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eljachba, der Schaalboniter; Bne-Jaschen; Jonathan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Schamma, der Harariter; Achiam, der Sohn Scharars, der Arariter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Eliphelet, der Sohn Achasbais, des Sohnes des Maakathiters; Eliam, der Sohn Ahitophels, der Giloniter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hezrai, der Karmeliter, Paarai, der Arbiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigal, der Sohn Nathans, von Zoba; Bani, der Gaditer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Zelek, der Ammoniter; Nacharai, der Beerothiter, der Waffenträger Joabs, des Sohnes der Zeruja;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira, der Jithriter; Gareb, der Jithriter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Urija, der Hethiter: in allem siebenunddreißig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Und der Zorn Jehovas entbrannte abermals wider Israel; und er reizte David wider sie, indem er sprach: Gehe hin, zähle Israel und Juda!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Da sprach der König zu Joab, dem Heerobersten, der bei ihm war: Gehe doch umher durch alle Stämme Israels, von Dan bis Beerseba, und musterte das Volk, damit ich die Zahl des Volkes wisse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Und Joab sprach zu dem König: Es möge Jehova, dein Gott, zu dem Volke, so viele ihrer auch sind, hundertmal hinzufügen, während die Augen meines Herrn, des Königs, es sehen! Aber warum hat mein Herr, der König, Gefallen an dieser Sache?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Aber das Wort des Königs blieb fest gegen Joab und gegen die Obersten des Heeres. Und Joab und die Obersten des Heeres zogen aus vor dem König, um das Volk Israel zu mustern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Und sie gingen über den Jordan und lagerten sich zu Aroer, rechts von der Stadt, die mitten im Flußtale von Gad liegt, und nach Jaser hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Und sie kamen nach Gilead und in das Land Tachtim-Hodschi; und sie kamen nach Dan-Jaan und in die Umgegend von Zidon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'und sie kamen zu der festen Stadt Zor und zu allen Städten der Hewiter und der Kanaaniter; und sie zogen hinaus in den Süden von Juda nach Beerseba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Und sie zogen umher durch das ganze Land, und kamen am Ende von neun Monaten und zwanzig Tagen nach Jerusalem zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Und Joab gab die Zahl des gemusterten Volkes dem König an; und es waren in Israel achthunderttausend Kriegsmänner, die das Schwert zogen, und der Männer von Juda fünfhunderttausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Aber dem David schlug sein Herz, nachdem er das Volk gezählt hatte; und David sprach zu Jehova: Ich habe sehr gesündigt in dem, was ich getan habe; und nun, Jehova, laß doch die Ungerechtigkeit deines Knechtes vorübergehen, denn ich habe sehr töricht gehandelt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Und als David am Morgen aufstand, da geschah das Wort Jehovas zu Gad, dem Propheten, dem Seher Davids, indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Gehe hin und rede zu David: So spricht Jehova: Dreierlei lege ich dir vor; wähle dir eines davon, daß ich es dir tue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Und Gad kam zu David und tat es ihm kund und sprach zu ihm: Sollen dir sieben Jahre Hungersnot in dein Land kommen? Oder willst du drei Monate vor deinen Feinden fliehen, indem sie dir nachjagen? Oder soll drei Tage Pest in deinem Lande sein? Nun wisse und sieh, was für eine Antwort ich dem zurückbringen soll, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Und David sprach zu Gad: Mir ist sehr angst! Mögen wir doch in die Hand Jehovas fallen, denn seine Erbarmungen sind groß; aber in die Hand der Menschen laß mich nicht fallen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Da sandte Jehova eine Pest unter Israel, vom Morgen an bis zur bestimmten Zeit; und es starben von dem Volke, von Dan bis Beerseba, siebzigtausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Und als der Engel seine Hand gegen Jerusalem ausstreckte, um es zu verderben, da reute Jehova des Übels, und er sprach zu dem Engel, der unter dem Volke verderbte: Genug! Ziehe jetzt deine Hand ab. Der Engel Jehovas war aber bei der Tenne Arawnas, des Jebusiters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Und als David den Engel sah, der unter dem Volke schlug, sprach er zu Jehova und sagte: Siehe, ich habe gesündigt, und ich habe verkehrt gehandelt; aber diese Schafe, was haben sie getan? Es sei doch deine Hand wider mich, und wider das Haus meines Vaters!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Und Gad kam zu David an selbigem Tage und sprach zu ihm: Gehe hinauf, errichte Jehova einen Altar auf der Tenne Arawnas, des Jebusiters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Und David ging hinauf, nach dem Worte Gads, so wie Jehova geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Und Arawna blickte hin und sah den König und seine Knechte zu sich herüberkommen; da ging Arawna hinaus und beugte sich vor dem König nieder, mit seinem Antlitz zur Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Und Arawna sprach: Warum kommt mein Herr, der König, zu seinem Knechte? Und David sprach: Die Tenne von dir zu kaufen, um Jehova einen Altar zu bauen, damit die Plage von dem Volke abgewehrt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Da sprach Arawna zu David: Mein Herr, der König, nehme und opfere, was gut ist in seinen Augen; siehe, die Rinder sind zum Brandopfer, und die Dreschwagen und die Geschirre der Rinder zum Holz:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'alles das, o König, gibt Arawna dem König. Und Arawna sprach zu dem König: Jehova, dein Gott, nehme dich wohlgefällig an!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Aber der König sprach zu Arawna: Nein, sondern kaufen will ich es von dir um einen Preis, und ich will Jehova, meinem Gott, nicht umsonst Brandopfer opfern. Und David kaufte die Tenne und die Rinder um fünfzig Sekel Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Und David baute daselbst Jehova einen Altar, und opferte Brandopfer und Friedensopfer. Und Jehova ließ sich für das Land erbitten, und die Plage wurde von Israel abgewehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Und der König David war alt, wohlbetagt; und sie bedeckten ihn mit Kleidern, aber er wurde nicht warm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Da sprachen seine Knechte zu ihm: Man suche meinem Herrn, dem König, ein Mädchen, eine Jungfrau; und sie stehe vor dem König und sei ihm eine Pflegerin, und sie schlafe an deinem Busen, daß mein Herr, der König, warm werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Und man suchte ein schönes Mädchen, in allen Grenzen Israels; und man fand Abischag, die Sunamitin, und brachte sie zu dem König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Und das Mädchen war überaus schön, und sie wurde dem König eine Pflegerin und bediente ihn; aber der König erkannte sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Adonija aber, der Sohn Haggiths, erhob sich und sprach: Ich will König werden! Und er schaffte sich Wagen und Reiter an, und fünfzig Mann, die vor ihm herliefen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Und sein Vater hatte ihn, so lange er lebte, nicht betrübt, daß er gesagt hätte: Warum tust du also? Und auch er war sehr schön von Gestalt; und Haggith hatte ihn nach Absalom geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Und er hatte Unterredungen mit Joab, dem Sohne der Zeruja, und mit Abjathar, dem Priester; und sie halfen Adonija und folgten ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Aber Zadok, der Priester, und Benaja, der Sohn Jojadas, und Nathan, der Prophet, und Simei und Rei, und die Helden, welche David hatte, waren nicht mit Adonija.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Und Adonija schlachtete Klein-und Rindvieh und Mastvieh bei dem Steine Socheleth, der neben En-Rogel ist; und er lud alle seine Brüder, die Söhne des Königs, und alle Männer von Juda, die Knechte des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Nathan aber, den Propheten, und Benaja und die Helden und Salomo, seinen Bruder, lud er nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Da sprach Nathan zu Bathseba, der Mutter Salomos, und sagte: Hast du nicht gehört, daß Adonija, der Sohn Haggiths, König geworden ist? Und unser Herr David weiß es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'So komm nun, laß mich dir doch einen Rat geben, daß du dein Leben und das Leben deines Sohnes Salomo errettest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Gehe hin und tritt zum König David hinein, und sprich zu ihm: Hast du, mein Herr König, nicht deiner Magd geschworen und gesagt: Dein Sohn Salomo soll nach mir König sein, und er soll auf meinem Throne sitzen? Und warum ist Adonija König geworden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Siehe, noch wirst du daselbst mit dem König reden, so werde ich nach dir hereinkommen und deine Worte bekräftigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Und Bathseba ging zu dem König hinein, in das Gemach; der König aber war sehr alt, und Abischag, die Sunamitin, bediente den König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Und Bathseba verneigte sich und beugte sich nieder vor dem König. Und der König sprach: Was ist dir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Und sie sprach zu ihm: Mein Herr, du hast ja deiner Magd bei Jehova, deinem Gott, geschworen: Dein Sohn Salomo soll nach mir König sein, und er soll auf meinem Throne sitzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'und nun, siehe, Adonija ist König geworden, und du, mein Herr König, weißt es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Und er hat Rinder und Mastvieh und Kleinvieh geschlachtet in Menge, und hat alle Söhne des Königs und Abjathar, den Priester, und Joab, den Heerobersten, geladen; aber deinen Knecht Salomo hat er nicht geladen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Und du, mein Herr König die Augen von ganz Israel sind auf dich gerichtet, daß du ihnen kundtuest, wer auf dem Throne meines Herrn, des Königs, nach ihm sitzen soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Und es wird geschehen, wenn mein Herr, der König, mit seinen Vätern liegt, daß ich und mein Sohn Salomo werden büßen müssen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Und siehe, noch redete sie mit dem König, da kam der Prophet Nathan herein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Und man berichtete dem König und sprach: Der Prophet Nathan ist da! Und er kam vor den König und beugte sich vor dem König auf sein Antlitz zur Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Und Nathan sprach: Mein Herr König, hast du gesagt: Adonija soll nach mir König sein, und er soll auf meinem Throne sitzen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Denn er ist heute hinabgegangen und hat Rinder und Mastvieh und Kleinvieh geschlachtet in Menge, und hat alle Söhne des Königs und die Obersten des Heeres und Abjathar, den Priester, geladen; und siehe, sie essen und trinken vor ihm und sprechen: Es lebe der König Adonija!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Aber mich, deinen Knecht, und Zadok, den Priester, und Benaja, den Sohn Jojadas, und Salomo, deinen Knecht, hat er nicht geladen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Ist diese Sache von meinem Herrn, dem König, aus geschehen? Und hast du nicht deinen Knechten kundgetan, wer auf dem Throne meines Herrn, des Königs, nach ihm sitzen soll?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Da antwortete der König David und sprach: Rufet mir Bathseba! Und sie kam herein vor den König und stand vor dem König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Und der König schwur und sprach: So wahr Jehova lebt, der meine Seele aus aller Bedrängnis erlöst hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'so wie ich dir bei Jehova, dem Gott Israels, geschworen habe, indem ich sprach: Dein Sohn Salomo soll nach mir König sein, und er soll auf meinem Throne sitzen an meiner Statt! also werde ich an diesem Tage tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Da verneigte sich Bathseba mit dem Antlitz zur Erde und beugte sich vor dem König nieder und sprach: Es lebe mein Herr, der König David, ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Und der König David sprach: Rufet mir Zadok, den Priester, und Nathan, den Propheten, und Benaja, den Sohn Jojadas! Und sie kamen herein vor den König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Und der König sprach zu ihnen: Nehmet die Knechte eures Herrn mit euch, und lasset meinen Sohn Salomo auf meiner Mauleselin reiten, und führet ihn nach Gihon hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Und Zadok, der Priester, und Nathan, der Prophet, sollen ihn daselbst zum König über Israel salben; und ihr sollt in die Posaune stoßen und sagen: Es lebe der König Salomo!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Und ziehet herauf hinter ihm her, und er komme und setze sich auf meinen Thron! Und er soll König sein an meiner Statt; und ihn habe ich bestellt, daß er Fürst sei über Israel und über Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Und Benaja, der Sohn Jojadas, antwortete dem König und sprach: Amen! Also spreche Jehova, der Gott meines Herrn, des Königs!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'So wie Jehova mit meinem Herrn, dem König, gewesen ist, also möge er mit Salomo sein, und er möge seinen Thron noch größer machen als den Thron meines Herrn, des Königs David!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Und Zadok, der Priester, und Nathan, der Prophet, und Benaja, der Sohn Jojadas, und die Kerethiter und die Pelethiter zogen hinab und ließen Salomo auf der Mauleselin des Königs David reiten, und sie führten ihn nach Gihon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Und Zadok, der Priester, nahm das Ölhorn aus dem Zelte und salbte Salomo; und sie stießen in die Posaune, und alles Volk sprach: Es lebe der König Salomo!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Und alles Volk zog hinauf hinter ihm her; und das Volk blies auf Flöten, und sie freuten sich mit großer Freude, so daß die Erde barst von ihrem Geschrei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Und Adonija hörte es und alle die Geladenen, die bei ihm waren, als sie eben das Essen beendigt hatten; und Joab hörte den Schall der Posaune und sprach: Weshalb dieses Geschrei der lärmenden Stadt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Während er noch redete, siehe, da kam Jonathan, der Sohn Abjathars, des Priesters. Und Adonija sprach: Komm, denn du bist ein wackerer Mann und wirst gute Botschaft bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Da antwortete Jonathan und sprach zu Adonija: Jawohl! Unser Herr, der König David, hat Salomo zum König gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Und der König hat Zadok, den Priester, und Nathan, den Propheten, und Benaja, den Sohn Jojadas, und die Kerethiter und die Pelethiter mit ihm gesandt, und sie haben ihn auf der Mauleselin des Königs reiten lassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'und Zadok, der Priester, und Nathan, der Prophet, haben ihn in Gihon zum König gesalbt; und sie sind von dannen heraufgezogen mit Freuden, und die Stadt ist in Bewegung. Das ist das Geschrei, welches ihr gehört habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Und auch hat sich Salomo auf den Thron des Königreichs gesetzt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'und auch sind die Knechte des Königs gekommen, um unseren Herrn, den König David, zu segnen, indem sie sprachen: Dein Gott mache den Namen Salomos noch vorzüglicher als deinen Namen, und mache seinen Thron größer als deinen Thron! Und der König hat auf dem Lager angebetet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'und auch hat der König also gesprochen: Gepriesen sei Jehova, der Gott Israels, der heute einen gegeben hat, der auf meinem Throne sitzt, während meine Augen es sehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Da erschraken alle die Geladenen Adonijas und standen auf und gingen ein jeder seines Weges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Und Adonija fürchtete sich vor Salomo; und er machte sich auf und ging hin und erfaßte die Hörner des Altars.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Und es wurde Salomo berichtet, indem man sprach: Siehe, Adonija fürchtet den König Salomo, und siehe, er hat die Hörner des Altars erfaßt und gesagt: Es schwöre mir jetzt der König Salomo, daß er seinen Knecht nicht mit dem Schwerte töten wolle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Und Salomo sprach: Wenn er sich als ein wackerer Mann erweisen wird, so soll von seinem Haar keines auf die Erde fallen; wenn aber Böses an ihm gefunden wird, so soll er sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Und der König Salomo sandte hin, und sie brachten ihn von dem Altar herab; und er kam und beugte sich vor dem König Salomo nieder; und Salomo sprach zu ihm: Gehe in dein Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Als nun die Tage Davids herannahten, daß er sterben sollte, gebot er seinem Sohne Salomo und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Ich gehe den Weg der ganzen Erde; so sei stark und sei ein Mann;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'und warte der Hut Jehovas, deines Gottes, daß du auf seinen Wegen wandelst, indem du seine Satzungen, seine Gebote und seine Rechte und seine Zeugnisse beobachtest, wie geschrieben ist in dem Gesetz Moses; auf daß es dir gelinge in allem, was du tust, und überall, wohin du dich wendest;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'auf daß Jehova sein Wort aufrecht halte, das er über mich geredet hat, indem er sprach: Wenn deine Söhne auf ihren Weg achthaben, so daß sie vor mir wandeln in Wahrheit, mit ihrem ganzen Herzen und mit ihrer ganzen Seele, so soll es, sprach er, dir nicht an einem Manne fehlen auf dem Throne Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Und du weißt ja auch, was mir Joab getan hat, der Sohn der Zeruja, was er den zwei Heerobersten Israels, Abner, dem Sohne Ners, und Amasa, dem Sohne Jethers, getan hat, indem er sie ermordete und Kriegsblut im Frieden vergoß, so daß er Kriegsblut an seinen Gürtel gebracht hat, der um seine Lenden war, und an seine Schuhe, die an seinen Füßen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'So handle nun nach deiner Weisheit, und laß sein graues Haar nicht in Frieden in den Scheol hinabfahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Aber an den Söhnen Barsillais, des Gileaditers, sollst du Güte erweisen, und sie sollen unter denen sein, die an deinem Tische essen; denn also sind sie mir entgegengekommen, als ich vor deinem Bruder Absalom floh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Und siehe, bei dir ist Simei, der Sohn Geras, der Benjaminiter, von Bachurim; und selbiger fluchte mir mit heftigem Fluche an dem Tage, da ich nach Machanaim ging. Aber er kam herab, mir entgegen, an den Jordan, und ich schwur ihm bei Jehova und sprach: Wenn ich dich mit dem Schwerte töte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Nun aber halte ihn nicht für schuldlos, denn du bist ein weiser Mann und wirst wissen, was du ihm tun sollst; und laß sein graues Haar mit Blut in den Scheol hinabfahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Und David legte sich zu seinen Vätern; und er wurde begraben in der Stadt Davids.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Und die Tage, die David über Israel regierte, waren vierzig Jahre; zu Hebron regierte er sieben Jahre, und zu Jerusalem regierte er dreiunddreißig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Und Salomo saß auf dem Throne seines Vaters David, und sein Königtum wurde sehr befestigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Und Adonija, der Sohn Haggiths, kam zu Bathseba, der Mutter Salomos; und sie sprach: Ist Friede dein Kommen? Und er sprach: Friede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Und er sprach: Ich habe ein Wort an dich. Und sie sprach: Rede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Und er sprach: Du weißt ja, daß das Königtum mein war, und daß ganz Israel sein Angesicht auf mich gerichtet hatte, daß ich König sein sollte; aber das Königtum hat sich gewandt und ist meinem Bruder geworden, denn von Jehova aus gehörte es ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Und nun bitte ich eine Bitte von dir; weise mich nicht ab! Und sie sprach zu ihm: Rede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Und er sprach: Sprich doch zu dem König Salomo, denn er wird dich nicht abweisen, daß er mir Abischag, die Sunamitin, zum Weibe gebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Und Bathseba sprach: Gut, ich will deinethalben mit dem König reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Und Bathseba ging zu dem König Salomo hinein, um wegen Adonijas mit ihm zu reden. Und der König stand auf, ihr entgegen, und beugte sich vor ihr nieder und setzte sich auf seinen Thron; und er ließ einen Thron für die Mutter des Königs hinstellen, und sie setzte sich zu seiner Rechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Und sie sprach: Ich habe eine kleine Bitte an dich; weise mich nicht ab! Und der König sprach zu ihr: Bitte, meine Mutter, denn ich werde dich nicht abweisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Und sie sprach: Möchte Abischag, die Sunamitin, deinem Bruder Adonija zum Weibe gegeben werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Da antwortete der König Salomo und sprach zu seiner Mutter: Und warum bittest du um Abischag, die Sunamitin, für Adonija? Bitte für ihn auch um das Königtum, denn er ist mein älterer Bruder sowohl für ihn, als für Abjathar, den Priester, und für Joab, den Sohn der Zeruja!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Und der König Salomo schwur bei Jehova und sprach: So soll mir Gott tun und so hinzufügen! Um sein Leben hat Adonija dieses Wort geredet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Und nun, so wahr Jehova lebt, der mich befestigt hat und mich hat sitzen lassen auf dem Throne meines Vaters David, und der mir ein Haus gemacht, so wie er geredet hat: heute soll Adonija getötet werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Und der König Salomo sandte hin durch Benaja, den Sohn Jojadas; und er stieß ihn nieder, und er starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Und zu Abjathar, dem Priester, sprach der König: Gehe nach Anathoth, auf deine Felder, denn du bist ein Mann des Todes; aber an diesem Tage will ich dich nicht töten, weil du die Lade des Herrn Jehova vor meinem Vater David getragen, und weil du gelitten hast in allem, worin mein Vater gelitten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Und so verstieß Salomo den Abjathar, daß er nicht mehr Priester Jehovas wäre, um das Wort Jehovas zu erfüllen, welches er zu Silo über das Haus Elis geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Und das Gerücht kam zu Joab (denn Joab hatte sich nach Adonija geneigt, aber nach Absalom hatte er sich nicht geneigt); da floh Joab zum Zelte Jehovas und erfaßte die Hörner des Altars.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Und es wurde dem König Salomo berichtet: Joab ist zum Zelte Jehovas geflohen, und siehe, er ist neben dem Altar. Da sandte Salomo Benaja, den Sohn Jojadas, und sprach: Gehe hin, stoße ihn nieder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Und Benaja kam zum Zelte Jehovas und sprach zu Joab: So spricht der König: Gehe hinaus! Und er sprach: Nein, sondern hier will ich sterben. Und Benaja brachte dem König Antwort und sprach: So hat Joab geredet, und so hat er mir geantwortet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Und der König sprach zu ihm: Tue, wie er geredet hat, und stoße ihn nieder, und begrabe ihn; und so tue das Blut, das Joab ohne Ursache vergossen hat, von mir und von dem Hause meines Vaters hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Und Jehova wird sein Blut auf seinen Kopf zurückbringen, weil er zwei Männer niedergestoßen hat, die gerechter und besser waren als er, und sie mit dem Schwerte ermordet hat, ohne daß mein Vater David es wußte: Abner, den Sohn Ners, den Heerobersten Israels, und Amasa, den Sohn Jethers, den Heerobersten Judas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Und ihr Blut wird zurückkehren auf den Kopf Joabs und auf den Kopf seines Samens ewiglich; aber David und seinem Samen und seinem Hause und seinem Throne wird Friede sein auf ewig von seiten Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Und Benaja, der Sohn Jojadas, ging hinauf und stieß ihn nieder und tötete ihn; und er wurde begraben in seinem Hause in der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Und der König setzte Benaja, den Sohn Jojadas, an seiner Statt über das Heer; und Zadok, den Priester, setzte der König an die Stelle Abjathars.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Und der König sandte hin und ließ Simei rufen, und er sprach zu ihm: Baue dir ein Haus zu Jerusalem, und wohne daselbst; und du sollst nicht von dannen herausgehen, dahin oder dorthin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Und es soll geschehen an dem Tage, da du hinausgehst und den Bach Kidron überschreitest, so wisse bestimmt, daß du sterben mußt; dein Blut wird auf deinem Kopfe sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Und Simei sprach zu dem König: Das Wort ist gut; so wie mein Herr, der König, geredet hat, also wird dein Knecht tun. Und Simei wohnte zu Jerusalem eine lange Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Es geschah aber am Ende von drei Jahren, da entflohen zwei Knechte Simeis zu Achis, dem Sohne Maakas, dem König von Gath; und man berichtete es Simei und sprach: Siehe, deine Knechte sind in Gath!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Da machte sich Simei auf und sattelte seinen Esel und ging nach Gath, zu Achis, um seine Knechte zu suchen; und Simei ging hin und brachte seine Knechte von Gath zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Und es wurde Salomo berichtet, daß Simei von Jerusalem nach Gath gegangen und zurückgekommen sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Da sandte der König hin und ließ Simei rufen, und er sprach zu ihm: Habe ich dich nicht bei Jehova beschworen und dir beteuert und gesagt: An dem Tage, da du hinausgehst und gehst dahin oder dorthin, so wisse bestimmt, daß du sterben mußt? Und du sprachst zu mir: Das Wort ist gut, das ich gehört habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Und warum hast du den Schwur Jehovas nicht beachtet und das Gebot, das ich dir geboten hatte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Und der König sprach zu Simei: Du selbst weißt all das Böse, dessen dein Herz sich bewußt ist, das du meinem Vater David getan hast; und so bringt Jehova deine Bosheit auf deinen Kopf zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Aber der König Salomo wird gesegnet sein, und der Thron Davids wird feststehen vor Jehova ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Und der König gebot Benaja, dem Sohne Jojadas; und er ging hinaus und stieß ihn nieder, und er starb. Und das Königtum wurde befestigt in der Hand Salomos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Und Salomo verschwägerte sich mit dem Pharao, dem König von Ägypten; und er nahm die Tochter des Pharao und brachte sie in die Stadt Davids, bis er den Bau seines Hauses und des Hauses Jehovas und der Mauer von Jerusalem ringsum vollendet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Nur opferte das Volk auf den Höhen; denn bis zu jenen Tagen war dem Namen Jehovas kein Haus gebaut worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Und Salomo liebte Jehova, indem er in den Satzungen seines Vaters David wandelte; nur opferte und räucherte er auf den Höhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Und der König ging nach Gibeon, um daselbst zu opfern, denn das war die große Höhe; tausend Brandopfer opferte Salomo auf selbigem Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Zu Gibeon erschien Jehova dem Salomo in einem Traume der Nacht; und Gott sprach: Bitte, was ich dir geben soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Und Salomo sprach: Du hast ja an deinem Knechte David, meinem Vater, große Güte erwiesen, so wie er vor dir gewandelt hat in Wahrheit und in Gerechtigkeit und in Geradheit des Herzens gegen dich; und du hast ihm diese große Güte bewahrt und ihm einen Sohn gegeben, der auf seinem Throne sitzt, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Und nun, Jehova, mein Gott, du hast deinen Knecht zum König gemacht an meines Vaters David Statt, und ich bin ein kleiner Knabe, ich weiß nicht aus-und einzugehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'und dein Knecht ist in der Mitte deines Volkes, das du erwählt hast, eines großen Volkes, das nicht gezählt noch berechnet werden kann vor Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'So gib denn deinem Knechte ein verständiges Herz, um dein Volk zu richten, zu unterscheiden zwischen Gutem und Bösem; denn wer vermöchte dieses dein zahlreiches Volk zu richten? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Und das Wort war gut in den Augen des Herrn, daß Salomo um dieses gebeten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Und Gott sprach zu ihm: Weil du um dieses gebeten hast, und hast dir nicht viele Tage erbeten, und hast dir nicht Reichtum erbeten, und nicht um das Leben deiner Feinde gebeten, sondern hast dir Einsicht erbeten, um das Recht zu verstehen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'siehe, so habe ich nach deinem Worte getan; siehe, ich habe dir ein weises und einsichtsvolles Herz gegeben, daß deinesgleichen vor dir nicht gewesen ist, und deinesgleichen nach dir nicht aufstehen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Und auch was du nicht erbeten hast, habe ich dir gegeben, sowohl Reichtum als Ehre, so daß deinesgleichen niemand unter den Königen sein wird alle deine Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Und wenn du auf meinen Wegen wandeln wirst, indem du meine Satzungen und meine Gebote beobachtest, so wie dein Vater David gewandelt hat, so werde ich deine Tage verlängern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Und Salomo erwachte, und siehe, es war ein Traum. Und er kam nach Jerusalem, und er stand vor der Lade des Bundes Jehovas und opferte Brandopfer und opferte Friedensopfer und machte allen seinen Knechten ein Mahl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Damals kamen zwei Huren zu dem König und standen vor ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Und das eine Weib sprach: Bitte, mein Herr! Ich und dieses Weib wohnten in einem Hause; und ich gebar bei ihr im Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Und es geschah am dritten Tage, nachdem ich geboren hatte, da gebar auch dieses Weib; und wir waren zusammen, kein Fremder war bei uns im Hause, nur wir beide waren im Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Und der Sohn dieses Weibes starb des Nachts, weil sie auf ihm gelegen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Und sie stand mitten in der Nacht auf und nahm meinen Sohn von meiner Seite, während deine Magd schlief, und legte ihn an ihren Busen; ihren toten Sohn aber legte sie an meinen Busen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Als ich nun am Morgen aufstand, um meinen Sohn zu säugen, siehe, da war er tot; und ich betrachtete ihn am Morgen, und siehe, es war nicht mein Sohn, den ich geboren hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Und das andere Weib sprach: Nein! Sondern mein Sohn ist der lebendige, und dein Sohn ist der tote. Und jene sprach: Nein! Sondern dein Sohn ist der tote, und mein Sohn ist der lebendige. Und so redeten sie vor dem König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Da sprach der König: Diese spricht: Dieser, der lebendige, ist mein Sohn, und dein Sohn ist der tote; und jene spricht: Nein! Sondern dein Sohn ist der tote, und mein Sohn ist der lebendige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Und der König sprach: Holet mir ein Schwert. Und man brachte das Schwert vor den König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Und der König sprach: Teilet das lebendige Kind in zwei Teile, und gebet der einen die Hälfte und der anderen die Hälfte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Da sprach das Weib, deren Sohn der lebendige war, zum König, denn ihr Innerstes wurde erregt über ihren Sohn, und sagte: Bitte mein Herr! Gebet ihr das lebendige Kind und tötet es ja nicht! Jene aber sagte: Weder mein noch dein soll es sein, zerteilet es!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Da antwortete der König und sprach: Gebet jener das lebendige Kind und tötet es ja nicht! Sie ist seine Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Und ganz Israel hörte das Urteil, das der König gefällt hatte, und sie fürchteten sich vor dem König; denn sie sahen, daß die Weisheit Gottes in ihm war, Recht zu üben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Und so war der König Salomo König über ganz Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Und dies sind die Obersten, die er hatte: Asarja, der Sohn Zadoks, war der Priester;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elichoreph und Achija, die Söhne Schischas, waren Schreiber; Josaphat, der Sohn Ahiluds, war Geschichtsschreiber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'und Benaja, der Sohn Jojadas, war über das Heer; und Zadok und Abjathar waren Priester;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'und Asarja, der Sohn Nathans, war über die Aufseher; und Sabut, der Sohn Nathans, war Krondiener, des Königs Freund;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'und Achischar war über das Haus, und Adoniram, der Sohn Abdas, über die Fron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Und Salomo hatte zwölf Aufseher über ganz Israel, und sie versorgten den König und sein Haus; einen Monat im Jahre lag jedem die Versorgung ob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Und dies sind ihre Namen: Ben-Hur im Gebirge Ephraim;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Ben-Deker in Makaz und in Schaalbim und Beth-Semes und Elon-Beth-Hanan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Ben-Hesed in Arubboth: Er hatte Soko und das ganze Land Hepher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Ben-Abinadab hatte das ganze Hügelgebiet von Dor; Taphath, die Tochter Salomos, war sein Weib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, der Sohn Ahiluds, hatte Taanak und Megiddo und ganz Beth-Schean, das neben Zarethan liegt, unterhalb Jisreel, von Beth-Schean bis Abel-Mehola, bis jenseits Jokmeam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Ben-Geber in Ramoth-Gilead; er hatte die Dörfer Jairs, des Sohnes Manasses, die in Gilead sind; er hatte den Landstrich Argob, der in Basan ist, sechzig große Städte mit Mauern und ehernen Riegeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Achinadab, der Sohn Iddos, in Machanaim;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Achimaaz in Naphtali; auch er hatte Basmath, die Tochter Salomos, zum Weibe genommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, der Sohn Husais, in Aser und Bealoth;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Josaphat, der Sohn Paruachs, in Issaschar;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Simei, der Sohn Elas, in Benjamin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber, der Sohn Uris, im Lande Gilead, dem Lande Sihons, des Königs der Amoriter, und Ogs, des Königs von Basan; und nur ein Aufseher war in diesem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Juda und Israel waren zahlreich, wie der Sand, der am Meere ist, an Menge; sie aßen und tranken und waren fröhlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Und Salomo war Herrscher über alle Königreiche, von dem Strome an bis zu dem Lande der Philister und bis zu der Grenze Ägyptens; sie brachten Geschenke und dienten Salomo alle Tage seines Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Und der Speisebedarf Salomos für einen Tag war: dreißig Kor Feinmehl und sechzig Kor Mehl,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'zehn gemästete Rinder und zwanzig Weiderinder und hundert Schafe; ohne die Hirsche und Gazellen und Damhirsche und das gemästete Geflügel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Denn er herrschte über das ganze Land diesseit des Stromes, von Tiphsach bis Gasa, über alle Könige diesseit des Stromes; und er hatte Frieden auf allen Seiten ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'Und Juda und Israel wohnten in Sicherheit, ein jeder unter seinem Weinstock und unter seinem Feigenbaum, von Dan bis Beerseba, alle Tage Salomos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Und Salomo hatte vierzigtausend Stände für Rosse zu seinen Wagen, und zwölftausend Reiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Und jene Aufseher versorgten den König Salomo und alle, die zum Tische des Königs Salomo kamen, ein jeder in seinem Monat; sie ließen es an nichts fehlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Und die Gerste und das Stroh für die Rosse und für die Renner brachten sie an den Ort, wo er war, ein jeder nach seiner Vorschrift.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Und Gott gab Salomo Weisheit und sehr große Einsicht, und Weite des Herzens, wie der Sand, der am Ufer des Meeres ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Und die Weisheit Salomos war größer als die Weisheit aller Söhne des Ostens und als alle Weisheit Ägyptens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Und er war weiser als alle Menschen, als Ethan, der Esrachiter, und Heman und Kalkol und Darda, die Söhne Machols. Und sein Name war unter allen Nationen ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Und er redete dreitausend Sprüche, und seiner Lieder waren tausendundfünf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Und er redete über die Bäume, von der Zeder, die auf dem Libanon ist, bis zum Ysop, der an der Mauer herauswächst; und er redete über das Vieh und über die Vögel und über das Gewürm und über die Fische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Und man kam aus allen Völkern, um die Weisheit Salomos zu hören, von allen Königen der Erde her, die von seiner Weisheit gehört hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Und Hiram, der König von Tyrus, sandte seine Knechte zu Salomo, denn er hatte gehört, daß man ihn zum König gesalbt hatte an seines Vaters Statt; denn Hiram war allezeit ein Freund Davids gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Und Salomo sandte zu Hiram und ließ ihm sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Du weißt ja, daß mein Vater David nicht vermochte, dem Namen Jehovas, seines Gottes, ein Haus zu bauen, wegen der Kriege, mit welchen sie ihn umgaben, bis Jehova sie unter seine Fußsohlen legte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Nun aber hat Jehova, mein Gott, mir Ruhe geschafft ringsum; da ist kein Widersacher mehr und kein schlimmes Begegnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Und siehe, ich gedenke dem Namen Jehovas, meines Gottes, ein Haus zu bauen, so wie Jehova zu meinem Vater David geredet und gesagt hat: Dein Sohn, den ich an deiner Statt auf deinen Thron setzen werde, der soll meinem Namen ein Haus bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Und nun gebiete, daß man mir Zedern vom Libanon haue; und meine Knechte sollen mit deinen Knechten sein; und den Lohn deiner Knechte will ich dir geben nach allem, was du sagen wirst; denn du weißt ja, daß niemand unter uns ist, der Holz zu hauen versteht wie die Zidonier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Und es geschah, als Hiram die Worte Salomos hörte, da freute er sich sehr; und er sprach: Gepriesen sei heute Jehova, der David einen weisen Sohn gegeben hat über dieses große Volk!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Und Hiram sandte zu Salomo und ließ ihm sagen: Ich habe gehört, was du mir entboten hast; ich will all dein Begehr tun betreffs des Zedernholzes und betreffs des Zypressenholzes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Meine Knechte sollen es vom Libanon an das Meer hinabbringen; und ich werde auf dem Meere Flöße daraus machen und sie bis an den Ort bringen lassen, den du mir angeben wirst, und dort will ich sie zerlegen lassen; und du sollst es abholen. Du aber sollst mein Begehr tun, indem du den Speisebedarf meines Hauses gibst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Und so gab Hiram dem Salomo Zedernholz und Zypressenholz nach all seinem Begehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Salomo aber gab Hiram zwanzigtausend Kor Weizen zur Nahrung für sein Haus, und zwanzig Kor zerstoßenes Öl: so gab Salomo dem Hiram Jahr für Jahr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Und Jehova gab Salomo Weisheit, so wie er zu ihm geredet hatte; und es war Friede zwischen Hiram und Salomo, und sie machten einen Bund miteinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Und der König Salomo hob Fronarbeiter aus ganz Israel aus, und der Fronarbeiter waren dreißigtausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Und er schickte sie auf den Libanon, zehntausend im Monat, wechselweise: einen Monat waren sie auf dem Libanon, zwei Monate in ihrem Hause; und Adoniram war über die Fronarbeiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Und Salomo hatte siebzigtausend Lastträger und achtzigtausend Steinhauer im Gebirge,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'ohne die Oberaufseher Salomos, welche über die Arbeit waren, dreitausenddreihundert, die über das Volk walteten, das an der Arbeit beschäftigt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Und der König gebot, und sie brachen große Steine, wertvolle Steine, um den Grund des Hauses zu legen, behauene Steine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Und die Bauleute Salomos und die Bauleute Hirams und die Gibliter behieben sie, und sie richteten das Holz und die Steine zum Bau des Hauses zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Und es geschah im vierhundertachtzigsten Jahre nach dem Auszuge der Kinder Israel aus dem Lande Ägypten, im vierten Jahre der Regierung Salomos über Israel, im Monat Siw, das ist der zweite Monat, da baute er Jehova das Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Und das Haus, das der König Salomo Jehova baute: sechzig Ellen war seine Länge, und zwanzig Ellen seine Breite, und dreißig Ellen seine Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Und die Halle vor dem Tempel des Hauses: zwanzig Ellen war ihre Länge vor der Breite des Hauses her; zehn Ellen war ihre Breite vor dem Hause her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Und er machte dem Hause Fenster, die mit unbeweglichen Querstäben vergittert waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Und er baute an die Wand des Hauses Stockwerke ringsum, an die Wände des Hauses ringsum, des Tempels und des Sprachortes; und er machte Seitenzimmer ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Das untere Stockwerk: fünf Ellen war seine Breite, und das mittlere, sechs Ellen seine Breite, und das dritte, sieben Ellen seine Breite; denn er hatte außen am Hause ringsum Absätze gemacht, um nicht in die Wände des Hauses einzugreifen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Und das Haus wurde bei seiner Erbauung aus vollständig behauenen Steinen erbaut; und Hammer und Meißel, irgend ein eisernes Werkzeug, wurde nicht am Hause gehört, als es erbaut wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Der Eingang der mittleren Seitenzimmer war an der rechten Seite des Hauses; und mittelst Wendeltreppen stieg man zu den mittleren, und von den mittleren zu den dritten hinauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Und er baute das Haus und vollendete es, und er deckte das Haus mit Balken und Reihen von Zedern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Und er baute die Stockwerke an das ganze Haus, fünf Ellen ihre Höhe; und sie waren mit dem Hause durch Zedernhölzer verbunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Und das Wort Jehovas geschah zu Salomo, indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Dieses Haus, das du baust, wenn du in meinen Satzungen wandeln und meine Rechte tun und alle meine Gebote beobachten wirst, daß du darin wandelst, so werde ich dir mein Wort aufrecht halten, das ich zu deinem Vater David geredet habe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'und ich werde inmitten der Kinder Israel wohnen und werde mein Volk Israel nicht verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Und Salomo baute das Haus und vollendete es. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Und er baute die Wände des Hauses innerhalb mit Zedernbrettern; vom Fußboden des Hauses bis an die Wände der Decke überzog er sie innerhalb mit Holz; und er überzog den Fußboden des Hauses mit Zypressenbrettern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Und er baute die zwanzig Ellen an der Hinterseite des Hauses mit Zedernbrettern, vom Fußboden bis an die Wände; und er baute sie ihm inwendig zum Sprachorte, zum Allerheiligsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Und das Haus, das ist der Tempel, vorn vor dem Sprachorte, war vierzig Ellen lang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Und das Zedernholz am Hause, inwendig, war Schnitzwerk von Koloquinthen und aufbrechenden Blumen; alles war Zedernholz, kein Stein wurde gesehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Und den Sprachort im Innersten des Hauses richtete er zu, um die Lade des Bundes Jehovas dahin zu setzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'und das Innere des Sprachortes: zwanzig Ellen die Länge, und zwanzig Ellen die Breite, und zwanzig Ellen seine Höhe; und er überzog ihn mit geläutertem Golde; auch den Zedernholzaltar überzog er damit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Und Salomo überzog das Haus inwendig mit geläutertem Golde; und er zog goldene Ketten vor dem Sprachorte her, und überzog ihn mit Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Und das ganze Haus überzog er mit Gold, das ganze Haus vollständig; auch den ganzen Altar, der zum Sprachorte gehörte, überzog er mit Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Und er machte im Sprachorte zwei Cherubim von Ölbaumholz, zehn Ellen ihre Höhe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'und fünf Ellen maß der eine Flügel des Cherubs, und fünf Ellen der andere Flügel des Cherubs: zehn Ellen von dem einen Ende seiner Flügel bis zu dem anderen Ende seiner Flügel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'und zehn Ellen maß der andere Cherub: beide Cherubim hatten ein Maß und einen Schnitt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Die Höhe des einen Cherubs war zehn Ellen, und ebenso die des anderen Cherubs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Und er stellte die Cherubim in das innerste Haus; und die Cherubim breiteten die Flügel aus, so daß der Flügel des einen an diese Wand rührte, und der Flügel des anderen Cherubs an die andere Wand rührte; und ihre Flügel, nach der Mitte des Hauses zu, rührten Flügel an Flügel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Und er überzog die Cherubim mit Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Und an allen Wänden des Hauses ringsum schnitzte er eingegrabenes Schnitzwerk von Cherubim und Palmen und aufbrechenden Blumen, innerhalb und außerhalb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Und den Fußboden des Hauses überzog er mit Gold, innerhalb und außerhalb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Und für den Eingang des Sprachortes machte er Türflügel von Ölbaumholz; die Einfassung, die Pfosten, bildeten den fünften Teil der Wand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Und in die zwei Türflügel von Ölbaumholz, darein schnitzte er Schnitzwerk von Cherubim und Palmen und aufbrechenden Blumen, und er überzog sie mit Gold: er breitete das Gold aus über die Cherubim und über die Palmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Und ebenso machte er für den Eingang des Tempels Pfosten von Ölbaumholz aus dem vierten Teile der Wand,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'und zwei Türflügel von Zypressenholz: aus zwei drehbaren Blättern war der eine Flügel, und aus zwei drehbaren Blättern der andere Flügel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Und er schnitzte Cherubim und Palmen und aufbrechende Blumen ein und überzog sie mit Gold, geschlichtet über das Eingegrabene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Und er baute den inneren Hof aus drei Reihen behauener Steine und aus einer Reihe Zedernbalken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Im vierten Jahre wurde der Grund des Hauses Jehovas gelegt, im Monat Siw;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'und im elften Jahre, im Monat Bul, das ist der achte Monat, war das Haus vollendet nach allen seinen Stücken und nach all seiner Vorschrift; und so baute er sieben Jahre daran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Und an seinem Hause baute Salomo dreizehn Jahre, und er vollendete sein ganzes Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Und zwar baute er das Haus des Waldes Libanon, hundert Ellen seine Länge, und fünfzig Ellen seine Breite, und dreißig Ellen seine Höhe, auf vier Reihen von Zedernsäulen, und Zedernbalken auf den Säulen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'und es war mit Zedernholz gedeckt oben über den Seitenzimmern, die auf den Säulen waren, fünfundvierzig, fünfzehn in der Reihe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Und der Balken waren drei Reihen, und Fenster gegen Fenster, dreimal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Und alle Türöffnungen und Pfosten waren viereckig, mit Gebälk, und Fenster gegen Fenster, dreimal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Und er machte die Säulenhalle, fünfzig Ellen ihre Länge, und dreißig Ellen ihre Breite; und noch eine Halle vor derselben, und Säulen und einen Auftritt vor denselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Und er machte die Thronhalle, wo er richtete, die Halle des Gerichts; und sie war mit Zedernholz getäfelt, von Boden zu Boden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Und sein Haus, in welchem er wohnte, im anderen Hofe innerhalb der Halle, war gleich diesem Werke. Und Salomo baute auch der Tochter des Pharao, die er zum Weibe genommen hatte, ein Haus gleich dieser Halle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Das alles war aus wertvollen Steinen, aus Steinen, die nach dem Maße behauen waren, mit der Säge gesägt von innen und von außen, und zwar von der Grundlage bis an die Kragsteine, und von außen bis zu dem großen Hofe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Und die Grundlage bestand aus wertvollen Steinen, aus großen Steinen, Steinen von zehn Ellen und Steinen von acht Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Und darüber her waren wertvolle Steine, Steine, die nach dem Maße behauen waren, und Zedernholz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Und der große Hof ringsum bestand aus drei Reihen behauener Steine und einer Reihe Zedernbalken; so war es auch mit dem inneren Hofe des Hauses Jehovas und mit der Halle des Hauses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Und der König Salomo sandte hin und ließ Hiram von Tyrus holen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Er war der Sohn einer Witwe aus dem Stamme Naphtali (sein Vater aber war ein Tyrer), ein Arbeiter in Erz; und er war voll Weisheit und Einsicht und Kenntnis, um allerlei Werk in Erz zu machen; und er kam zu dem König Salomo und machte sein ganzes Werk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Und er bildete die zwei Säulen von Erz: achtzehn Ellen die Höhe der einen Säule, und ein Faden von zwölf Ellen umfaßte die andere Säule.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Und er machte zwei Kapitäle, von Erz gegossen, um sie auf die Spitzen der Säulen zu setzen: fünf Ellen die Höhe des einen Kapitäls, und fünf Ellen die Höhe des anderen Kapitäls.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Geflecht im Netzwerk, Schnüre in Kettenwerk waren an den Kapitälen, die auf der Spitze der Säulen waren: sieben an dem einen Kapitäl, und sieben an dem anderen Kapitäl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Und er machte Granatäpfel, und zwar zwei Reihen ringsum, über das eine Netzwerk, zur Bedeckung der Kapitäle, die auf der Spitze der Säulen waren; und ebenso machte er es an dem anderen Kapitäl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Und die Kapitäle, die auf der Spitze der Säulen waren, waren wie die Lilienarbeit in der Halle, vier Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Und auch waren Kapitäle auf den beiden Säulen oben, dicht an dem Wulste, der jenseit des Flechtwerks war. Und der Granatäpfel waren zweihundert, in Reihen ringsum, an dem anderen Kapitäl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Und er richtete die Säulen auf bei der Halle des Tempels: er richtete die rechte Säule auf und gab ihr den Namen Jakin, und er richtete die linke Säule auf und gab ihr den Namen Boas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Und auf der Spitze der Säulen war Lilienarbeit. Und so wurde das Werk der Säulen vollendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Und er machte das Meer, gegossen, zehn Ellen von seinem einen Rande bis zu seinem anderen Rande, gerundet ringsum, und fünf Ellen seine Höhe; und eine Schnur von dreißig Ellen umfaßte es ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Und unterhalb seines Randes umgaben es Koloquinthen ringsum, zehn auf die Elle, das Meer ringsum einschließend; der Koloquinthen waren zwei Reihen, gegossen aus einem Gusse mit demselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Es stand auf zwölf Rindern: drei wandten sich gegen Norden, und drei wandten sich gegen Westen, und drei wandten sich gegen Süden, und drei wandten sich gegen Osten; und das Meer war auf denselben, oben darüber, und alle ihre Hinterteile waren nach innen gekehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Und seine Dicke war eine Handbreit, und sein Rand wie die Arbeit eines Becherrandes, wie eine Lilienblüte; es faßte zweitausend Bath.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Und er machte die zehn Gestelle von Erz: vier Ellen die Länge eines Gestelles, und vier Ellen seine Breite, und drei Ellen seine Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Und dies war die Arbeit der Gestelle: Es waren Felder an ihnen, und die Felder waren zwischen den Eckleisten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'und auf den Feldern, die zwischen den Eckleisten waren, waren Löwen, Rinder und Cherubim; und oben auf den Eckleisten ein Untersatz; und unterhalb der Löwen und der Rinder waren Kränze, in Form von Gehängen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Und jedes Gestell hatte vier eherne Räder und eherne Achsen, und seine vier Füße hatten Schulterstücke; unter dem Becken waren die Schulterstücke angegossen; jenseit eines jeden waren die Kränze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Und seine Öffnung, innerhalb der Krone und aufwärts, war bei einer Elle, und ihre Öffnung war gerundet, Gestellarbeit, eine Elle und eine halbe Elle; und auch an ihrer Öffnung war Schnitzwerk. Und ihre Felder waren viereckig, nicht rund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Und die vier Räder waren unterhalb der Felder; und die Halter der Räder waren an dem Gestell; und die Höhe eines Rades war eine Elle und eine halbe Elle;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'und die Arbeit der Räder war wie die Arbeit eines Wagenrades; ihre Halter und ihre Felgen und ihre Speichen und ihre Naben, das Ganze war gegossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Und vier Schulterstücke waren an den vier Ecken eines Gestelles: Aus dem Gestell waren seine Schulterstücke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Und am oberen Teile des Gestelles war eine Erhöhung von einer halben Elle, gerundet ringsum; und am oberen Teile des Gestelles waren seine Halter und seine Felder aus demselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Und er grub in die Tafeln seiner Halter und in seine Felder Cherubim, Löwen und Palmen ein, nach dem Raume eines jeden, und Kränze ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Auf diese Weise machte er die zehn Gestelle: ein Guß, ein Maß, ein Schnitt für sie alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Und er machte zehn Becken von Erz: Vierzig Bath faßte ein Becken; vier Ellen war ein Becken weit; je ein Becken war auf je einem Gestell von den zehn Gestellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Und er setzte die Gestelle, fünf auf die rechte Seite des Hauses, und fünf auf die linke Seite des Hauses. Und das Meer setzte er auf die rechte Seite des Hauses ostwärts, gegen Süden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Und Hiram machte die Töpfe und die Schaufeln und die Sprengschalen. Und so vollendete Hiram die Arbeit des ganzen Werkes, das er dem König Salomo für das Haus Jehovas machte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'zwei Säulen und die krugförmigen Kapitäle, die auf der Spitze der beiden Säulen waren; und die zwei Netzwerke zur Bedeckung der beiden krugförmigen Kapitäle, die auf der Spitze der Säulen waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'und die vierhundert Granatäpfel zu den beiden Netzwerken: zwei Reihen Granatäpfel zu jedem Netzwerk, zur Bedeckung der beiden krugförmigen Kapitäle, die oben auf den Säulen waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'und die zehn Gestelle, und die zehn Becken auf den Gestellen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'und das eine Meer, und die zwölf Rinder unter dem Meere;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'und die Töpfe und die Schaufeln und die Sprengschalen. Und alle diese Geräte, welche Hiram dem König Salomo für das Haus Jehovas machte, waren von geglättetem Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Im Jordankreise ließ der König sie gießen, in dichter Erde, zwischen Sukkoth und Zarethan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Und Salomo ließ alle Geräte ungewogen vor übergroßer Menge, das Gewicht des Erzes wurde nicht untersucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Und Salomo machte alle die Geräte, welche im Hause Jehovas waren: den goldenen Altar; und den goldenen Tisch, auf welchem, die Schaubrote lagen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'und die Leuchter, fünf zur Rechten und fünf zur Linken vor dem Sprachorte, von geläutertem Golde; und die Blumen und die Lampen und die Lichtschneuzen von Gold;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'und die Becken und die Lichtmesser und die Sprengschalen und die Schalen und die Räucherpfannen von geläutertem Golde; und die Angeln zu den Türflügeln des inneren Hauses, des Allerheiligsten, und zu den Flügeltüren des Hauses, des Tempels, von Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Und so war das ganze Werk vollendet, das der König Salomo für das Haus Jehovas machte. Und Salomo brachte die geheiligten Dinge seines Vaters David hinein: Das Silber und das Gold und die Geräte legte er in die Schatzkammern des Hauses Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Damals versammelte Salomo die Ältesten von Israel und alle Häupter der Stämme, die Fürsten der Vaterhäuser der Kinder Israel, zum König Salomo nach Jerusalem, um die Lade des Bundes Jehovas heraufzubringen aus der Stadt Davids, das ist Zion.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Und alle Männer von Israel versammelten sich zum König Salomo im Monat Ethanim, das ist der siebte Monat, am Feste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Und es kamen alle Ältesten von Israel, und die Priester nahmen die Lade auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Und sie brachten die Lade Jehovas hinauf, und das Zelt der Zusammenkunft und alle heiligen Geräte, die im Zelte waren: die Priester und die Leviten brachten sie hinauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Und der König Salomo und die ganze Gemeinde Israel, die sich zu ihm versammelt hatte und mit ihm vor der Lade stand, opferten Klein-und Rindvieh, das nicht gerechnet und nicht gezählt werden konnte vor Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Und die Priester brachten die Lade des Bundes Jehovas an ihren Ort, in den Sprachort des Hauses, in das Allerheiligste, unter die Flügel der Cherubim;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'denn die Cherubim breiteten die Flügel aus über den Ort der Lade, und die Cherubim bedeckten die Lade und ihre Stangen von oben her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Und die Stangen waren so lang, daß die Spitzen der Stangen vom Heiligen aus an der Vorderseite des Sprachortes gesehen wurden; aber auswärts wurden sie nicht gesehen. Und sie sind daselbst bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Nichts war in der Lade, als nur die beiden steinernen Tafeln, welche Mose am Horeb hineinlegte, als Jehova einen Bund machte mit den Kindern Israel, als sie aus dem Lande Ägypten zogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Und es geschah, als die Priester aus dem Heiligen hinausgingen, da erfüllte die Wolke das Haus Jehovas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'und die Priester vermochten wegen der Wolke nicht dazustehen, um den Dienst zu verrichten; denn die Herrlichkeit Jehovas erfüllte das Haus Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Damals sprach Salomo: Jehova hat gesagt, daß er im Dunkel wohnen wolle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Gebaut habe ich dir ein Haus zur Wohnung, eine Stätte zu deinem Sitze für Ewigkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Und der König wandte sein Angesicht und segnete die ganze Versammlung Israels; und die ganze Versammlung Israels stand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Und er sprach: Gepriesen sei Jehova, der Gott Israels, der mit seinem Munde zu meinem Vater David geredet und mit seiner Hand es erfüllt hat, indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Von dem Tage an, da ich mein Volk Israel aus Ägypten herausführte, habe ich keine Stadt aus allen Stämmen Israels erwählt, um ein Haus zu bauen, damit mein Name daselbst wäre; aber ich habe David erwählt, daß er über mein Volk Israel wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Und es war in dem Herzen meines Vaters David, dem Namen Jehovas, des Gottes Israels, ein Haus zu bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Und Jehova sprach zu meinem Vater David: Weil es in deinem Herzen gewesen ist, meinem Namen ein Haus zu bauen, so hast du wohlgetan, daß es in deinem Herzen gewesen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Nur sollst du nicht das Haus bauen; sondern dein Sohn, der aus deinen Lenden hervorkommen wird, er soll meinem Namen das Haus bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Und Jehova hat sein Wort aufrecht gehalten, das er geredet hat; und ich bin aufgestanden an meines Vaters David Statt, und habe mich auf den Thron Israels gesetzt, so wie Jehova geredet hat, und habe dem Namen Jehovas, des Gottes Israels, das Haus gebaut;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'und ich habe daselbst einen Ort hergerichtet für die Lade, in welcher der Bund Jehovas ist, den er mit unseren Vätern gemacht hat, als er sie aus dem Lande Ägypten herausführte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Und Salomo trat vor den Altar Jehovas angesichts der ganzen Versammlung Israels; und er breitete seine Hände aus gen Himmel und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'Jehova, Gott Israels! Kein Gott ist dir gleich im Himmel oben und auf der Erde unten, der du den Bund und die Güte deinen Knechten bewahrst, die vor dir wandeln mit ihrem ganzen Herzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'der du deinem Knechte David, meinem Vater, gehalten, was du zu ihm geredet hast: du hast es mit deinem Munde geredet, und mit deiner Hand hast du es erfüllt, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Und nun, Jehova, Gott Israels, halte deinem Knechte David, meinem Vater, was du zu ihm geredet hast, indem du sprachst: Es soll dir nicht an einem Manne fehlen vor meinem Angesicht, der da sitze auf dem Throne Israels, wenn nur deine Söhne auf ihren Weg achthaben, daß sie vor mir wandeln, so wie du vor mir gewandelt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Und nun, Gott Israels, mögen sich doch deine Worte bewähren, die du zu deinem Knechte David, meinem Vater, geredet hast! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Aber sollte Gott wirklich auf der Erde wohnen? Siehe, die Himmel und der Himmel Himmel können dich nicht fassen; wieviel weniger dieses Haus, das ich gebaut habe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Doch wende dich zu dem Gebet deines Knechtes und zu seinem Flehen, Jehova, mein Gott, daß du hörest auf das Rufen und auf das Gebet, welches dein Knecht heute vor dir betet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'daß deine Augen Nacht und Tag offen seien über dieses Haus, über den Ort, von dem du gesagt hast: Mein Name soll daselbst sein! Daß du hörest auf das Gebet, welches dein Knecht gegen diesen Ort hin beten wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Und höre auf das Flehen deines Knechtes und deines Volkes Israel, das sie gegen diesen Ort hin richten werden; und höre du an der Stätte deiner Wohnung, im Himmel, ja, höre und vergib!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Wenn jemand wider seinen Nächsten sündigt, und man ihm einen Eid auflegt, um ihn schwören zu lassen, und er kommt und schwört vor deinem Altar in diesem Hause:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'so höre du im Himmel und handle und richte deine Knechte, indem du den Schuldigen schuldig sprichst, daß du seinen Weg auf seinen Kopf bringst, und indem du den Gerechten gerecht sprichst, daß du ihm gibst nach seiner Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Wenn dein Volk Israel vor dem Feinde geschlagen wird, weil sie wider dich gesündigt haben, und sie kehren zu dir um und bekennen deinen Namen, und beten und flehen zu dir in diesem Hause:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'so höre du im Himmel und vergib die Sünde deines Volkes Israel; und bringe sie in das Land zurück, das du ihren Vätern gegeben hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Wenn der Himmel verschlossen, und kein Regen sein wird, weil sie wider dich gesündigt haben, und sie beten gegen diesen Ort hin und bekennen deinen Namen und kehren um von ihrer Sünde, weil du sie demütigst:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'so höre du im Himmel und vergib die Sünde deiner Knechte und deines Volkes Israel, daß du ihnen den guten Weg zeigest, auf welchem sie wandeln sollen; und gib Regen auf dein Land, das du deinem Volke zum Erbteil gegeben hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Wenn eine Hungersnot im Lande sein wird, wenn Pest sein wird, wenn Kornbrand, Vergilben des Getreides, Heuschrecken oder Grillen sein werden; wenn sein Feind es belagert im Lande seiner Tore, wenn irgend eine Plage, irgend eine Krankheit sein wird:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'welches Gebet, welches Flehen irgend geschehen wird von irgend einem Menschen, von deinem ganzen Volke Israel, wenn sie erkennen werden ein jeder die Plage seines Herzens, und er seine Hände ausbreitet gegen dieses Haus hin:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'so höre du im Himmel, der Stätte deiner Wohnung, und vergib, und tue und gib einem jeden nach allen seinen Wegen, wie du sein Herz kennst denn du, du allein kennst das Herz aller Menschenkinder; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'auf daß sie dich fürchten alle die Tage, die sie in dem Lande leben werden, das du unseren Vätern gegeben hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Und auch auf den Fremden, der nicht von deinem Volke Israel ist, kommt er aus fernem Lande um deines Namens willen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(denn sie werden hören von deinem großen Namen und deiner starken Hand und deinem ausgestreckten Arm), kommt er und betet gegen dieses Haus hin:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'so höre du im Himmel, der Stätte deiner Wohnung, und tue nach allem, um was der Fremde zu dir rufen wird; auf daß alle Völker der Erde deinen Namen erkennen, damit sie dich fürchten, wie dein Volk Israel, und damit sie erkennen, daß dieses Haus, welches ich gebaut habe, nach deinem Namen genannt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Wenn dein Volk ausziehen wird zum Streit wider seinen Feind, auf dem Wege, den du sie senden wirst, und sie zu Jehova beten nach der Stadt hin, die du erwählt hast, und dem Hause, das ich deinem Namen gebaut habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'so höre im Himmel ihr Gebet und ihr Flehen, und führe ihr Recht aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Wenn sie wider dich sündigen, denn da ist kein Mensch, der nicht sündigte und du über sie erzürnst und sie vor dem Feinde dahingibst und ihre Besieger sie gefangen wegführen in das Land des Feindes, ein fernes oder ein nahes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'und sie nehmen es zu Herzen in dem Lande, wohin sie gefangen weggeführt sind, und kehren um und flehen zu dir in dem Lande derer, die sie gefangen weggeführt haben, und sprechen: Wir haben gesündigt und haben verkehrt gehandelt, wir haben gesetzlos gehandelt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'und sie kehren zu dir um mit ihrem ganzen Herzen und mit ihrer ganzen Seele in dem Lande ihrer Feinde, die sie gefangen weggeführt haben, und sie beten zu dir nach ihrem Lande hin, das du ihren Vätern gegeben, nach der Stadt, die du erwählt hast, und dem Hause, das ich deinem Namen gebaut habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'so höre im Himmel, der Stätte deiner Wohnung, ihr Gebet und ihr Flehen, und führe ihr Recht aus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'und vergib deinem Volke, was sie gegen dich gesündigt haben, und alle ihre Übertretungen, womit sie wider dich übertreten haben; und laß sie Barmherzigkeit finden vor denen, die sie gefangen weggeführt haben, daß sie sich ihrer erbarmen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'denn sie sind dein Volk und dein Erbteil, das du herausgeführt hast aus Ägypten, mitten aus dem eisernen Schmelzofen: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'So daß deine Augen offen seien für das Flehen deines Knechtes und für das Flehen deines Volkes Israel, daß du auf sie hörest in allem, um was sie zu dir rufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Denn du, du hast sie ausgesondert, dir zum Erbteil aus allen Völkern der Erde, so wie du durch deinen Knecht Mose geredet hast, als du unsere Väter aus Ägypten herausführtest, Herr, Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Und es geschah, als Salomo geendigt hatte, dieses ganze Gebet und Flehen an Jehova zu richten, stand er auf vor dem Altar Jehovas von dem Beugen seiner Knie, indem seine Hände gen Himmel ausgebreitet waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'und er stand und segnete die ganze Versammlung Israels mit lauter Stimme und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Gepriesen sei Jehova, der seinem Volke Israel Ruhe gegeben, nach allem, was er geredet hat! Kein einziges Wort ist dahingefallen von allen seinen guten Worten, die er durch seinen Knecht Mose geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Jehova, unser Gott, sei mit uns, so wie er mit unseren Vätern gewesen ist; er verlasse uns nicht und verstoße uns nicht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'um unser Herz zu ihm zu neigen, damit wir auf allen seinen Wegen wandeln und seine Gebote und seine Satzungen und seine Rechte beobachten, die er unseren Vätern geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Und diese meine Worte, die ich vor Jehova gefleht habe, mögen Jehova, unserem Gott, nahe sein Tag und Nacht, daß er das Recht seines Knechtes und das Recht seines Volkes Israel ausführe, je nachdem der Tag es erfordert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'damit alle Völker der Erde erkennen, daß Jehova Gott ist, keiner mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Und euer Herz sei ungeteilt mit Jehova, unserem Gott, um in seinen Satzungen zu wandeln und seine Gebote zu beobachten, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Und der König und ganz Israel mit ihm opferten Schlachtopfer vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Und Salomo schlachtete als Friedensopfer, das er Jehova opferte, zweiundzwanzigtausend Rinder und hundertundzwanzigtausend Schafe. Und der König und alle Kinder Israel weihten das Haus Jehovas ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'An selbigem Tage heiligte der König die Mitte des Hofes, die vor dem Hause Jehovas lag; denn er opferte daselbst das Brandopfer und das Speisopfer und die Fettstücke der Friedensopfer; denn der eherne Altar, der vor Jehova stand, war zu klein, um das Brandopfer und das Speisopfer und die Fettstücke der Friedensopfer zu fassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Und so feierten Salomo und ganz Israel mit ihm, eine große Versammlung, von dem Eingang Hamaths bis an den Fluß Ägyptens, zu selbiger Zeit das Fest vor Jehova, unserem Gott, sieben Tage und sieben Tage, vierzehn Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Am achten Tage entließ er das Volk; und sie segneten den König und gingen nach ihren Zelten, fröhlich und guten Mutes wegen all des Guten, das Jehova seinem Knechte David und seinem Volke Israel erwiesen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Und es geschah, als Salomo den Bau des Hauses Jehovas und des Hauses des Königs und alles Begehren Salomos, das ihm zu machen gefiel, vollendet hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'da erschien Jehova dem Salomo zum zweiten Male, wie er ihm zu Gibeon erschienen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Und Jehova sprach zu ihm: Ich habe dein Gebet und dein Flehen gehört, das du vor mir gefleht hast; ich habe dieses Haus, das du gebaut hast, geheiligt, um meinen Namen dahin zu setzen auf ewig; und meine Augen und mein Herz sollen daselbst sein allezeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Und du, wenn du vor mir wandeln wirst, so wie dein Vater David gewandelt hat, in Lauterkeit des Herzens und in Geradheit, daß du tust nach allem, was ich dir geboten habe, und wenn du meine Satzungen und meine Rechte beobachten wirst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'so werde ich den Thron deines Königtums über Israel befestigen ewiglich, so wie ich zu deinem Vater David geredet habe, indem ich sprach: Es soll dir nicht an einem Manne fehlen auf dem Throne Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Wenn ihr aber, ihr und eure Kinder, euch hinter mir abwenden und meine Gebote, meine Satzungen, die ich euch vorgelegt habe, nicht beobachten werdet, und werdet hingehen und anderen Göttern dienen und euch vor ihnen niederbeugen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'so werde ich Israel ausrotten aus dem Lande, das ich ihnen gegeben; und das Haus, welches ich meinem Namen geheiligt habe, werde ich von meinem Angesicht wegwerfen; und Israel wird zum Sprichwort und zur Spottrede werden unter allen Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Und dieses Haus, das erhaben war, jeder, der an demselben vorbeigeht, wird sich entsetzen und zischen. Und man wird sagen: Warum hat Jehova diesem Lande und diesem Hause also getan?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Und man wird sagen: Darum, daß sie Jehova, ihren Gott, der ihre Väter aus dem Lande Ägypten herausgeführt hat, verlassen und andere Götter angenommen und sich vor ihnen niedergebeugt und ihnen gedient haben: darum hat Jehova all dieses Unglück über sie gebracht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Und es geschah am Ende von zwanzig Jahren, während welcher Salomo die beiden Häuser, das Haus Jehovas und das Haus des Königs, gebaut hatte');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Hiram, der König von Tyrus, hatte Salomo mit Zedernholz und mit Zypressenholz und mit Gold nach all seinem Begehr unterstützt damals gab der König Salomo dem Hiram zwanzig Städte im Lande Galiläa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Und Hiram zog von Tyrus aus, um die Städte zu besehen, die Salomo ihm gegeben hatte; und sie waren nicht recht in seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Und er sprach: Was sind das für Städte, die du mir gegeben hast, mein Bruder! Und er nannte sie das Land Kabul bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Hiram hatte nämlich dem König hundertzwanzig Talente Gold gesandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Und dies ist die Sache mit der Fron, welche der König Salomo aushob, um das Haus Jehovas zu bauen und sein Haus und das Millo und die Mauer von Jerusalem, und Hazor und Megiddo und Geser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, '(Der Pharao, der König von Ägypten, war heraufgezogen und hatte Geser eingenommen und es mit Feuer verbrannt und die Kanaaniter, die in der Stadt wohnten, erschlagen; und er hatte es seiner Tochter, dem Weibe Salomos, als Mitgift gegeben.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Und Salomo baute Geser und Unter-Beth-Horon');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'und Baalath, und Tadmor in der Wüste, im Lande;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'und alle Vorratsstädte, die Salomo hatte, und die Wagenstädte und die Reiterstädte; und was Salomo Lust hatte zu bauen in Jerusalem und auf dem Libanon und im ganzen Lande seiner Herrschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Alles Volk, das übriggeblieben war von den Amoritern, den Hethitern, den Perisitern, den Hewitern und den Jebusitern, die nicht von den Kindern Israel waren:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'ihre Söhne, die nach ihnen im Lande übriggeblieben waren, welche die Kinder Israel nicht zu verbannen vermocht hatten, die hob Salomo zu Fronarbeitern aus bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Aber aus den Kindern Israel machte Salomo keine Sklaven, sondern sie waren Kriegsleute und seine Knechte und seine Obersten und seine Anführer, und Oberste seiner Wagen und seiner Reiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Dies sind die Oberaufseher, welche über das Werk Salomos waren: fünfhundertfünfzig, die über das Volk walteten, das an dem Werke arbeitete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Sobald die Tochter des Pharao aus der Stadt Davids in ihr Haus hinaufgezogen war, das er ihr erbaut hatte, da baute er das Millo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Und Salomo opferte dreimal im Jahre Brandopfer und Friedensopfer auf dem Altar, den er Jehova erbaut hatte; und er räucherte auf dem, der vor Jehova stand. Und er vollendete das Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Und der König Salomo machte eine Flotte zu Ezjon-Geber, das bei Eloth, am Ufer des Schilfmeeres, im Lande Edom liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Und Hiram sandte auf der Flotte seine Knechte, Schiffsleute, die des Meeres kundig waren, mit den Knechten Salomos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Und sie kamen nach Ophir und holten von dort Gold, vierhundertzwanzig Talente, und brachten es zu dem König Salomo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Und die Königin von Scheba hörte den Ruf Salomos wegen des Namens Jehovas; und sie kam, um ihn mit Rätseln zu versuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Und sie kam nach Jerusalem mit einem sehr großen Zuge, mit Kamelen, die Gewürze und Gold trugen in sehr großer Menge und Edelsteine. Und sie kam zu Salomo und redete zu ihm alles, was in ihrem Herzen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Und Salomo erklärte ihr alles, um was sie fragte; keine Sache war vor dem König verborgen, die er ihr nicht erklärt hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Und als die Königin von Scheba all die Weisheit Salomos sah, und das Haus, das er gebaut hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'und die Speise seines Tisches, und das Sitzen seiner Knechte, und das Aufwarten seiner Diener, und ihre Kleidung und seine Mundschenken, und seinen Aufgang, auf welchem er in das Haus Jehovas hinaufging, da geriet sie außer sich und sprach zu dem König:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Das Wort ist Wahrheit gewesen, das ich in meinem Lande über deine Sachen und über deine Weisheit gehört habe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'und ich habe den Worten nicht geglaubt, bis ich gekommen bin und meine Augen es gesehen haben. Und siehe, nicht die Hälfte ist mir berichtet worden; du übertriffst an Weisheit und Gut das Gerücht, das ich gehört habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Glückselig sind deine Leute, glückselig diese deine Knechte, die beständig vor dir stehen, die deine Weisheit hören!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Gepriesen sei Jehova, dein Gott, der Gefallen an dir gehabt hat, dich auf den Thron Israels zu setzen! Weil Jehova Israel ewiglich liebt, hat er dich zum König eingesetzt, um Recht und Gerechtigkeit zu üben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Und sie gab dem König hundertzwanzig Talente Gold und Gewürze in sehr großer Menge und Edelsteine; nie wieder ist eine solche Menge Gewürz gekommen wie dieses, welches die Königin von Scheba dem König Salomo gab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, '(Und auch die Flotte Hirams, die Gold aus Ophir holte, brachte aus Ophir Sandelholz in sehr großer Menge und Edelsteine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Und der König machte von dem Sandelholz ein Geländer für das Haus Jehovas und für das Haus des Königs, und Lauten und Harfen für die Sänger; also ist kein Sandelholz gekommen noch gesehen worden bis auf diesen Tag.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Und der König Salomo gab der Königin von Scheba all ihr Begehr, das sie verlangte, außer dem, was er ihr gab nach der Freigebigkeit des Königs Salomo. Und sie wandte sich und zog in ihr Land, sie und ihre Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Und das Gewicht des Goldes, welches dem Salomo in einem Jahre einkam, war sechshundertsechsundsechzig Talente Gold,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'außer dem, was von den Krämern und dem Handel der Kaufleute und von allen Königen Arabiens und den Statthaltern des Landes einkam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Und der König Salomo machte zweihundert Schilde von getriebenem Golde: sechshundert Sekel Gold zog er über jeden Schild;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'und dreihundert Tartschen von getriebenem Golde: drei Minen Gold zog er über jede Tartsche; und der König tat sie in das Haus des Waldes Libanon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Und der König machte einen großen Thron von Elfenbein und überzog ihn mit gereinigtem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Sechs Stufen waren an dem Throne, und der obere Teil des Thrones war hinten gerundet; und Armlehnen waren auf dieser und auf jener Seite an der Stelle des Sitzes, und zwei Löwen standen neben den Armlehnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'und zwölf Löwen standen da auf den sechs Stufen, auf dieser und auf jener Seite. Desgleichen ist nicht gemacht worden in irgend einem Königreiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Und alle Trinkgefäße des Königs Salomo waren von Gold, und alle Geräte des Hauses des Waldes Libanon waren von geläutertem Golde; nichts war von Silber, es wurde in den Tagen Salomos für nichts geachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Denn der König hatte eine Tarsisflotte auf dem Meere mit der Flotte Hirams; einmal in drei Jahren kam die Tarsisflotte, beladen mit Gold und Silber, Elfenbein und Affen und Pfauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Und der König Salomo war größer als alle Könige der Erde an Reichtum und an Weisheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Und die ganze Erde suchte das Angesicht Salomos, um seine Weisheit zu hören, die Gott in sein Herz gegeben hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Und sie brachten ein jeder sein Geschenk: Geräte von Silber und Geräte von Gold, und Gewänder und Waffen, und Gewürze, Rosse und Maultiere, jährlich die Gebühr des Jahres.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Und Salomo brachte zusammen Wagen und Reiter, und er hatte tausendvierhundert Wagen und zwölftausend Reiter; und er verlegte sie in die Wagenstädte und zu dem König nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Und der König machte das Silber in Jerusalem den Steinen gleich, und die Zedern machte er den Sykomoren gleich, die in der Niederung sind, an Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Und die Ausfuhr der Rosse für Salomo geschah aus Ägypten; und ein Zug Handelsleute des Königs holte einen Zug um Geld.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Und ein Wagen kam herauf und wurde ausgeführt aus Ägypten um sechshundert Sekel Silber, und ein Roß um hundertfünfzig. Und also führte man für alle Könige der Hethiter und für die Könige von Syrien durch ihre Hand aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Und der König Salomo liebte viele fremde Weiber, und zwar neben der Tochter des Pharao: moabitische, ammonitische, edomitische, zidonische, hethitische,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'von den Nationen, von welchen Jehova zu den Kindern Israel gesagt hatte: Ihr sollt nicht unter sie kommen, und sie sollen nicht unter euch kommen; gewiß, sie würden euer Herz neigen ihren Göttern nach! An diesen hing Salomo mit Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Und er hatte an Weibern siebenhundert Fürstinnen und dreihundert Kebsweiber; und seine Weiber neigten sein Herz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Und es geschah zur Zeit, als Salomo alt war, da neigten seine Weiber sein Herz anderen Göttern nach; und sein Herz war nicht ungeteilt mit Jehova, seinem Gott, wie das Herz seines Vaters David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Und Salomo wandelte der Astoreth nach, der Gottheit der Zidonier, und dem Milkom, dem Greuel der Ammoniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Und Salomo tat, was böse war in den Augen Jehovas, und er folgte Jehova nicht völlig nach wie sein Vater David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Damals baute Salomo eine Höhe dem Kamos, dem Greuel der Moabiter, auf dem Berge, der vor Jerusalem liegt, und dem Molech, dem Greuel der Kinder Ammon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Und also tat er für alle seine fremden Weiber, die ihren Göttern räucherten und opferten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Da erzürnte Jehova wider Salomo, weil er sein Herz von Jehova, dem Gott Israels, abgewandt hatte, der ihm zweimal erschienen war');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'und ihm betreffs dieser Sache geboten hatte, nicht anderen Göttern nachzuwandeln; aber er beobachtete nicht, was Jehova geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Und Jehova sprach zu Salomo: Darum daß solches bei dir gewesen ist, und du meinen Bund nicht beobachtest hast und meine Satzungen, die ich dir geboten habe, so werde ich dir das Königreich gewißlich entreißen und es deinem Knechte geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Doch in deinen Tagen will ich es nicht tun, um deines Vaters David willen: aus der Hand deines Sohnes werde ich es reißen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'nur will ich ihm nicht das ganze Königreich entreißen: einen Stamm will ich deinem Sohne geben, um meines Knechtes David willen und um Jerusalems willen, das ich erwählt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Und Jehova erweckte Salomo einen Widersacher, Hadad, den Edomiter; er war vom königlichen Samen in Edom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Es geschah nämlich, als David in Edom war, als Joab, der Heeroberste, hinaufzog, um die Erschlagenen zu begraben, und er alles Männliche in Edom erschlug');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(denn Joab blieb sechs Monate daselbst mit ganz Israel, bis er alles Männliche in Edom ausgerottet hatte):');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'da entfloh Hadad, er und edomitische Männer von den Knechten seines Vaters mit ihm, um sich nach Ägypten zu begeben; Hadad war aber ein kleiner Knabe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Und sie machten sich auf aus Midian und kamen nach Paran; und sie nahmen Männer aus Paran mit sich und kamen nach Ägypten zu dem Pharao, dem König von Ägypten. Und er gab ihm ein Haus und wies ihm Speise an und gab ihm Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Und Hadad fand große Gnade in den Augen des Pharao, und er gab ihm die Schwester seines Weibes, die Schwester der Königin Thachpenes, zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Und die Schwester der Thachpenes gebar ihm Genubath, seinen Sohn; und Thachpenes pflegte ihn im Hause des Pharao; und so war Genubath im Hause des Pharao, unter den Söhnen des Pharao.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Und als Hadad in Ägypten hörte, daß David sich zu seinen Vätern gelegt hatte, und daß Joab, der Heeroberste, tot war, da sprach Hadad zu dem Pharao: Entlasse mich, daß ich in mein Land ziehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Und der Pharao sprach zu ihm: Was mangelt dir bei mir? Und siehe, du begehrst in dein Land zu ziehen? Und er sprach: Nichts; aber entlasse mich doch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Und Gott erweckte ihm einen Widersacher, Reson, den Sohn Eljadas, der von Hadadeser, dem König von Zoba, seinem Herrn, geflohen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Und er sammelte Männer um sich und wurde Oberster einer Schar, als David die Zobaiter tötete; und sie zogen nach Damaskus und wohnten darin, und sie regierten in Damaskus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Und er wurde ein Widersacher Israels, alle Tage Salomos, und zwar neben dem Übel, das Hadad tat; und er verabscheute Israel, und er wurde König über Syrien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Und Jerobeam, der Sohn Nebats, ein Ephratiter, von Zereda (und der Name seiner Mutter war Zerua, eine Witwe), ein Knecht Salomos, auch er erhob die Hand wider den König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Und dies war die Sache, warum er die Hand wider den König erhob: Salomo baute das Millo und schloß die Lücke der Stadt seines Vaters David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Der Mann Jerobeam aber war ein wackerer Mann; und als Salomo den Jüngling sah, daß er arbeitsam war, bestellte er ihn über alle Lastarbeiter des Hauses Joseph.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Und es geschah zu selbiger Zeit, als Jerobeam einmal aus Jerusalem hinausging, da fand ihn der Prophet Achija, der Siloniter, auf dem Wege; und er hatte sich in ein neues Oberkleid gehüllt, und sie beide waren allein auf dem Felde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Da faßte Achija das neue Oberkleid, das er anhatte, und zerriß es in zwölf Stücke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'und er sprach zu Jerobeam: Nimm dir zehn Stücke; denn so spricht Jehova, der Gott Israels: Siehe, ich will das Königreich aus der Hand Salomos reißen und will dir zehn Stämme geben');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, '(aber einen Stamm soll er behalten um meines Knechtes David willen und um Jerusalems willen, der Stadt, die ich erwählt habe aus allen Stämmen Israels);');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'darum, daß sie mich verlassen und sich niedergebeugt haben vor Astoreth, der Gottheit der Zidonier, vor Kamos, dem Gott der Moabiter, und vor Milkom, dem Gott der Kinder Ammon, und nicht auf meinen Wegen gewandelt haben, zu tun, was recht ist in meinen Augen, und meine Satzungen und meine Rechte zu beobachten, wie sein Vater David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Doch will ich nicht das ganze Königreich aus seiner Hand nehmen, sondern will ihn zum Fürsten setzen alle Tage seines Lebens, um meines Knechtes David willen, den ich erwählt habe, der meine Gebote und meine Satzungen beobachtet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Aber aus der Hand seines Sohnes will ich das Königreich nehmen und es dir geben, die zehn Stämme;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'und seinem Sohne will ich einen Stamm geben, auf daß mein Knecht David alle Tage eine Leuchte vor mir habe in Jerusalem, der Stadt, die ich mir erwählt habe, um meinen Namen dahin zu setzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Und dich will ich nehmen, daß du regierest über alles, was deine Seele begehren wird, und König seiest über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Und es wird geschehen, wenn du hören wirst auf alles, was ich dir gebiete, und auf meinen Wegen wandeln und tun wirst, was recht ist in meinen Augen, indem du meine Satzungen und meine Gebote beobachtest, wie mein Knecht David getan hat, so werde ich mit dir sein und dir ein beständiges Haus bauen, wie ich es dem David gebaut habe, und werde dir Israel geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'und ich werde den Samen Davids um deswillen demütigen, doch nicht für immer. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Und Salomo suchte Jerobeam zu töten; da machte Jerobeam sich auf und entfloh nach Ägypten zu Sisak, dem König von Ägypten; und er war in Ägypten bis zum Tode Salomos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Und das Übrige der Geschichte Salomos und alles, was er getan hat, und seine Weisheit, ist das nicht geschrieben in dem Buche der Geschichte Salomos?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Und die Tage, die Salomo zu Jerusalem über ganz Israel regierte, waren vierzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Und Salomo legte sich zu seinen Vätern, und er wurde begraben in der Stadt seines Vaters David. Und Rehabeam, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Und Rehabeam ging nach Sichem; denn ganz Israel war nach Sichem gekommen, um ihn zum König zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Und es geschah, als Jerobeam, der Sohn Nebats, es hörte (er war aber noch in Ägypten, wohin er vor dem König Salomo geflohen war, und Jerobeam wohnte in Ägypten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'und sie sandten hin und riefen ihn); da kamen Jerobeam und die ganze Versammlung Israels, und sie redeten zu Rehabeam und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Dein Vater hat unser Joch hart gemacht; du aber, erleichtere nun den harten Dienst deines Vaters und sein schweres Joch, das er auf uns gelegt hat, so wollen wir dir dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Und er sprach zu ihnen: Gehet hin noch drei Tage, dann kommet wieder zu mir. Und das Volk ging hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Und der König Rehabeam beriet sich mit den Alten, die vor seinem Vater Salomo gestanden hatten, als er noch am Leben war, und sprach: Wie ratet ihr, diesem Volke Antwort zu geben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Und sie redeten zu ihm und sprachen: Wenn du heute dieses Volkes Knecht wirst und ihnen dienst und sie erhörst und gütige Worte zu ihnen redest, so werden sie deine Knechte sein alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Aber er verließ den Rat der Alten, den sie ihm geraten hatten; und er beriet sich mit den Jungen, die mit ihm aufgewachsen waren, die vor ihm standen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Und er sprach zu ihnen: Was ratet ihr, daß wir diesem Volke zur Antwort geben, welches zu mir geredet und gesagt hat: Erleichtere das Joch, das dein Vater auf uns gelegt hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Und die Jungen, die mit ihm aufgewachsen waren, redeten zu ihm und sprachen: So sollst du zu diesem Volke sprechen, das zu dir geredet und gesagt hat: Dein Vater hat unser Joch schwer gemacht, du aber erleichtere es uns; so sollst du zu ihnen reden: Mein kleiner Finger ist dicker als die Lenden meines Vaters!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Nun denn, mein Vater hat euch ein schweres Joch aufgeladen, ich aber will zu eurem Joche hinzutun; mein Vater hat euch mit Geißeln gezüchtigt, ich aber will euch mit Skorpionen züchtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Und Jerobeam und alles Volk kam am dritten Tage zu Rehabeam, so wie der König geredet und gesagt hatte: Kommet wieder zu mir am dritten Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Und der König antwortete dem Volke hart und verließ den Rat der Alten, den sie ihm gegeben hatten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'und er redete zu ihnen nach dem Rate der Jungen und sprach: Mein Vater hat euer Joch schwer gemacht, ich aber will zu eurem Joche hinzutun; mein Vater hat euch mit Geißeln gezüchtigt, ich aber will euch mit Skorpionen züchtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'So hörte der König nicht auf das Volk; denn es war eine Wendung von seiten Jehovas, auf daß er sein Wort aufrecht hielte, welches Jehova durch Achija, den Siloniter, zu Jerobeam, dem Sohne Nebats, geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Und als ganz Israel sah, daß der König nicht auf sie hörte, da gab das Volk dem König Antwort und sprach: Was haben wir für Teil an David? Und wir haben kein Erbteil am Sohne Isais! Zu deinen Zelten, Israel! Nun sieh nach deinem Hause, David! Und Israel ging nach seinen Zelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Die Kinder Israel aber, die in den Städten Judas wohnten, über sie wurde Rehabeam König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Und der König Rehabeam sandte Adoram, der über die Fron war; aber ganz Israel steinigte ihn, und er starb. Da eilte der König Rehabeam, den Wagen zu besteigen, um nach Jerusalem zu fliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'So fiel Israel vom Hause Davids ab bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Und es geschah, als ganz Israel hörte, daß Jerobeam zurückgekehrt wäre, da sandten sie hin und riefen ihn zu der Gemeinde, und machten ihn zum König über ganz Israel. Niemand folgte dem Hause Davids, außer dem Stamme Juda allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Und Rehabeam kam nach Jerusalem; und er versammelte das ganze Haus Juda und den Stamm Benjamin, hundertachtzigtausend auserlesene Krieger, um mit dem Hause Israel zu streiten, damit er das Königreich an Rehabeam, den Sohn Salomos, zurückbrächte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Da geschah das Wort Gottes zu Schemaja, dem Manne Gottes, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Sage zu Rehabeam, dem Sohne Salomos, dem König von Juda, und zu dem ganzen Hause Juda und Benjamin und zu dem übrigen Volke, und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'So spricht Jehova: Ihr sollt nicht hinaufziehen und nicht mit euren Brüdern, den Kindern Israel, streiten; kehret um, ein jeder nach seinem Hause, denn von mir aus ist diese Sache geschehen. Und sie hörten auf das Wort Jehovas und zogen wieder zurück nach dem Worte Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Und Jerobeam baute Sichem im Gebirge Ephraim und wohnte darin; und er zog von dannen aus und baute Pnuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Und Jerobeam sprach in seinem Herzen: Nun wird das Königreich an das Haus David zurückkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Wenn dieses Volk hinaufziehen wird, um im Hause Jehovas zu Jerusalem Schlachtopfer zu opfern, so wird das Herz dieses Volkes sich zu ihrem Herrn zurückwenden, zu Rehabeam, dem König von Juda; und sie werden mich töten und sich zu Rehabeam, dem König von Juda, zurückwenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Da beriet sich der König und machte zwei goldene Kälber. Und er sprach zu dem Volke: Es ist zu viel für euch, nach Jerusalem hinaufzuziehen; siehe da, Israel, deine Götter, die dich aus dem Lande Ägypten heraufgeführt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Und er stellte das eine in Bethel auf, und das andere tat er nach Dan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Und diese Sache wurde zur Sünde, und das Volk ging vor das eine hin bis nach Dan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Auch baute er Höhenhäuser, und machte Priester aus sämtlichem Volke, die nicht von den Kindern Levi waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Und Jerobeam machte ein Fest im achten Monat, am fünfzehnten Tage des Monats, wie das Fest, das in Juda stattfand, und er opferte auf dem Altar. Ebenso tat er zu Bethel, indem er den Kälbern opferte, die er gemacht hatte; und er bestellte in Bethel die Priester der Höhen, die er gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Und er opferte auf dem Altar, den er zu Bethel gemacht hatte, am fünfzehnten Tage im achten Monat, in dem Monat, den er aus seinem Herzen erdacht hatte; und er machte den Kindern Israel ein Fest, und opferte auf dem Altar und räucherte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Und siehe, ein Mann Gottes kam aus Juda, durch das Wort Jehovas, nach Bethel, und Jerobeam stand bei dem Altar, um zu räuchern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Und er rief aus wider den Altar durch das Wort Jehovas und sprach: Altar, Altar! So spricht Jehova: Siehe, ein Sohn wird dem Hause Davids geboren werden, Josia sein Name; und er wird auf dir die Priester der Höhen schlachten, die auf dir räuchern, und man wird Menschengebeine auf dir verbrennen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Und er gab an selbigem Tage ein Zeichen und sprach: Dies ist das Zeichen, von dem Jehova geredet hat: Siehe, der Altar wird reißen und die Fettasche, die darauf ist, verschüttet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Und es geschah, als der König das Wort des Mannes Gottes hörte, das er wider den Altar zu Bethel ausgerufen hatte, da streckte Jerobeam seine Hand aus von dem Altar herab und sprach: Greifet ihn! Da verdorrte seine Hand, die er wider ihn ausgestreckt hatte, und er konnte sie nicht wieder an sich ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Und der Altar riß, und die Fettasche wurde vom Altar verschüttet, nach dem Zeichen, welches der Mann Gottes durch das Wort Jehovas gegeben hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Da antwortete der König und sprach zu dem Manne Gottes: Flehe doch Jehova, deinen Gott, an und bete für mich, daß meine Hand mir wiedergegeben werde. Und der Mann Gottes flehte Jehova an, und die Hand des Königs wurde ihm wiedergegeben und war wie zuvor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Und der König redete zu dem Manne Gottes: Komm mit mir ins Haus und stärke dich, und ich will dir ein Geschenk geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Aber der Mann Gottes sprach zu dem König: Wenn du mir die Hälfte deines Hauses gäbest, so würde ich nicht mit dir hingehen; und ich werde kein Brot essen und kein Wasser trinken an diesem Orte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Denn also ist mir geboten worden durch das Wort Jehovas und gesagt: Du sollst kein Brot essen und kein Wasser trinken, und du sollst nicht auf dem Wege zurückkehren, den du gegangen bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Und er ging auf einem anderen Wege und kehrte nicht auf dem Wege zurück, auf welchem er nach Bethel gekommen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Ein alter Prophet aber wohnte zu Bethel; und einer seiner Söhne kam und erzählte ihm alles, was der Mann Gottes an dem Tage zu Bethel getan hatte; die Worte, die er zum König geredet hatte, die erzählten sie auch ihrem Vater.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Und ihr Vater sprach zu ihnen: Welchen Weg ist er gegangen? Und seine Söhne hatten den Weg gesehen, den der Mann Gottes gegangen, der aus Juda gekommen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Da sprach er zu seinen Söhnen: Sattelt mir den Esel! Und sie sattelten ihm den Esel, und er ritt darauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Und er ritt dem Manne Gottes nach und fand ihn unter einer Terebinthe sitzen; und er sprach zu ihm: Bist du der Mann Gottes, der von Juda gekommen ist? Und er sprach: Ich bin\'s.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Da sprach er zu ihm: Komm mit mir nach Hause und iß Brot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Er aber sprach: Ich kann nicht mit dir umkehren und mit dir hineingehen, und ich werde kein Brot essen und kein Wasser mit dir trinken an diesem Orte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Denn ein Wort ist zu mir geschehen durch das Wort Jehovas: Du sollst kein Brot essen und kein Wasser daselbst trinken; du sollst nicht auf dem Wege zurückkehren, auf welchem du gegangen bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Und er sprach zu ihm: Auch ich bin ein Prophet, wie du; und ein Engel hat zu mir geredet durch das Wort Jehovas und gesagt: Bringe ihn mit dir in dein Haus zurück, daß er Brot esse und Wasser trinke. Er belog ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Da kehrte er mit ihm zurück, und aß Brot in seinem Hause und trank Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Und es geschah, während sie zu Tische saßen, da geschah das Wort Jehovas zu dem Propheten, der ihn zurückgebracht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Und er rief dem Manne Gottes zu, der aus Juda gekommen war, und sprach: So spricht Jehova: Darum daß du gegen den Befehl Jehovas widerspenstig gewesen bist und nicht beobachtet hast das Gebot, das Jehova, dein Gott, dir geboten hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'und bist umgekehrt und hast Brot gegessen und Wasser getrunken an dem Orte, von welchem er zu dir geredet hat: Iß kein Brot und trinke kein Wasser! So soll dein Leichnam nicht in das Grab deiner Väter kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Und es geschah, nachdem er Brot gegessen und nachdem er getrunken hatte, da sattelte er ihm, dem Propheten, den er zurückgebracht hatte, den Esel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Und er zog fort; und es fand ihn ein Löwe auf dem Wege und tötete ihn. Und sein Leichnam lag hingestreckt auf dem Wege, und der Esel stand daneben, und der Löwe stand neben dem Leichnam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Und siehe, da gingen Leute vorüber und sahen den Leichnam hingestreckt auf dem Wege, und den Löwen neben dem Leichnam stehen; und sie kamen und sagten es in der Stadt, in welcher der alte Prophet wohnte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Als nun der Prophet, der ihn von dem Wege zurückgeführt hatte, es hörte, sprach er: Das ist der Mann Gottes, der gegen den Befehl Jehovas widerspenstig gewesen ist; und so hat Jehova ihn dem Löwen preisgegeben: der hat ihn zerrissen und getötet, nach dem Worte Jehovas, das er zu ihm geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Und er redete zu seinen Söhnen und sprach: Sattelt mir den Esel! Und sie sattelten ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Und er ritt hin und fand seinen Leichnam hingestreckt auf dem Wege, und den Esel und den Löwen neben dem Leichnam stehen; der Löwe hatte den Leichnam nicht gefressen und den Esel nicht zerrissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Und der Prophet hob den Leichnam des Mannes Gottes auf und legte ihn auf den Esel und brachte ihn zurück. Und er kam in die Stadt des alten Propheten, um ihn zu beklagen und zu begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Und er legte seinen Leichnam in sein eigenes Grab; und man klagte über ihn: Ach, mein Bruder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Und es geschah, nachdem er ihn begraben hatte, da sprach er zu seinen Söhnen und sagte: Wenn ich gestorben bin, so begrabet mich in dem Grabe, in welchem der Mann Gottes begraben ist; leget meine Gebeine neben seine Gebeine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Denn das Wort wird gewißlich geschehen, welches er durch das Wort Jehovas ausgerufen hat wider den Altar, der zu Bethel ist, und wider alle Höhenhäuser, die in den Städten Samarias sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Nach dieser Begebenheit kehrte Jerobeam nicht um von seinem bösen Wege; und er machte wiederum aus sämtlichem Volke Priester der Höhen: wer Lust hatte, den weihte er, daß er ein Priester der Höhen würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Und diese Sache wurde dem Hause Jerobeams zur Sünde, und zur Vertilgung und zur Vernichtung vom Erdboden hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Zu selbiger Zeit erkrankte Abija, der Sohn Jerobeams.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Und Jerobeam sprach zu seinem Weibe: Mache dich doch auf und verstelle dich, damit man nicht wisse, daß du das Weib Jerobeams bist, und gehe hin nach Silo: Siehe, daselbst ist Achija, der Prophet; er ist es, der über mich geredet hat, daß ich König über dieses Volk sein würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Und nimm mit dir zehn Brote und Backwerk und einen Krug Honig und gehe zu ihm; er wird dir kundtun, was dem Knaben geschehen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Und das Weib Jerobeams tat also: Sie machte sich auf und ging nach Silo und kam in das Haus Achijas. Achija aber konnte nicht sehen, denn seine Augen waren starr wegen seines Alters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Und Jehova hatte zu Achija gesagt: Siehe, das Weib Jerobeams kommt, um etwas von dir zu erfragen betreffs ihres Sohnes, denn er ist krank; so und so sollst du zu ihr reden; es wird aber geschehen, wenn sie hereinkommt, so wird sie sich fremd stellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Und es geschah, als Achija das Geräusch ihrer Füße hörte, als sie zum Eingang hereinkam, da sprach er: Komm herein, Weib Jerobeams! Warum stellst du dich denn fremd? Ich aber bin mit hartem Worte zu dir gesandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Gehe hin, sprich zu Jerobeam: So spricht Jehova, der Gott Israels: Weil ich dich aus der Mitte des Volkes erhoben und dich als Fürst gesetzt habe über mein Volk Israel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'und das Königreich dem Hause Davids entrissen und es dir gegeben habe; du aber nicht gewesen bist wie mein Knecht David, der meine Gebote beobachtet hat und mir nachgefolgt ist mit seinem ganzen Herzen, daß er nur tat, was recht ist in meinen Augen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'sondern hast es ärger gemacht als alle, die vor dir gewesen sind, und bist hingegangen und hast dir andere Götter und gegossene Bilder gemacht, um mich zu reizen, und hast mich hinter deinen Rücken geworfen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Darum, siehe, will ich Unglück über das Haus Jerobeams bringen, und ich werde von Jerobeam ausrotten, was männlich ist, den Gebundenen und den Freien in Israel; und ich werde hinter dem Hause Jerobeams her ausfegen, wie man den Kot ausfegt, bis es mit ihm aus ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Wer von Jerobeam in der Stadt stirbt, den sollen die Hunde fressen, und wer auf dem Felde stirbt, den sollen die Vögel des Himmels fressen; denn Jehova hat es geredet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Und du, mache dich auf, gehe nach deinem Hause; wenn deine Füße in die Stadt eintreten, wird das Kind sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Und ganz Israel wird um ihn klagen und ihn begraben; denn von Jerobeam wird dieser allein in ein Grab kommen, weil an ihm etwas Gutes gegen Jehova, den Gott Israels, gefunden worden ist im Hause Jerobeams.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Und Jehova wird sich einen König über Israel erwecken, der das Haus Jerobeams ausrotten wird an jenem Tage; und was? Sogar jetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Und Jehova wird Israel schlagen, wie das Rohr im Wasser schwankt; und er wird Israel herausreißen aus diesem guten Lande, das er ihren Vätern gegeben hat, und wird sie zerstreuen jenseit des Stromes, darum daß sie ihre Ascherim gemacht haben, indem sie Jehova reizten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Und er wird Israel dahingeben um der Sünden Jerobeams willen, die er begangen und wodurch er Israel sündigen gemacht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Und das Weib Jerobeams machte sich auf und ging und kam nach Tirza; sie war eben an die Schwelle des Hauses gekommen, da starb der Knabe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Und ganz Israel begrub ihn und klagte um ihn, nach dem Worte Jehovas, das er durch seinen Knecht Achija, den Propheten, geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Und das Übrige der Geschichte Jerobeams, wie er gestritten und wie er regiert hat, siehe, das ist geschrieben in dem Buche der Chronika der Könige von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Und die Tage, die Jerobeam regierte, waren zweiundzwanzig Jahre; und er legte sich zu seinen Vätern. Und Nadab, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Und Rehabeam, der Sohn Salomos, regierte in Juda. Einundvierzig Jahre war Rehabeam alt, als er König wurde, und er regierte siebzehn Jahre zu Jerusalem, der Stadt, die Jehova aus allen Stämmen Israels erwählt hatte, um seinen Namen dorthin zu setzen. Und der Name seiner Mutter war Naama, die Ammonitin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Und Juda tat, was böse war in den Augen Jehovas; und sie reizten ihn zur Eifersucht durch ihre Sünden, die sie begingen, mehr als alles, was ihre Väter getan hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Und auch sie bauten sich Höhen und Bildsäulen und Ascherim auf jedem hohen Hügel und unter jedem grünen Baume.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Und es waren auch Buhler im Lande; sie taten nach allen Greueln der Nationen, die Jehova vor den Kindern Israel ausgetrieben hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Und es geschah im fünften Jahre des Königs Rehabeam, da zog Sisak, der König von Ägypten, wider Jerusalem herauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Und er nahm die Schätze des Hauses Jehovas weg und die Schätze des Hauses des Königs, ja, alles nahm er weg; und er nahm alle goldenen Schilde weg, die Salomo gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Und der König Rehabeam machte an ihrer Statt eherne Schilde, und er befahl sie unter die Hand der Obersten der Läufer, die den Eingang des Hauses des Königs bewachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Und es geschah: So oft der König in das Haus Jehovas ging, trugen die Läufer dieselben, und brachten sie dann wieder in das Gemach der Läufer zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Und das Übrige der Geschichte Rehabeams und alles, was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Und es war Krieg zwischen Rehabeam und Jerobeam alle ihre Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Und Rehabeam legte sich zu seinen Vätern, und er wurde begraben bei seinen Vätern in der Stadt Davids. Und der Name seiner Mutter war Naama, die Ammonitin. Und Abijam, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Und im achtzehnten Jahre des Königs Jerobeam, des Sohnes Nebats, wurde Abijam König über Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Er regierte drei Jahre zu Jerusalem; und der Name seiner Mutter war Maaka, die Tochter Absaloms.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Und er wandelte in allen Sünden seines Vaters, welche dieser vor ihm getan hatte; und sein Herz war nicht ungeteilt mit Jehova, seinem Gott, wie das Herz seines Vaters David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Dennoch gab ihm Jehova, sein Gott, um Davids willen eine Leuchte in Jerusalem, indem er seinen Sohn nach ihm erweckte und Jerusalem bestehen ließ;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'weil David getan hatte, was recht war in den Augen Jehovas und von allem, was er ihm geboten hatte, nicht abgewichen war alle Tage seines Lebens, außer in der Sache Urijas, des Hethiters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Und es war Krieg zwischen Rehabeam und Jerobeam alle Tage seines Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Und das Übrige der Geschichte Abijams und alles, was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda? Und es war Krieg zwischen Abijam und Jerobeam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Und Abijam legte sich zu seinen Vätern, und man begrub ihn in der Stadt Davids. Und Asa, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Und im zwanzigsten Jahre Jerobeams, des Königs von Israel, wurde Asa König über Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Und er regierte einundvierzig Jahre zu Jerusalem; und der Name seiner Mutter war Maaka, die Tochter Absaloms.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Und Asa tat, was recht war in den Augen Jehovas, wie sein Vater David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Und er schaffte die Buhler aus dem Lande und tat alle Götzen hinweg, die seine Väter gemacht hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Und auch Maaka, seine Mutter, die setzte er ab, daß sie nicht mehr Königin wäre, weil sie der Aschera ein Götzenbild gemacht hatte; und Asa rottete ihr Götzenbild aus und verbrannte es im Tale Kidron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Die Höhen aber wichen nicht; doch das Herz Asas war ungeteilt mit Jehova alle seine Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Und er brachte die geheiligten Dinge seines Vaters und seine geheiligten Dinge in das Haus Jehovas: Silber und Gold und Geräte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Und es war Krieg zwischen Asa und Baesa, dem König von Israel, alle ihre Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Und Baesa, der König von Israel, zog wider Juda herauf; und er baute Rama, um Asa, dem König von Juda, niemand aus-und eingehen zu lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Da nahm Asa alles Silber und Gold, das in den Schätzen des Hauses Jehovas übrig war, und die Schätze des Hauses des Königs, und gab sie in die Hand seiner Knechte; und der König Asa sandte sie zu Ben-Hadad, dem Sohne Tabrimmons, des Sohnes Hesjons, dem König von Syrien, der zu Damaskus wohnte, und ließ ihm sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Ein Bund ist zwischen mir und dir, zwischen meinem Vater und deinem Vater. Siehe, ich sende dir ein Geschenk an Silber und Gold: Wohlan! Brich deinen Bund mit Baesa, dem König von Israel, daß er von mir abziehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Und Ben-Hadad hörte auf den König Asa, und er sandte seine Heerobersten wider die Städte Israels und schlug Ijon und Dan und Abel-Beth-Maaka, und ganz Kinneroth nebst dem ganzen Lande Naphtali.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Und es geschah, als Baesa es hörte, da ließ er von dem Bau Ramas ab und blieb in Tirza.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Der König Asa aber ließ ganz Juda aufrufen, keiner war frei; und sie schafften die Steine Ramas und das Holz weg, womit Baesa gebaut hatte; und der König Asa baute damit Geba-Benjamin und Mizpa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Und das Übrige der ganzen Geschichte Asas und alle seine Macht, und alles, was er getan, und die Städte, die er gebaut hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda? Doch zur Zeit seines Alters erkrankte er an seinen Füßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Und Asa legte sich zu seinen Vätern, und er wurde bei seinen Vätern begraben in der Stadt seines Vaters David. Und Josaphat, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Und Nadab, der Sohn Jerobeams, wurde König über Israel im zweiten Jahre Asas, des Königs von Juda; und er regierte zwei Jahre über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Und er tat, was böse war in den Augen Jehovas, und wandelte auf dem Wege seines Vaters und in seiner Sünde, wodurch er Israel sündigen gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Und Basea, der Sohn Achijas, vom Hause Issaschar, machte eine Verschwörung wider ihn; und Basea erschlug ihn zu Gibbethon, welches den Philistern gehörte, als Nadab und ganz Israel Gibbethon belagerten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Und Baesa tötete ihn im dritten Jahre Asas, des Königs von Juda, und ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Und es geschah, sobald er König geworden war, erschlug er das ganze Haus Jerobeams; er ließ von Jerobeam nichts übrig, was Odem hatte, bis er ihn vertilgt hatte, nach dem Worte Jehovas, das er durch seinen Knecht Achija, den Siloniter, geredet hatte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'wegen der Sünden Jerobeams, die er begangen und wodurch er Israel sündigen gemacht, durch seine Reizung, wodurch er Jehova, den Gott Israels, gereizt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Und das Übrige der Geschichte Nadabs und alles, was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Und es war Krieg zwischen Asa und Baesa, dem König von Israel, alle ihre Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Im dritten Jahre Asas, des Königs von Juda, wurde Baesa, der Sohn Achijas, König über ganz Israel zu Tirza, vierundzwanzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Und er tat, was böse war in den Augen Jehovas und wandelte auf den Wegen Jerobeams und in seiner Sünde, wodurch er Israel sündigen gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Und es geschah das Wort Jehovas zu Jehu, dem Sohne Hananis, wider Baesa also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Weil ich dich aus dem Staube erhoben und dich als Fürst über mein Volk Israel gesetzt habe, du aber auf dem Wege Jerobeams gewandelt und mein Volk Israel sündigen gemacht hast, so daß sie mich reizen durch ihre Sünden:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'siehe, so werde ich hinter Baesa und hinter seinem Hause her ausfegen und werde dein Haus machen wie das Haus Jerobeams, des Sohnes Nebats.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Wer von Baesa in der Stadt stirbt, den sollen die Hunde fressen, und wer von ihm auf dem Felde stirbt, den sollen die Vögel des Himmels fressen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Und das Übrige der Geschichte Baesas und was er getan hat, und seine Macht, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Und Baesa legte sich zu seinen Vätern, und er wurde begraben zu Tirza. Und Ela, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Und auch war durch Jehu, den Sohn Hananis, den Propheten, das Wort Jehovas wider Baesa und wider sein Haus ergangen, sowohl wegen all des Bösen, das er in den Augen Jehovas getan hatte, um ihn durch das Tun seiner Hände zu reizen, so daß er dem Hause Jerobeams gleich war, als auch weil er dieses erschlagen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Im sechsundzwanzigsten Jahre Asas, des Königs von Juda, wurde Ela, der Sohn Baesas, König über Israel zu Tirza, zwei Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Und sein Knecht Simri, der Oberste über die Hälfte der Wagen, machte eine Verschwörung wider ihn. Er aber trank und berauschte sich zu Tirza, im Hause Arzas, der über das Haus zu Tirza war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Und Simri kam herein und erschlug ihn und tötete ihn im siebenundzwanzigsten Jahre Asas, des Königs von Juda; und er ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Und es geschah, als er König war, sobald er auf seinem Throne saß, erschlug er das ganze Haus Baesas; er ließ nichts von ihm übrig, was männlich war, weder seine Blutsverwandten noch seine Freunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'So vertilgte Simri das ganze Haus Baesas nach dem Worte Jehovas, das er durch Jehu, den Propheten, wider Baesa geredet hatte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'wegen all der Sünden Baesas und der Sünden Elas, seines Sohnes, die sie begangen und wodurch sie Israel sündigen gemacht hatten, so daß sie Jehova, den Gott Israels, reizten durch ihre nichtigen Götzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Und das Übrige der Geschichte Elas und alles, was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Im siebenundzwanzigsten Jahre Asas, des Königs von Juda, regierte Simri sieben Tage zu Tirza. Das Volk belagerte nämlich Gibbethon, welches den Philistern gehörte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Und als das belagernde Volk sagen hörte: Simri hat eine Verschwörung gemacht, und hat auch den König erschlagen, da machte ganz Israel Omri, den Heerobersten, zum König über Israel, an selbigem Tage, im Lager.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Und Omri, und ganz Israel mit ihm, zog von Gibbethon hinauf, und sie belagerten Tirza.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Und es geschah, als Simri sah, daß die Stadt eingenommen war, da ging er in die Burg des Königshauses und verbrannte das Königshaus über sich mit Feuer und starb:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'wegen seiner Sünden, die er begangen hatte, indem er tat, was böse war in den Augen Jehovas, indem er wandelte auf dem Wege Jerobeams und in seiner Sünde, die er getan, so daß er Israel sündigen gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Und das Übrige der Geschichte Simris und seine Verschwörung, die er gemacht hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Damals teilte sich das Volk Israel in zwei Hälften: die eine Hälfte des Volkes folgte Tibni, dem Sohne Ginaths, um ihn zum König zu machen; und die andere Hälfte folgte Omri.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Aber das Volk, welches Omri folgte, überwältigte das Volk, welches Tibni, dem Sohne Ginaths, folgte; und Tibni starb, und Omri wurde König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Im einunddreißigsten Jahre Asas, des Königs von Juda, wurde Omri König über Israel, zwölf Jahre; zu Tirza regierte er sechs Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Und er kaufte den Berg Samaria von Schemer um zwei Talente Silber; und er bebaute den Berg und gab der Stadt, die er gebaut hatte, den Namen Samaria, nach dem Namen Schemers, des Herrn des Berges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Und Omri tat, was böse war in den Augen Jehovas; und er machte es ärger als alle, die vor ihm gewesen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Und er wandelte auf allen Wegen Jerobeams, des Sohnes Nebats, und in seinen Sünden, wodurch er Israel sündigen gemacht hatte, so daß sie Jehova, den Gott Israels, reizten durch ihre nichtigen Götzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Und das Übrige der Geschichte Omris, was er getan, und seine Macht, die er ausgeübt hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Und Omri legte sich zu seinen Vätern, und er wurde zu Samaria begraben. Und Ahab, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Und Ahab, der Sohn Omris, wurde König über Israel im achtunddreißigsten Jahre Asas, des Königs von Juda; und Ahab, der Sohn Omris, regierte über Israel zu Samaria zweiundzwanzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Und Ahab, der Sohn Omris, tat, was böse war in den Augen Jehovas, mehr als alle, die vor ihm gewesen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Und es geschah war es zu wenig, daß er in den Sünden Jerobeams, des Sohnes Nebats, wandelte? daß er Isebel, die Tochter Ethbaals, des Königs der Zidonier, zum Weibe nahm; und er ging hin und diente dem Baal und beugte sich vor ihm nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Und er errichtete dem Baal einen Altar im Hause des Baal, das er zu Samaria gebaut hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'auch machte Ahab die Aschera. Und Ahab tat mehr, um Jehova, den Gott Israels, zu reizen, als alle Könige von Israel, die vor ihm gewesen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'In seinen Tagen baute Hiel, der Betheliter, Jericho wieder auf. Mit Abiram, seinem Erstgeborenen, legte er ihren Grund, und mit Segub, seinem Jüngsten, stellte er ihre Tore auf, nach dem Worte Jehovas, das er durch Josua, den Sohn Nuns, geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Und Elia, der Tisbiter, von den Beisassen Gileads, sprach zu Ahab: So wahr Jehova lebt, der Gott Israels, vor dessen Angesicht ich stehe, wenn es in diesen Jahren Tau und Regen geben wird, es sei denn auf mein Wort!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Und es geschah das Wort Jehovas zu ihm also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Gehe von hinnen und wende dich nach Osten, und verbirg dich am Bache Krith, der vor dem Jordan ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Und es soll geschehen, aus dem Bache wirst du trinken, und ich habe den Raben geboten, dich daselbst zu versorgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Und er ging hin und tat nach dem Worte Jehovas: er ging hin und blieb am Bache Krith, der vor dem Jordan ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Und die Raben brachten ihm Brot und Fleisch am Morgen, und Brot und Fleisch am Abend, und er trank aus dem Bache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Und es geschah nach Verlauf einer Zeit, da vertrocknete der Bach, denn es war kein Regen im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Da geschah das Wort Jehovas zu ihm also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Mache dich auf, gehe nach Zarpath, das zu Zidon gehört, und bleibe daselbst; siehe ich habe daselbst einer Witwe geboten, dich zu versorgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Und er machte sich auf und ging nach Zarpath; und als er an den Eingang der Stadt kam, siehe, da war eine Witwe daselbst, die Holz auflas. Und er rief ihr zu und sprach: Hole mir doch ein wenig Wasser im Gefäß, daß ich trinke!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Und als sie hinging, um es zu holen, rief er ihr zu und sprach: Hole mir doch einen Bissen Brot in deiner Hand!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Und sie sprach: So wahr Jehova, dein Gott lebt, wenn ich einen Kuchen habe außer einer Handvoll Mehl im Topfe und ein wenig Öl im Kruge! Und siehe, ich lese ein paar Holzstücke auf und will hineingehen und es mir und meinem Sohne bereiten, daß wir es essen und dann sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Und Elia sprach zu ihr: Fürchte dich nicht! Gehe hinein, tue nach deinem Worte; doch bereite mir zuerst einen kleinen Kuchen davon und bringe ihn mir heraus; und dir und deinem Sohne bereite danach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Denn so spricht Jehova, der Gott Israels: Das Mehl im Topfe soll nicht ausgehen, und das Öl im Kruge nicht abnehmen bis auf den Tag, da Jehova Regen geben wird auf den Erdboden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Und sie ging hin und tat nach dem Worte Elias; und sie aß, er und sie, und ihr Haus, viele Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Das Mehl im Topfe ging nicht aus, und das Öl im Kruge nahm nicht ab, nach dem Worte Jehovas, das er durch Elia geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Und es geschah nach diesen Dingen, da wurde der Sohn des Weibes, der Hauswirtin, krank; und seine Krankheit wurde sehr schwer, so daß kein Odem mehr in ihm blieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Da sprach sie zu Elia: Was haben wir miteinander zu schaffen, Mann Gottes? Du bist zu mir gekommen, um meine Ungerechtigkeit ins Gedächtnis zu bringen und meinen Sohn zu töten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Und er sprach zu ihr: Gib mir deinen Sohn her. Und er nahm ihn von ihrem Schoße und brachte ihn hinauf in das Obergemach, wo er wohnte, und legte ihn auf sein Bett.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Und er rief zu Jehova und sprach: Jehova, mein Gott, hast du gar an der Witwe, bei der ich mich aufhalte, übel getan, ihren Sohn zu töten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Und er streckte sich dreimal über das Kind, und rief zu Jehova und sprach: Jehova, mein Gott, laß doch die Seele dieses Kindes wieder in dasselbe zurückkehren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Und Jehova hörte auf die Stimme Elias, und die Seele des Kindes kehrte wieder in dasselbe zurück, und es wurde lebendig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Da nahm Elia das Kind und brachte es von dem Obergemach in das Haus hinab und gab es seiner Mutter; und Elia sprach: Siehe, dein Sohn lebt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Und das Weib sprach zu Elia: Nunmehr erkenne ich, daß du ein Mann Gottes bist, und daß das Wort Jehovas in deinem Munde Wahrheit ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Und es vergingen viele Tage, da geschah das Wort Jehovas zu Elia im dritten Jahre also: Gehe hin, zeige dich Ahab; und ich will Regen geben auf den Erdboden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Und Elia ging hin, um sich Ahab zu zeigen. Die Hungersnot aber war stark in Samaria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Und Ahab rief Obadja, der über das Haus war. (Obadja aber fürchtete Jehova sehr;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'und es geschah, als Isebel die Propheten Jehovas ausrottete, da nahm Obadja hundert Propheten und versteckte sie, je fünfzig Mann in eine Höhle, und versorgte sie mit Brot und Wasser.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Und Ahab sprach zu Obadja: Gehe durch das Land zu allen Wasserquellen und zu allen Bächen; vielleicht finden wir Gras, daß wir Rosse und Maultiere am Leben erhalten und nichts von dem Vieh ausrotten müssen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Und sie teilten das Land unter sich, um es zu durchziehen; Ahab ging auf einem Wege allein, und Obadja ging auf einem Wege allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Und als Obadja auf dem Wege war, siehe, da kam Elia ihm entgegen. Und er erkannte ihn und fiel auf sein Angesicht und sprach: Bist du es, mein Herr Elia?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Und er sprach zu ihm: Ich bin\'s; gehe hin, sage deinem Herrn: Siehe, Elia ist da!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Und er sprach: Was habe ich gesündigt, daß du deinen Knecht in die Hand Ahabs geben willst, daß er mich töte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'So wahr Jehova, dein Gott, lebt, wenn es eine Nation oder ein Königreich gibt, wohin mein Herr nicht gesandt hat, um dich zu suchen! Und sprachen sie: Er ist nicht da, so ließ er das Königreich und die Nation schwören, daß man dich nicht gefunden hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Und nun sprichst du: Gehe hin, sage deinem Herrn: Siehe, Elia ist da!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Und es wird geschehen, wenn ich von dir weggehe, so wird der Geist Jehovas dich tragen, ich weiß nicht wohin; und komme ich, es Ahab zu berichten, und er findet dich nicht, so wird er mich töten. Und dein Knecht fürchtet doch Jehova von meiner Jugend an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Ist meinem Herrn nicht berichtet worden, was ich getan habe, als Isebel die Propheten Jehovas tötete? Daß ich von den Propheten Jehovas hundert Mann versteckte, je fünfzig Mann in eine Höhle, und sie mit Brot und Wasser versorgte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Und nun sprichst du: Gehe hin, sage deinem Herrn: Siehe, Elia ist da! und er wird mich töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Aber Elia sprach: So wahr Jehova der Heerscharen lebt, vor dessen Angesicht ich stehe, heute werde ich mich ihm zeigen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Da ging Obadja hin, Ahab entgegen, und berichtete es ihm. Und Ahab ging hin, Elia entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Und es geschah, als Ahab Elia sah, da sprach Ahab zu ihm: Bist du da, der Israel in Trübsal bringt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Und er sprach: Ich habe Israel nicht in Trübsal gebracht, sondern du und das Haus deines Vaters, indem ihr die Gebote Jehovas verlassen habt, und du den Baalim nachgewandelt bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Und nun sende hin, versammle ganz Israel zu mir nach dem Berge Karmel, und die vierhundert und fünfzig Propheten des Baal und die vierhundert Propheten der Aschera, die am Tische Isebels essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Da sandte Ahab unter allen Kindern Israel umher und versammelte die Propheten nach dem Berge Karmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Da trat Elia zu dem ganzen Volke hin und sprach: Wie lange hinket ihr auf beiden Seiten? Wenn Jehova Gott ist, so wandelt ihm nach; wenn aber der Baal, so wandelt ihm nach! Und das Volk antwortete ihm kein Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Und Elia sprach zu dem Volke: Ich allein bin übriggeblieben, ein Prophet Jehovas, und der Propheten des Baal sind vierhundertfünfzig Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'So gebe man uns zwei Farren; und sie mögen sich den einen von den Farren auswählen und ihn zerstücken und aufs Holz legen, aber sie sollen kein Feuer daran legen; und ich, ich werde den anderen Farren zurichten und aufs Holz legen, aber ich werde kein Feuer daran legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Und rufet ihr den Namen eures Gottes an, und ich, ich werde den Namen Jehovas anrufen; und der Gott, der mit Feuer antworten wird, der sei Gott! Da antwortete das ganze Volk und sprach: Das Wort ist gut. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Und Elia sprach zu den Propheten des Baal: Wählet euch einen von den Farren aus und richtet ihn zuerst zu, denn ihr seid die Vielen, und rufet den Namen eures Gottes an; aber ihr sollt kein Feuer daran legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Und sie nahmen den Farren, den man ihnen gegeben hatte, und richteten ihn zu; und sie riefen den Namen des Baal an vom Morgen bis zum Mittag und sprachen: Baal, antworte uns! Aber da war keine Stimme, und niemand antwortete. Und sie hüpften um den Altar, den man gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Und es geschah am Mittag, da verspottete sie Elia und sprach: Rufet mit lauter Stimme, denn er ist ja ein Gott! Denn er ist in Gedanken, oder er ist beiseite gegangen, oder er ist auf der Reise; vielleicht schläft er und wird aufwachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Und sie riefen mit lauter Stimme und ritzten sich nach ihrer Weise mit Schwertern und mit Lanzen, bis sie Blut an sich vergossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Und es geschah, als der Mittag vorüber war, da weissagten sie bis zur Zeit, da man das Speisopfer opfert; aber da war keine Stimme und keine Antwort und kein Aufmerken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Da sprach Elia zu dem ganzen Volke: Tretet her zu mir! Und das ganze Volk trat zu ihm hin. Und er stellte den niedergerissenen Altar Jehovas wieder her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Und Elia nahm zwölf Steine, nach der Zahl der Stämme der Söhne Jakobs, zu welchem das Wort Jehovas geschehen war, indem er sprach: Israel soll dein Name sein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Und er baute von den Steinen einen Altar im Namen Jehovas; und er machte rings um den Altar einen Graben im Umfange von zwei Maß Saat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'und er richtete das Holz zu und zerstückte den Farren und legte ihn auf das Holz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Und er sprach: Füllet vier Eimer mit Wasser, und gießet es auf das Brandopfer und auf das Holz. Und er sprach: Tut es zum zweiten Male! Und sie taten es zum zweiten Male. Und er sprach: Tut es zum dritten Male! Und sie taten es zum dritten Male.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Und das Wasser lief rings um den Altar; und auch den Graben füllte er mit Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Und es geschah zur Zeit, da man das Speisopfer opfert, da trat Elia, der Prophet, herzu und sprach: Jehova, Gott Abrahams, Isaaks und Israels! Heute werde kund, daß du Gott in Israel bist, und ich dein Knecht, und daß ich nach deinem Worte alles dieses getan habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Antworte mir, Jehova, antwortete mir, damit dieses Volk wisse, daß du, Jehova, Gott bist, und daß du ihr Herz zurückgewendet hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Da fiel Feuer Jehovas herab und verzehrte das Brandopfer und das Holz und die Steine und die Erde; und das Wasser, das im Graben war, leckte es auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Und als das ganze Volk es sah, da fielen sie auf ihr Angesicht und sprachen: Jehova, er ist Gott! Jehova, er ist Gott! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Und Elia sprach zu ihnen: Greifet die Propheten des Baal, keiner von ihnen entrinne! Und sie griffen sie; und Elia führte sie hinab an den Bach Kison und schlachtete sie daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Und Elia sprach zu Ahab: Gehe hinauf, iß und trink, denn es ist ein Rauschen eines gewaltigen Regens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Und Ahab ging hinauf, um zu essen und zu trinken. Elia aber stieg auf den Gipfel des Karmel; und er beugte sich zur Erde und tat sein Angesicht zwischen seine Knie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Und er sprach zu seinem Knaben: Gehe doch hinauf, schaue nach dem Meere hin. Und er ging hinauf und schaute, und er sprach: Es ist nichts da. Und er sprach: Gehe wieder hin, siebenmal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Und es geschah beim siebten Male, da sprach er: Siehe, eine Wolke, klein wie eines Mannes Hand, steigt aus dem Meere herauf. Da sprach er: Gehe hinauf, sprich zu Ahab: Spanne an und fahre hinab, daß der Regen dich nicht aufhalte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Und es geschah unterdessen, da ward der Himmel schwarz von Wolken und Wind, und es kam ein starker Regen; und Ahab bestieg den Wagen und ging nach Jisreel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Und die Hand Jehovas kam über Elia; und er gürtete seine Lenden und lief vor Ahab her bis nach Jisreel hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Und Ahab berichtete der Isebel alles, was Elia getan hatte, und alles, wie er alle Propheten mit dem Schwerte getötet hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Da sandte Isebel einen Boten zu Elia und ließ ihm sagen: So sollen mir die Götter tun und so hinzufügen, wenn ich nicht morgen um diese Zeit dein Leben dem Leben eines von ihnen gleich mache!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Und als er das sah, machte er sich auf und ging fort um seines Lebens willen, und kam nach Beerseba, das zu Juda gehört; und er ließ seinen Knaben dort zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Er selbst aber ging in die Wüste, eine Tagereise weit, und kam und setzte sich unter einen Ginsterstrauch. Und er bat, daß seine Seele stürbe, und sprach: Es ist genug; nimm nun, Jehova, meine Seele, denn ich bin nicht besser als meine Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Und er legte sich nieder und schlief ein unter dem Ginsterstrauch. Und siehe da, ein Engel rührte ihn an und sprach zu ihm: Stehe auf, iß!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Und als er hinblickte, siehe, da lag zu seinen Häupten ein Kuchen, auf heißen Steinen gebacken, und ein Krug Wasser. Und er aß und trank und legte sich wieder hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Und der Engel Jehovas kam zum zweiten Male wieder und rührte ihn an und sprach: Stehe auf, iß! Denn der Weg ist zu weit für dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Und er stand auf und aß und trank, und er ging in der Kraft dieser Speise vierzig Tage und vierzig Nächte bis an den Berg Gottes, den Horeb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Und er ging daselbst in die Höhle und übernachtete daselbst. Und siehe, das Wort Jehovas geschah zu ihm, und er sprach zu ihm: Was tust du hier, Elia?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Und er sprach: Ich habe sehr geeifert für Jehova, den Gott der Heerscharen; denn die Kinder Israel haben deinen Bund verlassen, deine Altäre niedergerissen und deine Propheten mit dem Schwerte getötet; und ich allein bin übriggeblieben, und sie trachten danach, mir das Leben zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Und er sprach: Gehe hinaus und stelle dich auf den Berg vor Jehova! Und siehe, Jehova ging vorüber, und ein Wind, groß und stark, zerriß die Berge und zerschmetterte die Felsen vor Jehova her; Jehova war nicht in dem Winde. Und nach dem Winde ein Erdbeben; Jehova war nicht in dem Erdbeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Und nach dem Erdbeben ein Feuer; Jehova war nicht in dem Feuer. Und nach dem Feuer der Ton eines leisen Säuselns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Und es geschah, als Elia es hörte, da verhüllte er sein Angesicht mit seinem Mantel, und ging hinaus und stellte sich an den Eingang der Höhle. Und siehe, eine Stimme geschah zu ihm also: Was tust du hier, Elia?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Und er sprach: Ich habe sehr geeifert für Jehova, den Gott der Heerscharen; denn die Kinder Israel haben deinen Bund verlassen, deine Altäre niedergerissen und deine Propheten mit dem Schwerte getötet; und ich allein bin übriggeblieben, und sie trachten danach, mir das Leben zu nehmen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Und Jehova sprach zu ihm: Gehe, kehre zurück deines Weges, nach der Wüste von Damaskus; und wenn du angekommen bist, so salbe Hasael zum König über Syrien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Und Jehu, den Sohn Nimsis, sollst du zum König über Israel salben; und Elisa, den Sohn Saphats, von Abel-Mehola, sollst du zum Propheten salben an deiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Und es soll geschehen: wer dem Schwerte Hasaels entrinnt, den wird Jehu töten; und wer dem Schwerte Jehus entrinnt, den wird Elisa töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Aber ich habe siebentausend in Israel übriggelassen, alle die Knie, die sich nicht vor dem Baal gebeugt haben, und jeden Mund, der ihn nicht geküßt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Und er ging von dannen und fand Elisa, den Sohn Saphats, welcher gerade pflügte mit zwölf Joch Rindern vor sich her, und er war bei dem zwölften; und Elia ging zu ihm hin und warf seinen Mantel auf ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Und er verließ die Rinder und lief Elia nach und sprach: Laß mich doch meinen Vater und meine Mutter küssen, so will ich dir nachfolgen. Und er sprach zu ihm: Gehe, kehre zurück! Denn was habe ich dir getan?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Und er kehrte von ihm zurück und nahm das Joch Rinder und schlachtete es, und mit dem Geschirr der Rinder kochte er das Fleisch derselben und gab es den Leuten, und sie aßen; und er machte sich auf und folgte Elia nach und diente ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Und Ben-Hadad, der König von Syrien, versammelte seine ganze Heeresmacht: zweiunddreißig Könige waren mit ihm und Rosse und Wagen; und er zog herauf und belagerte Samaria und stritt wider dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Und er sandte Boten zu Ahab, dem König von Israel, in die Stadt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'und ließ ihm sagen: So spricht Ben-Hadad: Dein Silber und dein Gold ist mein, und deine Weiber und deine Söhne, die schönsten, sind mein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Und der König von Israel antwortete und sprach: Nach deinem Worte, mein Herr König: Dein bin ich mit allem, was mein ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Und die Boten kamen wieder und sprachen: So spricht Ben-Hadad und sagt: Wohl habe ich zu dir gesandt und gesprochen: Dein Silber und dein Gold, und deine Weiber und deine Söhne sollst du mir geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'doch morgen um diese Zeit werde ich meine Knechte zu dir senden, und sie werden dein Haus und die Häuser deiner Knechte durchsuchen; und es wird geschehen, alle Lust deiner Augen werden sie in ihre Hand tun und mitnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Da berief der König von Israel alle Ältesten des Landes und sprach: Erkennet doch und sehet, daß dieser Böses sucht; denn er hat zu mir gesandt um meine Weiber und meine Söhne, und um mein Silber und mein Gold, und ich habe es ihm nicht verweigert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Und alle Ältesten und alles Volk sprachen zu ihm: Gehorche nicht und willige nicht ein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Und er sprach zu den Boten Ben-Hadads: Saget meinem Herrn, dem König: Alles, was du deinem Knechte zuerst entboten hast, will ich tun; aber diese Sache kann ich nicht tun. Und die Boten gingen hin und brachten ihm Antwort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Da sandte Ben-Hadad zu ihm und ließ ihm sagen: So sollen mir die Götter tun und so hinzufügen, wenn der Staub von Samaria hinreichen soll für die hohlen Hände all des Volkes, das mir folgt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Und der König von Israel antwortete und sprach: Saget ihm: Es rühme sich nicht der sich Gürtende wie der den Gürtel Lösende!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Und es geschah, als er dieses Wort hörte, er trank eben, er und die Könige, in den Zelten- da sprach er zu seinen Knechten: Stellet euch! Und sie stellten sich wider die Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Und siehe, ein Prophet trat zu Ahab, dem König von Israel, und sprach: So spricht Jehova: Hast du diesen ganzen großen Haufen gesehen? Siehe, ich gebe ihn heute in deine Hand, und du sollst wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Und Ahab sprach: Durch wen? Und er sprach: So spricht Jehova: Durch die Knaben der Obersten der Landschaften. Und er sprach: Wer soll den Kampf eröffnen? Und er sprach: Du.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Da musterte er die Knaben der Obersten der Landschaften, und ihrer waren zweihundertzweiunddreißig; und nach ihnen musterte er das ganze Volk, alle Kinder Israel, siebentausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Und sie zogen aus am Mittag. Ben-Hadad aber trank und berauschte sich in den Zelten, er und die Könige, die zweiunddreißig Könige, die ihm halfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Und die Knaben der Obersten der Landschaften zogen zuerst aus. Und Ben-Hadad sandte hin, und man berichtete ihm und sprach: Es sind Männer aus Samaria gezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Da sprach er: Wenn sie zum Frieden ausgezogen sind, so greifet sie lebendig; und wenn sie zum Streit ausgezogen sind, so greifet sie lebendig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Diese aber zogen aus der Stadt: die Knaben der Obersten der Landschaften und das Heer, das ihnen folgte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Und sie schlugen ein jeder seinen Mann, und die Syrer flohen, und Israel jagte ihnen nach; und Ben-Hadad, der König von Syrien, entkam auf einem Rosse mit einigen Reitern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Da zog der König von Israel aus und schlug die Rosse und die Wagen, und er richtete unter den Syrern eine große Niederlage an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Da trat der Prophet zu dem König von Israel und sprach zu ihm: Wohlan, verstärke dich, und erkenne und sieh zu, was du zu tun hast; denn bei der Rückkehr des Jahres wird der König von Syrien wider dich heraufziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Und die Knechte des Königs von Syrien sprachen zu ihm: Ihre Götter sind Berggötter, darum waren sie uns überlegen; jedoch laßt uns in der Ebene wider sie streiten, ob wir ihnen nicht überlegen sein werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Tue aber dieses: Entferne die Könige, einen jeden von seinem Orte, und setze Befehlshaber an ihre Stelle;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'und du, zähle dir ein Heer wie das Heer, das dir gefallen ist, und Rosse wie die Rosse, und Wagen wie die Wagen; und wir wollen in der Ebene wider sie streiten, ob wir ihnen nicht überlegen sein werden. Und er hörte auf ihre Stimme und tat also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Und es geschah bei der Rückkehr des Jahres, da musterte Ben-Hadad die Syrer, und er zog hinauf nach Aphek zum Streit mit Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Und die Kinder Israel wurden gemustert und mit Vorrat versorgt, und sie zogen ihnen entgegen; und die Kinder Israel lagerten sich ihnen gegenüber wie zwei kleine Herden Ziegen; die Syrer aber füllten das Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Da trat der Mann Gottes herzu und sprach zu dem König von Israel und sagte: So spricht Jehova: Weil die Syrer gesagt haben: Jehova ist ein Gott der Berge und nicht ein Gott der Täler, so will ich diesen ganzen großen Haufen in deine Hand geben; und ihr werdet erkennen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Und sie lagerten, diese jenen gegenüber, sieben Tage lang. Und es geschah am siebten Tage, da begann der Streit; und die Kinder Israel schlugen die Syrer, hunderttausend Mann zu Fuß, an einem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Und die übrigen flohen nach Aphek in die Stadt. Da fiel die Mauer auf die siebenundzwanzigtausend Mann, die übriggeblieben waren. Und Ben-Hadad floh und kam in die Stadt, in das innerste Gemach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Da sprachen seine Knechte zu ihm: Siehe doch, wir haben gehört, daß die Könige des Hauses Israel gnädige Könige sind; laß uns doch Sacktuch um unsere Lenden legen und Stricke um unsere Häupter, und zum König von Israel hinausgehen; vielleicht läßt er deine Seele am Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Und sie gürteten Sacktuch um ihre Lenden und legten Stricke um ihre Häupter, und kamen zu dem König von Israel und sprachen: Dein Knecht Ben-Hadad spricht: Laß doch meine Seele am Leben! Und er sprach: Lebt er noch? Er ist mein Bruder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Und die Männer nahmen es als eine gute Vorbedeutung, und eilten sich zu vergewissern, ob er es wirklich so meinte, und sprachen: Dein Bruder Ben-Hadad. Und er sprach: Gehet, holet ihn. Da ging Ben-Hadad zu ihm hinaus, und er ließ ihn zu sich auf den Wagen steigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Und Ben-Hadad sprach: Die Städte, die mein Vater deinem Vater genommen hat, will ich dir zurückgeben, und du magst dir Straßen in Damaskus anlegen, so wie mein Vater sich solche in Samaria angelegt hat. Und ich, sprach Ahab, will dich mit diesem Bunde ziehen lassen. Und er machte einen Bund mit ihm und ließ ihn ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Und ein Mann von den Söhnen der Propheten sprach zu seinem Genossen durch das Wort Jehovas: Schlage mich doch! Aber der Mann weigerte sich, ihn zu schlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Da sprach er zu ihm: Darum daß du nicht auf die Stimme Jehovas gehört hast, siehe, sobald du von mir weggehst, wird dich ein Löwe töten. Und als er von ihm wegging, da fand ihn ein Löwe und tötete ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Und er traf einen anderen Mann und sprach: Schlage mich doch! Und der Mann schlug ihn, schlug und verwundete ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Da ging der Prophet hin und stellte sich auf den Weg des Königs, und machte sich unkenntlich, indem er den Kopfbund über seine Augen zog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Und es geschah, als der König vorbeiging, da schrie er den König an und sprach: Dein Knecht war mitten in den Streit gezogen, und siehe, da wandte sich ein Mann herzu und brachte einen Mann zu mir und sprach: Bewache diesen Mann; wenn er irgend vermißt wird, so soll dein Leben statt seines Lebens sein, oder du sollst ein Talent Silber darwägen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Und es geschah, während dein Knecht hier und dort zu tun hatte, da war er fort. Und der König von Israel sprach zu ihm: Also ist dein Urteil, du selbst hast entschieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Da tat er eilends den Kopfbund von seinen Augen, und der König von Israel erkannte ihn, daß er von den Propheten war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Und er sprach zu ihm: So spricht Jehova: Weil du den Mann, den ich verbannt habe, aus der Hand entlassen hast, so soll dein Leben statt seines Lebens sein und dein Volk statt seines Volkes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Und der König von Israel ging nach seinem Hause, mißmutig und zornig, und kam nach Samaria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Und es geschah nach diesen Dingen: Naboth, der Jisreeliter, hatte einen Weinberg, der zu Jisreel war, neben dem Palaste Ahabs, des Königs von Samaria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Und Ahab redete zu Naboth und sprach: Gib mir deinen Weinberg, daß er mein Krautgarten werde, denn er ist nahe bei meinem Hause; und ich will dir statt seiner einen besseren Weinberg geben; oder wenn es gut ist in deinen Augen, will ich dir Geld geben, im Werte desselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Aber Naboth sprach zu Ahab: Das lasse Jehova fern von mir sein, daß ich dir das Erbe meiner Väter geben sollte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Und Ahab kam in sein Haus, mißmutig und zornig über das Wort, das Naboth, der Jisreeliter, zu ihm geredet hatte, indem er sprach: Ich will dir das Erbe meiner Väter nicht geben. Und er legte sich auf sein Bett und wandte sein Angesicht ab und aß nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Und Isebel, sein Weib, kam zu ihm hinein und sprach zu ihm: Warum ist doch dein Geist mißmutig, und warum issest du nichts?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Und er sprach zu ihr: Weil ich zu Naboth, dem Jisreeliter, geredet und ihm gesagt habe: Gib mir deinen Weinberg um Geld, oder wenn du Lust hast, will ich dir statt seiner einen anderen Weinberg geben; aber er sagte: Ich will dir meinen Weinberg nicht geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Da sprach Isebel, sein Weib, zu ihm: Du, übest du jetzt Königsmacht über Israel aus? Stehe auf, iß, und laß dein Herz fröhlich sein. Ich werde dir den Weinberg Naboths, des Jisreeliters, geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Und sie schrieb Briefe im Namen Ahabs und siegelte sie mit seinem Siegel, und sandte die Briefe an die Ältesten und an die Edlen, die in seiner Stadt waren, die mit Naboth zusammen wohnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Und sie schrieb in den Briefen folgendes: Rufet ein Fasten aus, und setzet Naboth obenan unter dem Volke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Und setzet zwei Männer, Söhne Belials, ihm gegenüber, daß sie wider ihn zeugen und sprechen: Du hast Gott und den König gelästert! Und führet ihn hinaus und steiniget ihn, daß er sterbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Und die Männer seiner Stadt, die Ältesten und die Edlen, die in seiner Stadt wohnten, taten, wie Isebel ihnen entboten hatte, so wie in den Briefen geschrieben war, die sie an sie gesandt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Sie riefen ein Fasten aus und setzten Naboth obenan unter dem Volke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'und die zwei Männer, Söhne Belials, kamen und setzten sich ihm gegenüber; und die Männer Belials zeugten wider ihn, wider Naboth, vor dem Volke und sprachen: Naboth hat Gott und den König gelästert! Und sie führten ihn zur Stadt hinaus und steinigten ihn, und er starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Und sie sandten zu Isebel und ließen ihr sagen: Naboth ist gesteinigt worden und ist gestorben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Und es geschah, als Isebel hörte, daß Naboth gesteinigt worden und gestorben war, da sprach Isebel zu Ahab: Mache dich auf, nimm den Weinberg Naboths, des Jisreeliters, in Besitz, den er sich geweigert hat, dir um Geld zu geben; denn Naboth lebt nicht mehr, sondern ist tot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Und es geschah, als Ahab hörte, daß Naboth tot war, da machte sich Ahab auf, um in den Weinberg Naboths, des Jisreeliters, hinabzugehen, um ihn in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Da geschah das Wort Jehovas zu Elia, dem Tisbiter, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Mache dich auf, gehe hinab, Ahab, dem König von Israel, entgegen, der zu Samaria ist; siehe, er ist im Weinberge Naboths, wohin er hinabgegangen ist, um ihn in Besitz zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Und rede zu ihm und sprich: So spricht Jehova: Hast du gemordet und auch in Besitz genommen? Und rede zu ihm und sprich: So spricht Jehova: An der Stelle, wo die Hunde das Blut Naboths geleckt haben, sollen die Hunde dein, auch dein Blut lecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Und Ahab sprach zu Elia: Hast du mich gefunden, mein Feind? Und er sprach: Ich habe dich gefunden, weil du dich verkauft hat, um zu tun, was böse ist in den Augen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Siehe, ich will Unglück über dich bringen und hinter dir her ausfegen; und ich werde von Ahab ausrotten, was männlich ist, sowohl den Gebundenen als auch den Freien in Israel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'und ich werde dein Haus machen wie das Haus Jerobeams, des Sohnes Nebats, und wie das Haus Baesas, des Sohnes Achijas, wegen der Reizung, womit du mich gereizt und Israel sündigen gemacht hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Und auch von Isebel hat Jehova geredet und gesprochen: Die Hunde sollen Isebel fressen an der Vormauer von Jisreel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Wer von Ahab in der Stadt stirbt, den sollen die Hunde fressen, und wer auf dem Felde stirbt, den sollen die Vögel des Himmels fressen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, '(Es ist gar keiner gewesen wie Ahab, der sich verkauft hätte, um zu tun, was böse ist in den Augen Jehovas, welchen Isebel, sein Weib, anreizte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Und er tat sehr viele Greuel, indem er den Götzen nachwandelte, nach allem, was die Amoriter getan, welche Jehova vor den Kindern Israel ausgetrieben hatte.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Und es geschah, als Ahab diese Worte hörte, da zerriß er seine Kleider und legte Sacktuch um seinen Leib und fastete; und er lag im Sacktuch, und er ging still einher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Da geschah das Wort Jehovas zu Elia, dem Tisbiter, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Hast du gesehen, daß Ahab sich vor mir gedemütigt hat? Weil er sich vor mir gedemütigt hat, will ich das Unglück in seinen Tagen nicht bringen; in den Tagen seines Sohnes will ich das Unglück über sein Haus bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Und sie blieben drei Jahre ruhig; es war kein Krieg zwischen Syrien und Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Und es geschah im dritten Jahre, da kam Josaphat, der König von Juda, zu dem König von Israel herab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Und der König von Israel sprach zu seinen Knechten: Wisset ihr nicht, daß Ramoth-Gilead unser ist? Und wir bleiben still und nehmen es nicht aus der Hand des Königs von Syrien?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Und er sprach zu Josaphat: Willst du mit mir nach Ramoth-Gilead in den Streit ziehen? Und Josaphat sprach zu dem König von Israel: Ich will sein wie du, mein Volk wie dein Volk, meine Rosse wie deine Rosse!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Und Josaphat sprach zu dem König von Israel: Befrage doch heute das Wort Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Da versammelte der König von Israel die Propheten, bei vierhundert Mann, und er sprach zu ihnen: Soll ich wider Ramoth-Gilead in den Streit ziehen, oder soll ich davon abstehen? Und sie sprachen: Ziehe hinauf, und der Herr wird es in die Hand des Königs geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Aber Josaphat sprach: Ist hier kein Prophet Jehovas mehr, daß wir durch ihn fragen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Und der König von Israel sprach zu Josaphat: Es ist noch ein Mann da, um durch ihn Jehova zu befragen; aber ich hasse ihn, denn er weissagt nichts Gutes über mich, sondern nur Böses: Micha, der Sohn Jimlas. Und Josaphat sprach: Der König spreche nicht also!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Da rief der König von Israel einen Kämmerer und sprach: Bringe Micha, den Sohn Jimlas, eilends her!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Und der König von Israel und Josaphat, der König von Juda, saßen ein jeder auf seinem Throne, angetan mit königlichen Kleidern, auf einem freien Platze am Eingang des Tores von Samaria; und alle Propheten weissagten vor ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Und Zedekia, der Sohn Kenaanas, machte sich eiserne Hörner und sprach: So spricht Jehova: Mit diesen wirst du die Syrer stoßen, bis du sie vernichtet hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Und alle Propheten weissagten ebenso und sprachen: Ziehe hinauf nach Ramoth-Gilead, und es wird dir gelingen; denn Jehova wird es in die Hand des Königs geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Und der Bote, der hingegangen war, Micha zu rufen, redete zu ihm und sprach: Siehe doch, die Worte der Propheten verkündigen einstimmig dem König Gutes; laß doch dein Wort sein wie das Wort eines von ihnen und rede Gutes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Aber Micha sprach: So wahr Jehova lebt, was Jehova mir sagen wird, das werde ich reden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Und als er zu dem König kam, sprach der König zu ihm: Micha, sollen wir nach Ramoth-Gilead in den Streit ziehen, oder sollen wir davon abstehen? Und er sprach zu ihm: Ziehe hinauf, und es wird dir gelingen; denn Jehova wird es in die Hand des Königs geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Und der König sprach zu ihm: Wie viele Male muß ich dich beschwören, daß du nichts zu mir reden sollst als nur Wahrheit im Namen Jehovas?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Da sprach er: Ich sah ganz Israel auf den Bergen zerstreut, wie Schafe, die keinen Hirten haben. Und Jehova sprach: Diese haben keinen Herrn; sie sollen ein jeder nach seinem Hause zurückkehren in Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Und der König von Israel sprach zu Josaphat: Habe ich dir nicht gesagt: Er weissagt nichts Gutes über mich, sondern nur Böses?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Und er sprach: Darum höre das Wort Jehovas! Ich sah Jehova auf seinem Throne sitzen, und alles Heer des Himmels bei ihm stehen, zu seiner Rechten und zu seiner Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'und Jehova sprach: Wer will Ahab bereden, daß er hinaufziehe und zu Ramoth-Gilead falle? Und der eine sprach so, und der andere sprach so.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Da trat ein Geist hervor und stellte sich vor Jehova und sprach: Ich will ihn bereden. Und Jehova sprach zu ihm: Wodurch?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Und er sprach: Ich will ausgehen und will ein Lügengeist sein in dem Munde aller seiner Propheten. Und er sprach: Du wirst ihn bereden und wirst es auch ausrichten; gehe aus und tue also!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Und nun, siehe, Jehova hat einen Lügengeist in den Mund all dieser deiner Propheten gelegt, und Jehova hat Böses über dich geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Da trat Zedekia, der Sohn Kenaanas, herzu und schlug Micha auf den Backen und sprach: Wo wäre der Geist Jehovas von mir gewichen, um mit dir zu reden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Und Micha sprach: Siehe, du wirst es sehen an jenem Tage, wenn du ins innerste Gemach gehen wirst, um dich zu verstecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Und der König von Israel sprach: Nimm Micha und führe ihn zurück zu Amon, dem Obersten der Stadt, und zu Joas, dem Sohne des Königs,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'und sage: So spricht der König: Setzet diesen ins Gefängnis und speiset ihn mit Brot der Trübsal und mit Wasser der Trübsal, bis ich in Frieden heimkomme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Und Micha sprach: Wenn du je in Frieden zurückkehrst, so hat Jehova nicht durch mich geredet! Und er sprach: Höret es, ihr Völker alle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Und der König von Israel und Josaphat, der König von Juda, zogen hinauf nach Ramoth-Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Und der König von Israel sprach zu Josaphat: Ich will mich verkleiden und in den Streit ziehen, du aber lege deine Kleider an. Und der König von Israel verkleidete sich und zog in den Streit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Der König von Syrien hatte aber seinen zweiunddreißig Obersten der Wagen geboten und gesagt: Ihr sollt weder wider einen Geringen streiten, noch wider einen Großen, sondern wider den König von Israel allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Und es geschah, als die Obersten der Wagen Josaphat sahen, denn sie sprachen: Das ist gewiß der König von Israel! da lenkten sie auf ihn zu, um zu streiten; und Josaphat schrie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Und es geschah, als die Obersten der Wagen sahen, daß er nicht der König von Israel war, da wandten sie sich von ihm ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Und ein Mann spannte den Bogen aufs Geratewohl und traf den König von Israel zwischen den Panzeranhang und den Panzer. Da sprach er zu seinem Wagenlenker: Wende um und führe mich aus dem Heere hinaus, denn ich bin verwundet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Und der Streit nahm überhand an selbigem Tage, und der König wurde aufrecht erhalten in dem Wagen, den Syrern gegenüber; und er starb am Abend; und das Blut der Wunde floß in den Boden des Wagens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Da erging der laute Ruf durch das Lager beim Untergang der Sonne, indem man sprach: Ein jeder in seine Stadt, und ein jeder in sein Land!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Und so starb der König und kam nach Samaria; und man begrub den König zu Samaria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Und als man den Wagen am Teiche von Samaria abspülte, da leckten die Hunde sein Blut (da wo die Huren badeten), nach dem Worte Jehovas, das er geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Und das Übrige der Geschichte Ahabs und alles, was er getan und das elfenbeinerne Haus, das er gebaut, und alle Städte, die er gebaut hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Und Ahab legte sich zu seinen Vätern. Und Ahasja, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Und Josaphat, der Sohn Asas, wurde König über Juda im vierten Jahre Ahabs, des Königs von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Josaphat war fünfunddreißig Jahre alt, als er König wurde, und er regierte fünfundzwanzig Jahre zu Jerusalem; und er Name seiner Mutter war Asuba, die Tochter Schilchis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Und er wandelte auf allen Wegen seines Vaters Asa; er wich nicht davon, indem er tat, was recht war in den Augen Jehovas. (H22:44) Nur die Höhen wichen nicht: das Volk opferte und räucherte noch auf den Höhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, '(H22:45) Und Josaphat hatte Frieden mit dem König von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, '(H22:46) Und das Übrige der Geschichte Josaphats, und seine Macht, die er ausgeübt, und wie er gestritten hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, '(H22:47) Auch den Rest der Buhler, der in den Tagen seines Vaters Asa übriggeblieben war, schaffte er aus dem Lande hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, '(H22:48) Und es war damals kein König in Edom; ein Statthalter war König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, '(H22:49) Josaphat baute Tarsisschiffe, um nach Ophir zu fahren und Gold zu holen; aber man fuhr nicht, denn die Schiffe wurden bei Ezjon-Geber zertrümmert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, '(H22:50) Damals sprach Ahasja, der Sohn Ahabs, zu Josaphat: Laß meine Knechte mit deinen Knechten auf den Schiffen fahren; aber Josaphat wollte nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, '(H22:51) Und Josaphat legte sich zu seinen Vätern, und er wurde bei seinen Vätern begraben in der Stadt seines Vaters David. Und Joram, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, '(H22:52) Ahasja, der Sohn Ahabs, wurde König über Israel zu Samaria, im siebzehnten Jahre Josaphats, des Königs von Juda; und er regierte zwei Jahre über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, '(H22:53) Und er tat, was böse war in den Augen Jehovas, und er wandelte auf dem Wege seines Vaters und auf dem Wege seiner Mutter und auf dem Wege Jerobeams, des Sohnes Nebats, der Israel sündigen gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, '(H22:54) Und er diente dem Baal und beugte sich vor ihm nieder; und er reizte Jehova, den Gott Israels, nach allem, was sein Vater getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Und nach dem Tode Ahabs fielen die Moabiter von Israel ab. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Und Ahasja fiel durch das Gitter an seinem Obergemach zu Samaria und wurde krank. Und er sandte Boten und sprach zu ihnen: Gehet hin, befraget Baal-Sebub, den Gott von Ekron, ob ich von dieser Krankheit genesen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Und der Engel Jehovas redete zu Elia, dem Tisbiter: Mache dich auf, gehe hinauf, den Boten des Königs von Samaria entgegen, und sprich zu ihnen: Ist es, weil kein Gott in Israel ist, daß ihr hingehet, um Baal-Sebub, den Gott von Ekron, zu befragen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Und darum spricht Jehova also: Von dem Bette, das du bestiegen hast, sollt du nicht herabkommen, sondern du wirst gewißlich sterben. Und Elia ging hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Und die Boten kehrten zu ihm zurück; und er sprach zu ihnen: Warum seid ihr denn zurückgekehrt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Und sie sprachen zu ihm: Ein Mann kam herauf, uns entgegen, und sprach zu uns: Gehet, kehret zurück zu dem König, der euch gesandt hat, und redet zu ihm: So spricht Jehova: Ist es, weil kein Gott in Israel ist, daß du hinsendest, um Baal-Sebub, den Gott von Ekron, zu befragen? Darum sollst du von dem Bette, das du bestiegen hast, nicht herabkommen, sondern du wirst gewißlich sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Da sagte er zu ihnen: Was für ein Mann war es, der euch entgegen heraufkam und diese Worte zu euch redete?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Und sie sprachen zu ihm: Es war ein Mann in härenem Gewande und an seinen Lenden gegürtet mit einem ledernen Gürtel. Und er sprach: Es ist Elia, der Tisbiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Da sandte er zu ihm einen Obersten über fünfzig und seine Fünfzig. Und er ging zu ihm hinauf, und siehe, er saß auf dem Gipfel des Berges; und er sprach zu ihm: Mann Gottes! Der König sagt: Komm herab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Aber Elia antwortete und sprach zu dem Obersten über fünfzig: Und wenn ich ein Mann Gottes bin, so fahre Feuer vom Himmel herab und fresse dich und deine Fünfzig! Da fuhr Feuer vom Himmel herab und fraß ihn und seine Fünfzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Und er sandte wiederum zu ihm einen anderen Obersten über fünfzig und seine Fünfzig. Und er hob an und sprach zu ihm: Mann Gottes! So spricht der König: Komm eilends herab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Aber Elia antwortete und sprach zu ihnen: Wenn ich ein Mann Gottes bin, so fahre Feuer vom Himmel herab und fresse dich und deine Fünfzig! Da fuhr Feuer Gottes vom Himmel herab und fraß ihn und seine Fünfzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Und er sandte wiederum einen dritten Obersten über fünfzig und seine Fünfzig. Und der dritte Oberste über fünfzig ging hinauf und kam und beugte seine Knie vor Elia, und er flehte ihn an und sprach zu ihm: Mann Gottes! Möge doch mein Leben und das Leben deiner Knechte, dieser Fünfzig, teuer sein in deinen Augen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Siehe, Feuer ist vom Himmel herabgefahren und hat die beiden vorigen Obersten über fünfzig und ihre Fünfzig gefressen; nun aber möge mein Leben teuer sein in deinen Augen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Da sprach der Engel Jehovas zu Elia: Gehe mit ihm hinab, fürchte dich nicht vor ihm! Und er stand auf und ging mit ihm zu dem König hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Und er redete zu ihm: So spricht Jehova: Weil du Boten gesandt hast, um Baal-Sebub, den Gott von Ekron, zu befragen (ist es, weil kein Gott in Israel ist, um sein Wort zu befragen?), Darum sollst du von dem Bette, das du bestiegen hast, nicht herabkommen, sondern du wirst gewißlich sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Und er starb nach dem Worte Jehovas, das Elia geredet hatte. Und Joram ward König an seiner Statt im zweiten Jahre Jorams, des Sohnes Josaphats, des Königs von Juda; denn er hatte keinen Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Und das Übrige der Geschichte Ahasjas, was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Und es geschah, als Jehova den Elia im Sturmwinde gen Himmel auffahren ließ, da gingen Elia und Elisa von Gilgal hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Und Elia sprach zu Elisa: Bleibe doch hier; denn Jehova hat mich bis nach Bethel gesandt. Und Elisa sprach: So wahr Jehova lebt und deine Seele lebt, wenn ich dich verlasse! Und sie gingen nach Bethel hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Da kamen die Söhne der Propheten, die in Bethel waren, zu Elisa heraus und sprachen zu ihm: Weißt du, daß Jehova heute deinen Herrn über deinem Haupte hinwegnehmen wird? Und er sprach: Auch ich weiß es; schweiget!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Und Elia sprach zu ihm: Elisa, bleibe doch hier; denn Jehova hat mich nach Jericho gesandt. Aber er sprach: So wahr Jehova lebt und deine Seele lebt, wenn ich dich verlasse! Und sie kamen nach Jericho.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Da traten die Söhne der Propheten, die in Jericho waren, zu Elisa und sprachen zu ihm: Weißt du, daß Jehova heute deinen Herrn über deinem Haupte hinwegnehmen wird? Und er sprach: Auch ich weiß es; schweiget!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Und Elia sprach zu ihm: Bleibe doch hier; denn Jehova hat mich an den Jordan gesandt. Aber er sprach: So wahr Jehova lebt und deine Seele lebt, wenn ich dich verlasse! Und so gingen sie beide miteinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Und fünfzig Mann von den Söhnen der Propheten gingen hin und stellten sich gegenüber von ferne; und sie beide traten an den Jordan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Da nahm Elia seinen Mantel und wickelte ihn zusammen und schlug auf das Wasser; und es zerteilte sich dahin und dorthin, und sie gingen beide hinüber auf dem Trockenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Und es geschah, als sie hinübergegangen waren, da sprach Elia zu Elisa: Begehre, was ich dir tun soll, ehe ich von dir genommen werde. Und Elisa sprach: So möge mir doch ein zwiefaches Teil von deinem Geiste werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Und er sprach: Du hast Schweres begehrt! Wenn du mich sehen wirst, wann ich von dir genommen werde, so soll dir also geschehen; wenn aber nicht, so wird es nicht geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Und es geschah, während sie gingen und im Gehen redeten, siehe da, ein Wagen von Feuer und Rosse von Feuer, welche sie beide voneinander trennten; und Elia fuhr im Sturmwind auf gen Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Und Elisa sah es und schrie: Mein Vater, mein Vater! Wagen Israels und seine Reiter! Und er sah ihn nicht mehr. Da faßte er seine Kleider und zerriß sie in zwei Stücke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Und er hob den Mantel des Elia auf, der von ihm herabgefallen war, und kehrte um und trat an das Ufer des Jordan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Und er nahm den Mantel des Elia, der von ihm herabgefallen war, und schlug auf das Wasser und sprach: Wo ist Jehova, der Gott des Elia? Auch er schlug auf das Wasser, und es zerteilte sich dahin und dorthin; und Elisa ging hinüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Als nun die Söhne der Propheten, die gegenüber in Jericho waren, ihn sahen, da sprachen sie: Der Geist des Elia ruht auf Elisa! Und sie kamen ihm entgegen und beugten sich vor ihm zur Erde nieder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'und sie sprachen zu ihm: Siehe doch, es sind bei deinen Knechten fünfzig tapfere Männer; mögen sie doch gehen und deinen Herrn suchen, ob nicht etwa der Geist Jehovas ihn weggetragen und ihn auf einen der Berge oder in eins der Täler geworfen hat. Aber er sprach: Sendet nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Und sie drangen in ihn, bis er sich schämte. Da sprach er: Sendet! Und so sandten sie fünfzig Mann; und sie suchten drei Tage lang, aber sie fanden ihn nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Und sie kehrten zu ihm zurück (er verweilte aber noch in Jericho); und er sprach zu ihnen: Habe ich euch nicht gesagt: Gehet nicht hin?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Und die Männer der Stadt sprachen zu Elisa: Siehe doch, die Lage der Stadt ist gut, wie mein Herr sieht, aber das Wasser ist schlecht, und das Land ist unfruchtbar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Da sprach er: Holet mir eine neue Schale, und tut Salz darein! Und sie holten sie ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Und er ging hinaus zu der Quelle des Wassers, und warf das Salz hinein und sprach: So spricht Jehova: Ich habe dieses Wasser gesund gemacht; es wird weder Tod noch Unfruchtbarkeit mehr daraus entstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Und das Wasser wurde gesund bis auf diesen Tag, nach dem Worte, das Elisa geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Und er ging von dannen hinauf nach Bethel; und als er auf dem Wege hinaufging, da kamen kleine Knaben aus der Stadt heraus, und verspotteten ihn und sprachen zu ihm: Komm herauf, Kahlkopf! Komm herauf, Kahlkopf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Und er wandte sich um und sah sie an und fluchte ihnen im Namen Jehovas. Da kamen zwei Bären aus dem Walde und zerrissen von ihnen zweiundvierzig Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Und er ging von dannen nach dem Berge Karmel; und von dort kehrte er nach Samaria zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Und Joram, der Sohn Ahabs, wurde König über Israel zu Samaria, im achtzehnten Jahre Josaphats, des Königs von Juda; und er regierte zwölf Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Und er tat, was böse war in den Augen Jehovas, nur nicht wie sein Vater und seine Mutter; und er tat die Bildsäule des Baal hinweg, die sein Vater gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Doch blieb er hangen an den Sünden Jerobeams, des Sohnes Nebats, wodurch er Israel sündigen gemacht hatte; er wich nicht davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Und Mesa, der König von Moab, war ein Herdenbesitzer, und er zinste dem König von Israel hunderttausend Fettschafe und hunderttausend Widder mit der Wolle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Und es geschah, als Ahab starb, da fiel der König von Moab von dem König von Israel ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Und der König Joram zog in selbiger Zeit von Samaria aus und musterte ganz Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Und er ging hin und sandte zu Josaphat, dem König von Juda, und ließ ihm sagen: Der König von Moab ist von mir abgefallen; willst du mit mir wider Moab in den Streit ziehen? Und er sprach: Ich will hinaufziehen; ich will sein wie du, mein Volk wie dein Volk, meine Rosse wie deine Rosse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Und er sprach: Auf welchem Wege wollen wir hinaufziehen? Und er sprach: Auf dem Wege der Wüste Edom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Und so zogen der König von Israel und der König von Juda und der König von Edom hin; und sie machten einen Umweg von sieben Tagereisen, und es war kein Wasser da für das Heer und für das Vieh, das ihnen folgte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Da sprach der König von Israel: Ach, daß Jehova diese drei Könige gerufen hat, um sie in die Hand Moabs zu geben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Und Josaphat sprach: Ist hier kein Prophet Jehovas, daß wir Jehova durch ihn befragen könnten? Und einer von den Knechten des Königs von Israel antwortete und sprach: Hier ist Elisa, der Sohn Saphats, der Wasser goß auf die Hände des Elia.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Und Josaphat sprach: Das Wort Jehovas ist bei ihm. Und der König von Israel und Josaphat und der König von Edom gingen zu ihm hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Und Elisa sprach zu dem König von Israel: Was haben wir miteinander zu schaffen? Geh zu den Propheten deines Vaters und zu den Propheten deiner Mutter! Und der König von Israel sprach zu ihm: Nein, denn Jehova hat diese drei Könige gerufen, um sie in die Hand Moabs zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Da sprach Elisa: So wahr Jehova der Heerscharen lebt, vor dessen Angesicht ich stehe, wenn ich nicht auf die Person Josaphats, des Königs von Juda, Rücksicht nähme, so würde ich dich nicht anblicken, noch dich ansehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Und nun holet mir einen Saitenspieler. Und es geschah, als der Saitenspieler spielte, da kam die Hand Jehovas über ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Und er sprach: So spricht Jehova: Machet in diesem Tale Grube an Grube.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Denn so spricht Jehova: ihr werdet keinen Wind sehen und keinen Regen sehen, und doch wird dieses Tal sich mit Wasser füllen, so daß ihr trinken werdet, ihr und eure Herden und euer Vieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Und das ist noch gering in den Augen Jehovas; er wird auch Moab in eure Hand geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Und ihr werdet alle festen Städte und alle auserlesenen Städte schlagen, und werdet alle guten Bäume fällen und alle Wasserquellen verstopfen und alle guten Ackerstücke mit Steinen verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Und es geschah am Morgen, zur Zeit, da man das Speisopfer opfert, siehe, da kam Wasser des Weges von Edom her, und das Land füllte sich mit Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Und als alle Moabiter hörten, daß die Könige heraufgezogen waren, um wider sie zu streiten, da wurden sie zusammengerufen, von jedem an, der sich rüsten konnte und darüber; und sie rückten an die Grenze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Und als sie sich des Morgens früh aufmachten und die Sonne über dem Wasser aufging, da sahen die Moabiter das Wasser gegenüber rot wie Blut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Und sie sprachen: Das ist Blut! Die Könige haben sich gewißlich aufgerieben und haben einander erschlagen; und nun zur Beute, Moab!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Als sie aber zum Lager Israels kamen, da machten die Israeliten sich auf und schlugen die Moabiter, daß sie vor ihnen flohen. Und sie kamen in das Land Moab und schlugen es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Und sie rissen die Städte nieder, und auf alle guten Ackerstücke warfen sie ein jeder seinen Stein und füllten sie damit an, und sie verstopften alle Wasserquellen und fällten alle guten Bäume...,bis sie an Kir-Hareseth nur dessen Steine übrigließen. Und die Schleuderer umzingelten und beschossen die Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Und als der König von Moab sah, daß ihm der Streit zu stark war, nahm er siebenhundert Mann mit sich, die das Schwert zogen, um gegen den König von Edom hin durchzubrechen; aber sie vermochten es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Da nahm er seinen erstgeborenen Sohn, der an seiner Statt König werden sollte, und opferte ihn als Brandopfer auf der Mauer. Und es kam ein großer Zorn über Israel; und sie zogen von ihm ab und kehrten in ihr Land zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Und ein Weib von den Weibern der Söhne der Propheten schrie zu Elisa und sprach: Dein Knecht, mein Mann, ist gestorben, und du weißt ja, daß dein Knecht Jehova fürchtete; und der Schuldherr ist gekommen, um sich meine beiden Knaben zu Knechten zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Und Elisa sprach zu ihr: Was soll ich für dich tun? Sage mir, was du im Hause hast. Und sie sprach: Deine Magd hat gar nichts im Hause, als nur einen Krug Öl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Und er sprach: Gehe hin, erbitte dir Gefäße von draußen, von allen deinen Nachbarn, leere Gefäße, nimm nicht wenige;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'und gehe hinein und schließe die Tür hinter dir und hinter deinen Söhnen zu, und gieße in alle diese Gefäße; und was voll ist, setze beiseite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Und sie ging von ihm weg und schloß die Tür hinter sich und hinter ihren Söhnen zu; diese reichten ihr, und sie goß ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Und es geschah, als die Gefäße voll waren, da sprach sie zu ihrem Sohne: Reiche mir noch ein Gefäß. Aber er sprach zu ihr: Es ist kein Gefäß mehr da. Und das Öl stand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Und sie kam und berichtete es dem Manne Gottes; und er sprach: Gehe hin, verkaufe das Öl und bezahle deine Schuld; du aber und deine Söhne, lebet von dem Übrigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Und es geschah eines Tages, da ging Elisa nach Sunem hinüber; und daselbst war ein wohlhabendes Weib, und sie nötigte ihn, bei ihr zu essen. Und es geschah, sooft er durchzog, kehrte er dort ein, um zu essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Und sie sprach zu ihrem Manne: Siehe doch, ich merke, daß dieser ein heiliger Mann Gottes ist, der beständig bei uns durchzieht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Laß uns doch ein kleines gemauertes Obergemach machen, und ihm ein Bett und Tisch und Stuhl und Leuchter darein stellen; und es geschehe, wenn er zu uns kommt, mag er dort einkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Und es geschah eines Tages, da kam er dahin, und er kehrte in das Obergemach ein und schlief daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Und er sprach zu Gehasi, seinem Knaben: Rufe diese Sunamitin! Und er rief sie, und sie trat vor ihn hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Und er sprach zu ihm: Sprich doch zu ihr: Siehe, du hast dir unsertwegen alle diese Sorge gemacht; was ist für dich zu tun? Ist für dich mit dem König zu reden oder mit dem Heerobersten? Und sie sprach: Ich wohne inmitten meines Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Und er sprach: Was ist denn für sie zu tun? Und Gehasi sprach: Doch! Sie hat keinen Sohn, und ihr Mann ist alt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Und er sprach: Rufe sie! Und er rief sie, und sie trat in die Tür.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Und er sprach: Zu dieser bestimmten Zeit übers Jahr wirst du einen Sohn umarmen. Und sie sprach: Nicht doch mein Herr, du Mann Gottes, belüge deine Magd nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Und das Weib wurde schwanger und gebar einen Sohn zu dieser bestimmten Zeit übers Jahr, wie Elisa zu ihr geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Und das Kind wuchs heran. Und es geschah eines Tages, da ging es hinaus zu seinem Vater, zu den Schnittern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Und es sprach zu seinem Vater: Mein Kopf, mein Kopf! Und er sprach zu dem Knechte: Trage ihn zu seiner Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Und er nahm ihn auf und brachte ihn zu seiner Mutter; und er saß auf ihren Knien bis zum Mittag, und er starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Da ging sie hinauf und legte ihn auf das Bett des Mannes Gottes, und schloß hinter ihm zu und ging hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Und sie rief ihren Mann und sprach: Sende mir doch einen von den Knaben und eine von den Eselinnen, und ich will zu dem Manne Gottes laufen und wiederkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Und er sprach: Warum willst du heute zu ihm gehen? Es ist weder Neumond noch Sabbath. Und sie sprach: Es ist gut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Und sie sattelte die Eselin und sprach zu ihrem Knaben: Treibe immerfort; halte mich nicht auf im Reiten, es sei denn, daß ich es dir sage!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'So zog sie hin und kam zu dem Manne Gottes auf den Berg Karmel. Und es geschah, als der Mann Gottes sie von ferne sah, da sprach er zu Gehasi, seinem Knaben: Siehe da, die Sunamitin!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Nun laufe ihr doch entgegen und sprich zu ihr: Geht es dir wohl? Geht es deinem Manne wohl? Geht es dem Kinde wohl?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Und sie sprach: Wohl. Und sie kam zu dem Manne Gottes auf den Berg und umfaßte seine Füße. Da trat Gehasi herzu, um sie wegzustoßen. Aber der Mann Gottes sprach: Laß sie! Denn ihre Seele ist betrübt; und Jehova hat es mir verborgen und mir nicht kundgetan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Und sie sprach: Habe ich einen Sohn von meinem Herrn erbeten? Habe ich nicht gesagt: Täusche mich nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Da sprach er zu Gehasi: Gürte deine Lenden, und nimm meinen Stab in deine Hand und gehe hin; wenn du jemand triffst, grüße ihn nicht, und wenn jemand dich grüßt, antworte ihm nicht; und lege meinen Stab auf das Angesicht des Knaben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Und die Mutter des Knaben sprach: So wahr Jehova lebt und deine Seele lebt, wenn ich von dir lasse! Da machte er sich auf und ging ihr nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Gehasi aber war ihnen vorausgegangen und hatte den Stab auf das Angesicht des Knaben gelegt; aber da war keine Stimme und kein Aufmerken. Und er kehrte zurück, ihm entgegen, und berichtete ihm und sprach: Der Knabe ist nicht erwacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Und als Elisa in das Haus kam, siehe, da war der Knabe tot, hingelegt auf sein Bett.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Und er ging hinein und schloß die Tür hinter ihnen beiden zu und betete zu Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Und er stieg hinauf und legte sich auf das Kind, und er legte seinen Mund auf dessen Mund, und seine Augen auf dessen Augen, und seine Hände auf dessen Hände und beugte sich über dasselbe; und das Fleisch des Kindes wurde warm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Und er kam zurück und ging im Hause einmal dahin und einmal dorthin, und er stieg wieder hinauf und beugte sich über ihn. Da nieste der Knabe siebenmal, und der Knabe schlug seine Augen auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Und er rief Gehasi und sprach: Rufe diese Sunamitin. Und er rief sie, und sie kam zu ihm herein. Und er sprach: Nimm deinen Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Da kam sie und fiel ihm zu Füßen und beugte sich zur Erde nieder; und sie nahm ihren Sohn und ging hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Elisa aber kehrte nach Gilgal zurück. Und es war Hungersnot im Lande. Und die Söhne der Propheten saßen vor ihm. Und er sprach zu seinem Knaben: Setze den großen Topf auf und koche ein Gericht für die Söhne der Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Da ging einer auf das Feld hinaus, um Kräuter zu lesen, und er fand eine wilde Rebe und las davon wilde Koloquinthen, sein Kleid voll, und er kam und zerschnitt sie in den Kochtopf, denn sie kannten sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Und sie schütteten es aus zum Essen für die Männer. Aber es geschah, als sie von dem Gericht aßen, da schrieen sie und sprachen: Der Tod ist im Topfe, Mann Gottes! Und sie konnten es nicht essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Da sprach er: So holet Mehl her! Und er warf es in den Topf und sprach: Schütte es aus für die Leute, daß sie essen. Und es war nichts Schlimmes mehr im Topfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Und ein Mann kam von Baal-Schalischa und brachte dem Manne Gottes Brot der Erstlinge, zwanzig Gerstenbrote, und Gartenkorn in seinem Sacke. Und er sprach: Gib es den Leuten, daß sie essen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Und sein Diener sprach: Wie soll ich dieses hundert Männern vorsetzen? Und er sprach: Gib es den Leuten, daß sie essen! Denn so spricht Jehova: Man wird essen und übriglassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Und er setzte es ihnen vor; und sie aßen und ließen übrig, nach dem Worte Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Und Naaman, der Heeroberste des Königs von Syrien, war ein großer Mann vor seinem Herrn und angesehen; denn durch ihn hatte Jehova den Syrern Sieg gegeben; und der Mann war ein Kriegsheld, aber aussätzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Und die Syrer waren in Streifscharen ausgezogen und hatten aus dem Lande Israel ein junges Mädchen gefangen weggeführt, und sie war vor dem Weibe Naamans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Und sie sprach zu ihrer Herrin: Ach, wäre doch mein Herr vor dem Propheten, der zu Samaria wohnt! Dann würde er ihn von seinem Aussatz heilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Und Naaman ging und berichtete es seinem Herrn und sprach: So und so hat das Mädchen geredet, das aus dem Lande Israel ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Da sprach der König von Syrien: Geh, ziehe hin, und ich will an den König von Israel einen Brief senden. Und er ging hin und nahm mit sich zehn Talente Silber und sechstausend Sekel Gold und zehn Wechselkleider.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Und er brachte den Brief zu dem König von Israel, und er lautete also: Und nun, wenn dieser Brief zu dir kommt, siehe, ich habe meinen Knecht Naaman zu dir gesandt, daß du ihn seinem Aussatz heilest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Und es geschah, als der König von Israel den Brief gelesen hatte, da zerriß er seine Kleider und sprach: Bin ich Gott, um zu töten und lebendig zu machen, daß dieser zu mir sendet, einen Mann von seinem Aussatz zu heilen? Aber fürwahr, erkennet doch und sehet, daß er einen Anlaß an mir sucht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Und es geschah, als Elisa, der Mann Gottes, hörte, daß der König von Israel seine Kleider zerrissen hatte, da sandte er zu dem König und ließ ihm sagen: Warum hast du deine Kleider zerrissen? Laß ihn doch zu mir kommen, und er soll erkennen, daß ein Prophet in Israel ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Und Naaman kam mit seinen Rossen und mit seinen Wagen, und hielt am Eingang des Hauses Elisas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Und Elisa sandte einen Boten zu ihm und ließ ihm sagen: Gehe hin und bade dich siebenmal im Jordan, so wird dir dein Fleisch wieder werden, und du wirst rein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Da wurde Naaman zornig und zog weg; und er sprach: Siehe, ich hatte gedacht: Er wird gewißlich zu mir herauskommen und hintreten und den Namen Jehovas, seines Gottes, anrufen und wird seine Hand über die Stelle schwingen und so den Aussätzigen heilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Sind nicht Abana und Parpar, die Flüsse von Damaskus, besser als alle Wasser von Israel? Kann ich mich nicht darin baden und rein werden? Und er wandte sich und zog weg im Grimm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Da traten seine Knechte herzu und redeten zu ihm und sprachen: Mein Vater, hätte der Prophet etwas Großes zu dir geredet, würdest du es nicht tun? Wieviel mehr denn, da er zu dir gesagt hat: Bade dich, und du wirst rein sein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Da stieg er hinab und tauchte sich im Jordan siebenmal unter, nach dem Worte des Mannes Gottes. Da wurde sein Fleisch wieder wie das Fleisch eines jungen Knaben, und er war rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Und er kehrte zu dem Manne Gottes zurück, er und sein ganzer Zug, und er kam und trat vor ihn und sprach: Siehe doch, ich erkenne, daß es auf der ganzen Erde keinen Gott gibt, als nur in Israel! Und nun nimm doch ein Geschenk von deinem Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Aber er sprach: So wahr Jehova lebt, vor dessen Angesicht ich stehe, wenn ich es nehmen werde! Und er drang in ihn, es zu nehmen; aber er weigerte sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Da sprach Naaman: Wenn nicht, so werde doch deinem Knechte die Last eines Maultiergespannes Erde gegeben; denn dein Knecht wird nicht mehr anderen Göttern Brandopfer und Schlachtopfer opfern, sondern nur Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'In diesem Stücke wolle Jehova deinem Knechte vergeben: Wenn mein Herr in das Haus Rimmons geht, um sich daselbst niederzubeugen, denn er lehnt sich auf meine Hand, und ich beuge mich nieder im Hause Rimmons, ja, wenn ich mich niederbeuge im Hause Rimmons, so möge doch Jehova deinem Knechte in diesem Stücke vergeben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Und er sprach zu ihm: Gehe hin in Frieden. Und er zog von ihm weg eine Strecke Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Da sprach Gehasi, der Knabe Elisas, des Mannes Gottes: Siehe, mein Herr hat Naaman, diesen Syrer, verschont, daß er nicht aus seiner Hand genommen, was er gebracht hat; so wahr Jehova lebt, wenn ich ihm nicht nachlaufe und etwas von ihm nehme!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Und Gehasi eilte Naaman nach. Und als Naaman sah, daß er ihm nachlief, sprang er von dem Wagen herab, ihm entgegen, und sprach: Steht es wohl?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Und er sprach: Es steht wohl. Mein Herr sendet mich und läßt dir sagen: Siehe, eben jetzt sind vom Gebirge Ephraim zwei Knaben von den Söhnen der Propheten zu mir gekommen; gib ihnen doch ein Talent Silber und zwei Wechselkleider.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Und Naaman sprach: Laß es dir gefallen, nimm zwei Talente. Und er drang in ihn und band zwei Talente Silber in zwei Beutel, und zwei Wechselkeider, und gab es zweien seiner Knaben; und sie trugen es vor ihm her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Als er aber an den Hügel kam, nahm er es aus ihrer Hand und brachte es im Hause unter; dann entließ er die Männer, und sie gingen weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Er aber ging hinein und trat vor seinen Herrn. Da sprach Elisa zu ihm: Woher, Gehasi? Und er sprach: Dein Knecht ist weder dahin noch dorthin gegangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Und er sprach zu ihm: Ging mein Herz nicht mit, als der Mann sich von seinem Wagen herab dir entgegenwandte? Ist es Zeit, Silber zu nehmen und Kleider zu nehmen, und Olivenbäume und Weinberge, und Kleinvieh und Rinder, und Knechte und Mägde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'So wird der Aussatz Naamans an dir haften und an deinem Samen ewiglich. Und er ging von ihm hinaus, aussätzig wie Schnee.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Und die Söhne der Propheten sprachen zu Elisa: Siehe doch, der Ort, wo wir vor dir wohnen, ist uns zu enge;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'laß uns doch an den Jordan gehen und von dannen ein jeder einen Balken holen, und uns dort einen Ort herrichten, um daselbst zu wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Und er sprach: Gehet hin. Und einer sprach: Laß es dir doch gefallen und gehe mit deinen Knechten! Und er sprach: Ich will mitgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Und er ging mit ihnen; und sie kamen an den Jordan und hieben die Bäume um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Es geschah aber, als einer einen Balken fällte, da fiel das Eisen ins Wasser; und er schrie und sprach: Ach, mein Herr! Und es war entlehnt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Und der Mann Gottes sprach: Wohin ist es gefallen? Und er zeigte ihm die Stelle; da schnitt er ein Holz ab und warf es hinein und machte das Eisen schwimmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Und er sprach: Nimm es dir auf. Und er streckte seine Hand aus und nahm es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Und der König von Syrien führte Krieg wider Israel; und er beriet sich mit seinen Knechten und sprach: An dem und dem Orte soll mein Lager sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Da sandte der Mann Gottes zum König von Israel und ließ ihm sagen: Hüte dich, diesen Ort zu vernachlässigen; denn dort kommen die Syrer herab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Und der König von Israel sandte an den Ort, den der Mann Gottes ihm gesagt und vor dem er ihn gewarnt hatte, und er verwahrte sich daselbst; und das geschah nicht einmal und nicht zweimal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Da wurde das Herz des Königs von Syrien über diese Sache beunruhigt; und er rief seine Knechte und sprach zu ihnen: Könnt ihr mir nicht kundtun, wer von den Unsrigen für den König von Israel ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Und einer von seinen Knechten sprach: Nicht doch, mein Herr König; sondern Elisa, der Prophet, der in Israel ist, tut dem König von Israel die Worte kund, die du in deinem Schlafgemach redest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Da sprach er: Gehet hin und sehet, wo er ist; und ich werde hinsenden und ihn holen. Und es wurde ihm berichtet und gesagt: Siehe, er ist in Dothan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Da sandte er Rosse und Wagen dorthin und ein starkes Heer; und sie kamen des Nachts und umzingelten die Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Und als der Diener des Mannes Gottes früh aufstand und hinaustrat, siehe da, ein Heer umringte die Stadt, und Rosse und Wagen. Und sein Knabe sprach zu ihm: Ach, mein Herr! Was sollen wir tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Aber er sprach: Fürchte dich nicht! Denn mehr sind derer, die bei uns, als derer, die bei ihnen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Und Elisa betete und sprach: Jehova, öffne doch seine Augen, daß er sehe! Da öffnete Jehova die Augen des Knaben; und er sah: und siehe, der Berg war voll feuriger Rosse und Wagen, rings um Elisa her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Und sie kamen zu ihm herab; und Elisa betete zu Jehova und sprach: Schlage doch dieses Volk mit Blindheit! Und er schlug sie mit Blindheit nach dem Worte Elisas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Und Elisa sprach zu ihnen: Dies ist nicht der Weg, und dies nicht die Stadt; folget mir, und ich werde euch zu dem Manne führen, den ihr suchet. Und er führte sie nach Samaria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Und es geschah, als sie nach Samaria gekommen waren, da sprach Elisa: Jehova, öffne diesen die Augen, daß sie sehen! Da öffnete Jehova ihnen die Augen; und sie sahen: und siehe, sie waren mitten in Samaria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Und der König von Israel sprach zu Elisa, als er sie sah: Soll ich schlagen, soll ich schlagen, mein Vater?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Aber er sprach: Du sollst nicht schlagen. Würdest du die schlagen, welche du mit deinem Schwerte und mit deinem Bogen gefangen genommen hättest? Setze ihnen Brot und Wasser vor, daß sie essen und trinken und dann zu ihrem Herrn ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Und er richtete ihnen ein großes Mahl zu, und sie aßen und tranken; und er entließ sie, und sie zogen zu ihrem Herrn. Und die Streifscharen der Syrer kamen hinfort nicht mehr in das Land Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Und es geschah hernach, da versammelte Ben-Hadad, der König von Syrien, sein ganzes Heer, und zog herauf und belagerte Samaria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Und es entstand eine große Hungersnot in Samaria; und siehe, sie belagerten es, bis ein Eselskopf achtzig Sekel Silber und ein Viertel Kab Taubenmist fünf Sekel Silber galt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Und es geschah, als der König von Israel auf der Mauer einherging, da schrie ein Weib zu ihm und sprach: Hilf, mein Herr König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Aber er sprach: Hilft dir Jehova nicht, woher sollte ich dir helfen? Von der Tenne oder von der Kelter?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Und der König sprach zu ihr: Was ist dir? Und sie sprach: Dieses Weib da hat zu mir gesagt: Gib deinen Sohn her, daß wir ihn heute essen; und meinen Sohn wollen wir morgen essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Und so kochten wir meinen Sohn und aßen ihn. Und ich sprach zu ihr am anderen Tage: Gib deinen Sohn her, daß wir ihn essen! Aber sie hat ihren Sohn verborgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Und es geschah, als der König die Worte des Weibes hörte, da zerriß er seine Kleider, während er auf der Mauer einherging; und das Volk sah, und siehe, er trug Sacktuch darunter auf seinem Leibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Und er sprach: So soll mir Gott tun und so hinzufügen, wenn der Kopf Elisas, des Sohnes Saphats, heute auf ihm bleibt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Und Elisa saß in seinem Hause, und die Ältesten saßen bei ihm. Und der König sandte einen Mann vor sich her. Ehe der Bote zu ihm kam, sprach er aber zu den Ältesten: Habt ihr gesehen, daß dieser Mördersohn hergesandt hat, um mir den Kopf wegzunehmen? Sehet zu, sobald der Bote kommt, verschließet die Tür und dränget ihn mit der Tür hinweg! Ist nicht der Schall der Tritte seines Herrn hinter ihm?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Noch redete er mit ihnen, siehe, da kam der Bote zu ihm herab; und er sprach: Siehe, dieses Unglück ist von Jehova; was soll ich noch auf Jehova harren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Da sprach Elisa: Höret das Wort Jehovas! So spricht Jehova: Morgen um diese Zeit wird ein Maß Feinmehl einen Sekel gelten, und zwei Maß Gerste einen Sekel im Tore von Samaria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Da antwortete der Anführer, auf dessen Hand der König sich lehnte, dem Manne Gottes und sprach: Siehe, wenn Jehova Fenster am Himmel machte, würde wohl dieses geschehen? Und er sprach: Siehe, du wirst es mit deinen Augen sehen, aber du wirst nicht davon essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Es waren aber vier aussätzige Männer am Eingang des Tores; und sie sprachen einer zum anderen: Was bleiben wir hier, bis wir sterben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Wenn wir sprechen: Laßt uns in die Stadt gehen, so ist die Hungersnot in der Stadt, und wir werden daselbst sterben; und wenn wir hier bleiben, so werden wir auch sterben. Und nun kommt und laßt uns zu dem Lager der Syrer überlaufen; wenn sie uns am Leben lassen, so leben wir, und wenn sie uns töten, so sterben wir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Und so machten sie sich in der Dämmerung auf, um ins Lager der Syrer zu kommen; und sie kamen an das Ende des Lagers der Syrer, und siehe, kein Mensch war da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Denn der Herr hatte das Heerlager der Syrer ein Getöse von Wagen und ein Getöse von Rossen hören lassen, das Getöse einer großen Heeresmacht; und sie sprachen einer zum anderen: Siehe, der König von Israel hat die Könige der Hethiter und die Könige von Ägypten wider uns gedungen, daß sie über uns kommen sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Und sie machten sich auf und flohen in der Dämmerung; sie ließen ihre Zelte und ihre Rosse und ihre Esel, das Lager, so wie es war, und flohen um ihr Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Als nun jene Aussätzigen an das Ende des Lagers kamen, gingen sie in ein Zelt und aßen und tranken; und sie nahmen Silber daraus und Gold und Kleider und gingen hin und verbargen es. Und sie kamen wieder und gingen in ein anderes Zelt; und sie nahmen daraus und gingen hin und verbargen es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Da sprachen sie einer zum anderen: Wir tun nicht recht: Dieser Tag ist ein Tag guter Botschaft; schweigen wir aber und warten, bis der Morgen hell wird, so wird uns Schuld treffen. Und nun kommt und laßt uns hineingehen und es im Hause des Königs berichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Und sie kamen und riefen die Torwache der Stadt, und berichteten ihnen und sprachen: Wir sind in das Lager der Syrer gekommen, und siehe, kein Mensch war da, und keine Menschenstimme; sondern nur die Rosse angebunden und die Esel angebunden, und die Zelte, so wie sie waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Und sie riefen die Torwächter, und sie berichteten es drinnen im Hause des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Da stand der König in der Nacht auf und sprach zu seinen Knechten: Ich will euch sagen, was die Syrer uns getan haben: sie wissen, daß wir Hunger leiden, und sie sind aus dem Lager gegangen, um sich auf dem Felde zu verbergen, indem sie sagen: Wenn sie aus der Stadt herausgehen, so wollen wir sie lebendig greifen und in die Stadt eindringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Da antwortete einer von seinen Knechten und sprach: So nehme man doch fünf von den übrigen Rossen, die darin übriggeblieben sind (siehe, sie sind wie die ganze Menge Israels, die darin übriggeblieben, sie sind wie die ganze Menge Israels, die aufgerieben ist), und laßt uns hinsenden und sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Und sie nahmen zwei Wagen mit Rossen, und der König sandte sie hinter dem Heere der Syrer her und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Gehet hin und sehet. Und sie zogen ihnen nach bis an den Jordan; und siehe, der ganze Weg war voll Kleider und Geräte, welche die Syrer auf ihrer eiligen Flucht weggeworfen hatten. Und die Boten kehrten zurück und berichteten es dem König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Da ging das Volk hinaus und plünderte das Lager der Syrer; und es galt ein Maß Feinmehl einen Sekel, und zwei Maß Gerste einen Sekel nach dem Worte Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Der König hatte aber den Anführer, auf dessen Hand er sich lehnte, über das Tor bestellt; und das Volk zertrat ihn im Tore, und er starb, so wie der Mann Gottes geredet hatte, wie er geredet hatte, als der König zu ihm herabkam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Denn es geschah, als der Mann Gottes zu dem König redete und sprach: Zwei Maß Gerste werden morgen um diese Zeit einen Sekel gelten, und ein Maß Feinmehl einen Sekel im Tore von Samaria,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'da antwortete der Anführer dem Manne Gottes und sprach: Siehe, wenn Jehova auch Fenster am Himmel machte, würde wohl so etwas geschehen? Und er sprach: Siehe, du wirst es mit deinen Augen sehen, aber du wirst nicht davon essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Und es geschah ihm also: das Volk zertrat ihn im Tore, und er starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Und Elisa hatte zu dem Weibe, deren Sohn er lebendig gemacht hatte, geredet und gesagt: Mache dich auf und gehe hin, du und dein Haus, und weile, wo du weilen kannst; denn Jehova hat eine Hungersnot herbeigerufen, und sie kommt auch ins Land sieben Jahre lang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Und das Weib machte sich auf und tat nach dem Worte des Mannes Gottes: sie ging hin, sie und ihr Haus, und weilte in dem Lande der Philister sieben Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Und es geschah am Ende von sieben Jahren, da kehrte das Weib aus dem Lande der Philister zurück; und sie ging aus, um den König anzurufen wegen ihres Hauses und wegen ihrer Felder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Der König aber redete eben zu Gehasi, dem Knaben des Mannes Gottes, und sprach: Erzähle mir doch alle die großen Dinge, die Elisa getan hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Und es geschah, während er dem König erzählte, daß er den Toten lebendig gemacht habe, siehe, da rief das Weib, deren Sohn er lebendig gemacht hatte, den König an wegen ihres Hauses und wegen ihrer Felder. Da sprach Gehasi: Mein Herr König! Dies ist das Weib, und dies ist ihr Sohn, den Elisa lebendig gemacht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Und der König fragte das Weib, und sie erzählte ihm; und der König gab ihr einen Kämmerer mit und sprach: Erstatte alles zurück, was ihr gehört, sowie den ganzen Ertrag der Felder von dem Tage an, da sie das Land verlassen hat, bis jetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Und Elisa kam nach Damaskus. Und Ben-Hadad, der König von Syrien, war krank. Und es wurde ihm berichtet und gesagt: Der Mann Gottes ist hierher gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Da sprach der König zu Hasael: Nimm ein Geschenk mit dir und gehe dem Manne Gottes entgegen, und befrage Jehova durch ihn und sprich: Werde ich von dieser Krankheit genesen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Und Hasael ging ihm entgegen und nahm ein Geschenk mit sich: allerlei Gut von Damaskus, eine Last von vierzig Kamelen; und er kam und trat vor ihn hin und sprach: Dein Sohn Ben-Hadad, der König von Syrien, hat mich zu dir gesandt und läßt dir sagen: Werde ich von dieser Krankheit genesen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Und Elisa sprach zu ihm: Gehe hin, sprich zu ihm: Du wirst gewißlich genesen! Aber Jehova hat mir gezeigt, daß er gewißlich sterben wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Und er stellte sein Angesicht fest und richtete es auf ihn, bis er sich schämte; und der Mann Gottes weinte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Und Hasael sprach: Warum weint mein Herr? Und er sprach: Weil ich weiß, was du den Kindern Israel Übles tun wirst: ihre festen Städte wirst du in Brand stecken, und ihre Jünglinge mit dem Schwerte töten, und ihre Kindlein wirst du zerschmettern und ihre Schwangeren aufschlitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Da sprach Hasael: Was ist dein Knecht, der Hund, daß er diese große Sache tun sollte? Und Elisa sprach: Jehova hat mich dich sehen lassen als König über Syrien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Und er ging von Elisa weg und kam zu seinem Herrn; und dieser sprach zu ihm: Was hat Elisa dir gesagt? Und er sprach: Er hat mir gesagt, du werdest gewißlich genesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Und es geschah am folgenden Tage, da nahm er die Decke und tauchte sie ins Wasser und breitete sie über sein Angesicht, so daß er starb. Und Hasael ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Und im fünften Jahre Jorams, des Sohnes Ahabs, des Königs von Israel, als Josaphat König von Juda war, wurde Joram König, der Sohn Josaphats, des Königs von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Zweiunddreißig Jahre war er alt, als er König wurde, und er regierte acht Jahre zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Und er wandelte auf dem Wege der Könige von Israel, wie das Haus Ahabs tat, denn er hatte eine Tochter Ahabs zum Weibe; und er tat, was böse war in den Augen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Aber Jehova wollte Juda nicht verderben um seines Knechtes David willen, so wie er ihm gesagt hatte, daß er ihm eine Leuchte geben wolle für seine Söhne alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'In seinen Tagen fielen die Edomiter von der Botmäßigkeit Judas ab und setzten einen König über sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Da zog Joram hinüber nach Zair, und alle Wagen mit ihm. Und es geschah, als er sich des Nachts aufmachte, da schlug er die Edomiter, welche ihn und die Obersten der Wagen umringt hatten; und das Volk floh nach seinen Zelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'So fielen die Edomiter von der Botmäßigkeit Judas ab bis auf diesen Tag. Damals fiel auch Libna ab zu derselben Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Und das Übrige der Geschichte Jorams und alles was, er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Und Joram legte sich zu seinen Vätern, und er wurde bei seinen Vätern begraben in der Stadt Davids. Und Ahasja, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Im zwölften Jahre Jorams, des Sohnes Ahabs, des Königs von Israel, wurde Ahasja König, der Sohn Jorams, des Königs von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Zweiundzwanzig Jahre war Ahasja alt, als er König wurde, und er regierte ein Jahr zu Jerusalem; und der Name seiner Mutter war Athalja, die Tochter Omris, des Königs von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Und er wandelte auf dem Wege des Hauses Ahabs und tat, was böse war in den Augen Jehovas, wie das Haus Ahabs; denn er war ein Schwiegersohn des Hauses Ahabs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Und er zog mit Joram, dem Sohne Ahabs, in den Streit wider Hasael, dem König von Syrien, nach Ramoth-Gilead. Und die Syrer verwundeten Joram.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Da kehrte der König Joram zurück, um sich in Jisreel von den Wunden heilen zu lassen, welche ihm die Syrer zu Rama geschlagen hatten, als er wider Hasael, den König von Syrien, stritt. Und Ahasja, der Sohn Jorams, der König von Juda, zog hinab, um Joram, den Sohn Ahabs, in Jisreel zu besuchen, weil er krank war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Und Elisa, der Prophet, rief einen von den Söhnen der Propheten und sprach zu ihm: Gürte deine Lenden und nimm diese Ölflasche in deine Hand und gehe nach Ramoth-Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Und wenn du dahin gekommen bist, so sieh dich daselbst nach Jehu um, dem Sohne Josaphats, des Sohnes Nimsis; und gehe hinein, und laß ihn aufstehen aus der Mitte seiner Brüder und führe ihn in ein inneres Gemach;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'und nimm die Ölflasche und gieße sie über sein Haupt aus und sprich: So spricht Jehova: Ich habe dich zum König über Israel gesalbt! und öffne die Tür und fliehe, und harre nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Und der Jüngling, der Knabe des Propheten, ging nach Ramoth-Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Und er kam hinein, und siehe, da saßen die Obersten des Heeres. Und er sprach: Ich habe ein Wort an dich, Oberster. Und Jehu sprach: An wen von uns allen? Und er sprach: An dich, Oberster.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Da stand Jehu auf und ging ins Haus hinein; und er goß das Öl auf sein Haupt und sprach zu ihm: So spricht Jehova, der Gott Israels: Ich habe dich zum König gesalbt über das Volk Jehovas, über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Und du sollst das Haus Ahabs, deines Herrn, erschlagen; und ich werde das Blut meiner Knechte, der Propheten, und das Blut aller Knechte Jehovas rächen von der Hand Isebels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Ja, das ganze Haus Ahabs soll umkommen; und ich werde von Ahab ausrotten, was männlich ist, sowohl den Gebundenen als auch den Freien in Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Und ich werde das Haus Ahabs machen wie das Haus Jerobeams, des Sohnes Nebats, und wie das Haus Baesas, des Sohnes Achijas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Isebel aber sollen die Hunde fressen auf dem Ackerstück zu Jisreel, und niemand wird sie begraben. Und er öffnete die Tür und entfloh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Und Jehu kam heraus zu den Knechten seines Herrn. Und man sprach zu ihm: Steht es wohl? Warum ist dieser Rasende zu dir gekommen? Und er sprach zu ihnen: Ihr kennet ja den Mann und seine Rede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Und sie sprachen: Lüge! Tue es uns doch kund! Da sprach er: So und so hat er zu mir geredet und gesagt: So spricht Jehova: Ich habe dich zum König über Israel gesalbt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Da eilten sie und nahmen ein jeder sein Kleid und legten es unter ihn, auf die Stufen selbst; und sie stießen in die Posaune und sprachen: Jehu ist König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Und so machte Jehu, der Sohn Josaphats, des Sohnes Nimsis, eine Verschwörung gegen Joram. (Joram aber, er und ganz Israel, hatte Ramoth-Gilead gegen Hasael, den König von Syrien, verteidigt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'und der König Joram war zurückgekehrt, um sich in Jisreel von den Wunden heilen zu lassen, welche ihm die Syrer geschlagen hatten, als er wider Hasael, den König von Syrien, stritt.) Und Jehu sprach: Wenn es euer Wille ist, so soll niemand aus der Stadt entrinnen, um hinzugehen, es in Jisreel zu berichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Und Jehu saß auf und zog nach Jisreel; denn Joram lag daselbst. Und Ahasja, der König von Juda, war hinabgezogen, um Joram zu besuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Und der Wächter stand auf dem Turme zu Jisreel und sah den Haufen Jehus, wie er herankam, und sprach: Ich sehe einen Haufen. Und Joram sprach: Nimm einen Reiter und sende ihn ihnen entgegen, daß er spreche:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Ist es Friede? Da ritt der Berittene ihm entgegen und sprach: So spricht der König: Ist es Friede? Und Jehu sprach: Was hast du mit dem Frieden zu schaffen? Wende dich hinter mich! Und der Wächter berichtete und sprach: Der Bote ist bis zu ihnen gekommen und kehrt nicht zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Da sandte er einen zweiten Berittenen; und er kam zu ihnen und sprach: So spricht der König: Ist es Friede? Und Jehu sprach: Was hast du mit dem Frieden zu schaffen? Wende dich hinter mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Und der Wächter berichtete und sprach: Er ist bis zu ihnen gekommen und kehrt nicht zurück. Und das Treiben ist wie das Treiben Jehus, des Sohnes Nimsis; denn er treibt unsinnig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Da sprach Joram: Spannet an! Und man spannte seinen Wagen an; und Joram, der König von Israel, und Ahasja, der König von Juda, zogen aus, ein jeder auf seinem Wagen: sie zogen aus, Jehu entgegen, und sie trafen ihn auf dem Grundstück Naboths, des Jisreeliters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Und es geschah, als Joram den Jehu sah, da sprach er: Ist es Friede, Jehu? Aber er sprach: Was, Friede, während der vielen Hurereien Isebels, deiner Mutter, und ihrer vielen Zaubereien!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Da wandte Joram um und floh, und sprach zu Ahasja: Verrat, Ahasja!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Jehu aber nahm seinen Bogen zur Hand und traf Joram zwischen seine Arme, so daß der Pfeil ihm durch das Herz fuhr; und er sank nieder in seinem Wagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Und er sprach zu Bidkar, seinem Anführer: Nimm ihn und wirf ihn auf das Grundstück Naboths, des Jisreeliters. Denn gedenke, wie wir, ich und du, neben einander hinter seinem Vater Ahab herritten, und Jehova diesen Ausspruch über ihn tat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Wenn ich nicht das Blut Naboths und das Blut seiner Söhne gestern gesehen habe! spricht Jehova; und ich werde es dir vergelten auf diesem Grundstück, spricht Jehova. Und nun nimm ihn auf, wirf ihn auf das Grundstück, nach dem Worte Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Als Ahasja, der König von Juda, das sah, floh er des Weges zum Gartenhause. Und Jehu jagte ihm nach und sprach: Auch ihn erschlaget auf dem Wagen! Und sie verwundeten ihn auf der Anhöhe Gur, die bei Jibleam ist. Und er floh nach Megiddo und starb daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Und seine Knechte führten ihn zu Wagen nach Jerusalem, und sie begruben ihn in seinem Begräbnis, bei seinen Vätern, in der Stadt Davids. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Und im elften Jahre Jorams, des Sohnes Ahabs, war Ahasja König geworden über Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Und Jehu kam nach Jisreel. Und als Isebel es hörte, da tat sie Schminke an ihre Augen und schmückte ihr Haupt und schaute zum Fenster hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Und als Jehu in das Tor kam, da sprach sie: Erging es Simri wohl, dem Mörder seines Herrn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Und er erhob sein Angesicht zum Fenster und sprach: Wer ist mit mir, wer? Da blickten zwei, drei Kämmerer zu ihm hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Und er sprach: Stürzet sie herab! Und sie stürzten sie hinab; und es spritzte von ihrem Blute an die Wand und an die Rosse, und er zertrat sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Und er ging hinein und aß und trank; und er sprach: Sehet doch nach dieser Verfluchten und begrabet sie, denn sie ist eine Königstochter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Und sie gingen hin, um sie zu begraben; aber sie fanden nichts mehr von ihr, als nur den Schädel und die Füße und die Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Und sie kamen zurück und berichteten es ihm. Und er sprach: Das ist das Wort Jehovas, das er durch seinen Knecht Elia, den Tisbiter, geredet hat, indem er sprach: Auf dem Grundstück zu Jisreel sollen die Hunde das Fleisch Isebels fressen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'und der Leichnam Isebels soll auf dem Grundstück zu Jisreel dem Miste auf dem Felde gleichen, daß man nicht wird sagen können: Das ist Isebel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Und Ahab hatte siebzig Söhne zu Samaria. Und Jehu schrieb Briefe und sandte sie nach Samaria an die Obersten von Jisreel, die Ältesten, und an die Erzieher der Söhne Ahabs, und sie lauteten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Und nun, wenn dieser Brief zu euch kommt, bei euch sind ja die Söhne eures Herrn, und bei euch die Wagen und die Rosse, und eine feste Stadt und Waffen-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'so ersehet den besten und tüchtigsten aus den Söhnen eures Herrn, und setzet ihn auf den Thron seines Vaters; und streitet für das Haus eures Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Aber sie fürchteten sich gar sehr und sprachen: Siehe, die zwei Könige konnten vor ihm nicht standhalten, und wie wollten wir bestehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Und der über das Haus und der über die Stadt war und die Ältesten und die Erzieher sandten hin zu Jehu und ließen ihm sagen: Wir sind deine Knechte, und alles, was du zu uns sagen wirst, wollen wir tun; wir wollen niemand zum König machen; tue, was gut ist in deinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Da schrieb er zum zweiten Male einen Brief an sie, welcher lautete: Wenn ihr für mich seid und auf meine Stimme höret, so nehmet die Köpfe der Männer, der Söhne eures Herrn, und kommet morgen um diese Zeit zu mir nach Jisreel. (Und die Königssöhne, siebzig Mann, waren bei den Großen der Stadt, die sie auferzogen.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Und es geschah, als der Brief zu ihnen kam, da nahmen sie die Söhne des Königs und schlachteten sie, siebzig Mann, und legten ihre Köpfe in Körbe und sandten sie zu ihm nach Jisreel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Und ein Bote kam und berichtete ihm und sprach: Man hat die Köpfe der Königssöhne gebracht. Und er sprach: Leget sie in zwei Haufen an den Eingang des Tores, bis zum Morgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Und es geschah am Morgen, da ging er hinaus und trat hin und sprach zu dem ganzen Volke: Ihr seid gerecht! Siehe, ich habe eine Verschwörung wider meinen Herrn gemacht und habe ihn ermordet; wer aber hat alle diese erschlagen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Wisset denn, daß nichts zur Erde fallen wird von dem Worte Jehovas, das Jehova wider das Haus Ahabs geredet hat; und Jehova hat getan, was er durch seinen Knecht Elia geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Und Jehu erschlug alle, welche vom Hause Ahabs in Jisreel übriggeblieben waren, und alle seine Großen und seine Bekannten und seine Priester, bis er ihm keinen Entronnenen übrigließ.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Und er machte sich auf und ging und zog nach Samaria. Er war bei Beth-Eked-Haroim auf dem Wege,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'da traf Jehu die Brüder Ahasjas, des Königs von Juda; und er sprach: Wer seid ihr? Und sie sprachen: Wir sind die Brüder Ahasjas und sind herabgekommen, um die Söhne des Königs und die Söhne der Königin zu begrüßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Und er sprach: Greifet sie lebendig! Und sie griffen sie lebendig und schlachteten sie bei der Zisterne von Beth-Eked, zweiundvierzig Mann, und er ließ keinen von ihnen übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Und er zog von dannen und traf Jonadab, den Sohn Rekabs, der ihm entgegenkam; und er grüßte ihn und sprach zu ihm: Ist dein Herz redlich, wie mein Herz gegen dein Herz? Und Jonadab sprach: Es ist\'s. Wenn es so ist, so gib mir deine Hand. Und er gab ihm seine Hand. Da ließ er ihn zu sich auf den Wagen steigen und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Komm mit mir und sieh meinen Eifer für Jehova an! Und sie fuhren ihn auf seinem Wagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Und als er nach Samaria kam, erschlug er alle, welche von Ahab in Samaria übriggeblieben waren, bis er ihn vertilgte, nach dem Worte Jehovas, das er zu Elia geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Und Jehu versammelte das ganze Volk und sprach zu ihnen: Ahab hat dem Baal ein wenig gedient, Jehu will ihm viel dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Und nun, rufet alle Propheten des Baal, alle seine Diener und alle seine Priester zu mir; kein Mann werde vermißt! Denn ich habe ein großes Schlachtopfer für den Baal. Keiner, der vermißt wird, soll am Leben bleiben! Jehu handelte aber mit Hinterlist, um die Diener des Baal umzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Und Jehu sprach: Heiliget dem Baal eine Festversammlung! Und man rief sie aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Und Jehu sandte in ganz Israel umher. Da kamen alle Diener des Baal: keiner blieb übrig, der nicht gekommen wäre; und sie gingen in das Haus des Baal, und das Haus des Baal ward voll von einem Ende bis zum anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Und er sprach zu dem, der über die Kleiderkammer war: Bringe Kleider heraus für alle Diener des Baal! Und er brachte ihnen Kleidung heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Und Jehu und Jonadab, der Sohn Rekabs, gingen in das Haus des Baal; und er sprach zu den Dienern des Baal: Forschet und sehet zu, daß nicht etwa einer von den Dienern Jehovas hier bei euch sei, sondern nur Diener des Baal allein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Und sie gingen hinein, um Schlachtopfer und Brandopfer zu opfern. Jehu hatte sich aber draußen achtzig Mann bestellt und gesagt: Derjenige, welcher einen von den Männern entrinnen läßt, die ich in eure Hände gebracht habe, sein Leben soll statt dessen Leben sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Und es geschah, als man das Opfern des Brandopfers vollendet hatte, da sprach Jehu zu den Läufern und zu den Anführern: Gehet hinein, erschlaget sie; keiner komme heraus! Und sie schlugen sie mit der Schärfe des Schwertes. Und die Läufer und die Anführer warfen sie hin. Und sie gingen nach dem Stadtteil des Baalhauses,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'und brachten die Bildsäulen des Baalhauses heraus und verbrannten sie; und sie rissen die Bildsäule des Baal nieder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'und sie rissen das Haus des Baal nieder und machten Kotstätten daraus bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Also vertilgte Jehu den Baal aus Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Nur von den Sünden Jerobeams, des Sohnes Nebats, wodurch er Israel sündigen gemacht hatte, von denen wich Jehu nicht ab: von den goldenen Kälbern, die zu Bethel und zu Dan waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Und Jehova sprach zu Jehu: Weil du wohl ausgerichtet hast, was recht ist in meinen Augen, und an dem Hause Ahabs getan hast nach allem, was in meinem Herzen war, so sollen dir Söhne des vierten Gliedes auf dem Throne Israels sitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Aber Jehu achtete nicht darauf, in dem Gesetze Jehovas, des Gottes Israels, mit seinem ganzen Herzen zu wandeln; er wich nicht von den Sünden Jerobeams, wodurch er Israel sündigen gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'In jenen Tagen begann Jehova abzuhauen unter Israel; und Hasael schlug sie im ganzen Gebiet Israels,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'vom Jordan an, gegen Sonnenaufgang, das ganze Land Gilead, die Gaditer und die Rubeniter und die Manassiter, von Aroer an, das am Flusse Arnon liegt, sowohl Gilead als Basan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Und das Übrige der Geschichte Jehus und alles, was er getan hat, und alle seine Macht, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Und Jehu legte sich zu seinen Vätern, und man begrub ihn zu Samaria. Und Joahas, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Die Tage aber, die Jehu über Israel zu Samaria regierte, waren achtundzwanzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Und als Athalja, die Mutter Ahasjas, sah, daß ihr Sohn tot war, da machte sie sich auf und brachte allen königlichen Samen um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Aber Joseba, die Tochter des Königs Joram, die Schwester Ahasjas, nahm Joas, den Sohn Ahasjas, und stahl ihn weg aus der Mitte der Königssöhne, die getötet wurden, und tat ihn und seine Amme in das Schlafgemach; und so verbargen sie ihn vor Athalja, und er wurde nicht getötet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Und er war sechs Jahre bei ihr im Hause Jehovas versteckt. Athalja aber regierte über das Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Und im siebten Jahre sandte Jojada hin und ließ die Obersten über hundert der Karier und der Läufer holen und zu sich in das Haus Jehovas kommen; und er machte einen Bund mit ihnen und ließ sie schwören im Hause Jehovas, und er zeigte ihnen den Sohn des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Und er gebot ihnen und sprach: Dies ist es, was ihr tun sollt: Ein Drittel von euch, die ihr am Sabbath antretet, soll Wache halten im Hause des Königs,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'und ein Drittel soll am Tore Sur, und ein Drittel am Tore hinter den Läufern sein; und ihr sollt der Hut des Hauses warten zur Abwehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Und die zwei anderen Abteilungen von euch, alle, die am Sabbath abtreten, die sollen im Hause Jehovas Wache halten bei dem König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Und ihr sollt den König rings umgeben, ein jeder mit seinen Waffen in seiner Hand; und wer in die Reihen eindringt, soll getötet werden; und ihr sollt bei dem König sein, wenn er ausgeht und wenn er eingeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Und die Obersten über hundert taten nach allem, was der Priester Jojada geboten hatte; und sie nahmen ein jeder seine Männer, die am Sabbath antretenden samt den am Sabbath abtretenden, und kamen zu dem Priester Jojada.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Und der Priester gab den Obersten über hundert die Speere und die Schilde, welche dem König David gehört hatten, die im Hause Jehovas waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Und die Läufer stellten sich auf, ein jeder mit seinen Waffen in seiner Hand, von der rechten Seite des Hauses bis zur linken Seite des Hauses, gegen den Altar und gegen das Haus hin, rings um den König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Und er führte den Sohn des Königs heraus und setzte ihm die Krone auf und gab ihm das Zeugnis, und sie machten ihn zum König und salbten ihn; und sie klatschten in die Hände und riefen: Es lebe der König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Und als Athalja das Geschrei der Läufer und des Volkes hörte, kam sie zu dem Volke in das Haus Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Und sie sah: und siehe, der König stand auf dem Standorte, nach dem Gebrauch, und die Obersten und die Trompeter bei dem König; und alles Volk des Landes war fröhlich und stieß in die Trompeten. Da zerriß Athalja ihre Kleider und rief: Verschwörung, Verschwörung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Und der Priester Jojada gebot den Obersten über hundert, die über das Heer bestellt waren, und sprach zu ihnen: Führet sie hinaus außerhalb der Reihen, und wer ihr folgt, den tötet mit dem Schwerte! Denn der Priester sprach: Sie soll nicht in dem Hause Jehovas getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Und sie machten ihr Platz, und sie ging in das Haus des Königs auf dem Wege des Eingangs für die Rosse; und sie wurde daselbst getötet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Und Jojada machte einen Bund zwischen Jehova und dem König und dem Volke, daß sie das Volk Jehovas sein sollten, und zwischen dem König und dem Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Da ging alles Volk des Landes in das Haus des Baal und riß es nieder; seine Altäre und seine Bilder zerschlugen sie gänzlich; und Mattan, den Priester des Baal, töteten sie vor den Altären. Und der Priester setzte Aufseher über das Haus Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Und er nahm die Obersten über hundert und die Karier und die Läufer und alles Volk des Landes, und sie führten den König aus dem Hause Jehovas hinab und kamen auf dem Wege des Läufertores in das Haus des Königs; und er setzte sich auf den Thron der Könige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Und alles Volk des Landes freute sich, und die Stadt hatte Ruhe. Athalja aber hatten sie im Hause des Königs mit dem Schwerte getötet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, '(H12:1) Sieben Jahre war Joas alt, als er König wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, '(H12:1) Im siebten Jahre Jehus wurde Joas König, und er regierte vierzig Jahre zu Jerusalem; und der Name seiner Mutter war Zibja, von Beerseba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Und Joas tat, was recht war in den Augen Jehovas, solange der Priester Jojada ihn unterwies.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Doch die Höhen wichen nicht; das Volk opferte und räucherte noch auf den Höhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Und Joas sprach zu den Priestern: Alles Geld der geheiligten Dinge, welches in das Haus Jehovas gebracht wird: das Geld eines jeden Gemusterten, das Geld der Seelen, je nach der Schätzung eines jeden, und alles Geld, das jemand ins Herz kommt, in das Haus Jehovas zu bringen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'sollen die Priester an sich nehmen, ein jeder von seinen Bekannten; und sie selbst sollen das Baufällige des Hauses ausbessern, alles, was daselbst Baufälliges gefunden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Und es geschah, im dreiundzwanzigsten Jahre des Königs Joas hatten die Priester das Baufällige des Hauses nicht ausgebessert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Da rief der König Joas den Priester Jojada und die Priester und sprach zu ihnen: Warum bessert ihr das Baufällige des Hauses nicht aus? Und nun sollt ihr kein Geld von euren Bekannten nehmen, sondern ihr sollt es für das Baufällige des Hauses hergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Und die Priester willigten ein, kein Geld mehr von dem Volke zu nehmen, noch auch das Baufällige des Hauses auszubessern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Und der Priester Jojada nahm eine Lade und bohrte ein Loch in ihren Deckel, und er stellte sie neben den Altar, zur Rechten, wenn man in das Haus Jehovas hineingeht; und die Priester, welche die Schwelle hüteten, legten alles Geld darein, welches in das Haus Jehovas gebracht wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Und es geschah, wenn sie sahen, daß viel Geld in der Lade war, so kamen der Schreiber des Königs und der Hohepriester herauf, und sie banden das Geld, welches sich im Hause Jehovas vorfand, zusammen und zählten es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Und sie gaben das abgewogene Geld in die Hände derer, welche das Werk betrieben, die über das Haus Jehovas bestellt waren; und diese gaben es aus an die Zimmerleute und an die Bauleute, welche am Hause Jehovas arbeiteten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'und an die Maurer und an die Steinhauer, und um Holz und gehauene Steine zu kaufen, um das Baufällige des Hauses Jehovas auszubessern, und für alles, was zur Ausbesserung des Hauses ausgegeben wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Doch wurden für das Haus Jehovas keine silbernen Becken, Messer, Sprengschalen, Trompeten, noch irgend ein goldenes Gerät oder ein silbernes Gerät, von dem Gelde gemacht, welches in das Haus Jehovas gebracht wurde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'sondern man gab es denen, welche das Werk betrieben, daß sie das Haus Jehovas damit ausbesserten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Und man rechnete nicht mit den Männern, in deren Hand man das Geld gab, um es denen zu geben, welche das Werk taten; denn sie handelten getreulich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Das Geld von Schuldopfern und das Geld von Sündopfern wurde nicht in das Haus Jehovas gebracht; es war für die Priester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Damals zog Hasael, der König von Syrien, herauf und stritt wider Gath und nahm es ein. Und Hasael richtete sein Angesicht darauf, wider Jerusalem hinaufzuziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Da nahm Joas, der König von Juda, alle geheiligten Dinge, die Josaphat und Joram und Ahasja, seine Väter, die Könige von Juda, geheiligt hatten, und seine geheiligten Dinge, und all das Gold, das sich in den Schätzen des Hauses Jehovas und des Hauses des Königs vorfand, und sandte es Hasael, dem König von Syrien. Und er zog ab von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Und das Übrige der Geschichte Joas\' und alles, was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Und seine Knechte standen auf und machten eine Verschwörung, und sie erschlugen Joas im Hause Millo, wo man nach Silla hinabgeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Und Josakar, der Sohn Schimeaths, und Josabad, der Sohn Schomers, seine Knechte, erschlugen ihn, und er starb; und man begrub ihn bei seinen Vätern in der Stadt Davids. Und Amazja, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Im dreiundzwanzigsten Jahre Joas\', des Sohnes Ahasjas, des Königs von Juda, wurde Joahas, der Sohn Jehus, König über Israel zu Samaria und regierte siebzehn Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Und er tat, was böse war in den Augen Jehovas; und er wandelte den Sünden Jerobeams nach, des Sohnes Nebats, wodurch er Israel sündigen gemacht hatte: er wich nicht davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Da entbrannte der Zorn Jehovas wider Israel; und er gab sie in die Hand Hasaels, des Königs von Syrien, und in die Hand Ben-Hadads, des Sohnes Hasaels, alle Tage hindurch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Und Joahas flehte Jehova an; und Jehova hörte auf ihn, denn er sah den Druck Israels, denn der König von Syrien drückte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, '(Und Jehova gab Israel einen Retter, und sie kamen aus der Hand der Syrer heraus; und die Kinder Israel wohnten in ihren Zelten wie zuvor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Dennoch wichen sie nicht von den Sünden des Hauses Jerobeams, wodurch er Israel sündigen gemacht hatte: sie wandelten darin; auch die Aschera blieb in Samaria stehen.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Denn er hatte dem Joahas kein Volk übriggelassen, als nur fünfzig Reiter und zehn Wagen und zehntausend Mann zu Fuß; denn der König von Syrien hatte sie vernichtet und sie gemacht wie den Staub, den man zertritt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Und das Übrige der Geschichte Joahas\' und alles, was er getan hat, und seine Macht, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Und Joahas legte sich zu seinen Vätern, und man begrub ihn zu Samaria. Und Joas, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Im siebenunddreißigsten Jahre Joas\', des Königs von Juda, wurde Joas, der Sohn des Joahas, König über Israel zu Samaria und regierte sechzehn Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Und er tat, was böse war in den Augen Jehovas; er wich nicht von allen Sünden Jerobeams, des Sohnes Nebats, wodurch er Israel sündigen gemacht hatte: er wandelte darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Und das Übrige der Geschichte Joas\' und alles, was er getan, und seine Macht, wie er mit Amazja, dem König von Juda, gestritten hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Und Joas legte sich zu seinen Vätern, und Jerobeam setzte sich auf seinen Thron; und Joas wurde zu Samaria begraben bei den Königen von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Und Elisa erkrankte an seiner Krankheit, an welcher er starb. Und Joas, der König von Israel, kam zu ihm herab und weinte über seinem Angesicht und sprach: Mein Vater, mein Vater! Wagen Israels und seine Reiter!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Da sprach Elisa zu ihm: Hole Bogen und Pfeile. Und er holte ihm Bogen und Pfeile.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Und er sprach zu dem König von Israel: Lege deine Hand auf den Bogen. Da legte er seine Hand darauf: und Elisa tat seine Hände auf die Hände des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Und er sprach: Öffne das Fenster gegen Morgen. Und er öffnete es. Und Elisa sprach: Schieße! Und er schoß. Und er sprach: Ein Pfeil der Rettung von Jehova und ein Pfeil der Rettung wider die Syrer! Und so wirst du die Syrer zu Aphek schlagen bis zur Vernichtung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Und er sprach: Nimm die Pfeile. Und er nahm sie. Und er sprach zu dem König von Israel: Schlage auf die Erde! Und er schlug dreimal und hielt inne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Da ward der Mann Gottes zornig über ihn und sprach: Du hättest fünf-oder sechsmal schlagen sollen, dann würdest du die Syrer bis zur Vernichtung geschlagen haben; nun aber wirst du die Syrer dreimal schlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Und Elisa starb, und man begrub ihn. Und es kamen Streifscharen der Moabiter in das Land, als das Jahr anfing.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Und es geschah, als sie einen Mann begruben, siehe, da sahen sie die Streifschar, und sie warfen den Mann in das Grab Elisas; und als der Mann hineinkam und die Gebeine Elisas berührte, da wurde er lebendig und erhob sich auf seine Füße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Und Hasael, der König von Syrien, bedrückte Israel alle Tage des Joahas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Aber Jehova erwies ihnen Gnade und erbarmte sich ihrer und wandte sich ihnen zu, wegen seines Bundes mit Abraham, Isaak und Jakob; und er wollte sie nicht verderben und warf sie nicht von seinem Angesicht weg bis dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Und Hasael, der König von Syrien, starb. Und Ben-Hadad, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Da nahm Joas, der Sohn des Joahas, aus der Hand Ben-Hadads, des Sohnes Hasaels, die Städte wieder, welche dieser aus der Hand seines Vaters Joahas im Streit genommen hatte. Dreimal schlug ihn Joas und brachte die Städte Israels wieder zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Im zweiten Jahre Joas\', des Sohnes Joahas\', des Königs von Israel, wurde Amazja König, der Sohn Joas\', des Königs von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Fünfundzwanzig Jahre war er alt, als er König wurde, und er regierte neunundzwanzig Jahre zu Jerusalem; und der Name seiner Mutter war Joaddin, von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Und er tat, was recht war in den Augen Jehovas, nur nicht wie sein Vater David; er tat nach allem, was sein Vater Joas getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Doch die Höhen wichen nicht; das Volk opferte und räucherte noch auf den Höhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Und es geschah, als das Königtum in seiner Hand erstarkt war, da erschlug er seine Knechte, die den König, seinen Vater, erschlagen hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Aber die Söhne der Totschläger tötete er nicht, wie geschrieben steht im Buche des Gesetzes Moses, wo Jehova geboten und gesagt hat: Nicht sollen Väter getötet werden um der Kinder willen, und Kinder sollen nicht getötet werden um der Väter willen, sondern sie sollen ein jeder für seine Sünde getötet werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Er schlug die Edomiter im Salztal, zehntausend Mann, und nahm Sela ein im Streit, und er gab ihm den Namen Joktheel bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Damals sandte Amazja Boten an Joas, den Sohn Joahas\', des Sohnes Jehus, den König von Israel, und ließ ihm sagen: Komm, laß uns einander ins Angesicht sehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Da sandte Joas, der König von Israel, zu Amazja, dem König von Juda, und ließ ihm sagen: Der Dornstrauch auf dem Libanon sandte zu der Zeder auf dem Libanon und ließ ihr sagen: Gib meinem Sohne deine Tochter zum Weibe! Da lief das Getier des Feldes, das auf dem Libanon ist, vorüber und zertrat den Dornstrauch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Freilich hast du Edom geschlagen, und dein Herz erhebt sich; habe deinen Ruhm und bleibe in deinem Hause! Warum willst du dich denn mit dem Unglück einlassen, daß du fallest, du und Juda mit dir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Aber Amazja hörte nicht. Da zog Joas, der König von Israel, herauf; und sie sahen einander ins Angesicht, er und Amazja, der König von Juda, zu Beth-Semes, das zu Juda gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Und Juda wurde vor Israel geschlagen; und sie flohen, ein jeder nach seinem Zelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Und Joas, der König von Israel, nahm Amazja, den König von Juda, den Sohn Joas\', des Sohnes Ahasjas, zu Beth-Semes gefangen. Und er kam nach Jerusalem und machte einen Bruch in der Mauer Jerusalems, vom Tore Ephraim bis an das Ecktor, vierhundert Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Und er nahm alles Gold und Silber, und alle Geräte, welche sich im Hause Jehovas und in den Schätzen des Hauses des Königs vorfanden, und Geiseln und kehrte nach Samaria zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Und das Übrige der Geschichte Joas\', was er getan, und seine Macht, und wie er mit Amazja, dem König von Juda, gestritten hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Und Joas legte sich zu seinen Vätern, und er wurde begraben zu Samaria bei den Königen von Israel. Und Jerobeam, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Und Amazja, der Sohn Joas\', der König von Juda, lebte nach dem Tode Joas\', des Sohnes Joahas\', des Königs von Israel, fünfzehn Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Und das Übrige der Geschichte Amazjas, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Und sie machten zu Jerusalem eine Verschwörung wider ihn, und er floh nach Lachis; und sie sandten ihm nach bis Lachis und töteten ihn daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Und sie luden ihn auf Rosse, und er wurde begraben zu Jerusalem bei seinen Vätern in der Stadt Davids.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Und das ganze Volk von Juda nahm Asarja, der sechzehn Jahre alt war, und sie machten ihn zum König an seines Vaters Amazja Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Er baute Elath und brachte es an Juda zurück, nachdem der König sich zu seinen Vätern gelegt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Im fünfzehnten Jahre Amazjas, des Sohnes Joas\', des Königs von Juda, wurde Jerobeam, der Sohn Joas\', des Königs von Israel, König zu Samaria und regierte einundvierzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Und er tat, was böse war in den Augen Jehovas; er wich nicht von allen Sünden Jerobeams, des Sohnes Nebats, wodurch er Israel sündigen gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Er stellte die Grenze Israels wieder her, vom Eingange Hamaths bis an das Meer der Ebene, nach dem Worte Jehovas, des Gottes Israels, das er geredet hatte durch seinen Knecht Jona, den Sohn Amittais, den Propheten, der von Gath-Hepher war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Denn Jehova sah, daß das Elend Israels sehr bitter war, und daß dahin war der Gebundene und dahin der Freie, und daß kein Helfer da war für Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Und Jehova hatte nicht gesagt, daß er den Namen Israels austilgen würde unter dem Himmel hinweg; und so rettete er sie durch die Hand Jerobeams, des Sohnes Joas\'.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Und das Übrige der Geschichte Jerobeams, und alles, was er getan, und seine Macht, wie er gestritten, und wie er Damaskus und Hamath, die Juda gehört hatten, an Israel zurückgebracht hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Und Jerobeam legte sich zu seinen Vätern, zu den Königen von Israel. Und Sekarja, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Im siebenundzwanzigsten Jahre Jerobeams, des Königs von Israel, wurde Asarja König, der Sohn Amazjas, des Königs von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Sechzehn Jahre war er alt, als er König wurde, und regierte zweiundfünfzig Jahre zu Jerusalem; und der Name seiner Mutter war Jekolja, von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Und er tat, was recht war in den Augen Jehovas, nach allem, was sein Vater Amazja getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Doch die Höhen wichen nicht; das Volk opferte und räucherte noch auf den Höhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Und Jehova schlug den König, und er wurde aussätzig bis zum Tage seines Todes; und er wohnte in einem Krankenhause. Jotham aber, der Sohn des Königs, war über das Haus und richtete das Volk des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Und das Übrige der Geschichte Asarjas, und alles, was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Und Asarja legte sich zu seinen Vätern, und man begrub ihn bei seinen Vätern in der Stadt Davids. Und Jotham, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Im achtunddreißigsten Jahre Asarjas, des Königs von Juda, wurde Sekarja, der Sohn Jerobeams, König über Israel zu Samaria und regierte sechs Monate.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Und er tat, was böse war in den Augen Jehovas, so wie seine Väter getan hatten; er wich nicht von den Sünden Jerobeams, des Sohnes Nebats, wodurch er Israel sündigen gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Und Sallum, der Sohn Jabes\', machte eine Verschwörung wider ihn und erschlug ihn vor dem Volke und tötete ihn. Und er ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Und das Übrige der Geschichte Sekarjas, siehe, das ist geschrieben in dem Buche der Chronika der Könige von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Das ist das Wort Jehovas, welches er zu Jehu geredet hatte, indem er sprach: Dir sollen Söhne des vierten Gliedes auf dem Throne Israels sitzen. Und es geschah also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum, der Sohn Jabes\', wurde König im neununddreißigsten Jahre Ussijas, des Königs von Juda; und er regierte einen Monat lang zu Samaria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Da zog Menachem, der Sohn Gadis, von Tirza herauf und kam nach Samaria; und er erschlug Sallum, den Sohn Jabes\', zu Samaria und tötete ihn. Und er ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Und das Übrige der Geschichte Sallums, und seine Verschwörung, die er gemacht hat, siehe, das ist geschrieben in dem Buche der Chronika der Könige von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Damals schlug Menachem Tiphsach und alles, was darin war, und sein Gebiet, von Tirza aus: weil man ihm nicht aufgetan hatte, so schlug er es; alle seine Schwangeren schlitzte er auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Im neununddreißigsten Jahre Asarjas, des Königs von Juda, wurde Menachem, der Sohn Gadis, König über Israel und regierte zehn Jahre zu Samaria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Und er tat, was böse war in den Augen Jehovas; er wich nicht von den Sünden Jerobeams, des Sohnes Nebats, wodurch er Israel sündigen gemacht hatte, alle seine Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Und Pul, der König von Assyrien, kam wider das Land; und Menachem gab Pul tausend Talente Silber, damit seine Hand mit ihm wäre, um das Königtum in seiner Hand zu befestigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Und Menachem legte die Zahlung des Geldes auf Israel, auf alle vermögenden Leute, um es dem König von Assyrien zu geben: fünfzig Sekel Silber auf jeden Mann. Da kehrte der König von Assyrien um und blieb nicht daselbst im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Und das Übrige der Geschichte Menachems und alles, was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Und Menachem legte sich zu seinen Vätern. Und Pekachja, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Im fünfzigsten Jahre Asarjas, des Königs von Juda, wurde Pekachja, der Sohn Menachems, König über Israel zu Samaria und regierte zwei Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Und er tat, was böse war in den Augen Jehovas; er wich nicht von den Sünden Jerobeams, des Sohnes Nebats, wodurch er Israel sündigen gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Und Pekach, der Sohn Remaljas, sein Anführer, machte eine Verschwörung wider ihn und erschlug ihn zu Samaria in der Burg des Königshauses, mit Argob und mit Arjeh; und mit ihm waren fünfzig Mann von den Söhnen der Gileaditer. Und er tötete ihn und ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Und das Übrige der Geschichte Pekachjas und alles, was er getan hat, siehe, das ist geschrieben in dem Buche der Chronika der Könige von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Im zweiundfünfzigsten Jahre Asarjas, des Königs von Juda, wurde Pekach, der Sohn Remaljas, König über Israel zu Samaria und regierte zwanzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Und er tat, was böse war in den Augen Jehovas; er wich nicht von den Sünden Jerobeams, des Sohnes Nebats, wodurch er Israel sündigen gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'In den Tagen Pekachs, des Königs von Israel, kam Tiglath-Pileser, der König von Assyrien, und er nahm Ijjon ein und Abel-Beth-Maaka und Janoach und Kedes und Hazor und Gilead und Galiläa, das ganze Land Naphtali, und führte die Bewohner nach Assyrien hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Und Hosea, der Sohn Elas, machte eine Verschwörung wider Pekach, den Sohn Remaljas, und erschlug ihn und tötete ihn. Und er ward König an seiner Statt, im zwanzigsten Jahre Jothams, des Sohnes Ussijas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Und das Übrige der Geschichte Pekachs und alles, was er getan hat, siehe, das ist geschrieben in dem Buche der Chronika der Könige von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Im zweiten Jahre Pekachs, des Sohnes Remaljas, des Königs von Israel, wurde Jotham König, der Sohn Ussijas, des Königs von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Fünfundzwanzig Jahre war er alt, als er König wurde, und er regierte sechzehn Jahre zu Jerusalem; und der Name seiner Mutter war Jeruscha, die Tochter Zadoks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Und er tat, was recht war in den Augen Jehovas; er tat nach allem, was sein Vater Ussija getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Doch die Höhen wichen nicht; das Volk opferte und räucherte noch auf den Höhen. Er baute das obere Tor des Hauses Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Und das Übrige der Geschichte Jothams und alles, was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'In jenen Tagen begann Jehova, Rezin, den König von Syrien, und Pekach, den Sohn Remaljas, wider Juda zu senden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Und Jotham legte sich zu seinen Vätern, und er wurde begraben bei seinen Vätern in der Stadt seines Vaters David. (H15:39) Und Ahas, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Im siebzehnten Jahre Pekachs, des Sohnes Remaljas, wurde Ahas König, der Sohn Jothams, des Königs von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Zwanzig Jahre war Ahas alt, als er König wurde, und er regierte sechzehn Jahre zu Jerusalem. Und er tat nicht, was recht war in den Augen Jehovas, seines Gottes, wie sein Vater David;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'sondern er wandelte auf dem Wege der Könige von Israel, und er ließ sogar seinen Sohn durchs Feuer gehen, nach den Greueln der Nationen, die Jehova vor den Kindern Israel ausgetrieben hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'und er opferte und räucherte auf den Höhen und auf den Hügeln und unter jedem grünen Baume.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Damals zogen Rezin, der König von Syrien, und Pekach, der Sohn Remaljas, der König von Israel, nach Jerusalem hinauf zum Streit; und sie belagerten Ahas, aber sie vermochten nicht wider ihn zu streiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Zu selbiger Zeit brachte Rezin, der König von Syrien, Elath wieder an Syrien und trieb die Juden aus Elath hinaus; und die Syrer kamen nach Elath, und sie haben dort gewohnt bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Da sandte Ahas Boten an Tiglath-Pileser, den König von Assyrien, und ließ ihm sagen: Ich bin dein Knecht und dein Sohn; komm herauf und rette mich aus der Hand des Königs von Syrien und aus der Hand des Königs von Israel, die sich wider mich erhoben haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Und Ahas nahm das Silber und das Gold, das sich in dem Hause Jehovas und in den Schätzen des Königshauses vorfand, und sandte es als Geschenk an den König von Assyrien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Und der König von Assyrien hörte auf ihn; und der König von Assyrien zog hinauf wider Damaskus und nahm es ein und führte seine Einwohner weg nach Kir; und Rezin tötete er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Und der König Ahas zog Tiglath-Pileser, dem König von Assyrien, entgegen, nach Damaskus. Und als er den Altar sah, der zu Damaskus war, da sandte der König Ahas dem Priester Urija das Gleichnis des Altars und dessen Abbild nach seiner ganzen Bauart.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Und der Priester Urija baute den Altar; nach allem, was der König Ahas von Damaskus gesandt hatte, also machte ihn der Priester Urija, bis der König Ahas von Damaskus kam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Und als der König von Damaskus kam, und der König den Altar sah, da trat der König an den Altar und opferte darauf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'und er räucherte sein Brandopfer und sein Speisopfer, und goß sein Trankopfer aus, und sprengte das Blut seiner Friedensopfer an den Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Den ehernen Altar aber, der vor Jehova stand, den rückte er von der Vorderseite des Hauses weg, von der Stelle, zwischen seinem Altar und dem Hause Jehovas; und er setzte ihn an die Seite seines Altars gegen Norden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Und der König Ahas gebot dem Priester Urija und sprach: Räuchere auf dem großen Altar das Morgenbrandopfer und das Abendspeisopfer, und das Brandopfer des Königs samt seinem Speisopfer, und das Brandopfer des ganzen Volkes des Landes samt ihren Speisopfern und ihren Trankopfern; und alles Blut der Brandopfer und alles Blut der Schlachtopfer sollst du daran sprengen; und der eherne Altar soll für mich sein zum Erforschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Und der Priester Urija tat nach allem, was der König Ahas geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Und der König Ahas brach die Felder an den Gestellen ab und tat die Becken, die darauf waren, hinweg; und er ließ das Meer von den ehernen Rindern, die darunter waren, herabnehmen und auf eine Unterlage von Steinen setzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Und den bedeckten Sabbathgang, den man am Hause gebaut hatte, und den äußeren Eingang des Königs veränderte er am Hause Jehovas wegen des Königs von Assyrien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Und das Übrige der Geschichte Ahas\', was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Und Ahas legte sich zu seinen Vätern, und er wurde begraben bei seinen Vätern in der Stadt Davids. Und Hiskia, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Im zwölften Jahre Ahas\', des Königs von Juda, wurde Hosea, der Sohn Elas, König zu Samaria über Israel und regierte neun Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Und er tat, was böse war in den Augen Jehovas, doch nicht wie die Könige von Israel, die vor ihm gewesen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Wider ihn zog Salmaneser, der König von Assyrien, herauf; und Hosea wurde sein Knecht und entrichtete ihm Geschenke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Aber der König von Assyrien entdeckte eine Verschwörung des Hosea; denn er hatte Boten an So, den König von Ägypten, gesandt, und hatte dem König von Assyrien kein Geschenk dargebracht, wie von Jahr zu Jahr. Da verhaftete ihn der König von Assyrien und legte ihn gebunden ins Gefängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Und der König von Assyrien zog herauf in das ganze Land, und zog herauf nach Samaria und belagerte es drei Jahre lang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Im neunten Jahre Hoseas nahm der König von Assyrien Samaria ein und führte Israel nach Assyrien hinweg; und er ließ sie wohnen in Halach und am Habor, dem Strome Gosans, und in den Städten Mediens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Und dies geschah, weil die Kinder Israel gesündigt hatten wider Jehova, ihren Gott, der sie aus dem Lande Ägypten heraufgeführt hatte, unter der Hand des Pharao, des Königs von Ägypten, hinweg,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'und weil sie andere Götter fürchteten und in den Satzungen der Nationen wandelten, die Jehova vor den Kindern Israel ausgetrieben, und der Könige von Israel, welche dieselben gemacht hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Und die Kinder Israel trieben wider Jehova, ihren Gott, heimlich Dinge, die nicht recht waren; und sie bauten sich Höhen in allen ihren Städten, von den Türmen der Wächter bis zu den festen Städten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'und sie errichteten sich Bildsäulen und Ascherim auf jedem hohen Hügel und unter jedem grünen Baume,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'und sie räucherten daselbst auf allen Höhen, wie die Nationen, die Jehova vor ihnen weggeführt hatte; und sie taten böse Dinge, um Jehova zu reizen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'und sie dienten den Götzen, von denen Jehova ihnen gesagt hatte: Solches sollt ihr nicht tun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Und Jehova zeugte gegen Israel und gegen Juda durch alle Propheten, alle Seher, indem er sprach: Kehret um von euren bösen Wegen und beobachtet meine Gebote, meine Satzungen, nach dem ganzen Gesetz, das ich euren Vätern geboten, und das ich euch gesandt habe durch meine Knechte, die Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Aber sie hörten nicht und verhärteten ihren Nacken, gleich dem Nacken ihrer Väter, welche Jehova, ihrem Gott, nicht geglaubt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Und sie verachteten seine Satzungen und seinen Bund, den er mit ihren Vätern gemacht, und seine Zeugnisse, die er ihnen bezeugt hatte; und sie wandelten der Eitelkeit nach und handelten eitel, und den Nationen nach, die rings um sie her waren, von denen Jehova ihnen geboten hatte, nicht wie sie zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Und sie verließen alle Gebote Jehovas, ihres Gottes, und machten sich gegossene Bilder, zwei Kälber, und machten eine Aschera, und bückten sich vor dem ganzen Heere des Himmels und dienten dem Baal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Und sie ließen ihre Söhne und ihre Töchter durchs Feuer gehen, und trieben Wahrsagerei und Zauberei, und verkauften sich, zu tun, was böse war in den Augen Jehovas, um ihn zu reizen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Da erzürnte Jehova sehr über Israel und tat es vor seinem Angesicht hinweg; es blieb nichts übrig, nur der Stamm Juda allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Auch Juda beobachtete nicht die Gebote Jehovas, seines Gottes; und sie wandelten in den Satzungen Israels, die es gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Da verwarf Jehova den ganzen Samen Israels und demütigte sie, und er gab sie in die Hand von Plünderern, bis er sie von seinem Angesicht weggeworfen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Denn Israel hatte sich von dem Hause Davids losgerissen, und sie hatten Jerobeam, den Sohn Nebats, zum König gemacht; und Jerobeam lenkte Israel von der Nachfolge Jehovas ab und verleitete sie zu einer großen Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Und die Kinder Israel wandelten in allen Sünden Jerobeams, die er getan hatte; sie wichen nicht davon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'bis Jehova Israel vor seinem Angesicht hinwegtat, so wie er durch alle seine Knechte, die Propheten, geredet hatte; und Israel wurde aus seinem Lande nach Assyrien weggeführt bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Und der König von Assyrien brachte Leute aus Babel und aus Kutha und aus Awa und aus Hamath und aus Sepharwaim, und ließ sie an Stelle der Kinder Israel in den Städten Samarias wohnen; und sie nahmen Samaria in Besitz und wohnten in seinen Städten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Und es geschah, im Anfang ihrer Niederlassung daselbst fürchteten sie Jehova nicht; da sandte Jehova Löwen unter sie, welche unter ihnen würgten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Und man sprach zu dem König von Assyrien und sagte: Die Nationen, die du weggeführt und in den Städten Samarias hast wohnen lassen, kennen nicht die Weise des Gottes des Landes; und er hat Löwen unter sie gesandt, und siehe, sie töten sie, weil sie die Weise des Gottes des Landes nicht kennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Da gebot der König von Assyrien und sprach: Laßt einen der Priester, die ihr von dannen weggeführt habt, dahin gehen, daß sie hingehen und daselbst wohnen; und er lehre sie die Weise des Gottes des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Und es kam einer der Priester, die man aus Samaria weggeführt hatte, und wohnte zu Bethel; und er lehrte sie, wie sie Jehova fürchten sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Und sie machten sich, eine jede Nation, ihre Götter, und stellten sie in die Höhenhäuser, welche die Samariter gemacht hatten, eine jede Nation in ihren Städten, in welchen sie wohnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Und die Leute von Babel machten Sukkoth-Benoth; und die Leute von Kuth machten Nergal; und die Leute von Hamath machten Aschima;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'und die Awiter machten Nibchas und Tartak; und die Sepharwiter verbrannten dem Adrammelek und dem Anammelek, den Göttern von Sepharwaim, ihre Söhne im Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Und sie fürchteten Jehova, und sie machten sich aus ihrer Gesamtheit Priester der Höhen, welche für sie in den Höhenhäusern opferten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Sie fürchteten Jehova, und sie dienten ihren Göttern nach der Weise der Nationen, aus welchen man sie weggeführt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Bis auf diesen Tag tun sie nach den früheren Weisen: sie fürchten Jehova nicht, und sie tun nicht nach ihren Satzungen und nach ihren Rechten, und auch nicht nach dem Gesetz und nach dem Gebot, welches Jehova den Söhnen Jakobs geboten hatte, dem er den Namen Israel gab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Und doch hatte Jehova einen Bund mit ihnen gemacht und ihnen geboten und gesagt: Ihr sollt nicht andere Götter fürchten, und sollt euch nicht vor ihnen niederbeugen und ihnen nicht dienen und ihnen nicht opfern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'sondern Jehova, der euch mit großer Kraft und mit ausgestrecktem Arm aus dem Lande Ägypten heraufgeführt hat, den sollt ihr fürchten, und den sollt ihr anbeten und ihm opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Und die Satzungen und die Rechte und das Gesetz und das Gebot, die er für euch geschrieben hat, sollt ihr beobachten, zu tun alle Tage, und ihr sollt nicht andere Götter fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Und des Bundes, den ich mit euch gemacht habe, sollt ihr nicht vergessen, und sollt nicht andere Götter fürchten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'sondern Jehova, euren Gott, sollt ihr fürchten, und er wird euch erretten aus der Hand aller eurer Feinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Aber sie hörten nicht, sondern taten nach ihrer früheren Weise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'So fürchteten diese Nationen Jehova, und dienten zugleich ihren Götzenbildern. Auch ihre Kinder und ihre Kindeskinder tun bis auf diesen Tag, so wie ihre Väter getan haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Und es geschah im dritten Jahre Hoseas, des Sohnes Elas, des Königs von Israel, da wurde Hiskia König, der Sohn Ahas\', des Königs von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Fünfundzwanzig Jahre war er alt, als er König wurde, und er regierte neunundzwanzig Jahre zu Jerusalem; und der Name seiner Mutter war Abi, die Tochter Sekarjas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Und er tat, was recht war in den Augen Jehovas, nach allem, was sein Vater David getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Er tat die Höhen hinweg und zerschlug die Bildsäulen, und rottete die Aschera aus, und zertrümmerte die eherne Schlange, welche Mose gemacht hatte; denn bis zu jenen Tagen hatten die Kinder Israel ihr geräuchert, und man nannte sie Nechustan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Er vertraute auf Jehova, den Gott Israels; und nach ihm ist seinesgleichen nicht gewesen unter allen Königen von Juda, noch unter denen, die vor ihm waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Und er hing Jehova an, er wich nicht von ihm ab; und er beobachtete seine Gebote, die Jehova dem Mose geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Und Jehova war mit ihm; überall, wohin er zog, gelang es ihm. Und er empörte sich gegen den König von Assyrien und diente ihm nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Er schlug die Philister bis Gasa und verheerte dessen Gebiet, vom Turme der Wächter an bis zu der festen Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Und es geschah im vierten Jahre des Königs Hiskia, das war das siebte Jahr Hoseas, des Sohnes Elas, des Königs von Israel, da zog Salmaneser, der König von Assyrien, wider Samaria herauf und belagerte es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Und er nahm es ein am Ende von drei Jahren; im sechsten Jahre Hiskias, das war das neunte Jahr Hoseas, des Königs von Israel, wurde Samaria eingenommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Und der König von Assyrien führte Israel nach Assyrien hinweg; und er versetzte sie nach Halach und an den Habor, den Strom Gosans, und in die Städte Mediens:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'darum daß sie auf die Stimme Jehovas, ihres Gottes, nicht gehört, und seinen Bund übertreten hatten alles, was Mose, der Knecht Jehovas, geboten hat und weil sie nicht gehört und es nicht getan hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Und im vierzehnten Jahre des Königs Hiskia zog Sanherib, der König von Assyrien, herauf wider alle festen Städte Judas und nahm sie ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Da sandte Hiskia, der König von Juda, an den König von Assyrien nach Lachis und ließ ihm sagen: Ich habe gefehlt, kehre um von mir; was du mir auferlegen wirst, will ich tragen. Und der König von Assyrien legte Hiskia, dem König von Juda, dreihundert Talente Silber und dreißig Talente Gold auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Und Hiskia gab alles Silber, das sich in dem Hause Jehovas und in den Schätzen des Königshauses vorfand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Zu selbiger Zeit brach Hiskia von den Türflügeln des Tempels Jehovas und den Pfosten, die Hiskia, der König von Juda, überzogen hatte, das Gold ab und gab es dem König von Assyrien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Aber der König von Assyrien sandte von Lachis aus den Tartan und den Rabsaris und den Rabsake mit einem großen Heere wider den König Hiskia nach Jerusalem. Und sie zogen herauf und kamen nach Jerusalem: sie zogen herauf und kamen und hielten an der Wasserleitung des oberen Teiches, welcher an der Straße des Walkerfeldes liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Und sie riefen dem König. Da gingen zu ihnen hinaus Eljakim, der Sohn Hilkijas, der über das Haus war, und Schebna, der Schreiber, und Joach, der Sohn Asaphs, der Geschichtsschreiber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Und der Rabsake sprach zu ihnen: Saget doch zu Hiskia: So spricht der große König, der König von Assyrien: Was ist das für ein Vertrauen, womit du vertraust?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Du sagst doch nur ein Wort der Lippen ist es: Da ist Rat und Macht zum Kriege. Nun, auf wen vertraust du, daß du dich wider mich empört hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Nun, siehe, du vertraust auf jenen geknickten Rohrstab, auf Ägypten, der, wenn jemand sich auf ihn stützt, ihm in die Hand fährt und sie durchbohrt. So ist der Pharao, der König von Ägypten, allen, die auf ihn vertrauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Und wenn ihr zu mir sprechet: Auf Jehova, unseren Gott, vertrauen wir! ist er es nicht, dessen Höhen und dessen Altäre Hiskia hinweggetan, da er zu Juda und zu Jerusalem gesagt hat: Vor diesem Altar sollt ihr anbeten in Jerusalem? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Und nun, laß dich doch ein mit meinem Herrn, dem König von Assyrien: Ich will dir zweitausend Rosse geben, wenn du dir Reiter darauf setzen kannst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Und wie wolltest du einen einzigen Befehlshaber von den geringsten Knechten meines Herrn zurücktreiben? Aber du vertraust auf Ägypten der Wagen und Reiter wegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Nun, bin ich etwa ohne Jehova wider diesen Ort heraufgezogen, um ihn zu verheeren? Jehova hat zu mir gesagt: Ziehe hinauf wider dieses Land und verheere es!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Und Eljakim, der Sohn Hilkijas, und Schebna und Joach sprachen zu dem Rabsake: Rede doch zu deinen Knechten auf aramäisch, denn wir verstehen es; und rede nicht auf jüdisch mit uns vor den Ohren des Volkes, das auf der Mauer ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Und der Rabsake sprach zu ihnen: Hat mein Herr mich zu deinem Herrn und zu dir gesandt, um diese Worte zu reden? Nicht zu den Männern, die auf der Mauer sitzen, um mit euch ihren Kot zu essen und ihren Harn zu trinken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Und der Rabsake stand und rief mit lauter Stimme auf jüdisch und redete und sprach: Höret das Wort des großen Königs, des Königs von Assyrien!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'So spricht der König: Daß Hiskia euch nicht täusche; denn er wird euch nicht von seiner Hand zu erretten vermögen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Und das Hiskia euch nicht auf Jehova vertröste, indem er spricht: Jehova wird uns gewißlich erretten, und diese Stadt wird nicht in die Hand des Königs von Assyrien gegeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Höret nicht auf Hiskia! Denn also spricht der König von Assyrien: Machet Frieden mit mir und kommet zu mir heraus, so sollt ihr ein jeder von seinem Weinstock und ein jeder von seinem Feigenbaum essen, und ein jeder das Wasser seines Brunnens trinken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'bis ich komme und euch in ein Land hole wie euer Land, ein Land von Korn und Most, ein Land von Brot und Weinbergen, ein Land von Olivenbäumen und Honig, daß ihr lebet und nicht sterbet. Aber höret nicht auf Hiskia! Denn er verführt euch, indem er spricht: Jehova wird uns erretten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Haben denn irgend die Götter der Nationen ein jeder sein Land von der Hand des Königs von Assyrien errettet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Wo sind die Götter von Hamath und Arpad? Wo die Götter von Sepharwaim, von Hena und Iwa? Haben sie Samaria von meiner Hand errettet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Welche sind es unter allen Göttern der Länder, die ihr Land von meiner Hand errettet haben, daß Jehova Jerusalem von meiner Hand erretten sollte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Und das Volk schwieg still und antwortete ihm kein Wort; denn es war das Gebot des Königs, der gesagt hatte: Ihr sollt nicht antworten! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Und Eljakim, der Sohn Hilkijas, der über das Haus war, und Schebna, der Schreiber, und Joach, der Sohn Asaphs, der Geschichtsschreiber, kamen zu Hiskia mit zerrissenen Kleidern und berichteten ihm die Worte des Rabsake.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Und es geschah, als der König Hiskia es hörte, da zerriß er seine Kleider und hüllte sich in Sacktuch und ging in das Haus Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Und er sandte Eljakim, der über das Haus war, und Schebna, den Schreiber, und die Ältesten der Priester, in Sacktuch gehüllt, zu dem Propheten Jesaja, dem Sohne Amoz\'.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Und sie sprachen zu ihm: So spricht Hiskia: Dieser Tag ist ein Tag der Bedrängnis und der Züchtigung und der Schmähung; denn die Kinder sind bis an die Geburt gekommen, aber da ist keine Kraft zum Gebären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Vielleicht wird Jehova, dein Gott, alle Worte des Rabsake hören, welchen sein Herr, der König von Assyrien, gesandt hat, um den lebendigen Gott zu höhnen, und wird die Worte bestrafen, die Jehova, dein Gott, gehört hat. Erhebe denn ein Gebet für den Überrest, der sich noch vorfindet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Und die Knechte des Königs Hiskia kamen zu Jesaja.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Und Jesaja sprach zu ihnen: Also sollt ihr zu eurem Herrn sagen: So spricht Jehova: Fürchte dich nicht vor den Worten, die du gehört hast, womit die Diener des Königs von Assyrien mich gelästert haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Siehe, ich will ihm einen Geist eingeben, daß er ein Gerücht hören und in sein Land zurückkehren wird; und ich will ihn durchs Schwert fällen in seinem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Und der Rabsake kehrte zurück und fand den König von Assyrien streitend wider Libna; denn er hatte gehört, daß er von Lachis aufgebrochen wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Und er hörte von Tirhaka, dem König von Äthiopien, sagen: Siehe, er ist ausgezogen, um wider dich zu streiten. Da sandte er wiederum Boten zu Hiskia und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'So sollt ihr zu Hiskia, dem König von Juda, sprechen und sagen: Daß dich nicht täusche dein Gott, auf den du vertraust, indem du sprichst: Jerusalem wird nicht in die Hand des Königs von Assyrien gegeben werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Siehe, du hast gehört, was die Könige von Assyrien allen Ländern getan haben, indem sie sie vertilgten; und du solltest errettet werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Haben die Götter der Nationen, welche meine Väter vernichtet haben, sie errettet: Gosan und Haran und Rezeph, und die Kinder Edens, die in Telassar waren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Wo ist der König von Hamath und der König von Arpad und der König der Stadt Sepharwaim, von Hena und Iwa?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Und Hiskia nahm den Brief aus der Hand der Boten und las ihn; und er ging in das Haus Jehovas hinauf, und Hiskia breitete ihn vor Jehova aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Und Hiskia betete vor Jehova und sprach: Jehova, Gott Israels, der du zwischen den Cherubim thronst, du allein bist es, der der Gott ist von allen Königreichen der Erde; du hast den Himmel und die Erde gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Jehova, neige dein Ohr und höre! Jehova, tue deine Augen auf und sieh! Ja, höre die Worte Sanheribs, die er gesandt hat, um den lebendigen Gott zu höhnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Wahrlich, Jehova, die Könige von Assyrien haben die Nationen und ihr Land verwüstet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'und sie haben ihre Götter ins Feuer geworfen; denn sie waren nicht Götter, sondern ein Werk von Menschenhänden, Holz und Stein, und sie haben sie zerstört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Und nun, Jehova, unser Gott, rette uns doch von seiner Hand, damit alle Königreiche der Erde wissen, daß du, Jehova, allein Gott bist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Da sandte Jesaja, der Sohn Amoz\', zu Hiskia und ließ ihm sagen: So spricht Jehova, der Gott Israels: Was du wegen Sanheribs, des Königs von Assyrien, zu mir gebetet hast, habe ich gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Dies ist das Wort, welches Jehova über ihn geredet hat: Es verachtet dich, es spottet deiner die Jungfrau, die Tochter Zion; die Tochter Jerusalem schüttelt das Haupt dir nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Wen hast du gehöhnt und gelästert, und gegen wen die Stimme erhoben? Gegen den Heiligen Israels hast du deine Augen emporgerichtet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Durch deine Boten hast du den Herrn gehöhnt und hast gesprochen: Mit meiner Wagen Menge habe ich erstiegen die Höhe der Berge, das äußerste Ende des Libanon; und ich will umhauen den Hochwuchs seiner Zedern, die Auswahl seiner Zypressen, und ich will kommen in seine äußerste Wohnung, in seinen Gartenwald.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Ich habe gegraben und fremde Wasser getrunken; und mit der Sohle meiner Füße werde ich austrocknen alle Ströme Mazors.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Hast du nicht gehört, daß ich von ferne her es gewirkt und von den Tagen der Vorzeit her es gebildet habe? Nun habe ich es kommen lassen, daß du feste Städte verwüstest zu öden Steinhaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Und ihre Bewohner waren machtlos, sie wurden bestürzt und beschämt; sie waren wie Kraut des Feldes und grünes Gras, wie Gras der Dächer, und Korn, das verbrannt ist, ehe es aufschießt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Und ich kenne dein Sitzen, und dein Aus-und dein Eingehen, und dein Toben wider mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Wegen deines Tobens wider mich, und weil dein Übermut in meine Ohren heraufgekommen ist, werde ich meinen Ring in deine Nase legen und mein Gebiß in deine Lippen und werde dich zurückführen auf dem Wege, auf welchem du gekommen bist! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Und dies soll dir das Zeichen sein: Man wird in diesem Jahre den Nachwuchs der Ernte essen, und im zweiten Jahre, was ausgesproßt ist; im dritten Jahre aber säet und erntet, und pflanzet Weinberge und esset ihre Frucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Und das Entronnene vom Hause Juda, das übriggeblieben ist, wird wieder wurzeln nach unten und Frucht tragen nach oben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Denn von Jerusalem wird ein Überrest ausgehen, und ein Entronnenes vom Berge Zion. Der Eifer Jehovas wird solches tun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Darum, so spricht Jehova von dem König von Assyrien: Er soll nicht in diese Stadt kommen, und er soll keinen Pfeil darein schießen und keinen Schild ihr zukehren und keinen Wall gegen sie aufschütten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Auf dem Wege, auf welchem er gekommen ist, soll er zurückkehren, und soll in diese Stadt nicht kommen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Und ich will diese Stadt beschirmen, um sie zu retten, um meinet-und um Davids, meines Knechtes, willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Und es geschah in selbiger Nacht, da ging ein Engel Jehovas aus und schlug in dem Lager der Assyrer hundertfünfundachtzigtausend Mann. Und als man des Morgens früh aufstand, siehe, da waren sie allesamt Leichname.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Und Sanherib, der König von Assyrien, brach auf, und er zog fort und kehrte zurück und blieb in Ninive.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Und es geschah, als er sich im Hause Nisroks, seines Gottes, niederbeugte, da erschlugen ihn Adrammelek und Scharezer, seine Söhne, mit dem Schwerte; und sie entrannen in das Land Ararat. Und Esar-Haddon, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'In jenen Tagen wurde Hiskia krank zum Sterben. Und Jesaja, der Sohn Amoz\', der Prophet, kam zu ihm, und sprach zu ihm: So spricht Jehova: Bestelle dein Haus, denn du wirst sterben und nicht genesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Da wandte er sein Angesicht gegen die Wand und betete zu Jehova und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Ach, Jehova! Gedenke doch, daß ich in Wahrheit und mit ungeteiltem Herzen vor deinem Angesicht gewandelt, und getan habe, was gut ist in deinen Augen! Und Hiskia weinte sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Und es geschah, Jesaja war noch nicht zur mittleren Stadt hinausgegangen, da geschah das Wort Jehovas zu ihm also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Kehre um und sprich zu Hiskia, dem Fürsten meines Volkes: So spricht Jehova, der Gott deines Vaters David: Ich habe dein Gebet gehört, ich habe deine Tränen gesehen; siehe, ich will dich heilen; am dritten Tage wirst du in das Haus Jehovas hinaufgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Und ich will zu deinen Tagen fünfzehn Jahre hinzufügen; und von der Hand des Königs von Assyrien will ich dich und diese Stadt erretten; und ich will diese Stadt beschirmen um meinet-und um Davids, meines Knechtes, willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Und Jesaja sprach: Holet einen Feigenkuchen. Und sie holten ihn und legten ihn auf das Geschwür; und er genas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Und Hiskia sprach zu Jesaja: Welches ist das Zeichen, daß Jehova mich heilen wird, und daß ich am dritten Tage in das Haus Jehovas hinaufgehen werde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Und Jesaja sprach: Dies wird dir das Zeichen sein von seiten Jehovas, daß Jehova das Wort tun wird, welches er geredet hat: Soll der Schatten zehn Grade vorwärts gehen, oder soll er zehn Grade zurückgehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Und Hiskia sprach: Es ist dem Schatten ein Leichtes, zehn Grade zu fallen; nein, sondern der Schatten soll zehn Grade rückwärts gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Da rief der Prophet Jesaja zu Jehova; und er ließ den Schatten an den Graden, welche er am Sonnenzeiger Ahas\' niederwärts gegangen war, um zehn Grade rückwärts gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Zu jener Zeit sandte Berodak-Baladan, der Sohn Baladans, der König von Babel, Brief und Geschenk an Hiskia; denn er hatte gehört, daß Hiskia krank gewesen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Und Hiskia hörte sie an, und er zeigte ihnen sein ganzes Schatzhaus: das Silber und das Gold, und die Gewürze und das köstliche Öl; und sein ganzes Zeughaus, und alles, was sich in seinen Schätzen vorfand; es war nichts in seinem Hause und in seiner ganzen Herrschaft, was Hiskia ihnen nicht gezeigt hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Da kam Jesaja, der Prophet, zum König Hiskia und sprach zu ihm: Was haben diese Männer gesagt? Und woher sind sie zu dir gekommen? Und Hiskia sprach: Aus fernem Lande sind sie gekommen, von Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Und er sprach: Was haben sie in deinem Hause gesehen? Und Hiskia sprach: Sie haben alles gesehen, was in meinem Hause ist; es gibt nichts in meinen Schätzen, was ich ihnen nicht gezeigt hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Da sprach Jesaja zu Hiskia: Höre das Wort Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Siehe, es kommen Tage, da alles, was in deinem Hause ist und was deine Väter aufgehäuft haben bis auf diesen Tag, nach Babel weggebracht werden wird; es wird nichts übrigbleiben, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Und von deinen Söhnen, die aus dir hervorkommen werden, die du zeugen wirst, wird man nehmen; und sie werden Kämmerer sein im Palaste des Königs von Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Und Hiskia sprach zu Jesaja: Das Wort Jehovas ist gut, das du geredet hast; und er sprach: Nicht wahr, es wird Friede und Bestand sein in meinen Tagen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Und das Übrige der Geschichte Hiskias, und alle seine Macht, und wie er den Teich und die Wasserleitung gemacht und das Wasser in die Stadt geleitet hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Und Hiskia legte sich zu seinen Vätern. Und Manasse, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Zwölf Jahre war Manasse alt, als er König wurde, und er regierte fünfundfünfzig Jahre zu Jerusalem; und der Name seiner Mutter war Hephzi-Bah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Und er tat, was böse war in den Augen Jehovas, nach den Greueln der Nationen, die Jehova vor den Kindern Israel ausgetrieben hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Und er baute die Höhen wieder auf, die sein Vater Hiskia zerstört hatte, und errichtete dem Baal Altäre, und machte eine Aschera, so wie Ahab, der König von Israel, gemacht hatte, und er beugte sich nieder vor dem ganzen Heere des Himmels und diente ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Und er baute Altäre in dem Hause Jehovas, von welchem Jehova gesagt hatte: In Jerusalem will ich meinen Namen setzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Und er baute dem ganzen Heere des Himmels Altäre in den beiden Höfen des Hauses Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Und er ließ seinen Sohn durchs Feuer gehen, und er trieb Zauberei und Wahrsagerei, und bestellte Totenbeschwörer und Wahrsager: er tat viel Böses in den Augen Jehovas, um ihn zu reizen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Und er stellte das geschnitzte Bild der Aschera, das er gemacht, in das Haus, von welchem Jehova zu David und zu seinem Sohne Salomo gesagt hatte: In dieses Haus und in Jerusalem, das ich aus allen Stämmen Israels erwählt habe, will ich meinen Namen setzen ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Und ich will den Fuß Israels nicht mehr aus dem Lande wandern lassen, welches ich ihren Vätern gegeben habe, wenn sie nur darauf achten, nach allem zu tun, was ich ihnen geboten habe, und nach dem ganzen Gesetz, das mein Knecht Mose ihnen geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Aber sie hörten nicht; und Manasse verleitete sie, des Bösen mehr zu tun als die Nationen, welche Jehova vor den Kindern Israel vertilgt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Da redete Jehova durch seine Knechte, die Propheten, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Weil Manasse, der König von Juda, diese Greuel verübt und übel getan hat, mehr als alles, was die Amoriter getan haben, die vor ihm gewesen sind, und auch Juda durch seine Götzen sündigen gemacht hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'darum, so spricht Jehova, der Gott Israels, siehe, will ich Unglück über Jerusalem und Juda bringen, daß jedem, der es hört, seine beiden Ohren gellen sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Und ich werde über Jerusalem die Meßschnur Samarias ziehen und das Senkblei des Hauses Ahabs, und ich werde Jerusalem auswischen, wie man eine Schüssel auswischt: hat man sie ausgewischt, so kehrt man sie um auf ihre Oberseite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Und ich werde den Überrest meines Erbteils verstoßen und sie in die Hand ihrer Feinde geben, und sie werden allen ihren Feinden zum Raub und zur Plünderung werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'weil sie getan, was böse ist in meinen Augen, und mich stets gereizt haben von dem Tage an, da ihre Väter aus Ägypten gezogen sind, bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Und Manasse vergoß auch sehr viel unschuldiges Blut, bis er Jerusalem damit erfüllte von einem Ende bis zum anderen; außer seiner Sünde, wodurch er Juda sündigen machte, indem es tat, was böse war in den Augen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Und das Übrige der Geschichte Manasses und alles, was er getan und seine Sünde, die er begangen hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Und Manasse legte sich zu seinen Vätern, und er wurde begraben im Garten seines Hauses, im Garten Ussas. Und Amon, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Zweiundzwanzig Jahre war Amon alt, als er König wurde, und er regierte zwei Jahre zu Jerusalem; und der Name seiner Mutter war Meschullemeth, die Tochter Haruz\', von Jotba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Und er tat, was böse war in den Augen Jehovas, wie sein Vater Manasse getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Und er wandelte auf allen Wegen, die sein Vater gewandelt war, und diente den Götzen, welchen sein Vater gedient hatte, und beugte sich vor ihnen nieder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'und er verließ Jehova, den Gott seiner Väter, und wandelte nicht auf dem Wege Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Und die Knechte Amons machten eine Verschwörung wider ihn und töteten den König in seinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Da erschlug das Volk des Landes alle, die sich wider den König Amon verschworen hatten; und das Volk des Landes machte Josia, seinen Sohn, zum König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Und das Übrige der Geschichte Amons, was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Und man begrub ihn in seinem Begräbnis, im Garten Ussas. Und Josia, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Acht Jahre war Josia alt, als er König wurde, und er regierte einunddreißig Jahre zu Jerusalem; und der Name seiner Mutter war Jedida, die Tochter Adajas, von Bozkath.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Und er tat, was recht war in den Augen Jehovas; und er wandelte auf allen Wegen seines Vaters David und wich nicht zur Rechten noch zur Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Und es geschah im achtzehnten Jahre des Königs Josia, da sandte der König Schaphan, den Sohn Azaljas, des Sohnes Meschullams, den Schreiber, in das Haus Jehovas und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Gehe hinauf zu Hilkija, dem Hohenpriester, daß er das Geld zusammennehme, welches in das Haus Jehovas gebracht worden ist, welches die Hüter der Schwelle von dem Volke eingesammelt haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'damit man es in die Hand derer gebe, welche das Werk betreiben, die am Hause Jehovas bestellt sind; und sie sollen es denen geben, die das Werk tun im Hause Jehovas, um das Baufällige des Hauses auszubessern:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'den Zimmerleuten und den Bauleuten und den Maurern, und um Holz zu kaufen und behauene Steine, um das Haus auszubessern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Doch soll das Geld, das in ihre Hand gegeben wird, nicht mit ihnen verrechnet werden; denn sie handeln getreulich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Und der Hohepriester Hilkija sprach zu Schaphan, dem Schreiber: Ich habe das Buch des Gesetzes im Hause Jehovas gefunden. Und Hilkia gab das Buch dem Schaphan, und er laß es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Und Schaphan, der Schreiber, kam zum König und brachte dem König Nachricht und sprach: Deine Knechte haben das Geld, das sich im Hause vorfand, ausgeschüttet und es in die Hand derer gegeben, welche das Werk betreiben, die am Hause Jehovas bestellt sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Und Schaphan, der Schreiber, berichtete dem König und sprach: Der Priester Hilkia hat mir ein Buch gegeben. Und Schaphan las es vor dem König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Und es geschah, als der König die Worte des Buches des Gesetzes hörte, da zerriß er seine Kleider.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Und der König gebot Hilkija, dem Priester, und Achikam, dem Sohne Schaphans, und Akbor, dem Sohne Michajas, und Schaphan, dem Schreiber, und Asaja, dem Knechte des Königs, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Gehet hin, befraget Jehova für mich und für das Volk und für ganz Juda wegen der Worte dieses gefundenen Buches. Denn groß ist der Grimm Jehovas, der wider uns entzündet ist, darum daß unsere Väter auf die Worte dieses Buches nicht gehört haben, um nach allem zu tun, was unsertwegen geschrieben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Da gingen der Priester Hilkija und Achikam und Akbor und Schaphan und Asaja zu der Prophetin Hulda, dem Weibe Schallums, des Sohnes Tikwas, des Sohnes Harchas\', des Hüters der Kleider; sie wohnte aber zu Jerusalem im zweiten Stadtteile; und sie redeten zu ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Und sie sprach zu ihnen: So spricht Jehova, der Gott Israels: Saget dem Manne, der euch zu mir gesandt hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'So spricht Jehova: Siehe, ich will Unglück bringen über diesen Ort und über seine Bewohner: alle Worte des Buches, welches der König von Juda gelesen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Darum daß sie mich verlassen und anderen Göttern geräuchert haben, um mich zu reizen mit all dem Machwerk ihrer Hände, so wird mein Grimm sich entzünden wider diesen Ort und wird nicht erlöschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Zu dem König von Juda aber, der euch gesandt hat, um Jehova zu befragen, zu ihm sollt ihr also sprechen: So spricht Jehova, der Gott Israels: Die Worte anlangend, die du gehört hast,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'weil dein Herz weich geworden ist, und du dich vor Jehova gedemütigt hast, als du hörtest, was ich über diesen Ort und über seine Bewohner geredet habe, daß sie zur Verwüstung und zum Fluche werden sollen, und du deine Kleider zerrissen und vor mir geweint hast, so habe ich es auch gehört, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Darum, siehe, werde ich dich zu deinen Vätern versammeln; und du wirst zu deinen Gräbern versammelt werden in Frieden, und deine Augen sollen all das Unglück nicht ansehen, das ich über diesen Ort bringen werde. Und sie brachten dem König Antwort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Und der König sandte hin, und man versammelte zu ihm alle Ältesten von Juda und von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Und der König ging in das Haus Jehovas hinauf, und alle Männer von Juda und alle Bewohner von Jerusalem mit ihm, und die Priester und die Propheten, und alles Volk, vom Kleinsten bis zum Größten; und man las vor ihren Ohren alle Worte des Buches des Bundes, das im Hause Jehovas gefunden worden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Und der König stand auf dem Standorte und machte den Bund vor Jehova, Jehova nachzuwandeln und seine Gebote und seine Zeugnisse und seine Satzungen zu beobachten mit ganzem Herzen und mit ganzer Seele, um die Worte dieses Bundes zu erfüllen, welche in diesem Buche geschrieben sind. Und das ganze Volk trat in den Bund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Und der König gebot Hilkija, dem Hohenpriester, und den Priestern zweiten Ranges und den Hütern der Schwelle, aus dem Tempel Jehovas alle Geräte hinauszutun, die dem Baal und der Aschera und dem ganzen Heere des Himmels gemacht worden waren; und er verbrannte sie außerhalb Jerusalems in den Gefilden des Kidron, und ließ ihren Staub nach Bethel bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Und er schaffte die Götzenpriester ab, welche die Könige von Juda eingesetzt hatten, und die auf den Höhen, in den Städten von Juda und in der Umgebung von Jerusalem geräuchert hatten; und die, welche dem Baal, der Sonne und dem Monde und dem Tierkreise und dem ganzen Heere des Himmels räucherten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Und er schaffte die Aschera aus dem Hause Jehovas hinaus, außerhalb Jerusalems, in das Tal Kidron; und er verbrannte sie im Tale Kidron und zermalmte sie zu Staub und warf ihren Staub auf die Gräber der Kinder des Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Und er riß die Häuser der Buhler nieder, die sich im Hause Jehovas befanden, worin die Weiber Zelte webten für die Aschera.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Und er ließ alle Priester aus den Städten Judas kommen, und verunreinigte die Höhen, wo die Priester geräuchert hatten, von Geba bis Beerseba. Und er riß die Höhen der Tore nieder, die am Eingang des Tores Josuas, des Obersten der Stadt, und die am Stadttore zur Linken jedes Eintretenden waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Doch opferten die Priester der Höhen nicht auf dem Altar Jehovas zu Jerusalem, sondern sie aßen Ungesäuertes in der Mitte ihrer Brüder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Und er verunreinigte das Topheth, welches im Tale der Söhne Hinnoms lag, damit niemand mehr seinen Sohn oder seine Tochter dem Molech durchs Feuer gehen ließe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Und er schaffte die Rosse ab, welche die Könige von Juda der Sonne gesetzt hatten am Eingang des Hauses Jehovas, bei der Zelle Nethan-Meleks, des Kämmerers, der im Parwarim wohnte; und die Wagen der Sonne verbrannte er mit Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Und die Altäre, die auf dem Dache des Obergemachs des Ahas waren, welche die Könige von Juda gemacht hatten, und die Altäre, welche Manasse in den beiden Höfen des Hauses Jehovas gemacht hatte, riß der König nieder und zertrümmerte sie, und er warf ihren Staub in das Tal Kidron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Und der König verunreinigte die Höhen, die vor Jerusalem, zur Rechten des Berges des Verderbens waren, welche Salomo, der König von Israel, der Astoreth, dem Scheusal der Zidonier, und Kamos, dem Scheusal Moabs, und Milkom, dem Greuel der Kinder Ammon, gebaut hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Und er zerschlug die Bildsäulen und hieb die Ascherim um, und füllte ihre Stätte mit Menschengebeinen an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Und auch den Altar, der zu Bethel war, die Höhe, welche Jerobeam, der Sohn Nebats, gemacht hatte, der Israel sündigen machte, auch diesen Altar und die Höhe riß er nieder; und er verbrannte die Höhe, zermalmte sie zu Staub und verbrannte die Aschera.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Und als Josia sich umwandte und die Gräber sah, die daselbst in dem Berge waren, da sandte er hin und ließ die Gebeine aus den Gräbern holen und verbrannte sie auf dem Altar und verunreinigte ihn, nach dem Worte Jehovas, das der Mann Gottes ausgerufen hatte, der diese Dinge ausrief.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Und er sprach: Was ist das dort für ein Mal, das ich sehe? Und die Leute der Stadt sprachen zu ihm: Es ist das Grab des Mannes Gottes, der von Juda gekommen ist und diese Dinge ausgerufen hat, die du wider den Altar von Bethel getan hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Und er sprach: Laßt ihn liegen, niemand beunruhige seine Gebeine! Und so retteten sie seine Gebeine samt den Gebeinen des Propheten, der von Samaria gekommen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Und auch alle Häuser der Höhen, die in den Städten Samarias waren, welche die Könige von Israel gemacht hatten, um Jehova zu reizen, tat Josia hinweg; und er verfuhr mit ihnen gerade so, wie er zu Bethel verfahren war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Und er schlachtete alle Priester der Höhen, die daselbst waren, auf den Altären, und verbrannte Menschengebeine auf denselben. Und er kehrte nach Jerusalem zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Und der König gebot dem ganzen Volke und sprach: Feiert Jehova, eurem Gott, Passah, wie in diesem Buche des Bundes geschrieben steht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Denn es war kein solches Passah gefeiert worden wie dieses, von den Tagen der Richter an, welche Israel gerichtet haben, und alle Tage der Könige von Israel und der Könige von Juda;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'sondern im achtzehnten Jahre des Königs Josia wurde dieses Passah dem Jehova zu Jerusalem gefeiert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Und auch die Totenbeschwörer und die Wahrsager, und die Teraphim und die Götzen, und alle Scheusale, die im Lande Juda und in Jerusalem gesehen wurden, schaffte Josia hinweg, um die Worte des Gesetzes auszuführen, welche in dem Buche geschrieben standen, das der Priester Hilkija im Hause Jehovas gefunden hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Und vor ihm ist seinesgleichen kein König gewesen, der zu Jehova umgekehrt wäre mit seinem ganzen Herzen und mit seiner ganzen Seele und mit seiner ganzen Kraft, nach allem Gesetz Moses; und nach ihm ist seinesgleichen nicht aufgestanden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Doch kehrte Jehova nicht um von der großen Glut seines Zornes, womit sein Zorn wider Juda entbrannt war, wegen all der Reizungen, mit welchen Manasse ihn gereizt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Und Jehova sprach: Auch Juda will ich vor meinem Angesicht hinwegtun, wie ich Israel hinweggetan habe; und ich will diese Stadt verwerfen, die ich erwählt, Jerusalem, und das Haus, von dem ich gesagt habe: Mein Name soll daselbst sein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Und das Übrige der Geschichte Josias und alles, was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'In seinen Tagen zog der Pharao Neko, der König von Ägypten, wider den König von Assyrien hinauf, an den Strom Phrat. Und der König Josia zog ihm entgegen; aber Neko tötete ihn zu Megiddo, sowie er ihn sah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Und seine Knechte führten ihn zu Wagen tot von Megiddo hinweg und brachten ihn nach Jerusalem; und sie begruben ihn in seinem Begräbnis. Und das Volk des Landes nahm Joahas, den Sohn Josias, und sie salbten ihn und machten ihn zum König an seines Vaters Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Dreiundzwanzig Jahre war Joahas alt, als er König wurde, und er regierte drei Monate zu Jerusalem; und der Name seiner Mutter war Hamutal, die Tochter Jeremias, von Libna.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Und er tat, was böse war in den Augen Jehovas, nach allem, was seine Väter getan hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Und der Pharao Neko setzte ihn gefangen zu Ribla im Lande Hamath, daß er nicht mehr König wäre zu Jerusalem; und er legte dem Lande eine Buße von hundert Talenten Silber und einem Talente Gold auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Und der Pharao Neko machte Eljakim, den Sohn Josias, zum König, an Josias, seines Vaters, Statt, und verwandelte seinen Namen in Jojakim; Joahas aber nahm er mit, und er kam nach Ägypten und starb daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Und Jojakim gab das Silber und das Gold dem Pharao; doch schätzte er das Land, um das Geld nach dem Befehle des Pharao zu geben: von dem Volke des Landes, von einem jeden nach seiner Schätzung, trieb er das Silber und das Gold ein, um es dem Pharao Neko zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Fünfundzwanzig Jahre war Jojakim alt, als er König wurde, und er regierte elf Jahre zu Jerusalem; und der Name seiner Mutter war Sebudda, die Tochter Pedajas, von Ruma.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Und er tat, was böse war in den Augen Jehovas, nach allem, was seine Väter getan hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'In seinen Tagen zog Nebukadnezar, der König von Babel, herauf; und Jojakim wurde sein Knecht drei Jahre; dann wandte er sich und empörte sich gegen ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Und Jehova sandte wider ihn Scharen der Chaldäer und Scharen der Syrer und Scharen der Moabiter und Scharen der Kinder Ammon; er sandte sie wider Juda, um es zu vernichten, nach dem Worte Jehovas, das er durch seine Knechte, die Propheten, geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Fürwahr, nach dem Befehle Jehovas geschah dieses wider Juda, um es vor seinem Angesicht hinwegzutun, wegen der Sünden Manasses, nach allem, was er getan hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'und auch wegen des unschuldigen Blutes, das er vergossen, da er Jerusalem mit unschuldigem Blute erfüllt hatte. Und Jehova wollte nicht vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Und das Übrige der Geschichte Jojakims und alles, was er getan hat, ist das nicht geschrieben in dem Buche der Chronika der Könige von Juda?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Und Jojakim legte sich zu seinen Vätern. Und Jojakin, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Aber der König von Ägypten zog fortan nicht mehr aus seinem Lande; denn der König von Babel hatte von dem Flusse Ägyptens an bis zum Strome Phrat alles genommen, was dem König von Ägypten gehört hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Achtzehn Jahre war Jojakin alt, als er König wurde, und er regierte drei Monate zu Jerusalem; und der Name seiner Mutter war Nechuschta, die Tochter Elnathans, von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Und er tat, was böse war in den Augen Jehovas, nach allem, was sein Vater getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Zu jener Zeit zogen die Knechte Nebukadnezars, des Königs von Babel, nach Jerusalem herauf, und die Stadt kam in Belagerung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Und Nebukadnezar, der König von Babel, kam zu der Stadt, während seine Knechte sie belagerten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Und Jojakin, der König von Juda, ging zu dem König von Babel hinaus, er und seine Mutter und seine Knechte und seine Obersten und seine Kämmerer; und der König von Babel nahm ihn gefangen im achten Jahre seiner Regierung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Und er brachte von dannen heraus alle Schätze des Hauses Jehovas und die Schätze des Königshauses, und er zerschlug alle goldenen Geräte, die Salomo, der König von Israel, im Tempel Jehovas gemacht hatte: so wie Jehova geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Und er führte ganz Jerusalem hinweg, und alle Obersten und alle streitbaren Männer, zehntausend Gefangene, und alle Werkleute und Schlosser; nichts blieb übrig als nur das geringe Volk des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Und er führte Jojakin hinweg nach Babel; und die Mutter des Königs und die Weiber des Königs und seine Kämmerer und die Mächtigen des Landes führte er als Gefangene von Jerusalem hinweg nach Babel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'und alle Kriegsmänner, siebentausend, und die Werkleute und die Schlosser, tausend, alles streitbare Männer, Kriegsleute, die brachte der König von Babel als Gefangene nach Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Und der König von Babel machte Mattanja, Jojakins Oheim, zum König an seiner Statt und verwandelte seinen Namen in Zedekia.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Einundzwanzig Jahre war Zedekia alt, als er König wurde, und er regierte elf Jahre zu Jerusalem; und der Name seiner Mutter war Hamutal, die Tochter Jeremias, von Libna.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Und er tat, was böse war in den Augen Jehovas, nach allem was Jojakim getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Denn wegen des Zornes Jehovas geschah dieses wider Jerusalem und wider Juda, bis er sie von seinem Angesicht weggeworfen hatte. Und Zedekia empörte sich gegen den König von Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Und es geschah im neunten Jahre seiner Regierung, im zehnten Monat, am Zehnten des Monats, da kam Nebukadnezar, der König von Babel, er und sein ganzes Heer, wider Jerusalem und belagerte es; und sie bauten eine Verschanzung wider dasselbe ringsumher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Und die Stadt kam in Belagerung bis in das elfte Jahr des Königs Zedekia.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Am Neunten des vierten Monats, da nahm der Hunger in der Stadt überhand; und es war kein Brot mehr da für das Volk des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Und die Stadt wurde erbrochen, und alle Kriegsmänner flohen des Nachts auf dem Wege durch das Tor, welches zwischen den beiden Mauern bei dem Garten des Königs lag (die Chaldäer aber waren rings um die Stadt her); und man zog den Weg zur Ebene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Aber das Heer der Chaldäer jagte dem König nach, und sie erreichten ihn in den Ebenen von Jericho; und sein ganzes Heer zerstreute sich von ihm weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Und sie ergriffen den König und führten ihn zu dem König von Babel nach Ribla hinauf; und man sprach das Urteil über ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Und man schlachtete die Söhne Zedekias vor seinen Augen; und man blendete die Augen Zedekias, und band ihn mit ehernen Fesseln und brachte ihn nach Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Und im fünften Monat, am Siebten des Monats, das war das neunzehnte Jahr des Königs Nebukadnezar, des Königs von Babel, kam Nebusaradan, der Oberste der Leibwache, der Knecht des Königs von Babel, nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Und er verbrannte das Haus Jehovas und das Haus des Königs; und alle Häuser Jerusalems und jedes große Haus verbrannte er mit Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Und das ganze Heer der Chaldäer, das bei dem Obersten der Leibwache war, riß die Mauern von Jerusalem ringsum nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Und den Rest des Volkes, die in der Stadt Übriggebliebenen, und die Überläufer, die zum König von Babel übergelaufen waren, und den Rest der Menge führte Nebusaradan, der Oberste der Leibwache, hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Aber von den Geringen des Landes ließ der Oberste der Leibwache zurück zu Weingärtnern und zu Ackerleuten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Und die ehernen Säulen, die am Hause Jehovas waren, und die Gestelle und das eherne Meer, die im Hause Jehovas waren, zerschlugen die Chaldäer und führten das Erz davon nach Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Und die Töpfe und die Schaufeln und die Lichtmesser und die Schalen, und alle ehernen Geräte, womit man den Dienst verrichtete, nahmen sie weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Auch die Räucherpfannen und die Sprengschalen, was von Gold war, das Gold, und was von Silber war, das Silber, nahm der Oberste der Leibwache weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Die zwei Säulen, das eine Meer und die Gestelle, die Salomo für das Haus Jehovas gemacht hatte: das Erz aller dieser Geräte war nicht zu wägen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Achtzehn Ellen war die Höhe der einen Säule, und ein Kapitäl von Erz war darauf, und die Höhe des Kapitäls war drei Ellen, und Netzwerk und Granatäpfel waren an dem Kapitäl ringsum: alles von Erz; und desgleichen war die andere Säule nebst dem Netzwerk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Und der Oberste der Leibwache nahm Scheraja, den Oberpriester, und Zephanja, den zweiten Priester, und die drei Hüter der Schwelle;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'und aus der Stadt nahm er einen Kämmerer, der über die Kriegsleute bestellt war, und fünf Männer von denen, welche das Angesicht des Königs sahen, die in der Stadt vorgefunden wurden, und den Schreiber des Heerobersten, der das Volk des Landes zum Heere aushob, und sechzig Mann von dem Volke des Landes, die in der Stadt vorgefunden wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Und Nebusaradan, der Oberste der Leibwache, nahm sie und brachte sie zu dem König von Babel nach Ribla.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Und der König von Babel erschlug sie und tötete sie zu Ribla im Lande Hamath. Und so wurde Juda aus seinem Lande weggeführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Und über das Volk, das im Lande Juda übriggeblieben war, welches Nebukadnezar, der König von Babel, übriggelassen hatte, über sie bestellte er Gedalja, den Sohn Achikams, des Sohnes Schaphans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Und als alle Heerobersten, sie und ihre Männer, hörten, daß der König von Babel Gedalja bestellt habe, da kamen sie zu Gedalja nach Mizpa; nämlich Ismael, der Sohn Nethanjas, und Jochanan, der Sohn Kareachs, und Seraja, der Sohn Tanchumeths, der Netophathiter, und Jaasanja, der Sohn des Maakathiters, sie und ihre Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Und Gedalja schwur ihnen und ihren Männern und sprach zu ihnen: Fürchtet euch nicht vor den Knechten der Chaldäer; bleibet im Lande und dienet dem König von Babel, so wird es euch wohl gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Es geschah aber im siebten Monat, da kam Ismael, der Sohn Nethanjas, des Sohnes Elischamas, vom königlichen Geschlecht, und zehn Männer mit ihm; und sie erschlugen Gedalja (und er starb) sowie die Juden und die Chaldäer, die zu Mizpa bei ihm waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Da machte sich alles Volk, vom Kleinsten bis zum Größten, mit den Heerobersten auf, und sie kamen nach Ägypten; denn sie fürchteten sich vor den Chaldäern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Und es geschah im siebenunddreißigsten Jahre der Wegführung Jojakins, des Königs von Juda, im zwölften Monat, am Siebenundzwanzigsten des Monats, da erhob Ewil-Merodak, der König von Babel, im Jahre, da er König wurde, das Haupt Jojakins, des Königs von Juda, aus dem Gefängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Und er redete gütig mit ihm und setzte seinen Stuhl über den Stuhl der Könige, die bei ihm in Babel waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'und er veränderte die Kleider seines Gefängnisses; und er aß beständig vor ihm alle Tage seines Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Und sein Unterhalt, ein beständiger Unterhalt, wurde ihm, so viel er täglich bedurfte, von dem König gegeben alle Tage seines Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Seth, Enos,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahalalel, Jered,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Henoch, Methusalah, Lamech,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noah, Sem, Ham, und Japhet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Die Söhne Japhets: Gomer und Magog und Madai und Jawan und Tubal, und Mesech und Tiras.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Und die Söhne Gomers: Askenas und Diphath und Togarma.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Und die Söhne Jawans: Elisa und Tarsis, die Kittim und die Rodanim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Die Söhne Hams: Kusch und Mizraim, Put und Kanaan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Und die Söhne Kuschs: Seba und Hawila, und Sabta und Raghma und Sabteka. Und die Söhne Raghmas: Scheba und Dedan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Und Kusch zeugte Nimrod; der fing an, ein Gewaltiger zu sein auf der Erde. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Und Mizraim zeugte die Ludim und die Anamim und die Lehabim und die Naphtuchim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'und die Pathrusim und die Kasluchim (von welchen die Philister ausgegangen sind) und die Kaphtorim. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Und Kanaan zeugte Zidon, seinen Erstgeborenen, und Heth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'und den Jebusiter und den Amoriter und den Girgasiter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'und den Hewiter und den Arkiter und den Siniter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'und den Arwaditer und den Zemariter und den Hamathiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Die Söhne Sems: Elam und Assur und Arpaksad und Lud und Aram, und Uz und Hul und Gether und Mesech.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Und Arpaksad zeugte Schelach, und Schelach zeugte Heber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Und Heber wurden zwei Söhne geboren: der Name des einen war Peleg, denn in seinen Tagen wurde die Erde verteilt; und der Name seines Bruders war Joktan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Und Joktan zeugte Almodad und Scheleph und Hazarmaweth und Jerach,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'und Hadoram und Usal und Dikla,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'und Ebal und Abimael und Scheba,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'und Ophir und Hawila und Jobab; diese alle waren Söhne Joktans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arpaksad, Schelach,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Heber, Peleg, Reghu,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nahor, Tarah,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, das ist Abraham.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Die Söhne Abrahams: Isaak und Ismael.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Dies sind ihre Geschlechter: Der Erstgeborene Ismaels: Nebajoth; und Kedar und Adbeel und Mibsam,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Mischma und Duma, Massa, Hadad und Tema,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Naphisch und Kedma; das sind die Söhne Ismaels. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Und die Söhne der Ketura, des Kebsweibes Abrahams: sie gebar Simran und Jokschan und Medan und Midian und Jischbak und Schuach. Und die Söhne Jokschans: Scheba und Dedan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Und die Söhne Midians: Epha und Epher und Hanok und Abida und Eldaa. Diese alle waren Söhne der Ketura. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Und Abraham zeugte Isaak. Die Söhne Isaaks: Esau und Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Die Söhne Esaus: Eliphas, Reghuel, und Jeghusch und Jaghlam und Korach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Die Söhne Eliphas\': Teman und Omar, Zephi und Gaetam, Kenas und Timna und Amalek.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Die Söhne Reghuels: Nachath, Serach, Schamma und Missa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Und die Söhne Seirs: Lotan und Schobal und Zibeon und Ana und Dischon und Ezer und Dischan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Und die Söhne Lotans: Hori und Homam; und die Schwester Lotans: Timna.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Die Söhne Schobals: Aljan und Manachath und Ebal, Schephi und Onam. Und die Söhne Zibeons: Aja und Ana.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Die Söhne Anas: Dischon. Und die Söhne Dischons: Hamran und Eschban und Jithran und Keran. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Die Söhne Ezers: Bilhan und Saawan und Jaakan. Die Söhne Dischans: Uz und Aran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Und dies sind die Könige, welche im Lande Edom regiert haben, ehe ein König über die Kinder Israel regierte: Bela, der Sohn Beors; und der Name seiner Stadt war Dinhaba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Und Bela starb; und es ward König an seiner Statt Jobab, der Sohn Serachs, aus Bozra.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Und Jobab starb; und es ward König an seiner Statt Huscham, aus dem Lande der Temaniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Und Huscham starb; und es ward König an seiner Statt Hadad, der Sohn Bedads, welcher Midian schlug im Gefilde Moabs; und der Name seiner Stadt war Awith.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Und Hadad starb; und es ward König an seiner Statt Samla aus Masreka.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Und Samla starb; und es ward König an seiner Statt Saul, aus Rechoboth am Strome.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Und Saul starb; und es ward König an seiner Statt Baal-Hanan, der Sohn Akbors.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Und Baal-Hanan starb; und es ward König an seiner Statt Hadad; und der Name seiner Stadt war Paghi, und der Name seines Weibes Mehetabeel, die Tochter Matreds, der Tochter Mesahabs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Und Hadad starb. Und die Fürsten von Edom waren: der Fürst Timna, der Fürst Alja, der Fürst Jetheth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'der Fürst Oholibama, der Fürst Ela, der Fürst Pinon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'der Fürst Kenas, der Fürst Teman, der Fürst Mibzar,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'der Fürst Magdiel, der Fürst Iram. Das sind die Fürsten von Edom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Dies sind die Söhne Israels: Ruben, Simeon, Levi und Juda, Issaschar und Sebulon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph und Benjamin, Naphtali, Gad und Aser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Die Söhne Judas: Gher und Onan und Schela; diese drei wurden ihm geboren von der Tochter Schuas, der Kanaaniterin. Und Gher, der Erstgeborene Judas, war böse in den Augen Jehovas, und er tötete ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Und Tamar, seine Schwiegertochter, gebar ihm Perez und Serach. Aller Söhne Judas waren fünf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Die Söhne des Perez waren: Hezron und Hamul.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Und die Söhne Serachs: Simri und Ethan und Heman und Kalkol und Dara; ihrer aller waren fünf. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Und die Söhne Karmis: Achar, der Israel in Trübsal brachte, weil er Untreue beging an dem Verbannten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Und die Söhne Ethans: Asarja. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Und die Söhne Hezrons, die ihm geboren wurden: Jerachmeel und Ram und Kelubai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Und Ram zeugte Amminadab; und Amminadab zeugte Nachschon, den Fürsten der Kinder Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Und Nachschon zeugte Salma, und Salma zeugte Boas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'und Boas zeugte Obed, und Obed zeugte Isai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Und Isai zeugte Eliab, seinen Erstgeborenen; und Abinadab, den zweiten; und Schimea, den dritten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Nethaneel, den vierten; Raddai, den fünften;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Ozem, den sechsten; David, den siebten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Und ihre Schwestern waren: Zeruja und Abigail. Und die Söhne der Zeruja: Abisai und Joab und Asael, drei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Und Abigail gebar Amasa; und der Vater Amasas war Jether, der Ismaeliter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Und Kaleb, der Sohn Hezrons, zeugte Söhne mit Asuba, seinem Weibe, und mit Jerioth; und dies sind ihre Söhne: Jescher und Schobab und Ardon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Und Asuba starb; und Kaleb nahm sich Ephrath, und sie gebar ihm Hur.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Und Hur zeugte Uri, und Uri zeugte Bezaleel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Und danach ging Hezron ein zu der Tochter Makirs, des Vaters Gileads; und er nahm sie, als er sechzig Jahre alt war, und sie gebar ihm Segub.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Und Segub zeugte Jair. Und dieser hatte dreiundzwanzig Städte im Lande Gilead;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'und Gesur und Aram nahmen ihnen die Dörfer Jairs weg, mit Kenath und seinen Tochterstädten, sechzig Städte. Diese alle waren Söhne Makirs, des Vaters Gileads.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Und nach dem Tode Hezrons in Kaleb-Ephratha, da gebar Abija, Hezrons Weib, ihm Aschur, den Vater Tekoas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Und die Söhne Jerachmeels, des Erstgeborenen Hezrons, waren: Der Erstgeborene, Ram, und Buna und Oren und Ozem, von Achija.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Und Jerachmeel hatte ein anderes Weib, ihr Name war Atara; sie war die Mutter Onams. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Und die Söhne Rams, des Erstgeborenen Jerachmeels, waren: Maaz und Jamin und Eker. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Und die Söhne Onams waren: Schammai und Jada. Und die Söhne Schammais: Nadab und Abischur.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Und der Name des Weibes Abischurs war Abichail; und sie gebar ihm Achban und Molid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Und die Söhne Nadabs: Seled und Appaim. Und Seled starb ohne Söhne. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Und die Söhne Appaims: Jischhi. Und die Söhne Jischhis: Scheschan. Und die Söhne Scheschans: Achlai. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Und die Söhne Jadas, des Bruders Schammais: Jether und Jonathan. Und Jether starb ohne Söhne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Und die Söhne Jonathans: Peleth und Sasa. Das waren die Söhne Jerachmeels. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Und Scheschan hatte keine Söhne, sondern nur Töchter. Und Scheschan hatte einen ägyptischen Knecht, sein Name war Jarcha;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'und Scheschan gab seinem Knechte Jarcha seine Tochter zum Weibe, und sie gebar ihm Attai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Und Attai zeugte Nathan, und Nathan zeugte Sabad,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'und Sabad zeugte Ephlal, und Ephlal zeugte Obed,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'und Obed zeugte Jehu, und Jehu zeugte Asarja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'und Asarja zeugte Helez, und Helez zeugte Elasa,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'und Elasa zeugte Sismai, und Sismai zeugte Schallum,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'und Schallum zeugte Jekamja, und Jekamja zeugte Elischama.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Und die Söhne Kalebs, des Bruders Jerachmeels: Mescha, sein Erstgeborener (er ist der Vater Siphs), und die Söhne Mareschas, des Vaters Hebrons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Und die Söhne Hebrons: Korach und Tappuach und Rekem und Schema.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Und Schema zeugte Racham, den Vater Jorkeams, und Rekem zeugte Schammai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Und der Sohn Schammais war Maon, und Maon war der Vater Beth-Zurs. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Und Epha, das Kebsweib Kalebs, gebar Haran und Moza und Gases. Und Haran zeugte Gases. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Und die Söhne Jehdais: Regem und Jotham und Geschan und Peleth und Epha und Schaaph. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Maaka, das Kebsweib Kalebs, gebar Scheber und Tirchana;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'und sie gebar Schaaph, den Vater Madmannas, Schewa, den Vater Makbenas, und den Vater Gibeas. Und die Tochter Kalebs war Aksa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Dies waren die Söhne Kalebs: Die Söhne Hurs, des Erstgeborenen der Ephratha: Schobal, der Vater von Kirjath-Jearim;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, der Vater von Bethlehem; Hareph, der Vater von Beth-Gader.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Und Schobal, der Vater von Kirjath-Jearim, hatte Söhne: Haroeh, Hazi-Hammenuchoth;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'und die Geschlechter von Kirjath-Jearim waren: die Jithriter und die Puthiter und die Schumathiter und die Mischraiter; von diesen sind ausgegangen die Zorathiter und die Estauliter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Die Söhne Salmas: Bethlehem, und die Netophathiter, Ateroth-Beth-Joab, und Hazi-Hammanachti, die Zoriter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'und die Geschlechter der Schreiber, welche Jabez bewohnten: die Tirathiter, die Schimathiter, die Sukathiter. Das sind die Keniter, die von Hammath, dem Vater des Hauses Rekab, herkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Und dies waren die Söhne Davids, die ihm in Hebron geboren wurden: Der erstgeborene, Ammon, von Achinoam, der Jisreelitin; der zweite, Daniel, von Abigail, der Karmelitin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'der dritte, Absalom, der Sohn Maakas, der Tochter Talmais, des Königs von Gesur; der vierte, Adonija, der Sohn Haggiths;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'der fünfte, Schephatja, von Abital; der sechste, Jithream, von seinem Weibe Egla.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Sechs wurden ihm in Hebron geboren. Und er regierte daselbst sieben Jahre und sechs Monate; und dreiunddreißig Jahre regierte er zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Und diese wurden ihm in Jerusalem geboren: Schimea und Schobab und Nathan und Salomo, vier, von Bathschua, der Tochter Ammiels;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'und Jibchar und Elischama und Eliphelet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'und Nogah und Nepheg und Japhia,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'und Elischama und Eljada und Eliphelet, neun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'alles Söhne Davids, außer den Söhnen der Kebsweiber; und Tamar war ihre Schwester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Und der Sohn Salomos war Rehabeam; dessen Sohn Abija, dessen Sohn Asa, dessen Sohn Josaphat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'dessen Sohn Joram, dessen Sohn Ahasja, dessen Sohn Joas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'dessen Sohn Amazja, dessen Sohn Asarja, dessen Sohn Jotham,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'dessen Sohn Ahas, dessen Sohn Hiskia, dessen Sohn Manasse,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'dessen Sohn Amon, dessen Sohn Josia.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Und die Söhne Josias: Der erstgeborene, Jochanan; der zweite, Jojakim; der dritte, Zedekia; der vierte, Schallum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Und die Söhne Jojakims: dessen Sohn Jekonja, dessen Sohn Zedekia.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Und die Söhne Jekonjas: Assir; dessen Sohn Schealtiel');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'und Malkiram und Pedaja und Schenazar, Jekamja, Hoschama und Nebadja.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Und die Söhne Pedajas: Serubbabel und Simei. Und die Söhne Serubbabels: Meschullam und Hananja; und Schelomith war ihre Schwester;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'und Haschuba und Ohel und Berekja und Hasadja, Juschab-Hesed, fünf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Und die Söhne Hananjas: Pelatja und Jesaja; die Söhne Rephajas, die Söhne Arnans, die Söhne Obadjas, die Söhne Schekanjas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Und die Söhne Schekanjas: Schemaja. Und die Söhne Schemajas: Hattusch und Jigeal und Bariach und Nearja und Schaphath... sechs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Und die Söhne Nearjas: Eljoenai und Hiskia und Asrikam, drei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Und die Söhne Eljoenais: Hodajewa und Eljaschib und Pelaja und Akkub und Jochanan und Delaja und Anani, sieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Die Söhne Judas: Perez, Hezron und Karmi und Hur und Schobal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Und Reaja, der Sohn Schobals, zeugte Jachath; und Jachath zeugte Achumai und Lahad. Das sind die Geschlechter der Zorathiter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Und diese sind von dem Vater Etams: Jisreel und Jischma und Jitbasch; und der Name ihrer Schwester: Hazlelponi;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'und Pnuel, der Vater Gedors; und Eser, der Vater Huschas. Das sind die Söhne Hurs, des Erstgeborenen der Ephratha, des Vaters von Bethlehem. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Und Aschhur, der Vater Tekoas, hatte zwei Weiber: Helea und Naara.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Und Naara gebar ihm Achussam und Hepher und Temni und Achaschtari. Das sind die Söhne der Naara.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Und die Söhne der Helea: Zereth und Jizchar und Ethnan. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Und Koz zeugte Anub und Zobeba und die Geschlechter Acharchels, des Sohnes Harums.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Und Jabez war geehrter als seine Brüder; und seine Mutter gab ihm den Namen Jabez, indem sie sprach: Mit Schmerzen habe ich ihn geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Und Jabez rief zu dem Gott Israels und sprach: Wenn du mich reichlich segnest und meine Grenze erweiterst, und deine Hand mit mir ist, und du das Übel fern hältst, daß kein Schmerz mich trifft! Und Gott ließ kommen, was er erbeten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Und Kelub, der Bruder Schuchas, zeugte Mechir; er war der Vater Eschtons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Und Eschton zeugte Beth-Rapha und Paseach und Techinna, den Vater der Stadt Nahas\'; das sind die Männer von Reka. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Und die Söhne Kenas\': Othniel und Seraja. Und die Söhne Othniels: Hathath.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Und Meonothai zeugte Ophra; und Seraja zeugte Joab, den Vater des Tales der Werkleute, denn sie waren Werkleute. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Und die Söhne Kalebs, des Sohnes Jephunnes: Iru, Ela und Naam. Und die Söhne Elas: Kenas. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Und die Söhne Jehallelels: Siph und Sipha, Tirja und Asarel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Und die Söhne Esras: Jether und Mered und Epher und Jalon. Und sie wurde schwanger und gebar Mirjam und Schammai und Jischbach, den Vater Estemoas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Und sein Weib, die Jüdin, gebar Jered, den Vater Gedors, und Heber, den Vater Sokos, und Jekuthiel, den Vater Sanoachs. Und dies sind die Söhne der Bithja, der Tochter des Pharao, welche Mered genommen hatte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Und die Söhne des Weibes Hodijas, der Schwester Nachams: der Vater Kehilas, der Garmiter, und Estemoa, der Maakathiter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Und die Söhne Schimons: Amnon und Rinna, Benchanan und Tilon. Und die Söhne Jischeis: Socheth und Ben-Socheth. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Die Söhne Schelas, des Sohnes Judas: Gher, der Vater Lekas, und Laeda, der Vater Mareschas; und die Geschlechter des Hauses der Byssusarbeiter vom Hause Aschbea;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'und Jokim und die Männer von Koseba; und Joas und Saraph, die über Moab herrschten; und Jaschubi-Lechem. Die Dinge sind aber alt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Das waren die Töpfer und die Bewohner von Pflanzungen und Mauern; sie wohnten daselbst bei dem König in seinem Geschäft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Die Söhne Simeons: Nemuel und Jamin, Jarib, Serach, Saul;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'dessen Sohn Schallum, dessen Sohn Mibsam, dessen Sohn Mischma.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Und die Söhne Mischmas: dessen Sohn Hamuel, dessen Sohn Sakkur, dessen Sohn Simei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Und Simei hatte sechzehn Söhne und sechs Töchter; aber seine Brüder hatten nicht viele Söhne, und alle ihre Familien vermehrten sich nicht so sehr wie die Söhne Judas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Und sie wohnten in Beerseba und Molada und Hazar-Schual,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'und in Bilha und in Ezem und in Tolad,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'und in Bethuel und in Horma und in Ziklag,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'und in Beth-Markaboth und in Hazar-Susim und in Beth-Birei und in Schaaraim. Das waren ihre Städte, bis David König wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Und ihre Dörfer: Etam und Ain, Rimmon und Token und Aschan: fünf Städte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'nebst allen ihren Dörfern, die rings um diese Städte waren, bis nach Baal hin. Das waren ihre Wohnsitze; und sie hatten ihr Geschlechtsverzeichnis. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Und Meschobab und Jamlek und Joscha, der Sohn Amazjas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'und Joel und Jehu, der Sohn Joschibjas, des Sohnes Serajas, des Sohnes Asiels;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'und Eljoenai und Jaakoba und Jeschochaja und Asaja und Adiel und Jeschimiel und Benaja;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'und Sisa, der Sohn Schipheis, des Sohnes Allons, des Sohnes Jedajas, des Sohnes Schimris, des Sohnes Schemajas:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'diese mit Namen Angeführten waren Fürsten in ihren Geschlechtern; und ihre Vaterhäuser breiteten sich aus in Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Und sie zogen bis nach Gedor hin, bis an die Ostseite des Tales, um Weide für ihr Kleinvieh zu suchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Und sie fanden eine fette und gute Weide, und ein Land, weit nach allen Seiten hin, und ruhig und still; denn die vordem dort gewohnt hatten, waren von Ham.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Und diese mit Namen Aufgeschriebenen kamen in den Tagen Hiskias, des Königs von Juda, und sie schlugen ihre Zelte und die Meuniter, welche sich daselbst befanden; und sie verbannten sie bis auf diesen Tag und wohnten an ihrer Statt; denn daselbst war Weide für ihr Kleinvieh. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Und von ihnen, von den Söhnen Simeons, zogen fünfhundert Männer zum Gebirge Seir hin; und Pelatja und Nearja und Rephaja und Ussiel, die Söhne Jischeis, waren an ihrer Spitze;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'und sie schlugen den Überrest, die Entronnenen von Amalek, und haben daselbst gewohnt bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Und die Söhne Rubens, des Erstgeborenen Israels, denn er war der Erstgeborene; weil er aber das Lager seines Vaters entweiht hatte, wurde sein Erstgeburtsrecht den Söhnen Josephs, des Sohnes Israels, gegeben; aber er wird nicht nach der Erstgeburt verzeichnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Denn Juda hatte die Oberhand unter seinen Brüdern, und der Fürst kommt aus ihm; aber das Erstgeburtsrecht wurde dem Joseph zuteil; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'die Söhne Rubens, des Erstgeborenen Israels: Hanok und Pallu, Hezron und Karmi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Die Söhne Joels: dessen Sohn Schemaja, dessen Sohn Gog, dessen Sohn Simei,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'dessen Sohn Micha, dessen Sohn Reaja, dessen Sohn Baal,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'dessen Sohn Beera, welchen Tilgath-Pilneser, der König von Assyrien, wegführte; er war ein Fürst der Rubeniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Und seine Brüder, nach ihren Familien, nach dem Verzeichnis ihrer Geschlechter, waren: das Haupt, Jehiel; und Sekarja');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'und Bela, der Sohn Asas, des Sohnes Schemas, des Sohnes Joels; dieser wohnte in Aroer und bis Nebo und Baal-Meon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'und gegen Osten wohnte er bis zu der Wüste, welche sich von dem Strome Phrat her erstreckt; denn ihre Herden waren zahlreich im Lande Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Und in den Tagen Sauls führten sie Krieg mit den Hageritern; und diese fielen durch ihre Hand, und sie wohnten in ihren Zelten auf der ganzen Ostseite von Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Und die Kinder Gad wohnten ihnen gegenüber im Lande Basan bis Salka:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joel, das Haupt; und Schapham, der zweite; und Jahnai und Schaphat, in Basan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Und ihre Brüder nach ihren Vaterhäusern: Michael und Meschullam und Scheba und Jorai und Jakan und Sia und Heber, sieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Das waren die Söhne Abichails, des Sohnes Huris, des Sohnes Jaroachs, des Sohnes Gileads, des Sohnes Michaels, des Sohnes Jeschischais, des Sohnes Jachdos, des Sohnes Bus\'.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Achi, der Sohn Abdiels, des Sohnes Gunis, war das Haupt ihres Vaterhauses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Und sie wohnten in Gilead, in Basan, und in deren Tochterstädten, und in allen Weidetriften Sarons bis an ihre Ausgänge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Diese alle sind verzeichnet worden in den Tagen Jothams, des Königs von Juda, und in den Tagen Jerobeams, des Königs von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Die Kinder Ruben und die Gaditer und der halbe Stamm Manasse, was tapfere Männer waren, Männer, die Schild und Schwert trugen und den Bogen spannten und des Krieges kundig waren: vierundvierzigtausend siebenhundertsechzig, die zum Heere auszogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Und sie führten Krieg mit den Hageritern und mit Jetur und Naphisch und Nodab;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'und es wurde ihnen wider sie geholfen; und die Hageriter wurden in ihre Hand gegeben samt allen, die mit ihnen waren; denn sie schrieen zu Gott im Streit, und er ließ sich von ihnen erbitten, weil sie auf ihn vertraut hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Und sie führten ihr Vieh hinweg: fünfzigtausend Kamele, und zweihundertfünfzigtausend Stück Kleinvieh, und zweitausend Esel, und hunderttausend Menschenseelen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Denn es fielen viele Erschlagene, weil der Streit von Gott war. Und sie wohnten an ihrer Statt bis zur Wegführung. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Und die Kinder des halben Stammes Manasse wohnten im Lande, von Basan bis Baal-Hermon und bis zum Senir und bis zum Berge Hermon; sie waren zahlreich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Und dies waren die Häupter ihrer Vaterhäuser: nämlich Epher und Jischi und Eliel und Asriel und Jeremja und Hodawja und Jachdiel, tapfere Kriegsmänner, Männer von Namen, Häupter ihrer Vaterhäuser. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Aber sie handelten treulos gegen den Gott ihrer Väter und hurten den Göttern der Völker des Landes nach, welche Gott vor ihnen vertilgt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Da erweckte der Gott Israels den Geist Puls, des Königs von Assyrien, und den Geist Tilgath-Pilnesers, des Königs von Assyrien, und er führte sie hinweg, die Rubeniter und die Gaditer und den halben Stamm Manasse, und brachte sie nach Halach und an den Habor und nach Hara und an den Strom von Gosan bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Die Söhne Levis waren: Gersom, Kehath und Merari.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Und die Söhne Kehaths: Amram, Jizhar und Hebron und Ussiel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Und die Söhne Amrams: Aaron und Mose, und Mirjam. Und die Söhne Aarons: Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleasar zeugte Pinehas; Pinehas zeugte Abischua,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'und Abischua zeugte Bukki, und Bukki zeugte Ussi,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'und Ussi zeugte Serachja, und Serachja zeugte Merajoth;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Merajoth zeugte Amarja, und Amarja zeugte Ahitub,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'und Ahitub zeugte Zadok, und Zadok zeugte Achimaaz,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'und Achimaaz zeugte Asarja, und Asarja zeugte Jochanan,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'und Jochanan zeugte Asarja; dieser ist es, der den Priesterdienst ausübte in dem Hause, welches Salomo zu Jerusalem gebaut hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Und Asarja zeugte Amarja, und Amarja zeugte Ahitub,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'und Ahitub zeugte Zadok, und Zadok zeugte Schallum,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'und Schallum zeugte Hilkija, und Hilkija zeugte Asarja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'und Asarja zeugte Seraja, und Seraja zeugte Jehozadak;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'und Jehozadak zog mit, als Jehova Juda und Jerusalem durch Nebukadnezar wegführte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Die Söhne Levis: Gersom, Kehath und Merari.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Und dies sind die Namen der Söhne Gersoms: Libni und Simei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Und die Söhne Kehaths: Amram und Jizhar und Hebron und Ussiel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Die Söhne Meraris: Machli und Musi. Und dies sind die Familien der Leviten nach ihren Vätern:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Von Gersom: dessen Sohn Libni, dessen Sohn Jachath, dessen Sohn Simma,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'dessen Sohn Joach, dessen Sohn Iddo, dessen Sohn Serach, dessen Sohn Jeathrai. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Die Söhne Kehaths: dessen Sohn Amminadab, dessen Sohn Korah, dessen Sohn Assir,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'dessen Sohn Elkana, und dessen Sohn Ebjasaph, und dessen Sohn Assir,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'dessen Sohn Tachath, dessen Sohn Uriel, dessen Sohn Ussija, dessen Sohn Saul.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Und die Söhne Elkanas: Amasai und Achimoth;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Elkana, die Söhne Elkanas: dessen Sohn Zophai, dessen Sohn Nachath,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'dessen Sohn Eliab, dessen Sohn Jerocham, dessen Sohn Elkana.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Und die Söhne Samuels: der Erstgeborene Waschni, und Abija. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Die Söhne Meraris: Machli, dessen Sohn Libni, dessen Sohn Simei, dessen Sohn Ussa,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'dessen Sohn Schimea, dessen Sohn Haggija, dessen Sohn Asaja.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Und diese sind es, welche David zur Leitung des Gesanges im Hause Jehovas anstellte, seitdem die Lade einen Ruheplatz hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'und sie verrichteten den Dienst vor der Wohnung des Zeltes der Zusammenkunft beim Gesang, bis Salomo das Haus Jehovas zu Jerusalem gebaut hatte; und sie standen nach ihrer Ordnung ihrem Dienste vor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Und diese sind es, die da standen, und ihre Söhne: Von den Söhnen der Kehathiter: Heman, der Sänger, der Sohn Joels, des Sohnes Samuels,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'des Sohnes Elkanas, des Sohnes Jerochams, des Sohnes Eliels, des Sohnes Toachs,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'des Sohnes Zuphs, des Sohnes Elkanas, des Sohnes Machaths, des Sohnes Amasais,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'des Sohnes Elkanas, des Sohnes Joels, des Sohnes Asarja, des Sohnes Zephanjas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'des Sohnes Tachaths, des Sohnes Assirs, des Sohnes Ebjasaphs, des Sohnes Korahs,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'des Sohnes Jizhars, des Sohnes Kehaths, des Sohnes Levis, des Sohnes Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Und sein Bruder Asaph, der zu seiner Rechten stand: Asaph, der Sohn Berekjas, des Sohnes Schimeas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'des Sohnes Michaels, des Sohnes Baasejas, des Sohnes Malkijas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'des Sohnes Ethnis, des Sohnes Serachs, des Sohnes Adajas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'des Sohnes Ethans, des Sohnes Simmas, des Sohnes Simeis,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'des Sohnes Jachaths, des Sohnes Gersoms, des Sohnes Levis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Und die Söhne Meraris, ihre Brüder, standen zur Linken: Ethan, der Sohn Kischis, des Sohnes Abdis, des Sohnes Malluks,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'des Sohnes Haschabjas, des Sohnes Amazjas, des Sohnes Hilkijas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'des Sohnes Amzis, des Sohnes Banis, des Sohnes Schemers,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'des Sohnes Machlis, des Sohnes Musis, des Sohnes Meraris, des Sohnes Levis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Und ihre Brüder, die Leviten, waren gegeben zu allem Dienst der Wohnung des Hauses Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Und Aaron und seine Söhne räucherten auf dem Brandopferaltar und auf dem Räucheraltar, nach allem Geschäft des Allerheiligsten und um Sühnung zu tun für Israel; nach allem, was Mose, der Knecht Gottes, geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Und dies waren die Söhne Aarons: dessen Sohn Eleasar, dessen Sohn Pinehas, dessen Sohn Abischua,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'dessen Sohn Bukki, dessen Sohn Ussi, dessen Sohn Serachja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'dessen Sohn Merajoth, dessen Sohn Amarja, dessen Sohn Ahitub,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'dessen Sohn Zadok, dessen Sohn Achimaaz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Und dies waren ihre Wohnsitze, nach ihren Gehöften in ihren Grenzen: Den Söhnen Aarons von dem Geschlecht der Kehathiter (denn für sie war das erste Los),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'ihnen gaben sie Hebron im Lande Juda und seine Bezirke rings um dasselbe her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Aber das Feld der Stadt und ihre Dörfer gaben sie Kaleb, dem Sohne Jephunnes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Und sie gaben den Söhnen Aarons die Zufluchtstadt Hebron; und Libna und seine Bezirke, und Jattir, und Estemoa und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'und Hilen und seine Bezirke, Debir und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'und Aschan und seine Bezirke, und Beth-Semes und seine Bezirke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Und vom Stamme Benjamin: Geba und seine Bezirke, und Allemeth und seine Bezirke, und Anathoth und seine Bezirke. Alle ihre Städte: dreizehn Städte nach ihren Familien. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Und den übrigen Söhnen Kehaths gaben sie von dem Geschlecht des Stammes Ephraim und vom Stamme Dan und von der Hälfte des Stammes Manasse durchs Los, zehn Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Und den Söhnen Gersoms, nach ihren Familien: vom Stamme Issaschar und vom Stamme Aser und vom Stamme Naphtali und vom Stamme Manasse in Basan, dreizehn Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Den Söhnen Meraris, nach ihren Familien: vom Stamme Ruben und vom Stamme Gad und vom Stamme Sebulon, durchs Los, zwölf Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Und die Kinder Israel gaben den Leviten die Städte und ihre Bezirke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Und zwar gaben sie durchs Los vom Stamme der Kinder Juda und vom Stamme der Kinder Simeon und vom Stamme der Kinder Benjamin diese Städte, die sie mit Namen nannten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Und die übrigen von den Familien der Söhne Kehaths erhielten die Städte ihres Gebiets vom Stamme Ephraim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Und sie gaben ihnen die Zufluchtstadt Sichem und ihre Bezirke, im Gebirge Ephraim; und Geser und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'und Jokmeam und seine Bezirke, und Beth-Horon und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'und Ajalon und seine Bezirke, und Gath-Rimmon und seine Bezirke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'Und von der Hälfte des Stammes Manasse: Aner und seine Bezirke, und Bileam und seine Bezirke, den Familien der übrigen Söhne Kehaths.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Den Söhnen Gersoms: vom Geschlecht des halben Stammes Manasse: Golan in Basan und seine Bezirke, und Astaroth und seine Bezirke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'und vom Stamme Issaschar: Kedes und seine Bezirke, und Dobrath und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'und Ramoth und seine Bezirke, und Anem und seine Bezirke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'und vom Stamme Aser: Maschal und seine Bezirke, und Abdon und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'und Hukok und seine Bezirke, und Rechob und seine Bezirke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'und vom Stamme Naphtali: Kedes in Galiläa und seine Bezirke, und Hammon und seine Bezirke, und Kirjathaim und seine Bezirke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Den übrigen Söhnen Meraris: vom Stamme Sebulon: Rimmono und seine Bezirke, Tabor und seine Bezirke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'und jenseit des Jordan von Jericho, östlich vom Jordan, vom Stamme Ruben: Bezer in der Wüste und seine Bezirke, und Jahza und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'und Kedemoth und seine Bezirke, und Mephaath und seine Bezirke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'und vom Stamme Gad: Ramoth in Gilead und seine Bezirke, und Machanaim und seine Bezirke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'und Hesbon und seine Bezirke, und Jaser und seine Bezirke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Und die Söhne Issaschars: Tola und Pua, Jaschub und Schimron, vier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Und die Söhne Tolas: Ussi und Rephaja und Jeriel und Jachmai und Jibsam und Samuel, Häupter ihrer Vaterhäuser, von Tola, streitbare Männer, nach ihren Geschlechtern; ihre Zahl war in den Tagen Davids zweiundzwanzigtausend sechshundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Und die Söhne Ussis: Jisrachja; und die Söhne Jisrachjas: Michael und Obadja und Joel, Jissija; insgesamt fünf Häupter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Und bei ihnen waren nach ihren Geschlechtern, nach ihren Vaterhäusern, Kriegsheerscharen, sechsunddreißigtausend Mann; denn sie hatten viele Weiber und Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Und ihre Brüder, nach allen Geschlechtern Issaschars, streitbare Männer, waren siebenundachtzigtausend, die Gesamtzahl der Verzeichneten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Von Benjamin: Bela und Beker und Jediael, drei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Und die Söhne Belas: Ezbon und Ussi und Ussiel und Jerimoth und Iri, fünf, Häupter der Vaterhäuser, streitbare Männer; und sie waren verzeichnet: zweiundzwanzigtausend vierunddreißig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Und die Söhne Bekers: Semira und Joas und Elieser und Eljoenai und Omri und Jeremoth und Abija und Anathoth und Alameth; alle diese waren Söhne Bekers;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'und sie waren verzeichnet nach ihren Geschlechtern, Häupter ihrer Vaterhäuser, streitbare Männer: zwanzigtausend zweihundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Und die Söhne Jediaels: Bilhan; und die Söhne Bilhans: Jeusch und Benjamin und Ehud und Kenaana und Sethan und Tarsis und Achischachar;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'alle diese waren Söhne Jediaels, nach den Häuptern der Väter, streitbare Männer, siebzehntausend zweihundert, die zum Heere auszogen in den Streit. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Und Schuppim und Huppim, die Söhne Irs. Huschim, die Söhne Achers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Die Söhne Naphtalis: Jachziel und Guni und Jezer und Schallum, die Söhne Bilhas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Die Söhne Manasses: Asriel, welchen... gebar; sein syrisches Kebsweib gebar Makir, den Vater Gileads.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Und Makir nahm ein Weib, die Schwester von Huppim und Schuppim; und der Name ihrer Schwester war Maaka. Und der Name des zweiten Sohnes war Zelophchad; und Zelophchad hatte nur Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Und Maaka, das Weib Makirs, gebar einen Sohn, und sie gab ihm den Namen Peresch. Und der Name seines Bruders war Scheresch; und seine Söhne: Ulam und Rekem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Und die Söhne Ulams: Bedan. Das sind die Söhne Gileads, des Sohnes Makirs, des Sohnes Manasses. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Und seine Schwester Hammoleketh gebar Ischhod und Abieser und Machla. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Und die Söhne Schemidas waren Achjan und Sichem und Likchi und Aniam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Und die Söhne Ephraims: Schuthelach; und dessen Sohn Bered, und dessen Sohn Tachath, und dessen Sohn Elada, und dessen Sohn Tachath,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'und dessen Sohn Sabad, und dessen Sohn Schuthelach; und Eser und Elad. Und die Männer von Gath, die Eingeborenen des Landes, erschlugen sie; denn sie waren hinabgezogen, um ihre Herden wegzunehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Und Ephraim, ihr Vater, trauerte viele Tage; und seine Brüder kamen, um ihn zu trösten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Und er ging ein zu seinem Weibe, und sie wurde schwanger und gebar einen Sohn; und er gab ihm den Namen Beria, weil sein Haus im Unglück war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Und seine Tochter war Scheera; und sie baute das untere und das obere Beth-Horon, und Ussen-Scheera.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Und sein Sohn war Rephach und Rescheph; und dessen Sohn Telach, und dessen Sohn Tachan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'dessen Sohn Ladan, dessen Sohn Ammihud, dessen Sohn Elischama,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'dessen Sohn Nun, dessen Sohn Josua. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Und ihr Besitztum und ihre Wohnsitze waren Bethel und seine Tochterstädte, und gegen Sonnenaufgang Naaran, und gegen Sonnenuntergang Geser und seine Tochterstädte, und Sichem und seine Tochterstädte, bis nach Gasa und seinen Tochterstädten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Und in den Händen der Söhne Manasses waren: Beth-Schean und seine Tochterstädte, Taanak und seine Tochterstädte, Megiddo und seine Tochterstädte, Dor und seine Tochterstädte. In diesen wohnten die Kinder Josephs, des Sohnes Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Die Söhne Asers: Jimna und Jischwa und Jischwi und Beria; und Serach war ihre Schwester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Und die Söhne Berias: Heber und Malkiel; er war der Vater Birsawiths.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Und Heber zeugte Japhlet und Schomer und Hotham, und Schua, ihre Schwester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Und die Söhne Japhlets: Pasak und Bimhal und Aschwath. Das sind die Söhne Japhlets.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Und die Söhne Schomers: Achi und Rohga, und Hubba und Aram. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Und die Söhne Helems, seines Bruders: Zophach und Jimna und Schelesch und Amal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Die Söhne Zophachs: Suach und Harnepher und Schual und Beri und Jimra,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Bezer und Hod und Schamma und Schilscha und Jithran und Beera. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Und die Söhne Jethers: Jephunne und Pispa und Ara. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Und die Söhne Ullas: Arach und Hanniel und Rizja.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Alle diese waren Söhne Asers, Häupter der Vaterhäuser, auserlesene, streitbare Männer, Häupter der Fürsten. Und ihre Verzeichneten zum Heeresdienst im Kriege: ihre Zahl war sechsundzwanzigtausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Und Benjamin zeugte Bela, seinen Erstgeborenen, Aschbel, den zweiten, und Achrach, den dritten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Nocha, den vierten, und Rapha, den fünften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Und Bela hatte Söhne: Addar und Gera und Abihud,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'und Abischua und Naaman und Achoach,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'und Gera und Schephuphan und Huram. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Und dies sind die Söhne Echuds: (diese waren die Häupter der Väter der Bewohner von Geba; und man führte sie weg nach Manachath,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'nämlich Naaman und Achija und Gera; dieser führte sie weg) er zeugte Ussa und Achichud. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Und Schacharaim zeugte Söhne im Gefilde Moab, nachdem er Huschim und Baara, seine Weiber, entlassen hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'und er zeugte von Hodesch, seinem Weibe: Jobab und Zibja und Mescha und Malkam,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'und Jeuz und Schobja und Mirma. Das waren seine Söhne, Häupter der Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Und von Huschim zeugte er Abitub und Elpaal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Und die Söhne Elpaals: Heber und Mischeam und Schemer; dieser baute Ono, und Lod und seine Tochterstädte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Und Beria und Schema (diese waren die Häupter der Väter der Bewohner von Ajalon; sie verjagten die Bewohner von Gath)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'und Achjo, Schaschak und Jeremoth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'und Sebadja und Arad und Eder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'und Michael und Jischpa und Jocha waren die Söhne Berias.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Und Sebadja und Meschullam und Hiski und Heber,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'und Jischmerai und Jislia und Jobab waren die Söhne Elpaals. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Und Jakim und Sichri und Sabdi,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'und Elienai und Zillethai und Eliel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'und Adaja und Beraja und Schimrath waren die Söhne Simeis. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Und Jischpan und Heber und Eliel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'und Abdon und Sichri und Hanan,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'und Hananja und Elam und Anthothija,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'und Jiphdeja und Pnuel waren die Söhne Schaschaks. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Und Schamscherai und Schecharja und Athalja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'und Jaareschja und Elia und Sichri waren die Söhne Jerochams.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Diese waren Häupter der Väter nach ihren Geschlechtern, Häupter; diese wohnten zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Und in Gibeon wohnte der Vater Gibeons, und der Name seines Weibes war Maaka.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Und sein erstgeborener Sohn war Abdon, und Zur und Kis und Baal und Nadab,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'und Gedor und Achjo und Seker;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'und Mikloth zeugte Schimea. Und auch diese wohnten ihren Brüdern gegenüber in Jerusalem, bei ihren Brüdern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Und Ner zeugte Kis; und Kis zeugte Saul; und Saul zeugte Jonathan und Malkischua und Abinadab und Esch-Baal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Und der Sohn Jonathans war Merib-Baal; und Merib-Baal zeugte Micha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Und die Söhne Michas waren Pithon und Melek und Tharea und Achas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Und Achas zeugte Jehoadda; und Jehoadda zeugte Alemeth und Asmaweth und Simri; und Simri zeugte Moza,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'und Moza zeugte Binea: dessen Sohn Rapha, dessen Sohn Elasa, dessen Sohn Azel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Und Azel hatte sechs Söhne; und dies sind ihre Namen: Asrikam, Bokru und Ismael und Schearja und Obadja und Hanan. Alle diese waren Söhne Azels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Und die Söhne Escheks, seines Bruders: Ulam, sein Erstgeborener, Jeghusch, der zweite, und Eliphelet, der dritte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Und die Söhne Ulams waren tapfere Kriegsmänner, die den Bogen spannten; und sie hatten viele Söhne und Enkel, hundertfünfzig. Alle diese sind von den Söhnen Benjamins.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Und ganz Israel wurde im Geschlechtsverzeichnis verzeichnet; und siehe, sie sind aufgeschrieben in dem Buche der Könige von Israel. Und Juda wurde wegen seiner Untreue nach Babel weggeführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Und die ersten Bewohner, welche in ihrem Besitztum, in ihren Städten, wohnten, waren: Israel, die Priester, die Leviten und die Nethinim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Und in Jerusalem wohnten von den Söhnen Judas und von den Söhnen Benjamins und von den Söhnen Ephraims und Manasses:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Uthai, der Sohn Ammihuds, des Sohnes Omris, des Sohnes Imris, des Sohnes Banis, von den Söhnen Perez\', des Sohnes Judas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'und von den Schilonitern: Asaja, der Erstgeborene, und seine Söhne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'und von den Söhnen Serachs: Jeghuel und seine Brüder; sechshundertneunzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Und von den Söhnen Benjamins: Sallu, der Sohn Meschullams, des Sohnes Hodawjas, des Sohnes Hassenuas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'und Jibneja, der Sohn Jerochams; und Ela, der Sohn Ussis, des Sohnes Mikris; und Meschullam, der Sohn Schephatjas, des Sohnes Reghuels, des Sohnes Jibnijas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'und ihre Brüder nach ihren Geschlechtern: neunhundertsechsundfünfzig. Alle diese Männer waren Häupter der Väter ihrer Vaterhäuser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Und von den Priestern: Jedaja und Jehojarib und Jakin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'und Asarja, der Sohn Hilkijas, des Sohnes Meschullams, des Sohnes Zadoks, des Sohnes Merajoths, des Sohnes Ahitubs, Oberaufseher des Hauses Gottes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'und Adaja, der Sohn Jerochams, des Sohnes Paschchurs, des Sohnes Malkijas; und Masai, der Sohn Adiels, des Sohnes Jachseras, des Sohnes Meschullams, des Sohnes Meschillemiths, des Sohnes Immers;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'und ihre Brüder, Häupter ihrer Vaterhäuser: tausend siebenhundertsechzig, tüchtige Männer im Werke des Dienstes des Hauses Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Und von den Leviten: Schemaja, der Sohn Haschubs, des Sohnes Asrikams, des Sohnes Haschabjas, von den Söhnen Meraris;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'und Bakbakkar, Heresch und Galal; und Mattanja, der Sohn Michas, des Sohnes Sichris, des Sohnes Asaphs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'und Obadja, der Sohn Schemajas, des Sohnes Gallals, des Sohnes Jeduthuns; und Berekja, der Sohn Asas, des Sohnes Elkanas, der in den Dörfern der Netophathiter wohnte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Und die Torhüter: Schallum und Akkub und Talmon und Achiman, und ihre Brüder; Schallum war das Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Und bis jetzt waren sie im Königstor, gegen Sonnenaufgang. Sie waren die Torhüter der Lager der Söhne Levis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Und Schallum, der Sohn Kores, des Sohnes Ebjasaphs, des Sohnes Korahs, und seine Brüder vom Hause seines Vaters, die Korhiter, waren über das Werk des Dienstes, als Hüter der Schwellen des Zeltes. Und ihre Väter waren über das Lager Jehovas als Hüter des Eingangs gewesen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'und Pinehas, der Sohn Eleasars, war vordem Fürst über sie. Jehova war mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Sekarja, der Sohn Meschelemjas, war Torhüter am Eingang des Zeltes der Zusammenkunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Sie alle, auserlesen zu Torhütern an den Schwellen, waren zweihundertzwölf. Sie wurden in ihren Dörfern verzeichnet; David und Samuel, der Seher, hatten dieselben in ihr Amt eingesetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Und sie und ihre Söhne standen an den Toren des Hauses Jehovas, des Zelthauses, als Wachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Die Torhüter standen nach den vier Winden: gegen Osten, gegen Westen, gegen Norden und gegen Süden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Und ihre Brüder in ihren Dörfern mußten von sieben zu sieben Tagen, von einer Zeit zur anderen, mit jenen kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Denn die vier Vorsteher der Torhüter, sie, die Leviten, waren in Amtspflicht; und sie waren über die Zellen und über die Schätze des Hauses Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Und sie übernachteten rings um das Haus Gottes her; denn ihnen lag die Wache ob, und sie waren über das Öffnen bestellt, und zwar Morgen für Morgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Und einige von ihnen waren über die Geräte des Dienstes; denn nach der Zahl brachten sie sie hinein, und nach der Zahl brachten sie sie heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Und einige von ihnen waren bestellt über die Geräte und über alle Geräte des Heiligtums, und über das Feinmehl und den Wein und das Öl und den Weihrauch und die Gewürze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Und von den Söhnen der Priester mischten einige die Salbenmischung der Gewürze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Und Mattithja, von den Leviten, er war der Erstgeborene Schallums, des Korhiters, war das Pfannenbackwerk anvertraut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Und von den Söhnen der Kehathiter, von ihren Brüdern, waren einige über das Schichtbrot bestellt, um es Sabbath für Sabbath zuzurichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Und das waren die Sänger, die Häupter der Väter der Leviten, welche von anderen Diensten befreit in den Zelten wohnten; denn Tag und Nacht waren sie beschäftigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Das waren die Häupter der Väter der Leviten nach ihren Geschlechtern, die Häupter; diese wohnten zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Und in Gibeon wohnte der Vater Gibeons, Jeghiel; und der Name seines Weibes war Maaka.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Und sein erstgeborener Sohn war Abdon; und Zur und Kis und Baal und Ner und Nadab');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'und Gedor und Achjo und Sekarja und Mikloth;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'und Mikloth zeugte Schimean. Und auch diese wohnten ihren Brüdern gegenüber zu Jerusalem, bei ihren Brüdern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Und Ner zeugte Kis, und Kis zeugte Saul; und Saul zeugte Jonathan und Malkischua und Abinadab und Esch-Baal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Und der Sohn Jonathans war Merib-Baal; und Merib-Baal zeugte Micha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Und die Söhne Michas waren Pithon und Melek und Thachrea.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Und Achas zeugte Jara, und Jara zeugte Alemeth und Asmaweth und Simri; und Simri zeugte Moza,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'und Moza zeugte Binea; und dessen Sohn Rephaja, dessen Sohn Elasa, dessen Sohn Azel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Und Azel hatte sechs Söhne; und dies sind ihre Namen: Asrikam, Bokru und Ismael und Schearja und Obadja und Hanan. Das waren die Söhne Azels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Und die Philister stritten wider Israel; und die Männer von Israel flohen vor den Philistern, und Erschlagene fielen auf dem Gebirge Gilboa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Und die Philister setzten Saul und seinen Söhnen hart nach; und die Philister erschlugen Jonathan und Abinadab und Malkischua, die Söhne Sauls.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Und der Streit wurde heftig wider Saul, und es erreichten ihn die Bogenschützen; und es wurde ihm angst vor den Schützen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Da sprach Saul zu seinem Waffenträger: Ziehe dein Schwert und durchbohre mich damit, daß nicht diese Unbeschnittenen kommen und mich mißhandeln! Sein Waffenträger aber wollte nicht, denn er fürchtete sich sehr. Da nahm Saul das Schwert und stürzte sich darein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Und als sein Waffenträger sah, daß Saul tot war, da stürzte auch er sich in das Schwert und starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'So starben Saul und seine drei Söhne; und sein ganzes Haus starb zugleich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Und als alle Männer von Israel, die im Tale waren, sahen, daß sie geflohen und daß Saul und seine Söhne tot waren, da verließen sie ihre Städte und flohen; und die Philister kamen und wohnten darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Und es geschah am folgenden Tage, da kamen die Philister, um die Erschlagenen auszuziehen; und sie fanden Saul und seine Söhne auf dem Gebirge Gilboa liegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Und sie zogen ihn aus und nahmen seinen Kopf und seine Waffen; und sie sandten in das Land der Philister ringsumher, um die frohe Botschaft ihren Götzen und dem Volke zu verkünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Und sie legten seine Waffen in das Haus ihres Gottes, und seinen Schädel hefteten sie an das Haus Dagons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Als aber ganz Jabes-Gilead alles hörte, was die Philister mit Saul getan hatten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'da machten sich alle tapferen Männer auf und nahmen den Leichnam Sauls und die Leichname seiner Söhne und brachten sie nach Jabes; und sie begruben ihre Gebeine unter der Terebinthe zu Jabes und fasteten sieben Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Und so starb Saul wegen seiner Treulosigkeit, die er wider Jehova begangen, betreffs des Wortes Jehovas, das er nicht beobachtet hatte, und auch weil er eine Totenbeschwörerin aufsuchte, um sie zu befragen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'aber Jehova befragte er nicht. Darum tötete er ihn und wandte das Königtum David, dem Sohne Isais, zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Und ganz Israel versammelte sich zu David nach Hebron, und sie sprachen: Siehe, wir sind dein Gebein und dein Fleisch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Schon früher, schon als Saul König war, bist du es gewesen, der Israel aus-und einführte; und Jehova, dein Gott, hat zu dir gesagt: Du sollst mein Volk Israel weiden, und du sollst Fürst sein über mein Volk Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Und alle Ältesten Israels kamen zu dem König nach Hebron, und David machte einen Bund mit ihnen zu Hebron, vor Jehova; und sie salbten David zum König über Israel, nach dem Worte Jehovas durch Samuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Und David und ganz Israel zogen nach Jerusalem, das ist Jebus; und daselbst waren die Jebusiter, die Bewohner des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Und die Bewohner von Jebus sprachen zu David: Du wirst nicht hier hereinkommen! Aber David nahm die Burg Zion ein, das ist die Stadt Davids.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Und David sprach: Wer die Jebusiter zuerst schlägt, soll Haupt und Oberster werden. Da stieg Joab, der Sohn der Zeruja, zuerst hinauf, und er wurde zum Haupte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Und David wohnte in der Burg; darum nannte man sie Stadt Davids.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Und er baute die Stadt ringsum, von dem Millo an rund umher. Und Joab erneuerte das Übrige der Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Und David wurde immerfort größer, und Jehova der Heerscharen war mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Und dies sind die Häupter der Helden, welche David hatte, die ihm mit ganz Israel mutig beistanden in seinem Königtum, um ihn zum König zu machen, nach dem Worte Jehovas über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Und dies ist die Zahl der Helden, welche David hatte: Jaschobam, der Sohn Hakmonis, das Haupt der Anführer; er schwang seinen Speer wider dreihundert, die er auf einmal erschlug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Und nach ihm Eleasar, der Sohn Dodos, der Achochiter; er war unter den drei Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Er war mit David zu Pas-Dammim, als die Philister daselbst versammelt waren zum Streit. Und dort war ein Ackerstück voll Gerste; und das Volk floh vor den Philistern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Da stellten sie sich mitten auf das Stück und retteten es und schlugen die Philister; und Jehova schaffte eine große Rettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Und drei von den dreißig Häuptern ging zu dem Felsen hinab zu David, in die Höhle Adullam; und das Heer der Philister lagerte im Tale Rephaim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'David aber war damals auf der Bergfeste, und eine Aufstellung der Philister war damals zu Bethlehem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Und David hatte ein Gelüste und sprach: Wer wird mich mit Wasser tränken aus der Zisterne zu Bethlehem, die am Tore ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Da brachen die Drei durch das Lager der Philister und schöpften Wasser aus der Zisterne von Bethlehem, die am Tore ist, und trugen und brachten es zu David. Aber David wollte es nicht trinken und goß es aus als Trankopfer dem Jehova;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'und er sprach: Das lasse mein Gott fern von mir sein, daß ich solches tue! Sollte ich das Blut dieser Männer trinken, die mit Gefahr ihres Lebens hingegangen sind? Denn mit Gefahr ihres Lebens haben sie es gebracht. Und er wollte es nicht trinken. Das taten die drei Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Und Abisai, der Bruder Joabs, dieser war ein Haupt der Drei. Und er schwang seinen Speer wider dreihundert, die er erschlug; und er hatte einen Namen unter den Dreien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Vor den Dreien war er geehrt, neben den Zweien, so daß er ihr Oberster wurde; aber an die ersten Drei reichte er nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja, der Sohn Jojadas, der Sohn eines tapferen Mannes, groß an Taten, von Kabzeel; selbiger erschlug zwei Löwen von Moab. Und er stieg hinab und erschlug den Löwen in der Grube an einem Schneetage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Und er war es, der den ägyptischen Mann erschlug, einen Mann von fünf Ellen Länge. Und der Ägypter hatte einen Speer in der Hand wie einen Weberbaum; er aber ging zu ihm hinab mit einem Stabe, und riß dem Ägypter den Speer aus der Hand und tötete ihn mit seinem eigenen Speere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Das tat Benaja, der Sohn Jojadas; und er hatte einen Namen unter den drei Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Vor den Dreißigen, siehe, war er geehrt, aber an die ersten Drei reichte er nicht. Und David setzte ihn in seinen geheimen Rat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Und die Helden der Heere waren: Asael, der Bruder Joabs; Elchanan, der Sohn Dodos, von Bethlehem;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Schammoth, der Haroriter; Helez, der Peloniter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira, der Sohn Ikkesch\', der Tekoiter; Abieser, der Anathothiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibbekai, der Huschathiter; Ilai, der Achochiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharai, der Netophathiter; Heled, der Sohn Baanas, der Netophathiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ittai, der Sohn Ribais, von Gibea der Kinder Benjamin; Benaja, der Pirhathoniter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Hurai, von den Bächen Gaasch; Abiel, der Arbathiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Asmaweth, der Bacharumiter; Eljachba, der Schaalboniter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Bne-Haschem, der Gisoniter; Jonathan, der Sohn Schages, der Harariter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Achiam, der Sohn Sakars, der Harariter; Eliphal, der Sohn Urs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hepher, der Mekerathiter; Achija, der Peloniter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hezro, der Karmeliter; Naarai, der Sohn Esbais;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, der Bruder Nathans; Mibchar, der Sohn Hagris;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Zelek, der Ammoniter; Nacharai, der Beerothiter, der Waffenträger Joabs, des Sohnes der Zeruja;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira, der Jithriter; Gareb, der Jithriter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Urija, der Hethiter; Sabad, der Sohn Achlais;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, der Sohn Schisas, der Rubeniter, ein Haupt der Rubeniter, und dreißig bei ihm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan, der Sohn Maakas; und Josaphat, der Mithniter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Ussija, der Aschterothiter; Schamma und Jeghiel, die Söhne Hothams, des Aroeriters;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, der Sohn Schimris, und Jocha, sein Bruder, der Thiziter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel, der Machawim; und Jeribai und Joschawja, die Söhne Elnaams; und Jithma, der Moabiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel und Obed, und Jaasiel, der Mezobaiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Und diese sind es, welche zu David nach Ziklag kamen, als er sich noch vor Saul, dem Sohne Kis\', verborgen hielt; auch sie waren unter den Helden, die ihm im Streite halfen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'ausgerüstet mit dem Bogen und geübt, mit der Rechten und mit der Linken Steine zu schleudern und Pfeile mit dem Bogen abzuschießen: Von den Brüdern Sauls, aus Benjamin:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'das Haupt Achieser, und Joas, die Söhne Haschemaas, des Gibeathiters; und Jesiel und Peleth, die Söhne Asmaweths; und Beraka, und Jehu, der Anathothiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'und Jischmaja, der Gibeoniter, ein Held unter den Dreißig und über die Dreißig; und Jeremia und Jachasiel und Jochanan, und Josabad, der Gederathiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Elusai und Jerimoth und Bealja und Schemarja, und Schephatja, der Haruphiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkana und Jischschija und Asarel und Joeser und Jaschobam, die Korhiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'und Joela und Sebadja, die Söhne Jerochams, von Gedor. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Und von den Gaditern sonderten sich ab zu David, nach der Bergfeste in die Wüste, tapfere Helden, Männer des Heeres zum Kriege, mit Schild und Lanze gerüstet, deren Angesichter wie Löwenangesichter, und die den Gazellen auf den Bergen gleich waren an Schnelle:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Eser, das Haupt; Obadja, der zweite; Eliab, der dritte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Mischmanna, der vierte; Jeremia, der fünfte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Attai, der sechste; Eliel, der siebte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Jochanan, der achte; Elsabad, der neunte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jeremia, der zehnte; Makbannai, der elfte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Diese, von den Söhnen Gads, waren Häupter des Heeres; der Kleinste konnte es mit hundert, und der Größte mit tausend aufnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Diese sind es, welche über den Jordan gingen, im ersten Monat, wenn er alle seine Ufer überflutet, und alle Bewohner der Niederungen, gegen Osten und gegen Westen, in die Flucht jagten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Und es kamen einige von den Kindern Benjamin und Juda nach der Bergfeste zu David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Und David ging hinaus, ihnen entgegen, und er hob an und sprach zu ihnen: Wenn ihr zum Frieden zu mir gekommen seid, um mir zu helfen, so wird mein Herz sich mit euch vereinigen; wenn aber, um mich an meine Feinde zu verraten, ohne daß Unrecht in meiner Hand ist, so möge der Gott unserer Väter es sehen und strafen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Da kam der Geist über Amasai, das Haupt der Anführer: Dein sind wir, David, und mit dir, Sohn Isais! Friede, Friede dir und Friede deinen Helfern! denn dein Gott hilft dir! Und David nahm sie auf und setzte sie zu Häuptern von Scharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Und von Manasse liefen einige zu David über, als er mit den Philistern wider Saul in den Streit zog; aber sie halfen ihnen nicht; denn nachdem sie Rat gehalten hatten, entließen ihn die Fürsten der Philister, indem sie sprachen: Auf Gefahr unserer Köpfe könnte er zu seinem Herrn Saul überlaufen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Als er nach Ziklag zog, liefen von Manasse zu ihm über: Adna und Josabad und Jediael und Michael und Josabad und Elihu und Zillethai, Häupter der Tausende von Manasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Und sie halfen David wider die Streifschar, denn tapfere Helden waren sie alle; und sie wurden Oberste im Heere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Denn es kamen von Tag zu Tage zu David, um ihm zu helfen, bis es ein großes Heerlager wurde, wie ein Heerlager Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Und dies sind die Zahlen der Köpfe der zum Heere Gerüsteten, welche zu David nach Hebron kamen, um ihm das Königreich Sauls zuzuwenden nach dem Befehle Jehovas:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Die Kinder Juda, welche Schild und Lanze trugen, sechstausend achthundert zum Heere Gerüstete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Von den Kindern Simeon: streitbare Männer zum Heere, siebentausend einhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Von den Kindern Levi: viertausend sechshundert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'und Jojada, der Fürst von Aaron, und mit ihm dreitausend siebenhundert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'und Zadok, ein Jüngling, ein tapferer Held, und das Haus seines Vaters: zweiundzwanzig Oberste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'Und von den Kindern Benjamin, den Brüdern Sauls: dreitausend; aber der größte Teil von ihnen hielt bis dahin treu zum Hause Sauls.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Und von den Kindern Ephraim: zwanzigtausend achthundert, streitbare Männer, Männer von Namen, nach ihren Vaterhäusern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Und von dem halben Stamme Manasse: achtzehntausend, die mit Namen angegeben wurden, daß sie hingingen, um David zum König zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Und von den Kindern Issaschar: Männer, welche Einsicht hatten in die Zeiten, um zu wissen, was Israel tun mußte; ihre Häupter, zweihundert; und alle ihre Brüder folgten ihrem Befehl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Von Sebulon: die zum Heere auszogen, mit allen Kriegswaffen zum Kampfe bereit, fünfzigtausend, und zwar um sich in Schlachtreihen zu ordnen mit ungeteiltem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Und von Naphtali: tausend Oberste; und mit ihnen siebenunddreißigtausend mit Schild und Speer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Und von den Danitern: achtundzwanzigtausend sechshundert, zum Kampfe bereit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Und von Aser: die zum Heere auszogen, zum Kampfe bereit, vierzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Und von jenseit des Jordan, von den Rubenitern und den Gaditern und dem halben Stamme Manasse: mit allen Waffen eines Kriegsheeres, hundertzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Alle diese Kriegsleute, die sich in Schlachtreihen ordneten, kamen mit ungeteiltem Herzen nach Hebron, um David zum König über ganz Israel zu machen. Und auch alle übrigen in Israel waren eines Herzens, David zum König zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Und sie waren daselbst bei David drei Tage, und aßen und tranken; denn ihre Brüder hatten für sie zugerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Und auch die ihnen nahe wohnten, bis nach Issaschar und Sebulon und Naphtali hin, brachten Lebensmittel auf Eseln und auf Kamelen und auf Maultieren und auf Rindern: Mehlspeisen, Feigenkuchen und Rosinenkuchen, und Wein und Öl, und Rinder und Kleinvieh in Menge; denn es war Freude in Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Und David beriet sich mit den Obersten über tausend und über hundert, mit allen Fürsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Und David sprach zu der ganzen Versammlung Israels: Wenn es euch gut dünkt, und wenn es von Jehova, unserem Gott, ist, so laßt uns allenthalben umhersenden zu unseren übrigen Brüdern in allen Landen Israels, und mit ihnen zu den Priestern und zu den Leviten in den Städten ihrer Bezirke, daß sie sich zu uns versammeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Und wir wollen die Lade unseres Gottes zu uns herüberholen; denn wir haben sie in den Tagen Sauls nicht befragt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Und die ganze Versammlung sprach, daß man also tun sollte; denn die Sache war recht in den Augen des ganzen Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Und David versammelte ganz Israel, von dem Sihor Ägyptens bis nach Hamath hin, um die Lade Gottes von Kirjath-Jearim zu bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Und David und ganz Israel zogen hinauf nach Baala, nach Kirjath-Jearim, das zu Juda gehört, um von dannen die Lade Gottes, Jehovas, heraufzuholen, der zwischen den Cherubim thront, dessen Name dort angerufen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Und sie fuhren die Lade Gottes auf einem neuen Wagen aus dem Hause Abinadabs weg; und Ussa und Achjo führten den Wagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Und David und ganz Israel spielten vor Gott mit aller Kraft: mit Gesängen und mit Lauten und mit Harfen und mit Tamburinen und mit Zimbeln und mit Trompeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Und als sie zur Tenne Kidon kamen, da streckte Ussa seine Hand aus, um die Lade anzufassen; denn die Rinder hatten sich losgerissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Da entbrannte der Zorn Jehovas wider Ussa, und er schlug ihn, darum daß er seine Hand nach der Lade ausgestreckt hatte; und er starb daselbst vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Und David entbrannte, weil Jehova einen Bruch an Ussa gemacht hatte; und er nannte jenen Ort Perez-Ussa, bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Und David fürchtete sich vor Gott an selbigem Tage und sprach: Wie soll ich die Lade Gottes zu mir bringen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Und David ließ die Lade nicht zu sich einkehren in die Stadt Davids; und er ließ sie beiseite bringen in das Haus Obed-Edoms, des Gathiters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Und die Lade Gottes blieb bei der Familie Obed-Edoms, in seinem Hause, drei Monate. Und Jehova segnete das Haus Obed-Edoms und alles was, sein war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Und Hiram, der König von Tyrus, sandte Boten zu David, und Zedernholz und Mauerleute und Zimmerleute, damit sie ihm ein Haus bauten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Und David erkannte, daß Jehova ihn zum König über Israel bestätigt hatte; denn sein Königreich war hoch erhoben um seines Volkes Israel willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Und David nahm noch Weiber in Jerusalem, und David zeugte noch Söhne und Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Und dies sind die Namen derer, welche ihm in Jerusalem geboren wurden: Schammua und Schobab, Nathan und Salomo,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'und Jibchar und Elischua und Elpelet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'und Nogah und Nepheg und Japhija,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'und Elischama und Beeljada und Eliphelet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Und als die Philister hörten, daß David zum König über ganz Israel gesalbt worden war, da zogen alle Philister herauf, um David zu suchen. Und David hörte es und zog ihnen entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Und die Philister kamen und breiteten sich aus im Tale Rephaim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Und David befragte Gott und sprach: Soll ich wider die Philister hinaufziehen, und wirst du sie in meine Hand geben? Und Jehova sprach zu ihm: Ziehe hinauf, und ich werde sie in deine Hand geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Da zogen sie hinauf nach Baal-Perazim, und David schlug sie daselbst; und David sprach: Gott hat meine Feinde durch meine Hand durchbrochen, gleich einem Wasserdurchbruch. Daher gab man jenem Orte den Namen Baal-Perazim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Und sie ließen daselbst ihre Götter; und David gab Befehl, und sie wurden mit Feuer verbrannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Und die Philister zogen wiederum herauf und breiteten sich aus im Tale.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Und David befragte Gott abermals; und Gott sprach zu ihm: Du sollst nicht hinaufziehen ihnen nach; wende dich von ihnen ab, daß du an sie kommst, den Bakabäumen gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Und sobald du das Geräusch eines Daherschreitens in den Wipfeln der Bakabäume hörst, alsdann sollst du zum Angriff schreiten; denn Gott ist vor dir ausgezogen, um das Heerlager der Philister zu schlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Und David tat, so wie Gott ihm geboten hatte; und sie schlugen das Heerlager der Philister von Gibeon bis nach Geser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Und der Name Davids ging aus in alle Länder, und Jehova legte die Furcht vor ihm auf alle Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Und er machte sich Häuser in der Stadt Davids, und er bereitete einen Ort für die Lade Gottes und schlug ein Zelt für sie auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Damals sprach David: Die Lade Gottes soll niemand tragen als nur die Leviten; denn sie hat Jehova erwählt, um die Lade Gottes zu tragen und seinen Dienst zu verrichten ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Und David versammelte ganz Israel nach Jerusalem, um die Lade Jehovas an ihren Ort hinaufzubringen, den er für sie bereitet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Und David versammelte die Söhne Aarons und die Leviten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Von den Söhnen Kehaths: Uriel, den Obersten, und seine Brüder, hundertzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'von den Söhnen Meraris: Asaja, den Obersten, und seine Brüder, zweihundertzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'von den Söhnen Gersoms: Joel, den Obersten, und seine Brüder, hundertdreißig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'von den Söhnen Elizaphans: Schemaja, den Obersten, und seine Brüder, zweihundert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'von den Söhnen Hebrons: Eliel, den Obersten, und seine Brüder, achtzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'von den Söhnen Ussiels: Amminadab, den Obersten, und seine Brüder, hundertzwölf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Und David berief Zadok und Abjathar, die Priester, und die Leviten Uriel, Asaja und Joel, Schemaja und Eliel und Amminadab,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'und er sprach zu ihnen: Ihr seid die Häupter der Väter der Leviten; heiliget euch, ihr und eure Brüder, und bringet die Lade Jehovas, des Gottes Israels, hinauf an den Ort, welchen ich für sie bereitet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Denn weil ihr das vorige Mal es nicht tatet, so machte Jehova, unser Gott, einen Bruch unter uns, weil wir ihn nicht suchten nach der Vorschrift.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Da heiligten sich die Priester und die Leviten, um die Lade Jehovas, des Gottes Israels, hinaufzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Und die Söhne der Leviten trugen die Lade Gottes auf ihren Schultern, indem sie die Stangen auf sich legten, so wie Mose geboten hatte nach dem Worte Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Und David befahl den Obersten der Leviten, ihre Brüder, die Sänger, mit Musikinstrumenten, Harfen und Lauten und Zimbeln zu bestellen, damit sie laut spielten, indem sie die Stimme erhöben mit Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Und die Leviten bestellten Heman, den Sohn Joels, und von seinen Brüdern Asaph, den Sohn Berekjas; und von den Söhnen Meraris, ihren Brüdern, Ethan, den Sohn Kuschajas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'und mit ihnen ihre Brüder zweiten Ranges: Sekarja, Ben und Jaasiel und Schemiramoth und Jechiel und Unni, Eliab und Benaja und Maaseja und Mattithja und Elipheleh und Mikneja und Obed-Edom und Jeghiel, die Torhüter; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'und zwar die Sänger Heman, Asaph und Ethan, mit ehernen Zimbeln, um laut zu spielen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'und Sekarja und Asiel und Schemiramoth und Jechiel und Unni und Eliab und Maaseja und Benaja mit Harfen auf Alamoth;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'und Mattithja und Elipheleh und Mikneja und Obed-Edom und Jeghiel und Asasja mit Lauten auf Scheminith: um den Gesang zu leiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Und Kenanja war der Anführer der Leviten im Gesang; er unterwies im Gesang, denn er war kundig darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Und Berekja und Elkana waren Torhüter der Lade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Und Schebanja und Josaphat und Nethaneel und Amasai und Sekarja und Benaja und Elieser, die Priester, schmetterten mit den Trompeten vor der Lade Gottes her. Und Obed-Edom und Jechija waren Torhüter der Lade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Und so zogen David und die Ältesten von Israel und die Obersten über tausend hin, um die Lade des Bundes Jehovas aus dem Hause Obed-Edoms heraufzuholen mit Freuden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Und es geschah, da Gott den Leviten half, welche die Lade des Bundes Jehovas trugen, so opferten sie sieben Farren und sieben Widder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Und David war angetan mit einem Oberkleide von Byssus, ebenso alle Leviten, welche die Lade trugen, und die Sänger und Kenanja, der Anführer des Gesanges der Sänger; und David trug ein leinenes Ephod.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Und ganz Israel brachte die Lade des Bundes Jehovas hinauf mit Jauchzen und mit Posaunenschall und mit Trompeten und mit Zimbeln, laut spielend mit Harfen und Lauten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Und es geschah, als die Lade des Bundes Jehovas in die Stadt Davids kam, da schaute Michal, die Tochter Sauls, durchs Fenster; und sie sah den König David hüpfen und spielen, und sie verachtete ihn in ihrem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Und sie brachten die Lade Gottes hinein, und stellten sie innerhalb des Zeltes, das David für sie aufgeschlagen hatte. Und sie brachten Brandopfer und Friedensopfer dar vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Und als David das Opfern der Brandopfer und der Friedensopfer beendigt hatte, segnete er das Volk im Namen Jehovas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'und er verteilte an ganz Israel, vom Manne bis zum Weibe, an jeden einen Laib Brot und einen Trunk Wein und einen Rosinenkuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Und er bestellte vor die Lade Jehovas einige von den Leviten als Diener, daß sie Jehovas, des Gottes Israels, gedächten und ihn priesen und rühmten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asaph, das Haupt, und Sekarja, den zweiten nach ihm, Jeghiel und Schemiramoth und Jeghiel und Mattithja und Eliab und Benaja und Obed-Edom und Jeghiel, mit Harfinstrumenten und mit Lauten; und Asaph ließ die Zimbeln erklingen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'und Benaja und Jachasiel, die Priester, waren beständig mit Trompeten vor der Lade des Bundes Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Damals, an jenem Tage, trug David zum ersten Male Asaph und seinen Brüdern auf, Jehova zu preisen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Preiset Jehova, rufet seinen Namen an, machet kund unter den Völkern seine Taten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Singet ihm, singet ihm Psalmen; sinnet über alle seine Wunderwerke!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Rühmet euch seines heiligen Namens! Es freue sich das Herz derer, die Jehova suchen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Trachtet nach Jehova und seiner Stärke, suchet sein Angesicht beständig!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Gedenket seiner Wunderwerke, die er getan hat, seiner Wunderzeichen und der Gerichte seines Mundes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Du Same Israels, sein Knecht, ihr Söhne Jakobs, seine Auserwählten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Er, Jehova, ist unser Gott; seine Gerichte sind auf der ganzen Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Gedenket ewiglich seines Bundes, des Wortes, das er geboten hat, auf tausend Geschlechter hin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'den er gemacht hat mit Abraham, und seines Eides, den er Isaak geschworen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Und er stellte ihn Jakob zur Satzung, Israel zum ewigen Bunde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'indem er sprach: Dir will ich das Land Kanaan geben als Schnur eures Erbteils;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'als ihr ein zählbares Häuflein waret, gar wenige und Fremdlinge darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Und sie wanderten von Nation zu Nation und von einem Reiche zu einem anderen Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Er ließ niemand zu, sie zu bedrücken, und ihretwegen strafte er Könige:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, '\"Tastet meine Gesalbten nicht an, und meinen Propheten tut nichts Übles!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Singet Jehova, ganze Erde! Verkündet von Tag zu Tag seine Rettung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Erzählet unter den Nationen seine Herrlichkeit, unter allen Völkern seine Wundertaten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Denn groß ist Jehova und sehr zu loben, und furchtbar ist er über alle Götter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Denn alle Götter der Völker sind Nichtigkeiten, aber Jehova hat die Himmel gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Majestät und Pracht sind vor seinem Angesicht, Stärke und Freude in seiner Wohnstätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Gebet Jehova, ihr Völkerstämme, gebet Jehova Herrlichkeit und Stärke!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Gebet Jehova die Herrlichkeit seines Namens; bringet eine Opfergabe und kommet vor sein Angesicht; betet Jehova an in heiliger Pracht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Erzittert vor ihm, ganze Erde! Auch steht der Erdkreis fest, er wird nicht wanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Es freue sich der Himmel, und es frohlocke die Erde! Und man spreche unter den Nationen: Jehova regiert!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Es brause das Meer und seine Fülle! Es frohlocke das Gefilde und alles, was darauf ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Dann werden jubeln die Bäume des Waldes vor Jehova; denn er kommt, die Erde zu richten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Preiset Jehova, denn er ist gütig, denn seine Güte währt ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Und sprechet: Rette uns, Gott unserer Rettung, und sammle und befreie uns aus den Nationen; daß wir deinen heiligen Namen preisen, daß wir uns rühmen deines Lobes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Gepriesen sei Jehova, der Gott Israels, von Ewigkeit zu Ewigkeit! Und alles Volk sprach: Amen! und lobte Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Und David ließ daselbst, vor der Lade des Bundes Jehovas, Asaph und seine Brüder, um beständig vor der Lade zu dienen nach der täglichen Gebühr;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'und Obed-Edom und seine Brüder, achtundsechzig; und Obed-Edom, den Sohn Jeduthuns, und Hosa, als Torhüter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Zadok, den Priester aber, und seine Brüder, die Priester, ließ er vor der Wohnung Jehovas, auf der Höhe, die zu Gibeon ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'um Jehova Brandopfer zu opfern auf dem Brandopferaltar beständig, des Morgens und des Abends, und zwar nach allem, was in dem Gesetz Jehovas geschrieben steht, das er Israel geboten hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'und mit ihnen Heman und Jeduthun und die übrigen Auserlesenen, welche mit Namen angegeben waren, um Jehova zu preisen, daß seine Güte ewiglich währt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'und mit ihnen, mit Heman und Jeduthun, waren Trompeten und Zimbeln für die, welche laut spielten, und die Musikinstrumente Gottes; und die Söhne Jeduthuns waren für das Tor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Und das ganze Volk ging hin, ein jeder nach seinem Hause; und David wandte sich, um sein Haus zu segnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Und es geschah, als David in seinem Hause wohnte, da sprach David zu Nathan, dem Propheten: Siehe, ich wohne in einem Hause von Zedern, und die Lade des Bundes Jehovas wohnt unter Teppichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Und Nathan sprach zu David: Tue alles, was du im Herzen hast, denn Gott ist mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Und es geschah in selbiger Nacht, da geschah das Wort Gottes zu Nathan also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Gehe hin und sprich zu David, meinem Knechte: So spricht Jehova: Nicht du sollst mir das Haus zur Wohnung bauen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'denn ich habe nicht in einem Hause gewohnt von dem Tage an, da ich Israel heraufgeführt habe, bis auf diesen Tag; sondern ich wanderte von Zelt zu Zelt und von Wohnung zu Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Wo immer ich wanderte unter ganz Israel, habe ich zu einem der Richter Israels, dem ich gebot, mein Volk zu weiden, ein Wort geredet und gesagt: Warum habt ihr mir nicht ein Haus von Zedern gebaut?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Und nun sollst du also zu meinem Knechte David sagen: So spricht Jehova der Heerscharen: Ich habe dich von der Trift genommen, hinter dem Kleinvieh weg, daß du Fürst sein solltest über mein Volk Israel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'und ich bin mit dir gewesen überall, wohin du gegangen bist, und habe alle deine Feinde vor dir ausgerottet; und ich habe dir einen Namen gemacht, gleich dem Namen der Großen, die auf Erden sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Und ich werde einen Ort setzen für mein Volk Israel und werde es pflanzen, daß es an seiner Stätte wohne und nicht mehr beunruhigt werde; und die Söhne der Ungerechtigkeit sollen es nicht mehr aufreiben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'wie früher und seit den Tagen, da ich Richter über mein Volk Israel bestellt habe. Und ich werde alle deine Feinde demütigen; und ich tue dir kund, daß Jehova dir ein Haus bauen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Und es wird geschehen, wenn deine Tage voll sind, daß du zu deinen Vätern hingehst, so werde ich deinen Samen nach dir erwecken, der von deinen Söhnen sein wird, und werde sein Königtum befestigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Der wird mir ein Haus bauen; und ich werde seinen Thron befestigen auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Ich will ihm Vater sein, und er soll mir Sohn sein; und ich will meine Güte nicht von ihm weichen lassen, wie ich sie von dem weichen ließ, der vor dir war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Und ich will ihm Bestand geben in meinem Hause und in meinem Königreich auf ewig; und sein Thron soll fest sein auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Nach allen diesen Worten und nach diesem ganzen Gesicht, also redete Nathan zu David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Da ging der König David hinein und setzte sich vor Jehova nieder und sprach: Wer bin ich, Jehova Gott, und was ist mein Haus, daß du mich bis hierher gebracht hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Und dies ist noch ein Geringes gewesen in deinen Augen, o Gott! Und du hast auch von dem Hause deines Knechtes geredet in die Ferne hin; und du hast mich angesehen nach der Weise eines hochgestellten Menschen, Jehova Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Was soll David noch weiter zu dir reden von der Ehre an deinem Knechte? Du kennst ja deinen Knecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Jehova, um deines Knechtes willen und nach deinem Herzen hast du all dieses Große getan, um alle diese großen Dinge kundzutun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Jehova, niemand ist dir gleich, und kein Gott außer dir, nach allem, was wir mit unseren Ohren gehört haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Und wer ist wie dein Volk Israel, die einzige Nation auf Erden, welche Gott hingegangen ist, sich zum Volke zu erlösen, um dir einen Namen zu machen, große und furchtbare Dinge zu tun, indem du vor deinem Volke, das du aus Ägypten erlöst hast, Nationen vertriebst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Und du hast dir dein Volk Israel zum Volke bestimmt auf ewig; und du, Jehova, bist ihr Gott geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Und nun, Jehova, das Wort, das du über deinen Knecht und über sein Haus geredet hast, möge sich bewähren ewiglich; und tue, wie du geredet hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Ja, es möge sich bewähren! und dein Name sei groß auf ewig, daß man spreche: Jehova der Heerscharen, der Gott Israels, ist Gott für Israel! Und das Haus deines Knechtes David sei fest vor dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Denn du, mein Gott, hast dem Ohre deines Knechtes eröffnet, daß du ihm ein Haus bauen willst; darum hat dein Knecht sich ein Herz gefaßt, vor dir zu beten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Und nun, Jehova, du bist es, der da Gott ist, und du hast dieses Gute zu deinem Knechte geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Und nun, es hat dir gefallen, das Haus deines Knechtes zu segnen, daß es ewiglich vor dir sei; denn du, Jehova, hast es gesegnet, und es wird gesegnet sein ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Und es geschah hernach, da schlug David die Philister und demütigte sie; und er nahm Gath und seine Tochterstädte aus der Hand der Philister.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Und er schlug die Moabiter; und die Moabiter wurden David zu Knechten, welche Geschenke brachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Und David schlug Hadareser, den König von Zoba, bei Hamath, als er hinzog, um seine Macht am Strome Phrat zu befestigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Und David nahm von ihm gefangen tausend Wagen und siebentausend Reiter und zwanzigtausend Mann Fußvolk; und David lähmte alle Gespanne und ließ hundert Gespanne von ihm übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Und die Syrer von Damaskus kamen, um Hadareser, dem König von Zoba, zu helfen; und David erschlug unter den Syrern zweiundzwanzigtausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Und David legte Besatzungen in das damascenische Syrien; und die Syrer wurden David zu Knechten, welche Geschenke brachten. Und Jehova half David überall, wohin er zog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Und David nahm die goldenen Schilde, welche den Knechten Hadaresers gehörten, und brachte sie nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Und aus Tibchad und aus Kun, den Städten Hadaresers, nahm David Erz in großer Menge; davon machte Salomo das eherne Meer und die Säulen und die ehernen Geräte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Und als Tou, der König von Hamath, hörte, daß David die ganze Heeresmacht Hadaresers, des Königs von Zoba, geschlagen hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'da sandte er Hadoram, seinen Sohn, zu dem König David, um ihn nach seinem Wohlergehen zu fragen und ihn zu beglückwünschen, darum daß er wider Hadareser gestritten und ihn geschlagen hatte; denn Hadareser war stets im Kriege mit Tou; und er sandte allerlei Geräte von Gold und von Silber und von Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Auch diese heiligte der König David dem Jehova, samt dem Silber und dem Golde, das er von all den Nationen genommen hatte: von den Edomitern und von den Moabitern und von den Kindern Ammon und von den Philistern und von den Amalekitern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Und Abisai, der Sohn der Zeruja, schlug die Edomiter im Salztal, achtzehntausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Und er legte Besatzungen in Edom, und alle Edomiter wurden David zu Knechten. Und Jehova half David überall, wohin er zog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Und David regierte über ganz Israel; und er übte Recht und Gerechtigkeit an seinem ganzen Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Und Joab, der Sohn der Zeruja, war über das Heer; und Josaphat, der Sohn Ahiluds, war Geschichtsschreiber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'und Zadok, der Sohn Ahitubs, und Ahimelech, der Sohn Abjathars, waren Priester; und Schawscha war Schreiber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'und Benaja, der Sohn Jojadas, war über die Kerethiter und die Pelethiter; und die Söhne Davids waren die ersten zur Seite des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Und es geschah hernach, da starb Nahas, der König der Kinder Ammon; und sein Sohn ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Und David sprach: Ich will Güte erweisen an Hanun, dem Sohne Nahas\', denn sein Vater hat Güte an mir erwiesen. Und David sandte Boten, um ihn wegen seines Vaters zu trösten. Und die Knechte Davids kamen in das Land der Kinder Ammon zu Hanun, um ihn zu trösten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Da sprachen die Fürsten der Kinder Ammon zu Hanun: Ehrt wohl David deinen Vater in deinen Augen, daß er Tröster zu dir gesandt hat? Sind nicht seine Knechte zu dir gekommen, um das Land zu erforschen und es umzukehren und auszukundschaften?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Da nahm Hanun die Knechte Davids und ließ sie scheren, und ihre Oberkleider zur Hälfte abschneiden bis ans Gesäß; und er entließ sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Und man ging und berichtete David wegen der Männer. Da sandte er ihnen entgegen, denn die Männer schämten sich sehr; und der König ließ ihnen sagen: Bleibet in Jericho, bis euer Bart gewachsen ist, dann kommet zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Als nun die Kinder Ammon sahen, daß sie sich bei David stinkend gemacht hatten, da sandten Hanun und die Kinder Ammon tausend Talente Silber, um sich aus Mesopotamien und aus Aram-Maaka und aus Zoba Wagen und Reiter zu dingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Und sie dingten sich zweiunddreißigtausend Wagen, und den König von Maaka mit seinem Volke; und sie kamen und lagerten sich vor Medeba. Und die Kinder Ammon versammelten sich aus ihren Städten und kamen zum Streit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Und als David es hörte, sandte er Joab hin und das ganze Heer, die Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Und die Kinder Ammon zogen aus und stellten sich am Eingang der Stadt in Schlachtordnungen auf; und die Könige, die gekommen waren, waren für sich auf dem Felde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Und als Joab sah, daß der Streit von vorn und von hinten gegen ihn gerichtet war, da erwählte er von allen Auserlesenen Israels und stellte sich auf, den Syrern gegenüber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'und das übrige Volk übergab er der Hand seines Bruders Abisai, und sie stellten sich auf, den Kindern Ammon gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Und er sprach: Wenn die Syrer mir zu stark sind, so sollst du mir Hilfe leisten; und wenn die Kinder Ammon dir zu stark sind, so will ich dir helfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Sei stark und laß uns stark sein für unser Volk und für die Städte unseres Gottes! Und Jehova wird tun, was gut ist in seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Da rückte Joab und das Volk, das bei ihm war, vor, den Syrern entgegen zum Streit; und sie flohen vor ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Und als die Kinder Ammon sahen, daß die Syrer geflohen waren, da flohen auch sie vor seinem Bruder Abisai und zogen sich in die Stadt zurück. Und Joab kam nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Und als die Syrer sahen, daß sie vor Israel geschlagen waren, da sandten sie Boten hin und ließen die Syrer ausziehen, die jenseit des Stromes waren; und Schophak, der Heeroberste Hadaresers, zog vor ihnen her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Und es wurde David berichtet; da versammelte er ganz Israel und ging über den Jordan und kam wider sie; und er stellte sich wider sie auf. Und David stellte sich in Schlachtordnung auf, den Syrern gegenüber; und sie stritten mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Und die Syrer flohen vor Israel, und David tötete von den Syrern siebentausend Wagenkämpfer und vierzigtausend Mann Fußvolk; auch Schophak, den Heerobersten, tötete er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Und als die Knechte Hadaresers sahen, daß sie vor Israel geschlagen waren, da machten sie Frieden mit David und dienten ihm. Und die Syrer wollten den Kindern Ammon nicht mehr helfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Und es geschah zur Zeit der Rückkehr des Jahres, zur Zeit wann die Könige ausziehen, da führte Joab die Heeresmacht ins Feld und verheerte das Land der Kinder Ammon; und er kam und belagerte Rabba. David aber blieb in Jerusalem. Und Joab schlug Rabba und riß es nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Und David nahm die Krone ihres Königs von seinem Haupte; und er fand sie ein Talent Gold an Gewicht, und Edelsteine waren daran; und sie kam auf das Haupt Davids. Und die Beute der Stadt brachte er hinaus in großer Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Und das Volk, das darin war, führte er hinaus und zerschnitt sie mit der Säge und mit eisernen Dreschwagen und mit Sägen. Und also tat David allen Städten der Kinder Ammon. Und David und das ganze Volk kehrten nach Jerusalem zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Und es geschah hernach, da entstand ein Streit mit den Philistern zu Geser. Damals erschlug Sibbekai, der Huschathiter, den Sippai, einen von den Söhnen des Rapha; und sie wurden gedemütigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Und wiederum entstand ein Streit mit den Philistern. Und Elchanan, der Sohn Jairs, erschlug Lachmi, den Bruder Goliaths, des Gathiters; und der Schaft seines Speeres war wie ein Weberbaum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Und wiederum entstand ein Streit zu Gath. Da war ein Mann von großer Länge, und er hatte je sechs Finger und Zehen, zusammen vierundzwanzig; und auch er war dem Rapha geboren worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Und er höhnte Israel; und Jonathan, der Sohn Schimeas, des Bruders Davids, erschlug ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Diese wurden dem Rapha zu Gath geboren; und sie fielen durch die Hand Davids und durch die Hand seiner Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Und Satan stand auf wider Israel und reizte David an, Israel zu zählen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Da sprach David zu Joab und zu den Obersten des Volkes: Gehet hin, zählet Israel von Beerseba bis Dan; und berichtet mir, damit ich ihre Zahl wisse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Und Joab sprach: Es möge Jehova zu seinem Volke, so viele ihrer sind, hundertmal hinzufügen! Sind sie nicht alle, mein Herr König, die Knechte meines Herrn? Warum begehrt mein Herr solches? Warum soll es Israel zur Schuld werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Aber das Wort des Königs blieb fest gegen Joab. Und Joab zog aus und durchwanderte ganz Israel, und er kam nach Jerusalem zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Und Joab gab die Zahl des gemusterten Volkes David an; und es waren in ganz Israel elfhunderttausend Mann, die das Schwert zogen, und in Juda vierhundertsiebzigtausend Mann, die das Schwert zogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Levi aber und Benjamin musterte er nicht unter ihnen; denn das Wort des Königs war Joab ein Greuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Und diese Sache war übel in den Augen Gottes, und er schlug Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Und David sprach zu Gott: Ich habe sehr gesündigt, daß ich diese Sache getan habe; und nun laß doch die Ungerechtigkeit deines Knechtes vorübergehen, denn ich habe sehr töricht gehandelt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Und Jehova redete zu Gad, dem Seher Davids, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Gehe hin und rede zu David und sprich: So spricht Jehova: Dreierlei lege ich dir vor; wähle dir eines davon, daß ich es dir tue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Und Gad kam zu David und sprach zu ihm:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'So spricht Jehova: Wähle dir! Entweder drei Jahre Hungersnot; oder drei Monate dahingerafft zu werden vor deinen Bedrängern, und daß das Schwert deiner Feinde dich treffe; oder drei Tage das Schwert Jehovas und Pest im Lande, und daß der Engel Jehovas verderbe in allen Grenzen Israels. Und nun siehe zu, was für eine Antwort ich dem zurückbringen soll, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Und David sprach zu Gad: Mir ist sehr angst! Möge ich doch in die Hand Jehovas fallen, denn seine Erbarmungen sind sehr groß; aber in die Hand der Menschen laß mich nicht fallen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Und Jehova sandte eine Pest unter Israel; und es fielen von Israel siebzigtausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Und Jehova sandte den Engel nach Jerusalem, um es zu verderben. Und als er verderbte, sah es Jehova, und es reute ihn des Übels; und er sprach zu dem Engel, welcher verderbte: Genug! Ziehe jetzt deine Hand ab. Der Engel Jehovas stand aber bei der Tenne Ornans, des Jebusiters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Und als David seine Augen erhob, sah er den Engel Jehovas zwischen der Erde und dem Himmel stehen, sein Schwert gezückt in seiner Hand, ausgestreckt über Jerusalem. Da fielen David und die Ältesten, in Sacktuch gehüllt, auf ihr Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Und David sprach zu Gott: Bin ich es nicht, der gesagt hat, das Volk zu zählen? Und ich bin es, der gesündigt und sehr übel gehandelt hat; aber diese Schafe, was haben sie getan? Jehova, mein Gott, es sei doch deine Hand wider mich und wider das Haus meines Vaters, aber nicht wider dein Volk zur Plage!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Und der Engel Jehovas sprach zu Gad, daß er zu David sage, David solle hinaufgehen, um Jehova einen Altar zu errichten auf der Tenne Ornans, des Jebusiters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Und David ging hinauf, nach dem Worte Gads, das er im Namen Jehovas geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Und Ornan wandte sich um und sah den Engel; und seine vier Söhne versteckten sich mit ihm. Ornan aber drosch Weizen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Und David kam zu Ornan; und Ornan blickte hin und sah David, und er ging aus der Tenne hinaus und beugte sich vor David nieder, mit dem Antlitz zur Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Und David sprach zu Ornan: Gib mir den Platz der Tenne, daß ich Jehova einen Altar darauf baue, um volles Geld gib ihn mir, daß die Plage von dem Volke abgewehrt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Da sprach Ornan zu David: Nimm ihn dir, und mein Herr, der König, tue, was gut ist in seinen Augen; siehe, ich gebe die Rinder zu den Brandopfern, und die Dreschwagen zum Holz, und den Weizen zum Speisopfer: alles das gebe ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Aber der König David sprach zu Ornan: Nein, sondern kaufen will ich es um volles Geld; denn ich will nicht, was dir gehört, für Jehova nehmen und umsonst Brandopfer opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Und David gab Ornan für den Platz sechshundert Sekel Gold an Gewicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Und David baute daselbst Jehova einen Altar und opferte Brandopfer und Friedensopfer; und er rief zu Jehova, und er antwortete ihm mit Feuer vom Himmel auf dem Altar des Brandopfers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Und Jehova sprach zu dem Engel, und er steckte sein Schwert wieder in seine Scheide.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Zu jener Zeit, als David sah, daß Jehova ihm auf der Tenne Ornans, des Jebusiters, geantwortet hatte, opferte er daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Die Wohnung Jehovas aber, die Mose in der Wüste gemacht hatte, und der Brandopferaltar waren zu jener Zeit auf der Höhe zu Gibeon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Aber David vermochte nicht vor denselben hinzugehen, um Gott zu suchen; denn er war erschrocken vor dem Schwerte des Engels Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Und David sprach: Dieses hier soll das Haus Jehovas Gottes sein, und dies der Altar zum Brandopfer für Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Und David befahl, daß man die Fremdlinge versammeln solle, die im Lande Israel waren; und er stellte sie an als Steinhauer, um Quadersteine für den Bau des Hauses Gottes zu hauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Und David bereitete Eisen in Menge für die Nägel zu den Torflügeln und für die Klammern; und Erz in Menge, es war nicht zu wägen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'und Zedernholz ohne Zahl; denn die Zidonier und die Tyrer brachten Zedernholz in Menge zu David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Und David sprach: Salomo, mein Sohn, ist noch jung und zart; und das Haus, das dem Jehova zu erbauen ist, soll überaus groß werden, zum Namen und zum Ruhm in allen Ländern: so will ich denn das Nötige für ihn bereiten. Und so bereitete David Vorrat in Menge vor seinem Tode.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Und er rief seinen Sohn Salomo und gebot ihm, Jehova, dem Gott Israels, ein Haus zu bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Und David sprach zu Salomo: Mein Sohn! Ich selbst hatte in meinem Herzen, dem Namen Jehovas, meines Gottes, ein Haus zu bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Aber das Wort Jehovas geschah zu mir, indem er sprach: Du hast Blut in Menge vergossen und große Kriege geführt; du sollst meinem Namen kein Haus bauen, denn viel Blut hast du vor mir zur Erde vergossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Siehe, ein Sohn wird dir geboren werden, der wird ein Mann der Ruhe sein, und ich werde ihm Ruhe schaffen vor allen seinen Feinden ringsum. Denn Salomo wird sein Name sein, und Frieden und Ruhe werde ich Israel geben in seinen Tagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Der wird meinem Namen ein Haus bauen; und er soll mir Sohn, und ich will ihm Vater sein; und ich werde den Thron seines Königtums über Israel befestigen auf ewig. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Nun, mein Sohn, Jehova sei mit dir, daß es dir gelinge, und das Haus Jehovas, deines Gottes, bauest, so wie er von dir geredet hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Nur gebe dir Jehova Einsicht und Verstand, und er bestelle dich über Israel, und zwar um das Gesetz Jehovas, deines Gottes, zu beobachten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Dann wird es dir gelingen, wenn du darauf achtest, die Satzungen und die Rechte zu tun, welche Jehova dem Mose für Israel geboten hat. Sei stark und mutig, fürchte dich nicht und erschrick nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Und siehe, in meiner Mühsal habe ich für das Haus Jehovas hunderttausend Talente Gold und tausendmal tausend Talente Silber bereitet; und das Erz und das Eisen ist nicht zu wägen, denn es ist in Menge vorhanden; auch Holz und Steine habe ich bereitet, und du wirst noch mehr hinzufügen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Und Werkleute sind bei dir in Menge: Steinhauer und Arbeiter in Stein und Holz, und allerlei Verständige in allerlei Arbeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'das Gold, das Silber und das Erz und das Eisen ist nicht zu zählen. Mache dich auf und handle; und Jehova sei mit dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Und David gebot allen Obersten Israels, seinem Sohne Salomo beizustehen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Ist nicht Jehova, euer Gott, mit euch, und hat er euch nicht Ruhe geschafft ringsumher? Denn er hat die Bewohner des Landes in meine Hand gegeben, und das Land ist unterjocht vor Jehova und vor seinem Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Richtet nun euer Herz und eure Seele darauf, Jehova, euren Gott, zu suchen; und machet euch auf und bauet das Heiligtum Jehovas Gottes, daß ihr die Lade des Bundes Jehovas und die Geräte des Heiligtums Gottes in das Haus bringet, welches dem Namen Jehovas gebaut werden soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Und David war alt und der Tage satt; und er machte Salomo, seinen Sohn, zum König über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Und er versammelte alle Obersten Israels und die Priester und die Leviten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Und die Leviten wurden gezählt von dreißig Jahren an und darüber; und ihre Zahl war, Kopf für Kopf, an Männern achtunddreißigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Von diesen, sprach David, sollen vierundzwanzigtausend die Aufsicht über das Werk des Hauses Jehovas führen; und sechstausend sollen Vorsteher und Richter sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'und viertausend Torhüter; und viertausend, welche Jehova loben mit den Instrumenten, die ich gemacht habe, um zu loben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Und David teilte sie in Abteilungen, nach den Söhnen Levis, nach Gerson, Kehath und Merari.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Von den Gersonitern: Ladan und Simei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Die Söhne Ladans: das Haupt, Jechiel, und Setham und Joel, drei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Die Söhne Simeis: Schelomith und Hasiel und Haran, drei. Diese waren die Häupter der Väter von Ladan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Und die Söhne Simeis: Jachath, Sina und Jeghusch und Beria; das waren die Söhne Simeis, vier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Und Jachath war das Haupt, und Sina der zweite; und Jeghusch und Beria hatten nicht viele Söhne, und so bildeten sie ein Vaterhaus, eine Zählung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Die Söhne Kehaths: Amram, Jizhar, Hebron und Ussiel, vier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Die Söhne Amrams: Aaron und Mose. Und Aaron wurde abgesondert, daß er als hochheilig geheiligt würde, er und seine Söhne auf ewig, um vor Jehova zu räuchern, ihm zu dienen und in seinem Namen zu segnen ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Und was Mose, den Mann Gottes, betrifft, so wurden seine Söhne nach dem Stamme Levi genannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Die Söhne Moses: Gersom und Elieser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'die Söhne Gersoms: Schebuel, das Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Und die Söhne Eliesers waren: Rechabja, das Haupt; und Elieser hatte keine anderen Söhne; aber die Söhne Rechabjas waren überaus zahlreich. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Die Söhne Jizhars: Schelomith, das Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Die Söhne Hebrons: Jerija, das Haupt; Amarja, der zweite; Jachasiel, der dritte; und Jekamam, der vierte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Die Söhne Ussiels: Micha, das Haupt, und Jischija, der zweite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Die Söhne Meraris: Machli und Musi. Die Söhne Machlis: Eleasar und Kis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Und Eleasar starb, und er hatte keine Söhne, sondern nur Töchter; und die Söhne Kis\', ihre Brüder, nahmen sie zu Weibern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Die Söhne Musis: Machli und Eder und Jeremoth, drei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Das waren die Söhne Levis nach ihren Vaterhäusern, Häupter der Väter, wie sie gemustert wurden nach der Zahl der Namen, Kopf für Kopf, welche das Werk taten für den Dienst des Hauses Jehovas, von zwanzig Jahren an und darüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Denn David sprach: Jehova, der Gott Israels, hat seinem Volke Ruhe geschafft, und er wohnt in Jerusalem auf ewig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'so haben auch die Leviten die Wohnung und alle ihre Geräte zu ihrem Dienste nicht mehr zu tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Denn nach den letzten Worten Davids wurden von den Söhnen Levis diejenigen von zwanzig Jahren an und darüber gezählt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Denn ihre Stelle war zur Seite der Söhne Aarons für den Dienst des Hauses Jehovas betreffs der Vorhöfe und der Zellen und der Reinigung alles Heiligen, und betreffs des Werkes des Dienstes des Hauses Gottes:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'für das Schichtbrot, und für das Feinmehl zum Speisopfer, und für die ungesäuerten Fladen, und für die Pfanne, und für das Eingerührte, und für alles Hohl-und Längenmaß;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'und damit sie Morgen für Morgen hinträten, um Jehova zu preisen und zu loben, und ebenso am Abend;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'und um alle Brandopfer dem Jehova zu opfern an den Sabbathen, an den Neumonden und an den Festen, nach der Zahl, nach der Vorschrift darüber, beständig vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Und sie warteten der Hut des Zeltes der Zusammenkunft und der Hut des Heiligtums, und der Hut der Söhne Aarons, ihrer Brüder, für den Dienst des Hauses Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Und was die Söhne Aarons betrifft, so waren ihre Abteilungen: Die Söhne Aarons: Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Und Nadab und Abihu starben vor ihrem Vater, und sie hatten keine Söhne; und Eleasar und Ithamar übten den Priesterdienst aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Und David, und Zadok von den Söhnen Eleasars, und Ahimelech von den Söhnen Ithamars teilten sie ab nach ihrem Amte, in ihrem Dienste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Und von den Söhnen Eleasars wurden mehr Familienhäupter gefunden, als von den Söhnen Ithamars; und so teilten sie sie so ab: Von den Söhnen Eleasars sechzehn Häupter von Vaterhäusern, und von den Söhnen Ithamars acht Häupter von ihren Vaterhäusern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Und zwar teilten sie sie durch Lose ab, diese wie jene; denn die Obersten des Heiligtums und die Obersten Gottes waren aus den Söhnen Eleasars und aus den Söhnen Ithamars.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Und Schemaja, der Sohn Nethaneels, der Schreiber aus Levi, schrieb sie auf in Gegenwart des Königs und der Obersten und Zadoks, des Priesters, und Ahimelechs, des Sohnes Abjathars, und der Häupter der Väter der Priester und der Leviten. Je ein Vaterhaus wurde ausgelost für Eleasar, und je eines wurde ausgelost für Ithamar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Und das erste Los kam heraus für Jehojarib, für Jedaja das zweite,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'für Harim das dritte, für Seorim das vierte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'für Malkija das fünfte, für Mijamin das sechste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'für Hakkoz das siebte, für Abija das achte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'für Jeschua das neunte, für Schekanja das zehnte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'für Eljaschib das elfte, für Jakim das zwölfte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'für Huppa das dreizehnte, für Jeschebab das vierzehnte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'für Bilga das fünfzehnte, für Immer das sechzehnte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'für Hesir das siebzehnte, für Happizez das achtzehnte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'für Pethachja das neunzehnte, für Jecheskel das zwanzigste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'für Jakin das einundzwanzigste, für Gamul das zweiundzwanzigste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'für Delaja das dreiundzwanzigste, für Maasja das vierundzwanzigste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Das war ihre Einteilung zu ihrem Dienst, um in das Haus Jehovas zu kommen nach ihrer Vorschrift, gegeben durch ihren Vater Aaron, so wie Jehova, der Gott Israels, ihm geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Und was die übrigen Söhne Levis betrifft: von den Söhnen Amrams: Schubael; von den Söhnen Schubaels: Jechdeja. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Von Rechabja, von den Söhnen Rechabjas: das Haupt, Jischija. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Von den Jizharitern: Schelomoth; von den Söhnen Schelomoths: Jachath. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Und die Söhne Hebrons: Jerija, das Haupt; Amarja, der zweite; Jachasiel, der dritte; Jekamam, der vierte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'die Söhne Ussiels: Micha; von den Söhnen Michas: Schamir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Der Bruder Michas war Jischija; von den Söhnen Jischijas: Sekarja. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Die Söhne Meraris: Machli und Musi. Die Söhne Jaasijas, seines Sohnes:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'die Söhne Meraris von Jaasija, seinem Sohne: Schoham und Sakkur und Ibri;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'von Machli: Eleasar, der hatte aber keine Söhne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'von Kis, die Söhne Kis\': Jerachmeel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'und die Söhne Musis: Machil und Eder und Jerimoth. Das waren die Söhne der Leviten, nach ihren Vaterhäusern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Und auch sie warfen Lose wie ihre Brüder, die Söhne Aarons, in Gegenwart des Königs David und Zadoks und Ahimelechs und der Häupter der Väter der Priester und der Leviten, das Haupt der Väter wie sein geringster Bruder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Und David und die Obersten des Heeres sonderten von den Söhnen Asaphs und Hemans und Jeduthuns solche zum Dienste ab, welche weissagten mit Lauten und Harfen und mit Zimbeln. Und es war ihre Zahl, der Männer, die tätig waren für ihren Dienst:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Von den Söhnen Asaphs: Sakkur und Joseph und Nethanja und Ascharela, die Söhne Asaphs, unter der Leitung Asaphs, welcher nach der Anweisung des Königs weissagte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Von Jeduthun, die Söhne Jeduthuns: Gedalja und Zeri und Jesaja, Haschabja und Mattithja, und Simei, sechs, unter der Leitung ihres Vaters Jeduthun, mit der Laute, welcher weissagte, um Jehova zu preisen und zu loben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Von Heman, die Söhne Hemans: Bukkija und Mattanja, Ussiel, Schebuel und Jerimoth, Hananja, Hanani, Eliatha, Giddalti und Romamti-Eser, Joschbekascha, Mallothi, Hothir, Machasioth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Alle diese waren Söhne Hemans, des Sehers des Königs in den Worten Gottes, um seine Macht zu erheben; und Gott hatte dem Heman vierzehn Söhne und drei Töchter gegeben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Alle diese waren unter der Leitung ihrer Väter, Asaph und Jeduthun und Heman, beim Gesange im Hause Jehovas, mit Zimbeln, Harfen und Lauten, zum Dienste des Hauses Gottes, nach der Anweisung des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Und es war ihre Zahl mit ihren Brüdern, die im Gesange Jehovas geübt waren: aller Kundigen zweihundertachtundachtzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Und sie warfen Lose über ihr Amt, der Kleine wie der Große, der Kundige mit dem Lehrling.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Und das erste Los kam heraus für Asaph, für Joseph; für Gedalja das zweite: er und seine Brüder und seine Söhne waren zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'das dritte für Sakkur: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'das vierte für Jizri: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'das fünfte für Nathanja: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'das sechste für Bukkija: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'das siebte für Jescharela: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'das achte für Jesaja: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'das neunte für Mattanja: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'das zehnte für Simei: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'das elfte für Asarel: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'das zwölfte für Haschabja: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'das dreizehnte für Schubael: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'das vierzehnte für Mattithja: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'das fünfzehnte für Jeremoth: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'das sechzehnte für Hananja: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'das siebzehnte für Joschbekascha: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'das achtzehnte für Hanani: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'das neunzehnte für Mallothi: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'das zwanzigste für Eliatha: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'das einundzwanzigste für Hothir: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'das zweiundzwanzigste für Giddalti: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'das dreiundzwanzigste für Machasioth: seine Söhne und seine Brüder, zwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'das vierundzwanzigste für Romamti-Eser: seine Söhne und seine Brüder, zwölf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Die Abteilungen der Torhüter: von den Korhitern: Meschelemja, der Sohn Kores, von den Söhnen Asaphs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'und Meschelemja hatte Söhne: Sekarja, der Erstgeborene; Jediael, der zweite; Sebadja, der dritte; Jathniel, der vierte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Elam, der fünfte; Jochanan, der sechste; Eljehoenai, der siebte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Und Obed-Edom hatte Söhne: Schemaja, der Erstgeborene; Josabad, der zweite; Joach, der dritte; und Sakar, der vierte; und Nethaneel, der fünfte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Ammiel, der sechste: Issaschar, der siebte; Peullethai, der achte; denn Gott hatte ihn gesegnet. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Und Schemaja, seinem Sohne, wurden Söhne geboren, welche in dem Hause ihres Vaters herrschten, denn sie waren tapfere Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Die Söhne Schemajas: Othni und Rephael und Obed, Elsabad und seine Brüder, wackere Männer, Elihu und Semakja.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Alle diese von den Söhnen Obed-Edoms, sie und ihre Söhne und ihre Brüder, waren wackere Männer, fähig zum Dienste, zweiundsechzig von Obed-Edom. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Und Meschelemja hatte Söhne und Brüder, wackere Männer, achtzehn. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Und Hosa, von den Söhnen Meraris, hatte Söhne: Schimri, das Haupt (obwohl er nicht der Erstgeborene war, setzte sein Vater ihn doch zum Haupte);');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Hilkija, der zweite; Tebalja, der dritte; Sekarja, der vierte. Aller Söhne und Brüder Hosas waren dreizehn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Diese Abteilungen der Torhüter, nach den Häuptern der Männer, hatten die Wachen gleich ihren Brüdern, um in dem Hause Jehovas zu dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Und sie warfen Lose, der Kleine wie der Große, nach ihren Vaterhäusern, für jedes Tor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Und für Schelemja fiel das Los gegen Osten. Und sie warfen Lose für seinen Sohn Sekarja, der ein verständiger Ratgeber war; und sein Los kam heraus gegen Norden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Für Obed-Edom gegen Süden; und seinen Söhnen fiel das Vorratshaus zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Für Schuppim und für Hosa gegen Westen, bei dem Tore Schalleketh, an der aufsteigenden Straße, Wache gegen Wache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Gegen Osten waren sechs Leviten; gegen Norden täglich vier; gegen Süden täglich vier; und an dem Vorratshause je zwei;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'an dem Parbar gegen Westen: vier an der Straße, zwei an dem Parbar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Das sind die Abteilungen der Torhüter von den Söhnen der Korhiter und von den Söhnen Meraris.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Und die Leviten: Achija war über die Schätze des Hauses Gottes und über die Schätze der geheiligten Dinge. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Die Söhne Ladans, die Söhne der Gersoniter von Ladan, die Häupter der Väter von Ladan, dem Gersoniter, die Jechieliter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'die Söhne der Jechieliter: Setham und sein Bruder Joel, waren über die Schätze des Hauses Jehovas. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Was die Amramiter, die Jizhariter, die Hebroniter, die Ussieliter betrifft,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'so war Schebuel, der Sohn Gersoms, des Sohnes Moses, Oberaufseher über die Schätze. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Und seine Brüder, von Elieser: dessen Sohn Rechabja, und dessen Sohn Jesaja, und dessen Sohn Joram, und dessen Sohn Sikri, und dessen Sohn Schelomith.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Dieser Schelomith und seine Brüder waren über alle Schätze der geheiligten Dinge, welche der König David und die Häupter der Väter, die Obersten über tausend und über hundert, und die Obersten des Heeres geheiligt hatten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'von den Kriegen und von der Beute hatten sie sie geheiligt zur Unterhaltung des Hauses Jehovas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'und über alles, was Samuel, der Seher, und Saul, der Sohn Kis\', und Abner, der Sohn Ners, und Joab, der Sohn der Zeruja, geheiligt hatten. Alles Geheiligte stand unter der Aufsicht Schelomiths und seiner Brüder. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Von den Jizharitern waren Kenanja und seine Söhne für die äußeren Geschäfte über Israel, als Vorsteher und Richter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Von den Hebronitern waren Haschabja und seine Brüder, wackere Männer, tausendsiebenhundert, zur Aufsicht über Israel diesseit des Jordan gegen Abend, für alle Angelegenheiten Jehovas und für den Dienst des Königs. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Von den Hebronitern war Jerija das Haupt, von den Hebronitern, nach ihren Geschlechtern, nach den Vätern (im vierzigsten Jahre der Regierung Davids forschte man nach ihnen, und es fanden sich unter ihnen tüchtige Männer zu Jaser-Gilead);');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'und seine Brüder, wackere Männer, waren zweitausendsiebenhundert, Häupter der Väter. Und der König David bestellte sie über die Rubeniter und die Gaditer und den halben Stamm Manasse, für alle Angelegenheiten Gottes und für die Angelegenheiten des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Und die Kinder Israel, nach ihrer Zahl, die Häupter der Väter und die Obersten über tausend und über hundert, und ihre Vorsteher, die dem König dienten in allen Angelegenheiten der Abteilungen, der antretenden und der abtretenden, Monat für Monat, für alle Monate des Jahres; eine jede Abteilung zählte vierundzwanzigtausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Über die erste Abteilung für den ersten Monat war Jaschobam, der Sohn Sabdiels; und in seiner Abteilung waren vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Er war von den Söhnen des Perez, das Haupt aller Heerobersten für den ersten Monat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Und über die Abteilung des zweiten Monats war Dodai, der Achochiter; und von seiner Abteilung war Mikloth Oberaufseher; und in seiner Abteilung waren vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Der Oberste des dritten Heeres für den dritten Monat war Benaja, der Sohn Jojadas, des Krondieners, als Haupt; und in seiner Abteilung waren vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Dieser Benaja war ein Held unter den Dreißig und über die Dreißig; und von seiner Abteilung war Ammisabad, sein Sohn, Oberaufseher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Der vierte für den vierten Monat war Asael, der Bruder Joabs, und Sebadja, sein Sohn, nach ihm; und in seiner Abteilung waren vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'der fünfte für den fünften Monat war der Oberste Schamhuth, der Jisrachiter; und in seiner Abteilung waren vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Der sechste für den sechsten Monat war Ira, der Sohn Ikkesch\', der Tekoiter; und in seiner Abteilung waren vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Der siebte für den siebten Monat war Helez, der Peloniter, von den Kindern Ephraim; und in seiner Abteilung waren vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Der achte für den achten Monat war Sibbekai, der Huschathiter, von den Sarchitern; und in seiner Abteilung waren vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Der neunte für den neunten Monat war Abieser, der Anathothiter, von den Benjaminitern; und in seiner Abteilung waren vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Der zehnte für den zehnten Monat war Maharai, der Netophathiter, von den Sarchitern; und in seiner Abteilung waren vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Der elfte für den elften Monat war Benaja, der Pirhathoniter, von den Kindern Ephraim; und in seiner Abteilung waren vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'der zwölfte für den zwölften Monat war Heldai, der Netophathiter, von Othniel; und in seiner Abteilung waren vierundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Und über die Stämme Israels: Der Fürst der Rubeniter war Elieser, der Sohn Sikris; der Simeoniter, Schephatja, der Sohn Maakas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'von Levi, Haschabja, der Sohn Kemuels; von Aaron, Zadok;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'von Juda, Elihu, von den Brüdern Davids; von Issaschar, Omri, der Sohn Michaels;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'von Sebulon, Jischmaja, der Sohn Obadjas; von Naphtali, Jerimoth, der Sohn Asriels;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'von den Kindern Ephraim, Hosea, der Sohn Asasjas; von dem halben Stamme Manasse, Joel, der Sohn Pedajas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'von der Hälfte des Manasse in Gilead, Iddo, der Sohn Sekarjas; von Benjamin, Jaasiel, der Sohn Abners;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'von Dan, Asarel, der Sohn Jerochams. Das sind die Obersten der Stämme Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Und David nahm ihre Zahl von zwanzig Jahren an und darunter nicht auf; denn Jehova hatte gesagt, daß er Israel mehren würde wie die Sterne des Himmels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joab, der Sohn der Zeruja, hatte zu zählen begonnen, aber nicht vollendet; und es kam deshalb ein Zorn über Israel; und so wurde die Zahl in die Aufzählung der Jahrbücher des Königs David nicht aufgenommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Und über die Schätze des Königs war Asmaweth, der Sohn Adiels. Und über die Vorräte auf dem Felde, in den Städten und in den Dörfern und in den Türmen, war Jonathan, der Sohn Ussijas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Und über die Feldarbeiter beim Landbau: Esri, der Sohn Kelubs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Und über die Weinberge: Simei, der Ramathiter; und über den Ertrag der Weinberge, über die Weinvorräte: Sabdi, der Schiphmiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Und über die Olivenbäume und die Sykomoren, welche in der Niederung waren: Baal-Hanan, der Gederiter; und über die Ölvorräte: Joas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Und über die Rinder, die in Saron weideten: Schitrai, der Saroniter; und über die Rinder in den Niederungen: Schaphat, der Sohn Adlais;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'und über die Kamele: Obil, der Ismaeliter; und über die Eselinnen: Jechdeja, der Meronothiter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'und über das Kleinvieh: Jasis, der Hageriter. Alle diese waren Aufseher über die Habe des Königs David.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Und Jonathan, der Oheim Davids, war Rat; er war ein einsichtiger Mann und ein Schriftgelehrter. Und Jechiel, der Sohn Hakmonis, war bei den Söhnen des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Und Ahitophel war Rat des Königs; und Husai, der Arkiter, war Freund des Königs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'und nach Ahitophel war Jojada, der Sohn Benajas, und Abjathar. Und Joab war Heeroberster des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Und David versammelte alle Obersten Israels, die Obersten der Stämme und die Obersten der Abteilungen, welche dem König dienten, und die Obersten über tausend und die Obersten über hundert, und die Aufseher über alle Habe und alles Besitztum des Königs und seiner Söhne, samt den Kämmerern und den Helden und allen tapferen Männern, nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Und der König David erhob sich auf seine Füße und sprach: Höret mich, meine Brüder und mein Volk! Ich hatte in meinem Herzen, ein Haus der Ruhe zu bauen für die Lade des Bundes Jehovas und für den Schemel der Füße unseres Gottes; und ich schickte mich an zu bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Aber Gott sprach zu mir: Du sollst meinem Namen kein Haus bauen; denn du bist ein Kriegsmann und hast Blut vergossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Und Jehova, der Gott Israels, hat mich aus dem ganzen Hause meines Vaters erwählt, um König zu sein über Israel ewiglich; denn Juda hat er zum Fürsten erwählt, und im Hause Juda das Haus meines Vaters, und unter den Söhnen meines Vaters hat er an mir Wohlgefallen gehabt, mich zum König zu machen über ganz Israel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'und von allen meinen Söhnen (denn Jehova hat mir viele Söhne gegeben) hat er meinen Sohn Salomo erwählt, um auf dem Throne des Königtums Jehovas über Israel zu sitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Und er sprach zu mir: Salomo, dein Sohn, er soll mein Haus und meine Höfe bauen; denn ich habe ihn mir zum Sohne erwählt, und ich will ihm Vater sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Und ich werde sein Königreich befestigen auf ewig, wenn er fest daran halten wird, meine Gebote und meine Rechte zu tun, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Und nun, vor den Augen von ganz Israel, der Versammlung Jehovas, und vor den Ohren unseres Gottes: Beobachtet und suchet alle Gebote Jehovas, eures Gottes, auf daß ihr dieses gute Land besitzet und es euren Söhnen nach euch vererbet auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Und du, mein Sohn Salomo, erkenne den Gott deines Vaters und diene ihm mit ungeteiltem Herzen und mit williger Seele! Denn Jehova erforscht alle Herzen, und alles Gebilde der Gedanken kennt er. Wenn du ihn suchst, wird er sich von dir finden lassen; wenn du ihn aber verlässest, wird er dich verwerfen auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Sieh nun, daß Jehova dich erwählt hat, ihm ein Haus zu bauen zum Heiligtum; sei stark und handle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Und David gab seinem Sohne Salomo das Muster der Halle des Tempels und seiner Häuser und seiner Schatzkammern und seiner Obergemächer und seiner inneren Gemächer und des Hauses des Sühndeckels;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'und das Muster von allem, was durch den Geist in ihm war: betreffs der Höfe des Hauses Jehovas und aller Zellen ringsum; betreffs der Schatzkammern des Hauses Gottes und der Schatzkammern der geheiligten Dinge;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'und betreffs der Abteilungen der Priester und der Leviten und aller Dienstverrichtungen im Hause Jehovas; und betreffs aller Geräte des Dienstes im Hause Jehovas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'betreffs des Goldes nach dem Goldgewicht für alle Geräte eines jeden Dienstes; und betreffs aller silbernen Geräte nach dem Gewicht, für alle Geräte eines jeden Dienstes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Und er gab das Gewicht an für die goldenen Leuchter und für ihre goldenen Lampen, nach dem Gewicht eines jeden Leuchters und seiner Lampen; und für die silbernen Leuchter nach dem Gewicht eines Leuchters und seiner Lampen, je nach dem Dienst eines jeden Leuchters;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'und das Gold-Gewicht für die Tische der Schichtbrote, für jeden Tisch; und das Silber für die silbernen Tische;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'und die Gabeln und die Sprengschalen und die Kannen von reinem Golde; und das Gewicht für die goldenen Becher, nach dem Gewicht eines jeden Bechers, und für die silbernen Becher, nach dem Gewicht eines jeden Bechers;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'und für den Räucheraltar von geläutertem Golde, nach dem Gewicht; und das Muster des Wagens der Cherubim von Gold, welche die Flügel ausbreiten und die Lade des Bundes Jehovas überdecken. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Über dies alles, über alle Werke des Musters, sprach David, hat er mich durch Schrift unterwiesen, dadurch, daß die Hand Jehovas auf mir war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Und David sprach zu seinem Sohne Salomo: Sei stark und mutig und handle; fürchte dich nicht und erschrick nicht! denn Jehova Gott, mein Gott, wird mit dir sein: er wird dich nicht versäumen und dich nicht verlassen, bis alles Werk zum Dienste des Hauses Jehovas vollendet ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Und siehe, da sind die Abteilungen der Priester und der Leviten für den ganzen Dienst des Hauses Gottes; und bei dir sind in allem Werke solche, die bereitwillig und geschickt sind zu jedem Dienste, und die Obersten und das ganze Volk zu allen deinen Anordnungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Und der König David sprach zu der ganzen Versammlung: Salomo, mein Sohn, der einzige, den Gott erwählt hat, ist noch jung und zart; das Werk aber ist groß, denn nicht für einen Menschen ist dieser Palast, sondern für Jehova Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Und mit all meiner Kraft habe ich für das Haus meines Gottes bereitet: das Gold zu dem goldenen, und das Silber zu dem silbernen, und das Erz zu dem ehernen, das Eisen zu dem eisernen, und das Holz zu dem hölzernen Geräte; Onyxsteine und Steine zum Einsetzen, Steine zur Verzierung und buntfarbig, und allerlei kostbare Steine, und weiße Marmorsteine in Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Und überdies, weil ich Wohlgefallen habe an dem Hause meines Gottes, habe ich, was ich als eigenes Gut an Gold und Silber besitze, für das Haus meines Gottes gegeben, zu alledem hinzu, was ich für das Haus des Heiligtums bereitet habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'dreitausend Talente Gold von Gold aus Ophir, und siebentausend Talente geläutertes Silber, zum Überziehen der Wände der Häuser;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Gold zu dem goldenen und Silber zu dem silbernen Geräte, und zu allem Werke von Künstlerhand. Wer ist nun bereitwillig, heute seine Hand für Jehova zu füllen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Und die Obersten der Väter und die Obersten der Stämme Israels, und die Obersten über tausend und über hundert, und die Obersten über die Geschäfte des Königs zeigten sich bereitwillig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'und sie gaben für die Arbeit des Hauses Gottes fünftausend Talente Gold und zehntausend Dariken, und zehntausend Talente Silber, und achtzehntausend Talente Erz, und hunderttausend Talente Eisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Und bei welchem sich Edelsteine vorfanden, die gaben sie zum Schatze des Hauses Jehovas in die Hand Jechiels, des Gersoniters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Und das Volk freute sich über ihre Bereitwilligkeit, denn mit ungeteiltem Herzen zeigten sie sich bereitwillig für Jehova; und auch der König David freute sich mit großer Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Und David pries Jehova vor den Augen der ganzen Versammlung, und David sprach: Gepriesen seiest du, Jehova, Gott unseres Vaters Israel, von Ewigkeit zu Ewigkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Dein, Jehova, ist die Größe und die Stärke und der Ruhm und der Glanz und die Pracht; denn alles im Himmel und auf Erden ist dein. Dein, Jehova, ist das Königreich, und du bist über alles erhaben als Haupt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'und Reichtum und Ehre kommen von dir, und du bist Herrscher über alles; und in deiner Hand sind Macht und Stärke, und in deiner Hand ist es, alles groß und stark zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Und nun, unser Gott, wir preisen dich, und wir rühmen deinen herrlichen Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Denn wer bin ich, und was ist mein Volk, daß wir vermöchten, auf solche Weise freigebig zu sein? Denn von dir kommt alles, und aus deiner Hand haben wir dir gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Denn wir sind Fremdlinge vor dir und Beisassen, wie alle unsere Väter; wie ein Schatten sind unsere Tage auf Erden, und keine Hoffnung ist da, hienieden zu bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Jehova, unser Gott, alle diese Menge, die wir bereitet haben, um dir ein Haus zu bauen für deinen heiligen Namen, von deiner Hand ist sie, und das alles ist dein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Und ich weiß, mein Gott, daß du das Herz prüfst und Wohlgefallen hast an Aufrichtigkeit: Ich nun, in Aufrichtigkeit meines Herzens habe ich alles dieses bereitwillig gegeben; und ich habe jetzt mit Freuden gesehen, daß dein Volk, welches sich hier befindet, dir bereitwillig gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Jehova, Gott unserer Väter Abraham, Isaak und Israel, bewahre dieses ewiglich als Gebilde der Gedanken des Herzens deines Volkes, und richte ihr Herz zu dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'und meinem Sohne Salomo gib ein ungeteiltes Herz, deine Gebote, deine Zeugnisse und deine Satzungen zu beobachten, und alles zu tun und den Palast zu bauen, den ich vorbereitet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Und David sprach zu der ganzen Versammlung: Preiset doch Jehova, euren Gott! Und die ganze Versammlung pries Jehova, den Gott ihrer Väter; und sie neigten sich und beugten sich nieder vor Jehova und vor dem König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Und am nächstfolgenden Tage opferten sie Schlachtopfer dem Jehova, und opferten Brandopfer dem Jehova: tausend Farren, tausend Widder, tausend Schafe, und ihre Trankopfer, und Schlachtopfer in Menge für ganz Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Und sie aßen und tranken vor Jehova an selbigem Tage mit großer Freude; und sie machten Salomo, den Sohn Davids, zum zweiten Male zum König und salbten ihn Jehova zum Fürsten, und salbten Zadok zum Priester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Und so setzte sich Salomo auf den Thron Jehovas als König an seines Vaters David Statt, und er hatte Gedeihen; und ganz Israel gehorchte ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Und alle Fürsten und die Helden, und auch alle Söhne des Königs David unterwarfen dich dem König Salomo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Und Jehova machte Salomo überaus groß vor den Augen von ganz Israel; und er gab ihm eine königliche Pracht, wie sie vor ihm auf keinem König über Israel gewesen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'So regierte David, der Sohn Isais, über ganz Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Und die Tage, die er über ganz Israel regierte, waren vierzig Jahre; zu Hebron regierte er sieben Jahre, und zu Jerusalem regierte er dreiunddreißig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Und er starb in gutem Alter, satt an Tagen, Reichtum und Ehre. Und Salomo, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Und die Geschichte des Königs David, die erste und die letzte, siehe, sie ist geschrieben in der Geschichte Samuels, des Sehers, und in der Geschichte Nathans, des Propheten, und in der Geschichte Gads, des Schauers;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'nebst seiner ganzen Regierung und seiner Macht, und den Zeiten, die über ihn und über Israel und über alle Königreiche der Länder ergangen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Und Salomo, der Sohn Davids, erstarkte in seinem Königreich; und Jehova, sein Gott, war mit ihm und machte ihn überaus groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Und Salomo redete zu ganz Israel, zu den Obersten über tausend und über hundert, und zu den Richtern und zu allen Fürsten von ganz Israel, den Häuptern der Väter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'und sie gingen, Salomo und die ganze Versammlung mit ihm, nach der Höhe, die zu Gibeon war; denn dort war das Zelt der Zusammenkunft Gottes, welches Mose, der Knecht Jehovas, in der Wüste gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Jedoch die Lade Gottes hatte David von Kirjath-Jearim heraufgebracht an den Ort, welchen David für sie bereitet hatte; denn er hatte ihr zu Jerusalem ein Zelt aufgeschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Und der eherne Altar, den Bezaleel, der Sohn Uris, des Sohnes Hurs, gemacht hatte, war daselbst vor der Wohnung Jehovas; und Salomo und die Versammlung besuchten ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Und Salomo opferte daselbst vor Jehova auf dem ehernen Altar, der bei dem Zelte der Zusammenkunft war; und er opferte auf demselben tausend Brandopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'In selbiger Nacht erschien Gott dem Salomo und sprach zu ihm: Bitte, was ich dir geben soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Und Salomo sprach zu Gott: Du hast ja an David, meinem Vater, große Güte erwiesen, und du hast mich zum König gemacht an seiner Statt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'nun möge sich, Jehova Gott, dein Wort bewähren, das du zu meinem Vater David geredet hast! Denn du hast mich zum König gemacht über ein Volk, das zahlreich ist wie der Staub der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Gib mir nun Weisheit und Erkenntnis daß ich vor diesem Volke aus-und eingehen möge; denn wer könnte dieses dein großes Volk richten? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Und Gott sprach zu Salomo: Weil dieses in deinem Herzen gewesen ist, und du nicht gebeten hast um Reichtum, Güter und Ehre, und um das Leben derer, die dich hassen, und auch nicht um viele Tage gebeten, sondern dir Weisheit und Erkenntnis erbeten hast, damit du mein Volk richten mögest, über welches ich dich zum König gemacht habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'so sind dir Weisheit und Erkenntnis gegeben; und Reichtum und Güter und Ehre will ich dir geben, dergleichen die Könige, die vor dir gewesen sind, nicht gehabt haben, und dergleichen keiner nach dir haben wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Und Salomo kam von der Höhe, die zu Gibeon war, von dem Zelte der Zusammenkunft nach Jerusalem. Und er regierte über Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Und Salomo brachte Wagen und Reiter zusammen, und er hatte tausend vierhundert Wagen und zwölftausend Reiter; und er verlegte sie in die Wagenstädte und zu dem König nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Und der König machte das Silber und das Gold in Jerusalem den Steinen gleich, und die Zedern machte er den Sykomoren gleich, die in der Niederung sind, an Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Und die Ausfuhr der Rosse für Salomo geschah aus Ägypten; und ein Zug Handelsleute des Königs holte einen Zug um Geld.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Und sie brachten herauf und führten aus Ägypten einen Wagen aus um sechshundert Sekel Silber, und ein Roß um hundertfünfzig. Und also führte man für alle Könige der Hethiter und für die Könige von Syrien durch ihre Hand aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Und Salomo gedachte, dem Namen Jehovas ein Haus zu bauen und ein Haus für sein Königtum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Und Salomo zählte siebzigtausend Lastträger ab, und achtzigtausend Steinhauer im Gebirge, und dreitausend sechshundert Aufseher über dieselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Und Salomo sandte zu Huram, dem König von Tyrus, und ließ ihm sagen: So wie du meinem Vater David getan und ihm Zedern gesandt hast, daß er sich ein Haus baue, um darin zu wohnen, so tue auch mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Siehe, ich will dem Namen Jehovas, meines Gottes, ein Haus bauen, um es ihm zu heiligen, wohlriechendes Räucherwerk vor ihm zu räuchern, und um das beständige Schichtbrot zuzurichten und Brandopfer morgens und abends zu opfern, an den Sabbathen und an den Neumonden und an den Festen Jehovas, unseres Gottes; ewiglich liegt dies Israel ob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Und das Haus, das ich bauen will, soll groß sein; denn unser Gott ist größer als alle Götter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Aber wer vermöchte ihm ein Haus zu bauen? Denn die Himmel und der Himmel Himmel können ihn nicht fassen. Und wer bin ich, daß ich ihm ein Haus bauen sollte, es sei denn, um vor ihm zu räuchern?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Und nun sende mir einen Mann, der zu arbeiten versteht in Gold und in Silber, und in Erz und in Eisen, und in rotem Purpur und Karmesin und blauem Purpur, und kundig ist, Schnitzarbeit zu machen, nebst den Kunstverständigen, die bei mir in Juda und in Jerusalem sind, die mein Vater David bestellt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Und sende mir Zedern-,Zypressen-und Sandelholz vom Libanon; denn ich weiß, daß deine Knechte das Holz des Libanon zu hauen verstehen; und siehe, meine Knechte sollen mit deinen Knechten sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Und man möge mir Holz bereiten in Menge; denn das Haus, das ich bauen will, soll groß und außerordentlich sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Und siehe, ich werde deinen Knechten, den Holzhauern, die das Holz fällen, ausgeschlagenen Weizen geben, zwanzigtausend Kor, und zwanzigtausend Kor Gerste, und zwanzigtausend Bath Wein, und zwanzigtausend Bath Öl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Und Huram, der König von Tyrus, antwortete schriftlich und sandte an Salomo folgende Botschaft: Weil Jehova sein Volk liebt, hat er dich zum König über sie gesetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Und Huram sprach: Gepriesen sei Jehova, der Gott Israels, der Himmel und Erde gemacht hat, daß er dem König David einen weisen Sohn gegeben, voll Einsicht und Verstand, der Jehova ein Haus bauen will und ein Haus für sein Königtum!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Und nun sende ich einen kunstverständigen, einsichtsvollen Mann, Huram-Abi,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'den Sohn eines Weibes von den Töchtern Dans, und dessen Vater ein Tyrer war, der zu arbeiten weiß in Gold und Silber, in Erz, in Eisen, in Steinen und in Holz, in rotem Purpur, in blauem Purpur und in Byssus und in Karmesin, und allerlei Schnitzarbeit zu machen, und allerlei Kunstwerk zu ersinnen, das ihm aufgegeben wird, nebst deinen Kunstverständigen und den Kunstverständigen meines Herrn David, deines Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Und nun, den Weizen und die Gerste, das Öl und den Wein, wovon mein Herr gesprochen hat, möge er seinen Knechten senden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Wir aber werden Holz hauen vom Libanon nach all deinem Bedarf, und werden es dir als Flöße auf dem Meere nach Japho bringen; und du magst es nach Jerusalem hinaufschaffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Und Salomo zählte alle Fremdlinge, die im Lande Israel waren, nach der Zählung, welche sein Vater David von ihnen gemacht hatte; und es fanden sich hundertdreiundfünfzigtausend sechshundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Und er machte aus ihnen siebzigtausend zu Lastträgern, und achtzigtausend zu Steinhauern im Gebirge, und dreitausend sechshundert zu Aufsehern, um das Volk zur Arbeit anzuhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Und Salomo fing an, das Haus Jehovas zu bauen in Jerusalem, auf dem Berge Morija, wo er seinem Vater David erschienen war, an dem Orte, den David bereitet hatte, auf der Tenne Ornans, des Jebusiters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Und er fing an zu bauen im zweiten Monat, am zweiten Tage, im vierten Jahre seiner Regierung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Und dies war die Grundlage, welche Salomo zum Bau des Hauses Gottes legte: die Länge, nach dem früheren Ellenmaß, sechzig Ellen, und die Breite zwanzig Ellen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Und die Halle, welche der Länge nach vor der Breite des Hauses war, zwanzig Ellen, und die Höhe hundertundzwanzig; und er überzog sie inwendig mit reinem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Und das große Haus bekleidete er mit Zypressenholz, und bekleidete es mit gutem Golde; und er brachte Palmen und Ketten darauf an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Und er überzog das Haus mit kostbaren Steinen zum Schmuck; das Gold aber war Gold von Parwaim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Und er bekleidete das Haus, die Balken der Decke, die Schwellen und seine Wände und seine Türflügel mit Gold; und er schnitzte Cherubim ein an den Wänden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Und er machte das Haus des Allerheiligsten. Seine Länge, vor der Breite des Hauses her, war zwanzig Ellen, und seine Breite zwanzig Ellen; und er bekleidete es mit gutem Golde, an sechshundert Talente.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Und das Gewicht der Nägel war an fünfzig Sekel Gold. Auch die Obergemächer bekleidete er mit Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Und er machte im Hause des Allerheiligsten zwei Cherubim, ein Werk von Bildhauerarbeit; und man überzog sie mit Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Und die Flügel der Cherubim, ihre Länge war zwanzig Ellen: der Flügel des einen, von fünf Ellen, rührte an die Wand des Hauses; und der andere Flügel, von fünf Ellen, rührte an den Flügel des anderen Cherubs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'und der Flügel des anderen Cherubs, von fünf Ellen, rührte an die Wand des Hauses; und der andere Flügel, von fünf Ellen, stieß an den Flügel des einen Cherubs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Die Flügel dieser Cherubim maßen ausgebreitet zwanzig Ellen; und sie selbst standen auf ihren Füßen, und ihre Angesichter waren dem Hause zugewandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Und er machte den Vorhang von blauem und rotem Purpur und Karmesin und Byssus, und brachte Cherubim darauf an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Und er machte vor dem Hause zwei Säulen, fünfunddreißig Ellen die Länge; und das Kapitäl, das auf ihrer Spitze war, maß fünf Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Und er machte Ketten im Sprachorte und tat sie an die Spitze der Säulen; und er machte hundert Granatäpfel und tat sie an die Ketten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Und er richtete die Säulen vor dem Tempel auf, eine zur Rechten und eine zur Linken; und er gab der rechten den Namen Jakin, und der linken den Namen Boas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Und er machte einen ehernen Altar: zwanzig Ellen seine Länge, und zwanzig Ellen seine Breite, und zehn Ellen seine Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Und er machte das Meer, gegossen, zehn Ellen von seinem einen Rande bis zu seinem anderen Rande, gerundet ringsum, und fünf Ellen seine Höhe; und eine Schnur von dreißig Ellen umfaßte es ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Und unter demselben waren Gleichnisse von Rindern, die es ringsherum umgaben, zehn auf die Elle, das Meer ringsum einschließend; der Rinder waren zwei Reihen, gegossen aus einem Gusse mit demselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Es stand auf zwölf Rindern; drei wandten sich gegen Norden, und drei wandten sich gegen Westen, und drei wandten sich gegen Süden, und drei wandten sich gegen Osten; und das Meer war auf denselben, oben darüber, und alle ihre Hinterteile waren nach innen gekehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Und seine Dicke war eine Hand breit, und sein Rand wie die Arbeit eines Becherrandes, wie eine Lilienblüte; an Inhalt faßte es dreitausend Bath.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Und er machte zehn Becken, und er setzte fünf zur Rechten und fünf zur Linken, um darin zu waschen; was zum Brandopfer gehört, spülte man darin ab. Und das Meer war für die Priester, um sich darin zu waschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Und er machte die zehn goldenen Leuchter, nach ihrer Vorschrift, und er setzte sie in den Tempel, fünf zur Rechten und fünf zur Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Und er machte zehn Tische und stellte sie in den Tempel, fünf zur Rechten und fünf zur Linken; und er machte hundert goldene Sprengschalen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Und er machte den Hof der Priester und den großen Vorhof, und die Türen zu dem Vorhof; und ihre Flügel überzog er mit Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Und das Meer setzte er auf die rechte Seite ostwärts gegen Süden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Und Huram machte die Töpfe und die Schaufeln und die Sprengschalen. Und so vollendete Huram das Werk, welches er für den König Salomo im Hause Gottes machte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'zwei Säulen und die krugförmigen Kapitäle auf der Spitze der beiden Säulen; und die zwei Netzwerke zur Bedeckung der beiden krugförmigen Kapitäle, die auf der Spitze der Säulen waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'und die vierhundert Granatäpfel zu den beiden Netzwerken; zwei Reihen Granatäpfel zu jedem Netzwerk, zur Bedeckung der beiden krugförmigen Kapitäle, die oben auf den Säulen waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'und er machte die Gestelle, und machte die Becken auf den Gestellen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'das eine Meer, und die zwölf Rinder unter demselben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'und die Töpfe und die Schaufeln und die Gabeln. Und alle ihre Geräte machte Huram-Abiw dem König Salomo für das Haus Jehovas von geglättetem Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Im Jordankreise ließ der König sie gießen in dichter Erde, zwischen Sukkoth und Zeredatha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Und Salomo machte alle diese Geräte in sehr großer Menge; denn das Gewicht des Erzes wurde nicht untersucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Und Salomo machte alle die Geräte, welche im Hause Gottes waren: und zwar den goldenen Altar; und die Tische, auf welchen die Schaubrote waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'und die Leuchter und ihre Lampen, um sie nach der Vorschrift vor dem Sprachorte anzuzünden, von geläutertem Golde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'und die Blumen und die Lampen und die Lichtschneuzen von Gold (es war lauter Gold);');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'und die Lichtmesser und die Sprengschalen und die Schalen und die Räucherpfannen von geläutertem Golde; und den Eingang des Hauses: seine inneren Türflügel, die des Allerheiligsten, und die Flügeltüren des Hauses, des Tempels, von Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Und so war das ganze Werk vollendet, welches Salomo für das Haus Jehovas machte. Und Salomo brachte die geheiligten Dinge seines Vaters David hinein, nämlich das Silber und das Gold und alle Geräte; er legte sie in die Schatzkammern des Hauses Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Damals versammelte Salomo die Ältesten von Israel und alle Häupter der Stämme, die Fürsten der Väter der Kinder Israel, nach Jerusalem, um die Lade des Bundes Jehovas heraufzubringen aus der Stadt Davids, das ist Zion.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Und alle Männer von Israel versammelten sich zu dem König am Feste..., das ist der siebte Monat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Und es kamen alle Ältesten von Israel, und die Leviten nahmen die Lade auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Und sie brachten die Lade hinauf, sowie das Zelt der Zusammenkunft und alle heiligen Geräte, die im Zelte waren: die Priester, die Leviten, brachten sie hinauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Und der König Salomo und die ganze Gemeinde Israel, die sich zu ihm versammelt hatte und vor der Lade stand, opferten Klein-und Rindvieh, das nicht gerechnet und nicht gezählt werden konnte vor Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Und die Priester brachten die Lade des Bundes Jehovas an ihren Ort, in den Sprachort des Hauses, in das Allerheiligste, unter die Flügel der Cherubim;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'denn die Cherubim breiteten die Flügel aus über den Ort der Lade, und die Cherubim bedeckten die Lade und ihre Stangen von oben her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Und die Stangen waren so lang, daß die Spitzen der Stangen von der Lade her an der Vorderseite des Sprachortes gesehen wurden; aber auswärts wurden sie nicht gesehen. Und sie sind daselbst bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Nichts war in der Lade, als nur die beiden Tafeln, welche Mose am Horeb hineinlegte, als Jehova einen Bund machte mit den Kindern Israel, als sie aus Ägypten zogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Und es geschah, als die Priester aus dem Heiligen herausgingen (denn alle Priester, die sich vorfanden, hatten sich geheiligt, ohne die Abteilungen zu beobachten)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'und als die Leviten, die Sänger, sie alle, nämlich Asaph, Heman, Jeduthun, und ihre Söhne und ihre Brüder, in Byssus gekleidet, mit Zimbeln und mit Harfen und Lauten auf der Ostseite des Altars standen, und mit ihnen an hundertzwanzig Priester, die mit Trompeten schmetterten, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'es geschah, als die Trompeter und die Sänger wie ein Mann waren, um eine Stimme ertönen zu lassen, Jehova zu loben und zu preisen, und als sie die Stimme erhoben mit Trompeten und mit Zimbeln und mit Musikinstrumenten und mit dem Lobe Jehovas, weil er gütig ist, weil seine Güte ewiglich währt: da wurde das Haus, das Haus Jehovas, mit einer Wolke erfüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Und die Priester vermochten wegen der Wolke nicht dazustehen, um den Dienst zu verrichten; denn die Herrlichkeit Jehovas erfüllte das Haus Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Damals sprach Salomo: Jehova hat gesagt, daß er im Dunkel wohnen wolle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Ich aber habe dir ein Haus gebaut zur Wohnung, und eine Stätte zu deinem Sitze für Ewigkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Und der König wandte sein Angesicht und segnete die ganze Versammlung Israels; und die ganze Versammlung Israels stand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Und er sprach: Gepriesen sei Jehova, der Gott Israels, der mit seinem Munde zu meinem Vater David geredet und mit seiner Hand es erfüllt hat, indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Von dem Tage an, da ich mein Volk aus dem Lande Ägypten herausführte, habe ich keine Stadt aus allen Stämmen Israels erwählt, um ein Haus zu bauen, damit mein Name daselbst wäre; und ich habe keinen Mann erwählt, um Fürst zu sein über mein Volk Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Aber ich habe Jerusalem erwählt, daß mein Name daselbst wäre; und ich habe David erwählt, daß er über mein Volk Israel wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Und es war in dem Herzen meines Vaters David, dem Namen Jehovas, des Gottes Israels, ein Haus zu bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Und Jehova sprach zu meinem Vater David: Weil es in deinem Herzen gewesen ist, meinem Namen ein Haus zu bauen, so hast du wohlgetan, daß es in deinem Herzen gewesen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Nur sollst du nicht das Haus bauen; sondern dein Sohn, der aus deinen Lenden hervorkommen wird, er soll meinem Namen das Haus bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Und Jehova hat sein Wort aufrecht gehalten, das er geredet hat; und ich bin aufgestanden an meines Vaters David Statt und habe mich auf den Thron Israels gesetzt, so wie Jehova geredet hat, und habe dem Namen Jehovas, des Gottes Israels, das Haus gebaut;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'und ich habe daselbst die Lade hingestellt, in welcher der Bund Jehovas ist, den er mit den Kindern Israel gemacht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Und er trat vor den Altar Jehovas, angesichts der ganzen Versammlung Israels, und er breitete seine Hände aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Denn Salomo hatte ein Gestell von Erz gemacht und es mitten in den Vorhof gestellt: fünf Ellen seine Länge, und fünf Ellen seine Breite, und drei Ellen seine Höhe; und er trat darauf und kniete, angesichts der ganzen Versammlung Israels, auf seine Knie nieder und breitete seine Hände aus gen Himmel');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'und sprach: Jehova, Gott Israels! Kein Gott ist dir gleich im Himmel und auf der Erde, der du den Bund und die Güte deinen Knechten bewahrst, die vor dir wandeln mit ihrem ganzen Herzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'der du deinem Knechte David, meinem Vater, gehalten, was du zu ihm geredet hast: du hast es mit deinem Munde geredet, und mit deiner Hand hast du es erfüllt, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Und nun, Jehova, Gott Israels, halte deinem Knechte David, meinem Vater, was du zu ihm geredet hast, indem du sprachst: Es soll dir nicht fehlen an einem Manne vor meinem Angesicht, der da sitze auf dem Throne Israels, wenn nur deine Söhne auf ihren Weg achthaben, daß sie in meinem Gesetze wandeln, so wie du vor mir gewandelt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Und nun, Jehova, Gott Israels, möge sich dein Wort bewähren, das du zu deinem Knechte David geredet hast! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Aber sollte Gott wirklich bei dem Menschen auf der Erde wohnen? Siehe, die Himmel und der Himmel Himmel können dich nicht fassen; wieviel weniger dieses Haus, das ich gebaut habe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Doch wende dich zu dem Gebet deines Knechtes und zu seinem Flehen, Jehova, mein Gott, daß du hörest auf das Rufen und auf das Gebet, welches dein Knecht vor dir betet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'daß deine Augen Tag und Nacht offen seien über dieses Haus, über den Ort, von dem du gesagt hast, daß du deinen Namen dahin setzen wollest; daß du hörest auf das Gebet, welches dein Knecht gegen diesen Ort hin beten wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Und höre auf das Flehen deines Knechtes und deines Volkes Israel, das sie gegen diesen Ort hin richten werden; und höre du von der Stätte deiner Wohnung, vom Himmel her, ja, höre und vergib!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Wenn jemand wider seinen Nächsten sündigt, und man ihm einen Eid auflegt, um ihn schwören zu lassen, und er kommt und schwört vor deinem Altar in diesem Hause:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'so höre du vom Himmel, und handle und richte deine Knechte, indem du dem Schuldigen vergiltst, daß du seinen Weg auf seinen Kopf bringst; und indem du den Gerechten gerecht sprichst, daß du ihm gibst nach seiner Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Und wenn dein Volk Israel vor dem Feinde geschlagen wird, weil sie wider dich gesündigt haben, und sie kehren um und bekennen deinen Namen und beten und flehen zu dir in diesem Hause:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'so höre du vom Himmel her und vergib die Sünde deines Volkes Israel; und bringe sie in das Land zurück, das du ihnen und ihren Vätern gegeben hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Wenn der Himmel verschlossen, und kein Regen sein wird, weil sie wider dich gesündigt haben, und sie beten gegen diesen Ort hin und bekennen deinen Namen und kehren um von ihrer Sünde, weil du sie demütigst:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'so höre du im Himmel und vergib die Sünde deiner Knechte und deines Volkes Israel, daß du ihnen den guten Weg zeigest, auf welchem sie wandeln sollen; und gib Regen auf dein Land, das du deinem Volke zum Erbteil gegeben hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Wenn eine Hungersnot im Lande sein wird, wenn Pest sein wird, wenn Kornbrand und Vergilben des Getreides, Heuschrecken oder Grillen sein werden; wenn seine Feinde es belagern im Lande seiner Tore, wenn irgend eine Plage und irgend eine Krankheit sein wird:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'welches Gebet, welches Flehen irgend geschehen wird von irgend einem Menschen und von deinem ganzen Volke Israel, wenn sie erkennen werden ein jeder seine Plage und seinen Schmerz, und er seine Hände ausbreitet gegen dieses Haus hin:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'so höre du vom Himmel her, der Stätte deiner Wohnung, und vergib, und gib einem jeden nach allen seinen Wegen, wie du sein Herz kennst, denn du, du allein kennst das Herz der Menschenkinder; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'auf daß sie dich fürchten, um auf deinen Wegen zu wandeln, alle die Tage, die sie in dem Lande leben werden, das du unseren Vätern gegeben hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Und auch auf den Fremden, der nicht von deinem Volke Israel ist, kommt er aus fernem Lande, um deines großen Namens und deiner starken Hand und deines ausgestreckten Armes willen, kommen sie und beten gegen dieses Haus hin:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'so höre du vom Himmel her, der Stätte deiner Wohnung, und tue nach allem, um was der Fremde zu dir rufen wird; auf daß alle Völker der Erde deinen Namen erkennen, und damit sie dich fürchten, wie dein Volk Israel, und damit sie erkennen, daß dieses Haus, welches ich gebaut habe, nach deinem Namen genannt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Wenn dein Volk ausziehen wird zum Streit wider seine Feinde, auf dem Wege, den du sie senden wirst, und sie zu dir beten nach dieser Stadt hin, die du erwählt hast, und dem Hause, das ich deinem Namen gebaut habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'so höre vom Himmel her ihr Gebet und ihr Flehen, und führe ihr Recht aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Wenn sie wider dich sündigen, denn da ist kein Mensch, der nicht sündigte und du über sie erzürnst und sie vor dem Feinde dahingibst und ihre Besieger sie gefangen wegführen in ein fernes oder in ein nahes Land;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'und sie nehmen es zu Herzen in dem Lande, wohin sie gefangen weggeführt sind, und kehren um und flehen zu dir in dem Lande ihrer Gefangenschaft, und sprechen: Wir haben gesündigt, wir haben verkehrt gehandelt und haben gesetzlos gehandelt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'und sie kehren zu dir um mit ihrem ganzen Herzen und mit ihrer ganzen Seele in dem Lande ihrer Gefangenschaft, wohin man sie gefangen weggeführt hat, und sie beten nach ihrem Lande hin, das du ihren Vätern gegeben, und der Stadt, die du erwählt hast, und nach dem Hause hin, das ich deinem Namen gebaut habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'so höre vom Himmel her, der Stätte deiner Wohnung, ihr Gebet und ihr Flehen, und führe ihr Recht aus; und vergib deinem Volke, was sie gegen dich gesündigt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Nun, mein Gott, laß doch deine Augen offen und deine Ohren aufmerksam sein auf das Gebet an diesem Orte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Und nun, stehe auf, Jehova Gott, zu deiner Ruhe, du und die Lade deiner Stärke! Laß deine Priester, Jehova Gott, bekleidet sein mit Rettung, und deine Frommen sich freuen des Guten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Jehova Gott! Weise nicht ab das Angesicht deines Gesalbten; gedenke der Gütigkeiten gegen David, deinen Knecht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Und als Salomo geendigt hatte zu beten, da fuhr das Feuer vom Himmel herab und verzehrte das Brandopfer und die Schlachtopfer; und die Herrlichkeit Jehovas erfüllte das Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Und die Priester konnten nicht in das Haus Jehovas hineingehen, denn die Herrlichkeit Jehovas erfüllte das Haus Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Und als alle Kinder Israel das Feuer herabfahren sahen und die Herrlichkeit Jehovas über dem Hause, da beugten sie sich, mit dem Antlitz zur Erde, auf das Pflaster und beteten an, und sie priesen Jehova, weil er gütig ist, weil seine Güte ewiglich währt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Und der König und das ganze Volk opferten Schlachtopfer vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Und der König Salomo opferte als Schlachtopfer zweiundzwanzigtausend Rinder und hundertzwanzigtausend Schafe. Und der König und das ganze Volk weihten das Haus Gottes ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Und die Priester standen auf ihren Posten, und die Leviten mit den Musikinstrumenten Jehovas, die der König David gemacht hatte, um Jehova zu preisen, denn seine Güte währt ewiglich, wenn David durch sie lobpries; und die Priester trompeteten ihnen gegenüber, und ganz Israel stand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Und Salomo heiligte die Mitte des Hofes, der vor dem Hause Jehovas lag; denn er opferte daselbst die Brandopfer und die Fettstücke der Friedensopfer; denn der eherne Altar, den Salomo gemacht hatte, konnte das Brandopfer und das Speisopfer und die Fettstücke nicht fassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Und so feierten Salomo und ganz Israel mit ihm, eine sehr große Versammlung, von dem Eingang Hamaths bis an den Fluß Ägyptens, zu selbiger Zeit das Fest sieben Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Und am achten Tage hielten sie eine Festversammlung; denn sie feierten die Einweihung des Altars sieben Tage und das Fest sieben Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Und am dreiundzwanzigsten Tage des siebten Monats entließ er das Volk nach ihren Zelten, fröhlich und gutes Mutes wegen des Guten, das Jehova dem David und dem Salomo und seinem Volke Israel erwiesen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Und so vollendete Salomo das Haus Jehovas und das Haus des Königs; und alles, was Salomo ins Herz gekommen war, im Hause Jehovas und in seinem Hause zu machen, war ihm gelungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Da erschien Jehova dem Salomo in der Nacht und sprach zu ihm: Ich habe dein Gebet gehört und mir diesen Ort zum Opferhause erwählt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Wenn ich den Himmel verschließe, und kein Regen sein wird, und wenn ich der Heuschrecke gebiete, das Land abzufressen, und wenn ich eine Pest unter mein Volk sende;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'und mein Volk, welches nach meinem Namen genannt wird, demütigt sich, und sie beten und suchen mein Angesicht, und kehren um von ihren bösen Wegen: so werde ich vom Himmel her hören und ihre Sünden vergeben und ihr Land heilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Nun werden meinen Augen offen und meine Ohren aufmerksam sein auf das Gebet an diesem Orte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Und nun habe ich dieses Haus erwählt und geheiligt, daß mein Name daselbst sei ewiglich; und meine Augen und mein Herz sollen daselbst sein alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Und du, wenn du vor mir wandeln wirst, so wie dein Vater David gewandelt hat, daß du tust nach allem, was ich dir geboten habe, und wenn du meine Satzungen und meine Rechte beobachten wirst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'so werde ich den Thron deines Königtums befestigen, so wie ich mit deinem Vater David einen Bund gemacht und gesagt habe: Es soll dir nicht an einem Manne fehlen, der über Israel herrsche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Wenn ihr euch aber abwenden und meine Satzungen und meine Gebote, die ich euch vorgelegt habe, verlassen werdet, und werdet hingehen und anderen Göttern dienen und euch vor ihnen niederbeugen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'so werde ich sie herausreißen aus meinem Lande, das ich ihnen gegeben habe; und dieses Haus, welches ich meinem Namen geheiligt habe, werde ich von meinem Angesicht wegwerfen, und werde es zum Sprichwort und zur Spottrede machen unter allen Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Und dieses Haus, das erhaben war jeder, der an demselben vorbeigeht, wird sich entsetzen und sagen: Warum hat Jehova diesem Lande und diesem Hause also getan?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Und man wird sagen: Darum, daß sie Jehova, den Gott ihrer Väter, der sie aus dem Lande Ägypten herausgeführt hat, verlassen und andere Götter angenommen und sich vor ihnen niedergebeugt und ihnen gedient haben; darum hat er all dieses Unglück über sie gebracht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Und es geschah am Ende von zwanzig Jahren, während welcher Salomo das Haus Jehovas und sein Haus gebaut hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'da baute Salomo die Städte aus, welche Huram dem Salomo gegeben hatte; und er ließ die Kinder Israel daselbst wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Und Salomo zog nach Hamath-Zoba und überwältigte es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Und er baute Tadmor in der Wüste und alle Vorratsstädte, die er in Hamath baute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Und er baute Ober-Beth-Horon und Unter-Beth-Horon, feste Städte mit Mauern, Toren und Riegeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'und Baalath und alle Vorratsstädte, die Salomo hatte; und alle Wagenstädte und die Reiterstädte; und alles, was Salomo Lust hatte zu bauen in Jerusalem und auf dem Libanon und im ganzen Lande seiner Herrschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Alles Volk, das übriggeblieben war von den Hethitern und den Amoritern und den Perisitern und den Hewitern und den Jebusitern, die nicht von Israel waren:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'ihre Söhne, die nach ihnen im Lande übriggeblieben waren, welche die Kinder Israel nicht vertilgt hatten, die hob Salomo zu Fronarbeitern aus bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Aber aus den Kindern Israel machte Salomo keine Sklaven für seine Arbeit; sondern sie waren Kriegsleute und Oberste seiner Anführer und Oberste seiner Wagen und seiner Reiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Und dies sind die Oberaufseher, welche der König Salomo hatte: zweihundertfünfzig, die über das Volk walteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Und Salomo führte die Tochter des Pharao aus der Stadt Davids herauf in das Haus, das er ihr gebaut hatte; denn er sprach: Mein Weib soll nicht in dem Hause Davids, des Königs von Israel, wohnen; denn die Orte sind heilig, in welche die Lade Jehovas gekommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Damals opferte Salomo dem Jehova Brandopfer auf dem Altar Jehovas, den er vor der Halle gebaut hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'und zwar nach der täglichen Gebühr, indem er nach dem Gebot Moses opferte an den Sabbathen und an den Neumonden, und an den Festen dreimal im Jahre: am Feste der ungesäuerten Brote und am Feste der Wochen und am Feste der Laubhütten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Und er bestellte nach der Vorschrift seines Vaters David die Abteilungen der Priester zu ihrem Dienste; und die Leviten zu ihren Ämtern, um zu loben und zu dienen vor den Priestern, nach der täglichen Gebühr; und die Torhüter in ihren Abteilungen für jedes Tor; denn also war das Gebot Davids, des Mannes Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Und man wich nicht von dem Gebot des Königs an die Priester und die Leviten ab betreffs jeder Sache und betreffs der Schätze. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Und so wurde das ganze Werk Salomos zustande gebracht, bis zum Tage der Gründung des Hauses Jehovas und bis zur Vollendung desselben. Das Haus Jehovas war fertig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Damals ging Salomo nach Ezjon-Geber und nach Eloth, am Ufer des Meeres im Lande Edom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Und Huram sandte ihm durch seine Knechte Schiffe und Knechte, die des Meeres kundig waren. Und sie kamen mit den Knechten Salomos nach Ophir und holten von dort vierhundertfünfzig Talente Gold und brachten es zu dem König Salomo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Und die Königin von Scheba hörte den Ruf Salomos; und sie kam nach Jerusalem, um Salomo mit Rätseln zu versuchen, mit einem sehr großen Zuge und mit Kamelen, die Gewürze und Gold trugen in Menge und Edelsteine. Und sie kam zu Salomo und redete mit ihm alles, was in ihrem Herzen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Und Salomo erklärte ihr alles, um was sie fragte; und keine Sache war vor Salomo verborgen, die er ihr nicht erklärt hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Und als die Königin von Scheba die Weisheit Salomos sah, und das Haus, das er gebaut hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'und die Speise seines Tisches, und das Sitzen seiner Knechte, und das Aufwarten seiner Diener, und ihre Kleidung, und seine Mundschenken und ihre Kleidung, und seinen Aufgang, auf welchem er in das Haus Jehovas hinaufging,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'da geriet sie außer sich und sprach zu dem König: Das Wort ist Wahrheit gewesen, das ich in meinem Lande über deine Sachen und über deine Weisheit gehört habe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'und ich habe ihren Worten nicht geglaubt, bis ich gekommen bin und meine Augen es gesehen haben. Und siehe, nicht die Hälfte ist mir berichtet worden von der Größe deiner Weisheit; du übertriffst das Gerücht, das ich gehört habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Glückselig sind deine Leute, und glückselig diese deine Knechte, die beständig vor dir stehen und deine Weisheit hören!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Gepriesen sei Jehova, dein Gott, der Gefallen an dir gehabt hat, dich auf seinen Thron zu setzen als König für Jehova, deinen Gott! Weil dein Gott Israel liebt, um es ewiglich bestehen zu lassen, so hat er dich zum König über sie gesetzt, um Recht und Gerechtigkeit zu üben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Und sie gab dem König hundertzwanzig Talente Gold, und Gewürze in großer Menge und Edelsteine; und nie ist dergleichen Gewürz gewesen wie dieses, welches die Königin von Scheba dem König Salomo gab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, '(Und auch die Knechte Hurams und die Knechte Salomos, welche Gold aus Ophir holten, brachten Sandelholz und Edelsteine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Und der König machte von dem Sandelholz Stiegen für das Haus Jehovas und für das Haus des Königs, und Lauten und Harfen für die Sänger; und desgleichen ist vordem nicht gesehen worden im Lande Juda.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Und der König Salomo gab der Königin von Scheba all ihr Begehr, das sie verlangte, außer dem Gegengeschenk für das, was sie dem König gebracht hatte. Und sie wandte sich und zog in ihr Land, sie und ihre Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Und das Gewicht des Goldes, welches dem Salomo in einem Jahre einkam, war sechshundertsechsundsechzig Talente Gold,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'außer dem, was die Krämer und die Handelsleute brachten; und alle Könige von Arabien und die Statthalter des Landes brachten dem Salomo Gold und Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Und der König Salomo machte zweihundert Schilde von getriebenem Golde: sechshundert Sekel getriebenes Gold zog er über jeden Schild;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'und dreihundert Tartschen von getriebenem Golde: dreihundert Sekel Gold zog er über jede Tartsche; und der König tat sie in das Haus des Waldes Libanon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Und der König machte einen großen Thron von Elfenbein und überzog ihn mit reinem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Und sechs Stufen waren an dem Throne und ein goldener Fußschemel, die an dem Throne befestigt waren; und Armlehnen waren auf dieser und auf jener Seite an der Stelle des Sitzes, und zwei Löwen standen neben den Armlehnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'und zwölf Löwen standen da auf den sechs Stufen, auf dieser und auf jener Seite. Desgleichen ist nicht gemacht worden in irgend einem Königreiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Und alle Trinkgefäße des Königs Salomo waren von Gold, und alle Geräte des Hauses des Waldes Libanon waren von geläutertem Golde; das Silber wurde für nichts geachtet in den Tagen Salomos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Denn die Schiffe des Königs fuhren nach Tarsis mit den Knechten Hurams; einmal in drei Jahren kamen Tarsisschiffe, beladen mit Gold und Silber, Elfenbein und Affen und Pfauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Und der König Salomo war größer als alle Könige der Erde an Reichtum und Weisheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Und alle Könige der Erde suchten das Angesicht Salomos, um seine Weisheit zu hören, die Gott in sein Herz gegeben hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Und sie brachten ein jeder sein Geschenk: Geräte von Silber und Geräte von Gold und Gewänder, Waffen und Gewürze, Rosse und Maultiere, jährlich die Gebühr des Jahres.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Und Salomo hatte viertausend Stände für Rosse und Wagen und zwölftausend Reiter; und er verlegte sie in die Wagenstädte und zu dem König nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Und er war Herrscher über alle Könige, von dem Strome an bis zu dem Lande der Philister und bis zu der Grenze Ägyptens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Und der König machte das Silber in Jerusalem den Steinen gleich, und die Zedern machte er den Sykomoren gleich, die in der Niederung sind, an Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Und man führte Rosse aus für Salomo aus Ägypten und aus allen Ländern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Und das Übrige der Geschichte Salomos, die erste und die letzte, ist das nicht geschrieben in der Geschichte Nathans, des Propheten, und in der Weissagung Achijas, des Siloniters, und in den Gesichten Iddos, des Sehers, über Jerobeam, den Sohn Nebats?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Und Salomo regierte zu Jerusalem vierzig Jahre über ganz Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Und Salomo legte sich zu seinen Vätern, und man begrub ihn in der Stadt seines Vaters David. Und Rehabeam, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Und Rehabeam ging nach Sichem; denn ganz Israel war nach Sichem gekommen, um ihn zum König zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Und es geschah, als Jerobeam, der Sohn Nebats, es hörte (er war aber in Ägypten, wohin er vor dem König Salomo geflohen war), da kehrte Jerobeam aus Ägypten zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Und sie sandten hin und riefen ihn. Und Jerobeam und ganz Israel kamen und redeten zu Rehabeam und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Dein Vater hat unser Joch hart gemacht; und nun erleichtere den harten Dienst deines Vaters und sein schweres Joch, das er auf uns gelegt hat, so wollen wir dir dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Und er sprach zu ihnen: Noch drei Tage, dann kommet wieder zu mir. Und das Volk ging hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Und der König Rehabeam beriet sich mit den Alten, die vor seinem Vater Salomo gestanden hatten, als er noch am Leben war, und sprach: Wie ratet ihr, diesem Volke Antwort zu geben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Und sie redeten zu ihm und sprachen: Wenn du gegen dieses Volk gütig und ihnen gefällig bist und gütige Worte zu ihnen redest, so werden sie deine Knechte sein alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Aber er verließ den Rat der Alten, den sie ihm gegeben hatten; und er beriet sich mit den Jungen, die mit ihm aufgewachsen waren, die vor ihm standen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Und er sprach zu ihnen: Was ratet ihr, daß wir diesem Volke zur Antwort geben, welches zu mir geredet und gesagt hat: Erleichtere das Joch, das dein Vater auf uns gelegt hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Und die Jungen, die mit ihm aufgewachsen waren, redeten zu ihm und sprachen: So sollst du zu dem Volke sprechen, das zu dir geredet und gesagt hat: Dein Vater hat unser Joch schwer gemacht, du aber erleichtere es uns; so sollst du zu ihnen reden: Mein kleiner Finger ist dicker als die Lenden meines Vaters!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Nun denn, mein Vater hat euch ein schweres Joch aufgeladen, ich aber will zu eurem Joche hinzutun; mein Vater hat euch mit Geißeln gezüchtigt, ich aber will euch mit Skorpionen züchtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Und Jerobeam und alles Volk kamen zu Rehabeam am dritten Tage, so wie der König geredet und gesagt hatte: Kommet am dritten Tage wieder zu mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Und der König antwortete ihnen hart; und der König Rehabeam verließ den Rat der Alten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'und redete zu ihnen nach dem Rate der Jungen und sprach: Mein Vater hat euer Joch schwer gemacht, ich aber will zu demselben hinzutun; mein Vater hat euch mit Geißeln gezüchtigt, ich aber will euch mit Skorpionen züchtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'So hörte der König nicht auf das Volk; denn es war eine Wendung von seiten Gottes, auf daß Jehova sein Wort aufrecht hielte, welches er durch Achija, den Siloniter, zu Jerobeam, dem Sohne Nebats, geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Und als ganz Israel sah, daß der König nicht auf sie hörte, da antwortete das Volk dem König und sprach: Was haben wir für Teil an David? Und wir haben kein Erbteil am Sohne Isais! Ein jeder zu seinen Zelten, Israel! Nun sieh nach deinem Hause, David! Und ganz Israel ging nach seinen Zelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Die Kinder Israel aber, die in den Städten Judas wohnten, über sie wurde Rehabeam König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Und der König Rehabeam sandte Hadoram, der über die Fron war; aber die Kinder Israel steinigten ihn, und er starb. Da eilte der König Rehabeam, den Wagen zu besteigen, um nach Jerusalem zu fliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'So fiel Israel vom Hause Davids ab bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Und Rehabeam kam nach Jerusalem; und er versammelte das Haus Juda und Benjamin, hundertachtzigtausend auserlesene Krieger, um mit Israel zu streiten, damit er das Königreich an Rehabeam zurückbrächte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Da geschah das Wort Jehovas zu Schemaja, dem Manne Gottes, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Sage zu Rehabeam, dem Sohne Salomos, dem König von Juda, und zu ganz Israel in Juda und Benjamin, und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'So spricht Jehova: Ihr sollt nicht hinaufziehen und nicht mit euren Brüdern streiten; kehret um, ein jeder nach seinem Hause, denn von mir aus ist diese Sache geschehen. Und sie hörten auf die Worte Jehovas und kehrten um von dem Zuge wider Jerobeam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Und Rehabeam wohnte in Jerusalem; und er baute Städte zu Festungen in Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Und er baute Bethlehem und Etam und Tekoa,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'und Beth-Zur und Soko und Adullam,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'und Gath und Marescha und Siph,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'und Adoraim und Lachis und Aseka,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'und Zora und Ajalon und Hebron, die in Juda und Benjamin liegen, feste Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Und er machte die Festungen stark, und legte Befehlshaber darein und Vorräte von Speise und Öl und Wein,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'und in jede Stadt Schilde und Lanzen; und er machte sie überaus stark. Und Juda und Benjamin gehörten ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Und die Priester und die Leviten, die in ganz Israel waren, stellten sich bei ihm ein aus allen ihren Grenzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Denn die Leviten verließen ihre Bezirke und ihr Besitztum und zogen nach Juda und nach Jerusalem; denn Jerobeam und seine Söhne hatten sie aus dem Priesterdienst Jehovas verstoßen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'und er hatte sich Priester bestellt zu den Höhen und zu den Böcken und zu den Kälbern, die er gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Und ihnen folgten aus allen Stämmen Israels die, welche ihr Herz darauf richteten, Jehova, den Gott Israels, zu suchen; sie kamen nach Jerusalem, um Jehova, dem Gott ihrer Väter, zu opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Und sie stärkten das Königreich Juda und befestigten Rehabeam, den Sohn Salomos, drei Jahre lang; denn drei Jahre lang wandelten sie auf dem Wege Davids und Salomos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Und Rehabeam nahm sich zum Weibe Machalath, die Tochter Jerimoths, des Sohnes Davids, und Abichails, der Tochter Eliabs, des Sohnes Isais.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Und sie gebar ihm Söhne: Jeusch und Schemarja und Saham.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Und nach ihr nahm er Maaka, die Tochter Absaloms; und sie gabar ihm Abija und Attai und Sisa und Schelomith.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Und Rehabeam liebte Maaka, die Tochter Absaloms, mehr als alle seine Weiber und seine Kebsweiber; denn er hatte achtzehn Weiber genommen und sechzig Kebsweiber; und er zeugte achtundzwanzig Söhne und sechzig Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Und Rehabeam bestellte Abija, den Sohn der Maaka, zum Haupte, zum Fürsten unter seinen Brüdern; denn er gedachte ihn zum König zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Und er handelte verständig und verteilte alle seine Söhne in alle Länder Judas und Benjamins, in alle festen Städte, und gab ihnen Lebensunterhalt in Fülle, und begehrte für sie eine Menge Weiber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Und es geschah, als das Königtum Rehabeams befestigt, und er stark geworden war, verließ er das Gesetz Jehovas, und ganz Israel mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Und es geschah im fünften Jahre des Königs Rehabeam, da zog Sisak, der König von Ägypten, mit tausendzweihundert Wagen und mit sechstausend Reitern wider Jerusalem herauf, weil sie treulos gegen Jehova gehandelt hatten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'und ohne Zahl war das Volk, welches mit ihm aus Ägypten kam: Libyer, Sukkiter und Äthiopier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Und er nahm die festen Städte ein, die Juda gehörten, und kam bis nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Da kam Schemaja, der Prophet, zu Rehabeam und zu den Obersten von Juda, die sich vor Sisak nach Jerusalem zurückgezogen hatten, und sprach zu ihnen: So spricht Jehova: Ihr habt mich verlassen, so habe auch ich euch der Hand Sisaks überlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Und die Obersten von Israel und der König demütigten sich und sprachen: Jehova ist gerecht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Und als Jehova sah, daß sie sich gedemütigt hatten, geschah das Wort Jehovas zu Schemaja also: Sie haben sich gedemütigt: Ich will sie nicht verderben, und will ihnen ein wenig Errettung geben, und mein Grimm soll sich nicht durch Sisak über Jerusalem ergießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Doch sollen sie ihm zu Knechten sein, damit sie meinen Dienst kennen lernen und den Dienst der Königreiche der Länder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Und Sisak, der König von Ägypten, zog wider Jerusalem herauf. Und er nahm die Schätze des Hauses Jehovas weg und die Schätze des Hauses des Königs: alles nahm er weg; und er nahm die goldenen Schilde weg, die Salomo gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Und der König Rehabeam machte an ihrer Statt eherne Schilde, und er befahl sie unter die Hand der Obersten der Läufer, die den Eingang des Hauses des Königs bewachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Und es geschah: so oft der König in das Haus Jehovas ging, kamen die Läufer und trugen dieselben und brachten sie dann wieder in das Gemach der Läufer zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Und als er sich demütigte, wandte sich der Zorn Jehovas von ihm ab, so daß er ihn nicht völlig verderbte; und auch war in Juda noch etwas Gutes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Und der König Rehabeam erstarkte zu Jerusalem und regierte; denn Rehabeam war einundvierzig Jahre alt, als er König wurde, und er regierte siebzehn Jahre zu Jerusalem, der Stadt, die Jehova aus allen Stämmen Israels erwählt hatte, um seinen Namen dahin zu setzen. Und der Name seiner Mutter war Naama, die Ammonitin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Und er tat, was böse war; denn er richtete sein Herz nicht darauf, Jehova zu suchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Und die Geschichte Rehabeams, die erste und die letzte, ist sie nicht geschrieben in der Geschichte Schemajas, des Propheten, und Iddos, des Sehers, in den Geschlechtsverzeichnissen? Und die Kriege Rehabeams und Jerobeams währten immerfort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Und Rehabeam legte sich zu seinen Vätern, und er wurde begraben in der Stadt Davids. Und Abija, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Im achtzehnten Jahre des Königs Jerobeam, da wurde Abija König über Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Er regierte drei Jahre zu Jerusalem; und der Name seiner Mutter war Mikaja, die Tochter Uriels von Gibea. Und es war Krieg zwischen Abija und Jerobeam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Und Abija eröffnete den Krieg mit einem Heere von tapferen Kriegern, vierhunderttausend auserlesenen Männern; und Jerobeam stellte sich gegen ihn in Schlachtordnung auf mit achthunderttausend auserlesenen Männern, tapferen Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Da stellte sich Abija oben auf den Berg Zemaraim, der im Gebirge Ephraim liegt, und sprach: Höret mich, Jerobeam und ganz Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Solltet ihr nicht wissen, daß Jehova, der Gott Israels, das Königtum über Israel dem David gegeben hat ewiglich, ihm und seinen Söhnen durch einen Salzbund?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Aber Jerobeam, der Sohn Nebats, der Knecht Salomos, des Sohnes Davids, erhob sich und empörte sich wider seinen Herrn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'und es versammelten sich zu ihm lose Männer, Söhne Belials, und widersetzten sich Rehabeam, dem Sohne Salomos; Rehabeam aber war ein Jüngling und schwachen Herzens, und er hielt nicht stand vor ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Und nun gedenket ihr stand zu halten vor dem Königtum Jehovas in der Hand der Söhne Davids, weil ihr eine große Menge seid, und die goldenen Kälber bei euch sind, die Jerobeam euch zu Göttern gemacht hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Habt ihr nicht die Priester Jehovas, die Söhne Aarons, und die Leviten verstoßen, und euch Priester gemacht wie die Völker der Länder? Wer irgend mit einem jungen Farren und sieben Widdern kam, um sich weihen zu lassen, der wurde ein Priester der Nicht-Götter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Wir aber, Jehova ist unser Gott, und wir haben ihn nicht verlassen; und Priester, Söhne Aarons, dienen Jehova, und die Leviten sind in ihrem Geschäft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'und sie räuchern dem Jehova Brandopfer Morgen für Morgen und Abend für Abend, und wohlriechendes Räucherwerk; und wir haben das Schichtbrot auf dem reinen Tische, und den goldenen Leuchter und seine Lampen zum Anzünden Abend für Abend; denn wir warten der Hut Jehovas, unseres Gottes; ihr aber habt ihn verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Und siehe, Gott ist mit uns an unserer Spitze und seine Priester, und die Lärmtrompeten, um Lärm zu blasen wider euch. Kinder Israel! Streitet nicht wider Jehova, den Gott eurer Väter; denn es wird euch nicht gelingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Aber Jerobeam ließ den Hinterhalt eine Umgehung machen, daß er ihnen in den Rücken käme; und so standen sie im Angesicht Judas und der Hinterhalt in ihrem Rücken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Und als Juda sich umsah, siehe, da hatten sie den Streit vorn und hinten. Da schrieen sie zu Jehova, und die Priester bliesen mit den Trompeten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'und die Männer von Juda erhoben ein Kriegsgeschrei. Und es geschah, als die Männer von Juda das Kriegsgeschrei erhoben, da schlug Gott Jerobeam und ganz Israel vor Abija und Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Und die Kinder Israel flohen vor Juda, und Gott gab sie in ihre Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Und Abija und sein Volk richteten eine große Niederlage unter ihnen an, und es fielen von Israel Erschlagene, fünfhunderttausend auserlesene Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Und die Kinder Israel wurden gedemütigt zu selbiger Zeit; aber die Kinder Juda wurden stark, weil sie sich auf Jehova, den Gott ihrer Väter, gestützt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Und Abija jagte Jerobeam nach, und er nahm ihm Städte weg: Bethel und seine Tochterstädte, und Jeschana und seine Tochterstädte, und Ephron und seine Tochterstädte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Und Jerobeam behielt keine Kraft mehr in den Tagen Abijas. Und Jehova schlug ihn, und er starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Abija aber erstarkte. Und er nahm vierzehn Weiber und zeugte zweiundzwanzig Söhne und sechzehn Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Und das Übrige der Geschichte Abijas und seine Wege und seine Reden sind geschrieben in der Beschreibung des Propheten Iddo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Und Abija legte sich zu seinen Vätern, und man begrub ihn in der Stadt Davids. Und Asa, sein Sohn, ward König an seiner Statt. In seinen Tagen hatte das Land Ruhe zehn Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Und Asa tat, was gut und recht war in den Augen Jehovas, seines Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Und er tat die fremden Altäre und die Höhen hinweg, und zerschlug die Bildsäulen und hieb die Ascherim um;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'und er sprach zu Juda, daß sie Jehova, den Gott ihrer Väter, suchen und das Gesetz und das Gebot tun sollten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'und er tat aus allen Städten Judas die Höhen und die Sonnensäulen hinweg. Und das Königreich hatte Ruhe unter ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Und er baute feste Städte in Juda; denn das Land hatte Ruhe, und es war kein Krieg wider ihn in jenen Jahren, denn Jehova hatte ihm Ruhe geschafft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Und er sprach zu Juda: Laßt uns diese Städte bauen, und Mauern ringsum machen und Türme, Tore und Riegel; noch ist das Land vor uns, denn wir haben Jehova, unseren Gott, gesucht; wir haben ihn gesucht, und er hat uns Ruhe geschafft ringsumher. Und so bauten sie, und es gelang ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Und Asa hatte ein Heer, das Schild und Lanze trug: aus Juda dreihunderttausend und aus Benjamin zweihundertachtzigtausend Mann, die Tartschen trugen und den Bogen spannten: sämtlich tapfere Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Und Serach, der Kuschiter, zog wider sie aus mit einem Heere von tausendmal tausend Mann, und dreihundert Wagen; und er kam bis Marescha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Und Asa zog ihm entgegen; und sie stellten sich in Schlachtordnung auf im Tale Zephata bei Marescha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Und Asa rief zu Jehova, seinem Gott, und sprach: Jehova! Um zu helfen, ist bei dir kein Unterschied zwischen dem Mächtigen und dem Kraftlosen. Hilf uns, Jehova, unser Gott! Denn wir stützen uns auf dich, und in deinem Namen sind wir wider diese Menge gezogen. Du bist Jehova, unser Gott; laß den Menschen nichts wider dich vermögen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Und Jehova schlug die Kuschiter vor Asa und vor Juda; und die Kuschiter flohen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Und Asa und das Volk, das bei ihm war, jagten ihnen nach bis Gerar. Und es fielen von den Kuschitern so viele, daß sie sich nicht wieder erholen konnten; denn sie wurden zerschmettert vor Jehova und vor seinem Heere. Und sie trugen sehr viel Beute davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Auch schlugen sie alle Städte rings um Gerar, denn der Schrecken Jehovas war auf ihnen; und sie beraubten alle die Städte, denn es war viel Raubes darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Und auch die Herdenzelte schlugen sie und führten Kleinvieh in Menge weg und Kamele. Und sie kehrten nach Jerusalem zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Und auf Asarja, den Sohn Odeds, kam der Geist Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Und er ging hinaus, Asa entgegen, und sprach zu ihm: Höret mich, Asa und ganz Juda und Benjamin! Jehova ist mit euch, wenn ihr mit ihm seid. Und wenn ihr ihn suchet, wird er sich von euch finden lassen; wenn ihr ihn aber verlasset, wird er euch verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Und Israel war viele Tage ohne wahren Gott und ohne lehrenden Priester und ohne Gesetz;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'aber in ihrer Bedrängnis kehrten sie um zu Jehova, dem Gott Israels; und sie suchten ihn, und er ließ sich von ihnen finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Und in jenen Zeiten war kein Friede für den Ausgehenden und für den Eingehenden; sondern viele Unruhen kamen über alle Bewohner der Länder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Und es stieß sich Nation an Nation und Stadt an Stadt; denn Gott beunruhigte sie durch allerlei Bedrängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Ihr aber, seid stark und lasset eure Hände nicht erschlaffen, denn es gibt Lohn für euer Tun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Und als Asa diese Worte und die Weissagung Odeds, des Propheten, hörte, faßte er Mut; und er schaffte die Greuel weg aus dem ganzen Lande Juda und Benjamin und aus den Städten, die er vom Gebirge Ephraim eingenommen hatte, und er erneuerte den Altar Jehovas, der vor der Halle Jehovas stand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Und er versammelte ganz Juda und Benjamin und die Fremdlinge, die aus Ephraim und Manasse und aus Simeon bei ihnen lebten; denn in Menge liefen sie aus Israel zu ihm über, als sie sahen, daß Jehova, sein Gott, mit ihm war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Und sie versammelten sich zu Jerusalem im dritten Monat, im fünfzehnten Jahre der Regierung Asas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'und sie opferten Jehova an selbigem Tage von der Beute, die sie eingebracht hatten, siebenhundert Rinder und siebentausend Schafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Und sie gingen den Bund ein, Jehova, den Gott ihrer Väter, zu suchen mit ihrem ganzen Herzen und mit ihrer ganzen Seele;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'jeder aber, der Jehova, den Gott Israels, nicht suchen würde, sollte getötet werden, vom Kleinsten bis zum Größten, vom Manne bis zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Und sie schwuren Jehova mit lauter Stimme und mit Jauchzen und unter Trompeten-und Posaunenschall.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Und ganz Juda freute sich des Eides; denn sie schwuren mit ihrem ganzen Herzen und suchten Jehova mit ihrem ganzen Willen; und er ließ sich von ihnen finden. Und Jehova schaffte ihnen Ruhe ringsumher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Und auch Maaka, die Mutter des Königs Asa, setzte er ab, daß sie nicht mehr Königin wäre, weil sie der Aschera ein Götzenbild gemacht hatte; und Asa rottete ihr Götzenbild aus und zermalmte und verbrannte es im Tale Kidron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Die Höhen aber wichen nicht aus Israel; doch das Herz Asas war ungeteilt alle seine Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Und er brachte die geheiligten Dinge seines Vaters und seine geheiligten Dinge in das Haus Gottes: Silber und Gold und Geräte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Und es war kein Krieg bis zum fünfunddreißigsten Jahre der Regierung Asas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Im sechsunddreißigsten Jahre der Regierung Asas zog Baesa, der König von Israel, wider Juda herauf; und er baute Rama, um Asa, dem König von Juda, niemand aus-und eingehen zu lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Da brachte Asa Silber und Gold heraus aus den Schätzen des Hauses Jehovas und des Hauses des Königs; und er sandte zu Ben-Hadad, dem König von Syrien, der zu Damaskus wohnte, und ließ ihm sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Ein Bund ist zwischen mir und dir und zwischen meinem Vater und deinem Vater. Siehe, ich sende dir Silber und Gold; wohlan! Brich deinen Bund mit Baesa, dem König von Israel, daß er von mir abziehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Und Ben-Hadad hörte auf den König Asa, und er sandte seine Heerobersten wider die Städte Israels; und sie schlugen Ijon und Dan und Abel-Majim und alle Vorratsplätze der Städte Naphtalis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Und es geschah, als Baesa es hörte, da ließ er von dem Bau Ramas ab und stellte seine Arbeit ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Der König Asa aber nahm ganz Juda, und sie schafften die Steine Ramas und dessen Holz weg, womit Baesa gebaut hatte; und er baute damit Geba und Mizpa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Und zu selbiger Zeit kam Hanani, der Seher, zu Asa, dem König von Juda, und sprach zu ihm: Weil du dich auf den König von Syrien gestützt hast, und hast dich nicht auf Jehova, deinen Gott, gestützt, darum ist das Heer des Königs von Syrien deiner Hand entronnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Waren nicht die Kuschiter und die Libyer eine zahlreiche Heeresmacht, mit Wagen und Reitern in großer Menge? Aber weil du dich auf Jehova stütztest, gab er sie in deine Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Denn Jehovas Augen durchlaufen die ganze Erde, um sich mächtig zu erweisen an denen, deren Herz ungeteilt auf ihn gerichtet ist. Hierin hast du töricht gehandelt; denn von nun an wirst du Kriege haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Und Asa wurde ärgerlich über den Seher und legte ihn in das Stockhaus; denn er war dieserhalb gegen ihn erzürnt. Auch tat Asa zu selbiger Zeit etlichen von dem Volke Gewalt an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Und siehe, die Geschichte Asas, die erste und die letzte, siehe, sie ist geschrieben in dem Buche der Könige von Juda und Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Und im neununddreißigsten Jahre seiner Regierung erkrankte Asa an seinen Füßen, so daß er überaus krank war; aber auch in seiner Krankheit suchte er nicht Jehova, sondern die Ärzte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Und Asa legte sich zu seinen Vätern; und er starb im einundvierzigsten Jahre seiner Regierung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Und man begrub ihn in seinem Begräbnis, das er sich in der Stadt Davids gegraben hatte. Und man legte ihn auf ein Lager, das man gefüllt hatte mit Gewürz und Spezereien, gemischt nach der Kunst der Salbenmischung; und man veranstaltete für ihn einen sehr großen Brand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Und Josaphat, sein Sohn, ward König an seiner Statt. Und er stärkte sich wider Israel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'und er legte Kriegsvolk in alle festen Städte Judas und legte Besatzungen in das Land Juda und in die Städte Ephraims, die sein Vater Asa eingenommen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Und Jehova war mit Josaphat; denn er wandelte auf den früheren Wegen seines Vaters David und suchte nicht die Baalim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'sondern er suchte den Gott seines Vaters, und er wandelte in seinen Geboten und nicht nach dem Tun Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Und Jehova befestigte das Königtum in seiner Hand; und ganz Juda gab Josaphat Geschenke, und er hatte Reichtum und Ehre in Fülle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Und sein Herz gewann Mut auf den Wegen Jehovas, und er tat noch die Höhen und die Ascherim aus Juda hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Und im dritten Jahre seiner Regierung sandte er seine Obersten Ben-Hail und Obadja und Sekarja und Nethaneel und Mikaja, daß sie in den Städten Judas lehren sollten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'und mit ihnen die Leviten Schemaja und Nethanja und Sebadja und Asael und Schemiramoth und Jonathan und Adonija und Tobija und Tob-Adonija, die Leviten; und mit ihnen Elischama und Joram, die Priester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Und sie lehrten in Juda, indem sie das Buch des Gesetzes Jehovas bei sich hatten, und zogen umher durch alle Städte Judas und lehrten unter dem Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Und der Schrecken Jehovas kam auf alle Königreiche der Länder, die rings um Juda waren, so daß sie nicht wider Josaphat stritten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Und die Philister brachten Josaphat Geschenke und Silber als Tribut; auch die Araber brachten ihm Kleinvieh, siebentausendsiebenhundert Widder, und siebentausendsiebenhundert Böcke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Und Josaphat wurde immerfort größer, bis er überaus groß war. Und er baute in Juda Burgen und Vorratsstädte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'und er hatte große Vorräte in den Städten Judas, und Kriegsmänner, tapfere Helden, in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Und dies war ihre Einteilung nach ihren Vaterhäusern: Von Juda waren Oberste über Tausende: Adna, der Oberste, und mit ihm dreihunderttausend tapfere Helden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'und neben ihm Jochanan, der Oberste, und mit ihm zweihundertachtzigtausend;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'und neben ihm Amasja, der Sohn Sikris, der sich Jehova freiwillig gestellt hatte, und mit ihm zweihunderttausend tapfere Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Und von Benjamin: der tapfere Held Eljada und mit ihm zweihunderttausend mit Bogen und Schild Bewaffnete;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'und neben ihm Josabad, und mit ihm hundertachtzigtausend zum Heere Gerüstete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Diese waren es, die dem König dienten, außer denen, welche der König in die festen Städte von ganz Juda gelegt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'So hatte Josaphat Reichtum und Ehre in Fülle. Und er verschwägerte sich mit Ahab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Und nach Verlauf von einigen Jahren zog er zu Ahab nach Samaria hinab; und Ahab schlachtete für ihn und für das Volk, das bei ihm war, Klein-und Rindvieh in Menge; und er verleitete ihn, wider Ramoth-Gilead hinaufzuziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Und Ahab, der König von Israel, sprach zu Josaphat, dem König von Juda: Willst du mit mir nach Ramoth-Gilead ziehen? Und er sprach zu ihm: Ich will sein wie du, und mein Volk wie dein Volk, und will mit dir in den Streit ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Und Josaphat sprach zu dem König von Israel: Befrage doch heute das Wort Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Da versammelte der König von Israel die Propheten, vierhundert Mann, und er sprach zu ihnen: Sollen wir wider Ramoth-Gilead in den Streit ziehen, oder soll ich davon abstehen? Und sie sprachen: Ziehe hinauf, und Gott wird es in die Hand des Königs geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Aber Josaphat sprach: Ist hier kein Prophet Jehovas mehr, daß wir durch ihn fragen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Und der König von Israel sprach zu Josaphat: Es ist noch ein Mann da, um durch ihn Jehova zu befragen; aber ich hasse ihn, denn er weissagt nichts Gutes über mich, sondern immer nur Böses; es ist Micha, der Sohn Jimlas. Und Josaphat sprach: Der König spreche nicht also!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Da rief der König von Israel einen Kämmerer und sprach: Bringe Micha, den Sohn Jimlas, eilends her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Und der König von Israel und Josaphat, der König von Juda, saßen ein jeder auf seinem Throne, angetan mit königlichen Kleidern, und sie saßen auf einem freien Platze am Eingang des Tores von Samaria; und alle Propheten weissagten vor ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Und Zedekia, der Sohn Kenaanas, machte sich eiserne Hörner und sprach: So spricht Jehova: Mit diesen wirst du die Syrer stoßen, bis du sie vernichtet hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Und alle Propheten weissagten ebenso und sprachen: Ziehe hinauf nach Ramoth-Gilead, und es wird dir gelingen; denn Jehova wird es in die Hand des Königs geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Und der Bote, der hingegangen war, Micha zu rufen, redete zu ihm und sprach: Siehe, die Worte der Propheten verkündigen einstimmig dem König Gutes; so laß doch dein Wort sein wie das Wort eines von ihnen, und rede Gutes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Aber Micha sprach: So wahr Jehova lebt, was mein Gott mir sagen wird, das werde ich reden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Und als er zu dem König kam, sprach der König zu ihm: Micha, sollen wir nach Ramoth-Gilead in den Streit ziehen, oder soll ich davon abstehen? Und er sprach: Ziehet hinauf, und es wird euch gelingen; denn sie werden in eure Hand gegeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Und der König sprach zu ihm: Wieviele Male muß ich dich beschwören, daß du nichts zu mir reden sollst, als nur Wahrheit im Namen Jehovas?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Da sprach er: Ich sah ganz Israel auf den Bergen zerstreut wie Schafe, die keinen Hirten haben. Und Jehova sprach: Diese haben keinen Herrn; sie sollen ein jeder nach seinem Hause zurückkehren in Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Und der König von Israel sprach zu Josaphat: Habe ich dir nicht gesagt: er weissagt nichts Gutes über mich, sondern nur Böses?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Und er sprach: Darum höret das Wort Jehovas: Ich sah Jehova auf seinem Throne sitzen, und alles Heer des Himmels zu seiner Rechten und zu seiner Linken stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Und Jehova sprach: Wer will Ahab, den König von Israel, bereden, daß er hinaufziehe und zu Ramoth-Gilead falle? Und der eine sprach so, und der andere sprach so.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Da trat ein Geist hervor und stellte sich vor Jehova und sprach: Ich will ihn bereden. Und Jehova sprach zu ihm: Wodurch?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Und er sprach: Ich will ausgehen und will ein Lügengeist sein in dem Munde aller seiner Propheten. Und er sprach: Du wirst ihn bereden und wirst es auch ausrichten; gehe aus und tue also!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Und nun, siehe, Jehova hat einen Lügengeist in den Mund dieser deiner Propheten gelegt, und Jehova hat Böses über dich geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Da trat Zedekia, der Sohn Kenaanas, herzu und schlug Micha auf den Backen und sprach: Auf welchem Wege wäre der Geist Jehovas von mir gewichen, um mit dir zu reden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Und Micha sprach: Siehe, du wirst es sehen an jenem Tage, wenn du ins innerste Gemach gehen wirst, um dich zu verstecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Und der König von Israel sprach: Nehmet Micha und führet ihn zurück zu Amon, dem Obersten der Stadt, und zu Joas, dem Sohne des Königs, und saget:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'So spricht der König: Setzet diesen ins Gefängnis und speiset ihn mit Brot der Trübsal und mit Wasser der Trübsal, bis ich in Frieden wiederkomme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Und Micha sprach: Wenn du je in Frieden zurückkehrst, so hat Jehova nicht durch mich geredet! Und er sprach: Höret es, ihr Völker alle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Und der König von Israel und Josaphat, der König von Juda, zogen hinauf nach Ramoth-Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Und der König von Israel sprach zu Josaphat: Ich will mich verkleiden und in den Streit ziehen, du aber lege deine Kleider an. Und der König von Israel verkleidete sich, und sie zogen in den Streit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Der König von Syrien hatte aber seinen Obersten der Wagen geboten und gesagt: Ihr sollt weder wider einen Geringen streiten, noch wider einen Großen, sondern wider den König von Israel allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Und es geschah, als die Obersten der Wagen Josaphat sahen, denn sie sprachen: Das ist der König von Israel! da umringten sie ihn, um zu streiten; und Josaphat schrie; und Jehova half ihm, und Gott lenkte sie von ihm ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Und es geschah, als die Obersten der Wagen sahen, daß er nicht der König von Israel war, da wandten sie sich von ihm ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Und ein Mann spannte den Bogen aufs Geratewohl und traf den König von Israel zwischen den Panzeranhang und den Panzer. Da sprach er zu seinem Wagenlenker: Wende um und führe mich aus dem Lager hinaus, denn ich bin verwundet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Und der Streit nahm überhand an selbigem Tage, und der König von Israel blieb aufrecht stehen in dem Wagen, den Syrern gegenüber, bis zum Abend; und er starb zur Zeit des Sonnenuntergangs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Und Josaphat, der König von Juda, kehrte in Frieden zurück nach seinem Hause, nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Da ging ihm Jehu, der Sohn Hananis, der Seher, entgegen; und er sprach zu dem König Josaphat: Hilfst du dem Gesetzlosen, und liebst du, die Jehova hassen? Und um deswillen ist Zorn über dir von seiten Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Jedoch ist Gutes an dir gefunden worden, weil du die Ascheroth aus dem Lande hinweggeschafft und dein Herz darauf gerichtet hast, Gott zu suchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Und Josaphat blieb zu Jerusalem. Und er zog wiederum aus unter das Volk, von Beerseba bis zum Gebirge Ephraim, und führte sie zurück zu Jehova, dem Gott ihrer Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Und er bestellte Richter im Lande, in allen festen Städten Judas, Stadt für Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Und er sprach zu den Richtern: Sehet zu, was ihr tut; denn nicht für die Menschen richtet ihr, sondern für Jehova, und er ist mit euch im Rechtsspruch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'So sei denn der Schrecken Jehovas auf euch; habet acht, wie ihr handelt! Denn bei Jehova, unserem Gott, ist kein Unrecht, noch Ansehen der Person oder Annehmen von Geschenk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Und auch in Jerusalem bestellte Josaphat Leviten und Priester und Häupter der Väter Israels für das Gericht Jehovas und für den Rechtsstreit. Und sie waren nach Jerusalem zurückgekehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Und er gebot ihnen und sprach: Also sollt ihr tun in der Furcht Jehovas, mit Treue und mit ungeteiltem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Und was irgend für ein Rechtsstreit vor euch kommt von seiten eurer Brüder, die in ihren Städten wohnen, zwischen Blut und Blut, zwischen Gesetz und Gebot, Satzungen und Rechten, so sollt ihr sie verwarnen, daß sie sich nicht an Jehova verschulden, und daß nicht ein Zorn über euch und über eure Brüder komme. Also sollt ihr tun, damit ihr euch nicht verschuldet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Und siehe, Amarja, der Hauptpriester, ist über euch in allen Sachen Jehovas, und Sebadja, der Sohn Ismaels, der Fürst des Hauses Juda, in allen Sachen des Königs; und als Vorsteher sind die Leviten vor euch. Seid stark und handelt, und Jehova wird mit dem Guten sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Und es geschah hernach, da kamen die Kinder Moab und die Kinder Ammon und mit ihnen von den Meunitern wider Josaphat zum Streit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Und man kam und berichtete Josaphat und sprach: Eine große Menge ist wider dich gekommen von jenseit des Meeres, von Syrien; und siehe, sie sind zu Hazezon-Tamar, das ist Engedi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Da fürchtete sich Josaphat, und er richtete sein Angesicht darauf, Jehova zu suchen; und er rief ein Fasten aus über ganz Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Und Juda versammelte sich, um von Jehova Hilfe zu suchen; sogar aus allen Städten Judas kamen sie, um Jehova zu suchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Und Josaphat stand in der Versammlung Judas und Jerusalems im Hause Jehovas, vor dem neuen Vorhof;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'und er sprach: Jehova, Gott unserer Väter, bist du es nicht, der da Gott im Himmel ist, und bist du nicht der Herrscher über alle Königreiche der Nationen? Und in deiner Hand ist Kraft und Macht; und niemand vermag gegen dich zu bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Hast du nicht, unser Gott, die Bewohner dieses Landes vor deinem Volke Israel ausgetrieben und es dem Samen Abrahams, deines Freundes, gegeben ewiglich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Und sie haben darin gewohnt und haben dir ein Heiligtum darin gebaut für deinen Namen, und gesagt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Wenn Unglück über uns kommt, Schwert, Strafgericht, oder Pest, oder Hungersnot, und wir treten vor dieses Haus und vor dich, denn dein Name ist in diesem Hause und schrieen zu dir aus unserer Bedrängnis, so wirst du hören und retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Und nun, siehe, die Kinder Ammon und Moab und die vom Gebirge Seir, unter welche zu kommen du Israel nicht gestattet hast, als sie aus dem Lande Ägypten kamen, sondern sie sind ihnen ausgewichen und haben sie nicht vertilgt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'siehe da, sie vergelten es uns, indem sie kommen, um uns aus deinem Besitztum zu vertreiben, das du uns zum Besitz gegeben hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Unser Gott, willst du sie nicht richten? Denn in uns ist keine Kraft vor dieser großen Menge, die wider uns kommt; und wir wissen nicht, was wir tun sollen, sondern auf dich sind unsere Augen gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Und ganz Juda stand vor Jehova, samt ihren Kindlein, ihren Weibern und ihren Söhnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Und Jachasiel, der Sohn Sekarjas, des Sohnes Benajas, des Sohnes Jechiels, des Sohnes Mattanjas, der Levit, von den Söhnen Asaphs, auf ihn kam der Geist Jehovas mitten in der Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Und er sprach: Merket auf, ganz Juda, und ihr Bewohner von Jerusalem, und du, König Josaphat! So spricht Jehova zu euch: Fürchtet euch nicht und erschrecket nicht vor dieser großen Menge; denn nicht euer ist der Streit, sondern Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Morgen ziehet wider sie hinab; siehe, sie kommen die Anhöhe Ziz herauf, und ihr werdet sie am Ende des Tales finden vor der Wüste Jeruel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Ihr werdet hierbei nicht zu streiten haben; tretet hin, stehet und sehet die Rettung Jehovas an euch, Juda und Jerusalem! Fürchtet euch nicht und erschrecket nicht; morgen ziehet ihnen entgegen, und Jehova wird mit euch sein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Da neigte sich Josaphat, mit dem Antlitz zur Erde; und ganz Juda und die Bewohner von Jerusalem fielen nieder vor Jehova, um Jehova anzubeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Und die Leviten, von den Söhnen der Kehathiter und von den Söhnen der Korhiter, standen auf, um Jehova, den Gott Israels, zu loben mit überaus lauter Stimme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Und sie machten sich des Morgens früh auf und zogen aus nach der Wüste Tekoa. Und bei ihrem Auszuge trat Josaphat hin und sprach: Höret mich, Juda, und ihr Bewohner von Jerusalem! Glaubet an Jehova, euren Gott, und ihr werdet befestigt werden; glaubet seinen Propheten, und es wird euch gelingen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Und er beriet sich mit dem Volke und bestellte Sänger für Jehova, welche lobsangen in heiligem Schmuck, indem sie vor den Gerüsteten her auszogen und sprachen: Preiset Jehova, denn seine Güte währt ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Und zur Zeit, als sie begannen mit Jubel und Lobgesang, stellte Jehova einen Hinterhalt wider die Kinder Ammon, Moab und die vom Gebirge Seir, welche wider Juda gekommen waren; und sie wurden geschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Und die Kinder Ammon und Moab standen auf wider die Bewohner des Gebirges Seir, um sie zu vernichten und zu vertilgen; und als sie mit den Bewohnern von Seir fertig waren, half einer den anderen verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Und Juda kam auf die Bergwarte gegen die Wüste hin; und sie sahen sich um nach der Menge, und siehe, da waren es Leichname, die auf der Erde lagen, und niemand war entronnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Da kam Josaphat und sein Volk, um ihre Beute zu rauben; und sie fanden unter ihnen sowohl Habe als Leichname und kostbare Geräte in Menge, und sie plünderten für sich, bis es nicht mehr zu tragen war. Und drei Tage lang raubten sie die Beute, denn sie war groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Und am vierten Tage versammelten sie sich im Tale Beraka, denn daselbst priesen sie Jehova; daher gab man jenem Orte den Namen Tal Beraka, bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Und alle Männer von Juda und Jerusalem kehrten um, mit Josaphat an ihrer Spitze, um nach Jerusalem zurückzukehren mit Freude; denn Jehova hatte ihnen Freude an ihren Feinden gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Und sie kamen nach Jerusalem, zum Hause Jehovas, mit Harfen und mit Lauten und mit Trompeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Und der Schrecken Gottes fiel auf alle Königreiche der Länder, als sie hörten, daß Jehova mit den Feinden Israels gestritten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Und das Königreich Josaphats hatte Ruhe; und sein Gott schaffte ihm Ruhe ringsumher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Und so regierte Josaphat über Juda. Er war fünfunddreißig Jahre alt, als er König wurde, und er regierte fünfundzwanzig Jahre zu Jerusalem; und der Name seiner Mutter war Asuba, die Tochter Schilchis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Und er wandelte auf dem Wege seines Vaters Asa und wich nicht davon, indem er tat, was recht war in den Augen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Nur die Höhen wichen nicht, und das Volk hatte sein Herz noch nicht auf den Gott ihrer Väter gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Und das Übrige der Geschichte Josaphats, die erste und die letzte, siehe, sie ist geschrieben in der Geschichte Jehus, des Sohnes Hananis, welche in das Buch der Könige von Israel aufgenommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Und hernach verband sich Josaphat, der König von Juda, mit Ahasja, dem König von Israel; dieser handelte gesetzlos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Und er verband sich mit ihm, Schiffe zu bauen, um nach Tarsis zu fahren; und sie bauten Schiffe zu Ezjon-Geber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Und Elieser, der Sohn Dodawas, von Marescha, weissagte wider Josaphat und sprach: Weil du dich mit Ahasja verbunden hast, hat Jehova dein Werk zerstört. Und die Schiffe wurden zertrümmert und vermochten nicht nach Tarsis zu fahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Und Josaphat legte sich zu seinen Vätern, und er wurde bei seinen Vätern begraben in der Stadt Davids. Und Joram, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Und er hatte Brüder, Söhne Josaphats: Asarja und Jechiel und Sekarja und Asarja und Michael und Schephatja; alle diese waren Söhne Josaphats, des Königs von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Und ihr Vater gab ihnen viele Geschenke an Silber und an Gold und an Kostbarkeiten, nebst festen Städten in Juda; aber das Königreich gab er Joram, denn er war der Erstgeborene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Und als Joram über das Königreich seines Vaters aufgestanden und erstarkt war, da tötete er alle seine Brüder und auch einige Oberste von Israel mit dem Schwerte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Zweiunddreißig Jahre war Joram alt, als er König wurde, und er regierte acht Jahre zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Und er wandelte auf dem Wege der Könige von Israel, wie das Haus Ahabs getan hatte, denn er hatte eine Tochter Ahabs zum Weibe; und er tat, was böse war in den Augen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Aber Jehova wollte das Haus Davids nicht verderben, um des Bundes willen, den er mit David gemacht, und so wie er gesagt hatte, daß er ihm und seinen Söhnen eine Leuchte geben wolle alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'In seinen Tagen fielen die Edomiter von der Botmäßigkeit Judas ab und setzten einen König über sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Da zog Joram hinüber mit seinen Obersten, und alle Wagen mit ihm. Und es geschah, als er sich des Nachts aufmachte, da schlug er die Edomiter, welche ihn und die Obersten der Wagen umringt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'So fielen die Edomiter von der Botmäßigkeit Judas ab bis auf diesen Tag. Damals, zu derselben Zeit, fiel auch Libna von seiner Botmäßigkeit ab; denn er hatte Jehova, den Gott seiner Väter, verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Auch er machte Höhen auf den Bergen Judas, und er verleitete die Bewohner von Jerusalem, Hurerei zu treiben, und verführte Juda dazu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Da gelangte eine Schrift von Elia, dem Propheten, an ihn, welche lautete: So spricht Jehova, der Gott deines Vaters David: Darum, daß du nicht auf den Wegen deines Vaters Josaphat und auf den Wegen Asas, des Königs von Juda, gewandelt hast,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'sondern auf dem Wege der Könige von Israel gewandelt und Juda und die Bewohner von Jerusalem verleitet hast, Hurerei zu treiben, nach den Hurereien des Hauses Ahabs, und auch deine Brüder, das Haus deines Vaters, ermordet hast, die besser waren als du:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'siehe, so wird Jehova dein Volk und deine Söhne und deine Weiber und alle deine Habe plagen mit einer großen Plage;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'du aber wirst schwer erkranken an einer Krankheit deiner Eingeweide, bis deine Eingeweide infolge der Krankheit heraustreten werden Tag für Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Und Jehova erweckte wider Joram den Geist der Philister und der Araber, die zur Seite der Kuschiter wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Und sie zogen wider Juda herauf und brachen ein und führten alle Habe weg, die sich im Hause des Königs vorfand, und auch seine Söhne und seine Weiber; und es blieb ihm kein Sohn übrig als nur Joahas, der jüngste seiner Söhne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Und nach allem diesem plagte ihn Jehova mit einer unheilbaren Krankheit in seinen Eingeweiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Und es geschah von Tag zu Tag, und zur Zeit, als das Ende von zwei Jahren eintrat, daß seine Eingeweide bei seiner Krankheit heraustraten; und er starb unter heftigen Schmerzen. Und sein Volk machte ihm keinen Brand gleich dem Brande seiner Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Zweiunddreißig Jahre war er alt, als er König wurde, und er regierte acht Jahre zu Jerusalem. Und er ging hin, ohne vermißt zu werden; und man begrub ihn in der Stadt Davids, aber nicht in den Gräbern der Könige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Und die Bewohner von Jerusalem machten Ahasja, seinen jüngsten Sohn, zum König an seiner Statt; denn alle die älteren hatte die Schar ermordet, welche mit den Arabern ins Lager gekommen war. Und Ahasja, der Sohn Jorams, des Königs von Juda, ward König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Zweiundzwanzig Jahre war Ahasja alt, als er König wurde, und er regierte ein Jahr zu Jerusalem; und der Name seiner Mutter war Athalja, die Tochter Omris.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Auch er wandelte auf den Wegen des Hauses Ahabs; denn seine Mutter war seine Ratgeberin zum gesetzlosen Handeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Und er tat, was böse war in den Augen Jehovas, wie das Haus Ahabs; denn diese waren nach dem Tode seines Vaters seine Ratgeber, zu seinem Verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Auch ging er auf ihren Rat und zog hin mit Joram, dem Sohne Ahabs, dem König von Israel, in den Streit wider Hasael, den König von Syrien, nach Ramoth-Gilead. Und die Syrer verwundeten Joram.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Da kehrte er zurück, um sich in Jisreel von den Wunden heilen zu lassen, die sie ihm zu Rama geschlagen hatten, als er wider Hasael, den König von Syrien, stritt. Und Asarja, der Sohn Jorams, der König von Juda, zog hinab, um Joram, den Sohn Ahabs, in Jisreel zu besuchen, weil er krank war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Aber von Gott war es der Untergang Ahasjas, daß er zu Joram kam. Denn als er angekommen war, zog er mit Joram aus wider Jehu, den Sohn Nimsis, welchen Jehova gesalbt hatte, um das Haus Ahabs auszurotten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Und es geschah, als Jehu an dem Hause Ahabs Gericht übte, da traf er die Obersten von Juda und die Söhne der Brüder Ahasjas, welche Ahasja dienten; und er ermordete sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Und er suchte Ahasja, und sie griffen ihn, als er sich in Samaria versteckt hielt; und sie brachten ihn zu Jehu und töteten ihn. Und sie begruben ihn, denn sie sprachen: Er ist ein Sohn Josaphats, der Jehova gesucht hat mit seinem ganzen Herzen. Und das Haus Ahasjas hatte niemand mehr, der zum Königtum tüchtig gewesen wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Und als Athalja, die Mutter Ahasjas, sah, daß ihr Sohn tot war, da machte sie sich auf und brachte allen königlichen Samen vom Hause Juda um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Aber Josabath, die Tochter des Königs, nahm Joas, den Sohn Ahasjas, und stahl ihn weg aus der Mitte der Königssöhne, die getötet wurden, und sie tat ihn und seine Amme in das Schlafgemach. Und so verbarg ihn Josabath, die Tochter des Königs Joram, das Weib Jojadas, des Priesters (denn sie war die Schwester Ahasjas) vor Athalja, so daß sie ihn nicht tötete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Und er war sechs Jahre bei ihnen im Hause Gottes versteckt. Athalja aber regierte über das Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Und im siebten Jahre stärkte sich Jojada und verband die Obersten über hundert, Asarja, den Sohn Jerochams, und Ismael, den Sohn Jochanans, und Asarja, den Sohn Obeds, und Maaseja, den Sohn Adajas, und Elisaphat, den Sohn Sikris, mit sich in einem Bunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Und sie zogen in Juda umher und versammelten die Leviten aus allen Städten Judas, und die Häupter der Väter von Israel; und sie kamen nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Und die ganze Versammlung machte im Hause Gottes einen Bund mit dem König. Und Jojada sprach zu ihnen: Siehe, der Sohn des Königs soll König sein, so wie Jehova von den Söhnen Davids geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Dies ist es, was ihr tun sollt: Ein Drittel von euch, die ihr am Sabbath antretet, von den Priestern und von den Leviten, soll Türhüter der Schwellen sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'und ein Drittel soll im Hause des Königs sein; und ein Drittel am Tore Jesod; und alles Volk in den Höfen des Hauses Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Und es soll niemand in das Haus Jehovas hineingehen, als nur die Priester und die diensttuenden Leviten; sie sollen hineingehen, denn sie sind heilig. Und alles Volk soll die Vorschriften Jehovas beobachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Und die Leviten sollen den König rings umgeben, ein jeder mit seinen Waffen in seiner Hand; und wer in das Haus hineingeht, soll getötet werden; und ihr sollt bei dem König sein, wenn er eingeht und wenn er ausgeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Und die Leviten und ganz Juda taten nach allem, was der Priester Jojada geboten hatte; und sie nahmen ein jeder seine Männer, die am Sabbath antretenden samt den am Sabbath abtretenden; denn der Priester Jojada hatte die Abteilungen nicht entlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Und der Priester Jojada gab den Obersten über hundert die Speere und die Tartschen und die Schilde, welche dem König David gehört hatten, die im Hause Gottes waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Und er stellte alles Volk auf, und zwar einen jeden mit seiner Waffe in seiner Hand, von der rechten Seite des Hauses bis zur linken Seite des Hauses, gegen den Altar und gegen das Haus hin, rings um den König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Und sie führten den Sohn des Königs heraus und setzten ihm die Krone auf und gaben ihm das Zeugnis, und sie machten ihn zum König; und Jojada und seine Söhne salbten ihn und riefen: Es lebe der König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Und als Athalja das Geschrei des Volkes hörte, das herzulief und den König pries, kam sie zu dem Volke in das Haus Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Und sie sah: und siehe, der König stand auf seinem Standorte am Eingang, und die Obersten und die Trompeter bei dem König; und alles Volk des Landes war fröhlich und stieß in die Trompeten; und die Sänger waren da mit Musikinstrumenten und leiteten den Lobgesang. Da zerriß Athalja ihre Kleider und rief: Verschwörung, Verschwörung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Und der Priester Jojada ließ die Obersten über hundert, die über das Heer bestellt waren, heraustreten, und sprach zu ihnen: Führet sie hinaus außerhalb der Reihen, und wer ihr folgt, soll mit dem Schwerte getötet werden! Denn der Priester sprach: Ihr sollt sie nicht in dem Hause Jehovas töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Und sie machten ihr Platz, und sie ging durch den Eingang des Roßtores in das Haus des Königs; und sie töteten sie daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Und Jojada machte einen Bund zwischen sich und dem ganzen Volke und dem König, daß sie das Volk Jehovas sein sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Da ging alles Volk in das Haus des Baal und riß es nieder, und sie zerschlugen seine Altäre und seine Bilder; und Mattan, den Priester des Baal, töteten sie vor den Altären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Und Jojada legte die Ämter des Hauses Jehovas in die Hand der Priester, der Leviten, welche David über das Haus Jehovas abgeteilt hatte, um die Brandopfer Jehovas zu opfern, wie in dem Gesetz Moses geschrieben steht, mit Freuden und mit Gesang, nach der Anweisung Davids.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Und er stellte die Torhüter an die Tore des Hauses Jehovas, daß keiner hineinginge, der irgendwie unrein wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Und er nahm die Obersten über hundert und die Vornehmen und die Gebieter im Volke, und alles Volk des Landes, und führte den König aus dem Hause Jehovas hinab, und sie kamen durch das obere Tor in das Haus des Königs; und sie setzten den König auf den Thron des Königreichs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Und alles Volk des Landes freute sich, und die Stadt hatte Ruhe. Athalja aber hatten sie mit dem Schwerte getötet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Sieben Jahre war Joas alt, als er König wurde, und er regierte vierzig Jahre zu Jerusalem; und der Name seiner Mutter war Zibja, von Beerseba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Und Joas tat, was recht war in den Augen Jehovas, alle die Tage des Priesters Jojada.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Und Jojada nahm ihm zwei Weiber; und er zeugte Söhne und Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Und es geschah hernach, daß Joas im Herzen hatte, das Haus Jehovas zu erneuern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Und er versammelte die Priester und die Leviten und sprach zu ihnen: Ziehet aus in die Städte Judas, und sammelt Geld ein von ganz Israel, um das Haus eures Gottes auszubessern von Jahr zu Jahr; und ihr sollt mit der Sache eilen. Aber die Leviten eilten nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Da rief der König Jojada, das Haupt, und sprach zu ihm: Warum hast du die Leviten nicht aufgefordert, aus Juda und Jerusalem die Steuer einzubringen, welche Mose, der Knecht Jehovas, der Versammlung Israels für das Zelt des Zeugnisses auferlegt hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Denn die gottlose Athalja und ihre Söhne haben das Haus Gottes zerstört und haben auch alle geheiligten Dinge des Hauses Jehovas für die Baalim verwendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Und der König befahl, und man machte eine Lade und stellte sie an das Tor des Hauses Jehovas, auswärts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Und man rief in Juda und in Jerusalem aus, daß man Jehova die Steuer Moses, des Knechtes Gottes, bringen sollte, welche er Israel in der Wüste auferlegt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Da freuten sich alle Obersten und das ganze Volk; und sie brachten und warfen in die Lade, bis man fertig war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Und es geschah zur Zeit, wenn man die Lade durch die Leviten zum Amte des Königs brachte, und wenn man sah, daß viel Geld darin war, so kamen der Schreiber des Königs und der Beamte des Hauptpriesters und leerten die Lade aus; und sie trugen sie und brachten sie wieder an ihren Ort. So taten sie Tag für Tag und sammelten Geld in Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Und der König und Jojada gaben es denen, welche das Werk der Arbeit am Hause Jehovas betrieben; und diese dingten Steinhauer und Zimmerleute, um das Haus Jehovas zu erneuern, und auch Arbeiter in Eisen und Erz, um das Haus Jehovas auszubessern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Und die das Werk taten, arbeiteten, und die Herstellung des Werkes nahm zu durch ihre Hand; und sie setzten das Haus Gottes wieder in seinen früheren Stand und machten es fest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Und als sie fertig waren, brachten sie das übrige Geld vor den König und vor Jojada; und er machte davon Geräte für das Haus Jehovas, Geräte für den Dienst und für die Brandopfer, und Schalen, und goldene und silberne Geräte. Und man opferte Brandopfer im Hause Jehovas beständig, alle die Tage Jojadas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Und Jojada wurde alt und der Tage satt, und er starb; er war hundertdreißig Jahre alt, als er starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Und man begrub ihn in der Stadt Davids bei den Königen, weil er Gutes getan hatte an Israel und gegen Gott und sein Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Und nach dem Tode Jojadas kamen die Obersten von Juda und beugten sich vor dem König nieder; und der König hörte auf sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Und sie verließen das Haus Jehovas, des Gottes ihrer Väter, und dienten den Ascherim und den Götzenbildern. Da kam ein Zorn über Juda und Jerusalem um dieser ihrer Verschuldung willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Und er sandte Propheten unter sie, um sie zu Jehova zurückzuführen, und diese zeugten wider sie; aber sie nahmen es nicht zu Ohren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Und der Geist Gottes kam über Sekarja, den Sohn Jojadas, des Priesters; und er stand auf über dem Volke und sprach zu ihnen: So spricht Gott: Warum übertretet ihr die Gebote Jehovas? Es wird euch ja nicht gelingen. Weil ihr Jehova verlassen habt, so hat er euch verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Und sie machten eine Verschwörung wider ihn und steinigten ihn auf Befehl des Königs im Hofe des Hauses Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Und der König Joas gedachte nicht der Güte, die sein Vater Jojada an ihm erwiesen hatte, und ermordete dessen Sohn. Und als er starb, sprach er: Jehova möge es sehen und fordern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Und es geschah beim Umlauf des Jahres, daß ein Heer der Syrer wider ihn heraufzog. Und sie kamen nach Juda und Jerusalem und schlachteten aus dem Volke alle Obersten des Volkes; und alle ihre Beute sandten sie zu dem König von Damaskus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Wiewohl das Heer der Syrer mit wenigen Männern gekommen war, gab doch Jehova ein sehr zahlreiches Heer in ihre Hand, weil sie Jehova, den Gott ihrer Väter, verlassen hatten. Und sie übten Gericht an Joas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Und als sie von ihm weggezogen waren, sie verließen ihn aber in großen Schmerzen, machten seine Knechte eine Verschwörung wider ihn, um des Blutes der Söhne des Priesters Jojada willen; und sie ermordeten ihn auf seinem Bette, und er starb. Und man begrub ihn in der Stadt Davids, aber man begrub ihn nicht in den Gräbern der Könige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Und diese sind es, die eine Verschwörung wider ihn machten: Sabad, der Sohn Schimeaths, der Ammonitin, und Josabad, der Sohn Schimriths, der Moabitin. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Seine Söhne aber, und die Größe des Tributs, der ihm auferlegt wurde, und der Bau des Hauses Gottes, siehe, das ist geschrieben in der Beschreibung des Buches der Könige. Und Amazja, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Fünfundzwanzig Jahre alt, wurde Amazja König, und er regierte neunundzwanzig Jahre zu Jerusalem; und der Name seiner Mutter war Joaddan, von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Und er tat, was recht war in den Augen Jehovas, jedoch nicht mit ungeteiltem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Und es geschah, als das Königtum bei ihm erstarkt war, da tötete er seine Knechte, die den König, seinen Vater, erschlagen hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Aber ihre Söhne tötete er nicht, sondern er tat, wie im Gesetz, im Buche Moses, geschrieben steht, wo Jehova geboten und gesagt hat: Nicht sollen Väter sterben um der Kinder willen, und Kinder sollen nicht sterben um der Väter willen, sondern sie sollen ein jeder für seine Sünde sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Und Amazja versammelte Juda, und er stellte sie auf nach Vaterhäusern, nach Obersten über tausend und nach Obersten über hundert, von ganz Juda und Benjamin; und er musterte sie von zwanzig Jahren an und darüber, und fand ihrer dreihunderttausend Auserlesene, die zum Heere auszogen, die Lanze und Schild führten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Und er dingte aus Israel hunderttausend tapfere Helden um hundert Talente Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Da kam ein Mann Gottes zu ihm und sprach: O König! Laß das Heer von Israel nicht mit dir ziehen; denn Jehova ist nicht mit Israel, mit allen Kindern Ephraim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Denn wenn du ziehst, tue es, sei stark zum Streit! so wird Gott dich zu Fall bringen vor dem Feinde; denn bei Gott ist Macht, zu helfen und zu Fall zu bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Und Amazja sprach zu dem Manne Gottes: Und was ist betreffs der hundert Talente zu tun, die ich der Schar von Israel gegeben habe? Und der Mann Gottes sprach: Jehova hat, um dir mehr als das zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Da sonderte Amazja sie ab, nämlich die Schar, welche von Ephraim zu ihm gekommen war, daß sie an ihren Ort gingen. Und ihr Zorn entbrannte sehr wider Juda, und sie kehrten an ihren Ort zurück in glühendem Zorn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Amazja aber faßte Mut und führte sein Volk aus; und er zog ins Salztal und schlug die Kinder Seir, zehntausend Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Und die Kinder Juda führten zehntausend lebendig gefangen hinweg und brachten sie auf die Spitze eines Felsens, und sie stürzten sie hinab von der Spitze des Felsens, daß sie allesamt zerbarsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Aber die Männer der Schar, welche Amazja hatte zurückkehren lassen, daß sie nicht mit ihm in den Streit zögen, die fielen ein in die Städte Judas, von Samaria bis Beth-Horon, und erschlugen von ihnen dreitausend Mann und machten eine große Beute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Und es geschah, nachdem Amazja von der Edomiterschlacht zurückgekommen war, da brachte er die Götter der Kinder Seir und stellte sie sich zu Göttern auf; und er beugte sich vor ihnen nieder und räucherte ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Da entbrannte der Zorn Jehovas wider Amazja; und er sandte einen Propheten zu ihm, und er sprach zu ihm: Warum hast du die Götter des Volkes gesucht, die ihr Volk nicht aus deiner Hand errettet haben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Und es geschah, während er zu ihm redete, da sprach Amazja zu ihm: Haben wir dich zum Ratgeber des Königs gesetzt? Laß ab! Warum soll man dich erschlagen? Und der Prophet ließ ab und sprach: Ich weiß, daß Gott beschlossen hat, dich zu verderben, weil du solches getan und auf meinen Rat nicht gehört hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Und Amazja, der König von Juda, beriet sich und sandte zu Joas, dem Sohne Joahas\', des Sohnes Jehus, dem König von Israel, und ließ ihm sagen: Komm, laß uns einander ins Angesicht sehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Da sandte Joas, der König von Israel, zu Amazja, dem König von Juda, und ließ ihm sagen: Der Dornstrauch auf dem Libanon sandte zu der Zeder auf dem Libanon und ließ ihr sagen: Gib meinem Sohne deine Tochter zum Weibe! Da lief das Getier des Feldes, das auf dem Libanon ist, vorüber und zertrat den Dornstrauch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Du sagst: Siehe, du hast Edom geschlagen! und dein Herz erhebt sich, dir Ruhm zu erwerben. Bleibe nun in deinem Hause; warum willst du dich mit dem Unglück einlassen, daß du fallest, du und Juda mit dir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Aber Amazja hörte nicht; denn es war von Gott, damit er sie preisgäbe, weil sie die Götter von Edom gesucht hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Da zog Joas, der König von Israel, herauf; und sie sahen einander ins Angesicht, er und Amazja, der König von Juda, zu Beth-Semes, das zu Juda gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Und Juda wurde vor Israel geschlagen; und sie flohen, ein jeder nach seinem Zelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Und Joas, der König von Israel, nahm Amazja, den König von Juda, den Sohn Joas\', des Sohnes Joahas\', zu Beth-Semes gefangen und brachte ihn nach Jerusalem. Und er machte einen Bruch in der Mauer Jerusalems, vom Tore Ephraim bis an das Ecktor, vierhundert Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Und er nahm alles Gold und Silber, und alle Geräte, welche sich im Hause Gottes bei Obed-Edom vorfanden, und die Schätze des Hauses des Königs, und Geiseln, und kehrte nach Samaria zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Und Amazja, der Sohn Joas\', der König von Juda, lebte nach dem Tode Joas\', des Sohnes Joahas\', des Königs von Israel, fünfzehn Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Und das Übrige der Geschichte Amazjas, die erste und die letzte, siehe, ist das nicht geschrieben in dem Buche der Könige von Juda und Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Und von der Zeit an, da Amazja von der Nachfolge Jehovas abgewichen war, machten sie zu Jerusalem eine Verschwörung wider ihn; und er floh nach Lachis; und sie sandten ihm nach bis Lachis und töteten ihn daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Und sie luden ihn auf Rosse und begruben ihn bei seinen Vätern in der Stadt Judas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Und das ganze Volk von Juda nahm Ussija, der sechzehn Jahre alt war, und sie machten ihn zum König an seines Vaters Amazja Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Er baute Eloth und brachte es an Juda zurück, nachdem der König sich zu seinen Vätern gelegt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Sechzehn Jahre war Ussija alt, als er König wurde, und er regierte zweiundfünfzig Jahre zu Jerusalem; und der Name seiner Mutter war Jekolja, von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Und er tat, was recht war in den Augen Jehovas, nach allem, was sein Vater Amazja getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Und er suchte Gott in den Tagen Sekarjas, der kundig war in den Gesichten Gottes; und in den Tagen, da er Jehova suchte, gab Gott ihm Gelingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Und er zog aus und stritt wider sie Philister, und riß nieder die Mauer von Gath und die Mauer von Jabne und die Mauer von Asdod; und er baute Städte um Asdod her und unter den Philistern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Und Gott half ihm wider die Philister und wider die Araber, die zu Gur-Baal wohnten, und wider die Meuniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Und die Ammoniter gaben Ussija Geschenke, und sein Name drang bis nach Ägypten hin; denn er war überaus stark geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Und Ussija baute Türme in Jerusalem auf dem Ecktor und auf dem Taltor und auf dem Winkel, und befestigte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Und er baute Türme in der Wüste und grub viele Zisternen; denn er hatte viel Vieh, sowohl in der Niederung als auch in der Ebene, und Ackerleute und Weingärtner im Gebirge und im Fruchtgefilde; denn er liebte den Ackerbau.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Und Ussija hatte ein kriegführendes Heer, das in Scharen in den Kampf zog, nach der Zahl ihrer Musterung durch Jeghiel, den Schreiber, und Maaseja, den Vorsteher, unter der Leitung Hananjas, eines der Obersten des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Die ganze Zahl der Häupter der Väter der tapferen Helden war zweitausend sechshundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Und unter ihrer Leitung stand eine Heeresmacht von dreihundertsiebentausend fünfhundert Mann, welche den Krieg führte mit gewaltiger Kraft, um dem König wider den Feind beizustehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Und Ussija bereitete ihnen, dem ganzen Heere, Schilde und Lanzen und Helme und Panzer und Bogen und Schleudersteine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Und er machte zu Jerusalem Maschinen, ein Kunstwerk des Künstlers, daß sie auf den Türmen und auf den Zinnen sein sollten, um mit Pfeilen und mit großen Steinen zu schießen. Und sein Name ging aus bis in die Ferne; denn wunderbar ward ihm geholfen, bis er stark wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Und als er stark geworden war, erhob sich sein Herz, bis er verderbt handelte; und er handelte treulos gegen Jehova, seinen Gott, und trat in den Tempel Jehovas, um auf dem Räucheraltar zu räuchern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Da kam Asarja, der Priester, hinter ihm her, und mit ihm achtzig Priester Jehovas, wackere Männer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'und sie widerstanden dem König Ussija und sprachen zu ihm: Nicht dir, Ussija, geziemt es, Jehova zu räuchern, sondern den Priestern, den Söhnen Aarons, die geheiligt sind zum Räuchern. Geh aus dem Heiligtum hinaus; denn du hast treulos gehandelt, und es wird dir nicht zur Ehre gereichen von Jehova Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Aber Ussija wurde zornig; und er hatte in seiner Hand ein Räucherfaß zum Räuchern; und als er über die Priester erzürnte, da brach der Aussatz aus an seiner Stirn, angesichts der Priester im Hause Jehovas neben dem Räucheraltar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Und Asarja, der Hauptpriester, und alle die Priester wandten sich zu ihm, und siehe, er war aussätzig an seiner Stirn, und die trieben ihn eilends von dannen fort; und auch er selbst beeilte sich hinauszukommen, weil Jehova ihn geschlagen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Und der König Ussija war aussätzig bis zum Tage seines Todes, und er wohnte in einem Krankenhause als Aussätziger; denn er war von dem Hause Jehovas ausgeschlossen. Und Jotham, sein Sohn, war über das Haus des Königs und richtete das Volk des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Und das Übrige der Geschichte Ussijas, die erste und die letzte, hat Jesaja geschrieben, der Sohn Amoz\', der Prophet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Und Ussija legte sich zu seinen Vätern, und man begrub ihn bei seinen Vätern auf dem Begräbnisacker der Könige; denn man sprach: Er ist aussätzig. Und Jotham, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Fünfundzwanzig Jahre war Jotham alt, als er König wurde, und er regierte sechzehn Jahre zu Jerusalem; und der Name seiner Mutter war Jeruscha, die Tochter Zadoks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Und er tat, was recht war in den Augen Jehovas, nach allem, was sein Vater Ussija getan hatte; nur ging er nicht in den Tempel Jehovas. Aber das Volk handelte noch verderbt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Er baute das obere Tor des Hauses Jehovas; auch an der Mauer des Ophel baute er viel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Und er baute Städte im Gebirge Juda; und in den Wäldern baute er Burgen und Türme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Und er stritt mit dem König der Kinder Ammon und überwand sie; und die Kinder Ammon gaben ihm in selbigem Jahre hundert Talente Silber und zehntausend Kor Weizen und zehntausend Kor Gerste. Das entrichteten ihm die Kinder Ammon auch im zweiten und im dritten Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Und Jotham erstarkte; denn er richtete seine Wege vor dem Angesicht Jehovas, seines Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Und das Übrige der Geschichte Jothams, und alle seine Kriege und seine Wege, siehe, sie sind geschrieben in dem Buche der Könige von Israel und Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Fünfundzwanzig Jahre war er alt, als er König wurde, und er regierte sechzehn Jahre zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Und Jotham legte sich zu seinen Vätern, und man begrub ihn in der Stadt Davids. Und Ahas, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Zwanzig Jahre war Ahas alt, als er König wurde, und er regierte sechzehn Jahre zu Jerusalem. Und er tat nicht, was recht war in den Augen Jehovas, wie sein Vater David;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'sondern er wandelte auf den Wegen der Könige von Israel, und auch machte er den Baalim gegossene Bilder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'und er räucherte im Tale des Sohnes Hinnoms, und er verbrannte seine Söhne im Feuer, nach den Greueln der Nationen, die Jehova vor den Kindern Israel ausgetrieben hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'und er opferte und räucherte auf den Höhen und auf den Hügeln und unter jedem grünen Baume.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Da gab ihn Jehova, sein Gott, in die Hand des Königs von Syrien; und sie schlugen ihn und führten eine große Menge Gefangene von ihm weg und brachten sie nach Damaskus. Und auch in die Hand des Königs von Israel wurde er gegeben, welcher ihm eine große Niederlage beibrachte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Und Pekach, der Sohn Remaljas, erschlug in Juda an einem Tage hundertzwanzigtausend Mann, alles tapfere Leute, weil sie Jehova, den Gott ihrer Väter, verlassen hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Und Sikri, ein Held von Ephraim, erschlug Maaseja, den Sohn des Königs, und Asrikam, den Oberaufseher des Hauses, und Elkana, den Zweiten nach dem König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Und die Kinder Israel führten von ihren Brüdern zweihunderttausend Weiber, Söhne und Töchter gefangen hinweg; und auch raubten sie große Beute von ihnen und brachten sie Beute nach Samaria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Und daselbst war ein Prophet Jehovas, namens Obed; und er ging hinaus, dem Heere entgegen, das nach Samaria kam, und sprach zu ihnen: Siehe, weil Jehova, der Gott eurer Väter, gegen Juda zürnte, hat er sie in eure Hand gegeben; und ihr habt sie mit einer Wut gemordet, die bis an den Himmel reicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Und nun gedenket ihr, die Kinder Judas und Jerusalems euch zu Knechten und Mägden zu unterwerfen. Sind aber nicht bei euch selbst Verschuldungen gegen Jehova, euren Gott?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Und nun höret auf mich und sendet die Gefangenen zurück, die ihr von euren Brüdern weggeführt habt; denn die Zornglut Jehovas ist über euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Da traten Männer von den Häuptern der Kinder Ephraim: Asarja, der Sohn Jochanans, Berekja, der Sohn Meschillemoths, und Jehiskia, der Sohn Schallums, und Amasa, der Sohn Hadlais, vor die vom Heereszuge Kommenden');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'und sprachen zu ihnen: Ihr sollt nicht die Gefangenen hierher bringen; denn um eine Schuld gegen Jehova über uns zu bringen, gedenket ihr solches, um unsere Sünden und unsere Verschuldungen zu mehren; denn wir haben schon eine große Schuld, und eine Zornglut ist über Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Da ließen die Gerüsteten die Gefangenen und die Beute vor den Obersten und der ganzen Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Und die Männer, die mit Namen angegeben waren, standen auf und nahmen die Gefangenen; und alle, die nackt waren unter ihnen, bekleideten sie von der Beute; sie bekleideten und beschuhten sie und speisten und tränkten sie und salbten sie; und alle, die ermattet waren, führten sie auf Eseln und brachten sie nach Jericho, der Palmenstadt, in die Nähe ihrer Brüder. Und sie kehrten nach Samaria zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'In selbiger Zeit sandte der König Ahas zu den Königen von Assyrien, daß sie ihm helfen möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Und die Edomiter kamen abermals, und sie schlugen Juda und führten Gefangene hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Und die Philister fielen ein in die Städte der Niederung und des Südens von Juda, und nahmen Beth-Semes ein und Ajalon und Gederoth und Soko und seine Tochterstädte, und Timna und seine Tochterstädte, und Gimso und seine Tochterstädte; und sie wohnten daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Denn Jehova demütigte Juda, um Ahas\', des Königs von Israel, willen, weil er in Juda zügellos gehandelt und sich ganz treulos gegen Jehova erzeigt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Und Tilgath-Pilneser, der König von Assyrien, kam wider ihn und bedrängte ihn, und stärkte ihn nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Denn Ahas beraubte das Haus Jehovas und das Haus des Königs und der Obersten, und gab das Geraubte dem König von Assyrien; aber er war ihm nicht zur Hilfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Und in der Zeit seiner Bedrängnis, da handelte er noch treuloser gegen Jehova, er, der König Ahas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Und er opferte den Göttern von Damaskus, die ihn geschlagen hatten, und sprach: Da die Götter der Könige von Syrien ihnen helfen, so will ich ihnen opfern, und sie werden mir helfen; sie aber dienten ihm und ganz Israel zum Fall.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Und Ahas brachte die Geräte des Hauses Gottes zusammen und zerschlug die Geräte des Hauses Gottes; und er schloß die Türen des Hauses Jehovas, und machte sich Altäre an allen Ecken in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Und in jeder einzelnen Stadt von Juda machte er Höhen, um anderen Göttern zu räuchern. Und er reizte Jehova, den Gott seiner Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Und das Übrige seiner Geschichte und alle seine Wege, die ersten und die letzten, siehe, sie sind geschrieben in dem Buche der Könige von Juda und Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Und Ahas legte sich zu seinen Vätern, und man begrub ihn in der Stadt, in Jerusalem; denn man brachte ihn nicht in die Gräber der Könige von Israel. Und Jehiskia, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Jehiskia wurde König, als er fünfundzwanzig Jahre alt war, und er regierte neunundzwanzig Jahre zu Jerusalem; und der Name seiner Mutter war Abija, die Tochter Sekarjas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Und er tat, was recht war in den Augen Jehovas, nach allem, was sein Vater David getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Im ersten Jahre seiner Regierung, im ersten Monat, öffnete er die Türen des Hauses Jehovas und besserte sie aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Und er ließ die Priester und die Leviten kommen und versammelte sie auf dem Platze gegen Osten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'und er sprach zu ihnen: Höret mich, ihr Leviten! Heiliget euch nun, und heiliget das Haus Jehovas, des Gottes eurer Väter, und bringet die Unreinigkeit aus dem Heiligtum hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Denn unsere Väter haben treulos gehandelt und getan, was böse ist in den Augen Jehovas, unseres Gottes, und haben ihn verlassen; und sie haben ihr Angesicht von der Wohnung Jehovas abgewandt und ihr den Rücken zugekehrt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'auch haben sie die Türen der Halle verschlossen, und die Lampen ausgelöscht, und dem Gott Israels kein Räucherwerk geräuchert und kein Brandopfer im Heiligtum dargebracht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Und der Zorn Jehovas ist über Juda und Jerusalem gekommen, und er hat sie der Mißhandlung, der Verwüstung und dem Gezisch hingegeben, wie ihr mit euren Augen sehet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Und siehe, deswegen sind unsere Väter durch das Schwert gefallen, und unsere Söhne und unsere Töchter und unsere Weiber sind in Gefangenschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Nun ist es in meinem Herzen, einen Bund zu machen mit Jehova, dem Gott Israels, daß die Glut seines Zornes sich von uns abwende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Meine Söhne, seid nun nicht lässig; denn euch hat Jehova erwählt, um vor ihm zu stehen, daß ihr ihm dienet, und um seine Diener und Räucherer zu sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Da machten sich die Leviten auf: Machath, der Sohn Amasais, und Joel, der Sohn Asarjas, von den Söhnen der Kehathiter; und von den Söhnen Meraris: Kis, der Sohn Abdis, und Asarja, der Sohn Jehallelels; und von den Gersonitern: Joach, der Sohn Simmas, und Eden, der Sohn Joachs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'und von den Söhnen Elizaphans: Schimri und Jeghiel; und von den Söhnen Asaphs: Sekarja und Mattanja;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'und von den Söhnen Hemans: Jechiel und Simei; und von den Söhnen Jeduthuns: Schemaja und Ussiel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Und sie versammelten ihre Brüder und heiligten sich; und sie kamen nach dem Gebot des Königs, den Worten Jehovas gemäß, um das Haus Jehovas zu reinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Und die Priester gingen in das Innere des Hauses Jehovas, um es zu reinigen; und sie brachten alle Unreinigkeit, die sie in dem Tempel Jehovas fanden, in den Hof des Hauses Jehovas hinaus; und die Leviten nahmen sie auf, um sie an den Bach Kidron hinauszubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Und sie fingen am Ersten des ersten Monats an zu heiligen; und am achten Tage des Monats kamen sie in die Halle Jehovas und heiligten das Haus Jehovas acht Tage lang; und am sechzehnten Tage des ersten Monats waren sie fertig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Und sie gingen zu dem König Hiskia hinein und sprachen: Wir haben das ganze Haus Jehovas gereinigt, und den Brandopferaltar und alle seine Geräte und den Tisch der Schichtbrote und alle seine Geräte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Und alle Geräte, die der König Ahas während seiner Regierung in seiner Treulosigkeit entweiht hat, haben wir hergerichtet und geheiligt; und siehe, sie sind vor dem Altar Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Und der König Jehiskia machte sich früh auf und versammelte die Obersten der Stadt, und er ging hinauf in das Haus Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Und sie brachten sieben Farren und sieben Widder und sieben Schafe, und sieben Ziegenböcke zum Sündopfer, für das Königreich und für das Heiligtum und für Juda. Und er befahl den Söhnen Aarons, den Priestern, sie auf dem Altar Jehovas zu opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Und sie schlachteten die Rinder, und die Priester nahmen das Blut auf und sprengten es an den Altar; und sie schlachteten die Widder und sprengten das Blut an den Altar; und sie schlachteten die Schafe und sprengten das Blut an den Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Und sie brachten die Böcke des Sündopfers herzu vor den König und die Versammlung, und sie legten ihre Hände auf dieselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Und die Priester schlachteten sie und taten ihr Blut zur Entsündigung an den Altar, um für ganz Israel Sühnung zu tun; denn für ganz Israel hatte der König das Brandopfer und das Sündopfer befohlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Und er stellte die Leviten auf im Hause Jehovas, mit Zimbeln, mit Harfen und mit Lauten, nach dem Gebote Davids und Gads, des Sehers des Königs, und Nathans, des Propheten; denn das Gebot war durch Jehova, durch seine Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Und die Leviten standen da mit den Instrumenten Davids, und die Priester mit den Trompeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Und Hiskia befahl, das Brandopfer auf dem Altar zu opfern. Und zur Zeit, als das Brandopfer anfing, begann der Gesang Jehovas und die Trompeten, und zwar unter Begleitung der Instrumente Davids, des Königs von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Und die ganze Versammlung betete an, und der Gesang erscholl, und die Trompeten schmetterten; alles das währte bis zur Vollendung des Brandopfers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Und als man das Opfern des Brandopfers vollendet hatte, beugten sich der König und alle, die sich bei ihm befanden, und beteten an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Und der König Jehiskia und die Obersten sagten zu den Leviten, daß sie Jehova lobsingen sollten mit den Worten Davids und Asaphs, des Sehers. Und sie lobsangen mit Freude und neigten sich und beteten an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Und Jehiskia hob an und sprach: Nun habt ihr euch Jehova geweiht; tretet herzu und bringet Schlachtopfer und Dankopfer zum Hause Jehovas. Und die Versammlung brachte Schlachtopfer und Dankopfer, und jeder, der willigen Herzens war, brachte Brandopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Und die Zahl der Brandopfer, welche die Versammlung brachte, war: siebzig Rinder, hundert Widder, zweihundert Schafe; alle diese zum Brandopfer für Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Und der Geheiligten waren: sechshundert Rinder und dreitausend Schafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Nur waren der Priester zu wenig, so daß sie nicht allen Brandopfern die Haut abziehen konnten; und so unterstützten sie ihre Brüder, die Leviten, bis das Werk vollendet war, und bis die Priester sich geheiligt hatten; denn die Leviten waren redlichen Herzens, sich zu heiligen, mehr als die Priester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Aber der Brandopfer war auch eine Menge, mit den Fettstücken der Friedensopfer und mit den Trankopfern für die Brandopfer. Und so wurde der Dienst des Hauses Jehovas eingerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Und Jehiskia und das ganze Volk freuten sich über das, was Gott dem Volke bereitet hatte; denn die Sache war plötzlich geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Und Jehiskia sandte hin zu ganz Israel und Juda und schrieb auch Briefe an Ephraim und Manasse, daß sie zum Hause Jehovas in Jerusalem kommen möchten, um Jehova, dem Gott Israels, Passah zu feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Und der König und seine Obersten und die ganze Versammlung in Jerusalem wurden Rats, das Passah im zweiten Monat zu feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Denn sie konnten es zu jener Zeit nicht feiern, weil die Priester sich nicht in hinreichender Anzahl geheiligt hatten, und das Volk noch nicht nach Jerusalem versammelt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Und die Sache war recht in den Augen des Königs und in den Augen der ganzen Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Und sie setzten fest, einen Ruf ergehen zu lassen durch ganz Israel, von Beerseba bis Dan, daß sie kämen, um Jehova, dem Gott Israels, Passah zu feiern in Jerusalem; denn sie hatten es lange Zeit nicht gefeiert, wie es vorgeschrieben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Und die Läufer gingen mit den Briefen von der Hand des Königs und seiner Obersten durch ganz Israel und Juda, und nach dem Gebot des Königs, und sie sprachen: Kinder Israel! Kehret um zu Jehova, dem Gott Abrahams, Isaaks und Israels; so wird er umkehren zu den Entronnenen, die euch aus der Hand der Könige von Assyrien übriggeblieben sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Und seid nicht wie eure Väter und wie eure Brüder, die treulos gehandelt haben gegen Jehova, den Gott ihrer Väter, so daß er sie der Verwüstung hingegeben hat, wie ihr es sehet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Nun verhärtet euren Nacken nicht, wie eure Väter; gebet Jehova die Hand und kommet zu seinem Heiligtum, das er geheiligt hat auf ewig, und dienet Jehova, eurem Gott, damit die Glut seines Zornes sich von euch wende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Denn wenn ihr zu Jehova umkehret, so werden eure Brüder und eure Kinder Barmherzigkeit finden vor denen, die sie gefangen weggeführt haben, und in dieses Land zurückkehren. Denn gnädig und barmherzig ist Jehova, euer Gott, und er wird das Angesicht nicht von euch abwenden, wenn ihr zu ihm umkehret. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Und die Läufer zogen von Stadt zu Stadt durch das Land Ephraim und Manasse, und bis nach Sebulon; aber man verlachte und verspottete sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Doch einige Männer von Aser und Manasse und von Sebulon demütigten sich und kamen nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Auch über Juda kam die Hand Gottes, daß er ihnen ein einmütiges Herz gab, um das Gebot des Königs und der Obersten zu tun, nach dem Worte Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Und eine Menge Volks versammelte sich nach Jerusalem, um das Fest der ungesäuerten Brote im zweiten Monat zu feiern, eine sehr große Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Und sie machten sich auf und schafften die Altäre weg, die in Jerusalem waren; auch alle Räucheraltäre schafften sie weg und warfen sie in den Bach Kidron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Und man schlachtete das Passah am Vierzehnten des zweiten Monats. Denn die Priester und die Leviten hatten sich geschämt und hatten sich geheiligt; und sie brachten Brandopfer in das Haus Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Und sie standen an ihrem Standorte, nach ihrer Vorschrift, nach dem Gesetz Moses, des Mannes Gottes; die Priester sprengten das Blut aus der Hand der Leviten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Denn es waren viele in der Versammlung, die sich nicht geheiligt hatten; und so besorgten die Leviten das Schlachten der Passahopfer für einen jeden, der nicht rein war, um sie Jehova zu heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Denn ein großer Teil des Volkes, viele von Ephraim und Manasse, Issaschar und Sebulon, hatten sich nicht gereinigt, sondern aßen das Passah nicht, wie es vorgeschrieben ist. Doch Jehiskia bat für sie und sprach: Jehova, der Gütige, möge einem jeden vergeben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'der sein Herz darauf gerichtet hat, Gott zu suchen, Jehova, den Gott seiner Väter, wenn auch nicht gemäß der Reinheit des Heiligtums!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Und Jehova erhörte Jehiskia und heilte das Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Und die Kinder Israel, die sich in Jerusalem befanden, feierten das Fest der ungesäuerten Brote sieben Tage lang mit großer Freude; und die Leviten und die Priester lobten Jehova Tag für Tag mit den Instrumenten des Lobes Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Und Jehiskia redete zum Herzen aller Leviten, welche gute Einsicht in Bezug auf Jehova bewiesen. Und sie aßen das Festopfer die sieben Tage hindurch, indem sie Friedensopfer opferten und Jehova, den Gott ihrer Väter, priesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Und die ganze Versammlung wurde Rats, noch sieben andere Tage zu feiern; und sie feierten die sieben Tage mit Freuden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Denn Jehiskia, der König von Juda, schenkte der Versammlung tausend Farren und siebentausend Stück Kleinvieh; und die Obersten schenkten der Versammlung tausend Farren und zehntausend Stück Kleinvieh. Und die Priester hatten sich in Menge geheiligt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Und so freute sich die ganze Versammlung von Juda, und die Priester und die Leviten, und die ganze Versammlung, welche von Israel gekommen war, und die Fremdlinge, welche aus dem Lande Israel gekommen waren, und die in Juda wohnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Und es war große Freude in Jerusalem; denn seit den Tagen Salomos, des Sohnes Davids, des Königs von Israel, war desgleichen in Jerusalem nicht gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Und die Priester, die Leviten, standen auf und segneten das Volk; und ihre Stimme wurde erhört, und ihr Gebet kam zu seiner heiligen Wohnung, in den Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Und als sie dies alles vollendet hatten, zogen alle Israeliten, die sich daselbst befanden, hinaus zu den Städten Judas; und sie zerschlugen die Bildsäulen und hieben die Ascherim um, und rissen die Höhen und die Altäre nieder in ganz Juda und Benjamin und in Ephraim und Manasse, bis sie damit fertig waren. Und alle Kinder Israel kehrten in ihre Städte zurück, ein jeder zu seinem Besitztum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Und Jehiskia bestellte die Abteilungen der Priester und der Leviten, nach ihren Abteilungen, einen jeden seinem Dienste gemäß, sowohl die Priester als auch die Leviten, zu Brandopfern und zu Friedensopfern, zum Dienen und zum Preisen und zum Loben in den Toren der Lager Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Und er gab das Teil des Königs von seiner Habe zu den Brandopfern: zu den Morgen-und Abendbrandopfern, und zu den Brandopfern der Sabbathe und der Neumonde und der Feste, wie es im Gesetz Jehovas vorgeschrieben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Und er befahl dem Volke, den Bewohnern von Jerusalem, das Teil der Priester und der Leviten zu geben, damit sie am Gesetz Jehovas festhalten möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Und als das Wort kund wurde, brachten die Kinder Israel reichlich Erstlinge vom Getreide, Most und Öl und Honig und von allem Ertrage des Feldes; und den Zehnten von allem brachten sie in Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Und die Kinder Israel und Juda, die in den Städten Judas wohnten, auch sie brachten den Zehnten vom Rind-und Kleinvieh, und den Zehnten von den geheiligten Dingen, die Jehova, ihrem Gott, geheiligt waren, und sie legten Haufen bei Haufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Im dritten Monat fingen sie an, die Haufen aufzuschichten, und im siebten Monat waren sie damit fertig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Und Jehiskia und die Obersten kamen und besichtigten die Haufen, und sie priesen Jehova und sein Volk Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Und Jehiskia befragte die Priester und die Leviten wegen der Haufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Da sprach Asarja, der Hauptpriester, vom Hause Zadok, zu ihm und sagte: Seitdem man angefangen hat, das Hebopfer in das Haus Jehovas zu bringen, haben wir gegessen und sind satt geworden und haben übriggelassen in Menge; denn Jehova hat sein Volk gesegnet; und das Übriggebliebene ist diese große Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Und Jehiskia befahl, Vorratskammern im Hause Jehovas zu bereiten; und sie bereiteten sie;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'und sie brachten das Hebopfer und den Zehnten und die geheiligten Dinge treulich hinein. Und Oberaufseher über dieselben war Konanja, der Levit, und Simei, sein Bruder, als zweiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Und Jechiel und Asasja und Nachath und Asael und Jerimoth und Josabad und Eliel und Jismakja und Machath und Benaja waren Aufseher zur Hand Konanjas und Simeis, seines Bruders, durch Verordnung des Königs Jehiskia und Asarjas, des Fürsten des Hauses Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Und Kore, der Sohn Jimnas, der Levit, der Torhüter gegen Osten, war über die freiwilligen Gaben Gottes, um das Hebopfer Jehovas und das Hochheilige herauszugeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Und unter seiner Hand waren Eden und Minjamin und Jeschua und Schemaja, Amarja und Schekanja in den Städten der Priester, mit Treue, um ihren Brüdern nach den Abteilungen zu geben, dem Größten wie dem Kleinsten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'außer denen von ihnen, welche als Männliche ins Geschlechtsverzeichnis eingetragen waren, von drei Jahren an und darüber, allen, die in das Haus Jehovas kamen, nach der täglichen Gebühr zu ihrem Dienst in ihren Ämtern, nach ihren Abteilungen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'sowohl den ins Geschlechtsverzeichnis eingetragenen Priestern, nach ihren Vaterhäusern, als auch den Leviten, von zwanzig Jahren an und darüber, in ihren Ämtern, nach ihren Abteilungen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'und den ins Geschlechtsverzeichnis Eingetragenen unter allen ihren Kindlein, ihren Weibern und ihren Söhnen und ihren Töchtern, der ganzen Versammlung. Denn in ihrer Treue heiligten sie sich, um heilig zu sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Und für die Söhne Aarons, die Priester, auf den Feldern des Bezirks ihrer Städte, waren in jeder einzelnen Stadt Männer angestellt, die mit Namen angegeben waren, um jedem Männlichen unter den Priestern und jedem ins Geschlechtsverzeichnis Eingetragenen unter den Leviten Teile zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Und desgleichen tat Jehiskia in ganz Juda. Und er tat, was gut und recht und wahr war vor Jehova, seinem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Und in allem Werke, das er anfing im Dienste des Hauses Gottes und in dem Gesetz und in dem Gebot, um seinen Gott zu suchen, handelte er mit ganzem Herzen, und es gelang ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Nach diesen Dingen und dieser Treue kam Sanherib, der König von Assyrien; und er drang in Juda ein und lagerte sich wider die festen Städte, und er gedachte, sie für sich zu erobern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Und als Jehiskia sah, daß Sanherib gekommen und daß sein Angesicht zum Streit wider Jerusalem gerichtet war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'da beriet er sich mit seinen Obersten und seinen Helden, die Wasser der Quellen zu verstopfen, welche außerhalb der Stadt waren; und sie halfen ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Und es versammelte sich viel Volks, und sie verstopften alle Quellen und den Bach, der mitten durch das Land fließt, indem sie sprachen: Warum sollten die Könige von Assyrien kommen und viel Wasser finden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Und er faßte Mut und baute die ganze Mauer, wo sie eingerissen war, und führte sie auf bis an die Türme, und die andere Mauer außerhalb, und befestigte das Millo der Stadt Davids; und er verfertigte Waffen in Menge und Schilde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Auch setzte er Kriegsoberste über das Volk; und er versammelte sie zu sich auf den Platz am Stadttore, und redete zu ihren Herzen und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Seid stark und mutig! Fürchtet euch nicht und erschrecket nicht vor dem König von Assyrien und vor all der Menge, die mit ihm ist; denn mit uns sind mehr als mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Mit ihm ist ein Arm des Fleisches; aber mit uns ist Jehova, unser Gott, um uns zu helfen und unsere Streite zu führen! Und das Volk verließ sich auf die Worte Jehiskias, des Königs von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Nach diesem sandte Sanherib, der König von Assyrien, seine Knechte nach Jerusalem (er war aber noch vor Lachis, und seine ganze Macht mit ihm) an Jehiskia, den König von Juda, und an ganz Juda, das in Jerusalem war, und ließ ihnen sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'So spricht Sanherib, der König von Assyrien: Worauf vertrauet ihr, daß ihr in Belagerung bleibet zu Jerusalem?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Verführt euch Jehiskia nicht, um euch dem Tode durch Hunger und Durst preiszugeben, indem er spricht: Jehova, unser Gott, wird uns aus der Hand des Königs von Assyrien erretten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Ist es nicht Jehiskia, der seine Höhen und seine Altäre hinweggetan, und zu Juda und zu Jerusalem gesprochen und gesagt hat: Vor einem Altar sollt ihr anbeten, und auf ihm sollt ihr räuchern?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Wisset ihr nicht, was ich und meine Väter allen Völkern der Länder getan haben? Haben die Götter der Nationen der Länder irgendwie vermocht, ihr Land aus meiner Hand zu erretten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Wer ist unter allen Göttern dieser Nationen, die meine Väter vertilgt haben, der vermocht hätte, sein Volk aus meiner Hand zu erretten, daß euer Gott vermögen sollte, euch aus meiner Hand zu erretten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Und nun, daß euch Hiskia nicht täusche, und daß er euch nicht auf solche Weise verführe! Und glaubet ihm nicht! Denn kein Gott irgend einer Nation und irgend eines Königreiches hat sein Volk aus meiner Hand und aus der Hand meiner Väter zu erretten vermocht; wieviel weniger wird euer Gott euch aus meiner Hand erretten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Und noch mehr redeten seine Knechte wider Jehova Gott und wider Jehiskia, seinen Knecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Auch schrieb er einen Brief, um Jehova, den Gott Israels, zu verhöhnen und wider ihn zu reden, indem er sprach: Gleich den Göttern der Nationen der Länder, welche ihr Volk nicht aus meiner Hand errettet haben, so wird auch der Gott Jehiskias sein Volk nicht aus meiner Hand erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Und sie riefen dem Volke von Jerusalem, das auf der Mauer war, mit lauter Stimme auf jüdisch zu, um sie zu schrecken und bestürzt zu machen, damit sie die Stadt einnähmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Und sie redeten von dem Gott Jerusalems wie von den Göttern der Völker der Erde, einem Machwerk von Menschenhänden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Und der König Jehiskia und Jesaja, der Sohn Amoz\', der Prophet, beteten dieserhalb und schrieen gen Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Da sandte Jehova einen Engel, der alle tapferen Helden und Fürsten und Obersten im Lager des Königs von Assyrien vertilgte; und dieser zog mit Beschämung des Angesichts in sein Land zurück. Und als er in das Haus seines Gottes ging, fällten ihn daselbst durch das Schwert solche, die aus seinem Leibe hervorgegangen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'So rettete Jehova Jehiskia und die Bewohner von Jerusalem aus der Hand Sanheribs, des Königs von Assyrien, und aus der Hand aller; und er schützte sie ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Und viele brachten Gaben für Jehova nach Jerusalem, und Kostbarkeiten für Jehiskia, den König von Juda; und er wurde danach erhoben in den Augen aller Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'In jenen Tagen wurde Jehiskia krank zum Sterben; und er betete zu Jehova. Und Jehova redete zu ihm und gab ihm ein Wunder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Aber Jehiskia vergalt nicht nach der Wohltat, die ihm erwiesen worden war, denn sein Herz überhob sich; und es kam ein Zorn über ihn und über Juda und Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Da demütigte sich Jehiskia wegen der Überhebung seines Herzens, er und die Bewohner von Jerusalem; und der Zorn Jehovas kam nicht über sie in den Tagen Jehiskias.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Und Jehiskia hatte sehr viel Reichtum und Ehre. Und er machte sich Schatzkammern für Silber und Gold und Edelsteine, und für Gewürze, und für Schilde und für allerlei kostbare Geräte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'und Vorratshäuser für den Ertrag an Getreide und Most und Öl, und Ställe für allerlei Vieh, und er verschaffte sich Herden für die Ställe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Und er legte sich Städte an, und Herden von Kleinvieh und Rinder in Menge; denn Gott gab ihm eine sehr große Habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Und er, Jehiskia, verstopfte den oberen Ausfluß der Wasser des Gihon und leitete sie unter dem Boden westwärts nach der Stadt Davids. Und Jehiskia hatte Gelingen in all seinem Tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Und so verließ ihn Gott bei den Gesandten der Fürsten von Babel (die zu ihm gesandt hatten, um nach dem Wunder zu fragen, welches im Lande geschehen war), um ihn zu versuchen, damit er alles erkennte, was in seinem Herzen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Und das Übrige der Geschichte Jehiskias und seine guten Taten, siehe, sie sind geschrieben in dem Gesichte Jesajas, des Sohnes Amoz\', des Propheten, in dem Buche der Könige von Juda und Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Und Jehiskia legte sich zu seinen Vätern, und man begrub ihn auf der Anhöhe der Gräber der Söhne Davids; und ganz Juda und die Bewohner von Jerusalem erzeigten ihm Ehre bei seinem Tode. Und Manasse, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Zwölf Jahre war Manasse alt, als er König wurde, und er regierte fünfundfünfzig Jahre zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Und er tat, was böse war in den Augen Jehovas, nach den Greueln der Nationen, die Jehova vor den Kindern Israel ausgetrieben hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Und er baute die Höhen wieder auf, die sein Vater Jehiskia niedergerissen hatte, und errichtete den Baalim Altäre, und machte Ascheroth, und beugte sich nieder vor dem ganzen Heere des Himmels und diente ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Und er baute Altäre in dem Hause Jehovas, von welchem Jehova gesagt hatte: In Jerusalem soll mein Name sein ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Und er baute dem ganzen Heere des Himmels Altäre in den beiden Höfen des Hauses Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Und er ließ seine Söhne durchs Feuer gehen im Tale des Sohnes Hinnoms, und er trieb Zauberei und Wahrsagerei und Beschwörung, und bestellte Totenbeschwörer und Wahrsager: er tat viel Böses in den Augen Jehovas, um ihn zu reizen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Und er stellte das geschnitzte Bild des Gleichnisses, das er gemacht hatte, in das Haus Gottes, von welchem Gott zu David und zu seinem Sohne Salomo gesagt hatte: In dieses Haus und in Jerusalem, das ich aus allen Stämmen Israels erwählt habe, will ich meinen Namen setzen ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Und ich will den Fuß Israels nicht mehr aus dem Lande weichen lassen, welches ich euren Vätern bestimmt habe, wenn sie nur darauf achten, alles zu tun, was ich ihnen geboten habe, nach dem ganzen Gesetz und den Satzungen und den Rechten durch Mose.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Aber Manasse verleitete Juda und die Bewohner von Jerusalem, mehr Böses zu tun, als die Nationen, welche Jehova vor den Kindern Israel vertilgt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Und Jehova redete zu Manasse und zu seinem Volke; aber sie merkten nicht darauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Da ließ Jehova die Heerobersten des Königs von Assyrien über sie kommen; und sie nahmen Manasse gefangen und banden ihn mit ehernen Fesseln und führten ihn nach Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Und als er bedrängt war, flehte er Jehova, seinen Gott, an und demütigte sich sehr vor dem Gott seiner Väter und betete zu ihm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'und er ließ sich von ihm erbitten und erhörte sein Flehen, und brachte ihn nach Jerusalem in sein Königreich zurück. Da erkannte Manasse, daß Jehova Gott ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Und hernach baute er die äußere Mauer der Stadt Davids, westlich gegen den Gihon hin, im Tale, und bis zum Eingang des Fischtores, und umgab den Ophel mit einer Mauer und machte sie sehr hoch. Und er legte Kriegsoberste in alle festen Städte in Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Und er tat die Götter der Fremde hinweg und das Gleichnis aus dem Hause Jehovas, und alle Altäre, die er auf dem Berge des Hauses Jehovas und in Jerusalem gebaut hatte; und er warf sie hinaus außerhalb der Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Und er baute den Altar Jehovas wieder auf und opferte auf demselben Friedens-und Dankopfer; und er befahl Juda, daß sie Jehova, dem Gott Israels, dienen sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Aber das Volk opferte noch auf den Höhen, wiewohl Jehova, ihrem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Und das Übrige der Geschichte Manasses, und sein Gebet zu seinem Gott, und die Worte der Seher, die zu ihm redeten im Namen Jehovas, des Gottes Israels, siehe, das ist geschrieben in der Geschichte der Könige von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Sein Gebet aber, und wie Gott sich von ihm erbitten ließ, und alle seine Sünde und seine Untreue, und die Orte, an welchen er Höhen gebaut und die Ascherim und die geschnitzten Bilder aufgestellt hatte, bevor er sich demütigte: siehe, das ist geschrieben in der Geschichte Hosais.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Und Manasse legte sich zu seinen Vätern, und man begrub ihn in seinem Hause. Und Amon, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Zweiundzwanzig Jahre war Amon alt, als er König wurde, und er regierte zwei Jahre zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Und er tat, was böse war in den Augen Jehovas, wie sein Vater Manasse getan hatte; und Amon opferte allen geschnitzten Bildern, welche sein Vater Manasse gemacht hatte, und diente ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Und er demütigte sich nicht vor Jehova, wie sein Vater Manasse sich gedemütigt hatte; sondern er, Amon, häufte die Schuld.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Und seine Knechte machten eine Verschwörung wider ihn und töteten ihn in seinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Da erschlug das Volk des Landes alle, die sich wider den König Amon verschworen hatten; und das Volk des Landes machte Josia, seinen Sohn, zum König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Acht Jahre war Josia alt, als er König wurde, und er regierte einunddreißig Jahre zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Und er tat, was recht war in den Augen Jehovas; und er wandelte auf den Wegen seines Vaters David und wich nicht zur Rechten noch zur Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Und im achten Jahre seiner Regierung, als er noch ein Knabe war, fing er an, den Gott seines Vaters David zu suchen; und im zwölften Jahre fing er an, Juda und Jerusalem von den Höhen und den Ascherim und den geschnitzten und den gegossenen Bildern zu reinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Und man riß die Altäre der Baalim vor ihm nieder; und die Sonnensäulen, welche oben auf denselben waren, hieb er um; und die Ascherim und die geschnitzten und die gegossenen Bilder zerschlug und zermalmte er, und streute sie auf die Gräber derer, welche ihnen geopfert hatten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'und die Gebeine der Priester verbrannte er auf ihren Altären. Und so reinigte er Juda und Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Und in den Städten von Manasse und Ephraim und Simeon, und bis nach Naphtali hin, in ihren Trümmern ringsum, riß er die Altäre nieder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'und die Ascherim und die geschnitzten Bilder zertrümmerte er, indem er sie zermalmte; und alle Sonnensäulen hieb er um im ganzen Lande Israel. Und er kehrte nach Jerusalem zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Und im achtzehnten Jahre seiner Regierung, während er das Land und das Haus reinigte, sandte er Schaphan, den Sohn Azaljas, und Maaseja, den Obersten der Stadt, und Joach, den Sohn Joachas\', den Geschichtsschreiber, um das Haus Jehovas, seines Gottes, auszubessern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Und sie kamen zu Hilkija, dem Hohenpriester, und gaben das Geld, welches in das Haus Gottes gebracht worden war, das die Leviten, die Hüter der Schwelle, eingesammelt hatten, von der Hand Manasses und Ephraims und vom ganzen Überrest Israels, und von ganz Juda und Benjamin und den Bewohnern von Jerusalem:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'sie gaben es in die Hand derer, welche das Werk betrieben, die am Hause Jehovas bestellt waren. Und diese gaben es denen, welche das Werk taten, die im Hause Jehovas arbeiteten, um das Haus herzustellen und auszubessern:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'sie gaben es den Zimmerleuten und den Bauleuten, um gehauene Steine und Holz zu den Bindebalken zu kaufen, und um die Häuser zu bälken, welche die Könige von Juda verderbt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Und die Männer handelten getreulich an dem Werke. Und über sie waren bestellt Jachath und Obadja, die Leviten, von den Söhnen Meraris, und Sekarja und Meschullam von den Söhnen der Kehathiter, um die Aufsicht zu führen; und die Leviten, alle, welche der Musikinstrumente kundig waren,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'waren sowohl über die Lastträger gesetzt, als auch Aufseher über alle, die da arbeitete in jedem Dienste; und andere von den Leviten waren Schreiber und Vorsteher und Torhüter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Und als sie das Geld herausnahmen, welches in das Haus Jehovas gebracht worden war, fand der Priester Hilkija das Buch des Gesetzes Jehovas durch Mose.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Da hob Hilkija an und sprach zu Schaphan, dem Schreiber: Ich habe das Buch des Gesetzes im Hause Jehovas gefunden. Und Hilkija gab das Buch dem Schaphan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Und Schaphan brachte das Buch zu dem König; und er brachte ferner dem König Nachricht und sprach: Alles, was der Hand deiner Knechte übergeben worden ist, das tun sie:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'sie haben das Geld, welches im Hause Jehovas gefunden worden ist, ausgeschüttet und es in die Hand derer gegeben, welche zur Aufsicht bestellt sind, und in die Hand derer, welche das Werk tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Und Schaphan, der Schreiber, berichtete dem König und sprach: Der Priester Hilkija hat mir ein Buch gegeben. Und Schaphan las darin vor dem König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Und es geschah, als der König die Worte des Gesetzes hörte, da zerriß er seine Kleider.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Und der König gebot Hilkija und Achikam, dem Sohne Schaphans, und Abdon, dem Sohne Michas, und Schaphan, dem Schreiber, und Asaja, dem Knechte des Königs, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Gehet hin, befraget Jehova für mich und für die Übriggebliebenen in Israel und in Juda wegen der Worte des aufgefundenen Buches. Denn groß ist der Grimm Jehovas, der sich über uns ergossen hat, darum daß unsere Väter das Wort Jehovas nicht beobachtet haben, um nach allem zu tun, was in diesem Buche geschrieben steht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Da gingen Hilkija und diejenigen, welche der König entboten hatte, zu der Prophetin Hulda, dem Weibe Schallums, des Sohnes Tokhaths, des Sohnes Hasras, des Hüters der Kleider; sie wohnte aber zu Jerusalem im zweiten Stadtteile; und sie redeten auf diese Weise zu ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Und sie sprach zu ihnen: So spricht Jehova, der Gott Israels: Saget dem Manne, der euch zu mir gesandt hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'So spricht Jehova: Siehe, ich will Unglück bringen über diesen Ort und über seine Bewohner: alle die Flüche, welche in dem Buche geschrieben sind, das man vor dem König von Juda gelesen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Darum daß sie mich verlassen und anderen Göttern geräuchert haben, um mich zu reizen mit all den Machwerken ihrer Hände, so hat mein Grimm sich über diesen Ort ergossen, und er wird nicht erlöschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Zu dem König von Juda aber, der euch gesandt hat, um Jehova zu befragen, zu ihm sollt ihr also sprechen: So spricht Jehova, der Gott Israels: Die Worte anlangend, die du gehört hast,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'weil dein Herz weich geworden, und du dich vor Gott gedemütigt hast, als du seine Worte über diesen Ort und über seine Bewohner hörtest, und du dich vor mir gedemütigt und deine Kleider zerrissen und vor mir geweint hast, so habe ich es auch gehört, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Siehe, ich werde dich zu deinen Vätern versammeln, und du wirst zu deinen Gräbern versammelt werden in Frieden; und deine Augen sollen all das Unglück nicht ansehen, das ich über diesen Ort und über seine Bewohner bringen werde. Und sie brachten dem König Antwort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Und der König sandte hin und versammelte alle Ältesten von Juda und von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Und der König ging hinauf in das Haus Jehovas, und alle Männer von Juda und die Bewohner von Jerusalem, und die Priester und die Leviten, und alles Volk, vom Größten bis zum Kleinsten; und man las vor ihren Ohren alle Worte des Buches des Bundes, das im Hause Jehovas gefunden worden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Und der König stand auf seinem Standorte und machte den Bund vor Jehova, Jehova nachzuwandeln und seine Gebote und seine Zeugnisse und seine Satzungen zu beobachten mit seinem ganzen Herzen und mit seiner ganzen Seele, um die Worte des Bundes zu tun, welche in diesem Buche geschrieben sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Und er ließ alle in den Bund treten, welche sich in Jerusalem und in Benjamin befanden. Und die Bewohner von Jerusalem taten nach dem Bunde Gottes, des Gottes ihrer Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Und Josia tat alle Greuel hinweg aus allen Ländern, welche den Kindern Israel gehörten; und er hielt alle an, die sich in Israel befanden, Jehova, ihrem Gott, zu dienen. Alle seine Tage wichen sie nicht ab von der Nachfolge Jehovas, des Gottes ihrer Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Und Josia feierte dem Jehova Passah zu Jerusalem; und man schlachtete das Passah am Vierzehnten des ersten Monats.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Und er stellte die Priester in ihre Ämter und ermutigte sie zum Dienst des Hauses Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Und er sprach zu den Leviten, welche ganz Israel unterwiesen, die Jehova geheiligt waren: Setzet die heilige Lade in das Haus, welches Salomo, der Sohn Davids, der König von Israel, gebaut hat; ihr habt sie nicht mehr auf der Schulter zu tragen. Dienet nunmehr Jehova, eurem Gott, und seinem Volke Israel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'und bereitet euch nach euren Vaterhäusern, in euren Abteilungen, nach der Schrift Davids, des Königs von Israel, und nach der Schrift seines Sohnes Salomo;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'und stellet euch im Heiligtum auf nach den Klassen der Vaterhäuser eurer Brüder, der Kinder des Volkes, und zwar je eine Abteilung eines Vaterhauses der Leviten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'und schlachtet das Passah, und heiliget euch und bereitet es für eure Brüder, daß ihr tuet nach dem Worte Jehovas durch Mose.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Und Josia schenkte den Kindern des Volkes an Kleinvieh: Lämmer und Ziegenböcklein, alles zu den Passahopfern für alle, die sich vorfanden dreißigtausend an der Zahl, und dreitausend Rinder; das war von der Habe des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Und seine Obersten schenkten freiwillig für das Volk, für die Priester und für die Leviten. Hilkija und Sekarja und Jechiel, die Fürsten des Hauses Gottes, gaben den Priestern zu den Passahopfern zweitausendsechshundert Stück Kleinvieh und dreihundert Rinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Und Konanja, und Schemanja und Nethaneel, seine Brüder, und Haschabja und Jeghiel und Josabad, die Obersten der Leviten, schenkten den Leviten zu den Passahopfern fünftausend Stück Kleinvieh und fünfhundert Rinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Und der Dienst wurde eingerichtet; und die Priester standen an ihrer Stelle und die Leviten in ihren Abteilungen, nach dem Gebote des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Und sie schlachteten das Passah; und die Priester sprengten das Blut aus ihrer Hand, und die Leviten zogen die Haut ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Und sie taten die Brandopfer beiseite, um sie den Klassen der Vaterhäuser der Kinder des Volkes zu geben, um sie Jehova darzubringen, wie im Buche Moses geschrieben steht; und ebenso taten sie mit den Rindern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Und sie brieten das Passah am Feuer nach der Vorschrift; und die geheiligten Dinge kochten sie in Töpfen und in Kesseln und in Schüsseln, und verteilten sie eilends an alle Kinder des Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Und danach bereiteten sie für sich und für die Priester; denn die Priester, die Söhne Aarons, waren mit dem Opfern der Brandopfer und der Fettstücke bis zur Nacht beschäftigt; und so bereiteten die Leviten für sich und für die Priester, die Söhne Aarons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Und die Sänger, die Söhne Asaphs, waren an ihrer Stelle, nach dem Gebote Davids und Asaphs und Hemans und Jeduthuns, des Sehers des Königs; und die Torhüter waren an jedem Tore: sie hatten nicht nötig, von ihrem Dienste zu weichen, weil ihre Brüder, die Leviten, für sie bereiteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Und so wurde der ganze Dienst Jehovas an jenem Tage eingerichtet, um das Passah zu feiern und die Brandopfer auf dem Altar Jehovas zu opfern, nach dem Gebote des Königs Josia.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Und die Kinder Israel, die sich vorfanden, feierten das Passah zu selbiger Zeit, und das Fest der ungesäuerten Brote sieben Tage lang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Und es war kein solches Passah in Israel gefeiert worden wie dieses, seit den Tagen Samuels, des Propheten; und alle Könige von Israel hatten kein Passah gefeiert wie dasjenige, welches Josia feierte und die Priester und die Leviten und ganz Juda und Israel, das sich vorfand, und die Bewohner von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Im achtzehnten Jahre der Regierung Josias ist dieses Passah gefeiert worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Nach allem diesem, als Josia das Haus eingerichtet hatte, zog Neko, der König von Ägypten, hinauf, um wider Karchemis am Phrat zu streiten; und Josia zog aus, ihm entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Da sandte er Boten zu ihm und ließ ihm sagen: Was haben wir miteinander zu schaffen, König von Juda? Nicht wider dich komme ich heute, sondern wider das Haus, mit dem ich Krieg führe; und Gott hat gesagt, daß ich eilen sollte. Stehe ab von Gott, der mit mir ist, daß er dich nicht verderbe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Aber Josia wandte sein Angesicht nicht von ihm ab, sondern verkleidete sich, um wider ihn zu streiten; und er hörte nicht auf die Worte Nekos, die aus dem Munde Gottes kamen. Und er kam in das Tal Megiddo, um zu streiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Und die Schützen schossen auf den König Josia. Da sprach der König zu seinen Knechten: Bringet mich hinweg, denn ich bin schwer verwundet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Und seine Knechte brachten ihn von dem Wagen hinweg und setzten ihn auf den zweiten Wagen, den er hatte, und führten ihn nach Jerusalem. Und er starb und wurde in den Gräbern seiner Väter begraben; und ganz Juda und Jerusalem trauerten um Josia.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Und Jeremia stimmte ein Klagelied über Josia an. Und alle Sänger und Sängerinnen haben in ihren Klageliedern von Josia geredet bis auf den heutigen Tag; und man machte sie zu einem Gebrauch in Israel. Und siehe, sie sind geschrieben in den Klageliedern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Und das Übrige der Geschichte Josias und seine guten Taten, nach dem, was im Gesetz Jehovas geschrieben steht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'und seine Geschichte, die erste und die letzte, siehe, sie ist geschrieben in dem Buche der Könige von Israel und Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Und das Volk des Landes nahm Joahas, den Sohn Josias, und sie machten ihn zum König in Jerusalem an seines Vaters Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Dreiundzwanzig Jahre war Joahas alt, als er König wurde, und er regierte drei Monate zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Und der König von Ägypten setzte ihn ab zu Jerusalem; und er legte dem Lande eine Buße von hundert Talenten Silber und einem Talente Gold auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Und der König von Ägypten machte seinen Bruder Eljakim zum König über Juda und Jerusalem und verwandelte seinen Namen in Jojakim. Seinen Bruder Joahas aber nahm Neko fest und führte ihn nach Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Fünfundzwanzig Jahre war Jojakim alt, als er König wurde, und er regierte elf Jahre zu Jerusalem. Und er tat, was böse war in den Augen Jehovas, seines Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Wider ihn zog Nebukadnezar, der König von Babel, herauf; und er band ihn mit ehernen Fesseln, um ihn nach Babel zu führen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Auch von den Geräten des Hauses Jehovas brachte Nebukadnezar nach Babel und legte sie in seinen Tempel zu Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Und das Übrige der Geschichte Jojakims, und seine Greuel, die er verübt hat, und was an ihm gefunden wurde, siehe, das ist geschrieben in dem Buche der Könige von Israel und Juda. Und Jojakin, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Achtzehn Jahre war Jojakin alt, als er König wurde, und er regierte drei Monate und zehn Tage zu Jerusalem. Und er tat, was böse war in den Augen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Und beim Umlauf des Jahres sandte der König Nebukadnezar hin und ließ ihn nach Babel bringen samt den kostbaren Geräten des Hauses Jehovas; und er machte seinen Bruder Zedekia zum König über Juda und Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Einundzwanzig Jahre war Zedekia alt, als er König wurde, und er regierte elf Jahre zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Und er tat, was böse war in den Augen Jehovas, seines Gottes. Er demütigte sich nicht vor dem Propheten Jeremia, als er nach dem Befehle Jehovas redete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Und auch empörte er sich gegen den König Nebukadnezar, der ihn bei Gott hatte schwören lassen. Und er verhärtete seinen Nacken und verstockte sein Herz, so daß er nicht umkehrte zu Jehova, dem Gott Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Auch alle Obersten der Priester und das Volk häuften die Treulosigkeiten, nach allen Greueln der Nationen, und verunreinigten das Haus Jehovas, das er in Jerusalem geheiligt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Und Jehova, der Gott ihrer Väter, sandte zu ihnen durch seine Boten, früh sich aufmachend und sendend; denn er erbarmte sich seines Volkes und seiner Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Aber sie verspotteten die Boten Gottes und verachteten seine Worte und äfften seine Propheten, bis der Grimm Jehovas gegen sein Volk stieg, daß keine Heilung mehr war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Und er ließ den König der Chaldäer wider sie heraufkommen, und der erschlug ihre Jünglinge mit dem Schwerte im Hause ihres Heiligtums: er schonte nicht des Jünglings und der Jungfrau, des Alten und des Greises: alle gab er in seine Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Und alle Geräte des Hauses Gottes, die großen und die kleinen, und die Schätze des Hauses Jehovas, und die Schätze des Königs und seiner Obersten: alles brachte er nach Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Und sie verbrannten das Haus Gottes und rissen die Mauer von Jerusalem nieder; und alle seine Paläste verbrannten sie mit Feuer, und alle seine kostbaren Geräte verderbten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Und die vom Schwerte Übriggebliebenen führte er nach Babel hinweg; und sie wurden ihm und seinen Söhnen zu Knechten, bis das Königreich der Perser zur Herrschaft kam;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'damit erfüllt würde das Wort Jehovas durch den Mund Jeremias, bis das Land seine Sabbathe genossen hätte. Alle die Tage seiner Verwüstung hatte es Ruhe, bis siebzig Jahre voll waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Und im ersten Jahre Kores\', des Königs von Persien damit das Wort Jehovas durch den Mund Jeremias erfüllt würde erweckte Jehova den Geist Kores\', des Königs von Persien; und er ließ einen Ruf ergehen durch sein ganzes Königreich, und zwar auch schriftlich, indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'So spricht Kores, der König von Persien: Alle Königreiche der Erde hat Jehova, der Gott des Himmels, mir gegeben; und er hat mich beauftragt, ihm ein Haus zu bauen zu Jerusalem, das in Juda ist. Wer irgend unter euch aus seinem Volke ist, mit dem sei Jehova, sein Gott; und er ziehe hinauf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Und im ersten Jahre Kores\', des Königs von Persien, damit das Wort Jehovas aus dem Munde Jeremias erfüllt würde, erweckte Jehova den Geist Kores\', des Königs von Persien; und er ließ einen Ruf ergehen durch sein ganzes Königreich, und zwar auch schriftlich, indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'So spricht Kores, der König von Persien: Alle Königreiche der Erde hat Jehova, der Gott des Himmels, mir gegeben; und er hat mich beauftragt, ihm ein Haus zu bauen zu Jerusalem, das in Juda ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Wer irgend unter euch aus seinem Volke ist, mit dem sei sein Gott, und er ziehe hinauf nach Jerusalem, das in Juda ist, und baue das Haus Jehovas, des Gottes Israels (er ist Gott), in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Und jeder, der übrigbleibt an irgend einem Orte, wo er sich aufhält, den sollen die Leute seines Ortes unterstützen mit Silber und mit Gold und mit Habe und mit Vieh, nebst den freiwilligen Gaben für das Haus Gottes in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Und es machten sich auf die Häupter der Väter von Juda und Benjamin, und die Priester und die Leviten, ein jeder, dessen Geist Gott erweckte, hinaufzuziehen, um das Haus Jehovas in Jerusalem zu bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Und alle, die um sie her waren, unterstützten sie mit silbernen Geräten, mit Gold, mit Habe und mit Vieh und mit Kostbarkeiten, außer allem, was freiwillig gegeben wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Und der König Kores ließ die Geräte des Hauses Jehovas herausbringen, welche Nebukadnezar aus Jerusalem weggeführt und in das Haus seines Gottes gelegt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Und Kores, der König von Persien, ließ sie herausbringen unter der Aufsicht Mithredaths, des Schatzmeisters; und dieser zählte sie dem Sesbazar, dem Fürsten Judas, dar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Und dies ist ihre Zahl: dreißig goldene Becken, tausend silberne Becken, neunundzwanzig Messer,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'dreißig goldene Becher, vierhundertzehn silberne Becher von zweiter Gattung, tausend andere Geräte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Aller Geräte von Gold und von Silber waren fünftausend vierhundert. Das alles brachte Sesbazar hinauf, als die Weggeführten aus Babel nach Jerusalem hinaufgeführt wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Und dies sind die Kinder der Landschaft Juda, welche aus der Gefangenschaft der Weggeführten, die Nebukadnezar, der König von Babel, nach Babel weggeführt hatte, hinaufzogen, und die nach Jerusalem und Juda zurückkehrten, ein jeder in seine Stadt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'welche kamen mit Serubbabel, Jeschua, Nehemia, Seraja, Reelaja, Mordokai, Bilschan, Mispar, Bigwai, Rechum, Baana. Zahl der Männer des Volkes Israel:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Die Söhne Parhosch\', zweitausend einhundertzweiundsiebzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Die Söhne Schephatjas, dreihundertzweiundsiebzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'die Söhne Arachs, siebenhundertfünfundsiebzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'die Söhne Pachath-Moabs, von den Söhnen Jeschuas und Joabs, zweitausend achthundertzwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'die Söhne Elams, tausend zweihundertvierundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'die Söhne Sattus, neunhundertfünfundvierzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'die Söhne Sakkais, siebenhundertsechzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'die Söhne Banis, sechshundertzweiundvierzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'die Söhne Bebais, sechshundertdreiundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'die Söhne Asgads, tausend zweihundertzweiundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'die Söhne Adonikams, sechshundertsechsundsechzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'die Söhne Bigwais, zweitausend sechsundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'die Söhne Adins, vierhundertvierundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'die Söhne Aters, von Jehiskia, achtundneunzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'die Söhne Bezais, dreihundertdreiundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'die Söhne Jorahs, hundertzwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'die Söhne Haschums, zweihundertdreiundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'die Söhne Gibbars, fünfundneunzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'die Söhne Bethlehems, hundertdreiundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'die Männer von Netopha, sechsundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'die Männer von Anathoth, hundertachtundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'die Söhne Asmaweths, zweiundvierzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'die Söhne Kirjath-Arims, Kephiras und Beeroths, siebenhundertdreiundvierzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'die Söhne Ramas und Gebas, sechshunderteinundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'die Männer von Mikmas, hundertzweiundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'die Männer von Bethel und Ai, zweihundertdreiundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'die Söhne Nebos, zweiundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'die Söhne Magbisch\', hundertsechsundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'die Söhne des anderen Elam, tausend zweihundertvierundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'die Söhne Harims, dreihundertzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'die Söhne Lods, Hadids und Onos, siebenhundertfünfundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'die Söhne Jerechos, dreihundertfünfundvierzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'die Söhne Senaas, dreitausend sechshundertdreißig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Die Priester: die Söhne Jedajas, vom Hause Jeschua, neunhundertdreiundsiebzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'die Söhne Immers, tausend zweiundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'die Söhne Paschchurs, tausend zweihundertsiebenundvierzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'die Söhne Harims, tausend und siebzehn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Die Leviten: die Söhne Jeschuas und Kadmiels, von den Söhnen Hodawjas, vierundsiebzig. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Die Sänger: die Söhne Asaphs, hundertachtundzwanzig. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Die Söhne der Torhüter: die Söhne Schallums, die Söhne Aters, die Söhne Talmons, die Söhne Akkubs, die Söhne Hatitas, die Söhne Schobais, allesamt hundertneununddreißig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Die Nethinim: die Söhne Zichas, die Söhne Hasuphas, die Söhne Tabbaoths,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'die Söhne Keros\', die Söhne Siahas, die Söhne Padons,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'die Söhne Lebanas, die Söhne Hagabas, die Söhne Akkubs,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'die Söhne Hagabs, die Söhne Schalmais, die Söhne Hanans,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'die Söhne Giddels, die Söhne Gachars, die Söhne Reajas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'die Söhne Rezins, die Söhne Nekodas, die Söhne Gassams,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'die Söhne Ussas, die Söhne Paseachs, die Söhne Besais,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'die Söhne Asnas, die Söhne der Meunim, die Söhne der Nephisim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'die Söhne Bakbuks, die Söhne Hakuphas, die Söhne Harchurs,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'die Söhne Bazluths, die Söhne Mechidas, die Söhne Harschas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'die Söhne Barkos\', die Söhne Siseras, die Söhne Tamachs,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'die Söhne Neziachs, die Söhne Hatiphas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Die Söhne der Knechte Salomos: die Söhne Sotais, die Söhne Sophereths, die Söhne Perudas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'die Söhne Jaalas, die Söhne Darkons, die Söhne Giddels,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'die Söhne Schephatjas, die Söhne Hattils, die Söhne Pokereths-Hazzebaim, die Söhne Amis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Alle Nethinim und Söhne der Knechte Salomos: dreihundertzweiundneunzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Und diese sind es, die aus Tel-Melach, Tel-Harscha, Kerub, Addan, Immer hinaufzogen; aber sie konnten ihr Vaterhaus und ihre Abkunft nicht angeben, ob sie aus Israel wären:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'die Söhne Delajas, die Söhne Tobijas, die Söhne Nekodas, sechshundertzweiundfünfzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Und von den Söhnen der Priester: die Söhne Habajas, die Söhne Hakkoz\', die Söhne Barsillais, der ein Weib von den Töchtern Barsillais, des Gileaditers, genommen hatte und nach ihrem Namen genannt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Diese suchten ihr Geschlechtsregisterverzeichnis, aber es wurde nicht gefunden; und sie wurden von dem Priestertum als unrein ausgeschlossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Und der Tirsatha sprach zu ihnen, daß sie von dem Hochheiligen nicht essen dürften, bis ein Priester für die Urim und die Thummim aufstände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Die ganze Versammlung insgesamt war zweiundvierzigtausend dreihundertsechzig,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'außer ihren Knechten und ihren Mägden; dieser waren siebentausend dreihundertsiebenunddreißig. Und sie hatten noch zweihundert Sänger und Sängerinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Ihrer Rosse waren siebenhundertsechsunddreißig, ihrer Maultiere zweihundertfünfundvierzig,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'ihrer Kamele vierhundertfünfunddreißig, der Esel sechstausend siebenhundertzwanzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Und als sie zum Hause Jehovas in Jerusalem kamen, gaben einige von den Häuptern der Väter freiwillig für das Haus Gottes, um es an seiner Stätte aufzurichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Nach ihrem Vermögen gaben sie für den Schatz des Werkes: an Gold einundsechzigtausend Dariken und an Silber fünftausend Minen, und hundert Priesterleibröcke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Und die Priester und die Leviten und die aus dem Volke und die Sänger und die Torhüter und die Nethinim wohnten in ihren Städten; und ganz Israel wohnte in seinen Städten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Und als der siebte Monat herankam, und die Kinder Israel in den Städten waren, da versammelte sich das Volk wie ein Mann nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Und Jeschua, der Sohn Jozadaks, und seine Brüder, die Priester, und Serubbabel, der Sohn Schealtiels, und seine Brüder machten sich auf und bauten den Altar des Gottes Israels, um Brandopfer darauf zu opfern, wie geschrieben steht in dem Gesetz Moses, des Mannes Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Und sie richteten den Altar auf an seiner Stätte, denn ein Schrecken war auf ihnen vor den Völkern der Länder; und sie opferten auf ihm Brandopfer dem Jehova, die Morgen-und Abendbrandopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Und sie feierten das Laubhüttenfest, wie es vorgeschrieben ist; und sie opferten Brandopfer Tag für Tag, nach der Zahl, nach der Vorschrift, das Tägliche an seinem Tage;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'und danach das beständige Brandopfer und diejenigen der Neumonde und aller geheiligten Feste Jehovas, und die Brandopfer eines jeden, der Jehova eine freiwillige Gabe brachte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Am ersten Tage des siebten Monats fingen sie an, Jehova Brandopfer zu opfern; aber der Grund des Tempels Jehovas war noch nicht gelegt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Und sie gaben den Steinhauern und den Zimmerleuten Geld, und Speise und Trank und Öl den Zidoniern und den Tyrern, damit sie Zedernholz vom Libanon nach dem Meere von Japho brächten, gemäß der Vollmacht Kores\', des Königs von Persien, an sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Und im zweiten Jahre ihres Kommens zum Hause Gottes in Jerusalem, im zweiten Monat, begannen Serubbabel, der Sohn Schealtiels, und Jeschua, der Sohn Jozadaks, und ihre übrigen Brüder, die Priester und die Leviten, und alle, die aus der Gefangenschaft nach Jerusalem gekommen waren, und sie bestellten die Leviten von zwanzig Jahren an und darüber, um Aufsicht zu führen über das Werk des Hauses Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Und Jeschua, seine Söhne und seine Brüder, Kadmiel und seine Söhne, die Söhne Judas, standen wie ein Mann, um Aufsicht zu führen über die, welche das Werk am Hause Gottes taten; auch die Söhne Henadads, ihre Söhne und ihre Brüder, die Leviten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Und als die Bauleute den Grund zum Tempel Jehovas legten, ließ man die Priester in ihrer Kleidung hintreten, mit Trompeten, und die Leviten, die Söhne Asaphs, mit Zimbeln, um Jehova zu loben nach der Anweisung Davids, des Königs von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Und sie hoben einen Wechselgesang an mit Lob und Dank dem Jehova: denn er ist gütig, denn seine Güte währt ewiglich über Israel. Und das ganze Volk erhob ein großes Jubelgeschrei beim Lobe Jehovas, weil der Grund zum Hause Jehovas gelegt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Viele aber von den Priestern und den Leviten und den Häuptern der Väter, den Alten, welche das erste Haus gesehen hatten, weinten mit lauter Stimme, als vor ihren Augen der Grund zu diesem Hause gelegt wurde; viele aber erhoben ihre Stimme mit freudigem Jauchzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Und das Volk konnte den Schall des freudigen Jauchzens nicht unterscheiden von der Stimme des Weinens im Volke; denn das Volk erhob ein großes Jubelgeschrei, und der Schall wurde gehört bis in die Ferne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Und die Feinde Judas und Benjamins hörten, daß die Kinder der Wegführung Jehova, dem Gott Israels, einen Tempel bauten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'und sie traten zu Serubbabel und zu den Häuptern der Väter und sprachen zu ihnen: Wir wollen mit euch bauen; denn wir suchen euren Gott wie ihr; und ihm opfern wir seit den Tagen Esar-Haddons, des Königs von Assyrien, der uns hierher heraufgeführt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Aber Serubbabel und Jeschua und die übrigen Häupter der Väter Israels sprachen zu ihnen: Es geziemt euch nicht, mit uns unserem Gott ein Haus zu bauen; sondern wir allein wollen Jehova, dem Gott Israels, bauen, wie der König Kores, der König von Persien, uns geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Da suchte das Volk des Landes die Hände des Volkes Juda schlaff zu machen und sie vom Bauen abzuschrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Und sie dingten Ratgeber wider sie, um ihren Plan zu vereiteln, alle die Tage Kores\', des Königs von Persien, und bis zur Regierung Darius\', des Königs von Persien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Und unter der Regierung des Ahasveros, im Anfange seiner Regierung, schrieben sie eine Anklage wider die Bewohner von Juda und Jerusalem. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Und in den Tagen Artasastas schrieben Bischlam, Mithredath, Tabeel und seine übrigen Genossen an Artasasta, den König von Persien. Die Schrift des Briefes war aber aramäisch geschrieben und ins Aramäische übersetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rechum, der Statthalter, und Schimschai, der Schreiber, schrieben an Artasasta, den König, einen Brief wider Jerusalem also: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'damals schrieben nämlich Rechum, der Statthalter, und Schimschai, der Schreiber, und ihre übrigen Genossen, Diniter und Apharsathkiter, Tarpeliter, Apharsiter, Arkewiter, Babylonier, Susaniter, Dehiter und Elamiter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'und die übrigen Völker, welche der große und erlauchte Osnappar wegführte und in den Städten Samarias und in dem übrigen Gebiete jenseit des Stromes wohnen ließ, und so weiter: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'dies ist die Abschrift des Briefes, den sie an ihn, an den König Artasasta, sandten: Deine Knechte, die Männer diesseit des Stromes, und so weiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Es sei dem König kundgetan, daß die Juden, die von dir heraufgezogen, zu uns nach Jerusalem gekommen sind; sie bauen die aufrührerische und böse Stadt wieder auf, und vollenden die Mauern und bessern die Grundlagen aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'So sei nun dem König kundgetan, daß, wenn diese Stadt wieder aufgebaut wird, und die Mauern vollendet werden, sie Steuer, Zoll und Weggeld nicht mehr geben werden, und solches schließlich die Könige benachteiligen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Weil wir nun das Salz des Palastes essen und es uns nicht geziemt, den Schaden des Königs anzusehen, deswegen senden wir und tun es dem König kund,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'damit man in dem Buche der Denkwürdigkeiten deiner Väter nachsuche; und du wirst in dem Buche der Denkwürdigkeiten finden, und wirst erkennen, daß diese Stadt eine aufrührerische Stadt gewesen ist, und nachteilig den Königen und Ländern, und daß man von den Tagen der Vorzeit her Empörung darin gestiftet hat, weswegen diese Stadt zerstört worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Wir tun dem König kund, daß, wenn diese Stadt wieder aufgebaut wird, und die Mauern vollendet werden, du deshalb diesseit des Stromes kein Teil mehr haben wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Der König sandte eine Antwort an Rechum, den Statthalter, und Schimschai, den Schreiber, und an ihre übrigen Genossen, welche in Samaria und in dem übrigen Gebiete jenseit des Stromes wohnten: Frieden, und so weiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Der Brief, den ihr an uns gesandt habt, ist deutlich vor mir gelesen worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Und von mir ist Befehl gegeben worden, und man hat nachgesucht und gefunden, daß diese Stadt von den Tagen der Vorzeit her sich wider die Könige aufgelehnt hat, und daß Aufruhr und Empörung in ihr gestiftet worden sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Und mächtige Könige sind über Jerusalem gewesen, die über alles geherrscht haben, was jenseit des Stromes ist; und Steuer, Zoll und Weggeld wurde ihnen gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'So gebet nun Befehl, diesen Männern zu wehren, damit diese Stadt nicht wieder aufgebaut werde, bis von mir Befehl gegeben wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Und hütet euch, hierin einen Fehler zu begehen; warum sollte der Schaden wachsen, um den Königen Nachteil zu bringen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Hierauf, sobald die Abschrift des Briefes des Königs Artasasta vor Rechum und Schimschai, dem Schreiber, und ihren Genossen gelesen war, gingen sie eilends nach Jerusalem zu den Juden, und wehrten ihnen mit Gewalt und Macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Damals hörte die Arbeit am Hause Gottes in Jerusalem auf, und sie unterblieb bis zum zweiten Jahre der Regierung des Königs Darius von Persien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Und Haggai, der Prophet, und Sacharja, der Sohn Iddos, die Propheten, weissagten den Juden, die in Juda und in Jerusalem waren; im Namen des Gottes Israels weissagten sie ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Da machten sich Serubbabel, der Sohn Schealtiels, und Jeschua, der Sohn Jozadaks, auf und fingen an, das Haus Gottes in Jerusalem zu bauen, und mit ihnen die Propheten Gottes, welche sie unterstützten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'In jener Zeit kamen Tatnai, der Landpfleger diesseit des Stromes, und Schethar-Bosnai und ihre Genossen zu ihnen und sprachen zu ihnen also: Wer hat euch Befehl gegeben, dieses Haus zu bauen und diese Mauer zu vollenden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Darauf sagten wir ihnen, welches die Namen der Männer wären, die diesen Bau ausführten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Aber das Auge ihres Gottes war über den Ältesten der Juden, daß sie ihnen nicht wehrten, bis die Sache an Darius gelangte und man dann einen Brief darüber zurückschickte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Abschrift des Briefes, den Tatnai, der Landpfleger jenseit des Stromes, und Schethar-Bosnai und seine Genossen, die Apharsakiter, die jenseit des Stromes wohnten, an den König Darius sandten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Sie sandten einen Bericht an ihn, und also war darin geschrieben: Darius, dem König, allen Frieden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Es sei dem König kundgetan, daß wir in die Landschaft Juda zu dem Hause des großen Gottes gegangen sind; und es wird mit Quadersteinen erbaut, und Balken werden in die Wände gelegt, und diese Arbeit wird eifrig betrieben, und sie gedeiht unter ihrer Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Da haben wir jene Ältesten gefragt und also zu ihnen gesprochen: Wer hat euch Befehl gegeben, dieses Haus zu bauen und diese Mauer zu vollenden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Und auch nach ihren Namen haben wir sie gefragt, um sie dir kundzutun, damit wir die Namen der Männer aufschrieben, die ihre Häupter sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Und also gaben sie uns Antwort und sprachen: Wir sind die Knechte des Gottes des Himmels und der Erde, und wir bauen das Haus wieder auf, das viele Jahre zuvor gebaut wurde; und ein großer König von Israel hatte es gebaut und vollendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Aber seitdem unsere Väter den Gott des Himmels gereizt haben, hat er sie in die Hand Nebukadnezars, des Königs von Babel, des Chaldäers, gegeben, und er hat dieses Haus zerstört und das Volk nach Babel weggeführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Doch im ersten Jahre Kores\', des Königs von Babel, hat der König Kores Befehl gegeben, dieses Haus Gottes wieder aufzubauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Und auch die goldenen und silbernen Geräte des Hauses Gottes, welche Nebukadnezar aus dem Tempel, der zu Jerusalem war, herausgenommen und in den Tempel zu Babel gebracht hatte, die hat der König Kores aus dem Tempel zu Babel herausgenommen und sie einem gegeben, dessen Name Sesbazar war, den er zum Landpfleger einsetzte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Und er sprach zu ihm: Nimm diese Geräte, ziehe hin, lege sie nieder in dem Tempel, der zu Jerusalem ist; und das Haus Gottes werde wieder aufgebaut an seiner früheren Stätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Da kam dieser Sesbazar und legte den Grund des Hauses Gottes, das in Jerusalem ist; und von da an bis jetzt wird daran gebaut, es ist aber noch nicht vollendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Und nun, wenn es den König gutdünkt, so werde nachgesucht in dem Schatzhause des Königs, welches dort zu Babel ist, ob es so sei, daß vom König Kores Befehl gegeben worden ist, dieses Haus Gottes in Jerusalem zu bauen; und der König sende uns seinen Willen hierüber zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Da gab der König Darius Befehl, und man suchte nach in dem Urkundenhause, worin man die Schätze niederlegte zu Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Und es wurde zu Achmetha, in der Burg, die in der Landschaft Medien liegt, eine Rolle gefunden; und darin war eine Denkschrift also geschrieben:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Im ersten Jahre des Königs Kores gab der König Kores Befehl: Das Haus Gottes in Jerusalem anlangend: Dieses Haus soll wieder aufgebaut werden als eine Stätte, wo man Schlachtopfer opfert. Und seine Grundlagen sollen aufgerichtet werden: seine Höhe sechzig Ellen, seine Breite sechzig Ellen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'drei Lagen von Quadersteinen und eine Lage von neuen Balken. Und die Kosten sollen aus dem Hause des Königs bestritten werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Und auch die goldenen und silbernen Geräte des Hauses Gottes, welche Nebukadnezar aus dem Tempel, der zu Jerusalem war, herausgenommen und nach Babel gebracht hat, soll man zurückgeben, daß ein jedes wieder in den Tempel zu Jerusalem komme, an seinen Ort; und du sollst sie in dem Hause Gottes niederlegen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Nun denn, Tatnai, Landpfleger jenseit des Stromes, Schethar-Bosnai und eure Genossen, die Apharsakiter, die ihr jenseit des Stromes seid, entfernet euch von dannen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Laßt die Arbeit geschehen an diesem Hause Gottes; der Landpfleger der Juden und die Ältesten der Juden mögen dieses Haus Gottes an seiner früheren Stätte wieder aufbauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Und von mir wird Befehl gegeben wegen dessen, was ihr diesen Ältesten der Juden für den Bau dieses Hauses Gottes tun sollt; nämlich, von den Gütern des Königs, aus der Steuer jenseit des Stromes, sollen diesen Männern die Kosten pünktlich gegeben werden, damit sie nicht gehindert seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Und was nötig ist, sowohl junge Stiere, als auch Widder und Lämmer zu Brandopfern für den Gott des Himmels, Weizen, Salz, Wein und Öl, soll ihnen nach dem Geheiß der Priester, die in Jerusalem sind, Tag für Tag unfehlbar gegeben werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'damit sie dem Gott des Himmels Opfer lieblichen Geruchs darbringen und für das Leben des Königs und seiner Söhne beten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Und von mir wird Befehl gegeben: Welcher Mensch diesen Erlaß abändern wird, von dessen Hause soll ein Balken ausgerissen und er, aufgehängt, daran geschlagen werden; und sein Haus soll dieserhalb zu einer Kotstätte gemacht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Der Gott aber, der seinen Namen daselbst wohnen läßt, stürze jeden König und jedes Volk nieder, die ihre Hand ausstrecken werden, diesen Erlaß abzuändern, um dieses Haus Gottes zu zerstören, das in Jerusalem ist! Ich, Darius, habe den Befehl gegeben; pünktlich soll er vollzogen werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Da taten Tatnai, der Landpfleger jenseit des Stromes, Schethar-Bosnai und ihre Genossen, wegen dessen was der König Darius entboten hatte, pünktlich also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Und die Ältesten der Juden bauten; und es gelang ihnen durch die Weissagung Haggais, des Propheten, und Sacharjas, des Sohnes Iddos; und sie bauten und vollendeten nach dem Befehle des Gottes Israels, und nach dem Befehl Kores\' und Darius\' und Artasastas, des Königs von Persien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Und dieses Haus wurde beendet bis zum dritten Tage des Monats Adar, das ist das sechste Jahr der Regierung des Königs Darius.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Und die Kinder Israel, die Priester und die Leviten und die übrigen Kinder der Wegführung, feierten die Einweihung dieses Hauses Gottes mit Freuden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Und sie brachten dar zur Einweihung dieses Hauses Gottes hundert Stiere, zweihundert Widder, vierhundert Lämmer; und zum Sündopfer für ganz Israel zwölf Ziegenböcke, nach der Zahl der Stämme Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Und sie stellten die Priester in ihre Klassen und die Leviten in ihre Abteilungen zum Dienste Gottes in Jerusalem, nach der Vorschrift des Buches Moses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Und die Kinder der Wegführung feierten das Passah am vierzehnten Tage des ersten Monats.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Denn die Priester und die Leviten hatten sich gereinigt wie ein Mann; sie waren alle rein. Und sie schlachteten das Passah für alle Kinder der Wegführung und für ihre Brüder, die Priester, und für sich selbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Und die Kinder Israel, welche aus der Wegführung zurückgekehrt waren, und ein jeder, der sich von der Unreinigkeit der Nationen des Landes zu ihnen abgesondert hatte, um Jehova, den Gott Israels, zu suchen, aßen das Passah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Und sie feierten das Fest der ungesäuerten Brote sieben Tage mit Freuden; denn Jehova hatte ihnen Freude gegeben und ihnen das Herz des Königs von Assyrien zugewandt, so daß er ihre Hände stärkte in dem Werke des Hauses Gottes, des Gottes Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Und nach diesen Begebenheiten, unter der Regierung Artasastas, des Königs von Persien, zog Esra, der Sohn Serajas, des Sohnes Asarjas, des Sohnes Hilkijas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'des Sohnes Schallums, des Sohnes Zadoks, des Sohnes Ahitubs,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'des Sohnes Amarjas, des Sohnes Asarjas, des Sohnes Merajoths,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'des Sohnes Serachjas, des Sohnes Ussis, des Sohnes Bukkis,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'des Sohnes Abischuas, des Sohnes Pinehas\', des Sohnes Eleasars, des Sohnes Aarons, des Hauptpriesters-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'dieser Esra zog herauf von Babel; und er war ein kundiger Schriftgelehrter in dem Gesetz Moses, welches Jehova, der Gott Israels, gegeben hatte. Und weil die Hand Jehovas, seines Gottes, über ihm war, gab ihm der König all sein Begehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Und es zog mit ihm eine Anzahl von den Kindern Israel und von den Priestern und den Leviten und den Sängern und den Torhütern und den Nethinim nach Jerusalem hinauf, im siebten Jahre des Königs Artasasta.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Und er kam nach Jerusalem im fünften Monat, das war das siebte Jahr des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Denn am Ersten des ersten Monats hatte er den Hinaufzug aus Babel festgesetzt; und am Ersten des fünften Monats kam er nach Jerusalem, weil die gute Hand seines Gottes über ihm war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Denn Esra hatte sein Herz darauf gerichtet, das Gesetz Jehovas zu erforschen und zu tun, und in Israel Satzung und Recht zu lehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Und dies ist die Abschrift des Briefes, welchen der König Artasasta dem Priester Esra, dem Schriftgelehrten, gab, dem Schriftgelehrten in den Worten der Gebote Jehovas und seinen Satzungen für Israel:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artasasta, König der Könige, Esra, dem Priester, dem vollkommenen Schriftgelehrten im Gesetz des Gottes des Himmels, und so weiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Von mir wird Befehl gegeben, daß ein jeder in meinem Reiche, von dem Volke Israel und seinen Priestern und den Leviten, der bereitwillig ist, nach Jerusalem zu ziehen, mit dir ziehen mag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Weil du von dem König und seinen sieben Räten gesandt wirst, um eine Untersuchung über Juda und Jerusalem anzustellen, nach dem Gesetz deines Gottes, das in deiner Hand ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'und das Silber und das Gold hinzubringen, das der König und seine Räte dem Gott Israels, dessen Wohnung in Jerusalem ist, freiwillig gegeben haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'sowie alles Silber und Gold, das du in der ganzen Landschaft Babel bekommen wirst, nebst der freiwilligen Gabe des Volkes und der Priester, die freiwillig geben für das Haus ihres Gottes, das in Jerusalem ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'deshalb kaufe mit Fleiß für dieses Geld Stiere, Widder, Lämmer, und ihre Speisopfer und ihre Trankopfer, und bringe sie dar auf dem Altar des Hauses eures Gottes, das in Jerusalem ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Und was dich und deine Brüder gutdünkt, mit dem übrigen Silber und Gold zu tun, das möget ihr nach dem Willen eures Gottes tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Und die Geräte, die dir zum Dienste des Hauses deines Gottes gegeben worden sind, liefere ab vor dem Gott Jerusalems.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Und den übrigen Bedarf des Hauses deines Gottes, was dir auszugeben vorfallen wird, sollst du aus dem Schatzhause des Königs ausgeben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Und von mir, dem König Artasasta, wird an alle Schatzmeister jenseit des Stromes Befehl gegeben, daß alles, was Esra, der Priester, der Schriftgelehrte im Gesetz des Gottes des Himmels, von euch fordern wird, pünktlich getan werde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'bis zu hundert Talenten Silber und bis zu hundert Kor Weizen und bis zu hundert Bath Wein und bis zu hundert Bath Öl, und Salz ohne Maß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Alles, was nach dem Befehl des Gottes des Himmels ist, soll für das Haus des Gottes des Himmels sorgfältig getan werden; denn warum sollte ein Zorn kommen über das Reich des Königs und seiner Söhne?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Und euch wird kundgetan, daß niemand ermächtigt ist, allen Priestern und Leviten, Sängern, Torhütern, Nethinim und Dienern dieses Hauses Gottes Steuer, Zoll und Weggeld aufzuerlegen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Du aber, Esra, bestelle nach der Weisheit deines Gottes, die bei dir ist, Richter und Rechtspfleger, welche alles Volk richten sollen, das jenseit des Stromes ist, alle, welche die Gesetze deines Gottes kennen; und dem, der sie nicht kennt, sollt ihr sie kundtun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Und ein jeder, der das Gesetz deines Gottes und das Gesetz des Königs nicht tun wird, an dem soll mit Eifer Gericht geübt werden, sei es zum Tode, oder zur Verbannung, oder zur Buße an Gütern, oder zum Gefängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Gepriesen sei Jehova, der Gott unserer Väter, der solches in das Herz des Königs gegeben hat, um das Haus Jehovas zu verherrlichen, das in Jerusalem ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'und der mir Güte zugewandt hat vor dem König und seinen Räten und allen mächtigen Fürsten des Königs! Und ich erstarkte, weil die Hand Jehovas, meines Gottes, über mir war, und ich versammelte Häupter aus Israel, daß sie mit mir hinaufzögen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Und dies sind die Häupter ihrer Väter und ihr Geschlechtsverzeichnis, nämlich derer, die unter der Regierung des Königs Artasasta mit mir aus Babel heraufzogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Von den Söhnen Pinehas\': Gersom; von den Söhnen Ithamars: Daniel; von den Söhnen Davids: Hattusch;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'von den Söhnen Schekanjas, von den Söhnen Parhosch\': Sekarja, und mit ihm waren verzeichnet an Männlichen hundertfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'von den Söhnen Pachath-Moabs: Eljoenai, der Sohn Serachjas, und mit ihm zweihundert Männliche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'von den Söhnen Schekanjas: der Sohn Jachasiels, und mit ihm dreihundert Männliche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'und von den Söhnen Adins: Ebed, der Sohn Jonathans, und mit ihm fünfzig Männliche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'und von den Söhnen Elams: Jesaja, der Sohn Athaljas, und mit ihm siebzig Männliche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'und von den Söhnen Schephatjas: Sebadja, der Sohn Michaels, und mit ihm achtzig Männliche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'und von den Söhnen Joabs: Obadja, der Sohn Jechiels, und mit ihm zweihundertachtzehn Männliche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'und von den Söhnen Schelomiths: der Sohn Josiphjas, und mit ihm hundertsechzig Männliche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'und von den Söhnen Bebais: Sekarja, der Sohn Bebais, und mit ihm achtundzwanzig Männliche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'und von den Söhnen Asgads: Jochanan, der Sohn Hakkatans, und mit ihm hundertzehn Männliche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'und von den Söhnen Adonikams: die letzten, und dies sind ihre Namen: Elipheleth, Jeghiel und Schemaja, und mit ihnen sechzig Männliche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'und von den Söhnen Bigwais: Uthai und Sabbud, und mit ihnen siebzig Männliche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Und ich versammelte sie an den Fluß, der nach Ahawa fließt; und wir lagerten daselbst drei Tage. Und ich sah mich um unter dem Volke und unter den Priestern, und ich fand keinen von den Söhnen Levis daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Da sandte ich nach Elieser, Ariel, Schemaja und Elnathan und Jarib und Elnathan und Nathan und Sekarja und Meschullam, den Häuptern, und Jojarib und Elnathan, den einsichtigen Männern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'und entbot sie an Iddo, das Haupt in der Ortschaft Kasiphja, und ich legte ihnen Worte in den Mund, um sie zu Iddo zu reden und zu seinen Brüdern, den Nethinim, in der Ortschaft Kasiphja, daß sie uns Diener für das Haus unseres Gottes brächten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Und sie brachten uns, weil die gute Hand unseres Gottes über uns war, einen einsichtsvollen Mann von den Söhnen Machlis, des Sohnes Levis, des Sohnes Israels; und Scherebja und seine Söhne und seine Brüder, achtzehn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'und Haschabja und mit ihm Jesaja, von den Söhnen Meraris, seine Brüder und ihre Söhne, zwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'und von den Nethinim, welche David und die Fürsten zur Bedienung der Leviten gegeben hatten: zweihundertzwanzig Nethinim; sie alle waren mit Namen angegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Und ich rief daselbst, am Flusse Ahawa, ein Fasten aus, um uns vor unserem Gott zu demütigen, um von ihm einen geebneten Weg zu erbitten für uns und für unsere Kinder und für alle unsere Habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Denn ich schämte mich, von dem König eine Heeresmacht und Reiter zu fordern, um uns gegen den Feind auf dem Wege beizustehen; denn wir hatten zu dem König gesprochen und gesagt: Die Hand unseres Gottes ist über allen, die ihn suchen, zum Guten; aber seine Macht und sein Zorn sind gegen alle, die ihn verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Und so fasteten wir und erbaten dieses von unserem Gott; und er ließ sich von uns erbitten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Und ich sonderte von den Obersten der Priester zwölf aus: Scherebja, Haschabja, und mit ihnen zehn von ihren Brüdern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'und ich wog ihnen das Silber und das Gold und die Geräte dar, das Hebopfer für das Haus unseres Gottes, welches der König und seine Räte und seine Fürsten und ganz Israel, das vorhanden war, geschenkt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Und ich wog in ihre Hand dar: sechshundertundfünfzig Talente Silber; und an silbernen Geräten: hundert Talente; an Gold: hundert Talente;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'und zwanzig goldene Becher zu tausend Dariken; und zwei Geräte von goldglänzendem, feinem Erze, kostbar wie Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Und ich sprach zu ihnen: Ihr seid Jehova heilig, und die Geräte sind heilig; und das Silber und das Gold ist eine freiwillige Gabe für Jehova, den Gott eurer Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Seid wachsam und bewahret es, bis ihr es darwäget vor den Obersten der Priester und der Leviten und den Obersten der Väter Israels zu Jerusalem, in die Zellen des Hauses Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Und die Priester und die Leviten nahmen das dargewogene Silber und Gold und die Geräte in Empfang, um sie nach Jerusalem in das Haus unseres Gottes zu bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Und wir brachen auf von dem Flusse Ahawa am Zwölften des ersten Monats, um nach Jerusalem zu ziehen; und die Hand unseres Gottes war über uns, und er errettete uns von der Hand des Feindes und des am Wege Lauernden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Und wir kamen nach Jerusalem und blieben daselbst drei Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Und am vierten Tage wurden das Silber und das Gold und die Geräte im Hause unseres Gottes dargewogen in die Hand Meremoths, des Sohnes Urijas, des Priesters, und mit ihm war Eleasar, der Sohn Pinehas\', und mit ihnen Josabad, der Sohn Jeschuas, und Noadja, der Sohn Binnuis, die Leviten-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'nach der Zahl, nach dem Gewicht von allem; und das ganze Gewicht wurde zu selbiger Zeit aufgeschrieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Die aus der Gefangenschaft Gekommenen, die Kinder der Wegführung, brachten dem Gott Israels Brandopfer dar: zwölf Farren für ganz Israel, sechsundneunzig Widder, siebenundsiebzig Schafe, und zwölf Böcke zum Sündopfer, das Ganze als Brandopfer dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Und sie übergaben die Befehle des Königs den Satrapen des Königs und den Landpflegern diesseit des Stromes; und diese unterstützten das Volk und das Haus Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Und als dieses ausgerichtet war, traten die Obersten zu mir und sprachen: Das Volk Israel und die Priester und die Leviten haben sich nicht von den Völkern der Länder, nach deren Greueln, abgesondert, nämlich der Kanaaniter, der Hethiter, der Perisiter, der Jebusiter, der Ammoniter, der Moabiter, der Ägypter und der Amoriter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'denn sie haben von ihren Töchtern für sich und für ihre Söhne genommen, und so hat sich der heilige Same mit den Völkern der Länder vermischt; und die Hand der Obersten und der Vorsteher ist in dieser Treulosigkeit die erste gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Und als ich diese Sache hörte, zerriß ich mein Kleid und mein Obergewand, und raufte mir Haare meines Hauptes und meines Bartes aus, und saß betäubt da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Und zu mir versammelten sich alle, die da zitterten vor den Worten des Gottes Israels wegen der Treulosigkeit der Weggeführten; und ich saß betäubt da bis zum Abendopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Und beim Abendopfer stand ich auf von meiner Demütigung, indem ich mein Kleid und mein Obergewand zerrissen hatte, und ich beugte mich auf meine Knie nieder und breitete meine Hände aus zu Jehova, meinem Gott,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'und ich sprach: Mein Gott, ich schäme mich und scheue mich, mein Angesicht zu dir, mein Gott, zu erheben! Denn unsere Missetaten sind uns über das Haupt gewachsen, und unsere Schuld ist groß geworden bis an den Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Von den Tagen unserer Väter an sind wir in großer Schuld gewesen bis auf diesen Tag; und um unserer Missetaten willen sind wir, wir, unsere Könige, unsere Priester, der Hand der Könige der Länder übergeben worden, dem Schwerte, der Gefangenschaft und dem Raube und der Beschämung des Angesichts, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Und nun ist uns für einen kleinen Augenblick Gnade von seiten Jehovas, unseres Gottes, zuteil geworden, indem er uns Entronnene übriggelassen und uns einen Pflock gegeben hat an seiner heiligen Stätte, damit unser Gott unsere Augen erleuchte und uns ein wenig aufleben lasse in unserer Knechtschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Denn Knechte sind wir; aber in unserer Knechtschaft hat unser Gott uns nicht verlassen; und er hat uns Güte zugewandt vor den Königen von Persien, so daß sie uns ein Aufleben verliehen, um das Haus unseres Gottes aufzubauen und seine Trümmer aufzurichten, und uns eine Mauer zu geben in Juda und in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Und nun, unser Gott, was sollen wir nach diesem sagen? Denn wir haben deine Gebote verlassen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'die du uns durch deine Knechte, die Propheten, geboten hast, indem du sprachst: Das Land, wohin ihr kommet, um es in Besitz zu nehmen, ist ein unreines Land, wegen der Unreinigkeit der Völker der Länder, wegen ihrer Greuel, mit denen sie es angefüllt haben von einem Ende bis zum anderen durch ihre Verunreinigung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'So sollt ihr nun nicht eure Töchter ihren Söhnen geben, und ihre Töchter nicht für eure Söhne nehmen; und ihr sollt ihren Frieden und ihr Wohl nicht suchen ewiglich: damit ihr stark seiet und das Gut des Landes esset und es auf eure Söhne vererbet ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Und nach allem, was wegen unserer bösen Taten und wegen unserer großen Schuld über uns gekommen ist, wiewohl du, unser Gott, mehr geschont hast, als unsere Missetaten es verdienten, und du uns Entronnene gegeben hast, wie diese hier-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'sollten wir wiederum deine Gebote brechen und uns mit diesen Greuelvölkern verschwägern? Wirst du nicht wider uns erzürnen bis zur Vertilgung, daß kein Überrest und keine Entronnenen mehr bleiben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Jehova, Gott Israels, du bist gerecht; denn wir sind als Entronnene übriggeblieben, wie es an diesem Tage ist. Siehe, wir sind vor dir in unserer Schuld; denn dieserhalb kann man nicht vor dir bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Und als Esra betete, und als er bekannte, weinend und vor dem Hause Gottes hingestreckt, versammelte sich zu ihm aus Israel eine sehr große Versammlung von Männern und Weibern und Kindern; denn das Volk weinte mit vielem Weinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Und Schekanja, der Sohn Jechiels, von den Söhnen Elams, hob an und sprach zu Esra: Wir haben treulos gehandelt gegen unseren Gott und haben fremde Weiber aus den Völkern des Landes heimgeführt; nun aber ist noch Hoffnung für Israel betreffs dieser Sache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'So laßt uns jetzt einen Bund machen mit unserem Gott, daß wir alle Weiber und die von ihnen geboren sind hinaustun, nach dem Rate meines Herrn und derer, die da zittern vor dem Gebote unseres Gottes; und es soll nach dem Gesetz gehandelt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Stehe auf, denn dir liegt die Sache ob; und wir werden mit dir sein. Sei stark und handle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Da stand Esra auf, und er ließ die Obersten der Priester, der Leviten und des ganzen Israel schwören, nach diesem Worte zu tun. Und sie schwuren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Und Esra stand auf vor dem Hause Gottes und ging in die Zelle Jochanans, des Sohnes Eljaschibs; und er ging dahin, er aß kein Brot und trank kein Wasser, denn er trauerte über die Treulosigkeit der Weggeführten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Und sie ließen durch Juda und Jerusalem einen Ruf ergehen an alle Kinder der Wegführung, daß sie sich nach Jerusalem versammeln sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Und wer irgend binnen drei Tagen nicht käme, nach dem Rate der Obersten und Ältesten, dessen ganze Habe sollte verbannt, und er selbst aus der Versammlung der Weggeführten ausgeschlossen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Da versammelten sich alle Männer von Juda und Benjamin binnen drei Tagen nach Jerusalem... das war der neunte Monat, am Zwanzigsten des Monats. Und das ganze Volk saß auf dem Platze des Hauses Gottes, zitternd um der Sache willen und infolge der Regengüsse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Da stand Esra, der Priester, auf und sprach zu ihnen: Ihr habt treulos gehandelt und habt fremde Weiber heimgeführt, um die Schuld Israels zu mehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'So leget nun Bekenntnis ab vor Jehova, dem Gott eurer Väter; und tut sein Wohlgefallen und sondert euch ab von den Völkern des Landes und von den fremden Weibern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Und die ganze Versammlung antwortete und sprach mit lauter Stimme: Nach deinen Worten, also liegt es uns ob zu tun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Aber das Volk ist zahlreich; und es ist die Regenzeit, so daß man nicht draußen zu stehen vermag; auch ist es nicht ein Geschäft von einem Tage oder von zweien, denn viele unter uns haben in dieser Sache übertreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Laß doch unsere Obersten für die ganze Versammlung dastehen; und alle, die in unseren Städten sind, welche fremde Weiber heimgeführt haben, mögen zu bestimmten Zeiten kommen, und mit ihnen die Ältesten jeder Stadt und ihre Richter, so lange diese Sache währt, bis die Glut des Zornes unseres Gottes von uns abgewendet werde. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Nur Jonathan, der Sohn Asaels, und Jachseja, der Sohn Tikwas, traten dagegen auf; und Meschullam und Schabbethai, der Levit, standen ihnen bei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Und die Kinder der Wegführung taten also. Und es wurden ausgesondert Esra, der Priester, und Männer, Häupter der Väter nach ihren Vaterhäusern, und zwar alle mit Namen; und sie setzten sich nieder am ersten Tage des zehnten Monats, um die Sache zu untersuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Und sie kamen bis zum ersten Tage des ersten Monats mit allem zu Ende, hinsichtlich der Männer, die fremde Weiber heimgeführt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Und es fanden sich unter den Söhnen der Priester, welche fremde Weiber heimgeführt hatten, folgende: von den Söhnen Jeschuas, des Sohnes Jozadaks, und seinen Brüdern: Maaseja und Elieser und Jarib und Gedalja.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Und sie gaben ihre Hand darauf, daß sie ihre Weiber hinaustun und einen Widder vom Kleinvieh für ihre Schuld entrichten wollten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Und von den Söhnen Immers: Hanani und Sebadja;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'und von den Söhnen Harims: Maaseja und Elija und Schemaja und Jechiel und Ussija;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'und von den Söhnen Paschchurs: Eljoenai, Maaseja, Ismael, Nethaneel, Josabad und Elasa. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Und von den Leviten: Josabad und Simei und Kelaja (das ist Kelita), Pethachja, Juda und Elieser. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Und von den Sängern: Eljaschib. Und von den Torhütern: Schallum und Telem und Uri. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Und von Israel: von den Söhnen Parhosch\': Ramja und Jissija und Malkija und Mijamin und Eleasar und Malkija und Benaja:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'und von den Söhnen Elams: Mattanja, Sekarja und Jechiel und Abdi und Jeremoth und Elija;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'und von den Söhnen Sattus: Eljoenai, Eljaschib, Mattanja und Jeremoth und Sabad und Asisa;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'und von den Söhnen Bebais: Jochanan, Hananja, Sabbai, Athlai;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'und von den Söhnen Banis: Meschullam, Malluk und Adaja, Jaschub und Scheal, Jeremoth;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'und von den Söhnen Pachath-Moabs: Adna und Kelal, Benaja, Maaseja, Mattanja, Bezaleel und Binnui und Manasse;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'und von den Söhnen Harims: Elieser, Jischija, Malkija, Schemaja, Simeon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Malluk, Schemarja;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'von den Söhnen Haschums: Mattenai; Mattatta, Sabad, Elipheleth, Jeremai, Manasse, Simei;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'von den Söhnen Banis: Maadai, Amram und Ül,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Bedja, Keluhi,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Wanja, Meremoth, Eljaschib,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattanja, Mattenai und Jaasai,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'und Bani und Binnui, Simei,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'und Schelemja und Nathan und Adaja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Maknadbai, Schaschai, Scharai,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Asarel und Schelemja, Schemarja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Schallum, Amarja, Joseph;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'von den Söhnen Nebos: Jeghiel, Mattithja, Sabad, Sebina, Jaddai und Joel, Benaja.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Alle diese hatten fremde Weiber genommen, und es gab unter ihnen Weiber, welche Kinder geboren hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Geschichte Nehemias, des Sohnes Hakaljas. Und es geschah im Monat Kislew des zwanzigsten Jahres, als ich in der Burg Susan war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'da kam Hanani, einer von meinen Brüdern, er und einige Männer aus Juda. Und ich fragte sie nach den Juden, den Entronnenen, die von der Gefangenschaft übriggeblieben waren, und nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Und sie sprachen zu mir: Die Übriggebliebenen, die von der Gefangenschaft dort in der Landschaft übriggeblieben sind, sind in großem Unglück und in Schmach; und die Mauer von Jerusalem ist niedergerissen, und seine Tore sind mit Feuer verbrannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Und es geschah, als ich diese Worte hörte, setzte ich mich hin und weinte und trug Leid tagelang; und ich fastete und betete vor dem Gott des Himmels und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Ach, Jehova, Gott des Himmels, du, der große und furchtbare Gott, der den Bund und die Güte denen bewahrt, die ihn lieben und seine Gebote halten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'laß doch dein Ohr aufmerksam und deine Augen offen sein, daß du hörest auf das Gebet deines Knechtes, welches ich heute, Tag und Nacht, für die Kinder Israel, deine Knechte, vor dir bete, und wie ich die Sünden der Kinder Israel bekenne, die wir gegen dich begangen haben! Auch wir, ich und meines Vaters Haus, haben gesündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Wir haben sehr verderbt gegen dich gehandelt und haben nicht beobachtet die Gebote und die Satzungen und die Rechte, welche du deinem Knechte Mose geboten hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Gedenke doch des Wortes, das du deinem Knechte Mose geboten hast, indem du sprachst: Werdet ihr treulos handeln, so werde ich euch unter die Völker zerstreuen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'wenn ihr aber zu mir umkehret und meine Gebote beobachtet und sie tut: sollten eure Vertriebenen am Ende des Himmels sein, so würde ich sie von dannen sammeln und sie an den Ort bringen, den ich erwählt habe, um meinen Namen daselbst wohnen zu lassen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Sie sind ja deine Knechte und dein Volk, das du erlöst hast durch deine große Kraft und deine starke Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Ach, Herr, laß doch dein Ohr aufmerksam sein auf das Gebet deines Knechtes und auf das Gebet deiner Knechte, die Gefallen daran finden, deinen Namen zu fürchten; und laß es doch deinem Knechte heute gelingen und gewähre ihm Barmherzigkeit vor diesem Manne! Ich war nämlich Mundschenk des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Und es geschah im Monat Nisan, im zwanzigsten Jahre des Königs Artasasta, als Wein vor ihm war, da nahm ich den Wein und gab ihn dem König; ich war aber nie traurig vor ihm gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Und der König sprach zu mir: Warum ist dein Angesicht traurig? Und doch bist du nicht krank; es ist nichts anderes als Traurigkeit des Herzens. Da fürchtete ich mich gar sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Und ich sprach zu dem König: Der König lebe ewiglich! Warum sollte mein Angesicht nicht traurig sein, da die Stadt, die Begräbnisstätte meiner Väter, wüst liegt, und ihre Tore vom Feuer verzehrt sind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Und der König sprach zu mir: Um was bittest du denn? Da betete ich zu dem Gott des Himmels;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'und ich sprach zu dem König: Wenn es den König gut dünkt, und wenn dein Knecht wohlgefällig vor dir ist, so bitte ich, daß du mich nach Juda sendest zu der Stadt der Begräbnisse meiner Väter, damit ich sie wieder aufbaue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Da sprach der König zu mir und die Königin saß neben ihm: Wie lange wird deine Reise währen, und wann wirst du zurückkehren? Und es gefiel dem König, mich zu senden; und ich bestimmte ihm eine Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Und ich sprach zu dem König: Wenn es den König gut dünkt, so gebe man mir Briefe an die Landpfleger jenseit des Stromes, daß sie mich durchziehen lassen, bis ich nach Juda komme;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'und einen Brief an Asaph, den Hüter des königlichen Forstes, daß er mir Holz gebe, um die Tore der Burg zu bälken, welche zum Hause gehört, und für die Mauer der Stadt, und für das Haus, in welches ich ziehen werde. Und der König gab es mir, weil die gute Hand meines Gottes über mir war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Und ich kam zu den Landpflegern jenseit des Stromes und gab ihnen die Briefe des Königs. Der König hatte aber Heeroberste und Reiter mit mir gesandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Und als Sanballat, der Horoniter, und Tobija, der ammonitische Knecht, es hörten, verdroß es sie gar sehr, daß ein Mensch gekommen war, um das Wohl der Kinder Israel zu suchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Und ich kam nach Jerusalem und war daselbst drei Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Und ich machte mich des Nachts auf, ich und wenige Männer mit mir; ich hatte aber keinem Menschen kundgetan, was mein Gott mir ins Herz gegeben, für Jerusalem zu tun; und kein Tier war bei mir, außer dem Tiere, auf welchem ich ritt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Und ich zog des Nachts durch das Taltor hinaus, und gegen die Drachenquelle hin, und nach dem Misttore; und ich besichtigte die Mauern von Jerusalem, welche niedergerissen, und ihre Tore, die vom Feuer verzehrt waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Und ich zog hinüber zum Quellentore und zum Königsteiche, und es war kein Raum zum Durchkommen für das Tier, welches unter mir war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Und ich zog des Nachts das Tal hinauf und besichtigte die Mauer; und ich kam wieder durch das Taltor herein und kehrte zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Die Vorsteher wußten aber nicht, wohin ich gegangen war und was ich tat; denn ich hatte den Juden und den Priestern und den Edlen und den Vorstehern und den Übrigen, die das Werk taten, bis dahin nichts kundgetan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Und ich sprach zu ihnen: Ihr sehet das Unglück, in welchem wir sind, daß Jerusalem wüst liegt und seine Tore mit Feuer verbrannt sind. Kommt und laßt uns die Mauer Jerusalems wieder aufbauen, daß wir nicht länger zum Hohne seien!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Und ich tat ihnen kund, daß die Hand meines Gottes gütig über mir gewesen war, und auch die Worte des Königs, die er zu mir geredet hatte. Da sprachen sie: Wir wollen uns aufmachen und bauen! Und sie stärkten ihre Hände zum Guten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Als aber Sanballat, der Horoniter, und Tobija, der ammonitische Knecht, und Geschem, der Araber, es hörten, spotteten sie über uns und verachteten uns und sprachen: Was ist das für eine Sache, die ihr tun wollt? Wollt ihr euch wider den König empören?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Und ich gab ihnen Antwort und sprach zu ihnen: Der Gott des Himmels, er wird es uns gelingen lassen; und wir, seine Knechte, wollen uns aufmachen und bauen. Ihr aber habt weder Teil noch Recht, noch Gedächtnis in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Und Eljaschib, der Hohepriester, und seine Brüder, die Priester, machten sich auf und bauten das Schaftor; sie heiligten es und setzten seine Flügel ein. Und sie heiligten es bis an den Turm Mea, bis an den Turm Hananel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Und ihm zur Seite bauten die Männer von Jericho. Und ihnen zur Seite baute Sakkur, der Sohn Imris.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Und das Fischtor bauten die Söhne Senaas; sie bälkten es und setzten seine Flügel, seine Klammern und seine Riegel ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Und ihnen zur Seite besserte aus Meremoth, der Sohn Urijas, des Sohnes Hakkoz\'. Und ihm zur Seite besserte aus Meschullam, der Sohn Berekja, des Sohnes Meschesabeels. Und ihm zur Seite besserte aus Zadok, der Sohn Baanas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Und ihm zur Seite besserten die Tekoiter aus; aber die Vornehmen unter ihnen beugten ihren Nacken nicht unter den Dienst ihres Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Und das Tor der alten Mauer besserten aus Jojada, der Sohn Paseachs, und Meschullam, der Sohn Besodjas; sie bälkten es und setzten seine Flügel, seine Klammern und seine Riegel ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Und ihnen zur Seite besserten aus Melatja, der Gibeoniter, und Jadon, der Meronothiter, Männer von Gibeon und Mizpa, gegen den Gerichtsstuhl des Landpflegers diesseit des Stromes hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Ihnen zur Seite besserte aus Ussiel, der Sohn Harchajas, welche Goldschmiede waren. Und ihm zur Seite besserte aus Hananja, von den Salbenmischern. Und sie ließen Jerusalem bis an die breite Mauer, wie es war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Und ihm zur Seite besserte aus Rephaja, der Sohn Hurs, der Oberste des halben Bezirks von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Und ihm zur Seite besserte aus Jedaja, der Sohn Harumaphs, und zwar seinem Hause gegenüber. Und ihm zur Seite besserte aus Hattusch, der Sohn Haschabnejas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Malkija, der Sohn Harims, und Haschub, der Sohn Pachath-Moabs, besserten eine andere Strecke aus und den Ofenturm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Und ihnen zur Seite besserte aus Schallum, der Sohn Hallochesch\', der Oberste des anderen halben Bezirks von Jerusalem, er und seine Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Das Taltor besserten aus Hanun und die Bewohner von Sanoach; sie bauten es und setzten seine Flügel, seine Klammern und seine Riegel ein, und bauten tausend Ellen an der Mauer bis zum Misttore.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Und das Misttor besserte aus Malkija, der Sohn Rekabs, der Oberste des Bezirks von Beth-Kerem; er baute es und setzte seine Flügel, seine Klammern und seine Riegel ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Und das Quelltor besserte aus Schallun, der Sohn Kol-Hoses, der Oberste des Bezirks von Mizpa; er baute es und überdachte es und setzte seine Flügel, seine Klammern und seine Riegel ein; und er baute die Mauer am Teiche Siloah bei dem Garten des Königs und bis zu den Stufen, welche von der Stadt Davids hinabgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Nächst ihm besserte aus Nehemia, der Sohn Asbuks, der Oberste des halben Bezirks von Beth-Zur, bis gegenüber den Gräbern Davids und bis zu dem Teiche, der angelegt worden war, und bis zu dem Hause der Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Nächst ihm besserten aus die Leviten, Rechum, der Sohn Banis. Ihm zur Seite besserte aus Haschabja, der Oberste des halben Bezirks von Kehila, für seinen Bezirk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Nächst ihm besserten aus ihre Brüder, Bawai, der Sohn Henadads, der Oberste des anderen halben Bezirks von Kehila.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Und ihm zur Seite besserte Eser, der Sohn Jeschuas, der Oberste von Mizpa, eine andere Strecke aus, gegenüber dem Aufgang zum Zeughause des Winkels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Nächst ihm besserte Baruk, der Sohn Sabbais, eine andere Strecke eifrig aus, vom Winkel bis zum Eingang des Hauses Eljaschibs, des Hohenpriesters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Nächst ihm besserte Meremoth, der Sohn Urijas, des Sohnes Hakkoz\', eine andere Strecke aus, vom Eingang des Hauses Eljaschibs bis zum Ende des Hauses Eljaschibs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Und nächst ihm besserten aus die Priester, die Männer des Jordankreises.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Nächst ihnen besserten aus Benjamin und Haschub, ihrem Hause gegenüber. Nächst ihnen besserte aus Asarja, der Sohn Maasejas, des Sohnes Ananjas, neben seinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Nächst ihm besserte Binnui, der Sohn Henadads, eine andere Strecke aus, vom Hause Asarjas bis an den Winkel und bis an die Ecke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, der Sohn Usais, besserte aus gegenüber dem Winkel und dem hohen Turme, welcher an dem Hause des Königs vorspringt, der bei dem Gefängnishofe ist. Nächst ihm Pedaja, der Sohn Parhosch\'. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Und die Nethinim wohnten auf dem Ophel bis gegenüber dem Wassertore nach Osten und dem vorspringenden Turme. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Nächst ihm besserten die Tekoiter eine andere Strecke aus, dem großen vorspringenden Turme gegenüber und bis zur Mauer des Ophel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Oberhalb des Roßtores besserten die Priester aus, ein jeder seinem Hause gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Nächst ihnen besserte aus Zadok, der Sohn Immers, seinem Hause gegenüber. Und nächst ihm besserte aus Schemaja, der Sohn Schekanjas, der Hüter des Osttores.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Nächst ihm besserten Hananja, der Sohn Schelemjas, und Hanun, der sechste Sohn Zalaphs, eine andere Strecke aus. Nächst ihm besserte aus Meschullam, der Sohn Berekjas, seiner Zelle gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Nächst ihm besserte aus Malkija, von den Goldschmieden, bis an das Haus der Nethinim und der Krämer, dem Tore Miphkad gegenüber und bis an das Obergemach der Ecke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Und zwischen dem Obergemach der Ecke und dem Schaftore besserten die Goldschmiede und die Krämer aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Und es geschah, als Sanballat hörte, daß wir die Mauer bauten, da wurde er zornig und ärgerte sich sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Und er spottete über die Juden und sprach vor seinen Brüdern und dem Heere von Samaria und sagte: Was machen die ohnmächtigen Juden? Wird man es ihnen zulassen? Werden sie opfern? Werden sie es an diesem Tage vollenden? Werden sie die Steine aus den Schutthaufen wieder beleben, da sie doch verbrannt sind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Und Tobija, der Ammoniter, stand neben ihm und sprach: Was sie auch bauen; wenn ein Fuchs hinaufstiege, so würde er ihre steinerne Mauer auseinander reißen! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Höre, unser Gott, denn wir sind zur Verachtung geworden; und bringe ihren Hohn auf ihren Kopf zurück, und gib sie dem Raube hin in einem Lande der Gefangenschaft!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Und decke ihre Ungerechtigkeit nicht zu, und ihre Sünde werde nicht ausgelöscht vor deinem Angesicht! Denn sie haben dich gereizt angesichts der Bauenden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Aber wir bauten weiter an der Mauer; und die ganze Mauer wurde bis zur Hälfte geschlossen, und das Volk hatte Mut zur Arbeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Und es geschah, als Sanballat und Tobija und die Araber und die Ammoniter und die Asdoditer hörten, daß die Herstellung der Mauern Jerusalems zunahm, daß die Risse sich zu schließen begannen, da wurden sie sehr zornig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Und sie verschworen sich alle miteinander, zu kommen, um wider Jerusalem zu streiten und Schaden darin anzurichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Da beteten wir zu unserem Gott und stellten aus Furcht vor ihnen Tag und Nacht Wachen gegen sie auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Und Juda sprach: Die Kraft der Lastträger sinkt, und des Schuttes ist viel, und so vermögen wir nicht mehr an der Mauer zu bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Unsere Widersacher aber sprachen: Sie sollen es nicht wissen, noch sollen sie es sehen, bis wir mitten unter sie kommen und sie erschlagen und dem Werke Einhalt tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Und es geschah, als die Juden, welche neben ihnen wohnten, kamen und uns wohl zehnmal sagten, aus allen Orten her: Kehret zu uns zurück!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'da stellte ich an niedrigen Stellen des Raumes hinter der Mauer an nackten Plätzen, da stellte ich das Volk auf nach den Geschlechtern, mit ihren Schwertern, ihren Lanzen und ihren Bogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Und ich sah zu und machte mich auf und sprach zu den Edlen und zu den Vorstehern und zu dem übrigen Volke: Fürchtet euch nicht vor ihnen! Gedenket des Herrn, des großen und furchtbaren, und streitet für eure Brüder, eure Söhne und eure Töchter, eure Weiber und eure Häuser!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Und es geschah, als unsere Feinde hörten, daß es uns kundgeworden war, und daß Gott ihren Rat vereitelt hatte, da kehrten wir alle zur Mauer zurück, ein jeder an sein Werk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Und es geschah von jenem Tage an, daß die Hälfte meiner Diener an dem Werke arbeitete, während die andere Hälfte die Lanzen und die Schilde und die Bogen und die Panzer hielt; und die Obersten waren hinter dem ganzen Hause Juda, welches an der Mauer baute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Und die Lastträger luden auf, mit der einen Hand am Werke arbeitend, während die andere die Waffe hielt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Und die Bauenden hatten ein jeder sein Schwert um seine Lenden gegürtet und bauten. Und der in die Posaune stieß, war neben mir. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Und ich sprach zu den Edlen und zu den Vorstehern und zu dem übrigen Volke: Das Werk ist groß und weitläufig, und wir sind auf der Mauer zerstreut, einer von dem anderen entfernt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'An dem Orte, wo ihr den Schall der Posaune hören werdet, dahin versammelt euch zu uns. Unser Gott wird für uns streiten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'So arbeiteten wir an dem Werke, und die Hälfte von ihnen hielt die Lanzen vom Aufgang der Morgenröte an, bis die Sterne hervortraten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Auch sprach ich in selbiger Zeit zu dem Volke: Ein jeder übernachte mit seinem Diener innerhalb Jerusalems, so daß sie uns des Nachts zur Wache und des Tages zum Werke dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Und weder ich, noch meine Brüder, noch meine Diener, noch die Männer der Wache, die in meinem Gefolge waren, zogen unsere Kleider aus; ein jeder hatte seine Waffe zu seiner Rechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Und es entstand ein großes Geschrei des Volkes und ihrer Weiber gegen ihre Brüder, die Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Und es gab solche, die da sprachen: Unserer Söhne und unserer Töchter, unser sind viele; und wir müssen Getreide erhalten, daß wir essen und leben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Und es gab solche, die da sprachen: Wir mußten unsere Felder und unsere Weinberge und unsere Häuser verpfänden, daß wir Getreide erhielten in der Hungersnot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Und es gab solche, die da sprachen: Wir haben Geld entlehnt auf unsere Felder und unsere Weinberge für die Steuer des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Und nun, unser Fleisch ist wie das Fleisch unserer Brüder, unsere Kinder sind wie ihre Kinder; und siehe, wir müssen unsere Söhne und unsere Töchter dem Knechtsdienst unterwerfen; und manche von unseren Töchtern sind schon unterworfen, und es steht nicht in der Macht unserer Hände, sie zu lösen; unsere Felder und unsere Weinberge gehören ja anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Und als ich ihr Geschrei und diese Worte hörte, wurde ich sehr zornig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Und mein Herz pflegte Rats in mir, und ich haderte mit den Edlen und mit den Vorstehern und sprach zu ihnen: Auf Wucher leihet ihr, ein jeder seinem Bruder! Und ich veranstaltete eine große Versammlung gegen sie; und ich sprach zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Wir haben unsere Brüder, die Juden, welche den Nationen verkauft waren, soweit es uns möglich war, losgekauft; und ihr wollt gar eure Brüder verkaufen? Und sie sollen sich uns verkaufen? Da schwiegen sie und fanden keine Antwort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Und ich sprach: Nicht gut ist die Sache, die ihr tut! Solltet ihr nicht in der Furcht unseres Gottes wandeln, daß wir nicht den Nationen, unseren Feinden, zum Hohne seien?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Aber auch ich, meine Brüder und meine Diener, wir haben ihnen Geld und Getreide auf Zins geliehen. Laßt uns doch diesen Zins erlassen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Gebet ihnen doch gleich heute ihre Felder, ihre Weinberge, ihre Olivengärten und ihre Häuser zurück; und erlaßt ihnen den Hundertsten von dem Gelde und dem Getreide, dem Moste und dem Öle, welches ihr ihnen auf Zins geliehen habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Da sprachen sie: Wir wollen es zurückgeben und nichts von ihnen fordern; wir wollen also tun, wie du sagst. Und ich rief die Priester und ließ sie schwören, nach diesem Worte zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Auch schüttelte ich meinen Busen aus und sprach: So möge Gott jedermann, der dieses Wort nicht aufrecht halten wird, aus seinem Hause und aus seinem Erwerbe schütteln; und so sei er ausgeschüttelt und ausgeleert! Und die ganze Versammlung sprach: Amen! Und sie lobten Jehova. Und das Volk tat nach diesem Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Auch von dem Tage an, da er mich bestellt hatte, um ihr Landpfleger zu sein im Lande Juda, vom zwanzigsten Jahre bis zum zweiunddreißigsten Jahre des Königs Artasasta, zwölf Jahre lang, habe ich mit meinen Brüdern die Speise des Landpflegers nicht gegessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Aber die früheren Landpfleger, die vor mir gewesen waren, hatten das Volk beschwert und Brot und Wein von ihnen genommen, nebst vierzig Sekel Silber; auch ihre Diener schalteten willkürlich über das Volk. Ich aber tat nicht also, aus Furcht vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Und auch an dem Werke dieser Mauer griff ich mit an; und wir kauften kein Feld; und alle meine Diener waren daselbst zum Werke versammelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Und die Juden, sowohl die Vorsteher, hundertfünfzig Mann, als auch die, welche aus den Nationen, die ringsumher wohnten, zu uns kamen, waren an meinem Tische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Und was für einen Tag zubereitet wurde: ein Rind, sechs ausgewählte Schafe und Geflügel wurden mir zubereitet; und alle zehn Tage an allerlei Wein die Fülle; und trotzdem forderte ich nicht die Speise des Landpflegers, denn der Dienst lastete schwer auf diesem Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Gedenke mir, mein Gott, zum Guten, alles, was ich für dieses Volk getan habe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Und es geschah, als Sanballat und Tobija und Geschem, der Araber, und unsere übrigen Feinde vernahmen, daß ich die Mauer gebaut hätte und daß kein Riß mehr darin wäre, doch hatte ich bis zu jener Zeit die Flügel noch nicht in die Tore eingesetzt-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'da sandten Sanballat und Geschem zu mir und ließen mir sagen: Komm und laß uns in einem der Dörfer im Tale von Ono miteinander zusammentreffen! Sie gedachten aber, mir Böses zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Und ich sandte Boten zu ihnen und ließ ihnen sagen: Ich führe ein großes Werk aus und kann nicht hinabkommen. Warum sollte das Werk ruhen, wenn ich es ließe und zu euch hinabkäme?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Und sie sandten auf diese Weise viermal zu mir, und ich erwiderte ihnen auf diesselbe Weise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Da sandte Sanballat auf diese Weise zum fünften Male seinen Diener zu mir mit einem offenen Briefe in seiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Darin stand geschrieben: Unter den Nationen verlautet, und Gaschmu sagt es, daß ihr, du und die Juden, euch zu empören gedenket; darum bauest du die Mauer; und du wollest, nach diesem Gerücht, ihr König werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'auch habest du Propheten bestellt, damit sie in Jerusalem über dich ausrufen und sagen: Es ist ein König in Juda! Und nun wird der König diese Gerüchte vernehmen. So komm nun, daß wir uns zusammen beraten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Da sandte ich zu ihm und ließ ihm sagen: Es ist nicht geschehen nach diesen Worten, die du sprichst; sondern aus deinem eigenen Herzen erdichtest du sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Denn sie alle wollten uns in Furcht setzen, indem sie sprachen: Ihre Hände werden von dem Werke ablassen, und es wird nicht ausgeführt werden. Und nun, stärke meine Hände!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Und ich kam in das Haus Schemajas, des Sohnes Delajas, des Sohnes Mehetabeels, der sich eingeschlossen hatte. Und er sprach: Laß uns im Hause Gottes, im Innern des Tempels, zusammenkommen und die Türen des Tempels verschließen; denn sie werden kommen, dich zu ermorden; und zwar werden sie bei der Nacht kommen, dich zu ermorden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Aber ich sprach: Ein Mann wie ich sollte fliehen? Und wie könnte einer, wie ich bin, in den Tempel hineingehen und am Leben bleiben? Ich will nicht hineingehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Und ich merkte, daß nicht Gott ihn gesandt hatte; sondern er sprach diese Weissagung wider mich, und Tobija und Sanballat hatten ihn gedungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Darum war er gedungen, damit ich mich fürchten und also tun und mich versündigen sollte, und damit sie ein böses Gerücht hätten, auf daß sie mich verlästern könnten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Gedenke es, mein Gott, dem Tobija und dem Sanballat nach diesen ihren Werken, und auch der Prophetin Noadja und den übrigen Propheten, die mich in Furcht setzen wollten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Und die Mauer wurde vollendet am Fünfundzwanzigsten des Elul, in zweiundfünfzig Tagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Und es geschah, als alle unsere Feinde es hörten, da fürchteten sich alle Nationen, die rings um uns her waren, und sie sanken sehr in ihren Augen; und sie erkannten, daß dieses Werk von unserem Gott aus geschehen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Auch ließen in jenen Tagen Edle von Juda viele Briefe an Tobija abgehen, und solche von Tobija kamen an sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Denn es gab viele in Juda, die ihm geschworen hatten, denn er war ein Schwiegersohn Schekanjas, des Sohnes Arachs; und sein Sohn Jochanan hatte die Tochter Meschullams, des Sohnes Berekjas, genommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Auch redeten sie vor mir von seinen guten Taten und hinterbrachten ihm meine Worte; und Tobija sandte Briefe, um mich in Furcht zu setzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Und es geschah, als die Mauer gebaut war, da setzte ich die Türflügel ein; und die Torhüter und die Sänger und die Leviten wurden bestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Und ich beorderte über Jerusalem meinen Bruder Hanani und Hananja, den Obersten der Burg; denn er war ein sehr treuer Mann und gottesfürchtig vor vielen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Und ich sprach zu ihnen: Die Tore Jerusalems sollen nicht eher geöffnet werden, als bis die Sonne heiß scheint; und während sie noch dastehen, soll man die Türflügel zumachen, und verschließet sie. Und ihr sollt Wachen aus den Bewohnern Jerusalems aufstellen, den einen auf seine Wache und den anderen vor sein Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Die Stadt aber war geräumig und groß, und das Volk darin spärlich, und keine Häuser waren gebaut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Und mein Gott gab mir ins Herz, die Edlen und die Vorsteher und das Volk zu versammeln, um sie nach den Geschlechtern zu verzeichnen. Und ich fand das Geschlechtsverzeichnis derer, die zuerst heraufgezogen waren, und fand darin geschrieben:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Dies sind die Kinder der Landschaft Juda, welche aus der Gefangenschaft der Weggeführten, die Nebukadnezar, der König von Babel, weggeführt hatte, hinaufzogen, und die nach Jerusalem und Juda zurückkehrten, ein jeder in seine Stadt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'welche kamen mit Serubbabel, Jeschua, Nehemia, Asarja, Raamja, Nachamani, Mordokai, Bilschan, Mispereth, Bigwai, Nechum, Baana. Zahl der Männer des Volkes Israel:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Die Söhne Parhosch\', zweitausend einhundertzweiundsiebzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'die Söhne Schephatjas, dreihundertzweiundsiebzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'die Söhne Arachs, sechshundertzweiundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'die Söhne Pachath-Moabs, von den Söhnen Jeschuas und Joabs, zweitausend achthundertachtzehn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'die Söhne Elams, tausend zweihundertvierundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'die Söhne Sattus, achthundertfünfundvierzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'die Söhne Sakkais, siebenhundertsechzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'die Söhne Binnuis, sechshundertachtundvierzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'die Söhne Bebais, sechshundertachtundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'die Söhne Asgads, zweitausend dreihundertzweiundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'die Söhne Adonikams, sechshundertsiebenundsechzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'die Söhne Bigwais, zweitausend siebenundsechzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'die Söhne Adins, sechshundertfünfundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'die Söhne Aters, von Hiskia, achtundneunzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'die Söhne Haschums, dreihundertachtundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'die Söhne Bezais, dreihundertvierundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'die Söhne Hariphs, hundertzwölf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'die Söhne Gibeons, fünfundneunzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'die Männer von Bethlehem und Netopha, hundertachtundachtzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'die Männer von Anathoth, hundertachtundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'die Männer von Beth-Asmaweth, zweiundvierzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'die Männer von Kirjath-Jearim, Kephira und Beeroth, siebenhundertdreiundvierzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'die Männer von Rama und Geba, sechshunderteinundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'die Männer von Mikmas, hundertzweiundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'die Männer von Bethel und Ai, hundertdreiundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'die Männer von dem anderen Nebo, zweiundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'die Söhne des anderen Elam, tausend zweihundertvierundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'die Söhne Harims, dreihundertzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'die Söhne Jerechos, dreihundertfünfundvierzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'die Söhne Lods, Hadids und Onos, siebenhunderteinundzwanzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'die Söhne Senaas, dreitausend neunhundertdreißig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Die Priester: die Söhne Jedajas, vom Hause Jeschuas, neunhundertdreiundsiebzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'die Söhne Immers, tausend und zweiundfünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'die Söhne Paschchurs, tausend zweihundertsiebenundvierzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'die Söhne Harims, tausend und siebzehn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Die Leviten: die Söhne Jeschuas und Kadmiels, von den Söhnen Hodwas, vierundsiebzig. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Die Sänger: die Söhne Asaphs, hundertachtundvierzig. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Die Torhüter: die Söhne Schallums, die Söhne Aters, die Söhne Talmons, die Söhne Akkubs, die Söhne Hatitas, die Söhne Schobais, hundertachtunddreißig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Die Nethinim: die Söhne Zichas, die Söhne Hasuphas, die Söhne Tabbaoths,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'die Söhne Keros\', die Söhne Sias, die Söhne Padons,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'die Söhne Lebanas, die Söhne Hagabas, die Söhne Salmais,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'die Söhne Hanans, die Söhne Giddels, die Söhne Gachars,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'die Söhne Reajas, die Söhne Rezins, die Söhne Nekodas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'die Söhne Gassams, die Söhne Ussas, die Söhne Paseachs,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'die Söhne Besais, die Söhne der Meunim, die Söhne der Nephisim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'die Söhne Bakbuks, die Söhne Hakuphas, die Söhne Harchurs,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'die Söhne Bazluths, die Söhne Mechidas, die Söhne Harschas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'die Söhne Barkos\', die Söhne Siseras, die Söhne Tamachs,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'die Söhne Neziachs, die Söhne Hatiphas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Die Söhne der Knechte Salomos: die Söhne Sotais, die Söhne Sophereths, die Söhne Peridas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'die Söhne Jaalas, die Söhne Darkons, die Söhne Giddels,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'die Söhne Schephatjas, die Söhne Hattils, die Söhne Pokereths-Hazzebaim, die Söhne Amons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Alle Nethinim und Söhne der Knechte Salomos: dreihundertzweiundneunzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Und diese sind es, die aus Tel-Melach, Tel-Harscha, Kerub, Addon und Immer hinaufzogen; aber sie konnten ihr Vaterhaus und ihre Abkunft nicht angeben, ob sie aus Israel wären:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'die Söhne Delajas, die Söhne Tobijas, die Söhne Nekodas, sechshundertzweiundvierzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Und von den Priestern: die Söhne Habajas, die Söhne Hakkoz\', die Söhne Barsillais, der ein Weib von den Töchtern Barsillais, des Gileaditers, genommen hatte und nach ihrem Namen genannt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Diese suchten ihr Geschlechtsregisterverzeichnis, aber es wurde nicht gefunden; und sie wurden von dem Priestertum als unrein ausgeschlossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Und der Tirsatha sprach zu ihnen, daß sie von dem Hochheiligen nicht essen dürften, bis ein Priester für die Urim und die Thummim aufstände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Die ganze Versammlung insgesamt war zweiundvierzigtausend dreihundertundsechzig,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'außer ihren Knechten und ihren Mägden; dieser waren siebentausend dreihundertsiebenunddreißig. Und sie hatten zweihundertfünfundvierzig Sänger und Sängerinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Ihrer Rosse waren siebenhundertsechsunddreißig, ihrer Maultiere zweihundertfünfundvierzig,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'der Kamele vierhundertfünfunddreißig, der Esel sechstausend siebenhundertzwanzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Und ein Teil der Häupter der Väter gab zum Werke. Der Tirsatha gab für den Schatz: an Gold tausend Dariken, fünfzig Sprengschalen, fünfhundertdreißig Priesterleibröcke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Und einige von den Häuptern der Väter gaben für den Schatz des Werkes: an Gold zwanzigtausend Dariken, und an Silber zweitausend zweihundert Minen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Und was das übrige Volk gab, war an Gold zwanzigtausend Dariken, und an Silber zweitausend Minen, und siebenundsechzig Priesterleibröcke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Und die Priester und die Leviten und die Torhüter und die Sänger und die aus dem Volke und die Nethinim und ganz Israel wohnten in ihren Städten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Und als der siebte Monat herankam und die Kinder Israel in ihren Städten waren, da versammelte sich das ganze Volk wie ein Mann auf dem Platze, der vor dem Wassertore liegt. Und sie sprachen zu Esra, dem Schriftgelehrten, daß er das Buch des Gesetzes Moses bringen sollte, welches Jehova Israel geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Und am ersten Tage des siebten Monats brachte Esra, der Priester, das Gesetz vor die Versammlung, sowohl der Männer als der Weiber, und vor alle, die Verständnis hatten, um zuzuhören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Und er las darin vor dem Platze, der vor dem Wassertore liegt, vom lichten Morgen bis zum Mittag, in Gegenwart der Männer und der Weiber und derer, die Verständnis hatten; und die Ohren des ganzen Volkes waren auf das Buch des Gesetzes gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Und Esra, der Schriftgelehrte, stand auf einem Gerüst von Holz, welches man zu diesem Zweck gemacht hatte. Und neben ihm standen Mattithja und Schema und Anaja und Urija und Hilkija und Maaseja, zu seiner Rechten; und zu seiner Linken Pedaja und Mischael und Malkija und Haschum und Haschbaddana, Sekarja, Meschullam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Und Esra öffnete das Buch vor den Augen des ganzen Volkes, denn er ragte über dem ganzen Volke empor; und als er es öffnete, stand das ganze Volk auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Und Esra pries Jehova, den großen Gott, und das ganze Volk antwortete: Amen, Amen! indem sie ihre Hände emporhoben und sich verneigten und vor Jehova niederwarfen, mit dem Antlitz zur Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Und Jeschua und Bani und Scherebja, Jamin, Akkub, Schabbethai, Hodija, Maaseja, Kelita, Asarja, Josabad, Hanan, Pelaja und die Leviten belehrten das Volk über das Gesetz; und das Volk stand auf seiner Stelle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Und sie lasen in dem Buche, in dem Gesetz Gottes, deutlich, und gaben den Sinn an, so daß man das Gelesene verstand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Und Nehemia, das ist der Tirsatha, und Esra, der Priester, der Schriftgelehrte, und die Leviten, welche das Volk belehrten, sprachen zu dem ganzen Volke: Dieser Tag ist Jehova, eurem Gott, heilig; seid nicht traurig und weinet nicht! (Denn das ganze Volk weinte, als es die Worte des Gesetzes hörte.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Und er sprach zu ihnen: Gehet hin, esset Fettes und trinket Süßes, und sendet Teile denen, für welche nichts zubereitet ist; denn der Tag ist unserem Herrn heilig; und betrübet euch nicht, denn die Freude an Jehova ist eure Stärke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Und die Leviten beschwichtigten das ganze Volk, indem sie sprachen: Seid stille, denn der Tag ist heilig; und betrübet euch nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Und das ganze Volk ging hin, um zu essen und zu trinken und Teile zu senden und ein großes Freudenfest zu begehen. Denn sie hatten die Worte verstanden, die man ihnen kundgetan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Und am zweiten Tage versammelten sich die Häupter der Väter des ganzen Volkes, die Priester und die Leviten, zu Esra, dem Schriftgelehrten, und zwar um aufzumerken auf die Worte des Gesetzes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Und sie fanden im Gesetz geschrieben, daß Jehova durch Mose geboten hatte, daß die Kinder Israel am Feste im siebten Monat in Laubhütten wohnen sollten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'und daß sie verkündigen und einen Ruf ergehen lassen sollten durch alle ihre Städte und durch Jerusalem, und sagen: Gehet hinaus auf das Gebirge und holet Zweige vom Olivenbaum und Zweige vom wilden Ölbaum und Myrtenzweige und Palmzweige und Zweige von dichtbelaubten Bäumen, um Hütten zu machen, wie geschrieben steht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Und das Volk ging hinaus und holte herbei; und sie machten sich Hütten, ein jeder auf seinem Dache und in ihren Höfen, und in den Höfen des Hauses Gottes, und auf dem Platze am Wassertore, und auf dem Platze am Tore Ephraim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Und die ganze Versammlung, die aus der Gefangenschaft zurückgekehrt war, machte Hütten und wohnte in den Hütten. Denn die Kinder Israel hatten nicht also getan seit den Tagen Josuas, des Sohnes Nuns, bis auf jenen Tag. Und es war eine sehr große Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Und man las in dem Buche des Gesetzes Gottes Tag für Tag, vom ersten Tage bis zum letzten Tage. Und sie feierten das Fest sieben Tage lang; und am achten Tage war eine Festversammlung nach der Vorschrift.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Und am vierundzwanzigsten Tage dieses Monats versammelten sich die Kinder Israel unter Fasten, und in Sacktuch gekleidet, und mit Erde auf ihren Häuptern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Und der Same Israels sonderte sich ab von allen Kindern der Fremde; und sie traten hin und bekannten ihre Sünden und die Ungerechtigkeiten ihrer Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Und sie standen auf an ihrer Stelle und lasen in dem Buche des Gesetzes Jehovas, ihres Gottes, ein Viertel des Tages. Und ein anderes Viertel des Tages bekannten sie ihre Sünden und warfen sich nieder vor Jehova, ihrem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Und Jeschua und Bani, Kadmiel, Schebanja, Bunni, Scherebja, Bani, Kenani traten auf die Erhöhung der Leviten, und sie schrieen mit lauter Stimme zu Jehova, ihrem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Und die Leviten Jeschua und Kadmiel, Bani, Haschabneja, Scherebja, Hodija, Schebanja, Pethachja sprachen: Stehet auf, preiset Jehova, euren Gott, von Ewigkeit zu Ewigkeit! Und man preise deinen herrlichen Namen, der erhaben ist über allen Preis und Ruhm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Du bist, der da ist, Jehova, du allein; du hast die Himmel gemacht, der Himmel Himmel und all ihr Heer, die Erde und alles, was darauf ist, die Meere und alles, was in ihnen ist. Und du machst dies alles lebendig, und das Heer des Himmels betet dich an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Du bist es, Jehova, Gott, der du Abram erwählt und ihn aus Ur in Chaldäa herausgeführt, und ihm den Namen Abraham gegeben hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Und du hast sein Herz treu vor dir erfunden und hast mit ihm den Bund gemacht, das Land der Kanaaniter, der Hethiter, der Amoriter und der Perisiter und der Jebusiter und der Girgasiter zu geben, seinem Samen es zu geben; und du hast deine Worte erfüllt, denn du bist gerecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Und du hast das Elend unserer Väter in Ägypten angesehen, und hast ihr Geschrei am Schilfmeere gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Und du hast Zeichen und Wunder getan an dem Pharao und an allen seinen Knechten und an allem Volke seines Landes; denn du wußtest, daß sie in Übermut gegen sie gehandelt hatten; und du hast dir einen Namen gemacht, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Und das Meer hast du vor ihnen gespalten, und sie zogen mitten durch das Meer auf dem Trockenen; aber ihre Verfolger hast du in die Tiefen gestürzt, wie einen Stein in mächtige Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Und in einer Wolkensäule hast du sie geleitet des Tages, und in einer Feuersäule des Nachts, um ihnen den Weg zu erleuchten, auf welchem sie ziehen sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Und auf den Berg Sinai bist du herabgestiegen, und hast vom Himmel her mit ihnen geredet; und du hast ihnen gerade Rechte und Gesetze der Wahrheit, gute Satzungen und Gebote gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Und deinen heiligen Sabbath hast du ihnen kundgetan, und hast ihnen Gebote und Satzungen und ein Gesetz geboten durch Mose, deinen Knecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Und Brot vom Himmel hast du ihnen gegeben für ihren Hunger, und Wasser aus dem Felsen ihnen hervorgebracht für ihren Durst; und du hast ihnen gesagt, daß sie hineinziehen sollten, um das Land in Besitz zu nehmen, welches du ihnen zu geben geschworen hattest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Aber sie, nämlich unsere Väter, waren übermütig, und sie verhärteten ihren Nacken und hörten nicht auf deine Gebote.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Und sie weigerten sich zu gehorchen, und gedachten nicht deiner Wunder, welche du an ihnen getan hattest; sie verhärteten ihren Nacken und setzten sich in ihrer Widerspenstigkeit ein Haupt, um zu ihrer Knechtschaft zurückzukehren. Du aber bist ein Gott der Vergebung, gnädig und barmherzig, langsam zum Zorn und groß an Güte, und du verließest sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Sogar als sie sich ein gegossenes Kalb machten und sprachen: Das ist dein Gott, der dich aus Ägypten heraufgeführt hat! und große Schmähungen verübten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'verließest du in deinen großen Erbarmungen sie doch nicht in der Wüste. Die Wolkensäule wich nicht von ihnen des Tages, um sie auf dem Wege zu leiten, noch die Feuersäule des Nachts, um ihnen den Weg zu erleuchten, auf welchem sie ziehen sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Und du gabst ihnen deinen guten Geist, um sie zu unterweisen; und dein Manna versagtest du nicht ihrem Munde, und du gabst ihnen Wasser für ihren Durst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Und vierzig Jahre lang versorgtest du sie in der Wüste, sie hatten keinen Mangel; ihre Kleider zerfielen nicht, und ihre Füße schwollen nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Und du gabst ihnen Königreiche und Völker und verteiltest ihnen dieselben nach Gegenden; und sie nahmen das Land Sihons in Besitz, sowohl das Land des Königs von Hesbon, als auch das Land Ogs, des Königs von Basan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Und ihre Söhne mehrtest du wie die Sterne des Himmels; und du brachtest sie in das Land, von welchem du ihren Vätern gesagt hattest, daß sie hineingehen sollten, um es in Besitz zu nehmen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'und die Söhne kamen hinein und nahmen das Land in Besitz. Und du beugtest vor ihnen die Bewohner des Landes, die Kanaaniter, und gabst sie in ihre Hand, sowohl ihre Könige als auch die Völker des Landes, um mit ihnen zu tun nach ihrem Wohlgefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Und sie nahmen feste Städte ein und ein fettes Land, und nahmen Häuser in Besitz, die mit allerlei Gut gefüllt waren, ausgehauene Brunnen, Weinberge und Olivengärten und Obstbäume in Menge. Und sie aßen und wurden satt und fett und ließen sich\'s wohl sein durch deine große Güte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Aber sie wurden widerspenstig und empörten sich gegen dich, und warfen dein Gesetz hinter ihren Rücken; und sie ermordeten deine Propheten, welche wider sie zeugten, um sie zu dir zurückzuführen; und sie verübten große Schmähungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Da gabst du sie in die Hand ihrer Bedränger, und diese bedrängten sie; und zur Zeit ihrer Bedrängnis schrieen sie zu dir, und du hörtest vom Himmel her und gabst ihnen Retter nach deinen großen Erbarmungen, und diese retteten sie aus der Hand ihrer Bedränger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Aber sobald sie Ruhe hatten, taten sie wiederum Böses vor dir. Da überließest du sie der Hand ihrer Feinde, daß diese über sie herrschten; und sie schrieen wiederum zu dir, und du hörtest vom Himmel her und errettetest sie nach deinen Erbarmungen viele Male.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Und du zeugtest wider sie, um sie zu deinem Gesetz zurückzuführen, sie aber waren übermütig und gehorchten deinen Geboten nicht, sondern sündigten wider deine Rechte, durch welche der Mensch, wenn er sie tut, leben wird; und sie zogen die Schulter widerspenstig zurück und verhärteten ihren Nacken und gehorchten nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Und du verzogest mit ihnen viele Jahre und zeugtest wider sie durch deinen Geist, durch deine Propheten, aber sie gaben kein Gehör. Da gabst du sie in die Hand der Völker der Länder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Aber in deinen großen Erbarmungen hast du ihnen nicht den Garaus gemacht und sie nicht verlassen; denn du bist ein gnädiger und barmherziger Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Und nun, unser Gott, du großer, starker und furchtbarer Gott, der den Bund und die Güte bewahrt, laß nicht gering vor dir sein alle die Mühsal, die uns betroffen hat, unsere Könige, unsere Obersten und unsere Priester und unsere Propheten und unsere Väter und dein ganzes Volk, seit den Tagen der Könige von Assyrien bis auf diesen Tag!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Doch du bist gerecht in allem, was über uns gekommen ist; denn du hast nach der Wahrheit gehandelt, wir aber, wir haben gesetzlos gehandelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Und unsere Könige, unsere Obersten, unsere Priester und unsere Väter haben dein Gesetz nicht gehalten, und haben nicht gemerkt auf deine Gebote und auf deine Zeugnisse, womit du wider sie gezeugt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Und sie haben dir nicht gedient in ihrem Königreiche und in der Fülle deiner Güter, welche du ihnen gegeben, und in dem weiten und fetten Lande, das du vor sie gelegt hattest, und sind nicht umgekehrt von ihren bösen Handlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Siehe, wir sind heute Knechte; und das Land, welches du unseren Vätern gegeben hast, um seine Früchte und seine Güter zu genießen, siehe, wir sind Knechte in demselben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Und seinen Ertrag mehrt es für die Könige, die du um unserer Sünden willen über uns gesetzt hast; und sie schalten über unsere Leiber und über unser Vieh nach ihrem Wohlgefallen, und wir sind in großer Bedrängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'Und bei diesem allem machten und schrieben wir einen festen Bund; und auf der untersiegelten Schrift standen die Namen unserer Obersten, unserer Leviten und unserer Priester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Und auf der untersiegelten Schrift standen die Namen: Nehemia, der Tirsatha, der Sohn Hakaljas, und Zidkija. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Seraja, Asarja, Jeremia,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Paschchur, Amarja, Malkija,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hattusch, Schebanja, Malluk,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harim, Meremoth, Obadja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginnethon, Baruk,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Meschullam, Abija, Mijamin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maasja, Bilgai, Schemaja; das waren die Priester. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Und die Leviten, nämlich Jeschua, der Sohn Asanjas, Binnui, von den Söhnen Henadads, Kadmiel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'und ihre Brüder: Schebanja, Hodija, Kelita, Pelaja, Hanan,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Micha, Rechob, Haschabja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Sakkur, Scherebja, Schebanja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodija, Bani, Beninu. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Die Häupter des Volkes: Parhosch, Pachath-Moab, Elam, Sattu, Bani,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunni, Asgad, Bebai,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonija, Bigwai, Adin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Hiskija, Assur,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodija, Haschum, Bezai,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hariph, Anathoth, Nobai,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpiasch, Meschullam, Hesir,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Meschesabeel, Zadok, Jaddua,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatja, Hanan, Anaja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Hoschea, Hananja, Haschub,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hallochesch, Pilcha, Schobek,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rechum, Haschabna, Maaseja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'und Achija, Hanan, Anan,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Malluk, Harim, Baana.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Und das übrige Volk, die Priester, die Leviten, die Torhüter, die Sänger, die Nethinim, und alle, welche sich von den Völkern der Länder zu dem Gesetz Gottes abgesondert hatten, ihre Weiber, ihre Söhne und ihre Töchter, alle, die Erkenntnis und Einsicht hatten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'schlossen sich ihren Brüdern, den Vornehmen unter ihnen, an und traten in Eid und Schwur, nach den Gesetz Gottes, welches durch Mose, den Knecht Gottes, gegeben worden ist, zu wandeln und alle Gebote Jehovas, unseres Herrn, und seine Rechte und seine Satzungen zu beobachten und zu tun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'und daß wir unsere Töchter den Völkern des Landes nicht geben, noch ihre Töchter für unsere Söhne nehmen wollten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'und daß, wenn die Völker des Landes am Sabbathtage Waren und allerlei Getreide zum Verkauf brächten, wir es ihnen am Sabbath oder an einem anderen heiligen Tage nicht abnehmen wollten; und daß wir im siebten Jahre das Land brach liegen lassen und auf das Darlehn einer jeden Hand verzichten wollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Und wir verpflichteten uns dazu, uns den dritten Teil eines Sekels im Jahre für den Dienst des Hauses unseres Gottes aufzuerlegen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'für das Schichtbrot und das beständige Speisopfer, und für das beständige Brandopfer und für dasjenige der Sabbathe und der Neumonde, für die Feste und für die heiligen Dinge und für die Sündopfer, um Sühnung zu tun für Israel, und für alles Werk des Hauses unseres Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Und wir, die Priester, die Leviten und das Volk, warfen Lose über die Holzspende, um sie zum Hause unseres Gottes zu bringen, nach unseren Vaterhäusern, zu bestimmten Zeiten, Jahr für Jahr, zum Verbrennen auf dem Altar Jehovas, unseres Gottes, wie es in dem Gesetz vorgeschrieben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Und wir verpflichteten uns, die Erstlinge unseres Landes und die Erstlinge aller Früchte von allerlei Bäumen Jahr für Jahr zum Hause Jehovas zu bringen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'und die Erstgeborenen unserer Söhne und unseres Viehes, wie es in dem Gesetz vorgeschrieben ist; und die Erstgeborenen unserer Rinder und unseres Kleinviehes zum Hause unseres Gottes zu den Priestern zu bringen, welche den Dienst verrichten im Hause unseres Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Und den Erstling unseres Schrotmehls und unsere Hebopfer, und die Früchte von allerlei Bäumen, Most und Öl wollen wir den Priestern bringen in die Zellen des Hauses unseres Gottes; und den Zehnten unseres Landes den Leviten. Denn sie, die Leviten, sind es, welche den Zehnten erheben in allen Städten unseres Ackerbaues;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'und der Priester, der Sohn Aarons, soll bei den Leviten sein, wenn die Leviten den Zehnten erheben. Und die Leviten sollen den Zehnten vom Zehnten zum Hause unseres Gottes hinaufbringen, in die Zellen des Schatzhauses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Denn in die Zellen sollen die Kinder Israel und die Kinder Levi das Hebopfer vom Getreide, vom Most und Öl bringen; denn dort sind die heiligen Geräte und die Priester, welche den Dienst verrichten, und die Torhüter und die Sänger. Und so wollen wir das Haus unseres Gottes nicht verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Und die Obersten des Volkes wohnten in Jerusalem. Und das übrige Volk warf Lose, um je einen von zehn kommen zu lassen, damit er in Jerusalem, der heiligen Stadt, wohne, die neun anderen Teile aber in den Städten blieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Und das Volk segnete alle Männer, die sich freiwillig erboten, in Jerusalem zu wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Und dies sind die Häupter der Landschaft, welche in Jerusalem wohnten; in den Städten Judas aber wohnten, ein jeder in seinem Besitztum, in ihren Städten: Israel, die Priester und die Leviten und die Nethinim und die Söhne der Knechte Salomos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Und zwar wohnten in Jerusalem von den Söhnen Judas und von den Söhnen Benjamins; von den Söhnen Judas: Athaja, der Sohn Ussijas, des Sohnes Sekarjas, des Sohnes Amarjas, des Sohnes Schephatjas, des Sohnes Mahalalels, von den Söhnen Perez\';');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'und Maaseja, der Sohn Baruks, des Sohnes Kol-Hoses, des Sohnes Hasajas, des Sohnes Adajas, des Sohnes Jojaribs, des Sohnes Sekarjas, von den Schilonitern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Aller Söhne des Perez, die in Jerusalem wohnten, waren vierhundertachtundsechzig tapfere Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Und dies sind die Söhne Benjamins: Sallu, der Sohn Meschullams, des Sohnes Joeds, des Sohnes Pedajas, des Sohnes Kolajas, des Sohnes Maasejas, des Sohnes Ithiels, des Sohnes Jesajas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'und nach ihm Gabbai-Sallai, neunhundertachtundzwanzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Und Joel, der Sohn Sikris, war Aufseher über sie; und Juda, der Sohn Hassenuas, war über die Stadt als Zweiter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Von den Priestern: Jedaja, der Sohn des Jojarib, Jakin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraja, der Sohn Hilkijas, des Sohnes Meschullams, des Sohnes Zadoks, des Sohnes Merajoths, des Sohnes Ahitubs, Oberaufseher des Hauses Gottes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'und ihre Brüder, welche die Geschäfte im Hause verrichteten: achthundertzweiundzwanzig; und Adaja, der Sohn Jerochams, des Sohnes Pelaljas, des Sohnes Amzis, des Sohnes Sekarjas, des Sohnes Paschchurs, des Sohnes Malkijas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'und seine Brüder, Häupter von Vaterhäusern: zweihundertzweiundvierzig; und Amaschsai, der Sohn Asarels, des Sohnes Achsais, des Sohnes Meschillemoths, des Sohnes Immers,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'und ihre Brüder, tüchtige Männer: hundertachtundzwanzig. Und Aufseher über sie war Sabdiel, der Sohn Haggedolims. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Und von den Leviten: Schemaja, der Sohn Haschubs, des Sohnes Asrikams, des Sohnes Haschabjas, des Sohnes Bunnis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'und Schabbethai und Josabad, von den Häuptern der Leviten, welche über die äußeren Geschäfte des Hauses Gottes gesetzt waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'und Mattanja, der Sohn Michas, des Sohnes Sabdis, des Sohnes Asaphs, das Haupt; er stimmte den Lobgesang an beim Gebet; und Bakbukja, der Zweite, von seinen Brüdern; und Abda, der Sohn Schammuas, des Sohnes Galals, des Sohnes Jeduthuns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Aller Leviten in der heiligen Stadt waren zweihundertvierundachtzig. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Und die Torhüter: Akkub, Talmon und ihre Brüder, die in den Toren Wache hielten, hundertzweiundsiebzig. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, '(Und das übrige Israel, die Priester, die Leviten, waren in allen Städten Judas, ein jeder in seinem Erbteil. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Und die Nethinim wohnten auf dem Ophel; und Zicha und Gischpa waren über die Nethinim. -)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Und Aufseher der Leviten in Jerusalem war Ussi, der Sohn Banis, des Sohnes Haschabjas, des Sohnes Mattanjas, des Sohnes Michas, von den Söhnen Asaphs, den Sängern, für das Geschäft im Hause Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Denn ein Gebot des Königs war über sie ergangen, und eine Verpflichtung über die Sänger betreffs der täglichen Gebühr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Und Pethachja, der Sohn Meschesabeels, von den Söhnen Serachs, des Sohnes Judas, war zur Hand des Königs für alle Angelegenheiten des Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Und was die Dörfer auf ihren Feldern betrifft, so wohnten von den Kindern Juda in Kirjath-Arba und seinen Tochterstädten und in Dibon und seinen Tochterstädten und in Jekabzeel und seinen Dörfern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'und in Jeschua und in Molada und in Beth-Pelet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'und in Hazar-Schual und in Beerseba und seinen Tochterstädten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'und in Ziklag und in Mekona und in seinen Tochterstädten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'und in En-Rimmon und in Zora und in Jarmuth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Sanoach, Adullam und seinen Dörfern, Lachis und seinen Feldern, Aseka und seinen Tochterstädten. Und sie ließen sich nieder von Beerseba bis zum Tale Hinnom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Und die Kinder Benjamin wohnten von Geba an in Mikmas und Aija und Bethel und seinen Tochterstädten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'in Anathoth, Nob, Ananja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hazor, Rama, Gittaim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadid, Zeboim, Neballat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lod und Ono, dem Tale der Werkleute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Und von den Leviten gehörten Abteilungen von Juda zu Benjamin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Und dies sind die Priester und die Leviten, welche mit Serubbabel, dem Sohne Schealtiels, und Jeschua hinaufzogen: Seraja, Jeremia, Esra,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarja, Malluk, Hattusch,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Schekanja, Rechum, Meremoth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginnethoi, Abija,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamin, Maadja, Bilga,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Schemaja, und Jojarib, Jedaja,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amok, Hilkija, Jedaja. Das waren die Häupter der Priester und ihrer Brüder in den Tagen Jeschuas. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Und die Leviten: Jeschua, Binnui, Kadmiel, Scherebja, Juda, Mattanja; er und seine Brüder waren über den Lobgesang;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'und Bakbukja und Unni, ihre Brüder, standen ihnen gegenüber, den Dienstabteilungen gemäß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Und Jeschua zeugte Jojakim, und Jojakim zeugte Eljaschib, und Eljaschib zeugte Jojada,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'und Jojada zeugte Jonathan, und Jonathan zeugte Jaddua.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Und in den Tagen Jojakims waren Priester, Häupter der Väter: von Seraja: Meraja; von Jeremia: Hananja;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'von Esra: Meschullam; von Amarja: Jochanan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'von Meluki: Jonathan; von Schebanja: Joseph;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'von Harim: Adna; von Merajoth: Helkai;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'von Iddo: Sacharja; von Ginnethon: Meschullam;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'von Abija: Sikri; von Minjamin...;von Moadja: Piltai;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'von Bilga: Schammua; von Schemaja: Jonathan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'und von Jojarib: Mattenai; von Jedaja: Ussi;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'von Sallai: Kallai; von Amok: Heber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'von Hilkija: Haschabja; von Jedaja: Nethaneel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Von den Leviten wurden in den Tagen Eljaschibs, Jojadas und Jochanans und Jadduas die Häupter der Väter eingeschrieben, und von den Priestern, unter der Regierung Darius\', des Persers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Die Söhne Levis, die Häupter der Väter, sind in dem Buche der Chronika eingeschrieben, und zwar bis auf die Tage Jochanans, des Sohnes Eljaschibs. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Und die Häupter der Leviten waren Haschabja, Scherebja und Jeschua, der Sohn des Kadmiel, und ihre Brüder, die ihnen gegenüber standen, um zu loben und zu preisen, nach dem Gebote Davids, des Mannes Gottes, Abteilung gegenüber Abteilung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Mattanja und Bakbukja, Obadja, Meschullam, Talmon, Akkub hielten als Torhüter Wache bei den Vorratskammern der Tore. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Diese waren in den Tagen Jojakims, des Sohnes Jeschuas, des Sohnes Jozadaks, und in den Tagen Nehemias, des Landpflegers, und Esras, des Priesters, des Schriftgelehrten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Und bei der Einweihung der Mauer von Jerusalem suchte man die Leviten aus allen ihren Orten, daß man sie nach Jerusalem brächte, um die Einweihung zu feiern mit Freuden, und mit Lobliedern und mit Gesang, mit Zimbeln, Harfen und Lauten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Da versammelten sich die Söhne der Sänger, sowohl aus dem Kreise in der Umgebung von Jerusalem als auch aus den Dörfern der Netophathiter');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'und aus Beth-Gilgal und aus den Gefilden von Geba und Asmaweth; denn die Sänger hatten sich in der Umgebung von Jerusalem Dörfer gebaut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Und die Priester und die Leviten reinigten sich; und sie reinigten das Volk und die Tore und die Mauer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Und ich ließ die Obersten von Juda oben auf die Mauer steigen; und ich stellte zwei große Dankchöre und Züge auf. Der eine zog zur Rechten, oben auf der Mauer, zum Misttore hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Und hinter ihnen her gingen Hoschaja und die Hälfte der Obersten von Juda,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'und zwar Asarja, Esra und Meschullam,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda und Benjamin, und Schemaja und Jeremia;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'und von den Söhnen der Priester mit Trompeten: Sekarja, der Sohn Jonathans, des Sohnes Schemajas, des Sohnes Mattanjas, des Sohnes Mikajas, des Sohnes Sakkurs, des Sohnes Asaphs;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'und seine Brüder: Schemaja und Asarel, Milalai, Gilalai, Maai, Nethaneel und Juda, Hanani, mit den Musikinstrumenten Davids, des Mannes Gottes; und Esra, der Schriftgelehrte, vor ihnen her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Und sie zogen zum Quelltore; und sie stiegen gerade vor sich hin auf den Stufen der Stadt Davids den Aufgang der Mauer hinauf, und zogen an dem Hause Davids vorüber und bis an das Wassertor gegen Osten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Und der zweite Dankchor zog nach der entgegengesetzten Seite, und ich und die Hälfte des Volkes ging hinter ihm her, ober auf der Mauer, an dem Ofenturm vorüber und bis an die breite Mauer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'und an dem Tore Ephraim und dem Tore der alten Mauer und dem Fischtore und dem Turme Hananeel und dem Turme Mea vorüber und bis an das Schaftor; und sie blieben beim Gefängnistore stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Und beide Dankchöre stellten sich am Hause Gottes auf; und ich und die Hälfte der Vorsteher mit mir,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'und die Priester Eljakim, Maaseja, Minjamin, Mikaja, Eljoenai, Sekarja, Hananja, mit Trompeten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'und Maaseja und Schemaja und Eleasar und Ussi und Jochanan und Malkija und Elam und Eser. Und die Sänger ließen ihre Stimme erschallen, und Jisrachja war ihr Vorsteher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Und sie opferten an selbigem Tage große Schlachtopfer und freuten sich, denn Gott hatte ihnen große Freude gegeben; und auch die Weiber und die Kinder freuten sich. Und die Freude Jerusalems wurde bis in die Ferne hin gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Und es wurden an selbigem Tage Männer bestellt über die Vorratskammern für die Hebopfer, für die Erstlinge und für die Zehnten, um von den Feldern der Städte die gesetzlichen Teile für die Priester und für die Leviten darein zu sammeln; denn Juda hatte Freude an den Priestern und an den Leviten, welche dastanden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Und sie warteten der Hut ihres Gottes und der Hut der Reinigung; und so auch die Sänger und die Torhüter, nach dem Gebote Davids und seines Sohnes Salomo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Denn vor alters, in den Tagen Davids und Asaphs, gab es Häupter der Sänger, und Preis-und Lobgesänge für Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Und ganz Israel gab in den Tagen Serubbabels und in den Tagen Nehemias die Teile der Sänger und der Torhüter, den täglichen Bedarf; das Geheiligte aber gaben sie den Leviten, und die Leviten gaben das Geheiligte den Söhnen Aarons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'An selbigem Tage wurde in dem Buche Moses vor den Ohren des Volkes gelesen; und es fand sich darin geschrieben, daß kein Ammoniter und Moabiter in die Versammlung Gottes kommen sollte ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'weil sie den Kindern Israel nicht mit Brot und mit Wasser entgegen gekommen waren, und Bileam wider sie gedungen hatten, um sie zu verfluchen; aber unser Gott wandelte den Fluch in Segen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Und es geschah, als sie das Gesetz hörten, da sonderten sie alles Mischvolk von Israel ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Und vor diesem hatte Eljaschib, der Priester, der über die Zellen des Hauses unseres Gottes gesetzt war, ein Verwandter des Tobija,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'diesem eine große Zelle gemacht, wohin man vordem die Speisopfer legte, den Weihrauch und die Geräte und den Zehnten vom Getreide, Most und Öl, das für die Leviten und die Sänger und die Torhüter Gebotene, und die Hebopfer der Priester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Während diesem allem war ich aber nicht in Jerusalem; denn im zweiunddreißigsten Jahre Artasastas, des Königs von Babel, war ich zu dem König zurückgekommen. Und nach Verlauf einer Zeit erbat ich mir Urlaub von dem König;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'und als ich nach Jerusalem kam, bemerkte ich das Böse, welches Eljaschib zugunsten Tobijas getan, indem er ihm eine Zelle in den Höfen des Hauses Gottes gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Und es mißfiel mir sehr, und ich warf alle Hausgeräte Tobijas aus der Zelle hinaus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'und ich befahl, daß man die Zellen reinigen sollte; und ich brachte die Geräte des Hauses Gottes, das Speisopfer und den Weihrauch wieder hinein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Und ich erfuhr, daß die Teile der Leviten nicht gegeben worden, und daß die Leviten und die Sänger, welche das Werk taten, entflohen waren, ein jeder auf sein Feld.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Da zankte ich mit den Vorstehern und sprach: Warum ist das Haus Gottes verlassen worden? Und ich versammelte sie und stellte sie an ihre Stelle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Und ganz Juda brachte den Zehnten vom Getreide und Most und Öl in die Vorratskammern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Und ich bestellte zu Schatzmeistern über die Vorräte: Schelemja, den Priester, und Zadok, den Schreiber, und Pedaja, von den Leviten, und ihnen zur Seite Hanan, den Sohn Sakkurs, des Sohnes Mattanjas; denn sie wurden für treu geachtet, und ihnen lag es ob, ihren Brüdern auszuteilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Gedenke meiner um dessentwillen, mein Gott, und tilge nicht aus meine guten Taten, die ich am Hause meines Gottes und an dessen Hut erwiesen habe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'In jenen Tagen sah ich einige in Juda, welche am Sabbath die Keltern traten, und Garben einbrachten und auf Esel luden, und auch Wein, Trauben und Feigen und allerlei Last, und es am Sabbathtage nach Jerusalem hereinbrachten; und ich zeugte wider sie an dem Tage, da sie die Lebensmittel verkauften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Auch Tyrer wohnten darin, welche Fische und allerlei Waren hereinbrachten und sie am Sabbath den Kindern Juda und in Jerusalem verkauften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Da zankte ich mit den Edlen von Juda und sprach zu ihnen: Was ist das für eine böse Sache, die ihr tut, daß ihr den Sabbathtag entheiliget?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Haben nicht eure Väter ebenso getan, so daß unser Gott all dieses Unglück über uns und über diese Stadt brachte? Und ihr mehret die Zornglut über Israel, indem ihr den Sabbath entheiliget!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Und es geschah, sowie es in den Toren Jerusalems vor dem Sabbath dunkel wurde, da befahl ich, daß die Türen geschlossen würden; und ich befahl, daß man sie nicht auftun sollte bis nach dem Sabbath. Und ich bestellte einige von meinen Dienern über die Tore, damit keine Last am Sabbathtage hereinkäme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Da übernachteten die Krämer und die Verkäufer von allerlei Ware draußen vor Jerusalem einmal und zweimal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Und ich zeugte wider sie und sprach zu ihnen: Warum übernachtet ihr vor der Mauer? Wenn ihr es wieder tut, werde ich Hand an euch legen! Von dieser Zeit an kamen sie nicht mehr am Sabbath.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Und ich befahl den Leviten, daß sie sich reinigen und kommen sollten, die Tore zu bewachen, um den Sabbathtag zu heiligen. Auch das gedenke mir, mein Gott, und schone meiner nach der Größe deiner Güte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Auch besuchte ich in jenen Tagen die Juden, welche asdoditische, ammonitische und moabitische Weiber heimgeführt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Und die Hälfte ihrer Kinder redete asdoditisch und wußte nicht jüdisch zu reden, sondern redete nach der Sprache des einen oder anderen Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Und ich zankte mit ihnen und fluchte ihnen, und schlug einige Männer von ihnen und raufte sie. Und ich beschwor sie bei Gott: Wenn ihr eure Töchter ihren Söhnen geben werdet, und wenn ihr von ihren Töchtern für eure Söhne und für euch nehmen werdet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Hat nicht Salomo, der König von Israel, ihretwegen gesündigt? Und seinesgleichen ist unter den vielen Nationen kein König gewesen; und er war geliebt von seinem Gott, und Gott setzte ihn zum König über ganz Israel; doch ihn machten die fremden Weiber sündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Und sollten wir auf euch hören, daß ihr all dieses große Übel tut, treulos zu handeln gegen unseren Gott, indem ihr fremde Weiber heimführet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Und einer von den Söhnen Jojadas, des Sohnes Eljaschibs, des Hohenpriesters, war ein Schwiegersohn Sanballats, des Horoniters; und ich jagte ihn von mir weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Gedenke es ihnen, mein Gott, wegen der Verunreinigungen des Priestertums und des Bundes des Priestertums und der Leviten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Und so reinigte ich sie von allem Fremden, und ich stellte die Dienstleistungen der Priester und der Leviten fest, für einen jeden in seinem Geschäft,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'und für die Holzspende zu bestimmten Zeiten und für die Erstlinge. Gedenke es mir, mein Gott, zum Guten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Und es geschah in den Tagen des Ahasveros (das ist der Ahasveros, der von Indien bis Äthiopien über hundertsiebenundzwanzig Landschaften regierte),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'in selbigen Tagen, als der König Ahasveros auf dem Throne seines Königreiches saß, der in der Burg Susan war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'im dritten Jahre seiner Regierung, da machte er ein Gastmahl allen seinen Fürsten und Knechten, indem die Mächtigen von Persien und Medien, die Vornehmen und Fürsten der Landschaften vor ihm waren,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'als er den herrlichen Reichtum seines Königreiches und die glänzende Pracht seiner Größe viele Tage lang, hundertachtzig Tage, sehen ließ.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Und als diese Tage erfüllt waren, machte der König allem Volke, das sich in der Burg Susan befand, vom Größten bis zum Kleinsten, ein Gastmahl von sieben Tagen, im Hofe des Gartens des königlichen Palastes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Weiße und purpurblaue baumwollene Vorhänge waren befestigt mit Schnüren von Byssus und Purpur an silbernen Ringen und weißen Marmorsäulen; Polster von Gold und Silber lagen auf einem Pflaster von grünem und weißem Marmor und Perlmutterstein und schwarzem Marmor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Und man reichte das Getränk in goldenen Gefäßen, und die Gefäße waren von einander verschieden; und königlichen Wein gab es in Menge, nach der Freigebigkeit des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Und das Trinken geschah dem Befehle gemäß ohne Zwang; denn also hatte der König allen Obersten seines Hauses verordnet, daß sie tun sollten nach jedermanns Belieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Auch die Königin Vasti machte ein Gastmahl für die Weiber im königlichen Hause des Königs Ahasveros.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Am siebten Tage, als das Herz des Königs vom Weine fröhlich war, befahl er Mehuman, Bistha, Harbona, Bigtha und Abagtha, Sethar und Karkas, den sieben Kämmerern, welche vor dem König Ahasveros dienten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'die Königin Vasti mit der königlichen Krone vor den König zu bringen, um den Völkern und Fürsten ihre Schönheit zu zeigen; denn sie war schön von Ansehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Aber die Königin Vasti weigerte sich, auf das Wort des Königs zu kommen, welches ihr durch die Kämmerer überbracht wurde. Da erzürnte der König sehr, und sein Zorn entbrannte in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Und der König sprach zu den Weisen, welche sich auf die Zeiten verstanden (denn also wurden die Angelegenheiten des Königs vor allen Gesetz-und Rechtskundigen behandelt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'und die Nächsten bei ihm waren Karschna, Schethar, Admatha, Tharsis, Meres, Marsna, Memukan, die sieben Fürsten von Persien und Medien, welche das Angesicht des Königs sahen, die den ersten Sitz im Königreiche hatten):');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Was ist nach dem Gesetz mit der Königin Vasti zu tun, dafür daß sie das Wort des Königs Ahasveros durch die Kämmerer nicht befolgt hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Da sprach Memukan vor dem König und den Fürsten: Nicht an dem König allein hat sich die Königin Vasti vergangen, sondern auch an allen Fürsten und an allen Völkern, die in allen Landschaften des Königs Ahasveros wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Denn das Verhalten der Königin wird zu allen Weibern auskommen, so daß ihre Männer verächtlich sein werden in ihren Augen, indem sie sagen werden: Der König Ahasveros befahl, die Königin Vasti vor ihn zu bringen, aber sie kam nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Und an diesem Tage schon werden die Fürstinnen von Persien und Medien, welche das Verhalten der Königin erfahren haben, davon reden zu allen Fürsten des Königs; und es wird Verachtung und Zorn genug geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Wenn es den König gut dünkt, so gehe ein königliches Wort von ihm aus und werde geschrieben in die Gesetze der Perser und Meder, daß es nicht vergehe: nämlich daß Vasti nicht mehr vor den König Ahasveros komme, und daß der König ihre königliche Würde einer anderen gebe, die besser ist als sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Und wird man den Befehl des Königs, den er erlassen wird, in seinem ganzen Königreiche hören, denn es ist groß, so werden alle Weiber ihren Männern Ehre geben, vom Größten bis zum Kleinsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Und das Wort gefiel dem König und den Fürsten; und der König tat nach dem Worte Memukans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Und er sandte Briefe in alle Landschaften des Königs, in jede Landschaft nach ihrer Schrift, und an jedes Volk nach seiner Sprache: daß jeder Mann Herr in seinem Hause sein und nach der Sprache seines Volkes reden solle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Nach diesen Begebenheiten, als der Zorn des Königs Ahasveros sich gelegt hatte, gedachte er an Vasti und an das, was sie getan, und was über sie beschlossen worden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Da sprachen die Diener des Königs, die ihn bedienten: Man suche dem König Mädchen, die Jungfrauen sind und schön von Ansehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'und der König bestellte Beamte in allen Landschaften seines Königreiches, damit sie alle Mädchen, die Jungfrauen sind und schön von Ansehen, nach der Burg Susan in das Frauenhaus zusammenbringen unter die Aufsicht Heges, des königlichen Kämmerers, des Hüters der Frauen; und man gebe ihnen Reinigungssalben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Und das Mädchen, welches dem König gefallen wird, werde Königin an Vastis Statt. Und das Wort gefiel dem König; und er tat also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Es war ein jüdischer Mann in der Burg Susan, sein Name war Mordokai, der Sohn Jairs, des Sohnes Simeis, des Sohnes Kis\', ein Benjaminiter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'der aus Jerusalem weggeführt worden war mit den Weggeführten, die mit Jekonja, dem König von Juda, weggeführt wurden, welche Nebukadnezar, der König von Babel, weggeführt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Und er erzog Hadassa, das ist Esther, die Tochter seines Oheims; denn sie hatte weder Vater noch Mutter. Und das Mädchen war schön von Gestalt und schön von Angesicht. Und als ihr Vater und ihre Mutter gestorben waren, hatte Mordokai sie als seine Tochter angenommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Und es geschah, als das Wort des Königs und sein Befehl gehört, und als viele Mädchen in die Burg Susan unter die Aufsicht Hegais zusammengebracht wurden, da wurde auch Esther in das Haus des Königs aufgenommen, unter die Aufsicht Hegais, des Hüters der Frauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Und das Mädchen gefiel ihm und erlangte Gunst vor ihm. Und er beeilte sich, ihre Reinigungssalben und ihre Teile ihr zu geben, und ihr die sieben Mägde zu geben, welche aus dem Hause des Königs ausersehen waren; und er versetzte sie mit ihren Mägden in die besten Gemächer des Frauenhauses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Esther hatte ihr Volk und ihre Abstammung nicht kundgetan; denn Mordokai hatte ihr geboten, daß sie es nicht kundtun sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Und Tag für Tag wandelte Mordokai vor dem Hofe des Frauenhauses, um das Wohlergehen Esthers zu erfahren, und was mit ihr geschähe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Und wenn die Reihe an ein jedes Mädchen kam, zum König Ahasveros zu kommen, nachdem ihr zwölf Monate lang nach der Vorschrift für die Weiber geschehen war (denn also wurden die Tage ihrer Reinigung erfüllt, nämlich sechs Monate mit Myrrhenöl, und sechs Monate mit Gewürzen und mit Reinigungssalben der Weiber),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'und wenn alsdann das Mädchen zu dem König kam, so wurde ihr alles gegeben, was sie verlangte, um es aus dem Frauenhause in das Haus des Königs mitzunehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Am Abend kam sie, und am Morgen kehrte sie in das zweite Frauenhaus zurück, unter die Aufsicht Schaaschgas\', des königlichen Kämmerers, des Hüters der Kebsweiber. Sie kam nicht wieder zu dem König, es sei denn, daß der König Gefallen an ihr hatte, und sie mit Namen gerufen wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Und als die Reihe an Esther kam, die Tochter Abichails, des Oheims Mordokais, welche er als seine Tochter angenommen hatte, daß sie zu dem König kommen sollte, verlangte sie nichts, außer was Hegai, der königliche Kämmerer, der Hüter der Frauen, sagte. Und Esther erlangte Gnade in den Augen aller, die sie sahen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Und Esther wurde zu dem König Ahasveros in sein königliches Haus geholt im zehnten Monat, das ist der Monat Tebeth, im siebten Jahre seiner Regierung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Und der König gewann Esther lieb, mehr als alle Weiber, und sie erlangte Gnade und Gunst vor ihm, mehr als alle die Jungfrauen. Und er setzte die königliche Krone auf ihr Haupt und machte sie zur Königin an Vastis Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Und der König machte allen seinen Fürsten und Knechten ein großes Gastmahl, das Gastmahl Esthers; und er gab den Landschaften einen Steuererlaß und gab Geschenke nach der Freigebigkeit des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Und als zum zweiten Male Jungfrauen zusammengebracht wurden, und Mordokai im Tore des Königs saß');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, '(Esther tat ihre Abstammung und ihr Volk nicht kund, wie Mordokai ihr geboten hatte; und Esther tat, was Mordokai sagte, wie zur Zeit, da sie bei ihm erzogen wurde),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'in selbigen Tagen, als Mordokai im Tore des Königs saß, ergrimmten Bigthan und Teresch, zwei Kämmerer des Königs, von denen, welche die Schwelle hüteten, und trachteten danach, Hand an den König Ahasveros zu legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Und die Sache wurde dem Mordokai kund, und er berichtete es der Königin Esther; und Esther sagte es dem König im Namen Mordokais.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Und die Sache wurde untersucht und wahr gefunden; und sie wurden beide an ein Holz gehängt. Und es wurde vor dem König in das Buch der Chroniken eingeschrieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Nach diesen Begebenheiten machte der König Ahasveros Haman, den Sohn Hammedathas, den Agagiter, groß, und er erhob ihn und setzte seinen Stuhl über alle Fürsten, die bei ihm waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Und alle Knechte des Königs, die im Tore des Königs waren, beugten sich und warfen sich nieder vor Haman; denn also hatte der König seinetwegen geboten. Aber Mordokai beugte sich nicht und warf sich nicht nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Da sprachen die Knechte des Königs, die im Tore des Königs waren, zu Mordokai: Warum übertrittst du des Königs Gebot?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Und es geschah, als sie es Tag für Tag zu ihm sagten, und er nicht auf sie hörte, so berichteten sie es Haman, um zu sehen, ob die Worte Mordokais bestehen würden; denn er hatte ihnen kundgetan, daß er ein Jude wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Und als Haman sah, daß Mordokai sich nicht vor ihm beugte und niederwarf, da ward Haman voll Grimmes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Aber er war in seinen Augen verächtlich, die Hand an Mordokai allein zu legen; denn man hatte ihm das Volk Mordokais kundgetan. Und Haman suchte alle Juden, die im ganzen Königreiche des Ahasveros waren, das Volk Mordokais, zu vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Im ersten Monat, das ist der Monat Nisan, im zwölften Jahre des Königs Ahasveros, warf man das Pur, das ist das Los, vor Haman, von Tag zu Tag und von Monat zu Monat, bis zum zwölften Monat, das ist der Monat Adar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Und Haman sprach zu dem König Ahasveros: Da ist ein Volk, zerstreut und abgesondert unter den Völkern in allen Landschaften deines Königreiches; und ihre Gesetze sind von denen jedes anderen Volkes verschieden, und die Gesetze des Königs tun sie nicht; und es ist für den König nicht geziemend, sie gewähren zu lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Wenn es den König gut dünkt, so werde geschrieben, daß man sie umbringe; und ich will zehntausend Talente Silber in die Hände derer darwägen, welche die Geschäfte besorgen, daß sie es in die Schatzkammern des Königs bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Da zog der König seinen Siegelring von seiner Hand und gab ihn Haman, dem Sohne Hammedathas, dem Agagiter, dem Widersacher der Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Und der König sprach zu Haman: Das Silber sei dir gegeben, und das Volk, um mit ihm zu tun, wie es gut ist in deinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Da wurden die Schreiber des Königs berufen im ersten Monat, am dreizehnten Tage desselben; und es wurde nach allem, was Haman gebot, an die Satrapen des Königs geschrieben, und an die Landpfleger über jede Landschaft und an die Fürsten eines jeden Volkes, nach der Schrift jeder einzelnen Landschaft und nach der Sprache jedes einzelnen Volkes; es wurde geschrieben im Namen des Königs Ahasveros und mit dem Siegelringe des Königs untersiegelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Und die Briefe wurden durch die Eilboten in alle Landschaften des Königs gesandt, um alle Juden zu vertilgen, zu ermorden und umzubringen, vom Knaben bis zum Greise, Kinder und Weiber, an einem Tage, am Dreizehnten des zwölften Monats, das ist der Monat Adar, und um ihre Habe zu plündern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Und auf daß der Befehl in jeder einzelnen Landschaft erlassen würde, ward eine Abschrift des Schreibens allen Völkern bekannt gemacht, damit sie auf diesen Tag bereit wären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Die Eilboten zogen auf das Wort des Königs eilends aus. Und der Befehl wurde in der Burg Susan erlassen. Und der König und Haman saßen und tranken; aber die Stadt Susan war in Bestürzung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Und als Mordokai alles erfuhr, was geschehen war, da zerriß Mordokai seine Kleider und legte Sacktuch an und Asche; und er ging hinaus in die Stadt und erhob ein lautes und bitterliches Geschrei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Und er kam bis vor das Tor des Königs; denn zum Tore des Königs durfte man nicht in einem Sackkleide eingehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Und in jeder einzelnen Landschaft, überall wohin das Wort des Königs und sein Befehl gelangte, war eine große Trauer bei den Juden, und Fasten und Weinen und Wehklage; viele saßen auf Sacktuch und Asche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Und die Mägde Esthers und ihre Kämmerer kamen und taten es ihr kund. Da geriet die Königin sehr in Angst. Und sie sandte Kleider, daß man sie Mordokai anziehe und sein Sacktuch von ihm wegnehme; aber er nahm sie nicht an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Da rief Esther Hathak, einen von den Kämmerern des Königs, den er zu ihrem Dienste bestellt hatte, und entbot ihn an Mordokai, um zu erfahren, was das wäre, und warum es wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Da ging Hathak zu Mordokai hinaus auf den Platz der Stadt, der vor dem Tore des Königs lag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Und Mordokai berichtete ihm alles, was ihm begegnet war, und den Betrag des Silbers, welches Haman versprochen hatte, in die Schatzkammern des Königs für die Juden darzuwägen, um sie umzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Auch gab er ihm eine Abschrift des in Susan erlassenen schriftlichen Befehles, sie zu vertilgen: um sie der Esther zu zeigen und ihr kundzutun, und um ihr zu gebieten, daß sie zu dem König hineingehe, ihn um Gnade anzuflehen und für ihr Volk vor ihm zu bitten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Und Hathak kam und berichtete der Esther die Worte Mordokais.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Da sprach Esther zu Hathak und entbot ihn an Mordokai:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Alle Knechte des Königs und das Volk der Landschaften des Königs wissen, daß für einen jeden, Mann und Weib, der zu dem König in den inneren Hof hineingeht, ohne daß er gerufen wird, ein Gesetz gilt, nämlich daß er getötet werde; denjenigen ausgenommen, welchem der König das goldene Zepter entgegenreicht, daß er am Leben bleibe; ich aber bin seit nunmehr dreißig Tagen nicht gerufen worden, um zu dem König hineinzugehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Und man berichtete Mordokai die Worte Esthers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Und Mordokai ließ der Esther antworten: Denke nicht in deinem Herzen, daß du im Hause des Königs allein vor allen Juden entkommen werdest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Denn wenn du in dieser Zeit irgend schweigst, so wird Befreiung und Errettung für die Juden von einem anderen Orte her erstehen; du aber und deines Vaters Haus, ihr werdet umkommen. Und wer weiß, ob du nicht für eine Zeit, wie diese, zum Königtum gelangt bist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Da ließ Esther dem Mordokai antworten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Gehe hin, versammle alle Juden, die sich in Susan befinden; und fastet meinethalben, und esset nicht und trinket nicht drei Tage lang, Nacht und Tag; auch ich werde mit meinen Mägden ebenso fasten. Und alsdann will ich zu dem König hineingehen, was nicht nach dem Gesetz ist; und wenn ich umkomme, so komme ich um!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Und Mordokai ging hin und tat nach allem, was Esther ihm geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Und es geschah am dritten Tage, da kleidete sich Esther königlich und trat in den inneren Hof des Hauses des Königs, dem Hause des Königs gegenüber. Und der König saß auf seinem königlichen Throne im königlichen Hause, dem Eingang des Hauses gegenüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Und es geschah, als der König die Königin Esther im Hofe stehen sah, erlangte sie Gnade in seinen Augen; und der König reichte Esther das goldene Zepter entgegen, das in seiner Hand war; und Esther nahte herzu und rührte die Spitze des Zepters an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Und der König sprach zu ihr: Was ist dir, Königin Esther? Und was ist dein Begehr? Bis zur Hälfte des Königreiches, und sie soll dir gegeben werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Und Esther sprach: Wenn es den König gut dünkt, so möge der König und Haman heute zu dem Mahle kommen, das ich ihm bereitet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Da sprach der König: Bringet eilends Haman her, damit wir tun, was Esther gesagt hat. Und der König und Haman kamen zu dem Mahle, das Esther bereitet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Und der König sprach zu Esther beim Weingelage: Was ist deine Bitte? Und sie soll dir gewährt werden. Und was ist dein Begehr? Bis zur Hälfte des Königreiches, und es soll geschehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Da antwortete Esther und sprach: Meine Bitte und mein Begehr ist:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Wenn ich Gnade gefunden habe in den Augen des Königs, und wenn es den König gut dünkt, meine Bitte zu gewähren und mein Begehr zu tun, so möge der König und Haman zu dem Mahle kommen, das ich ihnen bereiten will; und morgen will ich tun nach dem Worte des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Und Haman ging an selbigem Tage hinaus, fröhlich und guten Mutes. Als aber Haman den Mordokai im Tore des Königs sah, und daß er weder aufstand, noch sich vor ihm rührte, da ward Haman voll Grimmes über Mordokai; aber Haman bezwang sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Und als er in sein Haus gekommen war, sandte er hin und ließ seine Freunde und sein Weib Seresch kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Und Haman erzählte ihnen von der Herrlichkeit seines Reichtums und von der Menge seiner Söhne; und alles, wie der König ihn groß gemacht, und wie er ihn erhoben habe über die Fürsten und Knechte des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Und Haman sprach: Auch hat die Königin Esther niemand mit dem König zu dem Mahle kommen lassen, das sie bereitet hatte, als nur mich; und auch auf morgen bin ich mit dem König von ihr geladen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Aber dieses alles gilt mir nichts, solange ich Mordokai, den Juden, im Tore des Königs sitzen sehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Da sprachen sein Weib Seresch und alle seine Freunde zu ihm: Man richte einen Baum her, fünfzig Ellen hoch; und am Morgen sage dem König, daß man Mordokai daran hänge. Dann gehe mit dem König fröhlich zum Mahle! Und das Wort dünkte Haman gut, und er ließ den Baum herrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'In jener Nacht floh dem König der Schlaf; und er befahl, das Gedächtnisbuch der Chroniken zu bringen; und sie wurden vor dem König gelesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Da fand sich geschrieben, daß Mordokai über Bigthana und Teresch, die beiden Kämmerer des Königs, von denen, welche die Schwelle hüteten, berichtet hatte, daß sie danach getrachtet hätten, Hand an den König Ahasveros zu legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Und der König sprach: Welche Ehre und Auszeichnung ist dem Mordokai dafür erwiesen worden? Und die Diener des Königs, die ihn bedienten, sprachen: Es ist ihm nichts erwiesen worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Da sprach der König: Wer ist im Hofe? Und Haman war eben in den äußeren Hof des Königshauses gekommen, um dem König sagen, man möge Mordokai an den Baum hängen, welchen er für ihn bereitet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Und die Diener des Königs sprachen zu ihm: Siehe, Haman steht im Hofe. Und der König sprach: Er komme herein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Und Haman kam herein. Und der König sprach zu ihm: Was ist dem Manne zu tun, an dessen Ehre der König Gefallen hat? Da dachte Haman in seinem Herzen: Wem anders als mir sollte der König Gefallen haben, Ehre zu erweisen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Und Haman sprach zu dem König: Der Mann, an dessen Ehre der König Gefallen hat-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'man bringe ein königliches Kleid, womit der König sich bekleidet, und das Roß, auf welchem der König reitet, und auf dessen Kopf die königliche Krone gesetzt wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'und man übergebe das Kleid und das Roß den Händen eines der vornehmsten Fürsten des Königs; und man bekleide den Mann, an dessen Ehre der König Gefallen hat, und man lasse ihn auf dem Rosse durch die Straßen der Stadt reiten und rufe vor ihm her: Also wird dem Manne getan, an dessen Ehre der König Gefallen hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Da sprach der König zu Haman: Eile, nimm das Kleid und das Roß, wie du gesagt hast, und tue so mit Mordokai, dem Juden, der im Tore des Königs sitzt; laß nichts ausfallen von allem, was du gesagt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Und Haman nahm das Kleid und das Roß, und er bekleidete Mordokai, und ließ ihn durch die Straßen der Stadt reiten und rief vor ihm her: Also wird dem Manne getan, an dessen Ehre der König Gefallen hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Und Mordokai kehrte zum Tore des Königs zurück. Haman aber eilte nach seinem Hause, traurig und mit verhülltem Haupte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Und Haman erzählte seinem Weibe Seresch und allen seinen Freunden alles, was ihm begegnet war. Da sprachen seine Weisen und sein Weib Seresch zu ihm: Wenn Mordokai, vor dem du zu fallen angefangen hast, vom Samen der Juden ist, so wirst du nichts gegen ihn vermögen, sondern du wirst gänzlich vor ihm fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Während sie noch mit ihm redeten, kamen die Kämmerer des Königs herbei und führten Haman eilends zu dem Mahle, das Esther bereitet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Und der König und Haman kamen zum Gelage bei der Königin Esther.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Und der König sprach zu Esther auch am zweiten Tage beim Weingelage: Was ist deine Bitte, Königin Esther? Und sie soll dir gewährt werden. Und was ist dein Begehr? Bis zur Hälfte des Königreiches, und es soll geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Da antwortete die Königin Esther und sprach: Wenn ich Gnade gefunden habe in deinen Augen, o König, und wenn es den König gut dünkt, so möge mir mein Leben geschenkt werden um meiner Bitte willen, und mein Volk um meines Begehrs willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Denn wir sind verkauft, ich und mein Volk, um vertilgt, ermordet und umgebracht zu werden; und wenn wir zu Knechten und Mägden verkauft worden wären, so hätte ich geschwiegen, obgleich der Bedränger nicht imstande wäre, den Schaden des Königs zu ersetzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Da sprach der König Ahasveros und sagte zu der Königin Esther: Wer ist der, und wo ist der, welchen sein Herz erfüllt hat, also zu tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Und Esther sprach: Der Bedränger und Feind ist dieser böse Haman! Da erschrak Haman vor dem König und der Königin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Und der König stand in seinem Grimme auf von dem Weingelage und ging in den Garten des Palastes. Haman aber blieb zurück, um bei der Königin Esther für sein Leben zu bitten; denn er sah, daß das Unglück gegen ihn beschlossen war von seiten des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Und als der König aus dem Garten des Palastes in das Haus des Weingelages zurückkam, da war Haman auf das Polster gesunken, auf welchem Esther saß. Da sprach der König: Will er gar der Königin Gewalt antun bei mir im Hause? Das Wort ging aus dem Munde des Königs, da verhüllte man das Angesicht Hamans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Und Harbona, einer von den Kämmerern, die vor dem König standen, sprach: Auch siehe, der Baum, welchen Haman für Mordokai hat machen lassen, der Gutes für den König geredet hat, steht im Hause Hamans, fünfzig Ellen hoch. Und der König sprach: Hänget ihn daran!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Und man hängte Haman an den Baum, welchen er für Mordokai bereitet hatte. Und der Grimm des Königs legte sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'An selbigem Tage gab der König Ahasveros der Königin Esther das Haus Hamans, des Widersachers der Juden. Und Mordokai kam vor den König, denn Esther hatte ihm kundgetan, was er ihr wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Und der König zog seinen Siegelring ab, den er Haman weggenommen hatte, und gab ihn Mordokai. Und Esther setzte Mordokai über das Haus Hamans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Und Esther redete wiederum vor dem König und fiel zu seinen Füßen nieder; und sie weinte und flehte ihn an, die Bosheit Hamans, des Agagiters, abzuwenden und seinen Anschlag, den er wider die Juden ersonnen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Und der König reichte Esther das goldene Zepter entgegen. Da erhob sich Esther und stand vor dem König; und sie sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Wenn es den König gut dünkt, und wenn ich Gnade vor ihm gefunden habe, und die Sache vor dem König recht ist und ich ihm wohlgefällig bin, so werde geschrieben, die Briefe zu widerrufen, nämlich den Anschlag Hamans, des Sohnes Hammedathas, des Agagiters, die er geschrieben hat, um die Juden umzubringen, welche in allen Landschaften des Königs sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Denn wie vermöchte ich das Unglück anzusehen, das mein Volk treffen wird? Und wie vermöchte ich den Untergang meines Geschlechtes anzusehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Und der König Ahasveros sprach zu der Königin Esther und zu Mordokai, dem Juden: Siehe, das Haus Hamans habe ich Esther gegeben, und ihn hat man an das Holz gehängt, darum daß er seine Hand an die Juden gelegt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'So schreibet ihr nun im Namen des Königs betreffs der Juden, wie es euch gut dünkt, und untersiegelt es mit dem Siegelringe des Königs. Denn eine Schrift, die im Namen des Königs geschrieben und mit dem Siegelringe des Königs untersiegelt ist, kann nicht widerrufen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Da wurden die Schreiber des Königs gerufen zu selbiger Zeit, im dritten Monat, das ist der Monat Siwan, am Dreiundzwanzigsten desselben; und es wurde nach allem, was Mordokai gebot, an die Juden geschrieben, und an die Satrapen und die Landpfleger und die Fürsten der Landschaften, die von Indien bis Äthiopien waren, hundertsiebenundzwanzig Landschaften, nach der Schrift jeder einzelnen Landschaft und nach der Sprache jedes einzelnen Volkes; und auch an die Juden nach ihrer Schrift und nach ihrer Sprache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Und er schrieb im Namen des Königs Ahasveros und untersiegelte mit dem Siegelringe des Königs; und er sandte durch die berittenen Eilboten, welche auf den Rennern der königlichen Gestüte ritten, Briefe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'worin geschrieben stand, daß der König den Juden, die in jeder einzelnen Stadt wären, gestattet habe, sich zu versammeln und für ihr Leben einzustehen, zu vertilgen, zu töten und umzubringen alle Heeresmacht von Volk und Landschaft, die sie, ihre Kinder und Weiber bedrängen würden, und ihre Habe zu plündern:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'an einem Tage in allen Landschaften des Königs Ahasveros, am dreizehnten Tage des zwölften Monats, das ist der Monat Adar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Und auf daß der Befehl in jeder einzelnen Landschaft erlassen würde, ward eine Abschrift des Schreibens allen Völkern bekannt gemacht, und zwar damit die Juden auf diesen Tag bereit wären, sich an ihren Feinden zu rächen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Die Eilboten, welche auf den königlichen Rennern ritten, zogen auf das Wort des Königs schleunig und eilends aus. Und der Befehl wurde in der Burg Susan erlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Und Mordokai ging von dem König hinaus in königlicher Kleidung von prupurblauer und weißer Baumwolle, und mit einer großen goldenen Krone, und in einem Mantel von Byssus und Purpur; und die Stadt Susan jauchzte und war fröhlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Den Juden war Licht und Freude und Wonne und Ehre zuteil geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Und in jeder einzelnen Landschaft und in jeder einzelnen Stadt, überall wohin das Wort des Königs und sein Befehl gelangte, war Freude und Wonne bei den Juden, Gastmahl und Festtag. Und viele aus den Völkern des Landes wurden Juden, denn die Furcht vor den Juden war auf sie gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Und im zwölften Monat, das ist der Monat Adar, am dreizehnten Tage desselben, als das Wort des Königs und sein Befehl zur Ausführung kommen sollte, an dem Tage, da die Feinde der Juden gehofft hatten, sie zu überwältigen (es wandte sich aber, so daß sie, die Juden, ihre Hasser überwältigten),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'da versammelten sich die Juden in ihren Städten, in allen Landschaften des Königs Ahasveros, um Hand an diejenigen zu legen, welche ihr Unglück suchten. Und niemand konnte vor ihnen bestehen, denn die Furcht vor ihnen war auf alle Völker gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Und alle Fürsten der Landschaften und die Satrapen und die Landpfleger und diejenigen, welche die Geschäfte des Königs besorgten, unterstützten die Juden; denn die Furcht vor Mordokai war auf sie gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Denn Mordokai war groß im Hause des Königs, und sein Ruf ging durch alle Landschaften; denn der Mann Mordokai wurde immerfort größer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Und die Juden richteten unter allen ihren Feinden eine Niederlage an, indem sie sie erstachen, ermordeten und umbrachten; und sie taten an ihren Hassern nach ihrem Wohlgefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Und in der Burg Susan töteten die Juden und brachten um fünfhundert Mann;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'und sie töteten Parschandatha und Dalphon und Aspatha');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'und Poratha und Adalja und Aridatha');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'und Parmaschtha und Arisai und Aridai und Wajesatha,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'die zehn Söhne Hamans, des Sohnes Hammedathas, des Widersachers der Juden; aber an die Beute legten sie ihre Hand nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'An selbigem Tage kam die Zahl der in der Burg Susan Getöteten vor den König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Und der König sprach zu der Königin Esther: In der Burg Susan haben die Juden fünfhundert Mann und die zehn Söhne Hamans getötet und umgebracht; was mögen sie in den übrigen Landschaften des Königs getan haben! Doch was ist deinen Bitte? und sie soll dir gewährt werden. Und was ist noch dein Begehr? und es soll geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Und Esther sprach: Wenn es den König gut dünkt, so werde auch morgen den Juden, die in Susan sind, gestattet, nach dem heutigen Befehle zu tun; und die zehn Söhne Hamans hänge man an das Holz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Da befahl der König, daß also geschehen sollte; und der Befehl wurde zu Susan erlassen, und man hängte die zehn Söhne Hamans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Und die Juden, die in Susan waren, versammelten sich auch am vierzehnten Tage des Monats Adar und töteten in Susan dreihundert Mann; aber an die Beute legten sie ihre Hand nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Und die übrigen Juden, die in den Landschaften des Königs waren, versammelten sich und standen für ihr Leben ein und erhielten Ruhe vor ihren Feinden; und sie töteten unter ihren Hassern fünfundsiebzigtausend; aber an die Beute legten sie ihre Hand nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Das geschah am dreizehnten Tage des Monats Adar; und am Vierzehnten des Monats ruhten sie, und sie machten ihn zu einem Tage des Gastmahls und der Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Aber die Juden, die in Susan waren, hatten sich am Dreizehnten des Monats und des Vierzehnten des Monats versammelt; und sie ruhten am Fünfzehnten des Monats und machten ihn zu einem Tage des Gastmahls und der Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Darum feiern die Juden des platten Landes, die in den offenen Städten wohnen, den vierzehnten Tag des Monats Adar als einen Tag der Freude und des Gastmahls, und als einen Festtag, wo man einander Teile sendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Und Mordokai schrieb diese Begebenheiten auf. Und er sandte Briefe an alle Juden, in allen Landschaften des Königs Ahasveros, die nahen und die fernen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'um ihnen festzusetzen, daß sie den vierzehnten Tag des Monats Adar und den fünfzehnten Tag desselben Jahr für Jahr feiern sollten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'als die Tage, an welchen die Juden Ruhe erlangt hatten vor ihren Feinden, und als den Monat, wo sich ihnen Kummer in Freude, und Trauer in einen Festtag verwandelt hatte, daß sie dieselben feiern sollten als Tage des Gastmahls und der Freude, wo man einander Teile sendet und Geschenke an die Armen gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Und die Juden nahmen als Brauch an, was sie zu tun angefangen, und was Mordokai ihnen geschrieben hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Denn Haman, der Sohn Hammedathas, der Agagiter, der Widersacher aller Juden, hatte gegen die Juden den Anschlag ersonnen, sie umzubringen, und hatte das Pur, das ist das Los, geworfen, um sie zu vertilgen und sie umzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Und als es vor den König kam, befahl er durch einen Brief, daß sein böser Anschlag, den er gegen die Juden ersonnen hatte, auf seinen Kopf zurückkehre; und man hängte ihn und seine Söhne an das Holz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Darum nannte man diese Tage Purim, nach dem Namen des Pur. Deshalb, wegen all der Worte dieses Briefes, sowohl dessen, was sie selbst davon gesehen hatten, als auch was zu ihnen gelangt war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'setzten die Juden fest und nahmen auf sich und auf ihre Nachkommen und auf alle, die sich ihnen anschlossen, als eine ewige Satzung, diese beiden Tage zu feiern, nach dem, was darüber geschrieben worden war, und nach ihrer bestimmten Zeit, Jahr für Jahr;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'und daß diese Tage im Andenken bleiben und gefeiert werden sollten in jedem einzelnen Geschlecht, in jeder einzelnen Familie, in jeder einzelnen Landschaft und in jeder einzelnen Stadt; und daß diese Purimtage unter den Juden nicht untergehen, und ihr Andenken nicht aufhören sollte bei ihren Nachkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Und die Königin Esther, die Tochter Abichails, und Mordokai, der Jude, schrieben mit allem Nachdruck, um diesen zweiten Brief über die Purim festzusetzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Und er sandte Briefe an alle Juden, in die hundersiebenundzwanzig Landschaften, das Königreich Ahasveros\', Worte des Friedens und der Wahrheit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'um diese Purimtage in ihren bestimmten Zeiten festzusetzen, so wie Mordokai, der Jude, und die Königin Esther es ihnen festgesetzt hatten, und wie sie es für sich selbst und für ihre Nachkommen festgesetzt hatten, nämlich die Angelegenheit der Fasten und ihrer Wehklage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Und der Befehl Esthers setzte diese Purim-Angelegenheit fest, und er wurde in ein Buch geschrieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Und der König Ahasveros legte dem Lande und den Inseln des Meeres eine Abgabe auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Und alle Taten seiner Gewalt und seiner Macht und die Beschreibung der Größe Mordokais, zu welcher der König ihn erhob, sind sie nicht geschrieben in dem Buche der Chroniken der Könige der Meder und Perser?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Denn Mordokai, der Jude, war der Zweite nach dem König Ahasveros, und groß bei den Juden, und wohlgefällig der Menge seiner Brüder; er suchte das Wohl seines Volkes und redete zur Wohlfahrt seines ganzen Geschlechts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Es war Mann im Lande Uz, sein Name war Hiob; und selbiger Mann war vollkommen und rechtschaffen und gottesfürchtig und das Böse meidend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Und es wurden ihm sieben Söhne und drei Töchter geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Und sein Besitztum bestand in siebentausend Schafen und dreitausend Kamelen und fünfhundert Joch Rindern und fünfhundert Eselinnen, und in sehr vielem Gesinde. Und selbiger Mann war größer als alle Söhne des Ostens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Und seine Söhne gingen hin und machten in dem Hause eines jeden ein Gastmahl an seinem Tage; und sie sandten hin und luden ihre drei Schwestern ein, um mit ihnen zu essen und zu trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Und es geschah, wenn die Tage des Gastmahls herum waren, so sandte Hiob hin und heiligte sie; und er stand des Morgens früh auf und opferte Brandopfer nach ihrer aller Zahl; denn Hiob sprach: Vielleicht haben meine Kinder gesündigt und sich in ihrem Herzen von Gott losgesagt. Also tat Hiob allezeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Und es geschah eines Tages, da kamen die Söhne Gottes, um sich vor Jehova zu stellen; und auch der Satan kam in ihrer Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Und Jehova sprach zum Satan: Wo kommst du her? Und der Satan antwortete Jehova und sprach: Vom Durchstreifen der Erde und vom Umherwandeln auf ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Und Jehova sprach zum Satan: Hast du achtgehabt auf meinen Knecht Hiob? Denn seinesgleichen ist kein Mann auf Erden, vollkommen und rechtschaffen, gottesfürchtig und das Böse meidend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Und der Satan antwortete Jehova und sprach: Ist es umsonst, daß Hiob Gott fürchtet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Hast du nicht selbst ihn und sein Haus und alles, was er hat, ringsum eingezäunt? Du hast das Werk seiner Hände gesegnet, und sein Besitztum hat sich ausgebreitet im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Aber strecke einmal deine Hand aus und taste alles an, was er hat, ob er sich nicht offen von dir lossagen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Da sprach Jehova zum Satan: Siehe, alles, was er hat, ist in deiner Hand; nur nach ihm strecke deine Hand nicht aus. Und der Satan ging von dem Angesicht Jehovas hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Und es geschah eines Tages, als seine Söhne und seine Töchter im Hause ihres erstgeborenen Bruders aßen und Wein tranken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'da kam ein Bote zu Hiob und sprach: Die Rinder pflügten, und die Eselinnen weideten neben ihnen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'da fielen Sabäer ein und nahmen sie weg, und die Knechte erschlugen sie mit der Schärfe des Schwertes; und ich bin entronnen, nur ich allein, um es dir zu berichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Dieser redete noch, da kam ein anderer und sprach: Feuer Gottes ist vom Himmel gefallen und hat das Kleinvieh und die Knechte verbrannt und sie verzehrt; und ich bin entronnen, nur ich allein, um es dir zu berichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Dieser redete noch, da kam ein anderer und sprach: Die Chaldäer haben drei Haufen gebildet und sind über die Kamele hergefallen und haben sie weggenommen, und die Knechte haben sie mit der Schärfe des Schwertes erschlagen; und ich bin entronnen, nur ich allein, um es dir zu berichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Während dieser noch redete, da kam ein anderer und sprach: Deine Söhne und deine Töchter aßen und tranken Wein im Hause ihres erstgeborenen Bruders;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'und siehe, ein starker Wind kam von jenseit der Wüste her und stieß an die vier Ecken des Hauses, und es fiel auf die jungen Leute, und sie starben; und ich bin entronnen, nur ich allein, um es dir zu berichten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Da stand Hiob auf und zerriß sein Gewand und schor sein Haupt; und er fiel zur Erde nieder und betete an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Und er sprach: Nackt bin ich aus meiner Mutter Leibe gekommen, und nackt werde ich dahin zurückkehren; Jehova hat gegeben, und Jehova hat genommen, der Name Jehovas sei gepriesen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Bei diesem allem sündigte Hiob nicht und schrieb Gott nichts Ungereimtes zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Und es geschah eines Tages, da kamen die Söhne Gottes, um sich vor Jehova zu stellen; und auch der Satan kam in ihrer Mitte, um sich vor Jehova zu stellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Und Jehova sprach zum Satan: Von woher kommst du? Und der Satan antwortete Jehova und sprach: Vom Durchstreifen der Erde und vom Umherwandeln auf ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Und Jehova sprach zum Satan: Hast du achtgehabt auf meinen Knecht Hiob? Denn seinesgleichen ist kein Mann auf Erden, vollkommen und rechtschaffen, gottesfürchtig und das Böse meidend; und noch hält er fest an seiner Vollkommenheit, wiewohl du mich wider ihn gereizt hast, ihn ohne Ursache zu verschlingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Und der Satan antwortete Jehova und sprach: Haut um Haut, ja, alles, was der Mensch hat, gibt er um sein Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Aber strecke einmal deine Hand aus und taste sein Gebein und sein Fleisch an, ob er sich nicht offen von dir lossagen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Und Jehova sprach zum Satan: Siehe, er ist in deiner Hand; nur schone seines Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Und der Satan ging von dem Angesicht Jehovas hinweg, und er schlug Hiob mit bösen Geschwüren, von seiner Fußsohle bis zu seinem Scheitel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Und er nahm einen Scherben, um sich damit zu schaben; und er saß mitten in der Asche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Da sprach sein Weib zu ihm: Hältst du noch fest an deiner Vollkommenheit? Sage dich los von Gott und stirb!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Und er sprach zu ihr: Du redest, wie eine der Törinnen redet. Wir sollten das Gute von Gott annehmen, und das Böse sollten wir nicht auch annehmen? Bei diesem allem sündigte Hiob nicht mit seinen Lippen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Und die drei Freunde Hiobs hörten all dieses Unglück, das über ihn gekommen war; und sie kamen, ein jeder aus seinem Orte: Eliphas, der Temaniter, und Bildad, der Schuchiter, und Zophar, der Naamathiter; und sie verabredeten sich miteinander zu kommen, um ihm ihr Beileid zu bezeugen und ihn zu trösten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Und sie erhoben ihre Augen von ferne und erkannten ihn nicht; da erhoben sie ihre Stimme und weinten, und sie zerrissen ein jeder sein Gewand und streuten Staub auf ihre Häupter himmelwärts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Und sie saßen mit ihm auf der Erde sieben Tage und sieben Nächte lang; und keiner redete ein Wort zu ihm, denn sie sahen, daß der Schmerz sehr groß war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Danach tat Hiob seinen Mund auf und verfluchte seinen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Und Hiob hob an und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Es verschwinde der Tag, an dem ich geboren wurde, und die Nacht, welche sprach: Ein Knäblein ist empfangen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Jener Tag sei Finsternis! Nicht frage Gott nach ihm droben, und nicht erglänze über ihm das Licht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Finsternis und Todesschatten mögen ihn einlösen, Gewölk lagere sich über ihm, es schrecken ihn Tagesverfinsterungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Jene Nacht, Dunkel ergreife sie; sie freue sich nicht unter den Tagen des Jahres, in die Zahl der Monde komme sie nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Siehe, jene Nacht sei unfruchtbar, es trete kein Jubel in sie ein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Verwünschen mögen sie die Verflucher des Tages, die fähig sind, den Leviathan aufzureizen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Verfinstert seien die Sterne ihrer Dämmerung; sie harre auf Licht, und da sei keines; und nicht schaue sie die Wimpern der Morgenröte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Denn sie hat die Pforte meines Mutterschoßes nicht verschlossen und Mühsal nicht verborgen vor meinen Augen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Warum starb ich nicht von Mutterleibe an, kam aus dem Schoße hervor und verschied?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Weshalb kamen Knie mir entgegen, und wozu Brüste, daß ich sog?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Denn jetzt würde ich liegen und rasten, ich würde schlafen: dann hätte ich Ruhe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'mit Königen und Räten der Erde, welche sich verödete Plätze erbauten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'oder mit Fürsten, die Gold hatten, die ihre Häuser mit Silber füllten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'oder, gleich einer verborgenen Fehlgeburt, wäre ich nicht da, gleich Kindern, die das Licht nicht erblickt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Dort lassen die Bösen ab vom Toben, und dort ruhen die an Kraft Erschöpften,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'rasten die Gefangenen allesamt, hören nicht die Stimme des Treibers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Der Kleine und der Große, dort sind sie gleich, und der Knecht ist frei von seinem Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Warum gibt er dem Mühseligen Licht, und Leben denen, die bitterer Seele sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'die auf den Tod harren, und er ist nicht da, und die nach ihm graben, mehr als nach verborgenen Schätzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'die sich freuen bis zum Jubel, Wonne haben, wenn sie das Grab finden; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'dem Manne, dessen Weg ihm verborgen ist, und den Gott eingeschlossen hat ringsum?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Denn gleich meinem Brote kommt mein Seufzen, und wie Wasser ergießt sich mein Gestöhn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Denn ich fürchtete einen Schrecken, und er traf mich, und vor dem mir bangte, das kam über mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Ich war nicht ruhig, und ich rastete nicht und ruhte nicht, da kam das Toben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Und Eliphas, der Temaniter, antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Wenn man ein Wort an dich versucht, wird es dich verdrießen? Doch die Worte zurückzuhalten, wer vermöchte es?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Siehe, du hast viele unterwiesen, und erschlaffte Hände stärktest du;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'den Strauchelnden richteten deine Worte auf, und sinkende Knie hast du befestigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Doch nun kommt es an dich, und es verdrießt dich; es erreicht dich, und du bist bestürzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Ist nicht deine Gottesfurcht deine Zuversicht, die Vollkommenheit deiner Wege deine Hoffnung?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Gedenke doch: Wer ist als Unschuldiger umgekommen, und wo sind Rechtschaffene vertilgt worden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'So wie ich es gesehen habe: die Unheil pflügen und Mühsal säen, ernten es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Durch den Odem Gottes kommen sie um, und durch den Hauch seiner Nase vergehen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Das Brüllen des Löwen und des Brüllers Stimme sind verstummt, und die Zähne der jungen Löwen sind ausgebrochen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'der Löwe kommt um aus Mangel an Raub, und die Jungen der Löwin werden zerstreut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Und zu mir gelangte verstohlen ein Wort, und mein Ohr vernahm ein Geflüster davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'In Gedanken, welche Nachtgesichte hervorrufen, wenn tiefer Schlaf die Menschen befällt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'kam Schauer über mich und Beben, und durchschauerte alle meine Gebeine;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'und ein Geist zog vor meinem Angesicht vorüber, das Haar meines Leibes starrte empor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Es stand da, und ich erkannte sein Aussehen nicht; ein Bild war vor meinen Augen, ein Säuseln und eine Stimme hörte ich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Sollte ein Mensch gerechter sein als Gott, oder ein Mann reiner als der ihn gemacht hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Siehe, auf seine Knechte vertraut er nicht, und seinen Engeln legt er Irrtum zur Last:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'wieviel mehr denen, die in Lehmhäusern wohnen, deren Grund im Staube ist! Wie Motten werden sie zertreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Von Morgen bis Abend werden sie zerschmettert; ohne daß man\'s beachtet, kommen sie um auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Ist es nicht so? Wird ihr Zeltstrick an ihnen weggerissen, so sterben sie, und nicht in Weisheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Rufe doch, ob einer da ist, der dir antwortet! Und an welchen der Heiligen willst du dich wenden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Denn den Narren erwürgt der Gram, und den Einfältigen tötet der Eifer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Ich, ich sah den Narren Wurzel schlagen, und alsbald verwünschte ich seine Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Fern blieben seine Kinder vom Glück; und sie wurden im Tore zertreten, und kein Erretter war da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Seine Ernte verzehrte der Hungrige, und bis aus den Dornhecken nahm er sie weg; und nach ihrem Vermögen schnappte die Schlinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Denn nicht aus dem Staube geht Unheil hervor, und nicht sproßt Mühsal aus dem Erdboden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'sondern der Mensch ist zur Mühsal geboren, wie die Funken sich erheben im Fluge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Ich jedoch würde Gott suchen und Gott meine Sache darlegen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'der Großes und Unerforschliches tut, Wunder bis zur Unzahl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'der Regen gibt auf die Fläche der Erde, und Wasser sendet auf die Fläche der Flur;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'um Niedrige in die Höhe zu setzen, und Trauernde steigen empor zum Glück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Der zunichte macht die Anschläge der Listigen, und ihre Hände führen den Plan nicht aus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'der die Weisen erhascht in ihrer List, und der Verschmitzten Rat überstürzt sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Bei Tage stoßen sie auf Finsternis, und am Mittag tappen sie wie bei der Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Und er rettet vom Schwerte, von ihrem Munde, und aus der Hand des Starken den Dürftigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'So wird dem Armen Hoffnung, und die Ungerechtigkeit verschließt ihren Mund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Siehe, glückselig der Mensch, den Gott straft! So verwirf denn nicht die Züchtigung des Allmächtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Denn er bereitet Schmerz und verbindet, er zerschlägt, und seine Hände heilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'In sechs Drangsalen wird er dich erretten, und in sieben wird dich kein Übel antasten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'In Hungersnot erlöst er dich von dem Tode, und im Kriege von der Gewalt des Schwertes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Vor der Zunge Geißel wirst du geborgen sein, und du wirst dich nicht fürchten vor der Verwüstung, wenn sie kommt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Der Verwüstung und des Hungers wirst du lachen, und vor dem Getier der Erde wirst du dich nicht fürchten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'denn dein Bund wird mit den Steinen des Feldes sein, und das Getier des Feldes wird Frieden mit dir haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Und du wirst erfahren, daß dein Zelt in Frieden ist, und überschaust du deine Wohnung, so wirst du nichts vermissen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'und du wirst erfahren, daß deine Nachkommenschaft zahlreich sein wird, und deine Sprößlinge gleich dem Kraut der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Du wirst in Rüstigkeit in das Grab kommen, wie der Garbenhaufen eingebracht wird zu seiner Zeit. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Siehe, dieses, wir haben es erforscht, so ist es; höre es, und du, merke es dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Und Hiob antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'O daß mein Gram doch gewogen würde, und man mein Mißgeschick auf die Waagschale legte allzumal!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Denn dann würde es schwerer sein als der Sand der Meere; darum sind unbesonnen meine Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Denn die Pfeile des Allmächtigen sind in mir, ihr Gift trinkt mein Geist; die Schrecken Gottes stellen sich in Schlachtordnung wider mich auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Schreit ein Wildesel beim Grase, oder brüllt ein Rind bei seinem Futter?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Wird Fades, Salzloses gegessen? Oder ist Geschmack im Eiweiß?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Was meine Seele sich weigerte anzurühren, das ist wie meine ekle Speise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'O daß doch meine Bitte einträfe, und Gott mein Verlangen gewährte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'daß es Gott gefiele, mich zu zermalmen, daß er seine Hand losmachte und mich vernichtete!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'So würde noch mein Trost sein, und ich würde frohlocken in schonungsloser Pein, daß ich die Worte des Heiligen nicht verleugnet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Was ist meine Kraft, daß ich ausharren, und was mein Ende, daß ich mich gedulden sollte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Ist Kraft der Steine meine Kraft, oder ist mein Fleisch von Erz?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Ist es nicht also, daß keine Hilfe in mir, und jede Kraft aus mir vertrieben ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Dem Verzagten gebührt Milde von seinem Freunde, sonst wird er die Furcht des Allmächtigen verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Meine Brüder haben sich trügerisch erwiesen wie ein Wildbach, wie das Bett der Wildbäche, welche hinschwinden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'welche trübe sind von Eis, in die der Schnee sich birgt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Zur Zeit, wenn sie erwärmt werden, versiegen sie; wenn es heiß wird, sind sie von ihrer Stelle verschwunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Es schlängeln sich die Pfade ihres Laufes, ziehen hinauf in die Öde und verlieren sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Es blickten hin die Karawanen Temas, die Reisezüge Schebas hofften auf sie:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'sie wurden beschämt, weil sie auf sie vertraut hatten, sie kamen hin und wurden zu Schanden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Denn jetzt seid ihr zu nichts geworden; ihr sehet einen Schrecken und fürchtet euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Habe ich etwa gesagt: Gebet mir, und machet mir ein Geschenk von eurem Vermögen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'und befreiet mich aus der Hand des Bedrängers, und erlöset mich aus der Hand der Gewalttätigen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Belehret mich, und ich will schweigen; und gebet mir zu erkennen, worin ich geirrt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Wie eindringlich sind richtige Worte! Aber was tadelt der Tadel, der von euch kommt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Gedenket ihr Reden zu tadeln? Für den Wind sind ja die Worte eines Verzweifelnden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Sogar den Verwaisten würdet ihr verlosen, und über euren Freund einen Handel abschließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Und nun, laßt es euch gefallen, auf mich hinzublicken: euch ins Angesicht werde ich doch wahrlich nicht lügen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Kehret doch um, es geschehe kein Unrecht; ja, kehret noch um, um meine Gerechtigkeit handelt es sich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Ist Unrecht auf meiner Zunge? Oder sollte mein Gaumen Frevelhaftes nicht unterscheiden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Hat der Mensch nicht einen harten Dienst auf Erden, und sind seine Tage nicht wie die Tage eines Tagelöhners?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Wie ein Knecht, der sich nach dem Schatten sehnt, und wie ein Tagelöhner, der seines Lohnes harrt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'so sind mir zuteil geworden Monde der Nichtigkeit, und Nächte der Mühsal mir zugezählt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Wenn ich mich niederlege, so spreche ich: Wann werde ich aufstehen? Und der Abend dehnt sich hin, und ich werde des Umherwerfens satt bis zur Dämmerung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Mein Fleisch ist bekleidet mit Gewürm und Erdkrusten, meine Haut zieht sich zusammen und eitert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Meine Tage gleiten schneller dahin als ein Weberschiffchen, und schwinden ohne Hoffnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Gedenke, daß mein Leben ein Hauch ist! Nicht wird mein Auge das Glück wiedersehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Nicht mehr wird mich schauen das Auge des mich Sehenden; richtest du deine Augen auf mich, so bin ich nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Die Wolke schwindet und fährt dahin; so steigt, wer in den Scheol hinabfährt, nicht wieder herauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Nicht mehr kehrt er zurück zu seinem Hause, und seine Stätte erkennt ihn nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'So will auch ich meinen Mund nicht zurückhalten, will reden in der Bedrängnis meines Geistes, will klagen in der Bitterkeit meiner Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Bin ich ein Meer, oder ein Seeungeheuer, daß du eine Wache wider mich aufstellst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Wenn ich sage: Trösten wird mich mein Bett, mein Lager wird tragen helfen meine Klage,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'so erschreckst du mich mit Träumen, und durch Gesichte ängstigst du mich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'so daß meine Seele Erstickung vorzieht, den Tod lieber wählt als meine Gebeine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Ich bin\'s überdrüssig, nicht ewiglich werde ich ja leben: Laß ab von mir! Denn ein Hauch sind meine Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Was ist der Mensch, daß du ihn hochhältst, und daß du dein Herz auf ihn richtest,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'und alle Morgen ihn heimsuchst, alle Augenblicke ihn prüfst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Wie lange willst du nicht von mir wegblicken, nicht von mir ablassen, bis ich meinen Speichel verschlucke?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Habe ich gesündigt, was tat ich dir an, du Beobachter der Menschen? Warum hast du mich dir zum Angriffspunkt gesetzt, daß ich mir selbst zur Last geworden bin?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Und warum vergibst du nicht meine Übertretung und lässest nicht vorübergehen meine Missetat? Denn nun werde ich in den Staub mich legen, und suchst du nach mir, so bin ich nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Und Bildad, der Schuchiter, antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Wie lange willst du solches reden, und sollen die Worte deines Mundes ungestümer Wind sein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Wird Gott das Recht beugen, oder wird der Allmächtige beugen die Gerechtigkeit?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Wenn deine Kinder gegen ihn gesündigt haben, so gab er sie ihrer Übertretung preis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Wenn du Gott eifrig suchst und zu dem Allmächtigen um Gnade flehst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'wenn du lauter und rechtschaffen bist, ja, dann wird er zu deinen Gunsten aufwachen und Wohlfahrt geben der Wohnung deiner Gerechtigkeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'und dein Anfang wird gering erscheinen, aber dein Ende sehr groß werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Denn befrage doch das vorige Geschlecht, und richte deinen Sinn auf das, was ihre Väter erforscht haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, '(Denn wir sind von gestern und wissen nichts, denn ein Schatten sind unsere Tage auf Erden.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Werden jene dich nicht belehren, dir\'s sagen, und Worte aus ihrem Herzen hervorbringen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Schießt Papierschilf auf, wo kein Sumpf ist? Wächst Riedgras empor ohne Wasser?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Noch ist es am Grünen, wird nicht ausgerauft, so verdorrt es vor allem Grase.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Also sind die Pfade aller, die Gottes vergessen; und des Ruchlosen Hoffnung geht zu Grunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Sein Vertrauen wird abgeschnitten, und seine Zuversicht ist ein Spinnengewebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Er stützt sich auf sein Haus, und es hält nicht stand; er hält sich daran fest, und es bleibt nicht aufrecht. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Saftvoll ist er vor der Sonne, und seine Schößlinge dehnen sich aus über seinen Garten hin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'über Steinhaufen schlingen sich seine Wurzeln, er schaut die Wohnung der Steine;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'wenn er ihn wegreißt von seiner Stätte, so verleugnet sie ihn: \"Ich habe dich nie gesehen!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Siehe, das ist die Freude seines Weges; und aus dem Staube sprossen andere hervor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Siehe, Gott wird den Vollkommenen nicht verwerfen, und nicht bei der Hand fassen die Übeltäter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Während er deinen Mund mit Lachen füllen wird und deine Lippen mit Jubelschall,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'werden deine Hasser bekleidet werden mit Scham, und das Zelt der Gesetzlosen wird nicht mehr sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Und Hiob antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Wahrlich, ich weiß, daß es also ist; und wie könnte ein Mensch gerecht sein vor Gott?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Wenn er Lust hat, mit ihm zu rechten, so kann er ihm auf tausend nicht eins antworten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Er ist weise von Herzen und stark an Kraft: wer hat sich wider ihn verhärtet und ist unversehrt geblieben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Der Berge versetzt, ehe sie es merken, er, der sie umkehrt in seinem Zorn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'der die Erde aufbeben macht von ihrer Stätte, und ihre Säulen erzittern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'der der Sonne befiehlt, und sie geht nicht auf, und der die Sterne versiegelt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'der die Himmel ausspannt, er allein, und einherschreitet auf den Höhen des Meeres;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'der den großen Bären gemacht hat, den Orion und das Siebengestirn und die Kammern des Südens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'der Großes tut, daß es nicht zu erforschen, und Wundertaten, daß sie nicht zu zählen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Siehe, er geht an mir vorüber, und ich sehe ihn nicht, und er zieht vorbei, und ich bemerke ihn nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Siehe, er rafft dahin, und wer will ihm wehren? Wer zu ihm sagen: Was tust du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Gott wendet seinen Zorn nicht ab, unter ihn beugen sich Rahabs Helfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Wieviel weniger könnte ich ihm antworten, meine Worte wählen ihm gegenüber!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Der ich, wenn ich gerecht wäre, nicht antworten könnte, um Gnade würde ich flehen zu meinem Richter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Wenn ich riefe, und er mir antwortete, nicht würde ich glauben, daß er meiner Stimme Gehör schenken würde:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Er, der mich zermalmt durch ein Sturmwetter, und meine Wunden mehrt ohne Ursache;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'er erlaubt mir nicht, Atem zu holen, denn er sättigt mich mit Bitterkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Wenn es auf Kraft des Starken ankommt, so sagt er: \"Siehe hier!\" und wenn auf Recht: \"Wer will mich vorladen?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Wenn ich auch gerecht wäre, so würde mein Mund mich doch verdammen; wäre ich vollkommen, so würde er mich für verkehrt erklären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Vollkommen bin ich; nicht kümmert mich meine Seele, ich verachte mein Leben; es ist eins!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Darum sage ich: Den Vollkommenen und den Gesetzlosen vernichtet er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Wenn die Geißel plötzlich tötet, so spottet er der Prüfung der Unschuldigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Die Erde ist in die Hand des Gesetzlosen gegeben, das Angesicht ihrer Richter verhüllt er. Wenn er es nun nicht ist, wer anders?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Und meine Tage eilen schneller dahin als ein Läufer, sie entfliehen, schauen das Glück nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Sie ziehen vorüber gleich Rohrschiffen, wie ein Adler, der auf Fraß herabstürzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Wenn ich sage: Ich will meine Klage vergessen, will mein Angesicht glätten und mich erheitern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'so bangt mir vor allen meinen Schmerzen; ich weiß, daß du mich nicht für schuldlos halten wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Ich muß schuldig sein; wozu soll ich mich denn nutzlos abmühen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Wenn ich mich mit Schnee wüsche und meine Hände mit Lauge reinigte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'alsdann würdest du mich in die Grube tauchen, und meinen eigenen Kleidern würde vor mir ekeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Denn er ist nicht ein Mann wie ich, daß ich ihm antworten dürfte, daß wir miteinander vor Gericht gehen könnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Es gibt zwischen uns keinen Schiedsmann, daß er seine Hand auf uns beide legte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Er tue seine Rute von mir weg, und sein Schrecken ängstige mich nicht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'so will ich reden und ihn nicht fürchten; denn nicht also steht es bei mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Meine Seele ist meines Lebens überdrüssig; ich will meiner Klage in mir freien Lauf lassen, will reden in der Bitterkeit meiner Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Ich will zu Gott sagen: Verdamme mich nicht! laß mich wissen, worüber du mit mir rechtest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Gefällt es dir, daß du bedrückst, daß du die Arbeit deiner Hände verwirfst und über den Rat der Gesetzlosen dein Licht leuchten lässest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Hast du Augen des Fleisches, oder siehst du, wie ein Mensch sieht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Sind deine Tage wie die Tage eines Menschen, oder deine Jahre wie die Tage eines Mannes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'daß du nach meiner Ungerechtigkeit suchst und nach meiner Sünde forschest,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'obwohl du weißt, daß ich nicht schuldig bin, und daß niemand ist, der aus deiner Hand errette?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Deine Hände haben mich ganz gebildet und gestaltet um und um, und du verschlingst mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Gedenke doch, daß du wie Ton mich gestaltet und zum Staube willst du mich zurückkehren lassen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Hast du mich nicht hingegossen wie Milch, und wie Käse mich gerinnen lassen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Mit Haut und Fleisch hast du mich bekleidet, und mit Knochen und Sehnen mich durchflochten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Leben und Huld hast du mir gewährt, und deine Obhut bewahrte meinen Geist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Doch solches bargest du in deinem Herzen; ich weiß, daß dieses bei dir war:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Wenn ich sündigte, so würdest du mich beobachten, und von meiner Missetat mich nicht freisprechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Wenn ich schuldig wäre, wehe mir! Und wäre ich gerecht, so dürfte ich mein Haupt nicht erheben, gesättigt von Schande und mein Elend schauend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Und richtete es sich empor, wie ein Löwe würdest du mich jagen, und immer wieder deine Wunderkraft an mir erweisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Du würdest deine Zeugen mir gegenüber erneuern und deinen Zorn wider mich mehren, stets frische Scharen und ein Heer wider mich entbieten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Warum hast du mich doch aus Mutterleibe hervorgehen lassen? Ich hätte verscheiden, und kein Auge hätte mich sehen sollen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Als ob ich nicht gewesen wäre, so hätte ich sein sollen, vom Mutterschoße zu Grabe getragen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Sind meiner Tage nicht wenige? Er lasse ab, wende sich von mir, daß ich ein wenig mich erheitere,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'ehe ich hingehe (und nicht wiederkomme) in das Land der Finsternis und des Todesschattens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'in das Land, düster wie das Dunkel, das Land des Todesschattens und der Unordnung, und wo das Hellwerden dem Dunkel gleich ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Und Zophar, der Naamathiter, antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Sollte die Menge der Worte nicht beantwortet werden, oder sollte ein Schwätzer recht behalten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Sollte dein Gerede die Leute zum Schweigen bringen, daß du spotten solltest, und niemand dich beschämen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'daß du sagen solltest: Meine Lehre ist lauter, und ich bin rein in deinen Augen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Aber möchte Gott doch reden und seine Lippen gegen dich öffnen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'und dir kundtun die Geheimnisse der Weisheit, daß sie das Doppelte ist an Bestand! Dann müßtest du erkennen, daß Gott dir viel von deiner Missetat übersieht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Kannst du die Tiefe Gottes erreichen, oder das Wesen des Allmächtigen ergründen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Himmelhoch sind sie, was kannst du tun? Tiefer als der Scheol, was kannst du wissen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Länger als die Erde ist ihr Maß und breiter als das Meer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Wenn er vorüberzieht und in Verhaft nimmt und zum Gericht versammelt, wer will ihm dann wehren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Denn er kennt die falschen Leute; und er sieht Frevel, ohne daß er achtgibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Auch ein Hohlköpfiger gewinnt Verstand, wenn auch der Mensch als ein Wildeselsfüllen geboren wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Wenn du dein Herz richtest und deine Hände zu ihm ausbreitest, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'wenn Frevel in deiner Hand ist, so entferne ihn, und laß Unrecht nicht wohnen in deinen Zelten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'ja, dann wirst du dein Angesicht erheben ohne Makel, und wirst unerschütterlich sein und dich nicht fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Denn du wirst die Mühsal vergessen, wirst ihrer gedenken wie vorübergeflossener Wasser;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'und heller als der Mittag wird dein Leben erstehen; mag es finster sein wie der Morgen wird es werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Und du wirst Vertrauen fassen, weil es Hoffnung gibt; und du wirst Umschau halten, in Sicherheit dich niederlegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Und du wirst dich lagern, und niemand wird dich aufschrecken; und viele werden deine Gunst suchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Aber die Augen der Gesetzlosen werden verschmachten; und jede Zuflucht ist ihnen verloren, und ihre Hoffnung ist das Aushauchen der Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Und Hiob antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Fürwahr, ihr seid die Leute, und mit euch wird die Weisheit aussterben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Auch ich habe Verstand wie ihr; ich stehe nicht hinter euch zurück; und wer wüßte nicht dergleichen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Ich muß einer sein, der seinem Freunde zum Gespött ist, der zu Gott ruft, und er antwortet ihm; der Gerechte, Vollkommene ist zum Gespött!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Dem Unglück gebührt Verachtung nach den Gedanken des Sorglosen; sie ist bereit für die, welche mit dem Fuße wanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Die Zelte der Verwüster sind in Ruhe, und Sicherheit ist für die, welche Gott reizen, für den, welcher Gott in seiner Hand führt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Aber frage doch das Vieh, und es wird\'s dich lehren; und das Gevögel des Himmels, und es wird\'s dir kundtun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'oder rede zu der Erde, und sie wird\'s dich lehren; und die Fische des Meeres werden es dir erzählen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Wer erkennte nicht an diesen allen, daß die Hand Jehovas solches gemacht hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'in dessen Hand die Seele alles Lebendigen ist und der Geist alles menschlichen Fleisches?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Soll nicht das Ohr die Worte prüfen, wie der Gaumen für sich die Speise kostet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Bei Greisen ist Weisheit, und Einsicht bei hohem Alter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Bei ihm ist Weisheit und Macht, sein ist Rat und Einsicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Siehe, er reißt nieder, und es wird nicht wieder gebaut; er schließt über jemand zu, und es wird nicht aufgetan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Siehe, er hemmt die Wasser, und sie vertrocknen; und er läßt sie los, und sie kehren das Land um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Bei ihm ist Kraft und vollkommenes Wissen; sein ist der Irrende und der Irreführende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Er führt Räte beraubt hinweg, und Richter macht er zu Narren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Die Herrschaft der Könige löst er auf, und schlingt eine Fessel um ihre Lenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Er führt Priester beraubt hinweg, und Feststehende stürzt er um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Zuverlässigen entzieht er die Sprache, und Alten benimmt er das Urteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Verachtung schüttet er auf Edle, und den Gürtel der Starken macht er schlaff.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Er enthüllt Tiefes aus der Finsternis, und Todesschatten zieht er an das Licht hervor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Er vergrößert Nationen, und er vernichtet sie; er breitet Nationen aus, und er führt sie hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Er entzieht den Verstand den Häuptern der Völker der Erde, und macht sie umherirren in pfadloser Einöde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'sie tappen in der Finsternis, wo kein Licht ist, und er macht sie umherirren gleich einem Trunkenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Siehe, das alles hat mein Auge gesehen, mein Ohr gehört und sich gemerkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'So viel ihr wisset, weiß auch ich; ich stehe nicht hinter euch zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Doch zu dem Allmächtigen will ich reden, und vor Gott mich zu rechtfertigen begehre ich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'ihr hingegen seid Lügenschmiede, nichtige Ärzte, ihr alle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'O daß ihr doch stille schwieget! Das würde euch zur Weisheit gereichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Höret doch meine Rechtfertigung, und horchet auf die Beweisgründe meiner Lippen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Wollt ihr für Gott Unrecht reden, und für ihn Trug reden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Wollt ihr für ihn Partei nehmen? Oder wollt ihr für Gott rechten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Ist es gut für euch, daß er euch erforsche? Oder werdet ihr ihn täuschen, wie man einen Menschen täuscht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Strafen wird er euch, wenn ihr im Geheimen die Person ansehet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Wird nicht seine Hoheit euch bestürzen, und sein Schrecken auf euch fallen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Eure Denksprüche sind Sprüche von Asche, eure Schutzwehren erweisen sich als Schutzwehren von Lehm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Schweiget, laßt mich, und ich will reden, was auch über mich ergehen möge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Warum sollte ich mein Fleisch zwischen meine Zähne nehmen, und mein Leben meiner Hand anvertrauen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Siehe, tötet er mich, ich werde auf ihn warten, nur will ich meine Wege ihm ins Angesicht rechtfertigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Auch das wird mir zur Rettung sein, daß ein Ruchloser nicht vor sein Angesicht kommen darf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Höret, höret meine Rede, und meine Erklärung dringe in eure Ohren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Siehe doch, ich habe die Rechtssache gerüstet! Ich weiß, daß ich Recht behalten werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Wer ist es, der mit mir rechten könnte? Denn dann wollte ich schweigen und verscheiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Nur zweierlei tue mir nicht; dann werde ich mich nicht vor deinem Angesicht verbergen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Deine Hand entferne von mir, und dein Schrecken ängstige mich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'So rufe denn, und ich will antworten, oder ich will reden, und erwidere mir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Wie viele Missetaten und Sünden habe ich? Laß mich meine Übertretung und meine Sünde wissen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Warum verbirgst du dein Angesicht, und hältst mich für deinen Feind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Willst du ein verwehtes Blatt hinwegschrecken, und die dürre Stoppel verfolgen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Denn Bitteres verhängst du über mich, und lässest mich erben die Missetaten meiner Jugend;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'und meine Füße legst du in den Stock, und beobachtest alle meine Pfade, grenzest dir ein die Sohlen meiner Füße;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'da ich doch zerfalle wie Moder, wie ein Kleid, das die Motte zerfressen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Der Mensch, vom Weibe geboren, ist kurz an Tagen und mit Unruhe gesättigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Wie eine Blume kommt er hervor und verwelkt; und er flieht wie der Schatten und hat keinen Bestand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Dennoch hast du über einen solchen deine Augen geöffnet, und mich führst du ins Gericht mit dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Wie könnte ein Reiner aus einem Unreinen kommen? Nicht ein einziger!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Wenn denn bestimmt sind seine Tage, die Zahl seiner Monde bei dir sind, wenn du ihm Schranken gesetzt hast, die er nicht überschreiten darf,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'so blicke von ihm weg, daß er Ruhe habe, bis er wie ein Tagelöhner seinen Tag vollende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Denn für den Baum gibt es Hoffnung: wird er abgehauen, so schlägt er wieder aus, und seine Schößlinge hören nicht auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Wenn seine Wurzel in der Erde altert, und sein Stumpf im Boden erstirbt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'vom Dufte des Wassers sproßt er wieder auf und treibt Zweige wie ein Pflänzling.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Der Mann aber stirbt und liegt da; und der Mensch verscheidet, und wo ist er?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Es verrinnen die Wasser aus dem See, und der Fluß trocknet ein und versiegt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'so legt der Mensch sich hin und steht nicht wieder auf; bis die Himmel nicht mehr sind, erwachen sie nicht und werden nicht aufgeweckt aus ihrem Schlafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'O daß du in dem Scheol mich verstecktest, mich verbärgest, bis dein Zorn sich abwendete, mir eine Frist setztest und dann meiner gedächtest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, '(Wenn ein Mann stirbt, wird er wieder leben?) Alle Tage meiner Dienstzeit wollte ich harren, bis meine Ablösung käme!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Du würdest rufen, und ich würde dir antworten; du würdest dich sehnen nach dem Werke deiner Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Denn nun zählst du meine Schritte; wachst du nicht über meine Sünde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Meine Übertretung ist versiegelt in einem Bündel, und du hast hinzugefügt zu meiner Missetat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Und doch, ein Berg stürzt ein, zerfällt, und ein Fels rückt weg von seiner Stelle;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Wasser zerreiben die Steine, ihre Fluten schwemmen den Staub der Erde hinweg; aber du machst zunichte die Hoffnung des Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Du überwältigst ihn für immer, und er geht dahin; sein Angesicht entstellend, sendest du ihn hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Seine Kinder kommen zu Ehren, und er weiß es nicht; und sie werden gering, und er achtet nicht auf sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Nur um ihn selbst hat sein Fleisch Schmerz, und nur um ihn selbst empfindet seine Seele Trauer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Und Eliphas, der Temaniter, antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Wird ein Weiser windige Erkenntnis antworten, und wird er sein Inneres füllen mit Ostwind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'streitend mit Reden, die nichts taugen, und mit Worten, womit er nicht nützt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Ja, du vernichtest die Gottesfurcht und schmälerst die Andacht vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Denn deine Ungerechtigkeit belehrt deinen Mund, und du wählst die Sprache der Listigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Dein Mund verdammt dich, und nicht ich; und deine Lippen zeugen wider dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Bist du als Erster zum Menschen gezeugt, und vor den Hügeln du geboren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Hast du im Rate Gottes zugehört, und die Weisheit an dich gerissen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Was weißt du, das wir nicht wüßten, was verstehst du, das uns nicht bekannt wäre?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Unter uns sind auch Alte, auch Greise, reicher an Tagen als dein Vater.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Sind dir zu wenig die Tröstungen Gottes, und ein sanftes Wort an dich zu gering?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Was reißt dein Herz dich hin, und was zwinken deine Augen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'daß du gegen Gott dein Schnauben kehrst, und Reden hervorgehen lässest aus deinem Munde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Was ist der Mensch, daß er rein sein sollte, und der vom Weibe Geborene, daß er gerecht wäre?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Siehe, auf seine Heiligen vertraut er nicht, und die Himmel sind nicht rein in seinen Augen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'wieviel weniger der Abscheuliche und Verderbte, der Mann, der Unrecht trinkt wie Wasser!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Ich will dir\'s berichten, höre mir zu; und was ich gesehen, will ich erzählen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'was die Weisen verkündigt und nicht verhehlt haben von ihren Vätern her, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'ihnen allein war das Land übergeben, und kein Fremder zog durch ihre Mitte; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Alle seine Tage wird der Gesetzlose gequält, und eine kleine Zahl von Jahren ist dem Gewalttätigen aufgespart.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Die Stimme von Schrecknissen ist in seinen Ohren, im Frieden kommt der Verwüster über ihn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'er glaubt nicht an eine Rückkehr aus der Finsternis, und er ist ausersehen für das Schwert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Er schweift umher nach Brot, wo es finden? Er weiß, daß neben ihm ein Tag der Finsternis bereitet ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Angst und Bedrängnis schrecken ihn, sie überwältigen ihn wie ein König, gerüstet zum Sturm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Weil er seine Hand wider Gott ausgestreckt hat und wider den Allmächtigen trotzte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'wider ihn anrannte mit gerecktem Halse, mit den dichten Buckeln seiner Schilde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'weil er sein Angesicht bedeckt hat mit seinem Fette und Schmer angesetzt an den Lenden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'und zerstörte Städte bewohnte, Häuser, die nicht bewohnt werden sollten, die zu Steinhaufen bestimmt waren:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'so wird er nicht reich werden, und sein Vermögen wird keinen Bestand haben; und nicht neigt sich zur Erde, was solche besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Er entweicht nicht der Finsternis; seine Schößlinge versengt die Flamme; und er muß weichen durch den Hauch seines Mundes. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Er verlasse sich nicht auf Nichtiges, er wird getäuscht; denn Nichtiges wird seine Vergeltung sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Noch ist sein Tag nicht da, so erfüllt es sich; und sein Palmzweig wird nicht grün.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Wie der Weinstock übt er Unbill an seinen unreifen Beeren, und wie der Olivenbaum wirft er seine Blüte ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Denn der Hausstand des Ruchlosen ist unfruchtbar, und Feuer frißt die Zelte der Bestechung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Sie sind schwanger mit Mühsal und gebären Unheil, und ihr Inneres bereitet Trug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Und Hiob antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Ich habe vieles dergleichen gehört; leidige Tröster seid ihr alle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Hat es ein Ende mit den windigen Worten? Oder was reizt dich, daß du antwortest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Auch ich könnte reden wie ihr. Wenn eure Seele an der Stelle meiner Seele wäre, könnte ich Worte wider euch zusammenreihen, und mein Haupt über euch schütteln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'ich wollte euch stärken mit meinem Munde, und das Beileid meiner Lippen würde euch Linderung bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Wenn ich rede, so wird mein Schmerz nicht gehemmt; und unterlasse ich es, nicht weicht er von mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Ja, bereits hat er mich erschöpft; du hast meinen ganzen Hausstand verwüstet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Und du hast mich zusammenschrumpfen lassen, zum Zeugen ward es; und meine Abmagerung tritt wider mich auf, sie zeugt mir ins Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Sein Zorn hat mich zerfleischt und verfolgt, er hat mit seinen Zähnen wider mich geknirscht; als mein Feind schärft er seine Augen wider mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Ihr Maul haben sie wider mich aufgesperrt, mit Hohn meine Backen geschlagen; allzumal verstärken sie sich wider mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Gott gab mich preis dem Ungerechten, und in die Hände der Gesetzlosen stürzte er mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Ich war in Ruhe, und er hat mich zerrüttelt, und er packte mich beim Nacken und zerschmetterte mich; und er stellte mich hin sich zur Zielscheibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Seine Schützen umringten mich, er spaltete meine Nieren ohne Schonung; er schüttete meine Galle zur Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Er durchbrach mich, Bruch auf Bruch; er rannte wider mich, wie ein Held.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Ich habe Sacktuch über meine Haut genäht, und mit Staub mein Horn besudelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Mein Angesicht glüht vom Weinen, und auf meinen Wimpern ist der Schatten des Todes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'obwohl keine Gewalttat in meinen Händen, und mein Gebet lauter ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Erde, bedecke nicht mein Blut, und für mein Geschrei sei kein Platz!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Sogar jetzt, siehe, im Himmel ist mein Zeuge, und der mir Zeugnis gibt, in den Höhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Meine Freunde sind meine Spötter: zu Gott tränt mein Auge,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'daß er schiedsrichterlich entscheide Gott gegenüber für einen Mann, und für einen Menschensohn hinsichtlich seines Freundes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Denn die zählbaren Jahre gehen vorüber, und ich werde einen Weg dahingehen, auf dem ich nicht wiederkehren werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Mein Geist ist verstört, meine Tage erlöschen, die Gräber sind für mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Sind nicht Spöttereien um mich her, und muß nicht mein Auge weilen auf ihren Beleidigungen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Setze doch ein, leiste Bürgschaft für mich bei dir selbst! Wer ist es sonst, der in meine Hand einschlagen wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Denn ihre Herzen hast du der Einsicht verschlossen; darum wirst du ihnen nicht die Oberhand geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Wenn einer die Freunde zur Beute ausbietet, so werden die Augen seiner Kinder verschmachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Und er hat mich hingestellt zum Sprichwort der Völker, und ich bin zum Anspeien ins Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Und mein Auge ist trübe geworden vor Gram, und wie der Schatten sind alle meine Glieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Die Aufrichtigen werden sich hierüber entsetzen, und der Schuldlose wird aufgebracht werden über den Ruchlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Doch der Gerechte wird an seinem Wege festhalten, und der an Händen Reine wird an Stärke zunehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Aber ihr alle, kommet nur wieder heran! Und einen Weisen werde ich nicht unter euch finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Meine Tage sind vorüber, zerrissen sind meine Pläne, das Eigentum meines Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Die Nacht machen sie zum Tage, das Licht nahe vor lauter Finsternis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Wenn ich hoffe, so ist der Scheol mein Haus, in der Finsternis bette ich mein Lager.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Zur Verwesung rufe ich: Du bist mein Vater! zu dem Gewürm: Meine Mutter und meine Schwester!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Wo denn also ist meine Hoffnung? Ja, meine Hoffnung, wer wird sie schauen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Sie fährt hinab zu den Riegeln des Scheols, wenn wir miteinander im Staube Ruhe haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Und Bildad, der Schuchiter, antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Wie lange wollt ihr auf Worte Jagd machen? Werdet verständig, und hernach wollen wir reden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Warum werden wir dem Vieh gleich geachtet, sind dumm in euren Augen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Du, der sich selbst zerfleischt in seinem Zorn, soll um deinetwillen die Erde verlassen werden, und ein Fels wegrücken von seiner Stelle?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Doch das Licht der Gesetzlosen wird erlöschen, und nicht leuchten wird die Flamme seines Feuers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Das Licht wird finster in seinem Zelte, und seine Lampe erlischt über ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Die Schritte seiner Kraft werden eingeengt werden, und sein Ratschlag wird ihn stürzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Denn durch seine eigenen Füße wird er ins Netz getrieben, und auf Fallgittern wird er einherwandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Der Fallstrick wird seine Ferse erfassen, die Schlinge ihn ergreifen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Sein Garn ist verborgen in der Erde, und seine Falle auf dem Pfade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Schrecken ängstigen ihn ringsum und scheuchen ihn auf Schritt und Tritt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Seine Kraft wird aufgezehrt werden durch Hunger, und das Verderben steht bereit an seiner Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Der Erstgeborene des Todes wird fressen die Glieder seines Leibes, seine Glieder wird er fressen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Seine Zuversicht wird hinweggerissen werden aus seinem Zelte, und es wird ihn forttreiben zu dem König der Schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Was nicht sein ist, wird in seinem Zelte wohnen, auf seine Wohnstätte wird Schwefel gestreut werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Unten werden seine Wurzeln verdorren, und oben wird sein Gezweig verwelken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Sein Gedächtnis verschwindet von der Erde, und auf der Fläche des Landes hat er keinen Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Man wird ihn aus dem Licht in die Finsternis stoßen, und aus der Welt ihn verjagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Er wird keinen Sohn und keinen Nachkommen haben unter seinem Volke, noch wird ein Entronnener in seinen Wohnsitzen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Über seinen Tag entsetzen sich die im Westen Wohnenden, und die im Osten erfaßt Schauder. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Ja, so sind die Wohnungen des Ungerechten, und so ist die Stätte dessen, der Gott nicht kennt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Und Hiob antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Wie lange wollt ihr meine Seele plagen und mich mit Worten zermalmen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Schon zehnmal ist es, daß ihr mich geschmäht habt; ihr schämet euch nicht, mich zu verletzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Und habe ich auch wirklich geirrt, so bleibt doch mein Irrtum bei mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Wenn ihr wirklich wider mich großtun wollt, und wider mich dartun meine Schmach,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'so wisset denn, daß Gott mich in meinem Rechte gebeugt und mich umstellt hat mit seinem Netze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Siehe, ich schreie über Gewalttat, und werde nicht erhört; ich rufe um Hilfe, und da ist kein Recht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Er hat meinen Weg verzäunt, daß ich nicht hinüber kann, und auf meine Pfade legte er Finsternis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Meine Ehre hat er mir ausgezogen, und weggenommen die Krone meines Hauptes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Er hat mich niedergerissen ringsum, so daß ich vergehe, und hat meine Hoffnung ausgerissen wie einen Baum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Und seinen Zorn ließ er wider mich entbrennen, und achtete mich seinen Feinden gleich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Allzumal kamen seine Scharen und bahnten ihren Weg wider mich, und lagerten sich rings um mein Zelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Meine Brüder hat er von mir entfernt, und meine Bekannten sind mir ganz entfremdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Meine Verwandten bleiben aus, und meine Vertrauten haben mich vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Meine Hausgenossen und meine Mägde achten mich für einen Fremden; ein Ausländer bin ich in ihren Augen geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Meinem Knechte rufe ich, und er antwortet nicht; mit meinem Munde muß ich zu ihm flehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Mein Atem ist meinem Weibe zuwider, und mein übler Geruch den Kindern meiner Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Selbst Buben verachten mich; will ich aufstehen, so reden sie über mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Alle meine Vertrauten verabscheuen mich, und die ich liebte, haben sich gegen mich gekehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Mein Gebein klebt an meiner Haut und an meinem Fleische, und nur mit der Haut meiner Zähne bin ich entronnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Erbarmet euch meiner, erbarmet euch meiner, ihr meine Freunde! Denn die Hand Gottes hat mich angetastet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Warum verfolget ihr mich wie Gott, und werdet meines Fleisches nicht satt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'O daß doch meine Worte aufgeschrieben würden! O daß sie in ein Buch gezeichnet würden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'mit eisernem Griffel und Blei in den Felsen eingehauen auf ewig!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Und ich, ich weiß, daß mein Erlöser lebt, und als der Letzte wird er auf der Erde stehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'und ist nach meiner Haut dieses da zerstört, so werde ich aus meinem Fleische Gott anschauen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'welchen ich selbst mir anschauen, und den meine Augen sehen werden, und kein anderer: meine Nieren verschmachten in meinem Innern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Wenn ihr saget: Wie wollen wir ihn verfolgen? und daß die Wurzel der Sache in mir sich befinde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'so fürchtet euch vor dem Schwerte! Denn das Schwert ist der Grimm über die Missetaten; auf daß ihr wisset, daß ein Gericht ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Und Zophar, der Naamathiter, antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Darum geben meine Gedanken mir Antwort, und deswegen bin ich innerlich erregt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Eine Zurechtweisung, mir zur Schande, höre ich; aber mein Geist antwortet mir aus meiner Einsicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Weißt du dieses, daß von jeher, seitdem der Mensch auf die Erde gesetzt wurde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'der Jubel der Gesetzlosen kurz und die Freude des Ruchlosen für einen Augenblick war?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Stiege auch seine Höhe bis zum Himmel hinauf, und rührte sein Haupt an die Wolken:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'gleich seinem Kote vergeht er auf ewig; die ihn gesehen haben, sagen: Wo ist er?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Wie ein Traum verfliegt er, und man findet ihn nicht, und er wird hinweggescheucht wie ein Nachtgesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Das Auge hat ihn erblickt und sieht ihn nimmer wieder, und seine Stätte gewahrt ihn nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Seine Kinder müssen die Armen begütigen, und seine Hände sein Vermögen zurückgeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Seine Knochen waren voll seiner Jugendkraft, und sie liegt mit ihm in dem Staube. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Wenn das Böse in seinem Munde süß war, und er es verbarg unter seiner Zunge,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'und es aufsparte und nicht fahren ließ und es zurückhielt unter seinem Gaumen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'so ist doch nun seine Speise in seinen Eingeweiden verwandelt; Natterngalle ist in seinem Innern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Reichtum hat er verschlungen, und er speit ihn aus: aus seinem Bauche treibt Gott ihn heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Natterngift sog er ein: es tötet ihn die Zunge der Otter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Nicht darf er sich laben an Bächen, flutenden Strömen von Honig und Milch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Das Errungene gibt er zurück, und er darf es nicht verschlingen; gemäß dem Vermögen, das er erworben, darf er sich nicht freuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Denn er hat mißhandelt, verlassen die Armen; Häuser hat er an sich gerissen und wird sie nicht ausbauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Denn er kannte keine Ruhe in seinem Innern: mit seinem Teuersten wird er nicht entrinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Nichts entging seiner Freßgier; darum wird sein Wohlstand nicht dauernd sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'In der Fülle seines Überflusses wird er in Bedrängnis sein; die Hand jedes Notleidenden wird über ihn kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Es wird geschehen: um seinen Bauch zu füllen, wird Gott die Glut seines Zornes in ihn entsenden, und sie auf ihn regnen lassen in sein Fleisch hinein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Flieht er vor den eisernen Waffen, so wird der eherne Bogen ihn durchbohren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Er zieht am Pfeile, und er kommt aus dem Leibe hervor, und das glänzende Eisen aus seiner Galle: Schrecken kommen über ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Eitel Finsternis ist aufgespart für seine Schätze; ein Feuer, das nicht angeblasen ist, wird ihn fressen, wird verzehren, was in seinem Zelte übriggeblieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Der Himmel wird seine Ungerechtigkeit enthüllen, und die Erde sich wider ihn erheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Der Ertrag seines Hauses wird weggeführt werden, wird zerrinnen am Tage seines Zornes. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Das ist das Teil des gesetzlosen Menschen von Gott und das von Gott ihm zugesprochene Los.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Und Hiob antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Höret, höret meine Rede! Und dies ersetze eure Tröstungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Ertraget mich, und ich will reden, und nachdem ich geredet habe, magst du spotten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Richtet sich meine Klage an einen Menschen? Oder warum sollte ich nicht ungeduldig sein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Wendet euch zu mir und entsetzet euch, und leget die Hand auf den Mund!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Ja, wenn ich daran denke, so bin ich bestürzt, und Schauder erfaßt mein Fleisch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Warum leben die Gesetzlosen, werden alt, nehmen gar an Macht zu?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Ihr Same steht fest vor ihnen, mit ihnen, und ihre Sprößlinge vor ihren Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Ihre Häuser haben Frieden, ohne Furcht, und Gottes Rute ist nicht über ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Sein Stier belegt und befruchtet sicher, seine Kuh kalbt und wirft nicht fehl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Ihre Buben schicken sie aus gleich einer Herde, und ihre Knaben hüpfen umher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Sie erheben die Stimme bei Tamburin und Laute und sind fröhlich beim Klange der Schalmei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'In Wohlfahrt verbringen sie ihre Tage, und in einem Augenblick sinken sie in den Scheol hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Und doch sprechen sie zu Gott: Weiche von uns! Und nach der Erkenntnis deiner Wege verlangen wir nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Was ist der Allmächtige, daß wir ihm dienen sollten, und was nützt es uns, daß wir ihn angehen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Siehe, ihre Wohlfahrt steht nicht in ihrer Hand. Der Rat der Gesetzlosen sei fern von mir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Wie oft geschieht es, daß die Leuchte der Gesetzlosen erlischt und ihr Verderben über sie kommt, daß er ihnen Schlingen zuteilt in seinem Zorn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'daß sie wie Stroh werden vor dem Winde, und wie Spreu, die der Sturmwind entführt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Gott spart, saget ihr, sein Unheil auf für seine Kinder. Er vergelte ihm, daß er es fühle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Seine Augen sollen sein Verderben sehen, und von dem Grimme des Allmächtigen trinke er!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Denn was liegt ihm an seinem Hause nach ihm, wenn die Zahl seiner Monde durchschnitten ist? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Kann man Gott Erkenntnis lehren, da er es ja ist, der die Hohen richtet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Dieser stirbt in seiner Vollkraft, ganz wohlgemut und sorglos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Seine Gefäße sind voll Milch, und das Mark seiner Gebeine ist getränkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Und jener stirbt mit bitterer Seele und hat des Guten nicht genossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Zusammen liegen sie im Staube, und Gewürm bedeckt sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Siehe, ich kenne eure Gedanken, und die Anschläge, womit ihr mir Gewalt antut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Denn ihr saget: Wo ist das Haus des Edlen, und wo das Wohngezelt der Gesetzlosen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Habt ihr nicht befragt, die des Weges vorüberziehen? Und erkennet ihr ihre Merkmale nicht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'daß der Böse verschont wird am Tage des Verderbens, daß am Tage der Zornesfluten sie weggeleitet werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Wer wird ihm ins Angesicht seinen Weg kundtun? Und hat er gehandelt, wer wird es ihm vergelten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Und er wird zu den Gräbern hingebracht, und auf dem Grabhügel wacht er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Süß sind ihm die Schollen des Tales. Und hinter ihm her ziehen alle Menschen, und vor ihm her gingen sie ohne Zahl. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Wie tröstet ihr mich nun mit Dunst? Und von euren Antworten bleibt nur Treulosigkeit übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Und Eliphas, der Temaniter, antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Kann ein Mann Gott Nutzen bringen? Vielmehr sich selbst nützt der Einsichtige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Liegt dem Allmächtigen daran, wenn du gerecht bist, oder ist es ihm ein Gewinn, wenn du deine Wege vollkommen machst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Ist es wegen deiner Gottesfurcht, daß er dich straft, mit dir ins Gericht geht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Ist nicht deine Bosheit groß, und deiner Missetaten kein Ende?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Denn du pfändetest deinen Bruder ohne Ursache, und die Kleider der Nackten zogest du aus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'den Lechzenden tränktest du nicht mit Wasser, und dem Hungrigen verweigertest du das Brot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Und dem Manne der Gewalt, ihm gehörte das Land, und der Angesehene wohnte darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Die Witwe schicktest du leer fort, und die Arme der Waisen wurden zermalmt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Darum sind Schlingen rings um dich her, und ein plötzlicher Schrecken macht dich bestürzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Oder siehst du nicht die Finsternis und die Wasserflut, die dich bedeckt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Ist Gott nicht so hoch wie die Himmel? Sieh doch den Gipfel der Sterne, wie erhaben sie sind!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Und so sprichst du: Was sollte Gott wissen? Kann er richten durch Wolkendunkel hindurch?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Die Wolken sind ihm eine Hülle, daß er nicht sieht, und er durchwandelt den Kreis des Himmels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Willst du den Pfad der Vorzeit einhalten, welchen die Frevler betraten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'die weggerafft wurden vor der Zeit? Wie ein Strom zerfloß ihr fester Grund;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'die zu Gott sprachen: Weiche von uns! Und was könnte der Allmächtige für uns tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Und doch hatte er ihre Häuser mit Wohlstand erfüllt. Aber der Rat der Gesetzlosen sei fern von mir! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Die Gerechten sehen es und freuen sich, und der Schuldlose spottet ihrer:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Sind nicht unsere Gegner vertilgt, und hat nicht Feuer ihren Überfluß gefressen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Verkehre doch freundlich mit ihm und halte Frieden; dadurch wird Wohlfahrt über dich kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Empfange doch Belehrung aus seinem Munde, und nimm dir seine Worte zu Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Wenn du zu dem Allmächtigen umkehrst, so wirst du wieder aufgebaut werden; wenn du Unrecht entfernst aus deinen Zelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Und lege das Golderz in den Staub und das Gold von Ophir unter den Kies der Bäche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'so wird der Allmächtige dein Golderz und dein glänzendes Silber sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Denn dann wirst du an dem Allmächtigen dich ergötzen und zu Gott dein Angesicht erheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Du wirst zu ihm beten, und er wird dich erhören; und deine Gelübde wirst du bezahlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Beschließest du eine Sache, so wird sie zustande kommen, und Licht wird strahlen über deinen Wegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Wenn sie abwärts gehen, so wirst du sagen: Empor! Und den, der mit gesenkten Augen einhergeht, wird er retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Selbst den Nicht-Schuldlosen wird er befreien: er wird befreit werden durch die Reinheit deiner Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Und Hiob antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Auch heute ist meine Klage trotzig; seine Hand lastet schwer auf meinem Seufzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'O daß ich ihn zu finden wüßte, daß ich kommen könnte bis zu seiner Wohnstätte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Ich würde meine Rechtssache vor ihm darlegen, und meinen Mund mit Beweisgründen füllen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Ich würde die Worte wissen, die er mir antworten, und vernehmen, was er mir sagen würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Würde er in der Größe seiner Kraft mit mir streiten? Nein; er würde nur acht auf mich haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Alsdann würde ein Rechtschaffener mit ihm rechten, und auf ewig würde ich meinem Richter entkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Siehe, gehe ich vorwärts, so ist er nicht da; und rückwärts, so bemerke ich ihn nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'zur Linken, während er wirkt, so schaue ich ihn nicht; er verhüllt sich zur Rechten, und ich sehe ihn nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Denn er kennt den Weg, der bei mir ist; prüfte er mich, wie Gold würde ich hervorgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'An seinem Schritte hat mein Fuß festgehalten, und seinen Weg habe ich beobachtet und bin nicht abgebogen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'von dem Gebote seiner Lippen bin ich nicht abgewichen, ich habe die Worte seines Mundes verwahrt, mehr als meinen eigenen Vorsatz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Doch er bleibt sich gleich, und wer kann seinen Sinn ändern? Was seine Seele begehrt, das tut er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Denn er wird vollenden, was über mich bestimmt ist; und dergleichen ist vieles bei ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Darum bin ich bestürzt vor seinem Angesicht; erwäge ich\'s, so erschrecke ich vor ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Ja, Gott hat mein Herz verzagt gemacht, und der Allmächtige mich in Bestürzung versetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Denn nicht wegen der Finsternis bin ich vernichtet, noch weil Dunkelheit mein Angesicht bedeckt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Warum sind nicht Zeiten aufgespart von dem Allmächtigen, und warum sehen die, welche ihn kennen, seine Tage nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Sie verrücken die Grenzen, sie rauben die Herde und weiden sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Sie treiben den Esel der Waisen weg, nehmen das Rind der Witwe zum Pfande;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'sie stoßen aus dem Wege die Dürftigen. Die Elenden des Landes verkriechen sich allesamt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Siehe, wie Wildesel in der Wüste gehen sie aus an ihr Werk, eifrig nach Beute suchend; die Steppe liefert ihnen Brot für die Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Auf dem Felde schneiden sie sein Futterkorn ab und lesen den Weinberg des Gesetzlosen nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Nackt übernachten sie, ohne Gewand, und haben keine Bedeckung in der Kälte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Vom Regenguß des Gebirges werden sie durchnäßt, und obdachlos umklammern sie den Felsen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Sie reißen die Waise von der Brust, und was der Elende anhat, nehmen sie zum Pfande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Nackt gehen sie einher, ohne Gewand, und hungernd tragen sie die Garbe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'zwischen ihren Mauern pressen sie Öl, treten die Kelter und dursten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Von der Stadt her ächzen Sterbende, und die Seele der Erschlagenen schreit. Und Gott rechnet es nicht als Ungebühr an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Jene gehören zu den Feinden des Lichtes, sie kennen seine Wege nicht und weilen nicht auf seinen Pfaden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Mit dem Lichte steht der Mörder auf, tötet den Elenden und den Dürftigen; und des Nachts ist er dem Diebe gleich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Und das Auge des Ehebrechers lauert auf die Dämmerung, indem er spricht: Kein Auge wird mich erblicken; und er legt einen Schleier an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'In der Finsternis erbricht man die Häuser. Bei Tage schließen sie sich ein, das Licht kennen sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Denn als Morgen gilt ihnen allesamt der Todesschatten, denn ein jeder von ihnen ist bekannt mit den Schrecken des Todesschattens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Er ist schnell auf der Wasserfläche, verflucht wird ihr Grundbesitz auf Erden; nicht mehr schlägt er den Weg zu den Weinbergen ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Dürre und Hitze raffen Schneewasser hinweg: so der Scheol, die gesündigt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Der Mutterleib vergißt seiner, das Gewürm labt sich an ihm, nicht mehr wird seiner gedacht: und das Unrecht wird zerbrochen wie ein Baum,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'er, der die Unfruchtbare beraubt, die nicht gebiert, und der Witwe kein Gutes tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Und Mächtige rafft er dahin durch seine Kraft; steht er auf, so getraut man sich nicht des Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Er gibt ihm Sicherheit, und er wird gestützt. Aber seine Augen sind über ihren Wegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Sie sind hochgestiegen: um ein Kleines, und sie sind nicht mehr; und sie sinken hin, werden zusammengerafft wie alle anderen; und wie der Kopf der Ähre werden sie abgeschnitten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Und wenn es nun nicht so ist, wer wird mich Lügen strafen und meine Rede zunichte machen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Und Bildad, der Schuchiter, antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Herrschaft und Schrecken sind bei ihm; er schafft Frieden in seinen Höhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Sind seine Scharen zu zählen? Und über wem erhebt sich nicht sein Licht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Und wie könnte ein Mensch gerecht sein vor Gott, und wie könnte rein sein ein vom Weibe Geborener?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Siehe, sogar der Mond scheint nicht hell, und die Sterne sind nicht rein in seinen Augen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'wieviel weniger der Mensch, der Wurm, und das Menschenkind, die Made!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Und Hiob antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Wie hast du dem Ohnmächtigen geholfen, den kraftlosen Arm gerettet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Wie hast du den beraten, der keine Weisheit hat, und gründliches Wissen in Fülle kundgetan!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'An wen hast du Worte gerichtet, und wessen Odem ist von dir ausgegangen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Die Schatten beben unter den Wassern und ihren Bewohnern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Der Scheol ist nackt vor ihm, und keine Hülle hat der Abgrund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Er spannt den Norden aus über der Leere, hängt die Erde auf über dem Nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Er bindet die Wasser in seine Wolken, und das Gewölk zerreißt nicht unter ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Er verhüllt den Anblick seines Thrones, indem er sein Gewölk darüber ausbreitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Er rundete eine Schranke ab über der Fläche der Wasser bis zum äußersten Ende, wo Licht und Finsternis zusammentreffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Die Säulen des Himmels wanken und entsetzen sich vor seinem Schelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Durch seine Kraft erregt er das Meer, und durch seine Einsicht zerschellt er Rahab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Durch seinen Hauch wird der Himmel heiter, seine Hand durchbohrt den flüchtigen Drachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Siehe, das sind die Säume seiner Wege; und wie wenig haben wir von ihm gehört! Und den Donner seiner Macht, wer versteht ihn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Und Hiob fuhr fort, seinen Spruch anzuheben, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'So wahr Gott lebt, der mir mein Recht entzogen, und der Allmächtige, der meine Seele bitter gemacht hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'so lange mein Odem in mir ist, und der Hauch Gottes in meiner Nase:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'wenn meine Lippen Unrecht reden werden, und wenn meine Zunge Trug aussprechen wird!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Fern sei es von mir, daß ich euch recht geben sollte; bis ich verscheide, werde ich meine Unsträflichkeit nicht von mir weichen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'An meiner Gerechtigkeit halte ich fest und werde sie nicht fahren lassen: mein Herz schmäht nicht einen von meinen Tagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Mein Feind sei wie der Gesetzlose, und der wider mich auftritt wie der Ungerechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Denn was ist des Ruchlosen Hoffnung, wenn Gott abschneidet, wenn er seine Seele herauszieht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Wird Gott sein Geschrei hören, wenn Bedrängnis über ihn kommt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Oder wird er sich an dem Allmächtigen ergötzen, Gott anrufen zu aller Zeit?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Ich will euch belehren über die Hand Gottes; was bei dem Allmächtigen ist, will ich nicht verhehlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Siehe, ihr selbst habt es alle erschaut, und warum denn schwatzet ihr so eitel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Dies ist das Teil des gesetzlosen Menschen bei Gott, und das Erbe der Gewalttätigen, welches sie von dem Allmächtigen empfangen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Wenn seine Kinder sich mehren, so ist er für das Schwert, und seine Sprößlinge, sie haben nicht satt Brot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Seine Übriggebliebenen werden begraben durch den Tod, und seine Witwen weinen nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Wenn er Silber aufhäuft wie Staub, und Kleider bereitet wie Lehm:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'er bereitet sie, aber der Gerechte bekleidet sich damit; und Schuldlose teilen sich in das Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Er hat sein Haus gebaut wie die Motte, und der Hütte gleich, die ein Wächter sich macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Reich legt er sich ihn, und er tut es nicht wieder; er schlägt die Augen auf, und ist nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Schrecken ereilen ihn wie Wasser, des Nachts entführt ihn ein Sturmwind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Der Ostwind hebt ihn empor, daß er dahinfährt, und stürmt ihn fort von seiner Stätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Und Gott schleudert auf ihn ohne Schonung; seiner Hand möchte er flüchtend entfliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Man klatscht über ihn in die Hände, und zischt ihm nach von seiner Stätte aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Denn für das Silber gibt es einen Fundort, und eine Stätte für das Gold, das man läutert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Eisen wird hervorgeholt aus der Erde, und Gestein schmelzt man zu Kupfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Er hat der Finsternis ein Ende gesetzt, und durchforscht bis zur äußersten Grenze das Gestein der Finsternis und des Todesschattens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Er bricht einen Schacht fern von dem Wohnenden; die von dem Fuße Vergessenen hangen hinab, fern von den Menschen schweben sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Die Erde, aus ihr kommt Brot hervor, und ihr Unteres wird zerwühlt wie vom Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Ihr Gestein ist der Sitz des Saphirs, und Goldstufen sind darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Ein Pfad, den der Raubvogel nicht kennt, und den das Auge des Habichts nicht erblickt hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'den die wilden Tiere nicht betreten, über den der Löwe nicht hingeschritten ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Er legt seine Hand an das harte Gestein, wühlt die Berge um von der Wurzel aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Kanäle haut er durch die Felsen, und allerlei Köstliches sieht sein Auge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Er dämmt Flüsse ein, daß sie nicht durchsickern, und Verborgenes zieht er hervor an das Licht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Aber die Weisheit, wo wird sie erlangt? Und welches ist die Stätte des Verstandes?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Kein Mensch kennt ihren Wert, und im Lande der Lebendigen wird sie nicht gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Die Tiefe spricht: Sie ist nicht in mir, und das Meer spricht: Sie ist nicht bei mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Geläutertes Gold kann nicht für sie gegeben, und Silber nicht dargewogen werden als ihr Kaufpreis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Sie wird nicht aufgewogen mit Gold von Ophir, mit kostbarem Onyx und Saphir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Gold und Glas kann man ihr nicht gleichstellen, noch sie eintauschen gegen ein Gerät von gediegenem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Korallen und Kristall kommen neben ihr nicht in Erwähnung; und der Besitz der Weisheit ist mehr wert als Perlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Nicht kann man ihr gleichstellen den Topas von Äthiopien; mit feinem Golde wird sie nicht aufgewogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Die Weisheit nun, woher kommt sie, und welches ist die Stätte des Verstandes?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Denn sie ist verborgen vor den Augen aller Lebendigen, und vor den Vögeln des Himmels ist sie verhüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Der Abgrund und der Tod sagen: Mit unseren Ohren haben wir ein Gerücht von ihr gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Gott versteht ihren Weg, und er kennt ihre Stätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Denn er schaut bis zu den Enden der Erde; unter dem ganzen Himmel sieht er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Als er dem Winde ein Gewicht bestimmte, und die Wasser mit dem Maße abwog,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'als er dem Regen ein Gesetz bestimmte und eine Bahn dem Donnerstrahl:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'da sah er sie und tat sie kund, er setzte sie ein und durchforschte sie auch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Und zu dem Menschen sprach er: Siehe, die Furcht des Herrn ist Weisheit, und vom Bösen weichen ist Verstand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Und Hiob fuhr fort, seinen Spruch anzuheben, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'O daß ich wäre wie in den Monden der Vorzeit, wie in den Tagen, da Gott mich bewahrte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'als seine Leuchte über meinem Haupte schien, und ich bei seinem Lichte durch die Finsternis wandelte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'wie ich war in den Tagen meiner Reife, als das Vertrauen Gottes über meinem Zelte waltete,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'als der Allmächtige noch mit mir war, meine Knaben rings um mich her;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'als meine Schritte sich in Milch badeten, und der Fels neben mir Ölbäche ergoß;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'als ich durch das Tor in die Stadt hineinging, meinen Sitz auf dem Platze aufstellte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Die Jünglinge sahen mich und verbargen sich, und die Greise erhoben sich, blieben stehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'die Fürsten hielten die Worte zurück und legten die Hand auf ihren Mund;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'die Stimme der Vornehmen verstummte, und ihre Zunge klebte an ihrem Gaumen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Denn wenn das Ohr von mir hörte, so pries es mich glücklich, und wenn das Auge mich sah, so legte es Zeugnis von mir ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Denn ich befreite den Elenden, der um Hilfe rief, und die Waise, die keinen Helfer hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Der Segen des Umkommenden kam über mich, und das Herz der Witwe machte ich jubeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Ich kleidete mich in Gerechtigkeit, und sie bekleidete mich, wie in Oberkleid und Kopfbund in mein Recht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Auge war ich dem Blinden, und Fuß dem Lahmen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Vater war ich den Dürftigen, und die Rechtssache dessen, den ich nicht kannte, untersuchte ich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'und ich zerbrach das Gebiß des Ungerechten, und seinen Zähnen entriß ich die Beute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Und ich sprach: In meinem Neste werde ich verscheiden, und meine Tage vermehren wie der Sand;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'meine Wurzel wird ausgebreitet sein am Wasser, und der Tau wird übernachten auf meinem Gezweig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'meine Ehre wird frisch bei mir bleiben, und mein Bogen sich in meiner Hand verjüngen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Sie hörten mir zu und harrten, und horchten schweigend auf meinen Rat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Nach meinem Worte sprachen sie nicht wieder, und auf sie träufelte meine Rede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Und sie harrten auf mich wie auf den Regen, und sperrten ihren Mund auf wie nach dem Spätregen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Ich lächelte ihnen zu, wenn sie kein Vertrauen hatten, und das Licht meines Angesichts konnten sie nicht trüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Ich wählte für sie den Weg aus, und saß als Haupt, und thronte wie ein König unter der Kriegsschar, gleichwie einer, der Trauernde tröstet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Und nun lachen über mich Jüngere als ich an Jahren, deren Väter ich verschmähte, den Hunden meiner Herde beizugesellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Wozu sollte mir auch die Kraft ihrer Hände nützen? Die Rüstigkeit ist bei ihnen verschwunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Durch Mangel und Hunger abgezehrt, nagen sie das dürre Land ab, welches längst öde und verödet ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'sie pflücken Salzkraut bei den Gesträuchen, und die Wurzel der Ginster ist ihre Speise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Aus der Mitte der Menschen werden sie vertrieben; man schreit über sie wie über einen Dieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'In grausigen Klüften müssen sie wohnen, in Erdlöchern und Felsenhöhlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Zwischen Gesträuchen kreischen sie, unter Dorngestrüpp sind sie hingestreckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Kinder von Verworfenen, ja, Kinder von Ehrlosen, sind sie hinausgepeitscht aus dem Lande!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Und nun bin ich ihr Spottlied geworden, und ward ihnen zum Gerede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Sie verabscheuen mich, treten fern von mir weg, und sie verschonen mein Angesicht nicht mit Speichel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Denn er hat meinen Strick gelöst und mich gebeugt: so lassen sie vor mir den Zügel schießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Zu meiner Rechten erhebt sich die Brut; sie stoßen meine Füße hinweg und bahnen wider mich ihre verderblichen Wege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Sie zerstören meinen Pfad, befördern meinen Untergang, sie, die selbst hilflos sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Sie kommen wie durch einen weiten Riß, unter Gekrach wälzen sie sich heran. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Schrecknisse haben sich gegen mich gekehrt; sie verfolgen wie der Wind meine Würde, und mein Heil ist vorübergezogen wie eine Wolke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Und nun ergießt sich in mir meine Seele; Tage des Elends haben mich ergriffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Die Nacht durchbohrt meine Gebeine und löst sie von mir ab, und die an mir nagenden Schmerzen ruhen nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Durch die Größe ihrer Kraft verändert sich mein Gewand, es umschließt mich wie der Halssaum meines Leibrocks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Er hat mich in den Kot geworfen, und ich bin dem Staube und der Asche gleich geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Ich schreie zu dir, und du antwortest mir nicht; ich stehe da, und du starrst mich an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'In einen Grausamen verwandelst du dich mir, mit der Stärke deiner Hand befeindest du mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Du hebst mich empor auf den Wind, du lässest mich dahinfahren und zerrinnen im Sturmgetöse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Denn ich weiß es, du willst mich in den Tod zurückführen und in das Versammlungshaus aller Lebendigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Doch streckt man beim Sturze nicht die Hand aus, oder erhebt man bei seinem Untergang nicht darob ein Hilfsgeschrei?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Weinte ich denn nicht über den, der harte Tage hatte? War meine Seele nicht um den Dürftigen bekümmert?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Denn ich erwartete Gutes, und es kam Böses; und ich harrte auf Licht, und es kam Finsternis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Meine Eingeweide wallen und ruhen nicht; Tage des Elends sind mir entgegengetreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Trauernd gehe ich einher, ohne Sonne; ich stehe auf in der Versammlung und schreie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Ich bin ein Bruder geworden den Schakalen, und ein Genosse den Straußen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Meine Haut ist schwarz geworden und löst sich von mir ab, und mein Gebein ist brennend vor Glut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Und so ist meine Laute zur Trauerklage geworden, und meine Schalmei zur Stimme der Weinenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Ich habe mit meinen Augen einen Bund gemacht, und wie hätte ich auf eine Jungfrau geblickt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Denn was wäre das Teil Gottes von oben gewesen, und das Erbe des Allmächtigen aus den Höhen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Ist nicht Verderben für den Ungerechten, und Mißgeschick für die, welche Frevel tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Sieht er nicht meine Wege und zählt alle meine Schritte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Wenn ich mit Falschheit umgegangen bin und mein Fuß dem Truge zugeeilt ist, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'er wäge mich auf der Waage der Gerechtigkeit, und Gott wird meine Unsträflichkeit erkennen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'wenn mein Schritt von dem Wege abgebogen, und mein Herz meinen Augen gefolgt ist, und an meinen Händen ein Makel kleben blieb:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'so möge ich säen, und ein anderer essen, und meine Sprößlinge mögen entwurzelt werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Wenn mein Herz zu einem Weibe verlockt worden ist und ich an der Tür meines Nächsten gelauert habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'so möge mein Weib für einen anderen mahlen, und andere mögen sich über sie beugen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Denn das ist eine Schandtat, und das eine Missetat für die Richter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Denn ein Feuer ist es, das bis zum Abgrund frißt, und das meinen ganzen Ertrag entwurzeln würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Wenn ich das Recht meines Knechtes und meiner Magd mißachtete, als sie mit mir stritten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'was wollte ich dann tun, wenn Gott sich erhöbe; und wenn er untersuchte, was ihm erwidern?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Hat nicht er, der mich im Mutterleibe bereitete, auch ihn bereitet, und hat nicht einer im Schoße uns gebildet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Wenn ich den Armen ihr Begehr versagte, und die Augen der Witwe verschmachten ließ,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'und aß meinen Bissen allein, so daß der Verwaiste nicht davon gegessen hat-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'ist er doch von meiner Jugend an bei mir aufgewachsen, wie bei einem Vater, und von meiner Mutter Leibe an habe ich sie geleitet; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'wenn ich jemand umkommen sah aus Mangel an Kleidung, und den Dürftigen ohne Decke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'wenn seine Lenden mich nicht gesegnet haben, und er mit der Wolle meiner Lämmer sich nicht erwärmte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'wenn ich meine Hand geschwungen über eine Waise, weil ich im Tore meinen Beistand sah:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'so falle meine Schulter aus ihrem Blatt, und mein Arm werde abgebrochen von der Röhre!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Denn das Verderben Gottes war mir ein Schrecken, und vor seiner Erhabenheit vermochte ich nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Wenn ich das Gold zu meiner Zuversicht gemacht, und zu dem feinen Golde gesagt habe: Mein Vertrauen! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'wenn ich mich freute, daß mein Vermögen groß war, und daß meine Hand Ansehnliches erworben hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'wenn ich die Sonne sah, wie sie glänzte, und den Mond in Pracht dahinwandeln,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'und mein Herz im Geheimen verführt wurde und mein Mund meine Hand geküßt hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'auch das wäre eine gerichtlich zu strafende Missetat; denn Gott droben würde ich verleugnet haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Wenn ich mich freute über das Unglück meines Hassers und aufjauchzte, als Böses ihn traf,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'nie habe ich ja meinem Gaumen erlaubt, zu sündigen, durch einen Fluch seine Seele zu fordern; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'wenn die Leute meines Zeltes nicht gesagt haben: Wer wäre nicht von dem Fleische seines Schlachtviehes satt geworden! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'der Fremdling übernachtete nicht draußen, ich öffnete dem Wanderer meine Tür;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'wenn ich, wie Adam, meine Übertretungen zugedeckt habe, verbergend in meinem Busen meine Missetat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'weil ich mich fürchtete vor der großen Menge, und die Verachtung der Familien mich erschreckte, so daß ich mich still hielt, nicht zur Türe hinausging...');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'O daß ich einen hätte, der auf mich hörte, hier ist meine Unterschrift; der Allmächtige antworte mir! und die Klageschrift, welche mein Gegner geschrieben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Würde ich sie nicht auf meiner Schulter tragen, sie mir umbinden als Krone?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Ich würde ihm kundtun die Zahl meiner Schritte, würde ihm nahen wie ein Fürst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Wenn mein Acker über mich schreit, und seine Furchen allesamt weinen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'wenn ich seinen Ertrag ohne Zahlung verzehrt habe, und die Seele seiner Besitzer aushauchen ließ:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'so mögen Dornen statt Weizen, und Unkraut statt Gerste hervorkommen! Die Worte Hiobs sind zu Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Und jene drei Männer hörten auf, dem Hiob zu antworten, weil er in seinen Augen gerecht war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Da entbrannte der Zorn Elihus, des Sohnes Barakeels, des Busiters, vom Geschlechte Ram; sein Zorn entbrannte wider Hiob, weil er sich selbst mehr rechtfertigte als Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Und sein Zorn entbrannte wider seine drei Freunde, darum, daß sie keine Antwort fanden und Hiob verdammten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Aber Elihu hatte auf Hiob gewartet mit Reden, weil jene älter an Jahren waren als er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Und als Elihu sah, daß keine Antwort in dem Munde der drei Männer war, da entbrannte sein Zorn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Und Elihu, der Sohn Barakeels, der Busiter, hob an und sprach: Ich bin jung an Jahren, und ihr seid Greise; darum habe ich mich gescheut und gefürchtet, euch mein Wissen kundzutun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Ich sagte: Mögen die Tage reden, und die Menge der Jahre Weisheit verkünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Jedoch der Geist ist es in den Menschen, und der Odem des Allmächtigen, der sie verständig macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Nicht die Bejahrten sind weise, noch verstehen die Alten, was recht ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Darum sage ich: Höre mir zu, auch ich will mein Wissen kundtun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Siehe, ich harrte auf eure Reden, horchte auf eure Einsichten, bis ihr Worte ausfindig gemacht hättet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'und ich richtete meine Aufmerksamkeit auf euch; und siehe, keiner ist unter euch, der Hiob widerlegt, der seine Reden beantwortet hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Daß ihr nur nicht saget: Wir haben Weisheit gefunden. Gott wird ihn aus dem Felde schlagen, nicht ein Mensch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Er hat ja an mich keine Worte gerichtet, und mit euren Reden werde ich ihm nicht erwidern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Sie sind bestürzt, sie antworten nicht mehr, die Worte sind ihnen ausgegangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Und ich sollte warten, weil sie nicht reden, weil sie dastehen, nicht mehr antworten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Auch ich will mein Teil erwidern, auch ich will mein Wissen kundtun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Denn voll bin ich von Worten; der Geist meines Innern drängt mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Siehe, mein Inneres ist wie Wein, der nicht geöffnet ist; gleich neuen Schläuchen will es bersten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Ich will reden, daß mir Luft werde, will meine Lippen auftun und antworten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Daß ich nur ja für niemand Partei nehme! Und keinem Menschen werde ich schmeicheln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Denn ich weiß nicht zu schmeicheln: gar bald würde mein Schöpfer mich hinwegnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Nun aber, Hiob, höre doch meine Reden, und nimm zu Ohren alle meine Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Siehe doch, ich habe meinen Mund aufgetan, meine Zunge redet in meinem Gaumen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Meine Worte sollen die Geradheit meines Herzens sein, und was meine Lippen wissen, sollen sie rein heraussagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Der Geist Gottes hat mich gemacht, und der Odem des Allmächtigen belebt mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Wenn du kannst, so antworte mir; rüste dich vor mir, stelle dich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Siehe, ich bin Gottes, wie du; vom Tone abgekniffen bin auch ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Siehe, mein Schrecken wird dich nicht ängstigen, und mein Druck wird nicht schwer auf dir lasten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Fürwahr, du hast vor meinen Ohren gesprochen, und ich hörte die Stimme der Worte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Ich bin rein, ohne Übertretung; ich bin makellos, und keine Ungerechtigkeit ist an mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Siehe, er erfindet Feindseligkeiten wider mich; er hält mich für seinen Feind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Er legt meine Füße in den Stock, beobachtet alle meine Pfade. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Siehe, darin hast du nicht recht, antworte ich dir; denn Gott ist erhabener als ein Mensch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Warum hast du wider ihn gehadert? Denn über all sein Tun gibt er keine Antwort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Doch in einer Weise redet Gott und in zweien, ohne daß man es beachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Im Traume, im Nachtgesicht, wenn tiefer Schlaf die Menschen befällt, im Schlummer auf dem Lager:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'dann öffnet er das Ohr der Menschen und besiegelt die Unterweisung, die er ihnen gibt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'um den Menschen von seinem Tun abzuwenden, und auf daß er Übermut vor dem Manne verberge;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'daß er seine Seele zurückhalte von der Grube, und sein Leben vom Rennen ins Geschoß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Auch wird er gezüchtigt mit Schmerzen auf seinem Lager und mit beständigem Kampf in seinen Gebeinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Und sein Leben verabscheut das Brot, und seine Seele die Lieblingsspeise;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'sein Fleisch zehrt ab, daß man es nicht mehr sieht, und entblößt sind seine Knochen, die nicht gesehen wurden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'und seine Seele nähert sich der Grube, und sein Leben den Würgern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Wenn es nun für ihn einen Gesandten gibt, einen Ausleger, einen aus tausend, um dem Menschen seine Geradheit kundzutun,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'so wird er sich seiner erbarmen und sprechen: Erlöse ihn, daß er nicht in die Grube hinabfahre; ich habe eine Sühnung gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Sein Fleisch wird frischer sein als in der Jugend; er wird zurückkehren zu den Tagen seiner Jünglingskraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Er wird zu Gott flehen, und Gott wird ihn wohlgefällig annehmen, und er wird sein Angesicht schauen mit Jauchzen; und Gott wird dem Menschen seine Gerechtigkeit vergelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Er wird von den Menschen singen und sagen: Ich hatte gesündigt und die Geradheit verkehrt, und es ward mir nicht vergolten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'er hat meine Seele erlöst, daß sie nicht in die Grube fahre, und mein Leben erfreut sich des Lichtes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Siehe, das alles tut Gott zwei-,dreimal mit dem Manne,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'um seine Seele abzuwenden von der Grube, daß sie erleuchtet werde von dem Lichte der Lebendigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Merke auf, Hiob, höre mir zu; schweige, und ich will reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Wenn du Worte hast, so antworte mir; rede, denn ich wünsche dich zu rechtfertigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Wenn nicht, so höre du mir zu; schweige, und ich werde dich Weisheit lehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Und Elihu hob wieder an und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Höret, ihr Weisen, meine Worte, und ihr Kundigen, gebet mir Gehör!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Denn das Ohr prüft die Worte, wie der Gaumen die Speise kostet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Erwählen wir für uns, was recht, erkennen wir unter uns, was gut ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Denn Hiob hat gesagt: Ich bin gerecht, und Gott hat mir mein Recht entzogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Trotz meines Rechtes soll ich lügen; meine Wunde ist unheilbar, ohne daß ich übertreten habe. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Wer ist ein Mann wie Hiob, der Hohn trinkt wie Wasser,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'und in Gesellschaft geht mit denen, die Frevel tun, und wandelt mit gottlosen Menschen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Denn er hat gesagt: Keinen Nutzen hat ein Mann davon, daß er Wohlgefallen an Gott hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Darum höret mir zu, ihr Männer von Verstand! Fern sei Gott von Gesetzlosigkeit, und der Allmächtige von Unrecht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Sondern des Menschen Tun vergilt er ihm, und nach jemandes Wege läßt er es ihn finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Ja, wahrlich, Gott handelt nicht gesetzlos, und der Allmächtige beugt nicht das Recht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Wer hat ihm die Erde anvertraut? Und wer den ganzen Erdkreis gegründet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Wenn er sein Herz nur auf sich selbst richtete, seinen Geist und seinen Odem an sich zurückzöge,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'so würde alles Fleisch insgesamt verscheiden, und der Mensch zum Staube zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Und wenn du doch dieses einsehen und hören, der Stimme meiner Worte Gehör schenken wolltest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Sollte auch herrschen, wer das Recht haßt? Oder willst du den Allgerechten verdammen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Sagt man zu einem Könige: Belial, zu Edlen: Du Gottloser? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Wieviel weniger zu ihm, der die Person der Fürsten nicht ansieht und den Reichen nicht vor dem Armen berücksichtigt! Denn sie alle sind das Werk seiner Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'In einem Augenblick sterben sie; und in der Mitte der Nacht wird ein Volk erschüttert und vergeht, und Mächtige werden beseitigt ohne Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Denn seine Augen sind auf die Wege des Menschen gerichtet, und er sieht alle seine Schritte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Da ist keine Finsternis und kein Todesschatten, daß sich darein verbergen könnten, die Frevel tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Denn er braucht nicht lange auf einen Menschen acht zu geben, damit er vor Gott ins Gericht komme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Er zerschmettert Gewaltige ohne Untersuchung, und setzt andere an ihre Stelle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Daher kennt er ihre Handlungen, und kehrt sie um über Nacht; und sie werden zermalmt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Er schlägt sie, wie Übeltäter, auf öffentlichem Platze,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'darum daß sie von seiner Nachfolge abgewichen sind und alle seine Wege nicht bedacht haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'um zu ihm hinaufdringen zu lassen das Schreien des Armen, und damit er das Schreien der Elenden höre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Schafft er Ruhe, wer will beunruhigen? Und verbirgt er das Angesicht, wer kann ihn schauen? So handelt er sowohl gegen ein Volk, als auch gegen einen Menschen zumal,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'damit der ruchlose Mensch nicht regiere, damit sie nicht Fallstricke des Volkes seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Denn hat er wohl zu Gott gesagt: Ich trage meine Strafe, ich will nicht mehr verderbt handeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'was ich nicht sehe, zeige du mir; wenn ich Unrecht verübt habe, so will ich es nicht mehr tun? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Soll nach deinem Sinne er es vergelten? Denn du hast seine Vergeltung verworfen, und so mußt du wählen, und nicht ich; was du weißt, reden denn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Männer von Verstand werden zu mir sagen, und ein weiser Mann, der mir zuhört:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Hiob redet nicht mit Erkenntnis, und seine Worte sind ohne Einsicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Ach, daß doch Hiob fort und fort geprüft würde wegen seiner Antworten nach Frevlerart!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Denn er fügt seiner Sünde Übertretung hinzu, klatscht unter uns in die Hände und mehrt seine Worte gegen Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Und Elihu hob wieder an und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Hältst du das für recht? Du hast gesagt: Meine Gerechtigkeit ist größer als diejenige Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Denn du fragst, was sie dir nütze; was gewinne ich mehr, als wenn ich gesündigt hätte? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Ich will dir Worte erwidern und deinen Genossen mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Blicke gen Himmel und sieh, und schaue die Wolken an, sie sind höher als du.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Wenn du sündigst, was tust du ihm an? Und mehren sich deine Übertretungen, was fügst du ihm zu?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Wenn du gerecht bist, was gibst du ihm, oder was empfängt er aus deiner Hand?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Für einen Mann wie du gilt deine Gesetzlosigkeit etwas, und für ein Menschenkind deine Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Wegen der Menge der Bedrückungen schreit man; man ruft um Hilfe wegen des Armes der Großen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Aber man spricht nicht: Wo ist Gott, mein Schöpfer, der Gesänge gibt in der Nacht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'der uns mehr belehrt als die Tiere der Erde, und uns weiser macht als das Gevögel des Himmels?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Alsdann schreit man, aber er antwortet nicht, wegen des Hochmuts der Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Auf nur Eitles hört Gott nicht, und der Allmächtige schaut es nicht an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Wenn du auch sagst, du schauest ihn nicht, die Rechtssache ist vor ihm; so harre sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Und nun, wenn sein Zorn nicht heimgesucht hat, sollte er nicht sehr wohl um den Übermut wissen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Und so sperrt Hiob eitler Weise seinen Mund auf, häuft Worte ohne Erkenntnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Und Elihu fuhr fort und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Harre mir ein wenig, und ich will dir berichten; denn noch sind Worte da für Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Ich will mein Wissen von weither holen, und meinem Schöpfer Gerechtigkeit geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Denn wahrlich, meine Worte sind keine Lüge; ein an Wissen Vollkommener ist bei dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Siehe, Gott ist mächtig, und doch verachtet er niemand, mächtig an Kraft des Verstandes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Er erhält den Gesetzlosen nicht am Leben, und das Recht der Elenden gewährt er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Er zieht seine Augen nicht ab von dem Gerechten, und mit Königen auf den Thron, dahin setzt er sie auf immerdar, und sie sind erhöht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Und wenn sie mit Fesseln gebunden sind, in Stricken des Elends gefangen werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'dann macht er ihnen kund ihr Tun und ihre Übertretungen, daß sie sich trotzig gebärdeten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'und er öffnet ihr Ohr der Zucht und spricht, daß sie umkehren sollen vom Frevel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Wenn sie hören und sich unterwerfen, so werden sie ihre Tage in Wohlfahrt verbringen und ihre Jahre in Annehmlichkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Wenn sie aber nicht hören, so rennen sie ins Geschoß und verscheiden ohne Erkenntnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Aber die ruchlosen Herzens sind, hegen Zorn: sie rufen nicht um Hilfe, wenn er sie gefesselt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Ihre Seele stirbt dahin in der Jugend, und ihr Leben unter den Schandbuben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Den Elenden errettet er in seinem Elend, und in der Drangsal öffnet er ihnen das Ohr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'So hätte er auch dich aus dem Rachen der Bedrängnis in einen weiten Raum geführt, wo keine Beengung gewesen, und die Besetzung deines Tisches würde voll Fett sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Aber du bist mit dem Urteil des Gesetzlosen erfüllt: Urteil und Gericht werden dich ergreifen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Denn der Grimm, möge er dich ja nicht verlocken zur Verhöhnung, und die Größe des Lösegeldes verleite dich nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Soll dich dein Schreien außer Bedrängnis stellen und alle Anstrengungen der Kraft?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Sehne dich nicht nach der Nacht, welche Völker plötzlich hinwegheben wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Hüte dich, wende dich nicht zum Frevel, denn das hast du dem Elend vorgezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Siehe, Gott handelt erhaben in seiner Macht; wer ist ein Lehrer wie er?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Wer hat ihm seinen Weg vorgeschrieben, und wer dürfte sagen: Du hast Unrecht getan?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Gedenke daran, daß du sein Tun erhebest, welches Menschen besingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Alle Menschen schauen es an, der Sterbliche erblickt es aus der Ferne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Siehe, Gott ist zu erhaben für unsere Erkenntnis; die Zahl seiner Jahre, sie ist unerforschlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Denn er zieht Wassertropfen herauf; von dem Dunst, den er bildet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'träufeln sie als Regen, den die Wolken rieseln und tropfen lassen auf viele Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Versteht man gar das Ausbreiten des Gewölks, das Krachen seines Zeltes?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Siehe, er breitet sein Licht um sich aus, und die Gründe des Meeres bedeckt er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Denn durch dieses richtet er Völker, gibt Speise im Überfluß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Seine Hände umhüllt er mit dem Blitz, und er entbietet ihn gegen denjenigen, den er treffen soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Sein Rollen kündigt ihn an, sogar das Vieh sein Heranziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Ja, darüber erzittert mein Herz und bebt auf von seiner Stelle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Höret, höret das Getöse seiner Stimme und das Gemurmel, das aus seinem Munde hervorgeht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Er sendet es aus unter den ganzen Himmel, und seinen Blitz bis zu den Säumen der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Nach dem Blitze brüllt eine Stimme; er donnert mit seiner erhabenen Stimme, und hält die Blitze nicht zurück, wenn seine Stimme gehört wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Gott donnert wunderbar mit seiner Stimme; er tut große Dinge, die wir nicht begreifen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Denn zum Schnee spricht er: Falle zur Erde! und zum Regengusse und den Güssen seines gewaltigen Regens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Er lähmt die Hand eines jeden Menschen, damit alle Menschen sein Werk kennen lernen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Und das Wild geht in sein Versteck und bleibt in seinen Höhlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Aus der Kammer des Südens kommt Sturm, und von den Nordwinden Kälte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Durch den Odem Gottes entsteht Eis, und die Breite der Wasser zieht sich zusammen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Auch beladet er mit Wasserfülle das Gewölk, breitet weithin aus seine Blitzwolken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Und unter seiner Leitung wenden sie sich ringsumher zu ihrem Werke, zu allem, was er ihnen gebietet, über die Fläche des Erdkreises hin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'sei es, daß er sie zur Geißel, oder für seine Erde, oder zur Erweisung seiner Gnade sich entladen läßt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Nimm dieses zu Ohren, Hiob; stehe und betrachte die Wunder Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Weißt du, wie Gott sie beladet, und leuchten läßt den Blitz seines Gewölks?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Verstehst du dich auf das Schweben der Wolke, auf die Wundertaten des an Wissen Vollkommenen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Du, dessen Kleider heiß werden, wenn das Land schwül wird von Süden her,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'kannst du, gleich ihm, das Himmelsgewölbe ausbreiten, fest wie ein gegossener Spiegel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Tue uns kund, was wir ihm sagen sollen! Wir können vor Finsternis nichts vorbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Soll ihm gemeldet werden, daß ich reden wolle? Wenn jemand zu ihm spricht, er wird gewiß verschlungen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Und jetzt sieht man das Licht nicht, welches leuchtet am Himmelsgewölbe; aber ein Wind fährt daher und reinigt dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Aus dem Norden kommt Gold: um Gott ist furchtbare Pracht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'den Allmächtigen, den erreichen wir nicht, den Erhabenen an Kraft; und das Recht und der Gerechtigkeit Fülle beugt er nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Darum fürchten ihn die Menschen; er sieht keine an, die weisen Herzens sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Und Jehova antwortete Hiob aus dem Sturme und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Wer ist es, der den Rat verdunkelt mit Worten ohne Erkenntnis?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Gürte doch wie ein Mann deine Lenden; so will ich dich fragen, und du belehre mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Wo warst du, als ich die Erde gründete? Tue es kund, wenn du Einsicht besitzest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Wer hat ihre Maße bestimmt, wenn du es weißt? Oder wer hat über sie die Meßschnur gezogen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'In was wurden ihre Grundfesten eingesenkt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Oder wer hat ihren Eckstein gelegt, als die Morgensterne miteinander jubelten und alle Söhne Gottes jauchzten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Und wer hat das Meer mit Toren verschlossen, als es ausbrach, hervorkam aus dem Mutterschoße,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'als ich Gewölk zu seinem Gewande und Wolkendunkel zu seiner Windel machte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'und ich ihm meine Grenze bestimmte und Riegel und Tore setzte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'und sprach: Bis hierher sollst du kommen und nicht weiter, und hier sei eine Schranke gesetzt dem Trotze deiner Wellen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Hast du, seitdem du lebst, einem Morgen geboten? Hast du die Morgenröte ihre Stätte wissen lassen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'daß sie erfasse die Säume der Erde, und die Gesetzlosen von ihr verscheucht werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Sie verwandelt sich wie Siegelton, und alles steht da wie in einem Gewande;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'und den Gesetzlosen wird ihr Licht entzogen, und der erhobene Arm wird zerbrochen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Bist du gekommen bis zu den Quellen des Meeres, und hast du die Gründe der Tiefe durchwandelt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Wurden dir die Pforten des Todes enthüllt, und sahest du die Pforten des Todesschattens?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Hast du Einsicht genommen in die Breiten der Erde? Sage an, wenn du es alles weißt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Welches ist der Weg zur Wohnung des Lichtes, und die Finsternis, wo ist ihre Stätte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Daß du sie hinbrächtest zu ihrer Grenze, und daß du der Pfade zu ihrem Hause kundig wärest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Du weißt es ja; denn damals wurdest du geboren, und die Zahl deiner Tage ist groß!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Bist du zu den Vorräten des Schnees gekommen, und hast du gesehen die Vorräte des Hagels,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'die ich aufgespart habe für die Zeit der Bedrängnis, für den Tag des Kampfes und der Schlacht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Welches ist der Weg, auf dem das Licht sich verteilt, der Ostwind sich verbreitet über die Erde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Wer teilt der Regenflut Kanäle ab und einen Weg dem Donnerstrahle,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'um regnen zu lassen auf ein Land ohne Menschen, auf die Wüste, in welcher kein Mensch ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'um zu sättigen die Öde und Verödung, und um hervorsprießen zu lassen die Triebe des Grases?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Hat der Regen einen Vater, oder wer zeugt die Tropfen des Taues?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Aus wessen Schoße kommt das Eis hervor, und des Himmels Reif, wer gebiert ihn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Wie das Gestein verdichten sich die Wasser, und die Fläche der Tiefe schließt sich zusammen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Kannst du knüpfen das Gebinde des Siebengestirns, oder lösen die Fesseln des Orion?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Kannst du die Bilder des Tierkreises hervortreten lassen zu ihrer Zeit, und den großen Bären leiten samt seinen Kindern?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Kennst du die Gesetze des Himmels, oder bestimmst du seine Herrschaft über die Erde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Kannst du deine Stimme zum Gewölk erheben, daß eine Menge Wassers dich bedecke?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Kannst du Blitze entsenden, daß sie hinfahren, daß sie zu dir sagen: Hier sind wir? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Wer hat Weisheit in die Nieren gelegt, oder wer hat dem Geiste Verstand gegeben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Wer zählt die Wolken mit Weisheit, und des Himmels Schläuche, wer gießt sie aus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'wenn der Staub zu dichtem Gusse zusammenfließt und die Schollen aneinander kleben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Erjagst du der Löwin den Raub, und stillst du die Gier der jungen Löwen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'wenn sie in den Höhlen kauern, im Dickicht auf der Lauer sitzen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Wer bereitet dem Raben seine Speise, wenn seine Jungen zu Gott schreien, umherirren ohne Nahrung?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Weißt du die Gebärzeit der Steinböcke? Beobachtest du das Kreißen der Hindinnen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Zählst du die Monde, die sie erfüllen, und weißt du die Zeit ihres Gebärens?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Sie krümmen sich, lassen ihre Jungen durchbrechen, entledigen sich ihrer Wehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Ihre Kinder werden stark, wachsen auf im Freien; sie gehen aus und kehren nicht zu ihnen zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Wer hat den Wildesel frei entsandt, und wer gelöst die Bande des Wildlings,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'zu dessen Hause ich die Steppe gemacht, und zu seinen Wohnungen das Salzland?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Er lacht des Getümmels der Stadt, das Geschrei des Treibers hört er nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Was er auf den Bergen erspäht, ist seine Weide, und allem Grünen spürt er nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Wird der Wildochs dir dienen wollen, oder wird er an deiner Krippe übernachten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Wirst du den Wildochs mit seinem Seile an die Furche binden, oder wird er hinter dir her die Talgründe eggen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Wirst du ihm trauen, weil seine Kraft groß ist, und ihm deine Arbeit überlassen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Wirst du auf ihn dich verlassen, daß er deine Saat heimbringe, und daß er das Getreide deiner Tenne einscheuere?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Fröhlich schwingt sich der Flügel der Straußin: ist es des Storches Fittich und Gefieder?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Denn sie überläßt ihre Eier der Erde und erwärmt sie auf dem Staube;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'und sie vergißt, daß ein Fuß sie zerdrücken und das Getier des Feldes sie zertreten kann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Sie behandelt ihre Kinder hart, als gehörten sie ihr nicht; ihre Mühe ist umsonst, es kümmert sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Denn Gott ließ sie der Weisheit vergessen, und keinen Verstand teilte er ihr zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Zur Zeit, wenn sie sich in die Höhe peitscht, lacht sie des Rosses und seines Reiters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Gibst du dem Rosse Stärke, bekleidest du seinen Hals mit der wallenden Mähne?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Machst du es aufspringen gleich der Heuschrecke? Sein prächtiges Schnauben ist Schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Es scharrt in der Ebene und freut sich der Kraft, zieht aus, den Waffen entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Es lacht der Furcht und erschrickt nicht, und kehrt vor dem Schwerte nicht um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Auf ihm klirrt der Köcher, der blitzende Speer und Wurfspieß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Mit Ungestüm und Zorn schlürft es den Boden, und läßt sich nicht halten, wenn die Posaune ertönt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Beim Schall der Posaune ruft es: Hui! und aus der Ferne wittert es die Schlacht, den Donnerruf der Heerführer und das Feldgeschrei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Schwingt sich der Habicht durch deinen Verstand empor, breitet seine Flügel aus gegen Süden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Oder erhebt sich auf deinen Befehl der Adler, und baut in der Höhe sein Nest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'In den Felsen wohnt und verweilt er, auf Felsenzacken und den Spitzen der Berge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Von dort aus erspäht er Nahrung, in die Ferne blicken seine Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Und seine Jungen schlürfen Blut, und wo Erschlagene sind, da ist er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, '(H39:31) Und Jehova antwortete Hiob und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, '(H39:32) Will der Tadler rechten mit dem Allmächtigen? Der da Gott zurechtweist, antworte darauf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, '(H39:33) Und Hiob antwortete Jehova und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, '(H39:34) Siehe, zu gering bin ich, was soll ich dir erwidern? Ich lege meine Hand auf meinen Mund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, '(H39:35) Einmal habe ich geredet, und ich will nicht mehr antworten, und zweimal, und ich will es nicht mehr tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, '(H40:1) Und Jehova antwortete Hiob aus dem Sturme und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, '(H40:2) Gürte doch wie ein Mann deine Lenden; ich will dich fragen, und du belehre mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, '(H40:3) Willst du gar mein Recht zunichte machen, mich verdammen, damit du gerecht seiest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, '(H40:4) Oder hast du einen Arm wie Gott, und kannst du donnern mit einer Stimme wie er?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, '(H40:5) Schmücke dich doch mit Erhabenheit und Hoheit, und kleide dich in Pracht und Majestät!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, '(H40:6) Gieße aus die Ausbrüche deines Zornes, und sieh an alles Hoffärtige und erniedrige es!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, '(H40:7) Sieh an alles Hoffärtige, beuge es, und reiße nieder die Gesetzlosen auf ihrer Stelle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, '(H40:8) Verbirg sie allesamt in den Staub, schließe ihre Angesichter in Verborgenheit ein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, '(H40:9) Dann werde auch ich dich preisen, daß deine Rechte dir Hilfe schafft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, '(H40:10) Sieh doch den Behemoth, den ich mit dir gemacht habe; er frißt Gras wie das Rind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, '(H40:11) Sieh doch, seine Kraft ist in seinen Lenden, und seine Stärke in den Muskeln seines Bauches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, '(H40:12) Er biegt seinen Schwanz gleich einer Zeder, die Sehnen seiner Schenkel sind verflochten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, '(H40:13) Seine Knochen sind Röhren von Erz, seine Gebeine gleich Barren von Eisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, '(H40:14) Er ist der Erstling der Wege Gottes; der ihn gemacht, hat ihm sein Schwert beschafft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, '(H40:15) Denn die Berge tragen ihm Futter, und daselbst spielt alles Getier des Feldes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, '(H40:16) Unter Lotosbüschen legt er sich nieder, im Versteck von Rohr und Sumpf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, '(H40:17) Lotosbüsche bedecken ihn mit ihrem Schatten, es umgeben ihn die Weiden des Baches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, '(H40:18) Siehe, der Strom schwillt mächtig an, er flieht nicht ängstlich davon; er bleibt wohlgemut, wenn ein Jordan gegen sein Maul hervorbricht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, '(H40:19) Fängt man ihn wohl vor seinen Augen, durchbohrt man ihm die Nase mit einem Fangseile?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, '(H40:20) Ziehst du den Leviathan herbei mit der Angel, und senkst du seine Zunge in die Angelschnur?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, '(H40:21) Kannst du einen Binsenstrick durch seine Nase ziehen, und seinen Kinnbacken mit einem Ringe durchbohren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, '(H40:22) Wird er viel Flehens an dich richten, oder dir sanfte Worte geben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, '(H40:23) Wird er einen Bund mit dir machen, daß du ihn zum ewigen Knechte nehmest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, '(H40:24) Wirst du mit ihm spielen wie mit einem Vogel, und ihn anbinden für deine Mädchen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, '(H40:25) Werden die Fischergenossen ihn verhandeln, ihn verteilen unter Kaufleute?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, '(H40:26) Kannst du seine Haut mit Spießen füllen, und seinen Kopf mit Fischharpunen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, '(H40:27) Lege deine Hand an ihn, gedenke des Kampfes, tue es nicht wieder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, '(H41:1) Siehe, eines jeden Hoffnung wird betrogen: wird man nicht schon bei seinem Anblick niedergeworfen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, '(H41:1) Niemand ist so kühn, daß er ihn aufreize. Und wer ist es, der sich vor mein Angesicht stellen dürfte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, '(H41:2) Wer hat mir zuvor gegeben? Und ich werde ihm vergelten. Was unter dem ganzen Himmel ist, ist mein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, '(H41:3) Nicht schweigen will ich von seinen Gliedern und von seiner Kraftfülle und von der Schönheit seines Baues.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, '(H41:4) Wer deckte die Oberfläche seines Gewandes auf? In sein Doppelgebiß, wer dringt da hinein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, '(H41:5) Wer tat die Pforte seines Angesichts auf? Der Kreis seiner Zähne ist ein Schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, '(H41:6) Ein Stolz sind seine starken Schilder, jedes einzelne verschlossen mit festem Siegel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, '(H41:7) Eines fügt sich ans andere, und keine Luft dringt dazwischen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, '(H41:8) Stück an Stück hangen sie fest zusammen, greifen ineinander und trennen sich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, '(H41:9) Sein Niesen strahlt Licht aus, und seine Augen sind gleich den Wimpern der Morgenröte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, '(H41:10) Aus seinem Rachen gehen Fackeln, sprühen feurige Funken hervor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, '(H41:11) Aus seinen Nüstern fährt Rauch, wie aus einem siedenden Topfe und Kessel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, '(H41:12) Sein Hauch entzündet Kohlen, und eine Flamme fährt aus seinem Rachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, '(H41:13) In seinem Halse wohnt Stärke, und die Angst hüpft vor ihm her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, '(H41:14) Die Wampen seines Fleisches schließen an, sind ihm fest angegossen, unbeweglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, '(H41:15) Sein Herz ist hart wie Stein, und hart wie ein unterer Mühlstein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, '(H41:16) Vor seinem Erheben fürchten sich Starke, vor Verzagtheit geraten sie außer sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, '(H41:17) Trifft man ihn mit dem Schwerte, es hält nicht stand, noch Speer, noch Wurfspieß, noch Harpune.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, '(H41:18) Das Eisen achtet er für Stroh, das Erz für faules Holz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, '(H41:19) Der Pfeil jagt ihn nicht in die Flucht, Schleudersteine verwandeln sich ihm in Stoppeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, '(H41:20) Wie Stoppeln gilt ihm die Keule, und er verlacht das Sausen des Wurfspießes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, '(H41:21) Unter ihm sind scharfe Scherben; einen Dreschschlitten breitet er hin auf den Schlamm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, '(H41:22) Er macht die Tiefe sieden wie einen Topf, macht das Meer wie einen Salbenkessel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, '(H41:23) Hinter ihm leuchtet der Pfad, man könnte die Tiefe für graues Haar halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, '(H41:24) Auf Erden ist keiner ihm gleich, der geschaffen ist ohne Furcht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, '(H41:25) Alles Hohe sieht er an; er ist König über alle wilden Tiere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Und Hiob antwortete Jehova und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Ich weiß, daß du alles vermagst, und kein Vorhaben dir verwehrt werden kann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Wer ist es, der den Rat verhüllt ohne Erkenntnis? So habe ich denn beurteilt, was ich nicht verstand, Dinge, zu wunderbar für mich, die ich nicht kannte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Höre doch, und ich will reden; ich will dich fragen, und du belehre mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Mit dem Gehör des Ohres hatte ich von dir gehört, aber nun hat mein Auge dich gesehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Darum verabscheue ich mich und bereue in Staub und Asche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Und es geschah, nachdem Jehova diese Worte zu Hiob geredet hatte, da sprach Jehova zu Eliphas, dem Temaniter: Mein Zorn ist entbrannt wider dich und wider deine beiden Freunde; denn nicht geziemend habt ihr von mir geredet, wie mein Knecht Hiob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Und nun nehmet euch sieben Farren und sieben Widder, und gehet zu meinem Knechte Hiob und opfert ein Brandopfer für euch. Und Hiob, mein Knecht, möge für euch bitten; denn ihn will ich annehmen, damit ich nicht an euch tue nach eurer Torheit; denn nicht geziemend habt ihr von mir geredet, wie mein Knecht Hiob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Da gingen Eliphas, der Temaniter, und Bildad, der Schuchiter, und Zophar, der Naamathiter, und taten, wie Jehova zu ihnen geredet hatte; und Jehova nahm Hiob an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Und Jehova wendete die Gefangenschaft Hiobs, als er für seine Freunde betete; und Jehova mehrte alles, was Hiob gehabt hatte, um das Doppelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Und es kamen zu ihm alle seine Brüder und alle seine Schwestern und alle seine früheren Bekannten; und sie aßen mit ihm in seinem Hause, und sie bezeugten ihm ihr Beileid und trösteten ihn über all das Unglück, welches Jehova über ihn gebracht hatte; und sie gaben ihm ein jeder eine Kesita, und ein jeder einen goldenen Ring.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Und Jehova segnete das Ende Hiobs mehr als seinen Anfang; und er bekam vierzehntausend Stück Kleinvieh und sechstausend Kamele und tausend Joch Rinder und tausend Eselinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Und es wurden ihm sieben Söhne und drei Töchter geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Und er gab der ersten den Namen Jemima, und der zweiten den Namen Kezia, und der dritten den Namen Keren-Happuk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Und so schöne Frauen wie die Töchter Hiobs wurden im ganzen Lande nicht gefunden. Und ihr Vater gab ihnen ein Erbteil inmitten ihrer Brüder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Und Hiob lebte nach diesem hundertvierzig Jahre; und er sah seine Kinder und seine Kindeskinder, vier Geschlechter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Und Hiob starb, alt und der Tage satt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Glückselig der Mann, der nicht wandelt im Rate der Gottlosen, und nicht steht auf dem Wege der Sünder, und nicht sitzt auf dem Sitze der Spötter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'sondern seine Lust hat am Gesetz Jehovas und über sein Gesetz sinnt Tag und Nacht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Und er ist wie ein Baum, gepflanzt an Wasserbächen, der seine Frucht bringt zu seiner Zeit, und dessen Blatt nicht verwelkt; und alles, was er tut, gelingt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Nicht so die Gesetzlosen, sondern sie sind wie die Spreu, die der Wind dahintreibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Darum werden die Gesetzlosen nicht bestehen im Gericht, noch die Sünder in der Gemeinde der Gerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Denn Jehova kennt den Weg der Gerechten; aber der Gesetzlosen Weg wird vergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Warum toben die Nationen und sinnen Eitles die Völkerschaften?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Es treten auf die Könige der Erde, und die Fürsten ratschlagen miteinander wider Jehova und wider seinen Gesalbten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '\"Lasset uns zerreißen ihre Bande, und von uns werfen ihre Seile!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Der im Himmel thront, lacht, der Herr spottet ihrer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Dann wird er zu ihnen reden in seinem Zorn, und in seiner Zornglut wird er sie schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '\"Habe doch ich meinen König gesalbt auf Zion, meinem heiligen Berge!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Vom Beschluß will ich erzählen: Jehova hat zu mir gesprochen: Du bist mein Sohn, heute habe ich dich gezeugt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Fordere von mir, und ich will dir zum Erbteil geben die Nationen, und zum Besitztum die Enden der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Mit eisernem Zepter wirst du sie zerschmettern, wie ein Töpfergefäß sie zerschmeißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Und nun, ihr Könige, seid verständig, lasset euch zurechtweisen, ihr Richter der Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Dienet Jehova mit Furcht, und freuet euch mit Zittern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Küsset den Sohn, daß er nicht zürne, und ihr umkommet auf dem Wege, wenn nur ein wenig entbrennt sein Zorn. Glückselig alle, die auf ihn trauen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Ein Psalm von David, als er vor seinem Sohne Absalom floh. Jehova! wie viele sind meiner Bedränger! Viele erheben sich wider mich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'viele sagen von meiner Seele: Es ist keine Rettung für ihn bei Gott! (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Du aber, Jehova, bist ein Schild um mich her, meine Herrlichkeit, und der mein Haupt emporhebt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Mit meiner Stimme rufe ich zu Jehova, und er antwortet mir von seinem heiligen Berge. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Ich legte mich nieder und schlief; ich erwachte, denn Jehova stützt mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Nicht fürchte ich mich vor Zehntausenden des Volkes, die sich ringsum wider mich gesetzt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Stehe auf, Jehova! Rette mich, mein Gott! Denn du hast alle meine Feinde auf den Backen geschlagen; die Zähne der Gesetzlosen hast du zerschmettert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Von Jehova ist die Rettung; dein Segen ist auf deinem Volke. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Dem Vorsänger mit Saitenspiel. Ein Psalm von David. Wenn ich rufe, antworte mir, Gott meiner Gerechtigkeit! In Bedrängnis hast du mir Raum gemacht; sei mir gnädig und höre mein Gebet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Ihr Männersöhne, bis wann soll meine Herrlichkeit zur Schande sein? Bis wann werdet ihr Eitles lieben, Lüge suchen? (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Erkennet doch, daß Jehova den Frommen für sich abgesondert hat! Jehova wird hören, wenn ich zu ihm rufe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Seid erregt, und sündiget nicht! Denket nach in eurem Herzen auf eurem Lager, und seid stille! (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Opfert Opfer der Gerechtigkeit, und vertrauet auf Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Viele sagen: Wer wird uns Gutes schauen lassen? Erhebe, Jehova über uns das Licht deines Angesichts!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Du hast Freude in mein Herz gegeben, mehr als zur Zeit, da ihres Kornes und ihres Mostes viel war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'In Frieden werde ich sowohl mich niederlegen als auch schlafen; denn du, Jehova, allein lässest mich in Sicherheit wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Dem Vorsänger, zu Nechiloth. Ein Psalm von David. Nimm zu Ohren, Jehova, meine Worte, merke auf mein Nachsinnen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Horche auf die Stimme meines Schreiens, mein König und mein Gott! Denn zu dir bete ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Frühe wirst du, Jehova, meine Stimme hören, frühe werde ich mein Anliegen dir vorstellen und harren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Denn nicht ein Gott bist du, der an Gesetzlosigkeit Gefallen hat; bei dir wird das Böse nicht weilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Nicht werden die Toren bestehen vor deinen Augen; du hassest alle, die Frevel tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Du wirst vertilgen die Lügenredner; den Mann des Blutes und des Truges verabscheut Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Ich aber, ich werde in der Größe deiner Güte eingehen in dein Haus, ich werde anbeten in deiner Furcht gegen deinen heiligen Tempel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Leite mich, Jehova, in deiner Gerechtigkeit um meiner Feinde willen; ebne vor mir deinen Weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Denn in ihrem Munde ist nichts Zuverlässiges; ihr Inneres ist Verderben, ein offenes Grab ihr Schlund; ihre Zunge glätten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Laß sie büßen, o Gott; mögen sie fallen durch ihre Anschläge! Stoße sie hinweg wegen der Menge ihrer Übertretungen! Denn sie sind widerspenstig gegen dich gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'So werden sich freuen alle, die auf dich trauen: ewig werden sie jubeln, und du wirst sie beschirmen; und in dir werden frohlocken, die deinen Namen lieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Denn du wirst den Gerechten segnen; Jehova, mit Gunst wirst du ihn umgeben wie mit einem Schilde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Dem Vorsänger, mit Saitenspiel, auf der Scheminith. Ein Psalm von David. Jehova, strafe mich nicht in deinem Zorn, und züchtige mich nicht in deinem Grimm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Sei mir gnädig, Jehova! Denn ich bin dahingewelkt; heile mich, Jehova! Denn meine Gebeine sind bestürzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Und sehr bestürzt ist meine Seele... Und du, Jehova, bis wann?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Kehre um, Jehova, befreie meine Seele; rette mich um deiner Güte willen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Denn im Tode gedenkt man deiner nicht; im Scheol, wer wird dich preisen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Müde bin ich durch mein Seufzen; jede Nacht schwemme ich mein Bett, mache mit meinen Tränen mein Lager zerfließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Verfallen ist mein Auge vor Gram, gealtert ob all meiner Bedränger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Weichet von mir alle, die ihr Frevel tut! Denn Jehova hat gehört die Stimme meines Weinens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Jehova hat mein Flehen gehört; mein Gebet nahm Jehova an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Alle meine Feinde werden beschämt und sehr bestürzt werden; sie werden umkehren, sie werden plötzlich beschämt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Schiggajon, von David, das er Jehova sang wegen der Worte Kusch\', des Benjaminiters. Jehova, mein Gott, auf dich traue ich; rette mich von allen meinen Verfolgern und befreie mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Daß er nicht meine Seele zerreiße wie ein Löwe, sie zermalmend, und kein Erretter ist da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Jehova, mein Gott! Wenn ich solches getan habe, wenn Unrecht in meinen Händen ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'wenn ich Böses vergolten dem, der mit mir im Frieden war, habe ich doch den befreit, der mich ohne Ursache bedrängte');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'so verfolge der Feind meine Seele und erreiche sie, und trete mein Leben zu Boden und strecke meine Ehre hin in den Staub. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Stehe auf, Jehova, in deinem Zorn! Erhebe dich wider das Wüten meiner Bedränger, und wache auf zu mir: Gericht hast du befohlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Und die Schar der Völkerschaften wird dich umringen; und ihretwegen kehre wieder zur Höhe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Jehova wird die Völker richten. Richte mich, Jehova, nach meiner Gerechtigkeit und nach meiner Lauterkeit, die bei mir ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Laß doch ein Ende nehmen die Bosheit der Gesetzlosen, und befestige den Gerechten! Es prüft ja Herzen und Nieren der gerechte Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Mein Schild ist bei Gott, der die von Herzen Aufrichtigen rettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Gott ist ein gerechter Richter, und ein Gott, der jeden Tag zürnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Wenn er nicht umkehrt, so wetzt er sein Schwert; seinen Bogen hat er gespannt und ihn gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Und Werkzeuge des Todes hat er für ihn bereitet, seine Pfeile macht er brennend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Siehe, er ist in Geburtswehen mit Unheil; und, schwanger mit Mühsal, gebiert er Falschheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Er hat eine Grube gegraben und hat sie ausgehöhlt, und er ist in die Grube gefallen, die er gemacht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Seine Mühsal wird zurückkehren auf sein Haupt, und auf seinen Scheitel wird herabstürzen seine Gewalttat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Ich will Jehova preisen nach seiner Gerechtigkeit, und besingen den Namen Jehovas, des Höchsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Dem Vorsänger, auf der Gittith. Ein Psalm von David. Jehova, unser Herr, wie herrlich ist dein Name auf der ganzen Erde, der du deine Majestät gestellt hast über die Himmel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Aus dem Munde der Kinder und Säuglinge hast du Macht gegründet um deiner Bedränger willen, um zum Schweigen zu bringen den Feind und den Rachgierigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Wenn ich anschaue deinen Himmel, deiner Finger Werk, den Mond und die Sterne, die du bereitet hast:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Was ist der Mensch, daß du sein gedenkst, und des Menschen Sohn, daß du auf ihn achthast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Denn ein wenig hast du ihn unter die Engel erniedrigt; und mit Herrlichkeit und Pracht hast du ihn gekrönt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Du hast ihn zum Herrscher gemacht über die Werke deiner Hände; alles hast du unter seine Füße gestellt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Schafe und Rinder allesamt und auch die Tiere des Feldes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'das Gevögel des Himmels und die Fische des Meeres, was die Pfade der Meere durchwandert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Jehova, unser Herr, wie herrlich ist dein Name auf der ganzen Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Dem Vorsänger, nach Muth Labben. Ein Psalm von David. Ich will Jehova preisen mit meinem ganzen Herzen, will erzählen alle deine Wundertaten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'In dir will ich mich freuen und frohlocken, will deinen Namen besingen, o Höchster!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Als meine Feinde sich zurückwandten, strauchelten sie und kamen um vor deinem Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Denn du hast ausgeführt mein Recht und meine Rechtssache; du hast dich auf den Thron gesetzt, ein gerechter Richter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Du hast die Nationen gescholten, den Gesetzlosen vertilgt; ihren Namen hast du ausgelöscht für immer und ewig; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'O Feind! Zu Ende sind die Trümmer für immer; auch hast du Städte zerstört: ihr, ja, ihr Gedächtnis ist verschwunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Jehova aber thront ewiglich; er hat seinen Thron aufgestellt zum Gericht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Und er, er wird den Erdkreis richten in Gerechtigkeit, wird über die Völkerschaften Gericht halten in Geradheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Und Jehova wird eine hohe Feste sein dem Unterdrückten, eine hohe Feste in Zeiten der Drangsal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Und auf dich werden vertrauen, die deinen Namen kennen; denn du hast nicht verlassen, die dich suchen, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Singet Psalmen Jehova, der Zion bewohnt, verkündet unter den Völkern seine Taten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Denn der dem vergossenen Blute nachforscht, hat ihrer gedacht; er hat das Schreien der Elenden nicht vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Sei mir gnädig, Jehova! Sieh an mein Elend von seiten meiner Hasser, indem du mich emporhebst aus den Toren des Todes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'auf daß ich all dein Lob erzähle in den Toren der Tochter Zion, frohlocke über deine Rettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Versunken sind die Nationen in die Grube, die sie gemacht; ihr Fuß ward gefangen in dem Netze, das sie heimlich gelegt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Jehova ist bekannt geworden: er hat Gericht ausgeübt, indem er den Gesetzlosen verstrickt hat in dem Werke seiner Hände. (Higgajon, Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Es werden zum Scheol umkehren die Gesetzlosen, alle Nationen, die Gottes vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Denn nicht für immer wird der Arme vergessen sein, noch für ewig verloren die Hoffnung der Sanftmütigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Stehe auf, Jehova! Nicht habe der Mensch die Oberhand; vor deinem Angesicht mögen gerichtet werden die Nationen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Lege Furcht auf sie, Jehova; mögen die Nationen wissen, daß sie Menschen sind! (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Warum, Jehova, stehst du fern, verbirgst dich in Zeiten der Drangsal?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'In seinem Hochmut verfolgt der Gesetzlose hitzig den Elenden. Sie werden erhascht werden in den Anschlägen, die sie ersonnen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Denn der Gesetzlose rühmt sich des Gelüstes seiner Seele; und er segnet den Habsüchtigen, er verachtet Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Der Gesetzlose spricht nach seinem Hochmut: Er wird nicht nachforschen. Alle seine Gedanken sind: Es ist kein Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Es gelingen seine Wege allezeit; hoch sind deine Gerichte, weit von ihm entfernt; alle seine Widersacher, er bläst sie an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Er spricht in seinem Herzen: Ich werde nicht wanken; von Geschlecht zu Geschlecht werde ich in keinem Unglück sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Sein Mund ist voll Fluchens und Truges und Bedrückung; unter seiner Zunge ist Mühsal und Unheil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Er sitzt im Hinterhalt der Dörfer, an verborgenen Örtern ermordet er den Unschuldigen; seine Augen spähen dem Unglücklichen nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Er lauert im Versteck, wie ein Löwe in seinem Dickicht; er lauert, um den Elenden zu erhaschen; er erhascht den Elenden, indem er ihn in sein Netz zieht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Er duckt sich, bückt sich, und in seine starken Klauen fallen die Unglücklichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Er spricht in seinem Herzen: Gott vergißt; er verbirgt sein Angesicht, niemals sieht er\'s!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Stehe auf, Jehova! Gott, erhebe deine Hand! Vergiß nicht der Elenden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Warum verachtet der Gesetzlose Gott, spricht in seinem Herzen, du werdest nicht nachforschen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Du hast es gesehen, denn du, du schaust auf Mühsal und Gram, um zu vergelten durch deine Hand; dir überläßt es der Unglückliche, der Waise Helfer bist du.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Zerbrich den Arm des Gesetzlosen; und der Böse, suche seine Gesetzlosigkeit, bis daß du sie nicht mehr findest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Jehova ist König immer und ewiglich; die Nationen sind umgekommen aus seinem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Den Wunsch der Sanftmütigen hast du gehört, Jehova; du befestigtest ihr Herz, ließest dein Ohr aufmerken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'um Recht zu schaffen der Waise und dem Unterdrückten, daß der Mensch, der von der Erde ist, hinfort nicht mehr schrecke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Dem Vorsänger. Von David. Auf Jehova traue ich; wie saget ihr zu meiner Seele: Fliehet wie ein Vogel nach eurem Berge?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Denn siehe, die Gesetzlosen spannen den Bogen, sie haben ihren Pfeil auf der Sehne gerichtet, um im Finstern zu schießen auf die von Herzen Aufrichtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Wenn die Grundpfeiler umgerissen werden, was tut dann der Gerechte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Jehova ist in seinem heiligen Palast. Jehova, in den Himmeln ist sein Thron; seine Augen schauen, seine Augenlider prüfen die Menschenkinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Jehova prüft den Gerechten; und den Gesetzlosen und den, der Gewalttat liebt, haßt seine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Er wird Schlingen regnen lassen auf die Gesetzlosen; Feuer und Schwefel und Glutwind wird das Teil ihres Bechers sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Denn gerecht ist Jehova, Gerechtigkeiten liebt er. Sein Angesicht schaut den Aufrichtigen an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Dem Vorsänger, auf der Scheminith. Ein Psalm von David. Rette, Jehova! Denn der Fromme ist dahin, denn die Treuen sind verschwunden unter den Menschenkindern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Sie reden Falschheit, ein jeder mit seinem Nächsten; ihre Lippen schmeicheln, mit doppeltem Herzen reden sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Jehova wird ausrotten alle schmeichelnden Lippen, die Zunge, die große Dinge redet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'die da sagen: Wir werden überlegen sein mit unserer Zunge, unsere Lippen sind mit uns; wer ist unser Herr?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Wegen der gewalttätigen Behandlung der Elenden, wegen des Seufzens der Armen will ich nun aufstehen, spricht Jehova; ich will in Sicherheit stellen den, der danach schmachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Die Worte Jehovas sind reine Worte Silber, das geläutert in dem Schmelztiegel zur Erde fließt, siebenmal gereinigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Du, Jehova, wirst sie bewahren, wirst sie behüten vor diesem Geschlecht ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Die Gesetzlosen wandeln ringsumher, wenn die Gemeinheit erhöht ist bei den Menschenkindern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Dem Vorsänger. Ein Psalm von David. Bis wann, Jehova, willst du meiner vergessen immerdar? Bis wann willst du dein Angesicht vor mir verbergen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Bis wann soll ich Ratschläge hegen in meiner Seele, Kummer in meinem Herzen bei Tage? Bis wann soll sich mein Feind über mich erheben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Schaue her, antworte mir, Jehova, mein Gott! Erleuchte meine Augen, daß ich nicht entschlafe zum Tode,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'daß mein Feind nicht sage: Ich habe ihn übermocht! meine Bedränger nicht frohlocken, wenn ich wanke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Ich aber, ich habe auf deine Güte vertraut; mein Herz soll frohlocken über deine Rettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, '(H13:5) Ich will Jehova singen, denn er hat wohlgetan an mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Dem Vorsänger. Von David. Der Tor spricht in seinem Herzen: Es ist kein Gott! Sie haben verderbt gehandelt, sie haben abscheulich getan; da ist keiner, der Gutes tue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Jehova hat vom Himmel herniedergeschaut auf die Menschenkinder, um zu sehen, ob ein Verständiger da sei, einer, der Gott suche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Alle sind abgewichen, sie sind allesamt verderbt; da ist keiner, der Gutes tue, auch nicht einer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Haben keine Erkenntnis alle, die Frevel tun, die mein Volk fressen, als äßen sie Brot? Jehova rufen sie nicht an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Da überfiel sie ein Schrecken, denn Gott ist unter dem gerechten Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Ihr machet zum Hohn den Ratschlag des Elenden, weil Jehova seine Zuflucht ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'O daß aus Zion die Rettung Israels da wäre! Wenn Jehova die Gefangenschaft seines Volkes wendet, soll Jakob frohlocken, Israel sich freuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Ein Psalm; von David. Jehova, wer wird in deinem Zelte weilen? Wer wird wohnen auf deinem heiligen Berge?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Der in Lauterkeit wandelt und Gerechtigkeit wirkt und Wahrheit redet von Herzen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'nicht verleumdet mit seiner Zunge, kein Übel tut seinem Genossen, und keine Schmähung bringt auf seinen Nächsten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'in dessen Augen verachtet ist der Verworfene, der aber die ehrt, welche Jehova fürchten; hat er zum Schaden geschworen, so ändert er es nicht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Der sein Geld nicht auf Zins gibt, und kein Geschenk nimmt wider den Unschuldigen. Wer solches tut, wird nicht wanken in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Ein Gedicht von David. Bewahre mich, Gott, denn ich traue auf dich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Du, meine Seele, hast zu Jehova gesagt: Du bist der Herr; meine Güte reicht nicht hinauf zu dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Du hast zu den Heiligen gesagt, die auf Erden sind, und zu den Herrlichen: An ihnen ist alle meine Lust.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Viele werden der Schmerzen derer sein, die einem anderen nacheilen; ihre Trankopfer von Blut werde ich nicht spenden, und ihre Namen nicht auf meine Lippen nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Jehova ist das Teil meines Erbes und meines Bechers; du erhältst mein Los.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Die Meßschnüre sind mir gefallen in lieblichen Örtern; ja, ein schönes Erbteil ist mir geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Jehova werde ich preisen, der mich beraten hat, selbst des Nachts unterweisen mich meine Nieren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Ich habe Jehova stets vor mich gestellt; weil er zu meiner Rechten ist, werde ich nicht wanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Darum freut sich mein Herz, und frohlockt meine Seele. Auch mein Fleisch wird in Sicherheit ruhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Denn meine Seele wirst du dem Scheol nicht lassen, wirst nicht zugeben, daß dein Frommer die Verwesung sehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Du wirst mir kundtun den Weg des Lebens; Fülle von Freuden ist vor deinem Angesicht, Lieblichkeiten in deiner Rechten immerdar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Ein Gebet; von David. Höre, Jehova, die Gerechtigkeit, horche auf mein Schreien; nimm zu Ohren mein Gebet von Lippen ohne Trug!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Von deiner Gegenwart gehe mein Recht aus; laß deine Augen Aufrichtigkeit anschauen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Du hast mein Herz geprüft, hast mich des Nachts durchforscht; du hast mich geläutert, nichts fandest du; mein Gedanke geht nicht weiter als mein Mund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Was das Tun des Menschen anlangt, so habe ich mich durch das Wort deiner Lippen bewahrt vor den Wegen des Gewalttätigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Meine Schritte hielten fest an deinen Spuren, meine Tritte haben nicht gewankt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Ich, ich habe dich angerufen, denn du erhörest mich, o Gott. Neige dein Ohr zu mir, höre meine Rede!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Erweise wunderbar deine Gütigkeiten, der du durch deine Rechte die auf dich Trauenden rettest vor denen, die sich wider sie erheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Bewahre mich wie den Augapfel im Auge; birg mich in dem Schatten deiner Flügel');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'vor den Gesetzlosen, die mich zerstören, meinen Todfeinden, die mich umzingeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Ihr fettes Herz verschließen sie, mit ihrem Munde reden sie stolz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'In allen unseren Schritten haben sie uns jetzt umringt; sie richten ihre Augen, uns zu Boden zu strecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Er ist gleich einem Löwen, der nach Raub schmachtet, und wie ein junger Löwe, sitzend im Versteck.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Stehe auf, Jehova! Komm ihm zuvor, wirf ihn nieder! Errette meine Seele von dem Gesetzlosen durch dein Schwert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'von den Leuten durch deine Hand, Jehova, von den Leuten dieses Zeitlaufs! Ihr Teil ist in diesem Leben, und ihren Bauch füllst du mit deinem Schatze; sie haben Söhne die Fülle, und ihren Überfluß lassen sie ihren Kindern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Ich, ich werde dein Angesicht schauen in Gerechtigkeit, werde gesättigt werden, wenn ich erwache, mit deinem Bilde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Dem Vorsänger. Von dem Knechte Jehovas, von David, der die Worte dieses Liedes zu Jehova redete an dem Tage, als Jehova ihn errettet hatte aus der Hand aller seiner Feinde und aus der Hand Sauls. Und er sprach: Ich liebe dich, Jehova, meine Stärke!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Jehova ist mein Fels und meine Burg und mein Erretter; mein Gott, mein Hort, auf ihn werde ich trauen, mein Schild und das Horn meines Heils, meine hohe Feste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Ich werde Jehova anrufen, der zu loben ist, und ich werde gerettet werden von meinen Feinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Es umfingen mich die Bande des Todes, und die Ströme Belials erschreckten mich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'die Bande des Scheols umringten mich, es ereilten mich die Fallstricke des Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'In meiner Bedrängnis rief ich zu Jehova, und ich schrie zu meinem Gott; er hörte aus seinem Tempel meine Stimme, und mein Schrei vor ihm kam in seine Ohren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Da wankte und bebte die Erde, und die Grundfesten der Berge erzitterten und wankten, weil er entbrannt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Rauch stieg auf von seiner Nase, und Feuer fraß aus seinem Munde; glühende Kohlen brannten aus ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Und er neigte die Himmel und fuhr hernieder, und Dunkel war unter seinen Füßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Und er fuhr auf einem Cherub und flog daher, und er schwebte auf den Fittichen des Windes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Finsternis machte er zu seinem Bergungsort, zu seinem Zelte rings um sich her, Finsternis der Wasser, dichtes Himmelsgewölk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Aus dem Glanze vor ihm fuhr sein dichtes Gewölk vorüber, Hagel und feurige Kohlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Und es donnerte Jehova in den Himmeln, und der Höchste ließ seine Stimme erschallen, Hagel und feurige Kohlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Und er schoß seine Pfeile und zerstreute sie, und er schleuderte Blitze und verwirrte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Und es wurden gesehen die Betten der Wasser, und die Grundfesten des Erdkreises wurden aufgedeckt vor deinem Schelten, Jehova, vor dem Schnauben des Hauches deiner Nase.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Er streckte seine Hand aus von der Höhe, er nahm mich, er zog mich aus großen Wassern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Er errettete mich von meinem starken Feinde und von meinen Hassern, denn sie waren mächtiger als ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Sie ereilten mich am Tage meines Unglücks, aber Jehova ward mir zur Stütze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Und er führte mich heraus ins Weite, er befreite mich, weil er Lust an mir hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Jehova vergalt mir nach meiner Gerechtigkeit, nach der Reinheit meiner Hände erstattete er mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Denn ich habe die Wege Jehovas bewahrt, und bin von meinem Gott nicht frevelhaft abgewichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Denn alle seine Rechte waren vor mir, und seine Satzungen, ich entfernte sie nicht von mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Und ich war vollkommen gegen ihn, und hütete mich vor meiner Ungerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Und Jehova erstattete mir nach meiner Gerechtigkeit, nach der Reinheit meiner Hände vor seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Gegen den Gütigen erzeigst du dich gütig, gegen den vollkommenen Mann erzeigst du dich vollkommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'gegen den Reinen erzeigst du dich rein, und gegen den Verkehrten erzeigst du dich entgegenstreitend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Denn du, du wirst retten das elende Volk, und die hohen Augen wirst du erniedrigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Denn du, du machst meine Leuchte scheinen; Jehova, mein Gott, erhellt meine Finsternis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Denn mit dir werde ich gegen eine Schar anrennen, und mit meinem Gott werde ich eine Mauer überspringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Gott, sein Weg ist vollkommen; Jehovas Wort ist geläutert; ein Schild ist er allen, die auf ihn trauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Denn wer ist Gott, außer Jehova? Und wer ein Fels, als nur unser Gott?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Der Gott, der mich mit Kraft umgürtet und vollkommen macht meinen Weg;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'der meine Füße denen der Hindinnen gleich macht, und mich hinstellt auf meine Höhen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'der meine Hände den Streit lehrt, und meine Arme spannen den ehernen Bogen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Und du gabst mir den Schild deines Heils, und deine Rechte stützte mich, und deine Herablassung machte mich groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Du machtest Raum meinen Schritten unter mir, und meine Knöchel haben nicht gewankt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Meinen Feinden jagte ich nach und erreichte sie, und ich kehrte nicht um, bis sie aufgerieben waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Ich zerschmetterte sie, und sie vermochten nicht aufzustehen; sie fielen unter meine Füße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Und du umgürtetest mich mit Kraft zum Streite, beugtest unter mich, die wider mich aufstanden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Und du hast mir gegeben den Rücken meiner Feinde; und meine Hasser, ich vernichtete sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Sie schrieen, und kein Retter war da zu Jehova, und er antwortete ihnen nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Und ich zermalmte sie wie Staub vor dem Winde; wie Straßenkot schüttete ich sie aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Du errettetest mich aus den Streitigkeiten des Volkes; du setztest mich zum Haupte der Nationen; ein Volk, das ich nicht kannte, dient mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Sowie ihr Ohr hörte, gehorchten sie mir; die Söhne der Fremde unterwarfen sich mir mit Schmeichelei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Die Söhne der Fremde sanken hin und zitterten hervor aus ihren Schlössern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Jehova lebt, und gepriesen sei mein Fels! Und erhoben werde der Gott meines Heils!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Der Gott, der mir Rache gab und die Völker mir unterwarf,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'der mich errettete von meinen Feinden. Ja, du erhöhtest mich über die, welche wider mich aufstanden; von dem Manne der Gewalttat befreitest du mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Darum, Jehova, will ich dich preisen unter den Nationen, und Psalmen singen deinem Namen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Dich, der groß macht die Rettungen seines Königs, und Güte erweist seinem Gesalbten, David und seinem Samen ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Dem Vorsänger. Ein Psalm von David. Die Himmel erzählen die Herrlichkeit Gottes, und die Ausdehnung verkündet seiner Hände Werk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Ein Tag berichtet es dem anderen, und eine Nacht meldet der anderen die Kunde davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Keine Rede und keine Worte, doch gehört wird ihre Stimme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Ihre Meßschnur geht aus über die ganze Erde, und bis an das Ende des Erdkreises ihre Sprache; er hat der Sonne in ihnen ein Zelt gesetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Und sie ist wie ein Bräutigam, der hervortritt aus seinem Gemach; sie freut sich wie ein Held, zu durchlaufen die Bahn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Vom Ende der Himmel ist ihr Ausgang, und ihr Umlauf bis zu ihren Enden; und nichts ist vor ihrer Glut verborgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Das Gesetz Jehovas ist vollkommen, erquickend die Seele; das Zeugnis Jehovas ist zuverlässig, macht weise den Einfältigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Die Vorschriften Jehovas sind richtig, erfreuend das Herz; das Gebot Jehovas ist lauter, erleuchtend die Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Die Furcht Jehovas ist rein, bestehend in Ewigkeit. Die Rechte Jehovas sind Wahrheit, sie sind gerecht allesamt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'sie, die köstlicher sind als Gold und viel gediegenes Gold, und süßer als Honig und Honigseim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Auch wird dein Knecht durch sie belehrt; im Beobachten derselben ist großer Lohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Verirrungen, wer sieht sie ein? Von verborgenen Sünden reinige mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Auch von übermütigen halte deinen Knecht zurück; laß sie mich nicht beherrschen! Dann bin ich tadellos und bin rein von großer Übertretung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Laß die Reden meines Mundes und das Sinnen meines Herzens wohlgefällig vor dir sein, Jehova, mein Fels und mein Erlöser!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Dem Vorsänger. Ein Psalm von David. Jehova erhöre dich am Tage der Drangsal, der Name des Gottes Jakobs setze dich in Sicherheit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Er sende deine Hilfe aus dem Heiligtum, und von Zion aus unterstütze er dich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Er gedenke aller deiner Speisopfer, und dein Brandopfer wolle er annehmen! (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Er gebe dir nach deinem Herzen, und alle deine Ratschläge erfülle er!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Jubeln wollen wir über deine Rettung, und im Namen unseres Gottes das Panier erheben. Jehova erfülle alle deine Bitten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Jetzt weiß ich, daß Jehova seinen Gesalbten rettet; aus seinen heiligen Himmeln wird er ihn erhören durch die Machttaten des Heils seiner Rechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Diese gedenken der Wagen und jene der Rosse, wir aber gedenken des Namens Jehovas, unseres Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Jene krümmen sich und fallen, wir aber stehen und halten uns aufrecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Jehova, rette! Der König erhöre uns am Tage unseres Rufens!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Dem Vorsänger. Ein Psalm von David. In deiner Kraft, Jehova, freut sich der König, und wie sehr frohlockt er über deine Rettung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Den Wunsch seines Herzens hast du ihm gegeben, und das Verlangen seiner Lippen nicht verweigert. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Denn mit Segnungen des Guten kamst du ihm zuvor; auf sein Haupt setztest du eine Krone von gediegenem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Leben erbat er von dir, du hast es ihm gegeben: Länge der Tage immer und ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Groß ist seine Herrlichkeit durch deine Rettung; Majestät und Pracht legtest du auf ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Denn zu Segnungen setztest du ihn ewiglich; du erfreutest ihn mit Freude durch dein Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Denn auf Jehova vertraut der König, und durch des Höchsten Güte wird er nicht wanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Deine Hand wird finden alle deine Feinde, finden wird deine Rechte deine Hasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Wie einen Feuerofen wirst du sie machen zur Zeit deiner Gegenwart; Jehova wird sie verschlingen in seinem Zorn, und Feuer wird sie verzehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Ihre Frucht wirst du von der Erde vertilgen, und ihren Samen aus den Menschenkindern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Denn sie haben Böses wider dich geplant, einen Anschlag ersonnen: sie werden nichts vermögen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Denn du wirst sie umkehren machen, wirst deine Sehne gegen ihr Angesicht richten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Erhebe dich, Jehova, in deiner Kraft! Wir wollen singen und Psalmen singen deiner Macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Dem Vorsänger, nach: \"Hindin der Morgenröte\". Ein Psalm von David. Mein Gott, mein Gott, warum hast du mich verlassen, bist fern von meiner Rettung, den Worten meines Gestöhns?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Mein Gott! Ich rufe des Tages, und du antwortest nicht; und des Nachts, und mir wird keine Ruhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Doch du bist heilig, der du wohnst unter den Lobgesängen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Auf dich vertrauten unsere Väter; sie vertrauten, und du errettetest sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Zu dir schrieen sie und wurden errettet; sie vertrauten auf dich und wurden nicht beschämt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Ich aber bin ein Wurm und kein Mann, der Menschen Hohn und der vom Volke Verachtete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Alle, die mich sehen, spotten meiner; sie reißen die Lippen auf, schütteln den Kopf:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, '\"Er vertraut auf Jehova! Der errette ihn, befreie ihn, weil er Lust an ihm hat!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Doch du bist es, der mich aus dem Mutterleibe gezogen hat, der mich vertrauen ließ an meiner Mutter Brüsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Auf dich bin ich geworfen von Mutterschoße an, von meiner Mutter Leibe an bist du mein Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Sei nicht fern von mir! Denn Drangsal ist nahe, denn kein Helfer ist da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Viele Farren haben mich umgeben, Stiere von Basan mich umringt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'sie haben ihr Maul wider mich aufgesperrt, gleich einem reißenden und brüllenden Löwen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Wie Wasser bin ich hingeschüttet, und alle meine Gebeine haben sich zertrennt; wie Wachs ist geworden mein Herz, es ist zerschmolzen inmitten meiner Eingeweide.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Meine Kraft ist vertrocknet wie ein Scherben, und meine Zunge klebt an meinem Gaumen; und in den Staub des Todes legst du mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Denn Hunde haben mich umgeben, eine Rotte von Übeltätern hat mich umzingelt. Sie haben meine Hände und meine Füße durchgraben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'alle meine Gebeine könnte ich zählen. Sie schauen und sehen mich an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Sie teilen meine Kleider unter sich, und über mein Gewand werfen sie das Los.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Du aber, Jehova, sei nicht fern! Meine Stärke, eile mir zur Hilfe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Errette vom Schwert meine Seele, meine einzige von der Gewalt des Hundes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'rette mich aus dem Rachen des Löwen! Ja, du hast mich erhört von den Hörnern der Büffel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Verkündigen will ich deinen Namen meinen Brüdern; inmitten der Versammlung will ich dich loben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Ihr, die ihr Jehova fürchtet, lobet ihn; aller Same Jakobs, verherrlichet ihn, und scheuet euch vor ihm, aller Same Israels!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Denn nicht verachtet hat er, noch verabscheut das Elend des Elenden, noch sein Angesicht vor ihm verborgen; und als er zu ihm schrie, hörte er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Von dir kommt mein Lobgesang in der großen Versammlung; bezahlen will ich meine Gelübde vor denen, die ihn fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Die Sanftmütigen werden essen und satt werden; es werden Jehova loben, die ihn suchen; euer Herz lebe immerdar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Es werden eingedenk werden und zu Jehova umkehren alle Enden der Erde; und vor dir werden niederfallen alle Geschlechter der Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Denn Jehovas ist das Reich, und unter den Nationen herrscht er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Es essen und fallen nieder alle Fetten der Erde; vor ihm werden sich beugen alle, die in den Staub hinabfahren, und der seine Seele nicht am Leben erhält.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Ein Same wird ihm dienen; er wird dem Herrn als ein Geschlecht zugerechnet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Sie werden kommen und verkünden seine Gerechtigkeit einem Volke, welches geboren wird, daß er es getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Ein Psalm von David. Jehova ist mein Hirte, mir wird nichts mangeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Er lagert mich auf grünen Auen, er führt mich zu stillen Wassern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Er erquickt meine Seele, er leitet mich in Pfaden der Gerechtigkeit um seines Namens willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Auch wenn ich wanderte im Tale des Todesschattens, fürchte ich nichts Übles, denn du bist bei mir; dein Stecken und dein Stab, sie trösten mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Du bereitest vor mir einen Tisch angesichts meiner Feinde; du hast mein Haupt mit Öl gesalbt, mein Becher fließt über.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Fürwahr, Güte und Huld werden mir folgen alle Tage meines Lebens; und ich werde wohnen im Hause Jehovas auf immerdar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Von David. Ein Psalm. Jehovas ist die Erde und ihre Fülle, der Erdkreis und die darauf wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Denn er, er hat sie gegründet über Meeren, und über Strömen sie festgestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Wer wird steigen auf den Berg Jehovas, und wer wird stehen an seiner heiligen Stätte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Der unschuldiger Hände und reinen Herzens ist, der nicht zur Falschheit erhebt seine Seele und nicht schwört zum Truge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Er wird Segen empfangen von Jehova, und Gerechtigkeit von dem Gott seines Heils.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Dies ist das Geschlecht derer, die nach ihm trachten, die dein Angesicht suchen Jakob. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Erhebet, ihr Tore, eure Häupter, und erhebet euch, ewige Pforten, daß einziehe der König der Herrlichkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Wer ist dieser König der Herrlichkeit? Jehova, stark und mächtig! Jehova, mächtig im Kampf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Erhebet, ihr Tore, eure Häupter, und erhebet euch, ewige Pforten, daß einziehe der König der Herrlichkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Wer ist er, dieser König der Herrlichkeit? Jehova der Heerscharen, er ist der König der Herrlichkeit! (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Von David. Zu dir, Jehova, erhebe ich meine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Mein Gott, auf dich vertraue ich: Laß mich nicht beschämt werden, laß meine Feinde nicht über mich frohlocken!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Auch werden alle, die auf dich harren, nicht beschämt werden; es werden beschämt werden, die treulos handeln ohne Ursache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Deine Wege, Jehova, tue mir kund, deine Pfade lehre mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Leite mich in deiner Wahrheit und lehre mich, denn du bist der Gott meines Heils; auf dich harre ich den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Gedenke deiner Erbarmungen, Jehova, und deiner Gütigkeiten; denn von Ewigkeit her sind sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Gedenke nicht der Sünden meiner Jugend, noch meiner Übertretungen; gedenke du meiner nach deiner Huld, um deiner Güte willen, Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Gütig und gerade ist Jehova, darum unterweist er die Sünder in dem Wege;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Er leitet die Sanftmütigen im Recht, und lehrt die Sanftmütigen seinen Weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Alle Pfade Jehovas sind Güte und Wahrheit für die, welche seinen Bund und seine Zeugnisse bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Um deines Namens willen, Jehova, wirst du ja vergeben meine Ungerechtigkeit; denn sie ist groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Wer ist nun der Mann, der Jehova fürchtet? Er wird ihn unterweisen in dem Wege, den er wählen soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Seine Seele wird im Guten wohnen, und sein Same die Erde besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Das Geheimnis Jehovas ist für die, welche ihn fürchten, und sein Bund, um ihnen denselben kundzutun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Meine Augen sind stets auf Jehova gerichtet; denn er wird meine Füße herausführen aus dem Netze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Wende dich zu mir und sei mir gnädig, denn einsam und elend bin ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Die Ängste meines Herzens haben sich vermehrt; führe mich heraus aus meinen Drangsalen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Sieh an mein Elend und meine Mühsal, und vergib alle meine Sünden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Sieh an meine Feinde, denn ihrer sind viele, und mit grausamem Hasse hassen sie mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Bewahre meine Seele und errette mich! Laß mich nicht beschämt werden, denn ich traue auf dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Lauterkeit und Geradheit mögen mich behüten, denn ich harre auf dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Erlöse Israel, o Gott, aus allen seinen Bedrängnissen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Von David. Richte mich, Jehova! Denn in meiner Lauterkeit habe ich gewandelt; und auf Jehova habe ich vertraut, ich werde nicht wanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Prüfe mich, Jehova, und erprobe mich; läutere meine Nieren und mein Herz!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Denn deine Güte ist vor meinen Augen, und in deiner Wahrheit wandle ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Nicht habe ich gesessen bei falschen Leuten, und mit Hinterlistigen ging ich nicht um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Ich habe die Versammlung der Übeltäter gehaßt, und bei Gesetzlosen saß ich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Ich wasche in Unschuld meine Hände, und umgehe deinen Altar, Jehova,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'um hören zu lassen die Stimme des Lobes, und um zu erzählen alle deine Wundertaten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Jehova, ich habe geliebt die Wohnung deines Hauses und den Wohnort deiner Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Raffe meine Seele nicht weg mit Sündern, noch mein Leben mit Blutmenschen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'in deren Händen böses Vornehmen, und deren Rechte voll Bestechung ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Ich aber wandle in meiner Lauterkeit. Erlöse mich und sei mir gnädig!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Mein Fuß steht auf ebenem Boden: Jehova werde ich preisen in den Versammlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Von David. Jehova ist mein Licht und mein Heil, vor wem sollte ich mich fürchten? Jehova ist meines Lebens Stärke, vor wem sollte ich erschrecken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Als Übeltäter mir nahten, um mein Fleisch zu fressen, meine Bedränger und meine Feinde, sie strauchelten und fielen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Wenn ein Heer sich wider mich lagert, nicht fürchtet sich mein Herz; wenn Krieg sich wider mich erhebt, hierauf vertraue ich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Eines habe ich von Jehova erbeten, nach diesem will ich trachten: zu wohnen im Hause Jehovas alle Tage meines Lebens, um anzuschauen die Lieblichkeit Jehovas und nach ihm zu forschen in seinem Tempel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Denn er wird mich bergen in seiner Hütte am Tage des Übels, er wird mich verbergen in dem Verborgenen seines Zeltes; auf einen Felsen wird er mich erhöhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Und nun wird mein Haupt erhöht sein über meine Feinde rings um mich her; und Opfer des Jubelschalls will ich opfern in seinem Zelte, ich will singen und Psalmen singen Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Höre, Jehova, mit meiner Stimme rufe ich; und sei mir gnädig und erhöre mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Von dir hat mein Herz gesagt: Du sprichst: Suchet mein Angesicht! Dein Angesicht, Jehova, suche ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Verbirg dein Angesicht nicht vor mir, weise nicht ab im Zorne deinen Knecht! Du bist meine Hilfe gewesen; laß mich nicht und verlaß mich nicht, Gott meines Heils!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Denn hätten mein Vater und meine Mutter mich verlassen, so nähme doch Jehova mich auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Lehre mich, Jehova, deinen Weg, und leite mich auf ebenem Pfade um meiner Feinde willen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Gib mich nicht preis der Gier meiner Bedränger! Denn falsche Zeugen sind wider mich aufgestanden und der da Gewalttat schnaubt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Wenn ich nicht geglaubt hätte, das Gute Jehovas zu schauen im Lande der Lebendigen...!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Harre auf Jehova! Sei stark, und dein Herz fasse Mut, und harre auf Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Von David. Zu dir, Jehova rufe ich; mein Fels, wende dich nicht schweigend von mir ab, damit nicht, wenn du gegen mich verstummst, ich denen gleich sei, die in die Grube hinabfahren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Höre die Stimme meines Flehens, wenn ich zu dir schreie, wenn ich meine Hände aufhebe gegen deinen heiligen Sprachort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Reiße mich nicht fort mit den Gesetzlosen und mit denen, die Frevel tun, die friedlich reden mit ihrem Nächsten, und Böses ist in ihrem Herzen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Gib ihnen nach ihrem Tun und nach der Bosheit ihrer Handlungen; nach dem Werke ihrer Hände gib ihnen, vergilt ihnen ihr Betragen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Denn sie achten nicht auf die Taten Jehovas, noch auf das Werk seiner Hände. Er wird sie zerstören und nicht bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Gepriesen sei Jehova! Denn er hat die Stimme meines Flehens gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Jehova ist meine Stärke und mein Schild; auf ihn hat mein Herz vertraut, und mir ist geholfen worden; daher frohlockt mein Herz, und ich werde ihn preisen mit meinem Liede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Jehova ist ihre Stärke, und er ist die Rettungsfeste seines Gesalbten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Rette dein Volk und segne dein Erbteil; und weide sie und trage sie bis in Ewigkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Ein Psalm; von David. Gebet Jehova, ihr Söhne der Starken, gebet Jehova Herrlichkeit und Stärke!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Gebet Jehova die Herrlichkeit seines Namens; betet Jehova an in heiliger Pracht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Die Stimme Jehovas ist auf den Wassern; der Gott der Herrlichkeit donnert, Jehova auf großen Wassern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Die Stimme Jehovas ist gewaltig, die Stimme Jehovas ist majestätisch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Die Stimme Jehovas zerbricht Zedern, ja, Jehova zerbricht die Zedern des Libanon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'und er macht sie hüpfen wie ein Kalb, den Libanon und Sirjon wie einen jungen Wildochsen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Die Stimme Jehovas sprüht Feuerflammen aus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Die Stimme Jehovas erschüttert die Wüste, Jehova erschüttert die Wüste Kades.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Die Stimme Jehovas macht Hindinnen kreißen, und entblößt die Wälder; und in seinem Tempel spricht alles: Herrlichkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Jehova thront auf der Wasserflut, und Jehova thront als König ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Jehova wird Stärke geben seinem Volke, Jehova wird sein Volk segnen mit Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Ein Psalm, ein Einweihungslied des Hauses. Von David. Ich will dich erheben, Jehova, denn du hast mich emporgezogen und hast nicht über mich sich freuen lassen meine Feinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Jehova, mein Gott! Zu dir habe ich geschrieen, und du hast mich geheilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Jehova! Du hast meine Seele aus dem Scheol heraufgeführt, hast mich belebt aus denen, die in die Grube hinabfahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Singet Psalmen Jehova, ihr seine Frommen, und preiset sein heiliges Gedächtnis!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Denn ein Augenblick ist in seinem Zorn, ein Leben in seiner Gunst; am Abend kehrt Weinen ein, und am Morgen ist Jubel da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Ich zwar sagte in meinem Wohlergehen: Ich werde nicht wanken ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Jehova! In deiner Gunst hattest du festgestellt meinen Berg; du verbargst dein Angesicht, ich ward bestürzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Zu dir, Jehova, rief ich, und zum Herrn flehte ich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Was für Gewinn ist in meinem Blute, in meinem Hinabfahren in die Grube? Wird der Staub dich preisen? Wird er deine Wahrheit verkünden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Höre, Jehova, und sei mir gnädig! Jehova, sei mein Helfer!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Meine Wehklage hast du mir in einen Reigen verwandelt, mein Sacktuch hast du gelöst, und mit Freude mich umgürtet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'auf daß meine Seele dich besinge und nicht schweige. Jehova, mein Gott, in Ewigkeit werde ich dich preisen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Dem Vorsänger. Ein Psalm von David. Auf dich, Jehova, traue ich; laß mich nimmer beschämt werden; errette mich in deiner Gerechtigkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Neige zu mir dein Ohr, eilends errette mich! Sei mir ein Fels der Zuflucht, ein befestigtes Haus, um mich zu retten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Denn mein Fels und meine Burg bist du; und um deines Namens willen führe mich und leite mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Ziehe mich aus dem Netze, das sie mir heimlich gelegt haben; denn du bist meine Stärke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'In deine Hand befehle ich meinen Geist. Du hast mich erlöst, Jehova, du Gott der Wahrheit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Gehaßt habe ich die, welche auf nichtige Götzen achten, und ich, ich habe auf Jehova vertraut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Ich will frohlocken und mich freuen in deiner Güte; denn du hast mein Elend angesehen, hast Kenntnis genommen von den Bedrängnissen meiner Seele,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'und hast mich nicht überliefert in die Hand des Feindes, hast in weiten Raum gestellt meine Füße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Sei mir gnädig, Jehova! Denn ich bin in Bedrängnis; vor Gram verfällt mein Auge, meine Seele und mein Bauch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Denn vor Kummer schwindet mein Leben dahin, und meine Jahre vor Seufzen; meine Kraft wankt durch meine Ungerechtigkeit, und es verfallen meine Gebeine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Mehr als allen meinen Bedrängern bin ich auch meinen Nachbarn zum Hohn geworden gar sehr, und zum Schrecken meinen Bekannten; die auf der Straße mich sehen, fliehen vor mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Meiner ist im Herzen vergessen wie eines Gestorbenen; ich bin geworden wie ein zertrümmertes Gefäß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Denn ich habe die Verleumdung vieler gehört, Schrecken ringsum; indem sie zusammen wider mich ratschlagten, sannen sie darauf, mir das Leben zu nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Ich aber, ich habe auf dich vertraut, Jehova; ich sagte: Du bist mein Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'In deiner Hand sind meine Zeiten; errette mich aus der Hand meiner Feinde und von meinen Verfolgern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Laß dein Angesicht leuchten über deinen Knecht, rette mich in deiner Huld!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Jehova, laß mich nicht beschämt werden! Denn ich habe dich angerufen; laß beschämt werden die Gesetzlosen, laß sie schweigen im Scheol!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Laß verstummen die Lügenlippen, die in Hochmut und Verachtung Freches reden wider den Gerechten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Wie groß ist deine Güte, welche du aufbewahrt hast denen, die dich fürchten, gewirkt für die, die auf dich trauen, angesichts der Menschenkinder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Du verbirgst sie in dem Schirme deiner Gegenwart vor den Verschwörungen der Menschen; du birgst sie in einer Hütte vor dem Gezänk der Zunge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Gepriesen sei Jehova! Denn wunderbar hat er seine Güte an mir erwiesen in einer festen Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Ich zwar sagte in meiner Bestürzung: Ich bin abgeschnitten von deinen Augen; dennoch hörtest du die Stimme meines Flehens, als ich zu dir schrie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Liebet Jehova, ihr seine Frommen alle! Die Treuen behütet Jehova, und vergilt reichlich dem, der Hochmut übt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Seid stark, und euer Herz fasse Mut, alle, die ihr auf Jehova harret!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Von David. Ein Maskil. Glückselig der, dessen Übertretung vergeben, dessen Sünde zugedeckt ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Glückselig der Mensch, dem Jehova die Ungerechtigkeit nicht zurechnet, und in dessen Geist kein Trug ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Als ich schwieg, verzehrten sich meine Gebeine durch mein Gestöhn den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Denn Tag und Nacht lastete auf mir deine Hand; verwandelt ward mein Saft in Sommerdürre. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Ich tat dir kund meine Sünde und habe meine Ungerechtigkeit nicht zugedeckt. Ich sagte: Ich will Jehova meine Übertretungen bekennen; und du, du hast vergeben die Ungerechtigkeit meiner Sünde. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Deshalb wird jeder Fromme zu dir beten, zur Zeit, wo du zu finden bist; gewiß, bei Flut großer Wasser, ihn werden sie nicht erreichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Du bist ein Bergungsort für mich; vor Bedrängnis behütest du mich; du umgibst mich mit Rettungsjubel. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Ich will dich unterweisen und dich lehren den Weg, den du wandeln sollst; mein Auge auf dich richtend, will ich dir raten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Seid nicht wie ein Roß, wie ein Maultier, das keinen Verstand hat; mit Zaum und Zügel, ihrem Schmucke, mußt du sie bändigen, sonst nahen sie dir nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Viele Schmerzen hat der Gesetzlose; wer aber auf Jehova vertraut, den wird Güte umgeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Freuet euch in Jehova und frohlocket, ihr Gerechten, und jubelt, alle ihr von Herzen Aufrichtigen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Jubelt, ihr Gerechten, in Jehova! Den Aufrichtigen geziemt Lobgesang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Preiset Jehova mit der Laute; singet ihm Psalmen mit der Harfe von zehn Saiten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Singet ihm ein neues Lied; spielet wohl mit Jubelschall!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Denn gerade ist das Wort Jehovas, und all sein Werk in Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Er liebt Gerechtigkeit und Recht; die Erde ist voll der Güte Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Durch Jehovas Wort sind die Himmel gemacht, und all ihr Heer durch den Hauch seines Mundes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Er sammelt die Wasser des Meeres wie einen Haufen, legt in Behälter die Fluten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Es fürchte sich vor Jehova die ganze Erde; mögen sich vor ihm scheuen alle Bewohner des Erdkreises!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Denn er sprach, und es war; er gebot, und es stand da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Jehova macht zunichte den Ratschluß der Nationen, er vereitelt die Gedanken der Völker.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Der Ratschluß Jehovas besteht ewiglich, die Gedanken seines Herzens von Geschlecht zu Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Glückselig die Nation, deren Gott Jehova ist, das Volk, das er sich erkoren zum Erbteil!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Jehova blickt von den Himmeln herab, er sieht alle Menschenkinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Von der Stätte seiner Wohnung schaut er auf alle Bewohner der Erde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Er, der da bildet ihr Herz allesamt, der da merkt auf alle ihre Werke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Ein König wird nicht gerettet durch die Größe seines Heeres; ein Held wird nicht befreit durch die Größe der Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Ein Trug ist das Roß zur Rettung, und durch die Größe seiner Stärke läßt es nicht entrinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Siehe, das Auge Jehovas ist gerichtet auf die, so ihn fürchten, auf die, welche auf seine Güte harren,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'um ihre Seele vom Tode zu erretten und sie am Leben zu erhalten in Hungersnot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Unsere Seele wartet auf Jehova; unsere Hilfe und unser Schild ist er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Denn in ihm wird unser Herz sich freuen, weil wir seinem heiligen Namen vertraut haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Deine Güte, Jehova, sei über uns, gleichwie wir auf dich geharrt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Von David, als er seinen Verstand vor Abimelech verstellte, und dieser ihn wegtrieb, und er fortging. Jehova will ich preisen allezeit, beständig soll sein Lob in meinem Munde sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'In Jehova soll sich rühmen meine Seele; hören werden es die Sanftmütigen und sich freuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Erhebet Jehova mit mir, und lasset uns miteinander erhöhen seinen Namen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Ich suchte Jehova, und er antwortete mir; und aus allen meinen Beängstigungen errettete er mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Sie blickten auf ihn und wurden erheitert, und ihre Angesichter wurden nicht beschämt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Dieser Elende rief, und Jehova hörte, und aus allen seinen Bedrängnissen rettete er ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Der Engel Jehovas lagert sich um die her, welche ihn fürchten, und er befreit sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Schmecket und sehet, daß Jehova gütig ist! Glückselig der Mann, der auf ihn traut!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Fürchtet Jehova, ihr seine Heiligen! Denn keinen Mangel haben, die ihn fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Junge Löwen darben und hungern, aber die Jehova suchen, ermangeln keines Guten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Kommet, ihr Söhne, höret mir zu: Die Furcht Jehovas will ich euch lehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Wer ist der Mann, der Lust zum Leben hat, der Tage liebt, um Gutes zu sehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Bewahre deine Zunge vor Bösem, und deine Lippen, daß sie nicht Trug reden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'weiche vom Bösen und tue Gutes; suche Frieden und jage ihm nach!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Die Augen Jehovas sind gerichtet auf die Gerechten, und seine Ohren auf ihr Schreien;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'das Angesicht Jehovas ist wider die, welche Böses tun, um ihr Gedächtnis von der Erde auszurotten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Sie schreien, und Jehova hört, und aus allen ihren Bedrängnissen errettet er sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Nahe ist Jehova denen, die zerbrochenen Herzens sind, und die zerschlagenen Geistes sind, rettet er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Viele sind der Widerwärtigkeiten des Gerechten, aber aus allen denselben errettet ihn Jehova;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Er bewahrt alle seine Gebeine, nicht eines von ihnen wird zerbrochen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Den Gesetzlosen wird das Böse töten; und die den Gerechten hassen, werden büßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Jehova erlöst die Seele seiner Knechte; und alle, die auf ihn trauen, werden nicht büßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Von David. Streite, Jehova, mit denen, die wider mich streiten, kämpfe mit denen, die mich bekämpfen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Ergreife Tartsche und Schild, und stehe auf zu meiner Hilfe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Und zücke den Speer und versperre den Weg wider meine Verfolger; sprich zu meiner Seele: Ich bin deine Rettung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Laß beschämt und zu Schanden werden, die nach meinem Leben trachten; laß zurückweichen und mit Scham bedeckt werden, die Übles wider mich ersinnen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Laß sie sein wie Spreu vor dem Winde, und der Engel Jehovas treibe sie fort!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Ihr Weg sei finster und schlüpfrig, und der Engel Jehovas verfolge sie!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Denn ohne Ursache haben sie mir ihr Netz heimlich gelegt, ohne Ursache meiner Seele eine Grube gegraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Über ihn komme Verderben, ohne daß er es wisse, und sein Netz, das er heimlich gelegt hat, fange ihn; zum Verderben falle er hinein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Und meine Seele wird frohlocken in Jehova, sich freuen in seiner Rettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Alle meine Gebeine werden sagen: Jehova, wer ist wie du! Der du den Elenden errettest von dem, der stärker ist als er, und den Elenden und Armen von dem, der ihn beraubt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Es treten ungerechte Zeugen auf; was ich nicht weiß, fragen sie mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Sie vergelten mir Böses für Gutes; verwaist ist meine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Ich aber, als sie krank waren, kleidete mich in Sacktuch; ich kasteite mit Fasten meine Seele, und mein Gebet kehrte in meinen Busen zurück;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'als wäre es mir ein Freund, ein Bruder gewesen, so bin ich einhergegangen; wie leidtragend um die Mutter habe ich mich trauernd niedergebeugt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Aber sie haben sich über mein Hinken gefreut und sich versammelt; Schmäher haben sich wider mich versammelt, und ich kannte sie nicht; sie haben gelästert und nicht aufgehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Gleich ruchlosen Schmarotzern knirschten sie wider mich mit ihren Zähnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Herr, wie lange willst du zusehen? Bringe meine Seele zurück aus ihren Verwüstungen, von den jungen Löwen meine einzige!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Ich werde dich preisen in der großen Versammlung, unter zahlreichem Volke dich loben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Laß sich nicht über mich freuen, die ohne Grund mir feind sind, nicht zwinken mit den Augen, die ohne Ursache mich hassen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Denn nicht von Frieden reden sie; und wider die Stillen im Lande ersinnen sie trügerische Dinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Und sie haben ihr Maul wider mich aufgesperrt; sie haben gesagt: Haha! Haha! Unser Auge hat\'s gesehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Du hast es gesehen, Jehova; schweige nicht! Herr, sei nicht fern von mir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Wache auf und erwache zu meinem Rechte, mein Gott und Herr, zu meinem Rechtsstreit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Schaffe mir Recht nach deiner Gerechtigkeit, Jehova, mein Gott! Und laß sie sich nicht über mich freuen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Laß sie nicht in ihrem Herzen sagen: Haha, so wollten wir\'s! Laß sie nicht sagen: Wir haben ihn verschlungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Laß sie beschämt und mit Scham bedeckt werden allesamt, die meines Unglücks sich freuen! Laß mit Scham und Schande bekleidet werden, die wider mich großtun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Laß jubeln und sich freuen, die Lust haben an meiner Gerechtigkeit, und laß sie stets sagen: Erhoben sei Jehova, der Lust hat an seines Knechtes Wohlfahrt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Und meine Zunge wird reden von deiner Gerechtigkeit, von deinem Lobe den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Dem Vorsänger. Von dem Knechte Jehovas, von David. Die Übertretung des Gesetzlosen spricht im Innern meines Herzens: Es ist keine Furcht Gottes vor seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Denn es schmeichelt ihm in seinen eigenen Augen, seine Ungerechtigkeit zu erreichen, Haß auszuüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Frevel und Trug sind die Worte seines Mundes; er hat es aufgegeben, verständig zu sein, Gutes zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Frevel ersinnt er auf seinem Lager; er stellt sich auf einen Weg, der nicht gut ist; das Böse verabscheut er nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Jehova! An die Himmel reicht deine Güte, bis zu den Wolken deine Treue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Deine Gerechtigkeit ist gleich Bergen Gottes, deine Gerichte sind eine große Tiefe; Menschen und Vieh rettest du, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Wie köstlich ist deine Güte, o Gott! Und Menschenkinder nehmen Zuflucht zu deiner Flügel Schatten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'sie werden reichlich trinken von der Fettigkeit deines Hauses, und mit dem Strome deiner Wonnen wirst du sie tränken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Denn bei dir ist der Quell des Lebens, in deinem Lichte werden wir das Licht sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Laß deine Güte fortdauern denen, die dich kennen, und deine Gerechtigkeit den von Herzen Aufrichtigen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Nicht erreiche mich der Fuß der Hochmütigen, und die Hand der Gesetzlosen vertreibe mich nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Da sind gefallen, die Frevel tun; sie wurden niedergestoßen, und vermochten nicht aufzustehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Von David. Erzürne dich nicht über die Übeltäter, beneide nicht die, welche Unrecht tun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Denn wie das Gras werden sie schnell vergehen, und wie das grüne Kraut verwelken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Vertraue auf Jehova und tue Gutes; wohne im Lande und weide dich an Treue;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'und ergötze dich an Jehova: so wird er dir geben die Bitten deines Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Befiehl Jehova deinen Weg und vertraue auf ihn! Und er wird handeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'und er wird deine Gerechtigkeit hervorkommen lassen wie das Licht, und dein Recht wie den Mittag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Vertraue still dem Jehova und harre auf ihn! Erzürne dich nicht über den, dessen Weg gelingt, über den Mann, der böse Anschläge ausführt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Stehe ab vom Zorn und laß den Grimm! Erzürne dich nicht! Nur zum Übeltun verleitet es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Denn die Übeltäter werden ausgerottet werden; aber die auf Jehova hoffen, diese werden das Land besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Und noch um ein Kleines, und der Gesetzlose ist nicht mehr; und siehst du dich um nach seiner Stätte, so ist er nicht da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Aber die Sanftmütigen werden das Land besitzen, und werden sich ergötzen an Fülle von Wohlfahrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Der Gesetzlose sinnt wider den Gerechten, und mit seinen Zähnen knirscht er wider ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Der Herr lacht seiner, denn er sieht, daß sein Tag kommt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Die Gesetzlosen haben das Schwert gezogen und ihren Bogen gespannt, um zu fällen den Elenden und den Armen, hinzuschlachten, die in Geradheit wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Ihr Schwert wird in ihr eigenes Herz dringen, und ihre Bogen werden zerbrochen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Besser das Wenige des Gerechten als der Überfluß vieler Gesetzlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Denn die Arme der Gesetzlosen werden zerbrochen werden, aber Jehova stützt die Gerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Jehova kennt die Tage derer, die lauter sind, und ihr Erbteil wird ewig sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'sie werden nicht beschämt werden in der Zeit des Übels, und in den Tagen des Hungers werden sie gesättigt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Denn die Gesetzlosen werden umkommen, und die Feinde Jehovas sind wie die Pracht der Auen; sie schwinden, sie schwinden dahin wie Rauch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Der Gesetzlose borgt und erstattet nicht wieder; der Gerechte aber ist gnädig und gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Denn die von ihm Gesegneten werden das Land besitzen, und die von ihm Verfluchten werden ausgerottet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Von Jehova werden befestigt des Mannes Schritte, und an seinem Wege hat er Wohlgefallen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'wenn er fällt, wird er nicht hingestreckt werden, denn Jehova stützt seine Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Ich war jung und bin auch alt geworden, und nie sah ich den Gerechten verlassen, noch seinen Samen nach Brot gehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'den ganzen Tag ist er gnädig und leiht, und sein Same wird gesegnet sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Weiche vom Bösen und tue Gutes, und bleibe ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Denn Jehova liebt das Recht und wird seine Frommen nicht verlassen; ewig werden sie bewahrt, aber der Same der Gesetzlosen wird ausgerottet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Die Gerechten werden das Land besitzen und werden darin wohnen immerdar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Der Mund des Gerechten spricht Weisheit aus, und seine Zunge redet das Recht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'das Gesetz seines Gottes ist in seinem Herzen, seine Schritte werden nicht wanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Der Gesetzlose lauert auf den Gerechten und sucht ihn zu töten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Jehova wird ihn nicht in seiner Hand lassen, und ihn nicht verdammen, wenn er gerichtet wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Harre auf Jehova und bewahre seinen Weg, und er wird dich erhöhen, das Land zu besitzen. Wenn die Gesetzlosen ausgerottet werden, wirst du zusehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Ich habe einen Gesetzlosen gesehen, der gewaltig war, und der sich ausbreitete wie ein nicht verpflanzter grüner Baum;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'und man ging vorbei, und siehe, er war nicht mehr; und ich suchte ihn, und er ward nicht gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Achte auf den Unsträflichen und sieh auf den Aufrichtigen; denn für den Mann des Friedens gibt es eine Zukunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Die Übertreter aber werden vertilgt allesamt, es wird abgeschnitten die Zukunft der Gesetzlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Aber die Rettung der Gerechten ist von Jehova, der ihre Stärke ist zur Zeit der Bedrängnis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'und Jehova wird ihnen helfen und sie erretten; er wird sie erretten von den Gesetzlosen und ihnen Rettung verschaffen, denn sie trauen auf ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Ein Psalm von David zum Gedächtnis. Jehova, strafe mich nicht in deinem Zorn, noch züchtige mich in deinem Grimm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Denn deine Pfeile sind in mich eingedrungen, und deine Hand hat sich auf mich herabgesenkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Nichts Heiles ist an meinem Fleische wegen deines Zürnens, kein Frieden in meinen Gebeinen wegen meiner Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Denn meine Ungerechtigkeiten sind über mein Haupt gegangen, wie eine schwere Last sind sie zu schwer für mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Es stinken, es eitern meine Wunden wegen meiner Torheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Ich bin gekrümmt, über die Maßen gebeugt; den ganzen Tag gehe ich trauernd einher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Denn voll Brand sind meine Lenden, und nichts Heiles ist an meinem Fleische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Ich bin ermattet und über die Maßen zerschlagen, ich heule vor Gestöhn meines Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Herr, vor dir ist all mein Begehr, und mein Seufzen ist nicht vor dir verborgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Mein Herz pocht, verlassen hat mich meine Kraft; und das Licht meiner Augen, auch das ist nicht bei mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Meine Lieben und meine Genossen stehen fernab von meiner Plage, und meine Verwandten stehen von ferne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Und die nach meinem Leben trachten, legen mir Schlingen; und die mein Unglück suchen, reden von Schadentun und sinnen auf Trug den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Ich aber, wie ein Tauber, höre nicht, und bin wie ein Stummer, der seinen Mund nicht auftut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Und ich bin wie ein Mann, der nicht hört, und in dessen Munde keine Gegenreden sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Denn auf dich, Jehova, harre ich; du, du wirst antworten, Herr, mein Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Denn ich sprach: Daß sie sich nicht über mich freuen! Beim Wanken meines Fußes tun sie groß wider mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Denn ich bin nahe daran zu hinken, und mein Schmerz ist beständig vor mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Denn ich tue kund meine Ungerechtigkeit; ich bin bekümmert wegen meiner Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Meine Feinde aber leben, sind stark, und viele sind derer, die ohne Grund mich hassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'und Böses für Gutes vergeltend, feinden sie mich an, weil ich dem Guten nachjage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Verlaß mich nicht, Jehova; mein Gott, sei nicht fern von mir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Eile zu meiner Hilfe, Herr, meine Rettung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Dem Vorsänger, dem Jeduthun. Ein Psalm von David. Ich sprach: Ich will meine Wege bewahren, daß ich nicht sündige mit meiner Zunge; ich will meinen Mund mit einem Maulkorbe verwahren, solange der Gesetzlose vor mir ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Ich verstummte in Stille, ich schwieg vom Guten, und mein Schmerz ward erregt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Mein Herz brannte in meinem Innern, bei meinem Nachsinnen entzündete sich Feuer; ich sprach mit meiner Zunge:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Tue mir kund, Jehova, mein Ende, und das Maß meiner Tage, welches es ist, daß ich wisse, wie vergänglich ich bin!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Siehe, Handbreiten gleich hast du meine Tage gemacht, und meine Lebensdauer ist wie nichts vor dir; ja, eitel Hauch ist jeder Mensch, der dasteht. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Ja, als ein Schattenbild wandelt der Mensch einher; ja, vergebens ist er voll Unruhe; er häuft auf und weiß nicht, wer es einsammeln wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Und nun, auf was harre ich, Herr? Meine Hoffnung ist auf dich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Errette mich von allen meinen Übertretungen, mache mich nicht zum Hohne des Toren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Ich bin verstummt, ich tue meinen Mund nicht auf; denn du, du hast es getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Entferne von mir deine Plage! Durch die Schläge deiner Hand vergehe ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Strafst du einen Mann mit Züchtigungen für die Ungerechtigkeit, so machst du, gleich der Motte, seine Schönheit zergehen; ja, ein Hauch sind alle Menschen. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Höre mein Gebet, Jehova, und nimm zu Ohren mein Schreien; schweige nicht zu meinen Tränen! Denn ein Fremdling bin ich bei dir, ein Beisasse wie alle meine Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Blicke von mir ab, daß ich mich erquicke, bevor ich dahingehe und nicht mehr bin!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Dem Vorsänger. Von David, ein Psalm. Beharrlich habe ich auf Jehova geharrt, und er hat sich zu mir geneigt und mein Schreien gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Er hat mich heraufgeführt aus der Grube des Verderbens, aus kotigem Schlamm; und er hat meine Füße auf einen Felsen gestellt, meine Schritte befestigt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'und in meinen Mund hat er gelegt ein neues Lied, einen Lobgesang unserem Gott. Viele werden es sehen und sich fürchten und auf Jehova vertrauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Glückselig der Mann, der Jehova zu seiner Zuversicht macht und sich nicht wendet zu den Stolzen und zu denen, die zur Lüge abweichen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Vielfach hast du deine Wundertaten und deine Gedanken gegen uns erwiesen, Jehova, mein Gott; nicht kann man sie der Reihe nach dir vorstellen. Wollte ich davon berichten und reden, es sind ihrer zu viele, um sie aufzuzählen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'An Schlacht-und Speisopfern hattest du keine Lust; Ohren hast du mir bereitet: Brand-und Sündopfer hast du nicht gefordert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Da sprach ich: Siehe, ich komme; in der Rolle des Buches steht von mir geschrieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Dein Wohlgefallen zu tun, mein Gott, ist meine Lust; und dein Gesetz ist im Innern meines Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Ich habe die Gerechtigkeit verkündet in der großen Versammlung; siehe, meine Lippen hemmte ich nicht Jehova, du weißt es!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Deine Gerechtigkeit habe ich nicht verborgen im Innern meines Herzens; deine Treue und deine Rettung habe ich ausgesprochen, deine Güte und deine Wahrheit nicht verhehlt vor der großen Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Du, Jehova, halte deine Erbarmungen nicht von mir zurück; deine Güte und deine Wahrheit laß beständig mich behüten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Denn Übel bis zur Unzahl haben mich umgeben, meine Ungerechtigkeiten haben mich erreicht, daß ich nicht sehen kann; zahlreicher sind sie als die Haare meines Hauptes, und mein Herz hat mich verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Laß dir gefallen, Jehova, mich zu erretten! Jehova, eile zu meiner Hilfe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Laß sie beschämt und mit Scham bedeckt werden allesamt, die nach meinem Leben trachten, es wegzuraffen; laß zurückweichen und zu Schanden werden, die Gefallen haben an meinem Unglück!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Laß sich entsetzen ob ihrer Schande, die von mir sagen: Haha! Haha!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Laß fröhlich sein und sich freuen in dir alle, die dich suchen; die deine Rettung lieben, laß stets sagen: Erhoben sei Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Ich aber bin elend und arm, der Herr denkt an mich. Meine Hilfe und mein Erretter bist du; mein Gott, zögere nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Dem Vorsänger. Ein Psalm von David. Glückselig, wer achthat auf den Armen! Am Tage des Übels wird Jehova ihn erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Jehova wird ihn bewahren und ihn am Leben erhalten; er wird glücklich sein auf Erden, und nicht wirst du ihn preisgeben der Gier seiner Feinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Jehova wird ihn stützen auf dem Siechbett, all sein Lager wandelst du um in seiner Krankheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Ich sprach: Jehova, sei mir gnädig! Heile meine Seele, denn ich habe gegen dich gesündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Meine Feinde wünschen mir Böses: Wann wird er sterben und sein Name vergehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Und wenn einer kommt, um mich zu sehen, so redet er Falschheit; sein Herz sammelt sich Unheil, er geht hinaus, redet davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Miteinander raunen wider mich alle meine Hasser; Böses ersinnen sie wider mich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Ein Belialsstück klebt ihm an; und weil er nun daliegt, wird er nicht wieder aufstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Selbst der Mann meines Friedens, auf den ich vertraute, der mein Brot aß, hat die Ferse wider mich erhoben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Du aber, Jehova, sei mir gnädig und richte mich auf, daß ich es ihnen vergelte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Daran erkenne ich, daß du Gefallen an mir hast, daß mein Feind nicht über mich jauchzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Ich aber, in meiner Lauterkeit hast du mich aufrecht gehalten und mich vor dich gestellt auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Gepriesen sei Jehova, der Gott Israels, von Ewigkeit bis in Ewigkeit! Amen, ja, Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Dem Vorsänger. Ein Maskil von den Söhnen Korahs. Wie ein Hirsch lechzt nach Wasserbächen, also lechzt meine Seele nach dir, o Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Meine Seele dürstet nach Gott, nach dem lebendigen Gott: Wann werde ich kommen und erscheinen vor Gottes Angesicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Meine Tränen sind mir zur Speise geworden Tag und Nacht, da man den ganzen Tag zu mir sagt: Wo ist dein Gott?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Daran will ich gedenken und in mir ausschütten meine Seele, wie ich einherzog in der Schar, mit ihnen wallte zum Hause Gottes, mit der Stimme des Jubels und des Lobes, eine feiernde Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Was beugst du dich nieder, meine Seele, und bist unruhig in mir? Harre auf Gott! Denn ich werde ihn noch preisen für das Heil seines Angesichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Mein Gott, es beugt sich nieder in mir meine Seele; darum gedenke ich deiner aus dem Lande des Jordan und des Hermon, vom Berge Mizhar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Tiefe ruft der Tiefe beim Brausen deiner Wassergüsse; alle deine Wogen und deine Wellen sind über mich hingegangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Des Tages wird Jehova seine Güte entbieten, und des Nachts wird sein Lied bei mir sein, ein Gebet zu dem Gott meines Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Sagen will ich zu Gott, meinem Fels: Warum hast du mich vergessen? Warum gehe ich trauernd einher wegen der Bedrückung des Feindes?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Wie eine Zermalmung in meinen Gebeinen höhnen mich meine Bedränger, indem sie den ganzen Tag zu mir sagen: Wo ist dein Gott?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Was beugst du dich nieder, meine Seele, und was bist du unruhig in mir? Harre auf Gott! Denn ich werde ihn noch preisen, der das Heil meines Angesichts und mein Gott ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Schaffe mir Recht, o Gott, und führe meinen Rechtsstreit wider eine lieblose Nation! Von dem Manne des Trugs und des Unrechts errette mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Denn du bist der Gott meiner Stärke. Warum hast du mich verworfen? Warum gehe ich trauernd einher wegen der Bedrückung des Feindes?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Sende dein Licht und deine Wahrheit; sie sollen mich leiten, mich bringen zu deinem heiligen Berge und zu deinen Wohnungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'So werde ich kommen zum Altar Gottes, zu dem Gott, der meine Jubelfreude ist, und werde dich preisen mit der Laute, Gott, mein Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Was beugst du dich nieder, meine Seele, und was bist du unruhig in mir? Harre auf Gott! Denn ich werde ihn noch preisen, der das Heil meines Angesichts und mein Gott ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Dem Vorsänger. Von den Söhnen Korahs, ein Maskil. Gott, mit unseren Ohren haben wir gehört, unsere Väter haben uns erzählt die Großtat, die du gewirkt hast in ihren Tagen, in den Tagen vor alters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Du, mit deiner Hand hast du Nationen ausgetrieben, und sie hast du gepflanzt, Völkerschaften hast du verderbt, und sie hast du ausgebreitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Denn nicht durch ihr Schwert haben sie das Land in Besitz genommen, und nicht ihr Arm hat sie gerettet; sondern deine Rechte und dein Arm und das Licht deines Angesichts, weil du Wohlgefallen an ihnen hattest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Du selbst bist mein König, o Gott; gebiete die Rettungen Jakobs!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Durch dich werden wir niederstoßen unsere Bedränger; durch deinen Namen werden wir zertreten, die wider uns aufstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Denn nicht auf meinen Bogen vertraue ich, und nicht wird mein Schwert mich retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Denn du rettest uns von unseren Bedrängern, und unsere Hasser machst du beschämt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'In Gott rühmen wir uns den ganzen Tag, und deinen Namen werden wir preisen ewiglich. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Doch du hast uns verworfen und zu Schanden gemacht, und zogest nicht aus mit unseren Heeren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Du ließest uns zurückweichen vor dem Bedränger, und unsere Hasser haben für sich geraubt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Du gabst uns hin wie Schlachtschafe, und unter die Nationen hast du uns zerstreut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Du verkauftest dein Volk um ein Geringes und hast nicht hochgestellt ihren Preis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Du machtest uns zum Hohne unseren Nachbarn, zum Spott und Schimpf denen, die uns umgeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Du machtest uns zum Sprichwort unter den Nationen, zum Kopfschütteln unter den Völkerschaften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Den ganzen Tag ist vor mir meine Schande, und die Scham meines Angesichts hat mich bedeckt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'wegen der Stimme des Schmähers und Lästerers, wegen des Feindes und des Rachgierigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Dieses alles ist über uns gekommen, und wir haben deiner nicht vergessen, noch betrüglich gehandelt wider deinen Bund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Nicht ist unser Herz zurückgewichen, noch sind unsere Schritte abgebogen von deinem Pfade;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'obgleich du uns zermalmt hast am Orte der Schakale, und uns bedeckt mit dem Schatten des Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Wenn wir vergessen hätten den Namen unseres Gottes und unsere Hände ausgestreckt zu einem fremden Gott,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'würde Gott das nicht erforschen? Denn er kennt die Geheimnisse des Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Doch um deinetwillen werden wir getötet den ganzen Tag, wie Schlachtschafe sind wir geachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Erwache! Warum schläfst du, Herr? Wache auf! Verwirf uns nicht auf ewig!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Warum verbirgst du dein Angesicht, vergissest unser Elend und unsere Bedrückung?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Denn unsere Seele ist in den Staub gebeugt, unser Bauch klebt an der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Stehe auf, uns zur Hilfe, und erlöse uns um deiner Güte willen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Dem Vorsänger, nach Schoschannim. Von den Söhnen Korahs; ein Maskil, ein Lied der Lieblichkeiten. Es wallt mein Herz von gutem Worte. Ich sage: Meine Gedichte dem Könige! Meine Zunge sei der Griffel eines fertigen Schreibers!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Du bist schöner als die Menschensöhne, Holdseligkeit ist ausgegossen über deine Lippen; darum hat Gott dich gesegnet ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Gürte dein Schwert um die Hüfte, du Held, deine Pracht und deine Majestät!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Und in deiner Majestät ziehe glücklich hin um der Wahrheit willen und der Sanftmut und der Gerechtigkeit; und Furchtbares wird dich lehren deine Rechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Deine Pfeile sind scharf, Völker fallen unter dir, im Herzen der Feinde des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Dein Thron, o Gott, ist immer und ewiglich, ein Zepter der Aufrichtigkeit ist das Zepter deines Reiches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Gerechtigkeit hast du geliebt und Gesetzlosigkeit gehaßt: darum hat Gott, dein Gott, dich gesalbt mit Freudenöl, mehr als deine Genossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Myrrhen und Aloe, Kassia sind alle deine Kleider; aus Palästen von Elfenbein erfreut dich Saitenspiel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Königstöchter sind unter deinen Herrlichen; die Königin steht zu deiner Rechten in Gold von Ophir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Höre, Tochter, und sieh, und neige dein Ohr; und vergiß deines Volkes und deines Vaters Hauses!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Und der König wird deine Schönheit begehren, denn er ist dein Herr: so huldige ihm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Und die Tochter Tyrus, die Reichen des Volkes, werden deine Gunst suchen mit Geschenken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Ganz herrlich ist des Königs Tochter drinnen, von Goldwirkerei ihr Gewand;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'in buntgewirkten Kleidern wird sie zum König geführt werden; Jungfrauen hinter ihr her, ihre Gefährtinnen, werden zu dir gebracht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Sie werden geführt werden unter Freude und Jubel, sie werden einziehen in den Palast des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'An deiner Väter Statt werden deine Söhne sein; zu Fürsten wirst du sie einsetzen im ganzen Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Ich will deines Namens gedenken lassen alle Geschlechter hindurch; darum werden die Völker dich preisen immer und ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Dem Vorsänger. Von den Söhnen Korahs; auf Alamoth, ein Lied. Gott ist uns Zuflucht und Stärke, eine Hilfe, reichlich gefunden in Drangsalen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Darum werden wir uns nicht fürchten, wenngleich gewandelt würde die Erde, und wenn die Berge wankten im Herzen des Meeres,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'wenn seine Wasser tobten und schäumten, die Berge erbebten durch sein Ungestüm. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Ein Strom, seine Bäche erfreuen die Stadt Gottes, das Heiligtum der Wohnungen des Höchsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Gott ist in ihrer Mitte, sie wird nicht wanken; Gott wird ihr helfen beim Anbruch des Morgens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Es toben die Nationen, die Königreiche wanken; er läßt seine Stimme erschallen: die Erde zerschmilzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Jehova der Heerscharen ist mit uns, eine hohe Feste ist uns der Gott Jakobs. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Kommet, schauet die Großtaten Jehovas, der Verheerungen angerichtet hat auf der Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Der die Kriege beschwichtigt bis an das Ende der Erde, den Bogen zerbricht und den Speer zerschlägt, die Wagen mit Feuer verbrennt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Lasset ab und erkennet, daß ich Gott bin! Ich werde erhöht werden unter den Nationen, ich werde erhöht werden auf Erden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Jehova der Heerscharen ist mit uns, eine hohe Feste ist uns der Gott Jakobs. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Dem Vorsänger. Von den Söhnen Korahs, ein Psalm. Ihr Völker alle, klatschet in die Hände! Jauchzet Gott mit Jubelschall!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Denn Jehova, der Höchste, ist furchtbar, ein großer König über die ganze Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Er unterwarf uns die Völker, und die Völkerschaften unter unsere Füße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Er erwählte für uns unser Erbteil, den Stolz Jakobs, den er geliebt hat. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Gott ist emporgestiegen unter Jauchzen, Jehova unter Posaunenschall.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Singet Gott Psalmen, singet Psalmen; singet Psalmen unserem König, singet Psalmen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Denn Gott ist König der ganzen Erde; singet Psalmen mit Einsicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Gott regiert über die Nationen; Gott hat sich auf den Thron seiner Heiligkeit gesetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Die Edlen der Völker haben sich versammelt und das Volk des Gottes Abrahams; denn die Schilde der Erde sind Gottes; er ist sehr erhaben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Ein Lied, ein Psalm. Von den Söhnen Korahs. Groß ist Jehova und sehr zu loben in der Stadt unseres Gottes auf seinem heiligen Berge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Schön ragt empor, eine Freude der ganzen Erde, der Berg Zion, an der Nordseite, die Stadt des großen Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Gott ist bekannt in ihren Palästen als eine hohe Feste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Denn siehe, die Könige hatten sich versammelt, waren herangezogen allesamt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Sie sahen, da erstaunten sie; sie wurden bestürzt, flohen ängstlich hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Beben ergriff sie daselbst, Angst, der Gebärenden gleich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Durch den Ostwind zertrümmertest du die Tarsisschiffe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Wie wir gehört hatten, also haben wir es gesehen in der Stadt Jehovas der Heerscharen, in der Stadt unseres Gottes: Gott wird sie befestigen bis in Ewigkeit. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Wir haben gedacht, o Gott, an deine Güte, im Innern deines Tempels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Wie dein Name, Gott, also ist dein Lob bis an die Enden der Erde; mit Gerechtigkeit ist gefüllt deine Rechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Es freue sich der Berg Zion, es mögen frohlocken die Töchter Judas um deiner Gerichte willen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Umgehet Zion und umkreiset es, zählet seine Türme;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'betrachtet genau seine Wälle, mustert seine Paläste, damit ihr\'s erzählet dem künftigen Geschlecht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Denn dieser Gott ist unser Gott immer und ewiglich! Er wird uns leiten bis an den Tod.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Dem Vorsänger. Von den Söhnen Korahs, ein Psalm. Höret dies, ihr Völker alle; nehmet es zu Ohren, alle Bewohner der Welt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'sowohl Menschensöhne als Männersöhne, Reiche und Arme allzumal!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Mein Mund soll Weisheit reden, und das Sinnen meines Herzens soll Einsicht sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Neigen will ich zu einem Spruche mein Ohr, mein Rätsel eröffnen bei der Laute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Warum sollte ich mich fürchten in Tagen des Übels, wenn die Ungerechtigkeit derer, die mir auf der Ferse sind, mich umringt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Welche auf ihr Vermögen vertrauen und der Größe ihres Reichtums sich rühmen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Keineswegs vermag jemand seinen Bruder zu erlösen, nicht kann er Gott sein Lösegeld geben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, '(Denn kostbar ist die Erlösung ihrer Seele, und er muß davon abstehen auf ewig)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'daß er fortlebe immerdar, die Grube nicht sehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Denn er sieht, daß die Weisen sterben, daß der Tor und der Unvernünftige miteinander umkommen und anderen ihr Vermögen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Ihr Gedanke ist, daß ihre Häuser stehen in Ewigkeit, ihre Wohnungen von Geschlecht zu Geschlecht; sie nennen Ländereien nach ihrem Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Doch der Mensch, der in Ansehen ist, bleibt nicht; er gleicht dem Vieh, das vertilgt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Dieser ihr Weg ist ihre Torheit; und die nach ihnen kommen, haben Wohlgefallen an ihren Worten. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Man legt sie in den Scheol wie Schafe, der Tod weidet sie; und am Morgen herrschen die Aufrichtigen über sie; und ihre Gestalt wird der Scheol verzehren, fern von ihrer Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Gott aber wird meine Seele erlösen von der Gewalt des Scheols; denn er wird mich aufnehmen. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Fürchte dich nicht, wenn ein Mann sich bereichert, wenn sich vergrößert die Herrlichkeit seines Hauses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Denn wenn er stirbt, nimmt er das alles nicht mit; nicht folgt ihm hinab seine Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Ob er auch seine Seele segnete in seinem Leben und man wird dich loben, wenn du dir selbst Gutes tust-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'sie wird kommen zu dem Geschlecht seiner Väter; nimmermehr werden sie das Licht sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Der Mensch, der in Ansehen ist und keine Einsicht hat, gleicht dem Vieh, das vertilgt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Ein Psalm; von Asaph. Der Mächtige, Gott, Jehova, hat geredet und die Erde gerufen vom Aufgang der Sonne bis zu ihrem Niedergang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Aus Zion, der Schönheit Vollendung, ist Gott hervorgestrahlt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Unser Gott kommt, und er wird nicht schweigen; Feuer frißt vor ihm her, und rings um ihn stürmt es gewaltig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Er ruft dem Himmel droben und der Erde, um sein Volk zu richten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '\"Versammelt mir meine Frommen, die meinen Bund geschlossen haben beim Opfer!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Und die Himmel verkünden seine Gerechtigkeit, denn Gott ist es, der richtet. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, '\"Höre, mein Volk, und ich will reden, Israel, und ich will wider dich zeugen! Ich, ich bin Gott, dein Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Nicht wegen deiner Schlachtopfer tadle ich dich, und deine Brandopfer sind beständig vor mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Nicht werde ich Farren nehmen aus deinem Hause, noch Böcke aus deinen Hürden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Denn mein ist alles Getier des Waldes, das Vieh auf tausend Bergen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Ich kenne alles Gevögel der Berge, und das Wild des Gefildes ist mir bekannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Wenn mich hungerte, ich würde es dir nicht sagen: denn mein ist der Erdkreis und seine Fülle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Sollte ich das Fleisch von Stieren essen und das Blut von Böcken trinken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Opfere Gott Lob, und bezahle dem Höchsten deine Gelübde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'und rufe mich an am Tage der Bedrängnis: ich will dich erretten, und du wirst mich verherrlichen!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Zu dem Gesetzlosen aber spricht Gott: \"Was hast du meine Satzungen herzusagen und meinen Bund in deinen Mund zu nehmen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Du hast ja die Zucht gehaßt und hinter dich geworfen meine Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Wenn du einen Dieb sahst, so gingst du gern mit ihm um, und dein Teil war mit Ehebrechern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Deinen Mund ließest du los zum Bösen, und Trug flocht deine Zunge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Du saßest da, redetest wider deinen Bruder, wider den Sohn deiner Mutter stießest du Schmähung aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Solches hast du getan, und ich schwieg; du dachtest, ich sei ganz wie du. Ich werde dich strafen und es dir vor Augen stellen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Merket doch dieses, die ihr Gottes vergesset, damit ich nicht zerreiße, und kein Erretter sei da!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Wer Lob opfert, verherrlicht mich, und wer seinen Weg einrichtet, ihn werde ich das Heil Gottes sehen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Dem Vorsänger. Ein Psalm von David, als der Prophet Nathan zu ihm kam, nachdem er zu Bathseba eingegangen war. Sei mir gnädig, o Gott, nach deiner Güte: nach der Größe deiner Erbarmungen tilge meine Übertretungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Wasche mich völlig von meiner Ungerechtigkeit, und reinige mich von meiner Sünde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Denn ich kenne meine Übertretungen, und meine Sünde ist beständig vor mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Gegen dich, gegen dich allein habe ich gesündigt, und ich habe getan, was böse ist in deinen Augen; damit du gerechtfertigt werdest, wenn du redest, rein erfunden, wenn du richtest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Siehe, in Ungerechtigkeit bin ich geboren, und in Sünde hat mich empfangen meine Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Siehe, du hast Lust an der Wahrheit im Innern, und im Verborgenen wirst du mich Weisheit kennen lehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Entsündige mich mit Ysop, und ich werde rein sein; wasche mich, und ich werde weißer sein als Schnee.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Laß mich Fröhlichkeit und Freude hören, so werden die Gebeine frohlocken, die du zerschlagen hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Verbirg dein Angesicht vor meinen Sünden, und tilge alle meine Ungerechtigkeiten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Schaffe mir, Gott, ein reines Herz, und erneuere in meinem Innern einen festen Geist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Verwirf mich nicht von deinem Angesicht, und den Geist deiner Heiligkeit nimm nicht von mir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Laß mir wiederkehren die Freude deines Heils, und mit einem willigen Geiste stütze mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Lehren will ich die Übertreter deine Wege, und die Sünder werden zu dir umkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Errette mich von Blutschuld, Gott, du Gott meiner Rettung, so wird meine Zunge jubelnd preisen deine Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Herr, tue meine Lippen auf, und mein Mund wird dein Lob verkünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Denn du hast keine Lust an Schlachtopfern, sonst gäbe ich sie; an Brandopfern hast du kein Wohlgefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Die Opfer Gottes sind ein zerbrochener Geist; ein zerbrochenes und zerschlagenes Herz wirst du, Gott, nicht verachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Tue Zion Gutes in deiner Gunst, baue die Mauern Jerusalems!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Dann wirst du Lust haben an Opfern der Gerechtigkeit, an Brandopfern und Ganzopfern; dann wird man Farren opfern auf deinem Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Dem Vorsänger. Ein Maskil von David, als Doeg, der Edomiter, kam und Saul berichtete und ihm sagte: David ist in das Haus Abimelechs gekommen. Was rühmst du dich des Bösen, du Gewaltiger? Die Güte Gottes währt den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Verderben sinnt deine Zunge, wie ein geschliffenes Schermesser Trug übend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Du hast das Böse mehr geliebt, als das Gute, die Lüge mehr, als Gerechtigkeit zu reden. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Du hast alle Vertilgungsworte geliebt, du Zunge des Trugs!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Gott wird dich auch zerstören für immerdar; er wird dich fassen und herausreißen aus dem Zelte und auswurzeln aus dem Lande der Lebendigen. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Und sehen werden es die Gerechten und sich fürchten, und sie werden über ihn lachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, '\"Sieh den Mann, der Gott nicht zu seiner Stärke machte, sondern auf die Größe seines Reichtums vertraute, durch sein Schadentun stark war!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Ich aber bin wie ein grüner Olivenbaum im Hause Gottes; ich vertraue auf die Güte Gottes immer und ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Ich werde dich preisen ewiglich, weil du es getan hast; und auf deinen Namen werde ich harren, denn er ist gut, vor deinen Frommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Dem Vorsänger, nach Machalath. Ein Maskil von David. Der Tor spricht in seinem Herzen: Es ist kein Gott! Sie haben verderbt gehandelt und haben abscheulich das Unrecht geübt; da ist keiner, der Gutes tue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Gott hat vom Himmel herniedergeschaut auf die Menschenkinder, um zu sehen, ob ein Verständiger da sei, einer, der Gott suche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Alle sind abgewichen, sie sind allesamt verderbt; da ist keiner, der Gutes tue, auch nicht einer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Haben keine Erkenntnis die, welche Frevel tun, die mein Volk fressen, als äßen sie Brot? Gott rufen sie nicht an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Da überfiel sie ein Schrecken, ohne daß ein Schrecken da war; denn Gott hat zerstreut die Gebeine dessen, der dich belagerte. Du hast sie beschämt gemacht, denn Gott hat sie verworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'O daß aus Zion die Rettungen Israels da wären! Wenn Gott die Gefangenschaft seines Volkes wendet, soll Jakob frohlocken, Israel sich freuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Dem Vorsänger, mit Saitenspiel. Ein Maskil von David, als die Siphiter kamen und zu Saul sprachen: Hält David sich nicht bei uns verborgen? Gott, durch deinen Namen rette mich, und schaffe mir Recht durch deine Macht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Gott, höre mein Gebet, nimm du Ohren die Reden meines Mundes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Denn Fremde sind wider mich aufgestanden, und Gewalttätige trachten nach meinem Leben; sie haben Gott nicht vor sich gestellt. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Siehe, Gott ist mein Helfer; der Herr ist unter denen, die meine Seele stützen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Er wird das Böse zurückerstatten meinen Feinden; nach deiner Wahrheit vertilge sie!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Opfern will ich dir mit Freiwilligkeit; deinen Namen will ich preisen, Jehova, denn er ist gut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Denn aus aller Bedrängnis hat er mich errettet; und mein Auge hat seine Lust gesehen an meinen Feinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Dem Vorsänger, mit Saitenspiel. Ein Maskil von David. Nimm zu Ohren, o Gott, mein Gebet, und verbirg dich nicht vor meinem Flehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Horche auf mich und antworte mir! Ich irre umher in meiner Klage und muß stöhnen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'vor der Stimme des Feindes, vor der Bedrückung des Gesetzlosen; denn sie wälzen Unheil auf mich, und im Zorn feinden sie mich an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Mein Herz ängstigte sich in meinem Innern, und Todesschrecken haben mich befallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Furcht und Zittern kamen mich an, und Schauder bedeckte mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Und ich sprach: O daß ich Flügel hätte wie die Taube! Ich wollte hinfliegen und ruhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Siehe, weithin entflöhe ich, würde weilen in der Wüste. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Ich wollte eilends entrinnen vor dem heftigen Winde, vor dem Sturme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Vernichte, Herr, zerteile ihre Zunge! Denn Gewalttat und Hader habe ich in der Stadt gesehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Tag und Nacht machen sie die Runde um sie auf ihren Mauern; und Unheil und Mühsal sind in ihrer Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Schadentun ist in ihrer Mitte, und Bedrückung und Trug weichen nicht von ihrer Straße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Denn nicht ein Feind ist es, der mich höhnt, sonst würde ich es ertragen; nicht mein Hasser ist es, der wider mich großgetan hat, sonst würde ich mich vor ihm verbergen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'sondern du, ein Mensch meinesgleichen, mein Freund und mein Vertrauter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'die wir trauten Umgang miteinander pflogen, ins Haus Gottes wandelten mit der Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Der Tod überrasche sie, lebendig mögen sie hinabfahren in den Scheol! Denn Bosheiten sind in ihrer Wohnung, in ihrem Innern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Ich aber, ich rufe zu Gott, und Jehova rettet mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Abends und morgens und mittags muß ich klagen und stöhnen, und er hört meine Stimme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Er hat meine Seele in Frieden erlöst aus dem Kampfe wider mich; denn ihrer sind viele gegen mich gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Hören wird Gott und sie demütigen, er thront ja von alters her (Sela.); weil es keine Änderung bei ihnen gibt und sie Gott nicht fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Er hat seine Hände ausgestreckt gegen die, welche mit ihm in Frieden waren; seinen Bund hat er gebrochen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Glatt sind die Milchworte seines Mundes, und Krieg ist sein Herz; geschmeidiger sind seine Worte als Öl, und sie sind gezogene Schwerter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Wirf auf Jehova, was dir auferlegt ist, und er wird dich erhalten; er wird nimmermehr zulassen, daß der Gerechte wanke!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Und du, Gott, wirst sie hinabstürzen in die Grube des Verderbens; die Männer des Blutes und des Truges werden nicht zur Hälfte bringen ihre Tage. Ich aber werde auf dich vertrauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Dem Vorsänger, nach: \"Die Taube der fernen Terebinthen\". Von David, ein Gedicht, als die Philister ihn zu Gath ergriffen. Sei mir gnädig, o Gott! Denn es schnaubt nach mir der Mensch; den ganzen Tag mich befehdend, bedrückt er mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Es schnauben meine Feinde den ganzen Tag; denn viele befehden mich in Hochmut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'An dem Tage, da ich mich fürchte, vertraue ich auf dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'In Gott werde ich rühmen sein Wort; auf Gott vertraue ich, ich werde mich nicht fürchten; was sollte das Fleisch mir tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Meine Worte verdrehen sie den ganzen Tag, alle ihre Gedanken sind wider mich zum Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Sie rotten sich zusammen, verstecken sich, sie beobachten meine Fersen, weil sie meiner Seele auflauern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Sollte bei ihrem Frevel Rettung für sie sein? Im Zorn stürze nieder die Völker, o Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Mein Umherirren zählst du. Lege in deinen Schlauch meine Tränen; sind sie nicht in deinem Buche?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Dann werden meine Feinde umkehren an dem Tage, da ich rufe; dieses weiß ich, daß Gott für mich ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'In Gott werde ich rühmen das Wort, in Jehova werde ich rühmen das Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Auf Gott vertraue ich; ich werde mich nicht fürchten; was sollte der Mensch mir tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Auf mir, o Gott, sind deine Gelübde, ich werde dir Dankopfer entrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Denn du hast meine Seele vom Tode errettet, ja, meine Füße vom Sturz, um zu wandeln vor dem Angesicht Gottes im Lichte der Lebendigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Dem Vorsänger. \"Verdirb nicht!\" Von David, ein Gedicht, als er vor Saul in die Höhle floh. Sei mir gnädig, o Gott, sei mir gnädig! Denn zu dir nimmt Zuflucht meine Seele, und ich will Zuflucht nehmen zu dem Schatten deiner Flügel, bis vorübergezogen das Verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Zu Gott, dem Höchsten, will ich rufen, zu dem Gott, der es für mich vollendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Vom Himmel wird er senden und mich retten; er macht zum Hohn den, der nach mir schnaubt. (Sela.) Senden wird Gott seine Güte und seine Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Mitten unter Löwen ist meine Seele, unter Flammensprühenden liege ich, unter Menschenkindern, deren Zähne Speere und Pfeile, und deren Zunge ein scharfes Schwert ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Erhebe dich über die Himmel, o Gott! Über der ganzen Erde sei deine Herrlichkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Ein Netz haben sie meinen Schritten bereitet, es beugte sich nieder meine Seele; eine Grube haben sie vor mir gegraben, sie sind mitten hineingefallen. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Befestigt ist mein Herz, o Gott, befestigt ist mein Herz! Ich will singen und Psalmen singen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Wache auf, meine Seele! Wachet auf, Harfe und Laute! Ich will aufwecken die Morgenröte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Ich will dich preisen, Herr, unter den Völkern, will dich besingen unter den Völkerschaften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Denn groß bis zu den Himmeln ist deine Güte, und bis zu den Wolken deine Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Erhebe dich über die Himmel, o Gott! Über der ganzen Erde sei deine Herrlichkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Dem Vorsänger. \"Verdirb nicht!\" Von David, ein Gedicht. Redet ihr wirklich Gerechtigkeit durch Verstummen? Richtet ihr in Geradheit, ihr Menschenkinder?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Ja, im Herzen übet ihr Ungerechtigkeiten; eurer Hände Gewalttat wäget ihr dar im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Abgewichen sind die Gesetzlosen von Mutterschoße an, es irren von Mutterleibe an die Lügenredner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Gift haben sie gleich Schlangengift, wie eine taube Otter, die ihr Ohr verschließt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'die nicht hört auf die Stimme der Beschwörer, des Zauberers, der der Zaubersprüche kundig ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Zerschmettere, o Gott, ihre Zähne in ihrem Maule, brich aus das Gebiß der jungen Löwen, Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Laß sie zergehen wie Wasser, die zerfließen! Legt er seine Pfeile an, so seien sie wie abgestumpft!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Laß sie sein gleich der Schnecke, die zerschmelzend dahingeht, gleich der Fehlgeburt eines Weibes, welche die Sonne nie erblickt hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Bevor eure Töpfe den Dorn merken, möge er ihn, frisch oder brennend, hinwegstürmen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Freuen wird sich der Gerechte, wenn er die Rache anschaut; er wird seine Füße baden im Blute des Gesetzlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Und der Mensch wird sagen: Fürwahr, es gibt Lohn für den Gerechten; fürwahr, es gibt einen Gott, der auf Erden richtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Dem Vorsänger, \"Verdirb nicht!\" Von David, ein Gedicht, als Saul sandte, und sie sein Haus bewachten, um ihn zu töten. Befreie mich von meinen Feinden, o mein Gott! Setze mich in Sicherheit vor denen, die sich wider mich erheben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Befreie mich von denen, die Frevel tun, und rette mich von den Blutmenschen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Denn siehe, sie lauern auf meine Seele; Starke rotten sich wider mich ohne meine Übertretung und ohne meine Sünde, Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Ohne eine Schuld meinerseits laufen und bereiten sie sich; wache auf, mir entgegen, und sieh!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Ja, du, Jehova, Gott der Heerscharen, Gott Israels, erwache, um heimzusuchen alle Nationen! Sei keinem gnädig von den treulos Frevelnden! (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Am Abend kehren sie zurück, heulen wie Hunde, und rings umgehen sie die Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Siehe, aus ihrem Munde sprudeln sie Böses hervor, Schwerter sind auf ihren Lippen, denn \"wer hört?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Du aber, Jehova, wirst ihrer lachen, wirst spotten aller Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Meine Stärke, auf dich will ich achten; denn Gott ist meine hohe Feste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Mein Gott wird mir mit seiner Güte zuvorkommen; Gott wird mich meine Lust sehen lassen an meinen Feinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Töte sie nicht, damit mein Volk es nicht vergesse; laß sie umherirren durch deine Macht, und stürze sie nieder, Herr, unser Schild!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Sünde ihres Mundes ist das Wort ihrer Lippen; so laß sie gefangen werden in ihrem Hochmut und wegen des Fluches und wegen der Lüge, die sie aussprechen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Mache ein Ende im Grimm, mache ein Ende, daß sie nicht mehr seien, und erkennen, daß Gott in Jakob herrscht bis an die Enden der Erde! (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Und am Abend kehren sie zurück, heulen wie Hunde, und rings umgehen sie die Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Sie schweifen umher nach Speise; sie übernachten, wenn sie auch nicht satt sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Ich aber will singen von deiner Stärke, und des Morgens jubelnd preisen deine Güte; denn du bist mir eine hohe Feste gewesen und ein Zuflucht am Tage meiner Bedrängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Dir, meine Stärke, will ich Psalmen singen; denn Gott ist meine hohe Feste, der Gott meiner Güte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Dem Vorsänger; nach Schuschan-Eduth. Ein Gedicht von David, zum Lehren, als er stritt mit den Syrern von Mesopotamien und mit den Syrern von Zoba, und Joab zurückkehrte und die Edomiter im Salztale schlug, zwölftausend Mann. Gott, du hast uns verworfen, hast uns zerstreut, bist zornig gewesen; führe uns wieder zurück!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Du hast das Land erschüttert, hast es zerrissen; heile seine Risse, denn es wankt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Du hast dein Volk Hartes sehen lassen, mit Taumelwein hast du uns getränkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Denen, die dich fürchten, hast du ein Panier gegeben, daß es sich erhebe um der Wahrheit willen. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Damit befreit werden deine Geliebten, rette durch deine Rechte und erhöre uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Gott hat geredet in seiner Heiligkeit: Frohlocken will ich, will Sichem verteilen und das Tal Sukkoth ausmessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Mein ist Gilead, und mein Manasse, und Ephraim ist die Wehr meines Hauptes, Juda mein Herrscherstab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Moab ist mein Waschbecken, auf Edom will ich meine Sandale werfen; Philistäa, jauchze mir zu!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Wer wird mich führen in die feste Stadt, wer wird mich leiten bis nach Edom?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Nicht du, Gott, der du uns verworfen hast, und nicht auszogest, o Gott, mit unseren Heeren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Schaffe uns Hilfe aus der Bedrängnis! Menschenrettung ist ja eitel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Mit Gott werden wir mächtige Taten tun; und er, er wird unsere Bedränger zertreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Dem Vorsänger, mit Saitenspiel. Von David. Höre, Gott, mein Schreien, horche auf mein Gebet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Vom Ende der Erde werde ich zu dir rufen, wenn mein Herz verschmachtet; du wirst mich auf einen Felsen leiten, der mir zu hoch ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Denn du bist mir eine Zuflucht gewesen, ein starker Turm, vor dem Feinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Ich werde weilen in deinem Zelte in Ewigkeit, werde Zuflucht nehmen zu dem Schutze deiner Flügel. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Denn du, Gott, hast auf meine Gelübde gehört, hast mir gegeben das Erbteil derer, die deinen Namen fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Du wirst Tage hinzufügen zu den Tagen des Königs; seine Jahre werden sein wie Geschlechter und Geschlechter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Er wird ewiglich bleiben vor dem Angesicht Gottes. Bestelle Güte und Wahrheit, daß sie ihn behüten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Also werde ich deinen Namen besingen immerdar, indem ich meine Gelübde bezahle Tag für Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Dem Vorsänger; für Jeduthun. Ein Psalm von David. Nur auf Gott vertraut still meine Seele, von ihm kommt meine Rettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Nur er ist mein Fels und meine Rettung, meine hohe Feste; ich werde nicht viel wanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Bis wann wollt ihr gegen einen Mann anstürmen, ihr alle ihn niederreißen wie eine überhängende Wand, eine angestoßene Mauer?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Sie ratschlagen nur, ihn von seiner Höhe zu stoßen; sie haben Wohlgefallen an der Lüge; mit ihrem Munde segnen sie, und in ihrem Innern fluchen sie. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Nur auf Gott vertraue still meine Seele! Denn von ihm kommt meine Erwartung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Nur er ist mein Fels und meine Rettung, meine hohe Feste; ich werde nicht wanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Auf Gott ruht mein Heil und meine Herrlichkeit; der Fels meiner Stärke, meine Zuflucht, ist in Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Vertrauet auf ihn allezeit, o Volk! Schüttet vor ihm aus euer Herz! Gott ist unsere Zuflucht. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Nur Eitelkeit sind die Menschensöhne, Lüge die Männersöhne. Auf der Waagschale steigen sie empor, sie sind allesamt leichter als ein Hauch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Vertrauet nicht auf Erpressung, und setzet nicht eitle Hoffnung auf Raub; wenn der Reichtum wächst, so setzet euer Herz nicht darauf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Einmal hat Gott geredet, zweimal habe ich dieses gehört, daß die Stärke Gottes sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Und dein, o Herr, ist die Güte; denn du, du vergiltst einem jeden nach seinem Werke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Ein Psalm von David, als er in der Wüste Juda war. Gott, du bist mein Gott! Frühe suche ich dich. Es dürstet nach dir meine Seele, nach dir schmachtet mein Fleisch in einem dürren und lechzenden Lande ohne Wasser,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'gleichwie ich dich angeschaut habe im Heiligtum, um deine Macht und deine Herrlichkeit zu sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Denn deine Güte ist besser als Leben; meine Lippen werden dich rühmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Also werde ich dich preisen während meines Lebens, meine Hände aufheben in deinem Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Wie von Mark und Fett wird gesättigt werden meine Seele, und mit jubelnden Lippen wird loben mein Mund,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Wenn ich deiner gedenke auf meinem Lager, über dich sinne in den Nachtwachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Denn du bist mir zur Hilfe gewesen, und ich werde jubeln in dem Schatten deiner Flügel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Meine Seele hängt dir nach, es hält mich aufrecht deine Rechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Jene aber, die nach meinem Leben trachten, um es zu verderben, werden hineingehen in die untersten Örter der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Man wird sie preisgeben der Gewalt des Schwertes, das Teil der Schakale werden sie sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Und der König wird sich freuen in Gott; es wird sich rühmen ein jeder, der bei ihm schwört; denn der Mund der Lügenredner wird verstopft werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Dem Vorsänger. Ein Psalm von David. Höre, Gott, meine Stimme in meiner Klage; vor dem Schrecken des Feindes behüte mein Leben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Verbirg mich vor dem geheimen Rat der Übeltäter, vor der Rotte derer, die Frevel tun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Welche ihre Zunge geschärft haben gleich einem Schwerte, ihren Pfeil angelegt, bitteres Wort,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'um im Versteck zu schießen auf den Unsträflichen: plötzlich schießen sie auf ihn und scheuen sich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Sie stärken sich in einer bösen Sache; sie reden davon, Fallstricke zu verbergen; sie sagen: Wer wird uns sehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Sie denken Schlechtigkeiten aus: \"Wir haben\'s fertig, der Plan ist ausgedacht!\" Und eines jeden Inneres und Herz ist tief.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Aber Gott schießt auf sie, plötzlich kommt ein Pfeil: ihre Wunden sind da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Und sie werden zu Fall gebracht, ihre Zunge kommt über sie; alle, die sie sehen, werden den Kopf schütteln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Und es werden sich fürchten alle Menschen, und das Tun Gottes verkünden und sein Werk erwägen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Der Gerechte wird sich in Jehova freuen und auf ihn trauen; und es werden sich rühmen alle von Herzen Aufrichtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Dem Vorsänger, ein Psalm. Von David, ein Lied. Deiner harrt schweigend der Lobgesang, o Gott, in Zion, und dir wird bezahlt werden das Gelübde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Hörer des Gebets! Zu dir wird kommen alles Fleisch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Ungerechtigkeiten haben mich überwältigt; unsere Übertretungen, du wirst sie vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Glückselig der, den du erwählst und herzunahen lässest, daß er wohne in deinen Vorhöfen! Wir werden gesättigt werden mit dem Guten deines Hauses, dem Heiligen deines Tempels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Du wirst uns antworten durch furchtbare Dinge in Gerechtigkeit, Gott unseres Heils, du Zuversicht aller Enden der Erde und der fernsten Meere!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Der die Berge feststellt durch seine Kraft, umgürtet ist mit Macht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'der da stillt das Brausen der Meere, das Brausen ihrer Wellen und das Getümmel der Völkerschaften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Und es fürchten sich die Bewohner der Enden der Erde, vor deinen Zeichen; du machst jauchzen die Ausgänge des Morgens und des Abends.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Du hast die Erde heimgesucht und ihr Überfluß gewährt, du bereicherst sie sehr: Gottes Bach ist voll Wassers. Du bereitest ihr Getreide, wenn du sie also bereitest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Du tränkest ihre Furchen, ebnest ihre Schollen, du erweichst sie mit Regengüssen, segnest ihr Gewächs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Du hast gekrönt das Jahr deiner Güte, und deine Spuren triefen von Fett.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Es triefen die Auen der Steppe, und mit Jubel umgürten sich die Hügel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Die Triften bekleiden sich mit Herden, und die Täler bedecken sich mit Korn; sie jauchzen, ja, sie singen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Dem Vorsänger. Ein Lied, ein Psalm. Jauchzet Gott, ganze Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Besinget die Herrlichkeit seines Namens, machet herrlich sein Lob!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Sprechet zu Gott: Wie furchtbar sind deine Werke! Wegen der Größe deiner Stärke unterwerfen sich dir deine Feinde mit Schmeichelei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Die ganze Erde wird dich anbeten und dir Psalmen singen; sie wird besingen deinen Namen. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Kommet und sehet die Großtaten Gottes; furchtbar ist er in seinem Tun gegen die Menschenkinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Er wandelte das Meer in trockenes Land, sie gingen zu Fuß durch den Strom; da freuten wir uns in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Er herrscht durch seine Macht auf ewig; seine Augen beobachten die Nationen. Daß sich nicht erheben die Widerspenstigen! (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Preiset, ihr Völker, unseren Gott, und lasset hören die Stimme seines Lobes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'der unsere Seele am Leben erhalten und nicht zugelassen hat, daß unsere Füße wankten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Denn du hast uns geprüft, o Gott, du hast uns geläutert, wie man Silber läutert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Du hast uns ins Netz gebracht, hast eine drückende Last auf unsere Lenden gelegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Du hast Menschen reiten lassen auf unserem Haupte; wir sind ins Feuer und ins Wasser gekommen, aber du hast uns herausgeführt zu überströmender Erquickung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Ich will eingehen in dein Haus mit Brandopfern, will dir bezahlen meine Gelübde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'wozu sich weit aufgetan meine Lippen, und die mein Mund ausgesprochen hat in meiner Bedrängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Brandopfer von Mastvieh will ich dir opfern samt Räucherwerk von Widdern; Rinder samt Böcken will ich opfern. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Kommet, höret zu, alle, die ihr Gott fürchtet, und ich will erzählen, was er an meiner Seele getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Zu ihm rief ich mit meinem Munde, und seine Erhebung war unter meiner Zunge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Wenn ich es in meinem Herzen auf Frevel abgesehen hätte, so würde der Herr nicht gehört haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Doch Gott hat gehört, er hat gemerkt auf die Stimme meines Gebets.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Gepriesen sei Gott, der nicht abgewiesen hat mein Gebet, noch von mir abgewandt seine Güte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Dem Vorsänger, mit Saitenspiel. Ein Psalm, ein Lied. Gott sei uns gnädig und segne uns, er lasse sein Angesicht leuchten über uns, (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'daß man auf der Erde erkenne deinen Weg, unter allen Nationen deine Rettung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Es werden dich preisen die Völker, o Gott; es werden dich preisen die Völker alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Es werden sich freuen und jubeln die Völkerschaften; denn du wirst die Völker richten in Geradheit, und die Völkerschaften auf der Erde, du wirst sie leiten. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Es werden dich preisen die Völker, o Gott; es werden dich preisen die Völker alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Die Erde gibt ihren Ertrag; Gott, unser Gott, wird uns segnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Gott wird uns segnen, und alle Enden der Erde werden ihn fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Dem Vorsänger. Von David. Ein Psalm, ein Lied. Möge Gott aufstehen! Mögen sich zerstreuen seine Feinde, und vor ihm fliehen seine Hasser!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Wie Rauch vertrieben wird, so wirst du sie vertreiben; wie Wachs vor dem Feuer zerschmilzt, so werden die Gesetzlosen umkommen vor dem Angesicht Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Aber freuen werden sich die Gerechten, sie werden frohlocken vor dem Angesicht Gottes und jubeln in Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Singet Gott, besinget seinen Namen! Machet Bahn dem, der einherfährt durch die Wüsteneien, Jah ist sein Name, und frohlocket vor ihm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Ein Vater der Waisen und ein Richter der Witwen ist Gott in seiner heiligen Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Gott läßt Einsame in einem Hause wohnen, führt Gefangene hinaus ins Glück; die Widerspenstigen aber wohnen in der Dürre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Gott, als du auszogest vor deinem Volke, als du einherschrittest durch die Wüste, (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'da bebte die Erde, auch troffen die Himmel vor Gott, jener Sinai vor Gott, dem Gott Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Reichlichen Regen gossest du aus, o Gott; dein Erbteil, wenn es ermattet war, richtetest du es auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Deine Schar hat darin gewohnt; du bereitetest in deiner Güte für den Elenden, o Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Der Herr erläßt das Wort; der Siegesbotinnen ist eine große Schar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Die Könige der Heere fliehen, sie fliehen, und die Hausbewohnerin verteilt die Beute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Wenn ihr zwischen den Hürden lieget, werdet ihr sein wie die Flügel einer Taube, die überzogen sind mit Silber, und ihre Schwingen mit grüngelbem Golde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Wenn der Allmächtige Könige darin zerstreut, wird es schneeweiß auf dem Zalmon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Der Berg Basans ist ein Berg Gottes, ein gipfelreicher Berg ist der Berg Basans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Warum blicket ihr neidisch, ihr gipfelreichen Berge, auf den Berg, den Gott begehrt hat zu seinem Wohnsitz? Auch wird Jehova daselbst wohnen immerdar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Der Wagen Gottes sind zwei Zehntausende, Tausende und aber Tausende; der Herr ist unter ihnen: ein Sinai an Heiligkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Du bist aufgefahren in die Höhe, du hast die Gefangenschaft gefangen geführt; du hast Gaben empfangen im Menschen, und selbst für Widerspenstige, damit Jehova, Gott, eine Wohnung habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Gepriesen sei der Herr! Tag für Tag trägt er unsere Last; Gott ist unsere Rettung. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Gott ist uns ein Gott der Rettungen, und bei Jehova, dem Herrn, stehen die Ausgänge vom Tode.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Gewiß, Gott wird zerschmettern das Haupt seiner Feinde, den Haarscheitel dessen, der da wandelt in seinen Vergehungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Der Herr sprach: Ich werde zurückbringen aus Basan, zurückbringen aus den Tiefen des Meeres,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'auf daß du deinen Fuß in Blut badest, und die Zunge deiner Hunde von den Feinden ihr Teil habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Gesehen haben sie deine Züge, o Gott, die Züge meines Gottes, meines Königs im Heiligtum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Voran gingen Sänger, danach Saitenspieler, inmitten tamburinschlagender Jungfrauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, '\"Preiset Gott, den Herrn, in den Versammlungen, die ihr aus der Quelle Israels seid!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Da sind Benjamin, der Jüngste, ihr Herrscher, die Fürsten Judas, ihr Haufe, die Fürsten Sebulons, die Fürsten Naphtalis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Geboten hat dein Gott deine Stärke. Stärke, o Gott, das, was du für uns gewirkt hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Um deines Tempels zu Jerusalem willen werden Könige dir Geschenke bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Schilt das Tier des Schilfes, die Schar der Stiere mit den Kälbern der Völker; jeder wird sich dir unterwerfen mit Silberbarren. Zerstreue die Völker, die Lust haben am Kriege!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Es werden kommen die Großen aus Ägypten; Äthiopien wird eilends seine Hände ausstrecken zu Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Ihr Königreiche der Erde, singet Gott, besinget den Herrn, (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'den, der da einherfährt auf den Himmeln, den Himmeln der Vorzeit! Siehe, er läßt seine Stimme erschallen, eine mächtige Stimme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Gebet Gott Stärke! Seine Hoheit ist über Israel und seine Macht in den Wolken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Furchtbar bist du, Gott, aus deinen Heiligtümern her; der Gott Israels, er ist es, der Stärke und Kraft gibt dem Volke. Gepriesen sei Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Dem Vorsänger, nach Schoschannim. Von David. Rette mich, o Gott! Denn die Wasser sind bis an die Seele gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Ich bin versunken in tiefen Schlamm, und kein Grund ist da; in Wassertiefen bin ich gekommen, und die Flut überströmt mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Ich bin müde vom Rufen, entzündet ist meine Kehle; meine Augen schwinden hin, harrend auf meinen Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Mehr als die Haare meines Hauptes sind derer, die ohne Ursache mich hassen; mächtig sind meine Vertilger, die ohne Grund mir feind sind; was ich nicht geraubt habe, muß ich alsdann erstatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Du, o Gott, weißt um meine Torheit, und meine Vergehungen sind dir nicht verborgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Laß nicht durch mich beschämt werden, die auf dich harren, Herr, Jehova der Heerscharen! Laß nicht durch mich zu Schanden werden, die dich suchen, Gott Israels!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Denn deinetwegen trage ich Hohn, hat Schande bedeckt mein Antlitz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Entfremdet bin ich meinen Brüdern, und ein Fremdling geworden den Söhnen meiner Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Denn der Eifer um dein Haus hat mich verzehrt, und die Schmähungen derer, die dich schmähen, sind auf mich gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Als ich weinte, und meine Seele im Fasten war, da wurde es mir zu Schmähungen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'als ich mich in Sacktuch kleidete, da ward ich ihnen zum Sprichwort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Die im Tore sitzen, reden über mich, und ich bin das Saitenspiel der Zecher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Ich aber, mein Gebet ist zu dir, Jehova, zur Zeit der Annehmung. O Gott, nach der Größe deiner Güte, erhöre mich nach der Wahrheit deines Heils!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Ziehe mich heraus aus dem Schlamm, daß ich nicht versinke! Laß mich errettet werden von meinen Hassern und aus den Wassertiefen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Laß die Flut der Wasser mich nicht überströmen, und die Tiefe mich nicht verschlingen; und laß die Grube ihren Mund nicht über mir verschließen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Erhöre mich, Jehova! Denn gut ist deine Güte; wende dich zu mir nach der Größe deiner Erbarmungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Und verbirg dein Angesicht nicht vor deinem Knechte! Denn ich bin bedrängt; eilends erhöre mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Nahe meiner Seele, erlöse sie; erlöse mich um meiner Feinde willen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Du, du kennst meinen Hohn und meine Schmach und meine Schande; vor dir sind alle meine Bedränger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Der Hohn hat mein Herz gebrochen, und ich bin ganz elend; und ich habe auf Mitleiden gewartet, und da war keines, und auf Tröster, und ich habe keine gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Und sie gaben in meine Speise Galle, und in meinem Durst tränkten sie mich mit Essig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Es werde zur Schlinge vor ihnen ihr Tisch, und ihnen, den Sorglosen, zum Fallstrick!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Laß dunkel werden ihre Augen, daß sie nicht sehen; und laß beständig wanken ihre Lenden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Schütte über sie aus deinen Grimm, und deines Zornes Glut erreiche sie!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Verwüstet sei ihre Wohnung, in ihren Zelten sei kein Bewohner!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Denn den du geschlagen hast, haben sie verfolgt, und von dem Schmerze deiner Verwundeten erzählen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Füge Ungerechtigkeit zu ihrer Ungerechtigkeit, und laß sie nicht kommen zu deiner Gerechtigkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Laß sie ausgelöscht werden aus dem Buche des Lebens, und nicht eingeschrieben mit den Gerechten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Ich aber bin elend, und mir ist wehe; deine Rettung, o Gott, setze mich in Sicherheit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Rühmen will ich den Namen Gottes im Liede, und ihn erheben mit Lob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Und es wird Jehova wohlgefälliger sein als ein Stier, ein Farre mit Hörnern und gespaltenen Hufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Die Sanftmütigen werden es sehen, sie werden sich freuen; ihr, die ihr Gott suchet, es lebe euer Herz!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Denn Jehova hört auf die Armen, und seine Gefangenen verachtet er nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Ihn sollen loben Himmel und Erde, die Meere, und alles, was in ihnen wimmelt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Denn Gott wird Zion retten und die Städte Judas bauen; und sie werden daselbst wohnen und es besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Und der Same seiner Knechte wird es erben; und die seinen Namen lieben, werden darin wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Dem Vorsänger. Von David, zum Gedächtnis. Eile, Gott, mich zu erretten, Jehova, zu meiner Hilfe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Laß beschämt und mit Scham bedeckt werden, die nach meinem Leben trachten! Laß zurückweichen und zu Schanden werden, die Gefallen haben an meinem Unglück!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Laß umkehren ob ihrer Schande, die da sagen: Haha! Haha!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Laß fröhlich sein und in dir sich freuen alle, die dich suchen! Und die deine Rettung lieben, laß stets sagen: Erhoben sei Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Ich aber bin elend und arm; o Gott, eile zu mir! Meine Hilfe und mein Erretter bist du; Jehova, zögere nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Auf dich, Jehova, traue ich: Laß mich nimmer beschämt werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'In deiner Gerechtigkeit befreie mich und errette mich! Neige dein Ohr zu mir und schaffe mir Rettung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Sei mir ein Fels zur Wohnung, um stets dahin zu gehen! Du hast geboten, mich zu retten, denn du bist mein Fels und meine Burg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Mein Gott, errette mich aus der Hand des Gesetzlosen, aus der Faust des Ungerechten und des Gewaltsamen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Denn du bist meine Hoffnung, Herr, Jehova; meine Zuversicht von meiner Jugend an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Auf dich habe ich mich gestützt von Mutterschoße an, aus meiner Mutter Leibe zogest du mich hervor; von dir ist stets mein Lobgesang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Vielen bin ich wie ein Wunder; du aber bist meine starke Zuflucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Mein Mund ist erfüllt von deinem Lobe, von deinem Ruhm den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Verwirf mich nicht zur Zeit des Alters; beim Schwinden meiner Kraft verlaß mich nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Denn meine Feinde haben von mir geredet, und die auf meine Seele lauern, miteinander geratschlagt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'und sie sagen: Gott hat ihn verlassen; verfolget und greifet ihn, denn kein Erretter ist da!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'O Gott, sei nicht fern von mir; mein Gott, eile zu meiner Hilfe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Laß beschämt werden, laß vergehen, die wider meine Seele sind! Laß mit Hohn und Schande bedeckt werden, die mein Unglück suchen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Ich aber will beständig harren und all dein Lob vermehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Mein Mund soll erzählen deine Gerechtigkeit, den ganzen Tag deine Rettung; denn ich weiß sie nicht zu zählen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Ich werde kommen mit den Machttaten des Herrn Jehova, werde gedenken deiner Gerechtigkeit, deiner allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Gott! Du hast mich gelehrt von meiner Jugend an, und bis hierher habe ich deine Wundertaten verkündet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Und auch bis zum Alter und bis zum Greisentum verlaß mich nicht, o Gott, bis ich verkünde deinen Arm dem künftigen Geschlecht, allen, die da kommen werden, deine Macht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Und deine Gerechtigkeit, o Gott, reicht bis zur Höhe; du, der du große Dinge getan hast, o Gott, wer ist wie du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Du, der du uns viele Bedrängnisse und Übel hast sehen lassen, du wirst uns wieder beleben, und uns wieder heraufführen aus den Tiefen der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Du wirst meine Größe mehren, und du wirst dich wenden und mich trösten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Auch will ich dich preisen mit der Harfe, ja, deine Wahrheit, mein Gott! Ich will dir Psalmen singen mit der Laute, du Heiliger Israels!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Jubeln werden meine Lippen, wenn ich dir Psalmen singe, und meine Seele, die du erlöst hast;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'auch meine Zunge wird von deiner Gerechtigkeit reden den ganzen Tag; denn beschämt, denn mit Scham sind bedeckt worden, die mein Unglück suchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Für Salomo. O Gott, gib dem Könige deine Gerichte, und deine Gerechtigkeit dem Sohne des Königs!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Er wird dein Volk richten in Gerechtigkeit, und deine Elenden nach Recht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Es werden dem Volke Frieden tragen die Berge und die Hügel durch Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Er wird Recht schaffen den Elenden des Volkes; er wird retten die Kinder des Armen, und den Bedrücker wird er zertreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Man wird dich fürchten von Geschlecht zu Geschlecht, so lange Sonne und Mond bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Er wird herabkommen wie ein Regen auf die gemähte Flur, wie Regenschauer, Regengüsse auf das Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'In seinen Tagen wird der Gerechte blühen, und Fülle von Frieden wird sein, bis der Mond nicht mehr ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Und er wird herrschen von Meer zu Meer, und vom Strome bis an die Enden der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Vor ihm werden sich beugen die Bewohner der Wüste, und seine Feinde werden den Staub lecken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'die Könige von Tarsis und von den Inseln werden Geschenke entrichten, es werden Abgaben darbringen die Könige von Scheba und Seba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Und alle Könige werden vor ihm niederfallen, alle Nationen ihm dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Denn erretten wird er den Armen, der um Hilfe ruft, und den Elenden, der keinen Helfer hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Er wird sich erbarmen des Geringen und des Armen, und die Seelen der Armen wird er retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Von Bedrückung und Gewalttat wird er ihre Seele erlösen, und ihr Blut wird teuer sein in seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Und er wird leben, und von dem Golde Schebas wird man ihm geben; und man wird beständig für ihn beten, den ganzen Tag ihn segnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Es wird Überfluß an Getreide sein im Lande, auf dem Gipfel der Berge; gleich dem Libanon wird rauschen seine Frucht; und Menschen werden hervorblühen aus den Städten wie das Kraut der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Sein Name wird ewig sein; so lange die Sonne besteht, wird fortdauern sein Name; und in ihm wird man sich segnen; alle Nationen werden ihn glücklich preisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Gepriesen sei Jehova, Gott, der Gott Israels, der Wunder tut, er allein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Und gepriesen sei sein herrlicher Name in Ewigkeit! Und die ganze Erde werde erfüllt mit seiner Herrlichkeit! Amen, ja, Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Es sind zu Ende die Gebete Davids, des Sohnes Isais.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Ein Psalm; von Asaph. Fürwahr, Gott ist Israel gut, denen, die reinen Herzens sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Ich aber, wenig fehlte, so wären meine Füße abgewichen, um nichts wären ausgeglitten meine Schritte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Denn ich beneidete die Übermütigen, als ich sah die Wohlfahrt der Gesetzlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Denn keine Qualen haben sie bei ihrem Tode, und wohlgenährt ist ihr Leib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Nicht sind sie im Ungemach der Sterblichen, und mit den Menschen werden sie nicht geplagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Deshalb umgibt sie der Hochmut wie ein Halsgeschmeide, Gewalttat umhüllt sie wie ein Gewand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Es tritt aus dem Fett hervor ihr Auge; sie wallen über in den Einbildungen des Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Sie höhnen und reden in Bosheit von Bedrückung; von oben herab reden sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Sie setzen in den Himmel ihren Mund, und ihre Zunge wandelt auf der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Deshalb wendet sich hierher sein Volk, und Wasser in Fülle wird von ihnen geschlürft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Und sie sprechen: Wie wüßte es Gott, und wie sollte Wissen sein bei dem Höchsten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Siehe, diese sind Gesetzlose, und, immerdar sorglos, erwerben sie sich Vermögen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Fürwahr, vergebens habe ich mein Herz gereinigt, und in Unschuld gewaschen meine Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Da ich ja geplagt ward den ganzen Tag, und alle Morgen meine Züchtigung da war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Wenn ich gesagt hätte: Ich will ebenso reden, siehe, so wäre ich treulos gewesen dem Geschlecht deiner Söhne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Da dachte ich nach, um dieses zu begreifen: eine mühevolle Arbeit war es in meinen Augen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'bis ich hineinging in die Heiligtümer Gottes und jener Ende gewahrte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Fürwahr, auf schlüpfrige Örter setzest du sie, stürzest sie hin zu Trümmern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Wie sind sie so plötzlich verwüstet, haben ein Ende genommen, sind umgekommen durch Schrecknisse!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Wie einen Traum nach dem Erwachen wirst du, Herr, beim Aufwachen ihr Bild verachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Als mein Herz sich erbitterte und es mich in meinen Nieren stach,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'da war ich dumm und wußte nichts; ein Tier war ich bei dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Doch ich bin stets bei dir: du hast mich erfaßt bei meiner rechten Hand;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'durch deinen Rat wirst du mich leiten, und nach der Herrlichkeit wirst du mich aufnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Wen habe ich im Himmel? Und neben dir habe ich an nichts Lust auf der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Vergeht mein Fleisch und mein Herz, meines Herzens Fels und mein Teil ist Gott auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Denn siehe, es werden umkommen, die dir ferne sind; du vertilgst alle, die buhlerisch von dir abweichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Ich aber, Gott zu nahen ist mir gut; ich habe meine Zuversicht auf den Herrn, Jehova, gesetzt, um zu erzählen alle deine Taten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Ein Maskil; von Asaph. Gott, warum hast du verworfen für immer, raucht dein Zorn wider die Herde deiner Weide?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Gedenke deiner Gemeinde, die du erworben hast vor alters, erlöst als dein Erbteil, des Berges Zion, auf welchem du gewohnt hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Erhebe deine Tritte zu den immerwährenden Trümmern! Alles im Heiligtum hat der Feind verderbt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Es brüllen deine Widersacher inmitten deiner Versammlungsstätte; sie haben ihre Zeichen als Zeichen gesetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Sie erscheinen wie einer, der die Axt emporhebt im Dickicht des Waldes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'und jetzt zerschlagen sie sein Schnitzwerk allzumal mit Beilen und mit Hämmern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Sie haben dein Heiligtum in Brand gesteckt, zu Boden entweiht die Wohnung deines Namens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Sie sprachen in ihrem Herzen: Laßt uns sie niederzwingen allesamt! Verbrannt haben sie alle Versammlungsstätten Gottes im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Unsere Zeichen sehen wir nicht; kein Prophet ist mehr da, und keiner bei uns, welcher weiß, bis wann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Bis wann, o Gott, soll höhnen der Bedränger, soll der Feind deinen Namen verachten immerfort?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Warum ziehst du deine Hand und deine Rechte zurück? Hervor aus deinem Busen, mache ein Ende!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Gott ist ja mein König von alters her, der Rettungen schafft inmitten des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Du zerteiltest das Meer durch deine Macht, zerschelltest die Häupter der Wasserungeheuer auf den Wassern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Du zerschmettertest die Häupter des Leviathans, gabst ihn zur Speise dem Volke, den Bewohnern der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Du ließest Quell und Bach hervorbrechen, immerfließende Ströme trocknetest du aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Dein ist der Tag, dein auch die Nacht; den Mond und die Sonne hast du bereitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Du hast festgestellt alle Grenzen der Erde; Sommer und Winter, du hast sie gebildet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Gedenke dessen: der Feind hat Jehova gehöhnt, und ein törichtes Volk hat deinen Namen verachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Gib nicht dem Raubtiere hin die Seele deiner Turteltaube; die Schar deiner Elenden vergiß nicht für immer!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Schaue hin auf den Bund! Denn die finsteren Örter der Erde sind voll von Wohnungen der Gewalttat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Nicht kehre beschämt zurück der Unterdrückte; laß den Elenden und Armen deinen Namen loben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Stehe auf, o Gott, führe deinen Rechtsstreit! Gedenke deiner Verhöhnung von den Toren den ganzen Tag!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Vergiß nicht die Stimme deiner Widersacher! Das Getöse derer, die sich wider dich erheben, steigt auf beständig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Dem Vorsänger, \"Verdirb nicht!\" Ein Psalm von Asaph, ein Lied. Wir preisen dich, o Gott, wir preisen dich; und nahe ist dein Name, deine Wundertaten verkündigen es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, '\"Wenn ich die Versammlung empfangen werde, will ich in Geradheit richten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Zerschmolzen sind die Erde und alle ihre Bewohner: Ich habe ihre Säulen festgestellt.\" (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Ich sprach zu den Übermütigen: Seid nicht übermütig! und zu den Gesetzlosen: Erhebet nicht das Horn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Erhebet nicht hoch euer Horn; redet nicht Freches mit gerecktem Halse!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Denn nicht von Osten, noch von Westen, und nicht von Süden her kommt Erhöhung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Denn Gott ist Richter; diesen erniedrigt er, und jenen erhöht er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Denn ein Becher ist in der Hand Jehovas, und er schäumt von Wein, ist voll von Würzwein, und er schenkt daraus: ja, seine Hefen müssen schlürfend trinken alle Gesetzlosen der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Ich aber, ich will es verkünden ewiglich, will Psalmen singen dem Gott Jakobs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Und alle Hörner der Gesetzlosen werde ich abhauen; es werden erhöht werden die Hörner der Gerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Dem Vorsänger, mit Saitenspiel. Ein Psalm von Asaph, ein Lied. Bekannt ist Gott in Juda, in Israel groß sein Name.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Und in Salem ist seine Hütte, und seine Wohnung in Zion.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Dort zerbrach er des Bogens Blitze, Schild und Schwert und Krieg. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Glanzvoller bist du, herrlicher als die Berge des Raubes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Zur Beute sind geworden die Starkherzigen, sie schlafen ihren Schlaf; und keiner der tapferen Männer fand seine Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Vor deinem Schelten, Gott Jakobs, sind in tiefen Schlaf gesunken sowohl Wagen als Roß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Du, du bist furchtbar, und wer kann vor dir bestehen, sobald du erzürnst!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Du ließest Gericht hören von den Himmeln her; die Erde fürchtete sich und ward stille.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Als Gott aufstand zum Gericht, um zu retten alle Sanftmütigen des Landes. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Denn der Grimm des Menschen wird dich preisen; mit dem Rest des Grimmes wirst du dich gürten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Tut und bezahlet Gelübde Jehova, eurem Gott; mögen alle, die rings um ihn her sind, Geschenke bringen dem Furchtbaren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Er wird abmähen den Geist der Fürsten, er ist furchtbar den Königen der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Dem Vorsänger, für Jeduthun. Von Asaph, ein Psalm. Meine Stimme ist zu Gott, und ich will schreien; meine Stimme ist zu Gott, und er wird mir Gehör schenken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Am Tage meiner Drangsal suchte ich den Herrn; meine Hand war des Nachts ausgestreckt und ließ nicht ab; meine Seele weigerte sich getröstet zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Ich gedachte Gottes, und ich stöhnte; ich sann nach, und mein Geist ermattete. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Du hieltest fest die Lider meiner Augen; ich war voll Unruhe und redete nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Ich durchdachte die Tage vor alters, die Jahre der Urzeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Ich gedachte meines Saitenspiels in der Nacht; ich sann nach in meinem Herzen, und es forschte mein Geist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Wird der Herr auf ewig verwerfen, und hinfort keine Gunst mehr erweisen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Ist zu Ende seine Güte für immer? Hat das Wort aufgehört von Geschlecht zu Geschlecht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Hat Gott vergessen gnädig zu sein? Hat er im Zorn verschlossen seine Erbarmungen? (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Da sprach ich: Das ist mein Kranksein. Der Jahre der Rechten des Höchsten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'will ich gedenken, der Taten des Jah; denn deiner Wunder von alters her will ich gedenken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'und ich will nachdenken über all dein Tun, und über deine Taten will ich sinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Gott! Dein Weg ist im Heiligtum; wer ist ein großer Gott wie Gott?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Du bist der Gott, der Wunder tut, du hast deine Stärke kundwerden lassen unter den Völkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Du hast dein Volk erlöst mit erhobenem Arm, die Söhne Jakobs und Josephs. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Dich sahen die Wasser, o Gott, dich sahen die Wasser: sie bebten; ja, es erzitterten die Tiefen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Die Wolken ergossen Wasser; das Gewölk ließ eine Stimme erschallen, und deine Pfeile fuhren hin und her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Die Stimme deines Donners war im Wirbelwind, Blitze erleuchteten den Erdkreis; es zitterte und bebte die Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Im Meere ist dein Weg, und deine Pfade in großen Wassern, und deine Fußstapfen sind nicht bekannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Du hast dein Volk geleitet wie eine Herde durch die Hand Moses und Aarons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Ein Maskil; von Asaph. Horche, mein Volk, auf mein Gesetz! Neiget euer Ohr zu den Worten meines Mundes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Ich will meinen Mund auftun zu einem Spruche, will Rätsel hervorströmen lassen aus der Vorzeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Was wir gehört und erfahren und unsere Väter uns erzählt haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'wollen wir nicht verhehlen ihren Söhnen, dem künftigen Geschlecht erzählend den Ruhm Jehovas und seine Stärke, und seine Wunderwerke, die er getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Denn er hat ein Zeugnis aufgerichtet in Jakob, und ein Gesetz gestellt in Israel, die er unseren Vätern geboten hat, um sie ihren Söhnen kundzutun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'damit sie kennte das künftige Geschlecht, die Söhne, die geboren werden sollten, und sie aufständen und sie ihren Söhnen erzählten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'und auf Gott ihr Vertrauen setzten, und die Taten Gottes nicht vergäßen, und seine Gebote bewahrten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'und nicht würden wie ihre Väter, ein widersetzliches und widerspenstiges Geschlecht, ein Geschlecht, das sein Herz nicht befestigte, und dessen Geist nicht treu war gegen Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Die Söhne Ephraims, gerüstete Bogenschützen, wandten um am Tage des Kampfes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Sie hielten nicht den Bund Gottes und weigerten sich, in seinem Gesetz zu wandeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'und sie vergaßen seine Taten und seine Wunderwerke, die er sie hatte schauen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Er tat Wunder vor ihren Vätern, im Lande Ägypten, dem Gefilde Zoans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Er spaltete das Meer und ließ sie hindurchgehen, und ließ die Wasser stehen wie einen Damm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Und er leitete sie des Tages mit der Wolke und die ganze Nacht mit dem Lichte eines Feuers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Er spaltete Felsen in der Wüste und tränkte sie reichlich wie aus Tiefen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Und er ließ Bäche hervorkommen aus dem Felsen und Wasser herablaufen gleich Flüssen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Doch sie fuhren weiter fort, wider ihn zu sündigen, indem sie gegen den Höchsten widerspenstig waren in der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'Und sie versuchten Gott in ihren Herzen, indem sie Speise forderten für ihr Gelüst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Und sie redeten wider Gott; sie sprachen: Sollte Gott in der Wüste einen Tisch zu bereiten vermögen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Siehe, den Felsen hat er geschlagen, und Wasser flossen heraus, und Bäche strömten; wird er auch Brot zu geben vermögen, oder wird er seinem Volke Fleisch verschaffen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Darum, als Jehova es hörte, ergrimmte er, und Feuer entzündete sich gegen Jakob, und auch Zorn stieg auf gegen Israel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'weil sie Gott nicht glaubten und nicht vertrauten auf seine Rettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Und doch hatte er den Wolken oben geboten und die Türen des Himmels geöffnet');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'und Manna auf sie regnen lassen, damit sie äßen, und ihnen Himmelsgetreide gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Der Mensch aß Brot der Starken, Speise sandte er ihnen bis zur Sättigung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Er führte den Ostwind herbei am Himmel, und durch seine Stärke trieb er herbei den Südwind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'und er ließ Fleisch auf sie regnen wie Staub, und geflügeltes Gevögel wie Sand der Meere,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'und ließ es fallen in ihr Lager, rings um ihre Wohnungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Und sie aßen und sättigten sich sehr, und ihr Gelüst führte er ihnen zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Noch hatten sie sich nicht abgewandt von ihrem Gelüst, noch war ihre Speise in ihrem Munde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'da stieg der Zorn Gottes wider sie auf; und er würgte unter ihren Kräftigen, und die Auserlesenen Israels streckte er nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Bei alledem sündigten sie wiederum und glaubten nicht durch seine Wunderwerke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Da ließ er in Eitelkeit hinschwinden ihre Tage, und ihre Jahre in Schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Wenn er sie tötete, dann fragten sie nach ihm, und kehrten um und suchten Gott eifrig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'und sie gedachten daran, daß Gott ihr Fels sei, und Gott, der Höchste, ihr Erlöser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Und sie heuchelten ihm mit ihrem Munde, und mit ihrer Zunge logen sie ihm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'denn ihr Herz war nicht fest gegen ihn, und sie hielten nicht treulich an seinem Bunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Er aber war barmherzig, er vergab die Ungerechtigkeit und verderbte sie nicht; und oftmals wandte er seinen Zorn ab und ließ nicht erwachen seinen ganzen Grimm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Und er gedachte daran, daß sie Fleisch seien, ein Hauch, der dahinfährt und nicht wiederkehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Wie oft waren sie widerspenstig gegen ihn in der Wüste, betrübten ihn in der Einöde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Und sie versuchten Gott wiederum und kränkten den Heiligen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Sie gedachten nicht an seine Hand, an den Tag, da er sie von dem Bedränger erlöste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'als er seine Zeichen tat in Ägypten und seine Wunder in dem Gefilde Zoans:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Er verwandelte ihre Ströme in Blut, so daß sie ihre fließenden Wasser nicht trinken konnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Er sandte Hundsfliegen unter sie, welche sie fraßen, und Frösche, die sie verderbten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Und er gab der Grille ihren Ertrag, und ihre Arbeit der Heuschrecke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Ihren Weinstock schlug er nieder mit Hagel, und ihre Maulbeerfeigenbäume mit Schloßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Und er gab ihr Vieh dem Hagel preis, und ihre Herden den Blitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Er ließ gegen sie los seines Zornes Glut, Wut und Grimm und Drangsal, eine Schar von Unglücksengeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Er bahnte seinem Zorne einen Weg, entzog nicht dem Tode ihre Seele und gab ihr Leben der Pest preis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Und er schlug alle Erstgeburt in Ägypten, die Erstlinge der Kraft in den Zelten Hams.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Und er ließ sein Volk wegziehen gleich Schafen, und leitete sie gleich einer Herde in der Wüste;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'und er führte sie sicher, so daß sie sich nicht fürchteten; und ihre Feinde bedeckte das Meer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Und er brachte sie zu der Grenze seines Heiligtums, zu diesem Berge, den seine Rechte erworben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Und er vertrieb Nationen vor ihnen, und verloste sie als Schnur des Erbteils und ließ in ihren Zelten wohnen die Stämme Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Aber sie versuchten Gott, den Höchsten, und waren widerspenstig gegen ihn, und seine Zeugnisse bewahrten sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Und sie wichen zurück und handelten treulos wie ihre Väter; sie wandten sich um gleich einem trügerischen Bogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Und sie erbitterten ihn durch ihre Höhen und reizten ihn zur Eifersucht durch ihre geschnitzten Bilder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Gott hörte es und ergrimmte, und er verachtete Israel sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Und er verließ die Wohnung zu Silo, das Zelt, welches er unter den Menschen aufgeschlagen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Und er gab in die Gefangenschaft seine Kraft, und seine Herrlichkeit in die Hand des Bedrängers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Und er gab sein Volk dem Schwerte preis, und gegen sein Erbteil ergrimmte er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Seine Jünglinge fraß das Feuer, und seine Jungfrauen wurden nicht besungen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'seine Priester fielen durch das Schwert, und seine Witwen weinten nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Da erwachte, gleich einem Schlafenden, der Herr, gleich einem Helden, der da jauchzt vom Wein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'und er schlug seine Feinde von hinten, gab ihnen ewige Schmach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Und er verwarf das Zelt Josephs, und den Stamm Ephraim erwählte er nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'sondern er erwählte den Stamm Juda, den Berg Zion, den er geliebt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Und er baute gleich Höhen sein Heiligtum, gleich der Erde, die er auf ewig gegründet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Und er erwählte David, seinen Knecht, und nahm ihn von den Hürden der Schafe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'hinter den Säugenden weg ließ er ihn kommen, um Jakob, sein Volk, zu weiden, und Israel, sein Erbteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Und er weidete sie nach der Lauterkeit seines Herzens, und mit der Geschicklichkeit seiner Hände leitete er sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Ein Psalm; von Asaph. Gott! Die Nationen sind in dein Erbteil gekommen, haben deinen heiligen Tempel verunreinigt, haben Jerusalem zu Trümmerhaufen gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Die Leichen deiner Knechte haben sie den Vögeln des Himmels zur Speise gegeben, das Fleisch deiner Frommen den wilden Tieren der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Sie haben ihr Blut wie Wasser vergossen rings um Jerusalem, und niemand war da, der begrub.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Wir sind ein Hohn geworden unseren Nachbarn, ein Spott und Schimpf denen, die uns umgeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Bis wann, Jehova? Willst du immerfort zürnen, soll wie Feuer brennen dein Eifer?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Schütte deinen Grimm aus über die Nationen, die dich nicht kennen, und auf die Königreiche, die deinen Namen nicht anrufen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Denn man hat Jakob aufgezehrt, und seine Wohnung haben sie verwüstet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Gedenke uns nicht die Ungerechtigkeiten der Vorfahren; laß eilends uns entgegenkommen deine Erbarmungen! Denn sehr gering sind wir geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Hilf uns, Gott unseres Heils, um der Herrlichkeit deines Namens willen; und errette uns, und vergib unsere Sünden um deines Namens willen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Warum sollen die Nationen sagen: Wo ist ihr Gott? Laß unter den Nationen vor unseren Augen kundwerden die Rache für das vergossene Blut deiner Knechte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Laß vor dich kommen das Seufzen des Gefangenen; nach der Größe deines Armes laß übrigbleiben die Kinder des Todes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Und gib unseren Nachbarn ihren Hohn, womit sie dich, Herr, gehöhnt haben, siebenfach in ihren Busen zurück!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'So werden wir, dein Volk, und die Herde deiner Weide, dich preisen ewiglich, dein Lob erzählen von Geschlecht zu Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Dem Vorsänger, nach Schoschannim-Eduth. Von Asaph, ein Psalm. Hirte Israels, nimm zu Ohren! Der du Joseph leitest wie eine Herde, der du thronst zwischen den Cherubim, strahle hervor!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Vor Ephraim und Benjamin und Manasse erwecke deine Macht und komm zu unserer Rettung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'O Gott! Führe uns zurück, und laß dein Angesicht leuchten, so werden wir gerettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Jehova, Gott der Heerscharen! Bis wann raucht dein Zorn wider das Gebet deines Volkes?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Du hast sie mit Tränenbrot gespeist, und sie maßweise getränkt mit Zähren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Du setztest uns zum Streit unseren Nachbarn, und unsere Feinde spotten untereinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'O Gott der Heerscharen! Führe uns zurück, und laß dein Angesicht leuchten, so werden wir gerettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Einen Weinstock zogest du aus Ägypten, vertriebest Nationen und pflanztest ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Du machtest Raum vor ihm, und er schlug Wurzeln und erfüllte das Land;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'die Berge wurden bedeckt von seinem Schatten, und seine Äste waren gleich Zedern Gottes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'er streckte seine Reben aus bis ans Meer, und bis zum Strome hin seine Schößlinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Warum hast du seine Mauern niedergerissen, so daß ihn berupfen alle, die des Weges vorübergehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Es zerwühlt ihn der Eber aus dem Walde, und das Wild des Gefildes weidet ihn ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Gott der Heerscharen! Kehre doch wieder; schaue vom Himmel und sieh, und suche heim diesen Weinstock,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'und den Setzling, den deine Rechte gepflanzt, und das Reis, das du dir gestärkt hattest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Er ist mit Feuer verbrannt, er ist abgeschnitten; vor dem Schelten deines Angesichts kommen sie um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Deine Hand sei auf dem Manne deiner Rechten, auf dem Menschensohne, den du dir gestärkt hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'So werden wir nicht von dir abweichen; belebe uns, und wir werden deinen Namen anrufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Jehova, Gott der Heerscharen! Führe uns zurück; laß dein Angesicht leuchten, so werden wir gerettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Dem Vorsänger, auf der Gittith. Von Asaph. Jubelt Gott, unserer Stärke! Jauchzet dem Gott Jakobs!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Erhebet Gesang und lasset das Tamburin ertönen, die liebliche Laute samt der Harfe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Stoßet am Neumonde in die Posaune, am Vollmonde zum Tage unseres Festes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Denn eine Satzung für Israel ist es, eine Verordnung des Gottes Jakobs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Er setzte es ein als ein Zeugnis in Joseph, als er auszog gegen das Land Ägypten, wo ich eine Sprache hörte, die ich nicht kannte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Ich entzog der Last seine Schulter, seine Hände entgingen dem Tragkorbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'In der Bedrängnis riefest du, und ich befreite dich; ich antwortete dir in des Donners Hülle; ich prüfte dich an den Wassern von Meriba. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Höre, mein Volk, und ich will wider dich zeugen. O Israel, wenn du mir gehorchtest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Es soll kein fremder Gott unter dir sein, und du sollst dich nicht bücken vor einem Gott des Auslandes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Ich bin Jehova, dein Gott, der dich aus dem Lande Ägypten heraufgeführt hat; tue deinen Mund weit auf, und ich will ihn füllen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Aber mein Volk hat nicht auf meine Stimme gehört, und Israel ist nicht willig gegen mich gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Und ich gab sie dahin der Verstocktheit ihres Herzens; sie wandelten nach ihren Ratschlägen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'O daß mein Volk auf mich gehört, daß Israel in meinen Wegen gewandelt hätte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Bald würde ich ihre Feinde gebeugt und meine Hand gewendet haben gegen ihre Bedränger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Die Hasser Jehovas würden sich ihm mit Schmeichelei unterworfen haben, und ihre Zeit würde ewig gewesen sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'und mit dem Fette des Weizens würde er es gespeist, und mit Honig aus dem Felsen würde ich dich gesättigt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Ein Psalm; von Asaph. Gott steht in der Versammlung Gottes, inmitten der Götter richtet er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Bis wann wollt ihr ungerecht richten und die Person der Gesetzlosen ansehen? (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Schaffet Recht dem Geringen und der Waise; dem Elenden und dem Armen lasset Gerechtigkeit widerfahren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Befreiet den Geringen und den Dürftigen, errettet ihn aus der Hand der Gesetzlosen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Sie wissen nichts und verstehen nichts, in Finsternis wandeln sie einher: es wanken alle Grundfesten der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Ich habe gesagt: Ihr seid Götter, und Söhne des Höchsten ihr alle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Doch wie ein Mensch werdet ihr sterben, und wie einer der Fürsten werdet ihr fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Stehe auf, o Gott, richte die Erde! Denn du wirst zum Erbteil haben alle Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Ein Lied, ein Psalm. Von Asaph. Gott, schweige nicht; verstumme nicht und sei nicht stille, o Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Denn siehe, deine Feinde toben, und deine Hasser erheben das Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Wider dein Volk machen sie listige Anschläge, und beraten sich wider deine Geborgenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Sie sprechen: Kommet und lasset uns sie vertilgen, daß sie keine Nation mehr seien, daß nicht mehr gedacht werde des Namens Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Denn sie haben sich beraten mit einmütigem Herzen, sie haben einen Bund wider dich gemacht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Die Zelte Edoms und die Ismaeliter, Moab und die Hageriter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Gebal und Ammon und Amalek, Philistäa samt den Bewohnern von Tyrus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'auch Assur hat sich ihnen angeschlossen; sie sind zu einem Arm geworden den Söhnen Lots. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Tue ihnen wie Midian, wie Sisera, wie Jabin am Bache Kison;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'die vertilgt wurden zu En-Dor, die dem Erdboden zum Dünger wurden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Mache sie, ihre Edlen, wie Oreb und wie Seeb, und wie Sebach und wie Zalmunna alle ihre Herrscher!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Weil sie gesagt haben: Lasset uns in Besitz nehmen die Wohnungen Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Mein Gott, mache sie gleich einem Staubwirbel, gleich Stoppeln vor dem Winde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Wie Feuer den Wald verbrennt, und wie eine Flamme die Berge entzündet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'also verfolge sie mit deinem Wetter, und mit deinem Sturmwinde schrecke sie hinweg!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Fülle ihr Angesicht mit Schande, damit sie deinen Namen, Jehova, suchen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Laß sie beschämt und hinweggeschreckt werden für immer, und mit Scham bedeckt werden und umkommen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'und erkennen, daß du allein, dessen Name Jehova ist, der Höchste bist über die ganze Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Dem Vorsänger, auf der Gittith. Von den Söhnen Korahs, ein Psalm. Wie lieblich sind deine Wohnungen, Jehova der Heerscharen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Es sehnt sich, ja, es schmachtet meine Seele nach den Vorhöfen Jehovas; mein Herz und mein Fleisch rufen laut nach dem lebendigen Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Selbst der Sperling hat ein Haus gefunden, und die Schwalbe ein Nest für sich, wo sie ihre Jungen hingelegt... deine Altäre, Jehova der Heerscharen, mein König und mein Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Glückselig, die da wohnen in deinem Hause! Stets werden sie dich loben. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Glückselig der Mensch, dessen Stärke in dir ist, in deren Herzen gebahnte Wege sind!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Durch das Tränental gehend, machen sie es zu einem Quellenort; ja, mit Segnungen bedeckt es der Frühregen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Sie gehen von Kraft zu Kraft; sie erscheinen vor Gott in Zion.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Jehova, Gott der Heerscharen, höre mein Gebet; nimm zu Ohren, du Gott Jakobs! (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Du, unser Schild, sieh, o Gott; und schaue an das Antlitz deines Gesalbten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Denn ein Tag in deinen Vorhöfen ist besser als sonst tausend; ich will lieber an der Schwelle stehen im Hause meines Gottes, als wohnen in den Zelten der Gesetzlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Denn Jehova, Gott, ist Sonne und Schild; Gnade und Herrlichkeit wird Jehova geben, kein Gutes vorenthalten denen, die in Lauterkeit wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Jehova der Heerscharen! Glückselig der Mensch, der auf dich vertraut!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Dem Vorsänger. Von den Söhnen Korahs, ein Psalm. Jehova, du hast Gunst erzeigt deinem Lande, hast die Gefangenschaft Jakobs gewendet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'du hast vergeben die Ungerechtigkeit deines Volkes, all ihre Sünde hast du zugedeckt. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Du hast zurückgezogen all deinen Grimm, hast dich abgewendet von der Glut deines Zornes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Führe uns zurück, Gott unseres Heils, und mache deinem Unwillen gegen uns ein Ende!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Willst du ewiglich wider uns zürnen? Willst du deinen Zorn währen lassen von Geschlecht zu Geschlecht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Willst du uns nicht wieder beleben, daß dein Volk sich in dir erfreue?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Laß uns, Jehova, deine Güte sehen, und dein Heil gewähre uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Hören will ich, was Gott, Jehova, reden wird; denn Frieden wird er reden zu seinem Volke und zu seinen Frommen, nur daß sie nicht zur Torheit zurückkehren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Fürwahr, nahe ist sein Heil denen, die ihn fürchten, damit die Herrlichkeit wohne in unserem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Güte und Wahrheit sind sich begegnet, Gerechtigkeit und Friede haben sich geküßt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Wahrheit wird sprossen aus der Erde, und Gerechtigkeit herniederschauen vom Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Auch wird Jehova das Gute geben, und unser Land wird darreichen seinen Ertrag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Die Gerechtigkeit wird vor ihm einhergehen und ihre Tritte zu seinem Wege machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Ein Gebet. Von David. Neige, Jehova, dein Ohr, erhöre mich! Denn ich bin elend und arm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Bewahre meine Seele, denn ich bin fromm; rette du, mein Gott, deinen Knecht, der auf dich vertraut!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Sei mir gnädig, Herr! Denn zu dir rufe ich den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Erfreue die Seele deines Knechtes! Denn zu dir, Herr, erhebe ich meine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Denn du, Herr, bist gut und zum Vergeben bereit, und groß an Güte gegen alle, die dich anrufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Nimm zu Ohren, Jehova, mein Gebet, und horche auf die Stimme meines Flehens!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Am Tage meiner Bedrängnis werde ich dich anrufen, denn du wirst mich erhören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Keiner ist wie du, Herr, unter den Göttern, und nichts gleich deinen Werken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Alle Nationen, die du gemacht hast, werden kommen und vor dir anbeten, Herr, und deinen Namen verherrlichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Denn groß bist du und Wunder tuend, du bist Gott, du allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Lehre mich, Jehova, deinen Weg: ich werde wandeln in deiner Wahrheit; einige mein Herz zur Furcht deines Namens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Ich will dich priesen, Herr, mein Gott, mit meinem ganzen Herzen, und deinen Namen verherrlichen ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Denn deine Güte ist groß gegen mich, und du hast meine Seele errettet aus dem untersten Scheol.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Gott! Übermütige sind wider mich aufgestanden, und der Gewalttätigen Rotte trachtet nach meinem Leben; und sie haben dich nicht vor sich gestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Du aber, Herr, bist ein Gott, barmherzig und gnädig, langsam zum Zorn und groß an Güte und Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Wende dich zu mir und sei mir gnädig! Gewähre deinem Knechte deine Kraft und rette den Sohn deiner Magd!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Erweise mir ein Zeichen zum Guten, daß meine Hasser es sehen und beschämt werden, weil du, Jehova, mir geholfen und mich getröstet hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Von den Söhnen Korahs, ein Psalm, ein Lied. Seine Gründung ist auf den Bergen der Heiligkeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Jehova liebt die Tore Zions mehr als alle Wohnungen Jakobs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Herrliches ist von dir geredet, du Stadt Gottes. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Erwähnen will ich Rahabs und Babels bei denen, die mich kennen; siehe, Philistäa und Tyrus samt Äthiopien: dieser ist daselbst geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Und von Zion wird gesagt werden: Der und der ist darin geboren; und der Höchste, er wird es befestigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Jehova wird schreiben beim Verzeichnen der Völker: Dieser ist daselbst geboren. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Und singend und den Reigen tanzend werden sie sagen: Alle meine Quellen sind in dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Ein Lied, ein Psalm von den Söhnen Korahs; dem Vorsänger, nach Machalath Leannoth; ein Maskil, von Heman, dem Esrachiter. Jehova, Gott meiner Rettung! Des Tages habe ich geschrieen und des Nachts vor dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Es komme vor dich mein Gebet! Neige dein Ohr zu meinem Schreien!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Denn satt ist meine Seele von Leiden, und mein Leben ist nahe am Scheol.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Ich bin gerechnet zu denen, die in die Grube hinabfahren; ich bin wie ein Mann, der keine Kraft hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'unter den Toten hingestreckt, gleich Erschlagenen, die im Grabe liegen, derer du nicht mehr gedenkst; denn sie sind von deiner Hand abgeschnitten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Du hast mich in die tiefste Grube gelegt, in Finsternisse, in Tiefen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Auf mir liegt schwer dein Grimm, und mit allen deinen Wellen hast du mich niedergedrückt. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Meine Bekannten hast du von mir entfernt, hast mich ihnen zum Greuel gesetzt; ich bin eingeschlossen und kann nicht herauskommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Mein Auge verschmachtet vor Elend; zu dir, Jehova, habe ich jeden Tag gerufen, zu dir habe ich meine Hände ausgebreitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Wirst du an den Toten Wunder tun? Oder werden die Schatten aufstehen, dich preisen? (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Wird deine Güte erzählt werden im Grabe, im Abgrund deine Treue?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Werden in der Finsternis bekannt werden deine Wunder, und deine Gerechtigkeit in dem Lande der Vergessenheit?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Ich aber, Jehova, schreie zu dir, und am Morgen kommt mein Gebet dir zuvor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Warum, Jehova, verwirfst du meine Seele, verbirgst dein Angesicht vor mir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Elend bin ich und verscheidend von Jugend auf; ich trage deine Schrecken, bin verwirrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Deine Zorngluten sind über mich hingegangen, deine Schrecknisse haben mich vernichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Sie haben mich umringt wie Wasser den ganzen Tag, sie haben mich umgeben allesamt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Freund und Genossen hast du von mir entfernt; meine Bekannten sind Finsternis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Ein Maskil; von Ethan, dem Esrachiter. Die Gütigkeiten Jehovas will ich besingen ewiglich, von Geschlecht zu Geschlecht mit meinem Munde kundmachen deine Treue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Denn ich sagte: Auf ewig wird die Güte gebaut werden; die Himmel, in ihnen wirst du feststellen deine Treue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Einen Bund habe ich mit meinem Auserwählten gemacht, habe David, meinem Knechte, geschworen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, '\"Bis in Ewigkeit will ich feststellen deinen Samen, und auf alle Geschlechter hin bauen deinen Thron.\" (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Und die Himmel werden deine Wunder preisen, Jehova, und deine Treue in der Versammlung der Heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Denn wer in den Wolken ist mit Jehova zu vergleichen? Wer ist Jehova gleich unter den Söhnen der Starken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Er ist ein Gott, gar erschrecklich in der Versammlung der Heiligen, und furchtbar über alle, die rings um ihn her sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Jehova, Gott der Heerscharen, wer ist mächtig wie du, o Jah? Und deine Treue ist rings um dich her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Du beherrschest des Meeres Toben; erheben sich seine Wogen, du stillest sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Du hast Rahab zertreten wie einen Erschlagenen; mit deinem starken Arme hast du deine Feinde zerstreut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Dein sind die Himmel und dein die Erde; der Erdkreis und seine Fülle, du hast sie gegründet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Norden und Süden, du hast sie erschaffen; Tabor und Hermon jubeln in deinem Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Du hast einen gewaltigen Arm, stark ist deine Hand, hoch deine Rechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Gerechtigkeit und Gericht sind deines Thrones Grundfeste; Güte und Wahrheit gehen vor deinem Angesicht her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Glückselig das Volk, das den Jubelschall kennt! Jehova, im Lichte deines Angesichts wandeln sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'In deinem Namen frohlocken sie den ganzen Tag, und durch deine Gerechtigkeit werden sie erhöht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Denn die Zierde ihrer Stärke bist du; und durch deine Gunst wird erhöht werden unser Horn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Denn Jehova ist unser Schild, und der Heilige Israels unser König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Dazumal redetest du im Gesicht von deinem Frommen und sagtest: Hilfe habe ich auf einen Mächtigen gelegt, ich habe einen Auserwählten erhöht aus dem Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Ich habe David gefunden, meinen Knecht, mit meinem heiligen Öle habe ich ihn gesalbt-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'mit welchem fest bleiben soll meine Hand, und mein Arm soll ihn stärken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Nicht soll ihn drängen der Feind, und der Sohn der Ungerechtigkeit ihn nicht bedrücken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'und ich will seine Bedränger vor ihm zerschmettern, und seine Hasser will ich schlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Und meine Treue und meine Güte werden mit ihm sein, und durch meinen Namen wird sein Horn erhöht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Und ich will seine Hand an das Meer legen, und seine Rechte an die Ströme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Er wird mir zurufen: Mein Vater bist du, mein Gott, und der Fels meiner Rettung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'So will auch ich ihn zum Erstgeborenen machen, zum Höchsten der Könige der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Ewig will ich ihm meine Güte bewahren, und mein Bund soll ihm fest bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Und ich will seinen Samen einsetzen für immer, und seinen Thron wie die Tage der Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Wenn seine Söhne mein Gesetz verlassen und nicht wandeln in meinen Rechten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'wenn sie meine Satzungen entweihen und meine Gebote nicht halten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'so werde ich mit der Rute heimsuchen ihre Übertretung, und mit Schlägen ihre Ungerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Aber meine Güte werde ich nicht von ihm weichen lassen, und nicht verleugnen meine Treue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Nicht werde ich entweihen meinen Bund, und nicht ändern, was hervorgegangen ist aus meinen Lippen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Einmal habe ich geschworen bei meiner Heiligkeit: Wenn ich dem David lüge!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Sein Same wird ewig sein, und sein Thron wie die Sonne vor mir;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'ewiglich wird er feststehen wie der Mond; und der Zeuge in den Wolken ist treu. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Du aber hast verworfen und verstoßen, bist sehr zornig gewesen gegen deinen Gesalbten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Du hast verworfen den Bund deines Knechtes, hast zu Boden entweiht seine Krone;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Du hast niedergerissen alle seine Mauern, hast seine Festen in Trümmer gelegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Es haben ihn beraubt alle, die des Weges vorübergehen; er ist zum Hohn geworden seinen Nachbarn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Du hast erhöht die Rechte seiner Bedränger, hast erfreut alle seine Feinde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'auch hast du zurückgewandt die Schärfe seines Schwertes, und hast ihn nicht bestehen lassen im Kampfe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Du hast aufhören lassen seinen Glanz und zur Erde gestürzt seinen Thron;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Du hast verkürzt die Tage seiner Jugend, mit Schmach hast du ihn bedeckt. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Bis wann, Jehova, willst du dich immerfort verbergen, soll wie Feuer brennen dein Grimm?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Gedenke, was meine Lebensdauer ist, zu welcher Nichtigkeit du alle Menschenkinder erschaffen hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Welcher Mann lebt und wird den Tod nicht sehen, wird seine Seele befreien von der Gewalt des Scheols? (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Wo sind, o Herr, deine früheren Gütigkeiten, die du David zugeschworen hast in deiner Treue?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Gedenke, Herr, des Hohnes deiner Knechte, daß ich in meinem Busen trage den Hohn all der vielen Völker,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'womit deine Feinde gehöhnt haben, Jehova, womit sie gehöhnt haben die Fußstapfen deines Gesalbten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Gepriesen sei Jehova ewiglich! Amen, ja, Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Ein Gebet von Mose, dem Manne Gottes. Herr, du bist unsere Wohnung gewesen von Geschlecht zu Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Ehe geboren waren die Berge, und du die Erde und den Erdkreis erschaffen hattest ja, von Ewigkeit zu Ewigkeit bist du Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Du lässest zum Staube zurückkehren den Menschen, und sprichst: Kehret zurück, ihr Menschenkinder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Denn tausend Jahre sind in deinen Augen wie der gestrige Tag, wenn er vergangen ist, und wie eine Wache in der Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Du schwemmst sie hinweg, sie sind wie ein Schlaf, am Morgen wie Gras, das aufsproßt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'am Morgen blüht es und sproßt auf; am Abend wird es abgemäht und verdorrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Denn wir vergehen durch deinen Zorn, und durch deinen Grimm werden wir hinweggeschreckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Du hast unsere Ungerechtigkeiten vor dich gestellt, unser verborgenes Tun vor das Licht deines Angesichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Denn alle unsere Tage schwinden durch deinen Grimm, wir bringen unsere Jahre zu wie einen Gedanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Die Tage unserer Jahre, ihrer sind siebzig Jahre, und, wenn in Kraft, achtzig Jahre, und ihr Stolz ist Mühsal und Nichtigkeit, denn schnell eilt es vorüber, und wir fliegen dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Wer erkennt die Stärke deines Zornes, und, deiner Furcht gemäß, deinen Grimm?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'So lehre uns denn zählen unsere Tage, auf daß wir ein weises Herz erlangen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Kehre wieder, Jehova! Bis wann? Und laß dich\'s gereuen über deine Knechte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Sättige uns früh mit deiner Güte, so werden wir jubeln und uns freuen in allen unseren Tagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Erfreue uns nach den Tagen, da du uns gebeugt hast, nach den Jahren, da wir Übles gesehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Laß deinen Knechten erscheinen dein Tun, und deine Majestät ihren Söhnen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Und die Huld des Herrn, unseres Gottes, sei über uns! Und befestige über uns das Werk unserer Hände; ja, das Werk unserer Hände, befestige es!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Wer im Schirm des Höchsten sitzt, wird bleiben im Schatten des Allmächtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Ich sage von Jehova: Meine Zuflucht und meine Burg; mein Gott, auf ihn will ich vertrauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Denn er wird dich erretten von der Schlinge des Vogelstellers, von der verderblichen Pest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Mit seinen Fittichen wird er dich decken, und du wirst Zuflucht finden unter seinen Flügeln; Schild und Tartsche ist seine Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Du wirst dich nicht fürchten vor dem Schrecken der Nacht, vor dem Pfeile, der bei Tage fliegt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'vor der Pest, die im Finstern wandelt, vor der Seuche, die am Mittag verwüstet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Tausend werden fallen an deiner Seite, und zehntausend an deiner Rechten, dich wird es nicht erreichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Nur schauen wirst du es mit deinen Augen, und wirst sehen die Vergeltung der Gesetzlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Weil du Jehova, meine Zuflucht, den Höchsten, gesetzt hast zu deiner Wohnung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'so wird dir kein Unglück widerfahren, und keine Plage deinem Zelte nahen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'denn er wird seinen Engeln über dir befehlen, dich zu bewahren auf allen deinen Wegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Auf den Händen werden sie dich tragen, damit du deinen Fuß nicht an einen Stein stoßest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Auf Löwen und Ottern wirst du treten, junge Löwen und Schlangen wirst du niedertreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Weil er Wonne an mir hat, will ich ihn erretten; ich will ihn in Sicherheit setzen, weil er meinen Namen kennt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Er wird mich anrufen, und ich werde ihm antworten, ich werde bei ihm sein in der Bedrängnis; ich werde ihn befreien und ihn verherrlichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Ich werde ihn sättigen mit Länge des Lebens und ihn schauen lassen meine Rettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Ein Psalm, ein Lied. Für den Tag des Sabbaths. Es ist gut, Jehova zu preisen, und Psalmen zu singen deinem Namen, o Höchster!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Am Morgen zu verkünden deine Güte, und deine Treue in den Nächten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'zum Zehnsait und zur Harfe, zum Saitenspiel mit der Laute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Denn du hast mich erfreut, Jehova, durch dein Tun; über die Werke deiner Hände will ich jubeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Wie groß sind deine Werke, Jehova! Sehr tief sind deine Gedanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Ein unvernünftiger Mensch erkennt es nicht, und ein Tor versteht solches nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Wenn die Gesetzlosen sprossen wie Gras, und alle, die Frevel tun, blühen, so geschieht es, damit sie vertilgt werden für immer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Du aber bist erhaben auf ewig, Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Denn siehe, deine Feinde, Jehova, denn siehe, deine Feinde werden umkommen; es werden zerstreut werden alle, die Frevel tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Aber du wirst mein Horn erhöhen gleich dem eines Wildochsen; mit frischem Öle werde ich übergossen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Und mein Auge wird seine Lust sehen an meinen Feinden, meine Ohren werden ihre Lust hören an den Übeltätern, die wider mich aufstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Der Gerechte wird sprossen wie der Palmbaum, wie eine Zeder auf dem Libanon wird er emporwachsen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Die gepflanzt sind in dem Hause Jehovas, werden blühen in den Vorhöfen unseres Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Noch im Greisenalter treiben sie, sind saftvoll und grün,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'um zu verkünden, daß Jehova gerecht ist. Er ist mein Fels, und kein Unrecht ist in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Jehova regiert, er hat sich bekleidet mit Hoheit; Jehova hat sich bekleidet, er hat sich umgürtet mit Stärke; auch steht der Erdkreis fest, er wird nicht wanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Dein Thron steht fest von alters her, von Ewigkeit her bist du.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Ströme erhoben, Jehova, Ströme erhoben ihre Stimme, Ströme erhoben ihre Brandung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Jehova in der Höhe ist gewaltiger als die Stimmen großer Wasser, als die gewaltigen Wogen des Meeres.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Deine Zeugnisse sind sehr zuverlässig. Deinem Hause geziemt Heiligkeit, Jehova, auf immerdar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Gott der Rache, Jehova, Gott der Rache, strahle hervor!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Erhebe dich, Richter der Erde, vergilt den Hoffärtigen ihr Tun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Bis wann werden die Gesetzlosen, Jehova, bis wann werden die Gesetzlosen frohlocken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'werden übersprudeln, Freches reden, sich rühmen alle, die Frevel tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Dein Volk, Jehova, zertreten und dein Erbteil bedrücken sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Sie töten die Witwe und den Fremdling, und sie ermorden die Waisen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'und sagen: Jah sieht es nicht, und der Gott Jakobs merkt es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Habet Einsicht, ihr Unvernünftigen unter dem Volke! Und ihr Toren, wann werdet ihr verständig werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Der das Ohr gepflanzt hat, sollte er nicht hören? Der das Auge gebildet, sollte er nicht sehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Der die Nationen zurechtweist, sollte er nicht strafen, er, der Erkenntnis lehrt den Menschen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Jehova kennt die Gedanken des Menschen, daß sie Eitelkeit sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Glückselig der Mann, den du züchtigst, Jehova, und den du belehrst aus deinem Gesetz,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'um ihm Ruhe zu geben vor den bösen Tagen, bis dem Gesetzlosen die Grube gegraben wird!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Denn Jehova wird sein Volk nicht verstoßen, und nicht verlassen sein Erbteil;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'denn zur Gerechtigkeit wird zurückkehren das Gericht, und alle von Herzen Aufrichtigen werden ihm folgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Wer wird für mich aufstehen wider die Übeltäter? Wer wird für mich auftreten wider die, welche Frevel tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Wäre nicht Jehova mir eine Hilfe gewesen, wenig fehlte, so hätte im Schweigen gewohnt meine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Wenn ich sagte: Mein Fuß wankt, so unterstützte mich deine Güte, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Bei der Menge meiner Gedanken in meinem Innern erfüllten deine Tröstungen meine Seele mit Wonne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Sollte mit dir vereint sein der Thron des Verderbens, der aus Frevel eine Satzung macht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Sie dringen ein auf die Seele des Gerechten, und unschuldiges Blut verurteilen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Doch Jehova ist meine hohe Feste, und mein Gott der Fels meiner Zuflucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Und er läßt ihre Ungerechtigkeit auf sie zurückkehren, und durch ihre Bosheit wird er sie vertilgen; vertilgen wird sie Jehova, unser Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Kommet, lasset uns Jehova zujubeln, lasset uns zujauchzen dem Felsen unseres Heils!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Lasset uns ihm entgegengehen mit Lob, lasset uns mit Psalmen ihm zujauchzen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Denn ein großer Gott ist Jehova, und ein großer König über alle Götter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'in dessen Hand die Tiefen der Erde, und dessen die Höhen der Berge sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'dessen das Meer ist, er hat es ja gemacht; und das Trockene, seine Hände haben es gebildet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Kommet, lasset uns anbeten und uns niederbeugen, lasset uns niederknien vor Jehova, der uns gemacht hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Denn er ist unser Gott, und wir sind das Volk seiner Weide und die Herde seiner Hand. Heute, wenn ihr seine Stimme höret,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'verhärtet euer Herz nicht, wie zu Meriba, wie am Tage von Massa in der Wüste;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'als eure Väter mich versuchten, mich prüften, und sie sahen doch mein Werk!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Vierzig Jahre hatte ich Ekel an dem Geschlecht, und ich sprach: Ein Volk irrenden Herzens sind sie. Aber sie haben meine Wege nicht erkannt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'so daß ich schwur in meinem Zorn: Wenn sie in meine Ruhe eingehen werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Singet Jehova ein neues Lied, singet Jehova, ganze Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Singet Jehova, preiset seinen Namen, verkündet von Tag zu Tag seine Rettung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Erzählet unter den Nationen seine Herrlichkeit, unter allen Völkern seine Wundertaten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Denn groß ist Jehova und sehr zu loben, furchtbar ist er über alle Götter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Denn alle Götter der Völker sind Nichtigkeiten, aber Jehova hat die Himmel gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Majestät und Pracht sind vor seinem Angesicht, Stärke und Herrlichkeit in seinem Heiligtum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Gebet Jehova, ihr Völkerstämme, gebet Jehova Herrlichkeit und Stärke!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Gebet Jehova die Herrlichkeit seines Namens; bringet eine Opfergabe und kommet in seine Vorhöfe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Betet Jehova an in heiliger Pracht! Erzittert vor ihm, ganze Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Saget unter den Nationen: Jehova regiert! Auch steht der Erdkreis fest, er wird nicht wanken. Er wird die Völker richten in Geradheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Es freue sich der Himmel, und es frohlocke die Erde! Es brause das Meer und seine Fülle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Es frohlocke das Gefilde und alles, was darauf ist! Dann werden jubeln alle Bäume des Waldes-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'vor Jehova; denn er kommt, denn er kommt, die Erde zu richten: er wird den Erdkreis richten in Gerechtigkeit, und die Völker in seiner Treue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Jehova regiert. Es frohlocke die Erde, mögen sich freuen die vielen Inseln!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Gewölk und Dunkel sind um ihn her; Gerechtigkeit und Gericht sind seines Thrones Grundfeste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Feuer geht vor ihm her und entzündet seine Feinde ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Seine Blitze erleuchteten den Erdkreis: die Erde sah es und bebte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Die Berge zerschmolzen wie Wachs, vor Jehova, vor dem Herrn der ganzen Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Die Himmel verkündeten seine Gerechtigkeit, und alle Völker sahen seine Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Mögen beschämt werden alle Diener der Bilder, die der Nichtigkeiten sich rühmen; fallet vor ihm nieder, ihr Götter alle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Zion hörte es und freute sich, und es frohlockten die Töchter Judas, wegen deiner Gerichte, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Denn du, Jehova, bist der Höchste über die ganze Erde; du bist sehr erhaben über alle Götter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Die ihr Jehova liebet, hasset das Böse! Er bewahrt die Seelen seiner Frommen; aus der Hand der Gesetzlosen errettet er sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Licht ist gesät dem Gerechten, und Freude den von Herzen Aufrichtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Freuet euch, ihr Gerechten, in Jehova, und preiset sein heiliges Gedächtnis!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Ein Psalm. Singet Jehova ein neues Lied! Denn er hat Wunder getan; Rettung hat ihm verschafft seine Rechte und sein heiliger Arm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Jehova hat kundgetan seine Rettung, vor den Augen der Nationen geoffenbart seine Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Er hat seiner Güte und seiner Treue gedacht dem Hause Israel; alle Enden der Erde haben die Rettung unseres Gottes gesehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Jauchzet Jehova, ganze Erde! Brechet in Jubel aus und singet Psalmen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Singet Psalmen Jehova mit der Laute mit der Laute und der Stimme des Gesanges!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Mit Trompeten und dem Schall der Posaune jauchzet vor dem König Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Es brause das Meer und seine Fülle, der Erdkreis und die darauf wohnen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Mögen die Ströme in die Hände klatschen, mögen jubeln die Berge allzumal-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'vor Jehova! Denn er kommt, die Erde zu richten: Er wird den Erdkreis richten in Gerechtigkeit und die Völker in Geradheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Jehova regiert: es zittern die Völker; er thront zwischen den Cherubim: es wankt die Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Groß ist Jehova in Zion, und hoch ist er über alle Völker.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Preisen sollen sie deinen Namen, den großen und furchtbaren, heilig ist er! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Und die Stärke des Königs, der das Recht liebt! Du stellst fest die Geradheit, du übst Recht und Gerechtigkeit in Jakob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Erhebet Jehova, unseren Gott, und fallet nieder vor dem Schemel seiner Füße! Heilig ist er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mose und Aaron unter seinen Priestern, und Samuel unter denen, die seinen Namen anrufen, riefen zu Jehova, und er antwortete ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'In der Wolkensäule redete er zu ihnen; sie bewahrten seine Zeugnisse und die Satzung, die er ihnen gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Jehova, unser Gott, du hast ihnen geantwortet! Ein vergebender Gott warst du ihnen, und ein Rächer ihrer Taten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Erhebet Jehova, unseren Gott, und fallet nieder an seinem heiligen Berge! Denn heilig ist Jehova, unser Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Ein Lobpsalm. Jauchzet Jehova, ganze Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Dienet Jehova mit Freuden; kommet vor sein Angesicht mit Jubel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Erkennet, daß Jehova Gott ist! Er hat uns gemacht, und nicht wir selbst, sein Volk und die Herde seiner Weide.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Kommet in seine Tore mit Lob, in seine Vorhöfe mit Lobgesang! Lobet ihn, preiset seinen Namen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Denn gut ist Jehova; seine Güte währt ewiglich, und seine Treue von Geschlecht zu Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Von David; ein Psalm. Von Güte und Recht will ich singen; dir, Jehova, will ich Psalmen singen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Ich will weislich handeln auf vollkommenem Wege; wann wirst du zu mir kommen? im Innern meines Hauses will ich wandeln in Lauterkeit meines Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Ich will kein Belialsstück vor meine Augen stellen; das Tun der Abtrünnigen hasse ich: es soll mir nicht ankleben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Ein verkehrtes Herz soll von mir weichen, den Bösen will ich nicht kennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Wer seinen Nächsten heimlich verleumdet, den will ich vertilgen; wer stolzer Augen und hochmütigen Herzens ist, den will ich nicht dulden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Meine Augen werden gerichtet sein auf die Treuen im Lande, damit sie bei mir wohnen; wer auf vollkommenem Wege wandelt, der soll mir dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Nicht soll wohnen im Innern meines Hauses, wer Trug übt; wer Lügen redet, soll nicht bestehen vor meinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Jeden Morgen will ich vertilgen alle Gesetzlosen des Landes, um aus der Stadt Jehovas auszurotten alle, die Frevel tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Gebet eines Elenden, wenn er verschmachtet und seine Klage vor Jehova ausschüttet. Jehova, höre mein Gebet, und laß zu dir kommen mein Schreien!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Verbirg dein Angesicht nicht vor mir am Tage meiner Bedrängnis; neige zu mir dein Ohr; an dem Tage, da ich rufe, erhöre mich eilends!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Denn wie Rauch entschwinden meine Tage, und meine Gebeine glühen wie ein Brand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Wie Kraut ist versengt und verdorrt mein Herz, daß ich vergessen habe, mein Brot zu essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Ob der Stimme meines Seufzens klebt mein Gebein an meinem Fleische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Ich gleiche dem Pelikan der Wüste, bin wie die Eule der Einöden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Ich wache, und bin wie ein einsamer Vogel auf dem Dache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Den ganzen Tag höhnen mich meine Feinde; die wider mich rasen, schwören bei mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Denn Asche esse ich wie Brot, und meinen Trank vermische ich mit Tränen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'vor deinem Zorn und deinem Grimm; denn du hast mich emporgehoben und hast mich hingeworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Meine Tage sind wie ein gestreckter Schatten, und ich verdorre wie Kraut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Du aber, Jehova, bleibst auf ewig, und dein Gedächtnis ist von Geschlecht zu Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Du wirst aufstehen, wirst dich Zions erbarmen; denn es ist Zeit, es zu begnadigen, denn gekommen ist die bestimmte Zeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'denn deine Knechte haben Gefallen an seinen Steinen und haben Mitleid mit seinem Schutt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Und die Nationen werden den Namen Jehovas fürchten, und alle Könige der Erde deine Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Denn Jehova wird Zion aufbauen, wird erscheinen in seiner Herrlichkeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Er wird sich wenden zum Gebete des Entblößten, und ihr Gebet wird er nicht verachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Das wird aufgeschrieben werden für das künftige Geschlecht; und ein Volk, das erschaffen werden soll, wird Jehova loben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Denn er hat herniedergeblickt von der Höhe seines Heiligtums, Jehova hat herabgeschaut vom Himmel auf die Erde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'um zu hören das Seufzen des Gefangenen, um zu lösen die Kinder des Todes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'damit man den Namen Jehovas verkündige in Zion, und in Jerusalem sein Lob,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'wenn die Völker sich versammeln werden allzumal, und die Königreiche, um Jehova zu dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Er hat meine Kraft gebeugt auf dem Wege, hat verkürzt meine Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Ich sprach: Mein Gott, nimm mich nicht hinweg in der Hälfte meiner Tage! Von Geschlecht zu Geschlecht sind deine Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Du hast vormals die Erde gegründet, und die Himmel sind deiner Hände Werk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Sie werden untergehen, du aber bleibst; und sie alle werden veralten wie ein Kleid; wie ein Gewand wirst du sie verwandeln, und sie werden verwandelt werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Du aber bist derselbe, und deine Jahre enden nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Die Söhne deiner Knechte werden wohnen, und ihr Same wird vor dir feststehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Von David. Preise Jehova, meine Seele, und all mein Inneres seinen heiligen Namen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Preise Jehova, meine Seele, und vergiß nicht alle seine Wohltaten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Der da vergibt alle deine Ungerechtigkeit, der da heilt alle deine Krankheiten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'der dein Leben erlöst von der Grube, der dich krönt mit Güte und Erbarmungen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'der mit Gutem sättigt dein Alter; deine Jugend erneuert sich wie die des Adlers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Jehova übt Gerechtigkeit und schafft Recht allen, die bedrückt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Er tat seine Wege kund dem Mose, den Kindern Israel seine Taten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Barmherzig und gnädig ist Jehova, langsam zum Zorn und groß an Güte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Er wird nicht immerdar rechten und nicht ewiglich nachtragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Er hat uns nicht getan nach unseren Sünden, und nach unseren Ungerechtigkeiten uns nicht vergolten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Denn so hoch die Himmel über der Erde sind, ist gewaltig seine Güte über die, welche ihn fürchten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'so weit der Osten ist vom Westen, hat er von uns entfernt unsere Übertretungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Wie ein Vater sich über die Kinder erbarmt, so erbarmt sich Jehova über die, welche ihn fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Denn er kennt unser Gebilde, ist eingedenk, daß wir Staub sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Der Mensch, wie Gras sind seine Tage; wie die Blume des Feldes, also blüht er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Denn ein Wind fährt darüber, und sie ist nicht mehr, und ihre Stätte kennt sie nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Die Güte Jehovas aber ist von Ewigkeit zu Ewigkeit über die, welche ihn fürchten, und seine Gerechtigkeit auf Kindeskinder hin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'für die, welche seinen Bund halten, und seiner Vorschriften gedenken, um sie zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Jehova hat in den Himmeln festgestellt seinen Thron, und sein Reich herrscht über alles.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Preiset Jehova, ihr seine Engel, ihr Gewaltigen an Kraft, Täter seines Wortes, gehorsam der Stimme seines Wortes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Preiset Jehova, alle seine Heerscharen, ihr seine Diener, Täter seines Wohlgefallens!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Preiset Jehova, alle seine Werke, an allen Orten seiner Herrschaft! Preise Jehova, meine Seele!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Preise Jehova, meine Seele! Jehova, mein Gott, du bist sehr groß, mit Majestät und Pracht bist du bekleidet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Du, der in Licht sich hüllt wie in ein Gewand, der die Himmel ausspannt gleich einer Zeltdecke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'der seine Obergemächer bälkt in den Wassern, der Wolken macht zu seinem Gefährt, der da einherzieht auf den Fittichen des Windes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'der seine Engel zu Winden macht, seine Diener zu flammendem Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Er hat die Erde gegründet auf ihre Grundfesten; sie wird nicht wanken immer und ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Mit der Tiefe hattest du sie bedeckt wie mit einem Gewande; die Wasser standen über den Bergen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Vor deinem Schelten flohen sie, vor der Stimme deines Donners eilten sie hinweg-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'die Berge erhoben sich, es senkten sich die Täler an den Ort, den du ihnen festgesetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Du hast ihnen eine Grenze gesetzt, die sie nicht überschreiten werden; sie werden nicht zurückkehren, die Erde zu bedecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Du, der Quellen entsendet in die Täler; zwischen den Bergen fließen sie dahin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'sie tränken alle Tiere des Feldes, die Wildesel stillen ihren Durst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'An denselben wohnen die Vögel des Himmels, zwischen den Zweigen hervor lassen sie ihre Stimme erschallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Du, der die Berge tränkt aus seinen Obergemächern; von der Frucht deiner Werke wird die Erde gesättigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Der Gras hervorsprossen läßt für das Vieh, und Kraut zum Dienste der Menschen: um Brot hervorzubringen aus der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'und damit Wein des Menschen Herz erfreue; um das Angesicht glänzen zu machen von Öl, und damit Brot des Menschen Herz stärke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Es werden gesättigt die Bäume Jehovas, die Zedern des Libanon, die er gepflanzt hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'woselbst die Vögel nisten; der Storch, Zypressen sind sein Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Die hohen Berge sind für die Steinböcke, die Felsen eine Zuflucht für die Klippendächse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Er hat den Mond gemacht für die bestimmten Zeiten; die Sonne weiß ihren Untergang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Du machst Finsternis, und es wird Nacht; in ihr regen sich alle Tiere des Waldes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'die jungen Löwen brüllen nach Raub und fordern von Gott ihre Speise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Die Sonne geht auf: sie ziehen sich zurück und lagern sich in ihre Höhlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Der Mensch geht aus an sein Werk und an seine Arbeit, bis zum Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Wie viele sind deiner Werke, Jehova! Du hast sie alle mit Weisheit gemacht, voll ist die Erde deiner Reichtümer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Dieses Meer, groß und ausgedehnt nach allen Seiten hin: daselbst wimmelt\'s, ohne Zahl, von Tieren klein und groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Daselbst ziehen Schiffe einher, der Leviathan, den du gebildet hast, um sich darin zu tummeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Sie alle warten auf dich, daß du ihnen ihre Speise gebest zu seiner Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Du gibst ihnen: sie sammeln ein; du tust deine Hand auf: sie werden gesättigt mit Gutem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Du verbirgst dein Angesicht: sie erschrecken; du nimmst ihren Odem hinweg: sie hauchen aus und kehren zurück zu ihrem Staube.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Du sendest deinen Odem aus: sie werden erschaffen, und du erneuerst die Fläche des Erdbodens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Jehovas Herrlichkeit wird ewig sein, Jehova wird sich freuen seiner Werke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'der die Erde anschaut, und sie bebt; er rührt die Berge an, und sie rauchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Singen will ich Jehova mein Leben lang, will meinem Gott Psalmen singen, solange ich bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Möge ihm angenehm sein mein Sinnen! Ich, ich werde mich in Jehova erfreuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Die Sünder werden schwinden von der Erde, und die Gesetzlosen nicht mehr sein. Preise Jehova, meine Seele! Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Preiset Jehova, rufet an seinen Namen, machet kund unter den Völkern seine Taten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Singet ihm, singet ihm Psalmen; sinnet über alle seine Wunderwerke!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Rühmet euch seines heiligen Namens! Es freue sich das Herz derer, die Jehova suchen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Trachtet nach Jehova und seiner Stärke, suchet sein Angesicht beständig!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Gedenket seiner Wunderwerke, die er getan hat, seiner Wunderzeichen und der Gerichte seines Mundes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Du Same Abrahams, seines Knechtes, ihr Söhne Jakobs, seine Auserwählten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Er, Jehova, ist unser Gott; seine Gerichte sind auf der ganzen Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Er gedenkt ewiglich seines Bundes, des Wortes, das er geboten hat auf tausend Geschlechter hin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Den er gemacht hat mit Abraham, und seines Eides, den er Isaak geschworen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Und er stellte ihn Jakob zur Satzung, Israel zum ewigen Bunde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'indem er sprach: Dir will ich das Land Kanaan geben als Schnur eures Erbteils;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'als sie ein zählbares Häuflein waren, gar wenige und Fremdlinge darin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'und als sie wanderten von Nation zu Nation, von einem Reiche zu einem anderen Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Er ließ keinem Menschen zu, sie zu bedrücken, und ihretwegen strafte er Könige:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, '\"Tastet meine Gesalbten nicht an, und meinen Propheten tut nichts Übles!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Und er rief eine Hungersnot über das Land herbei; jede Stütze des Brotes zerbrach er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Er sandte einen Mann vor ihnen her, Joseph wurde zum Knechte verkauft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Man preßte seine Füße in den Stock, er kam in das Eisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Bis zur Zeit, da sein Wort eintraf; das Wort Jehovas läuterte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Der König sandte hin und ließ ihn los, der Herrscher über Völker, und befreite ihn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'er setzte ihn zum Herrn über sein Haus, und zum Herrscher über all sein Besitztum,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'um seine Fürsten zu fesseln nach seiner Lust, und daß er seine Ältesten Weisheit lehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Und Israel kam nach Ägypten, und Jakob hielt sich auf im Lande Hams.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Und er machte sein Volk sehr fruchtbar, und machte es stärker als seine Bedränger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Er wandelte ihr Herz, sein Volk zu hassen, Arglist zu üben an seinen Knechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Er sandte Mose, seinen Knecht, Aaron, den er auserwählt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Sie taten unter ihnen seine Zeichen, und Wunder im Lande Hams.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Er sandte Finsternis und machte finster; und sie waren nicht widerspenstig gegen seine Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Er verwandelte ihre Wasser in Blut, und ließ sterben ihre Fische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Es wimmelte ihr Land von Fröschen, in den Gemächern ihrer Könige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Er sprach, und es kamen Hundsfliegen, Stechmücken in alle ihre Grenzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Er gab ihnen Hagel als Regen, flammendes Feuer in ihrem Lande;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'und er schlug ihre Weinstöcke und Feigenbäume, und zerbrach die Bäume ihres Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Er sprach, und es kamen Heuschrecken und Grillen ohne Zahl;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'und sie fraßen alles Kraut in ihrem Lande und fraßen die Frucht ihres Bodens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Und er schlug alle Erstgeburt in ihrem Lande, die Erstlinge all ihrer Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Und er führte sie heraus mit Silber und Gold, und kein Strauchelnder war in seinen Stämmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Froh war Ägypten, daß sie auszogen; denn ihr Schrecken war auf sie gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Er breitete eine Wolke aus zur Decke, und ein Feuer, die Nacht zu erleuchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Sie forderten, und er ließ Wachteln kommen; und mit Himmelsbrot sättigte er sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Er öffnete den Felsen, und es flossen Wasser heraus; sie liefen in den dürren Örtern wie ein Strom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Denn er gedachte seines heiligen Wortes, Abrahams, seines Knechtes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'und er führte sein Volk heraus mit Freuden, mit Jubel seine Auserwählten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Und er gab ihnen die Länder der Nationen, und das von den Völkerschaften Errungene nahmen sie in Besitz;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'damit sie seine Satzungen beobachteten und seine Gesetze bewahrten. Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Lobet Jehova! Preiset Jehova! Denn er ist gut, denn seine Güte währt ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Wer wird aussprechen die Machttaten Gottes, hören lassen all sein Lob?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Glückselig die das Recht bewahren, der Gerechtigkeit übt zu aller Zeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Gedenke meiner, Jehova, mit der Gunst gegen dein Volk; suche mich heim mit deiner Rettung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Daß ich anschaue die Wohlfahrt deiner Auserwählten, mich erfreue an der Freude deiner Nation, mich rühme mit deinem Erbteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Wir haben gesündigt samt unseren Vätern, haben unrecht getan, haben gesetzlos gehandelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Unsere Väter in Ägypten beachteten nicht deine Wundertaten, gedachten nicht der Menge deiner Gütigkeiten und waren widerspenstig am Meere, beim Schilfmeere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Aber er rettete sie um seines Namens willen, um kundzutun seine Macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Und er schalt das Schilfmeer, und es ward trocken; und er ließ sie durch die Tiefen gehen wie durch eine Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Und er rettete sie aus der Hand des Hassers, und erlöste sie aus der Hand des Feindes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Und die Wasser bedeckten ihre Bedränger, nicht einer von ihnen blieb übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Da glaubten sie seinen Worten, sie sangen sein Lob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Schnell vergaßen sie seine Taten, warteten nicht auf seinen Rat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'und sie wurden lüstern in der Wüste und versuchten Gott in der Einöde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Da gab er ihnen ihr Begehr, aber er sandte Magerkeit in ihre Seelen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Und sie wurden eifersüchtig auf Mose im Lager, auf Aaron, den Heiligen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Die Erde tat sich auf, und verschlang Dathan und bedeckte die Rotte Abirams;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'und ein Feuer brannte unter ihrer Rotte, eine Flamme verzehrte die Gesetzlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Sie machten ein Kalb am Horeb und bückten sich vor einem gegossenen Bilde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'und sie vertauschten ihre Herrlichkeit gegen das Bild eines Stieres, der Gras frißt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Sie vergaßen Gottes, ihres Retters, der Großes getan in Ägypten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Wundertaten im Lande Hams, Furchtbares am Schilfmeer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Da sprach er, daß er sie vertilgen wollte, wenn nicht Mose, sein Auserwählter, vor ihm in dem Riß gestanden hätte, um seinen Grimm vom Verderben abzuwenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Und sie verschmähten das köstliche Land, glaubten nicht seinem Worte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'und sie murrten in ihren Zelten, hörten nicht auf die Stimme Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Da schwur er ihnen, sie niederzuschlagen in der Wüste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'und ihren Samen niederzuschlagen unter den Nationen und sie zu zerstreuen in die Länder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Und sie hängten sich an Baal-Peor und aßen Schlachtopfer der Toten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'und sie erbitterten ihn durch ihre Handlungen, und eine Plage brach unter sie ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Da stand Pinehas auf und übte Gericht, und der Plage ward gewehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Und es wurde ihm zur Gerechtigkeit gerechnet von Geschlecht zu Geschlecht bis in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Und sie erzürnten ihn an dem Wasser von Meriba, und es erging Mose übel ihretwegen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'denn sie reizten seinen Geist, so daß er unbedacht redete mit seinen Lippen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Sie vertilgten die Völker nicht, wie doch Jehova ihnen gesagt hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'und sie vermischten sich mit den Nationen und lernten ihre Werke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'und sie dienten ihren Götzen, und sie wurden ihnen zum Fallstrick.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Und sie opferten ihre Söhne und ihre Töchter den Dämonen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Und sie vergossen unschuldiges Blut, das Blut ihrer Söhne und ihrer Töchter, welche sie den Götzen Kanaans opferten; und das Land wurde durch Blut entweiht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Und sie verunreinigten sich durch ihre Werke und hurten durch ihre Handlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Da entbrannte der Zorn Jehovas wider sein Volk, und er verabscheute sein Erbteil;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'und er gab sie in die Hand der Nationen, und ihre Hasser herrschten über sie;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'und ihre Feinde bedrückten sie, und sie wurden gebeugt unter ihre Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Oftmals errettete er sie; sie aber waren widerspenstig in ihren Anschlägen, und sie sanken hin durch ihre Ungerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Und er sah an ihre Bedrängnis, wenn er ihr Schreien hörte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'und er gedachte ihnen zugut an seinen Bund, und es reute ihn nach der Menge seiner Gütigkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Und er ließ sie Erbarmen finden vor allen, die sie gefangen weggeführt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Rette uns, Jehova, unser Gott, und sammle uns aus den Nationen, daß wir deinen heiligen Namen preisen, daß wir uns rühmen deines Lobes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Gepriesen sei Jehova, der Gott Israels, von Ewigkeit zu Ewigkeit! Und alles Volk sage: Amen! Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Preiset Jehova, denn er ist gut, denn seine Güte währt ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'So sollen sagen die Erlösten Jehovas, die er aus der Hand des Bedrängers erlöst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'und die er gesammelt hat aus den Ländern, von Osten und von Westen, von Norden und vom Meere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Sie irrten umher in der Wüste, auf ödem Wege, sie fanden keine Wohnstadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Hungrig waren sie und durstig, es verschmachtete in ihnen ihre Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Da schrieen sie zu Jehova in ihrer Bedrängnis, und aus ihren Drangsalen errettete er sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Und er leitete sie auf rechtem Wege, daß sie zu einer Wohnstadt gelangten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Mögen sie Jehova preisen wegen seiner Güte und wegen seiner Wundertaten an den Menschenkindern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Denn er hat die durstende Seele gesättigt und die hungernde Seele mit Gutem erfüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Die Bewohner der Finsternis und des Todesschattens, gefesselt in Elend und Eisen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Weil sie widerspenstig gewesen waren gegen die Worte Gottes und verachtet hatten den Rat des Höchsten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'so beugte er ihr Herz durch Mühsal; sie strauchelten, und kein Helfer war da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Da schrieen sie zu Jehova in ihrer Bedrängnis, und aus ihren Drangsalen rettete er sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Er führte sie heraus aus der Finsternis und dem Todesschatten, und zerriß ihre Fesseln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Mögen sie Jehova preisen wegen seiner Güte und wegen seiner Wundertaten an den Menschenkindern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Denn er hat zerbrochen die ehernen Türen und die eisernen Riegel zerschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Die Toren leiden ob des Weges ihrer Übertretung und ob ihrer Ungerechtigkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Ihre Seele verabscheut jede Speise, und sie kommen bis an die Pforten des Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Dann schreien sie zu Jehova in ihrer Bedrängnis, und aus ihren Drangsalen rettet er sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Er sendet sein Wort und heilt sie, und er errettet sie aus ihren Gruben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Mögen sie Jehova preisen wegen seiner Güte und wegen seiner Wundertaten an den Menschenkindern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'und Opfer des Lobes opfern und mit Jubel erzählen seine Taten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Die sich auf Schiffen aufs Meer hinabbegeben, auf großen Wassern Handel treiben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'diese sehen die Taten Jehovas und seine Wunderwerke in der Tiefe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Er spricht und bestellt einen Sturmwind, der hoch erhebt seine Wellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Sie fahren hinauf zum Himmel, sinken hinab in die Tiefen; es zerschmilzt in der Not ihre Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Sie taumeln und schwanken wie ein Trunkener, und zunichte wird alle ihre Weisheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Dann schreien sie zu Jehova in ihrer Bedrängnis, und er führt sie heraus aus ihren Drangsalen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Er verwandelt den Sturm in Stille, und es legen sich die Wellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Und sie freuen sich, daß sie sich beruhigen, und er führt sie in den ersehnten Hafen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Mögen sie Jehova preisen wegen seiner Güte, und wegen seiner Wundertaten an den Menschenkindern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Und ihn erheben in der Versammlung des Volkes, und in der Sitzung der Ältesten ihn loben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Er macht Ströme zur Wüste und Wasserquellen zu dürrem Lande,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'fruchtbares Land zur Salzsteppe wegen der Bosheit der darin Wohnenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Er macht zum Wasserteich die Wüste und dürres Land zu Wasserquellen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'und er läßt Hungrige daselbst wohnen und sie gründen eine Wohnstadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Und sie besäen Felder und pflanzen Weinberge, welche Frucht bringen als Ertrag;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'und er segnet sie, und sie mehren sich sehr, und ihres Viehes läßt er nicht wenig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Und sie vermindern sich und werden gebeugt durch Bedrückung, Unglück und Jammer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Er schüttet Verachtung auf Fürsten, und läßt sie umherirren in pfadloser Einöde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'und er hebt den Armen empor aus dem Elend, und macht Herden gleich seine Geschlechter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Die Aufrichtigen werden es sehen und sich freuen, und alle Ungerechtigkeit wird ihren Mund verschließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Wer weise ist, der wird dieses beachten, und verstehen werden sie die Gütigkeiten Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Ein Lied, ein Psalm. Von David. Befestigt ist mein Herz, o Gott! Ich will singen und Psalmen singen; auch meine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Wachet auf, Harfe und Laute! Ich will aufwecken die Morgenröte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Ich will dich preisen unter den Völkern, Jehova, und dich besingen unter den Völkerschaften;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'denn groß ist deine Güte über die Himmel hinaus, und bis zu den Wolken deine Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Erhebe dich über die Himmel, o Gott! Und über der ganzen Erde sei deine Herrlichkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Damit befreit werden deine Geliebten, rette durch deine Rechte und erhöre uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Gott hat geredet in seiner Heiligkeit: Frohlocken will ich, will Sichem verteilen, und das Tal Sukkoth ausmessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Mein ist Gilead, mein Manasse, und Ephraim ist die Wehr meines Hauptes, Juda mein Herrscherstab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moab ist mein Waschbecken; auf Edom will ich meine Sandale werfen, über Philistäa will ich jauchzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Wer wird mich führen in die befestigte Stadt, wer wird mich leiten bis nach Edom?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Nicht du, Gott, der du uns verworfen hast und nicht auszogest, o Gott, mit unseren Heeren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Schaffe uns Hilfe aus der Bedrängnis! Menschenrettung ist ja eitel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Mit Gott werden wir mächtige Taten tun; und er, er wird unsere Bedränger zertreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Dem Vorsänger. Von David, ein Psalm. Gott meines Lobes, schweige nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Denn der Mund des Gesetzlosen und der Mund des Truges haben sich wider mich geöffnet, mit Lügenzunge haben sie zu mir geredet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Und mit Worten des Hasses haben sie mich umgeben und haben wider mich gestritten ohne Ursache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Für meine Liebe feindeten sie mich an; ich aber bin stets im Gebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Und sie haben mir Böses für Gutes erwiesen und Haß für meine Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Bestelle einen Gesetzlosen über ihn, und ein Widersacher stehe zu seiner Rechten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Wenn er gerichtet wird, gehe er schuldig aus, und sein Gebet werde zur Sünde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Seiner Tage seien wenige, sein Amt empfange ein anderer!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Seine Söhne seien Waisen, und sein Weib eine Witwe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Und mögen seine Söhne umherschweifen und betteln und fern von ihren verwüsteten Wohnungen nach Brot suchen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Der Wucherer umgarne alles, was er hat, und Fremde mögen rauben seine Arbeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Er habe niemand, der ihm Güte bewahre, und es sei niemand, der seinen Waisen gnädig sei!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Seine Nachkommen mögen ausgerottet werden; im folgenden Geschlecht erlösche ihr Name!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Gedacht werde vor Jehova der Ungerechtigkeit seiner Väter, und nicht werde ausgelöscht die Sünde seiner Mutter!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Sie seien beständig vor Jehova, und er rotte ihr Gedächtnis aus von der Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Darum daß er nicht gedachte, Güte zu üben, und verfolgte den elenden und armen Mann, und den, der verzagten Herzens war, um ihn zu töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Und er liebte den Fluch, so komme er auf ihn! Und er hatte kein Gefallen an Segen, so sei er fern von ihm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Und er zog den Fluch an wie sein Kleid, so dringe er wie Wasser in sein Inneres und wie Öl in seine Gebeine!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Er sei ihm wie ein Gewand, in das er sich hüllt, und zu einem Gürtel, womit er stets sich gürtet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Das sei der Lohn meiner Widersacher von seiten Jehovas, und derer, die Böses reden wider meine Seele!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Du aber, Jehova, Herr, wirke für mich um deines Namens willen; weil deine Güte gut ist, errette mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Denn ich, ich bin elend und arm, und mein Herz ist verwundet in meinem Innern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Wie ein Schatten, wenn er sich streckt, gehe ich dahin, werde hinweggescheucht wie die Heuschrecke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Meine Knie wanken vom Fasten, und mein Fleisch ist abgemagert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Und ich, ich bin ihnen zum Hohn geworden; wenn sie mich sehen, schütteln sie ihren Kopf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Hilf mir, Jehova, mein Gott! Rette mich nach deiner Güte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Damit sie wissen, daß dies deine Hand ist, daß du, Jehova, es getan hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Mögen sie fluchen, du aber segne! Stehen sie auf, so laß sie beschämt werden, und deinen Knecht sich freuen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Laß meine Widersacher bekleidet werden mit Schande, und in ihre Schmach sich hüllen wie in einen Mantel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Ich werde Jehova sehr preisen mit meinem Munde, und inmitten vieler werde ich ihn loben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Denn er stand zur Rechten des Armen, um ihn zu retten von denen, die seine Seele richteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Von David. Ein Psalm. Jehova sprach zu meinem Herrn: Setze dich zu meiner Rechten, bis ich deine Feinde lege zum Schemel deiner Füße!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Den Stab deiner Macht wird Jehova aus Zion senden; herrsche inmitten deiner Feinde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Dein Volk wird voller Willigkeit sein am Tage deiner Macht; in heiliger Pracht, aus dem Schoße der Morgenröte wird dir der Tau deiner Jugend kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Geschworen hat Jehova, und es wird ihn nicht gereuen: \"Du bist Priester in Ewigkeit nach der Weise Melchisedeks!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Der Herr zu deiner Rechten zerschmettert Könige am Tage seines Zornes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Er wird richten unter den Nationen, er füllt alles mit Leichen; das Haupt über ein großes Land zerschmettert er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Auf dem Wege wird er trinken aus dem Bache, darum wird er das Haupt erheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Lobet Jehova! Preisen will ich Jehova von ganzem Herzen im Kreise der Aufrichtigen und in der Gemeinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Groß sind die Taten Jehovas, sie werden erforscht von allen, die Lust an ihnen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Majestät und Pracht ist sein Tun; und seine Gerechtigkeit besteht ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Er hat ein Gedächtnis gestiftet seinen Wundertaten; gnädig und barmherzig ist Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Er hat Speise gegeben denen, die ihn fürchten; er gedenkt in Ewigkeit seines Bundes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Er hat seinem Volke kundgemacht die Kraft seiner Taten, um ihnen zu geben das Erbteil der Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Die Taten seiner Hände sind Wahrheit und Recht; zuverlässig sind alle seine Vorschriften,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'festgestellt auf immer, auf ewig, ausgeführt in Wahrheit und Geradheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Er hat Erlösung gesandt seinem Volke, seinen Bund verordnet auf ewig; heilig und furchtbar ist sein Name.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Die Furcht Jehovas ist der Weisheit Anfang; gute Einsicht haben alle, die sie ausüben. Sein Lob besteht ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Lobet Jehova! Glückselig der Mann, der Jehova fürchtet, der große Lust hat an seinen Geboten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Sein Same wird mächtig sein im Lande; es wird gesegnet werden das Geschlecht der Aufrichtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Vermögen und Reichtum wird in seinem Hause sein, und seine Gerechtigkeit besteht ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Den Aufrichtigen geht Licht auf in der Finsternis; er ist gnädig und barmherzig und gerecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Wohl dem Manne, der gnädig ist und leiht! Er wird seine Sachen durchführen im Gericht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'denn in Ewigkeit wird er nicht wanken. Zum ewigen Andenken wird der Gerechte sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Nicht wird er sich fürchten vor böser Kunde; fest ist sein Herz, vertrauend auf Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Befestigt ist sein Herz; er fürchtet sich nicht, bis er seine Lust sieht an seinen Bedrängern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Er streut aus, gibt den Armen; seine Gerechtigkeit besteht ewiglich; sein Horn wird erhöht werden in Ehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Der Gesetzlose wird es sehen und sich ärgern; mit seinen Zähnen wird er knirschen und vergehen; das Begehren der Gesetzlosen wird untergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Lobet Jehova! Lobet, ihr Knechte Jehovas, lobet den Namen Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Gepriesen sei der Name Jehovas von nun an bis in Ewigkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Vom Aufgang der Sonne bis zu ihrem Niedergang sei gelobt der Name Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Hoch über alle Nationen ist Jehova, über die Himmel seine Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Wer ist wie Jehova, unser Gott, der hoch oben thront;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'der sich herabneigt, um auf die Himmel und auf die Erde zu schauen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Der aus dem Staube emporhebt den Geringen, aus dem Kote erhöht den Armen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'um ihn sitzen zu lassen bei den Edlen, bei den Edlen seines Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Der die Unfruchtbare des Hauses wohnen läßt als eine fröhliche Mutter von Söhnen. Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Als Israel aus Ägypten zog, das Haus Jakob aus dem Volke fremder Sprache,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'da war Juda sein Heiligtum, Israel seine Herrschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Das Meer sah es und floh, der Jordan wandte sich zurück;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'die Berge hüpften wie Widder, die Hügel wie junge Schafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Was war dir, du Meer, daß du flohest? Du Jordan, daß du dich zurückwandtest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Ihr Berge, daß ihr hüpftet wie Widder? ihr Hügel, wie junge Schafe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Erbebe vor dem Herrn, du Erde, vor dem Gott Jakobs,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Der den Felsen verwandelte in einen Wasserteich, den Kieselfelsen in einen Wasserquell!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Nicht uns, Jehova, nicht uns, sondern deinem Namen gib Ehre, um deiner Güte, um deiner Wahrheit willen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Warum sollen die Nationen sagen: Wo ist denn ihr Gott?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Aber unser Gott ist in den Himmeln; alles was ihm wohlgefällt, tut er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Ihre Götzen sind Silber und Gold, ein Werk von Menschenhänden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Einen Mund haben sie und reden nicht; Augen haben sie und sehen nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Ohren haben sie und hören nicht; eine Nase haben sie und riechen nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'sie haben Hände und tasten nicht, Füße, und sie gehen nicht; keinen Laut geben sie mit ihrer Kehle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Ihnen gleich sind die, die sie machen, ein jeder, der auf sie vertraut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Israel, vertraue auf Jehova! Ihre Hilfe und ihr Schild ist er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Haus Aaron, vertrauet auf Jehova! Ihre Hilfe und ihr Schild ist er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Ihr, die ihr Jehova fürchtet, vertrauet auf Jehova! Ihre Hilfe und ihr Schild ist er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Jehova hat unser gedacht, er wird segnen; er wird segnen das Haus Israel, segnen das Haus Aaron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Er wird segnen, die Jehova fürchten, die Kleinen mit den Großen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Jehova wird zu euch hinzufügen, zu euch und zu euren Kindern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Gesegnet seid ihr von Jehova, der Himmel und Erde gemacht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Die Himmel sind die Himmel Jehovas, die Erde aber hat er den Menschenkindern gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Die Toten werden Jehova nicht loben, noch alle, die zum Schweigen hinabfahren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'wir aber, wir werden Jehova preisen von nun an bis in Ewigkeit. Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Ich liebe Jehova; denn er hörte meine Stimme, mein Flehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'denn er hat zu mir geneigt sein Ohr; und ich will ihn anrufen in allen meinen Tagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Es umfingen mich die Bande des Todes, und die Bedrängnisse des Scheols erreichten mich; ich fand Drangsal und Kummer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Und ich rief an den Namen Jehovas: Bitte, Jehova, errette meine Seele!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Gnädig ist Jehova und gerecht, und unser Gott ist barmherzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Jehova bewahrt die Einfältigen; ich war elend, und er hat mich gerettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Kehre wieder, meine Seele, zu deiner Ruhe! Denn Jehova hat wohlgetan an dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Denn du hast meine Seele errettet vom Tode, meine Augen von Tränen, meinen Fuß vom Sturz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Ich werde wandeln vor Jehova in dem Lande der Lebendigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Ich glaubte, darum redete ich. Ich bin sehr gebeugt gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Ich sprach in meiner Bestürzung: Alle Menschen sind Lügner!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Wie soll ich Jehova alle seine Wohltaten an mir vergelten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Den Becher der Rettungen will ich nehmen und anrufen den Namen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Ich will Jehova meine Gelübde bezahlen, ja, in der Gegenwart seines ganzen Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Kostbar ist in den Augen Jehovas der Tod seiner Frommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Bitte, Jehova! Denn ich bin dein Knecht; ich bin dein Knecht, der Sohn deiner Magd; gelöst hast du meine Bande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Dir will ich Opfer des Lobes opfern, und anrufen den Namen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Ich will Jehova meine Gelübde bezahlen, ja, in der Gegenwart seines ganzen Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'In den Vorhöfen des Hauses Jehovas, in deiner Mitte, Jerusalem. Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Lobet Jehova, alle Nationen! Rühmet ihn, alle Völker!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Denn mächtig über uns ist seine Güte; und die Wahrheit Jehovas währt ewiglich. Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Preiset Jehova! Denn er ist gut, denn seine Güte währt ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Es sage doch Israel: denn seine Güte währt ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Es sage doch das Haus Aaron: denn seine Güte währt ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Es sagen doch, die Jehova fürchten: denn seine Güte währt ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Aus der Bedrängnis rief ich zu Jah; Jah erhörte mich und setzte mich in einen weiten Raum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Jehova ist für mich, ich werde mich nicht fürchten; was sollte der Mensch mir tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Jehova ist für mich unter meinen Helfern, und ich werde meine Lust sehen an meinen Hassern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Es ist besser, auf Jehova zu trauen, als sich zu verlassen auf den Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Es ist besser, auf Jehova zu trauen, als sich zu verlassen auf Fürsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Alle Nationen hatten mich umringt; gewiß, im Namen Jehovas vertilgte ich sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Sie hatten mich umringt, ja, mich umringt; gewiß, im Namen Jehovas vertilgte ich sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Sie hatten mich umringt wie Bienen; sie sind erloschen wie Dornenfeuer; gewiß, im Namen Jehovas vertilgte ich sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Hart hast du mich gestoßen, um mich zu Fall zu bringen; aber Jehova hat mir geholfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Meine Stärke und mein Gesang ist Jah, und er ist mir zur Rettung geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Die Stimme des Jubels und der Rettung ist in den Zelten der Gerechten; die Rechte Jehovas tut mächtige Taten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Die Rechte Jehovas ist erhoben, die Rechte Jehovas tut mächtige Taten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Ich werde nicht sterben, sondern leben und die Taten Jahs erzählen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Hart hat mich Jah gezüchtigt, aber dem Tode hat er mich nicht übergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Öffnet mir die Tore der Gerechtigkeit: ich will durch sie eingehen, Jah will ich preisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Dies ist das Tor Jehovas: Die Gerechten werden durch dasselbe eingehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Ich will dich preisen, denn du hast mich erhört und bist mir zur Rettung geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Der Stein, den die Bauleute verworfen haben, ist zum Eckstein geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Von Jehova ist dies geschehen; wunderbar ist es in unseren Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Dies ist der Tag, den Jehova gemacht hat; frohlocken wir und freuen wir uns in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Bitte, Jehova, rette doch! Bitte, Jehova, gib doch Wohlfahrt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Gesegnet, der da kommt im Namen Jehovas! Von dem Hause Jehovas aus haben wir euch gesegnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Jehova ist Gott, und er hat uns Licht gegeben; bindet das Festopfer mit Stricken bis an die Hörner des Altars.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Du bist mein Gott, und ich will dich preisen; mein Gott, ich will dich erheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Preiset Jehova! Denn er ist gut, denn seine Güte währt ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Glückselig, die im Wege untadelig sind, die da wandeln im Gesetze Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Glückselig, die seine Zeugnisse bewahren, die von ganzem Herzen ihn suchen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Die auch kein Unrecht tun, in seinen Wegen wandeln!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Du hast deine Vorschriften geboten, um sie fleißig zu beobachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'O daß meine Wege gerichtet wären, um deine Satzungen zu beobachten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Dann werde ich nicht beschämt werden, wenn ich achthabe auf alle deine Gebote.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Preisen werde ich dich in Aufrichtigkeit des Herzens, wenn ich gelernt habe die Rechte deiner Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Deine Satzungen werde ich beobachten; verlaß mich nicht ganz und gar!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Wodurch wird ein Jüngling seinen Pfad in Reinheit wandeln? Indem er sich bewahrt nach deinem Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Mit meinem ganzen Herzen habe ich dich gesucht: laß mich nicht abirren von deinen Geboten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'In meinem Herzen habe ich dein Wort verwahrt, auf daß ich nicht wider dich sündige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Gepriesen seiest du, Jehova! Lehre mich deine Satzungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Mit meinen Lippen habe ich erzählt alle Rechte deines Mundes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'An dem Wege deiner Zeugnisse habe ich mich erfreut wie über allen Reichtum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Über deine Vorschriften will ich sinnen und achthaben auf deine Pfade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'An deinen Satzungen habe ich meine Wonne; deines Wortes werde ich nicht vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Tue wohl an deinem Knechte, so werde ich leben; und ich will dein Wort bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Öffne meine Augen, damit ich Wunder schaue in deinem Gesetz!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Ein Fremdling bin ich im Lande, verbirg nicht vor mir deine Gebote!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Zermalmt ist meine Seele vor Verlangen nach deinen Rechten zu aller Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Gescholten hast du die Übermütigen, die Verfluchten, welche abirren von deinen Geboten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Wälze von mir Hohn und Verachtung! Denn deine Zeugnisse habe ich bewahrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Sitzen auch Fürsten und bereden sich wider mich, dein Knecht sinnt über deine Satzungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Deine Zeugnisse sind auch meine Wonne, meine Ratgeber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Am Staube klebt meine Seele; belebe mich nach deinem Worte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Meine Wege habe ich erzählt, und du hast mich erhört; lehre mich deine Satzungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Laß mich verstehen den Weg deiner Vorschriften, und sinnen will ich über deine Wundertaten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Vor Traurigkeit zerfließt in Tränen meine Seele; richte mich auf nach deinem Worte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Wende von mir ab den Weg der Lüge und gewähre mir dein Gesetz!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Den Weg der Treue habe ich erwählt, habe vor mich gestellt deine Rechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Ich hange an deinen Zeugnissen; Jehova, laß mich nicht beschämt werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Den Weg deiner Gebote werde ich laufen, wenn du Raum gemacht haben wirst meinem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Lehre mich, Jehova, den Weg deiner Satzungen, und ich will ihn bewahren bis ans Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Gib mir Einsicht, und ich will dein Gesetz bewahren und es halten von ganzem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Laß mich wandeln auf dem Pfade deiner Gebote! Denn an ihm habe ich meine Lust.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Neige mein Herz zu deinen Zeugnissen und nicht zum Gewinn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Wende meine Augen ab, daß sie Eitles nicht sehen! Belebe mich in deinen Wegen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Bestätige deinem Knechte deine Zusage, welche deiner Furcht entspricht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Wende ab meinen Hohn, den ich fürchte! Denn deine Rechte sind gut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Siehe, ich verlange nach deinen Vorschriften; belebe mich in deiner Gerechtigkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Und laß über mich kommen deine Gütigkeiten, Jehova, deine Rettung nach deiner Zusage!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'So werde ich Antwort geben dem mich Höhnenden; denn ich vertraue auf dein Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Und entziehe meinem Munde nicht gänzlich das Wort der Wahrheit! Denn ich harre auf deine Rechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Und halten will ich dein Gesetz beständig, immer und ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Und ich werde wandeln in weitem Raume; denn nach deinen Vorschriften habe ich getrachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Und vor Königen will ich reden von deinen Zeugnissen und mich nicht schämen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Und ich werde meine Wonne haben an deinen Geboten, die ich liebe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'und werde meine Hände aufheben zu deinen Geboten, die ich liebe; und über deine Satzungen will ich sinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Gedenke des Wortes an deinen Knecht, auf welches du mich hast harren lassen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Dies ist mein Trost in meinem Elende, daß deine Zusage mich belebt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Die Übermütigen haben mich über die Maßen verspottet; von deinem Gesetz bin ich nicht abgewichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Ich gedachte, Jehova, deiner Rechte von alters her, und ich tröstete mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Zornglut hat mich ergriffen wegen der Gesetzlosen, die dein Gesetz verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Deine Satzungen sind meine Gesänge gewesen im Hause meiner Fremdlingschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Des Nachts habe ich deines Namens gedacht, Jehova, und ich habe dein Gesetz gehalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Dies ist mir geschehen, weil ich deine Vorschriften bewahrt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Mein Teil, Jehova, habe ich gesagt, ist, deine Worte zu bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Von ganzem Herzen habe ich dich angefleht; sei mir gnädig nach deiner Zusage!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Ich habe meine Wege überdacht, und meine Füße gekehrt zu deinen Zeugnissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Ich habe geeilt und nicht gesäumt, deine Gebote zu halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Die Bande der Gesetzlosen haben mich umgeben; dein Gesetz habe ich nicht vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Um Mitternacht stehe ich auf, um dich zu preisen wegen der Rechte deiner Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Ich bin der Gefährte aller, die dich fürchten, und derer, die deine Vorschriften beobachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Von deiner Güte, Jehova, ist die Erde erfüllt; lehre mich deine Satzungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Du hast Gutes getan an deinem Knechte, Jehova, nach deinem Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Gute Einsicht und Erkenntnis lehre mich! Denn ich habe deinen Geboten geglaubt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Bevor ich gedemütigt ward, irrte ich; jetzt aber bewahre ich dein Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Du bist gut und guttätig; lehre mich deine Satzungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Lügen haben die Übermütigen wider mich erdichtet; ich bewahre deine Vorschriften von ganzem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Ihr Herz ist dick geworden wie Fett; ich habe meine Wonne an deinem Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Es ist gut für mich, daß ich gedemütigt ward, damit ich deine Satzungen lernte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Besser ist mir das Gesetz deines Mundes als Tausende von Gold und Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Deine Hände haben mich gemacht und bereitet; gib mir Einsicht, und ich will deine Gebote lernen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Die dich fürchten, werden mich sehen und sich freuen; denn ich habe auf dein Wort geharrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Ich weiß, Jehova, daß deine Gerichte Gerechtigkeit sind und daß du mich gedemütigt hast in Treue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Laß doch deine Güte mir zum Troste sein, nach deiner Zusage an deinen Knecht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Laß deine Erbarmungen über mich kommen, so werde ich leben; denn dein Gesetz ist meine Wonne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Laß beschämt werden die Übermütigen! Denn sie haben mich gebeugt ohne Grund; ich, ich sinne über deine Vorschriften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Laß sich zu mir kehren, die dich fürchten und die deine Zeugnisse kennen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Laß mein Herz untadelig sein in deinen Satzungen, damit ich nicht beschämt werde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Meine Seele schmachtet nach deiner Rettung, ich harre auf dein Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Meine Augen schmachten nach deiner Zusage, indem ich spreche: Wann wirst du mich trösten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Denn wie ein Schlauch im Rauche bin ich geworden; deine Satzungen habe ich nicht vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Wie viele werden der Tage deines Knechtes sein? Wann wirst du Gericht üben an meinen Verfolgern?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Die Übermütigen haben mir Gruben gegraben, sie, die nicht nach deinem Gesetz sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Alle deine Gebote sind Treue. Sie haben mich verfolgt ohne Grund: hilf mir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Wenig fehlte, so hätten sie mich vernichtet auf der Erde; ich aber, ich habe deine Vorschriften nicht verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Belebe mich nach deiner Güte, und ich will bewahren das Zeugnis deines Mundes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'In Ewigkeit, Jehova, steht dein Wort fest in den Himmeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'von Geschlecht zu Geschlecht währt deine Treue; du hast die Erde festgestellt, und sie steht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Nach deinen Verordnungen stehen sie heute da, denn alle Dinge dienen dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Wäre nicht dein Gesetz meine Wonne gewesen, dann würde ich umgekommen sein in meinem Elende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Nimmermehr werde ich deine Vorschriften vergessen, denn durch sie hast du mich belebt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Ich bin dein, rette mich! Denn ich habe nach deinen Vorschriften getrachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Die Gesetzlosen haben mir aufgelauert, um mich umzubringen; ich achte auf deine Zeugnisse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Von aller Vollkommenheit habe ich ein Ende gesehen; sehr ausgedehnt ist dein Gebot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Wie liebe ich dein Gesetz! Es ist mein Sinnen den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Weiser als meine Feinde machen mich deine Gebote, denn immer sind sie bei mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Verständiger bin ich als alle meine Lehrer, denn deine Zeugnisse sind mein Sinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Mehr Einsicht habe ich als die Alten, denn deine Vorschriften habe ich bewahrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Von jedem bösen Pfade habe ich meine Füße zurückgehalten, damit ich dein Wort bewahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Nicht bin ich von deinen Rechten gewichen, denn du, du hast mich unterwiesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Wie süß sind meinem Gaumen deine Worte, mehr als Honig meinem Munde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Aus deinen Vorschriften empfange ich Einsicht; darum hasse ich jeden Lügenpfad.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Dein Wort ist Leuchte meinem Fuße und Licht für meinen Pfad.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Ich habe geschworen und halte es aufrecht, zu beobachten die Rechte deiner Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Ich bin über die Maßen gebeugt; Jehova, belebe mich nach deinem Worte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Laß dir doch wohlgefallen, Jehova, die freiwilligen Opfer meines Mundes, lehre mich deine Rechte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Mein Leben ist stets in meiner Hand, aber dein Gesetz habe ich nicht vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Die Gesetzlosen haben mir eine Schlinge gelegt, aber von deinen Vorschriften bin ich nicht abgeirrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Deine Zeugnisse habe ich mir als Erbteil genommen auf ewig, denn meines Herzens Freude sind sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Ich habe mein Herz geneigt, deine Satzungen zu tun ewiglich bis ans Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Die Doppelherzigen hasse ich, und ich liebe dein Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Mein Bergungsort und mein Schild bist du; auf dein Wort harre ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Weichet von mir, ihr Übeltäter: ich will die Gebote meines Gottes bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Unterstütze mich nach deiner Zusage, so werde ich leben; und laß mich nicht beschämt werden in meiner Hoffnung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Stütze mich, so werde ich gerettet werden; und ich will stets schauen auf deine Satzungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Verworfen hast du alle, die von deinen Satzungen abirren; denn Lüge ist ihr Trug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Wie Schlacken hast du hinweggeräumt alle Gesetzlosen der Erde; darum liebe ich deine Zeugnisse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Vor deinem Schrecken schaudert mein Fleisch, und ich fürchte mich vor deinen Gerichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Ich habe Recht und Gerechtigkeit geübt; überlaß mich nicht meinen Bedrückern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Sei Bürge für deinen Knecht zum Guten; laß die Übermütigen mich nicht bedrücken!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Meine Augen schmachten nach deiner Rettung und nach der Zusage deiner Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Handle mit deinem Knechte nach deiner Güte, und lehre mich deine Satzungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Dein Knecht bin ich, gib mir Einsicht, so werde ich deine Zeugnisse erkennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Es ist Zeit für Jehova zu handeln: sie haben dein Gesetz gebrochen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Darum liebe ich deine Gebote mehr als Gold und gediegenes Gold;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'darum halte ich alle deine Vorschriften für recht; jeden Lügenpfad hasse ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Wunderbar sind deine Zeugnisse, darum bewahrt sie meine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Die Eröffnung deines Wortes erleuchtet, gibt Einsicht den Einfältigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Ich habe meinen Mund weit aufgetan und gelechzt, denn ich habe verlangt nach deinen Geboten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Wende dich zu mir und sei mir gnädig, nach dem Rechte derer, die deinen Namen lieben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Befestige meine Schritte in deinem Worte, und laß kein Unrecht mich beherrschen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Erlöse mich von der Bedrückung des Menschen, und ich will deine Vorschriften beobachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Laß dein Angesicht leuchten über deinen Knecht, und lehre mich deine Satzungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Wasserbäche fließen herab aus meinen Augen, weil sie dein Gesetz nicht halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Gerecht bist du, Jehova, und gerade sind deine Gerichte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Du hast in Gerechtigkeit deine Zeugnisse geboten und in Treue gar sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Verzehrt hat mich mein Eifer, denn meine Bedränger haben deine Worte vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Wohlgeläutert ist dein Wort, und dein Knecht hat es lieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Gering bin ich und verachtet; deine Vorschriften habe ich nicht vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Deine Gerechtigkeit ist eine ewige Gerechtigkeit, und dein Gesetz ist Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Angst und Bedrängnis haben mich erreicht; deine Gebote sind meine Wonne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Gerechtigkeit sind deine Zeugnisse ewiglich; gib mir Einsicht, so werde ich leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Von ganzem Herzen habe ich gerufen; erhöre mich, Jehova! Ich will deine Satzungen beobachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Zu dir habe ich gerufen, rette mich! Und ich will deine Zeugnisse bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Der Morgendämmerung bin ich zuvorgekommen und habe geschrieen; auf dein Wort habe ich geharrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Meine Augen sind den Nachtwachen zuvorgekommen, um zu sinnen über dein Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Höre meine Stimme nach deiner Güte; Jehova, belebe mich nach deinen Rechten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Es haben sich genaht, die bösen Plänen nachjagen; fern sind sie von deinem Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Du bist nahe, Jehova; und alle deine Gebote sind Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Von alters her habe ich aus deinen Zeugnissen gewußt, daß du sie gegründet hast auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Sieh an mein Elend und befreie mich! Denn dein Gesetz habe ich nicht vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Führe meinen Rechtsstreit und erlöse mich! Belebe mich nach deiner Zusage!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Fern ist von den Gesetzlosen Rettung, denn nach deinen Satzungen trachten sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Deiner Erbarmungen sind viele, Jehova; belebe mich nach deinen Rechten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Viele sind meiner Verfolger und meiner Bedränger; von deinen Zeugnissen bin ich nicht abgewichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Die Treulosen habe ich gesehen, und es ekelte mich an, weil sie dein Wort nicht bewahrten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Sieh, daß ich deine Vorschriften lieb habe; nach deiner Güte, Jehova, belebe mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Die Summe deines Wortes ist Wahrheit, und alles Recht deiner Gerechtigkeit währt ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Fürsten haben mich verfolgt ohne Ursache; aber vor deinem Worte hat mein Herz sich gefürchtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Ich freue mich über dein Wort wie einer, der große Beute findet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Lüge hasse und verabscheue ich; ich liebe dein Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Siebenmal des Tages lobe ich dich um der Rechte deiner Gerechtigkeit willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Große Wohlfahrt haben die, die dein Gesetz lieben, und kein Fallen gibt es für sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Ich habe auf deine Rettung gewartet, Jehova; und deine Gebote habe ich getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Meine Seele hat deine Zeugnisse bewahrt, und ich liebe sie sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Deine Vorschriften und deine Zeugnisse habe ich bewahrt, denn alle meine Wege sind vor dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Laß mein Schreien nahe vor dich kommen, Jehova; gib mir Einsicht nach deinem Worte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Laß vor dich kommen mein Flehen; errette mich nach deiner Zusage!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Meine Lippen sollen dein Lob hervorströmen lassen, wenn du mich gelehrt hast deine Satzungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Meine Zunge soll laut reden von deinem Worte, denn alle deine Gebote sind Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Laß deine Hand mir zu Hilfe kommen! Denn ich habe deine Vorschriften erwählt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Ich sehne mich nach deiner Rettung, Jehova; und dein Gesetz ist meine Wonne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Laß meine Seele leben, und sie wird dich loben; und deine Rechte mögen mir helfen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Ich bin umhergeirrt wie ein verlorenes Schaf; suche deinen Knecht! Denn ich habe deine Gebote nicht vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Ein Stufenlied. Zu Jehova rief ich in meiner Bedrängnis, und er erhörte mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Jehova, errette meine Seele von der Lippe der Lüge, von der Zunge des Truges!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Was soll man dir geben und was dir hinzufügen, du Zunge des Truges?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Scharfe Pfeile eines Gewaltigen, samt glühenden Kohlen der Ginster.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Wehe mir, daß ich weile in Mesech, daß ich wohne bei den Zelten Kedars!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Lange hat meine Seele bei denen gewohnt, die den Frieden hassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Ich will nur Frieden; aber wenn ich rede, so sind sie für Krieg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Ein Stufenlied. Ich hebe meine Augen auf zu den Bergen, woher meine Hilfe kommen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Meine Hilfe kommt von Jehova, der Himmel und Erde gemacht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Er wird nicht zulassen, daß dein Fuß wanke; dein Hüter schlummert nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Siehe, der Hüter Israels, nicht schlummert noch schläft er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Jehova ist dein Hüter, Jehova ist dein Schatten über deiner rechten Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Nicht wird die Sonne dich stechen des Tages, noch der Mond des Nachts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Jehova wird dich behüten vor allem Übel, er wird behüten deine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Jehova wird behüten deinen Ausgang und deinen Eingang, von nun an bis in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Ein Stufenlied. Von David. Ich freute mich, als sie zu mir sagten: Lasset uns zum Hause Jehovas gehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Unsere Füße werden in deinen Toren stehen, Jerusalem!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jerusalem, die du aufgebaut bist als eine fest in sich geschlossene Stadt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'wohin die Stämme hinaufziehen, die Stämme Jahs, ein Zeugnis für Israel, zu preisen den Namen Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Denn daselbst stehen die Throne zum Gericht, die Throne des Hauses Davids.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Bittet um die Wohlfahrt Jerusalems! Es gehe wohl denen, die dich lieben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Wohlfahrt sei in deinen Festungswerken, sichere Ruhe in deinen Palästen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Um meiner Brüder und meiner Genossen willen will ich sagen: Wohlfahrt sei in dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Um des Hauses Jehovas, unseres Gottes, willen will ich dein Bestes suchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Ein Stufenlied. Ich hebe meine Augen auf zu dir, der du thronst in den Himmeln!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Siehe, wie die Augen der Knechte auf die Hand ihres Herrn, wie die Augen der Magd auf die Hand ihrer Gebieterin, also sind unsere Augen gerichtet auf Jehova, unseren Gott, bis er uns gnädig ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Sei uns gnädig, Jehova, sei uns gnädig! Denn reichlich sind wir mit Verachtung gesättigt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'reichlich ist unsere Seele gesättigt mit dem Spotte der Sorglosen, mit der Verachtung der Hoffärtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Ein Stufenlied. Von David. Wenn nicht Jehova für uns gewesen wäre, sage doch Israel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'wenn nicht Jehova für uns gewesen wäre, als die Menschen wider uns aufstanden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'dann würden sie uns lebendig verschlungen haben, als ihr Zorn gegen uns entbrannte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'dann würden die Wasser uns überflutet haben, würde ein Strom über unsere Seele gegangen sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'dann würden über unsere Seele gegangen sein die stolzen Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Gepriesen sei Jehova, der uns nicht zum Raube gab ihren Zähnen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Unsere Seele ist entronnen wie ein Vogel aus der Schlinge der Vogelsteller; die Schlinge ist zerrissen, und wir sind entronnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Unsere Hilfe ist im Namen Jehovas, der Himmel und Erde gemacht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Ein Stufenlied. Die auf Jehova vertrauen, sind gleich dem Berge Zion, der nicht wankt, der ewiglich bleibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Jerusalem, Berge sind rings um sie her: so ist Jehova rings um sein Volk, von nun an bis in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Denn die Rute der Gesetzlosigkeit wird auf dem Lose der Gerechten nicht ruhen, damit die Gerechten ihre Hände nicht ausstrecken nach Unrecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Tue Gutes, Jehova, den Guten und denen, die aufrichtig sind in ihren Herzen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Die aber auf ihre krummen Wege abbiegen, die wird Jehova dahinfahren lassen mit denen, welche Frevel tun. Wohlfahrt über Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Ein Stufenlied. Als Jehova die Gefangenen Zions zurückführte, waren wir wie Träumende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Da ward unser Mund voll Lachens, und unsere Zunge voll Jubels; da sagte man unter den Nationen: Jehova hat Großes an ihnen getan!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Jehova hat Großes an uns getan: wir waren fröhlich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Führe unsere Gefangenen zurück, Jehova, gleich Bächen im Mittagslande!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Die mit Tränen säen, werden mit Jubel ernten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Er geht hin unter Weinen und trägt den Samen zur Aussaat; er kommt heim mit Jubel und trägt seine Garben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Ein Stufenlied. Von Salomo. Wenn Jehova das Haus nicht baut, vergeblich arbeiten daran die Bauleute; wenn Jehova die Stadt nicht bewacht, vergeblich wacht der Wächter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Vergeblich ist es für euch, daß ihr früh aufstehet, spät aufbleibet, das Brot der Mühsal esset; also gibt er seinem Geliebten im Schlaf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Siehe, ein Erbteil Jehovas sind Söhne, eine Belohnung die Leibesfrucht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'wie Pfeile in der Hand eines Helden, so sind die Söhne der Jugend:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Glückselig der Mann, der mit ihnen seinen Köcher gefüllt hat! Sie werden nicht beschämt werden, wenn sie mit Feinden reden im Tore.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Ein Stufenlied. Glückselig ein jeder, der Jehova fürchtet, der da wandelt in seinen Wegen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Denn essen wirst du die Arbeit deiner Hände; glückselig wirst du sein, und es wird dir wohlgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Dein Weib wird gleich einem fruchtbaren Weinstock sein im Innern deines Hauses, deine Söhne gleich Ölbaumsprossen rings um deinen Tisch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Siehe, also wird gesegnet sein der Mann, der Jehova fürchtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Segnen wird dich Jehova von Zion aus, und du wirst das Wohl Jerusalems schauen alle Tage deines Lebens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'und sehen deiner Kinder Kinder. Wohlfahrt über Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Ein Stufenlied. Oftmals haben sie mich bedrängt von meiner Jugend an, sage doch Israel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'oftmals haben sie mich bedrängt von meiner Jugend an; dennoch haben sie mich nicht übermocht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Pflüger haben auf meinem Rücken gepflügt, haben lang gezogen ihre Furchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Jehova ist gerecht; er hat durchschnitten das Seil der Gesetzlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Mögen beschämt werden und zurückweichen alle, die Zion hassen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Mögen sie sein wie das Gras der Dächer, welches verdorrt, ehe man es ausrauft,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'womit der Schnitter seine Hand nicht füllt, noch der Garbenbinder seinen Schoß;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'und die Vorübergehenden sagen nicht: Jehovas Segen über euch! Wir segnen euch im Namen Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Ein Stufenlied. Aus den Tiefen rufe ich zu dir, Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Herr, höre auf meine Stimme! Laß deine Ohren aufmerksam sein auf die Stimme meines Flehens!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Wenn du, Jehova, merkst auf die Ungerechtigkeiten: Herr, wer wird bestehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Doch bei dir ist Vergebung, damit du gefürchtet werdest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Ich warte auf Jehova, meine Seele wartet; und auf sein Wort harre ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Meine Seele harrt auf den Herrn, mehr als die Wächter auf den Morgen, die Wächter auf den Morgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Harre, Israel, auf Jehova! Denn bei Jehova ist die Güte, und viel Erlösung bei ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Und er, er wird Israel erlösen von allen seinen Ungerechtigkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Ein Stufenlied. Von David. Jehova! Nicht hoch ist mein Herz, noch tragen sich hoch meine Augen; und ich wandle nicht in Dingen, die zu groß und zu wunderbar für mich sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Habe ich meine Seele nicht beschwichtigt und gestillt? Gleich einem entwöhnten Kinde bei seiner Mutter, gleich dem entwöhnten Kinde ist meine Seele in mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Harre, Israel, auf Jehova, von nun an bis in Ewigkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Ein Stufenlied. Gedenke, Jehova, dem David alle seine Mühsal!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Welcher Jehova schwur, ein Gelübde tat dem Mächtigen Jakobs:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, '\"Wenn ich hineingehe in das Zelt meines Hauses, wenn ich steige auf das Lager meines Bettes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'wenn ich Schlaf gestatte meinen Augen, Schlummer meinen Augenlidern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'bis ich eine Stätte finde für Jehova, Wohnungen für den Mächtigen Jakobs!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Siehe, wir hörten von ihr in Ephrata, wir fanden sie in dem Gefilde Jaars.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Lasset uns eingehen in seine Wohnungen, niederfallen vor dem Schemel seiner Füße!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Stehe auf, Jehova, zu deiner Ruhe, du und die Lade deiner Stärke!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Laß deine Priester bekleidet werden mit Gerechtigkeit, und deine Frommen jubeln!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Um Davids, deines Knechtes, willen weise nicht ab das Angesicht deines Gesalbten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Jehova hat dem David geschworen in Wahrheit, er wird nicht davon abweichen: \"Von der Frucht deines Leibes will ich auf deinen Thron setzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Wenn deine Söhne meinen Bund und meine Zeugnisse bewahren, welche ich sie lehren werde, so sollen auch ihre Söhne auf deinem Throne sitzen immerdar.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Denn Jehova hat Zion erwählt, hat es begehrt zu seiner Wohnstätte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Dies ist meine Ruhe immerdar; hier will ich wohnen, denn ich habe es begehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Seine Speise will ich reichlich segnen, seine Armen mit Brot sättigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Und seine Priester will ich bekleiden mit Heil, und seine Frommen werden laut jubeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Dort will ich das Horn Davids wachsen lassen, habe eine Leuchte zugerichtet meinem Gesalbten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Seine Feinde will ich bekleiden mit Schande, und auf ihm wird seine Krone blühen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Ein Stufenlied. Siehe, wie gut und wie lieblich ist es, wenn Brüder einträchtig beieinander wohnen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Wie das köstliche Öl auf dem Haupte, das herabfließt auf den Bart, auf den Bart Aarons, das herabfließt auf den Saum seiner Kleider;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'wie der Tau des Hermon, der herabfällt auf die Berge Zions; denn dort hat Jehova den Segen verordnet, Leben bis in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Ein Stufenlied. Siehe, preiset Jehova, alle ihr Knechte Jehovas, die ihr stehet im Hause Jehovas in den Nächten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Erhebet eure Hände im Heiligtum und preiset Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Jehova segne dich von Zion aus, der Himmel und Erde gemacht hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Lobet Jehova! Lobet den Namen Jehovas! Lobet, ihr Knechte Jehovas,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'die ihr stehet im Hause Jehovas, in den Vorhöfen des Hauses unseres Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Lobet Jehova! Denn gut ist Jehova; singet Psalmen seinem Namen! Denn er ist lieblich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Denn Jehova hat sich Jakob erwählt, Israel zu seinem Eigentum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Denn ich weiß, daß Jehova groß ist, und unser Herr groß vor allen Göttern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Alles, was Jehova wohlgefällt, tut er in den Himmeln und auf der Erde, in den Meeren und in allen Tiefen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'der Dünste aufsteigen läßt vom Ende der Erde, der Blitze macht zum Regen, der den Wind herausführt aus seinen Vorratskammern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'der die Erstgeborenen Ägyptens schlug vom Menschen bis zum Vieh,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Zeichen und Wunder sandte in deine Mitte, Ägypten, wider den Pharao und wider alle seine Knechte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'der große Nationen schlug und starke Könige tötete:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Sihon, den König der Amoriter, und Og, den König von Basan, und alle Königreiche Kanaans;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'und ihr Land als Erbteil gab, als Erbteil seinem Volke Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Jehova, dein Name währt ewiglich, Jehova, dein Gedächtnis von Geschlecht zu Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Denn Jehova wird sein Volk richten, und er wird sich\'s gereuen lassen über seine Knechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Die Götzen der Nationen sind Silber und Gold, ein Werk von Menschenhänden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Einen Mund haben sie und reden nicht; Augen haben sie und sehen nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Ohren haben sie und hören nicht; auch ist kein Odem in ihrem Munde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Ihnen gleich sind die, die sie machen, ein jeder, der auf sie vertraut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Haus Israel, preiset Jehova! Haus Aaron, preiset Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Haus Levi, preiset Jehova! Die ihr Jehova fürchtet, preiset Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Gepriesen sei Jehova von Zion aus, der zu Jerusalem wohnt! Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Preiset Jehova! Denn er ist gütig, denn seine Güte währt ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Preiset den Gott der Götter, denn seine Güte währt ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Preiset den Herrn der Herren! Denn seine Güte währt ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'den, der große Wunder tut, er allein, denn seine Güte währt ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Den, der die Himmel gemacht hat mit Einsicht, denn seine Güte währt ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Den, der die Erde ausgebreitet hat über den Wassern, denn seine Güte währt ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Den, der große Lichter gemacht hat, denn seine Güte währt ewiglich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Die Sonne zur Beherrschung des Tages, denn seine Güte währt ewiglich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'den Mond und die Sterne zur Beherrschung der Nacht, denn seine Güte währt ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'den, der Ägypten schlug an seinen Erstgeborenen, denn seine Güte währt ewiglich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'und Israel herausführte aus ihrer Mitte, denn seine Güte währt ewiglich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'mit starker Hand und mit ausgestrecktem Arm, denn seine Güte währt ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'den, der das Schilfmeer in zwei Teile zerteilte, denn seine Güte währt ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'und Israel mitten hindurchgehen ließ, denn seinen Güte währt ewiglich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'und den Pharao und sein Heer ins Schilfmeer stürzte, denn seine Güte währt ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'den, der sein Volk durch die Wüste führte, denn seine Güte währt ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'den, der große Könige schlug, denn seine Güte währt ewiglich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'und mächtige Könige schlug, denn seine Güte währt ewiglich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sihon, den König der Amoriter, denn seine Güte währt ewiglich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'und Og, den König von Basan, denn seine Güte währt ewiglich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'und ihr Land zum Erbteil gab, denn seine Güte währt ewiglich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'zum Erbteil seinem Knechte Israel, denn seine Güte währt ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'der unser gedachte in unserer Niedrigkeit, denn seine Güte währt ewiglich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'und uns errettete von unseren Bedrängern, denn seine Güte währt ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'der Speise gibt allem Fleische, denn seine Güte währt ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Preiset den Gott der Himmel! Denn seine Güte währt ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'An den Flüssen Babels, da saßen wir und weinten, indem wir Zions gedachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'An die Weiden in ihr hängten wir unsere Lauten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Denn die uns gefangen weggeführt hatten, forderten daselbst von uns die Worte eines Liedes, und die uns wehklagen machten, Freude: \"Singet uns eines von Zions Liedern!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Wie sollten wir ein Lied Jehovas singen auf fremder Erde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Wenn ich dein vergesse, Jerusalem, so vergesse meine Rechte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Es klebe meine Zunge an meinem Gaumen, wenn ich deiner nicht gedenke, wenn ich Jerusalem nicht erhebe über die höchste meiner Freuden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Gedenke, Jehova, den Kindern Edom den Tag Jerusalems, die da sprachen: Entblößet, entblößet sie bis auf ihre Grundfeste!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Tochter Babel, du Verwüstete! Glückselig, der dir dasselbe vergilt, was du uns getan hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Glückselig, der deine Kindlein ergreift und sie hinschmettert an den Felsen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Von David. Preisen will ich dich mit meinem ganzen Herzen, will dich besingen vor den Göttern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Ich will anbeten gegen deinen heiligen Tempel, und deinen Namen preisen um deiner Güte und deiner Wahrheit willen; denn du hast dein Wort groß gemacht über all deinen Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'An dem Tage, da ich rief, antwortetest du mir; du hast mich ermutigt: in meiner Seele war Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Alle Könige der Erde werden dich preisen, Jehova, wenn sie gehört haben die Worte deines Mundes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'und sie werden die Wege Jehovas besingen, denn groß ist die Herrlichkeit Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Denn Jehova ist hoch, und er sieht den Niedrigen, und den Hochmütigen erkennt er von ferne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Wenn ich inmitten der Drangsal wandle, wirst du mich beleben; wider den Zorn meiner Feinde wirst du deine Hand ausstrecken, und deine Rechte wird mich retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Jehova wird\'s für mich vollenden. Jehova, deine Güte währt ewiglich. Laß nicht die Werke deiner Hände!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Dem Vorsänger. Von David, ein Psalm. Jehova! Du hast mich erforscht und erkannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Du kennst mein Sitzen und mein Aufstehen, du verstehst meine Gedanken von ferne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Du sichtest mein Wandeln und mein Liegen und bist vertraut mit allen meinen Wegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Denn das Wort ist noch nicht auf meiner Zunge, siehe, Jehova, du weißt es ganz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Von hinten und von vorn hast du mich eingeengt, und auf mich gelegt deine Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Kenntnis, zu wunderbar für mich, zu hoch: ich vermag sie nicht zu erfassen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Wohin sollte ich gehen vor deinem Geiste, und wohin fliehen vor deinem Angesicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Führe ich auf zum Himmel, du bist da; und bettete ich mir in dem Scheol, siehe, du bist da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Nähme ich Flügel der Morgenröte, ließe ich mich nieder am äußersten Ende des Meeres,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'auch daselbst würde deine Hand mich leiten, und deine Rechte mich fassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Und spräche ich: Nur Finsternis möge mich umhüllen, und Nacht werde das Licht um mich her:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Auch Finsternis würde vor dir nicht verfinstern, und die Nacht würde leuchten wie der Tag, die Finsternis wäre wie das Licht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Denn du besaßest meine Nieren; du wobest mich in meiner Mutter Leibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Ich preise dich darüber, daß ich auf eine erstaunliche, ausgezeichnete Weise gemacht bin. Wunderbar sind deine Werke, und meine Seele weiß es sehr wohl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Nicht verhohlen war mein Gebein vor dir, als ich gemacht ward im Verborgenen, gewirkt wie ein Stickwerk in den untersten Örtern der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Meinen Keim sahen deine Augen, und in dein Buch waren sie alle eingeschrieben; während vieler Tage wurden sie gebildet, als nicht eines von ihnen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Und wie köstlich sind mir deine Gedanken, o Gott! Wie gewaltig sind ihre Summen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Wollte ich sie zählen, ihrer sind mehr als des Sandes. Ich erwache und bin noch bei dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Möchtest du, o Gott, den Gesetzlosen töten! Und ihr Blutmenschen, weichet von mir!...');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Sie, die dich nennen zum Verbrechen, die zu Eitlem schwören, deine Feinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Hasse ich nicht, Jehova, die dich hassen, und verabscheue ich nicht, die wider dich aufstehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Mit vollkommenem Hasse hasse ich sie; sie sind Feinde für mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Erforsche mich, Gott, und erkenne mein Herz; prüfe mich und erkenne meine Gedanken!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Und sieh, ob ein Weg der Mühsal bei mir ist, und leite mich auf ewigem Wege!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Dem Vorsänger. Ein Psalm von David. Befreie mich, Jehova, von dem bösen Menschen; vor dem Manne der Gewalttaten behüte mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Welche Bosheiten ersinnen im Herzen, täglich Krieg erregen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Sie schärfen ihre Zunge wie eine Schlange; Otterngift ist unter ihren Lippen. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Bewahre mich, Jehova, vor den Händen des Gesetzlosen, vor dem Manne der Gewalttaten behüte mich, welche darauf sinnen, meine Tritte umzustoßen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Die Hoffärtigen haben mir heimlich eine Schlinge und Fallstricke gelegt, ein Netz ausgespannt zur Seite des Weges, sie haben mir Fallen gestellt. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Ich sprach zu Jehova: Du bist mein Gott! Nimm zu Ohren, Jehova, die Stimme meines Flehens!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Jehova, der Herr, ist die Stärke meiner Rettung; du hast mein Haupt beschirmt am Tage der Waffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Gewähre nicht, Jehova, die Gelüste des Gesetzlosen, laß sein Vorhaben nicht gelingen: sie würden sich erheben. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Die Häupter derer, die mich umringen, das Unheil ihrer Lippen bedecke sie!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Mögen feurige Kohlen auf sie herabfallen! Ins Feuer stürze er sie, in Wasserfluten, daß sie nicht aufstehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Der Mann von böser Zunge möge nicht feststehen im Lande; der Mann der Gewalttat, das Böse möge ihn jagen bis zum Sturz!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Ich weiß, daß Jehova ausführen wird die Rechtssache des Elenden, das Recht der Armen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Ja, die Gerechten werden deinen Namen preisen, die Aufrichtigen werden vor deinem Angesicht wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Ein Psalm. Von David. Jehova! Zu dir habe ich gerufen, eile zu mir; nimm zu Ohren meine Stimme, wenn ich zu dir rufe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Laß als Räucherwerk vor dir bestehen mein Gebet, die Erhebung meiner Hände als Abendopfer!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Setze, Jehova, eine Wache meinem Munde; behüte die Tür meiner Lippen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Neige nicht mein Herz zu einer bösen Sache, um in Gesetzlosigkeit Handlungen zu verüben mit Männern, die Frevel tun; und möge ich nicht essen von ihren Leckerbissen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Der Gerechte schlage mich: es ist Güte, und er strafe mich: es ist Öl des Hauptes; nicht wird mein Haupt sich weigern; denn noch ist in ihren Unglücksfällen mein Gebet für sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Sind ihre Richter die Felsen hinabgestürzt worden, so werden sie meine Worte hören, daß sie lieblich sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Wie einer die Erde schneidet und spaltet, so sind unsere Gebeine hingestreut am Rande des Scheols.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Doch auf dich, Jehova, Herr, sind meine Augen gerichtet, auf dich traue ich; gib meine Seele nicht preis!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Bewahre mich vor der Schlinge, die sie mir gelegt haben, und vor den Fallstricken derer, die Frevel tun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Laß die Gesetzlosen in ihre eigenen Netze fallen, während ich vorübergehe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Ein Maskil von David. Ein Gebet, als er in der Höhle war. Mit meiner Stimme schreie ich zu Jehova, mit meiner Stimme flehe ich zu Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Ich schütte meine Klage vor ihm aus, meine Bedrängnis tue ich vor ihm kund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Als mein Geist in mir ermattete, da kanntest du meinen Pfad. Auf dem Wege, den ich wandelte, haben sie mir heimlich eine Schlinge gelegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Schaue zur Rechten, und sieh: ich habe ja niemand, der mich erkennt; verloren ist mir jede Zuflucht, niemand fragt nach meiner Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Zu dir habe ich geschrieen, Jehova! Ich habe gesagt: Du bist meine Zuflucht, mein Teil im Lande der Lebendigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Horche auf mein Schreien, denn ich bin sehr elend; errette mich von meinen Verfolgern, denn sie sind mir zu mächtig!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Führe aus dem Gefängnis heraus meine Seele, damit ich deinen Namen preise! Die Gerechten werden mich umringen, wenn du mir wohlgetan hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Ein Psalm. Von David. Jehova! Höre mein Gebet, nimm zu Ohren mein Flehen; erhöre mich in deiner Treue, in deiner Gerechtigkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Und gehe nicht ins Gericht mit deinem Knechte! Denn vor dir ist kein Lebendiger gerecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Denn der Feind verfolgt meine Seele, zertritt zur Erde mein Leben, macht mich wohnen in Finsternissen gleich den Toten der Urzeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Und mein Geist ermattet in mir, mein Herz ist betäubt in meinem Innern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Ich gedenke der Tage der Vorzeit, überlege all dein Tun; ich sinne über das Werk deiner Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Zu dir breite ich meine Hände aus; gleich einem lechzenden Lande lechzt meine Seele nach dir. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Eilends erhöre mich, Jehova! Es verschmachtet mein Geist. Verbirg dein Angesicht nicht vor mir! Sonst werde ich denen gleich sein, die zur Grube hinabfahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Laß mich früh hören deine Güte, denn auf dich vertraue ich; tue mir kund den Weg, den ich wandeln soll, denn zu dir erhebe ich meine Seele!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Errette mich, Jehova, von meinen Feinden! Zu dir nehme ich meine Zuflucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Lehre mich tun dein Wohlgefallen! Denn du bist mein Gott; dein guter Geist leite mich in ebenem Lande!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Um deines Namens willen, Jehova, belebe mich; in deiner Gerechtigkeit führe meine Seele aus der Bedrängnis!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Und in deiner Güte vertilge meine Feinde, und alle Bedränger meiner Seele bringe um! Denn ich bin dein Knecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Von David. Gepriesen sei Jehova, mein Fels, der meine Hände unterweist zum Kampf, meine Finger zum Kriege:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Meine Güte und meine Burg, meine hohe Feste und mein Erretter; mein Schild und der, auf den ich traue, der mir mein Volk unterwirft!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Jehova, was ist der Mensch, daß du Kenntnis von ihm nimmst, der Sohn des Menschen, daß du ihn beachtest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Der Mensch gleicht dem Hauche; seine Tage sind wie ein vorübergehender Schatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Jehova, neige deine Himmel und fahre hernieder; rühre die Berge an, daß sie rauchen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Blitze mit Blitzen und zerstreue sie; schieße deine Pfeile und verwirre sie!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Strecke deine Hände aus von der Höhe; reiße mich und errette mich aus großen Wassern, aus der Hand der Söhne der Fremde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'deren Mund Eitelkeit redet, und deren Rechte eine Rechte der Lüge ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Gott! Ein neues Lied will ich dir singen, mit der Harfe von zehn Saiten will ich dir Psalmen singen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'dir, der Rettung gibt den Königen, der seinen Knecht David entreißt dem verderblichen Schwerte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Reiße mich und errette mich aus der Hand der Söhne der Fremde, deren Mund Eitelkeit redet, und deren Rechte eine Rechte der Lüge ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'daß unsere Söhne in ihrer Jugend seien gleich hochgezogenen Pflanzen, unsere Töchter gleich behauenen Ecksäulen nach der Bauart eines Palastes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'daß unsere Speicher voll seien, spendend von allerlei Art; daß unser Kleinvieh sich tausendfach mehre, zehntausendfach auf unseren Triften;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'daß unsere Rinder trächtig seien; daß kein Einbruch und kein Ausfall sei und kein Klaggeschrei auf unseren Straßen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Glückselig das Volk, dem also ist! Glückselig das Volk, dessen Gott Jehova ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Ein Lobgesang. Von David. Ich will dich erheben, mein Gott, du König, und deinen Namen preisen immer und ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Jeden Tag will ich dich preisen, und deinen Namen loben immer und ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Groß ist Jehova und sehr zu loben, und seine Größe ist unerforschlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Ein Geschlecht wird dem anderen rühmen deine Werke, und deine Machttaten werden sie verkünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Reden will ich von der herrlichen Pracht deiner Majestät und von deinen Wundertaten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Und sie werden sprechen von der Kraft deiner furchtbaren Taten, und deine Großtaten werde ich erzählen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Das Gedächtnis deiner großen Güte werden sie hervorströmen lassen, und deine Gerechtigkeit jubelnd preisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Gnädig und barmherzig ist Jehova, langsam zum Zorn und groß an Güte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Jehova ist gut gegen alle, und seine Erbarmungen sind über alle seine Werke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Es werden dich loben, Jehova, alle deine Werke, und deine Frommen dich preisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Sie werden sprechen von der Herrlichkeit deines Reiches und werden reden von deiner Macht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'um den Menschenkindern kundzutun seine Machttaten und die prachtvolle Herrlichkeit seines Reiches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Dein Reich ist ein Reich aller Zeitalter, und deine Herrschaft durch alle Geschlechter hindurch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Jehova stützt alle Fallenden und richtet auf alle Niedergebeugten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Aller Augen warten auf dich, und du gibst ihnen ihre Speise zu seiner Zeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Du tust deine Hand auf und sättigst alles Lebendige nach Begehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Jehova ist gerecht in allen seinen Wegen und gütig in allen seinen Taten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Nahe ist Jehova allen, die ihn anrufen, allen, die ihn anrufen in Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Er tut das Verlangen derer, die ihn fürchten; ihr Schreien hört er und rettet sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Jehova bewahrt alle, die ihn lieben, und alle Gesetzlosen vertilgt er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Mein Mund soll das Lob Jehovas aussprechen; und alles Fleisch preise seinen heiligen Namen immer und ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Lobet Jehova! Lobe Jehova, meine Seele!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Loben will ich Jehova mein Leben lang, will Psalmen singen meinem Gott, solange ich bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Vertrauet nicht auf Fürsten, auf einen Menschensohn, bei welchem keine Rettung ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Sein Geist geht aus, er kehrt wieder zu seiner Erde: an selbigem Tage gehen seine Pläne zu Grunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Glückselig der, dessen Hilfe der Gott Jakobs, dessen Hoffnung auf Jehova, seinen Gott, ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Der Himmel und Erde gemacht hat, das Meer und alles, was in ihnen ist; der Wahrheit hält auf ewig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'der Recht schafft den Bedrückten, der Brot gibt den Hungrigen. Jehova löst die Gebundenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Jehova öffnet die Augen der Blinden, Jehova richtet auf die Niedergebeugten, Jehova liebt die Gerechten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Jehova bewahrt die Fremdlinge, die Waise und die Witwe hält er aufrecht; aber er krümmt den Weg der Gesetzlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Jehova wird regieren in Ewigkeit, dein Gott, Zion, von Geschlecht zu Geschlecht. Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Lobet Jehova! Denn es ist gut, unseren Gott zu besingen; denn es ist lieblich, es geziemt sich Lobgesang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Jehova baut Jerusalem, die Vertriebenen Israels sammelt er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Der da heilt, die zerbrochenen Herzens sind, und ihre Wunden verbindet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'der da zählt die Zahl der Sterne, sie alle nennt mit Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Groß ist unser Herr, und groß an Macht; seiner Einsicht ist kein Maß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Jehova hält aufrecht die Elenden; er erniedrigt bis zur Erde die Gesetzlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Stimmet Jehova einen Lobgesang an, singet Psalmen unserem Gott mit der Laute!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Ihm, der die Himmel mit Wolken bedeckt, der Regen bereitet für die Erde, der Gras sprossen läßt auf den Bergen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'der dem Vieh sein Futter gibt, den jungen Raben, die da rufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Er hat nicht Lust an der Stärke des Rosses, noch Gefallen an den Beinen des Mannes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Jehova hat Gefallen an denen, die ihn fürchten, an denen, die auf seine Güte harren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Rühme, Jerusalem, Jehova! Lobe, Zion, deinen Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Denn er hat befestigt die Riegel deiner Tore, hat deine Kinder gesegnet in deiner Mitte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Er, der Frieden stellt in deine Grenzen, dich sättigt mit dem Fette des Weizens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'der seinen Befehl auf die Erde sendet: sehr schnell läuft sein Wort;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'der Schnee gibt wie Wolle, Reif wie Asche streut;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'der sein Eis wirft wie Brocken: wer kann bestehen vor seinem Frost?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Er sendet sein Wort und schmelzt sie; er läßt seinen Wind wehen: es rieseln die Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Er verkündet Jakob sein Wort, Israel seine Satzungen und seine Rechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Keiner Nation hat er also getan; und die Rechte, sie haben sie nicht gekannt. Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Lobet Jehova! Lobet Jehova von den Himmeln her; lobet ihn in den Höhen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Lobet ihn, alle seine Engel; lobet ihn, alle seine Heerscharen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Lobet ihn, Sonne und Mond; lobet ihn, alle ihr leuchtenden Sterne!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Lobet ihn, ihr Himmel der Himmel, und ihr Wasser, die ihr oberhalb der Himmel seid!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Loben sollen sie den Namen Jehovas! Denn er gebot, und sie waren geschaffen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'und er stellte sie hin für immer und ewig; er gab ihnen eine Satzung, und sie werden sie nicht überschreiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Lobet Jehova von der Erde her, ihr Wasserungeheuer und alle Tiefen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Feuer und Hagel, Schnee und Nebel, du Sturmwind, der du ausrichtest sein Wort;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'ihr Berge und alle Hügel, Fruchtbäume und alle Zedern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'wildes Getier und alles Vieh, kriechende Tiere und geflügeltes Gevögel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Ihr Könige der Erde und alle Völkerschaften, ihr Fürsten und alle Richter der Erde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'ihr Jünglinge und auch ihr Jungfrauen, ihr Alten samt den Jungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Loben sollen sie den Namen Jehovas! Denn sein Name ist hoch erhaben, er allein; seine Majestät ist über Erde und Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Und er hat erhöht das Horn seines Volkes, das Lob all seiner Frommen, der Kinder Israel, des Volkes, das ihm nahe ist. Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Lobet Jehova! Singet Jehova ein neues Lied, sein Lob in der Versammlung der Frommen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Israel freue sich seines Schöpfers; die Kinder Zions sollen frohlocken über ihren König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Loben sollen sie seinen Namen mit Reigen, mit Tamburin und Laute ihm Psalmen singen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Denn Jehova hat Wohlgefallen an seinem Volke; er schmückt die Sanftmütigen mit Rettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Es sollen jubeln die Frommen in Herrlichkeit, jauchzen auf ihren Lagern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Lobeserhebungen Gottes seien in ihrer Kehle, und ein zweischneidiges Schwert in ihrer Hand,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'um Rache auszuüben an den Nationen, Bestrafungen an den Völkerschaften;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'ihre Könige zu binden mit Ketten, und ihre Edlen mit eisernen Fesseln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'an ihnen auszuüben das geschriebene Gericht! Das ist die Ehre aller seiner Frommen. Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Lobet Jehova! Lobet Gott in seinem Heiligtum; lobet ihn in der Feste seiner Stärke!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Lobet ihn wegen seiner Machttaten; lobet ihn nach der Fülle seiner Größe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Lobet ihn mit Posaunenschall; lobet ihn mit Harfe und Laute!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Lobet ihn mit Tamburin und Reigen; lobet ihn mit Saitenspiel und Schalmei!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Lobet ihn mit klingenden Zimbeln; lobet ihn mit schallenden Zimbeln!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Alles, was Odem hat, lobe Jah! Lobet Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Sprüche Salomos, des Sohnes Davids, des Königs von Israel:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'um Weisheit und Unterweisung zu kennen, um Worte des Verstandes zu verstehen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'um zu empfangen einsichtsvolle Unterweisung, Gerechtigkeit und Recht und Geradheit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'um Einfältigen Klugheit zu geben, dem Jüngling Erkenntnis und Besonnenheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Der Weise wird hören und an Kenntnis zunehmen, und der Verständige wird sich weisen Rat erwerben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'um einen Spruch zu verstehen und verschlungene Rede, Worte der Weisen und ihre Rätsel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Die Furcht Jehovas ist der Erkenntnis Anfang; die Narren verachten Weisheit und Unterweisung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Höre, mein Sohn, die Unterweisung deines Vaters, und verlaß nicht die Belehrung deiner Mutter!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Denn sie werden ein anmutiger Kranz sein deinem Haupte und ein Geschmeide deinem Halse. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Mein Sohn, wenn Sünder dich locken, so willige nicht ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Wenn sie sagen: Geh mit uns, wir wollen auf Blut lauern, wollen den Unschuldigen nachstellen ohne Ursache;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'wir wollen sie lebendig verschlingen wie der Scheol, und unverletzt, gleich denen, welche plötzlich in die Grube hinabfahren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'wir werden allerlei kostbares Gut erlangen, werden unsere Häuser mit Beute füllen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'du sollst dein Los mitten unter uns werfen, wir alle werden einen Beutel haben:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Mein Sohn, wandle nicht mit ihnen auf dem Wege, halte deinen Fuß zurück von ihrem Pfade;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'denn ihre Füße laufen dem Bösen zu, und sie eilen, Blut zu vergießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Denn vergeblich wird das Netz ausgespannt vor den Augen alles Geflügelten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'sie aber lauern auf ihr eigenes Blut, stellen ihren eigenen Seelen nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'So sind die Pfade aller derer, welche der Habsucht frönen: sie nimmt ihrem eigenen Herrn das Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Die Weisheit schreit draußen, sie läßt auf den Straßen ihre Stimme erschallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Sie ruft an der Ecke lärmender Plätze; an den Eingängen der Tore, in der Stadt redet sie ihre Worte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Bis wann, ihr Einfältigen, wollt ihr Einfältigkeit lieben, und werden Spötter ihre Lust haben an Spott, und Toren Erkenntnis hassen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Wendet euch um zu meiner Zucht! Siehe, ich will euch meinen Geist hervorströmen lassen, will euch kundtun meine Reden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Weil ich gerufen, und ihr euch geweigert habt, meine Hand ausgestreckt, und niemand aufgemerkt hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'und ihr all meinen Rat verworfen, und meine Zucht nicht gewollt habt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'so werde auch ich bei eurem Unglück lachen, werde spotten, wenn euer Schrecken kommt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'wenn euer Schrecken kommt wie ein Unwetter, und euer Unglück hereinbricht wie ein Sturm, wenn Bedrängnis und Angst über euch kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Dann werden sie zu mir rufen, und ich werde nicht antworten; sie werden mich eifrig suchen, und mich nicht finden:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'darum, daß sie Erkenntnis gehaßt und die Furcht Jehovas nicht erwählt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'nicht eingewilligt haben in meinen Rat, verschmäht alle meine Zucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Und sie werden essen von der Frucht ihres Weges, und von ihren Ratschlägen sich sättigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Denn die Abtrünnigkeit der Einfältigen wird sie töten, und die Sorglosigkeit der Toren sie umbringen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'wer aber auf mich hört, wird sicher wohnen, und wird ruhig sein vor des Übels Schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Mein Sohn, wenn du meine Reden annimmst und meine Gebote bei dir verwahrst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'so daß du dein Ohr auf Weisheit merken läßt, dein Herz neigst zum Verständnis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'ja, wenn du dem Verstande rufst, deine Stimme erhebst zum Verständnis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'wenn du ihn suchst wie Silber, und wie nach verborgenen Schätzen ihm nachspürst:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'dann wirst du die Furcht Jehovas verstehen und die Erkenntnis Gottes finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Denn Jehova gibt Weisheit; aus seinem Munde kommen Erkenntnis und Verständnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Er bewahrt klugen Rat auf für die Aufrichtigen, er ist ein Schild denen, die in Vollkommenheit wandeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'indem er die Pfade des Rechts behütet und den Weg seiner Frommen bewahrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Dann wirst du Gerechtigkeit verstehen und Recht und Geradheit, jede Bahn des Guten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Denn Weisheit wird in dein Herz kommen, und Erkenntnis wird deiner Seele lieblich sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Besonnenheit wird über dich wachen, Verständnis dich behüten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'um dich zu erretten von dem bösen Wege, von dem Manne, der Verkehrtes redet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'die da verlassen die Pfade der Geradheit, um auf den Wegen der Finsternis zu wandeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'die sich freuen, Böses zu tun, über boshafte Verkehrtheit frohlocken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'deren Pfade krumm sind, und die abbiegen in ihren Bahnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'um dich zu erretten von dem fremden Weibe, von der Fremden, die ihre Worte glättet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'welche den Vertrauten ihrer Jugend verläßt und den Bund ihres Gottes vergißt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Denn zum Tode sinkt ihr Haus hinab, und ihre Bahnen zu den Schatten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'alle, die zu ihr eingehen, kehren nicht wieder und erreichen nicht die Pfade des Lebens:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Damit du wandelst auf dem Wege der Guten und die Pfade der Gerechten einhältst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Denn die Aufrichtigen werden das Land bewohnen, und die Vollkommenen darin übrigbleiben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'aber die Gesetzlosen werden aus dem Lande ausgerottet, und die Treulosen daraus weggerissen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Mein Sohn, vergiß nicht meine Belehrung, und dein Herz bewahre meine Gebote.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Denn Länge der Tage und Jahre des Lebens und Frieden werden sie dir mehren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Güte und Wahrheit mögen dich nicht verlassen; binde sie um deinen Hals, schreibe sie auf die Tafel deines Herzens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'so wirst du Gunst finden und gute Einsicht in den Augen Gottes und der Menschen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Vertraue auf Jehova mit deinem ganzen Herzen, und stütze dich nicht auf deinen Verstand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Erkenne ihn auf allen deinen Wegen, und er wird gerade machen deine Pfade. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Sei nicht weise in deinen Augen, fürchte Jehova und weiche vom Bösen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'es wird Heilung sein für deinen Nabel und Saft für deine Gebeine. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Ehre Jehova von deinem Vermögen und von den Erstlingen all deines Ertrages;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'so werden deine Speicher sich füllen mit Überfluß, und deine Kufen von Most überfließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Mein Sohn, verwirf nicht die Unterweisung Jehovas, und laß dich seine Zucht nicht verdrießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Denn wen Jehova liebt, den züchtigt er, und zwar wie ein Vater den Sohn, an dem er Wohlgefallen hat. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Glückselig der Mensch, der Weisheit gefunden hat, und der Mensch, der Verständnis erlangt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Denn ihr Erwerb ist besser als der Erwerb von Silber, und ihr Gewinn besser als feines Gold;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'kostbarer ist sie als Korallen, und alles, was du begehren magst, kommt ihr an Wert nicht gleich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Länge des Lebens ist in ihrer Rechten, in ihrer Linken Reichtum und Ehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Ihre Wege sind liebliche Wege, und alle ihre Pfade sind Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Ein Baum des Lebens ist sie denen, die sie ergreifen, und wer sie festhält, ist glückselig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Jehova hat durch Weisheit die Erde gegründet, und durch Einsicht die Himmel festgestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Durch seine Erkenntnis sind hervorgebrochen die Tiefen, und die Wolken träufelten Tau herab. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Mein Sohn, laß sie nicht von deinen Augen weichen, bewahre klugen Rat und Besonnenheit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'so werden sie Leben sein für deine Seele und Anmut deinem Halse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Dann wirst du in Sicherheit deinen Weg gehen, und dein Fuß wird nicht anstoßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Wenn du dich niederlegst, wirst du nicht erschrecken; und liegst du, so wird dein Schlaf süß sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Fürchte dich nicht vor plötzlichem Schrecken, noch vor der Verwüstung der Gesetzlosen, wenn sie kommt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'denn Jehova wird deine Zuversicht sein, und wird deinen Fuß vor dem Fange bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Enthalte kein Gutes dem vor, welchem es zukommt, wenn es in der Macht deiner Hand steht, es zu tun. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Sage nicht zu deinem Nächsten: Geh hin und komm wieder, und morgen will ich geben! da es doch bei dir ist. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Schmiede nichts Böses wider deinen Nächsten, während er vertrauensvoll bei dir wohnt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Hadere nicht mit einem Menschen ohne Ursache, wenn er dir nichts Böses angetan hat. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Beneide nicht den Mann der Gewalttat, und erwähle keinen von seinen Wegen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Denn der Verkehrte ist Jehova ein Greuel, aber sein Geheimnis ist bei den Aufrichtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Der Fluch Jehovas ist im Hause des Gesetzlosen, aber er segnet die Wohnung der Gerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Fürwahr, der Spötter spottet er, den Demütigen aber gibt er Gnade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Die Weisen erben Ehre, aber die Toren erhöht die Schande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Höret, Söhne, die Unterweisung des Vaters, und merket auf, um Verstand zu kennen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Denn gute Lehre gebe ich euch: verlasset meine Belehrung nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Denn ein Sohn bin ich meinem Vater gewesen, ein zarter und einziger vor meiner Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Und er lehrte mich und sprach zu mir: Dein Herz halte meine Worte fest; beobachte meine Gebote und lebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Erwirb Weisheit, erwirb Verstand; vergiß nicht und weiche nicht ab von den Reden meines Mundes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Verlaß sie nicht, und sie wird dich behüten; liebe sie, und sie wird dich bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Der Weisheit Anfang ist: Erwirb Weisheit; und um alles, was du erworben hast, erwirb Verstand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Halte sie hoch, und sie wird dich erhöhen; sie wird dich zu Ehren bringen, wenn du sie umarmst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Sie wird deinem Haupte einen anmutigen Kranz verleihen, wird dir darreichen eine prächtige Krone.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Höre, mein Sohn, und nimm meine Reden an! Und des Lebens Jahre werden sich dir mehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Ich unterweise dich in dem Wege der Weisheit, leite dich auf Bahnen der Geradheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Wenn du gehst, wird dein Schritt nicht beengt werden, und wenn du läufst, wirst du nicht straucheln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Halte fest an der Unterweisung, laß sie nicht los; bewahre sie, denn sie ist dein Leben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Komm nicht auf den Pfad der Gesetzlosen, und schreite nicht einher auf dem Wege der Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Laß ihn fahren, geh nicht darauf; wende dich von ihm ab und geh vorbei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Denn sie schlafen nicht, wenn sie nichts Böses getan, und ihr Schlaf wird ihnen geraubt, wenn sie nicht zu Fall gebracht haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Denn sie essen Brot der Gesetzlosigkeit, und trinken Wein der Gewalttaten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Aber der Pfad der Gerechten ist wie das glänzende Morgenlicht, das stets heller leuchtet bis zur Tageshöhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Der Weg der Gesetzlosen ist dem Dunkel gleich; sie erkennen nicht, worüber sie straucheln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Mein Sohn, merke auf meine Worte, neige dein Ohr zu meinen Reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Laß sie nicht von deinen Augen weichen, bewahre sie im Innern deines Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Denn Leben sind sie denen, die sie finden, und Gesundheit ihrem ganzen Fleische. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Behüte dein Herz mehr als alles, was zu bewahren ist; denn von ihm aus sind die Ausgänge des Lebens. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Tue von dir die Verkehrtheit des Mundes, und die Verdrehtheit der Lippen entferne von dir. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Laß deine Augen geradeaus blicken, und deine Wimpern stracks vor dich hin schauen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Ebne die Bahn deines Fußes, und alle deine Wege seien gerade;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'biege nicht aus zur Rechten noch zur Linken, wende deinen Fuß ab vom Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Mein Sohn, merke auf meine Weisheit, neige dein Ohr zu meiner Einsicht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'um Besonnenheit zu beobachten, und damit deine Lippen Erkenntnis bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Denn Honigseim träufeln die Lippen der Fremden, und glatter als Öl ist ihr Gaumen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'aber ihr Letztes ist bitter wie Wermut, scharf wie ein zweischneidiges Schwert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Ihre Füße steigen hinab zum Tode, an dem Scheol haften ihre Schritte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Damit sie nicht den Weg des Lebens einschlage, schweifen ihre Bahnen, ohne daß sie es weiß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Nun denn, ihr Söhne, höret auf mich, und weichet nicht ab von den Worten meines Mundes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Halte fern von ihr deinen Weg, und nahe nicht zu der Tür ihres Hauses:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'damit du nicht anderen deine Blüte gebest, und deine Jahre dem Grausamen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'damit nicht Fremde sich sättigen an deinem Vermögen, und dein mühsam Erworbenes nicht komme in eines Ausländers Haus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'und du nicht stöhnest bei deinem Ende, wenn dein Fleisch und dein Leib dahinschwinden, und sagest:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'Wie habe ich die Unterweisung gehaßt, und mein Herz hat die Zucht verschmäht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Und ich habe nicht gehört auf die Stimme meiner Unterweiser, und mein Ohr nicht zugeneigt meinen Lehrern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Wenig fehlte, so wäre ich in allem Bösen gewesen, inmitten der Versammlung und der Gemeinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Trinke Wasser aus deiner Zisterne und Fließendes aus deinem Brunnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Mögen nach außen sich ergießen deine Quellen, deine Wasserbäche auf die Straßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Dir allein sollen sie gehören, und nicht Fremden mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Deine Quelle sei gesegnet, und erfreue dich an dem Weibe deiner Jugend;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'die liebliche Hindin und anmutige Gemse, ihre Brüste mögen dich berauschen zu aller Zeit, taumle stets in ihrer Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Und warum solltest du, mein Sohn, an einer Fremden taumeln, und den Busen einer Fremden umarmen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Denn vor den Augen Jehovas sind eines jeden Wege, und alle seine Geleise wägt er ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Die eigenen Missetaten werden ihn, den Gesetzlosen, fangen, und in seiner Sünde Banden wird er festgehalten werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Sterben wird er, weil ihm Zucht mangelt, und in der Größe seiner Torheit wird er dahintaumeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Mein Sohn, wenn du Bürge geworden bist für deinen Nächsten, für einen anderen deine Hand eingeschlagen hast;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'bist du verstrickt durch die Worte deines Mundes, gefangen durch die Worte deines Mundes:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'tue denn dieses, mein Sohn, und reiße dich los, da du in deines Nächsten Hand gekommen bist; geh hin, wirf dich nieder, und bestürme deinen Nächsten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'gestatte deinen Augen keinen Schlaf, und keinen Schlummer deinen Wimpern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'reiße dich los wie eine Gazelle aus der Hand, und wie ein Vogel aus der Hand des Vogelstellers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Geh hin zur Ameise, du Fauler, sieh ihre Wege und werde weise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Sie, die keinen Richter, Vorsteher und Gebieter hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'sie bereitet im Sommer ihr Brot, hat in der Ernte ihre Nahrung eingesammelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Bis wann willst du liegen, du Fauler? Wann willst du von deinem Schlafe aufstehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Ein wenig Schlaf, ein wenig Schlummer, ein wenig Händefalten, um auszuruhen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'und deine Armut wird kommen wie ein rüstig Zuschreitender, und deine Not wie ein gewappneter Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Ein Belialsmensch, ein heilloser Mann ist, wer umhergeht mit Verkehrtheit des Mundes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'mit seinen Augen zwinkt, mit seinen Füßen scharrt, mit seinen Fingern deutet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Verkehrtheiten sind in seinem Herzen; er schmiedet Böses zu aller Zeit, streut Zwietracht aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Darum wird plötzlich sein Verderben kommen; im Augenblick wird er zerschmettert werden ohne Heilung. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Sechs sind es, die Jehova haßt, und sieben sind seiner Seele ein Greuel:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Hohe Augen, eine Lügenzunge, und Hände, die unschuldiges Blut vergießen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'ein Herz, welches heillose Anschläge schmiedet, Füße, die eilends zum Bösen hinlaufen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'wer Lügen ausspricht als falscher Zeuge, und wer Zwietracht ausstreut zwischen Brüdern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Mein Sohn, bewahre das Gebot deines Vaters, und verlaß nicht die Belehrung deiner Mutter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'binde sie stets auf dein Herz, knüpfe sie um deinen Hals.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Wenn du einhergehst, wird sie dich leiten; wenn du dich niederlegst, wird sie über dich wachen; und erwachst du, so wird sie mit dir reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Denn das Gebot ist eine Leuchte, und die Belehrung ein Licht; und die Zurechtweisung der Zucht sind der Weg des Lebens:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'um dich zu bewahren vor dem bösen Weibe, vor der Glätte der Zunge einer Fremden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Begehre nicht in deinem Herzen nach ihrer Schönheit, und sie fange dich nicht mit ihren Wimpern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Denn um eines hurerischen Weibes willen kommt man bis auf einen Laib Brot, und eines Mannes Weib stellt einer kostbaren Seele nach. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Sollte jemand Feuer in seinen Busen nehmen, ohne daß seine Kleider verbrennten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Oder sollte jemand über glühende Kohlen gehen, ohne daß seine Füße versengt würden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'So der, welcher zu dem Weibe seines Nächsten eingeht: keiner, der sie berührt, wird für schuldlos gehalten werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Man verachtet den Dieb nicht, wenn er stiehlt, um seine Gier zu stillen, weil ihn hungert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'und wenn er gefunden wird, kann er siebenfach erstatten, kann alles Gut seines Hauses hingeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Wer mit einem Weibe Ehebruch begeht, ist unsinnig; wer seine Seele verderben will, der tut solches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Plage und Schande wird er finden, und seine Schmach wird nicht ausgelöscht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Denn Eifersucht ist eines Mannes Grimm, und am Tage der Rache schont er nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Er nimmt keine Rücksicht auf irgendwelche Sühne und willigt nicht ein, magst du auch das Geschenk vergrößern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Mein Sohn, bewahre meine Worte, und birg bei dir meine Gebote;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'bewahre meine Gebote und lebe, und meine Belehrung wie deinen Augapfel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Binde sie um deine Finger, schreibe sie auf die Tafel deines Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Sprich zur Weisheit: Du bist meine Schwester! Und nenne den Verstand deinen Verwandten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'damit sie dich bewahre vor dem fremden Weibe, vor der Fremden, die ihre Worte glättet. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Denn an dem Fenster meines Hauses schaute ich durch mein Gitter hinaus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'und ich sah unter den Einfältigen, gewahrte unter den Söhnen einen unverständigen Jüngling,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'der hin und her ging auf der Straße, neben ihrer Ecke, und den Weg nach ihrem Hause schritt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'in der Dämmerung, am Abend des Tages, in der Mitte der Nacht und in der Dunkelheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Und siehe, ein Weib kam ihm entgegen im Anzug einer Hure und mit verstecktem Herzen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Sie ist leidenschaftlich und unbändig, ihre Füße bleiben nicht in ihrem Hause;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'bald ist sie draußen, bald auf den Straßen, und neben jeder Ecke lauert sie. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Und sie ergriff ihn und küßte ihn, und mit unverschämtem Angesicht sprach sie zu ihm:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Friedensopfer lagen mir ob, heute habe ich meine Gelübde bezahlt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'darum bin ich ausgegangen, dir entgegen, um dein Antlitz zu suchen, und dich habe dich gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Mit Teppichen habe ich mein Bett bereitet, mit bunten Decken von ägyptischem Garne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'ich habe mein Lager benetzt mit Myrrhe, Aloe und Zimmet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Komm, wir wollen uns in Liebe berauschen bis an den Morgen, an Liebkosungen uns ergötzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Denn der Mann ist nicht zu Hause, er ist auf eine weite Reise gegangen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'er hat den Geldbeutel in seine Hand genommen, am Tage des Vollmondes wird er heimkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Sie verleitete ihn durch ihr vieles Bereden, riß ihn fort durch die Glätte ihrer Lippen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Auf einmal ging er ihr nach, wie ein Ochs zur Schlachtbank geht, und wie Fußfesseln zur Züchtigung des Narren dienen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'bis ein Pfeil seine Leber zerspaltet; wie ein Vogel zur Schlinge eilt und nicht weiß, daß es sein Leben gilt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Nun denn, ihr Söhne, höret auf mich, und horchet auf die Worte meines Mundes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Dein Herz wende sich nicht ab nach ihren Wegen, und irre nicht umher auf ihren Pfaden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Denn viele Erschlagene hat sie niedergestreckt, und zahlreich sind alle ihre Ermordeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Ihr Haus sind Wege zum Scheol, die hinabführen zu den Kammern des Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Ruft nicht die Weisheit, und läßt nicht die Einsicht ihre Stimme erschallen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Oben auf den Erhöhungen am Wege, da wo Pfade zusammenstoßen, hat sie sich aufgestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Zur Seite der Tore, wo die Stadt sich auftut, am Eingang der Pforten schreit sie:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Zu euch, ihr Männer, rufe ich, und meine Stimme ergeht an die Menschenkinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Lernet Klugheit, ihr Einfältigen, und ihr Toren, lernet Verstand!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Höret! Denn Vortreffliches will ich reden, und das Auftun meiner Lippen soll Geradheit sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Denn mein Gaumen spricht Wahrheit aus, und Gesetzlosigkeit ist meinen Lippen ein Greuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Alle Worte meines Mundes sind in Gerechtigkeit; es ist nichts Verdrehtes und Verkehrtes in ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Sie alle sind richtig dem Verständigen, und gerade denen, die Erkenntnis erlangt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Nehmet an meine Unterweisung, und nicht Silber, und Erkenntnis lieber als auserlesenes, feines Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Denn Weisheit ist besser als Korallen, und alles, was man begehren mag, kommt ihr nicht gleich. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Ich, Weisheit, bewohne die Klugheit, und finde die Erkenntnis der Besonnenheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Die Furcht Jehovas ist: das Böse hassen. Hoffart und Hochmut und den Weg des Bösen und den Mund der Verkehrtheit hasse ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Mein sind Rat und Einsicht; ich bin der Verstand, mein ist die Stärke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Durch mich regieren Könige, und Fürsten treffen gerechte Entscheidungen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'durch mich herrschen Herrscher und Edle, alle Richter der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Ich liebe, die mich lieben; und die mich früh suchen, werden mich finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Reichtum und Ehre sind bei mir, bleibendes Gut und Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Meine Furcht ist besser als feines Gold und gediegenes Gold, und mein Ertrag als auserlesenes Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Ich wandle auf dem Pfade der Gerechtigkeit, mitten auf den Steigen des Rechts;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'um die, die mich lieben, beständiges Gut erben zu lassen, und um ihre Vorratskammern zu füllen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Jehova besaß mich im Anfang seines Weges, vor seinen Werken von jeher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Ich war eingesetzt von Ewigkeit her, von Anbeginn, vor den Uranfängen der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Ich war geboren, als die Tiefen noch nicht waren, als noch keine Quellen waren, reich an Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Ehe die Berge eingesenkt wurden, vor den Hügeln war ich geboren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'als er die Erde und die Fluren noch nicht gemacht hatte, und den Beginn der Schollen des Erdkreises.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Als er die Himmel feststellte, war ich da, als er einen Kreis abmaß über der Fläche der Tiefe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'als er die Wolken droben befestigte, als er Festigkeit gab den Quellen der Tiefe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'als er dem Meere seine Schranken setzte, daß die Wasser seinen Befehl nicht überschritten, als er die Grundfesten der Erde feststellte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'da war ich Schoßkind bei ihm, und war Tag für Tag seine Wonne, vor ihm mich ergötzend allezeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'mich ergötzend auf dem bewohnten Teile seiner Erde; und meine Wonne war bei den Menschenkindern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Nun denn, ihr Söhne, höret auf mich: Glückselig sind, die meine Wege bewahren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Höret Unterweisung und werdet weise, und verwerfet sie nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Glückselig der Mensch, der auf mich hört, indem er an meinen Türen wacht Tag für Tag, die Pfosten meiner Tore hütet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Denn wer mich findet, hat das Leben gefunden und Wohlgefallen erlangt von Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Wer aber an mir sündigt, tut seiner Seele Gewalt an; alle, die mich hassen, lieben den Tod.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Die Weisheit hat ihr Haus gebaut, hat ihre sieben Säulen ausgehauen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'sie hat ihr Schlachtvieh geschlachtet, ihren Wein gemischt, auch ihren Tisch gedeckt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'sie hat ihre Mägde ausgesandt, ladet ein auf den Höhen der Stadt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '\"Wer ist einfältig? Er wende sich hierher!\" Zu den Unverständigen spricht sie:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '\"Kommet, esset von meinem Brote, und trinket von dem Weine, den ich gemischt habe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Lasset ab von der Einfältigkeit und lebet, und schreitet einher auf dem Wege des Verstandes!\" -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Wer den Spötter zurechtweist, zieht sich Schande zu; und wer den Gesetzlosen straft, sein Schandfleck ist es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Strafe den Spötter nicht, daß er dich nicht hasse; strafe den Weisen, und er wird dich lieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Gib dem Weisen, so wird er noch weiser; belehre den Gerechten, so wird er an Kenntnis zunehmen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Die Furcht Jehovas ist der Weisheit Anfang; und die Erkenntnis des Heiligen ist Verstand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Denn durch mich werden deine Tage sich mehren, und Jahre des Lebens werden dir hinzugefügt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Wenn du weise bist, so bist du weise für dich; und spottest du, so wirst du allein es tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Frau Torheit ist leidenschaftlich; sie ist lauter Einfältigkeit und weiß gar nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Und sie sitzt am Eingang ihres Hauses, auf einem Sitze an hochgelegenen Stellen der Stadt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'um einzuladen, die des Weges vorübergehen, die ihre Pfade gerade halten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '\"Wer ist einfältig? Er wende sich hierher!\" Und zu dem Unverständigen spricht sie:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '\"Gestohlene Wasser sind süß, und heimliches Brot ist lieblich\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Und er weiß nicht, daß dort die Schatten sind, in den Tiefen des Scheols ihre Geladenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Ein weiser Sohn erfreut den Vater, aber ein törichter Sohn ist seiner Mutter Kummer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Schätze der Gesetzlosigkeit nützen nichts, aber Gerechtigkeit errettet vom Tode.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Jehova läßt die Seele des Gerechten nicht hungern, aber die Gier der Gesetzlosen stößt er hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Wer mit lässiger Hand schafft, wird arm; aber die Hand der Fleißigen macht reich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Wer im Sommer einsammelt, ist ein einsichtsvoller Sohn; wer zur Erntezeit in tiefem Schlafe liegt, ist ein Sohn, der Schande bringt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Dem Haupte des Gerechten werden Segnungen zuteil, aber den Mund der Gesetzlosen bedeckt Gewalttat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Das Gedächtnis des Gerechten ist zum Segen, aber der Name der Gesetzlosen verwest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Wer weisen Herzens ist, nimmt Gebote an; aber ein närrischer Schwätzer kommt zu Fall.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Wer in Vollkommenheit wandelt, wandelt sicher; wer aber seine Wege krümmt, wird bekannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Wer mit den Augen zwinkt, verursacht Kränkung; und ein närrischer Schwätzer kommt zu Fall.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Ein Born des Lebens ist der Mund des Gerechten, aber den Mund der Gesetzlosen bedeckt Gewalttat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Haß erregt Zwietracht, aber Liebe deckt alle Übertretungen zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Auf den Lippen des Verständigen wird Weisheit gefunden; aber der Stock gebührt dem Rücken des Unverständigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Die Weisen bewahren Erkenntnis auf, aber der Mund des Narren ist drohender Unglücksfall.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Der Wohlstand des Reichen ist seine feste Stadt, der Unglücksfall der Geringen ihre Armut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Der Erwerb des Gerechten gereicht zum Leben, der Ertrag des Gesetzlosen zur Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Es ist der Pfad zum Leben, wenn einer Unterweisung beachtet; wer aber Zucht unbeachtet läßt, geht irre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Wer Haß verbirgt, hat Lügenlippen; und wer Verleumdung ausbringt, ist ein Tor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Bei der Menge der Worte fehlt Übertretung nicht; wer aber seine Lippen zurückhält, ist einsichtsvoll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Die Zunge des Gerechten ist auserlesenes Silber, der Verstand der Gesetzlosen ist wenig wert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Die Lippen des Gerechten weiden viele, aber die Narren sterben durch Mangel an Verstand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Der Segen Jehovas, er macht reich, und Anstrengung fügt neben ihm nichts hinzu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Dem Toren ist es wie ein Spiel, Schandtat zu verüben, und Weisheit zu üben dem verständigen Manne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Wovor dem Gesetzlosen bangt, das wird über ihn kommen, und das Begehren der Gerechten wird gewährt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Wie ein Sturmwind daherfährt, so ist der Gesetzlose nicht mehr; aber der Gerechte ist ein ewig fester Grund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Wie der Essig den Zähnen, und wie der Rauch den Augen, so ist der Faule denen, die ihn senden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Die Furcht Jehovas mehrt die Tage, aber die Jahre der Gesetzlosen werden verkürzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Das Harren der Gerechten wird Freude, aber die Hoffnung der Gesetzlosen wird zunichte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Der Weg Jehovas ist eine Feste für die Vollkommenheit, aber Untergang für die, welche Frevel tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Der Gerechte wird nicht wanken in Ewigkeit, aber die Gesetzlosen werden das Land nicht bewohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Der Mund des Gerechten sproßt Weisheit, aber die Zunge der Verkehrtheit wird ausgerottet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Die Lippen des Gerechten verstehen sich auf Wohlgefälliges, aber der Mund der Gesetzlosen ist Verkehrtheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Trügerische Waagschalen sind Jehova ein Greuel, aber volles Gewicht ist sein Wohlgefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Kommt Übermut, so kommt auch Schande; bei den Bescheidenen aber ist Weisheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Die Unsträflichkeit der Aufrichtigen leitet sie, aber Treulosen Verkehrtheit zerstört sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Vermögen nützt nichts am Tage des Zornes, aber Gerechtigkeit errettet vom Tode.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Des Vollkommenen Gerechtigkeit macht seinen Weg gerade, aber der Gesetzlose fällt durch seine Gesetzlosigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Der Aufrichtigen Gerechtigkeit errettet sie, aber die Treulosen werden gefangen in ihrer Gier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Wenn ein gesetzloser Mensch stirbt, wird seine Hoffnung zunichte, und die Erwartung der Frevler ist zunichte geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Der Gerechte wird aus der Drangsal befreit, und der Gesetzlose tritt an seine Stelle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Mit dem Munde verdirbt der Ruchlose seinen Nächsten, aber durch Erkenntnis werden die Gerechten befreit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Die Stadt frohlockt beim Wohle der Gerechten, und beim Untergang der Gesetzlosen ist Jubel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Durch den Segen der Aufrichtigen kommt eine Stadt empor, aber durch den Mund der Gesetzlosen wird sie niedergerissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Wer seinen Nächsten verachtet, hat keinen Verstand; aber ein verständiger Mann schweigt still.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Wer als Verleumder umhergeht, deckt das Geheimnis auf; wer aber treuen Geistes ist, deckt die Sache zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Wo keine Führung ist, verfällt ein Volk; aber Heil ist bei der Menge der Ratgeber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Sehr schlecht ergeht\'s einem, wenn er für einen anderen Bürge geworden ist; wer aber das Handeinschlagen haßt, ist sicher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Ein anmutiges Weib erlangt Ehre, und Gewalttätige erlangen Reichtum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Sich selbst tut der Mildtätige wohl, der Unbarmherzige aber tut seinem Fleische wehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Der Gesetzlose schafft sich trüglichen Gewinn, wer aber Gerechtigkeit sät, wahrhaftigen Lohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Wie die Gerechtigkeit zum Leben, so gereicht es dem, der Bösem nachjagt, zu seinem Tode.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Die verkehrten Herzens sind, sind Jehova ein Greuel; aber sein Wohlgefallen sind die im Wege Vollkommenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Die Hand darauf! Der Böse wird nicht für schuldlos gehalten werden; aber der Same der Gerechten wird entrinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Ein goldener Ring in der Nase eines Schweines, so ist ein schönes Weib ohne Anstand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Das Begehren der Gerechten ist nur Gutes; die Hoffnung der Gesetzlosen ist der Grimm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Da ist einer, der ausstreut, und er bekommt noch mehr; und einer, der mehr spart als recht ist, und es ist nur zum Mangel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Die segnende Seele wird reichlich gesättigt, und der Tränkende wird auch selbst getränkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Wer Korn zurückhält, den verflucht das Volk; aber Segen wird dem Haupte dessen zuteil, der Getreide verkauft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Wer das Gute eifrig sucht, sucht Wohlgefallen; wer aber nach Bösem trachtet, über ihn wird es kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Wer auf seinen Reichtum vertraut, der wird fallen; aber die Gerechten werden sprossen wie Laub.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Wer sein Haus verstört, wird Wind erben; und der Narr wird ein Knecht dessen, der weisen Herzens ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Die Frucht des Gerechten ist ein Baum des Lebens, und der Weise gewinnt Seelen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Siehe, dem Gerechten wird auf Erden vergolten, wieviel mehr dem Gesetzlosen und Sünder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Wer Unterweisung liebt, liebt Erkenntnis; und wer Zucht haßt, ist dumm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Der Gütige erlangt Wohlgefallen von Jehova, aber den Mann der Ränke spricht er schuldig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Ein Mensch wird nicht bestehen durch Gesetzlosigkeit, aber die Wurzel der Gerechten wird nicht erschüttert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Ein wackeres Weib ist ihres Mannes Krone, aber wie Fäulnis in seinen Gebeinen ist ein schändliches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Die Gedanken der Gerechten sind Recht, die Überlegungen der Gesetzlosen sind Betrug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Die Worte der Gesetzlosen sind ein Lauern auf Blut; aber der Mund der Aufrichtigen errettet sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Man kehrt die Gesetzlosen um, und sie sind nicht mehr; aber das Haus der Gerechten bleibt bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Gemäß seiner Einsicht wird ein Mann gelobt; wer aber verkehrten Herzens ist, wird zur Verachtung sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Besser, wer gering ist und einen Knecht hat, als wer vornehm tut und hat Mangel an Brot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Der Gerechte kümmert sich um das Leben seines Viehes, aber das Herz der Gesetzlosen ist grausam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Wer sein Land bebaut, wird mit Brot gesättigt werden; wer aber nichtigen Dingen nachjagt, ist unverständig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Den Gesetzlosen gelüstete nach dem Raube der Bösen, aber die Wurzel der Gerechten trägt ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'In der Übertretung der Lippen ist ein böser Fallstrick, aber der Gerechte entgeht der Drangsal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Von der Frucht seines Mundes wird ein Mann mit Gutem gesättigt, und das Tun der Hände eines Menschen kehrt zu ihm zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Der Weg des Narren ist richtig in seinen Augen, aber der Weise hört auf Rat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Der Unmut des Narren tut sich am selben Tage kund, aber der Kluge verbirgt den Schimpf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Wer Wahrheit ausspricht, tut Gerechtigkeit kund, aber ein falscher Zeuge Trug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Da ist einer, der unbesonnene Worte redet gleich Schwertstichen; aber die Zunge der Weisen ist Heilung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Die Lippe der Wahrheit besteht ewiglich, aber nur einen Augenblick die Zunge der Lüge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Trug ist im Herzen derer, die Böses schmieden; bei denen aber, die Frieden planen, ist Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Dem Gerechten wird keinerlei Unheil widerfahren, aber die Gesetzlosen haben Übel die Fülle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Die Lippen der Lüge sind Jehova ein Greuel, die aber, welche Wahrheit üben, sein Wohlgefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Ein kluger Mensch hält die Erkenntnis verborgen, aber das Herz der Toren ruft Narrheit aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Die Hand der Fleißigen wird herrschen, aber die lässige wird fronpflichtig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Kummer im Herzen des Mannes beugt es nieder, aber ein gutes Wort erfreut es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Der Gerechte weist seinem Nächsten den Weg, aber der Weg der Gesetzlosen führt sie irre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Nicht erjagt der Lässige sein Wild; aber kostbares Gut eines Menschen ist es, wenn er fleißig ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Auf dem Pfade der Gerechtigkeit ist Leben, und kein Tod auf dem Wege ihres Steiges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Ein weiser Sohn hört auf die Unterweisung des Vaters, aber ein Spötter hört nicht auf Schelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Von der Frucht seines Mundes ißt ein Mann Gutes, aber die Seele der Treulosen ißt Gewalttat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Wer seinen Mund bewahrt, behütet seine Seele; wer seine Lippen aufreißt, dem wird\'s zum Untergang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Die Seele des Faulen begehrt, und nichts ist da; aber die Seele der Fleißigen wird reichlich gesättigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Der Gerechte haßt Lügenrede, aber der Gesetzlose handelt schändlich und schmählich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Die Gerechtigkeit behütet den im Wege Vollkommenen, und die Gesetzlosigkeit kehrt den Sünder um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Da ist einer, der sich reich stellt und hat gar nichts, und einer, der sich arm stellt und hat viel Vermögen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Lösegeld für das Leben eines Mannes ist sein Reichtum, aber der Arme hört keine Drohung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Das Licht der Gerechten brennt fröhlich, aber die Leuchte der Gesetzlosen erlischt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Durch Übermut gibt es nur Zank; bei denen aber, die sich raten lassen, Weisheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Vermögen, das auf nichtige Weise erworben ist, vermindert sich; wer aber allmählich sammelt, vermehrt es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Lang hingezogenes Harren macht das Herz krank, aber ein eingetroffener Wunsch ist ein Baum des Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Wer das Wort verachtet, wird von ihm gepfändet; wer aber das Gebot fürchtet, dem wird vergolten werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Die Belehrung des Weisen ist ein Born des Lebens, um zu entgehen den Fallstricken des Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Gute Einsicht verschafft Gunst, aber der Treulosen Weg ist hart.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Jeder Kluge handelt mit Bedacht; ein Tor aber breitet Narrheit aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Ein gottloser Bote fällt in Unglück, aber ein treuer Gesandter ist Gesundheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Armut und Schande dem, der Unterweisung verwirft; wer aber Zucht beachtet wird geehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Ein erfülltes Begehren ist der Seele süß, und den Toren ist\'s ein Greuel, vom Bösen zu weichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Wer mit Weisen umgeht, wird weise; aber wer sich zu Toren gesellt, wird schlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Das Böse verfolgt die Sünder, aber den Gerechten wird man mit Gutem vergelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Der Gute vererbt auf Kindeskinder, aber des Sünders Reichtum ist aufbewahrt für den Gerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Der Neubruch der Armen gibt viel Speise, aber mancher geht zu Grunde durch Unrechtlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Wer seine Rute spart, haßt seinen Sohn, aber wer ihn lieb hat, sucht ihn früh heim mit Züchtigung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Der Gerechte ißt bis zur Sättigung seiner Seele, aber der Leib der Gesetzlosen muß darben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Der Weiber Weisheit baut ihr Haus, und ihre Narrheit reißt es mit eigenen Händen nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Wer in seiner Geradheit wandelt, fürchtet Jehova; wer aber in seinen Wegen verkehrt ist, verachtet ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Im Munde des Narren ist eine Gerte des Hochmuts; aber die Lippen der Weisen, sie bewahren sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Wo keine Rinder sind, ist die Krippe rein; aber viel Ertrag ist durch des Stieres Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Ein treuer Zeuge lügt nicht, aber ein falscher Zeuge spricht Lügen aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Der Spötter sucht Weisheit, und sie ist nicht da; aber für den Verständigen ist Erkenntnis leicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Geh hinweg von einem törichten Manne und bei wem du nicht Lippen der Erkenntnis merkst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Die Weisheit des Klugen ist, auf seinen Weg zu merken, und die Narrheit der Toren ist Betrug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Die Schuld spottet der Narren, aber unter den Aufrichtigen ist Wohlwollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Das Herz kennt seine eigene Bitterkeit, und kein Fremder kann sich in seine Freude mischen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Das Haus der Gesetzlosen wird vertilgt werden, aber das Zelt der Aufrichtigen wird emporblühen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Da ist der Weg, der einem Menschen gerade erscheint, aber sein Ende sind Wege des Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Auch beim Lachen hat das Herz Kummer, und ihr, der Freude, Ende ist Traurigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Von seinen Wegen wird gesättigt, wer abtrünnigen Herzens ist, und von dem, was in ihm ist, der gute Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Der Einfältige glaubt jedem Worte, aber der Kluge merkt auf seine Schritte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Der Weise fürchtet sich und meidet das Böse, aber der Tor braust auf und ist sorglos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Der Jähzornige begeht Narrheit, und der Mann von Ränken wird gehaßt. gekrönt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Die Einfältigen erben Narrheit, die Klugen aber werden mit Erkenntnis gekrönt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Die Bösen beugen sich vor den Guten, und die Gesetzlosen stehen an den Toren des Gerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Selbst von seinem Nächsten wird der Arme gehaßt; aber derer, die den Reichen lieben, sind viele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Wer seinen Nächsten verachtet, sündigt; wer aber der Elenden sich erbarmt, ist glücklich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Werden nicht irregehen, die Böses schmieden, aber Güte und Wahrheit finden, die Gutes schmieden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Bei jeder Mühe wird Gewinn sein, aber Lippengerede gereicht nur zum Mangel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Der Weisen Krone ist ihr Reichtum; die Narrheit der Toren ist Narrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Ein wahrhaftiger Zeuge errettet Seelen; wer aber Lügen ausspricht, ist lauter Trug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'In der Furcht Jehovas ist ein starkes Vertrauen, und seine Kinder haben eine Zuflucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Die Furcht Jehovas ist ein Born des Lebens, um zu entgehen den Fallstricken des Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'In der Menge des Volkes ist die Herrlichkeit eines Königs, aber im Schwinden der Bevölkerung eines Fürsten Untergang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Ein Langmütiger hat viel Verstand, aber ein Jähzorniger erhöht die Narrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Ein gelassenes Herz ist des Leibes Leben, aber Ereiferung ist Fäulnis der Gebeine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Wer den Armen bedrückt, verhöhnt den, der ihn gemacht hat; wer aber des Dürftigen sich erbarmt, ehrt ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'In seinem Unglück wird der Gesetzlose umgestoßen, aber der Gerechte vertraut auch in seinem Tode.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Die Weisheit ruht im Herzen des Verständigen; aber was im Inneren der Toren ist, tut sich kund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Gerechtigkeit erhöht eine Nation, aber Sünde ist der Völker Schande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Des Königs Gunst wird dem einsichtigen Knechte zuteil; aber der Schändliche wird Gegenstand seines Grimmes sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Eine gelinde Antwort wendet den Grimm ab, aber ein kränkendes Wort erregt den Zorn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Die Zunge der Weisen spricht tüchtiges Wissen aus, aber der Mund der Toren sprudelt Narrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Die Augen Jehovas sind an jedem Orte, schauen aus auf Böse und auf Gute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Lindigkeit der Zunge ist ein Baum des Lebens, aber Verkehrtheit in ihr ist eine Verwundung des Geistes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Ein Narr verschmäht die Unterweisung seines Vaters; wer aber die Zucht beachtet, ist klug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Das Haus des Gerechten ist eine große Schatzkammer; aber im Einkommen des Gesetzlosen ist Zerrüttung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Die Lippen der Weisen streuen Erkenntnis aus, aber nicht also das Herz der Toren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Das Opfer der Gesetzlosen ist Jehova ein Greuel, aber das Gebet der Aufrichtigen sein Wohlgefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Der Weg des Gesetzlosen ist Jehova ein Greuel; wer aber der Gerechtigkeit nachjagt, den liebt er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Schlimme Züchtigung wird dem zuteil, der den Pfad verläßt; wer Zucht haßt, wird sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Scheol und Abgrund sind vor Jehova, wieviel mehr die Herzen der Menschenkinder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Der Spötter liebt es nicht, daß man ihn zurechtweise; zu den Weisen geht er nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Ein frohes Herz erheitert das Antlitz; aber bei Kummer des Herzens ist der Geist zerschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Des Verständigen Herz sucht Erkenntnis, aber der Mund der Toren weidet sich an Narrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Alle Tage des Elenden sind böse, aber ein fröhliches Herz ist ein beständiges Festmahl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Besser wenig mit der Furcht Jehovas, als ein großer Schatz und Unruhe dabei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Besser ein Gericht Gemüse und Liebe dabei, als ein gemästeter Ochs und Haß dabei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Ein zorniger Mann erregt Zank, aber ein Langmütiger beschwichtigt den Streit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Der Weg des Faulen ist wie eine Dornhecke, aber der Pfad der Aufrichtigen ist gebahnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Ein weiser Sohn erfreut den Vater, aber ein törichter Mensch verachtet seine Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Die Narrheit ist dem Unverständigen Freude, aber ein verständiger Mann wandelt geradeaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Pläne scheitern, wo keine Besprechung ist; aber durch viele Ratgeber kommen sie zustande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Ein Mann hat Freude an der Antwort seines Mundes; und ein Wort zu seiner Zeit, wie gut!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Der Weg des Lebens ist für den Einsichtigen aufwärts, damit er dem Scheol unten entgehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Das Haus der Hoffärtigen reißt Jehova nieder, aber der Witwe Grenze stellt er fest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Böse Anschläge sind Jehova ein Greuel, aber huldvolle Worte sind rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Wer der Habsucht frönt, verstört sein Haus; wer aber Geschenke haßt, wird leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Das Herz des Gerechten überlegt, um zu antworten; aber der Mund der Gesetzlosen sprudelt Bosheiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Jehova ist fern von den Gesetzlosen, aber das Gebet der Gerechten hört er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Das Leuchten der Augen erfreut das Herz; eine gute Nachricht labt das Gebein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Ein Ohr, das auf die Zucht zum Leben hört, wird inmitten der Weisen weilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Wer Unterweisung verwirft, verachtet seine Seele; wer aber auf Zucht hört, erwirbt Verstand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Die Furcht Jehovas ist Unterweisung zur Weisheit, und der Ehre geht Demut voraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Die Entwürfe des Herzens sind des Menschen, aber die Antwort der Zunge kommt von Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Alle Wege eines Mannes sind rein in seinen Augen, aber Jehova wägt die Geister.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Befiehl Jehova deine Werke, und deine Gedanken werden zustande kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Jehova hat alles zu seiner Absicht gemacht, und auch den Gesetzlosen für den Tag des Unglücks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Jeder Hochmütige ist Jehova ein Greuel; die Hand darauf! Er wird nicht für schuldlos gehalten werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Durch Güte und Wahrheit wird die Missetat gesühnt, und durch die Furcht Jehovas weicht man vom Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Wenn eines Mannes Wege Jehova wohlgefallen, so läßt er selbst seine Feinde mit ihm in Frieden sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Besser wenig mit Gerechtigkeit, als viel Einkommen mit Unrechtlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Das Herz des Menschen erdenkt seinen Weg, aber Jehova lenkt seine Schritte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Ein Orakelspruch ist auf den Lippen des Königs: sein Mund vergeht sich nicht am Recht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Gerechte Waage und Waagschalen sind Jehovas; sein Werk sind alle Gewichtsteine des Beutels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Der Könige Greuel ist, Gesetzlosigkeit zu tun; denn durch Gerechtigkeit steht ein Thron fest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Der Könige Wohlgefallen sind gerechte Lippen; und wer Aufrichtiges redet, den liebt er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Des Königs Grimm gleicht Todesboten; aber ein weiser Mann versöhnt ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Im Lichte des Angesichts des Königs ist Leben, und sein Wohlgefallen ist wie eine Wolke des Spätregens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Weisheit erwerben, wieviel besser ist es als feines Gold, und Verstand erwerben, wieviel vorzüglicher als Silber!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Der Aufrichtigen Straße ist: vom Bösen weichen; wer seinen Weg bewahrt, behütet seine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Hoffart geht dem Sturze, und Hochmut dem Falle voraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Besser niedrigen Geistes sein mit den Demütigen, als Raub teilen mit den Hoffärtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Wer auf das Wort achtet, wird Gutes erlangen; und wer auf Jehova vertraut, ist glückselig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Wer weisen Herzens ist, wird verständig genannt; und Süßigkeit der Lippen mehrt die Lehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Einsicht ist für ihre Besitzer ein Born des Lebens, aber die Züchtigung der Narren ist die Narrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Das Herz des Weisen gibt seinem Munde Einsicht und mehrt auf seinen Lippen die Lehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Huldvolle Worte sind eine Honigwabe, Süßes für die Seele und Gesundheit für das Gebein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Da ist ein Weg, der einem Menschen gerade erscheint, aber sein Ende sind Wege des Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Des Arbeiters Hunger arbeitet für ihn, denn sein Mund spornt ihn an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Ein Belialsmann gräbt nach Bösem, und auf seinen Lippen ist es wie brennendes Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Ein verkehrter Mann streut Zwietracht aus, und ein Ohrenbläser entzweit Vertraute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Ein Mann der Gewalttat verlockt seinen Nächsten und führt ihn auf einen Weg, der nicht gut ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Wer seine Augen zudrückt, um Verkehrtes zu ersinnen, seine Lippen zusammenkneift, hat das Böse beschlossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Das graue Haar ist eine prächtige Krone: auf dem Wege der Gerechtigkeit wird sie gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Besser ein Langmütiger als ein Held, und wer seinen Geist beherrscht, als wer eine Stadt erobert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Das Los wird in dem Busen geworfen, aber all seine Entscheidung kommt von Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Besser ein trockener Bissen und Friede dabei, als ein Haus voll Opferfleisch mit Zank.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Ein einsichtiger Knecht wird über den schändlichen Sohn herrschen, und inmitten der Brüder die Erbschaft teilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Der Schmelztiegel für das Silber, und der Ofen für das Gold; aber Prüfer der Herzen ist Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Ein Übeltäter horcht auf die Lippe des Unheils, ein Lügner gibt Gehör der Zunge des Verderbens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Wer des Armen spottet, verhöhnt den, der ihn gemacht hat; wer über Unglück sich freut, wird nicht für schuldlos gehalten werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Kindeskinder sind die Krone der Alten, und der Kinder Schmuck sind ihre Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Vortreffliche Rede schickt sich nicht für einen gemeinen Menschen; wieviel weniger Lügenrede für einen Edlen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Das Geschenk ist ein Edelstein in den Augen des Empfängers; wohin er sich wendet, gelingt es ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Wer Liebe sucht, deckt die Übertretung zu; wer aber eine Sache immer wieder anregt, entzweit Vertraute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Ein Verweis dringt bei einem Verständigen tiefer ein, als hundert Schläge bei einem Toren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Der Böse sucht nur Empörung; aber ein grausamer Bote wird gegen ihn gesandt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Eine Bärin, die der Jungen beraubt ist, begegne einem Manne, aber nicht ein Tor in seiner Narrheit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Wer Böses für Gutes vergilt, von dessen Hause wird das Böse nicht weichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Der Anfang eines Zankes ist, wie wenn einer Wasser entfesselt; so laß den Streit, ehe er heftig wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Wer den Gesetzlosen rechtfertigt, und wer den Gerechten verdammt, sie alle beide sind Jehova ein Greuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Wozu doch Geld in der Hand eines Toren, um Weisheit zu kaufen, da ihm doch der Verstand fehlt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Der Freund liebt zu aller Zeit, und als Bruder für die Drangsal wird er geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Ein unverständiger Mensch ist, wer in die Hand einschlägt, wer Bürgschaft leistet gegenüber seinem Nächsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Wer Zank liebt, liebt Übertretung; wer seine Tür hoch macht, sucht Einsturz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Wer verkehrten Herzens ist, wird das Gute nicht finden; und wer sich mit seiner Zunge windet, wird ins Unglück fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Wer einen Toren zeugt, dem wird es zum Kummer, und der Vater eines Narren hat keine Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Ein fröhliches Herz bringt gute Besserung, aber ein zerschlagener Geist vertrocknet das Gebein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Der Gesetzlose nimmt ein Geschenk aus dem Busen, um die Pfade des Rechts zu beugen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Vor dem Angesicht des Verständigen ist Weisheit, aber die Augen des Toren sind am Ende der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Ein törichter Sohn ist ein Gram für seinen Vater, und Bitterkeit für die, welche ihn geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Auch den Gerechten zu bestrafen, ist nicht gut, Edle zu schlagen um der Geradheit willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Wer seine Worte zurückhält, besitzt Erkenntnis; und wer kühlen Geistes ist, ist ein verständiger Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Auch ein Narr, der schweigt, wird für weise gehalten, für verständig, wer seine Lippen verschließt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Wer sich absondert, trachtet nach einem Gelüst; gegen alle Einsicht geht er heftig an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Der Tor hat keine Lust an Verständnis, sondern nur daran, daß sein Herz sich offenbare.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Wenn ein Gesetzloser kommt, so kommt auch Verachtung; und mit der Schande kommt Schmähung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Die Worte aus dem Munde eines Mannes sind tiefe Wasser, ein sprudelnder Bach, ein Born der Weisheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Es ist nicht gut, die Person des Gesetzlosen anzusehen, um den Gerechten zu beugen im Gericht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Die Lippen des Toren geraten in Streit, und sein Mund ruft nach Schlägen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Der Mund des Toren wird ihm zum Untergang, und seine Lippen sind der Fallstrick seiner Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Die Worte des Ohrenbläsers sind wie Leckerbissen, und sie dringen hinab in das Innerste des Leibes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Auch wer sich lässig zeigt in seiner Arbeit, ist ein Bruder des Verderbers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Der Name Jehovas ist ein starker Turm; der Gerechte läuft dahin und ist in Sicherheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Das Vermögen des Reichen ist seine feste Stadt, und in seiner Einbildung gleich einer hochragenden Mauer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Vor dem Sturze wird hoffärtig des Mannes Herz, und der Ehre geht Demut voraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Wer Antwort gibt, bevor er anhört, dem ist es Narrheit und Schande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Eines Mannes Geist erträgt seine Krankheit; aber ein zerschlagener Geist, wer richtet ihn auf?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Das Herz des Verständigen erwirbt Erkenntnis, und das Ohr der Weisen sucht nach Erkenntnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Das Geschenk des Menschen macht ihm Raum und verschafft ihm Zutritt zu den Großen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Der erste in seiner Streitsache hat recht; doch sein Nächster kommt und forscht ihn aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Das Los schlichtet Zwistigkeiten und bringt Mächtige auseinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Ein Bruder, an dem man treulos gehandelt hat, widersteht mehr als eine feste Stadt; und Zwistigkeiten sind wie der Riegel einer Burg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Von der Frucht des Mundes eines Mannes wird sein Inneres gesättigt, vom Ertrage seiner Lippen wird er gesättigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Tod und Leben sind in der Gewalt der Zunge, und wer sie liebt, wird ihre Frucht essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Wer ein Weib gefunden, hat Gutes gefunden und hat Wohlgefallen erlangt von Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Flehentlich bittet der Arme, aber der Reiche antwortet Hartes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Ein Mann vieler Freunde wird zu Grunde gehen; doch es gibt einen, der liebt und anhänglicher ist als ein Bruder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Besser ein Armer, der in seiner Vollkommenheit wandelt, als wer verkehrter Lippen und dabei ein Tor ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Auch Unkenntnis der Seele ist nicht gut; und wer mit den Füßen hastig ist, tritt fehl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Die Narrheit des Menschen verdirbt seinen Weg, und sein Herz grollt wider Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Reichtum verschafft viele Freunde; aber der Arme, sein Freund trennt sich von ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Ein falscher Zeuge wird nicht für schuldlos gehalten werden; und wer Lügen ausspricht, wird nicht entrinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Viele schmeicheln einem Edlen, und alle sind Freunde des Mannes, der Geschenke gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Alle Brüder des Armen hassen ihn; wieviel mehr entfernen sich von ihm seine Freunde! Er jagt Worten nach, die nichts sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Wer Verstand erwirbt, liebt seine Seele; wer auf Verständnis achtet, wird Glück erlangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Ein falscher Zeuge wird nicht für schuldlos gehalten werden, und wer Lügen ausspricht, wird umkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Nicht geziemt einem Toren Wohlleben; wieviel weniger einem Knechte, über Fürsten zu herrschen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Die Einsicht eines Menschen macht ihn langmütig, und sein Ruhm ist es, Vergehung zu übersehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Des Königs Zorn ist wie das Knurren eines jungen Löwen, aber sein Wohlgefallen wie Tau auf das Gras.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Ein törichter Sohn ist Verderben für seinen Vater; und die Zänkereien eines Weibes sind eine beständige Traufe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Haus und Gut sind ein Erbteil der Väter, aber eine einsichtsvolle Frau kommt von Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Faulheit versenkt in tiefen Schlaf, und eine lässige Seele wird hungern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Wer das Gebot bewahrt, bewahrt seine Seele; wer seine Wege verachtet, wird sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Wer des Armen sich erbarmt, leiht Jehova; und er wird ihm seine Wohltat vergelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Züchtige deinen Sohn, weil noch Hoffnung da ist; aber trachte nicht danach, ihn zu töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Wer jähzornig ist, muß dafür büßen; denn greifst du auch ein, so machst du\'s nur noch schlimmer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Höre auf Rat und nimm Unterweisung an, damit du weise seiest in der Zukunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Viele Gedanken sind in dem Herzen eines Mannes; aber der Ratschluß Jehovas, er kommt zustande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Die Willigkeit des Menschen macht seine Mildtätigkeit aus, und besser ein Armer als ein lügnerischer Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Die Furcht Jehovas ist zum Leben; und gesättigt verbringt man die Nacht, wird nicht heimgesucht vom Übel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Hat der Faule seine Hand in die Schüssel gesteckt, nicht einmal zu seinem Munde bringt er sie zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Schlägst du den Spötter, so wird der Einfältige klug; und weist man den Verständigen zurecht, so wird er Erkenntnis verstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Wer den Vater zu Grunde richtet, die Mutter verjagt, ist ein Sohn, der Schande und Schmach bringt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Laß ab, mein Sohn, auf Unterweisung zu hören, die abirren macht von den Worten der Erkenntnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Ein Belialszeuge spottet des Rechts, und der Mund der Gesetzlosen verschlingt Unheil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Für die Spötter sind Gerichte bereit, und Schläge für den Rücken der Toren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Der Wein ist ein Spötter, starkes Getränk ein Lärmer; und jeder, der davon taumelt, wird nicht weise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Des Königs Schrecken ist wie das Knurren eines jungen Löwen; wer ihn gegen sich aufbringt, verwirkt sein Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Ehre ist es dem Manne, vom Streite abzustehen; wer ein Narr ist, stürzt sich hinein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Wegen des Winters mag der Faule nicht pflügen; zur Erntezeit wird er begehren, und nichts ist da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Tiefes Wasser ist der Ratschluß im Herzen des Mannes, aber ein verständiger Mann schöpft ihn heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Die meisten Menschen rufen ein jeder seine Güte aus; aber einen zuverlässigen Mann, wer wird ihn finden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Wer in seiner Vollkommenheit gerecht wandelt, glückselig sind seine Kinder nach ihm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Ein König, der auf dem Throne des Gerichts sitzt, zerstreut alles Böse mit seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Wer darf sagen: Ich habe mein Herz gereinigt, ich bin rein geworden von meiner Sünde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Zweierlei Gewichtsteine, zweierlei Epha, sie alle beide sind Jehova ein Greuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Selbst ein Knabe gibt sich durch seine Handlungen zu erkennen, ob sein Tun lauter, und ob es aufrichtig ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Das hörende Ohr und das sehende Auge, Jehova hat sie alle beide gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Liebe nicht den Schlaf, damit du nicht verarmest; tue deine Augen auf, so wirst du satt Brot haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Schlecht, schlecht! spricht der Käufer; und wenn er weggeht, dann rühmt er sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Es gibt Gold und Korallen die Menge; aber ein kostbares Gerät sind Lippen der Erkenntnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Nimm ihm das Kleid, denn er ist für einen anderen Bürge geworden; und der Fremden halber pfände ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Das Brot der Falschheit ist einem Manne süß, aber hernach wird sein Mund voll Kies.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Pläne kommen durch Beratung zustande, und mit weiser Überlegung führe Krieg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Wer als Verleumder umhergeht, enthüllt das Geheimnis; und mit dem, der seine Lippen aufsperrt, laß dich nicht ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Wer seinem Vater oder seiner Mutter flucht, dessen Leuchte wird erlöschen in tiefster Finsternis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Ein Erbe, das hastig erlangt wird im Anfang, dessen Ende wird nicht gesegnet sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Sprich nicht: Ich will Böses vergelten. Harre auf Jehova, so wird er dich retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Zweierlei Gewichtsteine sind Jehova ein Greuel, und trügerische Waagschalen sind nicht gut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Des Mannes Schritte hängen ab von Jehova; und der Mensch, wie sollte er seinen Weg verstehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Ein Fallstrick des Menschen ist es, vorschnell zu sprechen: Geheiligt! und nach den Gelübden zu überlegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Ein weiser König zerstreut die Gesetzlosen und führt das Dreschrad über sie hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Der Geist des Menschen ist eine Leuchte Jehovas, durchforschend alle Kammern des Leibes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Güte und Wahrheit behüten den König, und durch Güte stützt er seinen Thron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Der Schmuck der Jünglinge ist ihre Kraft, und graues Haar die Zierde der Alten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Wundstriemen scheuern das Böse weg, und Schläge scheuern die Kammern des Leibes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Gleich Wasserbächen ist eines Königs Herz in der Hand Jehovas; wohin immer er will, neigt er es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Jeder Weg eines Mannes ist gerade in seinen Augen, aber Jehova wägt die Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Gerechtigkeit und Recht üben ist Jehova angenehmer als Opfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Stolz der Augen und Hochmut des Herzens, die Leuchte der Gesetzlosen, sind Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Die Gedanken des Fleißigen führen nur zum Überfluß; und jeder, der hastig ist, es ist nur zum Mangel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Erwerb von Schätzen durch Lügenzunge ist verwehender Dunst; solche suchen den Tod.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Die Gewalttätigkeit der Gesetzlosen rafft sie hinweg, denn Recht zu üben weigern sie sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Vielgewunden ist der Weg des schuldbeladenen Mannes; der Lautere aber, sein Tun ist gerade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Besser ist es, auf einer Dachecke zu wohnen, als ein zänkisches Weib und ein gemeinsames Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Die Seele des Gesetzlosen begehrt das Böse: sein Nächster findet keine Gnade in seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Wenn man den Spötter bestraft, so wird der Einfältige weise; und wenn man den Weisen belehrt, so nimmt er Erkenntnis an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Ein Gerechter hat acht auf das Haus des Gesetzlosen, er stürzt die Gesetzlosen ins Unglück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Wer sein Ohr verstopft vor dem Schrei des Armen, auch er wird rufen und nicht erhört werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Eine Gabe im Verborgenen wendet den Zorn ab, und ein Geschenk im Busen den heftigen Grimm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Dem Gerechten ist es Freude, Recht zu üben; aber denen, die Frevel tun, ein Schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Ein Mensch, der von dem Wege der Einsicht abirrt, wird ruhen in der Versammlung der Schatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Wer Freude liebt, wird ein Mann des Mangels werden; wer Wein und Öl liebt, wird nicht reich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Der Gesetzlose ist ein Lösegeld für den Gerechten, und der Treulose tritt an die Stelle der Aufrichtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Besser ist es, in einem wüsten Lande zu wohnen, als ein zänkisches Weib und Ärger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Ein kostbarer Schatz und Öl ist in der Wohnung des Weisen, aber ein törichter Mensch verschlingt es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Wer der Gerechtigkeit und der Güte nachjagt, wird Leben finden, Gerechtigkeit und Ehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Der Weise ersteigt die Stadt der Helden und stürzt nieder die Feste ihres Vertrauens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Wer seinen Mund und seine Zunge bewahrt, bewahrt vor Drangsalen seine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Der Übermütige, Stolze, Spötter ist sein Name, handelt mit vermessenem Übermut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Die Begierde des Faulen tötet ihn, denn seine Hände weigern sich zu arbeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Den ganzen Tag begehrt und begehrt man, aber der Gerechte gibt und hält nicht zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Das Opfer der Gesetzlosen ist ein Greuel; wieviel mehr, wenn er es in böser Absicht bringt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Ein Lügenzeuge wird umkommen; ein Mann aber, welcher hört, darf immerdar reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Ein gesetzloser Mann zeigt ein trotziges Gesicht; aber der Aufrichtige, er merkt auf seinen Weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Da ist keine Weisheit und keine Einsicht und kein Rat gegenüber Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Das Roß wird gerüstet für den Tag des Streites, aber die Rettung ist Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Ein guter Name ist vorzüglicher als großer Reichtum, Anmut besser als Silber und Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Reiche und Arme begegnen sich: Jehova hat sie alle gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Der Kluge sieht das Unglück und verbirgt sich; die Einfältigen aber gehen weiter und leiden Strafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Die Folge der Demut, der Furcht Jehovas, ist Reichtum und Ehre und Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Dornen, Schlingen sind auf dem Wege des Verkehrten; wer seine Seele bewahrt, hält sich fern von ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Erziehe den Knaben seinem Wege gemäß; er wird nicht davon weichen, auch wenn er alt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Der Reiche herrscht über den Armen, und der Borgende ist ein Knecht des Leihenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Wer Unrecht sät, wird Unheil ernten, und seines Zornes Rute wird ein Ende nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Wer gütigen Auges ist, der wird gesegnet werden; denn er gibt von seinem Brote dem Armen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Treibe den Spötter fort, so geht der Zank hinaus, und Streit und Schande hören auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Wer Reinheit des Herzens liebt, wessen Lippen Anmut sind, dessen Freund ist der König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Die Augen Jehovas behüten die Erkenntnis, und er vereitelt die Worte des Treulosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Der Faule spricht: Ein Löwe ist draußen; ich möchte ermordet werden mitten auf den Straßen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Der Mund fremder Weiber ist eine tiefe Grube; wem Jehova zürnt, der fällt hinein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Narrheit ist gekettet an das Herz des Knaben; die Rute der Zucht wird sie davon entfernen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Wer den Armen bedrückt, ihm zur Bereicherung ist es; wer dem Reichen gibt, es ist nur zum Mangel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Neige dein Ohr und höre die Worte der Weisen, und richte dein Herz auf mein Wissen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Denn lieblich ist es, wenn du sie in deinem Innern bewahrst; möchten sie allzumal auf deinen Lippen Bestand haben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Damit dein Vertrauen auf Jehova sei, habe ich heute dich, ja dich, belehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Habe ich dir nicht Vortreffliches aufgeschrieben an Ratschlägen und Erkenntnis,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'um dir kundzutun die Richtschnur der Worte der Wahrheit: damit du denen, die dich senden, Worte zurückbringest, welche Wahrheit sind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Beraube nicht den Armen, weil er arm ist, und zertritt nicht den Elenden im Tore.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Denn Jehova wird ihre Rechtssache führen, und ihre Berauber des Lebens berauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Geselle dich nicht zu einem Zornigen, und geh nicht um mit einem hitzigen Manne,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'damit du seine Pfade nicht lernest und einen Fallstrick davontragest für deine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Sei nicht unter denen, die in die Hand einschlagen, unter denen, welche für Darlehn Bürgschaft leisten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Wenn du nicht hast, um zu bezahlen, warum soll er dein Bett unter dir wegnehmen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Verrücke nicht die alte Grenze, welche deine Väter gemacht haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Siehst du einen Mann, der gewandt ist in seinem Geschäft, vor Königen wird er stehen, er wird nicht vor Niedrigen stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Wenn du dich hinsetzest, um mit einem Herrscher zu speisen, so beachte wohl, wen du vor dir hast;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'und setze ein Messer an deine Kehle, wenn du gierig bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Laß dich nicht gelüsten nach seinen Leckerbissen, denn sie sind eine trügliche Speise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Bemühe dich nicht, reich zu werden, laß ab von deiner Klugheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Willst du deine Augen darauf hinfliegen lassen, und siehe, fort ist es? Denn sicherlich schafft es sich Flügel gleich dem Adler, der gen Himmel fliegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Iß nicht das Brot des Scheelsehenden, und laß dich nicht gelüsten nach seinen Leckerbissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Denn wie er es abmißt in seiner Seele, so ist er. \"Iß und trink!\", spricht er zu dir, aber sein Herz ist nicht mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Deinen Bissen, den du gegessen hast, mußt du ausspeien, und deine freundlichen Worte wirst du verlieren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Rede nicht zu den Ohren eines Toren, denn er wird die Einsicht deiner Worte verachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Verrücke nicht die alte Grenze, und dringe nicht ein in die Felder der Waisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Denn ihr Erlöser ist stark; er wird ihren Rechtsstreit wider dich führen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Bringe dein Herz her zur Unterweisung, und deine Ohren zu den Worten der Erkenntnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Entziehe dem Knaben nicht die Züchtigung; wenn du ihn mit der Rute schlägst, wird er nicht sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Du schlägst ihn mit der Rute, und du errettest seine Seele von dem Scheol.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Mein Sohn, wenn dein Herz weise ist, so wird auch mein Herz sich freuen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'und meine Nieren werden frohlocken, wenn deine Lippen Geradheit reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Dein Herz beneide nicht die Sünder, sondern beeifere sich jeden Tag um die Furcht Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Wahrlich, es gibt ein Ende, und deine Hoffnung wird nicht vernichtet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Höre du, mein Sohn, und werde weise, und leite dein Herz geradeaus auf dem Wege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Sei nicht unter Weinsäufern, noch unter denen, die Fleisch verprassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'denn ein Säufer und ein Schlemmer verarmen, und Schlummer kleidet in Lumpen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Höre auf deinen Vater, der dich gezeugt hat, und verachte deine Mutter nicht, wenn sie alt geworden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Kaufe Wahrheit und verkaufe sie nicht, Weisheit und Unterweisung und Verstand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Hoch frohlockt der Vater eines Gerechten; und wer einen Weisen gezeugt hat, der freut sich seiner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Freuen mögen sich dein Vater und deine Mutter, und frohlocken, die dich geboren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Gib mir, mein Sohn, dein Herz, und laß deine Augen Gefallen haben an meinen Wegen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Denn die Hure ist eine tiefe Grube und die Fremde ein enger Brunnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'ja, sie lauert auf wie ein Räuber, und sie mehrt die Treulosen unter den Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Wer hat Ach, wer hat Weh, wer Zänkereien, wer Klage, wer Wunden ohne Ursache? Wer Trübung der Augen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Die spät beim Weine sitzen, die einkehren, um Mischtrank zu kosten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Sieh den Wein nicht an, wenn er sich rot zeigt, wenn er im Becher blinkt, leicht hinuntergleitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Sein Ende ist, daß er beißt wie eine Schlange und sticht wie ein Basilisk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Deine Augen werden Seltsames sehen, und dein Herz wird verkehrte Dinge reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Und du wirst sein wie einer, der im Herzen des Meeres liegt, und wie einer, der da liegt auf der Spitze eines Mastes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, '\"Man hat mich geschlagen, es schmerzte mich nicht; man hat mich geprügelt, ich fühlte es nicht. Wann werde ich aufwachen? Ich will es wieder tun, will ihn abermals aufsuchen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Beneide nicht böse Menschen, und laß dich nicht gelüsten, mit ihnen zu sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'denn ihr Herz sinnt auf Gewalttat, und ihre Lippen reden Mühsal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Durch Weisheit wird ein Haus gebaut, und durch Verstand wird es befestigt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'und durch Erkenntnis füllen sich die Kammern mit allerlei kostbarem und lieblichem Gut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Ein weiser Mann ist stark, und ein Mann von Erkenntnis befestigt seine Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Denn mit weiser Überlegung wirst du glücklich Krieg führen, und bei der Ratgeber Menge ist Heil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Weisheit ist dem Narren zu hoch, im Tore tut er seinen Mund nicht auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Wer darauf sinnt, Böses zu tun, den nennt man einen Ränkeschmied.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Das Vorhaben der Narrheit ist die Sünde, und der Spötter ist den Menschen ein Greuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Zeigst du dich schlaff am Tage der Drangsal, so ist deine Kraft gering.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Errette, die zum Tode geschleppt werden, und die zur Würgung hinwanken, o halte sie zurück!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Wenn du sprichst: Siehe, wir wußten nichts davon, wird nicht er, der die Herzen wägt, es merken? Und er, der auf deine Seele achthat, es wissen? Und er wird dem Menschen vergelten nach seinem Tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Iß Honig, mein Sohn, denn er ist gut, und Honigseim ist deinem Gaumen süß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Ebenso betrachte die Weisheit für deine Seele: wenn du sie gefunden hast, so gibt es eine Zukunft, und deine Hoffnung wird nicht vernichtet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Laure nicht, Gesetzloser, auf die Wohnung des Gerechten, zerstöre nicht seine Lagerstätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Denn der Gerechte fällt siebenmal und steht wieder auf, aber die Gesetzlosen stürzen nieder im Unglück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Freue dich nicht über den Fall deines Feindes, und dein Herz frohlocke nicht über seinen Sturz:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'damit Jehova es nicht sehe, und es böse sei in seinen Augen, und er seinen Zorn von ihm abwende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Erzürne dich nicht über die Übeltäter, beneide nicht die Gesetzlosen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'denn für den Bösen wird keine Zukunft sein, die Leuchte der Gesetzlosen wird erlöschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Mein Sohn, fürchte Jehova und den König; mit Aufrührern laß dich nicht ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Denn plötzlich erhebt sich ihr Verderben; und ihrer beider Untergang, wer weiß ihn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Auch diese sind von den Weisen: Die Person ansehen im Gericht ist nicht gut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Wer zu dem Gesetzlosen spricht: Du bist gerecht, den verfluchen die Völker, den verwünschen die Völkerschaften;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'denen aber, welche gerecht entscheiden, geht es wohl, und über sie kommt Segnung des Guten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Die Lippen küßt, wer richtige Antwort gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Besorge draußen deine Arbeit und bestelle sie dir auf dem Felde; hernach magst du dann dein Haus bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Werde nicht ohne Ursache Zeuge wider deinen Nächsten; wolltest du denn täuschen mit deinen Lippen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Sprich nicht: Wie er mir getan hat, so will ich ihm tun, will dem Manne vergelten nach seinem Werke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'An dem Acker eines faulen Mannes kam ich vorüber, und an dem Weinberge eines unverständigen Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'Und siehe, er war ganz mit Disteln überwachsen, seine Fläche war mit Brennesseln bedeckt, und seine steinerne Mauer eingerissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Und ich schaute es, ich richtete mein Herz darauf; ich sah es, empfing Unterweisung:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Ein wenig Schlaf, ein wenig Schlummer, ein wenig Händefalten, um auszuruhen-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'und deine Armut kommt herangeschritten, und deine Not wie ein gewappneter Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Auch diese sind Sprüche Salomos, welche die Männer Hiskias, des Königs von Juda, zusammengetragen haben:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Gottes Ehre ist es, eine Sache zu verbergen, aber der Könige Ehre, eine Sache zu erforschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Der Himmel an Höhe, und die Erde an Tiefe, und das Herz der Könige sind unerforschlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Man entferne die Schlacken von dem Silber, so geht für den Goldschmied ein Gerät hervor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Man entferne den Gesetzlosen vor dem König, so wird sein Thron feststehen durch Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Brüste dich nicht vor dem König, und stelle dich nicht an den Platz der Großen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Denn besser ist es, daß man dir sage: Komm hier herauf, als daß man dich erniedrige vor dem Edlen, den deine Augen doch gesehen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Geh nicht eilig aus zu einem Streithandel, damit am Ende davon nicht fraglich werde, was du zu tun hast, wenn dein Nächster dich beschämt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Führe deinen Streithandel mit deinem Nächsten, aber enthülle nicht das Geheimnis eines anderen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'damit dich nicht schmähe, wer es hört, und dein übler Ruf nicht mehr weiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Goldene Äpfel in silbernen Prunkgeräten: so ist ein Wort, geredet zu seiner Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Ein goldener Ohrring und ein Halsgeschmeide von feinem Golde: so ist ein weiser Tadler für ein hörendes Ohr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Wie Kühlung des Schnees an einem Erntetage ist ein treuer Bote denen, die ihn senden: er erquickt die Seele seines Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Wolken und Wind, und kein Regen: so ist ein Mann, welcher mit trügerischem Geschenke prahlt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Ein Richter wird überredet durch Langmut, und eine gelinde Zunge zerbricht Knochen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Hast du Honig gefunden, so iß dein Genüge, damit du seiner nicht satt werdest und ihn ausspeiest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Mache deinen Fuß selten im Hause deines Nächsten, damit er deiner nicht satt werde und dich hasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Hammer und Schwert und geschärfter Pfeil: so ist ein Mann, der wider seinen Nächsten falsches Zeugnis ablegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Ein zerbrochener Zahn und ein wankender Fuß: so ist das Vertrauen auf einen Treulosen am Tage der Drangsal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Einer, der das Oberkleid ablegt am Tage der Kälte, Essig auf Natron: so, wer einem traurigen Herzen Lieder singt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Wenn deinen Hasser hungert, speise ihn mit Brot, und wenn ihn dürstet, tränke ihn mit Wasser;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'denn glühende Kohlen wirst du auf sein Haupt häufen, und Jehova wird dir vergelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Nordwind gebiert Regen, und eine heimliche Zunge verdrießliche Gesichter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Besser auf einer Dachecke wohnen, als ein zänkisches Weib und ein gemeinsames Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Frisches Wasser auf eine lechzende Seele: so eine gute Nachricht aus fernem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Getrübter Quell und verderbter Brunnen: so ist der Gerechte, der vor dem Gesetzlosen wankt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Viel Honig essen ist nicht gut, aber schwere Dinge erforschen ist Ehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Eine erbrochene Stadt ohne Mauer: so ist ein Mann, dessen Geist Beherrschung mangelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Wie Schnee im Sommer und wie Regen in der Ernte, so ist Ehre dem Toren nicht geziemend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Wie der Sperling hin und her flattert, wie die Schwalbe wegfliegt, so ein unverdienter Fluch: er trifft nicht ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Die Peitsche dem Pferde, der Zaum dem Esel, und der Stock dem Rücken der Toren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Antworte dem Toren nicht nach seiner Narrheit, damit nicht auch du ihm gleich werdest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Antworte dem Toren nach seiner Narrheit, damit er nicht weise sei in seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Die Füße haut sich ab, Unbill trinkt, wer Bestellungen ausrichten läßt durch einen Toren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Schlaff hängen die Beine des Lahmen herab: so ein Spruch im Munde der Toren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Wie das Binden eines Steines in eine Schleuder: so, wer einem Toren Ehre erweist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Ein Dorn, der in die Hand eines Trunkenen gerät: so ein Spruch im Munde der Toren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Ein Schütze, der alles verwundet: so, wer den Toren dingt und die Vorübergehenden dingt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Wie ein Hund, der zurückkehrt zu seinem Gespei: so ist ein Tor, der seine Narrheit wiederholt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Siehst du einen Mann, der in seinen Augen weise ist, für einen Toren ist mehr Hoffnung als für ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Der Faule spricht: Der Brüller ist auf dem Wege, ein Löwe inmitten der Straßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Die Tür dreht sich in ihrer Angel: so der Faule auf seinem Bette.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Hat der Faule seine Hand in die Schüssel gesteckt, beschwerlich wird es ihm, sie zu seinem Munde zurückzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Der Faule ist weiser in seinen Augen als sieben, die verständig antworten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Der ergreift einen Hund bei den Ohren, wer vorbeigehend sich über einen Streit ereifert, der ihn nichts angeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Wie ein Wahnsinniger, der Brandgeschosse, Pfeile und Tod schleudert:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'so ein Mann, der seinen Nächsten betrügt und spricht: Habe ich nicht Scherz getrieben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Wo es an Holz fehlt, erlischt das Feuer; und wo kein Ohrenbläser ist, hört der Zank auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Kohle zur Glut und Holz zum Feuer, und ein zänkischer Mann zum Schüren des Streites.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Die Worte des Ohrenbläsers sind wie Leckerbissen, und sie dringen hinab in das Innerste des Leibes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Ein irdenes Geschirr, mit Schlackensilber überzogen: so sind feurige Lippen und ein böses Herz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Der Hasser verstellt sich mit seinen Lippen, aber in seinem Innern hegt er Trug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Wenn er seine Stimme holdselig macht, traue ihm nicht; denn sieben Greuel sind in seinem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Versteckt sich der Haß in Trug, seine Bosheit wird sich in der Versammlung enthüllen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Wer eine Grube gräbt, fällt hinein; und wer einen Stein wälzt, auf den kehrt er zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Eine Lügenzunge haßt diejenigen, welche sie zermalmt; und ein glatter Mund bereitet Sturz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Rühme dich nicht des morgenden Tages, denn du weißt nicht, was ein Tag gebiert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Es rühme dich ein anderer und nicht dein Mund, ein Fremder und nicht deine Lippen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Schwer ist der Stein, und der Sand eine Last; aber der Unmut des Narren ist schwerer als beide.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Grimm ist grausam, und Zorn eine überströmende Flut; wer aber kann bestehen vor der Eifersucht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Besser offener Tadel als verhehlte Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Treugemeint sind die Wunden dessen, der liebt, und überreichlich des Hassers Küsse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Eine satte Seele zertritt Honigseim; aber einer hungrigen Seele ist alles Bittere süß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Wie ein Vogel, der fern von seinem Neste schweift: so ein Mann, der fern von seinem Wohnorte schweift.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Öl und Räucherwerk erfreuen das Herz, und die Süßigkeit eines Freundes kommt aus dem Rate der Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Verlaß nicht deinen Freund und deines Vaters Freund, und geh nicht am Tage deiner Not in deines Bruders Haus: besser ein naher Nachbar als ein ferner Bruder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Sei weise, mein Sohn, und erfreue mein Herz, damit ich Antwort geben könne meinem Schmäher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Der Kluge sieht das Unglück und verbirgt sich; die Einfältigen gehen weiter und leiden Strafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Nimm ihm das Kleid, denn er ist für einen anderen Bürge geworden; und der Fremden halber pfände ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Wer frühmorgens aufsteht und seinem Nächsten mit lauter Stimme Glück wünscht, als Verwünschung wird es ihm angerechnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Eine beständige Traufe am Tage des strömenden Regens und ein zänkisches Weib gleichen sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Wer dieses zurückhält, hält den Wind zurück und seine Rechte greift in Öl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Eisen wird scharf durch Eisen, und ein Mann schärft das Angesicht des anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Wer des Feigenbaumes wartet, wird seine Frucht essen; und wer über seinen Herrn wacht, wird geehrt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Wie im Wasser das Angesicht dem Angesicht entspricht, so das Herz des Menschen dem Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Scheol und Abgrund sind unersättlich: so sind unersättlich die Augen des Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Der Schmelztiegel für das Silber, und der Ofen für das Gold; und ein Mann nach Maßgabe seines Lobes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Wenn du den Narren mit der Keule im Mörser zerstießest, mitten unter der Grütze, so würde seine Narrheit doch nicht von ihm weichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Bekümmere dich wohl um das Aussehen deines Kleinviehes, richte deine Aufmerksamkeit auf die Herden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Denn Wohlstand ist nicht ewig; und währt eine Krone von Geschlecht zu Geschlecht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Ist geschwunden das Heu, und erscheint das junge Gras, und sind eingesammelt die Kräuter der Berge,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'so dienen Schafe zu deiner Kleidung, und der Kaufpreis für ein Feld sind Böcke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'und genug Ziegenmilch ist da zu deiner Nahrung, zur Nahrung deines Hauses, und Lebensunterhalt für deine Mägde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Die Gesetzlosen fliehen, obgleich kein Verfolger da ist; die Gerechten aber sind getrost gleich einem jungen Löwen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Durch die Frevelhaftigkeit eines Landes werden seiner Fürsten viele; aber durch einen verständigen, einsichtigen Mann wird sein Bestand verlängert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Ein armer Mann, der Geringe bedrückt, ist ein Regen, der hinwegschwemmt und kein Brot bringt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Die das Gesetz verlassen, rühmen die Gesetzlosen; die aber das Gesetz beobachten, entrüsten sich über sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Böse Menschen verstehen das Recht nicht; die aber Jehova suchen, verstehen alles.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Besser ein Armer, der in seiner Vollkommenheit wandelt, als ein Verkehrter, der auf zwei Wegen geht und dabei reich ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Ein verständiger Sohn bewahrt das Gesetz; wer sich aber zu Schlemmern gesellt, macht seinem Vater Schande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Wer sein Vermögen durch Zins und durch Wucher mehrt, sammelt es für den, der sich der Armen erbarmt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Wer sein Ohr abwendet vom Hören des Gesetzes: selbst sein Gebet ist ein Greuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Wer Aufrichtige irreführt auf bösen Weg, wird selbst in seine Grube fallen; aber die Vollkommenen werden Gutes erben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Ein reicher Mann ist weise in seinen Augen, aber ein verständiger Armer durchschaut ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Wenn die Gerechten frohlocken, ist die Pracht groß; wenn aber die Gesetzlosen emporkommen, verstecken sich die Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Wer seine Übertretungen verbirgt, wird kein Gelingen haben; wer sie aber bekennt und läßt, wird Barmherzigkeit erlangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Glückselig der Mensch, der sich beständig fürchtet; wer aber sein Herz verhärtet, wird ins Unglück fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Ein brüllender Löwe und ein gieriger Bär: so ist ein gesetzloser Herrscher über ein armes Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Du Fürst, ohne Verstand und reich an Erpressungen! Wer unrechtmäßigen Gewinn haßt, wird seine Tage verlängern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Ein Mensch, belastet mit dem Blute einer Seele, flieht bis zur Grube: man unterstütze ihn nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Wer vollkommen wandelt, wird gerettet werden; wer aber verkehrt auf zwei Wegen geht, wird auf einmal fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Wer sein Land bebaut, wird mit Brot gesättigt werden; wer aber nichtigen Dingen nachjagt, wird mit Armut gesättigt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Ein treuer Mann hat viel Segen; wer aber hastig ist, reich zu werden, wird nicht schuldlos sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Die Person ansehen ist nicht gut, und um einen Bissen Brot kann ein Mann übertreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Ein scheelsehender Mann hascht nach Reichtum, und er erkennt nicht, daß Mangel über ihn kommen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Wer einen Menschen straft, wird hernach mehr Gunst finden, als wer mit der Zunge schmeichelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Wer seinen Vater und seine Mutter beraubt und spricht: Kein Frevel ist es! der ist ein Genosse des Verderbers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Der Habgierige erregt Zank; wer aber auf Jehova vertraut, wird reichlich gesättigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Wer auf sein Herz vertraut, der ist ein Tor; wer aber in Weisheit wandelt, der wird entrinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Wer dem Armen gibt, wird keinen Mangel haben; wer aber seine Augen verhüllt, wird mit Flüchen überhäuft werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Wenn die Gesetzlosen emporkommen, verbergen sich die Menschen; und wenn sie umkommen, mehren sich die Gerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Ein Mann, der, oft zurechtgewiesen, den Nacken verhärtet, wird plötzlich zerschmettert werden ohne Heilung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Wenn die Gerechten sich mehren, freut sich das Volk; wenn aber ein Gesetzloser herrscht, seufzt ein Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Ein Mann, der Weisheit liebt, erfreut seinen Vater; wer sich aber zu Huren gesellt, richtet das Vermögen zu Grunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Ein König gibt durch Recht dem Lande Bestand; aber ein Mann, der Geschenke liebt, bringt es herunter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Ein Mann, der seinem Nächsten schmeichelt, breitet ein Netz aus vor seine Tritte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'In der Übertretung des bösen Mannes ist ein Fallstrick; aber der Gerechte jubelt und ist fröhlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Der Gerechte erkennt das Recht der Armen; der Gesetzlose versteht keine Erkenntnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Spötter versetzen eine Stadt in Aufruhr, Weise aber wenden den Zorn ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Wenn ein weiser Mann mit einem närrischen Manne rechtet, mag er sich erzürnen oder lachen, er hat keine Ruhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Blutmenschen hassen den Unsträflichen, aber die Aufrichtigen bekümmern sich um seine Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Der Tor läßt seinen ganzen Unmut herausfahren, aber der Weise hält ihn beschwichtigend zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Ein Herrscher, der auf Lügenrede horcht, dessen Diener sind alle gesetzlos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Der Arme und der Bedrücker begegnen sich: Jehova erleuchtet ihrer beider Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Ein König, der die Geringen in Wahrheit richtet, dessen Thron wird feststehen immerdar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Rute und Zucht geben Weisheit; aber ein sich selbst überlassener Knabe macht seiner Mutter Schande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Wenn die Gesetzlosen sich mehren, mehrt sich die Übertretung; aber die Gerechten werden ihrem Falle zusehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Züchtige deinen Sohn, so wird er dir Ruhe verschaffen und Wonne gewähren deiner Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Wenn kein Gesicht da ist, wird ein Volk zügellos; aber glückselig ist es, wenn es das Gesetz beobachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Durch Worte wird ein Knecht nicht zurechtgewiesen; denn er versteht, aber er folgt nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Siehst du einen Mann, der hastig ist in seinen Worten, für einen Toren ist mehr Hoffnung als für ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Wenn einer seinen Knecht von Jugend auf verhätschelt, so wird dieser am Ende zum Sohne werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Ein zorniger Mann erregt Zank, und ein Hitziger ist reich an Übertretung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Des Menschen Hoffart wird ihn erniedrigen; wer aber niedrigen Geistes ist, wird Ehre erlangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Wer mit einem Diebe teilt, haßt seine eigene Seele: er hört den Fluch und zeigt es nicht an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Menschenfurcht legt einen Fallstrick; wer aber auf Jehova vertraut, wird in Sicherheit gesetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Viele suchen das Angesicht eines Herrschers, doch von Jehova kommt das Recht des Mannes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Der ungerechte Mann ist ein Greuel für die Gerechten, und wer geraden Weges wandelt, ein Greuel für den Gottlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Worte Agurs, des Sohnes Jakes, der Ausspruch. Es spricht der Mann zu Ithiel, zu Ithiel und Ukal:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Fürwahr, ich bin unvernünftiger als irgend einer, und Menschenverstand habe ich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Und Weisheit habe ich nicht gelernt, daß ich Erkenntnis des Heiligen besäße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Wer ist hinaufgestiegen gen Himmel und herniedergefahren? Wer hat den Wind in seine Fäuste gesammelt? Wer die Wasser in ein Tuch gebunden? Wer hat aufgerichtet alle Enden der Erde? Was ist sein Name, und was der Name seines Sohnes, wenn du es weißt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Alle Rede Gottes ist geläutert; ein Schild ist er denen, die auf ihn trauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Tue nichts zu seinen Worten hinzu, damit er dich nicht überführe und du als Lügner erfunden werdest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Zweierlei erbitte ich von dir; verweigere es mit nicht, ehe ich sterbe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Eitles und Lügenwort entferne von mir, Armut und Reichtum gib mir nicht, speise mich mit dem mir beschiedenen Brote;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'damit ich nicht satt werde und dich verleugne und spreche: Wer ist Jehova? und damit ich nicht verarme und stehle, und mich vergreife an dem Namen meines Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Verleumde einen Knecht nicht bei seinem Herrn, damit er dir nicht fluche, und du es büßen müssest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Ein Geschlecht, das seinem Vater flucht und seine Mutter nicht segnet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'ein Geschlecht, das rein ist in seinen Augen und doch nicht gewaschen von seinem Unflat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'ein Geschlecht, wie stolz sind seine Augen, und seine Wimpern erheben sich! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'ein Geschlecht, dessen Zähne Schwerter sind, und Messer sein Gebiß, um wegzufressen die Elenden von der Erde und die Dürftigen aus der Menschen Mitte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Der Blutegel hat zwei Töchter: gib her! gib her! Drei sind es, die nicht satt werden, vier, die nicht sagen: Genug!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Der Scheol und der verschlossene Mutterleib, die Erde, welche des Wassers nicht satt wird, und das Feuer, das nicht sagt: Genug!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Ein Auge, das den Vater verspottet und den Gehorsam gegen die Mutter verachtet, das werden die Raben des Baches aushacken und die Jungen des Adlers fressen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Drei sind es, die zu wunderbar für mich sind, und vier, die ich nicht erkenne:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'der Weg des Adlers am Himmel, der Weg einer Schlange auf dem Felsen, der Weg eines Schiffes im Herzen des Meeres, und der Weg eines Mannes mit einer Jungfrau. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Also ist der Weg eines ehebrecherischen Weibes: sie ißt, und wischt ihren Mund und spricht: Ich habe kein Unrecht begangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Unter dreien erzittert die Erde, und unter vieren kann sie es nicht aushalten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'unter einem Knechte, wenn er König wird, und einem gemeinen Menschen, wenn er satt Brot hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'unter einem unleidlichen Weibe, wenn sie zur Frau genommen wird, und einer Magd, wenn sie ihre Herrin beerbt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Vier sind die Kleinen der Erde, und doch sind sie mit Weisheit wohl versehen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'die Ameisen, ein nicht starkes Volk, und doch bereiten sie im Sommer ihre Speise;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'die Klippendächse, ein nicht kräftiges Volk, und doch setzen sie ihr Haus auf den Felsen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'die Heuschrecken haben keinen König, und doch ziehen sie allesamt aus in geordneten Scharen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'die Eidechse kannst du mit Händen fangen, und doch ist sie in den Palästen der Könige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Drei haben einen stattlichen Schritt, und vier einen stattlichen Gang:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'der Löwe, der Held unter den Tieren, und der vor nichts zurückweicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'der Lendenstraffe, oder der Bock; und ein König, bei welchem der Heerbann ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Wenn du töricht gehandelt hast, indem du dich erhobst, oder wenn du Böses ersonnen: die Hand auf den Mund!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Denn das Pressen der Milch ergibt Butter, und das Pressen der Nase ergibt Blut, und das Pressen des Zornes ergibt Hader.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Worte Lemuels, des Königs; Ausspruch, womit seine Mutter ihn unterwies:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Was, mein Sohn, und was, Sohn meines Leibes, und was, Sohn meiner Gelübde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Gib nicht den Weibern deine Kraft, noch deine Wege den Verderberinnen der Könige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Nicht für Könige ziemt es sich, Lemuel, nicht für Könige, Wein zu trinken, noch für Fürsten, zu fragen: Wo ist starkes Getränk?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'damit er nicht trinke und des Vorgeschriebenen vergesse, und verdrehe die Rechtssache aller Kinder des Elends. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Gebet starkes Getränk dem Umkommenden, und Wein denen, die betrübter Seele sind:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'er trinke, und vergesse seine Armut und gedenke seiner Mühsal nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Tue deinen Mund auf für den Stummen, für die Rechtssache aller Unglücklichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Tue deinen Mund auf, richte gerecht, und schaffe Recht dem Elenden und dem Dürftigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Ein wackeres Weib, wer wird es finden? Denn ihr Wert steht weit über Korallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Das Herz ihres Mannes vertraut auf sie, und an Ausbeute wird es ihm nicht fehlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Sie erweist ihm Gutes und nichts Böses alle Tage ihres Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Sie sucht Wolle und Flachs, und arbeitet dann mit Lust ihrer Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Sie ist Kaufmannsschiffen gleich, von fernher bringt sie ihr Brot herbei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Und sie steht auf, wenn es noch Nacht ist, und bestimmt die Speise für ihr Haus und das Tagewerk für ihre Mägde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Sie sinnt auf ein Feld und erwirbt es; von der Frucht ihrer Hände pflanzt sie einen Weinberg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Sie gürtet ihre Lenden mit Kraft und stärkt ihre Arme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Sie erfährt, daß ihr Erwerb gut ist: des Nachts geht ihr Licht nicht aus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'sie legt ihre Hände an den Spinnrocken, und ihre Finger erfassen die Spindel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Sie breitet ihre Hand aus zu dem Elenden und streckt ihre Hände dem Dürftigen entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Sie fürchtet für ihr Haus den Schnee nicht, denn ihr ganzes Haus ist in Karmesin gekleidet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Sie verfertigt sich Teppiche; Byssus und Purpur sind ihr Gewand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Ihr Mann ist bekannt in den Toren, indem er sitzt bei den Ältesten des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Sie verfertigt Hemden und verkauft sie, und Gürtel liefert sie dem Kaufmann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Macht und Hoheit sind ihr Gewand, und so lacht sie des künftigen Tages.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Sie tut ihren Mund auf mit Weisheit, und liebreiche Lehre ist auf ihrer Zunge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Sie überwacht die Vorgänge in ihrem Hause und ißt nicht das Brot der Faulheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Ihre Söhne stehen auf und preisen sie glücklich, ihr Mann steht auf und rühmt sie:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, '\"Viele Töchter haben wacker gehandelt, du aber hast sie alle übertroffen!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Die Anmut ist Trug, und die Schönheit Eitelkeit; ein Weib, das Jehova fürchtet, sie wird gepriesen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Gebet ihr von der Frucht ihrer Hände; und in den Toren mögen ihre Werke sie preisen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Worte des Predigers, des Sohnes Davids, des Königs in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Eitelkeit der Eitelkeiten! spricht der Prediger; Eitelkeit der Eitelkeiten! Alles ist Eitelkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Welchen Gewinn hat der Mensch bei all seiner Mühe, womit er sich abmüht unter der Sonne?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Ein Geschlecht geht, und ein Geschlecht kommt; aber die Erde besteht ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Und die Sonne geht auf und die Sonne geht unter; und sie eilt ihrem Orte zu, wo sie aufgeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Der Wind geht nach Süden, und wendet sich nach Norden; sich wendend und wendend geht er, und zu seinen Wendungen kehrt der Wind zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Alle Flüsse gehen in das Meer, und das Meer wird nicht voll; an den Ort, wohin die Flüsse gehen, dorthin gehen sie immer wieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Alle Dinge mühen sich ab: niemand vermag es auszusprechen; das Auge wird des Sehens nicht satt, und das Ohr nicht voll vom Hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Das, was gewesen, ist das, was sein wird; und das, was geschehen, ist das, was geschehen wird. Und es ist gar nichts Neues unter der Sonne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Gibt es ein Ding, von dem man sagt: Siehe, das ist neu, längst ist es gewesen in den Zeitaltern, die vor uns gewesen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Da ist kein Andenken an die Früheren; und für die Nachfolgenden, die sein werden, für sie wird es auch kein Andenken bei denen geben, welche später sein werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Ich, Prediger, war König über Israel, in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Und ich richtete mein Herz darauf, alles mit Weisheit zu erforschen und zu erkunden, was unter dem Himmel geschieht: ein übles Geschäft, das Gott den Menschenkindern gegeben hat, sich damit abzuplagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Ich habe alle die Taten gesehen, welche unter der Sonne geschehen; und siehe, alles ist Eitelkeit und ein Haschen nach Wind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Das Krumme kann nicht gerade werden, und das Fehlende kann nicht gezählt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Ich sprach in meinem Herzen und sagte: Siehe, ich habe Weisheit vergrößert und vermehrt über alle hinaus, die vor mir über Jerusalem waren, und mein Herz hat Fülle von Weisheit und Erkenntnis gesehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'und ich habe mein Herz darauf gerichtet, Weisheit zu erkennen, und Unsinn und Torheit zu erkennen: ich habe erkannt, daß auch das ein Haschen nach Wind ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Denn bei viel Weisheit ist viel Verdruß: und wer Erkenntnis mehrt, mehrt Kummer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Ich sprach in meinem Herzen: Wohlan denn, ich will dich prüfen durch Freude und genieße das Gute! Aber siehe, auch das ist Eitelkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Zum Lachen sprach ich, es sei unsinnig; und zur Freude, was sie denn schaffe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Ich beschloß in meinem Herzen, meinen Leib durch Wein zu pflegen, während mein Herz sich mit Weisheit benähme, und es mit der Torheit zu halten, bis ich sähe, was den Menschenkindern gut wäre, unter dem Himmel zu tun die Zahl ihrer Lebenstage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Ich unternahm große Werke: Ich baute mir Häuser, ich pflanzte mir Weinberge;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'ich machte mir Gärten und Parkanlagen, und pflanzte darin Bäume von allerlei Frucht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'ich machte mir Wasserteiche, um daraus den mit Bäumen sprossenden Wald zu bewässern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Ich kaufte Knechte und Mägde und hatte Hausgeborene; auch hatte ich ein großes Besitztum an Rind-und Kleinvieh, mehr als alle, die vor mir in Jerusalem waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Ich sammelte mir auch Silber und Gold und Reichtum der Könige und Landschaften; ich schaffte mir Sänger und Sängerinnen, und die Wonnen der Menschenkinder: Frau und Frauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Und ich wurde groß und größer, mehr als alle, die vor mir in Jerusalem waren. Auch meine Weisheit verblieb mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Und was irgend meine Augen begehrten, entzog ich ihnen nicht; ich versagte meinem Herzen keine Freude, denn mein Herz hatte Freude von all meiner Mühe, und das war mein Teil von all meiner Mühe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Und ich wandte mich hin zu allen meinen Werken, die meine Hände gemacht, und zu der Mühe, womit ich wirkend mich abgemüht hatte: und siehe, das alles war Eitelkeit und ein Haschen nach Wind; und es gibt keinen Gewinn unter der Sonne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Und ich wandte mich, um Weisheit und Unsinn und Torheit zu betrachten. Denn was wird der Mensch tun, der nach dem Könige kommen wird? Was man schon längst getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Und ich sah, daß die Weisheit den Vorzug hat vor der Torheit, gleich dem Vorzuge des Lichtes vor der Finsternis:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'der Weise hat seine Augen in seinem Kopfe, der Tor aber wandelt in der Finsternis. Und ich erkannte zugleich, daß einerlei Geschick ihnen allen widerfährt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'und ich sprach in meinem Herzen: Gleich dem Geschick des Toren wird auch mir widerfahren, und wozu bin ich dann überaus weise gewesen? Und ich sprach in meinem Herzen, daß auch das Eitelkeit sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Denn dem Weisen, gleichwie dem Toren, wird kein ewiges Andenken zuteil, weil in den kommenden Tagen alles längst vergessen sein wird. Und wie stirbt der Weise gleich dem Toren hin!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Da haßte ich das Leben; denn das Tun, welches unter der Sonne geschieht, mißfiel mir; denn alles ist Eitelkeit und ein Haschen nach Wind. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Und ich haßte alle meine Mühe, womit ich mich abmühte unter der Sonne, weil ich sie dem Menschen hinterlassen muß, der nach mir sein wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Und wer weiß, ob er weise oder töricht sein wird? Und doch wird er schalten über alle meine Mühe, womit ich mich abgemüht habe, und worin ich weise gewesen bin unter der Sonne. Auch das ist Eitelkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Da wandte ich mich zu verzweifeln ob all der Mühe, womit ich mich abgemüht hatte unter der Sonne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Denn da ist ein Mensch, dessen Mühe mit Weisheit und mit Kenntnis und mit Tüchtigkeit geschieht: und doch muß er sie einem Menschen als sein Teil abgeben, der sich nicht darum gemüht hat. Auch das ist Eitelkeit und ein großes Übel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Denn was wird dem Menschen bei all seiner Mühe und beim Trachten seines Herzens, womit er sich abmüht unter der Sonne?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Denn alle seine Tage sind Kummer, und seine Geschäftigkeit ist Verdruß; selbst des Nachts ruht sein Herz nicht. Auch das ist Eitelkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Es gibt nichts Besseres unter den Menschen, als daß man esse und trinke und seine Seele Gutes sehen lasse bei seiner Mühe. Ich habe gesehen, daß auch das von der Hand Gottes abhängt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Denn wer kann essen und wer kann genießen ohne ihn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Denn dem Menschen, der ihm wohlgefällig ist, gibt er Weisheit und Kenntnis und Freude; dem Sünder aber gibt er das Geschäft, einzusammeln und aufzuhäufen, um es dem abzugeben, der Gott wohlgefällig ist. Auch das ist Eitelkeit und ein Haschen nach Wind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Alles hat eine bestimmte Zeit, und jedes Vornehmen unter dem Himmel hat seine Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Geborenwerden hat seine Zeit, und Sterben hat seine Zeit; Pflanzen hat seine Zeit, und das Gepflanzte Ausreißen hat seine Zeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Töten hat seine Zeit, und Heilen hat seine Zeit; Abbrechen hat seine Zeit, und Bauen hat seine Zeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Weinen hat seine Zeit, und Lachen hat seine Zeit; Klagen hat seine Zeit und Tanzen hat seine Zeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Steinewerfen hat seine Zeit, und Steinesammeln hat seine Zeit; Umarmen hat seine Zeit, und vom Umarmen Sichfernhalten hat seine Zeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Suchen hat seine Zeit, und Verlieren hat seine Zeit; Aufbewahren hat seine Zeit, und Fortwerfen hat seine Zeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Zerreißen hat seine Zeit, und Nähen hat seine Zeit; Schweigen hat seine Zeit, und Reden hat seine Zeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Lieben hat seine Zeit, und Hassen hat seine Zeit; Krieg hat seine Zeit, und Frieden hat seine Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Was für einen Gewinn hat der Schaffende bei dem, womit er sich abmüht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Ich habe das Geschäft gesehen, welches Gott den Menschenkindern gegeben hat, sich damit abzuplagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Alles hat er schön gemacht zu seiner Zeit; auch hat er die Ewigkeit in ihr Herz gelegt, ohne daß der Mensch das Werk, welches Gott gewirkt hat, von Anfang bis zu Ende zu erfassen vermag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Ich habe erkannt, daß es nichts Besseres unter ihnen gibt, als sich zu freuen und sich in seinem Leben gütlich zu tun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'und auch, daß er esse und trinke und Gutes sehe bei all seiner Mühe, ist für jeden Menschen eine Gabe Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Ich habe erkannt, daß alles, was Gott tut, für ewig sein wird: es ist ihm nichts hinzuzufügen, und nichts davon wegzunehmen; und Gott hat es also gemacht, damit man sich vor ihm fürchte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Was da ist, war längst, und was sein wird, ist längst gewesen; und Gott sucht das Vergangene wieder hervor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Und ferner habe ich unter der Sonne gesehen: an der Stätte des Rechts, da war die Gesetzlosigkeit, und an der Stätte der Gerechtigkeit, da war die Gesetzlosigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Ich sprach in meinem Herzen: Gott wird den Gerechten und den Gesetzlosen richten; denn er hat eine Zeit gesetzt für jedes Vornehmen und für jedes Werk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Ich sprach in meinem Herzen: Wegen der Menschenkinder geschieht es, damit Gott sie prüfe, und damit sie sehen, daß sie an und für sich Tiere sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Denn was das Geschick der Menschenkinder und das Geschick der Tiere betrifft, so haben sie einerlei Geschick: wie diese sterben, so sterben jene, und einen Odem haben sie alle; und da ist kein Vorzug des Menschen vor dem Tiere, denn alles ist Eitelkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Alles geht an einen Ort; alles ist aus dem Staube geworden, und alles kehrt zum Staube zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Wer weiß von dem Odem der Menschenkinder, ob er aufwärts fährt, und von dem Odem der Tiere, ob er niederwärts zur Erde hinabfährt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Und so habe ich gesehen, daß nichts besser ist, als daß der Mensch sich freue an seinen Werken; denn das ist sein Teil. Denn wer wird ihn dahin bringen, daß er Einsicht gewinne in das, was nach ihm werden wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Und ich wandte mich und sah alle die Bedrückungen, welche unter der Sonne geschehen: und siehe, da waren Tränen der Bedrückten, und sie hatten keinen Tröster; und von der Hand ihrer Bedrücker ging Gewalttat aus, und sie hatten keinen Tröster.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Und ich pries die Toten, die längst gestorben, mehr als die Lebenden, welche jetzt noch leben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'und glücklicher als beide pries ich den, der noch nicht gewesen ist, der das böse Tun nicht gesehen hat, welches unter der Sonne geschieht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Und ich sah all die Mühe und all die Geschicklichkeit in der Arbeit, daß es Eifersucht des einen gegen den anderen ist. Auch das ist Eitelkeit und ein Haschen nach Wind. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Der Tor faltet seine Hände und verzehrt sein eigenes Fleisch. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Besser eine Hand voll Ruhe, als beide Fäuste voll Mühe und Haschen nach Wind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Und ich wandte mich und sah Eitelkeit unter der Sonne:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Da ist ein einzelner und kein zweiter, auch hat er weder Sohn noch Bruder, und all seiner Mühe ist kein Ende; gleichwohl werden seine Augen des Reichtums nicht satt: \"Für wen mühe ich mich doch, und lasse meine Seele Mangel leiden am Guten?\" Auch das ist Eitelkeit und ein übles Geschäft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Zwei sind besser daran als einer, weil sie eine gute Belohnung für ihre Mühe haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'denn wenn sie fallen, so richtet der eine seinen Genossen auf. Wehe aber dem einzelnen, welcher fällt, ohne daß ein zweiter da ist, um ihn aufzurichten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Auch wenn zwei beieinander liegen, so werden sie warm; der einzelne aber, wie will er warm werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Und wenn jemand den einzelnen gewalttätig angreift, so werden ihm die zwei widerstehen; und eine dreifache Schnur zerreißt nicht so bald.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Besser ein armer und weiser Jüngling als ein alter und törichter König, der nicht mehr weiß, sich warnen zu lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Denn aus dem Hause der Gefangenen ging er hervor, um König zu sein, obwohl er im Königreiche jenes arm geboren war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Ich sah alle Lebenden, die unter der Sonne wandeln, mit dem Jünglinge, dem zweiten, welcher an jenes Stelle treten sollte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'kein Ende all des Volkes, aller derer, welchen er vorstand; dennoch werden die Nachkommen sich seiner nicht freuen. Denn auch das ist Eitelkeit und ein Haschen nach Wind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Bewahre deinen Fuß, wenn du zum Hause Gottes gehst; und nahen, um zu hören, ist besser, als wenn die Toren Schlachtopfer geben: denn sie haben keine Erkenntnis, so daß sie Böses tun. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Sei nicht vorschnell mit deinem Munde, und dein Herz eile nicht, ein Wort vor Gott hervorzubringen; denn Gott ist im Himmel, und du bist auf der Erde: darum seien deiner Worte wenige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Denn Träume kommen durch viel Geschäftigkeit, und der Tor wird laut durch viele Worte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Wenn du Gott ein Gelübde tust, so säume nicht, es zu bezahlen; denn er hat kein Gefallen an den Toren. Was du gelobst, bezahle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Besser, daß du nicht gelobst, als daß du gelobst und nicht bezahlst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Gestatte deinem Munde nicht, daß er dein Fleisch sündigen mache; und sprich nicht vor dem Boten Gottes, es sei ein Versehen gewesen: warum sollte Gott über deine Stimme zürnen und das Werk deiner Hände verderben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Denn bei vielen Träumen und Worten sind auch viele Eitelkeiten. Vielmehr fürchte Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Wenn du die Bedrückung des Armen und den Raub des Rechts und der Gerechtigkeit in der Landschaft siehst, so verwundere dich nicht über die Sache; denn ein Hoher lauert über dem Hohen, und Hohe über ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Aber ein König, der sich dem Ackerbau widmet, ist durchaus ein Vorteil für ein Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Wer das Geld liebt, wird des Geldes nicht satt; und wer den Reichtum liebt, nicht des Ertrages. Auch das ist Eitelkeit. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Wenn das Gut sich mehrt, so mehren sich, die davon zehren; und welchen Nutzen hat dessen Besitzer, als das Anschauen seiner Augen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Der Schlaf des Arbeiters ist süß, mag er wenig oder viel essen; aber der Überfluß des Reichen läßt ihn nicht schlafen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Es gibt ein schlimmes Übel, das ich unter der Sonne gesehen habe: Reichtum, welcher von dessen Besitzer zu seinem Unglück aufbewahrt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Solcher Reichtum geht nämlich durch irgend ein Mißgeschick verloren; und hat er einen Sohn gezeugt, so ist gar nichts in dessen Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Gleichwie er aus dem Leibe seiner Mutter hervorgekommen ist, wird er nackt wieder hingehen, wie er gekommen ist; und für seine Mühe wird er nicht das Geringste davontragen, das er in seiner Hand mitnehmen könnte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Und auch dies ist ein schlimmes Übel: ganz so wie er gekommen ist, also wird er hingehen; und was für einen Gewinn hat er davon, daß er in den Wind sich müht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Auch isset er alle seine Tage in Finsternis, und hat viel Verdruß und Leid und Zorn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Siehe, was ich als gut, was ich als schön ersehen habe: daß einer esse und trinke und Gutes sehe bei all seiner Mühe, womit er sich abmüht unter der Sonne, die Zahl seiner Lebenstage, die Gott ihm gegeben hat; denn das ist sein Teil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Auch ist für jeden Menschen, welchem Gott Reichtum und Güter gegeben, und den er ermächtigt hat, davon zu genießen und sein Teil zu nehmen und sich bei seiner Mühe zu freuen, eben dieses eine Gabe Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Denn er wird nicht viel an die Tage seines Lebens denken, weil Gott ihm die Freude seines Herzens gewährt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Es gibt ein Übel, welches ich unter der Sonne gesehen habe, und schwer lastet es auf dem Menschen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Einer, dem Gott Reichtum und Güter und Ehre gibt, und welcher nichts für seine Seele entbehrt von allem, was er wünschen mag; aber Gott ermächtigt ihn nicht, davon zu genießen, sondern ein Fremder genießt es. Das ist Eitelkeit und ein schlimmes Übel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Wenn einer hundert Söhne zeugte und viele Jahre lebte, und der Tage seiner Jahre wären viele, und seine Seele sättigte sich nicht an Gutem, und auch würde ihm kein Begräbnis zuteil, so sage ich: Eine Fehlgeburt ist besser daran als er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Denn in Nichtigkeit kommt sie, und in Finsternis geht sie dahin, und mit Finsternis wird ihr Name bedeckt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'auch hat sie die Sonne nicht gesehen noch gekannt. Diese hat mehr Ruhe als jener.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Und wenn er auch zweimal tausend Jahre gelebt, und Gutes nicht gesehen hätte: geht nicht alles an einen Ort?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Alle Mühe des Menschen ist für seinen Mund, und dennoch wird seine Begierde nicht gestillt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Denn was hat der Weise vor dem Toren voraus, was der Arme, der vor den Lebenden zu wandeln versteht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Besser das Anschauen der Augen als das Umherschweifen der Begierde. Auch das ist Eitelkeit und ein Haschen nach Wind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Was entsteht, schon längst war sein Name genannt; und es ist bekannt, was ein Mensch sein wird, und er vermag nicht mit dem zu rechten, der stärker ist als er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Denn es gibt viele Worte, welche die Eitelkeit mehren; welchen Nutzen hat der Mensch davon?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, '(H6:11) Denn wer weiß, was dem Menschen gut ist im Leben, die Zahl der Tage seines eitlen Lebens, welche er wie ein Schatten verbringt? Denn wer kann dem Menschen kundtun, was nach ihm sein wird unter der Sonne?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Besser ein guter Name als gutes Salböl, und der Tag des Todes als der Tag, da einer geboren wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Besser, in das Haus der Trauer zu gehen, als in das Haus des Gelages zu gehen, indem jenes das Ende aller Menschen ist; und der Lebende nimmt es zu Herzen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Besser Bekümmernis als Lachen; denn bei traurigem Angesicht ist es dem Herzen wohl. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Das Herz der Weisen ist im Hause der Trauer, und das Herz der Toren im Hause der Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Besser, das Schelten der Weisen zu hören, als daß einer den Gesang der Toren hört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Denn wie das Geknister der Dornen unter dem Topfe, so das Lachen des Toren. Auch das ist Eitelkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, '...Denn die Erpressung macht den Weisen toll, und das Bestechungsgeschenk richtet das Herz zu Grunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Besser das Ende einer Sache als ihr Anfang; besser der Langmütige als der Hochmütige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Sei nicht vorschnell in deinem Geiste zum Unwillen, denn der Unwille ruht im Busen der Toren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Sprich nicht: Wie ist es, daß die früheren Tage besser waren als diese? Denn nicht aus Weisheit fragst du danach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Weisheit ist gut wie ein Erbbesitz, und ein Vorteil für die, welche die Sonne sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Denn im Schatten ist, wer Weisheit hat, im Schatten, wer Geld hat; aber der Vorzug der Erkenntnis ist dieser, daß die Weisheit ihren Besitzern Leben gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Schaue das Werk Gottes an; denn wer kann gerade machen, was er gekrümmt hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Am Tage der Wohlfahrt sei guter Dinge; aber am Tage des Unglücks bedenke: auch diesen wie jenen hat Gott gemacht, damit der Mensch nicht irgend etwas nach sich finde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Allerlei habe ich gesehen in den Tagen meiner Eitelkeit: da ist ein Gerechter, der bei seiner Gerechtigkeit umkommt, und da ist ein Gesetzloser, der bei seiner Bosheit seine Tage verlängert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Sei nicht allzu gerecht, und erzeige dich nicht übermäßig weise: warum willst du dich verderben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Sei nicht allzu gesetzlos, und sei nicht töricht: warum willst du sterben, ehe deine Zeit da ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Es ist gut, daß du an diesem festhältst, und auch von jenem deine Hand nicht abziehst; denn der Gottesfürchtige entgeht dem allen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Die Weisheit macht den Weisen stärker als zehn Machthaber, die in der Stadt sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Denn unter den Menschen ist kein Gerechter auf Erden, der Gutes tue und nicht sündige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Auch richte dein Herz nicht auf alle Worte, die man redet, damit du nicht deinen Knecht dir fluchen hörst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'denn auch viele Male, dein Herz weiß es, hast auch du anderen geflucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Das alles habe ich mit Weisheit geprüft. Ich sprach: Ich will weise werden; aber sie blieb fern von mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Fern ist das, was ist, und tief, tief: wer kann es erreichen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Ich wandte mich, und mein Herz ging darauf aus, Weisheit und ein richtiges Urteil zu erkennen und zu erkunden und zu suchen, und zu erkennen, daß die Gesetzlosigkeit Torheit ist, und die Narrheit Tollheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Und ich fand, was bitterer ist als der Tod: das Weib, welches Netzen gleicht, und dessen Herz Fanggarne, dessen Hände Fesseln sind. Wer Gott wohlgefällig ist, wird ihr entrinnen; aber der Sünder wird durch sie gefangen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Siehe, dieses habe ich gefunden, spricht der Prediger, indem ich eines zum anderen fügte, um ein richtiges Urteil zu finden:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Was meine Seele fort und fort gesucht und ich nicht gefunden habe, ist dies: einen Mann aus Tausenden habe ich gefunden, aber ein Weib unter diesen allen habe ich nicht gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Allein, siehe, dieses habe ich gefunden, daß Gott den Menschen aufrichtig geschaffen hat; sie aber haben viele Ränke gesucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Wer ist wie der Weise, und wer versteht die Deutung der Dinge? Die Weisheit des Menschen erleuchtet sein Angesicht, und der Trotz seines Angesichts wird verwandelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Ich sage: Habe acht auf den Befehl des Königs, und zwar wegen des Eides Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Übereile dich nicht, von ihm wegzugehen, laß dich nicht ein in eine böse Sache, denn er tut alles, was er will;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'weil des Königs Wort eine Macht ist, und wer will zu ihm sagen: Was tust du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Wer das Gebot hält, wird nichts Böses erfahren, und eines Weisen Herz kennt Zeit und richterliche Entscheidung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Denn für jede Sache gibt es eine Zeit und eine richterliche Entscheidung; denn das Unglück des Menschen lastet schwer auf ihm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'denn er weiß nicht, was werden wird; denn wer sollte ihm kundtun, wie es werden wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Kein Mensch hat Macht über den Wind, den Wind zurückzuhalten; und niemand hat Macht über den Tag des Todes; und keine Entlassung gibt es im Kriege; und die Gesetzlosigkeit wird den nicht retten, der sie übt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Das alles habe ich gesehen, und habe mein Herz auf alles Tun gerichtet, welches unter der Sonne geschieht, zur Zeit, wo der Mensch über die Menschen herrscht zu ihrem Unglück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Und alsdann habe ich Gesetzlose gesehen, die begraben wurden und zur Ruhe eingingen; diejenigen aber, welche recht gehandelt hatten, mußten von der heiligen Stätte wegziehen und wurden in der Stadt vergessen. Auch das ist Eitelkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Weil das Urteil über böse Taten nicht schnell vollzogen wird, darum ist das Herz der Menschenkinder in ihnen voll, Böses zu tun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'weil ein Sünder hundertmal Böses tut und doch seine Tage verlängert obgleich ich weiß, daß es denen, die Gott fürchten, wohlgehen wird, weil sie sich vor ihm fürchten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'aber dem Gesetzlosen wird es nicht wohlgehen, und er wird, dem Schatten gleich, seine Tage nicht verlängern, weil er sich vor Gott nicht fürchtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Es ist eine Eitelkeit, die auf Erden geschieht: daß es Gerechte gibt, welchen nach dem Tun der Gesetzlosen widerfährt, und daß es Gesetzlose gibt, welchen nach dem Tun der Gerechten widerfährt. Ich sagte, daß auch das Eitelkeit sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Und ich pries die Freude, weil es für den Menschen nichts Besseres unter der Sonne gibt, als zu essen und zu trinken und sich zu freuen; und dies wird ihn begleiten bei seiner Mühe, die Tage seines Lebens hindurch, welche Gott ihm unter der Sonne gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Als ich mein Herz darauf richtete, Weisheit zu erkennen, und das Treiben zu besehen, welches auf Erden geschieht (denn weder bei Tage noch bei Nacht sieht er den Schlaf mit seinen Augen),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'da habe ich bezüglich des ganzen Werkes Gottes gesehen, daß der Mensch das Werk nicht zu erfassen vermag, welches unter der Sonne geschieht, indem der Mensch sich abmüht es zu suchen, aber es nicht erfaßt. Und selbst wenn der Weise es zu erkennen meint, vermag er es doch nicht zu erfassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Denn dies alles habe ich mir zu Herzen genommen, und zwar um dies alles zu prüfen: daß die Gerechten und die Weisen und ihre Werke in der Hand Gottes sind; weder Liebe noch Haß kennt der Mensch im voraus: alles ist vor ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Alles ist gleicherweise für alle: einerlei Geschick für den Gerechten und den Gesetzlosen, für den Guten und den Reinen und den Unreinen, und für den, der opfert, und den, der nicht opfert: wie der Gute, so der Sünder, der, welcher schwört, wie der, welcher den Eid fürchtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Das ist ein Übel in allem, was unter der Sonne geschieht, daß einerlei Geschick allen zuteil wird; und auch ist das Herz der Menschenkinder voll Bosheit, und Narrheit ist in ihrem Herzen während ihres Lebens; und danach geht\'s zu den Toten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Denn für einen jeden, der all den Lebenden zugesellt wird, gibt es Hoffnung; denn selbst ein lebendiger Hund ist besser daran als ein toter Löwe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Denn die Lebenden wissen, daß sie sterben werden; die Toten aber wissen gar nichts, und sie haben keinen Lohn mehr, denn ihr Gedächtnis ist vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Sowohl ihre Liebe als auch ihr Haß und ihr Eifern sind längst verschwunden; und sie haben ewiglich kein Teil mehr an allem, was unter der Sonne geschieht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Geh, iß dein Brot mit Freude und trinke deinen Wein mit frohem Herzen; denn längst hat Gott Wohlgefallen an deinem Tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Deine Kleider seien weiß zu aller Zeit, und das Öl mangle nicht auf deinem Haupte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Genieße das Leben mit dem Weibe, das du liebst, alle Tage deines eitlen Lebens, welches er dir unter der Sonne gegeben hat, alle deine eitlen Tage hindurch; denn das ist dein Teil am Leben und an deiner Mühe, womit du dich abmühst unter der Sonne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Alles, was du zu tun vermagst mit deiner Kraft, das tue; denn es gibt weder Tun noch Überlegung noch Kenntnis noch Weisheit im Scheol, wohin du gehst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Ich wandte mich und sah unter der Sonne, daß nicht den Schnellen der Lauf gehört, und nicht den Helden der Krieg, und auch nicht den Weisen das Brot, und auch nicht den Verständigen der Reichtum, und auch nicht den Kenntnisreichen die Gunst; denn Zeit und Schicksal trifft sie alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Denn der Mensch weiß auch seine Zeit nicht; gleich den Fischen, welche gefangen werden im verderblichen Netze, und gleich den Vögeln, welche in der Schlinge gefangen werden: gleich diesen werden die Menschenkinder verstrickt zur Zeit des Unglücks, wenn dieses sie plötzlich überfällt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Auch dieses habe ich als Weisheit unter der Sonne gesehen, und sie kam mir groß vor:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Es war eine kleine Stadt, und wenig Männer waren darin; und wider sie kam ein großer König, und er umzingelte sie und baute große Belagerungswerke wider sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Und es fand sich darin ein armer weiser Mann, der die Stadt durch seine Weisheit rettete; aber kein Mensch gedachte dieses armen Mannes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Da sprach ich: Weisheit ist besser als Kraft; aber die Weisheit des Armen wird verachtet, und seine Worte werden nicht gehört. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Worte der Weisen, in Ruhe gehört, sind mehr wert als das Geschrei des Herrschers unter den Toren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Weisheit ist besser als Kriegsgeräte; aber ein Sünder vernichtet viel Gutes. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Tote Fliegen machen das Öl des Salbenmischers stinkend und gärend: ein wenig Torheit hat mehr Gewicht als Weisheit und Ehre. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Des Weisen Herz ist nach seiner Rechten, und des Toren Herz nach seiner Linken gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Und auch wenn der Tor auf dem Wege wandelt, fehlt ihm der Verstand, und er sagt allen, er sei ein Tor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Wenn der Zorn des Herrschers wider dich aufsteigt, so verlaß deine Stelle nicht; denn Gelassenheit verhindert große Sünden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Es gibt ein Übel, das ich unter der Sonne gesehen habe, gleich einem Irrtum, welcher von dem Machthaber ausgeht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Die Torheit wird in große Würden eingesetzt, und Reiche sitzen in Niedrigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Ich habe Knechte auf Rossen gesehen, und Fürsten, die wie Knechte zu Fuß gingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Wer eine Grube gräbt, kann hineinfallen; und wer eine Mauer einreißt, den kann eine Schlange beißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Wer Steine bricht, kann sich daran verletzen; wer Holz spaltet, kann sich dadurch gefährden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Wenn das Eisen stumpf geworden ist, und er hat die Schneide nicht geschliffen, so muß er seine Kräfte mehr anstrengen; aber die Weisheit ist vorteilhaft, um etwas in Stand zu setzen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Wenn die Schlange beißt, ehe die Beschwörung da ist, so hat der Beschwörer keinen Nutzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Die Worte des Mundes eines Weisen sind Anmut, aber die Lippen eines Toren verschlingen ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Der Anfang der Worte seines Mundes ist Torheit, und das Ende seiner Rede ist schlimmer Unsinn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Und der Tor macht viele Worte: doch weiß der Mensch nicht, was sein wird; und was nach ihm sein wird, wer wird es ihm kundtun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Die Mühe des Toren macht ihn müde, ihn, der nicht einmal nach der Stadt zu gehen weiß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Wehe dir, Land, dessen König ein Knabe ist, und dessen Fürsten am Morgen schmausen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Glücklich, du Land, dessen König ein Sohn der Edlen ist, und dessen Fürsten zu rechter Zeit speisen, als Männer und nicht als Schwelger! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Durch Faulenzen senkt sich das Gebälk, und durch Lässigkeit der Hände tropft das Haus. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Um sich zu belustigen, hält man Mahlzeiten, und Wein erheitert das Leben, und das Geld gewährt alles. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Auch in deinen Gedanken fluche dem Könige nicht, und in deinen Schlafgemächern fluche nicht dem Reichen; denn das Gevögel des Himmels möchte die Stimme entführen, und das Geflügelte das Wort anzeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Wirf dein Brot hin auf die Fläche der Wasser, denn nach vielen Tagen wirst du es finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Gib einen Teil an sieben, ja, sogar an acht; denn du weißt nicht, was für Unglück sich auf der Erde ereignen wird. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Wenn die Wolken voll Regen sind, so entleeren sie sich auf die Erde; und wenn ein Baum nach Süden oder nach Norden fällt: an dem Orte, wo der Baum fällt, da bleibt er liegen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Wer auf den Wind achtet, wird nicht säen, und wer auf die Wolken sieht, wird nicht ernten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Gleichwie du nicht weißt, welches der Weg des Windes ist, wie die Gebeine in dem Leibe der Schwangeren sich bilden, ebenso weißt du das Werk Gottes nicht, der alles wirkt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Am Morgen säe deinen Samen, und des Abends ziehe deine Hand nicht ab; denn du weißt nicht, welches gedeihen wird: ob dieses oder jenes, oder ob beides zugleich gut werden wird. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Und süß ist das Licht, und wohltuend den Augen, die Sonne zu sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Denn wenn der Mensch auch viele Jahre lebt, möge er in ihnen allen sich freuen und der Tage der Finsternis gedenken, daß ihrer viele sein werden: alles, was kommt, ist Eitelkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Freue dich, Jüngling, in deiner Jugend, und dein Herz mache dich fröhlich in den Tagen deiner Jugendzeit, und wandle in den Wegen deines Herzens und im Anschauen deiner Augen; doch wisse, daß um dies alles Gott dich ins Gericht bringen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Und entferne den Unmut aus deinem Herzen, und tue das Übel von deinem Leibe weg; denn die Jugend und das Mannesalter sind Eitelkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Und gedenke deines Schöpfers in den Tagen deiner Jugendzeit, ehe die Tage des Übels kommen, und die Jahre herannahen, von welchen du sagen wirst: Ich habe kein Gefallen an ihnen; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'ehe sich verfinstern die Sonne und das Licht, und der Mond und die Sterne, und die Wolken nach dem Regen wiederkehren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'an dem Tage, da die Hüter des Hauses zittern, und sich krümmen die starken Männer, und die Müllerinnen feiern, weil ihrer wenig geworden, und sich verfinstern die durch die Fenster Sehenden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'und die Türen nach der Straße geschlossen werden; indem das Geräusch der Mühle dumpf wird, und er aufsteht bei der Stimme des Vogels, und gedämpft werden alle Töchter des Gesanges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Auch fürchten sie sich vor der Höhe, und Schrecknisse sind auf dem Wege; und der Mandelbaum steht in Blüte, und die Heuschrecke schleppt sich hin, und die Kaper ist wirkungslos. Denn der Mensch geht hin zu seinem ewigen Hause, und die Klagenden ziehen umher auf der Straße; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'ehe zerrissen wird die silberne Schnur, und zerschlagen die goldene Schale, und zerbrochen der Eimer am Quell, und zerschlagen die Schöpfwelle an der Zisterne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'und der Staub zur Erde zurückkehrt, so wie er gewesen, und der Geist zu Gott zurückkehrt, der ihn gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Eitelkeit der Eitelkeiten! spricht der Prediger; alles ist Eitelkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Und überdem, daß der Prediger weise war, lehrte er noch das Volk Erkenntnis und erwog und forschte, verfaßte viele Sprüche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Der Prediger suchte angenehme Worte zu finden; und das Geschriebene ist richtig, Worte der Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Die Worte der Weisen sind wie Treibstacheln, und wie eingeschlagene Nägel die gesammelten Sprüche; sie sind gegeben von einem Hirten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Und überdies, mein Sohn, laß dich warnen: Des vielen Büchermachens ist kein Ende, und viel Studieren ist Ermüdung des Leibes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Das Endergebnis des Ganzen laßt uns hören: Fürchte Gott und halte seine Gebote; denn das ist der ganze Mensch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Denn Gott wird jedes Werk, es sei gut oder böse, in das Gericht über alles Verborgene bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Das Lied der Lieder, von Salomo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Er küsse mich mit den Küssen seines Mundes, denn deine Liebe ist besser als Wein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Lieblich an Geruch sind deine Salben, ein ausgegossenes Salböl ist dein Name; darum lieben dich die Jungfrauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Ziehe mich: wir werden dir nachlaufen. Der König hat mich in seine Gemächer geführt: wir wollen frohlocken und deiner uns freuen, wollen deine Liebe preisen mehr als Wein! Sie lieben dich in Aufrichtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Ich bin schwarz, aber anmutig, Töchter Jerusalems, wie die Zelte Kedars, wie die Zeltbehänge Salomos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Sehet mich nicht an, weil ich schwärzlich bin, weil die Sonne mich verbrannt hat; meiner Mutter Söhne zürnten mir, bestellten mich zur Hüterin der Weinberge; meinen eigenen Weinberg habe ich nicht gehütet. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Sage mir an, du, den meine Seele liebt, wo weidest du, wo lässest du lagern am Mittag? Denn warum sollte ich wie eine Verschleierte sein bei den Herden deiner Genossen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Wenn du es nicht weißt, du Schönste unter den Frauen, so geh hinaus, den Spuren der Herde nach und weide deine Zicklein bei den Wohnungen der Hirten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Einem Rosse an des Pharao Prachtwagen vergleiche ich dich, meine Freundin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Anmutig sind deine Wangen in den Kettchen, dein Hals in den Schnüren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Wir wollen dir goldene Kettchen machen mit Punkten von Silber. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Während der König an seiner Tafel war, gab meine Narde ihren Duft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Mein Geliebter ist mir ein Bündel Myrrhe, das zwischen meinen Brüsten ruht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Eine Zypertraube ist mir mein Geliebter, in den Weinbergen von Engedi. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Siehe, du bist schön, meine Freundin, siehe, du bist schön, deine Augen sind Tauben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Siehe, du bist schön, mein Geliebter, ja, holdselig; ja, unser Lager ist frisches Grün.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Die Balken unserer Behausung sind Zedern, unser Getäfel Zypressen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Ich bin eine Narzisse Sarons, eine Lilie der Täler. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Wie eine Lilie inmitten der Dornen, so ist meine Freundin inmitten der Töchter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Wie ein Apfelbaum unter den Bäumen des Waldes, so ist mein Geliebter inmitten der Söhne; ich habe mich mit Wonne in seinen Schatten gesetzt, und seine Frucht ist meinem Gaumen süß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Er hat mich in das Haus des Weines geführt, und sein Panier über mir ist die Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Stärket mich mit Traubenkuchen, erquicket mich mit Äpfeln, denn ich bin krank vor Liebe! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Seine Linke ist unter meinem Haupte, und seine Rechte umfaßt mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Ich beschwöre euch, Töchter Jerusalems, bei den Gazellen oder bei den Hindinnen des Feldes, daß ihr nicht wecket noch aufwecket die Liebe, bis es ihr gefällt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Horch! mein Geliebter! Siehe, da kommt er, springend über die Berge, hüpfend über die Hügel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Mein Geliebter gleicht einer Gazelle, oder einem Jungen der Hirsche. Siehe, da steht er hinter unserer Mauer, schaut durch die Fenster, blickt durch die Gitter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Mein Geliebter hob an und sprach zu mir: Mache dich auf, meine Freundin, meine Schöne, und komm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Denn siehe, der Winter ist vorbei, der Regen ist vorüber, er ist dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Die Blumen erscheinen im Lande, die Zeit des Gesanges ist gekommen, und die Stimme der Turteltaube läßt sich hören in unserem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Der Feigenbaum rötet seine Feigen, und die Weinstöcke sind in der Blüte, geben Duft. Mache dich auf, meine Freundin, meine Schöne, und komm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Meine Taube im Geklüft der Felsen, im Versteck der Felswände, laß mich deine Gestalt sehen, laß mich deine Stimme hören; denn deine Stimme ist süß und deine Gestalt anmutig. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Fanget uns die Füchse, die kleinen Füchse, welche die Weinberge verderben; denn unsere Weinberge sind in der Blüte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Mein Geliebter ist mein, und ich bin sein, der unter den Lilien weidet. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Bis der Tag sich kühlt und die Schatten fliehen, wende dich, sei, mein Geliebter, gleich einer Gazelle oder einem Jungen der Hirsche auf den zerklüfteten Bergen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Auf meinem Lager in den Nächten suchte ich, den meine Seele liebt: ich suchte ihn und fand ihn nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Ich will doch aufstehen und in der Stadt umhergehen, auf den Straßen und auf den Plätzen, will suchen, den meine Seele liebt. Ich suchte ihn und fand ihn nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Es fanden mich die Wächter, die in der Stadt umhergehen: Habt ihr den gesehen, den meine Seele liebt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Kaum war ich an ihnen vorüber, da fand ich, den meine Seele liebt. Ich ergriff ihn und ließ ihn nicht, bis ich ihn gebracht hatte in das Haus meiner Mutter und in das Gemach meiner Gebärerin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Ich beschwöre euch, Töchter Jerusalems, bei den Gazellen oder bei den Hindinnen des Feldes, daß ihr nicht wecket noch aufwecket die Liebe, bis es ihr gefällt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Wer ist die, die da heraufkommt von der Wüste her wie Rauchsäulen, durchduftet von Myrrhe und Weihrauch, von allerlei Gewürzpulver des Krämers?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Siehe da, Salomos Tragbett: Sechzig Helden rings um dasselbe her von den Helden Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Sie alle führen das Schwert, sind geübt im Kriege; ein jeder hat sein Schwert an seiner Hüfte, zum Schutz vor dem Schrecken in den Nächten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Der König Salomo hat sich ein Prachtbett gemacht von dem Holze des Libanon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Seine Säulen hat er von Silber gemacht, seine Lehne von Gold, seinen Sitz von Purpur; das Innere ist kunstvoll gestickt, aus Liebe, von den Töchtern Jerusalems.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Kommet heraus, Töchter Zions, und betrachtet den König Salomo in der Krone, mit welcher seine Mutter ihn gekrönt hat am Tage seiner Vermählung und am Tage der Freude seines Herzens!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Siehe, du bist schön, meine Freundin, siehe, du bist schön: Deine Augen sind Tauben hinter deinem Schleier. Dein Haar ist wie eine Herde Ziegen, die an den Abhängen des Gebirges Gilead lagern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Deine Zähne sind wie eine Herde geschorener Schafe, die aus der Schwemme heraufkommen, welche allzumal Zwillinge gebären, und keines unter ihnen ist unfruchtbar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Deine Lippen sind wie eine Karmesinschnur, und dein Mund ist zierlich. Wie ein Schnittstück einer Granate ist deine Schläfe hinter deinem Schleier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Dein Hals ist wie der Turm Davids, der in Terrassen gebaut ist: tausend Schilde hängen daran, alle Schilde der Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Deine beiden Brüste sind wie ein Zwillingspaar junger Gazellen, die unter den Lilien weiden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Bis der Tag sich kühlt und die Schatten fliehen, will ich zum Myrrhenberge hingehen und zum Weihrauchhügel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Ganz schön bist du, meine Freundin, und kein Makel ist an dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Mit mir vom Libanon herab, meine Braut, mit mir vom Libanon sollst du kommen; vom Gipfel des Amana herab sollst du schauen, vom Gipfel des Senir und Hermon, von den Lagerstätten der Löwen, von den Bergen der Panther.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Du hast mir das Herz geraubt, meine Schwester, meine Braut; du hast mir das Herz geraubt mit einem deiner Blicke, mit einer Kette von deinem Halsschmuck.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Wie schön ist deine Liebe, meine Schwester, meine Braut; wieviel besser ist deine Liebe als Wein, und der Duft deiner Salben als alle Gewürze! Honigseim träufeln deine Lippen, meine Braut;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Honig und Milch ist unter deiner Zunge, und der Duft deiner Gewänder wie der Duft des Libanon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Ein verschlossener Garten ist meine Schwester, meine Braut, ein verschlossener Born, eine versiegelte Quelle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Was dir entsproßt, ist ein Lustgarten von Granaten nebst edlen Früchten, Zyperblumen nebst Narden; Narde und Safran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Würzrohr und Zimt, nebst allerlei Weihrauchgehölz, Myrrhe und Aloe nebst allen vortrefflichsten Gewürzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'eine Gartenquelle, ein Brunnen lebendigen Wassers, und Bäche, die vom Libanon fließen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Wache auf, Nordwind, und komm, Südwind: durchwehe meinen Garten, laß träufeln seine Wohlgerüche! Mein Geliebter komme in seinen Garten und esse die ihm köstliche Frucht. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Ich bin in meinen Garten gekommen, meine Schwester, meine Braut, habe meine Myrrhe gepflückt samt meinem Balsam, habe meine Wabe gegessen samt meinem Honig, meinen Wein getrunken samt meiner Milch. Esset, Freunde; trinket und berauschet euch, Geliebte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Ich schlief, aber mein Herz wachte. Horch! Mein Geliebter! Er klopft: Tue mir auf, meine Schwester, meine Freundin, meine Taube, meine Vollkommene! Denn mein Haupt ist voll Tau, meine Locken voll Tropfen der Nacht. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Ich habe mein Kleid ausgezogen, wie sollte ich es wieder anziehen? Ich habe meine Füße gewaschen, wie sollte ich sie wieder beschmutzen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Mein Geliebter streckte seine Hand durch die Öffnung, und mein Inneres ward seinetwegen erregt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Ich stand auf, um meinem Geliebten zu öffnen, und meine Hände troffen von Myrrhe und meine Finger von fließender Myrrhe an dem Griffe des Riegels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Ich öffnete meinem Geliebten; aber mein Geliebter hatte sich umgewandt, war weitergegangen. Ich war außer mir, während er redete. Ich suchte ihn und fand ihn nicht; ich rief ihn und er antwortete mir nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Es fanden mich die Wächter, die in der Stadt umhergehen: sie schlugen mich, verwundeten mich; die Wächter der Mauern nahmen mir meinen Schleier weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Ich beschwöre euch, Töchter Jerusalems, wenn ihr meinen Geliebten findet, was sollt ihr ihm berichten? Daß ich krank bin vor Liebe. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Was ist dein Geliebter vor einem anderen Geliebten, du Schönste unter den Frauen? Was ist dein Geliebter vor einem anderen Geliebten, daß du uns also beschwörst? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Mein Geliebter ist weiß und rot, ausgezeichnet vor Zehntausenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Sein Haupt ist gediegenes, feines Gold, seine Locken sind herabwallend, schwarz wie der Rabe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'seine Augen wie Tauben an Wasserbächen, badend in Milch, eingefaßte Steine;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'seine Wangen wie Beete von Würzkraut, Anhöhen von duftenden Pflanzen; seine Lippen Lilien, träufelnd von fließender Myrrhe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'seine Hände goldene Rollen, mit Topasen besetzt; sein Leib ein Kunstwerk von Elfenbein, bedeckt mit Saphiren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'seine Schenkel Säulen von weißem Marmor, gegründet auf Untersätze von feinem Golde; seine Gestalt wie der Libanon, auserlesen wie die Zedern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'sein Gaumen ist lauter Süßigkeit, und alles an ihm ist lieblich. Das ist mein Geliebter, und das mein Freund, ihr Töchter Jerusalems! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Wohin ist dein Geliebter gegangen, du Schönste unter den Frauen? wohin hat dein Geliebter sich gewendet? Und wir wollen ihn mit dir suchen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Mein Geliebter ist in seinen Garten hinabgegangen, zu den Würzkrautbeeten, um in den Gärten zu weiden und Lilien zu pflücken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Ich bin meines Geliebten; und mein Geliebter ist mein, der unter den Lilien weidet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Du bist schön, meine Freundin, wie Tirza, lieblich wie Jerusalem, furchtbar wie Kriegsscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Wende deine Augen von mir ab, denn sie überwältigen mich. Dein Haar ist wie eine Herde Ziegen, die an den Abhängen des Gilead lagern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'deine Zähne sind wie eine Herde Mutterschafe, die aus der Schwemme heraufkommen, welche allzumal Zwillinge gebären, und keines unter ihnen ist unfruchtbar;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'wie ein Schnittstück einer Granate ist deine Schläfe hinter deinem Schleier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Sechzig sind der Königinnen und achtzig der Kebsweiber, und Jungfrauen ohne Zahl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Eine ist meine Taube, meine Vollkommene; sie ist die einzige ihrer Mutter, sie ist die Auserkorene ihrer Gebärerin. Töchter sahen sie und priesen sie glücklich, Königinnen und Kebsweiber, und sie rühmten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Wer ist sie, die da hervorglänzt wie die Morgenröte, schön wie der Mond, rein wie die Sonne, furchtbar wie Kriegsscharen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'In den Nußgarten ging ich hinab, um die jungen Triebe des Tales zu besehen, um zu sehen, ob der Weinstock ausgeschlagen wäre, ob die Granaten blühten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Unbewußt setzte mich meine Seele auf den Prachtwagen meines willigen Volkes. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Kehre um, kehre um, Sulamith; kehre um, kehre um, daß wir dich anschauen! Was möget ihr an der Sulamith schauen? Wie den Reigen von Machanaim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Wie schön sind deine Tritte in den Schuhen, Fürstentochter! Die Biegungen deiner Hüften sind wie ein Halsgeschmeide, ein Werk von Künstlerhand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Dein Nabel ist eine runde Schale, in welcher der Mischwein nicht mangelt; dein Leib ein Weizenhaufen, umzäunt mit Lilien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Deine beiden Brüste sind wie ein Zwillingspaar junger Gazellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Dein Hals ist wie ein Turm von Elfenbein; deine Augen wie die Teiche zu Hesbon am Tore der volkreichen Stadt; deine Nase wie der Libanonturm, der nach Damaskus hinschaut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Dein Haupt auf dir ist wie der Karmel, und das herabwallende Haar deines Hauptes wie Purpur: ein König ist gefesselt durch deine Locken!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Wie schön bist du, und wie lieblich bist du, o Liebe, unter den Wonnen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Dieser dein Wuchs gleicht der Palme, und deine Brüste den Trauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Ich sprach: Ich will die Palme ersteigen, will ihre Zweige erfassen; und deine Brüste sollen mir sein wie Trauben des Weinstocks, und der Duft deiner Nase wie Äpfel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'und dein Gaumen wie der beste Wein,...der meinem Geliebten sanft hinuntergleitet, der über die Lippen der Schlummernden schleicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Ich bin meines Geliebten und nach mir ist sein Verlangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Komm, mein Geliebter, laß uns aufs Feld hinausgehen, in den Dörfern übernachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Wir wollen uns früh aufmachen nach den Weinbergen, wollen sehen, ob der Weinstock ausgeschlagen ist, die Weinblüte sich geöffnet hat, ob die Granaten blühen; dort will ich dir meine Liebe geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Die Liebesäpfel duften, und über unseren Türen sind allerlei edle Früchte, neue und alte, die ich, mein Geliebter, dir aufbewahrt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'O wärest du mir gleich einem Bruder, der die Brüste meiner Mutter gesogen! Fände ich dich draußen, ich wollte dich küssen; und man würde mich nicht verachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Ich würde dich führen, dich hineinbringen in meiner Mutter Haus, du würdest mich belehren; ich würde dich tränken mit Würzwein, mit dem Moste meiner Granaten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Seine Linke sei unter meinem Haupte, und seine Rechte umfasse mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Ich beschwöre euch, Töchter Jerusalems, daß ihr nicht wecket noch aufwecket die Liebe, bis es ihr gefällt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Wer ist sie, die da heraufkommt von der Wüste her, sich lehnend auf ihren Geliebten? Unter dem Apfelbaume habe ich dich geweckt. Dort hat mit dir Wehen gehabt deine Mutter, dort hat Wehen gehabt, die dich geboren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Lege mich wie einen Siegelring an dein Herz, wie einen Siegelring an deinen Arm! Denn die Liebe ist gewaltsam wie der Tod, hart wie der Scheol ihr Eifer; ihre Gluten sind Feuergluten, eine Flamme Jahs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Große Wasser vermögen nicht die Liebe auszulöschen, und Ströme überfluten sie nicht. Wenn ein Mann allen Reichtum seines Hauses um die Liebe geben wollte, man würde ihn nur verachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Wir haben eine Schwester, eine kleine, die noch keine Brüste hat; was sollen wir mit unserer Schwester tun an dem Tage, da man um sie werben wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Wenn sie eine Mauer ist, so wollen wir eine Zinne von Silber darauf bauen; und wenn sie eine Tür ist, so wollen wir sie mit einem Zedernbrett verschließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Ich bin eine Mauer, und meine Brüste sind wie Türme; da wurde ich in seinen Augen wie eine, die Frieden findet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salomo hatte einen Weinberg zu Baal-Hamon; er übergab den Weinberg den Hütern: ein jeder sollte für seine Frucht tausend Silbersekel bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Mein eigener Weinberg ist vor mir; die tausend sind dein, Salomo, und zweihundert seien den Hütern seiner Frucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Bewohnerin der Gärten, die Genossen horchen auf deine Stimme; laß sie mich hören!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Enteile, mein Geliebter, und sei gleich einer Gazelle oder einem Jungen der Hirsche auf den duftenden Bergen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Das Gesicht Jesajas, des Sohnes Amoz\', welches er über Juda und Jerusalem geschaut hat in den Tagen Ussijas, Jothams, Ahas\', Jehiskias, der Könige von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Höret, ihr Himmel, und horche auf, du Erde! Denn Jehova hat geredet: Ich habe Kinder großgezogen und auferzogen, und sie sind von mir abgefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Ein Ochse kennt seinen Besitzer, und ein Esel die Krippe seines Herrn; Israel hat keine Erkenntnis, mein Volk hat kein Verständnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Wehe der sündigen Nation, dem Volke, belastet mit Ungerechtigkeit, dem Samen der Übeltäter, den verderbt handelnden Kindern! Sie haben Jehova verlassen, haben den Heiligen Israels verschmäht, sind rückwärts gewichen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Warum solltet ihr weiter geschlagen werden, da ihr nur den Abfall mehren würdet? Das ganze Haupt ist krank, und das ganze Herz ist siech.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Von der Fußsohle bis zum Haupte ist nichts Gesundes an ihm: Wunden und Striemen und frische Schläge; sie sind nicht ausgedrückt und nicht verbunden, und nicht erweicht worden mit Öl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Euer Land ist eine Wüste, eure Städte sind mit Feuer verbrannt; eure Flur Fremde verzehren sie vor euren Augen; und eine Wüste ist es, gleich einer Umkehrung durch Fremde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Und die Tochter Zion ist übriggeblieben wie eine Hütte im Weinberge, wie eine Nachthütte im Gurkenfelde, wie eine belagerte Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Wenn Jehova der Heerscharen uns nicht einen gar kleinen Überrest gelassen hätte, wie Sodom wären wir, Gomorra gleich geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Höret das Wort Jehovas, Vorsteher von Sodom; horchet auf das Gesetz unseres Gottes, Volk von Gomorra!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Wozu soll mir die Menge eurer Schlachtopfer? spricht Jehova; ich bin satt der Brandopfer von Widdern und des Fettes der Mastkälber, und am Blute von Farren und Lämmern und jungen Böcken habe ich kein Gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Wenn ihr kommet, um vor meinem Angesicht zu erscheinen, wer hat dieses von eurer Hand gefordert, meine Vorhöfe zu zertreten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Bringet keine eitle Opfergabe mehr! Räucherwerk ist mir ein Greuel. Neumond und Sabbath, das Berufen von Versammlungen: Frevel und Festversammlung mag ich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Eure Neumonde und eure Festzeiten haßt meine Seele; sie sind mir zur Last geworden, ich bin des Tragens müde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Und wenn ihr eure Hände ausbreitet, verhülle ich meine Augen vor euch; selbst wenn ihr des Betens viel machet, höre ich nicht: eure Hände sind voll Blutes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Waschet euch, reiniget euch; schaffet die Schlechtigkeit eurer Handlungen mir aus den Augen, lasset ab vom Übeltun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Lernet Gutes tun, trachtet nach Recht, leitet den Bedrückten; schaffet Recht der Waise, führet der Witwe Sache!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Kommt denn und laßt uns miteinander rechten, spricht Jehova. Wenn eure Sünden wie Scharlach sind, wie Schnee sollen sie weiß werden; wenn sie rot sind wie Karmesin, wie Wolle sollen sie werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Wenn ihr willig seid und höret, so sollt ihr das Gute des Landes essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Wenn ihr euch aber weigert und widerspenstig seid, so sollt ihr vom Schwerte verzehrt werden. Denn der Mund Jehovas hat geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Wie ist zur Hure geworden die treue Stadt! Sie war voll Recht, Gerechtigkeit weilte darin, und jetzt Mörder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Dein Silber ist zu Schlacken geworden, dein edler Wein mit Wasser verdünnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Deine Fürsten sind Widerspenstige und Diebsgesellen, ein jeder von ihnen liebt Geschenke und jagt nach Belohnungen; der Waise schaffen sie nicht Recht, und der Witwe Sache kommt nicht vor sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Darum spricht der Herr, Jehova der Heerscharen, der Mächtige Israels: Ha! Ich werde mich letzen an meinen Widersachern und Rache nehmen an meinen Feinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Und ich werde meine Hand gegen dich wenden, und werde deine Schlacken ausschmelzen wie mit Laugensalz und hinwegschaffen all dein Blei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Und ich werde deine Richter wiederherstellen wie zuerst, und deine Räte wie im Anfang. Danach wird man dich nennen: Stadt der Gerechtigkeit, treue Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Zion wird erlöst werden durch Gericht, und seine Rückkehrenden durch Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Aber Zerschmetterung der Übertreter und der Sünder allzumal; und die Jehova verlassen, werden untergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Denn sie werden beschämt werden wegen der Terebinthen, die ihr begehrt, und ihr werdet mit Scham bedeckt werden wegen der Gärten, an denen ihr Gefallen hattet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Denn ihr werdet sein wie eine Therebinthe, deren Laub verwelkt ist, und wie ein Garten, der kein Wasser hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Und der Starke wird zum Werge werden und sein Tun zum Funken; und sie werden beide miteinander verbrennen, und niemand wird löschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Das Wort, welches Jesaja, der Sohn Amoz\', über Juda und Jerusalem geschaut hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Und es wird geschehen am Ende der Tage, da wird der Berg des Hauses Jehovas feststehen auf dem Gipfel der Berge und erhaben sein über die Hügel; und alle Nationen werden zu ihm strömen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Und viele Völker werden hingehen und sagen: Kommt und laßt uns hinaufziehen zum Berge Jehovas, zum Hause des Gottes Jakobs! Und er wird uns belehren aus seinen Wegen, und wir wollen wandeln in seinen Pfaden. Denn von Zion wird das Gesetz ausgehen, und das Wort Jehovas von Jerusalem;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'und er wird richten zwischen den Nationen und Recht sprechen vielen Völkern. Und sie werden ihre Schwerter zu Pflugmessern schmieden, und ihre Speere zu Winzermessern; nicht wird Nation wider Nation das Schwert erheben, und sie werden den Krieg nicht mehr lernen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Kommt, Haus Jakob, und laßt uns wandeln im Lichte Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Denn du hast dein Volk, das Haus Jakob, verstoßen; denn sie sind voll dessen, was vom Morgenlande kommt, und sind Zauberer gleich den Philistern, und schlagen ein mit den Kindern der Fremden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Und ihr Land ist voll Silber und Gold, und ihrer Schätze ist kein Ende; und ihr Land ist voll Rosse, und ihrer Wagen ist kein Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Und ihr Land ist voll Götzen; sie werfen sich nieder vor dem Werke ihrer Hände, vor dem, was ihre Finger gemacht haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Und der Mensch wird gebeugt und der Mann erniedrigt werden; und du wirst ihnen nicht vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Verkrieche dich in die Felsen und verbirg dich im Staube vor dem Schrecken Jehovas und vor der Pracht seiner Majestät!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Die hochmütigen Augen des Menschen werden erniedrigt, und die Hoffart des Mannes wird gebeugt werden; und Jehova wird hoch erhaben sein, er allein, an jenem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Denn Jehova der Heerscharen hat einen Tag über alles Hoffärtige und Hohe, und über alles Erhabene, und es wird erniedrigt werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'und über alle Zedern des Libanon, die hohen und erhabenen, und über alle Eichen Basans;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'und über alle hohen Berge und über alle erhabenen Hügel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'und über jeden hohen Turm und über jede feste Mauer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'und über alle Tarsisschiffe und über alle kostbaren Schauwerke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Und der Hochmut des Menschen wird gebeugt und die Hoffart des Mannes erniedrigt werden; und Jehova wird hoch erhaben sein, er allein, an jenem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Und die Götzen werden gänzlich verschwinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Und sie werden sich in Felsenhöhlen und in Löcher der Erde verkriechen vor dem Schrecken Jehovas und vor der Pracht seiner Majestät, wenn er sich aufmacht, die Erde zu schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'An jenem Tage wird der Mensch seine Götzen von Silber und seine Götzen von Gold, die man ihm zum Anbeten gemacht hat, den Maulwürfen und den Fledermäusen hinwerfen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'um sich in die Spalten der Felsen und in die Felsenklüfte zu verkriechen vor dem Schrecken Jehovas und vor der Pracht seiner Majestät, wenn er sich aufmacht, die Erde zu schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Lasset ab von dem Menschen, in dessen Nase nur ein Odem ist! Denn wofür ist er zu achten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Denn siehe, der Herr, Jehova der Heerscharen, nimmt von Jerusalem und von Juda Stütze und Unterstützung hinweg, jede Stütze des Brotes und jede Stütze des Wassers;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Held und Kriegsmann, Richter und Prophet und Wahrsager und Ältesten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'den Obersten über fünfzig und den Angesehenen und den Rat, und den geschickten Künstler und den Zauberkundigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Und ich werde Jünglinge zu ihren Fürsten machen, und Buben sollen über sie herrschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Und das Volk wird sich gegenseitig bedrücken, der eine den anderen, und ein jeder seinen Nächsten; der Knabe wird frech auftreten gegen den Greis, und der Verachtete gegen den Geehrten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Wenn jemand seinen Bruder in seines Vaters Hause ergreift und sagt: Du hast ein Kleid, unser Vorsteher sollst du sein; und dieser Einsturz sei unter deiner Hand!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'so wird er an jenem Tage seine Stimme erheben und sagen: Ich kann kein Wundarzt sein; ist doch in meinem Hause weder Brot noch Kleid: machet mich nicht zum Vorsteher des Volkes. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Denn Jerusalem ist gestürzt und Juda gefallen, weil ihre Zunge und ihre Taten wider Jehova sind, um zu trotzen den Augen seiner Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Der Ausdruck ihres Angesichts zeugt wider sie; und von ihrer Sünde sprechen sie offen wie Sodom, sie verhehlen sie nicht. Wehe ihrer Seele! Denn sich selbst bereiten sie Böses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Saget vom Gerechten, daß es ihm wohlgehen wird; denn die Frucht ihrer Handlungen werden sie genießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Wehe dem Gesetzlosen! Es wird ihm übelgehen; denn das Tun seiner Hände wird ihm angetan werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Mein Volk, seine Bedrücker sind Buben, und Weiber herrschen über dasselbe. Mein Volk, deine Leiter führen irre, und den Weg deiner Pfade haben sie dir entrückt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Jehova steht da, um zu rechten; und er tritt auf, um die Völker zu richten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Jehova wird ins Gericht gehen mit den Ältesten seines Volkes und dessen Fürsten: Und ihr, ihr habt den Weinberg abgeweidet, der Raub des Elenden ist in euren Häusern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'was habt ihr, daß ihr mein Volk zertretet und das Angesicht der Elenden zermalmet? spricht der Herr, Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Und Jehova sprach: Weil die Töchter Zions hoffärtig sind, und einhergehen mit gerecktem Halse und blinzelnden Augen, und trippelnd einhergehen und mit ihren Fußspangen klirren:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'so wird der Herr den Scheitel der Töchter Zions kahl machen, und Jehova ihre Scham entblößen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'An jenem Tage wird der Herr wegnehmen den Schmuck der Fußspangen und der Stirnbänder und der Halbmonde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'die Ohrgehänge und die Armketten und die Schleier;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'die Kopfbunde und die Schrittkettchen und die Gürtel und die Riechfläschchen und die Amulette;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'die Fingerringe und die Nasenringe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'die Prachtkleider und die Oberröcke und die Umhänge und die Beutel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'die Handspiegel und die Hemden und die Turbane und die Überwürfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Und es wird geschehen, statt des Wohlgeruchs wird Moder sein, und statt des Gürtels ein Strick, und statt des Lockenwerks eine Glatze, und statt des Prunkgewandes ein Kittel von Sacktuch, Brandmal statt Schönheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Deine Männer werden durchs Schwert fallen, und deine Helden im Kriege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Und ihre Tore werden klagen und trauern, und ausgeleert wird sie sein, sich zur Erde niedersetzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Und an jenem Tage werden sieben Weiber einen Mann ergreifen und sprechen: Wir wollen unser eigenes Brot essen und uns mit unseren eigenen Kleidern bekleiden; nur laß uns nach deinem Namen genannt werden, nimm unsere Schmach hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'An jenem Tage wird der Sproß Jehovas zur Zierde und zur Herrlichkeit sein, und die Frucht der Erde zum Stolz und zum Schmuck für die Entronnenen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Und es wird geschehen, wer in Zion übriggeblieben und wer in Jerusalem übriggelassen ist, wird heilig heißen, ein jeder, der zum Leben eingeschrieben ist in Jerusalem:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'wenn der Herr den Unflat der Töchter Zions abgewaschen und die Blutschulden Jerusalems aus dessen Mitte hinweggefegt haben wird durch den Geist des Gerichts und durch den Geist des Vertilgens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Und Jehova wird über jede Wohnstätte des Berges Zion und über seine Versammlungen eine Wolke und einen Rauch schaffen bei Tage, und den Glanz eines flammenden Feuers bei Nacht; denn über der ganzen Herrlichkeit wird eine Decke sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Und eine Hütte wird sein zum Schatten bei Tage vor der Hitze, und zur Zuflucht und zur Bergung vor Sturm und vor Regen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Wohlan, ich will singen von meinem Geliebten, ein Lied meines Lieben von seinem Weinberge: Mein Geliebter hatte einen Weinberg auf einem fetten Hügel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Und er grub ihn um und säuberte ihn von Steinen und bepflanzte ihn mit Edelreben; und er baute einen Turm in seine Mitte und hieb auch eine Kelter darin aus; und er erwartete, daß er Trauben brächte, aber er brachte Herlinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Nun denn, Bewohner von Jerusalem und Männer von Juda, richtet doch zwischen mir und meinem Weinberge!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Was war noch an meinem Weinberge zu tun, das ich nicht an ihm getan hätte? Warum habe ich erwartet, daß er Trauben brächte, und er brachte Herlinge?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Nun, so will ich euch denn kundmachen, was ich meinem Weinberge tun will: seinen Zaun wegnehmen, daß er abgeweidet werde, seine Mauer niederreißen, daß er zertreten werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Und ich werde ihn zu Grunde richten; er soll nicht beschnitten noch behackt werden, und Dornen und Disteln sollen in ihm aufschießen; und ich will den Wolken gebieten, daß sie keinen Regen auf ihn fallen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Denn der Weinberg Jehovas der Heerscharen ist das Haus Israel, und die Männer von Juda sind die Pflanzung seines Ergötzens; und er wartete auf Recht, und siehe da: Blutvergießen, auf Gerechtigkeit, und siehe da: Wehgeschrei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Wehe denen, die Haus an Haus reihen, Feld an Feld rücken, bis gar kein Raum mehr ist, und ihr allein seßhaft seid inmitten des Landes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Vor meinen Ohren hat Jehova der Heerscharen gesprochen: Wenn nicht die vielen Häuser zur Wüste werden, die großen und schönen ohne Bewohner!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Denn zehn Juchart Weinberge werden ein Bath bringen, und ein Homer Samen wird ein Epha bringen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Wehe denen, die des Morgens früh sich aufmachen, um starkem Getränk nachzulaufen, bis spät am Abend bleiben, der Wein erhitzt sie!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Und Laute und Harfe, Tamburin und Flöte und Wein sind bei ihrem Gelage; aber auf das Tun Jehovas schauen sie nicht, und das Werk seiner Hände sehen sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Darum wird mein Volk weggeführt aus Mangel an Erkenntnis, und seine Edlen verhungern, und seine Menge lechzt vor Durst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Darum sperrt der Scheol weit auf seinen Schlund und reißt seinen Rachen auf ohne Maß; und hinab fährt seine Pracht und sein Getümmel und sein Getöse und wer darin frohlockt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Und der Mensch wird gebeugt und der Mann erniedrigt, und die Augen der Hoffärtigen werden erniedrigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Und Jehova der Heerscharen wird im Gericht erhaben sein, und Gott, der Heilige, sich heilig erweisen in Gerechtigkeit. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Und Schafe werden dort weiden wie auf ihrer Trift, und Fremdlinge in den verwüsteten Fluren der Fetten sich nähren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Wehe denen, welche die Ungerechtigkeit einherziehen mit Stricken der Falschheit, und die Sünde wie mit Wagenseilen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Die da sprechen: Er beeile, er beschleunige sein Werk, damit wir es sehen; und der Ratschluß des Heiligen Israels möge herannahen und kommen, damit wir ihn erfahren! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Wehe denen, die das Böse gut heißen, und das Gute böse; welche Finsternis zu Licht machen, und Licht zu Finsternis; welche Bitteres zu Süßem machen, und Süßes zu Bitterem! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Wehe denen, die in ihren Augen weise und bei sich selbst verständig sind! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Wehe denen, die Helden sind, um Wein zu trinken, und tapfere Männer, um starkes Getränk zu mischen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'welche den Gesetzlosen um eines Geschenkes willen gerecht sprechen, und die Gerechtigkeit der Gerechten ihnen entziehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Darum, wie des Feuers Zunge die Stoppeln verzehrt, und dürres Gras in der Flamme zusammensinkt, so wird ihre Wurzel wie Moder werden, und ihre Blüte auffliegen wie Staub; denn sie haben das Gesetz Jehovas der Heerscharen verworfen und das Wort des Heiligen Israels verschmäht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Darum ist der Zorn Jehovas wider sein Volk entbrannt, und er hat seine Hand gegen dasselbe ausgestreckt und es geschlagen; und die Berge erbebten, und ihre Leichname wurden wie Kehricht inmitten der Straßen. Bei dem allen wendet sich sein Zorn nicht ab, und noch ist seine Hand ausgestreckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Und er wird ein Panier erheben den fernen Nationen, und eine wird er herbeizischen vom Ende der Erde; und siehe, eilends, schnell wird sie kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Bei ihr ist kein Müder und kein Strauchelnder, keiner schlummert noch schläft; auch ist nicht gelöst der Gürtel ihrer Lenden, noch zerrissen der Riemen ihrer Schuhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Ihre Pfeile sind geschärft, und alle ihre Bogen gespannt; die Hufe ihrer Rosse sind Kieseln gleich zu achten, und ihre Räder dem Wirbelwinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Ihr Gebrüll ist wie das einer Löwin, sie brüllt wie die jungen Löwen; und sie knurrt und packt die Beute und bringt sie in Sicherheit, und kein Erretter ist da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Und sie knurrt über ihr an jenem Tage gleich dem Rauschen des Meeres. Und man blickt zur Erde, und siehe, Finsternis, Drangsal; und das Licht ist verfinstert durch ihr Gewölk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Im Todesjahre des Königs Ussija, da sah ich den Herrn sitzen auf hohem und erhabenem Throne, und seine Schleppen erfüllten den Tempel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Seraphim standen über ihm; ein jeder von ihnen hatte sechs Flügel: mit zweien bedeckte er sein Angesicht, und mit zweien bedeckte er seine Füße, und mit zweien flog er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Und einer rief dem anderen zu und sprach: Heilig, heilig, heilig ist Jehova der Heerscharen, die ganze Erde ist voll seiner Herrlichkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Und es erbebten die Grundfesten der Schwellen von der Stimme der Rufenden, und das Haus wurde mit Rauch erfüllt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Und ich sprach: Wehe mir! Denn ich bin verloren; denn ich bin ein Mann von unreinen Lippen, und inmitten eines Volkes von unreinen Lippen wohne ich; denn meine Augen haben den König, Jehova der Heerscharen, gesehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Und einer der Seraphim flog zu mir; und in seiner Hand war eine glühende Kohle, die er mit der Zange vom Altar genommen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Und er berührte meinen Mund damit und sprach: Siehe, dieses hat deine Lippen berührt; und so ist deine Ungerechtigkeit gewichen und deine Sünde gesühnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Und ich hörte die Stimme des Herrn, welcher sprach: Wen soll ich senden, und wer wird für uns gehen? Da sprach ich: Hier bin ich, sende mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Und er sprach: Geh hin und sprich zu diesem Volke: Hörend höret, und verstehet nicht; und sehend sehet, und erkennet nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Mache das Herz dieses Volkes fett, und mache seine Ohren schwer, und verklebe seine Augen: damit es mit seinen Augen nicht sehe und mit seinen Ohren nicht höre und sein Herz nicht verstehe, und es nicht umkehre und geheilt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Und ich sprach: Wie lange, Herr? Und er sprach: Bis die Städte verwüstet sind, ohne Bewohner, und die Häuser ohne Menschen, und das Land zur Öde verwüstet ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'und Jehova die Menschen weit entfernt hat, und der verlassenen Orte viele sind inmitten des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Und ist noch ein Zehntel darin, so wird es wiederum vertilgt werden, gleich der Terebinthe und gleich der Eiche, von welchen, wenn sie gefällt sind, ein Wurzelstock bleibt; ein heiliger Same ist sein Wurzelstock.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Und es geschah in den Tagen Ahas\', des Sohnes Jothams, des Sohnes Ussijas, des Königs von Juda, da zog Rezin, der König von Syrien, und Pekach, der Sohn Remaljas, der König von Israel, nach Jerusalem hinauf zum Streit wider dasselbe; aber er vermochte nicht wider dasselbe zu streiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Und es wurde dem Hause David berichtet und gesagt: Syrien hat sich in Ephraim gelagert. Da bebte sein Herz und das Herz seines Volkes, wie die Bäume des Waldes vor dem Winde beben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Und Jehova sprach zu Jesaja: Geh doch hinaus, dem Ahas entgegen, du und dein Sohn Schear-Jaschub, an das Ende der Wasserleitung des oberen Teiches, nach der Straße des Walkerfeldes hin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'und sprich zu ihm: Hüte dich und halte dich ruhig; fürchte dich nicht, und dein Herz verzage nicht vor diesen beiden rauchenden Brandscheitstümpfen, bei der Zornglut Rezins und Syriens und des Sohnes Remaljas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Darum, daß Syrien Böses wider dich beratschlagt hat, Ephraim und der Sohn Remaljas und gesagt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Laßt uns wider Juda hinaufziehen und ihm Grauen einjagen und es uns erobern und den Sohn Tabeels zum König darin machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'so spricht der Herr Jehova: Es wird nicht zustande kommen und nicht geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Denn Damaskus ist das Haupt von Syrien, und Rezin das Haupt von Damaskus; und in noch fünfundsechzig Jahren wird Ephraim zerschmettert werden, daß es kein Volk mehr sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Und Samaria ist das Haupt von Ephraim, und der Sohn Remaljas das Haupt von Samaria. Wenn ihr nicht glaubet, werdet ihr, fürwahr, keinen Bestand haben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Und Jehova fuhr fort, zu Ahas zu reden, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Fordere dir ein Zeichen von Jehova, deinem Gott; fordere es in der Tiefe oder oben in der Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Und Ahas sprach: Ich will nicht fordern und will Jehova nicht versuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Da sprach er: Höret doch, Haus David! Ist es euch zu wenig, Menschen zu ermüden, daß ihr auch meinen Gott ermüdet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Darum wird der Herr selbst euch ein Zeichen geben: Siehe, die Jungfrau wird schwanger werden und einen Sohn gebären, und wird seinen Namen Immanuel heißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Rahm und Honig wird er essen, wenn er weiß, das Böse zu verwerfen und das Gute zu erwählen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Denn ehe der Knabe weiß, das Böse zu verwerfen und das Gute zu erwählen, wird das Land verlassen sein, vor dessen beiden Königen dir graut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Jehova wird über dich und über dein Volk und über das Haus deines Vaters Tage kommen lassen, wie sie nicht gekommen sind seit dem Tage, da Ephraim von Juda gewichen ist, den König von Assyrien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Und es wird geschehen an jenem Tage, da wird Jehova die Fliege, die am Ende der Ströme Ägyptens, und die Biene, die im Lande Assyrien ist, herbeizischen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'Und sie werden kommen und sich allesamt niederlassen in den Tälern der steilen Höhen und in den Spalten der Felsen und in allen Dornstäuchern und auf allen Triften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'An jenem Tage wird der Herr durch ein gedungenes Schermesser, auf der anderen Seite des Stromes, durch den König von Assyrien, das Haupt und das Haar der Beine abscheren; ja, auch den Bart wird es wegnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Und es wird geschehen an jenem Tage, daß jemand eine junge Kuh und zwei Schafe füttern wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'Und es wird geschehen, wegen der Menge des Milchertrags wird er Rahm essen, denn Rahm und Honig wird jeder essen, der im Lande übriggeblieben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Und es wird geschehen an jenem Tage, daß jeder Ort, wo tausend Weinstöcke von tausend Silbersekel waren, zu Dornen und Disteln geworden sein wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Mit Pfeilen und mit Bogen wird man dorthin kommen; denn das ganze Land wird Dornen und Disteln sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, '(H7:24) Und alle Berge, die mit der Hacke behackt wurden, dahin wirst du nicht kommen, aus Furcht vor Dornen und Disteln; und sie werden ein Ort sein, wohin man Rinder treibt, und welcher vom Kleinvieh zertreten wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Und Jehova sprach zu mir: Nimm dir eine große Tafel und schreibe darauf mit Menschengriffel: Es eilt der Raub, bald kommt die Beute;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'und ich will mir zuverlässige Zeugen nehmen: Urija, den Priester, und Sacharja, den Sohn Jeberekjas. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Und ich nahte der Prophetin, und sie ward schwanger und gebar einen Sohn. Und Jehova sprach zu mir: Gib ihm den Namen: \"Es eilt der Raub, bald kommt die Beute\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Denn ehe der Knabe zu rufen weiß \"mein Vater\" und \"meine Mutter\", wird man vor dem König von Assyrien hertragen den Reichtum von Damaskus und die Beute von Samaria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Und Jehova fuhr fort, weiter zu mir zu reden, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Darum, daß dieses Volk die Wasser von Siloah verachtet, die still fließen, und Freude hat an Rezin und an dem Sohne Remaljas:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'darum, siehe, läßt der Herr über sie heraufkommen die Wasser des Stromes, die mächtigen und großen, den König von Assyrien und alle seine Herrlichkeit; und er wird über alle seine Betten steigen und über alle seine Ufer gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Und er wird in Juda eindringen, überschwemmen und überfluten; bis an den Hals wird er reichen. Und die Ausdehnung seiner Flügel wird die Breite deines Landes füllen, Immanuel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Tobet, ihr Völker, und werdet zerschmettert! Und nehmet es zu Ohren, alle ihr Fernen der Erde! Gürtet euch und werdet zerschmettert, gürtet euch und werdet zerschmettert!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Beschließet einen Ratschlag, und er soll vereitelt werden; redet ein Wort, und es soll nicht zustande kommen; denn Gott ist mit uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Denn also hat Jehova zu mir gesprochen, indem seine Hand stark auf mir war und er mich warnte, nicht auf dem Wege dieses Volkes zu wandeln:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Ihr sollt nicht alles Verschwörung nennen, was dieses Volk Verschwörung nennt; und fürchtet nicht ihre Furcht und erschrecket nicht davor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Jehova der Heerscharen, den sollt ihr heiligen; und er sei eure Furcht, und er sei euer Schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Und er wird zum Heiligtum sein; aber zum Stein des Anstoßes und zum Fels des Strauchelns den beiden Häusern Israels, zur Schlinge und zum Fallstrick den Bewohnern von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Und viele unter ihnen werden straucheln, und werden fallen und zerschmettert und verstrickt und gefangen werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Binde das Zeugnis zu, versiegele das Gesetz unter meinen Jüngern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Und ich will auf Jehova harren, der sein Angesicht verbirgt vor dem Hause Jakob, und will auf ihn hoffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Siehe, ich und die Kinder, die Jehova mir gegeben hat, wir sind zu Zeichen und zu Wundern in Israel, vor Jehova der Heerscharen, der da wohnt auf dem Berge Zion.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Und wenn sie zu euch sprechen werden: Befraget die Totenbeschwörer und die Wahrsager, die da flüstern und murmeln, so sprechet: Soll nicht ein Volk seinen Gott befragen? Soll es für die Lebenden die Toten befragen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'Zum Gesetz und zum Zeugnis! Wenn sie nicht nach diesem Worte sprechen, so gibt es für sie keine Morgenröte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Und es wird darin umherziehen, schwer gedrückt und hungernd. Und es wird geschehen, wenn es Hunger leidet, so wird es erzürnt sein und seinen König und seinen Gott verfluchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'Und es wird aufwärts schauen und wird zur Erde blicken: und siehe, Drangsal und Finsternis, angstvolles Dunkel; und in dichte Finsternis ist es hineingestoßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Doch nicht bleibt Finsternis dem Lande, welches Bedrängnis hat. Um die erste Zeit hat er das Land Sebulon und das Land Naphtali verächtlich gemacht; und in der letzten bringt er zu Ehren den Weg am Meere, das Jenseitige des Jordan, den Kreis der Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Das Volk, das im Finstern wandelt, hat ein großes Licht gesehen; die da wohnen im Lande des Todesschattens, Licht hat über sie geleuchtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Du hast die Nation vermehrt, hast ihr groß gemacht die Freude; sie freuen sich vor dir, gleich der Freude in der Ernte, wie man frohlockt beim Verteilen der Beute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Denn das Joch ihrer Last und den Stab ihrer Schulter, den Stock ihres Treibers hast du zerschlagen wie am Tage Midians.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Denn jeder Stiefel der Gestiefelten im Getümmel, und jedes Gewand, in Blut gewälzt, die werden zum Brande, ein Fraß des Feuers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Denn ein Kind ist uns geboren, ein Sohn uns gegeben, und die Herrschaft ruht auf seiner Schulter; und man nennt seinen Namen: Wunderbarer, Berater, starker Gott, Vater der Ewigkeit, Friedefürst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Die Mehrung der Herrschaft und der Friede werden kein Ende haben auf dem Throne Davids und über sein Königreich, um es zu befestigen und zu stützen durch Gericht und durch Gerechtigkeit, von nun an bis in Ewigkeit. Der Eifer Jehovas der Heerscharen wird dieses tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Der Herr hat ein Wort gesandt wider Jakob, und es steigt hernieder in Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Und das ganze Volk wird es erfahren, Ephraim und die Bewohner von Samaria, die in Hochmut und in Überhebung des Herzens sprechen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Die Ziegelsteine sind eingefallen, aber mit behauenen Steinen bauen wir auf; die Sykomoren sind abgehauen, aber wir setzen Zedern an ihre Stelle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Denn Jehova wird die Bedränger Rezins über dasselbe erheben und seine Feinde aufreizen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'die Syrer von Osten und die Philister von Westen; und sie werden Israel fressen mit vollem Maule. Bei dem allen wendet sich sein Zorn nicht ab, und noch ist seine Hand ausgestreckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Und das Volk kehrt nicht um zu dem, der es schlägt, und Jehova der Heerscharen suchen sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Und Jehova wird aus Israel Haupt und Schwanz, Palmzweig und Binse ausrotten an einem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Der Älteste und Angesehene, er ist das Haupt; und der Prophet, der Lüge lehrt, er ist der Schwanz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Denn die Leiter dieses Volkes führen irre, und die von ihnen Geleiteten werden verschlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Darum wird sich der Herr über dessen Jünglinge nicht freuen, und seiner Waisen und seiner Witwen sich nicht erbarmen; denn sie allesamt sind Ruchlose und Übeltäter, und jeder Mund redet Torheit. Bei dem allen wendet sich sein Zorn nicht ab, und noch ist seine Hand ausgestreckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Denn die Gesetzlosigkeit brennt wie Feuer: sie verzehrt Dornen und Disteln, und zündet in den Dickichten des Waldes, daß sie emporwirbeln in hoch aufsteigendem Rauche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Durch den Grimm Jehovas der Heerscharen ist das Land verbrannt, und das Volk ist wie eine Speise des Feuers geworden; keiner schont den anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Und man schlingt zur Rechten und hungert, und man frißt zur Linken und wird nicht satt. Sie fressen ein jeder das Fleisch seines eigenen Armes:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manasse den Ephraim, und Ephraim den Manasse; diese miteinander fallen über Juda her. Bei dem allen wendet sich sein Zorn nicht ab, und noch ist seine Hand ausgestreckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Wehe denen, die Satzungen des Unheils verordnen, und den Schreibern, welche Mühsal ausfertigen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'um die Armen vom Gericht zu verdrängen und die Elenden meines Volkes ihres Rechtes zu berauben, damit die Witwen ihre Beute werden und sie die Waisen plündern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Und was wollt ihr tun am Tage der Heimsuchung und beim Sturme, der von fern daherkommt? Zu wem sollt ihr fliehen um Hilfe, und wohin eure Herrlichkeit in Sicherheit bringen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Nichts anderes bleibt übrig, als unter Gefesselten sich zu krümmen; und unter Erschlagenen fallen sie hin. Bei dem allen wendet sich sein Zorn nicht ab, und noch ist seine Hand ausgestreckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'He! Assyrer, Rute meines Zornes! Und der Stock in seiner Hand ist mein Grimm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Wider eine ruchlose Nation werde ich ihn senden und gegen das Volk meines Grimmes ihn entbieten, um Raub zu rauben und Beute zu erbeuten, und es der Zertretung hinzugeben gleich Straßenkot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Er aber meint es nicht also, und sein Herz denkt nicht also; sondern zu vertilgen hat er im Sinne und auszurotten nicht wenige Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Denn er spricht: Sind nicht meine Fürsten allesamt Könige?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Ist nicht Kalno wie Karchemis? Nicht Hamath wie Arpad? Nicht Samaria wie Damaskus?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'So wie meine Hand die Königreiche der Götzen erreicht hat und ihre geschnitzten Bilder waren mehr als die von Jerusalem und von Samaria-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'werde ich nicht, wie ich Samaria und seinen Götzen getan habe, ebenso Jerusalem und seinen Götzen tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Und es wird geschehen, wenn der Herr sein ganzes Werk an dem Berge Zion und an Jerusalem vollbracht hat, so werde ich heimsuchen die Frucht der Überhebung des Herzens des Königs von Assyrien und den Stolz der Hoffart seiner Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Denn er hat gesagt: Durch die Kraft meiner Hand und durch meine Weisheit habe ich es getan, denn ich bin verständig; und ich verrückte die Grenzen der Völker und plünderte ihre Schätze und stieß, als ein Gewaltiger, Thronende hinab;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'und meine Hand hat den Reichtum der Völker erreicht wie ein Nest, und wie man verlassene Eier zusammenrafft, so habe ich die ganze Erde zusammengerafft: da war keiner, der den Flügel regte, oder den Schnabel aufsperrte und zirpte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Darf die Axt sich rühmen wider den, der damit haut? Oder die Säge sich brüsten wider den, der sie zieht? Als schwänge ein Stock die, welche ihn emporheben, als höbe ein Stab den empor, der kein Holz ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Darum wird der Herr, Jehova der Heerscharen, Magerkeit senden unter seine Fetten; und unter seiner Herrlichkeit wird ein Brand auflodern wie ein Feuerbrand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Und das Licht Israels wird zum Feuer werden, und sein Heiliger zur Flamme, die seine Dornen und seine Disteln in Brand setzen und verzehren wird an einem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Und er wird die Herrlichkeit seines Waldes und seines Fruchtgefildes von der Seele bis zum Fleische vernichten, daß es sein wird, wie wenn ein Kranker hinsiecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Und der Rest der Bäume seines Waldes wird zu zählen sein: ein Knabe könnte sie aufschreiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Und es wird geschehen an jenem Tage, da wird der Überrest Israels und das Entronnene des Hauses Jakob sich nicht mehr stützen auf den, der es schlägt; sondern es wird sich stützen auf Jehova, den Heiligen Israels, in Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Der Überrest wird umkehren, der Überrest Jakobs zu dem starken Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Denn wenn auch dein Volk, Israel, wie der Sand des Meeres wäre, nur ein Überrest davon wird umkehren. Vertilgung ist festbeschlossen, sie bringt einherflutend Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Denn der Herr, Jehova der Heerscharen, vollführt Vernichtung und Festbeschlossenes inmitten der ganzen Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Darum spricht der Herr, Jehova der Heerscharen, also: Fürchte dich nicht, mein Volk, das in Zion wohnt, vor Assur, wenn er dich mit dem Stocke schlagen und seinen Stab wider dich erheben wird nach der Weise Ägyptens!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Denn noch um ein gar Kleines, so wird der Grimm zu Ende sein und mein Zorn sich wenden zu ihrer Vernichtung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Und Jehova der Heerscharen wird über ihn die Geißel schwingen wie in der Niederlage Midians am Felsen Oreb; und sein Stab wird über das Meer sein, und er wird ihn erheben, wie er ihn über Ägypten erhob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Und es wird geschehen an jenem Tage, daß seine Last weichen wird von deiner Schulter und sein Joch von deinem Halse; und das Joch wird gesprengt werden infolge des Fettes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Er kommt gegen Aijath, zieht durch Migron; in Mikmas legt er sein Gepäck ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Sie ziehen über den Paß, zu Geba schlagen sie ihr Nachtlager auf. Rama bebt, Gibea Sauls flieht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Schreie laut, Tochter Gallims! Horche auf, Lais! Armes Anathoth!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena eilt davon, die Bewohner von Gebim flüchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Noch heute macht er halt in Nob; er schwingt seine Hand gegen den Berg der Tochter Zion, den Hügel Jerusalems. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Siehe, der Herr, Jehova der Heerscharen, haut mit Schreckensgewalt die Äste herunter; und die von hohem Wuchse werden gefällt, und die Emporragenden werden erniedrigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Und er schlägt die Dickichte des Waldes nieder mit dem Eisen, und der Libanon fällt durch einen Mächtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Und ein Reis wird hervorgehen aus dem Stumpfe Isais, und ein Schößling aus seinen Wurzeln wird Frucht bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Und auf ihm wird ruhen der Geist Jehovas, der Geist der Weisheit und des Verstandes, der Geist des Rates und der Kraft, der Geist der Erkenntnis und Furcht Jehovas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'und sein Wohlgefallen wird sein an der Furcht Jehovas. Und er wird nicht richten nach dem Sehen seiner Augen, und nicht Recht sprechen nach dem Hören seiner Ohren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'und er wird die Geringen richten in Gerechtigkeit, und den Demütigen des Landes Recht sprechen in Geradheit. Und er wird die Erde schlagen mit der Rute seines Mundes, und mit dem Hauche seiner Lippen den Gesetzlosen töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Und Gerechtigkeit wird der Gurt seiner Lenden sein, und die Treue der Gurt seiner Hüften. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Und der Wolf wird bei dem Lamme weilen, und der Pardel bei dem Böcklein lagern; und das Kalb und der junge Löwe und das Mastvieh werden zusammen sein, und ein kleiner Knabe wird sie treiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Und Kuh und Bärin werden miteinander weiden, ihre Jungen zusammen lagern; und der Löwe wird Stroh fressen wie das Rind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Und der Säugling wird spielen an dem Loche der Natter, und das entwöhnte Kind seine Hand ausstrecken nach der Höhle des Basilisken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Man wird nicht übeltun, noch verderbt handeln auf meinem ganzen heiligen Gebirge; denn die Erde wird voll sein der Erkenntnis Jehovas, gleichwie die Wasser den Meeresgrund bedecken. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Und es wird geschehen an jenem Tage: der Wurzelsproß Isais, welcher dasteht als Panier der Völker, nach ihm werden die Nationen fragen; und seine Ruhestätte wird Herrlichkeit sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Und es wird geschehen an jenem Tage, da wird der Herr noch zum zweiten Male seine Hand ausstrecken, um den Überrest seines Volkes, der übrigbleiben wird, loszukaufen aus Assyrien und aus Ägypten und aus Pathros und aus Äthiopien und aus Elam und aus Sinear und aus Hamath und aus den Inseln des Meeres.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Und er wird den Nationen ein Panier erheben und die Vertriebenen Israels zusammenbringen, und die Zerstreuten Judas wird er sammeln von den vier Enden der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Und der Neid Ephraims wird weichen, und die Bedränger Judas werden ausgerottet werden; Ephraim wird Juda nicht beneiden, und Juda wird Ephraim nicht bedrängen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Und sie werden den Philistern auf die Schultern fliegen gegen Westen, werden miteinander plündern die Söhne des Ostens; an Edom und Moab werden sie ihre Hand legen, und die Kinder Ammon werden ihnen gehorsam sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Und Jehova wird die Meereszunge Ägyptens zerstören; und er wird seine Hand über den Strom schwingen mit der Glut seines Hauches, und ihn in sieben Bäche zerschlagen und machen, daß man mit Schuhen hindurchgeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Und so wird eine Straße sein von Assyrien her für den Überrest seines Volkes, der übrigbleiben wird, wie eine Straße für Israel war an dem Tage, da es aus dem Lande Ägypten heraufzog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Und an jenem Tage wirst du sagen: Ich preise dich, Jehova; denn du warst gegen mich erzürnt: dein Zorn hat sich gewendet, und du hast mich getröstet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Siehe, Gott ist mein Heil, ich vertraue, und fürchte mich nicht; denn Jah, Jehova, ist meine Stärke und mein Gesang, und er ist mir zum Heil geworden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Und mit Wonne werdet ihr Wasser schöpfen aus den Quellen des Heils,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'und werdet sprechen an jenem Tage: Preiset Jehova, rufet seinen Namen aus, machet unter den Völkern kund seine Taten, verkündet, daß sein Name hoch erhaben ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Besinget Jehova, denn Herrliches hat er getan; solches werde kund auf der ganzen Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Jauchze und jubele, Bewohnerin von Zion! Denn groß ist in deiner Mitte der Heilige Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Ausspruch über Babel, welchen Jesaja, der Sohn Amoz\', geschaut hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Erhebet ein Panier auf kahlem Berge, rufet ihnen zu mit lauter Stimme, schwinget die Hand, daß sie einziehen in die Tore der Edlen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Ich habe meine Geheiligten entboten, auch meine Helden gerufen zu meinem Zorne, meine stolz Frohlockenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Horch! Ein Getümmel auf den Bergen, wie von einem großen Volke; horch! Ein Getöse von Königreichen versammelter Nationen: Jehova der Heerscharen mustert ein Kriegsheer,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'aus fernem Lande Gekommene, vom Ende des Himmels, Jehova und die Werkzeuge seines Grimmes, um das ganze Land zu verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Heulet, denn nahe ist der Tag Jehovas; er kommt wie eine Verwüstung vom Allmächtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Darum werden alle Hände erschlaffen, und jedes Menschenherz wird zerschmelzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Und sie werden bestürzt sein, Wehen und Schmerzen werden sie ergreifen, sie werden sich winden gleich einer Gebärenden; einer starrt den anderen an, ihre Angesichter glühen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Siehe, der Tag Jehovas kommt grausam, und Grimm und Zornglut, um die Erde zur Wüste zu machen; und ihre Sünder wird er von derselben vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Denn die Sterne des Himmels und seine Gestirne werden ihr Licht nicht leuchten lassen; die Sonne wird finster sein bei ihrem Aufgang, und der Mond wird sein Licht nicht scheinen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Und ich werde an dem Erdkreis heimsuchen die Bosheit, und an den Gesetzlosen ihre Missetat; und ich werde ein Ende machen dem Hochmut der Stolzen und die Hoffart der Gewalttätigen erniedrigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Ich will den Sterblichen kostbarer machen als gediegenes Gold, und den Menschen als Gold von Ophir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Darum werde ich die Himmel erzittern machen, und die Erde wird aufbeben von ihrer Stelle: beim Grimme Jehovas der Heerscharen und am Tage seiner Zornglut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Und es wird sein wie mit einer verscheuchten Gazelle und wie mit einer Herde, die niemand sammelt: ein jeder wird sich zu seinem Volke wenden, und ein jeder in sein Land fliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Wer irgend gefunden wird, wird durchbohrt werden; und wer irgend erhascht wird, wird durchs Schwert fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Und ihre Kinder werden vor ihren Augen zerschmettert, ihre Häuser geplündert und ihre Weiber geschändet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Siehe, ich erwecke wider sie die Meder, welche Silber nicht achten, und an Gold kein Gefallen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Und ihre Bogen werden Jünglinge niederstrecken, und über die Leibesfrucht werden sie sich nicht erbarmen, ihr Auge wird der Kinder nicht schonen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Und Babel, die Zierde der Königreiche, der Stolz des Hochmuts der Chaldäer, wird gleich sein der Umkehrung Sodoms und Gomorras durch Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Es wird in Ewigkeit nicht bewohnt werden, und keine Niederlassung mehr sein von Geschlecht zu Geschlecht; und der Araber wird dort nicht zelten, und Hirten werden dort nicht lagern lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Aber Wüstentiere werden dort lagern, und ihre Häuser mit Uhus angefüllt sein; und Strauße werden dort wohnen und Böcke dort hüpfen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'und wilde Hunde werden heulen in seinen Palästen und Schakale in den Lustschlössern. Und seine Zeit steht nahe bevor, und seine Tage werden nicht verlängert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Denn Jehova wird sich Jakobs erbarmen und Israel noch erwählen, und wird sie in ihr Land einsetzen. Und der Fremdling wird sich ihnen anschließen, und sie werden sich dem Hause Jakob zugesellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Und die Völker werden sie nehmen und sie an ihren Ort bringen; und das Haus Israel wird sich dieselben zu Knechten und zu Mägden zueignen im Lande Jehovas. Und sie werden gefangen wegführen, die sie gefangen wegführten, und werden herrschen über ihre Bedrücker.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Und es wird geschehen an dem Tage, an welchem Jehova dir Ruhe schafft von deiner Mühsal und von deiner Unruhe und von dem harten Dienst, welchen man dir auferlegt hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'da wirst du diesen Spruch anheben über den König von Babel und sprechen: Wie hat aufgehört der Bedrücker, aufgehört die Erpressung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Zerbrochen hat Jehova den Stab der Gesetzlosen, den Herrscherstab,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'welcher Völker schlug im Grimme mit Schlägen ohne Unterlaß, Nationen unterjochte im Zorn mit Verfolgung ohne Einhalt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Es ruht, es rastet die ganze Erde; man bricht in Jubel aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Auch die Zypressen freuen sich über dich, die Zedern des Libanon: \"Seit du daliegst, kommt niemand mehr herauf, uns abzuhauen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Der Scheol drunten ist in Bewegung um deinetwillen, deiner Ankunft entgegen; er stört deinetwegen die Schatten auf, alle Mächtigen der Erde, er läßt von ihren Thronen aufstehen alle Könige der Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Sie alle heben an und sagen zu dir: \"Auch du bist kraftlos geworden wie wir, bist uns gleich geworden!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'In den Scheol hinabgestürzt ist deine Pracht, das Rauschen deiner Harfen. Maden sind unter dir gebettet, und Würmer sind deine Decke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Wie bist du vom Himmel gefallen, du Glanzstern, Sohn der Morgenröte! Zur Erde gefällt, Überwältiger der Nationen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Und du, du sprachst in deinem Herzen: \"Zum Himmel will ich hinaufsteigen, hoch über die Sterne Gottes meinen Thron erheben, und mich niedersetzen auf den Versammlungsberg im äußersten Norden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Ich will hinauffahren auf Wolkenhöhen, mich gleichmachen dem Höchsten.\" -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Doch in den Scheol wirst du hinabgestürzt, in die tiefste Grube.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Die dich sehen, betrachten dich, schauen dich an: \"Ist das der Mann, der die Erde beben machte, Königreiche erschütterte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'der den Erdkreis der Wüste gleich machte und dessen Städte niederriß, dessen Gefangene nicht in die Heimat entließ?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Alle Könige der Nationen insgesamt liegen mit Ehren, ein jeder in seinem Hause;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'du aber bist hingeworfen fern von deiner Grabstätte, wie ein verabscheuter Schößling, bedeckt mit Erschlagenen, vom Schwerte Durchbohrten, die zu den Steinen der Grube hinabgefahren sind, wie ein zertretenes Aas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Nicht wirst du mit ihnen vereint werden im Begräbnis; denn du hast dein Land zu Grunde gerichtet, dein Volk hingemordet. Der Same der Übeltäter wird nicht genannt werden in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Bereitet seinen Söhnen die Schlachtung, um der Missetat ihrer Väter willen! Nicht sollen sie aufstehen und die Erde in Besitz nehmen, und mit Städten füllen die Fläche des Erdkreises.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Und ich werde wider sie aufstehen, spricht Jehova der Heerscharen, und werde von Babel ausrotten Namen und Überrest, und Sohn und Nachkommen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'Und ich werde es zum Besitztum der Igel machen und zu Wassersümpfen; und ich werde es ausfegen mit dem Besen der Vertilgung, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Jehova der Heerscharen hat geschworen und gesprochen: Wahrlich! Wie ich es vorbedacht, also geschieht es; und wie ich es beschlossen habe, also wird es zustande kommen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'daß ich Assyrien in meinem Lande zerschmettern und es auf meinen Bergen zertreten werde. Und so wird sein Joch von ihnen weichen, und seine Last wird weichen von ihrer Schulter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Das ist der Ratschluß, der beschlossen ist über die ganze Erde; und das ist die Hand, die ausgestreckt ist über alle Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Denn Jehova der Heerscharen hat es beschlossen, und wer wird es vereiteln? Und seine ausgestreckte Hand, wer könnte sie abwenden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Im Todesjahre des Königs Ahas geschah dieser Ausspruch:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Freue dich nicht gänzlich Philistäa, daß zerbrochen ist der Stock, der dich schlug! Denn aus der Wurzel der Schlange wird ein Basilisk hervorkommen, und seine Frucht wird sein eine fliegende, feurige Schlange.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Und die Erstgeborenen der Armen werden weiden, und die Dürftigen sich in Sicherheit lagern; aber deine Wurzel werde ich durch Hunger töten, und deinen Überrest wird er umbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Heule, Tor! Schreie Stadt! Gänzlich hinschmelzen sollst du, Philistäa; denn von Norden her kommt Rauch und kein Vereinzelter ist unter seinen Scharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Und was antwortet man den Boten der Nationen? Daß Jehova Zion gegründet hat, und daß die Elenden seines Volkes darin Zuflucht finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Ausspruch über Moab. Denn über Nacht ist Ar-Moab verwüstet, vernichtet; denn über Nacht ist Kir-Moab verwüstet, vernichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Man steigt zum Götzentempel hinauf, und nach Dibon auf die Höhen, um zu weinen; auf Nebo und auf Medeba jammert Moab; auf allen seinen Häuptern ist eine Glatze, jeder Bart ist abgeschoren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Auf seinen Gassen gürten sie sich Sacktuch um, auf seinen Dächern und auf seinen Märkten jammert alles, zerfließend in Tränen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Und Hesbon schreit und Elale; bis Jahaz wird ihre Stimme gehört. Darum schreien die Gerüsteten Moabs laut auf, seine Seele bebt in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Mein Herz schreit über Moab, seine Flüchtlinge fliehen bis Zoar, bis Eglath-Schelischija. Denn die Anhöhe von Luchith steigt man mit Weinen hinauf; denn auf dem Wege nach Horonaim erhebt man Jammergeschrei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Denn die Wasser von Nimrim sollen zu Wüsten werden. Denn verdorrt ist das Gras, verschmachtet das Kraut; das Grün ist nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Darum tragen sie was sie erübrigt haben und ihr Aufbewahrtes über den Weidenbach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Denn das Wehgeschrei hat die Runde gemacht in den Grenzen von Moab: bis Eglaim dringt sein Jammern, und bis Beer-Elim sein Jammern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Denn die Wasser Dimons sind voll von Blut; denn ich verhänge noch mehr Unheil über Dimon: einen Löwen über die Entronnenen Moabs und über den Überrest des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Sendet die Fettschafe des Landesherrschers von Sela durch die Wüste nach dem Berge der Tochter Zion.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Und es geschieht, wie umherflatternde Vögel, wie ein aufgescheuchtes Nest sind die Töchter Moabs an den Übergängen des Arnon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Schaffe Rat, triff Entscheidung; mache deinen Schatten der Nacht gleich am hellen Mittag, verbirg die Vertriebenen, den Flüchtling entdecke nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Laß meine Vertriebenen bei dir weilen, Moab! Sei ein Schutz vor dem Verwüster! Denn der Bedrücker hat ein Ende, die Zerstörung hat aufgehört, die Zertreter sind aus dem Lande verschwunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Und ein Thron wird durch Güte aufgerichtet werden; und auf ihm wird im Zelte Davids einer sitzen in Wahrheit, der da richtet und nach Recht trachtet und der Gerechtigkeit kundig ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Wir haben vernommen den Hochmut Moabs, des sehr Hochmütigen, seine Hoffart und seinen Hochmut und sein Wüten, sein eitles Prahlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Darum wird Moab heulen über Moab; alles wird heulen. Um die Traubenkuchen von Kir-Hareseth werdet ihr seufzen, tief betrübt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'denn Hesbons Fluren sind verwelkt, der Weinstock von Sibma. Die Herren der Nationen schlugen seine Edelreben nieder; sie reichten bis Jaser, irrten durch die Wüste; seine Ranken breiteten sich aus, gingen über das Meer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Darum weine ich mit dem Weinen Jasers über den Weinstock von Sibma, ich überströme dich mit meinen Tränen, Hesbon und Elale. Denn über deine Obsternte und über deine Weinlese ist ein lauter Ruf gefallen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'und verschwunden sind Freude und Frohlocken aus dem Fruchtgefilde, und in den Weinbergen wird nicht gejubelt, nicht gejauchzt; der Keltertreter tritt keinen Wein in den Keltern; dem lauten Rufe habe ich ein Ende gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Darum rauschen meine Eingeweide wegen Moabs wie eine Laute, und mein Inneres wegen Kir-Heres\'.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Und es wird geschehen, wenn Moab erscheint, sich abmüht auf der Höhe und in sein Heiligtum eintritt, um zu beten, so wird es nichts ausrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Das ist das Wort, welches Jehova vorlängst über Moab geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Jetzt aber redet Jehova und spricht: In drei Jahren, wie die Jahre eines Tagelöhners, da wird die Herrlichkeit Moabs verächtlich gemacht werden samt all der großen Menge; und der Überrest wird sehr gering, nicht groß sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Ausspruch über Damaskus. Siehe, Damaskus hört auf, eine Stadt zu sein, und wird ein Trümmerhaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Verlassen sind die Städte Aroer, sie werden den Herden preisgegeben; und diese lagern, und niemand schreckt sie auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Und die Festung nimmt ein Ende in Ephraim und das Königtum in Damaskus, sowie der Überrest von Syrien: er wird sein wie die Herrlichkeit der Kinder Israel, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Und es wird geschehen an jenem Tage, da wird die Herrlichkeit Jakobs verkümmert sein und das Fett seines Fleisches mager werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Und es wird sein, wie wenn ein Schnitter Getreidehalme zusammenfaßt und sein Arm Ähren abmäht; und es wird sein, wie wenn einer Ähren sammelt in der Talebene Rephaim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Doch wird eine Nachlese davon übrigbleiben wie beim Abschlagen der Oliven: zwei, drei Beeren oben im Wipfel, vier, fünf an seinen, des Fruchtbaumes, Zweigen, spricht Jehova, der Gott Israels. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'An jenem Tage wird der Mensch auf den hinschauen, der ihn gemacht hat, und seine Augen werden auf den Heiligen Israels blicken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Und er wird nicht schauen auf die Altäre, das Werk seiner Hände; und was seine Finger gemacht haben, wird er nicht ansehen, noch die Ascherim, noch die Sonnensäulen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'An jenem Tage werden seine Festungsstädte sein wie die verlassenen Orte des Waldes und des Berggipfels, welche man vor den Kindern Israel verließ; und es wird eine Wüste sein. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Denn du hast vergessen den Gott deines Heils und nicht gedacht des Felsen deiner Stärke. Darum pflanzest du liebliche Pflanzungen und besetzest sie mit ausländischen Reben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'Am Tage deiner Pflanzung hegst du sie ein, und am Morgen bringst du deine Pflanzen zur Blüte: ein Haufen Reisig am Tage gefährlicher Wunde und tödlichen Schmerzes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Wehe dem Getümmel vieler Völker: wie das Brausen der Meere brausen sie; und dem Rauschen von Völkerschaften: wie das Rauschen gewaltiger Wasser rauschen sie!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Völkerschaften rauschen wie das Rauschen vieler Wasser. Und er schilt sie, und sie fliehen weithin; und sie werden gejagt wie Spreu der Berge vor dem Winde und wie Stoppeln vor dem Sturme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Zur Abendzeit, siehe da, Bestürzung! Ehe es Morgen wird, sind sie nicht mehr. Das ist das Teil derer, die uns plündern, und das Los derer, die uns berauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'He! Land des Flügelgeschwirres, jenseit der Ströme von Äthiopien,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'welches Boten entsendet auf dem Meere und in Rohrschiffchen über der Wasserfläche! Gehet hin, schnelle Boten, zu der Nation, die weithin geschleppt und gerupft ist, zu dem Volke, wunderbar seitdem es ist und hinfort, der Nation von Vorschrift auf Vorschrift und von Zertretung, deren Land Ströme beraubt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Ihr alle, Bewohner des Erdkreises und die ihr auf der Erde ansässig seid, wenn man ein Panier auf den Bergen erhebt, so sehet hin; und wenn man in die Posaune stößt, so höret!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Denn also hat Jehova zu mir gesprochen: Ich will still sein und will zuschauen in meiner Wohnstätte, wie heitere Wärme bei Sonnenschein, wie Taugewölk in der Ernte Glut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Denn vor der Ernte, sobald die Blüte vorbei ist und die Blume zur reifenden Traube wird, da wird er die Reben abschneiden mit Winzermessern und die Ranken hinwegtun, abhauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Sie werden allzumal den Raubvögeln der Berge und den Tieren der Erde überlassen werden; und die Raubvögel werden darauf übersommern, und alle Tiere der Erde werden darauf überwintern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'In jener Zeit wird Jehova der Heerscharen ein Geschenk dargebracht werden: ein Volk, das weithin geschleppt und gerupft ist, und von einem Volke, wunderbar seitdem es ist und hinfort, einer Nation von Vorschrift auf Vorschrift und von Zertretung, deren Land Ströme beraubt haben, nach der Stätte des Namens Jehovas der Heerscharen, nach dem Berge Zion.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Ausspruch über Ägypten. Siehe, Jehova fährt auf schneller Wolke und kommt nach Ägypten. Und die Götzen Ägyptens beben vor ihm, und das Herz Ägyptens zerschmilzt in seinem Innern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Und ich will Ägypten aufreizen gegen Ägypten; und sie werden streiten, ein jeder wider seinen Bruder und ein jeder wider seinen Nächsten, Stadt wider Stadt, Königreich wider Königreich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Und der Geist Ägyptens wird vergehen in seinem Innern, und ich will seinen Ratschlag zunichte machen: und sie werden die Götzen und die Beschwörer und die Zauberer und die Wahrsager befragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Und ich will die Ägypter überliefern in die Hand eines harten Herrn; und ein grausamer König wird über sie herrschen, spricht der Herr, Jehova der Heerscharen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Und die Wasser werden sich aus dem Meere verlaufen, und der Strom wird versiegen und austrocknen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'und die Ströme werden stinken; die Kanäle Mazors nehmen ab und versiegen, Rohr und Schilf verwelken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Die Auen am Nil, am Ufer des Nil, und jedes Saatfeld am Nil verdorrt, zerstiebt und ist nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Und die Fischer klagen, und es trauern alle, welche Angeln in den Nil auswerfen; und die das Netz ausbreiten auf der Wasserfläche, schmachten hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Und beschämt sind die Wirker gehechelten Flachses und die Weber von Baumwollenzeug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Und seine Grundpfeiler sind zerschlagen; alle, die um Lohn arbeiten, sind seelenbetrübt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Eitel Toren sind die Fürsten von Zoan, die weisen Räte des Pharao; ihr Ratschlag ist dumm geworden. Wie saget ihr zu dem Pharao: \"Ich bin ein Sohn der Weisen, ein Sohn der Könige von ehemals?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Wo sind sie denn, deine Weisen? Mögen sie dir doch verkünden und erkennen, was Jehova der Heerscharen über Ägypten beschlossen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Die Fürsten von Zoan sind betört, die Fürsten von Noph sind betrogen; es haben Ägypten irregeführt die Häupter seiner Stämme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Jehova hat in sein Inneres einen Geist des Schwindels ausgegossen, daß sie Ägypten irregeführt haben in all seinem Tun, wie ein Trunkener taumelt in seinem Gespei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Und von Ägypten wird keine Tat geschehen, welche Haupt oder Schwanz, Palmzweig oder Binse verrichte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'An jenem Tage werden die Ägypter wie Weiber sein; und sie werden zittern und beben vor dem Schwingen der Hand Jehovas der Heerscharen, die er wider sie schwingen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Und das Land Juda wird für Ägypten zum Schrecken sein. So oft jemand es bei den Ägyptern erwähnt, werden sie beben wegen des Ratschlusses Jehovas der Heerscharen, welchen er über sie beschlossen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'An jenem Tage werden fünf Städte im Lande Ägypten sein, welche die Sprache Kanaans reden und bei Jehova der Heerscharen schwören werden. Eine wird die Stadt Heres heißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'An jenem Tage wird inmitten des Landes Ägypten ein Altar dem Jehova geweiht sein, und eine Denksäule nahe an seiner Grenze dem Jehova;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'und das wird zu einem Denkzeichen und zu einem Zeugnis sein dem Jehova der Heerscharen im Lande Ägypten. Denn sie werden zu Jehova schreien wegen der Bedrücker, und er wird ihnen einen Retter und Streiter senden und sie erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Und Jehova wird sich den Ägyptern kundgeben, und die Ägypter werden Jehova erkennen an jenem Tage; und sie werden dienen mit Schlachtopfern und Speisopfern, und werden Jehova Gelübde tun und bezahlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Und Jehova wird die Ägypter schlagen, schlagen und heilen; und sie werden sich zu Jehova wenden, und er wird sich von ihnen erbitten lassen und sie heilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'An jenem Tage wird eine Straße sein von Ägypten nach Assyrien; und die Assyrer werden nach Ägypten und die Ägypter nach Assyrien kommen, und die Ägypter werden mit den Assyrern Jehova dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'An jenem Tage wird Israel das dritte sein mit Ägypten und mit Assyrien, ein Segen inmitten der Erde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'denn Jehova der Heerscharen segnet es und spricht: Gesegnet sei mein Volk Ägypten, und Assyrien, meiner Hände Werk, und Israel, mein Erbteil!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'In dem Jahre, da der Tartan nach Asdod kam, als Sargon, der König von Assyrien, ihn gesandt hatte, und er wider Asdod stritt und es einnahm:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'in dieser Zeit redete Jehova durch Jesaja, den Sohn Amoz\', und sprach: Geh und löse das Sacktuch von deinen Lenden und ziehe deine Sandalen von deinen Füßen. Und er tat also, ging nackt und barfuß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Und Jehova sprach: Gleichwie mein Knecht Jesaja nackt und barfuß gegangen ist, drei Jahre lang ein Zeichen und Vorbild betreffs Ägyptens und betreffs Äthiopiens:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'also wird der König von Assyrien die Gefangenen Ägyptens und die Weggeführten Äthiopiens hinwegtreiben, Jünglinge und Greise, nackt und barfuß und mit entblößtem Gesäß, zur Schande Ägyptens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Und sie werden bestürzt und beschämt sein wegen Äthiopiens, ihrer Zuversicht, und wegen Ägyptens, ihres Ruhmes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Und die Bewohner dieses Küstenlandes werden an jenem Tage sprechen: Siehe, also ist es mit unserer Zuversicht, wohin wir um Hilfe flohen, um vor dem Könige von Assyrien errettet zu werden! Und wie sollten wir entrinnen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Ausspruch über die Wüste des Meeres. Wie Stürme, wenn sie im Süden daherfahren, so kommt\'s aus der Wüste, aus fruchtbarem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Ein hartes Gesicht ist mir kundgetan: Der Räuber raubt, und der Verwüster verwüstet. Ziehe hinauf, Elam! Belagere, Medien! All ihrem Seufzen mache ich ein Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Darum sind meine Lenden voll Schmerzes, Wehen haben mich ergriffen wie die Wehen einer Gebärenden; ich krümme mich, daß ich nicht hören, bin bestürzt, daß ich nicht sehen kann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Mein Herz schlägt wild, Schauder ängstigt mich; die Dämmerung, die ich liebe, hat er mir in Beben verwandelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Man rüstet den Tisch, es wacht die Wache, man ißt, man trinkt... Stehet auf, ihr Fürsten! Salbet den Schild! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Denn also hat der Herr zu mir gesprochen: Geh hin, stelle einen Wächter auf; was er sieht, soll er berichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Und er sah einen Reiterzug: Reiter bei Paaren; einen Zug Esel, einen Zug Kamele. Und er horchte gespannt, mit großer Aufmerksamkeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'und er rief wie ein Löwe: Herr, ich stehe auf der Turmwarte beständig bei Tage, und auf meinem Wachtposten stehe ich da alle Nächte hindurch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Und siehe da, es kam ein Zug Männer, Reiter bei Paaren...Und er hob an und sprach: Gefallen, gefallen ist Babel, und alle geschnitzten Bilder seiner Götzen hat er zu Boden geschmettert!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Du mein Gedroschenes und Sohn meiner Tenne! Was ich von Jehova der Heerscharen, dem Gott Israels, gehört, habe ich euch verkündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Ausspruch über Duma. Aus Seir ruft man mir zu: Wächter, wie weit ist\'s in der Nacht? Wächter, wie weit in der Nacht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Der Wächter spricht: Der Morgen kommt, und auch die Nacht. Wollt ihr fragen, so fraget! Kehret wieder, kommet her!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Ausspruch über Arabien. In der Wildnis von Arabien müßt ihr übernachten, Karawanen der Dedaniter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Bringet dem Durstigen Wasser entgegen! Die Bewohner des Landes Tema kommen mit seinem Brote dem Flüchtling entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Denn sie flüchten vor den Schwertern, vor dem gezückten Schwerte und vor dem gespannten Bogen und vor der Wucht des Krieges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Denn also hat der Herr zu mir gesprochen: Binnen Jahresfrist, wie die Jahre eines Tagelöhners, wird alle Herrlichkeit Kedars verschwinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'Und die übriggebliebene Zahl der Bogen, der Helden der Söhne Kedars, wird gering sein; denn Jehova, der Gott Israels, hat geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Ausspruch über das Tal der Gesichte. Was ist dir denn, daß du insgesamt auf die Dächer gestiegen bist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'O getümmelvolle, lärmende Stadt, du frohlockende Stadt, deine Erschlagenen sind nicht vom Schwert Erschlagene und nicht in der Schlacht Getötete!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Alle deine Oberen, flüchtend allzumal, wurden ohne Bogen gefesselt; alle in dir Gefundenen wurden miteinander gefesselt, fernhin wollten sie fliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Darum sage ich: Schauet von mir weg, daß ich bitterlich weine; dringet nicht in mich, um mich zu trösten über die Zerstörung der Tochter meines Volkes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Denn es ist ein Tag der Bestürzung und der Zertretung und der Verwirrung vom Herrn, Jehova der Heerscharen, im Tal der Gesichte, ein Tag, der Mauern zertrümmert; und Wehgeschrei hallt nach dem Gebirge hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Und Elam trägt den Köcher, mit bemannten Wagen und mit Reitern; und Kir entblößt den Schild.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Und es wird geschehen, deine auserlesenen Täler werden voll Wagen sein, und die Reiter nehmen Stellung gegen das Tor. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Und er deckt den Schleier auf von Juda, und du blickst an jenem Tage nach den Waffen des Waldhauses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Und ihr sehet die Risse der Stadt Davids, daß ihrer viele sind; und ihr sammelt die Wasser des unteren Teiches;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'und ihr zählet die Häuser von Jerusalem und brechet die Häuser ab, um die Mauer zu befestigen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'und ihr machet einen Behälter zwischen den beiden Mauern für die Wasser des alten Teiches. Aber ihr blicket nicht auf den, der es getan und sehet den nicht an, der von fernher es gebildet hat. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Und es ruft der Herr, Jehova der Heerscharen, an jenem Tage zum Weinen und zur Wehklage, und zum Haarscheren und zur Sackumgürtung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Aber siehe, Wonne und Freude, Rinderwürgen und Schafeschlachten, Fleischessen und Weintrinken: \"Laßt uns essen und trinken, denn morgen sterben wir!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Und Jehova der Heerscharen hat sich meinen Ohren geoffenbart: Wenn euch diese Missetat vergeben wird, bis ihr sterbet! spricht der Herr, Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'So sprach der Herr, Jehova der Heerscharen: Auf! Geh zu diesem Verwalter da, zu Schebna, der über das Haus ist, und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Was hast du hier, und wen hast du hier, daß du dir hier ein Grab aushaust? Du, der sein Grab aushaut auf der Höhe, sich eine Wohnung im Felsen gräbt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Siehe, Jehova wird dich weithin wegschleudern mit Manneswurf; und er wird dich zusammenwickeln,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'zu einem Knäuel wird er dich fest zusammenrollen, wie einen Ball dich wegschleudern in ein geräumiges Land. Dort sollst du sterben, und dorthin sollen deine Prachtwagen kommen, du Schande des Hauses deines Herrn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Und ich werde dich von deinem Posten hinwegstoßen, und von deinem Standorte wird er dich herunterreißen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Und es wird geschehen an jenem Tage, da werde ich meinen Knecht Eljakim rufen, den Sohn Hilkijas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'Und ich werde ihn mit deinem Leibrock bekleiden und ihm deinen Gürtel fest umbinden, und werde deine Herrschaft in seine Hand legen; und er wird den Bewohnern von Jerusalem und dem Hause Juda zum Vater sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Und ich werde den Schlüssel des Hauses Davids auf seine Schulter legen; und er wird öffnen, und niemand wird schließen, und er wird schließen, und niemand wird öffnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Und ich werde ihn als Pflock einschlagen an einen festen Ort; und er wird seinem Vaterhause zum Throne der Ehre sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Und man wird an ihn hängen die gesamte Herrlichkeit seines Vaterhauses: die Sprößlinge und die Seitenschosse, alle kleinen Gefäße, von den Beckengefäßen bis zu allen Kruggefäßen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'An jenem Tage, spricht Jehova der Heerscharen, wird der Pflock weichen, der eingeschlagen war an einem festen Orte, und er wird abgehauen werden und fallen; und die Last, die er trug, wird zu Grunde gehen; denn Jehova der Heerscharen hat geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Ausspruch über Tyrus. Heulet, ihr Tarsisschiffe! Denn Tyrus ist verwüstet, ist ohne Haus, ohne Eingehenden. Vom Lande der Kittäer her ist es ihnen kundgeworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Verstummet, ihr Bewohner der Insel! Zidonische Kaufleute, die das Meer befahren, füllten dich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'und auf großen Wassern war die Saat des Sichor, die Ernte des Nil ihr Ertrag; und sie war die Erwerbsquelle der Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Sei beschämt, Zidon! Denn das Meer spricht, des Meeres Feste, und sagt: Ich habe keine Wehen gehabt und nicht geboren, und keine Jünglinge großgezogen, noch Jungfrauen auferzogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Sobald die Kunde nach Ägypten kommt, werden sie zittern bei der Kunde von Tyrus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Fahret hinüber nach Tarsis; heulet, ihr Bewohner der Insel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Ist das eure frohlockende Stadt, deren Ursprung aus den Tagen der Vorzeit ist, welche ihre Füße tragen, um in der Ferne zu weilen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Wer hat solches beschlossen über Tyrus, die Kronenspenderin, deren Kaufleute Fürsten, deren Händler die Vornehmsten der Erde waren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Jehova der Heerscharen hat es beschlossen, um zu entweihen den Stolz jeder Pracht, um verächtlich zu machen alle Vornehmen der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Überflute dein Land wie der Nil, Tochter Tarsis! Es gibt keinen Gürtel mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Er hat seine Hand über das Meer ausgestreckt, hat Königreiche in Beben versetzt; Jehova hat über Kanaan geboten, seine Festen zu zerstören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Und er sprach: Du sollst nicht mehr frohlocken, du geschändete Jungfrau, Tochter Zidon! Mache dich auf nach Kittim, fahre hinüber! Auch dort wird dir keine Ruhe werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Siehe, das Land der Chaldäer, dieses Volk, das nicht war (Assur hat es den Bewohnern der Wüste angewiesen), richtet seine Belagerungstürme auf, schleift dessen Paläste, macht es zu einem Trümmerhaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Heulet, ihr Tarsisschiffe! Denn eure Feste ist verwüstet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Und es wird geschehen an jenem Tage, da wird Tyrus siebzig Jahre vergessen werden, gleich den Tagen eines Königs. Am Ende von siebzig Jahren wird es Tyrus ergehen nach dem Liede von der Hure:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, '\"Nimm die Laute, geh umher in der Stadt, vergessene Hure! Spiele, so gut du kannst, singe Lied auf Lied, daß man deiner gedenke\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Denn es wird geschehen am Ende von siebzig Jahren, da wird Jehova Tyrus heimsuchen; und sie wird wieder zu ihrem Hurenlohn kommen, und wird Hurerei treiben mit allen Königreichen der Erde auf der Fläche des Erdbodens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Und ihr Erwerb und ihr Hurenlohn wird Jehova heilig sein; er wird nicht aufgehäuft und nicht aufbewahrt werden; sondern ihr Erwerb wird für die sein, die vor Jehova wohnen, damit sie essen bis zur Sättigung und prächtig gekleidet seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Siehe, Jehova leert das Land aus und verödet es; und er kehrt seine Oberfläche um und zerstreut seine Bewohner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Und wie dem Volke, so ergeht es dem Priester; wie dem Knechte, so seinem Herrn; wie der Magd, so ihrer Gebieterin; wie dem Käufer, so dem Verkäufer; wie dem Leiher, so dem Borger; wie dem Schuldner, so seinem Gläubiger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Das Land wird völlig ausgeleert und geplündert; denn Jehova hat dieses Wort geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Es trauert, es welkt hin das Land; es schmachtet, es welkt hin der Erdkreis; es schmachten hin die Hohen des Volkes im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Und die Erde ist entweiht worden unter ihren Bewohnern; denn sie haben die Gesetze übertreten, die Satzung überschritten, gebrochen den ewigen Bund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Darum hat der Fluch die Erde verzehrt, und es büßen ihre Bewohner; darum sind verbrannt der Erde Bewohner, und wenig Menschen bleiben übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Es trauert der Most, es schmachtet der Weinstock; es seufzen alle, die fröhlichen Herzens waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'es feiert die Freude der Tamburine, aufgehört hat der Frohlockenden Getümmel, es feiert die Freude der Laute;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'man trinkt keinen Wein mehr unter Gesang, bitter schmeckt das starke Getränk denen, die es trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Zertrümmert ist die Stadt der Öde, verschlossen jedes Haus, so daß niemand hineingeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Klagegeschrei ob des Weines ist auf den Straßen; untergegangen ist alle Freude, weggezogen die Wonne der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Von der Stadt ist nur eine Wüste übriggeblieben, und in Trümmer zerschlagen ward das Tor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Denn so wird es geschehen inmitten der Erde, in der Mitte der Völker: wie beim Abschlagen der Oliven, wie bei der Nachlese, wenn die Weinernte zu Ende ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Jene werden ihre Stimme erheben, werden jubeln. Ob der Majestät Jehovas jauchzen sie vom Meere her:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Darum gebet Jehova Ehre im Osten, auf den Inseln des Meeres dem Namen Jehovas, des Gottes Israels!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Vom Ende der Erde her hören wir Gesänge: \"Herrlichkeit dem Gerechten!\" Da sprach ich: Ich vergehe, ich vergehe, wehe mir! Räuber rauben, und räuberisch raubend rauben sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Grauen und Grube und Garn über dich, Bewohner der Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Und es geschieht, wer vor der Stimme des Grauens flieht, fällt in die Grube; und wer aus der Grube heraufsteigt, wird im Garne gefangen. Denn die Fenster in der Höhe tun sich auf, und es erbeben die Grundfesten der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Die Erde klafft auseinander, die Erde zerberstet, die Erde schwankt hin und her;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'die Erde taumelt wie ein Trunkener und schaukelt wie eine Hängematte; und schwer lastet auf ihr ihre Übertretung: und sie fällt und steht nicht wieder auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Und es wird geschehen an jenem Tage, da wird Jehova heimsuchen die Heerschar der Höhe in der Höhe, und die Könige der Erde auf der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'Und sie werden in die Grube eingesperrt, wie man Gefangene einsperrt, und in den Kerker eingeschlossen; und nach vielen Tagen werden sie heimgesucht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Und der Mond wird mit Scham bedeckt und die Sonne beschämt werden; denn Jehova der Heerscharen herrscht als König auf dem Berge Zion und in Jerusalem, und vor seinen Ältesten ist Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Jehova, du bist mein Gott; ich will dich erheben, preisen will ich deinen Namen; denn du hast Wunder gewirkt, Ratschlüsse von fernher, Treue und Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Denn du hast aus einer Stadt einen Steinhaufen gemacht, die feste Stadt zu einem Trümmerhaufen, den Palast der Fremden, daß er keine Stadt mehr sei: er wird in Ewigkeit nicht aufgebaut werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Darum wird dich ehren ein trotziges Volk, Städte gewalttätiger Nationen werden dich fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Denn du bist eine Feste gewesen dem Armen, eine Feste dem Dürftigen in seiner Bedrängnis, eine Zuflucht vor dem Regensturm, ein Schatten vor der Glut; denn das Schnauben der Gewalttätigen war wie ein Regensturm gegen eine Mauer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Wie die Glut in einem dürren Lande, beugtest du der Fremden Ungestüm; wie die Glut durch einer Wolke Schatten, wurde gedämpft der Gewalttätigen Siegesgesang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Und Jehova der Heerscharen wird auf diesem Berge allen Völkern ein Mahl von Fettspeisen bereiten, ein Mahl von Hefenweinen, von markigen Fettspeisen, geläuterten Hefenweinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Und er wird auf diesem Berge den Schleier vernichten, der alle Völker verschleiert, und die Decke, die über alle Nationen gedeckt ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Den Tod verschlingt er auf ewig; und der Herr, Jehova, wird die Tränen abwischen von jedem Angesicht, und die Schmach seines Volkes wird er hinwegtun von der ganzen Erde. Denn Jehova hat geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Und an jenem Tage wird man sprechen: Siehe da, unser Gott, auf den wir harrten, daß er uns retten würde; da ist Jehova, auf den wir harrten! Laßt uns frohlocken und uns freuen in seiner Rettung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Denn die Hand Jehovas wird ruhen auf diesem Berge; und Moab wird unter ihm zertreten werden, wie Stroh zertreten wird in einer Mistlache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Und er wird seine Hände darin ausbreiten, wie der Schwimmer sie ausbreitet, um zu schwimmen; und er wird seinen Hochmut niederzwingen samt den Ränken seiner Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Und deine festen, hochragenden Mauern wird er niederwerfen, niederstürzen, zu Boden strecken bis in den Staub.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'An jenem Tage wird dieses Lied im Lande Juda gesungen werden: Wir haben eine starke Stadt; Rettung setzt er zu Mauern und zum Bollwerk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Machet auf die Tore, daß einziehe ein gerechtes Volk, welches Treue bewahrt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Den festen Sinn bewahrst du in Frieden, in Frieden; denn er vertraut auf dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Vertrauet auf Jehova ewiglich; denn in Jah, Jehova, ist ein Fels der Ewigkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Denn er hat Hochwohnende niedergebeugt, die hochragende Stadt; er hat sie niedergestürzt, zu Boden gestürzt, hat sie niedergestreckt bis in den Staub.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Es zertritt sie der Fuß, die Füße der Elenden, die Tritte der Armen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Der Pfad des Gerechten ist gerade; du bahnest gerade den Weg des Gerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Ja, wir haben dich, Jehova, erwartet auf dem Pfade deiner Gerichte; nach deinem Namen und nach deinem Gedächtnis ging das Verlangen der Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Mit meiner Seele verlangte ich nach dir in der Nacht; ja, mit meinem Geiste in meinem Innern suchte ich dich früh; denn wenn deine Gerichte die Erde treffen, so lernen Gerechtigkeit die Bewohner des Erdkreises.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Wird dem Gesetzlosen Gnade erzeigt, so lernt er nicht Gerechtigkeit: im Lande der Geradheit handelt er unrecht und sieht nicht die Majestät Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Jehova, deine Hand war hoch erhoben, sie wollten nicht schauen. Schauen werden sie den Eifer um das Volk und beschämt werden; ja, deine Widersacher, Feuer wird sie verzehren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Jehova, du wirst uns Frieden geben, denn du hast ja alle unsere Werke für uns vollführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Jehova, unser Gott, über uns haben Herren geherrscht außer dir; durch dich allein gedenken wir deines Namens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Tote leben nicht auf, Schatten erstehen nicht wieder; darum hast du sie heimgesucht und vertilgt und hast all ihr Gedächtnis zunichte gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Du hast die Nation vermehrt, Jehova, du hast die Nation vermehrt, du hast dich verherrlicht; du hast hinausgerückt alle Grenzen des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Jehova, in der Bedrängnis haben sie dich gesucht; als deine Züchtigung sie traf, flehten sie mit flüsterndem Gebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Wie eine Schwangere, die, dem Gebären nahe, sich windet und schreit in ihren Wehen: also sind wir gewesen, Jehova, fern von deinem Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Wir gingen schwanger, wir wanden uns; es war, als ob wir Wind geboren hätten: Rettung verschafften wir dem Lande nicht, und die Bewohner des Erdkreises sind nicht gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Deine Toten werden aufleben, meine Leichen wieder erstehen. Wachet auf und jubelt, die ihr im Staube lieget! Denn ein Tau des Lichtes ist dein Tau; und die Erde wird die Schatten auswerfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Geh hin, mein Volk, tritt ein in deine Gemächer und schließe deine Tür hinter dir zu; verbirg dich einen kleinen Augenblick, bis der Zorn vorübergehe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Denn siehe, Jehova tritt hervor aus seiner Stätte, um die Ungerechtigkeit der Bewohner der Erde an ihnen heimzusuchen; und die Erde enthüllt ihr Blut und bedeckt nicht länger ihre Ermordeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'An jenem Tage wird Jehova mit seinem Schwerte, dem harten und großen und starken, heimsuchen den Leviathan, die flüchtige Schlange, und den Leviathan, die gewundene Schlange, und wird das Ungeheuer töten, welches im Meere ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'An jenem Tage wird man singen: Ein Weinberg feurigen Weines! Besinget ihn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Ich, Jehova, behüte ihn, bewässere ihn alle Augenblicke; daß nichts ihn heimsuche, behüte ich ihn Nacht und Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Grimm habe ich nicht. O hätte ich Dornen und Disteln vor mir, im Kriege würde ich auf sie losschreiten, sie verbrennen allzumal!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Oder man müßte meinen Schutz ergreifen, Frieden mit mir machen, Frieden machen mit mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'In Zukunft wird Jakob Wurzel schlagen, Israel blühen und knospen; und sie werden mit Früchten füllen die Fläche des Erdkreises. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Hat er es geschlagen, wie er seinen Schläger schlug? Oder ist es ermordet worden, wie er die Ermordeten jenes ermordete?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Mit Maßen, als du es verstießest, hast du mit ihm gerechtet; er scheuchte es hinweg mit seinem heftigen Hauche am Tage des Ostwindes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Deshalb wird dadurch gesühnt werden die Ungerechtigkeit Jakobs. Und dies ist die ganze Frucht der Hinwegnahme seiner Sünde: wenn es alle Altarsteine gleich zerschlagenen Kalksteinen machen wird, und Ascherim und Sonnensäulen sich nicht mehr erheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Denn die feste Stadt ist einsam, eine preisgegebene und verlassene Wohnstätte wie die Steppe; daselbst weiden Kälber, und daselbst lagern sie und fressen ihre Zweige ab;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'wenn ihre Reiser dürr geworden sind, werden sie abgebrochen: Weiber kommen und zünden sie an. Denn es ist kein verständiges Volk; darum erbarmt sich seiner nicht, der es gemacht, und der es gebildet hat, erweist ihm keine Gnade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Und es wird geschehen an jenem Tage, da wird Jehova Getreide ausschlagen von der Strömung des Euphrat bis zum Bache Ägyptens; und ihr werdet zusammengelesen werden, einer zu dem anderen, ihr Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Und es wird geschehen an jenem Tage, da wird in eine große Posaune gestoßen werden, und die Verlorenen im Lande Assyrien und die Vertriebenen im Land Ägypten werden kommen und Jehova anbeten auf dem heiligen Berge zu Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Wehe der stolzen Krone der Trunkenen Ephraims, und der welkenden Blume seiner herrlichen Pracht auf dem Haupte des fetten Tales der vom Weine Überwältigten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Siehe, der Herr hat einen Starken und Mächtigen, gleich einem Hagelwetter, einem verderbenden Sturmwinde; wie ein Wetter gewaltiger, überflutender Wasser reißt er zu Boden mit Macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Mit Füßen wird zertreten die stolze Krone der Trunkenen Ephraims.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Und der welkenden Blume seiner herrlichen Pracht auf dem Haupte des fetten Tales ergeht es wie dessen Frühfeige vor der Obsternte: kaum ist sie in der Hand dessen, der sie erblickt, so verschlingt er sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'An jenem Tage wird Jehova der Heerscharen dem Überrest seines Volkes zur prächtigen Krone und zum herrlichen Kranze sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'und zum Geiste des Rechts dem, der zu Gericht sitzt; und zur Heldenkraft denen, welche den Streit zurückdrängen ans Tor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Und auch diese wanken vom Wein und taumeln von starkem Getränk: Priester und Prophet wanken von starkem Getränk, sind übermannt vom Wein, taumeln vom starken Getränk; sie wanken beim Gesicht, schwanken beim Rechtsprechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Denn alle Tische sind voll unflätigen Gespeies, daß kein Platz mehr ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Wen soll er Erkenntnis lehren, und wem die Botschaft verständlich machen? Den von der Milch Entwöhnten, den von den Brüsten Entfernten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Denn es ist Gebot auf Gebot, Gebot auf Gebot, Vorschrift auf Vorschrift, Vorschrift auf Vorschrift, hier ein wenig, da ein wenig! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Ja, durch stammelnde Lippen und durch eine fremde Sprache wird er zu diesem Volke reden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'er, der zu ihnen sprach: Dies ist die Ruhe, schaffet Ruhe dem Ermüdeten; und dies die Erquickung! Aber sie wollten nicht hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Und so wird ihnen das Wort Jehovas sein: Gebot auf Gebot, Gebot auf Gebot, Vorschrift auf Vorschrift, Vorschrift auf Vorschrift, hier ein wenig, da ein wenig; auf daß sie hingehen und rücklings fallen und zerschmettert werden und verstrickt und gefangen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Darum höret das Wort Jehovas, ihr Spötter, Beherrscher dieses Volkes, das in Jerusalem ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Denn ihr sprechet: Wir haben einen Bund mit dem Tode geschlossen und einen Vertrag mit dem Scheol gemacht: Wenn die überflutende Geißel hindurchfährt, wird sie an uns nicht kommen; denn wir haben die Lüge zu unserer Zuflucht gemacht und in der Falschheit uns geborgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Darum, so spricht der Herr, Jehova: Siehe, ich gründe einen Stein in Zion, einen bewährten Stein, einen kostbaren Eckstein, aufs festeste gegründet; wer glaubt, wird nicht ängstlich eilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Und ich werde das Recht zur Richtschnur machen, und die Gerechtigkeit zum Senkblei. Und der Hagel wird hinwegraffen die Zuflucht der Lüge, und die Wasser werden den Bergungsort wegschwemmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Und euer Bund mit dem Tode wird zunichte werden, und euer Vertrag mit dem Scheol nicht bestehen: Wenn die überflutende Geißel hindurchfährt, so werdet ihr von derselben zertreten werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'So oft sie hindurchfährt, wird sie euch hinraffen; denn jeden Morgen wird sie hindurchfahren, bei Tage und bei Nacht. Und es wird eitel Schrecken sein, die Botschaft zu vernehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Denn das Bett ist zu kurz, um sich auszustrecken und die Decke zu schmal, um sich einzuhüllen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Denn Jehova wird sich aufmachen wie bei dem Berge Perazim, wie im Tale zu Gibeon wird er zürnen: um sein Werk zu tun, befremdend ist sein Werk! und um seine Arbeit zu verrichten, außergewöhnlich ist seine Arbeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Und nun treibet nicht Spott, damit eure Bande nicht fester gemacht werden; denn ich habe Vernichtung vernommen und Festbeschlossenes von seiten des Herrn, Jehovas der Heerscharen, über die ganze Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Nehmet zu Ohren und höret meine Stimme, merket auf und höret meine Rede!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Pflügt wohl der Pflüger den ganzen Tag, um zu säen? Furcht und eggt er den ganzen Tag sein Ackerland?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Ist es nicht so? Wenn er dessen Fläche geebnet hat, so streut er Dill und sät Kümmel, und wirft Weizen reihenweise, und Gerste auf das abgesteckte Stück, und den Spelt an seinen Rand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'So unterwies ihn sein Gott zum richtigen Verfahren, er belehrte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Denn Dill wird nicht mit dem Dreschschlitten ausgedroschen und das Wagenrad nicht über Kümmel gerollt; sondern Dill wird mit dem Stabe ausgeschlagen und Kümmel mit dem Stocke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Wird Brotkorn zermalmt? Nein, nicht unaufhörlich drischt er es; und wenn er das Rad seines Wagens und seine Pferde darüber hintreibt, so zermalmt er es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Auch dieses geht aus von Jehova der Heerscharen; er ist wunderbar in seinem Rat, groß an Verstand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Wehe Ariel, Ariel, Stadt, wo David lagerte! Füget Jahr zu Jahr, laßt die Feste kreisen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Und ich werde Ariel bedrängen, und es wird Seufzen und Stöhnen geben. Und sie wird mir sein wie ein Ariel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Und ich werde dich im Kreise umlagern, und dich mit Heeresaufstellung einschließen, und Belagerungswerke wider dich aufrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Und erniedrigt wirst du aus der Erde reden, und deine Sprache wird dumpf aus dem Staube ertönen; und deine Stimme wird wie die eines Geistes aus der Erde hervorkommen, und deine Sprache wird aus dem Staube flüstern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Aber wie feiner Staub wird die Menge deiner Feinde sein, und wie dahinfahrende Spreu die Menge der Gewaltigen; und in einem Augenblick, plötzlich, wird es geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Von seiten Jehovas der Heerscharen wird sie heimgesucht werden mit Donner und mit Erdbeben und großem Getöse, Sturmwind und Gewitter und eine Flamme verzehrenden Feuers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Und wie ein nächtliches Traumgesicht wird die Menge all der Nationen sein, welche Krieg führen wider Ariel, und alle, welche sie und ihre Festung bestürmen und sie bedrängen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Und es wird geschehen, gleichwie der Hungrige träumt, und siehe, er ißt und er wacht auf, und seine Seele ist leer; und gleichwie der Durstige träumt, und siehe, er trinkt und er wacht auf, und siehe, er ist matt und seine Seele lechzt: also wird die Menge all der Nationen sein, welche Krieg führen wider den Berg Zion.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Stutzet und staunet! Blendet euch und erblindet! Sie sind trunken, doch nicht von Wein; sie schwanken, doch nicht von starkem Getränk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Denn Jehova hat einen Geist tiefen Schlafes über euch ausgegossen und hat eure Augen verschlossen; die Propheten und eure Häupter, die Seher, hat er verhüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Und jedes Gesicht ist euch geworden wie die Worte einer versiegelten Schrift, die man einem gibt, der lesen kann, indem man sagt: Lies doch dieses! Er aber sagt: Ich kann nicht, denn es ist versiegelt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'und man gibt die Schrift einem, der nicht lesen kann, indem man sagt: Lies doch dieses! Er aber sagt: Ich kann nicht lesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Und der Herr hat gesprochen: Weil dieses Volk mit seinem Munde sich naht und mit seinen Lippen mich ehrt, und sein Herz fern von mir hält, und ihre Furcht vor mir angelerntes Menschengebot ist:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Darum, siehe, will ich fortan wunderbar mit diesem Volke handeln, wunderbar und wundersam; und die Weisheit seiner Weisen wird zunichte werden, und der Verstand seiner Verständigen sich verbergen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Wehe denen, welche ihre Pläne tief verbergen vor Jehova, und deren Werke im Finstern geschehen, und die da sprechen: Wer sieht uns, und wer kennt uns?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'O über eure Verkehrtheit! Soll denn der Töpfer dem Tone gleichgeachtet werden? Daß das Werk von seinem Meister spreche: Er hat mich nicht gemacht! Und das Gebilde von seinem Bildner spreche: Er versteht es nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Ist es nicht noch um ein gar Kleines, daß der Libanon sich in ein Fruchtgefilde verwandeln und das Fruchtgefilde dem Walde gleichgeachtet werden wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Und an jenem Tage werden die Tauben die Worte des Buches hören, und aus Dunkel und Finsternis hervor werden die Augen der Blinden sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Und die Sanftmütigen werden ihre Freude in Jehova mehren, und die Armen unter den Menschen werden frohlocken in dem Heiligen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Denn der Gewalttätige hat ein Ende, und der Spötter verschwindet; und ausgerottet werden alle, die auf Unheil bedacht sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'die einen Menschen schuldig erklären um eines Wortes willen und dem Schlingen legen, welcher im Tore Recht spricht, und um nichts den Gerechten aus seinem Recht verdrängen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Darum, so spricht Jehova, der Abraham erlöst hat, zum Hause Jakob: Nunmehr wird Jakob nicht beschämt werden, und nunmehr wird sein Angesicht nicht erblassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Denn wenn er, wenn seine Kinder das Werk meiner Hände in seiner Mitte sehen werden, so werden sie meinen Namen heiligen; und sie werden den Heiligen Jakobs heiligen und vor dem Gott Israels beben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Und die verirrten Geistes sind, werden Verständnis erlangen, und Murrende werden Lehre annehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Wehe den widerspenstigen Kindern, spricht Jehova, welche Pläne ausführen, aber nicht von mir aus, und Bündnisse schließen, aber nicht nach meinem Geiste, um Sünde auf Sünde zu häufen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'die hingehen, um nach Ägypten hinabzuziehen, aber meinen Mund haben sie nicht befragt, um sich zu flüchten unter den Schutz des Pharao und Zuflucht zu suchen unter dem Schatten Ägyptens!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Und der Schutz des Pharao wird euch zur Schmach werden, und die Zuflucht unter dem Schatten Ägyptens zur Schande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Denn seine Fürsten waren in Zoan, und seine Gesandten langten in Hanes an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Alle werden beschämt werden über ein Volk, das ihnen nichts nützt, das nicht zur Hilfe und nicht zum Nutzen, sondern zur Beschämung und auch zum Hohne wird. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Ausspruch über den Behemoth des Südens: Durch ein Land der Bedrängnis und der Angst, aus welchem Löwin und Löwe, Ottern und fliegende, feurige Schlangen kommen, tragen sie auf den Rücken der Eselsfüllen ihren Reichtum und auf den Höckern der Kamele ihre Schätze zu einem Volke, das nichts nützt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Denn umsonst und vergebens wird Ägypten helfen. Darum nenne ich dieses Ägypten: Großtuer, die still sitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Geh nun hin, schreibe es vor ihnen auf eine Tafel und zeichne es in ein Buch ein; und es bleibe für die zukünftige Zeit, auf immer bis in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Denn es ist ein widerspenstiges Volk, betrügerische Kinder, Kinder, die das Gesetz Jehovas nicht hören wollen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'die zu den Sehern sprechen: Sehet nicht! Und zu den Schauern: Schauet uns nicht das Richtige, saget uns Schmeicheleien, schauet uns Täuschungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Weichet ab vom Wege, bieget ab vom Pfade; schaffet den Heiligen Israels vor unserem Angesicht hinweg!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Darum, so spricht der Heilige Israels: Weil ihr dieses Wort verwerfet und auf Bedrückung und Verdrehung vertrauet und euch darauf stützet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'darum wird euch diese Missetat wie ein sturzdrohender Riß sein, wie eine Ausbauchung an einer hochragenden Mauer, deren Einsturz in einem Augenblick, plötzlich kommt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Und er wird sie zerbrechen, wie man einen Töpferkrug zerbricht, der ohne Schonung zertrümmert wird, und von welchem, wenn er zertrümmert ist, nicht ein Scherben gefunden wird, um damit Feuer vom Herd zu holen oder Wasser aus einer Zisterne zu schöpfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Denn so spricht der Herr, Jehova, der Heilige Israels: Durch Umkehr und durch Ruhe würdet ihr gerettet werden; in Stillsein und in Vertrauen würde eure Stärke sein. Aber ihr habt nicht gewollt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'und ihr sprachet: \"Nein, sondern auf Rossen wollen wir fliegen\", darum werdet ihr fliehen; und: \"Auf Rennern wollen wir reiten\", darum werden eure Verfolger rennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Ein Tausend wird fliehen vor dem Dräuen eines einzigen; vor dem Dräuen von Fünfen werdet ihr fliehen, bis ihr übrigbleibet wie eine Stange auf des Berges Spitze und wie ein Panier auf dem Hügel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Und darum wird Jehova verziehen, euch gnädig zu sein; und darum wird er sich hinweg erheben, bis er sich euer erbarmt; denn Jehova ist ein Gott des Gerichts. Glückselig alle, die auf ihn harren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Denn ein Volk wird in Zion wohnen, in Jerusalem. Du wirst nie mehr weinen; er wird dir gewißlich Gnade erweisen auf die Stimme deines Schreiens. Sobald er hört, wird er dir antworten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Und der Herr wird euch Brot der Drangsal und Wasser der Trübsal geben. Und deine Lehrer werden sich nicht mehr verbergen, sondern deine Augen werden deine Lehrer sehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'und wenn ihr zur Rechten oder wenn ihr zur Linken abbieget, so werden deine Ohren ein Wort hinter dir her hören: Dies ist der Weg, wandelt darauf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Und ihr werdet den Überzug deiner silbernen Schnitzbilder und die Bekleidung deiner goldenen Gußbilder verunreinigen; du wirst sie wegwerfen wie ein unflätiges Kleid: \"Hinaus!\" wirst du zu ihnen sagen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Und er wird Regen geben zu deiner Saat, womit du den Erdboden besäst, und Brot als Ertrag des Erdbodens, und es wird fett und nahrhaft sein. Deine Herden werden an jenem Tage weiden auf weiter Aue;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'und die Ochsen und die Eselsfüllen, die das Ackerland bearbeiten, werden gesalzenes Futter fressen, welches man mit der Schaufel und mit der Gabel geworfelt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Und auf jedem hohen Berge und auf jedem erhabenen Hügel werden Bäche, Wasserströme sein an dem Tage des großen Gemetzels, wenn Türme fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Und das Licht des Mondes wird sein wie das Licht der Sonne, und das Licht der Sonne wird siebenfältig sein, wie das Licht von sieben Tagen, an dem Tage, da Jehova den Schaden seines Volkes verbinden und seiner Schläge Wunden heilen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Siehe, der Name Jehovas kommt von fernher. Sein Zorn brennt, und der aufsteigende Rauch ist gewaltig; seine Lippen sind voll Grimmes, und seine Zunge ist wie ein verzehrendes Feuer,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'und sein Odem wie ein überflutender Bach, der bis an den Hals reicht: um die Nationen zu schwingen mit einer Schwinge der Nichtigkeit, und einen irreführenden Zaum an die Kinnbacken der Völker zu legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Gesang werdet ihr haben wie in der Nacht, da das Fest geweiht wird, und Freude des Herzens gleich denen, die unter Flötenspiel hinziehen, um zu kommen auf den Berg Jehovas, zum Felsen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Und Jehova wird hören lassen die Majestät seiner Stimme, und sehen lassen das Herabfahren seines Armes mit Zornesschnauben und einer Flamme verzehrenden Feuers, Wolkenbruch und Regenguß und Hagelsteine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Denn vor der Stimme Jehovas wird Assur zerschmettert werden, wenn er mit dem Stocke schlägt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Und es wird geschehen, jeder Streich der verhängten Rute, die Jehova auf ihn herabfahren läßt, ergeht unter Tamburin-und Lautenspiel; und mit geschwungenem Arme wird er gegen ihn kämpfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Denn vorlängst ist eine Greuelstätte zugerichtet; auch für den König ist sie bereitet. Tief, weit hat er sie gemacht, ihr Holzstoß hat Feuer und Holz in Menge; wie ein Schwefelstrom setzt der Hauch Jehovas ihn in Brand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Wehe denen, welche nach Ägypten hinabziehen um Hilfe, auf Rosse sich stützen, und die ihr Vertrauen auf Wagen setzen, weil ihrer viele, und auf Reiter, weil sie zahlreich sind; und die auf den Heiligen Israels nicht schauen und nach Jehova nicht fragen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Aber auch er ist weise und führt Unglück herbei, und nimmt seine Worte nicht zurück; und er steht auf wider das Haus der Übeltäter und wider die Helferschaft derer, welche Frevel tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Und die Ägypter sind Menschen und nicht Gott, und ihre Rosse sind Fleisch und nicht Geist. Und Jehova streckt seine Hand aus, und es strauchelt der Helfer, und es stürzt der, welchem geholfen wird; und sie werden zunichte alle miteinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Denn also hat Jehova zu mir gesprochen: Wie der Löwe und der junge Löwe, wider den der Hirten Menge zusammengerufen wird, über seinem Raube knurrt, vor ihrer Stimme nicht erschrickt und sich vor ihrem Lärmen nicht ergibt, also wird Jehova der Heerscharen herniedersteigen, um auf dem Berge Zion und auf seinem Hügel zu streiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Gleich schwirrenden Vögeln, also wird Jehova der Heerscharen Jerusalem beschirmen: beschirmen und erretten, schonen und befreien. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Kehret um, Kinder Israel, zu dem, von welchem ihr so weit abgewichen seid!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Denn an jenem Tage werden sie verabscheuen, ein jeder seine Götzen von Silber und seine Götzen von Gold, die eure Hände euch gemacht haben zur Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Und Assyrien wird fallen durch ein Schwert, nicht eines Mannes; und ein Schwert, nicht eines Menschen, wird es verzehren. Und es wird vor dem Schwerte fliehen, und seine Jünglinge werden fronpflichtig werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Und sein Fels wird vor Schrecken entweichen, und seine Fürsten werden vor dem Panier verzagen, spricht Jehova, der sein Feuer in Zion und seinen Ofen in Jerusalem hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Siehe, ein König wird regieren in Gerechtigkeit; und die Fürsten, sie werden nach Recht herrschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Und ein Mann wird sein wie ein Bergungsort vor dem Winde und ein Schutz vor dem Regensturm, wie Wasserbäche in dürrer Gegend, wie der Schatten eines gewaltigen Felsens in lechzendem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Und die Augen der Sehenden werden nicht mehr verklebt sein, und die Ohren der Hörenden werden aufmerken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'und das Herz der Unbesonnenen wird Erkenntnis erlangen, und die Zunge der Stammelnden wird fertig und deutlich reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Der gemeine Mensch wird nicht mehr edel genannt und der Arglistige nicht mehr vornehm geheißen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Denn ein gemeiner Mensch redet Gemeinheit; und sein Herz geht mit Frevel um, um Ruchlosigkeit zu verüben und Irrtum zu reden wider Jehova, um leer zu lassen die Seele des Hungrigen und dem Durstigen den Trank zu entziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Und der Arglistige, seine Werkzeuge sind böse: er entwirft böse Anschläge, um die Sanftmütigen durch Lügenreden zu Grunde zu richten, selbst wenn der Arme sein Recht dartut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Aber der Edle entwirft Edles, und auf Edlem besteht er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Stehet auf, ihr sorglosen Weiber, höret meine Stimme! Ihr sicheren Töchter, nehmet zu Ohren meine Rede!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Nach Jahr und Tag werdet ihr zittern, ihr Sicheren; denn die Weinlese ist dahin, die Obsternte kommt nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Bebet, ihr Sorglosen; zittert, ihr Sicheren! Ziehet euch aus und entblößet euch und umgürtet mit Sacktuch die Lenden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'An die Brust schlägt man sich wegen der lieblichen Fluren, wegen des fruchtbaren Weinstocks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Auf dem Felde meines Volkes schießen Gestrüpp und Dornen auf, ja, auf allen Häusern der Wonne in der frohlockenden Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Denn der Palast ist aufgegeben, verlassen das Getümmel der Stadt; Ophel und Wartturm dienen zu Höhlen auf ewig, zur Freude der Wildesel, zum Weideplatz der Herden-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'bis der Geist über uns ausgegossen wird aus der Höhe, und die Wüste zum Fruchtgefilde wird, und das Fruchtgefilde dem Walde gleichgeachtet wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Und das Recht wird sich niederlassen in der Wüste, und die Gerechtigkeit auf dem Fruchtgefilde wohnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'und das Werk der Gerechtigkeit wird Friede sein, und der Ertrag der Gerechtigkeit Ruhe und Sicherheit ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Und mein Volk wird wohnen an einer Wohnstätte des Friedens und in sicheren Wohnungen und an stillen Ruhestätten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Und es wird hageln beim Niedersturz des Waldes, und die Stadt wird in Niedrigkeit versinken. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Glückselig ihr, die ihr an allen Wassern säet, frei umherschweifen lasset den Fuß der Rinder und der Esel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Wehe dir, Verwüster, und du selbst wurdest nicht verwüstet; und dir, Räuber, und man hat dich nicht beraubt! Sobald du das Verwüsten vollendet hast, wirst du verwüstet werden; sobald du mit dem Rauben fertig bist, wirst du beraubt werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Jehova, sei uns gnädig! Auf dich harren wir; sei ihr Arm jeden Morgen, ja, unsere Rettung zur Zeit der Bedrängnis! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Vor dem Brausen deines Getümmels entfliehen die Völker, vor deiner Erhebung zerstreuen sich die Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Und weggerafft wird eure Beute, wie die Heuschrecken wegraffen; wie Heuschrecken rennen, rennt man darauf los.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Jehova ist hocherhaben; denn er wohnt in der Höhe, er füllt Zion mit Recht und Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Und es wird Festigkeit deiner Zeiten, Fülle von Heil, von Weisheit und Erkenntnis geben; die Furcht Jehovas wird sein Schatz sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Siehe, ihre Helden schreien draußen, die Friedensboten weinen bitterlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Die Straßen sind verödet, der Wanderer feiert. Er hat den Bund gebrochen, die Städte verachtet, keines Menschen geachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Es trauert, es schmachtet das Land; der Libanon steht beschämt da, er verdorrt; Saron ist einer Steppe gleich geworden, und Basan und Karmel schütteln ihr Laub ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Nun will ich aufstehen, spricht Jehova; nun will ich mich emporrichten, nun mich erheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Ihr gehet schwanger mit Heu, Stoppeln werdet ihr gebären; euer Schnauben ist ein Feuer, das euch verzehren wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Und die Völker werden zu Kalkbränden, wie abgehauene Dornen, die im Feuer verbrannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Höret, ihr Fernen, was ich getan, und ihr Nahen, erkennet meine Macht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Die Sünder in Zion sind erschrocken, Beben hat die Ruchlosen ergriffen. \"Wer von uns kann weilen bei verzehrendem Feuer? Wer von uns kann weilen bei ewigen Gluten?\" -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Wer in Gerechtigkeit wandelt und Aufrichtigkeit redet; wer den Gewinn der Bedrückungen verschmäht; wer seine Hände schüttelt, um keine Bestechung anzunehmen; wer sein Ohr verstopft, um nicht von Bluttaten zu hören, und seine Augen verschließt, um Böses nicht zu sehen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'der wird auf Höhen wohnen, Felsenfesten sind seine Burg; sein Brot wird ihm dargereicht, sein Wasser versiegt nie. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Deine Augen werden den König schauen in seiner Schönheit, sehen werden sie ein weithin offenes Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Dein Herz wird des Schreckens gedenken: Wo ist der Schreiber? Wo der Wäger? Wo, der die Türme zählte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Du wirst das freche Volk nicht mehr sehen, das Volk von unverständlicher Sprache, daß man sie nicht vernehmen, von stammelnder Zunge, die man nicht verstehen kann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Schaue Zion an, die Stadt unserer Festversammlungen! Deine Augen werden Jerusalem sehen, eine ruhige Wohnstätte, ein Zelt, das nicht wandern wird, dessen Pflöcke ewiglich nicht herausgezogen, und von dessen Seilen keines je losgerissen werden wird; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'sondern daselbst ist ein Mächtiger, Jehova, bei uns; ein Ort von Flüssen, von breiten Strömen: kein Ruderschiff kommt hinein, und durch denselben zieht kein mächtiges Schiff.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Denn Jehova ist unser Richter, Jehova unser Feldherr, Jehova unser König; er wird uns retten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Schlaff hängen deine Taue; sie halten nicht fest das Gestell ihres Mastes, halten das Segel nicht ausgebreitet. Dann wird ausgeteilt des Raubes Beute in Menge, selbst Lahme plündern die Beute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Und kein Einwohner wird sagen: Ich bin schwach. Dem Volke, das darin wohnt, wird die Missetat vergeben sein. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Tretet herzu, ihr Nationen, um zu hören; und ihr Völkerschaften, merket auf! Es höre die Erde und ihre Fülle, der Erdkreis und alles, was ihm entsproßt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Denn der Zorn Jehovas ergeht wider alle Nationen, und sein Grimm wider all ihr Heer. Er hat sie der Vertilgung geweiht, zur Schlachtung hingegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Und ihre Erschlagenen werden hingeworfen, und der Gestank ihrer Leichname steigt auf, und die Berge zerfließen von ihrem Blute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Und alles Heer der Himmel zerschmilzt; und die Himmel werden zusammengerollt wie ein Buch; und all ihr Heer fällt herab, wie das Blatt vom Weinstock abfällt und wie das Verwelkte vom Feigenbaum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Denn trunken ist im Himmel mein Schwert; siehe, auf Edom fährt es herab und auf das Volk meines Bannes zum Gericht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Das Schwert Jehovas ist voll Blut, es ist getränkt von Fett, vom Blute der Fettschafe und Böcke, vom Nierenfett der Widder; denn Jehova hat ein Schlachtopfer in Bozra und eine große Schlachtung im Lande Edom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Und Wildochsen stürzen mit ihnen hin, und Farren samt Stieren; und ihr Land wird trunken von Blut, und ihr Staub von Fett getränkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Denn Jehova hat einen Tag der Rache, ein Jahr der Vergeltungen für die Rechtssache Zions. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Und Edoms Bäche verwandeln sich in Pech und sein Staub in Schwefel; und sein Land wird zu brennendem Peche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Tag und Nacht erlischt es nicht, ewiglich steigt sein Rauch empor. Von Geschlecht zu Geschlecht liegt es verödet, für immer und ewig zieht niemand hindurch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Und Pelikan und Igel nehmen es in Besitz, und Eule und Rabe wohnen darin. Und er zieht darüber die Meßschnur der Öde und das Senkblei der Leere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Seine Edlen, keine sind da, welche das Königtum ausrufen; und alle seine Fürsten sind zu nichts geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Und in seinen Palästen schießen Dornen auf, Nesseln und Disteln in seinen Burgen; und es wird zur Wohnstätte der Schakale, zur Wohnung der Strauße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Und Wüstentiere treffen mit wilden Hunden zusammen, und Böcke begegnen einander; ja, dort rastet die Lilith und findet einen Ruheplatz für sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Dort nistet die Pfeilschlange und legt Eier und brütet sie aus in ihrem Schatten; ja, daselbst versammeln sich die Geier, einer zum anderen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Forschet nach im Buche Jehovas und leset! Es fehlt nicht eines von diesen, keines vermißt das andere. Denn mein Mund, er hat es geboten; und sein Geist, er hat sie zusammengebracht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'und er selbst hat ihnen das Los geworfen, und seine Hand hat es ihnen zugeteilt mit der Meßschnur. Ewiglich werden sie es besitzen, von Geschlecht zu Geschlecht darin wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Die Wüste und das dürre Land werden sich freuen, und die Steppe wird frohlocken und aufblühen wie eine Narzisse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Sie wird in voller Blüte stehen und frohlocken, ja, frohlockend und jubelnd; die Herrlichkeit des Libanon ist ihr gegeben, die Pracht des Karmel und Sarons: sehen werden sie die Herrlichkeit Jehovas, die Pracht unseres Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Stärket die schlaffen Hände und befestiget die wankenden Knie!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Saget zu denen, welche zaghaften Herzens sind: Seid stark, fürchtet euch nicht! Siehe, euer Gott kommt, Rache kommt, die Vergeltung Gottes! Er selbst kommt und wird euch retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Dann werden die Augen der Blinden aufgetan und die Ohren der Tauben geöffnet werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'dann wird der Lahme springen wie ein Hirsch, und aufjauchzen wird die Zunge des Stummen. Denn es brechen Wasser hervor in der Wüste, und Bäche in der Steppe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'und die Kimmung wird zum Teiche, und das dürre Land zu Wasserquellen; an der Wohnstätte der Schakale, wo sie lagern, wird Gras nebst Rohr und Binse sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Und daselbst wird eine Straße sein und ein Weg, und er wird der heilige Weg genannt werden; kein Unreiner wird darüber hinziehen, sondern er wird für sie sein. Wer auf dem Wege wandelt, selbst Einfältige werden nicht irregehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Daselbst wird kein Löwe sein, und kein reißendes Tier wird ihn ersteigen noch daselbst gefunden werden; und die Erlösten werden darauf wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Und die Befreiten Jehovas werden zurückkehren und nach Zion kommen mit Jubel, und ewige Freude wird über ihrem Haupte sein; sie werden Wonne und Freude erlangen, und Kummer und Seufzen werden entfliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Und es geschah im vierzehnten Jahre des Königs Hiskia, da zog Sanherib, der König von Assyrien, herauf wider alle festen Städte Judas und nahm sie ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Und der König von Assyrien sandte von Lachis den Rabsake zum König Hiskia, mit einem großen Heere, nach Jerusalem; und er hielt an der Wasserleitung des oberen Teiches, an der Straße des Walkerfeldes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Da gingen zu ihm hinaus Eljakim, der Sohn Hilkijas, der über das Haus war, und Schebna, der Schreiber, und Joach, der Sohn Asaphs, der Geschichtsschreiber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Und der Rabsake sprach zu ihnen: Saget doch zu Hiskia: So spricht der große König, der König von Assyrien: Was ist das für ein Vertrauen, womit du vertraust?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Ich sage: Nur ein Wort der Lippen ist Rat und Macht zum Kriege. Nun, auf wen vertraust du, daß du dich wider mich empört hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Siehe, du vertraust auf jenen geknickten Rohrstab, auf Ägypten, der, wenn jemand sich auf ihn stützt, ihm in die Hand fährt und sie durchbohrt. So ist der Pharao, der König von Ägypten, allen, die auf ihn vertrauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Und wenn du zu mir sprichst: Auf Jehova, unseren Gott, vertrauen wir; ist er es nicht, dessen Höhen und dessen Altäre Hiskia hinweggetan, da er zu Juda und zu Jerusalem gesagt hat: Vor diesem Altar sollt ihr anbeten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Und nun, laß dich doch ein mit meinem Herrn, dem König von Assyrien; und ich will dir zweitausend Rosse geben, wenn du dir Reiter darauf setzen kannst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Und wie wolltest du einen einzigen Befehlshaber von den geringsten Knechten meines Herrn zurücktreiben? Aber du vertraust auf Ägypten der Wagen und Reiter wegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Und nun, bin ich ohne Jehova wider dieses Land heraufgezogen, um es zu verheeren? Jehova hat zu mir gesagt: Ziehe hinauf in dieses Land und verheere es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Und Eljakim und Schebna und Joach sprachen zu dem Rabsake: Rede doch zu deinen Knechten auf aramäisch, denn wir verstehen es; und rede nicht zu uns auf jüdisch vor den Ohren des Volkes, das auf der Mauer ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Und der Rabsake sprach: Hat mein Herr mich zu deinem Herrn und zu dir gesandt, um diese Worte zu reden? nicht zu den Männern, die auf der Mauer sitzen, um mit euch ihren Kot zu essen und ihren Harn zu trinken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Und der Rabsake trat hin und rief mit lauter Stimme auf jüdisch und sprach: Höret die Worte des großen Königs, des Königs von Assyrien!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'So spricht der König: Daß Hiskia euch nicht täusche; denn er wird euch nicht zu erretten vermögen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Und daß Hiskia euch nicht auf Jehova vertröste, indem er spricht: Jehova wird uns gewißlich erretten; diese Stadt wird nicht in die Hand des Königs von Assyrien gegeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Höret nicht auf Hiskia; denn also spricht der König von Assyrien: Machet Frieden mit mir und kommet zu mir heraus, so sollt ihr ein jeder von seinem Weinstock und ein jeder von seinem Feigenbaum essen, und ein jeder das Wasser seines Brunnens trinken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'bis ich komme und euch in ein Land hole wie euer Land, ein Land von Korn und Most, ein Land von Brot und Weinbergen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Daß Hiskia euch nicht verführe, indem er spricht: Jehova wird uns erretten! Haben die Götter der Nationen ein jeder sein Land von der Hand des Königs von Assyrien errettet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Wo sind die Götter von Hammath und Arpad? Wo die Götter von Sepharwaim? Und haben sie Samaria von meiner Hand errettet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Welche sind es unter allen Göttern dieser Länder, die ihr Land von meiner Hand erretten haben, daß Jehova Jerusalem von meiner Hand erretten sollte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Und sie schwiegen still und antworteten ihm kein Wort; denn es war das Gebot des Königs, der gesagt hatte: Ihr sollt ihm nicht antworten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Und Eljakim, der Sohn Hilkijas, der über das Haus war, und Schebna, der Schreiber, und Joach, der Sohn Asaphs, der Geschichtsschreiber, kamen zu Hiskia mit zerrissenen Kleidern und berichteten ihm die Worte des Rabsake.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Und es geschah, als der König Hiskia es hörte, da zerriß er seine Kleider und hüllte sich in Sacktuch und ging in das Haus Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Und er sandte Eljakim, der über das Haus war, und Schebna, den Schreiber, und die Ältesten der Priester, in Sacktuch gehüllt zu dem Propheten Jesaja, dem Sohne Amoz\'.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Und sie sprachen zu ihm: So spricht Hiskia: Dieser Tag ist ein Tag der Bedrängnis und der Züchtigung und der Schmähung; denn die Kinder sind bis an die Geburt gekommen, aber da ist keine Kraft zum Gebären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Vielleicht wird Jehova, dein Gott, die Worte des Rabsake hören, welchen sein Herr, der König von Assyrien, gesandt hat, um den lebendigen Gott zu verhöhnen, und wird die Worte bestrafen, die Jehova, dein Gott, gehört hat. Erhebe denn ein Gebet für den Überrest, der sich noch vorfindet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Und die Knechte des Königs Hiskia kamen zu Jesaja.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Und Jesaja sprach zu ihnen: Also sollt ihr zu eurem Herrn sagen: So spricht Jehova: Fürchte dich nicht vor den Worten, die du gehört hast, womit die Diener des Königs von Assyrien mich gelästert haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Siehe, ich will ihm einen Geist eingeben, daß er ein Gerücht hören und in sein Land zurückkehren wird; und ich will ihn durchs Schwert fällen in seinem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Und der Rabsake kehrte zurück und fand den König von Assyrien streitend wider Libna; denn er hatte gehört, daß er von Lachis aufgebrochen wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Und er hörte von Tirhaka, dem König von Äthiopien, sagen: Er ist ausgezogen, um wider dich zu streiten. Und als er es hörte, sandte er Boten zu Hiskia und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'So sollt ihr zu Hiskia, dem Könige von Juda, sprechen und sagen: Daß dich nicht täusche dein Gott, auf den du vertraust, indem du sprichst: Jerusalem wird nicht in die Hand des Königs von Assyrien gegeben werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Siehe, du hast gehört, was die Könige von Assyrien allen Ländern getan haben, indem sie sie vertilgten; und du solltest errettet werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Haben die Götter der Nationen, welche meine Väter vernichtet haben, sie errettet: Gosan und Haran und Rezeph und die Kinder Edens, die in Telassar waren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Wo ist der König von Hamath und der König von Arpad und der König der Stadt Sepharwaim, von Hena und Iwa?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Und Hiskia nahm den Brief aus der Hand der Boten und las ihn; und er ging hinauf in das Haus Jehovas, und Hiskia breitete ihn vor Jehova aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Und Hiskia betete zu Jehova und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Jehova der Heerscharen, Gott Israels, der du zwischen den Cherubim thronst, du allein bist es, der der Gott ist von allen Königreichen der Erde; du hast den Himmel und die Erde gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Jehova, neige dein Ohr und höre! Jehova, tue deine Augen auf und sieh! Ja, höre alle die Worte Sanheribs, der gesandt hat, um den lebendigen Gott zu verhöhnen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Wahrlich, Jehova, die Könige von Assyrien haben alle Nationen und ihr Land verwüstet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'und sie haben ihre Götter ins Feuer geworfen, denn sie waren nicht Götter, sondern ein Werk von Menschenhänden, Holz und Stein, und sie haben sie zerstört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Und nun, Jehova, unser Gott, rette uns von seiner Hand, damit alle Königreiche der Erde wissen, daß du allein Jehova bist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Da sandte Jesaja, der Sohn Amoz\', zu Hiskia und ließ ihm sagen: So spricht Jehova, der Gott Israels: Was du zu mir gebetet hast wegen Sanheribs, des Königs von Assyrien-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'dies ist das Wort, welches Jehova über ihn geredet hat: Es verachtet dich, es spottet deiner die Jungfrau, die Tochter Zion; die Tochter Jerusalem schüttelt das Haupt dir nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Wen hast du verhöhnt und gelästert, und gegen wen die Stimme erhoben? Gegen den Heiligen Israels hast du deine Augen emporgerichtet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Durch deine Knechte hast du den Herrn verhöhnt und hast gesprochen: \"Mit meiner Wagen Menge habe ich die Höhen der Berge erstiegen, das äußerste Ende des Libanon; und ich werde umhauen den Hochwuchs seiner Zedern, die Auswahl seiner Zypressen, und ich werde kommen auf seine äußerste Höhe, in seinen Gartenwald.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Ich habe gegraben und Wasser getrunken; und mit der Sohle meiner Füße werde ich austrocknen alle Ströme Mazors.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Hast du nicht gehört, daß ich von fernher es gewirkt und von den Tagen der Vorzeit her es gebildet habe? Nun habe ich es kommen lassen, daß du feste Städte verwüstest zu öden Steinhaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Und ihre Bewohner waren machtlos, sie wurden bestürzt und beschämt; sie waren wie Kraut des Feldes und grünes Gras, wie Gras der Dächer, und Korn, das verbrannt ist, ehe es aufschießt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Und ich kenne dein Sitzen, und dein Aus-und dein Eingehen, und dein Toben wider mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Wegen deines Tobens wider mich, und weil dein Übermut in meine Ohren heraufgekommen ist, werde ich meinen Ring in deine Nase legen und mein Gebiß in deine Lippen, und werde dich zurückführen auf dem Wege, auf welchem du gekommen bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Und dies soll dir das Zeichen sein: Man wird in diesem Jahre den Nachwuchs der Ernte essen, und im zweiten Jahre was ausgesproßt ist; und im dritten Jahre säet und erntet, und pflanzet Weinberge und esset ihre Frucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Und das Entronnene vom Hause Juda, das übriggeblieben ist, wird wieder wurzeln nach unten und Frucht tragen nach oben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Denn von Jerusalem wird ein Überrest ausgehen, und ein Entronnenes vom Berge Zion. Der Eifer Jehovas der Heerscharen wird solches tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Darum, so spricht Jehova von dem König von Assyrien: Er soll nicht in diese Stadt kommen, und er soll keinen Pfeil darein schießen und keinen Schild ihr zukehren, und er soll keinen Wall gegen sie aufschütten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Auf dem Wege, den er gekommen ist, auf dem soll er zurückkehren und soll in diese Stadt nicht kommen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Und ich will diese Stadt beschirmen, um sie zu retten, um meinet-und um Davids, meines Knechtes, willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Und ein Engel Jehovas zog aus und schlug in dem Lager der Assyrer hundertfünfundachtzigtausend Mann. Und als man des Morgens früh aufstand, siehe, da waren sie allesamt Leichname.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Und Sanherib, der König von Assyrien, brach auf, und er zog fort und kehrte zurück und blieb in Ninive.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Und es geschah, als er sich niederbeugte im Hause Nisroks, seines Gottes, da erschlugen ihn Adrammelek und Scharezer, seine Söhne, mit dem Schwerte; und sie entrannen in das Land Ararat. Und Esar-Haddon, sein Sohn, ward König an seiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'In jenen Tagen wurde Hiskia krank zum Sterben. Und Jesaja, der Sohn Amoz\', der Prophet, kam zu ihm und sprach zu ihm: So spricht Jehova: Bestelle dein Haus, denn du wirst sterben und nicht genesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Da wandte Hiskia sein Angesicht gegen die Wand und betete zu Jehova und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'Ach, Jehova! Gedenke doch, daß ich vor deinem Angesicht gewandelt habe in Wahrheit und mit ungeteiltem Herzen, und daß ich getan, was gut ist in deinen Augen! Und Hiskia weinte sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Da geschah das Wort Jehovas zu Jesaja also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Geh hin und sage zu Hiskia: So spricht Jehova, der Gott deines Vaters David: Ich habe dein Gebet gehört, ich habe deine Tränen gesehen; siehe, ich will zu deinen Tagen fünfzehn Jahre hinzufügen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Und von der Hand des Königs von Assyrien will ich dich und diese Stadt erretten; und ich will diese Stadt beschirmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Und dies wird dir das Zeichen sein von seiten Jehovas, daß Jehova dieses Wort tun wird, welches er geredet hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Siehe, ich lasse den Schatten der Grade, welche er an dem Sonnenzeiger Ahas\' durch die Sonne niederwärts gegangen ist, um zehn Grade rückwärts gehen. Und die Sonne kehrte an dem Sonnenzeiger zehn Grade zurück, welche sie niederwärts gegangen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Aufzeichnung Hiskias, des Königs von Juda, als er krank gewesen und von seiner Krankheit genesen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Ich sprach: In der Ruhe meiner Tage soll ich hingehen zu den Pforten des Scheol, bin beraubt des Restes meiner Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Ich sprach: Ich werde Jehova nicht sehen, Jehova im Lande der Lebendigen; ich werde Menschen nicht mehr erblicken bei den Bewohnern des Totenreiches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Meine Wohnung ist abgebrochen und ward von mir weggeführt wie ein Hirtenzelt. Ich habe, dem Weber gleich, mein Leben aufgerollt: vom Trumme schnitt er mich los. Vom Tage bis zur Nacht wirst du ein Ende mit mir machen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Ich beschwichtigte meine Seele bis zum Morgen... dem Löwen gleich, also zerbrach er alle meine Gebeine. Vom Tage bis zur Nacht wirst du ein Ende mit mir machen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Wie eine Schwalbe, wie ein Kranich, so klagte ich; ich girrte wie die Taube. Schmachtend blickten meine Augen zur Höhe: O Herr, mir ist bange! Tritt als Bürge für mich ein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Was soll ich sagen? Daß er es mir zugesagt und es auch ausgeführt hat. Ich will sachte wallen alle meine Jahre wegen der Betrübnis meiner Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'O Herr! Durch dieses lebt man, und in jeder Hinsicht ist darin das Leben meines Geistes. Und du machst mich gesund und erhältst mich am Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Siehe, zum Heile ward mir bitteres Leid: Du, du zogest liebevoll meine Seele aus der Vernichtung Grube; denn alle meine Sünden hast du hinter deinen Rücken geworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Denn nicht der Scheol preist dich, der Tod lobsingt dir nicht; die in die Grube hinabgefahren sind, harren nicht auf deine Treue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Der Lebende, der Lebende, der preist dich, wie ich heute: der Vater gibt den Kindern Kunde von deiner Treue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Jehova war bereit, mich zu retten; und wir wollen mein Saitenspiel rühren alle Tage unseres Lebens im Hause Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Und Jesaja sagte, daß man einen Feigenkuchen als Pflaster nehmen und ihn auf das Geschwür legen solle, damit er genese.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Und Hiskia sprach: Welches ist das Zeichen, daß ich in das Haus Jehovas hinaufgehen werde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Zu jener Zeit sandte Merodak-Baladan, der Sohn Baladans, der König von Babel, Brief und Geschenk an Hiskia; denn er hatte gehört, daß er krank gewesen und wieder gesund geworden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Und Hiskia freute sich über sie und zeigte ihnen sein Schatzhaus: Das Silber und das Gold und die Gewürze und das köstliche Öl; und sein ganzes Zeughaus, und alles, was sich in seinen Schätzen vorfand; es war nichts in seinem Hause und in seiner ganzen Herrschaft, das Hiskia ihnen nicht gezeigt hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Da kam Jesaja, der Prophet, zum König Hiskia und sprach zu ihm: Was haben diese Männer gesagt? Und woher sind sie zu dir gekommen? Und Hiskia sprach: Aus fernem Lande sind sie zu mir gekommen, von Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Und er sprach: Was haben sie in deinem Hause gesehen? Und Hiskia sprach: Sie haben alles gesehen, was in meinem Hause ist; es gibt nichts in meinen Schätzen, das ich ihnen nicht gezeigt hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Da sprach Jesaja zu Hiskia: Höre das Wort Jehovas der Heerscharen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Siehe, es kommen Tage, da alles, was in deinem Hause ist und was deine Väter aufgehäuft haben bis auf diesen Tag, nach Babel weggebracht werden wird; es wird nichts übrigbleiben, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Und von deinen Söhnen, die aus dir hervorkommen werden, die du zeugen wirst, wird man nehmen, und sie werden Kämmerer sein im Palaste des Königs von Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Und Hiskia sprach zu Jesaja: Das Wort Jehovas ist gut, das du geredet hast; und er sprach: Es wird ja Friede und Bestand sein in meinen Tagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Tröstet, tröstet mein Volk! spricht euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Redet zum Herzen Jerusalems, und rufet ihr zu, daß ihre Mühsal vollendet, daß ihre Schuld abgetragen ist, daß sie von der Hand Jehovas Zwiefältiges empfangen hat für alle ihre Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Stimme eines Rufenden: In der Wüste bahnet den Weg Jehovas; ebnet in der Steppe eine Straße für unseren Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Jedes Tal soll erhöht und jeder Berg und Hügel erniedrigt werden; und das Höckerichte soll zur Ebene werden, und das Hügelige zur Niederung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Und die Herrlichkeit Jehovas wird sich offenbaren, und alles Fleisch miteinander wird sie sehen; denn der Mund Jehovas hat geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Stimme eines Sprechenden: Rufe! Und er spricht: Was soll ich rufen? \"Alles Fleisch ist Gras, und alle seine Anmut wie die Blume des Feldes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Das Gras ist verdorrt, die Blume ist abgefallen; denn der Hauch Jehovas hat sie angeweht. Fürwahr, das Volk ist Gras.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Das Gras ist verdorrt, die Blume ist abgefallen; aber das Wort unseres Gottes besteht in Ewigkeit.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Auf einen hohen Berg steige hinauf, Zion, du Verkündigerin froher Botschaft; erhebe mit Macht deine Stimme, Jerusalem, du Verkündigerin froher Botschaft! Erhebe sie, fürchte dich nicht; sprich zu den Städten Judas:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Siehe da, euer Gott! Siehe, der Herr, Jehova, kommt mit Kraft, und sein Arm übt Herrschaft für ihn; siehe, sein Lohn ist bei ihm, und seine Vergeltung geht vor ihm her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Er wird seine Herde weiden wie ein Hirt, die Lämmer wird er in seinen Arm nehmen und in seinem Busen tragen, die Säugenden wird er sanft leiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Wer hat die Wasser gemessen mit seiner hohlen Hand und die Himmel abgegrenzt mit der Spanne, und hat den Staub der Erde in ein Maß gefaßt, und die Berge mit der Waage gewogen und die Hügel mit Waagschalen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Wer hat den Geist Jehovas gelenkt, und wer, als sein Ratgeber, ihn unterwiesen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Mit wem beriet er sich, daß er ihm Verstand gegeben und ihn belehrt hätte über den Pfad des Rechts, und ihn Erkenntnis gelehrt und ihm den Weg der Einsicht kundgemacht hätte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Siehe, Nationen sind geachtet wie ein Tropfen am Eimer und wie ein Sandkorn auf der Waagschale. Siehe, Inseln sind wie ein Stäubchen, das emporschwebt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Und der Libanon reicht nicht hin zum Brennholz, und sein Wild reicht nicht hin zum Brandopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Alle Nationen sind wie nichts vor ihm, und werden von ihm geachtet wie Nichtigkeit und Leere. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Und wem wollt ihr Gott vergleichen? Und was für ein Gleichnis wollt ihr ihm an die Seite stellen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Hat der Künstler das Bild gegossen, so überzieht es der Schmelzer mit Gold und schweißt silberne Ketten daran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Wer arm ist, so daß er nicht viel opfern kann, der wählt ein Holz, das nicht fault; er sucht sich einen geschickten Künstler, um ein Bild herzustellen, das nicht wanke. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Wisset ihr es nicht? Höret ihr es nicht? Ist es euch nicht von Anbeginn verkündet worden? Habt ihr nicht Einsicht erlangt in die Grundlegung der Erde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Er ist es, der da thront über dem Kreise der Erde, und ihre Bewohner sind wie Heuschrecken; der die Himmel ausgespannt hat wie einen Flor und sie ausgebreitet wie ein Zelt zum Wohnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'der die Fürsten zu nichts macht, die Richter der Erde in Nichtigkeit verwandelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Kaum sind sie gepflanzt, kaum sind sie gesät, kaum hat ihr Stock Wurzeln in der Erde getrieben: da bläst er sie schon an, und sie verdorren, und ein Sturmwind rafft sie wie Stoppeln hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Wem denn wollt ihr mich vergleichen, dem ich gleich wäre? spricht der Heilige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Hebet zur Höhe eure Augen empor und sehet: Wer hat diese da geschaffen? Er, der ihr Heer herausführt nach der Zahl, ruft sie alle mit Namen: Wegen der Größe seiner Macht und der Stärke seiner Kraft bleibt keines aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Warum sprichst du, Jakob, und redest du, Israel: Mein Weg ist verborgen vor Jehova, und mein Recht entgeht meinem Gott?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Weißt du es nicht? Oder hast du es nicht gehört? Ein ewiger Gott ist Jehova, der Schöpfer der Enden der Erde; er ermüdet nicht und ermattet nicht, unergründlich ist sein Verstand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Er gibt dem Müden Kraft, und dem Unvermögenden reicht er Stärke dar in Fülle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Und Jünglinge ermüden und ermatten, und junge Männer fallen hin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'aber die auf Jehova harren, gewinnen neue Kraft: sie heben die Schwingen empor wie die Adler; sie laufen und ermatten nicht, sie gehen und ermüden nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Wendet euch schweigend zu mir, ihr Inseln; und die Völkerschaften mögen neue Kraft gewinnen; sie mögen herannahen, dann mögen sie reden; laßt uns miteinander vor Gericht treten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Wer hat vom Aufgang her den erweckt, welchem Gerechtigkeit auf Schritt und Tritt begegnet? Er gab Nationen vor ihm dahin und ließ ihn Könige unterjochen, machte sie wie Staub vor seinem Schwerte, wie fortgetriebene Stoppeln vor seinem Bogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Er verfolgte sie, zog hin in Frieden einen Weg, den er mit seinen Füßen nie gegangen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Wer hat es gewirkt und getan? Der die Geschlechter ruft von Anbeginn. Ich, Jehova, bin der Erste, und bei den Letzten bin ich derselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Die Inseln sahen es und fürchteten sich, es erbebten die Enden der Erde; sie näherten sich und kamen herbei:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Einer half dem anderen und sprach zu seinem Bruder: Sei mutig!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Und der Künstler ermutigte den Schmelzer, der mit dem Hammer glättet ermutigte den, der auf den Amboß schlägt, und sprach von der Lötung: Sie ist gut; und er befestigte es mit Nägeln, daß es nicht wanke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Du aber, Israel, mein Knecht, Jakob, den ich erwählt habe, Same Abrahams, meines Freundes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'du, den ich ergriffen von den Enden der Erde und von ihren fernsten Gegenden her gerufen habe, und zu welchem ich sprach: Du bist mein Knecht, ich habe dich erwählt und nicht verschmäht-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'fürchte dich nicht, denn ich bin mit dir; schaue nicht ängstlich umher, denn ich bin dein Gott; ich stärke dich, ja, ich helfe dir, ja, ich stütze dich mit der Rechten meiner Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Siehe, es sollen beschämt und zu Schanden werden alle, die wider dich entbrannt sind; es sollen wie nichts werden und umkommen deine Widersacher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Du wirst sie suchen und nicht finden, die Männer, die mit dir hadern; wie nichts und wie Nichtigkeit sollen die Männer werden, die dich bekriegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Denn ich, Jehova, dein Gott, ergreife deine Rechte, der ich zu dir spreche: Fürchte dich nicht, ich helfe dir! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Fürchte dich nicht, du Wurm Jakob, du Häuflein Israel; ich helfe dir, spricht Jehova, und dein Erlöser ist der Heilige Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Siehe, ich habe dich zu einem scharfen, neuen Dreschschlitten gemacht, mit Doppelschneiden versehen: du wirst Berge dreschen und zermalmen, und Hügel der Spreu gleich machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'du wirst sie worfeln, daß der Wind sie entführt und der Sturm sie zerstreut. Du aber, du wirst in Jehova frohlocken und in dem Heiligen Israels dich rühmen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Die Elenden und die Armen, welche nach Wasser suchen, und keines ist da, deren Zunge vor Durst vertrocknet: Ich, Jehova, werde sie erhören, ich, der Gott Israels, werde sie nicht verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Ich werde Ströme hervorbrechen lassen auf den kahlen Höhen, und Quellen inmitten der Talebenen; ich werde die Wüste zum Wasserteich machen, und das dürre Land zu Wasserquellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Ich werde Zedern in die Wüste setzen, Akazien und Myrten und Olivenbäume, werde in die Steppe pflanzen Zypressen, Platanen und Scherbinzedern miteinander;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'damit sie sehen und erkennen und zu Herzen nehmen und verstehen allzumal, daß die Hand Jehovas dieses getan und der Heilige Israels es geschaffen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Bringet eure Rechtssache vor, spricht Jehova; bringet eure Beweisgründe herbei, spricht der König Jakobs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Sie mögen herbeibringen und uns verkünden, was sich ereignen wird: das Zunächstkommende, was es sein wird, verkündet, damit wir es zu Herzen nehmen und dessen Ausgang wissen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'oder laßt uns das Künftige hören, verkündet das späterhin Kommende, damit wir erkennen, daß ihr Götter seid! Ja, tut Gutes oder tut Böses, damit wir uns gegenseitig anblicken und miteinander es sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Siehe, ihr seid nichts, und euer Tun ist Nichtigkeit; ein Greuel ist, wer euch erwählt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Ich habe ihn von Norden her erweckt, und er kam herbei, von Sonnenaufgang her den, der meinen Namen anruft. Und er tritt auf Fürsten wie auf Lehm, und wie ein Töpfer, welcher Ton zerknetet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Wer hat es verkündet von Anbeginn, daß wir es wüßten? Und von ehedem, daß wir sagen könnten: Es ist recht! Ja, da war keiner, der es verkündete, ja, keiner, der es hören ließ, ja, keiner, der eure Worte gehört hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Als Erster habe ich zu Zion gesagt: Siehe, siehe, da ist es! Und Jerusalem will ich einen Freudenboten geben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Und ich sah hin: und da war niemand, und unter diesen war kein Bescheidgeber, daß ich sie hätte fragen können, und sie mir Antwort gegeben hätten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Siehe, sie allesamt, Eitelkeit, Nichtigkeit sind ihre Machwerke, Wind und Leere ihre gegossenen Bilder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Siehe, mein Knecht, den ich stütze, mein Auserwählter, an welchem meine Seele Wohlgefallen hat: Ich habe meinen Geist auf ihn gelegt, er wird den Nationen das Recht kundtun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Er wird nicht schreien und nicht rufen, noch seine Stimme hören lassen auf der Straße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Das geknickte Rohr wird er nicht zerbrechen, und den glimmenden Docht wird er nicht auslöschen; er wird der Wahrheit gemäß das Recht kundtun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Er wird nicht ermatten noch niedersinken, bis er das Recht auf Erden gegründet hat; und die Inseln werden auf seine Lehre harren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'So spricht Gott, Jehova, der die Himmel schuf und sie ausspannte, der die Erde ausbreitete mit ihren Gewächsen, dem Volke auf ihr den Odem gab, und den Lebenshauch denen, die darauf wandeln:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Ich, Jehova, ich habe dich gerufen in Gerechtigkeit und ergriff dich bei der Hand; und ich werde dich behüten und dich setzen zum Bunde des Volkes, zum Licht der Nationen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'um blinde Augen aufzutun, um Gefangene aus dem Kerker herauszuführen, und aus dem Gefängnis, die in der Finsternis sitzen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Ich bin Jehova, das ist mein Name; und meine Ehre gebe ich keinem anderen, noch meinen Ruhm den geschnitzten Bildern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Das Frühere, siehe, es ist eingetroffen, und Neues verkündige ich; ehe es hervorsproßt, lasse ich es euch hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Singet Jehova ein neues Lied, seinen Ruhm vom Ende der Erde: die ihr das Meer befahret, und alles, was es erfüllt, ihr Inseln und ihre Bewohner!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Es mögen ihre Stimme erheben die Steppe und ihre Städte, die Dörfer, welche Kedar bewohnt; jubeln mögen die Bewohner von Sela, jauchzen vom Gipfel der Berge her!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Man möge Jehova Ehre geben und seinen Ruhm verkündigen auf den Inseln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Jehova wird ausziehen wie ein Held, wie ein Kriegsmann den Eifer anfachen; er wird einen Schlachtruf, ja, ein gellendes Kriegsgeschrei erheben, sich als Held beweisen gegen seine Feinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Von lange her habe ich geschwiegen, war still, habe an mich gehalten. Gleich einer Gebärenden will ich tief aufatmen, schnauben und schnaufen zumal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Ich will Berge und Hügel öde machen und all ihr Kraut vertrocknen lassen; und ich will Ströme zu Inseln machen; und Seen trocken legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Und ich will die Blinden auf einem Wege führen, den sie nicht kennen; auf Steigen, die sie nicht kennen, will ich sie schreiten lassen; die Finsternis vor ihnen will ich zum Lichte machen, und das Höckerichte zur Ebene. Das sind die Dinge, die ich tun und nicht unterlassen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Die auf das geschnitzte Bild vertrauen, die zu dem gegossenen Bilde sagen: Du bist unser Gott! werden zurückweichen, werden gänzlich beschämt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Höret, ihr Tauben! Und ihr Blinden, schauet her, um zu sehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Wer ist blind, als nur mein Knecht? Und taub wie mein Bote, den ich sende? Wer ist blind wie der Vertraute, und blind wie der Knecht Jehovas?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Du hast vieles gesehen, aber du beachtest es nicht; bei offenen Ohren hört er nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Jehova gefiel es um seiner Gerechtigkeit willen, das Gesetz groß und herrlich zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Und doch ist es ein beraubtes und ausgeplündertes Volk; sie sind in Löchern gefesselt und allesamt in Kerkern versteckt; sie sind zur Beute geworden, und kein Erretter ist da, zur Plünderung, und niemand spricht: Gib wieder heraus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Wer unter euch will dieses zu Ohren nehmen, will aufmerken und in Zukunft hören?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Wer hat Jakob der Plünderung hingegeben und Israel den Räubern? Nicht Jehova, gegen den wir gesündigt haben? Und sie wollten nicht auf seinen Wegen wandeln, und hörten nicht auf sein Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Da hat er die Glut seines Zornes und die Gewalt des Krieges über ihn ausgegossen; und diese hat ihn ringsum angezündet, aber er ist nicht zur Erkenntnis gekommen; und sie hat ihn in Brand gesteckt, aber er nahm es nicht zu Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Und nun, so spricht Jehova, der dich geschaffen, Jakob, und der dich gebildet hat, Israel: Fürchte dich nicht, denn ich habe dich erlöst; ich habe dich bei deinem Namen gerufen, du bist mein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Wenn du durchs Wasser gehst, ich bin bei dir, und durch Ströme, sie werden dich nicht überfluten; wenn du durchs Feuer gehst, wirst du nicht versengt werden, und die Flamme wird dich nicht verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Denn ich bin Jehova, dein Gott, ich, der Heilige Israels, dein Heiland; ich gebe als dein Lösegeld Ägypten hin, Äthiopien und Seba an deiner Statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Weil du teuer, wertvoll bist in meinen Augen, und ich dich lieb habe, so werde ich Menschen hingeben an deiner Statt und Völkerschaften anstatt deines Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Fürchte dich nicht, denn ich bin mit dir; vom Aufgang her werde ich deinen Samen bringen, und vom Niedergang her werde ich dich sammeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Ich werde zum Norden sagen: Gib heraus! Und zum Süden: Halte nicht zurück, bringe meine Söhne von fernher und meine Töchter vom Ende der Erde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'einen jeden, der mit meinem Namen genannt ist, und den ich zu meiner Ehre geschaffen, den ich gebildet, ja, gemacht habe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Führe heraus das blinde Volk, das doch Augen hat, und die Tauben, die doch Ohren haben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Alle Nationen mögen sich miteinander versammeln, und die Völkerschaften zusammenkommen! Wer unter ihnen kann solches verkünden? So mögen sie uns Früheres hören lassen! Mögen sie ihre Zeugen stellen und gerechtfertigt werden, daß man es höre und sage: Es ist wahr!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Ihr seid meine Zeugen, spricht Jehova, und mein Knecht, den ich erwählt habe: damit ihr erkennet und mir glaubet und einsehet, daß ich derselbe bin. Vor mir ward kein Gott gebildet, und nach mir wird keiner sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Ich, ich bin Jehova, und außer mir ist kein Heiland.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Ich habe verkündigt und gerettet und vernehmen lassen, und kein fremder Gott war unter euch; und ihr seid meine Zeugen, spricht Jehova, und ich bin Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Ja, von jeher bin ich derselbe; und da ist niemand, der aus meiner Hand errette. Ich wirke, und wer kann es abwenden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'So spricht Jehova, euer Erlöser, der Heilige Israels: Um euretwillen habe ich nach Babel gesandt; und ich werde sie alle als Flüchtlinge hinabtreiben, und auch die Chaldäer, auf den Schiffen ihres Jubels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Ich, Jehova, bin euer Heiliger, ich, der Schöpfer Israels, euer König. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'So spricht Jehova, der einen Weg gibt im Meere, und einen Pfad in mächtigen Wassern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'der ausziehen läßt Wagen und Roß, Heer und Held, zusammen liegen sie da, stehen nicht wieder auf; sie sind erloschen, verglommen wie ein Docht: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Gedenket nicht des Früheren, und über die Dinge der Vorzeit sinnet nicht nach!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Siehe, ich wirke Neues; jetzt sproßt es auf; werdet ihr es nicht erfahren? Ja, ich mache durch die Wüste einen Weg, Ströme durch die Einöde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Das Getier des Feldes wird mich preisen, Schakale und Strauße; denn ich werde Wasser geben in der Wüste, Ströme in der Einöde, um mein Volk zu tränken, mein auserwähltes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Dieses Volk, das ich mir gebildet habe, sie sollen meinen Ruhm erzählen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Doch nicht mich hast du angerufen, Jakob, daß du dich um mich gemüht hättest, Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Du hast mir die Schafe deiner Brandopfer nicht gebracht, und mit deinen Schlachtopfern hast du mich nicht geehrt; ich habe dir nicht mit Speisopfern zu schaffen gemacht, noch mit Weihrauch dich ermüdet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'du hast mir nicht um Geld Würzrohr gekauft, noch mit dem Fette deiner Schlachtopfer mich gelabt. Aber du hast mir zu schaffen gemacht mit deinen Sünden, du hast mich ermüdet mit deinen Missetaten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Ich, ich bin es, der deine Übertretungen tilgt um meinetwillen; und deiner Sünden will ich nicht mehr gedenken. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Rufe mir ins Gedächtnis, wir wollen rechten miteinander; erzähle doch, damit du gerechtfertigt werdest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Dein erster Vater hat gesündigt, und deine Mittler sind von mir abgefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Und ich habe die Fürsten des Heiligtums entweiht, und Jakob dem Banne und Israel den Schmähungen hingegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Und nun höre, Jakob, mein Knecht, und du, Israel, den ich erwählt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'So spricht Jehova, der dich gemacht und von Mutterleibe an dich gebildet hat, der dir hilft: Fürchte dich nicht, mein Knecht Jakob, und du, Jeschurun, den ich erwählt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Denn ich werde Wasser gießen auf das Durstige, und Bäche auf das Trockene; ich werde meinen Geist ausgießen auf deinen Samen, und meinen Segen auf deine Sprößlinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'Und sie werden aufsprossen zwischen dem Grase wie Weiden an Wasserbächen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Dieser wird sagen: Ich bin Jehovas; und der wird den Namen Jakobs ausrufen; und jener wird mit seiner Hand schreiben: Ich bin Jehovas, und wird den Namen Israels ehrend nennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'So spricht Jehova, der König Israels und sein Erlöser, Jehova der Heerscharen: Ich bin der Erste und bin der Letzte, und außer mir ist kein Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Und wer ruft aus wie ich, so verkünde er es und lege es mir vor! seitdem ich das Volk der Urzeit eingesetzt habe? Und das Zukünftige und was da kommen wird, mögen sie verkünden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Erschrecket nicht und zittert nicht! Habe ich es nicht von längsther dich hören lassen und dir verkündet? Und ihr seid meine Zeugen. Gibt es einen Gott außer mir? Und es gibt keinen Fels, ich weiß keinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Die Bildner geschnitzter Bilder sind allesamt nichtig, und ihre Lieblinge nützen nichts; und die für sie zeugen, sehen nicht und haben keine Erkenntnis, damit sie beschämt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Wer hat einen Gott gebildet und ein Bild gegossen, daß es nichts nütze?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Siehe, alle seine Genossen werden beschämt werden; und die Künstler sind ja nur Menschen. Mögen sie sich alle versammeln, hintreten: erschrecken sollen sie, beschämt werden allzumal!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Der Eisenschmied hat ein Werkzeug und arbeitet bei Kohlenglut, und er gestaltet es mit Hämmern und verarbeitet es mit seinem kräftigen Arm. Er wird auch hungrig und kraftlos; er hat kein Wasser getrunken und ermattet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Der Holzschnitzler spannt die Schnur, zeichnet es ab mit dem Stifte, führt es aus mit den Hobeln und zeichnet es ab mit dem Zirkel; und er macht es wie das Bildnis eines Mannes, wie die Schönheit eines Menschen, damit es in einem Hause wohne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Man haut sich Zedern ab, oder nimmt eine Steineiche oder eine Eiche, und wählt sich aus unter den Bäumen des Waldes; man pflanzt eine Fichte, und der Regen macht sie wachsen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Und es dient dem Menschen zur Feuerung, und er nimmt davon und wärmt sich; auch heizt er und bäckt Brot; auch verarbeitet er es zu einem Gott und wirft sich davor nieder, macht ein Götzenbild daraus und betet es an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Die Hälfte davon hat er im Feuer verbrannt; bei der Hälfte davon ißt er Fleisch, brät einen Braten und sättigt sich; auch wärmt er sich und spricht: Ha! Mir wird\'s warm, ich spüre Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Und das Übrige davon macht er zu einem Gott, zu seinem Götzenbilde; er betet es an und wirft sich nieder, und er betet zu ihm und spricht: Errette mich, denn du bist mein Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Sie haben keine Erkenntnis und keine Einsicht; denn er hat ihre Augen verklebt, daß sie nicht sehen, und ihre Herzen, daß sie nicht verstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Und man nimmt es nicht zu Herzen, und da ist keine Erkenntnis und keine Einsicht, daß man sagte: Die Hälfte davon habe ich im Feuer verbrannt, und auch habe ich auf seinen Kohlen Brot gebacken, Fleisch gebraten, und habe gegessen; und den Rest davon sollte ich zu einem Greuel machen, ich sollte ein Stück Holz anbeten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Wer der Asche nachgeht, ein betörtes Herz hat ihn irregeführt, so daß er seine Seele nicht errettet und sagt: Ist nicht Lüge in meiner Rechten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Gedenke dessen, Jakob und Israel! Denn du bist mein Knecht. Ich habe dich gebildet, du bist mein Knecht; Israel, du wirst nicht von mir vergessen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Ich habe deine Übertretungen getilgt wie einen Nebel, und wie eine Wolke deine Sünden. Kehre um zu mir, denn ich habe dich erlöst!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Jubelt, ihr Himmel! Denn Jehova hat es vollführt; jauchzet, ihr Tiefen der Erde! Brechet in Jubel aus, ihr Berge, du Wald und jeder Baum darin! Denn Jehova hat Jakob erlöst, und an Israel verherrlicht er sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'So spricht Jehova, dein Erlöser und der von Mutterleibe an dich gebildet hat: Ich, Jehova, bin es, der alles wirkt, der die Himmel ausspannte, ich allein, die Erde ausbreitete durch mich selbst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'der die Wunderzeichen der Lügner vereitelt und die Wahrsager zu Narren macht; der die Weisen zurückdrängt und ihr Wissen zur Torheit macht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'der das Wort seines Knechtes bestätigt und den Bescheid seiner Boten vollführt; der von Jerusalem spricht: Es soll bewohnt werden! Und von den Städten Judas: Sie sollen aufgebaut werden, und ich will seine Trümmer wieder aufrichten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Der zu der Flut spricht: Versiege, und ich will deine Ströme austrocknen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Der von Kores spricht: Mein Hirt, und der all mein Wohlgefallen vollführt, indem er von Jerusalem sprechen wird: Es werde aufgebaut! Und vom Tempel: Er werde gegründet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'So spricht Jehova zu seinem Gesalbten, zu Kores, dessen Rechte ich ergriffen habe, um Nationen vor ihm niederzuwerfen, und damit ich die Lenden der Könige entgürte, um Pforten vor ihm aufzutun, und damit Tore nicht verschlossen bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Ich, ich werde vor dir herziehen und werde das Höckerichte eben machen; eherne Pforten werde ich zerbrechen und eiserne Riegel zerschlagen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'und ich werde dir verborgene Schätze und versteckte Reichtümer geben, auf daß du wissest, daß ich Jehova bin, der dich bei deinem Namen gerufen hat, der Gott Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Um Jakobs, meines Knechtes, und Israels, meines Auserwählten, willen rief ich dich bei deinem Namen, ich gab dir einen Beinamen, und du kanntest mich nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'ich bin Jehova, und sonst ist keiner, außer mir ist kein Gott; ich gürtete dich, und du kanntest mich nicht: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'auf daß man wisse vom Aufgang der Sonne und von ihrem Niedergang her, daß außer mir gar keiner ist. Ich bin Jehova, und sonst ist keiner!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Der ich das Licht bilde und die Finsternis schaffe, den Frieden mache und das Unglück schaffe; ich, Jehova, bin es, der dieses alles wirkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Träufelt, ihr Himmel droben, und Gerechtigkeit mögen rieseln die Wolken! Die Erde tue sich auf, und es sprosse Heil, und sie lasse Gerechtigkeit hervorwachsen zugleich! Ich, Jehova, habe es geschaffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Wehe dem, der mit seinem Bildner rechtet, ein Tongefäß unter irdenen Tongefäßen! Darf wohl der Ton zu seinem Bildner sagen: Was machst du? Und dein Werk von dir: Er hat keine Hände?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Wehe dem, der zum Vater spricht: Warum zeugst du? Und zum Weibe: Warum gebierst du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'So spricht Jehova, der Heilige Israels und der es gebildet hat: Über das Zukünftige fraget mich; meine Kinder und das Werk meiner Hände lasset mir anbefohlen sein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Ich habe die Erde gemacht und den Menschen auf ihr geschaffen; meine Hände haben die Himmel ausgespannt, und all ihr Heer habe ich bestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Ich habe ihn erweckt in Gerechtigkeit, und alle seine Wege werde ich ebnen; er wird meine Stadt bauen und meine Weggeführten entlassen, nicht um Kaufgeld und nicht um ein Geschenk, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'So spricht Jehova: Der Reichtum Ägyptens und der Erwerb Äthiopiens und die Sabäer, Männer von hohem Wuchse, werden zu dir übergehen und dir gehören; sie werden dir nachfolgen, in Fesseln werden sie zu dir übergehen; und sie werden sich vor dir niederwerfen, werden zu dir flehen: Fürwahr, Gott ist in dir; und sonst ist kein, gar kein Gott! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Wahrlich, du bist ein Gott, der sich verborgen hält, du Gott Israels, du Heiland! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Sie alle werden beschämt und auch zu Schanden, sie gehen insgesamt mit Schande dahin, die Götzenmacher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Israel wird gerettet durch Jehova mit ewiger Rettung; ihr werdet nicht beschämt und nicht zu Schanden werden in alle Ewigkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Denn so spricht Jehova, der die Himmel geschaffen (er ist Gott), der die Erde gebildet und sie gemacht hat (er hat sie bereitet; nicht als eine Öde hat er sie geschaffen; um bewohnt zu werden, hat er sie gebildet): Ich bin Jehova, und sonst ist keiner!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Nicht im verborgenen habe ich geredet, an einem Orte des Landes der Finsternis; ich sprach nicht zu dem Samen Jakobs: Suchet mich vergeblich. Ich bin Jehova, der Gerechtigkeit redet, Aufrichtiges verkündet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Versammelt euch und kommet, nähert euch insgesamt, ihr Entronnenen der Nationen! Es haben keine Erkenntnis, die das Holz ihres geschnitzten Bildes tragen und zu einem Gott flehen, der nicht retten kann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Tut kund und bringet herbei; ja, beraten mögen sie sich miteinander! Wer hat dieses von alters her hören lassen, vorlängst es verkündet? Nicht ich, Jehova? Und es ist sonst kein Gott außer mir; ein gerechter und rettender Gott ist keiner außer mir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Wendet euch zu mir und werdet gerettet, alle ihr Enden der Erde! Denn ich bin Gott, und keiner sonst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Ich habe bei mir selbst geschworen, aus meinem Munde ist ein Wort in Gerechtigkeit hervorgegangen, und es wird nicht rückgängig werden, daß jedes Knie sich vor mir beugen, jede Zunge mir schwören wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Nur in Jehova, wird man von mir sagen, ist Gerechtigkeit und Stärke. Zu ihm wird man kommen, und es werden beschämt werden alle, die wider ihn entbrannt waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'In Jehova wird gerechtfertigt werden und sich rühmen aller Same Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bel krümmt sich, Nebo sinkt zusammen; ihre Bilder sind dem Saumtiere und dem Lastvieh zuteil geworden; eure Tragbilder sind aufgeladen, eine Last für das ermüdete Vieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Sie sind zusammengesunken, haben sich gekrümmt allzumal und haben die Last nicht retten können; und sie selbst sind in die Gefangenschaft gezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Höret auf mich, Haus Jakob und aller Überrest des Hauses Israel, die ihr von Mutterleibe an aufgeladen, von Mutterschoße an getragen worden seid!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Und bis in euer Greisenalter bin ich derselbe, und bis zu eurem grauen Haare werde ich euch tragen; ich habe es getan, und ich werde heben, und ich werde tragen und erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Wem wollt ihr mich vergleichen und gleichstellen und mich ähnlich machen, daß wir gleich seien? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Sie, die Gold aus dem Beutel schütten und Silber mit der Waage darwägen, dingen einen Schmelzer, daß er einen Gott daraus mache; sie beten an, ja, sie werfen sich nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Sie heben ihn auf, tragen ihn auf der Schulter und lassen ihn nieder auf seine Stelle, und er steht da: von seinem Orte weicht er nicht. Auch schreit man zu ihm, aber er antwortet nicht: niemand rettet er aus seiner Not. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Gedenket dessen und werdet fest, nehmet es zu Herzen, ihr Abtrünnigen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Gedenket des Anfänglichen von der Urzeit her, daß ich Gott bin, und sonst ist keiner, daß ich Gott bin und gar keiner wie ich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'der ich von Anfang an das Ende verkünde, und von alters her, was noch nicht geschehen ist; der ich spreche: Mein Ratschluß soll zustande kommen, und all mein Wohlgefallen werde ich tun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'der ich einen Raubvogel rufe von Osten her, aus fernem Lande den Mann meines Ratschlusses. Ich habe geredet, und werde es auch kommen lassen; ich habe entworfen, und werde es auch ausführen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Höret auf mich, ihr Trotzigen, die ihr fern seid von Gerechtigkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Ich habe meine Gerechtigkeit nahe gebracht, sie ist nicht fern, und mein Heil zögert nicht; und ich gebe in Zion Heil, und Israel meine Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Steige herunter und setze dich in den Staub, Jungfrau, Tochter Babel! Setze dich hin zur Erde, ohne Thron, Tochter der Chaldäer! Denn nicht mehr sollst du Weichliche und Verzärtelte genannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Nimm die Mühle und mahle Mehl; schlage deinen Schleier zurück, ziehe die Schleppe herauf, entblöße die Schenkel, wate durch Ströme;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'aufgedeckt werde deine Blöße, ja, gesehen deine Schande! Ich werde Rache nehmen und Menschen nicht verschonen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Unser Erlöser, Jehova der Heerscharen ist sein Name, der Heilige Israels! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Sitze stumm und geh in die Finsternis, Tochter der Chaldäer! Denn nicht mehr sollst du Herrin der Königreiche genannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Ich war ergrimmt über mein Volk, ich entweihte mein Erbteil, und ich gab sie in deine Hand. Du hast ihnen kein Erbarmen erzeigt, auf den Greis legtest du schwer dein Joch;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'und du sprachst: In Ewigkeit werde ich Herrin sein! so daß du dir dieses nicht zu Herzen nahmst, das Ende davon nicht bedachtest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Und nun höre dieses, du Üppige, die in Sicherheit wohnt, die in ihrem Herzen spricht: Ich bin\'s und gar keine sonst! Ich werde nicht als Witwe sitzen, noch Kinderlosigkeit kennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Dieses beides wird über dich kommen in einem Augenblick, an einem Tage: Kinderlosigkeit und Witwentum; in vollstem Maße werden sie über dich kommen, trotz der Menge deiner Zaubereien, trotz der gewaltigen Zahl deiner Bannsprüche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Und du vertrautest auf deine Bosheit, du sprachst: Niemand sieht mich. Deine Weisheit und dein Wissen das hat dich irregeführt; und du sprachst in deinem Herzen: Ich bin\'s, und gar keine sonst!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Aber es kommt ein Unglück über dich, das du nicht wegzaubern kannst; und ein Verderben wird über dich herfallen, welches du nicht zu sühnen vermagst; und plötzlich wird eine Verwüstung über dich kommen, die du nicht ahnst. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Tritt doch auf mit deinen Bannsprüchen und mit der Menge deiner Zaubereien, worin du dich abgemüht hast von deiner Jugend an! Vielleicht kannst du dir Nutzen schaffen, vielleicht wirst du Schrecken einflößen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Du bist müde geworden durch die Menge deiner Beratungen. Sie mögen doch auftreten und dich retten, die Himmelszerleger, die Sternebeschauer, welche jeden Neumond kundtun, was über dich kommen wird!...');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Siehe, sie sind wie Stoppeln geworden, Feuer hat sie verbrannt! Vor der Gewalt der Flamme konnten sie ihr Leben nicht retten: Es war keine Kohle, um sich zu wärmen, kein Feuer, um davor zu sitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Also sind dir geworden, für welche du dich abgemüht hast; deine Handelsgenossen von deiner Jugend an, sie irren umher, ein jeder nach seiner Richtung hin; niemand hilft dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Höret dieses, Haus Jakob! Die ihr mit dem Namen Israel genannt und aus den Wassern Judas hervorgegangen seid, die ihr schwöret bei dem Namen Jehovas und des Gottes Israels rühmend gedenket, doch nicht in Wahrheit und nicht in Gerechtigkeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'denn nach der heiligen Stadt nennen sie sich, und sie stützen sich auf den Gott Israels, Jehova der Heerscharen ist sein Name:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Ich habe das Frühere vorlängst verkündet, und aus meinem Munde ist es hervorgegangen, und ich habe es hören lassen; plötzlich vollführte ich es, und es traf ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Weil ich wußte, daß du hart bist, und daß dein Nacken eine eiserne Sehne und deine Stirn von Erz ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'so habe ich es vorlängst dir verkündet, ehe es eintraf, habe ich es dich hören lassen; damit du nicht sagen möchtest: Mein Götze hat es getan, und mein geschnitztes und mein gegossenes Bild hat es geboten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Du hast es gehört, betrachte es alles; und ihr, wollt ihr es nicht bekennen? Von nun an lasse ich dich Neues hören und Verborgengehaltenes und was du nicht gewußt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Jetzt ist es geschaffen und nicht vorlängst, und vor diesem Tage hast du nicht davon gehört; damit du nicht sagen möchtest: Siehe, ich habe es gewußt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Du hast es weder gehört noch gewußt, noch war von längsther dein Ohr geöffnet; denn ich wußte, daß du gar treulos bist, und daß man dich von Mutterleibe an einen Übertreter genannt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Um meines Namens willen verziehe ich meinen Zorn, und um meines Ruhmes willen bezwinge ich ihn, dir zu gut, um dich nicht auszurotten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Siehe, ich habe dich geläutert, doch nicht wie Silber; ich habe dich geprüft im Schmelzofen des Elends.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Um meinetwillen, um meinetwillen will ich es tun; denn wie würde mein Name entweiht werden! Und meine Ehre gebe ich keinem anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Höre auf mich, Jakob, und Israel, mein Berufener! Ich bin, der da ist, ich der Erste, ich auch der Letzte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Auch hat meine Hand die Erde gegründet, und meine Rechte die Himmel ausgespannt; ich rufe ihnen zu: allesamt stehen sie da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Versammelt euch, ihr alle, und höret! Wer unter ihnen hat dieses verkündet? Den Jehova liebt, der wird sein Wohlgefallen vollführen an Babel und seinen Arm an den Chaldäern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Ich, ich habe geredet, ja, ich habe ihn gerufen; ich habe ihn kommen lassen, und sein Weg wird gelingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Nahet euch zu mir, höret dieses! Ich habe vom Anfang an nicht im Verborgenen geredet; von der Zeit an, da es ward, bin ich da. Und nun hat der Herr, Jehova, mich gesandt und sein Geist. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'So spricht Jehova, dein Erlöser, der Heilige Israels: Ich bin Jehova, dein Gott, der dich lehrt, zu tun, was dir frommt, der dich leitet auf dem Wege, den du gehen sollst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'O daß du gemerkt hättest auf meine Gebote! Dann würde dein Friede gewesen sein wie ein Strom, und deine Gerechtigkeit wie des Meeres Wogen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'und dein Same würde gewesen sein wie der Sand, und die Sprößlinge deines Leibes wie seine Körner; sein Name würde nicht ausgerottet und nicht vertilgt werden vor meinem Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Ziehet aus Babel, fliehet aus Chaldäa mit Jubelschall; verkündiget, laßt dieses hören, bringet es aus bis an das Ende der Erde! Sprechet: Jehova hat seinen Knecht Jakob erlöst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Und sie dürsteten nicht, als er sie durch die Wüste führte; er ließ ihnen Wasser rieseln aus dem Felsen, er spaltete den Felsen, und Wasser flossen heraus. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Kein Friede den Gesetzlosen! spricht Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Höret auf mich, ihr Inseln, und merket auf, ihr Völkerschaften in der Ferne! Jehova hat mich berufen von Mutterleibe an, hat von meiner Mutter Schoße an meines Namens Erwähnung getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Und er machte meinen Mund wie ein scharfes Schwert, hat mich versteckt in dem Schatten seiner Hand; und er machte mich zu einem geglätteten Pfeile, hat mich verborgen in seinem Köcher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Und er sprach zu mir: Du bist mein Knecht, bist Israel, an dem ich mich verherrlichen werde. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Ich aber sprach: Umsonst habe ich mich abgemüht, vergeblich und für nichts meine Kraft verzehrt; doch mein Recht ist bei Jehova und mein Lohn bei meinem Gott. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Und nun spricht Jehova, der mich von Mutterleibe an zu seinem Knechte gebildet hat, um Jakob zu ihm zurückzubringen, und Israel ist nicht gesammelt worden; aber ich bin geehrt in den Augen Jehovas, und mein Gott ist meine Stärke geworden-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'ja, er spricht: Es ist zu gering, daß du mein Knecht seiest, um die Stämme Jakobs aufzurichten und die Bewahrten von Israel zurückzubringen; ich habe dich auch zum Licht der Nationen gesetzt, um mein Heil zu sein bis an das Ende der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'So spricht Jehova, der Erlöser Israels, sein Heiliger, zu dem von jedermann Verachteten, zu dem Abscheu der Nation, zu dem Knechte der Herrscher: Könige werden es sehen und aufstehen, Fürsten, und sie werden sich niederwerfen, um Jehovas willen, der treu ist, des Heiligen Israels, der dich erwählt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'So spricht Jehova: Zur Zeit der Annehmung habe ich dich erhört, und am Tage des Heils habe ich dir geholfen. Und ich werde dich behüten und dich setzen zum Bunde des Volkes, um das Land aufzurichten, um die verwüsteten Erbteile auszuteilen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'um den Gefangenen zu sagen: Gehet hinaus! zu denen, die in Finsternis sind: Kommet ans Licht! Sie werden an den Wegen weiden, und auf allen kahlen Höhen wird ihre Weide sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'sie werden nicht hungern und nicht dürsten, und weder Kimmung noch Sonne wird sie treffen. Denn ihr Erbarmer wird sie führen und wird sie leiten an Wasserquellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Und alle meine Berge will ich zum Wege machen, und meine Straßen werden erhöht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Siehe, diese werden von ferner kommen, und siehe, diese von Norden und von Westen, und diese aus dem Lande der Sinim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Jubelt, ihr Himmel, und frohlocke, du Erde; und ihr Berge, brechet in Jubel aus! Denn Jehova hat sein Volk getröstet, und seiner Elenden erbarmt er sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Und Zion sprach: Jehova hat mich verlassen, und der Herr hat meiner vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Könnte auch ein Weib ihres Säuglings vergessen, daß sie sich nicht erbarmte über den Sohn ihres Leibes? Sollten selbst diese vergessen, ich werde deiner nicht vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Siehe, in meine beiden Handflächen habe ich dich eingezeichnet; deine Mauern sind beständig vor mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Deine Kinder eilen herbei, deine Zerstörer und deine Verwüster ziehen aus dir hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Erhebe ringsum deine Augen und sieh: sie alle versammeln sich, kommen zu dir. So wahr ich lebe, spricht Jehova, du wirst sie alle wie ein Geschmeide anlegen und dich damit gürten wie eine Braut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Denn deine Trümmer und deine Wüsten und dein zerstörtes Land, ja, nun wirst du zu enge werden für die Bewohner; und deine Verschlinger werden fern sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Die Kinder deiner Kinderlosigkeit werden noch vor deinen Ohren sagen: Der Raum ist mir zu eng; mache mir Platz, daß ich wohnen möge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Und du wirst in deinem Herzen sprechen: Wer hat mir diese geboren, da ich doch der Kinder beraubt und unfruchtbar war, verbannt und umherirrend? Und diese, wer hat sie großgezogen? Siehe, ich war ja allein übriggeblieben; diese, wo waren sie?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'So spricht der Herr, Jehova: Siehe, ich werde meine Hand zu den Nationen hin erheben, und zu den Völkern hin mein Panier aufrichten; und sie werden deine Söhne im Busen bringen, und deine Töchter werden auf der Schulter getragen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Und Könige werden deine Wärter sein, und ihre Fürstinnen deine Ammen; sie werden sich vor dir niederwerfen mit dem Antlitz zur Erde, und den Staub deiner Füße lecken. Und du wirst erkennen, daß ich Jehova bin: die auf mich harren, werden nicht beschämt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Sollte wohl einem Helden die Beute entrissen werden? Oder sollen rechtmäßig Gefangene entrinnen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Ja, so spricht Jehova: Auch die Gefangenen des Helden werden ihm entrissen werden, und die Beute des Gewaltigen wird entrinnen. Und ich werde den befehden, der dich befehdet; und ich werde deine Kinder retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Und ich werde deine Bedrücker speisen mit ihrem eigenen Fleische, und von ihrem Blute sollen sie trunken werden wie von Most. Und alles Fleisch wird erkennen, daß ich, Jehova, dein Heiland bin, und ich, der Mächtige Jakobs, dein Erlöser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'So spricht Jehova: Wo ist der Scheidebrief eurer Mutter, mit dem ich sie entließ? Oder welchem von meinen Gläubigern habe ich euch verkauft? Siehe, um eurer Missetaten willen seid ihr verkauft, und um eurer Übertretungen willen ist eure Mutter entlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Warum bin ich gekommen, und kein Mensch war da? Habe gerufen, und niemand antwortete? Ist meine Hand etwa zu kurz zur Erlösung? Oder ist in mir keine Kraft, um zu erretten? Siehe, durch mein Schelten trockne ich das Meer aus, mache Ströme zu einer Wüste: es stinken ihre Fische, weil kein Wasser da ist, und sie sterben vor Durst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Ich kleide die Himmel in Schwarz und mache Sacktuch zu ihrer Decke. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Der Herr, Jehova, hat mir eine Zunge der Belehrten gegeben, damit ich wisse, den Müden durch ein Wort aufzurichten. Er weckt jeden Morgen, er weckt mir das Ohr, damit ich höre gleich solchen, die belehrt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Der Herr, Jehova, hat mir das Ohr geöffnet, und ich, ich bin nicht widerspenstig gewesen, bin nicht zurückgewichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Ich bot meinen Rücken den Schlagenden und meine Wangen den Raufenden, mein Angesicht verbarg ich nicht vor Schmach und Speichel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Aber der Herr, Jehova, hilft mir; darum bin ich nicht zu Schanden geworden, darum machte ich mein Angesicht wie einen Kieselstein, und wußte, daß ich nicht würde beschämt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Nahe ist der mich rechtfertigt: Wer will mit mir rechten? Laßt uns zusammen hintreten! Wer hat eine Rechtssache wider mich? Er trete her zu mir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Siehe, der Herr, Jehova, wird mir helfen: Wer ist es, der mich für schuldig erklären könnte? Siehe, allesamt werden sie zerfallen wie ein Kleid, die Motte wird sie fressen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Wer unter euch fürchtet Jehova? Wer hört auf die Stimme seines Knechtes? Wer in Finsternis wandelt und welchem kein Licht glänzt, vertraue auf den Namen Jehovas und stütze sich auf seinen Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Siehe, ihr alle, die ihr ein Feuer anzündet, mit Brandpfeilen euch rüstet: Hinweg in die Glut eures Feuers und in die Brandpfeile, die ihr angesteckt habt! Solches geschieht euch von meiner Hand; in Herzeleid sollt ihr daliegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Höret auf mich, die ihr der Gerechtigkeit nachjaget, die ihr Jehova suchet! Blicket hin auf den Felsen, aus dem ihr gehauen, und auf die Höhlung der Grube, aus welcher ihr gegraben seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Blicket hin auf Abraham, euren Vater, und auf Sara, die euch geboren hat; denn ich rief ihn, den einen, und ich segnete ihn und mehrte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Denn Jehova tröstet Zion, tröstet alle ihre Trümmer; und er macht ihre Wüste gleich Eden, und ihre Steppe gleich dem Garten Jehovas. Wonne und Freude werden darin gefunden werden, Danklied und Stimme des Gesanges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Merket auf mich, mein Volk, und meine Nation, horchet auf mich! Denn ein Gesetz wird von mir ausgehen, und mein Recht werde ich aufstellen zum Lichte der Völker.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Nahe ist meine Gerechtigkeit, mein Heil ist ausgezogen, und meine Arme werden die Völker richten. Auf mich werden die Inseln hoffen, und sie werden harren auf meinen Arm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Hebet eure Augen auf gen Himmel und blicket auf die Erde unten! Denn die Himmel werden zergehen wie Rauch, und die Erde wird zerfallen wie ein Kleid, und ihre Bewohner werden dahinsterben. Aber mein Heil wird in Ewigkeit sein, und meine Gerechtigkeit wird nicht zerschmettert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Höret auf mich, die ihr Gerechtigkeit kennet, du Volk, in dessen Herzen mein Gesetz ist: Fürchtet nicht der Menschen Hohn, und erschrecket nicht vor ihren Schmähungen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Denn wie ein Kleid wird sie verzehren die Motte, und wie Wolle sie verzehren die Schabe; aber meine Gerechtigkeit wird in Ewigkeit sein, und mein Heil durch alle Geschlechter hindurch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Wache auf, wache auf; kleide dich in Macht, du Arm Jehovas! Wache auf wie in den Tagen der Vorzeit, in den Geschlechtern vor alters! Bist du es nicht, der Rahab zerhauen, das Seeungeheuer durchbohrt hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Bist du es nicht, der das Meer, die Wasser der großen Flut, trocken gelegt, der die Tiefen des Meeres zu einem Wege gemacht hat, damit die Erlösten hindurchzögen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Und die Befreiten Jehovas werden zurückkehren und nach Zion kommen mit Jubel, und ewige Freude wird über ihrem Haupte sein; sie werden Wonne und Freude erlangen, Kummer und Seufzen werden entfliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Ich, ich bin es, der euch tröstet. Wer bist du, daß du dich vor dem Menschen fürchtest, der hinstirbt, und vor dem Menschenkinde, welches wie Gras dahingegeben wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Und daß du Jehova vergissest, der dich gemacht, der die Himmel ausgespannt und die Erde gegründet hat; und dich beständig, den ganzen Tag, vor dem Grimme des Bedrängers fürchtest, wenn er sich rüstet, um zu verderben? Wo ist denn der Grimm des Bedrängers?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Der in Fesseln Gekrümmte wird alsbald losgelassen werden und wird nicht hinsterben in die Grube, und sein Brot wird ihm nicht mangeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Denn ich bin Jehova, dein Gott, der das Meer erregt, und seine Wogen brausen; Jehova der Heerscharen ist sein Name. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Und ich habe meine Worte in deinen Mund gelegt und dich bedeckt mit dem Schatten meiner Hand, um die Himmel aufzuschlagen und die Erde zu gründen, und zu Zion zu sagen: Du bist mein Volk!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Erwache, erwache; stehe auf, Jerusalem, die du aus der Hand Jehovas den Becher seines Grimmes getrunken! Den Kelchbecher des Taumels hast du getrunken, hast ihn ausgeschlürft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Da war niemand, der sie leitete, von allen Kindern, die sie geboren; und niemand, der sie bei der Hand nahm von allen Kindern, die sie großgezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Zweierlei war es, was dir begegnete, wer sollte dir Beileid bezeigen?: die Verheerung und die Zerschmetterung, und die Hungersnot und das Schwert. Wie könnte ich dich trösten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Deine Kinder sind ohnmächtig hingesunken, sie lagen an allen Straßenecken wie eine Antilope im Netze; sie waren voll des Grimmes Jehovas, des Scheltens deines Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Darum höre doch dieses, du Elende und Trunkene, aber nicht von Wein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'So spricht Jehova, dein Herr, und dein Gott, der die Rechtssache seines Volkes führt: Siehe, ich nehme aus deiner Hand den Taumelbecher, den Kelchbecher meines Grimmes; du wirst ihn hinfort nicht mehr trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Und ich gebe ihn in die Hand deiner Peiniger, die zu deiner Seele sprachen: Bücke dich, daß wir darüber hinschreiten! Und du machtest deinen Rücken der Erde gleich, und gleich einer Straße für die darüber Schreitenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Wache auf, wache auf; kleide dich, Zion, in deine Macht! Kleide dich in deine Prachtgewänder, Jerusalem, du heilige Stadt! Denn hinfort wird kein Unbeschnittener und kein Unreiner in dich eintreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Schüttle den Staub von dir ab, stehe auf, setze dich hin, Jerusalem! Mache dich los von den Fesseln deines Halses, du gefangene Tochter Zion!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Denn so spricht Jehova: Umsonst seid ihr verkauft worden, und nicht um Geld sollt ihr gelöst werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Denn so spricht der Herr, Jehova: Nach Ägypten zog mein Volk im Anfang hinab, um sich daselbst aufzuhalten; und Assyrien hat es ohne Ursache bedrückt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Und nun, was habe ich hier zu schaffen? spricht Jehova. Denn mein Volk ist umsonst hinweggenommen; seine Beherrscher jauchzen, spricht Jehova, und beständig, den ganzen Tag, wird mein Name gelästert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Darum soll mein Volk meinen Namen kennen lernen, darum an jenem Tage erfahren, daß ich es bin, der da spricht: Hier bin ich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Wie lieblich sind auf den Bergen die Füße dessen, der frohe Botschaft bringt, der Frieden verkündigt, der Botschaft des Guten bringt, der Heil verkündigt, der zu Zion spricht: Dein Gott herrscht als König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Stimme deiner Wächter! Sie erheben die Stimme, sie jauchzen insgesamt; denn Auge in Auge sehen sie, wie Jehova Zion wiederbringt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Brechet in Jubel aus, jauchzet insgesamt, ihr Trümmer Jerusalems! Denn Jehova hat sein Volk getröstet, hat Jerusalem erlöst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Jehova hat seinen heiligen Arm entblößt vor den Augen aller Nationen, und alle Enden der Erde sehen die Rettung unseres Gottes. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Weichet, weichet, gehet von dannen hinaus, rühret nichts Unreines an! Gehet hinaus aus ihrer Mitte, reiniget euch, die ihr die Geräte Jehovas traget!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Denn nicht in Hast sollt ihr ausziehen, und nicht in Flucht weggehen; denn Jehova zieht vor euch her, und eure Nachhut ist der Gott Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Siehe, mein Knecht wird einsichtig handeln; er wird erhoben und erhöht werden und sehr hoch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Gleichwie sich viele über dich entsetzt haben, so entstellt war sein Aussehen, mehr als irgend eines Mannes, und seine Gestalt, mehr als der Menschenkinder');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'ebenso wird er viele Nationen in Staunen setzen, über ihn werden Könige ihren Mund verschließen. Denn sie werden sehen, was ihnen nicht erzählt worden war; und was sie nicht gehört hatten, werden sie wahrnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Wer hat unserer Verkündigung geglaubt, und wem ist der Arm Jehovas offenbar geworden? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Und er ist wie ein Reis vor ihm aufgeschossen, und wie ein Wurzelsproß aus dürrem Erdreich. Er hatte keine Gestalt und keine Pracht; und als wir ihn sahen, da hatte er kein Ansehen, daß wir seiner begehrt hätten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Er war verachtet und verlassen von den Menschen, ein Mann der Schmerzen und mit Leiden vertraut, und wie einer, vor dem man das Angesicht verbirgt; er war verachtet, und wir haben ihn für nichts geachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Fürwahr, er hat unsere Leiden getragen, und unsere Schmerzen hat er auf sich geladen. Und wir, wir hielten ihn für bestraft, von Gott geschlagen und niedergebeugt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'doch um unserer Übertretungen willen war er verwundet, um unserer Missetaten willen zerschlagen. Die Strafe zu unserem Frieden lag auf ihm, und durch seine Striemen ist uns Heilung geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Wir alle irrten umher wie Schafe, wir wandten uns ein jeder auf seinen Weg; und Jehova hat ihn treffen lassen unser aller Ungerechtigkeit. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Er wurde mißhandelt, aber er beugte sich und tat seinen Mund nicht auf, gleich dem Lamme, welches zur Schlachtung geführt wird, und wie ein Schaf, das stumm ist vor seinen Scherern; und er tat seinen Mund nicht auf. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Er ist hinweggenommen worden aus der Angst und aus dem Gericht. Und wer wird sein Geschlecht aussprechen? Denn er wurde abgeschnitten aus dem Lande der Lebendigen: Wegen der Übertretung meines Volkes hat ihn Strafe getroffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Und man hat sein Grab bei Gesetzlosen bestimmt; aber bei einem Reichen ist er gewesen in seinem Tode, weil er kein Unrecht begangen hat und kein Trug in seinem Munde gewesen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Doch Jehova gefiel es, ihn zu zerschlagen, er hat ihn leiden lassen. Wenn seine Seele das Schuldopfer gestellt haben wird, so wird er Samen sehen, er wird seine Tage verlängern; und das Wohlgefallen Jehovas wird in seiner Hand gedeihen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Von der Mühsal seiner Seele wird er Frucht sehen und sich sättigen. Durch seine Erkenntnis wird mein gerechter Knecht die Vielen zur Gerechtigkeit weisen, und ihre Missetaten wird er auf sich laden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Darum werde ich ihm die Großen zuteil geben, und mit Gewaltigen wird er die Beute teilen: dafür, daß er seine Seele ausgeschüttet hat in den Tod und den Übertretern beigezählt worden ist; er aber hat die Sünde vieler getragen und für die Übertreter Fürbitte getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Juble, du Unfruchtbare, die nicht geboren, brich in Jubel aus und jauchze, die keine Wehen gehabt hat! Denn der Kinder der Vereinsamten sind mehr als der Kinder der Vermählten, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Mache weit den Raum deines Zeltes, und man spanne aus die Behänge deiner Wohnstätte; wehre nicht! Mache deine Seile lang, und deine Pflöcke stecke fest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Denn du wirst dich ausbreiten zur Rechten und zur Linken; und dein Same wird die Nationen in Besitz nehmen, und wird die verödeten Städte bevölkern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Fürchte dich nicht, denn du wirst nicht beschämt werden, und schäme dich nicht, denn du wirst nicht zu Schanden werden; sondern du wirst der Schmach deiner Jugend vergessen und der Schande deiner Witwenschaft nicht mehr gedenken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Denn der dich gemacht hat, ist dein Mann, Jehova der Heerscharen ist sein Name, und der Heilige Israels ist dein Erlöser: Er wird der Gott der ganzen Erde genannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Denn wie ein verlassenes und im Geiste betrübtes Weib ruft dich Jehova, und wie ein Weib der Jugend, wenn sie verstoßen ist, spricht dein Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Einen kleinen Augenblick habe ich dich verlassen, aber mit großem Erbarmen will ich dich sammeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'im Zorneserguß habe ich einen Augenblick mein Angesicht vor dir verborgen, aber mit ewiger Güte werde ich mich deiner erbarmen, spricht Jehova, dein Erlöser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Denn dieses soll mir sein wie die Wasser Noahs, als ich schwur, daß die Wasser Noahs die Erde nicht mehr überfluten sollten; so habe ich geschworen, daß ich nicht mehr über dich ergrimmen, noch dich schelten werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Denn die Berge mögen weichen und die Hügel wanken, aber meine Güte wird nicht von dir weichen und mein Friedensbund nicht wanken, spricht Jehova, dein Erbarmer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Du Elende, Sturmbewegte, Ungetröstete! Siehe, ich lege deine Steine in Bleiglanz und gründe dich mit Saphiren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'und ich mache deine Zinnen aus Rubinen und deine Tore von Karfunkeln und dein ganzes Gebiet von Edelsteinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Und alle deine Kinder werden von Jehova gelehrt, und der Friede deiner Kinder wird groß sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Durch Gerechtigkeit wirst du befestigt werden. Sei fern von Angst, denn du hast dich nicht zu fürchten, und von Schrecken, denn er wird dir nicht nahen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Siehe, wenn man sich auch rottet, so ist es nicht von mir aus; wer sich wider dich rottet, der wird um deinetwillen fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Siehe, ich habe den Schmied geschaffen, der das Kohlenfeuer anbläst und die Waffe hervorbringt, seinem Handwerk gemäß; und ich habe den Verderber geschaffen, um zu zerstören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Keiner Waffe, die wider dich gebildet wird, soll es gelingen; und jede Zunge, die vor Gericht wider dich aufsteht, wirst du schuldig sprechen. Das ist das Erbteil der Knechte Jehovas und ihre Gerechtigkeit von mir aus, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'He! Ihr Durstigen alle, kommet zu den Wassern; und die ihr kein Geld habt, kommet, kaufet ein und esset! Ja, kommet, kaufet ohne Geld und ohne Kaufpreis Wein und Milch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Warum wäget ihr Geld dar für das, was nicht Brot ist, und euren Erwerb für das, was nicht sättigt? Höret doch auf mich und esset das Gute, und eure Seele labe sich an Fettem!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Neiget euer Ohr und kommet zu mir; höret, und eure Seele wird leben. Und ich will einen ewigen Bund mit euch schließen: die gewissen Gnaden Davids. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Siehe, ich habe ihn zu einem Zeugen für Völkerschaften gesetzt, zum Fürsten und Gebieter von Völkerschaften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Siehe, du wirst eine Nation herbeirufen, die du nicht kanntest; und eine Nation, die dich nicht kannte, wird dir zulaufen, um Jehovas willen, deines Gottes, und wegen des Heiligen Israels; denn er hat dich herrlich gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Suchet Jehova, während er sich finden läßt; rufet ihn an, während er nahe ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Der Gesetzlose verlasse seinen Weg und der Mann des Frevels seine Gedanken; und er kehre um zu Jehova, so wird er sich seiner erbarmen, und zu unserem Gott, denn er ist reich an Vergebung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Denn meine Gedanken sind nicht eure Gedanken, und eure Wege sind nicht meine Wege, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Denn wie der Himmel höher ist als die Erde, so sind meine Wege höher als eure Wege und meine Gedanken als eure Gedanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Denn gleichwie der Regen und der Schnee vom Himmel herabfällt und nicht dahin zurückkehrt, er habe denn die Erde getränkt und befruchtet und sie sprossen gemacht, und dem Säemann Samen gegeben und Brot dem Essenden:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'also wird mein Wort sein, das aus meinem Munde hervorgeht; es wird nicht leer zu mir zurückkehren, sondern es wird ausrichten, was mir gefällt, und durchführen, wozu ich es gesandt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Denn in Freuden werdet ihr ausziehen und in Frieden geleitet werden; die Berge und die Hügel werden vor euch in Jubel ausbrechen, und alle Bäume des Feldes werden in die Hände klatschen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'statt der Dornsträucher werden Zypressen aufschießen, und statt der Brennesseln werden Myrten aufschießen. Und es wird Jehova zum Ruhme, zu einem ewigen Denkzeichen sein, das nicht ausgerottet wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'So spricht Jehova: Wahret das Recht und übet Gerechtigkeit! Denn mein Heil steht im Begriff zu kommen, und meine Gerechtigkeit geoffenbart zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Glückselig der Mensch, der dieses tut, und das Menschenkind, welches hieran festhält: Der den Sabbath hält, daß er ihn nicht entweihe, und seine Hand davor bewahrt, irgend etwas Böses zu tun!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Und der Sohn der Fremde, der sich Jehova angeschlossen hat, spreche nicht und sage: Jehova wird mich sicherlich von seinem Volke ausschließen; und der Verschnittene sage nicht: Siehe, ich bin ein dürrer Baum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Denn so spricht Jehova: Den Verschnittenen, welche meine Sabbathe halten und das erwählen, woran ich Gefallen habe, und festhalten an meinem Bunde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'ihnen will ich in meinem Hause und in meinen Mauern einen Platz geben, und einen Namen, besser als Söhne und Töchter: Einen ewigen Namen werde ich ihnen geben, der nicht ausgerottet werden soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Und die Söhne der Fremde, die sich Jehova angeschlossen haben, um ihm zu dienen und den Namen Jehovas zu lieben, ihm zu Knechten zu sein, einen jeden, der den Sabbath hält, daß er ihn nicht entweihe, und die da festhalten an meinem Bunde:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'die werde ich zu meinem heiligen Berge bringen und sie erfreuen in meinem Bethause; ihre Brandopfer und ihre Schlachtopfer sollen wohlgefällig sein auf meinem Altar. Denn mein Haus wird ein Bethaus genannt werden für alle Völker.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Es spricht der Herr, Jehova, der die Vertriebenen Israels sammelt: Zu ihm, zu seinen Gesammelten, werde ich noch mehr hinzusammeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Kommet her, um zu fressen, alle ihr Tiere des Feldes, alle ihr Tiere im Walde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Seine Wächter sind blind, sind alle ohne Erkenntnis; sie alle sind stumme Hunde, die nicht bellen können; sie träumen, liegen da, lieben den Schlummer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Und die Hunde sind gefräßig, kennen keine Sättigung; und das sind Hirten! Sie haben kein Verständnis; sie alle wenden sich auf ihren eigenen Weg, ein jeder von ihnen allen seinem Vorteil nach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, '\"Kommet her, ich will Wein holen, und laßt uns starkes Getränk saufen; und der morgende Tag soll wie dieser sein, herrlich über alle Maßen!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Der Gerechte kommt um, und niemand nimmt es zu Herzen, und die Frommen werden hinweggerafft, ohne daß jemand es beachtet, daß der Gerechte vor dem Unglück hinweggerafft wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Er geht ein zum Frieden; sie ruhen auf ihren Lagerstätten, ein jeder, der in Geradheit gewandelt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Und ihr, nahet hierher, Kinder der Zauberin, Same des Ehebrechers und der Hure!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Über wen machet ihr euch lustig, über wen sperret ihr das Maul auf und strecket die Zunge heraus? Seid ihr nicht Kinder des Abfalls, ein Same der Lüge,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'die ihr für die Götzen entbranntet unter jedem grünen Baume, die ihr Kinder in den Tälern schlachtetet unter den Klüften der Felsen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'An den glatten Steinen des Talbaches war dein Teil; sie, sie waren dein Los; auch gossest du ihnen Trankopfer aus, opfertest ihnen Speisopfer. Sollte ich mich darüber trösten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Auf einem hohen und erhabenen Berge schlugest du dein Lager auf; auch stiegest du dort hinauf, um Schlachtopfer zu opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Und hinter die Tür und den Pfosten setztest du dein Gedächtnis. Denn von mir abgewendet decktest du auf und bestiegest, machtest breit dein Lager, und du bedingtest dir Lohn von ihnen aus; du liebtest ihr Beilager, schautest ihre Blöße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Und du zogest mit Öl zu dem König und machtest viel deiner wohlriechenden Salben; und du sandtest deine Boten in die Ferne und erniedrigtest dich bis zum Scheol.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Durch die Weite deines Weges bist du müde geworden, doch du sprachst nicht: Es ist umsonst! Du gewannst neue Kraft, darum bist du nicht erschlafft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Und vor wem hast du dich gescheut und gefürchtet, daß du gelogen hast, und meiner nicht gedachtest, es nicht zu Herzen nahmst? Habe ich nicht geschwiegen, und zwar seit langer Zeit? Und mich fürchtest du nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Ich, ich werde deine Gerechtigkeit kundtun; und deine Machwerke, sie werden dir nichts nützen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Wenn du schreist, mögen dich deine Götzenhaufen erretten! Aber ein Wind wird sie allesamt entführen, ein Hauch sie hinwegnehmen. Wer aber zu mir seine Zuflucht nimmt, wird das Land erben und meinen heiligen Berg besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Und man wird sagen: Machet Bahn, machet Bahn; bereitet einen Weg, hebet aus dem Wege meines Volkes jeden Anstoß hinweg!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Denn so spricht der Hohe und Erhabene, der in Ewigkeit wohnt, und dessen Name der Heilige ist: Ich wohne in der Höhe und im Heiligtum, und bei dem, der zerschlagenen und gebeugten Geistes ist, um zu beleben den Geist der Gebeugten und zu beleben das Herz der Zerschlagenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Denn ich will nicht ewiglich rechten und nicht auf immerdar ergrimmt sein; denn der Geist würde vor mir verschmachten, und die Seelen, die ich ja gemacht habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Wegen der Missetat seiner Habsucht ergrimmte ich und schlug es, indem ich mich verbarg und ergrimmt war; und es wandelte abtrünnig auf dem Wege seines Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Seine Wege habe ich gesehen und werde es heilen; und ich werde es leiten, und Tröstungen erstatten ihm und seinen Trauernden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Die Frucht der Lippen schaffend, spricht Jehova: Friede, Friede den Fernen und den Nahen, und ich will es heilen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Aber die Gesetzlosen sind wie das aufgewühlte Meer; denn es kann nicht ruhig sein, und seine Wasser wühlen Schlamm und Kot auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Kein Friede den Gesetzlosen! spricht mein Gott. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Rufe aus voller Kehle, halte nicht zurück! Erhebe deine Stimme gleich einer Posaune, und tue meinem Volke seine Übertretung kund, und dem Hause Jakob seine Sünden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Und doch fragen sie nach mir Tag für Tag und begehren meine Wege zu kennen; gleich einer Nation, welche Gerechtigkeit übt und das Recht ihres Gottes nicht verlassen hat, fordern sie von mir Gerichte der Gerechtigkeit, begehren das Herannahen Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, '\"Warum haben wir gefastet, und du hast es nicht gesehen, unsere Seelen kasteit, und du hast es nicht gemerkt?\" Siehe, am Tage eures Fastens geht ihr euren Geschäften nach und dränget alle eure Arbeiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Siehe, zu Hader und Zank fastet ihr, und um zu schlagen mit boshafter Faust. Heutzutage fastet ihr nicht, um eure Stimme hören zu lassen in der Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Ist dergleichen ein Fasten, an dem ich Gefallen habe, ein Tag, an welchem der Mensch seine Seele kasteit? Seinen Kopf zu beugen wie ein Schilf, und Sacktuch und Asche unter sich zu betten, nennst du das ein Fasten und einen dem Jehova wohlgefälligen Tag?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Ist nicht dieses ein Fasten, an dem ich Gefallen habe: daß man löse die Schlingen der Bosheit, daß man losmache die Knoten des Joches und gewalttätig Behandelte als Freie entlasse, und daß ihr jedes Joch zersprenget?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Besteht es nicht darin, dein Brot dem Hungrigen zu brechen, und daß du verfolgte Elende ins Haus führst? Wenn du einen Nackten siehst, daß du ihn bedeckst und deinem Fleische dich nicht entziehst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Dann wird dein Licht hervorbrechen wie die Morgenröte, und deine Heilung wird eilends sprossen; und deine Gerechtigkeit wird vor dir herziehen, die Herrlichkeit Jehovas wird deine Nachhut sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Dann wirst du rufen, und Jehova wird antworten; du wirst um Hilfe schreien, und er wird sagen: Hier bin ich! Wenn du das Joch, das Fingerausstrecken und unheilvolle Reden aus deiner Mitte hinwegtust,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'und deine Speise dem Hungrigen darreichst und die niedergedrückte Seele sättigst: so wird dein Licht aufgehen in der Finsternis, und dein Dunkel wird sein wie der Mittag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Und beständig wird Jehova dich leiten, und er wird deine Seele sättigen in Zeiten der Dürre und deine Gebeine rüstig machen. Und du wirst sein wie ein bewässerter Garten und wie ein Wasserquell, dessen Gewässer nicht trügen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Und die aus dir kommen, werden die uralten Trümmer aufbauen; die Grundmauern vergangener Geschlechter wirst du aufrichten; und du wirst genannt werden: Vermaurer der Lücken, Wiederhersteller bewohnbarer Straßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Wenn du deinen Fuß vom Sabbath zurückhältst, daß du dein Geschäft nicht tust an meinem heiligen Tage, und den Sabbath ein Ergötzen und den heiligen Tag Jehovas ehrwürdig nennst; und wenn du ihn ehrst, so daß du nicht deine Wege verfolgst, dein Geschäft treibst und eitle Worte redest:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'dann wirst du dich an Jehova ergötzen, und ich werde dich einherfahren lassen auf den Höhen der Erde, und werde dich speisen mit dem Erbteil Jakobs, deines Vaters; denn der Mund Jehovas hat geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Siehe, die Hand Jehovas ist nicht zu kurz, um zu retten, und sein Ohr nicht zu schwer, um zu hören;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'sondern eure Missetaten haben eine Scheidung gemacht zwischen euch und eurem Gott, und eure Sünden haben sein Angesicht vor euch verhüllt, daß er nicht hört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Denn eure Hände sind mit Blut befleckt und eure Finger mit Ungerechtigkeit; eure Lippen reden Lüge, eure Zunge spricht Unrecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Niemand ruft Gerechtigkeit aus, und niemand rechtet in Treue; man vertraut auf Nichtigkeit und redet Falschheit; man ist schwanger mit Mühsal und gebiert Unheil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Basiliskeneier brüten sie aus, und sie weben Spinnengewebe: Wer von ihren Eiern ißt, muß sterben, und wird eines zertreten, so fährt eine Otter heraus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'ihr Gewebe taugt nicht zur Bekleidung, und mit ihrem Gewirke kann man sich nicht bedecken. Ihre Werke sind Werke des Unheils, und Gewalttat ist in ihren Händen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Ihre Füße laufen zum Bösen und eilen, unschuldiges Blut zu vergießen; ihre Gedanken sind Gedanken des Unheils, Verwüstung und Zertrümmerung ist auf ihren Bahnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Den Weg des Friedens kennen sie nicht, und kein Recht ist in ihren Geleisen; ihre Pfade machen sie krumm: Wer irgend sie betritt, kennt keinen Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Darum ist das Recht fern von uns, und die Gerechtigkeit erreicht uns nicht. Wir harren auf Licht, und siehe, Finsternis; auf Helle, aber in dichtem Dunkel wandeln wir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Wie Blinde tappen wir an der Wand herum, und wir tappen herum wie solche, die keine Augen haben; wir straucheln am Mittag wie in der Dämmerung. Wir sind unter Gesunden den Toten gleich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Wir brummen alle wie die Bären, und wir girren wie die Tauben. Wir harren auf Recht, und da ist keines; auf Rettung, aber sie ist fern von uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Denn viele sind unserer Übertretungen vor dir, und unsere Sünden zeugen wider uns; denn unserer Übertretungen sind wir uns bewußt, und unsere Missetaten, die kennen wir:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Abfallen von Jehova und ihn verleugnen und zurückweichen von unserem Gott, reden von Bedrückung und Abfall, Lügenworte in sich aufnehmen und sie aus dem Herzen sprechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Und das Recht ist zurückgedrängt, und die Gerechtigkeit steht von ferne; denn die Wahrheit ist gestrauchelt auf dem Markte, und die Geradheit findet keinen Einlaß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Und die Wahrheit wird vermißt; und wer das Böse meidet, setzt sich der Beraubung aus. Und Jehova sah es, und es war böse in seinen Augen, daß kein Recht vorhanden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Und er sah, daß kein Mann da war; und er staunte, daß kein Vermittler vorhanden. Da half ihm sein Arm, und seine Gerechtigkeit, sie unterstützte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Und er zog Gerechtigkeit an wie einen Panzer und setzte den Helm des Heils auf sein Haupt, und er zog Rachegewänder an als Kleidung und hüllte sich in Eifer wie in einen Mantel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Nach den Taten, danach wird er vergelten: Grimm seinen Widersachern, Vergeltung seinen Feinden; den Inseln wird er Vergeltung erstatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Und sie werden den Namen Jehovas fürchten vom Niedergang an, und vom Sonnenaufgang seine Herrlichkeit. Wenn der Bedränger kommen wird wie ein Strom, so wird der Hauch Jehovas ihn in die Flucht schlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Und ein Erlöser wird kommen für Zion und für die, welche in Jakob von der Übertretung umkehren, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Und ich, dies ist mein Bund mit ihnen, spricht Jehova: Mein Geist, der auf dir ist, und meine Worte, die ich in deinen Mund gelegt habe, werden nicht aus deinem Munde weichen, noch aus dem Munde deiner Nachkommen, noch aus dem Munde der Nachkommen deiner Nachkommen, spricht Jehova, von nun an bis in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Stehe auf, leuchte! Denn dein Licht ist gekommen, und die Herrlichkeit Jehovas ist über dir aufgegangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Denn siehe, Finsternis bedeckt die Erde und Dunkel die Völkerschaften; aber über dir strahlt Jehova auf, und seine Herrlichkeit erscheint über dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Und Nationen wandeln zu deinem Lichte hin, und Könige zu dem Glanze deines Aufgangs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Erhebe ringsum deine Augen und sieh! Sie alle versammeln sich, kommen zu dir: Deine Söhne kommen von ferne, und deine Töchter werden auf den Armen herbeigetragen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Dann wirst du es sehen und vor Freude strahlen, und dein Herz wird beben und weit werden; denn des Meeres Fülle wird sich zu dir wenden, der Reichtum der Nationen zu dir kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Eine Menge Kamele wird dich bedecken, junge Kamele von Midian und Epha. Allesamt werden sie aus Scheba kommen, Gold und Weihrauch bringen, und sie werden das Lob Jehovas fröhlich verkündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Alle Herden Kedars werden sich zu dir versammeln, die Widder Nebajoths werden dir zu Diensten stehen: Wohlgefällig werden sie auf meinen Altar kommen; und das Haus meiner Pracht werde ich prächtig machen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Wer sind diese, die wie eine Wolke geflogen kommen und gleich Tauben zu ihren Schlägen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Denn auf mich hoffen die Inseln, und die Tarsisschiffe ziehen voran, um deine Kinder aus der Ferne zu bringen, und ihr Silber und ihr Gold mit ihnen, zu dem Namen Jehovas, deines Gottes, und zu dem Heiligen Israels, weil er dich herrlich gemacht hat. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Und die Söhne der Fremde werden deine Mauern bauen, und ihre Könige dich bedienen; denn in meinem Grimm habe ich dich geschlagen, aber in meiner Huld habe ich mich deiner erbarmt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Und deine Tore werden beständig offen stehen; Tag und Nacht werden sie nicht geschlossen werden, um zu dir zu bringen den Reichtum der Nationen und ihre hinweggeführten Könige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Denn die Nation und das Königreich, welche dir nicht dienen wollen, werden untergehen, und diese Nationen werden gewißlich vertilgt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Die Herrlichkeit des Libanon wird zu dir kommen, Zypresse, Platane und Scherbinzeder miteinander, um die Stätte meines Heiligtums zu schmücken; und ich werde herrlich machen die Stätte meiner Füße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Und gebeugt werden zu dir kommen die Kinder deiner Bedrücker, und alle deine Schmäher werden niederfallen zu den Sohlen deiner Füße; und sie werden dich nennen: Stadt Jehovas, Zion des Heiligen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Statt daß du verlassen warst und gehaßt, und niemand hindurchzog, will ich dich zum ewigen Stolz machen, zur Wonne von Geschlecht zu Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Und du wirst saugen die Milch der Nationen, und saugen an der Brust der Könige; und du wirst erkennen, daß ich, Jehova, dein Heiland bin, und ich, der Mächtige Jakobs, dein Erlöser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Statt des Erzes werde ich Gold bringen, und statt des Eisens Silber bringen, und statt des Holzes Erz, und statt der Steine Eisen. Und ich werde den Frieden setzen zu deinen Aufsehern, und die Gerechtigkeit zu deinen Vögten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Nicht wird man ferner von Gewalttat hören in deinem Lande, von Verheerung und Zertrümmerung in deinen Grenzen; sondern deine Mauern wirst du Heil nennen, und deine Tore Ruhm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Nicht wird ferner die Sonne dir zum Licht sein bei Tage, noch zur Helle der Mond dir scheinen; sondern Jehova wird dir zum ewigen Licht sein, und dein Gott zu deinem Schmuck.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Nicht wird ferner deine Sonne untergehen, noch dein Mond sich zurückziehen; denn Jehova wird dir zum ewigen Licht sein. Und die Tage deines Trauerns werden ein Ende haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Und dein Volk, sie alle werden Gerechte sein, werden das Land besitzen auf ewig, sie, ein Sproß meiner Pflanzungen, ein Werk meiner Hände, zu meiner Verherrlichung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Der Kleinste wird zu einem Tausend werden, und der Geringste zu einer gewaltigen Nation. Ich, Jehova, werde es zu seiner Zeit eilends ausführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Der Geist des Herrn, Jehovas, ist auf mir, weil Jehova mich gesalbt hat, um den Sanftmütigen frohe Botschaft zu bringen, weil er mich gesandt hat, um zu verbinden, die zerbrochenen Herzens sind, Freiheit auszurufen den Gefangenen, und Öffnung des Kerkers den Gebundenen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'um auszurufen das Jahr der Annehmung Jehovas und den Tag der Rache unseres Gottes und zu trösten alle Trauernden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'um den Trauernden Zions aufzusetzen und ihnen zu geben Kopfschmuck statt Asche, Freudenöl statt Trauer, ein Ruhmesgewand statt eines verzagten Geistes; damit sie genannt werden Terebinthen der Gerechtigkeit, eine Pflanzung Jehovas, zu seiner Verherrlichung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Und sie werden die uralten Trümmer aufbauen, die Verwüstungen der Vorzeit aufrichten; und sie werden die verödeten Städte erneuern, was wüst lag von Geschlecht zu Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Und Fremdlinge werden dastehen und eure Herden weiden, und Söhne der Fremde werden eure Ackersleute und eure Weingärtner sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Ihr aber, ihr werdet Priester Jehovas genannt werden; Diener unseres Gottes wird man euch heißen. Ihr werdet der Nationen Reichtümer genießen und in ihre Herrlichkeit eintreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Anstatt eurer Schmach werdet ihr das Doppelte haben, und anstatt der Schande werden sie jubeln über ihr Teil; darum werden sie in ihrem Lande das Doppelte besitzen, werden ewige Freude haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Denn ich, Jehova, liebe das Recht, ich hasse den frevelhaften Raub; und ich werde ihnen ihre Belohnung getreulich geben und einen ewigen Bund mit ihnen schließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Und ihr Same wird bekannt werden unter den Nationen, und ihre Sprößlinge inmitten der Völker: Alle, die sie sehen, werden sie erkennen, daß sie ein Same sind, den Jehova gesegnet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Hoch erfreue ich mich in Jehova; meine Seele soll frohlocken in meinem Gott! Denn er hat mich bekleidet mit Kleidern des Heils, den Mantel der Gerechtigkeit mir umgetan, wie ein Bräutigam den Kopfschmuck nach Priesterart anlegt, und wie eine Braut sich schmückt mit ihrem Geschmeide.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Denn wie die Erde ihr Gesproß hervorbringt, und wie ein Garten sein Gesätes aufsprossen läßt, also wird der Herr, Jehova, Gerechtigkeit und Ruhm aufsprossen lassen vor allen Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Um Zions willen will ich nicht schweigen, und um Jerusalems willen will ich nicht still sein, bis ihre Gerechtigkeit hervorbricht wie Lichtglanz und ihr Heil wie eine lodernde Fackel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Und die Nationen werden deine Gerechtigkeit sehen, und alle Könige deine Herrlichkeit; und du wirst mit einem neuen Namen genannt werden, welchen der Mund Jehovas bestimmen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Und du wirst eine prachtvolle Krone sein in der Hand Jehovas und ein königliches Diadem in der Hand deines Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Nicht mehr wird man dich \"Verlassene\" heißen, und dein Land nicht mehr \"Wüste\" heißen; sondern man wird dich nennen \"meine Lust an ihr\", und dein Land \"Vermählte\"; denn Jehova wird Lust an dir haben, und dein Land wird vermählt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Denn wie der Jüngling sich mit der Jungfrau vermählt, so werden deine Kinder sich mit dir vermählen; und wie der Bräutigam sich an der Braut erfreut, so wird dein Gott sich an dir erfreuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Auf deine Mauern, Jerusalem, habe ich Wächter bestellt; den ganzen Tag und die ganze Nacht werden sie keinen Augenblick schweigen. Ihr, die ihr Jehova erinnert, gönnet euch keine Ruhe');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'und laßt ihm keine Ruhe, bis er Jerusalem befestigt und bis er es zum Ruhme macht auf Erden! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Jehova hat geschworen bei seiner Rechten und bei seinem starken Arm: Wenn ich fortan deinen Feinden dein Korn zur Speise gebe, und wenn Söhne der Fremde deinen Most trinken werden, um welchen du dich abgemüht hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Sondern die es einsammeln, sollen es essen und Jehova preisen; und die ihn einbringen, sollen ihn trinken in den Vorhöfen meines Heiligtums.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Ziehet, ziehet durch die Tore, bereitet den Weg des Volkes; bahnet, bahnet die Straße, reiniget sie von Steinen; erhebet ein Panier über die Völker!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Siehe, Jehova hat eine Kunde erschallen lassen nach dem Ende der Erde hin: Saget der Tochter Zion: Siehe, dein Heil kommt; siehe sein Lohn ist bei ihm, und seine Vergeltung geht vor ihm her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Und man wird sie nennen: das heilige Volk, die Erlösten Jehovas; und dich wird man nennen: die Gesuchte, Stadt, die nicht mehr verlassen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Wer ist dieser, der von Edom kommt, von Bozra in hochroten Kleidern, dieser, prächtig in seinem Gewande, der einherzieht in der Größe seiner Kraft? Ich bin\'s, der in Gerechtigkeit redet, der mächtig ist zu retten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Warum ist Rot an deinem Gewande, und sind deine Kleider wie die eines Keltertreters? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Ich habe die Kelter allein getreten, und von den Völkern war niemand bei mir; und ich zertrat sie in meinem Zorn und zerstampfte sie in meinem Grimm; und ihr Saft spritzte auf meine Kleider, und ich besudelte mein ganzes Gewand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Denn der Tag der Rache war in meinem Herzen, und das Jahr meiner Erlösung war gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Und ich blickte umher, und da war kein Helfer; und ich staunte, und da war kein Unterstützer. Da hat mein Arm mir geholfen, und mein Grimm, er hat mich unterstützt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Und ich trat die Völker nieder in meinem Zorn und machte sie trunken in meinem Grimm, und ich ließ ihren Saft zur Erde rinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Ich will der Gütigkeiten Jehovas gedenken, der Ruhmestaten Jehovas, nach allem, was Jehova uns erwiesen hat, und der großen Güte gegen das Haus Israel, welche er ihnen erwiesen nach seinen Erbarmungen und nach der Menge seiner Gütigkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Und er sprach: Sie sind ja mein Volk, Kinder, die nicht trügen werden; und er ward ihnen zum Heiland.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'In all ihrer Bedrängnis war er bedrängt, und der Engel seines Angesichts hat sie gerettet. In seiner Liebe und in seiner Erbarmung hat er sie erlöst; und er hob sie empor und trug sie alle Tage vor alters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Sie aber sind widerspenstig gewesen und haben seinen heiligen Geist betrübt; da wandelte er sich ihnen in einen Feind: Er selbst stritt wider sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Da gedachte sein Volk der Tage vor alters, der Tage Moses: \"Wo ist der, welcher sie aus dem Meere heraufführte samt den Hirten seiner Herde? Wo ist der, welcher seinen heiligen Geist in ihre Mitte gab;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'der seinen herrlichen Arm zur Rechten Moses einherziehen ließ; der die Wasser vor ihnen her spaltete, um sich einen ewigen Namen zu machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'der sie durch die Tiefen ziehen ließ, gleich dem Rosse in der Steppe, ohne daß sie strauchelten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Gleich dem Vieh, welches in das Tal hinabsteigt, brachte der Geist Jehovas sie zur Ruhe. Also hast du dein Volk geleitet, um dir einen herrlichen Namen zu machen.\" -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, '\"Blicke vom Himmel herab und sieh, von der Wohnstätte deiner Heiligkeit und deiner Majestät! Wo sind dein Eifer und deine Machttaten? Die Regung deines Innern und deine Erbarmungen halten sich gegen mich zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Denn du bist unser Vater; denn Abraham weiß nicht von uns, und Israel kennt uns nicht; du, Jehova, bist unser Vater; unser Erlöser von alters her ist dein Name.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Warum, Jehova, läßt du uns von deinen Wegen abirren, verhärtest unser Herz, daß wir dich nicht fürchten? Kehre zurück um deiner Knechte willen, der Stämme deines Erbteils!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Auf eine kleine Zeit hat dein heiliges Volk es besessen: Unsere Widersacher haben dein Heiligtum zertreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Wir sind zu solchen geworden, über die du von alters her nicht geherrscht hast, die nicht genannt gewesen sind nach deinem Namen.\" -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, '\"O daß du die Himmel zerrissest, herniederführest, daß vor deinem Angesicht die Berge erbebten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'wie Feuer Reisig entzündet, Feuer die Wasser wallen macht, um deinen Namen kundzutun deinen Widersachern: Damit die Nationen vor deinem Angesicht erzittern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'indem du furchtbare Taten vollziehst, die wir nicht erwarteten; o daß du herniederführest, daß vor deinem Angesicht die Berge erbebten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Denn von alters her hat man nicht gehört noch vernommen, hat kein Auge einen Gott gesehen, außer dir, der sich wirksam erwiese für den auf ihn Harrenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Du kommst dem entgegen, der Freude daran hat, Gerechtigkeit zu üben, denen, die auf deinen Wegen deiner gedenken. Siehe, du, du ergrimmtest, und wir haben gesündigt; darin sind wir schon lang, so laß uns gerettet werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Und wir allesamt sind dem Unreinen gleich geworden, und alle unsere Gerechtigkeiten gleich einem unflätigen Kleide; und wir verwelkten allesamt wie ein Blatt, und unsere Missetaten rafften uns dahin wie der Wind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Und da war niemand, der deinen Namen anrief, der sich aufmachte, dich zu ergreifen; denn du hast dein Angesicht vor uns verborgen und uns vergehen lassen durch unsere Missetaten.\" -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, '\"Und nun, Jehova, du bist unser Vater; wir sind der Ton, und du bist unser Bildner, und wir alle sind das Werk deiner Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Jehova, zürne nicht allzusehr, und gedenke nicht ewiglich der Missetat. Sieh, schau doch her, dein Volk sind wir alle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Deine heiligen Städte sind eine Wüste geworden, Zion ist eine Wüste geworden, Jerusalem eine Einöde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Unser heiliges und herrliches Haus, worin unsere Väter dich lobten, ist mit Feuer verbrannt, und alle unsere Kostbarkeiten sind verheert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Willst du, Jehova, bei solchem an dich halten? Willst du schweigen und uns ganz und gar niederbeugen?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Ich bin gesucht worden von denen, die nicht nach mir fragten; ich bin gefunden worden von denen, die mich nicht suchten. Ich sprach: Hier bin, ich, hier bin ich! Zu einer Nation, die nicht mit meinem Namen genannt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Ich habe den ganzen Tag meine Hände ausgebreitet zu einem widerspenstigen Volke, welches seinen eigenen Gedanken nach auf dem Wege wandelt, der nicht gut ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Das Volk, das mich beständig ins Angesicht reizt, in den Gärten opfert und auf Ziegelsteinen räuchert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'welches in den Gräbern sitzt und in verborgenen Orten übernachtet; welches Schweinefleisch ißt und Greuelbrühe in seinen Gefäßen hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'das da spricht: Bleibe für dich und nahe mir nicht, denn ich bin dir heilig: Diese sind ein Rauch in meiner Nase, ein Feuer, das den ganzen Tag brennt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Siehe, das ist vor mir aufgeschrieben. Ich werde nicht schweigen, ich habe denn vergolten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'und in ihren Busen werde ich vergelten eure Missetaten und die Missetaten eurer Väter miteinander, spricht Jehova, die auf den Bergen geräuchert und mich auf den Hügeln verhöhnt haben; und ich werde zuvor ihren Lohn in ihren Busen messen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'So spricht Jehova: Wie wenn sich Most in der Traube findet, und man spricht: Verdirb sie nicht, denn ein Segen ist in ihr; so werde ich tun um meiner Knechte willen, daß ich nicht das Ganze verderbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Und ich werde aus Jakob einen Samen hervorgehen lassen, und aus Juda einen Besitzer meiner Berge; und meine Auserwählten sollen es besitzen, und meine Knechte sollen daselbst wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Und Saron wird zu einer Trift der Schafe, und das Tal Achor zu einem Lagerplatz der Rinder werden, für mein Volk, das mich gesucht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Ihr aber, die ihr Jehova verlasset, die ihr meines heiligen Berges vergesset, die ihr dem Gad einen Tisch zurichtet und der Meni Mischtrank einschenket:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Ich habe euch dem Schwerte bestimmt, und ihr alle werdet zur Schlachtung niedersinken; weil ich gerufen, und ihr nicht geantwortet habt, geredet, und ihr nicht gehört habt, sondern getan, was böse ist in meinen Augen, und das erwählet, woran ich kein Gefallen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Darum spricht der Herr, Jehova, also: Siehe, meine Knechte werden essen, ihr aber werdet hungern; siehe, meine Knechte werden trinken, ihr aber werdet dürsten. Siehe, meine Knechte werden sich freuen, ihr aber werdet beschämt sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'siehe, meine Knechte werden jubeln vor Freude des Herzens, ihr aber werdet schreien vor Herzeleid und heulen vor Kummer des Geistes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Und ihr werdet euren Namen meinen Auserwählten zum Fluchwort hinterlassen; und der Herr, Jehova, wird dich töten. Seine Knechte aber wird er mit einem anderen Namen nennen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'So daß, wer sich im Lande segnet, sich bei dem Gott der Treue segnen wird, und wer im Lande schwört, bei dem Gott der Treue schwören wird; denn die früheren Drangsale werden vergessen und vor meinen Augen verborgen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Denn siehe, ich schaffe einen neuen Himmel und eine neue Erde; und der früheren wird man nicht mehr gedenken, und sie werden nicht mehr in den Sinn kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Sondern freuet euch und frohlocket für und für über das, was ich schaffe. Denn siehe, ich wandle Jerusalem in Frohlocken um und sein Volk in Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Und ich werde über Jerusalem frohlocken und über mein Volk mich freuen; und die Stimme des Weinens und die Stimme des Wehgeschreis wird nicht mehr darin gehört werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Und dort wird kein Säugling von einigen Tagen und kein Greis mehr sein, der seine Tage nicht erfüllte; denn der Jüngling wird als Hundertjähriger sterben, und der Sünder als Hundertjähriger verflucht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Und sie werden Häuser bauen und bewohnen, und Weinberge pflanzen und ihre Frucht essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Sie werden nicht bauen und ein anderer es bewohnen, sie werden nicht pflanzen und ein anderer essen; denn gleich den Tagen der Bäume sollen die Tage meines Volkes sein, und meine Auserwählten werden das Werk ihrer Hände verbrauchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Nicht vergeblich werden sie sich mühen, und nicht zum jähen Untergang werden sie zeugen; denn sie sind der Same der Gesegneten Jehovas, und ihre Sprößlinge werden bei ihnen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Und es wird geschehen: Ehe sie rufen, werde ich antworten; während sie noch reden, werde ich hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Wolf und Lamm werden beisammen weiden; und der Löwe wird Stroh fressen wie das Rind; und die Schlange: Staub wird ihre Speise sein. Man wird nicht übeltun noch verderbt handeln auf meinem ganzen heiligen Gebirge, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'So spricht Jehova: Der Himmel ist mein Thron, und die Erde der Schemel meiner Füße. Welches ist das Haus, das ihr mir bauen könntet, und welches der Ort zu meiner Ruhestätte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Hat doch meine Hand dieses alles gemacht, und alles dieses ist geworden, spricht Jehova. Aber auf diesen will ich blicken: auf den Elenden und den, der zerschlagenen Geistes ist, und der da zittert vor meinem Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Wer ein Rind schlachtet, erschlägt einen Menschen; wer ein Schaf opfert, bricht einem Hunde das Genick; wer Speisopfer opfert: es ist Schweinsblut; wer Weihrauch als Gedächtnisopfer darbringt, preist einen Götzen. So wie diese ihre Wege erwählt haben und ihre Seele Lust hat an ihren Scheusalen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'ebenso werde ich ihre Mißgeschicke erwählen und ihre Schrecknisse über sie bringen; weil ich gerufen, und niemand geantwortet hat, geredet, und sie nicht gehört haben, sondern getan, was böse ist in meinen Augen, und das erwählten, woran ich kein Gefallen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Höret das Wort Jehovas, die ihr zittert vor seinem Worte! Es sagen eure Brüder, die euch hassen, die euch verstoßen um meines Namens willen: Jehova erzeige sich herrlich, daß wir eure Freude sehen mögen! Aber sie werden beschämt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Stimme eines Getöses von der Stadt her! Stimme aus dem Tempel! Stimme Jehovas, der Vergeltung erstattet seinen Feinden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Ehe sie Wehen hatte, hat sie geboren; ehe Schmerzen sie ankamen, wurde sie von einem Knaben entbunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Wer hat solches gehört, wer hat dergleichen gesehen? Kann ein Land an einem Tage zur Welt gebracht, oder eine Nation mit einem Male geboren werden? Denn Zion hat Wehen bekommen und zugleich ihre Kinder geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Sollte ich zum Durchbruch bringen und nicht gebären lassen? spricht Jehova; oder sollte ich, der gebären läßt, verschließen? spricht dein Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Freuet euch mit Jerusalem und frohlocket über sie, alle, die ihr sie liebet; seid hocherfreut mit ihr, alle, die ihr über sie trauert!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Auf daß ihr sauget und euch sättiget an der Brust ihrer Tröstungen, auf daß ihr schlürfet und euch ergötzet an der Fülle ihrer Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Denn so spricht Jehova: Siehe, ich wende ihr Frieden zu wie einen Strom, und die Herrlichkeit der Nationen wie einen überflutenden Bach, und ihr werdet saugen; auf den Armen werdet ihr getragen und auf den Knieen geliebkost werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Wie einen, den seine Mutter tröstet, also werde ich euch trösten; und in Jerusalem sollt ihr getröstet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Und ihr werdet es sehen, und euer Herz wird sich freuen; und eure Gebeine werden sprossen wie das junge Gras. Und die Hand Jehovas wird sich kundgeben an seinen Knechten, und gegen seine Feinde wird er ergrimmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Denn siehe, Jehova wird kommen im Feuer, und seine Wagen sind wie der Sturmwind, um seinen Zorn zu vergelten in Glut und sein Schelten in Feuerflammen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Denn durch Feuer und durch sein Schwert wird Jehova Gericht üben an allem Fleische, und der Erschlagenen Jehovas werden viele sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Die sich weihen und sich reinigen für die Gärten, hinter einem her in der Mitte; die Schweinefleisch essen und Greuel und Mäuse: allzumal werden sie ein Ende nehmen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Und ich, ihre Werke und ihre Gedanken sind vor mir. Es kommt die Zeit, alle Nationen und Sprachen zu versammeln; und sie werden kommen und meine Herrlichkeit sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Und ich werde ein Wunderzeichen an ihnen tun, und werde von ihnen Entronnene an die Nationen senden, nach Tarsis, Pul und Lud, die den Bogen spannen, nach Tubal und Jawan, nach den fernen Inseln, die von mir nicht gehört und meine Herrlichkeit nicht gesehen haben; und sie werden meine Herrlichkeit unter den Nationen verkündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Und sie werden alle eure Brüder aus allen Nationen als Opfergabe für Jehova bringen, auf Rossen und auf Wagen und auf Sänften und auf Maultieren und auf Dromedaren, nach meinem heiligen Berge, nach Jerusalem, spricht Jehova, gleichwie die Kinder Israel das Speisopfer in einem reinen Gefäße zum Hause Jehovas bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Und auch aus ihnen werde ich zu Priestern und zu Leviten nehmen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Denn gleichwie der neue Himmel und die neue Erde, die ich mache, vor mir bestehen, spricht Jehova, also wird euer Same und euer Name bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Und es wird geschehen: von Neumond zu Neumond und von Sabbath zu Sabbath wird alles Fleisch kommen, um vor mir anzubeten, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'Und sie werden hinausgehen und sich die Leichname der Menschen ansehen, die von mir abgefallen sind; denn ihr Wurm wird nicht sterben und ihr Feuer nicht erlöschen, und sie werden ein Abscheu sein allem Fleische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Worte Jeremias, des Sohnes Hilkijas, von den Priestern, die zu Anathoth waren im Lande Benjamin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'zu welchem das Wort Jehovas geschah in den Tagen Josias, des Sohnes Amons, des Königs von Juda, im dreizehnten Jahre seiner Regierung;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'und es geschah auch in den Tagen Jojakims, des Sohnes Josias, des Königs von Juda, bis zum Ende des elften Jahres Zedekias, des Sohnes Josias, des Königs von Juda, bis zur Wegführung Jerusalems im fünften Monat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Ehe ich dich im Mutterleibe bildete, habe ich dich erkannt, und ehe du aus dem Mutterschoße hervorkamst, habe ich dich geheiligt: zum Propheten an die Nationen habe ich dich bestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Und ich sprach: Ach, Herr, Jehova! Siehe, ich weiß nicht zu reden, denn ich bin jung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Da sprach Jehova zu mir: Sage nicht: Ich bin jung; denn zu allen, wohin ich dich senden werde, sollst du gehen, und alles, was ich dir gebieten werde, sollst du reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Fürchte dich nicht vor ihnen; denn ich bin mit dir, um dich zu erretten, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Und Jehova streckte seine Hand aus und rührte meinen Mund an, und Jehova sprach zu mir: Siehe, ich lege meine Worte in deinen Mund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Siehe, ich bestelle dich an diesem Tage über die Nationen und über die Königreiche, um auszurotten und niederzureißen und zu zerstören und abzubrechen, um zu bauen und um zu pflanzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Und das Wort Jehovas geschah zu mir also: Was siehst du, Jeremia? Und ich sprach: Ich sehe einen Mandelstab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Und Jehova sprach zu mir: Du hast recht gesehen; denn ich werde über mein Wort wachen, es auszuführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Und das Wort Jehovas geschah zu mir zum zweiten Male also: Was siehst du? Und ich sprach: Ich sehe einen siedenden Topf, dessen Vorderteil gegen Süden gerichtet ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Und Jehova sprach zu mir: Von Norden her wird das Unglück losbrechen über alle Bewohner des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Denn siehe, ich rufe allen Geschlechtern der Königreiche gegen Norden, spricht Jehova, daß sie kommen und ein jeder seinen Thron stellen an den Eingang der Tore Jerusalems und wider alle seine Mauern ringsum, und wider alle Städte Judas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Und ich werde meine Gerichte über sie sprechen wegen all ihrer Bosheit, daß sie mich verlassen und anderen Göttern geräuchert und vor den Werken ihrer Hände sich niedergebeugt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Du aber gürte deine Lenden und mache dich auf, und rede zu ihnen alles, was ich dir gebieten werde; verzage nicht vor ihnen, damit ich dich nicht vor ihnen verzagt mache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Und ich, siehe, ich mache dich heute zu einer festen Stadt und zu einer eisernen Säule und zu einer ehernen Mauer wider das ganze Land, sowohl wider die Könige von Juda als auch dessen Fürsten, dessen Priester und das Volk des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Und sie werden gegen dich streiten, aber dich nicht überwältigen; denn ich bin mit dir, spricht Jehova, um dich zu erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Geh und rufe vor den Ohren Jerusalems und sprich: So spricht Jehova: Ich gedenke dir die Zuneigung deiner Jugend, die Liebe deines Brautstandes, dein Wandeln hinter mir her in der Wüste, im unbesäten Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Israel war heilig dem Jehova, der Erstling seines Ertrages; alle, die es verzehren wollten, verschuldeten sich: Unglück kam über sie, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Höret das Wort Jehovas, Haus Jakob und alle Geschlechter des Hauses Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'So spricht Jehova: Was haben eure Väter Unrechtes an mir gefunden, daß sie sich von mir entfernt haben und der Nichtigkeit nachgegangen und nichtig geworden sind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Und sie sprachen nicht: Wo ist Jehova, der uns aus dem Lande Ägypten heraufgeführt hat, der uns leitete in der Wüste, in dem Lande der Steppen und der Gruben, in dem Lande der Dürre und des Todesschattens, in dem Lande, durch welches niemand zieht, und wo kein Mensch wohnt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Und ich brachte euch in ein Land der Fruchtgefilde, um seine Frucht und seinen Ertrag zu essen; und ihr kamet hin und verunreinigtet mein Land, und mein Erbteil habt ihr zum Greuel gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Die Priester sprachen nicht: Wo ist Jehova? Und die das Gesetz handhabten, kannten mich nicht, und die Hirten fielen von mir ab; und die Propheten weissagten durch den Baal und sind denen nachgegangen, welche nichts nützen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Darum werde ich weiter mit euch rechten, spricht Jehova; und mit euren Kindeskindern werde ich rechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Denn gehet hinüber zu den Inseln der Kittäer und sehet, und sendet nach Kedar und merket wohl auf; und sehet, ob dergleichen geschehen ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Hat irgend eine Nation die Götter vertauscht? Und doch sind sie nicht Götter; aber mein Volk hat seine Herrlichkeit vertauscht gegen das, was nichts nützt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Entsetzet euch darüber, ihr Himmel, und schaudert, starret sehr! spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Denn zweifach Böses hat mein Volk begangen: Mich, den Born lebendigen Wassers, haben sie verlassen, um sich Zisternen auszuhauen, geborstene Zisternen, die kein Wasser halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Ist Israel ein Knecht, oder ist er ein Hausgeborener? Warum ist er zur Beute geworden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Junge Löwen haben wider ihn gebrüllt, ließen ihre Stimme hören, und haben sein Land zur Wüste gemacht; seine Städte sind verbrannt worden, so daß niemand darin wohnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Auch die Söhne von Noph und Tachpanches weideten dir den Scheitel ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Ist es nicht dein Verlassen Jehovas, deines Gottes, zur Zeit, da er dich auf dem Wege führte, welches dir dieses bewirkt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Und nun, was hast du mit dem Wege nach Ägypten zu schaffen, um die Wasser des Sichor zu trinken? Und was hast du mit dem Wege nach Assyrien zu schaffen, um die Wasser des Stromes zu trinken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Deine Bosheit züchtigt dich und deine Abtrünnigkeiten strafen dich; so erkenne und sieh, daß es schlimm und bitter ist, daß du Jehova, deinen Gott, verlässest, und daß meine Furcht nicht bei dir ist, spricht der Herr, Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Denn vor alters hast du dein Joch zerbrochen, deine Bande zerrissen, und hast gesagt: Ich will nicht dienen! Sondern auf jedem hohen Hügel und unter jedem grünen Baume gabst du dich preis als Hure.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Und ich hatte dich gepflanzt als Edelrebe, lauter echtes Gewächs; und wie hast du dich mir verwandelt in entartete Ranken eines fremden Weinstocks!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Ja, wenn du dich mit Natron wüschest und viel Laugensalz nähmest: schmutzig bleibt deine Ungerechtigkeit vor mir, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Wie sprichst du: Ich habe mich nicht verunreinigt, ich bin den Baalim nicht nachgegangen? Sieh deinen Weg im Tale, erkenne, was du getan hast, du flinke Kamelin, die rechts und links umherläuft!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Eine Wildeselin, die Wüste gewohnt, in ihrer Lustbegierde schnappt sie nach Luft; ihre Brunst, wer wird sie hemmen? Alle, die sie suchen, brauchen sich nicht abzumüden: In ihrem Monat werden sie sie finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Bewahre deinen Fuß vor dem Barfußgehen und deine Kehle vor dem Durste! Aber du sprichst: Es ist umsonst, nein! Denn ich liebe die Fremden, und ihnen gehe ich nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Wie ein Dieb beschämt ist, wenn er ertappt wird, also ist beschämt worden das Haus Israel, sie, ihre Könige, ihre Fürsten und ihre Priester und ihre Propheten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'die zum Holze sprechen: Du bist mein Vater, und zum Steine: Du hast mich geboren; denn sie haben mir den Rücken zugekehrt und nicht das Angesicht. Aber zur Zeit ihres Unglücks sprechen sie: Stehe auf und rette uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Wo sind nun deine Götter, die du dir gemacht hast? Mögen sie aufstehen, ob sie dich retten können zur Zeit deines Unglücks! Denn so zahlreich wie deine Städte sind deine Götter geworden, Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Warum rechtet ihr mit mir? Allesamt seid ihr von mir abgefallen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Vergeblich habe ich eure Kinder geschlagen, sie haben keine Zucht angenommen; euer Schwert hat eure Propheten gefressen wie ein verderbender Löwe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'O Geschlecht, das ihr seid, merket das Wort Jehovas! Bin ich für Israel eine Wüste gewesen, oder ein Land tiefer Finsternis? Warum spricht mein Volk: Wir schweifen umher, wir kommen nicht mehr zu dir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Vergißt auch eine Jungfrau ihres Schmuckes, eine Braut ihres Gürtels? Aber mein Volk hat meiner vergessen Tage ohne Zahl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Wie schön richtest du deinen Weg ein, um Liebe zu suchen! Darum hast du auch an Übeltaten deine Wege gewöhnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Ja, an den Säumen deiner Kleider findet sich das Blut unschuldiger Armer; und nicht beim Einbruch hast du sie betroffen, sondern wegen all jener Dinge hast du es getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Und du sagst: Ich bin unschuldig, ja, sein Zorn hat sich von mir abgewandt. Siehe, ich werde Gericht an dir üben, weil du sagst: Ich habe nicht gesündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Was läufst du so sehr, um deinen Weg zu ändern? Auch wegen Ägyptens wirst du beschämt werden, wie du wegen Assyriens beschämt worden bist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'auch von diesen wirst du weggehen mit deinen Händen auf deinem Haupte. Denn Jehova verwirft die, auf welche du vertraust, und es wird dir mit ihnen nicht gelingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Er spricht: Wenn ein Mann sein Weib entläßt, und sie von ihm weggeht und eines anderen Mannes wird, darf er wieder zu ihr zurückkehren? Würde nicht selbiges Land entweiht werden? Du aber hast mit vielen Buhlen gehurt, und doch solltest du zu mir zurückkehren! spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Hebe deine Augen auf zu den kahlen Höhen und sieh! Wo bist du nicht geschändet worden? An den Wegen saßest du für sie, wie ein Araber in der Wüste; und du hast das Land entweiht durch deine Hurerei und durch deine Bosheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Und die Regenschauer wurden zurückgehalten, und es ist kein Spätregen gewesen; aber du hattest die Stirn eines Hurenweibes, weigertest dich, dich zu schämen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Nicht wahr? Von jetzt an rufst du mir zu: Mein Vater, der Freund meiner Jugend bist du!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Wird er ewiglich nachtragen, wird er immer dar Zorn bewahren? Siehe, so redest du, und begehst Übeltaten und setzest sie durch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Und Jehova sprach zu mir in den Tagen des Königs Josia: Hast du gesehen, was die abtrünnige Israel getan hat? Sie ging auf jeden hohen Berg und unter jeden grünen Baum und hurte daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Und ich sprach: Nachdem sie dies alles getan hat, wird sie zu mir zurückkehren. Aber sie kehrte nicht zurück. Und ihre treulose Schwester Juda sah es;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'und ich sah, daß trotz alledem, daß ich die abtrünnige Israel, weil sie die Ehe gebrochen, entlassen und ihr einen Scheidebrief gegeben hatte, doch die treulose Juda, ihre Schwester, sich nicht fürchtete, sondern hinging und selbst auch hurte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Und es geschah, wegen des Lärmes ihrer Hurerei entweihte sie das Land; und sie trieb Ehebruch mit Stein und mit Holz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Und selbst bei diesem allen ist ihre treulose Schwester Juda nicht zu mir zurückgekehrt mit ihrem ganzen Herzen, sondern nur mit Falschheit, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Und Jehova sprach zu mir: Die abtrünnige Israel hat sich gerechter erwiesen als Juda, die treulose.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Geh, und rufe diese Worte aus gegen Norden und sprich: Kehre zurück, du abtrünnige Israel, spricht Jehova; ich will nicht finster auf euch blicken. Denn ich bin gütig, spricht Jehova, ich werde nicht ewiglich nachtragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Nur erkenne deine Missetat, daß du von Jehova, deinem Gott, abgefallen und zu den Fremden hin und her gelaufen bist unter jeden grünen Baum; aber auf meine Stimme habt ihr nicht gehört, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Kehret um, ihr abtrünnigen Kinder, spricht Jehova, denn ich habe mich ja mit euch vermählt; und ich werde euch nehmen, einen aus einer Stadt und zwei aus einem Geschlecht, und euch nach Zion bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Und ich werde euch Hirten geben nach meinem Herzen, und sie werden euch weiden mit Erkenntnis und Einsicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Und es wird geschehen, wenn ihr euch im Lande mehret und fruchtbar seid in jenen Tagen, spricht Jehova, so wird man nicht mehr sagen: \"Die Bundeslade Jehovas\"; und sie wird nicht mehr in den Sinn kommen, und man wird ihrer nicht mehr gedenken noch sie suchen, und sie wird nicht wieder gemacht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'In jener Zeit wird man Jerusalem den Thron Jehovas nennen, und alle Nationen werden sich zu ihr versammeln wegen des Namens Jehovas in Jerusalem; und sie werden nicht mehr dem Starrsinn ihres bösen Herzens nachwandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'In jenen Tagen wird das Haus Juda mit dem Hause Israel ziehen, und sie werden miteinander aus dem Lande des Nordens in das Land kommen, welches ich euren Vätern zum Erbteil gegeben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Und ich sprach: Wie will ich dich stellen unter den Söhnen und dir ein köstliches Land geben, ein Erbteil, das die herrlichste Zierde der Nationen ist! Und ich sprach: Ihr werdet mir zurufen: Mein Vater! und werdet euch nicht von mir abwenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Fürwahr, wie ein Weib ihren Freund treulos verläßt, so habt ihr treulos gegen mich gehandelt, Haus Israel, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Eine Stimme wird gehört auf den kahlen Höhen, ein Weinen, ein Flehen der Kinder Israel; weil sie ihren Weg verkehrt, Jehovas, ihres Gottes, vergessen haben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Kehret um, ihr abtrünnigen Kinder; ich will eure Abtrünnigkeiten heilen. \"Hier sind wir, wir kommen zu dir; denn du bist Jehova, unser Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Fürwahr, trüglich ist von den Hügeln, von den Bergen her das Lärmen; fürwahr, in Jehova, unserem Gott, ist das Heil Israels!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Denn die Schande hat den Erwerb unserer Väter verzehrt von unserer Jugend an, ihr Kleinvieh und ihre Rinder, ihre Söhne und ihre Töchter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'In unserer Schande müssen wir daliegen, und unsere Schmach bedeckt uns! Denn wir haben gegen Jehova, unseren Gott, gesündigt, wir und unsere Väter, von unserer Jugend an bis auf diesen Tag, und wir haben nicht auf die Stimme Jehovas, unseres Gottes, gehört.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Wenn du umkehrst, Israel, spricht Jehova, zu mir umkehrst, und wenn du deine Scheusale von meinem Angesicht hinwegtust, und nicht mehr umherschweifst, sondern schwörst:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'So wahr Jehova lebt! in Wahrheit, in Recht und in Gerechtigkeit, so werden die Nationen sich in ihm segnen und sich seiner rühmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Denn so spricht Jehova zu den Männern von Juda und zu Jerusalem: Pflüget euch einen Neubruch, und säet nicht unter die Dornen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Beschneidet euch für Jehova und tut hinweg die Vorhäute eurer Herzen, ihr Männer von Juda und ihr Bewohner von Jerusalem, damit mein Grimm nicht ausbreche wie ein Feuer und unauslöschlich brenne wegen der Bosheit eurer Handlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Verkündiget in Juda und laßt in Jerusalem vernehmen, und sprechet: Stoßet in die Posaune im Lande! Rufet aus voller Kehle und sprechet: Versammelt euch und laßt uns in die festen Städte ziehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Erhebet ein Panier gegen Zion hin; flüchtet, bleibet nicht stehen! Denn ich bringe Unglück von Norden her und große Zerschmetterung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Ein Löwe steigt herauf aus seinem Dickicht, und ein Verderber der Nationen bricht auf; er zieht von seinem Orte aus, um dein Land zur Wüste zu machen, daß deine Städte zerstört werden, ohne Bewohner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Darum gürtet euch Sacktuch um, klaget und jammert! Denn die Glut des Zornes Jehovas hat sich nicht von uns abgewendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Und es wird geschehen an jenem Tage, spricht Jehova, da wird das Herz des Königs und das Herz der Fürsten vergehen; und die Priester werden sich entsetzen, und die Propheten erstarrt sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Da sprach ich: Ach, Herr, Jehova! Fürwahr, getäuscht hast du dieses Volk und Jerusalem, indem du sprachst: Ihr werdet Frieden haben; und das Schwert dringt bis an die Seele!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'In jener Zeit wird diesem Volke und Jerusalem gesagt werden: Ein scharfer Wind von den kahlen Höhen in der Wüste kommt des Weges zur Tochter meines Volkes, nicht zum Worfeln und nicht zum Säubern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'ein Wind zu voll dazu wird mir kommen. Nun will auch ich Gerichte über sie aussprechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Siehe, gleich Wolken zieht er herauf, und wie der Sturmwind sind seine Wagen, schneller als Adler seine Rosse. Wehe uns! Denn wir sind verwüstet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Wasche dein Herz rein von Bosheit, Jerusalem, damit du gerettet werdest! Wie lange sollen deine heillosen Anschläge in deinem Innern weilen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Denn eine Stimme berichtet von Dan und verkündet Unheil vom Gebirge Ephraim her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Meldet es den Nationen, siehe, verkündet es Jerusalem: Belagerer kommen aus fernem Lande und lassen ihre Stimme erschallen wider die Städte Judas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'wie Feldwächter sind sie ringsumher wider dasselbe. Denn gegen mich ist es widerspenstig gewesen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Dein Weg und deine Handlungen haben dir solches bewirkt; dies ist deine Bosheit; ja, es ist bitter, ja, es dringt bis an dein Herz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Meine Eingeweide, meine Eingeweide! Mir ist angst! Die Wände meines Herzens! Es tobt in mir mein Herz! Ich kann nicht schweigen! Denn du, meine Seele, hörst den Schall der Posaune, Kriegsgeschrei:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Zerstörung über Zerstörung wird ausgerufen. Denn das ganze Land ist verwüstet; plötzlich sind meine Zelte zerstört, meine Zeltbehänge in einem Augenblick.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Wie lange soll ich das Panier sehen, den Schall der Posaune hören? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Denn mein Volk ist närrisch, mich kennen sie nicht; törichte Kinder sind sie und unverständig. Weise sind sie, Böses zu tun; aber Gutes zu tun verstehen sie nicht. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Ich schaue die Erde an und siehe, sie ist wüst und leer; und gen Himmel, und sein Licht ist nicht da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Ich schaue die Berge an, und siehe, sie heben; und alle Hügel schwanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Ich schaue, und siehe, kein Mensch ist da; und alle Vögel des Himmels sind entflohen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Ich schaue, und siehe, der Karmel ist eine Wüste; und alle seine Städte sind niedergerissen vor Jehova, vor der Glut seines Zornes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Denn so spricht Jehova: Das ganze Land soll eine Wüste werden; doch will ich es nicht gänzlich zerstören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Darum wird die Erde trauern, und der Himmel oben schwarz werden, weil ich es geredet, beschlossen habe; und ich werde es mich nicht gereuen lassen und nicht davon zurückkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Vor dem Geschrei der Reiter und der Bogenschützen flieht jede Stadt: Sie gehen ins Dickicht und ersteigen die Felsen; jede Stadt ist verlassen, und kein Mensch wohnt darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Und du, Verwüstete, was wirst du tun? Wenn du dich auch in Karmesin kleidest, wenn du mit goldenem Geschmeide dich schmückst, wenn du deine Augen mit Schminke aufreißest: vergeblich machst du dich schön; die Buhlen verschmähen dich, sie trachten nach deinem Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Denn ich höre eine Stimme wie von einer Kreißenden, Angst wie von einer Erstgebärenden, die Stimme der Tochter Zion; sie seufzt, sie breitet ihre Hände aus: Wehe mir! Denn kraftlos erliegt meine Seele den Mördern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Durchstreifet die Gassen Jerusalems, und sehet doch und erkundet und suchet auf ihren Plätzen, ob ihr jemand findet, ob einer da ist, der Recht übt, der Treue sucht: so will ich ihr vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Und wenn sie sprechen: So wahr Jehova lebt! so schwören sie darum doch falsch. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Jehova, sind deine Augen nicht auf die Treue gerichtet? Du hast sie geschlagen, aber es hat sie nicht geschmerzt; du hast sie vernichtet: Sie haben sich geweigert, Zucht anzunehmen; sie haben ihre Angesichter härter gemacht als einen Fels, sie haben sich geweigert, umzukehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Und ich sprach: Nur Geringe sind es; die sind betört, weil sie den Weg Jehovas, das Recht ihres Gottes, nicht kennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Ich will doch zu den Großen gehen und mit ihnen reden; denn sie kennen den Weg Jehovas, das Recht ihres Gottes. Doch sie haben allzumal das Joch zerbrochen, die Bande zerrissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Darum erschlägt sie ein Löwe aus dem Walde, ein Wolf der Steppen vertilgt sie, ein Pardel belauert ihre Städte: Jeder, der aus ihnen hinausgeht, wird zerrissen; denn ihrer Übertretungen sind viele, zahlreich ihre Abtrünnigkeiten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Weshalb sollte ich dir vergeben? Deine Söhne haben mich verlassen und schwören bei Nichtgöttern. Obwohl ich sie schwören ließ, haben sie Ehebruch getrieben und laufen scharenweise ins Hurenhaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Wie wohlgenährte Pferde schweifen sie umher; sie wiehern ein jeder nach seines Nächsten Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Sollte ich solches nicht heimsuchen? spricht Jehova; oder sollte an einer Nation, wie diese, meine Seele sich nicht rächen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Ersteiget seine Mauern und zerstöret, doch richtet ihn nicht völlig zu Grunde; nehmet seine Ranken weg, denn nicht Jehovas sind sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Denn das Haus Israel und das Haus Juda haben gar treulos gegen mich gehandelt, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Sie haben Jehova verleugnet und gesagt: Er ist nicht; und kein Unglück wird über uns kommen, und Schwert und Hunger werden wir nicht sehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'und die Propheten werden zu Wind werden, und der da redet, ist nicht in ihnen: Also wird ihnen geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Darum, so spricht Jehova, der Gott der Heerscharen: Weil ihr dieses Wort redet, siehe, so will ich meine Worte in deinem Munde zu Feuer machen und dieses Volk zu Holz, und es soll sie verzehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Siehe, ich bringe über euch eine Nation aus der Ferne, Haus Israel, spricht Jehova; es ist eine starke Nation, es ist eine Nation von alters her, eine Nation, deren Sprache du nicht kennst, und deren Rede du nicht verstehst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Ihr Köcher ist wie ein offenes Grab; sie sind Helden allesamt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Und sie wird deine Ernte verzehren und dein Brot, sie wird deine Söhne und deine Töchter verzehren, sie wird verzehren dein Kleinvieh und deine Rinder, verzehren deinen Weinstock und deinen Feigenbaum; deine festen Städte, auf welche du dich verlässest, wird sie mit dem Schwerte zerstören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Aber auch in selbigen Tagen, spricht Jehova, werde ich euch nicht den Garaus machen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Und es soll geschehen, wenn ihr sagen werdet: Weshalb hat Jehova, unser Gott, uns dies alles getan? so sprich zu ihnen: Gleichwie ihr mich verlassen und fremden Göttern gedient habt in eurem Lande, also sollt ihr Fremden dienen in einem Lande, das nicht euer ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Verkündet dieses im Hause Jakob und laßt es hören in Juda, und sprechet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Höret doch dieses, törichtes Volk, ohne Verstand, die Augen haben und nicht sehen, die Ohren haben und nicht hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Wollt ihr mich nicht fürchten, spricht Jehova, und vor mir nicht zittern? Der ich dem Meere Sand zur Grenze gesetzt habe, eine ewige Schranke, die es nicht überschreiten wird; und es regen sich seine Wogen, aber sie vermögen nichts, und sie brausen, aber überschreiten sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Aber dieses Volk hat ein störriges und widerspenstiges Herz; sie sind abgewichen und weggegangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Und sie sprachen nicht in ihrem Herzen: Laßt uns doch Jehova, unseren Gott, fürchten, welcher Regen gibt, sowohl Frühregen als Spätregen, zu seiner Zeit; der die bestimmten Wochen der Ernte uns einhält.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Eure Missetaten haben dieses weggewendet, und eure Sünden das Gute von euch abgehalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Denn unter meinem Volke finden sich Gesetzlose; sie lauern, wie Vogelsteller sich ducken; sie stellen Fallen, fangen Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Wie ein Käfig voll Vögel, so sind ihre Häuser voll Betrugs; darum sind sie groß und reich geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Sie sind fett, sie sind glatt; ja, sie überschreiten das Maß der Bosheit. Die Rechtssache richten sie nicht, die Rechtssache der Waisen, so daß es ihnen gelingen könnte; und die Rechtssache der Armen entscheiden sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Sollte ich solches nicht heimsuchen? spricht Jehova; oder sollte an einer Nation wie diese meine Seele sich nicht rächen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Entsetzliches und Schauderhaftes ist im Lande geschehen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'die Propheten weissagen falsch, und die Priester herrschen unter ihrer Leitung, und mein Volk liebt es so. Was werdet ihr aber tun am Ende von dem allen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Flüchtet, ihr Kinder Benjamin, aus Jerusalem hinaus, und stoßet in die Posaune zu Tekoa, und errichtet ein Zeichen über Beth-Hakkerem; denn Unglück ragt herein von Norden her und große Zerschmetterung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Die Schöne und die Verzärtelte, die Tochter Zion, vertilge ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Hirten kommen zu ihr mit ihren Herden; sie schlagen Zelte rings um sie auf, weiden ein jeder seinen Raum ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, '\"Heiliget einen Krieg wider sie! Machet euch auf und laßt uns am Mittag hinaufziehen!...Wehe uns! Denn der Tag hat sich geneigt, denn die Abendschatten strecken sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Machet euch auf und laßt uns in der Nacht hinaufziehen und ihre Paläste verderben!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Denn so hat Jehova der Heerscharen gesprochen: Fället Bäume und schüttet einen Wall wider Jerusalem auf! Sie ist die Stadt, die heimgesucht werden soll; sie ist voll Bedrückung in ihrem Innern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Wie ein Brunnen sein Wasser quellen läßt, so läßt sie ihre Bosheit quellen. Gewalttat und Zerstörung werden in ihr gehört, Wunde und Schlag sind beständig vor meinem Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Laß dich zurechtweisen, Jerusalem, damit meine Seele sich nicht von dir losreiße, damit ich dich nicht zur Wüste mache, zu einem unbewohnten Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'So spricht Jehova der Heerscharen: Wie am Weinstock wird man Nachlese halten an dem Überrest Israels. Lege wieder deine Hand an, wie der Winzer an die Ranken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Zu wem soll ich reden und wem Zeugnis ablegen, daß sie hören? Siehe, ihr Ohr ist unbeschnitten, und sie können nicht aufmerken; siehe, das Wort Jehovas ist ihnen zum Hohn geworden, sie haben keine Lust daran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Und ich bin voll des Grimmes Jehovas, bin müde, ihn zurückzuhalten. Ergieße ihn über die Kinder auf der Gasse und über den Kreis der Jünglinge allzumal; denn sowohl Mann als Weib werden getroffen werden, der Alte wie der Hochbetagte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'und ihre Häuser werden anderen zugewandt werden, Felder und Weiber allzumal. Denn ich strecke meine Hand aus wider die Bewohner des Landes, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Denn von ihrem Kleinsten bis zu ihrem Größten sind sie insgesamt der Gewinnsucht ergeben; und vom Propheten bis zum Priester üben sie allesamt Falschheit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'und sie heilen die Wunde der Tochter meines Volkes leichthin und sprechen: Friede, Friede! Und da ist doch kein Friede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Sie werden beschämt werden, weil sie Greuel verübt haben. Ja, sie schämen sich keineswegs, ja, Beschämung kennen sie nicht. Darum werden sie fallen unter den Fallenden; zur Zeit, da ich sie heimsuchen werde, werden sie straucheln, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'So spricht Jehova: Tretet auf die Wege, und sehet und fraget nach den Pfaden der Vorzeit, welches der Weg des Guten sei, und wandelt darauf; so werdet ihr Ruhe finden für eure Seelen. Aber sie sprechen: Wir wollen nicht darauf wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Und ich habe Wächter über euch bestellt, die da sagen: Merket auf den Schall der Posaune! Aber sie sprechen: Wir wollen nicht darauf merken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Darum höret, ihr Nationen, und wisse, du Gemeinde, was wider sie geschieht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Höre es, Erde! Siehe, ich bringe Unglück über dieses Volk, die Frucht ihrer Gedanken; denn auf meine Worte haben sie nicht gemerkt, und mein Gesetz sie haben es verschmäht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Wozu soll mir denn Weihrauch aus Scheba kommen, und das gute Würzrohr aus fernem Lande? Eure Brandopfer sind mir nicht wohlgefällig und eure Schlachtopfer mir nicht angenehm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Darum, so spricht Jehova: Siehe, ich lege diesem Volke Anstöße, daß Väter und Kinder darüber straucheln, daß der Nachbar und sein Genosse zumal umkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'So spricht Jehova: Siehe, es kommt ein Volk aus dem Lande des Nordens, und eine große Nation macht sich auf von dem äußersten Ende der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Bogen und Wurfspieß führen sie, sie sind grausam und ohne Erbarmen; ihre Stimme braust wie das Meer, und auf Rossen reiten sie: gerüstet wider dich, Tochter Zion, wie ein Mann zum Kriege. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Wir haben die Kunde von ihm vernommen: Unsere Hände sind schlaff geworden; Angst hat uns ergriffen, Wehen, der Gebärenden gleich. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Geh nicht hinaus aufs Feld und wandle nicht auf dem Wege; denn der Feind hat ein Schwert, Schrecken ringsum!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Tochter meines Volkes, gürte dir Sacktuch um und wälze dich in der Asche, trauere wie um den Eingeborenen, führe bittere Klage! Denn plötzlich wird der Verwüster über uns kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Ich habe dich zum Prüfer unter meinem Volke gesetzt, als eine Feste, damit du ihren Weg erkennen und prüfen möchtest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Allesamt sind sie die Widerspenstigsten der Widerspenstigen; sie gehen als Verleumder umher, sie sind Erz und Eisen; sie handeln verderbt allesamt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Versengt vom Feuer ist der Blasebalg, zu Ende ist das Blei; vergebens hat man geschmolzen und geschmolzen: Die Bösen sind nicht ausgeschieden worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Verworfenes Silber nennt man sie, denn Jehova hat sie verworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Das Wort, welches von seiten Jehovas zu Jeremia geschah, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Stelle dich in das Tor des Hauses Jehovas, und rufe daselbst dieses Wort aus und sprich: Höret das Wort Jehovas, ganz Juda, die ihr durch diese Tore eingehet, um Jehova anzubeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'So spricht Jehova der Heerscharen, der Gott Israels: Machet gut eure Wege und eure Handlungen, so will ich euch an diesem Orte wohnen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Und verlasset euch nicht auf Worte der Lüge, indem man spricht: Der Tempel Jehovas, der Tempel Jehovas, der Tempel Jehovas ist dies!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Sondern wenn ihr eure Wege und eure Handlungen wirklich gut machet, wenn ihr wirklich Recht übet zwischen dem einen und dem anderen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'den Fremdling, die Waise und die Witwe nicht bedrücket, und unschuldiges Blut an diesem Orte nicht vergießet, und anderen Göttern nicht nachwandelt euch zum Unglück:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'so will ich euch an diesem Orte, in dem Lande, das ich euren Vätern gegeben habe, wohnen lassen von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Siehe, ihr verlasset euch auf Worte der Lüge, die nichts nutzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Wie? Stehlen, morden und Ehebruch treiben und falsch schwören und dem Baal räuchern und anderen Göttern nachwandeln, die ihr nicht kennet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Und dann kommet ihr und tretet vor mein Angesicht in diesem Hause, welches nach meinem Namen genannt ist, und sprechet: Wir sind errettet damit ihr alle diese Greuel verübet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Ist denn dieses Haus, welches nach meinem Namen genannt ist, eine Räuberhöhle geworden in euren Augen? Ich selbst, siehe, ich habe es gesehen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Denn gehet doch hin nach meiner Stätte, die zu Silo war, woselbst ich zuerst meinen Namen wohnen ließ, und sehet, was ich ihr getan habe wegen der Bosheit meines Volkes Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Und nun, weil ihr alle diese Werke getan habt, spricht Jehova, und ich zu euch geredet habe, früh mich aufmachend und redend, ihr aber nicht gehört habt; und ich euch gerufen, ihr aber nicht geantwortet habt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'So werde ich diesem Hause, welches nach meinem Namen genannt ist, worauf ihr euch verlasset, und dem Orte, den ich euch und euren Vätern gegeben, ebenso tun, wie ich Silo getan habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Und ich werde euch wegwerfen von meinem Angesicht, so wie ich alle eure Brüder, den ganzen Samen Ephraims, weggeworfen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Du aber, bitte nicht für dieses Volk und erhebe weder Flehen noch Gebet für sie, und dringe nicht in mich; denn ich werde nicht auf dich hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Siehst du nicht, was sie in den Städten Judas und auf den Straßen von Jerusalem tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Die Kinder lesen Holz auf, und die Väter zünden das Feuer an; und die Weiber kneten den Teig, um Kuchen zu bereiten für die Königin des Himmels und anderen Göttern Trankopfer zu spenden, um mich zu kränken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Kränken sie mich, spricht Jehova, nicht vielmehr sich selbst zur Beschämung ihres Angesichts?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Darum spricht der Herr, Jehova, also: Siehe, mein Zorn und mein Grimm wird sich über diesen Ort ergießen, über die Menschen und über das Vieh, und über die Bäume des Feldes und über die Frucht des Landes; und er wird brennen und nicht erlöschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'So spricht Jehova der Heerscharen, der Gott Israels: Füget eure Brandopfer zu euren Schlachtopfern und esset Fleisch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Denn ich habe nicht mit euren Vätern geredet und ihnen nicht betreffs des Brandopfers und des Schlachtopfers geboten, an dem Tage, da ich sie aus dem Lande Ägypten herausführte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'sondern dieses Wort habe ich ihnen geboten, und gesagt: Höret auf meine Stimme, so werde ich euer Gott sein, und ihr werdet mein Volk sein; und wandelt auf dem ganzen Wege, den ich euch gebiete, auf daß es euch wohlgehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Aber sie haben nicht gehört und ihr Ohr nicht geneigt, sondern haben gewandelt in den Ratschlägen, in dem Starrsinn ihres bösen Herzens; und sie haben mir den Rücken zugekehrt und nicht das Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Von dem Tage an, da eure Väter aus dem Lande Ägypten auszogen, bis auf diesen Tag habe ich alle meine Knechte, die Propheten, zu euch gesandt, täglich früh mich aufmachend und sendend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Aber sie haben nicht auf mich gehört und ihr Ohr nicht geneigt; und sie haben ihren Nacken verhärtet, haben es ärger gemacht als ihre Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Und wenn du alle diese Worte zu ihnen redest, so werden sie nicht auf dich hören; und rufst du ihnen zu, so werden sie dir nicht antworten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'So sprich denn zu ihnen: Dies ist das Volk, welches auf die Stimme Jehovas, seines Gottes, nicht hört und keine Zucht annimmt; die Treue ist untergegangen und ist ausgerottet aus ihrem Munde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Schere deinen Haarschmuck und wirf ihn weg, und erhebe ein Klagelied auf den kahlen Höhen: Denn Jehova hat das Geschlecht seines Grimmes verworfen und verstoßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Denn die Kinder Juda haben getan, was böse ist in meinen Augen, spricht Jehova; sie haben ihre Scheusale in das Haus gestellt, welches nach meinem Namen genannt ist, um es zu verunreinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Und sie haben die Höhen des Topheth gebaut, welches im Tale des Sohnes Hinnoms ist, um ihre Söhne und ihre Töchter im Feuer zu verbrennen, was ich nicht geboten habe und mir nicht in den Sinn gekommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Darum siehe, Tage kommen, spricht Jehova, da man nicht mehr Topheth, noch Tal des Sohnes Hinnoms, sondern Würgetal sagen wird; man wird im Topheth begraben aus Mangel an Raum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Und die Leichname dieses Volkes werden dem Gevögel des Himmels und den Tieren der Erde zur Speise sein, und niemand wird sie wegscheuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Und ich werde in den Städten Judas und auf den Straßen von Jerusalem aufhören lassen die Stimme der Wonne und die Stimme der Freude, die Stimme des Bräutigams und die Stimme der Braut; denn das Land soll zur Einöde werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'In jener Zeit, spricht Jehova, wird man die Gebeine der Könige von Juda und die Gebeine seiner Fürsten und die Gebeine der Priester und die Gebeine der Propheten und die Gebeine der Bewohner von Jerusalem aus ihren Gräbern herausnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'Und man wird sie ausbreiten vor der Sonne und vor dem Monde und vor dem ganzen Heere des Himmels, welche sie geliebt und welchen sie gedient haben, und denen sie nachgewandelt sind, und welche sie gesucht und vor denen sie sich niedergebeugt haben; sie werden nicht gesammelt noch begraben werden, zu Dünger auf der Fläche des Erdbodens sollen sie werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Und der Tod wird dem Leben vorgezogen werden von dem ganzen Rest, der von diesem bösen Geschlecht übriggeblieben ist an allen Orten, wohin ich die Übriggebliebenen verstoßen haben werde, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Und sprich zu ihnen: So spricht Jehova: Fällt man denn und steht nicht wieder auf? Oder wendet man sich ab und kehrt nicht wieder zurück?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Warum kehrt sich dieses Volk Jerusalems ab in immerwährender Abkehr? Sie halten fest am Truge, sie weigern sich umzukehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Ich habe gehorcht und zugehört: Sie reden, was nicht recht ist; da ist keiner, der seine Bosheit bereue und spreche: Was habe ich getan! Allesamt wenden sie sich zu ihrem Laufe, wie ein in den Kampf stürmendes Roß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Selbst der Storch am Himmel kennt seine bestimmten Zeiten, und Turteltaube und Schwalbe und Kranich halten die Zeit ihres Kommens ein; aber mein Volk kennt das Recht Jehovas nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Wie möget ihr sagen: Wir sind weise, und das Gesetz Jehovas ist bei uns? Siehe, fürwahr, zur Lüge hat es gemacht der Lügengriffel der Schriftgelehrten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Die Weisen werden beschämt, bestürzt und gefangen werden; siehe, das Wort Jehovas haben sie verschmäht, und welcherlei Weisheit haben sie? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Darum werde ich ihre Weiber anderen geben, ihre Felder anderen Besitzern. Denn vom Kleinsten bis zum Größten sind sie insgesamt der Gewinnsucht ergeben; vom Propheten bis zum Priester üben sie allesamt Falschheit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'und sie heilen die Wunde der Tochter meines Volkes leichthin und sprechen: Friede, Friede! und da ist doch kein Friede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Sie werden beschämt werden, weil sie Greuel verübt haben. Ja, sie schämen sich keineswegs, ja, Beschämung kennen sie nicht. Darum werden sie fallen unter den Fallenden; zur Zeit ihrer Heimsuchung werden sie straucheln, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Wegraffen werde ich sie, spricht Jehova. Keine Trauben am Weinstock und keine Feigen am Feigenbaum, und das Blatt ist verwelkt: So will ich ihnen solche bestellen, die sie verheeren werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Wozu bleiben wir sitzen? Versammelt euch, und laßt uns in die festen Städte ziehen und dort umkommen! Denn Jehova, unser Gott, hat uns zum Untergang bestimmt, und uns mit bitterem Wasser getränkt, weil wir gegen Jehova gesündigt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Man hofft auf Frieden, und da ist nichts Gutes; auf die Zeit der Heilung, und siehe da, Schrecken. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Von Dan her wird das Schnauben seiner Rosse gehört; vom Schall des Wieherns seiner starken Rosse erzittert das ganze Land. Und sie kommen und verzehren das Land und seine Fülle, die Städte und ihre Bewohner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Denn siehe, ich sende unter euch Schlangen, Basilisken, gegen welche es keine Beschwörung gibt; und sie werden euch beißen, spricht Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'O meine Erquickung im Kummer! Mein Herz ist siech in mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Siehe, die Stimme des Geschreies der Tochter meines Volkes kommt aus fernem Lande: \"Ist Jehova nicht in Zion, oder ist ihr König nicht darin?\" Warum haben sie mich gereizt durch ihre geschnitzten Bilder, durch Nichtigkeiten der Fremde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, '\"Vorüber ist die Ernte, die Obstlese ist zu Ende, und wir sind nicht gerettet!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Ich bin zerschlagen wegen der Zerschmetterung der Tochter meines Volkes; ich gehe trauernd einher, Entsetzen hat mich ergriffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Ist kein Balsam in Gilead, oder kein Arzt daselbst? Denn warum ist der Tochter meines Volkes kein Verband angelegt worden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'O daß mein Haupt Wasser wäre und mein Auge ein Tränenquell, so wollte ich Tag und Nacht beweinen die Erschlagenen der Tochter meines Volkes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'O daß ich in der Wüste eine Wandererherberge hätte, so wollte ich mein Volk verlassen und von ihnen wegziehen! Denn sie sind allesamt Ehebrecher, eine Rotte Treuloser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Und sie spannen ihre Zunge, ihren Bogen, mit Lüge, und nicht nach Treue schalten sie im Lande; denn sie schreiten fort von Bosheit zu Bosheit, und mich kennen sie nicht, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Hütet euch ein jeder vor seinem Freunde, und auf keinen Bruder vertrauet; denn jeder Bruder treibt Hinterlist, und jeder Freund geht als Verleumder einher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Und sie betrügen einer den anderen, und Wahrheit reden sie nicht; sie lehren ihre Zunge Lügen reden, sie mühen sich ab, verkehrt zu handeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Deine Wohnung ist mitten unter Trug. Vor Trug weigern sie sich, mich zu erkennen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Darum, so spricht Jehova der Heerscharen: Siehe, ich will sie schmelzen und läutern; denn wie sollte ich anders handeln wegen der Tochter meines Volkes?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Ihre Zunge ist ein mörderischer Pfeil, man redet Trug; mit seinem Munde redet man Frieden mit seinem Nächsten, und in seinem Innern legt man ihm einen Hinterhalt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Sollte ich solches nicht an ihnen heimsuchen? spricht Jehova; oder sollte an einer Nation wie diese meine Seele sich nicht rächen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Über die Berge will ich ein Weinen und eine Wehklage erheben, und über die Auen der Steppe ein Klagelied. Denn sie sind verbrannt, so daß niemand hindurchzieht und man die Stimme der Herde nicht hört; sowohl die Vögel des Himmels als auch das Vieh sind entflohen, weggezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Und ich werde Jerusalem zu Steinhaufen machen, zur Wohnung der Schakale, und die Städte von Juda zur Wüste machen, ohne Bewohner. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Wer ist der weise Mann, daß er dieses verstehe, und zu wem hat der Mund Jehovas geredet, daß er es kundtue, warum das Land zu Grunde geht und verbrannt wird gleich der Wüste, so daß niemand hindurchzieht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Und Jehova sprach: Weil sie mein Gesetz verlassen haben, das ich ihnen vorgelegt, und auf meine Stimme nicht gehört, und nicht darin gewandelt haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'sondern dem Starrsinn ihres Herzens und den Baalim nachgegangen sind, was ihre Väter sie gelehrt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Darum, so spricht Jehova der Heerscharen, der Gott Israels: Siehe, ich will sie, dieses Volk, mit Wermut speisen und sie mit bitterem Wasser tränken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'und sie unter die Nationen zerstreuen, die sie nicht gekannt haben, weder sie noch ihre Väter; und ich will das Schwert hinter ihnen her senden, bis ich sie vernichtet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'So spricht Jehova der Heerscharen: Gebet acht, und rufet Klageweiber, daß sie kommen, und schicket zu den weisen Frauen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'daß sie kommen und eilends eine Wehklage über uns erheben, damit unsere Augen von Tränen rinnen und unsere Wimpern von Wasser fließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Denn eine Stimme der Wehklage wird aus Zion gehört: \"Wie sind wir verwüstet! Wir sind völlig zu Schanden geworden; denn wir haben das Land verlassen müssen, denn sie haben unsere Wohnungen umgestürzt\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Denn höret, ihr Weiber, das Wort Jehovas, und euer Ohr fasse das Wort seines Mundes; und lehret eure Töchter Wehklage und eine die andere Klagegesang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Denn der Tod ist durch unsere Fenster gestiegen, er ist in unsere Paläste gekommen, um das Kind auszurotten von der Gasse, die Jünglinge von den Straßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Rede: So spricht Jehova: Ja, die Leichen der Menschen werden fallen wie Dünger auf der Fläche des Feldes und wie eine Garbe hinter dem Schnitter, die niemand sammelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'So spricht Jehova: Der Weise rühme sich nicht seiner Weisheit, und der Starke rühme sich nicht seiner Stärke, der Reiche rühme sich nicht seines Reichtums;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'sondern wer sich rühmt, rühme sich dessen: Einsicht zu haben und mich zu erkennen, daß ich Jehova bin, der Güte, Recht und Gerechtigkeit übt auf der Erde; denn daran habe ich Gefallen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Siehe, Tage kommen, spricht Jehova, da ich heimsuchen werde alle Beschnittenen mit den Unbeschnittenen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Ägypten und Juda und Edom und die Kinder Ammon und Moab, und alle mit geschorenen Haarrändern, die in der Wüste wohnen; denn alle Nationen sind unbeschnitten, und das ganze Haus Israel ist unbeschnittenen Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Höret das Wort, welches Jehova zu euch redet, Haus Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'So spricht Jehova: Lernet nicht den Weg der Nationen, und erschrecket nicht vor den Zeichen des Himmels, weil die Nationen vor ihnen erschrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Denn die Satzungen der Völker sind Nichtigkeit; denn Holz ist es, das einer aus dem Walde gehauen hat, ein Werk von Künstlerhänden, mit dem Beile verfertigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Er schmückt es mit Silber und mit Gold; mit Nägeln und mit Hämmern befestigen sie es, daß es nicht wanke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'sie sind wie eine gedrechselte Säule und reden nicht; sie werden getragen, denn sie gehen nicht. Fürchtet euch nicht vor ihnen; denn sie können nichts Böses tun, und Gutes zu tun steht auch nicht bei ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Gar niemand ist dir gleich, Jehova; du bist groß, und groß ist dein Name in Macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Wer sollte dich nicht fürchten, König der Nationen? Denn dir gebührt es. Denn unter allen Weisen der Nationen und in allen ihren Königreichen ist gar niemand dir gleich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'sondern sie sind allzumal dumm und töricht; die Unterweisung der Nichtigkeiten ist Holz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Dünngeschlagenes Silber wird aus Tarsis gebracht und Gold aus Uphas, ein Werk des Künstlers und der Hände des Goldschmieds; blauer und roter Purpur ist ihr Gewand, ein Werk von Kunstfertigen sind sie allesamt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Aber Jehova, Gott, ist Wahrheit; er ist der lebendige Gott und ein ewiger König. Vor seinem Grimm erbebt die Erde, und seinen Zorn können die Nationen nicht ertragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'So sollt ihr zu ihnen sprechen: Die Götter, die den Himmel und die Erde nicht gemacht haben, diese werden verschwinden von der Erde und unter diesem Himmel hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Er hat die Erde gemacht durch seine Kraft, den Erdkreis festgestellt durch seine Weisheit und die Himmel ausgespannt durch seine Einsicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Wenn er beim Schalle des Donners Wasserrauschen am Himmel bewirkt und Dünste aufsteigen läßt vom Ende der Erde, Blitze zum Regen macht und den Wind herausführt aus seinen Vorratskammern: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Dumm wird jeder Mensch, ohne Erkenntnis; beschämt wird jeder Goldschmied über das Götzenbild; denn sein gegossenes Bild ist Lüge, und kein Geist ist in ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Nichtigkeit sind sie, ein Werk des Gespöttes: Zur Zeit ihrer Heimsuchung gehen sie zu Grunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Jakobs Teil ist nicht wie diese; denn er ist es, der das All gebildet hat, und Israel ist der Stamm seines Erbteils; Jehova der Heerscharen ist sein Name.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Raffe dein Gepäck zusammen aus dem Lande, du Bewohnerin der Festung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Denn so spricht Jehova: Siehe, ich werde diesmal die Bewohner des Landes hinwegschleudern und sie ängstigen, damit sie sie finden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Wehe mir ob meiner Wunde! Schmerzlich ist mein Schlag. Doch ich spreche: Ja, das ist mein Leiden, und ich will es tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Mein Zelt ist zerstört, und alle meine Seile sind zerrissen; meine Kinder sind von mir weggezogen und sind nicht mehr. Da ist niemand, der ferner mein Zelt ausspannt und meine Zeltbehänge aufrichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Denn die Hirten sind dumm geworden und haben Jehova nicht gesucht; darum haben sie nicht verständig gehandelt, und ihre ganze Herde hat sich zerstreut. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Horch! Ein Gerücht: Siehe, es kommt, und dein großes Getöse vom Lande des Nordens, um die Städte Judas zur Wüste zu machen, zur Wohnung der Schakale. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Ich weiß, Jehova, daß nicht beim Menschen sein Weg steht, nicht bei dem Manne, der da wandelt, seinen Gang zu richten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Züchtige mich, Jehova, doch nach Gebühr; nicht in deinem Zorne, daß du mich nicht aufreibest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Ergieße deinen Grimm über die Nationen, die dich nicht kennen, und über die Geschlechter, die deinen Namen nicht anrufen! Denn sie haben Jakob aufgezehrt, ja, sie haben ihn aufgezehrt und ihn vernichtet und seine Wohnung verwüstet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Das Wort, welches von seiten Jehovas zu Jeremia geschah, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Höret auf die Worte dieses Bundes und redet zu den Männern von Juda und zu den Bewohnern von Jerusalem!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Und du, sprich zu ihnen: So spricht Jehova, der Gott Israels: Verflucht sei der Mann, der nicht hört auf die Worte dieses Bundes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'welchen ich euren Vätern geboten habe an dem Tage, da ich sie herausführte aus dem Lande Ägypten, aus dem eisernen Schmelzofen, indem ich sprach: Höret auf meine Stimme und tut diese Worte, nach allem, was ich euch gebiete, so werdet ihr mein Volk, und ich werde euer Gott sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'auf daß ich den Eid aufrecht halte, den ich euren Vätern geschworen habe, ihnen ein Land zu geben, das von Milch und Honig fließt, wie es an diesem Tage ist. Und ich antwortete und sprach: Amen, Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Und Jehova sprach zu mir: Rufe alle diese Worte aus in den Städten Judas und auf den Straßen von Jerusalem, und sprich: Höret die Worte dieses Bundes und tut sie!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Denn ich habe euren Vätern ernstlich bezeugt an dem Tage, da ich sie aus dem Lande Ägypten heraufführte, bis auf diesen Tag, früh mich aufmachend und bezeugend, indem ich sprach: Höret auf meine Stimme!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Aber sie haben nicht gehört und ihr Ohr nicht geneigt, sondern sie wandelten ein jeder in dem Starrsinn ihres bösen Herzens. Und ich brachte über sie alle Worte dieses Bundes, welche ich zu tun geboten, und die sie nicht getan haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Und Jehova sprach zu mir: Es hat sich eine Verschwörung gefunden unter den Männern von Juda und unter den Bewohnern von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Sie sind zurückgekehrt zu den Missetaten ihrer ersten Väter, die sich geweigert haben, auf meine Worte zu hören; und sie selbst sind anderen Göttern nachgegangen, um ihnen zu dienen. Das Haus Israel und das Haus Juda haben meinen Bund gebrochen, den ich mit ihren Vätern gemacht habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Darum, so spricht Jehova: Siehe, ich bringe über sie ein Unglück, dem sie nicht werden entgehen können; und sie werden zu mir schreien, aber ich werde nicht auf sie hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Und die Städte von Juda und die Bewohner von Jerusalem werden hingehen und zu den Göttern schreien, welchen sie geräuchert haben; aber retten werden diese sie nicht zur Zeit ihres Unglücks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Denn so zahlreich wie deine Städte sind deine Götter geworden, Juda; und nach der Zahl der Straßen von Jerusalem habt ihr der Schande Altäre gesetzt, Altäre, um dem Baal zu räuchern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Du aber, bitte nicht für dieses Volk und erhebe weder Flehen noch Gebet für sie; denn ich werde nicht hören zu der Zeit, da sie wegen ihres Unglücks zu mir rufen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Was hat mein Geliebter in meinem Hause zu schaffen, da die Vielen Arglist üben? Wird heiliges Fleisch deine Bosheit von dir wegnehmen? Dann mögest du frohlocken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Einen grünen Olivenbaum, schön an herrlicher Frucht, hatte Jehova dich genannt; bei dem Lärm eines großen Getümmels legte er Feuer an ihn, und es brachen seine Äste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Und Jehova der Heerscharen, der dich gepflanzt, hat Böses über dich geredet wegen der Bosheit des Hauses Israel und des Hauses Juda, die sie verübt haben, um mich zu reizen, indem sie dem Baal räucherten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Und Jehova hat es mir kundgetan, und ich erfuhr es; damals zeigtest du mir ihre Handlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Und ich war wie ein zahmes Lamm, das zum Schlachten geführt wird; und ich wußte nicht, daß sie Anschläge wider mich ersannen: \"Laßt uns den Baum mit seiner Frucht verderben und ihn aus dem Lande der Lebendigen ausrotten, daß seines Namens nicht mehr gedacht werde!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Aber du, Jehova der Heerscharen, der du gerecht richtest, Nieren und Herz prüfst, laß mich deine Rache an ihnen sehen; denn dir habe ich meine Rechtssache anvertraut. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Darum, so spricht Jehova über die Männer von Anathoth, welche nach deinem Leben trachten und sprechen: Du sollst nicht weissagen im Namen Jehovas, damit du nicht durch unsere Hände sterbest-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'darum, so spricht Jehova der Heerscharen: Siehe, ich suche sie heim; die Jünglinge werden durchs Schwert sterben, ihre Söhne und ihre Töchter werden vor Hunger sterben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'und sie werden keinen Überrest haben; denn ich bringe Unglück über die Männer von Anathoth, das Jahr ihrer Heimsuchung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Du bist gerecht, Jehova, wenn ich mit dir hadere; doch von deinen Urteilen möchte ich mit dir reden: Warum ist der Weg der Gesetzlosen glücklich, sind sicher alle, die Treulosigkeit üben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Du hast sie gepflanzt, sie haben auch Wurzel geschlagen; sie kommen vorwärts, tragen auch Frucht. Du bist nahe in ihrem Munde, doch fern von ihren Nieren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Du aber, Jehova, du kennst mich, du siehst mich und prüfst mein Herz gegen dich. Reiße sie hinweg wie Schafe zur Schlachtung, und weihe sie für den Tag des Würgens!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Wie lange soll das Land trauern und das Kraut des ganzen Feldes welken? Wegen der Bosheit seiner Bewohner sind Vieh und Gevögel dahin; denn sie sprechen: Er wird unser Ende nicht sehen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Wenn du mit Fußgängern liefest, und sie dich ermüdeten, wie wolltest du denn mit Rossen wetteifern? Und wenn du auf ein Land des Friedens dein Vertrauen setzest, wie willst du es denn machen in der Pracht des Jordan?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Denn auch deine Brüder und deines Vaters Haus, auch sie sind treulos gegen dich, auch sie rufen dir nach aus voller Kehle. Glaube ihnen nicht, wenn sie freundlich mit dir reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Ich habe mein Haus verlassen, mein Erbteil verstoßen, ich habe den Liebling meiner Seele in die Hand seiner Feinde gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Mein Erbteil ist mir geworden wie ein Löwe im Walde; es hat seine Stimme gegen mich erhoben, darum habe ich es gehaßt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Ist mir mein Erbteil ein bunter Raubvogel, daß Raubvögel rings um dasselbe her sind? Auf! Versammelt alle Tiere des Feldes, bringet sie zum Fraße herbei!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Viele Hirten haben meinen Weinberg verderbt, mein Ackerstück zertreten; sie haben mein köstliches Ackerstück zur öden Wüste gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Man hat es zur Öde gemacht: Verwüstet trauert es um mich her. Das ganze Land ist verwüstet, weil niemand es zu Herzen nahm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Über alle kahlen Höhen in der Steppe sind Verwüster gekommen; denn ein Schwert von Jehova frißt von einem Ende des Landes bis zum anderen Ende des Landes: Kein Friede allem Fleische!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Sie haben Weizen gesät und Dornen geerntet; sie haben sich erschöpft und nichts ausgerichtet. So werdet zu Schanden an euren Erträgen vor der Glut des Zornes Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'So spricht Jehova über alle meine bösen Nachbarn, welche das Erbteil antasten, das ich mein Volk Israel habe erben lassen: Siehe, ich werde sie aus ihrem Lande herausreißen, und das Haus Juda werde ich aus ihrer Mitte reißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Und es soll geschehen, nachdem ich sie herausgerissen habe, werde ich mich ihrer wieder erbarmen und sie zurückbringen, einen jeden in sein Erbteil und einen jeden in sein Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Und es soll geschehen, wenn sie die Wege meines Volkes wirklich lernen, so daß sie bei meinem Namen schwören: So wahr Jehova lebt! Gleichwie sie mein Volk gelehrt haben, bei dem Baal zu schwören, so sollen sie inmitten meines Volkes aufgebaut werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Wenn sie aber nicht hören, so werde ich selbige Nation ausreißen, ausreißen und vertilgen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'So hat Jehova zu mir gesprochen: Geh und kaufe dir einen leinenen Gürtel und lege ihn um deine Lenden; aber ins Wasser sollst du ihn nicht bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Und ich kaufte den Gürtel, nach dem Worte Jehovas, und legte ihn um meine Lenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Und das Wort Jehovas geschah zum zweiten Male zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Nimm den Gürtel, den du gekauft hast, der um deine Lenden ist, und mache dich auf, geh an den Euphrat und verbirg ihn daselbst in einer Felsenspalte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Da ging ich hin und verbarg ihn am Euphrat, wie Jehova mir geboten hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Und es geschah am Ende vieler Tage, da sprach Jehova zu mir: Mache dich auf, geh an den Euphrat und hole von dort den Gürtel, den ich dir geboten habe daselbst zu verbergen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Und ich ging an den Euphrat und grub, und nahm den Gürtel von dem Orte, wo ich ihn verborgen hatte; und siehe, der Gürtel war verdorben, taugte zu gar nichts mehr. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'So spricht Jehova: Also werde ich verderben die Hoffart Judas und die große Hoffart Jerusalems.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Dieses böse Volk, das sich weigert meine Worte zu hören, das da wandelt in dem Starrsinn seines Herzens, und anderen Göttern nachgeht, um ihnen zu dienen und sich vor ihnen niederzubeugen: Es soll werden wie dieser Gürtel, der zu gar nichts taugt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Denn gleichwie der Gürtel sich an die Lenden eines Mannes anschließt, so habe ich das ganze Haus Israel und das ganze Haus Juda an mich geschlossen, spricht Jehova, damit sie mir zum Volk und zum Namen und zum Ruhm und zum Schmuck seien; aber sie haben nicht gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Und sprich dieses Wort zu ihnen: So spricht Jehova, der Gott Israels: Jeder Krug wird mit Wein gefüllt. Und wenn sie zu dir sagen: Wissen wir nicht sehr wohl, daß jeder Krug mit Wein gefüllt wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'so sprich zu ihnen: Also spricht Jehova: Siehe, ich werde alle Bewohner dieses Landes, und die Könige, die auf dem Throne Davids sitzen, und die Priester und die Propheten und alle Bewohner von Jerusalem mit Trunkenheit erfüllen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Und ich werde sie zerschmettern einen gegen den anderen, die Väter und die Kinder allzumal, spricht Jehova; ich werde nicht Mitleid haben, noch schonen, noch mich erbarmen, daß ich sie nicht verderbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Höret und nehmet zu Ohren, überhebet euch nicht! Denn Jehova hat geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Gebet Jehova, eurem Gott, Ehre, bevor er finster macht, und bevor eure Füße sich an Bergen der Dämmerung stoßen, und ihr auf Licht wartet, und er es in Todesschatten verwandelt und zur Dunkelheit macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Wenn ihr aber nicht höret, so wird meine Seele im Verborgenen weinen wegen eures Hochmuts; und tränen wird mein Auge und von Tränen rinnen, weil die Herde Jehovas gefangen weggeführt ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Sprich zu dem König und zu der Königin: Setzet euch tief herunter; denn von euren Häuptern ist herabgesunken die Krone eurer Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Die Städte des Südens sind verschlossen, und niemand öffnet; Juda ist weggeführt insgesamt, ist gänzlich weggeführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Hebet eure Augen auf und sehet die von Norden Kommenden! Wo ist die Herde, die dir gegeben war, deine herrliche Herde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Was willst du sagen, wenn er die zum Haupte über dich bestellt, welche du als Vertraute an dich gewöhnt hast? Werden nicht Wehen dich ergreifen, einer Gebärenden gleich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Und wenn du in deinem Herzen sprichst: Warum ist mir dieses begegnet? Um der Größe deiner Ungerechtigkeit willen sind deine Säume aufgedeckt und haben deine Fersen Gewalt gelitten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Kann ein Mohr seine Haut wandeln, ein Pardel seine Flecken? Dann könntet auch ihr Gutes tun, die ihr an Bösestun gewöhnt seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Darum werde ich sie zerstreuen wie Stoppeln, welche durch den Wind der Wüste dahinfahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Das ist dein Los, dein von mir zugemessenes Teil, spricht Jehova, weil du meiner vergessen und auf Lüge vertraut hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Und so werde auch ich deine Säume aufstreifen über dein Angesicht, daß deine Schande gesehen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Dein Ehebrechen und dein Wiehern, die Schandtat deiner Hurerei auf den Hügeln im Felde: Deine Greuel habe ich gesehen. Wehe dir, Jerusalem! Du wirst nicht rein werden, wie lange wird\'s noch währen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Das Wort Jehovas, welches zu Jeremia geschah betreffs der Dürre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Juda trauert, und seine Tore schmachten, liegen in Trauer am Boden, und Jerusalems Klagegeschrei steigt empor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Und seine Vornehmen schicken seine Geringen nach Wasser; sie kommen zu den Zisternen, finden kein Wasser, sie kommen leer zurück mit ihren Gefäßen; sie sind beschämt und mit Scham bedeckt und verhüllen ihr Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Wegen des Erdbodens, der bestürzt ist, weil kein Regen im Lande war, sind die Ackerleute beschämt, verhüllen ihr Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Ja, auch die Hindin auf dem Felde, sie gebiert und verläßt ihre Jungen; denn kein Gras ist da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Und die Wildesel stehen auf den kahlen Höhen, schnappen nach Luft wie die Schakale; ihre Augen schmachten hin, denn kein Kraut ist da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Wenn unsere Missetaten wider uns zeugen, Jehova, so handle um deines Namens willen; denn viele sind unserer Abtrünnigkeiten, gegen dich haben wir gesündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Du Hoffnung Israels, sein Retter in der Zeit der Bedrängnis, warum willst du sein wie ein Fremdling im Lande, und wie ein Wanderer, der zum Übernachten eingekehrt ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Warum willst du sein wie ein bestürzter Mann, wie ein Held, der nicht zu retten vermag? Du bist doch in unserer Mitte, Jehova, und wir sind nach deinem Namen genannt; verlaß uns nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'So spricht Jehova zu diesem Volke: Also haben sie geliebt umherzuschweifen, sie hielten ihre Füße nicht zurück; und Jehova hat kein Wohlgefallen an ihnen: Nun wird er ihrer Missetaten gedenken und ihre Sünden heimsuchen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Und Jehova sprach zu mir: Bitte nicht für dieses Volk zum Guten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Wenn sie fasten, werde ich nicht auf ihr Flehen hören; und wenn sie Brandopfer und Speisopfer opfern, werde ich kein Wohlgefallen an ihnen haben; sondern ich werde sie durch das Schwert und durch den Hunger und durch die Pest vernichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Und ich sprach: Ach, Herr, Jehova! Siehe, die Propheten sprechen zu ihnen: Ihr werdet kein Schwert sehen, und Hunger wird euch nicht treffen, sondern ich werde euch einen sicheren Frieden geben an diesem Orte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Und Jehova sprach zu mir: Die Propheten weissagen Lüge in meinem Namen; ich habe sie nicht gesandt und sie nicht entboten, noch zu ihnen geredet; sie weissagen euch Lügengesicht und Wahrsagung und Nichtigkeit und Trug ihres Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Darum spricht Jehova also über die Propheten, welche in meinem Namen weissagen, und ich habe sie doch nicht gesandt, und die da sprechen: Weder Schwert noch Hunger wird in diesem Lande sein: Die Propheten sollen durch das Schwert und durch den Hunger aufgerieben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Und das Volk, welchem sie weissagen, soll wegen des Hungers und des Schwertes hingeworfen liegen auf den Straßen von Jerusalem; und niemand wird sie begraben, sie, ihre Weiber und ihre Söhne und ihre Töchter; und ich werde ihre Bosheit über sie ausschütten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Und du sollst dieses Wort zu ihnen sprechen: Nacht und Tag rinnen meine Augen von Tränen und hören nicht auf; denn die Jungfrau, die Tochter meines Volkes, ist mit großer Zerschmetterung, mit einem sehr schmerzlichen Schlage zerschmettert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Wenn ich aufs Feld hinausgehe, siehe da, vom Schwert Erschlagene; und wenn ich in die Stadt komme, siehe da, vor Hunger Verschmachtende. Denn sowohl Propheten als Priester ziehen im Lande umher und wissen nicht Rat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Hast du Juda gänzlich verworfen? Oder verabscheut deine Seele Zion? Warum hast du uns geschlagen, daß keine Heilung für uns ist? Man hofft auf Frieden, und da ist nichts Gutes, und auf die Zeit der Heilung, und siehe da, Schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Jehova, wir kennen unsere Gesetzlosigkeit, die Ungerechtigkeit unserer Väter; denn wir haben gegen dich gesündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Verschmähe uns nicht um deines Namens willen, entehre nicht den Thron deiner Herrlichkeit; gedenke, brich nicht deinen Bund mit uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Gibt es unter den Nichtigkeiten der Nationen Regenspender, oder kann der Himmel Regengüsse geben? Bist du es nicht, Jehova, unser Gott? Und wir hoffen auf dich; denn du, du hast dieses alles gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Und Jehova sprach zu mir: Wenn auch Mose und Samuel vor mir ständen, so würde meine Seele sich nicht zu diesem Volke wenden. Treibe sie von meinem Angesicht hinweg, daß sie fortgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Und es soll geschehen, wenn sie zu dir sagen: Wohin sollen wir fortgehen? So sage ihnen: So spricht Jehova: Wer zum Tode bestimmt ist, gehe zum Tode; und wer zum Schwerte, zum Schwerte; und wer zum Hunger, zum Hunger; und wer zur Gefangenschaft, zur Gefangenschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Denn ich bestelle über sie vier Arten von Übeln, spricht Jehova: Das Schwert zum Würgen, und die Hunde zum Zerren, und das Gevögel des Himmels und die Tiere der Erde zum Fressen und zum Vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Und ich will sie zur Mißhandlung hingeben allen Königreichen der Erde, um Manasses willen, des Sohnes Hiskias, des Königs von Juda, wegen dessen, was er in Jerusalem getan hat. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Denn wer wird sich über dich erbarmen, Jerusalem, und wer dir Beileid bezeigen, und wer wird einkehren, um nach deinem Wohlergehen zu fragen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Du hast mich verstoßen, spricht Jehova, du gingst rückwärts; und so werde ich meine Hand wider dich ausstrecken und dich verderben; ich bin des Bereuens müde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Und ich werde sie mit der Worfschaufel zu den Toren des Landes hinausworfeln; ich werde mein Volk der Kinder berauben, es zu Grunde richten. Sie sind von ihren Wegen nicht umgekehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Ihre Witwen werden mir zahlreicher sein als der Sand der Meere; ich bringe ihnen über die Mütter der Jünglinge einen Verwüster am hellen Mittag, lasse plötzlich Angst und Schrecken auf sie fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Die sieben gebar, verschmachtet, sie haucht ihre Seele aus; ihre Sonne ist untergegangen, als es noch Tag war; sie ist beschämt und zu Schanden geworden. Und ihren Überrest werde ich dem Schwerte hingeben angesichts ihrer Feinde, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, '\"Wehe mir, meine Mutter, daß du mich geboren hast, einen Mann des Haders und einen Mann des Zankes für das ganze Land! Ich habe nicht ausgeliehen, und man hat mir nicht geliehen; alle fluchen mir.\" -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Jehova spricht: Wenn ich dich nicht zum Guten stärken, wenn ich nicht machen werde, daß zur Zeit des Unglücks und zur Zeit der Bedrängnis der Feind dich bittend angeht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Kann man Eisen, Eisen aus Norden, und Erz zerbrechen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Dein Vermögen und deine Schätze will ich zur Beute geben ohne Kaufpreis, und zwar wegen all deiner Sünden und in allen deinen Grenzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Und ich werde es deine Feinde in ein Land bringen lassen, das du nicht kennst; denn ein Feuer ist entbrannt in meinem Zorn, über euch wird es brennen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Jehova, du weißt es ja; gedenke meiner und nimm dich meiner an und räche mich an meinen Verfolgern! Raffe mich nicht hin nach deiner Langmut; erkenne, daß ich um deinetwillen Schmach trage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Deine Worte waren vorhanden, und ich habe sie gegessen, und deine Worte waren mir zur Wonne und zur Freude meines Herzens; denn ich bin nach deinem Namen genannt, Jehova, Gott der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Ich saß nicht im Kreise der Scherzenden und frohlockte; wegen deiner Hand saß ich allein, weil du mit deinem Grimm mich erfüllt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Warum ist mein Schmerz beständig und mein Schlag tödlich? Er will nicht heilen. Willst du mir wirklich wie ein trügerischer Bach sein, wie Wasser, die versiegen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Darum spricht Jehova also: Wenn du umkehrst, so will ich dich zurückbringen, daß du vor mir stehest; und wenn du das Köstliche vom Gemeinen ausscheidest, so sollst du wie mein Mund sein. Jene sollen zu dir umkehren, du aber sollst nicht zu ihnen umkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Und ich werde dich diesem Volke zu einer festen ehernen Mauer machen, und sie werden wider dich streiten, aber dich nicht überwältigen; denn ich bin mit dir, um dich zu retten und dich zu befreien, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Und ich werde dich befreien aus der Hand der Bösen und dich erlösen aus der Faust der Gewalttätigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Du sollst dir kein Weib nehmen, und weder Söhne noch Töchter haben an diesem Orte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Denn so spricht Jehova über die Söhne und über die Töchter, welche an diesem Orte geboren werden, und über ihre Mütter, die sie gebären, und über ihre Väter, die sie zeugen in diesem Lande:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Sie sollen an schmerzlichen Krankheiten sterben, sie sollen nicht beklagt noch begraben werden, zu Dünger auf der Fläche des Erdbodens sollen sie werden; und durch Schwert und durch Hunger sollen sie vernichtet werden, und ihre Leichname sollen dem Gevögel des Himmels und den Tieren der Erde zur Speise dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Denn so spricht Jehova: Geh nicht in ein Haus der Klage, und geh nicht hin, um zu trauern, und bezeige ihnen kein Beileid; denn ich habe meinen Frieden von diesem Volke weggenommen, spricht Jehova, die Gnade und die Barmherzigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Und Große und Kleine werden in diesem Lande sterben, ohne begraben zu werden; und man wird nicht um sie trauern, und sich nicht ritzen und sich nicht kahl scheren ihretwegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Und man wird ihnen nicht Brot brechen bei der Trauer, um jemand zu trösten über den Toten, noch ihnen zu trinken geben aus dem Becher des Trostes über jemandes Vater und über jemandes Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Auch in ein Haus des Gastmahls sollst du nicht gehen, bei ihnen zu sitzen, um zu essen und zu trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Denn so spricht Jehova der Heerscharen, der Gott Israels: Siehe, ich werde an diesem Orte vor euren Augen und in euren Tagen aufhören lassen die Stimme der Wonne und die Stimme der Freude, die Stimme des Bräutigams und die Stimme der Braut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Und es soll geschehen, wenn du diesem Volke alle diese Worte verkünden wirst, und sie zu dir sprechen: Warum hat Jehova all dieses große Unglück über uns geredet? Und was ist unsere Missetat, und was unsere Sünde, die wir gegen Jehova, unseren Gott, begangen haben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'So sollst du zu ihnen sprechen: Darum, daß eure Väter mich verlassen haben, spricht Jehova, und anderen Göttern nachgegangen sind, und ihnen gedient und sich vor ihnen niedergebeugt, mich aber verlassen und mein Gesetz nicht beobachtet haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'und ihr es ärger getrieben habt als eure Väter, und siehe, ihr gehet ein jeder dem Starrsinn seines bösen Herzens nach, so daß ihr nicht auf mich höret: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'So werde ich euch aus diesem Lande wegschleudern in ein Land, welches ihr nicht gekannt habt, weder ihr noch eure Väter; und daselbst werdet ihr anderen Göttern dienen Tag und Nacht, weil ich euch keine Gnade schenken werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Darum siehe, Tage kommen, spricht Jehova, da nicht mehr gesagt werden wird: So wahr Jehova lebt, der die Kinder Israel aus dem Lande Ägypten heraufgeführt hat! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'sondern: So wahr Jehova lebt, der die Kinder Israel heraufgeführt hat aus dem Lande des Nordens und aus all den Ländern, wohin er sie vertrieben hatte! Und ich werde sie in ihr Land zurückbringen, das ich ihren Vätern gegeben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Siehe, ich will zu vielen Fischern senden, spricht Jehova, daß sie sie fischen; und danach will ich zu vielen Jägern senden, daß sie sie jagen von jedem Berge und von jedem Hügel und aus den Felsenklüften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Denn meine Augen sind auf alle ihre Wege gerichtet; sie sind vor mir nicht verborgen, und ihre Ungerechtigkeit ist nicht verhüllt vor meinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Und zuvor will ich zweifach vergelten ihre Ungerechtigkeit und ihre Sünde, weil sie mein Land mit den Leichen ihrer Scheusale entweiht und mein Erbteil mit ihren Greueln erfüllt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Jehova, meine Stärke und mein Hort, und meine Zuflucht am Tage der Bedrängnis! Zu dir werden Nationen kommen von den Enden der Erde und sprechen: Nur Lüge haben unsere Väter ererbt, nichtige Götter; und unter ihnen ist keiner, der etwas nützt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Soll ein Mensch sich Götter machen, die doch keine Götter sind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Darum siehe, dieses Mal werde ich ihnen kundtun, werde ihnen kundtun meine Hand und meine Macht; und sie werden wissen, daß mein Name Jehova ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Die Sünde Judas ist geschrieben mit eisernem Griffel, mit diamantener Spitze; sie ist eingegraben in die Tafel ihres Herzens und an die Hörner eurer Altäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Wie ihrer Kinder, so gedenken sie ihrer Altäre und ihrer Ascherim bei den grünen Bäumen, auf den hohen Hügeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Meinen Berg im Gefilde, dein Vermögen, alle deine Schätze werde ich zur Beute geben, deine Höhen, um der Sünde willen in allen deinen Grenzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Und du wirst, und zwar durch dich selbst, dein Erbteil fahren lassen müssen, welches ich dir gegeben habe, und ich werde dich deinen Feinden dienen lassen in einem Lande, das du nicht kennst; denn ihr habt ein Feuer angezündet in meinem Zorn, es wird ewiglich brennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'So spricht Jehova: Verflucht ist der Mann, der auf den Menschen vertraut und Fleisch zu seinem Arme macht, und dessen Herz von Jehova weicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Und er wird sein wie ein Entblößter in der Steppe und nicht sehen, daß Gutes kommt; und an dürren Örtern in der Wüste wird er wohnen, in einem salzigen und unbewohnten Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Gesegnet ist der Mann, der auf Jehova vertraut und dessen Vertrauen Jehova ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Und er wird sein wie ein Baum, der am Wasser gepflanzt ist und am Bache seine Wurzeln ausstreckt, und sich nicht fürchtet, wenn die Hitze kommt; und sein Laub ist grün, und im Jahre der Dürre ist er unbekümmert, und er hört nicht auf, Frucht zu tragen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Arglistig ist das Herz, mehr als alles, und verderbt ist es; wer mag es kennen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Ich, Jehova, erforsche das Herz und prüfe die Nieren, und zwar um einem jeden zu geben nach seinen Wegen, nach der Frucht seiner Handlungen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Ein Rebhuhn, das Eier brütet, die es nicht gelegt hat, so ist, wer Reichtum erwirbt und nicht mit Recht: In der Hälfte seiner Tage wird er ihn verlassen, und an seinem Ende wird er ein Tor sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Thron der Herrlichkeit, Höhe von Anbeginn, du Ort unseres Heiligtums!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Hoffnung Israels, Jehova! Alle, die dich verlassen, werden beschämt werden. Und die von mir weichen, werden in die Erde geschrieben werden; denn sie haben den Born lebendigen Wassers, Jehova, verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Heile mich, Jehova, so werde ich geheilt werden; rette mich, so werde ich gerettet werden; denn du bist mein Ruhm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Siehe, jene sprechen zu mir: Wo ist das Wort Jehovas? Es möge doch kommen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Ich aber habe mich nicht entzogen, Hirte hinter dir her zu sein, und habe den unheilvollen Tag nicht herbeigewünscht; du weißt es ja. Was aus meinen Lippen hervorging, war vor deinem Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Sei mir nicht zum Schrecken, du bist meine Zuflucht am Tage des Unglücks!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Laß meine Verfolger beschämt werden, aber laß mich nicht beschämt werden, laß sie verzagt werden, aber laß mich nicht verzagt werden; bringe über sie den Tag des Unglücks, und zerschmettere sie mit zweifacher Zerschmetterung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'So spricht Jehova zu mir: Geh hin und stelle dich in das Tor der Kinder des Volkes, durch welches die Könige von Juda einziehen und durch welches sie ausziehen, und in alle Tore Jerusalems, und sprich zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Höret das Wort Jehovas, ihr Könige von Juda, und ganz Juda und alle Bewohner von Jerusalem, die ihr durch diese Tore einziehet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'So spricht Jehova: Hütet euch bei euren Seelen, und traget keine Last am Sabbathtage, daß ihr sie durch die Tore Jerusalems hereinbringet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Und ihr sollt am Sabbathtage keine Last aus euren Häusern hinausbringen, und sollt keinerlei Arbeit tun; sondern heiliget den Sabbathtag, wie ich euren Vätern geboten habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Aber sie haben nicht gehört und ihr Ohr nicht geneigt, und sie haben ihren Nacken verhärtet, um nicht zu hören und Zucht nicht anzunehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Und es wird geschehen, wenn ihr fleißig auf mich höret, spricht Jehova, daß ihr am Sabbathtage keine Last durch die Tore dieser Stadt hereinbringet, und daß ihr den Sabbathtag heiliget, indem ihr keinerlei Arbeit an demselben tut:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'so werden durch die Tore dieser Stadt Könige und Fürsten einziehen, welche auf dem Throne Davids sitzen, auf Wagen fahrend und auf Rossen reitend, sie und ihre Fürsten, die Männer von Juda und die Bewohner von Jerusalem; und diese Stadt wird bewohnt werden ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Und sie werden aus den Städten Judas kommen und aus den Umgebungen von Jerusalem und aus dem Lande Benjamin, und aus der Niederung und vom Gebirge und aus dem Süden, indem sie Brandopfer und Schlachtopfer und Speisopfer und Weihrauch bringen, und Lob bringen in das Haus Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Wenn ihr aber nicht auf mich höret, den Sabbathtag zu heiligen und keine Last zu tragen, und nicht durch die Tore Jerusalems einzugehen am Sabbathtage: so werde ich ein Feuer in seinen Toren anzünden, daß es die Paläste Jerusalems verzehren und nicht erlöschen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Das Wort, welches von seiten Jehovas zu Jeremia geschah, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Mache dich auf und geh in das Haus des Töpfers hinab, und daselbst werde ich dich meine Worte hören lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Und ich ging in das Haus des Töpfers hinab, und siehe, er machte eine Arbeit auf der Scheibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Und das Gefäß, das er aus dem Ton machte, mißriet in der Hand des Töpfers; und er machte wiederum ein anderes Gefäß daraus, wie es zu machen den Töpfer gut dünkte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Vermag ich euch nicht zu tun wie dieser Töpfer, Haus Israel? spricht Jehova; siehe, wie der Ton in der Hand des Töpfers, also seid ihr in meiner Hand, Haus Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Einmal rede ich über ein Volk und über ein Königreich, es auszureißen und abzubrechen und zu zerstören;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'kehrt aber jenes Volk, über welches ich geredet habe, von seiner Bosheit um, so lasse ich mich des Übels gereuen, das ich ihm zu tun gedachte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Und ein anderes Mal rede ich über ein Volk und über ein Königreich, es zu bauen und zu pflanzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'tut es aber, was böse ist in meinen Augen, so daß es auf meine Stimme nicht hört, so lasse ich mich des Guten gereuen, das ich ihm zu erweisen gesagt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Und nun rede zu den Männern von Juda und zu den Bewohnern von Jerusalem und sage: So spricht Jehova: Siehe, ich bereite ein Unglück wider euch und sinne wider euch einen Anschlag; kehret doch um, ein jeder von seinem bösen Wege, und machet gut eure Wege und eure Handlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Aber sie sagen: Es ist umsonst; denn unseren Gedanken wollen wir nachgehen und ein jeder nach dem Starrsinn seines bösen Herzens tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Darum, so spricht Jehova: Fraget doch unter den Nationen! Wer hat dergleichen gehört? Gar Schauderhaftes hat die Jungfrau Israel getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Verläßt wohl der Schnee des Libanon den Fels des Gefildes? Oder versiegen weither kommende, kalte, rieselnde Wasser?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Denn mein Volk hat mich vergessen, sie räuchern den nichtigen Götzen; und diese haben sie straucheln gemacht auf ihren Wegen, den Pfaden der Vorzeit, um Steige zu gehen, einen Weg, der nicht gebahnt ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'damit sie ihr Land zum Entsetzen machen, zu ewigem Gezisch: Jeder, der an demselben vorüberzieht, wird sich entsetzen und den Kopf schütteln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Wie der Ostwind werde ich sie vor dem Feinde zerstreuen; mit dem Rücken und nicht mit dem Angesicht werde ich sie ansehen an dem Tage ihres Verderbens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Da sprachen sie: Kommt und laßt uns Anschläge wider Jeremia ersinnen; denn nicht geht dem Priester das Gesetz verloren, noch der Rat dem Weisen und das Wort dem Propheten. Kommt und laßt uns ihn mit der Zunge schlagen und nicht aufmerken auf alle seine Worte! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Merke du, Jehova, auf mich, und höre die Stimme meiner Gegner!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Soll Böses für Gutes vergolten werden? Denn sie haben meiner Seele eine Grube gegraben. Gedenke, daß ich vor dir gestanden habe, Gutes über sie zu reden, um deinen Grimm von ihnen abzuwenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Darum übergib ihre Kinder dem Hunger, und gib sie preis der Gewalt des Schwertes, damit ihre Weiber kinderlos und Witwen werden, und ihre Männer vom Tode erwürgt, ihre Jünglinge vom Schwerte erschlagen werden im Kriege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Es erschalle ein Geschrei aus ihren Häusern, wenn du plötzlich Kriegsscharen über sie bringst; denn sie haben eine Grube gegraben, um mich zu fangen, und meinen Füßen haben sie heimlich Schlingen gelegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Und du, Jehova, du kennst alle ihre Mordanschläge wider mich; vergib nicht ihre Missetat, und tilge ihre Sünde nicht aus vor deinem Angesicht, sondern laß sie niedergestürzt vor dir liegen; zur Zeit deines Zornes handle mit ihnen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'So sprach Jehova: Geh und kaufe einen irdenen Krug, und nimm mit dir von den Ältesten des Volkes und von den Ältesten der Priester;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'und geh hinaus in das Tal des Sohnes Hinnoms, welches vor dem Eingang des Tores Charsuth liegt, und rufe daselbst die Worte aus, die ich zu dir reden werde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'und sprich: Höret das Wort Jehovas, ihr Könige von Juda und ihr Bewohner von Jerusalem! So spricht Jehova der Heerscharen, der Gott Israels: Siehe, ich bringe Unglück über diesen Ort, daß einem jeden, der es hört, seine Ohren gellen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Darum, daß sie mich verlassen und diesen Ort verkannt und in ihm anderen Göttern geräuchert haben, die sie nicht kannten, weder sie noch ihre Väter noch die Könige von Juda, und diesen Ort mit dem Blute Unschuldiger erfüllt haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'und die Höhen des Baal gebaut, um ihre Kinder als Brandopfer für den Baal im Feuer zu verbrennen, was ich nicht geboten noch geredet habe und mir nicht in den Sinn gekommen ist:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Darum siehe, Tage kommen, spricht Jehova, da dieser Ort nicht mehr Topheth, noch Tal des Sohnes Hinnoms, sondern Würgetal genannt werden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Und ich werde den Rat von Juda und Jerusalem vereiteln an diesem Orte, und werde sie durchs Schwert fallen lassen vor ihren Feinden und durch die Hand derer, welche nach ihrem Leben trachten; und ich werde ihre Leichname dem Gevögel des Himmels und den Tieren der Erde zur Speise geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Und ich werde diese Stadt zum Entsetzen und zum Gezisch machen: Jeder, der an ihr vorüberzieht, wird sich entsetzen und zischen über alle ihre Plagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Und ich werde sie das Fleisch ihrer Söhne und das Fleisch ihrer Töchter essen lassen, und sie sollen einer des anderen Fleisch essen in der Belagerung und in der Bedrängnis, womit ihre Feinde und die nach ihrem Leben trachten sie bedrängen werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Und du sollst den Krug zerbrechen vor den Augen der Männer, die mit dir gegangen sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'und zu ihnen sprechen: So spricht Jehova der Heerscharen: Also werde ich dieses Volk und diese Stadt zerschmettern, wie man ein Töpfergefäß zerschmettert, das nicht wiederhergestellt werden kann. Und man wird im Topheth begraben, aus Mangel an Raum zu begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Also werde ich diesem Orte tun, spricht Jehova, und seinen Bewohnern, um diese Stadt dem Topheth gleich zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Und die Häuser von Jerusalem und die Häuser der Könige von Juda sollen unrein werden wie der Ort Topheth: alle die Häuser, auf deren Dächern sie dem ganzen Heere des Himmels geräuchert und anderen Göttern Trankopfer gespendet haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Und Jeremia kam vom Topheth, wohin Jehova ihn gesandt hatte zu weissagen, und er trat in den Vorhof des Hauses Jehovas und sprach zu dem ganzen Volke:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'So spricht Jehova der Heerscharen, der Gott Israels: Siehe, ich will über diese Stadt und über alle ihre Städte all das Unglück bringen, welches ich über sie geredet habe; denn sie haben ihren Nacken verhärtet, um meine Worte nicht zu hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Und als Paschchur, der Sohn Immers, der Priester (er war Oberaufseher im Hause Jehovas), Jeremia diese Worte weissagen hörte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'da schlug Paschchur den Propheten Jeremia, und legte ihn in den Stock im oberen Tore Benjamin, das im Hause Jehovas ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Und es geschah am folgenden Tage, als Paschchur Jeremia aus dem Stock herausbringen ließ, da sprach Jeremia zu ihm: Nicht Paschchur heißt Jehova deinen Namen, sondern Magor-Missabib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Denn so spricht Jehova: Siehe, ich mache dich zum Schrecken, dir selbst und allen deinen Freunden; und sie sollen durch das Schwert ihrer Feinde fallen, indem deine Augen es sehen; und ich werde ganz Juda in die Hand des Königs von Babel geben, damit er sie nach Babel wegführe und sie mit dem Schwerte erschlage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Und ich werde den ganzen Reichtum dieser Stadt dahingeben und all ihren Erwerb und alle ihr Kostbarkeiten; und alle Schätze der Könige von Juda werde ich in die Hand ihrer Feinde geben; und sie werden sie plündern und wegnehmen und nach Babel bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Und du, Paschchur, und alle Bewohner deines Hauses, ihr werdet in die Gefangenschaft gehen; und du wirst nach Babel kommen und daselbst sterben und daselbst begraben werden, du und alle deine Freunde, welchen du falsch geweissagt hast. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Jehova, du hast mich beredet, und ich habe mich bereden lassen; du hast mich ergriffen und überwältigt. Ich bin zum Gelächter geworden den ganzen Tag, jeder spottet meiner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Denn so oft ich rede, muß ich schreien, Gewalttat und Zerstörung rufen; denn das Wort Jehovas ist mir zur Verhöhnung und zum Spott geworden den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Und spreche ich: Ich will ihn nicht mehr erwähnen, noch in seinem Namen reden, so ist es in meinem Herzen wie brennendes Feuer; eingeschlossen in meinen Gebeinen; und ich werde müde, es auszuhalten, und vermag es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Denn ich habe die Verleumdung vieler gehört, Schrecken ringsum: \"Zeiget an, so wollen wir ihn anzeigen!\" Alle meine Freunde lauern auf meinen Fall: \"Vielleicht läßt er sich bereden, so daß wir ihn überwältigen und uns an ihm rächen können.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Aber Jehova ist mit mir wie ein gewaltiger Held, darum werden meine Verfolger straucheln und nichts vermögen; sie werden sehr beschämt werden, weil sie nicht verständig gehandelt haben: Eine ewige Schande, die nicht vergessen werden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Und du, Jehova der Heerscharen, der du den Gerechten prüfst, Nieren und Herz siehst, laß mich deine Rache an ihnen sehen; denn dir habe ich meine Rechtssache anvertraut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Singet Jehova, preiset Jehova! Denn er hat die Seele des Armen errettet aus der Hand der Übeltäter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Verflucht sei der Tag, an welchem ich geboren wurde; der Tag, da meine Mutter mich gebar, sei nicht gesegnet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Verflucht sei der Mann, der meinem Vater die frohe Botschaft brachte und sprach: \"Ein männliches Kind ist dir geboren\", und der ihn hoch erfreute!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Und jener Mann werde den Städten gleich, die Jehova umgekehrt hat, ohne sich\'s gereuen zu lassen; und er höre ein Geschrei am Morgen und Feldgeschrei zur Mittagszeit:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'weil er mich nicht tötete im Mutterleibe, so daß meine Mutter mir zu meinem Grabe geworden und ihr Leib ewig schwanger geblieben wäre!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Warum bin ich doch aus dem Mutterleibe hervorgekommen, um Mühsal und Kummer zu sehen, und daß meine Tage in Schande vergingen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Das Wort, welches von seiten Jehovas zu Jeremia geschah, als der König Zedekia Paschchur, den Sohn Malkijas, und Zephanja, den Sohn Maasejas, den Priester, zu ihm sandte und sagen ließ:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Befrage doch Jehova für uns, denn Nebukadrezar, der König von Babel, streitet wider uns; vielleicht wird Jehova mit uns handeln nach allen seinen Wundern, daß er von uns abziehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Und Jeremia sprach zu ihnen: Also sollt ihr zu Zedekia sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'So spricht Jehova, der Gott Israels: Siehe, ich will die Kriegswaffen umwenden, die in eurer Hand sind, mit welchen ihr außerhalb der Mauer wider den König von Babel und wider die Chaldäer streitet, die euch belagern, und sie in diese Stadt hinein versammeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Und ich selbst werde wider euch streiten mit ausgestreckter Hand und mit starkem Arm und mit Zorn und mit Grimm und mit großer Wut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Und ich werde die Bewohner dieser Stadt schlagen, sowohl Menschen als Vieh; an einer großen Pest sollen sie sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Und danach, spricht Jehova, werde ich Zedekia, den König von Juda, und seine Knechte und das Volk, und zwar die in dieser Stadt von der Pest, vom Schwerte und vom Hunger Übriggebliebenen, in die Hand Nebukadrezars, des Königs von Babel, geben, und in die Hand ihrer Feinde und in die Hand derer, welche nach ihrem Leben trachten; und er wird sie schlagen mit der Schärfe des Schwertes, er wird ihrer nicht schonen, noch Mitleid haben, noch sich erbarmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Und zu diesem Volke sollst du sagen: So spricht Jehova: Siehe, ich lege euch den Weg des Lebens vor und den Weg des Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Wer in dieser Stadt bleibt, wird sterben durch das Schwert und durch den Hunger und durch die Pest; wer aber hinausgeht und zu den Chaldäern überläuft, die euch belagern, wird leben, und seine Seele wird ihm zur Beute sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Denn ich habe mein Angesicht wider diese Stadt gerichtet zum Bösen und nicht zum Guten, spricht Jehova; sie wird in die Hand des Königs von Babel gegeben werden, und er wird sie mit Feuer verbrennen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Und zu dem Hause des Königs von Juda sollst du sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Höret das Wort Jehovas! Haus David, so spricht Jehova: Haltet jeden Morgen Gericht und befreiet den Beraubten aus der Hand des Bedrückers, damit mein Grimm nicht ausbreche wie ein Feuer und unauslöschlich brenne wegen der Bosheit eurer Handlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Siehe, ich will an dich, du Bewohnerin des Tales, des Felsens der Ebene, spricht Jehova; die ihr sprechet: Wer wird wider uns herabsteigen, und wer wird in unsere Wohnungen kommen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Und ich will euch heimsuchen nach der Frucht eurer Handlungen, spricht Jehova; und ich will ein Feuer anzünden in ihrem Walde, daß es alle ihre Umgebungen verzehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'So sprach Jehova: Geh hinab in das Haus des Königs von Juda, und rede daselbst dieses Wort');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'und sprich: Höre das Wort Jehovas, König von Juda, der du auf dem Throne Davids sitzest, du und deine Knechte und dein Volk, die ihr durch diese Tore einziehet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'So spricht Jehova: Übet Recht und Gerechtigkeit, und befreiet den Beraubten aus der Hand des Bedrückers; und den Fremdling, die Waise und die Witwe bedrücket und vergewaltiget nicht, und vergießet nicht unschuldiges Blut an diesem Orte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Denn wenn ihr dieses Wort wirklich tun werdet, so werden durch die Tore dieses Hauses Könige einziehen, welche auf dem Throne Davids sitzen, auf Wagen fahrend und auf Rossen reitend, er und seine Knechte und sein Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Wenn ihr aber nicht auf diese Worte höret, so habe ich bei mir geschworen, spricht Jehova, daß dieses Haus zur Einöde werden soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Denn also spricht Jehova über das Haus des Königs von Juda: Du bist mir ein Gilead, ein Haupt des Libanon; wenn ich dich nicht zur Wüste machen werde, zu unbewohnten Städten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Und ich werde Verderber wider dich weihen, einen jeden mit seinen Waffen, und sie werden die Auswahl deiner Zedern umhauen und ins Feuer werfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Und viele Nationen werden an dieser Stadt vorüberziehen, und einer wird zum anderen sagen: Warum hat Jehova an dieser großen Stadt also getan?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Und man wird sagen: Weil sie den Bund Jehovas, ihres Gottes, verlassen und sich vor anderen Göttern niedergebeugt und ihnen gedient haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Weinet nicht um den Toten, und beklaget ihn nicht; weinet vielmehr um den Weggezogenen, denn er wird nicht mehr zurückkehren und das Land seiner Geburt sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Denn so spricht Jehova von Schallum, dem Sohne Josias, dem König von Juda, welcher König ward an seines Vaters Josia Statt, und der aus diesem Orte weggezogen ist: er wird nicht mehr hierher zurückkehren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'sondern an dem Orte, wohin sie ihn weggeführt haben, daselbst wird er sterben, und er wird dieses Land nicht wiedersehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Wehe dem, der sein Haus mit Ungerechtigkeit baut und seine Obergemächer mit Unrecht, der seinen Nächsten umsonst arbeiten läßt und ihm seinen Lohn nicht gibt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'der da spricht: Ich will mir ein geräumiges Haus bauen und weite Obergemächer! und er haut sich Fenster aus und deckt mit Zedern, und er streicht es an mit Zinnober.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Bist du ein König, weil du in Zedern wetteiferst? Hat nicht dein Vater gegessen und getrunken und Recht und Gerechtigkeit geübt? Da erging es ihm wohl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Er hat die Rechtssache des Elenden und des Armen gerichtet; da stand es wohl. Heißt das nicht mich erkennen? spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Denn deine Augen und dein Herz sind auf nichts gerichtet als auf deinen Gewinn, und auf das Blut des Unschuldigen, um es zu vergießen, und auf Bedrückung und Gewalttat, um sie zu verüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Darum spricht Jehova von Jojakim, dem Sohne Josias, dem König von Juda, also: Man wird nicht um ihn klagen: Wehe, mein Bruder! und: Wehe, Schwester! Man wird nicht um ihn klagen: Wehe, Herr! und: Wehe, seine Herrlichkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Mit dem Begräbnis eines Esels wird er begraben werden; man wird ihn fortschleifen und wegwerfen weit hinweg von den Toren Jerusalems.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Steige auf den Libanon und schreie, und erhebe deine Stimme auf dem Gebirge Basan und schreie vom Abarim her; denn zerschmettert sind alle deine Buhlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Ich redete zu dir in deinem Wohlergehen; du sprachst: Ich will nicht hören. Das war dein Weg von deiner Jugend an, daß du auf meine Stimme nicht hörtest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Der Wind wird alle deine Hirten abweiden, und deine Buhlen werden in die Gefangenschaft gehen. Ja, dann wirst du beschämt und zu Schanden werden ob all deiner Bosheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Die du auf dem Libanon wohnst und auf den Zedern nistest, wie mitleidswürdig wirst du sein, wenn Schmerzen dich ankommen, Wehen, der Gebärenden gleich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'So wahr ich lebe, spricht Jehova, wenn auch Konja, der Sohn Jojakims, der König von Juda, ein Siegelring wäre an meiner rechten Hand, so würde ich dich doch von dannen wegreißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Und ich werde dich in die Hand derer geben, welche nach deinem Leben trachten, und in die Hand derer, vor welchen du dich fürchtest, und in die Hand Nebukadrezars, des Königs von Babel, und in die Hand der Chaldäer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Und ich werde dich und deine Mutter, die dich geboren hat, in ein anderes Land schleudern, wo ihr nicht geboren seid; und daselbst werdet ihr sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Und in das Land, wohin sie sich sehnen zurückzukehren, dahin werden sie nicht zurückkehren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Ist denn dieser Mann Konja ein verachtetes Gefäß, das man zertrümmert, oder ein Gerät, an welchem man kein Gefallen hat? Warum werden sie weggeschleudert, er und sein Same, und in ein Land geworfen, das sie nicht kennen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'O Land, Land, Land, höre das Wort Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'So spricht Jehova: Schreibet diesen Mann auf als kinderlos, als einen Mann, der kein Gedeihen hat in seinen Tagen; denn von seinem Samen wird nicht einer gedeihen, der auf dem Throne Davids sitze und fortan über Juda herrsche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Wehe den Hirten, welche die Schafe meiner Weide zu Grunde richten und zerstreuen! spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Darum spricht Jehova, der Gott Israels, also über die Hirten, die mein Volk weiden: Ihr habt meine Schafe zerstreut und sie vertrieben, und habt nicht nach ihnen gesehen; siehe, ich werde die Bosheit eurer Handlungen an euch heimsuchen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Und ich werde den Überrest meiner Schafe sammeln aus all den Ländern, wohin ich sie vertrieben habe; und ich werde sie auf ihre Triften zurückbringen, daß sie fruchtbar seien und sich mehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Und ich werde Hirten über sie erwecken, die sie weiden werden; und sie sollen sich nicht mehr fürchten und nicht erschrecken, noch vermißt werden, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Siehe, Tage kommen, spricht Jehova, da ich dem David einen gerechten Sproß erwecken werde; und er wird als König regieren und verständig handeln, und Recht und Gerechtigkeit üben im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'In seinen Tagen wird Juda gerettet werden und Israel in Sicherheit wohnen; und dies wird sein Name sein, mit dem man ihn nennen wird: Jehova, unsere Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Darum siehe, Tage kommen, spricht Jehova, da man nicht mehr sagen wird: So wahr Jehova lebt, der die Kinder Israel aus dem Lande Ägypten heraufgeführt hat! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'sondern: So wahr Jehova lebt, der den Samen des Hauses Israel heraufgeführt und ihn gebracht hat aus dem Lande des Nordens und aus all den Ländern, wohin ich sie vertrieben hatte! Und sie sollen in ihrem Lande wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Über die Propheten. Mein Herz ist gebrochen in meinem Innern, es schlottern alle meine Gebeine; ich bin wie ein Trunkener und wie ein Mann, den der Wein überwältigt hat, wegen Jehovas und wegen seiner heiligen Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Denn das Land ist voll von Ehebrechern; denn das Land trauert wegen des Fluches, die Auen der Steppe verdorren, und ihr Lauf ist böse, und ihre Macht ist Unrecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Denn sowohl Propheten als Priester sind ruchlos; sogar in meinem Hause habe ich ihre Bosheit gefunden, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Darum wird ihnen ihr Weg sein wie schlüpfrige Orte in der Dunkelheit, sie werden gestoßen werden und auf ihm fallen; denn ich bringe Unglück über sie, das Jahr ihrer Heimsuchung, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Und an den Propheten Samarias habe ich Torheit gesehen: Sie weissagten durch den Baal und führten mein Volk Israel irre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Aber an den Propheten Jerusalems habe ich Schauderhaftes gesehen: Ehebrechen und in der Lüge Wandeln, und sie stärken die Hände der Übeltäter, auf daß sie nicht umkehren, ein jeder von seiner Bosheit; sie sind mir allesamt wie Sodom geworden, und seine Bewohner wie Gomorra.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Darum spricht Jehova der Heerscharen über die Propheten also: Siehe, ich will sie mit Wermut speisen und sie mit bitterem Wasser tränken; denn von den Propheten Jerusalems ist Ruchlosigkeit ausgegangen über das ganze Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'So spricht Jehova der Heerscharen: Höret nicht auf die Worte der Propheten, die euch weissagen; sie täuschen euch, sie reden das Gesicht ihres Herzens und nicht aus dem Munde Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Sie sagen stets zu denen, die mich verachten: \"Jehova hat geredet: Ihr werdet Frieden haben\"; und zu jedem, der in dem Starrsinn seines Herzens wandelt, sprechen sie: \"Es wird kein Unglück über euch kommen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Denn wer hat im Rate Jehovas gestanden, daß er sein Wort gesehen und gehört hätte? Wer hat auf mein Wort gemerkt und gehört?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Siehe, ein Sturmwind Jehovas, ein Grimm ist ausgegangen, ja, ein wirbelnder Sturmwind; er wird sich herniederwälzen auf den Kopf der Gesetzlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Nicht wenden wird sich der Zorn Jehovas, bis er getan und bis er ausgeführt hat die Gedanken seines Herzens. Am Ende der Tage werdet ihr dessen mit Verständnis inne werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Ich habe die Propheten nicht gesandt, und doch sind sie gelaufen. Ich habe nicht zu ihnen geredet, und doch haben sie geweissagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Hätten sie aber in meinem Rate gestanden, so würden sie mein Volk meine Worte hören lassen und es abbringen von seinem bösen Wege und von der Bosheit seiner Handlungen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Bin ich ein Gott aus der Nähe, spricht Jehova, und nicht ein Gott aus der Ferne?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Oder kann sich jemand in Schlupfwinkel verbergen, und ich sähe ihn nicht? spricht Jehova. Erfülle ich nicht den Himmel und die Erde? spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Ich habe gehört, was die Propheten sagen, die in meinem Namen Lüge weissagen und sprechen: Einen Traum, einen Traum habe ich gehabt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Wie lange sollen das im Sinne haben die Propheten, welche Lüge weissagen, und die Propheten des Truges ihres Herzens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'welche gedenken, meinen Namen bei meinem Volke in Vergessenheit zu bringen durch ihre Träume, die sie einer dem anderen erzählen, so wie ihre Väter meines Namens vergaßen über dem Baal?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Der Prophet, der einen Traum hat, erzähle den Traum; und wer mein Wort hat, rede mein Wort in Wahrheit! Was hat das Stroh mit dem Korn gemein? spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Ist mein Wort nicht also, wie Feuer, spricht Jehova, und wie ein Hammer, der Felsen zerschmettert?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Darum siehe, ich will an die Propheten, spricht Jehova, die einer vom anderen meine Worte stehlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Siehe, ich will an die Propheten, spricht Jehova, die Zungen nehmen und sprechen: Er hat geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Siehe, ich will an die, spricht Jehova, welche Lügenträume weissagen und sie erzählen und mein Volk irreführen mit ihrer Prahlerei; da ich sie doch nicht gesandt und sie nicht entboten habe, und sie diesem Volke gar nichts nützen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Und wenn dieses Volk, oder ein Prophet oder ein Priester dich fragt und spricht: Was ist die Last Jehovas? so sprich zu ihnen: Was die Last sei? Ich werde euch abwerfen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Und der Prophet und der Priester und das Volk, welche sagen werden: \"Last Jehovas\", diesen Mann und sein Haus werde ich heimsuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Also sollt ihr sprechen, ein jeder zu seinem Nächsten und ein jeder zu seinem Bruder: Was hat Jehova geantwortet und was hat Jehova geredet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Und die Last Jehovas sollt ihr nicht mehr erwähnen, denn die Last wird für einen jeden sein eigenes Wort sein; denn ihr verdrehet die Worte des lebendigen Gottes, Jehovas der Heerscharen, unseres Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Also sollst du zu dem Propheten sagen: Was hat Jehova dir geantwortet und was hat Jehova geredet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Wenn ihr aber saget: \"Last Jehovas\", darum, so spricht Jehova: Weil ihr dieses Wort saget: \"Last Jehovas\", und ich doch zu euch gesandt und gesprochen habe: Ihr sollt nicht sagen: \"Last Jehovas\" -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'darum, siehe, werde ich euch ganz vergessen, und euch und die Stadt, die ich euch und euren Vätern gegeben habe, von meinem Angesicht verstoßen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'und ich werde ewigen Hohn auf euch legen und eine ewige Schande, die nicht vergessen werden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Jehova ließ mich sehen, und siehe, zwei Körbe Feigen waren vor dem Tempel Jehovas aufgestellt, nachdem Nebukadrezar, der König von Babel, Jekonja, den Sohn Jojakims, den König von Juda und die Fürsten von Juda und die Werkleute und die Schlosser aus Jerusalem weggeführt und sie nach Babel gebracht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'In dem einen Korbe waren sehr gute Feigen, gleich den Frühfeigen; und in dem anderen Korbe waren sehr schlechte Feigen, die vor Schlechtigkeit nicht gegessen werden konnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Und Jehova sprach zu mir: Was siehst du, Jeremia? Und ich sprach: Feigen; die guten Feigen sind sehr gut, und die schlechten sehr schlecht, so daß sie vor Schlechtigkeit nicht gegessen werden können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'So spricht Jehova, der Gott Israels: Wie diese guten Feigen, also werde ich die Weggeführten von Juda, die ich aus diesem Orte in das Land der Chaldäer weggeschickt habe, ansehen zum Guten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Und ich werde mein Auge auf sie richten zum Guten und sie in dieses Land zurückbringen; und ich werde sie bauen und nicht abbrechen, und sie pflanzen und nicht ausreißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Und ich will ihnen ein Herz geben, mich zu erkennen, daß ich Jehova bin; und sie werden mein Volk, und ich werde ihr Gott sein; denn sie werden mit ihrem ganzen Herzen zu mir umkehren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Und wie die schlechten Feigen, die vor Schlechtigkeit nicht gegessen werden können: Ja, so spricht Jehova, also werde ich Zedekia, den König von Juda, machen, und seine Fürsten und den Überrest von Jerusalem, die in diesem Lande Übriggebliebenen und die im Lande Ägypten Wohnenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Und ich werde sie zur Mißhandlung, zum Unglück hingeben allen Königreichen der Erde, zum Hohn und zum Sprichwort, zur Spottrede und zum Fluch an allen Orten, wohin ich sie vertreiben werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Und ich werde das Schwert, den Hunger und die Pest unter sie senden, bis sie aufgerieben sind aus dem Lande, das ich ihnen und ihren Vätern gegeben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Das Wort, welches zu Jeremia geschah über das ganze Volk von Juda, im vierten Jahre Jojakims, des Sohnes Josias, des Königs von Juda, das ist das erste Jahr Nebukadrezars, des Königs von Babel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'welches Jeremia, der Prophet, zu dem ganzen Volke von Juda und zu allen Bewohnern von Jerusalem redete, indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Vom dreizehnten Jahre Josias, des Sohnes Amons, des Königs von Juda, bis auf diesen Tag, diese dreiundzwanzig Jahre, ist das Wort Jehovas zu mir geschehen; und ich habe zu euch geredet, früh mich aufmachend und redend, aber ihr hörtet nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Und Jehova hat alle seine Knechte, die Propheten, zu euch gesandt, früh sich aufmachend und sendend; aber ihr hörtet nicht und neigtet eure Ohren nicht, um zu hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Und er sprach: Kehret doch um, ein jeder von seinem bösen Wege und von der Bosheit eurer Handlungen, so sollt ihr in dem Lande, das Jehova euch und euren Vätern gegeben hat, wohnen von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Und wandelt nicht anderen Göttern nach, um ihnen zu dienen und euch vor ihnen niederzubeugen; und reizet mich nicht durch das Werk eurer Hände, daß ich euch nicht Übles tue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Aber ihr habt nicht auf mich gehört, spricht Jehova, um mich durch das Werk eurer Hände zu reizen, euch zum Unglück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Darum, so spricht Jehova der Heerscharen: Weil ihr auf meine Worte nicht gehört habt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'siehe, so sende ich hin und hole alle Geschlechter des Nordens, spricht Jehova, und sende zu Nebukadrezar, dem König von Babel, meinem Knechte, und bringe sie über dieses Land und über seine Bewohner und über alle diese Nationen ringsum; und ich will sie vertilgen und sie zum Entsetzen machen und zum Gezisch und zu ewigen Einöden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Und ich will unter ihnen aufhören lassen die Stimme der Wonne und die Stimme der Freude, die Stimme des Bräutigams und die Stimme der Braut, das Geräusch der Mühlen und das Licht der Lampe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Und dieses ganze Land wird zur Einöde, zur Wüste werden; und diese Nationen werden dem König von Babel dienen siebzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Und es wird geschehen, wenn siebzig Jahre voll sind, werde ich an dem König von Babel und an jenem Volke, spricht Jehova, ihre Schuld heimsuchen, und an dem Lande der Chaldäer: Und ich werde es zu ewigen Wüsteneien machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Und ich werde über jenes Land alle meine Worte bringen, die ich über dasselbe geredet habe: alles, was in diesem Buche geschrieben steht, was Jeremia geweissagt hat über alle Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Denn viele Nationen und große Könige werden auch sie dienstbar machen; und ich werde ihnen nach ihrem Tun und nach dem Werke ihrer Hände vergelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Denn so hat Jehova, der Gott Israels, zu mir gesprochen: Nimm diesen Becher Zornwein aus meiner Hand, und gib ihn zu trinken all den Nationen, zu welchen ich dich sende;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'damit sie trinken, und taumeln und rasen wegen des Schwertes, das ich unter sie sende. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Und ich nahm den Becher aus der Hand Jehovas und ließ trinken all die Nationen, zu welchen Jehova mich gesandt hatte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jerusalem und die Städte von Juda, und ihre Könige, ihre Fürsten, um sie zur Einöde, zum Entsetzen, zum Gezisch und zum Fluche zu machen, wie es an diesem Tage ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'den Pharao, den König von Ägypten, und seine Knechte und seine Fürsten und sein ganzes Volk,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'und alle gemischten Völker, und alle Könige des Landes Uz; und alle Könige des Landes der Philister, und Askalon und Gasa und Ekron und den Überrest von Asdod;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edom und Moab und die Kinder Ammon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'und alle Könige von Tyrus und alle Könige von Zidon; und die Könige der Inseln, welche jenseit des Meeres sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedan und Tema und Bus, und alle mit geschorenen Haarrändern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'und alle Könige von Arabien und alle Könige der gemischten Völker, die in der Wüste wohnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'und alle Könige von Simri und alle Könige von Elam und alle Könige von Medien;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'und alle Könige des Nordens, die nahen und die fernen, den einen nach dem anderen; und alle Königreiche der Erde, die auf der Fläche des Erdbodens sind. Und der König von Scheschak soll nach ihnen trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Und sprich zu ihnen: So spricht Jehova der Heerscharen, der Gott Israels: Trinket, und werdet berauscht und speiet, und fallet und stehet nicht wieder auf wegen des Schwertes, das ich unter euch sende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Und es soll geschehen, wenn sie sich weigern, den Becher aus deiner Hand zu nehmen, um zu trinken, so sollst du zu ihnen sagen: Also spricht Jehova der Heerscharen: Ihr sollt trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Denn siehe, bei der Stadt, welche nach meinem Namen genannt ist, beginne ich Übles zu tun, und ihr solltet etwa ungestraft bleiben? Ihr werdet nicht ungestraft bleiben; denn ich rufe das Schwert über alle Bewohner der Erde, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Und du, weissage ihnen alle diese Worte und sprich zu ihnen: Jehova wird brüllen aus der Höhe und seine Stimme erschallen lassen aus seiner heiligen Wohnung; brüllen wird er gegen seine Wohnstätte, einen lauten Ruf erheben, wie die Keltertreter, gegen alle Bewohner der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Ein Getöse dringt bis an das Ende der Erde, denn Jehova rechtet mit den Nationen, er hält Gericht mit allem Fleische; die Gesetzlosen gibt er dem Schwerte hin, spricht Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'So spricht Jehova der Heerscharen: Siehe, Unglück geht aus von Nation zu Nation, und ein gewaltiger Sturm macht sich auf von dem äußersten Ende der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Und die Erschlagenen Jehovas werden an jenem Tage liegen von einem Ende der Erde bis zum anderen Ende der Erde; sie werden nicht beklagt und nicht gesammelt noch begraben werden; zu Dünger auf der Fläche des Erdbodens sollen sie werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Heulet, ihr Hirten, und schreiet! Und wälzet euch in der Asche, ihr Herrlichen der Herde! Denn eure Tage sind erfüllt, um geschlachtet zu werden; und ich zerstreue euch, daß ihr hinfallen werdet wie ein kostbares Gefäß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Und die Zuflucht ist den Hirten verloren, und das Entrinnen den Herrlichen der Herde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Horch! Geschrei der Hirten, und Heulen der Herrlichen der Herde; denn Jehova verwüstet ihre Weide.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Und die Auen des Friedens werden zerstört vor der Glut des Zornes Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Gleich einem jungen Löwen hat er sein Dickicht verlassen; denn ihr Land ist zur Wüste geworden vor dem verderbenden Schwerte und vor der Glut seines Zornes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Im Anfang der Regierung Jojakims, des Sohnes Josias, des Königs von Juda, geschah dieses Wort von seiten Jehovas also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'So spricht Jehova: Tritt in den Vorhof des Hauses Jehovas und zu allen Städten Judas, welche kommen, um anzubeten im Hause Jehovas, rede alle die Worte, welche ich dir geboten habe, zu ihnen zu reden; tue kein Wort davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Vielleicht werden sie hören und ein jeder von seinem bösen Wege umkehren: So werde ich mich des Übels gereuen lassen, welches ich ihnen zu tun gedenke wegen der Bosheit ihrer Handlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Und sprich zu ihnen: So spricht Jehova: Wenn ihr nicht auf mich höret, daß ihr in meinem Gesetz wandelt, welches ich euch vorgelegt habe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'daß ihr auf die Worte meiner Knechte, der Propheten, höret, welche ich zu euch sende, früh mich aufmachend und sendend (ihr habt aber nicht gehört):');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'so will ich dieses Haus wie Silo machen, und diese Stadt werde ich zum Fluche machen allen Nationen der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Und die Priester und die Propheten und alles Volk hörten Jeremia diese Worte reden im Hause Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Und es geschah, als Jeremia alles zu Ende geredet, was Jehova geboten hatte, zu dem ganzen Volke zu reden, da ergriffen ihn die Priester und die Propheten und alles Volk und sprachen: Du mußt gewißlich sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Warum hast du im Namen Jehovas geweissagt und gesprochen: Dieses Haus wird wie Silo werden, und diese Stadt verwüstet, ohne Bewohner? Und alles Volk versammelte sich gegen Jeremia im Hause Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Und als die Fürsten von Juda diese Worte hörten, gingen sie hinauf aus dem Hause des Königs zum Hause Jehovas und setzten sich in den Eingang des neuen Tores Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Und die Priester und die Propheten redeten zu den Fürsten und zu allem Volke und sprachen: Diesem Manne gebührt die Todesstrafe, denn er hat wider diese Stadt geweissagt, wie ihr mit euren Ohren gehört habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Und Jeremia redete zu den Fürsten und zu allem Volke und sprach: Jehova hat mich gesandt, um wider dieses Haus und wider diese Stadt all die Worte zu weissagen, welche ihr gehört habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Und nun machet gut eure Wege und eure Handlungen, und höret auf die Stimme Jehovas, eures Gottes: so wird Jehova sich des Übels gereuen lassen, welches er über euch geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Ich aber, siehe, ich bin in eurer Hand; tut mir, wie es gut und wie es recht ist in euren Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Doch wisset bestimmt, daß ihr, wenn ihr mich tötet, unschuldiges Blut bringen werdet auf euch und auf diese Stadt und auf ihre Bewohner; denn in Wahrheit, Jehova hat mich zu euch gesandt, um alle diese Worte vor euren Ohren zu reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Und die Fürsten und alles Volk sprachen zu den Priestern und zu den Propheten: Diesem Manne gebührt nicht die Todesstrafe; denn er hat im Namen Jehovas, unseres Gottes, zu uns geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Und es erhoben sich Männer von den Ältesten des Landes, und sie sprachen zu der ganzen Versammlung des Volkes und sagten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Micha, der Moraschtiter, hat in den Tagen Hiskias, des Königs von Juda, geweissagt und zu dem ganzen Volke von Juda gesprochen und gesagt: So spricht Jehova der Heerscharen: \"Zion wird als Acker gepflügt werden, und Jerusalem wird zu Trümmerhaufen und der Berg des Hauses zu Waldeshöhen werden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Haben denn Hiskia, der König von Juda, und ganz Juda ihn getötet? Hat er nicht Jehova gefürchtet und Jehova angefleht, so daß Jehova sich des Übels gereuen ließ, welches er über sie geredet hatte? Und wir wollen eine so große Übeltat wider unsere Seelen begehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Und es war auch ein Mann, der im Namen Jehovas weissagte, Urija, der Sohn Schemajas, aus Kirjath-Jearim; und er weissagte wider diese Stadt und wider dieses Land nach allen Worten Jeremias.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Und als der König Jojakim und alle seine Helden und alle Fürsten seine Worte hörten, suchte der König ihn zu töten. Und als Urija es hörte, fürchtete er sich und floh, und er kam nach Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Da sandte der König Jojakim Männer nach Ägypten, Elnathan, den Sohn Akbors, und Männer mit ihm nach Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Und sie brachten Urija aus Ägypten und führten ihn zu dem König Jojakim; und er erschlug ihn mit dem Schwerte und warf seinen Leichnam auf die Gräber der Kinder des Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Doch die Hand Achikams, des Sohnes Schaphans, war mit Jeremia, daß man ihn nicht in die Hand des Volkes gab, um ihn zu töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Im Anfang der Regierung Zedekias, des Sohnes Josias, des Königs von Juda, geschah dieses Wort zu Jeremia von seiten Jehovas also: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'So sprach Jehova zu mir: Mache dir Bande und Jochstäbe, und lege sie um deinen Hals;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'und sende sie an den König von Edom und an den König von Moab und an den König der Kinder Ammon, und an den König von Tyrus und an den König von Zidon, durch die Boten, welche nach Jerusalem zu Zedekia, dem König von Juda, gekommen sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'und befiel ihnen, daß sie ihren Herren sagen: So spricht Jehova der Heerscharen, der Gott Israels: Also sollt ihr euren Herren sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Ich habe die Erde gemacht, die Menschen und das Vieh, die auf der Fläche der Erde sind, durch meine große Kraft und durch meinen ausgestreckten Arm; und ich gebe sie, wem es mich gut dünkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Und nun habe ich alle diese Länder in die Hand Nebukadnezars, des Königs von Babel, meines Knechtes, gegeben; und auch die Tiere des Feldes habe ich ihm gegeben, daß sie ihm dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Und alle Nationen werden ihm dienen und seinem Sohne und seinem Sohnessohne, bis die Zeit auch seines Landes gekommen ist, und viele Völker und große Könige ihn dienstbar machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Und es wird geschehen, die Nation und das Königreich, welche ihm, Nebukadnezar, dem König von Babel, nicht dienen und ihren Hals unter das Joch des Königs von Babel nicht geben wollen, selbige Nation, spricht Jehova, werde ich heimsuchen mit dem Schwerte und mit dem Hunger und mit der Pest, bis ich sie durch seine Hand aufgerieben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Und ihr, höret nicht auf eure Propheten und auf eure Wahrsager und auf eure Träume und auf eure Zauberer und auf eure Beschwörer, die zu euch sprechen und sagen: Ihr werdet dem König von Babel nicht dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Denn sie weissagen euch Lüge, um euch aus eurem Lande zu entfernen, und damit ich euch vertreibe und ihr umkommet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Die Nation aber, welche ihren Hals unter das Joch des Königs von Babel bringen und ihm dienen wird, die werde ich in ihrem Lande lassen, spricht Jehova; und sie wird es bebauen und darin wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Und ich redete zu Zedekia, dem König von Juda, nach allen diesen Worten und sprach: Bringet eure Hälse unter das Joch des Königs von Babel und dienet ihm und seinem Volke, so werdet ihr leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Warum wolltet ihr, du und dein Volk, durch das Schwert, durch den Hunger und durch die Pest sterben, wie Jehova über die Nation geredet hat, welche dem König von Babel nicht dienen will?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Und höret nicht auf die Worte der Propheten, die zu euch sprechen und sagen: Ihr werdet dem König von Babel nicht dienen; denn sie weissagen euch Lüge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Denn ich habe sie nicht gesandt, spricht Jehova, und sie weissagen falsch in meinem Namen, damit ich euch vertreibe und ihr umkommet, ihr und die Propheten, die euch weissagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Und ich redete zu den Priestern und zu diesem ganzen Volke und sprach: So spricht Jehova: Höret nicht auf die Worte eurer Propheten, die euch weissagen und sprechen: Siehe, die Geräte des Hauses Jehovas werden nun bald aus Babel zurückgebracht werden; denn sie weissagen euch Lüge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Höret nicht auf sie; dienet dem König von Babel, so werdet ihr leben; warum sollte diese Stadt zur Einöde werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Wenn sie aber Propheten sind, und wenn das Wort Jehovas bei ihnen ist, so mögen sie doch bei Jehova der Heerscharen Fürbitte tun, damit die Geräte, welche im Hause Jehovas und im Hause des Königs von Juda und in Jerusalem übriggeblieben sind, nicht nach Babel kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Denn so spricht Jehova der Heerscharen von den Säulen und von dem Meere und von den Gestellen und von den übrigen Geräten, die in dieser Stadt übriggeblieben sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'welche Nebukadnezar, der König von Babel, nicht weggenommen hat, als er Jekonja, den Sohn Jojakims, den König von Juda, samt allen Edlen von Juda und Jerusalem, von Jerusalem nach Babel wegführte-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'denn so spricht Jehova der Heerscharen, der Gott Israels, von den Geräten, welche im Hause Jehovas und im Hause des Königs von Juda und in Jerusalem übriggeblieben sind:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Sie sollen nach Babel gebracht werden, und sollen daselbst sein bis auf den Tag, da ich nach ihnen sehen werde, spricht Jehova, und ich sie heraufführe und sie an diesen Ort zurückbringe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Und es geschah in demselben Jahre, im Anfang der Regierung Zedekias, des Königs von Juda, im vierten Jahre, im fünften Monat, da sprach zu mir Hananja, der Sohn Assurs, der Prophet, der von Gibeon war, im Hause Jehovas vor den Augen der Priester und alles Volkes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'und sagte: So spricht Jehova der Heerscharen, der Gott Israels, und sagt: Ich zerbreche das Joch des Königs von Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Binnen zwei Jahren werde ich alle Geräte des Hauses Jehovas an diesen Ort zurückbringen, welche Nebukadnezar, der König von Babel, von diesem Orte weggenommen und nach Babel gebracht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Und Jekonja, den Sohn Jojakims, den König von Juda, und alle Weggeführten von Juda, die nach Babel gekommen sind, werde ich an diesen Ort zurückbringen, spricht Jehova; denn ich werde das Joch des Königs von Babel zerbrechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Da sprach der Prophet Jeremia zu dem Propheten Hananja vor den Augen der Priester und vor den Augen alles Volkes, das im Hause Jehovas stand;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'und der Prophet Jeremia sprach: Amen, Jehova tue also! Jehova bestätige deine Worte, die du geweissagt hast, daß er die Geräte des Hauses Jehovas und alle Weggeführten von Babel an diesen Ort zurückbringe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Nur höre doch dieses Wort, welches ich vor deinen Ohren und vor den Ohren alles Volkes rede:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Die Propheten, welche von alters her vor mir und vor dir gewesen sind, sie haben auch über viele Länder und über große Königreiche geweissagt von Krieg und von Unglück und von Pest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Der Prophet, der von Frieden weissagt, wird, wenn das Wort des Propheten eintrifft, als der Prophet erkannt werden, welchen Jehova in Wahrheit gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Und Hananja, der Prophet, nahm die Jochstäbe vom Halse des Propheten Jeremia und zerbrach sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Und Hananja redete vor den Augen alles Volkes und sprach: So spricht Jehova: Ebenso werde ich binnen zwei Jahren das Joch Nebukadnezars, des Königs von Babel, zerbrechen vom Halse aller Nationen. Und der Prophet Jeremia ging seines Weges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Und das Wort Jehovas geschah zu Jeremia, nachdem der Prophet Hananja die Jochstäbe vom Halse des Propheten Jeremia zerbrochen hatte, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Geh und sprich zu Hananja und sage: So spricht Jehova: Hölzerne Jochstäbe hast du zerbrochen, aber an ihrer Statt eiserne Jochstäbe gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Denn so spricht Jehova der Heerscharen, der Gott Israels: Ein eisernes Joch habe ich auf den Hals aller dieser Nationen gelegt, damit sie Nebukadnezar, dem König von Babel, dienen, und sie werden ihm dienen; und auch die Tiere des Feldes habe ich ihm gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Und der Prophet Jeremia sprach zu dem Propheten Hananja: Höre doch, Hananja! Jehova hat dich nicht gesandt, sondern du hast dieses Volk auf eine Lüge vertrauen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Darum, so spricht Jehova: Siehe, ich werfe dich vom Erdboden hinweg; dieses Jahr wirst du sterben; denn du hast Abfall geredet wider Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Und der Prophet Hananja starb in demselben Jahre im siebten Monat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Und dies sind die Worte des Briefes, welchen der Prophet Jeremia von Jerusalem an die übriggebliebenen Ältesten der Weggeführten und an die Priester und an die Propheten und an das ganze Volk sandte, welches Nebukadnezar von Jerusalem nach Babel weggeführt hatte');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, '(nachdem der König Jekonja und die Königin, und die Kämmerer, die Fürsten von Juda und Jerusalem, und die Werkleute und die Schlosser aus Jerusalem weggezogen waren),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'durch Eleasar, den Sohn Schaphans, und Gemarja, den Sohn Hilkijas, welche Zedekia, der König von Juda, nach Babel zu Nebukadnezar, dem König von Babel, sandte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'So spricht Jehova der Heerscharen, der Gott Israels, zu allen Weggeführten, die ich von Jerusalem nach Babel weggeführt habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Bauet Häuser und bewohnet sie, und pflanzet Gärten und esset ihre Frucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Nehmet Weiber und zeuget Söhne und Töchter, und nehmet Weiber für eure Söhne, und eure Töchter gebet Männern, damit sie Söhne und Töchter gebären; und mehret euch daselbst, und mindert euch nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Und suchet den Frieden der Stadt, wohin ich euch weggeführt habe, und betet für sie zu Jehova; denn in ihrem Frieden werdet ihr Frieden haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Denn so spricht Jehova der Heerscharen, der Gott Israels: Laßt euch von euren Propheten, die in eurer Mitte sind, und von euren Wahrsagern nicht täuschen; und höret nicht auf eure Träume, die ihr euch träumen lasset.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Denn sie weissagen euch falsch in meinem Namen; ich habe sie nicht gesandt, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Denn so spricht Jehova: Sobald siebzig Jahre für Babel voll sind, werde ich mich eurer annehmen und mein gutes Wort an euch erfüllen, euch an diesen Ort zurückzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Denn ich weiß ja die Gedanken, die ich über euch denke, spricht Jehova, Gedanken des Friedens und nicht zum Unglück, um euch Ausgang und Hoffnung zu gewähren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Und ihr werdet mich anrufen und hingehen und zu mir beten, und ich werde auf euch hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Und ihr werdet mich suchen und finden, denn ihr werdet nach mir fragen mit eurem ganzen Herzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'und ich werde mich von euch finden lassen, spricht Jehova. Und ich werde eure Gefangenschaft wenden und euch sammeln aus allen Nationen und aus allen Orten, wohin ich euch vertrieben habe, spricht Jehova; und ich werde euch an den Ort zurückbringen, von wo ich euch weggeführt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Wenn ihr saget: Jehova hat uns in Babel Propheten erweckt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'ja, so spricht Jehova von dem König, der auf dem Throne Davids sitzt, und von dem ganzen Volke, das in dieser Stadt wohnt, euren Brüdern, welche nicht mit euch in die Gefangenschaft weggezogen sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'so spricht Jehova der Heerscharen: Siehe, ich sende unter sie das Schwert, den Hunger und die Pest, und will sie machen wie die abscheulichen Feigen, die vor Schlechtigkeit nicht gegessen werden können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Und ich will ihnen nachjagen mit dem Schwerte, mit dem Hunger und mit der Pest; und ich will sie zur Mißhandlung hingeben allen Königreichen der Erde, zum Fluch und zum Entsetzen und zum Gezisch und zum Hohn unter allen Nationen, wohin ich sie vertrieben habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'darum, daß sie auf meine Worte nicht gehört haben, spricht Jehova, womit ich meine Knechte, die Propheten, zu ihnen sandte, früh mich aufmachend und sendend. Und auch ihr habt nicht gehört, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Ihr nun, höret das Wort Jehovas, ihr Weggeführten alle, die ich von Jerusalem nach Babel weggeschickt habe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'So spricht Jehova der Heerscharen, der Gott Israels, von Ahab, dem Sohne Kolajas, und von Zedekia, dem Sohne Maasejas, die euch Lügen weissagen in meinem Namen: Siehe, ich gebe sie in die Hand Nebukadrezars, des Königs von Babel, damit er sie vor euren Augen erschlage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Und von ihnen wird ein Fluch entnommen werden seitens aller Weggeführten Judas, die in Babel sind, so daß man sagen wird: Jehova mache dich wie Zedekia und wie Ahab, welche der König von Babel im Feuer braten ließ!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Weil sie eine Ruchlosigkeit begangen in Israel und Ehebruch getrieben haben mit den Weibern ihrer Nächsten, und in meinem Namen Lügenworte geredet haben, was ich ihnen nicht geboten hatte; und ich, ich weiß es und bin Zeuge, spricht Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Und zu Schemaja, dem Nechelamiter, sollst du sprechen und sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'So spricht Jehova der Heerscharen, der Gott Israels, und sagt: Weil du in deinem Namen Briefe gesandt hast an alles Volk, das in Jerusalem ist, und an den Priester Zephanja, den Sohn Maasejas, und an alle die Priester, und gesagt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, '\"Jehova hat dich zum Priester gesetzt anstatt des Priesters Jojada, damit Aufseher seien im Hause Jehovas betreffs jedes Rasenden und Weissagenden, damit du ihn in den Stock und in das Halseisen legest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Und nun, warum hast du Jeremia, den Anathothiter, nicht gescholten, der euch weissagt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Da er ja zu uns nach Babel gesandt und gesagt hat: Es wird lange dauern; bauet Häuser und bewohnet sie, und pflanzet Gärten und esset ihre Frucht.\"...');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, '(Und der Priester Zephanja hatte diesen Brief vor den Ohren des Propheten Jeremia gelesen.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Und das Wort Jehovas geschah zu Jeremia also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Sende hin zu allen Weggeführten und sprich: Also spricht Jehova von Schemaja, dem Nechelamiter: Weil Schemaja euch geweissagt, und ich ihn doch nicht gesandt habe, und er euch auf Lügen hat vertrauen lassen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'darum spricht Jehova also: Siehe, ich will Schemaja, den Nechelamiter, und seinen Samen heimsuchen: Er soll niemand haben, der inmitten dieses Volkes wohne, und er soll das Gute nicht sehen, welches ich meinem Volke tun werde, spricht Jehova; denn er hat Abfall geredet wider Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Das Wort, welches von seiten Jehovas zu Jeremia geschah, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'So spricht Jehova, der Gott Israels, und sagt: Schreibe dir alle Worte, die ich zu dir geredet habe, in ein Buch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Denn siehe, Tage kommen, spricht Jehova, da ich die Gefangenschaft meines Volkes Israel und Juda wenden werde, spricht Jehova; und ich werde sie in das Land zurückbringen, welches ich ihren Vätern gegeben habe, damit sie es besitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Und dies sind die Worte, welche Jehova über Israel und über Juda geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Denn so spricht Jehova: Eine Stimme des Schreckens haben wir gehört; da ist Furcht und kein Friede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Fraget doch und sehet, ob ein Mann gebiert? Warum sehe ich eines jeden Mannes Hände auf seinen Lenden, einer Gebärenden gleich, und jedes Angesicht in Blässe verwandelt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Wehe! Denn groß ist jener Tag, ohnegleichen, und es ist eine Zeit der Drangsal für Jakob; doch wird er aus ihr gerettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Denn es wird geschehen an jenem Tage, spricht Jehova der Heerscharen, daß ich sein Joch von deinem Halse zerbrechen und deine Fesseln zerreißen werde, und Fremde sollen ihn nicht mehr dienstbar machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'sondern sie werden Jehova, ihrem Gott, dienen und ihrem König David, den ich ihnen erwecken werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Und du, fürchte dich nicht, mein Knecht Jakob, spricht Jehova, und erschrick nicht, Israel! Denn siehe, ich will dich retten aus der Ferne und deine Nachkommen aus dem Lande ihrer Gefangenschaft; und Jakob wird zurückkehren und ruhig und sicher sein, und niemand wird ihn aufschrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Denn ich bin mit dir, spricht Jehova, um dich zu retten. Denn ich werde den Garaus machen allen Nationen, wohin ich dich zerstreut habe; nur dir werde ich nicht den Garaus machen, sondern dich nach Gebühr züchtigen und dich keineswegs ungestraft lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Denn so spricht Jehova: Deine Wunde ist unheilbar, schmerzlich ist dein Schlag;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'niemand führt deine Streitsache, für das Geschwür gibt es kein Heilmittel, da ist kein Pflaster für dich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Alle deine Buhlen haben dich vergessen, sie fragen nicht nach dir. Denn ich habe dich geschlagen mit dem Schlage eines Feindes, mit grausamer Züchtigung, um der Größe deiner Ungerechtigkeit willen, weil deine Sünden zahlreich sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Was schreist du über deine Wunde, daß dein Schmerz unheilbar ist? Um der Größe deiner Ungerechtigkeit willen, weil deine Sünden zahlreich sind, habe ich dir solches getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Darum sollen alle, die dich fressen, gefressen werden, und alle deine Bedränger sollen insgesamt in die Gefangenschaft gehen; und deine Berauber sollen zum Raube werden, und alle deine Plünderer werde ich zur Plünderung hingeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Denn ich will dir einen Verband anlegen und dich von deinen Schlägen heilen, spricht Jehova, weil man dich eine Verstoßene nennt: \"Das ist Zion, nach der niemand fragt!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'So spricht Jehova: Siehe, ich will die Gefangenschaft der Zelte Jakobs wenden, und seiner Wohnungen will ich mich erbarmen. Und die Stadt wird auf ihrem Hügel wieder erbaut, und der Palast nach seiner Weise bewohnt werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'und Lobgesang und die Stimme der Spielenden wird von ihnen ausgehen. Und ich will sie mehren, und sie werden sich nicht mindern; und ich will sie herrlich machen, und sie werden nicht gering werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Und seine Söhne werden sein wie ehedem, und seine Gemeinde wird vor mir feststehen; und alle seine Bedrücker werde ich heimsuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Und sein Herrlicher wird aus ihm sein, und sein Herrscher aus seiner Mitte hervorgehen; und ich will ihn herzutreten lassen, daß er mir nahe; denn wer ist es wohl, der sein Herz verpfändete, um zu mir zu nahen? spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Und ihr werdet mein Volk, und ich werde euer Gott sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Siehe, ein Sturmwind Jehovas, ein Grimm ist ausgegangen, ein sausender Sturmwind; er wird sich herniederwälzen auf den Kopf der Gesetzlosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Nicht wenden wird sich die Glut des Zornes Jehovas, bis er getan und bis er ausgeführt hat die Gedanken seines Herzens. Am Ende der Tage werdet ihr dessen innewerden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'In jener Zeit, spricht Jehova, werde ich der Gott aller Geschlechter Israels sein, und sie werden mein Volk sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'So spricht Jehova: Das Volk der dem Schwerte Entronnenen hat Gnade gefunden in der Wüste. Ich will gehen, um Israel zur Ruhe zu bringen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Jehova ist mir von fern erschienen: Ja, mit ewiger Liebe habe ich dich geliebt; darum habe ich dir fortdauern lassen meine Güte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Ich will dich wieder bauen, und du wirst gebaut werden, Jungfrau Israel! Du wirst dich wieder mit deinen Tamburinen schmücken und ausziehen im Reigen der Tanzenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Du wirst wieder Weinberge pflanzen auf den Bergen Samarias; die Pflanzer werden pflanzen und genießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Denn ein Tag wird sein, da die Wächter auf dem Gebirge Ephraim rufen werden: Machet euch auf und lasset uns nach Zion hinaufziehen zu Jehova, unserem Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Denn so spricht Jehova: Jubelt über Jakob mit Freuden und jauchzet an der Spitze der Nationen! Lobsinget laut und sprechet: Rette dein Volk, Jehova, den Überrest Israels!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Siehe, ich bringe sie aus dem Lande des Nordens und sammle sie von dem äußersten Ende der Erde, unter ihnen Blinde und Lahme, Schwangere und Gebärende allzumal; in großer Versammlung kehren sie hierher zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Mit Weinen kommen sie, und unter Flehen leite ich sie; ich führe sie zu Wasserbächen auf einem ebenen Wege, auf dem sie nicht straucheln werden. Denn ich bin Israel zum Vater geworden, und Ephraim ist mein Erstgeborener. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Höret das Wort Jehovas, ihr Nationen, und meldet es auf den fernen Inseln und sprechet: Der Israel zerstreut hat, wird es wieder sammeln und es hüten wie ein Hirt seine Herde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Denn Jehova hat Jakob losgekauft und hat ihn erlöst aus der Hand dessen, der stärker war als er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Und sie werden kommen und jubeln auf der Höhe Zions, und herbeiströmen zu den Gütern Jehovas: zum Korn und zum Most und zum Öl und zu den jungen Schafen und Rindern; und ihre Seele wird sein wie ein bewässerter Garten, und sie werden hinfort nicht mehr verschmachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Dann wird die Jungfrau sich freuen im Reigen, und Jünglinge und Greise allzumal; und ich will ihre Trauer in Freude verwandeln und sie trösten, und will sie erfreuen, indem ich sie von ihrem Kummer befreie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Und ich will die Seele der Priester laben mit Fett, und mein Volk wird sich an meinen Gütern sättigen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'So spricht Jehova: Eine Stimme wird in Rama gehört, Wehklage, bitteres Weinen. Rahel beweint ihre Kinder; sie will sich nicht trösten lassen über ihre Kinder, weil sie nicht mehr sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'So spricht Jehova: Halte deine Stimme zurück vom Weinen und deine Augen von Tränen; denn es gibt Lohn für deine Arbeit, spricht Jehova, und sie werden aus dem Lande des Feindes zurückkehren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'und Hoffnung ist da für dein Ende, spricht Jehova, und deine Kinder werden in ihr Gebiet zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Wohl habe ich Ephraim klagen hören: Du hast mich gezüchtigt, und ich bin gezüchtigt worden wie ein nicht ans Joch gewöhntes Kalb; bekehre mich, daß ich mich bekehre, denn du bist Jehova, mein Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Denn nach meiner Umkehr empfinde ich Reue, und nachdem ich zur Erkenntnis gebracht worden bin, schlage ich mich auf die Lenden. Ich schäme mich und bin auch zu Schanden geworden, denn ich trage die Schmach meiner Jugend. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Ist mir Ephraim ein teurer Sohn oder ein Kind der Wonne? Denn sooft ich auch wider ihn geredet habe, gedenke ich seiner doch immer wieder. Darum ist mein Innerstes um ihn erregt; ich will mich gewißlich seiner erbarmen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Richte dir Wegweiser auf, setze dir Stangen, richte dein Herz auf die Straße, auf den Weg, den du gegangen bist! Kehre um, Jungfrau Israel, kehre um zu diesen deinen Städten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Wie lange willst du dich hin und her wenden, du abtrünnige Tochter? Denn Jehova hat ein Neues geschaffen auf der Erde: Das Weib wird den Mann umgeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'So spricht Jehova der Heerscharen, der Gott Israels: Dieses Wort wird man noch sprechen im Lande Juda und in seinen Städten, wenn ich ihre Gefangenschaft wenden werde: Jehova segne dich, du Wohnung der Gerechtigkeit, du heiliger Berg!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Und Juda und alle seine Städte werden allzumal darin wohnen, Ackersleute und die mit der Herde umherziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Denn ich habe die lechzende Seele reichlich getränkt und jede schmachtende Seele gesättigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Darüber erwachte ich und sah, und mein Schlaf war mir süß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Siehe, Tage kommen, spricht Jehova, da ich das Haus Israel und das Haus Juda besäen werde mit Samen von Menschen und Samen von Vieh.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Und es wird geschehen, wie ich über sie gewacht habe, um auszureißen und abzubrechen und niederzureißen und zu zerstören und zu verderben, also werde ich über sie wachen, um zu bauen und zu pflanzen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'In jenen Tagen wird man nicht mehr sagen: Die Väter haben Herlinge gegessen, und die Zähne der Söhne sind stumpf geworden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'sondern ein jeder wird für seine Missetat sterben: Jeder Mensch, der Herlinge ißt, dessen Zähne sollen stumpf werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Siehe, Tage kommen, spricht Jehova, da ich mit dem Hause Israel und mit dem Hause Juda einen neuen Bund machen werde:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'nicht wie der Bund, den ich mit ihren Vätern gemacht habe an dem Tage, da ich sie bei der Hand faßte, um sie aus dem Lande Ägypten herauszuführen, welchen meinen Bund sie gebrochen haben; und doch hatte ich mich mit ihnen vermählt, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Sondern dies ist der Bund, den ich mit dem Hause Israel machen werde nach jenen Tagen, spricht Jehova: Ich werde mein Gesetz in ihr Inneres legen und werde es auf ihr Herz schreiben; und ich werde ihr Gott, und sie werden mein Volk sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Und sie werden nicht mehr ein jeder seinen Nächsten und ein jeder seinen Bruder lehren und sprechen: Erkennet Jehova! Denn sie alle werden mich erkennen von ihrem Kleinsten bis zu ihrem Größten, spricht Jehova. Denn ich werde ihre Missetat vergeben und ihrer Sünde nicht mehr gedenken. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'So spricht Jehova, der die Sonne gesetzt hat zum Lichte bei Tage, die Ordnungen des Mondes und der Sterne zum Lichte bei Nacht, der das Meer erregt, und seine Wogen brausen, Jehova der Heerscharen ist sein Name:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Wenn diese Ordnungen vor meinem Angesicht weichen werden, spricht Jehova, so soll auch der Same Israels aufhören, eine Nation zu sein vor meinem Angesicht alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'So spricht Jehova: Wenn die Himmel oben gemessen, und die Grundfesten der Erde unten erforscht werden können, so will ich auch den ganzen Samen Israels verwerfen wegen alles dessen, was sie getan haben, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Siehe, Tage kommen, spricht Jehova, da diese Stadt dem Jehova gebaut werden wird vom Turme Hananel bis zum Ecktore.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Und die Meßschnur wird weiter fortlaufen geradeaus über den Hügel Gareb, und sich nach Goah wenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Und das ganze Tal der Leichen und der Asche, und alles Gefilde bis zum Bache Kidron, bis zur Ecke des Roßtores gegen Osten, wird Jehova heilig sein; es soll nicht ausgerottet noch zerstört werden in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Das Wort, welches von seiten Jehovas zu Jeremia geschah im zehnten Jahre Zedekias, des Königs von Juda; dieses Jahr war das achtzehnte Jahr Nebukadnezars.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Und das Heer des Königs von Babel belagerte damals Jerusalem. Und der Prophet Jeremia war im Gefängnishofe eingesperrt, der im Hause des Königs von Juda ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'denn Zedekia, der König von Juda, hatte ihn eingesperrt und gesagt: \"Warum weissagst du und sprichst: So spricht Jehova: Siehe, ich gebe diese Stadt in die Hand des Königs von Babel, daß er sie einnehme;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'und Zedekia, der König von Juda, wird der Hand der Chaldäer nicht entrinnen, sondern gewißlich in die Hand des Königs von Babel gegeben werden; und sein Mund wird mit dessen Munde reden, und seine Augen werden dessen Augen sehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'und er wird Zedekia nach Babel führen, und daselbst wird er sein, bis ich mich seiner annehme, spricht Jehova. Wenn ihr mit den Chaldäern streitet, so wird es euch nicht gelingen?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Und Jeremia sprach: Das Wort Jehovas ist zu mir geschehen also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Siehe, Hanamel, der Sohn Schallums, deines Oheims, wird zu dir kommen und sagen: Kaufe dir mein Feld, das zu Anathoth ist; denn du hast das Lösungsrecht, um es zu kaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Und Hanamel, der Sohn meines Oheims, kam zu mir, nach dem Worte Jehovas, in den Gefängnishof und sprach zu mir: Kaufe doch mein Feld, das zu Anathoth im Lande Benjamin ist, denn du hast das Erbrecht, und du hast die Lösung; kaufe es dir. Und ich erkannte, daß es das Wort Jehovas war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Und ich kaufte von Hanamel, dem Sohne meines Oheims, das Feld, das zu Anathoth ist, und wog ihm das Geld dar: siebzehn Sekel Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Und ich schrieb einen Kaufbrief und versiegelte ihn und nahm Zeugen, und ich wog das Geld auf der Waage dar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Und ich nahm den Kaufbrief, den versiegelten: die Festsetzung und die Bestimmungen, und auch den offenen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'und ich gab den Kaufbrief Baruk, dem Sohne Nerijas, des Sohnes Machsejas, vor den Augen Hanamels, meines Vetters, und vor den Augen der Zeugen, welche den Kaufbrief unterschrieben hatten, vor den Augen aller Juden, die im Gefängnishofe saßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Und ich befahl Baruk vor ihren Augen und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'So spricht Jehova der Heerscharen, der Gott Israels: Nimm diese Briefe, diesen Kaufbrief, sowohl den versiegelten als auch diesen offenen Brief, und lege sie in ein irdenes Gefäß, auf daß sie viele Tage erhalten bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Denn so spricht Jehova der Heerscharen, der Gott Israels: Es werden wiederum Häuser und Felder und Weinberge in diesem Lande gekauft werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Und nachdem ich Baruk, dem Sohne Nerijas, den Kaufbrief gegeben hatte, betete ich zu Jehova und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ach, Herr, Jehova! Siehe, du hast die Himmel und die Erde gemacht durch deine große Kraft und durch deinen ausgestreckten Arm: Kein Ding ist dir unmöglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'der du Güte übst an Tausenden, und die Ungerechtigkeit der Väter vergiltst in den Busen ihrer Kinder nach ihnen; du großer, mächtiger Gott, dessen Name Jehova der Heerscharen ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'groß an Rat und mächtig an Tat; du, dessen Augen über alle Wege der Menschenkinder offen sind, um einem jeden zu geben nach seinen Wegen und nach der Frucht seiner Handlungen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'der du Zeichen und Wunder getan im Lande Ägypten und bis auf diesen Tag, sowohl an Israel als auch an anderen Menschen, und dir einen Namen gemacht hast, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Und du hast dein Volk Israel aus dem Lande Ägypten herausgeführt mit Zeichen und mit Wundern und mit starker Hand und mit ausgestrecktem Arm und mit großem Schrecken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'und hast ihnen dieses Land gegeben, welches du ihren Vätern geschworen hattest ihnen zu geben, ein Land, das von Milch und Honig fließt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Und sie sind hineingekommen und haben es in Besitz genommen; aber sie hörten nicht auf deine Stimme und wandelten nicht in deinem Gesetz: Sie haben nichts getan von allem, was du ihnen zu tun geboten hattest. Da hast du ihnen all dieses Unglück widerfahren lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Siehe, die Wälle reichen bis an die Stadt, um sie einzunehmen; und durch das Schwert und den Hunger und durch die Pest ist die Stadt in die Hand der Chaldäer gegeben, welche wider sie streiten. Und was du geredet hast, ist geschehen; und siehe, du siehst es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Und doch hast du zu mir gesprochen, Herr, Jehova: Kaufe dir das Feld für Geld und nimm Zeugen; und die Stadt ist ja in die Hand der Chaldäer gegeben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Und das Wort Jehovas geschah zu Jeremia also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Siehe, ich bin Jehova, der Gott alles Fleisches; sollte mir irgend ein Ding unmöglich sein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Darum, so spricht Jehova: Siehe, ich gebe diese Stadt in die Hand der Chaldäer und in die Hand Nebukadrezars, des Königs von Babel, daß er sie einnehme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Und die Chaldäer, die wider diese Stadt streiten, werden hineinkommen und werden diese Stadt mit Feuer anzünden und sie verbrennen, samt den Häusern, auf deren Dächern sie dem Baal geräuchert und anderen Göttern Trankopfer gespendet haben, um mich zu reizen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Denn die Kinder Israel und die Kinder Juda taten von ihrer Jugend an nur, was böse ist in meinen Augen; denn die Kinder Israel haben mich nur gereizt durch das Werk ihrer Hände, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Denn zu meinem Zorne und zu meinem Grimme ist mir diese Stadt gewesen von dem Tage an, da man sie gebaut hat, bis auf diesen Tag, auf daß ich sie von meinem Angesicht hinwegtäte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'Wegen all der Bosheit der Kinder Israel und der Kinder Juda, die sie verübt haben, um mich zu reizen, sie, ihre Könige, ihre Fürsten, ihre Priester und ihre Propheten, und die Männer von Juda und die Bewohner von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Und sie haben mir den Rücken zugekehrt und nicht das Angesicht. Und ob ich sie auch lehrte, früh mich aufmachend und lehrend, so hörten sie doch nicht, um Zucht anzunehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Und sie haben ihre Scheusale in das Haus gesetzt, welches nach meinem Namen genannt ist, um es zu verunreinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Und sie haben die Höhen des Baal gebaut, welche im Tale des Sohnes Hinnoms sind, um ihre Söhne und ihre Töchter dem Moloch durch das Feuer gehen zu lassen, was ich nicht geboten habe und mir nicht in den Sinn gekommen ist um diesen Greuel zu verüben, damit sie Juda sündigen machten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Und darum spricht Jehova, der Gott Israels, nun also betreffs dieser Stadt, von welcher ihr saget: Sie ist in die Hand des Königs von Babel gegeben durch das Schwert und durch den Hunger und durch die Pest:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Siehe, ich werde sie aus all den Ländern sammeln, wohin ich sie vertrieben haben werde in meinem Zorn und in meinem Grimm, und in großer Entrüstung; und ich werde sie an diesen Ort zurückbringen und sie in Sicherheit wohnen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Und sie werden mein Volk, und ich werde ihr Gott sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Und ich werde ihnen ein Herz und einen Weg geben, damit sie mich fürchten alle Tage, ihnen und ihren Kindern nach ihnen zum Guten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Und ich werde einen ewigen Bund mit ihnen machen, daß ich nicht von ihnen lassen werde, ihnen wohlzutun; und ich werde meine Furcht in ihr Herz legen, damit sie nicht von mir abweichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Und ich werde mich über sie freuen, ihnen wohlzutun, und werde sie in diesem Lande pflanzen in Wahrheit mit meinem ganzen Herzen und mit meiner ganzen Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Denn so spricht Jehova: Gleichwie ich über dieses Volk all dieses große Unglück gebracht habe, also will ich über sie all das Gute bringen, das ich über sie rede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Und es sollen Felder gekauft werden in diesem Lande, von welchem ihr saget: Es ist öde, ohne Menschen und ohne Vieh, es ist in die Hand der Chaldäer gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Man wird Felder um Geld kaufen und Kaufbriefe schreiben und sie versiegeln und Zeugen nehmen im Lande Benjamin und in den Umgebungen von Jerusalem und in den Städten Judas, sowohl in den Städten des Gebirges als auch in den Städten der Niederung und in den Städten des Südens. Denn ich werde ihre Gefangenschaft wenden, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Und das Wort Jehovas geschah zum zweiten Male zu Jeremia, als er noch im Gefängnishofe verhaftet war, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'So spricht Jehova, der es tut, Jehova, der es bildet, um es zu verwirklichen, Jehova ist sein Name:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Rufe zu mir, und ich will dir antworten und will dir große und unerreichbare Dinge kundtun, die du nicht weißt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Denn so spricht Jehova, der Gott Israels, über die Häuser dieser Stadt und über die Häuser der Könige von Juda, welche abgebrochen werden wegen der Wälle und wegen des Schwertes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'indem man kommt, um gegen die Chaldäer zu streiten und die Häuser mit den Leichnamen der Menschen zu füllen, welche ich in meinem Zorn und in meinem Grimm geschlagen, und um all deren Bosheit willen ich mein Angesicht vor dieser Stadt verborgen habe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Siehe, ich will ihr einen Verband anlegen und Heilung bringen und sie heilen, und ich will ihnen eine Fülle von Frieden und Wahrheit offenbaren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Und ich werde die Gefangenschaft Judas und die Gefangenschaft Israels wenden, und werde sie bauen wie im Anfang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Und ich werde sie reinigen von all ihrer Ungerechtigkeit, womit sie gegen mich gesündigt haben; und ich werde alle ihre Missetaten vergeben, womit sie gegen mich gesündigt haben und womit sie von mir abgefallen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Und sie soll mir zum Freudennamen, zum Ruhm und zum Schmuck sein bei allen Nationen der Erde, welche all das Gute hören werden, das ich ihnen tue. Und sie werden zittern und beben über all das Gute und über all den Frieden, den ich ihr angedeihen lasse. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'So spricht Jehova: An diesem Orte, von dem ihr saget: \"Er ist verödet, ohne Menschen und ohne Vieh\", in den Städten Judas und auf den Straßen Jerusalems, die verwüstet sind, ohne Menschen und ohne Bewohner und ohne Vieh, wird wiederum gehört werden die Stimme der Wonne');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'und die Stimme der Freude, die Stimme des Bräutigams und die Stimme der Braut, die Stimme derer, welche sagen: Lobet Jehova der Heerscharen, denn Jehova ist gütig, denn seine Güte währt ewiglich! Die Stimme derer, welche Lob in das Haus Jehovas bringen. Denn ich werde die Gefangenschaft des Landes wenden wie im Anfang, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'So spricht Jehova der Heerscharen: An diesem Orte, der verödet ist, ohne Menschen und ohne Vieh, und in allen seinen Städten wird wiederum eine Wohnung sein für die Hirten, welche Herden lagern lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'In den Städten des Gebirges, in den Städten der Niederung und in den Städten des Südens, und im Lande Benjamin und in den Umgebungen von Jerusalem und in den Städten Judas werden wiederum die Herden unter den Händen des Zählers vorüberziehen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Siehe, Tage kommen, spricht Jehova, da ich das gute Wort erfüllen werde, welches ich über das Haus Israel und über das Haus Juda geredet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'In jenen Tagen und zu jener Zeit werde ich dem David einen Sproß der Gerechtigkeit hervorsprossen lassen, und er wird Recht und Gerechtigkeit üben im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'In jenen Tagen wird Juda gerettet werden und Jerusalem in Sicherheit wohnen; und dies wird der Name sein, mit welchem man es benennen wird: Jehova, unsere Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Denn so spricht Jehova: Nie soll es dem David an einem Manne fehlen, der auf dem Throne des Hauses Israel sitze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Und den Priestern, den Leviten, soll es nie an einem Manne vor mir fehlen, der Brandopfer opfere und Speisopfer anzünde und Schlachtopfer zurichte alle Tage. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Und das Wort Jehovas geschah zu Jeremia also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'So spricht Jehova: Wenn ihr meinen Bund betreffs des Tages und meinen Bund betreffs der Nacht brechen könnt, so daß Tag und Nacht nicht mehr seien zu ihrer Zeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'so wird auch mein Bund mit meinem Knechte David gebrochen werden, daß er keinen Sohn habe, der auf seinem Throne König sei, und auch mit den Leviten, den Priestern, meinen Dienern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Wie das Heer des Himmels nicht gezählt und der Sand des Meeres nicht gemessen werden kann, also werde ich den Samen Davids, meines Knechtes, und die Leviten mehren, die mir dienen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Und das Wort Jehovas geschah zu Jeremia also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Hast du nicht gesehen, was dieses Volk redet, indem es spricht: \"Die zwei Geschlechter, welche Jehova erwählt hatte, die hat er verworfen\"? Und so verachten sie mein Volk, so daß es vor ihnen keine Nation mehr ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'So spricht Jehova: Wenn nicht mein Bund betreffs des Tages und der Nacht besteht, wenn ich nicht die Ordnungen des Himmels und der Erde festgesetzt habe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'so werde ich auch den Samen Jakobs und Davids, meines Knechtes, verwerfen, daß ich nicht mehr von seinem Samen Herrscher nehme über den Samen Abrahams, Isaaks und Jakobs. Denn ich werde ihre Gefangenschaft wenden und mich ihrer erbarmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Das Wort, welches von seiten Jehovas zu Jeremia geschah, als Nebukadnezar, der König von Babel, und sein ganzes Heer und alle Königreiche der Erde, die unter der Herrschaft seiner Hand waren, und alle Völker wider Jerusalem und wider alle seine Städte stritten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'So spricht Jehova, der Gott Israels: Geh und sprich zu Zedekia, dem König von Juda, und sage ihm: So spricht Jehova: Siehe, ich gebe diese Stadt in die Hand des Königs von Babel, daß er sie mit Feuer verbrenne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Und du, du wirst seiner Hand nicht entrinnen, sondern gewißlich ergriffen und in seine Hand gegeben werden; und deine Augen werden die Augen des Königs von Babel sehen, und sein Mund wird mit deinem Munde reden, und du wirst nach Babel kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Doch höre das Wort Jehovas, Zedekia, König von Juda! So spricht Jehova über dich: Du wirst nicht durch das Schwert sterben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'in Frieden wirst du sterben, und gleich den Bränden deiner Väter, der früheren Könige, die vor dir gewesen sind, also wird man dir einen Brand machen, und man wird über dich klagen: \"Wehe, Herr!\" Denn ich habe das Wort geredet, spricht Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Und Jeremia, der Prophet, redete zu Zedekia, dem König von Juda, alle diese Worte in Jerusalem,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'während das Heer des Königs von Babel wider Jerusalem und wider alle übriggebliebenen Städte Judas stritt, wider Lachis und wider Aseka; denn diese waren als feste Städte unter den Städten Judas übriggeblieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Das Wort, welches von seiten Jehovas zu Jeremia geschah, nachdem der König Zedekia einen Bund mit dem ganzen Volke, das zu Jerusalem war, gemacht hatte, um ihnen Freiheit auszurufen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'damit ein jeder seinen Knecht und ein jeder seine Magd, den Hebräer und die Hebräerin, frei entließe, so daß niemand mehr einen Juden, seinen Bruder, zum Dienst anhielte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Und es gehorchten alle Fürsten und das ganze Volk, welches den Bund eingegangen war, daß ein jeder seinen Knecht und ein jeder seine Magd frei entließe, ohne sie ferner zum Dienst anzuhalten; sie gehorchten und entließen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Aber nachher wandten sie sich um und ließen die Knechte und Mägde wiederkommen, welche sie frei entlassen hatten, und unterjochten sie zu Knechten und zu Mägden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Und das Wort Jehovas geschah von seiten Jehovas zu Jeremia also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'So spricht Jehova, der Gott Israels: Ich habe einen Bund mit euren Vätern gemacht an dem Tage, da ich sie aus dem Lande Ägypten, aus dem Hause der Knechtschaft, herausführte, und habe gesprochen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Am Ende von sieben Jahren sollt ihr ein jeder seinen Bruder entlassen, den Hebräer, der sich dir verkauft hat; er soll dir sechs Jahre dienen, und dann sollst du ihn frei von dir entlassen. Aber eure Väter hörten nicht auf mich und neigten ihr Ohr nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Und ihr seid heute zwar umgekehrt und habt getan, was recht ist in meinen Augen, daß ein jeder seinem Nächsten Freiheit ausrief; und ihr habt einen Bund vor mir gemacht in dem Hause, welches nach meinem Namen genannt ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'aber ihr habt euch wieder umgewandt und meinen Namen entweiht, und habt ein jeder seinen Knecht und ein jeder seine Magd wiederkommen lassen, die ihr nach ihrem Belieben frei entlassen hattet; und ihr habt sie unterjocht, daß sie euch zu Knechten und zu Mägden seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Darum spricht Jehova also: Ihr habt nicht auf mich gehört, Freiheit auszurufen, ein jeder seinem Bruder und ein jeder seinem Nächsten; siehe, so rufe ich euch Freiheit aus, spricht Jehova, für das Schwert, für die Pest und für den Hunger, und gebe euch zur Mißhandlung hin allen Königreichen der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Und ich will die Männer, welche meinen Bund übertreten haben, welche die Worte des Bundes nicht gehalten, den sie vor mir gemacht haben, wie das Kalb machen, das sie entzweigeschnitten und zwischen dessen Stücken sie hindurchgegangen sind:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Die Fürsten von Juda und die Fürsten von Jerusalem, die Kämmerer und die Priester und alles Volk des Landes, welche zwischen den Stücken des Kalbes hindurchgegangen sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'die will ich in die Hand ihrer Feinde geben und in die Hand derer, welche nach ihrem Leben trachten; und ihre Leichname sollen dem Gevögel des Himmels und den Tieren der Erde zur Speise dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Und Zedekia, den König von Juda, und seine Fürsten werde ich in die Hand ihrer Feinde geben und in die Hand derer, welche nach ihrem Leben trachten, und in die Hand des Heeres des Königs von Babel, das von euch abgezogen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Siehe, ich gebiete, spricht Jehova, und bringe sie zu dieser Stadt zurück, damit sie wider dieselbe streiten und sie einnehmen und sie mit Feuer verbrennen; und ich werde die Städte Judas zur Wüste machen, ohne Bewohner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Das Wort, welches von seiten Jehovas zu Jeremia geschah in den Tagen Jojakims, des Sohnes Josias, des Königs von Juda, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Geh zum Hause der Rekabiter und rede mit ihnen, und bringe sie in das Haus Jehovas in eine der Zellen, und gib ihnen Wein zu trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Und ich nahm Jaasanja, den Sohn Jeremias, des Sohnes Chabazinjas, und seine Brüder und alle seine Söhne und das ganze Haus der Rekabiter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'und ich brachte sie in das Haus Jehovas, in die Zelle der Söhne Chanans, des Sohnes Jigdaljas, des Mannes Gottes, neben der Zelle der Fürsten, welche oberhalb der Zelle Maasejas war, des Sohnes Schallums, des Hüters der Schwelle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Und ich setzte den Söhnen des Hauses der Rekabiter Kelche, mit Wein gefüllt, und Becher vor und sprach zu ihnen: Trinket Wein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Aber sie sprachen: Wir trinken keinen Wein; denn Jonadab, der Sohn Rekabs, unser Vater, hat uns geboten und gesagt: Ihr sollt keinen Wein trinken, weder ihr noch eure Kinder, ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'und ihr sollt kein Haus bauen und keinen Samen säen und keinen Weinberg pflanzen, noch sie besitzen; sondern in Zelten sollt ihr wohnen alle eure Tage, auf daß ihr viele Tage lebet auf dem Erdboden, wo ihr euch aufhaltet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Und wir haben der Stimme Jonadabs, des Sohnes Rekabs, unseres Vaters, gehorcht nach allem, was er uns geboten hat: keinen Wein zu trinken alle unsere Tage, weder wir, noch unsere Weiber, noch unsere Söhne, noch unsere Töchter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'und keine Häuser zu unserer Wohnung zu bauen; und wir besitzen weder Weinberg, noch Feld, noch Saat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'und wir haben in Zelten gewohnt, und haben gehorcht und getan nach allem, was unser Vater Jonadab uns geboten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Und es geschah, als Nebukadrezar, der König von Babel, nach diesem Lande heraufzog, da sprachen wir: Kommt und laßt uns nach Jerusalem ziehen vor dem Heere der Chaldäer und vor dem Heere der Syrer; und so wohnen wir in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Und das Wort Jehovas geschah zu Jeremia also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'So spricht Jehova der Heerscharen, der Gott Israels: Geh und sprich zu den Männern von Juda und zu den Bewohnern von Jerusalem: Werdet ihr keine Zucht annehmen, um auf meine Worte zu hören? spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Die Worte Jonadabs, des Sohnes Rekabs, die er seinen Kindern geboten hat, keinen Wein zu trinken, sind gehalten worden, und bis auf diesen Tag trinken sie keinen Wein; denn sie haben dem Gebot ihres Vaters gehorcht. Und ich habe zu euch geredet, früh mich aufmachend und redend; aber ihr habt nicht auf mich gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Und ich habe alle meine Knechte, die Propheten, zu euch gesandt, früh mich aufmachend und sendend, und habe gesprochen: Kehret doch um, ein jeder von seinem bösen Wege, und machet eure Handlungen gut, und wandelt nicht anderen Göttern nach, um ihnen zu dienen, so sollt ihr in dem Lande wohnen, das ich euch und euren Vätern gegeben habe; aber ihr habt eurer Ohr nicht geneigt und nicht auf mich gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Ja, die Kinder Jonadabs, des Sohnes Rekabs, haben das Gebot ihres Vaters gehalten, welches er ihnen geboten hat; aber dieses Volk hat nicht auf mich gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Darum spricht Jehova, der Gott der Heerscharen, der Gott Israels, also: Siehe, ich bringe über Juda und über alle Bewohner von Jerusalem all das Unglück, welches ich über sie geredet habe, weil ich zu ihnen geredet und sie nicht gehört, und ich ihnen zugerufen und sie nicht geantwortet haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Und Jeremia sprach zu dem Hause der Rekabiter: So spricht Jehova der Heerscharen, der Gott Israels: Weil ihr dem Gebot Jonadabs, eures Vaters, gehorcht und alle seine Gebote bewahrt, und getan habt nach allem, was er euch geboten hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'darum spricht Jehova der Heerscharen, der Gott Israels, also: Es soll Jonadab, dem Sohne Rekabs, nicht an einem Manne fehlen, der vor mir stehe, alle Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Und es geschah im vierten Jahre Jojakims, des Sohnes Josias, des Königs von Juda, da geschah dieses Wort von seiten Jehovas zu Jeremia also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Nimm dir eine Buchrolle und schreibe darauf alle die Worte, welche ich zu dir geredet habe über Israel und über Juda und über alle Nationen, von dem Tage an, da ich zu dir geredet habe, von den Tagen Josias an bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Vielleicht wird das Haus Juda auf all das Böse hören, welches ich ihnen zu tun gedenke, damit sie umkehren, ein jeder von seinem bösen Wege, und ich ihre Missetat und ihre Sünde vergebe. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Und Jeremia rief Baruk, den Sohn Nerijas; und Baruk schrieb aus dem Munde Jeremias auf eine Buchrolle alle die Worte Jehovas, welche er zu ihm geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Und Jeremia gebot Baruk und sprach: Ich bin verhindert, ich kann nicht in das Haus Jehovas gehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'so geh du hin und lies aus der Rolle, was du aus meinem Munde aufgeschrieben hast, die Worte Jehovas, vor den Ohren des Volkes im Hause Jehovas am Tage des Fastens; und du sollst sie auch vor den Ohren aller Juden lesen, die aus ihren Städten kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Vielleicht wird ihr Flehen vor Jehova kommen, so daß sie umkehren, ein jeder von seinem bösen Wege; denn groß ist der Zorn und der Grimm, den Jehova über dieses Volk ausgesprochen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Und Baruk, der Sohn Nerijas, tat nach allem, was der Prophet Jeremia ihm geboten hatte, indem er aus dem Buche die Worte Jehovas im Hause Jehovas vorlas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Und es geschah im fünften Jahre Jojakims, des Sohnes Josias, des Königs von Juda, im neunten Monat, da rief man allem Volke in Jerusalem und allem Volke, das aus den Städten Judas nach Jerusalem kam, ein Fasten aus vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Und Baruk las aus dem Buche die Worte Jeremias im Hause Jehovas, in der Zelle Gemarjas, des Sohnes Schaphans, des Schreibers, im oberen Vorhof, im Eingang des neuen Tores des Hauses Jehovas, vor den Ohren des ganzen Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Und Mikaja, der Sohn Gemarjas, des Sohnes Schaphans, hörte alle Worte Jehovas aus dem Buche,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'und er ging zum Hause des Königs hinab in das Gemach des Schreibers; und siehe, daselbst saßen alle Fürsten: Elischama, der Schreiber, und Delaja, der Sohn Schemajas, und Elnathan, der Sohn Akbors, und Gemarja, der Sohn Schaphans, und Zedekia, der Sohn Hananjas, und alle Fürsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Und Mikaja berichtete ihnen alle die Worte, die er gehört hatte, als Baruk vor den Ohren des Volkes aus dem Buche las.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Da sandten alle Fürsten Jehudi, den Sohn Nethanjas, des Sohnes Schelemjas, des Sohnes Kuschis, zu Baruk und ließen ihm sagen: Die Rolle, aus welcher du vor den Ohren des Volkes gelesen hast, nimm sie in deine Hand und komm! Und Baruk, der Sohn Nerijas, nahm die Rolle in seine Hand und kam zu ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Und sie sprachen zu ihm: Setze dich doch und lies sie vor unseren Ohren. Und Baruk las vor ihren Ohren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Und es geschah, als sie alle die Worte hörten, sahen sie einander erschrocken an und sprachen zu Baruk: Wir müssen dem König alle diese Worte berichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Und sie fragten Baruk und sprachen: Teile uns doch mit, wie du alle diese Worte aus seinem Munde aufgeschrieben hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Und Baruk sprach zu ihnen: Aus seinem Munde sagte er mir alle diese Worte vor, und ich schrieb sie mit Tinte in das Buch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Und die Fürsten sprachen zu Baruk: Geh, verbirg dich, du und Jeremia, daß niemand wisse, wo ihr seid. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Und sie gingen zu dem König in den Hof; die Rolle aber hatten sie in dem Gemach Elischamas, des Schreibers, niedergelegt; und sie berichteten alle die Worte vor den Ohren des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Da sandte der König den Jehudi, um die Rolle zu holen; und er holte sie aus dem Gemach Elischamas, des Schreibers; und Jehudi las sie vor den Ohren des Königs und vor den Ohren aller Fürsten, die um den König standen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Der König aber saß im Winterhause, im neunten Monat, und der Kohlentopf war vor ihm angezündet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Und es geschah, sooft Jehudi drei oder vier Spalten vorgelesen hatte, zerschnitt sie der König mit dem Schreibermesser und warf sie in das Feuer, das im Kohlentopf war, bis die ganze Rolle in dem Feuer des Kohlentopfes vernichtet war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Und der König und alle seine Knechte, welche alle diese Worte hörten, erschraken nicht und zerrissen nicht ihre Kleider.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Und obwohl Elnathan und Delaja und Gemarja den König angingen, daß er die Rolle nicht verbrennen möchte, hörte er doch nicht auf sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Und der König gebot Jerachmeel, dem Königssohne, und Seraja, dem Sohne Asriels, und Schelemja, dem Sohne Abdeels, Baruk, den Schreiber, und Jeremia, den Propheten, zu greifen; aber Jehova hatte sie verborgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Und das Wort Jehovas geschah zu Jeremia, nachdem der König die Rolle und die Worte, welche Baruk aus dem Munde Jeremias aufgeschrieben, verbrannt hatte, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Nimm dir wieder eine andere Rolle und schreibe darauf alle die vorigen Worte, die auf der vorigen Rolle waren, welche Jojakim, der König von Juda, verbrannt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Und über Jojakim, den König von Juda, sollst du sprechen: So spricht Jehova: Du hast diese Rolle verbrannt, indem du sprachst: \"Warum hast du darauf geschrieben: Der König von Babel wird gewißlich kommen und dieses Land verderben und Menschen und Vieh daraus vertilgen?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Darum spricht Jehova also über Jojakim, den König von Juda: Er wird niemand haben, der auf dem Throne Davids sitze; und sein Leichnam wird hingeworfen sein der Hitze bei Tage und der Kälte bei Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Und ich will an ihm und an seinem Samen und an seinen Knechten ihre Missetat heimsuchen, und will über sie und über die Bewohner von Jerusalem und über die Männer von Juda all das Unglück bringen, welches ich über sie geredet habe; aber sie haben nicht gehört. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Und Jeremia nahm eine andere Rolle und gab sie Baruk, dem Sohne Nerijas, dem Schreiber. Und er schrieb darauf aus dem Munde Jeremias alle Worte des Buches, welche Jojakim, der König von Juda, im Feuer verbrannt hatte. Und es wurden noch viele Worte gleichen Inhalts hinzugefügt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Und Zedekia, der Sohn Josias, welchen Nebukadrezar, der König von Babel, zum König gemacht hatte im Lande Juda, regierte als König an der Stelle Konjas, des Sohnes Jojakims.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Und weder er, noch seine Knechte, noch das Volk des Landes hörten auf die Worte Jehovas, welche er durch Jeremia, den Propheten, geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Und der König Zedekia sandte Jehukal, den Sohn Schelemjas, und Zephanja, den Sohn Maasejas, den Priester, zu dem Propheten Jeremia und ließ ihm sagen: Bete doch für uns zu Jehova, unserem Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Und Jeremia ging ein und aus inmitten des Volkes, und man hatte ihn noch nicht ins Gefängnis gesetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Und das Heer des Pharao war aus Ägypten ausgezogen; und die Chaldäer, welche Jerusalem belagerten, hatten die Kunde von ihnen vernommen und waren von Jerusalem abgezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Und das Wort Jehovas geschah zu Jeremia, dem Propheten, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'So spricht Jehova, der Gott Israels: Also sollt ihr dem König von Juda sagen, der euch zu mir gesandt hat, um mich zu befragen: Siehe, das Heer des Pharao, welches euch zu Hilfe ausgezogen ist, wird in sein Land Ägypten zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Und die Chaldäer werden wiederkommen und gegen diese Stadt streiten, und sie werden sie einnehmen und mit Feuer verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'So spricht Jehova: Täuschet euch nicht selbst, daß ihr sprechet: Die Chaldäer werden gewißlich von uns wegziehen; denn sie werden nicht wegziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Denn wenn ihr auch das ganze Heer der Chaldäer schlüget, die wider euch streiten, und es blieben unter ihnen nur einige durchbohrte Männer übrig, so würden diese ein jeder in seinem Zelte aufstehen und diese Stadt mit Feuer verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Und es geschah, als das Heer der Chaldäer von Jerusalem abgezogen war vor dem Heere des Pharao,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'da ging Jeremia aus Jerusalem hinaus, um in das Land Benjamin unter das Volk zu gehen, um seinen Anteil von dort zu holen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Und als er im Tore Benjamin war, wo ein Befehlshaber der Wache stand, namens Jerija, der Sohn Schelemjas, der Sohnes Hananjas, ergriff dieser den Propheten Jeremia und sprach: Du willst zu den Chaldäern überlaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Und Jeremia sprach: Eine Lüge! Ich will nicht zu den Chaldäern überlaufen. Aber er hörte nicht auf ihn, und Jerija nahm Jeremia fest und brachte ihn zu den Fürsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Und die Fürsten gerieten in Zorn über Jeremia und schlugen ihn, und sie setzten ihn in Gewahrsam im Hause Jonathans, des Schreibers; denn dieses hatten sie zum Gefängnis gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Als Jeremia in den Kerker, und zwar in die Gewölbe, gekommen war, und Jeremia viele Tage dort gesessen hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'da sandte der König Zedekia hin und ließ ihn holen. Und der König fragte ihn in seinem Hause insgeheim und sprach: Ist ein Wort da von seiten Jehovas? Und Jeremia sprach: Es ist eines da, nämlich: Du wirst in die Hand des Königs von Babel gegeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Und Jeremia sprach zu dem König Zedekia: Was habe ich an dir, oder an deinen Knechten, oder an diesem Volke gesündigt, daß ihr mich ins Gefängnis gesetzt habt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Wo sind denn eure Propheten, die euch geweissagt und gesagt haben: Der König von Babel wird nicht über euch noch über dieses Land kommen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Und nun höre doch, mein Herr König: Laß doch mein Flehen vor dich kommen und bringe mich nicht in das Haus Jonathans, des Schreibers, zurück, damit ich nicht daselbst sterbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Da gebot der König Zedekia, und man versetzte Jeremia in den Gefängnishof; und man gab ihm täglich einen Laib Brot aus der Bäckerstraße, bis alles Brot in der Stadt aufgezehrt war. So blieb Jeremia im Gefängnishofe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Und Schephatja, der Sohn Mattans, und Gedalja, der Sohn Paschchurs, und Jukal, der Sohn Schelemjas, und Paschchur, der Sohn Malkijas, hörten die Worte, welche Jeremia zu allem Volke redete, indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'So spricht Jehova: Wer in dieser Stadt bleibt, wird sterben durch das Schwert, durch den Hunger und durch die Pest; wer aber zu den Chaldäern hinausgeht, wird leben, und seine Seele wird ihm zur Beute sein, daß er lebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'So spricht Jehova: Diese Stadt wird gewißlich in die Hand des Heeres des Königs von Babel gegeben werden, und er wird sie einnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Und die Fürsten sprachen zu dem König: Möge doch dieser Mann getötet werden! Da er ja nur die Hände der Kriegsleute schlaff macht, die in dieser Stadt übriggeblieben sind, und die Hände des ganzen Volkes, indem er nach allen diesen Worten zu ihnen redet; denn dieser Mann sucht nicht den Frieden, sondern das Unglück dieses Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Und der König Zedekia sprach: Siehe, er ist in eurer Hand, denn der König vermag nichts neben euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Da nahmen sie Jeremia und warfen ihn in die Grube Malkijas, des Königssohnes, welche im Gefängnishofe war, und sie ließen Jeremia mit Stricken hinab; und in der Grube war kein Wasser, sondern Schlamm, und Jeremia sank in den Schlamm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Und Ebedmelech, der Äthiopier, ein Eunuch, der im Hause des Königs war, hörte, daß sie Jeremia in die Grube getan hatten; der König aber saß im Tore Benjamin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Und Ebedmelech ging aus dem Hause des Königs hinaus und redete zum König und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Mein Herr König, diese Männer haben übel gehandelt in allem, was sie dem Propheten Jeremia getan, den sie in die Grube geworfen haben; er muß ja da, wo er ist, vor Hunger sterben, denn es ist kein Brot mehr in der Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Und der König gebot Ebedmelech, dem Äthiopier, und sprach: Nimm von hier dreißig Männer unter deine Hand und hole den Propheten Jeremia aus der Grube herauf, bevor er stirbt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Und Ebedmelech nahm die Männer unter seine Hand und ging in das Haus des Königs, unter die Schatzkammer, und er nahm von dort zerrissene Lappen und abgetragene Lumpen, und er ließ sie an Stricken zu Jeremia in die Grube hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Und Ebedmelech, der Äthiopier, sprach zu Jeremia: Lege doch diese zerrissenen Lappen und abgetragenen Lumpen unter die Achseln deiner Arme, unter die Stricke. Und Jeremia tat also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Und sie zogen Jeremia an den Stricken empor und holten ihn aus der Grube herauf; und Jeremia blieb im Gefängnishof.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Und der König Zedekia sandte hin und ließ den Propheten Jeremia zu sich holen in den dritten Eingang, der im Hause Jehovas war. Und der König sprach zu Jeremia: Ich will dich um ein Wort fragen, verhehle mir nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Und Jeremia sprach zu Zedekia: Wenn ich es dir kundtue, wirst du mich nicht sicherlich töten? Und wenn ich dir einen Rat erteile, wirst du nicht auf mich hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Da schwur der König Zedekia dem Jeremia insgeheim und sprach: So wahr Jehova lebt, der uns diese Seele gemacht hat, wenn ich dich töten, oder wenn ich dich in die Hand dieser Männer geben werde, die nach deinem Leben trachten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Und Jeremia sprach zu Zedekia: So spricht Jehova, der Gott der Heerscharen, der Gott Israels: Wenn du zu den Fürsten des Königs von Babel hinausgehst, so wird deine Seele am Leben bleiben, und diese Stadt wird nicht mit Feuer verbrannt werden; und du wirst am Leben bleiben, du und dein Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Wenn du aber nicht zu den Fürsten des Königs von Babel hinausgehst, so wird diese Stadt in die Hand der Chaldäer gegeben werden, und sie werden sie mit Feuer verbrennen; und du, du wirst ihrer Hand nicht entrinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Und der König Zedekia sprach zu Jeremia: Ich fürchte mich vor den Juden, die zu den Chaldäern übergelaufen sind, daß man mich in ihre Hand liefere und sie mich mißhandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Und Jeremia sprach: Man wird dich nicht überliefern; höre doch auf die Stimme Jehovas nach dem, was ich zu dir rede, so wird es dir wohlgehen, und deine Seele wird leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Wenn du dich aber weigerst hinauszugehen, so ist dies das Wort, welches Jehova mich hat sehen lassen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Siehe, alle Weiber, die im Hause des Königs von Juda übriggeblieben sind, werden hinausgeführt werden zu den Fürsten des Königs von Babel; und sie werden sprechen: \"Deine Freunde haben dich betrogen und überwältigt; deine Füße sanken ein in den Sumpf: sie wichen zurück\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Und alle deine Weiber und deine Söhne wird man zu den Chaldäern hinausführen; und du, du wirst ihrer Hand nicht entrinnen, sondern wirst von der Hand des Königs von Babel ergriffen werden, und du wirst diese Stadt mit Feuer verbrennen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Und Zedekia sprach zu Jeremia: Niemand soll um diese Worte wissen, damit du nicht sterbest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Und wenn die Fürsten hören, daß ich mit dir geredet habe, und zu dir kommen und zu dir sprechen: Berichte uns doch, was du zu dem König geredet hast, verhehle es uns nicht, daß wir dich nicht töten; und was hat der König zu dir geredet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'so sollst du ihnen sagen: Ich legte mein Flehen vor dem König nieder, daß er mich nicht in das Haus Jonathans zurückbrächte, um daselbst zu sterben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Und alle Fürsten kamen zu Jeremia und fragten ihn; und er berichtete ihnen nach allen jenen Worten, welche der König geboten hatte. Und sie wandten sich schweigend von ihm ab, denn die Sache war nicht ruchbar geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Und Jeremia blieb im Gefängnishofe bis zu dem Tage, da Jerusalem eingenommen wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Und es geschah, als Jerusalem eingenommen wurde (im neunten Jahre Zedekias, des Königs von Juda, im zehnten Monat, war Nebukadrezar, der König von Babel, und sein ganzes Heer gegen Jerusalem gekommen, und sie belagerten es;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'im elften Jahre Zedekias, im vierten Monat, am Neunten des Monats, wurde die Stadt erbrochen),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'da zogen alle Fürsten des Königs von Babel ein und besetzten das Mitteltor: Nergal-Scharezer, Samgar-Nebusarsekim, der Oberkämmerer, Nergal-Scharezer, der Obermagier, und alle übrigen Fürsten des Königs von Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Und es geschah, als Zedekia, der König von Juda, und alle Kriegsleute sie sahen, da flohen sie und zogen des Nachts aus der Stadt hinaus den Weg des Königsgartens, durch das Tor zwischen den beiden Mauern; und er zog hinaus den Weg zur Ebene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Aber das Heer der Chaldäer jagte ihnen nach, und sie erreichten Zedekia in den Ebenen von Jericho; und sie fingen ihn und führten ihn hinauf zu Nebukadnezar, dem König von Babel, nach Ribla im Lande Hamath; und er sprach das Urteil über ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Und der König von Babel schlachtete die Söhne Zedekias in Ribla vor seinen Augen, und der König von Babel schlachtete alle Edlen von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Und er blendete die Augen Zedekias, und er band ihn mit ehernen Fesseln, um ihn nach Babel zu bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Und die Chaldäer verbrannten das Haus des Königs und die Häuser des Volkes mit Feuer, und rissen die Mauern von Jerusalem nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Und den Rest des Volkes, die in der Stadt Übriggebliebenen und die Überläufer, die zu ihm übergelaufen waren, und den Rest des Volkes, die Übriggebliebenen, führte Nebusaradan, der Oberste der Leibwache, nach Babel hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Aber von dem Volke, den Geringen, die nichts hatten, ließ Nebusaradan, der Oberste der Leibwache, im Lande Juda zurück; und er gab ihnen Weinberge und Äcker an jenem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Und betreffs Jeremias gebot Nebukadrezar, der König von Babel, durch Nebusaradan, den Obersten der Leibwache, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Nimm ihn und richte deine Augen auf ihn und tue ihm nichts zuleide, sondern wie er zu dir reden wird, so tue mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Da sandten Nebusaradan, der Oberste der Leibwache, und Nebuschasban, der Oberkämmerer, und Nergal-Scharezer, der Obermagier, und alle Großen des Königs von Babel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'sie sandten hin und ließen Jeremia aus dem Gefängnishofe holen; und sie übergaben ihn Gedalja, dem Sohne Achikams, des Sohnes Schaphans, daß er ihn ins Haus hinausführe. Und so wohnte er inmitten des Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Und das Wort Jehovas war zu Jeremia geschehen, als er im Gefängnishofe verhaftet war, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Geh und sprich zu Ebedmelech, dem Äthiopier, und sage: So spricht Jehova der Heerscharen, der Gott Israels: Siehe, ich bringe meine Worte über diese Stadt zum Bösen und nicht zum Guten, und sie werden an selbigem Tage vor dir geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Aber ich werde dich an jenem Tage erretten, spricht Jehova, und du wirst nicht in die Hand der Männer gegeben werden, vor welchen du dich fürchtest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Denn ich werde dich gewißlich entrinnen lassen, und du wirst nicht durch das Schwert fallen; und du sollst deine Seele zur Beute haben, weil du auf mich vertraut hast, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Das Wort, welches von seiten Jehovas zu Jeremia geschah, nachdem Nebusaradan, der Oberste der Leibwache, ihn von Rama entlassen hatte, als er ihn holen ließ, und er mit Ketten gebunden war inmitten aller Weggeführten von Jerusalem und Juda, die nach Babel weggeführt wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Und der Oberste der Leibwache ließ Jeremia holen und sprach zu ihm: Jehova, dein Gott, hat dieses Unglück über diesen Ort geredet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'und Jehova hat es kommen lassen und hat getan, wie er geredet hatte; denn ihr habt gegen Jehova gesündigt und auf seine Stimme nicht gehört, und so ist euch solches geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Und nun siehe, ich löse dich heute von den Ketten, die an deinen Händen sind; wenn es gut ist in deinen Augen, mit mir nach Babel zu kommen, so komm, und ich werde mein Auge auf dich richten; wenn es aber übel ist in deinen Augen, mit mir nach Babel zu kommen, so laß es. Siehe, das ganze Land ist vor dir; wohin es gut und wohin es recht ist in deinen Augen zu gehen, dahin geh. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Und da er sich noch nicht entschließen konnte, sprach er: So kehre zurück zu Gedalja, dem Sohne Achikams, des Sohnes Schaphans, welchen der König von Babel über die Städte Judas bestellt hat, und wohne bei ihm inmitten des Volkes; oder wohin irgend es recht ist in deinen Augen zu gehen, dahin geh. Und der Oberste der Leibwache gab ihm Zehrung und ein Geschenk und entließ ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Und Jeremia kam zu Gedalja, dem Sohne Achikams, nach Mizpa; und er wohnte bei ihm inmitten des Volkes, das im Lande übriggeblieben war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Und als alle Heerobersten, die im Gefilde waren, sie und ihre Männer, hörten, daß der König von Babel Gedalja, den Sohn Achikams, über das Land bestellt, und daß er ihm Männer und Weiber und Kinder und von den Geringen des Landes anvertraut hatte, von denen, welche nicht nach Babel weggeführt worden waren,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'da kamen sie zu Gedalja nach Mizpa: nämlich Ismael, der Sohn Nethanjas, und Jochanan und Jonathan, die Söhne Kareachs, und Seraja, der Sohn Tanchumeths, und die Söhne Ophais, des Netophathiters, und Jesanja, der Sohn eines Maakathiters, sie und ihre Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Und Gedalja, der Sohn Achikams, des Sohnes Schaphans, schwur ihnen und ihren Männern und sprach: Fürchtet euch nicht, den Chaldäern zu dienen; bleibet im Lande und dienet dem König von Babel, so wird es euch wohlgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Und ich, siehe, ich bleibe in Mizpa, um vor den Chaldäern zu stehen, die zu uns kommen werden. Ihr aber sammelt Wein und Obst und Öl ein, und tut sie in eure Gefäße; und wohnet in euren Städten, die ihr in Besitz genommen habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Und auch alle Juden, welche in Moab und unter den Kindern Ammon und in Edom, und welche in allen diesen Ländern waren, hörten, daß der König von Babel einen Überrest in Juda gelassen, und daß er Gedalja, den Sohn Achikams, des Sohnes Schaphans, über sie bestellt hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'und alle Juden kehrten aus all den Orten zurück, wohin sie vertrieben worden waren, und sie kamen in das Land Juda zu Gedalja nach Mizpa. Und sie sammelten sehr viel Wein und Obst ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Und Jochanan, der Sohn Kareachs, und alle Heerobersten, die im Gefilde gewesen waren, kamen zu Gedalja nach Mizpa,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'und sie sprachen zu ihm: Weißt du auch, daß Baalis, der König der Kinder Ammon, Ismael, den Sohn Nethanjas, ausgesandt hat, um dich zu ermorden? Aber Gedalja, der Sohn Achikams, glaubte ihnen nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Und Jochanan, der Sohn Kareachs, sprach insgeheim zu Gedalja in Mizpa und sagte: Laß mich doch hingehen und Ismael, den Sohn Nethanjas, erschlagen, und niemand wird es wissen; warum soll er dich ermorden, daß alle Juden, die sich zu dir gesammelt haben, zerstreut werden, und der Überrest von Juda umkomme?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Aber Gedalja, der Sohn Achikams, sprach zu Jochanan, dem Sohne Kareachs: Tue diese Sache nicht, denn du redest eine Lüge über Ismael.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Und es geschah im siebten Monat, da kam Ismael, der Sohn Nethanjas, des Sohnes Elischamas, vom königlichen Geschlecht und von den Großen des Königs, und zehn Männer mit ihm, zu Gedalja, dem Sohne Achikams, nach Mizpa; und sie speisten daselbst zusammen in Mizpa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Und Ismael, der Sohn Nethanjas, stand auf, und die zehn Männer, die mit ihm waren, und sie erschlugen Gedalja, den Sohn Achikams, des Sohnes Schaphans, mit dem Schwerte; und er tötete ihn, den der König von Babel über das Land bestellt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Und Ismael erschlug alle Juden, die bei ihm, bei Gedalja, in Mizpa waren, und auch die Chaldäer, die Kriegsleute, welche sich daselbst befanden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Und es geschah am zweiten Tage, nachdem er Gedalja getötet hatte (niemand aber wußte es),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'da kamen Leute von Sichem, von Silo und von Samaria, achtzig Mann, die den Bart abgeschoren und die Kleider zerrissen und sich Ritze gemacht hatten, mit Speisopfer und Weihrauch in ihrer Hand, um es zu dem Hause Jehovas zu bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Und Ismael, der Sohn Nethanjas, ging aus von Mizpa, ihnen entgegen, indem er weinend einherging; und es geschah, als er sie antraf, da sprach er zu ihnen: Kommet zu Gedalja, dem Sohne Achikams.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Und es geschah, als sie in die Stadt hineingekommen waren, da schlachtete sie Ismael, der Sohn Nethanjas, und warf sie in die Grube, er und die Männer, die mit ihm waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Es fanden sich aber unter ihnen zehn Männer, die zu Ismael sprachen: Töte uns nicht! Denn wir haben verborgene Vorräte im Felde: Weizen und Gerste und Öl und Honig. Und er ließ ab und tötete sie nicht inmitten ihrer Brüder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Und die Grube, in welche Ismael alle Leichname der Männer, die er erschlagen hatte, neben Gedalja warf, war diejenige, welche der König Asa wegen Baesas, des Königs von Israel, machen ließ; diese füllte Ismael, der Sohn Nethanjas, mit den Erschlagenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Und Ismael führte den ganzen Überrest des Volkes, der in Mizpa war, gefangen weg: die Königstöchter und alles Volk, welches in Mizpa übriggeblieben war, welches Nebusaradan, der Oberste der Leibwache, Gedalja, dem Sohne Achikams, anvertraut hatte; und Ismael, der Sohn Nethanjas, führte sie gefangen weg und zog hin, um zu den Kindern Ammon hinüberzugehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Und als Jochanan, der Sohn Kareachs, und alle Heerobersten, die mit ihm waren, all das Böse hörten, welches Ismael, der Sohn Nethanjas, verübt hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'da nahmen sie alle Männer und zogen hin, um wider Ismael, den Sohn Nethanjas, zu streiten; und sie fanden ihn an dem großen Wasser, das bei Gibeon ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Und es geschah, als alles Volk, welches mit Ismael war, Jochanan, den Sohn Kareachs, sah und alle Heerobersten, die mit ihm waren, da freuten sie sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Und alles Volk, welches Ismael von Mizpa gefangen weggeführt hatte, wandte sich und kehrte um und ging zu Jochanan, dem Sohne Kareachs, über.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Ismael aber, der Sohn Nethanjas, entrann vor Jochanan mit acht Männern und zog zu den Kindern Ammon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Da nahmen Jochanan, der Sohn Kareachs, und alle Heerobersten, die mit ihm waren, den ganzen Überrest des Volkes, welchen er von Ismael, dem Sohne Nethanjas, von Mizpa zurückgebracht, nachdem dieser den Gedalja, den Sohn Achikams, erschlagen hatte, die Männer, die Kriegsleute, und die Weiber und die Kinder und die Kämmerer, welche er von Gibeon zurückgebracht hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'und sie zogen hin und machten halt in der Herberge Kimhams, welche bei Bethlehem ist, um fortzuziehen, damit sie nach Ägypten kämen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'aus Furcht vor den Chaldäern; denn sie fürchteten sich vor ihnen, weil Ismael, der Sohn Nethanjas, Gedalja, den Sohn Achikams, erschlagen, welchen der König von Babel über das Land bestellt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Da traten herzu alle Heerobersten und Jochanan, der Sohn Kareachs, und Jesanja, der Sohn Hoschajas, und das ganze Volk, vom Kleinsten bis zum Größten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'und sprachen zu dem Propheten Jeremia: Laß doch unser Flehen vor dich kommen, und bete für uns zu Jehova, deinem Gott, für diesen ganzen Überrest; denn wenige sind wir übriggeblieben von vielen, wie deine Augen uns sehen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'damit Jehova, dein Gott, uns den Weg kundtue, auf welchem wir gehen, und die Sache, die wir tun sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Und der Prophet Jeremia sprach zu ihnen: Ich habe es gehört; siehe, ich will zu Jehova, eurem Gott, beten nach euren Worten; und es soll geschehen, jedes Wort, das Jehova euch antworten wird, werde ich euch kundtun, ich werde euch kein Wort vorenthalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Und sie sprachen zu Jeremia: Jehova sei wider uns ein wahrhaftiger und zuverlässiger Zeuge, wenn wir nicht nach jedem Worte, womit Jehova, dein Gott, dich zu uns senden wird, also tun werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Es sei Gutes oder Böses, wir wollen hören auf die Stimme Jehovas, unseres Gottes, an den wir dich senden; damit es uns wohlgehe, wenn wir auf die Stimme Jehovas, unseres Gottes, hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Und es geschah am Ende von zehn Tagen, da geschah das Wort Jehovas zu Jeremia.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Und er berief Jochanan, den Sohn Kareachs, und alle Heerobersten, die mit ihm waren, und das ganze Volk, vom Kleinsten bis zum Größten, und sprach zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'So spricht Jehova, der Gott Israels, an welchen ihr mich gesandt habt, um euer Flehen vor ihn kommen zu lassen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Wenn ihr in diesem Lande wohnen bleibet, so werde ich euch bauen und nicht abbrechen, und euch pflanzen und nicht ausreißen; denn es reut mich des Übels, das ich euch getan habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Fürchtet euch nicht vor dem König von Babel, vor dem ihr euch fürchtet; fürchtet euch nicht vor ihm, spricht Jehova; denn ich bin mit euch, um euch aus seiner Hand zu retten und zu befreien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Und ich werde euch Barmherzigkeit zuwenden, daß er sich euer erbarme und euch in euer Land zurückkehren lasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Wenn ihr aber sprechet: Wir wollen nicht in diesem Lande bleiben, so daß ihr nicht höret auf die Stimme Jehovas, eures Gottes, und sprechet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'Nein, sondern wir wollen in das Land Ägypten ziehen, wo wir keinen Krieg sehen und den Schall der Posaune nicht hören und nicht nach Brot hungern werden, und daselbst wollen wir wohnen-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'nun denn, darum höret das Wort Jehovas, ihr Überrest von Juda! So spricht Jehova der Heerscharen, der Gott Israels: Wenn ihr eure Angesichter wirklich dahin richtet, nach Ägypten zu ziehen, und hinziehet, um euch daselbst aufzuhalten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'so wird es geschehen, daß das Schwert, vor dem ihr euch fürchtet, euch dort, im Lande Ägypten, erreichen wird; und der Hunger, vor dem euch bange ist, wird dort, in Ägypten, hinter euch her sein; und ihr werdet dort sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Und es wird geschehen, alle Männer, die ihre Angesichter dahin gerichtet haben, nach Ägypten zu ziehen, um sich daselbst aufzuhalten, werden sterben durch das Schwert, durch den Hunger und durch die Pest; und sie werden keinen Übriggeliebenen noch Entronnenen haben vor dem Unglück, welches ich über sie bringen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Denn so spricht Jehova der Heerscharen, der Gott Israels: Gleichwie mein Zorn und mein Grimm sich ergossen haben über die Bewohner von Jerusalem, also wird mein Grimm sich über euch ergießen, wenn ihr nach Ägypten ziehet; und ihr werdet zum Fluch und zum Entsetzen und zur Verwünschung und zum Hohne sein, und werdet diesen Ort nicht mehr sehen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Jehova hat zu euch geredet, ihr Überrest von Juda: Ziehet nicht nach Ägypten! Wisset bestimmt, daß ich es euch heute ernstlich bezeugt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Denn ihr habt um den Preis eurer Seelen geirrt. Denn ihr habt mich an Jehova, euren Gott, gesandt und gesprochen: Bete für uns zu Jehova, unserem Gott; und nach allem, was Jehova, unser Gott, sagen wird, also tue uns kund, und wir werden es tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Und ich habe es euch heute kundgetan; aber ihr habt nicht auf die Stimme Jehovas, eures Gottes, gehört, nach allem, womit er mich zu euch gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Und nun wisset bestimmt, daß ihr sterben werdet durch das Schwert, durch den Hunger und durch die Pest an dem Orte, wohin es euch zu ziehen gelüstet, um euch daselbst aufzuhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Und es geschah, als Jeremia zu dem ganzen Volke alle Worte Jehovas, ihres Gottes, zu Ende geredet, womit ihn Jehova, ihr Gott, zu ihnen gesandt hatte, alle jene Worte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'da sprachen Asarja, der Sohn Hoschajas, und Jochanan, der Sohn Kareachs, und alle frechen Männer, sie sprachen zu Jeremia: Du redest Lügen! Jehova, unser Gott, hat dich nicht gesandt und gesagt: Ihr sollt nicht nach Ägypten ziehen, um euch daselbst aufzuhalten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'sondern Baruk, der Sohn Nerijas, hetzt dich wider uns auf, um uns in die Hand der Chaldäer zu liefern, damit sie uns töten und uns nach Babel wegführen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Und so hörten Jochanan, der Sohn Kareachs, und alle Heerobersten und das ganze Volk nicht auf die Stimme Jehovas, im Lande Juda zu bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Und Jochanan, der Sohn Kareachs, und alle Heerobersten nahmen den ganzen Überrest von Juda, welche aus allen Nationen, wohin sie vertrieben worden, zurückgekehrt waren, um sich im Lande Juda aufzuhalten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Die Männer und die Weiber und die Kinder und die Königstöchter, und alle Seelen, welche Nebusaradan, der Oberste der Leibwache, bei Gedalja, dem Sohne Achikams, des Sohnes Schaphans, zurückgelassen hatte, und auch den Propheten Jeremia und Baruk, den Sohn Nerijas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'und sie zogen nach Ägypten, denn sie hörten nicht auf die Stimme Jehovas. Und sie kamen nach Tachpanches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Und das Wort Jehovas geschah zu Jeremia in Tachpanches also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Nimm große Steine in deine Hand und senke sie in Mörtel ein am Ziegelofen, der bei dem Eingang des Hauses des Pharao in Tachpanches ist, vor den Augen der jüdischen Männer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'und sprich zu ihnen: So spricht Jehova der Heerscharen, der Gott Israels: Siehe, ich sende hin und hole Nebukadrezar, den König von Babel, meinen Knecht, und setze seinen Thron über diese Steine, die ich eingesenkt habe; und er wird seinen Prachtteppich über ihnen ausbreiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Und er wird kommen und das Land Ägypten schlagen: Wer zum Tode bestimmt ist, gehe zum Tode; und wer zur Gefangenschaft, zur Gefangenschaft; und wer zum Schwerte, zum Schwerte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Und ich werde ein Feuer anzünden in den Häusern der Götter Ägyptens, und er wird sie verbrennen und sie wegführen. Und er wird das Land Ägypten um sich wickeln, wie der Hirt sein Oberkleid um sich wickelt; und er wird von dannen ziehen in Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Und er wird die Säulen von Beth-Semes, welche im Lande Ägypten sind, zerschlagen, und die Häuser der Götter Ägyptens mit Feuer verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Das Wort, welches zu Jeremia geschah an alle Juden, die im Lande Ägypten wohnten, welche in Migdol und in Tachpanches und in Noph und im Lande Pathros wohnten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'So spricht Jehova der Heerscharen, der Gott Israels: Ihr habt all das Unglück gesehen, welches ich über Jerusalem und über alle Städte Judas gebracht habe; und siehe, sie sind eine Einöde an diesem Tage, und niemand wohnt darin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'um ihrer Bosheit willen, die sie verübt haben, um mich zu reizen, indem sie hingingen, zu räuchern und anderen Göttern zu dienen, welche sie nicht kannten, weder sie noch ihr und eure Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Und ich habe alle meine Knechte, die Propheten, zu euch gesandt, früh mich aufmachend und sendend, indem ich sprach: Tut doch nicht diesen Greuel, den ich hasse!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Aber sie haben nicht gehört und ihr Ohr nicht geneigt, um von ihrer Bosheit umzukehren, daß sie anderen Göttern nicht räucherten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Da ergoß sich mein Grimm und mein Zorn, und er brannte in den Städten Judas und auf den Straßen von Jerusalem; und sie sind zur Einöde, zur Wüste geworden, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Und nun, so spricht Jehova, der Gott der Heerscharen, der Gott Israels: Warum begehet ihr eine so große Übeltat wider eure Seelen, um euch Mann und Weib, Kind und Säugling aus Juda auszurotten, so daß ihr euch keinen Überrest übriglasset;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'indem ihr mich reizet durch die Werke eurer Hände, dadurch daß ihr anderen Göttern räuchert im Lande Ägypten, wohin ihr gekommen seid, um euch daselbst aufzuhalten, auf daß ihr euch ausrottet und zum Fluch und zum Hohne werdet unter allen Nationen der Erde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Habt ihr die Übeltaten eurer Väter vergessen und die Übeltaten der Könige von Juda und die Übeltaten ihrer Weiber und eure Übeltaten und die Übeltaten eurer Weiber, welche sie im Lande Juda und auf den Straßen von Jerusalem begangen haben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Bis auf diesen Tag sind sie nicht gedemütigt, und sie haben sich nicht gefürchtet und haben nicht gewandelt in meinem Gesetz und in meinen Satzungen, die ich euch und euren Vätern vorgelegt habe. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Darum, so spricht Jehova der Heerscharen, der Gott Israels: Siehe, ich will mein Angesicht wider euch richten zum Unglück, und zur Ausrottung von ganz Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Und ich werde den Überrest von Juda wegraffen, die ihre Angesichter dahin gerichtet haben, in das Land Ägypten zu ziehen, um sich daselbst aufzuhalten; und sie sollen alle aufgerieben werden, im Lande Ägypten sollen sie fallen; durch das Schwert, durch den Hunger sollen sie aufgerieben werden, vom Kleinsten bis zum Größten; durch das Schwert und durch den Hunger sollen sie sterben. Und sie sollen zum Fluche, zum Entsetzen und zur Verwünschung und zum Hohne werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Und ich will die im Lande Ägypten Wohnenden heimsuchen, wie ich Jerusalem heimgesucht habe durch das Schwert, durch den Hunger und durch die Pest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Und der Überrest von Juda, der in das Land Ägypten gekommen ist, um sich daselbst aufzuhalten, wird keinen Entronnenen noch Übriggebliebenen haben, um in das Land Juda zurückzukehren, wohin sie sich sehnen zurückzukehren, um dort zu wohnen; denn sie werden nicht zurückkehren, außer einigen Entronnenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Und alle Männer, welche wußten, daß ihre Weiber anderen Göttern räucherten, und alle Weiber, die in großer Menge dastanden, und alles Volk, das im Lande Ägypten, in Pathros wohnte, antworteten dem Jeremia und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Was das Wort betrifft, welches du im Namen Jehovas zu uns geredet hast, so werden wir nicht auf dich hören;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'sondern wir wollen gewißlich alles tun, was aus unserem Munde hervorgegangen ist, der Königin des Himmels zu räuchern und ihr Trankopfer zu spenden, so wie wir getan haben, wir und unsere Väter, unsere Könige und unsere Fürsten, in den Städten Judas und auf den Straßen von Jerusalem. Da hatten wir Brot in Fülle, und es ging uns wohl, und wir sahen kein Unglück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Aber seitdem wir aufgehört haben, der Königin des Himmels zu räuchern und ihr Trankopfer zu spenden, haben wir an allem Mangel gehabt und sind durch das Schwert und durch den Hunger aufgerieben worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Und wenn wir der Königin des Himmels räucherten und ihr Trankopfer spendeten, haben wir ihr denn ohne unsere Männer Kuchen bereitet, um sie abzubilden, und ihr Trankopfer gespendet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Und Jeremia sprach zu dem ganzen Volke, zu den Männern und zu den Weibern und zu allem Volke, welches ihm Antwort gegeben hatte, und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Das Räuchern, mit welchem ihr in den Städten Judas und auf den Straßen von Jerusalem geräuchert habt, ihr und eure Väter, eure Könige und eure Fürsten und das Volk des Landes, hat nicht Jehova daran gedacht, und ist es ihm nicht in den Sinn gekommen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Und Jehova konnte es nicht mehr ertragen wegen der Bosheit eurer Handlungen, wegen der Greuel, die ihr verübtet. Darum ist euer Land zur Einöde, zum Entsetzen und zum Fluche geworden, ohne Bewohner, wie es an diesem Tage ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Darum daß ihr geräuchert und gegen Jehova gesündigt und auf die Stimme Jehovas nicht gehört, und in seinem Gesetz und in seinen Satzungen und in seinen Zeugnissen nicht gewandelt habt, darum ist euch dieses Unglück widerfahren, wie es an diesem Tage ist. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Und Jeremia sprach zu dem ganzen Volke und zu allen Weibern: Höret das Wort Jehovas, alle Juden, die ihr im Lande Ägypten seid!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'So spricht Jehova der Heerscharen, der Gott Israels, und sagt: Ihr und eure Weiber, ihr habt es mit eurem Munde geredet und es mit euren Händen vollführt und gesprochen: Wir wollen unsere Gelübde gewißlich erfüllen, die wir getan haben, der Königin des Himmels zu räuchern und ihr Trankopfer zu spenden. So haltet nur eure Gelübde und erfüllet nur eure Gelübde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Darum höret das Wort Jehovas, alle Juden, die ihr im Lande Ägypten wohnet! Siehe, ich habe bei meinem großen Namen geschworen, spricht Jehova: Wenn je wieder mein Name im Munde irgend eines Mannes von Juda genannt werden soll, daß er spreche: \"So wahr der Herr, Jehova, lebt!\" im ganzen Lande Ägypten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Siehe, ich wache über sie zum Bösen und nicht zum Guten; und alle Männer von Juda, die im Lande Ägypten sind, sollen durch das Schwert und durch den Hunger aufgerieben werden, bis sie vernichtet sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Und dem Schwert Entronnene werden aus dem Lande Ägypten in das Land Juda zurückkehren, ein zählbares Häuflein. Und der ganze Überrest von Juda, der in das Land Ägypten gekommen ist, um sich daselbst aufzuhalten, wird wissen, welches Wort sich bestätigen wird, das meinige oder das ihrige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Und dies sei euch das Zeichen, spricht Jehova, daß ich euch an diesem Orte heimsuchen werde, auf daß ihr wisset, daß meine Worte über euch sich gewißlich bestätigen werden zum Unglück;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'so spricht Jehova: Siehe, ich gebe den Pharao Hophra, den König von Ägypten, in die Hand seiner Feinde und in die Hand derer, welche nach seinem Leben trachten, so wie ich Zedekia, den König von Juda, in die Hand Nebukadrezars gegeben habe, des Königs von Babel, seines Feindes, der ihm nach dem Leben trachtete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Das Wort, welches der Prophet Jeremia zu Baruk, dem Sohne Nerijas, redete, als er diese Worte aus dem Munde Jeremias in ein Buch schrieb, im vierten Jahre Jojakims, des Sohnes Josias, des Königs von Juda, indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'So spricht Jehova, der Gott Israels, von dir, Baruk:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Du sprichst: Wehe mir! Denn Jehova hat Kummer zu meinem Schmerze gefügt; ich bin müde von meinem Seufzen, und Ruhe finde ich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'So sollst du zu ihm sagen: So spricht Jehova: Siehe, was ich gebaut habe, breche ich ab; und was ich gepflanzt habe, reiße ich aus, und zwar das ganze Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Und du, du trachtest nach großen Dingen für dich? Trachte nicht danach! Denn siehe, ich bringe Unglück über alles Fleisch, spricht Jehova; aber ich gebe dir deine Seele zur Beute an allen Orten, wohin du ziehen wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Das Wort Jehovas, welches zu Jeremia, dem Propheten, geschah wider die Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Über Ägypten. Wider die Heeresmacht des Pharao Neko, des Königs von Ägypten, welche zu Karchemis war, am Strome Euphrat, welche Nebukadrezar, der König von Babel, schlug im vierten Jahre Jojakims, des Sohnes Josias, des Königs von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Rüstet Tartsche und Schild und rücket heran zum Streit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Spannet die Rosse an und besteiget die Reitpferde! Und stellet euch auf in Helmen, putzet die Lanzen, ziehet die Panzer an!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Warum sehe ich sie bestürzt zurückweichen? Und ihre Helden sind zerschmettert, und sie ergreifen die Flucht und sehen sich nicht um, Schrecken ringsum! spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Der Schnelle soll nicht entfliehen, und der Held nicht entrinnen; gegen Norden, zur Seite des Stromes Euphrat, sind sie gestrauchelt und gefallen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Wer ist es, der heraufzieht wie der Nil, wie Ströme wogen seine Gewässer?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Ägypten zieht herauf wie der Nil, und wie Ströme wogen seine Gewässer; und es spricht: Ich will hinaufziehen, will das Land bedecken, will Städte zerstören und ihre Bewohner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Ziehet hinauf, ihr Rosse, und raset, ihr Wagen; und ausziehen mögen die Helden, Kusch und Put, die den Schild fassen, und die Ludim, die den Bogen fassen und spannen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Aber selbiger Tag ist dem Herrn, Jehova der Heerscharen, ein Tag der Rache, um sich zu rächen an seinen Widersachern; und fressen wird das Schwert und sich sättigen, und sich laben an ihrem Blute. Denn der Herr, Jehova der Heerscharen, hat ein Schlachtopfer im Lande des Nordens, am Strome Euphrat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Geh hinauf nach Gilead und hole Balsam, du Jungfrau, Tochter Ägyptens! Vergeblich häufst du die Heilmittel; da ist kein Pflaster für dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Die Nationen haben deine Schande gehört, und die Erde ist voll deines Klagegeschreis; denn ein Held ist über den anderen gestrauchelt, sie sind gefallen beide zusammen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Das Wort, welches Jehova zu Jeremia, dem Propheten, redete betreffs der Ankunft Nebukadrezars, des Königs von Babel, um das Land Ägypten zu schlagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Verkündiget es in Ägypten, und laßt es hören in Migdol, und laßt es hören in Noph und in Tachpanches! Sprechet: Stelle dich und rüste dich! Denn das Schwert frißt alles rings um dich her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Warum sind deine Starken niedergeworfen? Keiner hielt stand, denn Jehova hat sie niedergestoßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Er machte der Strauchelnden viele; ja, einer fiel über den anderen, und sie sprachen: Auf! Und laßt uns zurückkehren zu unserem Volke und zu unserem Geburtslande vor dem verderbenden Schwerte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Man rief daselbst: Der Pharao, der König von Ägypten, ist verloren; er hat die bestimmte Zeit vorübergehen lassen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'So wahr ich lebe, spricht der König, Jehova der Heerscharen ist sein Name: Wie der Tabor unter den Bergen und wie der Karmel am Meere wird er kommen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Mache dir Auswanderungsgeräte, du Bewohnerin, Tochter Ägyptens; denn Noph wird zur Wüste werden und verbrannt, ohne Bewohner. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Eine sehr schöne junge Kuh ist Ägypten; eine Bremse von Norden kommt, sie kommt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Auch seine Söldner in seiner Mitte sind wie gemästete Kälber; ja, auch sie wandten um, sind geflohen allzumal, haben nicht standgehalten; denn der Tag ihres Verderbens ist über sie gekommen, die Zeit ihrer Heimsuchung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Sein Laut ist wie das Geräusch einer Schlange, welche davoneilt; denn sie ziehen mit Heeresmacht einher und kommen über Ägypten mit Beilen, wie Holzhauer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Sie haben seinen Wald umgehauen, spricht Jehova, denn sie sind unzählig; denn ihrer sind mehr als der Heuschrecken, und ihrer ist keine Zahl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Die Tochter Ägyptens ist zu Schanden geworden, sie ist in die Hand des Volkes von Norden gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Es spricht Jehova der Heerscharen, der Gott Israels: Siehe, ich suche heim den Amon von No, und den Pharao und Ägypten und seine Götter und seine Könige, ja, den Pharao und die auf ihn vertrauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Und ich gebe sie in die Hand derer, welche nach ihrem Leben trachten, und zwar in die Hand Nebukadrezars, des Königs von Babel, und in die Hand seiner Knechte. Hernach aber soll es bewohnt werden wie in den Tagen der Vorzeit, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Du aber, fürchte dich nicht, mein Knecht Jakob, und erschrick nicht, Israel! Denn siehe, ich will dich retten aus der Ferne und deine Nachkommen aus dem Lande ihrer Gefangenschaft; und Jakob wird zurückkehren und ruhig und sicher sein, und niemand wird ihn aufschrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Du, mein Knecht Jakob, fürchte dich nicht, spricht Jehova, denn ich bin mit dir. Denn ich werde den Garaus machen allen Nationen, wohin ich dich vertrieben habe; aber dir werde ich nicht den Garaus machen, sondern dich nach Gebühr züchtigen und dich keineswegs ungestraft lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Das Wort Jehovas, welches zu Jeremia, dem Propheten, geschah über die Philister, ehe der Pharao Gasa schlug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'So spricht Jehova: Siehe, Wasser steigen herauf von Norden her und werden zu einem überschwemmenden Wildbach; und sie überschwemmen das Land und seine Fülle, die Städte und ihre Bewohner. Und es schreien die Menschen, und alle Bewohner des Landes heulen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'vor dem Schalle des Stampfens der Hufe seiner starken Rosse, vor dem Getöse seiner Wagen, dem Gerassel seiner Räder, Väter sehen sich nicht um nach den Söhnen vor Erschlaffung der Hände-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'wegen des Tages, der da kommt, um alle Philister zu zerstören und für Tyrus und Zidon jeden hilfebringenden Überrest zu vertilgen. Denn Jehova zerstört die Philister, den Überrest der Insel Kaphtor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Kahlheit ist über Gasa gekommen, vernichtet ist Askalon, der Überrest ihres Tales. Wie lange willst du dich ritzen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Wehe! Schwert Jehovas, wie lange willst du nicht rasten? Fahre zurück in deine Scheide, halte dich ruhig und still!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Wie sollte es rasten, da doch Jehova ihm geboten hat? Gegen Askalon und gegen das Gestade des Meeres, dorthin hat er es bestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Über Moab. So spricht Jehova der Heerscharen, der Gott Israels: Wehe über Nebo! Denn es ist verwüstet. Zu Schanden geworden, eingenommen ist Kirjathaim; zu Schanden geworden ist die hohe Feste und bestürzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Moabs Ruhm ist dahin. In Hesbon hat man Böses ersonnen gegen dasselbe: \"Kommt und laßt es uns ausrotten, daß es keine Nation mehr sei!\" Auch du, Madmen, wirst vernichtet werden; das Schwert zieht hinter dir her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Horch! Ein Geschrei aus Horonaim: Verheerung und große Zertrümmerung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moab ist zerschmettert, seine Geringen haben ein lautes Geschrei erhoben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Denn die Anhöhe von Luchith steigt man mit Weinen hinauf, mit Weinen; denn am Abhang von Horonaim hat man Angstgeschrei der Zerschmetterung gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Fliehet, rettet euer Leben, und seid wie ein Entblößter in der Wüste!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Denn weil du auf deine Werke und auf deine Schätze vertrautest, sollst auch du eingenommen werden; und Kamos wird in die Gefangenschaft ziehen, seine Priester und seine Fürsten allzumal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Und der Verwüster wird über jede Stadt kommen, und keine Stadt wird entrinnen; und das Tal wird zu Grunde gehen und die Ebene vernichtet werden, wie Jehova gesprochen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Gebet Moab Flügel, denn fliegend wird es wegziehen; und seine Städte werden zur Wüste werden, so daß niemand darin wohnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Verflucht sei, wer das Werk Jehovas lässig treibt, und verflucht, wer sein Schwert vom Blute zurückhält!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Sorglos war Moab von seiner Jugend an, und still lag es auf seinen Hefen und wurde nicht ausgeleert von Faß zu Faß, und in die Gefangenschaft ist es nie gezogen; daher ist sein Geschmack ihm geblieben und sein Geruch nicht verändert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Darum siehe, Tage kommen, spricht Jehova, da ich ihm Schröter senden werde, die es schroten und seine Fässer ausleeren und seine Krüge zerschmeißen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Und Moab wird sich über Kamos schämen, gleichwie das Haus Israel sich geschämt hat über Bethel, ihre Zuversicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Wie sprechet ihr: Wir sind Helden und tapfere Männer zum Streit?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Moab ist verwüstet, und seine Städte hat man erstiegen, und die Auswahl seiner Jünglinge ist zur Schlachtung hingestürzt, spricht der König, Jehova der Heerscharen ist sein Name.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Moabs Verderben steht nahe bevor, und sein Unglück eilt sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Beklaget es, ihr seine Umwohner alle, und alle, die ihr seinen Namen kennet! Sprechet: Wie ist zerbrochen das Zepter der Macht, der Stab der Majestät!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Steige herab von der Herrlichkeit und wohne in dürrem Lande, du Bewohnerin, Tochter Dibons; denn Moabs Verwüster ist wider dich heraufgezogen, hat deine Festen zerstört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Tritt an den Weg und schaue, Bewohnerin von Aroer! Frage den Fliehenden und die Entronnenen, sprich: Was ist geschehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Moab ist zu Schanden geworden, denn es ist bestürzt. Heulet und schreiet, verkündet am Arnon, daß Moab verwüstet ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Und das Gericht ist gekommen über das Land der Ebene, über Cholon und über Jahza und über Mephaath,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'und über Dibon und über Nebo und über Beth-Diblathaim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'und über Kirjathaim und über Beth-Gamul und über Beth-Meon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'und über Kerijoth und über Bozra, und über alle Städte des Landes Moab, die fernen und die nahen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Das Horn Moabs ist abgehauen, und sein Arm ist zerschmettert, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Berauschet es, denn wider Jehova hat es großgetan, damit Moab sich wälze in seinem Gespei und auch selbst zum Gelächter werde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Oder war dir Israel nicht zum Gelächter? Oder war es unter Dieben ertappt worden, daß, sooft du von ihm sprachest, du den Kopf schütteltest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Verlasset die Städte und wohnet in den Felsen, ihr Bewohner von Moab, und seid wie die Taube, welche an den Rändern des Abgrundes nistet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Wir haben vernommen den Hochmut Moabs, des sehr hochmütigen, seinen Stolz und seinen Hochmut und seine Hoffart und die Erhebung seines Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Ich kenne wohl sein Wüten, spricht Jehova, und sein eitles Prahlen; unwahr haben sie gehandelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Darum jammere ich über Moab, und wegen ganz Moab schreie ich; über die Leute von Kir-Heres seufzt man.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Mehr als das Weinen Jasers weine ich über dich, du Weinstock von Sibma; deine Ranken gingen über das Meer, sie reichten bis zum Meere von Jaser. Über deine Obsternte und über deine Weinlese ist der Verwüster hergefallen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'und verschwunden sind Freude und Frohlocken aus dem Fruchtgefilde und aus dem Lande Moab. Und dem Weine aus den Kufen habe ich ein Ende gemacht: Man tritt nicht mehr die Kelter unter Jubelruf; der laute Ruf ist kein Jubelruf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Von dem Geschrei Hesbons haben sie bis Elale, bis Jahaz ihre Stimme erschallen lassen, von Zoar bis Horonaim, bis Eglath-Schelischija; denn auch die Wasser von Nimrim sollen zu Wüsten werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Und ich mache ein Ende in Moab, spricht Jehova, dem, der auf die Höhe steigt und seinen Göttern räuchert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Deshalb klagt gleich Flöten mein Herz um Moab, und klagt gleich Flöten mein Herz um die Leute von Kir-Heres. Deshalb geht, was es erübrigt hat, zu Grunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Denn jedes Haupt ist kahl und jeder Bart abgeschoren; auf allen Händen sind Ritze, und Sacktuch ist an den Lenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Auf allen Dächern Moabs und auf seinen Straßen ist lauter Klage; denn ich habe Moab zerbrochen wie ein Gefäß, an dem man kein Gefallen hat, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Wie ist es bestürzt! Sie heulen. Wie hat Moab den Rücken gewandt vor Scham! Und allen seinen Umwohnern wird Moab zum Gelächter und zur Bestürzung sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Denn so spricht Jehova: Siehe, wie der Adler fliegt er daher und breitet seine Flügel aus über Moab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kerijoth ist eingenommen, und die Festen sind erobert. Und das Herz der Helden Moabs wird an selbigem Tage sein wie das Herz eines Weibes in Kindesnöten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Und Moab wird vertilgt werden, daß es kein Volk mehr sei, weil es großgetan hat wider Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Grauen und Grube und Garn über dich, du Bewohner von Moab! spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Wer vor dem Grauen flieht, wird in die Grube fallen, und wer aus der Grube heraufsteigt, wird in dem Garne gefangen werden; denn ich bringe über dasselbe, über Moab, das Jahr seiner Heimsuchung, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Im Schatten Hesbons bleiben Flüchtlinge kraftlos stehen; denn ein Feuer ist ausgegangen von Hesbon und eine Flamme aus der Mitte Sihons, und hat die Seite Moabs verzehrt und den Scheitel der Söhne des Getümmels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Wehe dir, Moab! Verloren ist das Volk des Kamos! Denn deine Söhne sind als Gefangene weggeführt, und deine Töchter in die Gefangenschaft. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Aber ich werde die Gefangenschaft Moabs wenden am Ende der Tage, spricht Jehova. Bis hierher das Gericht über Moab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Über die Kinder Ammon. So spricht Jehova: Hat denn Israel keine Söhne, oder hat es keinen Erben? Warum hat ihr König Gad in Besitz genommen, und warum wohnt sein Volk in dessen Städten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Darum siehe, Tage kommen, spricht Jehova, da ich wider Rabba der Kinder Ammon Kriegsgeschrei werde erschallen lassen; und es soll zum Schutthaufen werden, und seine Tochterstädte sollen mit Feuer verbrannt werden. Und Israel wird seine Erben beerben, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Heule, Hesbon, denn Ai ist verwüstet! Schreiet, ihr Töchter von Rabba, gürtet euch Sacktuch um; klaget und laufet hin und her in den Einzäunungen! Denn ihr König wird in die Gefangenschaft gehen, seine Priester und seine Fürsten allzumal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Was rühmst du dich der Täler? Dein Tal zerfließt, du abtrünnige Tochter, die auf ihre Schätze vertraut: \"Wer sollte an mich kommen?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Siehe, ich lasse Schrecken über dich kommen von allen deinen Umwohnern, spricht der Herr, Jehova der Heerscharen; und ihr sollt weggetrieben werden, ein jeder vor sich hin, und niemand wird die Flüchtigen sammeln. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Aber nachher werde ich die Gefangenschaft der Kinder Ammon wenden, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Über Edom. So spricht Jehova der Heerscharen: Ist keine Weisheit mehr in Teman? Ist den Verständigen der Rat entschwunden, ist ihre Weisheit ausgeschüttet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Fliehet, wendet um, verkriechet euch, Bewohner von Dedan! Denn Esaus Verderben habe ich über ihn gebracht, die Zeit, da ich ihn heimsuche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Wenn Winzer über dich kommen, so werden sie keine Nachlese übriglassen; wenn Diebe in der Nacht, so verderben sie nach ihrem Genüge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Denn ich, ich habe Esau entblößt, ich habe seine Verstecke aufgedeckt; und will er sich verbergen, so kann er es nicht. Zerstört sind seine Nachkommen und seine Brüder und seine Nachbarn, und sie sind nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Verlasse deine Waisen, ich werde sie am Leben erhalten; und deine Witwen sollen auf mich vertrauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Denn so spricht Jehova: Siehe, deren Urteil es nicht war, den Becher zu trinken, die müssen ihn trinken; und du solltest der sein, welcher ungestraft bliebe? Du wirst nicht ungestraft bleiben, sondern sicherlich sollst du ihn trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Denn ich habe bei mir geschworen, spricht Jehova, daß Bozra zum Entsetzen, zum Hohne, zur Verwüstung und zum Fluche werden soll, und alle seine Städte zu ewigen Einöden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Eine Kunde habe ich vernommen von Jehova, und ein Bote ist unter die Nationen gesandt: Versammelt euch und kommet über dasselbe, und machet euch auf zum Kriege!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Denn siehe, ich habe dich klein gemacht unter den Nationen, verachtet unter den Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Deine Furchtbarkeit und der Übermut deines Herzens haben dich verführt, der du in Felsenklüften wohnst, den Gipfel des Hügels inne hast. Wenn du dein Nest hoch baust wie der Adler, ich werde dich von dort hinabstürzen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Und Edom soll zum Entsetzen werden; ein jeder, der an demselben vorüberzieht, wird sich entsetzen und zischen über alle seine Plagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Gleich der Umkehrung von Sodom und Gomorra und ihrer Nachbarn, spricht Jehova, wird niemand daselbst wohnen und kein Menschenkind darin weilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Siehe, er steigt herauf, wie ein Löwe von der Pracht des Jordan, wider die feste Wohnstätte; denn ich werde es plötzlich von ihr hinwegtreiben, und den, der auserkoren ist, über sie bestellen. Denn wer ist mir gleich, und wer will mich vorladen? Und wer ist der Hirt, der vor mir bestehen könnte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Darum höret den Ratschluß Jehovas, welchen er beschlossen hat über Edom, und seine Gedanken, die er denkt über die Bewohner von Teman: Wahrlich, man wird sie fortschleppen, die Geringen der Herde; wahrlich, ihre Trift wird sich über sie entsetzen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Von dem Getöse ihres Falles erbebt die Erde; Geschrei, am Schilfmeere wird sein Schall vernommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Siehe, wie der Adler zieht er herauf und fliegt und breitet seine Flügel aus über Bozra; und das Herz der Helden Edoms wird an selbigem Tage sein wie das Herz eines Weibes in Kindesnöten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Über Damaskus. Beschämt sind Hamath und Arpad; denn sie haben eine böse Kunde vernommen, sie verzagen. Am Meere ist Bangigkeit, ruhen kann man nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damaskus ist schlaff geworden; es hat sich umgewandt, um zu fliehen, und Schrecken hat es ergriffen; Angst und Wehen haben es erfaßt, der Gebärenden gleich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Wie ist es, daß sie nicht verlassen ist, die Stadt des Ruhmes, die Stadt meiner Freude?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Darum werden ihre Jünglinge auf ihren Straßen fallen und alle Kriegsmänner umkommen an selbigem Tage, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Und ich werde ein Feuer anzünden in den Mauern von Damaskus, und es wird die Paläste Ben-Hadads verzehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Über Kedar und über die Königreiche Hazors, welche Nebukadrezar, der König von Babel, schlug. So spricht Jehova: Machet euch auf, ziehet hinauf wider Kedar und zerstöret die Kinder des Ostens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Ihre Zelte und ihr Kleinvieh werden sie nehmen, ihre Zeltbehänge und alle ihre Geräte und ihre Kamele sich wegführen, und werden über sie ausrufen: Schrecken ringsum!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Fliehet, flüchtet schnell, verkriechet euch, Bewohner von Hazor! spricht Jehova; denn Nebukadrezar, der König von Babel, hat einen Ratschluß wider euch beschlossen und einen Anschlag wider euch ersonnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Machet euch auf, ziehet hinauf wider eine sorglose Nation, die in Sicherheit wohnt! spricht Jehova: Sie hat weder Tore noch Riegel, sie wohnen allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Und ihre Kamele sollen zum Raube und die Menge ihrer Herden zur Beute werden; und ich werde sie, die mit geschorenen Haarrändern, nach allen Winden hin zerstreuen, und werde ihr Verderben bringen von allen Seiten her, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Und Hazor wird zur Wohnung der Schakale werden, zur Wüste in Ewigkeit; niemand wird daselbst wohnen und kein Menschenkind darin weilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Das Wort Jehovas, welches zu Jeremia, dem Propheten, geschah über Elam, im Anfang der Regierung Zedekias, des Königs von Juda, indem er sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'So spricht Jehova der Heerscharen: Siehe, ich zerbreche den Bogen Elams, seine vornehmste Stärke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Und ich werde die vier Winde von den vier Enden des Himmels her über Elam bringen und es nach allen diesen Winden hin zerstreuen; und es soll keine Nation geben, wohin nicht Vertriebene Elams kommen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Und ich werde Elam verzagt machen vor ihren Feinden und vor denen, welche nach ihrem Leben trachten, und werde Unglück über sie bringen, die Glut meines Zornes, spricht Jehova; und ich werde das Schwert hinter ihnen her senden, bis ich sie vernichtet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Und ich werde meinen Thron in Elam aufstellen und werde König und Fürsten daraus vertilgen, spricht Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Aber es wird geschehen am Ende der Tage, da werde ich die Gefangenschaft Elams wenden, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Das Wort, welches Jehova über Babel, über das Land der Chaldäer, durch den Propheten Jeremia geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Verkündiget es unter den Nationen und laßt es hören, und erhebet ein Panier; laßt es hören, verhehlet es nicht! Sprechet: Babel ist eingenommen, Bel zu Schanden geworden, Merodak bestürzt; ihre Götzenbilder sind zu Schanden geworden, ihre Götzen sind bestürzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Denn wider dasselbe ist eine Nation heraufgezogen von Norden her: Diese wird sein Land zur Wüste machen, daß kein Bewohner mehr darin sein wird; sowohl Menschen als Vieh sind entflohen, weggezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'In jenen Tagen und zu jener Zeit, spricht Jehova, werden die Kinder Israel kommen, sie und die Kinder Juda zusammen; fort und fort weinend werden sie gehen und Jehova, ihren Gott, suchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Sie werden nach Zion fragen, indem ihr Angesicht dahin gerichtet ist: Kommet und schließet euch an Jehova an mit einem ewigen Bunde, der nicht vergessen werde! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Mein Volk war eine verlorene Schafherde: ihre Hirten leiteten sie irre auf verführerische Berge; sie gingen von Berg zu Hügel, vergaßen ihre Lagerstätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Alle, die sie fanden, fraßen sie; und ihre Feinde sprachen: Wir verschulden uns nicht, weil sie gegen Jehova gesündigt haben, die Wohnung der Gerechtigkeit, und gegen Jehova, die Erwartung ihrer Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Flüchtet aus Babel hinaus, und ziehet aus dem Lande der Chaldäer; und seid wie die Böcke vor der Herde her!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Denn siehe, ich erwecke und führe herauf wider Babel eine Versammlung großer Nationen aus dem Lande des Nordens, und sie werden sich wider dasselbe aufstellen: Von dort aus wird es eingenommen werden. Ihre Pfeile sind wie die eines geschickten Helden, keiner kehrt leer zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Und Chaldäa wird zum Raube werden; alle, die es berauben, werden satt werden, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Denn möget ihr euch auch freuen, denn möget ihr auch frohlocken, Plünderer meines Erbteils, denn möget ihr auch hüpfen wie eine dreschende junge Kuh, und wiehern gleich starken Rossen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Sehr beschämt ist eure Mutter, zu Schanden geworden eure Gebärerin. Siehe, es ist die letzte der Nationen, eine Wüste, eine Dürre und eine Steppe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Vor dem Grimm Jehovas wird es nicht mehr bewohnt werden, sondern eine Wüste sein ganz und gar. Ein jeder, der an Babel vorüberzieht, wird sich entsetzen und zischen über alle seine Plagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Stellet euch ringsum auf wider Babel, alle, die ihr den Bogen spannet; schießet nach ihm, schonet die Pfeile nicht! Denn gegen Jehova hat es gesündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Erhebet ein Schlachtgeschrei gegen dasselbe ringsum! Es hat sich ergeben; gefallen sind seine Festungswerke, niedergerissen seine Mauern. Denn es ist die Rache Jehovas. Rächet euch an ihm, tut ihm, wie es getan hat!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Rottet aus Babel den Säemann aus und den, der die Sichel führt zur Erntezeit! Vor dem verderbenden Schwerte wird ein jeder zu seinem Volke sich wenden und ein jeder in sein Land fliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israel ist ein versprengtes Schaf, welches Löwen verscheucht haben. Zuerst hat der König von Assyrien es gefressen, und nun zuletzt hat Nebukadrezar, der König von Babel, ihm die Knochen zermalmt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Darum spricht Jehova der Heerscharen, der Gott Israels, also: Siehe, ich suche heim den König von Babel und sein Land, gleichwie ich den König von Assyrien heimgesucht habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Und ich will Israel zu seiner Trift zurückbringen, daß es den Karmel und Basan beweide, und seine Seele sich sättige auf dem Gebirge Ephraim und in Gilead.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'In jenen Tagen und zu jener Zeit, spricht Jehova, wird Israels Missetat gesucht werden, und sie wird nicht da sein, und die Sünden Judas, und sie werden nicht gefunden werden; denn ich will denen vergeben, die ich übriglasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Wider das Land \"Doppelte Widerspenstigkeit\", wider dasselbe ziehe hinauf und gegen die Bewohner von \"Heimsuchung\". Verwüste und vertilge hinter ihnen her, spricht Jehova, und tue nach allem, was ich dir geboten habe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Kriegslärm im Lande und große Zertrümmerung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Wie ist zerhauen und zertrümmert der Hammer der ganzen Erde! Wie ist Babel zum Entsetzen geworden unter den Nationen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Ich habe dir Schlingen gelegt, und du wurdest auch gefangen, Babel, ohne daß du es wußtest; du wurdest gefunden und auch ergriffen, weil du dich wider Jehova in Krieg eingelassen hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Jehova hat seine Rüstkammer aufgetan und hervorgeholt die Waffen seines Grimmes; denn der Herr, Jehova der Heerscharen, hat ein Werk in dem Lande der Chaldäer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Kommet über dasselbe von allen Seiten her, öffnet seine Scheunen, schüttet es auf wie Garbenhaufen und vertilget es; nicht bleibe ihm ein Überrest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Erwürget alle seine Farren, zur Schlachtung sollen sie hinstürzen! Wehe über sie! Denn ihr Tag ist gekommen, die Zeit ihrer Heimsuchung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Horch! Flüchtlinge und Entronnene aus dem Lande Babel, um in Zion zu verkünden die Rache Jehovas, unseres Gottes, die Rache seines Tempels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Rufet Schützen herbei wider Babel, alle, die den Bogen spannen! Belagert es ringsum, niemand entrinne! Vergeltet ihm nach seinem Werke, tut ihm nach allem, was es getan hat; denn es hat vermessen gehandelt gegen Jehova, gegen den Heiligen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Darum sollen seine Jünglinge auf seinen Straßen fallen und alle seine Kriegsmänner umkommen an selbigem Tage, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Siehe, ich will an dich, du Stolze, spricht der Herr, Jehova der Heerscharen; denn gekommen ist dein Tag, die Zeit, da ich dich heimsuche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Dann wird die Stolze straucheln und fallen, und niemand wird sie aufrichten; und ich werde ein Feuer anzünden in ihren Städten, daß es alle ihre Umgebung verzehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'So spricht Jehova der Heerscharen: Die Kinder Israel und die Kinder Juda sind Bedrückte allzumal; und alle, die sie gefangen weggeführt, haben sie festgehalten, haben sich geweigert, sie zu entlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Ihr Erlöser ist stark, Jehova der Heerscharen ist sein Name; er wird ihre Rechtssache gewißlich führen, auf daß er dem Lande Ruhe schaffe und die Bewohner von Babel erzittern mache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Das Schwert über die Chaldäer, spricht Jehova, und über die Bewohner von Babel und über seine Fürsten und über seine Weisen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Das Schwert über die Schwätzer, daß sie zu Narren werden! Das Schwert über seine Helden, daß sie verzagen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Das Schwert über seine Rosse und über seine Wagen und über das ganze Mischvolk, welches in seiner Mitte ist, daß sie zu Weibern werden! Das Schwert über seine Schätze, daß sie geplündert werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Dürre über seine Gewässer, daß sie austrocknen! Denn es ist ein Land der geschnitzten Bilder, und sie rasen durch ihre erschreckenden Götzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Darum werden Wüstentiere mit wilden Hunden darin wohnen, und Strauße darin wohnen; und es soll in Ewigkeit nicht mehr bewohnt werden, und keine Niederlassung sein von Geschlecht zu Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Gleich der Umkehrung Sodoms und Gomorras und ihrer Nachbarn durch Gott, spricht Jehova, wird niemand daselbst wohnen und kein Menschenkind darin weilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Siehe, es kommt ein Volk von Norden her, und eine große Nation und viele Könige machen sich auf von dem äußersten Ende der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Bogen und Wurfspieß führen sie, sie sind grausam und ohne Erbarmen; ihre Stimme braust wie das Meer, und auf Rossen reiten sie: gerüstet wider dich, Tochter Babel, wie ein Mann zum Kriege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Der König von Babel hat die Kunde von ihnen vernommen, und seine Hände sind schlaff geworden; Angst hat ihn ergriffen, Wehen, der Gebärenden gleich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Siehe, er steigt herauf, wie ein Löwe von der Pracht des Jordan, wider die feste Wohnstätte; denn ich werde es plötzlich von ihr hinwegtreiben und den, der auserkoren ist, über sie bestellen. Denn wer ist mir gleich, und wer will mich vorladen? Und wer ist der Hirt, der vor mir bestehen könnte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Darum höret den Ratschluß Jehovas, welchen er über Babel beschlossen hat, und seine Gedanken, die er denkt über das Land der Chaldäer: Wahrlich, man wird sie fortschleppen, die Geringen der Herde; wahrlich, die Trift wird sich über sie entsetzen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Von dem Rufe: Babel ist erobert! erzittert die Erde und wird ein Geschrei unter den Nationen vernommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'So spricht Jehova: Siehe, ich erwecke wider Babel und gegen die, welche im Herzen meiner Widersacher wohnen, einen verderbenden Wind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Und ich sende nach Babel Fremde, die es worfeln und sein Land ausleeren werden; denn sie werden ringsumher wider dasselbe sein am Tage des Unglücks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Der Schütze spanne seinen Bogen gegen den, der da spannt, und gegen den, der sich in seinem Panzer erhebt; und schonet seiner Jünglinge nicht, vertilget sein ganzes Kriegsheer!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Und Erschlagene sollen fallen im Lande der Chaldäer und Durchbohrte auf seinen Straßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Denn nicht verwitwet ist Israel noch Juda von seinem Gott, von Jehova der Heerscharen; denn jener Land ist voll Schuld wegen des Heiligen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Fliehet aus Babel hinaus und rettet ein jeder sein Leben, werdet nicht vertilgt wegen seiner Ungerechtigkeit! Denn es ist die Zeit der Rache Jehovas: Was es getan hat, vergilt er ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Babel war ein goldener Becher in der Hand Jehovas, der die ganze Erde berauschte; von seinem Weine haben die Nationen getrunken, darum sind die Nationen rasend geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Plötzlich ist Babel gefallen und zertrümmert. Jammert über dasselbe! Holet Balsam für seinen Schmerz; vielleicht wird es geheilt werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, '\"Wir haben Babel heilen wollen, aber es ist nicht genesen. Verlasset es und laßt uns ein jeder in sein Land ziehen; denn sein Gericht reicht bis an den Himmel und erhebt sich bis zu den Wolken.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Jehova hat unsere Gerechtigkeiten ans Licht gebracht; kommt und laßt uns in Zion erzählen die Tat Jehovas, unseres Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Schärfet die Pfeile, fasset den Schild! Jehova hat den Geist der Könige von Medien erweckt; denn wider Babel ist ein Vornehmen, es zu verderben; denn es ist die Rache Jehovas, die Rache seines Tempels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Erhebet das Panier gegen die Mauern von Babel hin, verschärfet die Bewachung, stellet Wächter auf, bereitet die Hinterhalte! Denn wie Jehova es sich vorgenommen, also führt er aus, was er über die Bewohner von Babel geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Die du an vielen Wassern wohnst, reich an Schätzen bist, dein Ende ist gekommen, das Maß deines Raubes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Jehova der Heerscharen hat bei sich selbst geschworen: Habe ich dich auch mit Menschen gefüllt wie mit Heuschrecken, so wird man doch Triumphgeschrei über dich anstimmen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Er hat die Erde gemacht durch seine Kraft, den Erdkreis festgestellt durch seine Weisheit und die Himmel ausgespannt durch seine Einsicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Wenn er beim Schalle des Donners Wasserrauschen am Himmel bewirkt und Dünste aufsteigen läßt vom Ende der Erde, Blitze zum Regen macht und den Wind herausführt aus seinen Vorratskammern: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Dumm wird jeder Mensch, ohne Erkenntnis; beschämt wird jeder Goldschmied über das Götzenbild; denn sein gegossenes Bild ist Lüge, und kein Geist ist in ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Nichtigkeit sind sie, ein Werk des Gespöttes: zur Zeit ihrer Heimsuchung gehen sie zu Grunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Jakobs Teil ist nicht wie diese; denn er ist es, der das All gebildet hat und den Stamm seines Erbteils; Jehova der Heerscharen ist sein Name.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Du bist mir ein Streithammer, eine Kriegswaffe; und mit dir zerschmettere ich Nationen, und mit dir zerstöre ich Königreiche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'und mit dir zerschmettere ich das Roß und seinen Reiter, und mit dir zerschmettere ich den Wagen und seinen Lenker;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'und mit dir zerschmettere ich Mann und Weib, und mit dir zerschmettere ich Greis und Knaben, und mit dir zerschmettere ich Jüngling und Jungfrau;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'und mit dir zerschmettere ich den Hirten und seine Herde, und mit dir zerschmettere ich den Ackersmann und sein Gespann, und mit dir zerschmettere ich Landpfleger und Statthalter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Und ich will Babel und allen Bewohnern Chaldäas all ihr Böses, das sie an Zion verübt haben, vor euren Augen vergelten, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Siehe, ich will an dich, spricht Jehova, du Berg des Verderbens, der die ganze Erde verderbt; und ich will meine Hand wider dich ausstrecken und dich von dem Felsen hinabwälzen und dich zu einem verbrannten Berge machen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'so daß man von dir weder Eckstein noch Grundstein nehmen kann; denn eine ewige Wüstenei sollst du sein, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Erhebet das Panier im Lande, stoßet in die Posaune unter den Nationen! Weihet Nationen wider dasselbe, rufet wider dasselbe die Königreiche Ararat, Minni und Aschkenas herbei; bestellet Kriegsoberste wider dasselbe, lasset Rosse heraufziehen wie furchtbare Heuschrecken!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Weihet Nationen wider dasselbe, die Könige von Medien, dessen Landpfleger und alle seine Statthalter und das ganze Land ihrer Herrschaft!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Da erbebt und erzittert die Erde; denn die Gedanken Jehovas erfüllen sich wider Babel, um das Land Babel zu einer Wüste zu machen, ohne Bewohner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Babels Helden haben aufgehört zu streiten, sie sitzen in den Bergfesten; versiegt ist ihre Kraft, sie sind zu Weibern geworden; man hat ihre Wohnungen angezündet, ihre Riegel sind zerbrochen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Ein Läufer läuft dem anderen entgegen, und der Bote dem Boten, um dem König von Babel die Botschaft zu bringen, daß seine Stadt von allen Seiten her eingenommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'Und die Übergänge sind besetzt, und die Teiche hat man mit Feuer ausgebrannt, und die Kriegsmänner sind erschrocken. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Denn so spricht Jehova der Heerscharen, der Gott Israels: Die Tochter Babel ist wie eine Tenne, zur Zeit, da man sie stampft; noch um ein Kleines, so wird die Zeit der Ernte für sie kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Nebukadrezar, der König von Babel, hat mich gefressen, hat mich vernichtet, hat mich hingestellt als ein leeres Gefäß; er verschlang mich wie ein Ungeheuer, füllte seinen Bauch mit meinen Leckerbissen, stieß mich fort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Die an mir begangene Gewalttat und mein Fleisch komme über Babel, spreche die Bewohnerin von Zion, und mein Blut über die Bewohner von Chaldäa! Spreche Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Darum spricht Jehova also: Siehe, ich will deine Rechtssache führen und deine Rache vollziehen, und ich werde sein Meer austrocknen und seine Quelle versiegen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Und Babel soll zum Steinhaufen, zur Wohnung der Schakale, zum Entsetzen und zum Gezisch werden, ohne Bewohner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Sie brüllen allzumal wie junge Löwen, knurren wie die Jungen der Löwinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Wenn sie erhitzt sind, richte ich ihnen ein Trinkgelage an und berausche sie, auf daß sie frohlocken, und entschlafen zu ewigem Schlafe und nicht mehr erwachen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Gleich Fettschafen, gleich Widdern samt Böcken stürze ich sie hinab zur Schlachtung. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Wie ist Scheschak eingenommen, und erobert der Ruhm der ganzen Erde! Wie ist Babel zum Entsetzen geworden unter den Nationen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Das Meer ist heraufgestiegen über Babel; mit seiner Wellen Brausen ist es bedeckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Seine Städte sind zur Wüste geworden, ein dürres Land und eine Steppe, ein Land, worin niemand wohnt, und durch welches kein Menschenkind zieht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Und ich werde den Bel zu Babel heimsuchen und aus seinem Maule herausnehmen, was er verschlungen hat; und nicht mehr sollen Nationen zu ihm strömen. Auch Babels Mauer ist gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Ziehet aus ihm hinaus, mein Volk, und rettet ein jeder sein Leben vor der Glut des Zornes Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Und daß euer Herz nicht zaghaft werde, und ihr euch nicht fürchtet vor dem Gerüchte, welches im Lande vernommen wird! Denn in dem einen Jahre kommt dieses Gerücht, und in dem Jahre nachher jenes Gerücht und Gewalttat im Lande, Herrscher gegen Herrscher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Darum siehe, Tage kommen, da ich die geschnitzten Bilder Babels heimsuchen werde; und sein ganzes Land wird beschämt werden, und alle seine Erschlagenen werden in seiner Mitte fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Und Himmel und Erde, und alles, was in ihnen ist, werden jubeln über Babel; denn von Norden her kommen ihm die Verwüster, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Wie Babel darauf ausging, daß Erschlagene Israels fielen, also werden wegen Babel Erschlagene der ganzen Erde fallen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Ihr dem Schwert Entronnenen, gehet, bleibet nicht stehen! Gedenket Jehovas aus der Ferne, und Jerusalem komme euch in den Sinn! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Wir sind beschämt worden, denn wir haben Verhöhnung gehört; Schmach hat unser Angesicht bedeckt; denn Fremde sind über die Heiligtümer des Hauses Jehovas gekommen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Darum siehe, Tage kommen, spricht Jehova, da ich seine geschnitzten Bilder heimsuchen werde; und tödlich Verwundete werden ächzen in seinem ganzen Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Wenn auch Babel bis zum Himmel hinaufstiege und die Höhe seiner Stärke befestigte, von mir aus werden ihm Verwüster kommen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Horch! Ein Geschrei aus Babel, und große Zertrümmerung von dem Lande der Chaldäer her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Denn Jehova verwüstet Babel und tilgt aus demselben das laute Getöse; und es brausen seine Wogen wie große Wasser, es erschallt das Geräusch ihres Getöses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Denn über dasselbe, über Babel, kommt ein Verwüster; und seine Helden werden gefangen, ihre Bogen sind zerbrochen. Denn ein Gott der Vergeltung ist Jehova, er wird gewißlich erstatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Und ich berausche seine Fürsten und seine Weisen, seine Landpfleger und seine Statthalter und seine Helden, daß sie entschlafen zu ewigem Schlafe und nicht mehr erwachen, spricht der König, Jehova der Heerscharen ist sein Name.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'So spricht Jehova der Heerscharen: Die Mauern von Babel, die breiten, sollen gänzlich geschleift und seine hohen Tore mit Feuer verbrannt werden. Und so mühen sich Völker vergebens ab, und Völkerschaften fürs Feuer, und sie ermatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Das Wort, welches der Prophet Jeremia Seraja, dem Sohne Nerijas, des Sohnes Machsejas, gebot, als er mit Zedekia, dem König von Juda, im vierten Jahre seiner Regierung nach Babel zog; und Seraja war Reisemarschall.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Und Jeremia schrieb in ein Buch all das Unglück, welches über Babel kommen sollte, alle diese Worte, welche gegen Babel geschrieben sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Und Jeremia sprach zu Seraja: Wenn du nach Babel kommst, so sieh zu und lies alle diese Worte, und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Jehova, du hast gegen diesen Ort geredet, daß du ihn ausrotten werdest, so daß kein Bewohner mehr darin sei, weder Mensch noch Vieh, sondern daß er zu ewigen Wüsteneien werden solle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Und es soll geschehen, wenn du dieses Buch zu Ende gelesen hast, so binde einen Stein daran und wirf es mitten in den Euphrat');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'und sprich: Also wird Babel versinken und nicht wieder emporkommen wegen des Unglücks, welches ich über dasselbe bringe; und sie werden erliegen. Bis hierher die Worte Jeremias.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Einundzwanzig Jahre war Zedekia alt, als er König wurde, und er regierte elf Jahre zu Jerusalem; und der Name seiner Mutter war Hamutal, die Tochter Jeremias, von Libna.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Und er tat, was böse war in den Augen Jehovas, nach allem, was Jojakim getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Denn wegen des Zornes Jehovas erging es Jerusalem und Juda also, bis er sie weggeworfen hatte von seinem Angesicht. Und Zedekia empörte sich gegen den König von Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Und es geschah im neunten Jahre seiner Regierung, im zehnten Monat, am Zehnten des Monats, da kamen Nebukadrezar, der König von Babel, er und sein ganzes Heer, wider Jerusalem und lagerten sich wider dasselbe; und sie bauten Belagerungstürme wider dasselbe ringsumher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Und die Stadt kam in Belagerung bis in das elfte Jahr des Königs Zedekia.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Im vierten Monat, am Neunten des Monats, da nahm der Hunger in der Stadt überhand; und es war kein Brot mehr da für das Volk des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Und die Stadt wurde erbrochen, und alle Kriegsmänner flohen und zogen des Nachts aus der Stadt hinaus auf dem Wege durch das Tor, welches zwischen den beiden Mauern bei dem Garten des Königs war (die Chaldäer aber waren rings um die Stadt her); und sie zogen den Weg zur Ebene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Aber das Heer der Chaldäer jagte dem König nach, und sie erreichten Zedekia in den Ebenen von Jericho; und sein ganzes Heer zerstreute sich von ihm weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Und sie ergriffen den König und führten ihn hinauf zu dem König von Babel, nach Ribla im Lande Hamath; und er sprach das Urteil über ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Und der König von Babel schlachtete die Söhne Zedekias vor seinen Augen, und er schlachtete auch alle Fürsten von Juda zu Ribla.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Und er blendete die Augen Zedekias und band ihn mit ehernen Fesseln; und der König von Babel brachte ihn nach Babel und setzte ihn in Gewahrsam bis zum Tage seines Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Und im fünften Monat, am Zehnten des Monats, das war das neunzehnte Jahr des Königs Nebukadrezar, des Königs von Babel, kam Nebusaradan, der Oberste der Leibwache, der vor dem König von Babel stand, nach Jerusalem;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'und er verbrannte das Haus Jehovas und das Haus des Königs; und alle Häuser von Jerusalem und jedes große Haus verbrannte er mit Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Und das ganze Heer der Chaldäer, welches bei dem Obersten der Leibwache war, riß alle Mauern von Jerusalem ringsum nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Und von den Geringen des Volkes und den Rest des Volkes, die in der Stadt Übriggebliebenen, und die Überläufer, die zum König von Babel übergelaufen waren, und den Rest der Menge führte Nebusaradan, der Oberste der Leibwache, hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Aber von den Geringen des Landes ließ Nebusaradan, der Oberste der Leibwache, zurück zu Weingärtnern und zu Ackersleuten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Und die Chaldäer zerschlugen die ehernen Säulen, die am Hause Jehovas waren, und die Gestelle und das eherne Meer, welche im Hause Jehovas waren; und sie führten alles Erz davon nach Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Und sie nahmen die Töpfe weg und die Schaufeln und die Lichtmesser und die Sprengschalen und die Schalen und alle ehernen Geräte, womit man den Dienst verrichtete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Auch die Becken und die Räucherpfannen und die Sprengschalen und die Töpfe und die Leuchter und die Schalen und die Spendschalen, was von Gold war, das Gold, und was von Silber war, das Silber, nahm der Oberste der Leibwache weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Die zwei Säulen, das eine Meer und die zwölf ehernen Rinder, welche unter demselben waren, und die Gestelle, welche der König Salomo für das Haus Jehovas gemacht hatte: das Erz aller dieser Geräte war nicht zu wägen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Und die Säulen: achtzehn Ellen war die Höhe der einen Säule, und ein Faden von zwölf Ellen umfaßte sie; und ihre Dicke war vier Finger, sie war hohl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Und ein Kapitäl von Erz war darauf, und die Höhe des einen Kapitäls war fünf Ellen; und ein Netzwerk und Granatäpfel waren an dem Kapitäl ringsum: alles von Erz; und desgleichen war die andere Säule, und Granatäpfel daran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Und der Granatäpfel waren sechsundneunzig nach den vier Winden hin; aller Granatäpfel waren hundert am Netzwerk ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Und der Oberste der Leibwache nahm Scheraja, den Oberpriester, und Zephanja, den zweiten Priester, und die drei Hüter der Schwelle:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'und aus der Stadt nahm er einen Kämmerer, der über die Kriegsleute bestellt war, und sieben Männer von denen, welche das Angesicht des Königs sahen, die in der Stadt vorgefunden wurden, und den Schreiber des Heerobersten, welcher das Volk des Landes zum Heere aushob, und sechzig Mann von dem Volke des Landes, die in der Stadt vorgefunden wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Und Nebusaradan, der Oberste der Leibwache, nahm sie und brachte sie zu dem König von Babel nach Ribla.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Und der König von Babel erschlug sie und tötete sie zu Ribla im Lande Hamath. Und so wurde Juda aus seinem Lande weggeführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Dies ist das Volk, welches Nebukadrezar weggeführt hat: Im siebten Jahre dreitausenddreiundzwanzig Juden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'im achtzehnten Jahre Nebukadrezars achthundertzweiunddreißig Seelen aus Jerusalem;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'im dreiundzwanzigsten Jahre Nebukadrezars führte Nebusaradan, der Oberste der Leibwache, von den Juden siebenhundertfünfundvierzig Seelen weg; aller Seelen waren viertausendsechshundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Und es geschah im siebenunddreißigsten Jahre der Wegführung Jojakins, des Königs von Juda, im zwölften Monat, am Fünfundzwanzigsten des Monats, da erhob Ewil-Merodak, der König von Babel, im ersten Jahre seiner Regierung das Haupt Jojakins, des Königs von Juda, und führte ihn aus dem Gefängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Und er redete gütig mit ihm und setzte seinen Stuhl über den Stuhl der Könige, die bei ihm in Babel waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'und er veränderte die Kleider seines Gefängnisses. Und Jojakin aß beständig vor ihm alle Tage seines Lebens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'und sein Unterhalt: Ein beständiger Unterhalt wurde ihm von dem König von Babel gegeben, soviel er täglich bedurfte, bis zum Tage seines Todes, alle Tage seines Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Wie sitzt einsam die volkreiche Stadt, ist einer Witwe gleich geworden die Große unter den Nationen; die Fürstin unter den Landschaften ist zinsbar geworden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Bitterlich weint sie des Nachts, und ihre Tränen sind auf ihren Wangen; sie hat keinen Tröster unter allen, die sie liebten; alle ihre Freunde haben treulos an ihr gehandelt, sind ihr zu Feinden geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Juda ist ausgewandert vor Elend und vor schwerer Dienstbarkeit; es wohnt unter den Nationen, hat keine Ruhe gefunden; seine Verfolger haben es in der Bedrängnis ergriffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Die Wege Zions trauern, weil niemand zum Feste kommt; alle ihre Tore sind öde; ihre Priester seufzen; ihre Jungfrauen sind betrübt, und ihr selbst ist es bitter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Ihre Bedränger sind zum Haupte geworden, ihre Feinde sind wohlgemut; denn Jehova hat sie betrübt wegen der Menge ihrer Übertretungen; vor dem Bedränger her sind ihre Kinder in Gefangenschaft gezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Und von der Tochter Zion ist all ihre Pracht gewichen; ihre Fürsten sind wie Hirsche geworden, die keine Weide finden, und kraftlos gingen sie vor dem Verfolger einher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'In den Tagen ihres Elends und ihres Umherirrens gedenkt Jerusalem all ihrer Kostbarkeiten, die seit den Tagen der Vorzeit waren, da nun ihr Volk durch die Hand des Bedrängers gefallen ist und sie keinen Helfer hat: Die Bedränger sehen sie an, spotten ihres Feierns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jerusalem hat schwer gesündigt, darum ist sie wie eine Unreine geworden; alle, die sie ehrten, verachten sie, weil sie ihre Blöße gesehen haben; auch sie selbst seufzt und wendet sich ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Ihre Unreinigkeit ist an ihren Säumen; sie hat ihr Ende nicht bedacht und ist wunderbar heruntergekommen: Da ist niemand, der sie tröste. Sieh, Jehova, mein Elend, denn der Feind hat großgetan!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Der Bedränger hat seine Hand ausgebreitet über alle ihre Kostbarkeiten; denn sie hat gesehen, daß Nationen in ihr Heiligtum gekommen sind, von welchen du geboten hast: Sie sollen nicht in deine Versammlung kommen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'All ihr Volk seufzt, sucht nach Brot; sie geben ihre Kostbarkeiten für Speise hin, um sich zu erquicken. Sieh, Jehova, und schaue, daß ich verachtet bin!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Merket ihr es nicht, alle, die ihr des Weges ziehet? Schauet und sehet, ob ein Schmerz sei wie mein Schmerz, der mir angetan worden, mir, die Jehova betrübt hat am Tage seiner Zornglut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Aus der Höhe hat er ein Feuer in meine Gebeine gesandt, daß es sie überwältigte; ein Netz hat er meinen Füßen ausgebreitet, hat mich zurückgewendet; er hat mich zur Wüste gemacht, siech den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Angeschirrt durch seine Hand ist das Joch meiner Übertretungen: Sie haben sich verflochten, sind auf meinen Hals gekommen; er hat meine Kraft gebrochen. Der Herr hat mich in Hände gegeben, daß ich mich nicht aufrichten kann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Der Herr hat alle meine Starken weggerafft in meiner Mitte; er hat ein Fest wider mich ausgerufen, um meine Jünglinge zu zerschmettern; der Herr hat der Jungfrau, der Tochter Juda, die Kelter getreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Darüber weine ich, rinnt mein Auge, mein Auge von Wasser; denn fern von mir ist ein Tröster, der meine Seele erquicken könnte; meine Kinder sind vernichtet, denn der Feind hat obgesiegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Zion breitet ihre Hände aus: Da ist niemand, der sie tröste. Jehova hat seine Bedränger ringsum gegen Jakob entboten; wie eine Unreine ist Jerusalem unter ihnen geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Jehova ist gerecht, denn ich bin widerspenstig gegen seinen Mund gewesen. Höret doch, ihr Völker alle, und sehet meinen Schmerz! Meine Jungfrauen und meine Jünglinge sind in die Gefangenschaft gezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Ich rief meinen Liebhabern, sie aber betrogen mich; meine Priester und meine Ältesten sind in der Stadt verschieden, als sie für sich Speise suchten, damit sie ihre Seele erquicken möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Sieh, Jehova, wie mir angst ist! Meine Eingeweide wallen, mein Herz wendet sich um in meinem Innern; denn ich bin sehr widerspenstig gewesen. Draußen hat mich das Schwert der Kinder beraubt, drinnen ist es wie der Tod.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Sie haben gehört, daß ich seufzte: Ich habe niemand, der mich tröstet! Alle meine Feinde haben mein Unglück gehört, haben sich gefreut, daß du es getan hast. Führst du den Tag herbei, den du verkündigt hast, so werden sie sein wie ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Laß alle ihre Bosheit vor dein Angesicht kommen und tue ihnen, wie du mir getan hast wegen aller meiner Übertretungen; denn viele sind meiner Seufzer, und mein Herz ist siech.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Wie umwölkt der Herr in seinem Zorne die Tochter Zion! Er hat die Herrlichkeit Israels vom Himmel zur Erde geworfen, und hat des Schemels seiner Füße nicht gedacht am Tage seines Zornes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Der Herr hat schonungslos vernichtet alle Wohnstätten Jakobs; er hat in seinem Grimme niedergerissen die Festen der Tochter Juda; zu Boden geworfen, entweiht hat er das Königtum und seine Fürsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'In Zornesglut hat er abgehauen jedes Horn Israels; er hat seine Rechte zurückgezogen vor dem Feinde, und hat Jakob in Brand gesteckt wie ein flammendes Feuer, das ringsum frißt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Seinen Bogen hat er gespannt wie ein Feind, hat mit seiner Rechten sich hingestellt wie ein Gegner und alle Lust der Augen getötet; in das Zelt der Tochter Zion hat er seinen Grimm ausgegossen wie Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Der Herr ist wie ein Feind geworden, er hat Israel vernichtet, vernichtet alle ihre Paläste, seine Festen zerstört; und bei der Tochter Juda hat er Seufzen und Stöhnen gemehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Und er hat sein Gehege zerwühlt wie einen Garten, hat den Ort seiner Festversammlung zerstört; Jehova machte in Zion Fest und Sabbath vergessen; und in seines Zornes Grimm verschmähte er König und Priester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Der Herr hat seinen Altar verworfen, sein Heiligtum verschmäht; er hat die Mauern ihrer Prachtgebäude der Hand des Feindes preisgegeben: Sie haben im Hause Jehovas Lärm erhoben wie an einem Festtage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Jehova hat sich vorgenommen, die Mauer der Tochter Zion zu zerstören; er zog die Meßschnur, wandte seine Hand vom Verderben nicht ab; und Wall und Mauer hat er trauern lassen: Zusammen liegen sie kläglich da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'In die Erde gesunken sind ihre Tore, zerstört und zerschlagen hat er ihre Riegel; ihr König und ihre Fürsten sind unter den Nationen, kein Gesetz ist mehr; auch ihre Propheten erlangen kein Gesicht von Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Verstummt sitzen auf der Erde die Ältesten der Tochter Zion; sie haben Staub auf ihr Haupt geworfen, Sacktuch sich umgegürtet; die Jungfrauen Jerusalems haben ihr Haupt zur Erde gesenkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Durch Tränen vergehen meine Augen, meine Eingeweide wallen, meine Leber hat sich zur Erde ergossen: wegen der Zertrümmerung der Tochter meines Volkes, weil Kind und Säugling auf den Straßen der Stadt verschmachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Zu ihren Müttern sagen sie: Wo ist Korn und Wein? indem sie wie tödlich Verwundete hinschmachten auf den Straßen der Stadt, indem ihre Seele sich ergießt in den Busen ihrer Mütter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Was soll ich dir bezeugen, was dir vergleichen, Tochter Jerusalem? Was soll ich dir gleichstellen, daß ich dich tröste, du Jungfrau, Tochter Zion? Denn deine Zertrümmerung ist groß wie das Meer: Wer kann dich heilen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Nichtiges und Ungereimtes haben deine Propheten dir geschaut; und sie deckten deine Ungerechtigkeit nicht auf, um deine Gefangenschaft zu wenden; sondern sie schauten dir Aussprüche der Nichtigkeit und der Vertreibung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Alle, die des Weges ziehen, schlagen über dich die Hände zusammen, sie zischen und schütteln ihren Kopf über die Tochter Jerusalem: \"Ist das die Stadt, von der man sagte: Der Schönheit Vollendung, eine Freude der ganzen Erde?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Alle deine Feinde sperren ihren Mund über dich auf, sie zischen und knirschen mit den Zähnen; sie sprechen: Wir haben sie verschlungen; fürwahr, dies ist der Tag, den wir erhofft haben: Wir haben ihn erreicht, gesehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Jehova hat getan, was er beschlossen, hat sein Wort erfüllt, das er von den Tagen der Vorzeit her entboten hat. Er hat schonungslos niedergerissen und den Feind sich über dich freuen lassen, hat das Horn deiner Bedränger erhöht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Ihr Herz schreit zu dem Herrn. Du Mauer der Tochter Zion, laß, einem Bache gleich, Tränen rinnen Tag und Nacht; gönne dir keine Rast, deinem Augapfel keine Ruhe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Mache dich auf, klage in der Nacht beim Beginn der Nachtwachen, schütte dein Herz aus wie Wasser vor dem Angesicht des Herrn; hebe deine Hände zu ihm empor für die Seele deiner Kinder, die vor Hunger verschmachten an allen Straßenecken!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Sieh, Jehova, und schaue, wem du also getan hast! Sollen Weiber ihre Leibesfrucht essen, die Kindlein, welche sie auf den Händen tragen? Sollen im Heiligtum des Herrn ermordet werden Priester und Prophet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Knaben und Greise liegen am Boden auf den Straßen; meine Jungfrauen und meine Jünglinge sind durchs Schwert gefallen; hingemordet hast du am Tage deines Zornes, geschlachtet ohne Schonung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Meine Schrecknisse hast du von allen Seiten herbeigerufen wie an einem Festtage, und nicht einer entrann oder blieb übrig am Tage des Zornes Jehovas; die ich auf den Händen getragen und erzogen habe, mein Feind hat sie vernichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Ich bin der Mann, der Elend gesehen durch die Rute seines Grimmes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Mich hat er geleitet und geführt in Finsternis und Dunkel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Nur gegen mich kehrt er immer wieder seine Hand den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Er hat verfallen lassen mein Fleisch und meine Haut, meine Gebeine hat er zerschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Bitterkeit und Mühsal hat er wider mich gebaut und mich damit umringt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Er ließ mich wohnen in Finsternissen, gleich den Toten der Urzeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Er hat mich umzäunt, daß ich nicht herauskommen kann; er hat schwer gemacht meine Fesseln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Wenn ich auch schreie und rufe, so hemmt er mein Gebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Meine Wege hat er mit Quadern vermauert, meine Pfade umgekehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Ein lauernder Bär ist er mir, ein Löwe im Versteck.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Er hat mir die Wege entzogen und hat mich zerfleischt, mich verwüstet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Er hat seinen Bogen gespannt und mich wie ein Ziel dem Pfeile hingestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Er ließ in meine Nieren dringen die Söhne seines Köchers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Meinem ganzen Volke bin ich zum Gelächter geworden, bin ihr Saitenspiel den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Mit Bitterkeiten hat er mich gesättigt, mit Wermut mich getränkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Und er hat mit Kies meine Zähne zermalmt, hat mich niedergedrückt in die Asche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Und du verstießest meine Seele vom Frieden, ich habe des Guten vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Und ich sprach: Dahin ist meine Lebenskraft und meine Hoffnung auf Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Gedenke meines Elends und meines Umherirrens, des Wermuts und der Bitterkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Beständig denkt meine Seele daran und ist niedergebeugt in mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Dies will ich mir zu Herzen nehmen, darum will ich hoffen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Es sind die Gütigkeiten Jehovas, daß wir nicht aufgerieben sind; denn seine Erbarmungen sind nicht zu Ende;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'sie sind alle Morgen neu, deine Treue ist groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Jehova ist mein Teil, sagt meine Seele; darum will ich auf ihn hoffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Gütig ist Jehova gegen die, welche auf ihn harren, gegen die Seele, die nach ihm trachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Es ist gut, daß man still warte auf die Rettung Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Es ist dem Manne gut, daß er das Joch in seiner Jugend trage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Er sitze einsam und schweige, weil er es ihm auferlegt hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'er lege seinen Mund in den Staub; vielleicht gibt es Hoffnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Dem, der ihn schlägt, reiche er den Backen dar, werde mit Schmach gesättigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Denn der Herr verstößt nicht ewiglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'sondern wenn er betrübt hat, erbarmt er sich nach der Menge seiner Gütigkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Denn nicht von Herzen plagt und betrübt er die Menschenkinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Daß man alle Gefangenen der Erde unter seinen Füßen zertrete,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'das Recht eines Mannes beuge vor dem Angesicht des Höchsten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'einem Menschen Unrecht tue in seiner Streitsache: Sollte der Herr nicht darauf achten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Wer ist, der da sprach, und es geschah, ohne daß der Herr es geboten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Das Böse und das Gute, geht es nicht aus dem Munde des Höchsten hervor?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Was beklagt sich der lebende Mensch? Über seine Sünden beklage sich der Mann!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Prüfen und erforschen wir unsere Wege, und laßt uns zu Jehova umkehren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Laßt uns unser Herz samt den Händen erheben zu Gott im Himmel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Wir, wir sind abgefallen und sind widerspenstig gewesen; du hast nicht vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Du hast dich in Zorn gehüllt und hast uns verfolgt; du hast hingemordet ohne Schonung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Du hast dich in eine Wolke gehüllt, so daß kein Gebet hindurchdrang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Du hast uns zum Kehricht und zum Ekel gemacht inmitten der Völker.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Alle unsere Feinde haben ihren Mund gegen uns aufgesperrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Grauen und Grube sind über uns gekommen, Verwüstung und Zertrümmerung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Mit Wasserbächen rinnt mein Auge wegen der Zertrümmerung der Tochter meines Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Mein Auge ergießt sich ruhelos und ohne Rast,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'bis Jehova vom Himmel herniederschaue und dareinsehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Mein Auge schmerzt mich wegen aller Töchter meiner Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Wie einen Vogel haben mich heftig gejagt, die ohne Ursache meine Feinde sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Sie haben mein Leben in die Grube hinein vernichtet und Steine auf mich geworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Wasser strömten über mein Haupt; ich sprach: Ich bin abgeschnitten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Jehova, ich habe deinen Namen angerufen aus der tiefsten Grube.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Du hast meine Stimme gehört; verbirg dein Ohr nicht vor meinem Seufzen, meinem Schreien!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Du hast dich genaht an dem Tage, da ich dich anrief; du sprachst: Fürchte dich nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Herr, du hast die Rechtssachen meiner Seele geführt, hast mein Leben erlöst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Jehova, du hast meine Bedrückung gesehen; verhilf mir zu meinem Rechte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Du hast gesehen alle ihre Rache, alle ihre Anschläge gegen mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Jehova, du hast ihr Schmähen gehört, alle ihre Anschläge wider mich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'das Gerede derer, die wider mich aufgestanden sind, und ihr Sinnen wider mich den ganzen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Schaue an ihr Sitzen und ihr Aufstehen! Ich bin ihr Saitenspiel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Jehova, erstatte ihnen Vergeltung nach dem Werke ihrer Hände!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Gib ihnen Verblendung des Herzens, dein Fluch komme über sie!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Verfolge sie im Zorne und tilge sie unter Jehovas Himmel hinweg!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Wie ward verdunkelt das Gold, verändert das gute, feine Gold! Wie wurden verschüttet die Steine des Heiligtums an allen Straßenecken!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Die Kinder Zions, die kostbaren, die mit gediegenem Golde aufgewogenen, wie sind sie irdenen Krügen gleichgeachtet, dem Werke von Töpferhänden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Selbst Schakale reichen die Brust, säugen ihre Jungen; die Tochter meines Volkes ist grausam geworden wie die Strauße in der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Die Zunge des Säuglings klebt vor Durst an seinem Gaumen; die Kinder fordern Brot, niemand bricht es ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Die von Leckerbissen aßen, verschmachten auf den Straßen; die auf Karmesin getragen wurden, liegen auf Misthaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Und die Schuld der Tochter meines Volkes ist größer geworden als die Sünde Sodoms, welches plötzlich umgekehrt wurde, ohne daß Hände dabei tätig waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Ihre Fürsten waren reiner als Schnee, weißer als Milch; röter waren sie am Leibe als Korallen, wie Saphir ihre Gestalt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Dunkler als Schwärze ist ihr Aussehen, man erkennt sie nicht auf den Straßen; ihre Haut klebt an ihrem Gebein, ist dürr geworden wie Holz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Die vom Schwert Erschlagenen sind glücklicher als die vom Hunger Getöteten, welche hinschmachten, durchbohrt vom Mangel an Früchten des Feldes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Die Hände barmherziger Weiber haben ihre Kinder gekocht; sie wurden ihnen zur Speise bei der Zertrümmerung der Tochter meines Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Jehova hat seinen Grimm vollendet, seine Zornglut ausgegossen; und er hat in Zion ein Feuer angezündet, das seine Grundfesten verzehrt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Die Könige der Erde hätten es nicht geglaubt, noch alle Bewohner des Erdkreises, daß Bedränger und Feind in die Tore Jerusalems kommen würden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Es ist wegen der Sünden seiner Propheten, der Missetaten seiner Priester, welche in seiner Mitte das Blut der Gerechten vergossen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Sie irrten blind auf den Straßen umher; sie waren mit Blut befleckt, so daß man ihre Kleider nicht anrühren mochte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, '\"Weichet! Unrein!\" rief man ihnen zu; \"Weichet, weichet, rühret nicht an!\" Wenn sie flüchteten, so irrten sie umher; man sagte unter den Nationen: Sie sollen nicht länger bei uns weilen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Jehovas Angesicht hat sie zerstreut, er schaut sie nicht mehr an. Auf die Priester hat man keine Rücksicht genommen, an Greisen nicht Gnade geübt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Noch schmachten unsere Augen nach unserer nichtigen Hilfe; in unserem Warten warten wir auf ein Volk, das nicht retten wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Sie stellen unseren Schritten nach, daß wir auf unseren Straßen nicht gehen können. Unser Ende ist nahe, voll sind unsere Tage; ja, unser Ende ist gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Unsere Verfolger waren schneller als die Adler des Himmels; sie jagten uns nach auf den Bergen, in der Wüste lauerten sie auf uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Unser Lebensodem, der Gesalbte Jehovas, wurde in ihren Gruben gefangen, von welchem wir sagten: In seinem Schatten werden wir leben unter den Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Sei fröhlich und freue dich, Tochter Edom, Bewohnerin des Landes Uz! Auch an dich wird der Becher kommen; du wirst trunken werden und dich entblößen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Zu Ende ist deine Schuld, Tochter Zion! Er wird dich nicht mehr wegführen. er wird deine Missetat heimsuchen, Tochter Edom, er wird deine Sünden aufdecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Gedenke, Jehova, dessen, was uns geschehen! Schaue her und sieh unsere Schmach!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Unser Erbteil ist Fremden zugefallen, unsere Häuser Ausländern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Wir sind Waisen, ohne Vater; unsere Mütter sind wie Witwen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Unser Wasser trinken wir um Geld, unser Holz bekommen wir gegen Zahlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Unsere Verfolger sind uns auf dem Nacken; wir ermatten, man läßt uns keine Ruhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Ägypten reichen wir die Hand, und Assyrien, um mit Brot gesättigt zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Unsere Väter haben gesündigt, sie sind nicht mehr; wir, wir tragen ihre Missetaten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Knechte herrschen über uns; da ist niemand, der uns aus ihrer Hand reiße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Wir holen unser Brot mit Gefahr unseres Lebens, wegen des Schwertes der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Vor den Gluten des Hungers brennt unsere Haut wie ein Ofen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Sie haben Weiber geschwächt in Zion, Jungfrauen in den Städten Judas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Fürsten sind durch ihre Hand aufgehängt, das Angesicht der Alten wird nicht geehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Jünglinge tragen die Handmühle, und Knaben straucheln unter dem Holze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Die Alten bleiben fern vom Tore, die Jünglinge von ihrem Saitenspiel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Die Freude unseres Herzens hat aufgehört, in Trauer ist unser Reigen verwandelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Gefallen ist die Krone unseres Hauptes. Wehe uns! Denn wir haben gesündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Darum ist unser Herz siech geworden, um dieser Dinge willen sind unsere Augen verdunkelt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Wegen des Berges Zion, der verwüstet ist; Füchse streifen auf ihm umher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Du, Jehova, thronst in Ewigkeit; dein Thron ist von Geschlecht zu Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Warum willst du uns für immer vergessen, uns verlassen auf immerdar?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Jehova, bringe uns zu dir zurück, daß wir umkehren; erneuere unsere Tage wie vor alters!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Oder solltest du uns gänzlich verworfen haben, gar zu sehr auf uns zürnen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Und es geschah im dreißigsten Jahre, im vierten Monat, am Fünften des Monats, als ich inmitten der Weggeführten war, am Flusse Kebar, da taten sich die Himmel auf, und ich sah Gesichte Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Am Fünften des Monats, das war das fünfte Jahr der Wegführung des Königs Jojakin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'geschah das Wort Jehovas ausdrücklich zu Hesekiel, dem Sohne Busis, dem Priester, im Lande der Chaldäer, am Flusse Kebar; und daselbst kam die Hand Jehovas über ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Und ich sah: und siehe, ein Sturmwind kam von Norden her, eine große Wolke und ein Feuer, sich ineinander schlingend, und ein Glanz rings um dieselbe; und aus seiner Mitte, aus der Mitte des Feuers her, strahlte es wie der Anblick von glänzendem Metall.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Und aus seiner Mitte hervor erschien die Gestalt von vier lebendigen Wesen; und dies war ihr Aussehen: Sie hatten die Gestalt eines Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Und jedes hatte vier Angesichter, und jedes von ihnen hatte vier Flügel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Und ihre Füße waren gerade Füße, und ihre Fußsohlen wie die Fußsohle eines Kalbes; und sie funkelten wie der Anblick von leuchtendem Erze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Und Menschenhände waren unter ihren Flügeln an ihren vier Seiten; und die vier hatten ihre Angesichter und ihre Flügel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Ihre Flügel waren verbunden einer mit dem anderen; sie wandten sich nicht, wenn sie gingen: Sie gingen ein jeder stracks vor sich hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Und die Gestalt ihres Angesichts war eines Menschen Angesicht; und rechts hatten die vier eines Löwen Angesicht, und links hatten die vier eines Stieres Angesicht, und eines Adlers Angesicht hatten die vier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Und ihre Angesichter und ihre Flügel waren oben getrennt; jedes hatte zwei Flügel miteinander verbunden, und zwei, welche ihre Leiber bedeckten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Und sie gingen ein jedes stracks vor sich hin; wohin der Geist gehen wollte, gingen sie; sie wandten sich nicht, wenn sie gingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Und die Gestalt der lebendigen Wesen: Ihr Aussehen war wie brennende Feuerkohlen, wie das Aussehen von Fackeln. Das Feuer fuhr umher zwischen den lebendigen Wesen; und das Feuer hatte einen Glanz, und aus dem Feuer gingen Blitze hervor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Und die lebendigen Wesen liefen hin und her wie das Aussehen von Blitzstrahlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Und ich sah die lebendigen Wesen, und siehe, da war ein Rad auf der Erde neben den lebendigen Wesen, nach ihren vier Vorderseiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Das Aussehen der Räder und ihre Arbeit war wie der Anblick eines Chrysoliths, und die vier hatten einerlei Gestalt; und ihr Aussehen und ihre Arbeit war, wie wenn ein Rad inmitten eines Rades wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Wenn sie gingen, so gingen sie nach ihren vier Seiten hin: Sie wandten sich nicht, wenn sie gingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Und ihre Felgen, sie waren hoch und furchtbar; und ihre Felgen waren voll Augen ringsum bei den vieren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Und wenn die lebendigen Wesen gingen, so gingen die Räder neben ihnen; und wenn die lebendigen Wesen sich von der Erde erhoben, so erhoben sich die Räder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Wohin der Geist gehen wollte, gingen sie, dahin, wohin der Geist gehen wollte; und die Räder erhoben sich neben ihnen, denn der Geist des lebendigen Wesens war in den Rädern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Wenn sie gingen, gingen auch sie, und wenn sie stehen blieben, blieben auch sie stehen; und wenn sie sich von der Erde erhoben, so erhoben sich die Räder neben ihnen; denn der Geist des lebendigen Wesens war in den Rädern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Und über den Häuptern des lebendigen Wesens war das Gebilde einer Ausdehnung, wie der Anblick eines wundervollen Kristalls, ausgebreitet oben über ihren Häuptern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Und unter der Ausdehnung waren ihre Flügel gerade gerichtet, einer gegen den anderen; ein jedes von ihnen hatte zwei Flügel, welche ihre Leiber bedeckten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Und wenn sie gingen, hörte ich das Rauschen ihrer Flügel wie das Rauschen großer Wasser, wie die Stimme des Allmächtigen, das Rauschen eines Getümmels, wie das Rauschen eines Heerlagers. Wenn sie still standen, ließen sie ihre Flügel sinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Und es kam eine Stimme von oberhalb der Ausdehnung, die über ihren Häuptern war. Wenn sie still standen, ließen sie ihre Flügel sinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Und oberhalb der Ausdehnung, die über ihren Häuptern war, war die Gestalt eines Thrones wie das Aussehen eines Saphirsteines; und auf der Gestalt des Thrones eine Gestalt wie das Aussehen eines Menschen oben darauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Und ich sah wie den Anblick von glänzendem Metall, wie das Aussehen von Feuer innerhalb desselben ringsum; von seinen Lenden aufwärts und von seinen Lenden abwärts sah ich wie das Aussehen von Feuer; und ein Glanz war rings um denselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Wie das Aussehen des Bogens, der am Regentage in der Wolke ist, also war das Aussehen des Glanzes ringsum. Das war das Aussehen des Bildes der Herrlichkeit Jehovas. Und als ich es sah, fiel ich nieder auf mein Angesicht; und ich hörte die Stimme eines Redenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Und er sprach zu mir: Menschensohn, stelle dich auf deine Füße, und ich will mit dir reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Und als er zu mir redete, kam der Geist in mich und stellte mich auf meine Füße; und ich hörte den, der zu mir redete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Und er sprach zu mir: Menschensohn, ich sende dich zu den Kindern Israel, zu den empörerischen Nationen, die sich wider mich empört haben; sie und ihre Väter sind von mir abgefallen bis auf diesen selbigen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Und diese Kinder sind schamlosen Angesichts und harten Herzens; zu ihnen sende ich dich, und du sollst zu ihnen sprechen: \"So spricht der Herr, Jehova!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Und sie, mögen sie hören oder es lassen (denn sie sind ein widerspenstiges Haus) sie sollen doch wissen, daß ein Prophet in ihrer Mitte war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Und du, Menschensohn, fürchte dich nicht vor ihnen und fürchte dich nicht vor ihren Worten; denn Nesseln und Dornen sind bei dir, und bei Skorpionen wohnst du. Fürchte dich nicht vor ihren Worten, und erschrick nicht vor ihrem Angesicht; denn ein widerspenstiges Haus sind sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Und du sollst meine Worte zu ihnen reden, mögen sie hören oder es lassen; denn sie sind widerspenstig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Und du, Menschensohn, höre, was ich zu dir rede; sei nicht widerspenstig wie das widerspenstige Haus; tue deinen Mund auf und iß, was ich dir gebe. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Und ich sah: Und siehe, eine Hand war gegen mich ausgestreckt; und siehe, in derselben war eine Buchrolle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Und er breitete sie vor mir aus, und sie war auf der Vorder-und auf der Hinterseite beschrieben; und es waren darauf geschrieben Klagen und Seufzer und Wehe. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Und er sprach zu mir: Menschensohn, iß, was du findest; iß diese Rolle, und geh hin, rede zu dem Hause Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Und ich öffnete meinen Mund, und er gab mir diese Rolle zu essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Und er sprach zu mir: Menschensohn, speise deinen Bauch und fülle deinen Leib mit dieser Rolle, welche ich dir gebe. Und ich aß sie, und sie war in meinem Munde süß wie Honig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Und er sprach zu mir: Menschensohn! Auf, geh hin zu dem Hause Israel und rede zu ihnen mit meinen Worten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Denn nicht zu einem Volke von unverständlicher Sprache und schwieriger Rede bist du gesandt, sondern zum Hause Israel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'nicht zu vielen Völkern von unverständlicher Sprache und schwieriger Rede, deren Worte du nicht verstehst, sondern zu ihnen habe ich dich gesandt; sie können auf dich hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Aber das Haus Israel wird nicht auf dich hören wollen, denn sie wollen nicht auf mich hören. Denn das ganze Haus Israel ist von harter Stirn und verstockten Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Siehe, ich habe dein Angesicht hart gemacht gegenüber ihrem Angesicht, und deine Stirn hart gegenüber ihrer Stirn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'wie einen Diamant, der härter ist als ein Fels, habe ich deine Stirn gemacht. Fürchte sie nicht und erschrick nicht vor ihrem Angesicht, denn ein widerspenstiges Haus sind sie. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Und er sprach zu mir: Menschensohn, alle meine Worte, die ich zu dir reden werde, nimm in dein Herz auf und höre sie mit deinen Ohren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'und mache dich auf, geh hin zu den Weggeführten, zu den Kindern deines Volkes, und rede zu ihnen und sprich zu ihnen: \"So spricht der Herr, Jehova!\" Sie mögen hören oder es lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Und der Geist hob mich empor; und ich hörte hinter mir den Schall eines starken Getöses: \"Gepriesen sei die Herrlichkeit Jehovas von ihrer Stätte her!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'und das Rauschen der Flügel der lebendigen Wesen, welche einander berührten, und das Sausen der Räder neben ihnen, und den Schall eines starken Getöses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Und der Geist hob mich empor und nahm mich hinweg; und ich fuhr dahin, erbittert in der Glut meines Geistes; und die Hand Jehovas war stark auf mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Und ich kam nach Tel-Abib zu den Weggeführten, die am Flusse Kebar wohnten; und daselbst, wo sie saßen, dort saß ich sieben Tage betäubt in ihrer Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Und es geschah am Ende von sieben Tagen, da geschah das Wort Jehovas zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Menschensohn, ich habe dich dem Hause Israel zum Wächter gesetzt; und du sollst das Wort aus meinem Munde hören und sie von meinetwegen warnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Wenn ich zu dem Gesetzlosen spreche: Du sollst gewißlich sterben! und du warnst ihn nicht und redest nicht, um den Gesetzlosen vor seinem gesetzlosen Wege zu warnen, um ihn am Leben zu erhalten, so wird er, der Gesetzlose, wegen seiner Ungerechtigkeit sterben, aber sein Blut werde ich von deiner Hand fordern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Wenn du aber den Gesetzlosen warnst, und er kehrt nicht um von seiner Gesetzlosigkeit und von seinem gesetzlosen Wege, so wird er wegen seiner Ungerechtigkeit sterben; du aber hast deine Seele errettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Und wenn ein Gerechter von seiner Gerechtigkeit umkehrt und unrecht tut, und ich einen Anstoß vor ihn lege, so soll er sterben. Wenn du ihn nicht warnst, so wird er wegen seiner Sünde sterben, und seiner gerechten Taten, die er getan hat, wird nicht gedacht werden; aber sein Blut werde ich von deiner Hand fordern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Wenn du aber ihn, den Gerechten, warnst, damit der Gerechte nicht sündige, und er sündigt nicht, so wird er gewißlich leben, weil er sich hat warnen lassen; und du, du hast deine Seele errettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Und die Hand Jehovas kam daselbst über mich, und er sprach zu mir: Mache dich auf, geh hinaus in das Tal, und dort will ich mit dir reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Und ich machte mich auf und ging hinaus in das Tal; und siehe, daselbst stand die Herrlichkeit Jehovas, gleich der Herrlichkeit, die ich am Flusse Kebar gesehen hatte; und ich fiel nieder auf mein Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Und der Geist kam in mich und stellte mich auf meine Füße. Und er redete mit mir und sprach zu mir: Geh, schließe dich in deinem Hause ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Und du, Menschensohn, siehe, man wird dir Stricke anlegen und dich damit binden, daß du nicht wirst hinausgehen können in ihre Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Und ich werde deine Zunge an deinem Gaumen kleben lassen, damit du verstummest und sie nicht mehr zurechtweisest; denn ein widerspenstiges Haus sind sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Wenn ich aber mit dir reden werde, will ich deinen Mund auftun, und du sollst zu ihnen sprechen: \"So spricht der Herr, Jehova!\" Wer hören will, der höre, und wer es läßt, der lasse es; denn ein widerspenstiges Haus sind sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Und du, Menschensohn, nimm dir einen Ziegelstein und lege ihn vor dich hin, und zeichne darauf eine Stadt, Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Und mache eine Belagerung wider sie, und baue Belagerungstürme wider sie, und schütte wider sie einen Wall auf, und stelle Heerlager wider sie, und errichte Sturmböcke wider sie ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Und du, nimm dir eine eiserne Pfanne und stelle sie als eine eiserne Mauer zwischen dich und die Stadt; und richte dein Angesicht gegen sie, daß sie in Belagerung sei und du sie belagerst. Das sei ein Wahrzeichen dem Hause Israel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Und du, lege dich auf deine linke Seite und lege darauf die Ungerechtigkeit des Hauses Israel: Nach der Zahl der Tage, die du darauf liegst, sollst du ihre Ungerechtigkeit tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Denn ich habe dir die Jahre ihrer Ungerechtigkeit zu einer Anzahl Tage gemacht: Dreihundertneunzig Tage; und du sollst die Ungerechtigkeit des Hauses Israel tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Und hast du diese vollendet, so lege dich zum zweiten auf deine rechte Seite und trage die Ungerechtigkeit des Hauses Juda vierzig Tage; je einen Tag für ein Jahr habe ich dir auferlegt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Und du sollst dein Angesicht und deinen entblößten Arm gegen die Belagerung Jerusalems hin richten, und du sollst wider dasselbe weissagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Und siehe, ich lege dir Stricke an, daß du dich nicht von einer Seite auf die andere wirst umwenden können, bis du die Tage deiner Belagerung vollendet hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Und du, nimm dir Weizen und Gerste und Bohnen und Linsen und Hirse und Spelt, und tue sie in ein Gefäß; und mache dir Brot daraus, nach der Zahl der Tage, die du auf deiner Seite liegst: Dreihundertneunzig Tage sollst du davon essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Und deine Speise, die du essen wirst, soll nach dem Gewicht sein: zwanzig Sekel für den Tag; von Zeit zu Zeit sollst du davon essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Und Wasser sollst du nach dem Maße trinken: ein sechstel Hin; von Zeit zu Zeit sollst du trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Und wie Gerstenkuchen sollst du sie essen, und du sollst sie auf Ballen von Menschenkot vor ihren Augen backen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Und Jehova sprach: Also werden die Kinder Israel ihr Brot unrein essen unter den Nationen, wohin ich sie vertreiben werde. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Da sprach ich: Ach, Herr, Jehova! Siehe, meine Seele ist nie verunreinigt worden, und weder Aas noch Zerrissenes habe ich gegessen von meiner Jugend an bis jetzt, und kein Greuelfleisch ist in meinen Mund gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Und er sprach zu mir: Siehe, ich habe dir Rindermist statt Menschenkot gestattet; und darauf magst du dein Brot bereiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Und er sprach zu mir: Menschensohn, siehe, ich will in Jerusalem den Stab des Brotes zerbrechen; und sie werden Brot essen nach dem Gewicht und in Angst, und Wasser trinken nach dem Maße und in Entsetzen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'weil Brot und Wasser mangeln werden, und sie miteinander verschmachten und in ihrer Ungerechtigkeit hinschwinden werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Und du, Menschensohn, nimm dir ein scharfes Schwert: als Schermesser sollst du es dir nehmen und damit über dein Haupt und über deinen Bart fahren; und nimm dir Waagschalen und teile die Haare.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Ein Drittel sollst du mit Feuer verbrennen inmitten der Stadt, wenn die Tage der Belagerung voll sind; und ein Drittel sollst du nehmen, und rings um sie her mit dem Schwerte schlagen; und ein Drittel sollst du in den Wind streuen, denn ich werde das Schwert ziehen hinter ihnen her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Und du sollst davon eine kleine Zahl nehmen und in deine Rockzipfel binden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Und von diesen sollst du abermals nehmen und sie mitten ins Feuer werfen und sie mit Feuer verbrennen; davon wird ein Feuer ausgehen wider das ganze Haus Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'So spricht der Herr, Jehova: Dieses Jerusalem, inmitten der Nationen habe ich es gesetzt, und Länder rings um dasselbe her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Und es war widerspenstig gegen meine Rechte in Gesetzlosigkeit, mehr als die Nationen, und gegen meine Satzungen, mehr als die Länder, welche rings um dasselbe her sind; denn meine Rechte haben sie verworfen, und in meinen Satzungen haben sie nicht gewandelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Darum spricht der Herr, Jehova, also: Weil ihr getobt habt, mehr als die Nationen, die rings um euch her sind, in meinen Satzungen nicht gewandelt und meine Rechte nicht getan habt, ja, selbst nach den Rechten der Nationen, die rings um euch her sind, nicht getan habt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'darum spricht der Herr, Jehova, also: Siehe, auch ich will wider dich sein, und will Gerichte in deiner Mitte üben vor den Augen der Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Und ich will an dir tun, was ich nicht getan habe und desgleichen ich nicht wieder tun werde, um all deiner Greuel willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Darum werden Väter ihre Kinder essen in deiner Mitte, und Kinder werden ihre Väter essen; und ich will Gerichte an dir üben, und will deinen ganzen Überrest in alle Winde zerstreuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Darum, so wahr ich lebe, spricht der Herr, Jehova: Wahrlich, weil du mein Heiligtum verunreinigt hast durch alle deine Scheusale und durch alle deine Greuel, so will auch ich mein Auge abziehen ohne Mitleid, und auch ich will mich nicht erbarmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Ein Drittel von dir soll an der Pest sterben und durch Hunger umkommen in deiner Mitte; und ein Drittel soll durchs Schwert fallen rings um dich her; und ein Drittel werde ich in alle Winde zerstreuen, und ich werde das Schwert ziehen hinter ihnen her. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Und mein Zorn soll sich vollenden, und meinen Grimm werde ich an ihnen stillen und Rache nehmen. Und wenn ich meinen Grimm an ihnen vollende, so werden sie wissen, daß ich, Jehova, in meinem Eifer geredet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Und ich werde dich zur Einöde machen und zum Hohne unter den Nationen, die rings um dich her sind, vor den Augen jedes Vorübergehenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Und es soll ein Hohn und ein Spott sein, eine Warnung und ein Entsetzen für die Nationen, die rings um dich her sind, wenn ich Gerichte an dir üben werde im Zorn und im Grimm und in Züchtigungen des Grimmes. Ich, Jehova, habe geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Wenn ich die bösen Pfeile des Hungers wider sie sende, welche zum Verderben sein werden, die ich senden werde, um euch zu verderben, so werde ich den Hunger über euch häufen und euch den Stab des Brotes zerbrechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Und ich werde Hunger über euch senden und böse Tiere, daß sie dich der Kinder berauben; und Pest und Blut sollen über dich ergehen, und das Schwert werde ich über dich bringen. Ich, Jehova, habe geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Menschensohn, richte dein Angesicht gegen die Berge Israels, und weissage über sie und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'Berge Israels, höret das Wort des Herrn, Jehovas! So spricht der Herr, Jehova, zu den Bergen und zu den Hügeln, zu den Tälern und zu den Gründen: Siehe, ich, ich bringe das Schwert über euch und werde eure Höhen zerstören;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'und eure Altäre sollen verwüstet und eure Sonnensäulen zerbrochen werden. Und ich werde eure Erschlagenen fallen machen vor euren Götzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'und die Leichname der Kinder Israel werde ich vor ihre Götzen hinlegen und eure Gebeine rings um eure Altäre streuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'In allen euren Wohnsitzen sollen die Städte verödet und die Höhen verwüstet werden, auf daß eure Altäre verödet und wüst, und eure Götzen zerbrochen und vernichtet, und eure Sonnensäulen umgehauen und eure Machwerke vertilgt seien;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'und Erschlagene sollen in eurer Mitte fallen. Und ihr werdet wissen, daß ich Jehova bin. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Doch will ich einen Überrest lassen, indem ihr unter den Nationen solche haben werdet, die dem Schwert entronnen sind, wenn ihr in die Länder zerstreut seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Und eure Entronnenen werden meiner gedenken unter den Nationen, wohin sie gefangen weggeführt sind, wenn ich mir ihr hurerisches Herz, das von mir abgewichen ist, und ihre Augen, die ihren Götzen nachhurten, zerschlagen haben werde; und sie werden an sich selbst Ekel empfinden wegen der Übeltaten, die sie begangen haben nach allen ihren Greueln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Und sie werden wissen, daß ich Jehova bin. Nicht umsonst habe ich geredet, daß ich ihnen dieses Übel tun würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'So spricht der Herr, Jehova: Schlage in deine Hand und stampfe mit deinem Fuße und sprich: Wehe über alle bösen Greuel des Hauses Israel! Denn sie müssen fallen durch das Schwert, durch den Hunger und durch die Pest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Wer fern ist, wird an der Pest sterben, und wer nahe ist, wird durch das Schwert fallen, und wer übriggeblieben und bewahrt worden ist, wird vor Hunger sterben; und ich werde meinen Grimm an ihnen vollenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Und ihr werdet wissen, daß ich Jehova bin, wenn ihre Erschlagenen mitten unter ihren Götzen sein werden, um ihre Altäre her, auf jedem hohen Hügel, auf allen Gipfeln der Berge und unter jedem grünen Baume und unter jeder dichtbelaubten Terebinthe, an den Orten, wo sie allen ihren Götzen lieblichen Geruch dargebracht haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Und ich werde meine Hand wider sie ausstrecken und das Land zur Wüste und Verwüstung machen, mehr als die Wüste Diblath, in allen ihren Wohnsitzen. Und sie werden wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Und du, Menschensohn, so spricht der Herr, Jehova, zum Lande Israel: Es hat ein Ende! Das Ende kommt über die vier Ecken des Landes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Nun kommt das Ende über dich, und ich werde meinen Zorn wider dich senden und dich nach deinen Wegen richten; und alle deine Greuel werde ich über dich bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Und mein Auge wird deiner nicht schonen, und ich werde mich nicht erbarmen; sondern ich will deine Wege über dich bringen, und deine Greuel sollen in deiner Mitte sein. Und ihr werdet wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'So spricht der Herr, Jehova: Unglück, einziges Unglück, siehe, es kommt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Das Ende kommt; es kommt das Ende, es erwacht wider dich; siehe, es kommt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Es kommt das Verhängnis über dich, Bewohner des Landes; es kommt die Zeit, nahe ist der Tag; Getümmel und nicht Jubel auf den Bergen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Jetzt, bald werde ich meinen Grimm über dich ausgießen und meinen Zorn an dir vollenden, und dich nach deinen Wegen richten; und alle deine Greuel werde ich über dich bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Und mein Auge soll nicht schonen, und ich werde mich nicht erbarmen; nach deinen Wegen will ich\'s über dich bringen, und deine Greuel sollen in deiner Mitte sein. Und ihr werdet wissen, daß ich, Jehova, es bin, der schlägt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Siehe, der Tag! Siehe, es kommt! Das Verhängnis wächst hervor; es blüht die Rute, es sproßt der Übermut;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'die Gewalttat erhebt sich zur Rute der Gesetzlosigkeit. Nichts von ihnen wird bleiben, nichts von ihrer Menge und nichts von ihrem Getümmel, und nichts Herrliches an ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Die Zeit kommt, der Tag trifft ein! Der Käufer freue sich nicht, und der Verkäufer betrübe sich nicht; denn Zornglut kommt über seine ganze Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Denn der Verkäufer wird nicht wieder zu dem Verkauften gelangen, und wenn er auch noch am Leben wäre unter den Lebenden; denn das Gesicht wider seine ganze Menge wird nicht rückgängig werden, und niemand wird durch seine Ungerechtigkeit sein Leben befestigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Man stößt in das Horn und macht alles bereit, aber niemand zieht in den Streit; denn meine Zornglut kommt über seine ganze Menge. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Das Schwert ist draußen und die Pest und der Hunger drinnen. Wer auf dem Felde ist, wird durchs Schwert sterben; und wer in der Stadt ist, den werden Hunger und Pest verzehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Und wenn Entronnene von ihnen entrinnen, so werden sie auf den Bergen sein wie die Tauben der Täler, alle girrend, ein jeder wegen seiner Missetat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Alle Hände werden erschlaffen, und alle Knie werden zerfließen wie Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Und sie werden sich Sacktuch umgürten, und Schauder wird sie bedecken, und auf allen Angesichtern wird Scham sein, und Kahlheit auf allen ihren Häuptern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Ihr Silber werden sie auf die Gassen werfen, und ihr Gold wird als Unflat gelten; ihr Silber und ihr Gold wird sie nicht erretten können am Tage des Grimmes Jehovas; ihren Hunger werden sie damit nicht stillen und ihren Bauch davon nicht füllen. Denn es ist ein Anstoß zu ihrer Missetat gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Und seinen zierenden Schmuck, zur Hoffart hat es ihn gebraucht und ihre Greuelbilder, ihre Scheusale, haben sie daraus verfertigt; darum habe ich ihnen denselben zum Unflat gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Und ich will ihn der Hand der Fremden zur Beute geben und den Gesetzlosen der Erde zum Raube, daß sie ihn entweihen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Und ich werde mein Angesicht von ihnen abwenden, daß sie meine verborgene Stätte entweihen; und Gewalttätige werden in dieselbe eindringen und sie entweihen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Verfertige die Kette! Denn das Land ist voll Blutschuld, und die Stadt voll Gewalttat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Und ich werde die bösesten der Nationen kommen lassen, daß sie ihre Häuser in Besitz nehmen; und ich werde der Hoffart der Starken ein Ende machen, daß ihre Heiligtümer entweiht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Schrecken kommt; und sie werden Frieden suchen, aber da ist keiner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Verderben auf Verderben wird kommen, und Gerücht auf Gerücht wird entstehen. Und sie werden von Propheten Gesichte suchen; aber das Gesetz wird dem Priester entschwinden und den Ältesten der Rat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Der König wird trauern, und der Fürst wird sich in Entsetzen kleiden, und die Hände des Volkes des Landes werden zittern. Nach ihren Wegen will ich mit ihnen handeln, und mit ihren Rechten will ich sie richten, und sie werden wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Und es geschah im sechsten Jahre, im sechsten Monat, am Fünften des Monats: Ich saß in meinem Hause, und die Ältesten von Juda saßen vor mir, da fiel daselbst die Hand des Herrn, Jehovas, auf mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Und ich sah: und siehe, eine Gestalt wie das Aussehen von Feuer: Von ihren Lenden abwärts Feuer; und von ihren Lenden aufwärts wie das Aussehen eines Lichtglanzes, wie der Anblick von glänzendem Metall.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Und er streckte das Gebilde einer Hand aus und nahm mich beim Haarschopf meines Hauptes; und der Geist hob mich zwischen Erde und Himmel empor und brachte mich in Gesichten Gottes nach Jerusalem, an den Eingang des Tores des inneren Vorhofs, welches gegen Norden sieht, wo der Standort des Bildes der Eifersucht war, welches zum Eifer reizt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Und siehe, daselbst war die Herrlichkeit des Gottes Israels, gleich dem Gesicht, welches ich im Tale gesehen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Und er sprach zu mir: Menschensohn, hebe nun deine Augen auf gegen Norden! Und ich hob meine Augen auf gegen Norden, und siehe, nördlich vom Tore des Altars war dieses Bild der Eifersucht, am Eingang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Und er sprach zu mir: Menschensohn, siehst du, was sie tun, die großen Greuel, welche das Haus Israel hier verübt, damit ich mich von meinem Heiligtum entferne? Und du sollst noch weiter große Greuel sehen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Und er brachte mich an den Eingang des Vorhofs; und ich sah: Und siehe, ein Loch war in der Mauer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Und er sprach zu mir: Menschensohn, durchbrich doch die Mauer. Und ich durchbrach die Mauer; und siehe, da war eine Tür.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Und er sprach zu mir: Geh hinein und sieh die bösen Greuel, die sie hier verüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Und ich ging hinein und sah: und siehe, da waren allerlei Gebilde von scheußlichem Gewürm und Vieh, und allerlei Götzen des Hauses Israel, ringsumher an die Wand gezeichnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Und siebzig Männer von den Ältesten des Hauses Israel, und Jaasanja, der Sohn Schaphans, in ihrer Mitte stehend, standen davor, jeder mit seinem Räucherfaß in seiner Hand; und der Duft einer Weihrauchwolke stieg empor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Und er sprach zu mir: Hast du gesehen, Menschensohn, was die Ältesten des Hauses Israel im Finstern tun, ein jeder in seinen Bilderkammern? Denn sie sagen: Jehova sieht uns nicht, Jehova hat das Land verlassen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Und er sprach zu mir: Du sollst noch weiter große Greuel sehen, die sie verüben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Und er brachte mich an den Eingang des Tores des Hauses Jehovas, das gegen Norden ist; und siehe, dort saßen die Weiber, welche den Tammuz beweinten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Und er sprach zu mir: Hast du gesehen, Menschensohn? Du sollst weiter noch größere Greuel sehen als diese. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Und er brachte mich in den inneren Vorhof des Hauses Jehovas; und siehe, am Eingang des Tempels Jehovas, zwischen der Halle und dem Altar, waren fünfundzwanzig Männer, ihre Rücken gegen den Tempel Jehovas und ihre Angesichter gegen Osten gerichtet; und sie bückten sich gegen Osten hin vor der Sonne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Und er sprach zu mir: Hast du gesehen, Menschensohn? Ist es dem Hause Juda zu gering, die Greuel zu verüben, die sie hier verüben, daß sie auch das Land mit Gewalttat füllen und mich immer wieder reizen? Denn siehe, sie halten das Reis an ihre Nase.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'So will auch ich handeln im Grimm, mein Auge soll nicht schonen, und ich werde mich nicht erbarmen; und rufen sie auch vor meinen Ohren mit lauter Stimme, so werde ich sie doch nicht hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Und er rief vor meinen Ohren mit lauter Stimme und sprach: Nahet euch, ihr Aufseher der Stadt, ein jeder mit seinem Werkzeug der Zerstörung in seiner Hand!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Und siehe, sechs Männer kamen des Weges vom oberen Tore, welches gegen Norden sieht, ein jeder mit seinem Werkzeug zum Zerschlagen in seiner Hand; und ein Mann war in ihrer Mitte, in Linnen gekleidet, mit einem Schreibzeug an seiner Hüfte; und sie kamen und stellten sich neben den ehernen Altar. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Und die Herrlichkeit des Gottes Israels erhob sich von dem Cherub, über welchem sie war, zu der Schwelle des Hauses hin. Und er rief dem in Linnen gekleideten Manne, der das Schreibzeug an seiner Hüfte hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'und Jehova sprach zu ihm: Geh mitten durch die Stadt, mitten durch Jerusalem, und mache ein Zeichen an die Stirnen der Leute, welche seufzen und jammern über all die Greuel, die in ihrer Mitte geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Und zu jenen sprach er vor meinen Ohren: Gehet hinter ihm her durch die Stadt und schlaget; euer Auge schone nicht, und erbarmet euch nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Mordet bis zur Vertilgung Greise, Jünglinge und Jungfrauen und Kinder und Weiber! Aber nahet euch niemand, an welchem das Zeichen ist; und bei meinem Heiligtum sollt ihr anfangen. Und sie fingen an bei den alten Männern, welche vor dem Hause waren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Und er sprach zu ihnen: Verunreiniget das Haus und füllet die Vorhöfe mit Erschlagenen; gehet hinaus! Und sie gingen hinaus und schlugen in der Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Und es geschah, als sie schlugen, und ich allein übrigblieb, da fiel ich nieder auf mein Angesicht und schrie und sprach: Ach, Herr, Jehova! Willst du den ganzen Überrest Israels verderben, indem du deinen Grimm über Jerusalem ausgießest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Und er sprach zu mir: Die Schuld des Hauses Israel und Juda ist über die Maßen groß, und das Land ist mit Gewalttat erfüllt, und die Stadt ist voll Beugung des Rechts; denn sie sagen: Jehova hat das Land verlassen, und Jehova sieht uns nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'So auch ich, mein Auge soll nicht schonen, und ich werde mich nicht erbarmen; ihren Weg will ich auf ihren Kopf bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Und siehe, der in Linnen gekleidete Mann, welcher das Schreibzeug an seiner Hüfte hatte, brachte Antwort und sprach: Ich habe getan, wie du mir geboten hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Und ich sah: Und siehe, auf der Ausdehnung, die über dem Haupte der Cherubim war, war es wie ein Saphirstein, wie das Aussehen der Gestalt eines Thrones, der über ihnen erschien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Und er sprach zu dem in Linnen gekleideten Manne und sagte: Geh hinein zwischen den Räderwirbel unterhalb des Cherubs, und fülle deine Hände mit Feuerkohlen von dem Raume zwischen den Cherubim, und streue sie über die Stadt hin. Und er ging vor meinen Augen hinein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Die Cherubim aber standen zur rechten Seite des Hauses, als der Mann hineinging; und die Wolke erfüllte den inneren Vorhof.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Und die Herrlichkeit Jehovas hatte sich von dem Cherub auf die Schwelle des Hauses hin erhoben; und das Haus war von der Wolke erfüllt, und der Vorhof war voll von dem Glanze der Herrlichkeit Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Und das Rauschen der Flügel der Cherubim wurde bis in den äußeren Vorhof gehört wie die Stimme Gottes, des Allmächtigen, wenn er redet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Und es geschah, als er dem in Linnen gekleideten Manne gebot und sprach: Nimm Feuer zwischen dem Räderwirbel, zwischen den Cherubim weg, und er hineinging und zur Seite des Rades trat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'da streckte ein Cherub seine Hand zwischen den Cherubim hervor, zu dem Feuer hin, welches zwischen den Cherubim war, und hob es ab und gab es in die Hände dessen, der in Linnen gekleidet war; der nahm es und ging hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Und es erschien an den Cherubim das Gebilde einer Menschenhand unter ihren Flügeln. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Und ich sah: Und siehe, vier Räder waren neben den Cherubim, je ein Rad neben je einem Cherub. Und das Aussehen der Räder war wie der Anblick eines Chrysolithsteines;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'und ihr Aussehen: Die vier hatten einerlei Gestalt, wie wenn ein Rad inmitten eines Rades wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Wenn sie gingen, so gingen sie nach ihren vier Seiten hin: Sie wandten sich nicht, wenn sie gingen; denn nach dem Orte, wohin das Vorderteil gerichtet war, folgten sie demselben: Sie wandten sich nicht, wenn sie gingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Und ihr ganzer Leib und ihr Rücken und ihre Hände und ihre Flügel und die Räder waren voll Augen ringsum; alle vier hatten ihre Räder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Die Räder, sie wurden vor meinen Ohren \"Wirbel\" genannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Und ein jedes hatte vier Angesichter; das Angesicht des ersten war das Angesicht eines Cherubs, und das Angesicht des zweiten das Angesicht eines Menschen, und des dritten das Angesicht eines Löwen, und des vierten das Angesicht eines Adlers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Und die Cherubim hoben sich empor. Das war das lebendige Wesen, welches ich am Flusse Kebar gesehen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Und wenn die Cherubim gingen, so gingen die Räder neben ihnen; und wenn die Cherubim ihre Flügel erhoben, um sich von der Erde emporzuheben, so wandten sich die Räder auch nicht von ihrer Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Wenn sie stehen blieben, blieben auch sie stehen; und wenn sie sich emporhoben, hoben sie sich mit ihnen empor; denn der Geist des lebendigen Wesens war in ihnen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Und die Herrlichkeit Jehovas begab sich von der Schwelle des Hauses hinweg und stellte sich über die Cherubim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Und die Cherubim erhoben ihre Flügel und hoben sich vor meinen Augen von der Erde empor, als sie sich hinwegbegaben; und die Räder waren neben ihnen. Und sie stellten sich an den Eingang des östlichen Tores des Hauses Jehovas, und die Herrlichkeit des Gottes Israels war oben über ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Das war das lebendige Wesen, welches ich unter dem Gott Israels am Flusse Kebar gesehen hatte; und ich erkannte, daß es Cherubim waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Jeder hatte vier Angesichter, und jeder hatte vier Flügel, und das Gebilde von Menschenhänden war unter ihren Flügeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Und was die Gestalt ihrer Angesichter betrifft, so waren es die Angesichter, welche ich am Flusse Kebar gesehen hatte, ihr Aussehen und sie selbst. Sie gingen ein jeder stracks vor sich hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Und der Geist hob mich empor und brachte mich zum östlichen Tore des Hauses Jehovas, welches gegen Osten sieht. Und siehe, an dem Eingang des Tores waren fünfundzwanzig Männer; und ich sah in ihrer Mitte Jaasanja, den Sohn Assurs, und Pelatja, den Sohn Benajas, die Fürsten des Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Und er sprach zu mir: Menschensohn, das sind die Männer, welche Unheil sinnen und bösen Rat erteilen in dieser Stadt, die da sprechen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Es ist nicht an der Zeit, Häuser zu bauen; sie ist der Topf, und wir sind das Fleisch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Darum weissage wider sie; weissage, Menschensohn! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Und der Geist Jehovas fiel auf mich und sprach zu mir: Sprich: So spricht Jehova: Also sprechet ihr, Haus Israel; und was in eurem Geiste aufsteigt, das weiß ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Ihr habt eurer Erschlagenen viele gemacht in dieser Stadt und ihre Straßen mit Erschlagenen gefüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Darum, so spricht der Herr, Jehova: Eure Erschlagenen, die ihr in ihrer Mitte hingestreckt habt, die sind das Fleisch, und sie ist der Topf; euch aber wird man aus ihrer Mitte hinausführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Ihr fürchtet das Schwert; und das Schwert werde ich über euch bringen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Und ich werde euch aus ihrer Mitte hinausführen und euch in die Hand der Fremden geben, und werde Gerichte an euch üben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Durch das Schwert sollt ihr fallen: An der Grenze Israels werde ich euch richten. Und ihr werdet wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Sie wird euch nicht der Topf, und ihr werdet in ihrer Mitte nicht das Fleisch sein: An der Grenze Israels werde ich euch richten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Und ihr werdet wissen, daß ich Jehova bin, ich, in dessen Satzungen ihr nicht gewandelt und dessen Rechte ihr nicht getan habt; sondern ihr habt nach den Rechten der Nationen getan, welche rings um euch her sind. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Und es geschah, als ich weissagte, da starb Pelatja, der Sohn Benajas. Und ich fiel nieder auf mein Angesicht und schrie mit lauter Stimme und sprach: Ach, Herr, Jehova! Willst du dem Überrest Israels den Garaus machen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Menschensohn, deine Brüder, deine Brüder, die Männer deiner Verwandtschaft, sind es und das ganze Haus Israel insgesamt, zu welchen die Bewohner von Jerusalem sprechen: Bleibet fern von Jehova; uns ist das Land zum Besitztum gegeben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Darum sprich: So spricht der Herr, Jehova: Obgleich ich sie unter die Nationen entfernt, und obgleich ich sie in die Länder zerstreut habe, so bin ich ihnen doch ein wenig zum Heiligtum geworden in den Ländern, wohin sie gekommen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Darum sprich: So spricht der Herr, Jehova: Ja, ich werde euch aus den Völkern sammeln und euch zusammenbringen aus den Ländern, in welche ihr zerstreut worden seid, und werde euch das Land Israel geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Und sie werden dorthin kommen und alle seine Scheusale und alle seine Greuel daraus entfernen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Und ich werde ihnen ein Herz geben, und werde einen neuen Geist in euer Inneres geben; und ich werde das steinerne Herz aus ihrem Fleische wegnehmen und ihnen ein fleischernes Herz geben:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'auf daß sie in meinen Satzungen wandeln und meine Rechte bewahren und sie tun; und sie werden mein Volk, und ich werde ihr Gott sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Deren Herz aber nach dem Herzen ihrer Scheusale und ihrer Greuel wandelt: Denen will ich ihren Weg auf ihren Kopf bringen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Und die Cherubim erhoben ihre Flügel, und die Räder waren neben ihnen; und die Herrlichkeit des Gottes Israels war oben über ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Und die Herrlichkeit Jehovas erhob sich aus der Mitte der Stadt und stellte sich auf den Berg, welcher gegen Osten der Stadt ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Und der Geist hob mich empor und brachte mich im Gesicht durch den Geist Gottes zu den Weggeführten nach Chaldäa; und das Gesicht, welches ich gesehen hatte, hob sich von mir weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Und ich redete zu den Weggeführten alle Worte Jehovas, die er mich hatte sehen lassen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Menschensohn, du wohnst inmitten des widerspenstigen Hauses, welche Augen haben zu sehen und nicht sehen, Ohren haben zu hören und nicht hören; denn ein widerspenstiges Haus sind sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Und du, Menschensohn, mache dir Auswanderergeräte und wandere bei Tage vor ihren Augen aus, und du sollst vor ihren Augen von deinem Orte zu einem anderen Orte auswandern: Ob sie vielleicht sehen möchten; denn ein widerspenstiges Haus sind sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Und trage deine Geräte wie Auswanderergeräte bei Tage vor ihren Augen hinaus; und du, ziehe am Abend vor ihren Augen aus, wie man auszieht, um auszuwandern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Vor ihren Augen durchbrich dir die Mauer, und trage sie dadurch hinaus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'vor ihren Augen nimm sie auf die Schulter, in dichter Finsternis trage sie hinaus; du sollst dein Angesicht verhüllen, damit du das Land nicht sehest. Denn ich habe dich zu einem Wahrzeichen gemacht für das Haus Israel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Und ich tat also, wie mir geboten war. Meine Geräte trug ich wie Auswanderergeräte bei Tage hinaus, und am Abend durchbrach ich mir die Mauer mit der Hand; in dichter Finsternis trug ich sie hinaus, ich nahm sie vor ihren Augen auf die Schulter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Und das Wort Jehovas geschah zu mir am Morgen also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Menschensohn, hat nicht das Haus Israel, das widerspenstige Haus, zu dir gesagt: Was tust du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Sprich zu ihnen: So spricht der Herr, Jehova: Den Fürsten in Jerusalem betrifft dieser Ausspruch und das ganze Haus Israel, in dessen Mitte sie sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Sprich: Ich bin ein Wahrzeichen für euch; gleichwie ich getan habe, also soll ihnen getan werden: In die Verbannung, in die Gefangenschaft werden sie gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Und der Fürst, der in ihrer Mitte ist, wird es in dichter Finsternis auf die Schulter nehmen und ausziehen; sie werden die Mauer durchbrechen, um es dadurch hinauszutragen; er wird sein Angesicht verhüllen, auf daß er mit seinen Augen das Land nicht sehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Und ich will mein Netz über ihn ausbreiten, und in meinem Garne wird er gefangen werden; und ich will ihn nach Babel bringen, in das Land der Chaldäer, aber sehen wird er es nicht; und er wird daselbst sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Und alle, die um ihn her sind, seine Hilfe und alle seine Scharen, will ich in alle Winde zerstreuen und das Schwert ziehen hinter ihnen her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Und sie werden wissen, daß ich Jehova bin, wenn ich sie unter die Nationen versprenge und sie in die Länder zerstreue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Und ich werde von ihnen einige Leute übriglassen vom Schwert, vom Hunger und von der Pest, auf daß sie alle ihre Greuel erzählen unter den Nationen, wohin sie kommen werden. Und sie werden wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Menschensohn, mit Beben sollst du dein Brot essen, und mit Zittern und in Angst dein Wasser trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Und sprich zu dem Volke des Landes: So spricht der Herr, Jehova, von den Bewohnern Jerusalems im Lande Israel: In Angst werden sie ihr Brot essen und in Entsetzen ihr Wasser trinken, weil ihr Land veröden wird von seiner Fülle wegen der Gewalttat aller seiner Bewohner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Und die bewohnten Städte werden wüst, und das Land wird eine Einöde werden. Und ihr werdet wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Menschensohn, was ist das für ein Spruch, den ihr im Lande Israel habt, indem ihr sprechet: Die Tage werden sich in die Länge ziehen, und jedes Gesicht wird zunichte werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Darum sprich zu ihnen: So spricht der Herr, Jehova: Ich will diesem Spruche ein Ende machen, und man soll ihn nicht mehr als Spruch gebrauchen in Israel; sondern rede zu ihnen: Nahe sind die Tage und das Wort eines jeden Gesichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Denn kein eitles Gesicht und keine schmeichlerische Wahrsagung wird mehr sein inmitten des Hauses Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Denn ich bin Jehova, ich rede; das Wort, das ich rede, wird auch geschehen, es wird nicht mehr hinausgeschoben werden. Denn in euren Tagen, widerspenstiges Haus, rede ich ein Wort und tue es auch, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Menschensohn, siehe, das Haus Israel spricht: Das Gesicht, welches dieser schaut, ist auf viele Tage hin; und auf ferne Zeiten hin weissagt er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Darum sprich zu ihnen: So spricht der Herr, Jehova: Keines meiner Worte soll mehr hinausgeschoben werden; das Wort, das ich rede, wird auch geschehen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Menschensohn, weissage über die Propheten Israels, die da weissagen, und sprich zu denen, welche aus ihrem Herzen weissagen: Höret das Wort Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'So spricht der Herr, Jehova: Wehe den törichten Propheten, welche ihrem eigenen Geiste nachgehen und dem, was sie nicht gesehen haben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Wie Füchse in den Trümmern sind, Israel, deine Propheten geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'In die Risse seid ihr nicht getreten, und die Mauer habt ihr nicht vermauert um das Haus Israel her, um standzuhalten im Streit am Tage Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Sie schauten Eitles und Lügenwahrsagung, die da sagen: \"Spruch Jehovas!\", obwohl Jehova sie nicht gesandt hat; und sie ließen hoffen, daß ihr Wort erfüllt würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Schautet ihr nicht ein eitles Gesicht, und sprachet ihr nicht Lügenwahrsagung, als ihr sagtet: \"Spruch Jehovas!\", und ich hatte doch nicht geredet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Darum spricht der Herr, Jehova, also: Weil ihr Eitles redet und Lüge schauet, darum, siehe, will ich an euch, spricht der Herr, Jehova;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'und meine Hand wird wider die Propheten sein, die Eitles schauen und Lüge wahrsagen. Im Rate meines Volkes sollen sie nicht stehen, und in das Buch des Hauses Israel nicht eingeschrieben werden, und in das Land Israel sollen sie nicht kommen. Und ihr werdet wissen, daß ich der Herr, Jehova, bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Darum, ja, darum daß sie mein Volk irreführen und sprechen: Friede! obwohl kein Friede da ist; und baut dieses eine Wand, siehe, sie bestreichen sie mit Tünche; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'sprich zu den Übertünchern: Sie soll fallen! Es kommt ein überschwemmender Regen; und ihr Hagelsteine, ihr werdet fallen, und ein Sturmwind wird losbrechen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'und siehe, die Mauer fällt. Wird man euch nicht sagen: Wo ist das Getünchte, das ihr getüncht habt? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Darum, so spricht der Herr, Jehova: Ich will einen Sturmwind losbrechen lassen in meinem Grimm, und ein überschwemmender Regen wird kommen in meinem Zorn, und Hagelsteine im Grimm, zur Vernichtung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Und ich will die Mauer abbrechen, die ihr mit Tünche bestrichen habt, und sie zur Erde niederwerfen, daß ihr Grund entblößt werde; und sie soll fallen, und ihr werdet in ihrer Mitte umkommen. Und ihr werdet wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Und so werde ich meinen Grimm vollenden an der Mauer und an denen, die sie mit Tünche bestreichen; und ich werde zu euch sagen: Die Mauer ist nicht mehr, und die sie tünchten, sind nicht mehr,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'die Propheten Israels, welche über Jerusalem weissagen und für dasselbe Gesichte des Friedens schauen, obwohl kein Friede da ist, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Und du, Menschensohn, richte dein Angesicht wider die Töchter deines Volkes, welche aus ihrem Herzen weissagen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'und weissage wider sie und sprich: So spricht der Herr, Jehova: Wehe denen, welche Binden zusammennähen über alle Gelenke der Hände und Kopfhüllen machen für Häupter jedes Wuchses, um Seelen zu fangen! Die Seelen meines Volkes fanget ihr, und eure Seelen erhaltet ihr am Leben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Und ihr entheiliget mich bei meinem Volke für einige Hände voll Gerste und für einige Bissen Brotes, indem ihr Seelen tötet, die nicht sterben, und Seelen am Leben erhaltet, die nicht leben sollten; indem ihr mein Volk belüget, das auf Lügen hört? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Darum spricht der Herr, Jehova, also: Siehe, ich will an eure Binden, mit welchen ihr fanget, will die Seelen wegfliegen lassen und sie von euren Armen wegreißen; und ich will die Seelen freilassen, die ihr fanget, die Seelen, daß sie wegfliegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Und ich werde eure Kopfhüllen zerreißen und mein Volk aus eurer Hand erretten, damit sie nicht mehr zur Beute werden in eurer Hand. Und ihr werdet wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Weil ihr das Herz des Gerechten mit Lüge kränket, da ich ihn doch nicht betrübt habe, und weil ihr die Hände des Gesetzlosen stärket, damit er von seinem bösen Wege nicht umkehre, um sein Leben zu erhalten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'darum sollt ihr nicht mehr Eitles schauen und nicht ferner Wahrsagerei treiben; und ich werde mein Volk aus eurer Hand erretten. Und ihr werdet wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Und es kamen Männer von den Ältesten Israels zu mir, und sie setzten sich vor mir nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Menschensohn, diese Männer haben ihre Götzen in ihrem Herzen aufkommen lassen und den Anstoß zu ihrer Missetat vor ihr Angesicht gestellt; sollte ich mich wohl von ihnen befragen lassen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Darum rede mit ihnen und sprich zu ihnen: So spricht der Herr, Jehova: Jedermann aus dem Hause Israel, der seine Götzen in seinem Herzen aufkommen läßt und den Anstoß zu seiner Missetat vor sein Angesicht stellt, und zu dem Propheten kommt ich, Jehova, werde ihm demgemäß antworten, gemäß der Menge seiner Götzen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'damit ich das Haus Israel an seinem Herzen fasse, weil sie allesamt durch ihre Götzen von mir abgewichen sind. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Darum sprich zum Hause Israel: So spricht der Herr, Jehova: Kehret um, und wendet euch ab von euren Götzen, und wendet von allen euren Greueln euer Angesicht ab!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Denn jedermann aus dem Hause Israel und von den Fremdlingen, die in Israel weilen, welcher sich von mir trennt und seine Götzen in seinem Herzen aufkommen läßt und den Anstoß zu seiner Missetat vor sein Angesicht stellt, und zu dem Propheten kommt, um mich für sich zu befragen ich, Jehova, werde ihm in meiner Weise antworten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Und ich werde mein Angesicht wider selbigen Mann richten, und werde ihn zu einem Denkzeichen und zu Sprichwörtern machen; und ich werde ihn ausrotten aus der Mitte meines Volkes. Und ihr werdet wissen, daß ich Jehova bin. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Wenn aber der Prophet sich bereden läßt und ein Wort redet, so habe ich, Jehova, diesen Propheten beredet; und ich werde meine Hand wider ihn ausstrecken und ihn aus der Mitte meines Volkes Israel vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Und so sollen sie ihre Schuld tragen; wie die Schuld des Fragenden, also wird die Schuld des Propheten sein:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'damit das Haus Israel nicht mehr von mir abirre und sie sich nicht mehr durch alle ihre Übertretungen verunreinigen; und sie werden mein Volk, und ich werde ihr Gott sein, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Menschensohn, wenn ein Land gegen mich sündigt, indem es Treulosigkeit begeht, und ich meine Hand wider dasselbe ausstrecke, und ihm den Stab des Brotes zerbreche und Hunger darein sende, und Menschen und Vieh darin ausrotte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'und diese drei Männer wären in demselben: Noah, Daniel und Hiob, sie würden durch ihre Gerechtigkeit nur ihre eigene Seele erretten, spricht der Herr, Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Wenn ich böse Tiere in das Land bringe, damit sie es entvölkern und es eine Wüste werde, so daß wegen der Tiere niemand hindurchzieht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'Wären diese drei Männer in demselben, so wahr ich lebe, spricht der Herr, Jehova, sie würden weder Söhne noch Töchter erretten können; sie allein würden errettet, das Land aber würde eine Wüste werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Oder wenn ich das Schwert über selbiges Land bringe und spreche: Schwert, fahre durch das Land! und Menschen und Vieh darin ausrotte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'und diese drei Männer wären in demselben: So wahr ich lebe, spricht der Herr, Jehova, sie würden weder Söhne noch Töchter erretten können; sondern sie allein würden errettet werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Oder wenn ich die Pest in selbiges Land sende, und meinen Grimm in Blut über dasselbe ausgieße, um Menschen und Vieh darin auszurotten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'und Noah, Daniel und Hiob wären in demselben: So wahr ich lebe, spricht der Herr, Jehova, sie würden weder Sohn noch Tochter erretten können; sie würden durch ihre Gerechtigkeit nur ihre eigene Seele erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Denn so spricht der Herr, Jehova: Wieviel mehr, wenn ich meine vier bösen Gerichte, Schwert und Hunger und böse Tiere und die Pest, gegen Jerusalem entsenden werde, um Menschen und Vieh darin auszurotten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Doch siehe, Entronnene sollen darin übrigbleiben, die herausgeführt werden, Söhne und Töchter; siehe, sie werden zu euch hinausziehen, und ihr werdet ihren Weg und ihre Handlungen sehen; und ihr werdet euch trösten über das Unglück, welches ich über Jerusalem gebracht, alles, was ich über dasselbe gebracht habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'Und sie werden euch trösten, wenn ihr ihren Weg und ihre Handlungen sehen werdet; und ihr werdet erkennen, daß ich nicht ohne Ursache alles getan habe, was ich an ihm getan, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Menschensohn, was ist das Holz des Weinstocks mehr als alles andere Holz, die Rebe, welche unter den Bäumen des Waldes war?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Wird Holz davon genommen, um es zu einer Arbeit zu verwenden? Oder nimmt man davon einen Pflock, um irgend ein Gerät daran zu hängen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Siehe, es wird dem Feuer zur Speise gegeben. Hat das Feuer seine beiden Enden verzehrt und ist seine Mitte versengt, wird es zu einer Arbeit taugen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Siehe, wenn es unversehrt ist, wird es zu keiner Arbeit verwendet; wieviel weniger, wenn das Feuer es verzehrt hat und es versengt ist, kann es noch zu einer Arbeit verwendet werden! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Darum, so spricht der Herr, Jehova: Wie das Holz des Weinstocks unter den Bäumen des Waldes, welches ich dem Feuer zur Speise gebe, also gebe ich die Bewohner von Jerusalem dahin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'und ich werde mein Angesicht wider sie richten: Aus dem Feuer kommen sie heraus, und Feuer wird sie verzehren. Und ihr werdet wissen, daß ich Jehova bin, wenn ich mein Angesicht wider sie richte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Und ich werde das Land zur Wüste machen, weil sie Treulosigkeit begangen haben, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Menschensohn, tue Jerusalem seine Greuel kund und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'So spricht der Herr, Jehova, zu Jerusalem: Dein Ursprung und deine Abstammung ist aus dem Lande der Kanaaniter; dein Vater war ein Amoriter, und deine Mutter eine Hethiterin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Und was deine Geburt betrifft, an dem Tage, da du geboren wurdest, wurde dein Nabel nicht abgeschnitten, und du wurdest nicht in Wasser gebadet zur Reinigung, und nicht mit Salz abgerieben, und nicht in Windeln gewickelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Kein Auge blickte mitleidig auf dich hin, um dir eines dieser Dinge zu tun, um sich deiner zu erbarmen; und du wurdest auf das freie Feld geworfen, vor Abscheu an deinem Leben, an dem Tage, da du geboren wurdest. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Da ging ich an dir vorüber und sah dich zappeln in deinem Blute; und ich sprach zu dir: In deinem Blute lebe! Und ich sprach zu dir: In deinem Blute lebe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Zu Zehntausenden, wie das Gewächs des Feldes, machte ich dich; und du wuchsest heran und wurdest groß, und du gelangtest zu höchster Anmut; die Brüste rundeten sich, und dein Haar wuchs; aber du warst nackt und bloß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Und ich ging an dir vorüber und sah dich, und siehe, deine Zeit war die Zeit der Liebe; und ich breitete meinen Zipfel über dich aus, und bedeckte deine Blöße; und ich schwur dir und trat in einen Bund mit dir, spricht der Herr, Jehova, und du wurdest mein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Und ich badete dich in Wasser, und spülte dein Blut von dir ab, und salbte dich mit Öl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Und ich bekleidete dich mit Buntgewirktem und beschuhte dich mit Seekuhfellen, und ich umwand dich mit Byssus und bedeckte dich mit Seide;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'und ich schmückte dich mit Schmuck: Ich legte Armringe an deine Hände und eine Kette um deinen Hals,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'und legte einen Reif in deine Nase und Ringe in deine Ohren, und setzte eine Prachtkrone auf dein Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Und so wurdest du mit Gold und Silber geschmückt, und deine Kleidung war Byssus und Seide und Buntgewirktes; du aßest Feinmehl und Honig und Öl. Und du warst überaus schön und gelangtest zum Königtum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Und dein Ruf ging aus unter die Nationen wegen deiner Schönheit; denn sie war vollkommen durch meine Herrlichkeit, die ich auf dich gelegt hatte, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Aber du vertrautest auf deine Schönheit, und du hurtest auf deinen Ruf hin und gossest deine Hurereien aus über jeden Vorübergehenden: Ihm ward sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Und du nahmst von deinen Kleidern und machtest dir bunte Höhen, und du hurtest auf denselben, was nicht vorkommen und nicht geschehen sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Und du nahmst deine prächtigen Geschmeide von meinem Golde und von meinem Silber, welches ich dir gegeben hatte, und machtest dir Mannsbilder und hurtest mit ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Und du nahmst deine buntgewirkten Kleider und bedecktest sie damit; und mein Öl und mein Räucherwerk setztest du ihnen vor;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'und meine Speise, die ich dir gegeben: Feinmehl und Öl und Honig, womit ich dich gespeist hatte, die setztest du ihnen vor zum lieblichen Geruch. Und das ist geschehen, spricht der Herr, Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Und du nahmst deine Söhne und deine Töchter, die du mir geboren, und opfertest sie ihnen zum Fraß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'War es zu wenig an deiner Hurerei, daß du meine Kinder schlachtetest und sie hingabst, indem du sie ihnen durch das Feuer gehen ließest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Und bei allen deinen Greueln und deinen Hurereien gedachtest du nicht der Tage deiner Jugend, als du nackt und bloß warst, zappelnd in deinem Blute lagst. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Und es geschah, nach aller deiner Bosheit (wehe, wehe dir! spricht der Herr, Jehova)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'bautest du dir Gewölbe und machtest dir Höhen auf allen Straßen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'an jedem Scheidewege bautest du deine Höhen, und du schändetest deine Schönheit und spreiztest deine Füße gegen jeden Vorübergehenden; und du mehrtest deine Hurerei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Du hurtest mit den Söhnen Ägyptens, deinen Nachbarn, die groß an Fleisch sind; und du mehrtest deine Hurerei, um mich zu reizen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Und siehe, ich streckte meine Hand wider dich aus und verkürzte das dir Bestimmte; und ich gab dich hin der Gier derer, die dich hassen, der Töchter der Philister, die sich vor deinem unzüchtigen Wege schämen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Und du hurtest mit den Söhnen Assurs, weil du nie satt werden kannst; und du hurtest mit ihnen und wurdest auch nicht satt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Und du mehrtest deine Hurerei nach dem Krämerlande Chaldäa hin; und auch davon wurdest du nicht satt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Wie schmachtend ist dein Herz, spricht der Herr, Jehova, indem du dieses alles tust, das Tun eines ausgelassenen Hurenweibes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'indem du deine Gewölbe baust an jedem Scheidewege und deine Höhen auf allen Straßen machst. Und du warst nicht einmal wie eine Hure, indem du den Lohn verschmähtest;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'das ehebrecherische Weib nimmt statt ihres Mannes Fremde an!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Allen Huren gibt man Geschenke; du aber gabst deine Geschenke allen deinen Buhlen, und du beschenktest sie, damit sie von ringsumher zu dir kämen, um Hurerei mit dir zu treiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Und es geschah bei dir das Umgekehrte von den Weibern bei deinen Hurereien, daß man nicht dir nachhurte; denn indem du Lohn gabst und dir kein Lohn gegeben wurde, bist du das Umgekehrte gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Darum, Hure, höre das Wort Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'So spricht der Herr, Jehova: Weil deine Unreinigkeit ausgegossen und deine Blöße aufgedeckt worden ist in deinen Hurereien mit deinen Buhlen, und wegen all deiner greuelhaften Götzen und wegen des Blutes deiner Kinder, die du ihnen gegeben hast:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'darum, siehe, werde ich alle deine Buhlen sammeln, denen du gefielst, und alle, die du geliebt, samt allen, die du gehaßt hast. Und ich werde sie von ringsumher wider dich sammeln und deine Blöße vor ihnen aufdecken, so daß sie deine ganze Blöße sehen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Und ich werde dich richten nach den Rechten der Ehebrecherinnen und der Blutvergießerinnen, und dich machen zum Blute des Grimmes und der Eifersucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Und ich werde dich in ihre Hand geben, damit sie deine Gewölbe zerstören und deine Höhen niederreißen, und dir deine Kleider ausziehen und deine prächtigen Geschmeide nehmen und dich nackt und bloß liegen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Und sie werden eine Versammlung wider dich heraufführen und dich steinigen, und werden dich mit ihren Schwertern durchbohren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Und sie werden deine Häuser mit Feuer verbrennen und Gerichte an dir üben vor den Augen vieler Weiber. Und so werde ich dich aufhören lassen, eine Hure zu sein, und du wirst auch keinen Lohn mehr geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Und ich werde meinen Grimm an dir stillen, und mein Eifer wird von dir weichen; und ich werde ruhig sein und mich nicht mehr kränken. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Darum, daß du nicht gedacht hast der Tage deiner Jugend und mich durch alles dieses gereizt hast, siehe, so habe auch ich deinen Weg auf deinen Kopf gebracht, spricht der Herr, Jehova, damit du nicht mehr diese Schandtat begehest zu allen deinen Greueln hinzu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Siehe, jeder Spruchredner wird über dich das Sprichwort reden und sprechen: Wie die Mutter, so ihre Tochter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Du bist die Tochter deiner Mutter, die ihren Mann und ihre Kinder verschmähte; und du bist die Schwester deiner Schwestern, die ihre Männer und ihre Kinder verschmähten. Eure Mutter war eine Hethiterin, und euer Vater ein Amoriter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Und deine größere Schwester ist Samaria mit ihren Töchtern, die zu deiner Linken wohnt; und deine Schwester, die kleiner ist als du, und die zu deiner Rechten wohnt, ist Sodom mit ihren Töchtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Aber nicht auf ihren Wegen hast du gewandelt, und nicht nur ein wenig nach ihren Greueln getan; denn du hast verderbter gehandelt als sie auf allen deinen Wegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'So wahr ich lebe, spricht der Herr, Jehova, Sodom, deine Schwester, sie und ihre Töchter haben nicht getan, wie du getan hast, du und deine Töchter!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Siehe, dies war die Missetat Sodoms, deiner Schwester: Hoffart, Fülle von Brot und sorglose Ruhe hatte sie mit ihren Töchtern, aber die Hand des Elenden und des Armen stärkte sie nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'und sie waren hochmütig und verübten Greuel vor meinem Angesicht. Und ich tat sie hinweg, sobald ich es sah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Und Samaria hat nicht gesündigt gleich der Hälfte deiner Sünden; und du hast deiner Greuel mehr gemacht als sie, und hast deine Schwestern gerechtfertigt durch alle deine Greuel, die du verübt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'So trage auch du deine Schmach, welche du deinen Schwestern zuerkannt hast; durch deine Sünden, die du greulicher begangen hast als sie, sind sie gerechter als du. Und so werde auch du zu Schanden und trage deine Schmach, weil du deine Schwestern gerechtfertigt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Und ich werde ihre Gefangenschaft wenden, die Gefangenschaft Sodoms und ihrer Töchter und die Gefangenschaft Samarias und ihrer Töchter, und die Gefangenschaft deiner Gefangenen in ihrer Mitte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'auf daß du deine Schmach tragest und dich schämest alles dessen, was du getan hast, indem du sie tröstest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Und deine Schwestern, Sodom und ihre Töchter, werden zurückkehren zu ihrem früheren Stande; und Samaria und ihre Töchter werden zurückkehren zu ihrem früheren Stande; und auch du und deine Töchter, ihr werdet zurückkehren zu eurem früheren Stande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Und Sodom, deine Schwester, wurde nicht erwähnt in deinem Munde am Tage deiner Hoffärtigkeiten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'ehe deine Bosheit aufgedeckt wurde, wie zur Zeit des Hohnes der Töchter Syriens und aller seiner Umgebungen, der Töchter der Philister, die dich verachteten ringsumher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Deine Unzucht und deine Greuel, du wirst sie tragen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Denn so spricht der Herr, Jehova: Ja, ich will dir tun, so wie du getan, die du den Eid verachtet und den Bund gebrochen hast. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Doch ich will gedenken meines Bundes mit dir in den Tagen deiner Jugend, und will dir einen ewigen Bund errichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Und du wirst deiner Wege gedenken und dich schämen, wenn du deine Schwestern empfangen wirst, die größer sind als du, samt denen, die kleiner sind als du, und ich sie dir zu Töchtern geben werde, aber nicht infolge deines Bundes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Und ich werde meinen Bund mit dir errichten, und du wirst wissen, daß ich Jehova bin:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'auf daß du eingedenk seiest und dich schämest, und den Mund nicht mehr auftuest wegen deiner Schmach, wenn ich dir alles vergebe, was du getan hast, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Menschensohn, gib ein Rätsel auf und rede ein Gleichnis zu dem Hause Israel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'und sprich: So spricht der Herr, Jehova: Ein großer Adler mit großen Flügeln, langen Schwingen, voll buntfarbigen Gefieders, kam zum Libanon und nahm den Wipfel einer Zeder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Den obersten ihrer Schößlinge brach er ab und brachte ihn in ein Krämerland, in eine Stadt von Kaufleuten setzte er ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Und er nahm von dem Samen des Landes und setzte ihn in ein Saatfeld, er brachte ihn zu vielen Wassern, behandelte ihn wie eine Weide.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Und er wuchs und wurde zu einem üppigen Weinstock von niedrigem Wuchse, damit seine Ranken sich zu ihm hin wendeten und seine Wurzeln unter ihm wären; und er wurde zu einem Weinstock und trieb Äste und breitete sein Laubwerk aus. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Und da war ein anderer großer Adler mit großen Flügeln und vielem Gefieder. Und siehe, von den Beeten seiner Pflanzung aus streckte dieser Weinstock seine Wurzeln lechzend zu ihm hin und breitete seine Ranken nach ihm aus, damit er ihn tränke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'In ein gutes Feld, an vielen Wassern war er gepflanzt, um Zweige zu treiben und Frucht zu tragen, um zu einem herrlichen Weinstock zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Sprich: So spricht der Herr, Jehova: Wird er gedeihen? Wird man nicht seine Wurzeln ausreißen und seine Frucht abschneiden, so daß er verdorrt? Alle frischen Blätter seines Triebes werden verdorren; und nicht mit großem Arme und zahlreichem Volke wird es möglich sein, ihn von seinen Wurzeln emporzuheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Und siehe, wenngleich er gepflanzt ist, wird er gedeihen? Wird er nicht, sobald der Ostwind ihn berührt, ganz verdorren? Auf den Beeten, wo er wächst, wird er verdorren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Sprich doch zu dem widerspenstigen Hause: Wisset ihr nicht, was das ist? Sprich: Siehe, der König von Babel ist nach Jerusalem gekommen, und hat seinen König und seine Fürsten weggenommen und hat sie zu sich nach Babel geführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Und er hat von dem königlichen Samen genommen und einen Bund mit ihm gemacht, und hat ihn einen Eid eingehen lassen; die Mächtigen des Landes aber hat er mitgenommen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'damit das Königreich niedrig wäre, auf daß es sich nicht erhöbe, und damit er seinen Bund hielte, auf daß es bestände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Aber er empörte sich wider ihn, indem er seine Boten nach Ägypten sandte, damit es ihm Rosse und viel Volks gäbe. Wird er gedeihen? Wird er, der solches getan hat, entrinnen? Da er den Bund gebrochen hat, sollte er entrinnen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'So wahr ich lebe, spricht der Herr, Jehova, wenn er nicht an dem Orte des Königs, der ihn zum König gemacht hat, dessen Eid er verachtet und dessen Bund er gebrochen hat, bei ihm in Babel sterben wird!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Und nicht wird der Pharao mit einem großen Heere und mit einer zahlreichen Schar für ihn etwas ausrichten im Kriege, wenn man einen Wall aufschüttet und Belagerungstürme baut, um viele Seelen auszurotten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Da er den Eid verachtet und den Bund gebrochen hat, und siehe, er hatte seine Hand darauf gegeben und tat dennoch alles dieses, so wird er nicht entrinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Darum spricht der Herr, Jehova, also: So wahr ich lebe, wenn ich nicht meinen Eid, den er verachtet, und meinen Bund, den er gebrochen hat, ihm auf seinen Kopf bringe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Und ich will mein Netz über ihn ausbreiten, und in meinem Garne wird er gefangen werden; und ich will ihn nach Babel bringen und daselbst mit ihm rechten wegen seiner Treulosigkeit, die er gegen mich begangen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Und alle seine Flüchtlinge unter allen seinen Scharen, sie werden durchs Schwert fallen, und die Übriggebliebenen in alle Winde zerstreut werden. Und ihr werdet wissen, daß ich, Jehova, geredet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'So spricht der Herr, Jehova: Und ich werde von dem Wipfel der hohen Zeder einen Schößling nehmen und ihn setzen; von dem obersten ihrer Schößlinge werde ich einen zarten abbrechen und ihn pflanzen auf einen hohen und erhabenen Berg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Auf den hohen Berg Israels werde ich ihn pflanzen; und er wird Zweige treiben und Frucht tragen und zu einer herrlichen Zeder werden; und unter ihr werden alle Vögel wohnen, alles Geflügelte: Im Schatten ihrer Zweige werden sie wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Und alle Bäume des Feldes werden erkennen, daß ich, Jehova, den hohen Baum erniedrigt, den niedrigen Baum erhöht habe, den grünen Baum verdorren und den dürren Baum grünen ließ. Ich, Jehova, habe geredet und werde es tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Was habt ihr, daß ihr diesen Spruch im Lande Israel gebrauchet und sprechet: Die Väter essen Herlinge, und die Zähne der Söhne werden stumpf?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'So wahr ich lebe, spricht der Herr, Jehova, wenn ihr ferner diesen Spruch in Israel gebrauchen sollt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Siehe, alle Seelen sind mein; wie die Seele des Vaters, so auch die Seele des Sohnes: Sie sind mein; die Seele, welche sündigt, die soll sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Und wenn jemand gerecht ist und Recht und Gerechtigkeit übt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'auf den Bergen nicht isset und seine Augen nicht erhebt zu den Götzen des Hauses Israel, und das Weib seines Nächsten nicht verunreinigt und dem Weibe in ihrer Unreinigkeit nicht naht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'und niemand bedrückt, sein Schuldpfand zurückgibt, keinen Raub begeht, sein Brot dem Hungrigen gibt und den Nackten mit Kleidung bedeckt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'auf Zins nicht gibt und Wucher nicht nimmt, seine Hand vom Unrecht zurückhält, der Wahrheit gemäß zwischen Mann und Mann richtet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'in meinen Satzungen wandelt und meine Rechte hält, um nach Wahrheit zu handeln: Der ist gerecht; er soll gewißlich leben, spricht der Herr, Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Zeugt er aber einen gewalttätigen Sohn, der Blut vergießt und irgend eines von diesen tut-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'er selbst aber hat alles dieses nicht getan wenn er sogar auf den Bergen isset, und das Weib seines Nächsten verunreinigt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'den Elenden und den Armen bedrückt, Raub begeht, das Pfand nicht zurückgibt, und seine Augen zu den Götzen erhebt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Greuel verübt, auf Zins gibt und Wucher nimmt: Sollte er leben? Er soll nicht leben! Alle diese Greuel hat er verübt: Er soll gewißlich getötet werden, sein Blut soll auf ihm sein. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Und siehe, es zeugt einer einen Sohn, und dieser sieht alle Sünden seines Vater, die er tut; er sieht sie und tut nicht dergleichen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Er isset nicht auf den Bergen und erhebt nicht seine Augen zu den Götzen des Hauses Israel, er verunreinigt nicht das Weib seines Nächsten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'und er bedrückt niemand, nimmt kein Pfand und begeht keinen Raub, er gibt dem Hungrigen sein Brot und bedeckt den Nackten mit Kleidung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'er hält seine Hand von dem Elenden zurück, nimmt weder Zins noch Wucher, er tut meine Rechte, wandelt in meinen Satzungen: Der wird nicht wegen der Ungerechtigkeit seines Vaters sterben; er soll gewißlich leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Sein Vater, weil er Erpressung verübt, Raub am Bruder begangen, und was nicht gut war inmitten seines Volkes getan hat: Siehe, der soll wegen seiner Ungerechtigkeit sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Und sprechet ihr: Warum trägt der Sohn die Ungerechtigkeit des Vaters nicht mit? Der Sohn hat ja Recht und Gerechtigkeit geübt, hat alle meine Satzungen gehalten und sie getan: Er soll gewißlich leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Die Seele, welche sündigt, die soll sterben. Ein Sohn soll nicht die Ungerechtigkeit des Vaters mittragen, und ein Vater nicht die Ungerechtigkeit des Sohnes mittragen; die Gerechtigkeit des Gerechten soll auf ihm sein, und die Gesetzlosigkeit des Gesetzlosen soll auf ihm sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Wenn aber der Gesetzlose umkehrt von allen seinen Sünden, die er getan hat, und alle meine Satzungen hält und Recht und Gerechtigkeit übt, so soll er gewißlich leben, er soll nicht sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Aller seiner Übertretungen, die er begangen hat, soll ihm nicht gedacht werden; wegen seiner Gerechtigkeit, die er geübt hat, soll er leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Habe ich irgendwie Gefallen an dem Tode des Gesetzlosen, spricht der Herr, Jehova? Nicht vielmehr daran, daß er von seinen Wegen umkehre und lebe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Wenn aber ein Gerechter von seiner Gerechtigkeit umkehrt und unrecht tut, nach all den Greueln tut, die der Gesetzlose verübt hat, sollte er leben? Aller seiner gerechten Taten, die er getan hat, soll nicht gedacht werden; wegen seiner Treulosigkeit, die er begangen, und wegen seiner Sünde, die er getan hat, wegen dieser soll er sterben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Und ihr sprechet: Der Weg des Herrn ist nicht recht. Höret doch, Haus Israel: Ist mein Weg nicht recht? Sind nicht vielmehr eure Wege nicht recht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Wenn ein Gerechter von seiner Gerechtigkeit umkehrt und unrecht tut, und um deswillen stirbt, so stirbt er wegen seines Unrechts, das er getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Wenn aber ein Gesetzloser umkehrt von seiner Gesetzlosigkeit, die er begangen hat, und Recht und Gerechtigkeit übt: Er wird seine Seele am Leben erhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Sieht er es ein und kehrt er um von allen seinen Übertretungen, die er begangen hat, so soll er gewißlich leben, er soll nicht sterben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Aber das Haus Israel spricht: Der Weg des Herrn ist nicht recht. Sind meine Wege nicht recht, Haus Israel? Sind nicht vielmehr eure Wege nicht recht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Darum werde ich euch richten, Haus Israel, einen jeden nach seinen Wegen, spricht der Herr, Jehova. Kehret um, und wendet euch ab von allen euren Übertretungen, daß es euch nicht ein Anstoß zur Missetat werde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'werfet von euch alle eure Übertretungen, womit ihr übertreten habt, und schaffet euch ein neues Herz und einen neuen Geist! Denn warum wollt ihr sterben, Haus Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Denn ich habe kein Gefallen am Tode des Sterbenden, spricht der Herr, Jehova. So kehret um und lebet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Und du, erhebe ein Klagelied über die Fürsten Israels und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'Welch eine Löwin war deine Mutter! Zwischen Löwen lagerte sie, unter jungen Löwen zog sie ihre Jungen groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Und sie zog eines von ihren Jungen auf, es wurde ein junger Löwe; und er lernte Raub rauben, er fraß Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Und die Völker hörten von ihm, in ihrer Grube wurde er gefangen; und sie brachten ihn mit Nasenringen in das Land Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Und als sie sah, daß ihre Hoffnung dahin, verloren war, da nahm sie ein anderes von ihren Jungen, machte es zu einem jungen Löwen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Und es wandelte unter Löwen, wurde ein junger Löwe; und er lernte Raub rauben, er fraß Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Und er zerstörte ihre Paläste, verheerte ihre Städte; und das Land und seine Fülle entsetzte sich vor der Stimme seines Gebrülls.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Da stellten sich gegen ihn die Völker ringsum aus den Landschaften; und sie breiteten ihr Netz über ihn aus, in ihrer Grube wurde er gefangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Und sie setzten ihn mit Nasenringen in den Käfig und brachten ihn zu dem König von Babel; sie brachten ihn in eine der Festen, auf daß seine Stimme nicht mehr gehört würde auf den Bergen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Deine Mutter war wie ein Weinstock, gleich dir an Wassern gepflanzt; von vielen Wassern wurde er fruchtbar und voll Ranken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Und er bekam starke Zweige zu Herrscherzeptern, und sein Wuchs erhob sich bis zwischen die Wolken; und er wurde sichtbar durch seine Höhe, durch die Menge seiner Äste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Da wurde er ausgerissen im Grimm, zu Boden geworfen, und der Ostwind dörrte seine Frucht; seine starken Zweige wurden abgerissen und dürr, Feuer verzehrte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Und nun ist er in die Wüste gepflanzt, in ein dürres und durstiges Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Und ein Feuer ist ausgegangen vom Gezweige seiner Ranken, hat seine Frucht verzehrt; und an ihm ist kein starker Zweig mehr, kein Zepter zum Herrschen. Das ist ein Klagelied und wird zum Klageliede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Und es geschah im siebten Jahre, im fünften Monat, am Zehnten des Monats, da kamen Männer von den Ältesten Israels, um Jehova zu befragen; und sie setzten sich vor mir nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Menschensohn, rede zu den Ältesten Israels und sprich zu ihnen: So spricht der Herr, Jehova: Um mich zu befragen, seid ihr gekommen? So wahr ich lebe, wenn ich mich von euch befragen lasse! spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Willst du sie richten? Willst du richten, Menschensohn? Tue ihnen kund die Greuel ihrer Väter und sprich zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'So spricht der Herr, Jehova: An dem Tage, da ich Israel erwählte, und ich meine Hand dem Samen des Hauses Jakob erhob, und ihnen im Lande Ägypten mich kundgab, und meine Hand ihnen erhob und sprach: Ich bin Jehova, euer Gott-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'an jenem Tage erhob ich ihnen meine Hand, daß ich sie aus dem Lande Ägypten führen würde in ein Land, welches ich für sie erspäht hatte, das von Milch und Honig fließt; die Zierde ist es von allen Ländern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Und ich sprach zu ihnen: Werfet ein jeder die Scheusale seiner Augen weg, und verunreiniget euch nicht mit den Götzen Ägyptens; ich bin Jehova, euer Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Aber sie waren widerspenstig gegen mich und wollten nicht auf mich hören; keiner warf die Scheusale seiner Augen weg, und von den Götzen Ägyptens ließen sie nicht. Da gedachte ich meinen Grimm über sie auszugießen, meinen Zorn an ihnen zu vollenden mitten im Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Aber ich handelte um meines Namens willen, auf daß er nicht entweiht würde vor den Augen der Nationen, in deren Mitte sie waren, vor deren Augen ich mich ihnen kundgegeben hatte, um sie aus dem Lande Ägypten zu führen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'und ich führte sie aus dem Lande Ägypten und brachte sie in die Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Und ich gab ihnen meine Satzungen und tat ihnen meine Rechte kund, durch welche der Mensch, wenn er sie tut, leben wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Und auch meine Sabbathe gab ich ihnen, damit sie zum Denkzeichen wären zwischen mir und ihnen, auf daß sie wissen möchten, daß ich Jehova bin, der sie heiligt. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Aber das Haus Israel war widerspenstig gegen mich in der Wüste; sie wandelten nicht in meinen Satzungen und verwarfen meine Rechte, durch welche der Mensch, wenn er sie tut, leben wird; und sie entweihten meine Sabbathe sehr. Da gedachte ich meinen Grimm über sie auszugießen in der Wüste, um sie zu vernichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Aber ich handelte um meines Namens willen, auf daß er nicht entweiht würde vor den Augen der Nationen, vor deren Augen ich sie ausgeführt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Und ich erhob ihnen auch meine Hand in der Wüste, daß ich sie nicht in das Land bringen würde, welches ich ihnen gegeben hatte, das von Milch und Honig fließt; die Zierde ist es von allen Ländern:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'weil sie meine Rechte verwarfen und in meinen Satzungen nicht wandelten und meine Sabbathe entweihten; denn ihr Herz wandelte ihren Götzen nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Aber mein Auge schonte ihrer, daß ich sie nicht verderbte und ihnen nicht den Garaus machte in der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Und ich sprach zu ihren Kindern in der Wüste: Wandelt nicht in den Satzungen eurer Väter, und haltet ihre Rechte nicht, und verunreiniget euch nicht mit ihren Götzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Ich bin Jehova, euer Gott: Wandelt in meinen Satzungen, und haltet meine Rechte und tut sie;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'und heiliget meine Sabbathe, damit sie zum Denkzeichen seien zwischen mir und euch, auf daß ihr wisset, daß ich Jehova bin, euer Gott. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Aber die Kinder waren widerspenstig gegen mich; sie wandelten nicht in meinen Satzungen und hielten meine Rechte nicht, um sie zu tun, durch welche der Mensch, wenn er sie tut, leben wird; sie entweihten meine Sabbathe. Da gedachte ich, meinen Grimm über sie auszugießen, meinen Zorn an ihnen zu vollenden in der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Aber ich zog meine Hand zurück, und handelte um meines Namens willen, auf daß er nicht entweiht würde vor den Augen der Nationen, vor deren Augen ich sie ausgeführt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Auch erhob ich ihnen meine Hand in der Wüste, daß ich sie unter die Nationen versprengen und sie in die Länder zerstreuen würde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'weil sie meine Rechte nicht taten und meine Satzungen verwarfen und meine Sabbathe entweihten, und ihre Augen hinter den Götzen ihrer Väter her waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Und auch ich gab ihnen Satzungen, die nicht gut waren, und Rechte, durch welche sie nicht leben konnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'Und ich verunreinigte sie durch ihre Gaben, indem sie alles, was die Mutter bricht, durch das Feuer gehen ließen: auf daß ich sie verwüstete, damit sie wissen möchten, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Darum, Menschensohn, rede zum Hause Israel und sprich zu ihnen: So spricht der Herr, Jehova: Auch noch dadurch haben eure Väter mich geschmäht, als sie Treulosigkeit gegen mich begingen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Als ich sie in das Land gebracht, welches ihnen zu geben ich meine Hand erhoben hatte, ersahen sie jeden hohen Hügel und jeden dichtbelaubten Baum; und sie opferten daselbst ihre Schlachtopfer, und gaben daselbst ihre Ärger erregenden Opfergaben, und brachten daselbst den Duft ihrer Wohlgerüche dar, und spendeten daselbst ihre Trankopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Und ich sprach zu ihnen: Was ist das für eine Höhe, wohin ihr gehet? Und ihr Name wird Bama genannt bis auf diesen Tag. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Darum sprich zum Hause Israel: So spricht der Herr, Jehova: Wie? Ihr verunreiniget euch auf dem Wege eurer Väter und huret ihren Scheusalen nach;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'und ihr verunreiniget euch bis auf diesen Tag an allen euren Götzen durch das Darbringen eurer Gaben, indem ihr eure Kinder durch das Feuer gehen lasset! Und ich sollte mich von euch befragen lassen, Haus Israel? So wahr ich lebe, spricht der Herr, Jehova, wenn ich mich von euch befragen lasse!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Und was in eurem Geiste aufgestiegen ist, wird keineswegs geschehen, daß ihr sprechet: Wir wollen sein wie die Nationen und wie die Geschlechter der Länder, indem wir Holz und Stein dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'So wahr ich lebe, spricht der Herr, Jehova, wenn ich nicht mit starker Hand und mit ausgestrecktem Arm und mit ausgegossenem Grimm über euch regieren werde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Und ich werde euch herausführen aus den Völkern und euch aus den Ländern sammeln, in welche ihr zerstreut worden seid, mit starker Hand und mit ausgestrecktem Arm und mit ausgegossenem Grimm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'Und ich werde euch in die Wüste der Völker bringen und daselbst mit euch rechten von Angesicht zu Angesicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'wie ich mit euren Vätern gerechtet habe in der Wüste des Landes Ägypten, also werde ich mit euch rechten, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Und ich werde euch unter dem Stabe hindurchziehen lassen, und euch in das Band des Bundes bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Und ich werde die Empörer und die von mir Abgefallenen von euch ausscheiden; ich werde sie herausführen aus dem Lande ihrer Fremdlingschaft, aber in das Land Israel soll keiner von ihnen kommen. Und ihr werdet wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Ihr denn, Haus Israel, so spricht der Herr, Jehova: Gehet hin, dienet ein jeder seinen Götzen. Aber nachher, wahrlich, ihr werdet auf mich hören, und werdet meinen heiligen Namen nicht mehr entweihen mit euren Gaben und mit euren Götzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Denn auf meinem heiligen Berge, auf dem hohen Berge Israels, spricht der Herr, Jehova, daselbst wird mir das ganze Haus Israel insgesamt dienen im Lande; daselbst werde ich sie wohlgefällig annehmen, und daselbst werde ich eure Hebopfer fordern und die Erstlinge eurer Gaben, in allen euren geheiligten Dingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Als einen lieblichen Geruch werde ich euch wohlgefällig annehmen, wenn ich euch aus den Völkern herausführe und euch aus den Ländern sammle, in welche ihr zerstreut worden seid, und ich mich vor den Augen der Nationen an euch heilige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Und ihr werdet wissen, daß ich Jehova bin, wenn ich euch in das Land Israel bringe, in das Land, welches euren Vätern zu geben ich meine Hand erhoben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Und ihr werdet daselbst eurer Wege und all eurer Handlungen gedenken, durch welche ihr euch verunreinigt habt; und ihr werdet Ekel an euch selbst empfinden wegen all eurer Übeltaten, die ihr begangen habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Und ihr werdet wissen, daß ich Jehova bin, wenn ich mit euch handle um meines Namens willen, und nicht nach euren bösen Wegen und nach euren verderbten Handlungen, Haus Israel, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, '(H21:1) Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, '(H21:2) Menschensohn, richte dein Angesicht gegen Süden und rede gegen Mittag, und weissage über den Wald des Gefildes im Süden');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, '(H21:3) und sprich zu dem Walde des Südens: Höre das Wort Jehovas! So spricht der Herr, Jehova: Siehe, ich will in dir ein Feuer anzünden, welches jeden grünen Baum und jeden dürren Baum in dir verzehren wird; die lodernde Flamme wird nicht erlöschen, und vom Süden bis zum Norden werden alle Angesichter dadurch versengt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, '(H21:4) Und alles Fleisch soll sehen, daß ich, Jehova, es angezündet habe; es wird nicht erlöschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, '(H21:5) Und ich sprach: Ach, Herr, Jehova! Sie sagen von mir: Redet er nicht in Gleichnissen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, '(H21:6) Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, '(H21:7) Menschensohn, richte dein Angesicht gegen Jerusalem und rede über die Heiligtümer, und weissage über das Land Israel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, '(H21:8) und sprich zu dem Lande Israel: So spricht Jehova: Siehe, ich will an dich, und will mein Schwert aus seiner Scheide ziehen; und ich will aus dir ausrotten den Gerechten und den Gesetzlosen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, '(H21:9) Darum, weil ich aus dir den Gerechten und den Gesetzlosen ausrotten will, darum soll mein Schwert aus seiner Scheide fahren wider alles Fleisch vom Süden bis zum Norden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, '(H21:10) Und alles Fleisch wird wissen, daß ich, Jehova, mein Schwert aus seiner Scheide gezogen habe; es soll nicht wieder zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, '(H21:11) Und du, Menschensohn, seufze, daß die Hüften brechen, und mit bitterem Schmerze seufze vor ihren Augen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, '(H21:12) Und es soll geschehen, wenn sie zu dir sprechen: Warum seufzest du? so sollst du sprechen: Wegen des kommenden Gerüchtes; und jedes Herz wird zerschmelzen, und alle Hände werden erschlaffen, und jeder Geist wird verzagen, und alle Knie werden zerfließen wie Wasser; siehe, es kommt und wird geschehen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, '(H21:13) Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, '(H21:14) Menschensohn, weissage und sprich: So spricht der Herr: Sprich: Ein Schwert, ein Schwert, geschärft und auch geschliffen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, '(H21:15) Damit es eine Schlachtung anrichte, ist es geschärft; damit es blitze, ist es geschliffen. Oder sollen wir uns freuen und sagen: Das Zepter meines Sohnes verachtet alles Holz?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, '(H21:16) Aber man hat es zu schleifen gegeben, um es in der Hand zu führen. Das Schwert, geschärft ist es und geschliffen, um es in die Hand des Würgers zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, '(H21:17) Schreie und heule, Menschensohn! Denn es ist gegen mein Volk, es ist gegen alle Fürsten Israels: Samt meinem Volke sind sie dem Schwerte verfallen; darum schlage dich auf die Lenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, '(H21:18) Denn die Probe ist gemacht; und was? Wenn sogar das verachtende Zepter nicht mehr sein wird? spricht der Herr, Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, '(H21:19) Und du, Menschensohn, weissage und schlage die Hände zusammen; denn das Schwert, das Schwert der Erschlagenen, wird sich ins Dreifache vervielfältigen; es ist das Schwert des erschlagenen Großen, welches sie umkreist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, '(H21:20) Damit das Herz zerfließe und viele hinstürzen, habe ich das schlachtende Schwert wider alle ihre Tore gerichtet. Wehe! Zum Blitzen ist es gemacht, zum Schlachten geschärft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, '(H21:21) Nimm dich zusammen nach rechts, richte dich nach links, wohin deine Schneide bestimmt ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, '(H21:22) Und auch ich will meine Hände zusammenschlagen und meinen Grimm stillen. Ich, Jehova, habe geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, '(H21:23) Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, '(H21:24) Und du, Menschensohn, machte dir zwei Wege, auf welchen das Schwert des Königs von Babel kommen soll: Von einem Lande sollen sie beide ausgehen; und zeichne einen Wegweiser, am Anfang des Weges nach der Stadt zeichne ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, '(H21:25) Du sollst einen Weg machen, damit das Schwert nach Rabbath der Kinder Ammon komme, und nach Juda in das befestigte Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, '(H21:26) Denn der König von Babel bleibt am Kreuzwege stehen, am Anfang der beiden Wege, um sich wahrsagen zu lassen; er schüttelt die Pfeile, befragt die Teraphim, beschaut die Leber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, '(H21:27) In seine Rechte fällt die Wahrsagung \"Jerusalem\", daß er Sturmböcke aufstelle, den Mund auftue mit Geschrei, die Stimme erhebe mit Feldgeschrei, Sturmböcke gegen die Tore aufstelle, Wälle aufschütte und Belagerungstürme baue. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, '(H21:28) Und es wird ihnen wie ein falsche Wahrsagung in ihren Augen sein; Eide um Eide haben sie; er aber wird die Ungerechtigkeit in Erinnerung bringen, auf daß sie ergriffen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, '(H21:29) Darum, so spricht der Herr, Jehova: Weil ihr eure Ungerechtigkeit in Erinnerung bringet, indem eure Übertretungen offenbar werden, so daß eure Sünden in allen euren Handlungen zum Vorschein kommen, weil ihr in Erinnerung kommet, werdet ihr von der Hand ergriffen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, '(H21:30) Und du, Unheiliger, Gesetzloser, Fürst Israels, dessen Tag gekommen ist zur Zeit der Ungerechtigkeit des Endes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, '(H21:31) So spricht der Herr, Jehova: Hinweg mit dem Kopfbund und fort mit der Krone! Dies wird nicht mehr sein. Das Niedrige werde erhöht und das Hohe erniedrigt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, '(H21:32) Umgestürzt, umgestürzt, umgestürzt will ich sie machen; auch dies wird nicht mehr sein, bis der kommt, welchem das Recht gehört: Dem werde ich\'s geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, '(H21:33) Und du, Menschensohn, weissage und sprich: So spricht der Herr, Jehova, über die Kinder Ammon und über ihren Hohn; und sprich: Ein Schwert, ein Schwert, zur Schlachtung gezückt, geschliffen, damit es fresse, damit es blitze');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, '(H21:34) (während man dir Eitles schaut, während man dir Lügen wahrsagt), um dich zu den Hälsen der erschlagenen Gesetzlosen zu legen, deren Tag gekommen ist zur Zeit der Ungerechtigkeit des Endes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, '(H21:35) Stecke es wieder in seine Scheide! An dem Orte, wo du geschaffen bist, in dem Lande deines Ursprungs, werde ich dich richten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, '(H21:36) Und ich werde meinen Zorn über dich ausgießen, das Feuer meines Grimmes wider dich anfachen; und ich werde dich in die Hand roher Menschen geben, welche Verderben schmieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, '(H21:37) Du wirst dem Feuer zum Fraße werden, dein Blut wird inmitten des Landes sein; deiner wird nicht mehr gedacht werden. Denn ich, Jehova, habe geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Und du, Menschensohn, willst du richten, willst du richten die Stadt der Blutschuld? So tue ihr kund alle ihre Greuel und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'So spricht der Herr, Jehova: Stadt, die Blut vergießt in ihrer Mitte, damit ihre Zeit komme, und welche sich Götzen macht, um sich zu verunreinigen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Durch dein Blut, das du vergossen, hast du dich verschuldet, und durch deine Götzen, die du gemacht, hast du dich verunreinigt; und du hast deine Tage herbeigeführt und bist zu deinen Jahren gekommen. Darum habe ich dich den Nationen zum Hohne gemacht und allen Ländern zum Spott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Die Nahen und die von dir Entfernten werden dich verspotten als befleckten Namens und reich an Verwirrung. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Siehe, in dir waren die Fürsten Israels, ein jeder nach seiner Kraft, um Blut zu vergießen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Vater und Mutter verachteten sie in dir, an dem Fremdling handelten sie gewalttätig in deiner Mitte, Waisen und Witwen bedrückten sie in dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Meine heiligen Dinge hast du verachtet und meine Sabbathe entweiht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Verleumder waren in dir, um Blut zu vergießen; und auf den Bergen in dir haben sie gegessen, sie haben in deiner Mitte Schandtaten verübt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'In dir hat man die Blöße des Vaters aufgedeckt, in dir haben sie die Unreine in ihrer Unreinigkeit geschwächt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Und der eine hat Greuel verübt mit dem Weibe seines Nächsten, und der andere hat seine Schwiegertochter durch Schandtat verunreinigt, und ein anderer hat in dir seine Schwester, die Tochter seines Vaters, geschwächt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'In dir haben sie Geschenke genommen, um Blut zu vergießen; du hast Zins und Wucher genommen und deinen Nächsten mit Gewalt übervorteilt. Mich aber hast du vergessen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Und siehe, ich schlage in meine Hand wegen deines unrechtmäßigen Gewinnes, den du gemacht hast, und über deine Blutschuld, die in deiner Mitte ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Wird dein Herz feststehen, oder werden deine Hände stark sein an dem Tage, da ich mit dir handeln werde? Ich, Jehova, habe geredet und werde es tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Und ich werde dich versprengen unter die Nationen und dich zerstreuen in die Länder und deine Unreinigkeit gänzlich aus dir wegschaffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Und du wirst durch dich selbst entweiht werden vor den Augen der Nationen; und du wirst wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Menschensohn, das Haus Israel ist mir zu Schlacken geworden; sie alle sind Erz und Zinn und Eisen und Blei im Schmelzofen; Silberschlacken sind sie geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Darum, so spricht der Herr, Jehova: Weil ihr alle zu Schlacken geworden seid, darum, siehe, werde ich euch in Jerusalem zusammentun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Wie man Silber und Erz und Eisen und Blei und Zinn in einen Schmelzofen zusammentut, um Feuer darüber anzublasen zum Schmelzen, also werde ich euch in meinem Zorn und in meinem Grimm zusammentun und euch hineinlegen und schmelzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Und ich werde euch sammeln und das Feuer meines Grimmes über euch anblasen, daß ihr in Jerusalem geschmolzen werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Wie Silber im Ofen geschmolzen wird, also werdet ihr in Jerusalem geschmolzen werden. Und ihr werdet wissen, daß ich, Jehova, meinen Grimm über euch ausgegossen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Menschensohn, sprich zu ihm: Du bist ein Land, das nicht beschienen, nicht beregnet wird am Tage des Zornes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Verschwörung seiner Propheten ist in ihm; gleich einem brüllenden Löwen, der Beute zerreißt, fressen sie Seelen, nehmen Reichtum und Kostbarkeiten, mehren seine Witwen in seiner Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Seine Priester tun meinem Gesetze Gewalt an und entweihen meine heiligen Dinge; zwischen Heiligem und Unheiligem unterscheiden sie nicht, und den Unterschied zwischen Unreinem und Reinem tun sie nicht kund; und vor meinen Sabbathen verhüllen sie ihre Augen, und ich werde in ihrer Mitte entheiligt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Seine Fürsten in ihm sind wie Wölfe, die Beute zerreißen, indem sie Blut vergießen, Seelen vertilgen, um unrechtmäßigen Gewinn zu erlangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Und seine Propheten bestreichen ihnen alles mit Tünche, indem sie Eitles schauen und ihnen Lügen wahrsagen und sprechen: So spricht der Herr, Jehova! Und doch hat Jehova nicht geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Das Volk des Landes verübt Erpressung und begeht Raub; und den Elenden und Dürftigen bedrücken sie, und den Fremdling übervorteilen sie widerrechtlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Und ich suchte einen Mann unter ihnen, der die Mauer zumauern und vor mir in den Riß treten möchte für das Land, auf daß ich es nicht verderbte; aber ich fand keinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Und ich gieße meinen Zorn über sie aus, vernichte sie durch das Feuer meines Grimmes; ich bringe ihren Weg auf ihren Kopf, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Menschensohn, es waren zwei Weiber, Töchter einer Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Und sie hurten in Ägypten, in ihrer Jugend hurten sie; dort wurden ihre Brüste gedrückt, und dort betastete man ihren jungfräulichen Busen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Und ihre Namen sind Ohola, die größere, und Oholiba, ihre Schwester. Und sie wurden mein und gebaren Söhne und Töchter; und was ihre Namen betrifft: Samaria ist Ohola, und Jerusalem ist Oholiba.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Und Ohola hurte, als sie unter mir war. Und sie entbrannte gegen ihre Buhlen, gegen die Assyrer, die nahe waren, gekleidet in Purpurblau,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Landpfleger und Statthalter, allesamt anmutige Jünglinge, Reiter, auf Rossen reitend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Und sie richtete ihre Hurereien auf sie, die Auswahl der Söhne Assurs insgesamt; und mit allen, gegen welche sie entbrannte, mit allen deren Götzen verunreinigte sie sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Und auch ihre Hurereien von Ägypten her ließ sie nicht; denn sie hatten bei ihr gelegen in ihrer Jugend, und hatten ihren jungfräulichen Busen betastet und ihre Hurerei über sie ausgegossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Darum habe ich sie in die Hand ihrer Buhlen gegeben, in die Hand der Söhne Assurs, gegen welche sie entbrannt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Sie deckten ihre Blöße auf, nahmen ihre Söhne und ihre Töchter weg, und sie selbst töteten sie mit dem Schwerte; und so wurde sie berüchtigt unter den Weibern, und man übte Gerichte an ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Und ihre Schwester Oholiba sah es, und sie trieb ihre Lüsternheit ärger als sie, und ihre Hurereien weiter als die Hurereien ihrer Schwester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Sie entbrannte gegen die Söhne Assurs, Landpfleger und Statthalter, die nahe waren, prächtig gekleidet, Reiter, auf Rossen reitend, allesamt anmutige Jünglinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Und ich sah, daß sie sich verunreinigt hatte: einerlei Weg hatten beide.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Aber sie trieb ihre Hurereien noch weiter; denn sie sah Männer, an die Wand gezeichnet, Bilder von Chaldäern, mit Zinnober gezeichnet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'mit Gürteln an ihren Hüften gegürtet, überhängende Mützen auf ihren Häuptern, von Aussehen Ritter insgesamt, ähnlich den Söhnen Babels in Chaldäa, ihrem Geburtslande;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'und sie entbrannte gegen sie, als ihre Augen sie sahen, und sie sandte Boten zu ihnen nach Chaldäa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Und die Söhne Babels kamen zu ihr zum Liebeslager und verunreinigten sie durch ihre Hurerei. Und als sie sich an ihnen verunreinigt hatte, riß sich ihre Seele von ihnen los.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Und als sie ihre Hurereien aufdeckte und ihre Blöße aufdeckte, da riß sich meine Seele von ihr los, so wie meine Seele sich von ihrer Schwester losgerissen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Und sie mehrte ihre Hurereien, indem sie der Tage ihrer Jugend gedachte, als sie im Lande Ägypten hurte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'Und sie entbrannte gegen dessen Buhlen, deren Fleisch wie das Fleisch der Esel, und deren Erguß wie der Erguß der Rosse ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Und du schautest dich um nach der Schandtat deiner Jugend, als die von Ägypten deinen Busen betasteten um deiner jugendlichen Brüste willen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Darum Oholiba, so spricht der Herr, Jehova: Siehe, ich erwecke wider dich deine Buhlen, von welchen deine Seele sich losgerissen hat, und lasse sie von ringsumher über dich kommen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Die Söhne Babels und alle Chaldäer, Pekod und Schoa und Koa, alle Söhne Assurs mit ihnen, anmutige Jünglinge, Landpfleger und Statthalter insgesamt, Ritter und Räte, allesamt auf Rossen reitend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Und sie werden über dich kommen mit Waffen, Wagen und Rädern, und mit einer Schar von Völkern; Schild und Tartsche und Helm werden sie ringsum wider dich richten. Und ich werde ihnen das Gericht übergeben, und sie werden dich richten nach ihren Rechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Und ich will meinen Eifer wider dich richten, und sie werden im Grimme mit dir verfahren: Deine Nase und deine Ohren werden sie abschneiden, und was dir übrigbleibt wird durch das Schwert fallen; deine Söhne und deine Töchter werden sie wegnehmen, und was dir übrigbleibt wird durch das Feuer verzehrt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Und sie werden dir deine Kleider ausziehen und deine herrlichen Geschmeide nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Und ich will machen, daß deine Schandtat von dir abläßt, und deine Hurerei vom Lande Ägypten, so daß du deine Augen nicht mehr zu ihnen erheben und Ägyptens nicht mehr gedenken wirst. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Denn so spricht der Herr, Jehova: Siehe, ich gebe dich in die Hand derer, die du hassest, in die Hand derer, von welchen deine Seele sich losgerissen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Und sie werden im Haß mit dir verfahren, und deinen ganzen Erwerb wegnehmen und dich nackt und bloß lassen; und deine hurerische Blöße und deine Schandtat und deine Hurereien werden aufgedeckt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Solches wird dir geschehen, weil du den Nationen nachgehurt, weil du dich mit ihren Götzen verunreinigt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Auf dem Wege deiner Schwester hast du gewandelt, und so will ich ihren Becher in deine Hand geben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'So spricht der Herr, Jehova: Du wirst den Becher deiner Schwester trinken, den tiefen und weiten: Zum Gelächter und zum Spott wird er gereichen, weil er so viel faßt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Voll Trunkenheit und Kummer wirst du werden; der Becher deiner Schwester Samaria ist ein Becher des Entsetzens und der Betäubung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Und du wirst ihn trinken und ausschlürfen, und wirst seine Scherben benagen und deine Brüste zerreißen; denn ich habe geredet, spricht der Herr, Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Darum, so spricht der Herr, Jehova: Weil du meiner vergessen und mich hinter deinen Rücken geworfen hast, so trage du auch deine Schandtat und deine Hurereien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Und Jehova sprach zu mir: Menschensohn, willst du die Ohola und die Oholiba richten? So tue ihnen ihre Greuel kund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Denn sie haben Ehebruch getrieben, und Blut ist an ihren Händen; und mit ihren Götzen haben sie Ehebruch getrieben, und sogar ihre Kinder, die sie mir geboren, haben sie ihnen durch das Feuer gehen lassen zum Fraß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Noch dieses haben sie mir getan: Sie haben mein Heiligtum verunreinigt an selbigem Tage und meine Sabbathe entweiht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Denn wenn sie ihre Kinder ihren Götzen schlachteten, so kamen sie an demselben Tage in mein Heiligtum, es zu entweihen; und siehe, also haben sie getan inmitten meines Hauses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Ja, sie haben sogar zu Männern gesandt, die von ferne kommen sollten, zu welchen ein Bote gesandt wurde, und siehe, sie kamen für welche du dich badetest, deine Augen schminktest und dir Schmuck anlegtest,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'und dich auf ein prächtiges Polster setztest, vor welchem ein Tisch zugerichtet war; und darauf setztest du mein Räucherwerk und mein Öl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Und dabei war die Stimme einer sorglosen Menge. Und zu den Männern aus der Menschenmenge wurden Zecher gebracht aus der Wüste; und sie legten Armringe an ihre Hände und setzten prächtige Kronen auf ihre Häupter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Da sprach ich von der durch Ehebruch Entkräfteten: Wird sie, ja sie, jetzt noch ihre Hurereien treiben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Und man ging zu ihr ein, wie man zu einer Hure eingeht; so gingen sie ein zu Ohola und zu Oholiba, den lasterhaften Weibern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Aber gerechte Männer, die werden sie richten nach dem Rechte der Ehebrecherinnen und nach dem Rechte der Blutvergießerinnen; denn sie sind Ehebrecherinnen, und Blut ist an ihren Händen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Denn so spricht der Herr, Jehova: Ich will eine Versammlung wider sie heraufführen, und sie zur Mißhandlung und zur Beute übergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Und die Versammlung wird sie steinigen und sie mit ihren Schwertern zerhauen; ihre Söhne und ihre Töchter wird sie töten und ihre Häuser mit Feuer verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Und so werde ich die Schandtat wegschaffen aus dem Lande, damit alle Weiber sich zurechtweisen lassen und nicht nach eurer Schandtat tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Und sie werden eure Schandtat auf euch bringen, und die Sünden eurer Götzen werdet ihr tragen. Und ihr werdet wissen, daß ich der Herr, Jehova, bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Und das Wort Jehovas geschah zu mir im neunten Jahre, im zehnten Monat, am Zehnten des Monats, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Menschensohn, schreibe dir den Namen des Tages auf, dieses selbigen Tages! An diesem selbigen Tage rückt der König von Babel gegen Jerusalem heran.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Und rede ein Gleichnis zu dem widerspenstigen Hause und sprich zu ihnen: So spricht der Herr, Jehova: Setze den Topf auf, setze auf, und gieße auch Wasser darein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Tue seine Stücke zusammen darein, alle guten Stücke, Lende und Schulter; fülle ihn mit den besten Knochen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Nimm das beste Kleinvieh, und auch einen Holzstoß für die Knochen darunter; laß es tüchtig sieden, daß auch seine Knochen darin kochen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Darum spricht der Herr, Jehova, also: Wehe, Stadt der Blutschuld! Topf, an welchem sein Rost ist, und dessen Rost nicht von ihm abgeht! Stück für Stück hole sie heraus; nicht ist über sie das Los gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Denn ihr Blut ist in ihrer Mitte: Sie hat es auf einen kahlen Felsen getan, sie hat es nicht auf die Erde gegossen, daß man es mit Staub bedecken könnte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Um Grimm heraufzuführen, um Rache zu üben, habe ich ihr Blut auf einen kahlen Felsen getan, damit es nicht bedeckt würde. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Darum, so spricht der Herr, Jehova: Wehe, Stadt der Blutschuld! Auch ich werde den Holzstoß groß machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Häufe das Holz, zünde das Feuer an, mache das Fleisch gar und laß die Brühe auskochen, und die Knochen sollen verbrennen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Und stelle ihn leer auf seine Kohlen, damit sein Erz heiß und glühend werde, und seine Unreinigkeit in ihm schmelze, sein Rost vergehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Die Bemühungen hat er erschöpft, und sein vieler Rost geht nicht von ihm ab; ins Feuer mit seinem Rost! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'In deiner Unreinigkeit ist Schandtat. Weil ich dich gereinigt habe und du nicht rein geworden bist, so wirst du von deiner Unreinigkeit nicht mehr rein werden, bis ich meinen Grimm an dir stille.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Ich, Jehova, habe geredet. Es kommt, und ich werde es tun; ich werde nicht nachlassen und werde kein Mitleid haben und es mich nicht gereuen lassen. Nach deinen Wegen und nach deinen Handlungen werden sie dich richten, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Menschensohn, siehe, ich nehme die Lust deiner Augen von dir weg durch einen Schlag; und du sollst nicht klagen und nicht weinen, und keine Träne soll dir kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Seufze schweigend, Totenklage stelle nicht an; binde dir deinen Kopfbund um und ziehe deine Schuhe an deine Füße, und deinen Bart sollst du nicht verhüllen und Brot der Leute nicht essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Und ich redete zu dem Volke am Morgen, und am Abend starb mein Weib. Und ich tat am Morgen, wie mir geboten war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Da sprach das Volk zu mir: Willst du uns nicht kundtun, was dies uns bedeuten soll, daß du so tust?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Und ich sprach zu ihnen: Das Wort Jehovas ist zu mir geschehen also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Sprich zum Hause Israel: So spricht der Herr, Jehova: Siehe, ich werde mein Heiligtum entweihen, den Stolz eurer Stärke, die Lust eurer Augen und das Verlangen eurer Seele; und eure Söhne und eure Töchter, die ihr zurückgelassen habt, werden durchs Schwert fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Dann werdet ihr tun, wie ich getan habe: Den Bart werdet ihr nicht verhüllen und Brot der Leute nicht essen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'und eure Kopfbunde werden auf euren Häuptern sein, und eure Schuhe an euren Füßen; ihr werdet nicht klagen und nicht weinen, sondern werdet hinschwinden in euren Missetaten, und seufzen einer gegen den anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Und so wird euch Hesekiel zu einem Wahrzeichen sein: Nach allem, was er getan hat, werdet ihr tun. Wenn es kommt, dann werdet ihr wissen, daß ich der Herr, Jehova, bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Und du, Menschensohn, siehe, an dem Tage, da ich von ihnen wegnehmen werde ihre Stärke, die Freude ihrer Pracht, die Lust ihrer Augen und die Sehnsucht ihrer Seelen, ihre Söhne und ihre Töchter:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'An jenem Tage wird ein Entronnener zu dir kommen, um es deinen Ohren vernehmen zu lassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'an jenem Tage wird dein Mund aufgetan werden gegen den Entronnenen, und du wirst reden und nicht mehr verstummen. Und so sollst du ihnen zu einem Wahrzeichen sein; und sie werden wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Menschensohn, richte dein Angesicht gegen die Kinder Ammon und weissage wider sie;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'und sprich zu den Kindern Ammon: Höret das Wort des Herrn, Jehovas! So spricht der Herr, Jehova: Weil du Haha! sprichst über mein Heiligtum, daß es entweiht ist, und über das Land Israel, daß es verwüstet ist, und über das Haus Juda, daß sie in die Gefangenschaft zogen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'darum siehe, werde ich dich den Kindern des Ostens zum Besitztum geben, und sie werden ihre Zeltlager in dir aufschlagen und ihre Wohnungen in dir errichten; sie werden deine Früchte essen, und sie werden deine Milch trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Und ich werde Rabba zur Trift der Kamele machen, und die Kinder Ammon zum Lagerplatz der Herden. Und ihr werdet wissen, daß ich Jehova bin. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Denn so spricht der Herr, Jehova: Weil du in die Hände geklatscht und mit dem Fuße gestampft und mit aller Verachtung deiner Seele dich über das Land Israel gefreut hast:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'darum, siehe, werde ich meine Hand wider dich ausstrecken und dich den Nationen zur Beute geben, und ich werde dich ausrotten aus den Völkern und dich aus den Ländern vertilgen; ich werde dich vernichten, und du wirst wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'So spricht der Herr, Jehova: Weil Moab und Seir sprechen: Siehe, das Haus Juda ist wie alle Nationen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'darum, siehe, werde ich die Seiten Moabs öffnen von den Städten her, von seinen Städten her, in seinem ganzen Umfange, die Zierde des Landes, Beth-Jesimoth, Baal-Meon und bis nach Kirjathaim hin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'den Kindern des Ostens, zu den Kindern Ammon hinzu, und werde es ihnen zum Besitztum geben, auf daß der Kinder Ammon nicht mehr gedacht werde unter den Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'Und ich werde an Moab Gerichte üben; und sie werden wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'So spricht der Herr, Jehova: Weil Edom mit Rachsucht gegen das Haus Juda gehandelt, und sie sich sehr verschuldet haben, indem sie sich an ihnen rächten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'darum, so spricht der Herr, Jehova, werde ich meine Hand wider Edom ausstrecken und Menschen und Vieh aus ihm ausrotten; und ich werde es von Teman an zur Einöde machen, und bis nach Dedan hin werden sie durchs Schwert fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Und ich werde meine Rache über Edom bringen durch die Hand meines Volkes Israel, und sie werden an Edom handeln nach meinem Zorn und nach meinem Grimm. Und sie werden meine Rache kennen lernen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'So spricht der Herr, Jehova: Weil die Philister mit Rachsucht gehandelt und Rache geübt haben mit Verachtung der Seele, zur Zerstörung in ewiger Feindschaft:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'darum, so spricht der Herr, Jehova: Siehe, ich werde meine Hand wider die Philister ausstrecken, und werde die Kerethiter ausrotten und den Überrest an der Küste des Meeres vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Und ich werde durch Züchtigungen des Grimmes große Rache an ihnen üben. Und sie werden wissen, daß ich Jehova bin, wenn ich meine Rache über sie bringe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Und es geschah im elften Jahre, am Ersten des Monats, da geschah das Wort Jehovas zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Menschensohn, darum, daß Tyrus über Jerusalem spricht: Haha! Zerbrochen ist die Pforte der Völker; sie hat sich mir zugewandt; ich werde erfüllt werden, sie ist verwüstet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Darum, so spricht der Herr, Jehova: Siehe, ich will an dich, Tyrus! Und ich werde viele Nationen wider dich heraufführen, wie das Meer seine Wellen heraufführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Und sie werden die Mauern von Tyrus zerstören und seine Türme abbrechen; und ich werde seine Erde von ihm wegfegen und es zu einem kahlen Felsen machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'ein Ort zum Ausbreiten der Netze wird es sein mitten im Meere. Denn ich habe geredet, spricht der Herr, Jehova. Und es wird den Nationen zur Beute werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'und seine Töchter, die auf dem Gefilde sind, werden mit dem Schwerte getötet werden. Und sie werden wissen, daß ich Jehova bin. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Denn so spricht der Herr, Jehova: Siehe, ich werde Nebukadrezar, den König, von Babel, den König der Könige, von Norden her gegen Tyrus bringen, mit Rossen und Wagen und Reitern und mit einer großen Volksschar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Er wird deine Töchter auf dem Gefilde mit dem Schwerte töten; und er wird Belagerungstürme gegen dich aufstellen und einen Wall gegen dich aufschütten und Schilde gegen dich aufrichten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'und wird seine Mauerbrecher wider deine Mauern ansetzen und deine Türme mit seinen Eisen niederreißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Von der Menge seiner Rosse wird ihr Staub dich bedecken; vor dem Lärm der Reiter und Räder und Wagen werden deine Mauern erbeben, wenn er in deine Tore einziehen wird, wie man in eine erbrochene Stadt einzieht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Mit den Hufen seiner Rosse wird er alle deine Straßen zerstampfen; dein Volk wird er mit dem Schwerte töten, und die Bildsäulen deiner Stärke werden zu Boden sinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Und sie werden dein Vermögen rauben und deine Waren plündern, und deine Mauern abbrechen und deine Prachthäuser niederreißen; und deine Steine und dein Holz und deinen Schutt werden sie ins Wasser werfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Und ich werde dem Getöne deiner Lieder ein Ende machen, und der Klang deiner Lauten wird nicht mehr gehört werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Und ich werde dich zu einem kahlen Felsen machen; ein Ort zum Ausbreiten der Netze wirst du sein, du wirst nicht wieder aufgebaut werden. Denn ich, Jehova, habe geredet, spricht der Herr, Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'So spricht der Herr, Jehova, zu Tyrus: Werden nicht vom Gedröhne deines Sturzes, wenn der Erschlagene stöhnt, wenn in deiner Mitte gemordet wird, die Inseln erbeben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Und alle Fürsten des Meeres werden von ihren Thronen herabsteigen, und ihre Mäntel ablegen und ihre buntgewirkten Kleider ausziehen; in Schrecken werden sie sich kleiden, werden auf der Erde sitzen und jeden Augenblick erzittern und sich über dich entsetzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Und sie werden ein Klagelied über dich erheben und zu dir sprechen: Wie bist du untergegangen, du von den Meeren her Bewohnte, du berühmte Stadt, die mächtig auf dem Meere war, sie und ihre Bewohner, welche allen, die darin wohnten, ihren Schrecken einflößten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Nun erzittern die Inseln, am Tage deines Sturzes; und die Inseln die im Meere sind, sind bestürzt wegen deines Ausgangs. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Denn so spricht der Herr, Jehova: Wenn ich dich zu einer verwüsteten Stadt mache, den Städten gleich, die nicht mehr bewohnt werden; wenn ich die Flut über dich heraufführe, und die großen Wasser dich bedecken:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'so werde ich dich hinabstürzen zu denen, welche in die Grube hinabgefahren sind, zu dem Volke der Urzeit, und werde dich wohnen lassen in den untersten Örtern der Erde, in den Trümmern von der Vorzeit her, mit denen, welche in die Grube hinabgefahren sind, auf daß du nicht mehr bewohnt werdest; und ich werde Herrlichkeit setzen in dem Lande der Lebendigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Zum Schrecken werde ich dich machen, und du wirst nicht mehr sein; und du wirst gesucht und in Ewigkeit nicht wiedergefunden werden, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Und du, Menschensohn, erhebe ein Klagelied über Tyrus und sprich zu Tyrus:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'Die du wohnst an den Zugängen des Meeres und Handel treibst mit den Völkern nach vielen Inseln hin, so spricht der Herr, Jehova: Tyrus, du sprichst: Ich bin vollkommen an Schönheit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Deine Grenzen sind im Herzen der Meere; deine Bauleute haben deine Schönheit vollkommen gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Aus Zypressen von Senir bauten sie dir alles Doppelplankenwerk; sie nahmen Zedern vom Libanon, um dir einen Mast zu machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'aus Eichen von Basan machten sie deine Ruder; dein Verdeck machten sie aus Elfenbein, eingefaßt in Scherbinzeder von den Inseln der Kittäer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Byssus in Buntwirkerei aus Ägypten war dein Segel, um dir als Flagge zu dienen; blauer und roter Purpur von den Inseln Elischas war dein Zeltdach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Die Bewohner von Zidon und Arwad waren deine Ruderer; deine Weisen, die in dir waren, Tyrus, waren deine Steuermänner;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'die Ältesten von Gebal und seine Weisen waren in dir als Ausbesserer deiner Lecke. Alle Schiffe des Meeres und ihre Seeleute waren in dir, um deine Waren einzutauschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Perser und Lud und Put waren in deinem Heere deine Kriegsleute; Schild und Helm hängten sie in dir auf, sie gaben dir Glanz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Die Söhne Arwads und dein Heer waren auf deinen Mauern ringsum, und Tapfere waren auf deinen Türmen; ihre Schilde hängten sie ringsum an deinen Mauern auf; sie machten deine Schönheit vollkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tarsis trieb Handel mit dir wegen der Menge von allerlei Gütern; mit Silber, Eisen, Zinn und Blei bezahlten sie deinen Absatz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Jawan, Tubal und Mesech waren deine Kaufleute: Mit Menschenseelen und ehernen Geräten trieben sie Tauschhandel mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Die vom Hause Togarma zahlten Rosse und Reitpferde und Maulesel für deinen Absatz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Die Söhne Dedans waren deine Kaufleute. Viele Inseln standen in Handelsbeziehungen mit dir: Elefantenzähne und Ebenholz erstatteten sie dir als Zahlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Aram trieb Handel mit dir wegen der Menge deiner Erzeugnisse; mit Karfunkeln, rotem Purpur und Buntwirkerei und Byssus und Korallen und Rubinen bezahlten sie deinen Absatz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juda und das Land Israel waren deine Kaufleute; mit Weizen von Minnith und süßem Backwerk und Honig und Öl und Balsam trieben sie Tauschhandel mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damaskus trieb Handel mit dir um die Menge deiner Erzeugnisse, wegen der Menge von allerlei Gütern, mit Wein von Chelbon und Wolle von Zachar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Wedan und Jawan von Usal zahlten bearbeitetes Eisen für deinen Absatz; Kassia und Würzrohr waren für deinen Tauschhandel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan trieb Handel mit dir in Prachtdecken zum Reiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabien und alle Fürsten Kedars standen in Handelsbeziehungen mit dir; mit Fettschafen und Widdern und Böcken, damit trieben sie Handel mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Die Kaufleute von Scheba und Raghma waren deine Kaufleute; mit den vorzüglichsten Gewürzen und mit allerlei Edelsteinen und Gold bezahlten sie deinen Absatz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Haran und Kanne und Eden, die Kaufleute von Scheba, Assur und Kilmad waren deine Kaufleute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Sie handelten mit dir in Prachtgewändern, in Mänteln von blauem Purpur und Buntwirkerei, und in Schätzen von gezwirnten Garnen, in gewundenen und festen Schnüren, gegen deine Waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Die Tarsisschiffe waren deine Karawanen für deinen Tauschhandel. Und du wurdest angefüllt und sehr herrlich im Herzen der Meere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Deine Ruderer führten dich auf großen Wassern; der Ostwind zerschellte dich im Herzen der Meere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Deine Güter und dein Absatz, deine Tauschwaren, deine Seeleute und deine Steuermänner, die Ausbesserer deiner Lecke und die deine Waren eintauschten, und alle deine Kriegsleute, die in dir sind, samt deiner ganzen Schar, die in deiner Mitte ist, werden ins Herz der Meere fallen am Tage deines Sturzes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Von dem Getöse des Geschreies deiner Steuermänner werden die Gefilde erbeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Und alle, die das Ruder führen, die Seeleute, alle Steuermänner des Meeres, werden aus ihren Schiffen steigen, werden ans Land treten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'und sie werden ihre Stimme über dich hören lassen und bitterlich schreien; und sie werden Staub auf ihre Häupter werfen und sich in der Asche wälzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Und sie werden sich deinethalben kahl scheren und sich Sacktuch umgürten und werden deinetwegen weinen mit Betrübnis der Seele in bitterer Klage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Und in ihrem Jammern werden sie ein Klagelied über dich erheben und über dich klagen: Wer ist wie Tyrus, wie die Vernichtete inmitten des Meeres!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Als die Meere dir Absatz für deine Waren brachten, hast du viele Völker gesättigt; mit der Menge deiner Güter und deiner Waren hast du die Könige der Erde bereichert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Jetzt, da du von den Meeren weg zerschellt bist in den Tiefen der Wasser, und deine Waren und deine ganze Schar in deiner Mitte gefallen sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'entsetzen sich alle Bewohner der Inseln über dich, und ihre Könige schaudern, ihre Angesichter zittern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'die Händler unter den Völkern zischen über dich. Ein Schrecken bist du geworden, und bist dahin auf ewig!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Menschensohn, sprich zu dem Fürsten von Tyrus: So spricht der Herr, Jehova: Weil dein Herz sich erhebt, und du sprichst: \"Ich bin ein Gott, ich sitze auf einem Gottessitze im Herzen der Meere!\" (da du doch ein Mensch bist und nicht Gott) und hegst einen Sinn wie eines Gottes Sinn; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'siehe, du bist weiser als Daniel, nichts Verborgenes ist dunkel für dich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'durch deine Weisheit und durch deinen Verstand hast du dir Reichtum erworben, und hast Gold und Silber in deine Schatzkammern geschafft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'durch die Größe deiner Weisheit hast du mit deinem Handel deinen Reichtum gemehrt, und dein Herz hat sich wegen deines Reichtums erhoben; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'darum, so spricht der Herr, Jehova: Weil du einen Sinn hegst, wie eines Gottes Sinn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'darum, siehe, werde ich Fremde, die Gewalttätigsten der Nationen, über dich bringen; und sie werden ihre Schwerter ziehen wider die Schönheit deiner Weisheit, und deinen Glanz entweihen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'In die Grube werden sie dich hinabstürzen, und du wirst des Todes eines Erschlagenen sterben im Herzen der Meere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Wirst du wohl angesichts deines Mörders sagen: Ich bin ein Gott! da du doch ein Mensch bist, und nicht Gott, in der Hand derer, die dich erschlagen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Des Todes der Unbeschnittenen wirst du sterben durch die Hand der Fremden; denn ich habe geredet, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Menschensohn, erhebe ein Klagelied über den König von Tyrus und sprich zu ihm: So spricht der Herr, Jehova: Der du das Bild der Vollendung warst, voll von Weisheit und vollkommen an Schönheit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'du warst in Eden, dem Garten Gottes; allerlei Edelgestein war deine Decke: Sardis, Topas und Diamant, Chrysolith, Onyx und Jaspis, Saphir, Karfunkel und Smaragd und Gold. Das Kunstwerk deiner Tamburine und deiner Pfeifen war bei dir; an dem Tage, da du geschaffen wurdest, wurden sie bereitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Du warst ein schirmender, gesalbter Cherub, und ich hatte dich dazu gemacht; du warst auf Gottes heiligem Berge, du wandeltest inmitten feuriger Steine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Vollkommen warst du in deinen Wegen von dem Tage an, da du geschaffen worden, bis Unrecht an dir gefunden wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Durch die Größe deines Handels wurde dein Inneres mit Gewalttat erfüllt, und du sündigtest; und ich habe dich entweiht vom Berge Gottes hinweg und habe dich, du schirmender Cherub, vertilgt aus der Mitte der feurigen Steine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Dein Herz hat sich erhoben ob deiner Schönheit, du hast deine Weisheit zunichte gemacht wegen deines Glanzes; ich habe dich zu Boden geworfen, habe dich vor Königen dahingegeben, damit sie ihre Lust an dir sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Durch die Menge deiner Missetaten, in der Unrechtlichkeit deines Handels, hast du deine Heiligtümer entweiht; darum habe ich aus deinem Innern ein Feuer ausgehen lassen, welches dich verzehrt hat, und ich habe dich zu Asche gemacht auf der Erde vor den Augen aller derer, die dich sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Alle, die dich kennen unter den Völkern, entsetzen sich über dich; ein Schrecken bist du geworden, und bist dahin auf ewig!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Menschensohn, richte dein Angesicht gegen Zidon und weissage wider dasselbe und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'So spricht der Herr, Jehova: Siehe, ich will an dich, Zidon, und will mich verherrlichen in deiner Mitte; und sie werden wissen, daß ich Jehova bin, wenn ich Gerichte an ihm übe und mich an ihm heilige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Und ich werde die Pest darein senden und Blut auf seine Straßen; und Erschlagene werden in seiner Mitte fallen durch das Schwert, welches ringsum wider dasselbe sein wird. Und sie werden wissen, daß ich Jehova bin. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Und für das Haus Israel soll es nicht mehr einen stechenden Dorn und einen schmerzenden Stachel geben von allen um sie her, die sie verachteten. Und sie werden wissen, daß ich der Herr, Jehova, bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'So spricht der Herr, Jehova: Wenn ich das Haus Israel aus den Völkern sammeln werde, unter welche sie zerstreut worden sind, und ich mich an ihnen heilige vor den Augen der Nationen, dann werden sie in ihrem Lande wohnen, das ich meinem Knechte Jakob gegeben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Und sie werden in Sicherheit darin wohnen und Häuser bauen und Weinberge pflanzen; und sie werden in Sicherheit wohnen, wenn ich Gerichte geübt habe an allen, die sie verachteten aus ihrer Umgebung. Und sie werden wissen, daß ich Jehova, ihr Gott, bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Im zehnten Jahre, im zehnten Monat, am Zwölften des Monats, geschah das Wort Jehovas zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Menschensohn, richte dein Angesicht wider den Pharao, den König von Ägypten, und weissage wider ihn und wider ganz Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Rede und sprich: So spricht der Herr, Jehova: Siehe, ich will an dich, Pharao, König von Ägypten, du großes Seeungeheuer, das in seinen Strömen liegt, das da spricht: Mein Strom gehört mir, und ich habe ihn mir gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Und ich werde Haken in deine Kinnbacken legen und die Fische deiner Ströme an deine Schuppen sich hängen lassen, und werde dich aus deinen Strömen heraufziehen samt allen Fischen deiner Ströme, die an deinen Schuppen hängen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Und ich werde dich in die Wüste werfen, dich und alle Fische deiner Ströme; auf des Feldes Fläche wirst du fallen; du wirst nicht aufgelesen und nicht gesammelt werden: Den Tieren der Erde und den Vögeln des Himmels habe ich dich zur Speise gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Und alle Bewohner von Ägypten werden wissen, daß ich Jehova bin. Weil sie dem Hause Israel ein Rohrstab gewesen sind-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'wenn sie dich mit der Hand erfaßten, knicktest du und rissest ihnen die ganze Schulter auf; und wenn sie sich auf dich lehnten, zerbrachst du und machtest ihnen alle Hüften wanken');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'darum, so spricht der Herr, Jehova: Siehe, ich bringe das Schwert über dich und werde Menschen und Vieh aus dir ausrotten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'und das Land Ägypten wird zur Wüste und Einöde werden. Und sie werden wissen, daß ich Jehova bin. Weil der Pharao spricht: Der Strom ist mein, und ich habe ihn gemacht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'darum, siehe, will ich an dich und an deine Ströme; und ich werde das Land Ägypten zu öden, wüsten Einöden machen, von Migdol bis nach Syene, bis an die Grenze von Äthiopien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Der Fuß des Menschen wird es nicht durchwandern, und der Fuß des Tieres wird es nicht durchwandern, und es wird nicht bewohnt sein, vierzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Und ich werde das Land Ägypten zu einer Wüste machen inmitten verwüsteter Länder, und seine Städte werden inmitten verödeter Städte eine Wüste sein, vierzig Jahre; und ich werde die Ägypter unter die Nationen versprengen und sie in die Länder zerstreuen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Denn so spricht der Herr, Jehova: Am Ende von vierzig Jahren werde ich die Ägypter aus den Völkern sammeln, wohin sie versprengt waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'und ich werde die Gefangenschaft der Ägypter wenden und sie in das Land Pathros, in das Land ihres Ursprungs, zurückbringen, und daselbst werden sie ein niedriges Königreich sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Und es wird niedriger sein als die anderen Königreiche und sich nicht mehr über die Nationen erheben; und ich will sie vermindern, daß sie nicht mehr über die Nationen herrschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Und nicht soll es ferner dem Hause Israel zu einer Zuversicht sein, welche Missetat in Erinnerung bringt, indem sie sich nach ihnen hinwenden. Und sie werden wissen, daß ich der Herr, Jehova, bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Und es geschah im siebenundzwanzigsten Jahre, im ersten Monat, am Ersten des Monats, da geschah das Wort Jehovas zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Menschensohn, Nebukadrezar, der König von Babel, hat sein Heer eine schwere Arbeit tun lassen gegen Tyrus. Jedes Haupt ist kahl geworden, und jede Schulter ist abgerieben; und von Tyrus ist ihm und seinem Heere kein Lohn geworden für die Arbeit, welche er wider dasselbe getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Darum, so spricht der Herr, Jehova: Siehe, ich gebe Nebukadrezar, dem König von Babel, das Land Ägypten; und er wird seinen Reichtum wegtragen und seinen Raub rauben und seine Beute erbeuten, und das wird der Lohn sein für sein Heer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Als seine Belohnung, um welche er gearbeitet hat, habe ich ihm das Land Ägypten gegeben, weil sie für mich gearbeitet haben, spricht der Herr, Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'An jenem Tage werde ich dem Hause Israel ein Horn hervorsprossen lassen, und dir werde ich den Mund auftun in ihrer Mitte; und sie werden wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Menschensohn, weissage und sprich: So spricht der Herr, Jehova:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Heulet! Wehe der Tag! Denn nahe ist der Tag; ja, der Tag Jehovas ist nahe, ein Tag des Gewölks: Die Zeit der Nationen wird er sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Und das Schwert wird über Ägypten kommen; und im Lande Äthiopien wird große Angst sein, wenn Erschlagene in Ägypten fallen und man seinen Reichtum wegnimmt, und seine Grundfesten niedergerissen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Äthiopien und Put und Lud und alles Mischvolk und Kub und die Kinder des Bundeslandes werden mit ihnen durchs Schwert fallen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'So spricht Jehova: Ja, die, welche Ägypten stützen, werden fallen, und hinsinken wird der Stolz seiner Kraft; von Migdol bis nach Syene werden sie darin durchs Schwert fallen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Und sie werden verwüstet liegen inmitten verwüsteter Länder, und seine Städte werden inmitten verödeter Städte sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'Und sie werden wissen, daß ich Jehova bin, wenn ich Feuer anlege in Ägypten und alle seine Helfer zerschmettert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'An jenem Tage werden Boten von mir in Schiffen ausfahren, um das sichere Äthiopien zu erschrecken; und große Angst wird unter ihnen sein am Tage Ägyptens; denn siehe, es kommt! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'So spricht der Herr, Jehova: Ja, ich werde dem Getümmel Ägyptens ein Ende machen durch die Hand Nebukadrezars, des Königs von Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Er und sein Volk mit ihm, die Gewalttätigsten der Nationen, werden herbeigeführt werden, um das Land zu verderben; und sie werden ihre Schwerter ziehen wider Ägypten und das Land mit Erschlagenen füllen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Und ich werde die Ströme trocken legen, und das Land in die Hand von Bösewichtern verkaufen, und das Land und seine Fülle durch die Hand Fremder verwüsten. Ich, Jehova, habe geredet. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'So spricht der Herr, Jehova: Ja, ich werde die Götzen vertilgen und die Götzen aus Noph wegschaffen, und kein Fürst aus dem Lande Ägypten soll mehr sein; und ich werde Furcht bringen in das Land Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Und ich werde Pathros verwüsten, und Feuer anlegen in Zoan, und Gerichte üben an No.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Und ich werde meinen Grimm ausgießen über Sin, die Feste Ägyptens; und die Menge von No werde ich ausrotten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Und ich werde Feuer anlegen in Ägypten; Sin wird beben vor Angst, und No wird erbrochen werden, und Noph Feinde bei Tage!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Die Jünglinge von Awen und Pi-Beseth werden durch das Schwert fallen, und sie selbst werden in die Gefangenschaft ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Und zu Tachpanches wird der Tag sich verfinstern, wenn ich daselbst die Joche Ägyptens zerbreche, und der Stolz seiner Kraft darin ein Ende nimmt; Gewölk wird es bedecken, und seine Tochterstädte werden in die Gefangenschaft ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Und so werde ich Gerichte üben an Ägypten; und sie werden wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Und es geschah im elften Jahre, im ersten Monat, am Siebten des Monats, da geschah das Wort Jehovas zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Menschensohn, den Arm des Pharao, des Königs von Ägypten, habe ich zerbrochen; und siehe, er ist nicht verbunden worden, daß man Heilmittel angewandt, daß man einen Verband angelegt hätte, ihn zu verbinden, um ihn zu stärken, damit er das Schwert fasse. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Darum spricht der Herr, Jehova, also: Siehe, ich will an den Pharao, den König von Ägypten, und werde seine beiden Arme zerbrechen, den starken und den zerbrochenen, und werde das Schwert seiner Hand entfallen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Und ich werde die Ägypter unter die Nationen versprengen und sie in die Länder zerstreuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Und ich werde die Arme des Königs von Babel stärken und mein Schwert in seine Hand geben; und die Arme des Pharao werde ich zerbrechen, daß er wie ein Erschlagener vor ihm ächzen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Und ich werde die Arme des Königs von Babel stärken, aber die Arme des Pharao werden sinken. Und sie werden wissen, daß ich Jehova bin, wenn ich mein Schwert in die Hand des Königs von Babel gebe, und er es recken wird gegen das Land Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Und ich werde die Ägypter unter die Nationen versprengen und sie in die Länder zerstreuen; und sie werden wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Und es geschah im elften Jahre, im dritten Monat, am Ersten des Monats, da geschah das Wort Jehovas zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Menschensohn, sprich zu dem Pharao, dem König von Ägypten, und zu seiner Menge: Wem gleichst du in deiner Größe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Siehe, Assur war eine Zeder auf dem Libanon, mit schönen Zweigen, ein schattendes Dickicht und von hohem Wuchs; und sein Wipfel war zwischen den Wolken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Die Wasser zogen ihn groß, die Flut machte ihn hoch; ihre Ströme gingen rings um ihre Pflanzung, und sie entsandte ihre Kanäle zu allen Bäumen des Feldes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Darum wurde sein Wuchs höher als alle Bäume des Feldes und seine Zweige wurden groß und seine Äste lang von den vielen Wassern, als er sich ausbreitete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Alle Vögel des Himmels nisteten in seinen Zweigen, und alle Tiere des Feldes gebaren unter seinen Ästen; und in seinem Schatten wohnten alle großen Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Und er war schön in seiner Größe und in der Länge seiner Schößlinge; denn seine Wurzeln waren an vielen Wassern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Die Zedern im Garten Gottes verdunkelten ihn nicht, Zypressen kamen seinen Zweigen nicht gleich, und Platanen waren nicht wie seine Äste; kein Baum im Garten Gottes kam ihm an Schönheit gleich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Ich hatte ihn schön gemacht in der Menge seiner Schößlinge; und es beneideten ihn alle Bäume Edens, die im Garten Gottes waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Darum, so sprach der Herr, Jehova: Weil du hoch geworden bist an Wuchs, und er seinen Wipfel bis zwischen die Wolken streckte, und sein Herz sich erhob wegen seiner Höhe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'so werde ich ihn in die Hand des Mächtigen der Nationen geben; nach seiner Bosheit soll er mit ihm handeln; ich habe ihn verstoßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Und Fremde, die Gewalttätigsten der Nationen, hieben ihn um und warfen ihn hin; seine Schößlinge fielen auf die Berge und in alle Täler, und seine Äste wurden zerbrochen und geworfen in alle Gründe der Erde; und alle Völker der Erde zogen aus seinem Schatten hinweg und ließen ihn liegen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'auf seinen umgefallenen Stamm ließen sich alle Vögel des Himmels nieder, und über seine Äste kamen alle Tiere des Feldes:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'auf daß keine Bäume am Wasser wegen ihres Wuchses sich überheben und ihren Wipfel bis zwischen die Wolken strecken, und keine Wassertrinkenden auf sich selbst sich stützen wegen ihrer Höhe; denn sie alle sind dem Tode hingegeben in die untersten Örter der Erde, mitten unter den Menschenkindern, zu denen hin, welche in die Grube hinabgefahren sind. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'So spricht der Herr, Jehova: An dem Tage, da er in den Scheol hinabfuhr, machte ich ein Trauern; ich verhüllte um seinetwillen die Tiefe und hielt ihre Ströme zurück, und die großen Wasser wurden gehemmt; und den Libanon hüllte ich in Schwarz um seinetwillen, und um seinetwillen verschmachteten alle Bäume des Feldes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Von dem Getöse seines Falles machte ich die Nationen erbeben, als ich ihn in den Scheol hinabfahren ließ zu denen, welche in die Grube hinabgefahren sind. Und alle Bäume Edens, das Auserwählte und Beste des Libanon, alle Wassertrinkenden, trösteten sich in den untersten Örtern der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Auch sie fuhren mit ihm in den Scheol hinab zu den vom Schwerte Erschlagenen, die als seine Helfer in seinem Schatten saßen unter den Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Wem gleichst du so an Herrlichkeit und an Größe unter den Bäumen Edens? Und so sollst du mit den Bäumen Edens hinabgestürzt werden in die untersten Örter der Erde, sollst unter den Unbeschnittenen liegen, bei den vom Schwerte Erschlagenen. Das ist der Pharao und seine ganze Menge, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Und es geschah im zwölften Jahre, im zwölften Monat, am Ersten des Monats, da geschah das Wort Jehovas zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Menschensohn, erhebe ein Klagelied über den Pharao, den König von Ägypten, und sprich zu ihm: Einem jungen Löwen unter den Nationen wurdest du verglichen; und doch warst du wie ein Seeungeheuer in den Meeren, und du brachst hervor in deinen Strömen und trübtest die Wasser mit deinen Füßen und wühltest ihre Ströme auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'So spricht der Herr, Jehova: Daher werde ich mein Netz über dich ausbreiten durch eine Schar vieler Völker, und sie werden dich in meinem Garne heraufziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Und ich werde dich auf das Land werfen, werde dich auf das freie Feld schleudern; und ich werde machen, daß alle Vögel des Himmels sich auf dir niederlassen und die Tiere der ganzen Erde sich von dir sättigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Und ich werde dein Fleisch auf die Berge bringen und die Täler mit deinem Aase füllen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Und ich werde das Land bis an die Berge mit den Strömen deines Blutes tränken, und die Gründe sollen von dir angefüllt werden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Und ich werde, wenn ich dich auslösche, den Himmel bedecken und seine Sterne verdunkeln; ich werde die Sonne mit Gewölk bedecken, und der Mond wird sein Licht nicht scheinen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Alle leuchtenden Lichter am Himmel werde ich deinetwegen verdunkeln, und ich werde Finsternis über dein Land bringen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Und ich werde das Herz vieler Völker traurig machen, wenn ich deinen Sturz unter die Nationen ausbringe, in die Länder, die du nicht gekannt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Und ich werde machen, daß viele Völker sich über dich entsetzen, und ihre Könige werden über dich schaudern, wenn ich mein Schwert vor ihnen schwingen werde; und sie werden jeden Augenblick zittern, ein jeder für sein Leben, am Tage deines Falles. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Denn so spricht der Herr, Jehova: Das Schwert des Königs von Babel wird über dich kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Durch die Schwerter von Helden werde ich deine Menge fällen: Die Gewalttätigsten der Nationen sind sie alle; und sie werden die Hoffart Ägyptens zerstören, und seine ganze Menge wird vertilgt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Und ich werde all sein Vieh an den vielen Wassern vernichten, daß der Fuß des Menschen sie nicht mehr trübe, noch sie trüben die Klauen des Viehes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Dann werde ich ihre Wasser sich klären und ihre Flüsse wie Öl fließen lassen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Wenn ich das Land Ägypten zu einer Wüste mache, und wenn das Land seiner Fülle beraubt wird, indem ich alle seine Bewohner schlage, so werden sie wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Das ist ein Klagelied, und man wird es klagend singen, die Töchter der Nationen werden es klagend singen; sie werden es klagend singen über Ägypten und über seine ganze Menge, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Und es geschah im zwölften Jahre, am Fünfzehnten des Monats, da geschah das Wort Jehovas zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Menschensohn, wehklage über die Menge Ägyptens, und stürze sie hinab, sie und die Töchter herrlicher Nationen, in die untersten Örter der Erde, zu denen, welche in die Grube hinabgefahren sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Wen übertriffst du an Lieblichkeit? Fahre hinab und werde zu den Unbeschnittenen hingelegt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Inmitten der vom Schwert Erschlagenen sollen sie fallen! Das Schwert ist übergeben; schleppet Ägypten herbei und seine ganze Menge!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Aus der Mitte des Scheols reden von ihm die Mächtigen der Helden mit seinen Helfern. Sie sind hinabgefahren, sie liegen da, die Unbeschnittenen, vom Schwert erschlagen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Dort ist Assur und seine ganze Schar; rings um ihn her ihre Gräber: Sie alle sind erschlagen, durchs Schwert Gefallene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Seine Gräber sind in der tiefsten Grube gemacht, und seine Schar ist rings um sein Grab. Sie alle sind erschlagen, durchs Schwert gefallen, welche Schrecken verbreiteten im Lande der Lebendigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Dort ist Elam, und seine ganze Menge rings um sein Grab. Sie alle sind erschlagen, durchs Schwert Gefallene, welche unbeschnitten hinabfuhren in die untersten Örter der Erde, welche ihren Schrecken verbreiteten im Lande der Lebendigen; und sie tragen ihre Schmach bei denen, welche in die Grube hinabgefahren sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Mitten unter Erschlagenen hat man ihm ein Lager gegeben mit seiner ganzen Menge; rings um ihn her sind ihre Gräber. Sie alle, unbeschnitten, sind vom Schwert erschlagen, weil ihr Schrecken verbreitet war im Lande der Lebendigen; und sie tragen ihre Schmach bei denen, welche in die Grube hinabgefahren sind. Mitten unter Erschlagene ist er gelegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Dort ist Mesech-Tubal und seine ganze Menge; rings um ihn her ihre Gräber. Sie alle, unbeschnitten, sind vom Schwert erschlagen, weil sie ihren Schrecken verbreiteten im Lande der Lebendigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Und sie liegen nicht bei den Helden der Unbeschnittenen, die gefallen sind, welche in den Scheol hinabfuhren mit ihren Kriegswaffen, und denen man ihre Schwerter unter ihre Häupter legte. Und ihre Missetaten sind über ihre Gebeine gekommen, weil sie ein Schrecken der Helden waren im Lande der Lebendigen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Auch du, Ägypten, wirst inmitten der Unbeschnittenen zerschmettert werden und bei den vom Schwert Erschlagenen liegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Dort ist Edom, seine Könige und alle seine Fürsten, die trotz ihrer Macht zu den vom Schwert Erschlagenen gelegt wurden; sie liegen bei den Unbeschnittenen und bei denen, welche in die Grube hinabgefahren sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Dort sind die Fürsten des Nordens insgesamt und alle Zidonier, welche zu den Erschlagenen hinabgefahren und trotz des Schreckens vor ihrer Macht zu Schanden geworden sind; und sie liegen unbeschnitten bei den vom Schwert Erschlagenen, und tragen ihre Schmach mit denen, welche in die Grube hinabgefahren sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Der Pharao wird sie sehen und sich trösten über seine ganze Menge. Vom Schwert erschlagen sind der Pharao und sein ganzes Heer, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Denn ich ließ ihn seinen Schrecken verbreiten im Lande der Lebendigen; und so wird er hingelegt werden inmitten der Unbeschnittenen zu den vom Schwert Erschlagenen, der Pharao und seine ganze Menge, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Menschensohn, rede zu den Kindern deines Volkes und sprich zu ihnen: Wenn ich das Schwert über ein Land bringe, und das Volk des Landes einen Mann aus seiner Gesamtheit nimmt und ihn für sich zum Wächter setzt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'und er sieht das Schwert über das Land kommen, und stößt in die Posaune und warnt das Volk: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'Wenn einer den Schall der Posaune hört und sich nicht warnen läßt, so daß das Schwert kommt und ihn wegrafft, so wird sein Blut auf seinem Kopfe sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Er hat den Schall der Posaune gehört und hat sich nicht warnen lassen: Sein Blut wird auf ihm sein; denn hätte er sich warnen lassen, so würde er seine Seele errettet haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Wenn aber der Wächter das Schwert kommen sieht, und er stößt nicht in die Posaune, und das Volk wird nicht gewarnt, so daß das Schwert kommt und von ihnen eine Seele wegrafft, so wird dieser wegen seiner Ungerechtigkeit weggerafft; aber sein Blut werde ich von der Hand des Wächters fordern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Du nun, Menschensohn, ich habe dich dem Hause Israel zum Wächter gesetzt: Du sollst das Wort aus meinem Munde hören und sie von meinetwegen warnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Wenn ich zu dem Gesetzlosen spreche: Gesetzloser, du sollst gewißlich sterben! und du redest nicht, um den Gesetzlosen vor seinem Wege zu warnen, so wird er, der Gesetzlose, wegen seiner Ungerechtigkeit sterben; aber sein Blut werde ich von deiner Hand fordern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Wenn du aber den Gesetzlosen vor seinem Wege warnst, damit er von demselben umkehre, und er von seinem Wege nicht umkehrt, so wird er wegen seiner Ungerechtigkeit sterben; du aber hast deine Seele errettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Und du, Menschensohn, sprich zu dem Hause Israel: Also sprechet ihr und saget: Unsere Übertretungen und unsere Sünden sind auf uns, und in denselben schwinden wir dahin; wie könnten wir denn leben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Sprich zu ihnen: So wahr ich lebe, spricht der Herr, Jehova, ich habe kein Gefallen am Tode des Gesetzlosen, sondern daß der Gesetzlose von seinem Wege umkehre und lebe! Kehret um, kehret um von euren bösen Wegen! Denn warum wollt ihr sterben, Haus Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Und du, Menschensohn, sprich zu den Kindern deines Volkes: Die Gerechtigkeit des Gerechten wird ihn nicht erretten am Tage seiner Übertretung; und die Gesetzlosigkeit des Gesetzlosen, er wird nicht durch dieselbe fallen an dem Tage, da er von seiner Gesetzlosigkeit umkehrt; und der Gerechte wird nicht durch seine Gerechtigkeit leben können an dem Tage, da er sündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Wenn ich dem Gerechten sage, daß er gewißlich leben soll, und er verläßt sich auf seine Gerechtigkeit und tut unrecht: So wird aller seiner gerechten Taten nicht gedacht werden, und wegen seines Unrechts, das er getan hat, deswegen wird er sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Wenn ich aber zu dem Gesetzlosen spreche: Du sollst gewißlich sterben; und er kehrt von seiner Sünde um und übt Recht und Gerechtigkeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'so daß der Gesetzlose das Pfand zurückgibt, Geraubtes erstattet, in den Satzungen des Lebens wandelt, ohne unrecht zu tun, so soll er gewißlich leben, er soll nicht sterben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'aller seiner Sünden, die er begangen hat, soll ihm nicht gedacht werden; Recht und Gerechtigkeit hat er geübt: Er soll gewißlich leben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Und die Kinder deines Volkes sprechen: Der Weg des Herrn ist nicht recht; aber ihr Weg ist nicht recht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Wenn der Gerechte von seiner Gerechtigkeit umkehrt und unrecht tut, so wird er deswegen sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Und wenn der Gesetzlose von seiner Gesetzlosigkeit umkehrt und Recht und Gerechtigkeit übt, so wird er um deswillen leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Und doch sprechet ihr: Der Weg Jehovas ist nicht recht. Ich werde euch richten, einen jeden nach seinen Wegen, Haus Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Und es geschah im zwölften Jahre unserer Wegführung, im zehnten Monat, am Fünften des Monats, da kam ein Entronnener aus Jerusalem zu mir und sprach: Die Stadt ist geschlagen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Und die Hand Jehovas war am Abend über mich gekommen vor der Ankunft des Entronnenen, und er hatte meinen Mund aufgetan, bis jener am Morgen zu mir kam; und so war mein Mund aufgetan, und ich verstummte nicht mehr. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Menschensohn, die Bewohner jener Trümmer im Lande Israel sprechen und sagen: Abraham war ein einzelner, und er erhielt das Land zum Besitztum; wir aber sind viele, uns ist das Land zum Besitztum gegeben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Darum sprich zu ihnen: So spricht der Herr, Jehova: Ihr esset mit dem Blute, und erhebet eure Augen zu euren Götzen und vergießet Blut, und ihr solltet das Land besitzen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Ihr steifet euch auf euer Schwert, verübet Greuel und verunreiniget einer des anderen Weib, und ihr solltet das Land besitzen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'So sollst du zu ihnen sprechen: So spricht der Herr, Jehova: So wahr ich lebe, die in den Trümmern sind, sollen durchs Schwert fallen; und wer auf dem freien Felde ist, den gebe ich den wilden Tieren hin, daß sie ihn fressen; und die in den Festungen und in den Höhlen sind, sollen an der Pest sterben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Und ich werde das Land zur Wüste und Verwüstung machen, und der Stolz seiner Stärke wird ein Ende haben; und die Berge Israels werden wüst sein, so daß niemand darüber hinwandert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Und sie werden wissen, daß ich Jehova bin, wenn ich das Land zur Wüste und Verwüstung mache wegen all ihrer Greuel, die sie verübt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Und du, Menschensohn, die Kinder deines Volkes unterreden sich über dich an den Wänden und in den Türen der Häuser; und einer redet mit dem anderen, ein jeder mit seinem Bruder, und spricht: Kommet doch und höret, was für ein Wort von Jehova ausgeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Und sie kommen scharenweise zu dir und sitzen vor dir als mein Volk und hören deine Worte, aber sie tun sie nicht; sondern sie tun, was ihrem Munde angenehm ist, ihr Herz geht ihrem Gewinne nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Und siehe, du bist ihnen wie ein liebliches Lied, wie einer, der eine schöne Stimme hat und gut zu spielen versteht; und sie hören deine Worte, doch sie tun sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Wenn es aber kommt, siehe, es kommt! so werden sie wissen, daß ein Prophet in ihrer Mitte war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Menschensohn, weissage wider die Hirten Israels, weissage und sprich zu ihnen, den Hirten: So spricht der Herr, Jehova: Wehe den Hirten Israels, die sich selbst weiden! Sollen die Hirten nicht die Herde weiden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Ihr esset das Fett und kleidet euch mit der Wolle, das fette Vieh schlachtet ihr; die Herde weidet ihr nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Die Schwachen habt ihr nicht gestärkt und das Kranke nicht geheilt und das Verwundete nicht verbunden, und das Versprengte führtet ihr nicht zurück, und das Verlorene suchtet ihr nicht; und mit Strenge habt ihr über sie geherrscht und mit Härte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Und so wurden sie zerstreut, weil sie ohne Hirten waren; und sie wurden allen Tieren des Feldes zur Speise, und wurden zerstreut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Meine Schafe irren umher auf allen Bergen und auf jedem hohen Hügel; und über das ganze Land hin sind meine Schafe zerstreut worden, und da ist niemand, der nach ihnen fragt, und niemand, der sie sucht. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Darum, ihr Hirten, höret das Wort Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'So wahr ich lebe, spricht der Herr, Jehova: Weil meine Schafe zur Beute und meine Schafe allen Tieren des Feldes zur Speise geworden sind, weil kein Hirte da ist, und meine Hirten nicht nach meinen Schafen fragen, und die Hirten sich selbst weiden, aber nicht meine Schafe weiden:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'darum, ihr Hirten, höret das Wort Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'So spricht der Herr, Jehova: Siehe, ich will an die Hirten, und ich werde meine Schafe von ihrer Hand fordern und machen, daß sie aufhören, die Schafe zu weiden, damit die Hirten nicht mehr sich selbst weiden; und ich werde meine Schafe von ihrem Munde erretten, daß sie ihnen nicht mehr zur Speise seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Denn so spricht der Herr, Jehova: Siehe, ich bin da, und ich will nach meinen Schafen fragen und mich ihrer annehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Wie ein Hirt sich seiner Herde annimmt an dem Tage, da er unter seinen zerstreuten Schafen ist, also werde ich mich meiner Schafe annehmen und werde sie erretten aus allen Orten, wohin sie zerstreut worden sind am Tage des Gewölks und des Wolkendunkels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Und ich werde sie herausführen aus den Völkern und sie aus den Ländern sammeln und sie in ihr Land bringen; und ich werde sie weiden auf den Bergen Israels, in den Tälern und an allen Wohnplätzen des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Auf guter Weide werde ich sie weiden, und auf den hohen Bergen Israels wird ihre Trift sein; daselbst, auf den Bergen Israels, werden sie auf guter Trift lagern und fette Weide beweiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Ich will meine Schafe weiden, und ich will sie lagern, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Das Verlorene will ich suchen und das Versprengte zurückführen, und das Verwundete will ich verbinden, und das Kranke will ich stärken; das Fette aber und das Starke werde ich vertilgen: Nach Recht werde ich sie weiden. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Und ihr, meine Herde, so spricht der Herr, Jehova: Siehe, ich werde richten zwischen Schaf und Schaf, den Widdern und den Böcken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Ist es euch zu wenig, daß ihr die gute Weide abweidet und das Übrige eurer Weide mit euren Füßen zertretet, und daß ihr das abgeklärte Wasser trinket und das Übriggebliebene mit euren Füßen trübet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Und meine Schafe sollen abweiden, was mit euren Füßen zertreten, und trinken, was mit euren Füßen getrübt ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Darum, so spricht der Herr, Jehova, zu ihnen: Siehe, ich bin da, und ich werde richten zwischen fettem Schaf und magerem Schaf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Weil ihr all die Schwachen mit Seite und Schulter verdränget und mit euren Hörnern stoßet, bis ihr sie nach außen hin zerstreut habt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'so will ich meine Schafe retten, damit sie nicht mehr zur Beute seien; und ich werde richten zwischen Schaf und Schaf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Und ich werde einen Hirten über sie erwecken, und er wird sie weiden, meinen Knecht David: der wird sie weiden, und der wird ihr Hirt sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Und ich, Jehova, werde ihr Gott sein, und mein Knecht David wird Fürst sein in ihrer Mitte. Ich, Jehova, habe geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Und ich werde einen Bund des Friedens mit ihnen machen, und werde die bösen Tiere aus dem Lande vertilgen; und sie werden in der Wüste sicher wohnen und in den Wäldern schlafen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Und ich werde sie und die Umgebungen meines Hügels zum Segen machen; und ich werde den Regen fallen lassen zu seiner Zeit, Regen des Segens werden es sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Und der Baum des Feldes wird seine Frucht geben, und das Land wird seinen Ertrag geben; und sie werden in ihrem Lande sicher sein. Und sie werden wissen, daß ich Jehova bin, wenn ich die Stäbe ihres Joches zerbreche und sie aus der Hand derer errette, welche sie knechteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Und sie werden nicht mehr den Nationen zur Beute sein, und die wilden Tiere der Erde werden sie nicht mehr fressen; sondern sie werden in Sicherheit wohnen, und niemand wird sie aufschrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Und ich werde ihnen eine Pflanzung erwecken zum Ruhme, und sie werden nicht mehr durch Hunger weggerafft werden im Lande und nicht mehr die Schmach der Nationen tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Und sie werden wissen, daß ich, Jehova, ihr Gott, mit ihnen bin, und daß sie, das Haus Israel, mein Volk sind, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Und ihr, meine Herde, Herde meiner Weide, ihr seid Menschen; ich bin euer Gott, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Menschensohn, richte dein Angesicht wider das Gebirge Seir,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'und weissage wider dasselbe und sprich zu ihm: So spricht der Herr, Jehova: Siehe, ich will an dich, Gebirge Seir; und ich werde meine Hand wider dich ausstrecken und dich zur Wüste und Verwüstung machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'und ich werde deine Städte zur Einöde machen, und du selbst wirst eine Wüste werden. Und du wirst wissen, daß ich Jehova bin. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Weil du eine beständige Feindschaft hegtest und die Kinder Israel der Gewalt des Schwertes preisgabst zur Zeit ihrer Not, zur Zeit der Ungerechtigkeit des Endes:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'darum, so wahr ich lebe, spricht der Herr, Jehova, werde ich dich zu Blut machen, und Blut wird dich verfolgen; weil du Blut nicht gehaßt, so soll Blut dich verfolgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Und ich werde das Gebirge Seir zur Wüstenei und Verwüstung machen, und den Hin-und Wiederziehenden aus ihm ausrotten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Und seine Berge werde ich mit seinen Erschlagenen füllen; auf deinen Hügeln und in deinen Tälern und in allen deinen Gründen sollen vom Schwert Erschlagene fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Zu ewigen Wüsteneien werde ich dich machen, und deine Städte sollen nicht mehr bewohnt werden. Und ihr werdet wissen, daß ich Jehova bin. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Weil du sprachst: Die beiden Nationen und die beiden Länder sollen mein sein, und wir werden es in Besitz nehmen, da doch Jehova daselbst war:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'darum, so wahr ich lebe, spricht der Herr, Jehova, werde ich handeln nach deinem Zorn und nach deiner Eifersucht, wie du infolge deines Hasses gegen sie gehandelt hast; und ich werde mich unter ihnen kundtun, sobald ich dich gerichtet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Und du wirst wissen, daß ich, Jehova, alle deine Schmähungen gehört habe, welche du gegen die Berge Israels ausgesprochen hast, indem du sagtest: Sie sind verwüstet, uns sind sie zur Speise gegeben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Und ihr habt mit eurem Munde gegen mich großgetan und eure Worte gegen mich gehäuft; ich habe es gehört. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'So spricht der Herr, Jehova: Wenn die ganze Erde sich freut, werde ich dir Verwüstung bereiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Wie du deine Freude hattest an dem Erbteil des Hauses Israel, darum daß es verwüstet war, ebenso werde ich dir tun: Eine Wüste sollst du werden, Gebirge Seir und ganz Edom insgesamt! Und sie werden wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Und du, Menschensohn, weissage über die Berge Israels und sprich: Berge Israels, höret das Wort Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'So spricht der Herr, Jehova: Weil der Feind über euch spricht: Haha! und: Die ewigen Höhen, sie sind uns zum Besitztum geworden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'darum weissage und sprich: So spricht der Herr, Jehova: Darum, ja darum, daß man euch von allen Seiten her verwüstet und angeschnaubt hat, so daß ihr dem Überrest der Nationen ein Besitztum geworden und ins Gerede der Zunge und ins Geschwätz der Leute gekommen seid:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'darum, ihr Berge Israels, höret das Wort des Herrn, Jehovas! So spricht der Herr, Jehova, zu den Bergen und zu den Hügeln, zu den Gründen und zu den Tälern, und zu den wüsten Trümmern und zu den verlassenen Städten, welche dem Überrest der Nationen ringsum zur Beute und zum Spott geworden sind-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'darum, so spricht der Herr, Jehova: Wahrlich, im Feuer meines Eifers habe ich geredet wider den Überrest der Nationen und wider ganz Edom, die sich mein Land zum Besitztum gemacht haben, mit ganzer Herzensfreude, mit Verachtung der Seele, um es zur Plünderung auszuleeren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Darum weissage von dem Lande Israel und sprich zu den Bergen und zu den Hügeln, zu den Gründen und zu den Tälern: So spricht der Herr, Jehova: Siehe, in meinem Eifer und in meinem Grimm habe ich geredet, weil ihr die Schmach der Nationen getragen habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Darum, so spricht der Herr, Jehova: Ich, ich habe meine Hand erhoben: Wenn nicht die Nationen, welche rings um euch her sind, ihre eigene Schmach tragen sollen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Ihr aber, Berge Israels, ihr sollt meinem Volke Israel eure Zweige treiben und eure Frucht tragen, denn sie sind nahe daran zu kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Denn siehe, ich will zu euch kommen, und ich will mich zu euch wenden, und ihr sollt bebaut und besät werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Und ich werde die Menschen auf euch vermehren, das ganze Haus Israel insgesamt; und die Städte sollen bewohnt und die Trümmer aufgebaut werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Und ich werde Menschen und Vieh auf euch vermehren, und sie werden sich mehren und fruchtbar sein; und ich werde euch bewohnt machen, wie in euren Vorzeiten, und werde euch wohltun, mehr als in euren Anfängen. Und ihr werdet wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Und ich werde Menschen, mein Volk Israel, auf euch wandeln lassen, und sie werden dich besitzen, und du wirst ihnen zum Erbteil sein; und du wirst sie hinfort nicht mehr der Kinder berauben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'So spricht der Herr, Jehova: Weil sie zu euch sprechen: Du verzehrst Menschen und hast deine Nation der Kinder beraubt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'darum wirst du nicht mehr Menschen verzehren, und wirst deine Nation nicht mehr straucheln machen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Und ich will dich nicht mehr die Schmähung der Nationen hören lassen, und den Hohn der Völker sollst du nicht mehr tragen; und du sollst deine Nation nicht mehr straucheln machen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Menschensohn, das Haus Israel wohnte in seinem Lande, und sie verunreinigten es durch ihren Weg und durch ihre Handlungen; ihr Weg war vor mir wie die Unreinigkeit eines unreinen Weibes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Da goß ich meinen Grimm über sie aus wegen des Blutes, das sie im Lande vergossen, und weil sie es durch ihre Götzen verunreinigt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Und ich versprengte sie unter die Nationen, und sie wurden in die Länder zerstreut; ich richtete sie nach ihrem Wege und nach ihren Handlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Und als sie zu den Nationen kamen, wohin sie kamen, da entweihten sie meinen heiligen Namen, indem man von ihnen sagte: Jehovas Volk sind diese, und aus seinem Lande sind sie gezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Aber ich habe meinen heiligen Namen verschont, welchen das Haus Israel entweiht hat unter den Nationen, wohin sie kamen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Darum sprich zum Hause Israel: So spricht der Herr, Jehova: Nicht um euretwillen tue ich es, Haus Israel, sondern um meines heiligen Namens willen, den ihr entweiht habt unter den Nationen, wohin ihr gekommen seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Und ich werde meinen großen Namen heiligen, der entweiht ist unter den Nationen, welchen ihr entweiht habt in ihrer Mitte. Und die Nationen werden wissen, daß ich Jehova bin, spricht der Herr, Jehova, wenn ich mich vor ihren Augen an euch heilige. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Und ich werde euch aus den Nationen holen und euch sammeln aus allen Ländern und euch in euer Land bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Und ich werde reines Wasser auf euch sprengen, und ihr werdet rein sein; von allen euren Unreinigkeiten und von allen euren Götzen werde ich euch reinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Und ich werde euch ein neues Herz geben und einen neuen Geist in euer Inneres geben; und ich werde das steinerne Herz aus eurem Fleische wegnehmen und euch ein fleischernes Herz geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Und ich werde meinen Geist in euer Inneres geben; und ich werde machen, daß ihr in meinen Satzungen wandelt und meine Rechte bewahret und tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Und ihr werdet in dem Lande wohnen, das ich euren Vätern gegeben habe; und ihr werdet mein Volk, und ich werde euer Gott sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Und ich werde euch befreien von allen euren Unreinigkeiten. Und ich werde das Getreide herbeirufen und es mehren, und keine Hungersnot mehr auf euch bringen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'und ich werde die Frucht des Baumes und den Ertrag des Feldes mehren, auf daß ihr nicht mehr den Schimpf einer Hungersnot traget unter den Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Und ihr werdet eurer bösen Wege gedenken und eurer Handlungen, die nicht gut waren, und werdet Ekel an euch selbst empfinden wegen eurer Missetaten und eurer Greuel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Nicht um euretwillen tue ich es, spricht der Herr, Jehova, das sei euch kund; schämet euch und werdet beschämt vor euren Wegen, Haus Israel! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'So spricht der Herr, Jehova: An dem Tage, da ich euch reinigen werde von allen euren Missetaten, da will ich die Städte bewohnt machen, und die Trümmer sollen aufgebaut werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'Und das verwüstete Land soll bebaut werden, statt daß es eine Wüste war vor den Augen jedes Vorüberziehenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'Und man wird sagen: Dieses Land da, das verwüstete, ist wie der Garten Eden geworden, und die verödeten und verwüsteten und zerstörten Städte sind befestigt und bewohnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Und die Nationen, welche rings um euch her übrigbleiben werden, werden wissen, daß ich, Jehova, das Zerstörte aufbaue, das Verwüstete bepflanze. Ich, Jehova, habe geredet und werde es tun. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'So spricht der Herr, Jehova: Auch noch um dieses werde ich mich vom Hause Israel erbitten lassen, daß ich es ihnen tue: Ich werde sie an Menschen vermehren wie eine Herde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Wie eine geheiligte Herde, wie die Herde Jerusalems an seinen Festen, also werden die verödeten Städte voll Menschenherden sein. Und sie werden wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Die Hand Jehovas kam über mich, und Jehova führte mich im Geiste hinaus und ließ mich nieder mitten im Tale; und dieses war voll Gebeine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Und er führte mich ringsherum an ihnen vorüber; und siehe, es waren sehr viele auf der Fläche des Tales, und siehe, sie waren sehr verdorrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Und er sprach zu mir: Menschensohn, werden diese Gebeine lebendig werden? Und ich sprach: Herr, Jehova, du weißt es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Da sprach er zu mir: Weissage über diese Gebeine und sprich zu ihnen: Ihr verdorrten Gebeine, höret das Wort Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'So spricht der Herr, Jehova, zu diesen Gebeinen: Siehe, ich bringe Odem in euch, daß ihr lebendig werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Und ich werde Sehnen über euch legen und Fleisch über euch wachsen lassen und euch mit Haut überziehen, und ich werde Odem in euch legen, daß ihr lebendig werdet. Und ihr werdet wissen, daß ich Jehova bin. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Und ich weissagte, wie mir geboten war. Da entstand ein Geräusch, als ich weissagte, und siehe, ein Getöse: und die Gebeine rückten zusammen, Gebein an Gebein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Und ich sah, und siehe, es kamen Sehnen über sie, und Fleisch wuchs, und Haut zog sich darüber obenher; aber es war kein Odem in ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Und er sprach zu mir: Weissage dem Odem, weissage, Menschensohn, und sprich zu dem Odem: So spricht der Herr, Jehova: Komm von den vier Winden her, du Odem, und hauche diese Getöteten an, daß sie lebendig werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Und ich weissagte, wie er mir geboten hatte; und der Odem kam in sie, und sie wurden lebendig und standen auf ihren Füßen, ein überaus großes Heer. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Und er sprach zu mir: Menschensohn, diese Gebeine sind das ganze Haus Israel. Siehe, sie sprechen: Unsere Gebeine sind verdorrt, und unsere Hoffnung ist verloren; wir sind dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Darum weissage und sprich zu ihnen: So spricht der Herr, Jehova: Siehe, ich werde eure Gräber öffnen und euch aus euren Gräbern heraufkommen lassen, mein Volk, und werde euch in das Land Israel bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Und ihr werdet wissen, daß ich Jehova bin, wenn ich eure Gräber öffne und euch aus euren Gräbern heraufkommen lasse, mein Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Und ich werde meinen Geist in euch geben, daß ihr lebet, und werde euch in euer Land setzen. Und ihr werdet wissen, daß ich, Jehova, geredet und es getan habe, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Und du, Menschensohn, nimm dir ein Holz und schreibe darauf: Für Juda und für die Kinder Israel, seine Genossen. Und nimm ein anderes Holz und schreibe darauf: Für Joseph, Holz Ephraims und des ganzen Hauses Israel, seiner Genossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Und bringe sie zusammen, eines zum anderen, dir zu einem Holze, so daß sie geeint seien in deiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Und wenn die Kinder deines Volkes zu dir sprechen und sagen: Willst du uns nicht kundtun, was diese dir bedeuten sollen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'so rede zu ihnen: So spricht der Herr, Jehova: Siehe, ich werde das Holz Josephs nehmen, welches in der Hand Ephraims ist, und die Stämme Israels, seine Genossen; und ich werde sie dazu tun, zu dem Holze Judas, und werde sie zu einem Holze machen, so daß sie eins seien in meiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Und die Hölzer, auf welche du geschrieben hast, sollen in deiner Hand sein vor ihren Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Und rede zu ihnen: So spricht der Herr, Jehova: Siehe, ich werde die Kinder Israel aus den Nationen herausholen, wohin sie gezogen sind, und ich werde sie von ringsumher sammeln und sie in ihr Land bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Und ich werde sie zu einer Nation machen im Lande, auf den Bergen Israels, und sie werden allesamt einen König zum König haben; und sie sollen nicht mehr zu zwei Nationen werden, und sollen sich fortan nicht mehr in zwei Königreiche teilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Und sie werden sich nicht mehr verunreinigen durch ihre Götzen und durch ihre Scheusale und durch alle ihre Übertretungen; und ich werde sie retten aus allen ihren Wohnsitzen, in welchen sie gesündigt haben, und werde sie reinigen; und sie werden mein Volk, und ich werde ihr Gott sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Und mein Knecht David wird König über sie sein, und sie werden allesamt einen Hirten haben; und sie werden in meinen Rechten wandeln, und meine Satzungen bewahren und sie tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Und sie werden wohnen in dem Lande, das ich meinem Knechte Jakob gegeben, worin eure Väter gewohnt haben; und sie werden darin wohnen, sie und ihre Kinder und ihre Kindeskinder, bis in Ewigkeit; und mein Knecht David wird ihr Fürst sein ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Und ich werde einen Bund des Friedens mit ihnen machen, ein ewiger Bund wird es mit ihnen sein; und ich werde sie einsetzen und sie vermehren, und werde mein Heiligtum in ihre Mitte setzen ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Und meine Wohnung wird über ihnen sein; und ich werde ihr Gott, und sie werden mein Volk sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Und die Nationen werden wissen, daß ich Jehova bin, der Israel heiligt, wenn mein Heiligtum in ihrer Mitte sein wird ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Menschensohn, richte dein Angesicht gegen Gog vom Lande Magog, den Fürsten von Rosch, Mesech und Tubal, und weissage wider ihn und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'So spricht der Herr, Jehova: Siehe, ich will an dich, Gog, Fürst von Rosch, Mesech und Tubal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Und ich werde dich herumlenken und Haken in deine Kinnbacken legen; und ich werde dich herausführen und dein ganzes Heer, Rosse und Reiter, allesamt prächtig gekleidet, eine große Schar mit Schild und Tartsche, welche Schwerter führen allesamt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Perser, Äthiopier und Put mit ihnen, allesamt mit Schild und Helm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomer und alle seine Haufen, das Haus Togarma im äußersten Norden und alle seine Haufen; viele Völker mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Rüste dich und rüste dir zu, du und alle deine Scharen, die sich zu dir versammelt haben, und sei ihr Anführer!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Nach vielen Tagen sollst du heimgesucht werden: Am Ende der Jahre sollst du in das Land kommen, das vom Schwerte wiederhergestellt, das aus vielen Völkern gesammelt ist, auf die Berge Israels, welche beständig verödet waren; und es ist herausgeführt aus den Völkern, und sie wohnen in Sicherheit allesamt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Und du sollst heraufziehen, wie ein Sturm herankommen, sollst wie eine Wolke sein, um das Land zu bedecken, du und alle deine Haufen und viele Völker mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'So spricht der Herr, Jehova: Und es wird geschehen an jenem Tage, da werden Dinge in deinem Herzen aufsteigen, und du wirst einen bösen Anschlag ersinnen und sprechen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'Ich will hinaufziehen in das Land der offenen Städte, will über die kommen, welche in Ruhe sind, in Sicherheit wohnen, die allesamt ohne Mauern wohnen und Riegel und Tore nicht haben:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'um Raub zu rauben und Beute zu erbeuten, um deine Hand zu kehren gegen die wiederbewohnten Trümmer und gegen ein Volk, das aus den Nationen gesammelt ist, welches Hab und Gut erworben hat, welches den Mittelpunkt der Erde bewohnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Scheba und Dedan und die Kaufleute von Tarsis und alle ihre jungen Löwen werden zu dir sagen: Kommst du, um Raub zu rauben? Hast du deine Scharen versammelt, um Beute zu erbeuten, um Silber und Gold wegzuführen, Hab und Gut wegzunehmen, um einen großen Raub zu rauben? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Darum, weissage, Menschensohn, und sprich zu Gog: So spricht der Herr, Jehova: Wirst du es an jenem Tage nicht wissen, wenn mein Volk Israel in Sicherheit wohnt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Und du wirst von deinem Orte kommen, vom äußersten Norden her, du und viele Völker mit dir, auf Rossen reitend allesamt, eine große Schar und ein zahlreiches Heer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Und du wirst wider mein Volk Israel heraufziehen wie eine Wolke, um das Land zu bedecken. Am Ende der Tage wird es geschehen, daß ich dich heranbringen werde wider mein Land, auf daß die Nationen mich kennen, wenn ich mich an dir, Gog, vor ihren Augen heilige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'So spricht der Herr, Jehova: Bist du der, von welchem ich in vergangenen Tagen geredet habe durch meine Knechte, die Propheten Israels, welche in jenen Tagen Jahre lang weissagten, daß ich dich wider sie heranbringen würde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Und es wird geschehen an selbigem Tage, an dem Tage, wenn Gog in das Land Israel kommt, spricht der Herr, Jehova, da wird mein Grimm in meiner Nase aufsteigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Und in meinem Eifer, im Feuer meines Zornes habe ich geredet: Wahrlich, an selbigem Tage wird ein großes Beben sein im Lande Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Und es werden vor mir beben die Fische des Meeres und die Vögel des Himmels und die Tiere des Feldes und alles Gewürm, das sich auf dem Erdboden regt, und alle Menschen, die auf der Fläche des Erdbodens sind; und die Berge werden niedergerissen werden, und die steilen Höhen werden einstürzen, und jede Mauer wird zu Boden fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Und ich werde nach allen meinen Bergen hin das Schwert über ihn herbeirufen, spricht der Herr, Jehova; das Schwert des einen wird wider den anderen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Und ich werde Gericht an ihm üben durch die Pest und durch Blut; und einen überschwemmenden Regen und Hagelsteine, Feuer und Schwefel werde ich regnen lassen auf ihn und auf seine Haufen und auf die vielen Völker, die mit ihm sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Und ich werde mich groß und heilig erweisen, und werde mich kundtun vor den Augen vieler Nationen. Und sie werden wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Und du, Menschensohn, weissage wider Gog und sprich: So spricht der Herr, Jehova: Siehe, ich will an dich, Gog, Fürst von Rosch, Mesech und Tubal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Und ich werde dich herumlenken und herbeiführen, und dich heraufziehen lassen vom äußersten Norden her, und dich auf die Berge Israels bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Und ich werde dir den Bogen aus deiner linken Hand schlagen und deine Pfeile aus deiner rechten Hand werfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Auf den Bergen Israels wirst du fallen, du und alle deine Haufen und die Völker, die mit dir sind; den Raubvögeln allerlei Gefieders und den Tieren des Feldes habe ich dich zur Speise gegeben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'auf dem freien Felde sollst du fallen. Denn ich habe geredet, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Und ich werde Feuer senden unter Magog und unter die, welche auf den Inseln sicher wohnen. Und sie werden wissen, daß ich Jehova bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Und ich werde meinen heiligen Namen kundtun inmitten meines Volkes Israel, und werde meinen heiligen Namen nicht mehr entweihen lassen. Und die Nationen werden wissen, daß ich Jehova bin, der Heilige in Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Siehe, es kommt und wird geschehen, spricht der Herr, Jehova. Das ist der Tag, von welchem ich geredet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Und die Bewohner der Städte Israels werden hinausgehen, und werden Feuer machen und heizen mit Waffen und Tartschen und Schilden, mit Bogen und Pfeilen und mit Handstäben und Lanzen; und sie werden Feuer damit machen sieben Jahre lang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Und sie werden kein Holz vom Felde holen noch aus den Wäldern hauen, sondern werden Feuer machen mit den Waffen. Und sie werden ihre Räuber berauben und ihre Plünderer plündern, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Und es wird geschehen an jenem Tage, da werde ich Gog eine Grabstätte geben in Israel, das Tal der Wanderer auf der Ostseite des Meeres; und es wird den Wanderern den Weg versperren. Und daselbst werden sie Gog und seine ganze Menge begraben, und sie werden es nennen: Tal der Menge Gogs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Und das Haus Israel wird sie begraben, um das Land zu reinigen, sieben Monate lang;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'und das ganze Volk des Landes wird sie begraben, und es wird ihnen zum Ruhme sein an dem Tage, da ich mich verherrlichen werde, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Und sie werden Männer aussondern, die beständig im Lande umherziehen, und solche, welche mit den Umherziehenden die auf der Fläche des Landes Übriggebliebenen begraben, um es zu reinigen; nach Verlauf von sieben Monaten werden sie es durchsuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Und die Umherziehenden werden im Lande umherziehen; und wenn einer ein Menschengebein sieht, so wird er ein Mal daneben errichten, bis die Totengräber es im Tale der Menge Gogs begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Und auch der Name der Stadt soll Hamona sein. Und so werden sie das Land reinigen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Und du, Menschensohn, so spricht der Herr, Jehova: Sprich zu dem Gevögel allerlei Gefieders und zu allen Tieren des Feldes: Versammelt euch und kommet, sammelt euch von allen Seiten her zu meinem Schlachtopfer, das ich für euch schlachte, einem großen Schlachtopfer auf den Bergen Israels, und fresset Fleisch und trinket Blut!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Fleisch von Helden sollt ihr fressen, und Blut von Fürsten der Erde sollt ihr trinken: Widder, Fettschafe und Böcke und Farren, in Basan gemästet allesamt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Und Fett sollt ihr fressen bis zur Sättigung und Blut trinken bis zur Trunkenheit von meinem Schlachtopfer, das ich für euch geschlachtet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Und ihr sollt euch sättigen an meinem Tische von Rossen und Reitern, von Helden und allerlei Kriegsleuten, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Und ich werde meine Herrlichkeit unter den Nationen erweisen; und alle Nationen sollen mein Gericht sehen, welches ich gehalten, und meine Hand, die ich an sie gelegt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Und von jenem Tage an und hinfort wird das Haus Israel wissen, daß ich, Jehova, ihr Gott bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Und die Nationen werden wissen, daß das Haus Israel um seiner Ungerechtigkeit willen weggeführt wurde, weil sie treulos gegen mich gewesen sind, und ich mein Angesicht vor ihnen verborgen und sie in die Hand ihrer Bedränger gegeben habe, so daß sie allesamt durch das Schwert gefallen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Nach ihrer Unreinigkeit und nach ihren Übertretungen habe ich mit ihnen gehandelt, und habe mein Angesicht vor ihnen verborgen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Darum, so spricht der Herr, Jehova: Nun werde ich die Gefangenschaft Jakobs wenden und mich des ganzen Hauses Israel erbarmen, und werde eifern für meinen heiligen Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Und sie werden ihre Schmach tragen und alle ihre Treulosigkeit, mit welcher sie treulos gegen mich gehandelt haben, wenn sie in ihrem Lande sicher wohnen und niemand sie aufschreckt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'wenn ich sie aus den Völkern zurückgebracht und sie aus den Ländern ihrer Feinde gesammelt, und ich mich an ihnen geheiligt habe vor den Augen der vielen Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Und sie werden wissen, daß ich, Jehova, ihr Gott bin, indem ich sie zu den Nationen weggeführt habe und sie wieder in ihr Land sammle und keinen mehr von ihnen dort übriglasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Und ich werde mein Angesicht nicht mehr vor ihnen verbergen, wenn ich meinen Geist über das Haus Israel ausgegossen habe, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Im fünfundzwanzigsten Jahre unserer Wegführung, im Anfang des Jahres, am Zehnten des Monats, im vierzehnten Jahre, nachdem die Stadt geschlagen war, an diesem selbigen Tage kam die Hand Jehovas über mich, und er brachte mich dorthin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'In Gesichten Gottes brachte er mich in das Land Israel, und er ließ mich nieder auf einen sehr hohen Berg; und auf demselben, gegen Süden, war es wie der Bau einer Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Und er brachte mich dorthin; und siehe da, ein Mann, dessen Aussehen war wie das Aussehen von Erz; und in seiner Hand war eine leinene Schnur und eine Meßrute; und er stand im Tore.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Und der Mann redete zu mir: Menschensohn, sieh mit deinen Augen und höre mit deinen Ohren, und richte dein Herz auf alles, was ich dir zeigen werde; denn damit es dir gezeigt werde, bist du hierher gebracht worden. Berichte dem Hause Israel alles, was du siehst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Und siehe, eine Mauer war außerhalb des Hauses ringsherum; und in der Hand des Mannes war eine Meßrute von sechs Ellen, jede von einer Elle und einer Handbreite. Und er maß die Breite des Baues: eine Rute, und die Höhe: eine Rute. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Und er ging zu dem Tore, das gegen Osten gerichtet war, und stieg dessen Stufen hinauf. Und er maß die Schwelle des Tores: eine Rute breit, und zwar die erste Schwelle eine Rute breit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'und jedes Wachtzimmer: eine Rute lang und eine Rute breit, und zwischen den Wachtzimmern fünf Ellen; und die Torschwelle neben der Torhalle nach dem Hause hin: eine Rute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Und er maß die Torhalle nach dem Hause hin: eine Rute;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'und er maß die Torhalle: acht Ellen, und ihre Pfeiler: zwei Ellen dick, und die Torhalle war nach dem Hause hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Und der Wachtzimmer des Tores gegen Osten waren drei auf dieser und drei auf jener Seite; ein Maß hatten alle drei, und ein Maß die Pfeiler auf dieser und auf jener Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Und er maß die Breite der Toröffnung: zehn Ellen, und die Länge des Tores: dreizehn Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Und eine Grenzwehr war vor den Wachtzimmern, von einer Elle auf dieser Seite; und eine Elle Grenzwehr war auf jener Seite. Und jedes Wachtzimmer war sechs Ellen auf dieser und sechs Ellen auf jener Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Und er maß das Tor vom Dache eines Wachtzimmers bis zum Dache des anderen: fünfundzwanzig Ellen Breite, Tür gegen Tür.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Und er bestimmte die Pfeiler zu sechzig Ellen Höhe. Und an die Pfeiler stieß der Vorhof rings um das Torgebäude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Und von der Vorderseite des Eingangstores bis zur Vorderseite der Halle des inneren Tores waren fünfzig Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Und vergitterte Fenster waren an den Wachtzimmern, und zwar an ihren Pfeilern, nach dem Inneren des Torgebäudes zu, ringsherum, und ebenso an den Wandvorsprüngen; und so waren Fenster ringsherum nach innen zu; und an den Pfeilern waren Palmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Und er brachte mich in den äußeren Vorhof. Und siehe, da waren Zellen und ein Steinpflaster ringsum am Vorhof gemacht; dreißig Zellen waren auf dem Steinpflaster.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Und das Steinpflaster war zur Seite der Tore, entsprechend der Länge der Tore, nämlich das untere Steinpflaster.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Und er maß die Breite von der Vorderseite des Tores des unteren Vorhofs bis vor den inneren Vorhof, von außen, hundert Ellen; so war es an der Ostseite und an der Nordseite. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Und das Tor, welches gegen Norden gerichtet war, am äußeren Vorhof: er maß seine Länge und seine Breite;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'und seine Wachtzimmer, drei auf dieser und drei auf jener Seite; und seine Pfeiler und seine Wandvorsprünge. Es war nach dem Maße des ersten Tores, fünfzig Ellen seine Länge und fünfundzwanzig Ellen die Breite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Und seine Fenster und seine Wandvorsprünge und seine Palmen waren nach dem Maße des Tores, das gegen Osten gerichtet war; und auf sieben Stufen stieg man hinauf, und seine Wandvorsprünge waren vor ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Und ein Tor zum inneren Vorhof war dem Tore nach Norden und nach Osten gegenüber; und er maß von Tor zu Tor hundert Ellen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Und er führte mich gegen Süden. Und siehe, da war ein Tor gegen Süden; und er maß seine Pfeiler und seine Wandvorsprünge nach jenen Maßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Und Fenster waren an ihm und an seinen Wandvorsprüngen ringsherum, gleich jenen Fenstern. Die Länge war fünfzig Ellen und die Breite fünfundzwanzig Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Und sieben Stufen bildeten seine Stiege, und seine Wandvorsprünge waren vor ihnen; und es hatte Palmen an seinen Pfeilern, eine auf dieser und eine auf jener Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Und ein Tor zum inneren Vorhof war gegen Süden; und er maß vom Tore zu dem Tore gegen Süden, hundert Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Und er brachte mich durch das Südtor in den inneren Vorhof. Und er maß das Südtor nach jenen Maßen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'und seine Wachtzimmer und seine Pfeiler und seine Wandvorsprünge nach jenen Maßen. Und Fenster waren an ihm und an seinen Wandvorsprüngen ringsherum. Die Länge war fünfzig Ellen und die Breite fünfundzwanzig Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Und Wandvorsprünge waren ringsherum, die Länge fünfundzwanzig Ellen und die Breite fünf Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Und seine Wandvorsprünge waren gegen den äußeren Vorhof hin; und Palmen waren an seinen Pfeilern; und acht Stufen bildeten seine Stiege. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Und er brachte mich in den inneren Vorhof gegen Osten. Und er maß das Tor nach jenen Maßen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'und seine Wachtzimmer und seine Pfeiler und seine Wandvorsprünge nach jenen Maßen. Und Fenster waren an ihm und an seinen Wandvorsprüngen ringsherum. Die Länge war fünfzig Ellen und die Breite fünfundzwanzig Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Und seine Wandvorsprünge waren gegen den äußeren Vorhof hin; und Palmen waren an seinen Pfeilern auf dieser und auf jener Seite; und acht Stufen bildeten seine Stiege. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Und er brachte mich zu dem Nordtore. Und er maß es nach jenen Maßen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'seine Wachtzimmer, seine Pfeiler und seine Wandvorsprünge. Und Fenster waren an ihm ringsherum. Die Länge war fünfzig Ellen und die Breite fünfundzwanzig Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Und seine Pfeiler waren nach dem äußeren Vorhof zu; und Palmen waren an seinen Pfeilern auf dieser und auf jener Seite; und acht Stufen bildeten seine Stiege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Und eine Zelle und ihr Eingang war an den Pfeilern der Tore; daselbst spülte man das Brandopfer ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Und in der Torhalle waren zwei Tische auf dieser und zwei Tische auf jener Seite, um auf dieselben das geschlachtete Brandopfer und Sündopfer und Schuldopfer zu legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Und draußen, an der dem zum Toreingang hinaufgehenden nördlich liegenden Seite, waren zwei Tische; und an der anderen Seite der Torhalle zwei Tische:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'vier Tische auf dieser und vier Tische auf jener Seite, an der Seite des Tores: acht Tische, auf welche man das geschlachtete Fleisch legte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Und bei der Stiege waren vier Tische aus behauenen Steinen, anderthalb Ellen lang und anderthalb Ellen breit und eine Elle hoch; auf diese legte man die Geräte, womit man das Brandopfer und das Schlachtopfer schlachtete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Und die Doppelpflöcke, eine Handbreit lang, waren ringsherum am Torhause befestigt; und auf die Tische kam das Opferfleisch. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Und außerhalb des inneren Tores waren zwei Zellen im inneren Vorhof: eine an der Seite des Nordtores, und ihre Vorderseite gegen Süden; eine an der Seite des Südtores in der Richtung gegen Norden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Und er sprach zu mir: Diese Zelle, deren Vorderseite gegen Süden liegt, ist für die Priester, welche der Hut des Hauses warten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Und die Zelle, deren Vorderseite gegen Norden liegt, ist für die Priester, welche der Hut des Altars warten. Das sind die Söhne Zadoks, welche aus den Söhnen Levis Jehova nahen, um ihm zu dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Und er maß den Vorhof: die Länge hundert Ellen und die Breite hundert Ellen ins Geviert. Und der Altar war vor dem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Und er brachte mich zur Halle des Hauses. Und er maß den Pfeiler der Halle: fünf Ellen auf dieser und fünf Ellen auf jener Seite; und die Breite des Tores: drei Ellen auf dieser und drei Ellen auf jener Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Die Länge der Halle war zwanzig Ellen und die Breite elf Ellen, und zwar an den Stufen, auf welchen man zu ihr hinaufstieg. Und Säulen waren an den Pfeilern, eine auf dieser und eine auf jener Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Und er brachte mich in den Tempel. Und er maß die Pfeiler: sechs Ellen Breite auf dieser und sechs Ellen Breite auf jener Seite, die Breite des Zeltes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Und die Breite der Tür war zehn Ellen, und die Türschultern fünf Ellen auf dieser und fünf Ellen auf jener Seite. Und er maß seine Länge: vierzig Ellen, und die Breite: zwanzig Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Und er ging nach innen. Und er maß den Türpfeiler: zwei Ellen; und die Tür: sechs Ellen Höhe, und die Breite der Tür: sieben Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Und er maß seine Länge: zwanzig Ellen, und die Breite: zwanzig Ellen gegen den Tempel hin; und er sprach zu mir: Dies ist das Allerheiligste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Und er maß die Wand des Hauses: sechs Ellen, und die Breite der Seitenzimmer: vier Ellen, rings um das Haus herum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Und die Seitenzimmer waren Zimmer über Zimmer, drei, und zwar dreißigmal; und sie gingen in die Wand, welche das Haus ringsherum für die Seitenzimmer hatte, damit sie festgehalten würden; doch wurden sie nicht in der Wand des Hauses festgehalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Und die Erweiterung und Umgebung nahm nach oben hin mehr und mehr zu, hinsichtlich der Seitenzimmer; denn die Umgebung des Hauses vergrößerte sich nach oben hin mehr und mehr rings um das Haus, wodurch Breite am Hause nach oben hin entstand. Und so stieg das untere Stockwerk zum oberen auf nach Verhältnis des mittleren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Und ich sah am Hause eine Erhöhung ringsherum: die Seitenzimmer hatten nämlich eine Grundlage von einer vollen Rute, sechs Ellen nach der Verbindung hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Die Breite der Wand, welche die Seitenzimmer nach außen hatten, war fünf Ellen; und auch was freigelassen war am Seitenzimmergebäude des Hauses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Und zwischen den Zellen war eine Breite von zwanzig Ellen, rings um das Haus, ringsherum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Und die Tür der Seitenzimmer ging nach dem freigelassenen Raume, eine Tür gegen Norden und eine Tür gegen Süden. Und die Breite des freigelassenen Raumes war fünf Ellen ringsherum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Und das Bauwerk an der Vorderseite des abgesonderten Platzes, an der gegen Westen gerichteten Seite, war siebzig Ellen breit, und die Mauer des Bauwerks fünf Ellen breit ringsherum, und seine Länge neunzig Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Und er maß das Haus: die Länge hundert Ellen; und den abgesonderten Platz und das Bauwerk und seine Mauern: die Länge hundert Ellen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'und die Breite der Vorderseite des Hauses und des abgesonderten Platzes gegen Osten: hundert Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Und so maß er die Länge des an der Vorderseite des abgesonderten Platzes befindlichen Bauwerks, welches sich bis zu seiner Hinterseite hin erstreckte; und seine Galerien auf dieser und auf jener Seite: hundert Ellen; und den inneren Tempel und die Hallen des Vorhofs. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Die Schwellen und die vergitterten Fenster und die Galerien rings um diese drei Gebäude, den Schwellen gegenüber war getäfeltes Holz ringsherum, und vom Boden bis an die Fenster (und die Fenster waren verdeckt) -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'der Raum über den Türen und das ganze Haus, sowohl inwendig als auswendig, und der Raum an allen Wänden ringsherum, innen und außen: alles hatte seine Maße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Und Cherubim und Palmen waren gemacht, und zwar eine Palme zwischen Cherub und Cherub. Und der Cherub hatte zwei Angesichter:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'eines Menschen Angesicht gegen die Palme auf dieser, und eines Löwen Angesicht gegen die Palme auf jener Seite; so war es gemacht am ganzen Hause ringsherum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Vom Boden bis hinauf über die Tür waren die Cherubim und die Palmen gemacht, und zwar an der Wand des Tempels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Der Tempel hatte viereckige Türpfosten; und die auf der Vorderseite des Heiligtums hatten die gleiche Gestalt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Der Altar war von Holz, drei Ellen hoch, und seine Länge zwei Ellen; und er hatte seine Ecken; und sein Gestell und seine Wände waren von Holz. Und er sprach zu mir: Das ist der Tisch, der vor Jehova steht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Und der Tempel und das Heiligtum hatten zwei Flügeltüren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Und die Türflügel hatten zwei Flügelblätter, zwei drehbare Flügelblätter, zwei an dem einen Türflügel und zwei Flügelblätter an dem anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Und an ihnen, an den Flügeltüren des Tempels, waren Cherubim und Palmen gemacht, wie sie an den Wänden gemacht waren. Und ein hölzernes Dachgesims war an der Vorderseite der Halle draußen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Und vergitterte Fenster und Palmen waren auf dieser und auf jener Seite, an den Seitenwänden der Halle und an den Seitenzimmern des Hauses und den Dachgesimsen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Und er führte mich hinaus in den äußeren Vorhof, des Weges gegen Norden. Und er brachte mich zu den Zellen, welche dem abgesonderten Platze gegenüber und dem Bauwerk nach Norden gegenüber waren,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'vor die Langseite hin von hundert Ellen, mit dem Eingang gegen Norden, und die Breite fünfzig Ellen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'gegenüber den zwanzig Ellen des inneren Vorhofs und gegenüber dem Pflaster des äußeren Vorhofs, Galerie gegen Galerie war im dritten Stockwerk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Und vor den Zellen war ein Gang von zehn Ellen Breite: nach dem inneren Vorhof hin ein Weg von hundert Ellen. Und ihre Türen waren gegen Norden gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Und weil die Galerien Raum von ihnen wegnahmen, waren die oberen Zellen schmäler als die unteren und die mittleren des Baues.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Denn sie waren dreistöckig, hatten aber keine Säulen wie die Säulen der Vorhöfe; darum waren sie schmäler am Boden als die unteren und die mittleren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Und eine Mauer außerhalb, gleichlaufend den Zellen, nach dem äußeren Vorhof hin, war an der Vorderseite der Zellen; ihre Länge war fünfzig Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Denn die Länge der Zellen am äußeren Vorhof war fünfzig Ellen; und siehe, vor dem Tempel war sie hundert Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Und unterhalb dieser Zellen war der Zugang von Osten her, wenn man zu ihnen ging, vom äußeren Vorhof her. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'An der Breite der Mauer des Vorhofs gegen Süden, vor dem abgesonderten Platze und vor dem Bauwerk, waren Zellen-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'und ein Weg vor ihnen, von gleicher Gestalt wie die Zellen, die gegen Norden waren, wie nach ihrer Länge so nach ihrer Breite, und nach allen ihren Ausgängen wie nach ihren Einrichtungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Und wie ihre Eingänge, so waren auch die Eingänge der Zellen, welche gegen Süden waren: ein Eingang am Anfang des Weges, des Weges, welcher gegenüber der entsprechenden Mauer war gegen Osten, wenn man zu ihnen kam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Und er sprach zu mir: Die Zellen im Norden und die Zellen im Süden, welche vor dem abgesonderten Platze sind, sind die heiligen Zellen, wo die Priester, welche Jehova nahen, die hochheiligen Dinge essen sollen. Dahin sollen sie die hochheiligen Dinge legen, sowohl das Speisopfer als auch das Sündopfer und das Schuldopfer; denn der Ort ist heilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Wenn die Priester hineingehen, so sollen sie nicht aus dem Heiligtum in den äußeren Vorhof hinausgehen, sondern sollen dort ihre Kleider niederlegen, in welchen sie den Dienst verrichten; denn sie sind heilig; sie sollen andere Kleider anziehen und sich dem nahen, was für das Volk ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Und als er die Maße des inneren Hauses vollendet hatte, führte er mich hinaus des Weges zum Tore, das gegen Osten gerichtet war; und er maß es ringsherum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Er maß die Ostseite mit der Meßrute, fünfhundert Ruten mit der Meßrute ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Er maß die Nordseite, fünfhundert Ruten mit der Meßrute ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Die Südseite maß er, fünfhundert Ruten mit der Meßrute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Er wandte sich um nach der Westseite und maß fünfhundert Ruten mit der Meßrute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Er maß es nach den vier Seiten. Es hatte eine Mauer ringsherum: die Länge war fünfhundert und die Breite fünfhundert, um zwischen dem Heiligen und dem Unheiligen zu scheiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Und er führte mich zum Tore, dem Tore, das gegen Osten sah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Und siehe, die Herrlichkeit des Gottes Israels kam von Osten her; und ihr Rauschen war wie das Rauschen großer Wasser, und die Erde leuchtete von seiner Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Und das Ansehen des Gesichtes, das ich sah, war wie das Gesicht, welches ich gesehen hatte, als ich kam, um die Stadt zu verderben; und es waren Gesichte wie das Gesicht, welches ich am Flusse Kebar gesehen hatte. Und ich fiel nieder auf mein Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Und die Herrlichkeit Jehovas kam in das Haus, den Weg des Tores, welches gegen Osten gerichtet war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Und der Geist hob mich empor und brachte mich in den inneren Vorhof; und siehe, die Herrlichkeit Jehovas erfüllte das Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Und ich hörte einen, der aus dem Hause zu mir redete; und ein Mann stand neben mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Und er sprach zu mir: Menschensohn, dies ist der Ort meines Thrones und der Ort meiner Fußsohlen, wo ich inmitten der Kinder Israel wohnen werde ewiglich. Und das Haus Israel wird meinen heiligen Namen nicht mehr verunreinigen, sie und ihre Könige, durch ihre Hurerei und durch die Leichname ihrer Könige und ihre Höhen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'indem sie ihre Schwelle an meine Schwelle und ihre Türpfosten neben meine Türpfosten setzten, daß nur die Wand zwischen mir und ihnen war; und meinen heiligen Namen verunreinigten durch ihre Greuel, die sie verübten, so daß ich sie in meinem Zorne vernichtet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Nunmehr werden sie ihre Hurerei und die Leichname ihrer Könige von mir entfernen, und ich werde in ihrer Mitte wohnen ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Du, Menschensohn, berichte dem Hause Israel über dieses Haus, damit sie sich ihrer Missetaten schämen und den Bau messen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Und wenn sie sich alles dessen schämen, was sie getan haben, so zeige ihnen die Form des Hauses und seine Einrichtung, und seine Ausgänge und seine Eingänge, und alle seine Formen und alle seine Satzungen, und alle seine Formen und alle seine Gesetze; und schreibe es vor ihren Augen auf, damit sie seine ganze Form und alle seine Satzungen behalten und sie tun. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Dies ist das Gesetz des Hauses: Auf dem Gipfel des Berges soll sein ganzes Gebiet ringsherum hochheilig sein; siehe, das ist das Gesetz des Hauses. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Und dies sind die Maße des Altars nach Ellen, die Elle eine Elle und eine Handbreite: ein Untersatz, eine Elle hoch und eine Elle breit; und sein Gesims an seinem Rande ringsum: eine Spanne; und das ist der Sockel des Altars.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Und von dem Untersatz am Boden bis zur unteren Umwandung: zwei Ellen Höhe und eine Elle Breite; und von der kleineren Umwandung bis zur größeren Umwandung: vier Ellen Höhe und eine Elle Breite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Und der Gottesberg: vier Ellen Höhe; und von dem Gottesherde aufwärts die vier Hörner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Und der Gottesherd: zwölf Ellen Länge bei zwölf Ellen Breite, quadratförmig, an seinen vier Seiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Und die untere Umwandung: vierzehn Ellen Länge bei vierzehn Ellen Breite, an ihren vier Seiten; und das Gesims rings um dieselbe: eine halbe Elle, und ihr Untersatz eine Elle ringsum. Und seine Stufen waren gegen Osten gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Und er sprach zu mir: Menschensohn, so spricht der Herr, Jehova: Dies sind die Satzungen des Altars, an dem Tage, da er gemacht wird, um Brandopfer darauf zu opfern und Blut darauf zu sprengen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Und du sollst den Priestern, den Leviten, welche vom Samen Zadoks sind, die mir nahen, spricht der Herr, Jehova, um mir zu dienen, einen jungen Farren geben zum Sündopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Und du sollst von seinem Blute nehmen und es an seine vier Hörner tun und an die vier Ecken der Umwandung und an das Gesims ringsum; und so sollst du ihn entsündigen und Sühnung für ihn tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Und du sollst den Farren des Sündopfers nehmen, und man soll ihn an dem bestimmten Orte des Hauses, außerhalb des Heiligtums, verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Und am zweiten Tage sollst du einen Ziegenbock ohne Fehl zum Sündopfer darbringen; und man soll den Altar entsündigen, so wie man ihn mit dem Farren entsündigt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Wenn du das Entsündigen vollendet hast, sollst du einen jungen Farren ohne Fehl und einen Widder ohne Fehl vom Kleinvieh darbringen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'du sollst sie vor Jehova darbringen, und die Priester sollen Salz auf sie streuen und sie dem Jehova als Brandopfer opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Sieben Tage lang sollst du täglich einen Bock als Sündopfer opfern; und einen jungen Farren und einen Widder vom Kleinvieh, ohne Fehl, soll man opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Sieben Tage lang soll man Sühnung tun für den Altar und ihn reinigen und ihn einweihen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Und wenn man die Tage vollendet hat, so soll es am achten Tage und fernerhin geschehen, daß die Priester eure Brandopfer und eure Friedensopfer auf dem Altar opfern; und ich werde euch wohlgefällig annehmen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Und er führte mich zurück des Weges zum äußeren Tore des Heiligtums, welches gegen Osten sah; und es war verschlossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Und Jehova sprach zu mir: Dieses Tor soll verschlossen sein; es soll nicht geöffnet werden, und niemand soll durch dasselbe eingehen; weil Jehova, der Gott Israels, durch dasselbe eingezogen ist, so soll es verschlossen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Was den Fürsten betrifft, er, der Fürst, soll darin sitzen, um zu essen vor Jehova; auf dem Wege der Torhalle soll er hineingehen, und auf demselben Wege soll er hinausgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Und er brachte mich auf dem Wege des Nordtores vor das Haus; und ich sah: und siehe, die Herrlichkeit Jehovas erfüllte das Haus Jehovas; und ich fiel nieder auf mein Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Und Jehova sprach zu mir: Menschensohn, richte dein Herz darauf, und sieh mit deinen Augen und höre mit deinen Ohren alles, was ich mit dir rede betreffs aller Satzungen des Hauses Jehovas und betreffs aller seiner Gesetze; und richte dein Herz auf den Eingang des Hauses samt allen Ausgängen des Heiligtums.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Und sprich zu den Widerspenstigen, zu dem Hause Israel: So spricht der Herr, Jehova: Laßt es genug sein an allen euren Greueln, Haus Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Indem ihr Söhne der Fremde, unbeschnitten am Herzen und unbeschnitten am Fleische, hineinführtet, um in meinem Heiligtum zu sein, mein Haus zu entweihen, wenn ihr meine Speise, Fett und Blut, darbrachtet, so daß sie meinen Bund brachen zu allen euren Greueln hinzu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Und ihr habt der Hut meiner heiligen Dinge nicht gewartet, sondern habt sie euch zu Wärtern meiner Hut gesetzt in meinem Heiligtum. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'So spricht der Herr, Jehova: Kein Sohn der Fremde, unbeschnitten am Herzen und unbeschnitten am Fleische, von allen Söhnen der Fremde, welche inmitten der Kinder Israel sind, soll in mein Heiligtum kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Wahrlich, die Leviten, die sich von mir entfernt haben bei der Verirrung Israels, welches von mir abgeirrt ist, seinen Götzen nach, sie sollen ihre Missetat tragen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'aber sie sollen in meinem Heiligtum Diener sein, als Wachen an den Toren des Hauses und als Diener des Hauses; sie sollen das Brandopfer und das Schlachtopfer für das Volk schlachten, und sie sollen vor ihnen stehen, um ihnen zu dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Weil sie ihnen vor ihren Götzen gedient haben und dem Hause Israel ein Anstoß zur Verschuldung gewesen sind, darum habe ich meine Hand wider sie erhoben, spricht der Herr, Jehova, daß sie ihre Missetat tragen sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Und sie sollen mir nicht nahen, um mir den Priesterdienst auszuüben, und um allen meinen heiligen Dingen, den hochheiligen, zu nahen; sondern sie sollen ihre Schmach und ihre Greuel tragen, die sie verübt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Und ich werde sie zu Wärtern der Hut des Hauses machen, für all seinen Dienst und für alles, was darin verrichtet wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Aber die Priester, die Leviten, die Söhne Zadoks, welche der Hut meines Heiligtums gewartet haben, als die Kinder Israel von mir abirrten, sie sollen mir nahen, um mir zu dienen, und sollen vor mir stehen, um mir das Fett und das Blut darzubringen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Sie sollen in mein Heiligtum kommen, und sie sollen meinem Tische nahen, um mir zu dienen, und sollen meiner Hut warten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Und es soll geschehen, wenn sie zu den Toren des inneren Vorhofs eingehen, sollen sie leinene Kleider anziehen; aber Wolle soll nicht auf sie kommen, wenn sie in den Toren des inneren Vorhofs und gegen das Haus hin dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Leinene Kopfbunde sollen auf ihrem Haupte sein, und leinene Beinkleider an ihren Lenden; sie sollen sich nicht in Schweiß gürten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Und wenn sie in den äußeren Vorhof hinausgehen, in den äußeren Vorhof zum Volke, so sollen sie ihre Kleider, in welchen sie gedient haben, ausziehen in die heiligen Zellen niederlegen, und sollen andere Kleider anziehen, damit sie nicht das Volk mit ihren Kleidern heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Und sie sollen weder ihr Haupt kahl scheren, noch auch das Haar frei wachsen lassen; sie sollen ihr Haupthaar schneiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Und kein Priester soll Wein trinken, wenn sie in den inneren Vorhof gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Und eine Witwe und eine Verstoßene sollen sie sich nicht zu Weibern nehmen; sondern Jungfrauen vom Samen des Hauses Israel und die Witwe, welche von einem Priester Witwe geworden ist, mögen sie nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Und sie sollen mein Volk den Unterschied lehren zwischen Heiligem und Unheiligem, und sollen ihm den Unterschied kundtun zwischen Unreinem und Reinem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Und über Streitsachen sollen sie zum Gericht dastehen, nach meinen Rechten sollen sie richten; und sie sollen meine Gesetze und meine Satzungen bei allen meinen Festen beobachten und meine Sabbathe heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Und keiner soll zu dem Leichnam eines Menschen gehen, daß er unrein werde; nur allein wegen Vater und Mutter, und wegen Sohn und Tochter, wegen eines Bruders und wegen einer Schwester, die keines Mannes gewesen ist, dürfen sie sich verunreinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Und nach seiner Reinigung soll man ihm sieben Tage zählen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'und an dem Tage, da er in das Heiligtum, in den inneren Vorhof, hineingeht, um im Heiligtum zu dienen, soll er sein Sündopfer darbringen, spricht der Herr, Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Und dies soll ihr Erbteil sein: ich bin ihr Erbteil; und ihr sollt ihnen kein Besitztum in Israel geben: ich bin ihr Besitztum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Das Speisopfer und das Sündopfer und das Schuldopfer, die sollen sie essen; und alles Verbannte in Israel soll ihnen gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Und das Erste aller Erstlinge von allem, und alle Hebopfer von allem, von allen euren Hebopfern sollen den Priestern gehören; und die Erstlinge eures Schrotmehls sollt ihr dem Priester geben, damit Segen auf deinem Hause ruhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Kein Aas noch Zerrissenes vom Gevögel und vom Vieh sollen die Priester essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Und wenn ihr das Land als Erbteil verlosen werdet, sollt ihr für Jehova ein Hebopfer heben, als Heiliges vom Lande: die Länge fünfundzwanzigtausend Ruten lang, und die Breite zwanzigtausend; dasselbe soll heilig sein in seiner ganzen Grenze ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Davon sollen zum Heiligtum gehören fünfhundert bei fünfhundert ins Geviert ringsum, und fünfzig Ellen Freiplatz dazu ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Und von jenem Maße sollst du eine Länge messen von fünfundzwanzigtausend und eine Breite von zehntausend; und darin soll das Heiligtum, das Allerheiligste, sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Dies soll ein Heiliges vom Lande sein; den Priestern, den Dienern des Heiligtums, soll es gehören, welche nahen, um Jehova zu dienen, und es soll ihnen ein Platz für Häuser sein, und ein Geheiligtes für das Heiligtum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Und fünfundzwanzigtausend Ruten in die Länge und zehntausend in die Breite soll den Leviten, den Dienern, des Hauses, gehören, ihnen zum Eigentum, als Städte zum Wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Und als Eigentum der Stadt sollt ihr fünftausend in die Breite und fünfundzwanzigtausend in die Länge geben, gleichlaufend dem heiligen Hebopfer; dem ganzen Hause Israel soll es gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Und dem Fürsten sollt ihr geben auf dieser und auf jener Seite des heiligen Hebopfers und des Eigentums der Stadt, längs des heiligen Hebopfers und längs des Eigentums der Stadt, an der Westseite westwärts und an der Ostseite ostwärts, und der Länge nach gleichlaufend einem der Stammteile, welche von der Westgrenze bis zur Ostgrenze liegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Als Land soll es ihm gehören, als Eigentum in Israel; und meine Fürsten sollen nicht mehr mein Volk bedrücken, sondern das Land dem Hause Israel nach seinen Stämmen überlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'So spricht der Herr, Jehova: Laßt es euch genug sein, ihr Fürsten Israels! Tut Gewalttat und Bedrückung hinweg, und übet Recht und Gerechtigkeit; höret auf, mein Volk aus seinem Besitze zu vertreiben, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Gerechte Waage und gerechtes Epha und gerechtes Bath sollt ihr haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Das Epha und das Bath sollen von einerlei Maß sein, so daß das Bath den zehnten Teil des Homer enthalte, und das Epha den zehnten Teil des Homer; nach dem Homer soll ihr Maß sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Und der Sekel soll zwanzig Gera sein; zwanzig Sekel, fünfundzwanzig Sekel und fünfzehn Sekel soll euch die Mine sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Dies ist das Hebopfer, welches ihr heben sollt: ein sechstel Epha vom Homer Weizen und ein sechstel Epha vom Homer Gerste sollt ihr geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'und die Gebühr an Öl, vom Bath Öl: ein zehntel Bath vom Kor, von zehn Bath, von einem Homer, denn zehn Bath sind ein Homer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'und ein Stück vom Kleinvieh, von zweihundert, von dem bewässerten Lande Israel: zum Speisopfer und zum Brandopfer und zu den Friedensopfern, um Sühnung für sie zu tun, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Das ganze Volk des Landes soll zu diesem Hebopfer für den Fürsten in Israel gehalten sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Und dem Fürsten sollen obliegen die Brandopfer und das Speisopfer und das Trankopfer an den Festen und an den Neumonden und an den Sabbathen, zu allen Festzeiten des Hauses Israel. Er soll das Sündopfer und das Speisopfer und das Brandopfer und die Friedensopfer opfern, um Sühnung zu tun für das Haus Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'So spricht der Herr, Jehova: Im ersten Monat, am Ersten des Monats, sollst du einen jungen Farren ohne Fehl nehmen und das Heiligtum entsündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Und der Priester soll von dem Blute des Sündopfers nehmen, und es tun an die Türpfosten des Hauses und an die vier Ecken der Umwandung des Altars und an die Pfosten der Tore des inneren Vorhofs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Und ebenso sollst du tun am Siebten des Monats für den, der aus Versehen sündigt, und für den Einfältigen. Und so sollt ihr Sühnung tun für das Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Im ersten Monat, am vierzehnten Tage des Monats, soll euch das Passah sein, ein Fest von sieben Tagen; Ungesäuertes soll gegessen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Und der Fürst soll an selbigem Tage für sich und für das ganze Volk des Landes einen Farren als Sündopfer opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Und die sieben Tage des Festes soll er dem Jehova sieben Farren und sieben Widder, ohne Fehl, täglich, die sieben Tage als Brandopfer opfern, und einen Ziegenbock täglich als Sündopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Und als Speisopfer soll er ein Epha Feinmehl zu jedem Farren und ein Epha zu jedem Widder opfern; und Öl, ein Hin zu jedem Epha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Im siebten Monat, am fünfzehnten Tage des Monats, am Feste, soll er desgleichen tun die sieben Tage, betreffs des Sündopfers wie des Brandopfers und betreffs des Speisopfers wie des Öles.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'So spricht der Herr, Jehova: Das Tor des inneren Vorhofs, welches gegen Osten sieht, soll die sechs Werktage geschlossen sein; aber am Sabbathtage soll es geöffnet werden, und am Tage des Neumondes soll es geöffnet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Und der Fürst soll durch die Torhalle hineingehen von außen her und sich an die Pfosten des Tores stellen; und die Priester sollen sein Brandopfer und seine Friedensopfer opfern, und er soll auf der Schwelle des Tores anbeten und hinausgehen; das Tor soll aber nicht geschlossen werden bis zum Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Und das Volk des Landes soll anbeten am Eingang dieses Tores, an den Sabbathen und an den Neumonden, vor Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Und das Brandopfer, welches der Fürst dem Jehova am Sabbathtage darbringen soll: sechs Lämmer ohne Fehl und ein Widder ohne Fehl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'Und als Speisopfer: ein Epha Feinmehl zu jedem Widder; und zu den Lämmern als Speisopfer: eine Gabe seiner Hand; und Öl, ein Hin zu jedem Epha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Und am Tage des Neumondes: ein junger Farren ohne Fehl und sechs Lämmer und ein Widder; ohne Fehl sollen sie sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Und ein Epha zu jedem Farren und ein Epha zu jedem Widder soll er als Speisopfer opfern; und zu den Lämmern, nach dem was seine Hand aufbringen kann; und Öl, ein Hin zu jedem Epha. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Und wenn der Fürst hineingeht, soll er durch die Torhalle hineingehen; und durch sie soll er hinausgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Und wenn das Volk des Landes an den Festen vor Jehova kommt: wer durch das Nordtor hineingeht, um anzubeten, soll durch das Südtor hinausgehen; und wer durch das Südtor hineingeht, soll durch das Nordtor hinausgehen; er soll nicht durch das Tor zurückkehren, durch welches er hineingegangen ist, sondern stracks vor sich hinausgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Und der Fürst soll mitten unter ihnen hineingehen, wenn sie hineingehen; und wenn sie hinausgehen, sollen sie zusammen hinausgehen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Und an den Festen und zu den Festzeiten soll das Speisopfer sein: ein Epha Feinmehl zu jedem Farren und ein Epha zu jedem Widder; und zu den Lämmern eine Gabe seiner Hand; und Öl, ein Hin zu jedem Epha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Und wenn der Fürst ein freiwilliges Brandopfer oder freiwillige Friedensopfer dem Jehova opfern will, so soll man ihm das Tor öffnen, welches gegen Osten sieht; und er soll sein Brandopfer und seine Fiedensopfer opfern, gleichwie er am Sabbathtage tut; und wenn er hinausgeht, so soll man das Tor verschließen, nachdem er hinausgegangen ist. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Und du sollst täglich ein einjähriges Lamm ohne Fehl dem Jehova als Brandopfer opfern, Morgen für Morgen sollst du es opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Und ein Speisopfer sollst du dazu opfern, Morgen für Morgen: ein sechstel Epha; und Öl, ein drittel Hin, um das Feinmehl zu befeuchten, als Speisopfer dem Jehova: ewige Satzungen, die beständig währen sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Und opfert das Lamm und das Speisopfer und das Öl, Morgen für Morgen, als ein beständiges Brandopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'So spricht der Herr, Jehova: Wenn der Fürst einem seiner Söhne ein Geschenk gibt, so ist es dessen Erbteil; es soll seinen Söhnen gehören, es ist ihr Erbeigentum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Wenn er aber einem seiner Knechte ein Geschenk von seinem Erbteil gibt, so soll es demselben bis zum Freijahre gehören, und dann wieder an den Fürsten kommen; es ist ja sein Erbteil: seinen Söhnen, ihnen soll es gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Und der Fürst soll nichts von dem Erbteil des Volkes nehmen, so daß er sie aus ihrem Eigentum verdrängt; von seinem Eigentum soll er seinen Söhnen vererben, auf daß mein Volk nicht zerstreut werde, ein jeder aus seinem Eigentum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Und er brachte mich durch den Zugang, der an der Seite des Tores war, zu den heiligen Zellen für die Priester, welche gegen Norden sahen; und siehe, daselbst war ein Ort an der äußersten Seite gegen Westen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Und er sprach zu mir: Das ist der Ort, wo die Priester das Schuldopfer und das Sündopfer kochen, wo sie das Speisopfer backen sollen, damit sie es nicht in den äußeren Vorhof hinaustragen, das Volk zu heiligen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Und er führte mich hinaus in den äußeren Vorhof und ließ mich an den vier Ecken des Vorhofs vorübergehen; und siehe, in jeder Ecke des Vorhofs war ein Hof.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'In den vier Ecken des Vorhofs waren geschlossene Höfe, vierzig Ellen lang und dreißig breit; alle vier Eckhöfe hatten einerlei Maß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Und in denselben war eine Mauerreihe ringsherum bei allen vieren; und Kochherde waren unter den Mauerreihen angebracht ringsum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Und er sprach zu mir: Dies sind die Kochhäuser, wo die Diener des Hauses das Schlachtopfer des Volkes kochen sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Und er führte mich zurück zu der Tür des Hauses; und siehe, Wasser flossen unter der Schwelle des Hauses hervor gegen Osten, denn die Vorderseite des Hauses war gegen Osten; und die Wasser flossen herab von unten, von der rechten Seite des Hauses her, südlich vom Altar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Und er führte mich hinaus durch das Nordtor, und führte mich draußen herum zum äußeren Tore, des Weges zu dem gegen Osten gerichteten Tore; und siehe, Wasser rieselten von der rechten Torseite her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Und als der Mann gegen Osten hinausging, war eine Meßschnur in seiner Hand. Und er maß tausend Ellen, und ließ mich durch die Wasser gehen, Wasser bis an die Knöchel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'und er maß tausend Ellen, und ließ mich durch die Wasser gehen, Wasser bis an die Knie; und er maß tausend Ellen, und ließ mich hindurchgehen, Wasser bis an die Hüften;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'und er maß tausend Ellen, ein Fluß, durch den ich nicht gehen konnte; denn die Wasser waren hoch, Wasser zum Schwimmen, ein Fluß, der nicht zu durchgehen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Und er sprach zu mir: Hast du es gesehen, Menschensohn? Und er führte mich wieder zurück an dem Ufer des Flusses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Als ich zurückkehrte, siehe, da standen an dem Ufer des Flusses sehr viele Bäume auf dieser und auf jener Seite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Und er sprach zu mir: Diese Wasser fließen hinaus nach dem östlichen Kreise, und fließen in die Ebene hinab und gelangen in das Meer; und werden sie in das Meer hinausgeführt, so werden die Wasser des Meeres gesund werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Und es wird geschehen, daß alle lebendigen Seelen, die da wimmeln, überall wohin der Doppelfluß kommt, leben werden. Und der Fische werden sehr viele sein; denn wenn diese Wasser dorthin kommen, so werden die Wasser des Meeres gesund werden, und alles wird leben, wohin der Fluß kommt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Und es wird geschehen, daß Fischer an demselben stehen werden: von En-Gedi bis En-Eglaim werden Plätze sein zur Ausbreitung der Netze. Nach ihrer Art werden seine Fische sein, sehr zahlreich, wie die Fische des großen Meeres.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Seine Sümpfe und seine Lachen werden nicht gesund werden, sie werden salzig bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Und an dem Flusse, an seinem Ufer, auf dieser und auf jener Seite, werden allerlei Bäume wachsen, von denen man ißt, deren Blätter nicht verwelken und deren Früchte nicht ausgehen werden. Monat für Monat werden sie reife Früchte tragen, denn seine Wasser fließen aus dem Heiligtum hervor; und ihre Früchte werden zur Speise dienen und ihre Blätter zur Heilung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'So spricht der Herr, Jehova: Dies ist die Grenze, nach welcher ihr euch das Land als Erbe verteilen sollt nach den zwölf Stämmen Israels: für Joseph zwei Lose.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Und ihr sollt es erben, der eine wie der andere, das Land, welches euren Vätern zu geben ich meine Hand erhoben habe; und dieses Land soll euch als Erbteil zufallen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Und dies ist die Grenze des Landes: Auf der Nordseite, vom großen Meere an, des Weges nach Hethlon, gegen Zedad hin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Hamath, Berotha, Sibraim, welches zwischen der Grenze von Damaskus und der Grenze von Hamath liegt, das mittlere Hazer, welches an der Grenze von Hauran liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Und die Grenze vom Meere her soll Hazar-Enon sein, die Grenze von Damaskus; und den Norden betreffend nordwärts, so ist Hamath die Grenze. Und das ist die Nordseite. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Und was die Ostseite betrifft, so ist zwischen Hauran und Damaskus und Gilead und dem Lande Israel der Jordan; von der Nordgrenze nach dem östlichen Meere hin sollt ihr messen. Und das ist die Ostseite. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Und die Mittagseite südwärts: von Thamar bis zum Haderwasser Kades, und nach dem Bache Ägyptens hin bis an das große Meer. Und das ist die Südseite gegen Mittag. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Und die Westseite: das große Meer, von der Südgrenze, bis man Hamath gegenüber kommt; das ist die Westseite. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Und dieses Land sollt ihr unter euch verteilen nach den Stämmen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Und es soll geschehen: euch und den Fremdlingen, die in eurer Mitte weilen, welche Kinder in eurer Mitte gezeugt haben, sollt ihr es als Erbteil verlosen; und sie sollen euch sein wie Eingeborene unter den Kindern Israel; mit euch sollen sie um ein Erbteil losen inmitten der Stämme Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Und es soll geschehen, in dem Stamme, bei welchem der Fremdling weilt, daselbst sollt ihr ihm sein Erbteil geben, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Und dies sind die Namen der Stämme: Vom Nordende an, zur Seite des Weges nach Hethlon, gegen Hamath hin, und nach Hazar-Enon hin, der Grenze von Damaskus, nordwärts, zur Seite von Hamath, die Ost-und die Westseite sollen Dan gehören: ein Los.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Und an der Grenze Dans, von der Ostseite bis zur Westseite: Aser eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Und an der Grenze Asers, von der Ostseite bis zur Westseite: Naphtali eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Und an der Grenze Naphtalis, von der Ostseite bis zur Westseite: Manasse eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Und an der Grenze Manasses, von der Ostseite bis zur Westseite: Ephraim eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Und an der Grenze Ephraims, von der Ostseite bis zur Westseite: Ruben eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Und an der Grenze Rubens, von der Ostseite bis zur Westseite: Juda eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Und an der Grenze Judas, von der Ostseite bis zur Westseite soll das Hebopfer sein, welches ihr heben sollt: fünfundzwanzigtausend Ruten Breite, und die Länge wie eines der Stammteile von der Ostseite bis zur Westseite: und das Heiligtum soll in dessen Mitte sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Das Hebopfer, welches ihr für Jehova heben sollt, soll fünfundzwanzigtausend Ruten in die Länge, und zehntausend in die Breite sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Und diesen soll das heilige Hebopfer gehören, den Priestern: gegen Norden fünfundzwanzigtausend Ruten in die Länge, und gegen Westen zehntausend in die Breite, und gegen Osten zehntausend in die Breite und gegen Süden fünfundzwanzigtausend in die Länge; und das Heiligtum Jehovas soll in dessen Mitte sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Den Priestern, wer geheiligt ist von den Söhnen Zadoks die meiner Hut gewartet haben, welche, als die Kinder Israel abirrten, nicht abgeirrt sind, wie die Leviten abgeirrt sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'ihnen soll ein Gehobenes von dem Hebopfer des Landes gehören, ein Hochheiliges an der Grenze der Leviten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Und die Leviten sollen, gleichlaufend dem Gebiete der Priester, fünfundzwanzigtausend Ruten in die Länge und zehntausend in die Breite erhalten; die ganze Länge soll fünfundzwanzigtausend und die Breite zehntausend sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Und sie sollen nichts davon verkaufen noch vertauschen; und der Erstling des Landes soll nicht an andere übergehen, denn er ist Jehova heilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Und die fünftausend Ruten, die in der Breite übrig sind, längs der fünfundzwanzigtausend, soll gemeines Land sein für die Stadt zur Wohnung und zum Freiplatz; und die Stadt soll in der Mitte desselben sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Und dies sollen ihre Maße sein: die Nordseite viertausendfünfhundert Ruten, und die Südseite viertausendfünfhundert, und an der Ostseite viertausendfünfhundert, und die Westseite viertausendfünfhundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Und der Freiplatz der Stadt soll sein: gegen Norden zweihundertfünfzig Ruten, und gegen Süden zweihundertfünfzig, und gegen Osten zweihundertfünfzig, und gegen Westen zweihundertfünfzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Und das Übrige in der Länge, gleichlaufend dem heiligen Hebopfer, zehntausend Ruten, gegen Osten und zehntausend gegen Westen (es ist gleichlaufend dem heiligen Hebopfer), dessen Ertrag soll den Arbeitern der Stadt zur Nahrung dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Und die Arbeiter der Stadt, die sollen es bebauen aus allen Stämmen Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Das ganze Hebopfer soll fünfundzwanzigtausend Ruten bei fünfundzwanzigtausend sein. Den vierten Teil des heiligen Hebopfers sollt ihr heben zum Eigentum der Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Und das Übrige soll dem Fürsten gehören; auf dieser und auf jener Seite des heiligen Hebopfers und des Eigentums der Stadt, längs der fünfundzwanzigtausend Ruten des Hebopfers bis zur Ostgrenze, und gegen Westen längs der fünfundzwanzigtausend, nach der Westgrenze hin, gleichlaufend den Stammteilen, soll dem Fürsten gehören. Und das heilige Hebopfer und das Heiligtum des Hauses soll in dessen Mitte sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Und von dem Eigentum der Leviten und von dem Eigentum der Stadt ab, welche in der Mitte dessen liegen, was dem Fürsten gehört, was zwischen der Grenze Judas und der Grenze Benjamins ist, soll dem Fürsten gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Und die übrigen Stämme: Von der Ostseite bis zur Westseite: Benjamin ein Los.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Und an der Grenze Benjamins, von der Ostseite bis zur Westseite: Simeon eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Und an der Grenze Simeons, von der Ostseite bis zur Westseite: Issaschar eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Und an der Grenze Issaschars, von der Ostseite bis zur Westseite: Sebulon eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Und an der Grenze Sebulons, von der Ostseite bis zur Westseite: Gad eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Und an der Grenze Gads, nach der Mittagseite hin südwärts, da soll die Grenze sein von Thamar nach dem Wasser Meriba-Kades, nach dem Bache Ägyptens hin bis an das große Meer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Das ist das Land, welches ihr den Stämmen Israels als Erbteil verlosen sollt; und das sind ihre Teile, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Und dies sollen die Ausgänge der Stadt sein: Von der Nordseite an viertausendfünfhundert Ruten Maß;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'und die Tore der Stadt, nach den Namen der Stämme Israels: drei Tore gegen Norden: das Tor Rubens eines, das Tor Judas eines, das Tor Levis eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Und nach der Ostseite hin, viertausendfünfhundert Ruten, und drei Tore: das Tor Josephs eines, das Tor Benjamins eines, das Tor Dans eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Und an der Südseite, viertausendfünfhundert Ruten Maß, und drei Tore: das Tor Simeons eines, das Tor Issaschars eines, das Tor Sebulons eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'An der Westseite, viertausendfünfhundert Ruten, ihrer Tore drei: das Tor Gads eines, das Tor Asers eines, das Tor Naphtalis eines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Ringsum achtzehntausend Ruten. Und der Name der Stadt soll von nun an heißen: Jehova daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Im dritten Jahre der Regierung Jojakims, des Königs von Juda, kam Nebukadnezar, der König von Babel, nach Jerusalem und belagerte es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Und der Herr gab Jojakim, den König von Juda, in seine Hand, und einen Teil der Geräte des Hauses Gottes; und er brachte sie in das Land Sinear, in das Haus seines Gottes: die Geräte brachte er in das Schatzhaus seines Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Und der König befahl dem Aschpenas, dem Obersten seiner Kämmerer, daß er von den Kindern Israel, sowohl von dem königlichen Samen als auch von den Vornehmen, Jünglinge brächte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'an welchen keinerlei Fehl wäre, und schön von Ansehen und unterwiesen in aller Weisheit und kenntnisreich und mit Einsicht begabt, und welche tüchtig wären, im Palaste des Königs zu stehen; und daß man sie die Schriften und die Sprache der Chaldäer lehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Und der König verordnete ihnen ein Tagtägliches von der Tafelkost des Königs und von dem Weine, den er trank, und daß man sie drei Jahre lang erzöge; und am Ende derselben sollten sie vor dem König stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Und es waren unter ihnen, von den Kindern Juda: Daniel, Hananja, Misael und Asarja.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Und der Oberste der Kämmerer gab ihnen Namen; und er nannte Daniel Beltsazar, und Hananja Sadrach, und Misael Mesach, und Asarja Abednego.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Und Daniel nahm sich in seinem Herzen vor, sich nicht mit der Tafelkost des Königs und mit dem Weine, den er trank, zu verunreinigen; und er erbat sich von dem Obersten der Kämmerer, daß er sich nicht verunreinigen müsse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Und Gott gab Daniel Gnade und Barmherzigkeit vor dem Obersten der Kämmerer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Und der Oberste der Kämmerer sprach zu Daniel: Ich fürchte meinen Herrn, den König, der eure Speise und euer Getränk verordnet hat; denn warum sollte er sehen, daß eure Angesichter verfallener wären als die der Jünglinge eures Alters, so daß ihr meinen Kopf beim König verwirktet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Und Daniel sprach zu dem Aufseher, welchen der Oberste der Kämmerer über Daniel, Hananja, Misael und Asarja bestellt hatte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Versuche es doch mit deinen Knechten zehn Tage, und man gebe uns Gemüse zu essen und Wasser zu trinken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'und dann mögen unser Aussehen und das Aussehen der Jünglinge, welche die Tafelkost des Königs essen, von dir geprüft werden; und tue mit deinen Knechten nach dem, was du sehen wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Und er hörte auf sie in dieser Sache und versuchte es zehn Tage mit ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Und am Ende der zehn Tage zeigte sich ihr Aussehen besser und völliger an Fleisch als dasjenige aller Jünglinge, welche die Tafelkost des Königs aßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Da tat der Aufseher ihre Tafelkost und den Wein, den sie trinken sollten, weg und gab ihnen Gemüse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Und diesen vier Jünglingen, ihnen gab Gott Kenntnis und Einsicht in aller Schrift und Weisheit; und Daniel hatte Verständnis für alle Gesichte und Träume.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Und am Ende der Tage, nach welchen der König sie zu bringen befohlen hatte, brachte sie der Oberste der Kämmerer vor Nebukadnezar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Und der König redete mit ihnen; und unter ihnen allen wurde keiner gefunden wie Daniel, Hananja, Misael und Asarja; und sie standen vor dem König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Und in allen Sachen einsichtsvoller Weisheit, welche der König von ihnen erfragte, fand er sie zehnmal allen Schriftgelehrten und Beschwörern überlegen, die in seinem ganzen Königreiche waren. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Und Daniel blieb bis zum ersten Jahre des Königs Kores.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Und im zweiten Jahre der Regierung Nebukadnezars hatte Nebukadnezar Träume, und sein Geist wurde beunruhigt, und sein Schlaf war für ihn dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Und der König befahl, daß man die Schriftgelehrten und die Beschwörer und die Zauberer und die Chaldäer rufen sollte, um dem König seine Träume kundzutun; und sie kamen und traten vor den König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Und der König sprach zu ihnen: Ich habe einen Traum gehabt, und mein Geist ist beunruhigt, um den Traum zu wissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Und die Chaldäer sprachen zu dem König auf aramäisch: O König, lebe ewiglich! Sage deinen Knechten den Traum, so wollen wir die Deutung anzeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Der König antwortete und sprach zu den Chaldäern: Die Sache ist von mir fest beschlossen: wenn ihr mir den Traum und seine Deutung nicht kundtut, so sollt ihr in Stücke zerhauen, und eure Häuser sollen zu Kotstätten gemacht werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'wenn ihr aber den Traum und seine Deutung anzeiget, so sollt ihr Geschenke und Gaben und große Ehre von mir empfangen. Darum zeiget mir den Traum und seine Deutung an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Sie antworteten zum zweiten Male und sprachen: Der König sage seinen Knechten den Traum, so wollen wir die Deutung anzeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Der König antwortete und sprach: Ich weiß zuverlässig, daß ihr Zeit gewinnen wollt, weil ihr sehet, daß die Sache von mir fest beschlossen ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'daß, wenn ihr mir den Traum nicht kundtut, es bei eurem Urteil verbleibt; denn ihr habt euch verabredet, Lug und Trug vor mir zu reden, bis die Zeit sich ändere. Darum saget mir den Traum, und ich werde wissen, daß ihr mir seine Deutung anzeigen könnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Die Chaldäer antworteten vor dem König und sprachen: Kein Mensch ist auf dem Erdboden, der die Sache des Königs anzeigen könnte; weil kein großer und mächtiger König jemals eine Sache wie diese von irgend einem Schriftgelehrten oder Zauberer oder Chaldäer verlangt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Denn die Sache, welche der König verlangt, ist schwer; und es gibt keinen anderen, der sie vor dem König anzeigen könnte, als nur die Götter, deren Wohnung nicht bei dem Fleische ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Dieserhalb ward der König zornig und ergrimmte sehr, und er befahl, alle Weisen von Babel umzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Und der Befehl ging aus, und die Weisen wurden getötet; und man suchte Daniel und seine Genossen, um sie zu töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Da erwiderte Daniel mit Verstand und Einsicht dem Arioch, dem Obersten der Leibwache des Königs, welcher ausgezogen war, um die Weisen von Babel zu töten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'er antwortete und sprach zu Arioch, dem Oberbeamten des Königs: Warum der strenge Befehl vom König? Da tat Arioch die Sache dem Daniel kund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Und Daniel ging hinein und erbat sich von dem König, daß er ihm eine Frist gewähren möge, um dem König die Deutung anzuzeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Hierauf ging Daniel in sein Haus; und er tat die Sache seinen Genossen Hananja, Misael und Asarja kund,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'auf daß sie von dem Gott des Himmels Barmherzigkeit erbitten möchten wegen dieses Geheimnisses, damit nicht Daniel und seine Genossen mit den übrigen Weisen von Babel umkämen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Hierauf wurde dem Daniel in einem Nachtgesicht das Geheimnis geoffenbart. Da pries Daniel den Gott des Himmels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel hob an und sprach: Gepriesen sei der Name Gottes von Ewigkeit zu Ewigkeit! Denn Weisheit und Macht, sie sind sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Und er ändert Zeiten und Zeitpunkte, setzt Könige ab und setzt Könige ein; er gibt den Weisen Weisheit und Verstand den Verständigen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'er offenbart das Tiefe und das Verborgene; er weiß, was in der Finsternis ist, und bei ihm wohnt das Licht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Dich, Gott meiner Väter, lobe und rühme ich, daß du mir Weisheit und Kraft gegeben, und mir jetzt kundgetan hast, was wir von dir erbeten haben; denn du hast uns die Sache des Königs kundgetan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Dieserhalb ging Daniel zu Arioch hinein, welchen der König bestellt hatte, die Weisen von Babel umzubringen; er ging hin und sprach zu ihm also: Bringe die Weisen von Babel nicht um; führe mich vor den König, und ich werde dem König die Deutung anzeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Da führte Arioch eilends den Daniel vor den König, und sprach zu ihm also: Ich habe einen Mann unter den Weggeführten von Juda gefunden, welcher dem König die Deutung kundtun wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Der König hob an und sprach zu Daniel, dessen Name Beltsazar war: Bist du imstande, den Traum, den ich gesehen habe, und seine Deutung mir kundzutun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel antwortete vor dem König und sprach: Das Geheimnis, welches der König verlangt, können Weise, Beschwörer, Schriftgelehrte und Wahrsager dem König nicht anzeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Aber es ist ein Gott im Himmel, der Geheimnisse offenbart; und er hat dem König Nebukadnezar kundgetan, was am Ende der Tage geschehen wird. Dein Traum und die Gesichte deines Hauptes auf deinem Lager waren diese:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Dir, o König, stiegen auf deinem Lager Gedanken auf, was nach diesem geschehen werde; und der, welcher die Geheimnisse offenbart, hat dir kundgetan, was geschehen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Mir aber ist nicht durch Weisheit, die in mir mehr als in allen Lebenden wäre, dieses Geheimnis geoffenbart worden, sondern deshalb, damit man dem König die Deutung kundtue und du deines Herzens Gedanken erfahrest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Du, o König, sahst: und siehe, ein großes Bild; dieses Bild war gewaltig, und sein Glanz außergewöhnlich; es stand vor dir, und sein Aussehen war schrecklich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Dieses Bild, sein Haupt war von feinem Golde; seine Brust und seine Arme von Silber; sein Bauch und seine Lenden von Erz; seine Schenkel von Eisen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'seine Füße teils von Eisen und teils von Ton.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'du schautest, bis ein Stein sich losriß ohne Hände, und das Bild an seine Füße von Eisen und Ton schlug und sie zermalmte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Da wurden zugleich das Eisen, der Ton, das Erz, das Silber und das Gold zermalmt, und sie wurden wie Spreu der Sommertennen; und der Wind führte sie hinweg, und es wurde keine Stätte für sie gefunden. Und der Stein, der das Bild geschlagen hatte, wurde zu einem großen Berge und füllte die ganze Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Das ist der Traum; und seine Deutung wollen wir vor dem König ansagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Du, o König, du König der Könige, dem der Gott des Himmels das Königtum, die Macht und die Gewalt und die Ehre gegeben hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'und überall, wo Menschenkinder, Tiere des Feldes und Vögel des Himmels wohnen, hat er sie in deine Hand gegeben und dich zum Herrscher über sie alle gesetzt, du bist das Haupt von Gold.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Und nach dir wird ein anderes Königreich aufstehen, niedriger als du; und ein anderes, drittes Königreich, von Erz, welches über die ganze Erde herrschen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Und ein viertes Königreich wird stark sein wie Eisen; ebenso wie das Eisen alles zermalmt und zerschlägt, so wird es, dem Eisen gleich, welches zertrümmert, alle diese zermalmen und zertrümmern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Und daß du die Füße und die Zehen teils von Töpferton und teils von Eisen gesehen hast, es wird ein geteiltes Königreich sein; aber von der Festigkeit des Eisens wird in ihm sein, weil du das Eisen mit lehmigem Ton vermischt gesehen hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Und die Zehen der Füße, teils von Eisen und teils von Ton: zum Teil wird das Königreich stark sein, und ein Teil wird zerbrechlich sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Daß du das Eisen mit lehmigem Ton vermischt gesehen hast, sie werden sich mit dem Samen der Menschen vermischen, aber sie werden nicht aneinander haften: gleichwie sich Eisen mit Ton nicht vermischt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Und in den Tagen dieser Könige wird der Gott des Himmels ein Königreich aufrichten, welches ewiglich nicht zerstört, und dessen Herrschaft keinem anderen Volke überlassen werden wird; es wird alle jene Königreiche zermalmen und vernichten, selbst aber ewiglich bestehen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'weil du gesehen hast, daß von dem Berge ein Stein sich losriß ohne Hände und das Eisen, das Erz, den Ton, das Silber und das Gold zermalmte. Der große Gott hat dem Könige kundgetan, was nach diesem geschehen wird; und der Traum ist gewiß und seine Deutung zuverlässig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Da fiel der König Nebukadnezar nieder auf sein Angesicht und betete Daniel an; und er befahl, ihm Speisopfer und Räucherwerk darzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Der König antwortete Daniel und sprach: In Wahrheit, euer Gott ist der Gott der Götter und der Herr der Könige, und ein Offenbarer der Geheimnisse, da du vermocht hast, dieses Geheimnis zu offenbaren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Alsdann machte der König den Daniel groß und gab ihm viele große Geschenke, und er setzte ihn als Herrscher ein über die ganze Landschaft Babel und zum Obervorsteher über alle Weisen von Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Und Daniel bat den König, und er bestellte Sadrach, Mesach und Abednego über die Verwaltung der Landschaft Babel. Und Daniel war im Tore des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Der König Nebukadnezar machte ein Bild von Gold: seine Höhe sechzig Ellen, seine Breite sechs Ellen; er richtete es auf in der Ebene Dura, in der Landschaft Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Und der König Nebukadnezar sandte aus, um die Satrapen, die Statthalter und die Landpfleger, die Oberrichter, die Schatzmeister, die Gesetzeskundigen, die Rechtsgelehrten und alle Oberbeamten der Landschaften zu versammeln, damit sie zur Einweihung des Bildes kämen, welches der König Nebukadnezar aufgerichtet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Da versammelten sich die Satrapen, die Statthalter und die Landpfleger, die Oberrichter, die Schatzmeister, die Gesetzeskundigen, die Rechtsgelehrten und alle Oberbeamten der Landschaften zur Einweihung des Bildes, welches der König Nebukadnezar aufgerichtet hatte; und sie standen vor dem Bilde, welches Nebukadnezar aufgerichtet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Und der Herold rief mit Macht: Euch wird befohlen, ihr Völker, Völkerschaften und Sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Sobald ihr den Klang des Hornes, der Pfeife, der Zither, der Sambuke, der Laute, der Sackpfeife, und allerlei Art von Musik hören werdet, sollt ihr niederfallen und das goldene Bild anbeten, welches der König Nebukadnezar aufgerichtet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Und wer nicht niederfällt und anbetet, der soll sofort in den brennenden Feuerofen geworfen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Darum, sobald alle Völker den Klang des Hornes, der Pfeife, der Zither, der Sambuke, der Laute, und allerlei Art von Musik hörten, fielen alle Völker, Völkerschaften und Sprachen nieder, indem sie das goldene Bild anbeteten, welches der König Nebukadnezar aufgerichtet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Deswegen traten zur selben Zeit chaldäische Männer herzu, welche die Juden anzeigten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Sie hoben an und sprachen zum König Nebukadnezar:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'O König, lebe ewiglich! Du, o König, hast den Befehl gegeben, daß jedermann, der den Klang des Hornes, der Pfeife, der Zither, der Sambuke, der Laute und der Sackpfeife, und allerlei Art von Musik hören würde, niederfallen und das goldene Bild anbeten solle;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'und wer nicht niederfalle und anbete, der solle in den brennenden Feuerofen geworfen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Es sind nun jüdische Männer da, welche du über die Verwaltung der Landschaft Babel bestellt hast: Sadrach, Mesach und Abednego; diese Männer, o König, achten nicht auf dich; deinen Göttern dienen sie nicht, und das goldene Bild, welches du aufgerichtet hast, beten sie nicht an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Da befahl Nebukadnezar im Zorn und Grimm, Sadrach, Mesach und Abednego herbeizubringen. Da wurden diese Männer vor den König gebracht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Nebukadnezar hob an und sprach zu ihnen: Ist es Absicht, Sadrach, Mesach und Abednego, daß ihr meinen Göttern nicht dienet und das goldene Bild nicht anbetet, welches ich aufgerichtet habe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Nun, wenn ihr bereit seid, zur Zeit, da ihr den Klang des Hornes, der Pfeife, der Zither, der Sambuke, der Laute und der Sackpfeife, und allerlei Art von Musik hören werdet, niederzufallen und das Bild anzubeten, welches ich gemacht habe...;wenn ihr es aber nicht anbetet, sollt ihr sofort in den brennenden Feuerofen geworfen werden; und wer ist der Gott, der euch aus meiner Hand erretten wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Sadrach, Mesach und Abednego antworteten und sprachen zu dem König: Nebukadnezar, wir halten es nicht für nötig, dir ein Wort darauf zu erwidern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Ob unser Gott, dem wir dienen, uns aus dem brennenden Feuerofen zu erretten vermag und er wird uns aus deiner Hand, o König, erretten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'oder ob nicht, es sei dir kund, o König, daß wir deinen Göttern nicht dienen und das goldene Bild, welches du aufgerichtet hast, nicht anbeten werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Da wurde Nebukadnezar voll Grimmes, und das Aussehen seines Antlitzes veränderte sich gegen Sadrach, Mesach und Abednego. Er hob an und befahl, den Ofen siebenmal mehr zu heizen, als zur Heizung hinreichend war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Und er befahl Männern, den stärksten Männern in seinem Heere, Sadrach, Mesach und Abednego zu binden, um sie in den brennenden Feuerofen zu werfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Da wurden diese Männer in ihren Leibröcken, Oberröcken und Mänteln und ihren sonstigen Kleidern gebunden und in den brennenden Feuerofen geworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Darum, weil das Wort des Königs streng, und der Ofen außergewöhnlich geheizt war, tötete die Flamme des Feuers jene Männer, welche Sadrach, Mesach und Abednego hinaufbrachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Und diese drei Männer, Sadrach, Mesach und Abednego, fielen gebunden in den brennenden Feuerofen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Da erschrak der König Nebukadnezar, und er stand eilends auf, hob an und sprach zu seinen Räten: Haben wir nicht drei Männer gebunden ins Feuer geworfen? Sie antworteten und sprachen zu dem König: Gewiß, o König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Er antwortete und sprach: Siehe, ich sehe vier Männer frei wandeln mitten im Feuer, und keine Verletzung ist an ihnen; und das Aussehen des vierten ist gleich einem Sohne der Götter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Da trat Nebukadnezar an die Öffnung des brennenden Feuerofens, hob an und sprach: Sadrach, Mesach und Abednego, ihr Knechte des höchsten Gottes, gehet heraus und kommet her! Da gingen Sadrach, Mesach und Abednego aus dem Feuer heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Und es versammelten sich die Satrapen, die Statthalter und die Landpfleger und die Räte des Königs; sie sahen diese Männer, daß das Feuer keine Macht über ihre Leiber gehabt hatte: das Haar ihres Hauptes war nicht versengt, und ihre Leibröcke waren nicht verändert, und der Geruch des Feuers war nicht an sie gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Nebukadnezar hob an und sprach: Gepriesen sei der Gott Sadrachs, Mesachs und Abednegos, der seinen Engel gesandt und seine Knechte errettet hat, die auf ihn vertrauten und das Wort des Königs übertraten und ihre Leiber dahingaben, um keinem Gott zu dienen noch ihn anzubeten, als nur ihrem Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Und von mir wird Befehl gegeben, daß jedes Volk, jede Völkerschaft und Sprache, wer Unrechtes spricht wider den Gott Sadrachs, Mesachs und Abednegos, in Stücke zerhauen, und daß sein Haus zu einer Kotstätte gemacht werde; weil es keinen anderen Gott gibt, der auf solche Weise zu erretten vermag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Alsdann beförderte der König Sadrach, Mesach und Abednego in der Landschaft Babel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Nebukadnezar, der König, allen Völkern, Völkerschaften und Sprachen, die auf der ganzen Erde wohnen: Friede euch in Fülle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Es hat mir gefallen, die Zeichen und Wunder kundzutun, welche der höchste Gott an mir getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Wie groß sind seine Zeichen, und wie mächtig seine Wunder! Sein Reich ist ein ewiges Reich, und seine Herrschaft währt von Geschlecht zu Geschlecht! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Ich, Nebukadnezar, war ruhig in meinem Hause und hatte Gedeihen in meinem Palaste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Ich sah einen Traum, er erschreckte mich; und Gedanken auf meinem Lager und Gesichte meines Hauptes ängstigten mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Und von mir wurde Befehl gegeben, alle Weisen von Babel vor mich zu führen, auf daß sie mir die Deutung des Traumes kundtäten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Alsdann kamen die Schriftgelehrten, die Beschwörer, die Chaldäer und die Wahrsager herbei; und ich trug ihnen den Traum vor, aber sie taten mir seine Deutung nicht kund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Und zuletzt trat vor mich Daniel, dessen Name Beltsazar ist, nach dem Namen meines Gottes, und in welchem der Geist der heiligen Götter ist; und ich trug ihm den Traum vor:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, '\"Beltsazar, du Oberster der Schriftgelehrten, da ich weiß, daß der Geist der heiligen Götter in dir ist, und daß kein Geheimnis dir zu schwer ist, so sage mir die Gesichte meines Traumes, den ich gesehen habe, und seine Deutung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Was nun die Gesichte meines Hauptes auf meinem Lager betrifft, so sah ich: und siehe, ein Baum stand mitten auf der Erde, und seine Höhe war gewaltig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Der Baum wurde groß und stark, und seine Höhe reichte bis an den Himmel, und er wurde gesehen bis an das Ende der ganzen Erde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'sein Laub war schön und seine Frucht zahlreich, und es war Nahrung an ihm für alle; die Tiere des Feldes fanden Schatten unter ihm, und die Vögel des Himmels wohnten in seinen Zweigen, und alles Fleisch nährte sich von ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Ich schaute in den Gesichten meines Hauptes auf meinem Lager, und siehe, ein Wächter und Heiliger stieg vom Himmel hernieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Er rief mit Macht und sprach also: Hauet den Baum um und schneidet seine Zweige weg; streifet sein Laub ab und streuet seine Frucht umher! Die Tiere unter ihm sollen wegfliehen und die Vögel aus seinen Zweigen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Doch seinen Wurzelstock lasset in der Erde, und zwar in Fesseln von Eisen und Erz, im Grase des Feldes; und von dem Tau des Himmels werde er benetzt, und mit den Tieren habe er teil an dem Kraut der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Sein menschliches Herz werde verwandelt und das Herz eines Tieres ihm gegeben; und sieben Zeiten sollen über ihm vergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Durch Beschluß der Wächter ist dieser Ausspruch, und ein Befehl der Heiligen ist diese Sache: auf daß die Lebenden erkennen, daß der Höchste über das Königtum der Menschen herrscht und es verleiht, wem er will, und den Niedrigsten der Menschen darüber bestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Diesen Traum habe ich, der König Nebukadnezar, gesehen; und du, Beltsazar, sage seine Deutung, da alle Weisen meines Königreichs mir die Deutung nicht kundzutun vermögen; du aber vermagst es, weil der Geist der heiligen Götter in dir ist.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Da entsetzte sich Daniel, dessen Name Beltsazar ist, eine Zeitlang, und seine Gedanken ängstigten ihn. Der König hob an und sprach: Beltsazar, der Traum und seine Deutung ängstige dich nicht. Beltsazar antwortete und sprach: Mein Herr, der Traum gelte deinen Hassern und seine Deutung deinen Feinden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Der Baum, den du gesehen hast, der groß und stark wurde, dessen Höhe an den Himmel reichte, und der über die ganze Erde hin gesehen wurde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'und dessen Laub schön und dessen Frucht zahlreich, und an welchem Nahrung war für alle; unter welchem die Tiere des Feldes wohnten, und in dessen Zweigen die Vögel des Himmels sich aufhielten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'das bist du, o König, der du groß und stark geworden bist; und deine Größe wuchs und reichte bis an den Himmel, und deine Herrschaft bis an das Ende der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Und daß der König einen Wächter und Heiligen vom Himmel herniedersteigen sah, welcher sprach: Hauet den Baum um und verderbet ihn! Doch seinen Wurzelstock lasset in der Erde, und zwar in Fesseln von Eisen und Erz, im Grase des Feldes; und von dem Tau des Himmels werde er benetzt, und er habe sein Teil mit den Tieren des Feldes, bis sieben Zeiten über ihm vergehen-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'dies ist die Deutung, o König, und dies der Beschluß des Höchsten, der über meinen Herrn, den König, kommen wird:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Man wird dich von den Menschen ausstoßen, und bei den Tieren des Feldes wird deine Wohnung sein; und man wird dir Kraut zu essen geben, wie den Rindern, und dich vom Tau des Himmels benetzt werden lassen; und es werden sieben Zeiten über dir vergehen, bis du erkennst, daß der Höchste über das Königtum der Menschen herrscht und es verleiht, wem er will.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Und daß man gesagt hat, den Wurzelstock des Baumes zu lassen, dein Königtum wird dir wieder werden, sobald du erkannt haben wirst, daß die Himmel herrschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Darum, o König, laß dir meinen Rat gefallen, und brich mit deinen Sünden durch Gerechtigkeit und mit deinen Missetaten durch Barmherzigkeit gegen Elende, wenn deine Wohlfahrt Dauer haben soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Alles das kam über den König Nebukadnezar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Nach Verlauf von zwölf Monaten wandelte er umher auf dem königlichen Palaste zu Babel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'und der König hob an und sprach: Ist das nicht das große Babel, welches ich zum königlichen Wohnsitz erbaut habe durch die Stärke meiner Macht und zu Ehren meiner Herrlichkeit?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Noch war das Wort im Munde des Königs, da kam eine Stimme vom Himmel herab: Dir, König Nebukadnezar, wird gesagt: Das Königtum ist von dir gewichen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Und man wird dich von den Menschen ausstoßen, und bei den Tieren des Feldes wird deine Wohnung sein, und man wird dir Kraut zu essen geben wie den Rindern; und es werden sieben Zeiten über dir vergehen, bis du erkennst, daß der Höchste über das Königtum der Menschen herrscht und es verleiht, wem er will.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'In demselben Augenblick wurde das Wort über Nebukadnezar vollzogen; und er wurde von den Menschen ausgestoßen, und er aß Kraut wie die Rinder, und sein Leib ward benetzt von dem Tau des Himmels, bis sein Haar wuchs gleich Adlerfedern und seine Nägel gleich Vogelkrallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Und am Ende der Tage erhob ich, Nebukadnezar, meine Augen zum Himmel, und mein Verstand kam mir wieder; und ich pries den Höchsten, und ich rühmte und verherrlichte den ewig Lebenden, dessen Herrschaft eine ewige Herrschaft ist, und dessen Reich von Geschlecht zu Geschlecht währt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'Und alle Bewohner der Erde werden wie nichts geachtet, und nach seinem Willen tut er mit dem Heere des Himmels und mit den Bewohnern der Erde; und da ist niemand, der seiner Hand wehren und zu ihm sagen könnte: Was tust du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'Zur selben Zeit kam mir mein Verstand wieder, und zur Ehre meines Königtums kamen meine Herrlichkeit und mein Glanz mir wieder; und meine Räte und meine Gewaltigen suchten mich auf, und ich wurde wieder in mein Königtum eingesetzt, und ausnehmende Größe wurde mir hinzugefügt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Nun rühme ich, Nebukadnezar, und erhebe und verherrliche den König des Himmels, dessen Werke allesamt Wahrheit und dessen Wege Recht sind, und der zu erniedrigen vermag, die in Hoffart wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Der König Belsazar machte seinen tausend Gewaltigen ein großes Mahl, und er trank Wein vor den Tausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Belsazar befahl, als der Wein ihm schmeckte, daß man die goldenen und die silbernen Gefäße herbeibrächte, welche sein Vater Nebukadnezar aus dem Tempel zu Jerusalem weggenommen hatte, auf daß der König und seine Gewaltigen, seine Frauen und seine Kebsweiber daraus tränken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Dann brachte man die goldenen Gefäße, welche man aus dem Tempel des Hauses Gottes zu Jerusalem weggenommen hatte; und der König und seine Gewaltigen, seine Frauen und seine Kebsweiber tranken daraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Sie tranken Wein und rühmten die Götter von Gold und Silber, von Erz, Eisen, Holz und Stein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'In demselben Augenblick kamen Finger einer Menschenhand hervor und schrieben, dem Leuchter gegenüber, auf den Kalk der Wand des königlichen Palastes; und der König sah die Hand, welche schrieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Da veränderte sich die Gesichtsfarbe des Königs, und seine Gedanken ängstigten ihn; und die Bänder seiner Hüften lösten sich, und seine Knie schlugen aneinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Der König rief mit Macht, daß man die Beschwörer, die Chaldäer und die Wahrsager hereinbringe; und der König hob an und sprach zu den Weisen von Babel: Jeder, der diese Schrift lesen und ihre Deutung mir anzeigen wird, der soll mit Purpur bekleidet werden, mit einer goldenen Kette um seinen Hals, und er soll als Dritter im Königreich herrschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Dann kamen alle Weisen des Königs herbei; aber sie vermochten nicht die Schrift zu lesen, noch die Deutung derselben dem König kundzutun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Da geriet der König Belsazar in große Angst, und seine Gesichtsfarbe veränderte sich an ihm; und seine Gewaltigen wurden bestürzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Infolge der Worte des Königs und seiner Gewaltigen trat die Königin in das Haus des Gelages. Die Königin hob an und sprach: O König, lebe ewiglich! Laß deine Gedanken dich nicht ängstigen und deine Gesichtsfarbe sich nicht verändern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Es ist ein Mann in deinem Königreich, in welchem der Geist der heiligen Götter ist; und in den Tagen deines Vaters wurden Erleuchtung und Verstand und Weisheit gleich der Weisheit der Götter bei ihm gefunden; und der König Nebukadnezar, dein Vater, hat ihn zum Obersten der Schriftgelehrten, der Beschwörer, der Chaldäer und der Wahrsager erhoben, dein Vater, o König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Darum daß ein außergewöhnlicher Geist, und Kenntnis und Verstand, ein Geist der Traumdeutung und der Rätselerklärung und der Knotenlösung bei ihm gefunden wurde, bei Daniel, welchem der König den Namen Beltsazar gegeben hat. So werde nun Daniel gerufen, und er wird die Deutung anzeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Darauf wurde Daniel vor den König geführt. Der König hob an und sprach zu Daniel: Bist du Daniel, einer der Weggeführten von Juda, welche der König, mein Vater, aus Juda hergebracht hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Und ich habe von dir gehört, daß der Geist der Götter in dir ist, und daß Erleuchtung und Verstand und außergewöhnliche Weisheit bei dir gefunden werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Und nun sind die Weisen, die Beschwörer, vor mich geführt worden, damit sie diese Schrift läsen und ihre Deutung mir kundtäten; aber sie vermögen nicht, die Deutung der Sache anzuzeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Ich habe aber von dir gehört, daß du Deutung zu geben und Knoten zu lösen vermagst. Nun, wenn du diese Schrift zu lesen und ihre Deutung mir kundzutun vermagst, so sollst du mit Purpur bekleidet werden, mit einer goldenen Kette um deinen Hals, und du sollst als Dritter im Königreich herrschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Da antwortete Daniel und sprach vor dem König: Deine Gaben mögen dir verbleiben, und deine Geschenke gib einem anderen; jedoch werde ich die Schrift dem König lesen und die Deutung ihm kundtun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Du, o König! Der höchste Gott hatte Nebukadnezar, deinem Vater, das Königtum und die Größe und die Ehre und die Herrlichkeit verliehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'und wegen der Größe, die er ihm verliehen, bebten und fürchteten sich vor ihm alle Völker, Völkerschaften und Sprachen. Wen er wollte, tötete er, und wen er wollte ließ er leben; und wen er wollte, erhob er, und wen er wollte, erniedrigte er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Als aber sein Herz sich erhob und sein Geist bis zur Vermessenheit sich verstockte, wurde er von seinem königlichen Throne gestürzt, und man nahm ihm seine Würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Und er wurde von den Menschenkindern ausgestoßen, und sein Herz wurde dem der Tiere gleich, und seine Wohnung war bei den Wildeseln; man gab ihm Kraut zu essen wie den Rindern, und sein Leib wurde vom Tau des Himmels benetzt bis er erkannte, daß der höchste Gott über das Königtum der Menschen herrscht, und darüber bestellt, wen er will.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Und du, Belsazar, sein Sohn, hast dein Herz nicht gedemütigt, obwohl du dieses alles gewußt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Und du hast dich über den Herrn des Himmels erhoben; und man hat die Gefäße seines Hauses vor dich gebracht, und du und deine Gewaltigen, deine Frauen und deine Kebsweiber, ihr habt Wein daraus getrunken. Und du hast die Götter von Silber und Gold, von Erz, Eisen, Holz und Stein gerühmt, die nicht sehen und nicht hören und nicht wahrnehmen; aber den Gott, in dessen Hand dein Odem ist, und bei dem alle deine Wege sind, hast du nicht geehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Da wurde von ihm diese Hand gesandt und diese Schrift gezeichnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Und dies ist die Schrift, welche gezeichnet worden ist: Mene, mene, tekel upharsin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Dies ist die Deutung der Sache: Mene Gott hat dein Königtum gezählt und macht ihm ein Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tekel du bist auf der Waage gewogen und zu leicht erfunden worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres dein Königreich wird zerteilt und den Medern und Persern gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Alsdann befahl Belsazar, und man bekleidete Daniel mit Purpur, mit einer goldenen Kette um seinen Hals; und man rief über ihn aus, daß er der dritte Herrscher im Königreich sein solle. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'In derselben Nacht wurde Belsazar, der König der Chaldäer, getötet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, '(H6:1) Und Darius, der Meder, bekam das Königreich, als er ungefähr zweiundsechzig Jahre alt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, '(H6:2) Es gefiel Darius, über das Königreich hundertzwanzig Satrapen zu bestellen, die im ganzen Königreich sein sollten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, '(H6:3) und über diese drei Vorsteher, von welchen Daniel einer war: damit jene Satrapen ihnen Rechenschaft gäben und der König keinen Schaden erlitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, '(H6:4) Da übertraf dieser Daniel die Vorsteher und die Satrapen, weil ein außergewöhnlicher Geist in ihm war; und der König gedachte, ihn über das ganze Königreich zu bestellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, '(H6:5) Da suchten die Vorsteher und die Satrapen einen Anklagegrund gegen Daniel von seiten der Verwaltung zu finden; aber sie konnten keinen Anklagegrund und keine schlechte Handlung finden, weil er treu war und kein Vergehen und keine schlechte Handlung an ihm gefunden wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, '(H6:6) Da sprachen diese Männer: Wir werden gegen diesen Daniel keinen Anklagegrund finden, es sei denn daß wir in dem Gesetz seines Gottes einen gegen ihn finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, '(H6:7) Dann liefen diese Vorsteher und Satrapen eilig zu dem König und sprachen zu ihm also: König Darius, lebe ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, '(H6:8) Alle Vorsteher des Königreichs, die Statthalter und Satrapen, die Räte und Landpfleger, sind Rats geworden, daß der König eine Verordnung aufstelle und ein Verbot erlasse, daß ein jeder, der binnen dreißig Tagen von irgend einem Gott oder Menschen etwas erbittet außer von dir, o König, in die Löwengrube geworfen werden soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, '(H6:9) Nun, o König, erlaß das Verbot und laß eine Schrift aufzeichnen, die nach dem Gesetz der Meder und Perser, welches unwiderruflich ist, nicht abgeändert werden darf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, '(H6:10) Deshalb ließ der König Darius die Schrift und das Verbot aufzeichnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, '(H6:11) Und als Daniel erfuhr, daß die Schrift aufgezeichnet war, ging er in sein Haus; und er hatte in seinem Obergemach offene Fenster gegen Jerusalem hin; und dreimal des Tages kniete er auf seine Knie und betete und lobpries vor seinem Gott, wie er vordem getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, '(H6:12) Da liefen jene Männer eilig herbei und fanden Daniel betend und flehend vor seinem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, '(H6:13) Dann nahten sie und sprachen vor dem König betreffs des königlichen Verbotes: Hast du nicht ein Verbot aufzeichnen lassen, daß jedermann, der binnen dreißig Tagen von irgend einem Gott oder Menschen etwas erbitten würde, außer von dir, o König, in die Löwengrube geworfen werden sollte? Der König antwortete und sprach: Die Sache steht fest nach dem Gesetz der Meder und Perser, welches unwiderruflich ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, '(H6:14) Hierauf antworteten sie und sprachen vor dem König: Daniel, einer der Weggeführten von Juda, achtet nicht auf dich, o König, noch auf das Verbot, welches du hast aufzeichnen lassen; sondern er verrichtet dreimal des Tages sein Gebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, '(H6:15) Da wurde der König, als er die Sache hörte, sehr betrübt, und er sann darauf, Daniel zu retten; und bis zum Untergang der Sonne bemühte er sich, ihn zu befreien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, '(H6:16) Da liefen jene Männer eilig zum König und sprachen zum König: Wisse, o König, daß die Meder und Perser ein Gesetz haben, daß kein Verbot und keine Verordnung, die der König aufgestellt hat, abgeändert werden darf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, '(H6:17) Dann befahl der König, und man brachte Daniel und warf ihn in die Löwengrube. Der König hob an und sprach zu Daniel: Dein Gott, welchem du ohne Unterlaß dienst, er möge dich retten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, '(H6:18) Und ein Stein wurde gebracht und auf die Öffnung der Grube gelegt; und der König versiegelte ihn mit seinem Siegelringe und mit dem Siegelringe seiner Gewaltigen, damit hinsichtlich Daniels nichts verändert würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, '(H6:19) Darauf ging der König in seinen Palast, und er übernachtete fastend und ließ keine Kebsweiber zu sich hereinführen; und sein Schlaf floh von ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, '(H6:20) Dann stand der König bei der Morgenröte, sobald es hell wurde, auf und ging eilends zu der Löwengrube.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, '(H6:21) Und als er sich der Grube nahte, rief er mit trauriger Stimme nach Daniel. Der König hob an und sprach zu Daniel: Daniel, Knecht des lebendigen Gottes, hat dein Gott, welchem du ohne Unterlaß dienst, vermocht, dich von den Löwen zu retten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, '(H6:22) Da sprach Daniel zu dem König: O König, lebe ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, '(H6:23) Mein Gott hat seinen Engel gesandt und hat den Rachen der Löwen verschlossen, daß sie mich nicht verletzt haben, weil vor ihm Unschuld an mir gefunden wurde; und auch vor dir, o König, habe ich kein Verbrechen begangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, '(H6:24) Da freute sich der König sehr, und er befahl, Daniel aus der Grube herauszuholen. Und Daniel wurde aus der Grube herausgeholt; und keine Verletzung wurde an ihm gefunden, weil er auf seinen Gott vertraut hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, '(H6:25) Und der König befahl, und man brachte jene Männer, welche Daniel angezeigt hatten, und man warf sie in die Löwengrube, sie, ihre Kinder und ihre Weiber; und ehe sie noch auf den Boden der Grube gekommen waren, bemächtigten sich ihrer die Löwen und zermalmten alle ihre Gebeine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, '(H6:26) Alsdann schrieb der König Darius an alle Völker, Völkerschaften und Sprachen, welche auf der ganzen Erde wohnten: Friede euch in Fülle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, '(H6:27) Von mir wird Befehl gegeben, daß man in der ganzen Herrschaft meines Königreichs bebe und sich fürchte vor dem Gott Daniels; denn er ist der lebendige Gott und besteht in Ewigkeit, und sein Reich wird nie zerstört werden, und seine Herrschaft währt bis ans Ende;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, '(H6:28) der da rettet und befreit, und Zeichen und Wunder tut im Himmel und auf der Erde: denn er hat Daniel aus der Gewalt der Löwen errettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, '(H6:29) Und dieser Daniel hatte Gedeihen unter der Regierung des Darius und unter der Regierung Kores\', des Persers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Im ersten Jahre Belsazars, des Königs von Babel, sah Daniel einen Traum und Gesichte seines Hauptes auf seinem Lager. Dann schrieb er den Traum auf, die Summe der Sache berichtete er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel hob an und sprach: Ich schaute in meinem Gesicht bei der Nacht, und siehe, die vier Winde des Himmels brachen los auf das große Meer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Und vier große Tiere stiegen aus dem Meere herauf, eines verschieden von dem anderen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Das erste war gleich einem Löwen und hatte Adlersflügel; ich schaute, bis seine Flügel ausgerissen wurden, und es von der Erde aufgehoben und wie ein Mensch auf seine Füße gestellt und ihm eines Menschen Herz gegeben wurde. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Und siehe, ein anderes, zweites Tier, gleich einem Bären; und es richtete sich auf einer Seite auf, und es hatte drei Rippen in seinem Maule zwischen seinen Zähnen; und man sprach zu ihm also: Stehe auf, friß viel Fleisch! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Nach diesem schaute ich, und siehe, ein anderes, gleich einem Pardel; und es hatte vier Flügel eines Vogels auf seinem Rücken; und das Tier hatte vier Köpfe, und Herrschaft wurde ihm gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Nach diesem schaute ich in Gesichten der Nacht: und siehe, ein viertes Tier, schrecklich und furchtbar und sehr stark, und es hatte große eiserne Zähne; es fraß und zermalmte, und was übrigblieb, zertrat es mit seinen Füßen; und es war verschieden von allen Tieren, die vor ihm gewesen, und es hatte zehn Hörner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Während ich auf die Hörner achtgab, siehe, da stieg ein anderes, kleines Horn zwischen ihnen empor, und drei von den ersten Hörnern wurden vor ihm ausgerissen; und siehe, an diesem Horne waren Augen wie Menschenaugen, und ein Mund, der große Dinge redete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Ich schaute, bis Throne aufgestellt wurden und ein Alter an Tagen sich setzte: sein Gewand war weiß wie Schnee, und das Haar seines Hauptes wie reine Wolle; sein Thron Feuerflammen, dessen Räder ein loderndes Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Ein Strom von Feuer floß und ging von ihm aus; tausend mal Tausende dienten ihm, und zehntausend mal Zehntausende standen vor ihm. Das Gericht setzte sich, und Bücher wurden aufgetan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Dann schaute ich wegen der Stimme der großen Worte, welche das Horn redete: ich schaute, bis das Tier getötet, und sein Leib zerstört und dem Brande des Feuers übergeben wurde. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Und was die übrigen Tiere betrifft: ihre Herrschaft wurde weggenommen, aber Verlängerung des Lebens ward ihnen gegeben bis auf Zeit und Stunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Ich schaute in Gesichten der Nacht: und siehe, mit den Wolken des Himmels kam einer wie eines Menschen Sohn; und er kam zu dem Alten an Tagen und wurde vor denselben gebracht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Und ihm wurde Herrschaft und Herrlichkeit und Königtum gegeben, und alle Völker, Völkerschaften und Sprachen dienten ihm; seine Herrschaft ist eine ewige Herrschaft, die nicht vergehen, und sein Königtum ein solches, das nie zerstört werden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Mir, Daniel, ward mein Geist in mir tief ergriffen, und die Gesichte meines Hauptes ängstigten mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Ich nahte zu einem der Dastehenden, um von ihm Gewißheit über dies alles zu erbitten. Und er sagte mir, daß er mir die Deutung der Sache kundtun wolle:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Diese großen Tiere, deren vier waren, sind vier Könige, die von der Erde aufstehen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Aber die Heiligen der höchsten Örter werden das Reich empfangen, und werden das Reich besitzen bis in Ewigkeit, ja, bis in die Ewigkeit der Ewigkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Darauf begehrte ich Gewißheit über das vierte Tier, welches von allen anderen verschieden war, sehr schrecklich, dessen Zähne von Eisen und dessen Klauen von Erz waren, welches fraß, zermalmte, und was übrigblieb, mit seinen Füßen zertrat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'und über die zehn Hörner auf seinem Kopfe; und über das andere Horn, welches emporstieg, und vor welchem drei abfielen; und das Horn hatte Augen und einen Mund, der große Dinge redete, und sein Aussehen war größer als das seiner Genossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Ich sah, wie dieses Horn Krieg wider die Heiligen führte und sie besiegte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'bis der Alte an Tagen kam, und das Gericht den Heiligen der höchsten Örter gegeben wurde, und die Zeit kam, da die Heiligen das Reich in Besitz nahmen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Er sprach also: Das vierte Tier: ein viertes Königreich wird auf Erden sein, welches von allen Königreichen verschieden sein wird; und es wird die ganze Erde verzehren und sie zertreten und sie zermalmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Und die zehn Hörner: aus jenem Königreich werden zehn Könige aufstehen; und ein anderer wird nach ihnen aufstehen, und dieser wird verschieden sein von den vorigen und wird drei Könige erniedrigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Und er wird Worte reden gegen den Höchsten und die Heiligen der höchsten Örter vernichten; und er wird darauf sinnen, Zeiten und Gesetz zu ändern, und sie werden eine Zeit und Zeiten und eine halbe Zeit in seine Hand gegeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Aber das Gericht wird sich setzen; und man wird seine Herrschaft wegnehmen, um sie zu vernichten und zu zerstören bis zum Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Und das Reich und die Herrschaft und die Größe der Königreiche unter dem ganzen Himmel wird dem Volke der Heiligen der höchsten Örter gegeben werden. Sein Reich ist ein ewiges Reich, und alle Herrschaften werden ihm dienen und gehorchen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Bis hierher das Ende der Sache. Mich, Daniel, ängstigten meine Gedanken sehr, und meine Gesichtsfarbe veränderte sich an mir; und ich bewahrte die Sache in meinem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Im dritten Jahre der Regierung des Königs Belsazar erschien mir, Daniel, ein Gesicht, nach demjenigen, welches mir im Anfang erschienen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Und ich sah im Gesicht; und es geschah, als ich sah, da war ich in der Burg Susan, welche in der Landschaft Elam ist; und ich sah im Gesicht, und ich war am Flusse Ulai.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Und ich erhob meine Augen und sah: und siehe, ein Widder stand vor dem Flusse, der hatte zwei Hörner; und die zwei Hörner waren hoch, und das eine war höher als das andere, und das höhere stieg zuletzt empor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Ich sah den Widder nach Westen und nach Norden und nach Süden stoßen, und kein Tier konnte vor ihm bestehen, und niemand rettete aus seiner Hand; und er handelte nach seinem Gutdünken und wurde groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Und während ich achtgab, siehe, da kam ein Ziegenbock von Westen her über die ganze Erde, und er berührte die Erde nicht; und der Bock hatte ein ansehnliches Horn zwischen seinen Augen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Und er kam bis zu dem Widder mit den zwei Hörnern, welchen ich vor dem Flusse hatte stehen sehen; und er rannte ihn an im Grimme seiner Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Und ich sah ihn bei dem Widder anlangen, und er erbitterte sich gegen ihn, und er stieß den Widder und zerbrach seine beiden Hörner; und in dem Widder war keine Kraft, um vor ihm zu bestehen. Und er warf ihn zu Boden und zertrat ihn, und niemand rettete den Widder aus seiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Und der Ziegenbock wurde groß über die Maßen; und als er stark geworden war, zerbrach das große Horn, und vier ansehnliche Hörner wuchsen an seiner Statt nach den vier Winden des Himmels hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Und aus dem einen von ihnen kam ein kleines Horn hervor; und es wurde ausnehmend groß gegen Süden und gegen Osten und gegen die Zierde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Und es wurde groß bis zum Heere des Himmels, und es warf von dem Heere und von den Sternen zur Erde nieder und zertrat sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Selbst bis zu dem Fürsten des Heeres tat es groß; und es nahm ihm das beständige Opfer weg, und die Stätte seines Heiligtums wurde niedergeworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Und das Heer wurde dahingegeben samt dem beständigen Opfer, um des Frevels willen. Und es warf die Wahrheit zu Boden und handelte und hatte Gelingen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Und ich hörte einen Heiligen reden; und ein Heiliger sprach zu jenem, welcher redete: Bis wann geht das Gesicht von dem beständigen Opfer und von dem verwüstenden Frevel, da sowohl das Heiligtum als auch das Heer zur Zertretung hingegeben ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Und er sprach zu mir: Bis zu zweitausend dreihundert Abenden und Morgen; dann wird das Heiligtum gerechtfertigt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Und es geschah, als ich, Daniel, das Gesicht sah, da suchte ich Verständnis darüber; und siehe, da stand vor mir wie die Gestalt eines Mannes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Und ich hörte eine Menschenstimme zwischen den Ufern des Ulai, welche rief und sprach: Gabriel, gib diesem das Gesicht zu verstehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Und er trat an den Ort, wo ich stand; und als er herzutrat, erschrak ich und fiel nieder auf mein Angesicht. Und er sprach zu mir: Merke auf, Menschensohn! Denn das Gesicht geht auf die Zeit des Endes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Und als er mit mir redete, sank ich betäubt auf mein Angesicht zur Erde. Er aber rührte mich an und stellte mich auf meinen früheren Standort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Und er sprach: Siehe, ich will dir kundtun, was in der letzten Zeit des Zornes geschehen wird; denn es geht auf die bestimmte Zeit des Endes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Der Widder mit den zwei Hörnern, welchen du gesehen hast, sind die Könige von Medien und Persien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Und der zottige Ziegenbock ist der König von Griechenland; und das große Horn, das zwischen seinen Augen war, ist der erste König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Und daß es zerbrach und vier an seiner Statt aufkamen: vier Königreiche werden aus dieser Nation aufstehen, aber nicht mit seiner Macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Und am Ende ihres Königtums, wenn die Frevler das Maß voll gemacht haben werden, wird ein König aufstehen, frechen Angesichts und der Ränke kundig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Und seine Macht wird stark sein, aber nicht durch seine eigene Macht; und er wird erstaunliches Verderben anrichten, und Gelingen haben und handeln; und er wird Starke und das Volk der Heiligen verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Und durch seine Klugheit wird der Trug in seiner Hand gelingen; und er wird in seinem Herzen großtun und unversehens viele verderben. Und gegen den Fürsten der Fürsten wird er sich auflehnen, aber ohne Menschenhand zerschmettert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Und das Gesicht von den Abenden und von den Morgen, wovon gesprochen worden, ist Wahrheit; und du, verschließe das Gesicht, denn es sind noch viele Tage bis dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Und ich, Daniel, war dahin und war einige Tage krank. Dann stand ich auf und verrichtete die Geschäfte des Königs. Und ich war entsetzt über das Gesicht, und niemand verstand es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Im ersten Jahre Darius\', des Sohnes Ahasveros\', aus dem Samen der Meder, welcher über das Reich der Chaldäer König geworden war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'im ersten Jahre seiner Regierung merkte ich, Daniel, in den Schriften auf die Zahl der Jahre, betreffs welcher das Wort Jehovas zu dem Propheten Jeremia geschehen war, daß nämlich siebzig Jahre für die Verwüstung Jerusalems vollendet werden sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Und ich richtete mein Angesicht zu Gott, dem Herrn, um ihn mit Gebet und Flehen zu suchen, in Fasten und Sacktuch und Asche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Und ich betete zu Jehova, meinem Gott, und ich bekannte und sprach: Ach, Herr! Du großer und furchtbarer Gott, der den Bund und die Güte denen bewahrt, die ihn lieben und seine Gebote halten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Wir haben gesündigt und verkehrt und gesetzlos gehandelt, und wir haben uns empört und sind von deinen Geboten und von deinen Rechten abgewichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Und wir haben nicht auf deine Knechte, die Propheten, gehört, welche in deinem Namen zu unseren Königen, unseren Fürsten und unseren Vätern und zu allem Volke des Landes geredet haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Dein, o Herr, ist die Gerechtigkeit, unser aber die Beschämung des Angesichts, wie es an diesem Tage ist: der Männer von Juda und der Bewohner von Jerusalem, und des ganzen Israel, der Nahen und der Fernen, in allen Ländern, wohin du sie vertrieben hast wegen ihrer Treulosigkeit, die sie gegen dich begangen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Jehova! Unser ist die Beschämung des Angesichts, unserer Könige, unserer Fürsten und unserer Väter, weil wir gegen dich gesündigt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Des Herrn, unseres Gottes, sind die Erbarmungen und die Vergebungen; denn wir haben uns gegen ihn empört,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'und wir haben der Stimme Jehovas, unseres Gottes, nicht gehorcht, um in seinen Gesetzen zu wandeln, welche er uns durch seine Knechte, die Propheten, vorgelegt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Und ganz Israel hat dein Gesetz übertreten und ist abgewichen, so daß es deiner Stimme nicht gehorcht hat. Und so hat sich der Fluch und der Schwur über uns ergossen, welcher im Gesetz Moses, des Knechtes Gottes, geschrieben steht, weil wir gegen ihn gesündigt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Und er hat seine Worte erfüllt, die er über uns und über unsere Richter geredet hat, welche uns richteten, indem er ein großes Unglück über uns brachte; so daß unter dem ganzen Himmel keines geschehen ist wie dasjenige, welches an Jerusalem geschehen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'So wie es im Gesetz Moses geschrieben steht, ist all dieses Unglück über uns gekommen. Und wir flehten Jehova, unseren Gott, nicht an, daß wir von unseren Missetaten umgekehrt wären und Einsicht erlangt hätten für deine Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Und so hat Jehova über das Unglück gewacht und es über uns kommen lassen. Denn Jehova, unser Gott, ist gerecht in allen seinen Taten, die er getan hat; aber wir haben seiner Stimme nicht gehorcht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Und nun, Herr, unser Gott, der du dein Volk aus dem Lande Ägypten mit starker Hand herausgeführt und dir einen Namen gemacht hast, wie es an diesem Tage ist, wir haben gesündigt, wir haben gesetzlos gehandelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Herr, nach allen deinen Gerechtigkeiten laß doch deinen Zorn und deinen Grimm sich wenden von deiner Stadt Jerusalem, deinem heiligen Berge! Denn wegen unserer Sünden und der Missetaten unserer Väter sind Jerusalem und dein Volk zum Hohne geworden allen denen, die uns umgeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Und nun höre, unser Gott, auf das Gebet deines Knechtes und auf sein Flehen; und um des Herrn willen laß dein Angesicht leuchten über dein verwüstetes Heiligtum!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Neige, mein Gott, dein Ohr und höre! Tue deine Augen auf und sieh unsere Verwüstungen und die Stadt, welche nach deinem Namen genannt ist! Denn nicht um unserer Gerechtigkeiten willen legen wir unser Flehen vor dir nieder, sondern um deiner vielen Erbarmungen willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Herr, höre! Herr, vergib! Herr, merke auf und handle; zögere nicht, um deiner selbst willen, mein Gott! Denn deine Stadt und dein Volk sind nach deinem Namen genannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Während ich noch redete und betete, und meine Sünde und die Sünde meines Volkes Israel bekannte, und mein Flehen vor Jehova, meinem Gott, für den heiligen Berg meines Gottes niederlegte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'während ich noch redete im Gebet, da kam der Mann Gabriel, den ich im Anfang im Gesicht, als ich ganz ermattet war, gesehen hatte, zu mir her zur Zeit des Abendopfers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Und er gab mir Verständnis und redete mit mir und sprach: Daniel, jetzt bin ich ausgegangen, um dich Verständnis zu lehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Im Anfang deines Flehens ist ein Wort ausgegangen, und ich bin gekommen, um es dir kundzutun; denn du bist ein Vielgeliebter. So merke auf das Wort, und verstehe das Gesicht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Siebzig Wochen sind über dein Volk und über deine heilige Stadt bestimmt, um die Übertretung zum Abschluß zu bringen und den Sünden ein Ende zu machen, und die Ungerechtigkeit zu sühnen und eine ewige Gerechtigkeit einzuführen, und Gesicht und Propheten zu versiegeln, und ein Allerheiligstes zu salben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'So wisse denn und verstehe: Vom Ausgehen des Wortes, Jerusalem wiederherzustellen und zu bauen, bis auf den Messias, den Fürsten, sind sieben Wochen und zweiundsechzig Wochen. Straßen und Gräben werden wiederhergestellt und gebaut werden, und zwar in Drangsal der Zeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Und nach den zweiundsechzig Wochen wird der Messias weggetan werden und nichts haben. Und das Volk des kommenden Fürsten wird die Stadt und das Heiligtum zerstören, und das Ende davon wird durch die überströmende Flut sein; und bis ans Ende: Krieg, Festbeschlossenes von Verwüstungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Und er wird einen festen Bund mit den Vielen schließen für eine Woche; und zur Hälfte der Woche wird er Schlachtopfer und Speisopfer aufhören lassen. Und wegen der Beschirmung der Greuel wird ein Verwüster kommen, und zwar bis Vernichtung und Festbeschlossenes über das Verwüstete ausgegossen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Im dritten Jahre Kores\', des Königs von Persien, wurde dem Daniel, welcher Beltsazar genannt wird, eine Sache geoffenbart, und die Sache ist Wahrheit und betrifft eine große Mühsal; und er verstand die Sache und bekam Verständnis über das Gesicht. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'In selbigen Tagen trauerte ich, Daniel, drei volle Wochen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Köstliche Speise aß ich nicht, und weder Fleisch noch Wein kam in meinen Mund; und ich salbte mich nicht, bis drei volle Wochen um waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Und am vierundzwanzigsten Tage des ersten Monats, da war ich am Ufer des großen Stromes, das ist der Hiddekel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Und ich erhob meine Augen und sah: und siehe, da war ein Mann in Linnen gekleidet, und seine Lenden waren umgürtet mit Gold von Uphas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'und sein Leib war wie ein Chrysolith, und sein Angesicht wie das Aussehen des Blitzes, und seine Augen wie Feuerfackeln, und seine Arme und seine Füße wie der Anblick von leuchtendem Erze; und die Stimme seiner Worte war wie die Stimme einer Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Und ich, Daniel, allein sah das Gesicht; die Männer aber, welche bei mir waren, sahen das Gesicht nicht; doch fiel ein großer Schrecken auf sie, und sie flohen und verbargen sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Und ich blieb allein übrig und sah dieses große Gesicht; und es blieb keine Kraft in mir, und meine Gesichtsfarbe verwandelte sich an mir bis zur Entstellung, und ich behielt keine Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Und ich hörte die Stimme seiner Worte; und als ich die Stimme seiner Worte hörte, sank ich betäubt auf mein Angesicht, mit meinem Angesicht zur Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Und siehe, eine Hand rührte mich an und machte, daß ich auf meine Knie und Hände emporwankte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Und er sprach zu mir: Daniel, du vielgeliebter Mann! Merke auf die Worte, die ich zu dir rede, und stehe auf deiner Stelle; denn ich bin jetzt zu dir gesandt. Und als er dieses Wort zu mir redete, stand ich zitternd auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Und er sprach zu mir: Fürchte dich nicht, Daniel! Denn von dem ersten Tage an, da du dein Herz darauf gerichtet hast, Verständnis zu erlangen und dich vor deinem Gott zu demütigen, sind deine Worte erhört worden; und um deiner Worte willen bin ich gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Aber der Fürst des Königreichs Persien stand mir einundzwanzig Tage entgegen; und siehe, Michael, einer der ersten Fürsten, kam, um mir zu helfen, und ich trug daselbst den Sieg davon bei den Königen von Persien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Und ich bin gekommen, um dich verstehen zu lassen, was deinem Volke am Ende der Tage widerfahren wird; denn das Gesicht geht noch auf ferne Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Und als er in dieser Weise mit mir redete, richtete ich mein Angesicht zur Erde und verstummte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Und siehe, einer, den Menschenkindern gleich, berührte meine Lippen; und ich tat meinen Mund auf und redete und sprach zu dem, der vor mir stand: Mein Herr, wegen des Gesichts überfielen mich die Wehen, und ich habe keine Kraft behalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Und wie vermag ein Knecht dieses meines Herrn mit diesem meinem Herrn zu reden? Und ich, von nun an bleibt keine Kraft mehr in mir, und kein Odem ist in mir übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Da rührte mich wiederum einer an, von Aussehen wie ein Mensch, und stärkte mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Und er sprach: Fürchte dich nicht, du vielgeliebter Mann! Friede dir! Sei stark, ja, sei stark! Und als er mit mir redete, fühlte ich mich gestärkt und sprach: Mein Herr möge reden, denn du hast mich gestärkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Da sprach er: Weißt du, warum ich zu dir gekommen bin? Und jetzt werde ich zurückkehren, um mit dem Fürsten von Persien zu streiten; aber wenn ich ausziehe, siehe, so wird der Fürst von Griechenland kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Doch will ich dir kundtun, was in dem Buche der Wahrheit verzeichnet ist. Und es ist kein einziger, der mir wider jene mutig beisteht, als nur Michael, euer Fürst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Und auch ich stand im ersten Jahre Darius\', des Meders, ihm bei als Helfer und Schutz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Und nun will ich dir die Wahrheit kundtun: Siehe, es werden noch drei Könige in Persien aufstehen, und der vierte wird größeren Reichtum erlangen als alle; und wenn er durch seinen Reichtum stark geworden ist, wird er alles gegen das Königreich Griechenland aufregen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Und ein tapferer König wird aufstehen, und er wird mit großer Macht herrschen und nach seinem Gutdünken handeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Und sobald er aufgestanden ist, wird sein Reich zertrümmert und nach den vier Winden des Himmels hin zerteilt werden. Aber nicht für seine Nachkommen wird es sein und nicht nach der Macht, mit welcher er geherrscht hat; denn sein Reich wird zerstört und anderen zuteil werden, mit Ausschluß von jenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Und der König des Südens, und zwar einer von seinen Obersten, wird stark werden. Und einer wird stark werden über ihn hinaus und wird herrschen: seine Herrschaft wird eine große Herrschaft sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Und nach Verlauf von Jahren werden sie sich verbünden; und die Tochter des Königs des Südens wird zu dem König des Nordens kommen, um einen Ausgleich zu bewirken. Aber sie wird die Kraft des Armes nicht behalten, und er wird nicht bestehen noch sein Arm; und sie wird dahingegeben werden, sie und die sie eingeführt haben, und der sie gezeugt, und der sie in jenen Zeiten unterstützt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Doch einer von den Schößlingen ihrer Wurzeln wird an seiner Statt aufstehen; und er wird gegen die Heeresmacht kommen, und wird in die Festungen des Königs des Nordens eindringen und mit ihnen nach Gutdünken verfahren, und wird siegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Und auch wird er ihre Götter samt ihren gegossenen Bildern, samt ihren kostbaren Geräten, Silber und Gold, nach Ägypten in die Gefangenschaft führen; und er wird Jahre lang standhalten vor dem König des Nordens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Und dieser wird in das Reich des Königs des Südens kommen, aber in sein Land zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Aber seine Söhne werden sich zum Kriege rüsten und eine Menge großer Heere zusammenbringen; und einer wird kommen und überschwemmen und überfluten; und er wird wiederkommen, und sie werden Krieg führen bis zu seiner Festung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Und der König des Südens wird sich erbittern, und wird ausziehen und mit ihm, dem König des Nordens, streiten; und dieser wird eine große Menge aufstellen, aber die Menge wird in seine Hand gegeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Und wie die Menge weggenommen wird, wird sein Herz sich erheben; und er wird Zehntausende niederwerfen, aber nicht zu Macht kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Und der König des Nordens wird wiederkommen und eine Menge aufstellen, größer als die frühere; und nach Verlauf der Zeiten von Jahren wird er mit einem großen Heere und mit großer Ausrüstung kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Und in jenen Zeiten werden viele aufstehen gegen den König des Südens; und Gewalttätige deines Volkes werden sich erheben, um das Gesicht zu erfüllen, und werden zu Fall kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Und der König des Nordens wird kommen und einen Wall aufwerfen und eine befestigte Stadt einnehmen; und die Streitkräfte des Südens werden nicht standhalten, selbst sein auserlesenes Volk wird keine Kraft haben, um standzuhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Und der, welcher gegen ihn gekommen ist, wird nach seinem Gutdünken handeln, und niemand wird vor ihm bestehen; und er wird seinen Stand nehmen im Lande der Zierde, und Vertilgung wird in seiner Hand sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Und er wird sein Angesicht darauf richten, mit der Macht seines ganzen Reiches zu kommen, indem er einen Ausgleich im Sinne hat, und er wird ihn bewirken; und er wird ihm eine Tochter der Weiber geben, zu ihrem Verderben; und sie wird nicht bestehen und wird nichts für ihn sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Und er wird sein Angesicht nach den Inseln hinwenden und viele einnehmen; aber ein Feldherr wird seinem Hohne ein Ende machen, dazu noch seinen Hohn ihm zurückgeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Und er wird sein Angesicht nach den Festungen seines Landes hinwenden, und wird straucheln und fallen und nicht mehr gefunden werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Und an seiner Statt wird einer aufstehen, welcher einen Eintreiber der Abgaben durch die Herrlichkeit des Reiches ziehen läßt; aber in wenigen Tagen wird er zerschmettert werden, und zwar weder durch Zorn noch durch Krieg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Und an seiner Statt wird ein Verachteter aufstehen, auf den man nicht die Würde des Königtums legen wird; und er wird unversehens kommen und durch Schmeicheleien sich des Königtums bemächtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Und die überschwemmenden Streitkräfte werden vor ihm überschwemmt und zertrümmert werden, und sogar ein Fürst des Bundes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Denn seitdem er sich mit ihm verbündet hat, wird er Trug üben, und wird hinaufziehen und mit wenig Volk Macht gewinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Unversehens wird er in die fettesten Gegenden der Landschaft eindringen und tun, was weder seine Väter noch die Väter seiner Väter getan haben: Raub und Beute und Gut wird er ihnen zerstreuen und wider die Festungen seine Anschläge ersinnen, und zwar eine Zeitlang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Und er wird seine Kraft und seinen Mut wider den König des Südens erwecken mit einem großen Heere. Und der König des Südens wird sich zum Kriege rüsten mit einem großen und überaus starken Heere; aber er wird nicht bestehen, denn man wird Anschläge wider ihn ersinnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'und die seine Tafelkost essen, werden ihn zerschmettern; und sein Heer wird überschwemmen, und viele Erschlagene werden fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Und die beiden Könige: ihre Herzen werden auf Bosheit bedacht sein, und an einem Tische werden sie Lügen reden; aber es wird nicht gelingen, denn das Ende verzieht sich noch bis zur bestimmten Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Und er wird mit großem Reichtum in sein Land zurückkehren, und sein Herz wird wider den heiligen Bund gerichtet sein; und er wird handeln und in sein Land zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Zur bestimmten Zeit wird er wiederkehren und gegen den Süden ziehen, aber es wird zuletzt nicht sein wie im Anfang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Denn Schiffe von Kittim werden wider ihn kommen; und er wird verzagen und umkehren, und er wird gegen den heiligen Bund ergrimmen und handeln: er wird umkehren und sein Augenmerk auf diejenigen richten, welche den heiligen Bund verlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Und Streitkräfte von ihm werden dastehen; und sie werden das Heiligtum, die Feste, entweihen, und werden das beständige Opfer abschaffen und den verwüstenden Greuel aufstellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Und diejenigen, welche gottlos handeln gegen den Bund, wird er durch Schmeicheleien zum Abfall verleiten; aber das Volk, welches seinen Gott kennt, wird sich stark erweisen und handeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Und die Verständigen des Volkes werden die Vielen unterweisen, aber sie werden fallen durch Schwert und Flamme, durch Gefangenschaft und Raub, eine Zeitlang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Und wenn sie fallen, wird ihnen mit einer kleinen Hilfe geholfen werden; und viele werden sich ihnen mit Heuchelei anschließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Und von den Verständigen werden einige fallen, um sie zu läutern und zu reinigen und weiß zu machen bis zur Zeit des Endes; denn es verzieht sich noch bis zur bestimmten Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Und der König wird nach seinem Gutdünken handeln, und er wird sich erheben und groß machen über jeden Gott, und wider den Gott der Götter wird er Erstaunliches reden; und er wird Gelingen haben, bis der Zorn vollendet ist, denn das Festbeschlossene wird vollzogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Und auf den Gott seiner Väter wird er nicht achten, und weder auf die Sehnsucht der Weiber noch auf irgend einen Gott wird er achten, sondern er wird sich über alles erheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Und an dessen Statt wird er den Gott der Festungen ehren: den Gott, den seine Väter nicht gekannt haben, wird er ehren mit Gold und mit Silber und mit Edelsteinen und mit Kleinodien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Und er wird gegen die starken Festungen so verfahren mit dem fremden Gott: wer ihm Anerkennung zollt, dem wird er viel Ehre erweisen, und er wird ihm Herrschaft verleihen über die Vielen und das Land austeilen zum Lohne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Und zur Zeit des Endes wird der König des Südens mit ihm zusammenstoßen, und der König des Nordens wird gegen ihn anstürmen mit Wagen und mit Reitern und mit vielen Schiffen; und er wird in die Länder eindringen und wird sie überschwemmen und überfluten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Und er wird in das Land der Zierde eindringen, und viele Länder werden zu Fall kommen; diese aber werden seiner Hand entrinnen: Edom und Moab und die Vornehmsten der Kinder Ammon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Und er wird seine Hand an die Länder legen, und das Land Ägypten wird nicht entrinnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'und er wird die Schätze an Gold und Silber und alle Kostbarkeiten Ägyptens in seine Gewalt bringen, und Libyer und Äthiopier werden in seinem Gefolge sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Aber Gerüchte von Osten und von Norden her werden ihn erschrecken; und er wird ausziehen in großem Grimme, um viele zu vernichten und zu vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Und er wird sein Palastgezelt aufschlagen zwischen dem Meere und dem Berge der heiligen Zierde. Und er wird zu seinem Ende kommen, und niemand wird ihm helfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Und in jener Zeit wird Michael aufstehen, der große Fürst, der für die Kinder deines Volkes steht; und es wird eine Zeit der Drangsal sein, dergleichen nicht gewesen ist, seitdem eine Nation besteht bis zu jener Zeit. Und in jener Zeit wird dein Volk errettet werden, ein jeder, der im Buche geschrieben gefunden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Und viele von denen, die im Staube der Erde schlafen, werden erwachen: diese zu ewigem Leben, und jene zur Schande, zu ewigem Abscheu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Und die Verständigen werden leuchten wie der Glanz der Himmelsfeste, und die, welche die Vielen zur Gerechtigkeit weisen, wie die Sterne, immer und ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Und du, Daniel, verschließe die Worte und versiegele das Buch bis zur Zeit des Endes. Viele werden es durchforschen, und die Erkenntnis wird sich mehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Und ich, Daniel, sah: und siehe, zwei andere standen da, einer hier am Ufer des Stromes, und einer dort am Ufer des Stromes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Und einer sprach zu dem in Linnen gekleideten Mann, welcher oben über dem Wasser des Stromes war: Wie lange wird dauern das Ende dieser wunderbaren Dinge?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Und ich hörte den in Linnen gekleideten Mann, welcher oben über dem Wasser des Stromes war, und er erhob seine Rechte und seine Linke zum Himmel und schwur bei dem, der ewig lebt: Eine Zeit, Zeiten und eine halbe Zeit; und wenn die Zerschmetterung der Kraft des heiligen Volkes vollbracht sein wird, dann werden alle diese Dinge vollendet sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Und ich hörte es, aber ich verstand es nicht; und ich sprach: Mein Herr, was wird der Ausgang von diesem sein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Und er sprach: Gehe hin, Daniel; denn die Worte sollen verschlossen und versiegelt sein bis zur Zeit des Endes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Viele werden sich reinigen und weiß machen und läutern, aber die Gottlosen werden gottlos handeln; und keine der Gottlosen werden es verstehen, die Verständigen aber werden es verstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Und von der Zeit an, da das beständige Opfer abgeschafft wird, und zwar um den verwüstenden Greuel aufzustellen, sind tausend zweihundertneunzig Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Glückselig der, welcher harrt und tausend dreihundertfünfunddreißig Tage erreicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Du aber gehe hin bis zum Ende; und du wirst ruhen, und wirst auferstehen zu deinem Lose am Ende der Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Das Wort Jehovas, welches zu Hosea, dem Sohne Beeris, geschah in den Tagen Ussijas, Jothams, Ahas\', Hiskias, der Könige von Juda, und in den Tagen Jerobeams, des Sohnes Joas\', des Königs von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Als Jehova anfing mit Hosea zu reden, da sprach Jehova zu Hosea: Gehe hin, nimm dir ein Hurenweib und Hurenkinder; denn das Land treibt beständig Hurerei, von Jehova hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Und er ging hin und nahm Gomer, die Tochter Diblaims; und sie ward schwanger und gebar ihm einen Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Und Jehova sprach zu ihm: Gib ihm den Namen Jisreel; denn noch um ein Kleines, so werde ich die Blutschuld von Jisreel an dem Hause Jehus heimsuchen und dem Königtum des Hauses Israel ein Ende machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Und es wird geschehen an jenem Tage, da werde ich den Bogen Israels zerbrechen im Tale Jisreel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Und sie ward wiederum schwanger und gebar eine Tochter. Und er sprach zu ihm: Gib ihr den Namen Lo-Ruchama; denn ich werde mich fortan des Hauses Israel nicht mehr erbarmen, daß ich ihnen irgendwie vergebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Aber des Hauses Juda werde ich mich erbarmen und sie retten durch Jehova, ihren Gott; und nicht werde ich sie retten durch Bogen und durch Schwert und durch Krieg, durch Rosse und durch Reiter. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Und sie entwöhnte die Lo-Ruchama. Und sie ward schwanger und gebar einen Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Und er sprach: Gib ihm den Namen Lo-Ammi; denn ihr seid nicht mein Volk, und ich, ich will nicht euer sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Doch die Zahl der Kinder Israel wird sein wie der Sand des Meeres, der nicht gemessen und nicht gezählt werden kann; und es wird geschehen, an dem Orte, wo zu ihnen gesagt wurde: Ihr seid nicht mein Volk, wird zu ihnen gesagt werden: Kinder des lebendigen Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Und die Kinder Juda und die Kinder Israel werden sich miteinander versammeln, und sich ein Haupt setzen und aus dem Lande heraufziehen; denn groß ist der Tag von Jisreel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Sprechet zu euren Brüdern: Mein Volk, und zu euren Schwestern: Begnadigte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Rechtet mit eurer Mutter, rechtet! denn sie ist nicht mein Weib, und ich bin nicht ihr Mann. Damit sie ihre Hurerei von ihrem Angesicht wegtue und ihren Ehebruch zwischen ihren Brüsten hinweg:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'auf daß ich sie nicht nackt ausziehe und sie hinstelle wie an dem Tage, da sie geboren wurde, und ich sie der Wüste gleich mache und sie setze wie ein dürres Land und sie sterben lasse vor Durst. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Und ihrer Kinder werde ich mich nicht erbarmen, weil sie Hurenkinder sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Denn ihre Mutter hat gehurt, ihre Gebärerin hat Schande getrieben; denn sie sprach: Ich will meinen Buhlen nachgehen, die mir mein Brot und mein Wasser geben, meine Wolle und meinen Flachs, mein Öl und mein Getränk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Darum siehe, ich will deinen Weg mit Dornen verzäunen, und ich will ihr eine Mauer errichten, daß sie ihre Pfade nicht finden soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Und sie wird ihren Buhlen nachlaufen und sie nicht erreichen, und sie wird sie suchen und nicht finden; und sie wird sagen: Ich will hingehen und zu meinem ersten Manne zurückkehren, denn damals ging es mir besser als jetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Und sie erkannte nicht, daß ich ihr das Korn und den Most und das Öl gab, und ihr Silber und Gold mehrte, was sie für den Baal verwendet haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Darum werde ich mein Korn zurücknehmen zu seiner Zeit, und meinen Most zu seiner bestimmten Zeit, und werde ihr meine Wolle und meinen Flachs entreißen, die ihre Blöße bedecken sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Und nun werde ich ihre Schande aufdecken vor den Augen ihrer Buhlen, und niemand wird sie aus meiner Hand erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Und ich werde all ihrer Freude, ihren Festen, ihren Neumonden und ihren Sabbathen und allen ihren Festzeiten ein Ende machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Und ich werde ihren Weinstock und ihren Feigenbaum verwüsten, von welchen sie sagte: Diese sind mein Lohn, den mir meine Buhlen gegeben haben. Und ich werde dieselben zu einem Walde machen, und die Tiere des Feldes werden sie abfressen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Und ich werde an ihr die Tage der Baalim heimsuchen, da sie denselben räucherte und sich mit ihren Ohrringen und ihrem Halsgeschmeide schmückte und ihren Buhlen nachging; mich aber hat sie vergessen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Darum siehe, ich werde sie locken und sie in die Wüste führen und ihr zum Herzen reden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'und ich werde ihr von dort aus ihre Weinberge geben, und das Tal Achor zu einer Tür der Hoffnung. Und sie wird daselbst singen wie in den Tagen ihrer Jugend, und wie an dem Tage, da sie aus dem Lande Ägypten heraufzog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Und es wird geschehen an jenem Tage, spricht Jehova, da wirst du mich nennen: Mein Mann; und du wirst mich nicht mehr nennen: Mein Baal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Und ich werde die Namen der Baalim aus ihrem Munde hinwegtun, und sie werden nicht mehr mit ihrem Namen erwähnt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Und ich werde an jenem Tage einen Bund für sie schließen mit den Tieren des Feldes und mit den Vögeln des Himmels und mit den kriechenden Tieren der Erde; und ich werde Bogen und Schwert und den Krieg aus dem Lande zerbrechen und werde sie in Sicherheit wohnen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Und ich will dich mir verloben in Ewigkeit, und ich will dich mir verloben in Gerechtigkeit und in Gericht, und in Güte und in Barmherzigkeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'und ich will dich mir verloben in Treue; und du wirst Jehova erkennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Und es wird geschehen an jenem Tage, da werde ich erhören, spricht Jehova: ich werde den Himmel erhören, und dieser wird die Erde erhören;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'und die Erde wird erhören das Korn und den Most und das Öl; und sie, sie werden Jisreel erhören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Und ich will sie mir säen in dem Lande und will mich der Lo-Ruchama erbarmen. Und ich will zu Lo-Ammi sagen: Du bist mein Volk; und es wird sagen: Mein Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Und Jehova sprach zu mir: Geh wiederum hin, liebe ein Weib, das von ihrem Freunde geliebt wird und Ehebruch treibt: wie Jehova die Kinder Israel liebt, welche sich aber zu anderen Göttern hinwenden und Traubenkuchen lieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Und ich kaufte sie mir für fünfzehn Silbersekel und einen Homer Gerste und einen Letech Gerste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Und ich sprach zu ihr: Du sollst mir viele Tage also bleiben, du sollst nicht huren und keines Mannes sein; und so werde auch ich dir gegenüber tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Denn die Kinder Israel werden viele Tage ohne König bleiben und ohne Fürsten, und ohne Schlachtopfer und ohne Bildsäule, und ohne Ephod und Teraphim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Danach werden die Kinder Israel umkehren und Jehova, ihren Gott, und David, ihren König, suchen; und sie werden sich zitternd wenden zu Jehova und zu seiner Güte am Ende der Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Höret das Wort Jehovas, ihr Kinder Israel! Denn Jehova hat einen Rechtsstreit mit den Bewohnern des Landes; denn es ist keine Wahrheit und keine Güte und keine Erkenntnis Gottes im Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Schwören und Lügen, und Morden und Stehlen, und Ehebruchtreiben; sie brechen ein, und Blutschuld reiht sich an Blutschuld.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Darum trauert das Land und verschmachtet alles, was darin wohnt, sowohl die Tiere des Feldes als auch die Vögel des Himmels; und auch die Fische des Meeres werden hinweggerafft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Doch niemand rechte und niemand tadle! Ist doch dein Volk wie die, welche mit dem Priester rechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Und du wirst fallen bei Tage, und auch der Prophet wird mit dir fallen bei Nacht; und ich werde deine Mutter vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Mein Volk wird vertilgt aus Mangel an Erkenntnis; weil du die Erkenntnis verworfen hast, so verwerfe ich dich, daß du mir nicht mehr Priesterdienst ausübest; und du hast das Gesetz deines Gottes vergessen: so werde auch ich deine Kinder vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Je mehr ihrer geworden sind, desto mehr haben sie gegen mich gesündigt: ich werde ihre Herrlichkeit in Schande verwandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Sie essen die Sünde meines Volkes und verlangen nach seiner Missetat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Und so wird, wie das Volk, der Priester sein, und ich werde ihre Wege an ihnen heimsuchen und ihre Handlungen ihnen vergelten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'und sie werden essen und nicht satt werden. Sie treiben Hurerei, aber sie werden sich nicht ausbreiten; denn sie haben es aufgegeben, auf Jehova zu achten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Hurerei, Wein und Most nehmen den Verstand weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Mein Volk befragt sein Holz, und sein Stab tut es ihm kund; denn der Geist der Hurerei hat es irregeführt, und, ihren Gott verlassend, huren sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Sie opfern auf den Gipfeln der Berge und räuchern auf den Hügeln, unter Eiche und Pappel und Terebinthe, weil ihr Schatten gut ist; darum huren eure Töchter und treiben eure Schwiegertöchter Ehebruch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Ich werde es an euren Töchtern nicht heimsuchen, daß sie huren, und an euren Schwiegertöchtern, daß sie Ehebruch treiben; denn sie selbst gehen mit den Huren beiseite und opfern mit den Buhldirnen; und das Volk, das keinen Verstand hat, kommt zu Fall.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Wenn du hurst, Israel, so verschulde sich Juda nicht! Und kommet nicht nach Gilgal und ziehet nicht hinauf nach Beth-Awen, und schwöret nicht: So wahr Jehova lebt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Denn Israel ist widerspenstig geworden wie eine widerspenstige Kuh; nun wird Jehova sie weiden wie ein Lamm in weitem Raume.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Ephraim ist mit Götzen verbündet; laß ihn gewähren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Ihr Zechgelage ist ausgeartet: der Hurerei geben sie sich hin; leidenschaftlich lieben seine Fürsten die Schande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Der Wind hat ihn in seine Flügel geschlossen, und sie werden beschämt werden wegen ihrer Opfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Höret dieses, ihr Priester, und merket auf, Haus Israel! und ihr, Haus des Königs, nehmet es zu Ohren! Denn euch gilt das Gericht; denn ihr seid eine Schlinge zu Mizpa geworden und ein ausgebreitetes Netz auf Tabor;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'und im Verderbthandeln haben es die Abtrünnigen weit getrieben. Ich aber werde sie alle züchtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Ich kenne Ephraim wohl, und Israel ist nicht vor mir verborgen; denn nun hast du Hurerei getrieben, Ephraim, Israel hat sich verunreinigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Ihre Handlungen gestatten ihnen nicht, zu ihrem Gott umzukehren; denn der Geist der Hurerei ist in ihrem Innern, und Jehova kennen sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Und die Hoffart Israels zeugt ihm ins Angesicht, und Israel und Ephraim werden fallen durch ihre Ungerechtigkeit; auch Juda fällt mit ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Mit ihrem Kleinvieh und mit ihren Rindern werden sie hingehen, um Jehova zu suchen, und werden ihn nicht finden: er hat sich ihnen entzogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Sie haben treulos gegen Jehova gehandelt, denn sie haben fremde Kinder gezeugt; nun wird sie der Neumond verzehren mit ihren Erbteilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Stoßet in die Posaune zu Gibea, in die Trompete zu Rama; rufet laut zu Beth-Awen: Der Feind hinter dir her, Benjamin!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Ephraim wird zur Wüste werden am Tage der Strafe; über die Stimme Israels habe ich Gewisses verkündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Die Fürsten von Juda sind wie diejenigen geworden, welche die Grenze verrücken; über sie werde ich meinen Grimm ausgießen wie Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Ephraim ist bedrückt, zerschlagen vom Gericht; denn willig wandelte es nach Menschengeboten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Und ich werde für Ephraim wie die Motte sein, und für das Haus Juda wie der Wurmfraß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Und Ephraim sah seine Krankheit, und Juda sein Geschwür; und Ephraim ging nach Assyrien und sandte zu dem König Jareb; der aber vermag euch nicht zu heilen und wird euer Geschwür nicht vertreiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Denn ich werde für Ephraim wie ein Löwe sein, und für das Haus Juda wie ein junger Löwe. Ich, ich werde zerreißen und davongehen; ich werde wegtragen, und niemand wird erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Ich werde davongehen, an meinen Ort zurückkehren, bis sie ihre Schuld büßen und mein Angesicht suchen. In ihrer Bedrängnis werden sie mich eifrig suchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, '\"Kommt und laßt uns zu Jehova umkehren; denn er hat zerrissen und wird uns heilen, er hat geschlagen und wird uns verbinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Er wird uns nach zwei Tagen wieder beleben, am dritten Tage uns aufrichten; und so werden wir vor seinem Angesicht leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'So laßt uns Jehova erkennen, ja, laßt uns trachten nach seiner Erkenntnis! Sein Hervortreten ist sicher wie die Morgendämmerung; und er wird für uns kommen wie der Regen, wie der Spätregen die Erde benetzt.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Was soll ich dir tun, Ephraim, was soll ich dir tun, Juda, da eure Frömmigkeit wie die Morgenwolke ist und wie der Tau, der früh verschwindet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Darum habe ich sie behauen durch die Propheten, habe sie getötet durch die Worte meines Mundes; und mein Gericht geht hervor wie das Licht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Denn an Frömmigkeit habe ich Gefallen und nicht am Schlachtopfer, und an der Erkenntnis Gottes mehr als an Brandopfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Sie aber haben den Bund übertreten wie Adam, haben dort treulos gegen mich gehandelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gilead ist eine Stadt von Übeltätern, voll Blutspuren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Und wie ein Straßenräuber auflauert, so die Rotte der Priester; sie morden auf dem Wege nach Sichem, ja, sie verüben Schandtat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Im Hause Israel habe ich Schauderhaftes gesehen: daselbst ist Ephraims Hurerei, Israel hat sich verunreinigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Auch über dich, Juda, ist eine Ernte verhängt, wenn ich die Gefangenschaft meines Volkes wenden werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Sobald ich Israel heilen will, werden die Ungerechtigkeit Ephraims und die Bosheiten Samarias offenbar; denn sie üben Falschheit, und der Dieb dringt ein, draußen raubt die Streifschar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Und sie sprechen nicht in ihrem Herzen, daß ich all ihrer Bosheit gedenke; nun haben ihre Handlungen sie umringt, sie stehen vor meinem Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Mit ihrer Bosheit erfreuen sie den König und mit ihren Lügen die Fürsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Sie sind Ehebrecher allesamt, gleich einem Ofen, vom Bäcker geheizt, der zu schüren aufhört vom Kneten des Teiges an bis zu seiner Gärung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Am Tage unseres Königs machen sich die Fürsten krank von der Glut des Weines; er streckt seine Hand aus mit den Spöttern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Denn sie haben ihr Herz wie einen Ofen ihrer Arglist nahe gebracht; ihr Bäcker schläft die ganze Nacht; am Morgen brennt jener wie ein flammendes Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Sie allesamt glühen wie ein Ofen und verzehren ihre Richter. Alle ihre Könige sind gefallen; niemand unter ihnen ruft mich an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Ephraim vermischt sich mit den Völkern; Ephraim ist wie ein Kuchen geworden, der nicht umgewendet ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Fremde haben seine Kraft verzehrt, und er weiß es nicht; auch ist graues Haar auf sein Haupt gesprengt, und er weiß es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Und die Hoffart Israels zeugt ihm ins Angesicht; und sie kehren nicht um zu Jehova, ihrem Gott, und bei alledem suchen sie ihn nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Und Ephraim ist wie eine einfältige Taube geworden, ohne Verstand; sie rufen Ägypten an, sie gehen nach Assyrien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Sobald sie hingehen, werde ich mein Netz über sie ausbreiten, wie das Gevögel des Himmels werde ich sie herniederziehen. Ich werde sie züchtigen gemäß dem, was ihrer Gemeinde verkündigt worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Wehe ihnen! Denn sie sind von mir geflohen; Zerstörung über sie! Denn sie sind von mir abgefallen. Und ich möchte sie erlösen, sie aber reden Lügen über mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Und sie schreien nicht zu mir in ihrem Herzen, sondern sie heulen auf ihren Lagern; um Korn und Most scharen sie sich; sie weichen ab und wenden sich gegen mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Und ich, ich hatte ihre Arme unterwiesen und gestärkt, aber sie ersinnen Böses gegen mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Sie wenden sich um, doch nicht nach oben: sie sind wie ein trüglicher Bogen geworden. Ihre Fürsten werden durchs Schwert fallen wegen der Wut ihrer Zunge: das wird ihre Verspottung sein im Lande Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Die Posaune an deinen Mund! Wie ein Adler stürzt er auf das Haus Jehovas, weil sie meinen Bund übertreten und gegen mein Gesetz gefrevelt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Sie werden zu mir schreien: Mein Gott, wir kennen dich, wir, Israel!...');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Israel hat das Gute verworfen: der Feind verfolge es!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Sie haben Könige gemacht, aber nicht von mir aus; sie haben Fürsten eingesetzt, und ich wußte es nicht. Von ihrem Silber und von ihrem Golde haben sie sich Götzenbilder gemacht, damit es vernichtet werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Er hat dein Kalb verworfen, Samaria: mein Zorn ist wider sie entbrannt. Bis wann sind sie der Reinheit unfähig?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Denn auch dieses ist von Israel; ein Künstler hat es gemacht, und es ist kein Gott, denn das Kalb Samarias wird zu Stücken werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Denn Wind säen sie, und Sturm ernten sie; Halme hat es nicht, das Ausgesproßte bringt kein Mehl; wenn es auch Mehl brächte, so würden Fremde es verschlingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Israel ist verschlungen; nun sind sie unter den Nationen wie ein Gefäß geworden, an welchem man kein Gefallen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Denn sie sind nach Assyrien hinaufgezogen. Der Wildesel bleibt für sich allein, aber Ephraim hat Buhlen gedungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Ob sie auch unter den Nationen dingen, nun will ich sie sammeln; und sie werden anfangen, sich zu vermindern wegen der Last des Königs der Fürsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Denn Ephraim hat die Altäre vermehrt zur Versündigung, und die Altäre sind ihm zur Versündigung geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Ich schreibe ihm zehntausend Satzungen meines Gesetzes vor: wie Fremdes werden sie geachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Als Schlachtopfer meiner Opfergaben opfern sie Fleisch und essen es; Jehova hat kein Wohlgefallen an denselben. Nun wird er ihrer Ungerechtigkeit gedenken und ihre Sünden heimsuchen: sie werden nach Ägypten zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Und Israel hat den vergessen, der es gemacht, und hat Paläste gebaut, und Juda hat die festen Städte vermehrt; aber ich werde ein Feuer in seine Städte senden, welches seine Schlösser verzehren wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Freue dich nicht, Israel, bis zum Frohlocken, wie die Völker; denn du hast von deinem Gott weg gehurt, hast Buhlerlohn geliebt auf allen Korntennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Tenne und Kelter werden sie nicht ernähren, und der Most wird sie täuschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Sie werden nicht im Lande Jehovas bleiben, sondern Ephraim wird nach Ägypten zurückkehren, und sie werden Unreines essen in Assyrien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Sie werden Jehova keinen Wein spenden, und ihre Schlachtopfer werden ihm nicht angenehm sein: wie Trauerspeise wird es ihnen sein; alle, die davon essen, werden sich verunreinigen; denn für ihren Hunger wird ihre Speise sein, in das Haus Jehovas wird sie nicht kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Was werdet ihr tun am Tage der Feier und am Tage des Festes Jehovas?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Denn siehe, sie sind weggezogen wegen der Zerstörung; Ägypten wird sie sammeln, Moph sie begraben; ihre Kostbarkeiten an Silber werden die Nesseln in Besitz nehmen, Dornen werden in ihren Zelten sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Gekommen sind die Tage der Heimsuchung, gekommen die Tage der Vergeltung; Israel wird es erfahren. Der Prophet wird närrisch, der Mann des Geistes wahnsinnig, wegen der Größe deiner Ungerechtigkeit und der großen Feindseligkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Ephraim schaut nach Offenbarungen aus neben meinem Gott; der Prophet, eines Vogelstellers Schlinge ist auf allen seinen Wegen, Feindseligkeit ist im Hause seines Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Tief haben sie sich verderbt wie in den Tagen von Gibea. Er wird ihrer Ungerechtigkeit gedenken, er wird ihre Sünden heimsuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Ich fand Israel wie Trauben in der Wüste; wie eine Frühfrucht am Feigenbaum, in seinem ersten Triebe, ersah ich eure Väter. Sie aber gingen nach Baal-Peor und weihten sich der Schande, und sie wurden Greuel wie ihr Buhle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Ephraim, dem Vogel gleich wird ihre Herrlichkeit wegfliegen. Kein Gebären und keine Schwangerschaft und keine Empfängnis:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'ja, wenn sie auch ihre Söhne groß ziehen, so werde ich sie doch derselben berauben, so daß kein Mann mehr bleibt; denn wehe ihnen, wenn ich von ihnen weichen werde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Ephraim, wie ich hinschaute, war ein Tyrus, auf der Aue gepflanzt; aber Ephraim muß seine Söhne zum Würger hinausbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Gib ihnen, Jehova; was wirst du ihnen geben? Gib ihnen einen unfruchtbaren Mutterleib und trockene Brüste!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Alle ihre Bosheit ist zu Gilgal, denn daselbst habe ich sie gehaßt. Wegen der Bosheit ihrer Handlungen werde ich sie aus meinem Hause vertreiben; ich werde sie nicht mehr lieben; alle ihre Fürsten sind Abtrünnige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Ephraim ist geschlagen: ihre Wurzel ist verdorrt, sie werden keine Frucht bringen; selbst wenn sie gebären, werde ich die Lieblinge ihres Leibes töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Mein Gott verwirft sie, weil sie nicht auf ihn gehört haben; und sie sollen Flüchtlinge sein unter den Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Israel ist ein wuchernder Weinstock, der seine Frucht ansetzte; nach der Menge seiner Frucht hat er die Altäre vermehrt, nach der Güte seines Landes haben sie die Bildsäulen verschönert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Gleißnerisch war ihr Herz, nun werden sie es büßen: er wird ihre Altäre zertrümmern, ihre Bildsäulen zerstören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Ja, nun werden sie sagen: Wir haben keinen König; denn wir haben Jehova nicht gefürchtet, und der König, was wird er für uns tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Sie haben eitle Worte geredet, falsch geschworen, Bündnisse geschlossen: so wird das Gericht sprossen wie Giftkraut in den Furchen des Feldes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Sie Bewohner von Samaria werden bange sein für das Kalb von Beth-Awen; ja, sein Volk wird über dasselbe trauern, und seine Götzenpriester werden seinetwegen beben, wegen seiner Herrlichkeit, weil sie von ihm fortgezogen ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'auch dieses wird nach Assyrien gebracht werden als Geschenk für den König Jareb. Scham wird Ephraim ergreifen, und Israel wird zu Schanden werden wegen seines Ratschlags.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Dahin ist Samaria und sein König, wie ein Splitter auf des Wassers Fläche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Und die Höhen von Awen, die Sünde Israels, werden vertilgt werden; Dornen und Disteln werden über ihre Altäre wachsen. Und sie werden zu den Bergen sagen: Bedecket uns! und zu den Hügeln: Fallet auf uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Seit den Tagen von Gibea hast du gesündigt, Israel: dort sind sie stehen geblieben; nicht erreichte sie zu Gibea der Streit wider die Kinder des Frevels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Nach meiner Lust werde ich sie züchtigen, und Völker werden gegen sie versammelt werden, wenn ich sie an ihre beiden Sünden binden werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Und Ephraim ist eine ans Joch gewöhnte junge Kuh, die zu dreschen liebt; und ich, ich bin über die Schönheit ihres Halses hergefahren: ich werde Ephraim einspannen, Juda soll pflügen, Jakob soll eggen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Säet euch zur Gerechtigkeit, erntet der Güte gemäß; pflüget euch einen Neubruch: denn es ist Zeit, Jehova zu suchen, bis er komme und euch Gerechtigkeit regnen lasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Ihr habt Gesetzlosigkeit gepflügt, Unrecht geerntet, die Frucht der Lüge gegessen; denn du hast auf deinen Weg vertraut, auf die Menge deiner Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Und es wird sich ein Getümmel erheben unter deinen Völkern, und alle deine Festen werden zerstört werden, wie Schalman Beth-Arbel zerstörte am Tage des Krieges; die Mutter samt den Kindern wurde zerschmettert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Also hat Bethel euch getan um der Bosheit eurer Bosheit willen: mit dem Morgenrot wird Israels König gänzlich vernichtet sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Als Israel jung war, da liebte ich es, und aus Ägypten habe ich meinen Sohn gerufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'So oft sie ihnen riefen, gingen sie von ihrem Angesicht hinweg: sie opferten den Baalim und räucherten den geschnitzten Bildern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Und ich, ich gängelte Ephraim, er nahm sie auf seine Arme aber sie erkannten nicht, daß ich sie heilte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Mit Menschenbanden zog ich sie, mit Seilen der Liebe; und ich ward ihnen wie solche, die das Joch auf ihren Kinnbacken emporheben, und sanft gegen sie, gab ich ihnen Speise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Es wird nicht nach dem Lande Ägypten zurückkehren; sondern der Assyrer, der wird sein König sein, weil sie sich geweigert haben umzukehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Und das Schwert wird kreisen in seinen Städten und seine Riegel vernichten, und wird fressen um ihrer Ratschläge willen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'denn mein Volk hängt an dem Abfall von mir, und ruft man es nach oben, keiner von ihnen erhebt sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Wie sollte ich dich hingeben, Ephraim, dich überliefern, Israel? Wie sollte ich dich wie Adama machen, wie Zeboim dich setzen? Mein Herz hat sich in mir umgewendet, erregt sind alle meine Erbarmungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Nicht will ich ausführen die Glut meines Zornes, nicht wiederum Ephraim verderben; denn ich bin Gott und nicht ein Mensch, der Heilige in deiner Mitte, und ich will nicht in Zornesglut kommen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Sie werden Jehova nachwandeln: wie ein Löwe wird er brüllen; denn er wird brüllen, und zitternd werden die Kinder herbeieilen vom Meere;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'wie Vögel werden sie zitternd herbeieilen aus Ägypten und wie Tauben aus dem Lande Assyrien; und ich werde sie in ihren Häusern wohnen lassen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, '(H12:1) Mit Lüge hat Ephraim mich umringt, und das Haus Israel mit Trug; und Juda ist immer noch zügellos gegen Gott und gegen den Heiligen, der treu ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, '(H12:2) Ephraim weidet sich an Wind und jagt dem Ostwinde nach; den ganzen Tag mehrt es Lüge und Gewalttat; und sie schließen einen Bund mit Assyrien, und Öl wird nach Ägypten gebracht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, '(H12:3) Auch mit Juda hat Jehova einen Rechtsstreit; und er wird Jakob heimsuchen nach seinen Wegen, nach seinen Handlungen ihm vergelten. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, '(H12:4) Im Mutterleibe hielt er seines Bruders Ferse, und in seiner Manneskraft kämpfte er mit Gott:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, '(H12:5) er kämpfte mit dem Engel und überwand, er weinte und flehte zu ihm; zu Bethel fand er ihn, und daselbst redete er mit uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, '(H12:6) Und Jehova, der Gott der Heerscharen, Jehova ist sein Gedenkname.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, '(H12:7) Du denn, kehre um zu deinem Gott; bewahre Güte und Recht, und hoffe beständig auf deinen Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, '(H12:8) Ein Kaufmann ist er; in seiner Hand ist eine Waage des Betrugs, er liebt zu übervorteilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, '(H12:9) Und Ephraim spricht: ich bin doch reich geworden, habe mir Vermögen erworben; in all meinem Erwerb wird man mir keine Ungerechtigkeit nachweisen, welche Sünde wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, '(H12:10) Ich aber bin Jehova, dein Gott, vom Lande Ägypten her; ich werde dich wieder in Zelten wohnen lassen wie in den Tagen der Festfeier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, '(H12:11) Und ich habe zu den Propheten geredet, ja, ich habe Gesichte vermehrt und durch die Propheten in Gleichnissen geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, '(H12:12) Wenn Gilead Frevel ist, so werden sie nur Nichtiges werden. In Gilgal opferten sie Stiere; so werden auch ihre Altäre wie Steinhaufen sein auf den Furchen des Feldes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, '(H12:13) Und Jakob entfloh nach dem Gefilde von Aram, und Israel diente um ein Weib und hütete um ein Weib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, '(H12:14) Und Jehova führte Israel durch einen Propheten aus Ägypten herauf, und durch einen Propheten wurde es gehütet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, '(H12:15) Ephraim erzürnte ihn bitterlich, und sein Herr wird seine Blutschuld auf ihm lassen und seine Schmähung ihm vergelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Wenn Ephraim redete, war Schrecken; es erhob sich in Israel. Aber es verschuldete sich durch Baal und starb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Und nun fahren sie fort zu sündigen und machen sich von ihrem Silber gegossene Bilder, Götzenbilder nach ihrem Verstande, allesamt ein Werk der Künstler; von eben diesen sagt man: Die Menschen, welche opfern, küssen die Kälber!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Darum werden sie sein wie die Morgenwolke und wie der Tau, der früh verschwindet, wie Spreu, welche von der Tenne dahinfliegt, und wie Rauch aus dem Gitter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Ich aber bin Jehova, dein Gott, vom Lande Ägypten her; und du kennst keinen Gott außer mir, und da ist kein Retter als ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Ich habe dich ja gekannt in der Wüste, in dem Lande der Gluten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Ihrer Weide gemäß wurden sie satt, sie wurden satt, und ihr Herz erhob sich; darum haben sie mich vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Und so wurde ich ihnen wie ein Löwe; wie ein Pardel laure ich am Wege;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'ich werde sie anfallen wie eine Bärin, welche der Jungen beraubt ist, und werde den Verschluß ihres Herzens zerreißen; und ich werde sie daselbst verzehren wie ein Löwe; die Tiere des Feldes werden sie zerfleischen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Es hat dich zu Grunde gerichtet, Israel, daß du wider mich, wider deine Hilfe, bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Wo ist nun dein König, daß er dich rette in allen deinen Städten, und wo deine Richter, von welchen du sagtest: Gib mir einen König und Fürsten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Ich gab dir einen König in meinem Zorn, und nahm ihn weg in meinem Grimm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Die Ungerechtigkeit Ephraims ist zusammengebunden, aufbewahrt seine Sünde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Wehen einer Gebärenden werden ihn ankommen. Er ist ein unweiser Sohn; denn wenn es Zeit ist, tritt er nicht ein in den Durchbruch der Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Von Gewalt des Scheols werde ich sie erlösen, vom Tode sie befreien! Wo sind, o Tod, deine Seuchen? Wo ist, o Scheol, dein Verderben? Reue ist vor meinen Augen verborgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Denn er wird Frucht tragen unter den Brüdern. Ein Ostwind wird kommen, ein Wind Jehovas, von der Wüste heraufsteigend, und sein Born wird vertrocknen und sein Quell versiegen; er wird die Schatzkammer aller kostbaren Geräte plündern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Samaria wird büßen, denn es ist widerspenstig gewesen gegen seinen Gott; sie werden durchs Schwert fallen, ihre Kinder werden zerschmettert und ihre Schwangeren aufgeschlitzt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Kehre um, Israel, bis zu Jehova, deinem Gott, denn du bist gefallen durch deine Ungerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Nehmet Worte mit euch und kehret um zu Jehova; sprechet zu ihm: Vergib alle Ungerechtigkeit, und nimm an, was gut ist, daß wir die Frucht unserer Lippen als Schlachtopfer darbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Assyrien wird uns nicht retten; auf Rossen wollen wir nicht reiten, und zu dem Machwerk unserer Hände nicht mehr sagen: Unser Gott! Denn die Waise findet Erbarmen bei dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Ich will ihre Abtrünnigkeit heilen, will sie willig lieben; denn mein Zorn hat sich von ihm abgewendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Ich werde für Israel sein wie der Tau: blühen soll es wie die Lilie, und Wurzel schlagen wie der Libanon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Seine Schößlinge sollen sich ausbreiten, und seine Pracht soll sein wie der Olivenbaum, und sein Geruch wie der Libanon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Die unter seinem Schatten Wohnenden sollen wiederum Getreide hervorbringen, und blühen wie ein Weinstock, dessen Ruf wie der Wein des Libanon ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Ephraim wird sagen: Was habe ich fortan mit den Götzen zu schaffen? Ich, ich habe ihn erhört und auf ihn geblickt. Ich bin wie eine grünende Zypresse. Aus mir wird deine Frucht gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Wer weise ist, der wird dieses verstehen; wer verständig ist, der wird es erkennen. Denn die Wege Jehovas sind gerade, und die Gerechten werden darauf wandeln; die Abtrünnigen aber werden darauf fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Das Wort Jehovas, welches zu Joel, dem Sohne Pethuels, geschah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Höret dieses, ihr Alten, und nehmet es zu Ohren, alle ihr Bewohner des Landes! Ist solches in euren Tagen geschehen oder in den Tagen eurer Väter?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Erzählet davon euren Kindern, und eure Kinder ihren Kindern, und ihre Kinder dem folgenden Geschlecht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Was der Nager übriggelassen hatte, fraß die Heuschrecke; und was die Heuschrecke übriggelassen, fraß der Abfresser; und was der Abfresser übriggelassen, fraß der Vertilger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Wachet auf, ihr Trunkenen, und weinet! Und heulet, alle ihr Weinsäufer, über den Most, weil er weggenommen ist von eurem Munde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Denn eine Nation ist über mein Land heraufgezogen, mächtig und ohne Zahl; ihre Zähne sind Löwenzähne, und sie hat das Gebiß einer Löwin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Sie hat meinen Weinstock zu einer Wüste gemacht und meinen Feigenbaum zerknickt; sie hat ihn gänzlich abgeschält und hingeworfen, seine Ranken sind weiß geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Wehklage wie eine Jungfrau, die mit Sacktuch umgürtet ist wegen des Gatten ihrer Jugend!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Speisopfer und Trankopfer sind weggenommen vom Hause Jehovas; es trauern die Priester, die Diener Jehovas. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Das Feld ist verwüstet, es trauert der Erdboden; denn das Korn ist verwüstet, der Most ist vertrocknet, verwelkt das Öl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Seid beschämt, ihr Ackersleute, heulet, ihr Winzer, über den Weizen und über die Gerste! Denn die Ernte des Feldes ist zu Grunde gegangen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'der Weinstock ist verdorrt und der Feigenbaum verwelkt; Granate, auch Palme und Apfelbaum, alle Bäume des Feldes sind verdorrt; ja, verdorrt ist die Freude von den Menschenkindern. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Umgürtet euch und wehklaget, ihr Priester; heulet, ihr Diener des Altars! Kommet, übernachtet in Sacktuch, ihr Diener meines Gottes! Denn Speisopfer und Trankopfer sind dem Hause eures Gottes entzogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Heiliget ein Fasten, rufet eine Festversammlung aus; versammelt die Ältesten, alle Bewohner des Landes, zum Hause Jehovas, eures Gottes, und schreiet zu Jehova!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Ach über den Tag! Denn nahe ist der Tag Jehovas, und er kommt wie eine Verwüstung vom Allmächtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Ist nicht die Speise vor unseren Augen weggenommen, Freude und Frohlocken von dem Hause unseres Gottes?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Vermodert sind die Samenkörner unter ihren Schollen; verödet sind die Vorratshäuser, zerfallen die Scheunen, denn das Korn ist verdorrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Wie stöhnt das Vieh! Die Rinderherden sind bestürzt, weil sie keine Weide haben; auch die Kleinviehherden büßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Zu dir, Jehova, rufe ich; denn ein Feuer hat die Auen der Steppe verzehrt, und eine Flamme alle Bäume des Feldes versengt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Auch die Tiere des Feldes schreien lechzend zu dir; denn vertrocknet sind die Wasserbäche, und ein Feuer hat die Auen der Steppe verzehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Stoßet in die Posaune auf Zion, und blaset Lärm auf meinem heiligen Berge! Beben sollen alle Bewohner des Landes; denn es kommt der Tag Jehovas, denn er ist nahe:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'ein Tag der Finsternis und der Dunkelheit, ein Tag des Gewölks und der Wolkennacht. Wie die Morgendämmerung ist es ausgebreitet über die Berge, ein großes und mächtiges Volk, desgleichen von Ewigkeit her nicht gewesen ist und nach ihm nicht mehr sein wird bis in die Jahre der Geschlechter und Geschlechter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Vor ihm her verzehrt das Feuer, und nach ihm lodert die Flamme; vor ihm ist das Land wie der Garten Eden, und nach ihm eine öde Wüste, und auch keine Entronnenen läßt es übrig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Sein Aussehen ist wie das Aussehen von Rossen; und wie Reitpferde, also rennen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Gleich Wagengerassel hüpfen sie auf den Gipfeln der Berge, gleich dem Prasseln der Feuerflamme, welche Stoppeln verzehrt; sie sind wie ein mächtiges Volk, zum Kampfe gerüstet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Vor ihm zittern die Völker, alle Angesichter erblassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Sie rennen wie Helden, wie Kriegsleute ersteigen sie die Mauer; und sie ziehen ein jeder auf seinem Wege, und ihre Pfade wechseln sie nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'und keiner drängt den anderen, sie ziehen jeder einzeln auf seiner Bahn; und sie stürzen zwischen den Waffen hindurch und verwunden sich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Sie laufen in der Stadt umher, rennen auf die Mauer, steigen in die Häuser; durch die Fenster dringen sie ein wie der Dieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Vor ihnen erbebt die Erde, erzittert der Himmel; Sonne und Mond verfinstern sich, und die Sterne verhalten ihren Glanz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Und Jehova läßt vor seinem Heere her seine Stimme erschallen, denn sein Heerlager ist sehr groß, denn der Vollstrecker seines Wortes ist mächtig; denn groß ist der Tag Jehovas und sehr furchtbar, und wer kann ihn ertragen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Aber auch jetzt noch, spricht Jehova, kehret um zu mir mit eurem ganzen Herzen, und mit Fasten und mit Weinen und mit Klagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Und zerreißet euer Herz und nicht eure Kleider, und kehret um zu Jehova, eurem Gott; denn er ist gnädig und barmherzig, langsam zum Zorn und groß an Güte, und läßt sich des Übels gereuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Wer weiß? Er möchte umkehren und es sich gereuen lassen, und er möchte Segen hinter sich zurücklassen: Speisopfer und Trankopfer für Jehova, euren Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Stoßet in die Posaune auf Zion, heiliget ein Fasten, rufet eine Festversammlung aus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Versammelt das Volk, heiliget eine Versammlung, bringet die Ältesten zusammen, versammelt die Kinder und die Säuglinge an den Brüsten; der Bräutigam trete aus seiner Kammer, und die Braut aus ihrem Gemach!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Die Priester, die Diener Jehovas, sollen weinen zwischen der Halle und dem Altar und sprechen: Schone, Jehova, deines Volkes und gib nicht dein Erbteil der Schmähung hin, daß sie den Nationen zur Spottrede seien! Warum soll man unter den Völkern sagen: Wo ist ihr Gott?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Dann eifert Jehova für sein Land, und er hat Mitleid mit seinem Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Und Jehova antwortet und spricht zu seinem Volke: Siehe, ich sende euch das Korn und den Most und das Öl, daß ihr davon satt werdet; und ich werde euch nicht mehr zum Hohne machen unter den Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Und ich werde den von Norden Kommenden von euch entfernen und ihn in ein dürres und wüstes Land vertreiben, seinen Vortrab in das vordere Meer und seinen Nachtrab in das hintere Meer; und sein Gestank wird aufsteigen, und aufsteigen sein übler Geruch, weil er Großes getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Fürchte dich nicht, Erde; frohlocke und freue dich! Denn Jehova tut Großes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Fürchtet euch nicht, ihr Tiere des Feldes! Denn es grünen die Auen der Steppe; denn der Baum trägt seine Frucht, der Feigenbaum und der Weinstock geben ihren Ertrag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Und ihr, Kinder Zions, frohlocket und freuet euch in Jehova, eurem Gott! Denn er gibt euch den Frühregen nach rechtem Maße, und er läßt euch Regen herabkommen: Frühregen und Spätregen wie zuvor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Und die Tennen werden voll Getreide sein, und die Kufen überfließen von Most und Öl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Und ich werde euch die Jahre erstatten, welche die Heuschrecke, der Abfresser und der Vertilger und der Nager gefressen haben, mein großes Heer, das ich unter euch gesandt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Und ihr werdet essen, essen und satt werden, und werdet den Namen Jehovas, eures Gottes, preisen, der Wunderbares an euch getan hat. Und mein Volk soll nimmermehr beschämt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Und ihr werdet wissen, daß ich in Israels Mitte bin, und daß ich, Jehova, euer Gott bin, und keiner sonst. Und mein Volk soll nimmermehr beschämt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'Und danach wird es geschehen, daß ich meinen Geist ausgießen werde über alles Fleisch; und eure Söhne und eure Töchter werden weissagen, eure Greise werden Träume haben, eure Jünglinge werden Gesichte sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Und selbst über die Knechte und über die Mägde werde ich meinen Geist ausgießen in jenen Tagen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'Und ich werde Wunder geben im Himmel und auf der Erde: Blut und Feuer und Rauchsäulen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'die Sonne wird sich in Finsternis verwandeln und der Mond in Blut, ehe der Tag Jehovas kommt, der große und furchtbare. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'Und es wird geschehen, ein jeder, der den Namen Jehovas anrufen wird, wird errettet werden; denn auf dem Berge Zion und in Jerusalem wird Errettung sein, wie Jehova gesprochen hat, und unter den Übriggebliebenen, welche Jehova berufen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Denn siehe, in jenen Tagen und zu jener Zeit, wenn ich die Gefangenschaft Judas und Jerusalems wenden werde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'dann werde ich alle Nationen versammeln und sie in das Tal Josaphat hinabführen; und ich werde daselbst mit ihnen rechten über mein Volk und mein Erbteil Israel, welches sie unter die Nationen zerstreut haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'und mein Land haben sie geteilt, und über mein Volk das Los geworfen; und den Knaben haben sie um eine Hure gegeben, und das Mädchen um Wein verkauft, den sie getrunken haben. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Und auch ihr, was wollt ihr mir, Tyrus und Zidon und alle ihr Bezirke Philistäas? Wollt ihr mir eine Tat vergelten, oder wollt ihr mir etwas antun? Schnell, eilends werde ich euer Tun auf euren Kopf zurückbringen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'daß ihr mein Silber und mein Gold weggenommen und meine besten Kleinode in eure Tempel gebracht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'und die Kinder Judas und die Kinder Jerusalems den Kindern der Griechen verkauft habt, um sie weit von ihrer Grenze zu entfernen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Siehe, ich will sie erwecken von dem Orte, wohin ihr sie verkauft habt, und will euer Tun auf euren Kopf zurückbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Und ich werde eure Söhne und eure Töchter in die Hand der Kinder Judas verkaufen; und diese werden sie an die Sabäer verkaufen, an eine ferne Nation; denn Jehova hat geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Rufet dieses aus unter den Nationen, heiliget einen Krieg, erwecket die Helden; es sollen herankommen und heraufziehen alle Kriegsmänner!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Schmiedet eure Pflugmesser zu Schwertern und eure Winzermesser zu Speeren; der Schwache sage: Ich bin ein Held!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Eilet und kommet her, alle ihr Nationen ringsum, und versammelt euch! Dahin, Jehova, sende deine Helden hinab!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Die Nationen sollen sich aufmachen und hinabziehen in das Tal Josaphat; denn dort werde ich sitzen, um alle Nationen ringsum zu richten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Leget die Sichel an, denn die Ernte ist reif; kommet, stampfet, denn die Kelter ist voll, die Kufen fließen über! Denn groß ist ihre Bosheit. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Getümmel, Getümmel im Tale der Entscheidung; denn nahe ist der Tag Jehovas im Tale der Entscheidung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Die Sonne und der Mond verfinstern sich, und die Sterne verhalten ihren Glanz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Und Jehova brüllt aus Zion und läßt aus Jerusalem seine Stimme erschallen, und Himmel und Erde erbeben. Und Jehova ist eine Zuflucht für sein Volk und eine Feste für die Kinder Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Und ihr werdet erkennen, daß ich, Jehova, euer Gott bin, der auf Zion wohnt, meinem heiligen Berge. Und Jerusalem wird heilig sein, und Fremde werden es nicht mehr durchziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'Und es wird geschehen, an jenem Tage, da werden die Berge von Most triefen, und die Hügel von Milch fließen, und alle Bäche Judas werden von Wasser fließen; und eine Quelle wird aus dem Hause Jehovas hervorbrechen und das Tal Sittim bewässern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Ägypten wird zur Einöde und Edom zu einer öden Wüste werden wegen der Gewalttat an den Kindern Judas, weil sie in ihrem Lande unschuldiges Blut vergossen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Aber Juda soll ewiglich bewohnt werden, und Jerusalem von Geschlecht zu Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Und ich werde sie von ihrem Blute reinigen, von dem ich sie nicht gereinigt hatte. Und Jehova wird in Zion wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Worte des Amos, der unter den Hirten von Tekoa war, welche er über Israel geschaut hat in den Tagen Ussijas, des Königs von Juda, und in den Tagen Jerobeams, des Sohnes Joas\', des Königs von Israel, zwei Jahre vor dem Erdbeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Und er sprach: Jehova wird aus Zion brüllen und aus Jerusalem seine Stimme erschallen lassen, und die Auen der Hirten werden trauern, und der Gipfel des Karmel wird verdorren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'So spricht Jehova: Wegen drei Freveltaten von Damaskus und wegen vier werde ich es nicht rückgängig machen: Weil sie Gilead mit eisernen Dreschschlitten gedroschen haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'so werde ich ein Feuer senden in das Haus Hasaels, und es wird die Paläste Ben-Hadads verzehren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'und ich werde den Riegel von Damaskus zerbrechen, und den Bewohner ausrotten aus dem Tale Awen, und den, der das Zepter hält, aus Beth-Eden; und das Volk von Syrien wird nach Kir weggeführt werden, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'So spricht Jehova: Wegen drei Freveltaten von Gasa und wegen vier werde ich es nicht rückgängig machen: Weil sie Gefangene in voller Zahl weggeführt haben, um sie an Edom auszuliefern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'so werde ich ein Feuer senden in die Mauer von Gasa, und es wird seine Paläste verzehren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'und ich werde den Bewohner ausrotten aus Asdod, und den, der das Zepter hält, aus Askalon; und ich werde meine Hand wenden wider Ekron, und der Überrest der Philister wird untergehen, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'So spricht Jehova: Wegen drei Freveltaten von Tyrus und wegen vier werde ich es nicht rückgängig machen: Weil sie Gefangene in voller Zahl an Edom ausgeliefert und des Bruderbundes nicht gedacht haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'so werde ich ein Feuer senden in die Mauer von Tyrus, und es wird seine Paläste verzehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'So spricht Jehova: Wegen drei Freveltaten von Edom und wegen vier werde ich es nicht rückgängig machen: Weil es seinen Bruder mit dem Schwerte verfolgt und sein Erbarmen erstickt hat, und weil sein Zorn beständig zerfleischt, und es seinen Grimm immerdar bewahrt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'so werde ich ein Feuer senden nach Teman, und es wird die Paläste von Bozra verzehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'So spricht Jehova: Wegen drei Freveltaten der Kinder Ammon und wegen vier werde ich es nicht rückgängig machen: Weil sie die Schwangeren von Gilead aufgeschlitzt haben, um ihre Grenze zu erweitern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'so werde ich ein Feuer anzünden in der Mauer von Rabba, und es wird seine Paläste verzehren unter Kriegsgeschrei am Tage des Kampfes, unter Sturm am Tage des Ungewitters;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'und ihr König wird in die Gefangenschaft gehen, er und seine Fürsten miteinander, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'So spricht Jehova: Wegen drei Freveltaten von Moab und wegen vier werde ich es nicht rückgängig machen: Weil es die Gebeine des Königs von Edom zu Kalk verbrannt hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'so werde ich ein Feuer senden nach Moab, und es wird die Paläste von Kerijoth verzehren; und Moab wird sterben im Getümmel, unter Kriegsgeschrei, unter Posaunenschall;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'und ich werde den Richter ausrotten aus seiner Mitte und alle seine Fürsten mit ihm umbringen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'So spricht Jehova: Wegen drei Freveltaten von Juda und wegen vier werde ich es nicht rückgängig machen: Weil sie das Gesetz Jehovas verworfen und seine Satzungen nicht bewahrt haben, und ihre Lügen sie verführten, denen ihre Väter nachgewandelt sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'so werde ich ein Feuer senden nach Juda, und es wird die Paläste Jerusalems verzehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'So spricht Jehova: Wegen drei Freveltaten von Israel und wegen vier werde ich es nicht rückgängig machen: Weil sie den Gerechten für Geld und den Dürftigen um ein Paar Schuhe verkaufen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'sie, welche danach lechzen, den Staub der Erde auf dem Haupte der Armen zu sehen, und den Weg der Sanftmütigen krümmen; und ein Mann und sein Vater gehen zu derselben Dirne, um meinen heiligen Namen zu entweihen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'und neben jedem Altare strecken sie sich hin auf gepfändeten Oberkleidern, und im Hause ihres Gottes trinken sie Wein von Strafgeldern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Und doch habe ich den Amoriter vor ihnen vertilgt, dessen Höhe wie die Höhe der Zedern war, und er war stark wie die Eichen; und ich habe seine Frucht vertilgt von oben und seine Wurzeln von unten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Und doch habe ich euch aus dem Lande Ägypten heraufgeführt und euch vierzig Jahre in der Wüste geleitet, damit ihr das Land des Amoriters in Besitz nähmet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Und ich habe Propheten erweckt aus euren Söhnen und Nasiräer aus euren Jünglingen. Ja, ist es nicht also, ihr Kinder Israel? spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Aber ihr habt den Nasiräern Wein zu trinken gegeben, und den Propheten geboten und gesagt: Ihr sollt nicht weissagen! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Siehe, ich werde euch niederdrücken, wie der Wagen drückt, der voll Garben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Und dem Schnellen wird die Flucht entschwinden; und der Starke wird seine Kraft nicht befestigen, und der Held sein Leben nicht erretten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'und der den Bogen führt, wird nicht standhalten; und der Schnellfüßige wird nicht entrinnen, und der auf dem Rosse reitet sein Leben nicht erretten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'und der Beherzteste unter den Helden wird nackt entfliehen an jenem Tage, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Höret dieses Wort, das Jehova über euch redet, ihr Kinder Israel, über das ganze Geschlecht, welches ich aus dem Lande Ägypten heraufgeführt habe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Indem er spricht: Nur euch habe ich von allen Geschlechtern der Erde erkannt; darum werde ich alle eure Missetaten an euch heimsuchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Wandeln wohl zwei miteinander, es sei denn, daß sie übereingekommen sind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Brüllt der Löwe im Walde, wenn er keinen Raub hat? Läßt der junge Löwe seine Stimme aus seiner Höhle erschallen, außer wenn er einen Fang getan hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Fällt der Vogel in die Schlinge am Boden, wenn ihm kein Sprenkel gelegt ist? Schnellt die Schlinge von der Erde empor, wenn sie gar nichts gefangen hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Oder wird die Posaune in der Stadt geblasen, und das Volk sollte nicht erschrecken? Oder geschieht ein Unglück in der Stadt, und Jehova hätte es nicht bewirkt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Denn der Herr, Jehova, tut nichts, es sei denn, daß er sein Geheimnis seinen Knechten, den Propheten, geoffenbart habe. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Der Löwe hat gebrüllt, wer sollte sich nicht fürchten? Der Herr, Jehova, hat geredet, wer sollte nicht weissagen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Rufet über die Paläste in Asdod und über die Paläste im Lande Ägypten hin und sprechet: Versammelt euch auf den Bergen von Samaria, und sehet die große Verwirrung in seiner Mitte und die Bedrückungen in seinem Innern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Und sie wissen nicht zu tun, was recht ist, spricht Jehova, sie, welche Gewalttat und Zerstörung häufen in ihren Palästen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Darum, so spricht der Herr, Jehova: Der Feind, und zwar rings um das Land her! Und er wird deine Macht von dir herabstürzen, und dein Paläste werden geplündert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'So spricht Jehova: Gleichwie der Hirt zwei Beine oder einen Ohrzipfel aus dem Rachen des Löwen rettet, also werden gerettet werden die Kinder Israel, welche in Samaria in der Ecke des Polsters und auf dem Damaste des Ruhebettes sitzen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Höret und bezeuget es dem Hause Jakob, spricht der Herr, Jehova, der Gott der Heerscharen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'An dem Tage, da ich Israels Übertretungen an ihm heimsuchen werde, werde ich auch die Altäre von Bethel heimsuchen; und die Hörner des Altars sollen abgehauen werden und zu Boden fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Und ich werde das Winterhaus zertrümmern samt dem Sommerhause; und die Elfenbeinhäuser werden zu Grunde gehen, die großen Häuser werden verschwinden, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Höret dieses Wort, ihr Kühe Basans, die ihr auf dem Berge Samarias seid, die ihr die Armen bedrücket, die Dürftigen mißhandelt, und zu euren Herren sprechet: Bringe her, daß wir trinken!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Geschworen hat der Herr, Jehova, bei seiner Heiligkeit: Siehe, Tage werden über euch kommen, da man euch an Haken wegschleppen wird, und euren Rest an Fischerangeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Und ihr werdet durch die Mauerrisse hinausgehen, eine jede vor sich hin, und ihr werdet nach Harmon hingeworfen werden, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Gehet nach Bethel und übertretet! Nach Gilgal und mehret die Übertretung! Und bringet jeden Morgen eure Schlachtopfer, alle drei Tage eure Zehnten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'und räuchert von dem Gesäuerten Dankopfer, und rufet aus, verkündet freiwillige Gaben! Denn also liebet ihr\'s, ihr Kinder Israel, spricht der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Und so habe auch ich euch reine Zähne gegeben in allen euren Städten und Mangel an Brot in allen euren Orten; und doch seid ihr nicht bis zu mir umgekehrt, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Und auch ich habe euch den Regen entzogen, als noch drei Monate bis zur Ernte waren; und ich habe auf die eine Stadt regnen lassen, während ich auf die andere Stadt nicht regnen ließ; der eine Acker wurde beregnet, und der Acker, auf welchen es nicht regnete, verdorrte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'und zwei, drei Städte wankten zu einer Stadt hin, um Wasser zu trinken, und wurden nicht satt. Dennoch seid ihr nicht bis zu mir umgekehrt, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Ich habe euch mit Kornbrand und mit Vergilben geschlagen; eine große Zahl eurer Gärten und eurer Weinberge und eurer Feigen-und eurer Olivenbäume fraß die Heuschrecke. Dennoch seid ihr nicht bis zu mir umgekehrt, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Ich habe die Pest unter euch gesandt in der Weise Ägyptens; ich habe eure Jünglinge mit dem Schwerte getötet, indem zugleich eure Rosse gefangen weggeführt wurden, und ich ließ den Gestank eurer Heerlager aufsteigen, und zwar in eure Nase. Dennoch seid ihr nicht bis zu mir umgekehrt, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Ich habe eine Umkehrung unter euch angerichtet wie die Umkehrung von Sodom und Gomorra durch Gott; und ihr waret wie ein Brandscheit, das aus dem Feuer gerettet ist. Dennoch seid ihr nicht bis zu mir umgekehrt, spricht Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Darum werde ich dir also tun, Israel. Weil ich dir dieses tun will, so schicke dich an, Israel, deinem Gott zu begegnen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Denn siehe, der die Berge bildet und den Wind schafft, und dem Menschen kundtut, was sein Gedanke ist; der die Morgenröte und die Finsternis macht, und einherschreitet auf den Höhen der Erde: Jehova, Gott der Heerscharen, ist sein Name.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Höret dieses Wort, das ich über euch erhebe, ein Klagelied, Haus Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Sie ist gefallen, die Jungfrau Israel, sie wird nicht wieder aufstehen; sie liegt hingeworfen auf ihrem Lande, niemand richtet sie auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Denn so spricht der Herr, Jehova: Die Stadt, die zu tausend auszieht, wird hundert übrigbehalten, und die zu hundert auszieht, wird zehn übrigbehalten für das Haus Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Denn so spricht Jehova zum Hause Israel: Suchet mich und lebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Und suchet nicht Bethel auf, und gehet nicht nach Gilgal, und gehet nicht hinüber nach Beerseba; denn Gilgal wird gewißlich weggeführt und Bethel zunichte werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Suchet Jehova und lebet, damit er nicht in das Haus Josephs eindringe wie ein Feuer und es verzehre, und für Bethel niemand da sei, der es lösche,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'sie verwandeln das Recht in Wermut und werfen die Gerechtigkeit zu Boden; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'suchet den, der das Siebengestirn und den Orion gemacht hat, und den Todesschatten in Morgen verwandelt und den Tag zur Nacht verfinstert, der den Wassern des Meeres ruft und sie ausgießt über die Fläche der Erde: Jehova ist sein Name;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'der Verwüstung losbrechen läßt über den Starken, und Verwüstung kommt über die Feste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Sie hassen den, der im Tore Recht spricht, und verabscheuen den, der Unsträflichkeit redet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Darum, weil ihr den Armen niedertretet und Getreidegaben von ihm nehmet, habt ihr Häuser von behauenen Steinen gebaut und werdet nicht darin wohnen, liebliche Weinberge gepflanzt und werdet deren Wein nicht trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Denn ich weiß, daß eurer Übertretungen viele, und daß eure Sünden zahlreich sind; sie bedrängen den Gerechten, nehmen Lösegeld und beugen das Recht der Dürftigen im Tore.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Darum schweigt der Einsichtige in dieser Zeit, denn es ist eine böse Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Trachtet nach dem Guten und nicht nach dem Bösen, auf daß ihr lebet; und Jehova, der Gott der Heerscharen, wird also mit euch sein, wie ihr saget.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Hasset das Böse und liebet das Gute, und richtet das Recht auf im Tore; vielleicht wird Jehova, der Gott der Heerscharen, dem Überrest Josephs gnädig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Darum spricht Jehova, der Gott der Heerscharen, der Herr, also: Auf allen Plätzen Wehklage! Und auf allen Gassen wird man sagen: Wehe, wehe! Und man wird den Ackersmann zur Trauer rufen, und die des Klageliedes Kundigen zur Wehklage;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'und in allen Weinbergen wird Wehklage sein. Denn ich werde durch deine Mitte ziehen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Wehe denen, welche den Tag Jehovas herbeiwünschen! Wozu soll euch der Tag Jehovas sein? Er wird Finsternis sein und nicht Licht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'wie wenn jemand vor dem Löwen flieht, und es begegnet ihm ein Bär; und er kommt nach Hause und stützt seine Hand an die Mauer, und es beißt ihn eine Schlange.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Wird denn nicht der Tag Jehovas Finsternis sein und nicht Licht, und Dunkelheit und nicht Glanz?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Ich hasse, ich verschmähe eure Feste, und eure Festversammlungen mag ich nicht riechen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'denn wenn ihr mir Brandopfer und eure Speisopfer opfert, habe ich kein Wohlgefallen daran; und das Friedensopfer von eurem Mastvieh mag ich nicht ansehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Tue den Lärm deiner Lieder von mir hinweg, und das Spiel deiner Harfen mag ich nicht hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Aber das Recht wälze sich einher wie Wasser, und die Gerechtigkeit wie ein immerfließender Bach!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Habt ihr mir vierzig Jahre in der Wüste Schlachtopfer und Speisopfer dargebracht, Haus Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Ja, ihr habt die Hütte eures Königs und das Gestell eurer Götzenbilder getragen, das Sternbild eures Gottes, die ihr euch gemacht hattet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'So werde ich euch jenseit Damaskus wegführen, spricht Jehova, Gott der Heerscharen ist sein Name.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Wehe den Sorglosen in Zion und den Sicheren auf dem Berge von Samaria, den Vornehmen der ersten der Nationen, zu welchen das Haus Israel kommt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Gehet hinüber nach Kalne und sehet, und gehet von dort nach Hamath, der großen Stadt, und steiget hinab nach Gath der Philister: sind sie vorzüglicher als diese Königreiche, oder ist ihr Gebiet größer als euer Gebiet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Ihr, die den Tag des Unglücks hinausschieben und den Thron der Gewalttat nahe rücken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'die auf Polstern von Elfenbein liegen und auf ihren Ruhebetten sich strecken, und Fettschafe von der Herde essen und Kälber aus dem Maststall;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'die da faseln zum Klange der Harfe, sich wie David Musikinstrumente ersinnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'die Wein aus Schalen trinken und mit den besten Ölen sich salben, und sich nicht grämen über die Wunde Josephs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Darum werden sie nun weggeführt werden an der Spitze der Weggeführten, und das Gejauchze der träge Hingestreckten wird aufhören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Der Herr, Jehova, hat bei sich selbst geschworen, spricht Jehova, der Gott der Heerscharen: Ich verabscheue die Hoffart Jakobs und hasse seine Paläste; und ich werde die Stadt preisgeben und alles, was sie erfüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Und es wird geschehen, wenn zehn Männer in einem Hause übrigbleiben, so werden sie sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Und hebt einen der Gestorbenen sein Oheim und sein Bestatter auf, um die Gebeine aus dem Hause hinauszuschaffen, und spricht zu dem, der im Innern des Hauses ist: Ist noch jemand bei dir? und dieser sagt: Niemand; so wird er sagen: Still! denn der Name Jehovas darf nicht erwähnt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Denn siehe, Jehova gebietet, und man schlägt das große Haus in Trümmer und das kleine Haus in Splitter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Rennen wohl Rosse auf Felsen, oder pflügt man darauf mit Rindern? daß ihr das Recht in Gift und die Frucht der Gerechtigkeit in Wermut verwandelt habt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'die ihr euch über Nichtiges freuet, die ihr sprechet: Haben wir uns nicht durch unsere Stärke Hörner erworben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Denn siehe, ich werde wider euch, Haus Israel, eine Nation erwecken, spricht Jehova, der Gott der Heerscharen; und sie werden euch bedrücken von dem Eingange Hamaths an bis zum Bache der Ebene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Also ließ mich der Herr, Jehova, sehen: Siehe, er bildete Heuschrecken im Anfang des Spätgraswuchses; und siehe, es war das Spätgras nach dem Königsmähen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Und es geschah, als sie das Kraut der Erde ganz abgefressen hatten, da sprach ich: Herr, Jehova, vergib doch! Wie sollte Jakob bestehen? Denn es ist klein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Jehova ließ sich dieses gereuen: es soll nicht geschehen, sprach Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Also ließ mich der Herr, Jehova, sehen: Siehe, der Herr, Jehova rief, um mit Feuer zu richten; und es fraß die große Flut und fraß das Erbteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Da sprach ich: Herr, Jehova, laß doch ab! Wie sollte Jakob bestehen? Denn es ist klein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Jehova ließ sich dieses gereuen: auch das soll nicht geschehen, sprach der Herr, Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Also ließ er mich sehen: Siehe, der Herr stand auf einer senkrechten Mauer, und ein Senkblei war in seiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Und Jehova sprach zu mir: Was siehst du, Amos? Und ich sprach: Ein Senkblei. Und der Herr sprach: Siehe, ich lege ein Senkblei an mein Volk Israel, in seiner Mitte; ich werde fortan nicht mehr schonend an ihm vorübergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Und die Höhen Isaaks werden verwüstet und die Heiligtümer Israels zerstört werden, und ich werde mit dem Schwerte wider das Haus Jerobeams aufstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Da sandte Amazja, der Priester von Bethel, zu Jerobeam, dem König von Israel, und ließ ihm sagen: Amos hat eine Verschwörung wider dich angestiftet inmitten des Hauses Israel; das Land wird alle seine Worte nicht zu ertragen vermögen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'denn so spricht Amos: Jerobeam wird durchs Schwert sterben, und Israel wird gewißlich aus seinem Lande weggeführt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Und Amazja sprach zu Amos: Seher, geh, entfliehe in das Land Juda; und iß dort dein Brot, und dort magst du weissagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Aber in Bethel sollst du fortan nicht mehr weissagen; denn dies ist ein Heiligtum des Königs, und dies ein königlicher Wohnsitz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Und Amos antwortete und sprach zu Amazja: Ich war kein Prophet und war kein Prophetensohn, sondern ich war ein Viehhirt und las Maulbeerfeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Und Jehova nahm mich hinter dem Kleinvieh weg, und Jehova sprach zu mir: Gehe hin, weissage meinem Volke Israel. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Und nun höre das Wort Jehovas: Du sprichst: Du sollst nicht weissagen über Israel und sollst nicht reden über das Haus Isaak.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Darum spricht Jehova also: Dein Weib wird zur Hure werden in der Stadt, und deine Söhne und deine Töchter werden durchs Schwert fallen, und dein Land wird verteilt werden mit der Meßschnur, und du selbst wirst in einem unreinen Lande sterben; und Israel wird gewißlich aus seinem Lande weggeführt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Also ließ mich der Herr, Jehova, sehen: Siehe, ein Korb mit reifem Obst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Und er sprach: Was siehst du, Amos? Und ich sprach: Einen Korb mit reifem Obst. Und Jehova sprach zu mir: Das Ende ist über mein Volk Israel gekommen, ich werde fortan nicht mehr schonend an ihm vorübergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Und die Gesänge des Palastes werden sich in Geheul verwandeln an jenem Tage, spricht der Herr, Jehova. Leichen in Menge, aller Orten hat er sie hingeworfen... Still!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Höret dieses, die ihr nach dem Dürftigen schnaubet und nach der Vernichtung der Sanftmütigen im Lande, und sprechet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Wann ist der Neumond vorüber, daß wir Getreide verkaufen, und der Sabbath, daß wir die Kornspeicher auftun; um das Epha zu verkleinern und den Sekel zu vergrößern und die Waage des Betrugs zu fälschen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'um die Armen für Geld, und den Dürftigen um ein Paar Schuhe zu kaufen; und damit wir den Abfall des Korns verkaufen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Jehova hat geschworen bei dem Stolze Jakobs: Wenn ich alle ihre Werke vergessen werde ewiglich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Sollte das Land darob nicht erbeben, und jeder, der darin wohnt, nicht trauern? Und es wird insgesamt emporsteigen wie der Nil, und aufwogen und zurücksinken wie der Strom Ägyptens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Und es wird geschehen an jenem Tage, spricht der Herr, Jehova, da werde ich die Sonne untergehen lassen am Mittag und Finsternis über die Erde bringen am lichten Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Und ich werde eure Feste in Trauer verwandeln und alle eure Gesänge in Klagelieder, und werde auf alle Lenden Sacktuch und auf jedes Haupt eine Glatze bringen; und ich werde es machen gleich der Trauer um den Eingeborenen, und das Ende davon wie einen bitteren Tag. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Siehe, Tage kommen, spricht der Herr, Jehova, da werde ich einen Hunger in das Land senden, nicht einen Hunger nach Brot und nicht einen Durst nach Wasser, sondern die Worte Jehovas zu hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Und sie werden umherschweifen von Meer zu Meer und vom Norden bis zum Osten; sie werden umherlaufen, um das Wort Jehovas zu suchen, und werden es nicht finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'An jenem Tage werden die schönen Jungfrauen und die Jünglinge vor Durst verschmachten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'die da schwören bei der Schuld Samarias und sprechen: So wahr dein Gott lebt, Dan! und: So wahr der Weg nach Beerseba lebt! Und sie werden fallen und nicht mehr aufstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Und ich sah den Herrn an dem Altar stehen; und er sprach: Schlage auf den Säulenknauf, daß die Schwellen erbeben, und zerschmettere sie auf ihrer aller Haupt; und ich werde ihren Rest mit dem Schwerte umbringen; kein Flüchtling von ihnen soll entfliehen und kein Entronnener von ihnen davonkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Wenn sie in den Scheol einbrechen, wird von dort meine Hand sie holen; und wenn sie in den Himmel hinaufsteigen, werde ich von dort sie herniederbringen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'und wenn sie sich auf den Gipfel des Karmel verbergen, werde ich von dort sie hervorsuchen und holen; und wenn sie sich, vor meinen Augen hinweg, im Grunde des Meeres verstecken, werde ich von dort die Schlange entbieten, und sie wird sie beißen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'und wenn sie vor ihren Feinden her in Gefangenschaft ziehen, werde ich von dort das Schwert entbieten, und es wird sie umbringen. Und ich werde mein Auge wider sie richten zum Bösen und nicht zum Guten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Und der Herr, Jehova der Heerscharen, der das Land anrührt, und es zerfließt, und es trauern alle, die darin wohnen, und es steigt empor insgesamt, wie der Nil, und sinkt zurück, wie der Strom Ägyptens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'der seine Obergemächer im Himmel gebaut und seine Gewölbe über der Erde gegründet hat; der den Wassern des Meeres ruft und sie ausgießt über die Fläche der Erde: Jehova ist sein Name.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Seid ihr mir nicht wie die Kinder der Äthiopier, Kinder Israel? spricht Jehova. Habe ich nicht Israel aus dem Lande Ägypten heraufgeführt, und die Philister aus Kaphtor und die Syrer aus Kir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Siehe, die Augen des Herrn, Jehovas, sind wider das sündige Königreich, und ich will es vom Erdboden hinweg vertilgen; nur daß ich das Haus Jakob nicht gänzlich vertilgen werde, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Denn siehe, ich will gebieten und will das Haus Israel unter allen Nationen schütteln, wie Getreide in einem Siebe geschüttelt wird; und nicht ein Körnchen wird zur Erde fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Alle Sünder meines Volkes werden durchs Schwert sterben, die da sprechen: Das Unglück wird uns nicht nahen und nicht an uns herankommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'An jenem Tage werde ich die verfallene Hütte Davids aufrichten und ihre Risse vermauern und ihre Trümmer aufrichten, und ich werde sie bauen wie in den Tagen vor alters;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'auf daß sie den Überrest Edoms und all die Nationen in Besitz nehmen, über welche mein Name genannt werden wird, spricht Jehova, der dieses tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Siehe, Tage kommen, spricht Jehova, da der Pflüger an den Schnitter und der Traubentreter an den Säemann reichen wird; und die Berge werden träufeln von Most, und alle Hügel werden zerfließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Und ich werde die Gefangenschaft meines Volkes Israel wenden; und sie werden die verwüsteten Städte aufbauen und bewohnen, und Weinberge pflanzen und deren Wein trinken, und deren Gärten anlegen und deren Frucht essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Und ich werde sie in ihrem Lande pflanzen; und sie sollen nicht mehr herausgerissen werden aus ihrem Lande, das ich ihnen gegeben habe, spricht Jehova, dein Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Gesicht Obadjas. So spricht der Herr, Jehova, von Edom: Eine Kunde haben wir von Jehova gehört, und ein Bote ist unter die Nationen gesandt worden: \"Machet euch auf, und laßt uns wider dasselbe aufstehen zum Kriege!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Siehe, ich habe dich klein gemacht unter den Nationen, du bist sehr verachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Der Übermut deines Herzens hat dich verführt, der du in Felsenklüften, auf hohem Sitze wohnst und in deinem Herzen sprichst: Wer wird mich zur Erde hinabstürzen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Wenn du dein Nest auch hoch baust wie der Adler, und wenn es zwischen die Sterne gesetzt wäre: ich werde dich von dort hinabstürzen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Wenn Diebe über dich gekommen wären, wenn nächtliche Räuber, wie bist du vernichtet! würden sie nicht gestohlen haben nach ihrer Genüge? Wenn Winzer über dich gekommen wären, würden sie nicht eine Nachlese übriggelassen haben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Wie sind die von Esau durchsucht, ausgeforscht ihre verborgenen Schätze!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Alle deine Bundesgenossen haben dich bis zur Grenze geschickt; betrogen, überwältigt haben dich deine Freunde, die dein Brot aßen; sie legten eine Schlinge unter dich. Es ist kein Verstand in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Werde ich nicht an jenem Tage, spricht Jehova, die Weisen aus Edom vertilgen und den Verstand vom Gebirge Esaus?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Und deine Helden, Teman, werden verzagen, auf daß jedermann vom Gebirge Esaus ausgerottet werde durch Ermordung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Wegen der an deinem Bruder Jakob verübten Gewalttat wird Schande dich bedecken, und du wirst ausgerottet werden auf ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'An dem Tage, da du gegenüber standest, an dem Tage, da Fremde sein Vermögen hinwegführten, und Ausländer zu seinen Toren einzogen und über Jerusalem das Los warfen, da warst auch du wie einer von ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Und du solltest nicht auf den Tag deines Bruders sehen am Tage seines Mißgeschicks, und dich nicht freuen über die Kinder Juda am Tage ihres Untergangs, noch dein Maul aufsperren am Tage der Bedrängnis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'du solltest nicht in das Tor meines Volkes einziehen am Tage seiner Not, und du, auch du, nicht auf sein Unglück sehen am Tage seiner Not, noch deine Hand ausstrecken nach seinem Vermögen am Tage seiner Not;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'und du solltest nicht am Kreuzwege stehen, um seine Flüchtlinge zu vertilgen, und solltest seine Entronnenen nicht ausliefern am Tage der Bedrängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Denn der Tag Jehovas ist nahe über alle Nationen: wie du getan hast, wird dir getan werden; dein Tun wird auf dein Haupt zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Denn gleichwie ihr getrunken habt auf meinem heiligen Berge, so werden beständig trinken alle Nationen; ja, sie werden trinken und schlürfen, und werden sein wie solche, die nie gewesen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Aber auf dem Berge Zion wird Errettung sein, und er wird heilig sein; und die vom Hause Jakob werden ihre Besitzungen wieder in Besitz nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Und das Haus Jakob wird ein Feuer sein, und das Haus Joseph eine Flamme, und das Haus Esau zu Stoppeln; und sie werden unter ihnen brennen und sie verzehren. Und das Haus Esau wird keinen Übriggebliebenen haben, denn Jehova hat geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Und die vom Süden werden das Gebirge Esaus, und die von der Niederung die Philister in Besitz nehmen; und sie werden das Gefilde Ephraims und das Gefilde Samarias, und Benjamin wird Gilead in Besitz nehmen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'und die Weggeführten dieses Heeres der Kinder Israel werden in Besitz nehmen, was den Kanaanitern gehört bis nach Zarpath hin; und die Weggeführten von Jerusalem, welche in Sepharad sind, die Städte des Südens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Und es werden Retter auf den Berg Zion ziehen, um das Gebirge Esaus zu richten; und das Reich wird Jehova gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Und das Wort Jehovas geschah zu Jona, dem Sohne Amittais, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Mache dich auf, geh nach Ninive, der großen Stadt, und predige wider sie; denn ihre Bosheit ist vor mich heraufgestiegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Aber Jona machte sich auf, um von dem Angesicht Jehovas hinweg nach Tarsis zu fliehen; und er ging nach Japho hinab und fand ein Schiff, das nach Tarsis fuhr; und er gab sein Fährgeld und stieg in dasselbe hinab, um mit ihnen nach Tarsis zu fahren von dem Angesicht Jehovas hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Da warf Jehova einen heftigen Wind auf das Meer, und es entstand ein großer Sturm auf dem Meere, so daß das Schiff zu zerbrechen drohte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Und die Seeleute fürchteten sich und schrieen, ein jeder zu seinem Gott; und sie warfen die Geräte, welche im Schiffe waren, ins Meer, um sich zu erleichtern. Jona aber war in den unteren Schiffsraum hinabgestiegen, und hatte sich hingelegt und war in tiefen Schlaf gesunken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Und der Obersteuermann trat zu ihm hin und sprach zu ihm: Was ist mit dir, du Schläfer? Stehe auf, rufe deinen Gott an! Vielleicht wird der Gott unser gedenken, daß wir nicht umkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Und sie sprachen einer zum anderen: Kommt und laßt uns Lose werfen, damit wir erfahren, um wessentwillen dieses Unglück uns trifft. Und sie warfen Lose, und das Los fiel auf Jona.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Da sprachen sie zu ihm: Tue uns doch kund, um wessentwillen dieses Unglück uns trifft! Was ist dein Geschäft, und woher kommst du? Welches ist dein Land, und von welchem Volke bist du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Und er sprach zu ihnen: Ich bin ein Hebräer; und ich fürchte Jehova, den Gott des Himmels, der das Meer und das Trockene gemacht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Da fürchteten sich die Männer mit großer Furcht und sprachen zu ihm: Was hast du da getan! Denn die Männer wußten, daß er von dem Angesicht Jehovas hinwegfloh; denn er hatte es ihnen kundgetan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Und sie sprachen zu ihm: Was sollen wir dir tun, damit das Meer sich gegen uns beruhige? Denn das Meer wurde immer stürmischer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Und er sprach zu ihnen: Nehmet mich und werfet mich ins Meer, so wird das Meer sich gegen euch beruhigen; denn ich weiß, daß dieser große Sturm um meinetwillen über euch gekommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Und die Männer ruderten hart, um das Schiff ans Land zurückzuführen; aber sie vermochten es nicht, weil das Meer immer stürmischer gegen sie wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Da riefen sie zu Jehova und sprachen: Ach, Jehova! Laß uns doch nicht umkommen um der Seele dieses Mannes willen, und lege nicht unschuldiges Blut auf uns; denn du, Jehova, hast getan, wie es dir gefallen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Und sie nahmen Jona und warfen ihn ins Meer. Da ließ das Meer ab von seinem Wüten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Und die Männer fürchteten sich vor Jehova mit großer Furcht, und sie schlachteten Schlachtopfer und taten Gelübde dem Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, '(H2:1) Und Jehova bestellte einen großen Fisch, um Jona zu verschlingen; und Jona war im Bauche des Fisches drei Tage und drei Nächte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, '(H2:2) Und Jona betete zu Jehova, seinem Gott, aus dem Bauche des Fisches und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, '(H2:3) Ich rief aus meiner Bedrängnis zu Jehova, und er antwortete mir; ich schrie aus dem Schoße des Scheols, du hörtest meine Stimme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, '(H2:4) Denn du hattest mich in die Tiefe, in das Herz der Meere geworfen, und der Strom umschloß mich; alle deine Wogen und deine Wellen fuhren über mich hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, '(H2:5) Und ich sprach: Verstoßen bin ich aus deinen Augen; dennoch werde ich wieder hinschauen nach deinem heiligen Tempel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, '(H2:6) Die Wasser umfingen mich bis an die Seele, die Tiefe umschloß mich, das Meergras schlang sich um mein Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, '(H2:7) Ich fuhr hinab zu den Gründen der Berge; der Erde Riegel waren hinter mir auf ewig. Da führtest du mein Leben aus der Grube herauf, Jehova, mein Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, '(H2:8) Als meine Seele in mir verschmachtete, gedachte ich Jehovas, und zu dir kam mein Gebet in deinen heiligen Tempel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, '(H2:9) Die auf nichtige Götzen achten, verlassen ihre Gnade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, '(H2:10) Ich aber werde dir opfern mit der Stimme des Lobes; was ich gelobt habe, werde ich bezahlen. Bei Jehova ist die Rettung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, '(H2:11) Und Jehova befahl dem Fische, und er spie Jona an das Land aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Und das Wort Jehovas geschah zum zweiten Male zu Jona also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Mache dich auf, geh nach Ninive, der großen Stadt, und rufe ihr die Botschaft aus, die ich dir sagen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Da machte sich Jona auf und ging nach Ninive, nach dem Worte Jehovas. Ninive war aber eine außerordentlich große Stadt von drei Tagereisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Und Jona begann in die Stadt hineinzugehen eine Tagereise weit, und er rief und sprach: Noch vierzig Tage, so ist Ninive umgekehrt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Und die Leute von Ninive glaubten Gott; und sie riefen ein Fasten aus und kleideten sich in Sacktuch, von ihrem Größten bis zu ihrem Kleinsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Und das Wort gelangte an den König von Ninive; und er stand von seinem Throne auf und legte seinen Mantel ab, und hüllte sich in Sacktuch und setzte sich in die Asche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Und er ließ in Ninive, auf Befehl des Königs und seiner Großen, ausrufen und sagen: Menschen und Vieh, Rinder und Kleinvieh sollen gar nichts kosten, sie sollen nicht weiden und kein Wasser trinken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'und Menschen und Vieh sollen mit Sacktuch bedeckt sein und sollen heftig zu Gott rufen; und sie sollen umkehren, ein jeder von seinem bösen Wege und von dem Unrecht, das in ihren Händen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Wer weiß? Gott möchte sich wenden und es sich gereuen lassen, und umkehren von der Glut seines Zornes, daß wir nicht umkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Und Gott sah ihre Werke, daß sie von ihrem bösen Wege umgekehrt waren; und Gott ließ sich des Übels gereuen, wovon er geredet hatte, daß er es ihnen tun wolle, und tat es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Und es verdroß Jona sehr, und er wurde zornig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Und er betete zu Jehova und sprach: Ach, Jehova! War das nicht mein Wort, als ich noch in meinem Lande war? Darum kam ich zuvor, indem ich nach Tarsis entfloh; denn ich wußte, daß du ein gnädiger und barmherziger Gott bist, langsam zum Zorn und groß an Güte, und der sich des Übels gereuen läßt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Und nun, Jehova, nimm doch meine Seele von mir; denn es ist besser, daß ich sterbe, als daß ich lebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Und Jehova sprach: Ist es recht, daß du zürnest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Und Jona ging aus der Stadt hinaus und setzte sich gegen Osten der Stadt. Und er machte sich daselbst eine Hütte; und er saß darunter im Schatten, bis er sähe, was mit der Stadt geschehen würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Und Jehova Gott bestellte einen Wunderbaum und ließ ihn über Jona emporwachsen, damit Schatten über seinem Haupte wäre, um ihn von seinem Mißmut zu befreien; und Jona freute sich über den Wunderbaum mit großer Freude. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Aber Gott bestellte einen Wurm am folgenden Tage, beim Aufgang der Morgenröte; und dieser stach den Wunderbaum, daß er verdorrte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Und es geschah, als die Sonne aufging, da bestellte Gott einen schwülen Ostwind; und die Sonne stach Jona aufs Haupt, daß er ermattet niedersank. Und er begehrte, daß seine Seele stürbe, und sprach: Es ist besser, daß ich sterbe, als daß ich lebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Und Gott sprach zu Jona: Ich es recht, daß du wegen des Wunderbaumes zürnest? Und er sprach: Mit Recht zürne ich bis zum Tode!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Und Jehova sprach: Du erbarmst dich des Wunderbaumes, um welchen du dich nicht gemüht und den du nicht großgezogen hast, der als Sohn einer Nacht entstand und als Sohn einer Nacht zu Grunde ging;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'und ich sollte mich Ninives, der großen Stadt, nicht erbarmen, in welcher mehr als hundertundzwanzigtausend Menschen sind, die nicht zu unterscheiden wissen zwischen ihrer Rechten und ihrer Linken, und eine Menge Vieh?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Das Wort Jehovas, welches zu Micha, dem Moraschtiter, geschah in den Tagen Jothams, Ahas\' und Hiskias, der Könige von Juda, das er schaute über Samaria und Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Höret, ihr Völker alle, merke auf, du Erde und ihre Fülle! Und der Herr, Jehova, sei zum Zeugen wider euch, der Herr aus seinem heiligen Palast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Denn siehe, Jehova geht aus von seiner Stätte und kommt herab und schreitet einher auf den Höhen der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Und die Berge zerschmelzen unter ihm, und die Täler spalten sich wie das Wachs vor dem Feuer, wie Wasser, ausgegossen am Abhange.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Das alles wegen der Übertretung Jakobs und wegen der Sünden des Hauses Israel. Von wem geht die Übertretung Jakobs aus? Ist es nicht Samaria? Und von wem die Höhen Judas? Ist es nicht Jerusalem?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'So werde ich Samaria zu einem Steinhaufen des Feldes, zu Weinbergpflanzungen machen, und ich werde ihre Steine ins Tal hinabstürzen und ihre Grundfesten entblößen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Und alle ihre gegossenen Bilder werden zerschlagen und alle ihre Hurengeschenke mit Feuer verbrannt werden, und ich werde alle ihre Götzenbilder zur Wüste machen; denn sie hat sie durch Hurenlohn gesammelt, und zum Hurenlohn sollen sie wieder werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Darum will ich klagen und heulen, will entblößt und nackt einhergehen; ich will eine Wehklage halten gleich den Schakalen, und eine Trauer gleich den Straußen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Denn ihre Schläge sind tödlich; denn es kommt bis Juda, es reicht bis an das Tor meines Volkes, bis an Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Berichtet es nicht in Gath, weinet nur nicht! Zu Beth-Leaphra wälze ich mich im Staube.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Ziehe hin, Bewohnerin von Schaphir, in schimpflicher Blöße; die Bewohnerin von Zaanan ist nicht ausgezogen; die Wehklage Beth-Ezels wird dessen Rastort von euch wegnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Denn die Bewohnerin von Maroth zittert wegen ihrer Habe; denn von seiten Jehovas ist Unglück zum Tore Jerusalems herabgekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Spanne die Renner an den Wagen, Bewohnerin von Lachis! Der Anfang der Sünde war es für die Tochter Zion; denn in dir sind die Übertretungen Israels gefunden worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Darum wirst du Morescheth-Gath ein Entlassungsgeschenk geben. Die Häuser von Aksib werden zu einem trügerischen Bache für die Könige von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Noch werde ich den Besitznehmer dir bringen, Bewohnerin von Marescha. Bis Adullam werden kommen die Edlen von Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Mache dich kahl und schere dich um der Kinder deiner Wonne willen, mache deine Glatze breit wie die des Geiers; denn sie sind von dir hinweggeführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Wehe denen, die Unheil sinnen und Böses vorbereiten auf ihren Lagern! Beim Morgenlicht führen sie es aus, weil es in der Macht ihrer Hand steht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Und sie begehren nach Äckern und rauben sie, und nach Häusern und nehmen sie weg; und sie verüben Gewalttat an dem Manne und seinem Hause, an dem Menschen und seinem Erbteil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Darum, so spricht Jehova: Siehe, ich sinne ein Unglück wider dieses Geschlecht, aus dem ihr eure Hälse nicht ziehen und unter welchem ihr nicht hoch einhergehen werdet; denn es ist eine böse Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'An jenem Tage wird man einen Spruch über euch anheben und ein Klagelied anstimmen. Es ist geschehen! wird man sagen. Wir sind gänzlich verwüstet: das Teil meines Volkes vertauscht er; wie entzieht er es mir! Dem Abtrünnigen verteilt er unsere Felder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Darum wirst du niemand haben, der in der Versammlung Jehovas die Meßschnur wirft, um ein Los zu bestimmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '\"Weissaget nicht\", weissagen sie. Weissagt man nicht jenen, so wird die Schmach nicht weichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Du, Haus Jakob genannt, ist Jehova ungeduldig? Oder sind dies seine Taten? Sind meine Worte nicht gütig gegen den, der aufrichtig wandelt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Aber noch unlängst lehnte sich mein Volk als Feind auf: vom Oberkleide ziehet ihr den Mantel denen ab, die sorglos vorübergehen, vom Kriege abgewandt sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'die Weiber meines Volkes vertreibet ihr aus dem Hause ihrer Wonne, von ihren Kindern nehmet ihr meinen Schmuck auf immer. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Machet euch auf und ziehet hin! Denn dieses Land ist der Ruheort nicht, um der Verunreinigung willen, die Verderben bringt, und zwar gewaltiges Verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Wenn ein Mann da ist, der dem Winde nachgeht und betrügerisch lügt: \"Ich will dir weissagen von Wein und von starkem Getränk\", der wird ein Prophet dieses Volkes sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Sammeln werde ich dich, Jakob, ganz sammeln; versammeln, ja, versammeln werde ich den Überrest Israels. Ich werde ihn zusammenbringen wie die Schafe von Bozra, wie eine Herde inmitten ihrer Trift; sie werden lärmen vor Menge der Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Der Durchbrecher zieht herauf vor ihnen her; sie brechen durch, und ziehen durch das Tor und gehen durch dasselbe hinaus; und ihr König zieht vor ihnen her, und Jehova an ihrer Spitze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Und ich sprach: Höret doch, ihr Häupter Jakobs und ihr Fürsten des Hauses Israel: Ich es nicht an euch, das Recht zu kennen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Die ihr das Gute hasset und das Böse liebet; die ihr ihnen die Haut abziehet und das Fleisch von ihren Gebeinen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'und die ihr das Fleisch meines Volkes fresset, und ihre Haut von ihnen abstreifet, und ihre Gebeine zerbrechet und zerstücket wie in einem Topfe und wie Fleisch inmitten des Kessels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Dann werden sie zu Jehova schreien, und er wird ihnen nicht antworten; und er wird sein Angesicht vor ihnen verbergen zu jener Zeit, gleichwie sie ihre Handlungen böse gemacht haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'So spricht Jehova über die Propheten, die mein Volk irreführen, welche mit ihren Zähnen beißen, und Frieden rufen; und wer ihnen nichts ins Maul gibt, wider den heiligen sie einen Krieg:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Darum soll es euch Nacht werden, ohne Gesicht, und Finsternis werden, ohne Wahrsagung; und die Sonne wird über den Propheten untergehen, und der Tag über ihnen schwarz werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Und die Seher werden beschämt und die Wahrsager zu Schanden werden, und sie werden allesamt den Bart verhüllen, weil keine Antwort Gottes da ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Ich hingegen, ich bin mit Kraft erfüllt durch den Geist Jehovas, und mit Recht und Stärke, um Jakob seine Übertretung kundzutun und Israel seine Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Höret doch dieses, ihr Häupter des Hauses Jakob und ihr Fürsten des Hauses Israel, die ihr das Recht verabscheuet und alles Gerade krümmet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'die ihr Zion mit Blut bauet und Jerusalem mit Unrecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Seine Häupter richten um Geschenke, und seine Priester lehren um Lohn, und seine Propheten wahrsagen um Geld; und sie stützen sich auf Jehova und sagen: Ist nicht Jehova in unserer Mitte? Kein Unglück wird über uns kommen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Darum wird euretwegen Zion als Acker gepflügt werden, und Jerusalem wird zu Trümmerhaufen und der Berg des Hauses zu Waldeshöhen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Und es wird geschehen am Ende der Tage, da wird der Berg des Hauses Jehovas feststehen auf dem Gipfel der Berge und erhaben sein über die Hügel. Und Völker werden zu ihm strömen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'und viele Nationen werden hingehen und sagen: Kommt und laßt uns hinaufziehen zum Berge Jehovas und zum Hause des Gottes Jakobs! Und er wird uns belehren aus seinen Wegen, und wir wollen wandeln auf seinen Pfaden. Denn von Zion wird ausgehen das Gesetz, und das Wort Jehovas von Jerusalem;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'und er wird richten zwischen vielen Völkern und Recht sprechen mächtigen Nationen bis in die Ferne. Und sie werden ihre Schwerter zu Pflugmessern schmieden, und ihre Speere zu Winzermessern; nicht wird Nation wider Nation das Schwert erheben, und sie werden den Krieg nicht mehr lernen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Und sie werden sitzen, ein jeder unter seinem Weinstock und unter seinem Feigenbaum, und niemand wird sie aufschrecken. Denn der Mund Jehovas der Heerscharen hat geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Denn alle Völker werden wandeln, ein jedes im Namen seines Gottes; wir aber werden wandeln im Namen Jehovas, unseres Gottes, immer und ewiglich. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'An jenem Tage, spricht Jehova, werde ich das Hinkende sammeln und das Vertriebene zusammenbringen, und dem ich Übles getan habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Und ich werde das Hinkende zu einem Überrest und das Weitentfernte zu einer gewaltigen Nation machen; und Jehova wird König über sie sein auf dem Berge Zion, von nun an bis in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Und du Herdenturm, du Hügel der Tochter Zion, zu dir wird gelangen und zu dir wird kommen die frühere Herrschaft, das Königtum der Tochter Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Nun, warum erhebst du ein Geschrei? Ist kein König in dir? Oder ist dein Ratgeber umgekommen, daß dich Wehen ergriffen haben der Gebärenden gleich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Kreiße und stöhne, Tochter Zion, gleich einer Gebärenden! Denn nun wirst du aus der Stadt hinausziehen und auf dem Felde wohnen und bis nach Babel kommen. Daselbst wirst du errettet werden, daselbst wird Jehova dich aus der Hand deiner Feinde erlösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Und nun haben sich viele Nationen wider dich versammelt, die da sprechen: Sie werde entweiht, und unsere Augen mögen an Zion ihre Lust sehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Aber sie kennen nicht die Gedanken Jehovas und verstehen nicht seinen Ratschluß; denn er hat sie gesammelt, wie man Garben auf die Tenne sammelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Mache dich auf und drisch, Tochter Zion! Denn ich werde dein Horn zu Eisen und deine Hufe zu Erz machen, und du wirst viele Völker zermalmen; und ich werde ihren Raub dem Jehova verbannen, und ihr Vermögen dem Herrn der ganzen Erde. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, '(H4:14) Nun dränge dich zusammen, Tochter des Gedränges: man hat eine Belagerung gegen uns gerichtet; mit dem Stabe schlagen sie den Richter Israels auf den Backen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, '(H5:1) Und du, Bethlehem, Ephrata, zu klein, um unter den Tausenden von Juda zu sein, aus dir wird mir hervorkommen, der Herrscher über Israel sein soll; und seine Ausgänge sind von der Urzeit, von den Tagen der Ewigkeit her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, '(H5:2) Darum wird er sie dahingeben bis zur Zeit, da eine Gebärende geboren hat; und der Rest seiner Brüder wird zurückkehren samt den Kindern Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, '(H5:3) Und er wird dastehen und seine Herde weiden in der Kraft Jehovas, in der Hoheit des Namens Jehovas, seines Gottes. Und sie werden wohnen; denn nun wird er groß sein bis an die Enden der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, '(H5:4) Und dieser wird Friede sein. Wenn Assyrien in unser Land kommen und wenn es in unsere Paläste treten wird, so werden wir sieben Hirten und acht Menschenfürsten gegen dasselbe aufstellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, '(H5:5) Und sie werden das Land Assyrien mit dem Schwerte weiden, und das Land Nimrods in seinen Toren; und er wird uns von Assyrien erretten, wenn es in unser Land kommen und wenn es in unsere Grenzen treten wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, '(H5:6) Und der Überrest Jakobs wird inmitten vieler Völker sein wie ein Tau von Jehova, wie Regenschauer auf das Kraut, der nicht auf Menschen wartet und nicht auf Menschenkinder harrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, '(H5:7) Und der Überrest Jakobs wird unter den Nationen, inmitten vieler Völker, sein wie ein Löwe unter den Tieren des Waldes, wie ein junger Löwe unter den Schafherden, der, wenn er hindurchgeht, zertritt und zerreißt, und niemand errettet. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, '(H5:8) Hoch erhoben sei deine Hand über deine Bedränger, und alle deine Feinde mögen ausgerottet werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, '(H5:9) Und es wird geschehen an jenem Tage, spricht Jehova, da werde ich deine Rosse ausrotten aus deiner Mitte und deine Wagen vernichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, '(H5:10) Und ich werde ausrotten die Städte deines Landes und alle deine Festungen niederreißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, '(H5:11) Und ich werde die Wahrsagereien ausrotten aus deiner Hand, und du wirst keine Zauberer mehr haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, '(H5:12) Und ich werde deine geschnitzten Bilder und deine Bildsäulen aus deiner Mitte ausrotten, und du wirst dich nicht mehr niederwerfen vor dem Werke deiner Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, '(H5:13) Und ich werde deine Ascherim herausreißen aus deiner Mitte und deine Städte vertilgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, '(H5:14) Und ich werde in Zorn und in Grimm Rache üben an den Nationen, die nicht gehört haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Höret doch, was Jehova sagt: Mache dich auf, rechte vor den Bergen und laß die Hügel deine Stimme hören!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Höret, ihr Berge, den Rechtsstreit Jehovas, und ihr Unwandelbaren, ihr Grundfesten der Erde! Denn Jehova hat einen Rechtsstreit mit seinem Volke, und mit Israel wird er rechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, '\"Mein Volk, was habe ich dir getan, und womit habe ich dich ermüdet? Lege Zeugnis gegen mich ab!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Denn ich habe dich aus dem Lande Ägypten heraufgeführt und aus dem Diensthause dich erlöst; und ich habe Mose, Aaron und Mirjam vor dir hergesandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Mein Volk, gedenke doch, was Balak, der König von Moab, beratschlagt, und was Bileam, der Sohn Beors, ihm geantwortet hat, dessen, was von Sittim bis Gilgal geschehen ist; auf daß du die gerechten Taten Jehovas erkennest.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, '\"Womit soll ich vor Jehova treten, mich beugen vor dem Gott der Höhe? Soll ich vor ihn treten mit Brandopfern, mit einjährigen Kälbern?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Wird Jehova Wohlgefallen haben an Tausenden von Widdern, an Zehntausenden von Strömen Öls? Soll ich meinen Erstgeborenen geben für meine Übertretung, die Frucht meines Leibes für die Sünde meiner Seele?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Er hat dir kundgetan, o Mensch, was gut ist; und was fordert Jehova von dir, als Recht zu üben und Güte zu lieben, und demütig zu wandeln mit deinem Gott?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Die Stimme Jehovas ruft der Stadt, und dein Name hat Weisheit im Auge: Höret auf die Zuchtrute und auf den, der sie bestellt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Sind noch im Hause des Gesetzlosen Schätze der Gesetzlosigkeit und das knappe, verfluchte Epha?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, '\"Sollte ich rein sein bei der Waage der Gesetzlosigkeit und bei einem Beutel mit betrügerischen Gewichtsteinen?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Ihre Reichen sind voll Gewalttat, und ihre Bewohner reden Lügen, und ihre Zunge ist Trug in ihrem Munde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'So will auch ich dich unheilbar schlagen, dich verwüsten um deiner Sünden willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Du wirst essen, aber nicht satt werden; und dein Inneres wird leer bleiben. Und du wirst fortschaffen und nicht retten; und was du rettest, werde ich dem Schwerte hingeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Du wirst säen, aber nicht ernten; du wirst Oliven keltern, aber dich nicht mit Öl salben, und Most, aber keinen Wein trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Und man beobachtet eifrig die Satzungen Omris und alles Tun des Hauses Ahabs, und ihr wandelt in ihren Ratschlägen: auf daß ich dich zum Entsetzen mache und ihre Bewohner zum Gezisch; und ihr werdet die Schmach meines Volkes tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Wehe mir! Denn mir ist es wie bei der Obstlese, wie bei der Nachlese der Weinernte: keine Traube zu essen! Keine Frühfeige, die meine Seele begehrt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Der Gütige ist aus dem Lande verschwunden, und da ist kein Rechtschaffener unter den Menschen: allesamt lauern sie auf Blut, sie jagen ein jeder seinen Bruder mit dem Netze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Nach dem Bösen sind beide Hände gerichtet, um es wohl auszuführen. Der Fürst fordert, und der Richter richtet gegen Entgelt, und der Große spricht die Gier seiner Seele aus, und sie flechten es ineinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Der Beste unter ihnen ist wie ein Dornstrauch, der Rechtschaffenste wie eine Dornhecke. Der Tag deiner Wächter, deine Heimsuchung, ist gekommen; dann wird ihre Verwirrung da sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Trauet nicht dem Genossen, verlasset euch nicht auf den Vertrauten; verwahre die Pforten deines Mundes vor der, die an deinem Busen liegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Denn der Sohn verachtet den Vater, die Tochter lehnt sich auf gegen ihre Mutter, die Schwiegertochter gegen ihre Schwiegermutter; des Mannes Feinde sind seine Hausgenossen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Ich aber will nach Jehova ausschauen, will harren auf den Gott meines Heils; mein Gott wird mich erhören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Freue dich nicht über mich, meine Feindin! Denn bin ich gefallen, so stehe ich wieder auf; denn sitze ich in Finsternis, so ist Jehova mein Licht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Den Grimm Jehovas will ich tragen, denn ich habe gegen ihn gesündigt, bis er meinen Rechtsstreit führen und mir Recht verschaffen wird. Er wird mich herausführen an das Licht, ich werde seine Gerechtigkeit anschauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Und meine Feindin soll es sehen, und Scham soll sie bedecken, die zu mir sprach: Wo ist Jehova, dein Gott? Meine Augen werden ihre Lust an ihr sehen: nun wird sie zertreten werden wie Straßenkot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Ein Tag kommt, um deine Mauern aufzubauen. An jenem Tage wird die Schranke entfernt werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'an jenem Tage, da wird man zu dir kommen von Assyrien und den Städten Mazors, und von Mazor bis zum Strome und von Meer zu Meer und von Gebirge zu Gebirge. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Und das Land wird zur Wüste werden um seiner Bewohner willen, wegen der Frucht ihrer Handlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, '\"Weide dein Volk mit deinem Stabe, die Herde deines Erbteils, die abgesondert wohnt im Walde, inmitten des Karmel; laß sie weiden in Basan und Gilead, wie in den Tagen der Vorzeit.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Wie in den Tagen, da du aus dem Lande Ägypten zogest, werde ich es Wunder sehen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Die Nationen werden es sehen und beschämt werden über all ihre Macht: sie werden die Hand auf den Mund legen, ihre Ohren werden taub werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'sie werden Staub lecken wie die Schlange, wie die kriechenden Tiere der Erde; sie werden hervorzittern aus ihren Schlössern; sie werden sich bebend wenden zu Jehova, unserem Gott, und vor dir sich fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Wer ist ein Gott wie du, der die Ungerechtigkeit vergibt, und die Übertretung des Überrestes seines Erbteils übersieht? Er behält seinen Zorn nicht auf immer, denn er hat Gefallen an Güte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Er wird sich unser wieder erbarmen, wird unsere Ungerechtigkeiten niedertreten; und du wirst alle ihre Sünden in die Tiefen des Meeres werfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Du wirst an Jakob Wahrheit, an Abraham Güte erweisen, die du von den Tagen der Vorzeit her unseren Vätern geschworen hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Ausspruch über Ninive. Das Buch des Gesichtes Nahums, des Elkoschiters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Ein eifernder und rächender Gott ist Jehova, ein Rächer ist Jehova und voll von Grimm; Jehova übt Rache an seinen Widersachern und trägt seinen Feinden nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Jehova ist langsam zum Zorn und groß an Kraft, und er hält keineswegs für schuldlos den Schuldigen. Jehova, im Sturmwind und im Gewitter ist sein Weg, und Gewölk ist der Staub seiner Füße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Er schilt das Meer und legt es trocken, und alle Flüsse macht er versiegen; Basan und Karmel verwelken, und es verwelkt die Blüte des Libanon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Vor ihm erbeben die Berge und zerfließen die Hügel, und vor seinem Angesicht erhebt sich die Erde, und der Erdkreis und alle, die darauf wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Wer kann vor seinem Grimm bestehen, und wer standhalten bei der Glut seines Zornes? Sein Grimm ergießt sich wie Feuer, und die Felsen werden von ihm zerrissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Jehova ist gütig, er ist eine Feste am Tage der Drangsal; und er kennt die, welche auf ihn vertrauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Und mit einer überschwemmenden Flut wird er ihre Stätte gänzlich zerstören, und Finsternis wird seine Feinde verfolgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Was sinnet ihr wider Jehova? Er wird gänzlich zerstören; die Drangsal wird nicht zweimal erstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Denn wären sie gar wie Dornen verflochten und von ihrem edlen Weine berauscht, sie sollen völlig verzehrt werden wie dürre Stoppeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Von dir ist ausgegangen, der Böses sann wider Jehova, ein nichtswürdiger Ratgeber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'So spricht Jehova: Wenn sie gleich unversehrt und noch so zahlreich sind, auch so sollen sie weggemäht werden; und er wird dahin sein. Und habe ich dich auch niedergebeugt, ich werde dich nicht mehr niederbeugen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'sondern ich werde nun sein Joch von dir zerbrechen und deine Bande zerreißen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Und über dich hat Jehova geboten, daß von deinem Namen nicht mehr gesät werden soll; aus dem Hause deines Gottes werde ich das geschnitzte und das gegossene Bild ausrotten; ich werde dir ein Grab machen, denn verächtlich bist du.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Siehe, auf den Bergen die Füße dessen, der gute Botschaft bringt, der Frieden verkündigt! Feiere, Juda, deine Feste, bezahle deine Gelübde! Denn der Nichtswürdige wird fortan nicht mehr durch dich ziehen; er ist ganz ausgerottet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Der Zerschmetterer zieht wider dich herauf. Bewahre die Festung; überwache den Weg, stärke deine Lenden, befestige sehr deine Kraft!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Denn Jehova stellt die Herrlichkeit Jakobs wie die Herrlichkeit Israels wieder her; denn die Plünderer haben sie geplündert und haben ihre Reben zerstört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Die Schilde seiner Helden sind gerötet, die tapferen Männer sind in Karmesin gekleidet, die Wagen glänzen von Stahl am Tage seines Rüstens, und die Lanzen werden geschwungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Die Wagen rasen auf den Straßen, sie rennen auf den Plätzen, ihr Aussehen ist wie Fackeln, wie Blitze fahren sie daher. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Er gedenkt seiner Edlen: sie straucheln auf ihren Wegen, sie eilen zu ihrer Mauer, und das Schutzdach wird aufgerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Die Tore an den Strömen sind geöffnet, und der Palast verzagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Denn es ist beschlossen: sie wird entblößt, weggeführt; und ihre Mägde stöhnen wie die Stimme der Tauben, sie schlagen an ihre Brust.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Ninive war ja von jeher wie ein Wasserteich; und doch fliehen sie! Stehet, stehet! Aber keiner sieht sich um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Raubet Silber, raubet Gold! Denn unendlich ist der Vorrat, der Reichtum an allerlei kostbaren Geräten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Leere und Entleerung und Verödung! Und das Herz zerfließt, und die Knie wanken, und in allen Lenden ist Schmerz, und ihrer aller Angesichter erblassen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Wo ist nun die Wohnung der Löwen, und der Weideort der jungen Löwen, wo der Löwe wandelte, die Löwin und das Junge des Löwen, und niemand sie aufschreckte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Der Löwe raubte für den Bedarf seiner Jungen und erwürgte für seine Löwinnen, und er füllte seine Höhlen mit Raub und seine Wohnungen mit Geraubtem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Siehe, ich will an dich, spricht Jehova der Heerscharen, und ich werde ihre Wagen in Rauch aufgehen lassen, und deine jungen Löwen wird das Schwert verzehren; und ich werde deinen Raub von der Erde ausrotten, und die Stimme deiner Boten wird nicht mehr gehört werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Wehe der Blutstadt, ganz erfüllt mit Lüge und Gewalttat! Das Rauben hört nicht auf. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Peitschenknall und Getöse des Rädergerassels, und jagende Rosse und aufspringende Wagen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'heransprengende Reiter, und flammendes Schwert und blitzender Speer! Und Mengen Erschlagener und Haufen von Toten und Leichen ohne Ende; man strauchelt über ihre Leichen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Wegen der vielen Hurereien der anmutvollen Hure, der Zauberkundigen, welche Nationen verkauft mit ihren Hurereien und Geschlechter mit ihren Zaubereien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Siehe, ich will an dich, spricht Jehova der Heerscharen; und ich werde deine Säume aufdecken über dein Angesicht, und die Nationen deine Blöße sehen lassen und die Königreiche deine Schande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Und ich werde Unrat auf dich werfen, und dich verächtlich machen und dich zur Schau stellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Und es wird geschehen, jeder, der dich sieht, wird von dir fliehen und sprechen: Ninive ist verwüstet! Wer wird ihr Beileid bezeigen? Woher soll ich dir Tröster suchen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Bist du vorzüglicher als No-Ammon, die an den Strömen wohnte, Wasser rings um sich her? Das Meer war ihr Bollwerk, aus Meer bestand ihre Mauer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Äthiopien war ihre Stärke und Ägypter in zahlloser Menge; Put und Libyen waren zu ihrer Hilfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Auch sie ist in die Verbannung, in die Gefangenschaft gezogen; auch ihre Kinder wurden zerschmettert an allen Straßenecken; und über ihre Vornehmen warf man das Los, und alle ihre Großen wurden mit Ketten gefesselt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Auch du sollst trunken werden, sollst verborgen sein; auch du wirst eine Zuflucht suchen vor dem Feinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Alle deine Festungen sind Feigenbäume mit Frühfeigen; wenn sie geschüttelt werden, so fallen sie den Essenden in den Mund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Siehe, dein Volk ist zu Weibern geworden in deiner Mitte; deinen Feinden sind die Tore deines Landes weit aufgetan, Feuer verzehrt deine Riegel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Schöpfe dir Wasser für die Belagerung; bessere deine Festungswerke aus! Tritt den Ton stampfe den Lehm, stelle den Ziegelofen wieder her!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Dort wird das Feuer dich verzehren, wird das Schwert dich ausrotten, dich verzehren wie der Jelek. Vermehre dich wie der Jelek, vermehre dich wie die Heuschrecken!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Du hast deiner Kaufleute mehr gemacht als die Sterne des Himmels: der Jelek fällt raubend ein und fliegt davon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Deine Auserlesenen sind wie die Heuschrecken, und deine Kriegsobersten wie Heuschreckenschwärme, die sich an den Zäunen lagern am Tage des Frostes: geht die Sonne auf, so entfliehen sie, und man weiß ihre Stätte nicht; wo sind sie?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Deine Hirten schlafen, König von Assyrien, deine Edlen liegen da; dein Volk ist auf den Bergen zerstreut, und niemand sammelt es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Keine Linderung für deine Wunde, dein Schlag ist tödlich! Alle, welche die Kunde von dir hören, klatschen über dich in die Hände; denn über wen ist nicht deine Bosheit beständig ergangen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Der Ausspruch, welchen Habakuk, der Prophet, geschaut hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Wie lange, Jehova, habe ich gerufen, und du hörst nicht! Ich schreie zu dir: Gewalttat! und du rettest nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Warum läßt du mich Unheil sehen, und schaust Mühsal an? Und Verwüstung und Gewalttat sind vor mir, und Streit entsteht, und Hader erhebt sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Darum wird das Gesetz kraftlos, und das Recht kommt nimmermehr hervor; denn der Gesetzlose umzingelt den Gerechten: darum kommt das Recht verdreht hervor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Sehet unter den Nationen und schauet und erstaunet, staunet; denn ich wirke ein Werk in euren Tagen, ihr würdet es nicht glauben, wenn es erzählt würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Denn siehe, ich erwecke die Chaldäer, das grimmige und ungestüme Volk, welches die Breiten der Erde durchzieht, um Wohnungen in Besitz zu nehmen, die ihm nicht gehören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Es ist schrecklich und furchtbar; sein Recht und seine Hoheit gehen von ihm aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Und schneller als Pardel sind seine Rosse und rascher als Abendwölfe; und seine Reiter sprengen einher, und seine Reiter kommen von ferne, fliegen herbei wie ein Adler, der zum Fraße eilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Sie kommen zur Gewalttat allesamt; das Streben ihrer Angesichter ist vorwärts gerichtet, und Gefangene rafft es zusammen wie Sand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Und es spottet der Könige, und Fürsten sind ihm ein Gelächter; es lacht jeder Festung, und es schüttet Erde auf und nimmt sie ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Dann fährt es daher wie der Wind, und zieht weiter und verschuldet sich: diese seine Kraft ist sein Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Bist du nicht von alters her, Jehova, mein Gott, mein Heiliger? Wir werden nicht sterben. Jehova, zum Gericht hast du es gesetzt, und, o Fels, zur Züchtigung es bestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Du bist zu rein von Augen, um Böses zu sehen, und Mühsal vermagst du nicht anzuschauen. Warum schaust du Räubern zu, schweigst, wenn der Gesetzlose den verschlingt, der gerechter ist als er?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Und machst die Menschen wie die Fische des Meeres, wie das Gewürm, das keinen Herrscher hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Er hebt sie alle mit der Angel herauf, er zieht sie herbei mit seinem Netze und sammelt sie in sein Garn; darum freut er sich und jubelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Darum opfert er seinem Netze und räuchert seinem Garne, denn durch sie ist sein Teil fett und seine Speise feist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Soll er deshalb sein Netz ausleeren, und beständig darauf ausgehen, Nationen schonungslos hinzumorden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Auf meine Warte will ich treten und auf den Turm mich stellen, und will spähen, um zu sehen, was er mit mir reden wird, und was ich erwidern soll auf meine Klage. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Da antwortete mir Jehova und sprach: Schreibe das Gesicht auf, und grabe es in Tafeln ein, damit man es geläufig lesen könne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'denn das Gesicht geht noch auf die bestimmte Zeit, und es strebt nach dem Ende hin und lügt nicht. Wenn es verzieht, so harre sein; denn kommen wird es, es wird nicht ausbleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Siehe, aufgeblasen, nicht aufrichtig ist in ihm seine Seele. Der Gerechte aber wird durch seinen Glauben leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Und überdies: Der Wein ist treulos; der übermütige Mann, der bleibt nicht, er, der seinen Schlund weit aufsperrt wie der Scheol, und er ist wie der Tod und wird nicht satt; und er rafft an sich alle Nationen und sammelt zu sich alle Völker.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Werden nicht diese alle über ihn einen Spruch und eine Spottrede anheben, Rätsel auf ihn? Und man wird sagen: Wehe dem, der aufhäuft, was nicht sein ist! auf wie lange? Und der Pfandlast auf sich ladet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Und werden nicht plötzlich aufstehen, die dich beißen, und aufwachen, die dich fortscheuchen werden? Und du wirst ihnen zur Beute werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Denn du, du hast viele Nationen beraubt; und so werden alle übriggebliebenen Völker dich berauben wegen des Blutes der Menschen und der Gewalttat an Land und Stadt und an allen ihren Bewohnern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Wehe dem, der bösen Gewinn macht für sein Haus, um sein Nest hoch zu setzen, um sich zu retten aus der Hand des Unglücks!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Du hast Schande beratschlagt für dein Haus, die Vertilgung vieler Völker, und hast dein Leben verschuldet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Denn der Stein wird schreien aus der Mauer, und der Sparren aus dem Holzwerk ihm antworten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Wehe dem, der Städte mit Blut baut, und Städte mit Ungerechtigkeit gründet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Siehe, ist es nicht von Jehova der Heerscharen, daß Völker fürs Feuer sich abmühen, und Völkerschaften vergebens sich plagen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Denn die Erde wird voll werden von der Erkenntnis der Herrlichkeit Jehovas, gleichwie die Wasser den Meeresgrund bedecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Wehe dem, der seinem Nächsten zu trinken gibt, indem du deinen Zorn beimischest, und sie auch trunken machst, um ihre Blöße anzuschauen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Du hast mit Schande dich gesättigt anstatt mit Ehre: trinke auch du und zeige dein Unbeschnittensein; der Becher der Rechten Jehovas wird sich zu dir wenden, und schimpfliche Schande über deine Herrlichkeit kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Denn die Gewalttat am Libanon wird dich bedecken, und die Zerstörung der Tiere, welche sie in Schrecken setzte: wegen des Blutes der Menschen und der Gewalttat an Land und Stadt und an allen ihren Bewohnern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Was nützt ein geschnitztes Bild, daß sein Bildner es geschnitzt hat? Ein gegossenes Bild, und welches Lügen lehrt, daß der Bildner seines Bildes darauf vertraut, um stumme Götzen zu machen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Wehe dem, der zum Holze spricht: Wache auf! Zum schweigenden Steine: Erwache! Er sollte lehren? Siehe, er ist mit Gold und Silber überzogen, und gar kein Odem ist in seinem Innern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Aber Jehova ist in seinem heiligen Palast, schweige vor ihm, ganze Erde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Gebet Habakuks, des Propheten, nach Schigjonoth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Jehova, ich habe deine Kunde vernommen, ich fürchte mich; Jehova, belebe dein Werk inmitten der Jahre, inmitten der Jahre mache es kund; im Zorn gedenke des Erbarmens! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Gott kommt von Teman her, und der Heilige vom Gebirge Paran. (Sela.) Seine Pracht bedeckt die Himmel, und die Erde ist voll seines Ruhmes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Und es entsteht ein Glanz wie das Sonnenlicht; Strahlen sind zu seinen Seiten, und daselbst ist die Hülle seiner Macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Vor ihm her geht die Pest, und die Seuche zieht aus, seinen Füßen nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Er stand und machte die Erde schwanken, er schaute und machte aufbeben die Nationen; und es zerbarsten die Berge der Vorzeit, es senkten sich die ewigen Hügel; seine Wege sind die Wege vor alters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Unter Trübsal sah ich die Zelte Kuschans, es zitterten die Zeltbehänge des Landes Midian.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Ist Jehova wider die Ströme entbrannt? Ist etwa dein Zorn wider die Ströme, dein Grimm wider das Meer, daß du einherziehst auf deinen Rossen, deinen Wagen des Heils?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Entblößt, entblößt ist dein Bogen... Zuchtruten, geschworen durch dein Wort! (Sela.) Zu Strömen spaltest du die Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Es sahen dich, es zitterten die Berge; eine Wasserflut fuhr daher, die Tiefe ließ ihre Stimme erschallen, zur Höhe erhob sie ihre Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Sonne und Mond traten in ihre Wohnung beim Lichte deiner Pfeile, welche daherschossen, beim Glanze deines blitzenden Speeres.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Im Grimme duchschreitest du die Erde, im Zorne stampfest du die Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Du zogest aus zum Heile deines Volkes, zum Heile deines Gesalbten: du zerschmettertest das Haupt vom Hause des Gesetzlosen, entblößend den Grund bis zum Halse. (Sela.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Du durchbohrtest mit seinen eigenen Spießen die Häupter seiner Scharen, welche heranstürmten, mich zu zerstäuben, deren Frohlocken war, den Elenden im Verborgenen zu verschlingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Du betratest das Meer mit deinen Rossen, den Schwall großer Wasser. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Ich vernahm es, und es zitterte mein Leib; bei der Stimme bebten meine Lippen; Morschheit drang in meine Gebeine, und wo ich stand, erzitterte ich: der ich ruhen werde am Tage der Drangsal, wenn derjenige gegen das Volk heranzieht, der es angreifen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Denn der Feigenbaum wird nicht blühen, und kein Ertrag wird an den Reben sein; und es trügt die Frucht des Olivenbaumes, und die Getreidefelder tragen keine Speise; aus der Hürde ist verschwunden das Kleinvieh, und kein Rind ist in den Ställen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Ich aber, ich will in Jehova frohlocken, will jubeln in dem Gott meines Heils.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Jehova, der Herr, ist meine Kraft, und macht meine Füße denen der Hindinnen gleich und läßt mich einherschreiten auf meinen Höhen. Dem Vorsänger, mit meinem Saitenspiel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Das Wort Jehovas, welches zu Zephanja geschah, dem Sohne Kuschis, des Sohnes Gedaljas, des Sohnes Amarjas, des Sohnes Hiskijas, in den Tagen Josias, des Sohnes Amons, des Königs von Juda.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Ich werde alles von der Fläche des Erdbodens gänzlich wegraffen, spricht Jehova;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'ich werde Menschen und Vieh wegraffen, ich werde wegraffen die Vögel des Himmels und die Fische des Meeres, und die Ärgernisse samt den Gesetzlosen; und ich werde die Menschen ausrotten von der Fläche des Erdbodens, spricht Jehova. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Und ich werde meine Hand ausstrecken wider Juda und wider alle Bewohner von Jerusalem. Und ich werde aus diesem Orte den Überrest des Baal, den Namen der Götzenpriester samt den Priestern ausrotten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'und die auf den Dächern das Heer des Himmels anbeten, und die Anbetenden, welche dem Jehova schwören und bei ihrem König schwören;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'und die von Jehova zurückweichen, und die Jehova nicht suchen noch nach ihm fragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Still vor dem Herrn Jehova! Denn nahe ist der Tag Jehovas; denn Jehova hat ein Schlachtopfer bereitet, er hat seine Geladenen geheiligt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Und es wird geschehen an dem Tage des Schlachtopfers Jehovas, da werde ich die Fürsten und die Königssöhne heimsuchen und alle, die sich mit fremder Kleidung bekleiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Und an jenem Tage werde ich einen jeden heimsuchen, der über die Schwelle springt, alle, die das Haus ihres Herrn mit Gewalttat und Betrug erfüllen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'Und an jenem Tage, spricht Jehova, wird ein Geschrei erschallen vom Fischtore her, und ein Geheul von der Unterstadt, und lautes Jammern von den Hügeln her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Heulet, ihr Bewohner von Maktesch! Denn alles Krämervolk ist vernichtet, alle mit Silber Beladenen sind ausgerottet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Und es wird geschehen zu jener Zeit, da werde ich Jerusalem mit Leuchten durchsuchen; und ich werde die Männer heimsuchen, welche auf ihren Hefen liegen, die in ihrem Herzen sprechen: Jehova tut nichts Gutes und tut nichts Böses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Und ihr Vermögen wird zum Raube, und ihre Häuser werden zur Wüste werden; und sie werden Häuser bauen und sie nicht bewohnen, und Weinberge pflanzen und deren Wein nicht trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Nahe ist der große Tag Jehovas; er ist nahe und eilt sehr. Horch, der Tag Jehovas! Bitterlich schreit dort der Held.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Ein Tag des Grimmes ist dieser Tag, ein Tag der Drangsal und der Bedrängnis, ein Tag des Verwüstens und der Verwüstung, ein Tag der Finsternis und der Dunkelheit, ein Tag des Gewölks und des Wolkendunkels,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'ein Tag der Posaune und des Kriegsgeschreis wider die festen Städte und wider die hohen Zinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Und ich werde die Menschen ängstigen, und sie werden einhergehen wie die Blinden, weil sie gegen Jehova gesündigt haben; und ihr Blut wird verschüttet werden wie Staub, und ihr Fleisch wie Kot;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'auch ihr Silber, auch ihr Gold wird sie nicht erretten können am Tage des Grimmes Jehovas; und durch das Feuer seines Eifers wird das ganze Land verzehrt werden. Denn ein Ende, ja, ein plötzliches Ende wird er machen mit allen Bewohnern des Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Gehet in euch und sammelt euch, du Nation ohne Scham,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'ehe der Beschluß gebiert, wie Spreu fährt der Tag daher, ehe denn über euch komme die Glut des Zornes Jehovas, ehe denn über euch komme der Tag des Zornes Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Suchet Jehova, alle ihr Sanftmütigen des Landes, die ihr sein Recht gewirkt habt; suchet Gerechtigkeit, suchet Demut; vielleicht werdet ihr geborgen am Tage des Zornes Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Denn Gasa wird verlassen und Askalon eine Wüste sein; Asdod: am hellen Mittag wird man es vertreiben, und Ekron wird entwurzelt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Wehe den Bewohnern des Landstrichs am Meere, der Nation der Kerethiter! Das Wort Jehovas kommt über euch, Kanaan, Land der Philister! Und ich werde dich vernichten, daß kein Bewohner mehr bleibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Und der Landstrich am Meere wird zu Triften voll Hirtenzisternen und Kleinviehhürden werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'und es wird ein Landstrich sein für den Überrest des Hauses Juda: sie werden darauf weiden und am Abend sich lagern in den Häusern Askalons; denn Jehova, ihr Gott, wird sich ihrer annehmen und ihre Gefangenschaft wenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Ich habe gehört die Schmähung Moabs und die Lästerungen der Kinder Ammon, womit sie mein Volk geschmäht und großgetan haben wider dessen Gebiet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Darum, so wahr ich lebe, spricht Jehova der Heerscharen, der Gott Israels, soll Moab gewißlich wie Sodom, und die Kinder Ammon wie Gomorra werden, ein Besitztum der Brennesseln und eine Salzgrube und eine Wüste ewiglich. Der Überrest meines Volkes wird sie berauben, und das Überbleibsel meiner Nation sie beerben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Solches wird ihnen für ihren Hochmut zuteil, weil sie das Volk Jehovas der Heerscharen geschmäht und wider dasselbe großgetan haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Furchtbar wird Jehova wider sie sein, denn er wird hinschwinden lassen alle Götter der Erde; und alle Inseln der Nationen werden ihn anbeten, ein jeder von seiner Stätte aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Auch ihr, Äthiopier, werdet Erschlagene meines Schwertes sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Und er wird seine Hand gegen Norden ausstrecken, und wird Assyrien vernichten und Ninive zur Wüste machen, dürr wie die Steppe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Und in seiner Mitte werden Herden sich lagern, allerlei Tiere in Menge; auch Pelikane, auch Igel werden auf seinen Säulenknäufen übernachten. Eine Stimme singt im Fenster, Trümmer sind auf der Schwelle, denn er hat das Zederngetäfel bloßgelegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Das ist die frohlockende Stadt, die in Sicherheit wohnte, die in ihrem Herzen sprach: Ich bin\'s und gar keine sonst! Wie ist sie zur Wüste geworden, zum Lagerplatz der wilden Tiere! Ein jeder, der an ihr vorüberzieht, wird zischen, wird seine Hand schwenken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Wehe der Widerspenstigen und Befleckten, der bedrückenden Stadt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Sie hat auf keine Stimme gehört, keine Zucht angenommen; auf Jehova hat sie nicht vertraut, ihrem Gott sich nicht genaht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Ihre Fürsten in ihrer Mitte sind brüllende Löwen; ihre Richter sind Abendwölfe, die nichts für den Morgen übriglassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Ihre Propheten sind Prahler, treulose Männer; ihre Priester entweihen das Heiligtum, tun dem Gesetze Gewalt an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Jehova ist gerecht in ihrer Mitte, er tut kein Unrecht; Morgen für Morgen stellt er sein Recht ans Licht, ohne zu fehlen. Aber der Ungerechte kennt keine Scham.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Ich habe Nationen ausgerottet, ihre Zinnen sind verödet; ich habe ihre Straßen verwüstet, daß niemand darüber zieht; ihre Städte sind verheert, daß niemand da ist, kein Bewohner mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Ich sprach: Möchtest du mich nur fürchten, möchtest du Zucht annehmen! Und ihre Wohnung würde nicht ausgerottet werden, alles, was ich über sie verhängt habe. Allein sie haben sich früh aufgemacht, haben alle ihre Handlungen verderbt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Darum harret auf mich, spricht Jehova, auf den Tag, da ich mich aufmache zur Beute! Denn mein Rechtsspruch ist, die Nationen zu versammeln, die Königreiche zusammenzubringen, um meinen Grimm über sie auszugießen, die ganze Glut meines Zornes; denn durch das Feuer meines Eifers wird die ganze Erde verzehrt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Denn alsdann werde ich die Lippen der Völker in reine Lippen umwandeln, damit sie alle den Namen Jehovas anrufen und ihm einmütig dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Von jenseit der Ströme Äthiopiens werden sie meine Flehenden, meine zerstreute Schar, mir als Opfergabe darbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'An jenem Tage wirst du dich nicht mehr all deiner Handlungen schämen müssen, womit du wider mich übertreten hast; denn alsdann werde ich deine stolz Frohlockenden aus deiner Mitte wegnehmen, und du wirst fortan nicht mehr hoffärtig sein auf meinem heiligen Berge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Und ich werde in deiner Mitte ein elendes und armes Volk übriglassen, und sie werden auf den Namen Jehovas vertrauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Der Überrest Israels wird kein Unrecht tun und keine Lüge reden, und in ihrem Munde wird keine Zunge des Truges gefunden werden; denn sie werden weiden und lagern, und niemand wird sie aufschrecken. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Jubele, Tochter Zion; jauchze, Israel! Freue dich und frohlocke von ganzem Herzen, Tochter Jerusalem!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Jehova hat deine Gerichte weggenommen, deinen Feind weggefegt; der König Israels, Jehova, ist in deiner Mitte, du wirst kein Unglück mehr sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'An jenem Tage wird zu Jerusalem gesagt werden: Fürchte dich nicht! Zion, laß deine Hände nicht erschlaffen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Jehova, dein Gott, ist in deiner Mitte, ein rettender Held; er freut sich über dich mit Wonne, er schweigt in seiner Liebe, frohlockt über dich mit Jubel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Die wegen der Festversammlung Trauernden werde ich sammeln; sie waren aus dir, Schmach lastete auf ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Siehe, ich werde zu jener Zeit handeln mit allen deinen Bedrückern, und die Hinkenden retten und die Vertriebenen sammeln; und ich werde sie zum Lobe und zum Namen machen in allen Ländern ihrer Schmach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'In jener Zeit werde ich euch herbeibringen und zu der Zeit euch sammeln; denn ich werde euch zum Namen und zum Lobe machen unter allen Völkern der Erde, wenn ich eure Gefangenschaft vor euren Augen wenden werde, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Im zweiten Jahre des Königs Darius, im sechsten Monat, am ersten Tage des Monats, geschah das Wort Jehovas durch den Propheten Haggai zu Serubbabel, dem Sohne Schealtiels, dem Landpfleger von Juda, und zu Josua, dem Sohne Jozadaks, dem Hohenpriester, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'So spricht Jehova der Heerscharen und sagt: Dieses Volk spricht: Die Zeit ist nicht gekommen, die Zeit, daß das Haus Jehovas gebaut werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Und das Wort Jehovas geschah durch den Propheten Haggai also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Ist es für euch selbst Zeit, in euren getäfelten Häusern zu wohnen, während dieses Haus wüst liegt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Und nun, so spricht Jehova der Heerscharen: Richtet eurer Herz auf eure Wege!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Ihr habt viel gesät und wenig eingebracht; ihr esset, aber nicht zur Sättigung; ihr trinket, aber nicht zur Genüge; ihr kleidet euch, aber es wird keinem warm; und der Lohnarbeiter erwirbt Lohn für einen durchlöcherten Beutel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'So spricht Jehova der Heerscharen: Richtet euer Herz auf eure Wege!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Steiget auf das Gebirge und bringet Holz herbei und bauet das Haus, so werde ich Wohlgefallen daran haben und verherrlicht werden, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Ihr habt nach vielem ausgeschaut, und siehe, es wurde wenig; und brachtet ihr es heim, so blies ich darein. Weshalb das? spricht Jehova der Heerscharen; wegen meines Hauses, das wüst liegt, während ihr laufet, ein jeder für sein eigenes Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Darum hat der Himmel den Tau über euch zurückgehalten, und die Erde ihren Ertrag zurückgehalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Und ich habe eine Dürre gerufen über das Land und über die Berge, und über das Korn und über den Most und über das Öl, und über das, was der Erdboden hervorbringt, und über die Menschen und über das Vieh, und über alle Arbeit der Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Und Serubbabel, der Sohn Schealtiels, und Josua, der Sohn Jozadaks, der Hohepriester, und der ganze Überrest des Volkes hörten auf die Stimme Jehovas, ihres Gottes, und auf die Worte des Propheten Haggai, so wie Jehova, ihr Gott, ihn gesandt hatte; und das Volk fürchtete sich vor Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Da sprach Haggai, der Bote Jehovas, vermöge der Botschaft Jehovas, zu dem Volke und sagte: Ich bin mit euch, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Und Jehova erweckte den Geist Serubbabels, des Sohnes Schealtiels, des Landpflegers von Juda, und den Geist Josuas, des Sohnes Jozadaks, des Hohenpriesters, und den Geist des ganzen Überrestes des Volkes; und sie kamen und arbeiteten am Hause Jehovas der Heerscharen, ihres Gottes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'am vierundzwanzigsten Tage des sechsten Monats, im zweiten Jahre des Königs Darius.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Im siebten Monat, am Einundzwanzigsten des Monats, geschah das Wort Jehovas durch den Propheten Haggai also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Rede doch zu Serubbabel, dem Sohne Schealtiels, dem Landpfleger von Juda, und zu Josua, dem Sohne Jozadaks, dem Hohenpriester, und zu dem Überrest des Volkes, und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Wer ist unter euch übriggeblieben, der dieses Haus in seiner früheren Herrlichkeit gesehen hat? Und wie sehet ihr es jetzt? Ist es nicht wie nichts in euren Augen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Und nun sei stark, Serubbabel, spricht Jehova; und sei stark, Josua, Sohn Jozadaks, du Hoherpriester, und seid stark, alles Volk des Landes, spricht Jehova, und arbeitet! Denn ich bin mit euch, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Das Wort, welches ich mit euch eingegangen bin, als ihr aus Ägypten zoget, und mein Geist bestehen in eurer Mitte: Fürchtet euch nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Denn so spricht Jehova der Heerscharen: Noch einmal, eine kleine Weile ist es, da werde ich den Himmel erschüttern und die Erde und das Meer und das Trockene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Und ich werde alle Nationen erschüttern; und das Ersehnte aller Nationen wird kommen, und ich werde dieses Haus mit Herrlichkeit füllen, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Mein ist das Silber und mein das Gold, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Die letzte Herrlichkeit dieses Hauses wird größer sein als die erste, spricht Jehova der Heerscharen; und an diesem Orte will ich Frieden geben, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Am Vierundzwanzigsten des neunten Monats, im zweiten Jahre des Darius, geschah das Wort Jehovas zu dem Propheten Haggai also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'So spricht Jehova der Heerscharen: Frage doch die Priester über das Gesetz und sprich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Siehe, trägt jemand heiliges Fleisch im Zipfel seines Kleides, und er berührt mit seinem Zipfel Brot oder Gekochtes oder Wein oder Öl oder irgend eine Speise, wird es heilig werden? Und die Priester antworteten und sprachen: Nein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Und Haggai sprach: Wenn ein wegen einer Leiche Verunreinigter alles dieses anrührt, wird es unrein werden? Und die Priester antworteten und sprachen: Es wird unrein werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Da antwortete Haggai und sprach: Also ist dieses Volk und also diese Nation vor mir, spricht Jehova, und also ist alles Tun ihrer Hände; und was sie daselbst darbringen, ist unrein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Und nun richtet doch euer Herz auf die Zeit von diesem Tage an und aufwärts, ehe Stein auf Stein gelegt wurde am Tempel Jehovas!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Bevor dieses geschah: Kam man zu einem Garbenhaufen von zwanzig Maß, so wurden es zehn; kam man zu der Kufe, um fünfzig Eimer zu schöpfen, so wurden es zwanzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Ich schlug euch mit Kornbrand und mit Vergilben, und mit Hagel alle Arbeit eurer Hände; und ihr kehrtet nicht zu mir um, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Richtet doch euer Herz auf die Zeit von diesem Tage an und aufwärts; von dem vierundzwanzigsten Tage des neunten Monats an, von dem Tage an, da der Tempel Jehovas gegründet wurde, richtet euer Herz darauf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Ist noch die Saat auf dem Speicher? Ja, sogar der Weinstock und der Feigenbaum und der Granatbaum und der Olivenbaum haben nichts getragen. Von diesem Tage an will ich segnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Und das Wort Jehovas geschah zum zweiten Male zu Haggai, am Vierundzwanzigsten des Monats, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Rede zu Serubbabel, dem Landpfleger von Juda, und sprich: Ich werde den Himmel und die Erde erschüttern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Und ich werde den Thron der Königreiche umstürzen und die Macht der Königreiche der Nationen vernichten; und ich werde die Streitwagen umstürzen und die darauf fahren; und die Rosse und ihre Reiter sollen hinfallen, ein jeder durch das Schwert des anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'An jenem Tage, spricht Jehova der Heerscharen, werde ich dich nehmen, Serubbabel, Sohn Schealtiels, meinen Knecht, spricht Jehova, und werde dich wie einen Siegelring machen; denn ich habe dich erwählt, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Im achten Monat, im zweiten Jahre des Darius, geschah das Wort Jehovas zu Sacharja, dem Sohne Berekjas, des Sohnes Iddos, dem Propheten, also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Jehova ist heftig erzürnt gewesen über eure Väter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Und sprich zu ihnen: So spricht Jehova der Heerscharen: Kehret zu mir um, spricht Jehova der Heerscharen, und ich werde zu euch umkehren, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Seid nicht wie eure Väter, denen die früheren Propheten zuriefen und sprachen: So spricht Jehova der Heerscharen: Kehret doch um von euren bösen Wegen und von euren bösen Handlungen! aber sie hörten nicht und merkten nicht auf mich, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Eure Väter, wo sind sie? Und die Propheten, leben sie ewiglich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Doch meine Worte und meine Beschlüsse, welche ich meinen Knechten, den Propheten, gebot, haben sie eure Väter nicht getroffen? Und sie kehrten um und sprachen: So wie Jehova der Heerscharen vorhatte, uns nach unseren Wegen und nach unseren Handlungen zu tun, also hat er mit uns getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Am vierundzwanzigsten Tage, im elften Monat, das ist der Monat Schebat, im zweiten Jahre des Darius, geschah das Wort Jehovas zu Sacharja, dem Sohne Berekjas, des Sohnes Iddos, dem Propheten, also: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Ich schaute des Nachts, und siehe, ein Mann, der auf einem roten Rosse ritt; und er hielt zwischen den Myrten, welche im Talgrunde waren, und hinter ihm waren rote, hellrote und weiße Rosse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Und ich sprach: Mein Herr, wer sind diese? Und der Engel, der mit mir redete, sprach zu mir: Ich will dir zeigen, wer diese sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Und der Mann, der zwischen den Myrten hielt, antwortete und sprach: Diese sind die, welche Jehova ausgesandt hat, um die Erde zu durchziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Und sie antworteten dem Engel Jehovas, der zwischen den Myrten hielt, und sprachen: Wir haben die Erde durchzogen, und siehe, die ganze Erde sitzt still und ist ruhig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Da hob der Engel Jehovas an und sprach: Jehova der Heerscharen, wie lange willst du dich nicht Jerusalems und der Städte Judas erbarmen, auf welche du gezürnt hast diese siebzig Jahre?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Und Jehova antwortete dem Engel, der mit mir redete, gütige Worte, tröstliche Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Und der Engel, der mit mir redete, sprach zu mir: Rufe aus und sprich: So spricht Jehova der Heerscharen: Ich habe mit großem Eifer für Jerusalem und für Zion geeifert,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'und mit sehr großem Zorne zürne ich über die sicheren Nationen; denn ich habe ein wenig gezürnt, sie aber haben zum Unglück geholfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Darum spricht Jehova also: Ich habe mich Jerusalem mit Erbarmen wieder zugewandt; mein Haus, spricht Jehova der Heerscharen, soll darin gebaut, und die Meßschnur über Jerusalem gezogen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Rufe ferner aus und sprich: So spricht Jehova der Heerscharen: Meine Städte sollen noch überfließen von Gutem; und Jehova wird Zion noch trösten und Jerusalem noch erwählen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Und ich hob meine Augen auf und sah: und siehe, vier Hörner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'Und ich sprach zu dem Engel, der mit mir redete: Was sind diese? Und er sprach zu mir: Diese sind die Hörner, welche Juda, Israel und Jerusalem zerstreut haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Und Jehova ließ mich vier Werkleute sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Und ich sprach: Was wollen diese tun? Und er sprach zu mir und sagte: Jene sind die Hörner, welche Juda dermaßen zerstreut haben, daß niemand mehr sein Haupt erhob; und diese sind gekommen, um sie in Schrecken zu setzen und die Hörner der Nationen niederzuwerfen, welche das Horn gegen das Land Juda erhoben haben, um es zu zerstreuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Und ich hob meine Augen auf und sah: und siehe, ein Mann, und eine Meßschnur war in seiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Und ich sprach: Wohin gehst du? Und er sprach zu mir: Jerusalem zu messen, um zu sehen, wie groß seine Breite und wie groß seine Länge ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Und siehe, der Engel, der mit mir redete, ging aus; und ein anderer Engel ging aus, ihm entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Und er sprach zu ihm: Laufe, rede zu diesem Jüngling und sprich: Als offene Stadt wird Jerusalem bewohnt werden wegen der Menge Menschen und Vieh in seiner Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Und ich, spricht Jehova, werde ihm eine feurige Mauer sein ringsum, und werde zur Herrlichkeit sein in seiner Mitte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Hui! Hui! Fliehet aus dem Lande des Nordens! spricht Jehova; denn nach den vier Winden des Himmels breite ich euch aus, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Hui! Entrinne, Zion, die du wohnst bei der Tochter Babels!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Denn so spricht Jehova der Heerscharen: Nach der Herrlichkeit hat er mich zu den Nationen gesandt, die euch geplündert haben; denn wer euch antastet, tastet seinen Augapfel an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Denn siehe, ich werde meine Hand über sie schwingen, und sie werden denen zum Raube sein, welche ihnen dienten; und ihr werdet erkennen, daß Jehova der Heerscharen mich gesandt hat. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Jubele und freue dich, Tochter Zion! Denn siehe, ich komme und werde in deiner Mitte wohnen, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Und an jenem Tage werden viele Nationen sich an Jehova anschließen, und sie werden mein Volk sein; und ich werde in deiner Mitte wohnen, und du wirst erkennen, daß Jehova der Heerscharen mich zu dir gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Und Jehova wird Juda als sein Erbteil besitzen in dem heiligen Lande und wird Jerusalem noch erwählen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Alles Fleisch schweige vor Jehova! Denn er hat sich aufgemacht aus seiner heiligen Wohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Und er ließ mich den Hohenpriester Josua sehen, der vor dem Engel Jehovas stand; und der Satan stand zu seiner Rechten, ihm zu widerstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Und Jehova sprach zum Satan: Jehova schelte dich, Satan! Ja, es schelte dich Jehova, der Jerusalem erwählt hat! Ist dieser nicht ein Brandscheit, das aus dem Feuer gerettet ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Und Josua war bekleidet mit schmutzigen Kleidern und stand vor dem Engel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Und der Engel hob an und sprach zu denen, welche vor ihm standen, und sagte: Ziehet ihm die schmutzigen Kleider aus; und zu ihm sprach er: Siehe, ich habe deine Ungerechtigkeit von dir weggenommen, und ich kleide dich in Feierkleider.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Und ich sprach: Man setze einen reinen Kopfbund auf sein Haupt. Und sie setzten den reinen Kopfbund auf sein Haupt und zogen ihm Kleider an; und der Engel Jehovas stand dabei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Und der Engel Jehovas bezeugte dem Josua und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'So spricht Jehova der Heerscharen: Wenn du in meinen Wegen wandeln und wenn du meiner Hut warten wirst, so sollst du sowohl mein Haus richten als auch meine Vorhöfe behüten; und du sollst ein-und ausgehen unter diesen, die hier stehen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Höre doch, Josua, du Hoherpriester, du und deine Genossen, die vor dir sitzen, denn Männer des Wunders sind sie; denn siehe, ich will meinen Knecht, Sproß genannt, kommen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Denn siehe, der Stein, den ich vor Josua gelegt habe, auf einem Steine sieben Augen siehe, ich will seine Eingrabung eingraben, spricht Jehova der Heerscharen, und will die Ungerechtigkeit dieses Landes hinwegnehmen an einem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'An jenem Tage, spricht Jehova der Heerscharen, werdet ihr einer den anderen einladen unter den Weinstock und unter den Feigenbaum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Und der Engel, der mit mir redete, kam wieder und weckte mich wie einen Mann, der aus seinem Schlafe geweckt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Und er sprach zu mir: Was siehst du? Und ich sprach: Ich sehe, und siehe, ein Leuchter ganz von Gold, und sein Ölbehälter an seinem oberen Ende, und seine sieben Lampen an ihm, sieben, und sieben Gießröhren zu den Lampen, die an seinem oberen Ende sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'und zwei Olivenbäume neben demselben, einer zur Rechten des Ölbehälters und einer zu seiner Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Und ich hob an und sprach zu dem Engel, der mit mir redete, und sagte: Mein Herr, was sind diese?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Und der Engel, der mit mir redete, antwortete und sprach zu mir: Weißt du nicht, was diese sind? Und ich sprach: Nein, mein Herr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Da antwortete er und sprach zu mir und sagte: Dies ist das Wort Jehovas an Serubbabel: Nicht durch Macht und nicht durch Kraft, sondern durch meinen Geist, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Wer bist du, großer Berg, vor Serubbabel? Zur Ebene sollst du werden! Und er wird den Schlußstein herausbringen unter lautem Zuruf: Gnade, Gnade ihm! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Die Hände Serubbabels haben dieses Haus gegründet, und seine Hände werden es vollenden; und du wirst erkennen, daß Jehova der Heerscharen mich zu euch gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Denn wer verachtet den Tag kleiner Dinge? Und mit Freuden werden jene Sieben das Senkblei in der Hand Serubbabels sehen: die Augen Jehovas, sie durchlaufen die ganze Erde. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Und ich hob an und sprach zu ihm: Was sind diese zwei Olivenbäume zur Rechten des Leuchters und zu seiner Linken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Und ich hob zum zweiten Male an und sprach zu ihm: Was sind die beiden Zweige der Olivenbäume, welche neben den zwei goldenen Röhren sind, die das Gold von sich aus ergießen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Und er sprach zu mir und sagte: Weißt du nicht, was diese sind? Und ich sprach: Nein, mein Herr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Da sprach er: Dies sind die beiden Söhne des Öls, welche bei dem Herrn der ganzen Erde stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Und ich hob wiederum meine Augen auf und sah: und siehe, eine fliegende Rolle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Und er sprach zu mir: Was siehst du? Und ich sprach: Ich sehe eine fliegende Rolle, ihre Länge zwanzig Ellen und ihre Breite zehn Ellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Und er sprach zu mir: Dies ist der Fluch, welcher über die Fläche des ganzen Landes ausgeht; denn ein jeder, der stiehlt, wird gemäß dem, was auf dieser Seite der Rolle geschrieben ist, weggefegt werden; und ein jeder, der falsch schwört, wird gemäß dem, was auf jener Seite der Rolle geschrieben ist, weggefegt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Ich habe ihn ausgehen lassen, spricht Jehova der Heerscharen; und er wird kommen in das Haus des Diebes und in das Haus dessen, der bei meinem Namen falsch schwört; und er wird in seinem Hause herbergen und es vernichten, sowohl sein Gebälk als auch seine Steine. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Und der Engel, der mit mir redete, trat hervor und sprach zu mir: Hebe doch deine Augen auf und sieh: was ist dieses, das da hervorkommt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Und ich sprach: Was ist es? Und er sprach: Dies ist ein Epha, das hervorkommt; und er sprach: Solches ist ihr Aussehen im ganzen Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Und siehe, eine Scheibe von Blei wurde aufgehoben; und da war ein Weib, welches inmitten des Ephas saß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Und er sprach: Dies ist die Gesetzlosigkeit; und er warf sie in das Epha hinein und warf das Bleigewicht auf dessen Mündung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Und ich hob meine Augen auf und sah: und siehe, da kamen zwei Weiber hervor, und Wind war in ihren Flügeln, und sie hatten Flügel wie die Flügel des Storches; und sie hoben das Epha empor zwischen Erde und Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Und ich sprach zu dem Engel, der mit mir redete: Wohin bringen diese das Epha?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Und er sprach zu mir: Um ihm ein Haus zu bauen im Lande Sinear; und ist dieses aufgerichtet, so wird es daselbst auf seine Stelle niedergesetzt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Und ich hob wiederum meine Augen auf und sah: und siehe, vier Wagen kamen hervor zwischen zwei Bergen; und die Berge waren Berge von Erz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'An dem ersten Wagen waren rote Rosse, und an dem zweiten Wagen schwarze Rosse;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'und an dem dritten Wagen weiße Rosse, und an dem vierten Wagen scheckige, starke Rosse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Und ich hob an und sprach zu dem Engel, der mit mir redete: Mein Herr, was sind diese?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Und der Engel antwortete und sprach zu mir: Diese sind die vier Winde des Himmels, welche ausgehen, nachdem sie sich vor den Herrn der ganzen Erde gestellt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'An welchem die schwarzen Rosse sind, die ziehen aus nach dem Lande des Nordens; und die weißen ziehen aus hinter ihnen her; und die scheckigen ziehen aus nach dem Lande des Südens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'und die starken ziehen aus und trachten hinzugehen, die Erde zu durchziehen. Und er sprach: Gehet, durchziehet die Erde! Und sie durchzogen die Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Und er rief mir und redete zu mir und sprach: Siehe, diejenigen, welche nach dem Lande des Nordens ausgezogen sind, lassen meinen Geist Ruhe finden im Lande des Nordens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Und das Wort Jehovas geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Nimm von den Weggeführten, von Cheldai und von Tobija und von Jedaja, und geh du an selbigem Tage, geh in das Haus Josijas, des Sohnes Zephanjas, wohin sie aus Babel gekommen sind-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'ja, nimm Silber und Gold und mache eine Krone. Und setze sie auf das Haupt Josuas, des Sohnes Jozadaks, des Hohenpriester, und sprich zu ihm und sage:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'So spricht Jehova der Heerscharen und sagt: Siehe, ein Mann, sein Name ist Sproß; und er wird von seiner Stelle aufsprossen und den Tempel Jehovas bauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Ja, er wird den Tempel Jehovas bauen; und er wird Herrlichkeit tragen; und er wird auf seinem Throne sitzen und herrschen, und er wird Priester sein auf seinem Throne; und der Rat des Friedens wird zwischen ihnen beiden sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Und die Krone soll dem Chelem und Tobija und Jedaja und der Güte des Sohnes Zephanjas zum Gedächtnis sein im Tempel Jehovas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Und Entfernte werden kommen und am Tempel Jehovas bauen; und ihr werdet erkennen, daß Jehova der Heerscharen mich zu euch gesandt hat. Und dieses wird geschehen, wenn ihr fleißig auf die Stimme Jehovas, eures Gottes, hören werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Und es begab sich im vierten Jahre des Königs Darius, da geschah das Wort Jehovas zu Sacharja, am vierten Tage des neunten Monats, im Monat Kislev,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'als Bethel den Scharezer und Regem-Melech und seine Männer sandte, um Jehova anzuflehen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'und um den Priestern des Hauses Jehovas der Heerscharen und den Propheten zu sagen: Soll ich weinen im fünften Monat und mich enthalten, wie ich schon so viele Jahre getan habe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Und das Wort Jehovas der Heerscharen geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Rede zu dem ganzen Volke des Landes und zu den Priestern und sprich: Wenn ihr im fünften und im siebten Monat gefastet und gewehklagt habt, und zwar schon siebzig Jahre, habt ihr irgendwie mir gefastet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Und wenn ihr esset, und wenn ihr trinket, seid nicht ihr die Essenden und ihr die Trinkenden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Kennet ihr nicht die Worte, welche Jehova durch die früheren Propheten ausrief, als Jerusalem bewohnt und ruhig war, und seine Städte rings um dasselbe her, und der Süden und die Niederung bewohnt waren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Und das Wort Jehovas geschah zu Sacharja also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'So spricht Jehova der Heerscharen und sagt: Übet ein wahrhaftiges Gericht und erweiset Güte und Barmherzigkeit einer dem anderen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'und bedrücket nicht die Witwe und die Waise, den Fremdling und den Elenden; und sinnet keiner auf seines Bruders Unglück in euren Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Aber sie weigerten sich, aufzumerken, und zogen die Schulter widerspenstig zurück und machten ihre Ohren schwer, um nicht zu hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Und sie machten ihr Herz zu Diamant, um das Gesetz nicht zu hören noch die Worte, welche Jehova der Heerscharen durch seinen Geist mittelst der früheren Propheten sandte; und so kam ein großer Zorn von seiten Jehovas der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Und es geschah, gleichwie er gerufen, und sie nicht gehört hatten, also riefen sie, und ich hörte nicht, spricht Jehova der Heerscharen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'und ich stürmte sie hinweg unter alle Nationen, die sie nicht kannten, und das Land wurde hinter ihnen verwüstet, so daß niemand hin und wieder zieht; und sie machten das köstliche Land zu einer Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Und es geschah das Wort Jehovas der Heerscharen also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'So spricht Jehova der Heerscharen: Ich eifere für Zion mit großem Eifer, und mit großem Grimme eifere ich für dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'So spricht Jehova: Ich kehre nach Zion zurück und will inmitten Jerusalems wohnen; und Jerusalem wird genannt werden \"Stadt der Wahrheit\", und der Berg Jehovas der Heerscharen \"der heilige Berg\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'So spricht Jehova der Heerscharen: Es werden noch Greise und Greisinnen in den Straßen von Jerusalem sitzen, ein jeder mit seinem Stabe in seiner Hand vor Menge der Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Und die Straßen der Stadt werden voll sein von Knaben und Mädchen, die auf seinen Straßen spielen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'So spricht Jehova der Heerscharen: Wenn es wunderbar ist in den Augen des Überrestes dieses Volkes in jenen Tagen, wird es auch in meinen Augen wunderbar sein? spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'So spricht Jehova der Heerscharen: Siehe, ich werde mein Volk retten aus dem Lande des Aufgangs und aus dem Lande des Untergangs der Sonne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'und ich werde sie herbeibringen, und sie werden wohnen inmitten Jerusalems; und sie werden mein Volk, und ich werde ihr Gott sein in Wahrheit und in Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'So spricht Jehova der Heerscharen: Stärket eure Hände, die ihr in diesen Tagen diese Worte aus dem Munde der Propheten höret, welche an dem Tage waren, da der Grund des Hauses Jehovas der Heerscharen, des Tempels, gelegt wurde, um ihn zu erbauen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Denn vor diesen Tagen war kein Lohn für die Menschen und kein Lohn für das Vieh; und der Aus-und Eingehende hatte keinen Frieden vor dem Bedränger, und ich ließ alle Menschen gegeneinander los.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Nun aber will ich dem Überrest dieses Volkes nicht sein wie in den früheren Tagen, spricht Jehova der Heerscharen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'sondern die Saat des Friedens, der Weinstock, wird seine Frucht geben, und die Erde ihren Ertrag geben, und der Himmel wird seinen Tau geben; und dem Überrest dieses Volkes werde ich das alles zum Erbteil geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Und es wird geschehen, gleichwie ihr, Haus Juda und Haus Israel, ein Fluch unter den Nationen gewesen seid, also werde ich euch retten, und ihr werdet ein Segen sein. Fürchtet euch nicht, stärket eure Hände!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Denn so spricht Jehova der Heerscharen: Gleichwie ich euch Böses zu tun gedachte, als eure Väter mich erzürnten, spricht Jehova der Heerscharen, und ich es mich nicht gereuen ließ,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'also gedenke ich wiederum in diesen Tagen Jerusalem und dem Hause Juda Gutes zu tun. Fürchtet euch nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Dies sind die Dinge, die ihr tun sollt: Redet die Wahrheit einer mit dem anderen; richtet der Wahrheit gemäß und fället einen Rechtsspruch des Friedens in euren Toren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'und sinnet keiner auf des anderen Unglück in euren Herzen, und falschen Eid liebet nicht; denn alles dieses, ich hasse es, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Und das Wort Jehovas der Heerscharen geschah zu mir also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'So spricht Jehova der Heerscharen: Das Fasten des vierten und das Fasten des fünften und das Fasten des siebten und das Fasten des zehnten Monats wird dem Hause Juda zur Wonne und zur Freude und zu fröhlichen Festzeiten werden. Doch liebet die Wahrheit und den Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'So spricht Jehova der Heerscharen: Noch wird es geschehen, daß Völker und Bewohner vieler Städte kommen werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'und die Bewohner der einen werden zur anderen gehen und sagen: \"Laßt uns doch hingehen, um Jehova anzuflehen und Jehova der Heerscharen zu suchen!\" \"Auch ich will gehen!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Und viele Völker und mächtige Nationen werden kommen, um Jehova der Heerscharen in Jerusalem zu suchen und Jehova anzuflehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'So spricht Jehova der Heerscharen: In jenen Tagen, da werden zehn Männer aus allerlei Sprachen der Nationen ergreifen, ja, ergreifen werden sie den Rockzipfel eines jüdischen Mannes und sagen: Wir wollen mit euch gehen, denn wir haben gehört, daß Gott mit euch ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Ausspruch des Wortes Jehovas über das Land Chadrak; und auf Damaskus läßt es sich nieder (denn Jehova hat ein Auge auf die Menschen und auf alle Stämme Israels),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'und auch auf Hamath, welches daran grenzt, auf Tyrus und Zidon, weil es sehr weise ist. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Und Tyrus hat sich eine Feste erbaut und Silber gehäuft wie Staub, und Feingold wie Straßenkot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Siehe, der Herr wird es einnehmen und seine Macht im Meere schlagen; und es selbst wird vom Feuer verzehrt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Askalon soll es sehen und sich fürchten; auch Gasa, und soll sehr erzittern, und Ekron, denn seine Zuversicht ist zu Schanden geworden. Und der König wird auf Gasa vertilgt, und Askalon wird nicht mehr bewohnt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Und ein Bastard wird in Asdod wohnen, und ich werde den Hochmut der Philister ausrotten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Und ich werde sein Blut aus seinem Munde wegtun und seine Greuel zwischen seinen Zähnen hinweg; und auch er wird übrigbleiben unserem Gott, und wird sein wie ein Fürst in Juda, und Ekron wie der Jebusiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Und ich werde für mein Haus ein Lager aufschlagen vor dem Kriegsheere, vor den Hin-und Wiederziehenden, und kein Bedränger wird sie mehr überziehen; denn jetzt habe ich dareingesehen mit meinen Augen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Frohlocke laut, Tochter Zion; jauchze, Tochter Jerusalem! Siehe, dein König wird zu dir kommen: gerecht und ein Retter ist er, demütig, und auf einem Esel reitend, und zwar auf einem Füllen, einem Jungen der Eselin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Und ich werde die Wagen ausrotten aus Ephraim und die Rosse aus Jerusalem, und der Kriegsbogen wird ausgerottet werden. Und er wird Frieden reden zu den Nationen; und seine Herrschaft wird sein von Meer zu Meer, und vom Strome bis an die Enden der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Und du um des Blutes deines Bundes willen entlasse ich auch deine Gefangenen aus der Grube, in welcher kein Wasser ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Kehret zur Festung zurück, ihr Gefangenen der Hoffnung! Schon heute verkündige ich, daß ich dir das Doppelte erstatten werde. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Denn ich habe mir Juda gespannt, den Bogen mit Ephraim gefüllt; und ich wecke deine Söhne, Zion, auf wider deine Kinder, Griechenland, und mache dich wie das Schwert eines Helden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Und Jehova wird über ihnen erscheinen, und sein Pfeil wird ausfahren wie der Blitz; und der Herr, Jehova, wird in die Posaune stoßen und einherziehen in Stürmen des Südens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Jehova der Heerscharen wird sie beschirmen; und sie werden die Schleudersteine verzehren und niedertreten; und sie werden trinken, lärmen wie vom Wein und voll werden wie die Opferschalen, wie die Ecken des Altars.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Und Jehova, ihr Gott, wird sie retten an jenem Tage, wird sein Volk retten wie ein Herde; denn Kronensteine sind sie, funkelnd auf seinem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Denn wie groß ist seine Anmut, und wie groß seine Schönheit! Das Korn wird Jünglinge und der Most Jungfrauen wachsen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Erbittet von Jehova Regen zur Zeit des Spätregens; Jehova schafft die Wetterstrahlen, und er wird euch Regengüsse geben, Kraut auf dem Felde einem jeden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Denn die Teraphim haben Nichtiges geredet, und die Wahrsager haben Lüge geschaut; und sie reden Träume des Truges, trösten mit Dunst. Darum sind sie fortgewandert wie eine Herde, werden bedrückt, weil kein Hirte da ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Mein Zorn ist wider die Hirten entbrannt, und die Böcke werde ich heimsuchen; denn Jehova der Heerscharen wird seiner Herde, des Hauses Juda, sich annehmen und sie machen wie sein Prachtroß im Streite.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Von ihm kommt der Eckstein, von ihm der Pflock, von ihm der Kriegsbogen, von ihm werden alle Bedränger hervorkommen insgesamt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Und sie werden wie Helden sein, die den Kot der Straßen im Kampfe zertreten; und sie werden kämpfen, denn Jehova ist mit ihnen, und die Reiter auf Rossen werden zu Schanden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Und ich werde das Haus Juda stärken und das Haus Joseph retten, und werde sie wohnen lassen; denn ich habe mich ihrer erbarmt, und sie werden sein, als ob ich sie nicht verstoßen hätte. Denn ich bin Jehova, ihr Gott, und werde ihnen antworten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Und Ephraim wird sein wie ein Held, und ihr Herz wird sich freuen wie vom Wein; und ihre Kinder werden es sehen und sich freuen, ihr Herz wird frohlocken in Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Ich will sie herbeizischen und sie sammeln, denn ich habe sie erlöst; und sie werden sich mehren, wie sie sich gemehrt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Und ich will sie unter den Völkern säen, und in den fernen Ländern werden sie meiner gedenken; und sie werden mit ihren Kindern leben und zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Und ich werde sie zurückführen aus dem Lande Ägypten und sie sammeln aus Assyrien, und sie in das Land Gilead und auf den Libanon bringen; und nicht wird Raum genug für sie gefunden werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Und er wird durch das Meer der Angst ziehen und die Wellen im Meere schlagen, und alle Tiefen des Stromes werden versiegen; und die Hoffart Assyriens wird niedergeworfen werden, und weichen wird das Zepter Ägyptens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Und ich werde sie stark machen in Jehova, und in seinem Namen werden sie wandeln, spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Tue auf, Libanon, deine Tore, und Feuer verzehre deine Zedern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Heule, Zypresse! Denn die Zeder ist gefallen, denn die Herrlichen sind verwüstet. Heulet, Eichen Basans! Denn der unzugängliche Wald ist niedergestreckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Lautes Heulen der Hirten, denn ihre Herrlichkeit ist verwüstet; lautes Gebrüll der jungen Löwen, denn die Pracht des Jordan ist verwüstet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Also sprach Jehova, mein Gott: Weide die Herde des Würgens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'deren Käufer sie erwürgen und es nicht büßen, und deren Verkäufer sprechen: Gepriesen sei Jehova, denn ich werde reich! und deren Hirten sie nicht verschonen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Denn ich werde die Bewohner des Landes nicht mehr verschonen, spricht Jehova; und siehe, ich überliefere die Menschen, einen jeden der Hand seines Nächsten und der Hand seines Königs; und sie werden das Land zertrümmern, und ich werde nicht aus ihrer Hand befreien. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Und ich weidete die Herde des Würgens, mithin die Elenden der Herde; und ich nahm mir zwei Stäbe: den einen nannte ich Huld, und den anderen nannte ich Bande, und ich weidete die Herde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Und ich vertilgte drei Hirten in einem Monat. Und meine Seele wurde ungeduldig über sie, und auch ihre Seele wurde meiner überdrüssig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Da sprach ich: Ich will euch nicht mehr weiden; was stirbt, mag sterben, und was umkommt, mag umkommen; und die Übrigbleibenden mögen eines des anderen Fleisch fressen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Und ich nahm meinen Stab Huld und zerbrach ihn, um meinen Bund zu brechen, den ich mit allen Völkern gemacht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Und er wurde gebrochen an jenem Tage; und also erkannten die Elenden der Herde, die auf mich achteten, daß es das Wort Jehovas war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Und ich sprach zu ihnen: Wenn es gut ist in euren Augen, so gebet mir meinen Lohn, wenn aber nicht, so lasset es; und sie wogen meinen Lohn dar: dreißig Silbersekel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Da sprach Jehova zu mir: Wirf ihn dem Töpfer hin, den herrlichen Preis, dessen ich von ihnen wertgeachtet bin! Und ich nahm die dreißig Silbersekel und warf sie in das Haus Jehovas, dem Töpfer hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Und ich zerbrach meinen zweiten Stab, die Bande, um die Brüderschaft zwischen Juda und Israel zu brechen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Und Jehova sprach zu mir: Nimm dir noch das Gerät eines törichten Hirten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Denn siehe, ich erwecke einen Hirten im Lande: der Umkommenden wird er sich nicht annehmen, das Versprengte wird er nicht suchen, und das Verwundete nicht heilen; das Gesunde wird er nicht versorgen, und das Fleisch des Fetten wird er essen und ihre Klauen zerreißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Wehe dem nichtigen Hirten, der die Herde verläßt! Das Schwert über seinen Arm und über sein rechtes Auge! Sein Arm soll gänzlich verdorren, und sein rechtes Auge völlig erlöschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Ausspruch des Wortes Jehovas über Israel. Es spricht Jehova, der den Himmel ausspannt und die Erde gründet, und des Menschen Geist in seinem Innern bildet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Siehe, ich mache Jerusalem zu einer Taumelschale für alle Völker ringsum; und auch über Juda wird es kommen bei der Belagerung von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Und es wird geschehen an jenem Tage, da werde ich Jerusalem zu einem Laststein machen für alle Völker: alle, die ihn aufladen wollen, werden sich gewißlich daran verwunden. Und alle Nationen der Erde werden sich wider dasselbe versammeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'An jenem Tage, spricht Jehova, werde ich alle Rosse mit Scheuwerden und ihre Reiter mit Wahnsinn schlagen; und über das Haus Juda werde ich meine Augen offen halten, und alle Rosse der Völker mit Blindheit schlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Und die Fürsten von Juda werden in ihrem Herzen sprechen: Eine Stärke sind mir die Bewohner von Jerusalem in Jehova der Heerscharen, ihrem Gott. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'An jenem Tage werde ich die Fürsten von Juda machen gleich einem Feuerbecken unter Holzstücken und gleich einer Feuerfackel unter Garben; und sie werden zur Rechten und zur Linken alle Völker ringsum verzehren. Und fortan wird Jerusalem an seiner Stätte wohnen in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Und Jehova wird die Zelte Judas zuerst retten, auf daß die Pracht des Hauses Davids und die Pracht der Bewohner von Jerusalem sich nicht über Juda erhebe. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'An jenem Tage wird Jehova die Bewohner von Jerusalem beschirmen; und der Strauchelnde unter ihnen wird an jenem Tage wie David sein, und das Haus Davids wie Gott, wie der Engel Jehovas vor ihnen her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Und es wird geschehen an jenem Tage, da werde ich alle Nationen zu vertilgen suchen, die wider Jerusalem heranziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Und ich werde über das Haus Davids und über die Bewohner von Jerusalem den Geist der Gnade und des Flehens ausgießen; und sie werden auf mich blicken, den sie durchbohrt haben, und werden über ihn wehklagen gleich der Wehklage über den Eingeborenen, und bitterlich über ihn leidtragen, wie man bitterlich über den Erstgeborenen leidträgt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'An jenem Tage wird die Wehklage in Jerusalem groß sein wie die Wehklage von Hadad-Rimmon im Tale Megiddo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Und wehklagen wird das Land, jedes Geschlecht besonders: das Geschlecht des Hauses Davids besonders, und ihre Weiber besonders; das Geschlecht des Hauses Nathans besonders, und ihre Weiber besonders;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'das Geschlecht des Hauses Levis besonders, und ihre Weiber besonders; das Geschlecht der Simeiter besonders, und ihre Weiber besonders;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'alle übrigen Geschlechter, jedes Geschlecht besonders, und ihre Weiber besonders.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'An jenem Tage wird ein Quell geöffnet sein dem Hause Davids und den Bewohnern von Jerusalem für Sünde und für Unreinigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Und es wird geschehen an jenem Tage, spricht Jehova der Heerscharen, da werde ich die Namen der Götzen ausrotten aus dem Lande, und ihrer wird nicht mehr gedacht werden; und auch die Propheten und den Geist der Unreinheit werde ich aus dem Lande wegschaffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Und es wird geschehen, wenn ein Mann ferner weissagt, so werden sein Vater und seine Mutter, seine Erzeuger, zu ihm sprechen: Du darfst nicht leben, denn du hast Lüge geredet im Namen Jehovas! Und sein Vater und seine Mutter, seine Erzeuger, werden ihn durchbohren, wenn er weissagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Und es wird geschehen an jenem Tage, da werden die Propheten sich schämen, ein jeder über sein Gesicht, wenn er weissagt; und sie werden nicht mehr einen härenen Mantel anlegen, um zu lügen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Und er wird sprechen: Ich bin kein Prophet, ich bin ein Mann, der das Land bebaut; denn man hat mich gekauft von meiner Jugend an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Und wenn jemand zu ihm spricht: Was sind das für Wunden in deinen Händen? so wird er sagen: Es sind die Wunden, womit ich geschlagen worden bin im Hause derer, die mich lieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Schwert, erwache wider meinen Hirten und wider den Mann, der mein Genosse ist! spricht Jehova der Heerscharen; schlage den Hirten, und die Herde wird sich zerstreuen. Und ich werde meine Hand den Kleinen zuwenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Und es wird geschehen im ganzen Lande, spricht Jehova: zwei Teile davon werden ausgerottet werden und verscheiden, aber der dritte Teil davon wird übrigbleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Und ich werde den dritten Teil ins Feuer bringen, und ich werde sie läutern, wie man das Silber läutert, und sie prüfen, wie man das Gold prüft. Es wird meinen Namen anrufen, und ich werde ihm antworten; ich werde sagen: Es ist mein Volk; und es wird sagen: Jehova ist mein Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Siehe, ein Tag kommt für Jehova, da wird deine Beute verteilt werden in deiner Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Und ich werde alle Nationen nach Jerusalem zum Kriege versammeln; und die Stadt wird eingenommen und die Häuser werden geplündert und die Weiber geschändet werden; und die Hälfte der Stadt wird in die Gefangenschaft ausziehen, aber das übrige Volk wird nicht aus der Stadt ausgerottet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Und Jehova wird ausziehen und wider jene Nationen streiten, wie an dem Tage, da er streitet, an dem Tage der Schlacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Und seine Füße werden an jenem Tage auf dem Ölberge stehen, der vor Jerusalem gegen Osten liegt; und der Ölberg wird sich in der Mitte spalten nach Osten und nach Westen hin, zu einem sehr großen Tale, und die Hälfte des Berges wird nach Norden und seine andere Hälfte nach Süden weichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Und ihr werdet in das Tal meiner Berge fliehen, und das Tal der Berge wird bis Azel reichen; und ihr werdet fliehen, wie ihr vor dem Erdbeben geflohen seid in den Tagen Ussijas, des Königs von Juda. Und kommen wird Jehova, mein Gott, und alle Heiligen mit dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'Und es wird geschehen an jenem Tage, da wird kein Licht sein; die Gestirne werden sich verfinstern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Und es wird ein einziger Tag sein (er ist Jehova bekannt), nicht Tag und nicht Nacht; und es wird geschehen zur Zeit des Abends, da wird es Licht sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Und es wird geschehen an jenem Tage, da werden lebendige Wasser aus Jerusalem fließen, zur Hälfte nach dem östlichen Meere und zur Hälfte nach dem hinteren Meere; im Sommer und im Winter wird es geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Und Jehova wird König sein über die ganze Erde; an jenem Tage wird Jehova einer sein und sein Name einer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Das ganze Land wird sich umwandeln wie die Ebene, von Geba bis Rimmon, welches südlich von Jerusalem liegt; und Jerusalem wird erhaben sein und an seiner Stätte wohnen, vom Tore Benjamin bis zur Stelle des ersten Tores und bis zum Ecktore, und vom Turme Hananel bis zu den Keltern des Königs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'Und man wird darin wohnen, und kein Bann wird mehr sein; und Jerusalem wird in Sicherheit wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Und dies wird die Plage sein, womit Jehova alle Völker plagen wird, welche gegen Jerusalem Krieg geführt haben: Er wird eines jeden Fleisch verwesen lassen, während er auf seinen Füßen steht, und seine Augen werden verwesen in ihren Höhlen, und seine Zunge wird in seinem Munde verwesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Und es wird geschehen an jenem Tage, da wird eine große Verwirrung von Jehova unter ihnen entstehen; und sie werden einer des anderen Hand ergreifen, und eines jeden Hand wird sich gegen die Hand seines Nächsten erheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Und auch Juda wird in Jerusalem streiten; und der Reichtum aller Nationen ringsum wird gesammelt werden: Gold und Silber und Kleider in großer Menge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Und ebenso, gleich dieser Plage, wird die Plage der Rosse, der Maultiere, der Kamele und der Esel und alles Viehes sein, welches in jenen Heerlagern sein wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Und es wird geschehen, daß alle Übriggebliebenen von allen Nationen, welche wider Jerusalem gekommen sind, von Jahr zu Jahr hinaufziehen werden, um den König, Jehova der Heerscharen, anzubeten und das Laubhüttenfest zu feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Und es wird geschehen, wenn eines von den Geschlechtern der Erde nicht nach Jerusalem hinaufziehen wird, um den König, Jehova der Heerscharen, anzubeten: über dasselbe wird kein Regen kommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'und wenn das Geschlecht Ägyptens nicht hinaufzieht und nicht kommt, so wird der Regen auch nicht über dieses kommen. Das wird die Plage sein, womit Jehova die Nationen plagen wird, welche nicht hinaufziehen werden, um das Laubhüttenfest zu feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Das wird die Strafe Ägyptens und die Strafe aller Nationen sein, welche nicht hinaufziehen werden, um das Laubhüttenfest zu feiern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'An jenem Tage wird auf den Schellen der Rosse stehen: Heilig dem Jehova. Und die Kochtöpfe im Hause Jehovas werden sein wie die Opferschalen vor dem Altar;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'und jeder Kochtopf in Jerusalem und in Juda wird Jehova der Heerscharen heilig sein; und alle Opfernden werden kommen und von denselben nehmen und darin kochen. Und es wird an jenem Tage kein Kanaaniter mehr sein im Hause Jehovas der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Ausspruch des Wortes Jehovas an Israel durch Maleachi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Ich habe euch geliebt, spricht Jehova; aber ihr sprechet: \"Worin hast du uns geliebt?\" War nicht Esau der Bruder Jakobs? spricht Jehova, und ich habe Jakob geliebt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Esau aber habe ich gehaßt, und ich habe seine Berge zur Wüste gemacht und sein Erbteil für die Schakale der Steppe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Wenn Edom spricht: Wir sind zerschmettert, werden aber die Trümmer wieder aufbauen, so spricht Jehova der Heerscharen: Sie werden bauen, ich aber werde niederreißen; und man wird sie nennen \"Gebiet der Gesetzlosigkeit\" und \"das Volk, welchem Jehova ewiglich zürnt\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Und eure Augen werden es sehen, und ihr werdet sprechen: Groß ist Jehova über das Gebiet Israels hinaus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Ein Sohn soll den Vater ehren, und ein Knecht seinen Herrn. Wenn ich denn Vater bin, wo ist meine Ehre? Und wenn ich Herr bin, wo ist meine Furcht? spricht Jehova der Heerscharen zu euch, ihr Priester, die ihr meinen Namen verachtet und doch sprechet: Womit haben wir deinen Namen verachtet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Die ihr unreines Brot auf meinem Altar darbringet und doch sprechet: Womit haben wir dich verunreinigt? Damit, daß ihr saget: Der Tisch Jehovas ist verächtlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Und wenn ihr Blindes darbringet, um es zu opfern, so ist es nichts Böses; und wenn ihr Lahmes und Krankes darbringet, so ist es nichts Böses. Bringe es doch deinem Landpfleger dar: wird er dich wohlgefällig annehmen, oder Rücksicht auf dich nehmen? spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Und nun, flehet doch Gott an, daß er uns gnädig sei! von eurer Hand ist das geschehen, wird er um euretwillen Rücksicht nehmen? spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Wäre doch nur einer unter euch, der die Türen verschlösse, damit ihr nicht vergeblich auf meinem Altar Feuer anzündetet! Ich habe keine Lust an euch, spricht Jehova der Heerscharen, und eine Opfergabe nehme ich nicht wohlgefällig aus eurer Hand an. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Denn vom Aufgang der Sonne bis zu ihrem Niedergang wird mein Name groß sein unter den Nationen; und an jedem Orte wird geräuchert, dargebracht werden meinem Namen, und zwar reine Opfergaben. Denn mein Name wird groß sein unter den Nationen, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Ihr aber entweihet ihn, indem ihr sprechet: Der Tisch des Herrn ist verunreinigt, und sein Einkommen, seine Speise ist verächtlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Und ihr sprechet: Siehe, welch eine Mühsal! und ihr blaset ihn an, spricht Jehova der Heerscharen, und bringet Geraubtes herbei und das Lahme und das Kranke; und so bringet ihr die Opfergabe. Soll ich das wohlgefällig von eurer Hand annehmen? spricht Jehova.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Und verflucht sei, wer betrügt, während ein Männliches in seiner Herde ist; und wer gelobt und dem Herrn ein Verdorbenes opfert! Denn ich bin ein großer König, spricht Jehova der Heerscharen, und mein Name ist furchtbar unter den Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Und nun, ihr Priester, an euch ergeht dieses Gebot!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Wenn ihr nicht höret, und wenn ihr es nicht zu Herzen nehmet, meinem Namen Ehre zu geben, spricht Jehova der Heerscharen, so werde ich den Fluch unter euch senden, und eure Segnungen verfluchen; ja, ich habe sie auch verflucht, weil ihr es nicht zu Herzen nehmet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Siehe, ich schelte euch die Saat und streue euch Mist in das Angesicht, den Mist eurer Feste, und man wird euch zu ihm hintragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Und ihr werdet wissen, daß ich dieses Gebot an euch gesandt habe, damit mein Bund mit Levi sei, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Mein Bund mit ihm war das Leben und der Friede; und ich gab sie ihm zur Furcht, und er fürchtete mich, und er, er zitterte vor meinem Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Das Gesetz der Wahrheit war in seinem Munde, und Unrecht fand sich nicht auf seinen Lippen; er wandelte mit mir in Frieden und Geradheit, und viele brachte er von ihrer Ungerechtigkeit zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Denn die Lippen des Priesters sollen Erkenntnis bewahren, und das Gesetz sucht man aus seinem Munde, denn er ist ein Bote Jehovas der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Ihr aber seid abgewichen von dem Wege, habt viele straucheln gemacht im Gesetz, ihr habt den Bund Levis zerstört, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'So habe auch ich euch bei dem ganzen Volke verächtlich und niedrig gemacht, in demselben Maße, wie ihr meine Wege nicht bewahret und die Person ansehet beim Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Haben wir nicht alle einen Vater? Hat nicht ein Gott uns geschaffen? Warum handeln wir treulos einer gegen den anderen, indem wir den Bund unserer Väter entweihen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Juda hat treulos gehandelt, und ein Greuel ist verübt worden in Israel und in Jerusalem; denn Juda hat das Heiligtum Jehovas entweiht, welches er liebte, und ist mit der Tochter eines fremden Gottes vermählt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Jehova wird den Mann, der solches tut, aus den Zelten Jakobs ausrotten, den wachenden und den, der einen Laut von sich gibt, und den, welcher Jehova der Heerscharen eine Opfergabe darbringt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Und zweitens tut ihr dieses: Ihr bedecket den Altar Jehovas mit Tränen, mit Weinen und Seufzen, so daß er sich nicht mehr zu eurer Opfergabe wendet, noch Wohlgefälliges aus eurer Hand annimmt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Und ihr sprechet: Warum? Weil Jehova Zeuge gewesen ist zwischen dir und dem Weibe deiner Jugend, an welchem du treulos gehandelt hast, da sie doch deine Genossin und das Weib deines Bundes ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Und hat nicht einer sie gemacht? Und sein war der Überrest des Geistes. Und was wollte der eine? Er suchte einen Samen Gottes. So hütet euch in eurem Geiste, und handle nicht treulos gegen das Weib deiner Jugend!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Denn ich hasse Entlassung, spricht Jehova, der Gott Israels; und er bedeckt mit Gewalttat sein Gewand, spricht Jehova der Heerscharen. So hütet euch in eurem Geiste, daß ihr nicht treulos handelt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Ihr habt Jehova mit euren Worten ermüdet; und ihr sprechet: Womit haben wir ihn ermüdet? Damit, daß ihr saget: Jeder Übeltäter ist gut in den Augen Jehovas, und an ihnen hat er Gefallen; oder wo ist der Gott des Gerichts?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Siehe, ich sende meinen Boten, daß er den Weg bereite vor mir her. Und plötzlich wird zu seinem Tempel kommen der Herr, den ihr suchet; und der Engel des Bundes, den ihr begehret: siehe, er kommt, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Wer aber kann den Tag seines Kommens ertragen, und wer wird bestehen bei seinem Erscheinen? Denn er wird wie das Feuer des Schmelzers sein und wie die Lauge der Wäscher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Und er wird sitzen und das Silber schmelzen und reinigen; und er wird die Kinder Levi reinigen und sie läutern wie das Gold und wie das Silber, so daß sie Opfergaben dem Jehova darbringen werden in Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Dann wird die Opfergabe Judas und Jerusalems Jehova angenehm sein wie in den Tagen vor alters und wie in den Jahren der Vorzeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Und ich werde euch nahen zum Gericht und werde ein schneller Zeuge sein gegen die Zauberer und gegen die Ehebrecher und gegen die falsch Schwörenden; und gegen die, welche den Tagelöhner im Lohn, die Witwe und die Waise bedrücken und das Recht des Fremdlings beugen, und mich nicht fürchten, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Denn ich, Jehova, ich verändere mich nicht; und ihr, Kinder Jakobs, ihr werdet nicht vernichtet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Seit den Tagen eurer Väter seid ihr von meinen Satzungen abgewichen und habt sie nicht bewahrt. Kehret um zu mir, so will ich zu euch umkehren, spricht Jehova der Heerscharen. Und ihr sprechet: Worin sollen wir umkehren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Darf ein Mensch Gott berauben, daß ihr mich beraubet? Und ihr sprechet: Worin haben wir dich beraubt? In dem Zehnten und in dem Hebopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Mit dem Fluche seid ihr verflucht, und doch beraubet ihr mich, ihr, die ganze Nation!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Bringet den ganzen Zehnten in das Vorratshaus, auf daß Speise in meinem Hause sei; und prüfet mich doch dadurch, spricht Jehova der Heerscharen, ob ich euch nicht die Fenster des Himmels auftun und euch Segen ausgießen werde bis zum Übermaß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Und ich werde um euretwillen den Fresser schelten, daß er euch die Frucht des Bodens nicht verderbe; und der Weinstock auf dem Felde wird euch nicht mehr fehltragen, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Und alle Nationen werden euch glücklich preisen, denn ihr werdet ein Land des Wohlgefallens sein, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Eure Worte sind trotzig gegen mich gewesen, spricht Jehova. Und ihr sprechet: Was haben wir miteinander wider dich beredet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Ihr sprechet: Vergeblich ist es, Gott zu dienen, und was für Gewinn, daß wir seiner Hut warteten, und daß wir in Trauer einhergingen vor Jehova der Heerscharen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Und so preisen wir nun die Übermütigen glücklich: nicht nur sind die Täter der Gesetzlosigkeit aufgebaut worden, sondern sie haben auch Gott versucht und sind entronnen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Da unterredeten sich miteinander, die Jehova fürchten, und Jehova merkte auf und hörte; und ein Gedenkbuch ward vor ihm geschrieben für die, welche Jehova fürchten und welche seinen Namen achten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Und sie werden mir, spricht Jehova der Heerscharen, zum Eigentum sein an dem Tage, den ich machen werde; und ich werde ihrer schonen, wie ein Mann seines Sohnes schont, der ihm dient.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Und ihr werdet wiederum den Unterschied sehen zwischen dem Gerechten und dem Gesetzlosen, zwischen dem, der Gott dient, und dem, der ihm nicht dient.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Denn siehe, der Tag kommt, brennend wie ein Ofen; und es werden alle Übermütigen und jeder Täter der Gesetzlosigkeit zu Stoppeln werden; und der kommende Tag wird sie verbrennen, spricht Jehova der Heerscharen, so daß er ihnen weder Wurzel noch Zweig lassen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Aber euch, die ihr meinen Namen fürchtet, wird die Sonne der Gerechtigkeit aufgehen mit Heilung in ihren Flügeln. Und ihr werdet ausziehen und hüpfen gleich Mastkälbern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'und ihr werdet die Gesetzlosen zertreten, denn sie werden Asche sein unter euren Fußsohlen an dem Tage, den ich machen werde, spricht Jehova der Heerscharen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Gedenket des Gesetzes Moses, meines Knechtes, welches ich ihm auf Horeb an ganz Israel geboten habe, Satzungen und Rechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Siehe, ich sende euch Elia, den Propheten, ehe der Tag Jehovas kommt, der große und furchtbare.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Und er wird das Herz der Väter zu den Kindern, und das Herz der Kinder zu ihren Vätern wenden, auf daß ich nicht komme und das Land mit dem Banne schlage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Buch des Geschlechts Jesu Christi, des Sohnes Davids, des Sohnes Abrahams.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham zeugte Isaak; Isaak aber zeugte Jakob, Jakob aber zeugte Juda und seine Brüder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Juda aber zeugte Phares und Zara von der Thamar; Phares aber zeugte Esrom, Esrom aber zeugte Aram,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Aram aber zeugte Aminadab, Aminadab aber zeugte Nahasson, Nahasson aber zeugte Salmon,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Salmon aber zeugte Boas von der Rahab; Boas aber zeugte Obed von der Ruth; Obed aber zeugte Isai,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Isai aber zeugte David, den König. David aber zeugte Salomon von der, die Urias Weib gewesen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Salomon aber zeugte Roboam, Roboam aber zeugte Abia, Abia aber zeugte Asa,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Asa aber zeugte Josaphat, Josaphat aber zeugte Joram, Joram aber zeugte Osia,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Osia aber zeugte Joatham, Joatham aber zeugte Achas, Achas aber zeugte Ezekia,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ezekia aber zeugte Manasse, Manasse aber zeugte Amon, Amon aber zeugte Josia,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Josia aber zeugte Jechonia und seine Brüder um die Zeit der Wegführung nach Babylon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Nach der Wegführung nach Babylon aber zeugte Jechonia Salathiel, Salathiel aber zeugte Zorobabel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Zorobabel aber zeugte Abiud, Abiud aber zeugte Eliakim, Eliakim aber zeugte Asor,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Asor aber zeugte Zadok, Zadok aber zeugte Achim, Achim aber zeugte Eliud,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Eliud aber zeugte Eleasar, Eleasar aber zeugte Matthan, Matthan aber zeugte Jakob,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jakob aber zeugte Joseph, den Mann der Maria, von welcher Jesus geboren wurde, der Christus genannt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'So sind nun alle Geschlechter von Abraham bis auf David vierzehn Geschlechter, und von David bis zur Wegführung nach Babylon vierzehn Geschlechter, und von der Wegführung nach Babylon bis auf den Christus vierzehn Geschlechter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Die Geburt Jesu Christi war aber also: Als nämlich Maria, seine Mutter, dem Joseph verlobt war, wurde sie, ehe sie zusammengekommen waren, schwanger erfunden von dem Heiligen Geiste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Joseph aber, ihr Mann, indem er gerecht war und sie nicht öffentlich zur Schau stellen wollte, gedachte sie heimlich zu entlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Indem er aber solches bei sich überlegte, siehe, da erschien ihm ein Engel des Herrn im Traum und sprach: Joseph, Sohn Davids, fürchte dich nicht, Maria, dein Weib, zu dir zu nehmen; denn das in ihr Gezeugte ist von dem Heiligen Geiste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Und sie wird einen Sohn gebären, und du sollst seinen Namen Jesus heißen; denn er wird sein Volk erretten von ihren Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Dies alles geschah aber, auf daß erfüllt würde, was von dem Herrn geredet ist durch den Propheten, welcher spricht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '\"Siehe, die Jungfrau wird schwanger sein und einen Sohn gebären, und sie werden seinen Namen Emmanuel heißen\", was verdolmetscht ist: Gott mit uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Joseph aber, vom Schlafe erwacht, tat, wie ihm der Engel des Herrn befohlen hatte, und nahm sein Weib zu sich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'und er erkannte sie nicht, bis sie ihren erstgeborenen Sohn geboren hatte; und er hieß seinen Namen Jesus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Als aber Jesus zu Bethlehem in Judäa geboren war, in den Tagen Herodes\', des Königs, siehe, da kamen Magier vom Morgenlande nach Jerusalem, welche sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Wo ist der König der Juden, der geboren worden ist? Denn wir haben seinen Stern im Morgenlande gesehen und sind gekommen, ihm zu huldigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Als aber der König Herodes es hörte, wurde er bestürzt, und ganz Jerusalem mit ihm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'und er versammelte alle Hohenpriester und Schriftgelehrten des Volkes und erkundigte sich bei ihnen, wo der Christus geboren werden solle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Sie aber sagten ihm: Zu Bethlehem in Judäa; denn also steht durch den Propheten geschrieben:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '\"Und du, Bethlehem, Land Juda, bist keineswegs die geringste unter den Fürsten Judas; denn aus dir wird ein Führer hervorkommen, der mein Volk Israel weiden wird\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Dann berief Herodes die Magier heimlich und erforschte genau von ihnen die Zeit der Erscheinung des Sternes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'und er sandte sie nach Bethlehem und sprach: Ziehet hin und forschet genau nach dem Kindlein; wenn ihr es aber gefunden habt, so berichtet es mir, damit auch ich komme und ihm huldige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Sie aber, als sie den König gehört hatten, zogen hin. Und siehe, der Stern, den sie im Morgenlande gesehen hatten, ging vor ihnen her, bis er kam und oben über dem Orte stand, wo das Kindlein war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Als sie aber den Stern sahen, freuten sie sich mit sehr großer Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Und als sie in das Haus gekommen waren, sahen sie das Kindlein mit Maria, seiner Mutter, und sie fielen nieder und huldigten ihm; und sie taten ihre Schätze auf und opferten ihm Gaben: Gold und Weihrauch und Myrrhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Und als sie im Traum eine göttliche Weisung empfangen hatten, nicht wieder zu Herodes zurückzukehren, zogen sie auf einem anderen Wege hin in ihr Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Als sie aber hingezogen waren, siehe, da erscheint ein Engel des Herrn dem Joseph im Traum und spricht: Stehe auf, nimm das Kindlein und seine Mutter zu dir und fliehe nach Ägypten, und sei daselbst, bis ich es dir sage; denn Herodes wird das Kindlein suchen, um es umzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Er aber stand auf, nahm das Kindlein und seine Mutter des Nachts zu sich und zog hin nach Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Und er war daselbst bis zum Tode Herodes\', auf daß erfüllt würde, was von dem Herrn geredet ist durch den Propheten, welcher spricht: \"Aus Ägypten habe ich meinen Sohn gerufen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Da ergrimmte Herodes sehr, als er sah, daß er von den Magiern hintergangen worden war; und er sandte hin und ließ alle Knaben töten, die in Bethlehem und in allen seinen Grenzen waren, von zwei Jahren und darunter, nach der Zeit, die er von den Magiern genau erforscht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Da wurde erfüllt, was durch den Propheten Jeremias geredet ist, welcher spricht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '\"Eine Stimme ist in Rama gehört worden, Weinen und viel Wehklagen: Rahel beweint ihre Kinder, und sie wollte sich nicht trösten lassen, weil sie nicht mehr sind.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Als aber Herodes gestorben war, siehe, da erscheint ein Engel des Herrn dem Joseph im Traum in Ägypten und spricht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Stehe auf, nimm das Kindlein und seine Mutter zu dir und ziehe in das Land Israel; denn sie sind gestorben, die dem Kindlein nach dem Leben trachteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Und er stand auf und nahm das Kindlein und seine Mutter zu sich, und er kam in das Land Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Als er aber hörte, daß Archelaus über Judäa herrsche, anstatt seines Vaters Herodes, fürchtete er sich, dahin zu gehen; und als er im Traum eine göttliche Weisung empfangen hatte, zog er hin in die Gegenden von Galiläa');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'und kam und wohnte in einer Stadt, genannt Nazareth; damit erfüllt würde, was durch die Propheten geredet ist: \"Er wird Nazarener genannt werden.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'In jenen Tagen aber kommt Johannes der Täufer und predigt in der Wüste von Judäa und spricht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'Tut Buße, denn das Reich der Himmel ist nahe gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Denn dieser ist der, von welchem durch den Propheten Jesaias geredet ist, welcher spricht: \"Stimme eines Rufenden in der Wüste: Bereitet den Weg des Herrn, machet gerade seine Steige.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Er aber, Johannes, hatte seine Kleidung von Kamelhaaren und einen ledernen Gürtel um seine Lenden; seine Speise aber war Heuschrecken und wilder Honig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Da ging zu ihm hinaus Jerusalem und ganz Judäa und die ganze Umgegend des Jordan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'und sie wurden von ihm im Jordan getauft, indem sie ihre Sünden bekannten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Als er aber viele der Pharisäer und Sadducäer zu seiner Taufe kommen sah, sprach er zu ihnen: Otternbrut! Wer hat euch gewiesen, dem kommenden Zorn zu entfliehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Bringet nun der Buße würdige Frucht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'und denket nicht bei euch selbst zu sagen: Wir haben Abraham zum Vater; denn ich sage euch, daß Gott dem Abraham aus diesen Steinen Kinder zu erwecken vermag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Schon ist aber die Axt an die Wurzel der Bäume gelegt; jeder Baum nun, der nicht gute Frucht bringt, wird abgehauen und ins Feuer geworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Ich zwar taufe euch mit Wasser zur Buße; der nach mir Kommende aber ist stärker als ich, dessen Sandalen zu tragen ich nicht würdig bin; er wird euch mit Heiligem Geiste und Feuer taufen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'dessen Worfschaufel in seiner Hand ist, und er wird seine Tenne durch und durch reinigen und seinen Weizen in die Scheune sammeln, die Spreu aber wird er verbrennen mit unauslöschlichem Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Dann kommt Jesus aus Galiläa an den Jordan zu Johannes, um von ihm getauft zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Johannes aber wehrte ihm und sprach: Ich habe nötig von dir getauft zu werden, und du kommst zu mir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Jesus aber antwortete und sprach zu ihm: Laß es jetzt so sein; denn also gebührt es uns, alle Gerechtigkeit zu erfüllen. Dann läßt er es ihm zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Und als Jesus getauft war, stieg er alsbald von dem Wasser herauf; und siehe, die Himmel wurden ihm aufgetan, und er sah den Geist Gottes wie eine Taube herniederfahren und auf ihn kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Und siehe, eine Stimme kommt aus den Himmeln, welche spricht: Dieser ist mein geliebter Sohn, an welchem ich Wohlgefallen gefunden habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Dann wurde Jesus von dem Geiste in die Wüste hinaufgeführt, um von dem Teufel versucht zu werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'und als er vierzig Tage und vierzig Nächte gefastet hatte, hungerte ihn danach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Und der Versucher trat zu ihm hin und sprach: Wenn du Gottes Sohn bist, so sprich, daß diese Steine Brot werden. Er aber antwortete und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Es steht geschrieben: \"Nicht von Brot allein soll der Mensch leben, sondern von jedem Worte, das durch den Mund Gottes ausgeht.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Dann nimmt der Teufel ihn mit in die heilige Stadt und stellt ihn auf die Zinne des Tempels');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'und spricht zu ihm: Wenn du Gottes Sohn bist, so wirf dich hinab; denn es steht geschrieben: \"Er wird seinen Engeln über dir befehlen, und sie werden dich auf den Händen tragen, damit du nicht etwa deinen Fuß an einen Stein stoßest.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jesus sprach zu ihm: Wiederum steht geschrieben: \"Du sollst den Herrn, deinen Gott, nicht versuchen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Wiederum nimmt der Teufel ihn mit auf einen sehr hohen Berg und zeigt ihm alle Reiche der Welt und ihre Herrlichkeit und spricht zu ihm:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'Alles dieses will ich dir geben, wenn du niederfallen und mich anbeten willst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Da spricht Jesus zu ihm: Geh hinweg, Satan! Denn es steht geschrieben: \"Du sollst den Herrn, deinen Gott, anbeten und ihm allein dienen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Dann verläßt ihn der Teufel, und siehe, Engel kamen herzu und dienten ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Als er aber gehört hatte, daß Johannes überliefert worden war, entwich er nach Galiläa;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'und er verließ Nazareth und kam und wohnte in Kapernaum, das am See liegt, in dem Gebiet von Zabulon und Nephtalim;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'auf daß erfüllt würde, was durch den Propheten Jesajas geredet ist, welcher spricht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '\"Land Zabulon und Land Nephtalim, gegen den See hin, jenseit des Jordan, Galiläa der Nationen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'das Volk, das in Finsternis saß, hat ein großes Licht gesehen, und denen, die im Lande und Schatten des Todes saßen, Licht ist ihnen aufgegangen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Von da an begann Jesus zu predigen und zu sagen: Tut Buße, denn das Reich der Himmel ist nahe gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Als er aber am See von Galiläa wandelte, sah er zwei Brüder: Simon, genannt Petrus, und Andreas, seinen Bruder, die ein Netz in den See warfen, denn sie waren Fischer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Und er spricht zu ihnen: Kommet mir nach, und ich werde euch zu Menschenfischern machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Sie aber verließen alsbald die Netze und folgten ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Und als er von dannen weiterging, sah er zwei andere Brüder: Jakobus, den Sohn des Zebedäus, und Johannes, seinen Bruder, im Schiffe mit ihrem Vater Zebedäus, wie sie ihre Netze ausbesserten; und er rief sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Sie aber verließen alsbald das Schiff und ihren Vater und folgten ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Und Jesus zog in ganz Galiläa umher, lehrte in ihren Synagogen und predigte das Evangelium des Reiches und heilte jede Krankheit und jedes Gebrechen unter dem Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Und sein Ruf ging aus in das ganze Syrien; und sie brachten zu ihm alle Leidenden, die mit mancherlei Krankheiten und Qualen behaftet waren, und Besessene und Mondsüchtige und Gelähmte; und er heilte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Und es folgten ihm große Volksmengen von Galiläa und Dekapolis und Jerusalem und Judäa und von jenseit des Jordan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Als er aber die Volksmengen sah, stieg er auf den Berg; und als er sich gesetzt hatte, traten seine Jünger zu ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Und er tat seinen Mund auf, lehrte sie und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Glückselig die Armen im Geiste, denn ihrer ist das Reich der Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Glückselig die Trauernden, denn sie werden getröstet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Glückselig die Sanftmütigen, denn sie werden das Land ererben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Glückselig die nach der Gerechtigkeit hungern und dürsten, denn sie werden gesättigt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Glückselig die Barmherzigen, denn ihnen wird Barmherzigkeit widerfahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Glückselig die reinen Herzens sind, denn sie werden Gott schauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Glückselig die Friedensstifter, denn sie werden Söhne Gottes heißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Glückselig die um Gerechtigkeit willen Verfolgten, denn ihrer ist das Reich der Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Glückselig seid ihr, wenn sie euch schmähen und verfolgen und jedes böse Wort lügnerisch wider euch reden werden um meinetwillen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Freuet euch und frohlocket, denn euer Lohn ist groß in den Himmeln; denn also haben sie die Propheten verfolgt, die vor euch waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Ihr seid das Salz der Erde; wenn aber das Salz kraftlos geworden ist, womit soll es gesalzen werden? Es taugt zu nichts mehr, als hinausgeworfen und von den Menschen zertreten zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Ihr seid das Licht der Welt; eine Stadt, die oben auf einem Berge liegt, kann nicht verborgen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Man zündet auch nicht eine Lampe an und setzt sie unter den Scheffel sondern auf das Lampengestell, und sie leuchtet allen, die im Hause sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Also lasset euer Licht leuchten vor den Menschen, damit sie eure guten Werke sehen und euren Vater, der in den Himmeln ist, verherrlichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Wähnet nicht, daß ich gekommen sei, das Gesetz oder die Propheten aufzulösen; ich bin nicht gekommen, aufzulösen, sondern zu erfüllen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Denn wahrlich, ich sage euch: Bis der Himmel und die Erde vergehen, soll auch nicht ein Jota oder ein Strichlein von dem Gesetz vergehen, bis alles geschehen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Wer irgend nun eines dieser geringsten Gebote auflöst und also die Menschen lehrt, wird der Geringste heißen im Reiche der Himmel; wer irgend aber sie tut und lehrt, dieser wird groß heißen im Reiche der Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Denn ich sage euch: Wenn nicht eure Gerechtigkeit vorzüglicher ist als die der Schriftgelehrten und Pharisäer, so werdet ihr nicht in das Reich der Himmel eingehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Ihr habt gehört, daß zu den Alten gesagt ist: Du sollst nicht töten; wer aber irgend töten wird, wird dem Gericht verfallen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Ich aber sage euch, daß jeder, der seinem Bruder ohne Grund zürnt, dem Gericht verfallen sein wird; wer aber irgend zu seinem Bruder sagt: Raka! dem Synedrium verfallen sein wird; wer aber irgend sagt: Du Narr! der Hölle des Feuers verfallen sein wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Wenn du nun deine Gabe darbringst zu dem Altar und dich daselbst erinnerst, daß dein Bruder etwas wider dich habe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'so laß daselbst deine Gabe vor dem Altar und geh zuvor hin, versöhne dich mit deinem Bruder; und dann komm und bringe deine Gabe dar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Willfahre deiner Gegenpartei schnell, während du mit ihr auf dem Wege bist; damit nicht etwa die Gegenpartei dich dem Richter überliefere, und der Richter dich dem Diener überliefere, und du ins Gefängnis geworfen werdest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Wahrlich, ich sage dir: Du wirst nicht von dannen herauskommen, bis du auch den letzten Pfennig bezahlt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Ihr habt gehört, daß gesagt ist: Du sollst nicht ehebrechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Ich aber sage euch, daß jeder, der ein Weib ansieht, ihrer zu begehren, schon Ehebruch mit ihr begangen hat in seinem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Wenn aber dein rechtes Auge dich ärgert, so reiß es aus und wirf es von dir; denn es ist dir nütze, daß eines deiner Glieder umkomme und nicht dein ganzer Leib in die Hölle geworfen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Und wenn deine rechte Hand dich ärgert, so haue sie ab und wirf sie von dir; denn es ist dir nütze, daß eines deiner Glieder umkomme und nicht dein ganzer Leib in die Hölle geworfen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Es ist aber gesagt: Wer irgend sein Weib entlassen wird, gebe ihr einen Scheidebrief.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Ich aber sage euch: Wer irgend sein Weib entlassen wird, außer auf Grund von Hurerei, macht, daß sie Ehebruch begeht; und wer irgend eine Entlassene heiratet, begeht Ehebruch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Wiederum habt ihr gehört, daß zu den Alten gesagt ist: Du sollst nicht fälschlich schwören, du sollst aber dem Herrn deine Eide erfüllen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Ich aber sage euch: Schwöret überhaupt nicht; weder bei dem Himmel, denn er ist Gottes Thron;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'noch bei der Erde, denn sie ist seiner Füße Schemel; noch bei Jerusalem, denn sie ist des großen Königs Stadt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'noch sollst du bei deinem Haupte schwören, denn du vermagst nicht, ein Haar weiß oder schwarz zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Es sei aber eure Rede: Ja, ja; nein, nein; was aber mehr ist als dieses, ist aus dem Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Ihr habt gehört, daß gesagt ist: Auge um Auge, und Zahn um Zahn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Ich aber sage euch: Widerstehet nicht dem Bösen, sondern wer irgend dich auf deinen rechten Backen schlagen wird, dem biete auch den anderen dar;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'und dem, der mit dir vor Gericht gehen und deinen Leibrock nehmen will, dem laß auch den Mantel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'Und wer irgend dich zwingen wird, eine Meile zu gehen, mit dem geh zwei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Gib dem, der dich bittet, und weise den nicht ab, der von dir borgen will.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Ihr habt gehört, daß gesagt ist: Du sollst deinen Nächsten lieben und deinen Feind hassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Ich aber sage euch: Liebet eure Feinde, segnet, die euch fluchen, tut wohl denen, die euch hassen, und betet für die, die euch beleidigen und verfolgen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'damit ihr Söhne eures Vaters seid, der in den Himmeln ist; denn er läßt seine Sonne aufgehen über Böse und Gute und läßt regnen über Gerechte und Ungerechte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Denn wenn ihr liebet, die euch lieben, welchen Lohn habt ihr? Tun nicht auch die Zöllner dasselbe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Und wenn ihr eure Brüder allein grüßet, was tut ihr Besonderes? Tun nicht auch die von den Nationen dasselbe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Ihr nun sollt vollkommen sein, wie euer himmlischer Vater vollkommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Habet acht, daß ihr euer Almosen nicht gebet vor den Menschen, um von ihnen gesehen zu werden; wenn aber nicht, so habt ihr keinen Lohn bei eurem Vater, der in den Himmeln ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Wenn du nun Almosen gibst, sollst du nicht vor dir her posaunen lassen, wie die Heuchler tun in den Synagogen und auf den Straßen, damit sie von den Menschen geehrt werden. Wahrlich, ich sage euch, sie haben ihren Lohn dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Du aber, wenn du Almosen gibst, so laß deine Linke nicht wissen, was deine Rechte tut;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'damit dein Almosen im Verborgenen sei, und dein Vater, der im Verborgenen sieht, wird dir vergelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Und wenn du betest, sollst du nicht sein wie die Heuchler; denn die lieben es, in den Synagogen und an den Ecken der Straßen stehend zu beten, damit sie von den Menschen gesehen werden. Wahrlich, ich sage euch, sie haben ihren Lohn dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Du aber, wenn du betest, so geh in deine Kammer und, nachdem du deine Tür geschlossen hast, bete zu deinem Vater, der im Verborgenen ist, und dein Vater, der im Verborgenen sieht, wird dir vergelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Wenn ihr aber betet, sollt ihr nicht plappern wie die von den Nationen; denn sie meinen, daß sie um ihres vielen Redens willen werden erhört werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Seid ihnen nun nicht gleich; denn euer Vater weiß, was ihr bedürfet, ehe ihr ihn bittet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Betet ihr nun also: Unser Vater, der du bist in den Himmeln, geheiligt werde dein Name; dein Reich komme;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'dein Wille geschehe, wie im Himmel also auch auf Erden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Unser nötiges Brot gib uns heute;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'und vergib uns unsere Schulden, wie auch wir unseren Schuldnern vergeben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'und führe uns nicht in Versuchung, sondern errette uns von dem Bösen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Denn wenn ihr den Menschen ihre Vergehungen vergebet, so wird euer himmlischer Vater auch euch vergeben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'wenn ihr aber den Menschen ihre Vergehungen nicht vergebet, so wird euer Vater auch eure Vergehungen nicht vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Wenn ihr aber fastet, so sehet nicht düster aus wie die Heuchler; denn sie verstellen ihre Angesichter, damit sie den Menschen als Fastende erscheinen. Wahrlich, ich sage euch, sie haben ihren Lohn dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Du aber, wenn du fastest, so salbe dein Haupt und wasche dein Angesicht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'damit du nicht den Menschen als ein Fastender erscheinest, sondern deinem Vater, der im Verborgenen ist; und dein Vater, der im Verborgenen sieht, wird dir vergelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Sammelt euch nicht Schätze auf der Erde, wo Motte und Rost zerstört, und wo Diebe durchgraben und stehlen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'sammelt euch aber Schätze im Himmel, wo weder Motte noch Rost zerstört, und wo Diebe nicht durchgraben noch stehlen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'denn wo dein Schatz ist, da wird auch dein Herz sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Die Lampe des Leibes ist das Auge; wenn nun dein Auge einfältig ist, so wird dein ganzer Leib licht sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'wenn aber dein Auge böse ist, so wird dein ganzer Leib finster sein. Wenn nun das Licht, das in dir ist, Finsternis ist, wie groß die Finsternis!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Niemand kann zwei Herren dienen; denn entweder wird er den einen hassen und den anderen lieben, oder er wird einem anhangen und den anderen verachten. Ihr könnet nicht Gott dienen und dem Mammon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Deshalb sage ich euch: Seid nicht besorgt für euer Leben, was ihr essen und was ihr trinken sollt, noch für euren Leib, was ihr anziehen sollt. Ist nicht das Leben mehr als die Speise, und der Leib mehr als die Kleidung?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Sehet hin auf die Vögel des Himmels, daß sie nicht säen noch ernten, noch in Scheunen sammeln, und euer himmlischer Vater ernährt sie. Seid ihr nicht viel vorzüglicher als sie?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Wer aber unter euch vermag mit Sorgen seiner Größe eine Elle zuzusetzen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Und warum seid ihr um Kleidung besorgt? Betrachtet die Lilien des Feldes, wie sie wachsen: sie mühen sich nicht, auch spinnen sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Ich sage euch aber, daß selbst nicht Salomon in all seiner Herrlichkeit bekleidet war wie eine von diesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Wenn aber Gott das Gras des Feldes, das heute ist und morgen in den Ofen geworfen wird, also kleidet, nicht vielmehr euch, Kleingläubige?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'So seid nun nicht besorgt, indem ihr saget: Was sollen wir essen? oder: Was sollen wir trinken? oder: Was sollen wir anziehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'denn nach allem diesem trachten die Nationen; denn euer himmlischer Vater weiß, daß ihr dies alles bedürfet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Trachtet aber zuerst nach dem Reiche Gottes und nach seiner Gerechtigkeit, und dies alles wird euch hinzugefügt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'So seid nun nicht besorgt auf den morgenden Tag, denn der morgende Tag wird für sich selbst sorgen. Jeder Tag hat an seinem Übel genug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Richtet nicht, auf daß ihr nicht gerichtet werdet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'denn mit welchem Gericht ihr richtet, werdet ihr gerichtet werden, und mit welchem Maße ihr messet, wird euch gemessen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Was aber siehst du den Splitter, der in deines Bruders Auge ist, den Balken aber in deinem Auge nimmst du nicht wahr?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Oder wie wirst du zu deinem Bruder sagen: Erlaube, ich will den Splitter aus deinem Auge ziehen; und siehe, der Balken ist in deinem Auge?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Heuchler, ziehe zuerst den Balken aus deinem Auge, und dann wirst du klar sehen, um den Splitter aus deines Bruders Auge zu ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Gebet nicht das Heilige den Hunden; werfet auch nicht eure Perlen vor die Schweine, damit sie dieselben nicht etwa mit ihren Füßen zertreten und sich umwenden und euch zerreißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Bittet, und es wird euch gegeben werden; suchet, und ihr werdet finden; klopfet an, und es wird euch aufgetan werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Denn jeder Bittende empfängt, und der Suchende findet, und dem Anklopfenden wird aufgetan werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Oder welcher Mensch ist unter euch, der, wenn sein Sohn ihn um ein Brot bitten würde, ihm einen Stein geben wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Und wenn er um einen Fisch bitten würde, ihm eine Schlange gegeben wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Wenn nun ihr, die ihr böse seid, euren Kindern gute Gaben zu geben wisset, wieviel mehr wird euer Vater, der in den Himmeln ist, Gutes geben denen, die ihn bitten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Alles nun, was immer ihr wollt, daß euch die Menschen tun sollen, also tut auch ihr ihnen; denn dies ist das Gesetz und die Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Gehet ein durch die enge Pforte; denn weit ist die Pforte und breit der Weg, der zum Verderben führt, und viele sind, die durch dieselbe eingehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Denn eng ist die Pforte und schmal der Weg, der zum Leben führt, und wenige sind, die ihn finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Hütet euch aber vor den falschen Propheten, die in Schafskleidern zu euch kommen, inwendig aber sind sie reißende Wölfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'An ihren Früchten werdet ihr sie erkennen. Liest man etwa von Dornen eine Traube, oder von Disteln Feigen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Also bringt jeder gute Baum gute Früchte, aber der faule Baum bringt schlechte Früchte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Ein guter Baum kann nicht schlechte Früchte bringen, noch ein fauler Baum gute Früchte bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Jeder Baum, der nicht gute Frucht bringt, wird abgehauen und ins Feuer geworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Deshalb, an ihren Früchten werdet ihr sie erkennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Nicht jeder, der zu mir sagt: Herr, Herr! wird in das Reich der Himmel eingehen, sondern wer den Willen meines Vaters tut, der in den Himmeln ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Viele werden an jenem Tage zu mir sagen: Herr, Herr! Haben wir nicht durch deinen Namen geweissagt, und durch deinen Namen Dämonen ausgetrieben, und durch deinen Namen viele Wunderwerke getan?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Und dann werde ich ihnen bekennen: Ich habe euch niemals gekannt; weichet von mir, ihr Übeltäter!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Jeder nun, der irgend diese meine Worte hört und sie tut, den werde ich einem klugen Manne vergleichen, der sein Haus auf den Felsen baute;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'und der Platzregen fiel hernieder, und die Ströme kamen, und die Winde wehten und stürmten wider jenes Haus; und es fiel nicht, denn es war auf den Felsen gegründet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Und jeder, der diese meine Worte hört und sie nicht tut, der wird einem törichten Manne verglichen werden, der sein Haus auf den Sand baute;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'und der Platzregen fiel hernieder, und die Ströme kamen, und die Winde wehten und stießen an jenes Haus; und es fiel, und sein Fall war groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Und es geschah, als Jesus diese Worte vollendet hatte, da erstaunten die Volksmengen sehr über seine Lehre;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'denn er lehrte sie wie einer, der Gewalt hat, und nicht wie ihre Schriftgelehrten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Als er aber von dem Berge herabgestiegen war, folgten ihm große Volksmengen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Und siehe, ein Aussätziger kam herzu und warf sich vor ihm nieder und sprach: Herr, wenn du willst, kannst du mich reinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Und er streckte seine Hand aus, rührte ihn an und sprach: Ich will; sei gereinigt! Und alsbald wurde sein Aussatz gereinigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Und Jesus spricht zu ihm: Siehe, sage es niemand; sondern gehe hin, zeige dich dem Priester, und bringe die Gabe dar, die Moses angeordnet hat, ihnen zum Zeugnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Als er aber in Kapernaum eintrat, kam ein Hauptmann zu ihm, der ihn bat und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'Herr, mein Knecht liegt zu Hause gelähmt und wird schrecklich gequält.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Und Jesus spricht zu ihm: Ich will kommen und ihn heilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Der Hauptmann aber antwortete und sprach: Herr, ich bin nicht würdig, daß du unter mein Dach tretest; sondern sprich nur ein Wort, und mein Knecht wird gesund werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Denn auch ich bin ein Mensch unter Gewalt und habe Kriegsknechte unter mir; und ich sage zu diesem: Gehe hin, und er geht; und zu einem anderen: Komm, und er kommt; und zu meinem Knechte: Tue dieses, und er tut\'s.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Als aber Jesus es hörte, verwunderte er sich und sprach zu denen, welche nachfolgten: Wahrlich, ich sage euch, selbst nicht in Israel habe ich so großen Glauben gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Ich sage euch aber, daß viele von Osten und Westen kommen und mit Abraham und Isaak und Jakob zu Tische liegen werden in dem Reiche der Himmel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'aber die Söhne des Reiches werden hinausgeworfen werden in die äußere Finsternis: da wird sein das Weinen und das Zähneknirschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Und Jesus sprach zu dem Hauptmann: Gehe hin, und dir geschehe, wie du geglaubt hast. Und sein Knecht wurde gesund in jener Stunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Und als Jesus in das Haus des Petrus gekommen war, sah er dessen Schwiegermutter fieberkrank daniederliegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Und er rührte ihre Hand an, und das Fieber verließ sie; und sie stand auf und diente ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Als es aber Abend geworden war, brachten sie viele Besessene zu ihm; und er trieb die Geister aus mit einem Worte, und er heilte alle Leidenden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'damit erfüllt würde, was durch den Propheten Jesaias geredet ist, welcher spricht: \"Er selbst nahm unsere Schwachheiten und trug unsere Krankheiten.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Als aber Jesus eine große Volksmenge um sich sah, befahl er, an das jenseitige Ufer hinwegzufahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Und ein Schriftgelehrter kam herzu und sprach zu ihm: Lehrer, ich will dir nachfolgen, wohin irgend du gehst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Und Jesus spricht zu ihm: Die Füchse haben Höhlen, und die Vögel des Himmels Nester, aber der Sohn des Menschen hat nicht, wo er das Haupt hinlege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Ein anderer aber von seinen Jüngern sprach zu ihm: Herr, erlaube mir, zuvor hinzugehen und meinen Vater zu begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Jesus aber sprach zu ihm: Folge mir nach, und laß die Toten ihre Toten begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Und als er in das Schiff gestiegen war, folgten ihm seine Jünger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Und siehe, es erhob sich ein großes Ungestüm auf dem See, so daß das Schiff von den Wellen bedeckt wurde; er aber schlief.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Und die Jünger traten hinzu, weckten ihn auf und sprachen: Herr, rette uns, wir kommen um!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Und er spricht zu ihnen: Was seid ihr furchtsam, Kleingläubige? Dann stand er auf und bedrohte die Winde und den See; und es ward eine große Stille.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Die Menschen aber verwunderten sich und sprachen: Was für einer ist dieser, daß auch die Winde und der See ihm gehorchen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Und als er an das jenseitige Ufer gekommen war, in das Land der Gergesener, begegneten ihm zwei Besessene, die aus den Grüften hervorkamen, sehr wütend, so daß niemand jenes Weges vorbeizugehen vermochte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Und siehe, sie schrieen und sprachen: Was haben wir mit dir zu schaffen, Sohn Gottes? Bist du hierhergekommen, vor der Zeit uns zu quälen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Es war aber fern von ihnen eine Herde vieler Schweine, welche weidete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Die Dämonen aber baten ihn und sprachen: Wenn du uns austreibst, so sende uns in die Herde Schweine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Und er sprach zu ihnen: Gehet hin. Sie aber fuhren aus und fuhren in die Herde Schweine. Und siehe, die ganze Herde Schweine stürzte sich den Abhang hinab in den See, und sie kamen um in dem Gewässer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Die Hüter aber flohen und gingen in die Stadt und verkündeten alles und das von den Besessenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Und siehe, die ganze Stadt ging hinaus, Jesu entgegen, und als sie ihn sahen, baten sie, daß er aus ihren Grenzen weggehen möchte. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Und er stieg in das Schiff, setzte über und kam in seine eigene Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Und siehe, sie brachten einen Gelähmten zu ihm, der auf einem Bette lag; und als Jesus ihren Glauben sah, sprach er zu dem Gelähmten: Sei guten Mutes, Kind, deine Sünden sind vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Und siehe, etliche von den Schriftgelehrten sprachen bei sich selbst: Dieser lästert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Und als Jesus ihre Gedanken sah, sprach er: Warum denket ihr Arges in euren Herzen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Denn was ist leichter, zu sagen: Deine Sünden sind vergeben, oder zu sagen: Stehe auf und wandle?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Auf daß ihr aber wisset, daß der Sohn des Menschen Gewalt hat auf der Erde Sünden zu vergeben.... Dann sagt er zu dem Gelähmten: Stehe auf, nimm dein Bett auf und geh nach deinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Und er stand auf und ging nach seinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Als aber die Volksmengen es sahen, fürchteten sie sich und verherrlichten Gott, der solche Gewalt den Menschen gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Und als Jesus von dannen weiterging, sah er einen Menschen am Zollhause sitzen, Matthäus genannt, und er spricht zu ihm: Folge mir nach. Und er stand auf und folgte ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Und es geschah, als er in dem Hause zu Tische lag, siehe, da kamen viele Zöllner und Sünder und lagen zu Tische mit Jesu und seinen Jüngern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Und als die Pharisäer es sahen, sprachen sie zu seinen Jüngern: Warum isset euer Lehrer mit den Zöllnern und Sündern?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Als aber Jesus es hörte, sprach er: Die Starken bedürfen nicht eines Arztes, sondern die Kranken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Gehet aber hin und lernet, was das ist: \"Ich will Barmherzigkeit und nicht Schlachtopfer\"; denn ich bin nicht gekommen, Gerechte zu rufen, sondern Sünder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Dann kommen die Jünger des Johannes zu ihm und sagen: Warum fasten wir und die Pharisäer oft, deine Jünger aber fasten nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Und Jesus sprach zu ihnen: Können etwa die Gefährten des Bräutigams trauern, so lange der Bräutigam bei ihnen ist? Es werden aber Tage kommen, da der Bräutigam von ihnen weggenommen sein wird, und dann werden sie fasten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Niemand aber setzt einen Flicken von neuem Tuch auf ein altes Kleid; denn das Eingesetzte reißt von dem Kleide ab, und der Riß wird ärger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Auch tut man nicht neuen Wein in alte Schläuche; sonst zerreißen die Schläuche, und der Wein wird verschüttet, und die Schläuche verderben; sondern man tut neuen Wein in neue Schläuche, und beide werden zusammen erhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Während er dies zu ihnen redete, siehe, da kam ein Vorsteher herein und warf sich vor ihm nieder und sprach: Meine Tochter ist eben jetzt verschieden; aber komm und lege deine Hand auf sie, und sie wird leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Und Jesus stand auf und folgte ihm, und seine Jünger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Und siehe, ein Weib, das zwölf Jahre blutflüssig war, trat von hinten herzu und rührte die Quaste seines Kleides an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'denn sie sprach bei sich selbst: Wenn ich nur sein Kleid anrühre, so werde ich geheilt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Jesus aber wandte sich um, und als er sie sah, sprach er: Sei gutes Mutes, Tochter; dein Glaube hat dich geheilt. Und das Weib war geheilt von jener Stunde an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Und als Jesus in das Haus des Vorstehers kam und die Pfeifer und die lärmende Volksmenge sah,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'sprach er: Gehet fort, denn das Mägdlein ist nicht gestorben, sondern es schläft. Und sie verlachten ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Als aber die Volksmenge hinausgetrieben war, ging er hinein und ergriff sie bei der Hand; und das Mägdlein stand auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Und das Gerücht hiervon ging aus in jenes ganze Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Und als Jesus von dannen weiterging, folgten ihm zwei Blinde, welche schrieen und sprachen: Erbarme dich unser, Sohn Davids!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Als er aber in das Haus gekommen war, traten die Blinden zu ihm; und Jesus spricht zu ihnen: Glaubet ihr, daß ich dieses tun kann? Sie sagen zu ihm: Ja, Herr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Dann rührte er ihre Augen an und sprach: Euch geschehe nach eurem Glauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Und ihre Augen wurden aufgetan; und Jesus bedrohte sie und sprach: Sehet zu, niemand erfahre es!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Sie aber gingen aus und machten ihn ruchbar in jenem ganzen Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Als sie aber weggingen, siehe, da brachten sie einen stummen Menschen zu ihm, der besessen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Und als der Dämon ausgetrieben war, redete der Stumme. Und die Volksmengen verwunderten sich und sprachen: Niemals ward es also in Israel gesehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Die Pharisäer aber sagten: Er treibt die Dämonen aus durch den Obersten der Dämonen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Und Jesus zog umher durch alle Städte und Dörfer und lehrte in ihren Synagogen und predigte das Evangelium des Reiches und heilte jede Krankheit und jedes Gebrechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Als er aber die Volksmengen sah, wurde er innerlich bewegt über sie, weil sie erschöpft und verschmachtet waren wie Schafe, die keinen Hirten haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Dann spricht er zu seinen Jüngern: Die Ernte zwar ist groß, der Arbeiter aber sind wenige;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'bittet nun den Herrn der Ernte, daß er die Arbeiter aussende in seine Ernte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Und als er seine zwölf Jünger herzugerufen hatte, gab er ihnen Gewalt über unreine Geister, um sie auszutreiben, und jede Krankheit und jedes Gebrechen zu heilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Die Namen der zwölf Apostel aber sind diese: Der erste, Simon, der Petrus genannt wird, und Andreas, sein Bruder; Jakobus, der Sohn des Zebedäus, und Johannes, sein Bruder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Philippus und Bartholomäus; Thomas und Matthäus, der Zöllner; Jakobus, der Sohn des Alphäus, und Lebbäus, der zubenamt war Thaddäus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon, der Kananäer, und Judas, der Iskariot, der ihn auch überlieferte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Diese zwölf sandte Jesus aus und befahl ihnen und sprach: Gehet nicht auf einen Weg der Nationen, und gehet nicht in eine Stadt der Samariter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'gehet aber vielmehr zu den verlorenen Schafen des Hauses Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Indem ihr aber hingehet, prediget und sprechet: Das Reich der Himmel ist nahe gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Heilet Kranke, wecket Tote auf, reiniget Aussätzige, treibet Dämonen aus; umsonst habt ihr empfangen, umsonst gebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Verschaffet euch nicht Gold noch Silber noch Kupfer in eure Gürtel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'keine Tasche auf den Weg, noch zwei Leibröcke, noch Sandalen, noch einen Stab; denn der Arbeiter ist seiner Nahrung wert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'In welche Stadt aber oder in welches Dorf irgend ihr eintretet, erforschet, wer darin würdig ist; und daselbst bleibet, bis ihr weggehet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Wenn ihr aber in das Haus eintretet, so grüßet es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Und wenn nun das Haus würdig ist, so komme euer Friede auf dasselbe; wenn es aber nicht würdig ist, so wende sich euer Friede zu euch zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Und wer irgend euch nicht aufnehmen, noch eure Worte hören wird, gehet hinaus aus jenem Hause oder jener Stadt und schüttelt den Staub von euren Füßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Wahrlich, ich sage euch, es wird dem Lande von Sodom und Gomorra erträglicher ergehen am Tage des Gerichts als jener Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Siehe, ich sende euch wie Schafe inmitten von Wölfen; so seid nun klug wie die Schlangen und einfältig wie die Tauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Hütet euch aber vor den Menschen; denn sie werden euch an Synedrien überliefern und in ihren Synagogen euch geißeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'und auch vor Statthalter und Könige werdet ihr geführt werden um meinetwillen, ihnen und den Nationen zum Zeugnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Wenn sie euch aber überliefern, so seid nicht besorgt, wie oder was ihr reden sollt; denn es wird euch in jener Stunde gegeben werden, was ihr reden sollt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Denn nicht ihr seid die Redenden, sondern der Geist eures Vaters, der in euch redet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Es wird aber der Bruder den Bruder zum Tode überliefern, und der Vater das Kind; und Kinder werden sich erheben wider die Eltern und sie zum Tode bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Und ihr werdet von allen gehaßt werden um meines Namens willen. Wer aber ausharrt bis ans Ende, dieser wird errettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Wenn sie euch aber verfolgen in dieser Stadt, so fliehet in die andere; denn wahrlich, ich sage euch, ihr werdet mit den Städten Israels nicht zu Ende sein, bis der Sohn des Menschen gekommen sein wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Ein Jünger ist nicht über den Lehrer, und ein Knecht nicht über seinen Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Es ist dem Jünger genug, daß er sei wie sein Lehrer, und der Knecht wie sein Herr. Wenn sie den Hausherrn Beelzebub genannt haben, wieviel mehr seine Hausgenossen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Fürchtet euch nun nicht vor ihnen. Denn es ist nichts verdeckt, was nicht aufgedeckt, und verborgen, was nicht kundwerden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Was ich euch sage in der Finsternis, redet in dem Lichte, und was ihr höret ins Ohr, rufet aus auf den Dächern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Und fürchtet euch nicht vor denen, die den Leib töten, die Seele aber nicht zu töten vermögen; fürchtet aber vielmehr den, der sowohl Seele als Leib zu verderben vermag in der Hölle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Werden nicht zwei Sperlinge um einen Pfennig verkauft? Und nicht einer von ihnen fällt auf die Erde ohne euren Vater;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'an euch aber sind selbst die Haare des Hauptes alle gezählt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Fürchtet euch nun nicht; ihr seid vorzüglicher als viele Sperlinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Ein jeder nun, der mich vor den Menschen bekennen wird, den werde auch ich bekennen vor meinem Vater, der in den Himmeln ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Wer aber irgend mich vor den Menschen verleugnen wird, den werde auch ich verleugnen vor meinem Vater, der in den Himmeln ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Wähnet nicht, daß ich gekommen sei, Frieden auf die Erde zu bringen; ich bin nicht gekommen, Frieden zu bringen, sondern das Schwert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Denn ich bin gekommen, den Menschen zu entzweien mit seinem Vater, und die Tochter mit ihrer Mutter, und die Schwiegertochter mit ihrer Schwiegermutter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'und des Menschen Feinde werden seine eigenen Hausgenossen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Wer Vater oder Mutter mehr liebt als mich, ist meiner nicht würdig; und wer Sohn oder Tochter mehr liebt als mich, ist meiner nicht würdig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'und wer nicht sein Kreuz aufnimmt und mir nachfolgt, ist meiner nicht würdig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Wer sein Leben findet, wird es verlieren, und wer sein Leben verliert um meinetwillen, wird es finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Wer euch aufnimmt, nimmt mich auf, und wer mich aufnimmt, nimmt den auf, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Wer einen Propheten aufnimmt in eines Propheten Namen, wird eines Propheten Lohn empfangen; und wer einen Gerechten aufnimmt in eines Gerechten Namen, wird eines Gerechten Lohn empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Und wer irgend einen dieser Kleinen nur mit einem Becher kalten Wassers tränken wird in eines Jüngers Namen, wahrlich, ich sage euch, er wird seinen Lohn nicht verlieren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Und es geschah, als Jesus seine Befehle an seine zwölf Jünger vollendet hatte, ging er von dannen hinweg, um in ihren Städten zu lehren und zu predigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Als aber Johannes im Gefängnis die Werke des Christus hörte, sandte er durch seine Jünger');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'und ließ ihm sagen: Bist du der Kommende, oder sollen wir auf einen anderen warten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Und Jesus antwortete und sprach zu ihnen: Gehet hin und verkündet Johannes, was ihr höret und sehet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Blinde werden sehend, und Lahme wandeln, Aussätzige werden gereinigt, und Taube hören, und Tote werden auferweckt, und Armen wird gute Botschaft verkündigt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'und glückselig ist, wer irgend sich nicht an mir ärgern wird!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Als diese aber hingingen, fing Jesus an, zu den Volksmengen zu reden über Johannes: Was seid ihr in die Wüste hinausgegangen zu sehen? Ein Rohr vom Winde hin und her bewegt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Aber was seid ihr hinausgegangen zu sehen? Einen Menschen, mit weichen Kleidern angetan? Siehe, die die weichen Kleider tragen, sind in den Häusern der Könige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Aber was seid ihr hinausgegangen zu sehen? Einen Propheten? Ja, sage ich euch, und mehr als einen Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Denn dieser ist es, von dem geschrieben steht: \"Siehe, ich sende meinen Boten vor deinem Angesicht her, der deinen Weg vor dir bereiten wird.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Wahrlich, ich sage euch, unter den von Weibern Geborenen ist kein Größerer aufgestanden als Johannes der Täufer; der Kleinste aber im Reiche der Himmel ist größer als er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Aber von den Tagen Johannes\' des Täufers an bis jetzt wird dem Reiche der Himmel Gewalt angetan, und Gewalttuende reißen es an sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Denn alle Propheten und das Gesetz haben geweissagt bis auf Johannes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Und wenn ihr es annehmen wollt, er ist Elias, der kommen soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Wer Ohren hat zu hören, der höre!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Wem aber soll ich dieses Geschlecht vergleichen? Es ist Kindern gleich, die auf den Märkten sitzen und ihren Gespielen zurufen und sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'Wir haben euch gepfiffen, und ihr habt nicht getanzt; wir haben euch Klagelieder gesungen, und ihr habt nicht gewehklagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Denn Johannes ist gekommen, der weder aß noch trank, und sie sagen: Er hat einen Dämon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Der Sohn des Menschen ist gekommen, der da ißt und trinkt, und sie sagen: Siehe, ein Fresser und Weinsäufer, ein Freund der Zöllner und Sünder; und die Weisheit ist gerechtfertigt worden von ihren Kindern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Dann fing er an, die Städte zu schelten, in welchen seine meisten Wunderwerke geschehen waren, weil sie nicht Buße getan hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Wehe dir, Chorazin! Wehe dir, Bethsaida! Denn wenn zu Tyrus und Sidon die Wunderwerke geschehen wären, die unter euch geschehen sind, längst hätten sie in Sack und Asche Buße getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Doch ich sage euch: Tyrus und Sidon wird es erträglicher ergehen am Tage des Gerichts als euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Und du, Kapernaum, die du bis zum Himmel erhöht worden bist, bis zum Hades wirst du hinabgestoßen werden; denn wenn in Sodom die Wunderwerke geschehen wären, die in dir geschehen sind, es wäre geblieben bis auf den heutigen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Doch ich sage euch: Dem Sodomer Lande wird es erträglicher ergehen am Tage des Gerichts als dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'Zu jener Zeit hob Jesus an und sprach: Ich preise dich, Vater, Herr des Himmels und der Erde, daß du dies vor Weisen und Verständigen verborgen hast, und hast es Unmündigen geoffenbart.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Ja, Vater, denn also war es wohlgefällig vor dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Alles ist mir übergeben von meinem Vater; und niemand erkennt den Sohn, als nur der Vater, noch erkennt jemand den Vater, als nur der Sohn, und wem irgend der Sohn ihn offenbaren will.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Kommet her zu mir, alle ihr Mühseligen und Beladenen, und ich werde euch Ruhe geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Nehmet auf euch mein Joch und lernet von mir, denn ich bin sanftmütig und von Herzen demütig, und ihr werdet Ruhe finden für eure Seelen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'denn mein Joch ist sanft, und meine Last ist leicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Zu jener Zeit ging Jesus am Sabbath durch die Saaten; es hungerte aber seine Jünger, und sie fingen an, Ähren abzupflücken und zu essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Als aber die Pharisäer es sahen, sprachen sie zu ihm: Siehe, deine Jünger tun, was am Sabbath zu tun nicht erlaubt ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Er aber sprach zu ihnen: Habt ihr nicht gelesen, was David tat, als ihn und die bei ihm waren hungerte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Wie er in das Haus Gottes ging und die Schaubrote aß, welche er nicht essen durfte, noch die bei ihm waren, sondern allein die Priester?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Oder habt ihr nicht in dem Gesetz gelesen, daß an den Sabbathen die Priester in dem Tempel den Sabbath entheiligen und schuldlos sind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Ich sage euch aber: Größeres als der Tempel ist hier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Wenn ihr aber erkannt hättet, was es ist: \"Ich will Barmherzigkeit und nicht Schlachtopfer\", so würdet ihr die Schuldlosen nicht verurteilt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Denn der Sohn des Menschen ist Herr des Sabbaths.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Und als er von dannen weiterging, kam er in ihre Synagoge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Und siehe, da war ein Mensch, der eine verdorrte Hand hatte. Und sie fragten ihn und sprachen: Ist es erlaubt, an den Sabbathen zu heilen? auf daß sie ihn anklagen möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Er aber sprach zu ihnen: Welcher Mensch wird unter euch sein, der ein Schaf hat und, wenn dieses am Sabbath in eine Grube fiele, es nicht ergreifen und aufrichten wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Wieviel vorzüglicher ist nun ein Mensch als ein Schaf! Also ist es erlaubt, an den Sabbathen Gutes zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Dann spricht er zu dem Menschen: Strecke deine Hand aus. Und er streckte sie aus, und sie ward wiederhergestellt, gesund wie die andere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Die Pharisäer aber gingen hinaus und hielten Rat wider ihn, wie sie ihn umbrächten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Als aber Jesus es erkannte, entwich er von dannen; und es folgten ihm große Volksmengen, und er heilte sie alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Und er bedrohte sie, daß sie ihn nicht offenbar machten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'damit erfüllt würde, was durch den Propheten Jesaias geredet ist, welcher spricht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Siehe, mein Knecht, den ich erwählt habe, mein Geliebter, an welchem meine Seele Wohlgefallen gefunden hat; ich werde meinen Geist auf ihn legen, und er wird den Nationen Gericht ankündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Er wird nicht streiten noch schreien, noch wird jemand seine Stimme auf den Straßen hören;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'ein geknicktes Rohr wird er nicht zerbrechen, und einen glimmenden Docht wird er nicht auslöschen, bis er das Gericht hinausführe zum Siege;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'und auf seinen Namen werden die Nationen hoffen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Dann wurde ein Besessener zu ihm gebracht, blind und stumm; und er heilte ihn, so daß der Blinde und Stumme redete und sah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Und es erstaunten alle die Volksmengen und sagten: Dieser ist doch nicht etwa der Sohn Davids?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Die Pharisäer aber sagten, als sie es hörten: Dieser treibt die Dämonen nicht anders aus, als durch den Beelzebub, den Obersten der Dämonen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Da er aber ihre Gedanken wußte, sprach er zu ihnen: Jedes Reich, das wider sich selbst entzweit ist, wird verwüstet; und jede Stadt oder jedes Haus, das wider sich selbst entzweit ist, wird nicht bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Und wenn der Satan den Satan austreibt, so ist er wider sich selbst entzweit; wie wird denn sein Reich bestehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Und wenn ich durch Beelzebub die Dämonen austreibe, durch wen treiben eure Söhne sie aus? Darum werden sie eure Richter sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Wenn ich aber durch den Geist Gottes die Dämonen austreibe, so ist also das Reich Gottes zu euch hingekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Oder wie kann jemand in das Haus des Starken eindringen und seinen Hausrat rauben, wenn er nicht zuvor den Starken bindet? Und alsdann wird er sein Haus berauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Wer nicht mit mir ist, ist wider mich, und wer nicht mit mir sammelt, zerstreut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Deshalb sage ich euch: Jede Sünde und Lästerung wird den Menschen vergeben werden; aber die Lästerung des Geistes wird den Menschen nicht vergeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Und wer irgend ein Wort reden wird wider den Sohn des Menschen, dem wird vergeben werden; wer aber irgend wider den Heiligen Geist reden wird, dem wird nicht vergeben werden, weder in diesem Zeitalter noch in dem zukünftigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Entweder machet den Baum gut und seine Frucht gut, oder machet den Baum faul und seine Frucht faul; denn aus der Frucht wird der Baum erkannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Otternbrut! Wie könnt ihr Gutes reden, da ihr böse seid? Denn aus der Fülle des Herzens redet der Mund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Der gute Mensch bringt aus dem guten Schatze Gutes hervor, und der böse Mensch bringt aus dem bösen Schatze Böses hervor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Ich sage euch aber, daß von jedem unnützen Worte, das irgend die Menschen reden werden, sie von demselben Rechenschaft geben werden am Tage des Gerichts;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'denn aus deinen Worten wirst du gerechtfertigt werden, und aus deinen Worten wirst du verdammt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Dann antworteten ihm etliche der Schriftgelehrten und Pharisäer und sprachen: Lehrer, wir möchten ein Zeichen von dir sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Er aber antwortete und sprach zu ihnen: Ein böses und ehebrecherisches Geschlecht begehrt ein Zeichen, und kein Zeichen wird ihm gegeben werden, als nur das Zeichen Jonas\', des Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Denn gleichwie Jonas drei Tage und drei Nächte in dem Bauche des großen Fisches war, also wird der Sohn des Menschen drei Tage und drei Nächte in dem Herzen der Erde sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Männer von Ninive werden aufstehen im Gericht mit diesem Geschlecht und werden es verdammen, denn sie taten Buße auf die Predigt Jonas\'; und siehe, mehr als Jonas ist hier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Eine Königin des Südens wird auftreten im Gericht mit diesem Geschlecht und wird es verdammen, denn sie kam von den Enden der Erde, um die Weisheit Salomons zu hören; und siehe, mehr als Salomon ist hier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Wenn aber der unreine Geist von dem Menschen ausgefahren ist, so durchwandert er dürre Örter, Ruhe suchend, und findet sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Dann spricht er: Ich will in mein Haus zurückkehren, von wo ich ausgegangen bin; und wenn er kommt, findet er es leer, gekehrt und geschmückt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Dann geht er hin und nimmt sieben andere Geister mit sich, böser als er selbst, und sie gehen hinein und wohnen daselbst; und das Letzte jenes Menschen wird ärger als das Erste. Also wird es auch diesem bösen Geschlecht ergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Als er aber noch zu den Volksmengen redete, siehe, da standen seine Mutter und seine Brüder draußen und suchten ihn zu sprechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Und es sprach einer zu ihm: Siehe, deine Mutter und deine Brüder stehen draußen und suchen dich zu sprechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Er aber antwortete und sprach zu dem, der es ihm sagte: Wer ist meine Mutter, und wer sind meine Brüder?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Und er streckte seine Hand aus über seine Jünger und sprach: Siehe da, meine Mutter und meine Brüder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'denn wer irgend den Willen meines Vaters tun wird, der in den Himmeln ist, derselbe ist mein Bruder und meine Schwester und meine Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'An jenem Tage aber ging Jesus aus dem Hause hinaus und setzte sich an den See.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Und es versammelten sich große Volksmengen zu ihm, so daß er in ein Schiff stieg und sich setzte; und die ganze Volksmenge stand am Ufer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Und er redete vieles in Gleichnissen zu ihnen und sprach: Siehe, der Sämann ging aus zu säen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'und indem er säte, fiel etliches an den Weg, und die Vögel kamen und fraßen es auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Anderes aber fiel auf das Steinichte, wo es nicht viel Erde hatte; und alsbald ging es auf, weil es nicht tiefe Erde hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Als aber die Sonne aufging, wurde es verbrannt, und weil es keine Wurzel hatte, verdorrte es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Anderes aber fiel unter die Dornen; und die Dornen schossen auf und erstickten es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Anderes aber fiel auf die gute Erde und gab Frucht: das eine hundert-,das andere sechzig-,das andere dreißigfältig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Wer Ohren hat zu hören, der höre!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Und die Jünger traten herzu und sprachen zu ihm: Warum redest du in Gleichnissen zu ihnen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Er aber antwortete und sprach zu ihnen: Weil euch gegeben ist, die Geheimnisse des Reiches der Himmel zu wissen, jenen aber ist es nicht gegeben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'denn wer da hat, dem wird gegeben werden, und er wird Überfluß haben; wer aber nicht hat, von dem wird selbst, was er hat, genommen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Darum rede ich in Gleichnissen zu ihnen, weil sie sehend nicht sehen und hörend nicht hören, noch verstehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'und es wird an ihnen die Weissagung Jesaias\' erfüllt, welche sagt: \"Mit Gehör werdet ihr hören und doch nicht verstehen, und sehend werdet ihr sehen und doch nicht wahrnehmen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'denn das Herz dieses Volkes ist dick geworden, und mit den Ohren haben sie schwer gehört, und ihre Augen haben sie geschlossen, damit sie nicht etwa mit den Augen sehen und mit den Ohren hören und mit dem Herzen verstehen und sich bekehren, und ich sie heile.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Glückselig aber eure Augen, daß sie sehen, und eure Ohren, daß sie hören;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'denn wahrlich, ich sage euch: Viele Propheten und Gerechte haben begehrt zu sehen, was ihr anschauet, und haben es nicht gesehen; und zu hören, was ihr höret, und haben es nicht gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Höret ihr nun das Gleichnis vom Sämann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'So oft jemand das Wort vom Reiche hört und nicht versteht, kommt der Böse und reißt weg, was in sein Herz gesät war; dieser ist es, der an den Weg gesät ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Der aber auf das Steinichte gesät ist, dieser ist es, der das Wort hört und es alsbald mit Freuden aufnimmt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'er hat aber keine Wurzel in sich, sondern ist nur für eine Zeit; und wenn Drangsal entsteht oder Verfolgung um des Wortes willen, alsbald ärgert er sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Der aber unter die Dornen gesät ist, dieser ist es, der das Wort hört, und die Sorge dieses Lebens und der Betrug des Reichtums ersticken das Wort, und er bringt keine Frucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Der aber auf die gute Erde gesät ist, dieser ist es, der das Wort hört und versteht, welcher wirklich Frucht bringt; und der eine trägt hundert-,der andere sechzig-,der andere dreißigfältig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Ein anderes Gleichnis legte er ihnen vor und sprach: Das Reich der Himmel ist einem Menschen gleich geworden, der guten Samen auf seinen Acker säte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Während aber die Menschen schliefen, kam sein Feind und säte Unkraut mitten unter den Weizen und ging hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Als aber die Saat aufsproßte und Frucht brachte, da erschien auch das Unkraut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Es kamen aber die Knechte des Hausherrn hinzu und sprachen zu ihm: Herr, hast du nicht guten Samen auf deinen Acker gesät? Woher hat er denn Unkraut?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Er aber sprach zu ihnen: Ein feindseliger Mensch hat dies getan. Die Knechte aber sprachen zu ihm: Willst du denn, daß wir hingehen und es zusammenlesen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Er aber sprach: Nein, damit ihr nicht etwa beim Zusammenlesen des Unkrauts zugleich mit demselben den Weizen ausraufet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Laßt es beides zusammen wachsen bis zur Ernte, und zur Zeit der Ernte werde ich den Schnittern sagen: Leset zuerst das Unkraut zusammen und bindet es in Bündel, um es zu verbrennen; den Weizen aber sammelt in meine Scheune.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Ein anderes Gleichnis legte er ihnen vor und sprach: Das Reich der Himmel ist gleich einem Senfkorn, welches ein Mensch nahm und auf seinen Acker säte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'das zwar kleiner ist als alle Samen, wenn es aber gewachsen ist, so ist es größer als die Kräuter und wird ein Baum, so daß die Vögel des Himmels kommen und sich niederlassen in seinen Zweigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Ein anderes Gleichnis redete er zu ihnen: Das Reich der Himmel ist gleich einem Sauerteig, welchen ein Weib nahm und unter drei Maß Mehl verbarg, bis es ganz durchsäuert war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Dies alles redete Jesus in Gleichnissen zu den Volksmengen, und ohne Gleichnis redete er nicht zu ihnen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'damit erfüllt würde, was durch den Propheten geredet ist, welcher spricht: \"Ich werde meinen Mund auftun in Gleichnissen; ich werde aussprechen, was von Grundlegung der Welt an verborgen war.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Dann entließ er die Volksmengen und kam in das Haus; und seine Jünger traten zu ihm und sprachen: Deute uns das Gleichnis vom Unkraut des Ackers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Er aber antwortete und sprach: Der den guten Samen sät, ist der Sohn des Menschen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'der Acker aber ist die Welt; der gute Same aber, dies sind die Söhne des Reiches, das Unkraut aber sind die Söhne des Bösen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'der Feind aber, der es gesät hat, ist der Teufel; die Ernte aber ist die Vollendung des Zeitalters, die Schnitter aber sind Engel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Gleichwie nun das Unkraut zusammengelesen und im Feuer verbrannt wird, also wird es in der Vollendung des Zeitalters sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Der Sohn des Menschen wird seine Engel aussenden, und sie werden aus seinem Reiche alle Ärgernisse zusammenlesen und die das Gesetzlose tun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'und sie werden sie in den Feuerofen werfen: da wird sein das Weinen und das Zähneknirschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Dann werden die Gerechten leuchten wie die Sonne in dem Reiche ihres Vaters. Wer Ohren hat zu hören, der höre!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Das Reich der Himmel ist gleich einem im Acker verborgenen Schatz, welchen ein Mensch fand und verbarg; und vor Freude darüber geht er hin und verkauft alles, was er hat, und kauft jenen Acker.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Wiederum ist das Reich der Himmel gleich einem Kaufmann, der schöne Perlen sucht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'als er aber eine sehr kostbare Perle gefunden hatte, ging er hin und verkaufte alles, was er hatte, und kaufte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Wiederum ist das Reich der Himmel gleich einem Netze, das ins Meer geworfen wurde und von jeder Gattung zusammenbrachte, welches sie,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'als es voll war, ans Ufer heraufgezogen hatten; und sie setzten sich nieder und lasen die Guten in Gefäße zusammen, aber die Faulen warfen sie aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Also wird es in der Vollendung des Zeitalters sein: die Engel werden ausgehen und die Bösen aus der Mitte der Gerechten aussondern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'und sie in den Feuerofen werfen: da wird sein das Weinen und das Zähneknirschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Jesus spricht zu ihnen: Habt ihr dies alles verstanden? Sie sagen zu ihm: Ja, Herr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Er aber sprach zu ihnen: Darum ist jeder Schriftgelehrte, der im Reiche der Himmel unterrichtet ist, gleich einem Hausherrn, der aus seinem Schatze Neues und Altes hervorbringt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Und es geschah, als Jesus diese Gleichnisse vollendet hatte, ging er von dannen hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Und er kam in seine Vaterstadt und lehrte sie in ihrer Synagoge, so daß sie sehr erstaunten und sprachen: Woher diesem diese Weisheit und die Wunderwerke?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Ist dieser nicht der Sohn des Zimmermanns? Heißt nicht seine Mutter Maria, und seine Brüder Jakobus und Joseph und Simon und Judas?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Und seine Schwestern, sind sie nicht alle bei uns? Woher nun diesem dies alles?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Und sie ärgerten sich an ihm. Jesus aber sprach zu ihnen: Ein Prophet ist nicht ohne Ehre, außer in seiner Vaterstadt und in seinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Und er tat daselbst nicht viele Wunderwerke wegen ihres Unglaubens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Zu jener Zeit hörte Herodes, der Vierfürst, das Gerücht von Jesu und sprach zu seinen Knechten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Dieser ist Johannes der Täufer; er ist von den Toten auferstanden, und darum wirken solche Kräfte in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'denn Herodes hatte Johannes gegriffen, ihn gebunden und ins Gefängnis gesetzt, um der Herodias willen, des Weibes seines Bruders Philippus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Denn Johannes hatte ihm gesagt: Es ist dir nicht erlaubt, sie zu haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Und als er ihn töten wollte, fürchtete er die Volksmenge, weil sie ihn für einen Propheten hielten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Als aber der Geburtstag des Herodes begangen wurde, tanzte die Tochter der Herodias vor ihnen, und sie gefiel dem Herodes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'weshalb er mit einem Eide zusagte, ihr zu geben, um was irgend sie bitten würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Sie aber, von ihrer Mutter angewiesen, sagt: Gib mir hier auf einer Schüssel das Haupt Johannes\' es Täufers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Und der König wurde traurig; aber um der Eide und um derer willen, die mit zu Tische lagen, befahl er, es zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Und er sandte hin und ließ den Johannes im Gefängnis enthaupten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Und sein Haupt wurde auf einer Schüssel gebracht und dem Mägdlein gegeben, und sie brachte es ihrer Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Und seine Jünger kamen herzu, hoben den Leib auf und begruben ihn. Und sie kamen und verkündeten es Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Und als Jesus es hörte, entwich er von dannen in einem Schiffe an einen öden Ort besonders. Und als die Volksmengen es hörten, folgten sie ihm zu Fuß aus den Städten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Und als er hinausging, sah er eine große Volksmenge, und er wurde innerlich bewegt über sie und heilte ihre Schwachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Als es aber Abend geworden war, traten seine Jünger zu ihm und sprachen: Der Ort ist öde, und die Zeit ist schon vergangen; entlaß die Volksmengen, auf daß sie hingehen in die Dörfer und sich Speise kaufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Jesus aber sprach zu ihnen: Sie haben nicht nötig wegzugehen; gebet ihr ihnen zu essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Sie aber sagen zu ihm: Wir haben nichts hier als nur fünf Brote und zwei Fische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Er aber sprach: Bringet sie mir her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Und er befahl den Volksmengen, sich auf das Gras zu lagern, nahm die fünf Brote und die zwei Fische, blickte auf gen Himmel und segnete sie, und er brach die Brote und gab sie den Jüngern, die Jünger aber gaben sie den Volksmengen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Und sie aßen alle und wurden gesättigt. Und sie hoben auf, was an Brocken übrigblieb, zwölf Handkörbe voll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Die aber aßen, waren bei fünftausend Männer, ohne Weiber und Kindlein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Und alsbald nötigte er die Jünger, in das Schiff zu steigen und ihm an das jenseitige Ufer vorauszufahren, bis er die Volksmengen entlassen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Und als er die Volksmengen entlassen hatte, stieg er auf den Berg besonders, um zu beten. Als es aber Abend geworden, war er daselbst allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Das Schiff aber war schon mitten auf dem See und litt Not von den Wellen, denn der Wind war ihnen entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Aber in der vierten Nachtwache kam er zu ihnen, wandelnd auf dem See.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Und als die Jünger ihn auf dem See wandeln sahen, wurden sie bestürzt und sprachen: Es ist ein Gespenst! Und sie schrieen vor Furcht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Alsbald aber redete Jesus zu ihnen und sprach: Seid gutes Mutes, ich bin\'s; fürchtet euch nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Petrus aber antwortete ihm und sprach: Herr, wenn du es bist, so befiehl mir, zu dir zu kommen auf den Wassern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Er aber sprach: Komm! Und Petrus stieg aus dem Schiffe und wandelte auf den Wassern, um zu Jesu zu kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Als er aber den starken Wind sah, fürchtete er sich; und als er anfing zu sinken, schrie er und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Herr, rette mich! Alsbald aber streckte Jesus die Hand aus, ergriff ihn und spricht zu ihm: Kleingläubiger, warum zweifeltest du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Und als sie in das Schiff gestiegen waren, legte sich der Wind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Die aber in dem Schiffe waren, kamen und warfen sich vor ihm nieder und sprachen: Wahrhaftig, du bist Gottes Sohn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Und als sie hinübergefahren waren, kamen sie in das Land Genezareth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Und als die Männer jenes Ortes ihn erkannten, schickten sie in jene ganze Umgegend und brachten alle Leidenden zu ihm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'und sie baten ihn, daß sie nur die Quaste seines Kleides anrühren dürften: und so viele ihn anrührten, wurden völlig geheilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Dann kommen die Schriftgelehrten und Pharisäer von Jerusalem zu Jesu und sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Warum übertreten deine Jünger die Überlieferung der Ältesten? Denn sie waschen ihre Hände nicht, wenn sie Brot essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Er aber antwortete und sprach zu ihnen: Warum übertretet auch ihr das Gebot Gottes um eurer Überlieferung willen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Denn Gott hat geboten und gesagt: \"Ehre den Vater und die Mutter!\" und: \"Wer Vater oder Mutter flucht, soll des Todes sterben.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Ihr aber saget: Wer irgend zu dem Vater oder zu der Mutter spricht: Eine Gabe sei das, was irgend dir von mir zunutze kommen könnte; und er wird keineswegs seinen Vater oder seine Mutter ehren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'und ihr habt so das Gebot Gottes ungültig gemacht um eurer Überlieferung willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Heuchler! Trefflich hat Jesaias über euch geweissagt, indem er spricht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '\"Dieses Volk ehrt mich mit den Lippen, aber ihr Herz ist weit entfernt von mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Vergeblich aber verehren sie mich, indem sie als Lehren Menschengebote lehren.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Und er rief die Volksmenge herzu und sprach zu ihnen: Höret und verstehet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Nicht was in den Mund eingeht, verunreinigt den Menschen, sondern was aus dem Munde ausgeht, das verunreinigt den Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Dann traten seine Jünger herzu und sprachen zu ihm: Weißt du, daß die Pharisäer sich ärgerten, als sie das Wort hörten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Er aber antwortete und sprach: Jede Pflanze, die mein himmlischer Vater nicht gepflanzt hat, wird ausgerottet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Laßt sie; sie sind blinde Leiter der Blinden. Wenn aber ein Blinder einen Blinden leitet, so werden beide in eine Grube fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Petrus aber antwortete und sprach zu ihm: Deute uns dieses Gleichnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Er aber sprach: Seid auch ihr noch unverständig?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Begreifet ihr noch nicht, daß alles, was in den Mund eingeht, in den Bauch geht und in den Abort ausgeworfen wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Was aber aus dem Munde ausgeht, kommt aus dem Herzen hervor, und das verunreinigt den Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Denn aus dem Herzen kommen hervor böse Gedanken, Mord, Ehebruch, Hurerei, Dieberei, falsche Zeugnisse, Lästerungen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'diese Dinge sind es, die den Menschen verunreinigen, aber mit ungewaschenen Händen essen verunreinigt den Menschen nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Und Jesus ging aus von dannen und entwich in die Gegenden von Tyrus und Sidon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'und siehe, ein kananäisches Weib, das von jenen Grenzen herkam, schrie zu ihm und sprach: Erbarme dich meiner, Herr, Sohn Davids! Meine Tochter ist schlimm besessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Er aber antwortete ihr nicht ein Wort. Und seine Jünger traten herzu und baten ihn und sprachen: Entlaß sie, denn sie schreit hinter uns her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Er aber antwortete und sprach: Ich bin nicht gesandt, als nur zu den verlorenen Schafen des Hauses Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Sie aber kam und warf sich vor ihm nieder und sprach: Herr, hilf mir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Er aber antwortete und sprach: Es ist nicht schön, das Brot der Kinder zu nehmen und den Hündlein hinzuwerfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Sie aber sprach: Ja, Herr; denn es essen ja auch die Hündlein von den Brosamen, die von dem Tische ihrer Herren fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Da antwortete Jesus und sprach zu ihr: O Weib, dein Glaube ist groß; dir geschehe, wie du willst. Und ihre Tochter war geheilt von jener Stunde an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Und Jesus ging von dannen hinweg und kam an den See von Galiläa; und als er auf den Berg gestiegen war, setzte er sich daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Und große Volksmengen kamen zu ihm, welche Lahme, Blinde, Stumme, Krüppel und viele andere bei sich hatten, und sie warfen sie ihm zu Füßen; und er heilte sie,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'so daß die Volksmengen sich verwunderten, als sie sahen, daß Stumme redeten, Krüppel gesund wurden, Lahme wandelten und Blinde sahen; und sie verherrlichten den Gott Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Als Jesus aber seine Jünger herzugerufen hatte, sprach er: Ich bin innerlich bewegt über die Volksmenge; denn schon drei Tage weilen sie bei mir und haben nichts zu essen; und ich will sie nicht entlassen, ohne daß sie gegessen haben, damit sie nicht etwa auf dem Wege verschmachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Und seine Jünger sagen zu ihm: Woher nehmen wir in der Einöde so viele Brote, um eine so große Volksmenge zu sättigen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Und Jesus spricht zu ihnen: Wie viele Brote habt ihr? Sie aber sagten: Sieben, und wenige kleine Fische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Und er gebot der Volksmenge, sich auf die Erde zu lagern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Und er nahm die sieben Brote und die Fische, dankte und brach und gab sie seinen Jüngern, die Jünger aber gaben sie den Volksmengen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Und sie aßen alle und wurden gesättigt; und sie hoben auf, was an Brocken übrigblieb, sieben Körbe voll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Die aber aßen, waren viertausend Männer, ohne Weiber und Kindlein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Und als er die Volksmengen entlassen hatte, stieg er in das Schiff und kam in das Gebiet von Magada.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Und die Pharisäer und Sadducäer kamen herzu, und, um ihn zu versuchen, baten sie ihn, er möge ihnen ein Zeichen aus dem Himmel zeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Er aber antwortete und sprach zu ihnen: Wenn es Abend geworden ist, so saget ihr: Heiteres Wetter, denn der Himmel ist feuerrot;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'und frühmorgens: Heute stürmisches Wetter, denn der Himmel ist feuerrot und trübe; das Angesicht des Himmels wisset ihr zwar zu beurteilen, aber die Zeichen der Zeiten könnt ihr nicht beurteilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Ein böses und ehebrecherisches Geschlecht verlangt nach einem Zeichen, und kein Zeichen wird ihm gegeben werden, als nur das Zeichen Jonas\'. Und er verließ sie und ging hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Und als seine Jünger an das jenseitige Ufer gekommen waren, hatten sie vergessen, Brote mitzunehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Jesus aber sprach zu ihnen: Sehet zu und hütet euch vor dem Sauerteig der Pharisäer und Sadducäer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Sie aber überlegten bei sich selbst und sagten: Weil wir keine Brote mitgenommen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Als aber Jesus es erkannte, sprach er: Was überleget ihr bei euch selbst, Kleingläubige, weil ihr keine Brote mitgenommen habt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Verstehet ihr noch nicht, erinnert ihr euch auch nicht an die fünf Brote der fünftausend, und wie viele Handkörbe ihr aufhobet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Noch an die sieben Brote der viertausend, und wie viele Körbe ihr aufhobet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Wie, verstehet ihr nicht, daß ich euch nicht von Broten sagte: Hütet euch vor dem Sauerteig der Pharisäer und Sadducäer?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Da verstanden sie, daß er nicht gesagt hatte, sich zu hüten vor dem Sauerteig des Brotes, sondern vor der Lehre der Pharisäer und Sadducäer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Als aber Jesus in die Gegenden von Cäsarea Philippi gekommen war, fragte er seine Jünger und sprach: Wer sagen die Menschen, daß ich, der Sohn des Menschen, sei?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Sie aber sagten: Etliche: Johannes der Täufer; andere aber: Elias; und andere wieder: Jeremias, oder einer der Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Er spricht zu ihnen: Ihr aber, wer saget ihr, daß ich sei?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Simon Petrus aber antwortete und sprach: Du bist der Christus, der Sohn des lebendigen Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Und Jesus antwortete und sprach zu ihm: Glückselig bist du, Simon, Bar Jona; denn Fleisch und Blut haben es dir nicht geoffenbart, sondern mein Vater, der in den Himmeln ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Aber auch ich sage dir, daß du bist Petrus; und auf diesen Felsen will ich meine Versammlung bauen, und des Hades Pforten werden sie nicht überwältigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Und ich werde dir die Schlüssel des Reiches der Himmel geben; und was irgend du auf der Erde binden wirst, wird in den Himmeln gebunden sein, und was irgend du auf der Erde lösen wirst, wird in den Himmeln gelöst sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Dann gebot er seinen Jüngern, daß sie niemand sagten, daß er der Christus sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Von der Zeit an begann Jesus seinen Jüngern zu zeigen, daß er nach Jerusalem hingehen müsse und von den Ältesten und Hohenpriestern und Schriftgelehrten vieles leiden, und getötet und am dritten Tage auferweckt werden müsse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Und Petrus nahm ihn zu sich und fing an, ihn zu strafen, indem er sagte: Gott behüte dich, Herr! Dies wird dir nicht widerfahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Er aber wandte sich um und sprach zu Petrus: Geh hinter mich, Satan! Du bist mir ein Ärgernis, denn du sinnest nicht auf das, was Gottes, sondern auf das, was der Menschen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Dann sprach Jesus zu seinen Jüngern: Wenn jemand mir nachkommen will, der verleugne sich selbst und nehme sein Kreuz auf und folge mir nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Denn wer irgend sein Leben erretten will, wird es verlieren; wer aber irgend sein Leben verliert um meinetwillen, wird es finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Denn was wird es einem Menschen nützen, wenn er die ganze Welt gewönne, aber seine Seele einbüßte? Oder was wird ein Mensch als Lösegeld geben für seine Seele?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Denn der Sohn des Menschen wird kommen in der Herrlichkeit seines Vaters mit seinen Engeln, und dann wird er einem jeden vergelten nach seinem Tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Wahrlich, ich sage euch: Es sind etliche von denen, die hier stehen, welche den Tod nicht schmecken werden, bis sie den Sohn des Menschen haben kommen sehen in seinem Reiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Und nach sechs Tagen nimmt Jesus den Petrus und Jakobus und Johannes, seinen Bruder, mit und führt sie auf einen hohen Berg besonders.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Und er wurde vor ihnen umgestaltet. Und sein Angesicht leuchtete wie die Sonne, seine Kleider aber wurden weiß wie das Licht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'und siehe, Moses und Elias erschienen ihnen und unterredeten sich mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Petrus aber hob an und sprach zu Jesu: Herr, es ist gut, daß wir hier sind. Wenn du willst, laß uns hier drei Hütten machen, dir eine und Moses eine und Elias eine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Während er noch redete, siehe, da überschattete sie eine lichte Wolke, und siehe, eine Stimme kam aus der Wolke, welche sprach: Dieser ist mein geliebter Sohn, an welchem ich Wohlgefallen gefunden habe; ihn höret.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Und als die Jünger es hörten, fielen sie auf ihr Angesicht und fürchteten sich sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Und Jesus trat herzu, rührte sie an und sprach: Stehet auf und fürchtet euch nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Als sie aber ihre Augen aufhoben, sahen sie niemand als Jesum allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Und als sie von dem Berge herabstiegen, gebot ihnen Jesus und sprach: Saget niemand das Gesicht, bis der Sohn des Menschen aus den Toten auferstanden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Und seine Jünger fragten ihn und sprachen: Was sagen denn die Schriftgelehrten, daß Elias zuerst kommen müsse?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Er aber antwortete und sprach zu ihnen: Elias zwar kommt zuerst und wird alle Dinge wiederherstellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Ich sage euch aber, daß Elias schon gekommen ist, und sie haben ihn nicht erkannt, sondern an ihm getan, was irgend sie wollten. Also wird auch der Sohn des Menschen von ihnen leiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Da verstanden die Jünger, daß er von Johannes dem Täufer zu ihnen sprach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Und als sie zu der Volksmenge kamen, trat ein Mensch zu ihm und fiel vor ihm auf die Knie');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'und sprach: Herr, erbarme dich meines Sohnes, denn er ist mondsüchtig und leidet arg; denn oft fällt er ins Feuer und oft ins Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Und ich brachte ihn zu deinen Jüngern, und sie konnten ihn nicht heilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Jesus aber antwortete und sprach: O ungläubiges und verkehrtes Geschlecht! Bis wann soll ich bei euch sein? Bis wann soll ich euch ertragen? Bringet mir ihn her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Und Jesus bedrohte ihn, und der Dämon fuhr von ihm aus; und von jener Stunde an war der Knabe geheilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Da traten die Jünger zu Jesu besonders und sprachen: Warum haben wir ihn nicht austreiben können?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Er aber spricht zu ihnen: Wegen eures Unglaubens; denn wahrlich, ich sage euch, wenn ihr Glauben habt wie ein Senfkorn, so werdet ihr zu diesem Berge sagen: Werde versetzt von hier dorthin! und er wird versetzt werden; und nichts wird euch unmöglich sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Diese Art aber fährt nicht aus, als nur durch Gebet und Fasten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Als sie sich aber in Galiläa aufhielten, sprach Jesus zu ihnen: Der Sohn des Menschen wird überliefert werden in der Menschen Hände,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'und sie werden ihn töten, und am dritten Tage wird er auferweckt werden. Und sie wurden sehr betrübt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Als sie aber nach Kapernaum kamen, traten die Einnehmer der Doppeldrachmen zu Petrus und sprachen: Zahlt euer Lehrer nicht die Doppeldrachmen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Er sagt: Ja. Und als er in das Haus eintrat, kam Jesus ihm zuvor und sprach: Was dünkt dich Simon? Von wem erheben die Könige der Erde Zoll oder Steuer, von ihren Söhnen oder von den Fremden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Petrus sagt zu ihm: Von den Fremden. Jesus sprach zu ihm: Demnach sind die Söhne frei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Auf daß wir ihnen aber kein Ärgernis geben, geh an den See, wirf eine Angel aus und nimm den ersten Fisch, der heraufkommt, tue seinen Mund auf, und du wirst einen Stater finden; den nimm und gib ihnen für mich und dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'In jener Stunde traten die Jünger zu Jesu und sprachen: Wer ist denn der Größte im Reiche der Himmel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Und als Jesus ein Kindlein herzugerufen hatte, stellte er es in ihre Mitte und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'Wahrlich, ich sage euch, wenn ihr nicht umkehret und werdet wie die Kindlein, so werdet ihr nicht in das Reich der Himmel eingehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Darum, wer irgend sich selbst erniedrigen wird wie dieses Kindlein, dieser ist der Größte im Reiche der Himmel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'und wer irgend ein solches Kindlein aufnehmen wird in meinem Namen, nimmt mich auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Wer aber irgend eines dieser Kleinen, die an mich glauben, ärgern wird, dem wäre nütze, daß ein Mühlstein an seinen Hals gehängt, und er in die Tiefe des Meeres versenkt würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Wehe der Welt der Ärgernisse wegen! Denn es ist notwendig, daß Ärgernisse kommen; doch wehe dem Menschen, durch welchen das Ärgernis kommt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Wenn aber deine Hand oder dein Fuß dich ärgert, so haue ihn ab und wirf ihn von dir. Es ist dir besser, lahm oder als Krüppel in das Leben einzugehen, als mit zwei Händen oder mit zwei Füßen in das ewige Feuer geworfen zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Und wenn dein Auge dich ärgert, so reiß es aus und wirf es von dir. Es ist dir besser, einäugig in das Leben einzugehen, als mit zwei Augen in die Hölle des Feuers geworfen zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Sehet zu, daß ihr nicht eines dieser Kleinen verachtet; denn ich sage euch, daß ihre Engel in den Himmeln allezeit das Angesicht meines Vaters schauen, der in den Himmeln ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Denn der Sohn des Menschen ist gekommen, das Verlorene zu erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Was dünkt euch? Wenn ein Mensch hundert Schafe hätte, und eines von ihnen sich verirrte, läßt er nicht die neunundneunzig auf den Bergen und geht hin und sucht das irrende?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Und wenn es geschieht, daß er es findet, wahrlich, ich sage euch, er freut sich mehr über dieses, als über die neunundneunzig, die nicht verirrt sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Also ist es nicht der Wille eures Vaters, der in den Himmeln ist, daß eines dieser Kleinen verloren gehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Wenn aber dein Bruder wider dich sündigt, so gehe hin, überführe ihn zwischen dir und ihm allein. Wenn er auf dich hört, so hast du deinen Bruder gewonnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Wenn er aber nicht hört, so nimm noch einen oder zwei mit dir, damit aus zweier oder dreier Zeugen Mund jede Sache bestätigt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Wenn er aber nicht auf sie hören wird, so sage es der Versammlung; wenn er aber auch auf die Versammlung nicht hören wird, so sei er dir wie der Heide und der Zöllner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Wahrlich, ich sage euch: Was irgend ihr auf der Erde binden werdet, wird im Himmel gebunden sein, und was irgend ihr auf der Erde lösen werdet, wird im Himmel gelöst sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Wiederum sage ich euch: Wenn zwei von euch auf der Erde übereinkommen werden über irgend eine Sache, um welche sie auch bitten mögen, so wird sie ihnen werden von meinem Vater, der in den Himmeln ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Denn wo zwei oder drei versammelt sind in meinem Namen, da bin ich in ihrer Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Dann trat Petrus zu ihm und sprach: Herr, wie oft soll ich meinem Bruder, der wider mich sündigt, vergeben? Bis siebenmal?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jesus spricht zu ihm: Nicht sage ich dir, bis siebenmal, sondern bis siebzig mal sieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Deswegen ist das Reich der Himmel einem Könige gleich geworden, der mit seinen Knechten abrechnen wollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Als er aber anfing abzurechnen, wurde einer zu ihm gebracht, der zehntausend Talente schuldete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Da derselbe aber nicht hatte zu bezahlen, befahl sein Herr, ihn und sein Weib und die Kinder und alles, was er hatte, zu verkaufen und zu bezahlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Der Knecht nun fiel nieder, huldigte ihm und sprach: Herr, habe Geduld mit mir, und ich will dir alles bezahlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Der Herr jenes Knechtes aber, innerlich bewegt, gab ihn los und erließ ihm das Darlehn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Jener Knecht aber ging hinaus und fand einen seiner Mitknechte, der ihm hundert Denare schuldig war. Und er ergriff und würgte ihn und sprach: Bezahle, wenn du etwas schuldig bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Sein Mitknecht nun fiel nieder und bat ihn und sprach: Habe Geduld mit mir, und ich will dir bezahlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Er aber wollte nicht, sondern ging hin und warf ihn ins Gefängnis, bis er die Schuld bezahlt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Als aber seine Mitknechte sahen, was geschehen war, wurden sie sehr betrübt und gingen und berichteten ihrem Herrn alles, was geschehen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Dann rief ihn sein Herr herzu und spricht zu ihm: Böser Knecht! Jene ganze Schuld habe ich dir erlassen, dieweil du mich batest;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'solltest nicht auch du dich deines Mitknechtes erbarmt haben, wie auch ich mich deiner erbarmt habe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Und sein Herr wurde zornig und überlieferte ihn den Peinigern, bis er alles bezahlt habe, was er ihm schuldig war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Also wird auch mein himmlischer Vater euch tun, wenn ihr nicht ein jeder seinem Bruder von Herzen vergebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Und es geschah, als Jesus diese Reden vollendet hatte, begab er sich von Galiläa hinweg und kam in das Gebiet von Judäa, jenseit des Jordan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Und es folgten ihm große Volksmengen, und er heilte sie daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Und die Pharisäer kamen zu ihm, versuchten ihn und sprachen: Ist es einem Manne erlaubt, aus jeder Ursache sein Weib zu entlassen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Er aber antwortete und sprach zu ihnen: Habt ihr nicht gelesen, daß der, welcher sie schuf, von Anfang sie Mann und Weib schuf und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, '\"Um deswillen wird ein Mensch Vater und Mutter verlassen und seinem Weibe anhangen, und es werden die zwei ein Fleisch sein\";');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'so daß sie nicht mehr zwei sind, sondern ein Fleisch? Was nun Gott zusammengefügt hat, soll der Mensch nicht scheiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Sie sagen zu ihm: Warum hat denn Moses geboten, einen Scheidebrief zu geben und sie zu entlassen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Er spricht zu ihnen: Moses hat wegen eurer Herzenshärtigkeit euch gestattet, eure Weiber zu entlassen; von Anfang aber ist es nicht also gewesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Ich sage euch aber, daß, wer irgend sein Weib entlassen wird, nicht wegen Hurerei, und eine andere heiraten wird, Ehebruch begeht; und wer eine Entlassene heiratet, begeht Ehebruch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Seine Jünger sagen zu ihm: Wenn die Sache des Mannes mit dem Weibe also steht, so ist es nicht ratsam zu heiraten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Er aber sprach zu ihnen: Nicht alle fassen dieses Wort, sondern denen es gegeben ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'denn es gibt Verschnittene, die von Mutterleibe also geboren sind; und es gibt Verschnittene, die von den Menschen verschnitten worden sind; und es gibt Verschnittene, die sich selbst verschnitten haben um des Reiches der Himmel willen. Wer es zu fassen vermag, der fasse es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Dann wurden Kindlein zu ihm gebracht, auf daß er ihnen die Hände auflege und bete; die Jünger aber verwiesen es ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Jesus aber sprach: Lasset die Kindlein und wehret ihnen nicht, zu mir zu kommen, denn solcher ist das Reich der Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Und er legte ihnen die Hände auf und ging von dannen hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Und siehe, einer trat herzu und sprach zu ihm: Lehrer, welches Gute soll ich tun, auf daß ich ewiges Leben habe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Er aber sprach zu ihm: Was fragst du mich über das Gute? Einer ist gut. Wenn du aber ins Leben eingehen willst, so halte die Gebote.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Er spricht zu ihm: Welche? Jesus aber sprach: Diese: Du sollst nicht töten; du sollst nicht ehebrechen; du sollst nicht stehlen; du sollst nicht falsches Zeugnis geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'ehre den Vater und die Mutter, und: du sollst deinen Nächsten lieben wie dich selbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Der Jüngling spricht zu ihm: Alles dieses habe ich beobachtet; was fehlt mir noch?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jesus sprach zu ihm: Wenn du vollkommen sein willst, so gehe hin, verkaufe deine Habe und gib den Armen, und du wirst einen Schatz im Himmel haben; und komm, folge mir nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Als aber der Jüngling das Wort hörte, ging er betrübt hinweg, denn er hatte viele Güter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Jesus aber sprach zu seinen Jüngern: Wahrlich ich sage euch: Schwerlich wird ein Reicher in das Reich der Himmel eingehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Wiederum aber sage ich euch: Es ist leichter, daß ein Kamel durch ein Nadelöhr eingehe, als daß ein Reicher in das Reich Gottes eingehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Als aber die Jünger es hörten, waren sie sehr erstaunt und sagten: Wer kann dann errettet werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Jesus aber sah sie an und sprach zu ihnen: Bei Menschen ist dies unmöglich, bei Gott aber sind alle Dinge möglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Da antwortete Petrus und sprach zu ihm: Siehe, wir haben alles verlassen und sind dir nachgefolgt; was wird uns nun werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Jesus aber sprach zu ihnen: Wahrlich, ich sage euch: Ihr, die ihr mir nachgefolgt seid, auch ihr werdet in der Wiedergeburt, wenn der Sohn des Menschen sitzen wird auf seinem Throne der Herrlichkeit, auf zwölf Thronen sitzen und richten die zwölf Stämme Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Und ein jeder, der irgend verlassen hat Häuser, oder Brüder, oder Schwestern, oder Vater, oder Mutter, oder Weib, oder Kinder, oder Äcker um meines Namens willen, wird hundertfältig empfangen und ewiges Leben erben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Aber viele Erste werden Letzte, und Letzte Erste sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Denn das Reich der Himmel ist gleich einem Hausherrn, der frühmorgens ausging, um Arbeiter in seinen Weinberg zu dingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Nachdem er aber mit den Arbeitern um einen Denar den Tag übereingekommen war, sandte er sie in seinen Weinberg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Und als er um die dritte Stunde ausging, sah er andere auf dem Markte müßig stehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'und zu diesen sprach er: Gehet auch ihr hin in den Weinberg, und was irgend recht ist, werde ich euch geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Sie aber gingen hin. Wiederum aber ging er aus um die sechste und neunte Stunde und tat desgleichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Als er aber um die elfte Stunde ausging, fand er andere stehen und spricht zu ihnen: Was stehet ihr hier den ganzen Tag müßig?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Sie sagen zu ihm: Weil niemand uns gedungen hat. Er spricht zu ihnen: Gehet auch ihr hin in den Weinberg, und was irgend recht ist, werdet ihr empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Als es aber Abend geworden war, spricht der Herr des Weinbergs zu seinem Verwalter: Rufe die Arbeiter und zahle ihnen den Lohn, anfangend von den letzten bis zu den ersten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Und als die um die elfte Stunde Gedungenen kamen, empfingen sie je einen Denar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Als aber die ersten kamen, meinten sie, daß sie mehr empfangen würden; und auch sie empfingen je einen Denar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Als sie aber den empfingen, murrten sie wider den Hausherrn und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Diese letzten haben eine Stunde gearbeitet, und du hast sie uns gleich gemacht, die wir die Last des Tages und die Hitze getragen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Er aber antwortete und sprach zu einem von ihnen: Freund, ich tue dir nicht unrecht. Bist du nicht um einen Denar mit mir übereingekommen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Nimm das Deine und gehe hin. Ich will aber diesem letzten geben wie auch dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Ist es mir nicht erlaubt, mit dem Meinigen zu tun, was ich will? Blickt dein Auge böse, weil ich gütig bin?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Also werden die Letzten Erste, und die Ersten Letzte sein; denn viele sind Berufene, wenige aber Auserwählte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Und als Jesus nach Jerusalem hinaufging, nahm er die zwölf Jünger auf dem Wege besonders zu sich und sprach zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Siehe, wir gehen hinauf nach Jerusalem, und der Sohn des Menschen wird den Hohenpriestern und Schriftgelehrten überliefert werden, und sie werden ihn zum Tode verurteilen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'und sie werden ihn den Nationen überliefern, um ihn zu verspotten und zu geißeln und zu kreuzigen; und am dritten Tage wird er auferstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Dann trat die Mutter der Söhne des Zebedäus mit ihren Söhnen zu ihm und warf sich nieder und erbat etwas von ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Er aber sprach zu ihr: Was willst du? Sie sagt zu ihm: Sprich, daß diese meine zwei Söhne einer zu deiner Rechten und einer zu deiner Linken sitzen mögen in deinem Reiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Jesus aber antwortete und sprach: Ihr wisset nicht, um was ihr bittet. Könnt ihr den Kelch trinken, den ich trinken werde? Sie sagen zu ihm: Wir können es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Und er spricht zu ihnen: Meinen Kelch werdet ihr zwar trinken, aber das Sitzen zu meiner Rechten und zu meiner Linken steht nicht bei mir zu vergeben, sondern ist für die, welchen es von meinem Vater bereitet ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Und als die Zehn es hörten, wurden sie unwillig über die zwei Brüder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Jesus aber rief sie herzu und sprach: Ihr wisset, daß die Regenten der Nationen über dieselben herrschen und die Großen Gewalt über sie üben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Unter euch soll es nicht also sein; sondern wer irgend unter euch groß werden will, soll euer Diener sein,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'und wer irgend unter euch der Erste sein will, soll euer Knecht sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'gleichwie der Sohn des Menschen nicht gekommen ist, um bedient zu werden, sondern um zu dienen und sein Leben zu geben als Lösegeld für viele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Und als sie von Jericho auszogen, folgte ihm eine große Volksmenge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Und siehe, zwei Blinde, die am Wege saßen, als sie hörten, daß Jesus vorübergehe, schrieen und sprachen: Erbarme dich unser, Herr, Sohn Davids!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Die Volksmenge aber bedrohte sie, daß sie schweigen sollten. Sie aber schrieen noch mehr und sprachen: Erbarme dich unser, Herr, Sohn Davids!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Und Jesus blieb stehen und rief sie und sprach: Was wollt ihr, daß ich euch tun soll?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Sie sagen zu ihm: Herr, daß unsere Augen aufgetan werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Jesus aber, innerlich bewegt, rührte ihre Augen an; und alsbald wurden ihre Augen sehend, und sie folgten ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Und als sie Jerusalem nahten und nach Bethphage kamen, an den Ölberg,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'da sandte Jesus zwei Jünger und sprach zu ihnen: Gehet hin in das Dorf, das euch gegenüberliegt; und alsbald werdet ihr eine Eselin angebunden finden, und ein Füllen bei ihr; bindet sie los und führet sie zu mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Und wenn jemand etwas zu euch sagt, so sollt ihr sprechen: Der Herr bedarf ihrer, und alsbald wird er sie senden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Dies alles aber ist geschehen, auf daß erfüllt würde, was durch den Propheten geredet ist, welcher spricht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '\"Saget der Tochter Zion: Siehe, dein König kommt zu dir, sanftmütig und reitend auf einer Eselin und auf einem Füllen, des Lasttiers Jungen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Als aber die Jünger hingegangen waren und getan hatten, wie Jesus ihnen aufgetragen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'brachten sie die Eselin und das Füllen und legten ihre Kleider auf sie, und er setzte sich auf dieselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Und eine sehr große Volksmenge breitete ihre Kleider aus auf den Weg; andere aber hieben Zweige von den Bäumen und streuten sie auf den Weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Die Volksmengen aber, welche vor ihm hergingen und nachfolgten, riefen und sprachen: Hosanna dem Sohne Davids! Gepriesen sei, der da kommt im Namen des Herrn! Hosanna in der Höhe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Und als er in Jerusalem einzog, kam die ganze Stadt in Bewegung und sprach: Wer ist dieser?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Die Volksmengen aber sagten: Dieser ist Jesus, der Prophet, der von Nazareth in Galiläa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Und Jesus trat in den Tempel Gottes ein und trieb alle hinaus, die im Tempel verkauften, und kauften, und die Tische der Wechsler und die Sitze der Taubenverkäufer stieß er um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'Und er spricht zu ihnen: Es steht geschrieben: \"Mein Haus wird ein Bethaus genannt werden\"; \"ihr aber habt es zu einer Räuberhöhle gemacht\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Und es traten Blinde und Lahme in dem Tempel zu ihm, und er heilte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Als aber die Hohenpriester und die Schriftgelehrten die Wunder sahen, welche er tat, und sie Kinder, die im Tempel schrieen und sagten: Hosanna dem Sohne Davids! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'wurden sie unwillig und sprachen zu ihm: Hörst du, was diese sagen? Jesus aber spricht zu ihnen: Ja, habt ihr nie gelesen: \"Aus dem Munde der Unmündigen und Säuglinge hast du dir Lob bereitet\"?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Und er verließ sie und ging zur Stadt hinaus nach Bethanien, und übernachtete daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Des Morgens früh aber, als er in die Stadt zurückkehrte, hungerte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Und als er einen Feigenbaum an dem Wege sah, ging er auf ihn zu und fand nichts an ihm als nur Blätter. Und er spricht zu ihm: Nimmermehr komme Frucht von dir in Ewigkeit! Und alsbald verdorrte der Feigenbaum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Und als die Jünger es sahen, verwunderten sie sich und sprachen: Wie alsbald ist der Feigenbaum verdorrt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Jesus aber antwortete und sprach zu ihnen: Wahrlich, ich sage euch: Wenn ihr Glauben habt und nicht zweifelt, so werdet ihr nicht allein das mit dem Feigenbaum Geschehene tun, sondern wenn ihr auch zu diesem Berge sagen werdet: Werde aufgehoben und ins Meer geworfen! so wird es geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Und alles, was irgend ihr im Gebet glaubend begehret, werdet ihr empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Und als er in den Tempel kam, traten, als er lehrte, die Hohenpriester und die Ältesten des Volkes zu ihm und sprachen: In welchem Recht tust du diese Dinge? Und wer hat dir dieses Recht gegeben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jesus aber antwortete und sprach zu ihnen: Auch ich will euch ein Wort fragen, und wenn ihr es mir saget, so werde auch ich euch sagen, in welchem Recht ich diese Dinge tue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Die Taufe Johannes\', woher war sie? Vom Himmel oder von Menschen? Sie aber überlegten bei sich selbst und sprachen: Wenn wir sagen: Vom Himmel, so wird er zu uns sagen: Warum habt ihr ihm denn nicht geglaubt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Wenn wir aber sagen: Von Menschen, wir fürchten die Volksmenge, denn alle halten Johannes für einen Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Und sie antworteten Jesu und sprachen: Wir wissen es nicht. Da sagte auch er zu ihnen: So sage auch ich euch nicht, in welchem Recht ich diese Dinge tue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Was dünkt euch aber? Ein Mensch hatte zwei Kinder; und er trat hin zu dem ersten und sprach: Kind, geh heute hin, arbeite in meinem Weinberge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Er aber antwortete und sprach: Ich will nicht; danach aber gereute es ihn, und er ging hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Und er trat hin zu dem zweiten und sprach desgleichen. Der aber antwortete und sprach: Ich gehe, Herr, und ging nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Welcher von den beiden hat den Willen des Vaters getan? Sie sagen zu ihm: Der erste. Jesus spricht zu ihnen: Wahrlich, ich sage euch, daß die Zöllner und die Huren euch vorangehen in das Reich Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Denn Johannes kam zu euch im Wege der Gerechtigkeit, und ihr glaubtet ihm nicht; die Zöllner aber und die Huren glaubten ihm; euch aber, als ihr es sahet, gereute es danach nicht, um ihm zu glauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Höret ein anderes Gleichnis: Es war ein Hausherr, der einen Weinberg pflanzte und einen Zaun um denselben setzte und einen Kelter in ihm grub und einen Turm baute; und er verdingte ihn an Weingärtner und reiste außer Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Als aber die Zeit der Früchte nahte, sandte er seine Knechte zu den Weingärtnern, um seine Früchte zu empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Und die Weingärtner nahmen seine Knechte, einen schlugen sie, einen anderen töteten sie, einen anderen steinigten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Wiederum sandte er andere Knechte, mehr als die ersten; und sie taten ihnen ebenso.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Zuletzt aber sandte er seinen Sohn zu ihnen, indem er sagte: Sie werden sich vor meinem Sohne scheuen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Als aber die Weingärtner den Sohn sahen, sprachen sie untereinander: Dieser ist der Erbe; kommt, laßt uns ihn töten und sein Erbe in Besitz nehmen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Und sie nahmen ihn, warfen ihn zum Weinberg hinaus und töteten ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Wenn nun der Herr des Weinbergs kommt, was wird er jenen Weingärtnern tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Sie sagen zu ihm: Er wird jene Übeltäter übel umbringen, und den Weinberg wird er an andere Weingärtner verdingen, die ihm die Früchte abgeben werden zu ihrer Zeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jesus spricht zu ihnen: Habt ihr nie in den Schriften gelesen: \"Der Stein, den die Bauleute verworfen haben, dieser ist zum Eckstein geworden; von dem Herrn her ist er dies geworden, und er ist wunderbar in unseren Augen\"?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Deswegen sage ich euch: Das Reich Gottes wird von euch weggenommen und einer Nation gegeben werden, welche dessen Früchte bringen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Und wer auf diesen Stein fällt, wird zerschmettert werden; aber auf welchen irgend er fallen wird, den wird er zermalmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Und als die Hohenpriester und die Pharisäer seine Gleichnisse gehört hatten, erkannten sie, daß er von ihnen rede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Und als sie ihn zu greifen suchten, fürchteten sie die Volksmengen, denn sie hielten ihn für einen Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Und Jesus antwortete und redete wiederum in Gleichnissen zu ihnen und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Das Reich der Himmel ist einem Könige gleich geworden, der seinem Sohne Hochzeit machte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'Und er sandte seine Knechte aus, um die Geladenen zur Hochzeit zu rufen; und sie wollten nicht kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Wiederum sandte er andere Knechte aus und sprach: Saget den Geladenen: Siehe, mein Mahl habe ich bereitet, meine Ochsen und mein Mastvieh sind geschlachtet, und alles ist bereit; kommt zur Hochzeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Sie aber achteten es nicht und gingen hin, der eine auf seinen Acker, der andere an seinen Handel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'Die übrigen aber ergriffen seine Knechte, mißhandelten und töteten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Der König aber ward zornig und sandte seine Heere aus, brachte jene Mörder um und steckte ihre Stadt in Brand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Dann sagt er zu seinen Knechten: die Hochzeit ist zwar bereit, aber die Geladenen waren nicht würdig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'so gehet nun hin auf die Kreuzwege der Landstraßen, und so viele immer ihr finden werdet, ladet zur Hochzeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Und jene Knechte gingen aus auf die Landstraßen und brachten alle zusammen, so viele sie fanden, sowohl Böse als Gute. Und die Hochzeit wurde voll von Gästen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Als aber der König hereinkam, die Gäste zu besehen, sah er daselbst einen Menschen, der nicht mit einem Hochzeitskleide bekleidet war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'Und er spricht zu ihm: Freund, wie bist du hier hereingekommen, da du kein Hochzeitskleid anhast? Er aber verstummte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Da sprach der König zu den Dienern: Bindet ihm Füße und Hände, nehmet ihn und werfet ihn hinaus in die äußere Finsternis: da wird sein das Weinen und das Zähneknirschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Denn viele sind Berufene, wenige aber Auserwählte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Dann gingen die Pharisäer hin und hielten Rat, wie sie ihn in der Rede in eine Falle lockten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Und sie senden ihre Jünger mit den Herodianern zu ihm und sagen: Lehrer, wir wissen, daß du wahrhaftig bist und den Weg Gottes in Wahrheit lehrst und dich um niemand kümmerst, denn du siehst nicht auf die Person der Menschen; sage uns nun, was denkst du:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Ist es erlaubt, dem Kaiser Steuer zu geben, oder nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Da aber Jesus ihre Bosheit erkannte, sprach er: Was versuchet ihr mich, Heuchler?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Zeiget mir die Steuermünze. Sie aber überreichten ihm einen Denar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Und er spricht zu ihnen: Wessen ist dieses Bild und die Überschrift?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Sie sagen zu ihm: Des Kaisers. Da spricht er zu ihnen: Gebet denn dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Und als sie das hörten, verwunderten sie sich und ließen ihn und gingen hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'An jenem Tage kamen Sadducäer zu ihm, die da sagen, es gebe keine Auferstehung;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'und sie fragten ihn und sprachen: Lehrer, Moses hat gesagt: Wenn jemand stirbt und keine Kinder hat, so soll sein Bruder sein Weib heiraten und soll seinem Bruder Samen erwecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Es waren aber bei uns sieben Brüder. Und der erste verheiratete sich und starb; und weil er keinen Samen hatte, hinterließ er sein Weib seinem Bruder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Gleicherweise auch der zweite und der dritte, bis auf den siebten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Zuletzt aber von allen starb auch das Weib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'In der Auferstehung nun, wessen Weib von den sieben wird sie sein? Denn alle hatten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jesus aber antwortete und sprach zu ihnen: Ihr irret, indem ihr die Schriften nicht kennet, noch die Kraft Gottes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'denn in der Auferstehung heiraten sie nicht, noch werden sie verheiratet, sondern sie sind wie Engel Gottes im Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Was aber die Auferstehung der Toten betrifft, habt ihr nicht gelesen, was zu euch geredet ist von Gott, der da spricht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '\"Ich bin der Gott Abrahams und der Gott Isaaks und der Gott Jakobs\"? Gott ist nicht ein Gott der Toten, sondern der Lebendigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Und als die Volksmengen es hörten, erstaunten sie über seine Lehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Als aber die Pharisäer hörten, daß er die Sadducäer zum Schweigen gebracht hatte, versammelten sie sich miteinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'Und es fragte einer aus ihnen, ein Gesetzgelehrter, und versuchte ihn und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Lehrer, welches ist das große Gebot in dem Gesetz?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Er aber sprach zu ihm: \"Du sollst den Herrn, deinen Gott, lieben mit deinem ganzen Herzen und mit deiner ganzen Seele und mit deinem ganzen Verstande\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Dieses ist das große und erste Gebot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Das zweite aber, ihm gleiche, ist: \"Du sollst deinen Nächsten lieben wie dich selbst\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'An diesen zwei Geboten hängt das ganze Gesetz und die Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Als aber die Pharisäer versammelt waren, fragte sie Jesus und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'Was dünkt euch von dem Christus? Wessen Sohn ist er? Sie sagen zu ihm: Davids.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Er spricht zu ihnen: Wie nennt David ihn denn im Geiste Herr, indem er sagt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '\"Der Herr sprach zu meinem Herrn: Setze dich zu meiner Rechten, bis ich deine Feinde lege unter deine Füße\"?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Wenn nun David ihn Herr nennt, wie ist er sein Sohn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Und niemand konnte ihm ein Wort antworten, noch wagte jemand von dem Tage an, ihn ferner zu befragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Dann redete Jesus zu den Volksmengen und zu seinen Jüngern und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'Die Schriftgelehrten und die Pharisäer haben sich auf Moses\' Stuhl gesetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Alles nun, was irgend sie euch sagen, tut und haltet; aber tut nicht nach ihren Werken, denn sie sagen es und tun\'s nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Sie binden aber schwere und schwer zu tragende Lasten und legen sie auf die Schultern der Menschen, aber sie wollen sie nicht mit ihrem Finger bewegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Alle ihre Werke aber tun sie, um sich vor den Menschen sehen zu lassen; denn sie machen ihre Denkzettel breit und die Quasten groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'Sie lieben aber den ersten Platz bei den Gastmählern und die ersten Sitze in den Synagogen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'und die Begrüßungen auf den Märkten und von den Menschen Rabbi, Rabbi! genannt zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Ihr aber, laßt ihr euch nicht Rabbi nennen; denn einer ist euer Lehrer, ihr alle aber seid Brüder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Ihr sollt auch nicht jemand auf der Erde euren Vater nennen; denn einer ist euer Vater, der in den Himmeln ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Laßt euch auch nicht Meister nennen; denn einer ist euer Meister, der Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Der Größte aber unter euch soll euer Diener sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Wer irgend aber sich selbst erhöhen wird, wird erniedrigt werden; und wer irgend sich selbst erniedrigen wird, wird erhöht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Wehe aber euch, Schriftgelehrten und Pharisäer, Heuchler! Denn ihr verschließet das Reich der Himmel vor den Menschen; denn ihr gehet nicht hinein, noch laßt ihr die Hineingehenden eingehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, '(Dieser Vers gehört nicht zum ursprünglichen Text des Matthäusevangeliums.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Wehe euch, Schriftgelehrte und Pharisäer, Heuchler! Denn ihr durchziehet das Meer und das Trockene, um einen Proselyten zu machen; und wenn er es geworden ist, so machet ihr ihn zu einem Sohne der Hölle, zwiefältig mehr als ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Wehe euch, blinde Leiter! Die ihr saget: Wer irgend bei dem Tempel schwören wird, das ist nichts; wer aber irgend bei dem Golde des Tempels schwören wird, ist schuldig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Narren und Blinde! Denn was ist größer, das Gold, oder der Tempel, der das Gold heiligt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Und: Wer irgend bei dem Altar schwören wird, das ist nichts; wer aber irgend bei der Gabe schwören wird, die auf ihm ist, ist schuldig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Narren und Blinde! Denn was ist größer, die Gabe oder der Altar, der die Gabe heiligt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Wer nun bei dem Altar schwört, schwört bei demselben und bei allem, was auf ihm ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'Und wer bei dem Tempel schwört, schwört bei demselben und bei dem, der ihn bewohnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'Und wer bei dem Himmel schwört, schwört bei dem Throne Gottes und bei dem, der darauf sitzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'wehe euch, Schriftgelehrte und Pharisäer, Heuchler! Denn ihr verzehntet die Krausemünze und den Anis und den Kümmel, und habt die wichtigeren Dinge des Gesetzes beiseite gelassen: das Gericht und die Barmherzigkeit und den Glauben; diese hättet ihr tun und jene nicht lassen sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Blinde Leiter, die ihr die Mücke seihet, das Kamel aber verschlucket!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Wehe euch, Schriftgelehrte und Pharisäer, Heuchler! Denn ihr reiniget das Äußere des Bechers und der Schüssel, inwendig aber sind sie voll von Raub und Unenthaltsamkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Blinder Pharisäer! Reinige zuerst das Inwendige des Bechers und der Schüssel, auf daß auch das Auswendige derselben rein werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Wehe euch, Schriftgelehrte und Pharisäer, Heuchler! Denn ihr gleichet übertünchten Gräbern, die von außen zwar schön scheinen, inwendig aber voll von Totengebeinen und aller Unreinigkeit sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Also scheinet auch ihr von außen zwar gerecht vor den Menschen, von innen aber seid ihr voll Heuchelei und Gestezlosigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Wehe euch, Schriftgelehrte und Pharisäer, Heuchler! Denn ihr bauet die Gräber der Propheten und schmücket die Grabmäler der Gerechten und saget:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'Wären wir in den Tagen unserer Väter gewesen, so würden wir nicht ihre Teilhaber an dem Blute der Propheten gewesen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Also gebet ihr euch selbst Zeugnis, daß ihr Söhne derer seid, welche die Propheten ermordet haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'und ihr, machet voll das Maß eurer Väter!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Schlangen! Otternbrut! Wie solltet ihr dem Gericht der Hölle entfliehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Deswegen siehe, ich sende zu euch Propheten und Weise und Schriftgelehrte; und etliche von ihnen werdet ihr töten und kreuzigen, und etliche von ihnen werdet ihr in euren Synagogen geißeln und werdet sie verfolgen von Stadt zu Stadt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'damit über euch komme alles gerechte Blut, das auf der Erde vergossen wurde, von dem Blute Abels, des Gerechten, bis zu dem Blute Zacharias\', des Sohnes Barachias\', den ihr zwischen dem Tempel und dem Altar ermordet habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Wahrlich, ich sage euch, dies alles wird über dieses Geschlecht kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jerusalem, Jerusalem, die da tötet die Propheten und steinigt, die zu ihr gesandt sind! Wie oft habe ich deine Kinder versammeln wollen, wie eine Henne ihre Küchlein versammelt unter ihre Flügel, und ihr habt nicht gewollt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Siehe, euer Haus wird euch öde gelassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'denn ich sage euch: Ihr werdet mich von jetzt an nicht sehen, bis ihr sprechet: \"Gepriesen sei, der da kommt im Namen des Herrn!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Und Jesus trat hinaus und ging von dem Tempel hinweg; und seine Jünger traten herzu, um ihm die Gebäude des Tempels zu zeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Er aber antwortete und sprach zu ihnen: Sehet ihr nicht alles dieses? wahrlich, ich sage euch: Hier wird nicht ein Stein auf dem anderen gelassen werden, der nicht abgebrochen werden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Als er aber auf dem Ölberge saß, traten seine Jünger zu ihm besonders und sprachen: Sage uns, wann wird dieses sein, und was ist das Zeichen deiner Ankunft und der Vollendung des Zeitalters?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Und Jesus antwortete und sprach zu ihnen: Sehet zu, daß euch niemand verführe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Denn viele werden unter meinem Namen kommen und sagen: Ich bin der Christus! und sie werden viele verführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Ihr werdet aber von Kriegen und Kriegsgerüchten hören. Sehet zu, erschrecket nicht; denn dies alles muß geschehen, aber es ist noch nicht das Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Denn es wird sich Nation wider Nation erheben und Königreich wider Königreich, und es werden Hungersnöte und Seuchen sein und Erdbeben an verschiedenen Orten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Alles dieses aber ist der Anfang der Wehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Dann werden sie euch in Drangsal überliefern und euch töten; und ihr werdet von allen Nationen gehaßt werden um meines Namens willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Und dann werden viele geärgert werden und werden einander überliefern und einander hassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'und viele falsche Propheten werden aufstehen und werden viele verführen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'und wegen des Überhandnehmens der Gesetzlosigkeit wird die Liebe der Vielen erkalten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'wer aber ausharrt bis ans Ende, dieser wird errettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Und dieses Evangelium des Reiches wird gepredigt werden auf dem ganzen Erdkreis, allen Nationen zu einem Zeugnis, und dann wird das Ende kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Wenn ihr nun den Greuel der Verwüstung, von welchem durch Daniel, den Propheten, geredet ist, stehen sehet an heiligem Orte (wer es liest, der beachte es),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'daß alsdann die in Judäa sind, auf die Berge fliehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'wer auf dem Dache ist, nicht hinabsteige, um die Sachen aus seinem Hause zu holen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'und wer auf dem Felde ist, nicht zurückkehre, um sein Kleid zu holen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Wehe aber den Schwangeren und den Säugenden in jenen Tagen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Betet aber, daß eure Flucht nicht im Winter geschehe, noch am Sabbath;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'denn alsdann wird große Drangsal sein, dergleichen von Anfang der Welt bis jetzthin nicht gewesen ist, noch je sein wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'und wenn jene Tage nicht verkürzt würden, so würde kein Fleisch gerettet werden; aber um der Auserwählten willen werden jene Tage verkürzt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Alsdann, wenn jemand zu euch sagt: Siehe, hier ist der Christus, oder: Hier! so glaubet nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Denn es werden falsche Christi und falsche Propheten aufstehen und werden große Zeichen und Wunder tun, um so, wenn möglich, auch die Auserwählten zu verführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Siehe, ich habe es euch vorhergesagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Wenn sie nun zu euch sagen: Siehe, er ist in der Wüste! so gehet nicht hinaus; Siehe, in den Gemächern! so glaubet nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Denn gleichwie der Blitz ausfährt von Osten und scheint bis gen Westen, also wird die Ankunft des Sohnes des Menschen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Denn wo irgend das Aas ist, da werden die Adler versammelt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Alsbald aber nach der Drangsal jener Tage wird die Sonne verfinstert werden und der Mond seinen Schein nicht geben, und die Sterne werden vom Himmel fallen, und die Kräfte der Himmel werden erschüttert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Und dann wird das Zeichen des Sohnes des Menschen in dem Himmel erscheinen; und dann werden wehklagen alle Stämme des Landes, und sie werden den Sohn des Menschen kommen sehen auf den Wolken des Himmels mit Macht und großer Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Und er wird seine Engel aussenden mit starkem Posaunenschall, und sie werden seine Auserwählten versammeln von den vier Winden her, von dem einen Ende der Himmel bis zu ihrem anderen Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Von dem Feigenbaum aber lernet das Gleichnis: Wenn sein Zweig schon weich geworden ist und die Blätter hervortreibt, so erkennet ihr, daß der Sommer nahe ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Also auch ihr, wenn ihr alles dieses sehet, so erkennet, daß es nahe an der Tür ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Wahrlich, ich sage euch: Dieses Geschlecht wird nicht vergehen, bis alles dieses geschehen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Der Himmel und die Erde werden vergehen, meine Worte aber sollen nicht vergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Von jenem Tage aber und jener Stunde weiß niemand, auch nicht die Engel der Himmel, sondern mein Vater allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Aber gleichwie die Tage Noahs waren, also wird auch die Ankunft des Sohnes des Menschen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Denn gleichwie sie in den Tagen vor der Flut waren: sie aßen und tranken, sie heirateten und verheirateten, bis zu dem Tage, da Noah in die Arche ging,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'und sie es nicht erkannten, bis die Flut kam und alle wegraffte, also wird auch die Ankunft des Sohnes des Menschen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Alsdann werden zwei auf dem Felde sein, einer wird genommen und einer gelassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'zwei Weiber werden an dem Mühlstein mahlen, eine wird genommen und eine gelassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Wachet also, denn ihr wisset nicht, zu welcher Stunde euer Herr kommt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Jenes aber erkennet: Wenn der Hausherr gewußt hätte, in welcher Wache der Dieb komme, so würde er wohl gewacht und nicht erlaubt haben, daß sein Haus durchgraben würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Deshalb auch ihr, seid bereit; denn in der Stunde, in welcher ihr es nicht meinet, kommt der Sohn des Menschen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Wer ist nun der treue und kluge Knecht, den sein Herr über sein Gesinde gesetzt hat, um ihnen die Speise zu geben zur rechten Zeit?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Glückselig jener Knecht, den sein Herr, wenn er kommt, also tuend finden wird!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Wahrlich, ich sage euch, er wird ihn über seine ganze Habe setzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Wenn aber jener böse Knecht in seinem Herzen sagt: Mein Herr verzieht zu kommen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'und anfängt, seine Mitknechte zu schlagen, und ißt und trinkt mit den Trunkenen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'so wird der Herr jenes Knechtes kommen an einem Tage, an welchem er es nicht erwartet, und in einer Stunde, die er nicht weiß,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'und wird ihn entzweischneiden und ihm sein Teil setzen mit den Heuchlern: da wird sein das Weinen und das Zähneknirschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Alsdann wird das Reich der Himmel gleich geworden sein zehn Jungfrauen, welche ihre Lampen nahmen und ausgingen, dem Bräutigam entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Fünf aber von ihnen waren klug und fünf töricht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Die, welche töricht waren, nahmen ihre Lampen und nahmen kein Öl mit sich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'die Klugen aber nahmen Öl in ihren Gefäßen mit ihren Lampen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Als aber der Bräutigam verzog, wurden sie alle schläfrig und schliefen ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Um Mitternacht aber entstand ein Geschrei: Siehe, der Bräutigam! Gehet aus, ihm entgegen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Da standen alle jene Jungfrauen auf und schmückten ihre Lampen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Die Törichten aber sprachen zu den Klugen: Gebet uns von eurem Öl, denn unsere Lampen erlöschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Die Klugen aber antworteten und sagten: Nicht also, damit es nicht etwa für uns und euch nicht ausreiche; gehet lieber hin zu den Verkäufern und kaufet für euch selbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Als sie aber hingingen zu kaufen, kam der Bräutigam, und die bereit waren, gingen mit ihm ein zur Hochzeit; und die Tür ward verschlossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Später aber kommen auch die übrigen Jungfrauen und sagen: Herr, Herr, tue uns auf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Er aber antwortete und sprach: Wahrlich, ich sage euch, ich kenne euch nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'So wachet nun, denn ihr wisset weder den Tag noch die Stunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Denn gleichwie ein Mensch, der außer Landes reiste, seine eigenen Knechte rief und ihnen seine Habe übergab: und einem gab er fünf Talente,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'einem anderen zwei, einem anderen eins, einem jeden nach seiner eigenen Fähigkeit; und alsbald reiste er außer Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Der die fünf Talente empfangen hatte, ging aber hin und handelte mit denselben und gewann andere fünf Talente.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Desgleichen auch, der die zwei empfangen hatte, auch er gewann andere zwei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Der aber das eine empfangen hatte, ging hin, grub in die Erde und verbarg das Geld seines Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Nach langer Zeit aber kommt der Herr jener Knechte und hält Rechnung mit ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Und es trat herzu, der die fünf Talente empfangen hatte, und brachte andere fünf Talente und sagte: Herr, fünf Talente hast du mir übergeben, siehe, andere fünf Talente habe ich zu denselben gewonnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Sein Herr sprach zu ihm: Wohl, du guter und treuer Knecht! Über weniges warst du treu, über vieles werde ich dich setzen; gehe ein in die Freude deines Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Es trat aber auch herzu, der die zwei Talente empfangen hatte, und sprach: Herr, zwei Talente hast du mir übergeben; siehe, andere zwei Talente habe ich zu denselben gewonnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Sein Herr sprach zu ihm: Wohl, du guter und treuer Knecht! Über weniges warst du treu, über vieles werde ich dich setzen; gehe ein in die Freude deines Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Es trat aber auch herzu, der das eine Talent empfangen hatte, und sprach: Herr, ich kannte dich, daß du ein harter Mann bist: du erntest, wo du nicht gesät, und sammelst, wo du nicht ausgestreut hast;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'und ich fürchtete mich und ging hin und verbarg dein Talent in der Erde; siehe, da hast du das Deine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Sein Herr aber antwortete und sprach zu ihm: Böser und fauler Knecht! Du wußtest, daß ich ernte, wo ich nicht gesät, und sammle, wo ich nicht ausgestreut habe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'So solltest du nun mein Geld den Wechslern gegeben haben, und wenn ich kam, hätte ich das Meine mit Zinsen erhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Nehmet nun das Talent von ihm und gebet es dem, der sie zehn Talente hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'denn jedem, der da hat, wird gegeben werden, und er wird Überfluß haben; von dem aber, der nicht hat, von dem wird selbst, was er hat, weggenommen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Und den unnützen Knecht werfet hinaus in die äußere Finsternis: da wird sein das Weinen und das Zähneknirschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Wenn aber der Sohn des Menschen kommen wird in seiner Herrlichkeit, und alle Engel mit ihm, dann wird er auf seinem Throne der Herrlichkeit sitzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'und vor ihm werden versammelt werden alle Nationen, und er wird sie voneinander scheiden, gleichwie der Hirt die Schafe von den Böcken scheidet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'Und er wird die Schafe zu seiner Rechten stellen, die Böcke aber zur Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Dann wird der König zu denen zu seiner Rechten sagen: Kommet her, Gesegnete meines Vaters, ererbet das Reich, das euch bereitet ist von Grundlegung der Welt an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'denn mich hungerte, und ihr gabet mir zu essen; mich dürstete, und ihr tränktet mich; ich war Fremdling, und ihr nahmet mich auf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'nackt, und ihr bekleidetet mich; ich war krank, und ihr besuchtet mich; ich war im Gefängnis, und ihr kamet zu mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Alsdann werden die Gerechten ihm antworten und sagen: Herr, wann sahen wir dich hungrig und speisten dich? Oder durstig und tränkten dich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Wann aber sahen wir dich als Fremdling, und nahmen dich auf? Oder nackt und bekleideten dich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Wann aber sahen wir dich krank oder im Gefängnis und kamen zu dir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Und der König wird antworten und zu ihnen sagen: Wahrlich, ich sage euch, insofern ihr es einem der geringsten dieser meiner Brüder getan habt, habt ihr es mir getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Dann wird er auch zu denen zur Linken sagen: Gehet von mir, Verfluchte, in das ewige Feuer, das bereitet ist dem Teufel und seinen Engeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'denn mich hungerte, und ihr gabet mir nicht zu essen; mich dürstete, und ihr tränktet mich nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'ich war Fremdling, und ihr nahmet mich nicht auf; nackt, und ihr bekleidetet mich nicht; krank und im Gefängnis, und ihr besuchtet mich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Dann werden auch sie antworten und sagen: Herr, wann sahen wir dich hungrig, oder durstig, oder als Fremdling, oder nackt, oder krank, oder im Gefängnis, und haben dir nicht gedient?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Dann wird er ihnen antworten und sagen: Wahrlich, ich sage euch, insofern ihr es einem dieser Geringsten nicht getan habt, habt ihr es auch mir nicht getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Und diese werden hingehen in die ewige Pein, die Gerechten aber in das ewige Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Und es geschah, als Jesus alle diese Reden vollendet hatte, sprach er zu seinen Jüngern:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Ihr wisset, daß nach zwei Tagen das Passah ist, und der Sohn des Menschen wird überliefert, um gekreuzigt zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Dann versammelten sich die Hohenpriester und die Ältesten des Volkes in den Hof des Hohenpriesters, der Kajaphas hieß,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'und ratschlagten miteinander, auf daß sie Jesum mit List griffen und töteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Sie sagten aber: Nicht an dem Feste, auf daß nicht ein Aufruhr unter dem Volk entstehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Als aber Jesus in Bethanien war, im Hause Simons, des Aussätzigen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'kam ein Weib zu ihm, die ein Alabasterfläschchen mit sehr kostbarer Salbe hatte, und goß es auf sein Haupt, als er zu Tische lag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Als aber die Jünger es sahen, wurden sie unwillig und sprachen: Wozu diese Verschwendung?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Denn dieses hätte um vieles verkauft und den Armen gegeben werden können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Als aber Jesus es erkannte, sprach er zu ihnen: Was machet ihr dem Weibe Mühe? Denn sie hat ein gutes Werk an mir getan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'denn die Armen habt ihr allezeit bei euch, mich aber habt ihr nicht allezeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Denn indem sie diese Salbe über meinen Leib geschüttet hat, hat sie es zu meinem Begräbnis getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Wahrlich, ich sage euch: Wo irgend dieses Evangelium gepredigt werden wird in der ganzen Welt, wird auch von dem geredet werden, was diese getan hat, zu ihrem Gedächtnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Dann ging einer von den Zwölfen, der Judas Iskariot genannt war, zu den Hohenpriestern und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'Was wollt ihr mir geben, und ich werde ihn euch überliefern? Sie aber stellten ihm dreißig Silberlinge fest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Und von da an suchte er Gelegenheit, auf daß er ihn überliefere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'An dem ersten Tage der ungesäuerten Brote aber traten die Jünger zu Jesu und sprachen: Wo willst du, daß wir dir bereiten, das Passah zu essen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Er aber sprach: Gehet in die Stadt zu dem und dem und sprechet zu ihm: Der Lehrer sagt: Meine Zeit ist nahe; bei dir halte ich das Passah mit meinen Jüngern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Und die Jünger taten, wie Jesus ihnen befohlen hatte, und bereiteten das Passah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Als es aber Abend geworden war, legte er sich mit den Zwölfen zu Tische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Und während sie aßen, sprach er: Wahrlich, ich sage euch: Einer von euch wird mich überliefern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Und sie wurden sehr betrübt und fingen an, ein jeder von ihnen zu ihm zu sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Ich bin es doch nicht, Herr? Er aber antwortete und sprach: Der mit mir die Hand in die Schüssel eintaucht, dieser wird mich überliefern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Der Sohn des Menschen geht zwar dahin, wie über ihn geschrieben steht; wehe aber jenem Menschen, durch welchen der Sohn des Menschen überliefert wird! Es wäre jenem Menschen gut, wenn er nicht geboren wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Judas aber, der ihn überlieferte, antwortete und sprach: Ich bin es doch nicht, Rabbi? Er spricht zu ihm: Du hast es gesagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Während sie aber aßen, nahm Jesus Brot, segnete, brach und gab es den Jüngern und sprach: Nehmet, esset; dieses ist mein Leib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Und er nahm den Kelch und dankte und gab ihnen denselben und sprach: Trinket alle daraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Denn dieses ist mein Blut, das des neuen Bundes, welches für viele vergossen wird zur Vergebung der Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Ich sage euch aber, daß ich von nun an nicht mehr von diesem Gewächs des Weinstocks trinken werde, bis an jenem Tage, da ich es neu mit euch trinken werde in dem Reiche meines Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Und als sie ein Loblied gesungen hatten, gingen sie hinaus nach dem Ölberg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Da spricht Jesus zu ihnen: Ihr werdet euch alle in dieser Nacht an mir ärgern; denn es steht geschrieben: \"Ich werde den Hirten schlagen, und die Schafe der Herde werden zerstreut werden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Nachdem ich aber auferweckt sein werde, werde ich vor euch hingehen nach Galiläa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Petrus aber antwortete und sprach zu ihm: Wenn sich alle an dir ärgern werden, ich werde mich niemals ärgern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jesus sprach zu ihm: Wahrlich, ich sage dir, daß du in dieser Nacht, ehe der Hahn kräht, mich dreimal verleugnen wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Petrus spricht zu ihm: Selbst wenn ich mit dir sterben müßte, werde ich dich nicht verleugnen. Gleicherweise sprachen auch alle Jünger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Dann kommt Jesus mit ihnen an einen Ort, genannt Gethsemane, und er spricht zu den Jüngern: Setzet euch hier, bis ich hingegangen bin und dort gebetet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Und er nahm den Petrus und die zwei Söhne des Zebedäus mit, und fing an betrübt und beängstigt zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Dann spricht er zu ihnen: Meine Seele ist sehr betrübt bis zum Tode; bleibet hier und wachet mit mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Und er ging ein wenig weiter und fiel auf sein Angesicht und betete und sprach: Mein Vater, wenn es möglich ist, so gehe dieser Kelch an mir vorüber; doch nicht wie ich will, sondern wie du willst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Und er kommt zu den Jüngern und findet sie schlafend; und er spricht zu Petrus: also nicht eine Stunde vermochtet ihr mit mir zu wachen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Wachet und betet, auf daß ihr nicht in Versuchung kommet; der Geist zwar ist willig, das Fleisch aber schwach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Wiederum, zum zweiten Male, ging er hin und betete und sprach: Mein Vater, wenn dieser Kelch nicht an mir vorübergehen kann, ohne daß ich ihn trinke, so geschehe dein Wille.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Und als er kam, fand er sie wiederum schlafend, denn ihre Augen waren beschwert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Und er ließ sie, ging wiederum hin, betete zum dritten Male und sprach dasselbe Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Dann kommt er zu den Jüngern und spricht zu ihnen: So schlafet denn fort und ruhet aus; siehe, die Stunde ist nahe gekommen, und der Sohn des Menschen wird in Sünderhände überliefert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Stehet auf, laßt uns gehen; siehe, nahe ist gekommen, der mich überliefert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Und während er noch redete, siehe, da kam Judas, einer der Zwölfe, und mit ihm eine große Volksmenge mit Schwertern und Stöcken, von den Hohenpriestern und Ältesten des Volkes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Der ihn aber überlieferte, hatte ihnen ein Zeichen gegeben und gesagt: Welchen irgend ich küssen werde, der ist es; ihn greifet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Und alsbald trat er zu Jesu und sprach: Sei gegrüßt, Rabbi! und küßte ihn sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Jesus aber sprach zu ihm: Freund, wozu bist du gekommen! Dann traten sie herzu und legten die Hände an Jesum und griffen ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Und siehe, einer von denen, die mit Jesu waren, streckte die Hand aus, zog sein Schwert und schlug den Knecht des Hohenpriesters und hieb ihm das Ohr ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Da spricht Jesus zu ihm: Stecke dein Schwert wieder an seinen Ort; denn alle, die das Schwert nehmen, werden durchs Schwert umkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Oder meinst du, daß ich nicht jetzt meinen Vater bitten könne, und er mir mehr als zwölf Legionen Engel stellen werde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Wie sollten denn die Schriften erfüllt werden, daß es also geschehen muß?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'In jener Stunde sprach Jesus zu den Volksmengen: Seid ihr ausgezogen wie gegen einen Räuber mit Schwertern und Stöcken, mich zu fangen? Täglich saß ich bei euch, im Tempel lehrend, und ihr habt mich nicht gegriffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Aber dies alles ist geschehen, auf daß die Schriften der Propheten erfüllt würden. Da verließen ihn die Jünger alle und flohen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Die aber Jesum gegriffen hatten, führten ihn hinweg zu Kajaphas, dem Hohenpriester, wo die Schriftgelehrten und die Ältesten versammelt waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Petrus aber folgte ihm von ferne bis zu dem Hofe des Hohenpriesters und ging hinein und setzte sich zu den Dienern, um das Ende zu sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Die Hohenpriester aber und die Ältesten und das ganze Synedrium suchten falsches Zeugnis wider Jesum, damit sie ihn zum Tode brächten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'und sie fanden keines, wiewohl viele falsche Zeugen herzutraten. Zuletzt aber traten zwei falsche Zeugen herzu');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'und sprachen: dieser sagte: Ich kann den Tempel Gottes abbrechen und in drei Tagen ihn aufbauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Und der Hohepriester stand auf und sprach zu ihm: Antwortest du nichts? Was zeugen diese wider dich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Jesus aber schwieg. Und der Hohepriester hob an und sprach zu ihm: Ich beschwöre dich bei dem lebendigen Gott, daß du uns sagest, ob du der Christus bist, der Sohn Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jesus spricht zu ihm: Du hast es gesagt. Doch ich sage euch: Von nun an werdet ihr den Sohn des Menschen sitzen sehen zur Rechten der Macht und kommen auf den Wolken des Himmels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Da zerriß der Hohepriester seine Kleider und sprach: Er hat gelästert; was bedürfen wir noch Zeugen? Siehe, jetzt habt ihr die Lästerung gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Was dünkt euch? Sie aber antworteten und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Er ist des Todes schuldig. Dann spieen sie ihm ins Angesicht und schlugen ihn mit Fäusten; etliche aber gaben ihm Backenstreiche');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'und sprachen: Weissage uns, Christus, wer ist es, der dich schlug?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Petrus aber saß draußen im Hofe; und es trat eine Magd zu ihm und sprach: Auch du warst mit Jesu, dem Galiläer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Er aber leugnete vor allen und sprach: Ich weiß nicht, was du sagst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Als er aber in das Tor hinausgegangen war, sah ihn eine andere; und sie spricht zu denen, die daselbst waren: Auch dieser war mit Jesu, dem Nazaräer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Und wiederum leugnete er mit einem Eide: Ich kenne den Menschen nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Kurz nachher aber traten die Dastehenden herzu und sprachen zu Petrus: Wahrhaftig, auch du bist einer von ihnen, denn auch deine Sprache macht dich offenbar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Da fing er an, sich zu verwünschen und zu schwören: Ich kenne den Menschen nicht! Und alsbald krähte der Hahn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Und Petrus gedachte des Wortes Jesu, der zu ihm gesagt hatte: Ehe der Hahn kräht, wirst du mich dreimal verleugnen. Und er ging hinaus und weinte bitterlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Als es aber Morgen geworden war, hielten alle Hohenpriester und Ältesten des Volkes Rat wider Jesum, um ihn zum Tode zu bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Und nachdem sie ihn gebunden hatten, führten sie ihn weg und überlieferten ihn Pontius Pilatus, dem Landpfleger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Als nun Judas, der ihn überliefert hatte, sah, daß er verurteilt wurde, gereute es ihn, und er brachte die dreißig Silberlinge den Hohenpriestern und den Ältesten zurück und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'Ich habe gesündigt, indem ich schuldloses Blut überliefert habe. Sie aber sagten: Was geht das uns an? Siehe du zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Und er warf die Silberlinge in den Tempel und machte sich davon und ging hin und erhängte sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Die Hohenpriester aber nahmen die Silberlinge und sprachen: Es ist nicht erlaubt, sie in den Korban zu werfen, dieweil es Blutgeld ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Sie hielten aber Rat und kauften dafür den Acker des Töpfers zum Begräbnis für die Fremdlinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Deswegen ist jener Acker Blutacker genannt worden bis auf den heutigen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Da wurde erfüllt, was durch den Propheten Jeremias geredet ist, welcher spricht: \"Und sie nahmen die dreißig Silberlinge, den Preis des Geschätzten, welchen man geschätzt hatte seitens der Söhne Israels,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'und gaben sie für den Acker des Töpfers, wie mir der Herr befohlen hat.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Jesus aber stand vor dem Landpfleger. Und der Landpfleger fragte ihn und sprach: Bist du der König der Juden? Jesus aber sprach zu ihm: Du sagst es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Und als er von den Hohenpriestern und den Ältesten angeklagt wurde, antwortete er nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Da spricht Pilatus zu ihm: Hörst du nicht, wie vieles sie wider dich zeugen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Und er antwortete ihm auch nicht auf einziges Wort, so daß der Landpfleger sich sehr verwunderte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Auf das Fest aber war der Landpfleger gewohnt, der Volksmenge einen Gefangenen loszugeben, welchen sie wollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Sie hatten aber damals einen berüchtigten Gefangenen, genannt Barabbas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Als sie nun versammelt waren, sprach Pilatus zu ihnen: Wen wollt ihr, daß ich euch losgeben soll, Barabbas oder Jesum, welcher Christus genannt wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Denn er wußte, daß sie ihn aus Neid überliefert hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Während er aber auf dem Richterstuhl saß, sandte sein Weib zu ihm und ließ ihm sagen: Habe du nichts zu schaffen mit jenem Gerechten; denn viel habe ich heute im Traum gelitten um seinetwillen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Aber die Hohenpriester und die Ältesten überredeten die Volksmengen, daß sie um den Barabbas bäten, Jesum aber umbrächten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Der Landpfleger aber antwortete und sprach zu ihnen: Welchen von den beiden wollt ihr, daß ich euch losgebe? Sie aber sprachen: Barabbas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Pilatus spricht zu ihnen: Was soll ich denn mit Jesu tun, welcher Christus genannt wird? Sie sagen alle: Er werde gekreuzigt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Der Landpfleger aber sagte: Was hat er denn Böses getan? Sie aber schrieen übermäßig und sagten: Er werde gekreuzigt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Als aber Pilatus sah, daß er nichts ausrichtete, sondern vielmehr ein Tumult entstand, nahm er Wasser, wusch seine Hände vor der Volksmenge und sprach: Ich bin schuldlos an dem Blute dieses Gerechten; sehet ihr zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Und das ganze Volk antwortete und sprach: Sein Blut komme über uns und über unsere Kinder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Alsdann gab er ihnen den Barabbas los; Jesum aber ließ er geißeln und überlieferte ihn, auf daß er gekreuzigt würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Dann nahmen die Kriegsknechte des Landpflegers Jesum mit in das Prätorium und versammelten über ihn die ganze Schar;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'und sie zogen ihn aus und legten ihm einen Purpurmantel um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'Und sie flochten eine Krone aus Dornen und setzten sie auf sein Haupt, und gaben ihm ein Rohr in seine Rechte; und sie fielen vor ihm auf die Knie und verspotteten ihn und sagten: Sei gegrüßt, König der Juden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Und sie spieen ihn an, nahmen das Rohr und schlugen ihn auf das Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Und als sie ihn verspottet hatten, zogen sie ihm den Mantel aus und zogen ihm seine eigenen Kleider an; und sie führten ihn hin, um ihn zu kreuzigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Als sie aber hinausgingen, fanden sie einen Menschen von Kyrene, mit Namen Simon; diesen zwangen sie, daß er sein Kreuz trüge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Und als sie an einen Ort gekommen waren, genannt Golgatha, das heißt Schädelstätte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'gaben sie ihm Essig mit Galle vermischt zu trinken; und als er es geschmeckt hatte, wollte er nicht trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Als sie ihn aber gekreuzigt hatten, verteilten sie seine Kleider, indem sie das Los warfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'Und sie saßen und bewachten ihn daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Und sie befestigten oben über seinem Haupte seine Beschuldigungsschrift: Dieser ist Jesus, der König der Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Alsdann werden zwei Räuber mit ihm gekreuzigt, einer zur Rechten und einer zur Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Die Vorübergehenden aber lästerten ihn, indem sie ihre Köpfe schüttelten und sagten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'Der du den Tempel abbrichst und in drei Tagen aufbaust, rette dich selbst. Wenn du Gottes Sohn bist, so steige herab vom Kreuze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Gleicherweise aber spotteten auch die Hohenpriester samt den Schriftgelehrten und Ältesten und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Andere hat er gerettet, sich selbst kann er nicht retten. Er ist Israels König; so steige er jetzt vom Kreuze herab, und wir wollen an ihn glauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Er vertraute auf Gott, der rette ihn jetzt, wenn er ihn begehrt; denn er sagte: Ich bin Gottes Sohn. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Auf dieselbe Weise schmähten ihn auch die Räuber, die mit ihm gekreuzigt waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Aber von der sechsten Stunde an kam eine Finsternis über das ganze Land bis zur neunten Stunde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'um die neunte Stunde aber schrie Jesus auf mit lauter Stimme und sagte: Eli, eli, lama sabachthani? das ist: Mein Gott, mein Gott, warum hast du mich verlassen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Als aber etliche der Dastehenden es hörten, sagten sie: Dieser ruft den Elias.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Und alsbald lief einer von ihnen und nahm einen Schwamm, füllte ihn mit Essig und steckte ihn auf ein Rohr und tränkte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Die Übrigen aber sagten: Halt, laßt uns sehen, ob Elias kommt, ihn zu retten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Jesus aber schrie wiederum mit lauter Stimme und gab den Geist auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Und siehe, der Vorhang des Tempels zerriß in zwei Stücke, von oben bis unten; und die Erde erbebte, und die Felsen zerrissen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'und die Grüfte taten sich auf, und viele Leiber der entschlafenen Heiligen wurden auferweckt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'und sie gingen nach seiner Auferweckung aus den Grüften und gingen in die heilige Stadt und erschienen vielen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Als aber der Hauptmann und die mit ihm Jesum bewachten, das Erdbeben sahen und das, was geschah, fürchteten sie sich sehr und sprachen: Wahrhaftig, dieser war Gottes Sohn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Es waren aber daselbst viele Weiber, die von ferne zusahen, welche Jesu von Galiläa nachgefolgt waren und ihm gedient hatten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'unter welchen Maria Magdalene war und Maria, Jakobus\' und Joses\' Mutter, und die Mutter der Söhne des Zebedäus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Als es aber Abend geworden war, kam ein reicher Mann von Arimathia, namens Joseph, der auch selbst ein Jünger Jesu war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Dieser ging hin zu Pilatus und bat um den Leib Jesu. Da befahl Pilatus, daß ihm der Leib übergeben würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Und Joseph nahm den Leib und wickelte ihn in reine, feine Leinwand,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'und legte ihn in seine neue Gruft, die er in dem Felsen ausgehauen hatte; und er wälzte einen großen Stein an die Tür der Gruft und ging hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Es waren aber daselbst Maria Magdalene und die andere Maria, die dem Grabe gegenüber saßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Des folgenden Tages aber, der nach dem Rüsttage ist, versammelten sich die Hohenpriester und die Pharisäer bei Pilatus und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'Herr, wir haben uns erinnert, daß jener Verführer sagte, als er noch lebte: Nach drei Tagen stehe ich wieder auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'So befiehl nun, daß das Grab gesichert werde bis zum dritten Tage, damit nicht etwa seine Jünger kommen, ihn stehlen und dem Volke sagen: Er ist von den Toten auferstanden; und die letzte Verführung wird ärger sein als die erste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilatus aber sprach zu ihnen: Ihr habt eine Wache; gehet hin, sichert es, so gut ihr es wisset.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Sie aber gingen hin und sicherten, nachdem sie den Stein versiegelt hatten, das Grab mit der Wache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Aber spät am Sabbath, in der Dämmerung des ersten Wochentages, kam Maria Magdalene und die andere Maria, um das Grab zu besehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Und siehe, da geschah ein großes Erdbeben; denn ein Engel des Herrn kam aus dem Himmel hernieder, trat hinzu, wälzte den Stein weg und setzte sich darauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Sein Ansehen aber war wie der Blitz, und sein Kleid weiß wie Schnee.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Aber aus Furcht vor ihm bebten die Hüter und wurden wie Tote.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Der Engel aber hob an und sprach zu den Weibern: Fürchtet ihr euch nicht, denn ich weiß, daß ihr Jesum, den Gekreuzigten, suchet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Er ist nicht hier, denn er ist auferstanden, wie er gesagt hat. Kommet her, sehet die Stätte, wo der Herr gelegen hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'und gehet eilends hin und saget seinen Jüngern, daß er von den Toten auferstanden ist; und siehe, er geht vor euch hin nach Galiläa, daselbst werdet ihr ihn sehen. Siehe, ich habe es euch gesagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Und sie gingen eilends von der Gruft hinweg mit Furcht und großer Freude, und liefen, es seinen Jüngern zu verkünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Als sie aber hingingen, es seinen Jüngern zu verkünden, siehe, da kam Jesus ihnen entgegen und sprach: Seid gegrüßt! Sie aber traten herzu, umfaßten seine Füße und huldigten ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Da spricht Jesus zu ihnen: Fürchtet euch nicht; gehet hin, verkündet meinen Brüdern, daß sie hingehen nach Galiläa, und daselbst werden sie mich sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Während sie aber hingingen, siehe, da kamen etliche von der Wache in die Stadt und verkündeten den Hohenpriestern alles, was geschehen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Und sie versammelten sich mit den Ältesten und hielten Rat; und sie gaben den Soldaten Geld genug');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'und sagten: Sprechet: Seine Jünger kamen bei Nacht und stahlen ihn, während wir schliefen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Und wenn dies dem Landpfleger zu Ohren kommen sollte, so werden wir ihn zufriedenstellen und machen, daß ihr ohne Sorge seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Sie aber nahmen das Geld und taten, wie sie unterrichtet worden waren. Und diese Rede ist bei den Juden ruchbar geworden bis auf den heutigen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Die elf Jünger aber gingen nach Galiläa, an den Berg, wohin Jesus sie beschieden hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Und als sie ihn sahen, warfen sie sich vor ihm nieder; einige aber zweifelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Und Jesus trat herzu und redete mit ihnen und sprach: Mir ist alle Gewalt gegeben im Himmel und auf Erden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Gehet nun hin und machet alle Nationen zu Jüngern, und taufet sie auf den Namen des Vaters und des Sohnes und des Heiligen Geistes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'und lehret sie, alles zu bewahren, was ich euch geboten habe. Und siehe, ich bin bei euch alle Tage bis zur Vollendung des Zeitalters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Anfang des Evangeliums Jesu Christi, des Sohnes Gottes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'wie geschrieben steht in Jesaias, dem Propheten: \"Siehe, ich sende meinen Boten vor deinem Angesicht her, der deinen Weg bereiten wird\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, '\"Stimme eines Rufenden in der Wüste: Bereitet den Weg des Herrn, machet gerade seine Steige!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Johannes kam und taufte in der Wüste und predigte die Taufe der Buße zur Vergebung der Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Und es ging zu ihm hinaus das ganze jüdische Land und alle Bewohner von Jerusalem; und sie wurden im Jordanflusse von ihm getauft, indem sie ihre Sünden bekannten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Johannes aber war bekleidet mit Kamelhaaren und einem ledernen Gürtel um seine Lenden; und er aß Heuschrecken und wilden Honig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Und er predigte und sagte: Es kommt nach mir, der stärker ist als ich, dessen ich nicht würdig bin, ihm gebückt den Riemen seiner Sandalen zu lösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Ich zwar habe euch mit Wasser getauft, er aber wird euch mit Heiligem Geiste taufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Und es geschah in jenen Tagen, da kam Jesus von Nazareth in Galiläa, und wurde von Johannes in dem Jordan getauft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Und alsbald, als er von dem Wasser heraufstieg, sah er die Himmel sich teilen und den Geist wie eine Taube auf ihn herniederfahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Und eine Stimme geschah aus den Himmeln: Du bist mein geliebter Sohn, an dir habe ich Wohlgefallen gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Und alsbald treibt der Geist ihn hinaus in die Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Und er war vierzig Tage in der Wüste und wurde von dem Satan versucht; und er war unter den wilden Tieren, und die Engel dienten ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Nachdem aber Johannes überliefert war, kam Jesus nach Galiläa, predigte das Evangelium des Reiches Gottes und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'Die Zeit ist erfüllt, und das Reich Gottes ist nahe gekommen. Tut Buße und glaubet an das Evangelium.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Als er aber am See von Galiläa wandelte, sah er Simon und Andreas, Simons Bruder, die in dem See ein Netz hin-und herwarfen, denn sie waren Fischer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Und Jesus sprach zu ihnen: Kommet mir nach, und ich werde euch zu Menschenfischern machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'und alsbald verließen sie ihre Netze und folgten ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Und von dannen ein wenig weitergehend, sah er Jakobus, den Sohn des Zebedäus, und seinen Bruder Johannes, auch sie im Schiffe, wie sie die Netze ausbesserten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'und alsbald rief er sie. Und sie ließen ihren Vater Zebedäus in dem Schiffe mit den Tagelöhnern und gingen weg, ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Und sie gehen hinein nach Kapernaum. Und alsbald an dem Sabbath ging er in die Synagoge und lehrte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Und sie erstaunten sehr über seine Lehre: denn er lehrte sie wie einer, der Gewalt hat, und nicht wie die Schriftgelehrten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Und es war in ihrer Synagoge ein Mensch mit einem unreinen Geiste;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'und er schrie auf und sprach: Laß ab! Was haben wir mit dir zu schaffen, Jesu, Nazarener? Bist du gekommen, uns zu verderben? Ich kenne dich, wer du bist: der Heilige Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Und Jesus bedrohte ihn und sprach: Verstumme und fahre aus von ihm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Und der unreine Geist zerrte ihn und rief mit lauter Stimme und fuhr von ihm aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Und sie entsetzten sich alle, so daß sie sich untereinander befragten und sprachen: Was ist dies? Was ist dies für eine neue Lehre? Denn mit Gewalt gebietet er selbst den unreinen Geistern, und sie gehorchen ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Und alsbald ging das Gerücht von ihm aus in die ganze Umgegend von Galiläa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Und alsbald gingen sie aus der Synagoge und kamen in das Haus Simons und Andreas\', mit Jakobus und Johannes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Die Schwiegermutter Simons aber lag fieberkrank danieder; und alsbald sagen sie ihm von ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Und er trat hinzu und richtete sie auf, indem er sie bei der Hand ergriff; und das Fieber verließ sie alsbald, und sie diente ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Als es aber Abend geworden war, als die Sonne unterging, brachten sie alle Leidenden und Besessenen zu ihm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'und die ganze Stadt war an der Tür versammelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Und er heilte viele, die an mancherlei Krankheiten leidend waren; und er trieb viele Dämonen aus und erlaubte den Dämonen nicht zu reden, weil sie ihn kannten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Und frühmorgens, als es noch sehr dunkel war, stand er auf und ging hinaus und ging hin an einen öden Ort und betete daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Und Simon und die mit ihm waren, gingen ihm nach;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'und als sie ihn gefunden hatten, sagen sie zu ihm: Alle suchen dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Und er spricht zu ihnen: Laßt uns anderswohin in die nächsten Flecken gehen, auf daß ich auch daselbst predige; denn dazu bin ich ausgegangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Und er predigte in ihren Synagogen in ganz Galiläa und trieb die Dämonen aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Und es kommt ein Aussätziger zu ihm, bittet ihn und kniet vor ihm nieder und spricht zu ihm: Wenn du willst, kannst du mich reinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Jesus aber, innerlich bewegt, streckte die Hand aus, rührte ihn an und spricht zu ihm: Ich will; sei gereinigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Und während er redete, wich alsbald der Aussatz von ihm, und er war gereinigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Und er bedrohte ihn und schickte ihn alsbald fort und spricht zu ihm:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'Siehe zu, sage niemand etwas; sondern gehe hin, zeige dich dem Priester und opfere für deine Reinigung, was Moses geboten hat, ihnen zu einem Zeugnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Er aber ging weg und fing an, es viel kundzumachen und die Sache auszubreiten, so daß er nicht mehr öffentlich in die Stadt gehen konnte; sondern er war draußen in öden Örtern, und sie kamen von allen Seiten zu ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Und nach etlichen Tagen ging er wiederum hinein nach Kapernaum, und es wurde ruchbar, daß er im Hause sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Und alsbald versammelten sich viele, so daß selbst an der Tür nicht mehr Raum war; und er redete zu ihnen das Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Und sie kommen zu ihm und bringen einen Gelähmten, von vieren getragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Und da sie wegen der Volksmenge nicht nahe zu ihm kommen konnten, deckten sie das Dach ab, wo er war; und als sie es aufgebrochen hatten, ließen sie das Ruhebett hinab, auf welchem der Gelähmte lag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Als Jesus aber ihren Glauben sah, spricht er zu dem Gelähmten: Kind, deine Sünden sind vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Etliche aber von den Schriftgelehrten saßen daselbst und überlegten in ihren Herzen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Was redet dieser also? Er lästert. Wer kann Sünden vergeben, als nur einer, Gott?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Und alsbald erkannte Jesus in seinem Geiste, daß sie also bei sich überlegten, und sprach zu ihnen: Was überleget ihr dies in euren Herzen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Was ist leichter, zu dem Gelähmten zu sagen: Deine Sünden sind vergeben, oder zu sagen: Stehe auf, nimm dein Ruhebett auf und wandle?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Auf daß ihr aber wisset, daß der Sohn des Menschen Gewalt hat auf der Erde Sünden zu vergeben... spricht er zu dem Gelähmten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Ich sage dir, stehe auf, nimm dein Ruhebett auf und geh nach deinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Und alsbald stand er auf, nahm das Ruhebett auf und ging hinaus vor allen, so daß alle außer sich gerieten und Gott verherrlichten und sagten: Niemals haben wir es also gesehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Und er ging wiederum hinaus an den See, und die ganze Volksmenge kam zu ihm, und er lehrte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Und als er vorüberging, sah er Levi, den Sohn des Alphäus, am Zollhause sitzen, und er spricht zu ihm: Folge mir nach; und er stand auf und folgte ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Und es geschah, als er in seinem Hause zu Tische lag, daß viele Zöllner und Sünder zu Tische lagen mit Jesu und seinen Jüngern; denn es waren ihrer viele, und sie folgten ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Und als die Schriftgelehrten und die Pharisäer ihn mit den Sündern und Zöllnern essen sahen, sprachen sie zu seinen Jüngern: Warum ißt und trinkt er mit den Zöllnern und Sündern?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Und als Jesus es hörte, spricht er zu ihnen: Die Starken bedürfen nicht eines Arztes, sondern die Kranken. Ich bin nicht gekommen, Gerechte zu rufen, sondern Sünder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Und die Jünger Johannes\' und die Pharisäer fasteten; und sie kommen und sagen zu ihm: Warum fasten die Jünger Johannes\' und die Jünger der Pharisäer, deine Jünger aber fasten nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Und Jesus sprach zu ihnen: Können etwa die Gefährten des Bräutigams fasten, während der Bräutigam bei ihnen ist? So lange sie den Bräutigam bei sich haben, können sie nicht fasten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Es werden aber Tage kommen, da der Bräutigam von ihnen weggenommen sein wird, und dann, an jenem Tage, werden sie fasten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Niemand näht einen Flicken von neuem Tuch auf ein altes Kleid; sonst reißt das Eingesetzte von ihm ab, das neue vom alten, und der Riß wird ärger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Auch tut niemand neuen Wein in alte Schläuche; sonst zerreißt der Wein die Schläuche, und der Wein wird verschüttet, und die Schläuche verderben; sondern neuen Wein muß man in neue Schläuche tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Und es geschah, daß er am Sabbath durch die Saaten ging; und seine Jünger fingen an, im Gehen die Ähren abzupflücken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Und die Pharisäer sprachen zu ihm: Siehe, was tun sie am Sabbath, das nicht erlaubt ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Und er sprach zu ihnen: Habt ihr nie gelesen, was David tat, als er Mangel hatte und als ihn und die bei ihm waren, hungerte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Wie er in das Haus Gottes ging unter Abjathar, dem Hohenpriester, und die Schaubrote aß (welche niemand essen darf, als nur die Priester), und auch denen gab, die bei ihm waren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Und er sprach zu ihnen: Der Sabbath ward um des Menschen willen, nicht der Mensch um des Sabbaths willen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'also ist der Sohn des Menschen Herr auch des Sabbaths.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Und er ging wiederum in die Synagoge; und es war daselbst ein Mensch, der eine verdorrte Hand hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Und sie lauerten auf ihn, ob er ihn am Sabbath heilen würde, auf daß sie ihn anklagen möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Und er spricht zu dem Menschen, der die verdorrte Hand hatte: Stehe auf und tritt in die Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Und er spricht zu ihnen: Ist es erlaubt, an den Sabbathen Gutes zu tun oder Böses zu tun, das Leben zu retten oder zu töten? Sie aber schwiegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Und er blickte auf sie umher mit Zorn, betrübt über die Verstockung ihres Herzens, und spricht zu dem Menschen: Strecke deine Hand aus! Und er streckte sie aus, und seine Hand wurde wiederhergestellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Und die Pharisäer gingen alsbald hinaus und hielten mit den Herodianern Rat wider ihn, wie sie ihn umbrächten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Und Jesus entwich mit seinen Jüngern an den See; und es folgte ihm eine große Menge von Galiläa und von Judäa');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'und von Jerusalem und von Idumäa und von jenseit des Jordan; und die um Tyrus und Sidon, eine große Menge, als sie gehört hatten, wie vieles er tat, kamen zu ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Und er sagte seinen Jüngern, daß ein Schifflein für ihn in Bereitschaft bleiben solle wegen der Volksmenge, auf daß sie ihn nicht drängten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Denn er heilte viele, so daß alle, welche Plagen hatten, ihn überfielen, auf daß sie ihn anrühren möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Und wenn die unreinen Geister ihn sahen, fielen sie vor ihm nieder und riefen und sprachen: Du bist der Sohn Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Und er bedrohte sie sehr, daß sie ihn nicht offenbar machten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Und er steigt auf den Berg und ruft herzu, welche er selbst wollte. Und sie kamen zu ihm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'und er bestellte zwölf, auf daß sie bei ihm seien, und auf daß er sie aussende zu predigen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'und Gewalt zu haben, die Krankheiten zu heilen und die Dämonen auszutreiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Und er gab dem Simon den Beinamen Petrus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'und Jakobus, den Sohn des Zebedäus, und Johannes, den Bruder des Jakobus, und er gab ihnen den Beinamen Boanerges, das ist Söhne des Donners;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'und Andreas und Philippus und Bartholomäus und Matthäus und Thomas und Jakobus, den Sohn des Alphäus, und Thaddäus, und Simon, den Kananäer,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'und Judas Iskariot, der ihn auch überlieferte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Und die kommen in ein Haus. Und wiederum kommt eine Volksmenge zusammen, so daß sie nicht einmal essen konnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Und als seine Angehörigen es hörten, gingen sie hinaus, um ihn zu greifen; denn sie sprachen: Er ist außer sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Und die Schriftgelehrten, die von Jerusalem herabgekommen waren, sprachen: Er hat den Beelzebub, und: Durch den Obersten der Dämonen treibt er die Dämonen aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Und er rief sie herzu und sprach in Gleichnissen zu ihnen: Wie kann Satan den Satan austreiben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Und wenn ein Reich wider sich selbst entzweit ist, so kann jenes Reich nicht bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'Und wenn ein Haus wider sich selbst entzweit ist, so kann jenes Haus nicht bestehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Und wenn der Satan wider sich selbst aufsteht und entzweit ist, so kann er nicht bestehen, sondern hat ein Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Niemand aber kann in das Haus des Starken eindringen und seinen Hausrat rauben, wenn er nicht zuvor den Starken bindet, und alsdann wird er sein Haus berauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Wahrlich, ich sage euch: Alle Sünden werden den Söhnen der Menschen vergeben werden, und die Lästerungen, mit welchen irgend sie lästern mögen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'wer aber irgend wider den Heiligen Geist lästern wird, hat keine Vergebung in Ewigkeit, sondern ist ewiger Sünde schuldig; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'weil sie sagten: Er hat einen unreinen Geist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Und es kommen seine Mutter und seine Brüder; und draußen stehend sandten sie zu ihm und riefen ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Und eine Volksmenge saß um ihn her; sie sagten aber zu ihm: Siehe, deine Mutter und deine Brüder draußen suchen dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Und er antwortete ihnen und sprach: Wer ist meine Mutter oder meine Brüder?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Und im Kreise umherblickend auf die um ihn her Sitzenden, spricht er: Siehe da, meine Mutter und meine Brüder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'denn wer irgend den Willen Gottes tun wird, derselbe ist mein Bruder und meine Schwester und meine Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Und wiederum fing er an, am See zu lehren. Und es versammelte sich eine große Volksmenge zu ihm, so daß er in ein Schiff stieg und auf dem See saß; und die ganze Volksmenge war am See auf dem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Und er lehrte sie vieles in Gleichnissen; und er sprach zu ihnen in seiner Lehre:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Höret! Siehe, der Säemann ging aus zu säen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Und es geschah, indem er säte, fiel etliches an den Weg, und die Vögel kamen und fraßen es auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Und anderes fiel auf das Steinichte, wo es nicht viel Erde hatte; und alsbald ging es auf, weil es nicht tiefe Erde hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Und als die Sonne aufging, wurde es verbrannt, und weil es keine Wurzel hatte, verdorrte es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Und anderes fiel unter die Dornen; und die Dornen schossen auf und erstickten es, und es gab keine Frucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Und anderes fiel in die gute Erde und gab Frucht, die aufschoß und wuchs; und eines trug dreißig-,und eines sechzig-,und eines hundertfältig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Und er sprach: Wer Ohren hat zu hören, der höre!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Und als er allein war, fragten ihn, die um ihn waren mit den Zwölfen um die Gleichnisse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Und er sprach zu ihnen: Euch ist es gegeben, das Geheimnis des Reiches Gottes zu wissen; jenen aber, die draußen sind, geschieht alles in Gleichnissen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, '\"auf daß sie sehend sehen und nicht wahrnehmen, und hörend hören und nicht verstehen, damit sie sich nicht etwa bekehren und ihnen vergeben werde\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Und er spricht zu ihnen: Fasset ihr dieses Gleichnis nicht? Und wie werdet ihr all die Gleichnisse verstehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Der Sämann sät das Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Diese aber sind die an dem Wege: wo das Wort gesät wird und, wenn sie es hören, alsbald der Satan kommt und das Wort wegnimmt, das in ihre Herzen gesät war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Und diese sind es gleicherweise, die auf das Steinichte gesät werden, welche, wenn sie das Wort hören, es alsbald mit Freuden aufnehmen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'und sie haben keine Wurzel in sich, sondern sind nur für eine Zeit; dann, wenn Drangsal entsteht oder Verfolgung um des Wortes willen, ärgern sie sich alsbald.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Und andere sind die, welche unter die Dornen gesät werden: diese sind es, welche das Wort gehört haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'und die Sorgen des Lebens und der Betrug des Reichtums und die Begierde nach den übrigen Dingen kommen hinein und ersticken das Wort, und es bringt keine Frucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Und diese sind es, die auf die gute Erde gesät sind, welche das Wort hören und aufnehmen und Frucht bringen: eines dreißig-,und eines sechzig-,und eines hundertfältig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Und er sprach zu ihnen: Kommt etwa die Lampe, auf daß sie unter den Scheffel oder unter das Bett gestellt werde? Nicht daß sie auf das Lampengestell gestellt werde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Denn es ist nichts verborgen, außer damit es offenbar gemacht werde, noch gibt es etwas Geheimes, sondern auf daß es ans Licht komme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Wenn jemand Ohren hat zu hören, der höre!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Und er sprach zu ihnen: Sehet zu, was ihr höret; mit welchem Maße ihr messet, wird euch gemessen werden, und es wird euch hinzugefügt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Denn wer irgend hat, dem wird gegeben werden; und wer nicht hat, von dem wird selbst, was er hat, genommen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Und er sprach: Also ist das Reich Gottes, wie wenn ein Mensch den Samen auf das Land wirft,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'und schläft und aufsteht, Nacht und Tag, und der Same sprießt hervor und wächst, er weiß selbst nicht wie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Die Erde bringt von selbst Frucht hervor, zuerst Gras, dann eine Ähre, dann vollen Weizen in der Ähre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Wenn aber die Frucht sich darbietet, so schickt er alsbald die Sichel, denn die Ernte ist da.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Und er sprach: Wie sollen wir das Reich Gottes vergleichen? Oder in welchem Gleichnis sollen wir es darstellen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Gleichwie ein Senfkorn, welches, wenn es auf die Erde gesät wird, kleiner ist als alle Samen, die auf der Erde sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'und, wenn es gesät ist, aufschießt und größer wird als alle Kräuter und große Zweige treibt, so daß unter seinem Schatten die Vögel des Himmels sich niederlassen können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'Und in vielen solchen Gleichnissen redete er zu ihnen das Wort, wie sie es zu hören vermochten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Ohne Gleichnis aber redete er nicht zu ihnen; aber seinen Jüngern erklärte er alles besonders.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Und an jenem Tage, als es Abend geworden war, spricht er zu ihnen: Laßt uns übersetzen an das jenseitige Ufer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Und als er die Volksmenge entlassen hatte, nehmen sie ihn, wie er war, in dem Schiffe mit. Aber auch andere Schiffe waren mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Und es erhebt sich ein heftiger Sturmwind, und die Wellen schlugen in das Schiff, so daß es sich schon füllte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Und er war im Hinterteil des Schiffes und schlief auf einem Kopfkissen; und sie wecken ihn auf und sprechen zu ihm: Lehrer, liegt dir nichts daran, daß wir umkommen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Und er wachte auf, bedrohte den Wind und sprach zu dem See: Schweig, verstumme! Und der Wind legte sich, und es ward eine große Stille.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Und er sprach zu ihnen: Was seid ihr so furchtsam? Wie, habt ihr keinen Glauben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Und sie fürchteten sich mit großer Furcht und sprachen zueinander: Wer ist denn dieser, daß auch der Wind und der See ihm gehorchen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Und sie kamen an das jenseitige Ufer des Sees in das Land der Gadarener.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Und als er aus dem Schiff gestiegen war, begegnete ihm alsbald aus den Grüften ein Mensch mit einem unreinen Geiste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'der seine Wohnung in den Grabstätten hatte; und selbst mit Ketten konnte keiner ihn binden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'da er oft mit Fußfesseln und mit Ketten gebunden gewesen, und die Ketten von ihm in Stücke zerrissen und die Fußfesseln zerrieben worden waren; und niemand vermochte ihn zu bändigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Und allezeit, Nacht und Tag, war er in den Grabstätten und auf den Bergen und schrie und zerschlug sich mit Steinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Als er aber Jesum von ferne sah, lief er und warf sich vor ihm nieder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'und mit lauter Stimme schreiend, sagt er: Was habe ich mit dir zu schaffen, Jesu, Sohn Gottes, des Höchsten? Ich beschwöre dich bei Gott, quäle mich nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Denn er sagte zu ihm: Fahre aus, du unreiner Geist, aus dem Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Und er fragte ihn: Was ist dein Name? Und er spricht zu ihm: Legion ist mein Name, denn wir sind viele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Und er bat ihn sehr, daß er sie nicht aus der Gegend fortschicken möchte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Es war aber daselbst an dem Berge eine große Herde Schweine, welche weidete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Und sie baten ihn und sprachen: Schicke uns in die Schweine, daß wir in sie fahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Und Jesus erlaubte es ihnen alsbald. Und die unreinen Geister fuhren aus und fuhren in die Schweine, und die Herde stürzte sich den Abhang hinab in den See, (bei zweitausend) und sie ertranken in dem See.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Und die Hüter flohen und verkündeten es in der Stadt und auf dem Lande; und sie gingen hinaus, um zu sehen, was geschehen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Und sie kommen zu Jesu und sehen den Besessenen sitzen, bekleidet und vernünftig, den, der die Legion gehabt hatte; und sie fürchteten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Und die es gesehen hatten, erzählten ihnen, wie dem Besessenen geschehen war, und das von den Schweinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Und sie fingen an, ihm zuzureden, aus ihren Grenzen wegzugehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Und als er in das Schiff stieg, bat ihn der Besessene, daß er bei ihm sein dürfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Und er ließ es ihm nicht zu, sondern spricht zu ihm: Gehe hin nach deinem Hause zu den Deinigen und verkünde ihnen, wieviel der Herr an dir getan, und wie er sich deiner erbarmt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Und er ging hin und fing an, in der Dekapolis auszurufen, wieviel Jesus an ihm getan hatte; und alle verwunderten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Und als Jesus in dem Schiffe wieder an das jenseitige Ufer hinübergefahren war, versammelte sich eine große Volksmenge zu ihm; und er war am See.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Und siehe, es kommt einer der Synagogenvorsteher, mit Namen Jairus, und als er ihn sieht, fällt er ihm zu Füßen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'und er bat ihn sehr und sprach: Mein Töchterlein liegt in den letzten Zügen; ich bitte, daß du kommest und ihr die Hände auflegest, auf daß sie gerettet werde und lebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Und er ging mit ihm, und eine große Volksmenge folgte ihm und drängte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Und ein Weib, das zwölf Jahre mit einem Blutfluß behaftet war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'und vieles erlitten hatte von vielen Ärzten und alle ihre Habe verwandt und keinen Nutzen davon gehabt hatte (es war vielmehr schlimmer mit ihr geworden), kam,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'als sie von Jesu gehört, in der Volksmenge von hinten und rührte sein Kleid an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'denn sie sprach: Wenn ich nur seine Kleider anrühre, so werde ich geheilt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Und alsbald vertrocknete der Quell ihres Blutes, und sie merkte am Leibe, daß sie von der Plage geheilt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Und alsbald erkannte Jesus in sich selbst die Kraft, die von ihm ausgegangen war, wandte sich um in der Volksmenge und sprach: Wer hat meine Kleider angerührt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Und seine Jünger sprachen zu ihm: Du siehst, daß die Volksmenge dich drängt, und du sprichst: Wer hat mich angerührt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Und er blickte umher, um sie zu sehen, die dieses getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Das Weib aber, voll Furcht und Zittern, wissend, was ihr geschehen war, kam und fiel vor ihm nieder und sagte ihm die ganze Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Er aber sprach zu ihr: Tochter, dein Glaube hat dich geheilt; gehe hin in Frieden und sei gesund von deiner Plage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Während er noch redete, kommen sie von dem Synagogenvorsteher und sagen: Deine Tochter ist gestorben; was bemühst du den Lehrer noch?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Als aber Jesus das Wort reden hörte, spricht er alsbald zu dem Synagogenvorsteher: Fürchte dich nicht; glaube nur.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Und er erlaubte niemand, ihn zu begleiten, außer Petrus und Jakobus und Johannes, dem Bruder des Jakobus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Und sie kommen in das Haus des Synagogenvorstehers, und er sieht ein Getümmel und Weinende und laut Heulende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Und als er eingetreten war, spricht er zu ihnen: Was lärmet und weinet ihr? Das Kind ist nicht gestorben, sondern es schläft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Und sie verlachten ihn. Als er aber alle hinausgetrieben hatte, nimmt er den Vater des Kindes und die Mutter und die bei ihm waren mit und geht hinein, wo das Kind lag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Und indem er das Kind bei der Hand ergriff, spricht er zu ihm: Talitha kumi! das ist verdolmetscht: Mägdlein, ich sage dir, stehe auf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Und alsbald stand das Mägdlein auf und wandelte umher, denn es war zwölf Jahre alt. Und sie erstaunten mit großem Erstaunen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Und er gebot ihnen dringend, daß niemand dies erführe, und hieß ihr zu essen geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Und er ging von dannen hinweg und kam in seine Vaterstadt, und seine Jünger folgten ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Und als es Sabbath geworden war, fing er an, in der Synagoge zu lehren; und viele, die zuhörten, erstaunten und sprachen: Woher diesem solches? Und was ist das für eine Weisheit, die ihm gegeben ist, und solche Wunderwerke geschehen durch seine Hände?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Ist dieser nicht der Zimmermann, der Sohn der Maria, und ein Bruder des Jakobus und Joses und Judas und Simon? Und sind nicht seine Schwestern hier bei uns?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Und sie ärgerten sich an ihm. Und Jesus sprach zu ihnen: Ein Prophet ist nicht ohne Ehre, außer in seiner Vaterstadt und unter seinen Verwandten und in seinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Und er konnte daselbst kein Wunderwerk tun, außer daß er einigen Schwachen die Hände auflegte und sie heilte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Und er verwunderte sich über ihren Unglauben. Und er ging durch die Dörfer ringsum und lehrte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Und er ruft die Zwölfe herzu; und er fing an, sie zu zwei und zwei auszusenden, und gab ihnen Gewalt über die unreinen Geister.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Und er gebot ihnen, daß sie nichts mit auf den Weg nehmen sollten, als nur einen Stab; keine Tasche, kein Brot, keine Münze in den Gürtel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'sondern Sandalen untergebunden; und ziehet nicht zwei Leibröcke an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Und er sprach zu ihnen: Wo irgend ihr in ein Haus eintretet, daselbst bleibet, bis ihr von dannen weggeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Und welcher Ort irgend euch nicht aufnehmen, und wo man euch nicht hören wird, von dannen gehet hinaus und schüttelt den Staub ab, der unter euren Füßen ist, ihnen zum Zeugnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Und sie gingen aus und predigten, daß die Buße tun sollten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'und sie trieben viele Dämonen aus und salbten viele Schwache mit Öl und heilten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Und der König Herodes hörte von ihm (denn sein Name war bekannt geworden) und sagte: Johannes der Täufer ist aus den Toten auferstanden, und darum wirken solche Kräfte in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Andere aber sagten: Es ist Elias; und andere sagten: Es ist ein Prophet, wie einer der Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Als aber Herodes es hörte, sagte er: Johannes, den ich enthauptet habe, dieser ist auferweckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Denn er, Herodes, hatte hingesandt und den Johannes greifen und ihn im Gefängnis binden lassen, um der Herodias willen, des Weibes seines Bruders Philippus, weil er sie geheiratet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Denn Johannes hatte dem Herodes gesagt: Es ist dir nicht erlaubt, das Weib deines Bruders zu haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Die Herodias aber trug es ihm nach und wollte ihn töten, und sie konnte nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'denn Herodes fürchtete den Johannes, da er wußte, daß er ein gerechter und heiliger Mann war, und er verwahrte ihn; und wenn er ihn gehört hatte, so tat er vieles, und er hörte ihn gern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Und als ein geeigneter Tag kam, als Herodes an seinem Geburtstage seinen Großen und den Obersten und den Vornehmsten von Galiläa ein Gastmahl machte, und ihre,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'der Herodias, Tochter hereinkam und tanzte, gefiel sie dem Herodes und denen, die mit zu Tische lagen. Und der König sprach zu dem Mägdlein: Bitte von mir, was irgend du willst, und ich werde es dir geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Und er schwur ihr: Was irgend du von mir bitten wirst, werde ich dir geben, bis zur Hälfte meines Reiches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Sie aber ging hinaus und sagte ihrer Mutter: Um was soll ich bitten? Diese aber sprach: Um das Haupt Johannes\' des Täufers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Und sie ging alsbald mit Eile zu dem König hinein und bat und sagte: Ich will, daß du mir sofort auf einer Schüssel das Haupt Johannes\' des Täufers gebest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Und der König wurde sehr betrübt; doch um der Eide und um derer willen, die mit zu Tische lagen, wollte er sie nicht zurückweisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Und alsbald schickte der König einen von der Leibwache und befahl, sein Haupt zu bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Der aber ging hin und enthauptete ihn im Gefängnis; und er brachte sein Haupt auf einer Schüssel und gab es dem Mägdlein, und das Mägdlein gab es ihrer Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Und als seine Jünger es hörten, kamen sie und hoben seinen Leichnam auf und legten ihn in eine Gruft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Und die Apostel versammeln sich zu Jesu; und die berichteten ihm alles, was sie getan und was sie gelehrt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Und er sprach zu ihnen: Kommet ihr selbst her an einen öden Ort besonders und ruhet ein wenig aus. Denn derer, die da kamen und gingen, waren viele, und sie fanden nicht einmal Zeit, um zu essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Und sie gingen hin in einem Schiffe an einen öden Ort besonders;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'und viele sahen sie wegfahren und erkannten sie, und liefen zu Fuß von allen Städten dorthin zusammen und kamen ihnen zuvor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Und als Jesus aus dem Schiffe trat, sah er eine große Volksmenge und wurde innerlich bewegt über sie; denn sie waren wie Schafe, die keinen Hirten haben. Und er fing an, sie vieles zu lehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Und als es schon spät am Tage war, traten seine Jünger zu ihm und sagen: Der Ort ist öde, und es ist schon spät am Tage;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'entlaß sie, auf daß sie hingehen auf das Land und in die Dörfer ringsum und sich Brote kaufen, denn sie haben nichts zu essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Er aber antwortete und sprach zu ihnen: Gebet ihr ihnen zu essen. Und sie sagen zu ihm: Sollen hingehen und für zweihundert Denare Brote kaufen und ihnen zu essen geben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Er aber spricht zu ihnen: Wie viele Brote habt ihr? Gehet hin und sehet. Und als sie es wußten, sagen sie: Fünf, und zwei Fische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Und er befahl ihnen, daß sie alle sich lagern ließen, in Gruppen, auf dem grünen Grase.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Und sie lagerten sich in Abteilungen zu je hundert und je fünfzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Und er nahm die fünf Brote und die zwei Fische, blickte auf gen Himmel, segnete und brach die Brote und gab sie seinen Jüngern, auf daß sie ihnen vorlegten; und die zwei Fische verteilte er unter alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Und sie aßen alle und wurden gesättigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'Und sie hoben auf an Brocken zwölf Handkörbe voll, und von den Fischen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Und es waren derer, welche von den Broten gegessen hatten, fünftausend Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Und alsbald nötigte er seine Jünger, in das Schiff zu steigen und an das jenseitige Ufer nach Bethsaida vorauszufahren, während er die Volksmenge entläßt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Und als er sie verabschiedet hatte, ging er hin auf den Berg, um zu beten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Und als es Abend geworden, war das Schiff mitten auf dem See, und er allein auf dem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Und als er sie beim Rudern Not leiden sah, denn der Wind war ihnen entgegen, kommt er um die vierte Nachtwache zu ihnen, wandelnd auf dem See; und er wollte an ihnen vorübergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Sie aber, als sie ihn auf dem See wandeln sahen, meinten, es sei ein Gespenst, und schrieen auf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'denn alle sahen ihn und wurden bestürzt. Und alsbald redete er mit ihnen und spricht zu ihnen: Seid gutes Mutes, ich bin\'s; fürchtet euch nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Und er stieg zu ihnen in das Schiff, und der Wind legte sich. Und sie erstaunten sehr über die Maßen bei sich selbst und verwunderten sich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'denn sie waren durch die Brote nicht verständig geworden, denn ihr Herz war verhärtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Und als sie hinübergefahren waren, kamen sie in das Land Genezareth und legten an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Und als sie aus dem Schiffe gestiegen waren, erkannten sie ihn alsbald');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'und liefen in jener ganzen Umgegend umher und fingen an, die Leidenden auf den Betten umherzutragen, wo sie hörten, daß er sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Und wo irgend er eintrat in Dörfer oder Städte oder aufs Land, legten sie die Kranken auf den Marktplätzen hin und baten ihn, daß sie nur die Quaste seines Kleides anrühren dürften; und so viele irgend ihn anrührten, wurden geheilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Und es versammeln sich zu ihm die Pharisäer und etliche der Schriftgelehrten, die von Jerusalem gekommen waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'und als sie etliche seiner Jünger mit unreinen, das ist ungewaschenen Händen Brot essen sahen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, '(denn die Pharisäer und alle Juden essen nicht, es sei denn, daß sie sich sorgfältig die Hände waschen, indem sie die Überlieferung der Ältesten halten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'und vom Markte kommend, essen sie nicht, es sei denn, daß sie sich waschen; und vieles andere ist, was sie zu halten überkommen haben: Waschungen der Becher und Krüge und ehernen Gefäße und Tischlager),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'sodann fragen ihn die Pharisäer und die Schriftgelehrten: Warum wandeln deine Jünger nicht nach der Überlieferung der Ältesten, sondern essen das Brot mit unreinen Händen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Er aber antwortete und sprach zu ihnen: Trefflich hat Jesaias über euch Heuchler geweissagt, wie geschrieben steht: \"Dieses Volk ehrt mich mit den Lippen, aber ihr Herz ist weit entfernt von mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Vergeblich aber verehren sie mich, indem sie als Lehren Menschengebote lehren.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Denn das Gebot Gottes aufgebend, haltet ihr die Überlieferung der Menschen: Waschungen der Krüge und Becher, und vieles andere dergleichen ähnliche tut ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Und er sprach zu ihnen: Trefflich hebet ihr das Gebot Gottes auf, auf daß ihr eure Überlieferung haltet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Denn Moses hat gesagt: \"Ehre deinen Vater und deine Mutter!\" und: \"Wer Vater oder Mutter flucht, soll des Todes sterben.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Ihr aber saget: Wenn ein Mensch zu dem Vater oder zu der Mutter spricht: Korban (das ist Gabe) sei das, was irgend dir von mir zunutze kommen könnte; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'und ihr lasset ihn so nichts mehr für seinen Vater oder seine Mutter tun,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'indem ihr das Wort Gottes ungültig machet durch eure Überlieferung, die ihr überliefert habt; und vieles dergleichen ähnliche tut ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Und als er die Volksmenge wieder herzugerufen hatte, sprach er zu ihnen: Höret mich alle und verstehet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Da ist nichts, was von außerhalb des Menschen in denselben eingeht, das ihn verunreinigen kann, sondern was von ihm ausgeht, das ist es, was den Menschen verunreinigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Wenn jemand Ohren hat zu hören, der höre!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Und als er von der Volksmenge weg in ein Haus eintrat, befragten ihn seine Jünger über das Gleichnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Und er spricht zu ihnen: Seid auch ihr so unverständig? Begreifet ihr nicht, daß alles, was von außerhalb in den Menschen eingeht, ihn nicht verunreinigen kann?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Denn es geht nicht in sein Herz hinein, sondern in den Bauch, und es geht heraus in den Abort, indem so alle Speisen gereinigt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Er sagte aber: Was aus dem Menschen ausgeht, das verunreinigt den Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Denn von innen aus dem Herzen der Menschen gehen hervor die schlechten Gedanken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Ehebruch, Hurerei, Mord, Dieberei, Habsucht, Bosheit, List, Ausschweifung, böses Auge, Lästerung, Hochmut, Torheit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'alle diese bösen Dinge gehen von innen heraus und verunreinigen den Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Und er stand auf von dannen und ging hin in das Gebiet von Tyrus und Sidon; und als er in ein Haus getreten war, wollte er, daß niemand es erfahre; und er konnte nicht verborgen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Aber alsbald hörte ein Weib von ihm, deren Töchterlein einen unreinen Geist hatte, kam und fiel nieder zu seinen Füßen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'das Weib aber war eine Griechin, eine Syrophönicierin von Geburt; und sie bat ihn, daß er den Dämon von ihrer Tochter austreibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Jesus aber sprach zu ihr: Laßt zuerst die Kinder gesättigt werden, denn es ist nicht schön, das Brot der Kinder zu nehmen und den Hündlein hinzuwerfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Sie aber antwortete und spricht zu ihm: Ja, Herr; denn es essen ja auch die Hündlein unter dem Tische von den Brosamen der Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Und er sprach zu ihr: Um dieses Wortes willen gehe hin; der Dämon ist von deiner Tochter ausgefahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Und sie ging hin nach ihrem Hause und fand den Dämon ausgefahren und die Tochter auf dem Bette liegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Und als er aus dem Gebiet von Tyrus und Sidon wieder weggegangen war, kam er an den See von Galiläa, mitten durch das Gebiet von Dekapolis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Und sie bringen einen Tauben zu ihm, der schwer redete, und bitten ihn, daß er ihm die Hand auflege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Und er nahm ihn von der Volksmenge weg besonders und legte seine Finger in seine Ohren; und er spützte und rührte seine Zunge an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'und, gen Himmel blickend, seufzte er und spricht zu ihm: Ephata! das ist: Werde aufgetan!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Und alsbald wurden seine Ohren aufgetan, und das Band seiner Zunge wurde gelöst, und er redete recht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Und er gebot ihnen, daß sie es niemand sagen sollten. Je mehr er es ihnen aber gebot, desto mehr machten sie es übermäßig kund;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'und sie erstaunten überaus und sprachen: Er hat alles wohlgemacht; er macht sowohl die Tauben hören, als auch die Stummen reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'In jenen Tagen, als wiederum eine große Volksmenge da war und nichts zu essen hatte, rief er seine Jünger herzu und spricht zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Ich bin innerlich bewegt über die Volksmenge, denn schon drei Tage weilen sie bei mir und haben nichts zu essen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'und wenn ich sie nach Hause entlassen, ohne daß sie gegessen haben, so werden sie auf dem Wege verschmachten; denn etliche von ihnen sind von ferne gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Und seine Jünger antworteten ihm: Woher wird jemand diese hier in der Einöde mit Brot sättigen können?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Und er fragte sie: Wie viele Brote habt ihr? Sie aber sagten: Sieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Und er gebot der Volksmenge, sich auf der Erde zu lagern. Und er nahm die sieben Brote, dankte und brach sie und gab sie den Jüngern, auf daß sie vorlegten; und sie legten der Volksmenge vor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Und sie hatten einige kleine Fische; und als er sie gesegnet hatte, hieß er auch diese vorlegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Sie aßen aber und wurden gesättigt; und sie hoben auf, was an Brocken übrigblieb, sieben Körbe voll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Es waren aber derer, welche gegessen hatten, bei viertausend; und er entließ sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Und alsbald stieg er mit seinen Jüngern in das Schiff und kam in die Gegenden von Dalmanutha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Und die Pharisäer kamen heraus und fingen an, mit ihm zu streiten, indem sie, um ihn zu versuchen, ein Zeichen vom Himmel von ihm begehrten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Und in seinem Geiste tief seufzend, spricht er: Was begehrt dieses Geschlecht ein Zeichen? Wahrlich, ich sage euch: Wenn diesem Geschlecht ein Zeichen gegeben werden wird!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Und er ließ sie, stieg wieder in das Schiff und fuhr an das jenseitige Ufer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Und sie vergaßen Brote mitzunehmen, und hatten nichts bei sich auf dem Schiffe als nur ein Brot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Und er gebot ihnen und sprach: Sehet zu, hütet euch vor dem Sauerteig der Pharisäer und dem Sauerteig des Herodes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Und sie überlegten miteinander und sprachen: Weil wir keine Brote haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Und als Jesus es erkannte, spricht er zu ihnen: Was überleget ihr, weil ihr keine Brote habt? Begreifet ihr noch nicht und verstehet auch nicht? Habt ihr euer Herz noch verhärtet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Augen habt ihr und sehet nicht? Und Ohren habt ihr und höret nicht? Und erinnert ihr euch nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Als ich die fünf Brote unter die fünftausend brach, wie viele Handkörbe voll Brocken hobet ihr auf? Sie sagen zu ihm: Zwölf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'Als aber die sieben unter die viertausend, wie viele Körbe, mit Brocken gefüllt, hobet ihr auf? Sie aber sagten: Sieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Und er sprach zu ihnen: Wie, verstehet ihr noch nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Und er kommt nach Bethsaida; und sie bringen ihm einen Blinden und bitten ihn, daß er ihn anrühre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Und er faßte den Blinden bei der Hand und führte ihn aus dem Dorfe hinaus; und als er in seine Augen gespützt hatte, legte er ihm die Hände auf und fragte ihn, ob er etwas sehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Und aufblickend sprach er: Ich sehe die Menschen, denn ich gewahre solche, die wie Bäume umherwandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Dann legte er wiederum die Hände auf seine Augen, und er sah deutlich, und er war wiederhergestellt und sah alles klar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Und er schickte ihn nach seinem Hause und sprach: Geh nicht in das Dorf, sage es auch niemand im Dorfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Und Jesus ging hinaus und seine Jünger in die Dörfer von Cäsarea Philippi. Und auf dem Wege fragte er seine Jünger und sprach zu ihnen: Wer sagen die Menschen, daß ich sei?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Sie aber antworteten ihm und sagten: Johannes der Täufer; und andere: Elias; andere aber: einer der Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Und er fragte sie: Ihr aber, wer saget ihr, daß ich sei? Petrus aber antwortete und spricht zu ihm: Du bist der Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Und er bedrohte sie, daß sie niemand von ihm sagen sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Und er fing an, sie zu lehren, daß der Sohn des Menschen vieles leiden und verworfen werden müsse von den Ältesten und Hohenpriestern und Schriftgelehrten, und daß er getötet werden und nach drei Tagen auferstehen müsse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Und er redete das Wort öffentlich. Und Petrus nahm ihn zu sich und fing an ihn zu strafen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Er aber wandte sich um, und als er seine Jünger sah, strafte er den Petrus und sagte: Geh hinter mich, Satan! Denn du sinnst nicht auf das, was Gottes, sondern auf das was der Menschen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Und als er die Volksmenge samt seinen Jüngern herzugerufen hatte, sprach er zu ihnen: Wer irgend mir nachkommen will, verleugne sich selbst und nehme sein Kreuz auf und folge mir nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Denn wer irgend sein Leben erretten will, wird es verlieren; wer aber irgend sein Leben verliert um meinet-und des Evangeliums willen, wird es erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Denn was wird es einem Menschen nützen, wenn er die ganze Welt gewönne und seine Seele einbüßte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Denn was wird ein Mensch als Lösegeld geben für seine Seele?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Denn wer irgend sich meiner und meiner Worte schämt unter diesem ehebrecherischen und sündigen Geschlecht, dessen wird sich auch der Sohn des Menschen schämen, wenn er kommen wird in der Herrlichkeit seines Vaters mit den heiligen Engeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Und er sprach zu ihnen: Wahrlich, ich sage euch: Es sind etliche von denen, die hier stehen, welche den Tod nicht schmecken werden, bis sie das Reich Gottes, in Macht gekommen, gesehen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Und nach sechs Tagen nimmt Jesus den Petrus und den Jakobus und Johannes mit und führt sie auf einen hohen Berg besonders allein. Und er wurde vor ihnen umgestaltet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'und seine Kleider wurden glänzend, sehr weiß wie Schnee, wie kein Walker auf der Erde weiß machen kann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Und es erschien ihnen Elias mit Moses, und sie unterredeten sich mit Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Und Petrus hob an und spricht zu Jesu: Rabbi, es ist gut, daß wir hier sind; und laß uns drei Hütten machen, dir eine und Moses eine und Elias eine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Denn er wußte nicht, was er sagen sollte, denn sie waren voll Furcht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Und es kam eine Wolke, welche sie überschattete; und eine Stimme kam aus der Wolke: Dieser ist mein geliebter Sohn, ihn höret.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Und plötzlich, als sie sich umblickten, sahen sie niemand mehr, sondern Jesum allein bei sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Als sie aber von dem Berge herabstiegen, gebot er ihnen, daß sie niemand erzählen sollten, was sie gesehen hatten, außer wenn der Sohn des Menschen aus den Toten auferstanden wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Und sie behielten das Wort, indem sie sich untereinander befragten: Was ist das: aus den Toten auferstehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Und sie fragten ihn und sprachen: Was sagen die Schriftgelehrten, daß Elias zuerst kommen müsse?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Er aber antwortete und sprach zu ihnen: Elias zwar kommt zuerst und stellt alle Dinge wieder her; und wie über den Sohn des Menschen geschrieben steht, daß er vieles leiden und für nichts geachtet werden soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Aber ich sage euch, daß auch Elias gekommen ist, und sie haben ihm getan, was irgend sie wollten, so wie über ihn geschrieben steht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Und als er zu den Jüngern kam, sah er eine große Volksmenge um sie her, und Schriftgelehrte, die sich mit ihnen stritten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Und alsbald, als die ganze Volksmenge ihn sah, war sie sehr erstaunt; und sie liefen herzu und begrüßten ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Und er fragte sie: Worüber streitet ihr euch mit ihnen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Und einer aus der Volksmenge antwortete ihm: Lehrer, ich habe meinen Sohn zu dir gebracht, der einen stummen Geist hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'und wo immer er ihn ergreift, reißt er ihn, und er schäumt und knirscht mit seinen Zähnen, und er magert ab. Und ich sprach zu deinen Jüngern, daß sie ihn austreiben möchten, und sie vermochten es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Er aber antwortet ihnen und spricht: O ungläubiges Geschlecht! Bis wann soll ich bei euch sein? Bis wann soll ich euch ertragen? Bringet ihn zu mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Und sie brachten ihn zu ihm. Und als er ihn sah, zerrte ihn alsbald der Geist; und er fiel zur Erde und wälzte sich schäumend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Und er fragte seinen Vater: Wie lange Zeit ist es, daß ihm dies geschehen ist? Er aber sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'Von Kindheit an; und oftmals hat er ihn sogar ins Feuer geworfen und ins Wasser, auf daß er ihn umbrächte; aber wenn du etwas kannst, so erbarme dich unser und hilf uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Jesus aber sprach zu ihm: Das \"wenn du kannst\" ist, wenn du glauben kannst; dem Glaubenden ist alles möglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Und alsbald rief der Vater des Kindleins und sagte mit Tränen: Ich glaube; hilf meinem Unglauben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Als aber Jesus sah, daß eine Volksmenge zusammenlief, bedrohte er den unreinen Geist, indem er zu ihm sprach: Du stummer und tauber Geist, ich gebiete dir: fahre von ihm aus und fahre nicht mehr in ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Und schreiend und ihn sehr zerrend fuhr er aus; und er wurde wie tot, so daß die meisten sagten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Er ist gestorben. Jesus aber nahm ihn bei der Hand und richtete ihn empor; und er stand auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Und als er in ein Haus getreten war, fragten ihn seine Jünger besonders: Warum haben wir ihn nicht austreiben können?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Und er sprach zu ihnen: Diese Art kann durch nichts ausfahren, als nur durch Gebet und Fasten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Und sie gingen von dannen hinweg und zogen durch Galiläa; und er wollte nicht, daß es jemand erführe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Denn er lehrte seine Jünger und sprach zu ihnen: Der Sohn des Menschen wird überliefert in der Menschen Hände, und sie werden ihn töten; und nachdem er getötet worden ist, wird er nach drei Tagen auferstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Sie aber verstanden die Rede nicht und fürchteten sich, ihn zu fragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Und er kam nach Kapernaum, und als er in dem Hause war, fragte er sie: Was habt ihr auf dem Wege verhandelt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Sie aber schwiegen; denn sie hatten sich auf dem Wege untereinander besprochen, wer der Größte sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Und nachdem er sich niedergesetzt hatte, rief er die Zwölfe; und er spricht zu ihnen: Wenn jemand der Erste sein will, so soll er der Letzte von allen und aller Diener sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Und er nahm ein Kindlein und stellte es in ihre Mitte; und als er es in seine Arme genommen hatte, sprach er zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Wer irgend eines solcher Kindlein aufnehmen wird in meinem Namen, nimmt mich auf; und wer irgend mich aufnehmen wird, nimmt nicht mich auf, sondern den, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Johannes aber antwortete ihm und sprach: Lehrer, wir sahen jemand, der uns nicht nachfolgt, Dämonen austreiben in deinem Namen; und wir wehrten ihm, weil er uns nicht nachfolgt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Jesus aber sprach: Wehret ihm nicht, denn es ist niemand, der ein Wunderwerk in meinem Namen tun und bald übel von mir zu reden vermögen wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'denn wer nicht wider uns ist, ist für uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Denn wer irgend euch mit einem Becher Wassers tränken wird in meinem Namen, weil ihr Christi seid, wahrlich, ich sage euch: er wird seinen Lohn nicht verlieren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Und wer irgend einen der Kleinen, die an mich glauben, ärgern wird, dem wäre besser, wenn ein Mühlstein um seinen Hals gelegt, und er ins Meer geworfen würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Und wenn deine Hand dich ärgert, so haue sie ab. Es ist dir besser, als Krüppel in das Leben einzugehen, als mit zwei Händen in die Hölle hinabzufahren, in das unauslöschliche Feuer,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Und wenn dein Fuß dich ärgert, so haue ihn ab. Es ist dir besser, lahm in das Leben einzugehen, als mit zwei Füßen in die Hölle geworfen zu werden, in das unauslöschliche Feuer,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Und wenn dein Auge dich ärgert, so wirf es weg. Es ist dir besser, einäugig in das Reich Gottes einzugehen, als mit zwei Augen in die Hölle des Feuers geworfen zu werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Denn jeder wird mit Feuer gesalzen werden, und jedes Schlachtopfer wird mit Salz gesalzen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Das Salz ist gut; wenn aber das Salz unsalzig geworden ist, womit wollt ihr es würzen? Habt Salz in euch selbst und seid in Frieden untereinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Und er stand auf von dannen und kommt in das Gebiet von Judäa und von jenseit des Jordan. Und wiederum kommen Volksmengen zu ihm zusammen, und wie er gewohnt war, lehrte er sie wiederum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Und es traten Pharisäer herzu und fragten ihn: Ist es einem Manne erlaubt, sein Weib zu entlassen? indem sie ihn versuchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Er aber antwortete und sprach zu ihnen: Was hat euch Moses geboten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Sie aber sagten: Moses hat gestattet, einen Scheidebrief zu schreiben und zu entlassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Und Jesus antwortete und sprach zu ihnen: Wegen eurer Herzenshärtigkeit hat er euch dieses Gebot geschrieben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'von Anfang der Schöpfung aber schuf Gott sie Mann und Weib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, '\"Um deswillen wird ein Mensch seinen Vater und seine Mutter verlassen und seinem Weibe anhangen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'und es werden die zwei ein Fleisch sein\"; also sind sie nicht mehr zwei, sondern ein Fleisch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Was nun Gott zusammengefügt hat, soll der Mensch nicht scheiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Und in dem Hause befragten ihn die Jünger wiederum hierüber; und er spricht zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Wer irgend sein Weib entlassen und eine andere heiraten wird, begeht Ehebruch gegen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Und wenn ein Weib ihren Mann entlassen und einen anderen heiraten wird, so begeht sie Ehebruch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Und sie brachten Kindlein zu ihm, auf daß er sie anrühre. Die Jünger aber verwiesen es denen, welche sie herzubrachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Als aber Jesus es sah, wurde er unwillig und sprach zu ihnen: Lasset die Kindlein zu mir kommen und wehret ihnen nicht, denn solcher ist das Reich Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Wahrlich, ich sage euch: Wer irgend das Reich Gottes nicht aufnehmen wird wie ein Kindlein, wird nicht in dasselbe eingehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Und er nahm sie in seine Arme, legte die Hände auf sie und segnete sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Und als er auf den Weg hinausging, lief einer herzu, fiel vor ihm auf die Knie und fragte ihn: Guter Lehrer, was soll ich tun, auf daß ich ewiges Leben ererbe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Jesus aber sprach zu ihm: Was heißest du mich gut? Niemand ist gut als nur Einer, Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Die Gebote weißt du: \"Du sollst nicht ehebrechen; du sollst nicht töten; du sollst nicht stehlen; du sollst nicht falsches Zeugnis reden; du sollst nichts vorenthalten; ehre deinen Vater und deine Mutter.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Er aber antwortete und sprach zu ihm: Lehrer, dieses alles habe ich beobachtet von meiner Jugend an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Jesus aber blickte ihn an, liebte ihn und sprach zu ihm: Eines fehlt dir; gehe hin, verkaufe, was irgend du hast, und gib es den Armen, und du wirst einen Schatz im Himmel haben, und komm, folge mir nach, das Kreuz aufnehmend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Er aber ging, betrübt über das Wort, traurig hinweg, denn er hatte viele Güter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Und Jesus blickte umher und spricht zu seinen Jüngern: Wie schwerlich werden die, welche Güter haben, in das Reich Gottes eingehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Die Jünger aber entsetzten sich über seine Worte. Jesus aber antwortete wiederum und spricht zu ihnen: Kinder, wie schwer ist es, daß die, welche auf Güter vertrauen, in das Reich Gottes eingehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Es ist leichter, daß ein Kamel durch das Öhr der Nadel gehe, als daß ein Reicher in das Reich Gottes eingehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Sie aber waren über die Maßen erstaunt und sprachen zueinander: Und wer kann dann errettet werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Jesus aber sah sie an und spricht: Bei Menschen ist es unmöglich, aber nicht bei Gott; denn bei Gott sind alle Dinge möglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Petrus fing an, zu ihm zu sagen: Siehe, wir haben alles verlassen und sind dir nachgefolgt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jesus antwortete und sprach: Wahrlich, ich sage euch: Da ist niemand, der Haus oder Brüder oder Schwestern oder Vater oder Mutter oder Weib oder Kinder oder Äcker verlassen hat um meinet-und um des Evangeliums willen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'der nicht hundertfältig empfange, jetzt in dieser Zeit Häuser und Brüder und Schwestern und Mütter und Kinder und Äcker, mit Verfolgungen, und in dem kommenden Zeitalter ewiges Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Aber viele Erste werden Letzte, und Letzte Erste sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Sie waren aber auf dem Wege hinauf nach Jerusalem, und Jesus ging vor ihnen her; und sie entsetzten sich und, indem sie nachfolgten, fürchteten sie sich. Und er nahm wiederum die Zwölfe zu sich und fing an, ihnen zu sagen, was ihm widerfahren sollte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Siehe, wir gehen hinauf nach Jerusalem, und der Sohn des Menschen wird den Hohenpriestern und den Schriftgelehrten überliefert werden; und sie werden ihn zum Tode verurteilen und werden ihn den Nationen überliefern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'und sie werden ihn verspotten und ihn geißeln und ihn anspeien und ihn töten; und nach drei Tagen wird er auferstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Und es treten zu ihm Jakobus und Johannes, die Söhne des Zebedäus, und sagen zu ihm: Lehrer, wir wollen, daß du uns tuest, um was irgend wir dich bitten werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Er aber sprach zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Was wollt ihr, daß ich euch tun soll? Sie aber sprachen zu ihm: Gib uns, daß wir einer zu deiner Rechten und einer zu deiner Linken sitzen mögen in deiner Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Jesus aber sprach zu ihnen: Ihr wisset nicht, um was ihr bittet. Könnt ihr den Kelch trinken, den ich trinke, oder mit der Taufe getauft werden, mit der ich getauft werde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Sie aber sprachen zu ihm: Wir können es. Jesus aber sprach zu ihnen: Den Kelch, den ich trinke, werdet ihr trinken, und mit der Taufe, mit der ich getauft werde, werdet ihr getauft werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'aber das Sitzen zu meiner Rechten oder Linken steht nicht bei mir zu vergeben, sondern ist für die, welchen es bereitet ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Und als die Zehn es hörten, fingen sie an, unwillig zu werden über Jakobus und Johannes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Und als Jesus sie herzugerufen hatte, spricht er zu ihnen: Ihr wisset, daß die, welche als Regenten der Nationen gelten, über dieselben herrschen, und ihre Großen Gewalt über sie üben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Aber also ist es nicht unter euch; sondern wer irgend unter euch groß werden will, soll euer Diener sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'und wer irgend von euch der Erste sein will, soll aller Knecht sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Denn auch der Sohn des Menschen ist nicht gekommen, um bedient zu werden, sondern um zu dienen und sein Leben zu geben als Lösegeld für viele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Und sie kommen nach Jericho. Und als er aus Jericho ging mit seinen Jüngern und einer zahlreichen Volksmenge, saß der Sohn des Timäus, Bartimäus, der Blinde, bettelnd am Wege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Und als er hörte, daß es Jesus, der Nazarener sei, fing er an zu schreien und zu sagen: O Sohn Davids, Jesu, erbarme dich meiner!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Und viele bedrohten ihn, daß er schweigen solle; er aber schrie um so mehr: Sohn Davids, erbarme dich meiner!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Und Jesus blieb stehen und hieß ihn rufen. Und sie rufen den Blinden und sagen zu ihm: Sei gutes Mutes; stehe auf, er ruft dich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Er aber warf sein Gewand ab, sprang auf und kam zu Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Und Jesus hob an und spricht zu ihm: Was willst du, daß ich dir tun soll? Der Blinde aber sprach zu ihm: Rabbuni, daß ich sehend werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Jesus aber sprach zu ihm: Gehe hin, dein Glaube hat dich geheilt. Und alsbald wurde er sehend und folgte ihm nach auf dem Wege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Und als sie Jerusalem, Bethphage und Bethanien nahen, gegen den Ölberg hin, sendet er zwei seiner Jünger und spricht zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'Gehet hin in das Dorf, das euch gegenüber liegt; und alsbald, wenn ihr in dasselbe kommet, werdet ihr ein Füllen angebunden finden, auf welchem kein Mensch je gesessen hat; bindet es los und führet es her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Und wenn jemand zu euch sagt: Warum tut ihr dies? so saget: Der Herr bedarf seiner; und alsbald sendet er es hierher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Sie aber gingen hin und fanden ein Füllen angebunden an der Tür draußen auf dem Wege; und sie binden es los.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Und etliche von denen, die daselbst standen, sprachen zu ihnen: Was tut ihr, daß ihr das Füllen losbindet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Sie aber sprachen zu ihnen, wie Jesus gesagt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Und sie ließen sie. Und sie führten das Füllen zu Jesu und legten ihre Kleider darauf, und er setzte sich auf dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Viele aber breiteten ihre Kleider aus auf den Weg; andere hieben Zweige von den Bäumen und streuten sie auf den Weg;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'und die vorangingen und nachfolgten, riefen: Hosanna! Gepriesen sei, der da kommt im Namen des Herrn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Gepriesen sei das kommende Reich unseres Vaters David! Hosanna in der Höhe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Und er zog in Jerusalem ein und ging in den Tempel; und als er über alles umhergeblickt hatte, ging er, da es schon spät an der Zeit war, mit den Zwölfen hinaus nach Bethanien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Und des folgenden Tages, als sie von Bethanien weggegangen waren, hungerte ihn. Und als er von ferne einen Feigenbaum sah,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'der Blätter hatte, ging er hin, ob er vielleicht etwas an ihm fände; und als er zu ihm kam, fand er nichts als nur Blätter, denn es war nicht die Zeit der Feigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Und er hob an und sprach zu ihm: Nimmermehr esse jemand Frucht von dir in Ewigkeit! Und seine Jünger hörten es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Und sie kommen nach Jerusalem. Und als er in den Tempel eingetreten war, fing er an auszutreiben, die im Tempel verkauften und kauften; und die Tische der Wechsler und die Sitze der Taubenverkäufer stieß er um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'Und er erlaubte nicht, daß jemand ein Gefäß durch den Tempel trug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Und er lehrte und sprach zu ihnen: Steht nicht geschrieben: \"Mein Haus wird ein Bethaus genannt werden für alle Nationen\"? \"Ihr aber habt es zu einer Räuberhöhle gemacht\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Und die Hohenpriester und die Schriftgelehrten hörten es und suchten, wie sie ihn umbrächten; denn sie fürchteten ihn, weil die ganze Volksmenge sehr erstaunt war über seine Lehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Und wenn es Abend wurde, ging er zur Stadt hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Und als sie frühmorgens vorbeigingen, sahen sie den Feigenbaum verdorrt von den Wurzeln an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Und Petrus erinnerte sich und spricht zu ihm: Rabbi, siehe, der Feigenbaum, den du verfluchtest, ist verdorrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Und Jesus antwortet und spricht zu ihnen: Habet Glauben an Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Wahrlich, ich sage euch: Wer irgend zu diesem Berge sagen wird: Werde aufgehoben und ins Meer geworfen! und nicht zweifeln wird in seinem Herzen, sondern glauben, daß geschieht, was er sagt, dem wird werden was irgend er sagen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Darum sage ich euch: Alles, um was irgend ihr betet und bittet, glaubet, daß ihr es empfanget, und es wird euch werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Und wenn ihr im Gebet dastehet, so vergebet, wenn ihr etwas wider jemand habt, auf daß auch euer Vater, der in den Himmeln ist, euch eure Übertretungen vergebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Wenn ihr aber nicht vergebet, so wird euer Vater, der in den Himmeln ist, auch eure Übertretungen nicht vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Und sie kommen wiederum nach Jerusalem. Und als er in dem Tempel umherwandelte, kommen die Hohenpriester und die Schriftgelehrten und');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'die Ältesten zu ihm und sagen zu ihm: In welchem Recht tust du diese Dinge? Und wer hat dir dieses Recht gegeben, daß du diese Dinge tust?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Jesus aber antwortete und sprach zu ihnen: Auch ich will euch ein Wort fragen, und antwortet mir, und ich werde euch sagen, in welchem Recht ich diese Dinge tue:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Die Taufe Johannes\', war sie vom Himmel oder von Menschen? Antwortet mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Und sie überlegten miteinander und sprachen: Wenn wir sagen: Vom Himmel, so wird er sagen: Warum habt ihr ihm denn nicht geglaubt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Sagen wir aber: Von Menschen... sie fürchteten das Volk; denn alle hielten von Johannes, daß er wirklich ein Prophet war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Und sie antworten und sagen zu Jesu: Wir wissen es nicht. Und Jesus antwortet und spricht zu ihnen: So sage ich auch euch nicht, in welchem Recht ich diese Dinge tue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Und er fing an, in Gleichnissen zu ihnen zu reden: Ein Mensch pflanzte einen Weinberg und setzte einen Zaun um denselben und grub einen Keltertrog und baute einen Turm; und er verdingte ihn an Weingärtner und reiste außer Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Und er sandte zur bestimmten Zeit einen Knecht zu den Weingärtnern, auf daß er von den Weingärtnern von der Frucht des Weinbergs empfinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Sie aber nahmen ihn, schlugen ihn und sandten ihn leer fort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Und wiederum sandte er einen anderen Knecht zu ihnen; und den verwundeten sie durch Steinwürfe am Kopf und sandten ihn entehrt fort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Und wiederum sandte er einen anderen, und den töteten sie; und viele andere: die einen schlugen sie, die anderen töteten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Da er nun noch einen geliebten Sohn hatte, sandte er auch ihn, den letzten, zu ihnen, indem er sprach: Sie werden sich vor meinem Sohne scheuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Jene Weingärtner aber sprachen zueinander: Dieser ist der Erbe; kommt, laßt uns ihn töten, und das Erbe wird unser sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Und sie nahmen ihn und töteten ihn und warfen ihn zum Weinberg hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Was wird nun der Herr des Weinbergs tun? Er wird kommen und die Weingärtner umbringen und den Weinberg anderen geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Habt ihr nicht auch diese Schrift gelesen: \"Der Stein, den die Bauleute verworfen haben, dieser ist zum Eckstein geworden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'von dem Herrn her ist er dies geworden, und er ist wunderbar in unseren Augen\"?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Und sie suchten ihn zu greifen, und sie fürchteten die Volksmenge; denn sie erkannten, daß er das Gleichnis auf sie geredet hatte. Und sie ließen ihn und gingen hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Und sie senden etliche der Pharisäer und die Herodianer zu ihm, auf daß sie ihn in der Rede fingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Sie aber kommen und sagen zu ihm: Lehrer, wir wissen, daß du wahrhaftig bist und dich um niemand kümmerst; denn du siehst nicht auf die Person der Menschen, sondern lehrst den Weg Gottes in Wahrheit; ist es erlaubt, dem Kaiser Steuer zu geben oder nicht? Sollen wir sie geben, oder sollen wir sie nicht geben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Da er aber ihre Heuchelei kannte, sprach er zu ihnen: Was versuchet ihr mich? Bringet mir einen Denar, auf daß ich ihn sehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Sie aber brachten ihn. Und er spricht zu ihnen: Wessen ist dieses Bild und die Überschrift? Und sie sprachen zu ihm: Des Kaisers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Und Jesus antwortete und sprach zu ihnen: So gebet dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist. Und sie verwunderten sich über ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Und es kommen Sadducäer zu ihm, welche sagen, es gebe keine Auferstehung; und sie fragten ihn und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Lehrer, Moses hat uns geschrieben: Wenn jemandes Bruder stirbt und hinterläßt ein Weib und hinterläßt keine Kinder, daß sein Bruder sein Weib nehme und seinem Bruder Samen erwecke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Es waren sieben Brüder. Und der erste nahm ein Weib; und als er starb, hinterließ er keinen Samen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'und der zweite nahm sie und starb, und auch er hinterließ keinen Samen; und der dritte desgleichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Und die sieben nahmen sie und hinterließen keinen Samen. Am letzten von allen starb auch das Weib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'In der Auferstehung, wenn sie auferstehen werden, wessen Weib von ihnen wird sie sein? Denn die sieben haben sie zum Weibe gehabt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Und Jesus antwortete und sprach zu ihnen: Irret ihr deshalb nicht, indem ihr die Schriften nicht kennet, noch die Kraft Gottes?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Denn wenn sie aus den Toten auferstehen, heiraten sie nicht, noch werden sie verheiratet, sondern sie sind wie Engel in den Himmeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Was aber die Toten betrifft, daß sie auferstehen, habt ihr nicht in dem Buche Moses\' gelesen, \"in dem Dornbusch\", wie Gott zu ihm redete und sprach: \"Ich bin der Gott Abrahams und der Gott Isaaks und der Gott Jakobs\"?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Er ist nicht der Gott der Toten, sondern der Lebendigen. Ihr irret also sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Und einer der Schriftgelehrten, der gehört hatte, wie sie sich befragten, trat herzu, und als er wahrnahm, daß er ihnen gut geantwortet hatte, fragte er ihn: Welches Gebot ist das erste von allen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Jesus aber antwortete ihm: Das erste Gebot von allen ist: \"Höre, Israel: der Herr, unser Gott, ist ein einiger Herr;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'und du sollst den Herrn, deinen Gott, lieben aus deinem ganzen Herzen und aus deiner ganzen Seele und aus deinem ganzen Verstande und aus deiner ganzen Kraft\". Dies ist das erste Gebot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Und das zweite, ihm gleiche, ist dieses: \"Du sollst deinen Nächsten lieben wie dich selbst\". Größer als diese ist kein anderes Gebot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Und der Schriftgelehrte sprach zu ihm: Recht, Lehrer, du hast nach der Wahrheit geredet; denn er ist ein einiger Gott, und da ist kein anderer außer ihm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'und ihn lieben aus ganzem Herzen und aus ganzem Verständnis und aus ganzer Seele und aus ganzer Kraft, und den Nächsten lieben wie sich selbst, ist mehr als alle Brandopfer und Schlachtopfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Und als Jesus sah, daß er verständig geantwortet hatte, sprach er zu ihm: Du bist nicht fern vom Reiche Gottes. Und hinfort wagte niemand ihn zu befragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Und Jesus hob an und sprach, als er im Tempel lehrte: Wie sagen die Schriftgelehrten, daß der Christus Davids Sohn sei?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Denn David selbst hat in dem Heiligen Geiste gesagt: \"Der Herr sprach zu meinem Herrn: Setze dich zu meiner Rechten, bis ich deine Feinde lege zum Schemel deiner Füße\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'David selbst also nennt ihn Herr, und woher ist er sein Sohn? Und die große Menge des Volkes hörte ihn gern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Und er sprach zu ihnen in seiner Lehre: Hütet euch vor den Schriftgelehrten, die in langen Gewändern einhergehen wollen und die Begrüßungen auf den Märkten lieben');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'und die ersten Sitze in den Synagogen und die ersten Plätze bei den Gastmählern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'welche die Häuser der Witwen verschlingen und zum Schein lange Gebete halten. Diese werden ein schwereres Gericht empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Und Jesus setzte sich dem Schatzkasten gegenüber und sah, wie die Volksmenge Geld in den Schatzkasten legte; und viele Reiche legten viel ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Und eine arme Witwe kam und legte zwei Scherflein ein, das ist ein Pfennig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Und er rief seine Jünger herzu und sprach zu ihnen: Wahrlich, ich sage euch: Diese arme Witwe hat mehr eingelegt als alle, die in den Schatzkasten eingelegt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Denn alle haben von ihrem Überfluß eingelegt; diese aber hat von ihrem Mangel, alles was sie hatte, eingelegt, ihren ganzen Lebensunterhalt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Und als er aus dem Tempel heraustrat, sagte einer seiner Jünger zu ihm: Lehrer, siehe, was für Steine und was für Gebäude!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Und Jesus antwortete und sprach zu ihm: Siehst du diese großen Gebäude? Es wird nicht ein Stein auf dem anderen gelassen werden, der nicht abgebrochen werden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Und als er auf dem Ölberge saß, dem Tempel gegenüber, fragten ihn Petrus und Jakobus und Johannes und Andreas besonders:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Sage uns, wann wird dieses sein, und was ist das Zeichen, wann dieses alles vollendet werden soll?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Jesus aber antwortete ihnen und fing an zu reden: Sehet zu, daß euch niemand verführe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Denn viele werden unter meinem Namen kommen und sagen: Ich bin\'s! -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'und sie werden viele verführen. Wenn ihr aber von Kriegen und Kriegsgerüchten hören werdet, so erschrecket nicht; denn dies muß geschehen, aber es ist noch nicht das Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Denn es wird sich Nation wider Nation erheben und Königreich wider Königreich; und es werden Erdbeben sein an verschiedenen Orten, und es werden Hungersnöte und Unruhen sein. Dies sind die Anfänge der Wehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Ihr aber, sehet auf euch selbst, denn sie werden euch an Synedrien und an Synagogen überliefern; ihr werdet geschlagen und vor Statthalter und Könige gestellt werden um meinetwillen, ihnen zu einem Zeugnis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'und allen Nationen muß zuvor das Evangelium gepredigt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Wenn sie euch aber hinführen, um euch zu überliefern, so sorget nicht zuvor, was ihr reden sollt, bereitet euch auch nicht vor sondern was irgend euch in jener Stunde gegeben wird, das redet; denn nicht ihr seid die Redenden, sondern der Heilige Geist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Es wird aber der Bruder den Bruder zum Tode überliefern, und der Vater das Kind; und Kinder werden sich erheben wider die Eltern und sie zum Tode bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Und ihr werdet von allen gehaßt werden um meines Namens willen; wer aber ausharrt bis ans Ende, dieser wird errettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Wenn ihr aber den Greuel der Verwüstung stehen sehet, wo er nicht sollte (wer es liest, der beachte es), daß alsdann, die in Judäa sind, auf die Berge fliehen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'und wer auf dem Dache ist, nicht in das Haus hinabsteige, noch hineingehe, um etwas aus seinem Hause zu holen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'und wer auf dem Felde ist, sich nicht zurückwende, um sein Kleid zu holen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Wehe aber den Schwangeren und den Säugenden in jenen Tagen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Betet aber, daß es nicht im Winter geschehe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'denn jene Tage werden eine Drangsal sein, wie dergleichen von Anfang der Schöpfung, welche Gott schuf, bis jetzthin nicht gewesen ist und nicht sein wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Und wenn nicht der Herr die Tage verkürzt hätte, so würde kein Fleisch gerettet werden; aber um der Auserwählten willen, die er auserwählt hat, hat er die Tage verkürzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Und alsdann, wenn jemand zu euch sagt: Siehe, hier ist der Christus! oder: Siehe dort! so glaubet nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Denn es werden falsche Christi und falsche Propheten aufstehen und werden Zeichen und Wunder tun, um wenn möglich auch die Auserwählten zu verführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Ihr aber sehet zu! Siehe, ich habe euch alles vorhergesagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Aber in jenen Tagen, nach jener Drangsal, wird die Sonne verfinstert werden und der Mond seinen Schein nicht geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'und die Sterne des Himmels werden herabfallen, und die Kräfte in den Himmeln werden erschüttert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Und dann werden sie den Sohn des Menschen kommen sehen in Wolken mit großer Macht und Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Und dann wird er seine Engel aussenden und seine Auserwählten versammeln von den vier Winden her, vom Ende der Erde bis zum Ende des Himmels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Von dem Feigenbaum aber lernet das Gleichnis: Wenn sein Zweig schon weich geworden ist und die Blätter hervortreibt, so erkennet ihr, daß der Sommer nahe ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Also auch ihr, wenn ihr dies geschehen sehet, so erkennet, daß es nahe an der Tür ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Wahrlich, ich sage euch: dieses Geschlecht wird nicht vergehen, bis alles dieses geschehen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Der Himmel und die Erde werden vergehen, meine Worte aber sollen nicht vergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Von jenem Tage aber oder der Stunde weiß niemand, weder die Engel, die im Himmel sind, noch der Sohn, sondern nur der Vater.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Sehet zu, wachet und betet; denn ihr wisset nicht, wann die Zeit ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Gleichwie ein Mensch, der außer Landes reiste, sein Haus verließ und seinen Knechten die Gewalt gab und einem jeden sein Werk, und dem Türhüter einschärfte, daß er wache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'So wachet nun, denn ihr wisset nicht, wann der Herr des Hauses kommt, des Abends, oder um Mitternacht, oder um den Hahnenschrei, oder frühmorgens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'damit er nicht, plötzlich kommend, euch schlafend finde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Was ich aber euch sage, sage ich allen: Wachet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Es war aber nach zwei Tagen das Passah und das Fest der ungesäuerten Brote. Und die Hohenpriester und die Schriftgelehrten suchten, wie sie ihn mit List griffen und töteten; denn sie sagten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Nicht an dem Feste, damit nicht etwa ein Aufruhr des Volkes entstehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Und als er in Bethanien war, in dem Hause Simons, des Aussätzigen, kam, während er zu Tische lag, ein Weib, die ein Alabasterfläschchen mit Salbe von echter, kostbarer Narde hatte; und sie zerbrach das Fläschchen und goß es auf sein Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Es waren aber etliche unwillig bei sich selbst und sprachen: Wozu ist dieser Verlust der Salbe geschehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Denn diese Salbe hätte für mehr als dreihundert Denare verkauft und den Armen gegeben werden können. Und sie zürnten mit ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Jesus aber sprach: Lasset sie; was machet ihr ihr Mühe? Sie hat ein gutes Werk an mir getan;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'denn die Armen habt ihr allezeit bei euch, und wenn ihr wollt, könnt ihr ihnen wohltun; mich aber habt ihr nicht allezeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Sie hat getan, was sie vermochte; sie hat zum voraus meinen Leib zum Begräbnis gesalbt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Und wahrlich, ich sage euch: Wo irgend dieses Evangelium gepredigt werden wird in der ganzen Welt, wird auch von dem geredet werden, was diese getan hat, zu ihrem Gedächtnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Und Judas Iskariot, einer von den Zwölfen, ging hin zu den Hohenpriestern, auf daß er ihn denselben überlieferte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Sie aber freuten sich, als sie es hörten, und versprachen, ihm Geld zu geben; und er suchte, wie er ihn zu gelegener Zeit überliefern könnte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Und an dem ersten Tage der ungesäuerten Brote, da man das Passah schlachtete, sagen seine Jünger zu ihm: Wo willst du, daß wir hingehen und bereiten, auf daß du das Passah essest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Und er sendet zwei seiner Jünger und spricht zu ihnen: Gehet hin in die Stadt, und es wird euch ein Mensch begegnen, der einen Krug Wasser trägt; folget ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Und wo irgend er hineingeht, sprechet zu dem Hausherrn: Der Lehrer sagt: Wo ist mein Gastzimmer, wo ich mit meinen Jüngern das Passah essen mag?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Und derselbe wird euch einen großen Obersaal zeigen, mit Polstern belegt und fertig; daselbst bereitet für uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Und seine Jünger gingen aus und kamen in die Stadt und fanden es, wie er ihnen gesagt hatte; und sie bereiteten das Passah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Und als es Abend geworden war, kommt er mit den Zwölfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Und während sie zu Tische lagen und aßen, sprach Jesus: Wahrlich, ich sage euch: Einer von euch wird mich überliefern, der, welcher mit mir isset.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Sie aber fingen an, betrübt zu werden und einer nach dem anderen zu ihm zu sagen: Doch nicht ich? und ein anderer: Doch nicht ich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Er aber antwortete und sprach zu ihnen: Einer von den Zwölfen, der mit mir in die Schüssel eintaucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Der Sohn des Menschen geht zwar dahin, wie über ihn geschrieben steht; wehe aber jenem Menschen, durch welchen der Sohn des Menschen überliefert wird! Es wäre jenem Menschen gut, wenn er nicht geboren wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Und während sie aßen, nahm Jesus Brot, segnete und brach und gab es ihnen und sprach: Nehmet; dieses ist mein Leib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Und er nahm den Kelch, dankte und gab ihnen denselben; und sie tranken alle daraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Und er sprach zu ihnen: Dieses ist mein Blut, das des neuen Bundes, welches für viele vergossen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Wahrlich, ich sage euch, daß ich hinfort nicht mehr von dem Gewächs des Weinstocks trinken werde bis an jenem Tage, da ich es neu trinken werde in dem Reiche Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Und als sie ein Loblied gesungen hatten, gingen sie hinaus nach dem Ölberg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Und Jesus spricht zu ihnen: Ihr werdet euch alle ärgern, denn es steht geschrieben: \"Ich werde den Hirten schlagen, und die Schafe werden zerstreut werden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Nachdem ich aber auferweckt sein werde, werde ich vor euch hingehen nach Galiläa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Petrus aber sprach zu ihm: Wenn sich auch alle ärgern werden, ich aber nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Und Jesus spricht zu ihm: Wahrlich, ich sage dir, daß du heute, in dieser Nacht, ehe der Hahn zweimal kräht, mich dreimal verleugnen wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Er aber sprach über die Maßen mehr: Wenn ich mit dir sterben müßte, werde ich dich nicht verleugnen. Desgleichen aber sprachen auch alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Und sie kommen an einen Ort, mit Namen Gethsemane, und er spricht zu seinen Jüngern: Setzet euch hier, bis ich gebetet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Und er nimmt den Petrus und Jakobus und Johannes mit sich und fing an, sehr bestürzt und beängstigt zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Und er spricht zu ihnen: Meine Seele ist sehr betrübt, bis zum Tode; bleibet hier und wachet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Und er ging ein wenig weiter und fiel auf die Erde; und er betete, daß, wenn es möglich wäre, die Stunde an ihm vorüber gehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'Und er sprach: Abba, Vater, alles ist dir möglich; nimm diesen Kelch von mir weg; doch nicht was ich will, sondern was du willst!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Und er kommt und findet sie schlafend, und er spricht zu Petrus: Simon, schläfst du? Vermochtest du nicht eine Stunde zu wachen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Wachet und betet, auf daß ihr nicht in Versuchung kommet; der Geist zwar ist willig, das Fleisch aber schwach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Und er ging wiederum hin, betete und sprach dasselbe Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Und als er zurückkam, fand er sie wiederum schlafend, denn ihre Augen waren beschwert; und sie wußten nicht, was sie ihm antworten sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Und er kommt zum dritten Mal und spricht zu ihnen: So schlafet denn fort und ruhet aus. Es ist genug; die Stunde ist gekommen, siehe, der Sohn des Menschen wird in die Hände der Sünder überliefert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Stehet auf, laßt uns gehen; siehe, der mich überliefert, ist nahe gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Und alsbald, während er noch redete, kommt Judas, einer der Zwölfe, herzu, und mit ihm eine große Volksmenge mit Schwertern und Stöcken, von den Hohenpriestern und den Schriftgelehrten und den Ältesten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Der ihn aber überlieferte, hatte ihnen ein Zeichen gegeben und gesagt: Welchen irgend ich küssen werde, der ist\'s; ihn greifet und führet ihn sicher fort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Und als er kam, trat er alsbald zu ihm und spricht: Rabbi, Rabbi! und küßte ihn sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Sie aber legten ihre Hände an ihn und griffen ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Einer aber von den Dabeistehenden zog das Schwert, schlug den Knecht des Hohenpriesters und hieb ihm das Ohr ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Und Jesus hob an und sprach zu ihnen: Seid ihr ausgezogen wie gegen einen Räuber, mit Schwertern und Stöcken, mich zu fangen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Täglich war ich bei euch, im Tempel lehrend, und ihr habt mich nicht gegriffen; aber auf daß die Schriften erfüllt würden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Und es verließen ihn alle und flohen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Und ein gewisser Jüngling folgte ihm, der eine feine Leinwand um den bloßen Leib geworfen hatte; und die Jünglinge greifen ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'Er aber ließ die feine Leinwand fahren und floh nackt von ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Und sie führten Jesum hinweg zu dem Hohenpriester; und alle Hohenpriester und Ältesten und Schriftgelehrten versammeln sich zu ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Und Petrus folgte ihm von ferne bis hinein in den Hof des Hohenpriesters; und er saß mit bei den Dienern und wärmte sich an dem Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Die Hohenpriester aber und das ganze Synedrium suchten Zeugnis wider Jesum, um ihn zum Tode zu bringen; und sie fanden keines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Denn viele gaben falsches Zeugnis wider ihn, und die Zeugnisse waren nicht übereinstimmend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Und etliche standen auf und gaben falsches Zeugnis wider ihn und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Wir hörten ihn sagen: Ich werde diesen Tempel, der mit Händen gemacht ist, abbrechen, und in drei Tagen werde ich einen anderen aufbauen, der nicht mit Händen gemacht ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Und auch also war ihr Zeugnis nicht übereinstimmend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Und der Hohepriester stand auf, trat in die Mitte und fragte Jesum und sprach: Antwortest du nichts? Was zeugen diese wider dich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Er aber schwieg und antwortete nichts. Wiederum fragte ihn der Hohepriester und spricht zu ihm: Bist du der Christus, der Sohn des Gesegneten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Jesus aber sprach: Ich bin\'s! Und ihr werdet den Sohn des Menschen sitzen sehen zur Rechten der Macht und kommen mit den Wolken des Himmels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Der Hohepriester aber zerriß seine Kleider und spricht: Was bedürfen wir noch Zeugen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Ihr habt die Lästerung gehört; was dünkt euch? Sie aber verurteilten ihn, daß er des Todes schuldig sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Und etliche fingen an, ihn anzuspeien, und sein Angesicht zu verhüllen und ihn mit Fäusten zu schlagen und zu ihm zu sagen: Weissage! Und die Diener gaben ihm Backenstreiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Und als Petrus unten im Hofe war, kommt eine von den Mägden des Hohenpriesters,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'und als sie den Petrus sich wärmen sah, blickt sie ihn an und spricht: Auch du warst mit dem Nazarener Jesus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Er aber leugnete und sprach: Ich weiß nicht, verstehe auch nicht, was du sagst. Und er ging hinaus in den Vorhof; und der Hahn krähte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Und als die Magd ihn sah, fing sie wiederum an, zu den Dabeistehenden zu sagen: Dieser ist einer von ihnen. Er aber leugnete wiederum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Und kurz nachher sagten wiederum die Dabeistehenden zu Petrus: Wahrhaftig, du bist einer von ihnen, denn du bist auch ein Galiläer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Er aber fing an, sich zu verfluchen und zu schwören: Ich kenne diesen Menschen nicht, von welchem ihr redet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Und zum zweiten Male krähte der Hahn. Und Petrus gedachte des Wortes, wie Jesus zu ihm gesagt hatte: Ehe der Hahn zweimal kräht, wirst du mich dreimal verleugnen. Und als er daran dachte, weinte er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Und alsbald am frühen Morgen hielten die Hohenpriester Rat samt den Ältesten und Schriftgelehrten und das ganze Synedrium, und sie banden Jesum und führten ihn weg und überlieferten ihn dem Pilatus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Und Pilatus fragte ihn: Bist du der König der Juden? Er aber antwortete und sprach zu ihm: Du sagst es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Und die Hohenpriester klagten ihn vieler Dinge an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Pilatus aber fragte ihn wiederum und sprach: Antwortest du nichts? Siehe, wie vieles sie wider dich zeugen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Jesus aber antwortete gar nichts mehr, so daß Pilatus sich verwunderte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Auf das Fest aber pflegte er ihnen einen Gefangenen loszugeben, um welchen sie baten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Es war aber einer, genannt Barabbas, mit seinen Mitaufrührern gebunden, welche in dem Aufstande einen Mord begangen hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Und die Volksmenge erhob ein Geschrei und fing an zu begehren, daß er täte, wie er ihnen allezeit getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Pilatus aber antwortete ihnen und sprach: Wollt ihr, daß ich euch den König der Juden losgebe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Denn er wußte, daß die Hohenpriester ihn aus Neid überliefert hatten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Die Hohenpriester aber wiegelten die Volksmenge auf, daß er ihnen lieber den Barabbas losgebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Pilatus aber antwortete und sprach wiederum zu ihnen: Was wollt ihr denn, daß ich mit dem tue, welchen ihr König der Juden nennet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Sie aber schrieen wiederum: Kreuzige ihn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Pilatus aber sprach zu ihnen: Was hat er denn Böses getan? Sie aber schrieen übermäßig: Kreuzige ihn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Da aber Pilatus der Volksmenge willfahren wollte, gab er ihnen den Barabbas los und überliefere Jesum, nachdem er ihn hatte geißeln lassen, auf daß er gekreuzigt würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Die Kriegsknechte aber führten ihn in den Hof hinein, das ist das Prätorium; und sie rufen die ganze Schar zusammen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Und sie legen ihm einen Purpur an und flechten eine Dornenkrone und setzen sie ihm auf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'und sie fingen an, ihn zu grüßen: Sei gegrüßt, König der Juden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Und sie schlugen ihn mit einem Rohr auf das Haupt und spieen ihn an, und sie beugten die Knie und huldigten ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Und als sie ihn verspottet hatten, zogen sie ihm den Purpur aus und zogen ihm seine eigenen Kleider an; und sie führten ihn hinaus, auf daß sie ihn kreuzigten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Und sie zwingen einen Vorübergehenden, einen gewissen Simon von Kyrene, der vom Felde kam, den Vater Alexanders und Rufus\', daß er sein Kreuz trüge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Und sie bringen ihn nach der Stätte Golgatha, was verdolmetscht ist Schädelstätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Und sie gaben ihm Wein, mit Myrrhen vermischt, zu trinken er aber nahm es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Und als sie ihn gekreuzigt hatten, verteilten sie seine Kleider, indem sie das Los über dieselben warfen, was jeder bekommen sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Es war aber die dritte Stunde, und sie kreuzigten ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Und die Überschrift seiner Beschuldigung war oben über geschrieben: Der König der Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Und mit ihm kreuzigen sie zwei Räuber, einen zu seiner Rechten und einen zu seiner Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'Und die Schrift wurde erfüllt, welche sagt: \"Und er ist unter die Gesetzlosen gerechnet worden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Und die Vorübergehenden lästerten ihn, indem sie ihre Köpfe schüttelten und sagten: Ha! Der du den Tempel abbrichst und in drei Tagen aufbaust,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'rette dich selbst und steige herab vom Kreuze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Gleicherweise spotteten auch die Hohenpriester samt den Schriftgelehrten untereinander und sprachen: Andere hat er gerettet, sich selbst kann er nicht retten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Der Christus, der König Israels, steige jetzt herab vom Kreuze, auf daß wir sehen und glauben. Auch die mit ihm gekreuzigt waren, schmähten ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Als es aber die sechste Stunde war, kam eine Finsternis über das ganze Land bis zur neunten Stunde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'und zur neunten Stunde schrie Jesus mit lauter Stimme und sagte: Eloi, Eloi, lama sabachthani? was verdolmetscht ist: Mein Gott, mein Gott, warum hast du mich verlassen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Und als etliche der Dabeistehenden es hörten, sagten sie: Siehe, er ruft den Elias.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Es lief aber einer und füllte einen Schwamm mit Essig und steckte ihn auf ein Rohr und tränkte ihn und sprach: Halt, laßt uns sehen, ob Elias kommt, ihn herabzunehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Jesus aber gab einen lauten Schrei von sich und verschied.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Und der Vorhang des Tempels zerriß in zwei Stücke, von oben bis unten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Als aber der Hauptmann, der ihm gegenüber dabeistand, sah, daß er also schrie und verschied, sprach er: Wahrhaftig, dieser Mensch war Gottes Sohn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Es waren aber auch Weiber, die von ferne zusahen, unter welchen auch Maria Magdalene war und Maria, Jakobus\' des Kleinen und Joses\' Mutter, und Salome,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'welche auch, als er in Galiläa war, ihm nachfolgten und ihm dienten; und viele andere, die mit ihm nach Jerusalem hinaufgekommen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Und als es schon Abend geworden, (dieweil es Rüsttag war, welches der Vorsabbath ist)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'kam Joseph von Arimathia, ein ehrbarer Ratsherr, der auch selbst das Reich Gottes erwartete, und ging kühn zu Pilatus hinein und bat um den Leib Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilatus aber wunderte sich, daß er schon gestorben sei; und er rief den Hauptmann herzu und fragte ihn, ob er schon lange gestorben sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Und als er es von dem Hauptmann erfuhr, schenkte er dem Joseph den Leib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Und er kaufte feine Leinwand, nahm ihn herab und wickelte ihn in die feine Leinwand und legte ihn in eine Gruft, die aus einem Felsen gehauen war; und er wälzte einen Stein an die Tür der Gruft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Aber Maria Magdalene und Maria, Joses\' Mutter, sahen zu, wo er hingelegt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Und als der Sabbath vergangen war, kauften Maria Magdalene und Maria, die Mutter des Jakobus, und Salome wohlriechende Spezereien, auf daß sie kämen und ihn salbten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Und sehr früh am ersten Wochentage kommen sie zur Gruft, als die Sonne aufgegangen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Und sie sprachen zueinander: Wer wird uns den Stein von der Tür der Gruft wälzen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Und als sie aufblickten, sehen sie, daß der Stein weggewälzt ist; denn er war sehr groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Und als sie in die Gruft eintraten, sahen sie einen Jüngling zur Rechten sitzen, angetan mit einem weißen Gewande, und sie entsetzten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Er aber spricht zu ihnen: Entsetzet euch nicht; ihr suchet Jesum, den Nazarener, den Gekreuzigten. Er ist auferstanden, er ist nicht hier. Siehe da die Stätte, wo sie ihn hingelegt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Aber gehet hin, saget seinen Jüngern und Petrus, daß er vor euch hingeht nach Galiläa; daselbst werdet ihr ihn sehen, wie er euch gesagt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Und sie gingen hinaus und flohen von der Gruft. Denn Zittern und Bestürzung hatte sie ergriffen, und sie sagten niemand etwas, denn sie fürchteten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Als er aber früh am ersten Wochentage auferstanden war, erschien er zuerst der Maria Magdalene, von welcher er sieben Dämonen ausgetrieben hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Diese ging hin und verkündete es denen, die mit ihm gewesen waren, welche trauerten und weinten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Und als jene hörten, daß er lebe und von ihr gesehen worden sei, glaubten sie es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Nach diesem aber offenbarte er sich zweien aus ihnen in einer anderen Gestalt, während sie wandelten, als sie aufs Land gingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Und diese gingen hin und verkündeten es den übrigen; auch denen glaubten sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Nachher, als sie zu Tische lagen, offenbarte er sich den Elfen und schalt ihren Unglauben und ihre Herzenshärtigkeit, daß sie denen, die ihn auferweckt gesehen, nicht geglaubt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Und er sprach zu ihnen: Gehet hin in die ganze Welt und prediget das Evangelium der ganzen Schöpfung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Wer da glaubt und getauft wird, wird errettet werden; wer aber nicht glaubt, wird verdammt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Diese Zeichen aber werden denen folgen, welche glauben: In meinem Namen werden sie Dämonen austreiben; sie werden in neuen Sprachen reden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'werden Schlangen aufnehmen, und wenn sie etwas Tödliches trinken, so wird es ihnen nicht schaden; Schwachen werden sie die Hände auflegen, und sie werden sich wohl befinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Der Herr nun wurde, nachdem er mit ihnen geredet hatte, in den Himmel aufgenommen und setzte sich zur Rechten Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Jene aber gingen aus und predigten allenthalben, indem der Herr mitwirkte und das Wort bestätigte durch die darauf folgenden Zeichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Dieweil ja viele es unternommen haben, eine Erzählung von den Dingen, die unter uns völlig geglaubt werden, zu verfassen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'so wie es uns die überliefert haben, welche von Anfang an Augenzeugen und Diener des Wortes gewesen sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'hat es auch mir gut geschienen, der ich allem von Anfang an genau gefolgt bin, es dir, vortrefflichster Theophilus, der Reihe nach zu schreiben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'auf daß du die Zuverlässigkeit der Dinge erkennest, in welchen du unterrichtet worden bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Es war in den Tagen Herodes\', des Königs von Judäa, ein gewisser Priester, mit Namen Zacharias, aus der Abteilung Abias; und sein Weib war aus den Töchtern Aarons, und ihr Name Elisabeth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Beide aber waren gerecht vor Gott, indem sie untadelig wandelten in allen Geboten und Satzungen des Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Und sie hatten kein Kind, weil Elisabeth unfruchtbar war; und beide waren in ihren Tagen weit vorgerückt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Es geschah aber, als er in der Ordnung seiner Abteilung den priesterlichen Dienst vor Gott erfüllte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'traf ihn, nach der Gewohnheit des Priestertums, das Los, in den Tempel des Herrn zu gehen, um zu räuchern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Und die ganze Menge des Volkes war betend draußen zur Stunde des Räucherns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Es erschien ihm aber ein Engel des Herrn, zur Rechten des Räucheraltars stehend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Und als Zacharias ihn sah, ward er bestürzt, und Furcht überfiel ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Der Engel aber sprach zu ihm: Fürchte dich nicht, Zacharias, denn dein Flehen ist erhört, und dein Weib Elisabeth wird dir einen Sohn gebären, und du sollst seinen Namen Johannes heißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Und er wird dir zur Freude und Wonne sein, und viele werden sich über seine Geburt freuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Denn er wird groß sein vor dem Herrn; weder Wein noch starkes Getränk wird er trinken und schon von Mutterleibe an mit Heiligem Geiste erfüllt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Und viele der Söhne Israels wird er zu dem Herrn, ihrem Gott, bekehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Und er wird vor ihm hergehen in dem Geist und der Kraft des Elias, um der Väter Herzen zu bekehren zu den Kindern und Ungehorsame zur Einsicht von Gerechten, um dem Herrn ein zugerüstetes Volk zu bereiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Und Zacharias sprach zu dem Engel: Woran soll ich dies erkennen? Denn ich bin ein alter Mann, und mein Weib ist weit vorgerückt in ihren Tagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Und der Engel antwortete und sprach zu ihm: Ich bin Gabriel, der vor Gott steht, und ich bin gesandt worden, zu dir zu reden und dir diese gute Botschaft zu verkündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Und siehe, du wirst stumm sein und nicht sprechen können bis zu dem Tage, da dieses geschehen wird, weil du meinen Worten nicht geglaubt hast, die zu ihrer Zeit werden erfüllt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Und das Volk wartete auf Zacharias, und sie wunderten sich darüber, daß er im Tempel verzog.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Als er aber herauskam, konnte er nicht zu ihnen reden, und sie erkannten, daß er im Tempel ein Gesicht gesehen hatte. Und er winkte ihnen zu und blieb stumm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Und es geschah, als die Tage seines Dienstes erfüllt waren, ging er weg nach seinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Nach diesen Tagen aber wurde Elisabeth, sein Weib, schwanger und verbarg sich fünf Monate, indem sie sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Also hat mir der Herr getan in den Tagen, in welchen er mich angesehen hat, um meine Schmach unter den Menschen wegzunehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Im sechsten Monat aber wurde der Engel Gabriel von Gott gesandt in eine Stadt von Galiläa, mit Namen Nazareth,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'zu einer Jungfrau, die einem Manne verlobt war mit Namen Joseph, aus dem Hause Davids; und der Name der Jungfrau war Maria.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Und der Engel kam zu ihr hinein und sprach: Sei gegrüßt, Begnadigte! Der Herr ist mit dir; gesegnet bist du unter den Weibern!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Sie aber, als sie ihn sah ward bestürzt über sein Wort und überlegte, was für ein Gruß dies sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Und der Engel sprach zu ihr: Fürchte dich nicht, Maria, denn du hast Gnade bei Gott gefunden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'und siehe, du wirst im Leibe empfangen und einen Sohn gebären, und du sollst seinen Namen Jesus heißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Dieser wird groß sein und Sohn des Höchsten genannt werden; und der Herr, Gott, wird ihm den Thron seines Vaters David geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'und er wird über das Haus Jakobs herrschen ewiglich, und seines Reiches wird kein Ende sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Maria aber sprach zu dem Engel: Wie wird dies sein, dieweil ich keinen Mann kenne?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Und der Engel antwortete und sprach zu ihr: Der Heilige Geist wird über dich kommen, und Kraft des Höchsten wird dich überschatten; darum wird auch das Heilige, das geboren werden wird, Sohn Gottes genannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Und siehe, Elisabeth, deine Verwandte, ist auch mit einem Sohne schwanger in ihrem Alter, und dies ist der sechste Monat bei ihr, welche unfruchtbar genannt war;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'denn bei Gott wird kein Ding unmöglich sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Maria aber sprach: Siehe, ich bin die Magd des Herrn; es geschehe mir nach deinem Worte. Und der Engel schied von ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Maria aber stand in selbigen Tagen auf und ging mit Eile nach dem Gebirge, in eine Stadt Judas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'und sie kam in das Haus des Zacharias und begrüßte die Elisabeth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Und es geschah, als Elisabeth den Gruß der Maria hörte, hüpfte das Kind in ihrem Leibe; und Elisabeth wurde mit Heiligem Geiste erfüllt');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'und rief aus mit lauter Stimme und sprach: Gesegnet bist du unter den Weibern, und gesegnet ist die Frucht deines Leibes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Und woher mir dieses, daß die Mutter meines Herrn zu mir kommt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Denn siehe, wie die Stimme deines Grußes in meine Ohren drang, hüpfte das Kind vor Freude in meinem Leibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Und glückselig, die geglaubt hat, denn es wird zur Erfüllung kommen, was von dem Herrn zu ihr geredet ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Und Maria sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'Meine Seele erhebt den Herrn, und mein Geist hat frohlockt in Gott, meinem Heilande;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'denn er hat hingeblickt auf die Niedrigkeit seiner Magd; denn siehe, von nun an werden mich glückselig preisen alle Geschlechter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Denn große Dinge hat der Mächtige an mir getan, und heilig ist sein Name;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'und seine Barmherzigkeit ist von Geschlecht zu Geschlecht über die, welche ihn fürchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Er hat Macht geübt mit seinem Arm; er hat zerstreut, die in der Gesinnung ihres Herzens hochmütig sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Er hat Mächtige von Thronen hinabgestoßen, und Niedrige erhöht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Hungrige hat er mit Gütern erfüllt, und Reiche leer fortgeschickt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Er hat sich Israels, seines Knechtes, angenommen, damit er eingedenk sei der Barmherzigkeit');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, '(wie er zu unseren Vätern geredet hat) gegen Abraham und seinen Samen in Ewigkeit. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Und Maria blieb ungefähr drei Monate bei ihr; und sie kehrte nach ihrem Hause zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Für Elisabeth aber wurde die Zeit erfüllt, daß sie gebären sollte, und sie gebar einen Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Und ihre Nachbarn und Verwandten hörten, daß der Herr seine Barmherzigkeit an ihr groß gemacht habe, und sie freuten sich mit ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Und es geschah am achten Tage, da kamen sie, das Kindlein zu beschneiden; und sie nannten es nach dem Namen seines Vaters: Zacharias.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Und seine Mutter antwortete und sprach: Nein, sondern er soll Johannes heißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Und sie sprachen zu ihr: Niemand ist aus deiner Verwandtschaft, der diesen Namen trägt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Sie winkten aber seinem Vater zu, wie er etwa wolle, daß er genannt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Und er forderte ein Täfelchen und schrieb also: Johannes ist sein Name. Und sie verwunderten sich alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Alsbald aber wurde sein Mund aufgetan und seine Zunge gelöst, und er redete, indem er Gott lobte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Und Furcht kam über alle, die um sie her wohnten; und auf dem ganzen Gebirge von Judäa wurden alle diese Dinge besprochen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Und alle, die es hörten, nahmen es zu Herzen und sprachen: Was wird doch aus diesem Kindlein werden? Denn auch des Herrn Hand war mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Und Zacharias, sein Vater, wurde mit Heiligem Geiste erfüllt und weissagte und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Gepriesen sei der Herr, der Gott Israels, daß er besucht und Erlösung geschafft hat seinem Volke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'und uns ein Horn des Heils aufgerichtet hat in dem Hause Davids, seines Knechtes');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, '(gleichwie er geredet hat durch den Mund seiner heiligen Propheten, die von alters her waren),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Rettung von unseren Feinden und von der Hand aller, die uns hassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'um Barmherzigkeit zu vollbringen an unseren Vätern und seines heiligen Bundes zu gedenken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'des Eides, den er Abraham, unserem Vater, geschworen hat, um uns zu geben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'daß wir, gerettet aus der Hand unserer Feinde, ohne Furcht ihm dienen sollen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'in Frömmigkeit und Gerechtigkeit vor ihm alle unsere Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Und du, Kindlein, wirst ein Prophet des Höchsten genannt werden; denn du wirst vor dem Angesicht des Herrn hergehen, seine Wege zu bereiten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'um seinem Volke Erkenntnis des Heils zu geben in Vergebung ihrer Sünden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'durch die herzliche Barmherzigkeit unseres Gottes, in welcher uns besucht hat der Aufgang aus der Höhe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'um denen zu leuchten, die in Finsternis und Todesschatten sitzen, um unsere Füße zu richten auf den Weg des Friedens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Das Kindlein aber wuchs und erstarkte im Geist, und war in den Wüsteneien bis zum Tage seines Auftretens vor Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Es geschah aber in jenen Tagen, daß eine Verordnung vom Kaiser Augustus ausging, den ganzen Erdkreis einzuschreiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Die Einschreibung selbst geschah erst, als Kyrenius Landpfleger von Syrien war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Und alle gingen hin, um sich einschreiben zu lassen, ein jeder in seine eigene Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Es ging aber auch Joseph von Galiläa, aus der Stadt Nazareth, hinauf nach Judäa, in Davids Stadt, welche Bethlehem heißt, weil er aus dem Hause und Geschlecht Davids war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'um sich einschreiben zu lassen mit Maria, seinem verlobten Weibe, welche schwanger war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Und es geschah, als sie daselbst waren, wurden ihre Tage erfüllt, daß sie gebären sollte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'und sie gebar ihren erstgeborenen Sohn und wickelte ihn in Windeln und legte ihn in eine Krippe, weil in der Herberge kein Raum für sie war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Und es waren Hirten in selbiger Gegend, die auf freiem Felde blieben und des Nachts Wache hielten über ihre Herde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Und siehe, ein Engel des Herrn stand bei ihnen, und die Herrlichkeit des Herrn umleuchtete sie, und sie fürchteten sich mit großer Furcht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Und der Engel sprach zu ihnen: Fürchtet euch nicht, denn siehe, ich verkündige euch große Freude, die für das ganze Volk sein wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'denn euch ist heute, in Davids Stadt, ein Erretter geboren, welcher ist Christus, der Herr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Und dies sei euch das Zeichen: Ihr werdet ein Kind finden, in Windeln gewickelt und in einer Krippe liegend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Und plötzlich war bei dem Engel eine Menge der himmlischen Heerscharen, welche Gott lobten und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Herrlichkeit Gott in der Höhe, und Friede auf Erden, an den Menschen ein Wohlgefallen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Und es geschah, als die Engel von ihnen hinweg in den Himmel fuhren, daß die Hirten zueinander sagten: Laßt uns nun hingehen nach Bethlehem und diese Sache sehen, die geschehen ist, welche der Herr uns kundgetan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Und sie kamen eilends und fanden sowohl Maria als Joseph, und das Kind in der Krippe liegend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Als sie es aber gesehen hatten, machten sie überall das Wort kund, welches über dieses Kindlein zu ihnen geredet worden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Und alle, die es hörten, verwunderten sich über das, was von den Hirten zu ihnen gesagt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Maria aber bewahrte alle diese Worte und erwog sie in ihrem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Und die Hirten kehrten um, indem sie Gott verherrlichten und lobten über alles, was sie gehört und gesehen hatten, so wie es ihnen gesagt worden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Und als acht Tage erfüllt waren, daß man ihn beschneiden sollte, da wurde sein Name Jesus genannt, welcher von dem Engel genannt worden war, ehe er im Leibe empfangen wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Und als die Tage ihrer Reinigung nach dem Gesetz Moses\' erfüllt waren, brachten sie ihn nach Jerusalem hinauf, um ihn dem Herrn darzustellen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(gleichwie im Gesetz des Herrn geschrieben steht: \"Alles Männliche, das die Mutter bricht, soll dem Herrn heilig heißen\")');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'und ein Schlachtopfer zu geben nach dem, was im Gesetz des Herrn gesagt ist: ein Paar Turteltauben oder zwei junge Tauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Und siehe, es war in Jerusalem ein Mensch, mit Namen Simeon; und dieser Mensch war gerecht und gottesfürchtig und wartete auf den Trost Israels; und der Heilige Geist war auf ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Und es war ihm von dem Heiligen Geist ein göttlicher Ausspruch geworden, daß er den Tod nicht sehen solle, ehe er den Christus des Herrn gesehen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Und er kam durch den Geist in den Tempel. Und als die Eltern das Kindlein Jesus hereinbrachten, um betreffs seiner nach der Gewohnheit des Gesetzes zu tun,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'da nahm auch er es auf seine Arme und lobte Gott und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Nun, Herr, entlässest du deinen Knecht, nach deinem Worte, in Frieden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'denn meine Augen haben dein Heil gesehen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'welches du bereitet hast vor dem Angesicht aller Völker:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'ein Licht zur Offenbarung der Nationen und zur Herrlichkeit deines Volkes Israel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Und sein Vater und seine Mutter verwunderten sich über das, was über ihn geredet wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Und Simeon segnete sie und sprach zu Maria, seiner Mutter: Siehe, dieser ist gesetzt zum Fall und Aufstehen vieler in Israel und zu einem Zeichen, dem widersprochen wird');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(aber auch deine eigene Seele wird ein Schwert durchdringen), damit die Überlegungen vieler Herzen offenbar werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Und es war eine Prophetin Anna, eine Tochter Phanuels, aus dem Stamme Aser. Diese war in ihren Tagen weit vorgerückt und hatte sieben Jahre mit ihrem Manne gelebt von ihrer Jungfrauschaft an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'und sie war eine Witwe von vierundachtzig Jahren, die nicht von dem Tempel wich, indem sie Nacht und Tag mit Fasten und Flehen diente.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Und sie trat zu derselben Stunde herzu, lobte den Herrn und redete von ihm zu allen, welche auf Erlösung warteten in Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Und als sie alles vollendet hatten nach dem Gesetz des Herrn, kehrten sie nach Galiläa zurück in ihre Stadt Nazareth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Das Kindlein aber wuchs und erstarkte, erfüllt mit Weisheit, und Gottes Gnade war auf ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Und seine Eltern gingen alljährlich am Passahfest nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Und als er zwölf Jahre alt war und sie nach Jerusalem hinaufgingen, nach der Gewohnheit des Festes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'und die Tage vollendet hatten, blieb bei ihrer Rückkehr der Knabe Jesus in Jerusalem zurück; und seine Eltern wußten es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Da sie aber meinten, er sei unter der Reisegesellschaft, kamen sie eine Tagereise weit und suchten ihn unter den Verwandten und Bekannten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'und als sie ihn nicht fanden, kehrten sie nach Jerusalem zurück und suchten ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Und es geschah, nach drei Tagen fanden sie ihn im Tempel, wie er inmitten der Lehrer saß und ihnen zuhörte und sie befragte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Alle aber, die ihn hörten, gerieten außer sich über sein Verständnis und seine Antworten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Und als sie ihn sahen, erstaunten sie; und seine Mutter sprach zu ihm: Kind, warum hast du uns also getan? Siehe, dein Vater und ich haben dich mit Schmerzen gesucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Und er sprach zu ihnen: Was ist es, daß ihr mich gesucht habt? Wußtet ihr nicht, daß ich in dem sein muß, was meines Vaters ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Und sie verstanden das Wort nicht, das er zu ihnen redete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Und er ging mit ihnen hinab und kam nach Nazareth, und er war ihnen untertan. Und seine Mutter bewahrte alle diese Worte in ihrem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Und Jesus nahm zu an Weisheit und an Größe, und an Gunst bei Gott und Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Aber im fünfzehnten Jahre der Regierung des Kaisers Tiberius, als Pontius Pilatus Landpfleger von Judäa war, und Herodes Vierfürst von Galiläa, und sein Bruder Philippus Vierfürst von Ituräa und der Landschaft Trachonitis, und Lysanias Vierfürst von Abilene,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'unter dem Hohenpriestertum von Annas und Kajaphas, geschah das Wort Gottes zu Johannes, dem Sohne Zacharias\', in der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Und er kam in die ganze Umgegend des Jordan und predigte die Taufe der Buße zur Vergebung der Sünden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'wie geschrieben steht im Buche der Worte Jesaias\', des Propheten: \"Stimme eines Rufenden in der Wüste: Bereitet den Weg des Herrn, machet gerade seine Steige!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Jedes Tal wird ausgefüllt und jeder Berg und Hügel erniedrigt werden, und das Krumme wird zum geraden Wege und die höckerichten zu ebenen Wegen werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'und alles Fleisch wird das Heil Gottes sehen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Er sprach nun zu den Volksmengen, die hinausgingen, um von ihm getauft zu werden: Otternbrut! Wer hat euch gewiesen, dem kommenden Zorn zu entfliehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Bringet nun der Buße würdige Früchte; und beginnet nicht, bei euch selbst zu sagen: Wir haben Abraham zum Vater; denn ich sage euch, daß Gott dem Abraham aus diesen Steinen Kinder zu erwecken vermag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Schon ist aber auch die Axt an die Wurzel der Bäume gelegt; jeder Baum nun, der nicht gute Frucht bringt, wird abgehauen und ins Feuer geworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Und die Volksmengen fragten ihn und sprachen: Was sollen wir denn tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Er aber antwortete und sprach zu ihnen: Wer zwei Leibröcke hat, teile dem mit, der keinen hat; und wer Speise hat, tue gleicherweise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Es kamen aber auch Zöllner, um getauft zu werden; und sie sprachen zu ihm: Lehrer, was sollen wir tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Er aber sprach zu ihnen: Fordert nicht mehr, als euch bestimmt ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Es fragten ihn aber auch Kriegsleute und sprachen: Und wir, was sollen wir tun? Und er sprach zu ihnen: Tut niemand Gewalt, und klaget niemand fälschlich an, und begnüget euch mit eurem Solde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Als aber das Volk in Erwartung war, und alle in ihren Herzen wegen Johannes überlegten, ob er nicht etwa der Christus sei,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'antwortete Johannes allen und sprach: Ich zwar taufe euch mit Wasser; es kommt aber, der stärker ist als ich, dessen ich nicht würdig bin, ihm den Riemen seiner Sandalen zu lösen; er wird euch mit Heiligem Geiste und Feuer taufen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'dessen Worfschaufel in seiner Hand ist, und er wird seine Tenne durch und durch reinigen und den Weizen in seine Scheune sammeln; die Spreu aber wird er verbrennen mit unauslöschlichem Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Indem er nun auch mit vielem anderen ermahnte, verkündigte er dem Volke gute Botschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Herodes aber, der Vierfürst, weil er wegen der Herodias, des Weibes seines Bruders, und wegen alles Bösen, das Herodes getan hatte, von ihm gestraft wurde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'fügte allem auch dies hinzu, daß er Johannes ins Gefängnis einschloß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Es geschah aber, als das ganze Volk getauft wurde, und Jesus getauft war und betete, daß der Himmel aufgetan wurde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'und der Heilige Geist in leiblicher Gestalt, wie eine Taube, auf ihn herabstieg, und eine Stimme aus dem Himmel kam: Du bist mein geliebter Sohn, an dir habe ich Wohlgefallen gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Und er selbst, Jesus, begann ungefähr dreißig Jahre alt zu werden, und war, wie man meinte, ein Sohn des Joseph, des Eli,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'des Matthat, des Levi, des Melchi, des Janna, des Joseph,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'des Mattathias, des Amos, des Nahum, des Esli, des Naggai,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'des Maath, des Mattathias, des Semei, des Joseph, des Juda,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'des Johanna, des Resa, des Zorobabel, des Salathiel, des Neri,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'des Melchi, des Addi, des Kosam, des Elmodam, des Er,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'des Joses, des Elieser, des Jorim, des Matthat, des Levi,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'des Simeon, des Juda, des Joseph, des Jonan, des Eliakim,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'des Melea, des Menna, des Mattatha, des Nathan, des David,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'des Isai, des Obed, des Boas, des Salmon, des Nahasson,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'des Aminadab, des Aram, des Esrom, des Phares, des Juda,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'des Jakob, des Isaak, des Abraham, des Thara, des Nachor,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'des Seruch, des Rhagau, des Phalek, des Eber, des Sala,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'des Kainan, des Arphaxad, des Sem, des Noah, des Lamech,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'des Methusala, des Enoch, des Jared, des Maleleel, des Kainan,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'des Enos, des Seth, des Adam, des Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Jesus aber, voll Heiligen Geistes, kehrte vom Jordan zurück und wurde durch den Geist in der Wüste vierzig Tage umhergeführt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'indem er von dem Teufel versucht wurde. Und er aß in jenen Tagen nichts; und als sie vollendet waren, hungerte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Und der Teufel sprach zu ihm: Wenn du Gottes Sohn bist, so sprich zu diesem Steine, daß er Brot werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Und Jesus antwortete ihm und sprach: Es steht geschrieben: \"Nicht vom Brot allein soll der Mensch leben, sondern von jedem Worte Gottes\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Und der Teufel führte ihn auf einen hohen Berg und zeigte ihm in einem Augenblick alle Reiche des Erdkreises.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'Und der Teufel sprach zu ihm: Ich will dir alle diese Gewalt und ihre Herrlichkeit geben; denn mir ist sie übergeben, und wem irgend ich will, gebe ich sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Wenn du nun vor mir anbeten willst, soll sie alle dein sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Und Jesus antwortete ihm und sprach: Es steht geschrieben: \"Du sollst den Herrn, deinen Gott, anbeten und ihm allein dienen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Und er führte ihn nach Jerusalem und stellte ihn auf die Zinne des Tempels und sprach zu ihm: Wenn du Gottes Sohn bist, so wirf dich von hier hinab;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'denn es steht geschrieben: \"Er wird seinen Engeln über dir befehlen, daß sie dich bewahren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'und sie werden dich auf den Händen tragen, damit du nicht etwa deinen Fuß an einen Stein stoßest\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Und Jesus antwortete und sprach zu ihm: Es ist gesagt: \"Du sollst den Herrn, deinen Gott, nicht versuchen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Und als der Teufel jede Versuchung vollendet hatte, wich er für eine Zeit von ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Und Jesus kehrte in der Kraft des Geistes nach Galiläa zurück, und das Gerücht über ihn ging aus durch die ganze Umgegend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Und er lehrte in ihren Synagogen, geehrt von allen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Und er kam nach Nazareth, wo er erzogen war; und er ging nach seiner Gewohnheit am Sabbathtage in die Synagoge und stand auf, um vorzulesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Und es wurde ihm das Buch des Propheten Jesaias gereicht; und als er das Buch aufgerollt hatte, fand er die Stelle, wo geschrieben war:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '\"Der Geist des Herrn ist auf mir, weil er mich gesalbt hat, Armen gute Botschaft zu verkündigen; er hat mich gesandt, Gefangenen Befreiung auszurufen und Blinden das Gesicht, Zerschlagene in Freiheit hinzusenden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'auszurufen das angenehme Jahr des Herrn\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Und als er das Buch zugerollt hatte, gab er es dem Diener zurück und setzte sich; und aller Augen in der Synagoge waren auf ihn gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Er fing aber an, zu ihnen zu sagen: Heute ist diese Schrift vor euren Ohren erfüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Und alle gaben ihm Zeugnis und verwunderten sich über die Worte der Gnade, die aus seinem Munde hervorgingen; und sie sprachen: Ist dieser nicht der Sohn Josephs?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Und er sprach zu ihnen: Ihr werdet allerdings dieses Sprichwort zu mir sagen: Arzt, heile dich selbst; alles, was wir gehört haben, daß es in Kapernaum geschehen sei, tue auch hier in deiner Vaterstadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Er sprach aber: Wahrlich, ich sage euch, daß kein Prophet in seiner Vaterstadt angenehm ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'In Wahrheit aber sage ich euch: Viele Witwen waren in den Tagen Elias\' in Israel, als der Himmel drei Jahre und sechs Monate verschlossen war, so daß eine große Hungersnot über das ganze Land kam;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'und zu keiner von ihnen wurde Elias gesandt, als nur nach Sarepta in Sidonia, zu einem Weibe, einer Witwe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Und viele Aussätzige waren zur Zeit des Propheten Elisa in Israel, und keiner von ihnen wurde gereinigt, als nur Naaman, der Syrer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Und alle wurden von Wut erfüllt in der Synagoge, als sie dies hörten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'Und sie standen auf und stießen ihn zur Stadt hinaus und führten ihn bis an den Rand des Berges, auf welchem ihre Stadt erbaut war, um ihn so hinabzustürzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Er aber, durch ihre Mitte hindurchgehend, ging hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Und er kam nach Kapernaum hinab, einer Stadt in Galiläa, und lehrte sie an den Sabbathen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'Und sie erstaunten sehr über seine Lehre, denn sein Wort war mit Gewalt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Und es war in der Synagoge ein Mensch, der einen Geist eines unreinen Dämons hatte, und er schrie auf mit lauter Stimme');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'und sprach: Laß ab! Was haben wir mit dir zu schaffen, Jesu, Nazarener? Bist du gekommen, uns zu verderben? Ich kenne dich, wer du bist: der Heilige Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Und Jesus bedrohte ihn und sprach: Verstumme und fahre aus von ihm! Und als der Dämon ihn mitten unter sie geworfen hatte, fuhr er von ihm aus, ohne ihn zu beschädigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Und Entsetzen kam über alle, und sie redeten untereinander und sprachen: Was ist dies für ein Wort? Denn mit Gewalt und Kraft gebietet er den unreinen Geistern, und sie fahren aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Und das Gerücht über ihn ging aus in jeden Ort der Umgegend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Er machte sich aber auf von der Synagoge und kam in das Haus Simons. Die Schwiegermutter des Simon aber war von einem starken Fieber befallen; und sie baten ihn für sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Und über ihr stehend, bedrohte er das Fieber, und es verließ sie; sie aber stand alsbald auf und diente ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Als aber die Sonne unterging, brachten alle, welche an mancherlei Krankheiten Leidende hatten, dieselben zu ihm; er aber legte einem jeden von ihnen die Hände auf und heilte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Und auch Dämonen fuhren von vielen aus, indem sie schrieen und sprachen: Du bist der Sohn Gottes. Und er bedrohte sie und ließ sie nicht reden, weil sie wußten, daß er der Christus war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Als es aber Tag geworden war, ging er aus und begab sich an einen öden Ort; und die Volksmengen suchten ihn auf und kamen bis zu ihm, und sie hielten ihn auf, daß er nicht von ihnen ginge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Er aber sprach zu ihnen: Ich muß auch den anderen Städten das Evangelium vom Reiche Gottes verkündigen, denn dazu bin ich gesandt worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Und er predigte in den Synagogen von Galiläa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Es geschah aber, als die Volksmenge auf ihn andrängte, um das Wort Gottes zu hören, daß er an dem See Genezareth stand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'Und er sah zwei Schiffe am See stehen; die Fischer aber waren aus denselben getreten und wuschen ihre Netze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Er aber stieg in eines der Schiffe, welches Simon gehörte, und bat ihn, ein wenig vom Lande hinauszufahren; und er setzte sich und lehrte die Volksmengen vom Schiffe aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Als er aber aufhörte zu reden, sprach er zu Simon: Fahre hinaus auf die Tiefe und lasset eure Netze zu einem Fange hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Und Simon antwortete und sprach zu ihm: Meister, wir haben uns die ganze Nacht hindurch bemüht und nichts gefangen, aber auf dein Wort will ich das Netz hinablassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Und als sie dies getan hatten, umschlossen sie eine große Menge Fische, und ihr Netz riß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Und sie winkten ihren Genossen in dem anderen Schiffe, daß sie kämen und ihnen hülfen; und sie kamen, und sie füllten beide Schiffe, so daß sie sanken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Als aber Simon Petrus es sah, fiel er zu den Knieen Jesu nieder und sprach: Geh von mir hinaus, denn ich bin ein sündiger Mensch, Herr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Denn Entsetzen hatte ihn erfaßt und alle, die bei ihm waren, über den Fang der Fische, den sie getan hatten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'gleicherweise aber auch Jakobus und Johannes, die Söhne des Zebedäus, welche Genossen von Simon waren. Und Jesus sprach zu Simon: Fürchte dich nicht; von nun an wirst du Menschen fangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Und als sie die Schiffe ans Land gebracht hatten, verließen sie alles und folgten ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Und es geschah, als er in einer der Städte war, siehe, da war ein Mann voll Aussatz; und als er Jesum sah, fiel er auf sein Angesicht und bat ihn und sprach: Herr, wenn du willst, kannst du mich reinigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Und er streckte die Hand aus, rührte ihn an und sprach: Ich will; sei gereinigt! Und alsbald wich der Aussatz von ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Und er gebot ihm, es niemand zu sagen: Sondern gehe hin und zeige dich dem Priester und opfere für deine Reinigung, wie Moses geboten hat, ihnen zum Zeugnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Aber die Rede über ihn verbreitete sich um so mehr; und große Volksmengen versammelten sich, ihn zu hören und von ihren Krankheiten geheilt zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Er aber zog sich zurück und war in den Wüsteneien und betete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Und es geschah an einem der Tage, daß er lehrte; und es saßen da Pharisäer und Gesetzlehrer, welche aus jedem Dorfe von Galiläa und Judäa und aus Jerusalem gekommen waren; und des Herrn Kraft war da, um sie zu heilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Und siehe, Männer, welche auf einem Bett einen Menschen bringen, der gelähmt war; und sie suchten ihn hineinzubringen und vor ihn zu legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Und da sie nicht fanden, auf welchem Wege sie ihn hineinbringen sollten wegen der Volksmenge, stiegen sie auf das Dach und ließen ihn durch die Ziegel hinab mit dem Bettlein in die Mitte vor Jesum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Und als er ihren Glauben sah, sprach er: Mensch, deine Sünden sind dir vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Und die Schriftgelehrten und die Pharisäer fingen an zu überlegen, indem sie sagten: Wer ist dieser, der Lästerungen redet? Wer kann Sünden vergeben, außer Gott allein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Als aber Jesus ihre Überlegungen erkannte, antwortete und sprach er zu ihnen: Was überleget ihr in euren Herzen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Was ist leichter, zu sagen: Dir sind deine Sünden vergeben, oder zu sagen: Stehe auf und wandle?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Auf daß ihr aber wisset, daß der Sohn des Menschen Gewalt hat auf der Erde, Sünden zu vergeben... sprach er zu dem Gelähmten: Ich sage dir, stehe auf und nimm dein Bettlein auf und geh nach deinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Und alsbald stand er vor ihnen auf, nahm auf, worauf er gelegen hatte, und ging hin nach seinem Hause, indem er Gott verherrlichte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Und Staunen ergriff alle, und sie verherrlichten Gott und wurden mit Furcht erfüllt und sprachen: Wir haben heute außerordentliche Dinge gesehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Und nach diesem ging er hinaus und sah einen Zöllner, mit Namen Levi, am Zollhause sitzen und sprach zu ihm: Folge mir nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Und alles verlassend, stand er auf und folgte ihm nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Und Levi machte ihm ein großes Mahl in seinem Hause; und daselbst war eine große Menge Zöllner und anderer, die mit ihnen zu Tische lagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Und die Pharisäer und ihre Schriftgelehrten murrten gegen seine Jünger und sprachen: Warum esset und trinket ihr mit den Zöllnern und Sündern?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Und Jesus antwortete und sprach zu ihnen: Die Gesunden bedürfen nicht eines Arztes, sondern die Kranken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'ich bin nicht gekommen, Gerechte zu rufen, sondern Sünder zur Buße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Sie aber sprachen zu ihm: Warum fasten die Jünger Johannes\' oft und verrichten Gebete, gleicherweise auch die der Pharisäer; die deinigen aber essen und trinken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Jesus aber sprach zu ihnen: Ihr könnt doch nicht die Gefährten des Bräutigams fasten lassen, während der Bräutigam bei ihnen ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Es werden aber Tage kommen, und wann der Bräutigam von ihnen weggenommen sein wird, dann, in jenen Tagen, werden sie fasten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Er sagte aber auch ein Gleichnis zu ihnen: Niemand setzt einen Flicken von einem neuen Kleide auf ein altes Kleid; sonst wird er sowohl das neue zerschneiden, als auch der Flicken von dem neuen zum alten nicht passen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Und niemand tut neuen Wein in alte Schläuche; sonst wird der neue Wein die Schläuche zerreißen, und er selbst wird verschüttet werden, und die Schläuche werden verderben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'sondern neuen Wein tut man in neue Schläuche, und beide werden zusammen erhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Und niemand will, wenn er alten getrunken hat, alsbald neuen, denn er spricht: Der alte ist besser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Und es geschah am zweit-ersten Sabbath, daß er durch die Saaten ging, und seine Jünger die Ähren abpflückten und aßen, indem sie sie mit den Händen zerrieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Einige der Pharisäer aber sprachen zu ihnen: Warum tut ihr, was nicht erlaubt ist, am Sabbath zu tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Und Jesus antwortete und sprach zu ihnen: Habt ihr auch dieses nicht gelesen, was David tat, als ihn und die bei ihm waren hungerte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Wie er in das Haus Gottes ging und die Schaubrote nahm und aß, und auch denen gab, die bei ihm waren, welche niemand essen darf, als nur die Priester allein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Und er sprach zu ihnen: Der Sohn des Menschen ist Herr auch des Sabbaths.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Es geschah aber auch an einem anderen Sabbath, daß er in die Synagoge ging und lehrte; und es war daselbst ein Mensch, dessen rechte Hand verdorrt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Die Schriftgelehrten und die Pharisäer aber lauerten darauf, ob er am Sabbath heilen würde, auf daß sie eine Beschuldigung wider ihn fänden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Er aber wußte ihre Überlegungen und sprach zu dem Menschen, der die verdorrte Hand hatte: Stehe auf und stelle dich in die Mitte. Er aber stand auf und stellte sich hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Jesus sprach nun zu ihnen: Ich will euch fragen, ob es erlaubt ist, am Sabbath Gutes zu tun oder Böses zu tun, das Leben zu retten oder zu verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Und nachdem er sie alle umher angeblickt hatte, sprach er zu ihm: Strecke deine Hand aus! Und er tat also; und seine Hand wurde wiederhergestellt, wie die andere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Sie aber wurden mit Unverstand erfüllt und besprachen sich untereinander, was sie Jesu tun sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Und es geschah in selbigen Tagen, daß er auf den Berg hinausging, um zu beten; und er verharrte die Nacht im Gebet zu Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Und als es Tag wurde, rief er seine Jünger herzu und erwählte aus ihnen zwölf, die er auch Apostel nannte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simon, den er auch Petrus nannte, und Andreas, seinen Bruder, und Jakobus und Johannes, und Philippus und Bartholomäus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'und Matthäus und Thomas, und Jakobus, Alphäus\' Sohn, und Simon, genannt Zelotes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'und Judas, Jakobus\' Bruder, und Judas Iskariot, der auch sein Verräter wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Und als er mit ihnen herabgestiegen war, stand er auf einem ebenen Platze, und eine Menge seiner Jünger und eine große Menge des Volkes von ganz Judäa und Jerusalem und von der Seeküste von Tyrus und Sidon, welche kamen, ihn zu hören und von ihren Krankheiten geheilt zu werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'und die von unreinen Geistern Geplagten wurden geheilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'Und die ganze Volksmenge suchte ihn anzurühren, denn es ging Kraft von ihm aus und heilte alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Und er hob seine Augen auf zu seinen Jüngern und sprach: Glückselig ihr Armen, denn euer ist das Reich Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Glückselig, die ihr jetzt hungert, denn ihr werdet gesättigt werden. Glückselig, die ihr jetzt weinet, denn ihr werdet lachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Glückselig seid ihr, wenn die Menschen euch hassen werden, und wenn sie euch absondern und schmähen und euren Namen als böse verwerfen werden um des Sohnes des Menschen willen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'freuet euch an selbigem Tage und hüpfet, denn siehe, euer Lohn ist groß in dem Himmel; denn desgleichen taten ihre Väter den Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Aber wehe euch Reichen, denn ihr habt euren Trost dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Wehe euch, die ihr voll seid, denn ihr werdet hungern. Wehe euch, die ihr jetzt lachet, denn ihr werdet trauern und weinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Wehe, wenn alle Menschen wohl von euch reden; denn desgleichen taten ihre Väter den falschen Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Aber euch sage ich, die ihr höret: Liebet eure Feinde; tut wohl denen, die euch hassen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'segnet, die euch fluchen; betet für die, welche euch beleidigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Dem, der dich auf den Backen schlägt, biete auch den anderen dar; und dem, der dir den Mantel nimmt, wehre auch den Leibrock nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Gib jedem, der dich bittet; und von dem, der dir das Deinige nimmt, fordere es nicht zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Und wie ihr wollt, daß euch die Menschen tun sollen, tut auch ihr ihnen gleicherweise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Und wenn ihr liebet, die euch lieben, was für Dank ist es euch? Denn auch die Sünder lieben, die sie lieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Und wenn ihr denen Gutes tut, die euch Gutes tun, was für Dank ist es euch? Denn auch die Sünder tun dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Und wenn ihr denen leihet, von welchen ihr wieder zu empfangen hoffet, was für Dank ist es euch? Denn auch die Sünder leihen Sündern, auf daß sie das gleiche wieder empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Doch liebet eure Feinde, und tut Gutes, und leihet, ohne etwas wieder zu hoffen, und euer Lohn wird groß sein, und ihr werdet Söhne des Höchsten sein; denn er ist gütig gegen die Undankbaren und Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Seid nun barmherzig, wie auch euer Vater barmherzig ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Und richtet nicht, und ihr werdet nicht gerichtet werden; verurteilet nicht, und ihr werdet nicht verurteilt werden. Lasset los, und ihr werdet losgelassen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Gebet, und es wird euch gegeben werden: ein gutes, gedrücktes und gerütteltes und überlaufendes Maß wird man in euren Schoß geben; denn mit demselben Maße, mit welchem ihr messet, wird euch wieder gemessen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Er sagte aber auch ein Gleichnis zu ihnen: Kann etwa ein Blinder einen Blinden leiten? Werden nicht beide in eine Grube fallen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Ein Jünger ist nicht über den Lehrer; jeder aber, der vollendet ist, wird sein wie sein Lehrer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Was aber siehst du den Splitter, der in deines Bruders Auge ist, den Balken aber, der in deinem eigenen Auge ist, nimmst du nicht wahr?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Oder wie kannst du zu deinem Bruder sagen: Bruder, erlaube, ich will den Splitter herausziehen, der in deinem Auge ist, während du selbst den Balken in deinem Auge nicht siehst? Heuchler, ziehe zuerst den Balken aus deinem Auge, und dann wirst du klar sehen, um den Splitter herauszuziehen, der in deines Bruders Auge ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Denn es gibt keinen guten Baum, der faule Frucht bringt, noch einen faulen Baum, der gute Frucht bringt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'denn ein jeder Baum wird an seiner eigenen Frucht erkannt; denn von Dornen sammelt man nicht Feigen, noch liest man von einem Dornbusch Trauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Der gute Mensch bringt aus dem guten Schatze seines Herzens das Gute hervor, und der böse bringt aus dem bösen das Böse hervor; denn aus der Fülle des Herzens redet sein Mund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Was heißet ihr mich aber: Herr, Herr! und tut nicht, was ich sage?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Jeder, der zu mir kommt und meine Worte hört und sie tut, ich will euch zeigen, wem er gleich ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Er ist einem Menschen gleich, der ein Haus baute, welcher grub und vertiefte und den Grund auf den Felsen legte; als aber eine Flut kam, schlug der Strom an jenes Haus und vermochte es nicht zu erschüttern, denn es war auf den Felsen gegründet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Der aber gehört und nicht getan hat, ist einem Menschen gleich, der ein Haus auf die Erde baute ohne Grundlage, an welches der Strom schlug, und alsbald fiel es, und der Sturz jenes Hauses war groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Nachdem er aber alle seine Worte vor den Ohren des Volkes vollendet hatte, ging er hinein nach Kapernaum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Eines gewissen Hauptmanns Knecht aber, der ihm wert war, war krank und lag im Sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Als er aber von Jesu hörte, sandte er Älteste der Juden zu ihm und bat ihn, daß er käme und seinen Knecht gesund mache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Als diese aber zu Jesu hinkamen, baten sie ihn angelegentlich und sprachen: Er ist würdig, daß du ihm dies gewährest;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'denn er liebt unsere Nation, und er selbst hat uns die Synagoge erbaut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Jesus aber ging mit ihnen. Als er aber schon nicht mehr weit von dem Hause entfernt war, sandte der Hauptmann Freunde zu ihm und ließ ihm sagen: Herr, bemühe dich nicht, denn ich bin nicht würdig, daß du unter mein Dach tretest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Darum habe ich mich selbst auch nicht würdig geachtet, zu dir zu kommen; sondern sprich ein Wort, und mein Knecht wird gesund werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Denn auch ich bin ein Mensch, unter Gewalt gestellt, und habe Kriegsknechte unter mir; und ich sage zu diesem: Gehe hin, und er geht; und zu einem anderen: Komm, und er kommt; und zu meinem Knechte: Tue dieses, und er tut\'s.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Als Jesus dies hörte, verwunderte er sich über ihn; und er wandte sich zu der Volksmenge, die ihm folgte, und sprach: Ich sage euch, selbst nicht in Israel habe ich so großen Glauben gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Und als die Abgesandten in das Haus zurückkehrten, fanden sie den kranken Knecht gesund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Und es geschah danach, daß er in eine Stadt ging, genannt Nain, und viele seiner Jünger und eine große Volksmenge gingen mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Als er sich aber dem Tore der Stadt näherte, siehe, da wurde ein Toter herausgetragen, der eingeborene Sohn seiner Mutter, und sie war eine Witwe; und eine zahlreiche Volksmenge aus der Stadt war mit ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Und als der Herr sie sah, wurde er innerlich bewegt über sie und sprach zu ihr: Weine nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Und er trat hinzu und rührte die Bahre an, die Träger aber standen still; und er sprach: Jüngling, ich sage dir, stehe auf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Und der Tote setzte sich auf und fing an zu reden; und er gab ihn seiner Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Alle aber ergriff Furcht; und sie verherrlichten Gott und sprachen: Ein großer Prophet ist unter uns erweckt worden, und Gott hat sein Volk besucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Und diese Rede über ihn ging aus in ganz Judäa und in der ganzen Umgegend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Und dem Johannes berichteten seine Jünger über dies alles.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Und Johannes rief zwei seiner Jünger herzu und sandte sie zu Jesu und ließ ihm sagen: Bist du der Kommende, oder sollen wir auf einen anderen warten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Als aber die Männer zu ihm gekommen waren, sprachen sie: Johannes der Täufer hat uns zu dir gesandt und läßt dir sagen: Bist du der Kommende, oder sollen wir auf einen anderen warten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'In jener Stunde aber heilte er viele von Krankheiten und Plagen und bösen Geistern, und vielen Blinden schenkte er das Gesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Und Jesus antwortete und sprach zu ihnen: Gehet hin und verkündet Johannes, was ihr gesehen und gehört habt: daß Blinde sehend werden, Lahme wandeln, Aussätzige gereinigt werden, Taube hören, Tote auferweckt werden, Armen gute Botschaft verkündigt wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'und glückselig ist, wer irgend sich nicht an mir ärgern wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Als aber die Boten des Johannes weggegangen waren, fing er an, zu den Volksmengen zu reden über Johannes: Was seid ihr in die Wüste hinausgegangen zu sehen? Ein Rohr, vom Winde hin und her bewegt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Aber was seid ihr hinausgegangen zu sehen? Einen Menschen, mit weichen Kleidern angetan? Siehe, die in herrlicher Kleidung und in Üppigkeit leben, sind an den königlichen Höfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Aber was seid ihr hinausgegangen zu sehen? einen Propheten? Ja, sage ich euch, und mehr als einen Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Dieser ist es, von dem geschrieben steht: \"Siehe, ich sende meinen Boten vor deinem Angesicht her, der deinen Weg vor dir bereiten wird\";');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'denn ich sage euch: Unter den von Weibern Geborenen ist kein größerer Prophet als Johannes der Täufer; aber der Kleinste in dem Reiche Gottes ist größer als er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, '(Und das ganze Volk, das zuhörte, und die Zöllner rechtfertigten Gott, indem sie mit der Taufe Johannes\' getauft worden waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'die Pharisäer aber und die Gesetzesgelehrten machten in Bezug auf sich selbst den Ratschluß Gottes wirkungslos, indem sie nicht von ihm getauft worden waren.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'Wem soll ich nun die Menschen dieses Geschlechts vergleichen? und wem sind sie gleich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Sie sind Kindern gleich, die auf dem Markte sitzen und einander zurufen und sagen: Wir haben euch gepfiffen, und ihr habt nicht getanzt; wir haben euch Klagelieder gesungen, und ihr habt nicht geweint.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Denn Johannes der Täufer ist gekommen, der weder Brot aß, noch Wein trank, und ihr saget: Er hat einen Dämon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Der Sohn des Menschen ist gekommen, der da ißt und trinkt, und ihr saget: Siehe, ein Fresser und Weinsäufer, ein Freund von Zöllnern und Sündern; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'und die Weisheit ist gerechtfertigt worden von allen ihren Kindern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Es bat ihn aber einer der Pharisäer, daß er mit ihm essen möchte; und er ging in das Haus des Pharisäers und legte sich zu Tische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Und siehe, da war ein Weib in der Stadt, die eine Sünderin war; und als sie erfahren hatte, daß er in dem Hause des Pharisäers zu Tische liege, brachte sie eine Alabasterflasche mit Salbe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'und hinten zu seinen Füßen stehend und weinend, fing sie an, seine Füße mit Tränen zu benetzen; und sie trocknete sie mit den Haaren ihres Hauptes und küßte seine Füße sehr und salbte sie mit der Salbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Als es aber der Pharisäer sah, der ihn geladen hatte, sprach er bei sich selbst und sagte: Wenn dieser ein Prophet wäre, so würde er erkennen, wer und was für ein Weib es ist, die ihn anrührt; denn sie ist eine Sünderin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Und Jesus antwortete und sprach zu ihm: Simon, ich habe dir etwas zu sagen. Er aber spricht: Lehrer, sage an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Ein gewisser Gläubiger hatte zwei Schuldner; der eine schuldete fünfhundert Denare, der andere aber fünfzig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'da sie aber nicht hatten zu bezahlen, schenkte er es beiden. Wer nun von ihnen, sage wird ihn am meisten lieben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simon aber antwortete und sprach: Ich meine, dem er das meiste geschenkt hat. Er aber sprach zu ihm: Du hast recht geurteilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Und sich zu dem Weibe wendend, sprach er zu Simon: Siehst du dieses Weib? Ich bin in dein Haus gekommen, du hast mir kein Wasser auf meine Füße gegeben; diese aber hat meine Füße mit Tränen benetzt und mit ihren Haaren getrocknet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Du hast mir keinen Kuß gegeben; diese aber hat, seitdem ich hereingekommen bin, nicht abgelassen, meine Füße zu küssen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Du hast mein Haupt nicht mit Öl gesalbt; diese aber hat mit Salbe meine Füße gesalbt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Deswegen sage ich dir: Ihre vielen Sünden sind vergeben, denn sie hat viel geliebt; wem aber wenig vergeben wird, der liebt wenig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Er aber sprach zu ihr: Deine Sünden sind vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Und die mit zu Tische lagen, fingen an, bei sich selbst zu sagen: Wer ist dieser, der auch Sünden vergibt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Er sprach aber zu dem Weibe: Dein Glaube hat dich errettet; gehe hin in Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Und es geschah danach, daß er nacheinander Stadt und Dorf durchzog, indem er predigte und das Evangelium vom Reiche Gottes verkündigte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'und die Zwölfe mit ihm, und gewisse Weiber, die von bösen Geistern und Krankheiten geheilt worden waren: Maria, genannt Magdalene, von welcher sieben Dämonen ausgefahren waren,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'und Johanna, das Weib Chusas, des Verwalters Herodes\', und Susanna und viele andere Weiber, die ihm dienten mit ihrer Habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Als sich aber eine große Volksmenge versammelte und sie aus jeder Stadt zu ihm hinkamen, sprach er durch ein Gleichnis:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Der Sämann ging aus, seinen Samen zu säen; und indem er säte, fiel etliches an den Weg, und es wurde zertreten, und die Vögel des Himmels fraßen es auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Und anderes fiel auf den Felsen: und als es aufging, verdorrte es, weil es keine Feuchtigkeit hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Und anderes fiel mitten unter die Dornen; und indem die Dornen mit aufwuchsen, erstickten sie es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Und anderes fiel in die gute Erde und ging auf und brachte hundertfältige Frucht. Als er dies sagte, rief er aus: Wer Ohren hat zu hören, der höre!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Seine Jünger aber fragten ihn und sprachen: Was mag dieses Gleichnis sein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Er aber sprach: Euch ist es gegeben, die Geheimnisse des Reiches Gottes zu wissen, den übrigen aber in Gleichnissen, auf daß sie sehend nicht sehen und hörend nicht verstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Dies aber ist das Gleichnis: Der Same ist das Wort Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Die aber an dem Wege sind die, welche hören; dann kommt der Teufel und nimmt das Wort von ihren Herzen weg, auf daß sie nicht glauben und errettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Die aber auf dem Felsen sind die, welche, wenn sie hören, das Wort mit Freuden aufnehmen; und diese haben keine Wurzel, welche für eine Zeit glauben und in der Zeit der Versuchung abfallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Das aber unter die Dornen fiel sind diese, welche gehört haben und hingehen und durch Sorgen und Reichtum und Vergnügungen des Lebens erstickt werden und nichts zur Reife bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Das in der guten Erde aber sind diese, welche in einem redlichen und guten Herzen das Wort, nachdem sie es gehört haben, bewahren und Frucht bringen mit Ausharren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Niemand aber, der eine Lampe angezündet hat, bedeckt sie mit einem Gefäß oder stellt sie unter ein Bett, sondern er stellt sie auf ein Lampengestell, auf daß die Hereinkommenden das Licht sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Denn es ist nichts verborgen, was nicht offenbar werden wird, noch geheim, was nicht kundwerden und ans Licht kommen soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Sehet nun zu, wie ihr höret; denn wer irgend hat, dem wird gegeben werden, und wer irgend nicht hat, von dem wird selbst was er zu haben scheint genommen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Es kamen aber seine Mutter und seine Brüder zu ihm; und sie konnten wegen der Volksmenge nicht zu ihm gelangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Und es wurde ihm berichtet, indem man sagte: Deine Mutter und deine Brüder stehen draußen und wollen dich sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Er aber antwortete und sprach zu ihnen: Meine Mutter und meine Brüder sind diese, welche das Wort Gottes hören und tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Und es geschah an einem der Tage, daß er in ein Schiff stieg, er und seine Jünger; und er sprach zu ihnen: Laßt uns übersetzen an das jenseitige Ufer des Sees. Und sie fuhren ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Während sie aber fuhren, schlief er ein. Und es fiel ein Sturmwind auf den See, und das Schiff füllte sich mit Wasser, und sie waren in Gefahr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Sie traten aber hinzu und weckten ihn auf und sprachen: Meister, Meister, wir kommen um! Er aber stand auf, bedrohte den Wind und das Wogen des Wassers; und sie hörten auf, und es ward eine Stille.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Er aber sprach zu ihnen: Wo ist euer Glaube? Erschrocken aber erstaunten sie und sagten zueinander: Wer ist denn dieser, daß er auch den Winden und dem Wasser gebietet, und sie ihm gehorchen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Und sie fuhren nach dem Lande der Gadarener, welches Galiläa gegenüber ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Als er aber an das Land ausgestiegen war, kam ihm ein gewisser Mann aus der Stadt entgegen, der seit langer Zeit Dämonen hatte und keine Kleider anzog und nicht im Hause blieb, sondern in den Grabstätten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Als er aber Jesum sah, schrie er auf und fiel vor ihm nieder und sprach mit lauter Stimme: Was habe ich mit dir zu schaffen, Jesu, Sohn Gottes, des Höchsten? Ich bitte dich, quäle mich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Denn er hatte dem unreinen Geist geboten, von dem Menschen auszufahren. Denn öfters hatte er ihn ergriffen; und er war gebunden worden, verwahrt mit Ketten und Fußfesseln, und er zerbrach die Bande und wurde von dem Dämon in die Wüsteneien getrieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Jesus fragte ihn aber und sprach: Was ist dein Name? Er aber sprach: Legion; denn viele Dämonen waren in ihn gefahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Und sie baten ihn, daß er ihnen nicht gebieten möchte, in den Abgrund zu fahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Es war aber daselbst eine Herde vieler Schweine, welche an dem Berge weideten. Und sie baten ihn, daß er ihnen erlauben möchte, in jene zu fahren. Und er erlaubte es ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Die Dämonen aber fuhren von dem Menschen aus und fuhren in die Schweine, und die Herde stürzte sich den Abhang hinab in den See und ertrank.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Als aber die Hüter sahen, was geschehen war, flohen sie und verkündeten es in der Stadt und auf dem Lande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Sie aber gingen hinaus, um zu sehen, was geschehen war. Und sie kamen zu Jesu und fanden den Menschen, von welchem die Dämonen ausgefahren waren, bekleidet und vernünftig, zu den Füßen Jesu sitzend; und sie fürchteten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Die es gesehen hatten verkündeten ihnen aber auch, wie der Besessene geheilt worden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Und die ganze Menge der Umgegend der Gadarener bat ihn, von ihnen wegzugehen, denn sie waren von einer großen Furcht ergriffen. Er aber stieg in das Schiff und kehrte wieder zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Der Mann aber, von welchem die Dämonen ausgefahren waren, bat ihn, daß er bei ihm sein dürfe. Er aber entließ ihn und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Kehre in dein Haus zurück und erzähle, wieviel Gott an dir getan hat. Und er ging hin und rief aus durch die ganze Stadt, wieviel Jesus an ihm getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Es geschah aber, als Jesus zurückkehrte, nahm ihn das Volk auf, denn alle erwarteten ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Und siehe, es kam ein Mann, mit Namen Jairus (und er war Vorsteher der Synagoge), und fiel Jesu zu Füßen und bat ihn, in sein Haus zu kommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'denn er hatte eine eingeborene Tochter von etwa zwölf Jahren, und diese lag im Sterben. Indem er aber hinging, drängten ihn die Volksmengen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Und ein Weib, das seit zwölf Jahren mit einem Blutfluß behaftet war, welche, obgleich sie ihren ganzen Lebensunterhalt an die Ärzte verwandt hatte, von niemand geheilt werden konnte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'kam von hinten herzu und rührte die Quaste seines Kleides an; und alsbald stand der Fluß ihres Blutes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Und Jesus sprach: Wer ist es, der mich angerührt hat? Als aber alle leugneten, sprach Petrus und die mit ihm waren: Meister, die Volksmengen drängen und drücken dich, und du sagst: Wer ist es, der mich angerührt hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Jesus aber sprach: Es hat mich jemand angerührt; denn ich habe erkannt, daß Kraft von mir ausgegangen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Als das Weib aber sah, daß sie nicht verborgen blieb, kam sie zitternd und fiel vor ihm nieder und verkündete vor dem ganzen Volk, um welcher Ursache willen sie ihn angerührt habe, und wie sie alsbald geheilt worden sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Er aber sprach zu ihr: Sei gutes Mutes, Tochter, dein Glaube hat dich geheilt; gehe hin in Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Während er noch redete, kommt einer von dem Synagogenvorsteher und sagt zu ihm: Deine Tochter ist gestorben, bemühe den Lehrer nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Als aber Jesus es hörte, antwortete er ihm und sprach: Fürchte dich nicht, glaube nur, und sie wird gerettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Als er aber in das Haus kam, erlaubte er niemand hineinzugehen, außer Petrus und Johannes und Jakobus und dem Vater des Kindes und der Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Alle aber weinten und beklagten sie. Er aber sprach: Weinet nicht, denn sie ist nicht gestorben, sondern sie schläft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Und sie verlachten ihn, da sie wußten, daß sie gestorben war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Als er aber alle hinausgetrieben hatte, ergriff er sie bei der Hand und rief und sprach: Kind, stehe auf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Und ihr Geist kehrte zurück, und alsbald stand sie auf; und er befahl, ihr zu essen zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Und ihre Eltern gerieten außer sich; er aber gebot ihnen, niemand zu sagen, was geschehen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Als er aber die Zwölfe zusammengerufen hatte, gab er ihnen Kraft und Gewalt über alle Dämonen, und Krankheiten zu heilen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'und er sandte sie, das Reich Gottes zu predigen und die Kranken gesund zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Und er sprach zu ihnen: Nehmet nichts mit auf den Weg: weder Stab, noch Tasche, noch Brot, noch Geld, noch soll jemand zwei Leibröcke haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Und in welches Haus irgend ihr eintretet, daselbst bleibet, und von dannen gehet aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Und so viele euch etwa nicht aufnehmen werden, gehet fort aus jener Stadt und schüttelt auch den Staub von euren Füßen, zum Zeugnis wider sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Sie gingen aber aus und durchzogen die Dörfer nacheinander, indem sie das Evangelium verkündigten und überall heilten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Es hörte aber Herodes, der Vierfürst, alles was durch ihn geschehen war, und er war in Verlegenheit, weil von etlichen gesagt wurde, daß Johannes aus den Toten auferweckt worden sei;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'von etlichen aber, daß Elias erschienen, von anderen aber, daß einer der alten Propheten auferstanden sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Und Herodes sprach: Johannes habe ich enthauptet; wer aber ist dieser, von dem ich solches höre? Und er suchte ihn zu sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Und als die Apostel zurückkehrten, erzählten sie ihm alles, was sie getan hatten; und er nahm sie mit und zog sich besonders zurück nach einem öden Ort einer Stadt, mit Namen Bethsaida.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Als aber die Volksmengen es erfuhren, folgten sie ihm; und er nahm sie auf und redete zu ihnen vom Reiche Gottes, und die der Heilung bedurften, machte er gesund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Der Tag aber begann sich zu neigen, und die Zwölfe traten herzu und sprachen zu ihm: Entlaß die Volksmenge, auf daß sie in die Dörfer ringsum und aufs Land gehen und Herberge und Speise finden; denn hier sind wir an einem öden Orte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Er sprach aber zu ihnen: Gebet ihr ihnen zu essen. Sie aber sprachen: Wir haben nicht mehr als fünf Brote und zwei Fische, es sei denn, daß wir hingingen und für dieses ganze Volk Speise kauften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Denn es waren bei fünftausend Mann. Er sprach aber zu seinen Jüngern: Laßt sie sich reihenweise zu je fünfzig niederlegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Und sie taten also und ließen alle sich lagern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Er nahm aber die fünf Brote und die zwei Fische, blickte auf gen Himmel und segnete sie; und er brach sie und gab sie den Jüngern, um der Volksmenge vorzulegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Und sie aßen und wurden alle gesättigt; und es wurde aufgehoben, was ihnen an Brocken übriggeblieben war, zwölf Handkörbe voll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Und es geschah, als er allein betete, waren die Jünger bei ihm; und er fragte sie und sprach: Wer sagen die Volksmengen, daß ich sei?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Sie aber antworteten und sprachen: Johannes der Täufer; andere aber: Elias; andere aber, daß einer der alten Propheten auferstanden sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Er sprach aber zu ihnen: Ihr aber, wer saget ihr, daß ich sei? Petrus aber antwortete und sprach: Der Christus Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Er aber bedrohte sie und gebot ihnen, dies niemand zu sagen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'und sprach: Der Sohn des Menschen muß vieles leiden und verworfen werden von den Ältesten und Hohenpriestern und Schriftgelehrten, und getötet und am dritten Tage auferweckt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Er sprach aber zu allen: Wenn jemand mir nachkommen will, der verleugne sich selbst und nehme sein Kreuz auf täglich und folge mir nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Denn wer irgend sein Leben erretten will, wird es verlieren; wer aber irgend sein Leben verliert um meinetwillen, der wird es erretten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Denn was wird es einem Menschen nützen, wenn er die ganze Welt gewönne, sich selbst aber verlöre oder einbüßte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Denn wer irgend sich meiner und meiner Worte schämt, dessen wird der Sohn des Menschen sich schämen, wenn er kommen wird in seiner Herrlichkeit und der des Vaters und der heiligen Engel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Ich sage euch aber in Wahrheit: Es sind etliche von denen, die hier stehen, welche den Tod nicht schmecken werden, bis sie das Reich Gottes gesehen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Es geschah aber bei acht Tagen nach diesen Worten, daß er Petrus und Johannes und Jakobus mitnahm und auf den Berg stieg, um zu beten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Und indem er betete, wurde das Aussehen seines Angesichts anders und sein Gewand weiß, strahlend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Und siehe, zwei Männer redeten mit ihm, welche Moses und Elias waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Diese erschienen in Herrlichkeit und besprachen seinen Ausgang, den er in Jerusalem erfüllen sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Petrus aber und die mit ihm waren, waren beschwert vom Schlaf; als sie aber völlig aufgewacht waren, sahen sie seine Herrlichkeit und die zwei Männer, welche bei ihm standen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Und es geschah, als sie von ihm schieden, sprach Petrus zu Jesu: Meister, es ist gut, daß wir hier sind; und laß uns drei Hütten machen, dir eine und Moses eine und Elias eine; und er wußte nicht, was er sagte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Als er aber dies sagte, kam eine Wolke und überschattete sie. Sie fürchteten sich aber, als sie in die Wolke eintraten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'und es geschah eine Stimme aus der Wolke, welche sagte: Dieser ist mein geliebter Sohn, ihn höret.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Und indem die Stimme geschah, wurde Jesus allein gefunden. Und sie schwiegen und verkündeten in jenen Tagen niemand etwas von dem, was sie gesehen hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Es geschah aber an dem folgenden Tage, als sie von dem Berge herabgestiegen waren, kam ihm eine große Volksmenge entgegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Und siehe, ein Mann aus der Volksmenge rief laut und sprach: Lehrer, ich bitte dich, blicke hin auf meinen Sohn, denn er ist mein eingeborener;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'und siehe, ein Geist ergreift ihn, und plötzlich schreit er, und er zerrt ihn unter Schäumen, und mit Mühe weicht er von ihm, indem er ihn aufreibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Und ich bat deine Jünger, daß sie ihn austreiben möchten, und sie konnten es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Jesus aber antwortete und sprach: O ungläubiges und verkehrtes Geschlecht, bis wann soll ich bei euch sein und euch ertragen? Bringe deinen Sohn her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Während er aber noch herzukam, riß ihn der Dämon und zog ihn zerrend zusammen. Jesus aber bedrohte den unreinen Geist und heilte den Knaben und gab ihn seinem Vater zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Sie erstaunten aber alle sehr über die herrliche Größe Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Als sich aber alle verwunderten über alles, was Jesus tat, sprach er zu seinen Jüngern: Fasset ihr diese Worte in eure Ohren; denn der Sohn des Menschen wird überliefert werden in der Menschen Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Sie aber verstanden dieses Wort nicht, und es war vor ihnen verborgen, auf daß sie es nicht vernähmen; und sie fürchteten sich, ihn über dieses Wort zu fragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Es entstand aber unter ihnen eine Überlegung, wer wohl der Größte unter ihnen wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Als Jesus aber die Überlegung ihres Herzens sah, nahm er ein Kindlein und stellte es neben sich');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'und sprach zu ihnen: Wer irgend dieses Kindlein aufnehmen wird in meinem Namen, nimmt mich auf; und wer irgend mich aufnehmen wird, nimmt den auf, der mich gesandt hat; denn wer der Kleinste ist unter euch allen, der ist groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Johannes aber antwortete und sprach: Meister, wir sahen jemand Dämonen austreiben in deinem Namen, und wir wehrten ihm, weil er dir nicht mit uns nachfolgt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Und Jesus sprach zu ihm: Wehret nicht; denn wer nicht wider euch ist, ist für euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Es geschah aber, als sich die Tage seiner Aufnahme erfüllten, daß er sein Angesicht feststellte, nach Jerusalem zu gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Und er sandte Boten vor seinem Angesicht her; und sie gingen hin und kamen in ein Dorf der Samariter, um für ihn zuzubereiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Und sie nahmen ihn nicht auf, weil sein Angesicht nach Jerusalem hin gerichtet war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Als aber seine Jünger Jakobus und Johannes es sahen, sprachen sie: Herr, willst du, daß wir Feuer vom Himmel herabfallen und sie verzehren heißen, wie auch Elias tat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Er wandte sich aber um und strafte sie und sprach: Ihr wisset nicht, wes Geistes ihr seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Und sie gingen nach einem anderen Dorfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Es geschah aber, als sie auf dem Wege dahinzogen, sprach einer zu ihm: Ich will dir nachfolgen, wohin irgend du gehst, Herr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Und Jesus sprach zu ihm: Die Füchse haben Höhlen und die Vögel des Himmels Nester; aber der Sohn des Menschen hat nicht, wo er sein Haupt hinlege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Er sprach aber zu einem anderen: Folge mir nach. Der aber sprach: Herr, erlaube mir zuvor hinzugehen und meinen Vater zu begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Jesus aber sprach zu ihm: Laß die Toten ihre Toten begraben, du aber gehe hin und verkündige das Reich Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Es sprach aber auch ein anderer: Ich will dir nachfolgen, Herr; zuvor aber erlaube mir, Abschied zu nehmen von denen, die in meinem Hause sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Jesus aber sprach zu ihm: Niemand, der seine Hand an den Pflug gelegt hat und zurückblickt, ist geschickt zum Reiche Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Nach diesem aber bestellte der Herr auch siebzig andere und sandte sie zu je zwei vor seinem Angesicht her in jede Stadt und jeden Ort, wohin er selbst kommen wollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Er sprach aber zu ihnen: Die Ernte zwar ist groß, der Arbeiter aber sind wenige. Bittet nun den Herrn der Ernte, daß er Arbeiter aussende in seine Ernte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Gehet hin! Siehe, ich sende euch wie Lämmer inmitten von Wölfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Traget weder Börse noch Tasche, noch Sandalen, und grüßet niemand auf dem Wege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'In welches Haus irgend ihr aber eintretet, sprechet zuerst: Friede diesem Hause!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Und wenn daselbst ein Sohn des Friedens ist, so wird euer Friede auf demselben ruhen; wenn aber nicht, so wird er zu euch zurückkehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'In demselben Hause aber bleibet, und esset und trinket, was sie haben; denn der Arbeiter ist seines Lohnes wert. Gehet nicht aus einem Hause in ein anderes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Und in welche Stadt irgend ihr eintretet, und sie nehmen euch auf, da esset, was euch vorgesetzt wird, und heilet die Kranken in ihr');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'und sprechet zu ihnen: Das Reich Gottes ist nahe zu euch gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'In welche Stadt irgend ihr aber eingetreten seid, und sie nehmen euch nicht auf, da gehet hinaus auf ihre Straßen und sprechet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Auch den Staub, der uns aus eurer Stadt an den Füßen hängt, schütteln wir gegen euch ab; doch dieses wisset, daß das Reich Gottes nahe gekommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Ich sage euch, daß es Sodom an jenem Tage erträglicher ergehen wird als jener Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Wehe dir, Chorazin! Wehe dir, Bethsaida! Denn wenn in Tyrus und Sidon die Wunderwerke geschehen wären, die unter euch geschehen sind, längst hätten sie, in Sack und Asche sitzend, Buße getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Doch Tyrus und Sidon wird es erträglicher ergehen im Gericht als euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Und du, Kapernaum, die du bis zum Himmel erhöht worden bist, bis zum Hades wirst du hinabgestoßen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Wer euch hört, hört mich; und wer euch verwirft, verwirft mich; wer aber mich verwirft, verwirft den, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Die Siebzig aber kehrten mit Freuden zurück und sprachen: Herr, auch die Dämonen sind uns untertan in deinem Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Er sprach aber zu ihnen: Ich schaute den Satan wie einen Blitz vom Himmel fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Siehe, ich gebe euch die Gewalt, auf Schlangen und Skorpionen zu treten, und über die ganze Kraft des Feindes, und nichts soll euch irgendwie beschädigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Doch darüber freuet euch nicht, daß euch die Geister untertan sind; freuet euch aber, daß eure Namen in den Himmeln angeschrieben sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'In selbiger Stunde frohlockte Jesus im Geiste und sprach: Ich preise dich, Vater, Herr des Himmels und der Erde, daß du dies vor Weisen und Verständigen verborgen hast, und hast es Unmündigen geoffenbart. Ja, Vater, denn also war es wohlgefällig vor dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Alles ist mir übergeben von meinem Vater; und niemand erkennt, wer der Sohn ist, als nur der Vater; und wer der Vater ist, als nur der Sohn, und wem irgend der Sohn ihn offenbaren will.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Und er wandte sich zu den Jüngern besonders und sprach: Glückselig die Augen, welche sehen, was ihr sehet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Denn ich sage euch, daß viele Propheten und Könige begehrt haben zu sehen, was ihr sehet, und haben es nicht gesehen, und zu hören, was ihr höret, und haben es nicht gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Und siehe, ein gewisser Gesetzgelehrter stand auf und versuchte ihn und sprach: Lehrer, was muß ich getan haben, um ewiges Leben zu ererben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Er aber sprach zu ihm: Was steht in dem Gesetz geschrieben? Wie liesest du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Er aber antwortete und sprach: \"Du sollst den Herrn, deinen Gott, lieben aus deinem ganzen Herzen und mit deiner ganzen Seele und mit deiner ganzen Kraft und mit deinem ganzen Verstande, und deinen Nächsten wie dich selbst\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Er sprach aber zu ihm: Du hast recht geantwortet; tue dies, und du wirst leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Indem er aber sich selbst rechtfertigen wollte, sprach er zu Jesu: Und wer ist mein Nächster?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Jesus aber erwiderte und sprach: Ein gewisser Mensch ging von Jerusalem nach Jericho hinab und fiel unter Räuber, die ihn auch auszogen und ihm Schläge versetzten und weggingen und ihn halbtot liegen ließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Von ungefähr aber ging ein gewisser Priester jenes Weges hinab; und als er ihn sah, ging er an der entgegengesetzten Seite vorüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Gleicherweise aber auch ein Levit, der an den Ort gelangte, kam und sah ihn und ging an der entgegengesetzten Seite vorüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Aber ein gewisser Samariter, der auf der Reise war, kam zu ihm hin; und als er ihn sah, wurde er innerlich bewegt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'und er trat hinzu und verband seine Wunden und goß Öl und Wein darauf; und er setzte ihn auf sein eigenes Tier und führte ihn in eine Herberge und trug Sorge für ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Und am folgenden Morgen als er fortreiste zog er zwei Denare heraus und gab sie dem Wirt und sprach zu ihm: Trage Sorge für ihn; und was irgend du noch dazu verwenden wirst, werde ich dir bezahlen, wenn ich zurückkomme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Wer von diesen dreien dünkt dich der Nächste gewesen zu sein von dem, der unter die Räuber gefallen war?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Er aber sprach: Der die Barmherzigkeit an ihm tat. Jesus aber sprach zu ihm: Gehe hin und tue du desgleichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Es geschah aber, als sie ihres Weges zogen, daß er in ein Dorf kam; und ein gewisses Weib, mit Namen Martha, nahm ihn in ihr Haus auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Und diese hatte eine Schwester, genannt Maria, die sich auch zu den Füßen Jesu niedersetzte und seinem Worte zuhörte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Martha aber war sehr beschäftigt mit vielem Dienen; sie trat aber hinzu und sprach: Herr, kümmert es dich nicht, daß meine Schwester mich allein gelassen hat zu dienen? Sage ihr nun, daß sie mir helfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Jesus aber antwortete und sprach zu ihr: Martha, Martha! Du bist besorgt und beunruhigt um viele Dinge;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'eines aber ist not. Maria aber hat das gute Teil erwählt, welches nicht von ihr genommen werden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Und es geschah, als er an einem gewissen Orte war und betete, da sprach, als er aufhörte, einer seiner Jünger zu ihm: Herr, lehre uns beten, wie auch Johannes seine Jünger lehrte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Er sprach aber zu ihnen: Wenn ihr betet, so sprechet: Vater, geheiligt werde dein Name; dein Reich komme;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'unser nötiges Brot gib uns täglich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'und vergib uns unsere Sünden, denn auch wir selbst vergeben jedem, der uns schuldig ist; und führe uns nicht in Versuchung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Und er sprach zu ihnen: Wer von euch wird einen Freund haben und wird um Mitternacht zu ihm gehen und zu ihm sagen: Freund, leihe mir drei Brote,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'da mein Freund von der Reise bei mir angelangt ist, und ich nicht habe, was ich ihm vorsetzen soll; -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'und jener würde von innen antworten und sagen: Mache mir keine Mühe, die Tür ist schon geschlossen, und meine Kinder sind bei mir im Bett; ich kann nicht aufstehen und dir geben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Ich sage euch, wenn er auch nicht aufstehen und ihm geben wird, weil er sein Freund ist, so wird er wenigstens um seiner Unverschämtheit willen aufstehen und ihm geben, soviel er bedarf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Und ich sage euch: Bittet, und es wird euch gegeben werden; suchet, und ihr werdet finden; klopfet an, und es wird euch aufgetan werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Denn jeder Bittende empfängt, und der Suchende findet, und dem Anklopfenden wird aufgetan werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Wer aber ist ein Vater unter euch, den der Sohn um Brot bitten wird, er wird ihm doch nicht einen Stein geben? Oder auch um einen Fisch, er wird ihm statt des Fisches doch nicht eine Schlange geben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Oder auch, wenn er um ein Ei bäte, er wird ihm doch nicht einen Skorpion geben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Wenn nun ihr, die ihr böse seid, euren Kindern gute Gaben zu geben wisset, wieviel mehr wird der Vater, der vom Himmel ist, den Heiligen Geist geben denen, die ihn bitten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Und er trieb einen Dämon aus, und derselbe war stumm. Es geschah aber, als der Dämon ausgefahren war, redete der Stumme; und die Volksmengen verwunderten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Einige aber von ihnen sagten: Durch Beelzebub, den Obersten der Dämonen, treibt er die Dämonen aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Andere aber, ihn versuchend, forderten von ihm ein Zeichen aus dem Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Da er aber ihre Gedanken wußte, sprach er zu ihnen: Jedes Reich, das wider sich selbst entzweit ist, wird verwüstet, und Haus wider Haus entzweit, fällt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Wenn aber auch der Satan wider sich selbst entzweit ist, wie wird sein Reich bestehen? Weil ihr saget, daß ich durch Beelzebub die Dämonen austreibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Wenn aber ich durch Beelzebub die Dämonen austreibe, durch wen treiben eure Söhne sie aus? Darum werden sie eure Richter sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Wenn ich aber durch den Finger Gottes die Dämonen austreibe, so ist also das Reich Gottes zu euch hingekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Wenn der Starke bewaffnet seinen Hof bewacht, so ist seine Habe in Frieden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'wenn aber ein Stärkerer als er über ihn kommt und ihn besiegt, so nimmt er seine ganze Waffenrüstung weg, auf welche er vertraute, und seine Beute teilt er aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Wer nicht mit mir ist, ist wider mich; und wer nicht mit mir sammelt, zerstreut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Wenn der unreine Geist von dem Menschen ausgefahren ist, so durchwandert er dürre Örter, Ruhe suchend; und da er sie nicht findet, spricht er: Ich will in mein Haus zurückkehren, von wo ich ausgegangen bin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'und wenn er kommt, findet er es gekehrt und geschmückt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Dann geht er hin und nimmt sieben andere Geister mit, böser als er selbst, und sie gehen hinein und wohnen daselbst; und das Letzte jenes Menschen wird ärger als das Erste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Es geschah aber, indem er dies sagte, erhob ein gewisses Weib aus der Volksmenge ihre Stimme und sprach zu ihm: Glückselig der Leib, der dich getragen, und die Brüste, die du gesogen hast!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Er aber sprach: Ja, vielmehr glückselig, die das Wort Gottes hören und bewahren!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Als aber die Volksmengen sich zusammendrängten, fing er an zu sagen: Dieses Geschlecht ist ein böses Geschlecht; es fordert ein Zeichen, und kein Zeichen wird ihm gegeben werden, als nur das Zeichen Jonas\'.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Denn gleichwie Jonas den Niniviten ein Zeichen war, so wird es auch der Sohn des Menschen diesem Geschlecht sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Eine Königin des Südens wird auftreten im Gericht mit den Männern dieses Geschlechts und wird sie verdammen; denn sie kam von den Enden der Erde, um die Weisheit Salomons zu hören; und siehe, mehr als Salomon ist hier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Männer von Ninive werden aufstehen im Gericht mit diesem Geschlecht und werden es verdammen; denn sie taten Buße auf die Predigt Jonas\'; und siehe, mehr als Jonas ist hier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Niemand aber, der eine Lampe angezündet hat, stellt sie ins Verborgene, noch unter den Scheffel, sondern auf das Lampengestell, auf daß die Hereinkommenden den Schein sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Die Lampe des Leibes ist dein Auge; wenn dein Auge einfältig ist, so ist auch dein ganzer Leib licht; wenn es aber böse ist, so ist auch dein Leib finster.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Sieh nun zu, daß das Licht, welches in dir ist, nicht Finsternis ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Wenn nun dein ganzer Leib licht ist und keinen finsteren Teil hat, so wird er ganz licht sein, wie wenn die Lampe mit ihrem Strahle dich erleuchtete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Indem er aber redete, bat ihn ein gewisser Pharisäer, daß er bei ihm zu Mittag essen möchte; er ging aber hinein und legte sich zu Tische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Als aber der Pharisäer es sah, verwunderte er sich, daß er sich nicht erst vor dem Essen gewaschen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Der Herr aber sprach zu ihm: Jetzt, ihr Pharisäer, reiniget ihr das Äußere des Bechers und der Schüssel, euer Inneres aber ist voller Raub und Bosheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Toren! Hat nicht der, welcher das Äußere gemacht hat, auch das Innere gemacht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Gebet vielmehr Almosen von dem, was ihr habt, und siehe, alles ist euch rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Aber wehe euch Pharisäern! Denn ihr verzehntet die Krausemünze und die Raute und alles Kraut, und übergehet das Gericht und die Liebe Gottes; diese Dinge hättet ihr tun und jene nicht lassen sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Wehe euch Pharisäern! Denn ihr liebet den ersten Sitz in den Synagogen und die Begrüßungen auf den Märkten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Wehe euch! Denn ihr seid wie die Grüfte, die verborgen sind, und die Menschen, die darüber wandeln, wissen es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Aber einer der Gesetzgelehrten antwortete und spricht zu ihm: Lehrer, indem du dieses sagst, schmähst du auch uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Er aber sprach: Auch euch Gesetzgelehrten wehe! Denn ihr belastet die Menschen mit schwer zu tragenden Lasten, und selbst rühret ihr die Lasten nicht mit einem eurer Finger an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Wehe euch! Denn ihr bauet die Grabmäler der Propheten, eure Väter aber haben sie getötet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Also gebet ihr Zeugnis und stimmet den Werken eurer Väter bei; denn sie haben sie getötet, ihr aber bauet ihre Grabmäler.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Darum hat auch die Weisheit Gottes gesagt: Ich werde Propheten und Apostel zu ihnen senden, und etliche von ihnen werden sie töten und vertreiben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'auf daß das Blut aller Propheten, welches von Grundlegung der Welt an vergossen worden ist, von diesem Geschlecht gefordert werde:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'von dem Blute Abels bis zu dem Blute Zacharias\', welcher umkam zwischen dem Altar und dem Hause; ja, sage ich euch, es wird von diesem Geschlecht gefordert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Wehe euch Gesetzgelehrten! Denn ihr habt den Schlüssel der Erkenntnis weggenommen; ihr selbst seid nicht hineingegangen, und die Hineingehenden habt ihr gehindert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Als er aber dies zu ihnen sagte, fingen die Schriftgelehrten und die Pharisäer an, hart auf ihn einzudringen und ihn über vieles auszufragen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'und sie lauerten auf ihn, etwas aus seinem Munde zu erjagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Als sich unterdessen viele Tausende der Volksmenge versammelt hatten, so daß sie einander traten, fing er an, zu seinen Jüngern zu sagen, zuerst: Hütet euch vor dem Sauerteig der Pharisäer, welcher Heuchelei ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Es ist aber nichts verdeckt, was nicht aufgedeckt, und verborgen, was nicht kundwerden wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'deswegen, soviel ihr in der Finsternis gesprochen haben werdet, wird im Lichte gehört werden, und was ihr ins Ohr gesprochen haben werdet in den Kammern, wird auf den Dächern ausgerufen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Ich sage aber euch, meinen Freunden: Fürchtet euch nicht vor denen, die den Leib töten und nach diesem nichts weiter zu tun vermögen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Ich will euch aber zeigen, wen ihr fürchten sollt: Fürchtet den, der nach dem Töten Gewalt hat, in die Hölle zu werfen; ja, sage ich euch, diesen fürchtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Werden nicht fünf Sperlinge um zwei Pfennig verkauft? Und nicht einer von ihnen ist vor Gott vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Aber selbst die Haare eures Hauptes sind alle gezählt. So fürchtet euch nun nicht; ihr seid vorzüglicher als viele Sperlinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Ich sage euch aber: Jeder, der irgend mich vor den Menschen bekennen wird, den wird auch der Sohn des Menschen vor den Engeln Gottes bekennen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'wer aber mich vor den Menschen verleugnet haben wird, der wird vor den Engeln Gottes verleugnet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Und jeder, der ein Wort sagen wird wider den Sohn des Menschen, dem wird vergeben werden; dem aber, der wider den Heiligen Geist lästert, wird nicht vergeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Wenn sie euch aber vor die Synagogen und die Obrigkeiten und die Gewalten führen, so sorget nicht, wie oder womit ihr euch verantworten oder was ihr sagen sollt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'denn der Heilige Geist wird euch in selbiger Stunde lehren, was ihr sagen sollt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Einer aus der Volksmenge aber sprach zu ihm: Lehrer, sage meinem Bruder, daß er das Erbe mit mir teile.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Er aber sprach zu ihm: Mensch, wer hat mich zu einem Richter oder Erbteiler über euch gesetzt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Er sprach aber zu ihnen: Sehet zu und hütet euch vor aller Habsucht, denn nicht weil jemand Überfluß hat, besteht sein Leben von seiner Habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Er sagte aber ein Gleichnis zu ihnen und sprach: Das Land eines gewissen reichen Menschen trug viel ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'Und er überlegte bei sich selbst und sprach: Was soll ich tun? Denn ich habe nicht, wohin ich meine Früchte einsammeln soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Und er sprach: Dies will ich tun: ich will meine Scheunen niederreißen und größere bauen, und will dahin all mein Gewächs und meine Güter einsammeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'und ich will zu meiner Seele sagen: Seele, du hast viele Güter daliegen auf viele Jahre; ruhe aus, iß, trink, sei fröhlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Gott aber sprach zu ihm: Du Tor! In dieser Nacht wird man deine Seele von dir fordern; was du aber bereitet hast, für wen wird es sein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Also ist der für sich Schätze sammelt, und ist nicht reich in Bezug auf Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Er sprach aber zu seinen Jüngern: Deshalb sage ich euch: Seid nicht besorgt für das Leben, was ihr essen, noch für den Leib, was ihr anziehen sollt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Das Leben ist mehr als die Nahrung, und der Leib mehr als die Kleidung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Betrachtet die Raben, daß sie nicht säen noch ernten, die weder Vorratskammer noch Scheune haben, und Gott ernährt sie; um wieviel vorzüglicher seid ihr als die Vögel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Wer aber unter euch vermag mit Sorgen seiner Größe eine Elle zuzusetzen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Wenn ihr nun auch das Geringste nicht vermöget, warum seid ihr um das Übrige besorgt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Betrachtet die Lilien, wie sie wachsen; sie mühen sich nicht und spinnen auch nicht. Ich sage euch aber, selbst nicht Salomon in all seiner Herrlichkeit war bekleidet wie eine von diesen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Wenn aber Gott das Gras, das heute auf dem Felde ist und morgen in den Ofen geworfen wird, also kleidet, wieviel mehr euch, Kleingläubige!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Und ihr, trachtet nicht danach, was ihr essen oder was ihr trinken sollt, und seid nicht in Unruhe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'denn nach diesem allem trachten die Nationen der Welt; euer Vater aber weiß, daß ihr dieses bedürfet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Trachtet jedoch nach seinem Reiche, und dieses wird euch hinzugefügt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Fürchte dich nicht, du kleine Herde, denn es hat eurem Vater wohlgefallen, euch das Reich zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Verkaufet eure Habe und gebet Almosen; machet euch Säckel, die nicht veralten, einen Schatz, unvergänglich, in den Himmeln, wo kein Dieb sich naht und keine Motte verderbt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Denn wo euer Schatz ist, da wird auch euer Herz sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Es seien eure Lenden umgürtet und die Lampen brennend;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'und ihr, seid Menschen gleich, die auf ihren Herrn warten, wann irgend er aufbrechen mag von der Hochzeit, auf daß, wenn er kommt und anklopft, sie ihm alsbald aufmachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Glückselig jene Knechte, die der Herr, wenn er kommt, wachend finden wird! Wahrlich, ich sage euch: Er wird sich umgürten und sie sich zu Tische legen lassen und wird hinzutreten und sie bedienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Und wenn er in der zweiten Wache kommt und in der dritten Wache kommt und findet sie also, glückselig sind jene Knechte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Dies aber erkennet: Wenn der Hausherr gewußt hätte, zu welcher Stunde der Dieb kommen würde, so hätte er gewacht und nicht erlaubt, daß sein Haus durchgraben würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Auch ihr nun, seid bereit; denn in der Stunde, in welcher ihr es nicht meinet, kommt der Sohn des Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Petrus aber sprach zu ihm: Herr, sagst du dieses Gleichnis zu uns oder auch zu allen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Der Herr aber sprach: Wer ist nun der treue und kluge Verwalter, welchen der Herr über sein Gesinde setzen wird, um ihm die zugemessene Speise zu geben zur rechten Zeit?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Glückselig jener Knecht, den sein Herr, wenn er kommt, also tuend finden wird!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'In Wahrheit sage ich euch, daß er ihn über seine ganze Habe setzen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Wenn aber jener Knecht in seinem Herzen sagt: Mein Herr verzieht zu kommen, und anfängt, die Knechte und Mägde zu schlagen und zu essen und zu trinken und sich zu berauschen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'so wird der Herr jenes Knechtes kommen an einem Tage, an welchem er es nicht erwartet, und in einer Stunde, die er nicht weiß, und wird ihn entzweischneiden und ihm sein Teil setzen mit den Untreuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Jener Knecht aber, der den Willen seines Herrn wußte und sich nicht bereitet, noch nach seinem Willen getan hat, wird mit vielen Schlägen geschlagen werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'wer ihn aber nicht wußte, aber getan hat, was der Schläge wert ist, wird mit wenigen geschlagen werden. Jedem aber, dem viel gegeben ist, viel wird von ihm verlangt werden; und wem man viel anvertraut hat, von dem wird man desto mehr fordern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Ich bin gekommen, Feuer auf die Erde zu werfen; und was will ich, wenn es schon angezündet ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Ich habe aber eine Taufe, womit ich getauft werden muß, und wie bin ich beengt, bis sie vollbracht ist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Denket ihr, daß ich gekommen sei, Frieden auf der Erde zu geben? Nein, sage ich euch, sondern vielmehr Entzweiung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Denn es werden von nun an fünf in einem Hause entzweit sein; drei werden wider zwei und zwei wider drei entzweit sein:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Vater wider Sohn und Sohn wider Vater, Mutter wider Tochter und Tochter wider Mutter, Schwiegermutter wider ihre Schwiegertochter und Schwiegertochter wider ihre Schwiegermutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Er sprach aber auch zu den Volksmengen: Wenn ihr eine Wolke von Westen aufsteigen sehet, so saget ihr alsbald: Ein Regenguß kommt; und es geschieht also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Und wenn ihr den Südwind wehen sehet, so saget ihr: Es wird Hitze geben; und es geschieht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Heuchler! Das Angesicht der Erde und des Himmels wisset ihr zu beurteilen; wie aber ist es, daß ihr diese Zeit nicht beurteilet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Warum aber auch richtet ihr von euch selbst nicht, was recht ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Denn wenn du mit deiner Gegenpartei vor die Obrigkeit gehst, so gib dir auf dem Wege Mühe, von ihr loszukommen, damit sie dich nicht etwa zu dem Richter hinschleppe; und der Richter wird dich dem Gerichtsdiener überliefern, und der Gerichtsdiener dich ins Gefängnis werfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Ich sage dir: Du wirst nicht von dannen herauskommen, bis du auch den letzten Heller bezahlt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Zu selbiger Zeit waren aber einige gegenwärtig, die ihm von den Galiläern berichteten, deren Blut Pilatus mit ihren Schlachtopfern vermischt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Und er antwortete und sprach zu ihnen: Meinet ihr, daß diese Galiläer vor allen Galiläern Sünder waren, weil sie solches erlitten haben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Nein, sage ich euch, sondern wenn ihr nicht Buße tut, werdet ihr alle ebenso umkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Oder jene achtzehn, auf welche der Turm in Siloam fiel und sie tötete: meinet ihr, daß sie vor allen Menschen, die in Jerusalem wohnen, Schuldner waren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Nein, sage ich euch, sondern wenn ihr nicht Buße tut, werdet ihr alle gleicherweise umkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Er sagte aber dieses Gleichnis: Es hatte jemand einen Feigenbaum, der in seinem Weinberge gepflanzt war; und er kam und suchte Frucht an ihm und fand keine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Er sprach aber zu dem Weingärtner: Siehe, drei Jahre komme ich und suche Frucht an diesem Feigenbaum und finde keine; haue ihn ab, wozu macht er auch das Land unnütz?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Er aber antwortet und sagt zu ihm: Herr, laß ihn noch dieses Jahr, bis ich um ihn graben und Dünger legen werde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'und wenn er etwa Frucht bringen wird, gut, wenn aber nicht, so magst du ihn künftig abhauen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Er lehrte aber am Sabbath in einer der Synagogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Und siehe, da war ein Weib, die achtzehn Jahre einen Geist der Schwachheit hatte; und sie war zusammengekrümmt und gänzlich unfähig, sich aufzurichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Als aber Jesus sie sah, rief er ihr zu und sprach zu ihr: Weib, du bist gelöst von deiner Schwachheit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Und er legte ihr die Hände auf, und alsbald wurde sie gerade und verherrlichte Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Der Synagogenvorsteher aber, unwillig, daß Jesus am Sabbath heilte, hob an und sprach zu der Volksmenge: Sechs Tage sind es, an denen man arbeiten soll; an diesen nun kommt und laßt euch heilen, und nicht am Tage des Sabbaths.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Der Herr nun antwortete ihm und sprach: Heuchler! Löst nicht ein jeder von euch am Sabbath seinen Ochsen oder Esel von der Krippe und führt ihn hin und tränkt ihn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Diese aber, die eine Tochter Abrahams ist, welche der Satan gebunden hat, siehe, achtzehn Jahre, sollte sie nicht von dieser Fessel gelöst werden am Tage des Sabbaths?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Und als er dies sagte, wurden alle seine Widersacher beschämt; und die ganze Volksmenge freute sich über all die herrlichen Dinge, welche durch ihn geschahen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Er sprach aber: Wem ist das Reich Gottes gleich, und wem soll ich es vergleichen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Es ist gleich einem Senfkorn, welches ein Mensch nahm und in seinen Garten warf; und es wuchs und wurde zu einem großen Baume, und die Vögel des Himmels ließen sich nieder in seinen Zweigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Und wiederum sprach er: Wem soll ich das Reich Gottes vergleichen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Es ist gleich einem Sauerteig, welchen ein Weib nahm und unter drei Maß Mehl verbarg, bis es ganz durchsäuert war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Und er durchzog nacheinander Städte und Dörfer, indem er lehrte und nach Jerusalem reiste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Es sprach aber jemand zu ihm: Herr, sind derer wenige, die errettet werden? Er aber sprach zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Ringet danach, durch die enge Pforte einzugehen; denn viele, sage ich euch, werden einzugehen suchen und werden es nicht vermögen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Von da an, wenn der Hausherr aufgestanden ist und die Tür verschlossen hat, und ihr anfangen werdet, draußen zu stehen und an die Tür zu klopfen und zu sagen: Herr, tue uns auf! Und er antworten und zu euch sagen wird: Ich kenne euch nicht, wo ihr her seid;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'alsdann werdet ihr anfangen zu sagen: Wir haben vor dir gegessen und getrunken, und auf unseren Straßen hast du gelehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Und er wird sagen: Ich sage euch, ich kenne euch nicht, wo ihr her seid; weichet von mir, alle ihr Übeltäter!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Da wird sein das Weinen und das Zähneknirschen, wenn ihr sehen werdet Abraham und Isaak und Jakob und alle Propheten im Reiche Gottes, euch aber draußen hinausgeworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Und sie werden kommen von Osten und Westen und von Norden und Süden und zu Tische liegen im Reiche Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Und siehe, es sind Letzte, welche Erste sein werden, und es sind Erste, welche Letzte sein werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'In derselben Stunde kamen einige Pharisäer herzu und sagten zu ihm: Geh hinaus und ziehe von hinnen, denn Herodes will dich töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Und er sprach zu ihnen: Gehet hin und saget diesem Fuchs: Siehe, ich treibe Dämonen aus und vollbringe Heilungen heute und morgen, und am dritten Tage werde ich vollendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Doch ich muß heute und morgen und am folgenden Tage wandeln; denn es geht nicht an, daß ein Prophet außerhalb Jerusalems umkomme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jerusalem, Jerusalem, die da tötet die Propheten und steinigt, die zu ihr gesandt sind! Wie oft habe ich deine Kinder versammeln wollen, wie eine Henne ihre Brut unter die Flügel, und ihr habt nicht gewollt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Siehe, euer Haus wird euch überlassen. Ich sage euch aber: Ihr werdet mich nicht sehen, bis es kommt, daß ihr sprechet: \"Gepriesen sei, der da kommt im Namen des Herrn!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Und es geschah, als er am Sabbath in das Haus eines der Obersten der Pharisäer kam, um zu essen, daß sie auf ihn lauerten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Und siehe, ein gewisser wassersüchtiger Mensch war vor ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Und Jesus hob an und sprach zu den Gesetzgelehrten und Pharisäern und sagte: Ist es erlaubt, am Sabbath zu heilen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Sie aber schwiegen. Und er faßte ihn an und heilte ihn und entließ ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Und er antwortete und sprach zu ihnen: Wer ist unter euch, dessen Esel oder Ochs in einen Brunnen fällt, und der ihn nicht alsbald herauszieht am Tage des Sabbaths?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Und sie vermochten nicht, ihm darauf zu antworten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Er sprach aber zu den Eingeladenen ein Gleichnis, indem er bemerkte, wie sie die ersten Plätze wählten, und sagte zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Wenn du von jemand zur Hochzeit geladen wirst, so lege dich nicht auf den ersten Platz, damit nicht etwa ein Geehrterer als du von ihm geladen sei,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'und der, welcher dich und ihn geladen hat, komme und zu dir spreche: Mache diesem Platz; und dann wirst du anfangen, mit Schande den letzten Platz einzunehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Sondern, wenn du geladen bist, so gehe hin und lege dich auf den letzten Platz, auf daß, wenn der, welcher dich geladen hat, kommt, er zu dir spreche: Freund, rücke höher hinauf. Dann wirst du Ehre haben vor allen, die mit dir zu Tische liegen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'denn jeder, der sich selbst erhöht, wird erniedrigt werden, und wer sich selbst erniedrigt, wird erhöht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Er sprach aber auch zu dem, der ihn geladen hatte: Wenn du ein Mittags-oder ein Abendmahl machst, so lade nicht deine Freunde, noch deine Brüder, noch deine Verwandten, noch reiche Nachbarn, damit nicht etwa auch sie dich wiederladen und dir Vergeltung werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Sondern wenn du ein Mahl machst, so lade Arme, Krüppel, Lahme, Blinde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'und glückselig wirst du sein, weil sie nicht haben, dir zu vergelten; denn es wird dir vergolten werden in der Auferstehung der Gerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Als aber einer von denen, die mit zu Tische lagen, dies hörte, sprach er zu ihm: Glückselig, wer Brot essen wird im Reiche Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Er aber sprach zu ihm: Ein gewisser Mensch machte ein großes Abendmahl und lud viele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Und er sandte seinen Knecht zur Stunde des Abendmahls, um den Geladenen zu sagen: Kommet, denn schon ist alles bereit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Und sie fingen alle ohne Ausnahme an, sich zu entschuldigen. Der erste sprach zu ihm: Ich habe einen Acker gekauft und muß notwendig ausgehen und ihn besehen; ich bitte dich, halte mich für entschuldigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Und ein anderer sprach: Ich habe fünf Joch Ochsen gekauft, und ich gehe hin, sie zu versuchen; ich bitte dich, halte mich für entschuldigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Und ein anderer sprach: Ich habe ein Weib geheiratet, und darum kann ich nicht kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Und der Knecht kam herbei und berichtete dies seinem Herrn. Da wurde der Hausherr zornig und sprach zu seinem Knechte: Geh eilends hinaus auf die Straßen und Gassen der Stadt, und bringe hier herein die Armen und Krüppel und Lahmen und Blinden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Und der Knecht sprach: Herr, es ist geschehen, wie du befohlen hast, und es ist noch Raum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Und der Herr sprach zu dem Knechte: Geh hinaus auf die Wege und an die Zäune und nötige sie hereinzukommen, auf daß mein Haus voll werde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'denn ich sage euch, daß nicht einer jener Männer, die geladen waren, mein Abendmahl schmecken wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Es gingen aber große Volksmengen mit ihm; und er wandte sich um und sprach zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Wenn jemand zu mir kommt und haßt nicht seinen Vater und seine Mutter und sein Weib und seine Kinder und seine Brüder und Schwestern, dazu aber auch sein eigenes Leben, so kann er nicht mein Jünger sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'und wer nicht sein Kreuz trägt und mir nachkommt, kann nicht mein Jünger sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Denn wer unter euch, der einen Turm bauen will, setzt sich nicht zuvor nieder und berechnet die Kosten, ob er das Nötige zur Ausführung habe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Auf daß nicht etwa, wenn er den Grund gelegt hat und nicht zu vollenden vermag, alle, die es sehen, anfangen ihn zu verspotten');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'und sagen: Dieser Mensch hat angefangen zu bauen und vermochte nicht zu vollenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Oder welcher König, der auszieht, um sich mit einem anderen König in Krieg einzulassen, setzt sich nicht zuvor nieder und ratschlagt, ob er imstande sei, dem mit Zehntausend entgegen zu treten, der wider ihn kommt mit Zwanzigtausend?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Wenn aber nicht, so sendet er, während er noch fern ist, eine Gesandtschaft und bittet um die Friedensbedingungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Also nun jeder von euch, der nicht allem entsagt, was er hat, kann nicht mein Jünger sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Das Salz nun ist gut; wenn aber auch das Salz kraftlos geworden ist, womit soll es gewürzt werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Es ist weder für das Land noch für den Dünger tauglich; man wirft es hinaus. Wer Ohren hat zu hören, der höre!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Es nahten aber zu ihm alle Zöllner und Sünder, ihn zu hören;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'und die Pharisäer und die Schriftgelehrten murrten und sprachen: Dieser nimmt Sünder auf und isset mit ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Er sprach aber zu ihnen dieses Gleichnis und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Welcher Mensch unter euch, der hundert Schafe hat und eines von ihnen verloren hat, läßt nicht die neunundneunzig in der Wüste und geht dem verlorenen nach, bis er es findet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Und wenn er es gefunden hat, so legt er es mit Freuden auf seine Schultern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'und wenn er nach Hause kommt, ruft er die Freunde und die Nachbarn zusammen und spricht zu ihnen: Freuet euch mit mir, denn ich habe mein Schaf gefunden, das verloren war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Ich sage euch: Also wird Freude im Himmel sein über einen Sünder, der Buße tut, mehr als über neunundneunzig Gerechte, welche der Buße nicht bedürfen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Oder welches Weib, das zehn Drachmen hat, zündet nicht, wenn sie eine Drachme verliert, eine Lampe an und kehrt das Haus und sucht sorgfältig, bis sie sie findet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Und wenn sie sie gefunden hat, ruft sie die Freundinnen und Nachbarinnen zusammen und spricht: Freuet euch mit mir, denn ich habe die Drachme gefunden, die ich verloren hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Also, sage ich euch, ist Freude vor den Engeln Gottes über einen Sünder, der Buße tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Er sprach aber: Ein gewisser Mensch hatte zwei Söhne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'und der jüngere von ihnen sprach zu dem Vater: Vater, gib mir den Teil des Vermögens, der mir zufällt. Und er teilte ihnen die Habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Und nach nicht vielen Tagen brachte der jüngere Sohn alles zusammen und reiste weg in ein fernes Land, und daselbst vergeudete er sein Vermögen, indem er ausschweifend lebte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Als er aber alles verzehrt hatte, kam eine gewaltige Hungersnot über jenes Land, und er selbst fing an, Mangel zu leiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Und er ging hin und hängte sich an einen der Bürger jenes Landes; der schickte ihn auf seine Äcker, Schweine zu hüten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Und er begehrte, seinen Bauch zu füllen mit den Träbern, welche die Schweine fraßen; und niemand gab ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Als er aber zu sich selbst kam, sprach er: Wie viele Tagelöhner meines Vaters haben Überfluß an Brot, ich aber komme hier um vor Hunger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Ich will mich aufmachen und zu meinem Vater gehen, und will zu ihm sagen: Vater, ich habe gesündigt gegen den Himmel und vor dir,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'ich bin nicht mehr würdig, dein Sohn zu heißen; mache mich wie einen deiner Tagelöhner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Und er machte sich auf und ging zu seinem Vater. Als er aber noch fern war, sah ihn sein Vater und wurde innerlich bewegt und lief hin und fiel ihm um seinen Hals und küßte ihn sehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Der Sohn aber sprach zu ihm: Vater, ich habe gesündigt gegen den Himmel und vor dir, ich bin nicht mehr würdig, dein Sohn zu heißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Der Vater aber sprach zu seinen Knechten: Bringet das beste Kleid her und ziehet es ihm an und tut einen Ring an seine Hand und Sandalen an seine Füße;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'und bringet das gemästete Kalb her und schlachtet es, und lasset uns essen und fröhlich sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'denn dieser mein Sohn war tot und ist wieder lebendig geworden, war verloren und ist gefunden worden. Und sie fingen an fröhlich zu sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Es war aber sein älterer Sohn auf dem Felde; und als er kam und sich dem Hause näherte, hörte er Musik und Reigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Und er rief einen der Knechte herzu und erkundigte sich, was das wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Der aber sprach zu ihm: Dein Bruder ist gekommen, und dein Vater hat das gemästete Kalb geschlachtet, weil er ihn gesund wieder erhalten hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Er aber wurde zornig und wollte nicht hineingehen. Sein Vater aber ging hinaus und drang in ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Er aber antwortete und sprach zu dem Vater: Siehe, so viele Jahre diene ich dir, und niemals habe ich ein Gebot von dir übertreten; und mir hast du niemals ein Böcklein gegeben, auf daß ich mit meinen Freunden fröhlich wäre;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'da aber dieser dein Sohn gekommen ist, der deine Habe mit Huren verschlungen hat, hast du ihm das gemästete Kalb geschlachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Er aber sprach zu ihm: Kind, du bist allezeit bei mir, und all das Meinige ist dein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Es geziemte sich aber fröhlich zu sein und sich zu freuen; denn dieser dein Bruder war tot und ist wieder lebendig geworden und verloren und ist gefunden worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Er sprach aber auch zu seinen Jüngern: Es war ein gewisser reicher Mann, der einen Verwalter hatte; und dieser wurde bei ihm angeklagt, als verschwende er seine Habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Und er rief ihn und sprach zu ihm: Was ist dies, das ich von dir höre? Lege die Rechnung von deiner Verwaltung ab, denn du wirst nicht mehr Verwalter sein können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Der Verwalter aber sprach bei sich selbst: Was soll ich tun? Denn mein Herr nimmt mir die Verwaltung ab. Zu graben vermag ich nicht, zu betteln schäme ich mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Ich weiß, was ich tun werde, auf daß sie mich, wenn ich der Verwaltung enthoben bin, in ihre Häuser aufnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Und er rief jeden einzelnen der Schuldner seines Herrn herzu und sprach zu dem ersten: Wieviel bist du meinem Herrn schuldig?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Der aber sprach: Hundert Bath Öl. Und er sprach zu ihm: Nimm deinen Schuldbrief und setze dich flugs hin und schreibe fünfzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Danach sprach er zu einem anderen: Du aber, wieviel bist du schuldig? Der aber sprach: Hundert Kor Weizen. Und er spricht zu ihm: Nimm deinen Schuldbrief und schreibe achtzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Und der Herr lobte den ungerechten Verwalter, weil er klug gehandelt hatte; denn die Söhne dieser Welt sind klüger als die Söhne des Lichts gegen ihr eigenes Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Und ich sage euch: Machet euch Freunde mit dem ungerechten Mammon, auf daß, wenn er zu Ende geht, man euch aufnehme in die ewigen Hütten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Wer im Geringsten treu ist, ist auch in vielem treu, und wer im Geringsten ungerecht ist, ist auch in vielem ungerecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Wenn ihr nun in dem ungerechten Mammon nicht treu gewesen seid, wer wird euch das Wahrhaftige anvertrauen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Und wenn ihr in dem Fremden nicht treu gewesen seid, wer wird euch das Eurige geben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Kein Hausknecht kann zwei Herren dienen; denn entweder wird er den einen hassen und den anderen lieben, oder er wird dem einen anhangen und den anderen verachten. Ihr könnt nicht Gott dienen und dem Mammon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Dies alles hörten aber auch die Pharisäer, welche geldliebend waren, und sie verhöhnten ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Und er sprach zu ihnen: Ihr seid es, die sich selbst rechtfertigen vor den Menschen, Gott aber kennt eure Herzen; denn was unter den Menschen hoch ist, ist ein Greuel vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Das Gesetz und die Propheten waren bis auf Johannes; von da an wird das Evangelium des Reiches Gottes verkündigt, und jeder dringt mit Gewalt hinein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Es ist aber leichter, daß der Himmel und die Erde vergehen, als daß ein Strichlein des Gesetzes wegfalle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Jeder, der sein Weib entläßt und eine andere heiratet, begeht Ehebruch; und jeder, der die von einem Manne Entlassene heiratet, begeht Ehebruch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Es war aber ein gewisser reicher Mann, und er kleidete sich in Purpur und feine Leinwand und lebte alle Tage fröhlich und in Prunk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Es war aber ein gewisser Armer, mit Namen Lazarus, der an dessen Tor lag, voller Geschwüre,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'und er begehrte, sich von den Brosamen zu sättigen, die von dem Tische des Reichen fielen; aber auch die Hunde kamen und leckten seine Geschwüre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Es geschah aber, daß der Arme starb und von den Engeln getragen wurde in den Schoß Abrahams. Es starb aber auch der Reiche und wurde begraben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Und in dem Hades seine Augen aufschlagend, als er in Qualen war, sieht er Abraham von ferne und Lazarus in seinem Schoße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Und er rief und sprach: Vater Abraham, erbarme dich meiner und sende Lazarus, daß er die Spitze seines Fingers ins Wasser tauche und meine Zunge kühle; denn ich leide Pein in dieser Flamme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Abraham aber sprach: Kind, gedenke, daß du dein Gutes völlig empfangen hast in deinem Leben, und Lazarus gleicherweise das Böse; jetzt aber wird er hier getröstet, du aber leidest Pein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Und zu diesem allem ist zwischen uns und euch eine große Kluft befestigt, damit die, welche von hier zu euch hinübergehen wollen, nicht können, noch die, welche von dort zu uns herüberkommen wollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Er sprach aber: Ich bitte dich nun, Vater, daß du ihn in das Haus meines Vaters sendest,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'denn ich habe fünf Brüder, damit er ihnen ernstlich Zeugnis gebe, auf daß sie nicht auch kommen an diesen Ort der Qual.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Abraham aber spricht zu ihm: Sie haben Moses und die Propheten; mögen sie dieselben hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Er aber sprach: Nein, Vater Abraham, sondern wenn jemand von den Toten zu ihnen geht, so werden sie Buße tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Er sprach aber zu ihm: Wenn sie Moses und die Propheten nicht hören, so werden sie auch nicht überzeugt werden, wenn jemand aus den Toten aufersteht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Er sprach aber zu seinen Jüngern: Es ist unmöglich, daß nicht Ärgernisse kommen; wehe aber dem, durch welchen sie kommen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Es wäre ihm nützlicher, wenn ein Mühlstein um seinen Hals gelegt und er ins Meer geworfen würde, als daß er einen dieser Kleinen ärgere!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Habet acht auf euch selbst: wenn dein Bruder sündigt, so verweise es ihm, und wenn er es bereut, so vergib ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'Und wenn er siebenmal des Tages an dir sündigt und siebenmal zu dir umkehrt und spricht: Ich bereue es, so sollst du ihm vergeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Und die Apostel sprachen zu dem Herrn: Vermehre uns den Glauben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Der Herr aber sprach: Wenn ihr Glauben habt wie ein Senfkorn, so würdet ihr zu diesem Maulbeerfeigenbaum sagen: Werde entwurzelt und ins Meer gepflanzt! und er würde euch gehorchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Wer aber von euch, der einen Knecht hat, welcher pflügt oder weidet, wird zu ihm, wenn er vom Felde hereinkommt, sagen: Komm und lege dich alsbald zu Tische?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Wird er nicht vielmehr zu ihm sagen: Richte zu, was ich zu Abend essen soll, und gürte dich und diene mir, bis ich gegessen und getrunken habe; und danach sollst du essen und trinken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Dankt er etwa dem Knechte, daß er das Befohlene getan hat? Ich meine nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Also auch ihr, wenn ihr alles getan habt, was euch befohlen ist, so sprechet: Wir sind unnütze Knechte; wir haben getan, was wir zu tun schuldig waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Und es geschah, als er nach Jerusalem reiste, daß er mitten durch Samaria und Galiläa ging.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Und als er in ein gewisses Dorf eintrat, begegneten ihm zehn aussätzige Männer, welche von ferne standen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'Und sie erhoben ihre Stimme und sprachen: Jesu, Meister, erbarme dich unser!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Und als er sie sah, sprach er zu ihnen: Gehet hin und zeiget euch den Priestern. Und es geschah, indem sie hingingen, wurden sie gereinigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Einer aber von ihnen, als er sah, daß er geheilt war, kehrte zurück, indem er mit lauter Stimme Gott verherrlichte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'und er fiel aufs Angesicht zu seinen Füßen und dankte ihm; und derselbe war ein Samariter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Jesus aber antwortete und sprach: Sind nicht die zehn gereinigt worden? Wo sind aber die neun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Sind keine gefunden worden, die zurückkehrten, um Gott Ehre zu geben, außer diesem Fremdling?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Und er sprach zu ihm: Stehe auf und gehe hin; dein Glaube hat dich gerettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Und als er von den Pharisäern gefragt wurde: Wann kommt das Reich Gottes? antwortete er ihnen und sprach: Das Reich Gottes kommt nicht so, daß man es beobachten könnte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'noch wird man sagen: Siehe hier! oder: Siehe dort! Denn siehe, das Reich Gottes ist mitten unter euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Er sprach aber zu den Jüngern: Es werden Tage kommen, da ihr begehren werdet, einen der Tage des Sohnes des Menschen zu sehen, und ihr werdet ihn nicht sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Und man wird zu euch sagen: Siehe hier! oder: Siehe dort! Gehet nicht hin, folget auch nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Denn gleichwie der Blitz blitzend leuchtet von einem Ende unter dem Himmel bis zum anderen Ende unter dem Himmel, also wird der Sohn des Menschen sein an seinem Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Zuvor aber muß er vieles leiden und verworfen werden von diesem Geschlecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Und gleichwie es in den Tagen Noahs geschah, also wird es auch sein in den Tagen des Sohnes des Menschen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'sie aßen, sie tranken, sie heirateten, sie wurden verheiratet, bis zu dem Tage, da Noah in die Arche ging, und die Flut kam und alle umbrachte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Gleicherweise auch, wie es geschah in den Tagen Lots: sie aßen, sie tranken, sie kauften, sie verkauften, sie pflanzten, sie bauten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'an dem Tage aber, da Lot von Sodom ausging, regnete es Feuer und Schwefel vom Himmel und brachte alle um.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Desgleichen wird es an dem Tage sein, da der Sohn des Menschen geoffenbart wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'An jenem Tage, wer auf dem Dache sein wird und sein Gerät im Hause hat, der steige nicht hinab, um es zu holen; und wer auf dem Felde ist, wende sich gleicherweise nicht zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Gedenket an Lots Weib!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Wer irgend sein Leben zu retten sucht, wird es verlieren; und wer irgend es verliert, wird es erhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Ich sage euch: In jener Nacht werden zwei auf einem Bette sein; einer wird genommen und der andere gelassen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Zwei Weiber werden zusammen mahlen, die eine wird genommen, und die andere gelassen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Zwei werden auf dem Felde sein: der eine wird angenommen, der andere wird preisgegeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, '(G17:36) Und sie antworten und sagen zu ihm: Wo, Herr? Er aber sprach zu ihnen: Wo der Leichnam ist, da werden auch die Adler versammelt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Er sagte ihnen aber auch ein Gleichnis dafür, daß sie allezeit beten und nicht ermatten sollten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'und sprach: Es war ein gewisser Richter in einer Stadt, der Gott nicht fürchtete und vor keinem Menschen sich scheute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Es war aber eine Witwe in jener Stadt; und sie kam zu ihm und sprach: Schaffe mir Recht von meinem Widersacher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Und eine Zeitlang wollte er nicht; danach aber sprach er bei sich selbst: Wenn ich auch Gott nicht fürchte und vor keinem Menschen mich scheue,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'so will ich doch, weil diese Witwe mir Mühe macht, ihr Recht verschaffen, auf daß sie nicht unaufhörlich komme und mich quäle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Der Herr aber sprach: Höret, was der ungerechte Richter sagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Gott aber, sollte er das Recht seiner Auserwählten nicht ausführen, die Tag und Nacht zu ihm schreien, und ist er in Bezug auf sie langsam?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Ich sage euch, daß er ihr Recht schnell ausführen wird. Doch wird wohl der Sohn des Menschen, wenn er kommt, den Glauben finden auf der Erde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Er sprach aber auch zu etlichen, die auf sich selbst vertrauten, daß sie gerecht seien, und die übrigen für nichts achteten, dieses Gleichnis:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Zwei Menschen gingen hinauf in den Tempel, um zu beten, der eine ein Pharisäer und der andere ein Zöllner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Der Pharisäer stand und betete bei sich selbst also: O Gott, ich danke dir, daß ich nicht bin wie die übrigen der Menschen, Räuber, Ungerechte, Ehebrecher, oder auch wie dieser Zöllner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Ich faste zweimal in der Woche, ich verzehnte alles, was ich erwerbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Und der Zöllner, von ferne stehend, wollte sogar die Augen nicht aufheben gen Himmel, sondern schlug an seine Brust und sprach: O Gott, sei mir, dem Sünder, gnädig!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Ich sage euch: Dieser ging gerechtfertigt hinab in sein Haus vor jenem; denn jeder, der sich selbst erhöht, wird erniedrigt werden; wer aber sich selbst erniedrigt, wird erhöht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Sie brachten aber auch die Kindlein zu ihm, auf daß er sie anrühre. Als aber die Jünger es sahen, verwiesen sie es ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Jesus aber rief sie herzu und sprach: Lasset die Kindlein zu mir kommen und wehret ihnen nicht, denn solcher ist das Reich Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Wahrlich, ich sage euch: Wer irgend das Reich Gottes nicht aufnehmen wird wie ein Kindlein, wird nicht in dasselbe eingehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Und es fragte ihn ein gewisser Oberster und sprach: Guter Lehrer, was muß ich getan haben, um ewiges Leben zu ererben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Jesus aber sprach zu ihm: Was heißest du mich gut? Niemand ist gut, als nur einer, Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Die Gebote weißt du: \"Du sollst nicht ehebrechen; du sollst nicht töten; du sollst nicht stehlen; du sollst nicht falsches Zeugnis geben; ehre deinen Vater und deine Mutter\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Er aber sprach: Dies alles habe ich beobachtet von meiner Jugend an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Als Jesus dies hörte, sprach er zu ihm: Noch eines fehlt dir: Verkaufe alles, was du hast, und verteile es an die Armen, und du wirst einen Schatz in den Himmeln haben, und komm, folge mir nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Als er aber dies hörte, wurde er sehr betrübt, denn er war sehr reich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Als aber Jesus sah, daß er sehr betrübt wurde, sprach er: Wie schwerlich werden die, welche Güter haben, in das Reich Gottes eingehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Denn es ist leichter, daß ein Kamel durch ein Nadelöhr eingehe, als daß ein Reicher in das Reich Gottes eingehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Es sprachen aber die es hörten: Und wer kann dann errettet werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Er aber sprach: Was bei Menschen unmöglich ist, ist möglich bei Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Petrus aber sprach: Siehe, wir haben alles verlassen und sind dir nachgefolgt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Er aber sprach zu ihnen: Wahrlich, ich sage euch: Es ist niemand, der Haus oder Eltern oder Brüder oder Weib oder Kinder verlassen hat um des Reiches Gottes willen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'der nicht Vielfältiges empfangen wird in dieser Zeit und in dem kommenden Zeitalter ewiges Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Er nahm aber die Zwölfe zu sich und sprach zu ihnen: Siehe, wir gehen hinauf nach Jerusalem, und es wird alles vollendet werden, was durch die Propheten auf den Sohn des Menschen geschrieben ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'denn er wird den Nationen überliefert werden und wird verspottet und geschmäht und angespieen werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'und wenn sie ihn gegeißelt haben, werden sie ihn töten, und am dritten Tage wird er auferstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Und sie verstanden nichts von diesen Dingen, und dieses Wort war vor ihnen verborgen, und sie begriffen das Gesagte nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Es geschah aber, als er Jericho nahte, saß ein gewisser Blinder bettelnd am Wege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Und als er eine Volksmenge vorbeiziehen hörte, erkundigte er sich, was das wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Sie verkündeten ihm aber, daß Jesus, der Nazaräer, vorübergehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Und er rief und sprach: Jesu, Sohn Davids, erbarme dich meiner!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Und die Vorangehenden bedrohten ihn, daß er schweigen sollte; er aber schrie um so mehr: Sohn Davids, erbarme dich meiner!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Jesus aber stand still und hieß ihn zu sich führen. Als er sich aber näherte, fragte er ihn und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Was willst du, daß ich dir tun soll? Er aber sprach: Herr, daß ich sehend werde!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Und Jesus sprach zu ihm: Sei sehend! Dein Glaube hat dich geheilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Und alsbald ward er sehend und folgte ihm nach, indem er Gott verherrlichte. Und das ganze Volk, das es sah, gab Gott Lob.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Und er ging hinein und zog durch Jericho.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Und siehe, da war ein Mann, mit Namen Zachäus, und selbiger war ein Oberzöllner, und er war reich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Und er suchte Jesum zu sehen, wer er wäre; und er vermochte es nicht vor der Volksmenge, denn er war klein von Gestalt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Und er lief voraus und stieg auf einen Maulbeerfeigenbaum, auf daß er ihn sähe; denn er sollte daselbst durchkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Und als er an den Ort kam, sah Jesus auf und erblickte ihn und sprach zu ihm: Zachäus, steige eilends hernieder, denn heute muß ich in deinem Hause bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Und er stieg eilends hernieder und nahm ihn auf mit Freuden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Und als sie es sahen, murrten alle und sagten: Er ist eingekehrt, um bei einem sündigen Manne zu herbergen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Zachäus aber stand und sprach zu dem Herrn: Siehe, Herr, die Hälfte meiner Güter gebe ich den Armen, und wenn ich von jemand etwas durch falsche Anklage genommen habe, so erstatte ich es vierfältig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Jesus aber sprach zu ihm: Heute ist diesem Hause Heil widerfahren, dieweil auch er ein Sohn Abrahams ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'denn der Sohn des Menschen ist gekommen, zu suchen und zu erretten, was verloren ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Während sie aber dieses hörten, fügte er noch ein Gleichnis hinzu, weil er nahe bei Jerusalem war, und sie meinten, daß das Reich Gottes alsbald erscheinen sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Er sprach nun: Ein gewisser hochgeborener Mann zog in ein fernes Land, um ein Reich für sich zu empfangen und wiederzukommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Er berief aber seine zehn Knechte und gab ihnen zehn Pfunde und sprach zu ihnen: Handelt, bis ich komme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Seine Bürger aber haßten ihn und schickten eine Gesandtschaft hinter ihm her und ließen sagen: Wir wollen nicht, daß dieser über uns herrsche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Und es geschah, als er zurückkam, nachdem er das Reich empfangen hatte, da hieß er diese Knechte, denen er das Geld gegeben, zu sich rufen, auf daß er wisse, was ein jeder erhandelt hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Der erste aber kam herbei und sagte: Herr, dein Pfund hat zehn Pfunde hinzugewonnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Und er sprach zu ihm: Wohl, du guter Knecht! Weil du im Geringsten treu warst, so habe Gewalt über zehn Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Und der zweite kam und sagte: Herr, dein Pfund hat fünf Pfunde eingetragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Er sprach aber auch zu diesem: Und du, sei über fünf Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Und ein anderer kam und sagte: Herr, siehe, hier ist dein Pfund, welches ich in einem Schweißtuch verwahrt hielt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'denn ich fürchtete dich, weil du ein strenger Mann bist: du nimmst, was du nicht hingelegt, und du erntest, was du nicht gesät hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Er spricht zu ihm: Aus deinem Munde werde ich dich richten, du böser Knecht! Du wußtest, daß ich ein strenger Mann bin, der ich nehme, was ich nicht hingelegt, und ernte, was ich nicht gesät habe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Und warum hast du mein Geld nicht in eine Bank gegeben, und wenn ich kam, hätte ich es mit Zinsen eingefordert?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Und er sprach zu den Dabeistehenden: Nehmet das Pfund von ihm und gebet es dem, der die zehn Pfunde hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, '(Und sie sprachen zu ihm: Herr, er hat zehn Pfunde!)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Denn ich sage euch: Jedem, der da hat, wird gegeben werden; von dem aber, der nicht hat, von dem wird selbst, was er hat, weggenommen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Doch jene, meine Feinde, die nicht wollten, daß ich über sie herrschen sollte, bringet her und erschlaget sie vor mir. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Und als er dies gesagte hatte, zog er voran, indem er hinaufging nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Und es geschah, als er Bethphage und Bethanien nahte, gegen den Berg hin, welcher Ölberg genannt wird, sandte er zwei seiner Jünger und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'Gehet hin in das Dorf gegenüber, und wenn ihr hineinkommet, werdet ihr ein Füllen darin angebunden finden, auf welchem kein Mensch je gesessen hat; bindet es los und führet es her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Und wenn jemand euch fragt: Warum bindet ihr es los? so sprechet also zu ihm: Der Herr bedarf seiner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Und die Abgesandten gingen hin und fanden es, wie er ihnen gesagt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Als sie aber das Füllen losbanden, sprachen die Herren desselben zu ihnen: Warum bindet ihr das Füllen los?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Sie aber sprachen: Der Herr bedarf seiner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Und sie führten es zu Jesu; und sie warfen ihre Kleider auf das Füllen und setzten Jesum darauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Während er aber hinzog, breiteten sie ihre Kleider aus auf den Weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Und als er schon nahte und bei dem Abhang des Ölbergs war, fing die ganze Menge der Jünger an, mit lauter Stimme freudig Gott zu loben über alle die Wunderwerke, die sie gesehen hatten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'indem sie sagten: \"Gepriesen sei der König, der da kommt im Namen des Herrn!\" Friede im Himmel und Herrlichkeit in der Höhe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Und etliche der Pharisäer aus der Volksmenge sprachen zu ihm: Lehrer, verweise es deinen Jüngern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Und er antwortete und sprach zu ihnen: Ich sage euch, wenn diese schweigen, so werden die Steine schreien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Und als er sich näherte und die Stadt sah, weinte er über sie');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'und sprach: Wenn auch du erkannt hättest, und selbst an diesem deinem Tage, was zu deinem Frieden dient! Jetzt aber ist es vor deinen Augen verborgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Denn Tage werden über dich kommen, da werden deine Feinde einen Wall um dich aufschütten und dich umzingeln und dich von allen Seiten einengen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'und sie werden dich und deine Kinder in dir zu Boden werfen und werden in dir nicht einen Stein auf dem anderen lassen, darum daß du die Zeit deiner Heimsuchung nicht erkannt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Und als er in den Tempel eingetreten war, fing er an auszutreiben, die darin verkauften und kauften,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'indem er zu ihnen sprach: Es steht geschrieben: \"Mein Haus ist ein Bethaus\"; \"ihr aber habt es zu einer Räuberhöhle gemacht\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Und er lehrte täglich im Tempel; die Hohenpriester aber und die Schriftgelehrten und die Ersten des Volkes suchten ihn umzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'Und sie fanden nicht, was sie tun sollten, denn das ganze Volk hing an seinem Munde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Und es geschah an einem der Tage, als er das Volk im Tempel lehrte und das Evangelium verkündigte, da traten die Hohenpriester und die Schriftgelehrten mit den Ältesten herzu');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'und sprachen zu ihm und sagten: Sage uns, in welchem Recht tust du diese Dinge? Oder wer ist es, der dir dieses Recht gegeben hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Er aber antwortete und sprach zu ihnen: Auch ich will euch ein Wort fragen, und saget mir:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Die Taufe Johannes\', war sie vom Himmel oder von Menschen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Sie aber überlegten miteinander und sprachen: Wenn wir sagen: Vom Himmel, so wird er sagen: Warum habt ihr ihm nicht geglaubt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Wenn wir aber sagen: von Menschen, so wird das ganze Volk uns steinigen, denn es ist überzeugt, daß Johannes ein Prophet ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Und sie antworteten, sie wüßten nicht, woher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Und Jesus sprach zu ihnen: So sage auch ich euch nicht, in welchem Recht ich diese Dinge tue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Er fing aber an, zu dem Volke dieses Gleichnis zu sagen: Ein Mensch pflanzte einen Weinberg und verdingte ihn an Weingärtner und reiste für lange Zeit außer Landes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Und zur bestimmten Zeit sandte er einen Knecht zu den Weingärtnern, auf daß sie ihm von der Frucht des Weinbergs gäben; die Weingärtner aber schlugen ihn und schickten ihn leer fort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Und er fuhr fort und sandte einen anderen Knecht; sie aber schlugen auch den und behandelten ihn verächtlich und schickten ihn leer fort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Und er fuhr fort und sandte einen dritten; sie aber verwundeten auch diesen und warfen ihn hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Der Herr des Weinbergs aber sprach: Was soll ich tun? Ich will meinen geliebten Sohn senden; vielleicht, wenn sie diesen sehen, werden sie sich scheuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Als aber die Weingärtner ihn sahen, überlegten sie miteinander und sagten: Dieser ist der Erbe; kommt, laßt uns ihn töten, auf daß das Erbe unser werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Und als sie ihn aus dem Weinberg hinausgeworfen hatten, töteten sie ihn. Was wird nun der Herr des Weinbergs ihnen tun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Er wird kommen und diese Weingärtner umbringen und den Weinberg anderen geben. Als sie aber das hörten, sprachen sie: Das sei ferne!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Er aber sah sie an und sprach: Was ist denn dies, das geschrieben steht: \"Der Stein, den die Bauleute verworfen haben, dieser ist zum Eckstein geworden?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Jeder, der auf jenen Stein fällt, wird zerschmettert werden; auf welchen irgend er aber fallen wird, den wird er zermalmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Und die Hohenpriester und die Schriftgelehrten suchten zu derselben Stunde die Hände an ihn zu legen, und sie fürchteten das Volk; denn sie erkannten, daß er dieses Gleichnis auf sie geredet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Und sie beobachteten ihn und sandten Auflaurer aus, die sich verstellten, als ob sie gerecht wären, auf daß sie ihn in seiner Rede fingen, damit sie ihn der Obrigkeit und der Gewalt des Landpflegers überliefern möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Und sie fragten ihn und sagten: Lehrer, wir wissen, daß du recht redest und lehrst und die Person nicht ansiehst, sondern den Weg Gottes in Wahrheit lehrst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Ist es uns erlaubt, dem Kaiser Steuer zu geben oder nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Aber ihre Arglist wahrnehmend, sprach er zu ihnen: Was versuchet ihr mich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Zeiget mir einen Denar. Wessen Bild und Überschrift hat er? Sie aber antworteten und sprachen: Des Kaisers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Er aber sprach zu ihnen: Gebet daher dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Und sie vermochten nicht, ihn in seinem Worte vor dem Volke zu fangen; und sie verwunderten sich über seine Antwort und schwiegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Es kamen aber etliche der Sadducäer herzu, welche einwenden, es gebe keine Auferstehung, und fragten ihn und sagten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Lehrer, Moses hat uns geschrieben: Wenn jemandes Bruder stirbt, der ein Weib hat, und dieser kinderlos stirbt, daß sein Bruder das Weib nehme und seinem Bruder Samen erwecke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Es waren nun sieben Brüder. Und der erste nahm ein Weib und starb kinderlos;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'und der zweite nahm das Weib, und dieser starb kinderlos;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'und der dritte nahm sie; desgleichen aber auch die sieben hinterließen keine Kinder und starben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Zuletzt aber von allen starb auch das Weib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'In der Auferstehung nun, wessen Weib von ihnen wird sie? Denn die sieben hatten sie zum Weibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Und Jesus sprach zu ihnen: Die Söhne dieser Welt heiraten und werden verheiratet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'die aber würdig geachtet werden, jener Welt teilhaftig zu sein und der Auferstehung aus den Toten, heiraten nicht, noch werden sie verheiratet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'denn sie können auch nicht mehr sterben, denn sie sind Engeln gleich und sind Söhne Gottes, da sie Söhne der Auferstehung sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Daß aber die Toten auferstehen, hat auch Moses angedeutet \"in dem Dornbusch\", wenn er den Herrn \"den Gott Abrahams und den Gott Isaaks und den Gott Jakobs\" nennt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Er ist aber nicht Gott der Toten, sondern der Lebendigen; denn für ihn leben alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Einige der Schriftgelehrten aber antworteten und sprachen: Lehrer, du hast wohl gesprochen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Denn sie wagten nicht mehr, ihn über irgend etwas zu befragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Er aber sprach zu ihnen: Wie sagen sie, daß der Christus Davids Sohn sei,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'und David selbst sagt im Buche der Psalmen: \"Der Herr sprach zu meinem Herrn: Setze dich zu meiner Rechten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'bis ich deine Feinde lege zum Schemel deiner Füße\"?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'David also nennt ihn Herr, und wie ist er sein Sohn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Während aber das ganze Volk zuhörte, sprach er zu seinen Jüngern:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Hütet euch vor den Schriftgelehrten, die in langen Gewändern einhergehen wollen und die Begrüßungen auf den Märkten lieben und die ersten Sitze in den Synagogen und die ersten Plätze bei den Gastmählern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'welche die Häuser der Witwen verschlingen und zum Schein lange Gebete halten. Diese werden ein schwereres Gericht empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Er blickte aber auf und sah die Reichen ihre Gaben in den Schatzkasten legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Er sah aber auch eine gewisse arme Witwe zwei Scherflein daselbst einlegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Und er sprach: In Wahrheit sage ich euch, daß diese arme Witwe mehr eingelegt hat als alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Denn alle diese haben von ihrem Überfluß eingelegt zu den Gaben Gottes; diese aber hat von ihrem Mangel den ganzen Lebensunterhalt, den sie hatte, eingelegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Und als etliche von dem Tempel sagten, daß er mit schönen Steinen und Weihgeschenken geschmückt sei, sprach er:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Diese Dinge, die ihr sehet, Tage werden kommen, in welchen nicht ein Stein auf dem anderen gelassen wird, der nicht abgebrochen werden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Sie fragten ihn aber und sagten: Lehrer, wann wird denn dieses sein, und was ist das Zeichen, wann dieses geschehen soll?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Er aber sprach: Sehet zu, daß ihr nicht verführt werdet! Denn viele werden unter meinem Namen kommen und sagen: Ich bin\'s und die Zeit ist nahe gekommen! Gehet ihnen nun nicht nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Wenn ihr aber von Kriegen und Empörungen hören werdet, so erschrecket nicht; denn dies muß zuvor geschehen, aber das Ende ist nicht alsbald.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Dann sprach er zu ihnen: Es wird sich Nation wider Nation erheben und Königreich wider Königreich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'und es werden große Erdbeben sein an verschiedenen Orten, und Hungersnöte und Seuchen; auch Schrecknisse und große Zeichen vom Himmel wird es geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Vor diesem allem aber werden sie ihre Hände an euch legen und euch verfolgen, indem sie euch an die Synagogen und Gefängnisse überliefern, um euch vor Könige und Statthalter zu führen um meines Namens willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Es wird euch aber zu einem Zeugnis ausschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Setzet es nun fest in euren Herzen, nicht vorher darauf zu sinnen, wie ihr euch verantworten sollt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'denn ich werde euch Mund und Weisheit geben, welcher alle eure Widersacher nicht werden widersprechen oder widerstehen können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Ihr werdet aber sogar von Eltern und Brüdern und Verwandten und Freunden überliefert werden, und sie werden etliche von euch zum Tode bringen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'und ihr werdet von allen gehaßt werden um meines Namens willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Und nicht ein Haar von eurem Haupte wird verloren gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Gewinnet eure Seelen durch euer Ausharren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Wenn ihr aber Jerusalem von Heerscharen umzingelt sehet, alsdann erkennet, daß ihre Verwüstung nahe gekommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Daß alsdann, die in Judäa sind, auf die Berge fliehen, und die in ihrer Mitte sind, daraus entweichen, und die auf dem Lande sind, nicht in sie hineingehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Denn dies sind Tage der Rache, daß alles erfüllt werde, was geschrieben steht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Wehe aber den Schwangeren und den Säugenden in jenen Tagen! Denn große Not wird in dem Lande sein, und Zorn über dieses Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Und sie werden fallen durch die Schärfe des Schwertes und gefangen weggeführt werden unter alle Nationen; und Jerusalem wird zertreten werden von den Nationen, bis die Zeiten der Nationen erfüllt sein werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'Und es werden Zeichen sein an Sonne und Mond und Sternen, und auf der Erde Bedrängnis der Nationen in Ratlosigkeit bei brausendem Meer und Wasserwogen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'indem die Menschen verschmachten vor Furcht und Erwartung der Dinge, die über den Erdkreis kommen, denn die Kräfte der Himmel werden erschüttert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Und dann werden sie den Sohn des Menschen kommen sehen in einer Wolke mit Macht und großer Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Wenn aber diese Dinge anfangen zu geschehen, so blicket auf und hebet eure Häupter empor, weil eure Erlösung naht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Und er sprach ein Gleichnis zu ihnen: Sehet den Feigenbaum und alle Bäume;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'wenn sie schon ausschlagen, so erkennet ihr von selbst, indem ihr es sehet, daß der Sommer schon nahe ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'So auch ihr, wenn ihr dies geschehen sehet, erkennet, daß das Reich Gottes nahe ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Wahrlich, ich sage euch, daß dieses Geschlecht nicht vergehen wird, bis alles geschehen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Der Himmel und die Erde werden vergehen, meine Worte aber werden nicht vergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Hütet euch aber, daß eure Herzen nicht etwa beschwert werden durch Völlerei und Trunkenheit und Lebenssorgen, und jener Tag plötzlich über euch hereinbreche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'denn wie ein Fallstrick wird er kommen über alle, die auf dem ganzen Erdboden ansässig sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Wachet nun, zu aller Zeit betend, auf daß ihr würdig geachtet werdet, diesem allem, was geschehen soll, zu entfliehen und vor dem Sohne des Menschen zu stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Er lehrte aber des Tages in dem Tempel, und des Nachts ging er hinaus und übernachtete auf dem Berge, welcher Ölberg genannt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Und das ganze Volk kam frühmorgens im Tempel zu ihm, ihn zu hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Es nahte aber das Fest der ungesäuerten Brote, welches Passah genannt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Und die Hohenpriester und die Schriftgelehrten suchten, wie sie ihn umbrächten, denn sie fürchteten das Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Aber Satan fuhr in Judas, der Iskariot zubenamt ist, welcher aus der Zahl der Zwölfe war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Und er ging hin und besprach sich mit den Hohenpriestern und Hauptleuten, wie er ihn denselben überliefere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Und sie waren erfreut und kamen überein, ihm Geld zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Und er versprach es und suchte eine Gelegenheit, um ihn denselben zu überliefern ohne Volksauflauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Es kam aber der Tag der ungesäuerten Brote, an welchem das Passah geschlachtet werden mußte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Und er sandte Petrus und Johannes und sprach: Gehet hin und bereitet uns das Passah, auf daß wir es essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Sie aber sprachen zu ihm: Wo willst du, daß wir es bereiten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Er aber sprach zu ihnen: Siehe, wenn ihr in die Stadt kommet, wird euch ein Mensch begegnen, der einen Krug Wasser trägt; folget ihm in das Haus, wo er hineingeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'Und ihr sollt zu dem Herrn des Hauses sagen: Der Lehrer sagt dir: Wo ist das Gastzimmer, wo ich mit meinen Jüngern das Passah essen mag?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Und jener wird euch einen großen, mit Polstern belegten Obersaal zeigen; daselbst bereitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Als sie aber hingingen, fanden sie es, wie er ihnen gesagt hatte; und sie bereiteten das Passah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Und als die Stunde gekommen war, legte er sich zu Tische, und die zwölf Apostel mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Und er sprach zu ihnen: Mit Sehnsucht habe ich mich gesehnt, dieses Passah mit euch zu essen, ehe ich leide.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Denn ich sage euch, daß ich hinfort nicht mehr davon essen werde, bis es erfüllt sein wird im Reiche Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Und er nahm einen Kelch, dankte und sprach: Nehmet diesen und teilet ihn unter euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Denn ich sage euch, daß ich nicht von dem Gewächs des Weinstocks trinken werde, bis das Reich Gottes komme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Und er nahm Brot, dankte, brach und gab es ihnen und sprach: Dies ist mein Leib, der für euch gegeben wird; dieses tut zu meinem Gedächtnis!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Desgleichen auch den Kelch nach dem Mahle und sagte: Dieser Kelch ist der neue Bund in meinem Blute, das für euch vergossen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Doch siehe, die Hand dessen, der mich überliefert, ist mit mir über Tische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Und der Sohn des Menschen geht zwar dahin, wie es beschlossen ist; wehe aber jenem Menschen, durch welchen er überliefert wird!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Und sie fingen an, sich untereinander zu befragen, wer es wohl von ihnen sein möchte, der dies tun werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Es entstand aber auch ein Streit unter ihnen, wer von ihnen für den Größten zu halten sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Er aber sprach zu ihnen: Die Könige der Nationen herrschen über dieselben, und die Gewalt über sie üben, werden Wohltäter genannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Ihr aber nicht also; sondern der Größte unter euch sei wie der Jüngste, und der Leiter wie der Dienende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Denn wer ist größer, der zu Tische Liegende oder der Dienende? Nicht der zu Tische Liegende? Ich aber bin in eurer Mitte wie der Dienende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Ihr aber seid es, die mit mir ausgeharrt haben in meinen Versuchungen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'und ich verordne euch, gleichwie mein Vater mir verordnet hat, ein Reich,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'auf daß ihr esset und trinket an meinem Tische in meinem Reiche und auf Thronen sitzet, richtend die zwölf Stämme Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Der Herr aber sprach: Simon, Simon! Siehe, der Satan hat euer begehrt, euch zu sichten wie den Weizen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Ich aber habe für dich gebetet, auf daß dein Glaube nicht aufhöre; und du, bist du einst zurückgekehrt, so stärke deine Brüder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Er aber sprach zu ihm: Herr, mit dir bin ich bereit, auch ins Gefängnis und in den Tod zu gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Er aber sprach: Ich sage dir, Petrus, der Hahn wird heute nicht krähen, ehe du dreimal geleugnet hast, daß du mich kennest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Und er sprach zu ihnen: Als ich euch ohne Börse und Tasche und Sandalen sandte, mangelte euch wohl etwas? Sie aber sagten: Nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Er sprach nun zu ihnen: Aber jetzt, wer eine Börse hat, der nehme sie und gleicherweise eine Tasche, und wer keine hat, verkaufe sein Kleid und kaufe ein Schwert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'denn ich sage euch, daß noch dieses, was geschrieben steht, an mir erfüllt werden muß: \"Und er ist unter die Gesetzlosen gerechnet worden\"; denn auch das, was mich betrifft, hat eine Vollendung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Sie aber sprachen: Herr, siehe, hier sind zwei Schwerter. Er aber sprach zu ihnen: Es ist genug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Und er ging hinaus und begab sich der Gewohnheit nach an den Ölberg; es folgten ihm aber auch die Jünger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Als er aber an den Ort gekommen war, sprach er zu ihnen: Betet, daß ihr nicht in Versuchung kommet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Und er zog sich ungefähr einen Steinwurf weit von ihnen zurück und kniete nieder, betete');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'und sprach: Vater, wenn du diesen Kelch von mir wegnehmen willst, doch nicht mein Wille, sondern der deine geschehe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Es erschien ihm aber ein Engel vom Himmel, der ihn stärkte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Und als er in ringendem Kampfe war, betete er heftiger. Es wurde aber sein Schweiß wie große Blutstropfen, die auf die Erde herabfielen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Und er stand auf vom Gebet, kam zu den Jüngern und fand sie eingeschlafen vor Traurigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'Und er sprach zu ihnen: Was schlafet ihr? Stehet auf und betet, auf daß ihr nicht in Versuchung kommet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Während er noch redete, siehe, da kam eine Volksmenge, und der, welcher Judas genannt war, einer der Zwölfe, ging vor ihnen her und nahte Jesu, um ihn zu küssen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Jesus aber sprach zu ihm: Judas, überlieferst du den Sohn des Menschen mit einem Kuß?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Als aber die, welche um ihn waren, sahen, was es werden würde, sprachen sie zu ihm: Herr, sollen wir mit dem Schwerte dreinschlagen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Und einer aus ihnen schlug den Knecht des Hohenpriesters und hieb ihm das rechte Ohr ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Jesus aber antwortete und sprach: Lasset es so weit; und er rührte sein Ohr an und heilte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Jesus aber sprach zu den Hohenpriestern und Hauptleuten des Tempels und Ältesten, die wider ihn gekommen waren: Seid ihr ausgezogen wie gegen einen Räuber, mit Schwertern und Stöcken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Als ich täglich bei euch im Tempel war, habt ihr die Hände nicht gegen mich ausgestreckt; aber dies ist eure Stunde und die Gewalt der Finsternis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Sie ergriffen ihn aber und führten ihn hin und brachten ihn in das Haus des Hohenpriesters. Petrus aber folgte von ferne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Als sie aber mitten im Hofe ein Feuer angezündet und sich zusammengesetzt hatten, setzte sich Petrus in ihre Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Es sah ihn aber eine gewisse Magd bei dem Feuer sitzen und blickte ihn unverwandt an und sprach: Auch dieser war mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Er aber verleugnete ihn und sagte: Weib, ich kenne ihn nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Und kurz danach sah ihn ein anderer und sprach: Auch du bist einer von ihnen. Petrus aber sprach: Mensch, ich bin\'s nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Und nach Verlauf von etwa einer Stunde behauptete ein anderer und sagte: In Wahrheit, auch dieser war mit ihm, denn er ist auch ein Galiläer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Petrus aber sprach: Mensch, ich weiß nicht, was du sagst. Und alsbald, während er noch redete, krähte der Hahn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Und der Herr wandte sich um und blickte Petrus an; und Petrus gedachte an das Wort des Herrn, wie er zu ihm sagte: Ehe der Hahn kräht, wirst du mich dreimal verleugnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Und Petrus ging hinaus und weinte bitterlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Und die Männer, die ihn festhielten, verspotteten und schlugen ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'Und als sie ihn verhüllt hatten, fragten sie ihn und sprachen: Weissage, wer ist es, der dich schlug?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Und vieles andere sagten sie lästernd gegen ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Und als es Tag wurde, versammelte sich die Ältestenschaft des Volkes, sowohl Hohepriester als Schriftgelehrte, und führten ihn hin in ihr Synedrium und sagten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Wenn du der Christus bist, so sage es uns. Er aber sprach zu ihnen: Wenn ich es euch sagte, so würdet ihr nicht glauben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'wenn ich aber fragen würde, so würdet ihr mir nicht antworten, noch mich loslassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Von nun an aber wird der Sohn des Menschen sitzen zur Rechten der Macht Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Sie sprachen aber alle: Du bist also der Sohn Gottes? Er aber sprach zu ihnen: Ihr saget, daß ich es bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Sie aber sprachen: Was bedürfen wir noch Zeugnis? Denn wir selbst haben es aus seinem Munde gehört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Und die ganze Menge derselben stand auf, und sie führten ihn zu Pilatus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'Sie fingen aber an, ihn zu verklagen, indem sie sagten: Diesen haben wir befunden als einen, der unsere Nation verführt und wehrt, dem Kaiser Steuer zu geben, indem er sagt, daß er selbst Christus, ein König, sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Pilatus aber fragte ihn und sprach: Bist du der König der Juden? Er aber antwortete ihm und sprach: Du sagst es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Pilatus aber sprach zu den Hohenpriestern und den Volksmengen: Ich finde keine Schuld an diesem Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Sie aber bestanden darauf und sagten: Er wiegelt das Volk auf, indem er durch ganz Judäa hin lehrt, anfangend von Galiläa bis hierher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Als aber Pilatus von Galiläa hörte, fragte er, ob der Mensch ein Galiläer sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Und als er erfahren hatte, daß er aus dem Gebiet des Herodes sei, sandte er ihn zu Herodes, der auch selbst in jenen Tagen zu Jerusalem war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Als aber Herodes Jesum sah, freute er sich sehr; denn er wünschte schon seit langer Zeit, ihn zu sehen, weil er vieles über ihn gehört hatte, und er hoffte, irgend ein Zeichen durch ihn geschehen zu sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Er befragte ihn aber mit vielen Worten; er aber antwortete ihm nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Die Hohenpriester und die Schriftgelehrten standen aber auf und verklagten ihn heftig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Als aber Herodes mit seinen Kriegsleuten ihn geringschätzig behandelt und verspottet hatte, warf er ihm ein glänzendes Gewand um und sandte ihn zu Pilatus zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Pilatus und Herodes aber wurden an selbigem Tage Freunde miteinander, denn vorher waren sie gegeneinander in Feindschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Als aber Pilatus die Hohenpriester und die Obersten und das Volk zusammengerufen hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'sprach er zu ihnen: Ihr habt diesen Menschen zu mir gebracht, als mache er das Volk abwendig; und siehe, ich habe ihn vor euch verhört, und habe an diesem Menschen keine Schuld gefunden, betreffs dessen ihr ihn anklaget;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'aber auch Herodes nicht, denn ich habe euch zu ihm gesandt, und siehe, nichts Todeswürdiges ist von ihm getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Ich will ihn nun züchtigen und losgeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Er mußte ihnen aber notwendig auf das Fest einen losgeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Die ganze Menge schrie aber zugleich und sagte: Hinweg mit diesem, gib uns aber den Barabbas los!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Derselbe war wegen eines gewissen Aufruhrs, der in der Stadt geschehen war, und wegen eines Mordes ins Gefängnis geworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilatus rief ihnen nun wiederum zu, indem er Jesum losgeben wollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Sie aber schrieen dagegen und sagten: Kreuzige, kreuzige ihn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Er aber sprach zum dritten Mal zu ihnen: Was hat dieser denn Böses getan? Ich habe keine Ursache des Todes an ihm gefunden; ich will ihn nun züchtigen und losgeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Sie aber lagen ihm an mit großem Geschrei und forderten, daß er gekreuzigt würde. Und ihr und der Hohenpriester Geschrei nahm überhand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Pilatus aber urteilte, daß ihre Forderung geschehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Er gab aber den los, der eines Aufruhrs und Mordes wegen ins Gefängnis geworfen war, welchen sie forderten; Jesum aber übergab er ihrem Willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Und als sie ihn wegführten, ergriffen sie einen gewissen Simon von Kyrene, der vom Felde kam, und legten das Kreuz auf ihn, um es Jesu nachzutragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Es folgte ihm aber eine große Menge Volks und Weiber, welche wehklagten und ihn bejammerten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Jesus wandte sich aber zu ihnen und sprach: Töchter Jerusalems, weinet nicht über mich, sondern weinet über euch selbst und über eure Kinder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'denn siehe, Tage kommen, an welchen man sagen wird: Glückselig die Unfruchtbaren und die Leiber, die nicht geboren, und die Brüste, die nicht gesäugt haben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Dann werden sie anheben, zu den Bergen zu sagen: Fallet auf uns! und zu den Hügeln: Bedecket uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Denn wenn man dies tut an dem grünen Holze, was wird an dem dürren geschehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Es wurden aber auch zwei andere hingeführt, Übeltäter, um mit ihm hingerichtet zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Und als sie an den Ort kamen, der Schädelstätte genannt wird, kreuzigten sie daselbst ihn und die Übeltäter, den einen zur Rechten, den anderen zur Linken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Jesus aber sprach: Vater, vergib ihnen, denn sie wissen nicht, was sie tun! Sie aber verteilten seine Kleider und warfen das Los darüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Und das Volk stand und sah zu; es höhnten aber auch die Obersten mit denselben und sagten: Andere hat er gerettet; er rette sich selbst, wenn dieser der Christus ist, der Auserwählte Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Aber auch die Kriegsknechte verspotteten ihn, indem sie herzutraten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'ihm Essig brachten und sagten: Wenn du der König der Juden bist, so rette dich selbst!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Es war aber auch eine Überschrift über ihm geschrieben in griechischen und lateinischen und hebräischen Buchstaben: Dieser ist der König der Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Einer aber der gehenkten Übeltäter lästerte ihn und sagte: Bist du nicht der Christus? Rette dich selbst und uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Der andere aber antwortete und strafte ihn und sprach: Auch du fürchtest Gott nicht, da du in demselben Gericht bist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Und wir zwar mit Recht, denn wir empfangen, was unsere Taten wert sind; dieser aber hat nichts Ungeziemendes getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Und er sprach zu Jesu: Gedenke meiner, Herr wenn du in deinem Reiche kommst!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Und Jesus sprach zu ihm: Wahrlich, ich sage dir: Heute wirst du mit mir im Paradiese sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Es war aber um die sechste Stunde; und es kam eine Finsternis über das ganze Land bis zur neunten Stunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'Und die Sonne ward verfinstert, und der Vorhang des Tempels riß mitten entzwei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Und Jesus rief mit lauter Stimme und sprach: Vater, in deine Hände übergebe ich meinen Geist! Und als er dies gesagt hatte, verschied er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Als aber der Hauptmann sah, was geschah, verherrlichte er Gott und sagte: Fürwahr, dieser Mensch war gerecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Und alle die Volksmengen, die zu diesem Schauspiel zusammengekommen waren, schlugen sich, als sie sahen, was geschehen war, an die Brust und kehrten zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Aber alle seine Bekannten standen von ferne, auch die Weiber, die ihm von Galiläa nachgefolgt waren, und sahen dies.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Und siehe, ein Mann, mit Namen Joseph, der ein Ratsherr war, ein guter und gerechter Mann, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'dieser hatte nicht eingewilligt in ihren Rat und in ihre Tat, von Arimathia, einer Stadt der Juden, der auch selbst das Reich Gottes erwartete;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'dieser ging hin zu Pilatus und bat um den Leib Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Und als er ihn abgenommen hatte, wickelte er ihn in feine Leinwand und legte ihn in eine in Felsen gehauene Gruft, wo noch nie jemand gelegen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Und es war Rüsttag, und der Sabbath brach an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Es folgten aber die Weiber nach, welche mit ihm aus Galiläa gekommen waren, und besahen die Gruft und wie sein Leib hineingelegt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Als sie aber zurückgekehrt waren, bereiteten sie Spezereien und Salben; und den Sabbath über ruhten sie nach dem Gebot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'An dem ersten Wochentage aber, ganz in der Frühe, kamen sie zu der Gruft und brachten die Spezereien, die sie bereitet hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Sie fanden aber den Stein von der Gruft weggewälzt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'und als sie hineingingen, fanden sie den Leib des Herrn Jesus nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Und es geschah, als sie darüber in Verlegenheit waren, siehe, da standen zwei Männer in strahlenden Kleidern bei ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Als sie aber von Furcht erfüllt wurden und das Angesicht zur Erde neigten, sprachen sie zu ihnen: Was suchet ihr den Lebendigen unter den Toten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Er ist nicht hier, sondern ist auferstanden. Gedenket daran, wie er zu euch geredet hat, als er noch in Galiläa war, indem er sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'Der Sohn des Menschen muß in die Hände sündiger Menschen überliefert und gekreuzigt werden und am dritten Tage auferstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Und sie gedachten an seine Worte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'und sie kehrten von der Gruft zurück und verkündigten dies alles den Elfen und den übrigen allen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Es waren aber die Maria Magdalene und Johanna und Maria, des Jakobus Mutter, und die übrigen mit ihnen, welche dies zu den Aposteln sagten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Und ihre Reden schienen vor ihnen wie ein Märchen, und sie glaubten ihnen nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Petrus aber stand auf und lief zu der Gruft; und sich hineinbückend, sieht er die leinenen Tücher allein liegen, und er ging weg nach Hause und verwunderte sich über das, was geschehen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Und siehe, zwei von ihnen gingen an selbigem Tage nach einem Dorfe, mit Namen Emmaus, sechzig Stadien von Jerusalem entfernt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'Und sie unterhielten sich miteinander über alles dieses, was sich zugetragen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Und es geschah, indem sie sich unterhielten und miteinander überlegten, daß Jesus selbst nahte und mit ihnen ging;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'aber ihre Augen wurden gehalten, damit sie ihn nicht erkennten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Er sprach aber zu ihnen: Was sind das für Reden, die ihr wandelnd miteinander wechselt, und seid niedergeschlagen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Einer aber, mit Namen Kleopas, antwortete und sprach zu ihm: Bist du der einzige, der in Jerusalem weilt und nicht weiß, was in ihr geschehen ist in diesen Tagen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Und er sprach zu ihnen: Was denn? Sie aber sprachen zu ihm: Das von Jesus, dem Nazaräer, der ein Prophet war, mächtig im Werk und Wort vor Gott und dem ganzen Volke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'und wie ihn die Hohenpriester und unsere Obersten überlieferten, um zum Tode verurteilt zu werden, und ihn kreuzigten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Wir aber hofften, daß er der sei, der Israel erlösen solle. Doch auch bei alledem ist es heute der dritte Tag, seitdem dies geschehen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Aber auch etliche Weiber von uns haben uns außer uns gebracht, die am frühen Morgen bei der Gruft gewesen sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'und, als sie seinen Leib nicht fanden, kamen und sagten, daß sie auch ein Gesicht von Engeln gesehen hätten, welche sagen, daß er lebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Und etliche von denen, die mit uns sind, gingen zu der Gruft und fanden es so, wie auch die Weiber gesagt hatten; ihn aber sahen sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Und er sprach zu ihnen: O ihr Unverständigen und trägen Herzens, zu glauben an alles, was die Propheten geredet haben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Mußte nicht der Christus dies leiden und in seine Herrlichkeit eingehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Und von Moses und von allen Propheten anfangend, erklärte er ihnen in allen Schriften das, was ihn betraf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Und sie nahten dem Dorfe, wohin sie gingen; und er stellte sich, als wolle er weitergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Und sie nötigten ihn und sagten: Bleibe bei uns, denn es ist gegen Abend, und der Tag hat sich schon geneigt. Und er ging hinein, um bei ihnen zu bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Und es geschah, als er mit ihnen zu Tische lag, nahm er das Brot und segnete es; und als er es gebrochen hatte, reichte er es ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Ihre Augen aber wurden aufgetan, und sie erkannten ihn; und er wurde ihnen unsichtbar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Und sie sprachen zueinander: Brannte nicht unser Herz in uns, als er auf dem Wege zu uns redete, und als er uns die Schriften öffnete?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Und sie standen zur selbigen Stunde auf und kehrten nach Jerusalem zurück. Und sie fanden die Elfe und die mit ihnen waren versammelt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'welche sagten: Der Herr ist wirklich auferweckt worden und dem Simon erschienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Und sie erzählten, was auf dem Wege geschehen war, und wie er von ihnen erkannt worden war an dem Brechen des Brotes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Während sie aber dieses redeten, stand er selbst in ihrer Mitte und spricht zu ihnen: Friede euch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Sie aber erschraken und wurden von Furcht erfüllt und meinten, sie sähen einen Geist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Und er sprach zu ihnen: Was seid ihr bestürzt, und warum steigen Gedanken auf in euren Herzen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Sehet meine Hände und meine Füße, daß ich es selbst bin; betastet mich und sehet, denn ein Geist hat nicht Fleisch und Bein, wie ihr sehet, daß ich habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Und als er dies gesagt hatte, zeigte er ihnen die Hände und die Füße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Als sie aber noch nicht glaubten vor Freude und sich verwunderten, sprach er zu ihnen: Habt ihr hier etwas zu essen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Sie aber reichten ihm ein Stück gebratenen Fisch und von einer Honigscheibe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'und er nahm und aß vor ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Er sprach aber zu ihnen: Dies sind die Worte, die ich zu euch redete, als ich noch bei euch war, daß alles erfüllt werden muß, was über mich geschrieben steht in dem Gesetz Moses\' und den Propheten und Psalmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Dann öffnete er ihnen das Verständnis, um die Schriften zu verstehen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'und sprach zu ihnen: Also steht geschrieben, und also mußte der Christus leiden und am dritten Tage auferstehen aus den Toten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'und in seinem Namen Buße und Vergebung der Sünden gepredigt werden allen Nationen, anfangend von Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Ihr aber seid Zeugen hiervon;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'und siehe, ich sende die Verheißung meines Vaters auf euch. Ihr aber, bleibet in der Stadt, bis ihr angetan werdet mit Kraft aus der Höhe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Er führte sie aber hinaus bis nach Bethanien und hob seine Hände auf und segnete sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Und es geschah, indem er sie segnete, schied er von ihnen und wurde hinaufgetragen in den Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Und sie warfen sich vor ihm nieder und kehrten nach Jerusalem zurück mit großer Freude;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'und sie waren allezeit im Tempel, Gott lobend und preisend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Im Anfang war das Wort, und das Wort war bei Gott, und das Wort war Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Dieses war im Anfang bei Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Alles ward durch dasselbe, und ohne dasselbe ward auch nicht eines, das geworden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'In ihm war Leben, und das Leben war das Licht der Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Und das Licht scheint in der Finsternis, und die Finsternis hat es nicht erfaßt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Da war ein Mensch, von Gott gesandt, sein Name Johannes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Dieser kam zum Zeugnis, auf daß er zeugte von dem Lichte, damit alle durch ihn glaubten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Er war nicht das Licht, sondern auf daß er zeugte von dem Lichte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Das war das wahrhaftige Licht, welches, in die Welt kommend, jeden Menschen erleuchtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Er war in der Welt, und die Welt ward durch ihn, und die Welt kannte ihn nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Er kam in das Seinige, und die Seinigen nahmen ihn nicht an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'so viele ihn aber aufnahmen, denen gab er das Recht, Kinder Gottes zu werden, denen, die an seinen Namen glauben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'welche nicht aus Geblüt, noch aus dem Willen des Fleisches, noch aus dem Willen des Mannes, sondern aus Gott geboren sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Und das Wort ward Fleisch und wohnte unter uns (und wir haben seine Herrlichkeit angeschaut, eine Herrlichkeit als eines Eingeborenen vom Vater), voller Gnade und Wahrheit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, '(Johannes zeugt von ihm und rief und sprach: Dieser war es, von dem ich sagte: Der nach mir Kommende ist mir vor, denn er war vor mir)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'denn aus seiner Fülle haben wir alle empfangen, und zwar Gnade um Gnade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Denn das Gesetz wurde durch Moses gegeben; die Gnade und die Wahrheit ist durch Jesum Christum geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Niemand hat Gott jemals gesehen; der eingeborene Sohn, der in des Vaters Schoß ist, der hat ihn kundgemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Und dies ist das Zeugnis des Johannes, als die Juden aus Jerusalem Priester und Leviten sandten, damit sie ihn fragen sollten: Wer bist du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Und er bekannte und leugnete nicht, und er bekannte: Ich bin nicht der Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Und sie fragten ihn: Was denn? Bist du Elias? Und er sagt: Ich bin\'s nicht. Bist du der Prophet? Und er antwortete: Nein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Sie sprachen nun zu ihm: Wer bist du? Auf daß wir Antwort geben denen, die uns gesandt haben; was sagst du von dir selbst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Er sprach: Ich bin die \"Stimme eines Rufenden in der Wüste: Machet gerade den Weg des Herrn\", wie Jesajas, der Prophet, gesagt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Und sie waren abgesandt von den Pharisäern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Und sie fragten ihn und sprachen zu ihm: Was taufst du denn, wenn du nicht der Christus bist, noch Elias, noch der Prophet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Johannes antwortete ihnen und sprach: Ich taufe mit Wasser; mitten unter euch steht, den ihr nicht kennet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'der nach mir Kommende, dessen ich nicht würdig bin, ihm den Riemen seiner Sandale zu lösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Dies geschah zu Bethanien, jenseit des Jordan, wo Johannes taufte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Des folgenden Tages sieht er Jesum zu sich kommen und spricht: Siehe, das Lamm Gottes, welches die Sünde der Welt wegnimmt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Dieser ist es, von dem ich sagte: Nach mir kommt ein Mann, der mir vor ist, denn er war vor mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Und ich kannte ihn nicht; aber auf daß er Israel offenbar werden möchte, deswegen bin ich gekommen, mit Wasser taufend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Und Johannes zeugte und sprach: Ich schaute den Geist wie eine Taube aus dem Himmel herniederfahren, und er blieb auf ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Und ich kannte ihn nicht; aber der mich gesandt hat, mit Wasser zu taufen, der sprach zu mir: Auf welchen du sehen wirst den Geist herniederfahren und auf ihm bleiben, dieser ist es, der mit Heiligem Geiste tauft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Und ich habe gesehen und habe bezeugt, daß dieser der Sohn Gottes ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Des folgenden Tages stand wiederum Johannes und zwei von seinen Jüngern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'und hinblickend auf Jesum, der da wandelte, spricht er: Siehe, das Lamm Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Und es hörten ihn die zwei Jünger reden und folgten Jesu nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Jesus aber wandte sich um und sah sie nachfolgen und spricht zu ihnen: Was suchet ihr? Sie aber sagten zu ihm: Rabbi (was verdolmetscht heißt: Lehrer), wo hältst du dich auf?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Er spricht zu ihnen: Kommet und sehet! Sie kamen nun und sahen, wo er sich aufhielt, und blieben jenen Tag bei ihm. Es war um die zehnte Stunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Andreas, der Bruder des Simon Petrus, war einer von den zweien, die es von Johannes gehört hatten und ihm nachgefolgt waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Dieser findet zuerst seinen eigenen Bruder Simon und spricht zu ihm: Wir haben den Messias gefunden (was verdolmetscht ist: Christus).');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Und er führte ihn zu Jesu. Jesus blickte ihn an und sprach: Du bist Simon, der Sohn Jonas\'; du wirst Kephas heißen (was verdolmetscht wird: Stein).');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Des folgenden Tages wollte er aufbrechen nach Galiläa, und er findet Philippus; und Jesus spricht zu ihm: Folge mir nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Philippus aber war von Bethsaida, aus der Stadt des Andreas und Petrus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Philippus findet den Nathanael und spricht zu ihm: Wir haben den gefunden, von welchem Moses in dem Gesetz geschrieben und die Propheten, Jesum, den Sohn des Joseph, den von Nazareth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Und Nathanael sprach zu ihm: Kann aus Nazareth etwas Gutes kommen? Philippus spricht zu ihm: Komm und sieh!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jesus sah den Nathanael zu sich kommen und spricht von ihm: Siehe, wahrhaftig ein Israelit, in welchem kein Trug ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Nathanael spricht zu ihm: Woher kennst du mich? Jesus antwortete und sprach zu ihm: Ehe Philippus dich rief, als du unter dem Feigenbaum warst, sah ich dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Nathanael antwortete und sprach zu ihm: Rabbi, du bist der Sohn Gottes, du bist der König Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jesus antwortete und sprach zu ihm: Weil ich dir sagte: Ich sah dich unter dem Feigenbaum, glaubst du? Du wirst Größeres als dieses sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Und er spricht zu ihm: Wahrlich, wahrlich, ich sage euch: Von nun an werdet ihr den Himmel geöffnet sehen und die Engel Gottes auf-und niedersteigen auf den Sohn des Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Und am dritten Tage war eine Hochzeit zu Kana in Galiläa; und die Mutter Jesu war daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Es war aber auch Jesus mit seinen Jüngern zu der Hochzeit geladen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Und als es an Wein gebrach, spricht die Mutter Jesu zu ihm: Sie haben keinen Wein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Jesus spricht zu ihr: Was habe ich mit dir zu schaffen, Weib? Meine Stunde ist noch nicht gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Seine Mutter spricht zu den Dienern: Was irgend er euch sagen mag, tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Es waren aber daselbst sechs steinerne Wasserkrüge aufgestellt, nach der Reinigungssitte der Juden, wovon jeder zwei oder drei Maß faßte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jesus spricht zu ihnen: Füllet die Wasserkrüge mit Wasser. Und sie füllten sie bis oben an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Und er spricht zu ihnen: Schöpfet nun und bringet es dem Speisemeister. Und sie brachten es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Als aber der Speisemeister das Wasser gekostet hatte, welches Wein geworden war (und er wußte nicht, woher er war, die Diener aber, welche das Wasser geschöpft hatten, wußten es), ruft der Speisemeister den Bräutigam');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'und spricht zu ihm: Jeder Mensch setzt zuerst den guten Wein vor, und wenn sie trunken geworden sind, alsdann den geringeren; du hast den guten Wein bis jetzt aufbewahrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Diesen Anfang der Zeichen machte Jesus zu Kana in Galiläa und offenbarte seine Herrlichkeit; und seine Jünger glaubten an ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Nach diesem ging er hinab nach Kapernaum, er und seine Mutter und seine Brüder und seine Jünger; und daselbst blieben sie nicht viele Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Und das Passah der Juden war nahe, und Jesus ging hinauf nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Und er fand im Tempel die Ochsen-und Schafe-und Taubenverkäufer, und die Wechsler dasitzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Und er machte eine Geißel aus Stricken und trieb sie alle zum Tempel hinaus, sowohl die Schafe als auch die Ochsen; und die Münze der Wechsler schüttete er aus, und die Tische warf er um;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'und zu den Taubenverkäufern sprach er: Nehmet dies weg von hier, machet nicht das Haus meines Vaters zu einem Kaufhause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Seine Jünger aber gedachten daran, daß geschrieben steht: \"Der Eifer um dein Haus verzehrt mich\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Die Juden nun antworteten und sprachen zu ihm: Was für ein Zeichen zeigst du uns, daß du diese Dinge tust?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jesus antwortete und sprach zu ihnen: Brechet diesen Tempel ab, und in drei Tagen werde ich ihn aufrichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Da sprachen die Juden: Sechsundvierzig Jahre ist an diesem Tempel gebaut worden, und du willst ihn in drei Tagen aufrichten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Er aber sprach von dem Tempel seines Leibes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Als er nun aus den Toten auferweckt war, gedachten seine Jünger daran, daß er dies gesagt hatte, und sie glaubten der Schrift und dem Worte, welches Jesus gesprochen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Als er aber zu Jerusalem war, am Passah, auf dem Feste, glaubten viele an seinen Namen, als sie seine Zeichen sahen, die er tat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Jesus selbst aber vertraute sich ihnen nicht an, weil er alle kannte');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'und nicht bedurfte, daß jemand Zeugnis gebe von dem Menschen; denn er selbst wußte, was in dem Menschen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Es war aber ein Mensch aus den Pharisäern, sein Name Nikodemus, ein Oberster der Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Dieser kam zu ihm bei Nacht und sprach zu ihm: Rabbi, wir wissen, daß du ein Lehrer bist, von Gott gekommen, denn niemand kann diese Zeichen tun, die du tust, es sei denn Gott mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jesus antwortete und sprach zu ihm: Wahrlich, wahrlich, ich sage dir: Es sei denn, daß jemand von neuem geboren werde, so kann er das Reich Gottes nicht sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nikodemus spricht zu ihm: Wie kann ein Mensch geboren werden, wenn er alt ist? Kann er etwa zum zweiten Male in den Leib seiner Mutter eingehen und geboren werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jesus antwortete: Wahrlich, wahrlich, ich sage dir: Es sei denn, daß jemand aus Wasser und Geist geboren werde, so kann er nicht in das Reich Gottes eingehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Was aus dem Fleische geboren ist, ist Fleisch, und was aus dem Geiste geboren ist, ist Geist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Verwundere dich nicht, daß ich dir sagte: Ihr müsset von neuem geboren werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Der Wind weht, wo er will, und du hörst sein Sausen, aber du weißt nicht, woher er kommt, und wohin er geht; also ist jeder, der aus dem Geiste geboren ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nikodemus antwortete und sprach zu ihm: Wie kann dies geschehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jesus antwortete und sprach zu ihm: Du bist der Lehrer Israels und weißt dieses nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Wahrlich, wahrlich, ich sage dir: Wir reden, was wir wissen, und bezeugen, was wir gesehen haben, und unser Zeugnis nehmet ihr nicht an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Wenn ich euch das Irdische gesagt habe, und ihr glaubet nicht, wie werdet ihr glauben, wenn ich euch das Himmlische sage?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Und niemand ist hinaufgestiegen in den Himmel, als nur der aus dem Himmel herabgestiegen ist, der Sohn des Menschen, der im Himmel ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Und gleichwie Moses in der Wüste die Schlange erhöhte, also muß der Sohn des Menschen erhöht werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'auf daß jeder, der an ihn glaubt, nicht verloren gehe, sondern ewiges Leben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Denn also hat Gott die Welt geliebt, daß er seinen eingeborenen Sohn gab, auf daß jeder, der an ihn glaubt, nicht verloren gehe, sondern ewiges Leben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Denn Gott hat seinen Sohn nicht in die Welt gesandt, auf daß er die Welt richte, sondern auf daß die Welt durch ihn errettet werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Wer an ihn glaubt, wird nicht gerichtet; wer aber nicht glaubt, ist schon gerichtet, weil er nicht geglaubt hat an den Namen des eingeborenen Sohnes Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Dies aber ist das Gericht, daß das Licht in die Welt gekommen ist, und die Menschen haben die Finsternis mehr geliebt als das Licht, denn ihre Werke waren böse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Denn jeder, der Arges tut, haßt das Licht und kommt nicht zu dem Lichte, auf daß seine Werke nicht bloßgestellt werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'wer aber die Wahrheit tut, kommt zu dem Lichte, auf daß seine Werke offenbar werden, daß sie in Gott gewirkt sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Nach diesem kam Jesus und seine Jünger in das Land Judäa, und daselbst verweilte er mit ihnen und taufte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Aber auch Johannes taufte zu Änon, nahe bei Salim, weil viel Wasser daselbst war; und sie kamen hin und wurden getauft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Denn Johannes war noch nicht ins Gefängnis geworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Es entstand nun eine Streitfrage unter den Jüngern Johannes\' mit einem Juden über die Reinigung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Und sie kamen zu Johannes und sprachen zu ihm: Rabbi, der jenseit des Jordan bei dir war, dem du Zeugnis gegeben hast, siehe, der tauft, und alle kommen zu ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Johannes antwortete und sprach: Ein Mensch kann nichts empfangen, es sei ihm denn aus dem Himmel gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Ihr selbst gebet mir Zeugnis, daß ich sagte: Ich bin nicht der Christus, sondern daß ich vor ihm hergesandt bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Der die Braut hat, ist der Bräutigam; der Freund des Bräutigams aber, der dasteht und ihn hört, ist hoch erfreut über die Stimme des Bräutigams; diese meine Freude nun ist erfüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Er muß wachsen, ich aber abnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Der von ober kommt, ist über allen; der von der Erde ist, ist von der Erde und redet von der Erde. Der vom Himmel kommt, ist über allen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'und was er gesehen und gehört hat, dieses bezeugt er; und sein Zeugnis nimmt niemand an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Wer sein Zeugnis angenommen hat, hat besiegelt, daß Gott wahrhaftig ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Denn der, welchen Gott gesandt hat, redet die Worte Gottes; denn Gott gibt den Geist nicht nach Maß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Der Vater liebt den Sohn und hat alles in seine Hand gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Wer an den Sohn glaubt, hat ewiges Leben; wer aber dem Sohne nicht glaubt, wird das Leben nicht sehen, sondern der Zorn Gottes bleibt auf ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Als nun der Herr erkannte, daß die Pharisäer gehört hatten, daß Jesus mehr Jünger mache und taufe als Johannes');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(wiewohl Jesus selbst nicht taufte, sondern seine Jünger),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'verließ er Judäa und zog wieder nach Galiläa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Er mußte aber durch Samaria ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Er kommt nun in eine Stadt Samarias, genannt Sichar, nahe bei dem Felde, welches Jakob seinem Sohne Joseph gab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Es war aber daselbst eine Quelle Jakobs. Jesus nun, ermüdet von der Reise, setzte sich also an die Quelle nieder. Es war um die sechste Stunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Da kommt ein Weib aus Samaria, Wasser zu schöpfen. Jesus spricht zu ihr: Gib mir zu trinken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, '(Denn seine Jünger waren weggegangen in die Stadt, um Speise zu kaufen.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Das samaritische Weib spricht nun zu ihm: Wie bittest du, der du ein Jude bist, von mir zu trinken, die ich ein samaritisches Weib bin? (Denn die Juden verkehren nicht mit den Samaritern.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jesus antwortete und sprach zu ihr: Wenn du die Gabe Gottes kenntest, und wer es ist, der zu dir spricht: Gib mir zu trinken, so würdest du ihn gebeten haben, und er hätte dir lebendiges Wasser gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Das Weib spricht zu ihm: Herr, du hast kein Schöpfgefäß, und der Brunnen ist tief; woher hast du denn das lebendige Wasser?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Du bist doch nicht größer als unser Vater Jakob, der uns den Brunnen gab, und er selbst trank aus demselben und seine Söhne und sein Vieh?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jesus antwortete und sprach zu ihr: Jeden, der von diesem Wasser trinkt, wird wiederum dürsten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'wer irgend aber von dem Wasser trinken wird, das ich ihm geben werde, den wird nicht dürsten in Ewigkeit; sondern das Wasser, das ich ihm geben werde, wird in ihm eine Quelle Wassers werden, das ins ewige Leben quillt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Das Weib spricht zu ihm: Herr, gib mir dieses Wasser, damit mich nicht dürste und ich nicht hierher komme, um zu schöpfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Jesus spricht zu ihr: Gehe hin, rufe deinen Mann und komm hierher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Das Weib antwortete und sprach: Ich habe keinen Mann. Jesus spricht zu ihr: Du hast recht gesagt: Ich habe keinen Mann;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'denn fünf Männer hast du gehabt, und der, den du jetzt hast, ist nicht dein Mann; hierin hast du wahr geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Das Weib spricht zu ihm: Herr, ich sehe, daß du ein Prophet bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Unsere Väter haben auf diesem Berge angebetet, und ihr saget, daß in Jerusalem der Ort sei, wo man anbeten müsse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jesus spricht zu ihr: Weib, glaube mir, es kommt die Stunde, da ihr weder auf diesem Berge, noch in Jerusalem den Vater anbeten werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Ihr betet an und wisset nicht, was; wir beten an und wissen, was, denn das Heil ist aus den Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Es kommt aber die Stunde und ist jetzt, da die wahrhaftigen Anbeter den Vater in Geist und Wahrheit anbeten werden; denn auch der Vater sucht solche als seine Anbeter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Gott ist ein Geist, und die ihn anbeten, müssen in Geist und Wahrheit anbeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Das Weib spricht zu ihm: Ich weiß, das der Messias kommt, welcher Christus genannt wird; wenn jener kommt, wird er uns alles verkündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jesus spricht zu ihr: Ich bin\'s, der mit dir redet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Und über diesem kamen seine Jünger und verwunderten sich, daß er mit einem Weibe redete. Dennoch sagte niemand: Was suchst du? oder: Was redest du mit ihr?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Das Weib nun ließ ihren Wasserkrug stehen und ging weg in die Stadt und sagt zu den Leuten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Kommet, sehet einen Menschen, der mir alles gesagt hat, was irgend ich getan habe; dieser ist doch nicht etwa der Christus?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Sie gingen zu der Stadt hinaus und kamen zu ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'In der Zwischenzeit aber baten ihn die Jünger und sprachen: Rabbi, iß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Er aber sprach zu ihnen: Ich habe eine Speise zu essen, die ihr nicht kennet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Da sprachen die Jünger zueinander: Hat ihm wohl jemand zu essen gebracht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jesus spricht zu ihnen: Meine Speise ist, daß ich den Willen dessen tue, der mich gesandt hat, und sein Werk vollbringe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Saget ihr nicht: Es sind noch vier Monate, und die Ernte kommt? Siehe, ich sage euch: Hebet eure Augen auf und schauet die Felder an, denn sie sind schon weiß zur Ernte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Der da erntet, empfängt Lohn und sammelt Frucht zum ewigen Leben, auf daß beide, der da sät und der da erntet, zugleich sich freuen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Denn hierin ist der Spruch wahr: Ein anderer ist es, der da sät, und ein anderer, der da erntet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Ich habe euch gesandt, zu ernten, woran ihr nicht gearbeitet habt; andere haben gearbeitet, und ihr seid in ihre Arbeit eingetreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Aus jener Stadt aber glaubten viele von den Samaritern an ihn um des Wortes des Weibes willen, welches bezeugte: Er hat mir alles gesagt, was irgend ich getan habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Als nun die Samariter zu ihm kamen, baten sie ihn, bei ihnen zu bleiben; und er blieb daselbst zwei Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Und noch viele mehr glaubten um seines Wortes willen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'und sie sagten zu dem Weibe: Wir glauben nicht mehr um deines Redens willen, denn wir selbst haben gehört und wissen, daß dieser wahrhaftig der Heiland der Welt ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Nach den zwei Tagen aber zog er von dannen aus und ging hin nach Galiläa;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'denn Jesus selbst bezeugte, daß ein Prophet in dem eigenen Vaterlande keine Ehre hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Als er nun nach Galiläa kam, nahmen die Galiläer ihn auf, da sie alles gesehen, was er in Jerusalem auf dem Feste getan hatte; denn auch sie kamen zu dem Fest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Er kam nun wiederum nach Kana in Galiläa, wo er das Wasser zu Wein gemacht hatte. Und es war ein gewisser königlicher Beamter, dessen Sohn krank war, in Kapernaum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Als dieser gehört hatte, daß Jesus aus Judäa nach Galiläa gekommen sei, ging er zu ihm hin und bat ihn, daß er herabkomme und seinen Sohn heile; denn er lag im Sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Jesus sprach nun zu ihm: Wenn ihr nicht Zeichen und Wunder sehet, so werdet ihr nicht glauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Der königliche Beamte spricht zu ihm: Herr, komm herab, ehe mein Kind stirbt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jesus spricht zu ihm: Gehe hin, dein Sohn lebt. Und der Mensch glaubte dem Worte, das Jesus zu ihm sagte, und ging hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Aber schon während er hinabging, begegneten ihm seine Knechte und berichteten, daß sein Knabe lebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Er erforschte nun von ihnen die Stunde, in welcher es besser mit ihm geworden sei; und sie sagten zu ihm: Gestern zur siebten Stunde verließ ihn das Fieber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Da erkannte der Vater, daß es in jener Stunde war, in welcher Jesus zu ihm sagte: Dein Sohn lebt. Und er glaubte, er und sein ganzes Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Dies tat Jesus wiederum als zweites Zeichen, als er aus Judäa nach Galiläa gekommen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Nach diesem war ein Fest der Juden, und Jesus ging hinauf nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Es ist aber in Jerusalem bei dem Schaftor ein Teich, der auf hebräisch Bethesda zubenamt ist, welcher fünf Säulenhallen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'In diesen lag eine Menge Kranker, Blinder, Lahmer, Dürrer, die auf die Bewegung des Wassers warteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Denn zu gewissen Zeiten stieg ein Engel in den Teich herab und bewegte das Wasser. Wer nun nach der Bewegung des Wassers zuerst hineinstieg, ward gesund, mit welcher Krankheit irgend er behaftet war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Es war aber ein gewisser Mensch daselbst, der achtunddreißig Jahre mit seiner Krankheit behaftet war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Als Jesus diesen daliegen sah und wußte, daß es schon lange Zeit also mit ihm war, spricht er zu ihm: Willst du gesund werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Der Kranke antwortete ihm: Herr, ich habe keinen Menschen, daß er mich, wenn das Wasser bewegt worden ist, in den Teich werfe; indem ich aber komme, steigt ein anderer vor mir hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jesus spricht zu ihm: Stehe auf, nimm dein Bett auf und wandle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Und alsbald ward der Mensch gesund und nahm sein Bett auf und wandelte. Es war aber an jenem Tage Sabbath.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Es sagten nun die Juden zu dem Geheilten: Es ist Sabbath, es ist dir nicht erlaubt, das Bett zu tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Er antwortete ihnen: Der mich gesund machte, der sagte zu mir: Nimm dein Bett auf und wandle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Da fragten sie ihn: Wer ist der Mensch, der zu dir sagte: Nimm dein Bett auf und wandle?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Der Geheilte aber wußte nicht, wer es sei; denn Jesus war entwichen, weil eine Volksmenge an dem Orte war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Danach findet Jesus ihn im Tempel, und er sprach zu ihm: Siehe, du bist gesund geworden; sündige nicht mehr, auf daß dir nichts Ärgeres widerfahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Der Mensch ging hin und verkündete den Juden, daß es Jesus sei, der ihn gesund gemacht habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Und darum verfolgten die Juden Jesum und suchten ihn zu töten, weil er dies am Sabbath tat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Jesus aber antwortete ihnen: Mein Vater wirkt bis jetzt, und ich wirke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Darum nun suchten die Juden noch mehr, ihn zu töten, weil er nicht allein den Sabbath brach, sondern auch Gott seinen eigenen Vater nannte, sich selbst Gott gleich machend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Da antwortete Jesus und sprach zu ihnen: Wahrlich, wahrlich, ich sage euch: Der Sohn kann nichts von sich selbst tun, außer was er den Vater tun sieht; denn was irgend er tut, das tut auch der Sohn gleicherweise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Denn der Vater hat den Sohn lieb und zeigt ihm alles, was er selbst tut; und er wird ihm größere Werke als diese zeigen, auf daß ihr euch verwundert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Denn gleichwie der Vater die Toten auferweckt und lebendig macht, also macht auch der Sohn lebendig, welche er will.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Denn der Vater richtet auch niemand, sondern das ganze Gericht hat er dem Sohne gegeben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'auf daß alle den Sohn ehren, wie sie den Vater ehren. Wer den Sohn nicht ehrt, ehrt den Vater nicht, der ihn gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Wahrlich, wahrlich, ich sage euch: Wer mein Wort hört und glaubt dem, der mich gesandt hat, hat ewiges Leben und kommt nicht ins Gericht, sondern er ist aus dem Tode in das Leben übergegangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Wahrlich, wahrlich, ich sage euch, daß die Stunde kommt und jetzt ist, da die Toten die Stimme des Sohnes Gottes hören werden, und die sie gehört haben, werden leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Denn gleichwie der Vater Leben in sich selbst hat, also hat er auch dem Sohne gegeben, Leben zu haben in sich selbst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'und er hat ihm Gewalt gegen, auch Gericht zu halten, weil er des Menschen Sohn ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Wundert euch darüber nicht, denn es kommt die Stunde, in welcher alle, die in den Gräbern sind, seine Stimme hören,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'und hervorkommen werden: die das Gute getan haben, zur Auferstehung des Lebens, die aber das Böse verübt haben, zur Auferstehung des Gerichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Ich kann nichts von mir selbst tun; so wie ich höre, richte ich, und mein Gericht ist gerecht, denn ich suche nicht meinen Willen, sondern den Willen dessen, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Wenn ich von mir selbst zeuge, so ist mein Zeugnis nicht wahr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Ein anderer ist es, der von mir zeugt, und ich weiß, daß das Zeugnis wahr ist, welches er von mir zeugt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Ihr habt zu Johannes gesandt, und er hat der Wahrheit Zeugnis gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Ich aber nehme nicht Zeugnis von einem Menschen, sondern dies sage ich, auf daß ihr errettet werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Jener war die brennende und scheinende Lampe; ihr aber wolltet für eine Zeit in seinem Lichte fröhlich sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Ich aber habe das Zeugnis, das größer ist als das des Johannes; denn die Werke, welche der Vater mir gegeben hat, auf daß ich sie vollbringe, die Werke selbst, die ich tue, zeugen von mir, daß der Vater mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Und der Vater, der mich gesandt hat, er selbst hat Zeugnis von mir gegeben. Ihr habt weder jemals seine Stimme gehört, noch seine Gestalt gesehen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'und sein Wort habt ihr nicht bleibend in euch; denn welchen er gesandt hat, diesem glaubet ihr nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Ihr erforschet die Schriften, denn ihr meinet, in ihnen ewiges Leben zu haben, und sie sind es, die von mir zeugen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'und ihr wollt nicht zu mir kommen, auf daß ihr Leben habet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Ich nehme nicht Ehre von Menschen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'sondern ich kenne euch, daß ihr die Liebe Gottes nicht in euch habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Ich bin in dem Namen meines Vaters gekommen, und ihr nehmet mich nicht auf; wenn ein anderer in seinem eigenen Namen kommt, den werdet ihr aufnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Wie könnt ihr glauben, die ihr Ehre voneinander nehmet und die Ehre, welche von Gott allein ist, nicht suchet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Wähnet nicht, daß ich euch bei dem Vater verklagen werde; da ist einer, der euch verklagt, Moses, auf den ihr eure Hoffnung gesetzt habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Denn wenn ihr Moses glaubtet, so würdet ihr mir glauben, denn er hat von mir geschrieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Wenn ihr aber seinen Schriften nicht glaubet, wie werdet ihr meinen Worten glauben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Nach diesem ging Jesus weg auf die andere Seite des Sees von Galiläa oder von Tiberias;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'und es folgte ihm eine große Volksmenge, weil sie die Zeichen sahen, die er an den Kranken tat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Jesus aber ging hinauf auf den Berg und setzte sich daselbst mit seinen Jüngern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Es war aber das Passah nahe, das Fest der Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Als nun Jesus die Augen aufhob und sah, daß eine große Volksmenge zu ihm kommt, spricht er zu Philippus: Woher sollen wir Brote kaufen, auf daß diese essen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Dies sagte er aber, ihn zu versuchen; denn er selbst wußte, was er tun wollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Philippus antwortete ihm: Für zweihundert Denare Brote reichen nicht für sie hin, auf daß ein jeder etwas weniges bekomme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Einer von seinen Jüngern, Andreas, der Bruder des Simon Petrus, spricht zu ihm:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Es ist ein kleiner Knabe hier, der fünf Gerstenbrote und zwei Fische hat; aber was ist dies unter so viele?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Jesus aber sprach: Machet, daß die Leute sich lagern. Es war aber viel Gras an dem Orte. Es lagerten sich nun die Männer, an Zahl bei fünftausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Jesus aber nahm die Brote, und als er gedankt hatte, teilte er sie denen aus, die da lagerten; gleicherweise auch von den Fischen, soviel sie wollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Als sie aber gesättigt waren, spricht er zu seinen Jüngern: Sammelt die übriggebliebenen Brocken, auf daß nichts umkomme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Sie sammelten nun und füllten zwölf Handkörbe mit Brocken von den fünf Gerstenbroten, welche denen, die gegessen hatten, übrigblieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Als nun die Leute das Zeichen sahen, das Jesus tat, sprachen sie: Dieser ist wahrhaftig der Prophet, der in die Welt kommen soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Da nun Jesus erkannte, daß sie kommen und ihn ergreifen wollten, auf daß sie ihn zum König machten, entwich er wieder auf den Berg, er selbst allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Als es aber Abend geworden war, gingen seine Jünger hinab an den See;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'und sie stiegen in das Schiff und fuhren über den See nach Kapernaum. Und es war schon finster geworden, und Jesus war noch nicht zu ihnen gekommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'und der See erhob sich, indem ein starker Wind wehte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Als sie nun etwa fünfundzwanzig oder dreißig Stadien gerudert waren, sehen sie Jesum auf dem See wandeln und nahe an das Schiff herankommen, und sie fürchteten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Er aber spricht zu ihnen: Ich bin\'s, fürchtet euch nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Sie wollten ihn nun in das Schiff nehmen, und alsbald war das Schiff an dem Lande, zu welchem sie hinfuhren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Des folgenden Tages, als die Volksmenge, die jenseit des Sees stand, gesehen hatte, daß daselbst kein anderes Schifflein war, als nur jenes, in welches seine Jünger gestiegen waren, und daß Jesus nicht mit seinen Jüngern in das Schiff gestiegen, sondern seine Jünger allein weggefahren waren');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, '(es kamen aber andere Schifflein aus Tiberias nahe an den Ort, wo sie das Brot gegessen, nachdem der Herr gedankt hatte),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'da nun die Volksmenge sah, daß Jesus nicht daselbst sei, noch seine Jünger, stiegen sie in die Schiffe und kamen nach Kapernaum und suchten Jesum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Und als sie ihn jenseit des Sees gefunden hatten, sprachen sie zu ihm: Rabbi, wann bist du hierhergekommen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jesus antwortete ihnen und sprach: Wahrlich, wahrlich, ich sage euch: Ihr suchet mich, nicht weil ihr Zeichen gesehen, sondern weil ihr von den Broten gegessen habt und gesättigt worden seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Wirket nicht für die Speise, die vergeht, sondern für die Speise, die da bleibt ins ewige Leben, welche der Sohn des Menschen euch geben wird; denn diesen hat der Vater, Gott, versiegelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Da sprachen sie zu ihm: Was sollen wir tun, auf daß wir die Werke Gottes wirken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jesus antwortete und sprach zu ihnen: Dies ist das Werk Gottes, daß ihr an den glaubet, den er gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Da sprachen sie zu ihm: Was tust du nun für ein Zeichen, auf daß wir sehen und dir glauben? Was wirkst du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Unsere Väter aßen das Manna in der Wüste, wie geschrieben steht: \"Brot aus dem Himmel gab er ihnen zu essen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Da sprach Jesus zu ihnen: Wahrlich, wahrlich, ich sage euch: Nicht Moses hat euch das Brot aus dem Himmel gegeben, sondern mein Vater gibt euch das wahrhaftige Brot aus dem Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Denn das Brot Gottes ist der, welcher aus dem Himmel herniederkommt und der Welt das Leben gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Da sprachen sie zu ihm: Herr, gib uns allezeit dieses Brot!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jesus aber sprach zu ihnen: Ich bin das Brot des Lebens: wer zu mir kommt, wird nicht hungern, und wer an mich glaubt, wird nimmermehr dürsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Aber ich habe euch gesagt, daß ihr mich auch gesehen habt und nicht glaubet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Alles, was mir der Vater gibt, wird zu mir kommen, und wer zu mir kommt, den werde ich nicht hinausstoßen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'denn ich bin vom Himmel herniedergekommen, nicht auf daß ich meinen Willen tue, sondern den Willen dessen, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Dies aber ist der Wille dessen, der mich gesandt hat, daß ich von allem, was er mir gegeben hat, nichts verliere, sondern es auferwecke am letzten Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Denn dies ist der Wille meines Vaters, daß jeder, der den Sohn sieht und an ihn glaubt, ewiges Leben habe; und ich werde ihn auferwecken am letzten Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Da murrten die Juden über ihn, weil er sagte: Ich bin das Brot, das aus dem Himmel herniedergekommen ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'und sie sprachen: Ist dieser nicht Jesus, der Sohn Josephs, dessen Vater und Mutter wir kennen? Wie sagt denn dieser: Ich bin aus dem Himmel herniedergekommen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Da antwortete Jesus und sprach zu ihnen: Murret nicht untereinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Niemand kann zu mir kommen, es sei denn, daß der Vater, der mich gesandt hat, ihn ziehe; und ich werde ihn auferwecken am letzten Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Es steht in den Propheten geschrieben: \"Und sie werden alle von Gott gelehrt sein\". Jeder, der von dem Vater gehört und gelernt hat, kommt zu mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Nicht daß jemand den Vater gesehen habe, außer dem, der von Gott ist, dieser hat den Vater gesehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Wahrlich, wahrlich, ich sage euch: Wer an mich glaubt, hat ewiges Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Ich bin das Brot des Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Eure Väter haben das Manna in der Wüste gegessen und sind gestorben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Dies ist das Brot, das aus dem Himmel herniederkommt, auf daß man davon esse und nicht sterbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Ich bin das lebendige Brot, das aus dem Himmel herniedergekommen ist; wenn jemand von diesem Brote ißt, so wird er leben in Ewigkeit. Das Brot aber, daß ich geben werde, ist mein Fleisch, welches ich geben werde für das Leben der Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Die Juden stritten nun untereinander und sagten: Wie kann dieser uns sein Fleisch zu essen geben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Da sprach Jesus zu ihnen: Wahrlich, wahrlich, ich sage euch: Es sei denn, daß ihr das Fleisch des Sohnes des Menschen esset und sein Blut trinket, so habt ihr kein Leben in euch selbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Wer mein Fleisch ißt und mein Blut trinkt, hat ewiges Leben, und ich werde ihn auferwecken am letzten Tage;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'denn mein Fleisch ist wahrhaftig Speise, und mein Blut ist wahrhaftig Trank.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Wer mein Fleisch ißt und mein Blut trinkt, bleibt in mir und ich in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Gleichwie der lebendige Vater mich gesandt hat und ich lebe des Vaters wegen, so auch, wer mich ißt, der wird auch leben meinetwegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Dies ist das Brot, das aus dem Himmel herniedergekommen ist. Nicht wie die Väter aßen und starben; wer dieses Brot ißt, wird leben in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Dieses sprach er in der Synagoge, lehrend zu Kapernaum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Viele nun von seinen Jüngern, die es gehört hatten, sprachen: Diese Rede ist hart; wer kann sie hören?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Da aber Jesus bei sich selbst wußte, daß seine Jünger hierüber murrten, sprach er zu ihnen: Ärgert euch dieses?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Wenn ihr nun den Sohn des Menschen dahin auffahren sehet, wo er zuvor war?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Der Geist ist es, der lebendig macht; das Fleisch nützt nichts. Die Worte, welche ich zu euch geredet habe, sind Geist und sind Leben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'aber es sind etliche unter euch, die nicht glauben. Denn Jesus wußte von Anfang, welche es seien, die nicht glaubten, und wer es sei, der ihn überliefern würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Und er sprach: Darum habe ich euch gesagt, daß niemand zu mir kommen kann, es sei ihm denn von dem Vater gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Von da an gingen viele seiner Jünger zurück und wandelten nicht mehr mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Da sprach Jesus zu den Zwölfen: Wollt ihr etwa auch weggehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Simon Petrus antwortete ihm: Herr, zu wem sollen wir gehen? Du hast Worte ewigen Lebens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'und wir haben geglaubt und erkannt, daß du der Heilige Gottes bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jesus antwortete ihnen: Habe ich nicht euch, die Zwölfe, auserwählt? Und von euch ist einer ein Teufel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Er sprach aber von Judas, Simons Sohn, dem Iskariot; denn dieser sollte ihn überliefern, er, der einer von den Zwölfen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Und nach diesem wandelte Jesus in Galiläa; denn er wollte nicht in Judäa wandeln, weil die Juden ihn zu töten suchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Es war aber nahe das Fest der Juden, die Laubhütten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Es sprachen nun seine Brüder zu ihm: Ziehe von hinnen und geh nach Judäa, auf daß auch deine Jünger deine Werke sehen, die du tust;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'denn niemand tut etwas im Verborgenen und sucht dabei selbst öffentlich bekannt zu sein. Wenn du diese Dinge tust, so zeige dich der Welt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'denn auch seine Brüder glaubten nicht an ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Da spricht Jesus zu ihnen: Meine Zeit ist noch nicht da, eure Zeit aber ist stets bereit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Die Welt kann euch nicht hassen; mich aber haßt sie, weil ich von ihr zeuge, daß ihre Werke böse sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Gehet ihr hinauf zu diesem Feste; ich gehe nicht hinauf zu diesem Feste; denn meine Zeit ist noch nicht erfüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Nachdem er dies zu ihnen gesagt hatte, blieb er in Galiläa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Als aber seine Brüder hinaufgegangen waren, da ging auch er hinauf zu dem Feste, nicht offenbarlich, sondern wie im Verborgenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Die Juden nun suchten ihn auf dem Feste und sprachen: Wo ist jener?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Und viel Gemurmel war über ihn unter den Volksmengen; die einen sagten: Er ist gut; andere sagten: Nein, sondern er verführt die Volksmenge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Niemand jedoch sprach öffentlich von ihm aus Furcht vor den Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Als es aber schon um die Mitte des Festes war, ging Jesus hinauf in den Tempel und lehrte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Da verwunderten sich die Juden und sagten: Wie besitzt dieser Gelehrsamkeit, da er doch nicht gelernt hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Da antwortete ihnen Jesus und sprach: Meine Lehre ist nicht mein, sondern dessen, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Wenn jemand seinen Willen tun will, so wird er von der Lehre wissen, ob sie aus Gott ist, oder ob ich aus mir selbst rede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Wer aus sich selbst redet, sucht seine eigene Ehre; wer aber die Ehre dessen sucht, der ihn gesandt hat, dieser ist wahrhaftig, und Ungerechtigkeit ist nicht in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Hat nicht Moses euch das Gesetz gegeben? Und keiner von euch tut das Gesetz. Was suchet ihr mich zu töten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Die Volksmenge antwortete und sprach: Du hast einen Dämon; wer sucht dich zu töten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jesus antwortete und sprach zu ihnen: Ein Werk habe ich getan, und ihr alle verwundert euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Deswegen gab Moses euch die Beschneidung (nicht daß sie von Moses sei, sondern von den Vätern), und am Sabbath beschneidet ihr einen Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Wenn ein Mensch die Beschneidung am Sabbath empfängt, auf daß das Gesetz Moses\' nicht gebrochen werde, zürnet ihr mir, daß ich einen Menschen ganz gesund gemacht habe am Sabbath?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Richtet nicht nach dem Schein, sondern richtet ein gerechtes Gericht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Es sagten nun etliche von den Bewohnern Jerusalems: Ist das nicht der, welchen sie zu töten suchen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Und siehe, er redet öffentlich, und sie sagen ihm nichts. Haben denn etwa die Obersten in Wahrheit erkannt, daß dieser der Christus ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Diesen aber kennen wir, woher er ist; wenn aber der Christus kommt, so weiß niemand, woher er ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Jesus nun rief im Tempel, lehrte und sprach: Ihr kennet mich und wisset auch, woher ich bin; und ich bin nicht von mir selbst gekommen, sondern der mich gesandt hat, ist wahrhaftig, welchen ihr nicht kennet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Ich kenne ihn, weil ich von ihm bin, und er mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Da suchten sie ihn zu greifen; und niemand legte die Hand an ihn, weil seine Stunde noch nicht gekommen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Viele aber von der Volksmenge glaubten an ihn und sprachen: Wenn der Christus kommt, wird er wohl mehr Zeichen tun als die, welche dieser getan hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Die Pharisäer hörten die Volksmenge dies über ihn murmeln; und die Pharisäer und die Hohenpriester sandten Diener, daß sie ihn greifen möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Da sprach Jesus: Noch eine kleine Zeit bin ich bei euch, und ich gehe hin zu dem, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Ihr werdet mich suchen und nicht finden, und wo ich bin, könnt ihr nicht hinkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Es sprachen nun die Juden zueinander: Wohin will dieser gehen, daß wir ihn nicht finden sollen? Will er etwa in die Zerstreuung der Griechen gehen und die Griechen lehren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Was ist das für ein Wort, das er sprach: Ihr werdet mich suchen und nicht finden, und: Wo ich bin, könnt ihr nicht hinkommen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'An dem letzten, dem großen Tage des Festes aber stand Jesus und rief und sprach: Wenn jemand dürstet, so komme er zu mir und trinke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Wer an mich glaubt, gleichwie die Schrift gesagt hat, aus dessen Leibe werden Ströme lebendigen Wassers fließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Dies aber sagte er von dem Geiste, welchen die an ihn Glaubenden empfangen sollten; denn noch war der Geist nicht da, weil Jesus noch nicht verherrlicht worden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Etliche nun aus der Volksmenge sagten, als sie diese Worte hörten: Dieser ist wahrhaftig der Prophet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Andere sagten: Dieser ist der Christus. Andere sagten: Der Christus kommt doch nicht aus Galiläa?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Hat nicht die Schrift gesagt: Aus dem Samen Davids und aus Bethlehem, dem Dorfe, wo David war, kommt der Christus?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Es entstand nun seinethalben eine Spaltung in der Volksmenge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Etliche aber von ihnen wollten ihn greifen, aber keiner legte die Hände an ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Es kamen nun die Diener zu den Hohenpriestern und Pharisäern, und diese sprachen zu ihnen: Warum habt ihr ihn nicht gebracht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Die Diener antworteten: Niemals hat ein Mensch so geredet wie dieser Mensch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Da antworteten ihnen die Pharisäer: Seid ihr denn auch verführt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Hat wohl jemand von den Obersten an ihn geglaubt, oder von den Pharisäern?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Diese Volksmenge aber, die das Gesetz nicht kennt, sie ist verflucht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Da spricht Nikodemus zu ihnen, der einer von ihnen war:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Richtet denn unser Gesetz den Menschen, ehe es zuvor von ihm selbst gehört und erkannt hat, was er tut?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Sie antworteten und sprachen zu ihm: Bist du etwa auch aus Galiläa? Forsche und sieh, daß aus Galiläa kein Prophet aufsteht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'Und ein jeder ging nach seinem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Jesus aber ging nach dem Ölberg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Frühmorgens aber kam er wiederum in den Tempel, und alles Volk kam zu ihm; und er setzte sich und lehrte sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Die Schriftgelehrten und die Pharisäer aber bringen ein Weib zu ihm, im Ehebruch ergriffen, und stellen sie in die Mitte');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'und sagen zu ihm: Lehrer, dieses Weib ist im Ehebruch, auf er Tat selbst, ergriffen worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'In dem Gesetz aber hat uns Moses geboten, solche zu steinigen; du nun, was sagst du?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Dies aber sagten sie, ihn zu versuchen, auf daß sie etwas hätten, um ihn anzuklagen. Jesus aber bückte sich nieder und schrieb mit dem Finger auf die Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Als sie aber fortfuhren, ihn zu fragen, richtete er sich auf und sprach zu ihnen: Wer von euch ohne Sünde ist, werfe zuerst den Stein auf sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Und wiederum bückte er sich nieder und schrieb auf die Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Als sie aber dies hörten, gingen sie einer nach dem anderen hinaus, anfangend von den Ältesten bis zu den Letzten; und Jesus wurde allein gelassen mit dem Weibe in der Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Als aber Jesus sich aufrichtete und außer dem Weibe niemand sah, sprach er zu ihr: Weib, wo sind jene, deine Verkläger? Hat niemand dich verurteilt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Sie aber sprach: Niemand, Herr. Jesus aber sprach zu ihr: So verurteile auch ich dich nicht; gehe hin und sündige nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Wiederum nun redete Jesus zu ihnen und sprach: Ich bin das Licht der Welt; wer mir nachfolgt, wird nicht in der Finsternis wandeln, sondern wird das Licht des Lebens haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Da sprachen die Pharisäer zu ihm: Du zeugst von dir selbst; dein Zeugnis ist nicht wahr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jesus antwortete und sprach zu ihnen: Auch wenn ich von mir selbst zeuge, ist mein Zeugnis wahr, weil ich weiß, woher ich gekommen bin und wohin ich gehe; ihr aber wisset nicht, woher ich komme und wohin ich gehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Ihr richtet nach dem Fleische, ich richte niemand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Wenn ich aber auch richte, so ist mein Gericht wahr, weil ich nicht allein bin, sondern ich und der Vater, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Aber auch in eurem Gesetz steht geschrieben, daß das Zeugnis zweier Menschen wahr ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Ich bin es, der von mir selbst zeugt, und der Vater, der mich gesandt hat, zeugt von mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Da sprachen sie zu ihm: Wo ist dein Vater? Jesus antwortete: Ihr kennet weder mich noch meinen Vater; wenn ihr mich gekannt hättet, so würdet ihr auch meinen Vater gekannt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Diese Worte redete er in der Schatzkammer, lehrend in dem Tempel; und niemand griff ihn, denn seine Stunde war noch nicht gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Er sprach nun wiederum zu ihnen: Ich gehe hin, und ihr werdet mich suchen und werdet in eurer Sünde sterben; wo ich hingehe, könnt ihr nicht hinkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Da sagten die Juden: Er will sich doch nicht selbst töten, daß er spricht: Wo ich hingehe, könnt ihr nicht hinkommen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Und er sprach zu ihnen: Ihr seid von dem, was unten ist, ich bin von dem, was oben ist; ihr seid von dieser Welt, ich bin nicht von dieser Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Daher sagte ich euch, daß ihr in euren Sünden sterben werdet; denn wenn ihr nicht glauben werdet, daß ich es bin, so werdet ihr in euren Sünden sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Da sprachen sie zu ihm: Wer bist du? Und Jesus sprach zu ihnen: Durchaus das, was ich auch zu euch rede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Vieles habe ich über euch zu reden und zu richten, aber der mich gesandt hat, ist wahrhaftig; und ich, was ich von ihm gehört habe, das rede ich zu der Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Sie erkannten nicht, daß er von dem Vater zu ihnen sprach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Da sprach Jesus zu ihnen: Wenn ihr den Sohn des Menschen erhöht haben werdet, dann werdet ihr erkennen, daß ich es bin, und daß ich nichts von mir selbst tue, sondern wie der Vater mich gelehrt hat, das rede ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Und der mich gesandt hat, ist mit mir; er hat mich nicht allein gelassen, weil ich allezeit das ihm Wohlgefällige tue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Als er dies redete, glaubten viele an ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Jesus sprach nun zu den Juden, welche ihm geglaubt hatten: Wenn ihr in meinem Worte bleibet, so seid ihr wahrhaft meine Jünger;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'und ihr werdet die Wahrheit erkennen, und die Wahrheit wird euch frei machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Sie antworteten ihm: Wir sind Abrahams Same und sind nie jemandes Knechte gewesen; wie sagst du: Ihr sollt frei werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jesus antwortete ihnen: Wahrlich, wahrlich, ich sage euch: Jeder, der die Sünde tut, ist der Sünde Knecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Der Knecht aber bleibt nicht für immer in dem Hause; der Sohn bleibt für immer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Wenn nun der Sohn euch frei machen wird, so werdet ihr wirklich frei sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Ich weiß, daß ihr Abrahams Same seid; aber ihr suchet mich zu töten, weil mein Wort nicht Raum in euch findet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Ich rede, was ich bei meinem Vater gesehen habe, und ihr nun tut, was ihr von eurem Vater gehört habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Sie antworteten und sprachen zu ihm: Abraham ist unser Vater. Jesus spricht zu ihnen: Wenn ihr Abrahams Kinder wäret, so würdet ihr die Werke Abrahams tun;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'jetzt aber suchet ihr mich zu töten, einen Menschen, der die Wahrheit zu euch geredet hat, die ich von Gott gehört habe; das hat Abraham nicht getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Ihr tut die Werke eures Vaters. Da sprachen sie zu ihm: Wir sind nicht durch Hurerei geboren; wir haben einen Vater, Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jesus sprach zu ihnen: Wenn Gott euer Vater wäre, so würdet ihr mich lieben, denn ich bin von Gott ausgegangen und gekommen; denn ich bin auch nicht von mir selbst gekommen, sondern er hat mich gesandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Warum verstehet ihr meine Sprache nicht? Weil ihr mein Wort nicht hören könnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Ihr seid aus dem Vater, dem Teufel, und die Begierden eures Vaters wollt ihr tun. Jener war ein Menschenmörder von Anfang und ist in der Wahrheit nicht bestanden, weil keine Wahrheit in ihm ist. Wenn er die Lüge redet, so redet er aus seinem eigenen, denn er ist ein Lügner und der Vater derselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Weil ich aber die Wahrheit sage, glaubet ihr mir nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Wer von euch überführt mich der Sünde? Wenn ich die Wahrheit sage, warum glaubet ihr mir nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Wer aus Gott ist, hört die Worte Gottes. Darum höret ihr nicht, weil ihr nicht aus Gott seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Die Juden antworteten und sprachen zu ihm: Sagen wir nicht recht, daß du ein Samariter bist und einen Dämon hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jesus antwortete: Ich habe keinen Dämon, sondern ich ehre meinen Vater, und ihr verunehret mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Ich aber suche nicht meine Ehre: es ist einer, der sie sucht, und der richtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Wahrlich, wahrlich, ich sage euch: Wenn jemand mein Wort bewahren wird, so wird er den Tod nicht sehen ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Da sprachen die Juden zu ihm: Jetzt erkennen wir, daß du einen Dämon hast. Abraham ist gestorben und die Propheten, und du sagst: Wenn jemand mein Wort bewahren wird, so wird er den Tod nicht schmecken ewiglich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Bist du etwa größer als unser Vater Abraham, der gestorben ist? Und die Propheten sind gestorben. Was machst du aus dir selbst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jesus antwortete: Wenn ich mich selbst ehre, so ist meine Ehre nichts; mein Vater ist es, der mich ehrt, von welchem ihr saget: Er ist unser Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Und ihr habt ihn nicht erkannt, ich aber kenne ihn; und wenn ich sagte: Ich kenne ihn nicht, so würde ich euch gleich sein, ein Lügner. Aber ich kenne ihn, und ich bewahre sein Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, euer Vater, frohlockte, daß er meinen Tag sehen sollte, und er sah ihn und freute sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Da sprachen die Juden zu ihm: Du bist noch nicht fünfzig Jahre alt und hast Abraham gesehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jesus sprach zu ihnen: Wahrlich, wahrlich, ich sage euch: Ehe Abraham ward, bin ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Da hoben sie Steine auf, damit sie auf ihn würfen. Jesus aber verbarg sich und ging aus dem Tempel hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Und als er vorüberging, sah er einen Menschen, blind von Geburt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Und seine Jünger fragten ihn und sagten: Rabbi, wer hat gesündigt, dieser oder seine Eltern, daß er blind geboren wurde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jesus antwortete: Weder dieser hat gesündigt, noch seine Eltern, sondern auf daß die Werke Gottes an ihm geoffenbart würden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Ich muß die Werke dessen wirken, der mich gesandt hat, so lange es Tag ist; es kommt die Nacht, da niemand wirken kann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'So lange ich in der Welt bin, bin ich das Licht der Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Als er dies gesagt hatte, spützte er auf die Erde und bereitete einen Kot aus dem Speichel und strich den Kot wie Salbe auf seine Augen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'und er sprach zu ihm: Gehe hin, wasche dich in dem Teiche Siloam (was verdolmetscht wird: Gesandt). Da ging er hin und wusch sich und kam sehend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Die Nachbarn nun und die ihn früher gesehen hatten, daß er ein Bettler war, sprachen: Ist dieser nicht der, der da saß und bettelte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Einige sagten: Er ist es; andere sagten: Nein, sondern er ist ihm ähnlich; er sagte: Ich bin\'s.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Sie sprachen nun zu ihm: Wie sind deine Augen aufgetan worden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Er antwortete und sprach: Ein Mensch, genannt Jesus, bereitete einen Kot und salbte meine Augen damit und sprach zu mir: Gehe hin nach Siloam und wasche dich. Als ich aber hinging und mich wusch, wurde ich sehend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Da sprachen sie zu ihm: Wo ist jener? Er sagt: Ich weiß es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Sie führen ihn, den einst Blinden, zu den Pharisäern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Es war aber Sabbath, als Jesus den Kot bereitete und seine Augen auftat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Nun fragten ihn wiederum auch die Pharisäer, wie er sehend geworden sei. Er aber sprach zu ihnen: Er legte Kot auf meine Augen, und ich wusch mich, und ich sehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Da sprachen etliche von den Pharisäern: Dieser Mensch ist nicht von Gott, denn er hält den Sabbath nicht. Andere sagten: Wie kann ein sündiger Mensch solche Zeichen tun? Und es war Zwiespalt unter ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Sie sagen nun wiederum zu dem Blinden: Was sagst du von ihm, weil er deine Augen aufgetan hat? Er aber sprach: Er ist ein Prophet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Es glaubten nun die Juden nicht von ihm, daß er blind war und sehend geworden, bis sie die Eltern dessen riefen, der sehend geworden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'Und sie fragten sie und sprachen: Ist dieser euer Sohn, von dem ihr saget, daß er blind geboren wurde? Wie sieht er denn jetzt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Seine Eltern antworteten ihnen und sprachen: Wir wissen, daß dieser unser Sohn ist, und daß er blind geboren wurde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'wie er aber jetzt sieht, wissen wir nicht, oder wer seine Augen aufgetan hat, wissen wir nicht. Er ist mündig; fraget ihn, er wird selbst über sich reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Dies sagten seine Eltern, weil sie die Juden fürchteten; denn die Juden waren schon übereingekommen, daß, wenn jemand ihn als Christus bekennen würde, er aus der Synagoge ausgeschlossen werden sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Deswegen sagten seine Eltern: Er ist mündig, fraget ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Sie riefen nun zum zweiten Male den Menschen, der blind war, und sprachen zu ihm: Gib Gott die Ehre! Wir wissen, daß dieser Mensch ein Sünder ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Da antwortete er: Ob er ein Sünder ist, weiß ich nicht; eines weiß ich, daß ich blind war und jetzt sehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Und sie sprachen wiederum zu ihm: Was hat er dir getan? Wie tat er deine Augen auf?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Er antwortete ihnen: Ich habe es euch schon gesagt, und ihr habt nicht gehört; warum wollt ihr es nochmals hören? Wollt ihr etwa auch seine Jünger werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Sie schmähten ihn und sprachen: Du bist sein Jünger; wir aber sind Moses\' Jünger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Wir wissen, daß Gott zu Moses geredet hat; von diesem aber wissen wir nicht, woher er ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Der Mensch antwortete und sprach zu ihnen: Hierbei ist es doch wunderbar, daß ihr nicht wisset, woher er ist, und er hat doch meine Augen aufgetan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Wir wissen aber, daß Gott Sünder nicht hört, sondern wenn jemand gottesfürchtig ist und seinen Willen tut, den hört er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Von Ewigkeit her ist es nicht erhört, daß jemand die Augen eines Blindgeborenen aufgetan habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Wenn dieser nicht von Gott wäre, so könnte er nichts tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Sie antworteten und sprachen zu ihm: Du bist ganz in Sünden geboren, und du lehrst uns? Und sie warfen ihn hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jesus hörte, daß sie ihn hinausgeworfen hatten; und als er ihn fand, sprach er zu ihm: Glaubst du an den Sohn Gottes?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Er antwortete und sprach: Und wer ist es, Herr, auf daß ich an ihn glaube?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Jesus sprach zu ihm: Du hast ihn gesehen, und der mit dir redet, der ist es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Er aber sprach: Ich glaube, Herr; und er warf sich vor ihm nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Und Jesus sprach: Zum Gericht bin ich in diese Welt gekommen, auf daß die Nichtsehenden sehen und die Sehenden blind werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Und etliche von den Pharisäern, die bei ihm waren, hörten dies und sprachen zu ihm: Sind denn auch wir blind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jesus sprach zu ihnen: Wenn ihr blind wäret, so würdet ihr keine Sünde haben; nun ihr aber saget: Wir sehen, so bleibt eure Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Wahrlich, wahrlich, ich sage euch: Wer nicht durch die Tür in den Hof der Schafe eingeht, sondern anderswo hinübersteigt, der ist ein Dieb und ein Räuber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Wer aber durch die Tür eingeht, ist Hirte der Schafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Diesem tut der Türhüter auf, und die Schafe hören seine Stimme, und er ruft seine eigenen Schafe mit Namen und führt sie heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Wenn er seine eigenen Schafe alle herausgebracht hat, geht er vor ihnen her, und die Schafe folgen ihm, weil sie seine Stimme kennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Einem Fremden aber werden sie nicht folgen, sondern werden vor ihm fliehen, weil sie die Stimme der Fremden nicht kennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Dieses Gleichnis sprach Jesus zu ihnen; sie aber verstanden nicht, was es war, das er zu ihnen redete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Jesus sprach nun wiederum zu ihnen: Wahrlich, wahrlich, ich sage euch: Ich bin die Tür der Schafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Alle, die irgend vor mir gekommen, sind Diebe und Räuber; aber die Schafe hörten nicht auf sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Ich bin die Tür; wenn jemand durch mich eingeht, so wird er errettet werden und wird ein-und ausgehen und Weide finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Der Dieb kommt nur, um zu stehlen und zu schlachten und zu verderben. Ich bin gekommen, auf daß sie Leben haben und es in Überfluß haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Ich bin der gute Hirte; der gute Hirte läßt sein Leben für die Schafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Der Mietling aber und der nicht Hirte ist, dem die Schafe nicht eigen sind, sieht den Wolf kommen und verläßt die Schafe und flieht; und der Wolf raubt sie und zerstreut die Schafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Der Mietling aber flieht, weil er ein Mietling ist und sich um die Schafe nicht kümmert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Ich bin der gute Hirte; und ich kenne die Meinen und bin gekannt von den Meinen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'gleichwie der Vater mich kennt und ich den Vater kenne; und ich lasse mein Leben für die Schafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Und ich habe andere Schafe, die nicht aus diesem Hofe sind; auch diese muß ich bringen, und sie werden meine Stimme hören, und es wird eine Herde, ein Hirte sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Darum liebt mich der Vater, weil ich mein Leben lasse, auf daß ich es wiedernehme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Niemand nimmt es von mir, sondern ich lasse es von mir selbst. Ich habe Gewalt, es zu lassen, und habe Gewalt, es wiederzunehmen. Dieses Gebot habe ich von meinem Vater empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Es entstand wiederum ein Zwiespalt unter den Juden dieser Worte wegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Viele aber von ihnen sagten: Er hat einen Dämon und ist von Sinnen; was höret ihr ihn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Andere sagten: Diese Reden sind nicht die eines Besessenen; kann etwa ein Dämon der Blinden Augen auftun?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Es war aber das Fest der Tempelweihe in Jerusalem; und es war Winter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Und Jesus wandelte in dem Tempel, in der Säulenhalle Salomons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Da umringten ihn die Juden und sprachen zu ihm: Bis wann hältst du unsere Seele hin? Wenn du der Christus bist, so sage es uns frei heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jesus antwortete ihnen: Ich habe es euch gesagt, und ihr glaubet nicht. Die Werke, die ich in dem Namen meines Vaters tue, diese zeugen von mir;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'aber ihr glaubet nicht, denn ihr seid nicht von meinen Schafen, wie ich euch gesagt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Meine Schafe hören meine Stimme, und ich kenne sie, und sie folgen mir;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'und ich gebe ihnen ewiges Leben, und sie gehen nicht verloren ewiglich, und niemand wird sie aus meiner Hand rauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Mein Vater, der sie mir gegeben hat, ist größer als alles, und niemand kann sie aus der Hand meines Vaters rauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Ich und der Vater sind eins.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Da hoben die Juden wiederum Steine auf, auf daß sie ihn steinigten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jesus antwortete ihnen: Viele gute Werke habe ich euch von meinem Vater gezeigt; für welches Werk unter denselben steiniget ihr mich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Die Juden antworteten ihm: Wegen eines guten Werkes steinigen wir dich nicht, sondern wegen Lästerung, und weil du, der du ein Mensch bist, dich selbst zu Gott machst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jesus antwortete ihnen: Steht nicht in eurem Gesetz geschrieben: \"Ich habe gesagt: Ihr seid Götter?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Wenn er jene Götter nannte, zu welchen das Wort Gottes geschah (und die Schrift kann nicht aufgelöst werden),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'saget ihr von dem, welchen der Vater geheiligt und in die Welt gesandt hat: Du lästerst, weil ich sagte: Ich bin Gottes Sohn? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Wenn ich nicht die Werke meines Vaters tue, so glaubet mir nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'wenn ich sie aber tue, so glaubet den Werken, wenn ihr auch mir nicht glaubet, auf daß ihr erkennet und glaubet, daß der Vater in mir ist und ich in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Da suchten sie wiederum ihn zu greifen, und er entging ihrer Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'Und er ging wieder weg jenseit des Jordan an den Ort, wo Johannes zuerst taufte, und er blieb daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Und viele kamen zu ihm und sagten: Johannes tat zwar kein Zeichen; alles aber, was Johannes von diesem gesagt hat, war wahr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Und viele glaubten daselbst an ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Es war aber ein Gewisser krank, Lazarus von Bethanien, aus dem Dorfe der Maria und ihrer Schwester Martha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, '(Maria aber war es, die den Herrn mit Salbe salbte und seine Füße mit ihren Haaren abtrocknete; deren Bruder Lazarus war krank.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Da sandten die Schwestern zu ihm und ließen ihm sagen: Herr, siehe, der, den du lieb hast, ist krank.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Als aber Jesus es hörte, sprach er: Diese Krankheit ist nicht zum Tode, sondern um der Herrlichkeit Gottes willen, auf daß der Sohn Gottes durch sie verherrlicht werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Jesus aber liebte die Martha und ihre Schwester und den Lazarus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Als er nun hörte, daß er krank sei, blieb er noch zwei Tage an dem Orte, wo er war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Danach spricht er dann zu den Jüngern: Laßt uns wieder nach Judäa gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Die Jünger sagen zu ihm: Rabbi, eben suchten die Juden dich zu steinigen, und wiederum gehst du dahin?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jesus antwortete: Sind der Stunden des Tages nicht zwölf? Wenn jemand am Tage wandelt, stößt er nicht an, weil er das Licht dieser Welt sieht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'wenn aber jemand in der Nacht wandelt, stößt er an, weil das Licht nicht in ihm ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Dies sprach er, und danach sagt er zu ihnen: Lazarus, unser Freund, ist eingeschlafen; aber ich gehe hin, auf daß ich ihn aufwecke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Da sprachen die Jünger zu ihm: Herr, wenn er eingeschlafen ist, so wird er geheilt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Jesus aber hatte von seinem Tode gesprochen; sie aber meinten, er rede von der Ruhe des Schlafes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Dann nun sagte ihnen Jesus gerade heraus: Lazarus ist gestorben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'und ich bin froh um euretwillen, daß ich nicht dort war, auf daß ihr glaubet; aber laßt uns zu ihm gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Da sprach Thomas, der Zwilling genannt ist, zu den Mitjüngern: Laßt auch uns gehen, auf daß wir mit ihm sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Als nun Jesus kam, fand er ihn schon vier Tage in der Gruft liegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Bethanien aber war nahe bei Jerusalem, etwa fünfzehn Stadien weit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'und viele von den Juden waren zu Martha und Maria gekommen, auf daß sie dieselben über ihren Bruder trösteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Martha nun, als sie hörte, daß Jesus komme, ging ihm entgegen. Maria aber saß im Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Da sprach Martha zu Jesu: Herr, wenn du hier gewesen wärest, so wäre mein Bruder nicht gestorben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'aber auch jetzt weiß ich, daß, was irgend du von Gott bitten magst, Gott dir geben wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jesus spricht zu ihr: Dein Bruder wird auferstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Martha spricht zu ihm: Ich weiß, daß er auferstehen wird in der Auferstehung am letzten Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jesus sprach zu ihr: Ich bin die Auferstehung und das Leben; wer an mich glaubt, wird leben, auch wenn er gestorben ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'und jeder, der da lebt und an mich glaubt, wird nicht sterben in Ewigkeit. Glaubst du dies?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Sie spricht zu ihm: Ja, Herr, ich glaube, daß du der Christus bist, der Sohn Gottes, der in die Welt kommen soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Und als sie dies gesagt hatte, ging sie hin und rief ihre Schwester Maria heimlich und sagte: Der Lehrer ist da und ruft dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Als jene es hörte, steht sie schnell auf und geht zu ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Jesus aber war noch nicht in das Dorf gekommen, sondern war an dem Orte, wo Martha ihm begegnet war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Als nun die Juden, die bei ihr im Hause waren und sie trösteten, sahen, daß Maria schnell aufstand und hinausging, folgten sie ihr, indem sie sagten: Sie geht zur Gruft, auf daß sie daselbst weine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Als nun Maria dahin kam, wo Jesus war, und ihn sah, fiel sie ihm zu Füßen und sprach zu ihm: Herr, wenn du hier gewesen wärest, so wäre mein Bruder nicht gestorben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Als nun Jesus sie weinen sah, und die Juden weinen, die mit ihr gekommen waren, seufzte er tief im Geist und erschütterte sich');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'und sprach: Wo habt ihr ihn hingelegt? Sie sagen zu ihm: Herr, komm und sieh!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jesus vergoß Tränen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Da sprachen die Juden: Siehe, wie lieb hat er ihn gehabt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Etliche aber von ihnen sagten: Konnte dieser, der die Augen des Blinden auftat, nicht machen, daß auch dieser nicht gestorben wäre?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Jesus nun, wiederum tief in sich selbst seufzend, kommt zur Gruft. Es war aber eine Höhle, und ein Stein lag darauf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jesus spricht: Nehmet den Stein weg. Die Schwester des Verstorbenen, Martha, spricht zu ihm: Herr, er riecht schon, denn er ist vier Tage hier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jesus spricht zu ihr: Habe ich dir nicht gesagt, wenn du glauben würdest, so würdest du die Herrlichkeit Gottes sehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Sie nahmen nun den Stein weg. Jesus aber hob die Augen empor und sprach: Vater, ich danke dir, daß du mich erhört hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Ich aber wußte, daß du mich allezeit erhörst; doch um der Volksmenge willen, die umhersteht, habe ich es gesagt, auf daß sie glauben, daß du mich gesandt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Und als er dies gesagt hatte, rief er mit lauter Stimme: Lazarus, komm heraus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Und der Verstorbene kam heraus, an Füßen und Händen mit Grabtüchern gebunden, und sein Gesicht war mit einem Schweißtuch umbunden. Jesus spricht zu ihnen: Löset ihn auf und laßt ihn gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Viele nun von den Juden, die zu Maria gekommen waren und sahen, was er getan hatte, glaubten an ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Etliche aber von ihnen gingen hin zu den Pharisäern und sagten ihnen, was Jesus getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Da versammelten die Hohenpriester und die Pharisäer ein Synedrium und sprachen: Was tun wir? Denn dieser Mensch tut viele Zeichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Wenn wir ihn also lassen, werden alle an ihn glauben, und die Römer werden kommen und sowohl unseren Ort als auch unsere Nation wegnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Ein Gewisser aber aus ihnen, Kajaphas, der jenes Jahr Hoherpriester war, sprach zu ihnen: Ihr wisset nichts,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'und überleget auch nicht, daß es euch nützlich ist, daß ein Mensch für das Volk sterbe und nicht die ganze Nation umkomme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Dies aber sagte er nicht aus sich selbst, sondern da er jenes Jahr Hoherpriester war, weissagte er, daß Jesus für die Nation sterben sollte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'und nicht für die Nation allein, sondern auf daß er auch die zerstreuten Kinder Gottes in eins versammelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Von jenem Tage an ratschlagten sie nun, auf daß sie ihn töteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Jesus nun wandelte nicht mehr frei öffentlich unter den Juden, sondern ging von dannen hinweg in die Gegend nahe bei der Wüste, in eine Stadt, genannt Ephraim; und daselbst verweilte er mit den Jüngern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Es war aber nahe das Passah der Juden, und viele gingen aus dem Lande hinauf nach Jerusalem vor dem Passah, auf daß sie sich reinigten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Sie suchten nun Jesum und sprachen, im Tempel stehend, untereinander: Was dünkt euch? Daß er nicht zu dem Fest kommen wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Es hatten aber die Hohenpriester und die Pharisäer Befehl gegeben, daß, wenn jemand wisse, wo er sei, er es anzeigen solle, damit sie ihn griffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Jesus nun kam sechs Tage vor dem Passah nach Bethanien, wo Lazarus, der Gestorbene, war, welchen Jesus aus den Toten auferweckt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Sie machten ihm nun daselbst ein Abendessen, und Martha diente; Lazarus aber war einer von denen, die mit ihm zu Tische lagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Da nahm Maria ein Pfund Salbe von echter, sehr kostbarer Narde und salbte die Füße Jesu und trocknete seine Füße mit ihren Haaren. Das Haus aber wurde von dem Geruch der Salbe erfüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Es sagt nun einer von seinen Jüngern, Judas, Simons Sohn, der Iskariot, der ihn überliefern sollte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Warum ist diese Salbe nicht für dreihundert Denare verkauft und den Armen gegeben worden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Er sagte dies aber, nicht weil er für die Armen besorgt war, sondern weil er ein Dieb war und die Kasse hatte und trug, was eingelegt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Da sprach Jesus: Erlaube ihr, es auf den Tag meines Begräbnisses aufbewahrt zu haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'denn die Armen habt ihr allezeit bei euch, mich aber habt ihr nicht allezeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Eine große Volksmenge aus den Juden erfuhr nun, daß er daselbst sei; und sie kamen, nicht um Jesu willen allein, sondern damit sie auch den Lazarus sähen, welchen er aus den Toten auferweckt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Die Hohenpriester aber ratschlagten, auf daß sie auch den Lazarus töteten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'weil viele von den Juden um seinetwillen hingingen und an Jesum glaubten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Des folgenden Tages, als eine große Volksmenge, die zu dem Feste gekommen war, hörte, daß Jesus nach Jerusalem komme,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'nahmen sie Palmzweige und gingen hinaus, ihm entgegen, und schrieen: Hosanna! Gepriesen sei, der da kommt im Namen des Herrn, der König Israels!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Jesus aber fand einen jungen Esel und setzte sich darauf, wie geschrieben steht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '\"Fürchte dich nicht, Tochter Zion! Siehe, dein König kommt, sitzend auf einem Eselsfüllen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Dies aber verstanden seine Jünger zuerst nicht; jedoch als Jesus verherrlicht war, dann erinnerten sie sich, daß dies von ihm geschrieben war und sie ihm dies getan hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Es bezeugte nun die Volksmenge, die bei ihm war, daß er Lazarus aus dem Grabe gerufen und ihn aus den Toten auferweckt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Darum ging ihm auch die Volksmenge entgegen, weil sie hörten, daß er dieses Zeichen getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Da sprachen die Pharisäer zueinander: Ihr sehet, daß ihr gar nichts ausrichtet; siehe, die Welt ist ihm nachgegangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Es waren aber etliche Griechen unter denen, die hinaufkamen, auf daß sie auf dem Feste anbeteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Diese nun kamen zu Philippus, dem von Bethsaida in Galiläa, und baten ihn und sagten: Herr, wir möchten Jesum sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Philippus kommt und sagt es Andreas, und wiederum kommt Andreas und Philippus, und sie sagen es Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Jesus aber antwortete ihnen und sprach: Die Stunde ist gekommen, daß der Sohn des Menschen verherrlicht werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Wahrlich, wahrlich, ich sage euch: Wenn das Weizenkorn nicht in die Erde fällt und stirbt, bleibt es allein; wenn es aber stirbt, bringt es viel Frucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Wer sein Leben liebt, wird es verlieren; und wer sein Leben in dieser Welt haßt, wird es zum ewigen Leben bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Wenn mir jemand dient, so folge er mir nach; und wo ich bin, da wird auch mein Diener sein. Wenn mir jemand dient, so wird der Vater ihn ehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Jetzt ist meine Seele bestürzt, und was soll ich sagen? Vater, rette mich aus dieser Stunde! Doch darum bin ich in diese Stunde gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Vater, verherrliche deinen Namen! Da kam eine Stimme aus dem Himmel: Ich habe ihn verherrlicht und werde ihn auch wiederum verherrlichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Die Volksmenge nun, die dastand und zuhörte, sagte, es habe gedonnert; andere sagten: Ein Engel hat mit ihm geredet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jesus antwortete und sprach: Nicht um meinetwillen ist diese Stimme geschehen, sondern um euretwillen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Jetzt ist das Gericht dieser Welt; jetzt wird der Fürst dieser Welt hinausgeworfen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Und ich, wenn ich von der Erde erhöht bin, werde alle zu mir ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, '(Dies aber sagte er, andeutend, welches Todes er sterben sollte.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Die Volksmenge antwortete ihm: Wir haben aus dem Gesetz gehört, daß der Christus bleibe in Ewigkeit, und wie sagst du, daß der Sohn des Menschen erhöht werden müsse? Wer ist dieser, der Sohn des Menschen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Da sprach Jesus zu ihnen: Noch eine kleine Zeit ist das Licht unter euch; wandelt, während ihr das Licht habt, auf daß nicht Finsternis euch ergreife. Und wer in der Finsternis wandelt, weiß nicht, wohin er geht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Während ihr das Licht habt, glaubet an das Licht, auf daß ihr Söhne des Lichtes werdet. Dieses redete Jesus und ging hinweg und verbarg sich vor ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Wiewohl er aber so viele Zeichen vor ihnen getan hatte, glaubten sie nicht an ihn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'auf daß das Wort des Propheten Jesajas erfüllt würde, welches er sprach: \"Herr, wer hat unserer Verkündigung geglaubt, und wem ist der Arm des Herrn geoffenbart worden?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Darum konnten sie nicht glauben, weil Jesajas wiederum gesagt hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '\"Er hat ihre Augen verblendet und ihr Herz verstockt, auf daß sie nicht sehen mit den Augen und verstehen mit dem Herzen und sich bekehren, und ich sie heile.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Dies sprach Jesaja, weil er seine Herrlichkeit sah und von ihm redete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Dennoch aber glaubten auch von den Obersten viele an ihn; doch wegen der Pharisäer bekannten sie ihn nicht, auf daß sie nicht aus der Synagoge ausgeschlossen würden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'denn sie liebten die Ehre bei den Menschen mehr als die Ehre bei Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Jesus aber rief und sprach: Wer an mich glaubt, glaubt nicht an mich, sondern an den, der mich gesandt hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'und wer mich sieht, sieht den, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Ich bin als Licht in die Welt gekommen, auf daß jeder, der an mich glaubt, nicht in der Finsternis bleibe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'und wenn jemand meine Worte hört und nicht bewahrt, so richte ich ihn nicht, denn ich bin nicht gekommen, auf daß ich die Welt richte, sondern auf daß ich die Welt errette.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Wer mich verwirft und meine Worte nicht annimmt, hat den, der ihn richtet: das Wort, das ich geredet habe, das wird ihn richten an dem letzten Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Denn ich habe nicht aus mir selbst geredet, sondern der Vater, der mich gesandt hat, er hat mir ein Gebot gegeben, was ich sagen und was ich reden soll;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'und ich weiß, daß sein Gebot ewiges Leben ist. Was ich nun rede, rede ich also, wie mir der Vater gesagt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Vor dem Feste des Passah aber, als Jesus wußte, daß seine Stunde gekommen war, daß er aus dieser Welt zu dem Vater hingehen sollte, da er die Seinigen, die in der Welt waren, geliebt hatte, liebte er sie bis ans Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Und während des Abendessens, als der Teufel schon dem Judas, Simons Sohn, dem Iskariot, es ins Herz gegeben hatte, daß er ihn überliefere,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'steht Jesus, wissend, daß der Vater ihm alles in die Hände gegeben, und daß er von Gott ausgegangen war und zu Gott hingehe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'von dem Abendessen auf und legt die Oberkleider ab; und er nahm ein leinenes Tuch und umgürtete sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Dann gießt er Wasser in das Waschbecken und fing an, die Füße der Jünger zu waschen und mit dem leinenen Tuch abzutrocknen, mit welchem er umgürtet war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Er kommt nun zu Simon Petrus, und der spricht zu ihm: Herr, du wäschest meine Füße?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jesus antwortete und sprach zu ihm: Was ich tue, weißt du jetzt nicht, du wirst es aber hernach verstehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Petrus spricht zu ihm: Du sollst nimmermehr meine Füße waschen! Jesus antwortete ihm: Wenn ich dich nicht wasche, so hast du kein Teil mit mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Simon Petrus spricht zu ihm: Herr, nicht meine Füße allein, sondern auch die Hände und das Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jesus spricht zu ihm: Wer gebadet ist, hat nicht nötig sich zu waschen, ausgenommen die Füße, sondern ist ganz rein; und ihr seid rein, aber nicht alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Denn er kannte den, der ihn überlieferte; darum sagte er: Ihr seid nicht alle rein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Als er nun ihre Füße gewaschen und seine Oberkleider genommen hatte, legte er sich wiederum zu Tische und sprach zu ihnen: Wisset ihr, was ich euch getan habe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Ihr heißet mich Lehrer und Herr, und ihr saget recht, denn ich bin es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Wenn nun ich, der Herr und der Lehrer, eure Füße gewaschen habe, so seid auch ihr schuldig, einander die Füße zu waschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Denn ich habe euch ein Beispiel gegeben, auf daß, gleichwie ich euch getan habe, auch ihr tuet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Wahrlich, wahrlich, ich sage euch: Ein Knecht ist nicht größer als sein Herr, noch ein Gesandter größer, als der ihn gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Wenn ihr dies wisset, glückselig seid ihr, wenn ihr es tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Ich rede nicht von euch allen, ich weiß, welche ich auserwählt habe; aber auf daß die Schrift erfüllt würde: \"Der mit mir das Brot ißt, hat seine Ferse wider mich aufgehoben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Von jetzt an sage ich es euch, ehe es geschieht, auf daß ihr, wenn es geschieht, glaubet, daß ich es bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Wahrlich, wahrlich, ich sage euch: Wer aufnimmt, wen irgend ich senden werde, nimmt mich auf; wer aber mich aufnimmt, nimmt den auf, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Als Jesus dies gesagt hatte, ward er im Geiste erschüttert und bezeugte und sprach: Wahrlich, wahrlich, ich sage euch: Einer von euch wird mich überliefern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Da blickten die Jünger einander an, zweifelnd, von wem er rede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Einer aber von seinen Jüngern, den Jesus liebte, lag zu Tische in dem Schoße Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Diesem nun winkt Simon Petrus, damit er forschen möchte, wer es wohl wäre, von welchem er rede.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Jener aber, sich an die Brust Jesu lehnend, spricht zu ihm: Herr, wer ist es?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jesus antwortete: Jener ist es, welchem ich den Bissen, wenn ich ihn eingetaucht habe, geben werde. Und als er den Bissen eingetaucht hatte, gibt er ihn dem Judas, Simons Sohn, dem Iskariot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Und nach dem Bissen fuhr alsdann der Satan in ihn. Jesus spricht nun zu ihm: Was du tust, tue schnell.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Keiner aber von den zu Tische Liegenden verstand, wozu er ihm dies sagte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Denn etliche meinten, weil Judas die Kasse hatte, daß Jesus zu ihm sage: Kaufe, was wir für das Fest bedürfen, oder daß er den Armen etwas geben solle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Als nun jener den Bissen genommen hatte, ging er alsbald hinaus. Es war aber Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Als er nun hinausgegangen war, spricht Jesus: Jetzt ist der Sohn des Menschen verherrlicht, und Gott ist verherrlicht in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Wenn Gott verherrlicht ist in ihm, so wird auch Gott ihn verherrlichen in sich selbst, und alsbald wird er ihn verherrlichen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Kinder, noch eine kleine Weile bin ich bei euch; ihr werdet mich suchen, und wie ich den Juden sagte: Wo ich hingehe, könnt ihr nicht hinkommen, so sage ich jetzt auch euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Ein neues Gebot gebe ich euch, daß ihr einander liebet, auf daß, gleichwie ich euch geliebt habe, auch ihr einander liebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Daran werden alle erkennen, daß ihr meine Jünger seid, wenn ihr Liebe untereinander habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simon Petrus spricht zu ihm: Herr, wo gehst du hin? Jesus antwortete ihm: Wo ich hingehe, kannst du mir jetzt nicht folgen; du wirst mir aber später folgen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Petrus spricht zu ihm: Herr, warum kann ich dir jetzt nicht folgen? Mein Leben will ich für dich lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jesus antwortet: Dein Leben willst du für mich lassen? Wahrlich, wahrlich, ich sage dir, der Hahn wird nicht krähen, bis du mich dreimal verleugnet hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Euer Herz werde nicht bestürzt. Ihr glaubet an Gott, glaubet auch an mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Im Hause meines Vaters sind viele Wohnungen; wenn es nicht so wäre, würde ich es euch gesagt haben; denn ich gehe hin, euch eine Stätte zu bereiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Und wenn ich hingehe und euch eine Stätte bereite, so komme ich wieder und werde euch zu mir nehmen, auf daß, wo ich bin, auch ihr seiet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Und wo ich hingehe, wisset ihr, und den Weg wisset ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Thomas spricht zu ihm: Herr, wir wissen nicht, wo du hingehst, und wie können wir den Weg wissen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jesus spricht zu ihm: Ich bin der Weg und die Wahrheit und das Leben. Niemand kommt zum Vater, als nur durch mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Wenn ihr mich erkannt hättet, so würdet ihr auch meinen Vater erkannt haben; und von jetzt an erkennet ihr ihn und habt ihn gesehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Philippus spricht zu ihm: Herr, zeige uns den Vater, und es genügt uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jesus spricht zu ihm: So lange Zeit bin ich bei euch, und du hast mich nicht erkannt, Philippus? Wer mich gesehen hat, hat den Vater gesehen, und wie sagst du: Zeige uns den Vater? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Glaubst du nicht, daß ich in dem Vater bin und der Vater in mir ist? Die Worte, die ich zu euch rede, rede ich nicht von mir selbst; der Vater aber, der in mir bleibt, er tut die Werke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Glaubet mir, daß ich in dem Vater bin und der Vater in mir ist; wenn aber nicht, so glaubet mir um der Werke selbst willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Wahrlich, wahrlich, ich sage euch: Wer an mich glaubt, der wird auch die Werke tun, die ich tue, und wird größere als diese tun, weil ich zum Vater gehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Und was irgend ihr bitten werdet in meinem Namen, das werde ich tun, auf daß der Vater verherrlicht werde in dem Sohne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Wenn ihr etwas bitten werdet in meinem Namen, so werde ich es tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Wenn ihr mich liebet, so haltet meine Gebote;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'und ich werde den Vater bitten, und er wird euch einen anderen Sachwalter geben, daß er bei euch sei in Ewigkeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'den Geist der Wahrheit, den die Welt nicht empfangen kann, weil sie ihn nicht sieht noch ihn kennt. Ihr aber kennet ihn, denn er bleibt bei euch und wird in euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Ich werde euch nicht als Waisen lassen, ich komme zu euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Noch ein Kleines, und die Welt sieht mich nicht mehr; ihr aber sehet mich: Weil ich lebe, werdet auch ihr leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'An jenem Tage werdet ihr erkennen, daß ich in meinem Vater bin, und ihr in mir und ich in euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Wer meine Gebote hat und sie hält, der ist es, der mich liebt; wer aber mich liebt, wird von meinem Vater geliebt werden; und ich werde ihn lieben und mich selbst ihm offenbar machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Judas, nicht der Iskariot, spricht zu ihm: Herr, wie ist es, daß du dich uns offenbar machen willst, und nicht der Welt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jesus antwortete und sprach zu ihm: Wenn jemand mich liebt, so wird er mein Wort halten, und mein Vater wird ihn lieben, und wir werden zu ihm kommen und Wohnung bei ihm machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Wer mich nicht liebt, hält meine Worte nicht; und das Wort, welches ihr höret, ist nicht mein, sondern des Vaters, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Dies habe ich zu euch geredet, während ich bei euch bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Der Sachwalter aber, der Heilige Geist, welchen der Vater senden wird in meinem Namen, jener wird euch alles lehren und euch an alles erinnern, was ich euch gesagt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Frieden lasse ich euch, meinen Frieden gebe ich euch; nicht wie die Welt gibt, gebe ich euch. Euer Herz werde nicht bestürzt, sei auch nicht furchtsam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Ihr habt gehört, daß ich euch gesagt habe: Ich gehe hin, und ich komme zu euch. Wenn ihr mich liebtet, so würdet ihr euch freuen, daß ich zum Vater gehe, denn mein Vater ist größer als ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Und jetzt habe ich es euch gesagt, ehe es geschieht, auf daß, wenn es geschieht, ihr glaubet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Ich werde nicht mehr vieles mit euch reden, denn der Fürst der Welt kommt und hat nichts in mir;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'aber auf daß die Welt erkenne, daß ich den Vater liebe und also tue, wie mir der Vater geboten hat. Stehet auf, lasset uns von hinnen gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Ich bin der wahre Weinstock, und mein Vater ist der Weingärtner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Jede Rebe an mir, die nicht Frucht bringt, die nimmt er weg; und jede, die Frucht bringt, die reinigt er, auf daß sie mehr Frucht bringe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Ihr seid schon rein um des Wortes willen, das ich zu euch geredet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Bleibet in mir, und ich in euch. Gleichwie die Rebe nicht von sich selbst Frucht bringen kann, sie bleibe denn am Weinstock, also auch ihr nicht, ihr bleibet denn in mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Ich bin der Weinstock, ihr seid die Reben. Wer in mir bleibt und ich in ihm, dieser bringt viel Frucht, denn außer mir könnt ihr nichts tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Wenn jemand nicht in mir bleibt, so wird er hinausgeworfen wie die Rebe und verdorrt; und man sammelt sie und wirft sie ins Feuer, und sie verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Wenn ihr in mir bleibet und meine Worte in euch bleiben, so werdet ihr bitten, was ihr wollt, und es wird euch geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Hierin wird mein Vater verherrlicht, daß ihr viel Frucht bringet, und ihr werdet meine Jünger werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Gleichwie der Vater mich geliebt hat, habe auch ich euch geliebt; bleibet in meiner Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Wenn ihr meine Gebote haltet, so werdet ihr in meiner Liebe bleiben, gleichwie ich die Gebote meines Vaters gehalten habe und in seiner Liebe bleibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Dies habe ich zu euch geredet, auf daß meine Freude in euch sei und eure Freude völlig werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Dies ist mein Gebot, daß ihr einander liebet, gleichwie ich euch geliebt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Größere Liebe hat niemand, als diese, daß jemand sein Leben läßt für seine Freunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Ihr seid meine Freunde, wenn ihr tut, was irgend ich euch gebiete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Ich nenne euch nicht mehr Knechte, denn der Knecht weiß nicht, was sein Herr tut; aber ich habe euch Freunde genannt, weil ich alles, was ich von meinem Vater gehört, euch kundgetan habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ihr habt nicht mich auserwählt, sondern ich habe euch auserwählt und euch gesetzt, auf daß ihr hingehet und Frucht bringet, und eure Frucht bleibe, auf daß, was irgend ihr den Vater bitten werdet in meinem Namen, er euch gebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Dies gebiete ich euch, daß ihr einander liebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Wenn die Welt euch haßt, so wisset, daß sie mich vor euch gehaßt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Wenn ihr von der Welt wäret, würde die Welt das Ihrige lieben; weil ihr aber nicht von der Welt seid, sondern ich euch aus der Welt auserwählt habe, darum haßt euch die Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Gedenket des Wortes, das ich euch gesagt habe: Ein Knecht ist nicht größer als sein Herr. Wenn sie mich verfolgt haben, werden sie auch euch verfolgen; wenn sie mein Wort gehalten haben, werden sie auch das eure halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Aber dies alles werden sie euch tun um meines Namens willen, weil sie den nicht kennen, der mich gesandt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Wenn ich nicht gekommen wäre und zu ihnen geredet hätte, so hätten sie keine Sünde; jetzt aber haben sie keinen Vorwand für ihre Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Wer mich haßt, haßt auch meinen Vater.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Wenn ich nicht die Werke unter ihnen getan hätte, die kein anderer getan hat, so hätten sie keine Sünde; jetzt aber haben sie gesehen und gehaßt sowohl mich als auch meinen Vater.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Aber auf daß das Wort erfüllt würde, das in ihrem Gesetz geschrieben steht: \"Sie haben mich ohne Ursache gehaßt\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Wenn aber der Sachwalter gekommen ist, den ich euch von dem Vater senden werde, der Geist der Wahrheit, der von dem Vater ausgeht, so wird er von mir zeugen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Aber auch ihr zeuget, weil ihr von Anfang an bei mir seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Dieses habe ich zu euch geredet, auf daß ihr euch nicht ärgert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Sie werden euch aus der Synagoge ausschließen; es kommt aber die Stunde, daß jeder, der euch tötet, meinen wird, Gott einen Dienst darzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Und dies werden sie tun, weil sie weder den Vater noch mich erkannt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Dieses aber habe ich zu euch geredet, auf daß, wenn die Stunde gekommen ist, ihr daran gedenket, daß ich es euch gesagt habe. Dieses aber habe ich euch von Anfang nicht gesagt, weil ich bei euch war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Jetzt aber gehe ich hin zu dem, der mich gesandt hat, und niemand von euch fragt mich: Wo gehst du hin?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'sondern weil ich dieses zu euch geredet habe, hat Traurigkeit euer Herz erfüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Doch ich sage euch die Wahrheit: Es ist euch nützlich, daß ich weggehe, denn wenn ich nicht weggehe, wird der Sachwalter nicht zu euch kommen; wenn ich aber hingehe, werde ich ihn zu euch senden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Und wenn er gekommen ist, wird er die Welt überführen von Sünde und von Gerechtigkeit und von Gericht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'Von Sünde, weil sie nicht an mich glauben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'von Gerechtigkeit aber, weil ich zu meinem Vater gehe, und ihr mich nicht mehr sehet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'von Gericht aber, weil der Fürst dieser Welt gerichtet ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Noch vieles habe ich euch zu sagen, aber ihr könnt es jetzt nicht tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Wenn aber jener, der Geist der Wahrheit, gekommen ist, wird er euch in die ganze Wahrheit leiten; denn er wird nicht aus sich selbst reden, sondern was irgend er hören wird, wird er reden, und das Kommende wird er euch verkündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Er wird mich verherrlichen, denn von dem Meinen wird er empfangen und euch verkündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Alles, was der Vater hat, ist mein; darum sagte ich, daß er von dem Meinen empfängt und euch verkündigen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Über ein Kleines, und ihr schauet mich nicht, und wiederum über ein Kleines, und ihr werdet mich sehen weil ich zum Vater hingehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Es sprachen nun etliche von seinen Jüngern zueinander: Was ist dies, das er zu uns sagt: Über ein Kleines, und ihr schauet mich nicht, und wiederum über ein Kleines, und ihr werdet mich sehen, und: weil ich zum Vater hingehe? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Da sprachen sie: Was ist das für ein Kleines, wovon er redet? Wir wissen nicht, was er sagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Da erkannte Jesus, daß sie ihn fragen wollten, und sprach zu ihnen: Forschet ihr darüber untereinander, daß ich sagte: Über ein Kleines, und ihr schauet mich nicht, und wiederum über ein Kleines, und ihr werdet mich sehen? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Wahrlich, wahrlich, ich sage euch, daß ihr weinen und wehklagen werdet, aber die Welt wird sich freuen; ihr werdet traurig sein, aber eure Traurigkeit wird zur Freude werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Das Weib, wenn sie gebiert, hat Traurigkeit, weil ihre Stunde gekommen ist; wenn sie aber das Kind geboren hat, gedenkt sie nicht mehr der Drangsal, um der Freude willen, daß ein Mensch zur Welt geboren ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Auch ihr nun habt jetzt zwar Traurigkeit; aber ich werde euch wiedersehen, und euer Herz wird sich freuen, und eure Freude nimmt niemand von euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Und an jenem Tage werdet ihr mich nichts fragen. Wahrlich, wahrlich, ich sage euch: Was irgend ihr den Vater bitten werdet in meinem Namen, wird er euch geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Bis jetzt habt ihr nichts gebeten in meinem Namen. Bittet, und ihr werdet empfangen, auf daß eure Freude völlig sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Dies habe ich in Gleichnissen zu euch geredet; es kommt die Stunde, da ich nicht mehr in Gleichnissen zu euch reden, sondern euch offen von dem Vater verkündigen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'An jenem Tage werdet ihr bitten in meinem Namen, und ich sage euch nicht, daß ich den Vater für euch bitten werde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'denn der Vater selbst hat euch lieb, weil ihr mich geliebt und geglaubt habt, daß ich von Gott ausgegangen bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Ich bin von dem Vater ausgegangen und bin in die Welt gekommen; wiederum verlasse ich die Welt und gehe zum Vater.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Seine Jünger sprechen zu ihm: Siehe, jetzt redest du offen und sprichst kein Gleichnis;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'jetzt wissen wir, daß du alles weißt und nicht nötig hast, daß dich jemand frage; hierdurch glauben wir, daß du von Gott ausgegangen bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jesus antwortete ihnen: Glaubet ihr jetzt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Siehe, es kommt die Stunde und ist gekommen, daß ihr zerstreut sein werdet, ein jeder in das Seinige, und mich allein lassen werdet; und ich bin nicht allein, denn der Vater ist bei mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Dieses habe ich zu euch geredet, auf daß ihr in mir Frieden habet. In der Welt habt ihr Drangsal; aber seid gutes Mutes, ich habe die Welt überwunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Dieses redete Jesus und hob seine Augen auf gen Himmel und sprach: Vater, die Stunde ist gekommen; verherrliche deinen Sohn, auf daß dein Sohn dich verherrliche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Gleichwie du ihm Gewalt gegeben hast über alles Fleisch, auf daß er allen, die du ihm gegeben, ewiges Leben gebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Dies aber ist das ewige Leben, daß sie dich, den allein wahren Gott, und den du gesandt hast, Jesum Christum, erkennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Ich habe dich verherrlicht auf der Erde; das Werk habe ich vollbracht, welches du mir gegeben hast, daß ich es tun sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Und nun verherrliche du, Vater, mich bei dir selbst mit der Herrlichkeit, die ich bei dir hatte, ehe die Welt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Ich habe deinen Namen geoffenbart den Menschen, die du mir aus der Welt gegeben hast. Dein waren sie, und mir hast du sie gegeben, und sie haben dein Wort bewahrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Jetzt haben sie erkannt, daß alles, was du mir gegeben hast, von dir ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'denn die Worte, die du mir gegeben hast, habe ich ihnen gegeben, und sie haben sie angenommen und wahrhaftig erkannt, daß ich von dir ausgegangen bin, und haben geglaubt, daß du mich gesandt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Ich bitte für sie; nicht für die Welt bitte ich, sondern für die, welche du mir gegeben hast, denn sie sind dein');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, '(und alles, was mein ist, ist dein, und was dein ist, mein), und ich bin in ihnen verherrlicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Und ich bin nicht mehr in der Welt, und diese sind in der Welt, und ich komme zu dir. Heiliger Vater! Bewahre sie in deinem Namen, den du mir gegeben hast, auf daß sie eins seien, gleichwie wir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Als ich bei ihnen war, bewahrte ich sie in deinem Namen, den du mir gegeben hast; und ich habe sie behütet, und keiner von ihnen ist verloren, als nur der Sohn des Verderbens, auf daß die Schrift erfüllt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Jetzt aber komme ich zu dir; und dieses rede ich in der Welt, auf daß sie meine Freude völlig in sich haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Ich habe ihnen dein Wort gegeben, und die Welt hat sie gehaßt, weil sie nicht von der Welt sind, gleichwie ich nicht von der Welt bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Ich bitte nicht, daß du sie aus der Welt wegnehmest, sondern daß du sie bewahrest vor dem Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Sie sind nicht von der Welt, gleichwie ich nicht von der Welt bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Heilige sie durch die Wahrheit: dein Wort ist Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Gleichwie du mich in die Welt gesandt hast, habe auch ich sie in die Welt gesandt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'und ich heilige mich selbst für sie, auf daß auch sie Geheiligte seien durch Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Aber nicht für diese allein bitte ich, sondern auch für die, welche durch ihr Wort an mich glauben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'auf daß sie alle eins seien, gleichwie du, Vater, in mir und ich in dir, auf daß auch sie in uns eins seien, auf daß die Welt glaube, daß du mich gesandt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Und die Herrlichkeit, die du mir gegeben hast, habe ich ihnen gegeben, auf daß sie eins seien, gleichwie wir eins sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'ich in ihnen und du in mir, auf daß sie in eins vollendet seien, und auf daß die Welt erkenne, daß du mich gesandt und sie geliebt hast, gleichwie du mich geliebt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Vater, ich will, daß die, welche du mir gegeben hast, auch bei mir seien, wo ich bin, auf daß sie meine Herrlichkeit schauen, die du mir gegeben hast, denn du hast mich geliebt vor Grundlegung der Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Gerechter Vater! Und die Welt hat dich nicht erkannt; ich aber habe dich erkannt, und diese haben erkannt, daß du mich gesandt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Und ich habe ihnen deinen Namen kundgetan und werde ihn kundtun, auf daß die Liebe, womit du mich geliebt hast, in ihnen sei und ich in ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Als Jesus dieses gesagt hatte, ging er mit seinen Jüngern hinaus über den Bach Kidron, wo ein Garten war, in welchen er hineinging, er und seine Jünger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Aber auch Judas, der ihn überlieferte, wußte den Ort, weil Jesus sich oft daselbst mit seinen Jüngern versammelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Als nun Judas die Schar und von den Hohenpriestern und Pharisäern Diener genommen hatte, kommt er dahin mit Leuchten und Fackeln und Waffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Jesus nun, der alles wußte, was über ihn kommen würde, ging hinaus und sprach zu ihnen: Wen suchet ihr?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Sie antworteten ihm: Jesum, den Nazaräer. Jesus spricht zu ihnen: Ich bin\'s. Aber auch Judas, der ihn überlieferte, stand bei ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Als er nun zu ihnen sagte: Ich bin\'s, wichen sie zurück und fielen zu Boden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Da fragte er sie wiederum: Wen suchet ihr? Sie aber sprachen: Jesum, den Nazaräer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jesus antwortete: Ich habe euch gesagt, daß ich es bin; wenn ihr nun mich suchet, so laßt diese gehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'auf daß das Wort erfüllt würde, welches er sprach: Von denen, die du mir gegeben hast, habe ich keinen verloren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Simon Petrus nun, der ein Schwert hatte, zog es und schlug den Knecht des Hohenpriesters und hieb ihm das rechte Ohr ab. Der Name des Knechtes aber war Malchus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Da sprach Jesus zu Petrus: Stecke das Schwert in die Scheide. Den Kelch, den mir der Vater gegeben hat, soll ich den nicht trinken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Die Schar nun und der Oberste und die Diener der Juden nahmen Jesum und banden ihn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'und sie führten ihn zuerst hin zu Annas, denn er war Schwiegervater des Kajaphas, der jenes Jahr Hoherpriester war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Kajaphas aber war es, der den Juden geraten hatte, es sei nützlich, daß ein Mensch für das Volk sterbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Simon Petrus aber folgte Jesu und der andere Jünger. Dieser Jünger aber war dem Hohenpriester bekannt und ging mit Jesu hinein in den Hof des Hohenpriesters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Petrus aber stand an der Tür draußen. Da ging der andere Jünger, der dem Hohenpriester bekannt war, hinaus und sprach mit der Türhüterin und führte Petrus hinein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Da spricht die Magd, die Türhüterin, zu Petrus: Bist nicht auch du einer von den Jüngern dieses Menschen? Er sagt: Ich bin\'s nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Es standen aber die Knechte und die Diener, die ein Kohlenfeuer gemacht hatten, weil es kalt war, und wärmten sich; Petrus aber stand auch bei ihnen und wärmte sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Der Hohepriester nun fragte Jesum über seine Jünger und über seine Lehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jesus antwortete ihm: Ich habe öffentlich zu der Welt geredet; ich habe allezeit in der Synagoge und in dem Tempel gelehrt, wo alle Juden zusammenkommen, und im Verborgenen habe ich nichts geredet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'was fragst du mich? Frage die, welche gehört, was ich zu ihnen geredet habe; siehe, diese wissen, was ich gesagt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Als er aber dieses sagte, gab einer der Diener, der dabeistand, Jesu einen Backenstreich und sagte: Antwortest du also dem Hohenpriester?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jesus antwortete ihm: Wenn ich übel geredet habe, so gib Zeugnis von dem Übel; wenn aber recht, was schlägst du mich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Annas nun hatte ihn gebunden zu Kajaphas, dem Hohenpriester, gesandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Simon Petrus aber stand und wärmte sich. Da sprachen sie zu ihm: Bist nicht auch du einer von seinen Jüngern? Er leugnete und sprach: Ich bin\'s nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Es spricht einer von den Knechten des Hohenpriesters, der ein Verwandter dessen war, welchem Petrus das Ohr abgehauen hatte: Sah ich dich nicht in dem Garten bei ihm?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Da leugnete Petrus wiederum; und alsbald krähte der Hahn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Sie führen nun Jesum von Kajaphas in das Prätorium; es war aber frühmorgens. Und sie gingen nicht hinein in das Prätorium, auf daß sie sich nicht verunreinigten, sondern das Passah essen möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Pilatus ging nun zu ihnen hinaus und sprach: Welche Anklage bringet ihr wider diesen Menschen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Sie antworteten und sprachen zu ihm: Wenn dieser nicht ein Übeltäter wäre, würden wir ihn dir nicht überliefert haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Da sprach Pilatus zu ihnen: Nehmet ihr ihn und richtet ihn nach eurem Gesetz. Da sprachen die Juden zu ihm: Es ist uns nicht erlaubt, jemand zu töten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'auf daß das Wort Jesu erfüllt würde, das er sprach, andeutend, welches Todes er sterben sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Pilatus ging nun wieder hinein in das Prätorium und rief Jesum und sprach zu ihm: Bist du der König der Juden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jesus antwortete ihm: Sagst du dies von dir selbst, oder haben dir andere von mir gesagt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilatus antwortete: Bin ich etwa ein Jude? Deine Nation und die Hohenpriester haben dich mir überliefert; was hast du getan?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jesus antwortete: Mein Reich ist nicht von dieser Welt; wenn mein Reich von dieser Welt wäre, so hätten meine Diener gekämpft, auf daß ich den Juden nicht überliefert würde; jetzt aber ist mein Reich nicht von hier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Da sprach Pilatus zu ihm: Also du bist ein König? Jesus antwortete: Du sagst es, daß ich ein König bin. Ich bin dazu geboren und dazu in die Welt gekommen, auf daß ich der Wahrheit Zeugnis gebe. Jeder, der aus der Wahrheit ist, hört meine Stimme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilatus spricht zu ihm: Was ist Wahrheit? Und als er dies gesagt hatte, ging er wieder zu den Juden hinaus und spricht zu ihnen: Ich finde keinerlei Schuld an ihm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'ihr habt aber eine Gewohnheit, daß ich euch an dem Passah einen losgebe. Wollt ihr nun, daß ich euch den König der Juden losgebe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Da schrieen wiederum alle und sagten: Nicht diesen, sondern den Barabbas! Barabbas aber war ein Räuber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Dann nahm nun Pilatus Jesum und ließ ihn geißeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Und die Kriegsknechte flochten eine Krone aus Dornen und setzten sie auf sein Haupt und warfen ihm ein Purpurkleid um;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'und sie kamen zu ihm und sagten: Sei gegrüßt, König der Juden! und sie gaben ihm Backenstreiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Und Pilatus ging wieder hinaus und spricht zu ihnen: Siehe, ich führe ihn zu euch heraus, auf daß ihr wisset, daß ich keinerlei Schuld an ihm finde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Jesus nun ging hinaus, die Dornenkrone und das Purpurkleid tragend. Und er spricht zu ihnen: Siehe, der Mensch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Als ihn nun die Hohenpriester und die Diener sahen, schrieen sie und sagten: Kreuzige, kreuzige ihn! Pilatus spricht zu ihnen: Nehmet ihr ihn hin und kreuziget ihn, denn ich finde keine Schuld an ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Die Juden antworteten ihm: Wir haben ein Gesetz, und nach unserem Gesetz muß er sterben, weil er sich selbst zu Gottes Sohn gemacht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Als nun Pilatus dieses Wort hörte, fürchtete er sich noch mehr;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'und er ging wieder hinein in das Prätorium und spricht zu Jesu: Wo bist du her? Jesus aber gab ihm keine Antwort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Da spricht Pilatus zu ihm: Redest du nicht mit mir? Weißt du nicht, daß ich Gewalt habe, dich loszugeben, und Gewalt habe, dich zu kreuzigen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jesus antwortete: Du hättest keinerlei Gewalt wider mich, wenn sie dir nicht von oben gegeben wäre; darum hat der, welcher mich dir überliefert hat, größere Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Von da an suchte Pilatus ihn loszugeben. Die Juden aber schrieen und sagten: Wenn du diesen losgibst, bist du des Kaisers Freund nicht; jeder, der sich selbst zum König macht, spricht wider den Kaiser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Als nun Pilatus diese Worte hörte, führte er Jesum hinaus und setzte sich auf den Richterstuhl an einen Ort, genannt Steinpflaster, auf hebräisch aber Gabbatha.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Es war aber Rüsttag des Passah; es war um die sechste Stunde. Und er spricht zu den Juden: Siehe, euer König!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Sie aber schrieen: Hinweg, hinweg! Kreuzige ihn! Pilatus spricht zu ihnen: Euren König soll ich kreuzigen? Die Hohenpriester antworteten: Wir haben keinen König, als nur den Kaiser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Dann nun überlieferte er ihn denselben, auf daß er gekreuzigt würde. Sie aber nahmen Jesum hin und führten ihn fort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Und sein Kreuz tragend, ging er hinaus nach der Stätte, genannt Schädelstätte, die auf hebräisch Golgatha heißt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'wo sie ihn kreuzigten, und zwei andere mit ihm, auf dieser und auf jener Seite, Jesum aber in der Mitte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Pilatus schrieb aber auch eine Überschrift und setzte sie auf das Kreuz. Es war aber geschrieben: Jesus, der Nazaräer, der König der Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Diese Überschrift nun lasen viele von den Juden, denn die Stätte, wo Jesus gekreuzigt wurde, war nahe bei der Stadt; und es war geschrieben auf hebräisch, griechisch und lateinisch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Die Hohenpriester der Juden sagten nun zu Pilatus: Schreibe nicht: Der König der Juden, sondern daß jener gesagt hat: Ich bin König der Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilatus antwortete: Was ich geschrieben habe, habe ich geschrieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Die Kriegsknechte nun nahmen, als sie Jesum gekreuzigt hatten, seine Kleider (und machten vier Teile, einem jeden Kriegsknecht einen Teil) und den Leibrock. Der Leibrock aber war ohne Naht, von oben an durchweg gewebt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Da sprachen sie zueinander: Laßt uns ihn nicht zerreißen, sondern um ihn losen, wessen er sein soll; auf daß die Schrift erfüllt würde, welche spricht: \"Sie haben meine Kleider unter sich verteilt, und über mein Gewand haben sie das Los geworfen\". Die Kriegsknechte nun haben dies getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Es standen aber bei dem Kreuze Jesu seine Mutter und die Schwester seiner Mutter, Maria, des Kleopas Weib, und Maria Magdalene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Als nun Jesus die Mutter sah und den Jünger, welchen er liebte, dabeistehen, spricht er zu seiner Mutter: Weib, siehe, dein Sohn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Dann spricht er zu dem Jünger: Siehe, deine Mutter! Und von jener Stunde an nahm der Jünger sie zu sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Danach, da Jesus wußte, daß alles schon vollbracht war, spricht er, auf daß die Schrift erfüllt würde: Mich dürstet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Es stand nun daselbst ein Gefäß voll Essig. Sie aber füllten einen Schwamm mit Essig und legten ihn um einen Ysop und brachten ihn an seinen Mund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Als nun Jesus den Essig genommen hatte, sprach er: Es ist vollbracht! und er neigte das Haupt und übergab den Geist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Die Juden nun baten den Pilatus, damit die Leiber nicht am Sabbath am Kreuze blieben, weil es Rüsttag war (denn der Tag jenes Sabbaths war groß), daß ihre Beine gebrochen und sie abgenommen werden möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Da kamen die Kriegsknechte und brachen die Beine des ersten und des anderen, der mit ihm gekreuzigt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Als sie aber zu Jesu kamen und sahen, daß er schon gestorben war, brachen sie ihm die Beine nicht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'sondern einer der Kriegsknechte durchbohrte mit einem Speer seine Seite, und alsbald kam Blut und Wasser heraus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Und der es gesehen hat, hat es bezeugt, und sein Zeugnis ist wahrhaftig; und er weiß, daß er sagt, was wahr ist, auf daß auch ihr glaubet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Denn dies geschah, auf daß die Schrift erfüllt würde: \"Kein Bein von ihm wird zerbrochen werden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Und wiederum sagt eine andere Schrift: \"Sie werden den anschauen, welchen sie durchstochen haben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Nach diesem aber bat Joseph von Arimathia, der ein Jünger Jesu war, aber aus Furcht vor den Juden ein verborgener, den Pilatus, daß er den Leib Jesu abnehmen dürfe. Und Pilatus erlaubte es. Er kam nun und nahm den Leib Jesu ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Es kam aber auch Nikodemus, der zuerst bei Nacht zu Jesu gekommen war, und brachte eine Mischung von Myrrhe und Aloe, bei hundert Pfund.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Sie nahmen nun den Leib Jesu und wickelten ihn in leinene Tücher mit den Spezereien, wie es bei den Juden Sitte ist, zum Begräbnis zuzubereiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Es war aber an dem Orte, wo er gekreuzigt wurde, ein Garten, und in dem Garten eine neue Gruft, in welche noch nie jemand gelegt worden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Dorthin nun, wegen des Rüsttags der Juden, weil die Gruft nahe war, legten sie Jesum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'An dem ersten Wochentage aber kommt Maria Magdalene früh, als es noch finster war, zur Gruft und sieht den Stein von der Gruft weggenommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Sie läuft nun und kommt zu Simon Petrus und zu dem anderen Jünger, den Jesus lieb hatte, und spricht zu ihnen: Sie haben den Herrn aus der Gruft weggenommen, und wir wissen nicht, wo sie ihn hingelegt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Da ging Petrus hinaus und der andere Jünger, und sie gingen zu der Gruft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Die beiden aber liefen zusammen, und der andere Jünger lief voraus, schneller als Petrus, und kam zuerst zu der Gruft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'und sich vornüberbückend, sieht er die leinenen Tücher liegen; doch ging er nicht hinein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Da kommt Simon Petrus, ihm folgend, und ging hinein in die Gruft und sieht die leinenen Tücher liegen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'und das Schweißtuch, welches auf seinem Haupte war, nicht bei den leinenen Tüchern liegen, sondern besonders zusammengewickelt an einem Orte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Dann ging nun auch der andere Jünger hinein, der zuerst zu der Gruft kam, und er sah und glaubte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Denn sie kannten die Schrift noch nicht, daß er aus den Toten auferstehen mußte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Es gingen nun die Jünger wieder heim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Maria aber stand bei der Gruft, draußen, und weinte. Als sie nun weinte, bückte sie sich vornüber in die Gruft');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'und sieht zwei Engel in weißen Kleidern sitzen, einen zu dem Haupte und einen zu den Füßen, wo der Leib Jesu gelegen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Und jene sagen zu ihr: Weib, was weinst du? Sie spricht zu ihnen: Weil sie meinen Herrn weggenommen, und ich nicht weiß, wo sie ihn hingelegt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Als sie dies gesagt hatte, wandte sie sich zurück und sieht Jesum stehen; und sie wußte nicht, daß es Jesus sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jesus spricht zu ihr: Weib, was weinst du? Wen suchst du? Sie, in der Meinung, es sei der Gärtner, spricht zu ihm: Herr, wenn du ihn weggetragen, so sage mir, wo du ihn hingelegt hast, und ich werde ihn wegholen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jesus spricht zu ihr: Maria! Sie wendet sich um und spricht zu ihm auf hebräisch: Rabbuni! das heißt Lehrer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jesus spricht zu ihr: Rühre mich nicht an, denn ich bin noch nicht aufgefahren zu meinem Vater. Geh aber hin zu meinen Brüdern und sprich zu ihnen: Ich fahre auf zu meinem Vater und eurem Vater, und zu meinem Gott und eurem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Maria Magdalene kommt und verkündet den Jüngern, daß sie den Herrn gesehen, und er dies zu ihr gesagt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Als es nun Abend war an jenem Tage, dem ersten der Woche, und die Türen, wo die Jünger waren, aus Furcht vor den Juden verschlossen waren, kam Jesus und stand in der Mitte und spricht zu ihnen: Friede euch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Und als er dies gesagt hatte, zeigte er ihnen seine Hände und seine Seite. Da freuten sich die Jünger, als sie den Herrn sahen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Jesus sprach nun wiederum zu ihnen: Friede euch! Gleichwie der Vater mich ausgesandt hat, sende ich auch euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Und als er dies gesagt hatte, hauchte er in sie und spricht zu ihnen: Empfanget den Heiligen Geist!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Welchen irgend ihr die Sünden vergebet, denen sind sie vergeben, welchen irgend ihr sie behaltet, sind sie behalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Thomas aber, einer von den Zwölfen, genannt Zwilling, war nicht bei ihnen, als Jesus kam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Da sagten die anderen Jünger zu ihm: Wir haben den Herrn gesehen. Er aber sprach zu ihnen: Es sei denn, daß ich in seinen Händen das Mal der Nägel sehe und meine Finger in das Mal der Nägel lege, und lege meine Hand in seine Seite, so werde ich nicht glauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Und nach acht Tagen waren seine Jünger wiederum drinnen und Thomas bei ihnen. Da kommt Jesus, als die Türen verschlossen waren, und stand in der Mitte und sprach: Friede euch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Dann spricht er zu Thomas: Reiche deinen Finger her und sieh meine Hände, und reiche deine Hand her und lege sie in meine Seite, und sei nicht ungläubig, sondern gläubig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Thomas antwortete und sprach zu ihm: Mein Herr und mein Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jesus spricht zu ihm: Weil du mich gesehen hast, hast du geglaubt. Glückselig sind, die nicht gesehen und geglaubt haben!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Auch viele andere Zeichen hat nun zwar Jesus vor seinen Jüngern getan, die nicht in diesem Buche geschrieben sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Diese aber sind geschrieben, auf daß ihr glaubet, daß Jesus der Christus ist, der Sohn Gottes, und auf daß ihr glaubend Leben habet in seinem Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Nach diesem offenbarte Jesus sich wiederum den Jüngern am See von Tiberias. Er offenbarte sich aber also:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Simon Petrus und Thomas, genannt Zwilling, und Nathanael, der von Kana in Galiläa war, und die Söhne des Zebedäus und zwei andere von seinen Jüngern waren zusammen. Simon Petrus spricht zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Ich gehe hin fischen. Sie sprechen zu ihm: Auch wir gehen mit dir. Sie gingen hinaus und stiegen in das Schiff; und in jener Nacht fingen sie nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Als aber schon der frühe Morgen anbrach, stand Jesus am Ufer; doch wußten die Jünger nicht, daß es Jesus sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Jesus spricht nun zu ihnen: Kindlein, habt ihr wohl etwas zu essen? Sie antworteten ihm: Nein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Er aber sprach zu ihnen: Werfet das Netz auf der rechten Seite des Schiffes aus, und ihr werdet finden. Da warfen sie es aus und vermochten es vor der Menge der Fische nicht mehr zu ziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Da sagt jener Jünger, welchen Jesus liebte zu Petrus: Es ist der Herr. Simon Petrus nun, als er hörte, daß es der Herr sei, gürtete das Oberkleid um (denn er war nackt) und warf sich in den See.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Die anderen Jünger aber kamen in dem Schifflein, (denn sie waren nicht weit vom Lande, sondern bei zweihundert Ellen) und zogen das Netz mit den Fischen nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Als sie nun ans Land ausstiegen, sehen sie ein Kohlenfeuer liegen und Fisch darauf liegen und Brot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jesus spricht zu ihnen: Bringet her von den Fischen, die ihr jetzt gefangen habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Da ging Simon Petrus hinauf und zog das Netz voll großer Fische, hundertdreiundfünfzig, auf das Land; und wiewohl ihrer so viele waren, zerriß das Netz nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Jesus spricht zu ihnen: Kommt her, frühstücket. Keiner aber von den Jüngern wagte ihn zu fragen: Wer bist du? da sie wußten, daß es der Herr sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Jesus kommt und nimmt das Brot und gibt es ihnen, und gleicherweise den Fisch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Dies ist schon das dritte Mal, daß Jesus sich den Jüngern offenbarte, nachdem er aus den Toten auferweckt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Als sie nun gefrühstückt hatten, spricht Jesus zu Simon Petrus: Simon, Sohn Jonas\', liebst du mich mehr als diese? Er spricht zu ihm: Ja, Herr, du weißt, daß ich dich lieb habe. Spricht er zu ihm: Weide meine Lämmlein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Wiederum spricht er zum zweiten Male zu ihm: Simon, Sohn Jonas\', liebst du mich? Er spricht zu ihm: Ja, Herr, du weißt, daß ich dich lieb habe. Spricht er zu ihm: Hüte meine Schafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Er spricht zum dritten Male zu ihm: Simon, Sohn Jonas\', hast du mich lieb? Petrus wurde traurig, daß er zum dritten Male zu ihm sagte: Hast du mich lieb? und sprach zu ihm: Herr, du weißt alles; du erkennst, daß ich dich lieb habe. Jesus spricht zu ihm: Weide meine Schafe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Wahrlich, wahrlich, ich sage dir: Als du jünger warst, gürtetest du dich selbst und wandeltest, wohin du wolltest; wenn du aber alt geworden bist, wirst du deine Hände ausstrecken, und ein anderer wird dich gürten und hinbringen, wohin du nicht willst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Dies aber sagte er, andeutend, mit welchem Tode er Gott verherrlichen sollte. Und als er dies gesagt hatte, spricht er zu ihm: Folge mir nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Petrus wandte sich um und sieht den Jünger nachfolgen, welchen Jesus liebte, der sich auch bei dem Abendessen an seine Brust gelehnt und gesagt hatte: Herr, wer ist es, der dich überliefert?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Als nun Petrus diesen sah, spricht er zu Jesu: Herr, was soll aber dieser?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jesus spricht zu ihm: Wenn ich will, daß er bleibe, bis ich komme, was geht es dich an? Folge du mir nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Es ging nun dieses Wort unter die Brüder aus: Jener Jünger stirbt nicht. Und Jesus sprach nicht zu ihm, daß er nicht sterbe, sondern: Wenn ich will, daß er bleibe, bis ich komme, was geht es dich an?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Dieser ist der Jünger, der von diesen Dingen zeugt und der dieses geschrieben hat; und wir wissen, daß sein Zeugnis wahr ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Es sind aber auch viele andere Dinge, die Jesus getan hat, und wenn diese alle einzeln niedergeschrieben würden, so würde, dünkt mich, selbst die Welt die geschriebenen Bücher nicht fassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Den ersten Bericht habe ich verfaßt, o Theophilus, von allem, was Jesus anfing, sowohl zu tun als auch zu lehren,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'bis zu dem Tage, an welchem er aufgenommen wurde, nachdem er den Aposteln, die er sich auserwählt, durch den Heiligen Geist Befehl gegeben hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'welchen er sich auch nach seinem Leiden in vielen sicheren Kennzeichen lebendig dargestellt hat, indem er vierzig Tage hindurch von ihnen gesehen wurde und über die Dinge redete, welche das Reich Gottes betreffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Und als er mit ihnen versammelt war, befahl er ihnen, sich nicht von Jerusalem zu entfernen, sondern auf die Verheißung des Vaters zu warten, die ihr von mir gehört habt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'denn Johannes taufte zwar mit Wasser, ihr aber werdet mit Heiligem Geiste getauft werden nach nunmehr nicht vielen Tagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Sie nun, als sie zusammengekommen waren, fragten ihn und sagten: Herr, stellst du in dieser Zeit dem Israel das Reich wieder her?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Er sprach aber zu ihnen: Es ist nicht eure Sache, Zeiten oder Zeitpunkte zu wissen, die der Vater in seine eigene Gewalt gesetzt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Aber ihr werdet Kraft empfangen, wenn der Heilige Geist auf euch gekommen ist; und ihr werdet meine Zeugen sein, sowohl in Jerusalem als auch in ganz Judäa und Samaria und bis an das Ende der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Und als er dies gesagt hatte, wurde er emporgehoben, indem sie es sahen, und eine Wolke nahm ihn auf von ihren Augen hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Und wie sie unverwandt gen Himmel schauten, als er auffuhr, siehe, da standen zwei Männer in weißem Kleide bei ihnen, welche auch sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Männer von Galiläa, was stehet ihr und sehet hinauf gen Himmel? Dieser Jesus, der von euch weg in den Himmel aufgenommen worden ist, wird also kommen, wie ihr ihn habt hingehen sehen in den Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Da kehrten sie nach Jerusalem zurück von dem Berge, welcher Ölberg heißt, der nahe bei Jerusalem ist, einen Sabbathweg entfernt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Und als sie hineingekommen waren, stiegen sie auf den Obersaal, wo sie blieben: sowohl Petrus, als Johannes und Jakobus und Andreas, Philippus und Thomas, Bartholomäus und Matthäus, Jakobus, Alphäus\' Sohn, und Simon, der Eiferer, und Judas, Jakobus\' Bruder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Diese alle verharrten einmütig im Gebet mit etlichen Weibern und Maria, der Mutter Jesu, und mit seinen Brüdern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Und in diesen Tagen stand Petrus in der Mitte der Brüder auf und sprach (es war aber eine Menge von etwa hundertzwanzig beisammen):');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Brüder, es mußte die Schrift erfüllt werden, welche der Heilige Geist durch den Mund Davids vorhergesagt hat über Judas, der denen, die Jesum griffen, ein Wegweiser geworden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Denn er war unter uns gezählt und hatte das Los dieses Dienstes empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, '(Dieser nun hat zwar von dem Lohne der Ungerechtigkeit einen Acker erworben und ist, kopfüber gestürzt, mitten entzwei geborsten, und alle seine Eingeweide sind ausgeschüttet worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Und es ist allen Bewohnern von Jerusalem kundgeworden, so daß jener Acker in ihrer eigenen Mundart Akeldama, das ist Blutacker, genannt worden ist.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Denn es steht im Buche der Psalmen geschrieben: \"Seine Wohnung werde öde, und es sei niemand, der darin wohne\", und: \"Sein Aufseheramt empfange ein anderer\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Es muß nun von den Männern, die mit uns gegangen sind in all der Zeit, in welcher der Herr Jesus bei uns ein-und ausging,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'anfangend von der Taufe Johannes\' bis zu dem Tage, an welchem er von uns aufgenommen wurde, von diesen muß einer ein Zeuge seiner Auferstehung mit uns werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Und sie stellten zwei dar: Joseph, genannt Barsabas, der Justus zubenamt war, und Matthias.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Und sie beteten und sprachen: Du, Herr, Herzenskündiger aller, zeige von diesen beiden den einen an, den du auserwählt hast,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'um das Los dieses Dienstes und Apostelamtes zu empfangen, von welchem Judas abgewichen ist, um an seinen eigenen Ort zu gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'und sie gaben Lose über sie; und das Los fiel auf Matthias, und er wurde den elf Aposteln zugezählt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Und als der Tag der Pfingsten erfüllt wurde, waren sie alle an einem Orte beisammen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Und plötzlich geschah aus dem Himmel ein Brausen, wie von einem daherfahrenden, gewaltigen Winde, und erfüllte das ganze Haus, wo sie saßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Und es erschienen ihnen zerteilte Zungen wie von Feuer, und sie setzten sich auf jeden einzelnen von ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Und sie wurden alle mit Heiligem Geiste erfüllt und fingen an, in anderen Sprachen zu reden, wie der Geist ihnen gab auszusprechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Es wohnten aber in Jerusalem Juden, gottesfürchtige Männer, von jeder Nation derer, die unter dem Himmel sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Als sich aber das Gerücht hiervon verbreitete, kam die Menge zusammen und wurde bestürzt, weil jeder einzelne in seiner eigenen Mundart sie reden hörte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Sie entsetzten sich aber alle und verwunderten sich und sagten: Siehe, sind nicht alle diese, die da reden, Galiläer?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Und wie hören wir sie, ein jeder in unserer eigenen Mundart, in der wir geboren sind:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Parther und Meder und Elamiter, und die Bewohner von Mesopotamien und von Judäa und Kappadocien, Pontus und Asien,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'und Phrygien und Pamphylien, Ägypten und den Gegenden von Libyen gegen Kyrene hin, und die hier weilenden Römer, sowohl Juden als Proselyten, Kreter und Araber-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'wie hören wir sie die großen Taten Gottes in unseren Sprachen reden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Sie entsetzten sich aber alle und waren in Verlegenheit und sagten einer zum anderen: Was mag dies wohl sein?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Andere aber sagten spottend: Sie sind voll süßen Weines.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Petrus aber stand auf mit den Elfen, erhob seine Stimme und redete zu ihnen: Männer von Judäa, und ihr alle, die ihr zu Jerusalem wohnet, dies sei euch kund, und nehmet zu Ohren meine Worte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Denn diese sind nicht trunken, wie ihr meinet, denn es ist die dritte Stunde des Tages;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'sondern dies ist es, was durch den Propheten Joel gesagt ist:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '\"Und es wird geschehen in den letzten Tagen, spricht Gott, daß ich von meinem Geiste ausgießen werde auf alles Fleisch, und eure Söhne und eure Töchter werden weissagen, und eure Jünglinge werden Gesichte sehen, und eure Ältesten werden Träume haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'und sogar auf meine Knechte und auf meine Mägde werde ich in jenen Tagen von meinem Geiste ausgießen, und sie werden weissagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Und ich werde Wunder geben in dem Himmel oben und Zeichen auf der Erde unten: Blut und Feuer und Rauchdampf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'die Sonne wird verwandelt werden in Finsternis und der Mond in Blut, ehe der große und herrliche Tag des Herrn kommt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'Und es wird geschehen, ein jeder, der irgend den Namen des Herrn anrufen wird, wird errettet werden.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Männer von Israel, höret diese Worte: Jesum, den Nazaräer, einen Mann, von Gott an euch erwiesen durch mächtige Taten und Wunder und Zeichen, die Gott durch ihn in eurer Mitte tat, wie ihr selbst wisset-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'diesen, übergeben nach dem bestimmten Ratschluß und nach Vorkenntnis Gottes, habt ihr durch die Hand von Gesetzlosen ans Kreuz geheftet und umgebracht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Den hat Gott auferweckt, nachdem er die Wehen des Todes aufgelöst hatte, wie es denn nicht möglich war, daß er von demselben behalten würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Denn David sagt über ihn: \"Ich sah den Herrn allezeit vor mir; denn er ist zu meiner Rechten, auf daß ich nicht wanke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Darum freute sich mein Herz, und meine Zunge frohlockte; ja, auch mein Fleisch wird in Hoffnung ruhen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'denn du wirst meine Seele nicht im Hades zurücklassen, noch zugeben, daß dein Frommer Verwesung sehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Du hast mir kundgetan Wege des Lebens; du wirst mich mit Freude erfüllen mit deinem Angesicht.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Brüder, es sei erlaubt, mit Freimütigkeit zu euch zu reden über den Patriarchen David, daß er sowohl gestorben als auch begraben ist, und sein Grab ist unter uns bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Da er nun ein Prophet war und wußte, daß Gott ihm mit einem Eide geschworen hatte, von der Frucht seiner Lenden auf seinen Thron zu setzen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'hat er, voraussehend, von der Auferstehung des Christus geredet, daß er nicht im Hades zurückgelassen worden ist, noch sein Fleisch die Verwesung gesehen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Diesen Jesus hat Gott auferweckt, wovon wir alle Zeugen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Nachdem er nun durch die Rechte Gottes erhöht worden ist und die Verheißung des Heiligen Geistes vom Vater empfangen hat, hat er dieses ausgegossen, was ihr sehet und höret.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Denn nicht David ist in die Himmel aufgefahren; er sagt aber selbst: \"Der Herr sprach zu meinem Herrn: Setze dich zu meiner Rechten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'bis ich deine Feinde lege zum Schemel deiner Füße\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Das ganze Haus Israel wisse nun zuverlässig, daß Gott ihn sowohl zum Herrn als auch zum Christus gemacht hat, diesen Jesus, den ihr gekreuzigt habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Als sie aber das hörten, drang es ihnen durchs Herz, und sie sprachen zu Petrus und den anderen Aposteln:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Was sollen wir tun, Brüder? Petrus aber sprach zu ihnen: Tut Buße, und ein jeder von euch werde getauft auf den Namen Jesu Christi zur Vergebung der Sünden, und ihr werdet die Gabe des Heiligen Geistes empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Denn euch ist die Verheißung und euren Kindern und allen, die in der Ferne sind, so viele irgend der Herr, unser Gott, herzurufen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Und mit vielen anderen Worten beschwor und ermahnte er sie, indem er sagte: Laßt euch retten von diesem verkehrten Geschlecht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Die nun sein Wort aufnahmen, wurden getauft; und es wurden an jenem Tage hinzugetan bei dreitausend Seelen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Sie verharrten aber in der Lehre der Apostel und in der Gemeinschaft, im Brechen des Brotes und in den Gebeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Es kam aber jede Seele Furcht an, und es geschahen viele Wunder und Zeichen durch die Apostel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Alle aber, welche glaubten, waren beisammen und hatten alles gemein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'und sie verkauften die Güter und die Habe und verteilten sie an alle, jenachdem einer irgend Bedürfnis hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Und indem sie täglich einmütig im Tempel verharrten und zu Hause das Brot brachen, nahmen sie Speise mit Frohlocken und Einfalt des Herzens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'lobten Gott und hatten Gunst bei dem ganzen Volke. Der Herr aber tat täglich zu der Versammlung hinzu, die gerettet werden sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Petrus aber und Johannes gingen zusammen hinauf in den Tempel um die Stunde des Gebets, die neunte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Und ein gewisser Mann, der von seiner Mutter Leibe an lahm war, wurde getragen, welchen sie täglich an die Pforte des Tempels setzten, die man die schöne nennt, um Almosen zu erbitten von denen, die in den Tempel gingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Als dieser Petrus und Johannes sah, wie sie in den Tempel eintreten wollten, bat er, daß er ein Almosen empfinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Petrus aber blickte unverwandt mit Johannes auf ihn hin und sprach: Sieh uns an!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Er aber gab acht auf sie, in der Erwartung, etwas von ihnen zu empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Petrus aber sprach: Silber und Gold habe ich nicht; was ich aber habe, das gebe ich dir: In dem Namen Jesu Christi, des Nazaräers, stehe auf und wandle!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Und er ergriff ihn bei der rechten Hand und richtete ihn auf. Alsbald aber wurden seine Füße und seine Knöchel stark,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'und aufspringend stand er und wandelte; und er ging mit ihnen in den Tempel, wandelte und sprang und lobte Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Und das ganze Volk sah ihn wandeln und Gott loben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'und sie erkannten ihn, daß er der war, welcher um das Almosen an der schönen Pforte des Tempels gesessen; und sie wurden mit Verwunderung und Erstaunen erfüllt über das, was sich mit ihm ereignet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Während er aber den Petrus und Johannes festhielt, lief das ganze Volk voll Erstaunen zu ihnen zusammen in der Säulenhalle die Salomonshalle genannt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Als aber Petrus es sah, antwortete er dem Volke: Männer von Israel, was verwundert ihr euch hierüber, oder was sehet ihr unverwandt auf uns, als hätten wir aus eigener Kraft oder Frömmigkeit ihn wandeln gemacht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Der Gott Abrahams und Isaaks und Jakobs, der Gott unserer Väter, hat seinen Knecht Jesus verherrlicht, den ihr überliefert und angesichts des Pilatus verleugnet habt, als dieser geurteilt hatte, ihn loszugeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Ihr aber habt den Heiligen und Gerechten verleugnet und gebeten, daß euch ein Mann, der ein Mörder war, geschenkt würde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'den Urheber des Lebens aber habt ihr getötet, welchen Gott aus den Toten auferweckt hat, wovon wir Zeugen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Und durch Glauben an seinen Namen hat sein Name diesen, den ihr sehet und kennet, stark gemacht; und der Glaube, der durch ihn ist, hat ihm diese vollkommene Gesundheit gegeben vor euch allen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Und jetzt, Brüder, ich weiß, daß ihr in Unwissenheit gehandelt habt, gleichwie auch eure Obersten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Gott aber hat also erfüllt, was er durch den Mund aller Propheten zuvor verkündigt hat, daß sein Christus leiden sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'So tut nun Buße und bekehret euch, daß eure Sünden ausgetilgt werden, damit Zeiten der Erquickung kommen vom Angesicht des Herrn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'und er den euch zuvorverordneten Jesus Christus sende,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'welchen freilich der Himmel aufnehmen muß bis zu den Zeiten der Wiederherstellung aller Dinge, von welchen Gott durch den Mund seiner heiligen Propheten von jeher geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Moses hat schon gesagt: \"Einen Propheten wird euch der Herr, euer Gott, aus euren Brüdern erwecken, gleich mir; auf ihn sollt ihr hören in allem, was irgend er zu euch reden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Es wird aber geschehen, jede Seele, die irgend auf jenen Propheten nicht hören wird, soll aus dem Volke ausgerottet werden.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Aber auch alle Propheten, von Samuel an und der Reihe nach, so viele ihrer geredet haben, haben auch diese Tage verkündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Ihr seid die Söhne der Propheten und des Bundes, den Gott unseren Vätern verordnet hat, indem er zu Abraham sprach: \"Und in deinem Samen werden gesegnet werden alle Geschlechter der Erde\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Euch zuerst hat Gott, als er seinen Knecht erweckte, ihn gesandt, euch zu segnen, indem er einen jeden von euren Bosheiten abwendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Während sie aber zu dem Volke redeten, kamen die Priester und der Hauptmann des Tempels und die Sadducäer auf sie zu,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'welche es verdroß, daß sie das Volk lehrten und in Jesu die Auferstehung aus den Toten verkündigten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Und sie legten die Hände an sie und setzten sie in Gewahrsam bis an den Morgen, denn es war schon Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Viele aber von denen, welche das Wort gehört hatten, wurden gläubig; und es wurde die Zahl der Männer bei fünftausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Es geschah aber des folgenden Tages, daß ihre Obersten und Ältesten und Schriftgelehrten sich in Jerusalem versammelten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'und Annas, der Hohepriester, und Kajaphas und Johannes und Alexander, und so viele vom hohenpriesterlichen Geschlecht waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Und nachdem sie sie in die Mitte gestellt hatten, fragten sie: In welcher Kraft oder in welchem Namen habt ihr dies getan?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Da sprach Petrus, erfüllt mit Heiligem Geiste, zu ihnen: Oberste des Volkes und Älteste von Israel!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Wenn wir heute über die Wohltat an einem kranken Menschen verhört und gefragt werden, wodurch dieser geheilt worden ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'so sei euch allen und dem ganzen Volke Israel kund, daß in dem Namen Jesu Christi, des Nazaräers, welchen ihr gekreuzigt habt, den Gott auferweckt hat aus den Toten, daß durch ihn dieser gesund vor euch steht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Dieser ist der Stein, der von euch, den Bauleuten, für nichts geachtet, der zum Eckstein geworden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Und es ist in keinem anderen das Heil, denn auch kein anderer Name ist unter dem Himmel, der unter den Menschen gegeben ist, in welchem wir errettet werden müssen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Als sie aber die Freimütigkeit des Petrus und Johannes sahen und inne wurden, daß es ungelehrte und ungebildete Leute seien, verwunderten sie sich; und sie erkannten sie, daß sie mit Jesu gewesen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Und da sie den Menschen, der geheilt worden war, bei ihnen stehen sahen, hatten sie nichts dawider zu sagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Nachdem sie ihnen aber befohlen hatten, aus dem Synedrium zu gehen, überlegten sie miteinander und sagten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Was sollen wir diesen Menschen tun? Denn daß wirklich ein kundbares Zeichen durch sie geschehen ist, ist allen offenbar, die zu Jerusalem wohnen, und wir können es nicht leugnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Aber auf daß es nicht weiter unter dem Volke ausgebreitet werde, laßt uns sie ernstlich bedrohen, daß sie nicht mehr in diesem Namen zu irgend einem Menschen reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Und als sie sie gerufen hatten, geboten sie ihnen, sich durchaus nicht in dem Namen Jesu zu äußern noch zu lehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Petrus aber und Johannes antworteten und sprachen zu ihnen: Ob es vor Gott recht ist, auf euch mehr zu hören, als auf Gott, urteilet ihr;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'denn es ist uns unmöglich, von dem, was wir gesehen und gehört haben, nicht zu reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Sie aber bedrohten sie noch mehr und entließen sie, indem sie nicht fanden, auf welche Weise sie sie strafen sollten, um des Volkes willen; denn alle verherrlichten Gott über das, was geschehen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Denn der Mensch war mehr als vierzig Jahre alt, an welchem dieses Zeichen der Heilung geschehen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Als sie aber entlassen waren, kamen sie zu den Ihrigen und verkündeten alles, was die Hohenpriester und die Ältesten zu ihnen gesagt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Sie aber, als sie es hörten, erhoben einmütig ihre Stimme zu Gott und sprachen: Herrscher, du bist der Gott, der den Himmel und die Erde und das Meer gemacht hat und alles, was in ihnen ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'der du durch den Mund deines Knechtes David gesagt hast: \"Warum tobten die Nationen, und sannen Eitles die Völker?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Die Könige der Erde standen da, und die Obersten versammelten sich wider den Herrn und wider seinen Christus.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Denn in dieser Stadt versammelten sich in Wahrheit wider deinen heiligen Knecht Jesus, den du gesalbt hast, sowohl Herodes als Pontius Pilatus mit den Nationen und den Völkern Israels,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'alles zu tun, was deine Hand und dein Ratschluß zuvorbestimmt hat, daß es geschehen sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Und nun, Herr, sieh an ihre Drohungen und gib deinen Knechten, dein Wort zu reden mit aller Freimütigkeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'indem du deine Hand ausstreckst zur Heilung, und daß Zeichen und Wunder geschehen durch den Namen deines heiligen Knechtes Jesus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Und als sie gebetet hatten, bewegte sich die Stätte, wo sie versammelt waren; und sie wurden alle mit Heiligem Geiste erfüllt und redeten das Wort Gottes mit Freimütigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Die Menge derer aber, die gläubig geworden, war ein Herz und eine Seele; und auch nicht einer sagte, daß etwas von seiner Habe sein eigen wäre, sondern es war ihnen alles gemein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Und mit großer Kraft legten die Apostel das Zeugnis von der Auferstehung des Herrn Jesus ab; und große Gnade war auf ihnen allen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Denn es war auch keiner dürftig unter ihnen, denn so viele Besitzer von Äckern oder Häusern waren, verkauften sie und brachten den Preis des Verkauften');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'und legten ihn nieder zu den Füßen der Apostel; es wurde aber einem jeden ausgeteilt, so wie einer irgend Bedürfnis hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Joseph aber, der von den Aposteln Barnabas zubenamt wurde (was verdolmetscht heißt: Sohn des Trostes), ein Levit, ein Cyprier von Geburt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'der einen Acker besaß, verkaufte ihn, brachte das Geld und legte es nieder zu den Füßen der Apostel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Ein gewisser Mann aber, mit Namen Ananias, mit Sapphira, seinem Weibe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'verkaufte ein Gut und schaffte von dem Kaufpreis beiseite, wovon auch das Weib wußte; und er brachte einen gewissen Teil und legte ihn nieder zu den Füßen der Apostel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Petrus aber sprach: Ananias, warum hat der Satan dein Herz erfüllt, daß du den Heiligen Geist belogen und von dem Kaufpreis des Feldes beiseite geschafft hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Blieb es nicht dein, wenn es so blieb, und war es nicht, nachdem es verkauft war, in deiner Gewalt? Was ist es, daß du dir diese Tat in deinem Herzen vorgenommen hast? Nicht Menschen hast du belogen, sondern Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Als aber Ananias diese Worte hörte, fiel er hin und verschied. Und es kam große Furcht über alle, die es hörten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Die Jünglinge aber standen auf, rafften ihn zusammen und trugen ihn hinaus und begruben ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Es geschah aber nach Verlauf von etwa drei Stunden, daß sein Weib hereinkam, ohne zu wissen, was geschehen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Petrus aber antwortete ihr: Sage mir, ob ihr für so viel das Feld hingegeben habt? Sie aber sprach: Ja, für so viel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Petrus aber sprach zu ihr: Was ist es, daß ihr übereingekommen seid, den Geist des Herrn zu versuchen? Siehe, die Füße derer, welche deinen Mann begraben haben, sind an der Tür, und sie werden dich hinaustragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Sie fiel aber alsbald zu seinen Füßen nieder und verschied. Und als die Jünglinge hereinkamen, fanden sie sie tot; und sie trugen sie hinaus und begruben sie bei ihrem Manne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Und es kam große Furcht über die ganze Versammlung und über alle, welche dies hörten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Aber durch die Hände der Apostel geschahen viele Zeichen und Wunder unter dem Volke; (und sie waren alle einmütig in der Säulenhalle Salomons.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Von den übrigen aber wagte keiner, sich ihnen anzuschließen, sondern das Volk erhob sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Aber um so mehr Gläubige wurden dem Herrn hinzugetan, Scharen von Männern sowohl als Weibern;)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'so daß sie die Kranken auf die Straßen hinaustrugen und auf Betten und Lager legten, auf daß, wenn Petrus käme, auch nur sein Schatten einen von ihnen überschatten möchte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Es kam aber auch die Menge der umliegenden Städte nach Jerusalem zusammen, und sie brachten Kranke und von unreinen Geistern Geplagte, welche alle geheilt wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Der Hohepriester aber stand auf und alle, die mit ihm waren, das ist die Sekte der Sadducäer, und wurden von Eifersucht erfüllt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'und sie legten die Hände an die Apostel und setzten sie in öffentlichen Gewahrsam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Ein Engel des Herrn aber öffnete während der Nacht die Türen des Gefängnisses und führte sie hinaus und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Gehet und stellet euch hin und redet in dem Tempel zu dem Volke alle Worte dieses Lebens!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Als sie es aber gehört hatten, gingen sie frühmorgens in den Tempel und lehrten. Der Hohepriester aber kam und die mit ihm waren, und sie beriefen das Synedrium und die ganze Ältestenschaft der Söhne Israels zusammen und sandten nach dem Gefängnis, daß sie herbeigeführt würden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Als aber die Diener hinkamen, fanden sie sie nicht in dem Gefängnis; und sie kehrten zurück, berichteten und sagten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'Wir fanden das Gefängnis mit aller Sorgfalt verschlossen und die Wachen an den Türen stehen; als wir aber aufgemacht hatten, fanden wir niemand darin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Als aber sowohl der Priester und der Hauptmann des Tempels als auch die Hohenpriester diese Worte hörten, waren sie über sie in Verlegenheit, was dies doch werden möchte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Es kam aber einer und berichtete ihnen: Siehe, die Männer, die ihr ins Gefängnis gesetzt habt, sind im Tempel, stehen und lehren das Volk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Da ging der Hauptmann mit den Dienern hin und führte sie herbei, nicht mit Gewalt, denn sie fürchteten das Volk, sie möchten gesteinigt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Sie führten sie aber herbei und stellten sie vor das Synedrium; und der Hohepriester befragte sie und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'Wir haben euch streng geboten, in diesem Namen nicht zu lehren, und siehe, ihr habt Jerusalem erfüllt mit eurer Lehre und wollt das Blut dieses Menschen auf uns bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Petrus und die Apostel aber antworteten und sprachen: Man muß Gott mehr gehorchen als Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Der Gott unserer Väter hat Jesum auferweckt, den ihr ermordet habt, indem ihr ihn an ein Holz hängtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Diesen hat Gott durch seine Rechte zum Führer und Heiland erhöht, um Israel Buße und Vergebung der Sünden zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Und wir sind seine Zeugen von diesen Dingen, aber auch der Heilige Geist, welchen Gott denen gegeben hat, die ihm gehorchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Sie aber wurden, als sie es hörten, durchbohrt und ratschlagten, sie umzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Es stand aber einer in dem Synedrium auf, ein Pharisäer, mit Namen Gamaliel, ein Gesetzgelehrter, angesehen bei dem ganzen Volke, und befahl, die Leute eine kurze Zeit hinauszutun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'Und er sprach zu ihnen: Männer von Israel, sehet euch vor betreffs dieser Menschen, was ihr tun wollt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Denn vor diesen Tagen stand Theudas auf und sagte, daß er selbst etwas sei, welchem eine Anzahl von etwa vierhundert Männern anhing; der ist getötet worden, und alle, so viele ihm Gehör gaben, sind zerstreut und zunichte geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Nach diesem stand Judas der Galiläer auf, in den Tagen der Einschreibung, und machte Volk abfällig sich nach; auch der kam um, und alle, so viele ihm Gehör gaben, wurden zerstreut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Und jetzt sage ich euch: Stehet ab von diesen Menschen und lasset sie (denn wenn dieser Rat oder dieses Werk aus Menschen ist, so wird es zu Grunde gehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'wenn es aber aus Gott ist, so werdet ihr sie nicht zu Grunde richten können), damit ihr nicht gar als solche erfunden werdet, die wider Gott streiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Und sie gaben ihm Gehör; und als sie die Apostel herbeigerufen hatten, schlugen sie sie und geboten ihnen, nicht in dem Namen Jesu zu reden, und entließen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Sie nun gingen aus dem Synedrium hinweg, voll Freude, daß sie gewürdigt worden waren, für den Namen Schmach zu leiden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'und jeden Tag, in dem Tempel und in den Häusern, hörten sie nicht auf, zu lehren und Jesum als den Christus zu verkündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'In diesen Tagen aber, als die Jünger sich vermehrten, entstand ein Murren der Hellenisten gegen die Hebräer, weil ihre Witwen bei der täglichen Bedienung übersehen wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Die Zwölfe aber beriefen die Menge der Jünger und sprachen: Es ist nicht gut, daß wir das Wort Gottes verlassen und die Tische bedienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'So sehet euch nun um, Brüder, nach sieben Männern aus euch, von gutem Zeugnis, voll Heiligen Geistes und Weisheit, die wir über dieses Geschäft bestellen wollen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'wir aber werden im Gebet und im Dienst des Wortes verharren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Und die Rede gefiel der ganzen Menge; und sie erwählten Stephanus, einen Mann voll Glaubens und Heiligen Geistes, und Philippus und Prochorus und Nikanor und Timon und Parmenas und Nikolaus, einen Proselyten aus Antiochien,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'welche sie vor die Apostel stellten; und als sie gebetet hatten, legten sie ihnen die Hände auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Und das Wort Gottes wuchs, und die Zahl der Jünger in Jerusalem vermehrte sich sehr; und eine große Menge der Priester wurde dem Glauben gehorsam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Stephanus aber, voll Gnade und Kraft, tat Wunder und große Zeichen unter dem Volke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Es standen aber etliche auf von der sogenannten Synagoge der Libertiner und der Kyrenäer und der Alexandriner und derer von Cilicien und Asien und stritten mit Stephanus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Und sie vermochten nicht der Weisheit und dem Geiste zu widerstehen, womit er redete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Da schoben sie heimlich Männer vor, welche sagten: Wir haben ihn Lästerworte reden hören wider Moses und Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Und sie erregten das Volk und die Ältesten und die Schriftgelehrten; und sie fielen über ihn her und rissen ihn mit sich fort und führten ihn vor das Synedrium.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Und sie stellten falsche Zeugen auf, welche sagten: Dieser Mensch hört nicht auf, Worte zu reden wider die heilige Stätte und das Gesetz;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'denn wir haben ihn sagen hören: Dieser Jesus, der Nazaräer, wird diese Stätte zerstören und die Gebräuche verändern, die uns Moses überliefert hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Und alle, die in dem Synedrium saßen, schauten unverwandt auf ihn und sahen sein Angesicht wie eines Engels Angesicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Der Hohepriester aber sprach: Ist denn dieses also? Er aber sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Brüder und Väter, höret! Der Gott der Herrlichkeit erschien unserem Vater Abraham, als er in Mesopotamien war, ehe er in Haran wohnte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'und sprach zu ihm: \"Geh aus deinem Lande und aus deiner Verwandtschaft, und komm in das Land, das ich dir zeigen werde\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Da ging er aus dem Lande der Chaldäer und wohnte in Haran; und von da übersiedelte er ihn, nachdem sein Vater gestorben war, in dieses Land, in welchem ihr jetzt wohnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Und er gab ihm kein Erbe darin, auch nicht einen Fußbreit; und er verhieß, es ihm zum Besitztum zu geben und seinem Samen nach ihm, als er kein Kind hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Gott aber sprach also: \"Sein Same wird ein Fremdling sein in fremdem Lande, und man wird ihn knechten und mißhandeln vierhundert Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Und die Nation, welcher sie dienen werden, werde ich richten\", sprach Gott, \"und danach werden sie ausziehen und mir dienen an diesem Orte\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Und er gab ihm den Bund der Beschneidung; und also zeugte er den Isaak und beschnitt ihn am achten Tage, und Isaak den Jakob, und Jakob die zwölf Patriarchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Und die Patriarchen, neidisch auf Joseph, verkauften ihn nach Ägypten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'Und Gott war mit ihm und rettete ihn aus allen seinen Drangsalen und gab ihm Gunst und Weisheit vor Pharao, dem König von Ägypten; und er setzte ihn zum Verwalter über Ägypten und sein ganzes Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Es kam aber eine Hungersnot über das ganze Land Ägypten und Kanaan und eine große Drangsal, und unsere Väter fanden keine Speise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Als aber Jakob hörte, daß in Ägypten Getreide sei, sandte er unsere Väter zum ersten Male aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Und beim zweiten Male wurde Joseph von seinen Brüdern wiedererkannt, und dem Pharao wurde das Geschlecht Josephs offenbar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Joseph aber sandte hin und ließ seinen Vater Jakob holen und die ganze Verwandtschaft, an fünfundsiebzig Seelen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Jakob aber zog hinab nach Ägypten und starb, er und unsere Väter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'und sie wurden nach Sichem hinübergebracht und in die Grabstätte gelegt, welche Abraham für eine Summe Geldes von den Söhnen Hemors, des Vaters Sichems, kaufte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Als aber die Zeit der Verheißung nahte, welche Gott dem Abraham zugesagt hatte, wuchs das Volk und vermehrte sich in Ägypten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'bis ein anderer König über Ägypten aufstand, der Joseph nicht kannte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Dieser handelte mit List gegen unser Geschlecht und mißhandelte die Väter, so daß sie ihre Kindlein aussetzen mußten, damit sie nicht am Leben blieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'In dieser Zeit wurde Moses geboren, und er war ausnehmend schön; und er wurde drei Monate aufgezogen in dem Hause des Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Als er aber ausgesetzt worden war, nahm ihn die Tochter Pharaos zu sich und zog ihn auf, sich zum Sohne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Und Moses wurde unterwiesen in aller Weisheit der Ägypter; er war aber mächtig in seinen Worten und Werken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Als er aber ein Alter von vierzig Jahren erreicht hatte, kam es in seinem Herzen auf, nach seinen Brüdern, den Söhnen Israels, zu sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Und als er einen Unrecht leiden sah, verteidigte er ihn und rächte den Unterdrückten, indem er den Ägypter erschlug.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Er meinte aber, seine Brüder würden verstehen, daß Gott durch seine Hand ihnen Rettung gebe; sie aber verstanden es nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Und am folgenden Tage zeigte er sich ihnen, als sie sich stritten, und trieb sie zum Frieden, indem er sagte: Ihr seid Brüder, warum tut ihr einander unrecht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Der aber dem Nächsten unrecht tat, stieß ihn weg und sprach: Wer hat dich zum Obersten und Richter über uns gesetzt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Willst du mich etwa umbringen, wie du gestern den Ägypter umgebracht hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Moses aber entfloh bei diesem Worte und wurde Fremdling im Lande Midian, wo er zwei Söhne zeugte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Und als vierzig Jahre verflossen waren, erschien ihm in der Wüste des Berges Sinai ein Engel in einer Feuerflamme eines Dornbusches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Als aber Moses es sah, verwunderte er sich über das Gesicht; während er aber hinzutrat, es zu betrachten, geschah eine Stimme des Herrn:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, '\"Ich bin der Gott deiner Väter, der Gott Abrahams und Isaaks und Jakobs\". Moses aber erzitterte und wagte nicht, es zu betrachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Der Herr aber sprach zu ihm: \"Löse die Sandale von deinen Füßen, denn der Ort, auf dem du stehst, ist heiliges Land.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Gesehen habe ich die Mißhandlung meines Volkes, das in Ägypten ist, und ihr Seufzen habe ich gehört, und ich bin herniedergekommen, sie herauszureißen. Und nun komm, ich will dich nach Ägypten senden.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Diesen Moses, den sie verleugneten, indem sie sagten: \"Wer hat dich zum Obersten und Richter gesetzt?\" diesen hat Gott zum Obersten und Retter gesandt mit der Hand des Engels, der ihm in dem Dornbusch erschien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Dieser führte sie heraus, indem er Wunder und Zeichen tat im Lande Ägypten und im Roten Meere und in der Wüste, vierzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Dieser ist der Moses, der zu den Söhnen Israels sprach: \"Einen Propheten wird euch Gott aus euren Brüdern erwecken, gleich mir; ihn sollt ihr hören \".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Dieser ist es, der in der Versammlung in der Wüste mit dem Engel, welcher auf dem Berge Sinai zu ihm redete, und mit unseren Vätern gewesen ist; der lebendige Aussprüche empfing, um sie uns zu geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'welchem unsere Väter nicht gehorsam sein wollten, sondern stießen ihn von sich und wandten sich in ihren Herzen nach Ägypten zurück,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'indem sie zu Aaron sagten: \"Mache uns Götter, die vor uns herziehen sollen; denn dieser Moses, der uns aus dem Lande Ägypten geführt hat, wir wissen nicht, was ihm geschehen ist\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Und sie machten ein Kalb in jenen Tagen und brachten dem Götzenbilde ein Schlachtopfer und ergötzten sich an den Werken ihrer Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Gott aber wandte sich ab und gab sie dahin, dem Heere des Himmels zu dienen, wie geschrieben steht im Buche der Propheten: \"Habt ihr etwa mir vierzig Jahre in der Wüste Opfertiere und Schlachtopfer dargebracht, Haus Israel?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Ja, ihr nahmet die Hütte des Moloch auf und das Gestirn eures Gottes Remphan, die Bilder, welche ihr gemacht hattet, sie anzubeten; und ich werde euch verpflanzen über Babylon hinaus\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Unsere Väter hatten die Hütte des Zeugnisses in der Wüste, wie der, welcher zu Moses redete, befahl, sie nach dem Muster zu machen, das er gesehen hatte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'welche auch unsere Väter überkamen und mit Josua einführten bei der Besitzergreifung des Landes der Nationen, welche Gott austrieb von dem Angesicht unserer Väter hinweg, bis zu den Tagen Davids,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'welcher Gnade fand vor Gott und eine Wohnstätte zu finden begehrte für den Gott Jakobs.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Salomon aber baute ihm ein Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Aber der Höchste wohnt nicht in Wohnungen, die mit Händen gemacht sind, wie der Prophet spricht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '\"Der Himmel ist mein Thron, und die Erde der Schemel meiner Füße. Was für ein Haus wollt ihr mir bauen, spricht der Herr, oder welches ist der Ort meiner Ruhe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Hat nicht meine Hand dies alles gemacht?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Ihr Halsstarrigen und Unbeschnittenen an Herz und Ohren! Ihr widerstreitet allezeit dem Heiligen Geiste; wie eure Väter, so auch ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Welchen der Propheten haben eure Väter nicht verfolgt? Und sie haben die getötet, welche die Ankunft des Gerechten zuvor verkündigten, dessen Verräter und Mörder ihr jetzt geworden seid,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'die ihr das Gesetz durch Anordnung von Engeln empfangen und nicht beobachtet habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Als sie aber dies hörten, wurden ihre Herzen durchbohrt, und sie knirschten mit den Zähnen gegen ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Als er aber, voll Heiligen Geistes, unverwandt gen Himmel schaute, sah er die Herrlichkeit Gottes, und Jesum zur Rechten Gottes stehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'und er sprach: Siehe, ich sehe die Himmel geöffnet, und den Sohn des Menschen zur Rechten Gottes stehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Sie schrieen aber mit lauter Stimme, hielten ihre Ohren zu und stürzten einmütig auf ihn los.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'Und als sie ihn aus der Stadt hinausgestoßen hatten, steinigten sie ihn. Und die Zeugen legten ihre Kleider ab zu den Füßen eines Jünglings, genannt Saulus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Und sie steinigten den Stephanus, welcher betete und sprach: Herr Jesus, nimm meinen Geist auf!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Und niederkniend rief er mit lauter Stimme: Herr, rechne ihnen diese Sünde nicht zu! Und als er dies gesagt hatte, entschlief er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Saulus aber willigte in seine Tötung mit ein. Es entstand aber an jenem Tage eine große Verfolgung wider die Versammlung, die in Jerusalem war; und alle wurden in die Landschaften von Judäa und Samaria zerstreut, ausgenommen die Apostel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Gottesfürchtige Männer aber bestatteten den Stephanus und stellten eine große Klage über ihn an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Saulus aber verwüstete die Versammlung, indem er der Reihe nach in die Häuser ging; und er schleppte sowohl Männer als Weiber fort und überlieferte sie ins Gefängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Die Zerstreuten nun gingen umher und verkündigten das Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Philippus aber ging hinab in eine Stadt Samarias und predigte ihnen den Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Und die Volksmengen achteten einmütig auf das, was von Philippus geredet wurde, indem sie zuhörten und die Zeichen sahen, die er tat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Denn von vielen, welche unreine Geister hatten, fuhren sie aus, mit lauter Stimme schreiend; und viele Gelähmte und Lahme wurden geheilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Und es war eine große Freude in jener Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Ein gewisser Mann aber, mit Namen Simon, befand sich vorher in der Stadt, der Zauberei trieb und das Volk von Samaria außer sich brachte, indem er von sich selbst sagte, daß er etwas Großes sei;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'welchem alle, vom Kleinen bis zum Großen, anhingen, indem sie sagten: Dieser ist die Kraft Gottes, die man die große nennt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Sie hingen ihm aber an, weil er sie lange Zeit mit den Zaubereien außer sich gebracht hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Als sie aber dem Philippus glaubten, der das Evangelium von dem Reiche Gottes und dem Namen Jesu Christi verkündigte, wurden sie getauft, sowohl Männer als Weiber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Aber auch Simon selbst glaubte, und als er getauft war, hielt er sich zu Philippus; und als er die Zeichen und großen Wunder sah, welche geschahen, geriet er außer sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Als aber die Apostel, welche in Jerusalem waren, gehört hatten, daß Samaria das Wort Gottes angenommen habe, sandten sie Petrus und Johannes zu ihnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'welche, als sie hinabgekommen waren, für die beteten, damit sie den Heiligen Geist empfangen möchten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'denn er war noch nicht auf einen von ihnen gefallen, sondern sie waren allein getauft auf den Namen des Herrn Jesus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Dann legten sie ihnen die Hände auf, und sie empfingen den Heiligen Geist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Als aber Simon sah, daß durch das Auflegen der Hände der Apostel der Heilige Geist gegeben wurde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'bot er ihnen Geld an und sagte: Gebet auch mir diese Gewalt, auf daß, wem irgend ich die Hände auflege, er den Heiligen Geist empfange.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Petrus aber sprach zu ihm: Dein Geld fahre samt dir ins Verderben, weil du gemeint hast, daß die Gabe Gottes durch Geld zu erlangen sei!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Du hast weder Teil noch Los an dieser Sache, denn dein Herz ist nicht aufrichtig vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Tue nun Buße über diese deine Bosheit und bitte den Herrn, ob dir etwa der Anschlag deines Herzens vergeben werde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'denn ich sehe, daß du in Galle der Bitterkeit und in Banden der Ungerechtigkeit bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Simon aber antwortete und sprach: Bittet ihr für mich den Herrn, damit nichts über mich komme von dem, was ihr gesagt habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Nachdem sie nun das Wort des Herrn bezeugt und geredet hatten, kehrten sie nach Jerusalem zurück und verkündigten das Evangelium vielen Dörfern der Samariter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Ein Engel des Herrn aber redete zu Philippus und sprach: Stehe auf und geh gegen Süden auf den Weg, der von Jerusalem nach Gaza hinabführt; derselbe ist öde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Und er stand auf und ging hin. Und siehe ein Äthiopier, ein Kämmerer, ein Gewaltiger der Kandace, der Königin der Äthiopier, der über ihren ganzen Schatz gesetzt war, war gekommen, um zu Jerusalem anzubeten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'und er war auf der Rückkehr und saß auf seinem Wagen und las den Propheten Jesaias.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Der Geist aber sprach zu Philippus: Tritt hinzu und schließe dich diesem Wagen an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Philippus aber lief hinzu und hörte ihn den Propheten Jesaias lesen und sprach: Verstehst du auch, was du liesest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Er aber sprach: Wie könnte ich denn, wenn nicht jemand mich anleitet? Und er bat den Philippus, daß er aufsteige und sich zu ihm setze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Die Stelle der Schrift aber, welche er las, war diese: \"Er wurde wie ein Schaf zur Schlachtung geführt, und wie ein Lamm stumm ist vor seinem Scherer, also tut er seinen Mund nicht auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'In seiner Erniedrigung wurde sein Gericht weggenommen; wer aber wird sein Geschlecht beschreiben? Denn sein Leben wird von der Erde weggenommen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Der Kämmerer aber antwortete dem Philippus und sprach: Ich bitte dich, von wem sagt der Prophet dieses? Von sich selbst oder von einem anderen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Philippus aber tat seinen Mund auf, und, anfangend von dieser Schrift, verkündigte er ihm das Evangelium von Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Als sie aber auf dem Wege fortzogen, kamen sie an ein gewisses Wasser. Und der Kämmerer spricht: Siehe, da ist Wasser; was hindert mich, getauft zu werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, '(Dieser Vers gehört nicht zum ursprünglichen Text der Apostelgeschichte).');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Und er hieß den Wagen halten. Und sie stiegen beide in das Wasser hinab, sowohl Philippus als der Kämmerer; und er taufte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Als sie aber aus dem Wasser heraufstiegen, entrückte der Geist des Herrn den Philippus; und der Kämmerer sah ihn nicht mehr, denn er zog seinen Weg mit Freuden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Philippus aber wurde zu Asdod gefunden; und indem er hindurchzog, verkündigte er das Evangelium allen Städten, bis er nach Cäsarea kam.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Saulus aber, noch Drohung und Mord wider die Jünger des Herrn schnaubend, ging zu dem Hohenpriester');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'und erbat sich von ihm Briefe nach Damaskus an die Synagogen, damit, wenn er etliche, die des Weges wären, fände, sowohl Männer als Weiber, er sie gebunden nach Jerusalem führe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Als er aber hinzog, geschah es, daß er Damaskus nahte. Und plötzlich umstrahlte ihn ein Licht aus dem Himmel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'und auf die Erde fallend, hörte er eine Stimme, die zu ihm sprach: Saul, Saul, was verfolgst du mich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Er aber sprach: Wer bist du, Herr? Er aber sprach: Ich bin Jesus, den du verfolgst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Stehe aber auf und geh in die Stadt, und es wird dir gesagt werden, was du tun sollst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Die Männer aber, die mit ihm des Weges zogen, standen sprachlos, da sie wohl die Stimme hörten, aber niemand sahen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Saulus aber richtete sich von der Erde auf. Als aber seine Augen aufgetan waren, sah er niemand. Und sie leiteten ihn bei der Hand und führten ihn nach Damaskus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Und er war drei Tage nicht sehend und aß nicht und trank nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Es war aber ein gewisser Jünger in Damaskus, mit Namen Ananias; und der Herr sprach zu ihm in einem Gesicht: Ananias! Er aber sprach: Siehe, hier bin ich, Herr!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Der Herr aber sprach zu ihm: Stehe auf und geh in die Straße, welche die gerade genannt wird, und frage im Hause des Judas nach einem, mit Namen Saulus, von Tarsus, denn siehe, er betet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'und er hat im Gesicht einen Mann, mit Namen Ananias, gesehen, der hereinkam und ihm die Hände auflegte, damit er wieder sehend werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Ananias aber antwortete: Herr, ich habe von vielen von diesem Manne gehört, wie viel Böses er deinen Heiligen in Jerusalem getan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Und hier hat er Gewalt von den Hohenpriestern, alle zu binden, die deinen Namen anrufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Der Herr aber sprach zu ihm: Gehe hin; denn dieser ist mir ein auserwähltes Gefäß, meinen Namen zu tragen sowohl vor Nationen als Könige und Söhne Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Denn ich werde ihm zeigen, wie vieles er für meinen Namen leiden muß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Ananias aber ging hin und kam in das Haus; und ihm die Hände auflegend, sprach er: Bruder Saul, der Herr hat mich gesandt, Jesus, der dir erschienen ist auf dem Wege, den du kamst, damit du wieder sehend und mit Heiligem Geiste erfüllt werdest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Und alsbald fiel es wie Schuppen von seinen Augen, und er wurde sehend und stand auf und wurde getauft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'Und nachdem er Speise genommen hatte, wurde er gestärkt. Er war aber etliche Tage bei den Jüngern, die in Damaskus waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'Und alsbald predigte er in den Synagogen Jesum, daß dieser der Sohn Gottes ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Alle aber, die es hörten, gerieten außer sich und sagten: Ist dieser nicht der, welcher in Jerusalem die zerstörte, welche diesen Namen anrufen, und dazu hierhergekommen war, auf daß er sie gebunden zu den Hohenpriestern führe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Saulus aber erstarkte um so mehr und brachte die Juden, die in Damaskus wohnten, in Verwirrung, indem er bewies, daß dieser der Christus ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Als aber viele Tage verflossen waren, ratschlagten die Juden miteinander, ihn umzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Es wurde aber dem Saulus ihr Anschlag bekannt. Und sie bewachten auch die Tore sowohl bei Tage als bei Nacht, damit sie ihn umbrächten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Die Jünger aber nahmen ihn bei der Nacht und ließen ihn durch die Mauer hinab, indem sie ihn in einem Korbe hinunterließen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Als er aber nach Jerusalem gekommen war, versuchte er, sich den Jüngern anzuschließen; und alle fürchteten sich vor ihm, da sie nicht glaubten, daß er ein Jünger sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Barnabas aber nahm ihn und brachte ihn zu den Aposteln und erzählte ihnen, wie er auf dem Wege den Herrn gesehen habe, und daß derselbe zu ihm geredet, und wie er in Damaskus freimütig im Namen Jesu gesprochen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Und er ging mit ihnen aus und ein in Jerusalem und sprach freimütig im Namen des Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Und er redete und stritt mit den Hellenisten; sie aber trachteten, ihn umzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Als die Brüder es aber erfuhren, brachten sie ihn nach Cäsarea hinab und sandten ihn hinweg nach Tarsus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'So hatten denn die Versammlungen durch ganz Judäa und Galiläa und Samaria hin Frieden und wurden erbaut und wandelten in der Furcht des Herrn und wurden vermehrt durch den Trost des Heiligen Geistes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Es geschah aber, daß Petrus, indem er allenthalben hindurchzog, auch zu den Heiligen hinabkam, die zu Lydda wohnten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Er fand aber daselbst einen gewissen Menschen, mit Namen Äneas, der seit acht Jahren zu Bett lag, welcher gelähmt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Und Petrus sprach zu ihm: Äneas! Jesus, der Christus, heilt dich; stehe auf und bette dir selbst! Und alsbald stand er auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Und es sahen ihn alle, die zu Lydda und Saron wohnten, welche sich zum Herrn bekehrten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'In Joppe aber war eine gewisse Jüngerin, mit Namen Tabitha, was verdolmetscht heißt: Dorkas; diese war voll guter Werke und Almosen, die sie übte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Es geschah aber in jenen Tagen, daß sie krank wurde und starb. Und als sie sie gewaschen hatten, legten sie sie auf den Obersaal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Da aber Lydda nahe bei Joppe war, sandten die Jünger, als sie gehört hatten, daß Petrus daselbst sei, zwei Männer zu ihm und baten: Zögere nicht, zu uns zu kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Petrus aber stand auf und ging mit ihnen; und als er angekommen war, führten sie ihn auf den Obersaal. Und alle Witwen traten weinend zu ihm und zeigten ihm die Leibröcke und Kleider, welche die Dorkas gemacht hatte, während sie bei ihnen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Petrus aber trieb alle hinaus, kniete nieder und betete. Und er wandte sich zu dem Leichnam und sprach: Tabitha, stehe auf! Sie aber schlug ihre Augen auf, und als sie den Petrus sah, setzte sie sich auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Er aber gab ihr die Hand und richtete sie auf; er rief aber die Heiligen und die Witwen und stellte sie lebend dar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Es wurde aber durch ganz Joppe hin kund, und viele glaubten an den Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Es geschah aber, daß er viele Tage in Joppe blieb, bei einem gewissen Simon, einem Gerber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Ein gewisser Mann aber in Cäsarea, mit Namen Kornelius, ein Hauptmann von der sogenannten italischen Schar,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'fromm und gottesfürchtig mit seinem ganzen Hause, der dem Volke viele Almosen gab und allezeit zu Gott betete-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'sah in einem Gesicht ungefähr um die neunte Stunde des Tages offenbarlich, wie ein Engel Gottes zu ihm hereinkam und zu ihm sagte: Kornelius!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Er aber sah ihn unverwandt an und wurde von Furcht erfüllt und sagte: Was ist, Herr? Er sprach aber zu ihm: Deine Gebete und deine Almosen sind hinaufgestiegen zum Gedächtnis vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Und jetzt sende Männer nach Joppe und laß Simon holen, der Petrus zubenannt ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'dieser herbergt bei einem gewissen Simon, einem Gerber, dessen Haus am Meere ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Als aber der Engel, der mit ihm redete, weggegangen war, rief er zwei seiner Hausknechte und einen frommen Kriegsknecht von denen, die beständig bei ihm waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'und als er ihnen alles erzählt hatte, sandte er sie nach Joppe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Des folgenden Tages aber, während jene reisten und sich der Stadt näherten, stieg Petrus um die sechste Stunde auf das Dach, um zu beten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Er wurde aber hungrig und verlangte zu essen. Während sie ihm aber zubereiteten, kam eine Entzückung über ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Und er sieht den Himmel geöffnet und ein gewisses Gefäß, gleich einem großen leinenen Tuche, herabkommen, an vier Zipfeln gebunden und auf die Erde herniedergelassen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'in welchem allerlei vierfüßige und kriechende Tiere der Erde waren und das Gevögel des Himmels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Und eine Stimme geschah zu ihm: Stehe auf, Petrus, schlachte und iß!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Petrus aber sprach: Keineswegs, Herr! Denn niemals habe ich irgend etwas Gemeines oder Unreines gegessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Und wiederum geschah eine Stimme zum zweiten Male zu ihm: Was Gott gereinigt hat, mache du nicht gemein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Dieses aber geschah dreimal; und das Gefäß wurde alsbald hinaufgenommen in den Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Als aber Petrus bei sich selbst in Verlegenheit war, was doch das Gesicht sein möchte, das er gesehen hatte, siehe, da standen die Männer, welche von Kornelius gesandt waren und Simons Haus erfragt hatten, vor dem Tore;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'und als sie gerufen hatten, fragten sie, ob Simon, der Petrus zubenamt sei, daselbst herberge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Während aber Petrus über das Gesicht nachsann, sprach der Geist zu ihm: Siehe, drei Männer suchen dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Stehe aber auf, geh hinab und ziehe mit ihnen, ohne irgend zu zweifeln, weil ich sie gesandt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Petrus aber ging zu den Männern hinab und sprach: Siehe, ich bin\'s, den ihr suchet. Was ist die Ursache, weshalb ihr kommet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Sie aber sprachen: Kornelius, ein Hauptmann, ein gerechter und gottesfürchtiger Mann, und der ein gutes Zeugnis hat von der ganzen Nation der Juden, ist von einem heiligen Engel göttlich gewiesen worden, dich in sein Haus holen zu lassen und Worte von dir zu hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Als er sie nun hereingerufen hatte, beherbergte er sie. Des folgenden Tages aber machte er sich auf und zog mit ihnen fort, und etliche der Brüder von Joppe gingen mit ihm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'und des folgenden Tages kamen sie nach Cäsarea. Kornelius aber, der seine Verwandten und nächsten Freunde zusammengerufen hatte, erwartete sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Als es aber geschah, daß Petrus hereinkam, ging Kornelius ihm entgegen, fiel ihm zu Füßen und huldigte ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Petrus aber richtete ihn auf und sprach: Stehe auf! Auch ich selbst bin ein Mensch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Und sich mit ihm unterredend, ging er hinein und findet viele versammelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Und er sprach zu ihnen: Ihr wisset, wie unerlaubt es für einen jüdischen Mann ist, sich einem Fremdling anzuschließen oder zu ihm zu kommen; und mir hat Gott gezeigt, keinen Menschen gemein oder unrein zu heißen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Darum kam ich auch ohne Widerrede, als ich geholt wurde. Ich frage nun: Aus welchem Grunde habt ihr mich holen lassen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Und Kornelius sprach: Vor vier Tagen fastete ich bis zu dieser Stunde, und um die neunte betete ich in meinem Hause; und siehe, ein Mann stand vor mir in glänzendem Kleide');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'und spricht: Kornelius! Dein Gebet ist erhört, und deiner Almosen ist gedacht worden vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Sende nun nach Joppe und laß Simon holen, der Petrus zubenamt ist; dieser herbergt in dem Hause Simons, eines Gerbers, am Meere; der wird, wenn er hierhergekommen ist, zu dir reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Sofort nun sandte ich zu dir, und du hast wohlgetan, daß du gekommen bist. Jetzt sind wir nun alle vor Gott gegenwärtig, um alles zu hören, was dir von Gott befohlen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Petrus aber tat den Mund auf und sprach: In Wahrheit begreife ich, daß Gott die Person nicht ansieht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'sondern in jeder Nation, wer ihn fürchtet und Gerechtigkeit wirkt, ist ihm angenehm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Das Wort, welches er den Söhnen Israels gesandt hat, Frieden verkündigend durch Jesum Christum, dieser ist aller Herr');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'kennet ihr: das Zeugnis, welches, anfangend von Galiläa, durch ganz Judäa hin ausgebreitet worden ist, nach der Taufe, die Johannes predigte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Jesum, den von Nazareth, wie Gott ihn mit Heiligem Geiste und mit Kraft gesalbt hat, der umherging, wohltuend und heilend alle, die von dem Teufel überwältigt waren; denn Gott war mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Und wir sind Zeugen alles dessen, was er sowohl im Lande der Juden als auch in Jerusalem getan hat; welchen sie auch umgebracht haben, indem sie ihn an ein Holz hängten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Diesen hat Gott am dritten Tage auferweckt und ihn sichtbar werden lassen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'nicht dem ganzen Volke, sondern den von Gott zuvor erwählten Zeugen, uns, die wir mit ihm gegessen und getrunken haben, nachdem er aus den Toten auferstanden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Und er hat uns befohlen, dem Volke zu predigen und ernstlich zu bezeugen, daß er der von Gott verordnete Richter der Lebendigen und der Toten ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Diesem geben alle Propheten Zeugnis, daß jeder, der an ihn glaubt, Vergebung der Sünden empfängt durch seinen Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Während Petrus noch diese Worte redete, fiel der Heilige Geist auf alle, die das Wort hörten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Und die Gläubigen aus der Beschneidung, so viele ihrer mit Petrus gekommen waren, gerieten außer sich, daß auch auf die Nationen die Gabe des Heiligen Geistes ausgegossen worden war;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'denn sie hörten sie in Sprachen reden und Gott erheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Dann antwortete Petrus: Könnte wohl jemand das Wasser verwehren, daß diese nicht getauft würden, die den Heiligen Geist empfangen haben, gleichwie auch wir?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Und er befahl, daß sie getauft würden in dem Namen des Herrn. Dann baten sie ihn, etliche Tage zu bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Die Apostel aber und die Brüder, die in Judäa waren, hörten, daß auch die Nationen das Wort Gottes angenommen hätten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'und als Petrus nach Jerusalem hinaufkam, stritten die aus der Beschneidung mit ihm');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'und sagten: Du bist zu Männern eingekehrt, die Vorhaut haben, und hast mit ihnen gegessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Petrus aber fing an und setzte es ihnen der Reihe nach auseinander und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Ich war in der Stadt Joppe im Gebet, und ich sah in einer Entzückung ein Gesicht, wie ein gewisses Gefäß herabkam, gleich einem großen leinenen Tuche, an vier Zipfeln herniedergelassen aus dem Himmel; und es kam bis zu mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Und als ich es unverwandt anschaute, bemerkte und sah ich die vierfüßigen Tiere der Erde und die wilden Tiere und die kriechenden und das Gevögel des Himmels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Ich hörte aber auch eine Stimme, die zu mir sagte: Stehe auf, Petrus, schlachte und iß!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Ich sprach aber: Keineswegs, Herr! Denn niemals ist Gemeines oder Unreines in meinen Mund gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Eine Stimme aber antwortete zum zweiten Male aus dem Himmel: Was Gott gereinigt hat, mache du nicht gemein!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Dies aber geschah dreimal; und alles wurde wiederum hinaufgezogen in den Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Und siehe, alsbald standen vor dem Hause, in welchem ich war, drei Männer, die von Cäsarea zu mir gesandt waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Der Geist aber hieß mich mit ihnen gehen, ohne irgend zu zweifeln. Es kamen aber auch diese sechs Brüder mit mir, und wir kehrten in das Haus des Mannes ein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Und er erzählte uns, wie er den Engel gesehen habe in seinem Hause stehen und zu ihm sagen: Sende nach Joppe und laß Simon holen, der Petrus zubenamt ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'der wird Worte zu dir reden, durch welche du errettet werden wirst, du und dein ganzes Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Indem ich aber zu reden begann, fiel der Heilige Geist auf sie, so wie auch auf uns im Anfang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Ich gedachte aber an das Wort des Herrn, wie er sagte: Johannes taufte zwar mit Wasser, ihr aber werdet mit Heiligem Geiste getauft werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Wenn nun Gott ihnen die gleiche Gabe gegeben hat wie auch uns, die wir an den Herrn Jesus Christus geglaubt haben, wer war ich, daß ich vermocht hätte, Gott zu wehren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Als sie aber dies gehört hatten, beruhigten sie sich und verherrlichten Gott und sagten: Dann hat Gott also auch den Nationen die Buße gegeben zum Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Die nun zerstreut waren durch die Drangsal, welche wegen Stephanus entstanden war, zogen hindurch bis nach Phönicien und Cypern und Antiochien und redeten zu niemand das Wort, als allein zu Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Es waren aber unter ihnen etliche Männer von Cypern und Kyrene, welche, als sie nach Antiochien kamen, auch zu den Griechen redeten, indem sie das Evangelium von dem Herrn Jesus verkündigten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Und des Herrn Hand war mit ihnen, und eine große Zahl glaubte und bekehrte sich zu dem Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Es kam aber die Rede von ihnen zu den Ohren der Versammlung, die in Jerusalem war, und sie sandten Barnabas aus, daß er hindurchzöge bis nach Antiochien;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'welcher, als er hingekommen war und die Gnade Gottes sah, sich freute und alle ermahnte, mit Herzensentschluß bei dem Herrn zu verharren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Denn er war ein guter Mann und voll Heiligen Geistes und Glaubens; und eine zahlreiche Menge wurde dem Herrn hinzugetan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Er zog aber aus nach Tarsus, um Saulus aufzusuchen; und als er ihn gefunden hatte, brachte er ihn nach Antiochien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Es geschah ihnen aber, daß sie ein ganzes Jahr in der Versammlung zusammenkamen und eine zahlreiche Menge lehrten, und daß die Jünger zuerst in Antiochien Christen genannt wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'In diesen Tagen aber kamen Propheten von Jerusalem nach Antiochien herab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Einer aber von ihnen, mit Namen Agabus, stand auf und zeigte durch den Geist eine große Hungersnot an, die über den ganzen Erdkreis kommen sollte, welche auch unter Klaudius eintrat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Sie beschlossen aber, jenachdem einer der Jünger begütert war, ein jeder von ihnen zur Hilfsleistung den Brüdern zu senden, die in Judäa wohnten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'was sie auch taten, indem sie es an die Ältesten sandten durch die Hand des Barnabas und Saulus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Um jene Zeit aber legte Herodes, der König, die Hände an etliche von der Versammlung, sie zu mißhandeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'er tötete aber Jakobus, den Bruder des Johannes, mit dem Schwerte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Und als er sah, daß es den Juden gefiel, fuhr er fort, auch Petrus festzunehmen (es waren aber die Tage der ungesäuerten Brote),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'welchen er auch, nachdem er ihn ergriffen hatte, ins Gefängnis setzte und an vier Abteilungen von je vier Kriegsknechten zur Bewachung überlieferte, indem er willens war, ihn nach dem Passah dem Volke vorzuführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Petrus nun wurde in dem Gefängnis verwahrt; aber von der Versammlung geschah ein anhaltendes Gebet für ihn zu Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Als aber Herodes ihn vorführen wollte, schlief Petrus in jener Nacht zwischen zwei Kriegsknechten, gebunden mit zwei Ketten, und Wächter vor der Tür verwahrten das Gefängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Und siehe, ein Engel des Herrn stand da, und ein Licht leuchtete in dem Kerker; und er schlug Petrus an die Seite, weckte ihn und sagte: Stehe schnell auf! Und die Ketten fielen ihm von den Händen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Und der Engel sprach zu ihm: Gürte dich und binde deine Sandalen unter. Er tat aber also. Und er spricht zu ihm: Wirf dein Oberkleid um und folge mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Und er ging hinaus und folgte ihm und wußte nicht, daß es Wirklichkeit war, was durch den Engel geschah; er meinte aber, ein Gesicht zu sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Als sie aber durch die erste und die zweite Wache gegangen waren, kamen sie an das eiserne Tor, das in die Stadt führte, welches sich ihnen von selbst auftat; und sie traten hinaus und gingen eine Straße entlang, und alsbald schied der Engel von ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Und als Petrus zu sich selbst kam, sprach er: Nun weiß ich in Wahrheit, daß der Herr seinen Engel gesandt und mich gerettet hat aus der Hand des Herodes und aller Erwartung des Volkes der Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Und als er sich bedachte, kam er an das Haus der Maria, der Mutter des Johannes, der Markus zubenamt war, wo viele versammelt waren und beteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Als er aber an der Tür des Tores klopfte, kam eine Magd, mit Namen Rhode, herbei, um zu horchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Und als sie die Stimme des Petrus erkannte, öffnete sie vor Freude das Tor nicht; sie lief aber hinein und verkündete, Petrus stehe vor dem Tore.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Sie aber sprachen zu ihr: Du bist von Sinnen. Sie aber beteuerte, daß es also sei. Sie aber sprachen: Es ist sein Engel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Petrus aber fuhr fort zu klopfen. Als sie aber aufgetan hatten, sahen sie ihn und waren außer sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Er aber winkte ihnen mit der Hand zu schweigen, und erzählte ihnen, wie der Herr ihn aus dem Gefängnis herausgeführt habe; und er sprach: Verkündet dies Jakobus und den Brüdern. Und er ging hinaus und zog an einen anderen Ort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Als es aber Tag geworden, war eine nicht geringe Bestürzung unter den Kriegsknechten, was doch aus Petrus geworden sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Als aber Herodes nach ihm verlangte und ihn nicht fand, zog er die Wächter zur Untersuchung und befahl sie abzuführen; und er ging von Judäa nach Cäsarea hinab und verweilte daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Er war aber sehr erbittert gegen die Tyrer und Sidonier. Sie kamen aber einmütig zu ihm, und nachdem die Blastus, den Kämmerer des Königs, überredet hatten, baten sie um Frieden, weil ihr Land von dem königlichen ernährt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'An einem festgesetzten Tage aber hielt Herodes, nachdem er königliche Kleider angelegt und sich auf den Thron gesetzt hatte, eine öffentliche Rede an sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Das Volk aber rief ihm zu: Eines Gottes Stimme und nicht eines Menschen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Alsbald aber schlug ihn ein Engel des Herrn, darum daß er nicht Gott die Ehre gab; und von Würmern gefressen, verschied er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Das Wort Gottes aber wuchs und mehrte sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnabas aber und Saulus kehrten, nachdem sie den Dienst erfüllt hatten, von Jerusalem zurück und nahmen auch Johannes mit, der Markus zubenamt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Es waren aber in Antiochien, in der dortigen Versammlung, Propheten und Lehrer: Barnabas und Simeon, genannt Niger, und Lucius von Kyrene, und Manaen, der mit Herodes, dem Vierfürsten, auferzogen war, und Saulus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Während sie aber dem Herrn dienten und fasteten, sprach der Heilige Geist: Sondert mir nun Barnabas und Saulus zu dem Werke aus, zu welchem ich sie berufen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Da fasteten und beteten sie; und als sie ihnen die Hände aufgelegt hatten, entließen sie sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Sie nun, ausgesandt von dem Heiligen Geiste, gingen hinab nach Seleucia, und von dannen segelten sie nach Cypern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Und als sie in Salamis waren, verkündigten sie das Wort Gottes in den Synagogen der Juden. Sie hatten aber auch Johannes zum Diener.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Als sie aber die ganze Insel bis Paphos durchzogen hatten, fanden sie einen gewissen Mann, einen Magier, einen falschen Propheten, einen Juden, mit Namen Bar-Jesus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'der bei dem Prokonsul Sergius Paulus war, einem verständigen Manne. Dieser rief Barnabas und Saulus herbei und begehrte das Wort Gottes zu hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Elymas aber, der Zauberer (denn so wird sein Name verdolmetscht), widerstand ihnen und suchte den Prokonsul von dem Glauben abwendig zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Saulus aber, der auch Paulus heißt, erfüllt mit Heiligem Geiste, blickte unverwandt auf ihn hin');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'und sprach: O du, voll aller List und aller Bosheit, Sohn des Teufels, Feind aller Gerechtigkeit! Willst du nicht aufhören, die geraden Wege des Herrn zu verkehren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Und jetzt siehe, die Hand des Herrn ist auf dir! Und du wirst blind sein und die Sonne eine Zeitlang nicht sehen. Und alsbald fiel Dunkel und Finsternis auf ihn; und er tappte umher und suchte solche, die ihn an der Hand leiteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Dann, als der Prokonsul sah, was geschehen war, glaubte er, erstaunt über die Lehre des Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Als aber Paulus und seine Begleiter von Paphos abgefahren waren, kamen sie nach Perge in Pamphylien. Johannes aber sonderte sich von ihnen ab und kehrte nach Jerusalem zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Sie aber zogen von Perge aus hindurch und kamen nach Antiochien in Pisidien; und sie gingen am Tage des Sabbaths in die Synagoge und setzten sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Aber nach dem Vorlesen des Gesetzes und der Propheten sandten die Vorsteher der Synagoge zu ihnen und sagten: Brüder, wenn in euch irgend ein Wort der Ermahnung an das Volk ist, so redet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Paulus aber stand auf, winkte mit der Hand und sprach: Männer von Israel und die ihr Gott fürchtet, höret:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Der Gott dieses Volkes Israel erwählte unsere Väter und erhöhte das Volk in der Fremdlingschaft im Lande Ägypten, und mit erhobenem Arm führte er sie von dannen heraus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'und eine Zeit von etwa vierzig Jahren pflegte er sie in der Wüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Und nachdem er sieben Nationen im Lande Kanaan vertilgt hatte, ließ er sie deren Land erben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Und nach diesem, bei vierhundertfünfzig Jahren, gab er ihnen Richter bis auf Samuel, den Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Und von da an begehrten sie einen König, und Gott gab ihnen Saul, den Sohn Kis\', einen Mann aus dem Stamme Benjamin, vierzig Jahre lang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Und nachdem er ihn weggetan hatte, erweckte er ihnen David zum König, welchem er auch Zeugnis gab und sprach: \"Ich habe David gefunden, den Sohn Isais, einen Mann nach meinem Herzen, der meinen ganzen Willen tun wird\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Aus dessen Samen hat Gott nach Verheißung dem Israel als Erretter Jesum gebracht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'nachdem Johannes, angesichts seines Eintritts, zuvor die Taufe der Buße dem ganzen Volke Israel verkündigt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Als aber Johannes seinen Lauf erfüllte, sprach er: Wer meinet ihr, daß ich sei? Ich bin es nicht, sondern siehe, es kommt einer nach mir, dessen ich nicht würdig bin, ihm die Sandale an den Füßen zu lösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Brüder, Söhne des Geschlechts Abrahams, und die unter euch Gott fürchten, euch ist das Wort dieses Heils gesandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Denn die zu Jerusalem wohnen und ihre Obersten, indem sie diesen nicht erkannten, haben auch die Stimmen der Propheten erfüllt, welche jeden Sabbath gelesen werden, indem sie über ihn Gericht hielten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Und obschon sie keine Ursache des Todes fanden, baten sie den Pilatus, daß er umgebracht würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Und nachdem sie alles vollendet hatten, was über ihn geschrieben ist, nahmen sie ihn vom Holze herab und legten ihn in eine Gruft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Gott aber hat ihn aus den Toten auferweckt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'und er ist mehrere Tage hindurch denen erschienen, die mit ihm hinaufgezogen waren von Galiläa nach Jerusalem, welche jetzt seine Zeugen an das Volk sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Und wir verkündigen euch die gute Botschaft von der zu den Vätern geschehenen Verheißung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'daß Gott dieselbe uns, ihren Kindern, erfüllt hat, indem er Jesum erweckte; wie auch in dem zweiten Psalm geschrieben steht: \"Du bist mein Sohn, heute habe ich dich gezeugt\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Daß er ihn aber aus den Toten auferweckt hat, um nicht mehr zur Verwesung zurückzukehren, hat er also ausgesprochen: \"Ich werde euch die gewissen Gnaden Davids geben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Deshalb sagt er auch an einer anderen Stelle: \"Du wirst nicht zugeben, daß dein Frommer die Verwesung sehe\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Denn David freilich, als er zu seiner Zeit dem Willen Gottes gedient hatte, entschlief und wurde zu seinen Vätern beigesetzt und sah die Verwesung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Der aber, den Gott auferweckt hat, sah die Verwesung nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'So sei es euch nun kund, Brüder, daß durch diesen euch Vergebung der Sünden verkündigt wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'und von allem, wovon ihr im Gesetz Moses\' nicht gerechtfertigt werden konntet, wird in diesem jeder Glaubende gerechtfertigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Sehet nun zu, daß nicht über euch komme, was in den Propheten gesagt ist:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '\"Sehet, ihr Verächter, und verwundert euch und verschwindet; denn ich wirke ein Werk in euren Tagen, ein Werk, das ihr nicht glauben werdet, wenn es euch jemand erzählt\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Als sie aber hinausgingen, baten sie, daß auf den folgenden Sabbath diese Worte zu ihnen geredet würden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Als aber die Synagoge aus war, folgten viele der Juden und der anbetenden Proselyten dem Paulus und Barnabas, welche zu ihnen sprachen und ihnen zuredeten, in der Gnade Gottes zu verharren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Am nächsten Sabbath aber versammelte sich fast die ganze Stadt, um das Wort Gottes zu hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Als aber die Juden die Volksmengen sahen, wurden sie von Eifersucht erfüllt und widersprachen dem, was von Paulus geredet wurde, widersprechend und lästernd.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Paulus aber und Barnabas gebrauchten Freimütigkeit und sprachen: Zu euch mußte notwendig das Wort Gottes zuerst geredet werden; weil ihr es aber von euch stoßet und euch selbst nicht würdig achtet des ewigen Lebens, siehe, so wenden wir uns zu den Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Denn also hat uns der Herr geboten: \"Ich habe dich zum Licht der Nationen gesetzt, auf daß du zum Heil seiest bis an das Ende der Erde\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Als aber die aus den Nationen es hörten, freuten sie sich und verherrlichten das Wort des Herrn; und es glaubten, so viele ihrer zum ewigen Leben verordnet waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Das Wort des Herrn aber wurde ausgebreitet durch die ganze Gegend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Die Juden aber erregten die anbetenden vornehmen Frauen und die Ersten der Stadt und erweckten eine Verfolgung wider Paulus und Barnabas und vertrieben sie aus ihren Grenzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Sie aber schüttelten den Staub von ihren Füßen wider sie ab und kamen nach Ikonium.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Die Jünger aber wurden mit Freude und heiligem Geiste erfüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Es geschah aber zu Ikonium, daß sie zusammen in die Synagoge der Juden gingen und also redeten, daß eine große Menge, sowohl von Juden als auch von Griechen, glaubte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Die ungläubigen Juden aber reizten und erbitterten die Seelen derer aus den Nationen wider die Brüder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Sie verweilten nun lange Zeit und sprachen freimütig in dem Herrn, der dem Worte seiner Gnade Zeugnis gab, indem er Zeichen und Wunder geschehen ließ durch ihre Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Die Menge der Stadt aber war entzweit, und die einen waren mit den Juden, die anderen mit den Aposteln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Als aber ein ungestümer Angriff geschah, sowohl von denen aus den Nationen als auch von den Juden samt ihren Obersten, um sie zu mißhandeln und zu steinigen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'entflohen sie, als sie es inne wurden, in die Städte von Lykaonien: Lystra und Derbe, und die Umgegend;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'und daselbst verkündigten sie das Evangelium.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Und ein gewisser Mann in Lystra saß da, kraftlos an den Füßen, lahm von seiner Mutter Leibe an, der niemals gewandelt hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Dieser hörte Paulus reden, welcher, als er unverwandt auf ihn hinblickte und sah, daß er Glauben hatte, geheilt zu werden, mit lauter Stimme sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Stelle dich gerade hin auf deine Füße! Und er sprang auf und wandelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Als die Volksmengen aber sahen, was Paulus tat, erhoben sie ihre Stimme und sagten auf lykaonisch: Die Götter sind den Menschen gleich geworden und sind zu uns herabgekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Und sie nannten den Barnabas Zeus, den Paulus aber Hermes, weil er das Wort führte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Der Priester des Zeus aber, welcher vor der Stadt war, brachte Stiere und Kränze an die Tore und wollte mit den Volksmengen opfern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Als aber die Apostel Barnabas und Paulus es hörten, zerrissen sie ihre Kleider, sprangen hinaus unter die Volksmenge und riefen und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'Männer, warum tut ihr dieses? Auch wir sind Menschen von gleichen Empfindungen wie ihr und verkündigen euch, daß ihr euch von diesen nichtigen Götzen bekehren sollt zu dem lebendigen Gott, welcher den Himmel und die Erde und das Meer gemacht hat und alles, was in ihnen ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'der in den vergangenen Geschlechtern alle Nationen in ihren eigenen Wegen gehen ließ,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'wiewohl er sich doch nicht unbezeugt gelassen hat, indem er Gutes tat und euch vom Himmel Regen und fruchtbare Zeiten gab und eure Herzen mit Speise und Fröhlichkeit erfüllte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Und als sie dies sagten, stillten sie kaum die Volksmengen, daß sie ihnen nicht opferten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Es kamen aber aus Antiochien und Ikonium Juden an, und nachdem sie die Volksmengen überredet und Paulus gesteinigt hatten, schleiften sie ihn zur Stadt hinaus, indem sie meinten, er sei gestorben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Als aber die Jünger ihn umringten, stand er auf und ging in die Stadt hinein; und des folgenden Tages zog er mit Barnabas aus nach Derbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Und als sie jener Stadt das Evangelium verkündigt und viele zu Jüngern gemacht hatten, kehrten sie nach Lystra und Ikonium und Antiochien zurück,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'indem sie die Seelen der Jünger befestigten, und sie ermahnten, im Glauben zu verharren, und daß wir durch viele Trübsale in das Reich Gottes eingehen müssen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Als sie ihnen aber in jeder Versammlung Älteste gewählt hatten, beteten sie mit Fasten und befahlen sie dem Herrn, an welchen sie geglaubt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Und nachdem sie Pisidien durchzogen hatten, kamen sie nach Pamphylien;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'und als sie in Perge das Wort geredet hatten, gingen sie hinab nach Attalia;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'und von dannen segelten sie ab nach Antiochien, von wo sie der Gnade Gottes befohlen worden waren zu dem Werke, das sie erfüllt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Als sie aber angekommen waren und die Versammlung zusammengebracht hatten, erzählten sie alles, was Gott mit ihnen getan, und daß er den Nationen eine Tür des Glaubens aufgetan habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Sie verweilten aber eine nicht geringe Zeit bei den Jüngern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Und etliche kamen von Judäa herab und lehrten die Brüder: Wenn ihr nicht beschnitten worden seid nach der Weise Moses\', so könnt ihr nicht errettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Als nun ein Zwiespalt entstand und ein nicht geringer Wortwechsel zwischen ihnen und dem Paulus und Barnabas, ordneten sie an, daß Paulus und Barnabas und etliche andere von ihnen zu den Aposteln und Ältesten nach Jerusalem hinaufgehen sollten wegen dieser Streitfrage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Sie nun, nachdem sie von der Versammlung das Geleit erhalten hatten, durchzogen Phönicien und Samaria und erzählten die Bekehrung derer aus den Nationen; und sie machten allen Brüdern große Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Als sie aber nach Jerusalem gekommen waren, wurden sie von der Versammlung und den Aposteln und Ältesten aufgenommen, und sie verkündeten alles, was Gott mit ihnen getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Etliche aber derer von der Sekte der Pharisäer, welche glaubten, traten auf und sagten: Man muß sie beschneiden und ihnen gebieten, das Gesetz Moses\' zu halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Die Apostel aber und die Ältesten versammelten sich, um diese Angelegenheit zu besehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Als aber viel Wortwechsel entstanden war, stand Petrus auf und sprach zu ihnen: Brüder ihr wisset, daß Gott vor längerer Zeit mich unter euch auserwählt hat, daß die Nationen durch meinen Mund das Wort des Evangeliums hören und glauben sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Und Gott, der Herzenskenner, gab ihnen Zeugnis, indem er ihnen den Heiligen Geist gab, gleichwie auch uns;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'und er machte keinen Unterschied zwischen uns und ihnen, indem er durch den Glauben ihre Herzen reinigte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Nun denn, was versuchet ihr Gott, ein Joch auf den Hals der Jünger zu legen, das weder unsere Väter noch wir zu tragen vermochten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Sondern wir glauben durch die Gnade des Herrn Jesus in derselben Weise errettet zu werden wie auch jene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Die ganze Menge aber schwieg und hörte Barnabas und Paulus zu, welche erzählten, wie viele Zeichen und Wunder Gott unter den Nationen durch sie getan habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Nachdem sie aber ausgeredet hatten, antwortete Jakobus und sprach: Brüder, höret mich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simon hat erzählt, wie Gott zuerst die Nationen heimgesucht hat, um aus ihnen ein Volk zu nehmen für seinen Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Und hiermit stimmen die Worte der Propheten überein, wie geschrieben steht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '\"Nach diesem will ich zurückkehren und wieder aufbauen die Hütte Davids, die verfallen ist, und ihre Trümmer will ich wieder bauen und sie wieder aufrichten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'damit die übrigen der Menschen den Herrn suchen, und alle Nationen, über welche mein Name angerufen ist, spricht der Herr, der dieses tut\",');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'was von jeher bekannt ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Deshalb urteile ich, daß man diejenigen, welche sich von den Nationen zu Gott bekehren, nicht beunruhige, sondern ihnen schreibe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'daß sie sich enthalten von den Verunreinigungen der Götzen und von der Hurerei und vom Erstickten und vom Blute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Denn Moses hat von alten Zeiten her in jeder Stadt solche, die ihn predigen, indem er an jedem Sabbath in den Synagogen gelesen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Dann deuchte es den Aposteln und den Ältesten samt der ganzen Versammlung gut, Männer aus sich zu erwählen und sie mit Paulus und Barnabas nach Antiochien zu senden: Judas, genannt Barsabas, und Silas, Männer, welche Führer unter den Brüdern waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Und sie schrieben und sandten durch ihre Hand folgendes: \"Die Apostel und die Ältesten und die Brüder an die Brüder, die aus den Nationen sind zu Antiochien und in Syrien und Cilicien, ihren Gruß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Weil wir gehört haben, daß etliche, die aus unserer Mitte ausgegangen sind, euch mit Worten beunruhigt haben, indem sie eure Seelen verstören und sagen, ihr müßtet beschnitten werden und das Gesetz halten denen wir keine Befehle gegeben haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'deuchte es uns, einstimmig geworden, gut, Männer auszuerwählen und sie mit unseren Geliebten, Barnabas und Paulus, zu euch zu senden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'mit Männern, die ihr Leben hingegeben haben für den Namen unseres Herrn Jesus Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Wir haben nun Judas und Silas gesandt, die auch selbst mündlich dasselbe verkündigen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Denn es hat dem Heiligen Geiste und uns gut geschienen, keine größere Last auf euch zu legen, als diese notwendigen Stücke:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'euch zu enthalten von Götzenopfern und von Blut und von Ersticktem und von Hurerei. Wenn ihr euch davor bewahret, so werdet ihr wohl tun. Lebet wohl!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Nachdem sie nun entlassen waren, kamen sie nach Antiochien hinab; und sie versammelten die Menge und übergaben den Brief.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Als sie ihn aber gelesen hatten, freuten sie sich über den Trost.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Und Judas und Silas, die auch selbst Propheten waren, ermunterten die Brüder mit vielen Worten und stärkten sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Nachdem sie sich aber eine Zeitlang aufgehalten hatten, wurden sie mit Frieden von den Brüdern entlassen zu denen, die sie gesandt hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Paulus aber und Barnabas verweilten in Antiochien und lehrten und verkündigten mit noch vielen anderen das Wort des Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Nach etlichen Tagen aber sprach Paulus zu Barnabas: Laß uns nun zurückkehren und die Brüder besuchen in jeder Stadt, in welcher wir das Wort des Herrn verkündigt haben, und sehen, wie es ihnen geht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Barnabas aber war gesonnen, auch Johannes, genannt Markus, mitzunehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Paulus aber hielt es für billig, den nicht mitzunehmen, der aus Pamphylien von ihnen gewichen und nicht mit ihnen gegangen war zum Werke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Es entstand nun eine Erbitterung, so daß sie sich voneinander trennten, und daß Barnabas den Markus mitnahm und nach Cypern segelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Paulus aber erwählte sich Silas und zog aus, von den Brüdern der Gnade Gottes befohlen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Er durchzog aber Syrien und Cilicien und befestigte die Versammlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Er gelangte aber nach Derbe und Lystra. Und siehe, daselbst war ein gewisser Jünger, mit Namen Timotheus, der Sohn eines jüdischen gläubigen Weibes, aber eines griechischen Vaters;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'welcher ein gutes Zeugnis hatte von den Brüdern in Lystra und Ikonium.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Paulus wollte, daß dieser mit ihm ausgehe, und er nahm und beschnitt ihn um der Juden willen, die in jenen Orten waren; denn sie kannten alle seinen Vater, daß er ein Grieche war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Als sie aber die Städte durchzogen, teilten sie ihnen zur Beobachtung die Beschlüsse mit, welche von den Aposteln und Ältesten in Jerusalem festgesetzt waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Die Versammlungen nun wurden im Glauben befestigt und vermehrten sich täglich an Zahl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Sie durchzogen aber Phrygien und die galatische Landschaft, nachdem sie von dem Heiligen Geiste verhindert worden waren, das Wort in Asien zu reden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'als sie aber gegen Mysien hin kamen, versuchten sie nach Bithynien zu reisen, und der Geist Jesu erlaubte es ihnen nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Als sie aber an Mysien vorübergezogen waren, gingen sie nach Troas hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Und es erschien dem Paulus in der Nacht ein Gesicht: Ein gewisser macedonischer Mann stand da und bat ihn und sprach: Komm herüber nach Macedonien und hilf uns!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Als er aber das Gesicht gesehen hatte, suchten wir alsbald nach Macedonien abzureisen, indem wir schlossen, daß der Herr uns gerufen habe, ihnen das Evangelium zu verkündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Wir fuhren nun von Troas ab und kamen geraden Laufs nach Samothrace, und des folgenden Tages nach Neapolis,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'und von da nach Philippi, welches die erste Stadt jenes Teiles von Macedonien ist, eine Kolonie. In dieser Stadt aber verweilten wir einige Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Und am Tage des Sabbaths gingen wir hinaus vor das Tor an einen Fluß, wo es gebräuchlich war, das Gebet zu verrichten; und wir setzten uns nieder und redeten zu den Weibern, die zusammengekommen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Und ein gewisses Weib, mit Namen Lydia, eine Purpurkrämerin aus der Stadt Thyatira, welche Gott anbetete, hörte zu, deren Herz der Herr auftat, daß sie achtgab auf das, was von Paulus geredet wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Als sie aber getauft worden war und ihr Haus, bat sie und sagte: Wenn ihr urteilet, daß ich dem Herrn treu sei, so kehret in mein Haus ein und bleibet. Und sie nötigte uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Es geschah aber, als wir zum Gebet gingen, daß uns eine gewisse Magd begegnete, die einen Wahrsagergeist hatte, welche ihren Herren vielen Gewinn brachte durch Wahrsagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Diese folgte dem Paulus und uns nach und schrie und sprach: Diese Menschen sind Knechte Gottes, des Höchsten, die euch den Weg des Heils verkündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Dies aber tat sie viele Tage. Paulus aber, tiefbetrübt, wandte sich um und sprach zu dem Geiste: Ich gebiete dir in dem Namen Jesu Christi, von ihr auszufahren! Und er fuhr aus zu derselben Stunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Als aber ihre Herren sahen, daß die Hoffnung auf ihren Gewinn dahin war, griffen sie Paulus und Silas und schleppten sie auf den Markt zu den Vorstehern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Und sie führten sie zu den Hauptleuten und sprachen: Diese Menschen, welche Juden sind, verwirren ganz und gar unsere Stadt');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'und verkündigen Gebräuche, die uns nicht erlaubt sind anzunehmen noch auszuüben, da wir Römer sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Und die Volksmenge erhob sich zugleich wider sie, und die Hauptleute rissen ihnen die Kleider ab und befahlen, sie mit Ruten zu schlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Und als sie ihnen viele Schläge gegeben hatten, warfen sie sie ins Gefängnis und befahlen dem Kerkermeister, sie sicher zu verwahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Dieser warf sie, als er solchen Befehl empfangen hatte, in das innerste Gefängnis und befestigte ihre Füße in dem Stock.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Um Mitternacht aber beteten Paulus und Silas und lobsangen Gott; und die Gefangenen hörten ihnen zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Plötzlich aber geschah ein großes Erdbeben, so daß die Grundfesten des Gefängnisses erschüttert wurden; und alsbald öffneten sich alle Türen, und aller Bande wurden gelöst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Als aber der Kerkermeister aus dem Schlafe aufwachte und die Türen des Gefängnisses geöffnet sah, zog er das Schwert und wollte sich umbringen, indem er meinte, die Gefangenen wären entflohen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Paulus aber rief mit lauter Stimme und sprach: Tue dir nichts Übles, denn wir sind alle hier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Er aber forderte Licht und sprang hinein; und zitternd fiel er vor Paulus und Silas nieder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Und er führte sie heraus und sprach: Ihr Herren, was muß ich tun, auf daß ich errettet werde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Sie aber sprachen: Glaube an den Herrn Jesus, und du wirst errettet werden, du und dein Haus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'Und sie redeten das Wort des Herrn zu ihm samt allen, die in seinem Hause waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Und er nahm sie in jener Stunde der Nacht zu sich und wusch ihnen die Striemen ab; und er wurde getauft, er und alle die Seinigen alsbald.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Und er führte sie hinauf in sein Haus, setzte ihnen einen Tisch vor und frohlockte, an Gott gläubig geworden, mit seinem ganzen Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Als es aber Tag geworden war, sandten die Hauptleute die Rutenträger und sagten: Laß jene Menschen los.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Der Kerkermeister aber berichtete dem Paulus diese Worte: Die Hauptleute haben gesandt, daß ihr losgelassen würdet; so gehet denn jetzt hinaus und ziehet hin in Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Paulus aber sprach zu ihnen: Nachdem sie uns, die wir Römer sind, öffentlich unverurteilt geschlagen, haben sie uns ins Gefängnis geworfen, und jetzt stoßen sie uns heimlich aus? Nicht doch; sondern laß sie selbst kommen und uns hinausführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Die Rutenträger aber meldeten diese Worte den Hauptleuten; und sie fürchteten sich, als sie hörten, daß sie Römer seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'Und sie kamen und redeten ihnen zu; und sie führten sie hinaus und baten sie, daß sie aus der Stadt gehen möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Als sie aber aus dem Gefängnis herausgegangen waren, gingen sie zu der Lydia; und als sie die Brüder gesehen hatten, ermahnten sie sie und gingen weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Nachdem sie aber durch Amphipolis und Apollonia gereist waren, kamen sie nach Thessalonich, wo die Synagoge der Juden war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Nach seiner Gewohnheit aber ging Paulus zu ihnen hinein und unterredete sich an drei Sabbathen mit ihnen aus den Schriften,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'indem er eröffnete und darlegte, daß der Christus leiden und aus den Toten auferstehen mußte, und daß dieser, der Jesus, den ich euch verkündige, der Christus ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Und etliche von ihnen glaubten und gesellten sich zu Paulus und Silas, und von den anbetenden Griechen eine große Menge und der vornehmsten Frauen nicht wenige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Die Juden aber wurden voll Neides und nahmen etliche böse Männer vom Gassenpöbel zu sich, machten einen Volksauflauf und brachten die Stadt in Aufruhr; und sie traten vor das Haus Jasons und suchten sie unter das Volk zu führen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Als sie sie aber nicht fanden, schleppten sie Jason und etliche Brüder vor die Obersten der Stadt und riefen: Diese, welche den Erdkreis aufgewiegelt haben, sind auch hierher gekommen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'welche Jason beherbergt hat; und diese alle handeln wider die Verordnungen des Kaisers, indem sie sagen, daß ein anderer König sei Jesus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Sie beunruhigten aber die Volksmenge und die Obersten der Stadt, als sie dies hörten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Und nachdem sie von Jason und den übrigen Bürgschaft genommen hatten, entließen sie dieselben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Die Brüder aber sandten alsbald in der Nacht sowohl Paulus als Silas nach Beröa, welche, als sie angekommen waren, in die Synagoge der Juden gingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Diese aber waren edler als die in Thessalonich; sie nahmen mit aller Bereitwilligkeit das Wort auf, indem sie täglich die Schriften untersuchten, ob dies sich also verhielte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Viele nun von ihnen glaubten, und von den griechischen vornehmen Weibern und Männern nicht wenige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Als aber die Juden von Thessalonich erfuhren, daß auch in Beröa das Wort Gottes von Paulus verkündigt wurde, kamen sie auch dorthin und erregten die Volksmengen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Da sandten aber die Brüder alsbald den Paulus fort, um nach dem Meere hin zu gehen. Aber sowohl Silas als Timotheus blieben daselbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Die aber den Paulus geleiteten, brachten ihn bis nach Athen; und als sie für Silas und Timotheus Befehl empfangen hatten, daß sie sobald wie möglich zu ihm kommen sollten, reisten sie ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Während aber Paulus sie in Athen erwartete, wurde sein Geist in ihm erregt, da er die Stadt voll von Götzenbildern sah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Er unterredete sich nun in der Synagoge mit den Juden und mit den Anbetern, und auf dem Markte an jedem Tage mit denen, welche gerade herzukamen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Aber auch etliche der epikuräischen und stoischen Philosophen griffen ihn an; und etliche sagten: Was will doch dieser Schwätzer sagen? andere aber: Er scheint ein Verkündiger fremder Götter zu sein, weil er ihnen das Evangelium von Jesu und der Auferstehung verkündigte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Und sie ergriffen ihn, führten ihn zum Areopag und sagten: Können wir erfahren, was diese neue Lehre ist, von welcher du redest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Denn du bringst etwas Fremdes vor unsere Ohren. Wir möchten nun wissen, was das sein mag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Alle Athener aber und die Fremden, die sich da aufhielten, brachten ihre Zeit mit nichts anderem zu, als etwas Neues zu sagen und zu hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Paulus aber stand mitten auf dem Areopag und sprach: Männer von Athen, ich sehe, daß ihr in jeder Beziehung den Göttern sehr ergeben seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Denn als ich umherging und die Gegenstände eurer Verehrung betrachtete, fand ich auch einen Altar, an welchem die Aufschrift war: Dem unbekannten Gott. Den ihr nun, ohne ihn zu kennen, verehret, diesen verkündige ich euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Der Gott, der die Welt gemacht hat und alles, was darinnen ist, dieser, indem er der Herr des Himmels und der Erde ist, wohnt nicht in Tempeln, die mit Händen gemacht sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'noch wird er von Menschenhänden bedient, als wenn er noch etwas bedürfe, da er selbst allen Leben und Odem und alles gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Und er hat aus einem Blute jede Nation der Menschen gemacht, um auf dem ganzen Erdboden zu wohnen, indem er verordnete Zeiten und die Grenzen ihrer Wohnung bestimmt hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'daß sie Gott suchen, ob sie ihn wohl tastend fühlen und finden möchten, obgleich er nicht fern ist von einem jeden von uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Denn in ihm leben und weben und sind wir, wie auch etliche eurer Dichter gesagt haben: \"Denn wir sind auch sein Geschlecht\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Da wir nun Gottes Geschlecht sind, so sollen wir nicht meinen, daß das Göttliche dem Golde oder Silber oder Stein, einem Gebilde der Kunst und der Erfindung des Menschen, gleich sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Nachdem nun Gott die Zeiten der Unwissenheit übersehen hat, gebietet er jetzt den Menschen, daß sie alle allenthalben Buße tun sollen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'weil er einen Tag gesetzt hat, an welchem er den Erdkreis richten wird in Gerechtigkeit durch einen Mann, den er dazu bestimmt hat, und hat allen den Beweis davon gegeben, indem er ihn auferweckt hat aus den Toten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Als sie aber von Totenauferstehung hörten, spotteten die einen, die anderen aber sprachen: Wir wollen dich darüber auch nochmals hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'Also ging Paulus aus ihrer Mitte hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Etliche Männer aber schlossen sich ihm an und glaubten, unter welchen auch Dionysius war, der Areopagit, und ein Weib, mit Namen Damaris, und andere mit ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Nach diesem aber schied er von Athen und kam nach Korinth.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Und als er einen gewissen Juden fand, mit Namen Aquila, aus Pontus gebürtig, der kürzlich aus Italien gekommen war, und Priscilla, sein Weib, (weil Klaudius befohlen hatte, daß alle Juden sich aus Rom entfernen sollten), ging er zu ihnen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'und weil er gleichen Handwerks war, blieb er bei ihnen und arbeitete; denn sie waren Zeltmacher ihres Handwerks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Er unterredete sich aber in der Synagoge an jedem Sabbath und überzeugte Juden und Griechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Als aber sowohl Silas als Timotheus aus Macedonien herabkamen, wurde Paulus hinsichtlich des Wortes gedrängt und bezeugte den Juden, daß Jesus der Christus sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Als sie aber widerstrebten und lästerten, schüttelte er die Kleider aus und sprach zu ihnen: Euer Blut komme auf euren Kopf! Ich bin rein; von jetzt an werde ich zu den Nationen gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Und er ging von dannen fort und kam in das Haus eines Gewissen, mit Namen Justus, welcher Gott anbetete, dessen Haus an die Synagoge stieß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Krispus aber, der Vorsteher der Synagoge, glaubte an den Herrn mit seinem ganzen Hause; und viele der Korinther, welche hörten, glaubten und wurden getauft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Der Herr aber sprach durch ein Gesicht in der Nacht zu Paulus: Fürchte dich nicht, sondern rede und schweige nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Denn ich bin mit dir, und niemand soll dich angreifen, dir Übles zu tun; denn ich habe ein großes Volk in dieser Stadt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Und er hielt sich ein Jahr und sechs Monate auf und lehrte unter ihnen das Wort Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Als aber Gallion Prokonsul von Achaja war, traten die Juden einmütig gegen Paulus auf und führten ihn vor den Richterstuhl und sagten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'Dieser überredet die Menschen, Gott anzubeten, dem Gesetz zuwider.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Als aber Paulus den Mund öffnen wollte, sagte Gallion zu den Juden: Wenn es ein Unrecht oder eine böse Handlung wäre, o Juden, so hätte ich euch billigerweise ertragen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'wenn es aber Streitfragen sind über Worte und Namen und das Gesetz, das ihr habt, so sehet ihr selbst zu, denn über diese Dinge will ich nicht Richter sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Und er trieb sie von dem Richterstuhl hinweg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Alle aber ergriffen Sosthenes, den Vorsteher der Synagoge, und schlugen ihn vor dem Richterstuhl; und Gallion bekümmerte sich nicht um dies alles.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Nachdem aber Paulus noch viele Tage dageblieben war, nahm er Abschied von den Brüdern und segelte nach Syrien ab, und mit ihm Priscilla und Aquila, nachdem er zu Kenchreä das Haupt geschoren hatte, denn er hatte ein Gelübde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Er kam aber nach Ephesus und ließ jene daselbst; er selbst aber ging in die Synagoge und unterredete sich mit den Juden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Als sie ihn aber baten, daß er längere Zeit bei ihnen bleiben möchte, willigte er nicht ein,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'sondern nahm Abschied von ihnen und sagte: Ich muß durchaus das zukünftige Fest in Jerusalem halten ich werde, wenn Gott will, wieder zu euch zurückkehren. Und er fuhr von Ephesus ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Und als er zu Cäsarea gelandet war, ging er hinauf und begrüßte die Versammlung und zog hinab nach Antiochien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Und als er einige Zeit daselbst zugebracht hatte, reiste er ab und durchzog der Reihe nach die galatische Landschaft und Phrygien und befestigte alle Jünger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Ein gewisser Jude aber, mit Namen Apollos, aus Alexandrien gebürtig, ein beredter Mann, der mächtig war in den Schriften, kam nach Ephesus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Dieser war in dem Wege des Herrn unterwiesen, und, brünstig im Geist, redete und lehrte er sorgfältig die Dinge von Jesu, wiewohl er nur die Taufe Johannes\' kannte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Und dieser fing an, freimütig in der Synagoge zu reden. Als aber Aquila und Priscilla ihn hörten, nahmen sie ihn zu sich und legten ihm den Weg Gottes genauer aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Als er aber nach Achaja reisen wollte, schrieben die Brüder den Jüngern und ermahnten sie, ihn aufzunehmen. Dieser war, als er hinkam, den Glaubenden durch die Gnade sehr behilflich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'denn kräftig widerlegte er die Juden öffentlich, indem er durch die Schriften bewies, daß Jesus der Christus ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Es geschah aber, während Apollos in Korinth war, daß Paulus, nachdem er die oberen Gegenden durchzogen hatte, nach Ephesus kam. Und er fand etliche Jünger');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'und sprach zu ihnen: Habt ihr den Heiligen Geist empfangen, nachdem ihr gläubig geworden seid? Sie aber sprachen zu ihm: Wir haben nicht einmal gehört, ob der Heilige Geist da ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Und er sprach: Worauf seid ihr denn getauft worden? Sie aber sagten: Auf die Taufe Johannes\'.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Paulus aber sprach: Johannes hat mit der Taufe der Buße getauft, indem er dem Volke sagte, daß sie an den glauben sollten, der nach ihm käme, das ist an Jesum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Als sie es aber gehört hatten, wurden sie auf den Namen des Herrn Jesus getauft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'und als Paulus ihnen die Hände aufgelegt hatte, kam der Heilige Geist auf sie, und sie redeten in Sprachen und weissagten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Es waren aber insgesamt etwa zwölf Männer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Er ging aber in die Synagoge und sprach freimütig drei Monate lang, indem er sich unterredete und sie von den Dingen des Reiches Gottes überzeugte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Als aber etliche sich verhärteten und nicht glaubten und vor der Menge übel redeten von dem Wege, trennte er sich von ihnen und sonderte die Jünger ab, indem er sich täglich in der Schule des Tyrannus unterredete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Dies aber geschah zwei Jahre lang, so daß alle, die in Asien wohnten, sowohl Juden als Griechen, das Wort des Herrn hörten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Und nicht gemeine Wunderwerke tat Gott durch die Hände des Paulus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'so daß man sogar Schweißtücher oder Schürzen von seinem Leibe weg auf die Kranken legte, und die Krankheiten von ihnen wichen und die bösen Geister ausfuhren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Aber auch etliche von den umherziehenden jüdischen Beschwörern unternahmen es, über die, welche böse Geister hatten, den Namen des Herrn Jesus auszurufen, indem sie sagten: Ich beschwöre euch bei dem Jesus, welchen Paulus predigt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Es waren aber gewisse Söhne eines jüdischen Hohenpriesters Skeva, ihrer sieben, die dies taten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Der böse Geist aber antwortete und sprach zu ihnen: Jesum kenne ich, und von Paulus weiß ich; aber ihr, wer seid ihr?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Und der Mensch, in welchem der böse Geist war, sprang auf sie los und bemeisterte sich beider und überwältigte sie, so daß sie nackt und verwundet aus jenem Hause entflohen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Dies aber wurde allen bekannt, sowohl Juden als Griechen, die zu Ephesus wohnten; und Furcht fiel auf sie alle, und der Name des Herrn Jesus wurde erhoben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Viele aber von denen, die gläubig geworden waren, kamen und bekannten und verkündigten ihre Taten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Viele aber von denen, welche vorwitzige Künste getrieben hatten, trugen die Bücher zusammen und verbrannten sie vor allen; und sie berechneten den Wert derselben und fanden ihn zu fünfzigtausend Stück Silber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Also wuchs das Wort des Herrn mit Macht und nahm überhand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Als dies aber erfüllt war, setzte sich Paulus in seinem Geiste vor, nachdem er Macedonien und Achaja durchzogen habe, nach Jerusalem zu reisen, und sprach: Nachdem ich dort gewesen bin, muß ich auch Rom sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Er sandte aber zwei von denen, die ihm dienten, Timotheus und Erastus, nach Macedonien, und er selbst verweilte eine Zeitlang in Asien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Es entstand aber um jene Zeit ein nicht geringer Lärm betreffs des Weges.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Denn ein Gewisser, mit Namen Demetrius, ein Silberschmied, der silberne Tempel der Artemis machte, verschaffte den Künstlern nicht geringen Erwerb;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'und nachdem er diese samt den Arbeitern derartiger Dinge versammelt hatte, sprach er: Männer, ihr wisset, daß aus diesem Erwerb unser Wohlstand ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'und ihr sehet und höret, daß dieser Paulus nicht allein von Ephesus, sondern beinahe von ganz Asien eine große Volksmenge überredet und abgewandt hat, indem er sagt, daß das keine Götter seien, die mit Händen gemacht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Nicht allein aber ist für uns Gefahr, daß dieses Geschäft in Verachtung komme, sondern auch, daß der Tempel der großen Göttin Artemis für nichts geachtet und auch ihre herrliche Größe, welche ganz Asien und der Erdkreis verehrt, vernichtet werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Als sie aber das hörten und voll Wut wurden, schrieen sie und sagten: Groß ist die Artemis der Epheser!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Und die ganze Stadt geriet in Verwirrung; und sie stürmten einmütig nach dem Theater, indem sie die Macedonier Gajus und Aristarchus, die Reisegefährten des Paulus, mit fortrissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Als aber Paulus unter das Volk gehen wollte, ließen die Jünger es ihm nicht zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Und auch etliche der Asiarchen, die seine Freunde waren, sandten zu ihm und baten ihn, sich nicht nach dem Theater zu begeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Die einen nun schrieen dieses, die anderen jenes; denn die Versammlung war in Verwirrung, und die meisten wußten nicht, weshalb sie zusammengekommen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Sie zogen aber Alexander aus der Volksmenge hervor, indem die Juden ihn hervorstießen. Alexander aber winkte mit der Hand und wollte sich vor dem Volke verantworten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Als sie aber erkannten, daß er ein Jude war, erhob sich eine Stimme aus aller Mund, und sie schrieen bei zwei Stunden: Groß ist die Artemis der Epheser!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Als aber der Stadtschreiber die Volksmenge beruhigt hatte, spricht er: Männer von Ephesus, welcher Mensch ist denn, der nicht wisse, daß die Stadt der Epheser eine Tempelpflegerin der großen Artemis und des vom Himmel gefallenen Bildes ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Da nun dieses unwidersprechlich ist, so geziemt es euch, ruhig zu sein und nichts Übereiltes zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Denn ihr habt diese Männer hergeführt, die weder Tempelräuber sind, noch eure Göttin lästern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Wenn nun Demetrius und die Künstler mit ihm wider jemand eine Sache haben, so werden Gerichtstage gehalten, und es sind Statthalter da; mögen sie einander verklagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Wenn ihr aber wegen anderer Dinge ein Gesuch habt, so wird es in der gesetzlichen Versammlung erledigt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Denn wir sind auch in Gefahr, wegen heute des Aufruhrs angeklagt zu werden, indem es keine Ursache gibt, weswegen wir uns über diesen Auflauf werden verantworten können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, 'Und als er dies gesagt hatte, entließ er die Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Nachdem aber der Tumult aufgehört hatte, rief Paulus die Jünger zu sich, und als er Abschied genommen hatte, ging er fort, um nach Macedonien zu reisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Als er aber jene Gegenden durchzogen und sie mit vielen Worten ermahnt hatte, kam er nach Griechenland.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Und nachdem er sich drei Monate aufgehalten hatte und, als er nach Syrien abfahren wollte, von den Juden ein Anschlag gegen ihn geschehen war, wurde er des Sinnes, durch Macedonien zurückzukehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Es begleitete ihn aber bis nach Asien Sopater, des Pyrrhus Sohn, ein Beröer; von den Thessalonichern aber Aristarchus und Sekundus und Gajus von Derbe und Timotheus und Tychikus und Trophimus aus Asien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Diese gingen voraus und warteten auf uns in Troas;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'wir aber segelten nach den Tagen der ungesäuerten Brote von Philippi ab und kamen in fünf Tagen zu ihnen nach Troas, wo wir sieben Tage verweilten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Am ersten Tage der Woche aber, als wir versammelt waren, um Brot zu brechen, unterredete sich Paulus mit ihnen, indem er am folgenden Tage abreisen wollte; und er verzog das Wort bis Mitternacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Es waren aber viele Fackeln in dem Obersaal, wo wir versammelt waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Ein gewisser Jüngling aber, mit Namen Eutychus, saß im Fenster und wurde von einem tiefen Schlaf überwältigt, während Paulus noch weiter redete; und von dem Schlaf überwältigt, fiel er vom dritten Stock hinunter und wurde tot aufgehoben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Paulus aber ging hinab und fiel auf ihn, und, ihn umfassend, sagte er: Machet keinen Lärm, denn seine Seele ist in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Und als er hinaufgestiegen war und das Brot gebrochen und gegessen und lange bis zum Anbruch des Tages geredet hatte, reiste er also ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Sie brachten aber den Knaben lebendig und wurden nicht wenig getröstet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Wir aber gingen voraus auf das Schiff und fuhren ab nach Assos, indem wir dort den Paulus aufnehmen wollten; denn so hatte er es angeordnet, da er selbst zu Fuß gehen wollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Als er aber in Assos mit uns zusammentraf, nahmen wir ihn auf und kamen nach Mitylene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Und als wir von da abgesegelt waren, langten wir am folgenden Tage Chios gegenüber an; des anderen Tages aber legten wir in Samos an, und nachdem wir in Trogyllion geblieben waren, kamen wir am folgenden Tage nach Milet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'denn Paulus hatte sich entschlossen, an Ephesus vorbeizufahren, damit es ihm nicht geschehe, in Asien Zeit zu versäumen; denn er eilte, wenn es ihm möglich wäre, am Pfingsttage in Jerusalem zu sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Von Milet aber sandte er nach Ephesus und rief die Ältesten der Versammlung herüber.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Als sie aber zu ihm gekommen waren, sprach er zu ihnen: Ihr wisset von dem ersten Tage an, da ich nach Asien kam, wie ich die ganze Zeit bei euch gewesen bin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'dem Herrn dienend mit aller Demut und mit Tränen und Versuchungen, welche mir durch die Nachstellungen der Juden widerfuhren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'wie ich nichts zurückgehalten habe von dem, was nützlich ist, daß ich es euch nicht verkündigt und euch gelehrt hätte, öffentlich und in den Häusern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'indem ich sowohl Juden als Griechen bezeugte die Buße zu Gott und den Glauben an unseren Herrn Jesus Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Und nun siehe, gebunden in meinem Geiste gehe ich nach Jerusalem, nicht wissend, was mir daselbst begegnen wird,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'außer daß der Heilige Geist mir von Stadt zu Stadt bezeugt und sagt, daß Bande und Drangsale meiner warten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Aber ich nehme keine Rücksicht auf mein Leben, als teuer für mich selbst, auf daß ich meinen Lauf vollende und den Dienst, den ich von dem Herrn Jesus empfangen habe, zu bezeugen das Evangelium der Gnade Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Und nun siehe, ich weiß, daß ihr alle, unter welchen ich, das Reich Gottes predigend, umhergegangen bin, mein Angesicht nicht mehr sehen werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Deshalb bezeuge ich euch an dem heutigen Tage, daß ich rein bin von dem Blute aller;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'denn ich habe nicht zurückgehalten, euch den ganzen Ratschluß Gottes zu verkündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Habet nun acht auf euch selbst und auf die ganze Herde, in welcher der Heilige Geist euch als Aufseher gesetzt hat, die Versammlung Gottes zu hüten, welche er sich erworben hat durch das Blut seines Eigenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Denn ich weiß dieses, daß nach meinem Abschiede verderbliche Wölfe zu euch hereinkommen werden, die der Herde nicht schonen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Und aus euch selbst werden Männer aufstehen, die verkehrte Dinge reden, um die Jünger abzuziehen hinter sich her.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Darum wachet und gedenket, daß ich drei Jahre lang Nacht und Tag nicht aufgehört habe, einen jeden mit Tränen zu ermahnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Und nun befehle ich euch Gott und dem Worte seiner Gnade, welches vermag aufzuerbauen und euch ein Erbe zu geben unter allen Geheiligten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Ich habe niemandes Silber oder Gold oder Kleidung begehrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Ihr selbst wisset, daß meinen Bedürfnissen und denen, die bei mir waren, diese Hände gedient haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Ich habe euch alles gezeigt, daß man, also arbeitend, sich der Schwachen annehmen und eingedenk sein müsse der Worte des Herrn Jesus, der selbst gesagt hat: Geben ist seliger als Nehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Und als er dies gesagt hatte, kniete er nieder und betete mit ihnen allen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Es entstand aber viel Weinens bei allen; und sie fielen Paulus um den Hals und küßten ihn sehr,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'am meisten betrübt über das Wort, das er gesagt hatte, sie würden sein Angesicht nicht mehr sehen. Sie geleiteten ihn aber zu dem Schiffe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Als es aber geschah, daß wir abfuhren, nachdem wir uns von ihnen losgerissen hatten, kamen wir geraden Laufs nach Kos, des folgenden Tages aber nach Rhodus und von da nach Patara.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Und als wir ein Schiff fanden, das nach Phönicien übersetzte, stiegen wir ein und fuhren ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Als wir aber Cyperns ansichtig wurden und es links liegen ließen, segelten wir nach Syrien und legten zu Tyrus an, denn daselbst hatte das Schiff die Ladung abzuliefern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Und als wir die Jünger gefunden hatten, blieben wir daselbst sieben Tage; diese sagten dem Paulus durch den Geist, er möge nicht nach Jerusalem hinaufgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Als es aber geschah, daß wir die Tage vollendet hatten, zogen wir fort und reisten weiter; und sie alle geleiteten uns mit Weibern und Kindern bis außerhalb der Stadt; und wir knieten am Ufer nieder und beteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'Und als wir voneinander Abschied genommen hatten, stiegen wir in das Schiff, jene aber kehrten heim.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Als wir aber die Fahrt vollbracht hatten, gelangten wir von Tyrus nach Ptolemais; und wir begrüßten die Brüder und blieben einen Tag bei ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Des folgenden Tages aber zogen wir aus und kamen nach Cäsarea; und wir gingen in das Haus des Philippus, des Evangelisten, der einer von den sieben war, und blieben bei ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Dieser aber hatte vier Töchter, Jungfrauen, welche weissagten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Als wir aber mehrere Tage blieben, kam ein gewisser Prophet, mit Namen Agabus, von Judäa herab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Und er kam zu uns und nahm den Gürtel des Paulus und band sich die Hände und die Füße und sprach: Dies sagt der Heilige Geist: Den Mann, dem dieser Gürtel gehört, werden die Juden in Jerusalem also binden und in die Hände der Nationen überliefern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Als wir aber dies hörten, baten sowohl wir als auch die daselbst Wohnenden, daß er nicht nach Jerusalem hinaufgehen möchte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Paulus aber antwortete: Was machet ihr, daß ihr weinet und mir das Herz brechet? Denn ich bin bereit, nicht allein gebunden zu werden, sondern auch in Jerusalem für den Namen des Herrn Jesus zu sterben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Als er sich aber nicht überreden ließ, schwiegen wir und sprachen: Der Wille des Herrn geschehe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Nach diesen Tagen aber machten wir unsere Sachen bereit und gingen hinauf nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Es gingen aber auch einige von den Jüngern aus Cäsarea mit uns und brachten einen gewissen Mnason mit, einen Cyprier, einen alten Jünger, bei dem wir herbergen sollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Als wir aber zu Jerusalem angekommen waren, nahmen uns die Brüder freudig auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Des folgenden Tages aber ging Paulus mit uns zu Jakobus, und alle Ältesten kamen dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Und als er sie begrüßt hatte, erzählte er eines nach dem anderen, was Gott unter den Nationen durch seinen Dienst getan hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Sie aber, als sie es gehört hatten, verherrlichten Gott und sprachen zu ihm: Du siehst, Bruder, wie viele Tausende der Juden es gibt, welche glauben, und alle sind Eiferer für das Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Es ist ihnen aber über dich berichtet worden, daß du alle Juden, die unter den Nationen sind, Abfall von Moses lehrest und sagest, sie sollen die Kinder nicht beschneiden, noch nach den Gebräuchen wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Was ist es nun? Jedenfalls muß eine Menge zusammenkommen, denn sie werden hören, daß du gekommen bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Tue nun dieses, was wir dir sagen: Wir haben vier Männer, die ein Gelübde auf sich haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Diese nimm zu dir und reinige dich mit ihnen und trage die Kosten für sie, damit sie das Haupt scheren lassen; und alle werden erkennen, daß nichts an dem ist, was ihnen über dich berichtet worden, sondern daß du selbst auch in der Beobachtung des Gesetzes wandelst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Was aber die Gläubigen aus den Nationen betrifft, so haben wir geschrieben und verfügt, daß sie nichts dergleichen halten sollten, als nur daß sie sich sowohl vor dem Götzenopfer als auch vor Blut und Ersticktem und Hurerei bewahrten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Dann nahm Paulus die Männer zu sich, und nachdem er sich des folgenden Tages gereinigt hatte, ging er mit ihnen in den Tempel und kündigte die Erfüllung der Tage der Reinigung an, bis für einen jeden aus ihnen das Opfer dargebracht war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Als aber die sieben Tage beinahe vollendet waren, sahen ihn die Juden aus Asien im Tempel und brachten die ganze Volksmenge in Aufregung und legten die Hände an ihn und schrieen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Männer von Israel, helfet! Dies ist der Mensch, der alle allenthalben lehrt wider das Volk und das Gesetz und diese Stätte; und dazu hat er auch Griechen in den Tempel geführt und diese heilige Stätte verunreinigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Denn sie hatten vorher den Trophimus, den Epheser, mit ihm in der Stadt gesehen, von welchem sie meinten, daß Paulus ihn in den Tempel geführt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Und die ganze Stadt kam in Bewegung, und es entstand ein Zusammenlauf des Volkes; und sie ergriffen Paulus und schleppten ihn aus dem Tempel, und alsbald wurden die Türen geschlossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Während sie ihn aber zu töten suchten, kam an den Obersten der Schar die Anzeige, daß ganz Jerusalem in Aufregung sei;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'der nahm sofort Kriegsknechte und Hauptleute mit und lief zu ihnen hinab. Als sie aber den Obersten und die Kriegsknechte sahen, hörten sie auf, den Paulus zu schlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Dann näherte sich der Oberste, ergriff ihn und befahl, ihn mit zwei Ketten zu binden, und erkundigte sich, wer er denn sei und was er getan habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Die einen aber riefen dieses, die anderen jenes in der Volksmenge; da er aber wegen des Tumultes nichts Gewisses erfahren konnte, befahl er, ihn in das Lager zu führen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Als er aber an die Stufen kam, geschah es, daß er wegen der Gewalt des Volkes von den Kriegsknechten getragen wurde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'denn die Menge des Volkes folgte und schrie:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Hinweg mit ihm! Und als Paulus eben in das Lager hineingebracht werden sollte, spricht er zu dem Obersten: Ist es mir erlaubt, dir etwas zu sagen? Er aber sprach: Verstehst du Griechisch?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Du bist also nicht der Ägypter, der vor diesen Tagen eine Empörung gemacht und die viertausend Mann Meuchelmörder in die Wüste hinausgeführt hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Paulus aber sprach: Ich bin ein jüdischer Mann aus Tarsus, Bürger einer nicht unberühmten Stadt in Cilicien; ich bitte dich aber, erlaube mir, zu dem Volke zu reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Als er es aber erlaubt hatte, winkte Paulus, auf den Stufen stehend, dem Volke mit der Hand; nachdem aber eine große Stille eingetreten war, redete er sie in hebräischer Mundart an und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Brüder und Väter, höret jetzt meine Verantwortung an euch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Als sie aber hörten, daß er sie in hebräischer Mundart anredete, beobachteten sie desto mehr Stille.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Und er spricht: Ich bin ein jüdischer Mann, geboren zu Tarsus in Cilicien; aber auferzogen in dieser Stadt zu den Füßen Gamaliels, unterwiesen nach der Strenge des väterlichen Gesetzes, war ich, wie ihr alle heute seid, ein Eiferer für Gott;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'der ich diesen Weg verfolgt habe bis zum Tode, indem ich sowohl Männer als Weiber band und in die Gefängnisse überlieferte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'wie auch der Hohepriester und die ganze Ältestenschaft mir Zeugnis gibt, von denen ich auch Briefe an die Brüder empfing und nach Damaskus reiste, um auch diejenigen, die dort waren, gebunden nach Jerusalem zu führen, auf daß sie gestraft würden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Es geschah mir aber, als ich reiste und Damaskus nahte, daß um Mittag plötzlich aus dem Himmel ein großes Licht mich umstrahlte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Und ich fiel zu Boden und hörte eine Stimme, die zu mir sprach: Saul, Saul, was verfolgst du mich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Ich aber antwortete: Wer bist du, Herr? Und er sprach zu mir: Ich bin Jesus, der Nazaräer, den du verfolgst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Die aber bei mir waren, sahen zwar das Licht und wurden voll Furcht, aber die Stimme dessen, der mit mir redete, hörten sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Ich sprach aber: Was soll ich tun, Herr? Der Herr aber sprach zu mir: Stehe auf und geh nach Damaskus, und daselbst wird dir von allem gesagt werden, was dir zu tun verordnet ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Als ich aber vor der Herrlichkeit jenes Lichtes nicht sehen konnte, wurde ich von denen, die bei mir waren, an der Hand geleitet und kam nach Damaskus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Ein gewisser Ananias aber, ein frommer Mann nach dem Gesetz, der ein gutes Zeugnis hatte von allen daselbst wohnenden Juden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'kam zu mir, trat herzu und sprach zu mir: Bruder Saul, sei sehend! Und zu derselben Stunde schaute ich zu ihm auf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Er aber sprach: Der Gott unserer Väter hat dich zuvor verordnet, seinen Willen zu erkennen und den Gerechten zu sehen und eine Stimme aus seinem Munde zu hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Denn du wirst ihm an alle Menschen ein Zeuge sein von dem, was du gesehen und gehört hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Und nun, was zögerst du? Stehe auf, laß dich taufen und deine Sünden abwaschen, indem du seinen Namen anrufst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Es geschah mir aber, als ich nach Jerusalem zurückgekehrt war und in dem Tempel betete, daß ich in Entzückung geriet und ihn sah,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'der zu mir sprach: Eile und geh schnell aus Jerusalem hinaus, denn sie werden dein Zeugnis über mich nicht annehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Und ich sprach: Herr, sie selbst wissen, daß ich die an dich Glaubenden ins Gefängnis warf und in den Synagogen schlug;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'und als das Blut deines Zeugen Stephanus vergossen wurde, stand auch ich dabei und willigte mit ein und verwahrte die Kleider derer, welche ihn umbrachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Und er sprach zu mir: Gehe hin, denn ich werde dich weit weg zu den Nationen senden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Sie hörten ihm aber zu bis zu diesem Worte und erhoben ihre Stimme und sagten: Hinweg von der Erde mit einem solchen, denn es geziemte sich nicht, daß er am Leben blieb!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Als sie aber schrieen und die Kleider wegschleuderten und Staub in die Luft warfen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'befahl der Oberste, daß er in das Lager gebracht würde, und sagte, man solle ihn mit Geißelhieben ausforschen, auf daß er erführe, um welcher Ursache willen sie also gegen ihn schrieen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Als sie ihn aber mit den Riemen ausspannten, sprach Paulus zu dem Hauptmann, der dastand: Ist es euch erlaubt, einen Menschen, der ein Römer ist, und zwar unverurteilt, zu geißeln?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Als es aber der Hauptmann hörte, ging er hin und meldete dem Obersten und sprach: was hast du vor zu tun? Denn dieser Mensch ist ein Römer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Der Oberste aber kam herzu und sprach zu ihm: Sage mir, bist du ein Römer? Er aber sprach: Ja.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Und der Oberste antwortete: Ich habe um eine große Summe dieses Bürgerrecht erworben. Paulus aber sprach: Ich aber bin sogar darin geboren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Alsbald nun standen von ihm ab, die ihn ausforschen sollten; aber auch der Oberste fürchtete sich, als er erfuhr, daß er ein Römer sei, und weil er ihn gebunden hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Des folgenden Tages aber, da er mit Gewißheit erfahren wollte, weshalb er von den Juden angeklagt sei, machte er ihn los und befahl, daß die Hohenpriester und das ganze Synedrium zusammenkommen sollten; und er führte Paulus hinab und stellte ihn vor sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Paulus aber blickte das Synedrium unverwandt an und sprach: Brüder! Ich habe mit allem guten Gewissen vor Gott gewandelt bis auf diesen Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Der Hohepriester Ananias aber befahl denen, die bei ihm standen, ihn auf den Mund zu schlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Da sprach Paulus zu ihm: Gott wird dich schlagen, du getünchte Wand! Und du, sitzest du da, mich nach dem Gesetz zu richten, und, wider das Gesetz handelnd, befiehlst du mich zu schlagen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Die Dabeistehenden aber sprachen: Schmähst du den Hohenpriester Gottes?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Und Paulus sprach: Ich wußte nicht, Brüder, daß es der Hohepriester ist; denn es steht geschrieben: \"Von dem Obersten deines Volkes sollst du nicht übel reden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Da aber Paulus wußte, daß der eine Teil von den Sadducäern, der andere aber von den Pharisäern war, rief er in dem Synedrium: Brüder, ich bin ein Pharisäer, ein Sohn von Pharisäern; wegen der Hoffnung und Auferstehung der Toten werde ich gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Als er aber dies gesagt hatte, entstand ein Zwiespalt unter den Pharisäern und Sadducäern, und die Menge teilte sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Denn die Sadducäer sagen, es gebe keine Auferstehung, noch Engel, noch Geist; die Pharisäer aber bekennen beides.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Es entstand aber ein großes Geschrei, und die Schriftgelehrten von der Partei der Pharisäer standen auf und stritten und sagten: Wir finden an diesem Menschen nichts Böses; wenn aber ein Geist oder ein Engel zu ihm geredet hat...');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Als aber ein großer Zwiespalt entstand, fürchtete der Oberste, Paulus möchte von ihnen zerrissen werden, und befahl, daß das Kriegsvolk hinabgehe und ihn aus ihrer Mitte wegreiße und in das Lager führe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'In der folgenden Nacht aber stand der Herr bei ihm und sprach: Sei gutes Mutes! Denn wie du von mir in Jerusalem gezeugt hast, so mußt du auch in Rom zeugen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Als es aber Tag geworden war, rotteten sich die Juden zusammen, verfluchten sich und sagten, daß sie weder essen noch trinken würden, bis sie Paulus getötet hätten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Es waren aber mehr als vierzig, die diese Verschwörung gemacht hatten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'welche zu den Hohenpriestern und den Ältesten kamen und sprachen: Wir haben uns mit einem Fluche verflucht, nichts zu genießen, bis wir den Paulus getötet haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Machet ihr nun jetzt mit dem Synedrium dem Obersten Anzeige, damit er ihn zu euch herabführe, als wolltet ihr seine Sache genauer entscheiden; wir aber sind bereit, ehe er nahe kommt, ihn umzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Als aber der Schwestersohn des Paulus von der Nachstellung gehört hatte, kam er hin und ging in das Lager und meldete es dem Paulus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Paulus aber rief einen von den Hauptleuten zu sich und sagte: Führe diesen Jüngling zu dem Obersten, denn er hat ihm etwas zu melden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Der nun nahm ihn zu sich und führte ihn zu dem Obersten und sagt: Der Gefangene Paulus rief mich herzu und bat mich, diesen Jüngling zu dir zu führen, der dir etwas zu sagen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Der Oberste aber nahm ihn bei der Hand und zog sich mit ihm besonders zurück und fragte: Was ist es, das du mir zu melden hast?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Er aber sprach: Die Juden sind übereingekommen, dich zu bitten, daß du morgen den Paulus in das Synedrium hinabbringest, als wollest du etwas Genaueres über ihn erkunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Du nun, laß dich nicht von ihnen überreden, denn mehr als vierzig Männer von ihnen stellen ihm nach, welche sich verflucht haben, weder zu essen noch zu trinken, bis sie ihn umgebracht haben; und jetzt sind sie bereit und erwarten die Zusage von dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Der Oberste nun entließ den Jüngling und befahl ihm: Sage niemand, daß du mir dies angezeigt hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Und als er zwei von den Hauptleuten herzugerufen hatte, sprach er: Machet zweihundert Kriegsknechte bereit, damit sie bis Cäsarea ziehen, und siebzig Reiter und zweihundert Lanzenträger, von der dritten Stunde der Nacht an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Und sie sollten Tiere bereit halten, auf daß sie den Paulus darauf setzten und sicher zu Felix, dem Landpfleger, hinbrächten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Und er schrieb einen Brief folgenden Inhalts:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Klaudius Lysias dem vortrefflichsten Landpfleger Felix seinen Gruß!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Diesen Mann, der von den Juden ergriffen wurde und nahe daran war, von ihnen umgebracht zu werden, habe ich, mit dem Kriegsvolk einschreitend, ihnen entrissen, da ich erfuhr, daß er ein Römer sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Da ich aber die Ursache wissen wollte, weswegen sie ihn anklagten, führte ich ihn in ihr Synedrium hinab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'Da fand ich, daß er wegen Streitfragen ihres Gesetzes angeklagt war, daß aber keine Anklage gegen ihn vorlag, die des Todes oder der Bande wert wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Da mir aber ein Anschlag hinterbracht wurde, der von den Juden wider den Mann im Werke sei, habe ich ihn sofort zu dir gesandt und auch den Klägern befohlen, vor dir zu sagen, was wider ihn vorliegt. Lebe wohl!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Die Kriegsknechte nun nahmen, wie ihnen befohlen war, den Paulus und führten ihn bei der Nacht nach Antipatris.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Des folgenden Tages aber ließen sie die Reiter mit fortziehen und kehrten nach dem Lager zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Und als diese nach Cäsarea gekommen waren, übergaben sie dem Landpfleger den Brief und stellten ihm auch den Paulus dar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Als er es aber gelesen und gefragt hatte, aus welcher Provinz er sei, und erfahren, daß er aus Cilicien sei, sprach er:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Ich werde dich völlig anhören, wenn auch deine Ankläger angekommen sind. Und er befahl, daß er in dem Prätorium des Herodes verwahrt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Nach fünf Tagen aber kam der Hohepriester Ananias mit den Ältesten und einem gewissen Redner Tertullus herab, und sie machten bei dem Landpfleger Anzeige wider Paulus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Als er aber gerufen worden war, begann Tertullus die Anklage und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Da wir großen Frieden durch dich genießen, und da durch deine Fürsorge für diese Nation löbliche Maßregeln getroffen worden sind, so erkennen wir es allewege und allenthalben, vortrefflichster Felix, mit aller Dankbarkeit an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Auf daß ich dich aber nicht länger aufhalte, bitte ich dich, uns in Kürze nach deiner Geneigtheit anzuhören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Denn wir haben diesen Mann als eine Pest befunden und als einen, der unter allen Juden, die auf dem Erdkreis sind, Aufruhr erregt, und als einen Anführer der Sekte der Nazaräer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'welcher auch versucht hat, den Tempel zu entheiligen, den wir auch ergriffen haben und nach unserem Gesetz richten wollten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Lysias aber, der Oberste, kam herzu und führte ihn mit großer Gewalt aus unseren Händen weg,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'indem er seinen Anklägern befahl, zu dir zu kommen; von welchem du selbst, wenn du es untersucht hast, über alles dieses Gewißheit erhalten kannst, dessen wir ihn anklagen. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Aber auch die Juden griffen Paulus mit an und sagten, daß dies sich also verhielte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Paulus aber antwortete, nachdem ihm der Landpfleger zu reden gewinkt hatte: Da ich weiß, daß du seit vielen Jahren Richter über diese Nation bist, so verantworte ich mich über das mich Betreffende getrost,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'indem du erkennen kannst, daß es nicht mehr als zwölf Tage sind, seit ich hinaufging, um in Jerusalem anzubeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Und sie haben mich weder in dem Tempel mit jemand in Unterredung gefunden, noch einen Auflauf der Volksmenge machend, weder in den Synagogen noch in der Stadt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'auch können sie das nicht dartun, worüber sie mich jetzt anklagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Aber dies bekenne ich dir, daß ich nach dem Wege, den sie eine Sekte nennen, also dem Gott meiner Väter diene, indem ich allem glaube, was in dem Gesetz und in den Propheten geschrieben steht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'und die Hoffnung zu Gott habe, welche auch selbst diese annehmen, daß eine Auferstehung sein wird, sowohl der Gerechten als der Ungerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'Darum übe ich mich auch, allezeit ein Gewissen ohne Anstoß zu haben vor Gott und den Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Nach vielen Jahren aber kam ich her, um Almosen für meine Nation und Opfer darzubringen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'wobei sie mich gereinigt im Tempel fanden, weder mit Auflauf noch mit Tumult;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'es waren aber etliche Juden aus Asien, die hier vor dir sein und Klage führen sollten, wenn sie etwas wider mich hätten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Oder laß diese selbst sagen, welches Unrecht sie an mir gefunden haben, als ich vor dem Synedrium stand,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'es sei denn wegen dieses einen Ausrufs, den ich tat, als ich unter ihnen stand: Wegen der Auferstehung der Toten werde ich heute von euch gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Felix aber, der in betreff des Weges genauere Kenntnis hatte, beschied sie auf weiteres und sagte: Wenn Lysias, der Oberste, herabkommt, so will ich eure Sache entscheiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Und er befahl dem Hauptmann, ihn zu verwahren und ihm Erleichterung zu geben und niemand von den Seinigen zu wehren, ihm zu dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Nach etlichen Tagen aber kam Felix mit Drusilla, seinem Weibe, die eine Jüdin war, herbei und ließ den Paulus holen und hörte ihn über den Glauben an Christum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Als er aber über Gerechtigkeit und Enthaltsamkeit und das kommende Gericht redete, wurde Felix mit Furcht erfüllt und antwortete: Für jetzt gehe hin; wenn ich aber gelegene Zeit habe, werde ich dich rufen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Zugleich hoffte er, daß ihm von Paulus Geld gegeben werden würde; deshalb ließ er ihn auch öfter holen und unterhielt sich mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Als aber zwei Jahre verflossen waren, bekam Felix den Porcius Festus zum Nachfolger; und da Felix sich bei den Juden in Gunst setzen wollte, hinterließ er den Paulus gefangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Als nun Festus in die Provinz gekommen war, ging er nach drei Tagen von Cäsaräa hinauf nach Jerusalem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Und die Hohenpriester und die Vornehmsten der Juden machten Anzeige bei ihm wider Paulus und baten ihn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'indem sie es als eine Gunst wider denselben begehrten, daß er ihn nach Jerusalem kommen ließe; indem sie eine Nachstellung bereiteten, ihn unterwegs umzubringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Festus nun antwortete, Paulus werde in Cäsarea behalten, er selbst aber wolle in Kürze abreisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Die Angesehenen unter euch nun, sprach er, mögen mit hinabreisen und, wenn etwas an diesem Manne ist, ihn anklagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Nachdem er aber nicht mehr als acht oder zehn Tage unter ihnen verweilt hatte, ging er nach Cäsarea hinab; und des folgenden Tages setzte er sich auf den Richterstuhl und befahl, Paulus vorzuführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Als er aber angekommen war, stellten sich die von Jerusalem herabgekommenen Juden um ihn her und brachten viele und schwere Beschuldigungen vor, die sie nicht zu beweisen vermochten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'indem Paulus sich verantwortete: Weder gegen das Gesetz der Juden, noch gegen den Tempel, noch gegen den Kaiser habe ich etwas gesündigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Festus aber, der sich bei den Juden in Gunst setzen wollte, antwortete dem Paulus und sagte: Willst du nach Jerusalem hinaufgehen und dort dieserhalb vor mir gerichtet werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Paulus aber sprach: Ich stehe vor dem Richterstuhl des Kaisers, wo ich gerichtet werden muß; den Juden habe ich kein Unrecht getan, wie auch du sehr wohl weißt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Wenn ich nun Unrecht getan und etwas Todeswürdiges begangen habe, so weigere ich mich nicht zu sterben; wenn aber nichts an dem ist, wessen diese mich anklagen, so kann mich niemand ihnen preisgeben. Ich berufe mich auf den Kaiser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Dann besprach sich Festus mit dem Rat und antwortete: Auf den Kaiser hast du dich berufen, zum Kaiser sollst du gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Als aber etliche Tage vergangen waren, kamen der König Agrippa und Bernice nach Cäsarea, den Festus zu begrüßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Als sie aber mehrere Tage daselbst verweilt hatten, legte Festus dem König die Sache des Paulus vor und sprach: Ein gewisser Mann ist von Felix gefangen zurückgelassen worden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'wegen dessen, als ich zu Jerusalem war, die Hohenpriester und die Ältesten der Juden Anzeige machten, indem sie ein Urteil gegen ihn verlangten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'denen ich antwortete: Es ist bei den Römern nicht Sitte, irgend einen Menschen preiszugeben, ehe der Angeklagte seine Ankläger persönlich vor sich habe und Gelegenheit bekommen, sich wegen der Anklage zu verantworten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Als sie nun hierher zusammengekommen waren, setzte ich mich, ohne Aufschub zu machen, tags darauf auf den Richterstuhl und befahl, den Mann vorzuführen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'über welchen, als die Verkläger auftraten, sie keine Beschuldigung von dem vorbrachten, was ich vermutete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Sie hatten aber etliche Streitfragen wider ihn wegen ihres eigenen Gottesdienstes und wegen eines gewissen Jesus, der gestorben ist, von welchem Paulus sagte, er lebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Da ich aber hinsichtlich der Untersuchung wegen dieser Dinge in Verlegenheit war, sagte ich, ob er nach Jerusalem gehen und daselbst wegen dieser Dinge gerichtet werden wolle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Als aber Paulus Berufung einlegte und forderte, daß er auf das Erkenntnis des Augustus behalten würde, befahl ich, ihn zu verwahren, bis ich ihn zum Kaiser senden werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Agrippa aber sprach zu Festus: Ich möchte wohl auch selbst den Menschen hören. Morgen, sagte er, sollst du ihn hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Als nun des folgenden Tages Agrippa und Bernice mit großem Gepränge gekommen und mit den Obersten und den vornehmsten Männern der Stadt in den Verhörsaal eingetreten waren und Festus Befehl gegeben hatte, wurde Paulus vorgeführt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Und Festus spricht: König Agrippa und ihr Männer alle, die ihr mit uns zugegen seid, ihr sehet diesen, um welchen mich die ganze Menge der Juden angegangen hat, sowohl in Jerusalem als auch hier, indem sie gegen ihn schrieen, er dürfe nicht mehr leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Ich aber, da ich fand, daß er nichts Todeswürdiges begangen, dieser selbst aber sich auch auf den Augustus berufen hat, habe beschlossen, ihn zu senden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'über welchen ich nichts Gewisses dem Herrn zu schreiben habe. Deshalb habe ich ihn vor euch geführt und besonders vor dich, König Agrippa, damit ich, wenn die Untersuchung geschehen ist, etwas zu schreiben habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Denn es scheint mir ungereimt, einen Gefangenen zu senden und nicht auch die gegen ihn vorliegenden Beschuldigungen anzuzeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Agrippa aber sprach zu Paulus: Es ist dir erlaubt, für dich selbst zu reden. Da streckte Paulus die Hand aus und verantwortete sich:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Ich schätze mich glücklich, König Agrippa, daß ich über alles, dessen ich von den Juden angeklagt werde, mich heute vor dir verantworten soll;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'besonders weil du von allen Gebräuchen und Streitfragen, die unter den Juden sind, Kenntnis hast; darum bitte ich dich, mich langmütig anzuhören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Meinen Lebenswandel nun von Jugend auf, der von Anfang an unter meiner Nation in Jerusalem gewesen ist, wissen alle Juden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'die mich von der ersten Zeit her kennen (wenn sie es bezeugen wollen), daß ich nach der strengsten Sekte unserer Religion, als Pharisäer, lebte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Und nun stehe ich vor Gericht wegen der Hoffnung auf die von Gott an unsere Väter geschehene Verheißung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'zu welcher unser zwölfstämmiges Volk, unablässig Nacht und Tag Gott dienend, hinzugelangen hofft, wegen welcher Hoffnung, o König, ich von den Juden angeklagt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Warum wird es bei euch für etwas Unglaubliches gehalten, wenn Gott Tote auferweckt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Ich meinte freilich bei mir selbst, gegen den Namen Jesu, des Nazaräers, viel Widriges tun zu müssen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'was ich auch in Jerusalem getan habe; und viele der Heiligen habe ich in Gefängnisse eingeschlossen, nachdem ich von den Hohenpriestern die Gewalt empfangen hatte; und wenn sie umgebracht wurden, so gab ich meine Stimme dazu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Und in allen Synagogen sie oftmals strafend, zwang ich sie zu lästern; und über die Maßen gegen sie rasend, verfolgte ich sie sogar bis in die ausländischen Städte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Und als ich, damit beschäftigt, mit Gewalt und Vollmacht von den Hohenpriestern nach Damaskus reiste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'sah ich mitten am Tage auf dem Wege, o König, vom Himmel her ein Licht, das den Glanz der Sonne übertraf, welches mich und die mit mir reisten umstrahlte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Als wir aber alle zur Erde niedergefallen waren, hörte ich eine Stimme in hebräischer Mundart zu mir sagen: Saul, Saul, was verfolgst du mich? Es ist hart für dich, wider den Stachel auszuschlagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Ich aber sprach: Wer bist du, Herr? Der Herr aber sprach: Ich bin Jesus, den du verfolgst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'aber richte dich auf und stelle dich auf deine Füße; denn hierzu bin ich dir erschienen, dich zu einem Diener und Zeugen zu verordnen, sowohl dessen, was du gesehen hast, als auch worin ich dir erscheinen werde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'indem ich dich herausnehme aus dem Volke und den Nationen, zu welchen ich dich sende,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'ihre Augen aufzutun, auf daß sie sich bekehren von der Finsternis zum Licht und von der Gewalt des Satans zu Gott, auf daß sie Vergebung der Sünden empfangen und ein Erbe unter denen, die durch den Glauben an mich geheiligt sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Daher, König Agrippa, war ich nicht ungehorsam dem himmlischen Gesicht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'sondern verkündigte denen in Damaskus zuerst und Jerusalem und in der ganzen Landschaft von Judäa und den Nationen, Buße zu tun und sich zu Gott zu bekehren, indem sie der Buße würdige Werke vollbrächten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Dieserhalb haben mich die Juden in dem Tempel ergriffen und versucht, mich zu ermorden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Da mir nun der Beistand von Gott zuteil wurde, stehe ich bis zu diesem Tage, bezeugend sowohl Kleinen als Großen, indem ich nichts sage außer dem, was auch die Propheten und Moses geredet haben, daß es geschehen werde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'nämlich, daß der Christus leiden sollte, daß er als Erster durch Totenauferstehung Licht verkündigen sollte, sowohl dem Volke als auch den Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Während er aber dieses zur Verantwortung sagte, spricht Festus mit lauter Stimme: Du rasest, Paulus! Die große Gelehrsamkeit bringt dich zur Raserei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Paulus aber spricht: Ich rase nicht, vortrefflichster Festus, sondern ich rede Worte der Wahrheit und der Besonnenheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Denn der König weiß um diese Dinge, zu welchem ich auch mit Freimütigkeit rede; denn ich bin überzeugt, daß ihm nichts hiervon verborgen ist, denn nicht in einem Winkel ist dies geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Glaubst du, König Agrippa, den Propheten? Ich weiß, daß du glaubst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Agrippa aber sprach zu Paulus: In kurzem überredest du mich, ein Christ zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Paulus aber sprach: Ich wollte zu Gott, daß über kurz oder lang nicht allein du, sondern auch alle, die mich heute hören, solche würden, wie auch ich bin, ausgenommen diese Bande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Und der König stand auf und der Landpfleger und Bernice und die mit ihnen saßen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'Und als sie sich zurückgezogen hatten, redeten sie miteinander und sagten: Dieser Mensch tut nichts, was des Todes oder der Bande wert wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Agrippa aber sprach zu Festus: Dieser Mensch hätte losgelassen werden können, wenn er sich nicht auf den Kaiser berufen hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Als es aber beschlossen war, daß wir nach Italien absegeln sollten, überlieferten sie den Paulus und etliche andere Gefangene einem Hauptmann, mit Namen Julius, von der Schar des Augustus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Als wir aber in ein adramyttisches Schiff gestiegen waren, das im Begriff stand, die Orte längs der Küste Asiens zu befahren, fuhren wir ab; und es war bei uns Aristarchus, ein Macedonier aus Thessalonich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Und des anderen Tages legten wir zu Sidon an. Und Julius behandelte den Paulus sehr wohlwollend und erlaubte ihm, zu den Freunden zu gehen, um ihrer Fürsorge teilhaftig zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Und von da fuhren wir ab und segelten unter Cypern hin, weil die Winde uns entgegen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Und als wir das Meer von Cilicien und Pamphylien durchsegelt hatten, kamen wir nach Myra in Lycien;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'und als der Hauptmann daselbst ein alexandrinisches Schiff fand, das nach Italien segelte, brachte er uns auf dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Als wir aber viele Tage langsam segelten und mit Mühe gen Knidus gekommen waren, segelten wir, da uns der Wind nicht heranließ, unter Kreta hin, gegen Salmone;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'und als wir mit Mühe an ihr dahinfuhren, kamen wir an einen gewissen Ort, Schönhafen genannt, in dessen Nähe die Stadt Lasea war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Da aber viel Zeit verflossen und die Fahrt schon unsicher war, weil auch die Fasten schon vorüber waren, ermahnte Paulus und sprach zu ihnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Männer, ich sehe, daß die Fahrt mit Ungemach und großem Schaden, nicht nur der Ladung und des Schiffes, sondern auch unseres Lebens geschehen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Der Hauptmann aber glaubte dem Steuermann und dem Schiffsherrn mehr als dem von Paulus Gesagten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Da aber der Hafen zum Überwintern ungeeignet war, rieten die meisten dazu, von dort abzufahren, ob sie etwa nach Phönix zu gelangen und dort zu überwintern vermöchten, einem Hafen von Kreta, der gegen Nordost und gegen Südost sieht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Als aber ein Südwind sanft wehte, meinten sie ihren Vorsatz erreicht zu haben, lichteten die Anker und fuhren dicht an Kreta hin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Aber nicht lange danach erhob sich von Kreta her ein Sturmwind, Euroklydon genannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Als aber das Schiff mitfortgerissen wurde und dem Winde nicht zu widerstehen vermochte, gaben wir uns preis und trieben dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Als wir aber unter einer gewissen kleinen Insel, Klauda genannt, hinliefen, vermochten wir kaum des Bootes mächtig zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Dieses zogen sie herauf und bedienten sich der Schutzmittel, indem sie das Schiff umgürteten; und da sie fürchteten, in die Syrte verschlagen zu werden, ließen sie das Takelwerk nieder und trieben also dahin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Indem wir aber sehr vom Sturme litten, machten sie des folgenden Tages einen Auswurf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'und am dritten Tage warfen sie mit eigenen Händen das Schiffsgerät fort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Da aber viele Tage lang weder Sonne noch Sterne schienen und ein nicht geringes Unwetter auf uns lag, war zuletzt alle Hoffnung auf unsere Rettung entschwunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Und als man lange Zeit ohne Speise geblieben war, da stand Paulus in ihrer Mitte auf und sprach: O Männer! Man hätte mir freilich gehorchen und nicht von Kreta abfahren und dieses Ungemach und den Schaden nicht ernten sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Und jetzt ermahne ich euch, gutes Mutes zu sein, denn kein Leben von euch wird verloren gehen, nur das Schiff.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Denn ein Engel des Gottes, dessen ich bin und dem ich diene, stand in dieser Nacht bei mir und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'Fürchte dich nicht, Paulus! Du mußt vor den Kaiser gestellt werden; und siehe, Gott hat dir alle geschenkt, die mit dir fahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Deshalb seid gutes Mutes, ihr Männer! Denn ich vertraue Gott, daß es so sein wird, wie zu mir geredet worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Wir müssen aber auf eine gewisse Insel verschlagen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Als aber die vierzehnte Nacht gekommen war, und wir in dem Adriatischen Meere umhertrieben, meinten gegen Mitternacht die Matrosen, daß sich ihnen ein Land nahe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Und als sie das Senkblei ausgeworfen hatten, fanden sie zwanzig Faden; nachdem sie aber ein wenig weiter gefahren waren und das Senkblei wiederum ausgeworfen hatten, fanden sie fünfzehn Faden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Und indem sie fürchteten, wir möchten etwa auf felsige Orte verschlagen werden, warfen sie vom Hinterteil vier Anker aus und wünschten, daß es Tag würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Als aber die Matrosen aus dem Schiffe zu fliehen suchten und das Boot unter dem Vorwande, als wollten sie vom Vorderteil Anker auswerfen, in das Meer hinabließen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'sprach Paulus zu dem Hauptmann und den Kriegsleuten: Wenn diese nicht im Schiffe bleiben, könnt ihr nicht gerettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Dann hieben die Kriegsleute die Taue des Bootes ab und ließen es hinabfallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Als es aber Tag werden wollte, ermahnte Paulus alle, Speise zu nehmen, und sprach: Heute ist der vierzehnte Tag, daß ihr zuwartend ohne Essen geblieben seid, indem ihr nichts zu euch genommen habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Deshalb ermahne ich euch, Speise zu nehmen, denn dies gehört zu eurer Erhaltung; denn keinem von euch wird ein Haar des Hauptes verloren gehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Und als er dies gesagt und Brot genommen hatte, dankte er Gott vor allen, und als er es gebrochen hatte, begann er zu essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Alle aber, gutes Mutes geworden, nahmen auch selbst Speise zu sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Wir waren aber in dem Schiffe, alle Seelen, zweihundertsechsundsiebzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Als sie sich aber mit Speise gesättigt hatten, erleichterten sie das Schiff, indem sie den Weizen in das Meer warfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Als es aber Tag wurde, erkannten sie das Land nicht; sie bemerkten aber einen gewissen Meerbusen, der einen Strand hatte, auf welchen sie, wenn möglich, das Schiff zu treiben gedachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Und als sie die Anker gekappt hatten, ließen sie sie im Meere und machten zugleich die Bande der Steuerruder los und hißten das Vordersegel vor den Wind und hielten auf den Strand zu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Da sie aber auf eine Landzunge gerieten, ließen sie das Schiff stranden; und das Vorderteil saß fest und blieb unbeweglich, das Hinterteil aber wurde von der Gewalt der Wellen zerschellt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Der Kriegsknechte Rat aber war, daß sie die Gefangenen töten sollten, damit nicht jemand fortschwimmen und entfliehen möchte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Der Hauptmann aber, der den Paulus retten wollte, hinderte sie an ihrem Vorhaben und befahl, daß diejenigen, welche schwimmen könnten, sich zuerst hinabwerfen und an das Land gehen sollten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'und die übrigen teils auf Brettern, teils auf Stücken vom Schiffe. Und also geschah es, daß alle an das Land gerettet wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Und als wir gerettet waren, da erfuhren wir, daß die Insel Melite heiße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Die Eingeborenen aber erzeigten uns eine nicht gewöhnliche Freundlichkeit, denn sie zündeten ein Feuer an und nahmen uns alle zu sich wegen des eingetretenen Regens und wegen der Kälte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Als aber Paulus eine gewisse Menge Reiser zusammenraffte und auf das Feuer legte, kam infolge der Hitze eine Natter heraus und hängte sich an seine Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Als aber die Eingeborenen das Tier an seiner Hand hängen sahen, sagten sie zueinander: Jedenfalls ist dieser Mensch ein Mörder, welchen Dike, obschon er aus dem Meere gerettet ist, nicht leben läßt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Er nun schüttelte das Tier in das Feuer ab und erlitt nichts Schlimmes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Sie aber erwarteten, daß er aufschwellen oder plötzlich tot hinfallen würde. Als sie aber lange warteten und sahen, daß ihm nichts Ungewöhnliches geschah, änderten sie ihre Meinung und sagten, er sei ein Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'In der Umgebung jenes Ortes aber besaß der Erste der Insel, mit Namen Publius, Ländereien; der nahm uns auf und beherbergte uns drei Tage freundlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Es geschah aber, daß der Vater des Publius, von Fieber und Ruhr befallen, daniederlag. Zu dem ging Paulus hinein, und als er gebetet hatte, legte er ihm die Hände auf und heilte ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Als dies aber geschehen war, kamen auch die übrigen auf der Insel, welche Krankheiten hatten, herzu und wurden geheilt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'diese ehrten uns auch mit vielen Ehren, und als wir abfuhren, luden sie uns auf, was uns nötig war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Nach drei Monaten aber fuhren wir ab in einem alexandrinischen Schiffe, das auf der Insel überwintert hatte, mit dem Zeichen der Dioskuren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Und als wir in Syrakus gelandet waren, blieben wir drei Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Von dort fuhren wir herum und kamen nach Rhegium; und da nach einem Tage sich ein Südwind erhob, kamen wir den zweiten Tag nach Puteoli,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'wo wir Brüder fanden und gebeten wurden, sieben Tage bei ihnen zu bleiben; und so kamen wir nach Rom.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Und von dort kamen die Brüder, als sie von uns gehört hatten, uns bis Appii-Forum und Tres-Tabernä entgegen; und als Paulus sie sah, dankte er Gott und faßte Mut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Als wir aber nach Rom kamen, überlieferte der Hauptmann die Gefangenen dem Oberbefehlshaber; aber dem Paulus wurde erlaubt, mit dem Kriegsknechte, der ihn bewachte, für sich zu bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Es geschah aber nach drei Tagen, daß er die, welche die Ersten der Juden waren, zusammenberief. Als sie aber zusammengekommen waren, sprach er zu ihnen: Brüder! Ich, der ich nichts wider das Volk oder die väterlichen Gebräuche getan habe, bin gefangen aus Jerusalem in die Hände der Römer überliefert worden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'welche, nachdem sie mich verhört hatten, mich loslassen wollten, weil keine Ursache des Todes an mir war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Als aber die Juden widersprachen, war ich gezwungen, mich auf den Kaiser zu berufen, nicht als hätte ich wider meine Nation etwas zu klagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Um dieser Ursache willen nun habe ich euch herbeigerufen, euch zu sehen und zu euch zu reden; denn wegen der Hoffnung Israels bin ich mit dieser Kette umgeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Sie aber sprachen zu ihm: Wir haben über dich weder Briefe von Judäa empfangen, noch ist jemand von den Brüdern hergekommen und hat uns über dich etwas Böses berichtet oder gesagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Aber wir begehren von dir zu hören, welche Gesinnung du hast; denn von dieser Sekte ist uns bekannt, daß ihr allenthalben widersprochen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Als sie ihm aber einen Tag bestimmt hatten, kamen mehrere zu ihm in die Herberge, welchen er die Wahrheit auslegte, indem er das Reich Gottes bezeugte und sie zu überzeugen suchte von Jesu, sowohl aus dem Gesetz Moses\' als auch den Propheten, von frühmorgens bis zum Abend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Und etliche wurden überzeugt von dem, was gesagt wurde, andere aber glaubten nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Als sie aber unter sich uneins waren, gingen sie weg, als Paulus ein Wort sprach: Trefflich hat der Heilige Geist durch Jesaias, den Propheten, zu unseren Vätern geredet und gesagt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, '\"Gehe hin zu diesem Volke und sprich: Hörend werdet ihr hören und nicht verstehen, und sehend werdet ihr sehen und nicht wahrnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Denn das Herz dieses Volkes ist dick geworden, und mit den Ohren haben sie schwer gehört, und ihre Augen haben sie geschlossen, damit sie nicht etwa mit den Augen sehen und mit den Ohren hören und mit dem Herzen verstehen und sich bekehren und ich sie heile.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'So sei euch nun kund, daß dieses Heil Gottes den Nationen gesandt ist; sie werden auch hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'Und als er dies gesagt hatte, gingen die Juden weg und hatten viel Wortwechsel unter sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Er aber blieb zwei ganze Jahre in seinem eigenen gemieteten Hause und nahm alle auf, die zu ihm kamen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'indem er das Reich Gottes predigte und die Dinge, welche den Herrn Jesus Christus betreffen, mit aller Freimütigkeit ungehindert lehrte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paulus, Knecht Jesu Christi, berufener Apostel, abgesondert zum Evangelium Gottes');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, '(welches er durch seine Propheten in heiligen Schriften zuvor verheißen hat),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'über seinen Sohn, (der aus dem Samen Davids gekommen ist dem Fleische nach,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'und als Sohn Gottes in Kraft erwiesen dem Geiste der Heiligkeit nach durch Totenauferstehung) Jesum Christum, unseren Herrn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, '(durch welchen wir Gnade und Apostelamt empfangen haben für seinen Namen zum Glaubensgehorsam unter allen Nationen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'unter welchen auch ihr seid, Berufene Jesu Christi) -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'allen Geliebten Gottes, berufenen Heiligen, die in Rom sind: Gnade euch und Friede von Gott, unserem Vater, und dem Herrn Jesus Christus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Aufs erste danke ich meinem Gott durch Jesum Christum euer aller halben, daß euer Glaube verkündigt wird in der ganzen Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Denn Gott ist mein Zeuge, welchem ich diene in meinem Geiste in dem Evangelium seines Sohnes, wie unablässig ich euer erwähne,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'allezeit flehend bei meinen Gebeten, ob ich nun endlich einmal durch den Willen Gottes so glücklich sein möchte, zu euch zu kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Denn mich verlangt sehr, euch zu sehen, auf daß ich euch etwas geistliche Gnadengabe mitteilte, um euch zu befestigen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'daß ist aber, mit euch getröstet zu werden in eurer Mitte, ein jeder durch den Glauben, der in dem anderen ist, sowohl euren als meinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Ich will aber nicht, daß euch unbekannt sei, Brüder, daß ich mir oft vorgesetzt habe, zu euch zu kommen (und bis jetzt verhindert worden bin), auf daß ich auch unter euch einige Frucht haben möchte, gleichwie auch unter den übrigen Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Sowohl Griechen als Barbaren, sowohl Weisen als Unverständigen bin ich ein Schuldner.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Ebenso bin ich, soviel an mir ist, bereitwillig, auch euch, die ihr in Rom seid, das Evangelium zu verkündigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Denn ich schäme mich des Evangeliums nicht, denn es ist Gottes Kraft zum Heil jedem Glaubenden, sowohl dem Juden zuerst als auch dem Griechen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Denn Gottes Gerechtigkeit wird darin geoffenbart aus Glauben zu Glauben, wie geschrieben steht: \"Der Gerechte aber wird aus Glauben leben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Denn es wird geoffenbart Gottes Zorn vom Himmel her über alle Gottlosigkeit und Ungerechtigkeit der Menschen, welche die Wahrheit in Ungerechtigkeit besitzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'weil das von Gott Erkennbare unter ihnen offenbar ist, denn Gott hat es ihnen geoffenbart, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'denn das Unsichtbare von ihm, sowohl seine ewige Kraft als auch seine Göttlichkeit, die von Erschaffung der Welt an in dem Gemachten wahrgenommen werden, wird geschaut, damit sie ohne Entschuldigung seien;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'weil sie, Gott kennend, ihn weder als Gott verherrlichten, noch ihm Dank darbrachten, sondern in ihren Überlegungen in Torheit verfielen, und ihr unverständiges Herz verfinstert wurde:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'indem sie sich für Weise ausgaben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'sind sie zu Narren geworden und haben die Herrlichkeit des unverweslichen Gottes verwandelt in das Gleichnis eines Bildes von einem verweslichen Menschen und von Vögeln und von vierfüßigen und kriechenden Tieren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Darum hat Gott sie auch dahingegeben in den Gelüsten ihrer Herzen in Unreinigkeit, ihre Leiber untereinander zu schänden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'welche die Wahrheit Gottes in die Lüge verwandelt und dem Geschöpf mehr Verehrung und Dienst dargebracht haben als dem Schöpfer, welcher gepriesen ist in Ewigkeit. Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Deswegen hat Gott sie dahingegeben in schändliche Leidenschaften; denn sowohl ihre Weiber haben den natürlichen Gebrauch in den unnatürlichen verwandelt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'als auch gleicherweise die Männer, den natürlichen Gebrauch des Weibes verlassend, in ihrer Wollust zueinander entbrannt sind, indem sie Männer mit Männern Schande trieben und den gebührenden Lohn ihrer Verirrung an sich selbst empfingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Und gleichwie sie es nicht für gut fanden, Gott in Erkenntnis zu haben, hat Gott sie dahingegeben in einen verworfenen Sinn, zu tun, was sich nicht geziemt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'erfüllt mit aller Ungerechtigkeit, Bosheit, Habsucht, Schlechtigkeit; voll von Neid, Mord, Streit, List, Tücke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Ohrenbläser, Verleumder, Gottverhaßte, Gewalttäter, Hochmütige, Prahler, Erfinder böser Dinge, Eltern Ungehorsame,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Unverständige, Treulose, ohne natürliche Liebe, Unbarmherzige;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'die, wiewohl sie Gottes gerechtes Urteil erkennen, daß, die solches tun, des Todes würdig sind, es nicht allein ausüben, sondern auch Wohlgefallen an denen haben, die es tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Deshalb bist du nicht zu entschuldigen, o Mensch, jeder der da richtet; denn worin du den anderen richtest, verdammst du dich selbst; denn du, der du richtest, tust dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Wir wissen aber, daß das Gericht Gottes nach der Wahrheit ist über die, welche solches tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Denkst du aber dies, o Mensch, der du die richtest, die solches tun, und verübst dasselbe, daß du dem Gericht Gottes entfliehen werdest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Oder verachtest du den Reichtum seiner Gütigkeit und Geduld und Langmut, nicht wissend, daß die Güte Gottes dich zur Buße leitet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Nach deiner Störrigkeit und deinem unbußfertigen Herzen aber häufst du dir selbst Zorn auf am Tage des Zorns und der Offenbarung des gerechten Gerichts Gottes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'welcher einem jeden vergelten wird nach seinen Werken:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'denen, die mit Ausharren in gutem Werke Herrlichkeit und Ehre und Unverweslichkeit suchen, ewiges Leben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'denen aber, die streitsüchtig und der Wahrheit ungehorsam sind, der Ungerechtigkeit aber gehorsam, Zorn und Grimm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Drangsal und Angst über jede Seele eines Menschen, der das Böse vollbringt, sowohl des Juden zuerst als auch des Griechen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Herrlichkeit aber und Ehre und Frieden jedem, der das Gute wirkt, sowohl dem Juden zuerst als auch dem Griechen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'denn es ist kein Ansehen der Person bei Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Denn so viele ohne Gesetz gesündigt haben, werden auch ohne Gesetz verloren gehen; und so viele unter Gesetz gesündigt haben, werden durch Gesetz gerichtet werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '(denn nicht die Hörer des Gesetzes sind gerecht vor Gott, sondern die Täter des Gesetzes werden gerechtfertigt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Denn wenn Nationen, die kein Gesetz haben, von Natur die Dinge des Gesetzes ausüben, so sind diese, die kein Gesetz haben, sich selbst ein Gesetz,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'welche das Werk des Gesetzes geschrieben zeigen in ihren Herzen, indem ihr Gewissen mitzeugt und ihre Gedanken sich untereinander anklagen oder auch entschuldigen)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'an dem Tage, da Gott das Verborgene der Menschen richten wird, nach meinem Evangelium, durch Jesum Christum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Wenn du aber ein Jude genannt wirst und dich auf das Gesetz stützest');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'und dich Gottes rühmst, und den Willen kennst und das Vorzüglichere unterscheidest, indem du aus dem Gesetz unterrichtet bist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'und getraust dir, ein Leiter der Blinden zu sein, ein Licht derer, die in Finsternis sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'ein Erzieher der Törichten, ein Lehrer der Unmündigen, der die Form der Erkenntnis und der Wahrheit im Gesetz hat: -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'der du nun einen anderen lehrst, du lehrst dich selbst nicht? Der du predigst, man solle nicht stehlen, du stiehlst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Der du sagst, man solle nicht ehebrechen, du begehst Ehebruch? Der du die Götzenbilder für Greuel hältst, du begehst Tempelraub?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Der du dich des Gesetzes rühmst, du verunehrst Gott durch die Übertretung des Gesetzes?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Denn der Name Gottes wird eurethalben unter den Nationen gelästert, wie geschrieben steht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Denn Beschneidung ist wohl nütze, wenn du das Gesetz tust; wenn du aber ein Gesetzesübertreter bist, so ist deine Beschneidung Vorhaut geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Wenn nun die Vorhaut die Rechte des Gesetzes beobachtet, wird nicht seine Vorhaut für Beschneidung gerechnet werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'und die Vorhaut von Natur, die das Gesetz erfüllt, dich richten, der du mit Buchstaben und Beschneidung ein Gesetzesübertreter bist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Denn nicht der ist ein Jude, der es äußerlich ist, noch ist die äußerliche Beschneidung im Fleische Beschneidung;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'sondern der ist ein Jude, der es innerlich ist, und Beschneidung ist die des Herzens, im Geiste, nicht im Buchstaben; dessen Lob nicht von Menschen, sondern von Gott ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Was ist nun der Vorteil des Juden? Oder was der Nutzen der Beschneidung?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Viel, in jeder Hinsicht. Denn zuerst sind ihnen die Aussprüche Gottes anvertraut worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Was denn? Wenn etliche nicht geglaubt haben, wird etwa ihr Unglaube die Treue Gottes aufheben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Das sei ferne! Gott aber sei wahrhaftig, jeder Mensch aber Lügner, wie geschrieben steht: \"Damit du gerechtfertigt werdest in deinen Worten, und überwindest, wenn du gerichtet wirst\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Wenn aber unsere Ungerechtigkeit Gottes Gerechtigkeit erweist, was wollen wir sagen? Ist Gott etwa ungerecht, der Zorn auferlegt? (Ich rede nach Menschenweise.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Das sei ferne! Wie könnte sonst Gott die Welt richten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Denn wenn die Wahrheit Gottes durch meine Lüge überströmender geworden ist zu seiner Herrlichkeit, warum werde ich auch noch als Sünder gerichtet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Und warum nicht, wie wir gelästert werden, und wie etliche sagen, daß wir sprechen: Laßt uns das Böse tun, damit das Gute komme? deren Gericht gerecht ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Was nun? Haben wir einen Vorzug? Durchaus nicht; denn wir haben sowohl Juden als Griechen zuvor beschuldigt, daß sie alle unter der Sünde seien, wie geschrieben steht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, '\"Da ist kein Gerechter, auch nicht einer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'da ist keiner, der verständig sei; da ist keiner, der Gott suche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Alle sind abgewichen, sie sind allesamt untauglich geworden; da ist keiner, der Gutes tue, da ist auch nicht einer.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, '\"Ihr Schlund ist ein offenes Grab; mit ihren Zungen handelten sie trüglich.\" Otterngift ist unter ihren Lippen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, '\"Ihr Mund ist voll Fluchens und Bitterkeit.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, '\"Ihre Füße sind schnell, Blut zu vergießen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Verwüstung und Elend ist auf ihren Wegen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'und den Weg des Friedens haben sie nicht erkannt.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, '\"Es ist keine Furcht Gottes vor ihren Augen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Wir wissen aber, daß alles, was das Gesetz sagt, es denen sagt, die unter dem Gesetz sind, auf daß jeder Mund verstopft werde und die ganze Welt dem Gericht Gottes verfallen sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Darum, aus Gesetzeswerken wird kein Fleisch vor ihm gerechtfertigt werden; denn durch Gesetz kommt Erkenntnis der Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Jetzt aber ist, ohne Gesetz, Gottes Gerechtigkeit geoffenbart worden, bezeugt durch das Gesetz und die Propheten:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'Gottes Gerechtigkeit aber durch Glauben an Jesum Christum gegen alle und auf alle, die da glauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Denn es ist kein Unterschied, denn alle haben gesündigt und erreichen nicht die Herrlichkeit Gottes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'und werden umsonst gerechtfertigt durch seine Gnade, durch die Erlösung, die in Christo Jesu ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'welchen Gott dargestellt hat zu einem Gnadenstuhl durch den Glauben an sein Blut, zur Erweisung seiner Gerechtigkeit wegen des Hingehenlassens der vorher geschehenen Sünden unter der Nachsicht Gottes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'zur Erweisung seiner Gerechtigkeit in der jetzigen Zeit, daß er gerecht sei und den rechtfertige, der des Glaubens an Jesum ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Wo ist denn der Ruhm? Er ist ausgeschlossen worden. Durch was für ein Gesetz? Der Werke? Nein, sondern durch das Gesetz des Glaubens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Denn wir urteilen, daß ein Mensch durch Glauben gerechtfertigt wird, ohne Gesetzeswerke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Oder ist Gott der Gott der Juden allein? Nicht auch der Nationen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Ja, auch der Nationen, dieweil es ein einiger Gott ist, der die Beschneidung aus Glauben und die Vorhaut durch den Glauben rechtfertigen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Heben wir denn das Gesetz auf durch den Glauben? Das sei ferne! Sondern wir bestätigen das Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Was wollen wir denn sagen, daß Abraham, unser Vater, nach dem Fleische gefunden habe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Denn wenn Abraham aus Werken gerechtfertigt worden ist, so hat er etwas zum Rühmen, aber nicht vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Denn was sagt die Schrift? \"Abraham aber glaubte Gott, und es wurde ihm zur Gerechtigkeit gerechnet.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Dem aber, der wirkt, wird der Lohn nicht nach Gnade zugerechnet, sondern nach Schuldigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Dem aber, der nicht wirkt, sondern an den glaubt, der den Gottlosen rechtfertigt, wird sein Glaube zur Gerechtigkeit gerechnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Gleichwie auch David die Glückseligkeit des Menschen ausspricht, welchem Gott Gerechtigkeit ohne Werke zurechnet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, '\"Glückselig die, deren Gesetzlosigkeiten vergeben und deren Sünden bedeckt sind!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Glückselig der Mann, dem der Herr Sünde nicht zurechnet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Diese Glückseligkeit nun, ruht sie auf der Beschneidung, oder auch auf der Vorhaut? Denn wir sagen, daß der Glaube dem Abraham zur Gerechtigkeit gerechnet worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Wie wurde er ihm denn zugerechnet? Als er in der Beschneidung oder in der Vorhaut war? Nicht in der Beschneidung, sondern in der Vorhaut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Und er empfing das Zeichen der Beschneidung als Siegel der Gerechtigkeit des Glaubens, den er hatte, als er in der Vorhaut war, damit er Vater aller wäre, die in der Vorhaut glauben, damit auch ihnen die Gerechtigkeit zugerechnet würde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'und Vater der Beschneidung, nicht allein derer, die aus der Beschneidung sind, sondern auch derer, die in den Fußstapfen des Glaubens wandeln, den unser Vater Abraham hatte, als er in der Vorhaut war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Denn nicht durch Gesetz ward dem Abraham oder seinem Samen die Verheißung, daß er der Welt Erbe sein sollte, sondern durch Glaubensgerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Denn wenn die vom Gesetz Erben sind, so ist der Glaube zunichte gemacht und die Verheißung aufgehoben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Denn das Gesetz bewirkt Zorn; aber wo kein Gesetz ist, da ist auch keine Übertretung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Darum ist es aus Glauben, auf daß es nach Gnade sei, damit die Verheißung dem ganzen Samen fest sei, nicht allein dem vom Gesetz, sondern auch dem vom Glauben Abrahams, welcher unser aller Vater ist, (wie geschrieben steht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '\"Ich habe dich zum Vater vieler Nationen gesetzt\") vor dem Gott, welchem er glaubte, der die Toten lebendig macht und das Nichtseiende ruft, wie wenn es da wäre;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'der wider Hoffnung auf Hoffnung geglaubt hat, auf daß er ein Vater vieler Nationen würde, nach dem, was gesagt ist: \"Also soll dein Same sein\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Und nicht schwach im Glauben, sah er nicht seinen eigenen, schon erstorbenen Leib an, da er fast hundert Jahre alt war, und das Absterben des Mutterleibes der Sara,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'und zweifelte nicht an der Verheißung Gottes durch Unglauben, sondern wurde gestärkt im Glauben, Gott die Ehre gebend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'und war der vollen Gewißheit, daß er, was er verheißen habe, auch zu tun vermöge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Darum ist es ihm auch zur Gerechtigkeit gerechnet worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Es ist aber nicht allein seinetwegen geschrieben, daß es ihm zugerechnet worden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'sondern auch unsertwegen, denen es zugerechnet werden soll, die wir an den glauben, der Jesum, unseren Herrn, aus den Toten auferweckt hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'welcher unserer Übertretungen wegen dahingegeben und unserer Rechtfertigung wegen auferweckt worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Da wir nun gerechtfertigt worden sind aus Glauben, so haben wir Frieden mit Gott durch unseren Herrn Jesus Christus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'durch welchen wir mittelst des Glaubens auch Zugang haben zu dieser Gnade, in welcher wir stehen, und rühmen uns in der Hoffnung der Herrlichkeit Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Nicht allein aber das, sondern wir rühmen uns auch der Trübsale, da wir wissen, daß die Trübsal Ausharren bewirkt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'das Ausharren aber Erfahrung, die Erfahrung aber Hoffnung; die Hoffnung aber beschämt nicht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'denn die Liebe Gottes ist ausgegossen in unsere Herzen durch den Heiligen Geist, welcher uns gegeben worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Denn Christus ist, da wir noch kraftlos waren, zur bestimmten Zeit für Gottlose gestorben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Denn kaum wird jemand für einen Gerechten sterben; denn für den Gütigen möchte vielleicht jemand zu sterben wagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Gott aber erweist seine Liebe gegen uns darin, daß Christus, da wir noch Sünder waren, für uns gestorben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Vielmehr nun, da wir jetzt durch sein Blut gerechtfertigt sind, werden wir durch ihn gerettet werden vom Zorn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Denn wenn wir, da wir Feinde waren, mit Gott versöhnt wurden durch den Tod seines Sohnes, viel mehr werden wir, da wir versöhnt sind, durch sein Leben gerettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Nicht allein aber das, sondern wir rühmen uns auch Gottes durch unseren Herrn Jesus Christus, durch welchen wir jetzt die Versöhnung empfangen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Darum, gleichwie durch einen Menschen die Sünde in die Welt gekommen, und durch die Sünde der Tod, und also der Tod zu allen Menschen durchgedrungen ist, weil sie alle gesündigt haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, '(denn bis zu dem Gesetz war Sünde in der Welt; Sünde aber wird nicht zugerechnet, wenn kein Gesetz ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Aber der Tod herrschte von Adam bis auf Moses, selbst über die, welche nicht gesündigt hatten in der Gleichheit der Übertretung Adams, der ein Vorbild des Zukünftigen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Ist nicht aber wie die Übertretung also auch die Gnadengabe? Denn wenn durch des Einen Übertretung die Vielen gestorben sind, so ist vielmehr die Gnade Gottes und die Gabe in Gnade, die durch einen Menschen, Jesum Christum, ist, gegen die Vielen überströmend geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Und ist nicht wie durch Einen, der gesündigt hat, so auch die Gabe? Denn das Urteil war von einem zur Verdammnis, die Gnadengabe aber von vielen Übertretungen zur Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Denn wenn durch die Übertretung des Einen der Tod durch den Einen geherrscht hat, so werden vielmehr die, welche die Überschwenglichkeit der Gnade und der Gabe der Gerechtigkeit empfangen, im Leben herrschen durch den Einen, Jesum Christum);');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'also nun, wie es durch eine Übertretung gegen alle Menschen zur Verdammnis gereichte, so auch durch eine Gerechtigkeit gegen alle Menschen zur Rechtfertigung des Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Denn gleichwie durch des einen Menschen Ungehorsam die Vielen in die Stellung von Sündern gesetzt worden sind, so werden auch durch den Gehorsam des Einen die Vielen in die Stellung von Gerechten gesetzt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Das Gesetz aber kam daneben ein, auf daß die Übertretung überströmend würde. Wo aber die Sünde überströmend geworden, ist die Gnade noch überschwenglicher geworden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'auf daß, gleichwie die Sünde geherrscht hat im Tode, also auch die Gnade herrsche durch Gerechtigkeit zu ewigem Leben durch Jesum Christum, unseren Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Was sollen wir nun sagen? Sollten wir in der Sünde verharren, auf daß die Gnade überströme?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Das sei ferne! Wir, die wir der Sünde gestorben sind, wie sollen wir noch in derselben leben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Oder wisset ihr nicht, daß wir, so viele auf Christum Jesum getauft worden, auf seinen Tod getauft worden sind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'So sind wir nun mit ihm begraben worden durch die Taufe auf den Tod, auf daß, gleichwie Christus aus den Toten auferweckt worden ist durch die Herrlichkeit des Vaters, also auch wir in Neuheit des Lebens wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Denn wenn wir mit ihm einsgemacht worden sind in der Gleichheit seines Todes, so werden wir es auch in der seiner Auferstehung sein,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'indem wir dieses wissen, daß unser alter Mensch mitgekreuzigt worden ist, auf daß der Leib der Sünde abgetan sei, daß wir der Sünde nicht mehr dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Denn wer gestorben ist, ist freigesprochen von der Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Wenn wir aber mit Christo gestorben sind, so glauben wir, daß wir auch mit ihm leben werden, da wir wissen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'daß Christus, aus den Toten auferweckt, nicht mehr stirbt; der Tod herrscht nicht mehr über ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Denn was er gestorben ist, ist er ein für allemal der Sünde gestorben; was er aber lebt, lebt er Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Also auch ihr, haltet euch der Sünde für tot, Gott aber lebend in Christo Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'So herrsche denn nicht die Sünde in eurem sterblichen Leibe, um seinen Lüsten zu gehorchen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'stellet auch nicht eure Glieder der Sünde dar zu Werkzeugen der Ungerechtigkeit, sondern stellet euch selbst Gott dar als Lebende aus den Toten, und eure Glieder Gott zu Werkzeugen der Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Denn die Sünde wird nicht über euch herrschen, denn ihr seid nicht unter Gesetz, sondern unter Gnade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Was nun, sollten wir sündigen, weil wir nicht unter Gesetz, sondern unter Gnade sind? Das sei ferne!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Wisset ihr nicht, daß, wem ihr euch darstellet als Sklaven zum Gehorsam, ihr dessen Sklaven seid, dem ihr gehorchet? Entweder der Sünde zum Tode, oder des Gehorsams zur Gerechtigkeit?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Gott aber sei Dank, daß ihr Sklaven der Sünde waret, aber von Herzen gehorsam geworden seid dem Bilde der Lehre, welchem ihr übergeben worden seid!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Freigemacht aber von der Sünde, seid ihr Sklaven der Gerechtigkeit geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Ich rede menschlich, wegen der Schwachheit eures Fleisches. Denn gleichwie ihr eure Glieder dargestellt habt zur Sklaverei der Unreinigkeit und der Gesetzlosigkeit zur Gesetzlosigkeit, also stellet jetzt eure Glieder dar zur Sklaverei der Gerechtigkeit zur Heiligkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Denn als ihr Sklaven der Sünde waret, da waret ihr Freie von der Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Welche Frucht hattet ihr denn damals von den Dingen, deren ihr euch jetzt schämet? Denn das Ende derselben ist der Tod.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Jetzt aber, von der Sünde freigemacht und Gottes Sklaven geworden, habt ihr eure Frucht zur Heiligkeit, als das Ende aber ewiges Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Denn der Lohn der Sünde ist der Tod, die Gnadengabe Gottes aber ewiges Leben in Christo Jesu, unserem Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Oder wisset ihr nicht, Brüder (denn ich rede zu denen, die Gesetz kennen), daß das Gesetz über den Menschen herrscht, solange er lebt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Denn das verheiratete Weib ist durchs Gesetz an den Mann gebunden, solange er lebt; wenn aber der Mann gestorben ist, so ist sie losgemacht von dem Gesetz des Mannes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'So wird sie denn, während der Mann lebt, eine Ehebrecherin geheißen, wenn sie eines anderen Mannes wird; wenn aber der Mann gestorben ist, ist sie frei von dem Gesetz, so daß sie nicht eine Ehebrecherin ist, wenn sie eines anderen Mannes wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Also seid auch ihr, meine Brüder, dem Gesetz getötet worden durch den Leib des Christus, um eines anderen zu werden, des aus den Toten Auferweckten, auf daß wir Gott Frucht brächten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Denn als wir im Fleische waren, wirkten die Leidenschaften der Sünden, die durch das Gesetz sind, in unseren Gliedern, um dem Tode Frucht zu bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Jetzt aber sind wir von dem Gesetz losgemacht, da wir dem gestorben sind, in welchem wir festgehalten wurden, so daß wir dienen in dem Neuen des Geistes und nicht in dem Alten des Buchstabens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Was sollen wir nun sagen? Ist das Gesetz Sünde? Das sei ferne! Aber die Sünde hätte ich nicht erkannt, als nur durch Gesetz. Denn auch von der Lust hätte ich nichts gewußt, wenn nicht das Gesetz gesagt hätte: \"Laß dich nicht gelüsten\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Die Sünde aber, durch das Gebot Anlaß nehmend, bewirkte jede Lust in mir; denn ohne Gesetz ist die Sünde tot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Ich aber lebte einst ohne Gesetz; als aber das Gebot kam, lebte die Sünde auf;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'ich aber starb. Und das Gebot, das zum Leben gegeben, dasselbe erwies sich mir zum Tode.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Denn die Sünde, durch das Gebot Anlaß nehmend, täuschte mich und tötete mich durch dasselbe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'So ist also das Gesetz heilig und das Gebot heilig und gerecht und gut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Gereichte nun das Gute mir zum Tode? Das sei ferne! Sondern die Sünde, auf daß sie als Sünde erschiene, indem sie durch das Gute mir den Tod bewirkte, auf daß die Sünde überaus sündig würde durch das Gebot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Denn wir wissen, daß das Gesetz geistlich ist, ich aber bin fleischlich, unter die Sünde verkauft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'denn was ich vollbringe, erkenne ich nicht; denn nicht, was ich will, das tue ich, sondern was ich hasse, das übe ich aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Wenn ich aber das, was ich nicht will, ausübe, so stimme ich dem Gesetz bei, daß es recht ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Nun aber vollbringe nicht mehr ich dasselbe, sondern die in mir wohnende Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Denn ich weiß, daß in mir, das ist in meinem Fleische, nichts Gutes wohnt; denn das Wollen ist bei mir vorhanden, aber das Vollbringen dessen, was recht ist, finde ich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Denn das Gute, das ich will, übe ich nicht aus, sondern das Böse, das ich nicht will, dieses tue ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Wenn ich aber dieses, was ich nicht will, ausübe, so vollbringe nicht mehr ich dasselbe, sondern die in mir wohnende Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Also finde ich das Gesetz für mich, der ich das Rechte ausüben will, daß das Böse bei mir vorhanden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Denn ich habe Wohlgefallen an dem Gesetz Gottes nach dem inneren Menschen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'aber ich sehe ein anderes Gesetz in meinen Gliedern, das dem Gesetz meines Sinnes widerstreitet und mich in Gefangenschaft bringt unter das Gesetz der Sünde, das in meinen Gliedern ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Ich elender Mensch! Wer wird mich retten von diesem Leibe des Todes? -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Ich danke Gott durch Jesum Christum, unseren Herrn! Also nun diene ich selbst mit dem Sinne Gottes Gesetz, mit dem Fleische aber der Sünde Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Also ist jetzt keine Verdammnis für die, welche in Christo Jesu sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Denn das Gesetz des Geistes des Lebens in Christo Jesu hat mich freigemacht von dem Gesetz der Sünde und des Todes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Denn das dem Gesetz Unmögliche, weil es durch das Fleisch kraftlos war, tat Gott, indem er, seinen eigenen Sohn in Gleichgestalt des Fleisches der Sünde und für die Sünde sendend, die Sünde im Fleische verurteilte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'auf daß das Recht des Gesetzes erfüllt würde in uns, die nicht nach dem Fleische, sondern nach dem Geiste wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Denn die, welche nach dem Fleische sind, sinnen auf das, was des Fleisches ist; die aber, welche nach dem Geiste sind, auf das, was des Geistes ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Denn die Gesinnung des Fleisches ist der Tod, die Gesinnung des Geistes aber Leben und Frieden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'weil die Gesinnung des Fleisches Feindschaft ist gegen Gott, denn sie ist dem Gesetz Gottes nicht untertan, denn sie vermag es auch nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'die aber, welche im Fleische sind, vermögen Gott nicht zu gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Ihr aber seid nicht im Fleische, sondern im Geiste, wenn anders Gottes Geist in euch wohnt. Wenn aber jemand Christi Geist nicht hat, der ist nicht sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Wenn aber Christus in euch ist, so ist der Leib zwar tot der Sünde wegen, der Geist aber Leben der Gerechtigkeit wegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Wenn aber der Geist dessen, der Jesum aus den Toten auferweckt hat, in euch wohnt, so wird er, der Christum aus den Toten auferweckt hat, auch eure sterblichen Leiber lebendig machen wegen seines in euch wohnenden Geistes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'So denn, Brüder, sind wir Schuldner, nicht dem Fleische, um nach dem Fleische zu leben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'denn wenn ihr nach dem Fleische lebet, so werdet ihr sterben, wenn ihr aber durch den Geist die Handlungen des Leibes tötet, so werdet ihr leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Denn so viele durch den Geist Gottes geleitet werden, diese sind Söhne Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Denn ihr habt nicht einen Geist der Knechtschaft empfangen, wiederum zur Furcht, sondern einen Geist der Sohnschaft habt ihr empfangen, in welchem wir rufen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Abba, Vater! Der Geist selbst zeugt mit unserem Geiste, daß wir Kinder Gottes sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Wenn aber Kinder, so auch Erben, Erben Gottes und Miterben Christi, wenn wir anders mitleiden, auf daß wir auch mitverherrlicht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Denn ich halte dafür, daß die Leiden der Jetztzeit nicht wert sind, verglichen zu werden mit der zukünftigen Herrlichkeit, die an uns geoffenbart werden soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Denn das sehnsüchtige Harren der Schöpfung wartet auf die Offenbarung der Söhne Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Denn die Schöpfung ist der Nichtigkeit unterworfen worden (nicht mit Willen, sondern um deswillen, der sie unterworfen hat),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'auf Hoffnung, daß auch selbst die Schöpfung freigemacht werden wird von der Knechtschaft des Verderbnisses zu der Freiheit der Herrlichkeit der Kinder Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Denn wir wissen, daß die ganze Schöpfung zusammen seufzt und zusammen in Geburtswehen liegt bis jetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Nicht allein aber sie, sondern auch wir selbst, die wir die Erstlinge des Geistes haben, auch wir selbst seufzen in uns selbst, erwartend die Sohnschaft: die Erlösung unseres Leibes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Denn in Hoffnung sind wir errettet worden. Eine Hoffnung aber, die gesehen wird, ist keine Hoffnung; denn was einer sieht, was hofft er es auch?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Wenn wir aber das hoffen, was wir nicht sehen, so warten wir mit Ausharren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Desgleichen aber nimmt auch der Geist sich unserer Schwachheit an; denn wir wissen nicht, was wir bitten sollen, wie sich\'s gebührt, aber der Geist selbst verwendet sich für uns in unaussprechliche Seufzern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Der aber die Herzen erforscht, weiß, was der Sinn des Geistes ist, denn er verwendet sich für Heilige Gott gemäß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Wir wissen aber, daß denen, die Gott lieben, alle Dinge zum Guten mitwirken, denen, die nach Vorsatz berufen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Denn welche er zuvorerkannt hat, die hat er auch zuvorbestimmt, dem Bilde seines Sohnes gleichförmig zu sein, damit er der Erstgeborene sei unter vielen Brüdern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Welche er aber zuvorbestimmt hat, diese hat er auch berufen; und welche er berufen hat, diese hat er auch gerechtfertigt; welche er aber gerechtfertigt hat, diese hat er auch verherrlicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Was sollen wir nun hierzu sagen? Wenn Gott für uns ist, wer wider uns?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Er, der doch seines eigenen Sohnes nicht geschont, sondern ihn für uns alle hingegeben hat: wie wird er uns mit ihm nicht auch alles schenken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Wer wird wider Gottes Auserwählte Anklage erheben? Gott ist es, welcher rechtfertigt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'wer ist, der verdamme? Christus ist es, der gestorben, ja noch mehr, der auch auferweckt, der auch zur Rechten Gottes ist, der sich auch für uns verwendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Wer wird uns scheiden von der Liebe Christi? Drangsal oder Angst oder Verfolgung oder Hungersnot oder Blöße oder Gefahr oder Schwert?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Wie geschrieben steht: \"Um deinetwillen werden wir getötet den ganzen Tag; wie Schlachtschafe sind wir gerechnet worden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Aber in diesem allen sind wir mehr als Überwinder durch den, der uns geliebt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Denn ich bin überzeugt, daß weder Tod noch Leben, weder Engel noch Fürstentümer, weder Gegenwärtiges noch Zukünftiges, noch Gewalten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'weder Höhe noch Tiefe, noch irgend ein anderes Geschöpf uns zu scheiden vermögen wird von der Liebe Gottes, die in Christo Jesu ist, unserem Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Ich sage die Wahrheit in Christo, ich lüge nicht, indem mein Gewissen mit mir Zeugnis gibt in dem Heiligen Geiste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'daß ich große Traurigkeit habe und unaufhörlichen Schmerz in meinem Herzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'denn ich selbst, ich habe gewünscht, durch einen Fluch von Christo entfernt zu sein für meine Brüder, meine Verwandten nach dem Fleische;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'welche Israeliten sind, deren die Sohnschaft ist und die Herrlichkeit und die Bündnisse und die Gesetzgebung und der Dienst und die Verheißungen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'deren die Väter sind, und aus welchen, dem Fleische nach, der Christus ist, welcher über allem ist, Gott, gepriesen in Ewigkeit. Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Nicht aber als ob das Wort Gottes hinfällig geworden wäre; denn nicht alle, die aus Israel sind, diese sind Israel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'auch nicht, weil sie Abrahams Same sind, sind alle Kinder, sondern \"in Isaak wird dir ein Same genannt werden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Das ist: Nicht die Kinder des Fleisches, diese sind Kinder Gottes, sondern die Kinder der Verheißung werden als Same gerechnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Denn dieses Wort ist ein Verheißungswort: \"Um diese Zeit will ich kommen, und Sara wird einen Sohn haben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Nicht allein aber das, sondern auch als Rebekka schwanger war von Einem, von Isaak, unserem Vater,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'selbst als die Kinder noch nicht geboren waren und weder Gutes noch Böses getan hatten (auf daß der Vorsatz Gottes nach Auswahl bestände, nicht aus Werken, sondern aus dem Berufenden),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'wurde zu ihr gesagt: \"Der Größere wird dem Kleineren dienen\";');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'wie geschrieben steht: \"Den Jakob habe ich geliebt, aber den Esau habe ich gehaßt.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Was sollen wir nun sagen? Ist etwa Ungerechtigkeit bei Gott? Das sei ferne!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Denn er sagt zu Moses: \"Ich werde begnadigen, wen ich begnadige, und werde mich erbarmen, wessen ich mich erbarme\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Also liegt es nun nicht an dem Wollenden, noch an dem Laufenden, sondern an dem begnadigenden Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Denn die Schrift sagt zum Pharao: \"Eben hierzu habe ich dich erweckt, damit ich meine Macht an dir erzeige, und damit mein Name verkündigt werde auf der ganzen Erde\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'So denn, wen er will, begnadigt er, und wen er will, verhärtet er.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Du wirst nun zu mir sagen: Warum tadelt er noch? Denn wer hat seinem Willen widerstanden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Ja freilich, o Mensch, wer bist du, der du das Wort nimmst wider Gott? Wird etwa das Geformte zu dem Former sagen: Warum hast du mich also gemacht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Oder hat der Töpfer nicht Macht über den Ton, aus derselben Masse ein Gefäß zur Ehre und ein anderes zur Unehre zu machen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Wenn aber Gott, willens, seinen Zorn zu erzeigen und seine Macht kundzutun, mit vieler Langmut ertragen hat die Gefäße des Zornes, die zubereitet sind zum Verderben, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'und auf daß er kundtäte den Reichtum seiner Herrlichkeit an den Gefäßen der Begnadigung, die er zur Herrlichkeit zuvorbereitet hat...?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'Uns, die er auch berufen hat, nicht allein aus den Juden, sondern auch aus den Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Wie er auch in Hosea sagt: \"Ich werde Nicht-mein-Volk mein Volk nennen, und die Nicht-Geliebte Geliebte\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, '\"Und es wird geschehen, an dem Orte, da zu ihnen gesagt wurde: Ihr seid nicht mein Volk, daselbst werden sie Söhne des lebendigen Gottes genannt werden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Jesaias aber ruft über Israel: \"Wäre die Zahl der Söhne Israels wie der Sand des Meeres, nur der Überrest wird errettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Denn er vollendet die Sache und kürzt sie ab in Gerechtigkeit, denn der Herr wird eine abgekürzte Sache tun auf Erden.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Und wie Jesaias zuvorgesagt hat: \"Wenn nicht der Herr Zebaoth uns Samen übriggelassen hätte, so wären wir wie Sodom geworden und Gomorra gleich geworden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Was wollen wir nun sagen? Daß die von den Nationen, die nicht nach Gerechtigkeit strebten, Gerechtigkeit erlangt haben, eine Gerechtigkeit aber, die aus Glauben ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Israel aber, einem Gesetz der Gerechtigkeit nachstrebend, nicht zu diesem Gesetz gelangt ist. Warum?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Weil es nicht aus Glauben, sondern als aus Werken geschah. Sie haben sich gestoßen an dem Stein des Anstoßes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'wie geschrieben steht: \"Siehe, ich lege in Zion einen Stein des Anstoßes und einen Fels des Ärgernisses, und wer an ihn glaubt, wird nicht zu Schanden werden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Brüder! Das Wohlgefallen meines Herzens und mein Flehen für sie zu Gott ist, daß sie errettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Denn ich gebe ihnen Zeugnis, daß sie Eifer für Gott haben, aber nicht nach Erkenntnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Denn da sie Gottes Gerechtigkeit nicht erkannten und ihre eigene Gerechtigkeit aufzurichten trachteten, haben sie sich der Gerechtigkeit Gottes nicht unterworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Denn Christus ist des Gesetzes Ende, jedem Glaubenden zur Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Denn Moses beschreibt die Gerechtigkeit, die aus dem Gesetz ist: \"Der Mensch, der diese Dinge getan hat, wird durch sie leben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Die Gerechtigkeit aus Glauben aber sagt also: Sprich nicht in deinem Herzen: \"Wer wird in den Himmel hinaufsteigen?\" das ist, um Christum herabzuführen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'oder: \"Wer wird in den Abgrund hinabsteigen?\" das ist, um Christum aus den Toten heraufzuführen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'sondern was sagt sie? \"Das Wort ist dir nahe, in deinem Munde und in deinem Herzen\"; das ist das Wort des Glaubens, welches wir predigen, daß,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'wenn du mit deinem Munde Jesum als Herrn bekennen und in deinem Herzen glauben wirst, daß Gott ihn aus den Toten auferweckt hat, du errettet werden wirst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Denn mit dem Herzen wird geglaubt zur Gerechtigkeit, und mit dem Munde wird bekannt zum Heil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Denn die Schrift sagt: \"Jeder, der an ihn glaubt, wird nicht zu Schanden werden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Denn es ist kein Unterschied zwischen Jude und Grieche, denn derselbe Herr von allen ist reich für alle, die ihn anrufen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, '\"denn jeder, der irgend den Namen des Herrn anrufen wird, wird errettet werden\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Wie werden sie nun den anrufen, an welchen sie nicht geglaubt haben? Wie aber werden sie an den glauben, von welchem sie nicht gehört haben? Wie aber werden sie hören ohne einen Prediger?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Wie aber werden sie predigen, wenn sie nicht gesandt sind? Wie geschrieben steht: \"Wie lieblich sind die Füße derer, welche das Evangelium des Friedens verkündigen, welche das Evangelium des Guten verkündigen!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Aber nicht alle haben dem Evangelium gehorcht. Denn Jesaias sagt: \"Herr, wer hat unserer Verkündigung geglaubt?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Also ist der Glaube aus der Verkündigung, die Verkündigung aber durch Gottes Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Aber ich sage: Haben sie etwa nicht gehört? Ja freilich. \"Ihr Schall ist ausgegangen zu der ganzen Erde, und ihre Reden zu den Grenzen des Erdkreises.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Aber ich sage: Hat Israel es etwa nicht erkannt? Zuerst spricht Moses: \"Ich will euch zur Eifersucht reizen über ein Nicht-Volk, über eine unverständige Nation will ich euch erbittern\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Jesaias aber erkühnt sich und spricht: \"Ich bin gefunden worden von denen, die mich nicht suchten, ich bin offenbar geworden denen, die nicht nach mir fragten\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Von Israel aber sagt er: \"Den ganzen Tag habe ich meine Hände ausgestreckt zu einem ungehorsamen und widersprechenden Volke\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Ich sage nun: Hat Gott etwa sein Volk verstoßen? Das sei ferne! Denn auch ich bin ein Israelit aus dem Samen Abrahams, vom Stamme Benjamin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Gott hat sein Volk nicht verstoßen, das er zuvorerkannt hat. Oder wisset ihr nicht, was die Schrift in der Geschichte des Elias sagt? Wie er vor Gott auftritt wider Israel:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '\"Herr, sie haben deine Propheten getötet, deine Altäre niedergerissen, und ich allein bin übriggeblieben, und sie trachten nach meinem Leben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Aber was sagt ihm die göttliche Antwort? \"Ich habe mir übrigbleiben lassen siebentausend Mann, welche dem Baal das Knie nicht gebeugt haben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Also ist nun auch in der jetzigen Zeit ein Überrest nach Wahl der Gnade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Wenn aber durch Gnade, so nicht mehr aus Werken; sonst ist die Gnade nicht mehr Gnade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Was nun? Was Israel sucht, das hat es nicht erlangt; aber die Auserwählten haben es erlangt, die übrigen aber sind verstockt worden, wie geschrieben steht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, '\"Gott hat ihnen einen Geist der Schlafsucht gegeben, Augen, um nicht zu sehen, und Ohren, um nicht zu hören, bis auf den heutigen Tag\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Und David sagt: \"Es werde ihr Tisch ihnen zur Schlinge und zum Fallstrick und zum Anstoß und zur Vergeltung!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Verfinstert seien ihre Augen, um nicht zu sehen, und ihren Rücken beuge allezeit!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Ich sage nun: Sind sie etwa gestrauchelt, auf daß sie fallen sollten? Das sei ferne! Sondern durch ihren Fall ist den Nationen das Heil geworden, um sie zur Eifersucht zu reizen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Wenn aber ihr Fall der Reichtum der Welt ist, und ihr Verlust der Reichtum der Nationen, wieviel mehr ihre Vollzahl!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Denn ich sage euch, den Nationen: Insofern ich nun der Nationen Apostel bin, ehre ich meinen Dienst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'ob ich auf irgend eine Weise sie, die mein Fleisch sind, zur Eifersucht reizen und etliche aus ihnen erretten möge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Denn wenn ihre Verwerfung die Versöhnung der Welt ist, was wird die Annahme anders sein als Leben aus den Toten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Wenn aber der Erstling heilig ist, so auch die Masse; und wenn die Wurzel heilig ist, so auch die Zweige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Wenn aber einige der Zweige ausgebrochen worden sind, und du, der du ein wilder Ölbaum warst, unter sie eingepfropft und der Wurzel und der Fettigkeit des Ölbaumes mitteilhaftig geworden bist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'so rühme dich nicht wider die Zweige. Wenn du dich aber wider sie rühmst du trägst nicht die Wurzel, sondern die Wurzel dich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Du wirst nun sagen: Die Zweige sind ausgebrochen worden, auf daß ich eingepfropft würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Recht; sie sind ausgebrochen worden durch den Unglauben; du aber stehst durch den Glauben. Sei nicht hochmütig, sondern fürchte dich;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'denn wenn Gott der natürlichen Zweige nicht geschont hat, daß er auch deiner etwa nicht schonen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Sieh nun die Güte und die Strenge Gottes: gegen die, welche gefallen sind, Strenge; gegen dich aber Güte Gottes, wenn du an der Güte bleibst; sonst wirst auch du ausgeschnitten werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Und auch jene, wenn sie nicht im Unglauben bleiben, werden eingepfropft werden; denn Gott vermag sie wiederum einzupfropfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Denn wenn du aus dem von Natur wilden Ölbaum ausgeschnitten und wider die Natur in den edlen Ölbaum eingepfropft worden bist, wieviel mehr werden diese, die natürlichen Zweige, in ihren eigenen Ölbaum eingepfropft werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Denn ich will nicht, Brüder, daß euch dieses Geheimnis unbekannt sei, auf daß ihr nicht euch selbst klug dünket: daß Verstockung Israel zum Teil widerfahren ist, bis die Vollzahl der Nationen eingegangen sein wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'und also wird ganz Israel errettet werden, wie geschrieben steht: \"Es wird aus Zion der Erretter kommen, er wird die Gottlosigkeiten von Jakob abwenden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'und dies ist für sie der Bund von mir, wenn ich ihre Sünden wegnehmen werde\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Hinsichtlich des Evangeliums sind sie zwar Feinde, um euretwillen, hinsichtlich der Auswahl aber Geliebte, um der Väter willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Denn die Gnadengaben und die Berufung Gottes sind unbereubar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Denn gleichwie auch ihr einst Gott nicht geglaubt habt, jetzt aber unter die Begnadigung gekommen seid durch den Unglauben dieser,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'also haben auch jetzt diese an eure Begnadigung nicht geglaubt, auf daß auch sie unter die Begnadigung kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Denn Gott hat alle zusammen in den Unglauben eingeschlossen, auf daß er alle begnadige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'O Tiefe des Reichtums, sowohl der Weisheit als auch der Erkenntnis Gottes! Wie unausforschlich sind seine Gerichte und unausspürbar seine Wege!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Denn wer hat des Herrn Sinn erkannt, oder wer ist sein Mitberater gewesen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Oder wer hat ihm zuvorgegeben, und es wird ihm vergolten werden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Denn von ihm und durch ihn und für ihn sind alle Dinge; ihm sei die Herrlichkeit in Ewigkeit! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Ich ermahne euch nun, Brüder, durch die Erbarmungen Gottes, eure Leiber darzustellen als ein lebendiges, heiliges, Gott wohlgefälliges Schlachtopfer, welches euer vernünftiger Dienst ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Und seid nicht gleichförmig dieser Welt, sondern werdet verwandelt durch die Erneuerung eures Sinnes, daß ihr prüfen möget, was der gute und wohlgefällige und vollkommene Wille Gottes ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Denn ich sage durch die Gnade, die mir gegeben worden, jedem, der unter euch ist, nicht höher von sich zu denken, als zu denken sich gebührt, sondern so zu denken, daß er besonnen sei, wie Gott einem jeden das Maß des Glaubens zugeteilt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Denn gleichwie wir in einem Leibe viele Glieder haben, aber die Glieder nicht alle dieselbe Verrichtung haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'also sind wir, die Vielen, ein Leib in Christo, einzeln aber Glieder voneinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Da wir aber verschiedene Gnadengaben haben, nach der uns verliehenen Gnade: es sei Weissagung, so laßt uns weissagen nach dem Maße des Glaubens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'es sei Dienst, so laßt uns bleiben im Dienst; es sei, der da lehrt, in der Lehre;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'es sei, der da ermahnt, in der Ermahnung; der da mitteilt, in Einfalt; der da vorsteht, mit Fleiß; der da Barmherzigkeit übt, mit Freudigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Die Liebe sei ungeheuchelt. Verabscheuet das Böse, haltet fest am Guten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'In der Bruderliebe seid herzlich gegeneinander, in Ehrerbietung einer dem anderen vorangehend;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'im Fleiße nicht säumig, inbrünstig im Geist; dem Herrn dienend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'In Hoffnung freuet euch; in Trübsal harret aus; im Gebet haltet an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'an den Bedürfnissen der Heiligen nehmet teil; nach Gastfreundschaft trachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Segnet, die euch verfolgen; segnet, und fluchet nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Freuet euch mit den sich Freuenden, weinet mit den Weinenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Seid gleichgesinnt gegeneinander; sinnet nicht auf hohe Dinge, sondern haltet euch zu den niedrigen; seid nicht klug bei euch selbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Vergeltet niemand Böses mit Bösem; seid vorsorglich für das, was ehrbar ist vor allen Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Wenn möglich, so viel an euch ist, lebet mit allen Menschen in Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Rächet nicht euch selbst, Geliebte, sondern gebet Raum dem Zorn; denn es steht geschrieben: \"Mein ist die Rache; ich will vergelten, spricht der Herr\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, '\"Wenn nun deinen Feind hungert, so speise ihn; wenn ihn dürstet, so tränke ihn; denn wenn du dieses tust, wirst du feurige Kohlen auf sein Haupt sammeln.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Laß dich nicht von dem Bösen überwinden, sondern überwinde das Böse mit dem Guten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Jede Seele unterwerfe sich den obrigkeitlichen Gewalten; denn es ist keine Obrigkeit, außer von Gott, und diese, welche sind, sind von Gott verordnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Wer sich daher der Obrigkeit widersetzt, widersteht der Anordnung Gottes; die aber widerstehen, werden ein Urteil über sich bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Denn die Regenten sind nicht ein Schrecken für das gute Werk, sondern für das böse. Willst du dich aber vor der Obrigkeit nicht fürchten? So übe das Gute, und du wirst Lob von ihr haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'denn sie ist Gottes Dienerin, dir zum Guten. Wenn du aber das Böse übst, so fürchte dich, denn sie trägt das Schwert nicht umsonst; denn sie ist Gottes Dienerin, eine Rächerin zur Strafe für den, der Böses tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Darum ist es notwendig, untertan zu sein, nicht allein der Strafe wegen, sondern auch des Gewissens wegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Denn dieserhalb entrichtet ihr auch Steuern; denn sie sind Gottes Beamte, die eben hierzu fortwährend beschäftigt sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Gebet allen, was ihnen gebührt: die Steuer, dem die Steuer, den Zoll, dem der Zoll, die Furcht, dem die Furcht, die Ehre, dem die Ehre gebührt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Seid niemand irgend etwas schuldig, als nur einander zu lieben; denn wer den anderen liebt, hat das Gesetz erfüllt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Denn das: \"Du sollst nicht ehebrechen, du sollst nicht töten, du sollst nicht stehlen, laß dich nicht gelüsten\", und wenn es ein anderes Gebot gibt, ist in diesem Worte zusammengefaßt: \"Du sollst deinen Nächsten lieben wie dich selbst\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Die Liebe tut dem Nächsten nichts Böses. So ist nun die Liebe die Summe des Gesetzes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Und dieses noch, da wir die Zeit erkennen, daß die Stunde schon da ist, daß wir aus dem Schlaf aufwachen sollen; denn jetzt ist unsere Errettung näher, als da wir geglaubt haben:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Die Nacht ist weit vorgerückt, und der Tag ist nahe. Laßt uns nun die Werke der Finsternis ablegen und die Waffen des Lichts anziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Laßt uns anständig wandeln wie am Tage; nicht in Schwelgereien und Trinkgelagen, nicht in Unzucht und Ausschweifungen, nicht in Streit und Neid;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'sondern ziehet den Herrn Jesus Christus an, und treibet nicht Vorsorge für das Fleisch zur Erfüllung seiner Lüste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Den Schwachen im Glauben aber nehmet auf, doch nicht zur Entscheidung zweifelhafter Fragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Einer glaubt, er dürfe alles essen; der Schwache aber ißt Gemüse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Wer ißt, verachte den nicht, der nicht ißt; und wer nicht ißt, richte den nicht, der ißt; denn Gott hat ihn aufgenommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Wer bist du, der du den Hausknecht eines anderen richtest? Er steht oder fällt seinem eigenen Herrn. Er wird aber aufrecht gehalten werden, denn der Herr vermag ihn aufrecht zu halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Der eine hält einen Tag vor dem anderen, der andere aber hält jeden Tag gleich. Ein jeder aber sei in seinem eigenen Sinne völlig überzeugt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Wer den Tag achtet, achtet ihn dem Herrn. Und wer ißt, ißt dem Herrn, denn er danksagt Gott; und wer nicht ißt, ißt dem Herrn nicht und danksagt Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Denn keiner von uns lebt sich selbst, und keiner stirbt sich selbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Denn sei es, daß wir leben, wir leben dem Herrn; sei es, daß wir sterben, wir sterben dem Herrn. Sei es nun, daß wir leben, sei es, daß wir sterben, wir sind des Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Denn hierzu ist Christus gestorben und wieder lebendig geworden, auf daß er herrsche sowohl über Tote als über Lebendige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Du aber, was richtest du deinen Bruder? Oder auch du, was verachtest du deinen Bruder? Denn wir werden alle vor den Richterstuhl Gottes gestellt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Denn es steht geschrieben: \"So wahr ich lebe, spricht der Herr, mir soll sich jedes Knie beugen, und jede Zunge soll Gott bekennen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Also wird nun ein jeder von uns für sich selbst Gott Rechenschaft geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Laßt uns nun nicht mehr einander richten, sondern richtet vielmehr dieses: dem Bruder nicht einen Anstoß oder ein Ärgernis zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Ich weiß und bin überzeugt in dem Herrn Jesus, daß nichts an sich selbst gemein ist; nur dem, der etwas für gemein achtet, dem ist es gemein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Denn wenn dein Bruder wegen einer Speise betrübt wird, so wandelst du nicht mehr nach der Liebe. Verdirb nicht mit deiner Speise den, für welchen Christus gestorben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Laßt nun euer Gut nicht verlästert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Denn das Reich Gottes ist nicht Essen und Trinken, sondern Gerechtigkeit und Friede und Freude im Heiligen Geiste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Denn wer in diesem dem Christus dient, ist Gott wohlgefällig und den Menschen bewährt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Also laßt uns nun dem nachstreben, was des Friedens ist, und dem, was zur gegenseitigen Erbauung dient.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Zerstöre nicht einer Speise wegen das Werk Gottes. Alles zwar ist rein, aber es ist böse für den Menschen, der mit Anstoß isset.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Es ist gut, kein Fleisch zu essen, noch Wein zu trinken, noch etwas zu tun, worin dein Bruder sich stößt oder sich ärgert oder schwach ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Hast du Glauben? Habe ihn für dich selbst vor Gott. Glückselig, wer sich selbst nicht richtet in dem, was er gutheißt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Wer aber zweifelt, wenn er isset, ist verurteilt, weil er es nicht aus Glauben tut. Alles aber, was nicht aus Glauben ist, ist Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Wir aber, die Starken, sind schuldig, die Schwachheiten der Schwachen zu tragen und nicht uns selbst zu gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Ein jeder von uns gefalle dem Nächsten zum Guten, zur Erbauung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Denn auch der Christus hat nicht sich selbst gefallen, sondern wie geschrieben steht: \"Die Schmähungen derer, die dich schmähen, sind auf mich gefallen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Denn alles, was zuvor geschrieben ist, ist zu unserer Belehrung geschrieben, auf daß wir durch das Ausharren und durch die Ermunterung der Schriften die Hoffnung haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Der Gott des Ausharrens und der Ermunterung aber gebe euch, gleichgesinnt zu sein untereinander,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'Christo Jesu gemäß, auf daß ihr einmütig mit einem Munde den Gott und Vater unseres Herrn Jesus Christus verherrlichet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Deshalb nehmet einander auf, gleichwie auch der Christus euch aufgenommen hat, zu Gottes Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Denn ich sage, daß Jesus Christus ein Diener der Beschneidung geworden ist um der Wahrheit Gottes willen, um die Verheißungen der Väter zu bestätigen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'auf daß die Nationen aber Gott verherrlichen möchten um der Begnadigung willen, wie geschrieben steht: \"Darum werde ich dich bekennen unter den Nationen und deinem Namen lobsingen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Und wiederum sagt er: \"Seid fröhlich, ihr Nationen, mit seinem Volke!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Und wiederum: \"Lobet den Herrn, alle Nationen, und alle Völker sollen ihn preisen!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Und wiederum sagt Jesaias: \"Es wird sein die Wurzel Isais und der da aufsteht, über die Nationen zu herrschen, auf den werden die Nationen hoffen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Der Gott der Hoffnung aber erfülle euch mit aller Freude und allem Frieden im Glauben, damit ihr überreich seiet in der Hoffnung durch die Kraft des Heiligen Geistes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Ich bin aber, meine Brüder, auch selbst betreffs euer überzeugt, daß auch ihr selbst voll Gütigkeit seid, erfüllt mit aller Erkenntnis und fähig, auch einander zu ermahnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Ich habe aber zum Teil euch freimütiger geschrieben, Brüder, um euch zu erinnern, wegen der Gnade, die mir von Gott gegeben ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'um ein Diener Christi Jesu zu sein für die Nationen, priesterlich dienend an dem Evangelium Gottes, auf daß das Opfer der Nationen angenehm werde, geheiligt durch den Heiligen Geist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Ich habe also etwas zum Rühmen in Christo Jesu in den Dingen, die Gott angehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Denn ich werde nicht wagen, etwas von dem zu reden, was Christus nicht durch mich gewirkt hat zum Gehorsam der Nationen durch Wort und Werk,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'in der Kraft der Zeichen und Wunder, in der Kraft des Geistes Gottes, so daß ich von Jerusalem an und ringsumher bis nach Illyrikum das Evangelium des Christus völlig verkündigt habe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'und mich also beeifere, das Evangelium zu predigen, nicht da, wo Christus genannt worden ist, auf daß ich nicht auf eines anderen Grund baue;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'sondern wie geschrieben steht: \"Denen nicht von ihm verkündigt wurde, die sollen sehen, und die nicht gehört haben, sollen verstehen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Deshalb bin ich auch oftmals verhindert worden, zu euch zu kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Nun aber, da ich nicht mehr Raum habe in diesen Gegenden und großes Verlangen, zu euch zu kommen, seit vielen Jahren, falls ich nach Spanien reise...;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'denn ich hoffe, auf der Durchreise euch zu sehen und von euch dorthin geleitet zu werden, wenn ich euch zuvor etwas genossen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Jetzt aber reise ich nach Jerusalem im Dienste für die Heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Denn es hat Macedonien und Achaja wohlgefallen, eine gewisse Beisteuer zu leisten für die Dürftigen unter den Heiligen, die in Jerusalem sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Es hat ihnen nämlich wohlgefallen, auch sind sie ihre Schuldner. Denn wenn die Nationen ihrer geistlichen Güter teilhaftig geworden sind, so sind sie schuldig, ihnen auch in den leiblichen zu dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Wenn ich dies nun vollbracht und diese Frucht ihnen versiegelt habe, so will ich über euch nach Spanien abreisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Ich weiß aber, daß, wenn ich zu euch komme, ich in der Fülle des Segens Christi kommen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Ich bitte euch aber, Brüder, durch unseren Herrn Jesus Christus und durch die Liebe des Geistes, mit mir zu kämpfen in den Gebeten für mich zu Gott,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'auf daß ich von den Ungläubigen in Judäa errettet werde, und auf daß mein Dienst für Jerusalem den Heiligen angenehm sei;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'auf daß ich durch den Willen Gottes mit Freuden zu euch komme und mich mit euch erquicke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Der Gott des Friedens aber sei mit euch allen! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Ich empfehle euch aber Phöbe, unsere Schwester, welche eine Dienerin der Versammlung in Kenchreä ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'auf daß ihr sie in dem Herrn, der Heiligen würdig, aufnehmet und ihr beistehet, in welcher Sache irgend sie euer bedarf; denn auch sie ist vielen ein Beistand gewesen, auch mir selbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Grüßet Priska und Aquila, meine Mitarbeiter in Christo Jesu,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, '(welche für mein Leben ihren eigenen Hals preisgegeben haben, denen nicht allein ich danke, sondern auch alle Versammlungen der Nationen)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'und die Versammlung in ihrem Hause. Grüßet Epänetus, meinen Geliebten, welcher der Erstling Asiens ist für Christum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Grüßet Maria, die sehr für euch gearbeitet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Grüßet Andronikus und Junias, meine Verwandten und meine Mitgefangenen, welche unter den Aposteln ausgezeichnet sind, die auch vor mir in Christo waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Grüßet Amplias, meinen Geliebten im Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Grüßet Urbanus, unseren Mitarbeiter in Christo, und Stachys, meinen Geliebten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Grüßet Apelles, den Bewährten in Christo. Grüßet die von Aristobulus\' Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Grüßet Herodion, meinen Verwandten. Grüßet die von Narcissus\' Hause, die im Herrn sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Grüßet Tryphäna und Tryphosa, die im Herrn arbeiten. Grüßet Persis, die Geliebte, die viel gearbeitet hat im Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Grüßet Rufus, den Auserwählten im Herrn, und seine und meine Mutter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Grüßet Asynkritus, Phlegon, Hermes, Patrobas, Hermas und die Brüder bei ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Grüßet Philologus und Julias, Nereus und seine Schwester und Olympas und alle Heiligen bei ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Grüßet einander mit heiligem Kuß. Es grüßen euch alle Versammlungen des Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Ich ermahne euch aber, Brüder, daß ihr achthabet auf die, welche Zwiespalt und Ärgernis anrichten, entgegen der Lehre, die ihr gelernt habt, und wendet euch von ihnen ab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Denn solche dienen nicht unserem Herrn Christus, sondern ihrem eigenen Bauche, und durch süße Worte und schöne Reden verführen sie die Herzen der Arglosen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Denn euer Gehorsam ist zu allen hingelangt. Daher freue ich mich eurethalben; ich will aber, daß ihr weise seid zum Guten, aber einfältig zum Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Der Gott des Friedens aber wird in kurzem den Satan unter eure Füße zertreten. Die Gnade unseres Herrn Jesus Christus sei mit euch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Es grüßen euch Timotheus, mein Mitarbeiter, und Lucius und Jason und Sosipater, meine Verwandten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Ich, Tertius, der ich den Brief geschrieben habe, grüße euch im Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Es grüßt euch Gajus, mein und der ganzen Versammlung Wirt. Es grüßen euch Erastus, der Stadtrentmeister, und der Bruder Quartus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Die Gnade unseres Herrn Jesus Christus sei mit euch allen! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Dem aber, der euch zu befestigen vermag nach meinem Evangelium und der Predigt von Jesu Christo, nach der Offenbarung des Geheimnisses, das in den Zeiten der Zeitalter verschwiegen war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'jetzt aber geoffenbart und durch prophetische Schriften, nach Befehl des ewigen Gottes, zum Glaubensgehorsam an alle Nationen kundgetan worden ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'dem allein weisen Gott durch Jesum Christum, ihm sei die Herrlichkeit in Ewigkeit! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paulus, berufener Apostel Jesu Christi durch Gottes Willen, und Sosthenes, der Bruder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'der Versammlung Gottes, die in Korinth ist, den Geheiligten in Christo Jesu, den berufenen Heiligen, samt allen, die an jedem Orte den Namen unseres Herrn Jesus Christus anrufen, sowohl ihres als unseres Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Gnade euch und Friede von Gott, unserem Vater, und dem Herrn Jesus Christus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Ich danke meinem Gott allezeit eurethalben für die Gnade Gottes, die euch gegeben ist in Christo Jesu,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'daß ihr in ihm in allem reich gemacht worden seid, in allem Wort und aller Erkenntnis,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'wie das Zeugnis des Christus unter euch befestigt worden ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'so daß ihr in keiner Gnadengabe Mangel habt, indem ihr die Offenbarung unseres Herrn Jesus Christus erwartet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'welcher euch auch befestigen wird bis ans Ende, daß ihr untadelig seid an dem Tage unseres Herrn Jesus Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Gott ist treu, durch welchen ihr berufen worden seid in die Gemeinschaft seines Sohnes Jesus Christus, unseres Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Ich ermahne euch aber, Brüder, durch den Namen unseres Herrn Jesus Christus, daß ihr alle dasselbe redet und nicht Spaltungen unter euch seien, sondern daß ihr in demselben Sinne und in derselben Meinung völlig zusammengefügt seiet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Denn es ist mir von euch kund geworden, meine Brüder, durch die Hausgenossen der Chloe, daß Streitigkeiten unter euch sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Ich sage aber dieses, daß ein jeder von euch sagt: Ich bin des Paulus, ich aber des Apollos, ich aber des Kephas, ich aber Christi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Ist der Christus zerteilt? Ist etwa Paulus für euch gekreuzigt, oder seid ihr auf Paulus\' Namen getauft worden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Ich danke Gott, daß ich niemand von euch getauft habe, außer Krispus und Gajus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'auf daß nicht jemand sage, daß ich auf meinen Namen getauft habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Ich habe aber auch das Haus des Stephanas getauft; sonst weiß ich nicht, ob ich jemand anders getauft habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Denn Christus hat mich nicht ausgesandt zu taufen, sondern das Evangelium zu verkündigen; nicht in Redeweisheit, auf daß nicht das Kreuz Christi zunichte gemacht werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Denn das Wort vom Kreuz ist denen, die verloren gehen, Torheit; uns aber, die wir errettet werden, ist es Gottes Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Denn es steht geschrieben: \"Ich will die Weisheit der Weisen vernichten, und den Verstand der Verständigen will ich hinwegtun\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Wo ist der Weise? Wo der Schriftgelehrte? Wo der Schulstreiter dieses Zeitlaufs? Hat nicht Gott die Weisheit der Welt zur Torheit gemacht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Denn weil ja in der Weisheit Gottes die Welt durch die Weisheit Gott nicht erkannte, so gefiel es Gott wohl, durch die Torheit der Predigt die Glaubenden zu erretten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'weil ja sowohl Juden Zeichen fordern, als auch Griechen Weisheit suchen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'wir aber predigen Christum als gekreuzigt, den Juden ein Ärgernis, und den Nationen eine Torheit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'den Berufenen selbst aber, sowohl Juden als Griechen, Christum, Gottes Kraft und Gottes Weisheit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'denn das Törichte Gottes ist weiser als die Menschen, und das Schwache Gottes ist stärker als die Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Denn sehet eure Berufung, Brüder, daß es nicht viele Weise nach dem Fleische, nicht viele Mächtige, nicht viele Edle sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'sondern das Törichte der Welt hat Gott auserwählt, auf daß er die Weisen zu Schanden mache; und das Schwache der Welt hat Gott auserwählt, auf daß er das Starke zu Schanden mache;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'und das Unedle der Welt und das Verachtete hat Gott auserwählt, und das, was nicht ist, auf daß er das, was ist, zunichte mache,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'damit sich vor Gott kein Fleisch rühme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Aus ihm aber seid ihr in Christo Jesu, der uns geworden ist Weisheit von Gott und Gerechtigkeit und Heiligkeit und Erlösung;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'auf daß, wie geschrieben steht: \"Wer sich rühmt, der rühme sich des Herrn\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Und ich, als ich zu euch kam, Brüder, kam nicht nach Vortrefflichkeit der Rede oder Weisheit, euch das Zeugnis Gottes verkündigend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Denn ich hielt nicht dafür, etwas unter euch zu wissen, als nur Jesum Christum und ihn als gekreuzigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Und ich war bei euch in Schwachheit und in Furcht und in vielem Zittern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'und meine Rede und meine Predigt war nicht in überredenden Worten der Weisheit, sondern in Erweisung des Geistes und der Kraft,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'auf daß euer Glaube nicht beruhe auf Menschenweisheit, sondern auf Gotteskraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Wir reden aber Weisheit unter den Vollkommenen, nicht aber Weisheit dieses Zeitlaufs, noch der Fürsten dieses Zeitlaufs, die zunichte werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'sondern wir reden Gottes Weisheit in einem Geheimnis, die verborgene, welche Gott zuvorbestimmt hat, vor den Zeitaltern, zu unserer Herrlichkeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'welche keiner von den Fürsten dieses Zeitlaufs erkannt hat (denn wenn sie dieselbe erkannt hätten, so würden sie wohl den Herrn der Herrlichkeit nicht gekreuzigt haben), sondern wie geschrieben steht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, '\"Was kein Auge gesehen und kein Ohr gehört hat und in keines Menschen Herz gekommen ist, was Gott bereitet hat denen, die ihn lieben\";');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'uns aber hat Gott es geoffenbart durch seinen Geist, denn der Geist erforscht alles, auch die Tiefen Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Denn wer von den Menschen weiß, was im Menschen ist, als nur der Geist des Menschen, der in ihm ist? Also weiß auch niemand, was in Gott ist, als nur der Geist Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Wir aber haben nicht den Geist der Welt empfangen, sondern den Geist, der aus Gott ist, auf daß wir die Dinge kennen, die uns von Gott geschenkt sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'welche wir auch verkündigen, nicht in Worten, gelehrt durch menschliche Weisheit, sondern in Worten, gelehrt durch den Geist, mitteilend geistliche Dinge durch geistliche Mittel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Der natürliche Mensch aber nimmt nicht an, was des Geistes Gottes ist, denn es ist ihm eine Torheit, und er kann es nicht erkennen, weil es geistlich beurteilt wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'der geistliche aber beurteilt alles, er selbst aber wird von niemand beurteilt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'denn \"wer hat den Sinn des Herrn erkannt, der ihn unterweise?\" Wir aber haben Christi Sinn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Und ich, Brüder, konnte nicht zu euch reden als zu Geistlichen, sondern als zu Fleischlichen, als zu Unmündigen in Christo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Ich habe euch Milch zu trinken gegeben, nicht Speise; denn ihr vermochtet es noch nicht; aber ihr vermöget es auch jetzt noch nicht, denn ihr seid noch fleischlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Denn da Neid und Streit unter euch ist, seid ihr nicht fleischlich und wandelt nach Menschenweise?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Denn wenn einer sagt: Ich bin des Paulus; der andere aber: Ich des Apollos; seid ihr nicht menschlich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Wer ist denn Apollos, und wer Paulus? Diener, durch welche ihr geglaubt habt, und zwar wie der Herr einem jeden gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Ich habe gepflanzt, Apollos hat begossen, Gott aber hat das Wachstum gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Also ist weder der da pflanzt etwas, noch der da begießt, sondern Gott, der das Wachstum gibt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Der aber pflanzt und der begießt, sind eins; ein jeder aber wird seinen eigenen Lohn empfangen nach seiner eigenen Arbeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Denn wir sind Gottes Mitarbeiter; Gottes Ackerfeld, Gottes Bau seid ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Nach der Gnade Gottes, die mir gegeben ist, habe ich als ein weiser Baumeister den Grund gelegt; ein anderer aber baut darauf; ein jeder aber sehe zu, wie er darauf baut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Denn einen anderen Grund kann niemand legen, außer dem, der gelegt ist, welcher ist Jesus Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Wenn aber jemand auf diesen Grund baut Gold, Silber, köstliche Steine, Holz, Heu, Stroh,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'so wird das Werk eines jeden offenbar werden, denn der Tag wird es klar machen, weil er in Feuer geoffenbart wird; und welcherlei das Werk eines jeden ist, wird das Feuer bewähren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Wenn das Werk jemandes bleiben wird, das er darauf gebaut hat, so wird er Lohn empfangen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'wenn das Werk jemandes verbrennen wird, so wird er Schaden leiden, er selbst aber wird gerettet werden, doch so wie durchs Feuer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Wisset ihr nicht, daß ihr Gottes Tempel seid und der Geist Gottes in euch wohnt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Wenn jemand den Tempel Gottes verdirbt, den wird Gott verderben; denn der Tempel Gottes ist heilig, und solche seid ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Niemand betrüge sich selbst. Wenn jemand unter euch sich dünkt, weise zu sein in diesem Zeitlauf, so werde er töricht, auf daß er weise werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Denn die Weisheit dieser Welt ist Torheit bei Gott; denn es steht geschrieben: \"Der die Weisen erhascht in ihrer List\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'Und wiederum: \"Der Herr kennt die Überlegungen der Weisen, daß sie eitel sind\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'So rühme sich denn niemand der Menschen, denn alles ist euer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Es sei Paulus oder Apollos oder Kephas, es sei Welt oder Leben oder Tod, es sei Gegenwärtiges oder Zukünftiges:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'alles ist euer, ihr aber seid Christi, Christus aber ist Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Dafür halte man uns: für Diener Christi und Verwalter der Geheimnisse Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Übrigens sucht man hier an den Verwaltern, daß einer treu erfunden werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Mir aber ist es das Geringste, daß ich von euch oder von einem menschlichen Tage beurteilt werde; ich beurteile mich aber auch selbst nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Denn ich bin mir selbst nichts bewußt, aber dadurch bin ich nicht gerechtfertigt. Der mich aber beurteilt, ist der Herr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'So urteilet nicht etwas vor der Zeit, bis der Herr kommt, welcher auch das Verborgene der Finsternis ans Licht bringen und die Ratschläge der Herzen offenbaren wird; und dann wird einem jeden sein Lob werden von Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Dies aber, Brüder, habe ich auf mich und Apollos gedeutet um euretwillen, auf daß ihr an uns lernet, nicht über das hinaus zu denken, was geschrieben ist, auf daß ihr euch nicht aufblähet für den einen, wider den anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Denn wer unterscheidet dich? Was aber hast du, das du nicht empfangen hast? Wenn du es aber auch empfangen hast, was rühmst du dich, als hättest du es nicht empfangen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Schon seid ihr gesättigt, schon seid ihr reich geworden; ihr habt ohne uns geherrscht, und ich wollte wohl, daß ihr herrschtet, auf daß auch wir mit euch herrschen möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Denn mich dünkt, daß Gott uns, die Apostel, als die Letzten dargestellt hat, wie zum Tode bestimmt; denn wir sind der Welt ein Schauspiel geworden, sowohl Engeln als Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Wir sind Narren um Christi willen, ihr aber seid klug in Christo; wir schwach, ihr aber stark; ihr herrlich, wir aber verachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Bis auf die jetzige Stunde leiden wir sowohl Hunger als Durst und sind nackt und werden mit Fäusten geschlagen und haben keine bestimmte Wohnung und mühen uns ab,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'mit unseren eigenen Händen arbeitend. Geschmäht, segnen wir; verfolgt, dulden wir;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'gelästert, bitten wir; als Auskehricht der Welt sind wir geworden, ein Auswurf aller bis jetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Nicht euch zu beschämen schreibe ich dieses, sondern ich ermahne euch als meine geliebten Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Denn wenn ihr zehntausend Zuchtmeister in Christo hättet, so doch nicht viele Väter; denn in Christo Jesu habe ich euch gezeugt durch das Evangelium.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Ich bitte euch nun, seid meine Nachahmer!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Dieserhalb habe ich euch Timotheus gesandt, der mein geliebtes und treues Kind ist in dem Herrn; der wird euch erinnern an meine Wege, die in Christo sind, gleichwie ich überall in jeder Versammlung lehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Etliche aber sind aufgeblasen, als ob ich nicht zu euch kommen würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Ich werde aber bald zu euch kommen, wenn der Herr will, und werde erkennen, nicht das Wort der Aufgeblasenen, sondern die Kraft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'denn das Reich Gottes besteht nicht im Worte, sondern in Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Was wollt ihr? Soll ich mit der Rute zu euch kommen, oder in Liebe und im Geiste der Sanftmut?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Überhaupt hört man, daß Hurerei unter euch sei, und eine solche Hurerei, die selbst unter den Nationen nicht stattfindet: daß einer seines Vaters Weib habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Und ihr seid aufgeblasen und habt nicht vielmehr Leid getragen, auf daß der, welcher diese Tat begangen hat, aus eurer Mitte hinweggetan würde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Denn ich, zwar dem Leibe nach abwesend, aber im Geiste gegenwärtig, habe schon als gegenwärtig geurteilt, den, der dieses also verübt hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'im Namen unseres Herrn Jesus Christus (wenn ihr und mein Geist mit der Kraft unseres Herrn Jesus Christus versammelt seid)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'einen solchen dem Satan zu überliefern zum Verderben des Fleisches, auf daß der Geist errettet werde am Tage des Herrn Jesus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Euer Rühmen ist nicht gut. Wisset ihr nicht, daß ein wenig Sauerteig die ganze Masse durchsäuert?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Feget den alten Sauerteig aus, auf daß ihr eine neue Masse sein möget, gleichwie ihr ungesäuert seid. Denn auch unser Passah, Christus, ist geschlachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Darum laßt uns Festfeier halten, nicht mit altem Sauerteig, auch nicht mit Sauerteig der Bosheit und Schlechtigkeit, sondern mit Ungesäuertem der Lauterkeit und Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Ich habe euch in dem Briefe geschrieben, nicht mit Hurern Umgang zu haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'nicht durchaus mit den Hurern dieser Welt oder den Habsüchtigen und Räubern oder Götzendienern, sonst müßtet ihr ja aus der Welt hinausgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Nun aber habe ich euch geschrieben, keinen Umgang zu haben, wenn jemand, der Bruder genannt wird, ein Hurer ist, oder ein Habsüchtiger oder ein Götzendiener oder ein Schmäher oder ein Trunkenbold oder ein Räuber, mit einem solchen selbst nicht zu essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Denn was habe ich auch zu richten, die draußen sind? Ihr, richtet ihr nicht, die drinnen sind?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Die aber draußen sind, richtet Gott; tut den Bösen von euch selbst hinaus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Darf jemand unter euch, der eine Sache wider den anderen hat, rechten vor den Ungerechten und nicht vor den Heiligen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Oder wisset ihr nicht, daß die Heiligen die Welt richten werden? Und wenn durch euch die Welt gerichtet wird, seid ihr unwürdig, über die geringsten Dinge zu richten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Wisset ihr nicht, daß wir Engel richten werden? geschweige denn Dinge dieses Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Wenn ihr nun über Dinge dieses Lebens zu richten habt, so setzet diese dazu, die gering geachtet sind in der Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Zur Beschämung sage ich\'s euch. Also nicht ein Weiser ist unter euch, auch nicht einer, der zwischen seinen Brüdern zu entscheiden vermag?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'sondern es rechtet Bruder mit Bruder, und das vor Ungläubigen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Es ist nun schon überhaupt ein Fehler an euch, daß ihr Rechtshändel miteinander habt. Warum laßt ihr euch nicht lieber unrecht tun? Warum laßt ihr euch nicht lieber übervorteilen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Aber ihr tut unrecht und übervorteilt, und das Brüder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Oder wisset ihr nicht, daß Ungerechte das Reich Gottes nicht ererben werden? Irret euch nicht! Weder Hurer, noch Götzendiener, noch Ehebrecher, noch Weichlinge, noch Knabenschänder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'noch Diebe, noch Habsüchtige, noch Trunkenbolde, noch Schmäher, noch Räuber werden das Reich Gottes ererben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Und solches sind euer etliche gewesen; aber ihr seid abgewaschen, aber ihr seid geheiligt, aber ihr seid gerechtfertigt worden in dem Namen des Herrn Jesus und durch den Geist unseres Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Alles ist mir erlaubt, aber nicht alles ist nützlich. Alles ist mir erlaubt, aber ich will mich von keinem überwältigen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Die Speisen für den Bauch, und der Bauch für die Speisen; Gott aber wird sowohl diesen als jene zunichte machen. Der Leib aber nicht für die Hurerei, sondern für den Herrn, und der Herr für den Leib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Gott aber hat sowohl den Herrn auferweckt, als er auch uns auferwecken wird durch seine Macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Wisset ihr nicht, daß eure Leiber Glieder Christi sind? Soll ich denn die Glieder Christi nehmen und zu Gliedern einer Hure machen? Das sei ferne!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Oder wisset ihr nicht, daß, wer der Hure anhängt, ein Leib mit ihr ist? \"Denn es werden\", spricht er, \"die zwei ein Fleisch sein.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Wer aber dem Herrn anhängt, ist ein Geist mit ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Fliehet die Hurerei! Jede Sünde, die ein Mensch begehen mag, ist außerhalb des Leibes; wer aber hurt, sündigt wider seinen eigenen Leib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Oder wisset ihr nicht, daß euer Leib der Tempel des Heiligen Geistes ist, der in euch wohnt, den ihr von Gott habt, und daß ihr nicht euer selbst seid?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Denn ihr seid um einen Preis erkauft worden; verherrlichet nun Gott in eurem Leibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Was aber das betrifft, wovon ihr mir geschrieben habt, so ist es gut für einen Menschen, kein Weib zu berühren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Aber um der Hurerei willen habe ein jeder sein eigenes Weib, und eine jede habe ihren eigenen Mann.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Der Mann leiste dem Weibe die eheliche Pflicht, gleicherweise aber auch das Weib dem Manne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Das Weib hat nicht Macht über ihren eigenen Leib, sondern der Mann; gleicherweise aber hat auch der Mann nicht Macht über seinen eigenen Leib, sondern das Weib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Entziehet euch einander nicht, es sei denn etwa nach Übereinkunft eine Zeitlang, auf daß ihr zum Beten Muße habet; und kommet wieder zusammen, auf daß der Satan euch nicht versuche wegen eurer Unenthaltsamkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Dieses aber sage ich aus Nachsicht, nicht befehlsweise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Ich wünsche aber, alle Menschen wären wie auch ich selbst; aber ein jeder hat seine eigene Gnadengabe von Gott, der eine so, der andere so.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Ich sage aber den Unverheirateten und den Witwen: Es ist gut für sie, wenn sie bleiben wie auch ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Wenn sie sich aber nicht enthalten können, so laßt sie heiraten, denn es ist besser zu heiraten, als Brunst zu leiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Den Verheirateten aber gebiete nicht ich, sondern der Herr, daß ein Weib nicht vom Manne geschieden werde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, '(wenn sie aber auch geschieden ist, so bleibe sie unverheiratet, oder versöhne sich mit dem Manne) und daß ein Mann sein Weib nicht entlasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Den übrigen aber sage ich, nicht der Herr: Wenn ein Bruder ein ungläubiges Weib hat, und sie willigt ein, bei ihm zu wohnen, so entlasse er sie nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Und ein Weib, das einen ungläubigen Mann hat, und er willigt ein, bei ihr zu wohnen, so entlasse sie den Mann nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Denn der ungläubige Mann ist geheiligt durch das Weib, und das ungläubige Weib ist geheiligt durch den Bruder; sonst wären ja eure Kinder unrein, nun aber sind sie heilig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Wenn aber der Ungläubige sich trennt, so trenne er sich. Der Bruder oder die Schwester ist in solchen Fällen nicht gebunden; in Frieden aber hat uns Gott berufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Denn was weißt du, Weib, ob du den Mann erretten wirst? Oder was weißt du, Mann, ob du das Weib erretten wirst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Doch wie der Herr einem jeden ausgeteilt hat, wie Gott einen jeden berufen hat, also wandle er; und also verordne ich in allen Versammlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Ist jemand beschnitten berufen worden, so ziehe er keine Vorhaut; ist jemand in der Vorhaut berufen worden, so werde er nicht beschnitten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Die Beschneidung ist nichts, und die Vorhaut ist nichts, sondern das Halten der Gebote Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Ein jeder bleibe in dem Beruf, in welchem er berufen worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Bist du als Sklave berufen worden, so laß es dich nicht kümmern; wenn du aber auch frei werden kannst, so benutze es vielmehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Denn der als Sklave im Herrn Berufene ist ein Freigelassener des Herrn; gleicherweise auch ist der als Freier Berufene ein Sklave Christi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Ihr seid um einen Preis erkauft; werdet nicht der Menschen Sklaven.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Ein jeder, worin er berufen worden ist, Brüder, darin bleibe er bei Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Was aber die Jungfrauen betrifft, so habe ich kein Gebot des Herrn; ich gebe aber eine Meinung, als vom Herrn begnadigt worden, treu zu sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Ich meine nun, daß dies gut sei um der gegenwärtigen Not willen, daß es einem Menschen gut sei, also zu sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Bist du an ein Weib gebunden, so suche nicht los zu werden; bist du frei von einem Weibe, so suche kein Weib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Wenn du aber auch heiratest, so hast du nicht gesündigt; und wenn die Jungfrau heiratet, so hat sie nicht gesündigt; aber solche werden Trübsal im Fleische haben; ich aber schone euer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Dieses aber sage ich, Brüder: Die Zeit ist gedrängt. Übrigens daß auch die, welche Weiber haben, seien, als hätten sie keine,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'und die Weinenden als nicht Weinende, und die sich Freuenden als sich nicht Freuende, und die Kaufenden als nicht Besitzende,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'und die der Welt Gebrauchenden als ihrer nicht als Eigentum Gebrauchende; denn die Gestalt dieser Welt vergeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Ich will aber, daß ihr ohne Sorge seid. Der Unverheiratete ist für die Dinge des Herrn besorgt, wie er dem Herrn gefallen möge;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'der Verheiratete aber ist für die Dinge der Welt besorgt, wie er dem Weibe gefallen möge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Es ist ein Unterschied zwischen dem Weibe und der Jungfrau. Die Unverheiratete ist für die Dinge des Herrn besorgt, auf daß sie heilig sei, sowohl an Leib als Geist; die Verheiratete aber ist für die Dinge der Welt besorgt, wie sie dem Manne gefallen möge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Dies aber sage ich zu eurem eigenen Nutzen, nicht auf daß ich euch eine Schlinge überwerfe, sondern zur Wohlanständigkeit und zu ungeteiltem Anhangen an dem Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Wenn aber jemand denkt, er handle ungeziemend mit seiner Jungfrauschaft, wenn er über die Jahre der Blüte hinausgeht, und es muß also geschehen, so tue er, was er will; er sündigt nicht: sie mögen heiraten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Wer aber im Herzen feststeht und keine Not, sondern Gewalt hat über seinen eigenen Willen und dies in seinem Herzen beschlossen hat, seine Jungfrauschaft zu bewahren, der tut wohl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Also, wer heiratet, tut wohl, und wer nicht heiratet, tut besser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Ein Weib ist gebunden, so lange Zeit ihr Mann lebt; wenn aber der Mann entschlafen ist, so ist sie frei, sich zu verheiraten, an wen sie will, nur im Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Glückseliger ist sie aber, wenn sie also bleibt, nach meiner Meinung; ich denke aber, daß auch ich Gottes Geist habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Was aber die Götzenopfer betrifft, so wissen wir (denn wir alle haben Erkenntnis; die Erkenntnis bläht auf, die Liebe aber erbaut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Wenn jemand sich dünkt, er erkenne etwas, so hat er noch nicht erkannt, wie man erkennen soll;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'wenn aber jemand Gott liebt, der ist von ihm erkannt) -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'was nun das Essen der Götzenopfer betrifft, so wissen wir, daß ein Götzenbild nichts ist in der Welt, und daß kein anderer Gott ist, als nur einer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Denn wenn es anders solche gibt, die Götter genannt werden, sei es im Himmel oder auf Erden (wie es ja viele Götter und viele Herren gibt),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'so ist doch für uns ein Gott, der Vater, von welchem alle Dinge sind, und wir für ihn, und ein Herr, Jesus Christus, durch welchen alle Dinge sind, und wir durch ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Die Erkenntnis aber ist nicht in allen, sondern etliche essen, infolge des Gewissens, das sie bis jetzt vom Götzenbilde haben, als von einem Götzenopfer, und ihr Gewissen, da es schwach ist, wird befleckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Speise aber empfiehlt uns Gott nicht; weder sind wir, wenn wir nicht essen, geringer, noch sind wir, wenn wir essen, vorzüglicher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Sehet aber zu, daß nicht etwa dieses euer Recht den Schwachen zum Anstoß werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Denn wenn jemand dich, der du Erkenntnis hast, im Götzentempel zu Tische liegen sieht, wird nicht sein Gewissen, da er schwach ist, bestärkt werden, die Götzenopfer zu essen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Und durch deine Erkenntnis kommt der Schwache um, der Bruder, um dessentwillen Christus gestorben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Wenn ihr aber also gegen die Brüder sündiget und ihr schwaches Gewissen verletzet, so sündiget ihr gegen Christum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Darum, wenn eine Speise meinem Bruder Ärgernis gibt, so will ich für immer kein Fleisch essen, damit ich meinem Bruder kein Ärgernis gebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Bin ich nicht frei? Bin ich nicht ein Apostel? Habe ich nicht Jesum, unseren Herrn, gesehen? Seid nicht ihr mein Werk im Herrn?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Wenn ich anderen nicht ein Apostel bin, so bin ich es doch wenigstens euch; denn das Siegel meines Apostelamtes seid ihr im Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Meine Verantwortung vor denen, welche mich zur Untersuchung ziehen, ist diese:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Haben wir etwa nicht ein Recht zu essen und zu trinken?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Haben wir etwa nicht ein Recht, eine Schwester als Weib umherzuführen, wie auch die übrigen Apostel und die Brüder des Herrn und Kephas?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Oder haben allein ich und Barnabas nicht ein Recht, nicht zu arbeiten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Wer tut jemals Kriegsdienste auf eigenen Sold? Wer pflanzt einen Weinberg und ißt nicht von dessen Frucht? Oder wer weidet eine Herde und ißt nicht von der Milch der Herde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Rede ich dieses etwa nach Menschenweise, oder sagt nicht auch das Gesetz dieses?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Denn in dem Gesetz Moses\' steht geschrieben: \"Du sollst dem Ochsen, der da drischt, nicht das Maul verbinden\". Ist Gott etwa für die Ochsen besorgt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Oder spricht er nicht durchaus um unseretwillen? Denn es ist um unseretwillen geschrieben, daß der Pflügende auf Hoffnung pflügen soll, und der Dreschende auf Hoffnung dreschen, um dessen teilhaftig zu werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Wenn wir euch das Geistliche gesät haben, ist es ein Großes, wenn wir euer Fleischliches ernten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Wenn andere dieses Rechtes an euch teilhaftig sind, nicht vielmehr wir? Wir haben aber dieses Recht nicht gebraucht, sondern wir ertragen alles, auf daß wir dem Evangelium des Christus kein Hindernis bereiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Wisset ihr nicht, daß die, welche mit den heiligen Dingen beschäftigt sind, aus dem Tempel essen? Die, welche des Altars warten, mit dem Altar teilen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Also hat auch der Herr denen, die das Evangelium verkündigen, verordnet, vom Evangelium zu leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Ich aber habe von keinem dieser Dinge Gebrauch gemacht. Ich habe dies aber nicht geschrieben, auf daß es also mit mir geschehe; denn es wäre mir besser zu sterben, als daß jemand meinen Ruhm zunichte machen sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Denn wenn ich das Evangelium verkündige, so habe ich keinen Ruhm, denn eine Notwendigkeit liegt mir auf; denn wehe mir, wenn ich das Evangelium nicht verkündigte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Denn wenn ich dies freiwillig tue, so habe ich Lohn, wenn aber unfreiwillig, so bin ich mit einer Verwaltung betraut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Was ist nun mein Lohn? Daß ich, das Evangelium verkündigend, das Evangelium kostenfrei mache, so daß ich mein Recht am Evangelium nicht gebrauche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Denn wiewohl ich von allen frei bin, habe ich mich allen zum Sklaven gemacht, auf daß ich so viele wie möglich gewinne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Und ich bin den Juden geworden wie ein Jude, auf daß ich die Juden gewinne; denen, die unter Gesetz sind, wie unter Gesetz (wiewohl ich selbst nicht unter Gesetz bin), auf daß ich die, welche unter Gesetz sind, gewinne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'denen, die ohne Gesetz sind, wie ohne Gesetz (wiewohl ich nicht ohne Gesetz vor Gott bin, sondern Christo gesetzmäßig unterworfen), auf daß ich die, welche ohne Gesetz sind, gewinne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Den Schwachen bin ich geworden wie ein Schwacher, auf daß ich die Schwachen gewinne. Ich bin allen alles geworden, auf daß ich auf alle Weise etliche errette.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Ich tue aber alles um des Evangeliums willen, auf daß ich mit ihm teilhaben möge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Wisset ihr nicht, daß die, welche in der Rennbahn laufen, zwar alle laufen, aber einer den Preis empfängt? Laufet also, auf daß ihr ihn erlanget.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Jeder aber, der kämpft, ist enthaltsam in allem; jene freilich, auf daß sie eine vergängliche Krone empfangen, wir aber eine unvergängliche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Ich laufe daher also, nicht wie aufs ungewisse; ich kämpfe also, nicht wie einer, der die Luft schlägt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'sondern ich zerschlage meinen Leib und führe ihn in Knechtschaft, auf daß ich nicht, nachdem ich anderen gepredigt, selbst verwerflich werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Denn ich will nicht, daß ihr unkundig seid, Brüder, daß unsere Väter alle unter der Wolke waren und alle durch das Meer hindurchgegangen sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'und alle auf Moses getauft wurden in der Wolke und in dem Meere,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'und alle dieselbe geistliche Speise aßen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'und alle denselben geistlichen Trank tranken; denn sie tranken aus einem geistlichen Felsen, der sie begleitete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, '(Der Fels aber war der Christus.) An den meisten derselben aber hatte Gott kein Wohlgefallen, denn sie sind in der Wüste hingestreckt worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Diese Dinge aber sind als Vorbilder für uns geschehen, daß wir nicht nach bösen Dingen gelüsten, gleichwie auch jene gelüsteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Werdet auch nicht Götzendiener, gleichwie etliche von ihnen, wie geschrieben steht: \"Das Volk setzte sich nieder, zu essen und zu trinken, und sie standen auf, zu spielen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Auch laßt uns nicht Hurerei treiben, gleichwie etliche von ihnen Hurerei trieben, und es fielen an einem Tage dreiundzwanzigtausend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Laßt uns auch den Christus nicht versuchen, gleichwie etliche von ihnen ihn versuchten und von den Schlangen umgebracht wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Murret auch nicht, gleichwie etliche von ihnen murrten und von dem Verderber umgebracht wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Alle diese Dinge aber widerfuhren jenen als Vorbilder und sind geschrieben worden zu unserer Ermahnung, auf welche das Ende der Zeitalter gekommen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Daher, wer zu stehen sich dünkt, sehe zu, daß er nicht falle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Keine Versuchung hat euch ergriffen, als nur eine menschliche; Gott aber ist treu, der nicht zulassen wird, daß ihr über euer Vermögen versucht werdet, sondern mit der Versuchung auch den Ausgang schaffen wird, so daß ihr sie ertragen könnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Darum meine Geliebten, fliehet den Götzendienst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Ich rede als zu Verständigen; beurteilet ihr, was ich sage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Der Kelch der Segnung, den wir segnen, ist er nicht die Gemeinschaft des Blutes des Christus? Das Brot, das wir brechen, ist es nicht die Gemeinschaft des Leibes des Christus?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Denn ein Brot, ein Leib sind wir, die Vielen, denn wir alle nehmen teil an dem einen Brote.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Sehet auf Israel nach dem Fleische. Sind nicht die, welche die Schlachtopfer essen, in Gemeinschaft mit dem Altar?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Was sage ich nun? Daß das einem Götzen Geopferte etwas sei? Oder daß ein Götzenbild etwas sei?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Sondern daß das, was die Nationen opfern, sie den Dämonen opfern und nicht Gott. Ich will aber nicht, daß ihr Gemeinschaft habt mit den Dämonen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Ihr könnt nicht des Herrn Kelch trinken und der Dämonen Kelch; ihr könnt nicht des Herrn Tisches teilhaftig sein und des Dämonentisches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Oder reizen wir den Herrn zur Eifersucht? Sind wir etwa stärker als er?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Alles ist erlaubt, aber nicht alles ist nützlich; alles ist erlaubt, aber nicht alles erbaut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Niemand suche das Seine, sondern das des anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Alles, was auf dem Fleischmarkte verkauft wird, esset, ohne zu untersuchen um des Gewissens willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Denn \"die Erde ist des Herrn und ihre Fülle\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Wenn aber jemand von den Ungläubigen euch einladet, und ihr wollt hingehen, so esset alles, was euch vorgesetzt wird, ohne zu untersuchen um des Gewissens willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Wenn aber jemand zu euch sagt: Dies ist als Opfer dargebracht worden, so esset nicht, um jenes willen, der es anzeigt, und um des Gewissens willen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'des Gewissens aber, sage ich, nicht deines eigenen, sondern desjenigen des anderen; denn warum wird meine Freiheit von einem anderen Gewissen beurteilt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Wenn ich mit Danksagung teilhabe, warum werde ich gelästert über das, wofür ich danksage?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Ob ihr nun esset oder trinket oder irgend etwas tut, tut alles zur Ehre Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Seid ohne Anstoß, sowohl Juden als Griechen, und der Versammlung Gottes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'gleichwie auch ich mich in allen Dingen allen gefällig mache, indem ich nicht meinen Vorteil suche, sondern den der Vielen, auf daß sie errettet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Seid meine Nachahmer, gleichwie auch ich Christi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Ich lobe euch aber, daß ihr in allem meiner eingedenk seid und die Überlieferungen, wie ich sie euch überliefert habe, festhaltet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Ich will aber, daß ihr wisset, daß der Christus das Haupt eines jeden Mannes ist, des Weibes Haupt aber der Mann, des Christus Haupt aber Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Jeder Mann, der betet oder weissagt, indem er etwas auf dem Haupte hat, entehrt sein Haupt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Jedes Weib aber, das betet oder weissagt mit unbedecktem Haupte, entehrt ihr Haupt; denn es ist ein und dasselbe, wie wenn sie geschoren wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Denn wenn ein Weib nicht bedeckt ist, so werde ihr auch das Haar abgeschnitten; wenn es aber für ein Weib schändlich ist, daß ihr das Haar abgeschnitten oder sie geschoren werde, so laß sie sich bedecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Denn der Mann freilich soll nicht das Haupt bedecken, da er Gottes Bild und Herrlichkeit ist; das Weib aber ist des Mannes Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Denn der Mann ist nicht vom Weibe, sondern das Weib vom Manne;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'denn der Mann wurde auch nicht um des Weibes willen geschaffen, sondern das Weib um des Mannes willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Darum soll das Weib eine Macht auf dem Haupte haben, um der Engel willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Dennoch ist weder das Weib ohne den Mann, noch der Mann ohne das Weib im Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Denn gleichwie das Weib vom Manne ist, also ist auch der Mann durch das Weib; alles aber von Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Urteilet bei euch selbst: Ist es anständig, daß ein Weib unbedeckt zu Gott bete?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Oder lehrt euch nicht auch selbst die Natur, daß, wenn ein Mann langes Haar hat, es eine Unehre für ihn ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Wenn aber ein Weib langes Haar hat, es eine Ehre für sie ist? Weil das Haar ihr anstatt eines Schleiers gegeben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Wenn es aber jemand gut dünkt, streitsüchtig zu sein, so haben wir solche Gewohnheit nicht, noch die Versammlungen Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Indem ich aber dieses vorschreibe, lobe ich nicht, daß ihr nicht zum Besseren, sondern zum Schlechteren zusammenkommet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Denn fürs erste, wenn ihr als Versammlung zusammenkommet, höre ich, es seien Spaltungen unter euch, und zum Teil glaube ich es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Denn es müssen auch Parteiungen unter euch sein, auf daß die Bewährten unter euch offenbar werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Wenn ihr nun an einem Orte zusammenkommet, so ist das nicht des Herrn Mahl essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Denn ein jeder nimmt beim Essen sein eigenes Mahl vorweg, und der eine ist hungrig, der andere ist trunken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Habt ihr denn nicht Häuser, um zu essen und zu trinken? Oder verachtet ihr die Versammlung Gottes und beschämet die, welche nichts haben? Was soll ich euch sagen? Soll ich euch loben? In diesem lobe ich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Denn ich habe von dem Herrn empfangen, was ich auch euch überliefert habe, daß der Herr Jesus in der Nacht, in welcher er überliefert wurde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'Brot nahm, und als er gedankt hatte, es brach und sprach: Dies ist mein Leib, der für euch ist; dies tut zu meinem Gedächtnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Desgleichen auch den Kelch nach dem Mahle und sprach: Dieser Kelch ist der neue Bund in meinem Blute; dies tut, so oft ihr trinket, zu meinem Gedächtnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Denn so oft ihr dieses Brot esset und den Kelch trinket, verkündiget ihr den Tod des Herrn, bis er kommt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Wer also irgend das Brot ißt oder den Kelch des Herrn trinkt unwürdiglich, wird des Leibes und Blutes des Herrn schuldig sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Ein jeder aber prüfe sich selbst, und also esse er von dem Brote und trinke von dem Kelche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Denn wer unwürdiglich ißt und trinkt, ißt und trinkt sich selbst Gericht, indem er den Leib nicht unterscheidet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Deshalb sind viele unter euch schwach und krank, und ein gut Teil sind entschlafen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Aber wenn wir uns selbst beurteilten, so würden wir nicht gerichtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Wenn wir aber gerichtet werden, so werden wir vom Herrn gezüchtigt, auf daß wir nicht mit der Welt verurteilt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Daher, meine Brüder, wenn ihr zusammenkommet, um zu essen, so wartet aufeinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Wenn jemand hungert, der esse daheim, auf daß ihr nicht zum Gericht zusammenkommet. Das übrige aber will ich anordnen, sobald ich komme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Was aber die geistlichen Gaben betrifft, Brüder, so will ich nicht, daß ihr unkundig seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Ihr wisset, daß ihr, als ihr von den Nationen waret, zu den stummen Götzenbildern hingeführt wurdet, wie ihr irgend geleitet wurdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Deshalb tue ich euch kund, daß niemand, im Geiste Gottes redend, sagt: Fluch über Jesum! und niemand sagen kann: Herr Jesus! als nur im Heiligen Geiste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Es sind aber Verschiedenheiten von Gnadengaben, aber derselbe Geist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'und es sind Verschiedenheiten von Diensten, und derselbe Herr;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'und es sind Verschiedenheiten von Wirkungen, aber derselbe Gott, der alles in allen wirkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Einem jeden aber wird die Offenbarung des Geistes zum Nutzen gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Denn einem wird durch den Geist das Wort der Weisheit gegeben, einem anderen aber das Wort der Erkenntnis nach demselben Geiste;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'einem anderen aber Glauben in demselben Geiste, einem anderen aber Gnadengaben der Heilungen in demselben Geiste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'einem anderen aber Wunderwirkungen, einem anderen aber Prophezeiung, einem anderen aber Unterscheidungen der Geister; einem anderen aber Arten von Sprachen, einem anderen aber Auslegung der Sprachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Alles dieses aber wirkt ein und derselbe Geist, einem jeden insbesondere austeilend, wie er will.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Denn gleichwie der Leib einer ist und viele Glieder hat, alle Glieder des Leibes aber, obgleich viele, ein Leib sind: also auch der Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Denn auch in einem Geiste sind wir alle zu einem Leibe getauft worden, es seien Juden oder Griechen, es seien Sklaven oder Freie, und sind alle mit einem Geiste getränkt worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Denn auch der Leib ist nicht ein Glied, sondern viele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Wenn der Fuß spräche: Weil ich nicht Hand bin, so bin ich nicht von dem Leibe; ist er deswegen nicht von dem Leibe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Und wenn das Ohr spräche: Weil ich nicht Auge bin, so bin ich nicht von dem Leibe; ist es deswegen nicht von dem Leibe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Wenn der ganze Leib Auge wäre, wo wäre das Gehör? Wenn ganz Gehör, wo der Geruch?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Nun aber hat Gott die Glieder gesetzt, jedes einzelne von ihnen an dem Leibe, wie es ihm gefallen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Wenn aber alle ein Glied wären, wo wäre der Leib?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Nun aber sind der Glieder zwar viele, der Leib aber ist einer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Das Auge kann nicht zu der Hand sagen: Ich bedarf deiner nicht; oder wiederum das Haupt zu den Füßen: Ich bedarf euer nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'sondern vielmehr die Glieder des Leibes, die schwächer zu sein scheinen, sind notwendig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'und die uns die unehrbareren des Leibes zu sein dünken, diese umgeben wir mit reichlicherer Ehre; und unsere nichtanständigen haben desto reichlichere Wohlanständigkeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'unsere wohlanständigen aber bedürfen es nicht. Aber Gott hat den Leib zusammengefügt, indem er dem Mangelhafteren reichlichere Ehre gegeben hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'auf daß keine Spaltung in dem Leibe sei, sondern die Glieder dieselbe Sorge für einander haben möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Und wenn ein Glied leidet, so leiden alle Glieder mit; oder wenn ein Glied verherrlicht wird, so freuen sich alle Glieder mit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Ihr aber seid Christi Leib, und Glieder insonderheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Und Gott hat etliche in der Versammlung gesetzt: erstens Apostel, zweitens Propheten, drittens Lehrer, sodann Wunderkräfte, sodann Gnadengaben der Heilungen, Hilfeleistungen, Regierungen, Arten von Sprachen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Sind etwa alle Apostel? Alle Propheten? Alle Lehrer? Haben alle Wunderkräfte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Haben alle Gnadengaben der Heilungen? Reden alle in Sprachen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Legen alle aus? Eifert aber um die größeren Gnadengaben; und einen noch weit vortrefflicheren Weg zeige ich euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Wenn ich mit den Sprachen der Menschen und der Engel rede, aber nicht Liebe habe, so bin ich ein tönendes Erz geworden oder eine schallende Zimbel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Und wenn ich Prophezeiung habe und alle Geheimnisse und alle Erkenntnis weiß, und wenn ich allen Glauben habe, so daß ich Berge versetze, aber nicht Liebe habe, so bin ich nichts.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Und wenn ich alle meine Habe zur Speisung der Armen austeilen werde, und wenn ich meinen Leib hingebe, auf daß ich verbrannt werde, aber nicht Liebe habe, so ist es mir nichts nütze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Die Liebe ist langmütig, ist gütig; die Liebe neidet nicht; die Liebe tut nicht groß, sie bläht sich nicht auf,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'sie gebärdet sich nicht unanständig, sie sucht nicht das Ihrige, sie läßt sich nicht erbittern, sie rechnet Böses nicht zu,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'sie freut sich nicht über die Ungerechtigkeit, sondern sie freut sich mit der Wahrheit, sie erträgt alles,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'sie glaubt alles, sie hofft alles, sie erduldet alles.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Die Liebe vergeht nimmer; seien es aber Prophezeiungen, sie werden weggetan werden; seien es Sprachen, sie werden aufhören; sei es Erkenntnis, sie wird weggetan werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Denn wir erkennen stückweise, und wir prophezeien stückweise;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'wenn aber das Vollkommene gekommen sein wird, so wird das, was stückweise ist, weggetan werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Als ich ein Kind war, redete ich wie ein Kind, dachte wie ein Kind, urteilte wie ein Kind; als ich ein Mann wurde, tat ich weg, was kindisch war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Denn wir sehen jetzt durch einen Spiegel, undeutlich, dann aber von Angesicht zu Angesicht. Jetzt erkenne ich stückweise, dann aber werde ich erkennen, gleichwie auch ich erkannt worden bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Nun aber bleibt Glaube, Hoffnung, Liebe, diese drei; die größte aber von diesen ist die Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Strebet nach der Liebe; eifert aber um die geistlichen Gaben, vielmehr aber, daß ihr weissaget.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Denn wer in einer Sprache redet, redet nicht Menschen, sondern Gott; denn niemand versteht es, im Geiste aber redet er Geheimnisse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Wer aber weissagt, redet den Menschen zur Erbauung und Ermahnung und Tröstung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Wer in einer Sprache redet, erbaut sich selbst; wer aber weissagt, erbaut die Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Ich wollte aber, daß ihr alle in Sprachen redetet, vielmehr aber, daß ihr weissagtet. Wer aber weissagt, ist größer, als wer in Sprachen redet, es sei denn, daß er es auslege, auf daß die Versammlung Erbauung empfange.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Jetzt aber, Brüder, wenn ich zu euch komme und in Sprachen rede, was werde ich euch nützen, wenn ich nicht zu euch rede, entweder in Offenbarung oder in Erkenntnis oder in Weissagung oder in Lehre?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Doch auch die leblosen Dinge, die einen Ton von sich geben, es sei Pfeife oder Harfe, wenn sie den Tönen keinen Unterschied geben, wie wird man erkennen, was gepfiffen oder geharft wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Denn auch wenn die Posaune einen undeutlichen Ton gibt, wer wird sich zum Kampfe rüsten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Also auch ihr, wenn ihr durch die Sprache nicht eine verständliche Rede gebet, wie wird man wissen, was geredet wird? Denn ihr werdet in den Wind reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Es gibt vielleicht so und so viele Arten von Stimmen in der Welt, und keine Art ist ohne bestimmten Ton.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Wenn ich nun die Bedeutung der Stimme nicht weiß, so werde ich dem Redenden ein Barbar sein, und der Redende für mich ein Barbar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Also auch ihr, da ihr um geistliche Gaben eifert, so suchet, daß ihr überströmend seid zur Erbauung der Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Darum, wer in einer Sprache redet, bete, auf daß er es auslege.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Denn wenn ich in einer Sprache bete, so betet mein Geist, aber mein Verstand ist fruchtleer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Was ist es nun? Ich will beten mit dem Geiste, aber ich will auch beten mit dem Verstande; ich will lobsingen mit dem Geiste, aber ich will auch lobsingen mit dem Verstande.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Sonst, wenn du mit dem Geiste preisen wirst, wie soll der, welcher die Stelle des Unkundigen einnimmt, das Amen sprechen zu deiner Danksagung, da er ja nicht weiß, was du sagst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Denn du danksagst wohl gut, aber der andere wird nicht erbaut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Ich danke Gott, ich rede mehr in einer Sprache als ihr alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Aber in der Versammlung will ich lieber fünf Worte reden mit meinem Verstande, auf daß ich auch andere unterweise, als zehntausend Worte in einer Sprache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Brüder, werdet nicht Kinder am Verstande, sondern an der Bosheit seid Unmündige, am Verstande aber werdet Erwachsene.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Es steht in dem Gesetz geschrieben: \"Ich will in anderen Sprachen und durch andere Lippen zu diesem Volke reden, und auch also werden sie nicht auf mich hören, spricht der Herr.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Daher sind die Sprachen zu einem Zeichen, nicht den Glaubenden, sondern den Ungläubigen; die Weissagung aber nicht den Ungläubigen, sondern den Glaubenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Wenn nun die ganze Versammlung an einem Orte zusammenkommt und alle in Sprachen reden, und es kommen Unkundige oder Ungläubige herein, werden sie nicht sagen, daß ihr von Sinnen seid?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Wenn aber alle weissagen, und irgend ein Ungläubiger oder Unkundiger kommt herein, so wird er von allen überführt, von allen beurteilt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'das Verborgene seines Herzens wird offenbar, und also, auf sein Angesicht fallend, wird er Gott anbeten und verkündigen, daß Gott wirklich unter euch ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Was ist es nun, Brüder? Wenn ihr zusammenkommet, so hat ein jeder von euch einen Psalm, hat eine Lehre, hat eine Sprache, hat eine Offenbarung, hat eine Auslegung; alles geschehe zur Erbauung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Wenn nun jemand in einer Sprache redet, so sei es zu zwei oder höchstens drei und nacheinander, und einer lege aus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Wenn aber kein Ausleger da ist, so schweige er in der Versammlung, rede aber sich selbst und Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Propheten aber laßt zwei oder drei reden, und die anderen laßt urteilen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Wenn aber einem anderen, der dasitzt, eine Offenbarung wird, so schweige der erste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Denn ihr könnt einer nach dem anderen alle weissagen, auf daß alle lernen und alle getröstet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Und die Geister der Propheten sind den Propheten untertan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Denn Gott ist nicht ein Gott der Unordnung, sondern des Friedens, wie in allen Versammlungen der Heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Eure Weiber sollen schweigen in den Versammlungen, denn es ist ihnen nicht erlaubt zu reden, sondern unterwürfig zu sein, wie auch das Gesetz sagt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Wenn sie aber etwas lernen wollen, so sollen sie daheim ihre eigenen Männer fragen; denn es ist schändlich für ein Weib, in der Versammlung zu reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Oder ist das Wort Gottes von euch ausgegangen? Oder ist es zu euch allein gelangt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Wenn jemand sich dünkt, ein Prophet zu sein oder geistlich, so erkenne er, was ich euch schreibe, daß es ein Gebot des Herrn ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Wenn aber jemand unwissend ist, so sei er unwissend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Daher, Brüder, eifert danach zu weissagen, und wehret nicht, in Sprachen zu reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Alles aber geschehe anständig und in Ordnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Ich tue euch aber kund, Brüder, das Evangelium, das ich euch verkündigt habe, das ihr auch angenommen habt, in welchem ihr auch stehet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'durch welches ihr auch errettet werdet (wenn ihr an dem Worte festhaltet, das ich euch verkündigt habe), es sei denn, daß ihr vergeblich geglaubt habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Denn ich habe euch zuerst überliefert, was ich auch empfangen habe: daß Christus für unsere Sünden gestorben ist, nach den Schriften;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'und daß er begraben wurde, und daß er auferweckt worden ist am dritten Tage, nach den Schriften;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'und daß er Kephas erschienen ist, dann den Zwölfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Danach erschien er mehr als fünfhundert Brüdern auf einmal, von denen die meisten bis jetzt übriggeblieben, etliche aber auch entschlafen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Danach erschien er Jakobus, dann den Aposteln allen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'am letzten aber von allen, gleichsam der unzeitigen Geburt, erschien er auch mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Denn ich bin der geringste der Apostel, der ich nicht würdig bin, ein Apostel genannt zu werden, weil ich die Versammlung Gottes verfolgt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Aber durch Gottes Gnade bin ich, was ich bin; und seine Gnade gegen mich ist nicht vergeblich gewesen, sondern ich habe viel mehr gearbeitet als sie alle; nicht aber ich, sondern die Gnade Gottes, die mit mir war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Sei ich es nun, seien es jene, also predigen wir, und also habt ihr geglaubt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Wenn aber Christus gepredigt wird, daß er aus den Toten auferweckt sei, wie sagen etliche unter euch, daß es keine Auferstehung der Toten gebe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Wenn es aber keine Auferstehung der Toten gibt, so ist auch Christus nicht auferweckt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'wenn aber Christus nicht auferweckt ist, so ist also auch unsere Predigt vergeblich, aber auch euer Glaube vergeblich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Wir werden aber auch als falsche Zeugen Gottes erfunden, weil wir in Bezug auf Gott gezeugt haben, daß er den Christus auferweckt habe, den er nicht auferweckt hat, wenn wirklich Tote nicht auferweckt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Denn wenn Tote nicht auferweckt werden, so ist auch Christus nicht auferweckt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Wenn aber Christus nicht auferweckt ist, so ist euer Glaube eitel; ihr seid noch in euren Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Also sind auch die, welche in Christo entschlafen sind, verloren gegangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Wenn wir allein in diesem Leben auf Christum Hoffnung haben, so sind wir die elendesten von allen Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, '(Nun aber ist Christus aus den Toten auferweckt, der Erstling der Entschlafenen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'denn da ja durch einen Menschen der Tod kam, so auch durch einen Menschen die Auferstehung der Toten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Denn gleichwie in dem Adam alle sterben, also werden auch in dem Christus alle lebendig gemacht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Ein jeder aber in seiner eigenen Ordnung: der Erstling, Christus; sodann die, welche des Christus sind bei seiner Ankunft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'dann das Ende, wenn er das Reich dem Gott und Vater übergibt, wenn er weggetan haben wird alle Herrschaft und alle Gewalt und Macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Denn er muß herrschen, bis er alle Feinde unter seine Füße gelegt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Der letzte Feind, der weggetan wird, ist der Tod.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, '\"Denn alles hat er seinen Füßen unterworfen.\" Wenn er aber sagt, daß alles unterworfen sei, so ist es offenbar, daß der ausgenommen ist, der ihm alles unterworfen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Wenn ihm aber alles unterworfen sein wird, dann wird auch der Sohn selbst dem unterworfen sein, der ihm alles unterworfen hat, auf daß Gott alles in allem sei.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Was werden sonst die tun, die für die Toten getauft werden, wenn überhaupt Tote nicht auferweckt werden? Warum werden sie auch für sie getauft?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Warum sind auch wir jede Stunde in Gefahr?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Täglich sterbe ich, bei eurem Rühmen, das ich habe in Christo Jesu, unserem Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Wenn ich, nach Menschenweise zu reden, mit wilden Tieren gekämpft habe zu Ephesus, was nützt es mir, wenn Tote nicht auferweckt werden? \"Laßt uns essen und trinken, denn morgen sterben wir!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Laßt euch nicht verführen: Böser Verkehr verdirbt gute Sitten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Werdet rechtschaffen nüchtern und sündiget nicht, denn etliche sind in Unwissenheit über Gott; zur Beschämung sage ich\'s euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Es wird aber jemand sagen: Wie werden die Toten auferweckt? Und mit was für einem Leibe kommen sie? Tor!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Was du säst, wird nicht lebendig, es sterbe denn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'Und was du säst, du säst nicht den Leib, der werden soll, sondern ein nacktes Korn, es sei von Weizen oder von einem der anderen Samen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Gott aber gibt ihm einen Leib, wie er gewollt hat, und einem jeden der Samen seinen eigenen Leib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Nicht alles Fleisch ist dasselbe Fleisch; sondern ein anderes ist das der Menschen, und ein anderes das Fleisch des Viehes, und ein anderes das der Vögel, und ein anderes das der Fische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Und es gibt himmlische Leiber und irdische Leiber. Aber eine andere ist die Herrlichkeit der himmlischen, eine andere die der irdischen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'eine andere die Herrlichkeit der Sonne, und eine andere die Herrlichkeit des Mondes, und eine andere die Herrlichkeit der Sterne; denn es unterscheidet sich Stern von Stern an Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Also ist auch die Auferstehung der Toten. Es wird gesät in Verwesung, es wird auferweckt in Unverweslichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Es wird gesät in Unehre, es wird auferweckt in Herrlichkeit; es wird gesät in Schwachheit, es wird auferweckt in Kraft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'es wird gesät ein natürlicher Leib, es wird auferweckt ein geistiger Leib. Wenn es einen natürlichen Leib gibt, so gibt es auch einen geistigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'So steht auch geschrieben: \"Der erste Mensch, Adam, ward eine lebendige Seele\"; der letzte Adam ein lebendig machender Geist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Aber das Geistige war nicht zuerst, sondern das Natürliche, danach das Geistige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Der erste Mensch ist von der Erde, von Staub; der zweite Mensch vom Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Wie der von Staub ist, so sind auch die, welche von Staub sind; und wie der Himmlische, so sind auch die Himmlischen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Und wie wir das Bild dessen von Staub getragen haben, so werden wir auch das Bild des Himmlischen tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Dies aber sage ich, Brüder, daß Fleisch und Blut das Reich Gottes nicht ererben können, auch die Verwesung nicht die Unverweslichkeit ererbt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Siehe, ich sage euch ein Geheimnis: Wir werden zwar nicht alle entschlafen, wir werden aber alle verwandelt werden, in einem Nu,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'in einem Augenblick, bei der letzten Posaune; denn posaunen wird es, und die Toten werden auferweckt werden unverweslich, und wir werden verwandelt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Denn dieses Verwesliche muß Unverweslichkeit anziehen, und dieses Sterbliche Unsterblichkeit anziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Wenn aber dieses Verwesliche Unverweslichkeit anziehen und dieses Sterbliche Unsterblichkeit anziehen wird, dann wird das Wort erfüllt werden, das geschrieben steht: \"Verschlungen ist der Tod in Sieg\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, '\"Wo ist, o Tod, dein Stachel? Wo ist, o Tod, dein Sieg?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Der Stachel des Todes aber ist die Sünde, die Kraft der Sünde aber das Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Gott aber sei Dank, der uns den Sieg gibt durch unseren Herrn Jesus Christus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Daher, meine geliebten Brüder, seid fest, unbeweglich, allezeit überströmend in dem Werke des Herrn, da ihr wisset, daß eure Mühe nicht vergeblich ist im Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Was aber die Sammlung für die Heiligen betrifft: wie ich den Versammlungen von Galatien verordnet habe, also tut auch ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'An jedem ersten Wochentage lege ein jeder von euch bei sich zurück und sammle auf, je nachdem er Gedeihen hat, auf daß nicht dann, wenn ich komme, Sammlungen geschehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Wenn ich aber angekommen bin, so will ich die, welche irgend ihr für tüchtig erachten werdet, mit Briefen senden, daß sie eure Gabe nach Jerusalem hinbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Wenn es aber angemessen ist, daß auch ich hinreise, so sollen sie mit mir reisen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Ich werde aber zu euch kommen, wenn ich Macedonien durchzogen habe, denn ich ziehe durch Macedonien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Vielleicht aber werde ich bei euch bleiben oder auch überwintern, auf daß ihr mich geleitet, wohin irgend ich reise;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'denn ich will euch jetzt nicht im Vorbeigehen sehen, denn ich hoffe, einige Zeit bei euch zu bleiben, wenn der Herr es erlaubt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Ich werde aber bis Pfingsten in Ephesus bleiben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'denn eine große und wirkungsvolle Tür ist mir aufgetan, und der Widersacher sind viele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Wenn aber Timotheus kommt, so sehet zu, daß er ohne Furcht bei euch sei; denn er arbeitet am Werke des Herrn, wie auch ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Es verachte ihn nun niemand. Geleitet ihn aber in Frieden, auf daß er zu mir komme; denn ich erwarte ihn mit den Brüdern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Was aber den Bruder Apollos betrifft, so habe ich ihm viel zugeredet, daß er mit den Brüdern zu euch komme; und er war durchaus nicht willens, jetzt zu kommen, doch wird er kommen, wenn er eine gelegene Zeit finden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Wachet, stehet fest im Glauben; seid männlich, seid stark!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Alles bei euch geschehe in Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Ich ermahne euch aber, Brüder: Ihr kennet das Haus des Stephanas, daß es der Erstling von Achaja ist, und daß sie sich selbst den Heiligen zum Dienst verordnet haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'daß auch ihr solchen unterwürfig seid und jedem, der mitwirkt und arbeitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Ich freue mich aber über die Ankunft des Stephanas und Fortunatus und Achaikus, denn diese haben erstattet, was euerseits mangelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Denn sie haben meinen Geist erquickt und den eurigen; erkennet nun solche an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Es grüßen euch die Versammlungen Asiens. Es grüßen euch vielmal im Herrn Aquila und Priscilla, samt der Versammlung in ihrem Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Es grüßen euch die Brüder alle. Grüßet einander mit heiligem Kuß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Der Gruß mit meiner, des Paulus, Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Wenn jemand den Herrn Jesus Christus nicht lieb hat, der sei Anathema; Maranatha!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Die Gnade des Herrn Jesus Christus sei mit euch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Meine Liebe sei mit euch allen in Christo Jesu! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paulus, Apostel Jesu Christi durch Gottes Willen, und Timotheus, der Bruder, der Versammlung Gottes, die in Korinth ist, samt allen Heiligen, die in ganz Achaja sind:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Gnade euch und Friede von Gott, unserem Vater, und dem Herrn Jesus Christus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Gepriesen sei der Gott und Vater unseres Herrn Jesus Christus, der Vater der Erbarmungen und Gott alles Trostes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'der uns tröstet in all unserer Drangsal, auf daß wir die trösten können, die in allerlei Drangsal sind, durch den Trost, mit welchem wir selbst von Gott getröstet werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'weil, gleichwie die Leiden des Christus gegen uns überschwenglich sind, also auch durch den Christus unser Trost überschwenglich ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Es sei aber, wir werden bedrängt, so ist es um eures Trostes und Heiles willen, das bewirkt wird im Ausharren in denselben Leiden, die auch wir leiden');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, '(und unsere Hoffnung für euch ist fest); es sei wir werden getröstet, so ist es um eures Trostes und Heiles willen, indem wir wissen, daß, gleichwie ihr der Leiden teilhaftig seid, also auch des Trostes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Denn wir wollen nicht, daß ihr unkundig seid, Brüder, was unsere Drangsal betrifft, die uns in Asien widerfahren ist, daß wir übermäßig beschwert wurden, über Vermögen, so daß wir selbst am Leben verzweifelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Wir selbst aber hatten das Urteil des Todes in uns selbst, auf daß unser Vertrauen nicht auf uns selbst wäre, sondern auf Gott, der die Toten auferweckt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'welcher uns von so großem Tode errettet hat und errettet, auf welchen wir unsere Hoffnung gesetzt haben, daß er uns auch ferner erretten werde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'indem auch ihr durch das Flehen für uns mitwirket, auf daß für die mittelst vieler Personen uns verliehene Gnadengabe durch viele für uns Danksagung dargebracht werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Denn unser Rühmen ist dieses: das Zeugnis unseres Gewissens, daß wir in Einfalt und Lauterkeit Gottes, nicht in fleischlicher Weisheit, sondern in der Gnade Gottes unseren Verkehr gehabt haben in der Welt, am meisten aber bei euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Denn wir schreiben euch nichts anderes, als was ihr kennet oder auch anerkennet; ich hoffe aber, daß ihr es bis ans Ende anerkennen werdet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'gleichwie ihr auch uns zum Teil anerkannt habt, daß wir euer Ruhm sind, so wie auch ihr der unsrige seid an dem Tage des Herrn Jesus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Und in diesem Vertrauen wollte ich vorher zu euch kommen, auf daß ihr eine zweite Gnade hättet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'und bei euch hindurch nach Macedonien reisen, und wiederum von Macedonien zu euch kommen und von euch nach Judäa geleitet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Habe ich nun, indem ich mir dieses vornahm, mich etwa der Leichtfertigkeit bedient? Oder was ich mir vornehme, nehme ich mir das nach dem Fleische vor, auf daß bei mir das Ja ja und das Nein nein wäre?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Gott aber ist treu, daß unser Wort an euch nicht ja und nein ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Denn der Sohn Gottes, Jesus Christus, der unter euch durch uns gepredigt worden ist, durch mich und Silvanus und Timotheus, wurde nicht ja und nein, sondern es ist ja in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Denn so viele der Verheißungen Gottes sind, in ihm ist das Ja und in ihm das Amen, Gott zur Herrlichkeit durch uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Der uns aber mit euch befestigt in Christum und uns gesalbt hat, ist Gott,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'der uns auch versiegelt hat und hat das Unterpfand des Geistes in unsere Herzen gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Ich aber rufe Gott zum Zeugen an auf meine Seele, daß ich, um euer zu schonen, noch nicht nach Korinth gekommen bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Nicht daß wir über euren Glauben herrschen, sondern wir sind Mitarbeiter an eurer Freude; denn ihr stehet durch den Glauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Ich habe aber bei mir selbst dieses beschlossen, nicht wieder in Traurigkeit zu euch zu kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Denn wenn ich euch traurig mache, wer ist es auch, der mich fröhlich mache, wenn nicht der, welcher durch mich traurig gemacht wird?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Und eben dieses habe ich euch geschrieben, auf daß ich nicht, wenn ich komme, von denen Traurigkeit habe, deren ich mich freuen sollte; indem ich euch allen vertraue, daß meine Freude die euer aller ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Denn aus vieler Drangsal und Herzensangst schrieb ich euch mit vielen Tränen, nicht auf daß ihr traurig gemacht werden solltet, sondern auf daß ihr die Liebe erkennen möchtet, die ich überschwenglicher zu euch habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Wenn aber jemand traurig gemacht hat, so hat er nicht mich traurig gemacht, sondern in gewissem Maße (auf daß ich nicht beschwere) euch alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Genügend ist einem solchen diese Strafe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'die von den vielen ist, so daß ihr im Gegenteil vielmehr vergeben und ermuntern solltet, damit nicht etwa ein solcher durch übermäßige Traurigkeit verschlungen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Darum ermahne ich euch, Liebe gegen ihn zu betätigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Denn dazu habe ich auch geschrieben, auf daß ich eure Bewährung kennen lerne, ob ihr in allem gehorsam seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Wem ihr aber etwas vergebet, dem vergebe auch ich; denn auch ich, was ich vergeben, wenn ich etwas vergeben habe, habe ich um euretwillen vergeben in der Person Christi,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'auf daß wir nicht vom Satan übervorteilt werden; denn seine Gedanken sind uns nicht unbekannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Als ich aber nach Troas kam für das Evangelium des Christus und mir eine Tür aufgetan wurde im Herrn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'hatte ich keine Ruhe in meinem Geiste, weil ich Titus, meinen Bruder, nicht fand, sondern ich nahm Abschied von ihnen und zog fort nach Macedonien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Gott aber sei Dank, der uns allezeit im Triumphzuge umherführt in Christo und den Geruch seiner Erkenntnis an jedem Orte durch uns offenbart!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Denn wir sind Gott ein Wohlgeruch Christi in denen, die errettet werden, und in denen, die verloren gehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'den einen ein Geruch vom Tode zum Tode, den anderen aber ein Geruch vom Leben zum Leben. Und wer ist dazu tüchtig?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Denn wir verfälschen nicht, wie die vielen, das Wort Gottes, sondern als aus Lauterkeit, sondern als aus Gott, vor Gott, reden wir in Christo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Fangen wir wiederum an, uns selbst zu empfehlen? Oder bedürfen wir etwa, wie etliche, Empfehlungsbriefe an euch oder Empfehlungsbriefe von euch?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Ihr seid unser Brief, eingeschrieben in unsere Herzen, gekannt und gelesen von allen Menschen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'die ihr offenbar geworden, daß ihr ein Brief Christi seid, angefertigt durch uns im Dienst, geschrieben nicht mit Tinte, sondern mit dem Geiste des lebendigen Gottes, nicht auf steinerne Tafeln, sondern auf fleischerne Tafeln des Herzens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Solches Vertrauen aber haben wir durch Christum zu Gott:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'nicht daß wir von uns selbst aus tüchtig sind, etwas zu denken, als aus uns selbst, sondern unsere Tüchtigkeit ist von Gott,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'der uns auch tüchtig gemacht hat zu Dienern des neuen Bundes, nicht des Buchstabens, sondern des Geistes. Denn der Buchstabe tötet, der Geist aber macht lebendig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, '(Wenn aber der Dienst des Todes, mit Buchstaben in Steine eingegraben, in Herrlichkeit begann, so daß die Söhne Israels das Angesicht Moses\' nicht unverwandt anschauen konnten wegen der Herrlichkeit seines Angesichts, die hinweggetan werden sollte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'wie wird nicht vielmehr der Dienst des Geistes in Herrlichkeit bestehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Denn wenn der Dienst der Verdammnis Herrlichkeit ist, so ist vielmehr der Dienst der Gerechtigkeit überströmend in Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Denn auch das Verherrlichte ist nicht in dieser Beziehung verherrlicht worden, wegen der überschwenglichen Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Denn wenn das, was hinweggetan werden sollte, mit Herrlichkeit eingeführt wurde, wieviel mehr wird das Bleibende in Herrlichkeit bestehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Da wir nun eine solche Hoffnung haben, so gebrauchen wir große Freimütigkeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'und tun nicht gleichwie Moses, der eine Decke über sein Angesicht legte, auf daß die Söhne Israels nicht anschauen möchten das Ende dessen, was hinweggetan werden sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Aber ihr Sinn ist verstockt worden, denn bis auf den heutigen Tag bleibt beim Lesen des alten Bundes dieselbe Decke unaufgedeckt, die in Christo weggetan wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Aber bis auf den heutigen Tag, wenn Moses gelesen wird, liegt die Decke auf ihrem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Wenn es aber zum Herrn umkehren wird, so wird die Decke weggenommen.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Der Herr aber ist der Geist; wo aber der Geist des Herrn ist, ist Freiheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Wir alle aber, mit aufgedecktem Angesicht die Herrlichkeit des Herrn anschauend, werden verwandelt nach demselben Bilde von Herrlichkeit zu Herrlichkeit, als durch den Herrn, den Geist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Darum, da wir diesen Dienst haben, wie wir begnadigt worden sind, ermatten wir nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'sondern wir haben den geheimen Dingen der Scham entsagt, indem wir nicht Arglist wandeln, noch das Wort Gottes verfälschen, sondern durch die Offenbarung der Wahrheit uns selbst jedem Gewissen der Menschen empfehlen vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Wenn aber auch unser Evangelium verdeckt ist, so ist es in denen verdeckt, die verloren gehen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'in welchen der Gott dieser Welt den Sinn der Ungläubigen verblendet hat, damit ihnen nicht ausstrahle der Lichtglanz des Evangeliums der Herrlichkeit des Christus, welcher das Bild Gottes ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Denn wir predigen nicht uns selbst, sondern Christum Jesum als Herrn, uns selbst aber als eure Knechte um Jesu willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Denn der Gott, der aus Finsternis Licht leuchten hieß, ist es, der in unsere Herzen geleuchtet hat zum Lichtglanz der Erkenntnis der Herrlichkeit Gottes im Angesicht Christi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Wir haben aber diesen Schatz in irdenen Gefäßen, auf daß die Überschwenglichkeit der Kraft sei Gottes und nicht aus uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Allenthalben bedrängt, aber nicht eingeengt; keinen Ausweg sehend, aber nicht ohne Ausweg;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'verfolgt, aber nicht verlassen; niedergeworfen, aber nicht umkommend;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'allezeit das Sterben Jesu am Leibe umhertragend, auf daß auch das Leben Jesu an unserem Leibe offenbar werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Denn wir, die wir leben, werden allezeit dem Tode überliefert um Jesu willen, auf daß auch das Leben Jesu an unserem sterblichen Fleische offenbar werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'So denn wirkt der Tod in uns, das Leben aber in euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Da wir aber denselben Geist des Glaubens haben (nach dem, was geschrieben steht: \"Ich habe geglaubt, darum habe ich geredet\"), so glauben auch wir, darum reden wir auch,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'indem wir wissen, daß der, welcher den Herrn Jesus auferweckt hat, auch uns mit Jesu auferwecken und mit euch darstellen wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'denn alles ist um euretwillen, auf daß die Gnade, überreich geworden durch die Vielen, die Danksagung zur Herrlichkeit Gottes überströmen lasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Deshalb ermatten wir nicht, sondern wenn auch unser äußerer Mensch verfällt, so wird doch der innere Tag für Tag erneuert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Denn das schnell vorübergehende Leichte unserer Drangsal bewirkt uns ein über die Maßen überschwengliches, ewiges Gewicht von Herrlichkeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'indem wir nicht das anschauen, was man sieht, sondern das, was man nicht sieht; denn das, was man sieht, ist zeitlich, das aber, was man nicht sieht, ewig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Denn wir wissen, daß, wenn unser irdisches Haus, die Hütte, zerstört wird, wir einen Bau von Gott haben, ein Haus, nicht mit Händen gemacht, ein ewiges, in den Himmeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Denn in diesem freilich seufzen wir, uns sehnend, mit unserer Behausung, die aus dem Himmel ist, überkleidet zu werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'so wir anders, wenn wir auch bekleidet sind, nicht nackt erfunden werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Denn wir freilich, die in der Hütte sind, seufzen beschwert, wiewohl wir nicht entkleidet, sondern überkleidet werden möchten, damit das Sterbliche verschlungen werde von dem Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Der uns aber eben hierzu bereitet hat, ist Gott, der uns auch das Unterpfand des Geistes gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'So sind wir nun allezeit gutes Mutes und wissen, daß, während einheimisch in dem Leibe, wir von dem Herrn ausheimisch sind');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '(denn wir wandeln durch Glauben, nicht durch Schauen);');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'wir sind aber gutes Mutes und möchten lieber ausheimisch von dem Leibe und einheimisch bei dem Herrn sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Deshalb beeifern wir uns auch, ob einheimisch oder ausheimisch, ihm wohlgefällig zu sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Denn wir müssen alle vor dem Richterstuhl des Christus offenbar werden, auf daß ein jeder empfange, was er in dem Leibe getan, nach dem er gehandelt hat, es sei Gutes oder Böses.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Da wir nun den Schrecken des Herrn kennen, so überreden wir die Menschen, Gott aber sind wir offenbar geworden; ich hoffe aber, auch in euren Gewissen offenbar geworden zu sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Denn wir empfehlen uns selbst euch nicht wiederum, sondern geben euch Anlaß zum Ruhm unserethalben, auf daß ihr ihn habet bei denen, die sich nach dem Ansehen rühmen und nicht nach dem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Denn sei es, daß wir außer uns sind, so sind wir es Gott; sei es daß wir vernünftig sind euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Denn die Liebe des Christus drängt uns, indem wir also geurteilt haben, daß einer für alle gestorben ist und somit alle gestorben sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'Und er ist für alle gestorben, auf daß die, welche leben, nicht mehr sich selbst leben, sondern dem, der für sie gestorben ist und ist auferweckt worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Daher kennen wir von nun an niemand nach dem Fleische; wenn wir aber auch Christum nach dem Fleische gekannt haben, so kennen wir ihn doch jetzt nicht mehr also.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Daher, wenn jemand in Christo ist, da ist eine neue Schöpfung; das Alte ist vergangen, siehe, alles ist neu geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Alles aber von dem Gott, der uns mit sich selbst versöhnt hat durch Jesum Christum und hat uns den Dienst der Versöhnung gegeben:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'nämlich daß Gott in Christo war, die Welt mit sich selbst versöhnend, ihnen ihre Übertretungen nicht zurechnend, und hat in uns das Wort der Versöhnung niedergelegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'So sind wir nun Gesandte für Christum, als ob Gott durch uns ermahnte; wir bitten an Christi Statt: Laßt euch versöhnen mit Gott!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Den, der Sünde nicht kannte, hat er für uns zur Sünde gemacht, auf daß wir Gottes Gerechtigkeit würden in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Mitarbeitend aber ermahnen wir auch, daß ihr die Gnade Gottes nicht vergeblich empfanget');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, '(denn er spricht: \"Zur angenehmen Zeit habe ich dich erhört, und am Tage des Heils habe ich dir geholfen\". Siehe, jetzt ist die wohlangenehme Zeit, siehe, jetzt ist der Tag des Heils);');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'indem wir in keiner Sache irgend einen Anstoß geben, auf daß der Dienst nicht verlästert werde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'sondern in allem uns erweisen als Gottes Diener, in vielem Ausharren, in Drangsalen, in Nöten, in Ängsten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'in Streichen, in Gefängnissen, in Aufständen, in Mühen, in Wachen, in Fasten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'in Reinheit, in Erkenntnis, in Langmut, in Gütigkeit, im Heiligen Geiste, in ungeheuchelter Liebe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'im Worte der Wahrheit, in der Kraft Gottes; durch die Waffen der Gerechtigkeit zur Rechten und zur Linken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'durch Ehre und Unehre, durch böses Gerücht und gutes Gerücht, als Verführer und Wahrhaftige;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'als Unbekannte und Wohlbekannte; als Sterbende, und siehe, wir leben; als Gezüchtigte und nicht getötet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'als Traurige, aber allezeit uns freuend; als Arme, aber viele reich machend; als nichts habend und alles besitzend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Unser Mund ist zu euch aufgetan, ihr Korinther; unser Herz ist weit geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Ihr seid nicht verengt in uns, sondern ihr seid verengt in eurem Innern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Zur gleichen Vergeltung aber (ich rede als zu Kindern) werdet auch ihr weit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Seid nicht in einem ungleichen Joche mit Ungläubigen. Denn welche Genossenschaft hat Gerechtigkeit und Gesetzlosigkeit? Oder welche Gemeinschaft Licht mit Finsternis?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'und welche Übereinstimmung Christus mit Belial? Oder welches Teil ein Gläubiger mit einem Ungläubigen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Und welchen Zusammenhang der Tempel Gottes mit Götzenbildern? Denn ihr seid der Tempel des lebendigen Gottes, wie Gott gesagt hat: \"Ich will unter ihnen wohnen und wandeln, und ich werde ihr Gott sein, und sie werden mein Volk sein\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Darum gehet aus ihrer Mitte aus und sondert euch ab, spricht der Herr, und rühret Unreines nicht an, und ich werde euch aufnehmen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'und ich werde euch zum Vater sein, und ihr werdet mir zu Söhnen und Töchtern sein, spricht der Herr, der Allmächtige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Da wir nun diese Verheißungen haben, Geliebte, so laßt uns uns selbst reinigen von jeder Befleckung des Fleisches und des Geistes, indem wir die Heiligkeit vollenden in der Furcht Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Nehmet uns auf; wir haben niemand unrecht getan, wir haben niemand verderbt, wir haben niemand übervorteilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Nicht zur Verurteilung rede ich; denn ich habe vorhin gesagt, daß ihr in unseren Herzen seid, um mit zu sterben und mit zu leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Groß ist meine Freimütigkeit gegen euch, groß mein Rühmen eurethalben; ich bin mit Trost erfüllt, ich bin ganz überströmend in der Freude bei all unserer Drangsal.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Denn auch als wir nach Macedonien kamen, hatte unser Fleisch keine Ruhe, sondern allenthalben waren wir bedrängt; von außen Kämpfe, von innen Befürchtungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Der aber die Niedrigen tröstet, Gott, tröstete uns durch die Ankunft des Titus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'Nicht allein aber durch seine Ankunft, sondern auch durch den Trost, womit er eurethalben getröstet wurde, als er uns kundtat eure Sehnsucht, euer Wehklagen, euren Eifer für mich, so daß ich mich um so mehr freute.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Denn wenn ich euch auch durch den Brief betrübt habe, so reut es mich nicht, wenn es mich auch gereut hat; denn ich sehe, daß jener Brief, wenn auch nur für eine Zeit, euch betrübt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Jetzt freue ich mich, nicht daß ihr betrübt worden, sondern daß ihr zur Buße betrübt worden seid; denn ihr seid Gott gemäß betrübt worden, auf daß ihr in nichts von uns Schaden erlittet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Denn die Betrübnis Gott gemäß bewirkt eine nie zu bereuende Buße zum Heil; die Betrübnis der Welt aber bewirkt den Tod.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Denn siehe, eben dieses, daß ihr Gott gemäß betrübt worden seid, wieviel Fleiß hat es bei euch bewirkt! Sogar Verantwortung, sogar Unwillen, sogar Furcht, sogar Sehnsucht, sogar Eifer, sogar Vergeltung. Ihr habt euch in allem erwiesen, daß ihr an der Sache rein seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'So denn, wenn ich euch auch geschrieben habe, so geschah es nicht um des Beleidigers, noch um des Beleidigten willen, sondern um deswillen, damit unser Fleiß für euch bei euch offenbar werde vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Deswegen sind wir getröstet worden; vielmehr aber freuten wir uns bei unserem Troste noch überschwenglicher über die Freude des Titus, weil sein Geist durch euch alle erquickt worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Denn wenn ich ihm etwas über euch gerühmt habe, so bin ich nicht zu Schanden geworden; sondern wie wir alles in Wahrheit zu euch geredet haben, also ist auch unser Rühmen gegen Titus Wahrheit geworden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'und seine innerlichen Gefühle sind überströmender gegen euch, indem er an euer aller Gehorsam gedenkt, wie ihr ihn mit Furcht und Zittern empfangen habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Ich freue mich, daß ich in allem Zuversicht betreffs euer habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Wir tun euch aber kund, Brüder, die Gnade Gottes, die in den Versammlungen Macedoniens gegeben worden ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'daß bei großer Drangsalsprüfung die Überströmung ihrer Freude und ihre tiefe Armut übergeströmt ist in den Reichtum ihrer Freigebigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Denn nach Vermögen, ich bezeuge es, und über Vermögen waren sie aus eigenem Antriebe willig,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'indem sie mit vielem Zureden uns um die Gnade und die Gemeinschaft des Dienstes für die Heiligen baten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'Und nicht wie wir hofften, sondern sie gaben sich selbst zuerst dem Herrn und uns durch Gottes Willen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'so daß wir Titus zugeredet haben, daß er wie er zuvor angefangen hatte, also auch bei euch auch diese Gnade vollbringen möchte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Aber so wie ihr in allem überströmend seid: in Glauben und Wort und Erkenntnis und allem Fleiß und in eurer Liebe zu uns, daß ihr auch in dieser Gnade überströmend sein möget.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Nicht befehlsweise spreche ich, sondern wegen des Fleißes der anderen, und indem ich die Echtheit eurer Liebe prüfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Denn ihr kennet die Gnade unseres Herrn Jesus Christus, daß er, da er reich war, um euretwillen arm wurde, auf daß ihr durch seine Armut reich würdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Und ich gebe hierin eine Meinung; denn dies ist euch nützlich, die ihr nicht allein das Tun, sondern auch das Wollen vorher angefangen habt seit vorigem Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Nun aber vollbringet auch das Tun, damit, gleichwie die Geneigtheit zum Wollen, also auch das Vollbringen da sei nach dem, was ihr habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Denn wenn die Geneigtheit vorliegt, so ist einer annehmlich nach dem er hat, und nicht nach dem er nicht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Denn nicht auf daß andere Erleichterung haben, ihr aber Bedrängnis, sondern nach der Gleichheit:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'in der jetzigen Zeit diene euer Überfluß für den Mangel jener, auf daß auch jener Überfluß für euren Mangel diene, damit Gleichheit werde; wie geschrieben steht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, '\"Wer viel sammelte, hatte nicht Überfluß, und wer wenig sammelte, hatte nicht Mangel\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Gott aber sei Dank, der denselben Eifer für euch in das Herz des Titus gegeben hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'denn er nahm zwar das Zureden an, aber weil er sehr eifrig war, ist er aus eigenem Antriebe zu euch gegangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Wir haben aber den Bruder mit ihm gesandt, dessen Lob im Evangelium durch alle Versammlungen verbreitet ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'Aber nicht allein das, sondern er ist auch von den Versammlungen gewählt worden zu unserem Reisegefährten mit dieser Gnade, die von uns bedient wird zur Herrlichkeit des Herrn selbst und als Beweis unserer Geneigtheit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'indem wir dies verhüten, daß uns nicht jemand übel nachrede dieser reichen Gabe halben, die von uns bedient wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'denn wir sind vorsorglich für das, was ehrbar ist, nicht allein vor dem Herrn, sondern auch vor den Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Wir haben aber unseren Bruder mit ihnen gesandt, den wir oft in vielen Stücken erprobt haben, daß er eifrig ist, nun aber noch viel eifriger durch große Zuversicht, die er zu euch hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Sei es, was Titus betrifft, er ist mein Genosse und in Bezug auf euch mein Mitarbeiter; seien es unsere Brüder, sie sind Gesandte der Versammlungen, Christi Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'So beweiset nun gegen sie, angesichts der Versammlungen, den Beweis eurer Liebe und unseres Rühmens über euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Denn was den Dienst für die Heiligen betrifft, so ist es überflüssig für mich, euch zu schreiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Denn ich kenne eure Geneigtheit, deren ich mich eurethalben gegen die Macedonier rühme, daß Achaja seit vorigem Jahre bereit gewesen ist; und der von euch ausgegangene Eifer hat viele angereizt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Ich habe aber die Brüder gesandt, auf daß nicht unser Rühmen über euch in dieser Beziehung zunichte würde, auf daß ihr, wie ich gesagt habe, bereit seid,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'damit nicht etwa, wenn die Macedonier mit mir kommen und euch unbereit finden, wir, daß wir nicht sagen ihr, in dieser Zuversicht zu Schanden würden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Ich hielt es daher für nötig, die Brüder zu bitten, daß sie zu euch vorauszögen und diesen euren zuvor angekündigten Segen vorher zubereiteten, daß er also bereit sei als Segen, und nicht als Habsucht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Dies aber sage ich: Wer sparsam sät, wird auch sparsam ernten, und wer segensreich sät, wird auch segensreich ernten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Ein jeder, wie er sich in seinem Herzen vorsetzt: nicht mit Verdruß oder aus Zwang, denn einen fröhlichen Geber hat Gott lieb.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Gott aber ist mächtig, jede Gnade gegen euch überströmen zu lassen, auf daß ihr in allem, allezeit alle Genüge habend, überströmend seid zu jedem guten Werke;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'wie geschrieben steht: \"Er hat ausgestreut, er hat den Armen gegeben; seine Gerechtigkeit bleibt in Ewigkeit\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Der aber Samen darreicht dem Sämann und Brot zur Speise, wird eure Saat darreichen und überströmend machen und die Früchte eurer Gerechtigkeit wachsen lassen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'indem ihr in allem reich geworden seid zu aller Freigebigkeit, welche durch uns Gott Danksagung bewirkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Denn die Bedienung dieses Dienstes ist nicht nur eine Erfüllung des Mangels der Heiligen, sondern ist auch überströmend durch viele Danksagungen gegen Gott;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'indem sie durch die Bewährung dieses Dienstes Gott verherrlichen wegen der Unterwürfigkeit eures Bekenntnisses zum Evangelium des Christus und wegen der Freigebigkeit der Mitteilung gegen sie und gegen alle;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'und in ihrem Flehen für euch, die sich nach euch sehnen wegen der überschwenglichen Gnade Gottes an euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Gott sei Dank für seine unaussprechliche Gabe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Ich selbst aber, Paulus, ermahne euch durch die Sanftmut und Gelindigkeit des Christus, der ich unter euch gegenwärtig zwar demütig, abwesend aber kühn gegen euch bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Ich flehe aber, daß ich anwesend nicht kühn sein müsse mit der Zuversicht, mit welcher ich gedenke, gegen etliche dreist zu sein, die uns als nach dem Fleische wandelnd erachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Denn obwohl wir im Fleische wandeln, kämpfen wir nicht nach dem Fleische;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'denn die Waffen unseres Kampfes sind nicht fleischlich, sondern göttlich mächtig zur Zerstörung von Festungen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'indem wir Vernunftschlüsse zerstören und jede Höhe, die sich erhebt wider die Erkenntnis Gottes, und jeden Gedanken gefangen nehmen unter den Gehorsam des Christus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'und bereit stehen, allen Ungehorsam zu rächen, wenn euer Gehorsam erfüllt sein wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Sehet ihr auf das, was vor Augen ist? Wenn jemand sich selbst zutraut, daß er Christi sei, so denke er dies wiederum bei sich selbst, daß, gleichwie er Christi ist, also auch wir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Denn falls ich mich auch etwas mehr über unsere Gewalt rühmen wollte, die uns der Herr zur Auferbauung und nicht zu eurer Zerstörung gegeben hat, so werde ich nicht zu Schanden werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'auf daß ich nicht scheine, als wolle ich euch durch die Briefe schrecken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Denn die Briefe, sagt man, sind gewichtig und kräftig, aber die Gegenwart des Leibes ist schwach und die Rede verächtlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Ein solcher denke dieses, daß, wie wir abwesend im Worte durch Briefe sind, wir solche auch anwesend in der Tat sein werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Denn wir wagen nicht, uns selbst etlichen derer beizuzählen oder zu vergleichen, die sich selbst empfehlen; sie aber, indem sie sich an sich selbst messen und sich mit sich selbst vergleichen, sind unverständig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Wir aber wollen uns nicht ins Maßlose rühmen, sondern nach dem Maße des Wirkungskreises, den der Gott des Maßes uns zugeteilt hat, um auch bis zu euch zu gelangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Denn wir strecken uns selbst nicht zu weit aus, als gelangten wir nicht bis zu euch (denn wir sind auch bis zu euch gekommen in dem Evangelium des Christus),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'indem wir uns nicht ins Maßlose rühmen in fremden Arbeiten, aber Hoffnung haben, wenn euer Glaube wächst, unter euch vergrößert zu werden nach unserem Wirkungskreise,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'um noch überströmender das Evangelium weiter über euch hinaus zu verkündigen, nicht in fremdem Wirkungskreise uns dessen zu rühmen, was schon bereit ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, '\"Wer sich aber rühmt, rühme sich des Herrn\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Denn nicht wer sich selbst empfiehlt, der ist bewährt, sondern den der Herr empfiehlt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Ich wollte, ihr möchtet ein wenig Torheit von mir ertragen; doch ertraget mich auch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Denn ich eifere um euch mit Gottes Eifer; denn ich habe euch einem Manne verlobt, um euch als eine keusche Jungfrau dem Christus darzustellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Ich fürchte aber, daß etwa, wie die Schlange Eva durch ihre List verführte, also auch euer Sinn verderbt und abgewandt werde von der Einfalt gegen den Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Denn wenn der, welcher kommt, einen anderen Jesus predigt, den wir nicht gepredigt haben, oder ihr einen anderen Geist empfanget, den ihr nicht empfangen habt, oder ein anderes Evangelium, das ihr nicht angenommen habt, so ertrüget ihr es gut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Denn ich achte, daß ich in nichts den ausgezeichnetsten Aposteln nachstehe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Wenn ich aber auch ein Unkundiger in der Rede bin, so doch nicht in der Erkenntnis; sondern in jeder Weise sind wir in allen Stücken gegen euch offenbar geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Oder habe ich eine Sünde begangen, indem ich mich selbst erniedrigte, auf daß ihr erhöht würdet, weil ich euch das Evangelium Gottes umsonst verkündigt habe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Andere Versammlungen habe ich beraubt, indem ich Lohn empfing zu eurer Bedienung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Und als ich bei euch anwesend war und Mangel litt, fiel ich niemand zur Last (denn meinen Mangel erstatteten die Brüder, die aus Macedonien kamen), und ich hielt mich in allem euch unbeschwerlich, und werde mich also halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Die Wahrheit Christi ist in mir, daß mir dieses Rühmen in den Gegenden von Achaja nicht verwehrt werden soll!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Warum? Weil ich euch nicht liebe? Gott weiß es.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Was ich aber tue, werde ich auch tun, auf daß ich denen die Gelegenheit abschneide, die eine Gelegenheit wollen, auf daß sie, worin sie sich rühmen, erfunden werden wie auch wir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Denn solche sind falsche Apostel, betrügerische Arbeiter, welche die Gestalt von Aposteln Christi annehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Und kein Wunder, denn der Satan selbst nimmt die Gestalt eines Engels des Lichts an;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'es ist daher nichts Großes, wenn auch seine Diener die Gestalt als Diener der Gerechtigkeit annehmen, deren Ende nach ihren Werken sein wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Wiederum sage ich: Niemand halte mich für töricht; wenn aber nicht, so nehmet mich doch auf als einen Törichten, auf daß auch ich mich ein wenig rühmen möge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Was ich rede, rede ich nicht nach dem Herrn, sondern als in Torheit, in dieser Zuversicht des Rühmens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Weil viele sich nach dem Fleische rühmen, so will auch ich mich rühmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Denn ihr ertraget gern die Toren, da ihr klug seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Denn ihr ertraget es, wenn jemand euch knechtet, wenn jemand euch aufzehrt, wenn jemand von euch nimmt, wenn jemand sich überhebt, wenn jemand euch ins Gesicht schlägt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Ich rede bezüglich der Unehre, als ob wir schwach gewesen wären. Worin aber irgend jemand dreist ist (ich rede in Torheit), bin auch ich dreist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Sind sie Hebräer? Ich auch. Sind sie Israeliten? Ich auch. Sind sie Abrahams Same? Ich auch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Sind sie Diener Christi? (ich rede als von Sinnen) Ich über die Maßen. In Mühen überschwenglicher, in Schlägen übermäßig, in Gefängnissen überschwenglicher, in Todesgefahren oft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Von den Juden habe ich fünfmal empfangen vierzig Streiche weniger einen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Dreimal bin ich mit Ruten geschlagen, einmal gesteinigt worden; dreimal habe ich Schiffbruch gelitten, einen Tag und eine Nacht habe ich in der Tiefe zugebracht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'oft auf Reisen, in Gefahren auf Flüssen, in Gefahren von Räubern, in Gefahren von meinem Geschlecht, in Gefahren von den Nationen, in Gefahren in der Stadt, in Gefahren in der Wüste, in Gefahren auf dem Meere, in Gefahren unter falschen Brüdern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'in Arbeit und Mühe, in Wachen oft, in Hunger und Durst, in Fasten oft, in Kälte und Blöße;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'außer dem, was außergewöhnlich ist, noch das, was täglich auf mich andringt: die Sorge um alle Versammlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Wer ist schwach, und ich bin nicht schwach? Wer wird geärgert, und ich brenne nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Wenn es gerühmt sein muß, so will ich mich dessen rühmen, was meine Schwachheit betrifft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Der Gott und Vater des Herrn Jesus, der gepriesen ist in Ewigkeit, weiß, daß ich nicht lüge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'In Damaskus verwahrte der Landpfleger des Königs Aretas die Stadt der Damascener, indem er mich greifen wollte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'und ich wurde durch ein Fenster in einem Korbe an der Mauer hinabgelassen und entrann seinen Händen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Zu rühmen nützt mir wahrlich nicht; denn ich will auf Gesichte und Offenbarungen des Herrn kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Ich kenne einen Menschen in Christo, vor vierzehn Jahren (ob im Leibe, weiß ich nicht, oder außer dem Leibe, weiß ich nicht; Gott weiß es), einen Menschen, der entrückt wurde bis in den dritten Himmel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Und ich kenne einen solchen Menschen (ob im Leibe oder außer dem Leibe, weiß ich nicht; Gott weiß es),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'daß er in das Paradies entrückt wurde und unaussprechliche Worte hörte, welche der Mensch nicht sagen darf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Über einen solchen werde ich mich rühmen; über mich selbst aber werde ich mich nicht rühmen, es sei denn meiner Schwachheiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Denn wenn ich mich rühmen will, werde ich nicht töricht sein, denn ich werde die Wahrheit sagen. Ich enthalte mich aber dessen, auf daß nicht jemand höher von mir denke, als was er an mir sieht, oder was er von mir hört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Und auf daß ich mich nicht durch die Überschwenglichkeit der Offenbarungen überhebe, wurde mir ein Dorn für das Fleisch gegeben, ein Engel Satans, auf daß er mich mit Fäusten schlage, auf daß ich mich nicht überhebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Für dieses flehte ich dreimal zum Herrn, auf daß er von mir abstehen möge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Und er hat zu mir gesagt: Meine Gnade genügt dir, denn meine Kraft wird in Schwachheit vollbracht. Daher will ich am allerliebsten mich vielmehr meiner Schwachheiten rühmen, auf daß die Kraft des Christus über mir wohne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Deshalb habe ich Wohlgefallen an Schwachheiten, an Schmähungen, an Nöten, an Verfolgungen, an Ängsten für Christum; denn wenn ich schwach bin, dann bin ich stark.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Ich bin ein Tor geworden; ihr habt mich dazu gezwungen. Denn ich hätte von euch empfohlen werden sollen, denn ich habe in nichts den ausgezeichnetsten Aposteln nachgestanden, wenn ich auch nichts bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Die Zeichen des Apostels sind ja unter euch vollbracht worden in allem Ausharren, in Zeichen und Wundern und mächtigen Taten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Denn was ist es, worin ihr gegen die anderen Versammlungen verkürzt worden seid, es sei denn, daß ich selbst euch nicht zur Last gefallen bin? Verzeihet mir dieses Unrecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Siehe, dieses dritte Mal stehe ich bereit, zu euch zu kommen, und werde nicht zur Last fallen, denn ich suche nicht das Eure, sondern euch. Denn die Kinder sollen nicht für die Eltern Schätze sammeln, sondern die Eltern für die Kinder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Ich will aber sehr gern alles verwenden und völlig verwendet werden für eure Seelen, wenn ich auch, je überschwenglicher ich euch liebe, um so weniger geliebt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Doch es sei so, ich habe euch nicht beschwert; weil ich aber schlau bin, so habe ich euch mit List gefangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Habe ich euch etwa durch einen von denen übervorteilt, die ich zu euch gesandt habe?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Ich habe Titus gebeten und den Bruder mit ihm gesandt; hat etwa Titus euch übervorteilt? Haben wir nicht in demselben Geiste gewandelt? nicht in denselben Fußstapfen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Seit langem seid ihr der Meinung, daß wir uns vor euch verantworten. Wir reden vor Gott in Christo, alles aber, Geliebte, zu eurer Auferbauung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Denn ich fürchte, daß, wenn ich komme, ich euch etwa nicht als solche finde, wie ich will, und daß ich von euch als solcher erfunden werde, wie ihr nicht wollet: daß etwa Streitigkeiten, Neid, Zorn, Zänkereien, Verleumdungen, Ohrenbläsereien, Aufgeblasenheit, Unordnungen vorhanden seien;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'daß, wenn ich wiederkomme, mein Gott mich eurethalben demütige, und ich über viele trauern müsse, die zuvor gesündigt und nicht Buße getan haben über die Unreinigkeit und Hurerei und Unzucht, die sie getrieben haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Dieses dritte Mal komme ich zu euch: aus zweier oder dreier Zeugen Mund wird jede Sache bestätigt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Ich habe zuvor gesagt und sage zuvor, als wie das zweite Mal anwesend und jetzt abwesend, denen, die zuvor gesündigt haben, und den übrigen allen, daß, wenn ich wiederum komme, ich nicht schonen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Weil ihr einen Beweis suchet, daß Christus in mir redet (der gegen euch nicht schwach ist, sondern mächtig unter euch;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'denn wenn er auch in Schwachheit gekreuzigt worden ist, so lebt er doch durch Gottes Kraft; denn auch wir sind schwach in ihm, aber wir werden mit ihm leben durch Gottes Kraft gegen euch),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'so prüfet euch selbst, ob ihr im Glauben seid, untersuchet euch selbst; oder erkennet ihr euch selbst nicht, daß Jesus Christus in euch ist? Es sei denn, daß ihr etwa unbewährt seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Ich hoffe aber, daß ihr erkennen werdet, daß wir nicht unbewährt sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Wir beten aber zu Gott, daß ihr nichts Böses tun möget; nicht auf daß wir bewährt erscheinen, sondern auf daß ihr tuet, was recht ist, wir aber wie Unbewährte seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Denn wir vermögen nichts wider die Wahrheit, sondern für die Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Denn wir freuen uns, wenn wir schwach sind, ihr aber mächtig seid; um dieses bitten wir auch, um eure Vervollkommnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Deswegen schreibe ich dieses abwesend, auf daß ich anwesend nicht Strenge gebrauchen müsse, nach der Gewalt, die der Herr mir gegeben hat zur Auferbauung und nicht zur Zerstörung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Übrigens, Brüder, freuet euch, werdet vollkommen, seid getrost, seid eines Sinnes, seid in Frieden, und der Gott der Liebe und des Friedens wird mit euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Grüßet einander mit heiligem Kuß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, '(G13:12) Es grüßen euch die Heiligen alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, '(G13:13) Die Gnade des Herrn Jesus Christus und die Liebe Gottes und die Gemeinschaft des Heiligen Geistes sei mit euch allen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paulus, Apostel, nicht von Menschen, noch durch einen Menschen, sondern durch Jesum Christum und Gott, den Vater, der ihn auferweckt hat aus den Toten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'und alle Brüder, die bei mir sind, den Versammlungen von Galatien:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Gnade euch und Friede von Gott, dem Vater, und unserem Herrn Jesus Christus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'der sich selbst für unsere Sünden hingegeben hat, damit er uns herausnehme aus der gegenwärtigen bösen Welt, nach dem Willen unseres Gottes und Vaters,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'welchem die Herrlichkeit sei von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Ich wundere mich, daß ihr so schnell von dem, der euch in der Gnade Christi berufen hat, zu einem anderen Evangelium umwendet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'welches kein anderes ist; nur daß etliche sind, die euch verwirren und das Evangelium des Christus verkehren wollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Aber wenn auch wir oder ein Engel aus dem Himmel euch etwas als Evangelium verkündigte außer dem, was wir euch als Evangelium verkündigt haben: er sei verflucht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Wie wir zuvor gesagt haben, so sage ich auch jetzt wiederum: Wenn jemand euch etwas als Evangelium verkündigt außer dem, was ihr empfangen habt: er sei verflucht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Denn suche ich jetzt Menschen zufrieden zu stellen, oder Gott? Oder suche ich Menschen zu gefallen? Wenn ich noch Menschen gefiele, so wäre ich Christi Knecht nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Ich tue euch aber kund, Brüder, daß das Evangelium, welches von mir verkündigt worden, nicht nach dem Menschen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Denn ich habe es weder von einem Menschen empfangen, noch erlernt, sondern durch Offenbarung Jesu Christi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Denn ihr habt von meinem ehemaligen Wandel in dem Judentum gehört, daß ich die Versammlung Gottes über die Maßen verfolgte und sie zerstörte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'und in dem Judentum zunahm über viele Altersgenossen in meinem Geschlecht, indem ich übermäßig ein Eiferer für meine väterlichen Überlieferungen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Als es aber Gott, der mich von meiner Mutter Leibe an abgesondert und durch seine Gnade berufen hat, wohlgefiel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'seinen Sohn in mir zu offenbaren, auf daß ich ihn unter den Nationen verkündigte, ging ich alsbald nicht mit Fleisch und Blut zu Rate');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'und ging auch nicht hinauf nach Jerusalem zu denen, die vor mir Apostel waren, sondern ich ging fort nach Arabien und kehrte wiederum nach Damaskus zurück.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Darauf, nach drei Jahren, ging ich nach Jerusalem hinauf, um Kephas kennen zu lernen, und blieb fünfzehn Tage bei ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Ich sah aber keinen anderen der Apostel, außer Jakobus, den Bruder des Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Was ich euch aber schreibe, siehe, vor Gott! Ich lüge nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Darauf kam ich in die Gegenden von Syrien und Cilicien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Ich war aber den Versammlungen von Judäa, die in Christo sind, von Angesicht unbekannt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'sie hatten aber nur gehört: Der, welcher uns einst verfolgte, verkündigt jetzt den Glauben, den er einst zerstörte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'Und sie verherrlichten Gott an mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Darauf, nach Verlauf von vierzehn Jahren, zog ich wieder nach Jerusalem hinauf mit Barnabas und nahm auch Titus mit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Ich zog aber hinauf zufolge einer Offenbarung und legte ihnen das Evangelium vor, das ich unter den Nationen predige, im besonderen aber den Angesehenen, damit ich nicht etwa vergeblich laufe oder gelaufen wäre;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, '(aber auch Titus, der bei mir war, wurde, obwohl er ein Grieche war, nicht gezwungen, sich beschneiden zu lassen)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'es war aber der nebeneingeführten falschen Brüder wegen, die nebeneingekommen waren, um unsere Freiheit auszukundschaften, welche wir in Christo Jesu haben, auf daß sie uns in Knechtschaft brächten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'denen wir auch nicht eine Stunde durch Unterwürfigkeit nachgegeben haben, auf daß die Wahrheit des Evangeliums bei euch verbliebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Von denen aber, die in Ansehen standen, was irgend sie auch waren, das macht keinen Unterschied für mich, Gott nimmt keines Menschen Person an, denn mir haben die Angesehenen nichts hinzugefügt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'sondern im Gegenteil, als sie sahen, daß mir das Evangelium der Vorhaut anvertraut war, gleichwie Petrus das der Beschneidung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(denn der, welcher in Petrus für das Apostelamt der Beschneidung gewirkt hat, hat auch in mir in Bezug auf die Nationen gewirkt)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'und als sie die Gnade erkannten, die mir gegeben ist, gaben Jakobus und Kephas und Johannes, die als Säulen angesehen wurden, mir und Barnabas die Rechte der Gemeinschaft, auf daß wir unter die Nationen, sie aber unter die Beschneidung gingen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'nur daß wir der Armen eingedenk wären, dessen ich mich auch befleißigt habe, also zu tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Als aber Kephas nach Antiochien kam, widerstand ich ihm ins Angesicht, weil er dem Urteil verfallen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Denn bevor etliche von Jakobus kamen, hatte er mit denen aus den Nationen gegessen; als sie aber kamen, zog er sich zurück und sonderte sich ab, da er sich vor denen aus der Beschneidung fürchtete.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Und mit ihm heuchelten auch die übrigen Juden, so daß selbst Barnabas durch ihre Heuchelei mitfortgerissen wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Als ich aber sah, daß sie nicht den geraden Weg nach der Wahrheit des Evangeliums wandelten, sprach ich zu Kephas vor allen: Wenn du, der du ein Jude bist, wie die Nationen lebst und nicht wie die Juden, wie zwingst du denn die Nationen, jüdisch zu leben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Wir, von Natur Juden und nicht Sünder aus den Nationen, aber wissend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'daß der Mensch nicht aus Gesetzeswerken gerechtfertigt wird, sondern nur durch den Glauben an Jesum Christum, auch wir haben an Christum Jesum geglaubt, auf daß wir aus Glauben an Christum gerechtfertigt würden, und nicht aus Gesetzeswerken, weil aus Gesetzeswerken kein Fleisch gerechtfertigt werden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Wenn wir aber, indem wir in Christo gerechtfertigt zu werden suchen, auch selbst als Sünder erfunden worden sind, ist denn Christus ein Diener der Sünde? Das sei ferne!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Denn wenn ich das, was ich abgebrochen habe, wiederum aufbaue, so stelle ich mich selbst als Übertreter dar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Denn ich bin durchs Gesetz dem Gesetz gestorben, auf daß ich Gott lebe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'ich bin mit Christo gekreuzigt, und nicht mehr lebe ich, sondern Christus lebt in mir; was ich aber jetzt lebe im Fleische, lebe ich durch Glauben, durch den an den Sohn Gottes, der mich geliebt und sich selbst für mich hingegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Ich mache die Gnade Gottes nicht ungültig; denn wenn Gerechtigkeit durch Gesetz kommt, dann ist Christus umsonst gestorben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'O unverständige Galater! Wer hat euch bezaubert, denen Jesus Christus, als unter euch gekreuzigt, vor Augen gemalt wurde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Dies allein will ich von euch lernen: Habt ihr den Geist aus Gesetzeswerken empfangen, oder aus der Kunde des Glaubens?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Seid ihr so unverständig? Nachdem ihr im Geiste angefangen habt, wollt ihr jetzt im Fleische vollenden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Habt ihr so vieles vergeblich gelitten? wenn anders auch vergeblich?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Der euch nun den Geist darreicht und Wunderwerke unter euch wirkt, ist es aus Gesetzeswerken oder aus der Kunde des Glaubens?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Gleichwie Abraham Gott glaubte, und es ihm zur Gerechtigkeit gerechnet wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Erkennet denn: die aus Glauben sind, diese sind Abrahams Söhne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Die Schrift aber, voraussehend, daß Gott die Nationen aus Glauben rechtfertigen würde, verkündigte dem Abraham die gute Botschaft zuvor: \"In dir werden gesegnet werden alle Nationen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Also werden die, welche aus Glauben sind, mit dem gläubigen Abraham gesegnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Denn so viele aus Gesetzeswerken sind, sind unter dem Fluche; denn es steht geschrieben: \"Verflucht ist jeder, der nicht bleibt in allem, was im Buche des Gesetzes geschrieben ist, um es zu tun!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Daß aber durch Gesetz niemand vor Gott gerechtfertigt wird, ist offenbar, denn \"der Gerechte wird aus Glauben leben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Das Gesetz aber ist nicht aus Glauben, sondern: \"Wer diese Dinge getan hat, wird durch sie leben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Christus hat uns losgekauft von dem Fluche des Gesetzes, indem er ein Fluch für uns geworden ist (denn es steht geschrieben: \"Verflucht ist jeder, der am Holze hängt!\");');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'auf daß der Segen Abrahams in Christo Jesu zu den Nationen käme, auf daß wir die Verheißung des Geistes empfingen durch den Glauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Brüder, ich rede nach Menschenweise; selbst eines Menschen Bund, der bestätigt ist, hebt niemand auf oder verordnet etwas hinzu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Dem Abraham aber waren die Verheißungen zugesagt und seinem Samen. Er sagt nicht: \"und den Samen\", als von vielen, sondern als von einem: \"und deinem Samen\", welcher Christus ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Dieses aber sage ich: Einen vorher von Gott bestätigten Bund macht das vierhundertdreißig Jahre danach entstandene Gesetz nicht ungültig, um die Verheißung aufzuheben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Denn wenn die Erbschaft aus Gesetz ist, so nicht mehr aus Verheißung: dem Abraham aber hat Gott sie durch Verheißung geschenkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Warum nun das Gesetz? Es wurde der Übertretungen wegen hinzugefügt (bis der Same käme, dem die Verheißung gemacht war), angeordnet durch Engel in der Hand eines Mittlers.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Ein Mittler aber ist nicht Mittler von einem; Gott aber ist einer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Ist denn das Gesetz wider die Verheißungen Gottes? Das sei ferne! Denn wenn ein Gesetz gegeben worden wäre, das lebendig zu machen vermöchte, dann wäre wirklich die Gerechtigkeit aus Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Die Schrift aber hat alles unter die Sünde eingeschlossen, auf daß die Verheißung aus Glauben an Jesum Christum denen gegeben würde, die da glauben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Bevor aber der Glaube kam, wurden wir unter dem Gesetz verwahrt, eingeschlossen auf den Glauben hin, der geoffenbart werden sollte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Also ist das Gesetz unser Zuchtmeister gewesen auf Christum hin, auf daß wir aus Glauben gerechtfertigt würden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Da aber der Glaube gekommen ist, sind wir nicht mehr unter einem Zuchtmeister;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'denn ihr alle seid Söhne Gottes durch den Glauben an Christum Jesum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Denn so viele euer auf Christum getauft worden sind, ihr habt Christum angezogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Da ist nicht Jude noch Grieche, da ist nicht Sklave noch Freier, da ist nicht Mann und Weib; denn ihr alle seid einer in Christo Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Wenn ihr aber Christi seid, so seid ihr denn Abrahams Same und nach Verheißung Erben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Ich sage aber: Solange der Erbe unmündig ist, unterscheidet er sich in nichts von einem Knechte, wiewohl er Herr ist von allem;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'sondern er ist unter Vormündern und Verwaltern bis zu der vom Vater festgesetzten Frist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Also auch wir, als wir Unmündige waren, waren wir geknechtet unter die Elemente der Welt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Als aber die Fülle der Zeit gekommen war, sandte Gott seinen Sohn, geboren von einem Weibe, geboren unter Gesetz,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'auf daß er die, welche unter Gesetz waren, loskaufte, auf daß wir die Sohnschaft empfingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Weil ihr aber Söhne seid, so hat Gott den Geist seines Sohnes in unsere Herzen gesandt, der da ruft: Abba, Vater!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Also bist du nicht mehr Knecht, sondern Sohn; wenn aber Sohn, so auch Erbe durch Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Aber damals freilich, als ihr Gott nicht kanntet, dientet ihr denen, die von Natur nicht Götter sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'jetzt aber, da ihr Gott erkannt habt, vielmehr aber von Gott erkannt worden seid, wie wendet ihr wieder um zu den schwachen und armseligen Elementen, denen ihr wieder von neuem dienen wollt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Ihr beobachtet Tage und Monate und Zeiten und Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Ich fürchte um euch, ob ich nicht etwa vergeblich an euch gearbeitet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Seid wie ich, denn auch ich bin wie ihr, Brüder, ich bitte euch; ihr habt mir nichts zuleide getan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Ihr wisset aber, daß ich in Schwachheit des Fleisches euch ehedem das Evangelium verkündigt habe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'und meine Versuchung, die in meinem Fleische war, habt ihr nicht verachtet noch verabscheut, sondern wie einen Engel Gottes nahmet ihr mich auf, wie Christum Jesum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Was war denn eure Glückseligkeit? Denn ich gebe euch Zeugnis, daß ihr, wenn möglich, eure Augen ausgerissen und mir gegeben hättet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Bin ich also euer Feind geworden, weil ich euch die Wahrheit sage?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Sie eifern um euch nicht gut, sondern sie wollen euch ausschließen, auf daß ihr um sie eifert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Es ist aber gut, allezeit im Guten zu eifern, und nicht allein, wenn ich bei euch gegenwärtig bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Meine Kindlein, um die ich abermals Geburtswehen habe, bis Christus in euch gestaltet worden ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'ich wünschte aber jetzt bei euch gegenwärtig zu sein und meine Stimme umzuwandeln, denn ich bin eurethalben in Verlegenheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Saget mir, die ihr unter Gesetz sein wollt, höret ihr das Gesetz nicht?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Denn es steht geschrieben, daß Abraham zwei Söhne hatte, einen von der Magd und einen von der Freien;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'aber der von der Magd war nach dem Fleische geboren, der aber von der Freien durch die Verheißung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'was einen bildlichen Sinn hat; denn diese sind zwei Bündnisse: eines vom Berge Sinai, das zur Knechtschaft gebiert, welches Hagar ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Denn Hagar ist der Berg Sinai in Arabien, entspricht aber dem jetzigen Jerusalem, denn sie ist mit ihren Kindern in Knechtschaft;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'aber das Jerusalem droben ist frei, welches unsere Mutter ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Denn es steht geschrieben: \"Sei fröhlich, du Unfruchtbare, die du nicht gebierst; brich in Jubel aus und schreie, die du keine Geburtswehen hast! Denn die Kinder der Einsamen sind zahlreicher als derjenigen, die den Mann hat.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Ihr aber, Brüder seid, gleichwie Isaak, Kinder der Verheißung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Aber so wie damals der nach dem Fleische Geborene den nach dem Geiste Geborenen verfolgte, also auch jetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Aber was sagt die Schrift? \"Stoße hinaus die Magd und ihren Sohn, denn der Sohn der Magd soll nicht erben mit dem Sohne der Freien.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Also, Brüder, sind wir nicht Kinder der Magd, sondern der Freien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Für die Freiheit hat Christus uns freigemacht; stehet nun fest und lasset euch nicht wiederum unter einem Joche der Knechtschaft halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Siehe, ich, Paulus, sage euch, daß wenn ihr beschnitten werdet, Christus euch nichts nützen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Ich bezeuge aber wiederum jedem Menschen, der beschnitten wird, daß er das ganze Gesetz zu tun schuldig ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Ihr seid abgetrennt von dem Christus, so viele ihr im Gesetz gerechtfertigt werdet; ihr seid aus der Gnade gefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Denn wir erwarten durch den Geist aus Glauben die Hoffnung der Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Denn in Christo Jesu vermag weder Beschneidung noch Vorhaut etwas, sondern der Glaube, der durch die Liebe wirkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Ihr liefet gut; wer hat euch aufgehalten, daß ihr der Wahrheit nicht gehorchet?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Die Überredung ist nicht von dem, der euch beruft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Ein wenig Sauerteig durchsäuert den ganzen Teig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Ich habe Vertrauen zu euch im Herrn, daß ihr nicht anders gesinnt sein werdet; wer euch aber verwirrt, wird das Urteil tragen, wer er auch sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Ich aber, Brüder, wenn ich noch Beschneidung predige, was werde ich noch verfolgt? Dann ist ja das Ärgernis des Kreuzes hinweggetan.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Ich wollte, daß sie sich auch abschnitten, die euch aufwiegeln!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Denn ihr seid zur Freiheit berufen worden, Brüder; allein gebrauchet nicht die Freiheit zu einem Anlaß für das Fleisch, sondern durch die Liebe dienet einander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Denn das ganze Gesetz ist in einem Worte erfüllt, in dem: \"Du sollst deinen Nächsten lieben wie dich selbst\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Wenn ihr aber einander beißet und fresset, so sehet zu, daß ihr nicht voneinander verzehrt werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Ich sage aber: Wandelt im Geiste, und ihr werdet die Lust des Fleisches nicht vollbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Denn das Fleisch gelüstet wider den Geist, der Geist aber wider das Fleisch; diese aber sind einander entgegengesetzt, auf daß ihr nicht das tuet, was ihr wollt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Wenn ihr aber durch den Geist geleitet werdet, so seid ihr nicht unter Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Offenbar aber sind die Werke des Fleisches, welche sind: Hurerei, Unreinigkeit, Ausschweifung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'Götzendienst, Zauberei, Feindschaft, Hader, Eifersucht, Zorn, Zank, Zwietracht, Sekten, Neid, Totschlag,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Trunkenheit, Gelage und dergleichen, von denen ich euch vorhersage, gleichwie ich auch vorhergesagt habe, daß, die solches tun, das Reich Gottes nicht ererben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Die Frucht des Geistes aber ist: Liebe, Freude, Friede Langmut, Freundlichkeit, Gütigkeit, Treue, Sanftmut, Enthaltsamkeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'wider solche gibt es kein Gesetz.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Die aber des Christus sind, haben das Fleisch gekreuzigt samt den Leidenschaften und Lüsten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Wenn wir durch den Geist leben, so laßt uns auch durch den Geist wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Laßt uns nicht eitler Ehre geizig sein, indem wir einander herausfordern, einander beneiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Brüder! Wenn auch ein Mensch von einem Fehltritt übereilt würde, so bringet ihr, die Geistlichen, einen solchen wieder zurecht im Geiste der Sanftmut, indem du auf dich selbst siehst, daß nicht auch du versucht werdest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Einer trage des anderen Lasten, und also erfüllet das Gesetz des Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Denn wenn jemand meint, etwas zu sein, da er doch nichts ist, so betrügt er sich selbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Ein jeder aber prüfe sein eigenes Werk, und dann wird er an sich selbst allein und nicht an dem anderen Ruhm haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'denn ein jeder wird seine eigene Last tragen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Wer in dem Worte unterwiesen wird, teile aber von allerlei Gutem dem mit, der ihn unterweist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Irret euch nicht, Gott läßt sich nicht spotten! Denn was irgend ein Mensch sät, das wird er auch ernten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Denn wer für sein eigenes Fleisch sät, wird von dem Fleische Verderben ernten; wer aber für den Geist sät, wird von dem Geiste ewiges Leben ernten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Laßt uns aber im Gutestun nicht müde werden, denn zu seiner Zeit werden wir ernten, wenn wir nicht ermatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Also nun, wie wir Gelegenheit haben, laßt uns das Gute wirken gegen alle, am meisten aber gegen die Hausgenossen des Glaubens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Sehet, welch einen langen Brief ich euch geschrieben habe mit eigener Hand!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'So viele im Fleische wohl angesehen sein wollen, die nötigen euch, beschnitten zu werden, nur auf daß sie nicht um des Kreuzes Christi willen verfolgt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Denn auch sie, die beschnitten sind, beobachten selbst das Gesetz nicht, sondern sie wollen, daß ihr beschnitten werdet, auf daß sie sich eures Fleisches rühmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Von mir aber sei es ferne, mich zu rühmen, als nur des Kreuzes unseres Herrn Jesus Christus, durch welchen mir die Welt gekreuzigt ist, und ich der Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Denn weder Beschneidung noch Vorhaut ist etwas, sondern eine neue Schöpfung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Und so viele nach dieser Richtschnur wandeln werden, Friede über sie und Barmherzigkeit, und über den Israel Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Hinfort mache mir keiner Mühe, denn ich trage die Malzeichen des Herrn Jesus an meinem Leibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Die Gnade unseres Herrn Jesus Christus sei mit eurem Geiste, Brüder! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paulus, Apostel Jesu Christi durch Gottes willen, den Heiligen und Treuen in Christo Jesu, die in Ephesus sind:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Gnade euch und Friede von Gott, unserem Vater, und dem Herrn Jesus Christus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Gepriesen sei der Gott und Vater unseres Herrn Jesus Christus, der uns gesegnet hat mit jeder geistlichen Segnung in den himmlischen Örtern in Christo,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'wie er uns auserwählt hat in ihm vor Grundlegung der Welt, daß wir heilig und tadellos seien vor ihm in Liebe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'und uns zuvorbestimmt hat zur Sohnschaft durch Jesum Christum für sich selbst nach dem Wohlgefallen seines Willens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'zum Preise der Herrlichkeit seiner Gnade, worin er uns begnadigt hat in dem Geliebten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'in welchem wir die Erlösung haben durch sein Blut, die Vergebung der Vergehungen, nach dem Reichtum seiner Gnade,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'welche er gegen uns hat überströmen lassen in aller Weisheit und Einsicht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'indem er uns kundgetan hat das Geheimnis seines Willens, nach seinem Wohlgefallen, das er sich vorgesetzt hat in sich selbst');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'für die Verwaltung der Fülle der Zeiten: alles unter ein Haupt zusammenzubringen in dem Christus, das was in den Himmeln und das, was auf der Erde ist, in ihm,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'in welchem wir auch ein Erbteil erlangt haben, die wir zuvorbestimmt sind nach dem Vorsatz dessen, der alles wirkt nach dem Rate seines Willens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'damit wir zum Preise seiner Herrlichkeit seien, die wir zuvor auf den Christus gehofft haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'auf welchen auch ihr gehofft, nachdem ihr gehört habt das Wort der Wahrheit, das Evangelium eures Heils, in welchem ihr auch, nachdem ihr geglaubt habt, versiegelt worden seid mit dem Heiligen Geiste der Verheißung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'welcher das Unterpfand unseres Erbes ist, zur Erlösung des erworbenen Besitzes, zum Preise seiner Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Weshalb auch ich, nachdem ich gehört habe von dem Glauben an den Herrn Jesus, der in euch ist, und von der Liebe, die ihr zu allen Heiligen habt, nicht aufhöre,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'für euch zu danken, euer erwähnend in meinen Gebeten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'auf daß der Gott unseres Herrn Jesus Christus, der Vater der Herrlichkeit, euch gebe den Geist der Weisheit und Offenbarung in der Erkenntnis seiner selbst, damit ihr,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'erleuchtet an den Augen eures Herzens, wisset, welches die Hoffnung seiner Berufung ist, und welches der Reichtum der Herrlichkeit seines Erbes in den Heiligen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'und welches die überschwengliche Größe seiner Kraft an uns, den Glaubenden, nach der Wirksamkeit der Macht seiner Stärke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'in welcher er gewirkt hat in dem Christus, indem er ihn aus den Toten auferweckte (und er setzte ihn zu seiner Rechten in den himmlischen Örtern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'über jedes Fürstentum und jede Gewalt und Kraft und Herrschaft und jeden Namen, der genannt wird, nicht allein in diesem Zeitalter, sondern auch in dem zukünftigen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'und hat alles seinen Füßen unterworfen und ihn als Haupt über alles der Versammlung gegeben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'welche sein Leib ist, die Fülle dessen, der alles in allem erfüllt);');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'auch euch, die ihr tot waret in euren Vergehungen und Sünden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'in welchen ihr einst wandeltet nach dem Zeitlauf dieser Welt, nach dem Fürsten der Gewalt der Luft, des Geistes, der jetzt wirksam ist in den Söhnen des Ungehorsams;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'unter welchen auch wir einst alle unseren Verkehr hatten in den Lüsten unseres Fleisches, indem wir den Willen des Fleisches und der Gedanken taten und von Natur Kinder des Zorns waren, wie auch die übrigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Gott aber, der reich ist an Barmherzigkeit, wegen seiner vielen Liebe, womit er uns geliebt hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'als auch wir in den Vergehungen tot waren, hat uns mit dem Christus lebendig gemacht, durch Gnade seid ihr errettet-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'und hat uns mitauferweckt und mitsitzen lassen in den himmlischen Örtern in Christo Jesu,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'auf daß er in den kommenden Zeitaltern den überschwenglichen Reichtum seiner Gnade in Güte gegen uns erwiese in Christo Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Denn durch die Gnade seid ihr errettet, mittelst des Glaubens; und das nicht aus euch, Gottes Gabe ist es;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'nicht aus Werken, auf daß niemand sich rühme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Denn wir sind sein Werk, geschaffen in Christo Jesu zu guten Werken, welche Gott zuvor bereitet hat, auf daß wir in ihnen wandeln sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Deshalb seid eingedenk, daß ihr, einst die Nationen im Fleische, welche Vorhaut genannt werden von der sogenannten Beschneidung, die im Fleische mit Händen geschieht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'daß ihr zu jener Zeit ohne Christum waret, entfremdet dem Bürgerrecht Israels, und Fremdlinge betreffs der Bündnisse der Verheißung, keine Hoffnung habend, und ohne Gott in der Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Jetzt aber, in Christo Jesu, seid ihr, die ihr einst fern waret, durch das Blut des Christus nahe geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Denn er ist unser Friede, der aus beiden eines gemacht und abgebrochen hat die Zwischenwand der Umzäunung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'nachdem er in seinem Fleische die Feindschaft, das Gesetz der Gebote in Satzungen, hinweggetan hatte, auf daß er die zwei, Frieden stiftend, in sich selbst zu einem neuen Menschen schüfe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'und die beiden in einem Leibe mit Gott versöhnte durch das Kreuz, nachdem er durch dasselbe die Feindschaft getötet hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Und er kam und verkündigte Frieden, euch, den Fernen, und Frieden den Nahen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Denn durch ihn haben wir beide den Zugang durch einen Geist zu dem Vater.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Also seid ihr denn nicht mehr Fremdlinge und ohne Bürgerrecht, sondern ihr seid Mitbürger der Heiligen und Hausgenossen Gottes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'aufgebaut auf die Grundlage der Apostel und Propheten, indem Jesus Christus selbst Eckstein ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'in welchem der ganze Bau, wohl zusammengefügt, wächst zu einem heiligen Tempel im Herrn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'in welchem auch ihr mitaufgebaut werdet zu einer Behausung Gottes im Geiste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Dieserhalb ich, Paulus, der Gefangene Christi Jesu für euch, die Nationen-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, '(wenn ihr anders gehört habt von der Verwaltung der Gnade Gottes, die mir in Bezug auf euch gegeben ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'daß mir durch Offenbarung das Geheimnis kundgetan worden, wie ich es zuvor in kurzem beschrieben habe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'woran ihr im Lesen merken könnt mein Verständnis in dem Geheimnis des Christus-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'welches in anderen Geschlechtern den Söhnen der Menschen nicht kundgetan worden, wie es jetzt geoffenbart worden ist seinen heiligen Aposteln und Propheten im Geiste:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'daß die aus den Nationen Miterben seien und Miteinverleibte und Mitteilhaber seiner Verheißung in Christo Jesu durch das Evangelium,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'dessen Diener ich geworden bin nach der Gabe der Gnade Gottes, die mir gegeben ist nach der Wirksamkeit seiner Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Mir, dem Allergeringsten von allen Heiligen, ist diese Gnade gegeben worden, unter den Nationen den unausforschlichen Reichtum des Christus zu verkündigen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'und alle zu erleuchten, welches die Verwaltung des Geheimnisses sei, das von den Zeitaltern her verborgen war in Gott, der alle Dinge geschaffen hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'auf daß jetzt den Fürstentümern und den Gewalten in den himmlischen Örtern durch die Versammlung kundgetan werde die gar mannigfaltige Weisheit Gottes, nach dem ewigen Vorsatz,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'den er gefaßt hat in Christo Jesu, unserem Herrn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'in welchem wir die Freimütigkeit haben und den Zugang in Zuversicht durch den Glauben an ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Deshalb bitte ich, nicht mutlos zu werden durch meine Drangsale für euch, welche eure Ehre sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Dieserhalb beuge ich meine Knie vor dem Vater unseres Herrn Jesus Christus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'von welchem jede Familie in den Himmeln und auf Erden benannt wird,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'auf daß er euch gebe, nach dem Reichtum seiner Herrlichkeit mit Kraft gestärkt zu werden durch seinen Geist an dem inneren Menschen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'daß der Christus durch den Glauben in euren Herzen wohne, indem ihr in Liebe gewurzelt und gegründet seid,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'auf daß ihr völlig zu erfassen vermöget mit allen Heiligen, welches die Breite und Länge und Tiefe und Höhe sei,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'und zu erkennen die die Erkenntnis übersteigende Liebe des Christus, auf daß ihr erfüllt sein möget zu der ganzen Fülle Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Dem aber, der über alles hinaus zu tun vermag, über die Maßen mehr, als was wir erbitten oder erdenken, nach der Kraft, die in uns wirkt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'ihm sei die Herrlichkeit in der Versammlung in Christo Jesu, auf alle Geschlechter des Zeitalters der Zeitalter hin! Amen.) -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Ich ermahne euch nun, ich, der Gefangene im Herrn, daß ihr würdig wandelt der Berufung, mit welcher ihr berufen worden seid,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'mit aller Demut und Sanftmut, mit Langmut, einander ertragend in Liebe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'euch befleißigend, die Einheit des Geistes zu bewahren in dem Bande des Friedens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Da ist ein Leib und ein Geist, wie ihr auch berufen worden seid in einer Hoffnung eurer Berufung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Ein Herr, ein Glaube, eine Taufe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'ein Gott und Vater aller, der da ist über allen und durch alle und in uns allen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Jedem einzelnen aber von uns ist die Gnade gegeben worden nach dem Maße der Gabe des Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Darum sagt er: \"Hinaufgestiegen in die Höhe, hat er die Gefangenschaft gefangen geführt und den Menschen Gaben gegeben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Das aber: Er ist hinaufgestiegen, was ist es anders, als daß er auch hinabgestiegen ist in die unteren Teile der Erde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Der hinabgestiegen ist, ist derselbe, der auch hinaufgestiegen ist über alle Himmel, auf daß er alles erfüllte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Und er hat die einen gegeben als Apostel und andere als Propheten und andere als Evangelisten und andere als Hirten und Lehrer,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'zur Vollendung der Heiligen, für das Werk des Dienstes, für die Auferbauung des Leibes Christi,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'bis wir alle hingelangen zu der Einheit des Glaubens und zur Erkenntnis des Sohnes Gottes, zu dem erwachsenen Manne, zu dem Maße des vollen Wuchses der Fülle des Christus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'auf daß wir nicht mehr Unmündige seien, hin-und hergeworfen und umhergetrieben von jedem Winde der Lehre, die da kommt durch die Betrügerei der Menschen, durch ihre Verschlagenheit zu listig ersonnenem Irrtum;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'sondern die Wahrheit festhaltend in Liebe, laßt uns in allem heranwachsen zu ihm hin, der das Haupt ist, der Christus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'aus welchem der ganze Leib, wohl zusammengefügt und verbunden durch jedes Gelenk der Darreichung, nach der Wirksamkeit in dem Maße jedes einzelnen Teiles, für sich das Wachstum des Leibes bewirkt zu seiner Selbstauferbauung in Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Dieses nun sage und bezeuge ich im Herrn, daß ihr forthin nicht wandelt, wie auch die übrigen Nationen wandeln, in Eitelkeit ihres Sinnes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'verfinstert am Verstande, entfremdet dem Leben Gottes wegen der Unwissenheit, die in ihnen ist, wegen der Verstockung ihres Herzens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'welche, da sie alle Empfindung verloren, sich selbst der Ausschweifung hingegeben haben, alle Unreinigkeit mit Gier auszuüben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Ihr aber habt den Christus nicht also gelernt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'wenn ihr anders ihn gehört habt und in ihm gelehrt worden seid, wie die Wahrheit in dem Jesus ist:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'daß ihr, was den früheren Lebenswandel betrifft, abgelegt habt den alten Menschen, der nach den betrügerischen Lüsten verdorben wird,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'aber erneuert werdet in dem Geiste eurer Gesinnung');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'und angezogen habt den neuen Menschen, der nach Gott geschaffen ist in wahrhaftiger Gerechtigkeit und Heiligkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Deshalb, da ihr die Lüge abgelegt habt, redet Wahrheit, ein jeder mit seinem Nächsten, denn wir sind Glieder voneinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Zürnet, und sündiget nicht. Die Sonne gehe nicht unter über eurem Zorn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'und gebet nicht Raum dem Teufel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Wer gestohlen hat, stehle nicht mehr, sondern arbeite vielmehr und wirke mit seinen Händen das Gute, auf daß er dem Dürftigen mitzuteilen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Kein faules Wort gehe aus eurem Munde, sondern das irgend gut ist zur notwendigen Erbauung, auf daß es den Hörenden Gnade darreiche.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Und betrübet nicht den Heiligen Geist Gottes, durch welchen ihr versiegelt worden seid auf den Tag der Erlösung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Alle Bitterkeit und Wut und Zorn und Geschrei und Lästerung sei von euch weggetan, samt aller Bosheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Seid aber gegeneinander gütig, mitleidig, einander vergebend, gleichwie auch Gott in Christo euch vergeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Seid nun Nachahmer Gottes, als geliebte Kinder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'und wandelt in Liebe, gleichwie auch der Christus uns geliebt und sich selbst für uns hingegeben hat als Darbringung und Schlachtopfer, Gott zu einem duftenden Wohlgeruch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Hurerei aber und alle Unreinigkeit oder Habsucht werde nicht einmal unter euch genannt, gleichwie es Heiligen geziemt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'auch Schändlichkeit und albernes Geschwätz oder Witzelei, welche sich nicht geziemen, sondern vielmehr Danksagung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Denn dieses wisset und erkennet ihr, daß kein Hurer oder Unreiner oder Habsüchtiger, (welcher ein Götzendiener ist) ein Erbteil hat in dem Reiche Christi und Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Niemand verführe euch mit eitlen Worten, denn dieser Dinge wegen kommt der Zorn Gottes über die Söhne des Ungehorsams.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Seid nun nicht ihre Mitgenossen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Denn einst waret ihr Finsternis, jetzt aber seid ihr Licht in dem Herrn; wandelt als Kinder des Lichts,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(denn die Frucht des Lichts besteht in aller Gütigkeit und Gerechtigkeit und Wahrheit),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'indem ihr prüfet, was dem Herrn wohlgefällig ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Und habet nicht Gemeinschaft mit den unfruchtbaren Werken der Finsternis, vielmehr aber strafet sie auch;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'denn was heimlich von ihnen geschieht, ist schändlich selbst zu sagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Alles aber, was bloßgestellt wird, wird durch das Licht offenbar gemacht; denn das Licht ist es, welches alles offenbar macht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Deshalb sagt er: Wache auf, der du schläfst, und stehe auf aus den Toten, und der Christus wird dir leuchten!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Sehet nun zu, wie ihr sorgfältig wandelt, nicht als Unweise, sondern als Weise,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'die gelegene Zeit auskaufend, denn die Tage sind böse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Darum seid nicht töricht, sondern verständig, was der Wille des Herrn sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Und berauschet euch nicht mit Wein, in welchem Ausschweifung ist, sondern werdet mit dem Geiste erfüllt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'redend zueinander in Psalmen und Lobliedern und geistlichen Liedern, singend und spielend dem Herrn in eurem Herzen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'danksagend allezeit für alles dem Gott und Vater im Namen unseres Herrn Jesus Christus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'einander unterwürfig in der Furcht Christi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Ihr Weiber, seid unterwürfig euren eigenen Männern, als dem Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Denn der Mann ist das Haupt des Weibes, wie auch der Christus das Haupt der Versammlung ist; er ist des Leibes Heiland.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Aber gleichwie die Versammlung dem Christus unterworfen ist, also auch die Weiber ihren Männern in allem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Ihr Männer, liebet eure Weiber, gleichwie auch der Christus die Versammlung geliebt und sich selbst für sie hingegeben hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'auf daß er sie heiligte, sie reinigend durch die Waschung mit Wasser durch das Wort,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'auf daß er die Versammlung sich selbst verherrlicht darstellte, die nicht Flecken oder Runzel oder etwas dergleichen habe, sondern daß sie heilig und tadellos sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Also sind auch die Männer schuldig, ihre Weiber zu lieben wie ihre eigenen Leiber. Wer sein Weib liebt, liebt sich selbst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Denn niemand hat jemals sein eigenes Fleisch gehaßt, sondern er nährt und pflegt es, gleichwie auch der Christus die Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Denn wir sind Glieder seines Leibes, von seinem Fleische und von seinen Gebeinen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, '\"Deswegen wird ein Mensch seinen Vater und seine Mutter verlassen und seinem Weibe anhangen, und die zwei werden ein Fleisch sein\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Dieses Geheimnis ist groß; ich aber sage es in Bezug auf Christum und auf die Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Doch auch ihr, ein jeder von euch liebe sein Weib also wie sich selbst; das Weib aber, daß sie den Mann fürchte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Ihr Kinder, gehorchet euren Eltern im Herrn, denn das ist recht. \"Ehre deinen Vater und deine Mutter\",');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'welches das erste Gebot mit Verheißung ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, '\"auf daß es dir wohlgehe und du lange lebest auf der Erde\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Und ihr Väter, reizet eure Kinder nicht zum Zorn, sondern ziehet sie auf in der Zucht und Ermahnung des Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Ihr Knechte, gehorchet euren Herren nach dem Fleische mit Furcht und Zittern, in Einfalt eures Herzens, als dem Christus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'nicht mit Augendienerei, als Menschengefällige, sondern als Knechte Christi, indem ihr den Willen Gottes von Herzen tut,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'und mit Gutwilligkeit dienet, als dem Herrn und nicht den Menschen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'da ihr wisset, daß, was irgend ein jeder Gutes tun wird, er dies vom Herrn empfangen wird, er sei Sklave oder Freier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Und ihr Herren, tut dasselbe gegen sie und lasset das Drohen, da ihr wisset, daß sowohl ihr als euer Herr in den Himmeln ist, und daß bei ihm kein Ansehen der Person ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Übrigens, Brüder, seid stark in dem Herrn und in der Macht seiner Stärke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Ziehet an die ganze Waffenrüstung Gottes, damit ihr zu bestehen vermöget wider die Listen des Teufels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Denn unser Kampf ist nicht wider Fleisch und Blut, sondern wider die Fürstentümer, wider die Gewalten, wider die Weltbeherrscher dieser Finsternis, wider die geistlichen Mächte der Bosheit in den himmlischen Örtern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Deshalb nehmet die ganze Waffenrüstung Gottes, auf daß ihr an dem bösen Tage zu widerstehen und, nachdem ihr alles ausgerichtet habt, zu stehen vermöget.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Stehet nun, eure Lenden umgürtet mit Wahrheit, und angetan mit dem Brustharnisch der Gerechtigkeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'und beschuht an den Füßen mit der Bereitschaft des Evangeliums des Friedens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'indem ihr über das alles ergriffen habt den Schild des Glaubens, mit welchem ihr imstande sein werdet, alle feurigen Pfeile des Bösen auszulöschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Nehmet auch den Helm des Heils und das Schwert des Geistes, welches Gottes Wort ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'zu aller Zeit betend mit allem Gebet und Flehen in dem Geiste, und eben hierzu wachend in allem Anhalten und Flehen für alle Heiligen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'und für mich, auf daß mir Rede verliehen werde im Auftun meines Mundes, um mit Freimütigkeit kundzutun das Geheimnis des Evangeliums,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, '(für welches ich ein Gesandter bin in Ketten), damit ich in demselben freimütig rede, wie ich reden soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Auf daß aber auch ihr meine Umstände wisset, wie es mir geht, so wird Tychikus, der geliebte Bruder und treue Diener im Herrn, euch alles kundtun,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'den ich eben deshalb zu euch gesandt habe, auf daß ihr unsere Umstände wisset, und er eure Herzen tröste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Friede den Brüdern und Liebe mit Glauben von Gott, dem Vater, und dem Herrn Jesus Christus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Die Gnade mit allen denen, die unseren Herrn Jesus Christus lieben in Unverderblichkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paulus und Timotheus, Knechte Jesu Christi, allen Heiligen in Christo Jesu, die in Philippi sind, mit den Aufsehern und Dienern:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Gnade euch und Friede von Gott, unserem Vater, und dem Herrn Jesus Christus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Ich danke meinem Gott bei aller meiner Erinnerung an euch');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'allezeit in jedem meiner Gebete, indem ich für euch alle das Gebet mit Freuden tue,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'wegen eurer Teilnahme an dem Evangelium vom ersten Tage an bis jetzt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'indem ich eben dessen in guter Zuversicht bin, daß der, welcher ein gutes Werk in euch angefangen hat, es vollführen wird bis auf den Tag Jesu Christi;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'wie es für mich recht ist, daß ich dies in betreff euer aller denke, weil ihr mich im Herzen habt, und sowohl in meinen Banden, als auch in der Verantwortung und Bestätigung des Evangeliums, ihr alle meine Mitteilnehmer der Gnade seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Denn Gott ist mein Zeuge, wie ich mich nach euch allen sehne mit dem Herzen Christi Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Und um dieses bete ich, daß eure Liebe noch mehr und mehr überströme in Erkenntnis und aller Einsicht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'damit ihr prüfen möget, was das Vorzüglichere sei, auf daß ihr lauter und unanstößig seid auf den Tag Christi,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'erfüllt mit der Frucht der Gerechtigkeit, die durch Jesum Christum ist, zur Herrlichkeit und zum Preise Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Ich will aber, daß ihr wisset, Brüder, daß meine Umstände mehr zur Förderung des Evangeliums geraten sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'so daß meine Bande in Christo offenbar geworden sind in dem ganzen Prätorium und allen anderen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'und daß die meisten der Brüder, indem sie im Herrn Vertrauen gewonnen haben durch meine Bande, viel mehr sich erkühnen, das Wort Gottes zu reden ohne Furcht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Etliche zwar predigen Christum auch aus Neid und Streit, etliche aber auch aus gutem Willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Diese aus Liebe, indem sie wissen, daß ich zur Verantwortung des Evangeliums gesetzt bin;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'jene aus Streitsucht verkündigen Christum nicht lauter, indem sie meinen Banden Trübsal zu erwecken gedenken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Was denn? Wird doch auf alle Weise, sei es aus Vorwand oder in Wahrheit, Christus verkündigt, und darüber freue ich mich, ja, ich werde mich auch freuen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'denn ich weiß, daß dies mir zur Seligkeit ausschlagen wird durch euer Gebet und durch Darreichung des Geistes Jesu Christi,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'nach meiner sehnlichen Erwartung und Hoffnung, daß ich in nichts werde zu Schanden werden, sondern mit aller Freimütigkeit, wie allezeit, so auch jetzt Christus hoch erhoben werden wird an meinem Leibe, sei es durch Leben oder durch Tod.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Denn das Leben ist für mich Christus, und das Sterben Gewinn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Wenn aber das Leben im Fleische mein Los ist, das ist für mich der Mühe wert, und was ich erwählen soll, weiß ich nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Ich werde aber von beidem bedrängt, indem ich Lust habe, abzuscheiden und bei Christo zu sein, denn es ist weit besser;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'das Bleiben im Fleische aber ist nötiger um euretwillen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Und in dieser Zuversicht weiß ich, daß ich bleiben und mit und bei euch allen bleiben werde zu eurer Förderung und Freude im Glauben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'auf daß euer Rühmen in Christo Jesu meinethalben überströme durch meine Wiederkunft zu euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Wandelt nur würdig des Evangeliums des Christus, auf daß, sei es daß ich komme und euch sehe, oder abwesend bin, ich von euch höre, daß ihr feststehet in einem Geiste, indem ihr mit einer Seele mitkämpfet mit dem Glauben des Evangeliums,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'und in nichts euch erschrecken lasset von den Widersachern; was für sie ein Beweis des Verderbens ist, aber eures Heils, und das von Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Denn euch ist es in Bezug auf Christum geschenkt worden, nicht allein an ihn zu glauben, sondern auch für ihn zu leiden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'da ihr denselben Kampf habt, den ihr an mir gesehen und jetzt von mir höret.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Wenn es nun irgend eine Ermunterung gibt in Christo, wenn irgend einen Trost der Liebe, wenn irgend eine Gemeinschaft des Geistes, wenn irgend innerliche Gefühle und Erbarmungen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'so erfüllet meine Freude, daß ihr einerlei gesinnt seid, dieselbe Liebe habend, einmütig, eines Sinnes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'nichts aus Parteisucht oder eitlem Ruhm tuend, sondern in der Demut einer den anderen höher achtend als sich selbst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'ein jeder nicht auf das Seinige sehend, sondern ein jeder auch auf das der anderen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Denn diese Gesinnung sei in euch, die auch in Christo Jesu war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'welcher, da er in Gestalt Gottes war, es nicht für einen Raub achtete, Gott gleich zu sein,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'sondern sich selbst zu nichts machte und Knechtsgestalt annahm, indem er in Gleichheit der Menschen geworden ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'und, in seiner Gestalt wie ein Mensch erfunden, sich selbst erniedrigte, indem er gehorsam ward bis zum Tode, ja, zum Tode am Kreuze.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Darum hat Gott ihn auch hoch erhoben und ihm einen Namen gegeben, der über jeden Namen ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'auf daß in dem Namen Jesu jedes Knie sich beuge, der Himmlischen und Irdischen und Unterirdischen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'und jede Zunge bekenne, daß Jesus Christus Herr ist, zur Verherrlichung Gottes, des Vaters.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Daher, meine Geliebten, gleichwie ihr allezeit gehorsam gewesen seid, nicht allein als in meiner Gegenwart, sondern jetzt vielmehr in meiner Abwesenheit, bewirket eure eigene Seligkeit mit Furcht und Zittern;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'denn Gott ist es, der in euch wirkt sowohl das Wollen als auch das Wirken, nach seinem Wohlgefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Tut alles ohne Murren und zweifelnde Überlegungen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'auf daß ihr tadellos und lauter seid, unbescholtene Kinder Gottes, inmitten eines verdrehten und verkehrten Geschlechts, unter welchem ihr scheinet wie Lichter in der Welt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'darstellend das Wort des Lebens, mir zum Ruhm auf den Tag Christi, daß ich nicht vergeblich gelaufen bin, noch auch vergeblich gearbeitet habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Wenn ich aber auch als Trankopfer über das Opfer und den Dienst eures Glaubens gesprengt werde, so freue ich mich und freue mich mit euch allen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Gleicherweise aber freuet auch ihr euch und freuet euch mit mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Ich hoffe aber in dem Herrn Jesus, Timotheus bald zu euch zu senden, auf daß auch ich gutes Mutes sei, wenn ich eure Umstände weiß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Denn ich habe niemand gleichgesinnt, der von Herzen für das Eure besorgt sein wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'denn alle suchen das Ihrige, nicht das, was Jesu Christi ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Ihr kennet aber seine Bewährung, daß er, wie ein Kind dem Vater, mit mir gedient hat an dem Evangelium.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Diesen nun hoffe ich sofort zu senden, wenn ich gesehen haben werde, wie es um mich steht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Ich vertraue aber im Herrn, daß auch ich selbst bald kommen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Ich habe es aber für nötig erachtet, Epaphroditus, meinen Bruder und Mitarbeiter und Mitstreiter, aber euren Abgesandten und Diener meiner Notdurft, zu euch zu senden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'da ihn ja sehnlich nach euch allen verlangte, und er sehr bekümmert war, weil ihr gehört hattet, daß er krank war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Denn er war auch krank, dem Tode nahe; aber Gott hat sich über ihn erbarmt, nicht aber über ihn allein, sondern auch über mich, auf daß ich nicht Traurigkeit auf Traurigkeit hätte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Ich habe ihn nun desto eilender gesandt, auf daß ihr, wenn ihr ihn sehet, wieder froh werdet, und ich weniger betrübt sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Nehmet ihn nun auf im Herrn mit aller Freude und haltet solche in Ehren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'denn um des Werkes willen ist er dem Tode nahe gekommen, indem er sein Leben wagte, auf daß er den Mangel in eurem Dienste gegen mich ausfüllte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Übrigens, meine Brüder, freuet euch in dem Herrn! Euch dasselbe zu schreiben, ist mir nicht verdrießlich, für euch aber ist es sicher.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Sehet auf die Hunde, sehet auf die bösen Arbeiter, sehet auf die Zerschneidung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Denn wir sind die Beschneidung, die wir durch den Geist Gottes dienen und uns Christi Jesu rühmen und nicht auf Fleisch vertrauen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'wiewohl ich auch auf Fleisch Vertrauen habe. Wenn irgend ein anderer sich dünkt, auf Fleisch zu vertrauen, ich noch mehr:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Beschnitten am achten Tage, vom Geschlecht Israel, vom Stamme Benjamin, Hebräer von Hebräern; was das Gesetz betrifft, ein Pharisäer;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'was den Eifer betrifft, ein Verfolger der Versammlung; was die Gerechtigkeit betrifft, die im Gesetz ist, tadellos erfunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Aber was irgend mir Gewinn war, habe ich um Christi willen für Verlust geachtet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'ja, wahrlich, ich achte auch alles für Verlust wegen der Vortrefflichkeit der Erkenntnis Christi Jesu, meines Herrn, um dessentwillen ich alles eingebüßt habe und es für Dreck achte, auf daß ich Christum gewinne');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'und in ihm erfunden werde, indem ich nicht meine Gerechtigkeit habe, die aus dem Gesetz ist, sondern die durch den Glauben an Christum ist, die Gerechtigkeit aus Gott durch den Glauben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'um ihn zu erkennen und die Kraft seiner Auferstehung und die Gemeinschaft seiner Leiden, indem ich seinem Tode gleichgestaltet werde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'ob ich auf irgend eine Weise hingelangen möge zur Auferstehung aus den Toten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Nicht daß ich es schon ergriffen habe oder schon vollendet sei; ich jage ihm aber nach, ob ich es auch ergreifen möge, indem ich auch von Christo Jesu ergriffen bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Brüder, ich halte mich selbst nicht dafür, es ergriffen zu haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'eines aber tue ich: Vergessend was dahinten, und mich ausstreckend nach dem, was vorn ist, jage ich, das Ziel anschauend, hin zu dem Kampfpreis der Berufung Gottes nach oben in Christo Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'So viele nun vollkommen sind, laßt uns also gesinnt sein; und wenn ihr etwas anders gesinnt seid, so wird euch Gott auch dies offenbaren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Doch wozu wir gelangt sind, laßt uns in denselben Fußstapfen wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Seid zusammen meine Nachahmer, Brüder, und sehet hin auf die, welche also wandeln, wie ihr uns zum Vorbilde habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Denn viele wandeln, von denen ich euch oft gesagt habe, nun aber auch mit Weinen sage, daß sie die Feinde des Kreuzes Christi sind:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'deren Ende Verderben, deren Gott der Bauch, und deren Ehre in ihrer Schande ist, die auf das Irdische sinnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Denn unser Bürgertum ist in den Himmeln, von woher wir auch den Herrn Jesus Christus als Heiland erwarten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'der unseren Leib der Niedrigkeit umgestalten wird zur Gleichförmigkeit mit seinem Leibe der Herrlichkeit, nach der wirksamen Kraft, mit der er vermag, auch alle Dinge sich zu unterwerfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Daher, meine geliebten und ersehnten Brüder, meine Freude und Krone, also stehet fest im Herrn, Geliebte!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Die Evodia ermahne ich, und die Syntyche ermahne ich, einerlei gesinnt zu sein im Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Ja, ich bitte auch dich, mein treuer Mitknecht, stehe ihnen bei, die in dem Evangelium mit mir gekämpft haben, auch mit Clemens und meinen übrigen Mitarbeitern, deren Namen im Buche des Lebens sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Freuet euch in dem Herrn allezeit! Wiederum will ich sagen: Freuet euch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Laßt eure Gelindigkeit kundwerden allen Menschen; der Herr ist nahe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Seid um nichts besorgt, sondern in allem lasset durch Gebet und Flehen mit Danksagung eure Anliegen vor Gott kundwerden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'und der Friede Gottes, der allen Verstand übersteigt, wird eure Herzen und euren Sinn bewahren in Christo Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Übrigens, Brüder, alles was wahr, alles was würdig, alles was gerecht, alles was rein, alles was lieblich ist, alles was wohllautet, wenn es irgend eine Tugend und wenn es irgend ein Lob gibt, dieses erwäget.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Was ihr auch gelernt und empfangen und gehört und an mir gesehen habt, dieses tut, und der Gott des Friedens wird mit euch sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Ich habe mich aber im Herrn sehr gefreut, daß ihr endlich einmal wieder aufgelebt seid, meiner zu gedenken; wiewohl ihr auch meiner gedachtet, aber ihr hattet keine Gelegenheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Nicht daß ich dies des Mangels halber sage, denn ich habe gelernt, worin ich bin, mich zu begnügen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Ich weiß sowohl erniedrigt zu sein, als ich weiß, Überfluß zu haben; in jedem und in allem bin ich unterwiesen, sowohl satt zu sein als zu hungern, sowohl Überfluß zu haben als Mangel zu leiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Alles vermag ich in dem, der mich kräftigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Doch habt ihr wohlgetan, daß ihr an meiner Drangsal teilgenommen habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Ihr wisset aber auch, ihr Philipper, daß im Anfang des Evangeliums, als ich aus Macedonien wegging, keine Versammlung mir in Bezug auf Geben und Empfangen mitgeteilt hat, als nur ihr allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Denn auch in Thessalonich habt ihr mir einmal und zweimal für meine Notdurft gesandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Nicht daß ich die Gabe suche, sondern ich suche die Frucht, die überströmend sei für eure Rechnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Ich habe aber alles in Fülle und habe Überfluß; ich bin erfüllt, da ich von Epaphroditus das von euch Gesandte empfangen habe, einen duftenden Wohlgeruch, ein angenehmes Opfer, Gott wohlgefällig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Mein Gott aber wird alle eure Notdurft erfüllen nach seinem Reichtum in Herrlichkeit in Christo Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Unserem Gott und Vater aber sei die Herrlichkeit von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Grüßet jeden Heiligen in Christo Jesu. Es grüßen euch die Brüder, die bei mir sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Es grüßen euch alle Heiligen, und besonders die aus des Kaisers Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Die Gnade des Herrn Jesus Christus sei mit eurem Geiste! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paulus, Apostel Christi Jesu durch Gottes Willen, und Timotheus, der Bruder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'den heiligen und treuen Brüdern in Christo, die in Kolossä sind: Gnade euch und Friede von Gott, unserem Vater, und dem Herrn Jesus Christus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Wir danken dem Gott und Vater unseres Herrn Jesus Christus allezeit, indem wir für euch beten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'nachdem wir gehört haben von eurem Glauben in Christo Jesu und der Liebe, die ihr zu allen Heiligen habt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'wegen der Hoffnung, die für euch aufgehoben ist in den Himmeln, von welcher ihr zuvor gehört habt in dem Worte der Wahrheit des Evangeliums,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'das zu euch gekommen, so wie es auch in der ganzen Welt ist, und ist fruchtbringend und wachsend, wie auch unter euch, von dem Tage an, da ihr es gehört und die Gnade Gottes in Wahrheit erkannt habt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'so wie ihr gelernt habt von Epaphras, unserem geliebten Mitknecht, der ein treuer Diener des Christus für euch ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'der uns auch eure Liebe im Geiste kundgetan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Deshalb hören auch wir nicht auf, von dem Tage an, da wir es gehört haben, für euch zu beten und zu bitten, auf daß ihr erfüllt sein möget mit der Erkenntnis seines Willens in aller Weisheit und geistlichem Verständnis,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'um würdig des Herrn zu wandeln zu allem Wohlgefallen, in jedem guten Werke fruchtbringend, und wachsend durch die Erkenntnis Gottes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'gekräftigt mit aller Kraft nach der Macht seiner Herrlichkeit, zu allem Ausharren und aller Langmut mit Freuden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'danksagend dem Vater, der uns fähig gemacht hat zu dem Anteil am Erbe der Heiligen in dem Lichte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'der uns errettet hat aus der Gewalt der Finsternis und versetzt in das Reich des Sohnes seiner Liebe,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'in welchem wir die Erlösung haben, die Vergebung der Sünden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'welcher das Bild des unsichtbaren Gottes ist, der Erstgeborene aller Schöpfung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Denn durch ihn sind alle Dinge geschaffen worden, die in den Himmeln und die auf der Erde, die sichtbaren und die unsichtbaren, es seien Throne oder Herrschaften oder Fürstentümer oder Gewalten: alle Dinge sind durch ihn und für ihn geschaffen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Und er ist vor allen, und alle Dinge bestehen zusammen durch ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Und er ist das Haupt des Leibes, der Versammlung, welcher der Anfang ist, der Erstgeborene aus den Toten, auf daß er in allem den Vorrang habe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'denn es war das Wohlgefallen der ganzen Fülle, in ihm zu wohnen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'und durch ihn alle Dinge mit sich zu versöhnen indem er Frieden gemacht hat durch das Blut seines Kreuzes, durch ihn, es seien die Dinge auf der Erde oder die Dinge in den Himmeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Und euch, die ihr einst entfremdet und Feinde waret nach der Gesinnung in den bösen Werken, hat er aber nun versöhnt');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'in dem Leibe seines Fleisches durch den Tod, um euch heilig und tadellos und unsträflich vor sich hinzustellen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'wenn ihr anders in dem Glauben gegründet und fest bleibet und nicht abbewegt werdet von der Hoffnung des Evangeliums, welches ihr gehört habt, das gepredigt worden in der ganzen Schöpfung, die unter dem Himmel ist, dessen Diener ich, Paulus, geworden bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Jetzt freue ich mich in den Leiden für euch und ergänze in meinem Fleische, was noch rückständig ist von den Drangsalen des Christus für seinen Leib, das ist die Versammlung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'deren Diener ich geworden bin nach der Verwaltung Gottes, die mir in Bezug auf euch gegeben ist, um das Wort Gottes zu vollenden:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'das Geheimnis, welches von den Zeitaltern und von den Geschlechtern her verborgen war, jetzt aber seinen Heiligen geoffenbart worden ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'denen Gott kundtun wollte, welches der Reichtum der Herrlichkeit dieses Geheimnisses sei unter den Nationen, welches ist Christus in euch, die Hoffnung der Herrlichkeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'den wir verkündigen, indem wir jeden Menschen ermahnen und jeden Menschen lehren in aller Weisheit, auf daß wir jeden Menschen vollkommen in Christo darstellen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'wozu ich mich auch bemühe, indem ich kämpfend ringe gemäß seiner Wirksamkeit, die in mir wirkt in Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Denn ich will, daß ihr wisset, welch großen Kampf ich habe um euch und die in Laodicäa und so viele mein Angesicht im Fleische nicht gesehen haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'auf daß ihre Herzen getröstet sein mögen, vereinigt in Liebe und zu allem Reichtum der vollen Gewißheit des Verständnisses, zur Erkenntnis des Geheimnisses Gottes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'in welchem verborgen sind alle Schätze der Weisheit und der Erkenntnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Dies sage ich aber, auf daß niemand euch verführe durch überredende Worte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Denn wenn ich auch dem Fleische nach abwesend bin, so bin ich doch im Geiste bei euch, mich freuend und sehend eure Ordnung und die Festigkeit eures Glaubens an Christum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Wie ihr nun den Christus Jesus, den Herrn, empfangen habt, so wandelt in ihm,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'gewurzelt und auferbaut in ihm und befestigt in dem Glauben, so wie ihr gelehrt worden seid, überströmend in demselben mit Danksagung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Sehet zu, daß nicht jemand sei, der euch als Beute wegführe durch die Philosophie und durch eitlen Betrug, nach der Überlieferung der Menschen, nach den Elementen der Welt, und nicht nach Christo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Denn in ihm wohnt die ganze Fülle der Gottheit leibhaftig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'und ihr seid vollendet in ihm, welcher das Haupt jedes Fürstentums und jeder Gewalt ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'in welchem ihr auch beschnitten worden seid mit einer nicht mit Händen geschehenen Beschneidung, in dem Ausziehen des Leibes des Fleisches,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'in der Beschneidung des Christus, mit ihm begraben in der Taufe, in welcher ihr auch mitauferweckt worden seid durch den Glauben an die wirksame Kraft Gottes, der ihn aus den Toten auferweckt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Und euch, als ihr tot waret in den Vergehungen und in der Vorhaut eures Fleisches, hat er mitlebendig gemacht mit ihm, indem er uns alle Vergehungen vergeben hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'als er ausgetilgt die uns entgegenstehende Handschrift in Satzungen, die wider uns war, hat er sie auch aus der Mitte weggenommen, indem er sie an das Kreuz nagelte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'als er die Fürstentümer und die Gewalten ausgezogen hatte, stellte er sie öffentlich zur Schau, indem er durch dasselbe über sie einen Triumph hielt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'So richte euch nun niemand über Speise oder Trank, oder in Ansehung eines Festes oder Neumondes oder von Sabbathen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'die ein Schatten der zukünftigen Dinge sind, der Körper aber ist Christi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Laßt niemand euch um den Kampfpreis bringen, der seinen eigenen Willen tut in Demut und Anbetung der Engel, indem er auf Dinge eingeht, die er nicht gesehen hat, eitler Weise aufgeblasen von dem Sinne seines Fleisches,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'und nicht festhaltend das Haupt, aus welchem der ganze Leib, durch die Gelenke und Bande Darreichung empfangend und zusammengefügt, das Wachstum Gottes wächst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Wenn ihr mit Christo den Elementen der Welt gestorben seid, was unterwerfet ihr euch Satzungen, als lebtet ihr noch in der Welt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Berühre nicht, koste nicht, betaste nicht!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, '(Dinge, welche alle zur Zerstörung durch den Gebrauch bestimmt sind) nach den Geboten und Lehren der Menschen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, '(welche zwar einen Schein von Weisheit haben, in eigenwilligem Gottesdienst und in Demut und im Nichtverschonen des Leibes, und nicht in einer gewissen Ehre), zur Befriedigung des Fleisches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Wenn ihr nun mit dem Christus auferweckt worden seid, so suchet, was droben ist, wo der Christus ist, sitzend zur Rechten Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Sinnet auf das, was droben ist, nicht auf das, was auf der Erde ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'denn ihr seid gestorben, und euer Leben ist verborgen mit dem Christus in Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Wenn der Christus, unser Leben, geoffenbart werden wird, dann werdet auch ihr mit ihm geoffenbart werden in Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Tötet nun eure Glieder, die auf der Erde sind: Hurerei, Unreinigkeit, Leidenschaft, böse Lust und Habsucht, welche Götzendienst ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'um welcher Dinge willen der Zorn Gottes kommt über die Söhne des Ungehorsams;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'unter welchen auch ihr einst gewandelt habt, als ihr in diesen Dingen lebtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Jetzt aber leget auch ihr das alles ab: Zorn, Wut, Bosheit, Lästerung, schändliches Reden aus eurem Munde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Belüget einander nicht, da ihr den alten Menschen mit seinen Handlungen ausgezogen und den neuen angezogen habt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'der erneuert wird zur Erkenntnis nach dem Bilde dessen, der ihn erschaffen hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'wo nicht ist Grieche und Jude, Beschneidung und Vorhaut, Barbar, Scythe, Sklave, Freier, sondern Christus alles und in allen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Ziehet nun an, als Auserwählte Gottes, als Heilige und Geliebte: herzliches Erbarmen, Güte, Demut, Milde, Langmut,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'einander ertragend und euch gegenseitig vergebend, wenn einer Klage hat wider den anderen; wie auch der Christus euch vergeben hat, also auch ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Zu diesem allen aber ziehet die Liebe an, welche das Band der Vollkommenheit ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Und der Friede des Christus regiere in euren Herzen, zu welchem ihr auch berufen worden seid in einem Leibe; und seid dankbar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Laßt das Wort des Christus reichlich in euch wohnen, indem ihr in aller Weisheit euch gegenseitig lehret und ermahnet mit Psalmen, Lobliedern und geistlichen Liedern, Gott singend in euren Herzen in Gnade.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Und alles, was immer ihr tut, im Wort oder im Werk, alles tut im Namen des Herrn Jesus, danksagend Gott, dem Vater, durch ihn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Ihr Weiber, seid euren Männern unterwürfig, wie es sich geziemt in dem Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Ihr Männer, liebet eure Weiber und seid nicht bitter gegen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Ihr Kinder, gehorchet euren Eltern in allem, denn dies ist wohlgefällig im Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Ihr Väter, ärgert eure Kinder nicht, auf daß sie nicht mutlos werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Ihr Knechte, gehorchet in allem euren Herren nach dem Fleische, nicht in Augendienerei, als Menschengefällige, sondern in Einfalt des Herzens, den Herrn fürchtend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Was irgend ihr tut, arbeitet von Herzen, als dem Herrn und nicht den Menschen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'da ihr wisset, daß ihr vom Herrn die Vergeltung des Erbes empfangen werdet; ihr dienet dem Herrn Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Denn wer unrecht tut, wird das Unrecht empfangen, das er getan hat; und da ist kein Ansehen der Person.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Ihr Herren, gewähret euren Knechten, was recht und billig ist, da ihr wisset, daß auch ihr einen Herrn in den Himmeln habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Beharret im Gebet und wachet in demselben mit Danksagung;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'und betet zugleich auch für uns, auf daß Gott uns eine Tür des Wortes auftue, um das Geheimnis des Christus zu reden, um deswillen ich auch gebunden bin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'auf daß ich es offenbare, wie ich reden soll.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Wandelt in Weisheit gegen die, welche draußen sind, die gelegene Zeit auskaufend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Euer Wort sei allezeit in Gnade, mit Salz gewürzt, um zu wissen, wie ihr jedem einzelnen antworten sollt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Alles, was mich angeht, wird euch Tychikus kundtun, der geliebte Bruder und treue Diener und Mitknecht in dem Herrn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'den ich eben dieserhalb zu euch gesandt habe, auf daß er eure Umstände erfahre und eure Herzen tröste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'mit Onesimus, dem treuen und geliebten Bruder, der von euch ist; sie werden euch alles kundtun, was hier vorgeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Es grüßt euch Aristarchus, mein Mitgefangener, und Markus, der Neffe des Barnabas, betreffs dessen ihr Befehle erhalten habt (wenn er zu euch kommt, so nehmet ihn auf),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'und Jesus, genannt Justus, die aus der Beschneidung sind. Diese allein sind Mitarbeiter am Reiche Gottes, die mir ein Trost gewesen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Es grüßt euch Epaphras, der von euch ist, ein Knecht Christi Jesu, der allezeit für euch ringt in den Gebeten, auf daß ihr stehet vollkommen und völlig überzeugt in allem Willen Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Denn ich gebe ihm Zeugnis, daß er viel Mühe hat um euch und die in Laodicäa und die in Hierapolis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Es grüßt euch Lukas, der geliebte Arzt, und Demas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Grüßet die Brüder in Laodicäa, und Nymphas und die Versammlung, die in seinem Hause ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Und wenn der Brief bei euch gelesen ist, so machet, daß er auch in der Versammlung der Laodicäer gelesen werde, und daß auch ihr den aus Laodicäa leset;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'und saget Archippus: Sieh auf den Dienst, den du im Herrn empfangen hast, daß du ihn erfüllest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Der Gruß mit meiner, des Paulus, Hand. Gedenket meiner Bande. Die Gnade sei mit euch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paulus und Silvanus und Timotheus der Versammlung der Thessalonicher in Gott, dem Vater, und dem Herrn Jesus Christus: Gnade euch und Friede!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Wir danken Gott allezeit für euch alle, indem wir euer erwähnen in unseren Gebeten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'unablässig eingedenk eures Werkes des Glaubens und der Bemühung der Liebe und des Ausharrens der Hoffnung auf unseren Herrn Jesus Christus, vor unserem Gott und Vater,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'wissend, von Gott geliebte Brüder, eure Auserwählung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Denn unser Evangelium war nicht bei euch im Worte allein, sondern auch in Kraft und im Heiligen Geiste und in großer Gewißheit, wie ihr wisset, was wir unter euch waren um euretwillen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Und ihr seid unsere Nachahmer geworden und des Herrn, indem ihr das Wort aufgenommen habt in vieler Drangsal mit Freude des Heiligen Geistes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'so daß ihr allen Gläubigen in Macedonien und in Achaja zu Vorbildern geworden seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Denn von euch aus ist das Wort des Herrn erschollen, nicht allein in Macedonien und in Achaja, sondern an jedem Orte ist euer Glaube an Gott ausgebreitet worden, so daß wir nicht nötig haben, etwas zu sagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Denn sie selbst verkündigen von uns, welchen Eingang wir bei euch hatten, und wie ihr euch von den Götzenbildern zu Gott bekehrt habt, dem lebendigen und wahren Gott zu dienen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'und seinen Sohn aus den Himmeln zu erwarten, den er aus den Toten auferweckt hat, Jesum, der uns errettet von dem kommenden Zorn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Denn ihr selbst wisset, Brüder, unseren Eingang bei euch, daß er nicht vergeblich war;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'sondern nachdem wir in Philippi zuvor gelitten hatten und mißhandelt worden waren, wie ihr wisset, waren wir freimütig in unserem Gott, das Evangelium Gottes zu euch zu reden unter großem Kampf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Denn unsere Ermahnung war nicht aus Betrug, noch aus Unreinigkeit, noch mit List;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'sondern so, wie wir von Gott bewährt worden sind, mit dem Evangelium betraut zu werden, also reden wir, nicht um Menschen zu gefallen, sondern Gott, der unsere Herzen prüft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Denn niemals sind wir mit einschmeichelnder Rede umgegangen, wie ihr wisset, noch mit einem Vorwande für Habsucht, Gott ist Zeuge;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'noch suchten wir Ehre von Menschen, weder von euch, noch von anderen, wiewohl wir als Christi Apostel euch zur Last sein konnten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'sondern wir sind in eurer Mitte zart gewesen, wie eine nährende Frau ihre eigenen Kinder pflegt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Also, da wir ein sehnliches Verlangen nach euch haben, gefiel es uns wohl, euch nicht allein das Evangelium Gottes, sondern auch unser eigenes Leben mitzuteilen, weil ihr uns lieb geworden waret.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Denn ihr gedenket, Brüder, an unsere Mühe und Beschwerde: Nacht und Tag arbeitend, um niemand von euch beschwerlich zu fallen, haben wir euch das Evangelium Gottes gepredigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Ihr seid Zeugen und Gott, wie göttlich und gerecht und untadelig wir gegen euch, die Glaubenden, waren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'gleichwie ihr wisset, wie wir jeden einzelnen von euch, wie ein Vater seine eigenen Kinder, euch ermahnt und getröstet und euch bezeugt haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'daß ihr wandeln solltet würdig des Gottes, der euch zu seinem eigenen Reiche und seiner eigenen Herrlichkeit beruft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Und darum danken wir auch Gott unablässig, daß, als ihr von uns das Wort der Kunde Gottes empfinget, ihr es nicht als Menschenwort aufnahmet, sondern, wie es wahrhaftig ist, als Gottes Wort, das auch in euch, den Glaubenden, wirkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Denn, Brüder, ihr seid Nachahmer der Versammlungen Gottes geworden, die in Judäa sind in Christo Jesu, weil auch ihr dasselbe von den eigenen Landsleuten erlitten habt, wie auch jene von den Juden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'die sowohl den Herrn Jesus als auch die Propheten getötet und uns durch Verfolgung weggetrieben haben, und Gott nicht gefallen und allen Menschen entgegen sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'indem sie uns wehren, zu den Nationen zu reden, auf daß sie errettet werden, damit sie ihre Sünden allezeit vollmachen; aber der Zorn ist völlig über sie gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Wir aber, Brüder, da wir für kurze Zeit von euch verwaist waren, dem Angesicht, nicht dem Herzen nach, haben wir uns um so mehr befleißigt, euer Angesicht zu sehen, mit großem Verlangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Deshalb wollten wir zu euch kommen (ich, Paulus, nämlich), einmal und zweimal, und der Satan hat uns verhindert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Denn wer ist unsere Hoffnung oder Freude oder Krone des Ruhmes? Nicht auch ihr vor unserem Herrn Jesus bei seiner Ankunft?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Denn ihr seid unsere Herrlichkeit und Freude.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Deshalb, da wir es nicht länger aushalten konnten, gefiel es uns, in Athen allein gelassen zu werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'und wir sandten Timotheus, unseren Bruder und Mitarbeiter Gottes in dem Evangelium des Christus, um euch zu befestigen und zu trösten eures Glaubens halber,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'auf daß niemand wankend werde in diesen Drangsalen. (Denn ihr selbst wisset, daß wir dazu gesetzt sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'denn auch als wir bei euch waren, sagten wir euch vorher, daß wir Drangsale haben würden, wie es auch geschehen ist und ihr wisset.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Darum auch, da ich es nicht länger aushalten konnte, sandte ich, um euren Glauben zu erfahren, ob nicht etwa der Versucher euch versucht habe und unsere Arbeit vergeblich gewesen sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Da jetzt aber Timotheus von euch zu uns gekommen ist und uns die gute Botschaft von eurem Glauben und eurer Liebe verkündigt hat, und daß ihr uns allezeit in gutem Andenken habt, indem euch sehr verlangt, uns zu sehen, gleichwie auch uns euch:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'deswegen Brüder, sind wir in all unserer Not und Drangsal über euch getröstet worden durch euren Glauben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'denn jetzt leben wir, wenn ihr feststehet im Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Denn was für Dank können wir Gott für euch vergelten über all der Freude, womit wir uns euretwegen freuen vor unserem Gott;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'indem wir Nacht und Tag über die Maßen flehen, daß wir euer Angesicht sehen und vollenden mögen, was an eurem Glauben mangelt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Unser Gott und Vater selbst aber und unser Herr Jesus richte unseren Weg zu euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Euch aber mache der Herr völlig und überströmend in der Liebe gegeneinander und gegen alle (gleichwie auch wir gegen euch sind),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'um eure Herzen tadellos in Heiligkeit zu befestigen vor unserem Gott und Vater, bei der Ankunft unseres Herrn Jesus mit allen seinen Heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Übrigens nun, Brüder, bitten und ermahnen wir euch in dem Herrn Jesus, wie ihr von uns empfangen habt, in welcher Weise ihr wandeln und Gott gefallen sollt, wie ihr auch wandelt, daß ihr reichlicher zunehmet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Denn ihr wisset, welche Gebote wir euch gegeben haben durch den Herrn Jesus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Denn dies ist Gottes Wille: eure Heiligkeit, daß ihr euch der Hurerei enthaltet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'daß ein jeder von euch sein eigenes Gefäß in Heiligkeit und Ehrbarkeit zu besitzen wisse,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'nicht in Leidenschaft der Lust, wie auch die Nationen, die Gott nicht kennen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'daß er seinen Bruder nicht übersehe noch hintergehe in der Sache, weil der Herr Rächer ist über dies alles, wie wir euch auch zuvor gesagt und ernstlich bezeugt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Denn Gott hat uns nicht zur Unreinigkeit berufen, sondern in Heiligkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Deshalb nun, wer dies verachtet, verachtet nicht einen Menschen, sondern Gott, der euch auch seinen Heiligen Geist gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Was aber die Bruderliebe betrifft, so habt ihr nicht nötig, daß wir euch schreiben, denn ihr selbst seid von Gott gelehrt, einander zu lieben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'denn das tut ihr auch gegen alle Brüder, die in ganz Macedonien sind. Wir ermahnen euch aber, Brüder, reichlicher zuzunehmen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'und euch zu beeifern, still zu sein und eure eigenen Geschäfte zu tun und mit euren eigenen Händen zu arbeiten, so wie wir euch geboten haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'auf daß ihr ehrbarlich wandelt gegen die, welche draußen sind, und niemandes bedürfet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Wir wollen aber nicht, Brüder, daß ihr, was die Entschlafenen betrifft, unkundig seid, auf daß ihr euch nicht betrübet wie auch die übrigen, die keine Hoffnung haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Denn wenn wir glauben, daß Jesus gestorben und auferstanden ist, also wird auch Gott die durch Jesum Entschlafenen mit ihm bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, '(Denn dieses sagen wir euch im Worte des Herrn, daß wir, die Lebenden, die übrigbleiben bis zur Ankunft des Herrn, den Entschlafenen keineswegs zuvorkommen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Denn der Herr selbst wird mit gebietendem Zuruf, mit der Stimme eines Erzengels und mit der Posaune Gottes herniederkommen vom Himmel, und die Toten in Christo werden zuerst auferstehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'danach werden wir, die Lebenden, die übrigbleiben, zugleich mit ihnen entrückt werden in Wolken dem Herrn entgegen in die Luft; und also werden wir allezeit bei dem Herrn sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'So ermuntert nun einander mit diesen Worten.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Was aber die Zeiten und Zeitpunkte betrifft, Brüder, so habt ihr nicht nötig, daß euch geschrieben werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Denn ihr selbst wisset genau, daß der Tag des Herrn also kommt wie ein Dieb in der Nacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Wenn sie sagen: Friede und Sicherheit! dann kommt ein plötzliches Verderben über sie, gleichwie die Geburtswehen über die Schwangere; und sie werden nicht entfliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Ihr aber Brüder, seid nicht in Finsternis, daß euch der Tag wie ein Dieb ergreife;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'denn ihr alle seid Söhne des Lichtes und Söhne des Tages; wir sind nicht von der Nacht, noch von der Finsternis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Also laßt uns nun nicht schlafen wie die übrigen, sondern wachen und nüchtern sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Denn die da schlafen, schlafen des Nachts, und die da trunken sind, sind des Nachts trunken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Wir aber, die von dem Tage sind, laßt uns nüchtern sein, angetan mit dem Brustharnisch des Glaubens und der Liebe und als Helm mit der Hoffnung der Seligkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Denn Gott hat uns nicht zum Zorn gesetzt, sondern zur Erlangung der Seligkeit durch unseren Herrn Jesus Christus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'der für uns gestorben ist, auf daß wir, sei es daß wir wachen oder schlafen, zusammen mit ihm leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Deshalb ermuntert einander und erbauet einer den anderen, wie ihr auch tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Wir bitten euch aber, Brüder, daß ihr die erkennet, die unter euch arbeiten und euch vorstehen im Herrn und euch zurechtweisen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'und daß ihr sie über die Maßen in Liebe achtet, um ihres Werkes willen. Seid in Frieden untereinander.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Wir ermahnen euch aber, Brüder: Weiset die Unordentlichen zurecht, tröstet die Kleinmütigen, nehmet euch der Schwachen an, seid langmütig gegen alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Sehet zu, daß niemand Böses mit Bösem jemand vergelte, sondern strebet allezeit dem Guten nach gegeneinander und gegen alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Freuet euch allezeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'betet unablässig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'danksaget in allem, denn dieses ist der Wille Gottes in Christo Jesu gegen euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Den Geist löschet nicht aus;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Weissagungen verachtet nicht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'prüfet aber alles, das Gute haltet fest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Von aller Art des Bösen haltet euch fern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Er selbst aber, der Gott des Friedens, heilige euch völlig; und euer ganzer Geist und Seele und Leib werde tadellos bewahrt bei der Ankunft unseres Herrn Jesus Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Treu ist, der euch ruft; der wird es auch tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Brüder, betet für uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Grüßet alle Brüder mit heiligem Kuß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Ich beschwöre euch bei dem Herrn, daß der Brief allen heiligen Brüdern vorgelesen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Die Gnade unseres Herrn Jesus Christus sei mit euch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paulus und Silvanus und Timotheus der Versammlung der Thessalonicher in Gott, unserem Vater, und dem Herrn Jesus Christus:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Gnade euch und Friede von Gott, unserem Vater, und dem Herrn Jesus Christus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Wir sind schuldig, Brüder, Gott allezeit für euch zu danken, wie es billig ist, weil euer Glaube überaus wächst, und die Liebe jedes einzelnen von euch allen gegeneinander überströmend ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'so daß wir selbst uns euer rühmen in den Versammlungen Gottes wegen eures Ausharrens und Glaubens in allen euren Verfolgungen und Drangsalen, die ihr erduldet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'ein offenbares Zeichen des gerechten Gerichts Gottes, daß ihr würdig geachtet werdet des Reiches Gottes, um dessentwillen ihr auch leidet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'wenn es anders bei Gott gerecht ist, Drangsal zu vergelten denen, die euch bedrängen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'und euch, die ihr bedrängt werdet, Ruhe mit uns bei der Offenbarung des Herrn Jesus vom Himmel, mit den Engeln seiner Macht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'in flammendem Feuer, wenn er Vergeltung gibt denen, die Gott nicht kennen, und denen, die dem Evangelium unseres Herrn Jesus Christus nicht gehorchen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'welche Strafe leiden werden, ewiges Verderben vom Angesicht des Herrn und von der Herrlichkeit seiner Stärke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'wenn er kommen wird, um an jenem Tage verherrlicht zu werden in seinen Heiligen und bewundert in allen denen, die geglaubt haben; denn unser Zeugnis bei euch ist geglaubt worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Weshalb wir auch allezeit für euch beten, auf daß unser Gott euch würdig erachte der Berufung und erfülle alles Wohlgefallen seiner Gütigkeit und das Werk des Glaubens in Kraft,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'damit der Name unseres Herrn Jesus Christus verherrlicht werde in euch, und ihr in ihm, nach der Gnade unseres Gottes und des Herrn Jesus Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Wir bitten euch aber, Brüder, wegen der Ankunft unseres Herrn Jesus Christus und unseres Versammeltwerdens zu ihm hin,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'daß ihr nicht schnell erschüttert werdet in der Gesinnung, noch erschreckt, weder durch Geist, noch durch Wort, noch durch Brief als durch uns, als ob der Tag des Herrn da wäre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Laßt euch von niemand auf irgend eine Weise verführen, denn dieser Tag kommt nicht, es sei denn, daß zuerst der Abfall komme und geoffenbart worden sei der Mensch der Sünde, der Sohn des Verderbens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'welcher widersteht und sich selbst erhöht über alles, was Gott heißt oder ein Gegenstand der Verehrung ist, so daß er sich in den Tempel Gottes setzt und sich selbst darstellt, daß er Gott sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Erinnert ihr euch nicht, daß ich dies zu euch sagte, als ich noch bei euch war?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Und jetzt wisset ihr, was zurückhält, daß er zu seiner Zeit geoffenbart werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Denn schon ist das Geheimnis der Gesetzlosigkeit wirksam; nur ist jetzt der, welcher zurückhält, bis er aus dem Wege ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'und dann wird der Gesetzlose geoffenbart werden, den der Herr Jesus verzehren wird durch den Hauch seines Mundes und vernichten durch die Erscheinung seiner Ankunft,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'ihn, dessen Ankunft nach der Wirksamkeit des Satans ist, in aller Macht und allen Zeichen und Wundern der Lüge');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'und in allem Betrug der Ungerechtigkeit denen, die verloren gehen, darum daß sie die Liebe zur Wahrheit nicht annahmen, damit sie errettet würden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Und deshalb sendet ihnen Gott eine wirksame Kraft des Irrwahns, daß sie der Lüge glauben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'auf daß alle gerichtet werden, die der Wahrheit nicht geglaubt, sondern Wohlgefallen gefunden haben an der Ungerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Wir aber sind schuldig, Gott allezeit für euch zu danken, vom Herrn geliebte Brüder, daß Gott euch von Anfang erwählt hat zur Seligkeit in Heiligung des Geistes und im Glauben an die Wahrheit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'wozu er euch berufen hat durch unser Evangelium, zur Erlangung der Herrlichkeit unseres Herrn Jesus Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Also nun, Brüder, stehet fest und haltet die Überlieferungen, die ihr gelehrt worden seid, sei es durch Wort oder durch unseren Brief.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Er selbst aber, unser Herr Jesus Christus, und unser Gott und Vater, der uns geliebt und uns ewigen Trost und gute Hoffnung gegeben hat durch die Gnade,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'tröste eure Herzen und befestige euch in jedem guten Werk und Wort.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Übrigens, Brüder, betet für uns, daß das Wort des Herrn laufe und verherrlicht werde, wie auch bei euch,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'und daß wir errettet werden von den schlechten und bösen Menschen; denn der Glaube ist nicht aller Teil.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Der Herr aber ist treu, der euch befestigen und vor dem Bösen bewahren wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Wir haben aber im Herrn das Vertrauen zu euch, daß ihr, was wir gebieten, sowohl tut als auch tun werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Der Herr aber richte eure Herzen zu der Liebe Gottes und zu dem Ausharren des Christus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Wir gebieten euch aber, Brüder, im Namen unseres Herrn Jesus Christus, daß ihr euch zurückziehet von jedem Bruder, der unordentlich wandelt, und nicht nach der Überlieferung, die er von uns empfangen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Denn ihr selbst wisset, wie ihr uns nachahmen sollt; denn wir haben nicht unordentlich unter euch gewandelt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'noch haben wir von jemand Brot umsonst gegessen, sondern wir haben mit Mühe und Beschwerde Nacht und Tag gearbeitet, um nicht jemand von euch beschwerlich zu fallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Nicht daß wir nicht das Recht dazu haben, sondern auf daß wir uns selbst euch zum Vorbilde gäben, damit ihr uns nachahmet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Denn auch als wir bei euch waren, geboten wir euch dieses: Wenn jemand nicht arbeiten will, so soll er auch nicht essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Denn wir hören, daß etliche unter euch unordentlich wandeln, indem sie nichts arbeiten, sondern fremde Dinge treiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Solchen aber gebieten wir und ermahnen sie in dem Herrn Jesus Christus, daß sie, in der Stille arbeitend, ihr eigenes Brot essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Ihr aber, Brüder, ermattet nicht im Gutestun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Wenn aber jemand unserem Wort durch den Brief nicht gehorcht, den bezeichnet und habet keinen Umgang mit ihm, auf daß er beschämt werde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'und achtet ihn nicht als einen Feind, sondern weiset ihn zurecht als einen Bruder.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Er selbst aber, der Herr des Friedens, gebe euch den Frieden immerdar auf alle Weise! Der Herr sei mit euch allen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Der Gruß mit meiner, des Paulus, Hand, welches das Zeichen in jedem Briefe ist; so schreibe ich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Die Gnade unseres Herrn Jesus Christus sei mit euch allen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paulus, Apostel Jesu Christi, nach Befehl Gottes, unseres Heilandes, und Christi Jesu, unserer Hoffnung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Timotheus, meinem echten Kinde im Glauben: Gnade, Barmherzigkeit, Friede von Gott, dem Vater, und Christo Jesu, unserem Herrn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'So wie ich dich bat, als ich nach Macedonien reiste, in Ephesus zu bleiben, auf daß du etlichen gebötest, nicht andere Lehren zu lehren,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'noch mit Fabeln und endlosen Geschlechtsregistern sich abzugeben, die mehr Streitfragen hervorbringen, als die Verwaltung Gottes fördern, die im Glauben ist...');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Das Endziel des Gebotes aber ist: Liebe aus reinem Herzen und gutem Gewissen und ungeheucheltem Glauben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'wovon etliche abgeirrt sind und sich zu eitlem Geschwätz gewandt haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'die Gesetzlehrer sein wollen und nicht verstehen, weder was sie sagen, noch was sie fest behaupten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Wir wissen aber, daß das Gesetz gut ist, wenn jemand es gesetzmäßig gebraucht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'indem er dies weiß, daß für einen Gerechten das Gesetz nicht bestimmt ist, sondern für Gesetzlose und Zügellose, für Gottlose und Sünder, für Heillose und Ungöttliche, Vaterschläger und Mutterschläger, Menschenmörder,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Hurer, Knabenschänder, Menschenräuber, Lügner, Meineidige, und wenn etwas anderes der gesunden Lehre zuwider ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'nach dem Evangelium der Herrlichkeit des seligen Gottes, welches mir anvertraut worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Und ich danke Christo Jesu, unserem Herrn, der mir Kraft verliehen, daß er mich treu erachtet hat, indem er den in den Dienst stellte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'der zuvor ein Lästerer und Verfolger und Gewalttäter war; aber mir ist Barmherzigkeit zuteil geworden, weil ich es unwissend im Unglauben tat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Über die Maßen aber ist die Gnade unseres Herrn überströmend geworden mit Glauben und Liebe, die in Christo Jesu sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Das Wort ist gewiß und aller Annahme wert, daß Christus Jesus in die Welt gekommen ist, Sünder zu erretten, von welchen ich der erste bin.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Aber darum ist mir Barmherzigkeit zuteil geworden, auf daß an mir, dem ersten, Jesus Christus die ganze Langmut erzeige, zum Vorbild für die, welche an ihn glauben werden zum ewigen Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Dem Könige der Zeitalter aber, dem unverweslichen, unsichtbaren, alleinigen Gott, sei Ehre und Herrlichkeit von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Dieses Gebot vertraue ich dir an, mein Kind Timotheus, nach den vorangegangenen Weissagungen über dich, auf daß du durch dieselben den guten Kampf kämpfest,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'indem du den Glauben bewahrst und ein gutes Gewissen, welches etliche von sich gestoßen und so, was den Glauben betrifft, Schiffbruch gelitten haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'unter welchen Hymenäus ist und Alexander, die ich dem Satan überliefert habe, auf daß sie durch Zucht unterwiesen würden, nicht zu lästern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Ich ermahne nun vor allen Dingen, daß Flehen, Gebete, Fürbitten, Danksagungen getan werden für alle Menschen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'für Könige und alle, die in Hoheit sind, auf daß wir ein ruhiges und stilles Leben führen mögen in aller Gottseligkeit und würdigem Ernst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Denn dieses ist gut und angenehm vor unserem Heilandgott,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'welcher will, daß alle Menschen errettet werden und zur Erkenntnis der Wahrheit kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Denn Gott ist einer, und einer Mittler zwischen Gott und Menschen, der Mensch Christus Jesus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'der sich selbst gab zum Lösegeld für alle, wovon das Zeugnis zu seiner Zeit verkündigt werden sollte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'wozu ich bestellt worden bin als Herold und Apostel (ich sage die Wahrheit, ich lüge nicht), ein Lehrer der Nationen, in Glauben und Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Ich will nun, daß die Männer an jedem Orte beten, indem sie heilige Hände aufheben, ohne Zorn und zweifelnde Überlegung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Desgleichen auch, daß die Weiber in bescheidenem Äußeren mit Schamhaftigkeit und Sittsamkeit sich schmücken, nicht mit Haarflechten und Gold oder Perlen oder kostbarer Kleidung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'sondern was Weibern geziemt, die sich zur Gottesfurcht bekennen, durch gute Werke.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Ein Weib lerne in der Stille in aller Unterwürfigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Ich erlaube aber einem Weibe nicht, zu lehren, noch über den Mann zu herrschen, sondern still zu sein,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'denn Adam wurde zuerst gebildet, danach Eva;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'und Adam wurde nicht betrogen, das Weib aber wurde betrogen und fiel in Übertretung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Sie wird aber gerettet werden in Kindesnöten, wenn sie bleiben in Glauben und Liebe und Heiligkeit mit Sittsamkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Das Wort ist gewiß: Wenn jemand nach einem Aufseherdienst trachtet, so begehrt er ein schönes Werk.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Der Aufseher nun muß untadelig sein, eines Weibes Mann, nüchtern, besonnen, sittsam, gastfrei, lehrfähig;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'nicht dem Wein ergeben, kein Schläger, sondern gelinde, nicht streitsüchtig, nicht geldliebend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'der dem eigenen Hause wohl vorsteht, der seine Kinder in Unterwürfigkeit hält mit allem würdigen Ernst');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(wenn aber jemand dem eigenen Hause nicht vorzustehen weiß, wie wird er die Versammlung Gottes besorgen?),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'nicht ein Neuling, auf daß er nicht aufgebläht, ins Gericht des Teufels verfalle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Er muß aber auch ein gutes Zeugnis haben von denen, die draußen sind, auf daß er nicht in Schmach und in den Fallstrick des Teufels verfalle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Die Diener desgleichen, würdig, nicht doppelzüngig, nicht vielem Wein ergeben, nicht schändlichem Gewinn nachgehend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'die das Geheimnis des Glaubens in reinem Gewissen bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Laß diese aber zuerst erprobt werden, dann laß sie dienen, wenn sie untadelig sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Die Weiber desgleichen, würdig, nicht verleumderisch, nüchtern, treu in allem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Die Diener seien eines Weibes Mann, die ihren Kindern und den eigenen Häusern wohl vorstehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'denn die, welche wohl gedient haben, erwerben sich eine schöne Stufe und viel Freimütigkeit im Glauben, der in Christo Jesu ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Dieses schreibe ich dir in der Hoffnung, bald zu dir zu kommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'wenn ich aber zögere, auf daß du wissest, wie man sich verhalten soll im Hause Gottes, welches die Versammlung des lebendigen Gottes ist, der Pfeiler und die Grundfeste der Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Und anerkannt groß ist das Geheimnis der Gottseligkeit: Gott ist geoffenbart worden im Fleische, gerechtfertigt im Geiste, gesehen von den Engeln, gepredigt unter den Nationen, geglaubt in der Welt, aufgenommen in Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Der Geist aber sagt ausdrücklich, daß in späteren Zeiten etliche von dem Glauben abfallen werden, indem sie achten auf betrügerische Geister und Lehren von Dämonen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'die in Heuchelei Lügen reden und betreffs des eigenen Gewissens wie mit einem Brenneisen gehärtet sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'verbieten zu heiraten, und gebieten, sich von Speisen zu enthalten, welche Gott geschaffen hat zur Annehmung mit Danksagung für die, welche glauben und die Wahrheit erkennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Denn jedes Geschöpf Gottes ist gut und nichts verwerflich, wenn es mit Danksagung genommen wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'denn es wird geheiligt durch Gottes Wort und durch Gebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Wenn du dieses den Brüdern vorstellst, so wirst du ein guter Diener Christi Jesu sein, auferzogen durch die Worte des Glaubens und der guten Lehre, welcher du genau gefolgt bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Die ungöttlichen und altweibischen Fabeln aber weise ab, übe dich aber zur Gottseligkeit;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'denn die leibliche Übung ist zu wenigem nütze, die Gottseligkeit aber ist zu allen Dingen nütze, indem sie die Verheißung des Lebens hat, des jetzigen und des zukünftigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Das Wort ist gewiß und aller Annahme wert;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'denn für dieses arbeiten wir und werden geschmäht, weil wir auf einen lebendigen Gott hoffen, der ein Erhalter aller Menschen ist, besonders der Gläubigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Dieses gebiete und lehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Niemand verachte deine Jugend, sondern sei ein Vorbild der Gläubigen in Wort, in Wandel, in Liebe, in Glauben, in Keuschheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Bis ich komme, halte an mit dem Vorlesen, mit dem Ermahnen, mit dem Lehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Vernachlässige nicht die Gnadengabe in dir, welche dir gegeben worden ist durch Weissagung mit Händeauflegen der Ältestenschaft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Bedenke dieses sorgfältig; lebe darin, auf daß deine Fortschritte allen offenbar seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Habe acht auf dich selbst und auf die Lehre; beharre in diesen Dingen; denn wenn du dieses tust, so wirst du sowohl dich selbst erretten als auch die, welche dich hören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Einen älteren Mann fahre nicht hart an, sondern ermahne ihn als einen Vater, jüngere als Brüder;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'ältere Frauen als Mütter, jüngere als Schwestern, in aller Keuschheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Ehre die Witwen, die wirklich Witwen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Wenn aber eine Witwe Kinder oder Enkel hat, so mögen sie zuerst lernen, gegen das eigene Haus fromm zu sein und den Eltern Gleiches zu vergelten; denn dieses ist angenehm vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Die aber wirklich Witwe und vereinsamt ist, hofft auf Gott und verharrt in dem Flehen und den Gebeten Nacht und Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Die aber in Üppigkeit lebt, ist lebendig tot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Und dies gebiete, auf daß sie unsträflich seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Wenn aber jemand für die Seinigen und besonders für die Hausgenossen nicht sorgt, so hat er den Glauben verleugnet und ist schlechter als ein Ungläubiger.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Eine Witwe werde verzeichnet, wenn sie nicht weniger als sechzig Jahre alt ist, eines Mannes Weib war,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'ein Zeugnis hat in guten Werken, wenn sie Kinder auferzogen, wenn sie Fremde beherbergt, wenn sie der Heiligen Füße gewaschen, wenn sie Bedrängten Hilfe geleistet hat, wenn sie jedem guten Werke nachgegangen ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Jüngere Witwen aber weise ab; denn wenn sie üppig geworden sind wider Christum,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'so wollen sie heiraten und fallen dem Urteil anheim, weil sie den ersten Glauben verworfen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Zugleich aber lernen sie auch müßig zu sein, umherlaufend in den Häusern; nicht allein aber müßig, sondern auch geschwätzig und vorwitzig, indem sie reden, was sich nicht geziemt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Ich will nun, daß jüngere Witwen heiraten, Kinder gebären, Haushaltung führen, dem Widersacher keinen Anlaß geben der Schmähung halber;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'denn schon haben sich etliche abgewandt, dem Satan nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Wenn ein Gläubiger oder eine Gläubige Witwen hat, so leiste er ihnen Hilfe, und die Versammlung werde nicht beschwert, auf daß sie denen Hilfe leiste, die wirklich Witwen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Die Ältesten, welche wohl vorstehen, laß doppelter Ehre würdig geachtet werden, sonderlich die da arbeiten in Wort und Lehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Denn die Schrift sagt: \"Du sollst dem Ochsen, der da drischt, nicht das Maul verbinden\", und: \"Der Arbeiter ist seines Lohnes wert\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Wider einen Ältesten nimm keine Klage an, außer bei zwei oder drei Zeugen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Die da sündigen, überführe vor allen, auf daß auch die übrigen Furcht haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Ich bezeuge ernstlich vor Gott und Christo Jesu und den auserwählten Engeln, daß du diese Dinge ohne Vorurteil beobachtest, indem du nichts nach Gunst tust.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Die Hände lege niemand schnell auf und habe nicht teil an fremden Sünden. Bewahre dich selbst keusch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Trinke nicht länger nur Wasser, sondern gebrauche ein wenig Wein, um deines Magens und deines häufigen Unwohlseins willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Von etlichen Menschen sind die Sünden vorher offenbar und gehen voraus zum Gericht, etlichen aber folgen sie auch nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Desgleichen sind auch die guten Werke vorher offenbar, und die, welche anders sind, können nicht verborgen bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Alle, welche Knechte unter dem Joche sind, sollen ihre eigenen Herren aller Ehre würdig achten, auf daß nicht der Name Gottes und die Lehre verlästert werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Die aber, welche gläubige Herren haben, sollen dieselben nicht verachten, weil sie Brüder sind, sondern ihnen vielmehr dienen, weil sie Treue und Geliebte sind, welche die Wohltat empfangen. Dieses lehre und ermahne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Wenn jemand anders lehrt und nicht beitritt den gesunden Worten, die unseres Herrn Jesus Christus sind, und der Lehre, die nach der Gottseligkeit ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'so ist er aufgeblasen und weiß nichts, sondern ist krank an Streitfragen und Wortgezänken, aus welchen entsteht: Neid, Hader, Lästerungen, böse Verdächtigungen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'beständige Zänkereien von Menschen, die an der Gesinnung verderbt und von der Wahrheit entblößt sind, welche meinen, die Gottseligkeit sei ein Mittel zum Gewinn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Die Gottseligkeit aber mit Genügsamkeit ist ein großer Gewinn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'denn wir haben nichts in die Welt hereingebracht, so ist es offenbar, daß wir auch nichts hinausbringen können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Wenn wir aber Nahrung und Bedeckung haben, so wollen wir uns daran genügen lassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Die aber reich werden wollen, fallen in Versuchung und Fallstrick und in viele unvernünftige und schädliche Lüste, welche die Menschen versenken in Verderben und Untergang.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Denn die Geldliebe ist eine Wurzel alles Bösen, welcher nachtrachtend etliche von dem Glauben abgeirrt sind und sich selbst mit vielen Schmerzen durchbohrt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Du aber, o Mensch Gottes, fliehe diese Dinge; strebe aber nach Gerechtigkeit, Gottseligkeit, Glauben, Liebe, Ausharren, Sanftmut des Geistes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Kämpfe den guten Kampf des Glaubens; ergreife das ewige Leben, zu welchem du berufen worden bist und bekannt hast das gute Bekenntnis vor vielen Zeugen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Ich gebiete dir vor Gott, der alles am Leben erhält, und Christo Jesu, der vor Pontius Pilatus das gute Bekenntnis bezeugt hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'daß du das Gebot unbefleckt, unsträflich bewahrst bis zur Erscheinung unseres Herrn Jesus Christus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'welche zu seiner Zeit zeigen wird der selige und alleinige Machthaber, der König der Könige und Herr der Herren,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'der allein Unsterblichkeit hat, der ein unzugängliches Licht bewohnt, den keiner der Menschen gesehen hat noch sehen kann, welchem Ehre sei und ewige Macht! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Den Reichen in dem gegenwärtigen Zeitlauf gebiete, nicht hochmütig zu sein, noch auf die Ungewißheit des Reichtums Hoffnung zu setzen, sondern auf Gott, der uns alles reichlich darreicht zum Genuß;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Gutes zu tun, reich zu sein in guten Werken, freigebig zu sein, mitteilsam,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'indem sie sich selbst eine gute Grundlage auf die Zukunft sammeln, auf daß sie das wirkliche Leben ergreifen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'O Timotheus, bewahre das anvertraute Gut, indem du dich von den ungöttlichen, eitlen Reden und Widersprüchen der fälschlich sogenannten Kenntnis wegwendest,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'zu welcher sich bekennend etliche von dem Glauben abgeirrt sind. Die Gnade sei mit dir!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paulus, Apostel Jesu Christi durch Gottes Willen, nach Verheißung des Lebens, das in Christo Jesu ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Timotheus, meinem geliebten Kinde: Gnade, Barmherzigkeit, Friede von Gott, dem Vater, und Christo Jesu, unserem Herrn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Ich danke Gott, dem ich von meinen Voreltern her mit reinem Gewissen diene, wie unablässig ich deiner gedenke in meinen Gebeten, Nacht und Tag,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'voll Verlangen, dich zu sehen, indem ich eingedenk bin deiner Tränen, auf daß ich mit Freude erfüllt sein möge;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'indem ich mich erinnere des ungeheuchelten Glaubens in dir, der zuerst wohnte in deiner Großmutter Lois und deiner Mutter Eunike, ich bin aber überzeugt, auch in dir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Um welcher Ursache willen ich dich erinnere, die Gnadengabe Gottes anzufachen, die in dir ist durch das Auflegen meiner Hände.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Denn Gott hat uns nicht einen Geist der Furchtsamkeit gegeben, sondern der Kraft und der Liebe und der Besonnenheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'So schäme dich nun nicht des Zeugnisses unseres Herrn noch meiner, seines Gefangenen, sondern leide Trübsal mit dem Evangelium, nach der Kraft Gottes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'der uns errettet hat und berufen mit heiligem Rufe, nicht nach unseren Werken, sondern nach seinem eigenen Vorsatz und der Gnade, die uns in Christo Jesu vor den Zeiten der Zeitalter gegeben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'jetzt aber geoffenbart worden ist durch die Erscheinung unseres Heilandes Jesus Christus, welcher den Tod zunichte gemacht, aber Leben und Unverweslichkeit ans Licht gebracht hat durch das Evangelium,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'zu welchem ich bestellt worden bin als Herold und Apostel und Lehrer der Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Um welcher Ursache willen ich dies auch leide; aber ich schäme mich nicht, denn ich weiß, wem ich geglaubt habe, und bin überzeugt, daß er mächtig ist, das ihm von mir anvertraute Gut auf jenen Tag zu bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Halte fest das Bild gesunder Worte, die du von mir gehört hast, in Glauben und Liebe, die in Christo Jesu sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Bewahre das schöne anvertraute Gut durch den Heiligen Geist, der in uns wohnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Du weißt dieses, daß alle, die in Asien sind, sich von mir abgewandt haben, unter welchen Phygelus ist und Hermogenes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Der Herr gebe dem Hause des Onesiphorus Barmherzigkeit, denn er hat mich oft erquickt und sich meiner Kette nicht geschämt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'sondern als er in Rom war, suchte er mich fleißig auf und fand mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Der Herr gebe ihm, daß er von seiten des Herrn Barmherzigkeit finde an jenem Tage! Und wieviel er in Ephesus diente, weißt du am besten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Du nun, mein Kind, sei stark in der Gnade, die in Christo Jesu ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'und was du von mir in Gegenwart vieler Zeugen gehört hast, das vertraue treuen Leuten an, welche tüchtig sein werden, auch andere zu lehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Nimm teil an den Trübsalen als ein guter Kriegsmann Jesu Christi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Niemand, der Kriegsdienste tut, verwickelt sich in die Beschäftigungen des Lebens, auf daß er dem gefalle, der ihn angeworben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Wenn aber auch jemand kämpft, so wird er nicht gekrönt, er habe denn gesetzmäßig gekämpft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Der Ackerbauer muß, um die Früchte zu genießen, zuerst arbeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Bedenke, was ich sage; denn der Herr wird dir Verständnis geben in allen Dingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Halte im Gedächtnis Jesum Christum, auferweckt aus den Toten, aus dem Samen Davids, nach meinem Evangelium,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'in welchem ich Trübsal leide bis zu Banden, wie ein Übeltäter; aber das Wort Gottes ist nicht gebunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Deswegen erdulde ich alles um der Auserwählten willen, auf daß auch sie die Seligkeit erlangen, die in Christo Jesu ist, mit ewiger Herrlichkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Das Wort ist gewiß; denn wenn wir mitgestorben sind, so werden wir auch mitleben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'wenn wir ausharren, so werden wir auch mitherrschen; wenn wir verleugnen, so wird auch er uns verleugnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'wenn wir untreu sind, er bleibt treu, denn er kann sich selbst nicht verleugnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Dies bringe in Erinnerung, indem du ernstlich vor dem Herrn bezeugst, nicht Wortstreit zu führen, was zu nichts nütze, sondern zum Verderben der Zuhörer ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Befleißige dich, dich selbst Gott bewährt darzustellen als einen Arbeiter, der sich nicht zu schämen hat, der das Wort der Wahrheit recht teilt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Die ungöttlichen eitlen Geschwätze aber vermeide; denn sie werden zu weiterer Gottlosigkeit fortschreiten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'und ihr Wort wird um sich fressen wie ein Krebs; unter welchen Hymenäus ist und Philetus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'die von der Wahrheit abgeirrt sind, indem sie sagen, daß die Auferstehung schon geschehen sei, und den Glauben etlicher zerstören.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Doch der feste Grund Gottes steht und hat dieses Siegel: Der Herr kennt, die sein sind; und: Jeder, der den Namen des Herrn nennt, stehe ab von der Ungerechtigkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'In einem großen Hause aber sind nicht allein goldene und silberne Gefäße, sondern auch hölzerne und irdene, und die einen zur Ehre, die anderen aber zur Unehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Wenn nun jemand sich von diesen reinigt, so wird er ein Gefäß zur Ehre sein, geheiligt, nützlich dem Hausherrn, zu jedem guten Werke bereitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Die jugendlichen Lüste aber fliehe; strebe aber nach Gerechtigkeit, Glauben, Liebe, Frieden mit denen, die den Herrn anrufen aus reinem Herzen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Aber die törichten und ungereimten Streitfragen weise ab, da du weißt, daß sie Streitigkeiten erzeugen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Ein Knecht des Herrn aber soll nicht streiten, sondern gegen alle milde sein, lehrfähig, duldsam,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'der in Sanftmut die Widersacher zurechtweist, ob ihnen Gott nicht etwa Buße gebe zur Erkenntnis der Wahrheit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'und sie wieder nüchtern werden aus dem Fallstrick des Teufels, die von ihm gefangen sind, für seinen Willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Dieses aber wisse, daß in den letzten Tagen schwere Zeiten da sein werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'denn die Menschen werden eigenliebig sein, geldliebend, prahlerisch, hochmütig, Lästerer, den Eltern ungehorsam, undankbar, heillos,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'ohne natürliche Liebe, unversöhnlich, Verleumder, unenthaltsam, grausam, das Gute nicht liebend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Verräter, verwegen, aufgeblasen, mehr das Vergnügen liebend als Gott,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'die eine Form der Gottseligkeit haben, deren Kraft aber verleugnen; und von diesen wende dich weg.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Denn aus diesen sind, die sich in die Häuser schleichen und Weiblein gefangen nehmen, welche, mit Sünden beladen, von mancherlei Lüsten getrieben werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'die immerdar lernen und niemals zur Erkenntnis der Wahrheit kommen können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Gleicherweise aber wie Jannes und Jambres Mose widerstanden, also widerstehen auch diese der Wahrheit, Menschen, verderbt in der Gesinnung, unbewährt hinsichtlich des Glaubens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Sie werden aber nicht weiter fortschreiten, denn ihr Unverstand wird allen offenbar werden, wie auch der von jenen es wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Du aber hast genau erkannt meine Lehre, mein Betragen, meinen Vorsatz, meinen Glauben, meine Langmut, meine Liebe, mein Ausharren,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'meine Verfolgungen, meine Leiden: welcherlei Leiden mir widerfahren sind in Antiochien, in Ikonium, in Lystra; welcherlei Verfolgungen ich ertrug, und aus allen hat der Herr mich gerettet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Alle aber auch, die gottselig leben wollen in Christo Jesu, werden verfolgt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Böse Menschen aber und Gaukler werden im Bösen fortschreiten, indem sie verführen und verführt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Du aber bleibe in dem, was du gelernt hast und wovon du völlig überzeugt bist, da du weißt, von wem du gelernt hast,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'und weil du von Kind auf die heiligen Schriften kennst, die vermögend sind, dich weise zu machen zur Seligkeit durch den Glauben, der in Christo Jesu ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Alle Schrift ist von Gott eingegeben und nütze zur Lehre, zur Überführung, zur Zurechtweisung, zur Unterweisung in der Gerechtigkeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'auf daß der Mensch Gottes vollkommen sei, zu jedem guten Werke völlig geschickt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Ich bezeuge ernstlich vor Gott und Christo Jesu, der da richten wird Lebendige und Tote, und bei seiner Erscheinung und seinem Reiche:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Predige das Wort, halte darauf in gelegener und ungelegener Zeit; überführe, strafe, ermahne mit aller Langmut und Lehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Denn es wird eine Zeit sein, da sie die gesunde Lehre nicht ertragen, sondern nach ihren eigenen Lüsten sich selbst Lehrer aufhäufen werden, indem es ihnen in den Ohren kitzelt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'und sie werden die Ohren von der Wahrheit abkehren und zu den Fabeln sich hinwenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Du aber sei nüchtern in allem, leide Trübsal, tue das Werk eines Evangelisten, vollführe deinen Dienst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Denn ich werde schon als Trankopfer gesprengt, und die Zeit meines Abscheidens ist vorhanden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Ich habe den guten Kampf gekämpft, ich habe den Lauf vollendet, ich habe den Glauben bewahrt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'fortan liegt mir bereit die Krone der Gerechtigkeit, welche der Herr, der gerechte Richter, mir zur Vergeltung geben wird an jenem Tage; nicht allein aber mir, sondern auch allen, die seine Erscheinung lieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Befleißige dich, bald zu mir zu kommen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'denn Demas hat mich verlassen, da er den jetzigen Zeitlauf liebgewonnen hat, und ist nach Thessalonich gegangen, Krescenz nach Galatien, Titus nach Dalmatien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Lukas ist allein bei mir. Nimm Markus und bringe ihn mit dir, denn er ist mir nützlich zum Dienst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tychikus aber habe ich nach Ephesus gesandt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Den Mantel, den ich in Troas bei Karpus zurückließ, bringe mit, wenn du kommst, und die Bücher, besonders die Pergamente.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexander, der Schmied, hat mir viel Böses erzeigt; der Herr wird ihm vergelten nach seinen Werken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Vor ihm hüte auch du dich, denn er hat unseren Worten sehr widerstanden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Bei meiner ersten Verantwortung stand mir niemand bei, sondern alle verließen mich; es werde ihnen nicht zugerechnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Der Herr aber stand mir bei und stärkte mich, auf daß durch mich die Predigt vollbracht werde, und alle die aus den Nationen hören möchten; und ich bin gerettet worden aus dem Rachen des Löwen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Der Herr wird mich retten von jedem bösen Werk und bewahren für sein himmlisches Reich, welchem die Herrlichkeit sei von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Grüße Priska und Aquila und das Haus des Onesiphorus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erastus blieb in Korinth; Trophimus aber habe ich in Milet krank zurückgelassen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Befleißige dich, vor dem Winter zu kommen. Es grüßt dich Eubulus und Pudens und Linus und Klaudia und die Brüder alle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Der Herr Jesus Christus sei mit deinem Geiste! Die Gnade sei mit euch!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paulus, Knecht Gottes, aber Apostel Jesu Christi, nach dem Glauben der Auserwählten Gottes und nach der Erkenntnis der Wahrheit, die nach der Gottseligkeit ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'in der Hoffnung des ewigen Lebens, welches Gott, der nicht lügen kann, verheißen hat vor ewigen Zeiten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'zu seiner Zeit aber sein Wort geoffenbart hat durch die Predigt, die mir anvertraut worden ist nach Befehl unseres Heilandgottes');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Titus, meinem echten Kinde nach unserem gemeinschaftlichen Glauben: Gnade und Friede von Gott, dem Vater, und Christo Jesu, unserem Heilande!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Deswegen ließ ich dich in Kreta, daß du, was noch mangelte, in Ordnung bringen und in jeder Stadt Älteste anstellen möchtest, wie ich dir geboten hatte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Wenn jemand untadelig ist, eines Weibes Mann, der gläubige Kinder hat, die nicht eines ausschweifenden Lebens beschuldigt oder zügellos sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Denn der Aufseher muß untadelig sein als Gottes Verwalter, nicht eigenmächtig, nicht zornmütig, nicht dem Wein ergeben, nicht ein Schläger, nicht schändlichem Gewinn nachgehend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'sondern gastfrei, das Gute liebend, besonnen, gerecht, fromm, enthaltsam,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'anhangend dem zuverlässigen Worte nach der Lehre, auf daß er fähig sei, sowohl mit der gesunden Lehre zu ermahnen, als auch die Widersprechenden zu überführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Denn es gibt viele zügellose Schwätzer und Betrüger, besonders die aus der Beschneidung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'denen man den Mund stopfen muß, welche ganze Häuser umkehren, indem sie um schändlichen Gewinnes willen lehren, was sich nicht geziemt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Es hat einer aus ihnen, ihr eigener Prophet, gesagt: \"Kreter sind immer Lügner, böse, wilde Tiere, faule Bäuche\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Dieses Zeugnis ist wahr; um dieser Ursache willen weise sie streng zurecht, auf daß sie gesund seien im Glauben');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'und nicht achten auf jüdische Fabeln und Gebote von Menschen, die sich von der Wahrheit abwenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Den Reinen ist alles rein; den Befleckten aber und Ungläubigen ist nichts rein, sondern befleckt ist sowohl ihre Gesinnung, als auch ihr Gewissen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Sie geben vor, Gott zu kennen, aber in den Werken verleugnen sie ihn und sind greulich und ungehorsam und zu jedem guten Werke unbewährt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Du aber rede, was der gesunden Lehre geziemt:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'daß die alten Männer nüchtern seien, würdig, besonnen, gesund im Glauben, in der Liebe, im Ausharren;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'die alten Frauen desgleichen in ihrem Betragen, wie es dem heiligen Stande geziemt, nicht verleumderisch, nicht Sklavinnen von vielem Wein, Lehrerinnen des Guten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'auf daß sie die jungen Frauen unterweisen, ihre Männer zu lieben, ihre Kinder zu lieben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'besonnen, keusch, mit häuslichen Arbeiten beschäftigt, gütig, den eigenen Männern unterwürfig zu sein, auf daß das Wort Gottes nicht verlästert werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Die Jünglinge desgleichen ermahne, besonnen zu sein,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'indem du in allem dich selbst als ein Vorbild guter Werke darstellst; in der Lehre Unverderbtheit, würdigen Ernst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'gesunde, nicht zu verurteilende Rede, auf daß der von der Gegenpartei sich schäme, indem er nichts Schlechtes über uns zu sagen hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Die Knechte ermahne, ihren eigenen Herren unterwürfig zu sein, in allem sich wohlgefällig zu machen, nicht widersprechend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'nichts unterschlagend, sondern alle gute Treue erweisend, auf daß sie die Lehre, die unseres Heilandgottes ist, zieren in allem.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Denn die Gnade Gottes ist erschienen, heilbringend für alle Menschen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'und unterweist uns, auf daß wir, die Gottlosigkeit und die weltlichen Lüste verleugnend, besonnen und gerecht und gottselig leben in dem jetzigen Zeitlauf,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'indem wir erwarten die glückselige Hoffnung und Erscheinung der Herrlichkeit unseres großen Gottes und Heilandes Jesus Christus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'der sich selbst für uns gegeben hat, auf daß er uns loskaufte von aller Gesetzlosigkeit und reinigte sich selbst ein Eigentumsvolk, eifrig in guten Werken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Dieses rede und ermahne und überführe mit aller Machtvollkommenheit. Laß dich niemand verachten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Erinnere sie, Obrigkeiten und Gewalten untertan zu sein, Gehorsam zu leisten, zu jedem guten Werke bereit zu sein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'niemand zu lästern, nicht streitsüchtig zu sein, gelinde, alle Sanftmut erweisend gegen alle Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Denn einst waren auch wir unverständig, ungehorsam, irregehend, dienten mancherlei Lüsten und Vergnügungen, führten unser Leben in Bosheit und Neid, verhaßt und einander hassend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Als aber die Güte und die Menschenliebe unseres Heilandgottes erschien,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'errettete er uns, nicht aus Werken, die, in Gerechtigkeit vollbracht, wir getan hatten, sondern nach seiner Barmherzigkeit durch die Waschung der Wiedergeburt und Erneuerung des Heiligen Geistes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'welchen er reichlich über uns ausgegossen hat durch Jesum Christum, unseren Heiland,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'auf daß wir, gerechtfertigt durch seine Gnade, Erben würden nach der Hoffnung des ewigen Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Das Wort ist gewiß; und ich will, daß du auf diesen Dingen fest bestehst, auf daß die, welche Gott geglaubt haben, Sorge tragen, gute Werke zu betreiben. Dies ist gut und nützlich für die Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Törichte Streitfragen aber und Geschlechtsregister und Zänkereien und Streitigkeiten über das Gesetz vermeide, denn sie sind unnütz und eitel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Einen sektiererischen Menschen weise ab nach einer ein-und zweimaligen Zurechtweisung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'da du weißt, daß ein solcher verkehrt ist und sündigt, indem er durch sich selbst verurteilt ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Wenn ich Artemas oder Tychikus zu dir senden werde, so befleißige dich, zu mir nach Nikopolis zu kommen, denn ich habe beschlossen, daselbst zu überwintern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zenas, dem Gesetzgelehrten, und Apollos gib mit Sorgfalt das Geleit, auf daß ihnen nichts mangle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Laß aber auch die Unsrigen lernen, für die notwendigen Bedürfnisse gute Werke zu betreiben, auf daß sie nicht unfruchtbar seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Es grüßen dich alle, die bei mir sind. Grüße, die uns lieben im Glauben. Die Gnade sei mit euch allen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paulus, ein Gefangener Christi Jesu, und Timotheus, der Bruder, Philemon, dem Geliebten und unserem Mitarbeiter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'und Appia, der Schwester, und Archippus, unserem Mitkämpfer, und der Versammlung, die in deinem Hause ist:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Gnade euch und Friede von Gott, unserem Vater, und dem Herrn Jesus Christus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Ich danke meinem Gott, indem ich allezeit deiner erwähne in meinen Gebeten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'da ich höre von deiner Liebe und von dem Glauben, den du an den Herrn Jesus und zu allen Heiligen hast,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'daß die Gemeinschaft deines Glaubens wirksam werde in der Anerkennung alles Guten, welches in uns ist gegen Christum Jesum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Denn wir haben große Freude und großen Trost durch deine Liebe, weil die Herzen der Heiligen durch dich, Bruder, erquickt worden sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Deshalb, obgleich ich große Freimütigkeit in Christo habe, dir zu gebieten, was sich geziemt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'so bitte ich doch vielmehr um der Liebe willen, da ich nun ein solcher bin, wie Paulus, der Alte, jetzt aber auch ein Gefangener Jesu Christi.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Ich bitte dich für mein Kind, das ich gezeugt habe in den Banden, Onesimus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'der dir einst unnütz war, jetzt aber dir und mir nützlich ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'den ich zu dir zurückgesandt habe ihn, das ist mein Herz;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'welchen ich bei mir behalten wollte, auf daß er statt deiner mir diene in den Banden des Evangeliums.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Aber ohne deinen Willen wollte ich nichts tun, auf daß deine Wohltat nicht wie gezwungen, sondern freiwillig sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Denn vielleicht ist er deswegen für eine Zeit von dir getrennt gewesen, auf daß du ihn für immer besitzen mögest,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'nicht länger als einen Sklaven, sondern mehr als einen Sklaven, als einen geliebten Bruder, besonders für mich, wieviel mehr aber für dich, sowohl im Fleische als im Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Wenn du mich nun für deinen Genossen hältst, so nimm ihn auf wie mich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Wenn er dir aber irgend ein Unrecht getan hat, oder dir etwas schuldig ist, so rechne dies mir an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Ich, Paulus, habe es mit meiner Hand geschrieben, ich will bezahlen; daß ich dir nicht sage, daß du auch dich selbst mir schuldig bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Ja, Bruder, ich möchte gern Nutzen an dir haben im Herrn; erquicke mein Herz in Christo.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Da ich deinem Gehorsam vertraue, so habe ich dir geschrieben, indem ich weiß, daß du auch mehr tun wirst, als ich sage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Zugleich aber bereite mir auch eine Herberge, denn ich hoffe, daß ich durch eure Gebete euch werde geschenkt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Es grüßt dich Epaphras, mein Mitgefangener in Christo Jesu,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Markus, Aristarchus, Demas, Lukas, meine Mitarbeiter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Die Gnade unseres Herrn Jesus Christus sei mit eurem Geiste!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Nachdem Gott vielfältig und auf vielerlei Weise ehemals zu den Vätern geredet hat in den Propheten, hat er am Ende dieser Tage zu uns geredet im Sohne,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'den er gesetzt hat zum Erben aller Dinge, durch den er auch die Welten gemacht hat;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'welcher, der Abglanz seiner Herrlichkeit und der Abdruck seines Wesens seiend und alle Dinge durch das Wort seiner Macht tragend, nachdem er durch sich selbst die Reinigung der Sünden bewirkt, sich gesetzt hat zur Rechten der Majestät in der Höhe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'indem er um so viel besser geworden ist als die Engel, als er einen vorzüglicheren Namen vor ihnen ererbt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Denn zu welchem der Engel hat er je gesagt: \"Du bist mein Sohn, heute habe ich dich gezeugt\"? Und wiederum: \"Ich will ihm zum Vater, und er soll mir zum Sohne sein\"?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Wenn er aber den Erstgeborenen wiederum in den Erdkreis einführt, spricht er: \"Und alle Engel Gottes sollen ihn anbeten\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Und in Bezug auf die Engel zwar spricht er: \"Der seine Engel zu Winden macht und seine Diener zu einer Feuerflamme\"; in Bezug auf den Sohn aber:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, '\"Dein Thron, o Gott, ist von Ewigkeit zu Ewigkeit, und ein Zepter der Aufrichtigkeit ist das Zepter deines Reiches;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'du hast Gerechtigkeit geliebt und Gesetzlosigkeit gehaßt; darum hat Gott, dein Gott, dich gesalbt mit Freudenöl über deine Genossen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Und: \"Du, Herr, hast im Anfang die Erde gegründet, und die Himmel sind Werke deiner Hände;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'sie werden untergehen, du aber bleibst; und sie alle werden veralten wie ein Kleid,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'und wie ein Gewand wirst du sie zusammenwickeln, und sie werden verwandelt werden. Du aber bist derselbe, und deine Jahre werden nicht vergehen.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Zu welchem der Engel aber hat er je gesagt: \"Setze dich zu meiner Rechten, bis ich deine Feinde lege zum Schemel deiner Füße\"?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Sind sie nicht alle dienstbare Geister, ausgesandt zum Dienst um derer willen, welche die Seligkeit ererben sollen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Deswegen sollen wir um so mehr auf das achten, was wir gehört haben, damit wir nicht etwa abgleiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Denn wenn das durch Engel geredete Wort fest war und jede Übertretung und jeder Ungehorsam gerechte Vergeltung empfing,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'wie werden wir entfliehen, wenn wir eine so große Errettung vernachlässigen? Welche den Anfang ihrer Verkündigung durch den Herrn empfangen hat und uns von denen bestätigt worden ist, die es gehört haben, indem Gott außerdem mitzeugte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'sowohl durch Zeichen als durch Wunder und mancherlei Wunderwerke und Austeilungen des Heiligen Geistes nach seinem Willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Denn nicht Engeln hat er unterworfen den zukünftigen Erdkreis, von welchem wir reden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'es hat aber irgendwo jemand bezeugt und gesagt: \"Was ist der Mensch, daß du seiner gedenkst, oder des Menschen Sohn, daß du auf ihn siehst?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Du hast ihn ein wenig unter die Engel erniedrigt; mit Herrlichkeit und Ehre hast du ihn gekrönt und ihn gesetzt über die Werke deiner Hände;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'du hast alles seinen Füßen unterworfen.\" Denn indem er ihm alles unterworfen, hat er nichts gelassen, das ihm nicht unterworfen wäre; jetzt aber sehen wir ihm noch nicht alles unterworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Wir sehen aber Jesum, der ein wenig unter die Engel wegen des Leidens des Todes erniedrigt war, mit Herrlichkeit und Ehre gekrönt so daß er durch Gottes Gnade für alles den Tod schmeckte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Denn es geziemte ihm, um deswillen alle Dinge und durch den alle Dinge sind, indem er viele Söhne zur Herrlichkeit brachte, den Urheber ihrer Errettung durch Leiden vollkommen zu machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Denn sowohl der, welcher heiligt, als auch die, welche geheiligt werden, sind alle von einem; um welcher Ursache willen er sich nicht schämt, sie Brüder zu nennen, indem er spricht:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, '\"Ich will deinen Namen kundtun meinen Brüdern; inmitten der Versammlung will ich dir lobsingen\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Und wiederum: \"Ich will mein Vertrauen auf ihn setzen\". Und wiederum: \"Siehe, ich und die Kinder, die Gott mir gegeben hat\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Weil nun die Kinder Blutes und Fleisches teilhaftig sind, hat auch er in gleicher Weise an denselben teilgenommen, auf daß er durch den Tod den zunichte machte, der die Macht des Todes hat, das ist den Teufel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'und alle die befreite, welche durch Todesfurcht das ganze Leben hindurch der Knechtschaft unterworfen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Denn er nimmt sich fürwahr nicht der Engel an, sondern des Samens Abrahams nimmt er sich an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Daher mußte er in allem den Brüdern gleich werden, auf daß er in den Sachen mit Gott ein barmherziger und treuer Hoherpriester werden möchte, um die Sünden des Volkes zu sühnen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'denn worin er selbst gelitten hat, als er versucht wurde, vermag er denen zu helfen, die versucht werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Daher, heilige Brüder, Genossen der himmlischen Berufung, betrachtet den Apostel und Hohenpriester unseres Bekenntnisses, Jesum,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'der treu ist dem, der ihn bestellt hat, wie es auch Moses war in seinem ganzen Hause.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Denn dieser ist größerer Herrlichkeit würdig geachtet worden als Moses, insofern größere Ehre als das Haus der hat, der es bereitet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Denn jedes Haus wird von jemand bereitet; der aber alles bereitet hat, ist Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Und Moses zwar war treu in seinem ganzen Hause als Diener, zum Zeugnis von dem, was hernach geredet werden sollte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Christus aber als Sohn über sein Haus, dessen Haus wir sind, wenn wir anders die Freimütigkeit und den Ruhm der Hoffnung bis zum Ende standhaft festhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Deshalb, wie der Heilige Geist spricht: \"Heute, wenn ihr seine Stimme höret,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'verhärtet eure Herzen nicht, wie in der Erbitterung, an dem Tage der Versuchung in der Wüste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'wo eure Väter mich versuchten, indem sie mich prüften, und sie sahen doch meine Werke vierzig Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Deshalb zürnte ich diesem Geschlecht und sprach: Allezeit gehen sie irre mit dem Herzen; aber sie haben meine Wege nicht erkannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'So schwur ich in meinem Zorn: Wenn sie in meine Ruhe eingehen werden!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Sehet zu, Brüder, daß nicht etwa in jemand von euch ein böses Herz des Unglaubens sei in dem Abfallen vom lebendigen Gott,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'sondern ermuntert euch selbst jeden Tag, solange es \"heute\" heißt, auf daß niemand von euch verhärtet werde durch Betrug der Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Denn wir sind Genossen des Christus geworden, wenn wir anders den Anfang der Zuversicht bis zum Ende standhaft festhalten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'indem gesagt wird: \"Heute, wenn ihr seine Stimme höret, verhärtet eure Herzen nicht, wie in der Erbitterung\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, '(Denn welche, als sie gehört hatten, haben ihn erbittert? Waren es aber nicht alle, die durch Moses von Ägypten ausgezogen waren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Welchen aber zürnte er vierzig Jahre? Nicht denen, welche gesündigt hatten, deren Leiber in der Wüste fielen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Welchen aber schwur er, daß sie nicht in seine Ruhe eingehen sollten, als nur denen, die ungehorsam gewesen waren?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Und wir sehen, daß sie nicht eingehen konnten wegen des Unglaubens.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Fürchten wir uns nun, daß nicht etwa, da eine Verheißung, in seine Ruhe einzugehen, hinterlassen ist, jemand von euch scheine zurückgeblieben zu sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Denn auch uns ist eine gute Botschaft verkündigt worden, gleichwie auch jenen; aber das Wort der Verkündigung nützte jenen nicht, weil es bei denen, die es hörten, nicht mit dem Glauben vermischt war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Denn wir, die wir geglaubt haben, gehen in die Ruhe ein, wie er gesagt hat: \"So schwur ich in meinem Zorn: Wenn sie in meine Ruhe eingehen werden!\" wiewohl die Werke von Grundlegung der Welt an geworden waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Denn er hat irgendwo von dem siebten Tage also gesprochen: \"Und Gott ruhte am siebten Tage von allen seinen Werken\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Und an dieser Stelle wiederum: \"Wenn sie in meine Ruhe eingehen werden!\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Weil nun übrigbleibt, daß etliche in dieselbe eingehen, und die, welchen zuerst die gute Botschaft verkündigt worden ist, des Ungehorsams wegen nicht eingegangen sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'so bestimmt er wiederum einen gewissen Tag: \"Heute\", in David nach so langer Zeit sagend, wie vorhin gesagt worden ist: \"Heute, wenn ihr seine Stimme höret, verhärtet eure Herzen nicht\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Denn wenn Josua sie in die Ruhe gebracht hätte, so würde er danach nicht von einem anderen Tage geredet haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Also bleibt noch eine Sabbathruhe dem Volke Gottes aufbewahrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Denn wer in seine Ruhe eingegangen ist, der ist auch zur Ruhe gelangt von seinen Werken, gleichwie Gott von seinen eigenen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Laßt uns nun Fleiß anwenden, in jene Ruhe einzugehen, auf daß nicht jemand nach demselben Beispiel des Ungehorsams falle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Denn das Wort Gottes ist lebendig und wirksam und schärfer als jedes zweischneidige Schwert, und durchdringend bis zur Scheidung von Seele und Geist, sowohl der Gelenke als auch des Markes, und ein Beurteiler der Gedanken und Gesinnungen des Herzens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'und kein Geschöpf ist vor ihm unsichtbar, sondern alles bloß und aufgedeckt vor den Augen dessen, mit dem wir es zu tun haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Da wir nun einen großen Hohenpriester haben, der durch die Himmel gegangen ist, Jesum, den Sohn Gottes, so laßt uns das Bekenntnis festhalten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'denn wir haben nicht einen Hohenpriester, der nicht Mitleid zu haben vermag mit unseren Schwachheiten, sondern der in allem versucht worden ist in gleicher Weise wie wir, ausgenommen die Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Laßt uns nun mit Freimütigkeit hinzutreten zu dem Thron der Gnade, auf daß wir Barmherzigkeit empfangen und Gnade finden zur rechtzeitigen Hilfe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Denn jeder aus Menschen genommene Hohepriester wird für Menschen bestellt in den Sachen mit Gott, auf daß er sowohl Gaben als auch Schlachtopfer für Sünden darbringe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'der Nachsicht zu haben vermag mit den Unwissenden und Irrenden, da auch er selbst mit Schwachheit umgeben ist;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'und um dieser willen muß er, wie für das Volk, so auch für sich selbst opfern für die Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Und niemand nimmt sich selbst die Ehre, sondern als von Gott berufen, gleichwie auch Aaron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Also hat auch der Christus sich nicht selbst verherrlicht, um Hoherpriester zu werden, sondern der, welcher zu ihm gesagt hat: \"Du bist mein Sohn, heute habe ich dich gezeugt\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Wie er auch an einer anderen Stelle sagt: \"Du bist Priester in Ewigkeit nach der Ordnung Melchisedeks.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Der in den Tagen seines Fleisches, da er sowohl Bitten als Flehen dem, der ihn aus dem Tode zu erretten vermochte, mit starkem Geschrei und Tränen dargebracht hat (und um seiner Frömmigkeit willen erhört worden ist),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'obwohl er Sohn war, an dem, was er litt, den Gehorsam lernte; und, vollendet worden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'ist er allen, die ihm gehorchen, der Urheber ewigen Heils geworden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'von Gott begrüßt als Hoherpriester nach der Ordnung Melchisedeks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Über diesen haben wir viel zu sagen, und was mit Worten schwer auszulegen ist, weil ihr im Hören träge geworden seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Denn da ihr der Zeit nach Lehrer sein solltet, bedürfet ihr wiederum, daß man euch lehre, welches die Elemente des Anfangs der Aussprüche Gottes sind; und ihr seid solche geworden, die der Milch bedürfen und nicht der festen Speise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Denn jeder, der noch Milch genießt, ist unerfahren im Worte der Gerechtigkeit, denn er ist ein Unmündiger;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'die feste Speise aber ist für Erwachsene, welche vermöge der Gewohnheit geübte Sinne haben zur Unterscheidung des Guten sowohl als auch des Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Deshalb, das Wort von dem Anfang des Christus lassend, laßt uns fortfahren zum vollen Wuchse und nicht wiederum einen Grund legen mit der Buße von toten Werken und dem Glauben an Gott,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'der Lehre von Waschungen und dem Händeauflegen und der Totenauferstehung und dem ewigen Gericht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Und dies wollen wir tun, wenn Gott es erlaubt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Denn es ist unmöglich, diejenigen, welche einmal erleuchtet waren und geschmeckt haben die himmlische Gabe, und teilhaftig geworden sind des Heiligen Geistes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'und geschmeckt haben das gute Wort Gottes und die Wunderwerke des zukünftigen Zeitalters, und abgefallen sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'wiederum zur Buße zu erneuern, indem sie den Sohn Gottes für sich selbst kreuzigen und ihn zur Schau stellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Denn das Land, welches den häufig über dasselbe kommenden Regen trinkt und nützliches Kraut hervorbringt für diejenigen, um derentwillen es auch bebaut wird, empfängt Segen von Gott;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'wenn es aber Dornen und Disteln hervorbringt, so ist es unbewährt und dem Fluche nahe, und sein Ende ist die Verbrennung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Wir aber sind in Bezug auf euch, Geliebte, von besseren und mit der Seligkeit verbundenen Dingen überzeugt, wenn wir auch also reden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Denn Gott ist nicht ungerecht, eures Werkes zu vergessen und der Liebe, die ihr gegen seinen Namen bewiesen, da ihr den Heiligen gedient habt und dienet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Wir wünschen aber sehr, daß ein jeder von euch denselben Fleiß beweise zur vollen Gewißheit der Hoffnung bis ans Ende,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'auf daß ihr nicht träge werdet, sondern Nachahmer derer, welche durch Glauben und Ausharren die Verheißungen ererben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Denn als Gott dem Abraham Verheißung gab, schwur er, weil er bei keinem Größeren zu schwören hatte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'bei sich selbst und sprach: \"Wahrlich, reichlich werde ich dich segnen und sehr werde ich dich mehren\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Und nachdem er also ausgeharrt hatte, erlangte er die Verheißung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Denn Menschen schwören wohl bei einem Größeren, und der Eid ist ihnen ein Ende alles Widerspruchs zur Bestätigung;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'worin Gott, da er den Erben der Verheißung die Unwandelbarkeit seines Ratschlusses überschwenglicher beweisen wollte, mit einem Eide ins Mittel getreten ist,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'auf daß wir durch zwei unveränderliche Dinge, wobei es unmöglich war, daß Gott lügen sollte, einen starken Trost hätten, die wir Zuflucht genommen haben zum Ergreifen der vor uns liegenden Hoffnung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'welche wir als einen sicheren und festen Anker der Seele haben, der auch in das Innere des Vorhangs hineingeht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'wohin Jesus als Vorläufer für uns eingegangen ist, welcher Hoherpriester geworden in Ewigkeit nach der Ordnung Melchisedeks.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Denn dieser Melchisedek, König von Salem, Priester Gottes, des Höchsten, der Abraham entgegenging, als er von der Schlacht der Könige zurückkehrte, und ihn segnete,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'welchem auch Abraham den Zehnten zuteilte von allem; der erstlich verdolmetscht König der Gerechtigkeit heißt, sodann aber auch König von Salem, das ist König des Friedens,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'ohne Vater, ohne Mutter, ohne Geschlechtsregister, weder Anfang der Tage noch Ende des Lebens habend, aber dem Sohne Gottes verglichen, bleibt Priester auf immerdar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Schauet aber, wie groß dieser war, welchem selbst Abraham, der Patriarch, den Zehnten von der Beute gab.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Und zwar haben die von den Söhnen Levi, welche das Priestertum empfangen, ein Gebot, den Zehnten von dem Volke zu nehmen nach dem Gesetz, das ist von ihren Brüdern, wiewohl sie aus den Lenden Abrahams gekommen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Er aber, der sein Geschlecht nicht von ihnen ableitete, hat den Zehnten von Abraham genommen und den gesegnet, der die Verheißungen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Ohne allen Widerspruch aber wird das Geringere von dem Besseren gesegnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Und hier zwar empfangen Menschen, welche sterben, die Zehnten, dort aber einer, von welchem bezeugt wird, daß er lebe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'und sozusagen ist durch Abraham auch Levi, der die Zehnten empfängt, gezehntet worden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'denn er war noch in der Lende des Vaters, als Melchisedek ihm entgegenging.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Wenn nun die Vollkommenheit durch das levitische Priestertum wäre (denn in Verbindung mit demselben hat das Volk das Gesetz empfangen), welches Bedürfnis war noch vorhanden, daß ein anderer Priester nach der Ordnung Melchisedeks aufstehe, und nicht nach der Ordnung Aarons genannt werde?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Denn wenn das Priestertum geändert wird, so findet notwendig auch eine Änderung des Gesetzes statt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Denn der, von welchem dies gesagt wird, gehört zu einem anderen Stamme, aus welchem niemand des Altars gewartet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Denn es ist offenbar, daß unser Herr aus Juda entsprossen ist, zu welchem Stamme Moses nichts in Bezug auf Priester geredet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Und es ist noch weit augenscheinlicher, wenn, nach der Gleichheit Melchisedeks, ein anderer Priester aufsteht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'der es nicht nach dem Gesetz eines fleischlichen Gebots geworden ist, sondern nach der Kraft eines unauflöslichen Lebens.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Denn ihm wird bezeugt: \"Du bist Priester in Ewigkeit nach der Ordnung Melchisedeks\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Denn da ist eine Abschaffung des vorhergehenden Gebots seiner Schwachheit und Nutzlosigkeit wegen');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, '(denn das Gesetz hat nichts zur Vollendung gebracht) und die Einführung einer besseren Hoffnung, durch welche wir Gott nahen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Und inwiefern dies nicht ohne Eidschwur geschah,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, '(denn jene sind ohne Eidschwur Priester geworden, dieser aber mit Eidschwur durch den, der zu ihm sprach: \"Der Herr hat geschworen, und es wird ihn nicht gereuen: Du bist Priester in Ewigkeit nach der Ordnung Melchisedeks \"),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'insofern ist Jesus eines besseren Bundes Bürge geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Und jener sind mehrere Priester geworden, weil sie durch den Tod verhindert waren zu bleiben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'dieser aber, weil er in Ewigkeit bleibt, hat ein unveränderliches Priestertum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Daher vermag er auch völlig zu erretten, die durch ihn Gott nahen, indem er immerdar lebt, um sich für sie zu verwenden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Denn ein solcher Hoherpriester geziemte uns: heilig, unschuldig, unbefleckt, abgesondert von den Sündern und höher als die Himmel geworden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'der nicht Tag für Tag nötig hat, wie die Hohenpriester, zuerst für die eigenen Sünden Schlachtopfer darzubringen, sodann für die des Volkes; denn dieses hat er ein für allemal getan, als er sich selbst geopfert hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Denn das Gesetz bestellt Menschen zu Hohenpriestern, die Schwachheit haben; das Wort des Eidschwurs aber, der nach dem Gesetz gekommen ist, einen Sohn, vollendet in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Die Summe dessen aber, was wir sagen, ist: Wir haben einen solchen Hohenpriester, der sich gesetzt hat zur Rechten des Thrones der Majestät in den Himmeln,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'ein Diener des Heiligtums und der wahrhaftigen Hütte, welche der Herr errichtet hat, nicht der Mensch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Denn jeder Hohepriester wird bestellt, um sowohl Gaben als auch Schlachtopfer darzubringen; daher ist es notwendig, daß auch dieser etwas habe, das er darbringe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Wenn er nun auf Erden wäre, so wäre er nicht einmal Priester, weil solche da sind, die nach dem Gesetz die Gaben darbringen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, '(welche dem Abbilde und Schatten der himmlischen Dinge dienen, gleichwie Moses eine göttliche Weisung empfing, als er im Begriff war, die Hütte aufzurichten; denn \"siehe\", spricht er, \"daß du alles nach dem Muster machest, das dir auf dem Berge gezeigt worden ist\").');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Jetzt aber hat er einen vortrefflicheren Dienst erlangt, insofern er auch Mittler ist eines besseren Bundes, der auf Grund besserer Verheißungen gestiftet ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Denn wenn jener erste Bund tadellos wäre, so wäre kein Raum gesucht worden für einen zweiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Denn tadelnd spricht er zu ihnen: \"Siehe, es kommen Tage, spricht der Herr, da werde ich in Bezug auf das Haus Israel und in Bezug auf das Haus Juda einen neuen Bund vollziehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'nicht nach dem Bunde, den ich mit ihren Vätern machte an dem Tage, da ich ihre Hand ergriff, um sie aus dem Lande Ägypten herauszuführen; denn sie blieben nicht in meinem Bunde, und ich kümmerte mich nicht um sie, spricht der Herr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Denn dies ist der Bund, den ich dem Hause Israel errichten werde nach jenen Tagen, spricht der Herr: Indem ich meine Gesetze in ihren Sinn gebe, werde ich sie auch auf ihre Herzen schreiben; und ich werde ihnen zum Gott, und sie werden mir zum Volke sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Und sie werden nicht ein jeder seinen Mitbürger und ein jeder seinen Bruder lehren und sagen: Erkenne den Herrn! denn alle werden mich erkennen vom Kleinen bis zum Großen unter ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Denn ich werde ihren Ungerechtigkeiten gnädig sein, und ihrer Sünden und ihrer Gesetzlosigkeiten werde ich nie mehr gedenken.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Indem er sagt: \"einen neuen\", hat er den ersten alt gemacht; was aber alt wird und veraltet, ist dem Verschwinden nahe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Es hatte nun zwar auch der erste Bund Satzungen des Dienstes und das Heiligtum, ein weltliches.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Denn eine Hütte wurde zugerichtet, die vordere, in welcher sowohl der Leuchter war als auch der Tisch und die Darstellung der Brote, welche das Heilige genannt wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'hinter dem zweiten Vorhang aber eine Hütte, welche das Allerheiligste genannt wird,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'die ein goldenes Räucherfaß hatte und die Lade des Bundes, überall mit Gold überdeckt, in welcher der goldene Krug war, der das Manna enthielt, und der Stab Aarons, der gesproßt hatte, und die Tafeln des Bundes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'oben über derselben aber die Cherubim der Herrlichkeit, den Versöhnungsdeckel überschattend, von welchen Dingen jetzt nicht im einzelnen zu reden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Da nun dieses also eingerichtet ist, gehen in die vordere Hütte allezeit die Priester hinein und vollbringen den Dienst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'in die zweite aber einmal des Jahres allein der Hohepriester, nicht ohne Blut, welches er für sich selbst und für die Verirrungen des Volkes darbringt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'wodurch der Heilige Geist dieses anzeigt, daß der Weg zum Heiligtum noch nicht geoffenbart ist, solange die vordere Hütte noch Bestand hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'welches ein Gleichnis auf die gegenwärtige Zeit ist, nach welchem sowohl Gaben als auch Schlachtopfer dargebracht werden, die dem Gewissen nach den nicht vollkommen machen können, der den Gottesdienst übt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'welcher allein in Speisen und Getränken und verschiedenen Waschungen besteht, in Satzungen des Fleisches, auferlegt bis auf die Zeit der Zurechtbringung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Christus aber, gekommen als Hoherpriester der zukünftigen Güter, in Verbindung mit der größeren und vollkommneren Hütte, die nicht mit Händen gemacht (das heißt nicht von dieser Schöpfung ist),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'auch nicht mit Blut von Böcken und Kälbern, sondern mit seinem eigenen Blute, ist ein für allemal in das Heiligtum eingegangen, als er eine ewige Erlösung erfunden hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Denn wenn das Blut von Böcken und Stieren und die Asche einer jungen Kuh, auf die Unreinen gesprengt, zur Reinigkeit des Fleisches heiligt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'wieviel mehr wird das Blut des Christus, der durch den ewigen Geist sich selbst ohne Flecken Gott geopfert hat, euer Gewissen reinigen von toten Werken, um den lebendigen Gott zu dienen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Und darum ist er Mittler eines neuen Bundes, damit, da der Tod stattgefunden hat zur Erlösung von den Übertretungen unter dem ersten Bunde, die Berufenen die Verheißung des ewigen Erbes empfingen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, '(denn wo ein Testament ist, da muß notwendig der Tod dessen eintreten, der das Testament gemacht hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Denn ein Testament ist gültig, wenn der Tod eingetreten ist, weil es niemals Kraft hat, solange der lebt, der das Testament gemacht hat;)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'daher ist auch der erste Bund nicht ohne Blut eingeweiht worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Denn als jedes Gebot nach dem Gesetz von Moses zu dem ganzen Volke geredet war, nahm er das Blut der Kälber und Böcke mit Wasser und Purpurwolle und Ysop und besprengte sowohl das Buch selbst als auch das ganze Volk, und sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, '\"Dies ist das Blut des Bundes, den Gott für euch geboten hat\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Und auch die Hütte und alle Gefäße des Dienstes besprengte er gleicherweise mit dem Blute;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'und fast alle Dinge werden mit Blut gereinigt nach dem Gesetz, und ohne Blutvergießung gibt es keine Vergebung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Es war nun nötig, daß die Abbilder der Dinge in den Himmeln hierdurch gereinigt wurden, die himmlischen Dinge selbst aber durch bessere Schlachtopfer als diese.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Denn der Christus ist nicht eingegangen in das mit Händen gemachte Heiligtum, ein Gegenbild des wahrhaftigen, sondern in den Himmel selbst, um jetzt vor dem Angesicht Gottes für uns zu erscheinen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'auch nicht, auf daß er sich selbst oftmals opferte, wie der Hohepriester alljährlich in das Heiligtum hineingeht mit fremdem Blut;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'sonst hätte er oftmals leiden müssen von Grundlegung der Welt an; jetzt aber ist er einmal in der Vollendung der Zeitalter geoffenbart worden zur Abschaffung der Sünde durch sein Opfer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Und ebenso wie es den Menschen gesetzt ist, einmal zu sterben, danach aber das Gericht, also wird auch der Christus,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'nachdem er einmal geopfert worden ist, um vieler Sünden zu tragen, zum zweiten Male denen, die ihn erwarten, ohne Sünde erscheinen zur Seligkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Denn da das Gesetz einen Schatten der zukünftigen Güter, nicht der Dinge Ebenbild selbst hat, so kann es nimmer mit denselben Schlachtopfern, welche sie alljährlich ununterbrochen darbringen, die Hinzunahenden vollkommen machen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Denn würde sonst nicht ihre Darbringung aufgehört haben, weil die den Gottesdienst Übenden, einmal gereinigt, kein Gewissen mehr von Sünden gehabt hätten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Aber in jenen Opfern ist alljährlich ein Erinnern an die Sünden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'denn unmöglich kann Blut von Stieren und Böcken Sünden hinwegnehmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Darum, als er in die Welt kommt, spricht er: \"Schlachtopfer und Speisopfer hast du nicht gewollt, einen Leib aber hast du mir bereitet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'an Brandopfern und Opfern für die Sünde hast du kein Wohlgefallen gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Da sprach ich: Siehe, ich komme (in der Rolle des Buches steht von mir geschrieben), um deinen Willen, o Gott zu tun.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Indem er vorher sagt: \"Schlachtopfer und Speisopfer und Brandopfer und Opfer für die Sünde hast du nicht gewollt, noch Wohlgefallen daran gefunden\" (die nach dem Gesetz dargebracht werden), sprach er dann:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, '\"Siehe, ich komme, um deinen Willen zu tun\". (Er nimmt das Erste weg, auf daß er das Zweite aufrichte.)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Durch welchen Willen wir geheiligt sind durch das ein für allemal geschehene Opfer des Leibes Jesu Christi. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Und jeder Priester steht täglich da, den Dienst verrichtend und oft dieselben Schlachtopfer darbringend, welche niemals Sünden hinwegnehmen können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Er aber, nachdem er ein Schlachtopfer für Sünden dargebracht, hat sich auf immerdar gesetzt zur Rechten Gottes, fortan wartend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'bis seine Feinde gelegt sind zum Schemel seiner Füße.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Denn mit einem Opfer hat er auf immerdar vollkommen gemacht, die geheiligt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Das bezeugt uns aber auch der Heilige Geist: denn nachdem er gesagt hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '\"Dies ist der Bund, den ich ihnen errichten werde nach jenen Tagen, spricht der Herr: Indem ich meine Gesetze in ihre Herzen gebe, werde ich sie auch auf ihre Sinne schreiben\"; und:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, '\"Ihrer Sünden und ihrer Gesetzlosigkeiten werde ich nie mehr gedenken\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Wo aber eine Vergebung derselben ist, da ist nicht mehr ein Opfer für die Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Da wir nun, Brüder, Freimütigkeit haben zum Eintritt in das Heiligtum durch das Blut Jesu,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'auf dem neuen und lebendigen Wege, welchen er uns eingeweiht hat durch den Vorhang hin, das ist sein Fleisch,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'und einen großen Priester über das Haus Gottes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'so laßt uns hinzutreten mit wahrhaftigem Herzen, in voller Gewißheit des Glaubens, die Herzen besprengt und also gereinigt vom bösen Gewissen, und den Leib gewaschen mit reinem Wasser.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Laßt uns das Bekenntnis der Hoffnung unbeweglich festhalten, (denn treu ist er, der die Verheißung gegeben hat);');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'und laßt uns aufeinander achthaben zur Anreizung zur Liebe und zu guten Werken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'indem wir unser Zusammenkommen nicht versäumen, wie es bei etlichen Sitte ist, sondern einander ermuntern, und das um so mehr, je mehr ihr den Tag herannahen sehet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Denn wenn wir mit Willen sündigen, nachdem wir die Erkenntnis der Wahrheit empfangen haben, so bleibt kein Schlachtopfer für Sünden mehr übrig,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'sondern ein gewisses furchtvolles Erwarten des Gerichts und der Eifer eines Feuers, das die Widersacher verschlingen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Jemand, der das Gesetz Moses\' verworfen hat, stirbt ohne Barmherzigkeit auf die Aussage von zwei oder drei Zeugen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'wieviel ärgerer Strafe, meinet ihr, wird der wertgeachtet werden, der den Sohn Gottes mit Füßen getreten und das Blut des Bundes, durch welches er geheiligt worden ist, für gemein geachtet und den Geist der Gnade geschmäht hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Denn wir kennen den, der gesagt hat: \"Mein ist die Rache, ich will vergelten, spricht der Herr\". Und wiederum: \"Der Herr wird sein Volk richten\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Es ist furchtbar, in die Hände des lebendigen Gottes zu fallen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Gedenket aber der vorigen Tage, in welchen ihr, nachdem ihr erleuchtet worden, viel Kampf der Leiden erduldet habt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'indem ihr einerseits sowohl durch Schmähungen als Drangsale zur Schau gestellt wurdet, und anderseits Genossen derer wurdet, welche also einhergingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Denn ihr habt sowohl den Gefangenen Teilnahme bewiesen, als auch den Raub eurer Güter mit Freuden aufgenommen, da ihr wisset, daß ihr für euch selbst eine bessere und bleibende Habe besitzet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Werfet nun eure Zuversicht nicht weg, die eine große Belohnung hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Denn ihr bedürfet des Ausharrens, auf daß ihr, nachdem ihr den Willen Gottes getan habt, die Verheißung davontraget.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Denn noch über ein gar Kleines, und der Kommende wird kommen und nicht verziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, '\"Der Gerechte aber wird aus Glauben leben\"; und: \"Wenn jemand sich zurückzieht, so wird meine Seele kein Wohlgefallen an ihm haben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Wir aber sind nicht von denen, die sich zurückziehen zum Verderben, sondern von denen, die da glauben zur Errettung der Seele.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Der Glaube aber ist eine Verwirklichung dessen, was man hofft, eine Überzeugung von Dingen, die man nicht sieht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Denn in diesem haben die Alten Zeugnis erlangt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Durch Glauben verstehen wir, daß die Welten durch Gottes Wort bereitet worden sind, so daß das, was man sieht, nicht aus Erscheinendem geworden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Durch Glauben brachte Abel Gott ein vorzüglicheres Opfer dar als Kain, durch welches er Zeugnis erlangte, daß er gerecht war, indem Gott Zeugnis gab zu seinen Gaben; und durch diesen, obgleich er gestorben ist, redet er noch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Durch Glauben ward Henoch entrückt, damit er den Tod nicht sehen sollte, und er wurde nicht gefunden, weil Gott ihn entrückt hatte; denn vor der Entrückung hat er das Zeugnis gehabt, daß er Gott wohlgefallen habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Ohne Glauben aber ist es unmöglich, ihm wohlzugefallen; denn wer Gott naht, muß glauben, daß er ist, und denen, die ihn suchen, ein Belohner ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Durch Glauben bereitete Noah, als er einen göttlichen Ausspruch über das, was noch nicht zu sehen war, empfangen hatte, von Furcht bewegt, eine Arche zur Rettung seines Hauses, durch welche er die Welt verurteilte und Erbe der Gerechtigkeit wurde, die nach dem Glauben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Durch Glauben war Abraham, als er gerufen wurde, gehorsam, auszuziehen an den Ort, den er zum Erbteil empfangen sollte; und er zog aus, ohne zu wissen, wohin er komme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Durch Glauben hielt er sich auf in dem Lande der Verheißung, wie in einem fremden, und wohnte in Zelten mit Isaak und Jakob, den Miterben derselben Verheißung;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'denn er erwartete die Stadt, welche Grundlagen hat, deren Baumeister und Schöpfer Gott ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Durch Glauben empfing auch selbst Sara Kraft, einen Samen zu gründen, und zwar über die geeignete Zeit des Alters hinaus, weil sie den für treu achtete, der die Verheißung gegeben hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Deshalb sind auch von einem, und zwar Gestorbenen, geboren worden gleichwie die Sterne des Himmels an Menge, und wie der Sand am Ufer des Meeres, der unzählig ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Diese alle sind im Glauben gestorben und haben die Verheißungen nicht empfangen, sondern sahen sie von ferne und begrüßten sie und bekannten, daß sie Fremdlinge und ohne Bürgerschaft auf der Erde seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Denn die solches sagen, zeigen deutlich, daß sie ein Vaterland suchen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Und wenn sie an jenes gedacht hätten, von welchem sie ausgegangen waren, so hätten sie Zeit gehabt zurückzukehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Jetzt aber trachten sie nach einem besseren, das ist himmlischen. Darum schämt sich Gott ihrer nicht, ihr Gott genannt zu werden, denn er hat ihnen eine Stadt bereitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Durch Glauben hat Abraham, als er versucht wurde, den Isaak geopfert, und der, welcher die Verheißungen empfangen hatte, brachte den Eingeborenen dar,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'über welchen gesagt worden war: \"In Isaak soll dein Same genannt werden\";');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'indem er urteilte, daß Gott auch aus den Toten zu erwecken vermöge, von woher er ihn auch im Gleichnis empfing.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Durch Glauben segnete Isaak, in Bezug auf zukünftige Dinge, den Jakob und den Esau.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Durch Glauben segnete Jakob sterbend einen jeden der Söhne Josephs und betete an über der Spitze seines Stabes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Durch Glauben gedachte Joseph sterbend des Auszugs der Söhne Israels und gab Befehl wegen seiner Gebeine.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Durch Glauben wurde Moses, als er geboren wurde, drei Monate von seinen Eltern verborgen, weil sie sahen, daß das Kindlein schön war; und sie fürchteten das Gebot des Königs nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Durch Glauben weigerte sich Moses, als er groß geworden war, ein Sohn der Tochter Pharaos zu heißen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'und wählte lieber, mit dem Volke Gottes Ungemach zu leiden, als die zeitliche Ergötzung der Sünde zu haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'indem er die Schmach des Christus für größeren Reichtum hielt als die Schätze Ägyptens; denn er schaute auf die Belohnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Durch Glauben verließ er Ägypten und fürchtete die Wut des Königs nicht; denn er hielt standhaft aus, als sähe er den Unsichtbaren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Durch Glauben hat er das Passah gefeiert und die Besprengung des Blutes, auf daß der Zerstörer der Erstgeburt sie nicht antaste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Durch Glauben gingen sie durch das Rote Meer wie durch trockenes Land, welches die Ägypter versuchten und verschlungen wurden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Durch Glauben fielen die Mauern Jerichos, nachdem sie sieben Tage umzogen waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Durch Glauben kam Rahab, die Hure, nicht mit den Ungläubigen um, da sie die Kundschafter in Frieden aufgenommen hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Und was soll ich noch sagen? Denn die Zeit würde mir fehlen, wenn ich erzählen wollte von Gideon und Barak und Simson und Jephta, und David');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'und Samuel und den Propheten, welche durch Glauben Königreiche bezwangen, Gerechtigkeit wirkten, Verheißungen erlangten, der Löwen Rachen verstopften,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'des Feuers Kraft auslöschten, des Schwertes Schärfe entgingen, aus der Schwachheit Kraft gewannen, im Kampfe stark wurden, der Fremden Heerscharen zurücktrieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Weiber erhielten ihre Toten wieder durch Auferstehung; andere aber wurden gefoltert, da sie die Befreiung nicht annahmen, auf daß sie eine bessere Auferstehung erlangten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Andere aber wurden durch Verhöhnung und Geißelung versucht und dazu durch Bande und Gefängnis.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Sie wurden gesteinigt, zersägt, versucht, starben durch den Tod des Schwertes, gingen umher in Schafpelzen, in Ziegenfellen, hatten Mangel, Drangsal, Ungemach,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '(deren die Welt nicht wert war) irrten umher in Wüsten und Gebirgen und Klüften und den Höhlen der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Und diese alle, die durch den Glauben ein Zeugnis erlangten, haben die Verheißung nicht empfangen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'da Gott für uns etwas Besseres vorgesehen hat, auf daß sie nicht ohne uns vollkommen gemacht würden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Deshalb nun, da wir eine so große Wolke von Zeugen um uns haben, laßt auch uns, indem wir jede Bürde und die leicht umstrickende Sünde ablegen, mit Ausharren laufen den vor uns liegenden Wettlauf,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'hinschauend auf Jesum, den Anfänger und Vollender des Glaubens, welcher, der Schande nicht achtend, für die vor ihm liegende Freude das Kreuz erduldete und sich gesetzt hat zur Rechten des Thrones Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Denn betrachtet den, der so großen Widerspruch von den Sündern gegen sich erduldet hat, auf daß ihr nicht ermüdet, indem ihr in euren Seelen ermattet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Ihr habt noch nicht, wider die Sünde ankämpfend, bis aufs Blut widerstanden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'und habt der Ermahnung vergessen, die zu euch als zu Söhnen spricht: \"Mein Sohn! Achte nicht gering des Herrn Züchtigung, noch ermatte, wenn du von ihm gestraft wirst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'denn wen der Herr liebt, den züchtigt er; er geißelt aber jeden Sohn, den er aufnimmt\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Was ihr erduldet, ist zur Züchtigung: Gott handelt mit euch als mit Söhnen; denn wer ist ein Sohn, den der Vater nicht züchtigt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Wenn ihr aber ohne Züchtigung seid, welcher alle teilhaftig geworden sind, so seid ihr denn Bastarde und nicht Söhne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Zudem hatten wir auch unsere Väter nach dem Fleische zu Züchtigern und scheuten sie; sollen wir nicht viel mehr dem Vater der Geister unterwürfig sein und leben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Denn jene freilich züchtigten uns für wenige Tage nach ihrem Gutdünken, er aber zum Nutzen, damit wir seiner Heiligkeit teilhaftig werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Alle Züchtigung aber scheint für die Gegenwart nicht ein Gegenstand der Freude, sondern der Traurigkeit zu sein; hernach aber gibt sie die friedsame Frucht der Gerechtigkeit denen, die durch sie geübt sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Darum \"richtet auf die erschlafften Hände und die gelähmten Knie\",');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'und \"machet gerade Bahn für eure Füße!\", auf daß nicht das Lahme vom Wege abgewandt, sondern vielmehr geheilt werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Jaget dem Frieden nach mit allen und der Heiligkeit, ohne welche niemand den Herrn schauen wird;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'indem ihr darauf achtet, daß nicht jemand an der Gnade Gottes Mangel leide, daß nicht irgend eine Wurzel der Bitterkeit aufsprosse und euch beunruhige, und viele durch diese verunreinigt werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'daß nicht jemand ein Hurer sei oder ein Ungöttlicher wie Esau, der für eine Speise sein Erstgeburtsrecht verkaufte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'denn ihr wisset, daß er auch nachher, als er den Segen ererben wollte, verworfen wurde (denn er fand keinen Raum für die Buße), obgleich er ihn mit Tränen eifrig suchte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Denn ihr seid nicht gekommen zu dem Berge, der betastet werden konnte, und zu dem entzündeten Feuer, und dem Dunkel und der Finsternis und dem Sturm,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'und dem Posaunenschall, und der Stimme der Worte, deren Hörer baten, daß das Wort nicht mehr an sie gerichtet würde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, '(denn sie konnten nicht ertragen, was geboten wurde: \"Und wenn ein Tier den Berg berührt, soll es gesteinigt werden.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Und so furchtbar war die Erscheinung, daß Moses sagte: \"Ich bin voll Furcht und Zittern\"),');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'sondern ihr seid gekommen zum Berge Zion und zur Stadt des lebendigen Gottes, dem himmlischen Jerusalem; und zu Myriaden von Engeln,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'der allgemeinen Versammlung; und zu der Versammlung der Erstgeborenen, die in den Himmeln angeschrieben sind; und zu Gott, dem Richter aller; und zu den Geistern der vollendeten Gerechten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'und zu Jesu, dem Mittler eines neuen Bundes; und zu dem Blute der Besprengung, das besser redet als Abel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Sehet zu, daß ihr den nicht abweiset, der da redet! Denn wenn jene nicht entgingen, die den abwiesen, der auf Erden die göttlichen Aussprüche gab: wieviel mehr wir nicht, wenn wir uns von dem abwenden, der von den Himmeln her redet!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Dessen Stimme damals die Erde erschütterte; jetzt aber hat er verheißen und gesagt: \"Noch einmal werde ich nicht allein die Erde bewegen, sondern auch den Himmel.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Aber das \"noch einmal\" deutet die Verwandlung der Dinge an, die erschüttert werden als solche, die gemacht sind, auf daß die, welche nicht erschüttert werden, bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Deshalb, da wir ein unerschütterliches Reich empfangen, laßt uns Gnade haben, durch welche wir Gott wohlgefällig dienen mögen mit Frömmigkeit und Furcht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, '\"Denn auch unser Gott ist ein verzehrendes Feuer.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Die Bruderliebe bleibe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Der Gastfreundschaft vergesset nicht, denn durch dieselbe haben etliche ohne ihr Wissen Engel beherbergt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Gedenket der Gefangenen, als Mitgefangene; derer, die Ungemach leiden, als solche, die auch selbst im Leibe sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Die Ehe sei geehrt in allem, und das Bett unbefleckt; Hurer aber und Ehebrecher wird Gott richten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Der Wandel sei ohne Geldliebe; begnüget euch mit dem, was vorhanden ist, denn er hat gesagt: \"Ich will dich nicht versäumen, noch dich verlassen\";');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'so daß wir kühn sagen mögen: \"Der Herr ist mein Helfer, und ich will mich nicht fürchten; was wird mir ein Mensch tun?\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Gedenket eurer Führer, die das Wort Gottes zu euch geredet haben, und, den Ausgang ihres Wandels anschauend, ahmet ihren Glauben nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jesus Christus ist derselbe gestern und heute und in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Laßt euch nicht fortreißen durch mancherlei und fremde Lehren; denn es ist gut, daß das Herz durch Gnade befestigt werde, nicht durch Speisen, von welchen keinen Nutzen hatten, die darin wandelten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Wir haben einen Altar, von welchem kein Recht haben zu essen, die der Hütte dienen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Denn von den Tieren, deren Blut für die Sünde in das Heiligtum hineingetragen wird durch den Hohenpriester, werden die Leiber außerhalb des Lagers verbrannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Darum hat auch Jesus, auf daß er durch sein eigenes Blut das Volk heiligte, außerhalb des Tores gelitten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Deshalb laßt uns zu ihm hinausgehen, außerhalb des Lagers, seine Schmach tragend.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Denn wir haben hier keine bleibende Stadt, sondern die zukünftige suchen wir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Durch ihn nun laßt uns Gott stets ein Opfer des Lobes darbringen, das ist die Frucht der Lippen, die seinen Namen bekennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Des Wohltuns aber und Mitteilens vergesset nicht, denn an solchen Opfern hat Gott Wohlgefallen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Gehorchet euren Führern und seid unterwürfig; denn sie wachen über eure Seelen (als die da Rechenschaft geben sollen), auf daß sie dies mit Freuden tun und nicht mit Seufzen; denn dies wäre euch nicht nützlich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Betet für uns; denn wir halten dafür, daß wir ein gutes Gewissen haben, da wir in allem ehrbar zu wandeln begehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Ich bitte euch aber um so mehr, dies zu tun, auf daß ich euch desto schneller wiedergegeben werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Der Gott des Friedens aber, der aus den Toten wiederbrachte unseren Herrn Jesus, den großen Hirten der Schafe, in dem Blute des ewigen Bundes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'vollende euch in jedem guten Werke, um seinen Willen zu tun, in euch schaffend, was vor ihm wohlgefällig ist, durch Jesum Christum, welchem die Herrlichkeit sei von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Ich bitte euch aber, Brüder, ertraget das Wort der Ermahnung; denn ich habe euch auch mit kurzen Worten geschrieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Wisset, daß unser Bruder Timotheus freigelassen ist, mit welchem, wenn er bald kommt, ich euch sehen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Grüßet alle eure Führer und alle Heiligen. Es grüßen euch die von Italien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Die Gnade sei mit euch allen! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakobus, Knecht Gottes und des Herrn Jesus Christus, den zwölf Stämmen, die in der Zerstreuung sind, seinen Gruß!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Achtet es für lauter Freude, meine Brüder, wenn ihr in mancherlei Versuchungen fallet,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'da ihr wisset, daß die Bewährung eures Glaubens Ausharren bewirkt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Das Ausharren aber habe ein vollkommenes Werk, auf daß ihr vollkommen und vollendet seid und in nichts Mangel habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Wenn aber jemand von euch Weisheit mangelt, so bitte er von Gott, der allen willig gibt und nichts vorwirft, und sie wird ihm gegeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Er bitte aber im Glauben, ohne irgend zu zweifeln; denn der Zweifelnde ist gleich einer Meereswoge, die vom Winde bewegt und hin und her getrieben wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Denn jener Mensch denke nicht, daß er etwas von dem Herrn empfangen werde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'er ist ein wankelmütiger Mann, unstet in allen seinen Wegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Der niedrige Bruder aber rühme sich seiner Hoheit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'der reiche aber seiner Erniedrigung; denn wie des Grases Blume wird er vergehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Denn die Sonne ist aufgegangen mit ihrer Glut und hat das Gras gedörrt, und seine Blume ist abgefallen, und die Zierde seines Ansehens ist verdorben; also wird auch der Reiche in seinen Wegen verwelken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Glückselig der Mann, der die Versuchung erduldet! Denn nachdem er bewährt ist, wird er die Krone des Lebens empfangen, welche er denen verheißen hat, die ihn lieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Niemand sage, wenn er versucht wird: Ich werde von Gott versucht; denn Gott kann nicht versucht werden vom Bösen, und selbst versucht er niemand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Ein jeder aber wird versucht, wenn er von seiner eigenen Lust fortgezogen und gelockt wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Danach, wenn die Lust empfangen hat, gebiert sie die Sünde; die Sünde aber, wenn sie vollendet ist, gebiert den Tod.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Irret euch nicht, meine geliebten Brüder!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Jede gute Gabe und jedes vollkommene Geschenk kommt von oben herab, von dem Vater der Lichter, bei welchem keine Veränderung ist, noch eines Wechsels Schatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Nach seinem eigenen Willen hat er uns durch das Wort der Wahrheit gezeugt, auf daß wir eine gewisse Erstlingsfrucht seiner Geschöpfe seien.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Daher, meine geliebten Brüder, sei jeder Mensch schnell zum Hören, langsam zum Reden, langsam zum Zorn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Denn eines Mannes Zorn wirkt nicht Gottes Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Deshalb leget ab alle Unsauberkeit und alles Überfließen von Schlechtigkeit, und empfanget mit Sanftmut das eingepflanzte Wort, das eure Seelen zu erretten vermag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Seid aber Täter des Wortes und nicht allein Hörer, die sich selbst betrügen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Denn wenn jemand ein Hörer des Wortes ist und nicht ein Täter, der ist einem Manne gleich, welcher sein natürliches Angesicht in einem Spiegel betrachtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Denn er hat sich selbst betrachtet und ist weggegangen, und er hat alsbald vergessen, wie er beschaffen war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Wer aber in das vollkommene Gesetz, das der Freiheit, nahe hineingeschaut hat und darin bleibt, indem er nicht ein vergeßlicher Hörer, sondern ein Täter des Werkes ist, dieser wird glückselig sein in seinem Tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Wenn jemand sich dünkt, er diene Gott, und zügelt nicht seine Zunge, sondern betrügt sein Herz, dessen Gottesdienst ist eitel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Ein reiner und unbefleckter Gottesdienst vor Gott und dem Vater ist dieser: Waisen und Witwen in ihrer Drangsal besuchen, sich selbst von der Welt unbefleckt erhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Meine Brüder, habet den Glauben unseres Herrn Jesus Christus, des Herrn der Herrlichkeit, nicht mit Ansehen der Person.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Denn wenn in eure Synagoge ein Mann kommt mit goldenem Ringe, in prächtigem Kleide, es kommt aber auch ein Armer in unsauberem Kleide herein,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'und ihr sehet auf den, der das prächtige Kleid trägt, und sprechet: Setze du dich bequem hierher, und zu dem Armen sprechet ihr: Stehe du dort, oder setze dich hier unter meinen Fußschemel-');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'habt ihr nicht unter euch selbst einen Unterschied gemacht und seid Richter mit bösen Gedanken geworden?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Höret, meine geliebten Brüder: Hat nicht Gott die weltlich Armen auserwählt, reich zu sein im Glauben, und zu Erben des Reiches, welches er denen verheißen hat, die ihn lieben?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Ihr aber habt den Armen verachtet. Unterdrücken euch nicht die Reichen, und ziehen nicht sie euch vor die Gerichte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Lästern nicht sie den guten Namen, der über euch angerufen worden ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Wenn ihr wirklich das königliche Gesetz erfüllet nach der Schrift: \"Du sollst deinen Nächsten lieben wie dich selbst\", so tut ihr wohl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Wenn ihr aber die Person ansehet, so begehet ihr Sünde, indem ihr von dem Gesetz als Übertreter überführt werdet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Denn wer irgend das ganze Gesetz halten, aber in einem straucheln wird, ist aller Gebote schuldig geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Denn der da sprach: \"Du sollst nicht ehebrechen\", sprach auch: \"Du sollst nicht töten\". Wenn du nun nicht ehebrichst, aber tötest, so bist du ein Gesetzesübertreter geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Also redet und also tut, als die durchs Gesetz der Freiheit gerichtet werden sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Denn das Gericht wird ohne Barmherzigkeit sein gegen den, der nicht Barmherzigkeit geübt hat. Die Barmherzigkeit rühmt sich wider das Gericht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Was nützt es, meine Brüder, wenn jemand sagt, er habe Glauben, hat aber nicht Werke? Kann etwa der Glaube ihn erretten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Wenn aber ein Bruder oder eine Schwester nackt ist und der täglichen Nahrung entbehrt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'und jemand unter euch spricht zu ihnen: Gehet hin in Frieden, wärmet euch und sättiget euch! ihr gebet ihnen aber nicht die Notdurft des Leibes, was nützt es?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Also ist auch der Glaube, wenn er nicht Werke hat, an sich selbst tot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Es wird aber jemand sagen: Du hast Glauben, und ich habe Werke; zeige mir deinen Glauben ohne Werke, und ich werde dir meinen Glauben aus meinen Werken zeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Du glaubst, daß Gott einer ist, du tust wohl; auch die Dämonen glauben und zittern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Willst du aber wissen, o eitler Mensch, daß der Glaube ohne die Werke tot ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Ist nicht Abraham, unser Vater, aus Werken gerechtfertigt worden, da er Isaak, seinen Sohn, auf dem Altar opferte?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Du siehst, daß der Glaube zu seinen Werken mitwirkte, und daß der Glaube durch die Werke vollendet wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'Und die Schrift ward erfüllt, welche sagt: \"Abraham aber glaubte Gott, und es wurde ihm zur Gerechtigkeit gerechnet\", und er wurde Freund Gottes genannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Ihr sehet also, daß ein Mensch aus Werken gerechtfertigt wird und nicht aus Glauben allein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Ist aber gleicherweise nicht auch Rahab, die Hure, aus Werken gerechtfertigt worden, da sie die Boten aufnahm und auf einem anderen Wege hinausließ?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Denn wie der Leib ohne Geist tot ist, also ist auch der Glaube ohne die Werke tot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Seid nicht viele Lehrer, meine Brüder, da ihr wisset, daß wir ein schwereres Urteil empfangen werden; denn wir alle straucheln oft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Wenn jemand nicht im Worte strauchelt, der ist ein vollkommener Mann, fähig, auch den ganzen Leib zu zügeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Siehe, den Pferden legen wir die Gebisse in die Mäuler, damit sie uns gehorchen, und lenken ihren ganzen Leib.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Siehe, auch die Schiffe, die so groß sind, und von heftigen Winden getrieben werden, werden durch ein sehr kleines Steuerruder gelenkt, wohin irgend der Trieb des Steuermanns will.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'So ist auch die Zunge ein kleines Glied und rühmt sich großer Dinge. Siehe, ein kleines Feuer, welch einen großen Wald zündet es an!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Und die Zunge ist ein Feuer, die Welt der Ungerechtigkeit. Die Zunge ist unter unseren Gliedern gesetzt, als die den ganzen Leib befleckt und den Lauf der Natur anzündet und von der Hölle angezündet wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Denn jede Natur, sowohl der Tiere als der Vögel, sowohl der kriechenden als der Meertiere, wird gebändigt und ist gebändigt worden durch die menschliche Natur;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'die Zunge aber kann keiner der Menschen bändigen: sie ist ein unstetes Übel, voll tödlichen Giftes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Mit ihr preisen wir den Herrn und Vater, und mit ihr fluchen wir den Menschen, die nach dem Bilde Gottes geworden sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Aus demselben Munde geht Segen und Fluch hervor. Dies, meine Brüder, sollte nicht also sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Die Quelle sprudelt doch nicht aus derselben Öffnung das Süße und das Bittere?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Kann etwa, meine Brüder, ein Feigenbaum Oliven hervorbringen, oder ein Weinstock Feigen? Auch kann Salziges nicht süßes Wasser hervorbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Wer ist weise und verständig unter euch? Er zeige aus dem guten Wandel seine Werke in Sanftmut der Weisheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Wenn ihr aber bitteren Neid und Streitsucht in eurem Herzen habt, so rühmet euch nicht und lüget nicht wider die Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Dies ist nicht die Weisheit, die von oben herabkommt, sondern eine irdische, sinnliche, teuflische.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Denn wo Neid und Streitsucht ist, da ist Zerrüttung und jede schlechte Tat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Die Weisheit aber von oben ist aufs erste rein, sodann friedsam, gelinde, folgsam, voll Barmherzigkeit und guter Früchte, unparteiisch, ungeheuchelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Die Frucht der Gerechtigkeit in Frieden aber wird denen gesät, die Frieden stiften.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Woher kommen Kriege und woher Streitigkeiten unter euch? Nicht daher, aus euren Lüsten, die in euren Gliedern streiten?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Ihr gelüstet und habt nichts; ihr tötet und neidet und könnet nichts erlangen; ihr streitet und krieget; ihr habt nichts, weil ihr nicht bittet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'ihr bittet und empfanget nichts, weil ihr übel bittet, auf daß ihr es in euren Lüsten vergeudet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Ihr Ehebrecherinnen, wisset ihr nicht, daß die Freundschaft der Welt Feindschaft wider Gott ist? Wer nun irgend ein Freund der Welt sein will, stellt sich als Feind Gottes dar.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Oder meinet ihr, daß die Schrift vergeblich rede? Begehrt der Geist, der in uns wohnt, mit Neid?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Er gibt aber größere Gnade; deshalb spricht er: \"Gott widersteht den Hochmütigen, den Demütigen aber gibt er Gnade\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Unterwerfet euch nun Gott. Widerstehet dem Teufel, und er wird von euch fliehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Nahet euch Gott, und er wird sich euch nahen. Säubert die Hände, ihr Sünder, und reiniget die Herzen, ihr Wankelmütigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Seid niedergebeugt, und trauert und weinet; euer Lachen verwandle sich in Traurigkeit und eure Freude in Niedergeschlagenheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Demütiget euch vor dem Herrn, und er wird euch erhöhen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Redet nicht widereinander, Brüder. Wer wider seinen Bruder redet oder seinen Bruder richtet, redet wider das Gesetz und richtet das Gesetz. Wenn du aber das Gesetz richtest, so bist du nicht ein Täter des Gesetzes, sondern ein Richter.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Einer ist der Gesetzgeber und Richter, der zu erretten und zu verderben vermag. Du aber, wer bist du, der du den Nächsten richtest?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Wohlan denn, die ihr saget: Heute oder morgen wollen wir in die und die Stadt gehen und daselbst ein Jahr zubringen und Handel treiben und Gewinn machen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, '(die ihr nicht wisset, was der morgende Tag bringen wird; denn was ist euer Leben? Ein Dampf ist es ja, der eine kleine Zeit sichtbar ist und dann verschwindet;)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'statt daß ihr saget: Wenn der Herr will und wir leben, so werden wir auch dieses oder jenes tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Nun aber rühmet ihr euch in euren Großtuereien. Alles solches Rühmen ist böse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Wer nun weiß, Gutes zu tun, und tut es nicht, dem ist es Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Wohlan nun, ihr Reichen, weinet und heulet über euer Elend, das über euch kommt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Euer Reichtum ist verfault, und eure Kleider sind mottenfräßig geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Euer Gold und Silber ist verrostet, und ihr Rost wird zum Zeugnis sein wider euch und euer Fleisch fressen wie Feuer; ihr habt Schätze gesammelt in den letzten Tagen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Siehe, der Lohn der Arbeiter, die eure Felder geschnitten haben, der von euch vorenthalten ist, schreit, und das Geschrei der Schnitter ist vor die Ohren des Herrn Zebaoth gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Ihr habt in Üppigkeit gelebt auf der Erde und geschwelgt; ihr habt eure Herzen gepflegt wie an einem Schlachttage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Ihr habt verurteilt, ihr habt getötet den Gerechten; er widersteht euch nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Habt nun Geduld, Brüder, bis zur Ankunft des Herrn. Siehe, der Ackersmann wartet auf die köstliche Frucht der Erde und hat Geduld ihretwegen, bis sie den Früh-und Spätregen empfange.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Habt auch ihr Geduld, befestiget eure Herzen, denn die Ankunft des Herrn ist nahe gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Seufzet nicht widereinander, Brüder, auf daß ihr nicht gerichtet werdet. Siehe, der Richter steht vor der Tür.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Nehmet, Brüder, zum Vorbild des Leidens und der Geduld die Propheten, die im Namen des Herrn geredet haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Siehe, wir preisen die glückselig, welche ausgeharrt haben. Von dem Ausharren Hiobs habt ihr gehört, und das Ende des Herrn habt ihr gesehen, daß der Herr voll innigen Mitgefühls und barmherzig ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Vor allem aber, meine Brüder, schwöret nicht, weder bei dem Himmel, noch bei der Erde, noch mit irgend einem anderen Eide; es sei aber euer Ja ja, und euer Nein nein, auf daß ihr nicht unter Gericht fallet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Leidet jemand unter euch Trübsal? Er bete. Ist jemand gutes Mutes? Er singe Psalmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Ist jemand krank unter euch? Er rufe die Ältesten der Versammlung zu sich, und sie mögen über ihn beten und ihn mit Öl salben im Namen des Herrn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Und das Gebet des Glaubens wird den Kranken heilen, und der Herr wird ihn aufrichten, und wenn er Sünden begangen hat, wird ihm vergeben werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Bekennet denn einander die Vergehungen und betet füreinander, damit ihr geheilt werdet; das inbrünstige Gebet eines Gerechten vermag viel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elias war ein Mensch von gleichen Gemütsbewegungen wie wir; und er betete ernstlich, daß es nicht regnen möge, und es regnete nicht auf der Erde drei Jahre und sechs Monate.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Und wiederum betete er, und der Himmel gab Regen, und die Erde brachte ihre Frucht hervor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Meine Brüder, wenn jemand unter euch von der Wahrheit abirrt, und es führt ihn jemand zurück,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'so wisse er, daß der, welcher einen Sünder von der Verirrung seines Weges zurückführt, eine Seele vom Tode erretten und eine Menge von Sünden bedecken wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Petrus, Apostel Jesu Christi, den Fremdlingen von der Zerstreuung von Pontus, Galatien, Kappadocien, Asien und Bithynien,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'auserwählt nach Vorkenntnis Gottes, des Vaters, durch Heiligung des Geistes, zum Gehorsam und zur Blutbesprengung Jesu Christi: Gnade und Friede sei euch vermehrt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Gepriesen sei der Gott und Vater unseres Herrn Jesus Christus, der nach seiner großen Barmherzigkeit uns wiedergezeugt hat zu einer lebendigen Hoffnung durch die Auferstehung Jesu Christi aus den Toten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'zu einem unverweslichen und unbefleckten und unverwelklichen Erbteil, welches in den Himmeln aufbewahrt ist für euch,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'die ihr durch Gottes Macht durch Glauben bewahrt werdet zur Errettung, die bereit ist, in der letzten Zeit geoffenbart zu werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'worin ihr frohlocket, die ihr jetzt eine kleine Zeit, wenn es nötig ist, betrübt seid durch mancherlei Versuchungen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'auf daß die Bewährung eures Glaubens, viel köstlicher als die des Goldes, das vergeht, aber durch Feuer erprobt wird, erfunden werde zu Lob und Herrlichkeit und Ehre in der Offenbarung Jesu Christi;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'welchen ihr, obgleich ihr ihn nicht gesehen habt, liebet; an welchen glaubend, obgleich ihr ihn jetzt nicht sehet, ihr mit unaussprechlicher und verherrlichter Freude frohlocket,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'indem ihr das Ende eures Glaubens, die Errettung der Seelen, davontraget;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'über welche Errettung Propheten nachsuchten und nachforschten, die von der Gnade gegen euch geweissagt haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'forschend, auf welche oder welcherlei Zeit der Geist Christi, der in ihnen war, hindeutete, als er von den Leiden, die auf Christum kommen sollten, und von den Herrlichkeiten danach zuvor zeugte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'welchen es geoffenbart wurde, daß sie nicht für sich selbst, sondern für euch die Dinge bedienten, die euch jetzt verkündigt worden sind durch die, welche euch das Evangelium gepredigt haben durch den vom Himmel gesandten Heiligen Geist, in welche Dinge Engel hineinzuschauen begehren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Deshalb umgürtet die Lenden eurer Gesinnung, seid nüchtern und hoffet völlig auf die Gnade, die euch gebracht wird bei der Offenbarung Jesu Christi;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'als Kinder des Gehorsams bildet euch nicht nach den vorigen Lüsten in eurer Unwissenheit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'sondern wie der, welcher euch berufen hat, heilig ist, seid auch ihr heilig in allem Wandel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'denn es steht geschrieben: \"Seid heilig, denn ich bin heilig\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Und wenn ihr den als Vater anrufet, der ohne Ansehen der Person richtet nach eines jeden Werk, so wandelt die Zeit eurer Fremdlingschaft in Furcht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'indem ihr wisset, daß ihr nicht mit verweslichen Dingen, mit Silber oder Gold, erlöst worden seid von eurem eitlen, von den Vätern überlieferten Wandel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'sondern mit dem kostbaren Blute Christi, als eines Lammes ohne Fehl und ohne Flecken;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'welcher zwar zuvorerkannt ist vor Grundlegung der Welt, aber geoffenbart worden am Ende der Zeiten um euretwillen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'die ihr durch ihn glaubet an Gott, der ihn aus den Toten auferweckt und ihm Herrlichkeit gegeben hat, auf daß euer Glaube und eure Hoffnung auf Gott sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Da ihr eure Seelen gereinigt habt durch den Gehorsam gegen die Wahrheit zur ungeheuchelten Bruderliebe, so liebet einander mit Inbrunst aus reinem Herzen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'die ihr nicht wiedergeboren seid aus verweslichem Samen, sondern aus unverweslichem, durch das lebendige und bleibende Wort Gottes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'denn \"alles Fleisch ist wie Gras, und alle seine Herrlichkeit wie des Grases Blume. Das Gras ist verdorrt, und seine Blume ist abgefallen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'aber das Wort des Herrn bleibt in Ewigkeit.\" Dies aber ist das Wort, welches euch verkündigt worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Leget nun ab alle Bosheit und allen Trug und Heuchelei und Neid und alles üble Nachreden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'und wie neugeborene Kindlein seid begierig nach der vernünftigen, unverfälschten Milch, auf daß ihr durch dieselbe wachset zur Errettung,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'wenn ihr anders geschmeckt habt, daß der Herr gütig ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Zu welchem kommend, als zu einem lebendigen Stein, von Menschen zwar verworfen, bei Gott aber auserwählt, kostbar,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'werdet auch ihr selbst, als lebendige Steine, aufgebaut, ein geistliches Haus, ein heiliges Priestertum, um darzubringen geistliche Schlachtopfer, Gott wohlannehmlich durch Jesum Christum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Denn es ist in der Schrift enthalten: \"Siehe, ich lege in Zion einen Eckstein, einen auserwählten, kostbaren; und wer an ihn glaubt, wird nicht zu Schanden werden.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Euch nun, die ihr glaubet, ist die Kostbarkeit; den Ungehorsamen aber: \"Der Stein, den die Bauleute verworfen haben, dieser ist zum Eckstein geworden\",');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'und \"ein Stein des Anstoßes und ein Fels des Ärgernisses\", die sich, da sie nicht gehorsam sind, an dem Worte stoßen, wozu sie auch gesetzt worden sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Ihr aber seid ein auserwähltes Geschlecht, ein königliches Priestertum, eine heilige Nation, ein Volk zum Besitztum, damit ihr die Tugenden dessen verkündigt, der euch berufen hat aus der Finsternis zu seinem wunderbaren Licht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'die ihr einst \"nicht ein Volk\" waret, jetzt aber ein Volk Gottes seid; die ihr \"nicht Barmherzigkeit empfangen hattet\", jetzt aber Barmherzigkeit empfangen habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Geliebte, ich ermahne euch als Fremdlinge und als die ihr ohne Bürgerrecht seid, daß ihr euch enthaltet von den fleischlichen Lüsten, welche wider die Seele streiten,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'indem ihr euren Wandel unter den Nationen ehrbar führet, auf daß sie, worin sie wider euch als Übeltäter reden, aus den guten Werken, die sie anschauen, Gott verherrlichen am Tage der Heimsuchung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Unterwerfet euch nun aller menschlichen Einrichtung um des Herrn willen: es sei dem Könige als Oberherrn,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'oder den Statthaltern als denen, die von ihm gesandt werden zur Bestrafung der Übeltäter, aber zum Lobe derer, die Gutes tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Denn also ist es der Wille Gottes, daß ihr durch Gutestun die Unwissenheit der unverständigen Menschen zum Schweigen bringet:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'als Freie, und die nicht die Freiheit zum Deckmantel der Bosheit haben, sondern als Knechte Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Erweiset allen Ehre; liebet die Brüderschaft; fürchtet Gott; ehret den König.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Ihr Hausknechte, seid den Herren unterwürfig in aller Furcht, nicht allein den guten und gelinden, sondern auch den verkehrten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Denn dies ist wohlgefällig, wenn jemand um des Gewissens vor Gott willen Beschwerden erträgt, indem er ungerecht leidet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Denn was für ein Ruhm ist es, wenn ihr ausharret, indem ihr sündiget und geschlagen werdet? Wenn ihr aber ausharret, indem ihr Gutes tut und leidet, das ist wohlgefällig bei Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Denn hierzu seid ihr berufen worden; denn auch Christus hat für euch gelitten, euch ein Beispiel hinterlassend, auf daß ihr seinen Fußstapfen nachfolget;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'welcher keine Sünde tat, noch wurde Trug in seinem Munde erfunden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'der, gescholten, nicht wiederschalt, leidend, nicht drohte, sondern sich dem übergab, der recht richtet;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'welcher selbst unsere Sünden an seinem Leibe auf dem Holze getragen hat, auf daß wir, den Sünden abgestorben, der Gerechtigkeit leben, durch dessen Striemen ihr heil geworden seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Denn ihr ginget in der Irre wie Schafe, aber ihr seid jetzt zurückgekehrt zu dem Hirten und Aufseher eurer Seelen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Gleicherweise ihr Weiber, seid euren eigenen Männern unterwürfig, auf daß, wenn auch etliche dem Worte nicht gehorchen, sie durch den Wandel der Weiber ohne Wort mögen gewonnen werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'indem sie euren in Furcht keuschen Wandel angeschaut haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'deren Schmuck nicht der auswendige sei durch Flechten der Haare und Umhängen von Gold oder Anziehen von Kleidern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'sondern der verborgene Mensch des Herzens in dem unverweslichen Schmuck des sanften und stillen Geistes, welcher vor Gott sehr köstlich ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Denn also schmückten sich auch einst die heiligen Weiber, die ihre Hoffnung auf Gott setzten, indem sie ihren eigenen Männern unterwürfig waren:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'wie Sara dem Abraham gehorchte und ihn Herr nannte, deren Kinder ihr geworden seid, wenn ihr Gutes tut und keinerlei Schrecken fürchtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Ihr Männer gleicherweise, wohnet bei ihnen nach Erkenntnis, als bei einem schwächeren Gefäße, dem weiblichen, ihnen Ehre gebend, als die auch Miterben der Gnade des Lebens sind, auf daß eure Gebete nicht verhindert werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Endlich aber seid alle gleichgesinnt, mitleidig, voll brüderlicher Liebe, barmherzig, demütig,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'und vergeltet nicht Böses mit Bösem, oder Scheltwort mit Scheltwort, sondern im Gegenteil segnet, weil ihr dazu berufen worden seid, daß ihr Segen ererbet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, '\"Denn wer das Leben lieben und gute Tage sehen will, der enthalte seine Zunge vom Bösen, und seine Lippen, daß sie nicht Trug reden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'er wende sich ab vom Bösen und tue Gutes; er suche Frieden und jage ihm nach;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'denn die Augen des Herrn sind gerichtet auf die Gerechten, und seine Ohren auf ihr Flehen; das Angesicht des Herrn aber ist wider die, welche Böses tun.\"');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Und wer ist, der euch Böses tun wird, wenn ihr Nachahmer des Guten geworden seid?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Aber wenn ihr auch leiden solltet um der Gerechtigkeit willen, glückselig seid ihr! Fürchtet aber nicht ihre Furcht, noch seid bestürzt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'sondern heiliget Christus, den Herrn, in euren Herzen. Seid aber jederzeit bereit zur Verantwortung gegen jeden, der Rechenschaft von euch fordert über die Hoffnung, die in euch ist, aber mit Sanftmut und Furcht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'indem ihr ein gutes Gewissen habt, auf daß, worin sie sie wider euch als Übeltäter reden, die zu Schanden werden, welche euren guten Wandel in Christo verleumden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Denn es ist besser, wenn der Wille Gottes es will, für Gutestun zu leiden, als für Bösestun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Denn es hat ja Christus einmal für Sünden gelitten, der Gerechte für die Ungerechten, auf daß er uns zu Gott führe, getötet nach dem Fleische, aber lebendig gemacht nach dem Geiste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'in welchem er auch hinging und predigte den Geistern, die im Gefängnis sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'welche einst ungehorsam waren, als die Langmut Gottes harrte in den Tagen Noahs, während die Arche zugerichtet wurde, in welche wenige, daß ist acht Seelen, durch Wasser gerettet wurden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'welches Gegenbild auch euch jetzt errettet, das ist die Taufe (nicht ein Ablegen der Unreinigkeit des Fleisches, sondern das Begehren eines guten Gewissens vor Gott), durch die Auferstehung Jesu Christi,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'welcher, in den Himmel gegangen, zur Rechten Gottes ist, indem Engel und Gewalten und Mächte ihm unterworfen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Da nun Christus für uns im Fleische gelitten hat, so waffnet auch ihr euch mit demselben Sinne; denn wer im Fleische gelitten hat, ruht von der Sünde,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'um die im Fleische noch übrige Zeit nicht mehr den Lüsten der Menschen, sondern dem Willen Gottes zu leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Denn die vergangene Zeit ist uns genug, den Willen der Nationen vollbracht zu haben, indem wir wandelten in Ausschweifungen, Lüsten, Trunkenheit, Festgelagen, Trinkgelagen und frevelhaften Götzendienereien;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'wobei es sie befremdet, daß ihr nicht mitlaufet zu demselben Treiben der Ausschweifung, und lästern euch,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'welche dem Rechenschaft geben werden, der bereit ist, Lebendige und Tote zu richten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Denn dazu ist auch den Toten gute Botschaft verkündigt worden, auf daß sie gerichtet werden möchten dem Menschen gemäß nach dem Fleische, aber leben möchten Gott gemäß nach dem Geiste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Es ist aber nahe gekommen das Ende aller Dinge. Seid nun besonnen und seid nüchtern zum Gebet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Vor allen Dingen aber habt untereinander eine inbrünstige Liebe, denn die Liebe bedeckt eine Menge von Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Seid gastfrei gegeneinander ohne Murren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Je nachdem ein jeder eine Gnadengabe empfangen hat, dienet einander damit als gute Verwalter der mancherlei Gnade Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Wenn jemand redet, so rede er als Aussprüche Gottes; wenn jemand dient, so sei es als aus der Kraft, die Gott darreicht, auf daß in allem Gott verherrlicht werde durch Jesum Christum, welchem die Herrlichkeit ist und die Macht von Ewigkeit zu Ewigkeit. Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Geliebte, laßt euch das Feuer der Verfolgung unter euch, das euch zur Versuchung geschieht, nicht befremden, als begegne euch etwas Fremdes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'sondern insoweit ihr der Leiden des Christus teilhaftig seid, freuet euch, auf daß ihr auch in der Offenbarung seiner Herrlichkeit mit Frohlocken euch freuet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Wenn ihr im Namen Christi geschmäht werdet, glückselig seid ihr! Denn der Geist der Herrlichkeit und der Geist Gottes ruht auf euch. Bei ihnen freilich wird er verlästert, bei euch aber wird er verherrlicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Daß doch niemand von euch leide als Mörder oder Dieb oder Übeltäter, oder als einer, der sich in fremde Sachen mischt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'wenn aber als Christ, so schäme er sich nicht, sondern verherrliche Gott in diesem Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Denn die Zeit ist gekommen, daß das Gericht anfange bei dem Hause Gottes; wenn aber zuerst bei uns, was wird das Ende derer sein, die dem Evangelium Gottes nicht gehorchen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Und wenn der Gerechte mit Not errettet wird, wo will der Gottlose und Sünder erscheinen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Daher sollen auch die, welche nach dem Willen Gottes leiden, einem treuen Schöpfer ihre Seelen befehlen im Gutestun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Die Ältesten, die unter euch sind, ermahne ich, der Mitälteste und Zeuge der Leiden des Christus und auch Teilhaber der Herrlichkeit, die geoffenbart werden soll:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Hütet die Herde Gottes, die bei euch ist, indem ihr die Aufsicht nicht aus Zwang führet, sondern freiwillig, auch nicht um schändlichen Gewinn, sondern bereitwillig,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'nicht als die da herrschen über ihre Besitztümer, sondern indem ihr Vorbilder der Herde seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'Und wenn der Erzhirte offenbar geworden ist, so werdet ihr die unverwelkliche Krone der Herrlichkeit empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Gleicherweise ihr jüngeren, seid den älteren unterwürfig. Alle aber seid gegeneinander mit Demut fest umhüllt; denn \"Gott widersteht den Hochmütigen, den Demütigen aber gibt er Gnade\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'So demütiget euch nun unter die mächtige Hand Gottes, auf daß er euch erhöhe zur rechten Zeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'indem ihr alle eure Sorge auf ihn werfet; denn er ist besorgt für euch.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Seid nüchtern, wachet; euer Widersacher, der Teufel, geht umher wie ein brüllender Löwe und sucht, wen er verschlinge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Dem widerstehet standhaft im Glauben, da ihr wisset, daß dieselben Leiden sich vollziehen an eurer Brüderschaft, die in der Welt ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Der Gott aller Gnade aber, der euch berufen hat zu seiner ewigen Herrlichkeit in Christo Jesu, nachdem ihr eine kleine Zeit gelitten habt, er selbst wird euch vollkommen machen, befestigen, kräftigen, gründen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Ihm sei die Herrlichkeit und die Macht von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Durch Silvanus, den treuen Bruder, wie ich dafür halte, habe ich euch mit wenigem geschrieben, euch ermahnend und bezeugend, daß dies die wahre Gnade Gottes ist, in welcher ihr stehet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Es grüßt euch die Miterwählte in Babylon und Markus, mein Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Grüßet einander mit dem Kuß der Liebe. Friede euch allen, die ihr in Christo seid!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simon Petrus, Knecht und Apostel Jesu Christi, denen, die einen gleich kostbaren Glauben mit uns empfangen haben durch die Gerechtigkeit unseres Gottes und Heilandes Jesus Christus:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Gnade und Friede sei euch vermehrt in der Erkenntnis Gottes und Jesu, unseres Herrn!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Da seine göttliche Kraft uns alles in betreff des Lebens und der Gottseligkeit geschenkt hat durch die Erkenntnis dessen, der uns berufen hat durch Herrlichkeit und Tugend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'durch welche er uns die größten und kostbaren Verheißungen geschenkt hat, auf daß ihr durch diese Teilhaber der göttlichen Natur werdet, indem ihr dem Verderben entflohen seid, das in der Welt ist durch die Lust;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'ebendeshalb reichet aber auch dar, indem ihr allen Fleiß anwendet, in eurem Glauben die Tugend, in der Tugend aber die Erkenntnis,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'in der Erkenntnis aber die Enthaltsamkeit, in der Enthaltsamkeit aber das Ausharren, in dem Ausharren aber die Gottseligkeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'in der Gottseligkeit aber die Bruderliebe, in der Bruderliebe aber die Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Denn wenn diese Dinge bei euch sind und reichlich vorhanden, so stellen sie euch nicht träge noch fruchtleer hin bezüglich der Erkenntnis unseres Herrn Jesus Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Denn bei welchem diese Dinge nicht sind, der ist blind, kurzsichtig und hat die Reinigung seiner vorigen Sünden vergessen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Darum, Brüder, befleißiget euch um so mehr, eure Berufung und Erwählung fest zu machen; denn wenn ihr diese Dinge tut, so werdet ihr niemals straucheln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Denn also wird euch reichlich dargereicht werden der Eingang in das ewige Reich unseres Herrn und Heilandes Jesus Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Deshalb will ich Sorge tragen, euch immer an diese Dinge zu erinnern, wiewohl ihr sie wisset und in der gegenwärtigen Wahrheit befestigt seid.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Ich halte es aber für recht, solange ich in dieser Hütte bin, euch durch Erinnerung aufzuwecken,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'da ich weiß, daß das Ablegen meiner Hütte bald geschieht, wie auch unser Herr Jesus Christus mir kundgetan hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Ich will mich aber befleißigen, daß ihr auch zu jeder Zeit nach meinem Abschiede imstande seid, euch diese Dinge ins Gedächtnis zu rufen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Denn wir haben euch die Macht und Ankunft unseres Herrn Jesus Christus nicht kundgetan, indem wir künstlich erdichteten Fabeln folgten, sondern als die da Augenzeugen seiner herrlichen Größe gewesen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Denn er empfing von Gott, dem Vater, Ehre und Herrlichkeit, als von der prachtvollen Herrlichkeit eine solche Stimme an ihn erging: \"Dieser ist mein geliebter Sohn, an welchem ich Wohlgefallen gefunden habe\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Und diese Stimme hörten wir vom Himmel her erlassen, als wir mit ihm auf dem heiligen Berge waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Und so besitzen wir das prophetische Wort befestigt, auf welches zu achten ihr wohl tut, als auf eine Lampe, welche an einem dunklen Orte leuchtet, bis der Tag anbreche und der Morgenstern aufgehe in euren Herzen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'indem ihr dies zuerst wisset, daß keine Weissagung der Schrift von eigener Auslegung ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Denn die Weissagung wurde niemals durch den Willen des Menschen hervorgebracht, sondern heilige Männer Gottes redeten, getrieben vom Heiligen Geiste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Es waren aber auch falsche Propheten unter dem Volke, wie auch unter euch falsche Lehrer sein werden, welche verderbliche Sekten nebeneinführen werden und den Gebieter verleugnen, der sie erkauft hat, und sich selbst schnelles Verderben zuziehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Und viele werden ihren Ausschweifungen nachfolgen, um welcher willen der Weg der Wahrheit verlästert werden wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Und durch Habsucht werden sie euch verhandeln mit erkünstelten Worten; welchen das Gericht von alters her nicht zögert, und ihr Verderben schlummert nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Denn wenn Gott Engel, welche gesündigt hatten, nicht verschonte, sondern, sie in den tiefsten Abgrund hinabstürzend, Ketten der Finsternis überlieferte, um aufbewahrt zu werden für das Gericht;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'und die alte Welt nicht verschonte, sondern nur Noah, den Prediger der Gerechtigkeit, selbacht erhielt, als er die Flut über die Welt der Gottlosen brachte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'und die Städte Sodom und Gomorra einäscherte und zur Zerstörung verurteilte, indem er sie denen, welche gottlos leben würden, als Beispiel hinstellte;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'und den gerechten Lot rettete, der von dem ausschweifenden Wandel der Ruchlosen gequält wurde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(denn der unter ihnen wohnende Gerechte quälte durch das, was er sah und hörte, Tag für Tag seine gerechte Seele mit ihren gesetzlosen Werken)...');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Der Herr weiß die Gottseligen aus der Versuchung zu retten, die Ungerechten aber aufzubewahren auf den Tag des Gerichts, um bestraft zu werden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'besonders aber die, welche in der Lust der Befleckung dem Fleische nachwandeln und die Herrschaft verachten, Verwegene, Eigenmächtige; sie erzittern nicht, Herrlichkeiten zu lästern,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'während Engel, die an Stärke und Macht größer sind, nicht ein lästerndes Urteil wider sie beim Herrn vorbringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Diese aber, wie unvernünftige, natürliche Tiere, geschaffen zum Fang und Verderben, lästernd über das, was sie nicht wissen, werden auch in ihrem eigenen Verderben umkommen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'indem sie den Lohn der Ungerechtigkeit empfangen; welche eine eintägige Schwelgerei für Vergnügen achten, Flecken und Schandflecke, die in ihren eigenen Betrügereien schwelgen und Festessen mit euch halten;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'welche Augen voll Ehebruch haben und von der Sünde nicht ablassen, indem sie unbefestigte Seelen anlocken; die ein Herz haben, in Habsucht geübt, Kinder des Fluches,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'welche, da sie den geraden Weg verlassen haben, abgeirrt sind, indem sie dem Wege des Balaam nachfolgten, des Sohnes Bosors, der den Lohn der Ungerechtigkeit liebte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'aber eine Zurechtweisung seiner eigenen Verkehrtheit empfing: ein sprachloses Lasttier, mit Menschenstimme redend, wehrte der Torheit des Propheten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Diese sind Brunnen ohne Wasser, und Nebel, vom Sturmwind getrieben, welchen das Dunkel der Finsternis aufbewahrt ist in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Denn stolze, nichtige Reden führend, locken sie mit fleischlichen Lüsten durch Ausschweifungen diejenigen an, welche eben entflohen sind denen, die im Irrtum wandeln;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'ihnen Freiheit versprechend, während sie selbst Sklaven des Verderbens sind; denn von wem jemand überwältigt ist, diesem ist er auch als Sklave unterworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Denn wenn sie, entflohen den Befleckungen der Welt durch die Erkenntnis des Herrn und Heilandes Jesus Christus, aber wiederum in diese verwickelt, überwältigt werden, so ist ihr Letztes ärger geworden als das Erste.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Denn es wäre ihnen besser, den Weg der Gerechtigkeit nicht erkannt zu haben, als, nachdem sie ihn erkannt haben, umzukehren von dem ihnen überlieferten heiligen Gebot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Es ist ihnen aber nach dem wahren Sprichwort ergangen: Der Hund kehrte um zu seinem eigenen Gespei, und die gewaschene Sau zum Wälzen im Kot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Diesen zweiten Brief, Geliebte, schreibe ich euch bereits, in welchen beiden ich durch Erinnerung eure lautere Gesinnung aufwecke,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'damit ihr gedenket der von den heiligen Propheten zuvor gesprochenen Worte und des Gebotes des Herrn und Heilandes durch eure Apostel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'indem ihr zuerst dieses wisset, daß in den letzten Tagen Spötter mit Spötterei kommen werden, die nach ihren eigenen Lüsten wandeln und sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'Wo ist die Verheißung seiner Ankunft? Denn seitdem die Väter entschlafen sind, bleibt alles so von Anfang der Schöpfung an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Denn nach ihrem eigenen Willen ist ihnen dies verborgen, daß von alters her Himmel waren und eine Erde, entstehend aus Wasser und im Wasser durch das Wort Gottes,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'durch welche die damalige Welt, vom Wasser überschwemmt, unterging.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Die jetzigen Himmel aber und die Erde sind durch sein Wort aufbewahrt, für das Feuer behalten auf den Tag des Gerichts und des Verderbens der gottlosen Menschen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Dies eine aber sei euch nicht verborgen, Geliebte, daß ein Tag bei dem Herrn ist wie tausend Jahre, und tausend Jahre wie ein Tag.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Der Herr verzieht nicht die Verheißung, wie es etliche für einen Verzug achten, sondern er ist langmütig gegen euch, da er nicht will, daß irgend welche verloren gehen, sondern daß alle zur Buße kommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Es wird aber der Tag des Herrn kommen wie ein Dieb, an welchem die Himmel vergehen werden mit gewaltigem Geräusch, die Elemente aber im Brande werden aufgelöst und die Erde und die Werke auf ihr verbrannt werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Da nun dies alles aufgelöst wird, welche solltet ihr dann sein in heiligem Wandel und Gottseligkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Indem ihr erwartet und beschleuniget die Ankunft des Tages Gottes, dessentwegen die Himmel, in Feuer geraten, werden aufgelöst und die Elemente im Brande zerschmelzen werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Wir erwarten aber, nach seiner Verheißung, neue Himmel und eine neue Erde, in welchen Gerechtigkeit wohnt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Deshalb, Geliebte, da ihr dies erwartet, so befleißiget euch, ohne Flecken und tadellos von ihm erfunden zu werden in Frieden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Und achtet die Langmut unseres Herrn für Errettung, so wie auch unser geliebter Bruder Paulus nach der ihm gegebenen Weisheit euch geschrieben hat,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'wie auch in allen seinen Briefen, wenn er in denselben von diesen Dingen redet, von denen etliche schwer zu verstehen sind, welche die Unwissenden und Unbefestigten verdrehen, wie auch die übrigen Schriften, zu ihrem eigenen Verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Ihr nun, Geliebte, da ihr es vorher wisset, so hütet euch, daß ihr nicht, durch den Irrwahn der Ruchlosen mitfortgerissen, aus eurer eigenen Festigkeit fallet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Wachset aber in der Gnade und Erkenntnis unseres Herrn und Heilandes Jesus Christus. Ihm sei die Herrlichkeit, sowohl jetzt als auch auf den Tag der Ewigkeit! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Was von Anfang war, was wir gehört, was wir mit unseren Augen gesehen, was wir angeschaut und unsere Hände betastet haben, betreffend das Wort des Lebens;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(und das Leben ist geoffenbart worden, und wir haben gesehen und bezeugen und verkündigen euch das ewige Leben, welches bei dem Vater war und uns geoffenbart worden ist;)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'was wir gesehen und gehört haben, verkündigen wir euch, auf daß auch ihr mit uns Gemeinschaft habet; und zwar ist unsere Gemeinschaft mit dem Vater und mit seinem Sohne Jesus Christus.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Und dies schreiben wir euch, auf daß eure Freude völlig sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Und dies ist die Botschaft, die wir von ihm gehört haben und euch verkündigen: daß Gott Licht ist und gar keine Finsternis in ihm ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Wenn wir sagen, daß wir Gemeinschaft mit ihm haben, und wandeln in der Finsternis, so lügen wir und tun nicht die Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Wenn wir aber in dem Lichte wandeln, wie er in dem Lichte ist, so haben wir Gemeinschaft miteinander, und das Blut Jesu Christi, seines Sohnes, reinigt uns von aller Sünde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Wenn wir sagen, daß wir keine Sünde haben, so betrügen wir uns selbst, und die Wahrheit ist nicht in uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Wenn wir unsere Sünden bekennen, so ist er treu und gerecht, daß er uns die Sünden vergibt und uns reinigt von aller Ungerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Wenn wir sagen, daß wir nicht gesündigt haben, so machen wir ihn zum Lügner, und sein Wort ist nicht in uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Meine Kinder, ich schreibe euch dieses, auf daß ihr nicht sündiget; und wenn jemand gesündigt hat wir haben einen Sachwalter bei dem Vater, Jesum Christum, den Gerechten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Und er ist die Sühnung für unsere Sünden, nicht allein aber für die unseren, sondern auch für die ganze Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Und hieran wissen wir, daß wir ihn kennen, wenn wir seine Gebote halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Wer da sagt: Ich kenne ihn, und hält seine Gebote nicht, ist ein Lügner, und in diesem ist die Wahrheit nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Wer aber irgend sein Wort hält, in diesem ist wahrhaftig die Liebe Gottes vollendet. Hieran wissen wir, daß wir in ihm sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Wer da sagt, daß er in ihm bleibe, ist schuldig, selbst auch so zu wandeln, wie er gewandelt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Geliebte, nicht ein neues Gebot schreibe ich euch, sondern ein altes Gebot, welches ihr von Anfang hattet. Das alte Gebot ist das Wort, welches ihr gehört habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Wiederum schreibe ich euch ein neues Gebot, das was wahr ist in ihm und in euch, weil die Finsternis vergeht und das wahrhaftige Licht schon leuchtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Wer da sagt, daß er in dem Lichte sei und haßt seinen Bruder, ist in der Finsternis bis jetzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Wer seinen Bruder liebt, bleibt in dem Lichte, und kein Ärgernis ist in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Wer aber seinen Bruder haßt, ist in der Finsternis und wandelt in der Finsternis und weiß nicht, wohin er geht, weil die Finsternis seine Augen verblendet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Ich schreibe euch, Kinder, weil euch die Sünden vergeben sind um seines Namens willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Ich schreibe euch, Väter, weil ihr den erkannt habt, der von Anfang ist. Ich schreibe euch, Jünglinge, weil ihr den Bösen überwunden habt. Ich schreibe euch, Kindlein, weil ihr den Vater erkannt habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Ich habe euch, Väter, geschrieben, weil ihr den erkannt habt, der von Anfang ist. Ich habe euch, Jünglinge, geschrieben, weil ihr stark seid und das Wort Gottes in euch bleibt und ihr den Bösen überwunden habt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Liebet nicht die Welt, noch was in der Welt ist. Wenn jemand die Welt liebt, so ist die Liebe des Vaters nicht in ihm;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'denn alles, was in der Welt ist, die Lust des Fleisches und die Lust der Augen und der Hochmut des Lebens, ist nicht von dem Vater, sondern ist von der Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Und die Welt vergeht und ihre Lust; wer aber den Willen Gottes tut, bleibt in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Kindlein, es ist die letzte Stunde, und wie ihr gehört habt, daß der Antichrist kommt, so sind auch jetzt viele Antichristen geworden; daher wissen wir, daß es die letzte Stunde ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Sie sind von uns ausgegangen, aber sie waren nicht von uns; denn wenn sie von uns gewesen wären, so würden sie wohl bei uns geblieben sein; aber auf daß sie offenbar würden, daß sie alle nicht von uns sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Und ihr habt die Salbung von dem Heiligen und wisset alles.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Ich habe euch nicht geschrieben, weil ihr die Wahrheit nicht wisset, sondern weil ihr sie wisset, und daß keine Lüge aus der Wahrheit ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Wer ist der Lügner, wenn nicht der, der da leugnet, daß Jesus der Christus ist? Dieser ist der Antichrist, der den Vater und den Sohn leugnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Jeder, der den Sohn leugnet, hat auch den Vater nicht; wer den Sohn bekennt, hat auch den Vater.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Ihr, was ihr von Anfang gehört habt, bleibe in euch. Wenn in euch bleibt, was ihr von Anfang gehört habt, so werdet auch ihr in dem Sohne und in dem Vater bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Und dies ist die Verheißung, welche er uns verheißen hat: das ewige Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Dies habe ich euch betreffs derer geschrieben, die euch verführen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Und ihr, die Salbung, die ihr von ihm empfangen habt, bleibt in euch, und ihr bedürfet nicht, daß euch jemand belehre, sondern wie dieselbe Salbung euch über alles belehrt und wahr ist und keine Lüge ist, und wie sie euch belehrt hat, so werdet ihr in ihm bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Und nun, Kinder, bleibet in ihm, auf daß wir, wenn er geoffenbart werden wird, Freimütigkeit haben und nicht vor ihm beschämt werden bei seiner Ankunft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Wenn ihr wisset, daß er gerecht ist, so erkennet, daß jeder, der die Gerechtigkeit tut, aus ihm geboren ist. -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Sehet, welch eine Liebe uns der Vater gegeben hat, daß wir Kinder Gottes heißen sollen! Deswegen erkennt uns die Welt nicht, weil sie ihn nicht erkannt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Geliebte, jetzt sind wir Kinder Gottes, und es ist noch nicht offenbar geworden, was wir sein werden; wir wissen, daß, wenn es offenbar werden wird, wir ihm gleich sein werden, denn wir werden ihn sehen, wie er ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Und jeder, der diese Hoffnung zu ihm hat, reinigt sich selbst, gleichwie er rein ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Jeder, der die Sünde tut, tut auch die Gesetzlosigkeit, und die Sünde ist die Gesetzlosigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Und ihr wisset, daß er geoffenbart worden ist, auf daß er unsere Sünden wegnehme; und Sünde ist nicht in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Jeder, der in ihm bleibt, sündigt nicht; jeder, der sündigt, hat ihn nicht gesehen noch ihn erkannt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Kinder, daß niemand euch verführe! Wer die Gerechtigkeit tut, ist gerecht, gleichwie er gerecht ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Wer die Sünde tut, ist aus dem Teufel, denn der Teufel sündigt von Anfang. Hierzu ist der Sohn Gottes geoffenbart worden, auf daß er die Werke des Teufels vernichte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Jeder, der aus Gott geboren ist, tut nicht Sünde, denn sein Same bleibt in ihm; und er kann nicht sündigen, weil er aus Gott geboren ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Hieran sind offenbar die Kinder Gottes und die Kinder des Teufels. Jeder, der nicht Gerechtigkeit tut, ist nicht aus Gott, und wer nicht seinen Bruder liebt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Denn dies ist die Botschaft, die ihr von Anfang gehört habt, daß wir einander lieben sollen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'nicht wie Kain aus dem Bösen war und seinen Bruder ermordete; und weshalb ermordete er ihn? Weil seine Werke böse waren, die seines Bruders aber gerecht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Wundert euch nicht, Brüder, wenn die Welt euch haßt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Wir wissen, daß wir aus dem Tode in das Leben übergegangen sind, weil wir die Brüder lieben; wer den Bruder nicht liebt, bleibt in dem Tode.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Jeder, der seinen Bruder haßt, ist ein Menschenmörder, und ihr wisset, daß kein Menschenmörder ewiges Leben in sich bleibend hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Hieran haben wir die Liebe erkannt, daß er für uns sein Leben dargelegt hat; auch wir sind schuldig, für die Brüder das Leben darzulegen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Wer aber der Welt Güter hat und sieht seinen Bruder Mangel leiden und verschließt sein Herz vor ihm, wie bleibt die Liebe Gottes in ihm?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Kinder, laßt uns nicht lieben mit Worten, noch mit der Zunge, sondern in Tat und Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Und hieran werden wir erkennen, daß wir aus der Wahrheit sind, und werden vor ihm unsere Herzen überzeugen, -');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'daß, wenn unser Herz uns verurteilt, Gott größer ist als unser Herz und alles kennt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Geliebte, wenn unser Herz uns nicht verurteilt, so haben wir Freimütigkeit zu Gott,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'und was irgend wir bitten, empfangen wir von ihm, weil wir seine Gebote halten und das vor ihm Wohlgefällige tun.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Und dies ist sein Gebot, daß wir an den Namen seines Sohnes Jesus Christus glauben und einander lieben, gleichwie er uns ein Gebot gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Und wer seine Gebote hält, bleibt in ihm, und er in ihm; und hieran erkennen wir, daß er in uns bleibt, durch den Geist, den er uns gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Geliebte, glaubet nicht jedem Geiste, sondern prüfet die Geister, ob sie aus Gott sind; denn viele falsche Propheten sind in die Welt ausgegangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Hieran erkennet ihr den Geist Gottes: Jeder Geist, der Jesum Christum im Fleische gekommen bekennt, ist aus Gott;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'und jeder Geist, der nicht Jesum Christum im Fleische gekommen bekennt, ist nicht aus Gott; und dies ist der Geist des Antichrists, von welchem ihr gehört habt, daß er komme, und jetzt ist er schon in der Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Ihr seid aus Gott, Kinder, und habt sie überwunden, weil der, welcher in euch ist, größer ist als der, welcher in der Welt ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Sie sind aus der Welt, deswegen reden sie aus der Welt, und die Welt hört sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Wir sind aus Gott; wer Gott kennt, hört uns; wer nicht aus Gott ist, hört uns nicht. Hieraus erkennen wir den Geist der Wahrheit und den Geist des Irrtums.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Geliebte, laßt uns einander lieben, denn die Liebe ist aus Gott; und jeder, der liebt, ist aus Gott geboren und erkennt Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Wer nicht liebt, hat Gott nicht erkannt, denn Gott ist Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Hierin ist die Liebe Gottes zu uns geoffenbart worden, daß Gott seinen eingeborenen Sohn in die Welt gesandt hat, auf daß wir durch ihn leben möchten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Hierin ist die Liebe: nicht daß wir Gott geliebt haben, sondern daß er uns geliebt und seinen Sohn gesandt hat als eine Sühnung für unsere Sünden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Geliebte, wenn Gott uns also geliebt hat, so sind auch wir schuldig, einander zu lieben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Niemand hat Gott jemals gesehen. Wenn wir einander lieben, so bleibt Gott in uns, und seine Liebe ist vollendet in uns.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Hieran erkennen wir, daß wir in ihm bleiben und er in uns, daß er uns von seinem Geiste gegeben hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Und wir haben gesehen und bezeugen, daß der Vater den Sohn gesandt hat als Heiland der Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Wer irgend bekennt, daß Jesus der Sohn Gottes ist, in ihm bleibt Gott und er in Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Und wir haben erkannt und geglaubt die Liebe, die Gott zu uns hat. Gott ist Liebe, und wer in der Liebe bleibt, bleibt in Gott und Gott in ihm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Hierin ist die Liebe mit uns vollendet worden, damit wir Freimütigkeit haben an dem Tage des Gerichts, daß, gleichwie er ist, auch wir sind in dieser Welt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Furcht ist nicht in der Liebe, sondern die vollkommene Liebe treibt die Furcht aus, denn die Furcht hat Pein. Wer sich aber fürchtet, ist nicht vollendet in der Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Wir lieben, weil er uns zuerst geliebt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Wenn jemand sagt: Ich liebe Gott, und haßt seinen Bruder, so ist er ein Lügner. Denn wer seinen Bruder nicht liebt, den er gesehen hat, wie kann der Gott lieben, den er nicht gesehen hat?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Und dieses Gebot haben wir von ihm, daß, wer Gott liebt, auch seinen Bruder liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Jeder, der da glaubt, daß Jesus der Christus ist, ist aus Gott geboren; und jeder, der den liebt, welcher geboren hat, liebt auch den, der aus ihm geboren ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Hieran wissen wir, daß wir die Kinder Gottes lieben, wenn wir Gott lieben und seine Gebote halten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Denn dies ist die Liebe Gottes, daß wir seine Gebote halten, und seine Gebote sind nicht schwer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Denn alles, was aus Gott geboren ist, überwindet die Welt; und dies ist der Sieg, der die Welt überwunden hat: unser Glaube.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Wer ist es, der die Welt überwindet, wenn nicht der, welcher glaubt, daß Jesus der Sohn Gottes ist?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Dieser ist es, der gekommen ist durch Wasser und Blut, Jesus, der Christus; nicht durch das Wasser allein, sondern durch das Wasser und das Blut. Und der Geist ist es, der da zeugt, weil der Geist die Wahrheit ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Denn drei sind, die da zeugen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'der Geist und das Wasser und das Blut, und die drei sind einstimmig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Wenn wir das Zeugnis der Menschen annehmen, das Zeugnis Gottes ist größer; denn dies ist das Zeugnis Gottes, welches er gezeugt hat über seinen Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Wer an den Sohn Gottes glaubt, hat das Zeugnis in sich selbst; wer Gott nicht glaubt, hat ihn zum Lügner gemacht, weil er nicht an das Zeugnis geglaubt hat, welches Gott gezeugt hat über seinen Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Und dies ist das Zeugnis: daß Gott uns ewiges Leben gegeben hat, und dieses Leben ist in seinem Sohne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Wer den Sohn hat, hat das Leben; wer den Sohn Gottes nicht hat, hat das Leben nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Dies habe ich euch geschrieben, auf daß ihr wisset, daß ihr ewiges Leben habt, die ihr glaubet an den Namen des Sohnes Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Und dies ist die Zuversicht, die wir zu ihm haben, daß, wenn wir etwas nach seinem Willen bitten, er uns hört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Und wenn wir wissen, daß er uns hört, um was irgend wir bitten, so wissen wir, daß wir die Bitten haben, die wir von ihm erbeten haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Wenn jemand seinen Bruder sündigen sieht, eine Sünde nicht zum Tode, so wird er bitten, und er wird ihm das Leben geben, denen, die nicht zum Tode sündigen. Es gibt Sünde zum Tode; nicht für diese sage ich, daß er bitten solle.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Jede Ungerechtigkeit ist Sünde; und es gibt Sünde, die nicht zum Tode ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Wir wissen, daß jeder, der aus Gott geboren ist, nicht sündigt; sondern der aus Gott Geborene bewahrt sich, und der Böse tastet ihn nicht an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Wir wissen, daß wir aus Gott sind, und die ganze Welt liegt in dem Bösen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Wir wissen aber, daß der Sohn Gottes gekommen ist und uns ein Verständnis gegeben hat, auf daß wir den Wahrhaftigen kennen; und wir sind in dem Wahrhaftigen, in seinem Sohne Jesus Christus. Dieser ist der wahrhaftige Gott und das ewige Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Kinder, hütet euch vor den Götzen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Der Älteste der auserwählten Frau und ihren Kindern, die ich liebe in der Wahrheit; und nicht ich allein, sondern auch alle, welche die Wahrheit erkannt haben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'um der Wahrheit willen, die in uns bleibt und mit uns sein wird in Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Es wird mit euch sein Gnade, Barmherzigkeit, Friede von Gott, dem Vater, und von dem Herrn Jesus Christus, dem Sohne des Vaters, in Wahrheit und Liebe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Ich freute mich sehr, daß ich einige von deinen Kindern in der Wahrheit wandelnd gefunden habe, wie wir von dem Vater ein Gebot empfangen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Und nun bitte ich dich, Frau, nicht als ob ich ein neues Gebot dir schriebe, sondern das, welches wir von Anfang gehabt haben: daß wir einander lieben sollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Und dies ist die Liebe, daß wir nach seinen Geboten wandeln. Dies ist das Gebot, wie ihr von Anfang gehört habt, daß ihr darin wandeln sollt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Denn viele Verführer sind in die Welt ausgegangen, die nicht Jesum Christum im Fleische kommend bekennen; dies ist der Verführer und der Antichrist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Sehet auf euch selbst, auf daß wir nicht verlieren, was wir erarbeitet haben, sondern vollen Lohn empfangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Jeder, der weitergeht und nicht bleibt in der Lehre des Christus, hat Gott nicht; wer in der Lehre bleibt, dieser hat sowohl den Vater als auch den Sohn.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Wenn jemand zu euch kommt und diese Lehre nicht bringt, so nehmet ihn nicht ins Haus auf und grüßet ihn nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Denn wer ihn grüßt, nimmt teil an seinen bösen Werken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Da ich euch vieles zu schreiben habe, wollte ich es nicht mit Papier und Tinte tun, sondern ich hoffe, zu euch zu kommen und mündlich mit euch zu reden, auf daß unsere Freude völlig sei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Es grüßen dich die Kinder deiner auserwählten Schwester.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Der Älteste dem geliebten Gajus, den ich liebe in der Wahrheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Geliebter, ich wünsche, daß es dir in allem wohlgehe und du gesund seiest, gleichwie es deiner Seele wohlgeht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Denn ich freute mich sehr, als Brüder kamen und Zeugnis gaben von deinem Festhalten an der Wahrheit, gleichwie du in der Wahrheit wandelst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Ich habe keine größere Freude als dies, daß ich höre, daß meine Kinder in der Wahrheit wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Geliebter, treulich tust du, was irgend du an den Brüdern, und zwar an Fremden, getan haben magst,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, '(die von deiner Liebe Zeugnis gegeben haben vor der Versammlung) und du wirst wohltun, wenn du sie auf eine gotteswürdige Weise geleitest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Denn für den Namen sind sie ausgegangen und nehmen nichts von denen aus den Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Wir nun sind schuldig, solche aufzunehmen, auf daß wir Mitarbeiter der Wahrheit werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Ich schrieb etwas an die Versammlung, aber Diotrephes, der gern unter ihnen der erste sein will, nimmt uns nicht an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Deshalb, wenn ich komme, will ich seiner Werke gedenken, die er tut, indem er mit bösen Worten wider uns schwatzt; und sich hiermit nicht begnügend, nimmt er selbst die Brüder nicht an und wehrt auch denen, die es wollen, und stößt sie aus der Versammlung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Geliebter, ahme nicht das Böse nach, sondern das Gute. Wer Gutes tut, ist aus Gott; wer Böses tut, hat Gott nicht gesehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Dem Demetrius wird Zeugnis gegeben von allen und von der Wahrheit selbst; aber auch wir geben Zeugnis, und du weißt, daß unser Zeugnis wahr ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Ich hätte dir vieles zu schreiben, aber ich will dir nicht mit Tinte und Feder schreiben,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'sondern ich hoffe, dich bald zu sehen, und wir wollen mündlich miteinander reden. (G1:15) Friede dir! Es grüßen dich die Freunde. Grüße die Freunde mit Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, '');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Judas, Knecht Jesu Christi und Bruder des Jakobus, den in Gott, dem Vater, geliebten und in Jesu Christo bewahrten Berufenen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Barmherzigkeit und Friede und Liebe sei euch vermehrt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Geliebte, indem ich allen Fleiß anwandte, euch über unser gemeinsames Heil zu schreiben, war ich genötigt, euch zu schreiben und zu ermahnen, für den einmal den Heiligen überlieferten Glauben zu kämpfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Denn gewisse Menschen haben sich nebeneingeschlichen, die schon vorlängst zu diesem Gericht zuvor aufgezeichnet waren, Gottlose, welche die Gnade unseres Gottes in Ausschweifung verkehren und unseren alleinigen Gebieter und Herrn Jesus Christus verleugnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Ich will euch aber, die ihr einmal alles wußtet, daran erinnern, daß der Herr, nachdem er das Volk aus dem Lande Ägypten gerettet hatte, zum anderenmal die vertilgte, welche nicht geglaubt haben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'und Engel, die ihren ersten Zustand nicht bewahrt, sondern ihre eigene Behausung verlassen haben, hat er zum Gericht des großen Tages mit ewigen Ketten unter der Finsternis verwahrt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Wie Sodom und Gomorra und die umliegenden Städte, die sich, gleicherweise wie jene, der Hurerei ergaben und anderem Fleische nachgingen, als ein Beispiel vorliegen, indem sie des ewigen Feuers Strafe leiden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Doch gleicherweise beflecken auch diese Träumer das Fleisch und verachten die Herrschaft und lästern Herrlichkeiten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Michael aber, der Erzengel, als er, mit dem Teufel streitend, Wortwechsel hatte um den Leib Moses\', wagte nicht ein lästerndes Urteil über ihn zu fällen, sondern sprach: Der Herr schelte dich!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Diese aber lästern, was sie nicht kennen; was irgend sie aber von Natur wie die unvernünftigen Tiere verstehen, darin verderben sie sich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Wehe ihnen! Denn sie sind den Weg Kains gegangen und haben sich für Lohn dem Irrtum Balaams überliefert, und in dem Widerspruch Korahs sind sie umgekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Diese sind Flecken bei euren Liebesmahlen, indem sie ohne Furcht Festessen mit euch halten und sich selbst weiden; Wolken ohne Wasser, von Winden hingetrieben; spätherbstliche Bäume, fruchtleer, zweimal erstorben, entwurzelt;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'wilde Meereswogen, die ihre eigenen Schändlichkeiten ausschäumen; Irrsterne, denen das Dunkel der Finsternis in Ewigkeit aufbewahrt ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Es hat aber auch Henoch, der siebte von Adam, von diesen geweissagt und gesagt: \"Siehe, der Herr ist gekommen inmitten seiner heiligen Tausende,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Gericht auszuführen wider alle und völlig zu überführen alle ihre Gottlosen von allen ihren Werken der Gottlosigkeit, die sie gottlos verübt haben, und von all den harten Worten, welche gottlose Sünder wider ihn geredet haben\".');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Diese sind Murrende, mit ihrem Lose Unzufriedene, die nach ihren Lüsten wandeln; und ihr Mund redet stolze Worte, und Vorteils halber bewundern sie Personen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Ihr aber, Geliebte, gedenket an die von den Aposteln unseres Herrn Jesus Christus zuvorgesprochenen Worte,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'daß sie euch sagten, daß am Ende der Zeit Spötter sein werden, die nach ihren eigenen Lüsten der Gottlosigkeit wandeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Diese sind es, die sich absondern, natürliche Menschen, die den Geist nicht haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Ihr aber, Geliebte, euch selbst erbauend auf euren allerheiligsten Glauben, betend im Heiligen Geiste,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'erhaltet euch selbst in der Liebe Gottes, indem ihr die Barmherzigkeit unseres Herrn Jesus Christus erwartet zum ewigen Leben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Und die einen, welche streiten, weiset zurecht,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'die anderen aber rettet mit Furcht, sie aus dem Feuer reißend, indem ihr auch das von dem Fleische befleckte Kleid hasset.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Dem aber, der euch ohne Straucheln zu bewahren und vor seiner Herrlichkeit tadellos darzustellen vermag mit Frohlocken, dem alleinigen Gott,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'unserem Heilande, durch Jesum Christum, unseren Herrn, sei Herrlichkeit, Majestät, Macht und Gewalt vor aller Zeit und jetzt und in alle Ewigkeit! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Offenbarung Jesu Christi, welche Gott ihm gab, um seinen Knechten zu zeigen, was bald geschehen muß; und durch seinen Engel sendend, hat er es seinem Knechte Johannes gezeigt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'der bezeugt hat das Wort Gottes und das Zeugnis Jesu Christi, alles, was er sah.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Glückselig, der da liest und die da hören die Worte der Weissagung und bewahren, was in ihr geschrieben ist; denn die Zeit ist nahe!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Johannes den sieben Versammlungen, die in Asien sind: Gnade euch und Friede von dem, der da ist und der da war und der da kommt, und von den sieben Geistern, die vor seinem Throne sind,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'und von Jesu Christo, welcher der treue Zeuge ist, der Erstgeborene der Toten und der Fürst der Könige der Erde! Dem, der uns liebt und uns von unseren Sünden gewaschen hat in seinem Blute,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'und uns gemacht hat zu einem Königtum, zu Priestern seinem Gott und Vater: Ihm sei die Herrlichkeit und die Macht von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Siehe, er kommt mit den Wolken, und jedes Auge wird ihn sehen, auch die ihn durchstochen haben, und wehklagen werden seinetwegen alle Stämme des Landes. Ja, Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Ich bin das Alpha und das Omega, spricht der Herr, Gott, der da ist und der da war und der da kommt, der Allmächtige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Ich, Johannes, euer Bruder und Mitgenosse in der Drangsal und dem Königtum und dem Ausharren in Jesu, war auf der Insel, genannt Patmos, um des Wortes Gottes und des Zeugnisses Jesu willen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Ich war an des Herrn Tage im Geiste, und ich hörte hinter mir eine laute Stimme wie die einer Posaune, welche sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'Was du siehst, schreibe in ein Buch und sende es den sieben Versammlungen: nach Ephesus und nach Smyrna und nach Pergamus und nach Thyatira und nach Sardes und nach Philadelphia und nach Laodicäa.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Und ich wandte mich um, die Stimme zu sehen, welche mit mir redete, und als ich mich umgewandt hatte, sah ich sieben goldene Leuchter,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'und inmitten der sieben Leuchter einen gleich dem Sohne des Menschen, angetan mit einem bis zu den Füßen reichenden Gewande, und an der Brust umgürtet mit einem goldenen Gürtel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'sein Haupt aber und seine Haare weiß wie weiße Wolle, wie Schnee, und seine Augen wie eine Feuerflamme,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'und seine Füße gleich glänzendem Kupfer, als glühten sie im Ofen, und seine Stimme wie das Rauschen vieler Wasser;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'und er hatte in seiner rechten Hand sieben Sterne, und aus seinem Munde ging hervor ein scharfes, zweischneidiges Schwert, und sein Angesicht war, wie die Sonne leuchtet in ihrer Kraft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Und als ich ihn sah, fiel ich zu seinen Füßen wie tot. Und er legte seine Rechte auf mich und sprach: Fürchte dich nicht! Ich bin der Erste und der Letzte');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'und der Lebendige, und ich war tot, und siehe, ich bin lebendig von Ewigkeit zu Ewigkeit und habe die Schlüssel des Todes und des Hades.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Schreibe nun, was du gesehen hast, und was ist, und was nach diesem geschehen wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Das Geheimnis der sieben Sterne, die du in meiner Rechten gesehen hast, und die sieben goldenen Leuchter: Die sieben Sterne sind Engel der sieben Versammlungen, und die sieben Leuchter sind sieben Versammlungen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Dem Engel der Versammlung in Ephesus schreibe: Dieses sagt, der die sieben Sterne in seiner Rechten hält, der da wandelt inmitten der sieben goldenen Leuchter:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Ich kenne deine Werke und deine Arbeit und dein Ausharren, und daß du Böse nicht ertragen kannst; und du hast die geprüft, welche sich Apostel nennen, und sind es nicht, und hast sie als Lügner erfunden;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'und du hast Ausharren und hast getragen um meines Namens willen, und bist nicht müde geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Aber ich habe wider dich, daß du deine erste Liebe verlassen hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Gedenke nun, wovon du gefallen bist, und tue Buße und tue die ersten Werke; wenn aber nicht, so komme ich dir und werde deinen Leuchter aus seiner Stelle wegrücken, wenn du nicht Buße tust.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Aber dieses hast du, daß du die Werke der Nikolaiten hassest, die auch ich hasse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Wer ein Ohr hat, höre, was der Geist den Versammlungen sagt! Dem, der überwindet, dem werde ich zu essen geben von dem Baume des Lebens, welcher in dem Paradiese Gottes ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Und dem Engel der Versammlung in Smyrna schreibe: Dieses sagt der Erste und der Letzte, der starb und wieder lebendig wurde:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Ich kenne deine Drangsal und deine Armut (du bist aber reich) und die Lästerung von denen, welche sagen, sie seien Juden, und sind es nicht, sondern eine Synagoge des Satans.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Fürchte nichts von dem, was du leiden wirst. Siehe, der Teufel wird etliche von euch ins Gefängnis werfen, auf daß ihr geprüft werdet, und ihr werdet Drangsal haben zehn Tage. Sei getreu bis zum Tode, und ich werde dir die Krone des Lebens geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Wer ein Ohr hat, höre was der Geist den Versammlungen sagt! Wer überwindet, wird nicht beschädigt werden von dem zweiten Tode.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Und dem Engel der Versammlung in Pergamus schreibe: Dieses sagt, der das scharfe, zweischneidige Schwert hat:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Ich weiß, wo du wohnst, wo der Thron des Satans ist; und du hältst fest an meinem Namen und hast meinen Glauben nicht verleugnet, auch in den Tagen, in welchen Antipas mein treuer Zeuge war, der bei euch, wo der Satan wohnt, ermordet worden ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Aber ich habe ein weniges wider dich, daß du solche dort hast, welche die Lehre Balaams festhalten, der den Balak lehrte, ein Ärgernis vor die Söhne Israels zu legen, Götzenopfer zu essen und Hurerei zu treiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Also hast auch du solche, welche in gleicher Weise die Lehre der Nikolaiten festhalten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Tue nun Buße; wenn aber nicht, so komme ich dir bald und werde Krieg mit ihnen führen mit dem Schwerte meines Mundes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Wer ein Ohr hat, höre, was der Geist den Versammlungen sagt! Dem, der überwindet, dem werde ich von dem verborgenen Manna geben; und ich werde ihm einen weißen Stein geben, und auf den Stein einen neuen Namen geschrieben, welchen niemand kennt, als wer ihn empfängt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Und dem Engel der Versammlung in Thyatira schreibe: Dieses sagt der Sohn Gottes, der seine Augen hat wie eine Feuerflamme und seine Füße gleich glänzendem Kupfer:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Ich kenne deine Werke und deine Liebe und deinen Glauben und deinen Dienst und dein Ausharren, und weiß, daß deiner letzten Werke mehr sind als der ersten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Aber ich habe wider dich, daß du das Weib Jesabel duldest, welche sich eine Prophetin nennt, und sie lehrt und verführt meine Knechte, Hurerei zu treiben und Götzenopfer zu essen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Und ich gab ihr Zeit, auf daß sie Buße täte, und sie will nicht Buße tun von ihrer Hurerei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Siehe, ich werfe sie in ein Bett und die, welche Ehebruch mit ihr treiben, in große Drangsal, wenn sie nicht Buße tun von ihren Werken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Und ihre Kinder werde ich mit Tod töten, und alle Versammlungen werden erkennen, daß ich es bin, der Nieren und Herzen erforscht: und ich werde euch einem jeden nach euren Werken geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Euch aber sage ich, den übrigen, die in Thyatira sind, so viele diese Lehre nicht haben, welche die Tiefen des Satans, wie sie sagen, nicht erkannt haben: ich werfe keine andere Last auf euch;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'doch was ihr habt haltet fest, bis ich komme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Und wer überwindet und meine Werke bewahrt bis ans Ende, dem werde ich Gewalt über die Nationen geben;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'und er wird sie weiden mit eiserner Rute, wie Töpfergefäße zerschmettert werden, wie auch ich von meinem Vater empfangen habe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'und ich werde ihm den Morgenstern geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Wer ein Ohr hat, höre, was der Geist den Versammlungen sagt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Und dem Engel der Versammlung in Sardes schreibe: Dieses sagt, der die sieben Geister Gottes hat und die sieben Sterne: Ich kenne deine Werke, daß du den Namen hast, daß du lebest, und bist tot.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Sei wachsam und stärke das Übrige, das sterben will; denn ich habe deine Werke nicht völlig erfunden vor meinem Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Gedenke nun, wie du empfangen und gehört hast, und bewahre es und tue Buße. Wenn du nun nicht wachen wirst, so werde ich über dich kommen wie ein Dieb, und du wirst nicht wissen, um welche Stunde ich über dich kommen werde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Aber du hast einige wenige Namen in Sardes, die ihre Kleider nicht besudelt haben; und sie werden mit mir einhergehen in weißen Kleidern, denn sie sind es wert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Wer überwindet, der wird mit weißen Kleidern bekleidet werden, und ich werde seinen Namen nicht auslöschen aus dem Buche des Lebens und werde seinen Namen bekennen vor meinem Vater und vor seinen Engeln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Wer ein Ohr hat, höre, was der Geist den Versammlungen sagt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Und dem Engel der Versammlung in Philadelphia schreibe: Dieses sagt der Heilige, der Wahrhaftige, der den Schlüssel des David hat, der da öffnet, und niemand wird schließen, und schließt und niemand wird öffnen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Ich kenne deine Werke. Siehe, ich habe eine geöffnete Tür vor dir gegeben, die niemand zu schließen vermag; denn du hast eine kleine Kraft, und hast mein Wort bewahrt und hast meinen Namen nicht verleugnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Siehe, ich gebe aus der Synagoge des Satans von denen, welche sagen, sie seien Juden, und sind es nicht, sondern lügen; siehe, ich werde sie zwingen, daß sie kommen und sich niederwerfen vor deinen Füßen und erkennen, daß ich dich geliebt habe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Weil du das Wort meines Ausharrens bewahrt hast, werde auch ich dich bewahren vor der Stunde der Versuchung, die über den ganzen Erdkreis kommen wird, um die zu versuchen, welche auf der Erde wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Ich komme bald; halte fest, was du hast, auf daß niemand deine Krone nehme!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Wer überwindet, den werde ich zu einer Säule machen in dem Tempel meines Gottes, und er wird nie mehr hinausgehen; und ich werde auf ihn schreiben den Namen meines Gottes und den Namen der Stadt meines Gottes, des neuen Jerusalem, das aus dem Himmel herniederkommt von meinem Gott, und meinen neuen Namen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Wer ein Ohr hat, höre, was der Geist den Versammlungen sagt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Und dem Engel der Versammlung in Laodicäa schreibe: Dieses sagt der Amen, der treue und wahrhaftige Zeuge, der Anfang der Schöpfung Gottes:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Ich kenne deine Werke, daß du weder kalt noch warm bist. Ach, daß du kalt oder warm wärest!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Also, weil du lau bist und weder kalt noch warm, so werde ich dich ausspeien aus meinem Munde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Weil du sagst: Ich bin reich und bin reich geworden und bedarf nichts, und weißt nicht, daß du der Elende und der Jämmerliche und arm und blind und bloß bist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Ich rate dir, Gold von mir zu kaufen, geläutert im Feuer, auf daß du reich werdest; und weiße Kleider, auf daß du bekleidet werdest, und die Schande deiner Blöße nicht offenbar werde; und Augensalbe, deine Augen zu salben, auf daß du sehen mögest.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Ich überführe und züchtige, so viele ich liebe. Sei nun eifrig und tue Buße!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Siehe, ich stehe an der Tür und klopfe an; wenn jemand meine Stimme hört und die Tür auftut, zu dem werde ich eingehen und das Abendbrot mit ihm essen, und er mit mir.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Wer überwindet, dem werde ich geben, mit mir auf meinem Throne zu sitzen, wie auch ich überwunden und mich mit meinem Vater gesetzt habe auf seinen Thron.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Wer ein Ohr hat, höre, was der Geist den Versammlungen sagt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Nach diesem sah ich: und siehe, eine Tür war aufgetan in dem Himmel, und die erste Stimme, die ich gehört hatte wie die einer Posaune mit mir reden, sprach: Komm hier herauf, und ich werde dir zeigen, was nach diesem geschehen muß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Alsbald war ich im Geiste; und siehe, ein Thron stand in dem Himmel, und auf dem Throne saß einer.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Und der da saß, war von Ansehen gleich einem Jaspisstein und einem Sardis, und ein Regenbogen war rings um den Thron, von Ansehen gleich einem Smaragd.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Und rings um den Thron waren vierundzwanzig Throne, und auf den Thronen saßen vierundzwanzig Älteste, bekleidet mit weißen Kleidern, und auf ihren Häuptern goldene Kronen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Und aus dem Throne gehen hervor Blitze und Stimmen und Donner; und sieben Feuerfackeln brannten vor dem Throne, welche die sieben Geister Gottes sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Und vor dem Throne wie ein gläsernes Meer, gleich Kristall; und inmitten des Thrones und um den Thron her vier lebendige Wesen, voller Augen vorn und hinten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Und das erste lebendige Wesen war gleich einem Löwen, und das zweite lebendige Wesen gleich einem Kalbe, und das dritte lebendige Wesen hatte das Angesicht eines Menschen, und das vierte lebendige Wesen war gleich einem fliegenden Adler.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Und die vier lebendigen Wesen hatten, ein jedes von ihnen für sich, je sechs Flügel; ringsum und inwendig sind sie voller Augen, und sie hören Tag und Nacht nicht auf zu sagen: Heilig, heilig, heilig, Herr, Gott, Allmächtiger, der da war und der da ist und der da kommt!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Und wenn die lebendigen Wesen Herrlichkeit und Ehre und Danksagung geben werden dem, der auf dem Throne sitzt, der da lebt von Ewigkeit zu Ewigkeit,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'so werden die vierundzwanzig Ältesten niederfallen vor dem, der auf dem Throne sitzt, und den anbeten, der da lebt von Ewigkeit zu Ewigkeit, und werden ihre Kronen niederwerfen vor dem Throne und sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Du bist würdig, o unser Herr und unser Gott, zu nehmen die Herrlichkeit und die Ehre und die Macht; denn du hast alle Dinge erschaffen, und deines Willens wegen waren sie und sind sie erschaffen worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Und ich sah in der Rechten dessen, der auf dem Throne saß, ein Buch, beschrieben inwendig und auswendig, mit sieben Siegeln versiegelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Und ich sah einen starken Engel, der mit lauter Stimme ausrief: Wer ist würdig, das Buch zu öffnen und seine Siegel zu brechen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Und niemand in dem Himmel, noch auf der Erde, noch unter der Erde vermochte das Buch zu öffnen, noch es anzublicken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Und ich weinte sehr, weil niemand würdig erfunden wurde, das Buch zu öffnen, noch es anzublicken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Und einer von den Ältesten spricht zu mir: Weine nicht! Siehe, es hat überwunden der Löwe, der aus dem Stamme Juda ist, die Wurzel Davids, das Buch zu öffnen und seine sieben Siegel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Und ich sah inmitten des Thrones und der vier lebendigen Wesen und inmitten der Ältesten ein Lamm stehen wie geschlachtet, das sieben Hörner hatte und sieben Augen, welche die sieben Geister Gottes sind, die gesandt sind über die ganze Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Und es kam und nahm das Buch aus der Rechten dessen, der auf dem Throne saß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Und als es das Buch nahm, fielen die vier lebendigen Wesen und die vierundzwanzig Ältesten nieder vor dem Lamme, und sie hatten ein jeder eine Harfe und goldene Schalen voll Räucherwerk, welches die Gebete der Heiligen sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Und sie singen ein neues Lied: Du bist würdig, das Buch zu nehmen und seine Siegel zu öffnen; denn du bist geschlachtet worden und hast für Gott erkauft, durch dein Blut, aus jedem Stamm und Sprache und Volk und Nation,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'und hast sie unserem Gott zu Königen und Priestern gemacht, und sie werden über die Erde herrschen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Und ich sah: und ich hörte eine Stimme vieler Engel um den Thron her und um die lebendigen Wesen und die Ältesten; und ihre Zahl war Zehntausende mal Zehntausende und Tausende mal Tausende,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'die mit lauter Stimme sprachen: Würdig ist das Lamm, das geschlachtet worden ist, zu empfangen die Macht und Reichtum und Weisheit und Stärke und Ehre und Herrlichkeit und Segnung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Und jedes Geschöpf, das in dem Himmel und auf der Erde und unter der Erde und auf dem Meere ist, und alles, was in ihnen ist, hörte ich sagen: Dem, der auf dem Throne sitzt und dem Lamme die Segnung und die Ehre und die Herrlichkeit und die Macht von Ewigkeit zu Ewigkeit!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Und die vier lebendigen Wesen sprachen: Amen! Und die Ältesten fielen nieder und beteten an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Und ich sah, als das Lamm eines von den sieben Siegeln öffnete: und ich hörte eines von den vier lebendigen Wesen wie eine Donnerstimme sagen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Komm! Und ich sah: und siehe, ein weißes Pferd, und der darauf saß hatte einen Bogen; und eine Krone wurde ihm gegeben, und er zog aus, siegend und auf daß er siegte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Und als es das zweite Siegel öffnete, hörte ich das zweite lebendige Wesen sagen: Komm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Und es zog aus ein anderes, feuerrotes Pferd; und dem, der darauf saß, ihm wurde gegeben, den Frieden von der Erde zu nehmen, und daß sie einander schlachteten; und ein großes Schwert wurde ihm gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Und als es das dritte Siegel öffnete, hörte ich das dritte lebendige Wesen sagen: Komm! Und ich sah: und siehe, ein schwarzes Pferd, und der darauf saß, hatte eine Waage in seiner Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Und ich hörte wie eine Stimme inmitten der vier lebendigen Wesen, welche sagte: Ein Chönix Weizen für einen Denar, und drei Chönix Gerste für einen Denar; und das Öl und den Wein beschädige nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Und als es das vierte Siegel öffnete, hörte ich die Stimme des vierten lebendigen Wesens sagen: Komm!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Und ich sah: und siehe, ein fahles Pferd, und der darauf saß, sein Name war Tod; und der Hades folgte ihm. Und ihm wurde Gewalt gegeben über den vierten Teil der Erde, zu töten mit dem Schwerte und mit Hunger und mit Tod und durch die wilden Tiere der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Und als es das fünfte Siegel öffnete, sah ich unter dem Altar die Seelen derer, welche geschlachtet worden waren um des Wortes Gottes und um des Zeugnisses willen, das sie hatten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Und sie riefen mit lauter Stimme und sprachen: Bis wann, o Herrscher, der du heilig und wahrhaftig bist, richtest und rächst du nicht unser Blut an denen, die auf der Erde wohnen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Und es wurde ihnen einem jeden ein weißes Gewand gegeben; und es wurde ihnen gesagt, daß sie noch eine kleine Zeit ruhen sollten, bis auch ihre Mitknechte und ihre Brüder vollendet sein würden, die ebenso wie sie getötet werden würden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Und ich sah, als es das sechste Siegel öffnete: und es geschah ein großes Erdbeben; und die Sonne wurde schwarz wie ein härener Sack, und der ganze Mond wurde wie Blut,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'und die Sterne des Himmels fielen auf die Erde, wie ein Feigenbaum, geschüttelt von einem starken Winde, seine unreifen Feigen abwirft.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Und der Himmel entwich wie ein Buch, das aufgerollt wird, und jeder Berg und jede Insel wurden aus ihren Stellen gerückt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Und die Könige der Erde und die Großen und die Obersten und die Reichen und die Starken und jeder Knecht und Freie verbargen sich in die Höhlen und in die Felsen der Berge;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'und sie sagen zu den Bergen und zu den Felsen: Fallet auf uns und verberget uns vor dem Angesicht dessen, der auf dem Throne sitzt, und vor dem Zorne des Lammes;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'denn gekommen ist der große Tag seines Zornes, und wer vermag zu bestehen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Und nach diesem sah ich vier Engel auf den vier Ecken der Erde stehen, welche die vier Winde der Erde festhielten, auf daß kein Wind wehe auf der Erde, noch auf dem Meere, noch über irgend einen Baum.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Und ich sah einen anderen Engel von Sonnenaufgang heraufsteigen, welcher das Siegel des lebendigen Gottes hatte; und er rief mit lauter Stimme den vier Engeln, welchen gegeben worden war, die Erde und das Meer zu beschädigen, und sagte:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Beschädiget nicht die Erde, noch das Meer, noch die Bäume, bis wir die Knechte unseres Gottes an ihren Stirnen versiegelt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Und ich hörte die Zahl der Versiegelten: hundertvierundvierzigtausend Versiegelte, aus jedem Stamme der Söhne Israels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Aus dem Stamme Juda zwölftausend Versiegelte, aus dem Stamme Ruben zwölftausend, aus dem Stamme Gad zwölftausend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'aus dem Stamme Aser zwölftausend, aus dem Stamme Nephthalim zwölftausend, aus dem Stamme Manasse zwölftausend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'aus dem Stamme Simeon zwölftausend, aus dem Stamme Levi zwölftausend, aus dem Stamme Issaschar zwölftausend,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'aus dem Stamme Zabulon zwölftausend, aus dem Stamme Joseph zwölftausend, aus dem Stamme Benjamin zwölftausend Versiegelte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Nach diesem sah ich: und siehe, eine große Volksmenge, welche niemand zählen konnte, aus jeder Nation und aus Stämmen und Völkern und Sprachen, und sie standen vor dem Throne und vor dem Lamme, bekleidet mit weißen Gewändern, und Palmen waren in ihren Händen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'Und sie rufen mit lauter Stimme und sagen: Das Heil unserem Gott, der auf dem Throne sitzt, und dem Lamme!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Und alle Engel standen um den Thron her und um die Ältesten und die vier lebendigen Wesen, und sie fielen vor dem Throne auf ihre Angesichter und beteten Gott an und sagten: Amen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'Die Segnung und die Herrlichkeit und die Weisheit und die Danksagung und die Ehre und die Macht und die Stärke unserem Gott von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Und einer von den Ältesten hob an und sprach zu mir: Diese, die mit weißen Gewändern bekleidet sind, wer sind sie, und woher sind sie gekommen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Und ich sprach zu ihm: Mein Herr, du weißt es. Und er sprach zu mir: Dies sind die, welche aus der großen Drangsal kommen, und sie haben ihre Gewänder gewaschen und haben sie weiß gemacht in dem Blute des Lammes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Darum sind sie vor dem Throne Gottes und dienen ihm Tag und Nacht in seinem Tempel; und der auf dem Throne sitzt, wird sein Zelt über ihnen errichten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Sie werden nicht mehr hungern, auch werden sie nicht mehr dürsten, noch wird je die Sonne auf sie fallen, noch irgend eine Glut;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'denn das Lamm, das in der Mitte des Thrones ist, wird sie weiden und sie leiten zu Quellen der Wasser des Lebens, und Gott wird jede Träne von ihren Augen abwischen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Und als es das siebte Siegel öffnete, entstand ein Schweigen in dem Himmel bei einer halben Stunde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Und ich sah die sieben Engel, welche vor Gott stehen; und es wurden ihnen sieben Posaunen gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Und ein anderer Engel kam und stellte sich an den Altar, und er hatte ein goldenes Räucherfaß; und es wurde ihm viel Räucherwerk gegeben, auf daß er Kraft gebe den Gebeten aller Heiligen auf dem goldenen Altar, der vor dem Throne ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Und der Rauch des Räucherwerks stieg mit den Gebeten der Heiligen auf aus der Hand des Engels vor Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Und der Engel nahm das Räucherfaß und füllte es von dem Feuer des Altars und warf es auf die Erde; und es geschahen Stimmen und Donner und Blitze und ein Erdbeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Und die sieben Engel, welche die sieben Posaunen hatten, bereiteten sich, auf daß sie posaunten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Und der erste posaunte: und es kam Hagel und Feuer, mit Blut vermischt, und wurde auf die Erde geworfen. Und der dritte Teil der Erde verbrannte, und der dritte Teil der Bäume verbrannte, und alles grüne Gras verbrannte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Und der zweite Engel posaunte: und wie ein großer, mit Feuer brennender Berg wurde ins Meer geworfen; und der dritte Teil des Meeres wurde zu Blut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'Und es starb der dritte Teil der Geschöpfe, welche im Meere waren, die Leben hatten, und der dritte Teil der Schiffe wurde zerstört.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Und der dritte Engel posaunte: und es fiel vom Himmel ein großer Stern, brennend wie eine Fackel, und er fiel auf den dritten Teil der Ströme und auf die Wasserquellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Und der Name des Sternes heißt Wermut; und der dritte Teil der Wasser wurde zu Wermut, und viele der Menschen starben von den Wassern, weil sie bitter gemacht waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Und der vierte Engel posaunte: und es wurde geschlagen der dritte Teil der Sonne und der dritte Teil des Mondes und der dritte Teil der Sterne, auf daß der dritte Teil derselben verfinstert würde, und der Tag nicht schiene seinen dritten Teil und die Nacht gleicherweise.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Und ich sah: und ich hörte einen Adler fliegen inmitten des Himmels und mit lauter Stimme sagen: Wehe, wehe, wehe denen, die auf der Erde wohnen, wegen der übrigen Stimmen der Posaune der drei Engel, die posaunen werden!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Und der fünfte Engel posaunte: und ich sah einen Stern, der vom Himmel auf die Erde gefallen war; und es wurde ihm der Schlüssel zum Schlunde des Abgrundes gegeben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Und er öffnete den Schlund des Abgrundes; und ein Rauch stieg auf aus dem Schlunde wie der Rauch eines großen Ofens, und die Sonne und die Luft wurden von dem Rauche des Schlundes verfinstert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Und aus dem Rauche kamen Heuschrecken hervor auf die Erde, und es wurde ihnen Gewalt gegeben, wie die Skorpionen der Erde Gewalt haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Und es wurde ihnen gesagt, daß sie nicht beschädigen sollten das Gras der Erde, noch irgend etwas Grünes, noch irgend einen Baum, sondern die Menschen, welche nicht das Siegel Gottes an ihren Stirnen haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Und es wurde ihnen gegeben, daß sie sie nicht töteten, sondern daß sie fünf Monate gequält würden; und ihre Qual war wie die Qual eines Skorpions, wenn er einen Menschen schlägt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Und in jenen Tagen werden die Menschen den Tod suchen und werden ihn nicht finden, und werden zu sterben begehren, und der Tod flieht vor ihnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Und die Gestalten der Heuschrecken waren gleich zum Kampfe gerüsteten Pferden, und auf ihren Köpfen wie Kronen gleich Gold, und ihre Angesichter wie Menschenangesichter;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'und sie hatten Haare wie Weiberhaare, und ihre Zähne waren wie die der Löwen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Und sie hatten Panzer wie eiserne Panzer, und das Geräusch ihrer Flügel war wie das Geräusch von Wagen mit vielen Pferden, die in den Kampf laufen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'und sie haben Schwänze gleich Skorpionen, und Stacheln, und ihre Gewalt ist in ihren Schwänzen, die Menschen fünf Monate zu beschädigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Sie haben über sich einen König, den Engel des Abgrundes; sein Name ist auf hebräisch Abaddon, und im Griechischen hat er den Namen Apollyon.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Das eine Wehe ist vorüber; siehe, es kommen noch zwei Wehe nach diesen Dingen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Und der sechste Engel posaunte: und ich hörte eine Stimme aus den vier Hörnern des goldenen Altars, der vor Gott ist, zu dem sechsten Engel,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'der die Posaune hatte, sagen: Löse die vier Engel, welche an dem großen Strome Euphrat gebunden sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Und die vier Engel wurden gelöst, welche bereitet waren auf Stunde und Tag und Monat und Jahr, auf daß sie den dritten Teil der Menschen töteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Und die Zahl der Kriegsheere zu Roß war zweimal zehntausend mal zehntausend; ich hörte ihre Zahl.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Und also sah ich die Rosse in dem Gesicht und die auf ihnen saßen: und sie hatten feurige und hyazinthene und schweflichte Panzer; und die Köpfe der Rosse waren wie Löwenköpfe, und aus ihren Mäulern geht Feuer und Rauch und Schwefel hervor.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Von diesen drei Plagen wurde der dritte Teil der Menschen getötet, von dem Feuer und dem Rauch und dem Schwefel, die aus ihren Mäulern hervorgehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Denn die Gewalt der Rosse ist in ihrem Maule und in ihren Schwänzen; denn ihre Schwänze sind gleich Schlangen und haben Köpfe, und mit ihnen beschädigen sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Und die übrigen der Menschen, welche durch diese Plagen nicht getötet wurden, taten nicht Buße von den Werken ihrer Hände, daß sie nicht anbeteten die Dämonen und die goldenen und die silbernen und die ehernen und die steinernen und die hölzernen Götzenbilder, die weder sehen noch hören noch wandeln können.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'Und sie taten nicht Buße von ihren Mordtaten, noch von ihren Zaubereien, noch von ihrer Hurerei, noch von ihren Diebstählen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Und ich sah einen anderen starken Engel aus dem Himmel herniederkommen, bekleidet mit einer Wolke, und der Regenbogen war auf seinem Haupte, und sein Angesicht war wie die Sonne, und seine Füße wie Feuersäulen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'und er hatte in seiner Hand ein geöffnetes Büchlein. Und er stellte seinen rechten Fuß auf das Meer, den linken aber auf die Erde;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'und er rief mit lauter Stimme, wie ein Löwe brüllt. Und als er rief, redeten die sieben Donner ihre Stimmen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Und als die sieben Donner redeten, wollte ich schreiben; und ich hörte eine Stimme aus dem Himmel sagen: Versiegle, was die sieben Donner geredet haben, und schreibe dieses nicht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Und der Engel, den ich auf dem Meere und auf der Erde stehen sah, erhob seine rechte Hand zum Himmel und schwur bei dem,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'der da lebt von Ewigkeit zu Ewigkeit, welcher den Himmel erschuf und was in ihm ist, und die Erde und was auf ihr ist, und das Meer und was in ihm ist, daß keine Frist mehr sein wird,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'sondern in den Tagen der Stimme des siebten Engels, wenn er posaunen wird, wird auch das Geheimnis Gottes vollendet sein, wie er seinen eigenen Knechten, den Propheten, die frohe Botschaft verkündigt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Und die Stimme, die ich aus dem Himmel hörte, redete wiederum mit mir und sprach: Gehe hin, nimm das geöffnete Büchlein in der Hand des Engels, der auf dem Meere und auf der Erde steht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Und ich ging zu dem Engel und sagte ihm, er möge mir das Büchlein geben. Und er spricht zu mir: Nimm es und iß es auf; und es wird deinen Bauch bitter machen, aber in deinem Munde wird es süß sein wie Honig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Und ich nahm das Büchlein aus der Hand des Engels und aß es auf; und es war in meinem Munde süß, wie Honig, und als ich es gegessen hatte, wurde mein Bauch bitter gemacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Und es wurde mir gesagt: Du mußt wiederum weissagen über Völker und Nationen und Sprachen und viele Könige.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Und es wurde mir ein Rohr, gleich einem Stabe, gegeben und gesagt: Stehe auf und miß den Tempel Gottes und den Altar und die darin anbeten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Und den Hof, der außerhalb des Tempels ist, wirf hinaus und miß ihn nicht; denn er ist den Nationen gegeben worden, und sie werden die heilige Stadt zertreten zweiundvierzig Monate.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Und ich werde meinen zwei Zeugen Kraft geben, und sie werden tausendzweihundertsechzig Tage weissagen, mit Sacktuch bekleidet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Diese sind die zwei Ölbäume und die zwei Leuchter, die vor dem Herrn der Erde stehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Und wenn jemand sie beschädigen will, so geht Feuer aus ihrem Munde und verzehrt ihre Feinde; und wenn jemand sie beschädigen will, so muß er also getötet werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Diese haben die Gewalt, den Himmel zu verschließen, auf daß während der Tage ihrer Weissagung kein Regen falle; und sie haben Gewalt über die Wasser, sie in Blut zu verwandeln, und die Erde zu schlagen mit jeder Plage, so oft sie nur wollen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Und wenn sie ihr Zeugnis vollendet haben werden, so wird das Tier, das aus dem Abgrund heraufsteigt, Krieg mit ihnen führen, und wird sie überwinden und sie töten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Und ihr Leichnam wird auf der Straße der großen Stadt liegen, welche geistlicherweise Sodom und Ägypten heißt, wo auch ihr Herr gekreuzigt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Und viele aus den Völkern und Stämmen und Sprachen und Nationen sehen ihren Leichnam drei Tage und einen halben, und erlauben nicht, ihre Leichname ins Grab zu legen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Und die auf der Erde wohnen, freuen sich über sie und frohlocken und werden einander Geschenke senden, weil diese, die zwei Propheten, die quälten, welche auf der Erde wohnen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Und nach den drei Tagen und einem halben kam der Geist des Lebens aus Gott in sie, und sie standen auf ihren Füßen; und große Furcht fiel auf die, welche sie schauten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Und ich hörte eine laute Stimme aus dem Himmel zu ihnen sagen: Steiget hier herauf! Und sie stiegen in den Himmel hinauf in der Wolke, und es schauten sie ihre Feinde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Und in jener Stunde geschah ein großes Erdbeben, und der zehnte Teil der Stadt fiel, und siebentausend Menschennamen kamen in dem Erdbeben um; und die übrigen wurden voll Furcht und gaben dem Gott des Himmels Ehre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Das zweite Wehe ist vorüber; siehe, das dritte Wehe kommt bald.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Und der siebte Engel posaunte: und es geschahen laute Stimmen in dem Himmel, welche sprachen: Das Reich der Welt unseres Herrn und seines Christus ist gekommen, und er wird herrschen von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Und die vierundzwanzig Ältesten, die vor Gott auf ihren Thronen sitzen, fielen auf ihre Angesichter und beteten Gott an und sprachen:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Wir danken dir, Herr, Gott, Allmächtiger, der da ist und der da war, daß du angenommen hast deine große Macht und angetreten deine Herrschaft!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Und die Nationen sind zornig gewesen, und dein Zorn ist gekommen und die Zeit der Toten, um gerichtet zu werden, und den Lohn zu geben deinen Knechten, den Propheten, und den Heiligen und denen, die deinen Namen fürchten, den Kleinen und den Großen, und die zu verderben, welche die Erde verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Und der Tempel Gottes im Himmel wurde geöffnet, und die Lade seines Bundes wurde in seinem Tempel gesehen; und es geschahen Blitze und Stimmen und Donner und ein Erdbeben und ein großer Hagel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Und ein großes Zeichen erschien in dem Himmel: Ein Weib bekleidet mit der Sonne, und der Mond war unter ihren Füßen, und auf ihrem Haupte eine Krone von zwölf Sternen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Und sie ist schwanger und schreit in Geburtswehen und in Schmerzen zu gebären.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Und es erschien ein anderes Zeichen in dem Himmel: und siehe, ein großer, feuerroter Drache, welcher sieben Köpfe und zehn Hörner hatte, und auf seinen Köpfen sieben Diademe;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'und sein Schwanz zieht den dritten Teil der Sterne des Himmels mit sich fort; und er warf sie auf die Erde. Und der Drache stand vor dem Weibe, das im Begriff war zu gebären, auf daß er, wenn sie geboren hätte, ihr Kind verschlänge.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Und sie gebar einen männlichen Sohn, der alle Nationen weiden soll mit eiserner Rute; und ihr Kind wurde entrückt zu Gott und zu seinem Throne.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Und das Weib floh in die Wüste, woselbst sie eine von Gott bereitete Stätte hat, auf daß man sie daselbst ernähre tausendzweihundertsechzig Tage.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Und es entstand ein Kampf in dem Himmel: Michael und seine Engel kämpften mit dem Drachen. Und der Drache kämpfte und seine Engel;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'und sie siegten nicht ob, auch wurde ihre Stätte nicht mehr in dem Himmel gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Und es wurde geworfen der große Drache, die alte Schlange, welcher Teufel und Satan genannt wird, der den ganzen Erdkreis verführt, geworfen wurde er auf die Erde, und seine Engel wurden mit ihm hinabgeworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Und ich hörte eine laute Stimme in dem Himmel sagen: Nun ist das Heil und die Macht und das Reich unseres Gottes und die Gewalt seines Christus gekommen; denn hinabgeworfen ist der Verkläger unserer Brüder, der sie Tag und Nacht vor unserem Gott verklagte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Und sie haben ihn überwunden um des Blutes des Lammes und um des Wortes ihres Zeugnisses willen, und sie haben ihr Leben nicht geliebt bis zum Tode!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Darum seid fröhlich, ihr Himmel und die ihr in ihnen wohnet! Wehe der Erde und dem Meere! Denn der Teufel ist zu euch hinabgekommen und hat große Wut, da er weiß, daß er wenig Zeit hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Und als der Drache sah, daß er auf die Erde geworfen war, verfolgte er das Weib, welches das männliche Kind geboren hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Und es wurden dem Weibe die zwei Flügel des großen Adlers gegeben, auf daß sie in die Wüste fliege, an ihre Stätte, woselbst sie ernährt wird eine Zeit und Zeiten und eine halbe Zeit, fern von dem Angesicht der Schlange.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Und die Schlange warf aus ihrem Munde Wasser, wie einen Strom, hinter dem Weibe her, auf daß sie sie mit dem Strome fortrisse.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Und die Erde half dem Weibe, und die Erde tat ihren Mund auf und verschlang den Strom, den der Drache aus seinem Munde warf.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Und der Drache ward zornig über das Weib und ging hin, Krieg zu führen mit den übrigen ihres Samens, welche die Gebote Gottes halten und das Zeugnis Jesu haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 18, '');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, '(G12:18) Und ich stand auf dem Sande des Meeres. (G13:1) Und ich sah aus dem Meere ein Tier aufsteigen, welches zehn Hörner und sieben Köpfe hatte, und auf seinen Hörnern zehn Diademe, und auf seinen Köpfen Namen der Lästerung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Und das Tier, das ich sah, war gleich einem Pardel, und seine Füße wie die eines Bären, und sein Maul wie eines Löwen Maul. Und der Drache gab ihm seine Macht und seinen Thron und große Gewalt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Und ich sah einen seiner Köpfe wie zum Tode geschlachtet. Und seine Todeswunde wurde geheilt, und die ganze Erde verwunderte sich über das Tier.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'Und sie beteten den Drachen an, weil er dem Tiere die Gewalt gab, und sie beteten das Tier an und sagten: Wer ist dem Tiere gleich? Und wer vermag mit ihm zu kämpfen?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Und es wurde ihm ein Mund gegeben, der große Dinge und Lästerungen redete; und es wurde ihm Gewalt gegeben, zweiundvierzig Monate zu wirken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Und es öffnete seinen Mund zu Lästerungen wider Gott, seinen Namen zu lästern und seine Hütte und die, welche ihre Hütte in dem Himmel haben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Und es wurde ihm gegeben, mit den Heiligen Krieg zu führen und sie zu überwinden; und es wurde ihm Gewalt gegeben über jeden Stamm und Volk und Sprache und Nation.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Und alle, die auf der Erde wohnen, werden es anbeten, ein jeder, dessen Name nicht geschrieben ist in dem Buche des Lebens des geschlachteten Lammes von Grundlegung der Welt an.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Wenn jemand ein Ohr hat, so höre er!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Wenn jemand in Gefangenschaft führt, so geht er in Gefangenschaft; wenn jemand mit dem Schwerte töten wird, so muß er mit dem Schwerte getötet werden. Hier ist das Ausharren und der Glaube der Heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Und ich sah ein anderes Tier aus der Erde aufsteigen: und es hatte zwei Hörner gleich einem Lamme, und es redete wie ein Drache.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Und die ganze Gewalt des ersten Tieres übt es vor ihm aus, und es macht, daß die Erde und die auf ihr wohnen das erste Tier anbeten, dessen Todeswunde geheilt wurde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Und es tut große Zeichen, daß es selbst Feuer vom Himmel auf die Erde herabkommen läßt vor den Menschen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'und es verführt, die auf der Erde wohnen wegen der Zeichen, welche vor dem Tiere zu tun ihm gegeben wurde, indem es die, welche auf der Erde wohnen, auffordert, ein Bild dem Tiere zu machen, das die Wunde des Schwertes hat und lebte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Und es wurde ihm gegeben, dem Bilde des Tieres Odem zu geben, auf daß das Bild des Tieres auch redete und bewirkte, daß alle getötet wurden, die das Bild des Tieres nicht anbeteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Und es bringt alle dahin, die Kleinen und die Großen, und die Reichen und die Armen, und die Freien und die Knechte, daß sie ein Malzeichen annehmen an ihre rechte Hand oder an ihre Stirn;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'und daß niemand kaufen oder verkaufen kann, als nur der, welcher das Malzeichen hat, den Namen des Tieres oder die Zahl seines Namens. Hier ist die Weisheit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Wer Verständnis hat, berechne die Zahl des Tieres, denn es ist eines Menschen Zahl; und seine Zahl ist sechshundertsechsundsechzig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Und ich sah: und siehe, das Lamm stand auf dem Berge Zion und mit ihm hundertvierundvierzigtausend, welche seinen Namen und den Namen seines Vaters an ihren Stirnen geschrieben trugen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Und ich hörte eine Stimme aus dem Himmel wie das Rauschen vieler Wasser und wie das Rollen eines lauten Donners; und die Stimme, welche ich hörte, war wie von Harfensängern, die auf ihren Harfen spielen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'Und sie singen ein neues Lied vor dem Throne und vor den vier lebendigen Wesen und den Ältesten; und niemand konnte das Lied lernen, als nur die hundertvierundvierzigtausend, die von der Erde erkauft waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Diese sind es, die sich mit Weibern nicht befleckt haben, denn sie sind Jungfrauen; diese sind es, die dem Lamme folgen, wohin irgend es geht. Diese sind aus den Menschen erkauft worden als Erstlinge Gott und dem Lamme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'Und in ihrem Munde wurde kein Falsch gefunden; denn sie sind tadellos.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Und ich sah einen anderen Engel inmitten des Himmels fliegen, der das ewige Evangelium hatte, um es denen zu verkündigen, die auf der Erde ansässig sind, und jeder Nation und Stamm und Sprache und Volk,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'indem er mit lauter Stimme sprach: Fürchtet Gott und gebet ihm Ehre, denn die Stunde seines Gerichts ist gekommen; und betet den an, der den Himmel und die Erde gemacht hat und das Meer und die Wasserquellen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Und ein anderer, zweiter Engel folgte und sprach: Gefallen, gefallen ist Babylon, die große, die mit dem Weine der Wut ihrer Hurerei alle Nationen getränkt hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Und ein anderer, dritter Engel folgte ihnen und sprach mit lauter Stimme: Wenn jemand das Tier und sein Bild anbetet und ein Malzeichen annimmt an seine Stirn oder an seine Hand,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'so wird auch er trinken von dem Weine des Grimmes Gottes, der unvermischt in dem Kelche seines Zornes bereitet ist; und er wird mit Feuer und Schwefel gequält werden vor den heiligen Engeln und vor dem Lamme.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Und der Rauch ihrer Qual steigt auf von Ewigkeit zu Ewigkeit; und sie haben keine Ruhe Tag und Nacht, die das Tier und sein Bild anbeten, und wenn jemand das Malzeichen seines Namens annimmt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Hier ist das Ausharren der Heiligen, welche die Gebote Gottes halten und den Glauben Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Und ich hörte eine Stimme aus dem Himmel sagen: Schreibe: Glückselig die Toten, die im Herrn sterben, von nun an! Ja, spricht der Geist, auf daß sie ruhen von ihren Arbeiten, denn ihre Werke folgen ihnen nach.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Und ich sah: und siehe, eine weiße Wolke, und auf der Wolke saß einer gleich dem Sohne des Menschen, welcher auf seinem Haupte eine goldene Krone und in seiner Hand eine scharfe Sichel hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Und ein anderer Engel kam aus dem Tempel hervor und rief dem, der auf der Wolke saß, mit lauter Stimme zu: Schicke deine Sichel und ernte; denn die Stunde des Erntens ist gekommen, denn die Ernte der Erde ist überreif geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Und der auf der Wolke saß, legte seine Sichel an die Erde, und die Erde wurde geerntet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Und ein anderer Engel kam aus dem Tempel hervor, der in dem Himmel ist, und auch er hatte eine scharfe Sichel.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Und ein anderer Engel, der Gewalt über das Feuer hatte, kam aus dem Altar hervor, und er rief dem, der die scharfe Sichel hatte, mit lautem Schrei zu und sprach: Schicke deine scharfe Sichel und lies die Trauben des Weinstocks der Erde, denn seine Beeren sind reif geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Und der Engel legte seine Sichel an die Erde und las die Trauben des Weinstocks der Erde und warf sie in die große Kelter des Grimmes Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Und die Kelter wurde außerhalb der Stadt getreten, und Blut ging aus der Kelter hervor bis an die Gebisse der Pferde, tausendsechshundert Stadien weit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Und ich sah ein anderes Zeichen in dem Himmel, groß und wunderbar: Sieben Engel, welche sieben Plagen hatten, die letzten; denn in ihnen ist der Grimm Gottes vollendet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Und ich sah wie ein gläsernes Meer, mit Feuer gemischt, und die Überwinder über das Tier und über sein Bild und über die Zahl seines Namens an dem gläsernen Meere stehen, und sie hatten Harfen Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Und sie singen das Lied Moses\', des Knechtes Gottes, und das Lied des Lammes und sagen: Groß und wunderbar sind deine Werke, Herr, Gott, Allmächtiger! Gerecht und wahrhaftig deine Wege, o König der Nationen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Wer sollte nicht dich, Herr, fürchten und deinen Namen verherrlichen? Denn du allein bist heilig; denn alle Nationen werden kommen und vor dir anbeten, denn deine gerechten Taten sind offenbar geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Und nach diesem sah ich: und der Tempel der Hütte des Zeugnisses in dem Himmel wurde geöffnet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'Und die sieben Engel, welche die sieben Plagen hatten, kamen aus dem Tempel hervor, angetan mit reinem, glänzenden Linnen, und um die Brust gegürtet mit goldenen Gürteln.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Und eines der vier lebendigen Wesen gab den sieben Engeln sieben goldene Schalen, voll des Grimmes Gottes, der da lebt von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Und der Tempel wurde mit Rauch gefüllt von der Herrlichkeit Gottes und von seiner Macht; und niemand konnte in den Tempel eintreten, bis die sieben Plagen der sieben Engel vollendet waren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Und ich hörte eine laute Stimme aus dem Tempel zu den sieben Engeln sagen: Gehet hin und gießet die sieben Schalen des Grimmes Gottes aus auf die Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Und der erste ging hin und goß seine Schale aus auf die Erde; und es kam ein böses und schlimmes Geschwür an die Menschen, welche das Malzeichen des Tieres hatten und die sein Bild anbeteten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Und der zweite goß seine Schale aus auf das Meer; und es wurde zu Blut, wie von einem Toten, und jede lebendige Seele starb, alles was in dem Meere war.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Und der dritte goß seine Schale aus auf die Ströme und auf die Wasserquellen, und sie wurden zu Blut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Und ich hörte den Engel der Wasser sagen: Du bist gerecht, der da ist und der da war, der Heilige, daß du also gerichtet hast.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Denn Blut von Heiligen und Propheten haben sie vergossen, und Blut hast du ihnen zu trinken gegeben; sie sind es wert.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Und ich hörte den Altar sagen: Ja, Herr, Gott, Allmächtiger, wahrhaftig und gerecht sind deine Gerichte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Und der vierte goß seine Schale aus auf die Sonne; und es wurde ihr gegeben, die Menschen mit Feuer zu versengen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Und die Menschen wurden von großer Hitze versengt und lästerten den Namen Gottes, der über diese Plagen Gewalt hat, und taten nicht Buße, ihm Ehre zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Und der fünfte goß seine Schale aus auf den Thron des Tieres; und sein Reich wurde verfinstert; und sie zerbissen ihre Zungen vor Pein');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'und lästerten den Gott des Himmels wegen ihrer Pein und wegen ihrer Geschwüre, und taten nicht Buße von ihren Werken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Und der sechste goß seine Schale aus auf den großen Strom Euphrat; und sein Wasser vertrocknete, auf daß der Weg der Könige bereitet würde, die von Sonnenaufgang herkommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Und ich sah aus dem Munde des Drachen und aus dem Munde des Tieres und aus dem Munde des falschen Propheten drei unreine Geister kommen, wie Frösche;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'denn es sind Geister von Dämonen, die Zeichen tun, welche zu den Königen des ganzen Erdkreises ausgehen, sie zu versammeln zu dem Kriege jenes großen Tages Gottes, des Allmächtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '(Siehe, ich komme wie ein Dieb. Glückselig, der da wacht und seine Kleider bewahrt, auf daß er nicht nackt wandle und man seine Schande sehe!)');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Und er versammelte sie an den Ort, der auf hebräisch Armagedon heißt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Und der siebte goß seine Schale aus in die Luft; und es ging eine laute Stimme aus von dem Tempel des Himmels, von dem Throne, welche sprach:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Es ist geschehen. Und es geschahen Blitze und Stimmen und Donner; und ein großes Erdbeben geschah, desgleichen nicht geschehen ist, seitdem die Menschen auf der Erde waren, solch ein Erdbeben, so groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Und die große Stadt wurde in drei Teile geteilt, und die Städte der Nationen fielen, und die große Babylon kam ins Gedächtnis vor Gott, ihr den Kelch des Weines des Grimmes seines Zornes zu geben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Und jede Insel entfloh, und Berge wurden nicht gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Und große Hagelsteine, wie ein Talent schwer, fallen aus dem Himmel auf die Menschen hernieder; und die Menschen lästerten Gott wegen der Plage des Hagels, denn seine Plage ist sehr groß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Und es kam einer von den sieben Engeln, welche die sieben Schalen hatten, und redete mit mir und sprach: Komm her, ich will dir das Urteil über die große Hure zeigen, die auf den vielen Wassern sitzt,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'mit welcher die Könige der Erde Hurerei getrieben haben; und die auf der Erde wohnen, sind trunken geworden von dem Weine ihrer Hurerei.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Und er führte mich im Geiste hinweg in eine Wüste; und ich sah ein Weib auf einem scharlachroten Tiere sitzen, voll Namen der Lästerung, das sieben Köpfe und zehn Hörner hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Und das Weib war bekleidet mit Purpur und Scharlach und übergoldet mit Gold und Edelgestein und Perlen, und sie hatte einen goldenen Becher in ihrer Hand, voll Greuel und Unreinigkeit ihrer Hurerei;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'und an ihrer Stirn einen Namen geschrieben: Geheimnis, Babylon, die große, die Mutter der Huren und der Greuel der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Und ich sah das Weib trunken von dem Blute der Heiligen und von dem Blute der Zeugen Jesu. Und ich verwunderte mich, als ich sie sah, mit großer Verwunderung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Und der Engel sprach zu mir: Warum verwundertest du dich? Ich will dir das Geheimnis des Weibes sagen und des Tieres, das sie trägt, welches die sieben Köpfe und die zehn Hörner hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Das Tier, welches du sahest, war und ist nicht und wird aus dem Abgrund heraufsteigen und ins Verderben gehen; und die auf der Erde wohnen, deren Namen nicht in dem Buche des Lebens geschrieben sind von Grundlegung der Welt an, werden sich verwundern, wenn sie das Tier sehen, daß es war und nicht ist und da sein wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Hier ist der Verstand, der Weisheit hat: Die sieben Köpfe sind sieben Berge, auf welchen das Weib sitzt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Und es sind sieben Könige: fünf von ihnen sind gefallen, der eine ist, der andere ist noch nicht gekommen; und wenn er kommt, muß er eine kleine Weile bleiben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Und das Tier, welches war und nicht ist, er ist auch ein achter und ist von den sieben und geht ins Verderben.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Und die zehn Hörner, die du sahst, sind zehn Könige, welche noch kein Königreich empfangen haben, aber Gewalt wie Könige empfangen eine Stunde mit dem Tiere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Diese haben einen Sinn und geben ihre Macht und Gewalt dem Tiere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Diese werden mit dem Lamme Krieg führen, und das Lamm wird sie überwinden; denn er ist Herr der Herren und König der Könige, und die mit ihm sind Berufene und Auserwählte und Treue.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Und er spricht zu mir: Die Wasser, die du sahst, wo die Hure sitzt, sind Völker und Völkerscharen und Nationen und Sprachen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'und die zehn Hörner, die du sahst, und das Tier, diese werden die Hure hassen und werden sie öde und nackt machen, und werden ihr Fleisch fressen und sie mit Feuer verbrennen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Denn Gott hat in ihre Herzen gegeben, seinen Sinn zu tun und in einem Sinne zu handeln und ihr Königreich dem Tiere zu geben, bis die Worte Gottes vollbracht sein werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Und das Weib, das du sahst, ist die große Stadt, welche das Königtum hat über die Könige der Erde.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Nach diesem sah ich einen anderen Engel aus dem Himmel herniederkommen, welcher große Gewalt hatte; und die Erde wurde von seiner Herrlichkeit erleuchtet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Und er rief mit starker Stimme und sprach: Gefallen, gefallen ist Babylon, die große, und ist eine Behausung von Dämonen geworden und ein Gewahrsam jedes unreinen Geistes und ein Gewahrsam jedes unreinen und gehaßten Vogels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Denn von dem Weine der Wut ihrer Hurerei haben alle Nationen getrunken, und die Könige der Erde haben Hurerei mit ihr getrieben, und die Kaufleute der Erde sind durch die Macht ihrer Üppigkeit reich geworden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Und ich hörte eine andere Stimme aus dem Himmel sagen: Gehet aus ihr hinaus, mein Volk, auf daß ihr nicht ihrer Sünden mitteilhaftig werdet, und auf daß ihr nicht empfanget von ihren Plagen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'denn ihre Sünden sind aufgehäuft bis zum Himmel, und Gott hat ihrer Ungerechtigkeiten gedacht.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Vergeltet ihr, wie auch sie vergolten hat, und verdoppelt ihr doppelt nach ihren Werken; in dem Kelche, welchen sie gemischt hat, mischet ihr doppelt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Wieviel sie sich verherrlicht und Üppigkeit getrieben hat, so viel Qual und Trauer gebet ihr. Denn sie spricht in ihrem Herzen: Ich sitze als Königin, und Witwe bin ich nicht, und Traurigkeit werde ich nicht sehen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Darum werden ihre Plagen an einem Tage kommen: Tod und Traurigkeit und Hungersnot, und mit Feuer wird sie verbrannt werden; denn stark ist der Herr, Gott, der sie gerichtet hat.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Und es werden über sie weinen und wehklagen die Könige der Erde, welche Hurerei und Üppigkeit mit ihr getrieben haben, wenn sie den Rauch ihres Brandes sehen;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'und sie werden von ferne stehen aus Furcht vor ihrer Qual und sagen: Wehe, wehe! Die große Stadt, Babylon, die starke Stadt! Denn in einer Stunde ist dein Gericht gekommen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Und die Kaufleute der Erde weinen und trauern über sie, weil niemand mehr ihre Ware kauft:');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'Ware von Gold und Silber und Edelgestein und Perlen und feiner Leinwand und Purpur und Seide und Scharlach, und alles Thynenholz und jedes Gerät von Elfenbein und jedes Gerät von kostbarstem Holz und von Erz und Eisen und Marmor,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'und Zimmet und Amomum und Räucherwerk und Salbe und Weihrauch und Wein und Öl und Feinmehl und Weizen und Vieh und Schafe, und von Pferden und von Wagen und von Leibeigenen, und Menschenseelen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Und das Obst der Lust deiner Seele ist von dir gewichen, und alles Glänzende und Prächtige ist dir verloren, und du wirst es nie mehr finden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Die Kaufleute dieser Dinge, die an ihr reich geworden sind, werden aus Furcht vor ihrer Qual von ferne stehen, weinend und trauernd,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'und werden sagen: Wehe, wehe! Die große Stadt, die bekleidet war mit feiner Leinwand und Purpur und Scharlach und übergoldet mit Gold und Edelgestein und Perlen! Denn in einer Stunde ist der so große Reichtum verwüstet worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Und jeder Steuermann und jeder, der nach irgend einem Orte segelt, und Schiffsleute und so viele auf dem Meere beschäftigt sind, standen von ferne und riefen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'als sie den Rauch ihres Brandes sahen, und sprachen: Welche Stadt ist gleich der großen Stadt?');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Und sie warfen Staub auf ihre Häupter und riefen weinend und trauernd und sprachen: Wehe, wehe! Die große Stadt, in welcher alle, die Schiffe auf dem Meere hatten, reich wurden von ihrer Kostbarkeit! Denn in einer Stunde ist sie verwüstet worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Sei fröhlich über sie, du Himmel, und ihr Heiligen und ihr Apostel und ihr Propheten! Denn Gott hat euer Urteil an ihr vollzogen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Und ein starker Engel hob einen Stein auf wie einen großen Mühlstein und warf ihn ins Meer und sprach: Also wird Babylon, die große Stadt, mit Gewalt niedergeworfen und nie mehr gefunden werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Und die Stimme der Harfensänger und Musiker und Flötenspieler und Trompeter wird nie mehr in dir gehört werden, und nie mehr wird ein Künstler irgend welcher Kunst in dir gefunden werden, und das Geräusch des Mühlsteins wird nie mehr in dir gehört werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'und das Licht einer Lampe wird nie mehr in dir scheinen, und die Stimme des Bräutigams und der Braut wird nie mehr in dir gehört werden; denn deine Kaufleute waren die Großen der Erde; denn durch deine Zauberei sind alle Nationen verführt worden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Und in ihr wurde das Blut von Propheten und Heiligen gefunden und von allen denen, die auf der Erde geschlachtet worden sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Nach diesem hörte ich wie eine laute Stimme einer großen Volksmenge in dem Himmel, welche sprach: Halleluja! Das Heil und die Herrlichkeit und die Macht unseres Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Denn wahrhaftig und gerecht sind seine Gerichte; denn er hat die große Hure gerichtet, welche die Erde mit ihrer Hurerei verderbte, und hat das Blut seiner Knechte gerächt an ihrer Hand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Und zum anderen Male sprachen sie: Halleluja! Und ihr Rauch steigt auf von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Und die vierundzwanzig Ältesten und die vier lebendigen Wesen fielen nieder und beteten Gott an, der auf dem Throne sitzt, und sagten: Amen, Halleluja!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Und eine Stimme kam aus dem Throne hervor, welche sprach: Lobet unseren Gott, alle seine Knechte, und die ihr ihn fürchtet, die Kleinen und die Großen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Und ich hörte wie eine Stimme einer großen Volksmenge und wie ein Rauschen vieler Wasser und wie ein Rollen starker Donner, welche sprachen: Halleluja! Denn der Herr, unser Gott, der Allmächtige, hat die Herrschaft angetreten.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Laßt uns fröhlich sein und frohlocken und ihm Ehre geben; denn die Hochzeit des Lammes ist gekommen, und sein Weib hat sich bereitet.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Und es ward ihr gegeben, daß sie sich kleide in feine Leinwand, glänzend und rein; denn die feine Leinwand sind die Gerechtigkeiten der Heiligen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Und er spricht zu mir: Schreibe: Glückselig, die geladen sind zum Hochzeitsmahle des Lammes! Und er spricht zu mir: Dies sind die wahrhaftigen Worte Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Und ich fiel zu seinen Füßen nieder, ihn anzubeten. Und er spricht zu mir: Siehe zu, tue es nicht. Ich bin dein Mitknecht und der deiner Brüder, die das Zeugnis Jesu haben; bete Gott an. Denn der Geist der Weissagung ist das Zeugnis Jesu.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Und ich sah den Himmel geöffnet, und siehe, ein weißes Pferd, und der darauf saß, genannt Treu und Wahrhaftig, und er richtet und führt Krieg in Gerechtigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Seine Augen aber sind eine Feuerflamme, und auf seinem Haupte sind viele Diademe, und er trägt einen Namen geschrieben, den niemand kennt, als nur er selbst;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'und er ist bekleidet mit einem in Blut getauchten Gewande, und sein Name heißt: Das Wort Gottes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Und die Kriegsheere, die in dem Himmel sind, folgten ihm auf weißen Pferden, angetan mit weißer, reiner Leinwand.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'Und aus seinem Munde geht hervor ein scharfes, zweischneidiges Schwert, auf daß er damit die Nationen schlage; und er wird sie weiden mit eiserner Rute, und er tritt die Kelter des Weines des Grimmes des Zornes Gottes, des Allmächtigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Und er trägt auf seinem Gewande und auf seiner Hüfte einen Namen geschrieben: König der Könige und Herr der Herren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Und ich sah einen Engel in der Sonne stehen, und er rief mit lauter Stimme und sprach zu allen Vögeln, die inmitten des Himmels fliegen: Kommet her, versammelt euch zu dem großen Mahle Gottes!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Auf daß ihr Fleisch von Königen fresset und Fleisch von Obersten und Fleisch von Starken und Fleisch von Pferden und von denen, die darauf sitzen, und Fleisch von allen, sowohl von Freien als Sklaven, sowohl von Kleinen als Großen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Und ich sah das Tier und die Könige der Erde und ihre Heere versammelt Krieg zu führen mit dem, der auf dem Pferde saß und mit seinem Heere.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Und es wurde ergriffen das Tier und der falsche Prophet, der mit ihm war, der die Zeichen vor ihm tat, durch welche er die verführte, welche das Malzeichen des Tieres annahmen und die sein Bild anbeteten, lebendig wurden die zwei in den Feuersee geworfen, der mit Schwefel brennt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Und die übrigen wurden getötet mit dem Schwerte dessen, der auf dem Pferde saß, welches Schwert aus seinem Munde hervorging; und alle Vögel wurden von ihrem Fleische gesättigt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Und ich sah einen Engel aus dem Himmel herniederkommen, welcher den Schlüssel des Abgrundes und eine große Kette in seiner Hand hatte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Und er griff den Drachen, die alte Schlange, welche der Teufel und der Satan ist; und er band ihn tausend Jahre,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'und warf ihn in den Abgrund und schloß zu und versiegelte über ihm, auf daß er nicht mehr die Nationen verführe, bis die tausend Jahre vollendet wären. Nach diesem muß er eine kleine Zeit gelöst werden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Und ich sah Throne, und sie saßen darauf, und es wurde ihnen gegeben, Gericht zu halten; und die Seelen derer, welche um des Zeugnisses Jesu und um des Wortes Gottes willen enthauptet waren, und die, welche das Tier nicht angebetet hatten, noch sein Bild, und das Malzeichen nicht angenommen hatten an ihre Stirn und an ihre Hand, und sie lebten und herrschten mit dem Christus tausend Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Die übrigen der Toten wurden nicht lebendig, bis die tausend Jahre vollendet waren. Dies ist die erste Auferstehung.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Glückselig und heilig, wer teilhat an der ersten Auferstehung! Über diese hat der zweite Tod keine Gewalt, sondern sie werden Priester Gottes und des Christus sein und mit ihm herrschen tausend Jahre.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Und wenn die tausend Jahre vollendet sind, wird der Satan aus seinem Gefängnis losgelassen werden,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'und wird ausgehen, die Nationen zu verführen, die an den vier Ecken der Erde sind, den Gog und den Magog, sie zum Kriege zu versammeln, deren Zahl wie der Sand des Meeres ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Und sie zogen herauf auf die Breite der Erde und umzingelten das Heerlager der Heiligen und die geliebte Stadt; und Feuer kam von Gott hernieder aus dem Himmel und verschlang sie.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Und der Teufel, der sie verführte, wurde in den Feuer-und Schwefelsee geworfen, wo sowohl das Tier ist als auch der falsche Prophet; und sie werden Tag und Nacht gepeinigt werden von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Und ich sah einen großen weißen Thron und den, der darauf saß, vor dessen Angesicht die Erde entfloh und der Himmel, und keine Stätte wurde für sie gefunden.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Und ich sah die Toten, die Großen und die Kleinen, vor dem Throne stehen, und Bücher wurden aufgetan; und ein anderes Buch ward aufgetan, welches das des Lebens ist. Und die Toten wurden gerichtet nach dem, was in den Büchern geschrieben war, nach ihren Werken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'Und das Meer gab die Toten, die in ihm waren, und der Tod und der Hades gaben die Toten, die in ihnen waren, und sie wurden gerichtet, ein jeder nach seinen Werken.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Und der Tod und der Hades wurden in den Feuersee geworfen. Dies ist der zweite Tod, der Feuersee.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Und wenn jemand nicht geschrieben gefunden wurde in dem Buche des Lebens, so wurde er in den Feuersee geworfen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Und ich sah einen neuen Himmel und eine neue Erde; denn der erste Himmel und die erste Erde waren vergangen, und das Meer ist nicht mehr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Und ich sah die heilige Stadt, das neue Jerusalem, aus dem Himmel herniederkommen von Gott, bereitet wie eine für ihren Mann geschmückte Braut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Und ich hörte eine laute Stimme aus dem Himmel sagen: Siehe, die Hütte Gottes bei den Menschen! Und er wird bei ihnen wohnen, und sie werden sein Volk sein, und Gott selbst wird bei ihnen sein, ihr Gott.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Und er wird jede Träne von ihren Augen abwischen, und der Tod wird nicht mehr sein, noch Trauer, noch Geschrei, noch Schmerz wird mehr sein; denn das Erste ist vergangen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Und der auf dem Throne saß sprach: Siehe, ich mache alles neu. Und er spricht zu mir: Schreibe, denn diese Worte sind gewiß und wahrhaftig.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Und er sprach zu mir: Es ist geschehen. Ich bin das Alpha und das Omega, der Anfang und das Ende. Ich will dem Dürstenden aus der Quelle des Wassers des Lebens geben umsonst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Wer überwindet, wird dieses ererben, und ich werde ihm Gott sein, und er wird mir Sohn sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Den Feigen aber und Ungläubigen und mit Greueln Befleckten und Mördern und Hurern und Zauberern und Götzendienern und allen Lügnern, ihr Teil ist in dem See, der mit Feuer und Schwefel brennt, welches der zweite Tod ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Und es kam einer von den sieben Engeln, welche die sieben Schalen hatten, voll der sieben letzten Plagen, und redete mit mir und sprach: Komm her, ich will dir die Braut, das Weib des Lammes zeigen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Und er führte mich im Geiste hinweg auf einen großen und hohen Berg und zeigte mir die heilige Stadt, Jerusalem, herniederkommend aus dem Himmel von Gott;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'und sie hatte die Herrlichkeit Gottes. Ihr Lichtglanz war gleich einem sehr kostbaren Edelstein, wie ein kristallheller Jaspisstein;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'und sie hatte eine große und hohe Mauer und hatte zwölf Tore, und an den Toren zwölf Engel, und Namen darauf geschrieben, welche die der zwölf Stämme der Söhne Israels sind.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Nach Osten drei Tore, und nach Norden drei Tore, und nach Süden drei Tore, und nach Westen drei Tore.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Und die Mauer der Stadt hatte zwölf Grundlagen, und auf denselben zwölf Namen der zwölf Apostel des Lammes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Und der mit mir redete hatte ein Maß, ein goldenes Rohr, auf daß er die Stadt messe und ihre Tore und ihre Mauern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Und die Stadt liegt viereckig, und ihre Länge ist so groß wie die Breite. Und er maß die Stadt mit dem Rohre, zwölftausend Stadien; die Länge und die Breite und die Höhe derselben sind gleich.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Und er maß ihre Mauer, hundertvierundvierzig Ellen, eines Menschen Maß, das ist des Engels.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Und der Bau ihrer Mauer war Jaspis, und die Stadt reines Gold, gleich reinem Glase.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Die Grundlagen der Mauer der Stadt waren geschmückt mit jedem Edelstein: die erste Grundlage, Jaspis; die zweite Saphir; die dritte Chalcedon; die vierte, Smaragd; die fünfte, Sardonix;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'die sechste, Sardis; die siebte, Chrysolith; die achte, Beryll; die neunte, Topas; die zehnte, Chrysopras; die elfte, Hyazinth; die zwölfte, Amethyst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Und die zwölf Tore waren zwölf Perlen, je eines der Tore war aus einer Perle, und die Straße der Stadt reines Gold, wie durchsichtiges Glas.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Und ich sah keinen Tempel in ihr, denn der Herr, Gott, der Allmächtige, ist ihr Tempel, und das Lamm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Und die Stadt bedarf nicht der Sonne, noch des Mondes, auf daß sie ihr scheinen; denn die Herrlichkeit Gottes hat sie erleuchtet, und ihre Lampe ist das Lamm.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Und die Nationen werden durch ihr Licht wandeln, und die Könige der Erde bringen ihre Herrlichkeit zu ihr.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Und ihre Tore sollen bei Tage nicht geschlossen werden, denn Nacht wird daselbst nicht sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'Und man wird die Herrlichkeit und die Ehre der Nationen zu ihr bringen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'Und nicht wird in sie eingehen irgend etwas Gemeines und was Greuel und Lüge tut, sondern nur die geschrieben sind in dem Buche des Lebens des Lammes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Und er zeigte mir einen Strom von Wasser des Lebens, glänzend wie Kristall, der hervorging aus dem Throne Gottes und des Lammes.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'In der Mitte ihrer Straße und des Stromes, diesseits und jenseits, war der Baum des Lebens, der zwölf Früchte trägt und jeden Monat seine Frucht gibt; und die Blätter des Baumes sind zur Heilung der Nationen.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Und keinerlei Fluch wird mehr sein; und der Thron Gottes und des Lammes wird in ihr sein; und seine Knechte werden ihm dienen,');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'und sie werden sein Angesicht sehen; und sein Name wird an ihren Stirnen sein.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Und Nacht wird nicht mehr sein und kein Bedürfnis nach einer Lampe und dem Lichte der Sonne; denn der Herr, Gott, wird über ihnen leuchten, und sie werden herrschen von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Und er sprach zu mir: Diese Worte sind gewiß und wahrhaftig, und der Herr, der Gott der Geister der Propheten, hat seinen Engel gesandt, seinen Knechten zu zeigen, was bald geschehen muß.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Und siehe, ich komme bald. Glückselig, der da bewahrt die Worte der Weissagung dieses Buches!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Und ich, Johannes, bin der, welcher diese Dinge hörte und sah; und als ich hörte und sah, fiel ich nieder, um anzubeten vor den Füßen des Engels, der mir diese Dinge zeigte.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Und er spricht zu mir: Siehe zu, tue es nicht. Ich bin dein Mitknecht und der deiner Brüder, der Propheten, und derer, welche die Worte dieses Buches bewahren.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Bete Gott an. Und er spricht zu mir: Versiegle nicht die Worte der Weissagung dieses Buches; die Zeit ist nahe.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Wer unrecht tut, tue noch unrecht, und wer unrein ist, verunreinige sich noch, und wer gerecht ist, übe noch Gerechtigkeit, und wer heilig ist, sei noch geheiligt.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Siehe, ich komme bald, und mein Lohn mit mir, um einem jeden zu vergelten, wie sein Werk sein wird.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Ich bin das Alpha und das Omega, der Erste und der Letzte, der Anfang und das Ende.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Glückselig, die ihre Kleider waschen, auf daß sie ein Recht haben an dem Baume des Lebens und durch die Tore in die Stadt eingehen!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Draußen sind die Hunde und die Zauberer und die Hurer und die Mörder und die Götzendiener und jeder, der die Lüge liebt und tut.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Ich, Jesus, habe meinen Engel gesandt, euch diese Dinge zu bezeugen in den Versammlungen. Ich bin die Wurzel und das Geschlecht Davids, der glänzende Morgenstern.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Und der Geist und die Braut sagen: Komm! Und wer es hört, spreche: Komm! Und wen da dürstet, der komme; wer da will, nehme das Wasser des Lebens umsonst.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Ich bezeuge jedem, der die Worte der Weissagung dieses Buches hört: Wenn jemand zu diesen Dingen hinzufügt, so wird Gott ihm die Plagen hinzufügen, die in diesem Buche geschrieben sind;');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'und wenn jemand von den Worten des Buches dieser Weissagung wegnimmt, so wird Gott sein Teil wegnehmen von dem Baume des Lebens und aus der heiligen Stadt, wovon in diesem Buche geschrieben ist.');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Der diese Dinge bezeugt, spricht: Ja, ich komme bald. Amen; komm, Herr Jesus!');
INSERT INTO `GerElb1905_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Die Gnade des Herrn Jesus Christus sei mit allen Heiligen!');
